INSERT INTO hausa_vpl VALUES ("NH7_39","017_7_39","NEH","7","39","39","Ga zuriyar Firistoci. Zuriyar Yedahiya (ta wurin iyalin Yeshuwa) 973 ");
INSERT INTO hausa_vpl VALUES ("NH7_40","017_7_40","NEH","7","40","40","ta Immer 1,052 ");
