INSERT INTO hausa_vpl VALUES ("NH7_42","017_7_42","NEH","7","42","42","ta Harim 1,017. ");
INSERT INTO hausa_vpl VALUES ("NH7_43","017_7_43","NEH","7","43","43","Ga zuriyar Lawiyawa. Zuriyar Yeshuwa da Kadmiyel (ta wurin Hodeba) 74. ");
INSERT INTO hausa_vpl VALUES ("NH7_44","017_7_44","NEH","7","44","44","Mawaƙa. Zuriyar Asaf mutum 148. ");
INSERT INTO hausa_vpl VALUES ("NH7_45","017_7_45","NEH","7","45","45","Ga zuriyar Matsaran Ƙofofi. Zuriyar Shallum, Ater, Talmon, Akkub, Hatita da Shobai 138. ");
INSERT INTO hausa_vpl VALUES ("NH7_46","017_7_46","NEH","7","46","46","Ma’aikatan haikali. Zuriyar Ziha, Hasufa, Tabbawot, ");
INSERT INTO hausa_vpl VALUES ("NH7_47","017_7_47","NEH","7","47","47","da ta Keros, da ta Siya, da ta Fadon, ");
INSERT INTO hausa_vpl VALUES ("NH7_48","017_7_48","NEH","7","48","48","da ta Lebana, da ta Hagaba, da ta Shalmai, ");
INSERT INTO hausa_vpl VALUES ("NH7_49","017_7_49","NEH","7","49","49","da ta Hanan, da ta Giddel, da ta Gahar, ");
INSERT INTO hausa_vpl VALUES ("NH7_50","017_7_50","NEH","7","50","50","da ta Reyahiya, da ta Rezin, da ta Nekoda, ");
INSERT INTO hausa_vpl VALUES ("NH7_51","017_7_51","NEH","7","51","51","da ta Gazzam, da ta Uzza, da ta Faseya, ");
INSERT INTO hausa_vpl VALUES ("NH7_52","017_7_52","NEH","7","52","52","da ta Besai, da ta Meyunawa, da ta Nefussiyawa, ");
INSERT INTO hausa_vpl VALUES ("NH7_53","017_7_53","NEH","7","53","53","da ta Bakbuk, da ta Hakufa, da ta Harhur, ");
INSERT INTO hausa_vpl VALUES ("NH7_54","017_7_54","NEH","7","54","54","da ta Bazlit, da ta Mehida, da ta Harsha, ");
INSERT INTO hausa_vpl VALUES ("NH7_55","017_7_55","NEH","7","55","55","da ta Barkos, da ta Sisera, da ta Tema, ");
INSERT INTO hausa_vpl VALUES ("NH7_56","017_7_56","NEH","7","56","56","da ta Neziya, da kuma ta Hatifa. ");
INSERT INTO hausa_vpl VALUES ("NH7_57","017_7_57","NEH","7","57","57","Ga zuriyar bayin Solomon. Zuriyar Sotai, da ta Soferet, da ta Ferida, ");
INSERT INTO hausa_vpl VALUES ("NH7_58","017_7_58","NEH","7","58","58","da ta Ya’ala, da ta Darkon, da ta Giddel, ");
INSERT INTO hausa_vpl VALUES ("NH7_59","017_7_59","NEH","7","59","59","Shefatiya, Hattil, Fokeret-Hazzebayim, da Amon. ");
INSERT INTO hausa_vpl VALUES ("NH7_60","017_7_60","NEH","7","60","60","Zuriyar ma’aikatan haikali da ta bayin Solomon su 392. ");
INSERT INTO hausa_vpl VALUES ("NH7_61","017_7_61","NEH","7","61","61","Waɗansu sun hauro daga garuruwan Tel-Mela, Tel-Harsha, Kerub, Addon da Immer, amma ba su iya nuna cewa iyalansu su zuriyar Isra’ila ce ba, ");
INSERT INTO hausa_vpl VALUES ("NH7_62","017_7_62","NEH","7","62","62","zuriyar Delahiya, Tobiya, da Nekoda 642. ");
INSERT INTO hausa_vpl VALUES ("NH7_63","017_7_63","NEH","7","63","63","Na wajen firistoci kuwa su ne, Zuriyar Hobahiya, da ta Hakkoz, da ta Barzillai (wani mutumin da ya auri ’yar Barzillai mutumin Gileyad, aka kuma kira shi da wannan suna). ");
INSERT INTO hausa_vpl VALUES ("NH7_64","017_7_64","NEH","7","64","64","Waɗannan ne aka nemi sunayensu a cikin tarihin asalin iyalai, amma ba a same su a ciki ba, saboda haka aka hana su shiga cikin firistoci, sun zama kamar marasa tsarki. ");
INSERT INTO hausa_vpl VALUES ("NH7_65","017_7_65","NEH","7","65","65","Sai gwamna ya umarce su kada su ci wani abinci mafi tsarki, sai akwai firist da zai nemi nufin Ubangiji ta wurin Urim da Tummim. ");
INSERT INTO hausa_vpl VALUES ("NH7_66","017_7_66","NEH","7","66","66","Yawan jama’ar duka ya kai mutum 42,360, ");
INSERT INTO hausa_vpl VALUES ("NH7_67","017_7_67","NEH","7","67","67","ban da bayinsu maza da mata 7,337. Suna kuma da mawaƙa maza da mata 245. ");
INSERT INTO hausa_vpl VALUES ("NH7_68","017_7_68","NEH","7","68","68","Akwai dawakai 736, alfadarai 245 ");
INSERT INTO hausa_vpl VALUES ("NH7_69","017_7_69","NEH","7","69","69","raƙuma 435, da kuma jakuna 6,720. ");
INSERT INTO hausa_vpl VALUES ("NH7_70","017_7_70","NEH","7","70","70","Waɗansu shugabannin iyalai suka ba da kyautai domin taimakon aiki. Gwamna ya ba da darik 1,000 na zinariya, kwanoni 50, da riguna 530 don firistoci. ");
INSERT INTO hausa_vpl VALUES ("NH7_71","017_7_71","NEH","7","71","71","Waɗansu shugabannin iyalai sun ba da darik 20,000 na zinariya da mina 2,200 na azurfa don aiki. ");
INSERT INTO hausa_vpl VALUES ("NH7_72","017_7_72","NEH","7","72","72","Jimillar da sauran mutane suka bayar ta kai darik 20,000 na zinariya, minas 2,000 na azurfa, da riguna sittin da bakwai don firistoci. ");
INSERT INTO hausa_vpl VALUES ("NH7_73","017_7_73","NEH","7","73","73","Firistoci, da Lawiyawa, da matsaran ƙofofi, da mawaƙa, da ma’aikatan haikali tare da waɗansu mutane da kuma sauran mutanen Isra’ila, suka zauna a garuruwansu. Da wata na bakwai ya zo, Isra’ilawa kuwa sun riga sun zauna a garuruwansu, ");
INSERT INTO hausa_vpl VALUES ("NH8_1","017_8_1","NEH","8","1","1","sai dukan mutane suka taru kamar mutum guda a dandali a gaban Ƙofar Ruwa. Suka faɗa wa Ezra malamin Doka yă fitar da Littafin Dokar Musa, wanda Ubangiji ya umarta domin Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("NH8_2","017_8_2","NEH","8","2","2","Saboda haka a rana ta farko ga watan bakwai, Ezra firist, ya kawo Doka a gaban taro, wanda ya ƙunshi maza da mata da dukan waɗanda za su iya fahimta. ");
INSERT INTO hausa_vpl VALUES ("NH8_3","017_8_3","NEH","8","3","3","Ya karanta Dokar da ƙarfi daga safe har tsakar rana yayinda yake a kan dandali da yake fuskantar dandali a gaban Ƙofar Ruwa, gaban maza, mata da kuma sauran mutanen da za su iya fahimta. Dukan mutane kuwa suka saurara a hankali ga karatun Littafin Dokar. ");
INSERT INTO hausa_vpl VALUES ("NH8_4","017_8_4","NEH","8","4","4","Ezra malamin Doka ya tsaya a kan dakalin itacen da aka yi saboda wannan hidima. Kusa da shi a damansa, Mattitiya, Shema, Anahiya, Uriya, Hilkiya da Ma’asehiya suka tsaya; a hagunsa kuma Fedahiya, Mishayel, Malkiya, Hashum, Hashbaddana, Zakariya da Meshullam suka tsaya. ");
INSERT INTO hausa_vpl VALUES ("NH8_5","017_8_5","NEH","8","5","5","Sai Ezra ya buɗe littafin. Dukan mutane kuwa suka gan shi domin yana tsaye a bisa fiye da inda mutane suke tsaye; yayinda ya buɗe littafin kuwa, dukan mutane suka miƙe tsaye. ");
INSERT INTO hausa_vpl VALUES ("NH8_6","017_8_6","NEH","8","6","6","Ezra ya yabi Ubangiji, Allah mai girma; dukan mutane kuwa suka tā da hannuwansu suka amsa, “Amin! Amin!” Sa’an nan suka sunkuya suka yi wa Ubangiji sujada da fuskokinsu har ƙasa. ");
INSERT INTO hausa_vpl VALUES ("NH8_7","017_8_7","NEH","8","7","7","Lawiyawa, wato, su Yeshuwa, Bani, Sherebiya, Yamin, Akkub, Shabbetai, Hodiya, Ma’asehiya, Kelita, Azariya, Yozabad, Hanan da Felahiya, suka koyar da mutane a cikin Dokar yayinda mutane suke a tsaye a can. ");
INSERT INTO hausa_vpl VALUES ("NH8_8","017_8_8","NEH","8","8","8","Suka karanta daga Littafin Dokar Allah, suna sa kowa ya gane, suna kuma ba da fassarar domin mutane su fahimci abin da ake karatu. ");
INSERT INTO hausa_vpl VALUES ("NH8_9","017_8_9","NEH","8","9","9","Sa’an nan Nehemiya gwamna, Ezra firist da kuma wanda yake malamin Doka, da Lawiyawa waɗanda suke koyar da mutane, suka ce musu duka, “Wannan rana mai tsarki ce ga Ubangiji Allahnku. Kada ku yi makoki ko kuka.” Gama dukan mutane suna ta kuka yayinda suke sauraran kalmomin Dokar. ");
INSERT INTO hausa_vpl VALUES ("NH8_10","017_8_10","NEH","8","10","10","Nehemiya ya ce, “Ku koma gidajenku ku ci abinci mai kyau, ku sha abin sha mai zaƙi, ku kuma aika wa wanda ba shi da shi. Wannan rana mai tsarki ce ga Ubangijinmu. Kada ku yi baƙin ciki, gama farin cikin Ubangiji shi ne ƙarfinku.” ");
INSERT INTO hausa_vpl VALUES ("NH8_11","017_8_11","NEH","8","11","11","Lawiyawa suka rarrashi mutane duka suna cewa, “Ku natsu, gama wannan rana ce mai tsarki. Kada ku yi baƙin ciki.” ");
INSERT INTO hausa_vpl VALUES ("NH8_12","017_8_12","NEH","8","12","12","Sa’an nan dukan mutane suka koma gidajensu suka ci, suka sha, suka aika wa wanda ba shi da abinci, gama yanzu sun fahimci kalmomin da aka karanta musu. ");
INSERT INTO hausa_vpl VALUES ("NH8_13","017_8_13","NEH","8","13","13","A rana ta biyu ga wata, shugabannin iyalai, tare da firistoci da Lawiyawa, suka taru kewaye da Ezra malamin Doka don su mai da hankali ga kalmomin Dokar. ");
INSERT INTO hausa_vpl VALUES ("NH8_14","017_8_14","NEH","8","14","14","Suka tarar a rubuce a cikin Doka wadda Ubangiji ya umarta ta wurin Musa, cewa Isra’ilawa su zauna a bukkoki a lokaci bikin watan bakwai ");
INSERT INTO hausa_vpl VALUES ("NH8_15","017_8_15","NEH","8","15","15","kuma cewa ya kamata su yi shelar wannan magana, su kuma yaɗa ta a duk garuruwansu da kuma cikin Urushalima cewa, “Ku fita zuwa cikin ƙasar tudu ku kawo rassa daga itatuwan zaitun da na zaitun jeji, da kuma daga dargaza, da dabino da itatuwa masu ganye, don yin bukkoki”, kamar yadda yake a rubuce. ");
INSERT INTO hausa_vpl VALUES ("NH8_16","017_8_16","NEH","8","16","16","Sai mutanen suka fita suka dawo da rassa suka kuma yi wa kansu bukkoki a bisa rufin ɗakunansu, a cikin filaye, a shirayin gidan Allah, da ciki dandalin da yake kusa da Ƙofar Ruwa, da kuma a dandalin da yake a Ƙofar Efraim. ");
INSERT INTO hausa_vpl VALUES ("NH8_17","017_8_17","NEH","8","17","17","Dukan jama’ar da suka komo daga zaman bauta suka yi bukkoki suka kuma zauna a cikinsu. Daga kwanakin Yoshuwa ɗan Nun har yă zuwa yau, Isra’ilawa ba su taɓa yin bikinsa haka ba. Mutane suka cika da farin ciki sosai. ");
INSERT INTO hausa_vpl VALUES ("NH8_18","017_8_18","NEH","8","18","18","Kowace rana, daga rana farko zuwa ƙarshe, Ezra ya karanta daga Littafin Dokar Allah. Suka yi bikin kwana bakwai, a rana ta takwas kuma suka yi muhimmin taro bisa ga ƙa’ida. ");
INSERT INTO hausa_vpl VALUES ("NH9_1","017_9_1","NEH","9","1","1","A rana ta ashirin da huɗu ga watan nan, Isra’ilawa suka taru, suna yin azumi, suna sa rigunan makoki, suna kuma zuba toka a kansu. ");
INSERT INTO hausa_vpl VALUES ("NH9_2","017_9_2","NEH","9","2","2","Waɗanda suke zuriyar Isra’ilawa suka ware kansu daga dukan baƙi. Suka tsaya, suka kuma furta zunubansu da muguntar kakanninsu. ");
INSERT INTO hausa_vpl VALUES ("NH9_3","017_9_3","NEH","9","3","3","Sa’ad da suke nan a tsaye, aka ɗauki awa uku ana karanta Littafin Dokar Ubangiji Allahnsu. Aka kuma ɗauki awa uku ana sujada ga Ubangiji Allahnsu. ");
INSERT INTO hausa_vpl VALUES ("NH9_4","017_9_4","NEH","9","4","4","A kan dakalin kuwa akwai Lawiyawa, wato, Yeshuwa, Bani, Kadmiyel, Shebaniya, Bunni, Sherebiya, Bani da Kenani tsaye, waɗanda suka kira da babbar murya ga Ubangiji Allahnsu. ");
INSERT INTO hausa_vpl VALUES ("NH9_5","017_9_5","NEH","9","5","5","Lawiyawan nan, Yeshuwa, Kadmiyel, Bani, Hashabnehiya, Sherebiya, Hodiya, Shebaniya da Fetahahiya, suka ce, “Ku miƙe tsaye ku yabi Ubangiji Allahnku, wanda yake har abada abadin.” “Albarka ta tabbata ga sunanka mai ɗaukaka, bari kuma a ɗaukaka shi bisa dukan albarka da yabo. ");
INSERT INTO hausa_vpl VALUES ("NH9_6","017_9_6","NEH","9","6","6","Kai kaɗai ne Ubangiji. Kai ka yi sammai, har ma da sama sammai, da dukan rundunar taurari, da duniya da kuma dukan abin da yake cikinta, da tekuna da dukan abubuwan da suke cikinsu. Ka ba da rai ga kome, kuma rundunonin sama suna maka sujada. ");
INSERT INTO hausa_vpl VALUES ("NH9_7","017_9_7","NEH","9","7","7","“Kai ne Ubangiji Allah, wanda ya zaɓi Abram, ya fitar da shi daga Ur na Kaldiyawa, ya kuma ba shi suna Ibrahim. ");
INSERT INTO hausa_vpl VALUES ("NH9_8","017_9_8","NEH","9","8","8","Kai ka sami zuciyarsa da aminci a gare ka, ka kuma yi alkawari da shi cewa za ka ba zuriyarsa ƙasar Kan’aniyawa, da ta Hittiyawa, da ta Amoriyawa, da ta Ferizziyawa, da ta Yebusiyawa, da kuma ta Girgashiyawa. Ka kiyaye alkawarinka domin kai mai adalci ne. ");
INSERT INTO hausa_vpl VALUES ("NH9_9","017_9_9","NEH","9","9","9","“Ka ga wahalar kakanninmu a Masar; ka kuwa ji kukansu a Jan Teku. ");
INSERT INTO hausa_vpl VALUES ("NH9_10","017_9_10","NEH","9","10","10","Ka aika da alamu masu banmamaki da al’ajabai a kan Fir’auna, a kan dukan shugabanninsa da kuma a kan dukan mutanen ƙasarsa, gama ka ga irin danniyar da suka yi wa mutanenka. Ka samo wa kanka suna, wadda ta dawwama har yă zuwa yau. ");
INSERT INTO hausa_vpl VALUES ("NH9_11","017_9_11","NEH","9","11","11","Ka raba teku a gaban kakanninmu, saboda su wuce cikinsa a busasshiyar ƙasa, amma ka hallaka masu binsu cikin zurfafa, nutse kamar dutse a cikin ruwa. ");
INSERT INTO hausa_vpl VALUES ("NH9_12","017_9_12","NEH","9","12","12","Da rana ka bishe kakanninmu da girgije, da dare kuwa ka bishe su da ginshiƙin wuta don ka ba su haske a hanyar da za su bi. ");
INSERT INTO hausa_vpl VALUES ("NH9_13","017_9_13","NEH","9","13","13","“Ka sauko a kan Dutsen Sinai; ka yi musu magana daga sama. Ka ba su ƙa’idodi da dokokin da suke masu adalci da kuma daidai, ka ba su farillai da umarnai da suke da kyau. ");
INSERT INTO hausa_vpl VALUES ("NH9_14","017_9_14","NEH","9","14","14","Ka sanar da su Asabbacinka mai tsarki, ka kuma ba su umarnai, da farillai, da kuma dokoki ta wurin bawanka Musa. ");
INSERT INTO hausa_vpl VALUES ("NH9_15","017_9_15","NEH","9","15","15","Cikin yunwansu ka ba su burodi daga sama, cikin ƙishirwansu kuma ka fitar musu ruwa daga dutse. Ka faɗa musu su shiga su mallaki ƙasar da ka rantse ta wurin ɗaga hannu cewa za ka ba su. ");
INSERT INTO hausa_vpl VALUES ("NH9_16","017_9_16","NEH","9","16","16","“Amma su kakanninmu, suka yi fariya da taurinkai, ba su kuwa yi biyayya ga umarnanka ba. ");
INSERT INTO hausa_vpl VALUES ("NH9_17","017_9_17","NEH","9","17","17","Suka ƙi su saurare ka, suka kāsa tuna da mu’ujizan da ka aikata a cikinsu. Suka yi taurinkai, cikin tawayensu kuma suka naɗa shugaba don su koma bautarsu. Amma kai Allah ne mai gafartawa, mai alheri da jinƙai, mai jinkirin fushi, mai yalwar ƙauna. Saboda haka ba ka yashe su ba, ");
INSERT INTO hausa_vpl VALUES ("NH9_18","017_9_18","NEH","9","18","18","ko ma sa’ad da suka yi wa kansu siffar ɗan maraƙi, suka ce, ‘Wannan shi ne allahnku, wanda ya fitar da ku daga Masar,’ ko sa’ad da suka yi saɓo mai bantsoro. ");
INSERT INTO hausa_vpl VALUES ("NH9_19","017_9_19","NEH","9","19","19","“Saboda jinƙanka mai girma, ba ka yashe su a hamada ba. Da rana, ginshiƙin girgije bai daina bishe su a hanyarsu ba, da dare kuma ginshiƙin wuta bai daina haskakawa a hanyar da za su bi ba. ");
INSERT INTO hausa_vpl VALUES ("NH9_20","017_9_20","NEH","9","20","20","Ka ba da Ruhunka mai kyau don yă koyar da su. Ba ka janye Manna naka daga bakunansu ba, ka kuma ba su ruwa don ƙishirwansu. ");
INSERT INTO hausa_vpl VALUES ("NH9_21","017_9_21","NEH","9","21","21","Shekaru arba’in ka riƙe su a cikin hamada; ba su rasa kome ba, rigunansu ba su yage ba, ƙafafunsu kuwa ba su kumbura ba. ");
INSERT INTO hausa_vpl VALUES ("NH9_22","017_9_22","NEH","9","22","22","“Ka ba su mulkoki da al’ummai, kana ba su har ma da ƙasashen da suke jeji. Suka ci ƙasar Sihon na sarkin Heshbon da ƙasar Og inda sarkin Bashan yake mulki. ");
INSERT INTO hausa_vpl VALUES ("NH9_23","017_9_23","NEH","9","23","23","Ka sa ’ya’yansu maza suka yi yawa kamar taurarin sararin sama, ka kuma kawo su cikin ƙasar da ka faɗa wa kakanninsu su shiga su mallake. ");
INSERT INTO hausa_vpl VALUES ("NH9_24","017_9_24","NEH","9","24","24","’Ya’yansu maza suka shiga suka kuma mallaki ƙasar. A gabansu ka rinjayi Kan’aniyawan da suke zama a cikin ƙasar; ka ba da Kan’aniyawa a gare su, tare da sarakunansu da kuma mutanen ƙasar, su yi da su yadda suke so. ");
INSERT INTO hausa_vpl VALUES ("NH9_25","017_9_25","NEH","9","25","25","Suka kame birane masu katanga masu ƙarfi, da ƙasa masu ba da amfani; suka mallaki gidaje cike da kowane irin abu mai kyau, da rijiyoyin da aka riga aka haƙa, da gonakin inabi, da gonakin itatuwan zaitun da kuma itatuwan ba da ’ya’ya a yalwace a ciki. Suka ci suka ƙoshi, suka kuma yi ƙiba; suka ji daɗi cikin alherinka mai girma. ");
INSERT INTO hausa_vpl VALUES ("NH9_26","017_9_26","NEH","9","26","26","“Amma suka yi rashin biyayya suka kuma yi tawaye gare ka; suka sa dokarka a bayansu. Suka kashe annabawanka waɗanda suka gargaɗe su don su mai da su gare ka; suka aikata saɓo mai bantsoro. ");
INSERT INTO hausa_vpl VALUES ("NH9_27","017_9_27","NEH","9","27","27","Saboda haka ka miƙa su ga abokan gābansu waɗanda suka yi musu danniya. Amma sa’ad da ake danniyarsu sai suka yi kuka gare ka. Daga sama ka ji su, cikin jinƙanka mai girma kuwa ka ba su mai ceto, wanda ya fisshe su daga hannun abokan gābansu. ");
INSERT INTO hausa_vpl VALUES ("NH9_28","017_9_28","NEH","9","28","28","“Amma nan da nan, da suka sami hutu, sai suka sāke aikata abin da yake mugu a idonka. Sai ka yashe su ga hannun abokan gābansu don su yi mulki a kansu. Sa’ad da suka yi kuka kuma gare ka, ka ji daga sama, cikin jinƙanka kuma ka fisshe su sau da sau. ");
INSERT INTO hausa_vpl VALUES ("NH9_29","017_9_29","NEH","9","29","29","“Ka gargaɗe su su dawo ga dokarka, amma suka yi fariya, suka bijire wa umarnanka. Suka yi zunubi game da farillanka waɗanda ta wurinsu ne mutum zai rayu in ya yi biyayya da su. Cikin taurinkai suka juye bayansu daga gare ka, suka zama masu taurinkai, suka kuma ƙi su saurara. ");
INSERT INTO hausa_vpl VALUES ("NH9_30","017_9_30","NEH","9","30","30","Shekaru masu yawa ka yi haƙuri da su. Ta wurin Ruhunka ka gargaɗe su ta wurin annabawa. Duk da haka ba su kasa kunne ba, saboda haka ka miƙa su ga maƙwabtansu. ");
INSERT INTO hausa_vpl VALUES ("NH9_31","017_9_31","NEH","9","31","31","Amma cikin tausayinka mai girma ba ka kawo su ga ƙarshe ko ka yashe su ba, gama kai Allah ne mai alheri da kuma mai jinƙai. ");
INSERT INTO hausa_vpl VALUES ("NH9_32","017_9_32","NEH","9","32","32","“To yanzu, ya Allahnmu, mai girma, mai iko, da kuma mai banrazana, wanda yake kiyaye alkawarinsa na ƙauna, kada ka bar dukan wannan wahala ta zama kamar marar muhimmanci a idanunka, wahalar da ta zo a kanmu, a kan sarakunanmu da shugabanni, a kan firistocinmu da annabawa, a kan kakanninmu da kuma dukan mutanenka, daga kwanakin sarakunan Assuriya har yă zuwa yau. ");
INSERT INTO hausa_vpl VALUES ("NH9_33","017_9_33","NEH","9","33","33","Cikin dukan abubuwan da suka faru da mu, ka kasance mai adalci; ka yi aminci, yayinda mu kuwa muka aikata mugu. ");
INSERT INTO hausa_vpl VALUES ("NH9_34","017_9_34","NEH","9","34","34","Sarakunanmu, da shugabanninmu, da firistocinmu da kuma kakanninmu ba su bi dokarka ba, ba su ma mai da hankali ga umarnanka ko gargaɗin da ka yi musu ba. ");
INSERT INTO hausa_vpl VALUES ("NH9_35","017_9_35","NEH","9","35","35","Ko ma yayinda suke a masarautarsu, suna jin daɗin girmar kyautatawarka gare su, cikin ƙasar mai girma, da kuma mai fāɗin da ka ba su, ba su bauta maka ko su juye daga mugayen hanyoyinsu ba. ");
INSERT INTO hausa_vpl VALUES ("NH9_36","017_9_36","NEH","9","36","36","“Amma duba, mu bayi ne a yau, bayi a ƙasar da ka ba kakanninmu don su ci amfaninta da kuma waɗansu abubuwa masu kyau da take bayarwa. ");
INSERT INTO hausa_vpl VALUES ("NH9_37","017_9_37","NEH","9","37","37","Saboda zunubanmu, yalwar girbin da muke samu yana tafiya wurin sarakunan da ka sa a kanmu. Suna mulki bisa jikunanmu, da bisa garkenmu yadda suka ga dama. Muna cikin baƙin ciki. ");
INSERT INTO hausa_vpl VALUES ("NH9_38","017_9_38","NEH","9","38","38","“Saboda wannan duka, muna yin zaunannen alkawari, muna sa shi a rubuce, shugabanninmu kuwa da Lawiyawanmu, da firistocinmu suna buga hatimansu a kai.” ");
INSERT INTO hausa_vpl VALUES ("NH10_1","017_10_1","NEH","10","1","1","Waɗanda suka buga hatimin su ne, Nehemiya ɗan Hakaliya, wanda yake gwamna. Zedekiya ");
INSERT INTO hausa_vpl VALUES ("NH10_2","017_10_2","NEH","10","2","2","da Serahiya, da Azariya, da Irmiya, ");
INSERT INTO hausa_vpl VALUES ("NH10_3","017_10_3","NEH","10","3","3","da Fashhur, da Amariya, da Malkiya, ");
INSERT INTO hausa_vpl VALUES ("NH10_4","017_10_4","NEH","10","4","4","da Hattush, da Shebaniya, da Malluk, ");
INSERT INTO hausa_vpl VALUES ("NH10_5","017_10_5","NEH","10","5","5","da Harim, da Meremot, da Obadiya, ");
INSERT INTO hausa_vpl VALUES ("NH10_6","017_10_6","NEH","10","6","6","da Daniyel, da Ginneton, da Baruk, ");
INSERT INTO hausa_vpl VALUES ("NH10_7","017_10_7","NEH","10","7","7","da Meshullam, da Abiya, da Miyamin, ");
INSERT INTO hausa_vpl VALUES ("NH10_8","017_10_8","NEH","10","8","8","da Ma’aziya, da Bilgai, da kuma Shemahiya. Waɗannan su ne Firistocin. ");
INSERT INTO hausa_vpl VALUES ("NH10_9","017_10_9","NEH","10","9","9","Lawiyawan kuwa su ne, Yeshuwa ɗan Azaniya, da Binnuyi ɗan Henadad, da Kadmiyel, ");
INSERT INTO hausa_vpl VALUES ("NH10_10","017_10_10","NEH","10","10","10","’yan’uwansu kuwa su ne, Shebaniya, da Hodiya, da Kelita, da Felahiya, da Hanan, ");
INSERT INTO hausa_vpl VALUES ("NH10_11","017_10_11","NEH","10","11","11","da Mika, da Rehob, da Hashabiya, ");
INSERT INTO hausa_vpl VALUES ("NH10_12","017_10_12","NEH","10","12","12","da Zakkur, da Sherebiya, da Shebaniya, ");
INSERT INTO hausa_vpl VALUES ("NH10_13","017_10_13","NEH","10","13","13","da Hodiya, da Bani da kuma Beninu. ");
INSERT INTO hausa_vpl VALUES ("NH10_14","017_10_14","NEH","10","14","14","Shugabannin mutane su ne, Farosh, da Fahat-Mowab, da Elam, da Zattu, da Bani, ");
INSERT INTO hausa_vpl VALUES ("NH10_15","017_10_15","NEH","10","15","15","da Bunni, da Azgad, da Bebai, ");
INSERT INTO hausa_vpl VALUES ("NH10_16","017_10_16","NEH","10","16","16","da Adoniya, da Bigwai, da Adin, ");
INSERT INTO hausa_vpl VALUES ("NH10_17","017_10_17","NEH","10","17","17","da Ater, da Hezekiya, da Azzur, ");
INSERT INTO hausa_vpl VALUES ("NH10_18","017_10_18","NEH","10","18","18","da Hodiya, da Hashum, da Bezai, ");
INSERT INTO hausa_vpl VALUES ("NH10_19","017_10_19","NEH","10","19","19","da Harif, da Anatot, da Nebai, ");
INSERT INTO hausa_vpl VALUES ("NH10_20","017_10_20","NEH","10","20","20","da Magfiyash, da Meshullam, da Hezir, ");
INSERT INTO hausa_vpl VALUES ("NH10_21","017_10_21","NEH","10","21","21","da Meshezabel, da Zadok, da Yadduwa ");
INSERT INTO hausa_vpl VALUES ("NH10_22","017_10_22","NEH","10","22","22","da Felatiya, da Hanan, da Anahiya, ");
INSERT INTO hausa_vpl VALUES ("NH10_23","017_10_23","NEH","10","23","23","da Hosheya, da Hananiya, da Hasshub, ");
INSERT INTO hausa_vpl VALUES ("NH10_24","017_10_24","NEH","10","24","24","da Hallohesh, da Filha, da Shobek, ");
INSERT INTO hausa_vpl VALUES ("NH10_25","017_10_25","NEH","10","25","25","da Rehum, da Hashabna, da Ma’asehiya ");
INSERT INTO hausa_vpl VALUES ("NH10_26","017_10_26","NEH","10","26","26","da Ahiya, da Hanan, da Anan, ");
INSERT INTO hausa_vpl VALUES ("NH10_27","017_10_27","NEH","10","27","27","da Malluk, da Harim da kuma Ba’ana. ");
INSERT INTO hausa_vpl VALUES ("NH10_28","017_10_28","NEH","10","28","28","“Sauran mutane, wato, firistoci, Lawiyawa, matsaran ƙofofi, mawaƙa, ma’aikatan haikali da dukan waɗanda suka ware kansu daga maƙwabta saboda Dokar Allah, tare da matansu da dukan ’ya’yansu maza da mata waɗanda za su iya fahimta, ");
INSERT INTO hausa_vpl VALUES ("NH10_29","017_10_29","NEH","10","29","29","dukan waɗannan yanzu suka sadu da manyan gari ’yan’uwansu, suka rantse, cewa la’ana ta same su idan ba su kiyaye Dokar Allah da aka bayar ta wurin Musa bawan Allah su kuma mai da hankali ga yin biyayya da dukan umarnai, ƙa’idodi da farillan Ubangiji shugabanmu ba. ");
INSERT INTO hausa_vpl VALUES ("NH10_30","017_10_30","NEH","10","30","30","“Mun yi alkawari ba za mu ba da ’ya’yanmu mata aure ga mutanen da suke kewaye da mu ba, ba kuwa za mu auri ’ya’yansu mata wa ’ya’yanmu maza ba. ");
INSERT INTO hausa_vpl VALUES ("NH10_31","017_10_31","NEH","10","31","31","“Sa’ad da maƙwabta suka kawo kayayyaki ko hatsi don su sayar a ranar Asabbaci, ba za mu saya daga gare su a ranar Asabbaci ko a rana mai tsarki ba. Kowace shekarar Asabbaci ba za mu nome ƙasa ba kuma za mu yafe kowane irin bashi. ");
INSERT INTO hausa_vpl VALUES ("NH10_32","017_10_32","NEH","10","32","32","“Mun ɗauka hakkin bin umarnai na ba da kashi ɗaya bisa uku na shekel kowace shekara don hidimar gidan Allahnmu. ");
INSERT INTO hausa_vpl VALUES ("NH10_33","017_10_33","NEH","10","33","33","Za mu tanada burodin da ake ajiye a kan tebur; za mu ba da hadayun hatsi da hadayun ƙonawa na kullum; za mu ba da hadayun Asabbatai, da na bukukkuwan Sabon Wata da na bukukkuwan da aka ƙayyade; za mu ba da hadayu masu tsarki; za mu ba da hadayun zunubi don a yi kafara domin Isra’ila; mu kuma ba da abubuwan da ake bukata dukan domin ayyukan gidan Allahnmu. ");
INSERT INTO hausa_vpl VALUES ("NH10_34","017_10_34","NEH","10","34","34","“Mu, firistoci, da Lawiyawa da kuma mutane, mun jefa ƙuri’a don a san lokacin da kowane iyalinmu zai kawo sadakar itace don ƙonewa a gidan Allahnmu a ƙayyadaddun lokuta a bagaden Ubangiji Allahnmu, kamar yadda yake a rubuce a cikin Doka. ");
INSERT INTO hausa_vpl VALUES ("NH10_35","017_10_35","NEH","10","35","35","“Mun kuma ɗauka hakkin kawo nunan fari na hatsinmu da kuma na kowane itace mai ba da ’ya’ya a gidan Ubangiji kowace shekara. ");
INSERT INTO hausa_vpl VALUES ("NH10_36","017_10_36","NEH","10","36","36","“Kamar yadda yake a rubuce a cikin Doka, za mu kawo ɗan fari na ’ya’yanmu maza da na garken shanunmu, da na tumakinmu, da kuma na awakinmu a gidan Allahnmu, don firistocin da suke aikin a can. ");
INSERT INTO hausa_vpl VALUES ("NH10_37","017_10_37","NEH","10","37","37","“Ban da haka ma, za mu kawo wa ɗakunan ajiyar gidan Allahnmu, abincinmu na farko daga ƙasa, na hadayun hatsinmu, na ’ya’yan dukan itatuwanmu da kuma na sabon ruwan inabinmu da mai namu wa firistoci. Za mu kuma kawo zakkar hatsinmu wa Lawiyawa, gama Lawiyawa ne ke karɓan Zakka cikin dukan garuruwan da muke noma. ");
INSERT INTO hausa_vpl VALUES ("NH10_38","017_10_38","NEH","10","38","38","Firist wanda yake daga zuriyar Haruna zai raka Lawiyawa sa’ad da suke karɓan zakka, Lawiyawan kuma za su kawo kashi ɗaya bisa goma na zakka zuwa gidan Allahnmu, su kawo a ɗakunan ajiya na baitulmali. ");
INSERT INTO hausa_vpl VALUES ("NH10_39","017_10_39","NEH","10","39","39","Mutanen Isra’ila haɗe da Lawiyawa, za su kawo sadakokinsu na hatsi, sabon ruwan inabi da mai a ɗakunan ajiya inda ake ajiyar kayayyakin wuri mai tsarki da kuma inda firistoci, matsaran ƙofofi da kuma mawaƙa suke zama. “Ba za mu ƙyale gidan Allahnmu ba.” ");
INSERT INTO hausa_vpl VALUES ("NH11_1","017_11_1","NEH","11","1","1","To, fa, shugabannin mutane suka zauna a Urushalima, sauran mutanen kuma suka jefa ƙuri’a don su kawo mutum ɗaya daga kowane mutum goma don su zauna a Urushalima, birni mai tsarki, yayinda sauran tara suka zauna a garuruwansu. ");
INSERT INTO hausa_vpl VALUES ("NH11_2","017_11_2","NEH","11","2","2","Sai mutane suka yaba wa dukan mutanen da suka ba da kansu da yardar rai su zauna a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("NH11_3","017_11_3","NEH","11","3","3","Waɗannan su ne shugabannin yankuna waɗanda suka zauna a Urushalima (ko da yake waɗansu Isra’ilawa, da firistoci, da Lawiyawa, da ma’aikatan haikali, da zuriyar bayin Solomon, suka yi zama a cikin garuruwan Yahuda, kowanne a mallakarsa cikin garuruwa dabam-dabam, ");
INSERT INTO hausa_vpl VALUES ("NH11_4","017_11_4","NEH","11","4","4","yayinda sauran mutane daga Yahuda da Benyamin suka zauna a Urushalima). Daga zuriyar Yahuda akwai, Atahiya ɗan Uzziya, ɗan Zakariya, ɗan Amariya, ɗan Shefatiya, ɗan Mahalalel, wani zuriyar Ferez; ");
INSERT INTO hausa_vpl VALUES ("NH11_5","017_11_5","NEH","11","5","5","da Ma’asehiya ɗan Baruk, ɗan Kol-Hoze, ɗan Hazahiya, ɗan Adahiya, ɗan Yohiyarib, ɗan Zakariya, zuriyar Shela. ");
INSERT INTO hausa_vpl VALUES ("NH11_6","017_11_6","NEH","11","6","6","Zuriyar Ferez waɗanda suka zauna a Urushalima sun kai ɗari huɗu da sittin da takwas, dukansu kuwa muhimman mutane ne. ");
INSERT INTO hausa_vpl VALUES ("NH11_7","017_11_7","NEH","11","7","7","Daga zuriyar Benyamin akwai, Sallu ɗan Meshullam, ɗan Yowed, ɗan Fedahiya, ɗan Kolahiya, ɗan Ma’asehiya, ɗan Itiyel, ɗan Yeshahiya, ");
INSERT INTO hausa_vpl VALUES ("NH11_8","017_11_8","NEH","11","8","8","da mabiyansa, Gabbai da Sallai, mutum 928. ");
INSERT INTO hausa_vpl VALUES ("NH11_9","017_11_9","NEH","11","9","9","Yowel ɗan Zikri ne babban shugabansu, Yahuda kuma ɗan Hassenuwa, ya shugabanci Yanki na Biyu na birni. ");
INSERT INTO hausa_vpl VALUES ("NH11_10","017_11_10","NEH","11","10","10","Daga firistoci akwai, Yedahiya ɗan Yohiyarib, da Yakin, ");
INSERT INTO hausa_vpl VALUES ("NH11_11","017_11_11","NEH","11","11","11","da Serahiya ɗan Hilkiya, ɗan Meshullam, ɗan Zadok, ɗan Merahiyot, ɗan Ahitub, mai lura da abubuwa a cikin gidan Allah, ");
INSERT INTO hausa_vpl VALUES ("NH11_12","017_11_12","NEH","11","12","12","tare da ’yan’uwansu waɗanda suke aiki domin haikali, su 822 ne. Akwai kuma Adahiya ɗan Yeroham, ɗan Felaliya, ɗan Amzi, ɗan Zakariya, ɗan Fashhur, ɗan Malkiya, ");
INSERT INTO hausa_vpl VALUES ("NH11_13","017_11_13","NEH","11","13","13","da ’yan’uwansa waɗanda suke shugabannin iyalai, su 242. Sai kuma Amashsai ɗan Azarel, ɗan Ahzai, ɗan Meshillemot, ɗan Immer, ");
INSERT INTO hausa_vpl VALUES ("NH11_14","017_11_14","NEH","11","14","14","da ’yan’uwansa, su 128 ne muhimman mutane. Babban shugabansu shi ne Zabdiyel ɗan Haggedolim. ");
INSERT INTO hausa_vpl VALUES ("NH11_15","017_11_15","NEH","11","15","15","Daga Lawiyawa kuwa akwai, Shemahiya ɗan Hasshub, ɗan Azrikam, ɗan Hashabiya, ɗan Bunni, ");
INSERT INTO hausa_vpl VALUES ("NH11_16","017_11_16","NEH","11","16","16","da Shabbetai, da kuma Yozabad, biyu cikin shugabanni Lawiyawa waɗanda suke da nawayar aiki waje da gidan Allah. ");
INSERT INTO hausa_vpl VALUES ("NH11_17","017_11_17","NEH","11","17","17","Sai kuma Mattaniya ɗan Mika, ɗan Zabdi, ɗan Asaf, shugaban da yake bi da hidimar godiya da kuma addu’a. Sai Bakbukiya, na biyu a cikin ’yan’uwansa; da Abda ɗan Shammuwa, ɗan Galal, ɗan Yedutun. ");
INSERT INTO hausa_vpl VALUES ("NH11_18","017_11_18","NEH","11","18","18","Lawiyawan da suke cikin birni mai tsarki sun kai 284. ");
INSERT INTO hausa_vpl VALUES ("NH11_19","017_11_19","NEH","11","19","19","Matsaran ƙofofi kuwa su ne, Akkub, da Talmon, da ’yan’uwansu waɗanda suke tsaron ƙofofi, su 172 ne. ");
INSERT INTO hausa_vpl VALUES ("NH11_20","017_11_20","NEH","11","20","20","Sauran Isra’ilawa tare da firistoci, da Lawiyawa sun kasance a dukan garuruwan Yahuda, kowanne a mallakar kakansa. ");
INSERT INTO hausa_vpl VALUES ("NH11_21","017_11_21","NEH","11","21","21","Ma’aikatan haikali sun zauna a kan tudun Ofel. Ziha, da Gishfa ne suke lura da su. ");
INSERT INTO hausa_vpl VALUES ("NH11_22","017_11_22","NEH","11","22","22","Babban shugaban Lawiyawa a Urushalima shi ne Uzzi ɗan Bani, ɗan Hashabiya, ɗan Mattaniya, ɗan Mika. Uzzi yana ɗaya daga zuriyar Asaf, waɗanda suke mawaƙan da suke da nawayar hidima a gidan Allah. ");
INSERT INTO hausa_vpl VALUES ("NH11_23","017_11_23","NEH","11","23","23","Mawaƙa sun bi umarnan sarki, a kan abin da za su yi kowace rana. ");
INSERT INTO hausa_vpl VALUES ("NH11_24","017_11_24","NEH","11","24","24","Fetahahiya ɗan Meshezabel, ɗaya daga zuriyar Zera ɗan Yahuda ne, wakilin sarki cikin dukan al’amuran da suka shafi mutane. ");
INSERT INTO hausa_vpl VALUES ("NH11_25","017_11_25","NEH","11","25","25","Game da ƙauyukan da filayensu, waɗansu mutanen Yahuda suka zauna a Kiriyat Arba da ƙauyukanta, da Dibon da ƙauyukanta, da Yekabzeyel da ƙauyukanta. ");
INSERT INTO hausa_vpl VALUES ("NH11_26","017_11_26","NEH","11","26","26","Akwai su kuma a Yeshuwa, da Molada, da Bet-Felet, ");
INSERT INTO hausa_vpl VALUES ("NH11_27","017_11_27","NEH","11","27","27","da Hazar Shuwal, da Beyersheba da ƙauyukanta. ");
INSERT INTO hausa_vpl VALUES ("NH11_28","017_11_28","NEH","11","28","28","Akwai su a Ziklag, da Mekona da ƙauyukanta. ");
INSERT INTO hausa_vpl VALUES ("NH11_29","017_11_29","NEH","11","29","29","Suna nan kuma a En Rimmon, da Zora, da Yarmut, ");
INSERT INTO hausa_vpl VALUES ("NH11_30","017_11_30","NEH","11","30","30","da Zanowa, da Adullam da ƙauyukansu, da Lakish da gonakinta, da kuma Azeka da ƙauyukanta. Saboda haka sun yi zama tun daga Beyersheba har zuwa Kwarin Hinnom. ");
INSERT INTO hausa_vpl VALUES ("NH11_31","017_11_31","NEH","11","31","31","Zuriyar mutanen Benyamin daga Geba sun zauna a Mikmash, da Aiya, da Betel da ƙauyukanta, ");
INSERT INTO hausa_vpl VALUES ("NH11_32","017_11_32","NEH","11","32","32","da Anatot, da Nob, da Ananiya, ");
INSERT INTO hausa_vpl VALUES ("NH11_33","017_11_33","NEH","11","33","33","da Hazor, da Rama, da Gittayim, ");
INSERT INTO hausa_vpl VALUES ("NH11_34","017_11_34","NEH","11","34","34","da Hadid, da Zeboyim, da Neballat, ");
INSERT INTO hausa_vpl VALUES ("NH11_35","017_11_35","NEH","11","35","35","da Lod, da Ono, da kuma a Kwarin Masu sana’a. ");
INSERT INTO hausa_vpl VALUES ("NH11_36","017_11_36","NEH","11","36","36","Waɗansu gundumomin Lawiyawan Yahuda sun zauna a Benyamin. ");
INSERT INTO hausa_vpl VALUES ("NH12_1","017_12_1","NEH","12","1","1","Waɗannan su ne firistoci da Lawiyawa waɗanda suka komo tare da Zerubbabel ɗan Sheyaltiyel da kuma Yeshuwa. Serahiya, Irmiya, Ezra, ");
INSERT INTO hausa_vpl VALUES ("NH12_2","017_12_2","NEH","12","2","2","Amariya, Malluk, Hattush ");
INSERT INTO hausa_vpl VALUES ("NH12_3","017_12_3","NEH","12","3","3","Shekaniya, Rehum, Meremot, ");
INSERT INTO hausa_vpl VALUES ("NH12_4","017_12_4","NEH","12","4","4","Iddo, Ginneton, Abiya, ");
INSERT INTO hausa_vpl VALUES ("NH12_5","017_12_5","NEH","12","5","5","Miyamin, Mowadiya, Bilga, ");
INSERT INTO hausa_vpl VALUES ("NH12_6","017_12_6","NEH","12","6","6","Shemahiya, Yohiyarib, Yedahiya, ");
INSERT INTO hausa_vpl VALUES ("NH12_7","017_12_7","NEH","12","7","7","Sallu, Amok, Hilkiya da Yedahiya. Waɗannan su ne shugabannin firistoci da ’yan’uwansu a kwanakin Yeshuwa. ");
INSERT INTO hausa_vpl VALUES ("NH12_8","017_12_8","NEH","12","8","8","Lawiyawan su ne Yeshuwa, Binnuyi, Kadmiyel, Sherebiya, Yahuda, da kuma Mattaniya, wanda tare da ’yan’uwansa yake lura da waƙoƙin godiya. ");
INSERT INTO hausa_vpl VALUES ("NH12_9","017_12_9","NEH","12","9","9","Bakbukiya da Unni, ’yan’uwansu sun tsaya ɗaura da su a hidimomi. ");
INSERT INTO hausa_vpl VALUES ("NH12_10","017_12_10","NEH","12","10","10","Yeshuwa ne mahaifin Yohiyakim, Yohiyakim shi ne mahaifin Eliyashib, Eliyashib shi ne mahaifin Yohiyada, ");
INSERT INTO hausa_vpl VALUES ("NH12_11","017_12_11","NEH","12","11","11","Yohiyada shi ne mahaifin Yonatan, Yonatan kuma mahaifin Yadduwa. ");
INSERT INTO hausa_vpl VALUES ("NH12_12","017_12_12","NEH","12","12","12","A kwanakin Yohiyakim, waɗannan su ne shugabannin iyalan firistoci, na iyalin Serahiya, Merahiya; na iyalin Irmiya, Hananiya; ");
INSERT INTO hausa_vpl VALUES ("NH12_13","017_12_13","NEH","12","13","13","na iyalin Ezra, Meshullam; na iyalin Amariya, Yehohanan; ");
INSERT INTO hausa_vpl VALUES ("NH12_14","017_12_14","NEH","12","14","14","na iyalin Malluk, Yonatan; na iyalin Shebaniya, Yusuf; ");
INSERT INTO hausa_vpl VALUES ("NH12_15","017_12_15","NEH","12","15","15","na iyalin Harim, Adna; na iyalin Merahiyot, Helkai; ");
INSERT INTO hausa_vpl VALUES ("NH12_16","017_12_16","NEH","12","16","16","na iyalin Iddo, Zakariya; na iyalin Ginneton, Meshullam; ");
INSERT INTO hausa_vpl VALUES ("NH12_17","017_12_17","NEH","12","17","17","na iyalin Abiya, Zikri; na iyalin Miniyamin da na Mowadiya, Filtai; ");
INSERT INTO hausa_vpl VALUES ("NH12_18","017_12_18","NEH","12","18","18","na iyalin Bilga, Shammuwa; na iyalin Shemahiya, Yehonatan; ");
INSERT INTO hausa_vpl VALUES ("NH12_19","017_12_19","NEH","12","19","19","na iyalin Yohiyarib, Mattenai; na iyalin Yedahiya, Uzzi; ");
INSERT INTO hausa_vpl VALUES ("NH12_20","017_12_20","NEH","12","20","20","na iyalin Sallu, Kallai; na iyalin Amok, Eber; ");
INSERT INTO hausa_vpl VALUES ("NH12_21","017_12_21","NEH","12","21","21","na iyalin Hilkiya, Hashabiya; na iyalin Yedahiya, Netanel. ");
INSERT INTO hausa_vpl VALUES ("NH12_22","017_12_22","NEH","12","22","22","Shugabannin iyalin Lawiyawa a kwanakin Eliyashib, Yohiyada, Yohanan da Yadduwa, da kuma na firistoci, an rubuta su a zamanin mulkin Dariyus mutumin Farisa. ");
INSERT INTO hausa_vpl VALUES ("NH12_23","017_12_23","NEH","12","23","23","Shugabannin iyali cikin zuriyar Lawi har zuwa lokacin Yohanan ɗan Eliyashib, an rubuta su a cikin littafin tarihi. ");
INSERT INTO hausa_vpl VALUES ("NH12_24","017_12_24","NEH","12","24","24","Shugabannin Lawiyawa kuwa su ne Hashabiya, Sherebiya, Yeshuwa ɗan Kadmiyel, da ’yan’uwansu, waɗanda suka tsaya ɗaura da su don su yi yabo da kuma godiya, sashe ɗaya kan ba da amsa ga ɗaya sashen, kamar yadda Dawuda mutumin Allah ya umarta. ");
INSERT INTO hausa_vpl VALUES ("NH12_25","017_12_25","NEH","12","25","25","Mattaniya, Bakbukiya, Obadiya, Meshullam, Talmon da Akkub su ne matsaran ƙofofi waɗanda suka yi tsaron ɗaukan ajiya a ƙofofi. ");
INSERT INTO hausa_vpl VALUES ("NH12_26","017_12_26","NEH","12","26","26","Sun yi hidima a kwanakin Yohiyakim ɗan Yeshuwa, ɗan Yozadak, kuma a kwanakin Nehemiya gwamna da kuma na Ezra firist da kuma marubuci. ");
INSERT INTO hausa_vpl VALUES ("NH12_27","017_12_27","NEH","12","27","27","A keɓewar katangar Urushalima, an nemi Lawiyawa daga inda suke zama aka kawo su Urushalima don su yi bikin miƙawa da farin ciki da waƙoƙin godiya da kuma kiɗin kuge, garaya da molo. ");
INSERT INTO hausa_vpl VALUES ("NH12_28","017_12_28","NEH","12","28","28","Aka kuma tattara mawaƙa su ma daga yankin kewayen Urushalima, daga ƙauyukan Netofawa, ");
INSERT INTO hausa_vpl VALUES ("NH12_29","017_12_29","NEH","12","29","29","daga Bet-Gilgal, da kuma daga wuraren Geba da Azmawet, gama mawaƙan sun gina wa kansu ƙauyuka kewaye da Urushalima. ");
INSERT INTO hausa_vpl VALUES ("NH12_30","017_12_30","NEH","12","30","30","Sa’ad da firistoci da Lawiyawa suka tsarkake kansu da tsarki, sai suka tsarkake mutane, ƙofofi da kuma katanga. ");
INSERT INTO hausa_vpl VALUES ("NH12_31","017_12_31","NEH","12","31","31","Sai na sa shugabannin Yahuda suka haura zuwa bisan katangar. Na kuma sa manyan ƙungiyoyi biyu na mawaƙa su miƙa godiya. Ɗaya ya haura zuwa bisan katangar zuwa dama, wajen Ƙofar Juji. ");
INSERT INTO hausa_vpl VALUES ("NH12_32","017_12_32","NEH","12","32","32","Hoshahiya da rabin shugabannin Yahuda kuwa suka bi su, ");
INSERT INTO hausa_vpl VALUES ("NH12_33","017_12_33","NEH","12","33","33","tare da Azariya, Ezra, Meshullam, ");
INSERT INTO hausa_vpl VALUES ("NH12_34","017_12_34","NEH","12","34","34","Yahuda, Benyamin, Shemahiya, Irmiya, ");
INSERT INTO hausa_vpl VALUES ("NH12_35","017_12_35","NEH","12","35","35","da waɗansu firistoci kuma da ƙahoni, da kuma Zakariya ɗan Yonatan, ɗan Shemahiya, ɗan Mattaniya, ɗan Mikahiya, ɗan Zakkur, ɗan Asaf, ");
INSERT INTO hausa_vpl VALUES ("NH12_36","017_12_36","NEH","12","36","36","da ’yan’uwansa, Shemahiya, Azarel, Milalai, Gilalai, Ma’ai, Netanel, Yahuda da Hanani, tare da kayan kiɗi da Dawuda mutumin Allah ya umarta. Ezra malamin Doka ya jagoranci jerin gwanon. ");
INSERT INTO hausa_vpl VALUES ("NH12_37","017_12_37","NEH","12","37","37","A Ƙofar Maɓuɓɓuga suka ci gaba kai tsaye suka haura matakalan Birnin Dawuda a kan hawa zuwa katangar suka wuce a bisa gidan Dawuda zuwa Ƙofar Ruwa wajen gabas. ");
INSERT INTO hausa_vpl VALUES ("NH12_38","017_12_38","NEH","12","38","38","Ƙungiyar mawaƙa ta biyu suka yi jerin gwano a ɗaya gefen. Na bi su a bisan katangar, tare da rabin mutanen, muka wuce Hasumiya Tanderu zuwa Katanga Mai Faɗi, ");
INSERT INTO hausa_vpl VALUES ("NH12_39","017_12_39","NEH","12","39","39","bisa Ƙofar Efraim, Ƙofar Yeshana, Ƙofar Kifi, Hasumiyar Hananel da kuma Hasumiya ɗari, har zuwa Ƙofar Tumaki. A Ƙofar Matsara suka tsaya. ");
INSERT INTO hausa_vpl VALUES ("NH12_40","017_12_40","NEH","12","40","40","Ƙungiyoyin mawaƙa biyu da suka yi godiya suka ɗauki wurarensu a gidan Allah, haka ma ni, tare da rabin shugabanni, ");
INSERT INTO hausa_vpl VALUES ("NH12_41","017_12_41","NEH","12","41","41","da kuma firistoci, Eliyakim, Ma’asehiya, Miniyamin, Mikahiya, Eliyohenai, Zakariya da Hananiya tare da ƙahoninsu, ");
INSERT INTO hausa_vpl VALUES ("NH12_42","017_12_42","NEH","12","42","42","haka ma Ma’asehiya, Shemahiya, Eleyazar, Uzzi, Yehohanan, Malkiya, Elam da Ezer. Mawaƙan suka rera waƙoƙi a ƙarƙashin kulawar Yezrahiya. ");
INSERT INTO hausa_vpl VALUES ("NH12_43","017_12_43","NEH","12","43","43","A rana ta uku kuma suka miƙa manyan hadayu, suna farin ciki domin Allah ya ba su farin ciki mai girma. Mata da yara suka yi farin ciki su ma. An ji ƙarar farin ciki da ake yi a Urushalima daga nesa. ");
INSERT INTO hausa_vpl VALUES ("NH12_44","017_12_44","NEH","12","44","44","A lokacin an naɗa mutane su lura da ɗakunan ajiya don sadakoki, nunan fari da kuma zakka. Daga gonakin garuruwan da suke kewaye za su kawo sassan da Dokar ta umarta zuwa ɗakunan ajiya domin firistoci da Lawiyawa, gama Yahuda ya ji daɗin aikin firistoci da Lawiyawa. ");
INSERT INTO hausa_vpl VALUES ("NH12_45","017_12_45","NEH","12","45","45","Sun yi hidimar Allahnsu da kuma hidimar tsarkakewa, kamar yadda mawaƙa da matsaran ƙofofi suka yi, bisa ga umarnin Dawuda da ɗansa Solomon. ");
INSERT INTO hausa_vpl VALUES ("NH12_46","017_12_46","NEH","12","46","46","Gama tun dā, a kwanakin Dawuda da Asaf, akwai masu bi da mawaƙa da kuma na waƙoƙin yabo da na godiya ga Allah. ");
INSERT INTO hausa_vpl VALUES ("NH12_47","017_12_47","NEH","12","47","47","Saboda haka a kwanakin Zerubbabel da Nehemiya, dukan Isra’ila suka ba da sashe na kowace rana domin mawaƙa da matsaran ƙofofi. Suka kuma keɓe sashe don sauran Lawiyawa, Lawiyawan kuma suka keɓe sashe don zuriyar Haruna. ");
INSERT INTO hausa_vpl VALUES ("NH13_1","017_13_1","NEH","13","1","1","A wannan rana aka karanta Littafin Musa da ƙarfi a kunnuwan mutane aka kuma sami an rubuta cewa kada a karɓi mutumin Ammon ko mutumin Mowab cikin taron Allah, ");
INSERT INTO hausa_vpl VALUES ("NH13_2","017_13_2","NEH","13","2","2","domin ba su taryi Isra’ila da abinci da ruwa ba amma suka yi hayar Bala’am don yă kira la’ana a kansu. (Amma Allahnmu, ya mai da la’anar ta zama albarka.) ");
INSERT INTO hausa_vpl VALUES ("NH13_3","017_13_3","NEH","13","3","3","Sa’ad da mutane suka ji wannan doka, sai suka ware daga Isra’ila duk waɗanda suke na baƙon zuriya. ");
INSERT INTO hausa_vpl VALUES ("NH13_4","017_13_4","NEH","13","4","4","Kafin wannan, an sa Eliyashib firist yă lura da ɗakuna ajiyar gidan Allahnmu. Yana da dangantaka na kurkusa da Tobiya, ");
INSERT INTO hausa_vpl VALUES ("NH13_5","017_13_5","NEH","13","5","5","ya kuma tanada masa babban ɗakin da dā ake ajiyar hadayun hatsi da turare da kayayyaki haikali, da kuma zakan hatsi, sabon ruwan inabi da kuma mai da aka umarta don Lawiyawa, mawaƙa da kuma matsaran ƙofofi, da kuma sadakoki domin firistoci. ");
INSERT INTO hausa_vpl VALUES ("NH13_6","017_13_6","NEH","13","6","6","Amma yayinda dukan wannan yake faruwa, ba ni a Urushalima, gama a shekara ta talatin da biyu na Artazerzes sarkin Babilon na dawo wurin sarki. A wani lokaci daga baya na nemi izininsa ");
INSERT INTO hausa_vpl VALUES ("NH13_7","017_13_7","NEH","13","7","7","sai na koma zuwa Urushalima. A nan na ji game da mugun abin da Eliyashib ya aikata da ya tanada wa Tobiya ɗaki a filayen gidan Allah. ");
INSERT INTO hausa_vpl VALUES ("NH13_8","017_13_8","NEH","13","8","8","Na ɓace rai ƙwarai na kuma zubar da dukan kayan gidan Tobiya daga ɗakin. ");
INSERT INTO hausa_vpl VALUES ("NH13_9","017_13_9","NEH","13","9","9","Na umarta a tsarkake ɗakunan, sa’an nan na mayar da kayan gidan Allah a cikin ɗakunan, tare da hadayun hatsi da kuma turare. ");
INSERT INTO hausa_vpl VALUES ("NH13_10","017_13_10","NEH","13","10","10","Na kuma ji cewa sassan da ake ba wa Lawiyawa ba a ba su ba, cewa kuma dukan Lawiyawa da mawaƙan da suke da hakkin hidima sun koma gonakinsu. ");
INSERT INTO hausa_vpl VALUES ("NH13_11","017_13_11","NEH","13","11","11","Sai na tsawata wa shugabanni na kuma tambaye su na ce, “Me ya sa aka ƙyale gidan Allah?” Sa’an nan na kira su gaba ɗaya na sa su a wuraren aikinsu. ");
INSERT INTO hausa_vpl VALUES ("NH13_12","017_13_12","NEH","13","12","12","Dukan Yahuda suka kawo zakan hatsi, sabon ruwan inabi da mai cikin ɗakunan ajiya. ");
INSERT INTO hausa_vpl VALUES ("NH13_13","017_13_13","NEH","13","13","13","Na sa Shelemiya firist, Zadok marubuci, da wani Balawe mai suna Fedahiya su lura da ɗakunan ajiya na kuma sa Hanan ɗan Zakkur, ɗan Mattaniya ya zama mataimakinsu, domin an ɗauka waɗannan mutane amintattu ne. Aka ba su hakkin raban kayayyaki wa ’yan’uwansu. ");
INSERT INTO hausa_vpl VALUES ("NH13_14","017_13_14","NEH","13","14","14","Ka tuna da ni saboda wannan, ya Allahna, kuma kada ka shafe abin da na yi da aminci domin gidan Allahna da kuma hidimarsa. ");
INSERT INTO hausa_vpl VALUES ("NH13_15","017_13_15","NEH","13","15","15","A waɗannan kwanaki, na ga mutane a Yahuda suna matse ruwan inabi a ranar Asabbaci suna kuma kawo hatsi suna labta su a kan jakuna, tare da ruwan inabi, ’ya’yan inabi, ɓaure da kaya iri-iri. Suna kuma kawowa dukan wannan cikin Urushalima a ranar Asabbaci. Saboda haka na gargaɗe su a kan sayar da abinci a wannan rana. ");
INSERT INTO hausa_vpl VALUES ("NH13_16","017_13_16","NEH","13","16","16","Mutane daga Taya waɗanda suke zama a Urushalima suna shigar da kifi da kaya iri-iri na ’yan kasuwa suna kuma sayar da su a Urushalima a ranar Asabbaci wa mutanen Yahuda. ");
INSERT INTO hausa_vpl VALUES ("NH13_17","017_13_17","NEH","13","17","17","Sai na tsawata wa manyan Yahuda na ce musu, “Wanda irin mugun abu ke nan kuke yi, kuna ƙazantar da ranar Asabbaci? ");
INSERT INTO hausa_vpl VALUES ("NH13_18","017_13_18","NEH","13","18","18","Kakanninku ba su yi irin waɗannan abubuwa ba, har Allahnmu ya kawo dukan masifun nan a kanmu da kuma a kan wannan birni? Yanzu kuna tsokanar fushi mai yawa a kan Isra’ila ta wurin ƙazantar da Asabbaci.” ");
INSERT INTO hausa_vpl VALUES ("NH13_19","017_13_19","NEH","13","19","19","Sa’ad da inuwar yamma ya fāɗo a ƙofofin Urushalima kafin Asabbaci, na umarta a rufe ƙofofi kuma kada a buɗe sai Asabbaci ya wuce. Na kafa waɗansu mutanena a ƙofofin don kada a shigo da wani kaya a ranar Asabbaci. ");
INSERT INTO hausa_vpl VALUES ("NH13_20","017_13_20","NEH","13","20","20","Sau ɗaya ko biyu, ’yan kasuwa da masu sayar da kowane irin kaya suka kwana waje da Urushalima. ");
INSERT INTO hausa_vpl VALUES ("NH13_21","017_13_21","NEH","13","21","21","Amma na ja kunnensu na ce, “Me ya sa kuke kwana kusa da katanga? In kuka ƙara yin haka, zan kama ku.” Daga wannan lokaci har zuwa gaba ba su ƙara zuwa a ranar Asabbaci ba. ");
INSERT INTO hausa_vpl VALUES ("NH13_22","017_13_22","NEH","13","22","22","Sai na umarci Lawiyawa su tsarkake kansu su kuma tafi su yi tsaron ƙofofi don a kiyaye ranar Asabbaci da tsarki. Ka tuna da ni saboda wannan shi ma, ya Allahna, ka nuna mini jinƙai bisa ga madawwamiyar ƙaunarka. ");
INSERT INTO hausa_vpl VALUES ("NH13_23","017_13_23","NEH","13","23","23","Ban da haka, a waɗannan kwanakin na ga mutanen Yahuda waɗanda suka auri mata daga Ashdod, Ammon da Mowab. ");
INSERT INTO hausa_vpl VALUES ("NH13_24","017_13_24","NEH","13","24","24","Rabin ’ya’yansu suna yaren Ashdod ko kuwa wani yare na waɗansu mutane, ba su kuwa san yadda za su yi Yahudanci ba. ");
INSERT INTO hausa_vpl VALUES ("NH13_25","017_13_25","NEH","13","25","25","Na tsawata musu na kuma kira la’ana a kansu. Na bugi waɗansu mutane na kuma ja gashin kansu. Na sa suka yi rantsuwa da sunan Allah na ce, “Kada ku ba da ’ya’yanku mata aure ga ’ya’yansu maza, ba kuwa za ku auri ’ya’yansu mata wa ’ya’yanku maza ko wa kanku ba. ");
INSERT INTO hausa_vpl VALUES ("NH13_26","017_13_26","NEH","13","26","26","Ba don aure-aure irin waɗannan ne Solomon sarkin Isra’ila ya yi zunubi ba? A cikin yawancin al’ummai babu sarki kamar sa. Allahnsa ya ƙaunace shi, Allah kuma ya mai da shi sarki a kan dukan Isra’ila, amma duk da haka baren mata suka rinjaye shi ga zunubi. ");
INSERT INTO hausa_vpl VALUES ("NH13_27","017_13_27","NEH","13","27","27","Yanzu za mu ji cewa ku ma kuna yin duk wannan mugunta kuna zama marasa aminci ga Allahnmu ta wurin auren baren mata?” ");
INSERT INTO hausa_vpl VALUES ("NH13_28","017_13_28","NEH","13","28","28","Ɗaya daga cikin ’ya’yan Yohiyada maza, ɗan Eliyashib babban firist, surukin Sanballat mutumin Horon ne. Na kuwa kore shi daga wurina. ");
INSERT INTO hausa_vpl VALUES ("NH13_29","017_13_29","NEH","13","29","29","Ka tuna da su, ya Allahna, domin sun ƙazantar da aikin firist da kuma alkawarin aikin firist da na Lawiyawa. ");
INSERT INTO hausa_vpl VALUES ("NH13_30","017_13_30","NEH","13","30","30","Saboda haka na tsarkake firistoci da Lawiyawa daga kowane baƙon abu, na kuma ba su aikinsu, kowa ga aikinsa. ");
INSERT INTO hausa_vpl VALUES ("NH13_31","017_13_31","NEH","13","31","31","Na kuma yi tanadi don sadakokin itace a ƙayyadaddun lokuta, da kuma don nunan fari. Ka tuna da ni da alheri, ya Allahna.");
INSERT INTO hausa_vpl VALUES ("ET1_1","018_1_1","EST","1","1","1","Ga abin da ya faru a zamanin Zerzes. Zerzes ya yi mulki bisan larduna 127 daga Indiya zuwa Kush. ");
INSERT INTO hausa_vpl VALUES ("ET1_2","018_1_2","EST","1","2","2","A lokacin nan, Sarki Zerzes ya yi mulki daga gadon sarauta, cikin mazaunin masarautar Shusha. ");
INSERT INTO hausa_vpl VALUES ("ET1_3","018_1_3","EST","1","3","3","A shekara ta uku ta mulkinsa, ya yi wa dukan hakimansa da ma’aikatansa liyafa. Shugabannin mayaƙan Farisa, da Mediya, da yerimai; da kuma hakimai na lardunan suka kasance. ");
INSERT INTO hausa_vpl VALUES ("ET1_4","018_1_4","EST","1","4","4","Kwanaki 180 cif, ya nuna yawan dukiyar masarautarsa, da ɗaukakarta da kuma darajar girmansa. ");
INSERT INTO hausa_vpl VALUES ("ET1_5","018_1_5","EST","1","5","5","Sa’ad da waɗannan kwanaki suka wuce, sai sarki ya yi liyafa a cikin lambun da aka shinge na fadar sarki wadda ta ɗauki kwana bakwai wa dukan mutane daga ƙarami har zuwa babba, waɗanda suke zama a masarautar Shusha. ");
INSERT INTO hausa_vpl VALUES ("ET1_6","018_1_6","EST","1","6","6","Lambun yana da fararen labulen da aka rataye da shunayya na lallausan lilin, da aka ɗaura da igiyoyin fararen lilin, da yadin jan garura, haɗe da zoban azurfa a kan ginshiƙin farin ƙasa. A nan, akwai kujeru na zinariya da na azurfa a kan daɓe mai ado da aka yi da duwatsu masu daraja, da farin ƙasa, da fararen duwatsun wuya, da waɗansu duwatsu masu tsada. ");
INSERT INTO hausa_vpl VALUES ("ET1_7","018_1_7","EST","1","7","7","Aka rarraba ruwan inabi cikin kwaf na zinariya, kowanne kuwa dabam yake da ɗayan. Ruwan inabin kuwa yana da yawa, bisa ga wadatar sarki. ");
INSERT INTO hausa_vpl VALUES ("ET1_8","018_1_8","EST","1","8","8","Bisa ga umarnin sarki, aka bar kowane baƙo yă sha yadda ya ga dama, gama sarki ya umarci dukan bayin da suke rarraba ruwan inabin su ba wa kowa abin da yake so. ");
INSERT INTO hausa_vpl VALUES ("ET1_9","018_1_9","EST","1","9","9","Sarauniya Bashti ita ma ta yi liyafa saboda mata a fadar Sarki Zerzes. ");
INSERT INTO hausa_vpl VALUES ("ET1_10","018_1_10","EST","1","10","10","A rana ta bakwai, sa’ad da Sarki Zerzes, ya yi tilis da ruwan inabi, sai ya umarci bābānni bakwai waɗanda suke yin masa hidima, wato, Mehuman, Bizta, Harbona, Bigta, Abagta, Zetar da Karkas, ");
INSERT INTO hausa_vpl VALUES ("ET1_11","018_1_11","EST","1","11","11","su kawo Sarauniya Bashti a gabansa, sanye da rawanin sarautarta, don ta nuna kyanta wa mutane da kuma hakimai, gama ita kyakkyawa ce ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("ET1_12","018_1_12","EST","1","12","12","Amma da masu hidima suka ba da umarnin sarki, sai Sarauniya Bashti ta ƙi zuwa. Wannan ya ɓata wa sarki rai, ya kuma yi fushi ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("ET1_13","018_1_13","EST","1","13","13","Da yake, al’ada ce sarki yă nemi shawara daga sanannu a batun doka da adalci, sai ya yi magana da masu hikima waɗanda suke fahimtar lokuta ");
INSERT INTO hausa_vpl VALUES ("ET1_14","018_1_14","EST","1","14","14","suke kuma mafi kusa da sarki. Waɗannan masu hikima kuwa su ne, Karshena, Shetar, Admata, Tarshish, Meres, Marsena da kuma Memukan. Su hakimai bakwai ne na Farisa da Mediya waɗanda suke da dama ta musamman ta kaiwa ga sarki, suke kuma da matsayi mafi girma a masarautar. ");
INSERT INTO hausa_vpl VALUES ("ET1_15","018_1_15","EST","1","15","15","Ya ce, “Bisa ga doka, me za a yi wa Sarauniya Bashti? Gama ta ƙi yin biyayya da umarnin sarki Zerzes da bābānni suka kai mata?” ");
INSERT INTO hausa_vpl VALUES ("ET1_16","018_1_16","EST","1","16","16","Sai Memukan ya amsa a gaban sarki da hakimai ya ce, “Sarauniya Bashti ta yi laifi, ba ga sarki kaɗai ba, amma ga dukan hakimai ma, da kuma mutanen dukan lardunan sarki Zerzes. ");
INSERT INTO hausa_vpl VALUES ("ET1_17","018_1_17","EST","1","17","17","Domin halin Sarauniya zai zama sananne ga dukan mata, ta haka kuwa za su ƙasƙantar da mazansu su kuma ce, ‘Sarki Zerzes ya umarta a kawo Sarauniya Bashti a gabansa, amma ta ƙi zuwa.’ ");
INSERT INTO hausa_vpl VALUES ("ET1_18","018_1_18","EST","1","18","18","Wannan rana matan hakiman Farisa da na Mediya waɗanda suka ji game da halin sarauniya, za su yi haka wa dukan hakiman sarki. Zai zama babu ƙarshen rashin bangirma da kuma reni. ");
INSERT INTO hausa_vpl VALUES ("ET1_19","018_1_19","EST","1","19","19","“Saboda haka, in ya gamshi sarki, bari yă ba da hatimi na sarauta, bari kuma a rubuta shi cikin dokokin Farisa da Mediya, wanda ba za a iya sokewa ba, cewa Bashti ba za tă ƙara zuwa gaban sarkin Zerzes ba. Bari kuma sarki yă ba da matsayinta na sarauta ga wata, wadda ta fi ta. ");
INSERT INTO hausa_vpl VALUES ("ET1_20","018_1_20","EST","1","20","20","Ta haka, sa’ad da aka yi shelar dokar sarki ko’ina a fāɗin masarautarsa, dukan mata za su ba wa mazansu girma, daga ƙarami har zuwa babba.” ");
INSERT INTO hausa_vpl VALUES ("ET1_21","018_1_21","EST","1","21","21","Sarki da hakimansa suka gamsu da wannan shawara. Saboda haka sarki ya yi kamar yadda Memukan ya faɗa. ");
INSERT INTO hausa_vpl VALUES ("ET1_22","018_1_22","EST","1","22","22","Ya aika da saƙo zuwa ga dukan ɓangarorin masarautar, zuwa ga kowane lardi a irin nasa rubutu, zuwa kuma ga kowane mutane a nasu harshe, ana shelar a kowane yare na mutane, cewa kowane mutum yă zama mai mulki bisa gidansa. ");
INSERT INTO hausa_vpl VALUES ("ET2_1","018_2_1","EST","2","1","1","Daga baya sa’ad da fushin Sarki Zerzes ya huce, sai ya tuna da Bashti da abin da ta yi, da kuma dokar da ya bayar game da ita. ");
INSERT INTO hausa_vpl VALUES ("ET2_2","018_2_2","EST","2","2","2","Sai masu hidimar sarki na musamman, suka kawo shawara cewa, “Bari a nemi, kyawawan budurwai saboda sarki. ");
INSERT INTO hausa_vpl VALUES ("ET2_3","018_2_3","EST","2","3","3","Bari sarki yă naɗa komishinoni a kowane yanki na masarautarsa, domin su kawo dukan waɗannan kyawawan ’yan mata cikin harabar mazaunin masarautar a Shusha. Bari a sa su a hannun Hegai, bābān sarki, wanda yake lura da mata, bari kuma a yi musu kulawa ta musamman. ");
INSERT INTO hausa_vpl VALUES ("ET2_4","018_2_4","EST","2","4","4","Sa’an nan bari yarinyar da ta gamshi sarki, tă zama sarauniya a maimakon Bashti.” Wannan shawara ta gamshi sarki, ya kuwa yi na’am da ita. ");
INSERT INTO hausa_vpl VALUES ("ET2_5","018_2_5","EST","2","5","5","To, a cikin mazaunin masarauta a Shusha, akwai wani mutumin Yahuda, daga Kabilar Benyamin mai suna Mordekai, ɗan Yayir, ɗan Shimeyi, ɗan Kish, ");
INSERT INTO hausa_vpl VALUES ("ET2_6","018_2_6","EST","2","6","6","wanda Nebukadnezzar sarkin Babilon ya ɗauka tare ’yan zaman bauta cikin waɗanda ya ɗauko daga Urushalima, tare da Yekoniya, sarkin Yahuda. ");
INSERT INTO hausa_vpl VALUES ("ET2_7","018_2_7","EST","2","7","7","Mordekai yana da wata ’yar kawunsa mai suna Hadassa, wanda ya yi reno, ba ta da mahaifi ko mahaifiya. Ita ce yarinyar da aka santa da suna Esta. Kyakkyawa ce ƙwarai. Mordekai dai ya ɗauke ta tamƙar ’yarsa sa’ad da mahaifinta da mahaifiyarta suka mutu. ");
INSERT INTO hausa_vpl VALUES ("ET2_8","018_2_8","EST","2","8","8","Da aka yi shelar umarni da dokar sarki, sai aka kawo ’yan mata masu yawa a mazaunin masarauta a Shusha, aka kuma sa su ƙarƙashin kulawar Hegai. Aka kawo Esta ma zuwa fadar sarki, aka danƙa ta wa Hegai, wanda yake lura da mata. ");
INSERT INTO hausa_vpl VALUES ("ET2_9","018_2_9","EST","2","9","9","Yarinyar ta gamshe shi, ta kuma sami tagomashinsa. Nan da nan ya tanada mata, ya ba ta man shafawa da abinci na musamman. Ya ba ta bayi mata bakwai da aka zaɓa daga fadar sarki. Ya kuma kai ta tare da bayinta zuwa wuri mafi kyau na gidan matan kulle. ");
INSERT INTO hausa_vpl VALUES ("ET2_10","018_2_10","EST","2","10","10","Esta ba tă bayyana asalin al’ummarta da na iyalinta ba, domin Mordekai ya hana yin haka. ");
INSERT INTO hausa_vpl VALUES ("ET2_11","018_2_11","EST","2","11","11","Kowace rana Mordekai yana kai da komowa kusa da harabar filin gidan matan kulle, domin ya san yadda Esta take, da kuma abin da yake faruwa da ita. ");
INSERT INTO hausa_vpl VALUES ("ET2_12","018_2_12","EST","2","12","12","Kafin a kai kowace yarinya wurin Sarki Zerzes, sai ta gama watanni goma sha biyu cif ana yin mata kwalliyar da aka tsara, akan ɗauki watanni shida ana shafa mata man mur, a ɗauki watanni shida kuma ana shafa mata man ƙanshi da kayan shafe-shafe. ");
INSERT INTO hausa_vpl VALUES ("ET2_13","018_2_13","EST","2","13","13","A kuma koya mata yadda za tă tafi wurin sarki. Aka ba ta duk abin da take so ta riƙe daga gidan matan kulle zuwa fadar sarki. ");
INSERT INTO hausa_vpl VALUES ("ET2_14","018_2_14","EST","2","14","14","Da yamma za tă tafi can, da safe kuma ta dawo wani ɓangaren gidan matan kullen da yake a ƙarƙashin kulawar Sha’ashgaz, bābā na sarki, wanda yake lura da ƙwarƙwarai. Ba ta dawowa wurin sarki sai in ta gamshe shi, sai ya kuma kira ta da suna. ");
INSERT INTO hausa_vpl VALUES ("ET2_15","018_2_15","EST","2","15","15","Sa’ad da lokaci ya yi da Esta (yarinyar da Mordekai ya ɗauka tamƙar ’yarsa, ’yar kawunsa Abihayil) za tă shiga wurin sarki, ba tă nemi a ba ta kome ba in ban da abin da Hegai, bābān sarki mai lura da gidan matan kulle, ya ba da shawara. Esta kuwa ta sami tagomashin kowa da ya ganta. ");
INSERT INTO hausa_vpl VALUES ("ET2_16","018_2_16","EST","2","16","16","Aka kai Esta wurin Sarki Zerzes a mazaunin sarauta a wata na goma, watan Tebet, a shekara ta bakwai ta mulkinsa. ");
INSERT INTO hausa_vpl VALUES ("ET2_17","018_2_17","EST","2","17","17","To, sarki ya so Esta fiye da duk sauran matan, ta kuma sami tagomashinsa da kuma yardarsa fiye da duk sauran budurwai. Saboda haka ya sa rawanin sarauta a kanta, ya kuma mai da ita sarauniya a maimakon Bashti. ");
INSERT INTO hausa_vpl VALUES ("ET2_18","018_2_18","EST","2","18","18","Sarki kuwa ya yi ƙasaitacciyar liyafa, liyafar Esta, wa dukan hakimansa da shugabannin masarautarsa. Ya yi shelar hutu ko’ina a larduna, ya kuma raba kyautai a yalwace irin na sarauta. ");
INSERT INTO hausa_vpl VALUES ("ET2_19","018_2_19","EST","2","19","19","Sa’ad da aka tara budurwai karo na biyu, Mordekai kuwa yana zama a bakin ƙofar sarki. ");
INSERT INTO hausa_vpl VALUES ("ET2_20","018_2_20","EST","2","20","20","Amma Esta ta ɓoye asalin iyalinta da na al’ummarta yadda Mordekai ya ce ta yi, gama ta ci gaba da bin umarnan Mordekai yadda take yi sa’ad da yake renonta. ");
INSERT INTO hausa_vpl VALUES ("ET2_21","018_2_21","EST","2","21","21","Sa’ad da Mordekai yake zaune a bakin ƙofar sarki, sai Bigtana da Teresh, biyu daga cikin hafsoshin sarki masu gadin ƙofar shiga, suka yi fushi, suka kuma ƙulla su kashe sarki Zerzes. ");
INSERT INTO hausa_vpl VALUES ("ET2_22","018_2_22","EST","2","22","22","Mordekai kuwa ya sami labarin makircin, ya kuma faɗa wa Sarauniya Esta, wadda ta faɗa wa sarki, ta kuma nuna masa cewa Mordekai ne ya ji. ");
INSERT INTO hausa_vpl VALUES ("ET2_23","018_2_23","EST","2","23","23","Sa’ad da aka bincika labarin aka kuma iske gaskiya ne, sai aka rataye hafsoshin nan biyu a wurin rataye mai laifi. Aka rubuta dukan wannan a cikin littafin tarihi a gaban sarki. ");
INSERT INTO hausa_vpl VALUES ("ET3_1","018_3_1","EST","3","1","1","Bayan waɗannan al’amura, sai Sarki Zerzes ya girmama Haman ɗan Hammedata, mutumin Agag, ya ɗaukaka shi, ya kuma ba shi matsayi mafi girma fiye da na dukan sauran hakiman. ");
INSERT INTO hausa_vpl VALUES ("ET3_2","018_3_2","EST","3","2","2","Dukan masu hidimar da suke a ƙofar sarki suka riƙa durƙusa suna ba wa Haman girma, gama sarki ya ba da umarni a yi masa haka. Amma Mordekai bai durƙusa ya ba shi girma ba. ");
INSERT INTO hausa_vpl VALUES ("ET3_3","018_3_3","EST","3","3","3","Sa’an nan masu hidimar da suke a ƙofar sarki suka tambaye Mordekai, “Me ya sa ba ka yin biyayya da umarnin sarki?” ");
INSERT INTO hausa_vpl VALUES ("ET3_4","018_3_4","EST","3","4","4","Kowace rana suna masa magana, amma ya ƙi yă yi. Saboda haka, suka faɗa wa Haman game da wannan don su ga ko za a jure da halin Mordekai, gama ya faɗa musu cewa shi mutumin Yahuda ne. ");
INSERT INTO hausa_vpl VALUES ("ET3_5","018_3_5","EST","3","5","5","Sa’ad da Haman ya ga cewa Mordekai ba ya durƙusa ko yă girmama shi, sai ya fusata. ");
INSERT INTO hausa_vpl VALUES ("ET3_6","018_3_6","EST","3","6","6","Da yake an faɗa masa asalin Mordekai, sai ya ga a kashe Mordekai kaɗai ba zai biya masa bukata ba. A maimakon haka, Haman ya nemi hanya a hallaka dukan mutanen Mordekai, wato, Yahudawa, a ko’ina a dukan masarautar Zerzes. ");
INSERT INTO hausa_vpl VALUES ("ET3_7","018_3_7","EST","3","7","7","A shekara ta goma sha biyu ta Sarki Zerzes, a wata na farko, watan Nisan, sai suka jefa fur (wato, ƙuri’a) a gaban Haman don a zaɓi rana da watan da zai dace da ƙulle-ƙullen. Sai ƙuri’a ta fāɗa a kan wata na goma sha biyu, wato, watan Adar. ");
INSERT INTO hausa_vpl VALUES ("ET3_8","018_3_8","EST","3","8","8","Sai Haman ya ce wa Sarki Zerzes, “Akwai waɗansu mutanen da suke a warwatse, sun kuma bazu a cikin mutane cikin dukan lardunan masarautarka, waɗanda al’adunsu sun yi dabam da na dukan sauran mutane. Mutanen nan ba sa biyayya da dokokin sarki; ba zai yi wa sarki kyau a jure su ba. ");
INSERT INTO hausa_vpl VALUES ("ET3_9","018_3_9","EST","3","9","9","In ya gamshi sarki, bari a yi doka, don a hallaka su, zan kuma sa talenti dubu goma na azurfa a cikin ma’ajin fada saboda mutanen da suka aikata wannan sha’ani.” ");
INSERT INTO hausa_vpl VALUES ("ET3_10","018_3_10","EST","3","10","10","Saboda haka sarki ya zare zoben hatimi daga yatsarsa, ya ba wa Haman ɗan Hammedata, mutumin Agag, abokin gāban Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("ET3_11","018_3_11","EST","3","11","11","Sarki ya ce wa Haman, “Ka riƙe kuɗin, ka kuma yi da mutanen yadda ka ga dama.” ");
INSERT INTO hausa_vpl VALUES ("ET3_12","018_3_12","EST","3","12","12","Sa’an nan aka kira magatakardun sarki a rana ta goma sha uku na wata na fari. Suka rubuta dukan umarnin Haman a irin rubutun kowane lardi, kuma cikin harshen kowane mutane, zuwa ga shugabannin mahukuntai na sarki, da gwamnonin larduna dabam-dabam, da kuma hakiman mutane dabam-dabam. Aka rubuta waɗannan a sunan Sarki Zerzes da kansa, aka kuma hatimce da zobensa. ");
INSERT INTO hausa_vpl VALUES ("ET3_13","018_3_13","EST","3","13","13","Aka aika ’yan-kada-tă-kwana da saƙoni zuwa dukan lardunan sarki da umarni a hallaka, a karkashe, a kuma kawar da dukan Yahudawa, manya da ƙanana, mata da yara, a kuma washe kayayyakinsu. ");
INSERT INTO hausa_vpl VALUES ("ET3_14","018_3_14","EST","3","14","14","Za a ba da kofin rubutun a matsayin doka a kowane lardi, a kuma sanar da mutanen kowace al’umma, domin su zauna da shiri don wannan rana. ");
INSERT INTO hausa_vpl VALUES ("ET3_15","018_3_15","EST","3","15","15","Bisa ga umarnin sarki, sai ’yan-kada-tă-kwana, suka tafi da sauri. Aka ba da umarni a mazaunin masarauta da yake a Shusha. Sai Sarki da Haman suka zauna don su sha, amma birnin Shusha ya ruɗe. ");
INSERT INTO hausa_vpl VALUES ("ET4_1","018_4_1","EST","4","1","1","Sa’ad da Mordekai ya sami labari game da dukan abin da aka yi, sai ya yayyage rigunansa, ya sanya tsummokin makoki, ya zuba toka a kā, ya kuma shiga ciki birni yana kuka mai zafi da ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("ET4_2","018_4_2","EST","4","2","2","Amma ya kai bakin ƙofar sarki ne kawai, gama ba a yarda wani sanye da tsummokin makoki yă shiga cikin birni ba. ");
INSERT INTO hausa_vpl VALUES ("ET4_3","018_4_3","EST","4","3","3","Aka yi makoki sosai da azumi, da kuka mai zafi a cikin Yahudawa a kowane lardin da aka kai doka da kuma umarnin sarki. Mutane da yawa suka kwanta a cikin tsummokin makoki da kuma toka. ");
INSERT INTO hausa_vpl VALUES ("ET4_4","018_4_4","EST","4","4","4","Sa’ad da bayi da bābānnin Esta suka zo suka faɗa mata game da Mordekai, sai ta damu ƙwarai. Ta aika masa da riguna domin yă sa a maimakon tsummokin makoki, amma ya ƙi. ");
INSERT INTO hausa_vpl VALUES ("ET4_5","018_4_5","EST","4","5","5","Sai Esta ta kira Hatak, ɗaya daga cikin bābānnin sarkin da aka ba shi aikin lura da ita, ta umarce shi yă yi tambaya me ke damun Mordekai da kuma me ya jawo haka. ");
INSERT INTO hausa_vpl VALUES ("ET4_6","018_4_6","EST","4","6","6","Saboda haka Hatak ya tafi wurin Mordekai a dandalin birni, a gaban ƙofar sarki. ");
INSERT INTO hausa_vpl VALUES ("ET4_7","018_4_7","EST","4","7","7","Mordekai ya faɗa masa duk abin da ya faru da shi, haɗe da yawan kuɗin da Haman ya yi alkawari zai zuba a ma’ajin fada don a hallaka Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("ET4_8","018_4_8","EST","4","8","8","Ya kuma ba shi kofi na rubutaccen doka na kakkaɓe su, wanda aka wallafa a Shusha don yă nuna wa Esta, yă bayyana mata. Mordekai ya faɗa wa Hatak yă iza ta tă tafi gaban sarki domin tă yi roƙo don jinƙai, tă kuma roƙe shi saboda mutanenta. ");
INSERT INTO hausa_vpl VALUES ("ET4_9","018_4_9","EST","4","9","9","Hatak ya koma ya ba wa Esta rahoton abin da Mordekai ya faɗa. ");
INSERT INTO hausa_vpl VALUES ("ET4_10","018_4_10","EST","4","10","10","Sa’an nan Esta ta umarce Hatak yă ce wa Mordekai, ");
INSERT INTO hausa_vpl VALUES ("ET4_11","018_4_11","EST","4","11","11","“Dukan hafsoshin sarki da mutanen lardunan sarki sun san cewa duk wanda ya tafi wurin sarki a shirayi na ciki, mace ko namiji, ba tare da an kira shi ba, doka ɗaya ce take kan mutum, wato, kisa. Abu guda kawai da ya sha bamban shi ne sai wanda sarki ya miƙa wa sandan sarauta na zinariya don yă rayu. Kwana talatin ke nan ba a kira ni in tafi wurin sarki ba.” ");
INSERT INTO hausa_vpl VALUES ("ET4_12","018_4_12","EST","4","12","12","Sa’ad da aka kai wa Mordekai rahoton maganan Esta, ");
INSERT INTO hausa_vpl VALUES ("ET4_13","018_4_13","EST","4","13","13","sai ya mayar da wannan amsa wa Esta cewa, “Kada ki yi tsammani cewa don kina a cikin gidan sarki, ke kaɗai cikin dukan Yahudawa za ki tsira. ");
INSERT INTO hausa_vpl VALUES ("ET4_14","018_4_14","EST","4","14","14","Gama in kin yi shiru a wannan lokaci, taimako da ceto zai zo daga wani wuri saboda Yahudawa, amma ke da gidanki za ku hallaka. Wa ya san ko saboda irin wannan lokaci ne kika sami wannan muƙami?” ");
INSERT INTO hausa_vpl VALUES ("ET4_15","018_4_15","EST","4","15","15","Sai Esta ta aika da wannan amsa ga Mordekai cewa, ");
INSERT INTO hausa_vpl VALUES ("ET4_16","018_4_16","EST","4","16","16","“Ka tafi, ka tattara dukan Yahudawan da suke Shusha, ku yi azumi saboda ni. Kada ku ci ko ku sha, dare da rana har kwana uku. Ni kuwa da bayina za mu yi azumi yadda kuke yi. Idan aka yi haka, zan tafi wurin sarki, ko da yake wannan karya doka ce. Idan na hallaka, to, na hallaka.” ");
INSERT INTO hausa_vpl VALUES ("ET4_17","018_4_17","EST","4","17","17","Saboda haka, Mordekai ya tafi, ya aikata dukan umarnan Esta. ");
INSERT INTO hausa_vpl VALUES ("ET5_1","018_5_1","EST","5","1","1","A rana ta uku, Esta ta sanya rigunanta na sarauta, ta tafi ta tsaya a harabar fada, a gaban zaure sarki. Sarki yana zaune a kan gadon sarautarsa a zauren, yana fuskantar ƙofar shiga. ");
INSERT INTO hausa_vpl VALUES ("ET5_2","018_5_2","EST","5","2","2","Sa’ad da ya ga Sarauniya Esta tsaye a harabar, sai ya ji daɗin ganinta, ya miƙa mata sandan sarauta na zinariya da take hannunsa. Sai Esta ta matsa kusa ta taɓa kan sandan. ");
INSERT INTO hausa_vpl VALUES ("ET5_3","018_5_3","EST","5","3","3","Sai sarki ya ce mata, “Me kike so, Sarauniya Esta? Mene ne roƙonki? Kai, ko rabin masarautata ce, za a ba ki.” ");
INSERT INTO hausa_vpl VALUES ("ET5_4","018_5_4","EST","5","4","4","Esta ta ce, “In ya gamshi sarki, bari sarki, tare da Haman su zo wurin liyafar da na shirya wa sarki yau.” ");
INSERT INTO hausa_vpl VALUES ("ET5_5","018_5_5","EST","5","5","5","Sai sarki ya ce, “Maza a kawo Haman don mu yi abin da Esta ta roƙa.” Saboda haka, sarki da Haman suka tafi liyafar da Esta ta shirya. ");
INSERT INTO hausa_vpl VALUES ("ET5_6","018_5_6","EST","5","6","6","Yayinda suke shan ruwan inabi, sarki ya sāke ce wa Esta, “Yanzu, mece ce bukatarki? Za a biya miki shi. Kuma mene ne roƙonki? Kai, ko rabin masarautata ce, za a ba ki.” ");
INSERT INTO hausa_vpl VALUES ("ET5_7","018_5_7","EST","5","7","7","Esta ta amsa ta ce, “Bukatata da kuma roƙona shi ne, ");
INSERT INTO hausa_vpl VALUES ("ET5_8","018_5_8","EST","5","8","8","in na sami tagomashi a wurin sarki, in kuma sarki ya yarda yă biya mini bukatata, yă kuma ji roƙona, bari sarki da Haman su zo gobe wurin liyafar da zan shirya musu. Sa’an nan zan amsa tambayar sarki.” ");
INSERT INTO hausa_vpl VALUES ("ET5_9","018_5_9","EST","5","9","9","Haman ya fita a ranan da murna, ya kuma ji daɗi. Amma sa’ad da ya ga Mordekai a bakin ƙofar sarki, ya kuma lura cewa bai tashi, ko yă nuna bangirma a gabansa ba, sai ya cika da fushi. ");
INSERT INTO hausa_vpl VALUES ("ET5_10","018_5_10","EST","5","10","10","Duk da haka, Haman ya cije, ya tafi gida. Sai ya kira abokansa da kuma matarsa, Zeresh, ");
INSERT INTO hausa_vpl VALUES ("ET5_11","018_5_11","EST","5","11","11","ya yi ta taƙama game da ɗumbun wadatarsa, da yawan ’ya’yansa maza, da dukan yadda sarki ya girmama shi, ya kuma ɗaga shi bisan sauran hakimai da shugabanni. ");
INSERT INTO hausa_vpl VALUES ("ET5_12","018_5_12","EST","5","12","12","Haman ya ƙara da cewa, “Ba duka ke nan ba, kai, ni ne kaɗai mutumin da Sarauniya Esta ta gayyata yă tafi tare da sarki zuwa liyafar da ta shirya. Ta sāke gayyace ni tare da sarki gobe. ");
INSERT INTO hausa_vpl VALUES ("ET5_13","018_5_13","EST","5","13","13","Amma dukan wannan bai biya mini bukata ba, muddin ina ganin wannan mutumin Yahudan nan Mordekai, yana zama a bakin ƙofar sarki.” ");
INSERT INTO hausa_vpl VALUES ("ET5_14","018_5_14","EST","5","14","14","Matarsa Zeresh, da dukan abokansa suka ce masa, “Ka sa a gina wurin rataye mai laifi, mai tsawo, ƙafa saba’in da biyar, da safe kuwa ka ce wa sarki a rataye Mordekai a kansa. Sa’an nan ka tafi cin abincin dare tare da sarki da murna.” Wannan shawarar ta faranta wa Haman rai, ya kuma sa aka gina wurin rataye mai laifi. ");
INSERT INTO hausa_vpl VALUES ("ET6_1","018_6_1","EST","6","1","1","A daren nan, sarki bai iya barci ba, saboda haka ya ba da umarni a kawo, a kuma karanta masa littafin tarihi na shekara-shekara, da rubutaccen labarin mulkinsa. ");
INSERT INTO hausa_vpl VALUES ("ET6_2","018_6_2","EST","6","2","2","Aka tarar, a rubuce a ciki, cewa Mordekai ya tone ƙulle-ƙullen Bigtana da Teresh, biyu daga hafsoshin sarki, waɗanda suke tsaron mashigin ƙofa, waɗanda suka ƙulla su kashe Sarki Zerzes. ");
INSERT INTO hausa_vpl VALUES ("ET6_3","018_6_3","EST","6","3","3","Sarki ya ce, “Wace girma da daraja ce aka ba wa Mordekai saboda wannan?” Masu hidimarsa suka ce, “Ba a yi masa wani abu ba.” ");
INSERT INTO hausa_vpl VALUES ("ET6_4","018_6_4","EST","6","4","4","Sarki ya ce, “Wa yake a haraba?” Daidai lokacin kuwa Haman ya shigo harabar waje na fada don yă yi magana da sarki a kan a rataye Mordekai a wurin rataye mai laifin da ya shirya. ");
INSERT INTO hausa_vpl VALUES ("ET6_5","018_6_5","EST","6","5","5","Masu yi wa sarki hidima, suka amsa, “Haman yana tsaye a haraba.” Sarki ya umarta, “A kawo shi ciki.” ");
INSERT INTO hausa_vpl VALUES ("ET6_6","018_6_6","EST","6","6","6","Sa’an nan Haman ya shigo, sai sarki ya ce masa, “Me ya kamata a yi wa mutumin da sarki yake jin daɗi yă girmama?” Haman dai ya yi tunani a ransa ya ce, “Wane ne sarki zai girmama in ba ni ba?” ");
INSERT INTO hausa_vpl VALUES ("ET6_7","018_6_7","EST","6","7","7","Sai ya amsa wa sarki cewa, “Saboda mutumin da sarki yake jin daɗi yă girmama, ");
INSERT INTO hausa_vpl VALUES ("ET6_8","018_6_8","EST","6","8","8","bari a kawo rigar sarautar da sarki ya taɓa sawa, da kuma dokin da sarki ya taɓa hawa, wanda aka sa kambin sarauta a kai. ");
INSERT INTO hausa_vpl VALUES ("ET6_9","018_6_9","EST","6","9","9","Sa’an nan, bari a ba da rigar da kuma dokin wa ɗaya daga cikin manyan sarakuna mafi kirki na sarki. Bari shi kuma yă sa wannan riga wa mutumin da sarki yake jin daɗi yă girmama, a kuma bi da shi a bisan doki ko’ina a titunan birni, ana shela a gabansa ana cewa, ‘Wannan shi ne abin da ake yin wa mutumin da sarki yake jin daɗi yă girmama!’ ” ");
INSERT INTO hausa_vpl VALUES ("ET6_10","018_6_10","EST","6","10","10","Sarki ya umarci Haman ya ce, “Tafi yanzu ka karɓi rigar da dokin, ka kuma yi yadda ka shawarta wa Mordekai, mutumin Yahudan nan, wanda yake zama a bakin ƙofar sarki. Kada ka kāsa yin kome daga cikin abin da ka faɗa.” ");
INSERT INTO hausa_vpl VALUES ("ET6_11","018_6_11","EST","6","11","11","Saboda haka, Haman ya karɓo rigar da dokin. Ya sa wa Mordekai rigar, ya kuma bi da shi a kan doki ko’ina a titunan birnin, yana shela a gabansa yana cewa, “Wannan shi ne abin da ake yi wa mutumin da sarki yake jin daɗi yă girmama!” ");
INSERT INTO hausa_vpl VALUES ("ET6_12","018_6_12","EST","6","12","12","Daga baya, Mordekai ya dawo zuwa ƙofar sarki. Amma Haman ya ruga gida, kansa a rufe, saboda baƙin ciki. ");
INSERT INTO hausa_vpl VALUES ("ET6_13","018_6_13","EST","6","13","13","Ya je ya faɗa wa matarsa Zeresh, da dukan abokansa, me ya same shi. Masu ba shi shawara, da matarsa Zeresh, suka ce masa, “Idan Mordekai, wanda ka fara fāɗuwa a gabansa, daga zuriyar Yahudawa yake, to, ba za ka yi nasara a kansa ba, tabbatacce za ka fāɗi a gabansa!” ");
INSERT INTO hausa_vpl VALUES ("ET6_14","018_6_14","EST","6","14","14","Suna cikin magana da shi ke nan, sai ga bābānnin sarki, suka iso suka kuma hanzarta da Haman zuwa liyafar da Esta ta shirya. ");
INSERT INTO hausa_vpl VALUES ("ET7_1","018_7_1","EST","7","1","1","Saboda haka sarki da Haman suka tafi cin abinci wurin sarauniya Esta. ");
INSERT INTO hausa_vpl VALUES ("ET7_2","018_7_2","EST","7","2","2","Yayinda suke shan ruwan inabi a rana ta biyun nan, sai sarki ya sāke tambaya, “Sarauniya Esta, me kike so? Za a ba ki. Mene ne roƙonki? Ko da rabin masarautata ne, za a ba ki.” ");
INSERT INTO hausa_vpl VALUES ("ET7_3","018_7_3","EST","7","3","3","Sai Sarauniya Esta ta amsa ta ce, “In na sami tagomashi a wurinka, ya sarki, in kuma mai girma ya yarda, a bar ni da raina, wannan shi ne roƙona. Ka kuma sa kada a kashe mutanena, wannan ita ce bukata. ");
INSERT INTO hausa_vpl VALUES ("ET7_4","018_7_4","EST","7","4","4","Gama an sayar da ni da mutanena don a hallaka, a karkashe mu, a kuma ƙi mu. Da a ce an sayar da mu kamar bayi maza da mata ne, da na yi shiru, domin wannan zai zama abin da bai taka kara ya karye ba, har da za a dami sarki a kai.” ");
INSERT INTO hausa_vpl VALUES ("ET7_5","018_7_5","EST","7","5","5","Sarki Zerzes ya tambayi Sarauniya Esta ya ce, “Wane ne shi? Ina mutumin da ya yi ƙarfin halin yin wannan karambani?” ");
INSERT INTO hausa_vpl VALUES ("ET7_6","018_7_6","EST","7","6","6","Esta ta ce, “Maƙiyi da abokin gāban, shi ne wannan mugun Haman.” Sai Haman ya tsorota a gaban sarki da sarauniya. ");
INSERT INTO hausa_vpl VALUES ("ET7_7","018_7_7","EST","7","7","7","Sarki ya tashi cikin fushi, ya bar ruwan inabinsa, ya fita zuwa cikin lambun fada. Amma da Haman ya gane cewa sarki ya riga ya yanke shawara a kan ƙaddararsa, ya dakata domin yă roƙi sarauniya Esta saboda ransa. ");
INSERT INTO hausa_vpl VALUES ("ET7_8","018_7_8","EST","7","8","8","Sarki yana dawowa daga lambun fada zuwa babban zauren liyafan ke nan, sai ga Haman ya fāɗi a kan shimfiɗar da Esta take zaune. Sarki ya tā da murya da ƙarfi ya ce, “Har ma zai ci mutuncin sarauniya yayinda take tare da ni a cikin gida?” Sarki bai ma rufe baki ba, sai bayin sarki suka rufe fuskar Haman. ");
INSERT INTO hausa_vpl VALUES ("ET7_9","018_7_9","EST","7","9","9","Sai Harbona, ɗaya daga cikin bābānni masu yi wa sarki hidima ya ce, “Akwai wurin rataye mai laifi da tsayinsa ya kai ƙafa saba’in da biyar yana nan tsaye kusa da gidan Haman. Ya gyara shi ne domin a rataye Mordekai, wanda ya yi cece sarki wanda ya tone makircin masu niyya su hallaka sarki.” Sai sarki ya ce, “Ku rataye shi a kansa!” ");
INSERT INTO hausa_vpl VALUES ("ET7_10","018_7_10","EST","7","10","10","Saboda haka suka rataye Haman a kan wurin rataye mai laifin da shi Haman ya shirya saboda Mordekai. Sa’an nan sarki ya huce. ");
INSERT INTO hausa_vpl VALUES ("ET8_1","018_8_1","EST","8","1","1","A wannan rana, Sarki Zerzes ya ba wa Esta mallakar Haman, abokin gāban Yahudawa. Mordekai kuma ya zo gaban sarki, gama Esta ta faɗa yadda ta haɗa dangi da shi. ");
INSERT INTO hausa_vpl VALUES ("ET8_2","018_8_2","EST","8","2","2","Sarki ya cire zobensa na hatimi, wanda ya karɓo daga Haman ya ba Mordekai. Esta kuma ta naɗa shi a kan mallakar Haman. ");
INSERT INTO hausa_vpl VALUES ("ET8_3","018_8_3","EST","8","3","3","Esta ta sāke roƙon sarki, ta fāɗi a ƙafafunsa tana kuka. Ta roƙe shi yă kawo ƙarshen mugun shirin nan na Haman, mutumin Agag; wanda ya shirya a kan Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("ET8_4","018_8_4","EST","8","4","4","Sai sarki ya miƙa wa Esta sandan sarauta na zinariya, ta kuwa tashi ta tsaya a gabansa. ");
INSERT INTO hausa_vpl VALUES ("ET8_5","018_8_5","EST","8","5","5","Ta ce, “In sarki ya yarda, in kuma na sami tagomashi daga gare shi, idan kuma ya gamshe shi yă yi abin da yake daidai, idan yana jin daɗina, bari a rubuta umarni a soke hukuncin saƙonin da Haman ɗan Hammedata, mutumin Agag, ya shirya ya kuma rubuta domin a hallaka Yahudawa a dukan lardunan sarki. ");
INSERT INTO hausa_vpl VALUES ("ET8_6","018_8_6","EST","8","6","6","Gama yaya zan jure da ganin masifa ta faɗa a kan mutanena? Yaya zan jure in ga an hallaka iyalina?” ");
INSERT INTO hausa_vpl VALUES ("ET8_7","018_8_7","EST","8","7","7","Sarki Zerzes ya amsa wa Esta da Mordekai mutumin Yahuda, “Domin Haman ya kai wa Yahudawa hari, na ba da mallakarsa ga Esta, an kuma rataye shi a wurin rataye mai laifi. ");
INSERT INTO hausa_vpl VALUES ("ET8_8","018_8_8","EST","8","8","8","Yanzu ku rubuta wata doka, a sunan sarki, a madadin Yahudawa, yadda kuka ga ya fi kyau ku kuma hatimce ta da zoben hatimin sarki, gama babu takardar da aka rubuta da sunan sarki, aka kuma hatimce da zobensa da za a iya sokewa.” ");
INSERT INTO hausa_vpl VALUES ("ET8_9","018_8_9","EST","8","9","9","Nan da nan aka kira magatakardun fada, a ranar ashirin da uku ga watan uku, wato, watan Siban. Suka rubuta dukan umarnan Mordekai ga Yahudawa, da kuma ga shugabanni, da gwamnoni, da hakiman larduna 127 tun daga Indiya har zuwa Kush. Aka rubuta waɗannan umarnan a rubutun kowane lardi, da kuma cikin harshen kowane mutane. Aka kuma rubuta ga Yahudawa a rubutunsu da harshensu. ");
INSERT INTO hausa_vpl VALUES ("ET8_10","018_8_10","EST","8","10","10","Mordekai ya yi rubutu da sunan Sarki Zerzes, ya hatimce saƙonin da zoben hatimin sarki, ya kuma aika da su ta hannun masu ’yan aika a kan dawakai, waɗanda sukan hau dawakai masu gudu sosai, da aka yi kiwonsu musamman saboda sarki. ");
INSERT INTO hausa_vpl VALUES ("ET8_11","018_8_11","EST","8","11","11","Dokar sarki ta ba wa Yahudawa a kowace birni izini su taru, su kuma kāre kansu, domin su hallaka, su kashe, su kuma hallaka kowace ƙungiyar mayaƙa, na kowace ƙasa, ko lardi, da wataƙila za su kai musu, da matansu, da yaransu hari; su kuma washe mallakar abokan gābansu. ");
INSERT INTO hausa_vpl VALUES ("ET8_12","018_8_12","EST","8","12","12","Ranar da aka shirya domin Yahudawa su yi wannan a dukan lardunan Sarki Zerzes, ita ce ranar goma sha uku ga watan goma sha biyu, wato, watan Adar. ");
INSERT INTO hausa_vpl VALUES ("ET8_13","018_8_13","EST","8","13","13","Za a ba da kofi na rubutacciyar dokar a matsayin ƙa’ida a kowane lardi, a kuma sanar wa mutanen kowace ƙasa, domin Yahudawa su zauna da shiri a ranar, domin su ɗau fansa a kan maƙiyansu. ");
INSERT INTO hausa_vpl VALUES ("ET8_14","018_8_14","EST","8","14","14","’Yan aikan, a kan dawakan fada, suka fita a guje, umarnin sarki yana iza su. Aka kuma ba da dokar a mazaunin masarauta wadda take Shusha. ");
INSERT INTO hausa_vpl VALUES ("ET8_15","018_8_15","EST","8","15","15","Mordekai kuwa ya fita a gaban sarki da rigunan sarauta, masu ruwan shuɗi, da fari, da babban kambi na zinariya, da alkyabba ta lilin mai ruwan shunayya. Aka yi sowa don murna a birnin Shusha. ");
INSERT INTO hausa_vpl VALUES ("ET8_16","018_8_16","EST","8","16","16","Ga Yahudawa kuwa, lokaci ne na murna da farin ciki, da jin daɗi da bangirma. ");
INSERT INTO hausa_vpl VALUES ("ET8_17","018_8_17","EST","8","17","17","A kowane lardi da kowace birni, ko’ina da dokar sarki ta kai, aka yi farin ciki a cikin Yahudawa, cike da bukukkuwa. Yawan mutane da waɗansu ƙasashe suka zama Yahudawa, don tsoron Yahudawa ya kama su. ");
INSERT INTO hausa_vpl VALUES ("ET9_1","018_9_1","EST","9","1","1","A rana ta goma sha uku na watan goma sha biyu, wato, watan Adar ne za a aiwatar da dokar da sarki ya umarta. A wannan rana, abokan gāban Yahudawa suka sa zuciya za su sha ƙarfinsu, amma yanzu Zerzes ya canja, Yahudawa kuma suka yi galiba a bisa waɗanda suka ƙi jininsu. ");
INSERT INTO hausa_vpl VALUES ("ET9_2","018_9_2","EST","9","2","2","Yahudawa suka tattaru a cikin biranensu a dukan lardunan Sarki Zerzes don su kai wa waɗanda suka nemi a hallaka su hari. Babu wanda ya tasar musu domin mutanen dukan sauran al’ummai sun jin tsoronsu. ");
INSERT INTO hausa_vpl VALUES ("ET9_3","018_9_3","EST","9","3","3","Dukan sarakuna larduna, da hakimai, da gwamnoni da kuma ma’aikatan sarki suka taimaki Yahudawa, domin tsoron Mordekai ya kama su. ");
INSERT INTO hausa_vpl VALUES ("ET9_4","018_9_4","EST","9","4","4","Mordekai babban mutum ne a fada, sunansa ya kai ko’ina a lardunan, ikonsa ya yi ta ƙasaita gaba-gaba. ");
INSERT INTO hausa_vpl VALUES ("ET9_5","018_9_5","EST","9","5","5","Yahudawa suka karkashe dukan abokan gābansu da takobi, suka karkashe waɗanda suka ƙi jininsu, suka kuma hallaka su yadda suka ga dama. ");
INSERT INTO hausa_vpl VALUES ("ET9_6","018_9_6","EST","9","6","6","A mazaunin masarautar a Shusha, Yahudawa suka karkashe, suka kuma hallaka mutum ɗari biyar. ");
INSERT INTO hausa_vpl VALUES ("ET9_7","018_9_7","EST","9","7","7","Suka kuma kashe Farshandata, da Dalfon, da Asfata, ");
INSERT INTO hausa_vpl VALUES ("ET9_8","018_9_8","EST","9","8","8","da Forata, da Adaliya, da Aridata, ");
INSERT INTO hausa_vpl VALUES ("ET9_9","018_9_9","EST","9","9","9","da Farmashta, da Arisai, da Aridai da kuma Baizata, ");
INSERT INTO hausa_vpl VALUES ("ET9_10","018_9_10","EST","9","10","10","’ya’ya maza goma na Haman ɗan Hammedata, abokin gāban Yahudawa. Amma ba su taɓa dukiyarsu ba. ");
INSERT INTO hausa_vpl VALUES ("ET9_11","018_9_11","EST","9","11","11","A wannan rana, aka ba wa sarki rahoton yawan mutanen da aka kashe a mazaunin masarauta, a Shusha. ");
INSERT INTO hausa_vpl VALUES ("ET9_12","018_9_12","EST","9","12","12","Sarki ya ce wa Sarauniya Esta, “Yahudawa sun karkashe, suka kuma hallaka mutum ɗari biyar, da kuma ’ya’ya maza goma na Haman a mazaunin masarauta a Shusha. Me suka yi a sauran lardunan sarki? Yanzu kuma mene ne roƙonki? Za a ba ki. Mece ce bukatarki? Za a biya miki.” ");
INSERT INTO hausa_vpl VALUES ("ET9_13","018_9_13","EST","9","13","13","Esta ta ce, “In sarki ya yarda, yă ba wa Yahudawa da suke Shusha izini su aikata dokan nan gobe kuma, bari kuma a rataye ’ya’ya maza goma na Haman a kan gumagumai.” ");
INSERT INTO hausa_vpl VALUES ("ET9_14","018_9_14","EST","9","14","14","Sai sarki ya ba da umarni a yi haka ɗin. Aka ba da doka a Shusha, aka kuma rataye ’ya’ya maza goma na Haman. ");
INSERT INTO hausa_vpl VALUES ("ET9_15","018_9_15","EST","9","15","15","Yahudawan da suke Shusha suka taru a ran goma sha huɗu na watan Adar suka kuma karkashe mutum ɗari uku a Shusha, amma ba su taɓa dukiyarsu ba. ");
INSERT INTO hausa_vpl VALUES ("ET9_16","018_9_16","EST","9","16","16","Ana cikin haka, sai saura Yahudawa waɗanda suke lardunan sarki su ma suka taru domin su kāre kansu su kuma sami hutu daga abokan gābansu. Suka karkashe mutum dubu saba’in da biyar amma ba su taɓa dukiyarsu ba. ");
INSERT INTO hausa_vpl VALUES ("ET9_17","018_9_17","EST","9","17","17","Wannan ya faru a ran goma sha uku na watan Adar. A rana ta goma sha huɗu kuwa suka huta, suka kuma mai da ita ranar biki da kuma ta farin ciki. ");
INSERT INTO hausa_vpl VALUES ("ET9_18","018_9_18","EST","9","18","18","Amma Yahudawan da suke a Shusha suka taru a rana ta goma sha uku da ta sha huɗu, sa’an nan a rana ta goma sha biyar suka huta, suka kuma mai da ita ranar biki da ta farin ciki. ");
INSERT INTO hausa_vpl VALUES ("ET9_19","018_9_19","EST","9","19","19","Shi ya sa Yahudawan ƙauyuka, waɗanda suke zama a karkara, suke kiyaye rana ta goma sha huɗu ta watan Adar a matsayin ranar farin ciki da ta biki, ranar ba da kyautai ga juna. ");
INSERT INTO hausa_vpl VALUES ("ET9_20","018_9_20","EST","9","20","20","Sai Mordekai ya rubuta waɗannan abubuwa, ya kuma aika wasiƙu ga dukan Yahudawa ko’ina a lardunan Sarki Zerzes, na kusa da na nesa. ");
INSERT INTO hausa_vpl VALUES ("ET9_21","018_9_21","EST","9","21","21","Ya sa su yi bikin kowace shekara a ranaku goma sha huɗu da goma sha biyar na watan Adar ");
INSERT INTO hausa_vpl VALUES ("ET9_22","018_9_22","EST","9","22","22","a matsayin lokacin da Yahudawa suka sami huta daga abokan gābansu, da kuma a matsayin watan da aka mai da baƙin cikinsu ya zama farin ciki, makokinsu kuma ya zama ranar biki. Ya rubuta musu su kiyaye ranakun a matsayin ranakun biki da na farin ciki. Su kuma ba da kyautai na abinci ga juna, da kuma kyautai ga matalauta. ");
INSERT INTO hausa_vpl VALUES ("ET9_23","018_9_23","EST","9","23","23","Ta haka, Yahudawa suka yarda su ci gaba da bikin da suka fara, suna aikata abin da Mordekai ya rubuta musu. ");
INSERT INTO hausa_vpl VALUES ("ET9_24","018_9_24","EST","9","24","24","Haman ɗan Hammedata, mutumin Agag, abokin gāban dukan Yahudawa, ya ƙulla maƙarƙashiya game da Yahudawa, domin a hallaka su, ya kuma jefa fur (wato, ƙuri’a) don yă hallaka su. ");
INSERT INTO hausa_vpl VALUES ("ET9_25","018_9_25","EST","9","25","25","Amma sa’ad da sarki ya sami labarin maƙarƙashiyar, sai ya ba da umarnai a rubuce cewa mugun shirin da Haman ya ƙulla a kan Yahudawa yă komo kansa, kuma cewa a rataye shi da ’ya’yansa maza a kan gumagumai. ");
INSERT INTO hausa_vpl VALUES ("ET9_26","018_9_26","EST","9","26","26","(Saboda haka, aka kira ranakun nan Furim, daga kalma fur). Saboda dukan abin da aka rubuta cikin wannan wasiƙa da kuma abin da suka gani, da abin da ya same su. ");
INSERT INTO hausa_vpl VALUES ("ET9_27","018_9_27","EST","9","27","27","Yahudawa suka ɗauki nawayar kafa al’adar cewa su, da zuriyarsu, da dukan waɗanda suka haɗa hannun da su, za su kiyaye waɗannan kwanaki biyu, kowace shekara yadda aka tsara, a kuma lokacin da aka keɓe dominsu. ");
INSERT INTO hausa_vpl VALUES ("ET9_28","018_9_28","EST","9","28","28","Za a tuna, a kuma kiyaye waɗannan kwanaki a kowane zamani, cikin kowane iyali, da kuma cikin kowane lardi, da kowace birni. Kuma kada Yahudawa su fasa yin bikin waɗannan kwanakin Furim, ko su bar jikokinsu su manta da kiyaye waɗannan ranaku biyu. ");
INSERT INTO hausa_vpl VALUES ("ET9_29","018_9_29","EST","9","29","29","Saboda haka Sarauniya Esta, ’yar Abihayil, tare da Mordekai mutumin Yahuda, suka rubuta da cikakken iko, suka tabbatar da wannan wasiƙa ta biyu game da Furim. ");
INSERT INTO hausa_vpl VALUES ("ET9_30","018_9_30","EST","9","30","30","Mordekai kuwa ya aika da wasiƙu zuwa ga dukan Yahudawa cikin larduna 127 na masarautar Zerzes. Saƙon fatan alheri da na tabbaci, ");
INSERT INTO hausa_vpl VALUES ("ET9_31","018_9_31","EST","9","31","31","don a kafa waɗannan ranakun Furim a keɓaɓɓen lokacinsu, kamar yadda Mordekai mutumin Yahuda da Sarauniya Esta suka dokace su. Yadda kuma suka kafa wa kansu da zuriyarsu, game da lokutansu na azumi da makoki. ");
INSERT INTO hausa_vpl VALUES ("ET9_32","018_9_32","EST","9","32","32","Dokar Esta ta tabbatar da waɗannan umarnai game da Furim, aka kuma rubuta ta cikin tarihi. ");
INSERT INTO hausa_vpl VALUES ("ET10_1","018_10_1","EST","10","1","1","Sarki Zerzes ya sa a biya haraji a ko’ina a cikin daular, har zuwa ƙasashe masu nesa na bakin teku. ");
INSERT INTO hausa_vpl VALUES ("ET10_2","018_10_2","EST","10","2","2","Dukan ayyukan Sarki Zerzes masu iko da masu girma tare da cikakken rahoton girmama Mordekai wanda sarki ya yi masa, ba a rubuce suke a cikin littafin tarihin sarakunan Mediya da na Farisa ba? ");
INSERT INTO hausa_vpl VALUES ("ET10_3","018_10_3","EST","10","3","3","Mordekai mutumin Yahuda, shi ne na biyu a matsayi bayan Sarki Zerzes, mai farin ciki kuma a cikin Yahudawa, aka kuma ɗauke shi da martaba cikin ’yan’uwansa Yahudawa. Gama ya yi aiki don kyautatawar mutanensa, ya kuma yi magana don a kyautata rayuwar dukan Yahudawa.");
INSERT INTO hausa_vpl VALUES ("JB1_1","019_1_1","JOB","1","1","1","A ƙasar Uz akwai wani mutum mai suna Ayuba. Mutum ne marar laifi kuma mai adalci; yana tsoron Allah, ba ruwansa da mugunta. ");
INSERT INTO hausa_vpl VALUES ("JB1_2","019_1_2","JOB","1","2","2","Yana da ’ya’ya maza bakwai da ’yan mata uku, ");
INSERT INTO hausa_vpl VALUES ("JB1_3","019_1_3","JOB","1","3","3","yana da tumaki dubu bakwai, raƙuma dubu uku, shanu ɗari biyar, da jakuna ɗari biyar, yana kuma da masu yi masa aiki da yawa. A ƙasar Gabas ba wani kamar sa. ");
INSERT INTO hausa_vpl VALUES ("JB1_4","019_1_4","JOB","1","4","4","’Ya’yansa maza sukan yi biki a gidajensu, wannan yă yi yă ba wancan, sai su kira ’yan’uwansu mata ukun su ci, su sha tare. ");
INSERT INTO hausa_vpl VALUES ("JB1_5","019_1_5","JOB","1","5","5","Bayan lokacin bikin ya wuce, sai Ayuba yă aika su zo don yă tsarkake su. Tun da sassafe zai miƙa hadaya ta ƙonawa domin kowannensu, don yana tunani cewa, “Mai yiwuwa ’ya’yana sun yi wa Allah zunubi, ko sun la’anta shi a cikin zuciyarsu.” Haka Ayuba ya saba yi. ");
INSERT INTO hausa_vpl VALUES ("JB1_6","019_1_6","JOB","1","6","6","Wata rana mala’iku suka kawo kansu gaban Ubangiji, Shaiɗan shi ma ya zo tare da su. ");
INSERT INTO hausa_vpl VALUES ("JB1_7","019_1_7","JOB","1","7","7","Ubangiji ya ce wa Shaiɗan, “Daga ina ka fito?” Shaiɗan ya amsa wa Ubangiji ya ce, “Daga yawo a duniya ina kai da kawowa a cikinta.” ");
INSERT INTO hausa_vpl VALUES ("JB1_8","019_1_8","JOB","1","8","8","Sai Ubangiji ya ce wa Shaiɗan, “Ko ka ga bawana Ayuba? A cikin duniya babu wani kamar sa; shi marar laifi ne, adali kuma, mutum ne mai tsoron Allah, ba ruwansa da mugunta.” ");
INSERT INTO hausa_vpl VALUES ("JB1_9","019_1_9","JOB","1","9","9","Sai Shaiɗan ya amsa ya ce, “Haka kawai Ayuba yake tsoron Allah? ");
INSERT INTO hausa_vpl VALUES ("JB1_10","019_1_10","JOB","1","10","10","Ba ka kāre shi da iyalinsa gaba ɗaya da duk mallakarsa ba? Ka Albarkaci ayyukan hannunsa yadda dabbobinsa duk sun cika ko’ina. ");
INSERT INTO hausa_vpl VALUES ("JB1_11","019_1_11","JOB","1","11","11","Ka ɗan miƙa hannunka ka raba shi da duk abin da yake da shi, ba shakka zai la’anta ka kana ji, kana gani.” ");
INSERT INTO hausa_vpl VALUES ("JB1_12","019_1_12","JOB","1","12","12","Ubangiji ya ce wa Shaiɗan, “To, shi ke nan, duk abin da yake da shi yana hannunka, amma kada ka taɓa shi, shi kansa.” Sai Shaiɗan ya bar Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JB1_13","019_1_13","JOB","1","13","13","Wata rana lokacin da ’ya’yan Ayuba suke cikin biki a gidan babban ɗansa, ");
INSERT INTO hausa_vpl VALUES ("JB1_14","019_1_14","JOB","1","14","14","sai ɗan aika ya zo wurin Ayuba ya ce masa, “Shanu suna huɗa, jakuna kuma suna kiwo nan kusa, ");
INSERT INTO hausa_vpl VALUES ("JB1_15","019_1_15","JOB","1","15","15","sai Sabenawa suka auka musu suka kwashe su suka tafi, suka karkashe masu yi maka aiki duka, ni kaɗai na tsira na zo in gaya maka!” ");
INSERT INTO hausa_vpl VALUES ("JB1_16","019_1_16","JOB","1","16","16","Yana cikin magana sai ga wani ɗan aika ya zo ya ce, “Wutar Allah ta sauko daga sama ta ƙona dukan tumaki da masu lura da su, wato, bayinka, ni kaɗai na tsira na zo in gaya maka!” ");
INSERT INTO hausa_vpl VALUES ("JB1_17","019_1_17","JOB","1","17","17","Yana cikin magana sai ga wani ɗan aika ya zo ya ce, “Ƙungiyoyin mahara uku na Kaldiyawa sun auka wa raƙumanka sun kwashe su duka, suka kuma karkashe masu yi maka aiki, ni kaɗai ne na tsira na zo in gaya maka!” ");
INSERT INTO hausa_vpl VALUES ("JB1_18","019_1_18","JOB","1","18","18","Yana cikin magana, sai ga wani ɗan aika ya zo ya ce, “’Ya’yanka maza da mata suna biki, suna ci suna sha a gidan babban ɗanka, ");
INSERT INTO hausa_vpl VALUES ("JB1_19","019_1_19","JOB","1","19","19","sai wata iska mai ƙarfi daga hamada ta auka ta rushe gidan, gidan kuwa ya fāɗi a kan ’ya’yanka ya kashe su, ni kaɗai na tsira na zo in gaya maka!” ");
INSERT INTO hausa_vpl VALUES ("JB1_20","019_1_20","JOB","1","20","20","Da jin haka sai Ayuba ya tashi ya yayyaga tufafin jikinsa, ya aske kansa. Ya fāɗi a ƙasa ya yi sujada ");
INSERT INTO hausa_vpl VALUES ("JB1_21","019_1_21","JOB","1","21","21","ya ce, “Tsirara na fito daga cikin mahaifiyata, tsirara kuma zan koma. Ubangiji ya bayar, Ubangiji kuma ya karɓa; yabo ya tabbata ga Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("JB1_22","019_1_22","JOB","1","22","22","Cikin wannan duka Ayuba bai yi wa Allah zunubi ta wurin ba shi laifi ba. ");
INSERT INTO hausa_vpl VALUES ("JB2_1","019_2_1","JOB","2","1","1","Wata rana kuma mala’iku suka sāke kawo kansu gaban Ubangiji, sai Shaiɗan shi ma ya zo tare da su yă nuna kansa a gabansa. ");
INSERT INTO hausa_vpl VALUES ("JB2_2","019_2_2","JOB","2","2","2","Sai Ubangiji ya ce wa Shaiɗan, “Daga ina ka fito?” Shaiɗan ya amsa wa Ubangiji ya ce, “Daga yawo a duniya ina kai da kawowa a cikinta.” ");
INSERT INTO hausa_vpl VALUES ("JB2_3","019_2_3","JOB","2","3","3","Sai Ubangiji ya ce wa Shaiɗan, “Ko ka ga bawana Ayuba? A cikin duniya babu wani kamar sa; shi marar laifi ne, adali kuma, mutum ne mai tsoron Allah ba ruwansa da mugunta. Kuma har yanzu bai fasa zama mai aminci ba duk da wahalar da ka sa na bari ka ba shi ba tare da wani dalili ba.” ");
INSERT INTO hausa_vpl VALUES ("JB2_4","019_2_4","JOB","2","4","4","Shaiɗan ya amsa ya ce, “Fata don fata! Mutum zai iya rabuwa da duk abin da yake da shi domin ransa. ");
INSERT INTO hausa_vpl VALUES ("JB2_5","019_2_5","JOB","2","5","5","Ka ɗan taɓa lafiyar jikinsa ka gani ba shakka zai la’anta ka kana ji kana gani.” ");
INSERT INTO hausa_vpl VALUES ("JB2_6","019_2_6","JOB","2","6","6","Ubangiji ya ce wa Shaiɗan, “To, shi ke nan, duk abin da yake da shi yana hannunka, amma kada ka taɓa shi, shi kansa.” ");
INSERT INTO hausa_vpl VALUES ("JB2_7","019_2_7","JOB","2","7","7","Sai Shaiɗan ya bar Ubangiji, ya je ya sa wa Ayuba ƙuraje masu zafi a jikinsa daga tafin ƙafafunsa har zuwa kansa. ");
INSERT INTO hausa_vpl VALUES ("JB2_8","019_2_8","JOB","2","8","8","Sai Ayuba ya ɗauki kaskon tukunya yana ta sosa ƙurajen da shi, yayinda yake zaune cikin toka. ");
INSERT INTO hausa_vpl VALUES ("JB2_9","019_2_9","JOB","2","9","9","Matarsa ta ce masa, “Har yanzu kana nan da amincinka? Ka la’anta Allah ka mutu!” ");
INSERT INTO hausa_vpl VALUES ("JB2_10","019_2_10","JOB","2","10","10","Ya amsa ya ce, “Kina magana kamar wawiya. Alheri kaɗai za mu dinga samu daga Allah ban da wahala?” A cikin wannan duka Ayuba bai yi zunubi ba cikin maganarsa. ");
INSERT INTO hausa_vpl VALUES ("JB2_11","019_2_11","JOB","2","11","11","Lokacin da abokan Ayuba su uku wato, Elifaz mutumin Teman, Bildad mutumin Shuwa, da Zofar mutumin Na’ama suka ji wahalar da ta auka wa Ayuba, sai suka shirya suka bar gidajensu suka je don su ta’azantar da shi. ");
INSERT INTO hausa_vpl VALUES ("JB2_12","019_2_12","JOB","2","12","12","Sa’ad da suka gan shi daga nesa, da ƙyar suka gane shi; sai suka fara kuka da ƙarfi, suka yayyaga tufafinsu suka zuba toka a kawunansu, ");
INSERT INTO hausa_vpl VALUES ("JB2_13","019_2_13","JOB","2","13","13","sai suka zauna da shi a ƙasa har kwana bakwai. Ba wanda ya ce masa kome, don sun ga tsananin wahalar da yake ciki. ");
INSERT INTO hausa_vpl VALUES ("JB3_1","019_3_1","JOB","3","1","1","Bayan wannan Ayuba ya buɗe baki ya la’anta ranar da aka haife shi. ");
INSERT INTO hausa_vpl VALUES ("JB3_2","019_3_2","JOB","3","2","2","Ayuba ya ce, ");
INSERT INTO hausa_vpl VALUES ("JB3_3","019_3_3","JOB","3","3","3","“A hallaka ranar da aka haife ni, da kuma daren da aka ce, ‘An haifi jariri namiji!’ ");
INSERT INTO hausa_vpl VALUES ("JB3_4","019_3_4","JOB","3","4","4","Bari ranan nan ta zama duhu; kada Allah yă kula da ita; kada rana tă yi haske a wannan rana. ");
INSERT INTO hausa_vpl VALUES ("JB3_5","019_3_5","JOB","3","5","5","Bari duhu da inuwa mai duhu ta sāke rufe ta; gizagizai kuma su rufe ta; duhu kuma ya rufe haskenta. ");
INSERT INTO hausa_vpl VALUES ("JB3_6","019_3_6","JOB","3","6","6","Bari duhu mai yawa yă rufe daren nan; kada a haɗa ta cikin kwanakin shekara, ko kuma cikin kwanakin watanni. ");
INSERT INTO hausa_vpl VALUES ("JB3_7","019_3_7","JOB","3","7","7","Bari daren yă zama marar amfani; kada a ji wata sowa ta farin ciki. ");
INSERT INTO hausa_vpl VALUES ("JB3_8","019_3_8","JOB","3","8","8","Bari waɗanda suke la’anta ranaku su la’anta wannan rana su waɗanda suke umartar dodon ruwa. ");
INSERT INTO hausa_vpl VALUES ("JB3_9","019_3_9","JOB","3","9","9","Bari taurarinta na safe su zama duhu; bari ranar tă yi ta jiran ganin haske amma kada tă gani, ");
INSERT INTO hausa_vpl VALUES ("JB3_10","019_3_10","JOB","3","10","10","gama ba tă hana uwata ɗaukar cikina, don ta hana ni shan wahalan nan ba. ");
INSERT INTO hausa_vpl VALUES ("JB3_11","019_3_11","JOB","3","11","11","“Me ya sa ban mutu ba da za a haife ni, ko kuma in mutu sa’ad da ana haihuwata ba? ");
INSERT INTO hausa_vpl VALUES ("JB3_12","019_3_12","JOB","3","12","12","Me ya sa aka haife ni, aka tanada nono na sha na rayu? ");
INSERT INTO hausa_vpl VALUES ("JB3_13","019_3_13","JOB","3","13","13","Da yanzu ina kwance cikin salama; da ina barcina cikin salama ");
INSERT INTO hausa_vpl VALUES ("JB3_14","019_3_14","JOB","3","14","14","tare da sarakuna da mashawarta a cikin ƙasa, waɗanda suka gina wa kansu wuraren da yanzu duk sun rushe, ");
INSERT INTO hausa_vpl VALUES ("JB3_15","019_3_15","JOB","3","15","15","da shugabanni waɗanda suke da zinariya, waɗanda suka cika gidajensu da azurfa. ");
INSERT INTO hausa_vpl VALUES ("JB3_16","019_3_16","JOB","3","16","16","Ko kuma don me ba a ɓoye ni a cikin ƙasa kamar jaririn da aka haifa ba rai ba, kamar jaririn da bai taɓa ganin hasken rana ba. ");
INSERT INTO hausa_vpl VALUES ("JB3_17","019_3_17","JOB","3","17","17","A wurin mugaye za su daina yin mugunta, gajiyayyu kuma za su huta. ");
INSERT INTO hausa_vpl VALUES ("JB3_18","019_3_18","JOB","3","18","18","Waɗanda aka daure za su sami jin daɗin; an sake su ba za su sāke jin ana tsawata masu ba. ");
INSERT INTO hausa_vpl VALUES ("JB3_19","019_3_19","JOB","3","19","19","Manyan da ƙanana suna a can, bawa kuma ya sami ’yanci daga wurin maigidansa. ");
INSERT INTO hausa_vpl VALUES ("JB3_20","019_3_20","JOB","3","20","20","“Don me ake ba da haske ga waɗanda suke cikin ƙunci, rai kuma ga masu ɗacin rai ");
INSERT INTO hausa_vpl VALUES ("JB3_21","019_3_21","JOB","3","21","21","ga waɗanda suke neman mutuwa amma ba su samu ba, waɗanda suke nemanta kamar wani abu mai daraja a ɓoye, ");
INSERT INTO hausa_vpl VALUES ("JB3_22","019_3_22","JOB","3","22","22","waɗanda suke farin ciki sa’ad da suka kai kabari? ");
INSERT INTO hausa_vpl VALUES ("JB3_23","019_3_23","JOB","3","23","23","Don me aka ba mutum rai, mutumin da bai san wani abu game da kansa ba, mutumin da Allah ya kange shi. ");
INSERT INTO hausa_vpl VALUES ("JB3_24","019_3_24","JOB","3","24","24","Baƙin ciki ya ishe ni maimakon abinci; ina ta yin nishi ba fasawa; ");
INSERT INTO hausa_vpl VALUES ("JB3_25","019_3_25","JOB","3","25","25","Abin da nake tsoro ya faru da ni; abin da ba na so ya same ni. ");
INSERT INTO hausa_vpl VALUES ("JB3_26","019_3_26","JOB","3","26","26","Ba ni da salama, ba natsuwa; ba ni da hutu, sai wahala kawai.” ");
INSERT INTO hausa_vpl VALUES ("JB4_1","019_4_1","JOB","4","1","1","Sai Elifaz mutumin Teman ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB4_2","019_4_2","JOB","4","2","2","“In wani ya yi maka magana, za ka ji haushi? Amma wa zai iya yin shiru? ");
INSERT INTO hausa_vpl VALUES ("JB4_3","019_4_3","JOB","4","3","3","Ka tuna yadda ka yi wa mutane da yawa magana, yadda ka ƙarfafa hannuwa marasa ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("JB4_4","019_4_4","JOB","4","4","4","Maganarka ta ƙarfafa waɗanda suka yi tuntuɓe; ka ƙarfafa gwiwoyin da suka rasa ƙarfinsu. ");
INSERT INTO hausa_vpl VALUES ("JB4_5","019_4_5","JOB","4","5","5","Amma yanzu wahala ta zo maka, sai ka karaya; wahala ta sa ka rikice. ");
INSERT INTO hausa_vpl VALUES ("JB4_6","019_4_6","JOB","4","6","6","Ashe bai kamata ka dogara ga Allahnka ba, amincinka kuma yă zama begenka? ");
INSERT INTO hausa_vpl VALUES ("JB4_7","019_4_7","JOB","4","7","7","“Ka duba ka gani yanzu. Wane marar laifi ne ya taɓa hallaka? Ko an taɓa hallaka masu adalci? ");
INSERT INTO hausa_vpl VALUES ("JB4_8","019_4_8","JOB","4","8","8","Na kula cewa waɗanda suke huɗa gonar mugunta, da waɗanda suke shuka mugunta, su ne suke girbe mugunta. ");
INSERT INTO hausa_vpl VALUES ("JB4_9","019_4_9","JOB","4","9","9","A sa’a ɗaya Allah yake hallaka su, cikin fushinsa yakan hallaka su. ");
INSERT INTO hausa_vpl VALUES ("JB4_10","019_4_10","JOB","4","10","10","Zakoki suna ruri suna gurnani; duk da haka an karya haƙoran manyan zakoki. ");
INSERT INTO hausa_vpl VALUES ("JB4_11","019_4_11","JOB","4","11","11","Zakoki suna mutuwa domin ba dabbar da za su kashe su ci, ’ya’yan zakanya kuma sun watse. ");
INSERT INTO hausa_vpl VALUES ("JB4_12","019_4_12","JOB","4","12","12","“Asirce aka gaya mini maganan nan, da ƙyar kunnuwana suka iya ji. ");
INSERT INTO hausa_vpl VALUES ("JB4_13","019_4_13","JOB","4","13","13","Cikin mafarki da tsakar dare, lokacin kowa yana zurfin barci, na sami saƙon nan. ");
INSERT INTO hausa_vpl VALUES ("JB4_14","019_4_14","JOB","4","14","14","Tsoro da fargaba suka kama ni har duk ƙasusuwan jikina suka yi ta rawa. ");
INSERT INTO hausa_vpl VALUES ("JB4_15","019_4_15","JOB","4","15","15","Wani iska ya taɓa mini fuska, sai tsigar jikina ta tashi. ");
INSERT INTO hausa_vpl VALUES ("JB4_16","019_4_16","JOB","4","16","16","Ya tsaya cik, amma ban iya sani ko mene ne ba. Wani abu ya tsaya a gabana, na kuma ji murya. ");
INSERT INTO hausa_vpl VALUES ("JB4_17","019_4_17","JOB","4","17","17","‘Ko zai yiwu mutum yă fi Allah adalci, ko kuma mutum yă fi wanda ya halicce shi tsarki? ");
INSERT INTO hausa_vpl VALUES ("JB4_18","019_4_18","JOB","4","18","18","In Allah bai yarda da bayinsa ba, in ya sami mala’ikunsa da laifi, ");
INSERT INTO hausa_vpl VALUES ("JB4_19","019_4_19","JOB","4","19","19","to, su wane ne mutane masu zama a gidan da aka yi da laka, waɗanda da ƙura aka yi harsashensu, waɗanda za a iya murƙushe su kamar asu! ");
INSERT INTO hausa_vpl VALUES ("JB4_20","019_4_20","JOB","4","20","20","Tsakanin safe da yamma mai yiwuwa ne ragargaza su; farat ɗaya, su mutu har abada. ");
INSERT INTO hausa_vpl VALUES ("JB4_21","019_4_21","JOB","4","21","21","Ba a tuge igiyar tentinsu, don su mutu ba tare da hikima ba?’ ");
INSERT INTO hausa_vpl VALUES ("JB5_1","019_5_1","JOB","5","1","1","“Ka yi kira in kana so, amma wa zai amsa maka? Wurin waɗanne tsarkaka za ka juya? ");
INSERT INTO hausa_vpl VALUES ("JB5_2","019_5_2","JOB","5","2","2","Fushi yana kashe wawa, ƙyashi kuma yana kashe marar azanci. ");
INSERT INTO hausa_vpl VALUES ("JB5_3","019_5_3","JOB","5","3","3","Ni ma na ga wawa yana cin gaba, amma nan da nan gidansa ya zama la’ananne. ");
INSERT INTO hausa_vpl VALUES ("JB5_4","019_5_4","JOB","5","4","4","’Ya’yansa suna cikin hatsari, ba wanda zai tsaya musu a gaban alƙali, ");
INSERT INTO hausa_vpl VALUES ("JB5_5","019_5_5","JOB","5","5","5","mayunwata sun kwashe girbinsa, har abubuwan da suke cikin ƙaya, masu jin ƙishirwa kuma suna zuba ido ga dukiyarsa. ");
INSERT INTO hausa_vpl VALUES ("JB5_6","019_5_6","JOB","5","6","6","Gama ba daga cikin ƙasa wahala take fitowa ba, ko kuma bala’i daga ƙasa. ");
INSERT INTO hausa_vpl VALUES ("JB5_7","019_5_7","JOB","5","7","7","Duk da haka an haifi mutum don wahala ne, kamar yadda ba shakka tartsatsin wuta yake tashi. ");
INSERT INTO hausa_vpl VALUES ("JB5_8","019_5_8","JOB","5","8","8","“Amma da a ce ni ne, da zan roƙi Allah; zan gaya masa damuwata. ");
INSERT INTO hausa_vpl VALUES ("JB5_9","019_5_9","JOB","5","9","9","Yana yin abubuwan al’ajabi waɗanda ba a ganewa, mu’ujizai waɗanda ba a ƙirgawa. ");
INSERT INTO hausa_vpl VALUES ("JB5_10","019_5_10","JOB","5","10","10","Yana zuba ruwan sama a ƙasa; yana zuba ruwa a gonaki. ");
INSERT INTO hausa_vpl VALUES ("JB5_11","019_5_11","JOB","5","11","11","Yana ɗaukaka masu sauƙinkai, yana kāre waɗanda suke makoki. ");
INSERT INTO hausa_vpl VALUES ("JB5_12","019_5_12","JOB","5","12","12","Yana dagula shirye-shiryen masu wayo don kada su yi nasara cikin abubuwan da suke shirin yi. ");
INSERT INTO hausa_vpl VALUES ("JB5_13","019_5_13","JOB","5","13","13","Yana kama masu wayo cikin wayonsu, yana kawar da shirye-shiryensu ba za su yi nasara ba. ");
INSERT INTO hausa_vpl VALUES ("JB5_14","019_5_14","JOB","5","14","14","Da rana sukan yi karo da duhu; da rana ma suna lallube kamar a duhun dare suke. ");
INSERT INTO hausa_vpl VALUES ("JB5_15","019_5_15","JOB","5","15","15","Yana ceton matalauta daga takobin da za tă kashe su da shi; yana cetonsu daga hannun waɗanda suka fi su ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("JB5_16","019_5_16","JOB","5","16","16","Saboda haka matalauta suna da bege, rashin gaskiya kuma ta yi shiru. ");
INSERT INTO hausa_vpl VALUES ("JB5_17","019_5_17","JOB","5","17","17","“Mai albarka ne wanda Allah yake yi masa gyara in mutumin ya yi kuskure; saboda haka kada ka guje wa horon Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("JB5_18","019_5_18","JOB","5","18","18","Ko da yake yana sa ciwo, shi ne kuma yake warkar da ciwon; ciwon da ya ji maka, shi da kansa zai warkar da shi. ");
INSERT INTO hausa_vpl VALUES ("JB5_19","019_5_19","JOB","5","19","19","Zai cece ka daga bala’o’i guda shida; har bakwai ma ba abin da zai same ka. ");
INSERT INTO hausa_vpl VALUES ("JB5_20","019_5_20","JOB","5","20","20","Lokacin yunwa yana tsare ka daga mutuwa, a cikin yaƙi kuma yana kāre ka daga sarar takobi. ");
INSERT INTO hausa_vpl VALUES ("JB5_21","019_5_21","JOB","5","21","21","Zai kāre ka daga ɓata suna, kuma ba ka bukata ka ji tsoro in hallaka ta zo. ");
INSERT INTO hausa_vpl VALUES ("JB5_22","019_5_22","JOB","5","22","22","Za ka yi wa hallaka da yunwa dariya; kuma ba ka bukata ka ji tsoron manyan namun jeji. ");
INSERT INTO hausa_vpl VALUES ("JB5_23","019_5_23","JOB","5","23","23","Gama za ka zauna lafiya da duwatsu a gonaki, kuma manyan namun jeji za su yi zaman salama da kai. ");
INSERT INTO hausa_vpl VALUES ("JB5_24","019_5_24","JOB","5","24","24","Za ka zauna lafiya a cikin tenti naka, za ka ƙirga kayanka za ka samu kome na nan. ");
INSERT INTO hausa_vpl VALUES ("JB5_25","019_5_25","JOB","5","25","25","Za ka san cewa ’ya’yanka za su zama da yawa, zuriyarka kuma kamar ciyawa a ƙasa. ");
INSERT INTO hausa_vpl VALUES ("JB5_26","019_5_26","JOB","5","26","26","Za ka yi kyakkyawan tsufa kafin ka mutu, kamar yadda ake tara dammuna a lokacin girbi. ");
INSERT INTO hausa_vpl VALUES ("JB5_27","019_5_27","JOB","5","27","27","“Mun yi nazarin wannan, kuma gaskiya ne. Saboda haka ka ji, ka kuma yi amfani da shi.” ");
INSERT INTO hausa_vpl VALUES ("JB6_1","019_6_1","JOB","6","1","1","Sa’an nan Ayuba ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB6_2","019_6_2","JOB","6","2","2","“Da kawai za a iya auna wahalata a kuma sa ɓacin raina a ma’auni! ");
INSERT INTO hausa_vpl VALUES ("JB6_3","019_6_3","JOB","6","3","3","Ba shakka da sun fi yashin teku nauyi, shi ya sa nake magana haka. ");
INSERT INTO hausa_vpl VALUES ("JB6_4","019_6_4","JOB","6","4","4","Kibiyoyin Maɗaukaki suna a kaina, ruhuna yana shan dafinsa; fushin Allah ya sauka a kaina. ");
INSERT INTO hausa_vpl VALUES ("JB6_5","019_6_5","JOB","6","5","5","Jaki yakan yi kuka sa’ad da ya sami ciyawar ci, ko saniya takan yi kuka in ta sami abincinta? ");
INSERT INTO hausa_vpl VALUES ("JB6_6","019_6_6","JOB","6","6","6","Akan cin abinci marar ɗanɗano ba tare da an sa gishiri ba, ko akwai wani ƙanshin daɗi a cikin farin ruwan ƙwai? ");
INSERT INTO hausa_vpl VALUES ("JB6_7","019_6_7","JOB","6","7","7","Na ƙi in taɓa shi; irin wannan abinci zai sa ni rashin lafiya. ");
INSERT INTO hausa_vpl VALUES ("JB6_8","019_6_8","JOB","6","8","8","“Kash, da ma Allah zai ba ni abin da nake fatar samu, da ma Allah zai biya mini bukatata, ");
INSERT INTO hausa_vpl VALUES ("JB6_9","019_6_9","JOB","6","9","9","wato, Allah yă kashe ni, yă miƙa hannunsa yă yanke raina! ");
INSERT INTO hausa_vpl VALUES ("JB6_10","019_6_10","JOB","6","10","10","Da sai in ji daɗi duk zafin da nake sha ban hana maganar Mai Tsarkin nan cika ba. ");
INSERT INTO hausa_vpl VALUES ("JB6_11","019_6_11","JOB","6","11","11","“Wane ƙarfi nake da shi, har da zan ci gaba da sa zuciya? Wane sa zuciya ne zai sa in yi haƙuri? ");
INSERT INTO hausa_vpl VALUES ("JB6_12","019_6_12","JOB","6","12","12","Da ƙarfin dutse aka yi ni ne? Ko jikina tagulla ne? ");
INSERT INTO hausa_vpl VALUES ("JB6_13","019_6_13","JOB","6","13","13","Ina da wani ikon da zan iya taimakon kai na ne, yanzu da aka kore nasara daga gare ni? ");
INSERT INTO hausa_vpl VALUES ("JB6_14","019_6_14","JOB","6","14","14","“Duk wanda ya ƙi yă yi alheri ga aboki ya rabu ta tsoron Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("JB6_15","019_6_15","JOB","6","15","15","Amma ’yan’uwana sun nuna ba zan iya dogara gare su ba, kamar rafin da yakan bushe da rani, ");
INSERT INTO hausa_vpl VALUES ("JB6_16","019_6_16","JOB","6","16","16","kamar rafin da yakan cika a lokacin ƙanƙara, yă kuma kumbura kamar ƙanƙarar da ta narke, ");
INSERT INTO hausa_vpl VALUES ("JB6_17","019_6_17","JOB","6","17","17","amma da rani sai yă bushe, lokacin zafi ba a samun ruwa yana gudu a wurin. ");
INSERT INTO hausa_vpl VALUES ("JB6_18","019_6_18","JOB","6","18","18","Ayari sukan bar hanyarsu; sukan yi ta neman wurin da za su sami ruwa, su kāsa samu har su mutu. ");
INSERT INTO hausa_vpl VALUES ("JB6_19","019_6_19","JOB","6","19","19","Ayarin Tema sun nemi ruwa, matafiya ’yan kasuwa Sheba sun nema cike da begen samu. ");
INSERT INTO hausa_vpl VALUES ("JB6_20","019_6_20","JOB","6","20","20","Ransu ya ɓace, domin sun sa zuciya sosai; sa’ad da suka kai wurin kuwa ba su sami abin da suka sa zuciyar samu ba. ");
INSERT INTO hausa_vpl VALUES ("JB6_21","019_6_21","JOB","6","21","21","Yanzu kuma kun nuna mini ba ku iya taimako; kun ga abin bantsoro kuka tsorata. ");
INSERT INTO hausa_vpl VALUES ("JB6_22","019_6_22","JOB","6","22","22","Ko na taɓa cewa, ‘Ku ba da wani abu a madadina, ko na roƙe ku, ku ba da wani abu domina daga cikin dukiyarku, ");
INSERT INTO hausa_vpl VALUES ("JB6_23","019_6_23","JOB","6","23","23","ko kuma kun taɓa kuɓutar da ni daga hannun maƙiyina, ko kun taɓa ƙwato ni daga hannun marasa kirki’? ");
INSERT INTO hausa_vpl VALUES ("JB6_24","019_6_24","JOB","6","24","24","“Ku koya mini, zan yi shiru; ku nuna mini inda ban yi daidai ba. ");
INSERT INTO hausa_vpl VALUES ("JB6_25","019_6_25","JOB","6","25","25","Faɗar gaskiya tana da zafi! Amma ina amfanin gardamar da kuke yi? ");
INSERT INTO hausa_vpl VALUES ("JB6_26","019_6_26","JOB","6","26","26","Ko kuna so ku gyara abin da na faɗi ne, ku mai da magana wanda yake cikin wahala ta zama ta wofi? ");
INSERT INTO hausa_vpl VALUES ("JB6_27","019_6_27","JOB","6","27","27","Kukan yi ƙuri’a a kan marayu ku kuma sayar da abokinku. ");
INSERT INTO hausa_vpl VALUES ("JB6_28","019_6_28","JOB","6","28","28","“Amma yanzu ku dube ni da kyau, zan yi muku ƙarya ne? ");
INSERT INTO hausa_vpl VALUES ("JB6_29","019_6_29","JOB","6","29","29","Ku bi a hankali, kada ku ɗora mini laifi; ku sāke dubawa, gama ba ni da laifi. ");
INSERT INTO hausa_vpl VALUES ("JB6_30","019_6_30","JOB","6","30","30","Ko akwai wata mugunta a bakina? Bakina ba zai iya rarrabewa tsakanin gaskiya da ƙarya ba? ");
INSERT INTO hausa_vpl VALUES ("JB7_1","019_7_1","JOB","7","1","1","“Mutum bai sha wahalar aiki ba a duniya? Rayuwarsa ba kamar ta wanda aka yi hayarsa ba ne? ");
INSERT INTO hausa_vpl VALUES ("JB7_2","019_7_2","JOB","7","2","2","Kamar yadda bawa yakan jira yamma ta yi, ko kuma kamar yadda wanda aka yi hayarsa yakan jira a biya shi kuɗin aikin da ya yi. ");
INSERT INTO hausa_vpl VALUES ("JB7_3","019_7_3","JOB","7","3","3","Saboda haka rabona shi ne watanni na zama banza, kowane dare kuwa sai ɓacin rai nake samu. ");
INSERT INTO hausa_vpl VALUES ("JB7_4","019_7_4","JOB","7","4","4","Lokacin da na kwanta ina tunani, ‘Har sai yaushe zan tashi?’ Gari ya ƙi wayewa, ina ta jujjuyawa har safe. ");
INSERT INTO hausa_vpl VALUES ("JB7_5","019_7_5","JOB","7","5","5","Jikina duk tsutsotsi da ƙuraje sun rufe shi, fatar jikina ta ruɓe tana fitar da ruwan miki. ");
INSERT INTO hausa_vpl VALUES ("JB7_6","019_7_6","JOB","7","6","6","“Kwanakina suna wucewa da sauri, fiye da yadda ƙoshiyar masaƙa take wucewa da sauri, za su kawo ga ƙarshe ba bege. ");
INSERT INTO hausa_vpl VALUES ("JB7_7","019_7_7","JOB","7","7","7","Ka tuna, ya Allah, raina numfashi ne kawai; idanuna ba za su taɓa sāke ganin farin ciki ba. ");
INSERT INTO hausa_vpl VALUES ("JB7_8","019_7_8","JOB","7","8","8","Idanun da suke ganina yanzu ba za su sāke ganina ba; za ku neme ni amma ba za ku same ni ba. ");
INSERT INTO hausa_vpl VALUES ("JB7_9","019_7_9","JOB","7","9","9","Kamar yadda girgije yakan ɓace yă tafi, haka mutum yake shige zuwa kabari ba kuwa zai dawo ba. ");
INSERT INTO hausa_vpl VALUES ("JB7_10","019_7_10","JOB","7","10","10","Ba zai taɓa zuwa gidansa ba; ba za a sāke san da shi ba. ");
INSERT INTO hausa_vpl VALUES ("JB7_11","019_7_11","JOB","7","11","11","“Saboda haka ba zan yi shiru ba; zan yi magana cikin ɓacin raina, zan nuna ɓacin raina cikin ruhu, cikin ƙuncin raina. ");
INSERT INTO hausa_vpl VALUES ("JB7_12","019_7_12","JOB","7","12","12","Ni teku ne, ko kuwa dodon ruwa, don me kake tsaro na? ");
INSERT INTO hausa_vpl VALUES ("JB7_13","019_7_13","JOB","7","13","13","Lokacin da nake zato zan sami salama in na kwanta a gadona don in huta, ");
INSERT INTO hausa_vpl VALUES ("JB7_14","019_7_14","JOB","7","14","14","duk da haka kana ba ni tsoro da mafarke-mafarke, kana tsorata ni da wahayi. ");
INSERT INTO hausa_vpl VALUES ("JB7_15","019_7_15","JOB","7","15","15","Na gwammace a shaƙe ni in mutu maimakon in kasance cikin wannan jiki. ");
INSERT INTO hausa_vpl VALUES ("JB7_16","019_7_16","JOB","7","16","16","Ba na so in zauna da rai; ba zan rayu ba har abada. Ku rabu da ni; rayuwata ba ta da amfani. ");
INSERT INTO hausa_vpl VALUES ("JB7_17","019_7_17","JOB","7","17","17","“Mene ne mutum har da ka kula da shi haka, har ka mai da hankali a kansa, ");
INSERT INTO hausa_vpl VALUES ("JB7_18","019_7_18","JOB","7","18","18","har kake duba shi kowace safiya, kake kuma gwada shi koyaushe? ");
INSERT INTO hausa_vpl VALUES ("JB7_19","019_7_19","JOB","7","19","19","Ba za ka ɗan daina kallo na ba ko ka rabu da ni na ɗan lokaci? ");
INSERT INTO hausa_vpl VALUES ("JB7_20","019_7_20","JOB","7","20","20","In na yi zunubi, me na yi maka, kai mai lura da mutane? Don me ka sa ni a gaba? Na zame maka kaya mai nauyi ne? ");
INSERT INTO hausa_vpl VALUES ("JB7_21","019_7_21","JOB","7","21","21","Me ya sa ba za ka gafarta mini laifofina ba? Gama na kusa kwantawa cikin ƙasa; za ka neme ni, amma ba za ka same ni ba.” ");
INSERT INTO hausa_vpl VALUES ("JB8_1","019_8_1","JOB","8","1","1","Sai Bildad mutumin Shuwa ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB8_2","019_8_2","JOB","8","2","2","“Har yaushe za ka gama faɗa waɗannan abubuwa? Maganganunka ba su da amfani. ");
INSERT INTO hausa_vpl VALUES ("JB8_3","019_8_3","JOB","8","3","3","Allah ba mai shari’ar gaskiya ba ne? Ko Maɗaukaki yakan yi abin da ba daidai ba? ");
INSERT INTO hausa_vpl VALUES ("JB8_4","019_8_4","JOB","8","4","4","Lokacin da ’ya’yansa suka yi masa zunubi, yakan bar su su sha wahalar da zunubi yake kawowa. ");
INSERT INTO hausa_vpl VALUES ("JB8_5","019_8_5","JOB","8","5","5","Amma in za ka dubi Allah ka roƙi Maɗaukaki, ");
INSERT INTO hausa_vpl VALUES ("JB8_6","019_8_6","JOB","8","6","6","in kai mai tsarki ne, kuma mai adalci, ko yanzu ma zai taimake ka, yă mayar maka iyalinka da farin cikinka. ");
INSERT INTO hausa_vpl VALUES ("JB8_7","019_8_7","JOB","8","7","7","Ko da yake za ka fara da kaɗan, duk da haka za ka gama da samu mai yawa. ");
INSERT INTO hausa_vpl VALUES ("JB8_8","019_8_8","JOB","8","8","8","“Tambayi na gaba da kai ka ji abin da iyayenka suka koya ");
INSERT INTO hausa_vpl VALUES ("JB8_9","019_8_9","JOB","8","9","9","gama jiya kaɗai aka haife mu ba mu san kome ba, kuma kwanakinmu a duniya masu wucewa ne. ");
INSERT INTO hausa_vpl VALUES ("JB8_10","019_8_10","JOB","8","10","10","Ba za su bishe ka su kuma gaya maka abin da za ka yi ba? Ba za su yi magana daga cikin hikimar da suke da ita ba? ");
INSERT INTO hausa_vpl VALUES ("JB8_11","019_8_11","JOB","8","11","11","Ko kyauro zai iya yi girma a wurin da ba ruwa? Ko za tă taɓa iya yin girma ba tare da ruwa ba? ");
INSERT INTO hausa_vpl VALUES ("JB8_12","019_8_12","JOB","8","12","12","Yayinda take girma ba a yanka ta, takan mutu da sauri fiye da ciyawa. ");
INSERT INTO hausa_vpl VALUES ("JB8_13","019_8_13","JOB","8","13","13","Abin da yake faruwa ke nan da duk wanda yake mantawa da Allah; waɗanda ba su da Allah, ba su da bege. ");
INSERT INTO hausa_vpl VALUES ("JB8_14","019_8_14","JOB","8","14","14","Abin da yake dogara a kai ba shi da ƙarfi; abin da yake dogara a kai yanar gizo ce. ");
INSERT INTO hausa_vpl VALUES ("JB8_15","019_8_15","JOB","8","15","15","Ya jingina ga yanar gizo, amma ba ta tare shi, sun kama ta, amma ba za tă taimake su tsayawa ba. ");
INSERT INTO hausa_vpl VALUES ("JB8_16","019_8_16","JOB","8","16","16","Yana kama da shukar da aka ba ta ruwa sosai lokacin da akwai rana sosai, tana yaɗuwa da kyau; ");
INSERT INTO hausa_vpl VALUES ("JB8_17","019_8_17","JOB","8","17","17","shukar tana bin yaɗuwa, jijiyoyinta suna nannaɗe duwatsu, suna neman wurin da za su kama sosai a cikin duwatsu. ");
INSERT INTO hausa_vpl VALUES ("JB8_18","019_8_18","JOB","8","18","18","Amma lokacin da aka tuge shukar daga wurin da take, wurin ba zai san da ita kuma ba, wurin zai ce, ‘Ban taɓa ganin ki ba.’ ");
INSERT INTO hausa_vpl VALUES ("JB8_19","019_8_19","JOB","8","19","19","Ba shakka shukar ta mutu ke nan, kuma waɗansu za su tsiro a wurin. ");
INSERT INTO hausa_vpl VALUES ("JB8_20","019_8_20","JOB","8","20","20","“Ba shakka, Allah ba ya ƙin marar laifi, ko kuma yă ƙarfafa masu aikata mugunta. ");
INSERT INTO hausa_vpl VALUES ("JB8_21","019_8_21","JOB","8","21","21","Sai dai yă cika bakinka da dariya, yă sa ka yi sowa ta murna. ");
INSERT INTO hausa_vpl VALUES ("JB8_22","019_8_22","JOB","8","22","22","Maƙiyanka za su sha kunya, za a kawar da tentin mugaye.” ");
INSERT INTO hausa_vpl VALUES ("JB9_1","019_9_1","JOB","9","1","1","Sai Ayuba ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB9_2","019_9_2","JOB","9","2","2","“Lalle, na san wannan gaskiya ne. Amma ta yaya mutum zai iya zama mai adalci a gaban Allah? ");
INSERT INTO hausa_vpl VALUES ("JB9_3","019_9_3","JOB","9","3","3","Ko da mutum yana so yă yi gardama da shi, ba zai taɓa amsa masa ba ko da sau ɗaya cikin dubu. ");
INSERT INTO hausa_vpl VALUES ("JB9_4","019_9_4","JOB","9","4","4","Hikimarsa tana da zurfi, ikonsa yana da yawa. Wane ne ya taɓa yin faɗa da shi har ya yi nasara? ");
INSERT INTO hausa_vpl VALUES ("JB9_5","019_9_5","JOB","9","5","5","Yana matsar da manyan duwatsu kafin su sani kuma yana juya su cikin fushinsa. ");
INSERT INTO hausa_vpl VALUES ("JB9_6","019_9_6","JOB","9","6","6","Yana girgiza ƙasa, yana girgiza harsashenta. ");
INSERT INTO hausa_vpl VALUES ("JB9_7","019_9_7","JOB","9","7","7","Yana magana da rana sai ta ƙi yin haske; yana hana taurari yin haske. ");
INSERT INTO hausa_vpl VALUES ("JB9_8","019_9_8","JOB","9","8","8","Shi kaɗai ya shimfiɗa sammai ya kuma yi tafiya a kan raƙuman ruwan teku. ");
INSERT INTO hausa_vpl VALUES ("JB9_9","019_9_9","JOB","9","9","9","Shi ne ya halicci Mafarauci da Kare da Zomo, da Kaza, da ’Ya’yanta da tarin taurari a sama, da taurarin kudu. ");
INSERT INTO hausa_vpl VALUES ("JB9_10","019_9_10","JOB","9","10","10","Yana yin abubuwan banmamaki waɗanda ba a iya ganewa, mu’ujizai waɗanda ba a iya ƙirgawa. ");
INSERT INTO hausa_vpl VALUES ("JB9_11","019_9_11","JOB","9","11","11","Ba na iya ganinsa lokacin da ya wuce ni; ba na sani ya wuce lokacin da ya wuce. ");
INSERT INTO hausa_vpl VALUES ("JB9_12","019_9_12","JOB","9","12","12","Wane ne ya isa yă hana shi in ya ƙwace abu? Wa zai ce masa, ‘Me kake yi?’ ");
INSERT INTO hausa_vpl VALUES ("JB9_13","019_9_13","JOB","9","13","13","Allah ba ya danne fushinsa; ko dodannin ruwan da ake kira ayarin Rahab ya tattake su. ");
INSERT INTO hausa_vpl VALUES ("JB9_14","019_9_14","JOB","9","14","14","“Ta yaya zan iya yin faɗa da shi? Ina zan iya samun kalmomin da zan yi gardama da shi? ");
INSERT INTO hausa_vpl VALUES ("JB9_15","019_9_15","JOB","9","15","15","Ko da yake ba ni da laifi, ba zan iya amsa masa ba; sai dai roƙon jinƙai zan iya yi ga mahukuncina. ");
INSERT INTO hausa_vpl VALUES ("JB9_16","019_9_16","JOB","9","16","16","Ko da na yi kira gare shi ya amsa mini, ban yarda cewa zai saurare ni ba. ");
INSERT INTO hausa_vpl VALUES ("JB9_17","019_9_17","JOB","9","17","17","Zai sa hadari yă danne ni yă ƙara mini ciwona ba dalili. ");
INSERT INTO hausa_vpl VALUES ("JB9_18","019_9_18","JOB","9","18","18","Ba zai bari in yi numfashi ba, sai dai yă ƙara mini azaba. ");
INSERT INTO hausa_vpl VALUES ("JB9_19","019_9_19","JOB","9","19","19","In maganar ƙarfi ne, shi babban mai ƙarfi ne! In kuma maganar shari’a ne, wa zai kai kararsa? ");
INSERT INTO hausa_vpl VALUES ("JB9_20","019_9_20","JOB","9","20","20","Ko da ni marar ƙarfi ne, bakina ya isa yă sa in zama mai laifi; in ba ni da laifi, zai sa in yi laifi. ");
INSERT INTO hausa_vpl VALUES ("JB9_21","019_9_21","JOB","9","21","21","“Ko da yake ba ni da laifi, ban damu da kaina ba; na rena raina. ");
INSERT INTO hausa_vpl VALUES ("JB9_22","019_9_22","JOB","9","22","22","Ba bambanci; shi ya sa na ce, ‘Yana hallaka marasa laifi da kuma mugaye.’ ");
INSERT INTO hausa_vpl VALUES ("JB9_23","019_9_23","JOB","9","23","23","Lokacin da bala’i ya kawo ga mutuwa, yakan yi dariyar baƙin cikin marasa laifi. ");
INSERT INTO hausa_vpl VALUES ("JB9_24","019_9_24","JOB","9","24","24","Lokacin da ƙasa ta faɗa a hannun mugaye, yakan rufe idanun masu shari’a. In ba shi ba wa zai yi wannan? ");
INSERT INTO hausa_vpl VALUES ("JB9_25","019_9_25","JOB","9","25","25","“Kwanakina sun fi mai gudu wucewa da sauri; suna firiya babu wani abin jin daɗi a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("JB9_26","019_9_26","JOB","9","26","26","Suna wucewa kamar jirgin ruwan da aka yi da kyauro, kamar jahurma da ta kai wa namanta cafka. ");
INSERT INTO hausa_vpl VALUES ("JB9_27","019_9_27","JOB","9","27","27","‘In na ce zan manta da abin da yake damu na, zan yi murmushi in daina nuna ɓacin rai,’ ");
INSERT INTO hausa_vpl VALUES ("JB9_28","019_9_28","JOB","9","28","28","duk da haka ina tsoron duk wahalata, domin na san ba za ka ɗauke ni marar laifi ba. ");
INSERT INTO hausa_vpl VALUES ("JB9_29","019_9_29","JOB","9","29","29","Tun da an riga an ɗauke ni mai laifi, duk ƙoƙarina a banza yake. ");
INSERT INTO hausa_vpl VALUES ("JB9_30","019_9_30","JOB","9","30","30","Ko da na wanke jikina duka da sabulu, na wanke hannuwana kuma da soda, ");
INSERT INTO hausa_vpl VALUES ("JB9_31","019_9_31","JOB","9","31","31","duk da haka za ka jefa ni cikin ƙazamin wuri, yadda ko rigunan jikina ma za su ƙi ni. ");
INSERT INTO hausa_vpl VALUES ("JB9_32","019_9_32","JOB","9","32","32","“Shi ba mutum ba ne kamar ni wanda zan iya amsa masa, har da za mu yi faɗa da juna a wurin shari’a. ");
INSERT INTO hausa_vpl VALUES ("JB9_33","019_9_33","JOB","9","33","33","In da akwai wanda zai iya shiga tsakaninmu, ya ɗora hannunsa a kanmu tare, ");
INSERT INTO hausa_vpl VALUES ("JB9_34","019_9_34","JOB","9","34","34","wani wanda zai sa Allah yă daina duka na, don yă daina ba ni tsoro. ");
INSERT INTO hausa_vpl VALUES ("JB9_35","019_9_35","JOB","9","35","35","Sa’an nan ne zan iya yin magana ba tare da jin tsoronsa ba, amma a yadda nake a yanzu ba zan iya ba. ");
INSERT INTO hausa_vpl VALUES ("JB10_1","019_10_1","JOB","10","1","1","“Na gaji da rayuwa; saboda haka bari in faɗi zuciyata gabagadi yadda raina yake jin ba daɗi. ");
INSERT INTO hausa_vpl VALUES ("JB10_2","019_10_2","JOB","10","2","2","Zan ce wa Allah, kada ka hukunta ni, amma ka gaya mini laifin da na yi maka. ");
INSERT INTO hausa_vpl VALUES ("JB10_3","019_10_3","JOB","10","3","3","Kana jin daɗin ba ni wahala, don me ka yashe ni, abin da ka halitta da hannunka, yayinda kake murmushi game da shirye-shiryen mugaye? ");
INSERT INTO hausa_vpl VALUES ("JB10_4","019_10_4","JOB","10","4","4","Idanunka irin na mutum ne? Kana gani yadda mutum yake gani ne? ");
INSERT INTO hausa_vpl VALUES ("JB10_5","019_10_5","JOB","10","5","5","Kwanakinka kamar na mutane ne, ko shekarunka kamar na mutane ne ");
INSERT INTO hausa_vpl VALUES ("JB10_6","019_10_6","JOB","10","6","6","da za ka neme ni da laifi ka hukunta ni? ");
INSERT INTO hausa_vpl VALUES ("JB10_7","019_10_7","JOB","10","7","7","Ko da yake ka san ba ni da laifi, kuma ba wanda zai iya cetona daga hannunka. ");
INSERT INTO hausa_vpl VALUES ("JB10_8","019_10_8","JOB","10","8","8","“Da hannuwanka ka ƙera ni, kai ka halicce ni. Yanzu kuma kai za ka juya ka hallaka ni? ");
INSERT INTO hausa_vpl VALUES ("JB10_9","019_10_9","JOB","10","9","9","Ka tuna cewa ka mulmula ni kamar yumɓu. Yanzu za ka mai da ni in zama ƙura kuma? ");
INSERT INTO hausa_vpl VALUES ("JB10_10","019_10_10","JOB","10","10","10","Ba kai ka zuba ni kamar madara ba, na daskare kamar cuku. ");
INSERT INTO hausa_vpl VALUES ("JB10_11","019_10_11","JOB","10","11","11","Ka rufe ni da tsoka da fata, ka harhaɗa ni da ƙasusuwa da jijiyoyi? ");
INSERT INTO hausa_vpl VALUES ("JB10_12","019_10_12","JOB","10","12","12","Ka ba ni rai ka kuma yi mini alheri, kuma cikin tanadinka ka kula da ruhuna. ");
INSERT INTO hausa_vpl VALUES ("JB10_13","019_10_13","JOB","10","13","13","“Amma wannan shi ne abin da ka ɓoye a zuciyarka, na kuma san abin da yake cikin zuciyarka ke nan. ");
INSERT INTO hausa_vpl VALUES ("JB10_14","019_10_14","JOB","10","14","14","In na yi zunubi kana kallo na kuma ba za ka fasa ba ni horo ba don laifin da na yi. ");
INSERT INTO hausa_vpl VALUES ("JB10_15","019_10_15","JOB","10","15","15","Idan ina da laifi, kaitona! Ko da ba ni da laifi, ba zan iya ɗaga fuskata ba, gama kunya ta ishe ni duk ɓacin rai ya ishe ni. ");
INSERT INTO hausa_vpl VALUES ("JB10_16","019_10_16","JOB","10","16","16","In na ɗaga kaina, za ka neme ni kamar zaki ka sāke nuna al’ajabin ikonka a kaina. ");
INSERT INTO hausa_vpl VALUES ("JB10_17","019_10_17","JOB","10","17","17","Kana sāke kawo sababbin waɗanda za su ba da shaida a kaina kana ƙara haushinka a kaina; kana ƙara kawo mini hari. ");
INSERT INTO hausa_vpl VALUES ("JB10_18","019_10_18","JOB","10","18","18","“Me ya sa ka fito da ni daga cikin uwata? Da ma na mutu kafin a haife ni. ");
INSERT INTO hausa_vpl VALUES ("JB10_19","019_10_19","JOB","10","19","19","Da ma ba a halicce ni ba, da na mutu tun daga cikin cikin uwata na wuce zuwa kabari! ");
INSERT INTO hausa_vpl VALUES ("JB10_20","019_10_20","JOB","10","20","20","’Yan kwanakina ba su kusa ƙarewa ba ne? Ka rabu da ni don in ɗan samu sukuni na ɗan lokaci ");
INSERT INTO hausa_vpl VALUES ("JB10_21","019_10_21","JOB","10","21","21","kafin in koma inda na fito, ƙasa mai duhu da inuwa sosai, ");
INSERT INTO hausa_vpl VALUES ("JB10_22","019_10_22","JOB","10","22","22","zuwa ƙasa mai duhun gaske, da inuwa da hargitsi, inda haske yake kamar duhu.” ");
INSERT INTO hausa_vpl VALUES ("JB11_1","019_11_1","JOB","11","1","1","Sa’an nan Zofar mutumin Na’ama ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB11_2","019_11_2","JOB","11","2","2","“Duk surutun nan ba za a amsa maka ba? Ko mai surutun nan marar laifi ne? ");
INSERT INTO hausa_vpl VALUES ("JB11_3","019_11_3","JOB","11","3","3","Ko maganganun nan naka marasa amfani za su sa mutane su yi maka shiru? Ba wanda zai kwaɓe ka lokacin da kake faɗar maganar da ba daidai ba? ");
INSERT INTO hausa_vpl VALUES ("JB11_4","019_11_4","JOB","11","4","4","Ka ce wa Allah, ‘Abin da na gaskata ba laifi ba ne kuma ni mai tsabta ne a gabanka.’ ");
INSERT INTO hausa_vpl VALUES ("JB11_5","019_11_5","JOB","11","5","5","Da ma Allah zai yi magana, yă buɗe baki yă faɗi wani abin da ka yi da ba daidai ba ");
INSERT INTO hausa_vpl VALUES ("JB11_6","019_11_6","JOB","11","6","6","yă kuma buɗe maka asirin hikima, gama hikima ta gaskiya tana da gefe biyu. Ka san wannan, Allah ya riga ya manta da waɗansu zunubanka. ");
INSERT INTO hausa_vpl VALUES ("JB11_7","019_11_7","JOB","11","7","7","“Ko za ka iya gane al’amuran Allah? Ko za ka iya gane girman asirin Maɗaukaki? ");
INSERT INTO hausa_vpl VALUES ("JB11_8","019_11_8","JOB","11","8","8","Sun fi nisan sama tudu, me za ka iya yi? Sun fi zurfin kabari zurfi, me za ka sani? ");
INSERT INTO hausa_vpl VALUES ("JB11_9","019_11_9","JOB","11","9","9","Tsayinsu ya fi tsawon duniya da kuma fāɗin teku. ");
INSERT INTO hausa_vpl VALUES ("JB11_10","019_11_10","JOB","11","10","10","“In ya zo ya kulle ka a kurkuku ya ce kai mai laifi ne, wa zai hana shi? ");
INSERT INTO hausa_vpl VALUES ("JB11_11","019_11_11","JOB","11","11","11","Ba shakka yana iya gane mutanen da suke marasa gaskiya; kuma in ya ga abin da yake mugu, ba ya kula ne? ");
INSERT INTO hausa_vpl VALUES ("JB11_12","019_11_12","JOB","11","12","12","Amma daƙiƙin mutum ba ya taɓa zama mai hikima kamar dai a ce ba a taɓa haihuwar ɗan aholaki horarre. ");
INSERT INTO hausa_vpl VALUES ("JB11_13","019_11_13","JOB","11","13","13","“Duk da haka in ka miƙa masa zuciyarka, ka kuma miƙa hannuwanka gare shi, ");
INSERT INTO hausa_vpl VALUES ("JB11_14","019_11_14","JOB","11","14","14","in ka kawar da zunubin da yake hannunka, ba ka bar zunubi ya kasance tare da kai ba ");
INSERT INTO hausa_vpl VALUES ("JB11_15","019_11_15","JOB","11","15","15","shi ne za ka iya ɗaga fuskarka ba tare da jin kunya ba; za ka tsaya da ƙarfi kuma ba za ka ji tsoro ba. ");
INSERT INTO hausa_vpl VALUES ("JB11_16","019_11_16","JOB","11","16","16","Ba shakka za ka manta da wahalolinka, za ka tuna da su kamar yadda ruwa yake wucewa. ");
INSERT INTO hausa_vpl VALUES ("JB11_17","019_11_17","JOB","11","17","17","Rayuwarka za tă fi hasken rana haske, duhu kuma zai zama kamar safiya. ");
INSERT INTO hausa_vpl VALUES ("JB11_18","019_11_18","JOB","11","18","18","Za ka zauna lafiya, domin akwai bege; za ka duba kewaye da kai ka huta cikin kwanciyar rai. ");
INSERT INTO hausa_vpl VALUES ("JB11_19","019_11_19","JOB","11","19","19","Za ka kwanta, ba wanda zai sa ka ji tsoro, da yawa za su zo neman taimako a wurinka. ");
INSERT INTO hausa_vpl VALUES ("JB11_20","019_11_20","JOB","11","20","20","Amma idanun mugaye ba za su iya gani ba, kuma ba za su iya tserewa ba; begensu zai zama na mutuwa.” ");
INSERT INTO hausa_vpl VALUES ("JB12_1","019_12_1","JOB","12","1","1","Sai Ayuba ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB12_2","019_12_2","JOB","12","2","2","“Ba shakka ku ne mutanen nan, hikima za tă mutu tare da ku! ");
INSERT INTO hausa_vpl VALUES ("JB12_3","019_12_3","JOB","12","3","3","Amma ni ma ina da hankali kamar ku; ba ku fi ni ba. Wane ne bai san duk waɗannan abubuwan ba? ");
INSERT INTO hausa_vpl VALUES ("JB12_4","019_12_4","JOB","12","4","4","“Na zama abin dariya ga abokaina, ko da yake na yi kira ga Allah ya kuwa amsa mini, duk da haka suka yi mini riya ko da yake ni mai adalci ne kuma marar laifi! ");
INSERT INTO hausa_vpl VALUES ("JB12_5","019_12_5","JOB","12","5","5","Mutanen da ba su da damuwa suna jin daɗin ganin waɗanda suke dab da fāɗuwa. ");
INSERT INTO hausa_vpl VALUES ("JB12_6","019_12_6","JOB","12","6","6","Amma wurin zaman ’yan fashi yana nan ba mai damunsu, waɗanda kuma suke saɓa wa Allah suna zamansu lafiya, har ma da masu ɗaukar allahnsu a hannuwansu. ");
INSERT INTO hausa_vpl VALUES ("JB12_7","019_12_7","JOB","12","7","7","“Amma ka tambayi dabbobi, za su kuma koya maka, ko kuma tsuntsayen sararin sama kuma za su gaya maka. ");
INSERT INTO hausa_vpl VALUES ("JB12_8","019_12_8","JOB","12","8","8","Ko ka yi magana da duniya, za tă kuma koya maka, ko kuma ka bar kifin teku su sanar da kai. ");
INSERT INTO hausa_vpl VALUES ("JB12_9","019_12_9","JOB","12","9","9","Wane ne cikin waɗannan bai san cewa hannun Ubangiji ne ya yi wannan ba? ");
INSERT INTO hausa_vpl VALUES ("JB12_10","019_12_10","JOB","12","10","10","Ran kowace halitta yana a hannunsa, haka kuma numfashin dukan ’yan adam. ");
INSERT INTO hausa_vpl VALUES ("JB12_11","019_12_11","JOB","12","11","11","Ko kunne ba ya gwada kalmomi kamar yadda harshe yake ɗanɗana abinci? ");
INSERT INTO hausa_vpl VALUES ("JB12_12","019_12_12","JOB","12","12","12","Ko ba a wurin tsofaffi ake samun hikima ba? Ba tsawon rai yana kawo ganewa ba? ");
INSERT INTO hausa_vpl VALUES ("JB12_13","019_12_13","JOB","12","13","13","“Allah ne mai iko da kuma hikima, shawara da ganewa nasa ne. ");
INSERT INTO hausa_vpl VALUES ("JB12_14","019_12_14","JOB","12","14","14","Abin da ya rushe ba a iya ginawa ba; in ya kulle mutum ba a iya buɗe shi a sake shi ba. ");
INSERT INTO hausa_vpl VALUES ("JB12_15","019_12_15","JOB","12","15","15","Idan ya hana ruwan sama, za a yi fări; in kuma ya saki ruwa za a yi ambaliya. ");
INSERT INTO hausa_vpl VALUES ("JB12_16","019_12_16","JOB","12","16","16","Shi ne mai ƙarfi da kuma mai nasara; mai ruɗi da wanda aka ruɗa, duk nasa ne. ");
INSERT INTO hausa_vpl VALUES ("JB12_17","019_12_17","JOB","12","17","17","Yakan sa mashawarta su zama marasa hikima yă kuma sa wawaye su zama masu shari’a. ");
INSERT INTO hausa_vpl VALUES ("JB12_18","019_12_18","JOB","12","18","18","Yana cire sarƙar da sarakuna suka ɗaura yă kuma ɗaura musu wata tsumma a kwankwaso. ");
INSERT INTO hausa_vpl VALUES ("JB12_19","019_12_19","JOB","12","19","19","Yakan ƙasƙantar da firistoci yă kuma tumɓuke masu ikon da aka kafa tun da daɗewa. ");
INSERT INTO hausa_vpl VALUES ("JB12_20","019_12_20","JOB","12","20","20","Yana sa amintattun mashawarta su yi shiru yakan kawar da hikimar dattawa. ");
INSERT INTO hausa_vpl VALUES ("JB12_21","019_12_21","JOB","12","21","21","Yakan sa masu iko su ji kunya yă kuma ƙwace ƙarfin masu ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("JB12_22","019_12_22","JOB","12","22","22","Yana buɗe abubuwan da suke cikin duhu yă kuma kawo haske a wuraren da ba haske; ");
INSERT INTO hausa_vpl VALUES ("JB12_23","019_12_23","JOB","12","23","23","yana sa al’ummai su zama manya, sai kuma yă hallaka su; yana sa al’ummai su ƙasaita, yă kuma watsar da su. ");
INSERT INTO hausa_vpl VALUES ("JB12_24","019_12_24","JOB","12","24","24","Yana hana shugabannin duniya ganewa; Ya bar su su yi ta makuwa, su ruɗe, su ɓata. ");
INSERT INTO hausa_vpl VALUES ("JB12_25","019_12_25","JOB","12","25","25","Suna lallube cikin duhu ba haske; yă sa su yi ta tangaɗi kamar bugaggu. ");
INSERT INTO hausa_vpl VALUES ("JB13_1","019_13_1","JOB","13","1","1","“Idanuna sun ga waɗannan duka, kunnuwana sun ji sun kuma gane. ");
INSERT INTO hausa_vpl VALUES ("JB13_2","019_13_2","JOB","13","2","2","Abin da kuka sani, ni ma na sani; ba ku fi ni ba. ");
INSERT INTO hausa_vpl VALUES ("JB13_3","019_13_3","JOB","13","3","3","Amma ina so in yi magana da Maɗaukaki, in kai kukana wurin Allah kai tsaye. ");
INSERT INTO hausa_vpl VALUES ("JB13_4","019_13_4","JOB","13","4","4","Ku kuma kun ishe ni da ƙarairayi; ku likitocin wofi ne, dukanku! ");
INSERT INTO hausa_vpl VALUES ("JB13_5","019_13_5","JOB","13","5","5","In da za ku yi shiru gaba ɗaya! Zai zama muku hikima. ");
INSERT INTO hausa_vpl VALUES ("JB13_6","019_13_6","JOB","13","6","6","Ku ji gardamata yanzu; ku ji roƙon da zai fito daga bakina. ");
INSERT INTO hausa_vpl VALUES ("JB13_7","019_13_7","JOB","13","7","7","Za ku iya yin muguwar magana a madadin Allah? Ko za ku yi ƙarya a madadinsa? ");
INSERT INTO hausa_vpl VALUES ("JB13_8","019_13_8","JOB","13","8","8","Ko za ku nuna masa sonkai? Ko za ku yi gardama a madadinsa? ");
INSERT INTO hausa_vpl VALUES ("JB13_9","019_13_9","JOB","13","9","9","In ya bincike ku zai tarar ba ku da laifi? Ko za ku iya ruɗe shi yadda za ku ruɗi mutane? ");
INSERT INTO hausa_vpl VALUES ("JB13_10","019_13_10","JOB","13","10","10","Ba shakka zai kwaɓe ku in kun nuna sonkai a ɓoye. ");
INSERT INTO hausa_vpl VALUES ("JB13_11","019_13_11","JOB","13","11","11","Ko ikonsa ba ya ba ku tsoro? Tsoronsa ba zai auka muku ba? ");
INSERT INTO hausa_vpl VALUES ("JB13_12","019_13_12","JOB","13","12","12","Duk surutanku kamar toka suke; kāriyarku na yimɓu ne. ");
INSERT INTO hausa_vpl VALUES ("JB13_13","019_13_13","JOB","13","13","13","“Ku yi shiru zan yi magana; sa’an nan abin da zai same ni yă same ni. ");
INSERT INTO hausa_vpl VALUES ("JB13_14","019_13_14","JOB","13","14","14","Don me na sa kaina cikin hatsari na yi kasada da raina? ");
INSERT INTO hausa_vpl VALUES ("JB13_15","019_13_15","JOB","13","15","15","Ko da zai kashe ni ne, begena a cikinsa zai kasance; ba shakka zan kāre kaina a gabansa ");
INSERT INTO hausa_vpl VALUES ("JB13_16","019_13_16","JOB","13","16","16","lalle wannan zai kawo mini kuɓuta gama ba wani marar tsoron Allah da zai iya zuwa wurinsa! ");
INSERT INTO hausa_vpl VALUES ("JB13_17","019_13_17","JOB","13","17","17","Ku saurara da kyau ku ji abin da zan faɗa; bari kunnuwanku su ji abin da zan ce. ");
INSERT INTO hausa_vpl VALUES ("JB13_18","019_13_18","JOB","13","18","18","Yanzu da na shirya ƙarata, na san za a ce ba ni da laifi. ");
INSERT INTO hausa_vpl VALUES ("JB13_19","019_13_19","JOB","13","19","19","Ko wani zai ce ga laifin da na yi? In an same ni da laifi, zan yi shiru in mutu. ");
INSERT INTO hausa_vpl VALUES ("JB13_20","019_13_20","JOB","13","20","20","“Kai dai biya mini waɗannan bukatu biyu kawai ya Allah, ba zan kuwa ɓoye daga gare ka ba; ");
INSERT INTO hausa_vpl VALUES ("JB13_21","019_13_21","JOB","13","21","21","Ka janye hannunka nesa da ni, ka daina ba ni tsoro da bantsoronka. ");
INSERT INTO hausa_vpl VALUES ("JB13_22","019_13_22","JOB","13","22","22","Sa’an nan ka kira ni, zan kuwa amsa, ko kuma ka bar ni in yi magana sai ka amsa mini. ");
INSERT INTO hausa_vpl VALUES ("JB13_23","019_13_23","JOB","13","23","23","Abubuwa nawa na yi waɗanda ba daidai ba, kuma zunubi ne? Ka nuna mini laifina da zunubina. ");
INSERT INTO hausa_vpl VALUES ("JB13_24","019_13_24","JOB","13","24","24","Don me ka ɓoye mini fuskarka; ka kuma sa na zama kamar maƙiyinka? ");
INSERT INTO hausa_vpl VALUES ("JB13_25","019_13_25","JOB","13","25","25","Ko za a wahalar da ganye wanda iska take hurawa? Ko za ka bi busasshiyar ciyawa? ");
INSERT INTO hausa_vpl VALUES ("JB13_26","019_13_26","JOB","13","26","26","Gama ka rubuta abubuwa marasa daɗi game da ni; ka sa na yi gādon zunuban ƙuruciyata. ");
INSERT INTO hausa_vpl VALUES ("JB13_27","019_13_27","JOB","13","27","27","Ka daure ƙafafuna da sarƙa; kana kallon duk inda na taka ta wurin sa shaida a tafin ƙafafuna. ");
INSERT INTO hausa_vpl VALUES ("JB13_28","019_13_28","JOB","13","28","28","“Haka mutum yake lalacewa kamar ruɓaɓɓen abu, kamar rigar da asu ya cinye. ");
INSERT INTO hausa_vpl VALUES ("JB14_1","019_14_1","JOB","14","1","1","“Mutum haihuwar mace kwanakinsa kaɗan ne, kuma cike da wahala. ");
INSERT INTO hausa_vpl VALUES ("JB14_2","019_14_2","JOB","14","2","2","Yana tasowa kamar fure yana kuma shuɗewa; kamar inuwa, ba ya daɗewa. ");
INSERT INTO hausa_vpl VALUES ("JB14_3","019_14_3","JOB","14","3","3","Za ka zura ido a kan irin wannan ne? Za ka kawo shi gaba don ka yi masa shari’a? ");
INSERT INTO hausa_vpl VALUES ("JB14_4","019_14_4","JOB","14","4","4","Wane ne zai iya kawo abin da yake da tsarki daga cikin abu marar tsarki? Babu! ");
INSERT INTO hausa_vpl VALUES ("JB14_5","019_14_5","JOB","14","5","5","An lissafta kwanakin mutum; ka riga ka ɗibar masa watanni, ka yi masa iyaka, ba zai iya wuce iyakar ba. ");
INSERT INTO hausa_vpl VALUES ("JB14_6","019_14_6","JOB","14","6","6","Saboda haka ka kawar da kanka daga gare shi, ka rabu da shi har sai ya cika lokacinsa kamar mutumin da aka ɗauki hayarsa. ");
INSERT INTO hausa_vpl VALUES ("JB14_7","019_14_7","JOB","14","7","7","“Aƙalla itace yana da bege. In an sare shi, zai sāke tsira, zai tohu da kyau. ");
INSERT INTO hausa_vpl VALUES ("JB14_8","019_14_8","JOB","14","8","8","Ko da jijiyoyin itacen sun tsufa a cikin ƙasa kuma kututturensa ya mutu a cikin ƙasa. ");
INSERT INTO hausa_vpl VALUES ("JB14_9","019_14_9","JOB","14","9","9","Daga ya ji ƙanshin ruwa zai tohu yă yi tsiro kamar shuka. ");
INSERT INTO hausa_vpl VALUES ("JB14_10","019_14_10","JOB","14","10","10","Amma mutum yana mutuwa a bizne shi; daga ya ja numfashinsa na ƙarshe, shi ke nan. ");
INSERT INTO hausa_vpl VALUES ("JB14_11","019_14_11","JOB","14","11","11","Kamar yadda ruwa yake bushewa a teku ko a gaɓar rafi sai wurin yă bushe, ");
INSERT INTO hausa_vpl VALUES ("JB14_12","019_14_12","JOB","14","12","12","haka mutum zai kwanta ba zai tashi ba; har sai duniya ta shuɗe mutane ba za su farka ba, ba za su tashi daga barcinsu ba. ");
INSERT INTO hausa_vpl VALUES ("JB14_13","019_14_13","JOB","14","13","13","“Da ma za ka ɓoye ni a cikin kabari ka ɓoye ni har sai fushinka ya wuce! In da za ka keɓe mini lokaci sa’an nan ka tuna da ni! ");
INSERT INTO hausa_vpl VALUES ("JB14_14","019_14_14","JOB","14","14","14","In mutum ya mutu, ko zai sāke rayuwa? In haka ne zan daure kwanakin da nake shan wahala har su wuce. ");
INSERT INTO hausa_vpl VALUES ("JB14_15","019_14_15","JOB","14","15","15","Za ka kira zan kuwa amsa maka; za ka yi marmarin abin da hannunka ya halitta. ");
INSERT INTO hausa_vpl VALUES ("JB14_16","019_14_16","JOB","14","16","16","Ba shakka a lokacin ne za ka lura da matakaina amma ba za ka kula da zunubaina ba. ");
INSERT INTO hausa_vpl VALUES ("JB14_17","019_14_17","JOB","14","17","17","Za a daure laifofina a cikin jaka; za ka rufe zunubaina. ");
INSERT INTO hausa_vpl VALUES ("JB14_18","019_14_18","JOB","14","18","18","“Amma kamar yadda manyan duwatsu suke fāɗuwa su farfashe su kuma gusa daga wurarensu, ");
INSERT INTO hausa_vpl VALUES ("JB14_19","019_14_19","JOB","14","19","19","yadda ruwa yakan zaizaye duwatsu ruwa mai ƙarfi kuma yă kwashe turɓayar ƙasa, haka kake barin mutum ba bege. ");
INSERT INTO hausa_vpl VALUES ("JB14_20","019_14_20","JOB","14","20","20","Ka sha ƙarfinsa gaba ɗaya, sai ya ɓace, ka sauya yanayinsa ka kuma kore shi. ");
INSERT INTO hausa_vpl VALUES ("JB14_21","019_14_21","JOB","14","21","21","Ko an martaba ’ya’yansa maza, ba zai sani ba; Ko an wulaƙanta su, ba zai gani ba. ");
INSERT INTO hausa_vpl VALUES ("JB14_22","019_14_22","JOB","14","22","22","Zafin jikinsa kaɗai yake ji yana kuka wa kansa ne kaɗai.” ");
INSERT INTO hausa_vpl VALUES ("JB15_1","019_15_1","JOB","15","1","1","Sai Elifaz mutumin Teman ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB15_2","019_15_2","JOB","15","2","2","“Mutum mai hikima zai amsa da surutai marasa kan gado ko yă cika cikinsa da iskar gabas? ");
INSERT INTO hausa_vpl VALUES ("JB15_3","019_15_3","JOB","15","3","3","Ko zai yi gardama da maganganun wofi maganganu marasa amfani? ");
INSERT INTO hausa_vpl VALUES ("JB15_4","019_15_4","JOB","15","4","4","Amma ka ma rena Allah ka hana a yi addu’a gare shi. ");
INSERT INTO hausa_vpl VALUES ("JB15_5","019_15_5","JOB","15","5","5","Zunubanka ne suke gaya maka abin da za ka ce; kana magana kamar mai wayo. ");
INSERT INTO hausa_vpl VALUES ("JB15_6","019_15_6","JOB","15","6","6","Bakinka zai kai ka yă baro, ba nawa ba; maganar bakinka za tă juya a kanka. ");
INSERT INTO hausa_vpl VALUES ("JB15_7","019_15_7","JOB","15","7","7","“Kai ne mutum na farko da aka fara haihuwa? Ko kai ne aka fara halitta kafin tuddai? ");
INSERT INTO hausa_vpl VALUES ("JB15_8","019_15_8","JOB","15","8","8","Kana sauraron shawarar Allah? Ko kana gani kai kaɗai ne mai hikima? ");
INSERT INTO hausa_vpl VALUES ("JB15_9","019_15_9","JOB","15","9","9","Me ka sani da ba mu sani ba? Wane fahimi kake da shi da ba mu da shi? ");
INSERT INTO hausa_vpl VALUES ("JB15_10","019_15_10","JOB","15","10","10","Masu furfura da tsofaffi suna gefenmu mutanen da sun girme babanka. ");
INSERT INTO hausa_vpl VALUES ("JB15_11","019_15_11","JOB","15","11","11","Ta’aziyyar Allah ba tă ishe ka ba. Maganarsa mai laushi ba tă ishe ka ba? ");
INSERT INTO hausa_vpl VALUES ("JB15_12","019_15_12","JOB","15","12","12","Don me ka bar zuciyarka ta kwashe ka, kuma don me idanunka suke haske, ");
INSERT INTO hausa_vpl VALUES ("JB15_13","019_15_13","JOB","15","13","13","har kake fushi da Allah kake kuma faɗar waɗannan maganganu daga bakinka? ");
INSERT INTO hausa_vpl VALUES ("JB15_14","019_15_14","JOB","15","14","14","“Mene ne mutum, har da zai zama da tsarki, ko kuma mace ta haife shi, har yă iya zama mai adalci? ");
INSERT INTO hausa_vpl VALUES ("JB15_15","019_15_15","JOB","15","15","15","In Allah bai nuna amincewa ga tsarkakansa ba, in har sammai ba su da tsarki a idonsa, ");
INSERT INTO hausa_vpl VALUES ("JB15_16","019_15_16","JOB","15","16","16","mutum fa, wanda yake da mugunta da lalacewa, wanda yake shan mugunta kamar ruwa! ");
INSERT INTO hausa_vpl VALUES ("JB15_17","019_15_17","JOB","15","17","17","“Ka saurare ni, zan kuma yi maka bayani; bari in gaya maka abin da na gani, ");
INSERT INTO hausa_vpl VALUES ("JB15_18","019_15_18","JOB","15","18","18","abin da masu hikima suka ce, ba tare da sun ɓoye wani abu da suka samu daga wurin iyayensu ba ");
INSERT INTO hausa_vpl VALUES ("JB15_19","019_15_19","JOB","15","19","19","(waɗanda su ne masu ƙasar kafin baƙi su shigo ƙasar). ");
INSERT INTO hausa_vpl VALUES ("JB15_20","019_15_20","JOB","15","20","20","Dukan kwanakin ransa mugu yana shan wahala, wahala kaɗai zai yi ta sha. ");
INSERT INTO hausa_vpl VALUES ("JB15_21","019_15_21","JOB","15","21","21","Ƙara mai bantsoro za tă cika kunnuwansa ’yan fashi za su kai masa hari. ");
INSERT INTO hausa_vpl VALUES ("JB15_22","019_15_22","JOB","15","22","22","Yana jin tsoron duhu domin za a kashe shi da takobi. ");
INSERT INTO hausa_vpl VALUES ("JB15_23","019_15_23","JOB","15","23","23","Yana ta yawo, abinci don ungulaye; ya san ranar duhu tana kusa. ");
INSERT INTO hausa_vpl VALUES ("JB15_24","019_15_24","JOB","15","24","24","Ɓacin rai da baƙin ciki sun cika shi, kamar sarkin da yake shirin yaƙi, ");
INSERT INTO hausa_vpl VALUES ("JB15_25","019_15_25","JOB","15","25","25","domin ya nuna wa Allah yatsa ya rena Allah Maɗaukaki, ");
INSERT INTO hausa_vpl VALUES ("JB15_26","019_15_26","JOB","15","26","26","ya tasar masa da faɗa da garkuwa mai kauri da kuma ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("JB15_27","019_15_27","JOB","15","27","27","“Ko da yake fuskarsa ta cika da kumatu kuma yana da tsoka ko’ina, ");
INSERT INTO hausa_vpl VALUES ("JB15_28","019_15_28","JOB","15","28","28","zai yi gādon garuruwan da suka lalace, da kuma gidajen da ba wanda yake zama a ciki, gidajen da sun zama tarkace. ");
INSERT INTO hausa_vpl VALUES ("JB15_29","019_15_29","JOB","15","29","29","Ba zai sāke zama mai arziki ba, dukiyarsa ba za tă dawwama ba, abin da ya mallaka kuma ba zai bazu a ƙasar ba. ");
INSERT INTO hausa_vpl VALUES ("JB15_30","019_15_30","JOB","15","30","30","Ba zai tsere wa duhu ba; wuta za tă ƙona rassansa, kuma numfashi daga bakin Allah zai hallaka shi. ");
INSERT INTO hausa_vpl VALUES ("JB15_31","019_15_31","JOB","15","31","31","Kada yă ruɗi kansa ta wurin dogara ga abin da ba shi da amfani domin ba zai samu wani abu ba daga ciki. ");
INSERT INTO hausa_vpl VALUES ("JB15_32","019_15_32","JOB","15","32","32","Kafin lokacinsa yă cika, za a gama biyansa duka, kuma rassansa ba za su ba da amfani ba. ");
INSERT INTO hausa_vpl VALUES ("JB15_33","019_15_33","JOB","15","33","33","Zai zama kamar itacen inabi wanda ’ya’yansa suka kakkaɓe kafin su nuna, kamar itacen zaitun zai zubar da furensa. ");
INSERT INTO hausa_vpl VALUES ("JB15_34","019_15_34","JOB","15","34","34","Gama marasa tsoron Allah za su zama marasa ba da ’ya’ya, wuta kuma za tă ƙona tenti na masu son cin hanci. ");
INSERT INTO hausa_vpl VALUES ("JB15_35","019_15_35","JOB","15","35","35","Suna yin cikin rikici su kuma haifi mugunta; cikinsu yana cike da ruɗami.” ");
INSERT INTO hausa_vpl VALUES ("JB16_1","019_16_1","JOB","16","1","1","Sai Ayuba ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB16_2","019_16_2","JOB","16","2","2","“Na ji abubuwa da yawa kamar waɗannan; dukanku ba ku iya ta’aziyya ba! ");
INSERT INTO hausa_vpl VALUES ("JB16_3","019_16_3","JOB","16","3","3","Dogayen surutanku ba sa ƙare ne? Me yake sa kuke ta yin waɗannan surutai har kuke cin gaba da yin gardama? ");
INSERT INTO hausa_vpl VALUES ("JB16_4","019_16_4","JOB","16","4","4","Ni ma zan iya yin maganganu kamar yadda kuke yi in da kuna cikin halin da nake; zan iya faɗar duk abubuwan da kuke faɗi, in kaɗa muku kaina. ");
INSERT INTO hausa_vpl VALUES ("JB16_5","019_16_5","JOB","16","5","5","Amma bakina zai ƙarfafa ku; ta’aziyyar da za tă fito daga bakina za tă kawar muku da ɓacin zuciyarku. ");
INSERT INTO hausa_vpl VALUES ("JB16_6","019_16_6","JOB","16","6","6","“Duk da haka in na yi magana, ba na samun sauƙi; in ma na yi shiru zafin ba ya tafiya. ");
INSERT INTO hausa_vpl VALUES ("JB16_7","019_16_7","JOB","16","7","7","Ba shakka ya Allah ka gajiyar da ni; ka ɓata gidana gaba ɗaya. ");
INSERT INTO hausa_vpl VALUES ("JB16_8","019_16_8","JOB","16","8","8","Ka daure ni, ya kuma zama shaida; yadda na rame sai ƙasusuwa, wannan ya sa ake gani kamar don ni mai zunubi ne shi ya sa. ");
INSERT INTO hausa_vpl VALUES ("JB16_9","019_16_9","JOB","16","9","9","Allah ya kai mini hari ya yi kaca-kaca da ni cikin fushinsa yana cizon haƙoransa don fushin da yake yi da ni; ya zura mini ido. ");
INSERT INTO hausa_vpl VALUES ("JB16_10","019_16_10","JOB","16","10","10","Mutane suka buɗe baki suka yi mini riyar reni; suka yi mini ba’a suka haɗu suka tayar mini. ");
INSERT INTO hausa_vpl VALUES ("JB16_11","019_16_11","JOB","16","11","11","Allah ya bashe ni ga mugayen mutane, ya jefa ni hannun mugaye. ");
INSERT INTO hausa_vpl VALUES ("JB16_12","019_16_12","JOB","16","12","12","Dā ina zamana lafiya kome yana tafiya daidai; amma ya ragargaza ni; ya shaƙe ni a wuya; ya murƙushe ni na zama abin barata gare shi; ");
INSERT INTO hausa_vpl VALUES ("JB16_13","019_16_13","JOB","16","13","13","maharbansa sun kewaye ni. Ba tausayi, ya soke ni a ƙodata har jini ya zuba a ƙasa. ");
INSERT INTO hausa_vpl VALUES ("JB16_14","019_16_14","JOB","16","14","14","Ya ji mini rauni a kai a kai ya auko mini kamar mai yaƙi. ");
INSERT INTO hausa_vpl VALUES ("JB16_15","019_16_15","JOB","16","15","15","“Ina makoki saye da tsummoki na ɓoye fuskata a cikin ƙura. ");
INSERT INTO hausa_vpl VALUES ("JB16_16","019_16_16","JOB","16","16","16","Fuskata ta yi ja don kuka idanuna sun kukumbura; ");
INSERT INTO hausa_vpl VALUES ("JB16_17","019_16_17","JOB","16","17","17","duk da haka hannuwana ba su aikata ɓarna ba kuma addu’ata mai tsabta ce. ");
INSERT INTO hausa_vpl VALUES ("JB16_18","019_16_18","JOB","16","18","18","“Ya duniya, kada ki ɓoye jinina; bari yă yi kuka a madadina! ");
INSERT INTO hausa_vpl VALUES ("JB16_19","019_16_19","JOB","16","19","19","Ko yanzu haka shaidata tana sama; wanda zai tsaya mini yana sama. ");
INSERT INTO hausa_vpl VALUES ("JB16_20","019_16_20","JOB","16","20","20","Shi mai yin roƙo a madadina abokina ne yayinda nake kuka ga Allah; ");
INSERT INTO hausa_vpl VALUES ("JB16_21","019_16_21","JOB","16","21","21","a madadin mutum ya yi roƙo ga Allah kamar yadda mutum yakan yi roƙo domin abokinsa. ");
INSERT INTO hausa_vpl VALUES ("JB16_22","019_16_22","JOB","16","22","22","“Shekaru kaɗan suka rage in kama hanyar da ba a komawa. ");
INSERT INTO hausa_vpl VALUES ("JB17_1","019_17_1","JOB","17","1","1","Na karaya, kwanakina sun kusa ƙarewa, kabari yana jirana. ");
INSERT INTO hausa_vpl VALUES ("JB17_2","019_17_2","JOB","17","2","2","Ba shakka masu yi mini ba’a suna kewaye da ni; idanuna suna ganin tsokanar da suke yi mini. ");
INSERT INTO hausa_vpl VALUES ("JB17_3","019_17_3","JOB","17","3","3","“Ya Allah, ka ba ni abin da ka yi mini alkawari. Wane ne zai kāre ni? ");
INSERT INTO hausa_vpl VALUES ("JB17_4","019_17_4","JOB","17","4","4","Ka rufe zuciyarsu yadda ba za su iya ganewa ba, saboda haka ba za ka bari su yi nasara ba. ");
INSERT INTO hausa_vpl VALUES ("JB17_5","019_17_5","JOB","17","5","5","In mutum ya juya wa abokansa baya don a ba shi wata lada ’ya’yansa za su makance. ");
INSERT INTO hausa_vpl VALUES ("JB17_6","019_17_6","JOB","17","6","6","“Allah ya sa na zama abin da kowa yake magana a kai wanda kowa yake tofa wa miyau a fuska. ");
INSERT INTO hausa_vpl VALUES ("JB17_7","019_17_7","JOB","17","7","7","Idanuna ba sa gani sosai don baƙin ciki; jikina ya zama kamar inuwa kawai ");
INSERT INTO hausa_vpl VALUES ("JB17_8","019_17_8","JOB","17","8","8","Mutanen da suke masu adalci wannan abu ya ba su tsoro; marasa laifi sun tayar wa marasa tsoron Allah. ");
INSERT INTO hausa_vpl VALUES ("JB17_9","019_17_9","JOB","17","9","9","Duk da haka, masu adalci za su ci gaba da tafiya a kan hanyarsu, waɗanda hannuwansu suke da tsabta kuma za su ƙara ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("JB17_10","019_17_10","JOB","17","10","10","“Amma ku zo dukanku, ku sāke gwadawa! Ba zan sami mutum ɗaya mai hikima ba a cikinku. ");
INSERT INTO hausa_vpl VALUES ("JB17_11","019_17_11","JOB","17","11","11","Kwanakina sun wuce, shirye-shiryena sun ɓaci haka kuma abubuwan da zuciyata take so. ");
INSERT INTO hausa_vpl VALUES ("JB17_12","019_17_12","JOB","17","12","12","Mutanen nan sun juya rana ta zama dare. A tsakiyar duhu suka ce, ‘Haske yana kusa.’ ");
INSERT INTO hausa_vpl VALUES ("JB17_13","019_17_13","JOB","17","13","13","In kabari ne begen da nake da shi kaɗai, in na shimfiɗa gadona a cikin duhu, ");
INSERT INTO hausa_vpl VALUES ("JB17_14","019_17_14","JOB","17","14","14","In na ce wa kabari, ‘Kai ne mahaifina,’ tsutsa kuma ke ce, ‘Mahaifiyata’ ko ‘’yar’uwata,’ ");
INSERT INTO hausa_vpl VALUES ("JB17_15","019_17_15","JOB","17","15","15","To, ina begena yake? Wane ne zai iya ganin wani bege domina? ");
INSERT INTO hausa_vpl VALUES ("JB17_16","019_17_16","JOB","17","16","16","Ko begena zai tafi tare da ni zuwa kabari ne? Ko tare za a bizne mu cikin ƙura?” ");
INSERT INTO hausa_vpl VALUES ("JB18_1","019_18_1","JOB","18","1","1","Sai Bildad mutumin Shuwa ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB18_2","019_18_2","JOB","18","2","2","“Yaushe za ka gama maganganun nan? Ka dawo da hankalinka sa’an nan za mu iya yin magana. ");
INSERT INTO hausa_vpl VALUES ("JB18_3","019_18_3","JOB","18","3","3","Don me muke kamar shanu a wurinka, ka ɗauke mu mutanen wofi? ");
INSERT INTO hausa_vpl VALUES ("JB18_4","019_18_4","JOB","18","4","4","Kai da ka yayyage kanka don haushi, za a yashe duniya saboda kai ne? Ko kuma duwatsu za su matsa daga wurinsu? ");
INSERT INTO hausa_vpl VALUES ("JB18_5","019_18_5","JOB","18","5","5","“An kashe fitilar mugu; harshen wutarsa ya daina ci. ");
INSERT INTO hausa_vpl VALUES ("JB18_6","019_18_6","JOB","18","6","6","Wutar cikin tentinsa ta zama duhu; fitilar da take kusa da shi ta mutu. ");
INSERT INTO hausa_vpl VALUES ("JB18_7","019_18_7","JOB","18","7","7","Ƙarfin takawarsa ya ragu; dabararsa ta ja fāɗuwarsa. ");
INSERT INTO hausa_vpl VALUES ("JB18_8","019_18_8","JOB","18","8","8","Ƙafafunsa sun kai shi cikin raga, yana ta yawo a cikin ragar. ");
INSERT INTO hausa_vpl VALUES ("JB18_9","019_18_9","JOB","18","9","9","Tarko ya kama ɗiɗɗigensa; tarko ya riƙe shi kam. ");
INSERT INTO hausa_vpl VALUES ("JB18_10","019_18_10","JOB","18","10","10","An ɓoye masa igiya da za tă zarge shi a ƙasa; an sa masa tarko a kan hanyar da zai bi. ");
INSERT INTO hausa_vpl VALUES ("JB18_11","019_18_11","JOB","18","11","11","Tsoro duk ya kewaye shi ta kowane gefe yana bin shi duk inda ya je. ");
INSERT INTO hausa_vpl VALUES ("JB18_12","019_18_12","JOB","18","12","12","Masifa tana jiransa; bala’i yana shirye yă fāɗa masa a lokacin da zai fāɗi. ");
INSERT INTO hausa_vpl VALUES ("JB18_13","019_18_13","JOB","18","13","13","Ya cinye wani sashe na gaɓar jikinsa; ɗan fari na mutuwa ya cinye ƙafafunsa. ");
INSERT INTO hausa_vpl VALUES ("JB18_14","019_18_14","JOB","18","14","14","An yage shi daga zaman lafiyar da yake yi a cikin tentinsa aka sa shi tsoro sosai. ");
INSERT INTO hausa_vpl VALUES ("JB18_15","019_18_15","JOB","18","15","15","Wuta ta cinye tentinsa; farar wuta ta rufe wurin da yake zama. ");
INSERT INTO hausa_vpl VALUES ("JB18_16","019_18_16","JOB","18","16","16","Jijiyoyinsa sun bushe a ƙasa rassansa sun mutu a sama. ");
INSERT INTO hausa_vpl VALUES ("JB18_17","019_18_17","JOB","18","17","17","An manta da shi a duniya; ba wanda yake ƙara tunawa da shi. ");
INSERT INTO hausa_vpl VALUES ("JB18_18","019_18_18","JOB","18","18","18","An tura shi daga cikin haske zuwa cikin duhu, an kore shi daga duniya. ");
INSERT INTO hausa_vpl VALUES ("JB18_19","019_18_19","JOB","18","19","19","Ba shi da ’ya’ya ko zuriya cikin mutanensa, ba sauran wanda yake a raye a wurin da ya taɓa zama. ");
INSERT INTO hausa_vpl VALUES ("JB18_20","019_18_20","JOB","18","20","20","Mutanen Yamma suna mamakin abin da ya faru da shi; tsoro ya kama mutanen gabas. ");
INSERT INTO hausa_vpl VALUES ("JB18_21","019_18_21","JOB","18","21","21","Ba shakka haka wurin zaman mugun mutum yake, haka wurin zaman wanda bai san Allah ba yake.” ");
INSERT INTO hausa_vpl VALUES ("JB19_1","019_19_1","JOB","19","1","1","Sai Ayuba ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB19_2","019_19_2","JOB","19","2","2","“Har yaushe za ku yi ta ba ni azaba ku kuma murƙushe ni da maganganunku? ");
INSERT INTO hausa_vpl VALUES ("JB19_3","019_19_3","JOB","19","3","3","Yanzu sau goma ke nan kuna wulaƙanta ni, kuna kai mini hari na rashin kunya. ");
INSERT INTO hausa_vpl VALUES ("JB19_4","019_19_4","JOB","19","4","4","In gaskiya ne na yi laifi, kuskurena ya rage nawa. ");
INSERT INTO hausa_vpl VALUES ("JB19_5","019_19_5","JOB","19","5","5","In kuwa za ku ɗaukaka kanku a kaina kuna ɗauka wahalar da nake sha domin na yi laifi ne, ");
INSERT INTO hausa_vpl VALUES ("JB19_6","019_19_6","JOB","19","6","6","sai ku san cewa Allah ya yi mini ba daidai ba ya kewaye ni da ragarsa. ");
INSERT INTO hausa_vpl VALUES ("JB19_7","019_19_7","JOB","19","7","7","“Ko da yake na yi kuka cewa, ‘An yi mini ba daidai ba!’ Ba a amsa mini ba; ko da yake na nemi taimako, ba a yi adalci ba. ");
INSERT INTO hausa_vpl VALUES ("JB19_8","019_19_8","JOB","19","8","8","Ya tare mini hanya yadda ba zan iya wucewa ba; ya rufe hanyata da duhu. ");
INSERT INTO hausa_vpl VALUES ("JB19_9","019_19_9","JOB","19","9","9","Ya cire darajar da nake da ita, ya kuma cire rawani daga kaina. ");
INSERT INTO hausa_vpl VALUES ("JB19_10","019_19_10","JOB","19","10","10","Ya yi kaca-kaca da ni har sai da na ƙare; ya tuge begen da nake da shi kamar itace. ");
INSERT INTO hausa_vpl VALUES ("JB19_11","019_19_11","JOB","19","11","11","Yana jin haushina ya lissafta ni cikin maƙiyansa. ");
INSERT INTO hausa_vpl VALUES ("JB19_12","019_19_12","JOB","19","12","12","Rundunarsa ta zo da ƙarfi; suka kafa sansani kewaye da ni, suka zagaye tentina. ");
INSERT INTO hausa_vpl VALUES ("JB19_13","019_19_13","JOB","19","13","13","“Ya raba ni da ’yan’uwana maza; abokaina sun zama baƙi gare ni. ");
INSERT INTO hausa_vpl VALUES ("JB19_14","019_19_14","JOB","19","14","14","Dangina sun tafi; abokaina na kurkusa sun manta da ni. ");
INSERT INTO hausa_vpl VALUES ("JB19_15","019_19_15","JOB","19","15","15","Waɗanda sukan ziyarce ni, da masu yi mini aiki mata sun ɗauke ni baƙo. ");
INSERT INTO hausa_vpl VALUES ("JB19_16","019_19_16","JOB","19","16","16","Na kira bawana, amma bai amsa ba, ko da yake na roƙe shi da bakina. ");
INSERT INTO hausa_vpl VALUES ("JB19_17","019_19_17","JOB","19","17","17","Numfashina yana ɓata wa matata rai; ’yan’uwana sun ƙi ni. ");
INSERT INTO hausa_vpl VALUES ("JB19_18","019_19_18","JOB","19","18","18","Har ’yan yara suna rena ni; in sun gan ni sai su fara yi mini riyar reni. ");
INSERT INTO hausa_vpl VALUES ("JB19_19","019_19_19","JOB","19","19","19","Duk abokaina sun yashe ni; waɗanda nake ƙauna sun zama ba sa ƙaunata. ");
INSERT INTO hausa_vpl VALUES ("JB19_20","019_19_20","JOB","19","20","20","Ni ba kome ba ne sai dai fata da ƙashi, da ƙyar na tsira. ");
INSERT INTO hausa_vpl VALUES ("JB19_21","019_19_21","JOB","19","21","21","“Ku tausaya mini, abokaina, ku ji tausayina, gama hannun Allah ya sauko a kaina. ");
INSERT INTO hausa_vpl VALUES ("JB19_22","019_19_22","JOB","19","22","22","Don me kuke fafarata kamar yadda Allah yake yi? Ba ku gaji da yagar fatata ba? ");
INSERT INTO hausa_vpl VALUES ("JB19_23","019_19_23","JOB","19","23","23","“Kash, da ma a ce ana rubuta maganganuna, da an rubuta su a littafi, ");
INSERT INTO hausa_vpl VALUES ("JB19_24","019_19_24","JOB","19","24","24","a rubuta su da ƙarfe a kan dutse don su dawwama har abada! ");
INSERT INTO hausa_vpl VALUES ("JB19_25","019_19_25","JOB","19","25","25","Na san wanda zai fanshe ni yana nan da rai, kuma a ƙarshe zai tsaya a kan duniya. ");
INSERT INTO hausa_vpl VALUES ("JB19_26","019_19_26","JOB","19","26","26","Kuma bayan an hallaka fatata, duk da haka a cikin jiki zan ga Allah. ");
INSERT INTO hausa_vpl VALUES ("JB19_27","019_19_27","JOB","19","27","27","Zan gan shi da kaina da idanuna, Ni, ba wani ba ne. Zuciyata ta cika da wannan tunani! ");
INSERT INTO hausa_vpl VALUES ("JB19_28","019_19_28","JOB","19","28","28","“In kuka ce, ‘Za ku ci gaba da matsa mini, tun da shi ne tushen damuwa,’ ");
INSERT INTO hausa_vpl VALUES ("JB19_29","019_19_29","JOB","19","29","29","sai ku ma ku ji tsoron takobin; gama fushi yakan kawo hukunci ta wurin takobi, sa’an nan za ku san cewa akwai shari’a.” ");
INSERT INTO hausa_vpl VALUES ("JB20_1","019_20_1","JOB","20","1","1","Sai Zofar mutumin Na’ama ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB20_2","019_20_2","JOB","20","2","2","“Tunanin da ya dame ni ya sa dole in amsa domin abin ya dame ni sosai. ");
INSERT INTO hausa_vpl VALUES ("JB20_3","019_20_3","JOB","20","3","3","Na ji wani zargin da ka yi mini na reni, kuma yadda na gane, shi ya sa zan ba da amsa. ");
INSERT INTO hausa_vpl VALUES ("JB20_4","019_20_4","JOB","20","4","4","“Ba shakka ka san yadda abin yake tuntuni, tun da aka sa mutum cikin duniya, ");
INSERT INTO hausa_vpl VALUES ("JB20_5","019_20_5","JOB","20","5","5","mugun mutum bai taɓa daɗewa ba, farin cikin mutum na ɗan gajeren lokaci ne. ");
INSERT INTO hausa_vpl VALUES ("JB20_6","019_20_6","JOB","20","6","6","Ko da ya ƙasaita ya kai sararin sama, kansa kuma yana taɓa gizagizai. ");
INSERT INTO hausa_vpl VALUES ("JB20_7","019_20_7","JOB","20","7","7","Zai hallaka har abada, kamar bayan gidansa; waɗanda suka gan shi za su ce, ‘Ina yake?’ ");
INSERT INTO hausa_vpl VALUES ("JB20_8","019_20_8","JOB","20","8","8","Kamar mafarki haka zai ɓace, ba za a ƙara ganinsa ba zai ɓace kamar wahayi da dare. ");
INSERT INTO hausa_vpl VALUES ("JB20_9","019_20_9","JOB","20","9","9","Idon da ya gan shi ba zai ƙara ganinsa ba; wurin zamansa ba zai sāke ganinsa ba. ");
INSERT INTO hausa_vpl VALUES ("JB20_10","019_20_10","JOB","20","10","10","Dole ’ya’yansa su mayar wa matalauta abin da ya kamata; dole hannuwansa su mayar da dukiyarsa. ");
INSERT INTO hausa_vpl VALUES ("JB20_11","019_20_11","JOB","20","11","11","Jin ƙarfi da ya cika ƙasusuwansa zai kwantar da shi a cikin ƙura. ");
INSERT INTO hausa_vpl VALUES ("JB20_12","019_20_12","JOB","20","12","12","“Ko da yake mugunta tana da daɗi a bakinsa kuma yana ɓoye ta a harshensa, ");
INSERT INTO hausa_vpl VALUES ("JB20_13","019_20_13","JOB","20","13","13","ko da yake ba zai iya rabuwa da ita ba, yana kuma ajiye ta a bakinsa, ");
INSERT INTO hausa_vpl VALUES ("JB20_14","019_20_14","JOB","20","14","14","duk da haka abincin da ya ci zai zama da tsami a cikin cikinsa; zai zama kamar dafin maciji a cikinsa. ");
INSERT INTO hausa_vpl VALUES ("JB20_15","019_20_15","JOB","20","15","15","Zai haras da dukiyar da ya haɗiye; Allah zai sa cikinsa yă haras da su. ");
INSERT INTO hausa_vpl VALUES ("JB20_16","019_20_16","JOB","20","16","16","Zai sha dafin maciji; sarar maciji mai dafi za tă tashe shi. ");
INSERT INTO hausa_vpl VALUES ("JB20_17","019_20_17","JOB","20","17","17","Ba zai ji daɗin koguna da rafuffuka masu kwarara da zuma da madara ba. ");
INSERT INTO hausa_vpl VALUES ("JB20_18","019_20_18","JOB","20","18","18","Dole yă ba da abin da ya yi gumi kafin yă samu, ba zai ci ba; ba zai ji daɗin ribar da ya samu daga kasuwancinsa ba. ");
INSERT INTO hausa_vpl VALUES ("JB20_19","019_20_19","JOB","20","19","19","Gama ya ci zalin talakawa ya bar su cikin wahala; ya ƙwace gidajen da ba shi ya gina ba. ");
INSERT INTO hausa_vpl VALUES ("JB20_20","019_20_20","JOB","20","20","20","“Ba shakka ba zai samu abin da yake ƙoƙarin samu ba, dukiyarsa ba za tă cece shi ba. ");
INSERT INTO hausa_vpl VALUES ("JB20_21","019_20_21","JOB","20","21","21","Ba abin da ya ragu da zai ɗauka; arzikinsa ba zai dawwama ba. ");
INSERT INTO hausa_vpl VALUES ("JB20_22","019_20_22","JOB","20","22","22","Yana cikin samun arziki, ɓacin rai zai auka masa; ƙunci mai ƙarfi zai zo masa. ");
INSERT INTO hausa_vpl VALUES ("JB20_23","019_20_23","JOB","20","23","23","Lokacin da ya cika cikinsa, Allah zai zuba fushinsa a kansa, zai daddaka shi. ");
INSERT INTO hausa_vpl VALUES ("JB20_24","019_20_24","JOB","20","24","24","Ko da yake yana guje wa makamin ƙarfe, kibiya mai bakin tagulla za tă huda shi. ");
INSERT INTO hausa_vpl VALUES ("JB20_25","019_20_25","JOB","20","25","25","Zai zāre ta daga bayansa, tsinin zai fita daga hantarsa; tsoro zai cika shi; ");
INSERT INTO hausa_vpl VALUES ("JB20_26","019_20_26","JOB","20","26","26","duhu kawai yake jiran dukiyarsa. Wutar da ba a fifita ba za tă cinye shi ta kuma ƙona duk abin da ya rage a tentinsa. ");
INSERT INTO hausa_vpl VALUES ("JB20_27","019_20_27","JOB","20","27","27","Sammai za su fallasa laifinsa; duniya za tă yi gāba da shi. ");
INSERT INTO hausa_vpl VALUES ("JB20_28","019_20_28","JOB","20","28","28","Ambaliyar ruwa za tă tafi da gidansa, ruwaye masu gudu a ranar fushin Allah. ");
INSERT INTO hausa_vpl VALUES ("JB20_29","019_20_29","JOB","20","29","29","Abin da Allah zai sa yă faru da mugu ke nan, gādon da Allah ya ba shi ke nan.” ");
INSERT INTO hausa_vpl VALUES ("JB21_1","019_21_1","JOB","21","1","1","Sai Ayuba ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB21_2","019_21_2","JOB","21","2","2","“Ku saurare ni da kyau; bari wannan yă zama ta’aziyyar da za ku ba ni. ");
INSERT INTO hausa_vpl VALUES ("JB21_3","019_21_3","JOB","21","3","3","Ku ba ni zarafi in yi magana, bayan na gama sai ku yi ba’arku. ");
INSERT INTO hausa_vpl VALUES ("JB21_4","019_21_4","JOB","21","4","4","“A wurin mutum ne na kawo kukana? Don me ba zan kāsa haƙuri ba? ");
INSERT INTO hausa_vpl VALUES ("JB21_5","019_21_5","JOB","21","5","5","Ku dube ni, ku kuma yi mamaki; ku rufe bakina da hannunku. ");
INSERT INTO hausa_vpl VALUES ("JB21_6","019_21_6","JOB","21","6","6","Lokacin da na yi tunanin wannan, sai in ji tsoro; jikina yă fara rawa. ");
INSERT INTO hausa_vpl VALUES ("JB21_7","019_21_7","JOB","21","7","7","Don me mugaye suke rayuwa har su tsufa, suna kuma ƙaruwa da iko? ");
INSERT INTO hausa_vpl VALUES ("JB21_8","019_21_8","JOB","21","8","8","Suna ganin ’ya’yansu suna girma, suna ganin jikokinsu suna tasowa a kan idanunsu. ");
INSERT INTO hausa_vpl VALUES ("JB21_9","019_21_9","JOB","21","9","9","Gidajensu suna zama cikin lafiya ba ruwansu da fargaba. Kuma Allah ba ya ba su horo. ");
INSERT INTO hausa_vpl VALUES ("JB21_10","019_21_10","JOB","21","10","10","Shanunsu ba sa fasa haihuwa; suna haihuwa ba sa yin ɓari. ");
INSERT INTO hausa_vpl VALUES ("JB21_11","019_21_11","JOB","21","11","11","Suna aika ’ya’yansu kamar garke; ’ya’yansu suna guje-guje da tsalle-tsalle. ");
INSERT INTO hausa_vpl VALUES ("JB21_12","019_21_12","JOB","21","12","12","Suna rera da kayan kiɗa na ganga da garaya; suna jin daɗin busar sarewa. ");
INSERT INTO hausa_vpl VALUES ("JB21_13","019_21_13","JOB","21","13","13","Suna yin rayuwarsu cikin arziki kuma su mutu cikin salama. ");
INSERT INTO hausa_vpl VALUES ("JB21_14","019_21_14","JOB","21","14","14","Duk da haka suna ce wa Allah, ‘Ka rabu da mu.’ Ba ma so mu san hanyoyinka. ");
INSERT INTO hausa_vpl VALUES ("JB21_15","019_21_15","JOB","21","15","15","Wane ne Maɗaukaki har da za mu bauta masa? Wace riba za mu samu ta wurin yin addu’a gare shi? ");
INSERT INTO hausa_vpl VALUES ("JB21_16","019_21_16","JOB","21","16","16","Amma arzikinsu ba a hannunsu yake ba saboda haka ba ruwana da shawarar mugaye. ");
INSERT INTO hausa_vpl VALUES ("JB21_17","019_21_17","JOB","21","17","17","“Duk da haka, sau nawa fitilar mugu take mutuwa? Sau nawa bala’i yake auka masa, ko Allah ya taɓa hukunta mugu cikin fushi? ");
INSERT INTO hausa_vpl VALUES ("JB21_18","019_21_18","JOB","21","18","18","Sau nawa suke zama kamar tattaka a iska, ko kuma kamar ƙura da iskar hadari take kwashewa? ");
INSERT INTO hausa_vpl VALUES ("JB21_19","019_21_19","JOB","21","19","19","An ce ‘Allah yana tara wa ’ya’yan mutum horon da zai ba mutumin.’ Bari yă ba mutumin horo don yă san ya yi haka! ");
INSERT INTO hausa_vpl VALUES ("JB21_20","019_21_20","JOB","21","20","20","Bari idanunsa su ga yadda zai hallaka; bari yă sha daga fushin Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("JB21_21","019_21_21","JOB","21","21","21","Ko zai damu da iyalin da ya bari a baya sa’ad da kwanakinsa suka ƙare? ");
INSERT INTO hausa_vpl VALUES ("JB21_22","019_21_22","JOB","21","22","22","“Wani zai iya koya wa Allah ilimi tun da yana shari’anta har da waɗanda suke manya masu iko? ");
INSERT INTO hausa_vpl VALUES ("JB21_23","019_21_23","JOB","21","23","23","Wani mutum zai mutu cikin jin daɗi da kwanciyar hankali, ");
INSERT INTO hausa_vpl VALUES ("JB21_24","019_21_24","JOB","21","24","24","jikinsa ɓulɓul, ƙasusuwansa da alamar ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("JB21_25","019_21_25","JOB","21","25","25","Wani kuma zai mutu cikin ɗacin rai, bai taɓa jin daɗin wani abu mai kyau ba. ");
INSERT INTO hausa_vpl VALUES ("JB21_26","019_21_26","JOB","21","26","26","Dukansu kuwa za a bizne su a ƙasa, kuma tsutsotsi za su cinye su. ");
INSERT INTO hausa_vpl VALUES ("JB21_27","019_21_27","JOB","21","27","27","“Na san duk abin da kuke tunani, yadda za ku saɓa mini. ");
INSERT INTO hausa_vpl VALUES ("JB21_28","019_21_28","JOB","21","28","28","Kuna cewa, ‘Yanzu ina gidan babban mutumin nan, tenti wurin da mugaye suke zama?’ ");
INSERT INTO hausa_vpl VALUES ("JB21_29","019_21_29","JOB","21","29","29","Ba ku taɓa tambayar waɗanda suke tafiya ba? Ba ku kula da labaransu, ");
INSERT INTO hausa_vpl VALUES ("JB21_30","019_21_30","JOB","21","30","30","cewa an kāre mugu daga ranar bala’i, an kāre shi daga ranar fushi? ");
INSERT INTO hausa_vpl VALUES ("JB21_31","019_21_31","JOB","21","31","31","Wane ne yake gaya masa abin da ya yi? Wane ne yake rama abin da ya yi? ");
INSERT INTO hausa_vpl VALUES ("JB21_32","019_21_32","JOB","21","32","32","Za a bizne shi a kabari, a kuma yi tsaron kabarinsa. ");
INSERT INTO hausa_vpl VALUES ("JB21_33","019_21_33","JOB","21","33","33","Akan mai da ƙasa a kan gawarsa a hankali; dukan jama’a suna binsa, da yawa kuma suna gabansa. ");
INSERT INTO hausa_vpl VALUES ("JB21_34","019_21_34","JOB","21","34","34","“Saboda haka ta yaya za ku iya yi mini ta’aziyya da surutan banzan nan naku? Babu wani abu cikin amsarku sai ƙarya!” ");
INSERT INTO hausa_vpl VALUES ("JB22_1","019_22_1","JOB","22","1","1","Sai Elifaz mutumin Teman ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB22_2","019_22_2","JOB","22","2","2","“Mutum yana iya zama da amfani a wurin Allah? Mai hikima ma zai iya zama da amfani a wurin shi? ");
INSERT INTO hausa_vpl VALUES ("JB22_3","019_22_3","JOB","22","3","3","Wane daɗi Allah zai ji in kai mai adalci ne? Wace riba zai samu in rayuwarka marar laifi ce? ");
INSERT INTO hausa_vpl VALUES ("JB22_4","019_22_4","JOB","22","4","4","“Ko don kana tsoron Allah shi ya sa ya kwaɓe ka ya kuma bari haka yă same ka? ");
INSERT INTO hausa_vpl VALUES ("JB22_5","019_22_5","JOB","22","5","5","Ba muguntarka ce ta yi yawa ba? Ba zunubanka ne ba iyaka ba? ");
INSERT INTO hausa_vpl VALUES ("JB22_6","019_22_6","JOB","22","6","6","Ka sa ɗan’uwanka yă biya ka bashin da kake binsa ba dalili; ka ƙwace wa mutanen rigunansu ka bar su tsirara. ");
INSERT INTO hausa_vpl VALUES ("JB22_7","019_22_7","JOB","22","7","7","Ba ka ba masu jin ƙishirwa su sha ba kuma ka hana wa masu jin yunwa abinci su ci. ");
INSERT INTO hausa_vpl VALUES ("JB22_8","019_22_8","JOB","22","8","8","Ko da yake kai mai ƙarfi ne, ka mallaki ƙasa, mutum mai martaba kuma, kana zama cikin ƙasarka. ");
INSERT INTO hausa_vpl VALUES ("JB22_9","019_22_9","JOB","22","9","9","Ka kori gwauraye hannu wofi, ka kuma karya ƙarfin marayu. ");
INSERT INTO hausa_vpl VALUES ("JB22_10","019_22_10","JOB","22","10","10","Shi ya sa kake kewaye da tarkuna, shi ya sa ka cika da tsoron mugun abin da zai auko maka. ");
INSERT INTO hausa_vpl VALUES ("JB22_11","019_22_11","JOB","22","11","11","An yi duhu ƙwarai, har ba ka iya gani, shi ya sa ambaliyar ruwa ta rufe ka. ");
INSERT INTO hausa_vpl VALUES ("JB22_12","019_22_12","JOB","22","12","12","“Ba Allah ne a can sama ba? Dubi yadda taurarin sama suke can nesa a sama! ");
INSERT INTO hausa_vpl VALUES ("JB22_13","019_22_13","JOB","22","13","13","Duk da haka ka ce, ‘Me Allah ya sani? A cikin duhu ne yake shari’a? ");
INSERT INTO hausa_vpl VALUES ("JB22_14","019_22_14","JOB","22","14","14","Gajimare ya rufe shi, saboda haka ba ya ganinmu lokacin da yake takawa a cikin sammai.’ ");
INSERT INTO hausa_vpl VALUES ("JB22_15","019_22_15","JOB","22","15","15","Za ka ci gaba da bin tsohuwar hanyar da mugayen mutane suka bi? ");
INSERT INTO hausa_vpl VALUES ("JB22_16","019_22_16","JOB","22","16","16","An ɗauke su kafin lokacinsu yă cika, ruwa ya share tushensu. ");
INSERT INTO hausa_vpl VALUES ("JB22_17","019_22_17","JOB","22","17","17","Suka ce wa Allah, ‘Ka rabu da mu! Me Maɗaukaki zai yi mana?’ ");
INSERT INTO hausa_vpl VALUES ("JB22_18","019_22_18","JOB","22","18","18","Duk da haka kuwa shi ne ya cika gidajensu da abubuwa masu kyau, saboda haka ba ruwana da shawarar mugaye. ");
INSERT INTO hausa_vpl VALUES ("JB22_19","019_22_19","JOB","22","19","19","“Masu adalci suna gani ana hallaka mugaye, suna jin daɗi; marasa laifi suna yi musu ba’a, suna cewa, ");
INSERT INTO hausa_vpl VALUES ("JB22_20","019_22_20","JOB","22","20","20","‘Ba shakka an hallaka maƙiyanmu, wuta kuma ta ƙona dukiyarsu.’ ");
INSERT INTO hausa_vpl VALUES ("JB22_21","019_22_21","JOB","22","21","21","“Ka miƙa kanka ga Allah ka samu salamarsa; ta haka ne arziki zai zo maka. ");
INSERT INTO hausa_vpl VALUES ("JB22_22","019_22_22","JOB","22","22","22","Ka bi umarnin da zai fito daga bakinsa kuma ka riƙe maganarsa a cikin zuciyarka. ");
INSERT INTO hausa_vpl VALUES ("JB22_23","019_22_23","JOB","22","23","23","In ka komo ga Maɗaukaki, za ka warke. In ka kawar da mugunta daga cikin gidanka. ");
INSERT INTO hausa_vpl VALUES ("JB22_24","019_22_24","JOB","22","24","24","Ka jefar da zinariyarka a ƙasa, ka jefar da zinariyar Ofir da ka fi so a cikin duwatsu, ");
INSERT INTO hausa_vpl VALUES ("JB22_25","019_22_25","JOB","22","25","25","sa’an nan ne Maɗaukaki zai zama zinariyarka, zai zama azurfa mafi kyau a wurinka. ");
INSERT INTO hausa_vpl VALUES ("JB22_26","019_22_26","JOB","22","26","26","Ba shakka a lokacin ne za ka sami farin ciki daga wurin Maɗaukaki, ku kuma ɗaga idanunku ga Allah ");
INSERT INTO hausa_vpl VALUES ("JB22_27","019_22_27","JOB","22","27","27","Za ka yi addu’a zuwa gare shi, zai kuwa ji ka, kuma za ka cika alkawuranka. ");
INSERT INTO hausa_vpl VALUES ("JB22_28","019_22_28","JOB","22","28","28","Abin da ka zaɓa za ka yi za ka yi nasara a ciki, haske kuma zai haskaka hanyarka. ");
INSERT INTO hausa_vpl VALUES ("JB22_29","019_22_29","JOB","22","29","29","Sa’ad da aka ƙasƙantar da mutane ka kuma ce, ‘A ɗaga su!’ Sa’an nan zai ceci masu tawali’u. ");
INSERT INTO hausa_vpl VALUES ("JB22_30","019_22_30","JOB","22","30","30","Zai ceci wanda ma yake mai laifi, wanda zai tsirar da shi ta wurin tsabtar hannuwanka.” ");
INSERT INTO hausa_vpl VALUES ("JB23_1","019_23_1","JOB","23","1","1","Sa’an nan Ayuba ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB23_2","019_23_2","JOB","23","2","2","“Ko a yau, ina kuka mai zafi; hannunsa yana da nauyi duk da nishin da nake yi. ");
INSERT INTO hausa_vpl VALUES ("JB23_3","019_23_3","JOB","23","3","3","Da a ce na san inda zan same shi; da a ce zan iya zuwa wurin da yake zama! ");
INSERT INTO hausa_vpl VALUES ("JB23_4","019_23_4","JOB","23","4","4","Zan kai damuwata wurinsa in yi gardama da shi. ");
INSERT INTO hausa_vpl VALUES ("JB23_5","019_23_5","JOB","23","5","5","Zan nemi in san abin da zai ce mini, in kuma auna abin da zai ce mini. ");
INSERT INTO hausa_vpl VALUES ("JB23_6","019_23_6","JOB","23","6","6","Zai yi gardama da ni da ikonsa mai girma? Babu, ba zai zarge ni da laifi ba. ");
INSERT INTO hausa_vpl VALUES ("JB23_7","019_23_7","JOB","23","7","7","Mai adalci ne zai kawo ƙara a wurinsa, kuma zan samu kuɓuta daga wurin mai shari’an nan har abada. ");
INSERT INTO hausa_vpl VALUES ("JB23_8","019_23_8","JOB","23","8","8","“Amma in na je gabas, ba ya wurin; in na je yamma, ba zan same shi ba. ");
INSERT INTO hausa_vpl VALUES ("JB23_9","019_23_9","JOB","23","9","9","Sa’ad da yake aiki a arewa, ba ni ganinsa; sa’ad da ya juya zuwa kudu, ba na ganinsa. ");
INSERT INTO hausa_vpl VALUES ("JB23_10","019_23_10","JOB","23","10","10","Amma ya san hanyar da nake bi; sa’ad da ya gwada ni zan fito kamar zinariya. ");
INSERT INTO hausa_vpl VALUES ("JB23_11","019_23_11","JOB","23","11","11","Ƙafafuna suna bin ƙafafunsa kurkusa; na bi hanyarsa ba tare da na juya ba. ");
INSERT INTO hausa_vpl VALUES ("JB23_12","019_23_12","JOB","23","12","12","Ban fasa bin dokokin da ya bayar ba; na riƙe maganarsa da muhimmanci fiye da abincin yau da gobe. ");
INSERT INTO hausa_vpl VALUES ("JB23_13","019_23_13","JOB","23","13","13","“Amma ya tsaya shi kaɗai, kuma wa ya isa yă ja da shi? Yana yin abin da yake so. ");
INSERT INTO hausa_vpl VALUES ("JB23_14","019_23_14","JOB","23","14","14","Yana yi mini abin da ya shirya yă yi mini, kuma yana da sauran irinsu a ajiye. ");
INSERT INTO hausa_vpl VALUES ("JB23_15","019_23_15","JOB","23","15","15","Shi ya sa na tsorata a gabansa; sa’ad da na yi tunanin wannan duka, nakan ji tsoronsa. ");
INSERT INTO hausa_vpl VALUES ("JB23_16","019_23_16","JOB","23","16","16","Allah ya sa zuciyata ta yi sanyi; Maɗaukaki ya tsorata ni. ");
INSERT INTO hausa_vpl VALUES ("JB23_17","019_23_17","JOB","23","17","17","Duk da haka duhun bai sa in yi shiru ba, duhun da ya rufe mini fuska. ");
INSERT INTO hausa_vpl VALUES ("JB24_1","019_24_1","JOB","24","1","1","“Domin me Maɗaukaki ba zai sa ranar shari’a ba? Don me waɗanda suka san shi suke faman samun irin ranakun nan? ");
INSERT INTO hausa_vpl VALUES ("JB24_2","019_24_2","JOB","24","2","2","Mugaye suna satar fili ta wurin matsar da duwatsun da aka yi iyaka da su; suna satar dabbobi su kuma yi kiwon su. ");
INSERT INTO hausa_vpl VALUES ("JB24_3","019_24_3","JOB","24","3","3","Suna ƙwace wa marayu jakunansu suna kuma ƙwace wa gwauruwa sa don suna binta bashi. ");
INSERT INTO hausa_vpl VALUES ("JB24_4","019_24_4","JOB","24","4","4","Suna ture matalauta daga hanya suna kuma sa dole matalautan ƙasar su ɓoye. ");
INSERT INTO hausa_vpl VALUES ("JB24_5","019_24_5","JOB","24","5","5","Kamar jakunan jeji a hamada, matalauta suna aikin neman abinci gonaki marasa amfani suna tanada abinci wa ’ya’yansu. ");
INSERT INTO hausa_vpl VALUES ("JB24_6","019_24_6","JOB","24","6","6","Suna girbi a gonakin da ba nasu ba, suna yin kala a gonar inabi ta mugaye. ");
INSERT INTO hausa_vpl VALUES ("JB24_7","019_24_7","JOB","24","7","7","Don ba su da tufafi, sukan kwana tsirara; ba su da wani abin da zai rufe su cikin sanyi. ");
INSERT INTO hausa_vpl VALUES ("JB24_8","019_24_8","JOB","24","8","8","Sun jiƙe sharkaf da ruwan da yake kwararowa daga duwatsu, sun rungume duwatsu don rashin wurin fakewa. ");
INSERT INTO hausa_vpl VALUES ("JB24_9","019_24_9","JOB","24","9","9","Ana ƙwace jinjiri mai shan mama; ana ƙwace ɗan yaron matalauci don biyan bashi. ");
INSERT INTO hausa_vpl VALUES ("JB24_10","019_24_10","JOB","24","10","10","Don ba su da tufafi suna yawo tsirara; suna dakon dammunan hatsi amma duk da haka suna cikin shan yunwa. ");
INSERT INTO hausa_vpl VALUES ("JB24_11","019_24_11","JOB","24","11","11","Suna matse zaitun a cikin kunyoyi suna kuma matse ruwan inabi daga ’ya’yan inabi, duk da haka suna fama da ƙishi. ");
INSERT INTO hausa_vpl VALUES ("JB24_12","019_24_12","JOB","24","12","12","Ana jin nishin masu mutuwa daga birni, kuma rayukan waɗanda aka ji musu rauni suna kuka suna kira don taimako. Amma bai ba wani laifi ba. ");
INSERT INTO hausa_vpl VALUES ("JB24_13","019_24_13","JOB","24","13","13","“Akwai waɗanda suke yi wa haske tawaye, waɗanda ba su san hanyoyinsa ba ko kuma ba su taɓa bin hanyoyinsa ba. ");
INSERT INTO hausa_vpl VALUES ("JB24_14","019_24_14","JOB","24","14","14","Sa’ad da hasken yini ya tafi, mai kisankai yakan tashi; yă je yă kashe matalauta da masu bukata; a cikin dare yake shigowa kamar ɓarawo. ");
INSERT INTO hausa_vpl VALUES ("JB24_15","019_24_15","JOB","24","15","15","Idanun mazinaci suna jiran yamma ta yi sosai; yana tunani cewa, ‘Ba wanda zai gan ni,’ sai kuma yă ɓoye fuskarsa. ");
INSERT INTO hausa_vpl VALUES ("JB24_16","019_24_16","JOB","24","16","16","Cikin duhu mutane suna fasa gidaje, amma da rana sukan kulle kansu; ba sa so wani abu yă haɗa su da haske. ");
INSERT INTO hausa_vpl VALUES ("JB24_17","019_24_17","JOB","24","17","17","Gama dukansu, duhu mai yawa shi ne safiyarsu; suna abokantaka da razanar duhu. ");
INSERT INTO hausa_vpl VALUES ("JB24_18","019_24_18","JOB","24","18","18","“Duk da haka kamar abu marar nauyi suke a kan ruwa; gefen ƙasar da suke, an la’anta ta, yadda ba wanda yake zuwa gonar inabinsu. ");
INSERT INTO hausa_vpl VALUES ("JB24_19","019_24_19","JOB","24","19","19","Kamar yadda zafi da fări suke shanye ƙanƙarar da ta narke, haka kabari zai ƙwace waɗanda suka yi zunubi. ");
INSERT INTO hausa_vpl VALUES ("JB24_20","019_24_20","JOB","24","20","20","Waɗanda suka haife su za su manta da su, tsutsotsi za su cinye su; ba za a sāke tunawa da mugaye ba amma an sare su kamar itace. ");
INSERT INTO hausa_vpl VALUES ("JB24_21","019_24_21","JOB","24","21","21","Suna cutar macen da ba ta da ɗa, suna nuna wa gwauruwa rashin alheri. ");
INSERT INTO hausa_vpl VALUES ("JB24_22","019_24_22","JOB","24","22","22","Amma Allah cikin ikonsa yakan kawar da masu ƙarfi, ko da yake sun yi ƙarfi, ba su da tabbacin rayuwa. ");
INSERT INTO hausa_vpl VALUES ("JB24_23","019_24_23","JOB","24","23","23","Mai yiwuwa zai bar su su zauna cikin kwanciyar hankali, amma idanunsa suna kansu. ");
INSERT INTO hausa_vpl VALUES ("JB24_24","019_24_24","JOB","24","24","24","Sukan samu cin nasara na ɗan lokaci, amma kuma za su ɓace; za su fāɗi a tattara su kamar sauran; za a datse su kamar kan hatsi. ");
INSERT INTO hausa_vpl VALUES ("JB24_25","019_24_25","JOB","24","25","25","“In wannan ba haka ba ne, wane ne zai shaida ƙarya nake yi har yă ƙi yarda da maganata?” ");
INSERT INTO hausa_vpl VALUES ("JB25_1","019_25_1","JOB","25","1","1","Sai Bildad mutumin Shuwa ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB25_2","019_25_2","JOB","25","2","2","“Mulki na Allah ne, dole a ji tsoronsa; yana tafiyar da kome yadda ya kamata a cikin sama. ");
INSERT INTO hausa_vpl VALUES ("JB25_3","019_25_3","JOB","25","3","3","Za a iya ƙirga rundunarsa? A kan wane ne ba ya haska haskensa? ");
INSERT INTO hausa_vpl VALUES ("JB25_4","019_25_4","JOB","25","4","4","Ta yaya mutum zai iya zama mai adalci a gaban Allah? Ta yaya mutumin da mace ta haifa zai zama mai tsarki? ");
INSERT INTO hausa_vpl VALUES ("JB25_5","019_25_5","JOB","25","5","5","In har wata da taurari ba su da tsarki a idanunsa, ");
INSERT INTO hausa_vpl VALUES ("JB25_6","019_25_6","JOB","25","6","6","mutum fa? Ai, wannan tsutsa ne, ɗan ƙwaro kawai. Me mutum ya daɗa a gaban Allah!” ");
INSERT INTO hausa_vpl VALUES ("JB26_1","019_26_1","JOB","26","1","1","Sai Ayuba ya amsa, ");
INSERT INTO hausa_vpl VALUES ("JB26_2","019_26_2","JOB","26","2","2","“Yadda ka taimaki marar ƙarfi! Yadda ka ceci marar ƙarfi! ");
INSERT INTO hausa_vpl VALUES ("JB26_3","019_26_3","JOB","26","3","3","Ka ba marar hikima shawara! Ka nuna kana da ilimi sosai. ");
INSERT INTO hausa_vpl VALUES ("JB26_4","019_26_4","JOB","26","4","4","Wane ne ya taimake ka ka yi waɗannan maganganu? Kuma ruhun wane ne ya yi magana ta bakinka? ");
INSERT INTO hausa_vpl VALUES ("JB26_5","019_26_5","JOB","26","5","5","“Matattu suna cikin azaba, waɗanda suke ƙarƙashin ruwaye da dukan mazauna cikin ruwaye. ");
INSERT INTO hausa_vpl VALUES ("JB26_6","019_26_6","JOB","26","6","6","Mutuwa tsirara take a gaban Allah; haka kuma hallaka take a buɗe. ");
INSERT INTO hausa_vpl VALUES ("JB26_7","019_26_7","JOB","26","7","7","Ya shimfiɗa arewancin sararin sama a sarari; ya rataye duniya ba a jikin wani abu ba. ");
INSERT INTO hausa_vpl VALUES ("JB26_8","019_26_8","JOB","26","8","8","Ya naɗe ruwaye a cikin gizagizansa, duk da haka girgijen bai yage saboda nauyi ba. ");
INSERT INTO hausa_vpl VALUES ("JB26_9","019_26_9","JOB","26","9","9","Ya rufe fuskar wata, ya shimfiɗa gizagizai a kan shi, ");
INSERT INTO hausa_vpl VALUES ("JB26_10","019_26_10","JOB","26","10","10","ya zāna iyakar fuskar ruwa a kan iyakar da take tsakanin duhu da haske. ");
INSERT INTO hausa_vpl VALUES ("JB26_11","019_26_11","JOB","26","11","11","Madogaran sama sun girgiza, saboda tsawatawarsa. ");
INSERT INTO hausa_vpl VALUES ("JB26_12","019_26_12","JOB","26","12","12","Da ikonsa ya kwantar da teku; da hikimarsa ya hallaka dodon ruwan nan Rahab. ");
INSERT INTO hausa_vpl VALUES ("JB26_13","019_26_13","JOB","26","13","13","Da numfashinsa ya sa sararin sama ya yi kyau da hannunsa ya soke macijin nan mai gudu. ");
INSERT INTO hausa_vpl VALUES ("JB26_14","019_26_14","JOB","26","14","14","Waɗannan kaɗan ke nan daga cikin ayyukansa masu yawa. Kaɗan kawai muke ji game da shi! Wane ne kuwa yake iya gane tsawar ikonsa?” ");
INSERT INTO hausa_vpl VALUES ("JB27_1","019_27_1","JOB","27","1","1","Ayuba kuwa ya ci gaba da magana, ");
INSERT INTO hausa_vpl VALUES ("JB27_2","019_27_2","JOB","27","2","2","“Na rantse da Allah mai rai, wanda ya danne mini gaskiyata, Maɗaukaki, wanda ya sa nake cikin ɗacin rai. ");
INSERT INTO hausa_vpl VALUES ("JB27_3","019_27_3","JOB","27","3","3","Muddin ina da rai a cikina kuma numfashin Allah yana cikin hancina, ");
INSERT INTO hausa_vpl VALUES ("JB27_4","019_27_4","JOB","27","4","4","bakina ba zai faɗi mugun abu ba, harshena kuma ba zai yi ƙarya ba. ");
INSERT INTO hausa_vpl VALUES ("JB27_5","019_27_5","JOB","27","5","5","Ba zan taɓa yarda cewa kuna da gaskiya ba; har in mutu, ba zan daina kāre mutuncina ba. ");
INSERT INTO hausa_vpl VALUES ("JB27_6","019_27_6","JOB","27","6","6","Zan ci gaba da adalcina, ba zan fasa ba; lamirina ba zai taɓa yashe ni ba, dukan kwanakin raina. ");
INSERT INTO hausa_vpl VALUES ("JB27_7","019_27_7","JOB","27","7","7","“Bari maƙiyana su zama kamar mugaye, masu gāba da ni kuma su zama kamar marasa adalci. ");
INSERT INTO hausa_vpl VALUES ("JB27_8","019_27_8","JOB","27","8","8","Gama wane bege marar tsoron Allah yake da shi, lokacin da aka datse shi, lokacin da Allah ya ɗauke ransa? ");
INSERT INTO hausa_vpl VALUES ("JB27_9","019_27_9","JOB","27","9","9","Ko Allah yana sauraron kukansa lokacin da ƙunci ya auko masa? ");
INSERT INTO hausa_vpl VALUES ("JB27_10","019_27_10","JOB","27","10","10","Ko zai sami farin ciki daga Maɗaukaki? Ko zai yi kira ga Allah a kowane lokaci? ");
INSERT INTO hausa_vpl VALUES ("JB27_11","019_27_11","JOB","27","11","11","“Zan koya muku game da ikon Allah; ba zan ɓoye hanyoyin Maɗaukaki ba. ");
INSERT INTO hausa_vpl VALUES ("JB27_12","019_27_12","JOB","27","12","12","Duk kun ga wannan ku da kanku saboda haka me ya sa kuke maganganun nan marasa ma’ana? ");
INSERT INTO hausa_vpl VALUES ("JB27_13","019_27_13","JOB","27","13","13","“Ga abin da mugaye za su samu gādon da azzalumi zai samu daga Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("JB27_14","019_27_14","JOB","27","14","14","Kome yawan ’ya’yansa, takobi za tă gama da su; zuriyarsa ba za su taɓa samun isashen abinci ba. ");
INSERT INTO hausa_vpl VALUES ("JB27_15","019_27_15","JOB","27","15","15","Waɗanda suka tsira annoba za tă kashe su, kuma gwaurayensu ba za su yi kukan mutuwarsu ba. ");
INSERT INTO hausa_vpl VALUES ("JB27_16","019_27_16","JOB","27","16","16","Ko da yake ya tara azurfa kamar ƙasa, tufafi kuma kamar tarin ƙasa, ");
INSERT INTO hausa_vpl VALUES ("JB27_17","019_27_17","JOB","27","17","17","abin da ya tara masu adalci za su sa marasa laifi za su raba azurfarsa. ");
INSERT INTO hausa_vpl VALUES ("JB27_18","019_27_18","JOB","27","18","18","Gidan da ya gina kamar gidan gizo-gizo, kamar bukkar mai tsaro. ");
INSERT INTO hausa_vpl VALUES ("JB27_19","019_27_19","JOB","27","19","19","Attajiri zai kwanta, amma daga wannan shi ke nan; lokacin da zai buɗe idanunsa, kome ya tafi. ");
INSERT INTO hausa_vpl VALUES ("JB27_20","019_27_20","JOB","27","20","20","Tsoro zai kwashe shi kamar ambaliyar ruwa; Da dare iska za tă tafi da shi. ");
INSERT INTO hausa_vpl VALUES ("JB27_21","019_27_21","JOB","27","21","21","Iskar gabas za tă tafi da shi; shi ke nan ya ƙare; za tă share shi daga wurinsa. ");
INSERT INTO hausa_vpl VALUES ("JB27_22","019_27_22","JOB","27","22","22","Za tă murɗe shi ba tausayi, lokacin da yake guje wa ikon iskar. ");
INSERT INTO hausa_vpl VALUES ("JB27_23","019_27_23","JOB","27","23","23","Zai tafa hannu yă yi tsaki yă kawar da shi daga wurinsa.” ");
INSERT INTO hausa_vpl VALUES ("JB28_1","019_28_1","JOB","28","1","1","Akwai ramin azurfa akwai kuma wurin da ake tace zinariya. ");
INSERT INTO hausa_vpl VALUES ("JB28_2","019_28_2","JOB","28","2","2","Daga cikin ƙasa ake ciro ƙarfe, ana kuma narkar da tagulla daga cikin dutse. ");
INSERT INTO hausa_vpl VALUES ("JB28_3","019_28_3","JOB","28","3","3","Mutum ya kawo ƙarshen duhu; yakan bincike zuzzurfar iyaka, yana neman duwatsu a wuri mafi duhu. ");
INSERT INTO hausa_vpl VALUES ("JB28_4","019_28_4","JOB","28","4","4","Nesa da inda mutane suke zama, yakan huda rami yă yi abin lilo, a wurin da mutane ba sa bi. ");
INSERT INTO hausa_vpl VALUES ("JB28_5","019_28_5","JOB","28","5","5","Cikin ƙasa inda ake samun abinci, a ƙarƙashinta kuwa zafi ne kamar wuta; ");
INSERT INTO hausa_vpl VALUES ("JB28_6","019_28_6","JOB","28","6","6","akwai duwatsu masu daraja a cikin duwatsunta, akwai kuma zinariya a cikin ƙurarta. ");
INSERT INTO hausa_vpl VALUES ("JB28_7","019_28_7","JOB","28","7","7","Tsuntsu mai farauta bai san hanyarta ba, ba shahon da ya taɓa ganin ta. ");
INSERT INTO hausa_vpl VALUES ("JB28_8","019_28_8","JOB","28","8","8","Manyan namun jeji ba su taɓa binta ba, ba zakin da ya taɓa binta. ");
INSERT INTO hausa_vpl VALUES ("JB28_9","019_28_9","JOB","28","9","9","Hannun mutum ya iya sarrafa ƙanƙarar duwatsu, yă kuma tumɓuke tushen duwatsu. ");
INSERT INTO hausa_vpl VALUES ("JB28_10","019_28_10","JOB","28","10","10","Yana tona rami a cikin duwatsu idanunsa suna ganin dukan dukiyar da ke cikin duwatsun. ");
INSERT INTO hausa_vpl VALUES ("JB28_11","019_28_11","JOB","28","11","11","Yana nema daga ina ruwan rafi yake ɓulɓulowa yana kuma binciko abubuwan da suke a ɓoye yă kawo su cikin haske. ");
INSERT INTO hausa_vpl VALUES ("JB28_12","019_28_12","JOB","28","12","12","Amma a ina ne za a iya samun hikima? Ina fahimta take zama? ");
INSERT INTO hausa_vpl VALUES ("JB28_13","019_28_13","JOB","28","13","13","Mutum bai gane muhimmancinta ba, ba a samunta a ƙasar masu rai. ");
INSERT INTO hausa_vpl VALUES ("JB28_14","019_28_14","JOB","28","14","14","Zurfi ya ce, “Ba ta wurina”; teku ya ce, “Ba ta wurina.” ");
INSERT INTO hausa_vpl VALUES ("JB28_15","019_28_15","JOB","28","15","15","Ba irin zinariyar da za tă iya sayenta, ko kuma a iya auna nauyinta da azurfa. ");
INSERT INTO hausa_vpl VALUES ("JB28_16","019_28_16","JOB","28","16","16","Ba za a iya sayenta da zinariyar Ofir, ko sauran duwatsu masu daraja ba. ");
INSERT INTO hausa_vpl VALUES ("JB28_17","019_28_17","JOB","28","17","17","Zinariya da madubi ba za su iya gwada kansu da ita ba, ba kuwa za a iya musayarta da abubuwan da aka yi da zinariya ba. ");
INSERT INTO hausa_vpl VALUES ("JB28_18","019_28_18","JOB","28","18","18","Kada ma a ce murjani da duwatsu masu walƙiya; farashin hikima ya fi na lu’ulu’ai. ");
INSERT INTO hausa_vpl VALUES ("JB28_19","019_28_19","JOB","28","19","19","Ba za a iya daidaita darajarta da duwatsun Tofaz na Kush ba, zallar zinariya ma ba tă isa ta saye ta ba. ");
INSERT INTO hausa_vpl VALUES ("JB28_20","019_28_20","JOB","28","20","20","“To, daga ina ke nan hikima ta fito? Ina fahimta take zama? ");
INSERT INTO hausa_vpl VALUES ("JB28_21","019_28_21","JOB","28","21","21","An ɓoye ta daga idanun kowane abu mai rai, har tsuntsayen sararin sama ma an ɓoye masu ita. ");
INSERT INTO hausa_vpl VALUES ("JB28_22","019_28_22","JOB","28","22","22","Hallaka da mutuwa suna cewa, ‘Jita-jitarta kaɗai muke ji.’ ");
INSERT INTO hausa_vpl VALUES ("JB28_23","019_28_23","JOB","28","23","23","Allah ya gane hanyar zuwa wurinta. Shi ne kaɗai ya san inda take zama, ");
INSERT INTO hausa_vpl VALUES ("JB28_24","019_28_24","JOB","28","24","24","Gama yana ganin iyakar duniya kuma yana ganin duk abin da yake ƙarƙashin sama. ");
INSERT INTO hausa_vpl VALUES ("JB28_25","019_28_25","JOB","28","25","25","Lokacin da ya yi iska ya sa ta hura, ya kuma auna ruwaye. ");
INSERT INTO hausa_vpl VALUES ("JB28_26","019_28_26","JOB","28","26","26","Lokacin da ya yi wa ruwan sama doka da kuma hanya domin walƙiya, ");
INSERT INTO hausa_vpl VALUES ("JB28_27","019_28_27","JOB","28","27","27","sai ya dubi hikima ya auna ta; ya tabbatar da ita, ya gwada ta. ");
INSERT INTO hausa_vpl VALUES ("JB28_28","019_28_28","JOB","28","28","28","Ya kuma ce wa mutum, ‘Tsoron Ubangiji shi ne hikima, kuma guje wa mugunta shi ne fahimi.’ ” ");
INSERT INTO hausa_vpl VALUES ("JB29_1","019_29_1","JOB","29","1","1","Ayuba ya ci gaba da jawabinsa, ");
INSERT INTO hausa_vpl VALUES ("JB29_2","019_29_2","JOB","29","2","2","“Da ma ina nan lokacin da ya wuce baya can, kwanakin da Allah yake lura da ni, ");
INSERT INTO hausa_vpl VALUES ("JB29_3","019_29_3","JOB","29","3","3","lokacin da fitilarsa take haske a kaina na yi tafiya cikin duhu tare da haskensa. ");
INSERT INTO hausa_vpl VALUES ("JB29_4","019_29_4","JOB","29","4","4","Kwanakin da nake tasowa, lokacin da abokantakar Allah ta sa wa gidana albarka, ");
INSERT INTO hausa_vpl VALUES ("JB29_5","019_29_5","JOB","29","5","5","lokacin da Maɗaukaki yana tare da ni, kuma ’ya’yana suna kewaye da ni, ");
INSERT INTO hausa_vpl VALUES ("JB29_6","019_29_6","JOB","29","6","6","lokacin da ake zuba madara a inda nake takawa, duwatsu kuma suna ɓulɓulo mini man zaitun. ");
INSERT INTO hausa_vpl VALUES ("JB29_7","019_29_7","JOB","29","7","7","“Sa’ad da na je ƙofar birni na zauna a bainin jama’a, ");
INSERT INTO hausa_vpl VALUES ("JB29_8","019_29_8","JOB","29","8","8","matasan da suka gan ni sukan ja gefe tsofaffi kuma suka tashi tsaye; ");
INSERT INTO hausa_vpl VALUES ("JB29_9","019_29_9","JOB","29","9","9","sarakuna suka yi shiru suka rufe bakunansu da hannuwansu; ");
INSERT INTO hausa_vpl VALUES ("JB29_10","019_29_10","JOB","29","10","10","Muryar manya ta yi tsit harshensu ya manne a rufin bakunansu. ");
INSERT INTO hausa_vpl VALUES ("JB29_11","019_29_11","JOB","29","11","11","Duk wanda ya ji ni ya yaba mini waɗanda suka gan ni kuma sun amince da ni, ");
INSERT INTO hausa_vpl VALUES ("JB29_12","019_29_12","JOB","29","12","12","domin na ceci matalauta waɗanda suka nemi taimako, da marasa mahaifi waɗanda ba su da wanda zai taimake su. ");
INSERT INTO hausa_vpl VALUES ("JB29_13","019_29_13","JOB","29","13","13","Mutumin da yake bakin mutuwa ya sa mini albarka. Na faranta wa gwauruwa zuciya. ");
INSERT INTO hausa_vpl VALUES ("JB29_14","019_29_14","JOB","29","14","14","Na yafa adalci ya zama suturata; gaskiya ita ce rigata da rawanina. ");
INSERT INTO hausa_vpl VALUES ("JB29_15","019_29_15","JOB","29","15","15","Ni ne idon makafi kuma ƙafa ga guragu. ");
INSERT INTO hausa_vpl VALUES ("JB29_16","019_29_16","JOB","29","16","16","Ni mahaifi ne ga masu bukata; na tsaya wa baƙo. ");
INSERT INTO hausa_vpl VALUES ("JB29_17","019_29_17","JOB","29","17","17","Na karya ƙarfin mugaye na ƙwato waɗanda suke riƙe da haƙoransu. ");
INSERT INTO hausa_vpl VALUES ("JB29_18","019_29_18","JOB","29","18","18","“Na yi tunani cewa, ‘Zan mutu a cikin gidana, kwanakina da yawa kamar turɓayar ƙasa. ");
INSERT INTO hausa_vpl VALUES ("JB29_19","019_29_19","JOB","29","19","19","Jijiyoyina za su kai cikin ruwa, kuma raɓa za tă kwanta a rassana dukan dare. ");
INSERT INTO hausa_vpl VALUES ("JB29_20","019_29_20","JOB","29","20","20","Ɗaukakata za tă kasance tare da ni garau, bakana koyaushe sabo ne a hannuna.’ ");
INSERT INTO hausa_vpl VALUES ("JB29_21","019_29_21","JOB","29","21","21","“Mutane suna mai da hankali su saurare ni, suna yin shiru don su ji shawarata. ");
INSERT INTO hausa_vpl VALUES ("JB29_22","019_29_22","JOB","29","22","22","Bayan da na yi magana, ba su ƙara ce kome ba. Maganata ta shige su. ");
INSERT INTO hausa_vpl VALUES ("JB29_23","019_29_23","JOB","29","23","23","Sukan jira ni kamar yadda ake jiran ruwan sama. Sukan sha daga cikin maganganuna kamar mai shan ruwan bazara. ");
INSERT INTO hausa_vpl VALUES ("JB29_24","019_29_24","JOB","29","24","24","Sa’ad da na yi musu murmushi da ƙyar sukan yarda; hasken fuskata yana da daraja a gare su. ");
INSERT INTO hausa_vpl VALUES ("JB29_25","019_29_25","JOB","29","25","25","Na zaɓar masu inda za su bi na kuma zauna kamar sarkinsu; na zauna kamar sarki a cikin rundunansu; ina nan kamar mai yi wa masu makoki ta’aziyya. ");
INSERT INTO hausa_vpl VALUES ("JB30_1","019_30_1","JOB","30","1","1","“Amma yanzu suna yi mini ba’a waɗanda na girme su, waɗanda iyayensu maza ba su isa su zama karnukan kiwon garken tumakina ba. ");
INSERT INTO hausa_vpl VALUES ("JB30_2","019_30_2","JOB","30","2","2","Ina amfani ƙarfin hannuwansu gare ni, tun da ba su da sauran kuzari? ");
INSERT INTO hausa_vpl VALUES ("JB30_3","019_30_3","JOB","30","3","3","Duk sun rame don rashi da yunwa, suna yawo a gaigayar ƙasa a kufai da dare. ");
INSERT INTO hausa_vpl VALUES ("JB30_4","019_30_4","JOB","30","4","4","A cikin jeji suna tsinkar ganyaye marasa daɗi, jijiyoyin itacen kwakwa ne abincinsu. ");
INSERT INTO hausa_vpl VALUES ("JB30_5","019_30_5","JOB","30","5","5","An kore su daga cikin mutanensu, aka yi musu ihu kamar ɓarayi. ");
INSERT INTO hausa_vpl VALUES ("JB30_6","019_30_6","JOB","30","6","6","An sa dole su zauna a kwazazzabai da kuma cikin kogunan duwatsu da kuma cikin ramummuka cikin ƙasa. ");
INSERT INTO hausa_vpl VALUES ("JB30_7","019_30_7","JOB","30","7","7","Suka yi ta kuka kamar dabbobi a jeji, suka taru a ƙarƙashin sarƙaƙƙiya. ");
INSERT INTO hausa_vpl VALUES ("JB30_8","019_30_8","JOB","30","8","8","Mutane marasa hankali marasa suna, an kore su daga ƙasar. ");
INSERT INTO hausa_vpl VALUES ("JB30_9","019_30_9","JOB","30","9","9","“Yanzu kuma ’ya’yansu maza su suke yi mini ba’a cikin waƙa na zama abin banza a gare su. ");
INSERT INTO hausa_vpl VALUES ("JB30_10","019_30_10","JOB","30","10","10","Suna ƙyamata suna guduna; suna tofa mini miyau a fuska. ");
INSERT INTO hausa_vpl VALUES ("JB30_11","019_30_11","JOB","30","11","11","Yanzu da Allah ya kunce bakana ya ba ni wahala sun raba ni da mutuncina. ");
INSERT INTO hausa_vpl VALUES ("JB30_12","019_30_12","JOB","30","12","12","A hannun damana ’yan tā-da-na-zaune-tsaye sun tayar; sun sa tarko a ƙafafuna, sun yi shirin hallaka ni. ");
INSERT INTO hausa_vpl VALUES ("JB30_13","019_30_13","JOB","30","13","13","Sun ɓata mini hanyata; sun yi nasara cikin hallaka ni, ba tare da wani ya taimake su ba. ");
INSERT INTO hausa_vpl VALUES ("JB30_14","019_30_14","JOB","30","14","14","Suka nufo ni daga kowane gefe; suka auko mini da dukan ƙarfinsu. ");
INSERT INTO hausa_vpl VALUES ("JB30_15","019_30_15","JOB","30","15","15","Tsoro ya rufe ni; an kawar mini mutuncina kamar da iska, dukiyata ta watse kamar girgije. ");
INSERT INTO hausa_vpl VALUES ("JB30_16","019_30_16","JOB","30","16","16","“Yanzu raina yana ƙarewa; kwanakin wahala sun kama ni. ");
INSERT INTO hausa_vpl VALUES ("JB30_17","019_30_17","JOB","30","17","17","Dare ya huda ƙasusuwana; ina ta shan azaba ba hutawa. ");
INSERT INTO hausa_vpl VALUES ("JB30_18","019_30_18","JOB","30","18","18","A cikin girman ikonsa Allah ya zama kamar riga a jikina; ya shaƙe ni kamar wuyan rigata. ");
INSERT INTO hausa_vpl VALUES ("JB30_19","019_30_19","JOB","30","19","19","Ya jefa ni cikin laka, na zama ba kome ba sai ƙura da toka. ");
INSERT INTO hausa_vpl VALUES ("JB30_20","019_30_20","JOB","30","20","20","“Na yi kuka gare ka ya Allah, amma ba ka amsa mini ba. Na tashi tsaye, amma sai ka dube ni kawai. ");
INSERT INTO hausa_vpl VALUES ("JB30_21","019_30_21","JOB","30","21","21","Ka dube ni ba tausayi; Ka kai mini hari da ƙarfin hannunka. ");
INSERT INTO hausa_vpl VALUES ("JB30_22","019_30_22","JOB","30","22","22","Ka ɗaga ni sama ka ɗora ni a kan iska; ka jujjuya ni cikin hadari. ");
INSERT INTO hausa_vpl VALUES ("JB30_23","019_30_23","JOB","30","23","23","Na san za ka sauko da ni ga mutuwa zuwa wurin da kowane mai rai zai je. ");
INSERT INTO hausa_vpl VALUES ("JB30_24","019_30_24","JOB","30","24","24","“Ba shakka ba mai ɗora hannu a kan mutumin da yake cikin wahala. Lokacin da ya yi kukan neman taimako a cikin wahalarsa. ");
INSERT INTO hausa_vpl VALUES ("JB30_25","019_30_25","JOB","30","25","25","Ashe ban yi kuka domin waɗanda suke cikin damuwa ba? Ko zuciyata ba tă yi baƙin ciki domin matalauta ba? ");
INSERT INTO hausa_vpl VALUES ("JB30_26","019_30_26","JOB","30","26","26","Duk da haka sa’ad da nake begen abu mai kyau, mugun abu ne ya zo; Sa’ad da nake neman haske, sai duhu ya zo. ");
INSERT INTO hausa_vpl VALUES ("JB30_27","019_30_27","JOB","30","27","27","Zuciyata ba tă daina ƙuna ba; ina fuskantar kwanakin wahala. ");
INSERT INTO hausa_vpl VALUES ("JB30_28","019_30_28","JOB","30","28","28","Na yi baƙi ƙirin, amma ba rana ce ta ƙona ni ba. Na tsaya a cikin mutane, na kuma yi kuka don taimako. ");
INSERT INTO hausa_vpl VALUES ("JB30_29","019_30_29","JOB","30","29","29","Na zama ɗan’uwan diloli, na zama abokan mujiyoyi. ");
INSERT INTO hausa_vpl VALUES ("JB30_30","019_30_30","JOB","30","30","30","Fatar jikina ta yi baƙi tana ɓarewa; jikina yana ƙuna da zazzaɓi. ");
INSERT INTO hausa_vpl VALUES ("JB30_31","019_30_31","JOB","30","31","31","Garayata ta zama ta makoki, sarewata kuma ta zama ta kuka. ");
INSERT INTO hausa_vpl VALUES ("JB31_1","019_31_1","JOB","31","1","1","“Na yi alkawari da idanuna kada su dubi budurwa da muguwar sha’awa. ");
INSERT INTO hausa_vpl VALUES ("JB31_2","019_31_2","JOB","31","2","2","Gama mene ne rabon mutum daga Allah a sama, gādonsa daga Maɗaukaki a sama? ");
INSERT INTO hausa_vpl VALUES ("JB31_3","019_31_3","JOB","31","3","3","Ba masifa ba ne domin mugaye, hallaka kuma ga waɗanda suka yi ba daidai ba? ");
INSERT INTO hausa_vpl VALUES ("JB31_4","019_31_4","JOB","31","4","4","Bai ga hanyoyina ba ne bai ƙirga kowace takawata ba? ");
INSERT INTO hausa_vpl VALUES ("JB31_5","019_31_5","JOB","31","5","5","“In da na yi tafiya cikin rashin gaskiya ko kuma ƙafata ta yi sauri zuwa yin ƙarya, ");
INSERT INTO hausa_vpl VALUES ("JB31_6","019_31_6","JOB","31","6","6","Bari Allah yă auna a kan ma’auni na gaskiya zai kuma san cewa ni marar laifi ne. ");
INSERT INTO hausa_vpl VALUES ("JB31_7","019_31_7","JOB","31","7","7","In takawata ta kauce daga hanya, in zuciyata ta bi abin da idanuna ke so, ko kuma in hannuwana suna da laifi; ");
INSERT INTO hausa_vpl VALUES ("JB31_8","019_31_8","JOB","31","8","8","bari waɗansu su ci abin da na shuka, kuma bari a tuge amfanin gonata. ");
INSERT INTO hausa_vpl VALUES ("JB31_9","019_31_9","JOB","31","9","9","“In sha’awar mace ya shiga mini zuciya, ko kuma na laɓe a ƙofar maƙwabcina, ");
INSERT INTO hausa_vpl VALUES ("JB31_10","019_31_10","JOB","31","10","10","sai matata ta niƙa hatsin wani kuma waɗansu maza su kwana da ita. ");
INSERT INTO hausa_vpl VALUES ("JB31_11","019_31_11","JOB","31","11","11","Gama wannan zai zama abin kunya, zunubin da za a yi shari’a a kai. ");
INSERT INTO hausa_vpl VALUES ("JB31_12","019_31_12","JOB","31","12","12","Wuta ce take ƙuna har ta hallakar; za tă cinye saiwar abin da na shuka ƙurmus. ");
INSERT INTO hausa_vpl VALUES ("JB31_13","019_31_13","JOB","31","13","13","“In da na danne wa bayina maza da mata hakkinsu, sa’ad da suke da damuwa da ni, ");
INSERT INTO hausa_vpl VALUES ("JB31_14","019_31_14","JOB","31","14","14","me zan yi lokacin da Allah ya tuhume ni? Me zan ce lokacin da ya tambaye ni? ");
INSERT INTO hausa_vpl VALUES ("JB31_15","019_31_15","JOB","31","15","15","Shi wanda ya yi ni a cikin uwata ba shi ne ya yi su ba? Ba shi ne ya yi mu a cikin uwayenmu ba? ");
INSERT INTO hausa_vpl VALUES ("JB31_16","019_31_16","JOB","31","16","16","“In na hana wa matalauta abin da suke so, ko kuma in sa idanun gwauruwa su yi nauyi don kuka, ");
INSERT INTO hausa_vpl VALUES ("JB31_17","019_31_17","JOB","31","17","17","in na ajiye burodina don kaina kaɗai, ban kuwa ba wa marayu abinci sa’ad da suke jin yunwa, ");
INSERT INTO hausa_vpl VALUES ("JB31_18","019_31_18","JOB","31","18","18","amma tun suna tasowa na lura da su, kamar yadda mahaifi zai lura da ɗa, kuma tun da aka haife ni ina lura da gwauruwa. ");
INSERT INTO hausa_vpl VALUES ("JB31_19","019_31_19","JOB","31","19","19","In da na ga wani yana mutuwa don rashin sutura, ko wani mai bukata da ba shi da riga, ");
INSERT INTO hausa_vpl VALUES ("JB31_20","019_31_20","JOB","31","20","20","kuma zuciyarsa ba tă gode mini ba don na yi masa sutura da gashin tumakina, ");
INSERT INTO hausa_vpl VALUES ("JB31_21","019_31_21","JOB","31","21","21","in na ɗaga hannuna don in cuci maraya, domin na san in na faɗa za a ji ni a wurin masu shari’a, ");
INSERT INTO hausa_vpl VALUES ("JB31_22","019_31_22","JOB","31","22","22","bari hannuna yă guntule daga kafaɗata, bari yă tsinke daga inda aka haɗa shi. ");
INSERT INTO hausa_vpl VALUES ("JB31_23","019_31_23","JOB","31","23","23","Gama ina jin tsoron hallaka daga Allah, kuma domin tsoron ɗaukakarsa ba zan iya yin waɗannan abubuwa ba. ");
INSERT INTO hausa_vpl VALUES ("JB31_24","019_31_24","JOB","31","24","24","“In na dogara ga zinariya ko kuma na ce wa zallan zinariya, ‘Gare ki nake dogara,’ ");
INSERT INTO hausa_vpl VALUES ("JB31_25","019_31_25","JOB","31","25","25","in na yi fahariya don yawan dukiyata, arzikin da hannuwana suka samu. ");
INSERT INTO hausa_vpl VALUES ("JB31_26","019_31_26","JOB","31","26","26","In na dubi rana cikin haskenta, ko kuma wata yana tafiyarsa, ");
INSERT INTO hausa_vpl VALUES ("JB31_27","019_31_27","JOB","31","27","27","zuciyata ta jarrabtu gare su a ɓoye, hannuna kuma ya sumbace su. ");
INSERT INTO hausa_vpl VALUES ("JB31_28","019_31_28","JOB","31","28","28","Waɗannan ma za su zama zunubin da za a shari’anta ke nan don zai zama na yi wa Allah na sama rashin aminci. ");
INSERT INTO hausa_vpl VALUES ("JB31_29","019_31_29","JOB","31","29","29","“In na yi murna domin mugun abu ya faru da maƙiyina; ko kuma domin wahala ta same shi, ");
INSERT INTO hausa_vpl VALUES ("JB31_30","019_31_30","JOB","31","30","30","ban bar bakina yă yi zunubi ta wurin la’anta shi ba, ");
INSERT INTO hausa_vpl VALUES ("JB31_31","019_31_31","JOB","31","31","31","in mutanen gidana ba su taɓa cewa, ‘Wane ne bai ƙoshi da naman Ayuba ba?’ ");
INSERT INTO hausa_vpl VALUES ("JB31_32","019_31_32","JOB","31","32","32","Ba baƙon da ya taɓa kwana a titi, gama koyaushe ƙofata tana buɗe domin matafiya, ");
INSERT INTO hausa_vpl VALUES ("JB31_33","019_31_33","JOB","31","33","33","in na ɓoye zunubina yadda mutane suke yi, ta wurin ɓoye laifina a cikin zuciyata, ");
INSERT INTO hausa_vpl VALUES ("JB31_34","019_31_34","JOB","31","34","34","domin ina tsoron taron mutane kuma ina tsoron wulaƙancin da dangina za su yi mini, sai na yi shiru kuma ban fita waje ba. ");
INSERT INTO hausa_vpl VALUES ("JB31_35","019_31_35","JOB","31","35","35","(“Kash, da ina da wanda zai ji ni! Na sa hannu ga abin da na faɗa don kāre kaina, bari Maɗaukaki yă amsa mini; bari mai tuhumata da laifi yă yi ƙarata a rubuce. ");
INSERT INTO hausa_vpl VALUES ("JB31_36","019_31_36","JOB","31","36","36","Ba shakka sai in ɗora a kafaɗata, zan aza a kaina kamar rawani. ");
INSERT INTO hausa_vpl VALUES ("JB31_37","019_31_37","JOB","31","37","37","Zan ba shi lissafin duk abin da na taɓa yi; zan zo gabansa kamar ɗan sarki.) ");
INSERT INTO hausa_vpl VALUES ("JB31_38","019_31_38","JOB","31","38","38","“In ƙasata tana kuka da ni kunyoyinta duk sun cika da hawaye, ");
INSERT INTO hausa_vpl VALUES ("JB31_39","019_31_39","JOB","31","39","39","in na kwashe amfaninta ban biya ba ko kuma na kashe masu ita, ");
INSERT INTO hausa_vpl VALUES ("JB31_40","019_31_40","JOB","31","40","40","bari ƙaya ta fito a maimakon alkama ciyawa kuma a maimakon sha’ir.” Maganar Ayuba ta ƙare. ");
INSERT INTO hausa_vpl VALUES ("JB32_1","019_32_1","JOB","32","1","1","Sai mutanen nan uku suka daina amsa wa Ayuba, domin a ganinsa shi mai adalci ne. ");
INSERT INTO hausa_vpl VALUES ("JB32_2","019_32_2","JOB","32","2","2","Amma Elihu ɗan Barakel mutumin Buz na iyalin Ram, ya ji haushi da Ayuba don yă nuna shi ne mai gaskiya ba Allah ba. ");
INSERT INTO hausa_vpl VALUES ("JB32_3","019_32_3","JOB","32","3","3","Ya kuma ji haushin abokan nan guda uku, don sun kāsa amsa wa Ayuba ko da yake sun nuna Ayuba ne yake da laifi. ");
INSERT INTO hausa_vpl VALUES ("JB32_4","019_32_4","JOB","32","4","4","Elihu ya jira sai a wannan lokaci ne ya yi magana da Ayuba, don shi ne yaro a cikinsu duka. ");
INSERT INTO hausa_vpl VALUES ("JB32_5","019_32_5","JOB","32","5","5","Amma sa’ad da Elihu ya ga mutanen nan uku ba su da abin cewa, sai ya fusata. ");
INSERT INTO hausa_vpl VALUES ("JB32_6","019_32_6","JOB","32","6","6","Sai Elihu ɗan Barakel mutumin Buz ya ce, “Ni ƙarami ne a shekaru, ku kuma kun girme ni; shi ya sa na ji tsoro na kāsa gaya muku abin da na sani. ");
INSERT INTO hausa_vpl VALUES ("JB32_7","019_32_7","JOB","32","7","7","Na ɗauka ya kamata ‘shekaru su yi magana; ya kamata yawan shekaru su koyar da hikima.’ ");
INSERT INTO hausa_vpl VALUES ("JB32_8","019_32_8","JOB","32","8","8","Amma ruhun da yake cikin mutum, numfashin Maɗaukaki shi ne yake ba shi ganewa. ");
INSERT INTO hausa_vpl VALUES ("JB32_9","019_32_9","JOB","32","9","9","Ba tsofaffi ne kaɗai suke da hikima ba, ba masu yawan shekaru ne suke gane abin da yake daidai ba. ");
INSERT INTO hausa_vpl VALUES ("JB32_10","019_32_10","JOB","32","10","10","“Saboda haka nake ce muku, ku saurare ni; ni ma zan gaya muku abin da na sani. ");
INSERT INTO hausa_vpl VALUES ("JB32_11","019_32_11","JOB","32","11","11","Na jira sa’ad da kuke magana, na ji muhawwararku lokacin da kuke neman abin da za ku faɗa, ");
INSERT INTO hausa_vpl VALUES ("JB32_12","019_32_12","JOB","32","12","12","na saurare ku da kyau. Amma ba waninku da ya nuna Ayuba yana da laifi; ba ko ɗayanku da ya amsa muhawwararsa. ");
INSERT INTO hausa_vpl VALUES ("JB32_13","019_32_13","JOB","32","13","13","Kada ku ce, ‘Mun sami hikima; Allah ne kaɗai yake da ikon yin nasara da shi ba mutum ba.’ ");
INSERT INTO hausa_vpl VALUES ("JB32_14","019_32_14","JOB","32","14","14","Amma ba da ni Ayuba ya yi gardama ba kuma ba zan amsa masa da irin amsarku ba. ");
INSERT INTO hausa_vpl VALUES ("JB32_15","019_32_15","JOB","32","15","15","“Mamaki ya kama su kuma ba su da abin cewa; kalmomi sun kāsa musu. ");
INSERT INTO hausa_vpl VALUES ("JB32_16","019_32_16","JOB","32","16","16","Dole ne in jira yanzu da suka yi shiru, yanzu da suke tsaye a wurin ba su da amsa. ");
INSERT INTO hausa_vpl VALUES ("JB32_17","019_32_17","JOB","32","17","17","Ni ma zan faɗi nawa; ni ma zan faɗi abin da na sani. ");
INSERT INTO hausa_vpl VALUES ("JB32_18","019_32_18","JOB","32","18","18","Gama ina cike da magana, kuma ruhun da yake cikina yana iza ni; ");
INSERT INTO hausa_vpl VALUES ("JB32_19","019_32_19","JOB","32","19","19","a ciki ina kamar ruwan inabi wanda aka rufe a cikin kwalaba, kamar sabuwar salkar ruwan inabi mai shirin fashewa. ");
INSERT INTO hausa_vpl VALUES ("JB32_20","019_32_20","JOB","32","20","20","Dole in yi magana in sami lafiya; dole in buɗe baki in ba da amsa. ");
INSERT INTO hausa_vpl VALUES ("JB32_21","019_32_21","JOB","32","21","21","Ba zan nuna wa wani sonkai ba, ko kuma in yi wa wani daɗin baki ba; ");
INSERT INTO hausa_vpl VALUES ("JB32_22","019_32_22","JOB","32","22","22","gama da a ce na iya daɗin baki, da wanda ya yi ni ya ɗauke ni daga nan tuntuni. ");
INSERT INTO hausa_vpl VALUES ("JB33_1","019_33_1","JOB","33","1","1","“Amma yanzu, Ayuba, ka saurari abin da zan ce; ka sa hankali ga kowane abin da zan faɗa. ");
INSERT INTO hausa_vpl VALUES ("JB33_2","019_33_2","JOB","33","2","2","Zan yi magana; kalmomina suna dab da fitowa daga bakina. ");
INSERT INTO hausa_vpl VALUES ("JB33_3","019_33_3","JOB","33","3","3","Abin da zan faɗa gaskiya ne daga cikin zuciyata; bakina zai faɗi gaskiyar abin da na sani. ");
INSERT INTO hausa_vpl VALUES ("JB33_4","019_33_4","JOB","33","4","4","Ruhun Allah ne ya yi ni; numfashin Maɗaukaki ya ba ni rai. ");
INSERT INTO hausa_vpl VALUES ("JB33_5","019_33_5","JOB","33","5","5","Ka amsa mini in za ka iya; ka yi shirin fuskanta ta. ");
INSERT INTO hausa_vpl VALUES ("JB33_6","019_33_6","JOB","33","6","6","Ni kamar ka nake a gaban Allah; ni ma daga ƙasa aka yi ni. ");
INSERT INTO hausa_vpl VALUES ("JB33_7","019_33_7","JOB","33","7","7","Kada ka ji tsorona, ba abin da zai fi ƙarfinka. ");
INSERT INTO hausa_vpl VALUES ("JB33_8","019_33_8","JOB","33","8","8","“Amma ka faɗa na ji, na ji daidai abin da ka faɗa, ");
INSERT INTO hausa_vpl VALUES ("JB33_9","019_33_9","JOB","33","9","9","‘ni mai tsarki ne marar zunubi; ina da tsabta kuma ba ni da laifi. ");
INSERT INTO hausa_vpl VALUES ("JB33_10","019_33_10","JOB","33","10","10","Duk da haka Allah ya same ni da laifi; ya ɗauke ni maƙiyinsa, ");
INSERT INTO hausa_vpl VALUES ("JB33_11","019_33_11","JOB","33","11","11","ya daure ƙafafuna da sarƙa; yana tsaron duk inda na bi.’ ");
INSERT INTO hausa_vpl VALUES ("JB33_12","019_33_12","JOB","33","12","12","“Amma na gaya maka, a nan ba ka yi daidai ba, gama Allah ya fi mutum girma. ");
INSERT INTO hausa_vpl VALUES ("JB33_13","019_33_13","JOB","33","13","13","Don me ka yi masa gunaguni cewa ba ya amsa tambayoyin mutum? ");
INSERT INTO hausa_vpl VALUES ("JB33_14","019_33_14","JOB","33","14","14","Gama Allah yana magana, yanzu ga wannan hanya, yanzu kuma ga wata hanya ko da yake ba lalle mutum yă lura ba. ");
INSERT INTO hausa_vpl VALUES ("JB33_15","019_33_15","JOB","33","15","15","A cikin mafarki, cikin wahayi da dare, sa’ad da barci mai zurfi ya fāɗo a kan mutane lokacin da suke cikin barci kan gadajensu, ");
INSERT INTO hausa_vpl VALUES ("JB33_16","019_33_16","JOB","33","16","16","mai yiwuwa yă yi musu magana a cikin kunnuwansu yă razana su da gargaɗinsa, ");
INSERT INTO hausa_vpl VALUES ("JB33_17","019_33_17","JOB","33","17","17","don a juyar da su daga abin da yake yi da ba daidai ba a kuma hana su daga girman kai, ");
INSERT INTO hausa_vpl VALUES ("JB33_18","019_33_18","JOB","33","18","18","don a kāre su daga fāɗuwa cikin rami, a kāre su daga hallaka ta wurin takobi. ");
INSERT INTO hausa_vpl VALUES ("JB33_19","019_33_19","JOB","33","19","19","“Ko kuma mutum yă sha horo ta wurin kwanciya da ciwo da rashin jin daɗi cikin ƙasusuwansa, ");
INSERT INTO hausa_vpl VALUES ("JB33_20","019_33_20","JOB","33","20","20","yadda zai ji ƙyamar abinci, har yă ƙi son abinci mafi daɗi. ");
INSERT INTO hausa_vpl VALUES ("JB33_21","019_33_21","JOB","33","21","21","Naman jikinsa ya lalace ba wani abu mai kyau a ciki kuma ƙasusuwansa da suke a rufe da tsoka yanzu duk sun fito. ");
INSERT INTO hausa_vpl VALUES ("JB33_22","019_33_22","JOB","33","22","22","Ransa yana matsawa kusa da rami, ransa kuma kusa da ’yan aikan mutuwa. ");
INSERT INTO hausa_vpl VALUES ("JB33_23","019_33_23","JOB","33","23","23","Duk da haka, in akwai mala’ika a gefensa kamar matsakanci, ɗaya daga cikin dubu, da zai gaya wa mutum abin da yake daidai gare shi, ");
INSERT INTO hausa_vpl VALUES ("JB33_24","019_33_24","JOB","33","24","24","yă yi masa alheri yă ce, ‘Kada ka bari yă fāɗa cikin rami, na samu fansa dominsa.’ ");
INSERT INTO hausa_vpl VALUES ("JB33_25","019_33_25","JOB","33","25","25","Sa’an nan fatar jikinsa za tă zama sabuwa kamar ta jariri; za tă zama kamar lokacin da yake matashi. ");
INSERT INTO hausa_vpl VALUES ("JB33_26","019_33_26","JOB","33","26","26","Ya yi addu’a ga Allah ya kuwa samu alheri a wurinsa, yana ganin fuskar Allah yana kuma yin sowa don murna; Allah ya mayar da shi ya zama mai adalci. ");
INSERT INTO hausa_vpl VALUES ("JB33_27","019_33_27","JOB","33","27","27","Sa’an nan sai ya zo wurin, wurin mutane ya ce, ‘Na yi zunubi, na kauce wa abin da yake daidai, amma ban samu abin da ya kamata in samu ba. ");
INSERT INTO hausa_vpl VALUES ("JB33_28","019_33_28","JOB","33","28","28","Ya fanshi raina daga fāɗawa cikin rami, kuma zan rayu in ji daɗin hasken.’ ");
INSERT INTO hausa_vpl VALUES ("JB33_29","019_33_29","JOB","33","29","29","“Allah ya yi wa mutum duk waɗannan, sau biyu, har ma sau uku. ");
INSERT INTO hausa_vpl VALUES ("JB33_30","019_33_30","JOB","33","30","30","Ya juyo da ransa daga fāɗawa cikin rami, don hasken rai ya haskaka a kansa. ");
INSERT INTO hausa_vpl VALUES ("JB33_31","019_33_31","JOB","33","31","31","“Ka sa hankali da kyau, Ayuba, ka saurare ni; ka yi shiru zan yi magana. ");
INSERT INTO hausa_vpl VALUES ("JB33_32","019_33_32","JOB","33","32","32","In kana da abin da za ka ce, ka amsa mini; yi magana, domin ina so in ’yantar da kai. ");
INSERT INTO hausa_vpl VALUES ("JB33_33","019_33_33","JOB","33","33","33","Amma in ba haka ba, sai ka saurare ni; yi shiru, zan kuma koya maka hikima.” ");
INSERT INTO hausa_vpl VALUES ("JB34_1","019_34_1","JOB","34","1","1","Sa’an nan Elihu ya ce, ");
INSERT INTO hausa_vpl VALUES ("JB34_2","019_34_2","JOB","34","2","2","“Ku ji maganata, ku masu hikima; ku saurare ni, ku masu ilimi. ");
INSERT INTO hausa_vpl VALUES ("JB34_3","019_34_3","JOB","34","3","3","Gama kunne yana rarrabe magana kamar yadda harshe yake ɗanɗana abinci. ");
INSERT INTO hausa_vpl VALUES ("JB34_4","019_34_4","JOB","34","4","4","Bari mu zaɓi abin da yake daidai, bari mu koyi abin da yake mai kyau tare. ");
INSERT INTO hausa_vpl VALUES ("JB34_5","019_34_5","JOB","34","5","5","“Ayuba ya ce, ‘Ba ni da laifi, amma Allah ya hana mini hakkina. ");
INSERT INTO hausa_vpl VALUES ("JB34_6","019_34_6","JOB","34","6","6","Ko da yake ina da gaskiya, an ɗauke ni maƙaryaci; ko da yake ba ni da laifi, kibiyoyinsa sun ji mini ciwo wanda ba ya warkewa.’ ");
INSERT INTO hausa_vpl VALUES ("JB34_7","019_34_7","JOB","34","7","7","Wane mutum ne kamar Ayuba, wanda yake shan ba’a kamar ruwa? ");
INSERT INTO hausa_vpl VALUES ("JB34_8","019_34_8","JOB","34","8","8","Yana abokantaka da masu aikata mugunta; yana cuɗanya da mugaye. ");
INSERT INTO hausa_vpl VALUES ("JB34_9","019_34_9","JOB","34","9","9","Gama ya ce, ‘Ba ribar da mutum zai samu lokacin da yake ƙoƙari yă faranta wa Allah zuciya.’ ");
INSERT INTO hausa_vpl VALUES ("JB34_10","019_34_10","JOB","34","10","10","“Saboda haka ku saurare ni, ku masu ganewa. Ko kaɗan Allah ba ya mugunta, Maɗaukaki ba ya kuskure. ");
INSERT INTO hausa_vpl VALUES ("JB34_11","019_34_11","JOB","34","11","11","Yana biyan mutum bisa ga abin da ya yi; yana kawo masa abin da ayyukansa suka jawo. ");
INSERT INTO hausa_vpl VALUES ("JB34_12","019_34_12","JOB","34","12","12","Ba zai yiwu Allah yă yi ba daidai ba, Maɗaukaki ba zai yi shari’a marar gaskiya ba. ");
INSERT INTO hausa_vpl VALUES ("JB34_13","019_34_13","JOB","34","13","13","Wane ne ya ba shi iko yă lura da duniya? Wane ne ya ba shi iko kan dukan duniya? ");
INSERT INTO hausa_vpl VALUES ("JB34_14","019_34_14","JOB","34","14","14","In nufinsa ne ya kuma janye ruhunsa da numfashinsa, ");
INSERT INTO hausa_vpl VALUES ("JB34_15","019_34_15","JOB","34","15","15","’yan adam duka za su hallaka tare, mutum kuma zai koma ƙasa. ");
INSERT INTO hausa_vpl VALUES ("JB34_16","019_34_16","JOB","34","16","16","“In kana da ganewa sai ka saurari wannan; ka saurari abin da zan ce. ");
INSERT INTO hausa_vpl VALUES ("JB34_17","019_34_17","JOB","34","17","17","Maƙiyin gaskiya zai iya yin mulki? Za ka iya ba mai gaskiya, Maɗaukaki laifi? ");
INSERT INTO hausa_vpl VALUES ("JB34_18","019_34_18","JOB","34","18","18","Ba shi ne ya ce wa sarakuna, ‘Ba ku da amfani ba,’ ya ce wa manya ‘Ku mugaye ne,’ ");
INSERT INTO hausa_vpl VALUES ("JB34_19","019_34_19","JOB","34","19","19","wanda ba ya nuna sonkai ga ’ya’yan sarki kuma ba ya goyon bayan masu arziki a kan matalauta, gama dukansu shi ya yi su da hannuwansa. ");
INSERT INTO hausa_vpl VALUES ("JB34_20","019_34_20","JOB","34","20","20","Suna mutuwa nan take, a cikin tsakiyar dare; an girgiza mutanen amma sun wuce; an taɓa manya amma ba da hannun mutum ba. ");
INSERT INTO hausa_vpl VALUES ("JB34_21","019_34_21","JOB","34","21","21","“Idanunsa suna kan al’amuran mutane; yana ganin tafiyarsu duka. ");
INSERT INTO hausa_vpl VALUES ("JB34_22","019_34_22","JOB","34","22","22","Babu wuri mai duhu, babu inuwa mai duhu, inda masu aikata mugunta za su ɓoye. ");
INSERT INTO hausa_vpl VALUES ("JB34_23","019_34_23","JOB","34","23","23","Allah ba ya bukata yă ci gaba da bincike mutane, har da za su zo gabansa don yă shari’anta su. ");
INSERT INTO hausa_vpl VALUES ("JB34_24","019_34_24","JOB","34","24","24","Ba tare da tambaya ba yana ragargaza masu iko, yă kuma sa waɗansu a wurinsu. ");
INSERT INTO hausa_vpl VALUES ("JB34_25","019_34_25","JOB","34","25","25","Gama yana sane da abubuwan da suke yi, yana hamɓarar da su da dare a kuma ragargaza su. ");
INSERT INTO hausa_vpl VALUES ("JB34_26","019_34_26","JOB","34","26","26","Yana ba su horo, don muguntarsu, inda kowa zai gan su, ");
INSERT INTO hausa_vpl VALUES ("JB34_27","019_34_27","JOB","34","27","27","domin sun juya daga binsa, kuma ba su kula da hanyoyinsa ba. ");
INSERT INTO hausa_vpl VALUES ("JB34_28","019_34_28","JOB","34","28","28","Sun sa kukan matalauta ya kai wurinsa yadda ya kai ga jin kukan masu bukata. ");
INSERT INTO hausa_vpl VALUES ("JB34_29","019_34_29","JOB","34","29","29","Amma in ya yi shiru, wa zai ba shi laifi? In ya ɓoye fuskarsa, wa zai gan shi? Duk da haka shi yake da iko kan mutum da al’umma duka, ");
INSERT INTO hausa_vpl VALUES ("JB34_30","019_34_30","JOB","34","30","30","yana hana wanda bai san Allah ba yă yi mulki, ya hana shi sa wa mutane tarko. ");
INSERT INTO hausa_vpl VALUES ("JB34_31","019_34_31","JOB","34","31","31","“A ce mutum ya ce wa Allah, ‘Na yi laifi, amma ba zan sāke saɓa wa wani ba. ");
INSERT INTO hausa_vpl VALUES ("JB34_32","019_34_32","JOB","34","32","32","Ka koya mini abin da ba zan iya gani ba; in na yi ba daidai ba, ba zan sāke yi ba.’ ");
INSERT INTO hausa_vpl VALUES ("JB34_33","019_34_33","JOB","34","33","33","Ya kamata Allah yă yi maka bisa ga abin da ka ce ne, sa’ad da ka ƙi ka tuba? Dole kai ka zaɓa, ba ni ba; yanzu ka gaya mini abin da ka sani. ");
INSERT INTO hausa_vpl VALUES ("JB34_34","019_34_34","JOB","34","34","34","“Mutane masu ganewa za su ce, masu hikima waɗanda suka ji ni za su ce mini, ");
INSERT INTO hausa_vpl VALUES ("JB34_35","019_34_35","JOB","34","35","35","‘Ayuba ya yi magana cikin rashin sani; maganganunsa na marar hikima ne.’ ");
INSERT INTO hausa_vpl VALUES ("JB34_36","019_34_36","JOB","34","36","36","Kash, da za a gwada Ayuba har ƙarshe, domin yana ba da amsa kamar mugun mutum. ");
INSERT INTO hausa_vpl VALUES ("JB34_37","019_34_37","JOB","34","37","37","Ya ƙara tawaye a kan zunubansa; ya tafa hannuwansa na reni a cikinmu ya kuma ƙara yawan maganganunsa ga Allah.” ");
INSERT INTO hausa_vpl VALUES ("JB35_1","019_35_1","JOB","35","1","1","Sai Elihu ya ce, ");
INSERT INTO hausa_vpl VALUES ("JB35_2","019_35_2","JOB","35","2","2","“Ko kana tsammani wannan gaskiya ne? Kana cewa, ‘Ni mai adalci ne a gaban Allah.’ ");
INSERT INTO hausa_vpl VALUES ("JB35_3","019_35_3","JOB","35","3","3","Duk da haka kana tambayarsa cewa, ‘Wace riba nake da ita, kuma mene ne zan samu ta wurin ƙin yin zunubi?’ ");
INSERT INTO hausa_vpl VALUES ("JB35_4","019_35_4","JOB","35","4","4","“Zan so in ba ka amsa kai tare da abokanka. ");
INSERT INTO hausa_vpl VALUES ("JB35_5","019_35_5","JOB","35","5","5","Ku ɗaga kai ku dubi sama ku gani; ku dubi gizagizai a samanku. ");
INSERT INTO hausa_vpl VALUES ("JB35_6","019_35_6","JOB","35","6","6","In kun yi zunubi ta yaya wannan zai shafi Allah? In zunubanku sun yi yawa, me wannan zai yi masa? ");
INSERT INTO hausa_vpl VALUES ("JB35_7","019_35_7","JOB","35","7","7","In kuna da adalci, me kuka ba shi, ko kuma me ya karɓa daga hannunku? ");
INSERT INTO hausa_vpl VALUES ("JB35_8","019_35_8","JOB","35","8","8","Muguntarku takan shafi mutum kamar ku ne kaɗai, adalcinku kuma yakan shafi ’yan adam ne kaɗai. ");
INSERT INTO hausa_vpl VALUES ("JB35_9","019_35_9","JOB","35","9","9","“Mutane suna kuka don yawan zalunci; suna roƙo don taimako daga hannu mai ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("JB35_10","019_35_10","JOB","35","10","10","Amma ba wanda ya ce, ‘Ina Allah wanda ya halicce ni, mai ba da waƙoƙi cikin dare, ");
INSERT INTO hausa_vpl VALUES ("JB35_11","019_35_11","JOB","35","11","11","wanda ya fi koya mana fiye da dabbobin duniya ya kuma sa muka fi tsuntsayen cikin iska hikima.’ ");
INSERT INTO hausa_vpl VALUES ("JB35_12","019_35_12","JOB","35","12","12","Ba ya amsawa lokacin da mutane suka yi kira don taimako domin girman kan mugaye. ");
INSERT INTO hausa_vpl VALUES ("JB35_13","019_35_13","JOB","35","13","13","Lalle Allah ba ya sauraron roƙonsu na wofi; Maɗaukaki ba ya kula da roƙonsu. ");
INSERT INTO hausa_vpl VALUES ("JB35_14","019_35_14","JOB","35","14","14","Ta yaya zai saurara sosai ko zai saurara lokacin da kake cewa ba ka ganinsa, cewa ka kawo ƙara a wurinsa kuma dole ka jira shi. ");
INSERT INTO hausa_vpl VALUES ("JB35_15","019_35_15","JOB","35","15","15","Kuma ka ce, ba ya ba da horo cikin fushinsa ko kaɗan ba ya kula da mugunta. ");
INSERT INTO hausa_vpl VALUES ("JB35_16","019_35_16","JOB","35","16","16","Saboda haka Ayuba ya buɗe baki yana magana barkatai; yana ta yawan magana ba tare da sani ba.” ");
INSERT INTO hausa_vpl VALUES ("JB36_1","019_36_1","JOB","36","1","1","Elihu ya ci gaba, ");
INSERT INTO hausa_vpl VALUES ("JB36_2","019_36_2","JOB","36","2","2","“Ka ɗan ƙara haƙuri da ni kaɗan, zan kuma nuna maka cewa akwai sauran abubuwan da zan faɗa a madadin Allah. ");
INSERT INTO hausa_vpl VALUES ("JB36_3","019_36_3","JOB","36","3","3","Daga nesa na sami sanina; zan nuna cewa Mahaliccina shi mai gaskiya ne. ");
INSERT INTO hausa_vpl VALUES ("JB36_4","019_36_4","JOB","36","4","4","Abin da zan gaya maka ba ƙarya ba ne; mai cikakken sani yana tare da kai. ");
INSERT INTO hausa_vpl VALUES ("JB36_5","019_36_5","JOB","36","5","5","“Allah mai iko ne, amma ba ya rena mutane; shi mai girma ne cikin manufarsa. ");
INSERT INTO hausa_vpl VALUES ("JB36_6","019_36_6","JOB","36","6","6","Ba ya barin mugaye da rai sai dai yana ba waɗanda ake tsanantawa hakkinsu. ");
INSERT INTO hausa_vpl VALUES ("JB36_7","019_36_7","JOB","36","7","7","Ba ya fasa duban masu adalci; yana sa su tare da sarakuna yana ɗaukaka su har abada. ");
INSERT INTO hausa_vpl VALUES ("JB36_8","019_36_8","JOB","36","8","8","Amma in mutane suna daure da sarƙoƙi, ƙunci kuma ya daure su, ");
INSERT INTO hausa_vpl VALUES ("JB36_9","019_36_9","JOB","36","9","9","yana gaya musu abin da suka yi, cewa sun yi zunubi da girman kai. ");
INSERT INTO hausa_vpl VALUES ("JB36_10","019_36_10","JOB","36","10","10","Yana sa su saurari gyara yă kuma umarce su su tuba daga muguntarsu. ");
INSERT INTO hausa_vpl VALUES ("JB36_11","019_36_11","JOB","36","11","11","In sun yi biyayya suka bauta masa, za su yi rayuwa dukan kwanakinsu cikin wadata shekarunsu kuma cikin kwanciyar zuciya. ");
INSERT INTO hausa_vpl VALUES ("JB36_12","019_36_12","JOB","36","12","12","Amma in ba su saurara ba, za su hallaka da takobi kuma za su mutu ba ilimi. ");
INSERT INTO hausa_vpl VALUES ("JB36_13","019_36_13","JOB","36","13","13","“Waɗanda ba su da Allah a zuciyarsu su ne suke riƙe fushi; ko sa’ad da ya ba su horo, ba su neman taimakonsa. ");
INSERT INTO hausa_vpl VALUES ("JB36_14","019_36_14","JOB","36","14","14","Suna mutuwa tun suna matasa, cikin ƙazamar rayuwar karuwanci. ");
INSERT INTO hausa_vpl VALUES ("JB36_15","019_36_15","JOB","36","15","15","Amma yana kuɓutar da masu wahala; yana magana da su cikin wahalarsu. ");
INSERT INTO hausa_vpl VALUES ("JB36_16","019_36_16","JOB","36","16","16","“Yana so yă rinjaye ka daga haƙoran ƙunci, zuwa wuri mai sauƙi inda ba matsi zuwa teburinka cike da abincin da kake so. ");
INSERT INTO hausa_vpl VALUES ("JB36_17","019_36_17","JOB","36","17","17","Amma yanzu an cika ka da hukuncin da ya kamata a yi wa mugaye; shari’a da kuma gaskiya sun kama ka. ");
INSERT INTO hausa_vpl VALUES ("JB36_18","019_36_18","JOB","36","18","18","Ka yi hankali kada wani yă ruɗe ka da arziki; kada ka bar toshiya ta sa ka juya. ");
INSERT INTO hausa_vpl VALUES ("JB36_19","019_36_19","JOB","36","19","19","Dukiyarka ko dukan yawan ƙoƙarinka sun isa su riƙe ka su hana ka shan ƙunci? ");
INSERT INTO hausa_vpl VALUES ("JB36_20","019_36_20","JOB","36","20","20","Kada ka yi marmari dare yă yi, don a fitar da mutane daga gidajensu. ");
INSERT INTO hausa_vpl VALUES ("JB36_21","019_36_21","JOB","36","21","21","Ka kula kada ka juya ga mugunta, abin da ka fi so fiye da wahala. ");
INSERT INTO hausa_vpl VALUES ("JB36_22","019_36_22","JOB","36","22","22","“An ɗaukaka Allah cikin ikonsa. Wane ne malami kamar sa? ");
INSERT INTO hausa_vpl VALUES ("JB36_23","019_36_23","JOB","36","23","23","Wane ne ya nuna masa hanyar da zai bi, ko kuma wane ne ya ce masa, ‘Ba ka yi daidai ba?’ ");
INSERT INTO hausa_vpl VALUES ("JB36_24","019_36_24","JOB","36","24","24","Ka tuna ka ɗaukaka aikinsa, waɗanda mutane suka yaba a cikin waƙa. ");
INSERT INTO hausa_vpl VALUES ("JB36_25","019_36_25","JOB","36","25","25","Dukan ’yan adam sun gani; mutane sun hanga daga nesa. ");
INSERT INTO hausa_vpl VALUES ("JB36_26","019_36_26","JOB","36","26","26","Allah mai girma ne, ya wuce ganewarmu! Yawan shekarunsa ba su bincikuwa. ");
INSERT INTO hausa_vpl VALUES ("JB36_27","019_36_27","JOB","36","27","27","“Yana sa ruwa yă zama tururi yă zubo daga sama. ");
INSERT INTO hausa_vpl VALUES ("JB36_28","019_36_28","JOB","36","28","28","Gizagizai suna zubo da raɓarsu kuma ruwan sama yana zubowa ’yan adam a wadace. ");
INSERT INTO hausa_vpl VALUES ("JB36_29","019_36_29","JOB","36","29","29","Wane ne zai iya gane yadda ya shimfiɗa gizagizai yadda yake tsawa daga wurin zamansa? ");
INSERT INTO hausa_vpl VALUES ("JB36_30","019_36_30","JOB","36","30","30","Dubi yadda ya baza walƙiyarsa kewaye da shi, tana haskaka zurfin teku. ");
INSERT INTO hausa_vpl VALUES ("JB36_31","019_36_31","JOB","36","31","31","Haka yake mulkin al’ummai yana kuma tanada abinci a wadace. ");
INSERT INTO hausa_vpl VALUES ("JB36_32","019_36_32","JOB","36","32","32","Yana cika hannuwansa da walƙiya kuma yana ba ta umarni tă fāɗi a inda ya yi nufi. ");
INSERT INTO hausa_vpl VALUES ("JB36_33","019_36_33","JOB","36","33","33","Tsawarsa tana nuna cewa babbar iska da ruwa suna zuwa; ko shanu sun san da zuwansa. ");
INSERT INTO hausa_vpl VALUES ("JB37_1","019_37_1","JOB","37","1","1","“Wannan ya sa gabana ya fāɗi, zuciyata ta yi tsalle. ");
INSERT INTO hausa_vpl VALUES ("JB37_2","019_37_2","JOB","37","2","2","Ka saurara! Ka saurari rurin muryarsa, tsawar da take fita daga bakinsa. ");
INSERT INTO hausa_vpl VALUES ("JB37_3","019_37_3","JOB","37","3","3","Ya saki walƙiyarsa, a ƙarƙashin dukan sammai ya kuma aika ta ko’ina a cikin duniya. ");
INSERT INTO hausa_vpl VALUES ("JB37_4","019_37_4","JOB","37","4","4","Bayan wannan sai ƙarar rurinsa ta biyo; Ya tsawata da muryarsa mai girma. Sa’ad da ya sāke yin tsawa ba ya rage wani abu. ");
INSERT INTO hausa_vpl VALUES ("JB37_5","019_37_5","JOB","37","5","5","Muryar Allah tana tsawatawa a hanyoyi masu ban al’ajabi; yana yin manyan abubuwa waɗanda sun wuce ganewarmu. ");
INSERT INTO hausa_vpl VALUES ("JB37_6","019_37_6","JOB","37","6","6","Yakan ce wa dusar ƙanƙara, ‘Fāɗo a kan duniya,’ ya kuma ce wa ruwa, ‘Zubo da ƙarfi.’ ");
INSERT INTO hausa_vpl VALUES ("JB37_7","019_37_7","JOB","37","7","7","Domin dukan mutanen da ya halitta za su san aikinsa, ya hana kowane mutum yin wahalar aiki. ");
INSERT INTO hausa_vpl VALUES ("JB37_8","019_37_8","JOB","37","8","8","Dabbobi sun ɓoye; sun zauna cikin kogunansu. ");
INSERT INTO hausa_vpl VALUES ("JB37_9","019_37_9","JOB","37","9","9","Guguwa tana fitowa daga inda take, sanyi kuma daga iska mai sanyi. ");
INSERT INTO hausa_vpl VALUES ("JB37_10","019_37_10","JOB","37","10","10","Da numfashinsa Allah yana samar da ƙanƙara sai manyan ruwaye su zama ƙanƙara. ");
INSERT INTO hausa_vpl VALUES ("JB37_11","019_37_11","JOB","37","11","11","Yana cika gizagizai da lema; yana baza walƙiyarsa ta cikinsu. ");
INSERT INTO hausa_vpl VALUES ("JB37_12","019_37_12","JOB","37","12","12","Bisa ga bishewarsa suke juyawa a kan fuskar duniya, suna yin dukan abin da ya umarce su su yi. ");
INSERT INTO hausa_vpl VALUES ("JB37_13","019_37_13","JOB","37","13","13","Yana aiko da ruwa domin horon mutane, ko kuma don yă jiƙa duniya yă kuma nuna ƙaunarsa. ");
INSERT INTO hausa_vpl VALUES ("JB37_14","019_37_14","JOB","37","14","14","“Ka saurari wannan Ayuba; ka tsaya ka dubi abubuwan al’ajabi na Allah. ");
INSERT INTO hausa_vpl VALUES ("JB37_15","019_37_15","JOB","37","15","15","Ko ka san yadda Allah yake iko da gizagizai ya kuma sa walƙiyarsa ta haskaka? ");
INSERT INTO hausa_vpl VALUES ("JB37_16","019_37_16","JOB","37","16","16","Ko ka san yadda gizagizai suke tsayawa cik a sararin sama, waɗannan abubuwa al’ajabi na mai cikakken sani. ");
INSERT INTO hausa_vpl VALUES ("JB37_17","019_37_17","JOB","37","17","17","Kai mai sa kaya don ka ji ɗumi lokacin da iska mai sanyi take hurawa, ");
INSERT INTO hausa_vpl VALUES ("JB37_18","019_37_18","JOB","37","18","18","ko za ka iya shimfiɗa sararin sama tare da shi da ƙarfi kamar madubi? ");
INSERT INTO hausa_vpl VALUES ("JB37_19","019_37_19","JOB","37","19","19","“Gaya mana abin da ya kamata mu ce masa; ba za mu iya kawo ƙara ba domin duhunmu. ");
INSERT INTO hausa_vpl VALUES ("JB37_20","019_37_20","JOB","37","20","20","Ko za a gaya masa cewa ina so in yi magana? Ko wani zai nemi a haɗiye shi? ");
INSERT INTO hausa_vpl VALUES ("JB37_21","019_37_21","JOB","37","21","21","Yanzu ba wanda zai iya kallon rana, yadda take da haske a sararin sama bayan iska ta share ta. ");
INSERT INTO hausa_vpl VALUES ("JB37_22","019_37_22","JOB","37","22","22","Yana fitowa daga arewa da haske na zinariya, Allah yana zuwa da ɗaukaka mai ban al’ajabi. ");
INSERT INTO hausa_vpl VALUES ("JB37_23","019_37_23","JOB","37","23","23","Maɗaukaki ya fi ƙarfin ganewarmu, shi babban mai iko ne, mai gaskiya da babban adalci, ba ya cutar mutum. ");
INSERT INTO hausa_vpl VALUES ("JB37_24","019_37_24","JOB","37","24","24","Saboda haka, mutane suke girmama shi, ko bai kula da waɗanda suke gani su masu hikima ba ne?” ");
INSERT INTO hausa_vpl VALUES ("JB38_1","019_38_1","JOB","38","1","1","Sa’an nan Ubangiji ya amsa wa Ayuba. Ya ce, ");
INSERT INTO hausa_vpl VALUES ("JB38_2","019_38_2","JOB","38","2","2","“Wane ne wannan da yake ɓata mini shawarata da surutan wofi? ");
INSERT INTO hausa_vpl VALUES ("JB38_3","019_38_3","JOB","38","3","3","Ka sha ɗamara kamar namiji; zan yi maka tambaya, za ka kuwa amsa mini. ");
INSERT INTO hausa_vpl VALUES ("JB38_4","019_38_4","JOB","38","4","4","“Kana ina lokacin da na aza harsashen duniya? Gaya mini, in ka sani. ");
INSERT INTO hausa_vpl VALUES ("JB38_5","019_38_5","JOB","38","5","5","Wane ne ya zāna girmanta? Ba shakka ka sani! Wane ne ya ja layin aunawa a kanta? ");
INSERT INTO hausa_vpl VALUES ("JB38_6","019_38_6","JOB","38","6","6","A kan me aka kafa tushenta, ko kuma wa ya sa dutsen kan kusurwarta, ");
INSERT INTO hausa_vpl VALUES ("JB38_7","019_38_7","JOB","38","7","7","yayinda taurarin safe suke waƙa tare dukan mala’iku kuma suka yi sowa don farin ciki. ");
INSERT INTO hausa_vpl VALUES ("JB38_8","019_38_8","JOB","38","8","8","“Wane ne ya rufe teku a bayan ƙofofi, lokacin da ya burtsatso daga cikin ciki. ");
INSERT INTO hausa_vpl VALUES ("JB38_9","019_38_9","JOB","38","9","9","Lokacin da na yi wa gizagizai riga na kuma naɗe su a cikin duhu sosai, ");
INSERT INTO hausa_vpl VALUES ("JB38_10","019_38_10","JOB","38","10","10","sa’ad da na yi masa iyaka na sa masa ƙofofi da wurin kullewa. ");
INSERT INTO hausa_vpl VALUES ("JB38_11","019_38_11","JOB","38","11","11","Sa’ad da na ce ga iyakar inda za ka kai, ga inda raƙuman ruwanka za su tsaya? ");
INSERT INTO hausa_vpl VALUES ("JB38_12","019_38_12","JOB","38","12","12","“Ko ka taɓa ba safiya umarni ko kuma ka sa asuba ta fito, ");
INSERT INTO hausa_vpl VALUES ("JB38_13","019_38_13","JOB","38","13","13","don ta kama gefen duniya ta kakkaɓe mugaye daga cikinta? ");
INSERT INTO hausa_vpl VALUES ("JB38_14","019_38_14","JOB","38","14","14","Ƙasa ta sāke siffa kamar laka da aka yi wa hatimi; ta fito a fili kamar riga. ");
INSERT INTO hausa_vpl VALUES ("JB38_15","019_38_15","JOB","38","15","15","An hana mugaye haskensu, hannun da suka ɗaga an karya shi. ");
INSERT INTO hausa_vpl VALUES ("JB38_16","019_38_16","JOB","38","16","16","“Ko ka taɓa tafiya zuwa maɓulɓulan teku, ko kuma ka taɓa zuwa cikin zurfin lungun teku? ");
INSERT INTO hausa_vpl VALUES ("JB38_17","019_38_17","JOB","38","17","17","Ko an taɓa nuna maka ƙofar mutuwa? Ko ka taɓa ganin ƙofar inuwar duhun mutuwa? ");
INSERT INTO hausa_vpl VALUES ("JB38_18","019_38_18","JOB","38","18","18","Ko ka gane fāɗin duniya? Gaya mini, in ka san wannan duka. ");
INSERT INTO hausa_vpl VALUES ("JB38_19","019_38_19","JOB","38","19","19","“Ina ne hanyar zuwa gidan haske? Kuma a ina duhu yake zama? ");
INSERT INTO hausa_vpl VALUES ("JB38_20","019_38_20","JOB","38","20","20","Ko za ka iya kai su wurarensu? Ka san hanyar zuwa wurin da suke zama? ");
INSERT INTO hausa_vpl VALUES ("JB38_21","019_38_21","JOB","38","21","21","Ba shakka ka sani, gama an riga an haife ka a lokacin! Ka yi shekaru da yawa kana rayuwa. ");
INSERT INTO hausa_vpl VALUES ("JB38_22","019_38_22","JOB","38","22","22","“Ka taɓa shiga rumbunan dusar ƙanƙara ko ka taɓa ganin rumbunan ƙanƙara ");
INSERT INTO hausa_vpl VALUES ("JB38_23","019_38_23","JOB","38","23","23","waɗanda nake ajiya domin lokacin wahala, domin kwanakin yaƙi da faɗa? ");
INSERT INTO hausa_vpl VALUES ("JB38_24","019_38_24","JOB","38","24","24","Ina ne hanyar zuwa wurin da ake samun walƙiya, ko kuma inda daga nan ne ake watsa iskar gabas zuwa ko’ina cikin duniya? ");
INSERT INTO hausa_vpl VALUES ("JB38_25","019_38_25","JOB","38","25","25","Wane ne ya yanka hanyar wucewar ruwa, da kuma hanyar walƙiyar tsawa ");
INSERT INTO hausa_vpl VALUES ("JB38_26","019_38_26","JOB","38","26","26","don ba da ruwa a ƙasar da ba kowa a wurin jeji inda ba mai zama ciki ");
INSERT INTO hausa_vpl VALUES ("JB38_27","019_38_27","JOB","38","27","27","don a ƙosar da wurin da ya bushe a sa ciyawa ta tsiro a can? ");
INSERT INTO hausa_vpl VALUES ("JB38_28","019_38_28","JOB","38","28","28","Ruwan sama yana da mahaifi? Wa ya zama mahaifin raɓa? ");
INSERT INTO hausa_vpl VALUES ("JB38_29","019_38_29","JOB","38","29","29","Daga cikin wane ne aka haifi ƙanƙara? Wane ne ya haifi jaura daga sammai ");
INSERT INTO hausa_vpl VALUES ("JB38_30","019_38_30","JOB","38","30","30","lokacin da ruwa ya zama da ƙarfi kamar dutse, lokacin da saman ruwa ya daskare? ");
INSERT INTO hausa_vpl VALUES ("JB38_31","019_38_31","JOB","38","31","31","“Za ka iya daure kyakkyawar kaza da ’ya’yanta? Ko za ka iya kunce igiyoyin mafarauci da kare da zomo? ");
INSERT INTO hausa_vpl VALUES ("JB38_32","019_38_32","JOB","38","32","32","Za ka iya tattara taurari bisa ga lokacinsu ko kuma ka bi da beyar da ’ya’yanta zuwa waje? ");
INSERT INTO hausa_vpl VALUES ("JB38_33","019_38_33","JOB","38","33","33","Ka san dokokin sammai? Ko za ka iya faɗar dangantakar Allah da duniya? ");
INSERT INTO hausa_vpl VALUES ("JB38_34","019_38_34","JOB","38","34","34","“Za ka iya tsawata wa gizagizai ka kuma rufe kanka da ambaliyar ruwa? ");
INSERT INTO hausa_vpl VALUES ("JB38_35","019_38_35","JOB","38","35","35","Kai ne kake aika walƙiya da tsawa zuwa inda suke zuwa? Ko suna zuwa wurinka su ce, ‘Ga mu nan mun zo?’ ");
INSERT INTO hausa_vpl VALUES ("JB38_36","019_38_36","JOB","38","36","36","Wane ne yake cika zuciya da hikima ko kuma yake ba zuciya ganewa? ");
INSERT INTO hausa_vpl VALUES ("JB38_37","019_38_37","JOB","38","37","37","Wane ne yake da hikimar iya ƙirga gizagizai? Wane ne zai iya karkato bakunan tulunan sammai ");
INSERT INTO hausa_vpl VALUES ("JB38_38","019_38_38","JOB","38","38","38","sa’ad da ƙura ta yi yawa ta daskare a wuri ɗaya? ");
INSERT INTO hausa_vpl VALUES ("JB38_39","019_38_39","JOB","38","39","39","“Za ka iya farauto wa zakanya nama, ka kuma kawar wa zakoki yunwarsu. ");
INSERT INTO hausa_vpl VALUES ("JB38_40","019_38_40","JOB","38","40","40","Lokacin da suka kwanta cikin kogunansu, ko kuma lokacin da suke a wurin ɓuyansu? ");
INSERT INTO hausa_vpl VALUES ("JB38_41","019_38_41","JOB","38","41","41","Wane ne yake ba hankaka abinci lokacin da ’ya’yansa suke kuka ga Allah, kuma suna yawo don rashin abinci? ");
INSERT INTO hausa_vpl VALUES ("JB39_1","019_39_1","JOB","39","1","1","“Ka san lokacin da awakin kan dutse suke haihuwa? Ko ka taɓa lura da yadda batsiya take haihuwa? ");
INSERT INTO hausa_vpl VALUES ("JB39_2","019_39_2","JOB","39","2","2","Kana ƙirga watanni nawa suke yi kafin su haihu? Ka san lokacin da suke haihuwa? ");
INSERT INTO hausa_vpl VALUES ("JB39_3","019_39_3","JOB","39","3","3","Suna kwanciya su haifi ’ya’yansu; naƙudarsu ta ƙare bayan sun haihu. ");
INSERT INTO hausa_vpl VALUES ("JB39_4","019_39_4","JOB","39","4","4","’Ya’yansu suna girma kuma suna girma cikin ƙarfi a jeji; sukan tafi ba su dawowa. ");
INSERT INTO hausa_vpl VALUES ("JB39_5","019_39_5","JOB","39","5","5","“Wane ne yake sakin jakin dawa yă bar shi? Wane ne yake kunce igiyoyinsu? ");
INSERT INTO hausa_vpl VALUES ("JB39_6","019_39_6","JOB","39","6","6","Na sa jeji yă zama gidansa ƙasar gishiri kuma ta zama wurin zamansa. ");
INSERT INTO hausa_vpl VALUES ("JB39_7","019_39_7","JOB","39","7","7","Yana dariyar hargitsin da yake faruwa a cikin gari; ba ya jin tsawar mai tuƙa shi. ");
INSERT INTO hausa_vpl VALUES ("JB39_8","019_39_8","JOB","39","8","8","Yana kiwo a kan tuddai don abincinsa yana neman kowane ɗanyen abu mai ruwan ciyawa. ");
INSERT INTO hausa_vpl VALUES ("JB39_9","019_39_9","JOB","39","9","9","“Ko ɓauna zai yarda yă zauna a wurin sa wa dabbobi abinci? Zai tsaya a ɗakin dabbobinka da dare? ");
INSERT INTO hausa_vpl VALUES ("JB39_10","019_39_10","JOB","39","10","10","Ko za ka iya daure shi da igiya a kwarin kunya? Zai yi maka buɗar gonarka? ");
INSERT INTO hausa_vpl VALUES ("JB39_11","019_39_11","JOB","39","11","11","Ko za ka dogara da shi don yawan ƙarfinsa? Za ka bar masa nauyin aikinka? ");
INSERT INTO hausa_vpl VALUES ("JB39_12","019_39_12","JOB","39","12","12","Ko za ka amince da shi yă kawo maka hatsinka gida yă tattara shi a masussuka? ");
INSERT INTO hausa_vpl VALUES ("JB39_13","019_39_13","JOB","39","13","13","“Fikafikan jimina suna bugawa cike da farin ciki amma ba za su gwada kansu da fikafikan da na shamuwa ba. ");
INSERT INTO hausa_vpl VALUES ("JB39_14","019_39_14","JOB","39","14","14","Tana sa ƙwai nata a ƙasa kuma ta bar su su yi ɗumi a cikin ƙasa, ");
INSERT INTO hausa_vpl VALUES ("JB39_15","019_39_15","JOB","39","15","15","ba tă damu ko za a taka su a fasa su, ko waɗansu manyan dabbobi za su tattake su. ");
INSERT INTO hausa_vpl VALUES ("JB39_16","019_39_16","JOB","39","16","16","Tana tsananta wa ’ya’yanta kamar ba nata ba ba tă damu da wahalar da ta sha ba. ");
INSERT INTO hausa_vpl VALUES ("JB39_17","019_39_17","JOB","39","17","17","Gama Allah bai ba ta hikima ba ko kuma iya fahimta. ");
INSERT INTO hausa_vpl VALUES ("JB39_18","019_39_18","JOB","39","18","18","Duk da haka sa’ad da ta buɗe fikafikanta ta shara da gudu tana yi wa doki da mai hawansa dariya. ");
INSERT INTO hausa_vpl VALUES ("JB39_19","019_39_19","JOB","39","19","19","“Ko kai ne kake ba doki ƙarfinsa kai kake rufe wuyansa da geza mai yawa? ");
INSERT INTO hausa_vpl VALUES ("JB39_20","019_39_20","JOB","39","20","20","Ko kai kake sa shi yă yi tsalle kamar fāra, ba ya jin tsoro sai dai a ji tsoronsa. ");
INSERT INTO hausa_vpl VALUES ("JB39_21","019_39_21","JOB","39","21","21","Yana takawa da ƙarfi yana jin daɗin ƙarfinsa yana shiga filin yaƙi gabagadi. ");
INSERT INTO hausa_vpl VALUES ("JB39_22","019_39_22","JOB","39","22","22","Yana yi wa tsoro dariya ba ya jin tsoron kome; ba ya guje wa takobi. ");
INSERT INTO hausa_vpl VALUES ("JB39_23","019_39_23","JOB","39","23","23","Kwari a baka yana lilo a gabansa kibiya da māshi suna wuce kansa. ");
INSERT INTO hausa_vpl VALUES ("JB39_24","019_39_24","JOB","39","24","24","Yana kartar ƙasa da ƙarfi; ba ya iya tsayawa tsab sa’ad da ya ji busar ƙaho. ");
INSERT INTO hausa_vpl VALUES ("JB39_25","019_39_25","JOB","39","25","25","Da jin ƙarar ƙaho sai ya ce, ‘Yauwa!’ Ya ji ƙanshin yaƙi daga nesa, da ihun shugabannin yaƙi. ");
INSERT INTO hausa_vpl VALUES ("JB39_26","019_39_26","JOB","39","26","26","“Ko ta wurin hikimarka ce shirwa take firiya take kuma baza fikafikanta zuwa kudu? ");
INSERT INTO hausa_vpl VALUES ("JB39_27","019_39_27","JOB","39","27","27","Ko da umarninka ne shaho yake firiya ya kuma yi sheƙarsa a can sama? ");
INSERT INTO hausa_vpl VALUES ("JB39_28","019_39_28","JOB","39","28","28","Yana zama a kan dutse yă zauna a wurin da dare; cikin duwatsu ne wurin zamansa. ");
INSERT INTO hausa_vpl VALUES ("JB39_29","019_39_29","JOB","39","29","29","Daga can yake neman abincinsa; idanunsa suna gani daga nesa. ");
INSERT INTO hausa_vpl VALUES ("JB39_30","019_39_30","JOB","39","30","30","’Ya’yansa suna shan jini, inda akwai waɗanda aka kashe nan za a same shi.” ");
INSERT INTO hausa_vpl VALUES ("JB40_1","019_40_1","JOB","40","1","1","Ubangiji ya ce wa Ayuba, ");
INSERT INTO hausa_vpl VALUES ("JB40_2","019_40_2","JOB","40","2","2","“Mai neman sa wa wani laifi zai iya ja da Maɗaukaki? Bari mai tuhumar Allah yă amsa masa.” ");
INSERT INTO hausa_vpl VALUES ("JB40_3","019_40_3","JOB","40","3","3","Sai Ayuba ya amsa wa Ubangiji, ");
INSERT INTO hausa_vpl VALUES ("JB40_4","019_40_4","JOB","40","4","4","“Ai, ni ba a bakin kome nake ba ne, ta yaya zan iya amsa maka? Na rufe bakina da hannuna. ");
INSERT INTO hausa_vpl VALUES ("JB40_5","019_40_5","JOB","40","5","5","Na yi magana sau ɗaya amma ba ni da amsa, sau biyu, amma ba zan ƙara cewa kome ba.” ");
INSERT INTO hausa_vpl VALUES ("JB40_6","019_40_6","JOB","40","6","6","Sa’an nan Ubangiji ya yi wa Ayuba magana ta cikin guguwa, ");
INSERT INTO hausa_vpl VALUES ("JB40_7","019_40_7","JOB","40","7","7","“Ka tashi tsaye ka tsaya da ƙarfi kamar namiji; zan yi maka tambaya kuma za ka amsa mini. ");
INSERT INTO hausa_vpl VALUES ("JB40_8","019_40_8","JOB","40","8","8","“Ko za ka ƙi yarda da shari’ata? Za ka ba ni laifi don ka nuna kai marar laifi ne? ");
INSERT INTO hausa_vpl VALUES ("JB40_9","019_40_9","JOB","40","9","9","Ko hannunka irin na Allah ne, kuma ko muryarka za tă iya tsawa kamar ta Allah? ");
INSERT INTO hausa_vpl VALUES ("JB40_10","019_40_10","JOB","40","10","10","Sai ka yi wa kanka ado da ɗaukaka da girma, ka yafa daraja da muƙami. ");
INSERT INTO hausa_vpl VALUES ("JB40_11","019_40_11","JOB","40","11","11","Ka saki fushinka, ka dubi dukan wani mai girman kai ka wulaƙanta shi. ");
INSERT INTO hausa_vpl VALUES ("JB40_12","019_40_12","JOB","40","12","12","Ka dubi duk wani mai girman kai ka ƙasƙantar da shi, ka tattake mugaye a inda ka tsaya. ");
INSERT INTO hausa_vpl VALUES ("JB40_13","019_40_13","JOB","40","13","13","Ka bizne su duka tare ka rufe fuskokinsu a cikin kabari. ");
INSERT INTO hausa_vpl VALUES ("JB40_14","019_40_14","JOB","40","14","14","Sa’an nan ni kaina zan shaida maka cewa hannun damanka zai iya cetonka. ");
INSERT INTO hausa_vpl VALUES ("JB40_15","019_40_15","JOB","40","15","15","“Dubi dorina, wadda na halicce ku tare kuma ciyawa take ci kamar sa. ");
INSERT INTO hausa_vpl VALUES ("JB40_16","019_40_16","JOB","40","16","16","Ga shi ƙarfinta yana a ƙugunta ikonta yana cikin tsokar cikinta. ");
INSERT INTO hausa_vpl VALUES ("JB40_17","019_40_17","JOB","40","17","17","Wutsiyarta tana da ƙarfi kamar itacen al’ul; jijiyoyin cinyoyinta suna haɗe a wuri ɗaya. ");
INSERT INTO hausa_vpl VALUES ("JB40_18","019_40_18","JOB","40","18","18","Ƙasusuwanta bututun tagulla ne, haƙarƙarinta kamar sandunan ƙarfe. ");
INSERT INTO hausa_vpl VALUES ("JB40_19","019_40_19","JOB","40","19","19","Tana ta farko cikin ayyukan Allah, Mahaliccinta kaɗai yake iya tunkarar ta da takobi. ");
INSERT INTO hausa_vpl VALUES ("JB40_20","019_40_20","JOB","40","20","20","Tuddai su suke tanada mata abinci a inda duk namun jeji suke wasa. ");
INSERT INTO hausa_vpl VALUES ("JB40_21","019_40_21","JOB","40","21","21","Tana kwanciya a ƙarƙashin inuwar itacen lotus ta ɓuya cikin kyauro da fadama. ");
INSERT INTO hausa_vpl VALUES ("JB40_22","019_40_22","JOB","40","22","22","Inuwa ta rufe ta da ƙaddaji, itatuwan wardi na rafi, sun kewaye ta. ");
INSERT INTO hausa_vpl VALUES ("JB40_23","019_40_23","JOB","40","23","23","Sa’ad da kogi ya cika yana hauka, ba tă damu ba; ba abin da zai same ta ko da a gaban bakinta Urdun yake wucewa. ");
INSERT INTO hausa_vpl VALUES ("JB40_24","019_40_24","JOB","40","24","24","Ko akwai wanda zai iya kama ta ba ta kallo, ko kuma a kama ta da tarko a huda hancinta? ");
INSERT INTO hausa_vpl VALUES ("JB41_1","019_41_1","JOB","41","1","1","“Ko za ka iya kama dodon ruwa da ƙugiyar kamar kifi ko kuma ka daure harshenta da igiya? ");
INSERT INTO hausa_vpl VALUES ("JB41_2","019_41_2","JOB","41","2","2","Za ka iya sa igiya a cikin hancinta ko kuma ka huda muƙamuƙanta da ƙugiya? ");
INSERT INTO hausa_vpl VALUES ("JB41_3","019_41_3","JOB","41","3","3","Za tă ci gaba da roƙonka ka yi mata jinƙai? Ko za tă yi maka magana a hankali? ");
INSERT INTO hausa_vpl VALUES ("JB41_4","019_41_4","JOB","41","4","4","Za tă yi yarjejjeniya da kai don ka ɗauke ta tă zama baiwa gare ka dukan kwanakin ranta? ");
INSERT INTO hausa_vpl VALUES ("JB41_5","019_41_5","JOB","41","5","5","Za ka yi wasa da ita kamar yadda za ka yi da tsuntsu? Ko za ka daure ta da tsirkiya domin bayinka mata? ");
INSERT INTO hausa_vpl VALUES ("JB41_6","019_41_6","JOB","41","6","6","’Yan kasuwa za su saye ta ko za su raba ta a tsakaninsu? ");
INSERT INTO hausa_vpl VALUES ("JB41_7","019_41_7","JOB","41","7","7","Ko za ka iya huda fatarta da kibiya ka kuma huda kansa da māsu? ");
INSERT INTO hausa_vpl VALUES ("JB41_8","019_41_8","JOB","41","8","8","In ka ɗora hannunka sau ɗaya a kanta za ka tuna da yaƙin da ba za ka sāke yi ba! ");
INSERT INTO hausa_vpl VALUES ("JB41_9","019_41_9","JOB","41","9","9","Duk ƙoƙarin kama ta banza ne; ganin ta kawai abin tsoro ne. ");
INSERT INTO hausa_vpl VALUES ("JB41_10","019_41_10","JOB","41","10","10","Ba wanda ya isa yă tsokane ta. Wane ne kuma ya isa yă yi tsayayya da ni? ");
INSERT INTO hausa_vpl VALUES ("JB41_11","019_41_11","JOB","41","11","11","Wane ne yake bi na bashi da dole in biya? Duk abin da yake ƙarƙashin sama nawa ne. ");
INSERT INTO hausa_vpl VALUES ("JB41_12","019_41_12","JOB","41","12","12","“Ba zan daina magana game da gaɓoɓinta ba ƙarfinta da kuma kyan kamanninta ba. ");
INSERT INTO hausa_vpl VALUES ("JB41_13","019_41_13","JOB","41","13","13","Wa zai iya tuɓe mata mayafinta? Wa zai iya shiga tsakanin ɓawonta. ");
INSERT INTO hausa_vpl VALUES ("JB41_14","019_41_14","JOB","41","14","14","Wa zai iya buɗe ƙofofin bakinta? Haƙoranta ma abin tsoro ne? ");
INSERT INTO hausa_vpl VALUES ("JB41_15","019_41_15","JOB","41","15","15","An rufe bayanta da jerin garkuwoyi aka manne su sosai. ");
INSERT INTO hausa_vpl VALUES ("JB41_16","019_41_16","JOB","41","16","16","Suna kurkusa da juna yadda da ƙyar iska take iya wucewa tsakani. ");
INSERT INTO hausa_vpl VALUES ("JB41_17","019_41_17","JOB","41","17","17","An haɗa su da juna sun mannu da juna kuma ba za a iya raba su ba. ");
INSERT INTO hausa_vpl VALUES ("JB41_18","019_41_18","JOB","41","18","18","Numfashinta yana fitar da wuta; idanunta kamar hasken zuwan safe. ");
INSERT INTO hausa_vpl VALUES ("JB41_19","019_41_19","JOB","41","19","19","Wuta tana fitowa daga bakinta; tartsatsin wuta suna fitowa, ");
INSERT INTO hausa_vpl VALUES ("JB41_20","019_41_20","JOB","41","20","20","Hayaƙi yana fitowa daga hancinta kamar daga tukunya mai tafasa a kan wutar itace. ");
INSERT INTO hausa_vpl VALUES ("JB41_21","019_41_21","JOB","41","21","21","Numfashinta yana sa garwashi yă kama wuta, harshen wuta yana fita daga bakinta. ");
INSERT INTO hausa_vpl VALUES ("JB41_22","019_41_22","JOB","41","22","22","Akwai ƙarfi a cikin wuyanta; razana tana wucewa a gabanta. ");
INSERT INTO hausa_vpl VALUES ("JB41_23","019_41_23","JOB","41","23","23","Namanta yana da kauri a manne da juna; naman yana da tauri ba ya matsawa. ");
INSERT INTO hausa_vpl VALUES ("JB41_24","019_41_24","JOB","41","24","24","Ƙirjinta yana da ƙarfi kamar dutse, da ƙarfi kamar dutsen niƙa. ");
INSERT INTO hausa_vpl VALUES ("JB41_25","019_41_25","JOB","41","25","25","Sa’ad da ta tashi, manya suna tsorata; suna ja da baya. ");
INSERT INTO hausa_vpl VALUES ("JB41_26","019_41_26","JOB","41","26","26","Takobi ba ta iya yankanta, kibiya ko māshi ba sa iya huda ta. ");
INSERT INTO hausa_vpl VALUES ("JB41_27","019_41_27","JOB","41","27","27","Ƙarfe kamar kara ne a wurinta tagulla kuma kamar ruɓaɓɓen katako ne a wurinta. ");
INSERT INTO hausa_vpl VALUES ("JB41_28","019_41_28","JOB","41","28","28","Māsu ba su sa ta tă gudu; jifar majajjawa kamar na ciyawa ne gare ta. ");
INSERT INTO hausa_vpl VALUES ("JB41_29","019_41_29","JOB","41","29","29","Kulki a gare ta kamar ciyawa ne, tana dariyar wucewar māshi. ");
INSERT INTO hausa_vpl VALUES ("JB41_30","019_41_30","JOB","41","30","30","Cikinta yana rufe a ɓawo masu ƙarfi, tana kabtar ƙasa in tana tafiya. ");
INSERT INTO hausa_vpl VALUES ("JB41_31","019_41_31","JOB","41","31","31","Tana sa zurfin kogi yă tafasa kamar tukunya, ta kuma sa teku yă zama kamar tukunyar man shafawa. ");
INSERT INTO hausa_vpl VALUES ("JB41_32","019_41_32","JOB","41","32","32","A bayanta ya bar haske kamar zurfin ruwan da yana kumfa. ");
INSERT INTO hausa_vpl VALUES ("JB41_33","019_41_33","JOB","41","33","33","Ba wani abu kamar ta a duniya, halitta marar tsoro. ");
INSERT INTO hausa_vpl VALUES ("JB41_34","019_41_34","JOB","41","34","34","Tana rena duk masu girman kai. Ita take mulki kan duk masu girman kai.” ");
INSERT INTO hausa_vpl VALUES ("JB42_1","019_42_1","JOB","42","1","1","Sa’an nan Ayuba ya amsa wa Ubangiji, ");
INSERT INTO hausa_vpl VALUES ("JB42_2","019_42_2","JOB","42","2","2","“Na san cewa za ka iya yin dukan abubuwa; ba wanda zai iya ɓata shirinka. ");
INSERT INTO hausa_vpl VALUES ("JB42_3","019_42_3","JOB","42","3","3","Ka yi tambaya, ‘Wane ne wannan da ya ƙi karɓar shawarata shi marar ilimi?’ Ba shakka na yi magana game da abubuwan da ban gane ba, abubuwan ban al’ajabi da sun fi ƙarfin ganewata. ");
INSERT INTO hausa_vpl VALUES ("JB42_4","019_42_4","JOB","42","4","4","“Ka ce, ‘Saurara yanzu, zan kuma yi magana zan tambaye ka, kuma za ka amsa mini.’ ");
INSERT INTO hausa_vpl VALUES ("JB42_5","019_42_5","JOB","42","5","5","Kunnuwana sun ji game da kai amma yanzu na gan ka. ");
INSERT INTO hausa_vpl VALUES ("JB42_6","019_42_6","JOB","42","6","6","Saboda haka na rena kaina na kuma tuba cikin ƙura da toka.” ");
INSERT INTO hausa_vpl VALUES ("JB42_7","019_42_7","JOB","42","7","7","Bayan Ubangiji ya gaya wa Ayuba waɗannan abubuwa, ya ce wa Elifaz mutumin Teman, “Ina fushi da kai da abokanka guda biyu domin ba ku faɗi abin da yake daidai game da ni ba, kamar yadda bawana Ayuba ya yi. ");
INSERT INTO hausa_vpl VALUES ("JB42_8","019_42_8","JOB","42","8","8","Saboda haka yanzu sai ku ɗauki bijimai guda bakwai, da raguna bakwai, ku je wurin bawana Ayuba ku miƙa hadaya ta ƙonawa domin kanku. Bawana Ayuba zai yi muku addu’a zan kuwa karɓi addu’arsa in bi da ku nisa da wawancinku. Ba ku faɗi abin da yake daidai game da ni ba yadda bawana Ayuba ya yi ba.” ");
INSERT INTO hausa_vpl VALUES ("JB42_9","019_42_9","JOB","42","9","9","Saboda haka Elifaz mutumin Teman, Bildad mutumin Shuwa da Zofar mutumin Na’ama, suka yi abin da Ubangiji ya gaya masu; Ubangiji kuma ya karɓi addu’ar Ayuba. ");
INSERT INTO hausa_vpl VALUES ("JB42_10","019_42_10","JOB","42","10","10","Bayan Ayuba ya yi wa abokansa addu’a, Ubangiji ya sa shi ya sāke zama mai arziki ya ninka abin da yake da shi a dā sau biyu. ");
INSERT INTO hausa_vpl VALUES ("JB42_11","019_42_11","JOB","42","11","11","Dukan ’yan’uwansa maza da mata da duk waɗanda suka san shi a dā suka zo suka ci abinci tare da shi a cikin gidansa. Suka ta’azantar da shi suka ƙarfafa shi game da duk wahalar da Ubangiji ya auka masa, kowannensu kuma ya ba shi azurfa da zobe na zinariya. ");
INSERT INTO hausa_vpl VALUES ("JB42_12","019_42_12","JOB","42","12","12","Ubangiji ya albarkaci ƙarshen Ayuba fiye da farkonsa. Yana da tumaki guda dubu goma sha huɗu, raƙuma guda dubu shida; shanun noma guda dubu da jakuna guda dubu. ");
INSERT INTO hausa_vpl VALUES ("JB42_13","019_42_13","JOB","42","13","13","Ya kuma haifi ’ya’ya maza bakwai, mata uku. ");
INSERT INTO hausa_vpl VALUES ("JB42_14","019_42_14","JOB","42","14","14","’Yar farko ya kira ta Yemima, ta biyun Keziya ta ukun Keren-Haffuk. ");
INSERT INTO hausa_vpl VALUES ("JB42_15","019_42_15","JOB","42","15","15","Duk a cikin ƙasar ba a samu kyawawan mata kamar ’ya’yan Ayuba ba, kuma babansu ya ba su gādo tare ta ’yan’uwansu maza. ");
INSERT INTO hausa_vpl VALUES ("JB42_16","019_42_16","JOB","42","16","16","Bayan wannan Ayuba ya rayu shekara ɗari da arba’in; ya ga ’ya’yansa da ’ya’yansu har tsara ta huɗu. ");
INSERT INTO hausa_vpl VALUES ("JB42_17","019_42_17","JOB","42","17","17","Sa’an nan Ayuba ya rasu da kyakkyawan tsufa.");
INSERT INTO hausa_vpl VALUES ("PS1_1","020_1_1","PSA","1","1","1","Mai farin ciki ne mutumin da ba ya aiki da shawarar mugaye ko yă yi abin da masu zunubi suke yi ko yă zauna tare da masu yin ba’a. ");
INSERT INTO hausa_vpl VALUES ("PS1_2","020_1_2","PSA","1","2","2","Amma yana jin daɗin bin dokar Ubangiji, kuma yana ta nazarinta dare da rana. ");
INSERT INTO hausa_vpl VALUES ("PS1_3","020_1_3","PSA","1","3","3","Yana kama da itacen da aka shuka kusa da maɓulɓulan ruwa, wanda yake ba da amfani a daidai lokaci wanda kuma ganyensa ba sa bushewa. Duk abin da yake yi, yakan yi nasara. ");
INSERT INTO hausa_vpl VALUES ("PS1_4","020_1_4","PSA","1","4","4","Ba haka yake da mugaye ba! Su kamar yayi ne da iska take kwashewa. ");
INSERT INTO hausa_vpl VALUES ("PS1_5","020_1_5","PSA","1","5","5","Saboda haka mugaye ba za su iya tsayawa a shari’a ba, balle a sami masu zunubi a taron adalai. ");
INSERT INTO hausa_vpl VALUES ("PS1_6","020_1_6","PSA","1","6","6","Gama Ubangiji yana lura da yadda adalai suke yin abubuwa, amma ayyukan mugaye za su kai su ga hallaka. ");
INSERT INTO hausa_vpl VALUES ("PS2_1","020_2_1","PSA","2","1","1","Me ya sa ƙasashe suke haɗa baki mutane kuma suke ƙulla shawarwarin banza? ");
INSERT INTO hausa_vpl VALUES ("PS2_2","020_2_2","PSA","2","2","2","Sarakunan duniya sun ɗauki matsayi masu mulki sun taru gaba ɗaya suna gāba da Ubangiji da kuma Shafaffensa. ");
INSERT INTO hausa_vpl VALUES ("PS2_3","020_2_3","PSA","2","3","3","Suna cewa, “Bari mu tsittsinke sarƙoƙinsu, mu kuma ’yantar da kamammu daga kangin bautar Allah.” ");
INSERT INTO hausa_vpl VALUES ("PS2_4","020_2_4","PSA","2","4","4","Mai zama a kursiyi a sama yana dariya; Ubangiji yana musu ba’a. ");
INSERT INTO hausa_vpl VALUES ("PS2_5","020_2_5","PSA","2","5","5","Sa’an nan ya tsawata musu cikin fushinsa ya kuma razanar da su cikin hasalarsa, yana cewa, ");
INSERT INTO hausa_vpl VALUES ("PS2_6","020_2_6","PSA","2","6","6","“Na kafa Sarkina a kan kursiyi a kan Sihiyona, dutsena mai tsarki.” ");
INSERT INTO hausa_vpl VALUES ("PS2_7","020_2_7","PSA","2","7","7","Sarki ya yi shelar umarnin Ubangiji. Ubangiji ya ce mini, “Kai Ɗana ne; yau na zama Mahaifinka. ");
INSERT INTO hausa_vpl VALUES ("PS2_8","020_2_8","PSA","2","8","8","Ka tambaye ni zan kuwa sa al’ummai su zama gādonka, iyakokin duniya su zama mallakarka. ");
INSERT INTO hausa_vpl VALUES ("PS2_9","020_2_9","PSA","2","9","9","Za ka yi mulkinsu da sandan ƙarfe; za ka farfashe su kucu-kucu kamar tukunyar laka.” ");
INSERT INTO hausa_vpl VALUES ("PS2_10","020_2_10","PSA","2","10","10","Saboda haka, ku sarakuna, ku yi wayo; ku shiga hankalinku, ku masu mulkin duniya. ");
INSERT INTO hausa_vpl VALUES ("PS2_11","020_2_11","PSA","2","11","11","Ku bauta wa Ubangiji da tsoro ku kuma yi farin ciki kuna rawar jiki. ");
INSERT INTO hausa_vpl VALUES ("PS2_12","020_2_12","PSA","2","12","12","Ku sumbaci Ɗan, don kada yă yi fushi ku hallaka a abubuwan da kuke yi, gama fushinsa zai iya kuna farat ɗaya. Masu farin ciki ne dukan waɗanda suke neman mafaka daga gare shi. ");
INSERT INTO hausa_vpl VALUES ("PS3_1","020_3_1","PSA","3","1","1","Zabura ta Dawuda. Sa’ad da ya gudu daga ɗansa Absalom. Ya Ubangiji, abokan gābana nawa ne! Su nawa suke gāba da ni! ");
INSERT INTO hausa_vpl VALUES ("PS3_2","020_3_2","PSA","3","2","2","Da yawa suna magana a kaina suna cewa, “Allah ba zai cece shi ba.” Sela ");
INSERT INTO hausa_vpl VALUES ("PS3_3","020_3_3","PSA","3","3","3","Amma kai ne garkuwa kewaye da ni, ya Ubangiji; ka ba ni ɗaukaka ka kuma ɗaga kaina. ");
INSERT INTO hausa_vpl VALUES ("PS3_4","020_3_4","PSA","3","4","4","Ga Ubangiji na yi kuka mai ƙarfi, ya kuwa amsa mini daga tudunsa mai tsarki. Sela ");
INSERT INTO hausa_vpl VALUES ("PS3_5","020_3_5","PSA","3","5","5","Na kwanta na yi barci; na kuma farka, gama Ubangiji yana kiyaye ni. ");
INSERT INTO hausa_vpl VALUES ("PS3_6","020_3_6","PSA","3","6","6","Ba zan ji tsoro ko dubu goma suka ja dāgā gāba da ni a kowane gefe ba. ");
INSERT INTO hausa_vpl VALUES ("PS3_7","020_3_7","PSA","3","7","7","Ka tashi Ya Ubangiji! Ka cece ni, ya Allahna! Ka bugi dukan abokan gābana a muƙamuƙi; ka kakkarya haƙoran mugaye. ");
INSERT INTO hausa_vpl VALUES ("PS3_8","020_3_8","PSA","3","8","8","Daga wurin Ubangiji ne ceto kan zo. Bari albarkanka yă kasance a kan mutanenka. Sela ");
INSERT INTO hausa_vpl VALUES ("PS4_1","020_4_1","PSA","4","1","1","Don mai bi da kaɗe-kaɗe. Da kayan kiɗi masu tsirkiya. Ta Dawuda. Ka amsa mini sa’ad da na kira gare ka, Ya Allahna mai adalci. Ka ba ni sauƙi daga wahalata; ka ji tausayina ka kuma ji addu’ata. ");
INSERT INTO hausa_vpl VALUES ("PS4_2","020_4_2","PSA","4","2","2","Har yaushe, ya ku mutane za ku mai da ɗaukakata abin kunya? Har yaushe za ku ƙaunaci ruɗu ku nemi allolin ƙarya? Sela ");
INSERT INTO hausa_vpl VALUES ("PS4_3","020_4_3","PSA","4","3","3","Ku san cewa Ubangiji ya keɓe masu tsoron Allah wa kansa; Ubangiji zai ji sa’ad da na yi kira gare shi. ");
INSERT INTO hausa_vpl VALUES ("PS4_4","020_4_4","PSA","4","4","4","Cikin fushinku kada ku yi zunubi; sa’ad da kuke kan gadajenku, ku bincike zukatanku ku kuma yi shiru. Sela ");
INSERT INTO hausa_vpl VALUES ("PS4_5","020_4_5","PSA","4","5","5","Ku miƙa hadayun da suka dace ku kuma dogara ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS4_6","020_4_6","PSA","4","6","6","Yawanci suna cewa, “Wa zai yi mana alheri?” Bari hasken fuskarka yă haskaka a kanmu, ya Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS4_7","020_4_7","PSA","4","7","7","Ka cika zuciyata da farin ciki sa’ad da hatsinsu da sabon ruwan inabinsu ya yi yawa. ");
INSERT INTO hausa_vpl VALUES ("PS4_8","020_4_8","PSA","4","8","8","Zan kwanta in kuma yi barci lafiya, gama kai kaɗai, ya Ubangiji, kake sa mazaunina yă kasance lafiya lau. ");
INSERT INTO hausa_vpl VALUES ("PS5_1","020_5_1","PSA","5","1","1","Don mai bi da kaɗe-kaɗe. Don Busa. Ta Dawuda. Ka saurare kalmomina, ya Ubangiji, ka ji ajiyar zuciyata. ");
INSERT INTO hausa_vpl VALUES ("PS5_2","020_5_2","PSA","5","2","2","Ka saurare kukata na neman taimako, Sarkina da Allahna, gama gare ka nake addu’a. ");
INSERT INTO hausa_vpl VALUES ("PS5_3","020_5_3","PSA","5","3","3","Da safe, ya Ubangiji, ka ji muryata; da safe na gabatar da bukatuna a gabanka in kuma jira da sa zuciya. ");
INSERT INTO hausa_vpl VALUES ("PS5_4","020_5_4","PSA","5","4","4","Kai ba Allahn da yake jin daɗin mugu ba ne; gama kana gāba da dukan masu aikata mugunta. ");
INSERT INTO hausa_vpl VALUES ("PS5_5","020_5_5","PSA","5","5","5","Masu fariya ba za su iya tsaya a gabanka ba. Kana ƙin duk masu aikata abin da ba daidai ba. ");
INSERT INTO hausa_vpl VALUES ("PS5_6","020_5_6","PSA","5","6","6","Kakan hallaka masu yin ƙarya. Masu kisankai da mutane masu ruɗu Ubangiji yana ƙyama. ");
INSERT INTO hausa_vpl VALUES ("PS5_7","020_5_7","PSA","5","7","7","Amma ni, ta wurin jinƙanka mai girma, zan shiga gidanka; da bangirma zan durƙusa ga haikalinka. ");
INSERT INTO hausa_vpl VALUES ("PS5_8","020_5_8","PSA","5","8","8","Ka bi da ni, ya Ubangiji, cikin adalcinka saboda abokan gābana, ka fayyace hanyarka a gabana. ");
INSERT INTO hausa_vpl VALUES ("PS5_9","020_5_9","PSA","5","9","9","Babu ko kalma guda daga bakinsu da za a dogara da ita; marmarinsu kawai shi ne su hallakar da waɗansu. Maƙogwaronsu buɗaɗɗen kabari ne; da harshensu suna faɗin ƙarya. ");
INSERT INTO hausa_vpl VALUES ("PS5_10","020_5_10","PSA","5","10","10","Ka furta su masu laifi, ya Allah! Bari makircinsu yă zama fāɗuwarsu. Ka kore su saboda yawan zunubansu, saboda sun tayar maka. ");
INSERT INTO hausa_vpl VALUES ("PS5_11","020_5_11","PSA","5","11","11","Amma bari dukan waɗanda suke neman mafaka gare ka su yi murna; bari kullum su yi ta rerawa saboda farin ciki. Ka buɗe kāriyarka a bisansu, domin waɗanda suke ƙaunar sunanka su yi farin ciki a cikinka. ");
INSERT INTO hausa_vpl VALUES ("PS5_12","020_5_12","PSA","5","12","12","Gama tabbatacce, ya Ubangiji, kakan albarkaci adalai; kakan kewaye su da tagomashinka kamar garkuwa. ");
INSERT INTO hausa_vpl VALUES ("PS6_1","020_6_1","PSA","6","1","1","Don mai bi da kaɗe-kaɗe. Da kayan kiɗi masu tsirkiya. Bisa ga sheminit. Ta Dawuda. Ya Ubangiji, kada ka tsawata mini cikin fushinka ko ka hore ni cikin hasalarka. ");
INSERT INTO hausa_vpl VALUES ("PS6_2","020_6_2","PSA","6","2","2","Ka yi mini jinƙai, Ubangiji, gama na suma; Ya Ubangiji, ka warkar da ni, gama ƙasusuwana suna zafin ciwo. ");
INSERT INTO hausa_vpl VALUES ("PS6_3","020_6_3","PSA","6","3","3","Raina yana cikin wahala. Har yaushe, ya Ubangiji, har yaushe? ");
INSERT INTO hausa_vpl VALUES ("PS6_4","020_6_4","PSA","6","4","4","Ka juyo, ya Ubangiji, ka cece ni; ka cece ni saboda madawwamiyar ƙaunarka. ");
INSERT INTO hausa_vpl VALUES ("PS6_5","020_6_5","PSA","6","5","5","Babu wanda yakan tuna da kai sa’ad da ya mutu. Wa ke yabonka daga kabari? ");
INSERT INTO hausa_vpl VALUES ("PS6_6","020_6_6","PSA","6","6","6","Na gaji tiƙis daga nishi. Dukan dare na jiƙe gadona da kuka na jiƙe kujerata da hawaye. ");
INSERT INTO hausa_vpl VALUES ("PS6_7","020_6_7","PSA","6","7","7","Idanuna sun rasa ƙarfi da baƙin ciki; sun rasa ƙarfi saboda dukan abokan gābana. ");
INSERT INTO hausa_vpl VALUES ("PS6_8","020_6_8","PSA","6","8","8","Ku tafi daga gare ni, dukanku masu aikata mugunta, gama Ubangiji ya ji kukata. ");
INSERT INTO hausa_vpl VALUES ("PS6_9","020_6_9","PSA","6","9","9","Ubangiji ya ji kukata saboda jinƙansa; Ubangiji ya karɓi addu’ata. ");
INSERT INTO hausa_vpl VALUES ("PS6_10","020_6_10","PSA","6","10","10","Dukan abokan gābana za su sha kunya su kuma karaya; za su juya da kunya nan da nan. ");
INSERT INTO hausa_vpl VALUES ("PS7_1","020_7_1","PSA","7","1","1","Wani shiggayiyon ta Dawuda, wanda Ya Rera wa Ubangiji game da Kush mutumin Benyamin. Ya Ubangiji Allahna, na zo neman mafaka a wurinka; ka cece ni ka kuɓutar da ni daga dukan waɗanda suke bi na, ");
INSERT INTO hausa_vpl VALUES ("PS7_2","020_7_2","PSA","7","2","2","in ba haka ba za su yayyage ni kamar zaki su ɓarke ni kucu-kucu ba tare da wani da zai cece ni ba. ");
INSERT INTO hausa_vpl VALUES ("PS7_3","020_7_3","PSA","7","3","3","Ya Ubangiji Allahna, in na yi kuskure aka kuwa sami laifi a hannuwana, ");
INSERT INTO hausa_vpl VALUES ("PS7_4","020_7_4","PSA","7","4","4","in na yi mugunta ga wanda yake zaman lafiya da ni ko kuwa ba da wani dalilin cuci abokin gābana, ");
INSERT INTO hausa_vpl VALUES ("PS7_5","020_7_5","PSA","7","5","5","to, bari abokin gābana yă bi yă kuma cim mini; bari yă tattake raina a ƙasa ya sa in kwana a ƙura. Sela ");
INSERT INTO hausa_vpl VALUES ("PS7_6","020_7_6","PSA","7","6","6","Ka tashi, ya Ubangiji, cikin fushinka; ka tashi gāba da fushin abokan gābana. Ka farka, Allahna, ka umarta adalci. ");
INSERT INTO hausa_vpl VALUES ("PS7_7","020_7_7","PSA","7","7","7","Bari taron mutane su taru kewaye da kai. Ka yi mulki a bisansu daga bisa; ");
INSERT INTO hausa_vpl VALUES ("PS7_8","020_7_8","PSA","7","8","8","bari Ubangiji mai shari’ar mutane. Ka shari’anta ni Ya Ubangiji, bisa ga adalcina, bisa ga mutuncina, ya Mafi Ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("PS7_9","020_7_9","PSA","7","9","9","Ya Allah mai adalci, wanda yake binciken tunani da zukata, ka kawo ƙarshen rikicin mugaye ka kuma sa adalai su zauna lafiya. ");
INSERT INTO hausa_vpl VALUES ("PS7_10","020_7_10","PSA","7","10","10","Garkuwata shi ne Allah Mafi Ɗaukaka, wanda yake ceton masu tsabtar zuciya. ");
INSERT INTO hausa_vpl VALUES ("PS7_11","020_7_11","PSA","7","11","11","Allah alƙali ne mai adalci, Allahn da yakan bayyana fushinsa kowace rana. ");
INSERT INTO hausa_vpl VALUES ("PS7_12","020_7_12","PSA","7","12","12","In mutum bai tuba ba, Allah zai wasa takobinsa; zai tanƙware yă kuma ɗaura bakansa. ");
INSERT INTO hausa_vpl VALUES ("PS7_13","020_7_13","PSA","7","13","13","Ya shirya makamansa masu dafi; ya shirya kibiyoyinsa masu wuta. ");
INSERT INTO hausa_vpl VALUES ("PS7_14","020_7_14","PSA","7","14","14","Wanda yake da cikin mugunta ya kuma ɗauki cikin damuwa yakan haifi ƙarya. ");
INSERT INTO hausa_vpl VALUES ("PS7_15","020_7_15","PSA","7","15","15","Wanda ya haƙa rami yakan fāɗa cikin ramin da ya haƙa. ");
INSERT INTO hausa_vpl VALUES ("PS7_16","020_7_16","PSA","7","16","16","Damuwar da ya ja yakan sāke nannaɗe a kansa; fitinarsa takan sauka a kansa. ");
INSERT INTO hausa_vpl VALUES ("PS7_17","020_7_17","PSA","7","17","17","Zan gode wa Ubangiji saboda adalcinsa zan kuma rera yabo ga sunan Ubangiji Mafi Ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("PS8_1","020_8_1","PSA","8","1","1","Don mai bi da kaɗe-kaɗe. Bisa ga gittit. Zabura ta Dawuda. Ya Ubangiji, shugabanmu, sunanka da girma take a cikin dukan duniya! Ka kafa ɗaukakarka bisa sammai. ");
INSERT INTO hausa_vpl VALUES ("PS8_2","020_8_2","PSA","8","2","2","Daga leɓunan yara da jarirai ka kafa yabo domin su sa abokan gābanka da masu ɗaukan fansa su yi shiru. ");
INSERT INTO hausa_vpl VALUES ("PS8_3","020_8_3","PSA","8","3","3","Sa’ad da na dubi sammai, aikin yatsotsinka, wata da taurari waɗanda ka ajiye a wurarensu, ");
INSERT INTO hausa_vpl VALUES ("PS8_4","020_8_4","PSA","8","4","4","wane ne mutum da kake tunawa da shi, ɗan mutum da kake lura da shi? ");
INSERT INTO hausa_vpl VALUES ("PS8_5","020_8_5","PSA","8","5","5","Ka yi shi ƙasa kaɗan da Allah ka yi masa rawani da ɗaukaka da girma. ");
INSERT INTO hausa_vpl VALUES ("PS8_6","020_8_6","PSA","8","6","6","Ka mai da shi mai mulki bisa ayyukan hannuwanka; ka sa kome a ƙarƙashin ƙafafunsa, ");
INSERT INTO hausa_vpl VALUES ("PS8_7","020_8_7","PSA","8","7","7","dukan shanu da tumaki, da kuma namun jeji, ");
INSERT INTO hausa_vpl VALUES ("PS8_8","020_8_8","PSA","8","8","8","tsuntsayen sararin sama da kifin teku, da dukan abin da yake yawo a ƙarƙashin ruwan teku. ");
INSERT INTO hausa_vpl VALUES ("PS8_9","020_8_9","PSA","8","9","9","Ya Ubangiji, shugabanmu, sunanka da girma take a cikin dukan duniya! ");
INSERT INTO hausa_vpl VALUES ("PS9_1","020_9_1","PSA","9","1","1","Don mai bi da kaɗe-kaɗe. Ga muryar “Mutuwar Ɗa.” Zabura ta Dawuda. Zan yabe ka, ya Ubangiji, da dukan zuciyata; zan faɗa dukan abubuwan banmamakinka. ");
INSERT INTO hausa_vpl VALUES ("PS9_2","020_9_2","PSA","9","2","2","Zan yi murna in kuma yi farin ciki a cikinka; zan rera yabo ga sunanka, ya Mafi Ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("PS9_3","020_9_3","PSA","9","3","3","Abokan gābana sun ja da baya; suka yi tuntuɓe suka hallaka a gabanka. ");
INSERT INTO hausa_vpl VALUES ("PS9_4","020_9_4","PSA","9","4","4","Gama ka tabbata da gaskiyata da kuma abin da nake yi; ka zauna a kujerarka, kana yin shari’a da adalci. ");
INSERT INTO hausa_vpl VALUES ("PS9_5","020_9_5","PSA","9","5","5","Ka tsawata wa ƙasashe ka kuma hallakar da mugaye; ka shafe sunansu har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("PS9_6","020_9_6","PSA","9","6","6","Lalaci marar ƙarewa ya cimma abokan gābanmu, ka tuttumɓuke biranensu; yadda ma ba aka ƙara tunaninsu. ");
INSERT INTO hausa_vpl VALUES ("PS9_7","020_9_7","PSA","9","7","7","Ubangiji yana mulki har abada; ya kafa kujerarsa don shari’a. ");
INSERT INTO hausa_vpl VALUES ("PS9_8","020_9_8","PSA","9","8","8","Zai hukunta duniya da adalci; zai yi mulkin mutane cikin gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PS9_9","020_9_9","PSA","9","9","9","Ubangiji shi ne mafakan waɗanda ake danniya, mafaka a lokutan wahala. ");
INSERT INTO hausa_vpl VALUES ("PS9_10","020_9_10","PSA","9","10","10","Waɗanda suka san sunanka za su dogara da kai, gama kai, Ubangiji, ba ka taɓa yashe waɗanda suke nemanka ba. ");
INSERT INTO hausa_vpl VALUES ("PS9_11","020_9_11","PSA","9","11","11","Rera yabai ga Ubangiji, wanda yake zaune a kursiyi a Sihiyona; yi shela a cikin al’ummai abin da ya aikata. ");
INSERT INTO hausa_vpl VALUES ("PS9_12","020_9_12","PSA","9","12","12","Gama shi da yakan ɗauki fansa a kan mai kisa yakan tuna; ba ya ƙyale kukan masu wahala. ");
INSERT INTO hausa_vpl VALUES ("PS9_13","020_9_13","PSA","9","13","13","Ya Ubangiji, dubi yadda abokan gābana suna tsananta mini! Ka yi jinƙai ka kuma ɗaga ni daga ƙofofin mutuwa, ");
INSERT INTO hausa_vpl VALUES ("PS9_14","020_9_14","PSA","9","14","14","don in furta yabanka cikin ƙofofin ’Yar Sihiyona a can kuwa in yi farin ciki cikin cetonka. ");
INSERT INTO hausa_vpl VALUES ("PS9_15","020_9_15","PSA","9","15","15","Al’umma sun fāɗa cikin ramin da suka haƙa wa waɗansu; aka kama ƙafafunsu a ragar da suka ɓoye. ");
INSERT INTO hausa_vpl VALUES ("PS9_16","020_9_16","PSA","9","16","16","An san Ubangiji ta wurin gaskiyarsa; an kama mugaye da aikin hannuwansu. Haggayiyon. Sela ");
INSERT INTO hausa_vpl VALUES ("PS9_17","020_9_17","PSA","9","17","17","Mugaye za su koma kabari, dukan al’umman da suka manta da Allah. ");
INSERT INTO hausa_vpl VALUES ("PS9_18","020_9_18","PSA","9","18","18","Amma har abada ba za a manta da mai bukata ba, ba kuwa sa zuciyar mai wahala zai taɓa hallaka. ");
INSERT INTO hausa_vpl VALUES ("PS9_19","020_9_19","PSA","9","19","19","Ka tashi, ya Ubangiji, kada ka bar wani yă yi nasara; bari a hukunta al’ummai a gabanka. ");
INSERT INTO hausa_vpl VALUES ("PS9_20","020_9_20","PSA","9","20","20","Ka buge su da rawar jiki, ya Ubangiji; bari al’ummai su sani su mutane ne kurum. Sela ");
INSERT INTO hausa_vpl VALUES ("PS10_1","020_10_1","PSA","10","1","1","Don me, ya Ubangiji, kake tsaya can da nesa? Me ya sa kake ɓoye kanka a lokutan wahala? ");
INSERT INTO hausa_vpl VALUES ("PS10_2","020_10_2","PSA","10","2","2","Cikin fariyarsa mugun mutum yakan cuci marasa ƙarfi, waɗanda yake kama cikin makircin da ya shirya. ");
INSERT INTO hausa_vpl VALUES ("PS10_3","020_10_3","PSA","10","3","3","Yakan yi taƙama da ƙulle-ƙullen zuciyarsa; yana albarkaci mai haɗama yana kuma ƙin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS10_4","020_10_4","PSA","10","4","4","Cikin ɗaga kai mutum ba ya neman Allah; cikin tunaninsa ba ya ba da wata dama saboda Allah. ");
INSERT INTO hausa_vpl VALUES ("PS10_5","020_10_5","PSA","10","5","5","Hanyoyinsa kullum sukan yi nasara; yana da girman kai kuma dokokinka suna nesa da shi; yakan yi wa dukan abokan gābansa duban reni. ");
INSERT INTO hausa_vpl VALUES ("PS10_6","020_10_6","PSA","10","6","6","Yakan ce wa kansa, “Ba abin da zai girgiza ni; kullum zan yi murna ba zan taɓa shiga wahala ba.” ");
INSERT INTO hausa_vpl VALUES ("PS10_7","020_10_7","PSA","10","7","7","Bakinsa ya cika da zage-zage da ƙarairayi da kuma barazana; wahala da mugunta suna a ƙarƙashin harshensa. ");
INSERT INTO hausa_vpl VALUES ("PS10_8","020_10_8","PSA","10","8","8","Yakan yi kwanto kusa da ƙauyuka; daga kwanton yakan kashe marar laifi. Yana kallon waɗanda za su shiga hannunsa a ɓoye. ");
INSERT INTO hausa_vpl VALUES ("PS10_9","020_10_9","PSA","10","9","9","Yakan yi kwanto a ɓoye kamar zaki. Yakan yi kwanto don yă kama marasa ƙarfi; yakan kama marasa ƙarfi yă ja su cikin ragarsa. ");
INSERT INTO hausa_vpl VALUES ("PS10_10","020_10_10","PSA","10","10","10","Yakan ragargaza waɗanda suka shiga hannu, su fāɗi; sukan fāɗi a ƙarƙashin ƙarfinsa. ");
INSERT INTO hausa_vpl VALUES ("PS10_11","020_10_11","PSA","10","11","11","Yakan ce wa kansa, “Ai, Allah ya manta; ya rufe fuskarsa ba ya gani.” ");
INSERT INTO hausa_vpl VALUES ("PS10_12","020_10_12","PSA","10","12","12","Ka tashi, Ubangiji! Ka hukunta miyagu, ya Allah. Kada ka manta da marasa ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("PS10_13","020_10_13","PSA","10","13","13","Don me mugun mutum zai ƙi Allah? Don me yakan ce wa kansa, “Allah ba zai nemi hakki daga gare ni ba”? ");
INSERT INTO hausa_vpl VALUES ("PS10_14","020_10_14","PSA","10","14","14","Amma kai, ya Allah, kana gani wahala da baƙin ciki; kana lura da yadda suke ɗaukansu a hannu. Marar taimako kan danƙa kansa gare ka; kai ne mai taimakon marayu ");
INSERT INTO hausa_vpl VALUES ("PS10_15","020_10_15","PSA","10","15","15","Ka karye hannun mugaye da kuma mugun mutum; ka nemi hakki daga gare shi saboda muguntar da ba za a gane ba. ");
INSERT INTO hausa_vpl VALUES ("PS10_16","020_10_16","PSA","10","16","16","Ubangiji Sarkin har abada abadin ne; al’ummai za su hallaka daga ƙasarsa. ");
INSERT INTO hausa_vpl VALUES ("PS10_17","020_10_17","PSA","10","17","17","Kakan ji, ya Ubangiji sha’awar mai shan wahala; kakan ƙarfafa su, ka kuma saurari kukansu, ");
INSERT INTO hausa_vpl VALUES ("PS10_18","020_10_18","PSA","10","18","18","kana kāre marayu da waɗanda aka danne, domin mutum, wanda yake na duniya kada ƙara haddasa wata razana. ");
INSERT INTO hausa_vpl VALUES ("PS11_1","020_11_1","PSA","11","1","1","Don mai bi da kaɗe-kaɗe. Don busa. Ta Dawuda. A wurin Ubangiji ne nake samun mafaka. Yaya za ku ce mini, “Ka yi firiya kamar tsuntsu zuwa duwatsu. ");
INSERT INTO hausa_vpl VALUES ("PS11_2","020_11_2","PSA","11","2","2","Gama duba, mugaye sun tanƙware bakkunansu; sun kuma ɗana kibiyoyinsu don su harbi mutanen kirki a zuciya daga cikin duhu. ");
INSERT INTO hausa_vpl VALUES ("PS11_3","020_11_3","PSA","11","3","3","Sa’ad da aka tumɓuke tushe, me adali zai iya yi?” ");
INSERT INTO hausa_vpl VALUES ("PS11_4","020_11_4","PSA","11","4","4","Ubangiji yana cikin haikalinsa mai tsarki; Ubangiji yana a kursiyinsa a sama. Yana kallon ’ya’yan mutane; idanunsa suna bincike su. ");
INSERT INTO hausa_vpl VALUES ("PS11_5","020_11_5","PSA","11","5","5","Ubangiji yana bincike adalai, amma ransa yana ƙi mugaye da masu son rikici. ");
INSERT INTO hausa_vpl VALUES ("PS11_6","020_11_6","PSA","11","6","6","A kan mugaye zai zuba garwashin wuta mai zafi da kuma kibiritu; iska mai zafi zai zama rabonsu. ");
INSERT INTO hausa_vpl VALUES ("PS11_7","020_11_7","PSA","11","7","7","Gama Ubangiji mai adalci ne, yana ƙaunar gaskiya masu adalci za su ga fuskarsa. ");
INSERT INTO hausa_vpl VALUES ("PS12_1","020_12_1","PSA","12","1","1","Don mai bi da kaɗe-kaɗe. Da kayan kiɗi. Bisa ga sheminit. Zabura ta Dawuda. Ka taimaka, Ubangiji, gama masu tsoron Allah ba sa nan kuma; masu aminci sun ɓace daga cikin mutane. ");
INSERT INTO hausa_vpl VALUES ("PS12_2","020_12_2","PSA","12","2","2","Kowa yana yi wa maƙwabcinsa ƙarya; zaƙin bakinsu maganar ƙarya ce suna cike da ruɗu a zukatansu. ");
INSERT INTO hausa_vpl VALUES ("PS12_3","020_12_3","PSA","12","3","3","Bari Ubangiji yă yanke dukan zaƙin bakinsu da kuma kowane harshe mai fariya, ");
INSERT INTO hausa_vpl VALUES ("PS12_4","020_12_4","PSA","12","4","4","masu cewa, “Da harsunanmu za mu yi nasara; leɓunanmu za su kāre mu, wane ne maigidanmu?” ");
INSERT INTO hausa_vpl VALUES ("PS12_5","020_12_5","PSA","12","5","5","“Saboda danniyar marasa ƙarfi da kuma nishin masu bukata, zan tashi yanzu,” in ji Ubangiji. “Zan kāre su daga masu yin musu sharri.” ");
INSERT INTO hausa_vpl VALUES ("PS12_6","020_12_6","PSA","12","6","6","Kalmomin Ubangiji kuwa ba su da kuskure, kamar azurfan da aka tace cikin matoyan yumɓu, aka tsabtacce sau bakwai. ");
INSERT INTO hausa_vpl VALUES ("PS12_7","020_12_7","PSA","12","7","7","Ya Ubangiji, za ka kiyaye mu lafiya ka tsare mu daga irin mutanen nan har abada. ");
INSERT INTO hausa_vpl VALUES ("PS12_8","020_12_8","PSA","12","8","8","Mugaye suna yawo a sake sa’ad da ake girmama abin da ba shi da kyau a cikin mutane. ");
INSERT INTO hausa_vpl VALUES ("PS13_1","020_13_1","PSA","13","1","1","Don mai bi da kaɗe-kaɗe. Zabura ta Dawuda. Har yaushe, ya Ubangiji? Za ka manta da ni har abada ne? Har yaushe za ka ɓoye fuskarka daga gare ni? ");
INSERT INTO hausa_vpl VALUES ("PS13_2","020_13_2","PSA","13","2","2","Har yaushe zan yi kokawa da tunanina kuma kowace rana in kasance da damuwa a zuciyata? Har yaushe abokin gābana zai yi nasara a kaina? ");
INSERT INTO hausa_vpl VALUES ("PS13_3","020_13_3","PSA","13","3","3","Ka dube ni ka amsa mini, ya Ubangiji Allahna. Ka ba da haske ga fuskata, ko in yi barci cikin mutuwa; ");
INSERT INTO hausa_vpl VALUES ("PS13_4","020_13_4","PSA","13","4","4","abokin gābana zai ce, “Na sha ƙarfinsa,” kuma abokan gābana za su yi murna sa’ad da na fāɗi. ");
INSERT INTO hausa_vpl VALUES ("PS13_5","020_13_5","PSA","13","5","5","Amma na dogara a kan ƙaunarka marar ƙarewa; zuciyata tana farin ciki a cikin cetonka. ");
INSERT INTO hausa_vpl VALUES ("PS13_6","020_13_6","PSA","13","6","6","Zan rera ga Ubangiji gama ya yi mini alheri. ");
INSERT INTO hausa_vpl VALUES ("PS14_1","020_14_1","PSA","14","1","1","Don mai bi da kaɗe-kaɗe. Ta Dawuda. Wawaye sukan ce a ransu, “Ba Allah.” Sun lalace, ayyukansu kuwa mugaye ne; babu wani da yake yi abu mai kyau. ");
INSERT INTO hausa_vpl VALUES ("PS14_2","020_14_2","PSA","14","2","2","Ubangiji ya duba daga sama a kan ’yan adam don yă ga ko akwai wani da ya gane, wani wanda yake neman Allah. ");
INSERT INTO hausa_vpl VALUES ("PS14_3","020_14_3","PSA","14","3","3","Duka sun kauce, duka gaba ɗaya sun zama lalatattu; babu ɗaya wanda yake yin abu mai kyau, ba ko ɗaya. ");
INSERT INTO hausa_vpl VALUES ("PS14_4","020_14_4","PSA","14","4","4","Masu aikata mugunta za su taɓa koyo. Suna cin mutane yadda mutane ke cin gurasa kuma waɗanda ba sa kira bisa Ubangiji? ");
INSERT INTO hausa_vpl VALUES ("PS14_5","020_14_5","PSA","14","5","5","Ga su, tsoro ya sha kansu, gama Allah yana cikin ƙungiyar adalai. ");
INSERT INTO hausa_vpl VALUES ("PS14_6","020_14_6","PSA","14","6","6","Ku masu mugunta kuna sa ƙoƙarin matalauta yă zama banza, amma Ubangiji ne mafakansu. ");
INSERT INTO hausa_vpl VALUES ("PS14_7","020_14_7","PSA","14","7","7","Kash, da ceton Isra’ila zai fito daga Sihiyona mana! Sa’ad da Ubangiji zai maido da sa’ar mutanensa, bari Yaƙub yă yi farin ciki Isra’ila kuma yă yi murna! ");
INSERT INTO hausa_vpl VALUES ("PS15_1","020_15_1","PSA","15","1","1","Zabura ta Dawuda. Ubangiji, wa zai zauna cikin wuri mai tsarkinka? Wa zai zauna a kan tudunka mai tsarki? ");
INSERT INTO hausa_vpl VALUES ("PS15_2","020_15_2","PSA","15","2","2","Sai wanda ba shi da laifi kuma yana yin abin da yake daidai, wanda yake faɗin gaskiya daga zuciyarsa ");
INSERT INTO hausa_vpl VALUES ("PS15_3","020_15_3","PSA","15","3","3","ba ya kuwa ɓata sunan wani da harshensa, wanda ba ya yi wa maƙwabcinsa mugunta ba ya kuwa baza jita-jita a kan ɗan’uwansa, ");
INSERT INTO hausa_vpl VALUES ("PS15_4","020_15_4","PSA","15","4","4","wanda yake ƙin mugun mutum amma yakan girmama masu tsoron Ubangiji, yakan cika alkawarinsa ko da ma ya zafe shi, ");
INSERT INTO hausa_vpl VALUES ("PS15_5","020_15_5","PSA","15","5","5","wanda yake ba da rance ba tare da ruwa ba kuma ba ya karɓan cin hanci don yă kā da marar laifi. Shi wanda yake yin waɗannan abubuwa ba zai taɓa jijjiguwa ba. ");
INSERT INTO hausa_vpl VALUES ("PS16_1","020_16_1","PSA","16","1","1","Miktam ne na Dawuda. Ka kiyaye ni, ya Allah, gama a cikinka nake samun mafaka. ");
INSERT INTO hausa_vpl VALUES ("PS16_2","020_16_2","PSA","16","2","2","Na ce wa Ubangiji, “Kai ne shugabana; in ba tare da kai ba, ba ni da wani abu mai kyau.” ");
INSERT INTO hausa_vpl VALUES ("PS16_3","020_16_3","PSA","16","3","3","Game da tsarkakan da suke cikin ƙasar kuwa, su ne masu ɗaukakar da dukan farin cikina ya dangana. ");
INSERT INTO hausa_vpl VALUES ("PS16_4","020_16_4","PSA","16","4","4","Baƙin ciki zai ƙaru wa waɗanda suke bin waɗansu alloli. Ba zan zuba musu hadayarsu ta jini ba ko in ambaci sunayensu da bakina. ");
INSERT INTO hausa_vpl VALUES ("PS16_5","020_16_5","PSA","16","5","5","Ubangiji, ka ba ni rabona da kwaf ɗin na; ka kiyaye rabona, ");
INSERT INTO hausa_vpl VALUES ("PS16_6","020_16_6","PSA","16","6","6","Iyakoki sun fāɗo mini a wurare masu daɗi; tabbatacce ina da gādo mai bansha’awa. ");
INSERT INTO hausa_vpl VALUES ("PS16_7","020_16_7","PSA","16","7","7","Zan yabi Ubangiji, wanda yake ba ni shawara; ko da dare ma zuciyata kan koya mini. ");
INSERT INTO hausa_vpl VALUES ("PS16_8","020_16_8","PSA","16","8","8","Kullum nakan sa Ubangiji a gabana. Gama yana a hannun damana, ba zan jijjigu ba. ");
INSERT INTO hausa_vpl VALUES ("PS16_9","020_16_9","PSA","16","9","9","Saboda haka zuciyata tana murna harshena kuma yana farin ciki; jikina kuma zai zauna lafiya, ");
INSERT INTO hausa_vpl VALUES ("PS16_10","020_16_10","PSA","16","10","10","domin ba za ka yashe ni a kabari ba, ba kuwa za ka bar Mai Tsarkinka yă ruɓa ba. ");
INSERT INTO hausa_vpl VALUES ("PS16_11","020_16_11","PSA","16","11","11","Ka sanar da ni hanyar rai; za ka cika ni da farin ciki a gabanka, da madawwamin jin daɗi a hannun damarka. ");
INSERT INTO hausa_vpl VALUES ("PS17_1","020_17_1","PSA","17","1","1","Addu’a ce ta Dawuda. Ka ji, ya Ubangiji, roƙona na adalci; ka saurari kukata. Ka kasa kunne ga addu’ata, ba ta fitowa daga leɓuna masu ƙarya. ");
INSERT INTO hausa_vpl VALUES ("PS17_2","020_17_2","PSA","17","2","2","Bari fiffitawata tă zo daga gare ka; bari idanunka su ga abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("PS17_3","020_17_3","PSA","17","3","3","Ko ka duba zuciyata, ka kuma bincike ni da dare, ko ka gwada ni, ba za ka sami kome ba; na yanke shawara cewa bakina ba zai yi zunubi ba. ");
INSERT INTO hausa_vpl VALUES ("PS17_4","020_17_4","PSA","17","4","4","Game da ayyukan mutane kuwa, ta wurin maganar leɓunanka na kiyaye kaina daga hanyoyin tashin hankali. ");
INSERT INTO hausa_vpl VALUES ("PS17_5","020_17_5","PSA","17","5","5","Sawuna sun kama hanyoyinka ƙafafu kuwa ba za su yi santsi ba. ");
INSERT INTO hausa_vpl VALUES ("PS17_6","020_17_6","PSA","17","6","6","Na kira gare ka, ya Allah, gama za ka amsa mini; ka kasa kunne ka kuma ji addu’ata. ");
INSERT INTO hausa_vpl VALUES ("PS17_7","020_17_7","PSA","17","7","7","Ka nuna mini girmar ƙaunarka mai banmamaki, kai da kake ceton waɗanda suke neman mafaka daga abokan gābansu da hannunka na dama. ");
INSERT INTO hausa_vpl VALUES ("PS17_8","020_17_8","PSA","17","8","8","Ka kiyaye ni yadda ake kiyaye ido; ka ɓoye ni cikin inuwar fikafikanka ");
INSERT INTO hausa_vpl VALUES ("PS17_9","020_17_9","PSA","17","9","9","daga mugaye waɗanda suke kai mini hari, daga abokan gāba masu mutuwa waɗanda suka kewaye ni. ");
INSERT INTO hausa_vpl VALUES ("PS17_10","020_17_10","PSA","17","10","10","Sun rufe zukatansu marar tausayi, da bakunansu suna magana da fariya. ");
INSERT INTO hausa_vpl VALUES ("PS17_11","020_17_11","PSA","17","11","11","Sun sa mini ido, yanzu sun kewaye ni, a shirye suke, su jefa ni a ƙasa. ");
INSERT INTO hausa_vpl VALUES ("PS17_12","020_17_12","PSA","17","12","12","Suna kama da zaki mai yunwan abinci, kamar babban zaki mai fako a maɓuya. ");
INSERT INTO hausa_vpl VALUES ("PS17_13","020_17_13","PSA","17","13","13","Ka tashi, ya Ubangiji, ka yi arangama da su, ka durƙusar da su; ka cece ni daga mugaye ta wurin takobinka. ");
INSERT INTO hausa_vpl VALUES ("PS17_14","020_17_14","PSA","17","14","14","Ya Ubangiji, da hannunka ka cece ni daga irin mutanen nan, daga mutanen duniyan nan waɗanda ladarsu yana a wannan rayuwa ne. Kakan cika yunwan waɗanda kake so; ’ya’yansu suna da isashe suna kuma ajiyar wadata wa ’ya’yansu. ");
INSERT INTO hausa_vpl VALUES ("PS17_15","020_17_15","PSA","17","15","15","Amma ni, cikin adalci zan ga fuskarka; sa’ad da na farka, zan gamsu da ganin kamanninka. ");
INSERT INTO hausa_vpl VALUES ("PS18_1","020_18_1","PSA","18","1","1","Don mai bi da kaɗe-kaɗe. Ta Dawuda bawan Ubangiji. Ya rera ta ga Ubangiji kalmomin wannan waƙa sa’ad da Ubangiji ya cece shi daga hannun dukan abokan gābansa da kuma daga hannun Shawulu, ya ce, Ina ƙaunarka, ya Ubangiji, ƙarfina. ");
INSERT INTO hausa_vpl VALUES ("PS18_2","020_18_2","PSA","18","2","2","Ubangiji shi ne dutsena, kagarata da kuma mai cetona; Allahna shi ne dutsena, a gare shi nake neman mafaka. Shi ne garkuwata da ƙahon cetona, mafakata. ");
INSERT INTO hausa_vpl VALUES ("PS18_3","020_18_3","PSA","18","3","3","Na kira ga Ubangiji, wanda ya cancanci yabo, na kuwa kuɓuta daga abokan gābana. ");
INSERT INTO hausa_vpl VALUES ("PS18_4","020_18_4","PSA","18","4","4","Igiyoyin mutuwa sun shaƙe ni; rigyawan hallaka sun sha kaina. ");
INSERT INTO hausa_vpl VALUES ("PS18_5","020_18_5","PSA","18","5","5","Igiyoyin mutuwa sun nannaɗe kewaye da ni; tarkon mutuwa ya yi mini arangama. ");
INSERT INTO hausa_vpl VALUES ("PS18_6","020_18_6","PSA","18","6","6","Cikin wahalata na yi kira ga Ubangiji; Na yi kuka ga Allahna don taimako. A Haikalinsa ya ji muryata, Kukana na neman taimako ya kai kunnensa. ");
INSERT INTO hausa_vpl VALUES ("PS18_7","020_18_7","PSA","18","7","7","Ƙasa ta yi rawa ta kuma girgiza, tussan duwatsu sun girgiza; sun yi rawa domin ya yi fushi. ");
INSERT INTO hausa_vpl VALUES ("PS18_8","020_18_8","PSA","18","8","8","Hayaƙi ya tashi daga kafan hancinsa; wuta mai ci daga bakinsa, garwashi wuta mai ci daga bakinsa. ");
INSERT INTO hausa_vpl VALUES ("PS18_9","020_18_9","PSA","18","9","9","Ya buɗe sammai ya sauko; baƙaƙen gizagizai suna a ƙarƙashin ƙafafunsa. ");
INSERT INTO hausa_vpl VALUES ("PS18_10","020_18_10","PSA","18","10","10","Ya hau kerubobi ya kuma yi firiya; ya yi shawagi a fikafikan iska. ");
INSERT INTO hausa_vpl VALUES ("PS18_11","020_18_11","PSA","18","11","11","Ya mai da duhu abin rufuwarsa, rumfa kewaye da shi, baƙaƙen gizagizan ruwan sama na sarari, ");
INSERT INTO hausa_vpl VALUES ("PS18_12","020_18_12","PSA","18","12","12","daga cikin hasken kasancewarsa gizagizai suka yi gaba, da ƙanƙara da kuma walƙiya. ");
INSERT INTO hausa_vpl VALUES ("PS18_13","020_18_13","PSA","18","13","13","Ubangiji ya yi tsawa daga sama; muryar Mafi Ɗaukaka ya yi kāra. ");
INSERT INTO hausa_vpl VALUES ("PS18_14","020_18_14","PSA","18","14","14","Ya harba kibiyoyinsa ya kuma watsar da abokan gāba, walƙiya mai girma ya fafare su. ");
INSERT INTO hausa_vpl VALUES ("PS18_15","020_18_15","PSA","18","15","15","Kwarin teku sun bayyana tussan duniya sun bayyana a fili sa’ad da ka tsawata, ya Ubangiji, sa’ad da ka numfasa daga hancinka. ");
INSERT INTO hausa_vpl VALUES ("PS18_16","020_18_16","PSA","18","16","16","Ya miƙa hannunsa daga sama ya kama ni; ya ja ni daga zurfin ruwaye. ");
INSERT INTO hausa_vpl VALUES ("PS18_17","020_18_17","PSA","18","17","17","Ya cece ni daga abokin gābana mai ƙarfi, daga abokan gābana, waɗanda suka fi ƙarfina. ");
INSERT INTO hausa_vpl VALUES ("PS18_18","020_18_18","PSA","18","18","18","Sun yi arangama da ni a ranar masifa, amma Ubangiji ya zama mai taimakona. ");
INSERT INTO hausa_vpl VALUES ("PS18_19","020_18_19","PSA","18","19","19","Ya fitar da ni zuwa wuri mai sarari; ya kuɓutar da ni, gama yana jin daɗina. ");
INSERT INTO hausa_vpl VALUES ("PS18_20","020_18_20","PSA","18","20","20","Ubangiji ya yi haka da ni bisa ga adalcina; bisa ga tsabtar hannuwana ya ba ni lada. ");
INSERT INTO hausa_vpl VALUES ("PS18_21","020_18_21","PSA","18","21","21","Gama na kiyaye hanyoyin Ubangiji; ban yi mugunta ta wurin juyewa daga Allahna ba. ");
INSERT INTO hausa_vpl VALUES ("PS18_22","020_18_22","PSA","18","22","22","Dukan dokokinsa suna a gābana; ban juye daga ƙa’idodinsa ba. ");
INSERT INTO hausa_vpl VALUES ("PS18_23","020_18_23","PSA","18","23","23","Na kasance marar laifi a gabansa na kuma kiyaye kaina daga zunubi. ");
INSERT INTO hausa_vpl VALUES ("PS18_24","020_18_24","PSA","18","24","24","Ubangiji ya ba ni lada bisa ga adalcina, bisa ga tsabtan hannuwana a gabansa. ");
INSERT INTO hausa_vpl VALUES ("PS18_25","020_18_25","PSA","18","25","25","Ga mai aminci ka nuna kanka mai aminci, ga marar laifi ka nuna kanka marar laifi, ");
INSERT INTO hausa_vpl VALUES ("PS18_26","020_18_26","PSA","18","26","26","ga mai tsabta ka nuna kanka mai tsabta, amma ga karkatacce, ka nuna kanka mai wayo. ");
INSERT INTO hausa_vpl VALUES ("PS18_27","020_18_27","PSA","18","27","27","Kakan cece mai sauƙinkai amma kakan ƙasƙantar da masu girman kai. ");
INSERT INTO hausa_vpl VALUES ("PS18_28","020_18_28","PSA","18","28","28","Kai Ya Ubangiji, ka sa fitilata ta yi ta ci; Allahna ya mai da duhu ya zama haske. ");
INSERT INTO hausa_vpl VALUES ("PS18_29","020_18_29","PSA","18","29","29","Da taimakonka zan iya fāɗa wa runduna; tare da Allahna zan iya rinjayi katanga. ");
INSERT INTO hausa_vpl VALUES ("PS18_30","020_18_30","PSA","18","30","30","Game da Allah kuwa, hanyarsa cikakkiya ce; maganar Ubangiji marar kuskure ne. Shi garkuwa ne ga dukan waɗanda suke neman mafaka a gare shi. ");
INSERT INTO hausa_vpl VALUES ("PS18_31","020_18_31","PSA","18","31","31","Gama wane ne Allah in ba Ubangiji ba? Wane ne kuwa Dutse in ba Allahnmu ba? ");
INSERT INTO hausa_vpl VALUES ("PS18_32","020_18_32","PSA","18","32","32","Allah ne ya ƙarfafa ni da ƙarfi ya kuma sa hanyarta ta zama cikakkiya. ");
INSERT INTO hausa_vpl VALUES ("PS18_33","020_18_33","PSA","18","33","33","Ya sa ƙafafuna kamar ƙafafun barewa; ya sa na iya tsaya a kan ƙwanƙoli. ");
INSERT INTO hausa_vpl VALUES ("PS18_34","020_18_34","PSA","18","34","34","Ya horar da hannuwana don yaƙi; hannuwana za su iya tanƙware bakan tagulla. ");
INSERT INTO hausa_vpl VALUES ("PS18_35","020_18_35","PSA","18","35","35","Ka ba ni garkuwar nasara, kuma hannunka na dama yana riƙe ni; ya sunkuya don ka mai da ni mai girma. ");
INSERT INTO hausa_vpl VALUES ("PS18_36","020_18_36","PSA","18","36","36","Ka fadada hanyar da yake a ƙarƙashina, don kada ɗiɗɗigena yă juya. ");
INSERT INTO hausa_vpl VALUES ("PS18_37","020_18_37","PSA","18","37","37","Na bi abokan gābana na kuma cim musu; ban juya ba sai da na hallaka su. ");
INSERT INTO hausa_vpl VALUES ("PS18_38","020_18_38","PSA","18","38","38","Na ragargaza su har ba za su iya tashi ba; sun fāɗi a ƙarƙashin ƙafafuna. ");
INSERT INTO hausa_vpl VALUES ("PS18_39","020_18_39","PSA","18","39","39","Ka ƙarfafa ni da ƙarfi saboda yaƙi; ka sa abokan gābana suka rusuna mini. ");
INSERT INTO hausa_vpl VALUES ("PS18_40","020_18_40","PSA","18","40","40","Ka sa abokan gābana suka juya suka gudu, na kuma hallaka abokan gābana. ");
INSERT INTO hausa_vpl VALUES ("PS18_41","020_18_41","PSA","18","41","41","Sun nemi taimako, amma ba su sami wanda zai cece su ba, ga Ubangiji, amma bai amsa ba. ");
INSERT INTO hausa_vpl VALUES ("PS18_42","020_18_42","PSA","18","42","42","Na murƙushe su kamar ƙura mai laushi da iska ke kwashewa; na zubar da su kamar laka a tituna. ");
INSERT INTO hausa_vpl VALUES ("PS18_43","020_18_43","PSA","18","43","43","Ka cece ni daga harin mutane; ka mai da ni kan al’ummai. Mutanen da ban sani ba sun zama bayina, ");
INSERT INTO hausa_vpl VALUES ("PS18_44","020_18_44","PSA","18","44","44","da zarar sun ji ni, sukan yi mini biyayya; baƙi suna rusuna a gabana. ");
INSERT INTO hausa_vpl VALUES ("PS18_45","020_18_45","PSA","18","45","45","Duk sukan karai; suna zuwa da rawan jiki daga mafakansu. ");
INSERT INTO hausa_vpl VALUES ("PS18_46","020_18_46","PSA","18","46","46","Ubangiji mai rai ne! Yabo ya tabbata ga Dutsena! Girma ya tabbata ga Allah Mai cetona! ");
INSERT INTO hausa_vpl VALUES ("PS18_47","020_18_47","PSA","18","47","47","Shi ne Allah mai sāka mini, wanda yake sa al’ummai a ƙarƙashina, ");
INSERT INTO hausa_vpl VALUES ("PS18_48","020_18_48","PSA","18","48","48","wanda yakan cece ni daga abokan gābana. Ana girmama ka bisa abokan gābana; daga masu tā-da-na-zaune-tsaye ka kuɓutar da ni. ");
INSERT INTO hausa_vpl VALUES ("PS18_49","020_18_49","PSA","18","49","49","Saboda haka zan yabe ka a cikin al’ummai, ya Ubangiji; zan rera yabai ga sunanka. ");
INSERT INTO hausa_vpl VALUES ("PS18_50","020_18_50","PSA","18","50","50","Yakan ba sarkinsa nasarori; yakan nuna alheri marar ƙarewa ga shafaffensa, ga Dawuda da zuriyarsa har abada. ");
INSERT INTO hausa_vpl VALUES ("PS19_1","020_19_1","PSA","19","1","1","Don mai bi da kaɗe-kaɗe. Zabura ta Dawuda. Sammai suna shelar ɗaukakar Allah; sararin sama suna furta aikin hannuwansa. ");
INSERT INTO hausa_vpl VALUES ("PS19_2","020_19_2","PSA","19","2","2","Kowace rana tana yin jawabi; kowane dare yana nuna sani. ");
INSERT INTO hausa_vpl VALUES ("PS19_3","020_19_3","PSA","19","3","3","Ba magana, ba kalmar da aka hurta, ba wani amon da aka ji daga gare su. ");
INSERT INTO hausa_vpl VALUES ("PS19_4","020_19_4","PSA","19","4","4","Duk da haka muryarsu tana kaiwa ga dukan duniya, kalmominsu zuwa iyakokin duniya. A sammai Allah ya kafa tenti domin rana, ");
INSERT INTO hausa_vpl VALUES ("PS19_5","020_19_5","PSA","19","5","5","wanda yake kamar ango mai fitowa daga rumfarsa, kamar gwani ɗan wasan da yake farin ciki yă yi tsere. ");
INSERT INTO hausa_vpl VALUES ("PS19_6","020_19_6","PSA","19","6","6","Takan taso daga ƙarshen sammai ta kewaye zuwa wancan; babu abin da yake ɓuya wa zafinta. ");
INSERT INTO hausa_vpl VALUES ("PS19_7","020_19_7","PSA","19","7","7","Dokar Ubangiji cikakkiya ce, takan wartsakar da rai. Farillan Ubangiji abin dogara ne, suna mai da hikima da sauƙi. ");
INSERT INTO hausa_vpl VALUES ("PS19_8","020_19_8","PSA","19","8","8","Ƙa’idodin Ubangiji daidai ne, suna ba da farin ciki ga zuciya. Umarnan Ubangiji haske ne suna ba da haske ga idanu. ");
INSERT INTO hausa_vpl VALUES ("PS19_9","020_19_9","PSA","19","9","9","Tsoron Ubangiji yakan kawo tsabtar zuciya, zai kasance har abada. Farillan Ubangiji tabbatattu ne, kuma gaba ɗaya masu adalci ne. ");
INSERT INTO hausa_vpl VALUES ("PS19_10","020_19_10","PSA","19","10","10","Sun fi zinariya daraja, fiye da zalla zinariya nesa; sun fi zuma zaƙi fiye da zuma daga kaki. ");
INSERT INTO hausa_vpl VALUES ("PS19_11","020_19_11","PSA","19","11","11","Ta wurinsu ana gargaɗe bawanka; a kiyaye su akwai lada mai girma. ");
INSERT INTO hausa_vpl VALUES ("PS19_12","020_19_12","PSA","19","12","12","Wane ne zai iya rabe kurakuransa? Ya gafarta ɓoyayyun laifofinsa. ");
INSERT INTO hausa_vpl VALUES ("PS19_13","020_19_13","PSA","19","13","13","Ka kiyaye bawanka daga zunubin ganganci; kada ka bari su yi mulki a kaina. Ta haka zan zama marar laifi; marar laifi na babban tawaye. ");
INSERT INTO hausa_vpl VALUES ("PS19_14","020_19_14","PSA","19","14","14","Bari kalmomin bakina da tunanin zuciyata su zama abin gamsuwa a gabanka, Ya Ubangiji, Dutsena da Mai fansata. ");
INSERT INTO hausa_vpl VALUES ("PS20_1","020_20_1","PSA","20","1","1","Don mai bi da kaɗe-kaɗe. Zabura ta Dawuda. Ubangiji ya amsa maka sa’ad da ka yi kira cikin wahala; bari sunan Allah na Yaƙub yă kiyaye ka. ");
INSERT INTO hausa_vpl VALUES ("PS20_2","020_20_2","PSA","20","2","2","Bari yă aiko maka da taimako daga wuri mai tsarki yă kuma ba ka gudummawa daga Sihiyona. ");
INSERT INTO hausa_vpl VALUES ("PS20_3","020_20_3","PSA","20","3","3","Bari yă tuna da dukan sadakokinka yă kuma karɓi hadayunka na ƙonawa. Sela ");
INSERT INTO hausa_vpl VALUES ("PS20_4","020_20_4","PSA","20","4","4","Bari yă biya maka bukatan ranka yă kuma sa dukan shirye-shiryenka su yi nasara. ");
INSERT INTO hausa_vpl VALUES ("PS20_5","020_20_5","PSA","20","5","5","Za mu yi sowa ta farin ciki sa’ad da ka yi nasara mu kuma ɗaga tutotinmu a cikin sunan Allahnmu. Bari Ubangiji yă biya maka dukan bukatunka. ");
INSERT INTO hausa_vpl VALUES ("PS20_6","020_20_6","PSA","20","6","6","Yanzu na san cewa, Ubangiji yakan cece shafaffensa. Yakan amsa masa daga samansa mai tsarki da ikon ceto na hannun damansa. ");
INSERT INTO hausa_vpl VALUES ("PS20_7","020_20_7","PSA","20","7","7","Waɗansu sun dogara a kekunan yaƙi waɗansu kuma a dawakai, amma mu, mun dogara a cikin sunan Ubangiji Allahnmu. ");
INSERT INTO hausa_vpl VALUES ("PS20_8","020_20_8","PSA","20","8","8","Za a durƙusar da su, su kuma fāɗi, amma mu za mu tashi mu tsaya daram. ");
INSERT INTO hausa_vpl VALUES ("PS20_9","020_20_9","PSA","20","9","9","Ya Ubangiji, ka ba da nasara ga sarki! Ka amsa mana sa’ad da muka yi kira! ");
INSERT INTO hausa_vpl VALUES ("PS21_1","020_21_1","PSA","21","1","1","Don mai bi da kaɗe-kaɗe. Zabura ta Dawuda. Ya Ubangiji, sarki yana farin ciki cikin ƙarfinka. Yana farin cikinsa ƙwarai cikin nasarorin da ka ba shi! ");
INSERT INTO hausa_vpl VALUES ("PS21_2","020_21_2","PSA","21","2","2","Ka biya masa bukatar zuciyarsa ba ka kuwa hana masa roƙon da ya yi da leɓunansa ba. Sela ");
INSERT INTO hausa_vpl VALUES ("PS21_3","020_21_3","PSA","21","3","3","Ka marabce shi da yalwar albarka ka kuma sa masa rawanin zallan zinariya a kansa. ");
INSERT INTO hausa_vpl VALUES ("PS21_4","020_21_4","PSA","21","4","4","Ya nemi ka ba shi rai, ka kuwa ba shi, tsawo kwanaki, har abada abadin ");
INSERT INTO hausa_vpl VALUES ("PS21_5","020_21_5","PSA","21","5","5","Ta wurin nasarorin da ka ba shi, ɗaukakarsa mai girma ce; ka mayar masa ɗaukaka da kuma suna. ");
INSERT INTO hausa_vpl VALUES ("PS21_6","020_21_6","PSA","21","6","6","Tabbatacce ka ba shi madawwamiyar albarka ka kuma sa shi murna da farin cikin kasancewarka. ");
INSERT INTO hausa_vpl VALUES ("PS21_7","020_21_7","PSA","21","7","7","Gama sarki ya dogara gare ka Ubangiji ta wurin ƙauna marar ƙarewa ta Mafi Ɗaukaka ba zai jijjigu ba. ");
INSERT INTO hausa_vpl VALUES ("PS21_8","020_21_8","PSA","21","8","8","Hannunka zai kakkama dukan abokan gābanka; hannunka na dama zai kakkama masu ƙinka. ");
INSERT INTO hausa_vpl VALUES ("PS21_9","020_21_9","PSA","21","9","9","A lokacin bayyanarka za ka sa su zama kamar wutar matoya. Cikin fushinsa Ubangiji zai haɗiye su, kuma wutarsa za tă cinye su. ");
INSERT INTO hausa_vpl VALUES ("PS21_10","020_21_10","PSA","21","10","10","Za ka hallaka ’ya’yansu daga duniya, zuriyarsu kuma daga ’yan adam. ");
INSERT INTO hausa_vpl VALUES ("PS21_11","020_21_11","PSA","21","11","11","Ko da yake suna shirya maka mugunta suna kuma ƙirƙiro mugayen dabaru, ba za su yi nasara ba; ");
INSERT INTO hausa_vpl VALUES ("PS21_12","020_21_12","PSA","21","12","12","gama za ka sa su juye bayansu sa’ad da ka auna su da bakan da ka ja. ");
INSERT INTO hausa_vpl VALUES ("PS21_13","020_21_13","PSA","21","13","13","Ka sami ɗaukaka, ya Ubangiji cikin ƙarfinka; za mu rera mu kuma yabi ikonka. ");
INSERT INTO hausa_vpl VALUES ("PS22_1","020_22_1","PSA","22","1","1","Don mai bi da kaɗe-kaɗe. Da salon “Matar Zomon Safiya.” Zabura ta Dawuda. Ya Allahna, ya Allahna, don me ka yashe ni? Me ya sa ka yi nisa da cetona, ka yi nesa daga kalmomin nishina? ");
INSERT INTO hausa_vpl VALUES ("PS22_2","020_22_2","PSA","22","2","2","Ya Allahna, na yi kuka da rana, amma ba ka amsa ba, da dare kuma ban yi shiru ba. ");
INSERT INTO hausa_vpl VALUES ("PS22_3","020_22_3","PSA","22","3","3","Duk da haka kana a kursiyi a matsayin Mai Tsarkin nan; kai ne yabon Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS22_4","020_22_4","PSA","22","4","4","A gare ka ne kakanninmu suka sa bege; sun dogara ka kuwa cece su. ");
INSERT INTO hausa_vpl VALUES ("PS22_5","020_22_5","PSA","22","5","5","Sun yi kuka gare ka suka kuma sami ceto; a gare ka suka dogara kuma ba su sha kunya ba. ");
INSERT INTO hausa_vpl VALUES ("PS22_6","020_22_6","PSA","22","6","6","Amma ni dai tsutsa ne ba mutum ba, wanda mutane suke yi wa ba’a suka kuma rena shi. ");
INSERT INTO hausa_vpl VALUES ("PS22_7","020_22_7","PSA","22","7","7","Duk wanda ya gan ni yakan yi mini ba’a; suna yin mini ashar, suna kaɗa kansu suna cewa, ");
INSERT INTO hausa_vpl VALUES ("PS22_8","020_22_8","PSA","22","8","8","“Ya dogara ga Ubangiji; bari Ubangiji yă cece shi. Bari yă cece shi, da yake yana jin daɗinsa.” ");
INSERT INTO hausa_vpl VALUES ("PS22_9","020_22_9","PSA","22","9","9","Duk da haka ka fitar da ni daga ciki; ka sa na dogara gare ka, ko ma a ƙirjin mahaifiyata. ");
INSERT INTO hausa_vpl VALUES ("PS22_10","020_22_10","PSA","22","10","10","Daga haihuwa an jefa ni a kanka; daga cikin mahaifiyata kai ne Allahna. ");
INSERT INTO hausa_vpl VALUES ("PS22_11","020_22_11","PSA","22","11","11","Kada ka yi nesa da ni, gama wahala na kusa kuma babu wani da zai taimaka. ");
INSERT INTO hausa_vpl VALUES ("PS22_12","020_22_12","PSA","22","12","12","Bijimai masu yawa sun kewaye ni; bijimai masu ƙarfi na Bashan sun sa ni a tsaka. ");
INSERT INTO hausa_vpl VALUES ("PS22_13","020_22_13","PSA","22","13","13","Zakoki masu ruri suna yayyage abin da suka kama sun buɗe bakunansu a kaina. ");
INSERT INTO hausa_vpl VALUES ("PS22_14","020_22_14","PSA","22","14","14","An zubar da ni kamar ruwa, kuma dukan ƙasusuwana sun fiffito daga mahaɗai. Zuciyata ta zama kaki; ta narke a cikina. ");
INSERT INTO hausa_vpl VALUES ("PS22_15","020_22_15","PSA","22","15","15","Ƙarfina ya bushe kamar kasko, harshena kuma ya manne wa dasashina na sama; ka kwantar da ni a ƙurar mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PS22_16","020_22_16","PSA","22","16","16","Karnuka sun kewaye ni; ƙungiyar mugaye sun sa ni a tsaka, sun soki hannuwana da ƙafafuna. ");
INSERT INTO hausa_vpl VALUES ("PS22_17","020_22_17","PSA","22","17","17","Zan iya ƙirga ƙasusuwana; mutane suna farin ciki a kaina. ");
INSERT INTO hausa_vpl VALUES ("PS22_18","020_22_18","PSA","22","18","18","Sun raba rigunana a tsakaninsu suka kuma jefa ƙuri’a a kan rigunana. ");
INSERT INTO hausa_vpl VALUES ("PS22_19","020_22_19","PSA","22","19","19","Amma kai, ya Ubangiji, kada ka yi nisa; Ya Ƙarfina zo da sauri don ka taimake ni. ");
INSERT INTO hausa_vpl VALUES ("PS22_20","020_22_20","PSA","22","20","20","Ka ceci raina daga takobi, raina mai daraja daga ikon karnuka. ");
INSERT INTO hausa_vpl VALUES ("PS22_21","020_22_21","PSA","22","21","21","Ka cece ni daga bakin zakoki; ka cece ni daga ƙahonin ɓauna. ");
INSERT INTO hausa_vpl VALUES ("PS22_22","020_22_22","PSA","22","22","22","Zan furta sunanka ga ’yan’uwana; cikin taron masu sujada zan yabe ka. ");
INSERT INTO hausa_vpl VALUES ("PS22_23","020_22_23","PSA","22","23","23","Ku da kuke tsoron Ubangiji, ku yabe shi! Dukanku zuriyar Yaƙub, ku girmama shi! Ku girmama shi, dukanku zuriyar Isra’ila! ");
INSERT INTO hausa_vpl VALUES ("PS22_24","020_22_24","PSA","22","24","24","Gama bai rena ko yă ƙyale wahalar masu shan wuya ba; bai ɓoye fuskarsa daga gare shi ba amma ya saurari kukansa na neman taimako. ");
INSERT INTO hausa_vpl VALUES ("PS22_25","020_22_25","PSA","22","25","25","Daga gare ka yabona yake zuwa cikin babban taro; a gaban waɗanda suke tsoronka zan cika alkawarina. ");
INSERT INTO hausa_vpl VALUES ("PS22_26","020_22_26","PSA","22","26","26","Matalauta za su ci su ƙoshi; su da suke neman Ubangiji za su yabe shi, bari zukatanku su rayu har abada! ");
INSERT INTO hausa_vpl VALUES ("PS22_27","020_22_27","PSA","22","27","27","Dukan iyakokin duniya za su tuna su kuma juya ga Ubangiji, kuma dukan iyalan al’ummai za su rusuna a gabansa, ");
INSERT INTO hausa_vpl VALUES ("PS22_28","020_22_28","PSA","22","28","28","gama mulki na Ubangiji ne kuma yana mulki a bisa al’ummai. ");
INSERT INTO hausa_vpl VALUES ("PS22_29","020_22_29","PSA","22","29","29","Dukan attajiran duniya za su yi biki su kuma yi sujada; dukan waɗanda suka gangara zuwa ƙura za su durƙusa a gabansa, waɗanda ba za su iya bar kansu da rai ba. ");
INSERT INTO hausa_vpl VALUES ("PS22_30","020_22_30","PSA","22","30","30","Zuriya masu zuwa za su yi masa hidima; za a faɗa wa zuriya na nan gaba game da Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS22_31","020_22_31","PSA","22","31","31","Za su yi shelar adalcinsa ga mutanen da ba a riga an haifa ba, gama ya aikata shi. ");
INSERT INTO hausa_vpl VALUES ("PS23_1","020_23_1","PSA","23","1","1","Zabura ta Dawuda. Ubangiji ne yake kiwona, ba zan rasa kome ba, ");
INSERT INTO hausa_vpl VALUES ("PS23_2","020_23_2","PSA","23","2","2","Yakan sa in kwanta a makiyaya mai ɗanyar ciyawa, yakan bi da ni kusa da ruwaye marar hayaniya, ");
INSERT INTO hausa_vpl VALUES ("PS23_3","020_23_3","PSA","23","3","3","yakan maido da raina. Yakan bi da ni a hanyoyin adalci saboda sunansa. ");
INSERT INTO hausa_vpl VALUES ("PS23_4","020_23_4","PSA","23","4","4","Ko da na yi tafiya ta kwari na inuwar mutuwa, ba zan ji tsoron mugu ba, gama kana tare da ni; bulalarka na dūka da kuma sandanka na tafiya, za su yi mini ta’aziyya. ");
INSERT INTO hausa_vpl VALUES ("PS23_5","020_23_5","PSA","23","5","5","Ka shirya mini tebur a gaban abokan gābana. Ka shafe kaina da mai; kwaf nawa ya cika har yana zuba. ");
INSERT INTO hausa_vpl VALUES ("PS23_6","020_23_6","PSA","23","6","6","Tabbatacce alheri da ƙauna za su bi dukan kwanakin raina, zan kuwa zauna a gidan Ubangiji har abada. ");
INSERT INTO hausa_vpl VALUES ("PS24_1","020_24_1","PSA","24","1","1","Zabura ta Dawuda. Duniya ta Ubangiji ce da kome da yake cikinta, duniya, da dukan waɗanda suke zama a cikinta; ");
INSERT INTO hausa_vpl VALUES ("PS24_2","020_24_2","PSA","24","2","2","gama ya gina ta a kan tekuna ya kafa ta a kan ruwaye. ");
INSERT INTO hausa_vpl VALUES ("PS24_3","020_24_3","PSA","24","3","3","Wa zai iya hawan tudun Ubangiji? Wa zai iya tsaya a wurinsa mai tsarki? ");
INSERT INTO hausa_vpl VALUES ("PS24_4","020_24_4","PSA","24","4","4","Sai wanda yake da hannu mai tsabta da kuma tsabtar zuciya, wanda ba ya ba da ransa ga bautar gunki ko ya rantse bisa abin da yake ƙarya. ");
INSERT INTO hausa_vpl VALUES ("PS24_5","020_24_5","PSA","24","5","5","Zai sami albarka daga Ubangiji da fiffitawa daga Allah Mai cetonsa. ");
INSERT INTO hausa_vpl VALUES ("PS24_6","020_24_6","PSA","24","6","6","Irin tsaran waɗanda suke nemansa ke nan, waɗanda suke neman fuskarka, ya Allah na Yaƙub. Sela ");
INSERT INTO hausa_vpl VALUES ("PS24_7","020_24_7","PSA","24","7","7","Ku ɗaga kawunanku, ya ku ƙofofi; ku ɗagu, ku daɗaɗɗun ƙofofi, don Sarkin ɗaukaka yă shiga. ");
INSERT INTO hausa_vpl VALUES ("PS24_8","020_24_8","PSA","24","8","8","Wane ne wannan Sarkin ɗaukaka? Ubangiji ne mai ƙarfi mai iko, Ubangiji mai girma a yaƙi. ");
INSERT INTO hausa_vpl VALUES ("PS24_9","020_24_9","PSA","24","9","9","Ku ɗaga kawunanku, ya ku ƙofofi; ku ɗagu, ku daɗaɗɗun ƙofofi, don Sarkin ɗaukaka yă shiga. ");
INSERT INTO hausa_vpl VALUES ("PS24_10","020_24_10","PSA","24","10","10","Wane ne shi, wannan Sarkin ɗaukaka? Ubangiji Maɗaukaki, shi ne Sarkin ɗaukaka. Sela ");
INSERT INTO hausa_vpl VALUES ("PS25_1","020_25_1","PSA","25","1","1","Ta Dawuda. A gare ka Ya Ubangiji, na miƙa raina. ");
INSERT INTO hausa_vpl VALUES ("PS25_2","020_25_2","PSA","25","2","2","A gare ka na dogara, ya Allahna. Kada ka bari in sha kunya, ko ka bar abokan gābana su yi nasara a kaina. ");
INSERT INTO hausa_vpl VALUES ("PS25_3","020_25_3","PSA","25","3","3","Ba wanda yake sa bege a gare ka da zai taɓa shan kunya, amma za su sha kunya su da suke tayarwa babu dalili. ");
INSERT INTO hausa_vpl VALUES ("PS25_4","020_25_4","PSA","25","4","4","Ka nuna mini hanyoyinka, ya Ubangiji, ka koya mini hanyoyinka; ");
INSERT INTO hausa_vpl VALUES ("PS25_5","020_25_5","PSA","25","5","5","ka bi da ni cikin gaskiyarka ka kuma koya mini, gama kai ne Allah Mai cetona, kuma begena yana a kanka dukan yini. ");
INSERT INTO hausa_vpl VALUES ("PS25_6","020_25_6","PSA","25","6","6","Ka tuna, ya Ubangiji da jinƙai da kuma ƙaunarka mai girma, gama suna nan tun dā. ");
INSERT INTO hausa_vpl VALUES ("PS25_7","020_25_7","PSA","25","7","7","Kada ka tuna da zunuban ƙuruciyata da kuma hanyoyin tawayena; bisa ga ƙaunarka ka tuna da ni, gama kai nagari ne, ya Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS25_8","020_25_8","PSA","25","8","8","Ubangiji nagari da mai adalci ne; saboda haka yakan koyar da masu zunubi a hanyoyinsa. ");
INSERT INTO hausa_vpl VALUES ("PS25_9","020_25_9","PSA","25","9","9","Yakan bi da masu tawali’u cikin abin da yake daidai ya kuma koyar da su hanyoyinsa. ");
INSERT INTO hausa_vpl VALUES ("PS25_10","020_25_10","PSA","25","10","10","Dukan hanyoyin Ubangiji ƙaunatattu ne da kuma aminci ga waɗanda suke kiyaye abin da alkawari ya bukaci. ");
INSERT INTO hausa_vpl VALUES ("PS25_11","020_25_11","PSA","25","11","11","Saboda sunanka, ya Ubangiji, ka gafarta laifina, ko da yake mai girma ne. ");
INSERT INTO hausa_vpl VALUES ("PS25_12","020_25_12","PSA","25","12","12","To wane ne mai tsoron Ubangiji? Zai koyar da shi a hanyar da ya zaɓa masa. ");
INSERT INTO hausa_vpl VALUES ("PS25_13","020_25_13","PSA","25","13","13","Zai ci kwanakinsa a wadace, kuma zuriyarsa za su gāji ƙasar. ");
INSERT INTO hausa_vpl VALUES ("PS25_14","020_25_14","PSA","25","14","14","Ubangiji yakan amince da waɗanda suke tsoronsa; yakan sa su san alkawarinsa. ");
INSERT INTO hausa_vpl VALUES ("PS25_15","020_25_15","PSA","25","15","15","Idanuna kullum suna a kan Ubangiji, gama shi ne kaɗai zai kuɓutar da ƙafafuna daga tarko. ");
INSERT INTO hausa_vpl VALUES ("PS25_16","020_25_16","PSA","25","16","16","Ka juye wurina ka kuma yi mini jinƙai, gama na kaɗaice ina kuma wahala. ");
INSERT INTO hausa_vpl VALUES ("PS25_17","020_25_17","PSA","25","17","17","Damuwoyin zuciyata sun ninka; ka ’yantar da ni daga wahalata. ");
INSERT INTO hausa_vpl VALUES ("PS25_18","020_25_18","PSA","25","18","18","Ka dubi wahalata da kuma azabata ka ɗauke mini dukan zunubaina. ");
INSERT INTO hausa_vpl VALUES ("PS25_19","020_25_19","PSA","25","19","19","Dubi yadda abokan gābana sun ƙaru da kuma yadda suka ƙara ƙina! ");
INSERT INTO hausa_vpl VALUES ("PS25_20","020_25_20","PSA","25","20","20","Ka tsare raina ka kuma kuɓutar da ni; kada ka bari in sha kunya, gama na nemi mafaka daga gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS25_21","020_25_21","PSA","25","21","21","Bari mutunci da adalci su tsare ni, domin begena yana a kanka. ");
INSERT INTO hausa_vpl VALUES ("PS25_22","020_25_22","PSA","25","22","22","Ka fanshi Isra’ila, ya Allah, daga dukan wahalarsu! ");
INSERT INTO hausa_vpl VALUES ("PS26_1","020_26_1","PSA","26","1","1","Ta Dawuda. Ka nuna rashin laifina, ya Ubangiji, gama na yi rayuwa marar zargi; Na dogara ga Ubangiji ba tare da kaucewa ba. ");
INSERT INTO hausa_vpl VALUES ("PS26_2","020_26_2","PSA","26","2","2","Ka jarraba ni, ya Ubangiji, ka kuma gwada ni, ka bincike zuciyata da tunanina; ");
INSERT INTO hausa_vpl VALUES ("PS26_3","020_26_3","PSA","26","3","3","gama ƙaunarka kullum tana a gabana, kuma ina cin gaba da tafiya a cikin gaskiyarka. ");
INSERT INTO hausa_vpl VALUES ("PS26_4","020_26_4","PSA","26","4","4","Ba na zama tare da masu ruɗu, ko in yi tarayya da masu riya; ");
INSERT INTO hausa_vpl VALUES ("PS26_5","020_26_5","PSA","26","5","5","na ƙi jinin taron masu aikata mugunta na ƙi in zauna tare da mugaye. ");
INSERT INTO hausa_vpl VALUES ("PS26_6","020_26_6","PSA","26","6","6","Na wanke hannuwana cikin rashin laifi, ina yawo a bagadenka Ya Ubangiji, ");
INSERT INTO hausa_vpl VALUES ("PS26_7","020_26_7","PSA","26","7","7","ina shelar yabonka da ƙarfi ina faɗin dukan ayyukanka masu banmamaki. ");
INSERT INTO hausa_vpl VALUES ("PS26_8","020_26_8","PSA","26","8","8","Ina ƙaunar gidan da kake zama, ya Ubangiji, wurin da ɗaukakarka ke zaune. ");
INSERT INTO hausa_vpl VALUES ("PS26_9","020_26_9","PSA","26","9","9","Kada ka ɗauke raina tare da masu zunubi raina tare da masu son yin kisankai ");
INSERT INTO hausa_vpl VALUES ("PS26_10","020_26_10","PSA","26","10","10","waɗanda akwai mugayen dabaru a hannuwansu, waɗanda hannuwansu na dama suna cike da cin hanci. ");
INSERT INTO hausa_vpl VALUES ("PS26_11","020_26_11","PSA","26","11","11","Amma na yi rayuwa marar zargi; ka cece ni ka kuma yi mini jinƙai. ");
INSERT INTO hausa_vpl VALUES ("PS26_12","020_26_12","PSA","26","12","12","Ƙafafuna suna tsaye daram; cikin taro mai girma zan yabi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS27_1","020_27_1","PSA","27","1","1","Ta Dawuda. Ubangiji ne haskena da cetona, wa zan ji tsoro? Ubangiji ne mafakar raina, wane ne zan ji tsoro? ");
INSERT INTO hausa_vpl VALUES ("PS27_2","020_27_2","PSA","27","2","2","Sa’ad da mugaye suka tasar mini don su cinye ni, sa’ad da abokan gābana da maƙiyina suka kawo mini hari, sun yi tuntuɓe suka fāɗi. ");
INSERT INTO hausa_vpl VALUES ("PS27_3","020_27_3","PSA","27","3","3","Ko da yake mayaƙa sun kewaye ni, zuciyata ba za tă ji tsoro ba; ko da yake ya ɓarke a kaina, duk da haka zan ƙarfafa. ");
INSERT INTO hausa_vpl VALUES ("PS27_4","020_27_4","PSA","27","4","4","Abu guda na roƙi Ubangiji, wannan shi ne na nema, cewa in zauna a gidan Ubangiji dukan kwanakin raina, in dubi kyan Ubangiji in kuma neme shi a cikin haikalinsa. ");
INSERT INTO hausa_vpl VALUES ("PS27_5","020_27_5","PSA","27","5","5","Gama a lokacin wahala, zai kiyaye ni lafiya a wurin zamansa; zai ɓoye ni cikin inuwar tabanakul nasa ya kuma sa ni can a bisa dutse. ");
INSERT INTO hausa_vpl VALUES ("PS27_6","020_27_6","PSA","27","6","6","Sa’an nan kaina zai ɗaukaka a bisa abokan gābana waɗanda suka kewaye ni; a tabanakul nasa zan miƙa hadaya da sowa ta farin ciki; zan rera in kuma yi kiɗi ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS27_7","020_27_7","PSA","27","7","7","Ka ji muryata sa’ad da na yi kira, ya Ubangiji; ka yi mini jinƙai ka kuma amsa mini. ");
INSERT INTO hausa_vpl VALUES ("PS27_8","020_27_8","PSA","27","8","8","Zuciyata kan faɗa game da kai, “Nemi fuskarsa!” Fuskarka, Ubangiji, zan nema. ");
INSERT INTO hausa_vpl VALUES ("PS27_9","020_27_9","PSA","27","9","9","Kada ka ɓoye fuskarka daga gare ni, kada ka kore bawanka daga gare ka cikin fushi; kai ne ka kasance mai taimakona. Kada ka ƙi ni ko ka yashe ni, Ya Allah Mai cetona. ");
INSERT INTO hausa_vpl VALUES ("PS27_10","020_27_10","PSA","27","10","10","Ko da mahaifina da mahaifiyata sun yashe ni, Ubangiji zai karɓe ni. ");
INSERT INTO hausa_vpl VALUES ("PS27_11","020_27_11","PSA","27","11","11","Ka koya mini hanyarka, ya Ubangiji; ka bi da ni a miƙaƙƙiyar hanya saboda masu danne ni. ");
INSERT INTO hausa_vpl VALUES ("PS27_12","020_27_12","PSA","27","12","12","Kada ka ba da ni da sha’awar maƙiyina, gama masu shaidar ƙarya sun taso a kaina, suna numfasa tashin hankali. ");
INSERT INTO hausa_vpl VALUES ("PS27_13","020_27_13","PSA","27","13","13","Har yanzu ina da ƙarfin gwiwa a wannan cewa zan ga alherin Ubangiji; a ƙasar masu rai. ");
INSERT INTO hausa_vpl VALUES ("PS27_14","020_27_14","PSA","27","14","14","Ka dogara ga Ubangiji, ka yi ƙarfin hali ka yi ƙarfin zuciya ka kuma dogara ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS28_1","020_28_1","PSA","28","1","1","Ta Dawuda. A gare ka nake kira, ya Ubangiji Dutsena; kada ka yi mini kunnen ƙashi. Gama in ka yi shiru, zan zama kamar waɗanda suka gangara rami. ");
INSERT INTO hausa_vpl VALUES ("PS28_2","020_28_2","PSA","28","2","2","Ka ji kukata ta neman jinƙai yayinda nake kira ka don neman taimako, yayinda nake daga hannuwana wajen Wurinka Mafi Tsarki. ");
INSERT INTO hausa_vpl VALUES ("PS28_3","020_28_3","PSA","28","3","3","Kada ka ja ni tare da mugaye, tare da masu yin mugunta, masu magana kamar ta alheri ce da maƙwabtansu amma suna riƙe da su a zukatansu. ");
INSERT INTO hausa_vpl VALUES ("PS28_4","020_28_4","PSA","28","4","4","Ka sāka musu da ayyukansu da kuma don mugun aikinsu; ka sāka musu saboda abin da hannuwansu suka yi ka kuma mayar musu abin da ya dace da su. ");
INSERT INTO hausa_vpl VALUES ("PS28_5","020_28_5","PSA","28","5","5","Da yake ba su kula da ayyukan Ubangiji da abin da hannuwansa suka yi ba, zai rushe su ba kuwa zai ƙara gina su ba. ");
INSERT INTO hausa_vpl VALUES ("PS28_6","020_28_6","PSA","28","6","6","Yabo ya tabbata ga Ubangiji, gama ya ji kukata na neman jinƙai. ");
INSERT INTO hausa_vpl VALUES ("PS28_7","020_28_7","PSA","28","7","7","Ubangiji shi ne ƙarfina da garkuwata; zuciyata ta amince da shi, kuma na sami taimako. Zuciyata ta yi tsalle don farin ciki zan kuwa yi godiya gare shi cikin waƙa. ");
INSERT INTO hausa_vpl VALUES ("PS28_8","020_28_8","PSA","28","8","8","Ubangiji shi ne ƙarfin mutanensa, kagarar ceto domin shafaffensa. ");
INSERT INTO hausa_vpl VALUES ("PS28_9","020_28_9","PSA","28","9","9","Ka cece mutanenka ka kuma albarkace gādonka; ka zama mai kiwonsu ka kuma riƙe su har abada. ");
INSERT INTO hausa_vpl VALUES ("PS29_1","020_29_1","PSA","29","1","1","Zabura ta Dawuda. Ku ba da girma ga Ubangiji, ya ku manya, ku ba da girma ga Ubangiji saboda ɗaukaka da kuma ƙarfinsa. ");
INSERT INTO hausa_vpl VALUES ("PS29_2","020_29_2","PSA","29","2","2","Ku ba da girma ga Ubangiji, ɗaukakar da ta dace da sunansa; ku bauta wa Ubangiji cikin ɗaukakar tsarkinsa. ");
INSERT INTO hausa_vpl VALUES ("PS29_3","020_29_3","PSA","29","3","3","Muryar Ubangiji tana a bisa ruwaye; Allah Maɗaukaki ya yi tsawa, Ubangiji ya yi tsawa a bisa manyan ruwaye. ");
INSERT INTO hausa_vpl VALUES ("PS29_4","020_29_4","PSA","29","4","4","Muryar Ubangiji mai iko ce; muryar Ubangiji da girma take. ");
INSERT INTO hausa_vpl VALUES ("PS29_5","020_29_5","PSA","29","5","5","Muryar Ubangiji ta kakkarya itatuwan al’ul na Lebanon. Ubangiji ya kakkarya itatuwan al’ul na Lebanon kucu-kucu. ");
INSERT INTO hausa_vpl VALUES ("PS29_6","020_29_6","PSA","29","6","6","Ya sa dutsen Lebanon ya yi ta tsalle kamar ɗan maraƙi, Siriyon kuma kamar ɗan jakin jeji. ");
INSERT INTO hausa_vpl VALUES ("PS29_7","020_29_7","PSA","29","7","7","Muryar Ubangiji ta buga da walƙatar walƙiya. ");
INSERT INTO hausa_vpl VALUES ("PS29_8","020_29_8","PSA","29","8","8","Muryar Ubangiji ta girgiza hamada Ubangiji ya girgiza Hamadan Kadesh. ");
INSERT INTO hausa_vpl VALUES ("PS29_9","020_29_9","PSA","29","9","9","Muryar Ubangiji ta murɗa itatuwan oak ya kakkaɓe itatuwan kurmi. Kuma a cikin haikalinsa kowa ya ce, “Ɗaukaka!” ");
INSERT INTO hausa_vpl VALUES ("PS29_10","020_29_10","PSA","29","10","10","Ubangiji na zaune yana sarauta a bisa rigyawa; Ubangiji yana sarauta kamar Sarki har abada. ");
INSERT INTO hausa_vpl VALUES ("PS29_11","020_29_11","PSA","29","11","11","Ubangiji kan ba da ƙarfi ga mutanensa; Ubangiji kan albarkace mutanensa da salama. ");
INSERT INTO hausa_vpl VALUES ("PS30_1","020_30_1","PSA","30","1","1","Zabura ce. Wata waƙa. Don keɓewar haikali. Ta Dawuda. Zan girmama ka Ya Ubangiji, gama ka tsamo ni daga zurfafa ba ka bar abokan gābana sun yi farin ciki a kaina ba. ");
INSERT INTO hausa_vpl VALUES ("PS30_2","020_30_2","PSA","30","2","2","Ya Ubangiji Allahna, na yi kira gare ka don taimako ka kuwa warkar da ni. ");
INSERT INTO hausa_vpl VALUES ("PS30_3","020_30_3","PSA","30","3","3","Ya Ubangiji, ka dawo da ni daga kabari; ka kiyaye ni daga gangarawa zuwa cikin rami. ");
INSERT INTO hausa_vpl VALUES ("PS30_4","020_30_4","PSA","30","4","4","Ku rera ga Ubangiji, ku tsarkakansa; ku yabi sunansa mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("PS30_5","020_30_5","PSA","30","5","5","Gama fushinsa na ɗan lokaci ne amma alherinsa har matuƙa ne; mai yiwuwa a yi kuka da dare amma farin ciki kan zo da safe. ");
INSERT INTO hausa_vpl VALUES ("PS30_6","020_30_6","PSA","30","6","6","Sa’ad da nake lafiya, na ce, “Ba zan jijjigu ba.” ");
INSERT INTO hausa_vpl VALUES ("PS30_7","020_30_7","PSA","30","7","7","Ya Ubangiji, sa’ad da ka yi mini alheri, ka sa katangar dutsena ya tsaya daram; amma sa’ad da ka ɓoye fuskarka, sai in cika da tsoro. ");
INSERT INTO hausa_vpl VALUES ("PS30_8","020_30_8","PSA","30","8","8","A gare ka, ya Ubangiji, na yi kira; a gare ka Ubangiji na yi kukan neman jinƙai. ");
INSERT INTO hausa_vpl VALUES ("PS30_9","020_30_9","PSA","30","9","9","“Wace riba ce a hallakata, a kuma gangarawa ta zuwa cikin rami? Ƙura za tă yabe ka ne? Za tă iya yin shelar amincinka? ");
INSERT INTO hausa_vpl VALUES ("PS30_10","020_30_10","PSA","30","10","10","Ka ji, ya Ubangiji, ka kuwa yi mini jinƙai; Ya Ubangiji, ka zama taimakona.” ");
INSERT INTO hausa_vpl VALUES ("PS30_11","020_30_11","PSA","30","11","11","Ka mai da kukata ta zama rawa; ka tuɓe rigar makokina ka sa mini na farin ciki, ");
INSERT INTO hausa_vpl VALUES ("PS30_12","020_30_12","PSA","30","12","12","don zuciyata za tă iya rera gare ka ba kuwa za tă yi shiru ba. Ya Ubangiji Allahna, zan yi maka godiya har abada. ");
INSERT INTO hausa_vpl VALUES ("PS31_1","020_31_1","PSA","31","1","1","Don mai bi da kaɗe-kaɗe. Zabura ta Dawuda. A gare ka, ya Ubangiji, na nemi mafaka; kada ka bari in taɓa shan kunya; ka cece ni cikin rahamarka. ");
INSERT INTO hausa_vpl VALUES ("PS31_2","020_31_2","PSA","31","2","2","Ka juye kunnenka gare ni, ka zo da sauri ka cece ni; ka zama dutsen mafakata, mafaka mai ƙarfi na cetona. ");
INSERT INTO hausa_vpl VALUES ("PS31_3","020_31_3","PSA","31","3","3","Da yake kai ne dutsena da kuma kagarata, saboda sunanka ka bi da ni ka kuma jagorance ni. ");
INSERT INTO hausa_vpl VALUES ("PS31_4","020_31_4","PSA","31","4","4","Ka ’yantar da ni daga tarkon da aka sa mini, gama kai ne mafakata. ");
INSERT INTO hausa_vpl VALUES ("PS31_5","020_31_5","PSA","31","5","5","Cikin hannuwanka na miƙa ruhuna; ka cece ni, ya Ubangiji Allah na gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PS31_6","020_31_6","PSA","31","6","6","Na ƙi waɗanda suke manne wa gumakan banza; na dogara ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS31_7","020_31_7","PSA","31","7","7","Zan yi murna in kuma yi farin ciki a cikin ƙaunarka, gama ka ga azabata ka kuma san wahalar raina. ");
INSERT INTO hausa_vpl VALUES ("PS31_8","020_31_8","PSA","31","8","8","Ba ka ba da ni ga abokin gāba ba amma ka sa ƙafafuna a wuri mai sarari. ");
INSERT INTO hausa_vpl VALUES ("PS31_9","020_31_9","PSA","31","9","9","Ka yi mini jinƙai, ya Ubangiji, gama ina cikin damuwa; idanuna sun gaji da baƙin ciki, raina da jikina sun tafke tilis. ");
INSERT INTO hausa_vpl VALUES ("PS31_10","020_31_10","PSA","31","10","10","Baƙin ciki ya rufe raina shekaruna sun cika da nishi; ƙarfina ya karai saboda azaba, ƙasusuwana kuma sun gaji tiƙis. ");
INSERT INTO hausa_vpl VALUES ("PS31_11","020_31_11","PSA","31","11","11","Saboda dukan abokan gābana, Na zama tamƙar abin reni na maƙwabtana; na zama abin tsoro ga abokaina, waɗanda suka gan ni a titi sukan gudu daga gare ni. ");
INSERT INTO hausa_vpl VALUES ("PS31_12","020_31_12","PSA","31","12","12","An manta da ni sai ka ce na mutu; na zama kamar fasasshen kasko. ");
INSERT INTO hausa_vpl VALUES ("PS31_13","020_31_13","PSA","31","13","13","Gama nakan ji raɗe-raɗen mutane masu yawa; akwai tsoro a kowane gefe; suna ƙulla maƙarƙashiya a kaina suna shirya su ɗauke raina. ");
INSERT INTO hausa_vpl VALUES ("PS31_14","020_31_14","PSA","31","14","14","Amma na dogara gare ka, ya Ubangiji; na ce, “Kai ne Allahna.” ");
INSERT INTO hausa_vpl VALUES ("PS31_15","020_31_15","PSA","31","15","15","Lokutana suna a hannuwanka; ka cece ni daga abokan gābana da kuma daga waɗanda suke fafara ta. ");
INSERT INTO hausa_vpl VALUES ("PS31_16","020_31_16","PSA","31","16","16","Bari fuskarka ta haskaka a kan bawanka; ka cece ni da ƙaunarka marar ƙarewa. ");
INSERT INTO hausa_vpl VALUES ("PS31_17","020_31_17","PSA","31","17","17","Kada ka bari in sha kunya, ya Ubangiji, gama na yi kuka gare ka; amma bari mugaye su sha kunya su kuma kwanta shiru a cikin kabari. ");
INSERT INTO hausa_vpl VALUES ("PS31_18","020_31_18","PSA","31","18","18","Bari a rufe leɓunan ƙarairayinsu, gama da fariya da reni suna magana da girman kai a kan adalai. ");
INSERT INTO hausa_vpl VALUES ("PS31_19","020_31_19","PSA","31","19","19","Alherinka da girma yake, wanda ka ajiye domin waɗanda suke tsoronka, wanda ka mayar a gaban mutane a kan waɗanda suke neman mafaka daga gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS31_20","020_31_20","PSA","31","20","20","Cikin inuwar kasancewarka ka ɓoye su daga makircin mutane; a wurin zamanka ka kiyaye su lafiya daga harsuna masu zagi. ");
INSERT INTO hausa_vpl VALUES ("PS31_21","020_31_21","PSA","31","21","21","Yabo ya tabbata ga Ubangiji, gama ya nuna ƙaunarsa mai banmamaki gare ni sa’ad da aka yi mini kwanto kewaye da birni. ");
INSERT INTO hausa_vpl VALUES ("PS31_22","020_31_22","PSA","31","22","22","Cikin tsorona na ce, “An yanke ni daga gabanka!” Duk da haka ka ji kukata na neman jinƙai sa’ad da na kira gare ka don taimako. ");
INSERT INTO hausa_vpl VALUES ("PS31_23","020_31_23","PSA","31","23","23","Ku ƙaunaci Ubangiji, dukanku tsarkakansa! Ubangiji yakan adana amintattu, amma masu girman kai yakan sāka musu cikakke. ");
INSERT INTO hausa_vpl VALUES ("PS31_24","020_31_24","PSA","31","24","24","Ku yi ƙarfin hali ku kuma ƙarfafa, dukanku masu sa bege a kan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS32_1","020_32_1","PSA","32","1","1","Ta Dawuda. Maskil ne. Mai farin ciki ne shi wanda aka gafarta masa laifofinsa, wanda aka shafe zunubansa. ");
INSERT INTO hausa_vpl VALUES ("PS32_2","020_32_2","PSA","32","2","2","Mai farin ciki ne mutumin da Ubangiji ba ya lissafin zunubinsa a kansa wanda kuma babu ruɗu a ruhunsa. ");
INSERT INTO hausa_vpl VALUES ("PS32_3","020_32_3","PSA","32","3","3","Sa’ad da na yi shiru, ƙasusuwana sun yi ta mutuwa cikin nishina dukan yini. ");
INSERT INTO hausa_vpl VALUES ("PS32_4","020_32_4","PSA","32","4","4","Gama dare da rana hannunka yana da nauyi a kaina; an shanye ƙarfina ƙaf sai ka ce a zafin bazara. Sela ");
INSERT INTO hausa_vpl VALUES ("PS32_5","020_32_5","PSA","32","5","5","Sa’an nan na furta zunubina a gare ka ban kuwa ɓoye laifina ba. Na ce, “Zan furta laifofina ga Ubangiji.” Ka kuwa gafarta laifin zunubina. Sela ");
INSERT INTO hausa_vpl VALUES ("PS32_6","020_32_6","PSA","32","6","6","Saboda haka bari duk mai tsoron Allah yă yi addu’a gare ka yayinda kake samuwa; tabbatacce sa’ad da manyan ruwaye suka taso, ba za su kai wurinsa ba. ");
INSERT INTO hausa_vpl VALUES ("PS32_7","020_32_7","PSA","32","7","7","Kai ne wurin ɓuyata; za ka tsare ni daga wahala ka kewaye ni da waƙoƙin ceto. Sela ");
INSERT INTO hausa_vpl VALUES ("PS32_8","020_32_8","PSA","32","8","8","Zan umarce ka in kuma koyar da kai a hanyar da za ka bi; Zan ba ka shawara in kuma lura da kai. ");
INSERT INTO hausa_vpl VALUES ("PS32_9","020_32_9","PSA","32","9","9","Kada ka zama kamar doki ko doki, wanda ba su da azanci wanda dole sai an bi da su da linzami da ragama in ba haka ba, ba za su zo wurinka ba. ");
INSERT INTO hausa_vpl VALUES ("PS32_10","020_32_10","PSA","32","10","10","Azaban mugu da yawa suke, amma ƙaunar Ubangiji marar ƙarewa kan kewaye mutumin da ya dogara gare shi. ");
INSERT INTO hausa_vpl VALUES ("PS32_11","020_32_11","PSA","32","11","11","Ku yi farin ciki a cikin Ubangiji ku kuma yi murna, ku adalai; ku rera, dukanku waɗanda zuciyarku take daidai! ");
INSERT INTO hausa_vpl VALUES ("PS33_1","020_33_1","PSA","33","1","1","Ku rera da farin ciki ga Ubangiji ku adalai; daidai ne masu gaskiya su yabe shi. ");
INSERT INTO hausa_vpl VALUES ("PS33_2","020_33_2","PSA","33","2","2","Ku yabi Ubangiji da garaya; ku yi kiɗi gare shi da molo mai tsirkiya goma. ");
INSERT INTO hausa_vpl VALUES ("PS33_3","020_33_3","PSA","33","3","3","Ku rera masa sabuwar waƙa; ku yi kiɗi da gwaninta, ku kuma yi sowa don farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS33_4","020_33_4","PSA","33","4","4","Gama maganar Ubangiji daidai ne da kuma gaskiya; yana da aminci cikin kome da yake yi. ");
INSERT INTO hausa_vpl VALUES ("PS33_5","020_33_5","PSA","33","5","5","Ubangiji yana ƙaunar adalci duniya ta cika da ƙaunarsa marar ƙarewa. ");
INSERT INTO hausa_vpl VALUES ("PS33_6","020_33_6","PSA","33","6","6","Ta wurin maganar Ubangiji aka yi sammai, rundunar taurarinsu kuwa da numfashin bakinsa. ");
INSERT INTO hausa_vpl VALUES ("PS33_7","020_33_7","PSA","33","7","7","Ya tattara ruwan teku cikin tuluna; ya sa zurfafa cikin gidajen ajiya. ");
INSERT INTO hausa_vpl VALUES ("PS33_8","020_33_8","PSA","33","8","8","Bari dukan duniya ta ji tsoron Ubangiji; bari dukan mutanen duniya su girmama shi. ");
INSERT INTO hausa_vpl VALUES ("PS33_9","020_33_9","PSA","33","9","9","Gama ya yi magana, abu ya kuwa kasance; ya umarta, ya kuwa tsaya daram. ");
INSERT INTO hausa_vpl VALUES ("PS33_10","020_33_10","PSA","33","10","10","Ubangiji yakan soke shirye-shiryen al’ummai; yakan wofintar da manufofin mutane. ");
INSERT INTO hausa_vpl VALUES ("PS33_11","020_33_11","PSA","33","11","11","Amma shirye-shiryen Ubangiji kan tsaya daram har abada, manufofin zuciyarsa kuwa har dukan zamanai. ");
INSERT INTO hausa_vpl VALUES ("PS33_12","020_33_12","PSA","33","12","12","Mai farin ciki ce al’ummar da Allah ne Ubangijinta, mutanen da ya zaɓa don gādonsa. ");
INSERT INTO hausa_vpl VALUES ("PS33_13","020_33_13","PSA","33","13","13","Daga sama Ubangiji ya duba ya kuwa ga dukan ’yan adam; ");
INSERT INTO hausa_vpl VALUES ("PS33_14","020_33_14","PSA","33","14","14","daga mazauninsa yana lura da dukan waɗanda suke zama a duniya, ");
INSERT INTO hausa_vpl VALUES ("PS33_15","020_33_15","PSA","33","15","15","shi da ya yi zukatan duka, wanda yake kula da kome da suke yi. ");
INSERT INTO hausa_vpl VALUES ("PS33_16","020_33_16","PSA","33","16","16","Babu sarkin da ake ceto ta wurin yawan mayaƙansa; ba jarumin da kan kuɓuta ta wurin yawan ƙarfinsa. ");
INSERT INTO hausa_vpl VALUES ("PS33_17","020_33_17","PSA","33","17","17","Dogara a kan doki don ceto banza ne; duk da yawan ƙarfinsa ba ya ceto. ");
INSERT INTO hausa_vpl VALUES ("PS33_18","020_33_18","PSA","33","18","18","Amma idanun Ubangiji suna a kan wanda yake tsoronsa, a kan waɗanda suke sa zuciya cikin ƙaunarsa marar ƙarewa, ");
INSERT INTO hausa_vpl VALUES ("PS33_19","020_33_19","PSA","33","19","19","don yă cece su daga mutuwa ya bar su da rai a lokacin yunwa. ");
INSERT INTO hausa_vpl VALUES ("PS33_20","020_33_20","PSA","33","20","20","Muna jiran Ubangiji da bege; shi ne taimakonmu da garkuwarmu. ");
INSERT INTO hausa_vpl VALUES ("PS33_21","020_33_21","PSA","33","21","21","A cikinsa zukatanmu na farin ciki, gama mun dogara cikin sunansa mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("PS33_22","020_33_22","PSA","33","22","22","Bari ƙaunarka marar ƙarewa ta zauna a kanmu, ya Ubangiji, ko ma da muke sa begenmu a gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS34_1","020_34_1","PSA","34","1","1","Ta Dawuda. Sa’ad da ya yi kamar ya haukace a gaban Abimelek, Wanda ya kore shi, ya kuwa tafi. Zan gode wa Ubangiji kullayaumi; yabonsa kullum za su kasance a leɓunana. ");
INSERT INTO hausa_vpl VALUES ("PS34_2","020_34_2","PSA","34","2","2","Raina zai yi fariya a cikin Ubangiji; bari waɗanda suke wahala su ji su kuma yi farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS34_3","020_34_3","PSA","34","3","3","Ku ɗaukaka Ubangiji tare da ni; bari mu ɗaukaka sunansa tare. ");
INSERT INTO hausa_vpl VALUES ("PS34_4","020_34_4","PSA","34","4","4","Na nemi Ubangiji, ya kuwa amsa mini; ya cece ni daga dukan tsoro. ");
INSERT INTO hausa_vpl VALUES ("PS34_5","020_34_5","PSA","34","5","5","Waɗanda suke dubansa sukan haskaka; fuskokinsu ba sa rufuwa da kunya. ");
INSERT INTO hausa_vpl VALUES ("PS34_6","020_34_6","PSA","34","6","6","Wannan matalauci ya yi kira, Ubangiji kuwa ya ji shi; ya cece shi daga dukan wahalarsa. ");
INSERT INTO hausa_vpl VALUES ("PS34_7","020_34_7","PSA","34","7","7","Mala’ikan Ubangiji ya kafa sansani kewaye da waɗanda suke tsoronsa, ya kuwa cece su. ");
INSERT INTO hausa_vpl VALUES ("PS34_8","020_34_8","PSA","34","8","8","Ku gwada ku gani cewa Ubangiji yana da kyau; mai albarka ne mutumin da yake neman mafaka a gare shi. ");
INSERT INTO hausa_vpl VALUES ("PS34_9","020_34_9","PSA","34","9","9","Ku ji tsoron Ubangiji, ku tsarkakansa, gama masu tsoronsa ba sa rasa kome. ");
INSERT INTO hausa_vpl VALUES ("PS34_10","020_34_10","PSA","34","10","10","Zakoki za su iya rasa ƙarfi su kuma ji yunwa, amma waɗanda suke neman Ubangiji ba sa rasa abu mai kyau. ");
INSERT INTO hausa_vpl VALUES ("PS34_11","020_34_11","PSA","34","11","11","Ku zo, ’ya’yana, ku saurare ni; zan koya muku tsoron Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS34_12","020_34_12","PSA","34","12","12","Duk waninku da yake ƙaunar rayuwa yana kuma so yă ga kwanaki masu kyau, ");
INSERT INTO hausa_vpl VALUES ("PS34_13","020_34_13","PSA","34","13","13","ka kiyaye harshenka daga mugunta da kuma leɓunanku daga faɗar ƙarairayi. ");
INSERT INTO hausa_vpl VALUES ("PS34_14","020_34_14","PSA","34","14","14","Juyo daga mugunta ku yi alheri; nemi salama ku kuma yi ƙoƙarin samunta. ");
INSERT INTO hausa_vpl VALUES ("PS34_15","020_34_15","PSA","34","15","15","Idanun Ubangiji suna a kan masu adalci kuma kunnuwansa suna sauraran kukansu; ");
INSERT INTO hausa_vpl VALUES ("PS34_16","020_34_16","PSA","34","16","16","fuskar Ubangiji yana gāba da waɗanda suke aikata mugunta, don yă sa a manta da su a duniya. ");
INSERT INTO hausa_vpl VALUES ("PS34_17","020_34_17","PSA","34","17","17","Adalai kan yi kuka, Ubangiji kuwa yakan ji su; yakan cece su daga dukan wahalarsu. ");
INSERT INTO hausa_vpl VALUES ("PS34_18","020_34_18","PSA","34","18","18","Ubangiji yana kusa da waɗanda suka karai ya kuma cece waɗanda aka ragargaza a ruhu. ");
INSERT INTO hausa_vpl VALUES ("PS34_19","020_34_19","PSA","34","19","19","Adali zai iya kasance da wahala da yawa, amma Ubangiji yakan cece shi daga dukansu; ");
INSERT INTO hausa_vpl VALUES ("PS34_20","020_34_20","PSA","34","20","20","yakan tsare dukan ƙasusuwansa, ba ko ɗayansu da zai karye. ");
INSERT INTO hausa_vpl VALUES ("PS34_21","020_34_21","PSA","34","21","21","Mugunta zai kashe mugu; za a hukunta abokan gāban adalai. ");
INSERT INTO hausa_vpl VALUES ("PS34_22","020_34_22","PSA","34","22","22","Ubangiji yakan cece bayinsa; ba wanda yake neman mafaka a wurinsa da za a hukunta. ");
INSERT INTO hausa_vpl VALUES ("PS35_1","020_35_1","PSA","35","1","1","Ta Dawuda. Yi hamayya, ya Ubangiji, da waɗanda suke hamayya da ni; yi faɗa da waɗanda suke faɗa da ni. ");
INSERT INTO hausa_vpl VALUES ("PS35_2","020_35_2","PSA","35","2","2","Ka ɗauki garkuwa da kuma makami; ka tashi ka taimake ni. ");
INSERT INTO hausa_vpl VALUES ("PS35_3","020_35_3","PSA","35","3","3","Ka ɗaga māshi da kuma abin da ake jefa a kan waɗanda suke fafarata. Ka ce wa raina, “Ni ne cetonka.” ");
INSERT INTO hausa_vpl VALUES ("PS35_4","020_35_4","PSA","35","4","4","Bari waɗanda suke neman raina su sha kunya a kuma kunyatar da su; bari waɗanda suke shirya lalacewata su juya da baya su ruɗe. ");
INSERT INTO hausa_vpl VALUES ("PS35_5","020_35_5","PSA","35","5","5","Bari su zama kamar yayi a gaban iska, mala’ikan Ubangiji kuma yana korarsu; ");
INSERT INTO hausa_vpl VALUES ("PS35_6","020_35_6","PSA","35","6","6","bari hanyarsu tă yi duhu ta kuma yi santsi, mala’ikan Ubangiji kuma yana fafararsu. ");
INSERT INTO hausa_vpl VALUES ("PS35_7","020_35_7","PSA","35","7","7","Da yake sun ɓoye tarko domina ba dalili kuma babu dalili suka haƙa mini rami, ");
INSERT INTO hausa_vpl VALUES ("PS35_8","020_35_8","PSA","35","8","8","bari lalaci yă kama su ba zato, bari tarkon da suka ɓoye yă kama su, bari su fāɗa cikin ramin, yă kai ga lalacinsu. ");
INSERT INTO hausa_vpl VALUES ("PS35_9","020_35_9","PSA","35","9","9","Sa’an nan raina zai cika da farin ciki a cikin Ubangiji in yi kuma murna a cikin cetonsa. ");
INSERT INTO hausa_vpl VALUES ("PS35_10","020_35_10","PSA","35","10","10","Dukan raina zai ce, “Wane ne kamar ka, ya Ubangiji? Ka kuɓutar da matalauta daga waɗanda suka fi ƙarfinsu, matalauta da masu bukata daga waɗanda suke musu fashi.” ");
INSERT INTO hausa_vpl VALUES ("PS35_11","020_35_11","PSA","35","11","11","Shaidu marasa imani sun fito; suna mini tambaya a kan abubuwan da ban san kome a kai ba. ");
INSERT INTO hausa_vpl VALUES ("PS35_12","020_35_12","PSA","35","12","12","Suna sāka alherin da na yi musu da mugunta suka bar raina da nadama. ");
INSERT INTO hausa_vpl VALUES ("PS35_13","020_35_13","PSA","35","13","13","Duk da haka sa’ad da suke ciwo, na sanya rigar makoki na ƙasƙantar da kaina da azumi. Sa’ad da aka mayar mini da addu’o’i babu amsa, ");
INSERT INTO hausa_vpl VALUES ("PS35_14","020_35_14","PSA","35","14","14","nakan yi ta yawo ina makoki sai ka ce yadda nake yi wa abokina ko ɗan’uwana. Nakan sunkuyar da kaina cikin baƙin ciki sai ka ce ina kuka domin mahaifiyata. ");
INSERT INTO hausa_vpl VALUES ("PS35_15","020_35_15","PSA","35","15","15","Amma sa’ad da na yi tuntuɓe, sukan taru suna murna; masu kai hari sun taru a kaina sa’ad da ban sani ba. Suna ɓata mini suna ba tsagaitawa. ");
INSERT INTO hausa_vpl VALUES ("PS35_16","020_35_16","PSA","35","16","16","Kamar marasa sani Allah suna mini riyar ba’a; Suna hararata da ƙiyayya. ");
INSERT INTO hausa_vpl VALUES ("PS35_17","020_35_17","PSA","35","17","17","Ya Ubangiji, har yaushe za ka ci gaba da zuba ido kawai? Ka kuɓutar da raina daga farmakinsu, raina mai daraja daga waɗannan zakoki. ");
INSERT INTO hausa_vpl VALUES ("PS35_18","020_35_18","PSA","35","18","18","Zan yi godiya cikin taro mai girma; cikin ɗumbun mutane zan yabe ka. ");
INSERT INTO hausa_vpl VALUES ("PS35_19","020_35_19","PSA","35","19","19","Kada ka bar maƙaryatan nan, su yi farin ciki a kaina; kada ka bar waɗanda suke ƙina ba dalili, su ji daɗin baƙin cikina. ");
INSERT INTO hausa_vpl VALUES ("PS35_20","020_35_20","PSA","35","20","20","Ba sa maganar salama sukan ƙirƙiro zage-zagen ƙarya a kan waɗanda suka zama shiru a ƙasar. ");
INSERT INTO hausa_vpl VALUES ("PS35_21","020_35_21","PSA","35","21","21","Sukan wage mini bakinsu suna cewa, “Allah yă ƙara! Da idanunmu mun gani.” ");
INSERT INTO hausa_vpl VALUES ("PS35_22","020_35_22","PSA","35","22","22","Ya Ubangiji, ka ga wannan; kada ka yi shiru. Kada ka yi nisa da ni, ya Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS35_23","020_35_23","PSA","35","23","23","Ka farka, ka kuma tashi ka kāre ni! Ka yi mini faɗa, ya Allahna da shugabana. ");
INSERT INTO hausa_vpl VALUES ("PS35_24","020_35_24","PSA","35","24","24","Ka nuna ni marar laifi ne ciki adalcinka, Ya Ubangiji Allahna; kada ka bari su yi farin ciki a kaina. ");
INSERT INTO hausa_vpl VALUES ("PS35_25","020_35_25","PSA","35","25","25","Kada ka bari su ce wa kansu, “Allah yă ƙara, dā ma abin da mun so ke nan!” Ko su ce, “Mun haɗiye shi.” ");
INSERT INTO hausa_vpl VALUES ("PS35_26","020_35_26","PSA","35","26","26","Bari dukan waɗanda suke farin ciki a kaina a wahalata su sha kunya su kuma ruɗe; bari dukan waɗanda suke ɗaukar kansu sun fi ni su sha kunya da wulaƙanci. ");
INSERT INTO hausa_vpl VALUES ("PS35_27","020_35_27","PSA","35","27","27","Bari waɗanda suke murna saboda nasarata su yi sowa don farin ciki da murna; bari kullum su riƙa cewa, “A ɗaukaka Ubangiji, wanda yake farin ciki da zaman lafiyar bawansa.” ");
INSERT INTO hausa_vpl VALUES ("PS35_28","020_35_28","PSA","35","28","28","Harshena zai yi zancen adalcinka da kuma yabonka dukan yini. ");
INSERT INTO hausa_vpl VALUES ("PS36_1","020_36_1","PSA","36","1","1","Don mai bi da kaɗe-kaɗe. Ta Dawuda bawan Ubangiji. Akwai magana a cikin zuciyata game da zunubin mugu. Babu tsoron Allah a idanunsa. ");
INSERT INTO hausa_vpl VALUES ("PS36_2","020_36_2","PSA","36","2","2","Gama a idanunsa yana ganin kansa wani abu ne wanda ya sha ƙarfi a gane ko ya ƙi zunubinsa. ");
INSERT INTO hausa_vpl VALUES ("PS36_3","020_36_3","PSA","36","3","3","Kalmomin bakinsa mugaye ne da kuma ruɗu; ya daina zama mai hikima da yin alheri. ");
INSERT INTO hausa_vpl VALUES ("PS36_4","020_36_4","PSA","36","4","4","Ko a kan gadonsa ma yana shirya mugunta; yakan sa kansa ga aikata zunubi kuma ba ya ƙin abin da ba shi da kyau. ");
INSERT INTO hausa_vpl VALUES ("PS36_5","020_36_5","PSA","36","5","5","Ƙaunarka, ya Ubangiji, kan kai sammai, amincinka har sararin sammai. ");
INSERT INTO hausa_vpl VALUES ("PS36_6","020_36_6","PSA","36","6","6","Adalcinka yana kama da manyan duwatsu, hukuncinka kamar zurfi mai girma. Ya Ubangiji, kana lura da mutum da dabba. ");
INSERT INTO hausa_vpl VALUES ("PS36_7","020_36_7","PSA","36","7","7","Ina misalin ƙaunarka marar ƙarewa! Mutane manya da ƙanana kan sami mafaka cikin inuwar fikafikanka. ");
INSERT INTO hausa_vpl VALUES ("PS36_8","020_36_8","PSA","36","8","8","Suna biki a yalwar gidanka; kakan ba su sha daga rafin farin cikinka. ");
INSERT INTO hausa_vpl VALUES ("PS36_9","020_36_9","PSA","36","9","9","Gama a gare ka akwai maɓulɓular rai cikin haskenka mukan ga haske. ");
INSERT INTO hausa_vpl VALUES ("PS36_10","020_36_10","PSA","36","10","10","Ka ci gaba da ƙaunarka ga waɗanda suka san ka, adalcinka ga masu gaskiyar zuciya. ");
INSERT INTO hausa_vpl VALUES ("PS36_11","020_36_11","PSA","36","11","11","Kada ka bari ƙafar mai girman kai yă fāɗa mini, ko hannun mugu ya kore ni. ");
INSERT INTO hausa_vpl VALUES ("PS36_12","020_36_12","PSA","36","12","12","Dubi yadda masu aikata zunubi suka fāɗi, a zube, ba za su kuwa iya tashi ba! ");
INSERT INTO hausa_vpl VALUES ("PS37_1","020_37_1","PSA","37","1","1","Ta Dawuda. Kada ka tsorata saboda mugayen mutane ko ka yi kishin waɗanda suka aikata mugunta; ");
INSERT INTO hausa_vpl VALUES ("PS37_2","020_37_2","PSA","37","2","2","gama kamar ciyawa za su bushe, kamar ɗanyun ganyaye za su mutu. ");
INSERT INTO hausa_vpl VALUES ("PS37_3","020_37_3","PSA","37","3","3","Ka dogara ga Ubangiji ka kuma aikata alheri; yi zama cikin ƙasar ka kuma more makiyaya mai lafiya. ");
INSERT INTO hausa_vpl VALUES ("PS37_4","020_37_4","PSA","37","4","4","Ka ji daɗinka a cikin Ubangiji zai kuwa biya bukatun zuciyarka. ");
INSERT INTO hausa_vpl VALUES ("PS37_5","020_37_5","PSA","37","5","5","Ka sa kanka a hanyar Ubangiji; ka kuma dogara gare shi zai kuwa yi wannan. ");
INSERT INTO hausa_vpl VALUES ("PS37_6","020_37_6","PSA","37","6","6","Zai sa adalcinka yă haskaka kamar hasken safiya, gaskiyarka kuma kamar rana a tsaka. ");
INSERT INTO hausa_vpl VALUES ("PS37_7","020_37_7","PSA","37","7","7","Ka natsu a gaban Ubangiji ka kuma jira da haƙuri gare shi; kada ka tsorata sa’ad da mutane ke nasara a hanyoyinsu, sa’ad da suke aikata mugayen shirye-shiryensu. ");
INSERT INTO hausa_vpl VALUES ("PS37_8","020_37_8","PSA","37","8","8","Kada ka yi fushi kada kuma ka yi hasala; kada ka tsorata, wannan yakan kai ga mugunta ne kawai. ");
INSERT INTO hausa_vpl VALUES ("PS37_9","020_37_9","PSA","37","9","9","Gama za a datse mugayen mutane, amma waɗanda suke sa zuciya ga Ubangiji za su gāji ƙasar. ");
INSERT INTO hausa_vpl VALUES ("PS37_10","020_37_10","PSA","37","10","10","A ɗan ƙanƙanen lokaci, mugaye za su shuɗe; ko ka neme su, ba za a same su ba. ");
INSERT INTO hausa_vpl VALUES ("PS37_11","020_37_11","PSA","37","11","11","Amma masu tawali’u za su gāji ƙasar su kuma zauna da cikakkiyar salama. ");
INSERT INTO hausa_vpl VALUES ("PS37_12","020_37_12","PSA","37","12","12","Mugaye sukan shirya wa adalai maƙarƙashiya su ciji baki a kansu; ");
INSERT INTO hausa_vpl VALUES ("PS37_13","020_37_13","PSA","37","13","13","amma Ubangiji yakan yi dariyar mugaye, gama ya sani ranarsu tana zuwa. ");
INSERT INTO hausa_vpl VALUES ("PS37_14","020_37_14","PSA","37","14","14","Mugaye sukan zare takobi su ja baka don su kashe matalauta da masu bukata, don su kashe waɗanda hanyoyinsu daidai suke. ");
INSERT INTO hausa_vpl VALUES ("PS37_15","020_37_15","PSA","37","15","15","Amma takubansu za su soki zukatansu, kuma bakkunansu za su kakkarye. ");
INSERT INTO hausa_vpl VALUES ("PS37_16","020_37_16","PSA","37","16","16","Ƙanƙanen abin da mai adalci yake da shi ya fi arzikin mugaye yawa; ");
INSERT INTO hausa_vpl VALUES ("PS37_17","020_37_17","PSA","37","17","17","gama za a kakkarya ikon mugaye, amma Ubangiji zai riƙe mai adalci. ");
INSERT INTO hausa_vpl VALUES ("PS37_18","020_37_18","PSA","37","18","18","Kwanakin marasa zarge suna sane ga Ubangiji, kuma gādonsu zai dawwama har abada. ");
INSERT INTO hausa_vpl VALUES ("PS37_19","020_37_19","PSA","37","19","19","A lokutan masifu ba za su yanƙwane ba; a kwanakin yunwa za su sami a yalwace. ");
INSERT INTO hausa_vpl VALUES ("PS37_20","020_37_20","PSA","37","20","20","Amma mugaye za su hallaka, Abokan gāban Ubangiji za su zama kamar kyan gonaki, za su ɓace, za su ɓace kamar hayaƙi. ");
INSERT INTO hausa_vpl VALUES ("PS37_21","020_37_21","PSA","37","21","21","Mugaye kan yi rance ba sa kuma biya, amma masu adalci suna bayar hannu sake; ");
INSERT INTO hausa_vpl VALUES ("PS37_22","020_37_22","PSA","37","22","22","waɗanda Ubangiji ya sa wa albarka za su gāji ƙasar, amma waɗanda ya la’anta, za a kore su. ");
INSERT INTO hausa_vpl VALUES ("PS37_23","020_37_23","PSA","37","23","23","In Ubangiji ya ji daɗin hanyar da mutum yake bi, zai sa sawu su kahu; ");
INSERT INTO hausa_vpl VALUES ("PS37_24","020_37_24","PSA","37","24","24","ko ya yi tuntuɓe, ba zai fāɗi ba, gama Ubangiji yakan riƙe shi da hannunsa. ");
INSERT INTO hausa_vpl VALUES ("PS37_25","020_37_25","PSA","37","25","25","Dā ni yaro ne amma yanzu na tsufa, duk da haka ban taɓa ganin an yashe masu adalci ba ko a ce ’ya’yansu suna roƙon burodi. ");
INSERT INTO hausa_vpl VALUES ("PS37_26","020_37_26","PSA","37","26","26","Kullum suna bayar hannu sake suna kuma ba da bashi ba da wahala ba, za a yi wa ’ya’yansu albarka. ");
INSERT INTO hausa_vpl VALUES ("PS37_27","020_37_27","PSA","37","27","27","Ku juyo daga mugunta ku yi alheri; sa’an nan za ku zauna a ƙasar har abada. ");
INSERT INTO hausa_vpl VALUES ("PS37_28","020_37_28","PSA","37","28","28","Gama Ubangiji yana ƙaunar masu aikata daidai kuma ba zai yashe amintattunsa ba. Za a hallaka masu aikata mugunta gaba ɗaya, ’ya’yan mugaye za su hallaka. ");
INSERT INTO hausa_vpl VALUES ("PS37_29","020_37_29","PSA","37","29","29","Masu adalci za su gāji ƙasar su kuma zauna a cikinta har abada. ");
INSERT INTO hausa_vpl VALUES ("PS37_30","020_37_30","PSA","37","30","30","Bakin mutum mai adalci yakan yi magana da hikima, harshensa kuwa yakan yi maganar abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("PS37_31","020_37_31","PSA","37","31","31","Dokar Allahnsa tana a cikin zuciyarsa; ƙafafunsa ba sa santsi. ");
INSERT INTO hausa_vpl VALUES ("PS37_32","020_37_32","PSA","37","32","32","Mugaye suna fako suna jira masu adalci, suna ƙoƙari neman ransu; ");
INSERT INTO hausa_vpl VALUES ("PS37_33","020_37_33","PSA","37","33","33","amma Ubangiji ba zai bar su a ikonsu ba ko ya bari a hukunta su sa’ad da aka kawo su shari’a ba. ");
INSERT INTO hausa_vpl VALUES ("PS37_34","020_37_34","PSA","37","34","34","Ku sa zuciya ga Ubangiji ku kuma kiyaye hanyarsa. Zai ɗaukaka ku ku ci gādon ƙasar, sa’ad da aka kawar da mugaye, za ka gani. ");
INSERT INTO hausa_vpl VALUES ("PS37_35","020_37_35","PSA","37","35","35","Na ga wani mugu, azzalumi, yana yaɗuwa kamar ɗanyen itace a asalin ƙasarsa, ");
INSERT INTO hausa_vpl VALUES ("PS37_36","020_37_36","PSA","37","36","36","amma yakan mutu nan da nan kuma ba ya ƙara kasancewa; ko an neme shi, ba za a same shi ba. ");
INSERT INTO hausa_vpl VALUES ("PS37_37","020_37_37","PSA","37","37","37","Ka dubi marasa zargi, ka lura da adali; akwai sa zuciya domin mutum mai salama. ");
INSERT INTO hausa_vpl VALUES ("PS37_38","020_37_38","PSA","37","38","38","Amma za a hallaka dukan masu zunubi; za a yanke sa zuciya ta mugaye. ");
INSERT INTO hausa_vpl VALUES ("PS37_39","020_37_39","PSA","37","39","39","Ceton adalai kan zo daga Ubangiji; shi ne mafaka a lokacin wahala. ");
INSERT INTO hausa_vpl VALUES ("PS37_40","020_37_40","PSA","37","40","40","Ubangiji yakan taimake su yă kuma cece su; yakan kuɓutar da su daga mugaye yă kuma cece su, domin sukan nemi mafaka daga gare shi. ");
INSERT INTO hausa_vpl VALUES ("PS38_1","020_38_1","PSA","38","1","1","Zabura ta Dawuda. Roƙo ne. Ya Ubangiji, kada ka tsawata mini cikin fushinka ko ka hore ni cikin hasalarka. ");
INSERT INTO hausa_vpl VALUES ("PS38_2","020_38_2","PSA","38","2","2","Gama kibiyoyinka sun soke ni, hannunka kuma ya fāɗo a kaina. ");
INSERT INTO hausa_vpl VALUES ("PS38_3","020_38_3","PSA","38","3","3","Saboda hasalarka babu lafiya a jikina; ƙasusuwana ba lafiya saboda zunubina. ");
INSERT INTO hausa_vpl VALUES ("PS38_4","020_38_4","PSA","38","4","4","Laifofina sun mamaye ni kamar nauyin da ya sha ƙarfin ɗauka. ");
INSERT INTO hausa_vpl VALUES ("PS38_5","020_38_5","PSA","38","5","5","Miyakuna sun ruɓe suna kuma wari saboda wawancina na zunubi. ");
INSERT INTO hausa_vpl VALUES ("PS38_6","020_38_6","PSA","38","6","6","An tanƙware ni aka kuma ƙasƙantar da ni; dukan yini ina ta kuka. ");
INSERT INTO hausa_vpl VALUES ("PS38_7","020_38_7","PSA","38","7","7","Bayana yana fama da zazzaɓi; babu lafiya a jikina. ");
INSERT INTO hausa_vpl VALUES ("PS38_8","020_38_8","PSA","38","8","8","Na gaji sharkaf an kuma ragargaza ni; ina nishi da wahala a cikin zuciyata. ");
INSERT INTO hausa_vpl VALUES ("PS38_9","020_38_9","PSA","38","9","9","Dukan bukatata tana a shimfiɗe a gabanka, ya Ubangiji; ajiyar zuciyata ba ta ɓoyuwa daga gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS38_10","020_38_10","PSA","38","10","10","Zuciyata na bugu, ƙarfina kuma ya ƙare, har ma haske ya rabu da idanuna. ");
INSERT INTO hausa_vpl VALUES ("PS38_11","020_38_11","PSA","38","11","11","Abokaina da maƙwabtana sun guje ni saboda miyakuna; maƙwabtana ba sa zuwa kusa. ");
INSERT INTO hausa_vpl VALUES ("PS38_12","020_38_12","PSA","38","12","12","Waɗanda suke neman raina sun sa tarkonsu, waɗanda suke so su cuce ni suna zance lalatar da ni; yini sukutum suna ƙulla mini maƙarƙashiya. ");
INSERT INTO hausa_vpl VALUES ("PS38_13","020_38_13","PSA","38","13","13","Ni kamar kurma ne, wanda ba ya ji, kamar bebe, wanda ba ya iya buɗe bakinsa. ");
INSERT INTO hausa_vpl VALUES ("PS38_14","020_38_14","PSA","38","14","14","Na zama kamar mutumin da ba ya ji, wanda bakinsa ba ya iya ba da amsa. ");
INSERT INTO hausa_vpl VALUES ("PS38_15","020_38_15","PSA","38","15","15","Na dogara gare ka, ya Ubangiji; za ka amsa, ya Ubangiji Allahna. ");
INSERT INTO hausa_vpl VALUES ("PS38_16","020_38_16","PSA","38","16","16","Gama na ce, “Kada ka bar su su yi farin ciki a kaina ko su yi kirari a kaina sa’ad da ƙafata ta yi santsi.” ");
INSERT INTO hausa_vpl VALUES ("PS38_17","020_38_17","PSA","38","17","17","Gama ina gab da fāɗuwa, kuma cikin azaba nake kullum. ");
INSERT INTO hausa_vpl VALUES ("PS38_18","020_38_18","PSA","38","18","18","Na furta laifina; na damu da zunubina. ");
INSERT INTO hausa_vpl VALUES ("PS38_19","020_38_19","PSA","38","19","19","Da yawa ne masu gāba da ni da ƙarfi; waɗanda suke kina ba dalili sun yi yawa. ");
INSERT INTO hausa_vpl VALUES ("PS38_20","020_38_20","PSA","38","20","20","Waɗanda suke sāka alherina da mugunta, suna cin zarafina sa’ad da nake bin abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("PS38_21","020_38_21","PSA","38","21","21","Ya Ubangiji, kada ka yashe ni; kada ka yi nesa da ni, ya Allahna. ");
INSERT INTO hausa_vpl VALUES ("PS38_22","020_38_22","PSA","38","22","22","Zo da sauri ka taimake ni, Ya Ubangiji Mai Cetona. ");
INSERT INTO hausa_vpl VALUES ("PS39_1","020_39_1","PSA","39","1","1","Don mai bi da kaɗe-kaɗe. Don Yedutun. Zabura ta Dawuda. Na ce, “Zan lura da hanyoyina zan kuma kiyaye harshena daga zunubi; zan sa linzami a bakina muddin mugaye suna a gabana.” ");
INSERT INTO hausa_vpl VALUES ("PS39_2","020_39_2","PSA","39","2","2","Na yi shiru, ban ce kome ba, Ko a kan abin da yake da kyau! Amma duk da haka wahalata sai ƙaruwa take yi; ");
INSERT INTO hausa_vpl VALUES ("PS39_3","020_39_3","PSA","39","3","3","zuciyata ta ƙara zafi a cikina. Kuma sa’ad da nake tunani, wuta ta yi ta kuna; sai na yi magana da harshena na ce, ");
INSERT INTO hausa_vpl VALUES ("PS39_4","020_39_4","PSA","39","4","4","“Nuna mini, ya Ubangiji, ƙarshen rayuwata da kuma yawan kwanakina; bari in san yadda rayuwata tana wucewa da sauri. ");
INSERT INTO hausa_vpl VALUES ("PS39_5","020_39_5","PSA","39","5","5","Ka sa kwanakina suka zama tafin hannu ne kawai; yawan shekaruna kamar ba kome ba ne a gabanka. Duk ran mutum shaƙar iska ne kurum, har ma waɗanda suke tsammani suke da kāriya. Sela ");
INSERT INTO hausa_vpl VALUES ("PS39_6","020_39_6","PSA","39","6","6","“Mutum dai shirim ne kawai yayinda yake kai da komowa. Yana ta yawo, amma a banza ne kawai; yakan tara dukiya, ba tare da sanin wa zai more ta ba. ");
INSERT INTO hausa_vpl VALUES ("PS39_7","020_39_7","PSA","39","7","7","“Amma yanzu, ya Ubangiji, me zan nema? Begena yana a gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS39_8","020_39_8","PSA","39","8","8","Ka cece ni daga dukan laifofina; kada ka sa in zama abin dariya ga wawaye. ");
INSERT INTO hausa_vpl VALUES ("PS39_9","020_39_9","PSA","39","9","9","Na yi shiru; ba zan buɗe bakina ba, gama kai ne wanda ka aikata wannan. ");
INSERT INTO hausa_vpl VALUES ("PS39_10","020_39_10","PSA","39","10","10","Ka ɗauke bulalarka daga gare ni; na ji jiki ta wurin bugun da hannunka ya yi mini. ");
INSERT INTO hausa_vpl VALUES ("PS39_11","020_39_11","PSA","39","11","11","Kakan tsawata ka kuma hore mutane saboda zunubinsu; kakan cinye wadatarsu kamar yadda asu ke yi, kowane mutum dai shaƙar iska ne. Sela ");
INSERT INTO hausa_vpl VALUES ("PS39_12","020_39_12","PSA","39","12","12","“Ka ji addu’ata, ya Ubangiji, ka saurari kukata ta neman taimako; kada ka kurmance ga kukata. Gama ina zama tare da kai kamar baƙo, baƙo, kamar yadda dukan kakannina sun kasance. ");
INSERT INTO hausa_vpl VALUES ("PS39_13","020_39_13","PSA","39","13","13","Ka kau da fuskarka daga gare ni, saboda in sāke yin farin ciki kafin in tafi in kuma rabu da nan.” ");
INSERT INTO hausa_vpl VALUES ("PS40_1","020_40_1","PSA","40","1","1","Don mai bi da kaɗe-kaɗe. Ta Dawuda. Zabura ce. Na jira da haƙuri ga Ubangiji; ya juya wurina ya kuma ji kukata. ");
INSERT INTO hausa_vpl VALUES ("PS40_2","020_40_2","PSA","40","2","2","Ya ɗaga ni daga rami marar fāɗi, daga laka da taɓo; ya sa ƙafafuna a kan dutse ya kuma ba ni tsayayyen wuri don in tsaya. ");
INSERT INTO hausa_vpl VALUES ("PS40_3","020_40_3","PSA","40","3","3","Ya sa sabuwar waƙa a bakina, waƙar yabo ga Allahna. Da yawa za su gani su tsorata su kuma dogara ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS40_4","020_40_4","PSA","40","4","4","Mai albarka ne mutumin da ya mai da Ubangiji abin dogararsa, wanda ba ya kula da masu girman kai, waɗanda suka juya ga allolin ƙarya. ");
INSERT INTO hausa_vpl VALUES ("PS40_5","020_40_5","PSA","40","5","5","Da yawa ne, ya Ubangiji Allahna, abubuwan banmamakin da ka aikata. Abubuwan da ka shirya mana. Ba wanda zai iya faɗa maka su; a ce zan yi magana in faɗe su, za su wuce gaban misali a furta. ");
INSERT INTO hausa_vpl VALUES ("PS40_6","020_40_6","PSA","40","6","6","Hadaya da sadaka ba ka sha’awa, amma kunnuwana ka huda; hadayun ƙonawa da hadayun zunubi ba ka bukata. ");
INSERT INTO hausa_vpl VALUES ("PS40_7","020_40_7","PSA","40","7","7","Sa’an nan na ce, “Ga ni, na zo, kamar yadda yake a rubuce game da ni cikin littafi. ");
INSERT INTO hausa_vpl VALUES ("PS40_8","020_40_8","PSA","40","8","8","Ina sha’awar aikata nufinka, ya Allahna; dokar tana cikin zuciyata.” ");
INSERT INTO hausa_vpl VALUES ("PS40_9","020_40_9","PSA","40","9","9","Na yi shelar adalcinka cikin babban taro; ba na rufe leɓunana, kamar yadda ka sani, ya Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS40_10","020_40_10","PSA","40","10","10","Ba na ɓoye adalcinka cikin zuciyata; ina maganar amincinka da cetonka. Ban ɓoye ƙaunarka da gaskiyarka a gaban taron jama’arka mai girma ba. ");
INSERT INTO hausa_vpl VALUES ("PS40_11","020_40_11","PSA","40","11","11","Kada ka hana mini jinƙanka, ya Ubangiji; bari ƙaunarka da gaskiyarka kullum su kāre ni. ");
INSERT INTO hausa_vpl VALUES ("PS40_12","020_40_12","PSA","40","12","12","Gama damuwoyin da suka wuce misali sun kewaye ni; zunubaina sun mamaye ni, kuma ba na iya gani. Sun fi gashin kaina yawa, har ma na fid da zuciya. ");
INSERT INTO hausa_vpl VALUES ("PS40_13","020_40_13","PSA","40","13","13","Ka ji daɗin cetona, ya Ubangiji; Ya Ubangiji, ka zo da sauri ka taimake ni. ");
INSERT INTO hausa_vpl VALUES ("PS40_14","020_40_14","PSA","40","14","14","Bari masu neman raina su sha kunya su kuma rikice; bari dukan waɗanda suke neman lalacewata su koma baya da kunya. ");
INSERT INTO hausa_vpl VALUES ("PS40_15","020_40_15","PSA","40","15","15","Bari masu ce mini, “Allah yă ƙara!” Su sha mamaki saboda kunyar da za su sha. ");
INSERT INTO hausa_vpl VALUES ("PS40_16","020_40_16","PSA","40","16","16","Amma bari dukan masu nemanka su yi farin ciki su kuma yi murna a cikinka; bari waɗanda suke ƙaunar cetonka kullum su ce, “Ubangiji mai girma ne!” ");
INSERT INTO hausa_vpl VALUES ("PS40_17","020_40_17","PSA","40","17","17","Ni dai matalauci ne da mai bukata; bari Ubangiji yă tuna da ni. Kai ne taimakona da mai cetona; Ya Allahna, kada ka jinkirta. ");
INSERT INTO hausa_vpl VALUES ("PS41_1","020_41_1","PSA","41","1","1","Don mai bi da kaɗe-kaɗe. Zabura ta Dawuda. Mai albarka ne wanda yake jin tausayin marasa ƙarfi; Ubangiji yakan kuɓutar da shi a lokutan wahala. ");
INSERT INTO hausa_vpl VALUES ("PS41_2","020_41_2","PSA","41","2","2","Ubangiji zai kāre shi yă kuma kiyaye ransa; zai albarkace shi a cikin ƙasar ba kuwa zai miƙa shi ga hannun maƙiyansa ba. ");
INSERT INTO hausa_vpl VALUES ("PS41_3","020_41_3","PSA","41","3","3","Ubangiji zai ba shi ƙarfi a gadon rashin lafiyarsa ya mayar masa da lafiya daga ciwon da ya kwantar da shi. ");
INSERT INTO hausa_vpl VALUES ("PS41_4","020_41_4","PSA","41","4","4","Na ce, “Ya Ubangiji, ka yi mini jinƙai; ka warkar da ni, gama na yi maka zunubi.” ");
INSERT INTO hausa_vpl VALUES ("PS41_5","020_41_5","PSA","41","5","5","Abokan gābana suna muguwar magana a kaina cewa, “Yaushe zai mutu sunansa yă ɓace ne?” ");
INSERT INTO hausa_vpl VALUES ("PS41_6","020_41_6","PSA","41","6","6","Duk sa’ad da wani ya zo ganina, yakan yi maganar ƙarya, yayinda zuciyarsa tana tattare da cin zarafi; sa’an nan yă fita yă yi ta bazawa ko’ina. ");
INSERT INTO hausa_vpl VALUES ("PS41_7","020_41_7","PSA","41","7","7","Dukan abokan gābana suna raɗa tare a kaina; suna fata mugun abu ya same ni, suna cewa, ");
INSERT INTO hausa_vpl VALUES ("PS41_8","020_41_8","PSA","41","8","8","“Mugun ciwo ya kama shi; ba zai taɓa tashi daga inda yake kwanciya ba.” ");
INSERT INTO hausa_vpl VALUES ("PS41_9","020_41_9","PSA","41","9","9","Har abokina na kurkusa, wanda na amince da shi, wanda muke cin abinci tare, ya juya yana gāba da ni. ");
INSERT INTO hausa_vpl VALUES ("PS41_10","020_41_10","PSA","41","10","10","Amma kai, ya Ubangiji, ka yi mini jinƙai, ka tā da ni, don in sāka musu. ");
INSERT INTO hausa_vpl VALUES ("PS41_11","020_41_11","PSA","41","11","11","Na sani kana jin daɗina, gama abokin gābana ba zai ci nasara a kaina ba. ");
INSERT INTO hausa_vpl VALUES ("PS41_12","020_41_12","PSA","41","12","12","Cikin mutuncina ka riƙe ni ka sa ni a gabanka har abada. ");
INSERT INTO hausa_vpl VALUES ("PS41_13","020_41_13","PSA","41","13","13","Yabo ya tabbata ga Ubangiji, Allah na Isra’ila, har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("PS42_1","020_42_1","PSA","42","1","1","Don mai bi da kaɗe-kaɗe. Maskil ne na ’Ya’yan Kora maza. Kamar yadda barewa take marmarin ruwan rafuffuka, haka raina yake marmarinka, ya Allah. ");
INSERT INTO hausa_vpl VALUES ("PS42_2","020_42_2","PSA","42","2","2","Raina yana ƙishin Allah, Allah mai rai. Yaushe zan tafi in sadu da Allah ne? ");
INSERT INTO hausa_vpl VALUES ("PS42_3","020_42_3","PSA","42","3","3","Hawayena ne sun zama abincina dare da rana, yayinda mutane suke ce da ni dukan yini, “Ina Allahnka ɗin?” ");
INSERT INTO hausa_vpl VALUES ("PS42_4","020_42_4","PSA","42","4","4","Waɗannan abubuwa ne nakan tuna sa’ad da nake faɗin abin da yake a raina, yadda dā nakan tafi tare da taron jama’a, ina bishe su a jere zuwa gidan Allah, da sowa ta farin ciki da kuma godiya a cikin taron biki. ");
INSERT INTO hausa_vpl VALUES ("PS42_5","020_42_5","PSA","42","5","5","Me ya sa kake baƙin ciki, ya raina? Me ya sa ka damu a cikina? Ka dogara ga Allah, gama zai sāke yabe shi, Mai Cetona da kuma Allahna. ");
INSERT INTO hausa_vpl VALUES ("PS42_6","020_42_6","PSA","42","6","6","Raina yana baƙin ciki a cikina; saboda haka zan tuna da kai daga ƙasar Urdun, a ƙwanƙolin Hermon, daga Dutsen Mizar. ");
INSERT INTO hausa_vpl VALUES ("PS42_7","020_42_7","PSA","42","7","7","Zurfi kan kira zurfi cikin rurin matsirgar ruwanka; dukan raƙuma da igiyoyi sun sha kaina. ");
INSERT INTO hausa_vpl VALUES ("PS42_8","020_42_8","PSA","42","8","8","Da rana Ubangiji yakan nuna ƙaunarsa, da dare waƙarsa tana tare da ni, addu’a ga Allah na raina. ");
INSERT INTO hausa_vpl VALUES ("PS42_9","020_42_9","PSA","42","9","9","Na ce wa Allah Dutsena, “Me ya sa ka manta da ni? Me zai sa in yi ta yawo ina makoki, a danne a hannun abokin gāba?” ");
INSERT INTO hausa_vpl VALUES ("PS42_10","020_42_10","PSA","42","10","10","Ƙasusuwana suna jin jiki da wahala yayinda maƙiyana suna mini ba’a, suna ce mini dukan yini, “Ina Allahnka ɗin?” ");
INSERT INTO hausa_vpl VALUES ("PS42_11","020_42_11","PSA","42","11","11","Me ya sa kake baƙin ciki, ya raina? Me ya sa ka damu a cikina? Ka dogara ga Allah, gama zai sāke yabe shi, Mai Cetona da kuma Allahna. ");
INSERT INTO hausa_vpl VALUES ("PS43_1","020_43_1","PSA","43","1","1","Ka nuna ni marar laifi ne, ya Allah, ka kuma nemi hakkina a kan al’ummai marasa sanin Allah. Ka kuɓutar da ni daga masu ruɗu da mugayen mutane. ");
INSERT INTO hausa_vpl VALUES ("PS43_2","020_43_2","PSA","43","2","2","Kai ne Allah mafakata. Me ya sa ka ƙi ni? Me zai sa in yi ta yawo ina makoki, a danne a hannun abokin gāba? ");
INSERT INTO hausa_vpl VALUES ("PS43_3","020_43_3","PSA","43","3","3","Ka aiko da haskenka da gaskiyarka, bari su bishe ni bari su kawo ni ga dutsenka mai tsarki, zuwa wurin da kake zama. ");
INSERT INTO hausa_vpl VALUES ("PS43_4","020_43_4","PSA","43","4","4","Sa’an nan zan tafi bagaden Allah, ga Allah, farin cikina da murnata. Zan yabe ka da garaya, Ya Allah, Allahna. ");
INSERT INTO hausa_vpl VALUES ("PS43_5","020_43_5","PSA","43","5","5","Me ya sa kake baƙin ciki, ya raina? Me ya sa ka damu a cikina? Ka dogara ga Allah, gama zai sāke yabe shi, Mai Cetona da Allahna. ");
INSERT INTO hausa_vpl VALUES ("PS44_1","020_44_1","PSA","44","1","1","Don mai bi da kaɗe-kaɗe. Ta ’ya’yan Kora maza. Maskil ne. Mun ji da kunnuwanmu, ya Allah; kakanninmu sun faɗa mana abin da ka aikata a kwanakinsu, tun dā can. ");
INSERT INTO hausa_vpl VALUES ("PS44_2","020_44_2","PSA","44","2","2","Da hannunka ka kori al’ummai ka kuma dasa kakanninmu; ka ragargaza mutanen ka kuma sa kakanninmu suka haɓaka. ");
INSERT INTO hausa_vpl VALUES ("PS44_3","020_44_3","PSA","44","3","3","Ba da takobinsu ba ne suka ci ƙasar, ba kuwa ƙarfin hannunsu ne ya ba su nasara ba; hannun damanka ne, ƙarfin hannunka, da kuma hasken fuskarka, gama ka ƙaunace su. ");
INSERT INTO hausa_vpl VALUES ("PS44_4","020_44_4","PSA","44","4","4","Kai ne Sarkina da kuma Allahna, wanda ya ba da nasarori wa Yaƙub. ");
INSERT INTO hausa_vpl VALUES ("PS44_5","020_44_5","PSA","44","5","5","Ta wurinka mun tura abokan gābanmu baya; ta wurin sunanka muka tattake maƙiyanmu. ");
INSERT INTO hausa_vpl VALUES ("PS44_6","020_44_6","PSA","44","6","6","Ba na dogara ga bakana, takobina ba ya kawo nasara; ");
INSERT INTO hausa_vpl VALUES ("PS44_7","020_44_7","PSA","44","7","7","amma kana ba mu nasara a kan abokan gābanmu, ka sa abokan gābanmu suka sha kunya. ");
INSERT INTO hausa_vpl VALUES ("PS44_8","020_44_8","PSA","44","8","8","A cikin Allah muke fariyarmu dukan yini, kuma za mu yabi sunanka har abada. Sela ");
INSERT INTO hausa_vpl VALUES ("PS44_9","020_44_9","PSA","44","9","9","Amma yanzu ka ƙi mu ka kuma ƙasƙantar da mu; ba ka ƙara fita tare da mayaƙanmu. ");
INSERT INTO hausa_vpl VALUES ("PS44_10","020_44_10","PSA","44","10","10","Ka sa muka gudu a gaban abokin gāba, kuma abokan gābanmu suka washe mu. ");
INSERT INTO hausa_vpl VALUES ("PS44_11","020_44_11","PSA","44","11","11","Ka ba da mu a cinye kamar tumaki ka kuma watsar da mu a cikin al’ummai. ");
INSERT INTO hausa_vpl VALUES ("PS44_12","020_44_12","PSA","44","12","12","Ka sayar da mutanenka a kuɗin da bai taka ƙara ya karye ba babu wata riba daga sayar da su da ka yi. ");
INSERT INTO hausa_vpl VALUES ("PS44_13","020_44_13","PSA","44","13","13","Ka mai da mu abin dariya ga maƙwabtanmu, abin dariya da reni ga waɗanda suke kewaye da mu. ");
INSERT INTO hausa_vpl VALUES ("PS44_14","020_44_14","PSA","44","14","14","Ka sa muka zama abin ba’a a cikin al’ummai; mutanen suna kaɗa mana kai. ");
INSERT INTO hausa_vpl VALUES ("PS44_15","020_44_15","PSA","44","15","15","Dukan yini ina cikin wulaƙanci, fuskata kuma ta rufu da kunya ");
INSERT INTO hausa_vpl VALUES ("PS44_16","020_44_16","PSA","44","16","16","saboda ba’ar waɗanda suke zagi suke kuma ƙina, saboda abokan gābana, waɗanda suka sha alwashi sai sun yi ramuwa. ");
INSERT INTO hausa_vpl VALUES ("PS44_17","020_44_17","PSA","44","17","17","Dukan wannan ya faru da mu, ko da yake ba mu manta da kai ba ko mu kasance masu ƙarya ga alkawarinka. ");
INSERT INTO hausa_vpl VALUES ("PS44_18","020_44_18","PSA","44","18","18","Zukatanmu ba su juya baya; ƙafafunmu ba su kauce daga hanyarka ba. ");
INSERT INTO hausa_vpl VALUES ("PS44_19","020_44_19","PSA","44","19","19","Amma ka ragargaza mu ka kuma maishe mu abin farautar karnukan jeji ka kuma rufe mu cikin duhu baƙi ƙirin. ");
INSERT INTO hausa_vpl VALUES ("PS44_20","020_44_20","PSA","44","20","20","Da a ce mun manta da sunan Allahnmu ko mun miƙa hannuwanmu ga baƙin alloli, ");
INSERT INTO hausa_vpl VALUES ("PS44_21","020_44_21","PSA","44","21","21","da Allah bai gane ba, da yake ya san asiran zuciya? ");
INSERT INTO hausa_vpl VALUES ("PS44_22","020_44_22","PSA","44","22","22","Duk da haka saboda kai mun fuskanci mutuwa dukan yini; aka ɗauke mu kamar tumakin da za a yanka. ");
INSERT INTO hausa_vpl VALUES ("PS44_23","020_44_23","PSA","44","23","23","Ka farka, ya Ubangiji! Don me kake barci? Ta da kanka! Kada ka ƙi mu har abada. ");
INSERT INTO hausa_vpl VALUES ("PS44_24","020_44_24","PSA","44","24","24","Me ya sa ka ɓoye fuskarka ka manta da azabanmu da kuma danniyar da ake mana? ");
INSERT INTO hausa_vpl VALUES ("PS44_25","020_44_25","PSA","44","25","25","An kai mu ƙasa zuwa ƙura; jikunanmu sun manne da ƙasa. ");
INSERT INTO hausa_vpl VALUES ("PS44_26","020_44_26","PSA","44","26","26","Ka tashi ka taimake mu; ka cece mu saboda ƙaunarka marar ƙarewa. ");
INSERT INTO hausa_vpl VALUES ("PS45_1","020_45_1","PSA","45","1","1","Don mai bi da kaɗe-kaɗe. Da salon “Lili.” Na ’ya’yan Kora maza. Maskil Waƙar Aure. Zuciyata ta cika da kyakkyawan kan magana yayinda nake rera ayoyina wa sarki; harshena ne alƙalamin ƙwararren marubuci. ");
INSERT INTO hausa_vpl VALUES ("PS45_2","020_45_2","PSA","45","2","2","Kai ne mafi kyau cikin mutane an kuma shafe leɓunanka da alheri, da yake Allah ya albarkace ka har abada. ");
INSERT INTO hausa_vpl VALUES ("PS45_3","020_45_3","PSA","45","3","3","Ka ɗaura takobinka a gefenka, ya jarumi; ka rufe kanka da ɗaukaka da kuma daraja. ");
INSERT INTO hausa_vpl VALUES ("PS45_4","020_45_4","PSA","45","4","4","Cikin darajarka ka hau zuwa nasara a madadin gaskiya, tawali’u da adalci; bari hannunka na dama yă nuna ayyukan banmamaki. ");
INSERT INTO hausa_vpl VALUES ("PS45_5","020_45_5","PSA","45","5","5","Bari kibiyoyinka masu tsini su huda zukatan abokan gāban sarki; bari al’ummai su fāɗi ƙarƙashin ƙafafunka. ");
INSERT INTO hausa_vpl VALUES ("PS45_6","020_45_6","PSA","45","6","6","Kursiyinka, ya Allah, zai kasance har abada abadin; sandar adalci zai zama sandar mulkinka. ");
INSERT INTO hausa_vpl VALUES ("PS45_7","020_45_7","PSA","45","7","7","Kana ƙaunar abin da yake daidai kana kuma ƙin mugunta; saboda haka Allah, Allahnka, ya sa ka a bisa abokanka ta wurin shafe ka da man farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS45_8","020_45_8","PSA","45","8","8","Dukan rigunanka suna ƙanshin turaren mur da na aloyes, da na kashiya; daga kowace fadan da aka yi masa ado da hauren giwa kaɗe-kaɗen tsirkiya kan sa ka murna. ");
INSERT INTO hausa_vpl VALUES ("PS45_9","020_45_9","PSA","45","9","9","’Ya’yan sarki mata suna cikin matan da ake girmama; a hannun damarka kuwa ga amarya, sarauniya saye da ofir zinariya. ");
INSERT INTO hausa_vpl VALUES ("PS45_10","020_45_10","PSA","45","10","10","Ki saurara, ya ke diya, ki lura ku kuma kasa kunne, Ki manta da mutanenki da gidan mahaifinki. ");
INSERT INTO hausa_vpl VALUES ("PS45_11","020_45_11","PSA","45","11","11","Sarki ya cika da sha’awar kyanki; ki girmama shi, gama shi ne maigidanki. ");
INSERT INTO hausa_vpl VALUES ("PS45_12","020_45_12","PSA","45","12","12","Diyar Taya za tă zo da kyauta, mawadata za su nemi tagomashinki. ");
INSERT INTO hausa_vpl VALUES ("PS45_13","020_45_13","PSA","45","13","13","Gimbiya tana fada, kyakkyawa ce ainun; an saƙa rigarta da zaren zinariya. ");
INSERT INTO hausa_vpl VALUES ("PS45_14","020_45_14","PSA","45","14","14","Cikin riguna masu ado aka kai ta wurin sarki; abokanta budurwai suna biye da ita aka kuwa kawo su gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS45_15","020_45_15","PSA","45","15","15","Aka bi da su cikin farin ciki da murna; suka shiga fadan sarki. ");
INSERT INTO hausa_vpl VALUES ("PS45_16","020_45_16","PSA","45","16","16","’Ya’yanka maza za su maye matsayin kakanninka; za ka sa su yi mulki a duk fāɗin ƙasar. ");
INSERT INTO hausa_vpl VALUES ("PS45_17","020_45_17","PSA","45","17","17","Zan sa a tuna da kai a dukan zamanai; saboda haka al’ummai za su yabe ka har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("PS46_1","020_46_1","PSA","46","1","1","Don mai bi da kaɗe-kaɗe. Ta ’Ya’yan Kora maza. Bisa ga alamot Waƙa ce. Allah ne mafakarmu da ƙarfinmu, kullum yana a shirye yă taimaka a lokacin wahala. ");
INSERT INTO hausa_vpl VALUES ("PS46_2","020_46_2","PSA","46","2","2","Saboda haka ba za mu ji tsoro ba, ko da ƙasa ta girgiza duwatsu kuma suka fāɗi cikin zurfin teku, ");
INSERT INTO hausa_vpl VALUES ("PS46_3","020_46_3","PSA","46","3","3","ko da ruwansa suna ruri suna kumfa duwatsu kuma suna girgiza da tumbatsansu. Sela ");
INSERT INTO hausa_vpl VALUES ("PS46_4","020_46_4","PSA","46","4","4","Akwai kogi mai rafuffukan da suke sa birnin Allah murna, tsattsarkan wuri inda Mafi Ɗaukaka ke zama. ");
INSERT INTO hausa_vpl VALUES ("PS46_5","020_46_5","PSA","46","5","5","Allah yana cikinta, ba za tă fāɗi ba; Allah zai taimake ta da safe. ");
INSERT INTO hausa_vpl VALUES ("PS46_6","020_46_6","PSA","46","6","6","Al’ummai suna hayaniya, mulkoki sun fāɗi; ya ɗaga muryarsa, duniya ta narke. ");
INSERT INTO hausa_vpl VALUES ("PS46_7","020_46_7","PSA","46","7","7","Ubangiji Maɗaukaki yana tare da mu; Allah na Yaƙub ne kagararmu. Sela ");
INSERT INTO hausa_vpl VALUES ("PS46_8","020_46_8","PSA","46","8","8","Zo ku ga ayyukan Ubangiji, kangon da ya kawo a kan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS46_9","020_46_9","PSA","46","9","9","Ya sa yaƙoƙi suka yi tsit ko’ina a duniya. Ya kakkarya bakkuna ya kuma ragargaza māsu, ya ƙone garkuwoyi da wuta. ");
INSERT INTO hausa_vpl VALUES ("PS46_10","020_46_10","PSA","46","10","10","“Ku natsu ku kuma san cewa ni ne Allah; za a ɗaukaka ni a cikin al’ummai, za a ɗaukaka ni cikin duniya.” ");
INSERT INTO hausa_vpl VALUES ("PS46_11","020_46_11","PSA","46","11","11","Ubangiji Maɗaukaki yana tare da mu; Allah na Yaƙub ne kagararmu. Sela ");
INSERT INTO hausa_vpl VALUES ("PS47_1","020_47_1","PSA","47","1","1","Don mai bi da kaɗe-kaɗe. Ta ’Ya’yan Kora maza. Zabura ce. Ku tafa hannuwanku, dukanku al’ummai; ku yi sowa ga Allah da muryoyin farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS47_2","020_47_2","PSA","47","2","2","Ubangiji Mafi Ɗaukaka mai banmamaki ne, Sarki ne mai girma a bisa dukan duniya! ");
INSERT INTO hausa_vpl VALUES ("PS47_3","020_47_3","PSA","47","3","3","Ya rinjayi al’ummai a ƙarƙashinmu, mutane kuma a ƙarƙashin ƙafafunmu. ");
INSERT INTO hausa_vpl VALUES ("PS47_4","020_47_4","PSA","47","4","4","Ya zaɓar mana gādonmu, abar taƙamar Yaƙub, wanda yake ƙauna. Sela ");
INSERT INTO hausa_vpl VALUES ("PS47_5","020_47_5","PSA","47","5","5","Allah ya haura a cikin sowa ta farin ciki, Ubangiji ya haura a cikin ƙarar ƙahoni. ");
INSERT INTO hausa_vpl VALUES ("PS47_6","020_47_6","PSA","47","6","6","Ku rera yabai ga Allah, ku rera yabai; ku rera yabai ga Sarkinmu, ku rera yabai. ");
INSERT INTO hausa_vpl VALUES ("PS47_7","020_47_7","PSA","47","7","7","Gama Allah shi ne Sarkin dukan duniya; ku rera zabura ta yabo gare shi. ");
INSERT INTO hausa_vpl VALUES ("PS47_8","020_47_8","PSA","47","8","8","Allah yana mulki a bisa al’ummai; Allah yana zama a kan kursiyinsa mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("PS47_9","020_47_9","PSA","47","9","9","Manyan mutanen al’ummai sun taru a matsayin mutanen Allah na Ibrahim, gama sarkunan duniya na Allah ne; ana ɗaukaka shi ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("PS48_1","020_48_1","PSA","48","1","1","Waƙa ce. Zabura ta ’ya’yan Kora maza. Ubangiji mai girma ne, kuma mafificin yabo, a birnin Allahnmu, dutsensa mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("PS48_2","020_48_2","PSA","48","2","2","Kyakkyawa ce cikin tsayinta, abin farin cikin dukan duniya. Kamar ƙwanƙoli mafi tsayi na Zafon ne Dutsen Sihiyona, birnin Babban Sarki. ");
INSERT INTO hausa_vpl VALUES ("PS48_3","020_48_3","PSA","48","3","3","Allah yana cikin fadodinta; ya nuna kansa mafaka ce gare ta. ");
INSERT INTO hausa_vpl VALUES ("PS48_4","020_48_4","PSA","48","4","4","Sa’ad da sarakuna suka haɗa rundunoni, sa’ad da suka yi gaba tare, ");
INSERT INTO hausa_vpl VALUES ("PS48_5","020_48_5","PSA","48","5","5","sun gan ta suka kuwa yi mamaki; suka gudu don tsoro. ");
INSERT INTO hausa_vpl VALUES ("PS48_6","020_48_6","PSA","48","6","6","Rawar jiki ya kama su a can, zafi kamar na mace mai naƙuda. ");
INSERT INTO hausa_vpl VALUES ("PS48_7","020_48_7","PSA","48","7","7","Ka hallaka su kamar jiragen ruwan Tarshish da iskar gabas ta wargaje. ");
INSERT INTO hausa_vpl VALUES ("PS48_8","020_48_8","PSA","48","8","8","Yadda muka ji, haka muka gani a cikin birnin Ubangiji Maɗaukaki, a cikin birnin Allahnmu. Allah ya sa ta zauna lafiya har abada. Sela ");
INSERT INTO hausa_vpl VALUES ("PS48_9","020_48_9","PSA","48","9","9","Cikin haikalinka, ya Allah, mun yi tunani a kan ƙaunarka marar ƙarewa. ");
INSERT INTO hausa_vpl VALUES ("PS48_10","020_48_10","PSA","48","10","10","Kamar sunanka, ya Allah, yabonka ya kai iyakokin duniya; hannunka na dama ya cika da adalci. ");
INSERT INTO hausa_vpl VALUES ("PS48_11","020_48_11","PSA","48","11","11","Dutsen Sihiyona ya yi farin ciki, ƙauyukan Yahuda suna murna saboda hukuntanka. ");
INSERT INTO hausa_vpl VALUES ("PS48_12","020_48_12","PSA","48","12","12","Yi tafiya cikin Sihiyona, ku kewaye ta, ku ƙirga hasumiyoyinta, ");
INSERT INTO hausa_vpl VALUES ("PS48_13","020_48_13","PSA","48","13","13","ku lura da katangarta da kyau, ku dubi fadodinta, don ku faɗe su ga tsara mai zuwa. ");
INSERT INTO hausa_vpl VALUES ("PS48_14","020_48_14","PSA","48","14","14","Gama wannan Allah shi ne Allahnmu har abada abadin; zai zama jagorarmu har zuwa ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("PS49_1","020_49_1","PSA","49","1","1","Don mai bi da kaɗe-kaɗe. Na ’ya’yan Kora maza. Zabura ce. Ku ji wannan, dukanku mutane; ku saurara, dukanku waɗanda suke zama a wannan duniya, ");
INSERT INTO hausa_vpl VALUES ("PS49_2","020_49_2","PSA","49","2","2","babba da yaro mai arziki da talaka. ");
INSERT INTO hausa_vpl VALUES ("PS49_3","020_49_3","PSA","49","3","3","Bakina zai yi maganar hikima; magana daga zuciyata za tă ba da ganewa. ");
INSERT INTO hausa_vpl VALUES ("PS49_4","020_49_4","PSA","49","4","4","Zan juye kunnena ga karin magana; da garaya zan ƙarfafa kacici-kacicina. ");
INSERT INTO hausa_vpl VALUES ("PS49_5","020_49_5","PSA","49","5","5","Don me zan ji tsoro sa’ad da mugayen kwanaki suka zo, sa’ad da mugaye masu ruɗu suka kewaye ni, ");
INSERT INTO hausa_vpl VALUES ("PS49_6","020_49_6","PSA","49","6","6","waɗanda suka dogara ga arzikinsu suna kuma fariya a kan yawan arzikinsu? ");
INSERT INTO hausa_vpl VALUES ("PS49_7","020_49_7","PSA","49","7","7","Ba wani da zai iya ceton ran wani ko yă ba wa Allah kuɗin fansa saboda shi, ");
INSERT INTO hausa_vpl VALUES ("PS49_8","020_49_8","PSA","49","8","8","kuɗin fansa domin rai yana da tsada, babu abin da za a biya da ya taɓa isa, ");
INSERT INTO hausa_vpl VALUES ("PS49_9","020_49_9","PSA","49","9","9","da zai sa yă ci gaba da rayuwa har abada yă hana shi shigan kabari yă ruɓa. ");
INSERT INTO hausa_vpl VALUES ("PS49_10","020_49_10","PSA","49","10","10","Gama kowa na iya ganin masu hikima na mutuwa; wawaye da marasa azanci su ma kan hallaka su bar wa waɗansu arzikinsu. ");
INSERT INTO hausa_vpl VALUES ("PS49_11","020_49_11","PSA","49","11","11","Kaburburansu za su ci gaba da zama gidajensu har abada, Can za su kasance har zamanai marasa ƙarewa, ko da yake sun ba wa filaye sunayen kansu. ");
INSERT INTO hausa_vpl VALUES ("PS49_12","020_49_12","PSA","49","12","12","Amma mutum, kome arzikinsa, ba ya dawwama; shi kamar dabbobi ne da suke mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PS49_13","020_49_13","PSA","49","13","13","Wannan ne ƙaddarar waɗanda suke dogara a kansu, da kuma ta mabiyansu, waɗanda suka tabbatar da faɗinsu. Sela ");
INSERT INTO hausa_vpl VALUES ("PS49_14","020_49_14","PSA","49","14","14","Kamar tumaki an ƙaddara su ga kabari; za su kuwa zama abincin mutuwa amma masu gaskiya za su yi mulki a kansu da safe. Kamanninsu za su ruɓe a cikin kabari, nesa da gidajensu masu tsada. ");
INSERT INTO hausa_vpl VALUES ("PS49_15","020_49_15","PSA","49","15","15","Amma Allah zai ceci raina daga kabari; tabbatacce zai ɗauke ni zuwa wurinsa. Sela ");
INSERT INTO hausa_vpl VALUES ("PS49_16","020_49_16","PSA","49","16","16","Kada ka razana da yawa sa’ad da mutum ya yi arziki sa’ad da darajar gidansa ta ƙaru; ");
INSERT INTO hausa_vpl VALUES ("PS49_17","020_49_17","PSA","49","17","17","gama ba zai ɗauki kome tare da shi sa’ad da ya mutu ba, darajarsa ba za tă gangara tare da shi ba. ");
INSERT INTO hausa_vpl VALUES ("PS49_18","020_49_18","PSA","49","18","18","Ko da yake yayinda yake a raye ya ɗauka kansa mai albarka ne, mutane kuma sun yabe ka sa’ad da kake cin nasara, ");
INSERT INTO hausa_vpl VALUES ("PS49_19","020_49_19","PSA","49","19","19","zai gamu da tsarar kakanninsa, waɗanda ba za su taɓa ganin hasken rayuwa ba. ");
INSERT INTO hausa_vpl VALUES ("PS49_20","020_49_20","PSA","49","20","20","Mutumin da yake da arziki ba tare da ganewa ba shi kamar dabbobi ne da suke mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PS50_1","020_50_1","PSA","50","1","1","Zabura ta Asaf. Maɗaukaki, Allah, Ubangiji, ya yi magana ya kuma kira duniya daga fitowar rana zuwa inda take fāɗuwa. ");
INSERT INTO hausa_vpl VALUES ("PS50_2","020_50_2","PSA","50","2","2","Daga Sihiyona, cikakkiya a kyau, Allah na haskakawa. ");
INSERT INTO hausa_vpl VALUES ("PS50_3","020_50_3","PSA","50","3","3","Allahnmu yana zuwa ba kuwa zai yi shiru ba; wuta mai cinyewa a gabansa, babban hadari kuma ya kewaye shi. ");
INSERT INTO hausa_vpl VALUES ("PS50_4","020_50_4","PSA","50","4","4","Ya kira sammai da suke bisa, da duniya, don yă shari’anta mutanensa. ");
INSERT INTO hausa_vpl VALUES ("PS50_5","020_50_5","PSA","50","5","5","“Ku tattara mini shafaffuna, waɗanda suka yi alkawari da ni ta wurin hadaya.” ");
INSERT INTO hausa_vpl VALUES ("PS50_6","020_50_6","PSA","50","6","6","Sammai kuwa sun yi shelar adalcinsa gama Allah kansa alƙali ne. Sela ");
INSERT INTO hausa_vpl VALUES ("PS50_7","020_50_7","PSA","50","7","7","“Ku ji, ya mutanena, zan kuwa yi magana, Ya Isra’ila, zan kuwa ba da shaida a kanku. Ni ne Allah, Allahnku. ");
INSERT INTO hausa_vpl VALUES ("PS50_8","020_50_8","PSA","50","8","8","Ba na tsawata muku saboda hadayunku ko kuwa hadayunku na ƙonawa, waɗanda kuka taɓa kawo a gabana. ");
INSERT INTO hausa_vpl VALUES ("PS50_9","020_50_9","PSA","50","9","9","Ba na bukatan bijimi daga turkenku ko awaki daga garkunanku, ");
INSERT INTO hausa_vpl VALUES ("PS50_10","020_50_10","PSA","50","10","10","gama kowace dabbar kurmi nawa ne, da kuma shanu a kan dubban tuddai. ");
INSERT INTO hausa_vpl VALUES ("PS50_11","020_50_11","PSA","50","11","11","Na san kowane tsuntsun da yake a duwatsu kuma halittun filaye nawa ne. ");
INSERT INTO hausa_vpl VALUES ("PS50_12","020_50_12","PSA","50","12","12","Da a ce ina jin yunwa ai, ba sai na faɗa muku ba, gama duniyar nawa ne, da kome da yake cikinta. ");
INSERT INTO hausa_vpl VALUES ("PS50_13","020_50_13","PSA","50","13","13","Ina cin naman bijimai ne ko ina shan jinin awaki ne? ");
INSERT INTO hausa_vpl VALUES ("PS50_14","020_50_14","PSA","50","14","14","“Ku miƙa hadayar godiya ga Allah, ku cika alkawuranku ga Mafi Ɗaukaka, ");
INSERT INTO hausa_vpl VALUES ("PS50_15","020_50_15","PSA","50","15","15","ku kira gare ni a ranar wahala; zan cece ku, za ku kuwa girmama ni.” ");
INSERT INTO hausa_vpl VALUES ("PS50_16","020_50_16","PSA","50","16","16","Amma ga mugaye, Allah ya ce, “Wace dama ce kuke da ita na haddace dokokina ko na yin maganar alkawarina a leɓunanku? ");
INSERT INTO hausa_vpl VALUES ("PS50_17","020_50_17","PSA","50","17","17","Kun ƙi umarnina kuka kuma zubar da kalmomina a bayanku ");
INSERT INTO hausa_vpl VALUES ("PS50_18","020_50_18","PSA","50","18","18","Sa’ad da kuka ga ɓarawo, kukan haɗa kai da shi; kukan haɗa kai da mazinata. ");
INSERT INTO hausa_vpl VALUES ("PS50_19","020_50_19","PSA","50","19","19","Kuna amfani da bakunanku don mugunta kuna kuma gyara harshenku don ruɗu. ");
INSERT INTO hausa_vpl VALUES ("PS50_20","020_50_20","PSA","50","20","20","Kuna ci gaba da magana a kan ɗan’uwanku ku kuma yi maganar ƙarya a kan ɗan mahaifinku. ");
INSERT INTO hausa_vpl VALUES ("PS50_21","020_50_21","PSA","50","21","21","Kun yi waɗannan abubuwa na kuwa yi shiru; kun ɗauka gaba ɗaya ni kamar ku ne. Amma zan tsawata muku in kuma zarge ku a fuskarku. ");
INSERT INTO hausa_vpl VALUES ("PS50_22","020_50_22","PSA","50","22","22","“Ku lura da wannan, ku da kuka manta da Allah, ko kuwa in yayyage ku kucu-kucu, ba kuma wanda zai cece ku. ");
INSERT INTO hausa_vpl VALUES ("PS50_23","020_50_23","PSA","50","23","23","Shi wanda ya miƙa hadayun godiya yakan girmama ni, ya kuma shirya hanya saboda in nuna masa ceton Allah.” ");
INSERT INTO hausa_vpl VALUES ("PS51_1","020_51_1","PSA","51","1","1","Don mai bi da kaɗe-kaɗe. Zabura ta Dawuda. Sa’ad da annabi Natan ya zo wurinsa bayan Dawuda ya yi zina da Batsheba. Ka yi mini jinƙai, ya Allah, bisa ga ƙaunarka marar ƙarewa; bisa ga tausayinka mai girma ka shafe laifofina. ");
INSERT INTO hausa_vpl VALUES ("PS51_2","020_51_2","PSA","51","2","2","Ka wanke dukan kurakuraina ka tsarkake ni daga zunubina. ");
INSERT INTO hausa_vpl VALUES ("PS51_3","020_51_3","PSA","51","3","3","Gama ina sane da laifofina zunubaina kuma kullum suna a gabana. ");
INSERT INTO hausa_vpl VALUES ("PS51_4","020_51_4","PSA","51","4","4","Kai kaɗai na yi wa zunubi na yi abin da yake mugu a idonka, ta haka an tabbatar kai mai gaskiya sa’ad da ka yi magana aka kuma nuna kai mai adalci ne sa’ad da ka hukunta. ");
INSERT INTO hausa_vpl VALUES ("PS51_5","020_51_5","PSA","51","5","5","Tabbatacce ni mai zunubi ne tun haihuwa mai zunubi daga lokacin da mahaifiyata ta yi cikina. ");
INSERT INTO hausa_vpl VALUES ("PS51_6","020_51_6","PSA","51","6","6","Tabbatacce kana son gaskiya a sassan ciki; ka koya mini hikima a wuri can ciki. ");
INSERT INTO hausa_vpl VALUES ("PS51_7","020_51_7","PSA","51","7","7","Ka tsarkake ni da hizzob, zan kuwa zama tsab; ka wanke ni, zan kuma fi dusan ƙanƙara fari. ");
INSERT INTO hausa_vpl VALUES ("PS51_8","020_51_8","PSA","51","8","8","Bari in ji farin ciki da murna; bari ƙasusuwan da ka ragargaza su yi farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS51_9","020_51_9","PSA","51","9","9","Ka ɓoye fuskarka daga zunubaina ka kuma shafe dukan kurakuraina. ");
INSERT INTO hausa_vpl VALUES ("PS51_10","020_51_10","PSA","51","10","10","Ka halitta zuciya mai tsabta a cikina, ya Allah, ka kuma sabunta tsayayyen ruhu a cikina. ");
INSERT INTO hausa_vpl VALUES ("PS51_11","020_51_11","PSA","51","11","11","Kada ka fid da ni daga gabanka ko ka ɗauke Ruhunka Mai Tsarki daga gare ni. ");
INSERT INTO hausa_vpl VALUES ("PS51_12","020_51_12","PSA","51","12","12","Ka mayar mini farin cikin cetonka ka kuma ba ni ruhun biyayya, yă riƙe ni. ");
INSERT INTO hausa_vpl VALUES ("PS51_13","020_51_13","PSA","51","13","13","Ta haka zan koyar wa masu laifi hanyoyinka, masu zunubi kuma za su komo gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS51_14","020_51_14","PSA","51","14","14","Ka cece ni daga laifin jini, ya Allah, Allahn da ya cece ni, harshena kuwa zai rera adalcinka. ");
INSERT INTO hausa_vpl VALUES ("PS51_15","020_51_15","PSA","51","15","15","Ya Ubangiji, ka buɗe leɓunana, bakina kuwa zai furta yabonka. ");
INSERT INTO hausa_vpl VALUES ("PS51_16","020_51_16","PSA","51","16","16","Ba ka farin ciki a hadaya, ai da na kawo; ba ka jin daɗin hadayun ƙonawa. ");
INSERT INTO hausa_vpl VALUES ("PS51_17","020_51_17","PSA","51","17","17","Hadayun Allah su ne karyayyen ruhu; karyayyiya da kuma zuciya mai tuba, Ya Allah, ba za ka ƙi ba. ");
INSERT INTO hausa_vpl VALUES ("PS51_18","020_51_18","PSA","51","18","18","Cikin jin daɗinka ka sa Sihiyona ta yi nasara; ka gina katangar Urushalima. ");
INSERT INTO hausa_vpl VALUES ("PS51_19","020_51_19","PSA","51","19","19","Ta haka za a kasance da hadayu masu adalci, hadayun ƙonawa ɗungum don su faranta ka; sa’an nan za a miƙa bijimai a bagadenka. ");
INSERT INTO hausa_vpl VALUES ("PS52_1","020_52_1","PSA","52","1","1","Don mai bi da kaɗe-kaɗe. Wani maskil ta Dawuda. Sa’ad da Doyeg mutumin Edom ya tafi wurin Shawulu ya ce masa, “Dawuda ya tafi gidan Ahimelek.” Me ya sa kake fariya game da mugunta, kai babban mutum? Me ya sa kake fariya dukan yini, kai da kake abin kunya a idanun Allah? ");
INSERT INTO hausa_vpl VALUES ("PS52_2","020_52_2","PSA","52","2","2","Harshenka kan shirya hallaka; yana nan kamar reza mai ci, kana ta ruɗu. ");
INSERT INTO hausa_vpl VALUES ("PS52_3","020_52_3","PSA","52","3","3","Kana ƙaunar mugunta fiye da alheri, ƙarya a maimakon faɗin gaskiya. Sela ");
INSERT INTO hausa_vpl VALUES ("PS52_4","020_52_4","PSA","52","4","4","Kana ƙaunar kowace kalmar cutarwa, Ya kai harshe mai ruɗu! ");
INSERT INTO hausa_vpl VALUES ("PS52_5","020_52_5","PSA","52","5","5","Tabbatacce Allah zai kai ka ga madawwamiyar hallaka. Zai fizge ka yă yayyage ka daga tentinka; zai tumɓuke ka daga ƙasar masu rai. Sela ");
INSERT INTO hausa_vpl VALUES ("PS52_6","020_52_6","PSA","52","6","6","Masu adalci za su ga su ji tsoro; za su yi masa dariya, suna cewa, ");
INSERT INTO hausa_vpl VALUES ("PS52_7","020_52_7","PSA","52","7","7","“Yanzu, ga mutumin da bai mai da Allah mafakarsa ba amma ya dogara a yawan arzikinsa ya kuma yi ƙarfi ta wurin hallaka waɗansu!” ");
INSERT INTO hausa_vpl VALUES ("PS52_8","020_52_8","PSA","52","8","8","Amma ni kamar itace zaitun ne ina haɓaka a gidan Allah; na dogara ga ƙauna marar ƙarewa ta Allah har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("PS52_9","020_52_9","PSA","52","9","9","Zan yabe ka har abada game da abin da ka yi; a cikin sunanka zan dogara, gama sunanka yana da kyau. Zan yabe ka a gaban tsarkakanka. ");
INSERT INTO hausa_vpl VALUES ("PS53_1","020_53_1","PSA","53","1","1","Don mai bi da kaɗe-kaɗe. Bisa ga mahalat. Wani maskil na Dawuda. Wawa ne kawai yakan ce a zuciyarsa, “Ba Allah.” Sun lalace, kuma hanyoyinsu ba su da kyau; babu wani mai aikata abu mai kyau. ");
INSERT INTO hausa_vpl VALUES ("PS53_2","020_53_2","PSA","53","2","2","Allah yana duba daga sama a kan ’ya’yan mutane yă ga ko akwai wani wanda ya gane, wani wanda yake neman Allah. ");
INSERT INTO hausa_vpl VALUES ("PS53_3","020_53_3","PSA","53","3","3","Kowa ya kauce, gaba ɗaya sun lalace; babu guda da yake aikata abu mai kyau, babu ko ɗaya. ");
INSERT INTO hausa_vpl VALUES ("PS53_4","020_53_4","PSA","53","4","4","Masu aikata mugunta ba sa taɓa koyo? Suna cin mutanena kamar yadda ake cin burodi, ba sa kuma kira ga Allah. ");
INSERT INTO hausa_vpl VALUES ("PS53_5","020_53_5","PSA","53","5","5","Ga shi fa, sun firgita don tsoro, ko da yake babu dalilin tsoro, gama Allah zai watsar da ƙasusuwan masu ƙinsa, za su sha kunya, gama Allah ya ƙi su. ");
INSERT INTO hausa_vpl VALUES ("PS53_6","020_53_6","PSA","53","6","6","Kash, da ceton Isra’ila zai fito daga Sihiyona mana! Sa’ad da Allah ya sāke arzuta mutanensa, bari Yaƙub yă yi farin ciki Isra’ila kuma yă yi murna! ");
INSERT INTO hausa_vpl VALUES ("PS54_1","020_54_1","PSA","54","1","1","Don mai bi da kaɗe-kaɗe. Da kayan kiɗi masu tsirkiya. Wani maskil ta Dawuda. Sa’ad da Zifawa suka tafi wurin Shawulu suka ce, “Ba Dawuda ba ne yake ɓuya a cikinmu?” Ka cece ni, ya Allah ta wurin sunanka; ka nuna ni marar laifi ne ta wurin ƙarfinka. ");
INSERT INTO hausa_vpl VALUES ("PS54_2","020_54_2","PSA","54","2","2","Ka ji addu’ata, ya Allah; ka saurari maganar bakina. ");
INSERT INTO hausa_vpl VALUES ("PS54_3","020_54_3","PSA","54","3","3","Baƙi suna kawo mini hari; mutane marasa imani suna neman raina, mutanen da ba sa tsoron Allah. Sela ");
INSERT INTO hausa_vpl VALUES ("PS54_4","020_54_4","PSA","54","4","4","Tabbatacce Allah ne mai taimakona, Ubangiji shi ne wanda yake riƙe ni. ");
INSERT INTO hausa_vpl VALUES ("PS54_5","020_54_5","PSA","54","5","5","Bari mugunta ta shaƙe masu magana marar kyau a kaina; cikin amincinka ka hallaka su. ");
INSERT INTO hausa_vpl VALUES ("PS54_6","020_54_6","PSA","54","6","6","Zan miƙa hadaya ta yardar rai gare ka; zan yabe sunanka, ya Ubangiji, gama yana da kyau. ");
INSERT INTO hausa_vpl VALUES ("PS54_7","020_54_7","PSA","54","7","7","Gama ya cece ni daga dukan wahalolina, idanuna kuma sun ga an yi nasara a kan maƙiyana. ");
INSERT INTO hausa_vpl VALUES ("PS55_1","020_55_1","PSA","55","1","1","Don mai bi da kaɗe-kaɗe. Da kayan kiɗi masu tsirkiya. Wani maskil ta Dawuda. Ka ji addu’ata, ya Allah, kada ka ƙyale roƙona; ");
INSERT INTO hausa_vpl VALUES ("PS55_2","020_55_2","PSA","55","2","2","ka ji ni ka kuma amsa mini. Tunanina yana damuna na kuma gaji tilis ");
INSERT INTO hausa_vpl VALUES ("PS55_3","020_55_3","PSA","55","3","3","hankalina ya tashi saboda yawan surutan masu ƙina, saboda danniyar mugaye. Gama sukan jawo mini wahala, suna jin haushina suna ƙina. ");
INSERT INTO hausa_vpl VALUES ("PS55_4","020_55_4","PSA","55","4","4","Zuciyata tana wahala a cikina; tsorace-tsoracen mutuwa sun sha kaina. ");
INSERT INTO hausa_vpl VALUES ("PS55_5","020_55_5","PSA","55","5","5","Tsoro da rawan jiki sun kama ni; razana ta sha kaina. ");
INSERT INTO hausa_vpl VALUES ("PS55_6","020_55_6","PSA","55","6","6","Na ce, “Kash, da a ce ina da fikafikan kurciya mana! Ai, da na yi firiya na tafi na huta, ");
INSERT INTO hausa_vpl VALUES ("PS55_7","020_55_7","PSA","55","7","7","da na tafi can da nisa na zauna a hamada; Sela ");
INSERT INTO hausa_vpl VALUES ("PS55_8","020_55_8","PSA","55","8","8","da na hanzarta na tafi wurin mafakata, nesa da muguwar iska da hadiri.” ");
INSERT INTO hausa_vpl VALUES ("PS55_9","020_55_9","PSA","55","9","9","Ka rikitar da mugaye, ya Ubangiji, ka birkitar da maganarsu, gama na ga rikici da faɗa a cikin birni. ");
INSERT INTO hausa_vpl VALUES ("PS55_10","020_55_10","PSA","55","10","10","Dare da rana suna yawo a kan katanga; mugun hali da zargi suna a cikinta. ");
INSERT INTO hausa_vpl VALUES ("PS55_11","020_55_11","PSA","55","11","11","Rundunar hallaka suna aiki a cikin birni; barazana da ƙarairayi ba sa taɓa barin titunanta. ");
INSERT INTO hausa_vpl VALUES ("PS55_12","020_55_12","PSA","55","12","12","Da a ce abokin gāba ne ke zagina, da na jure da shi; da a ce maƙiyi yana tā da kansa a kaina, da na ɓoye daga gare shi. ");
INSERT INTO hausa_vpl VALUES ("PS55_13","020_55_13","PSA","55","13","13","Amma kai ne, mutum kamar ni, abokina, abokina na kurkusa, ");
INSERT INTO hausa_vpl VALUES ("PS55_14","020_55_14","PSA","55","14","14","wanda na taɓa jin daɗin zumunci da shi sosai yayinda muke tafiya tare a taron jama’a a gidan Allah. ");
INSERT INTO hausa_vpl VALUES ("PS55_15","020_55_15","PSA","55","15","15","Bari mutuwa ta ɗauki abokan gābana ba labari; bari su gangara da rai zuwa cikin kabari, gama mugunta tana samun masauƙi a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("PS55_16","020_55_16","PSA","55","16","16","Amma na kira ga Allah, Ubangiji kuwa ya cece ni. ");
INSERT INTO hausa_vpl VALUES ("PS55_17","020_55_17","PSA","55","17","17","Safe, rana da yamma ina kuka da nishi, yakan kuwa ji muryata. ");
INSERT INTO hausa_vpl VALUES ("PS55_18","020_55_18","PSA","55","18","18","Yakan fisshe ni lafiya daga yaƙin da ake yi da ni, ko da yake da yawa suna gāba da ni. ");
INSERT INTO hausa_vpl VALUES ("PS55_19","020_55_19","PSA","55","19","19","Allah, yana mulki har abada, zai ji su yă kuma azabtar da su, Sela mutanen da ba sa taɓa canja hanyoyinsu kuma ba sa tsoron Allah. ");
INSERT INTO hausa_vpl VALUES ("PS55_20","020_55_20","PSA","55","20","20","Abokina ya kai wa abokansa hari; ya tā da alkawarinsa. ");
INSERT INTO hausa_vpl VALUES ("PS55_21","020_55_21","PSA","55","21","21","Maganarsa tana da laushi kamar man zaitun, duk da haka yaƙi yana a cikin zuciyarsa; kalmominsa sun fi mai sulɓi, duk da haka takuba ne zārarru. ");
INSERT INTO hausa_vpl VALUES ("PS55_22","020_55_22","PSA","55","22","22","Ku kawo damuwoyinku ga Ubangiji zai kuwa riƙe ku; ba zai taɓa barin mai adalci yă fāɗi ba. ");
INSERT INTO hausa_vpl VALUES ("PS55_23","020_55_23","PSA","55","23","23","Amma kai, ya Allah, za ka kawar da mugaye zuwa cikin ramin lalacewa; masu kisa da mutane masu ruɗu ba za su kai rabin kwanakin rayuwarsu ba. Amma ni dai, na dogara gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS56_1","020_56_1","PSA","56","1","1","Don mai bi da kaɗe-kaɗe. Da murya “Kurciya a Itatuwan Oak Mai Nisa.” Ta Dawuda. Wani miktam. Sa’ad da Filistiyawa suka kama shi a birnin Gat. Ka yi mini jinƙai, ya Allah, gama mutane sun tasar mini da zafi; dukan yini suna matsa harinsu. ");
INSERT INTO hausa_vpl VALUES ("PS56_2","020_56_2","PSA","56","2","2","Masu ɓata sunana suna bina dukan yini; da yawa suna kai mini hari cikin fariyarsu. ");
INSERT INTO hausa_vpl VALUES ("PS56_3","020_56_3","PSA","56","3","3","Sa’ad da nake tsoro, zan dogara gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS56_4","020_56_4","PSA","56","4","4","Ga Allah wanda maganarsa nake yabo ga Allah na dogara; ba zan ji tsoro ba. Me mutum mai mutuwa zai yi mini? ");
INSERT INTO hausa_vpl VALUES ("PS56_5","020_56_5","PSA","56","5","5","Dukan yini sun yi ta juya maganata; kullum suna ƙulle-ƙulle su cuce ni. ");
INSERT INTO hausa_vpl VALUES ("PS56_6","020_56_6","PSA","56","6","6","Sun haɗa baki, sun ɓoye, suna kallon takawata suna a shirye su ɗauki raina. ");
INSERT INTO hausa_vpl VALUES ("PS56_7","020_56_7","PSA","56","7","7","Sam, kada ka bari su kuɓuce; cikin fushinka, ya Allah, ka saukar da al’ummai. ");
INSERT INTO hausa_vpl VALUES ("PS56_8","020_56_8","PSA","56","8","8","Ka lissafta makokina; ka jera hawayena a littafinka, ba a rubuce suke a cikin littafinka ba? ");
INSERT INTO hausa_vpl VALUES ("PS56_9","020_56_9","PSA","56","9","9","Ta haka abokan gābana za su juya da baya sa’ad da na nemi taimako. Ta haka zan san cewa Allah yana tare da ni. ");
INSERT INTO hausa_vpl VALUES ("PS56_10","020_56_10","PSA","56","10","10","Ga Allah, wanda nake yabon maganarsa, ga Ubangiji, wanda nake yabon maganarsa, ");
INSERT INTO hausa_vpl VALUES ("PS56_11","020_56_11","PSA","56","11","11","ga Allah na dogara; ba zan ji tsoro ba. Me mutum zai iya yi mini? ");
INSERT INTO hausa_vpl VALUES ("PS56_12","020_56_12","PSA","56","12","12","Ina ƙarƙashin alkawari gare ka, ya Allah; zan miƙa hadayuna na godiya gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS56_13","020_56_13","PSA","56","13","13","Gama ka cece ni daga mutuwa da kuma ƙafafun daga tuntuɓe, don in yi tafiya a gaban Allah cikin hasken rai. ");
INSERT INTO hausa_vpl VALUES ("PS57_1","020_57_1","PSA","57","1","1","Don mai bi da kaɗe-kaɗe. Da muryar “Kada Ka Hallaka.” Ta Dawuda. Wani miktam. Sa’ad da ya gudu daga Shawulu zuwa cikin kogo. Ka yi mini jinƙai, ya Allah, ka yi mini jinƙai, gama a gare ka raina yake samun mafaka. Zan sami mafaka a inuwar fikafikanka sai masifar ta wuce. ");
INSERT INTO hausa_vpl VALUES ("PS57_2","020_57_2","PSA","57","2","2","Na yi kuka ga Allah Mafi Ɗaukaka, ga Allah, wanda yake cika manufarsa gare ni. ");
INSERT INTO hausa_vpl VALUES ("PS57_3","020_57_3","PSA","57","3","3","Ya aika daga sama ya kuwa cece ni, yana tsawata wa waɗanda suke fafarata da zafi; Sela Allah yakan aika da ƙaunarsa da amincinsa. ");
INSERT INTO hausa_vpl VALUES ("PS57_4","020_57_4","PSA","57","4","4","Ina tsakiyar zakoki; ina kwance a cikin namun jeji masu cin mutane, mutanen da haƙoransu masu ne da kuma kibiyoyi, waɗanda harshensu suna da kaifi kamar takobi. ");
INSERT INTO hausa_vpl VALUES ("PS57_5","020_57_5","PSA","57","5","5","Bari a ɗaukaka ka, ya Allah, bisa sammai; bari ɗaukakarka ta kasance a dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS57_6","020_57_6","PSA","57","6","6","Sun shimfiɗa raga don su kama ƙafafuna, damuwa ta sha ƙarfina. Sun haƙa rami a hanyata, amma su kansu suka fāɗa a cikinta. Sela ");
INSERT INTO hausa_vpl VALUES ("PS57_7","020_57_7","PSA","57","7","7","Zuciyata tana nan daram, ya Allah, zuciyata tana nan daram; zan rera in kuma yi kaɗe-kaɗe. ");
INSERT INTO hausa_vpl VALUES ("PS57_8","020_57_8","PSA","57","8","8","Ka farka, raina! Ku farka, garaya da molo! Zan sa safe yă farka. ");
INSERT INTO hausa_vpl VALUES ("PS57_9","020_57_9","PSA","57","9","9","Zan yabe ka, ya Ubangiji, a cikin al’ummai; zan rera game da kai a cikin mutane. ");
INSERT INTO hausa_vpl VALUES ("PS57_10","020_57_10","PSA","57","10","10","Gama ƙaunarka mai girma ce, tana kaiwa sammai; amincinka na kaiwa sarari. ");
INSERT INTO hausa_vpl VALUES ("PS57_11","020_57_11","PSA","57","11","11","Bari a ɗaukaka ka, ya Allah, bisa sammai; bari ɗaukakarka ta kasance a dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS58_1","020_58_1","PSA","58","1","1","Don mai bi da kaɗe-kaɗe. Da muryar “Kada Ka Hallaka.” Ta Dawuda. Wani miktam. Ku masu mulki tabbatacce kuna magana daidai? Kuna yin shari’a daidai a cikin mutane? ");
INSERT INTO hausa_vpl VALUES ("PS58_2","020_58_2","PSA","58","2","2","Sam, a zuciyarku kuna ƙirƙiro rashin adalci, da hannuwanku kuma kuna tā da hargitsi a duniya. ");
INSERT INTO hausa_vpl VALUES ("PS58_3","020_58_3","PSA","58","3","3","Kai, tun haihuwa mugaye sukan kauce; daga cikin ciki, su lalatattu ne maƙaryata. ");
INSERT INTO hausa_vpl VALUES ("PS58_4","020_58_4","PSA","58","4","4","Dafinsu ya yi kamar dafin maciji, kamar na gamsheƙan da ya toshe kunnuwansa, ");
INSERT INTO hausa_vpl VALUES ("PS58_5","020_58_5","PSA","58","5","5","da ba ya jin muryar gardi, kome dabarar gwanin mai waƙar zai zama. ");
INSERT INTO hausa_vpl VALUES ("PS58_6","020_58_6","PSA","58","6","6","Ka kakkarya haƙoran a bakunansu, ya Allah; ka yayyage fiƙoƙin zakoki, ya Ubangiji! ");
INSERT INTO hausa_vpl VALUES ("PS58_7","020_58_7","PSA","58","7","7","Bari su ɓace kamar ruwa mai wucewa; sa’ad da suka ja bakansu, bari kibiyoyinsu su murtsuke. ");
INSERT INTO hausa_vpl VALUES ("PS58_8","020_58_8","PSA","58","8","8","Kamar katantanwun da suke narkewa yayinda suke tafiya, kamar jinjirin da aka haifa matacce, kada su ga hasken rana. ");
INSERT INTO hausa_vpl VALUES ("PS58_9","020_58_9","PSA","58","9","9","Kafin tukwanenka su ji zafin ƙayayyuwa, ko su kore ne ko busasshe, za a shafe mugaye. ");
INSERT INTO hausa_vpl VALUES ("PS58_10","020_58_10","PSA","58","10","10","Masu adalci za su yi murna sa’ad da aka rama musu, sa’ad da suka wanke ƙafafunsu cikin jinin mugaye. ");
INSERT INTO hausa_vpl VALUES ("PS58_11","020_58_11","PSA","58","11","11","Sa’an nan mutane za su ce, “Tabbatacce har yanzu ana sāka wa adalai; tabbatacce akwai Allahn da yake shari’anta duniya.” ");
INSERT INTO hausa_vpl VALUES ("PS59_1","020_59_1","PSA","59","1","1","Don mai bi da kaɗe-kaɗe. Da muryar “Kada Ka Hallaka.” Ta Dawuda. Wani miktam. Sa’ad da Shawulu ya aiki mutane su yi tsaron gidan Dawuda don yă kashe shi. Ka cece ni daga abokan gābana, ya Allah; ka tsare ni daga waɗanda suka tayar mini. ");
INSERT INTO hausa_vpl VALUES ("PS59_2","020_59_2","PSA","59","2","2","Ka kuɓutar da ni daga masu aikata mugunta ka kuma cece ni daga masu kisa. ");
INSERT INTO hausa_vpl VALUES ("PS59_3","020_59_3","PSA","59","3","3","Duba yadda suka kwanta suna jirana! Mugaye suna ƙulle-ƙullen gāba da ni ba saboda wani dalili ko na yi wa wani zunubi ba, ya Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS59_4","020_59_4","PSA","59","4","4","Ban yi wani laifi ba, duk da haka suna a shirye su fāɗa mini. Tashi ka taimake ni; dubi halin da nake ciki! ");
INSERT INTO hausa_vpl VALUES ("PS59_5","020_59_5","PSA","59","5","5","Ya Ubangiji Allah Maɗaukaki, Allah na Isra’ila, ka tashi ka hukunta dukan al’ummai; kada ka nuna jinƙai ga mugaye maciya amana. Sela ");
INSERT INTO hausa_vpl VALUES ("PS59_6","020_59_6","PSA","59","6","6","Sukan dawo da yamma, suna wage haƙora kamar karnuka, suna yawo a birni. ");
INSERT INTO hausa_vpl VALUES ("PS59_7","020_59_7","PSA","59","7","7","Dubi abin da suke tofawa daga bakunansu, suna tofar da takuba daga leɓunansu, suna cewa, “Wa zai ji mu?” ");
INSERT INTO hausa_vpl VALUES ("PS59_8","020_59_8","PSA","59","8","8","Amma kai, ya Ubangiji, kakan yi musu dariya; kana yi wa dukan waɗannan al’ummai ba’a. ");
INSERT INTO hausa_vpl VALUES ("PS59_9","020_59_9","PSA","59","9","9","Ya ƙarfina, na dogara gare ka; kai, ya Allah, kai ne kagarata, ");
INSERT INTO hausa_vpl VALUES ("PS59_10","020_59_10","PSA","59","10","10","Allah mai ƙaunata. Allah zai sha gabana zai kuma sa in yi dariya a kan waɗanda suke magana marar kyau a kaina. ");
INSERT INTO hausa_vpl VALUES ("PS59_11","020_59_11","PSA","59","11","11","Amma kada ka kashe su, ya Ubangiji garkuwarmu, in ba haka mutanena za su manta. Cikin ikonka ka sa su yi ta yawo barkatai, ka kuma kawar da su. ");
INSERT INTO hausa_vpl VALUES ("PS59_12","020_59_12","PSA","59","12","12","Saboda zunuban bakunansu, saboda maganganun leɓunansu, bari a kama su cikin fariyarsu. Saboda zage-zage da ƙarairayin da suke yi, ");
INSERT INTO hausa_vpl VALUES ("PS59_13","020_59_13","PSA","59","13","13","ka cinye su da hasala, ka cinye su sarai. Sa’an nan za a sani a iyakar duniya cewa Allah yana mulki a bisa Yaƙub. Sela ");
INSERT INTO hausa_vpl VALUES ("PS59_14","020_59_14","PSA","59","14","14","Sukan dawo da yamma, suna wage haƙora kamar karnuka, suna yawo a birni. ");
INSERT INTO hausa_vpl VALUES ("PS59_15","020_59_15","PSA","59","15","15","Suna ta yawo neman abinci su kuwa yi haushi in ba su ƙoshi ba. ");
INSERT INTO hausa_vpl VALUES ("PS59_16","020_59_16","PSA","59","16","16","Amma zan rera game da ƙarfinka, da safe zan rera game da ƙaunarka; gama kai ne mafakata, kagarata a lokacin wahala. ");
INSERT INTO hausa_vpl VALUES ("PS59_17","020_59_17","PSA","59","17","17","Ya ƙarfina, na rera yabo gare ka; kai, ya Allah, kai ne kagarata, Allah mai ƙaunata. ");
INSERT INTO hausa_vpl VALUES ("PS60_1","020_60_1","PSA","60","1","1","Don mai bi da kaɗe-kaɗe. Da muryar “Lilin Alkawari.” Wani miktam ta Dawuda. Don koyarwa. Sa’ad da ya yaƙi Aram-Naharayim da Aram-Zoba, da kuma sa’ad da Yowab ya dawo ya bugi mutanen Edom dubu goma sha biyu a Kwarin Gishiri. Ka ki mu, ya Allah, ka kuma fashe kāriyarmu; ka yi fushi da mu, yanzu ka mai da mu! ");
INSERT INTO hausa_vpl VALUES ("PS60_2","020_60_2","PSA","60","2","2","Ka girgiza ƙasar ka kuma tsaga ta; ka daure karayarta, gama tana rawa. ");
INSERT INTO hausa_vpl VALUES ("PS60_3","020_60_3","PSA","60","3","3","Ka nuna wa mutanenka lokutan wahala; ka ba mu ruwan inabin da ya sa muka bugu. ");
INSERT INTO hausa_vpl VALUES ("PS60_4","020_60_4","PSA","60","4","4","Amma ga waɗanda suke tsoronka, ka ɗaga tuta don a buɗe gāba da baka. Sela ");
INSERT INTO hausa_vpl VALUES ("PS60_5","020_60_5","PSA","60","5","5","Ka cece mu ka kuma taimake mu da hannunka na dama, domin waɗanda kake ƙauna su kuɓuta. ");
INSERT INTO hausa_vpl VALUES ("PS60_6","020_60_6","PSA","60","6","6","Allah ya yi magana daga wurinsa mai tsarki, “Da nasara zan rarraba Shekem in kuma auna Kwarin Sukkot. ");
INSERT INTO hausa_vpl VALUES ("PS60_7","020_60_7","PSA","60","7","7","Gileyad nawa ne, Manasse kuma nawa ne; Efraim shi ne hular kwanona, Yahuda kuma sandar mulkina. ");
INSERT INTO hausa_vpl VALUES ("PS60_8","020_60_8","PSA","60","8","8","Mowab shi ne kwanon wankina, a kan Edom zan jefa takalmina; a bisa Filistiya zan yi kirarin nasara.” ");
INSERT INTO hausa_vpl VALUES ("PS60_9","020_60_9","PSA","60","9","9","Wa zai kawo ni birnin katanga? Wa zai bishe ni zuwa Edom? ");
INSERT INTO hausa_vpl VALUES ("PS60_10","020_60_10","PSA","60","10","10","Ba kai ba ne, ya Allah, kai da ka ƙi mu ba ka kuwa fita tare da mayaƙanmu? ");
INSERT INTO hausa_vpl VALUES ("PS60_11","020_60_11","PSA","60","11","11","Ka ba mu gudummawa a kan abokin gāba, gama taimakon mutum banza ne. ");
INSERT INTO hausa_vpl VALUES ("PS60_12","020_60_12","PSA","60","12","12","Tare da Allah za mu yi nasara, zai kuma tattake abokan gābanmu. ");
INSERT INTO hausa_vpl VALUES ("PS61_1","020_61_1","PSA","61","1","1","Don mai bi da kaɗe-kaɗe. Da kayan kiɗi masu tsirkiya. Ta Dawuda. Ka ji kukata, ya Allah; ka saurari addu’ata. ");
INSERT INTO hausa_vpl VALUES ("PS61_2","020_61_2","PSA","61","2","2","Daga iyakar duniya na yi kira gare ka, na yi kira yayinda zuciyata ta karai; ka bishe ni zuwa dutsen da ya fi ni tsayi. ");
INSERT INTO hausa_vpl VALUES ("PS61_3","020_61_3","PSA","61","3","3","Gama kai ne mafakata, hasumiya mai ƙarfi gāba da maƙiyi. ");
INSERT INTO hausa_vpl VALUES ("PS61_4","020_61_4","PSA","61","4","4","Ina marmari in zauna a tentinka har abada in sami mafaka a cikin inuwar fikafikanka. Sela ");
INSERT INTO hausa_vpl VALUES ("PS61_5","020_61_5","PSA","61","5","5","Gama ka ji alkawarina, ya Allah; ka ba ni gādo na waɗanda suke tsoron sunanka. ");
INSERT INTO hausa_vpl VALUES ("PS61_6","020_61_6","PSA","61","6","6","Ka ƙara kwanakin ran sarki, shekarunsa su kasance a zamanai masu yawa. ");
INSERT INTO hausa_vpl VALUES ("PS61_7","020_61_7","PSA","61","7","7","Bari yă yi mulki a gaban Allah har abada; ka sa ƙaunarka da amincinka su tsare shi. ");
INSERT INTO hausa_vpl VALUES ("PS61_8","020_61_8","PSA","61","8","8","Sa’an nan zan riƙa rera yabo ga sunanka in kuma cika alkawarina kowace rana. ");
INSERT INTO hausa_vpl VALUES ("PS62_1","020_62_1","PSA","62","1","1","Don mai bi da kaɗe-kaɗe. Don Yedutun. Zaburar Dawuda. Raina na samun hutu a wurin Allah ne kaɗai; cetona na zuwa daga gare shi. ");
INSERT INTO hausa_vpl VALUES ("PS62_2","020_62_2","PSA","62","2","2","Shi kaɗai ne dutsena da cetona; shi ne kagarata, ba zan jijjigu ba. ");
INSERT INTO hausa_vpl VALUES ("PS62_3","020_62_3","PSA","62","3","3","Har yaushe za ku tasar wa mutum guda? Dukanku ne za ku kā da shi wannan jinganannen bango, wannan rusasshen katanga? ");
INSERT INTO hausa_vpl VALUES ("PS62_4","020_62_4","PSA","62","4","4","Sun kintsa sosai su tumɓuke shi daga matsayinsa mai martaba; suna jin daɗi yin ƙarairayi. Sukan sa wa mutum albarka da bakinsu, amma a zuciyarsu la’antawa suke yi. Sela ");
INSERT INTO hausa_vpl VALUES ("PS62_5","020_62_5","PSA","62","5","5","Ka nemi hutu, ya raina, a wurin Allah kaɗai; dogarata kan zo daga gare shi ne. ");
INSERT INTO hausa_vpl VALUES ("PS62_6","020_62_6","PSA","62","6","6","Shi ne kaɗai dutsena da cetona; shi ne kagarata, ba zan jijjigu ba. ");
INSERT INTO hausa_vpl VALUES ("PS62_7","020_62_7","PSA","62","7","7","Cetona da girmata sun dangana ga Allah ne, shi ne dutsena mai ƙarfi, mafakata. ");
INSERT INTO hausa_vpl VALUES ("PS62_8","020_62_8","PSA","62","8","8","Ku dogara a gare shi a duk lokuta, ya mutane; ku faɗi albarkaci bakin zukatanku a gare shi, gama Allah ne mafakarmu. Sela ");
INSERT INTO hausa_vpl VALUES ("PS62_9","020_62_9","PSA","62","9","9","Talakawa dai kamar shaƙar iska suke, Attajirai dai kamar shirim suke; in aka auna a ma’auni, su ba wani abu ba ne; dukansu dai kamar shaƙar iska ne kawai. ");
INSERT INTO hausa_vpl VALUES ("PS62_10","020_62_10","PSA","62","10","10","Kada ku dogara a kan ƙwace ko yin fariya a kayan sata; ko arzikinku ya ƙaru, kada ku sa zuciyarku a kansu. ");
INSERT INTO hausa_vpl VALUES ("PS62_11","020_62_11","PSA","62","11","11","Abu guda Allah ya ce, abubuwa biyu na ji, “Cewa kai, ya Allah, kake mai ƙarfi, ");
INSERT INTO hausa_vpl VALUES ("PS62_12","020_62_12","PSA","62","12","12","kuma cewa kai, ya Ubangiji, mai ƙauna ne. Tabbatacce za ka sāka wa kowane mutum bisa ga abin da ya yi.” ");
INSERT INTO hausa_vpl VALUES ("PS63_1","020_63_1","PSA","63","1","1","Zabura ta Dawuda. Sa’ad da yake a hamadar Yahuda. Ya Allah, kai ne Allahna, da nacewa na neme ka; raina yana ƙishinka, jikina yana marmarinka, cikin busasshiyar ƙasar da ta zozaye inda babu ruwa. ");
INSERT INTO hausa_vpl VALUES ("PS63_2","020_63_2","PSA","63","2","2","Na gan ka a wuri mai tsarki na kuma dubi ikonka da ɗaukakarka. ");
INSERT INTO hausa_vpl VALUES ("PS63_3","020_63_3","PSA","63","3","3","Domin ƙaunarka ta fi rai kyau, leɓunana za su ɗaukaka ka. ");
INSERT INTO hausa_vpl VALUES ("PS63_4","020_63_4","PSA","63","4","4","Zan yabe ka muddin raina, kuma a cikin sunanka zai ɗaga hannuwana. ");
INSERT INTO hausa_vpl VALUES ("PS63_5","020_63_5","PSA","63","5","5","Raina zai ƙoshi kamar da abinci mafi kyau; da leɓunan rerawa bakina zai yabe ka. ");
INSERT INTO hausa_vpl VALUES ("PS63_6","020_63_6","PSA","63","6","6","A gadona na tuna da kai; ina tunaninka dukan dare. ");
INSERT INTO hausa_vpl VALUES ("PS63_7","020_63_7","PSA","63","7","7","Domin kai ne mai taimakona, ina rera a cikin inuwar fikafikanka. ");
INSERT INTO hausa_vpl VALUES ("PS63_8","020_63_8","PSA","63","8","8","Raina ya manne maka; hannunka na dama yana riƙe da ni. ");
INSERT INTO hausa_vpl VALUES ("PS63_9","020_63_9","PSA","63","9","9","Su da suke neman raina za su hallaka; za su gangara zuwa zurfafan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS63_10","020_63_10","PSA","63","10","10","Za a bayar da su ga takobi su kuma zama abincin karnukan jeji. ");
INSERT INTO hausa_vpl VALUES ("PS63_11","020_63_11","PSA","63","11","11","Amma sarki zai yi farin ciki ga Allah; dukan waɗanda suke rantse da sunan Allah za su yabe shi, amma za a rufe bakunan maƙaryata. ");
INSERT INTO hausa_vpl VALUES ("PS64_1","020_64_1","PSA","64","1","1","Don mai bi da kaɗe-kaɗe. Zabura ta Dawuda. Ka ji ni, ya Allah, yayinda nake faɗin abin da yake damuna; ka tsare raina daga barazanan abokin gāba. ");
INSERT INTO hausa_vpl VALUES ("PS64_2","020_64_2","PSA","64","2","2","Ka ɓoye ni daga ƙulle-ƙullen mugaye, daga daure dauren wannan taro masu aikata mugunta. ");
INSERT INTO hausa_vpl VALUES ("PS64_3","020_64_3","PSA","64","3","3","Sukan wāsa harsunansu kamar takuba su harba kalmominsu kamar kibiyoyi masu kisa. ");
INSERT INTO hausa_vpl VALUES ("PS64_4","020_64_4","PSA","64","4","4","Sukan yin kwanto su harbi marar laifi; sukan yi harbi nan da nan, ba tsoro. ");
INSERT INTO hausa_vpl VALUES ("PS64_5","020_64_5","PSA","64","5","5","Sukan ƙarfafa juna a mugayen ƙulle-ƙullensu, sukan yi magana yadda za su ɓoye tarkunansu; su ce, “Wa zai gan su?” ");
INSERT INTO hausa_vpl VALUES ("PS64_6","020_64_6","PSA","64","6","6","Sukan yi ƙulle-ƙullen rashin adalci su ce, “Mun gama ƙulla cikakkiyar maƙarƙashiya tsab!” Zuciyar mutum da tunaninsa, suna da wuyar ganewa. ");
INSERT INTO hausa_vpl VALUES ("PS64_7","020_64_7","PSA","64","7","7","Amma Allah zai harbe su da kibiyoyi; nan da nan za a buge su su fāɗi. ");
INSERT INTO hausa_vpl VALUES ("PS64_8","020_64_8","PSA","64","8","8","Zai juya harshensu a kansu yă kuma kawo su ga hallaka; duk waɗanda suka gan su za su kaɗa kai, suna musu ba’a. ");
INSERT INTO hausa_vpl VALUES ("PS64_9","020_64_9","PSA","64","9","9","Dukan mutane za su ji tsoro; za su yi shelar ayyukan Allah su kuma yi tunanin abin da ya aikata. ");
INSERT INTO hausa_vpl VALUES ("PS64_10","020_64_10","PSA","64","10","10","Bari masu adalci su yi farin ciki a cikin Ubangiji su kuma nemi mafaka a gare shi; bari dukan masu gaskiya a zuciya su yabe shi! ");
INSERT INTO hausa_vpl VALUES ("PS65_1","020_65_1","PSA","65","1","1","Don mai bi da kaɗe-kaɗe. Zabura ta Dawuda. Wata waƙa. Yabo ya dace da kai, ya Allah, a Sihiyona; a gare ka za mu cika alkawuranmu ");
INSERT INTO hausa_vpl VALUES ("PS65_2","020_65_2","PSA","65","2","2","Ya kai wanda yake jin addu’a a gare ka dukan mutane za su zo. ");
INSERT INTO hausa_vpl VALUES ("PS65_3","020_65_3","PSA","65","3","3","Sa’ad da zunubai suka sha ƙarfinmu, ka gafarta laifofinmu. ");
INSERT INTO hausa_vpl VALUES ("PS65_4","020_65_4","PSA","65","4","4","Masu albarka ne waɗanda ka zaɓa ka kawo kusa don su zauna a filayenka! Mun cika da abubuwa masu kyau na gidanka, na haikalinka mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("PS65_5","020_65_5","PSA","65","5","5","Ka amsa mana da ayyuka masu banmamaki na adalci, Ya Allah Mai Cetonmu, begen dukan iyakar duniya da kuma na tekuna masu nesa, ");
INSERT INTO hausa_vpl VALUES ("PS65_6","020_65_6","PSA","65","6","6","wanda ya yi duwatsu ta wurin ikonka, bayan ka kintsa kanka da ƙarfi, ");
INSERT INTO hausa_vpl VALUES ("PS65_7","020_65_7","PSA","65","7","7","wanda ya kwantar da rurin tekuna, rurin raƙumansu, da kuma tumbatsar al’ummai. ");
INSERT INTO hausa_vpl VALUES ("PS65_8","020_65_8","PSA","65","8","8","Waɗanda suke zama can da nesa sukan ji tsoron manyan ayyukanka; inda safe ke haskaka yamma kuma ta shuɗe kakan sa a yi waƙoƙin farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS65_9","020_65_9","PSA","65","9","9","Kana kula da ƙasa kana kuma yi mata banruwa; kana azurta ta a yalwace. Rafuffukan Allah sun cika da ruwa don su ba mutane hatsi, don haka ne ka ƙaddara. ");
INSERT INTO hausa_vpl VALUES ("PS65_10","020_65_10","PSA","65","10","10","Ka kwarara ta da ruwa ka kuma baje kunyoyinta; ka sa ta yi laushi da yayyafi ka kuma albarkaci tsire-tsirenta. ");
INSERT INTO hausa_vpl VALUES ("PS65_11","020_65_11","PSA","65","11","11","Saboda alherinka, ya Allah, an sami kaka mai albarka, amalankenka kuwa sun cika har suna zuba. ");
INSERT INTO hausa_vpl VALUES ("PS65_12","020_65_12","PSA","65","12","12","Makiyayan hamada sun cika har suna zuba; tuddai sun rufu da murna. ");
INSERT INTO hausa_vpl VALUES ("PS65_13","020_65_13","PSA","65","13","13","Wurin dausayin kiwo sun rufu da garkuna kwari kuma sun cika da hatsi; suna sowa don farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS66_1","020_66_1","PSA","66","1","1","Don mai bi da kaɗe-kaɗe. Zabura ta Dawuda. Waƙa. Zabura. Ku yi sowa ta farin ciki ga Allah, dukan duniya! ");
INSERT INTO hausa_vpl VALUES ("PS66_2","020_66_2","PSA","66","2","2","Ku rera ɗaukaka ga sunansa; ku sa yabonsa yă zama da ɗaukaka! ");
INSERT INTO hausa_vpl VALUES ("PS66_3","020_66_3","PSA","66","3","3","Ku ce wa Allah, “Ayyukanka da banmamaki suke! Ikonka da girma yake har abokan gābanka suna durƙusa a gabanka. ");
INSERT INTO hausa_vpl VALUES ("PS66_4","020_66_4","PSA","66","4","4","Dukan duniya sun rusuna a gabanka suna rera yabo gare ka, suna rera yabo ga sunanka.” Sela ");
INSERT INTO hausa_vpl VALUES ("PS66_5","020_66_5","PSA","66","5","5","Ku zo ku ga abin da Allah ya yi, ayyukansa masu banmamaki a madadin mutum! ");
INSERT INTO hausa_vpl VALUES ("PS66_6","020_66_6","PSA","66","6","6","Ya juya teku zuwa busasshiyar ƙasa, sun wuce cikin ruwaye da ƙafa, ku zo, mu yi farin ciki a cikinsa. ");
INSERT INTO hausa_vpl VALUES ("PS66_7","020_66_7","PSA","66","7","7","Yana mulki har abada ta wurin ikonsa, idanunsa suna duban al’ummai, kada ’yan tawaye su tayar masa. Sela ");
INSERT INTO hausa_vpl VALUES ("PS66_8","020_66_8","PSA","66","8","8","Ku yabi Allahnku, ya mutane, bari a ji ƙarar yabonsa; ");
INSERT INTO hausa_vpl VALUES ("PS66_9","020_66_9","PSA","66","9","9","ya adana rayukanmu ya kuma kiyaye ƙafafunmu daga santsi. ");
INSERT INTO hausa_vpl VALUES ("PS66_10","020_66_10","PSA","66","10","10","Gama kai, ya Allah, ka gwada mu; ka tace mu kamar azurfa. ");
INSERT INTO hausa_vpl VALUES ("PS66_11","020_66_11","PSA","66","11","11","Ka kawo mu cikin kurkuku ka kuma jibga kaya masu nauyi a bayanmu. ");
INSERT INTO hausa_vpl VALUES ("PS66_12","020_66_12","PSA","66","12","12","Ka bar mutane suka hau a kawunanmu; mun bi ta wuta da ruwa, amma ka kawo mu zuwa wurin yalwa. ");
INSERT INTO hausa_vpl VALUES ("PS66_13","020_66_13","PSA","66","13","13","Zan zo haikalinka da hadayun ƙonawa zan kuwa cika alkawurana gare ka, ");
INSERT INTO hausa_vpl VALUES ("PS66_14","020_66_14","PSA","66","14","14","alkawuran da leɓunana suka yi alkawari bakina kuma ya faɗa sa’ad da nake cikin wahala. ");
INSERT INTO hausa_vpl VALUES ("PS66_15","020_66_15","PSA","66","15","15","Zan miƙa kitsen dabbobi gare ka da kuma baye-baye na raguna; zan miƙa bijimai da awaki. Sela ");
INSERT INTO hausa_vpl VALUES ("PS66_16","020_66_16","PSA","66","16","16","Ku zo ku saurara, dukanku waɗanda suke tsoron Allah; bari in faɗa muku abin da ya yi mini. ");
INSERT INTO hausa_vpl VALUES ("PS66_17","020_66_17","PSA","66","17","17","Na yi kuka gare shi da bakina; yabonsa yana a harshena. ");
INSERT INTO hausa_vpl VALUES ("PS66_18","020_66_18","PSA","66","18","18","Da a ce na ji daɗin zunubi a zuciyata, da Ubangiji ba zai saurara ba; ");
INSERT INTO hausa_vpl VALUES ("PS66_19","020_66_19","PSA","66","19","19","amma tabbatacce Allah ya saurara ya kuma ji muryata a cikin addu’a. ");
INSERT INTO hausa_vpl VALUES ("PS66_20","020_66_20","PSA","66","20","20","Yabo ga Allah, wanda bai ƙi addu’ata ba ko yă janye ƙaunarsa daga gare ni! ");
INSERT INTO hausa_vpl VALUES ("PS67_1","020_67_1","PSA","67","1","1","Don mai bi da kaɗe-kaɗe. Tare da kayan kiɗi masu tsirkiya. Zabura. Waƙa. Bari Allah yă yi mana alheri yă kuma albarkace mu yă kuma sa fuskarsa ta haskaka a kanmu, Sela ");
INSERT INTO hausa_vpl VALUES ("PS67_2","020_67_2","PSA","67","2","2","don a san hanyoyinka a duniya, cetonka kuma a cikin dukan al’ummai. ");
INSERT INTO hausa_vpl VALUES ("PS67_3","020_67_3","PSA","67","3","3","Bari mutane su yabe ka, ya Allah; bari dukan mutane su yabe ka. ");
INSERT INTO hausa_vpl VALUES ("PS67_4","020_67_4","PSA","67","4","4","Bari al’ummai su yi murna su kuma rera don farin ciki, gama kana mulkin mutanenka da adalci kana kuma bi da al’umman duniya. Sela ");
INSERT INTO hausa_vpl VALUES ("PS67_5","020_67_5","PSA","67","5","5","Bari mutane su yabe ka, ya Allah; bari dukan mutane su yabe. ");
INSERT INTO hausa_vpl VALUES ("PS67_6","020_67_6","PSA","67","6","6","Sa’an nan ƙasa za tă ba da girbinta Allah kuma, Allahnmu, zai albarkace mu. ");
INSERT INTO hausa_vpl VALUES ("PS67_7","020_67_7","PSA","67","7","7","Allah yă sa mana albarka, dukan iyakar duniya kuma su ji tsoronsa. ");
INSERT INTO hausa_vpl VALUES ("PS68_1","020_68_1","PSA","68","1","1","Don mai bi da kaɗe-kaɗe. Ta Dawuda. Zabura. Waƙa. Bari Allah yă tashi, bari a watsar da abokan gābansa; bari maƙiyansa su gudu a gabansa. ");
INSERT INTO hausa_vpl VALUES ("PS68_2","020_68_2","PSA","68","2","2","Kamar yadda iska take hura hayaƙi, bari yă hura su haka; kamar yadda kaki kan narke a gaban wuta, bari mugaye su hallaka a gaban Allah. ");
INSERT INTO hausa_vpl VALUES ("PS68_3","020_68_3","PSA","68","3","3","Amma bari adalai su yi murna su kuma yi farin ciki a gaban Allah; bari su yi murna da farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS68_4","020_68_4","PSA","68","4","4","Rera wa Allah, rera yabo ga sunansa, ku ɗaukaka wanda yake hawa a kan gizagizai; sunansa Ubangiji ne, ku kuma yi farin ciki a gabansa. ");
INSERT INTO hausa_vpl VALUES ("PS68_5","020_68_5","PSA","68","5","5","Uba ga marayu, mai kāre gwauraye, shi ne Allah a mazauninsa mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("PS68_6","020_68_6","PSA","68","6","6","Allah ya shirya masu kaɗaici a cikin iyalai, ya jagorance ’yan kurkuku da waƙoƙi; amma ’yan tawaye suna zama a ƙasa mai zafin rana. ");
INSERT INTO hausa_vpl VALUES ("PS68_7","020_68_7","PSA","68","7","7","Sa’ad da ka fito a gaban mutanenka, ya Allah, sa’ad da ka taka ta cikin ƙasar da take wofi, Sela ");
INSERT INTO hausa_vpl VALUES ("PS68_8","020_68_8","PSA","68","8","8","duniya ta girgiza, sammai suka zuba ruwan sama, a gaban Allah, wanda ya bayyana a Sinai, a gaban Allah, Allah na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS68_9","020_68_9","PSA","68","9","9","Ka ba da yayyafi a yalwace, ya Allah; ka rayar da gādonka da ya gāji. ");
INSERT INTO hausa_vpl VALUES ("PS68_10","020_68_10","PSA","68","10","10","Mutanenka suka zauna a cikinsa, kuma daga yalwarka, ya Allah, ka tanada wa matalauta. ");
INSERT INTO hausa_vpl VALUES ("PS68_11","020_68_11","PSA","68","11","11","Ubangiji ya yi umarni, mutane masu yawa ne suka yi shelarsa, ");
INSERT INTO hausa_vpl VALUES ("PS68_12","020_68_12","PSA","68","12","12","“Sarakuna da mayaƙa suka gudu a gaggauce; cikin sansani mutane sun raba ganima. ");
INSERT INTO hausa_vpl VALUES ("PS68_13","020_68_13","PSA","68","13","13","Har yayinda kuke barci a cikin garken tumaki, an dalaye fikafikan kurciya da azurfa, fikafikanta da zinariya mai ƙyalli.” ");
INSERT INTO hausa_vpl VALUES ("PS68_14","020_68_14","PSA","68","14","14","Sa’ad da Maɗaukaki ya watsar da sarakuna a cikin ƙasa, sai ya zama kamar ƙanƙara ta sauka a kan Zalmon. ");
INSERT INTO hausa_vpl VALUES ("PS68_15","020_68_15","PSA","68","15","15","Duwatsun Bashan, duwatsu masu alfarma ne; duwatsun Bashan masu wuyar hawa ne. ");
INSERT INTO hausa_vpl VALUES ("PS68_16","020_68_16","PSA","68","16","16","Don me kuke duba da kishi, ya duwatsu masu wuyan hawa, a kan dutsen da Allah ya zaɓa yă yi mulki, inda Ubangiji kansa zai zauna har abada? ");
INSERT INTO hausa_vpl VALUES ("PS68_17","020_68_17","PSA","68","17","17","Karusan Allah ninkin dubbai goma ne da kuma dubu dubbai; Ubangiji ya zo daga Sinai ya shiga cikin haikalinsa. ");
INSERT INTO hausa_vpl VALUES ("PS68_18","020_68_18","PSA","68","18","18","Sa’ad da ka hau bisa, ka bi da kamammu cikin tawagarka; ka karɓi kyautai daga mutane, har ma daga ’yan tawaye, don kai, ya Ubangiji Allah, za ka zauna a can. ");
INSERT INTO hausa_vpl VALUES ("PS68_19","020_68_19","PSA","68","19","19","Yabo ya tabbata ga Ubangiji, ga Allah Mai Cetonmu, wanda kullum yake ɗaukan nauyinmu. Sela ");
INSERT INTO hausa_vpl VALUES ("PS68_20","020_68_20","PSA","68","20","20","Allahnmu shi ne Allah wanda yake ceto; daga Ubangiji Mai Iko Duka kuɓuta yake zuwa daga mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PS68_21","020_68_21","PSA","68","21","21","Tabbatacce Allah zai murƙushe kawunan abokan gābansa, rawanin gashi na waɗanda suke ci gaba cikin zunubansa. ");
INSERT INTO hausa_vpl VALUES ("PS68_22","020_68_22","PSA","68","22","22","Ubangiji ya ce, “Zan kawo su daga Bashan; zan kawo su daga zurfafan teku, ");
INSERT INTO hausa_vpl VALUES ("PS68_23","020_68_23","PSA","68","23","23","don ku wanke ƙafafunku a cikin jinin maƙiyanku, yayinda harsunan karnukanku su sami rabonsu.” ");
INSERT INTO hausa_vpl VALUES ("PS68_24","020_68_24","PSA","68","24","24","Jerin gwanonka ya zo a bayyane, ya Allah, jerin gwanon Allahna da Sarkina zuwa cikin wuri mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("PS68_25","020_68_25","PSA","68","25","25","A gaba akwai mawaƙa, a bayansu akwai makaɗa; tare da su akwai ’yan mata suna bugan ganguna. ");
INSERT INTO hausa_vpl VALUES ("PS68_26","020_68_26","PSA","68","26","26","Ku yabi Allah cikin taro mai girma; yabi Ubangiji cikin taron Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS68_27","020_68_27","PSA","68","27","27","Ga ƙaramar kabilar Benyamin, suna jagorance su, ga babbar ƙungiya shugabannin Yahuda, ga kuma shugabannin Zebulun da na Naftali. ");
INSERT INTO hausa_vpl VALUES ("PS68_28","020_68_28","PSA","68","28","28","Ka bayyana ikonka, ya Allah; ka nuna ƙarfinka, ya Allah, kamar yadda ka yi a dā. ");
INSERT INTO hausa_vpl VALUES ("PS68_29","020_68_29","PSA","68","29","29","Saboda haikalinka a Urushalima sarakuna za su kawo maka kyautai. ");
INSERT INTO hausa_vpl VALUES ("PS68_30","020_68_30","PSA","68","30","30","Ka tsawata wa naman jejin nan a cikin kyauro, garken bijimai a cikin ’yan maruƙan al’ummai. Ka ƙasƙantar, bari yă kawo sandunan azurfa. Ka watsar da al’ummai waɗanda suke jin daɗin yaƙi. ");
INSERT INTO hausa_vpl VALUES ("PS68_31","020_68_31","PSA","68","31","31","Jakadu za su zo daga Masar; Kush za tă miƙa kanta ga Allah. ");
INSERT INTO hausa_vpl VALUES ("PS68_32","020_68_32","PSA","68","32","32","Ku rera wa Allah, ya masarautan duniya, ku rera yabo ga Ubangiji, Sela ");
INSERT INTO hausa_vpl VALUES ("PS68_33","020_68_33","PSA","68","33","33","gare shi wanda yake hawan daɗaɗɗen sararin sama, wanda yake tsawa da babbar murya. ");
INSERT INTO hausa_vpl VALUES ("PS68_34","020_68_34","PSA","68","34","34","Ku yi shelar ikon Allah, wanda ɗaukakarsa take a bisa Isra’ila, wanda ikonsa yake a cikin sarari. ");
INSERT INTO hausa_vpl VALUES ("PS68_35","020_68_35","PSA","68","35","35","Kai mai banmamaki ne, ya Allah, cikin wurinka mai tsarki; Allah na Isra’ila yakan ba da iko da kuma ƙarfi ga mutanensa. Yabo ya tabbata ga Allah! ");
INSERT INTO hausa_vpl VALUES ("PS69_1","020_69_1","PSA","69","1","1","Don mai bi da kaɗe-kaɗe. Da muryar “Lilin.” Ta Dawuda. Ka cece ni, ya Allah, gama ruwa ya kai wuyata ");
INSERT INTO hausa_vpl VALUES ("PS69_2","020_69_2","PSA","69","2","2","Na nutse cikin laka mai zurfi, inda babu wurin tsayawa. Na shiga cikin ruwaye masu zurfi; rigyawa ya sha kaina. ");
INSERT INTO hausa_vpl VALUES ("PS69_3","020_69_3","PSA","69","3","3","Na gaji da kira ina neman taimako; maƙogwarona ya bushe idanuna sun dushe, suna neman Allahna. ");
INSERT INTO hausa_vpl VALUES ("PS69_4","020_69_4","PSA","69","4","4","Waɗanda suke ƙina ba dalili sun fi gashin kaina yawa; da yawa ne abokan gābana babu dalili, su da suke nema su hallaka ni. An tilasta mini in mayar da abin da ban sata ba. ");
INSERT INTO hausa_vpl VALUES ("PS69_5","020_69_5","PSA","69","5","5","Ka san wautata, ya Allah; laifina ba a ɓoye yake daga gare ka ba. ");
INSERT INTO hausa_vpl VALUES ("PS69_6","020_69_6","PSA","69","6","6","Bari waɗanda suke sa zuciya gare ka kada su sha kunya saboda ni, Ya Ubangiji, Ubangiji Maɗaukaki; bari waɗanda suke neman ka kada su sha kunya saboda ni, Ya Allah na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS69_7","020_69_7","PSA","69","7","7","Gama na jimre da ba’a saboda kai, kunya kuma ta rufe fuskata. ");
INSERT INTO hausa_vpl VALUES ("PS69_8","020_69_8","PSA","69","8","8","Ni baƙo ne a cikin ’yan’uwana, bare kuma ga ’ya’yan mahaifiyata maza; ");
INSERT INTO hausa_vpl VALUES ("PS69_9","020_69_9","PSA","69","9","9","gama himma da nake yi wa gidanka yana ƙunata, kuma zagi na masu zaginka yana fāɗuwa a kaina. ");
INSERT INTO hausa_vpl VALUES ("PS69_10","020_69_10","PSA","69","10","10","Sa’ad da na yi kuka na kuma yi azumi dole in jimre da ba’a; ");
INSERT INTO hausa_vpl VALUES ("PS69_11","020_69_11","PSA","69","11","11","sa’ad da na sanya rigunan makoki, mutane suna maishe ni abin dariya. ");
INSERT INTO hausa_vpl VALUES ("PS69_12","020_69_12","PSA","69","12","12","Masu zama a ƙofa suna mini ba’a, na zama waƙa a bakin bugaggu da giya. ");
INSERT INTO hausa_vpl VALUES ("PS69_13","020_69_13","PSA","69","13","13","Amma na yi addu’a gare ka, ya Ubangiji, a lokacin da ka ga dama; a cikin ƙaunarka mai girma, ya Allah, ka amsa mini da tabbacin ceto. ");
INSERT INTO hausa_vpl VALUES ("PS69_14","020_69_14","PSA","69","14","14","Ka fid da ni daga laka, kada ka bari in nutse; ka cece ni daga waɗanda suke ƙina, daga rurin ruwaye. ");
INSERT INTO hausa_vpl VALUES ("PS69_15","020_69_15","PSA","69","15","15","Kada ka bar rigyawa yă sha kaina ko zurfafa su haɗiye ni ko rami yă rufe bakinsa a kaina. ");
INSERT INTO hausa_vpl VALUES ("PS69_16","020_69_16","PSA","69","16","16","Ka amsa mini, ya Ubangiji cikin alherin ƙaunarka; cikin jinƙanka mai girma ka juyo gare ni. ");
INSERT INTO hausa_vpl VALUES ("PS69_17","020_69_17","PSA","69","17","17","Kada ka ɓoye fuskarka daga bawanka; ka amsa mini da sauri, gama ina cikin wahala. ");
INSERT INTO hausa_vpl VALUES ("PS69_18","020_69_18","PSA","69","18","18","Ka zo kusa ka kuɓutar da ni; ka fanshe ni saboda maƙiyana. ");
INSERT INTO hausa_vpl VALUES ("PS69_19","020_69_19","PSA","69","19","19","Ka san yadda ake mini ba’a, ake kunyatar da ni da kuma yadda nake shan kunya; dukan abokan gābana suna a gabanka. ");
INSERT INTO hausa_vpl VALUES ("PS69_20","020_69_20","PSA","69","20","20","Ba’a ta sa zuciyata ta karai ta bar ni ba mataimaki; Na nemi a ji tausayina, amma ban sami ko ɗaya ba, na nemi masu ta’aziyya, amma ban sami ko ɗaya ba. ");
INSERT INTO hausa_vpl VALUES ("PS69_21","020_69_21","PSA","69","21","21","Sun sa abin ɗaci cikin abincina suka kuma ba ni ruwan inabi mai tsami sa’ad da nake jin ƙishi. ");
INSERT INTO hausa_vpl VALUES ("PS69_22","020_69_22","PSA","69","22","22","Bari teburin da aka shirya a gabansu yă zama musu tarko; bari yă zama sakamakon laifi da kuma tarko. ");
INSERT INTO hausa_vpl VALUES ("PS69_23","020_69_23","PSA","69","23","23","Bari idanunsu yă dushe don kada su gani, bayansu kuma yă tanƙware har abada. ");
INSERT INTO hausa_vpl VALUES ("PS69_24","020_69_24","PSA","69","24","24","Ka kwarara fushinka a kansu; bari fushinka mai zafi yă ci musu. ");
INSERT INTO hausa_vpl VALUES ("PS69_25","020_69_25","PSA","69","25","25","Bari wurinsu yă zama kufai; kada ka bar wani yă zauna a tentunansu. ");
INSERT INTO hausa_vpl VALUES ("PS69_26","020_69_26","PSA","69","26","26","Gama sun tsananta wa waɗanda ka hukunta suna kuma taɗin wahalar waɗanda ka ji musu rauni. ");
INSERT INTO hausa_vpl VALUES ("PS69_27","020_69_27","PSA","69","27","27","Ka neme su da laifi a kan laifi; kada ka bar su su sami rabo a cikin cetonka. ");
INSERT INTO hausa_vpl VALUES ("PS69_28","020_69_28","PSA","69","28","28","Bari a shafe su sarai daga littafin rai kada a kuma lissafta su tare da adalai. ");
INSERT INTO hausa_vpl VALUES ("PS69_29","020_69_29","PSA","69","29","29","Ina cikin zafi da kuma azaba; bari cetonka, ya Allah, yă tsare ni. ");
INSERT INTO hausa_vpl VALUES ("PS69_30","020_69_30","PSA","69","30","30","Zan yabe sunan Allah cikin waƙa in kuma ɗaukaka shi tare wurin yin godiya. ");
INSERT INTO hausa_vpl VALUES ("PS69_31","020_69_31","PSA","69","31","31","Wannan zai gamshi Ubangiji fiye da saniya, fiye da bijimi da ƙahoninsa da kuma kofatansa. ");
INSERT INTO hausa_vpl VALUES ("PS69_32","020_69_32","PSA","69","32","32","Matalauta za su gani su kuma yi murna, ku da kuke neman Allah, bari zukatanku su rayu! ");
INSERT INTO hausa_vpl VALUES ("PS69_33","020_69_33","PSA","69","33","33","Ubangiji yakan ji masu bukata ba ya kuwa ƙyale kamammun mutanensa. ");
INSERT INTO hausa_vpl VALUES ("PS69_34","020_69_34","PSA","69","34","34","Bari sama da ƙasa su yabe shi, tekuna da dukan abin da yake motsi a cikinsu, ");
INSERT INTO hausa_vpl VALUES ("PS69_35","020_69_35","PSA","69","35","35","gama Allah zai cece Sihiyona yă sāke gina biranen Yahuda. Sa’an nan mutane za su zauna a can su mallake ta, ");
INSERT INTO hausa_vpl VALUES ("PS69_36","020_69_36","PSA","69","36","36","’ya’yan bayinsa za su gāje ta, waɗanda kuma suna ƙaunar sunansa za su zauna a can. ");
INSERT INTO hausa_vpl VALUES ("PS70_1","020_70_1","PSA","70","1","1","Don mai bi da kaɗe-kaɗe. Ta Dawuda. Roƙo. Ka hanzarta, ya Allah, ka cece ni; Ya Ubangiji, zo da sauri ka taimake ni. ");
INSERT INTO hausa_vpl VALUES ("PS70_2","020_70_2","PSA","70","2","2","Bari masu neman raina su sha kunya su kuma rikice; bari dukan masu sha’awar gani lalacewata su juye baya da kunya. ");
INSERT INTO hausa_vpl VALUES ("PS70_3","020_70_3","PSA","70","3","3","Bari masu ce mini, “Allah yă ƙara!” Su juye baya saboda kunyansu. ");
INSERT INTO hausa_vpl VALUES ("PS70_4","020_70_4","PSA","70","4","4","Amma bari dukan masu nemanka su yi farin ciki su kuma yi murna a cikinka; bari waɗanda suke ƙaunar cetonka kullum su ce, “Bari Allah yă sami ɗaukaka!” ");
INSERT INTO hausa_vpl VALUES ("PS70_5","020_70_5","PSA","70","5","5","Duk da haka ni matalauci ne da kuma mai bukata; ka zo da sauri gare ni, ya Allah. Kai ne mai taimakona da mai cetona; Ya Ubangiji, kada ka yi jinkiri. ");
INSERT INTO hausa_vpl VALUES ("PS71_1","020_71_1","PSA","71","1","1","A gare ka, ya Ubangiji, na nemi mafaka; kada ka taɓa sa in sha kunya. ");
INSERT INTO hausa_vpl VALUES ("PS71_2","020_71_2","PSA","71","2","2","Ka kuɓutar da ni ka cece ni cikin adalcinka; ka juya kunnenka gare ni ka kuma cece ni. ");
INSERT INTO hausa_vpl VALUES ("PS71_3","020_71_3","PSA","71","3","3","Ka zama dutsena da kagarata, inda kullum zan je. Ka ba da umarni a cece ni, gama kai ne dutsen ɓuyana da katangata. ");
INSERT INTO hausa_vpl VALUES ("PS71_4","020_71_4","PSA","71","4","4","Ka cece ni, ya Allahna, daga hannun mugaye, da kuma daga ikon mugaye da masu mugunta. ");
INSERT INTO hausa_vpl VALUES ("PS71_5","020_71_5","PSA","71","5","5","Gama kai ne abin sa zuciyata, ya Ubangiji Mai Iko Duka, ƙarfin zuciyata tun ina yaro. ");
INSERT INTO hausa_vpl VALUES ("PS71_6","020_71_6","PSA","71","6","6","Daga haihuwa na dogara gare ka; kai ka kawo ni daga cikin mahaifiyata. Kullayaumi zan yabe ka. ");
INSERT INTO hausa_vpl VALUES ("PS71_7","020_71_7","PSA","71","7","7","Na zama kamar abin sa zuciya ga yawanci, amma kai ne katangata mai ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("PS71_8","020_71_8","PSA","71","8","8","Bakina ya cika da yabonka, ina furta darajarka dukan yini. ");
INSERT INTO hausa_vpl VALUES ("PS71_9","020_71_9","PSA","71","9","9","Kada ka yar da ni sa’ad da na tsufa; kada ka yashe ni sa’ad da ƙarfina ya ƙare. ");
INSERT INTO hausa_vpl VALUES ("PS71_10","020_71_10","PSA","71","10","10","Gama abokan gābana suna magana a kaina; waɗanda suke jira su kashe ni suna haɗa baki tare. ");
INSERT INTO hausa_vpl VALUES ("PS71_11","020_71_11","PSA","71","11","11","Suna cewa, “Allah ya yashe shi; mu fafare shi mu kama shi, gama ba wanda zai kuɓutar da shi.” ");
INSERT INTO hausa_vpl VALUES ("PS71_12","020_71_12","PSA","71","12","12","Kada ka yi nisa da ni, ya Allah; zo da sauri, ya Allahna, ka taimake ni. ");
INSERT INTO hausa_vpl VALUES ("PS71_13","020_71_13","PSA","71","13","13","Bari masu zagina su hallaka da kunya; bari waɗanda suke so su cutar da ni su sha ba’a da kuma kunya. ");
INSERT INTO hausa_vpl VALUES ("PS71_14","020_71_14","PSA","71","14","14","Amma game da ni, kullayaumi zan kasance da sa zuciya; zan yabe ka sau da sau. ");
INSERT INTO hausa_vpl VALUES ("PS71_15","020_71_15","PSA","71","15","15","Bakina zai ba da labarin adalcinka, zai yi maganar cetonka dukan yini, ko da yake ban san yawansa ba. ");
INSERT INTO hausa_vpl VALUES ("PS71_16","020_71_16","PSA","71","16","16","Zan zo in furta in kuma yi shelar ayyukanka masu girma, ya Ubangiji Mai Iko Duka; zan yi shelar adalcinka, naka kaɗai. ");
INSERT INTO hausa_vpl VALUES ("PS71_17","020_71_17","PSA","71","17","17","Tun ina yaro, ya Allah, ka koya mini har wa yau ina furta ayyukanka masu banmamaki. ");
INSERT INTO hausa_vpl VALUES ("PS71_18","020_71_18","PSA","71","18","18","Ko sa’ad da na tsufa da furfura, kada ka yashe ni, ya Allah, sai na furta ikonka ga tsara mai zuwa, ƙarfinka ga dukan waɗanda suke zuwa. ");
INSERT INTO hausa_vpl VALUES ("PS71_19","020_71_19","PSA","71","19","19","Adalcinka ya kai sararin sama, ya Allah, kai da ka yi manyan abubuwa. Wane ne kamar ka, ya Allah? ");
INSERT INTO hausa_vpl VALUES ("PS71_20","020_71_20","PSA","71","20","20","Ko da yake ka sa na ga wahaloli, masu yawa da kuma masu ɗaci, za ka sāke mayar mini da rai; daga zurfafan duniya za ka sāke tā da ni. ");
INSERT INTO hausa_vpl VALUES ("PS71_21","020_71_21","PSA","71","21","21","Za ka ƙara girmana ka sāke ta’azantar da ni. ");
INSERT INTO hausa_vpl VALUES ("PS71_22","020_71_22","PSA","71","22","22","Zan yabe ka da garaya saboda amincinka, ya Allah; zan rera yabo gare ka da molo, Ya Mai Tsarki na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS71_23","020_71_23","PSA","71","23","23","Leɓunana za su yi sowa don farin ciki sa’ad da na rera yabo gare ka, ni, wanda ka fansa. ");
INSERT INTO hausa_vpl VALUES ("PS71_24","020_71_24","PSA","71","24","24","Harshena zai ba da labarin ayyukanka masu adalci dukan yini, gama waɗanda suka so su cutar da ni sun sha kunya suka kuma rikice. ");
INSERT INTO hausa_vpl VALUES ("PS72_1","020_72_1","PSA","72","1","1","Ta Solomon. Ka tanada sarki da shari’arka ta gaskiya, ya Allah, ɗan sarki da adalcinka. ");
INSERT INTO hausa_vpl VALUES ("PS72_2","020_72_2","PSA","72","2","2","Zai shari’anta mutanenka da adalci, marasa ƙarfinka da shari’ar gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PS72_3","020_72_3","PSA","72","3","3","Duwatsu za su kawo wadata ga mutane, tuddai kuma su ba da amfani na adalci. ");
INSERT INTO hausa_vpl VALUES ("PS72_4","020_72_4","PSA","72","4","4","Zai kāre marasa ƙarfi a cikin mutane yă kuma cece ’ya’yan masu bukata; zai murƙushe masu danniya. ");
INSERT INTO hausa_vpl VALUES ("PS72_5","020_72_5","PSA","72","5","5","Zai jimre muddin rana tana nan, muddin akwai wata, har dukan zamanai. ");
INSERT INTO hausa_vpl VALUES ("PS72_6","020_72_6","PSA","72","6","6","Zai zama kamar ruwan sama mai fāɗuwa a filin ciyayin da aka yanka, kamar yayyafi mai ba wa duniya ruwa. ");
INSERT INTO hausa_vpl VALUES ("PS72_7","020_72_7","PSA","72","7","7","A kwanakinsa adalai za su haɓaka wadata za tă yalwata har sai babu sauran wata. ");
INSERT INTO hausa_vpl VALUES ("PS72_8","020_72_8","PSA","72","8","8","Zai yi mulki daga teku zuwa teku kuma daga Kogi zuwa iyakar duniya. ");
INSERT INTO hausa_vpl VALUES ("PS72_9","020_72_9","PSA","72","9","9","Kabilun hamada za su rusuna a gabansa abokan gābansa kuwa za su lashe ƙura. ");
INSERT INTO hausa_vpl VALUES ("PS72_10","020_72_10","PSA","72","10","10","Sarakunan Tarshish da na bakin kogi masu nisa za su ba da gandu gare shi; sarakunan Sheba da Seba za su ba shi kyautai. ");
INSERT INTO hausa_vpl VALUES ("PS72_11","020_72_11","PSA","72","11","11","Dukan sarakuna za su rusuna masa kuma dukan al’ummai za su bauta masa. ");
INSERT INTO hausa_vpl VALUES ("PS72_12","020_72_12","PSA","72","12","12","Gama zai ceci masu bukatan da suka yi kuka, marasa ƙarfin da ba su da mai taimako. ");
INSERT INTO hausa_vpl VALUES ("PS72_13","020_72_13","PSA","72","13","13","Zai ji tausayin gajiyayyu da masu bukata yă ceci masu bukata daga mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PS72_14","020_72_14","PSA","72","14","14","Zai kuɓutar da su daga danniya da rikici, gama jininsu yake a gabansa. ");
INSERT INTO hausa_vpl VALUES ("PS72_15","020_72_15","PSA","72","15","15","Bari yă yi doguwar rayuwa! Bari a ba shi zinariya daga Sheba. Bari mutane su riƙa yin addu’a dominsa su kuma albarkace shi dukan yini. ");
INSERT INTO hausa_vpl VALUES ("PS72_16","020_72_16","PSA","72","16","16","Bari hatsi yă yalwata a duk fāɗin ƙasar; bari yă cika bisan tuddai. Bari ’ya’yan itatuwansa su haɓaka kamar Lebanon; bari yă bazu kamar ciyayi a gona. ");
INSERT INTO hausa_vpl VALUES ("PS72_17","020_72_17","PSA","72","17","17","Bari sunansa yă dawwama har abada; bari yă ci gaba muddin rana tana nan. Dukan al’ummai za su sami albarka ta wurinsa, za su kuma ce da shi mai albarka. ");
INSERT INTO hausa_vpl VALUES ("PS72_18","020_72_18","PSA","72","18","18","Yabo ya tabbata ga Ubangiji Allah, Allah na Isra’ila, wanda shi kaɗai ya aikata abubuwa masu banmamaki. ");
INSERT INTO hausa_vpl VALUES ("PS72_19","020_72_19","PSA","72","19","19","Yabo ya tabbata ga sunansa mai ɗaukaka har abada; bari dukan duniya ta cika da ɗaukakarsa. ");
INSERT INTO hausa_vpl VALUES ("PS72_20","020_72_20","PSA","72","20","20","Wannan ya kammala addu’o’in Dawuda ɗan Yesse. ");
INSERT INTO hausa_vpl VALUES ("PS73_1","020_73_1","PSA","73","1","1","Zabura ta Asaf. Tabbatacce Allah mai alheri ne ga Isra’ila, ga waɗanda suke masu tsabta a zuciya. ");
INSERT INTO hausa_vpl VALUES ("PS73_2","020_73_2","PSA","73","2","2","Amma game da ni, ƙafafuna suna gab da yin santsi; tafin ƙafana ya yi kusan zamewa. ");
INSERT INTO hausa_vpl VALUES ("PS73_3","020_73_3","PSA","73","3","3","Gama na yi kishin masu girman kai sa’ad da na ga cin gaban da masu mugunta suke yi. ");
INSERT INTO hausa_vpl VALUES ("PS73_4","020_73_4","PSA","73","4","4","Ba sa yin wata fama; jikunansu lafiya suke da kuma ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("PS73_5","020_73_5","PSA","73","5","5","Ba sa shan wata wahalar da sauran mutane ke sha; ba su da damuwa irin na ’yan adam. ");
INSERT INTO hausa_vpl VALUES ("PS73_6","020_73_6","PSA","73","6","6","Saboda girman kai ya zama musu abin wuya; tā da hankali ya zama musu riga. ");
INSERT INTO hausa_vpl VALUES ("PS73_7","020_73_7","PSA","73","7","7","Daga mugayen zukatansu laifi kan fito mugaye ƙulle-ƙullen da suke cikin zukatansu ba su da iyaka. ");
INSERT INTO hausa_vpl VALUES ("PS73_8","020_73_8","PSA","73","8","8","Suna ba’a, suna faɗin mugayen abubuwa; cikin girman kan suna barazana yin danniya. ");
INSERT INTO hausa_vpl VALUES ("PS73_9","020_73_9","PSA","73","9","9","Bakunansu na cewa sama na su ne, kuma harsunansu sun mallaki duniya. ");
INSERT INTO hausa_vpl VALUES ("PS73_10","020_73_10","PSA","73","10","10","Saboda haka mutanensu sun juya gare su suna kuma shan ruwa a yalwace. ");
INSERT INTO hausa_vpl VALUES ("PS73_11","020_73_11","PSA","73","11","11","Suna cewa, “Yaya Allah zai sani? Mafi Ɗaukaka yana da sani ne?” ");
INSERT INTO hausa_vpl VALUES ("PS73_12","020_73_12","PSA","73","12","12","Ga yadda mugaye suke, kullum ba su da damuwa, arzikinsu yana ta ƙaruwa. ");
INSERT INTO hausa_vpl VALUES ("PS73_13","020_73_13","PSA","73","13","13","Tabbatacce a banza na bar zuciyata da tsabta; a banza na wanke hannuwa don nuna rashin laifi. ");
INSERT INTO hausa_vpl VALUES ("PS73_14","020_73_14","PSA","73","14","14","Dukan yini na sha annoba; an hukunta ni kowace safiya. ");
INSERT INTO hausa_vpl VALUES ("PS73_15","020_73_15","PSA","73","15","15","Da na ce, “Zan faɗa haka,” da na bashe ’ya’yanka. ");
INSERT INTO hausa_vpl VALUES ("PS73_16","020_73_16","PSA","73","16","16","Sa’ad da na yi ƙoƙari in gane wannan, sai ya zama danniya a gare ni ");
INSERT INTO hausa_vpl VALUES ("PS73_17","020_73_17","PSA","73","17","17","sai da na shiga wuri mai tsarki na Allah; sa’an nan na gane abin da ƙarshensu zai zama. ");
INSERT INTO hausa_vpl VALUES ("PS73_18","020_73_18","PSA","73","18","18","Tabbatacce ka sa su a ƙasa mai santsi; ka jefar da su ga hallaka. ");
INSERT INTO hausa_vpl VALUES ("PS73_19","020_73_19","PSA","73","19","19","Duba yadda suka hallaka farat ɗaya, razana ta share su gaba ɗaya! ");
INSERT INTO hausa_vpl VALUES ("PS73_20","020_73_20","PSA","73","20","20","Kamar yadda mafarki yake sa’ad da mutum ya farka, haka yake sa’ad da ka farka, ya Ubangiji, za ka rena su kamar almarai. ");
INSERT INTO hausa_vpl VALUES ("PS73_21","020_73_21","PSA","73","21","21","Sa’ad da zuciyata ta ɓaci hankalina kuma ya tashi, ");
INSERT INTO hausa_vpl VALUES ("PS73_22","020_73_22","PSA","73","22","22","na zama marar azanci da jahili; na zama kamar dabba a gabanka. ");
INSERT INTO hausa_vpl VALUES ("PS73_23","020_73_23","PSA","73","23","23","Duk da haka kullum ina tare da kai; ka riƙe ni a hannun damana. ");
INSERT INTO hausa_vpl VALUES ("PS73_24","020_73_24","PSA","73","24","24","Ka bishe ni da shawararka, bayan haka kuma za ka kai ni cikin ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("PS73_25","020_73_25","PSA","73","25","25","Wa nake da shi a sama in ba kai ba? Ba na kuma sha’awar kome a duniya in ban da kai. ");
INSERT INTO hausa_vpl VALUES ("PS73_26","020_73_26","PSA","73","26","26","Jikina da zuciyata za su iya raunana, amma Allah ne ƙarfin zuciyata da kuma rabona har abada. ");
INSERT INTO hausa_vpl VALUES ("PS73_27","020_73_27","PSA","73","27","27","Waɗanda suke nesa da kai za su hallaka; kakan hallaka dukan waɗanda suke maka rashin aminci. ");
INSERT INTO hausa_vpl VALUES ("PS73_28","020_73_28","PSA","73","28","28","Amma game da ni, yana da kyau in kasance kusa da Allah. Na mai da Ubangiji Mai Iko Duka mafakata; zan yi shelar dukan ayyukanka. ");
INSERT INTO hausa_vpl VALUES ("PS74_1","020_74_1","PSA","74","1","1","Maskil na Asaf. Me ya sa ka ƙi mu har abada, ya Allah? Me ya sa fushinka yake a kan tumakin kiwonka? ");
INSERT INTO hausa_vpl VALUES ("PS74_2","020_74_2","PSA","74","2","2","Ka tuna da mutanen da ka saya tun da daɗewa, kabilar gādonka, wadda ka fansa, Dutsen Sihiyona, inda ka zauna. ");
INSERT INTO hausa_vpl VALUES ("PS74_3","020_74_3","PSA","74","3","3","Ka juye sawunka wajen waɗannan madawwamin kufai, dukan wannan hallakar da abokin gāba ya yi wa wuri mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("PS74_4","020_74_4","PSA","74","4","4","Maƙiyanka sun yi ruri a inda ka sadu da mu; suka kakkafa tutotinsu a matsayin alamu. ");
INSERT INTO hausa_vpl VALUES ("PS74_5","020_74_5","PSA","74","5","5","Sun yi kamar mutane masu wāshin gatura don yanka itatuwa a kurmi. ");
INSERT INTO hausa_vpl VALUES ("PS74_6","020_74_6","PSA","74","6","6","Sun ragargaje dukan sassaƙar katako da gatura da kuma gudumarsu. ");
INSERT INTO hausa_vpl VALUES ("PS74_7","020_74_7","PSA","74","7","7","Suka ƙone wurinka mai tsarki ƙurmus; suka ƙazantar da mazaunin Sunanka. ");
INSERT INTO hausa_vpl VALUES ("PS74_8","020_74_8","PSA","74","8","8","Suna cewa a zukatansu, “Za mu murƙushe su sarai!” Suka ƙone ko’ina aka yi wa Allah sujada a ƙasar. ");
INSERT INTO hausa_vpl VALUES ("PS74_9","020_74_9","PSA","74","9","9","Ba a ba mu wata alama mai banmamaki ba; ba sauran annabawan da suka ragu, kuma babu waninmu da ya sani har yaushe wannan zai ci gaba. ");
INSERT INTO hausa_vpl VALUES ("PS74_10","020_74_10","PSA","74","10","10","Har yaushe abokan gāba za su yi mana ba’a, ya Allah? Maƙiya za su ci gaba da ɓata sunanka har abada ne? ");
INSERT INTO hausa_vpl VALUES ("PS74_11","020_74_11","PSA","74","11","11","Me ya sa ka janye hannunka, hannunka na dama? Ka fid da shi daga rigarka ka hallaka su! ");
INSERT INTO hausa_vpl VALUES ("PS74_12","020_74_12","PSA","74","12","12","Amma kai, ya Allah, kai ne sarki tun da daɗewa; ka kawo ceto a kan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS74_13","020_74_13","PSA","74","13","13","Kai ne ka raba teku ta wurin ikonka; ka farfashe kawunan dodo a cikin ruwaye. ");
INSERT INTO hausa_vpl VALUES ("PS74_14","020_74_14","PSA","74","14","14","Kai ne ka murƙushe kawunan dodon ruwa ka kuma ba da shi yă zama abinci ga halittun hamada. ");
INSERT INTO hausa_vpl VALUES ("PS74_15","020_74_15","PSA","74","15","15","Kai ne ka bubbuɗe maɓulɓulai da rafuffuka; ka busar da koguna masu ruwa. ");
INSERT INTO hausa_vpl VALUES ("PS74_16","020_74_16","PSA","74","16","16","Yini naka ne, dare kuma naka ne; ka kafa rana da wata. ");
INSERT INTO hausa_vpl VALUES ("PS74_17","020_74_17","PSA","74","17","17","Kai ne ka kafa dukan iyakokin duniya; ka yi rani da damina. ");
INSERT INTO hausa_vpl VALUES ("PS74_18","020_74_18","PSA","74","18","18","Ka tuna da yadda abokin gāba ya yi maka ba’a, ya Ubangiji, yadda wawaye suka ɓata sunanka. ");
INSERT INTO hausa_vpl VALUES ("PS74_19","020_74_19","PSA","74","19","19","Kada ka ba da ran kurciyarka ga namun jeji; kada ka manta har abada da rayukan mutanenka masu shan azaba. ");
INSERT INTO hausa_vpl VALUES ("PS74_20","020_74_20","PSA","74","20","20","Ka kula da alkawarinka, domin akwai tashin hankali a kowane lungu mai duhu na ƙasar. ");
INSERT INTO hausa_vpl VALUES ("PS74_21","020_74_21","PSA","74","21","21","Kada ka bar waɗanda ake danniya su sha kunya; bari matalauta da mabukata su yabe sunanka. ");
INSERT INTO hausa_vpl VALUES ("PS74_22","020_74_22","PSA","74","22","22","Ka tashi, ya Allah, ka kāre muradinka; ka tuna yadda wawaye suka yi maka ba’a dukan yini. ");
INSERT INTO hausa_vpl VALUES ("PS74_23","020_74_23","PSA","74","23","23","Kada ka ƙyale surutan ban haushi na maƙiyanka, ihun abokan gābanka, waɗanda suke ci gaba da yi. ");
INSERT INTO hausa_vpl VALUES ("PS75_1","020_75_1","PSA","75","1","1","Don mai bi da kaɗe-kaɗe. Mai muryar “Kada A Hallaka.” Zabura ta Asaf. Waƙa ce. Muna maka godiya, ya Allah, muna maka godiya, gama Sunanka yana kusa; mutane na faɗin ayyukanka masu banmamaki. ");
INSERT INTO hausa_vpl VALUES ("PS75_2","020_75_2","PSA","75","2","2","Ka ce, “Na zaɓi ƙayyadadden lokaci; ni ne wanda yake shari’ar gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PS75_3","020_75_3","PSA","75","3","3","Sa’ad da duniya da dukan mutanenta suka girgiza, ni ne wanda na riƙe ginshiƙan daram. Sela ");
INSERT INTO hausa_vpl VALUES ("PS75_4","020_75_4","PSA","75","4","4","Ga masu girman kai na ce, ‘Kada ku ƙara taƙama,’ ga mugaye kuma, ‘Kada ku ɗaga ƙahoninku. ");
INSERT INTO hausa_vpl VALUES ("PS75_5","020_75_5","PSA","75","5","5","Kada ku ɗaga ƙahoninku gāba da sama; kada ku yi magana da miƙaƙƙen wuya.’ ” ");
INSERT INTO hausa_vpl VALUES ("PS75_6","020_75_6","PSA","75","6","6","Ba wani daga gabas ko yamma ko hamada da zai ɗaukaka mutum. ");
INSERT INTO hausa_vpl VALUES ("PS75_7","020_75_7","PSA","75","7","7","Amma Allah ne mai yin shari’a, yakan saukar da wannan, yă kuma tayar da wani. ");
INSERT INTO hausa_vpl VALUES ("PS75_8","020_75_8","PSA","75","8","8","A hannun Ubangiji akwai kwaf cike da ruwan inabi mai kumfa gauraye da kayan yaji; yakan zuba shi, dukan mugayen duniya kuwa su sha shi tas. ");
INSERT INTO hausa_vpl VALUES ("PS75_9","020_75_9","PSA","75","9","9","Game da ni dai, zan furta wannan har abada; zan rera yabo ga Allah na Yaƙub, ");
INSERT INTO hausa_vpl VALUES ("PS75_10","020_75_10","PSA","75","10","10","wanda ya ce, “Zan yanke ƙahonin dukan mugaye, amma za a ɗaga ƙahonin adalai sama.” ");
INSERT INTO hausa_vpl VALUES ("PS76_1","020_76_1","PSA","76","1","1","Don mai bi da kaɗe-kaɗe. Tare da kayan kiɗi masu tsirkiya. Zabura ta Asaf. Waƙa ce. A cikin Yahuda an san Allah; sunansa da girma yake a cikin Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS76_2","020_76_2","PSA","76","2","2","Tentinsa yana a Salem mazauninsa yana a Sihiyona. ");
INSERT INTO hausa_vpl VALUES ("PS76_3","020_76_3","PSA","76","3","3","A can ya kakkarya kibiyoyin wuta, garkuwoyi da takuban, makaman yaƙi. Sela ");
INSERT INTO hausa_vpl VALUES ("PS76_4","020_76_4","PSA","76","4","4","Darajarka tana da haske, fiye da darajar tuddai waɗanda suke cike da namun jeji masu yawa. ");
INSERT INTO hausa_vpl VALUES ("PS76_5","020_76_5","PSA","76","5","5","Jarumawa sun zube kamar ganima sun yi barcinsu na ƙarshe; ba ko jarumi guda da zai iya ɗaga hannuwansa. ");
INSERT INTO hausa_vpl VALUES ("PS76_6","020_76_6","PSA","76","6","6","A tsawatawarka, ya Allah na Yaƙub, doki da keken yaƙi suka kwanta ba motsi. ");
INSERT INTO hausa_vpl VALUES ("PS76_7","020_76_7","PSA","76","7","7","Kai kaɗai ne za a ji tsoro. Wane ne zai iya tsayawa sa’ad da ka yi fushi? ");
INSERT INTO hausa_vpl VALUES ("PS76_8","020_76_8","PSA","76","8","8","Daga sama ka yi shelar hukunci, ƙasa kuwa ta ji tsoro ta kuwa yi tsit, ");
INSERT INTO hausa_vpl VALUES ("PS76_9","020_76_9","PSA","76","9","9","sa’ad da kai, ya Allah, ka tashi don ka yi shari’a, don ka cece dukan masu shan wahala a ƙasar. Sela ");
INSERT INTO hausa_vpl VALUES ("PS76_10","020_76_10","PSA","76","10","10","Tabbatacce fushinka a kan mutane kan jawo maka yabo, waɗanda suka tsira daga fushinka za su zama kamar rawaninka. ");
INSERT INTO hausa_vpl VALUES ("PS76_11","020_76_11","PSA","76","11","11","Ku yi alkawari wa Ubangiji Allahnku ku kuma cika su; bari dukan ƙasashen maƙwabta su kawo kyautai ga Wannan da za a ji tsoro. ");
INSERT INTO hausa_vpl VALUES ("PS76_12","020_76_12","PSA","76","12","12","Ya kakkarya ƙarfin masu mulki; sarakunan duniya suna tsoronsa. ");
INSERT INTO hausa_vpl VALUES ("PS77_1","020_77_1","PSA","77","1","1","Don mai bi da kaɗe-kaɗe. Don Yedutun. Na Asaf. Zabura ce. Na yi kuka ga Allah don taimako; na yi kuka ga Allah don yă ji ni. ");
INSERT INTO hausa_vpl VALUES ("PS77_2","020_77_2","PSA","77","2","2","Sa’ad da nake cikin damuwa, na nemi Ubangiji; da dare na miƙa hannuwa ba gajiya raina kuma ya ƙi yă ta’azantu. ");
INSERT INTO hausa_vpl VALUES ("PS77_3","020_77_3","PSA","77","3","3","Na tuna da kai, ya Allah, na kuma yi nishi; na yi nishi, ƙarfina kuwa duk ya raunana. Sela ");
INSERT INTO hausa_vpl VALUES ("PS77_4","020_77_4","PSA","77","4","4","ka hana idanuna rufewa; na damu ƙwarai har ba na iya magana. ");
INSERT INTO hausa_vpl VALUES ("PS77_5","020_77_5","PSA","77","5","5","Na yi tunani kwanakin da suka wuce, shekarun da suka wuce da daɗewa; ");
INSERT INTO hausa_vpl VALUES ("PS77_6","020_77_6","PSA","77","6","6","na tuna da waƙoƙina da dare. Zuciyata ta yi nishi, ƙarfina kuwa ya nemi yă sani. ");
INSERT INTO hausa_vpl VALUES ("PS77_7","020_77_7","PSA","77","7","7","“Ubangiji zai ƙi ne har abada? Ba zai taɓa nuna alherinsa kuma ba? ");
INSERT INTO hausa_vpl VALUES ("PS77_8","020_77_8","PSA","77","8","8","Ƙaunarsa marar ƙarewa ta ɓace ke nan har abada? Alkawarinsa ya kāsa ke nan a dukan lokaci? ");
INSERT INTO hausa_vpl VALUES ("PS77_9","020_77_9","PSA","77","9","9","Allah ya manta yă yi jinƙai? Cikin fushinsa ya janye tausayinsa ne?” Sela ");
INSERT INTO hausa_vpl VALUES ("PS77_10","020_77_10","PSA","77","10","10","Sai na yi tunani, “Zan yi roƙo saboda wannan, shekarun da Mafi Ɗaukaka ya miƙa hannunsa na dama.” ");
INSERT INTO hausa_vpl VALUES ("PS77_11","020_77_11","PSA","77","11","11","Zan tuna da ayyukan Ubangiji; I, zan tuna mu’ujizanka na tun dā. ");
INSERT INTO hausa_vpl VALUES ("PS77_12","020_77_12","PSA","77","12","12","Zan yi tunani a kan dukan ayyukanka in lura da dukan manyan abubuwan da ka aikata. ");
INSERT INTO hausa_vpl VALUES ("PS77_13","020_77_13","PSA","77","13","13","Hanyoyinka, ya Allah, masu tsarki ne. Wanda allah ne yake da girma kamar Allahnmu? ");
INSERT INTO hausa_vpl VALUES ("PS77_14","020_77_14","PSA","77","14","14","Kai ne Allahn da yakan aikata mu’ujizai; ka nuna ikonka a cikin mutane. ");
INSERT INTO hausa_vpl VALUES ("PS77_15","020_77_15","PSA","77","15","15","Da hannunka mai ƙarfi ka fanshi mutanenka, zuriyar Yaƙub da Yusuf. Sela ");
INSERT INTO hausa_vpl VALUES ("PS77_16","020_77_16","PSA","77","16","16","Ruwaye sun gan ka, ya Allah, ruwaye sun gan ka suka firgita; zurfafan gaske sun girgiza. ");
INSERT INTO hausa_vpl VALUES ("PS77_17","020_77_17","PSA","77","17","17","Gizagizai sun sauko da ruwa, sararin sama suka buga tsawa; kibiyoyinka suka yi ta kai komo da walƙiya. ");
INSERT INTO hausa_vpl VALUES ("PS77_18","020_77_18","PSA","77","18","18","Aka ji tsawanka a cikin guguwa, walƙiyarka ta haskaka duniya; duniya ta yi rawar jiki ta girgiza. ");
INSERT INTO hausa_vpl VALUES ("PS77_19","020_77_19","PSA","77","19","19","Hanyarka ta bi ta cikin teku, hanyarka ta bi cikin manyan ruwaye, duk da haka ba a ga sawunka ba. ");
INSERT INTO hausa_vpl VALUES ("PS77_20","020_77_20","PSA","77","20","20","Ka bi da mutanenka kamar garke ta hannun Musa da Haruna. ");
INSERT INTO hausa_vpl VALUES ("PS78_1","020_78_1","PSA","78","1","1","Maskil na Asaf. Ya mutanena, ku ji koyarwata; ku saurari kalmomin bakina. ");
INSERT INTO hausa_vpl VALUES ("PS78_2","020_78_2","PSA","78","2","2","Zan buɗe bakina da misalai, zan faɗi ɓoyayyun abubuwa, abubuwan dā, ");
INSERT INTO hausa_vpl VALUES ("PS78_3","020_78_3","PSA","78","3","3","abin da muka ji muka kuma sani, abubuwan da kakanninmu suka faɗa mana. ");
INSERT INTO hausa_vpl VALUES ("PS78_4","020_78_4","PSA","78","4","4","Ba za mu ɓoye su wa ’ya’yanmu ba; za mu faɗa wa tsara mai zuwa ayyukan da suka zama yabo na Ubangiji, ikonsa, da abubuwan banmamakin da ya aikata. ");
INSERT INTO hausa_vpl VALUES ("PS78_5","020_78_5","PSA","78","5","5","Ya kafa ƙa’idodi wa Yaƙub ya kuma kafa doka a cikin Isra’ila, wadda ya umarce kakanni-kakanninmu su koya wa ’ya’yansu, ");
INSERT INTO hausa_vpl VALUES ("PS78_6","020_78_6","PSA","78","6","6","don tsara na biye su san su, har da ’ya’yan da ba a riga an haifa ba, su kuma su faɗa wa ’ya’yansu. ");
INSERT INTO hausa_vpl VALUES ("PS78_7","020_78_7","PSA","78","7","7","Ta haka za su dogara ga Allah ba kuwa za su manta da ayyukansa ba amma za su kiyaye umarnansa. ");
INSERT INTO hausa_vpl VALUES ("PS78_8","020_78_8","PSA","78","8","8","Ba za su zama kamar kakanni kakanninsu ba, masu taurinkai da kuma tsara masu tayarwa, waɗanda zukatansu ba su yi biyayya ga Allah ba, waɗanda zukatansu ba su yi aminci ga Allah ba. ");
INSERT INTO hausa_vpl VALUES ("PS78_9","020_78_9","PSA","78","9","9","Mutanen Efraim, ko da yake suna da bakkuna, suka juya da baya a ranar yaƙi; ");
INSERT INTO hausa_vpl VALUES ("PS78_10","020_78_10","PSA","78","10","10","ba su kiyaye alkawarin Allah ba suka kuma ƙi su yi rayuwa ta wurin dokarsa. ");
INSERT INTO hausa_vpl VALUES ("PS78_11","020_78_11","PSA","78","11","11","Suka manta da abin da ya aikata, abubuwan banmamakin da ya nuna musu. ");
INSERT INTO hausa_vpl VALUES ("PS78_12","020_78_12","PSA","78","12","12","Ya yi mu’ujizai a idanun kakanninsu a ƙasar Masar, a yankin Zowan. ");
INSERT INTO hausa_vpl VALUES ("PS78_13","020_78_13","PSA","78","13","13","Ya raba teku ya kuma bi da su ciki; ya sa ruwa ya tsaya daram kamar bango. ");
INSERT INTO hausa_vpl VALUES ("PS78_14","020_78_14","PSA","78","14","14","Ya bishe su da girgije da rana da kuma haske daga wuta dukan dare. ");
INSERT INTO hausa_vpl VALUES ("PS78_15","020_78_15","PSA","78","15","15","Ya tsage duwatsu a cikin hamada ya kuma ba su ruwaye a yalwace kamar tekuna; ");
INSERT INTO hausa_vpl VALUES ("PS78_16","020_78_16","PSA","78","16","16","ya fid da rafuffuka daga dutsen da ya tsaga ya sa ruwa ya gudu kamar koguna. ");
INSERT INTO hausa_vpl VALUES ("PS78_17","020_78_17","PSA","78","17","17","Amma suka ci gaba da yin masa zunubi, suna tayarwa a cikin hamada a kan Mafi Ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("PS78_18","020_78_18","PSA","78","18","18","Da gangan suka gwada Allah ta wurin neman abincin da suke kwaɗayi. ");
INSERT INTO hausa_vpl VALUES ("PS78_19","020_78_19","PSA","78","19","19","Suka yi magana a kan Allah, suna cewa, “Allah zai iya shimfiɗa tebur a cikin hamada? ");
INSERT INTO hausa_vpl VALUES ("PS78_20","020_78_20","PSA","78","20","20","Sa’ad da ya bugi dutse, ruwa ya ɓulɓulo, rafuffuka suka yi gudu a yalwace. Amma zai iya ba mu abinci? Zai iya tanada wa mutanensa nama?” ");
INSERT INTO hausa_vpl VALUES ("PS78_21","020_78_21","PSA","78","21","21","Sa’ad da Ubangiji ya ji su, ya yi fushi ƙwarai; wutarsa ta ɓarke a kan Yaƙub, hasalarsa kuwa ta tashi a kan Isra’ila, ");
INSERT INTO hausa_vpl VALUES ("PS78_22","020_78_22","PSA","78","22","22","gama ba su gaskata ga Allah ba ko su dogara ga cetonsa. ");
INSERT INTO hausa_vpl VALUES ("PS78_23","020_78_23","PSA","78","23","23","Duk da haka ya ba da umarni ga sarari a bisa ya kuma buɗe ƙofofin sammai; ");
INSERT INTO hausa_vpl VALUES ("PS78_24","020_78_24","PSA","78","24","24","ya sauko da Manna wa mutanensa don su ci, ya ba su hatsin sama. ");
INSERT INTO hausa_vpl VALUES ("PS78_25","020_78_25","PSA","78","25","25","Mutane suka ci burodin mala’iku; ya aika musu dukan abincin da za su iya ci. ");
INSERT INTO hausa_vpl VALUES ("PS78_26","020_78_26","PSA","78","26","26","Ya saki iskar gabas daga sammai ya kuma saki iskar yamma ta wurin ikonsa. ");
INSERT INTO hausa_vpl VALUES ("PS78_27","020_78_27","PSA","78","27","27","Ya sauko da nama a kansu kamar ƙura, tsuntsaye masu firiya kamar yashi a bakin teku. ");
INSERT INTO hausa_vpl VALUES ("PS78_28","020_78_28","PSA","78","28","28","Ya sa suka sauka a cikin sansaninsu, ko’ina kewaye da tentunansu. ");
INSERT INTO hausa_vpl VALUES ("PS78_29","020_78_29","PSA","78","29","29","Suka ci har suka sami fiye da abin da ya ishe su, gama ya ba su abin da suka yi kwaɗayi. ");
INSERT INTO hausa_vpl VALUES ("PS78_30","020_78_30","PSA","78","30","30","Amma kafin su juyo daga abincin da suka yi kwaɗayi, kai tun ma yana a bakunansu, ");
INSERT INTO hausa_vpl VALUES ("PS78_31","020_78_31","PSA","78","31","31","fushin Allah ya ƙuna a kansu; ya karkashe waɗanda suka fi ƙiba a cikinsu, yana yankan matasan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS78_32","020_78_32","PSA","78","32","32","Duk da haka, suka ci gaba da yin zunubi; duk da abubuwan banmamakinsa, ba su gaskata ba. ");
INSERT INTO hausa_vpl VALUES ("PS78_33","020_78_33","PSA","78","33","33","Saboda haka ya sa kwanakinsu suka ƙare a banza shekarunsu kuma cikin masifa. ");
INSERT INTO hausa_vpl VALUES ("PS78_34","020_78_34","PSA","78","34","34","A duk sa’ad da Allah ya kashe su, sai su neme shi; sukan juyo a natse gare shi. ");
INSERT INTO hausa_vpl VALUES ("PS78_35","020_78_35","PSA","78","35","35","Sun tuna cewa Allah ne Dutsensu, cewa Allah Mafi Ɗaukaka ne Mai fansarsu. ");
INSERT INTO hausa_vpl VALUES ("PS78_36","020_78_36","PSA","78","36","36","Amma sai su yi ta yin masa zaƙin baki, suna masa ƙarya da harsunansu; ");
INSERT INTO hausa_vpl VALUES ("PS78_37","020_78_37","PSA","78","37","37","zukatansu ba sa biyayya gare shi, ba su da aminci ga alkawarinsa. ");
INSERT INTO hausa_vpl VALUES ("PS78_38","020_78_38","PSA","78","38","38","Duk da haka ya kasance mai jinƙai; ya gafarta laifofinsu bai kuwa hallaka su ba. Sau da sau ya janye fushinsa bai kuwa sa fushinsa yă ƙuna ba. ");
INSERT INTO hausa_vpl VALUES ("PS78_39","020_78_39","PSA","78","39","39","Ya tuna cewa su naman jiki ne kawai, iska mai wucewa da ba ta dawowa. ");
INSERT INTO hausa_vpl VALUES ("PS78_40","020_78_40","PSA","78","40","40","Sau da yawa sun tayar masa a cikin hamada suka kuma ɓata masa rai a jeji! ");
INSERT INTO hausa_vpl VALUES ("PS78_41","020_78_41","PSA","78","41","41","Sau da sau suka riƙa gwada Allah; suka tsokane Mai Tsarki na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS78_42","020_78_42","PSA","78","42","42","Ba su tuna da ikonsa, a ranar da ya fanshe su daga mai danniya, ");
INSERT INTO hausa_vpl VALUES ("PS78_43","020_78_43","PSA","78","43","43","ranar da ya nuna mu’ujizansa a Masar abubuwan banmamakinsa a yankin Zowan ba. ");
INSERT INTO hausa_vpl VALUES ("PS78_44","020_78_44","PSA","78","44","44","Ya mai da kogunansu suka zama jini; ba su iya sha daga rafuffuka ba. ");
INSERT INTO hausa_vpl VALUES ("PS78_45","020_78_45","PSA","78","45","45","Ya aika da tarin ƙudajen da suka cinye su, da kwaɗin da suka wahalshe su. ");
INSERT INTO hausa_vpl VALUES ("PS78_46","020_78_46","PSA","78","46","46","Ya ba da hatsinsu ga fāra, amfanin gonakinsu ga ɗango. ");
INSERT INTO hausa_vpl VALUES ("PS78_47","020_78_47","PSA","78","47","47","Ya lalace inabinsu da ƙanƙara itatuwan al’ul nasu kuma da jaura. ");
INSERT INTO hausa_vpl VALUES ("PS78_48","020_78_48","PSA","78","48","48","Ya miƙa shanunsu ga ƙanƙara, tumakinsu ga aradun tsawa. ");
INSERT INTO hausa_vpl VALUES ("PS78_49","020_78_49","PSA","78","49","49","Ya saki musu fushinsa mai zafi, hasalarsa, zafin rai da kuma ɓacin ransa, ƙungiyar mala’iku masu hallakarwa. ");
INSERT INTO hausa_vpl VALUES ("PS78_50","020_78_50","PSA","78","50","50","Ya shirya hanya wa fushinsa; bai tsare ransu daga mutuwa ba amma ya miƙa su ga annoba. ");
INSERT INTO hausa_vpl VALUES ("PS78_51","020_78_51","PSA","78","51","51","Ya bugi kowane ɗan fari na Masar, mafari ƙarfin mazantakansu a tentunan Ham. ");
INSERT INTO hausa_vpl VALUES ("PS78_52","020_78_52","PSA","78","52","52","Amma ya fitar da mutanensa kamar garke; ya bi da su kamar tumaki ta cikin hamada. ");
INSERT INTO hausa_vpl VALUES ("PS78_53","020_78_53","PSA","78","53","53","Ya bi da su lafiya ƙalau, don kada su ji tsoro; amma teku ya cinye abokan gābansu. ");
INSERT INTO hausa_vpl VALUES ("PS78_54","020_78_54","PSA","78","54","54","Ta haka ya kawo su iyakar ƙasa mai tsarki, zuwa ƙasar tudun da hannunsa na dama ya kame. ");
INSERT INTO hausa_vpl VALUES ("PS78_55","020_78_55","PSA","78","55","55","Ya kori al’ummai a gabansu ya rarraba ƙasashensu gare su a matsayin gādo; ya zaunar da kabilan Isra’ila a gidajensu. ");
INSERT INTO hausa_vpl VALUES ("PS78_56","020_78_56","PSA","78","56","56","Amma suka gwada Allah suka tayar wa Mafi Ɗaukaka; ba su kiyaye ƙa’idodinsa ba. ");
INSERT INTO hausa_vpl VALUES ("PS78_57","020_78_57","PSA","78","57","57","Kamar kakanninsu suka zama marasa biyayya da marasa aminci, marar tabbas kamar tanƙwararren baka. ");
INSERT INTO hausa_vpl VALUES ("PS78_58","020_78_58","PSA","78","58","58","Suka ba shi haushi da masujadansu na kan tudu; suka tayar da kishinsa da gumakansu. ");
INSERT INTO hausa_vpl VALUES ("PS78_59","020_78_59","PSA","78","59","59","Sa’ad da Allah ya ji su, ya yi fushi ƙwarai; ya ƙi Isra’ila gaba ɗaya. ");
INSERT INTO hausa_vpl VALUES ("PS78_60","020_78_60","PSA","78","60","60","Ya yashe tabanakul na Shilo, tentin da ya kafa a cikin mutane. ");
INSERT INTO hausa_vpl VALUES ("PS78_61","020_78_61","PSA","78","61","61","Ya aika da akwatin alkawarin ƙarfinsa zuwa bauta, darajarsa zuwa cikin hannuwan abokin gāba. ");
INSERT INTO hausa_vpl VALUES ("PS78_62","020_78_62","PSA","78","62","62","Ya ba da mutanensa ga takobi; ya yi fushi ƙwarai da gādonsa. ");
INSERT INTO hausa_vpl VALUES ("PS78_63","020_78_63","PSA","78","63","63","Wuta ta cinye matasansu maza, ’yan matansu kuma ba su da waƙoƙin aure; ");
INSERT INTO hausa_vpl VALUES ("PS78_64","020_78_64","PSA","78","64","64","aka karkashe firistocinsu, gwaurayensu kuwa ba su iya makoki ba. ");
INSERT INTO hausa_vpl VALUES ("PS78_65","020_78_65","PSA","78","65","65","Sa’an nan Ubangiji ya farka sai ka ce daga barcinsa, kamar yadda mutum kan farka daga buguwar ruwan inabi. ");
INSERT INTO hausa_vpl VALUES ("PS78_66","020_78_66","PSA","78","66","66","Ya kori abokan gābansa; ya sa suka sha madawwamiyar kunya. ");
INSERT INTO hausa_vpl VALUES ("PS78_67","020_78_67","PSA","78","67","67","Sa’an nan ya ƙi tentunan Yusuf, bai zaɓi kabilar Efraim ba; ");
INSERT INTO hausa_vpl VALUES ("PS78_68","020_78_68","PSA","78","68","68","amma ya zaɓi kabilar Yahuda, Dutsen Sihiyona, wanda ya ƙaunaci. ");
INSERT INTO hausa_vpl VALUES ("PS78_69","020_78_69","PSA","78","69","69","Ya gina wurinsa mai tsarki kamar bisa, kamar duniyar da ya kafa har abada. ");
INSERT INTO hausa_vpl VALUES ("PS78_70","020_78_70","PSA","78","70","70","Ya zaɓi Dawuda bawansa ya kuma ɗauke shi daga ɗakin tumaki; ");
INSERT INTO hausa_vpl VALUES ("PS78_71","020_78_71","PSA","78","71","71","daga kiwon tumaki ya kawo shi don yă kuma zama makiyayin mutanensa Yaƙub, na Isra’ila gādonsa. ");
INSERT INTO hausa_vpl VALUES ("PS78_72","020_78_72","PSA","78","72","72","Dawuda kuwa ya zama makiyayinsu da mutuncin zuciya; da hannuwa masu gwaninta ya bi da su. ");
INSERT INTO hausa_vpl VALUES ("PS79_1","020_79_1","PSA","79","1","1","Zabura ta Asaf. Ya Allah, al’ummai sun mamaye gādonka; sun ƙazantar da haikalinka mai tsarki, sun bar Urushalima kufai. ");
INSERT INTO hausa_vpl VALUES ("PS79_2","020_79_2","PSA","79","2","2","Sun ba da gawawwakin bayinka kamar abinci ga tsuntsayen sararin sama, nama jikin tsarkakanka ga namun jejin duniya. ");
INSERT INTO hausa_vpl VALUES ("PS79_3","020_79_3","PSA","79","3","3","Sun zubar da jini kamar ruwa ko’ina a Urushalima, kuma babu wani da zai binne matattu. ");
INSERT INTO hausa_vpl VALUES ("PS79_4","020_79_4","PSA","79","4","4","Mun zama abin reni ga maƙwabta, abin ba’a da reni ga waɗanda suke kewaye da mu. ");
INSERT INTO hausa_vpl VALUES ("PS79_5","020_79_5","PSA","79","5","5","Har yaushe, ya Ubangiji za ka yi ta fushi? Har abada ne? Har yaushe kishinka zai yi ta ƙuna kamar wuta? ");
INSERT INTO hausa_vpl VALUES ("PS79_6","020_79_6","PSA","79","6","6","Ka zuba fushinka a kan al’umman da ba su yarda da kai ba, a kan mulkokin da ba sa kira bisa sunanka; ");
INSERT INTO hausa_vpl VALUES ("PS79_7","020_79_7","PSA","79","7","7","gama sun cinye Yaƙub suka lalatar da ƙasar zamansa. ");
INSERT INTO hausa_vpl VALUES ("PS79_8","020_79_8","PSA","79","8","8","Kada ka riƙe zunubai kakanni a kanmu; bari jinƙanka yă zo da sauri yă sadu da mu, gama mun fid da zuciya sarai. ");
INSERT INTO hausa_vpl VALUES ("PS79_9","020_79_9","PSA","79","9","9","Ka taimake mu, ya Allah Mai Cetonmu, saboda ɗaukakar sunanka; ka cece mu ka kuma gafarta mana zunubanmu saboda sunanka. ");
INSERT INTO hausa_vpl VALUES ("PS79_10","020_79_10","PSA","79","10","10","Don me al’ummai za su ce, “Ina Allahnsu yake?” A idanunmu, ka sanar wa al’ummai cewa kana ɗaukan fansar jinin bayinka da aka zubar. ");
INSERT INTO hausa_vpl VALUES ("PS79_11","020_79_11","PSA","79","11","11","Bari nishe-nishen ’yan kurkuku su zo gabanka; ta wurin ƙarfin hannunka ka kiyaye waɗanda aka yanke wa hukuncin mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PS79_12","020_79_12","PSA","79","12","12","Ka sāka a cinyoyin maƙwabtanmu sau bakwai zage-zagen da suka yi ta yi maka, ya Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS79_13","020_79_13","PSA","79","13","13","Sa’an nan mu mutanenka, tumakin makiyayarka, za mu yabe ka har abada; daga tsara zuwa tsara za mu yi ta ba da labarin yabonka. ");
INSERT INTO hausa_vpl VALUES ("PS80_1","020_80_1","PSA","80","1","1","Don mai bi da kaɗe-kaɗe. Mai muryar “Lilin Alkawari.” Na Asaf. Zabura ce. Ka ji mu, ya Makiyayin Isra’ila, kai da ka bishe Yusuf kamar garke. Kai da kake zaune a kursiyi tsakanin kerubobi, ka haskaka ");
INSERT INTO hausa_vpl VALUES ("PS80_2","020_80_2","PSA","80","2","2","a gaban Efraim, Benyamin da Manasse. Ka tā da ƙarfinka; ka zo ka cece mu. ");
INSERT INTO hausa_vpl VALUES ("PS80_3","020_80_3","PSA","80","3","3","Ka mai da mu, ya Allah; ka sa fuskarka ta haskaka a kanmu, za mu kuwa cetu. ");
INSERT INTO hausa_vpl VALUES ("PS80_4","020_80_4","PSA","80","4","4","Ya Ubangiji Allah Maɗaukaki, har yaushe fushinka zai yi ta ƙuna a kan addu’o’in mutanenka? ");
INSERT INTO hausa_vpl VALUES ("PS80_5","020_80_5","PSA","80","5","5","Ka ciyar da su da burodin hawaye; ka sa suka sha hawaye ta cikakken kwaf. ");
INSERT INTO hausa_vpl VALUES ("PS80_6","020_80_6","PSA","80","6","6","Ka mai da mu abin faɗa ga maƙwabtanmu, kuma abokan gābanmu suna mana ba’a. ");
INSERT INTO hausa_vpl VALUES ("PS80_7","020_80_7","PSA","80","7","7","Ka mai da mu, ya Allah Maɗaukaki; ka sa fuskarka ta haskaka a kanmu za mu kuwa cetu. ");
INSERT INTO hausa_vpl VALUES ("PS80_8","020_80_8","PSA","80","8","8","Ka fitar da inabi daga Masar; ka kori al’ummai ka kuma dasa shi. ");
INSERT INTO hausa_vpl VALUES ("PS80_9","020_80_9","PSA","80","9","9","Ka gyara wuri saboda shi, ya kuwa yi saiwa ya cike ƙasa. ");
INSERT INTO hausa_vpl VALUES ("PS80_10","020_80_10","PSA","80","10","10","Aka rufe duwatsu da inuwarsa, manya-manyan itatuwan al’ul da rassansa. ");
INSERT INTO hausa_vpl VALUES ("PS80_11","020_80_11","PSA","80","11","11","Ya miƙe rassansa zuwa Teku tohonsa har zuwa Kogi. ");
INSERT INTO hausa_vpl VALUES ("PS80_12","020_80_12","PSA","80","12","12","Me ya sa ka rurrushe bangayensa don duk masu wucewa su tsinke ’ya’yan inabinsa? ");
INSERT INTO hausa_vpl VALUES ("PS80_13","020_80_13","PSA","80","13","13","Aladu daga kurmi suna ɓarnatar da shi halittun gonaki kuma suna cinsa. ");
INSERT INTO hausa_vpl VALUES ("PS80_14","020_80_14","PSA","80","14","14","Ka komo wurinmu, ya Allah Maɗaukaki! Ka duba daga sama ka gani! Ka lura da wannan inabi, ");
INSERT INTO hausa_vpl VALUES ("PS80_15","020_80_15","PSA","80","15","15","saiwar da hannun damarka ya dasa, ɗan da ka renar wa kanka. ");
INSERT INTO hausa_vpl VALUES ("PS80_16","020_80_16","PSA","80","16","16","An yanke inabinka, an ƙone shi da wuta; a tsawatawarka mutanenka sun hallaka. ");
INSERT INTO hausa_vpl VALUES ("PS80_17","020_80_17","PSA","80","17","17","Bari hannunka yă zauna a kan mutumin da yake hannun damarka, ɗan mutum da ka renar wa kanka. ");
INSERT INTO hausa_vpl VALUES ("PS80_18","020_80_18","PSA","80","18","18","Ta haka ba za mu juye mu bar ka ba; ka rayar da mu, za mu kuwa kira bisa sunanka. ");
INSERT INTO hausa_vpl VALUES ("PS80_19","020_80_19","PSA","80","19","19","Ka mai da mu, ya Ubangiji Allah Maɗaukaki; ka sa fuskarka ta haskaka a kanmu, za mu kuwa cetu. ");
INSERT INTO hausa_vpl VALUES ("PS81_1","020_81_1","PSA","81","1","1","Don mai bi da kaɗe-kaɗe. Bisa ga gittit. Ta Asaf. Ku rera don farin ciki ga Allah ƙarfinmu; ku yi sowa ga Allah na Yaƙub! ");
INSERT INTO hausa_vpl VALUES ("PS81_2","020_81_2","PSA","81","2","2","Ku fara kaɗe-kaɗe, ku buga ganga, ku kaɗa garaya da molo masu daɗi. ");
INSERT INTO hausa_vpl VALUES ("PS81_3","020_81_3","PSA","81","3","3","Ku busa ƙahon rago a Sabon Wata, da kuma sa’ad da wata ya kai tsakiya, a ranar Bikinmu; ");
INSERT INTO hausa_vpl VALUES ("PS81_4","020_81_4","PSA","81","4","4","wannan ƙa’ida ce domin Isra’ila, farilla ta Allah na Yaƙub. ");
INSERT INTO hausa_vpl VALUES ("PS81_5","020_81_5","PSA","81","5","5","Ya kafa shi a matsayin ƙa’ida domin Yusuf sa’ad da ya fito daga Masar. Muka ji yaren da ba mu fahimta ba. ");
INSERT INTO hausa_vpl VALUES ("PS81_6","020_81_6","PSA","81","6","6","Ya ce, “Na kau da nauyi daga kafaɗunku; an ’yantar da hannuwansu daga kwando. ");
INSERT INTO hausa_vpl VALUES ("PS81_7","020_81_7","PSA","81","7","7","Cikin damuwarku kun yi kira na kuwa kuɓutar da ku, na amsa muku daga girgijen tsawa; na gwada ku a ruwan Meriba. Sela ");
INSERT INTO hausa_vpl VALUES ("PS81_8","020_81_8","PSA","81","8","8","“Ku ji, ya mutanena, zan kuwa gargaɗe ku, in ba za ku saurare ni ba, ya Isra’ila! ");
INSERT INTO hausa_vpl VALUES ("PS81_9","020_81_9","PSA","81","9","9","Kada ku kasance da baƙon allah a cikinku; ba za ku rusuna ga baƙon allah ba. ");
INSERT INTO hausa_vpl VALUES ("PS81_10","020_81_10","PSA","81","10","10","Ni ne Ubangiji Allahnku wanda ya fitar da ku daga Masar. Ku buɗe bakinku zan kuwa cika shi. ");
INSERT INTO hausa_vpl VALUES ("PS81_11","020_81_11","PSA","81","11","11","“Amma mutanena ba su saurare ni ba; Isra’ila bai miƙa kansa gare ni ba. ");
INSERT INTO hausa_vpl VALUES ("PS81_12","020_81_12","PSA","81","12","12","Saboda haka na ba da su ga zukatansu da suka taurare don su bi dabararsu. ");
INSERT INTO hausa_vpl VALUES ("PS81_13","020_81_13","PSA","81","13","13","“A ce mutanena za su saurare ni, a ce Isra’ila zai bi hanyoyina, ");
INSERT INTO hausa_vpl VALUES ("PS81_14","020_81_14","PSA","81","14","14","da nan da nan sai in rinjayi abokan gābansu in kuma juye hannuna a kan maƙiyansu! ");
INSERT INTO hausa_vpl VALUES ("PS81_15","020_81_15","PSA","81","15","15","Waɗanda suke ƙin Ubangiji za su fāɗi a gabansa da rawar jiki, hukuncinsu kuma zai dawwama har abada. ");
INSERT INTO hausa_vpl VALUES ("PS81_16","020_81_16","PSA","81","16","16","Amma za a ciyar da ku da alkama mafi kyau; da zuma daga dutsen da zai ƙosar da ku.” ");
INSERT INTO hausa_vpl VALUES ("PS82_1","020_82_1","PSA","82","1","1","Zabura ta Asaf. Allah yana shugabanta cikin babban taro; yakan zartar da hukunci a cikin “alloli”. ");
INSERT INTO hausa_vpl VALUES ("PS82_2","020_82_2","PSA","82","2","2","“Har yaushe za ku kāre marasa adalci ku kuma goyi bayan mugaye? Sela ");
INSERT INTO hausa_vpl VALUES ("PS82_3","020_82_3","PSA","82","3","3","Ku tsare mutuncin marasa ƙarfi da marayu; ku kāre hakkin matalauta da waɗanda ake danniya. ");
INSERT INTO hausa_vpl VALUES ("PS82_4","020_82_4","PSA","82","4","4","Ku ceci marasa ƙarfi da masu bukata; ku kuɓutar da su daga hannun mugaye. ");
INSERT INTO hausa_vpl VALUES ("PS82_5","020_82_5","PSA","82","5","5","“Ba su san kome ba, ba su fahimci kome ba. Suna yawo cikin duhu; an girgiza dukan tussan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS82_6","020_82_6","PSA","82","6","6","“Na ce, ‘Ku “alloli” ne; dukanku ’ya’yan Mafi Ɗaukaka’ ne. ");
INSERT INTO hausa_vpl VALUES ("PS82_7","020_82_7","PSA","82","7","7","Amma za ku mutu kamar mutum kurum; za ku fāɗi kamar duk wani mai mulki.” ");
INSERT INTO hausa_vpl VALUES ("PS82_8","020_82_8","PSA","82","8","8","Ka tashi, ya Allah, ka shari’anta duniya, gama dukan al’ummai gādonka ne. ");
INSERT INTO hausa_vpl VALUES ("PS83_1","020_83_1","PSA","83","1","1","Waƙa ce. Zabura ta Asaf. Ya Allah, kada ka yi shiru; kada ka tsaya cik, ya Allah, kada ka daina motsi. ");
INSERT INTO hausa_vpl VALUES ("PS83_2","020_83_2","PSA","83","2","2","Dubi yadda abokan gābanka suke fariya, dubi yadda maƙiyanka suke ɗaga kansu. ");
INSERT INTO hausa_vpl VALUES ("PS83_3","020_83_3","PSA","83","3","3","Da wayo suna ƙulle-ƙulle a kan mutanenka; suna shirya maƙarƙashiya a kan waɗanda kake so. ");
INSERT INTO hausa_vpl VALUES ("PS83_4","020_83_4","PSA","83","4","4","Suna cewa, “Ku zo, bari mu hallaka su ɗungum a matsayin al’umma, don kada a ƙara tuna da sunan Isra’ila.” ");
INSERT INTO hausa_vpl VALUES ("PS83_5","020_83_5","PSA","83","5","5","Da zuciya ɗaya suka yi ƙulle-ƙulle tare; suka haɗa kai gāba da kai, ");
INSERT INTO hausa_vpl VALUES ("PS83_6","020_83_6","PSA","83","6","6","tentunan Edom da na mutanen Ishmayel, na Mowab da kuma na Hagirawa, ");
INSERT INTO hausa_vpl VALUES ("PS83_7","020_83_7","PSA","83","7","7","Gebal, Ammon da Amalek, Filistiya, tare da mutanen Taya. ");
INSERT INTO hausa_vpl VALUES ("PS83_8","020_83_8","PSA","83","8","8","Har Assuriya ma ta haɗa kai da su don ta ba da ƙarfi ga zuriyar Lot. Sela ");
INSERT INTO hausa_vpl VALUES ("PS83_9","020_83_9","PSA","83","9","9","Ka yi musu abin da ka yi wa Midiyan, yadda ka yi wa Sisera da Yabin a kogin Kishon, ");
INSERT INTO hausa_vpl VALUES ("PS83_10","020_83_10","PSA","83","10","10","waɗanda suka hallaka a En Dor suka zama kamar juji a ƙasa. ");
INSERT INTO hausa_vpl VALUES ("PS83_11","020_83_11","PSA","83","11","11","Ka mai da manyansu kamar Oreb da Zeyib, dukan sarakunansu kamar Zeba da Zalmunna, ");
INSERT INTO hausa_vpl VALUES ("PS83_12","020_83_12","PSA","83","12","12","waɗanda suka ce, “Bari mu mallaki wuraren kiwon Allah.” ");
INSERT INTO hausa_vpl VALUES ("PS83_13","020_83_13","PSA","83","13","13","Ka mai da su kamar ɗan tsiron da kan karye, iska ta yi ta turawa, ya Allahna, kamar yayin da iska take hurawa, ");
INSERT INTO hausa_vpl VALUES ("PS83_14","020_83_14","PSA","83","14","14","kamar yadda wuta ke cin kurmi ko harshen wutar da take ci a kan duwatsu, ");
INSERT INTO hausa_vpl VALUES ("PS83_15","020_83_15","PSA","83","15","15","haka za ka kore su da iska mai ƙarfi ka kuma firgita su da guguwarka. ");
INSERT INTO hausa_vpl VALUES ("PS83_16","020_83_16","PSA","83","16","16","Ka rushe fuskokinsu da kunya don mutane su nemi sunanka, ya Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS83_17","020_83_17","PSA","83","17","17","Bari su kasance cikin kunya da taƙaici; bari su hallaka cikin wulaƙanci. ");
INSERT INTO hausa_vpl VALUES ("PS83_18","020_83_18","PSA","83","18","18","Bari su san cewa kai, wanda sunansa ne Ubangiji, cewa kai kaɗai ne Mafi Ɗaukaka a bisa dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS84_1","020_84_1","PSA","84","1","1","Don mai bi da kaɗe-kaɗe. Bisa ga gittit. Na ’Ya’yan Kora maza. Zabura ce. Ina misalin kyan wurin zamanka, Ya Ubangiji Maɗaukaki! ");
INSERT INTO hausa_vpl VALUES ("PS84_2","020_84_2","PSA","84","2","2","Raina yana marmari, har yana suma, don filayen gidan Ubangiji; zuciyata da namana na tā da murya domin Allah mai rai. ");
INSERT INTO hausa_vpl VALUES ("PS84_3","020_84_3","PSA","84","3","3","Har tsada ma ta sami gida, tsatsewa kuma ta yi wa kanta sheƙa, inda za tă ƙyanƙyashe ’ya’yanta, wuri kusa da bagadenka, Ya Ubangiji Maɗaukaki, Sarkina da kuma Allahna. ");
INSERT INTO hausa_vpl VALUES ("PS84_4","020_84_4","PSA","84","4","4","Masu albarka ne waɗanda suke zama a gidanka; kullum suna ta yabonka. Sela ");
INSERT INTO hausa_vpl VALUES ("PS84_5","020_84_5","PSA","84","5","5","Masu albarka ne waɗanda ƙarfinsu yana daga gare ka, waɗanda suka kafa zukatansu a yin tafiya zuwa wuri mai tsarki ne. ");
INSERT INTO hausa_vpl VALUES ("PS84_6","020_84_6","PSA","84","6","6","Yayinda suke wuce ta Kwarin Baka, sukan mai da shi wurin maɓulɓulai; ruwan sama na farko kuma kan rufe shi da tafkuna. ");
INSERT INTO hausa_vpl VALUES ("PS84_7","020_84_7","PSA","84","7","7","Suna ta ƙara ƙarfi, har sai kowanne ya bayyana a gaban Allah a Sihiyona. ");
INSERT INTO hausa_vpl VALUES ("PS84_8","020_84_8","PSA","84","8","8","Ka ji addu’ata, ya Ubangiji Allah Maɗaukaki; ka saurare ni, ya Allah na Yaƙub. Sela ");
INSERT INTO hausa_vpl VALUES ("PS84_9","020_84_9","PSA","84","9","9","Ka dubi garkuwarmu, ya Allah; ka duba da alheri a kan shafaffenka. ");
INSERT INTO hausa_vpl VALUES ("PS84_10","020_84_10","PSA","84","10","10","Rana guda a filayen gidan sun fi dubu a wani wuri dabam; zan gwammaci in zama mai tsaron ƙofa a gidan Allahna da in zauna a tentunan mugaye. ");
INSERT INTO hausa_vpl VALUES ("PS84_11","020_84_11","PSA","84","11","11","Gama Ubangiji Allah rana ne da kuma garkuwa; Ubangiji yakan yi alheri da kuma daraja; ba ya hana kowane abu mai kyau wa waɗanda suke aikata abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("PS84_12","020_84_12","PSA","84","12","12","Ya Ubangiji Maɗaukaki, mai albarka ne mutumin da ya dogara gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS85_1","020_85_1","PSA","85","1","1","Don mai bi da kaɗe-kaɗe. Na ’ya’yan Kora maza. Zabura ce. Ka nuna wa ƙasarka alheri, ya Ubangiji; ka mai da nasarorin Yaƙub. ");
INSERT INTO hausa_vpl VALUES ("PS85_2","020_85_2","PSA","85","2","2","Ka gafarta laifin mutanenka ka kuma shafe dukan zunubansu. Sela ");
INSERT INTO hausa_vpl VALUES ("PS85_3","020_85_3","PSA","85","3","3","Ka kau da dukan fushinka ka kuma juye daga hasalar fushinka. ");
INSERT INTO hausa_vpl VALUES ("PS85_4","020_85_4","PSA","85","4","4","Ka sāke mai da mu, ya Allah Mai Cetonmu, ka kau da rashin jin daɗinka daga gare mu. ");
INSERT INTO hausa_vpl VALUES ("PS85_5","020_85_5","PSA","85","5","5","Za ka ci gaba da fushi da mu har abada ne? Za ka ja fushinka cikin dukan tsararraki? ");
INSERT INTO hausa_vpl VALUES ("PS85_6","020_85_6","PSA","85","6","6","Ba za ka sāke raya mu ba, don mutanenka su yi farin ciki a cikinka? ");
INSERT INTO hausa_vpl VALUES ("PS85_7","020_85_7","PSA","85","7","7","Ka nuna mana ƙaunarka marar ƙarewa, ya Ubangiji, ka kuma ba mu cetonka. ");
INSERT INTO hausa_vpl VALUES ("PS85_8","020_85_8","PSA","85","8","8","Zan saurari abin da Allah Ubangiji zai faɗa; ya yi alkawarin salama ga mutanensa, tsarkakansa, amma kada su koma ga wauta. ");
INSERT INTO hausa_vpl VALUES ("PS85_9","020_85_9","PSA","85","9","9","Tabbatacce cetonsa yana kusa da waɗanda suke tsoronsa, don ɗaukakarsa ta zauna a cikin ƙasarmu. ");
INSERT INTO hausa_vpl VALUES ("PS85_10","020_85_10","PSA","85","10","10","Ƙauna da aminci za su sadu; adalci da salama za su yi wa juna sumba. ");
INSERT INTO hausa_vpl VALUES ("PS85_11","020_85_11","PSA","85","11","11","Aminci zai ɓulɓulo daga ƙasa, adalci kuma yă duba daga sama. ");
INSERT INTO hausa_vpl VALUES ("PS85_12","020_85_12","PSA","85","12","12","Ubangiji tabbatacce zai bayar da abin da yake da kyau, ƙasarmu kuwa za tă ba da amfaninta. ");
INSERT INTO hausa_vpl VALUES ("PS85_13","020_85_13","PSA","85","13","13","Adalci na tafiya a gabansa yana shirya hanya domin ƙafafunsa. ");
INSERT INTO hausa_vpl VALUES ("PS86_1","020_86_1","PSA","86","1","1","Addu’ar Dawuda. Ka ji, ya Ubangiji, ka kuma amsa mini, gama ni matalauci ne mai bukata kuma. ");
INSERT INTO hausa_vpl VALUES ("PS86_2","020_86_2","PSA","86","2","2","Ka tsare raina, gama na ba da kaina gare ka. Kai ne Allahna; ka ceci bawanka wanda ya dogara gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS86_3","020_86_3","PSA","86","3","3","Ka yi mini jinƙai, ya Ubangiji, gama na yi kira gare ka dukan yini. ");
INSERT INTO hausa_vpl VALUES ("PS86_4","020_86_4","PSA","86","4","4","Ka ba bawanka farin ciki gama gare ka, ya Ubangiji, na miƙa raina. ");
INSERT INTO hausa_vpl VALUES ("PS86_5","020_86_5","PSA","86","5","5","Kai mai gafartawa da kuma mai alheri ne, ya Ubangiji, cike da ƙauna ga dukan waɗanda suke kira gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS86_6","020_86_6","PSA","86","6","6","Ka ji addu’ata, ya Ubangiji; ka saurari kukata na neman jinƙai. ");
INSERT INTO hausa_vpl VALUES ("PS86_7","020_86_7","PSA","86","7","7","A lokacin wahala zan yi kira gare ka, gama za ka amsa mini. ");
INSERT INTO hausa_vpl VALUES ("PS86_8","020_86_8","PSA","86","8","8","A cikin alloli babu kamar ka, ya Ubangiji; babu ayyukan da za a kwatanta da naka. ");
INSERT INTO hausa_vpl VALUES ("PS86_9","020_86_9","PSA","86","9","9","Dukan al’umman da ka yi za su zo su yi sujada a gabanka, ya Ubangiji; za su kawo ɗaukaka ga sunanka. ");
INSERT INTO hausa_vpl VALUES ("PS86_10","020_86_10","PSA","86","10","10","Gama kai mai girma ne kana kuma aikata ayyuka masu banmamaki; kai kaɗai ne Allah. ");
INSERT INTO hausa_vpl VALUES ("PS86_11","020_86_11","PSA","86","11","11","Ka koya mini hanyarka, ya Ubangiji, zan kuwa yi tafiya cikin gaskiyarka; ka ba ni zuciya wadda ba tă rabu ba, don in ji tsoron sunanka. ");
INSERT INTO hausa_vpl VALUES ("PS86_12","020_86_12","PSA","86","12","12","Zan yabe ka, ya Ubangiji Allahna, da dukan zuciyata; zan ɗaukaka sunanka har abada. ");
INSERT INTO hausa_vpl VALUES ("PS86_13","020_86_13","PSA","86","13","13","Gama ƙaunarka da girma take gare ni; kai ka cece ni daga zurfafa, daga mazaunin matattu. ");
INSERT INTO hausa_vpl VALUES ("PS86_14","020_86_14","PSA","86","14","14","Masu girman kai suna kai mini hari, ya Allah; ƙungiyar marasa imani suna neman raina, mutanen da ba su kula da kai ba. ");
INSERT INTO hausa_vpl VALUES ("PS86_15","020_86_15","PSA","86","15","15","Amma kai, ya Ubangiji, kai Allah mai tausayi ne da kuma mai alheri, mai jinkirin fushi, mai yawan ƙauna da aminci. ");
INSERT INTO hausa_vpl VALUES ("PS86_16","020_86_16","PSA","86","16","16","Ka juyo gare ni ka yi mini jinƙai; ka ba wa bawanka ƙarfi; ka ceci ni gama na bauta maka yadda mahaifiyata ta yi. ");
INSERT INTO hausa_vpl VALUES ("PS86_17","020_86_17","PSA","86","17","17","Ka ba ni alamar alherinka, don abokan gābana su gani su kuma sha kunya, gama kai, ya Ubangiji, ka taimake ni ka kuma ta’azantar da ni. ");
INSERT INTO hausa_vpl VALUES ("PS87_1","020_87_1","PSA","87","1","1","Na ’ya’yan Kora maza. Zabura ce. Waƙa ce. Ya kafa harsashinsa a kan dutse mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("PS87_2","020_87_2","PSA","87","2","2","Ubangiji yana ƙaunar ƙofofin Sihiyona fiye da dukan wuraren zaman Yaƙub. ");
INSERT INTO hausa_vpl VALUES ("PS87_3","020_87_3","PSA","87","3","3","Ana faɗin abubuwa masu ɗaukaka game da ke Ya birnin Allah, Sela ");
INSERT INTO hausa_vpl VALUES ("PS87_4","020_87_4","PSA","87","4","4","“Zan lissafta Rahab a cikin waɗanda suka san ni, Filistiya ita ma, da Taya, tare da Kush, zan kuma ce, ‘An haifi wannan a Sihiyona.’ ” ");
INSERT INTO hausa_vpl VALUES ("PS87_5","020_87_5","PSA","87","5","5","Tabbatacce, game da Sihiyona za a ce, “Wannan da wancan an haifa a cikinta, Mafi Ɗaukaka kansa zai kafa ta.” ");
INSERT INTO hausa_vpl VALUES ("PS87_6","020_87_6","PSA","87","6","6","Ubangiji zai rubuta a littafin sunayen mutanensa, “An haifi wannan a Sihiyona.” Sela ");
INSERT INTO hausa_vpl VALUES ("PS87_7","020_87_7","PSA","87","7","7","Yayinda suke kaɗe-kaɗe za su rera, “Dukan maɓulɓulaina suna cikinki.” ");
INSERT INTO hausa_vpl VALUES ("PS88_1","020_88_1","PSA","88","1","1","Waƙa ce, Zabura ta ’ya’yan Kora maza. Don mai bi da kaɗe-kaɗe. Bisa ga mahalat leyannotmaskil na Heman dangin Ezra. Ya Ubangiji, Allah wanda ya cece ni, dare da rana ina kuka a gabanka. ");
INSERT INTO hausa_vpl VALUES ("PS88_2","020_88_2","PSA","88","2","2","Bari addu’ata ta zo a gabanka; ka kasa kunne ga kukata. ");
INSERT INTO hausa_vpl VALUES ("PS88_3","020_88_3","PSA","88","3","3","Gama raina yana cike da wahala rayuwata tana gab da kabari. ");
INSERT INTO hausa_vpl VALUES ("PS88_4","020_88_4","PSA","88","4","4","An lissafta ni cikin waɗanda suka gangara zuwa cikin rami; ni kamar mutumin da ba shi da ƙarfi ne. ");
INSERT INTO hausa_vpl VALUES ("PS88_5","020_88_5","PSA","88","5","5","An ware ni tare da matattu, kamar waɗanda aka kashe da suke kwance a kabari, waɗanda ba ka ƙara tunawa, waɗanda aka yanke daga taimakonka. ");
INSERT INTO hausa_vpl VALUES ("PS88_6","020_88_6","PSA","88","6","6","Ka sa ni a ramin da yake can ƙasa cikin zurfafa mafi duhu. ");
INSERT INTO hausa_vpl VALUES ("PS88_7","020_88_7","PSA","88","7","7","Hasalarka tana da nauyi a kaina; ka turmushe ni da dukan raƙumanka. Sela ");
INSERT INTO hausa_vpl VALUES ("PS88_8","020_88_8","PSA","88","8","8","Ka ɗauke abokaina na kurkusa daga gare ni ka sa na zama abin ƙyama a gare su. An kange ni, ba yadda zan kuɓuta ");
INSERT INTO hausa_vpl VALUES ("PS88_9","020_88_9","PSA","88","9","9","idanuna ba sa gani sosai saboda baƙin ciki. Ina kira gare ka, ya Ubangiji, kowace rana; na tā da hannuwana zuwa gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS88_10","020_88_10","PSA","88","10","10","Kakan nuna wa matattu ayyukanka na banmamaki ne? Waɗanda suka mutu sukan tashi su yabe ka ne? Sela ");
INSERT INTO hausa_vpl VALUES ("PS88_11","020_88_11","PSA","88","11","11","Ana furta ƙaunar a cikin kabari ne, ana zancen amincinka a cikin Hallaka ne? ");
INSERT INTO hausa_vpl VALUES ("PS88_12","020_88_12","PSA","88","12","12","An san ayyukanka masu banmamaki a wurin duhu ne, ko ayyukan adalcinka a lahira? ");
INSERT INTO hausa_vpl VALUES ("PS88_13","020_88_13","PSA","88","13","13","Amma ina kuka gare ka neman taimako, ya Ubangiji; da safe addu’ata kan zo gabanka. ");
INSERT INTO hausa_vpl VALUES ("PS88_14","020_88_14","PSA","88","14","14","Don me, ya Ubangiji, ka ƙi ni ka kuma ɓoye fuskarka daga gare ni? ");
INSERT INTO hausa_vpl VALUES ("PS88_15","020_88_15","PSA","88","15","15","Tun ina ƙarami na sha wahala na kuma yi kusa in mutu; na sha wahalar razanarka kuma na kuma fid da zuciya. ");
INSERT INTO hausa_vpl VALUES ("PS88_16","020_88_16","PSA","88","16","16","Hasalarka ta sha kaina; razanarka ta hallaka ni. ");
INSERT INTO hausa_vpl VALUES ("PS88_17","020_88_17","PSA","88","17","17","Dukan yini sun kewaye ni kamar rigyawa; sun mamaye ni ɗungum. ");
INSERT INTO hausa_vpl VALUES ("PS88_18","020_88_18","PSA","88","18","18","Ka ɗauke abokaina da ƙaunatattuna daga gare ni; duhu ne abokina na kurkusa. ");
INSERT INTO hausa_vpl VALUES ("PS89_1","020_89_1","PSA","89","1","1","Maskil na Etan dangin Ezra. Zan rera game da ƙauna mai girma ta Ubangiji har abada; da bakina zan sanar da amincinka a dukan zamanai. ");
INSERT INTO hausa_vpl VALUES ("PS89_2","020_89_2","PSA","89","2","2","Zan furta cewa ƙaunarka tana nan daram har abada, cewa ka kafa amincinka a sama kanta. ");
INSERT INTO hausa_vpl VALUES ("PS89_3","020_89_3","PSA","89","3","3","Ka ce, “Na yi alkawari da zaɓaɓɓena, na rantse wa Dawuda bawana, ");
INSERT INTO hausa_vpl VALUES ("PS89_4","020_89_4","PSA","89","4","4","cewa ‘Zan kafa zuriyarka har abada in kuma sa kursiyinka yă tsaya daram dukan zamanai.’ ” Sela ");
INSERT INTO hausa_vpl VALUES ("PS89_5","020_89_5","PSA","89","5","5","Sammai na yabon abubuwan banmamakinka, ya Ubangiji, amincinka shi ma, a cikin taron tsarkakanka. ");
INSERT INTO hausa_vpl VALUES ("PS89_6","020_89_6","PSA","89","6","6","Gama wane ne a sarari za a iya kwatanta da Ubangiji? Wane ne yake kamar Ubangiji a cikin talikan samaniya? ");
INSERT INTO hausa_vpl VALUES ("PS89_7","020_89_7","PSA","89","7","7","Cikin taron tsarkaka Allah ne aka fi tsoro; shi ne mafi bantsoro fiye da dukan waɗanda suka kewaye shi. ");
INSERT INTO hausa_vpl VALUES ("PS89_8","020_89_8","PSA","89","8","8","Ya Ubangiji Allah Maɗaukaki, wane ne kamar ka? Kai mai iko ne, ya Ubangiji, kuma amincinka ya kewaye ka. ");
INSERT INTO hausa_vpl VALUES ("PS89_9","020_89_9","PSA","89","9","9","Kana mulkin teku mai tumbatsa; sa’ad da raƙuma sun tashi, kakan kwantar da su. ");
INSERT INTO hausa_vpl VALUES ("PS89_10","020_89_10","PSA","89","10","10","Ka ragargaza Rahab kamar waɗanda aka kashe; da hannunka mai ƙarfi ka watsar da abokan gābanka. ");
INSERT INTO hausa_vpl VALUES ("PS89_11","020_89_11","PSA","89","11","11","Sammai naka ne, haka kuma duniya; ka kafa duniya da dukan abin da yake cikinta. ");
INSERT INTO hausa_vpl VALUES ("PS89_12","020_89_12","PSA","89","12","12","Ka halicce arewa da kudu; Tabor da Hermon suna rera don farin ciki ga sunanka. ");
INSERT INTO hausa_vpl VALUES ("PS89_13","020_89_13","PSA","89","13","13","Hannunka mai iko ne; hannunka yana da ƙarfi, hannunka na dama ya sami ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("PS89_14","020_89_14","PSA","89","14","14","Adalci da gaskiya su ne tushen kursiyinka; ƙauna da aminci suna tafiya a gabanka. ");
INSERT INTO hausa_vpl VALUES ("PS89_15","020_89_15","PSA","89","15","15","Masu albarka ne waɗanda suka koyi yin maka kirari waɗanda suke tafiya cikin hasken da yake gabanka, Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS89_16","020_89_16","PSA","89","16","16","Suna farin ciki a cikin sunanka dukan yini; suna samun ɗaukaka cikin adalcinka. ");
INSERT INTO hausa_vpl VALUES ("PS89_17","020_89_17","PSA","89","17","17","Gama kai ne ɗaukakarsu da ƙarfinsu, kuma ta wurin alherinka ka ɗaukaka ƙahonka. ");
INSERT INTO hausa_vpl VALUES ("PS89_18","020_89_18","PSA","89","18","18","Tabbatacce, garkuwarmu ta Ubangiji ce, ta sarkinmu ce, da kuma ta Mai Tsarki na Isra’ila ce. ");
INSERT INTO hausa_vpl VALUES ("PS89_19","020_89_19","PSA","89","19","19","Ka taɓa yin magana cikin wahayi, ga mutanenka masu aminci ka ce, “Na ba wa jarumi ƙarfi; na ɗaukaka saurayi daga cikin mutane. ");
INSERT INTO hausa_vpl VALUES ("PS89_20","020_89_20","PSA","89","20","20","Na sami Dawuda bawana; da mai na mai tsarki na shafe shi. ");
INSERT INTO hausa_vpl VALUES ("PS89_21","020_89_21","PSA","89","21","21","Hannuna zai kasance tare da shi; tabbatacce hannuna zai ƙarfafa shi. ");
INSERT INTO hausa_vpl VALUES ("PS89_22","020_89_22","PSA","89","22","22","Babu abokin gāban da zai sa yă biya haraji; babu mugun mutumin da zai danne shi. ");
INSERT INTO hausa_vpl VALUES ("PS89_23","020_89_23","PSA","89","23","23","Zan murƙushe maƙiyansa a gabansa in kashe dukan abokan gābansa. ");
INSERT INTO hausa_vpl VALUES ("PS89_24","020_89_24","PSA","89","24","24","Amintacciya ƙaunata za tă kasance tare da shi, kuma ta wurin sunana za a ɗaukaka ƙahonsa. ");
INSERT INTO hausa_vpl VALUES ("PS89_25","020_89_25","PSA","89","25","25","Zan sa hannunsa a bisa teku, hannunsa na dama a bisa koguna. ");
INSERT INTO hausa_vpl VALUES ("PS89_26","020_89_26","PSA","89","26","26","Zai yi kira gare ni yă ce, ‘Kai ne Mahaifina, Allahna, Dutse mai cetona.’ ");
INSERT INTO hausa_vpl VALUES ("PS89_27","020_89_27","PSA","89","27","27","Zan kuma naɗa shi ɗan farina, mafi ɗaukaka cikin sarakunan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS89_28","020_89_28","PSA","89","28","28","Zan ci gaba da ƙaunarsa har abada, alkawarina da shi ba zai taɓa fasa ba. ");
INSERT INTO hausa_vpl VALUES ("PS89_29","020_89_29","PSA","89","29","29","Zan kafa zuriyarsa har abada, kursiyinsa muddin sammai suna nan. ");
INSERT INTO hausa_vpl VALUES ("PS89_30","020_89_30","PSA","89","30","30","“In ’ya’yansa maza suka yashe dokata ba su kuwa bi ƙa’idodina ba, ");
INSERT INTO hausa_vpl VALUES ("PS89_31","020_89_31","PSA","89","31","31","in suka take ƙa’idodina suka kuma kāsa kiyaye umarnaina, ");
INSERT INTO hausa_vpl VALUES ("PS89_32","020_89_32","PSA","89","32","32","zan hukunta zunubinsu da sanda, laifinsu da bulala; ");
INSERT INTO hausa_vpl VALUES ("PS89_33","020_89_33","PSA","89","33","33","amma ba zan ɗauke ƙaunata daga gare shi ba, ba kuwa zan taɓa rasa cika amincina ba. ");
INSERT INTO hausa_vpl VALUES ("PS89_34","020_89_34","PSA","89","34","34","Ba zan take alkawarina ba ko in canja abin da leɓunana suka ambata. ");
INSERT INTO hausa_vpl VALUES ("PS89_35","020_89_35","PSA","89","35","35","Sau ɗaya ba ƙari, na rantse da tsarkina, ba kuwa zan yi ƙarya wa Dawuda ba, ");
INSERT INTO hausa_vpl VALUES ("PS89_36","020_89_36","PSA","89","36","36","cewa zuriyarsa za tă ci gaba har abada kuma kursiyinsa zai dawwama a gabana kamar rana; ");
INSERT INTO hausa_vpl VALUES ("PS89_37","020_89_37","PSA","89","37","37","zai kahu har abada kamar wata, amintacciyar shaida a cikin sarari.” Sela ");
INSERT INTO hausa_vpl VALUES ("PS89_38","020_89_38","PSA","89","38","38","Amma ka ƙi, ka yi ƙyama ka kuma yi fushi sosai da shafaffenka. ");
INSERT INTO hausa_vpl VALUES ("PS89_39","020_89_39","PSA","89","39","39","Ka soke alkawarin da ka yi da bawanka ka kuma ƙazantar da rawaninsa a ƙura. ");
INSERT INTO hausa_vpl VALUES ("PS89_40","020_89_40","PSA","89","40","40","Ka rurrushe dukan katangansa ka sa kagaransa suka zama kufai. ");
INSERT INTO hausa_vpl VALUES ("PS89_41","020_89_41","PSA","89","41","41","Dukan waɗanda suka wuce sun washe shi; ya zama abin dariya wajen maƙwabtansa. ");
INSERT INTO hausa_vpl VALUES ("PS89_42","020_89_42","PSA","89","42","42","Ka ɗaukaka hannun dama na maƙiyansa; ka sa dukan abokan gābansa suna farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS89_43","020_89_43","PSA","89","43","43","Ka juye bakin takobinsa ba ka kuma taimake shi a cikin yaƙi ba. ");
INSERT INTO hausa_vpl VALUES ("PS89_44","020_89_44","PSA","89","44","44","Ka kawo ƙarshen darajarsa ka kuma jefar da kursiyinsa ƙasa. ");
INSERT INTO hausa_vpl VALUES ("PS89_45","020_89_45","PSA","89","45","45","Ka rage kwanakin ƙuruciyarsa; ka rufe shi da mayafin kunya. Sela ");
INSERT INTO hausa_vpl VALUES ("PS89_46","020_89_46","PSA","89","46","46","Har yaushe, ya Ubangiji za ka ɓoye? Za ka ɓoye har abada ne? Har yaushe fushinka zai yi ta ci kamar wuta? ");
INSERT INTO hausa_vpl VALUES ("PS89_47","020_89_47","PSA","89","47","47","Ka tuna yadda raina mai wucewa ne. Gama ka halicce dukan mutane ba amfani! ");
INSERT INTO hausa_vpl VALUES ("PS89_48","020_89_48","PSA","89","48","48","Wanda mutum ne zai rayu da ba zai ga mutuwa ba, ko yă cece kansa daga ikon kabari? Sela ");
INSERT INTO hausa_vpl VALUES ("PS89_49","020_89_49","PSA","89","49","49","Ya Ubangiji, ina ƙaunar mai girma ta dā, wadda cikin amincinka ka rantse wa Dawuda? ");
INSERT INTO hausa_vpl VALUES ("PS89_50","020_89_50","PSA","89","50","50","Ka tuna, Ubangiji, yadda aka yi wa bawanka ba’a, yadda na jimre a zuciyata da zage-zagen dukan al’ummai, ");
INSERT INTO hausa_vpl VALUES ("PS89_51","020_89_51","PSA","89","51","51","zage-zagen da abokan gābanka suka yi mini, ya Ubangiji, da suka yi wa kowane matakin da shafaffenka ya ɗauka. ");
INSERT INTO hausa_vpl VALUES ("PS89_52","020_89_52","PSA","89","52","52","Yabo ya tabbata ga Ubangiji har abada! ");
INSERT INTO hausa_vpl VALUES ("PS90_1","020_90_1","PSA","90","1","1","Addu’ar Musa Mutumin Allah. Ubangiji kai ne mazauninmu cikin dukan zamanai. ");
INSERT INTO hausa_vpl VALUES ("PS90_2","020_90_2","PSA","90","2","2","Kafin a haifi duwatsu ko a fid da ƙasa da duniya, daga madawwami zuwa madawwami kai Allah ne. ");
INSERT INTO hausa_vpl VALUES ("PS90_3","020_90_3","PSA","90","3","3","Ka komar da mutane zuwa ƙura, kana cewa, “Ku koma ƙura, ya ku ’ya’yan mutane.” ");
INSERT INTO hausa_vpl VALUES ("PS90_4","020_90_4","PSA","90","4","4","Gama shekaru dubu a gabanka kamar kwana ɗaya ne da ya wuce, ko sa’a guda na dare. ");
INSERT INTO hausa_vpl VALUES ("PS90_5","020_90_5","PSA","90","5","5","Ka share mutane cikin barcin mutuwa; suna kama da sabuwa ciyawar safiya, ");
INSERT INTO hausa_vpl VALUES ("PS90_6","020_90_6","PSA","90","6","6","ko da yake da safe takan yi sabuwar huda da yamma sai ta bushe ta kuma yanƙwane. ");
INSERT INTO hausa_vpl VALUES ("PS90_7","020_90_7","PSA","90","7","7","An cinye mu ta wurin fushinka mun kuma razana ta wurin hasalarka. ");
INSERT INTO hausa_vpl VALUES ("PS90_8","020_90_8","PSA","90","8","8","Ka ajiye laifinmu a gabanka, asirin zunubanmu a hasken kasancewarka. ");
INSERT INTO hausa_vpl VALUES ("PS90_9","020_90_9","PSA","90","9","9","Dukan kwanakinmu sun wuce ƙarƙashin fushinka; mun gama shekarunmu da nishi. ");
INSERT INTO hausa_vpl VALUES ("PS90_10","020_90_10","PSA","90","10","10","Tsawon kwanakinmu shekaru saba’in ne, ko tamanin, in muna da ƙarfi; duk da haka tsawonsu wahaloli ne kawai da ɓacin rai, gama da sauri suke wucewa, ta mu kuma ta ƙare. ");
INSERT INTO hausa_vpl VALUES ("PS90_11","020_90_11","PSA","90","11","11","Wa ya san ƙarfin fushinka? Gama hasalarka tana da girma kamar tsoron da ya dace da kai. ");
INSERT INTO hausa_vpl VALUES ("PS90_12","020_90_12","PSA","90","12","12","Ka koya mana yawan kwanakinmu daidai, don mu sami zuciyar hikima. ");
INSERT INTO hausa_vpl VALUES ("PS90_13","020_90_13","PSA","90","13","13","Ka ji mu, ya Ubangiji! Har yaushe zai ci gaba? Ka ji tausayin bayinka. ");
INSERT INTO hausa_vpl VALUES ("PS90_14","020_90_14","PSA","90","14","14","Ka ƙosar da mu da safe da ƙaunarka marar ƙarewa, don mu rera don yabo, mu kuma yi murna dukan kwanakinmu. ");
INSERT INTO hausa_vpl VALUES ("PS90_15","020_90_15","PSA","90","15","15","Faranta mana zuciya kamar yawan kwanakin da muka sha azaba, kamar yawan shekarun da muka ga wahala. ");
INSERT INTO hausa_vpl VALUES ("PS90_16","020_90_16","PSA","90","16","16","Bari a nuna ayyukanka ga bayinka, darajarka ga ’ya’yansu. ");
INSERT INTO hausa_vpl VALUES ("PS90_17","020_90_17","PSA","90","17","17","Bari alherin shugabanmu Allah yă kasance a kanmu; ka albarkaci mana aikin hannuwanmu, I, ka albarkaci aikin hannuwanmu. ");
INSERT INTO hausa_vpl VALUES ("PS91_1","020_91_1","PSA","91","1","1","Shi wanda yake zama a wurin Mafi Ɗaukaka zai huta a cikin inuwar Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("PS91_2","020_91_2","PSA","91","2","2","Zan ce game da Ubangiji, “Shi ne mafakata da kagarata, Allahna, wanda nake dogara.” ");
INSERT INTO hausa_vpl VALUES ("PS91_3","020_91_3","PSA","91","3","3","Tabbatacce zai cece ka daga tarkon mai farauta da kuma daga cututtuka masu kisa. ");
INSERT INTO hausa_vpl VALUES ("PS91_4","020_91_4","PSA","91","4","4","Zai rufe ka da fikafikansa, a ƙarƙashin fikafikansa kuwa za ka sami mafaka; amincinsa zai zama maka garkuwa da katanga. ");
INSERT INTO hausa_vpl VALUES ("PS91_5","020_91_5","PSA","91","5","5","Ba za ka ji tsoron razanar dare, ko kibiyoyi da suke firiya da rana ba, ");
INSERT INTO hausa_vpl VALUES ("PS91_6","020_91_6","PSA","91","6","6","ko bala’in da yake aukowa cikin duhu, ko annobar da take hallakarwa da tsakar rana. ");
INSERT INTO hausa_vpl VALUES ("PS91_7","020_91_7","PSA","91","7","7","Dubu za su iya fāɗuwa a gefenka, dubu goma a hannun damanka, amma ba abin da zai zo kusa da kai. ");
INSERT INTO hausa_vpl VALUES ("PS91_8","020_91_8","PSA","91","8","8","Za ka dai gan da idanunka yadda ake hukunta mugaye. ");
INSERT INTO hausa_vpl VALUES ("PS91_9","020_91_9","PSA","91","9","9","In ka mai da Mafi Ɗaukaka wurin zamanka, har ma Ubangiji wanda yake mafakata, ");
INSERT INTO hausa_vpl VALUES ("PS91_10","020_91_10","PSA","91","10","10","to, babu wani mugun abin da zai same ka, ba masifar da za tă zo kusa da tentinka. ");
INSERT INTO hausa_vpl VALUES ("PS91_11","020_91_11","PSA","91","11","11","Gama zai umarci mala’ikunsa game da kai don su tsare ka a dukan hanyoyinka; ");
INSERT INTO hausa_vpl VALUES ("PS91_12","020_91_12","PSA","91","12","12","za su tallafe ka da hannuwansu, don kada ka buga ƙafarka a kan dutse. ");
INSERT INTO hausa_vpl VALUES ("PS91_13","020_91_13","PSA","91","13","13","Za ka taka zaki da gamsheƙa; za ka tattake babban zaki da maciji. ");
INSERT INTO hausa_vpl VALUES ("PS91_14","020_91_14","PSA","91","14","14","Ubangiji ya ce, “Domin ya ƙaunace ni, zan kuɓutar da shi; zan kiyaye shi, gama ya yarda da sunana. ");
INSERT INTO hausa_vpl VALUES ("PS91_15","020_91_15","PSA","91","15","15","Zai kira bisa sunana, zan kuma amsa masa; zan kasance tare da shi a lokacin wahala, zan kuɓutar da shi in kuma girmama shi. ");
INSERT INTO hausa_vpl VALUES ("PS91_16","020_91_16","PSA","91","16","16","Da tsawon rai zan ƙosar da shi in kuma nuna masa cetona.” ");
INSERT INTO hausa_vpl VALUES ("PS92_1","020_92_1","PSA","92","1","1","Zabura ce. Waƙa ce. Domin ranar Asabbaci. Yana da kyau a yabi Ubangiji a kuma yi kiɗi ga sunanka, ya Mafi Ɗaukaka, ");
INSERT INTO hausa_vpl VALUES ("PS92_2","020_92_2","PSA","92","2","2","don a yi shelar ƙaunarka da safe amincinka kuma da dare, ");
INSERT INTO hausa_vpl VALUES ("PS92_3","020_92_3","PSA","92","3","3","da kiɗin molo mai tsirkiya goma da kuma ƙarar garaya. ");
INSERT INTO hausa_vpl VALUES ("PS92_4","020_92_4","PSA","92","4","4","Gama ka sa na yi murna ta wurin ayyukanka, ya Ubangiji; na rera don farin ciki saboda ayyukan hannuwanka. ");
INSERT INTO hausa_vpl VALUES ("PS92_5","020_92_5","PSA","92","5","5","Ina misalin ayyukanka, ya Ubangiji, tunaninka da zurfi suke ƙwarai! ");
INSERT INTO hausa_vpl VALUES ("PS92_6","020_92_6","PSA","92","6","6","Mutum marar azanci ba zai sani ba, wawa ba zai gane ba, ");
INSERT INTO hausa_vpl VALUES ("PS92_7","020_92_7","PSA","92","7","7","cewa ko da yake mugaye suna girma kamar ciyawa kuma dukan masu aikata mugunta suna haɓaka, za a hallaka su har abada. ");
INSERT INTO hausa_vpl VALUES ("PS92_8","020_92_8","PSA","92","8","8","Amma kai, ya Ubangiji, za a ɗaukaka har abada. ");
INSERT INTO hausa_vpl VALUES ("PS92_9","020_92_9","PSA","92","9","9","Gama tabbatacce abokan gābanka, ya Ubangiji, tabbatacce abokan gābanka za su hallaka; za a watsar da dukan masu aikata mugunta. ");
INSERT INTO hausa_vpl VALUES ("PS92_10","020_92_10","PSA","92","10","10","Ka ɗaukaka ƙahona kamar na ɓauna; an zubo mai masu kyau a kaina. ");
INSERT INTO hausa_vpl VALUES ("PS92_11","020_92_11","PSA","92","11","11","Idanuna sun ga fāɗuwar maƙiyana; kunnuwana sun ji kukan mugayen maƙiyana. ");
INSERT INTO hausa_vpl VALUES ("PS92_12","020_92_12","PSA","92","12","12","Adalai za su haɓaka kamar itacen dabino, za su yi girma kama al’ul na Lebanon; ");
INSERT INTO hausa_vpl VALUES ("PS92_13","020_92_13","PSA","92","13","13","da aka daddasa a gidan Ubangiji, za su haɓaka a filayen gidan Allahnmu. ");
INSERT INTO hausa_vpl VALUES ("PS92_14","020_92_14","PSA","92","14","14","Za su ci gaba da ba da ’ya’ya a tsufansu, za su kasance ɗanye kuma kore shar, ");
INSERT INTO hausa_vpl VALUES ("PS92_15","020_92_15","PSA","92","15","15","suna shela cewa, “Ubangiji adali ne; shi ne Dutsena, kuma babu mugunta a cikinsa.” ");
INSERT INTO hausa_vpl VALUES ("PS93_1","020_93_1","PSA","93","1","1","Ubangiji yana mulki, yana sanye da ɗaukaka; Ubangiji yana sanye da ɗaukaka yana kuma sanye da ƙarfi. An kafa duniya daram; ba za a iya matsar da ita ba. ");
INSERT INTO hausa_vpl VALUES ("PS93_2","020_93_2","PSA","93","2","2","An kafa kursiyin tun da daɗewa; kana nan tun fil azal. ");
INSERT INTO hausa_vpl VALUES ("PS93_3","020_93_3","PSA","93","3","3","Tekuna sun taso, ya Ubangiji, tekuna sun ta da muryarsu; tekuna sun tā da ta raƙumansu masu tumbatsa. ");
INSERT INTO hausa_vpl VALUES ("PS93_4","020_93_4","PSA","93","4","4","Mafi ƙarfi fiye da tsawan manyan ruwaye, mafi ƙarfi fiye da ikon raƙuman ruwan teku, Ubangiji mai zama a bisa mai girma ne. ");
INSERT INTO hausa_vpl VALUES ("PS93_5","020_93_5","PSA","93","5","5","Ƙa’idodinka suna nan daram; tsarki ya yi wa gidanka ado har kwanaki marar ƙarewa, ya Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS94_1","020_94_1","PSA","94","1","1","Ya Ubangiji, Allahn da yake ramuwa, Ya Allah wanda yake ramuwa, ka haskaka. ");
INSERT INTO hausa_vpl VALUES ("PS94_2","020_94_2","PSA","94","2","2","Ka tashi, ya Alƙalin duniya; ka sāka wa masu girman kai abin da ya dace da su. ");
INSERT INTO hausa_vpl VALUES ("PS94_3","020_94_3","PSA","94","3","3","Har yaushe mugaye, ya Ubangiji har yaushe mugaye za su yi ta murna? ");
INSERT INTO hausa_vpl VALUES ("PS94_4","020_94_4","PSA","94","4","4","Suna ta yin maganganun fariya; dukan masu aikata mugunta sun cika da fariya. ");
INSERT INTO hausa_vpl VALUES ("PS94_5","020_94_5","PSA","94","5","5","Suna murƙushe mutanenka, ya Ubangiji; suna danne gādonka. ");
INSERT INTO hausa_vpl VALUES ("PS94_6","020_94_6","PSA","94","6","6","Suna kashe gwauraye da kuma baƙi; suna kisan marayu. ");
INSERT INTO hausa_vpl VALUES ("PS94_7","020_94_7","PSA","94","7","7","Suna ce, “Ubangiji ba ya gani; Allah na Yaƙub bai kula ba.” ");
INSERT INTO hausa_vpl VALUES ("PS94_8","020_94_8","PSA","94","8","8","Ku mai da hankali, ku marasa azanci a cikin mutane; ku wawaye, yaushe za ku zama masu hikima? ");
INSERT INTO hausa_vpl VALUES ("PS94_9","020_94_9","PSA","94","9","9","Shi da ya sa kunne ba don a ji ba ne? Shi da ya yi ido ba don yă gani ba ne? ");
INSERT INTO hausa_vpl VALUES ("PS94_10","020_94_10","PSA","94","10","10","Shi da yake yi wa al’ummai horo ba ya hukunci ne? Shi da yake koya wa mutum ba shi da sani ne? ");
INSERT INTO hausa_vpl VALUES ("PS94_11","020_94_11","PSA","94","11","11","Ubangiji ya san tunanin mutum; ya san cewa tunaninsu banza ne. ");
INSERT INTO hausa_vpl VALUES ("PS94_12","020_94_12","PSA","94","12","12","Mai albarka ne mutumin da ka yi masa horo, ya Ubangiji, mutumin da ka koyar daga dokarka; ");
INSERT INTO hausa_vpl VALUES ("PS94_13","020_94_13","PSA","94","13","13","kana ba shi sauƙi a lokacin wahala, sai har an haƙa rami wa mugaye. ");
INSERT INTO hausa_vpl VALUES ("PS94_14","020_94_14","PSA","94","14","14","Gama Ubangiji ba zai ƙi mutanensa ba; ba zai taɓa yashe gādonsa ba. ");
INSERT INTO hausa_vpl VALUES ("PS94_15","020_94_15","PSA","94","15","15","Za a sāke kafa hukunci a kan adalci, kuma dukan masu adalci a zuciya za su bi shi. ");
INSERT INTO hausa_vpl VALUES ("PS94_16","020_94_16","PSA","94","16","16","Wane ne zai yi gāba da mugaye domina? Wane ne zai ɗauki matsayi ya yi gāba da masu aikata mugunta domina? ");
INSERT INTO hausa_vpl VALUES ("PS94_17","020_94_17","PSA","94","17","17","Da ba don Ubangiji ya yi mini taimako ba, da tuni na zauna shiru a wurin mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PS94_18","020_94_18","PSA","94","18","18","Sa’ad da na ce, “Ƙafata na santsi,” ƙaunarka, ya Ubangiji, ta riƙe ni. ");
INSERT INTO hausa_vpl VALUES ("PS94_19","020_94_19","PSA","94","19","19","Sa’ad da alhini ya yi yawa a cikina, ta’aziyyarka ta kawo farin ciki wa raina. ");
INSERT INTO hausa_vpl VALUES ("PS94_20","020_94_20","PSA","94","20","20","Zai yiwu kursiyin da ya cika da lalaci yă haɗa kai da kai, wanda yake kawo azaba ta wurin abin da ya zartar? ");
INSERT INTO hausa_vpl VALUES ("PS94_21","020_94_21","PSA","94","21","21","Sun yi ƙungiya tare a kan mai adalci suka yanke wa marar laifi hukuncin mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PS94_22","020_94_22","PSA","94","22","22","Amma Ubangiji ya zama kagarata, Allahna kuma dutsen da nake samun mafaka. ");
INSERT INTO hausa_vpl VALUES ("PS94_23","020_94_23","PSA","94","23","23","Zai sāka musu saboda zunubansu yă kuma hallaka su saboda muguntarsu; Ubangiji Allahnmu zai hallaka su. ");
INSERT INTO hausa_vpl VALUES ("PS95_1","020_95_1","PSA","95","1","1","Ku zo, bari mu rera don farin ciki ga Ubangiji; bari mu yi sowa da ƙarfi ga Dutsen cetonmu. ");
INSERT INTO hausa_vpl VALUES ("PS95_2","020_95_2","PSA","95","2","2","Bari mu zo gabansa da godiya mu rera gare shi da kiɗi da waƙa. ");
INSERT INTO hausa_vpl VALUES ("PS95_3","020_95_3","PSA","95","3","3","Gama Ubangiji Allah mai girma ne, babban Sarki a bisa dukan alloli. ");
INSERT INTO hausa_vpl VALUES ("PS95_4","020_95_4","PSA","95","4","4","A hannunsa ne zurfafan duniya suke, ƙwanƙolin dutse kuma nasa ne. ");
INSERT INTO hausa_vpl VALUES ("PS95_5","020_95_5","PSA","95","5","5","Teku nasa ne, gama shi ne ya yi shi, da hannuwansa kuma ya yi busasshiyar ƙasa. ");
INSERT INTO hausa_vpl VALUES ("PS95_6","020_95_6","PSA","95","6","6","Ku zo, bari mu rusuna mu yi sujada, bari mu durƙusa a gaban Ubangiji Mahaliccinmu; ");
INSERT INTO hausa_vpl VALUES ("PS95_7","020_95_7","PSA","95","7","7","gama shi ne Allahnmu mu mutanen makiyayansa ne, garke kuwa a ƙarƙashin kulawarsa. Yau, in kuka ji muryarsa, ");
INSERT INTO hausa_vpl VALUES ("PS95_8","020_95_8","PSA","95","8","8","“Kada ku taurare zukatanku kamar yadda kuka yi a Meriba, kamar yadda kuka yi a wancan rana a Massa a hamada, ");
INSERT INTO hausa_vpl VALUES ("PS95_9","020_95_9","PSA","95","9","9","inda kakanninku suka gwada suka kuma jarraba ni, ko da yake sun ga abin da na yi. ");
INSERT INTO hausa_vpl VALUES ("PS95_10","020_95_10","PSA","95","10","10","Shekara arba’in na yi fushi da wancan tsara; na ce, ‘Su mutane ne waɗanda zukatansu suka kauce, kuma ba su san hanyoyina ba.’ ");
INSERT INTO hausa_vpl VALUES ("PS95_11","020_95_11","PSA","95","11","11","Saboda haka na yi rantsuwa cikin fushina, ‘Ba za su taɓa shiga hutuna ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("PS96_1","020_96_1","PSA","96","1","1","Ku rera sabuwar waƙa ga Ubangiji; ku rera ga Ubangiji, ku duniya duka. ");
INSERT INTO hausa_vpl VALUES ("PS96_2","020_96_2","PSA","96","2","2","Ku rera ga Ubangiji, ku yabe sunansa; ku yi shelar cetonsa kowace rana. ");
INSERT INTO hausa_vpl VALUES ("PS96_3","020_96_3","PSA","96","3","3","Ku furta ɗaukakarsa a cikin al’ummai, manyan ayyukansa a cikin dukan mutane. ");
INSERT INTO hausa_vpl VALUES ("PS96_4","020_96_4","PSA","96","4","4","Gama da girma Ubangiji yake, ya kuma cancanci yabo; tilas a ji tsoronsa fiye da dukan alloli. ");
INSERT INTO hausa_vpl VALUES ("PS96_5","020_96_5","PSA","96","5","5","Gama dukan allolin al’ummai gumaka ne, amma Ubangiji ne ya yi sammai. ");
INSERT INTO hausa_vpl VALUES ("PS96_6","020_96_6","PSA","96","6","6","Daraja da ɗaukaka suna a gabansa; ƙarfi da ɗaukaka suna a cikin tsarkakar wurinsa. ");
INSERT INTO hausa_vpl VALUES ("PS96_7","020_96_7","PSA","96","7","7","Ku ba wa Ubangiji, ya iyalan al’ummai ku ba wa Ubangiji ɗaukaka da kuma ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("PS96_8","020_96_8","PSA","96","8","8","Ku ba wa Ubangiji ɗaukakar da ta dace da sunansa; ku kawo sadaka ku kuma zo cikin filayen gidansa. ");
INSERT INTO hausa_vpl VALUES ("PS96_9","020_96_9","PSA","96","9","9","Ku bauta wa Ubangiji da darajar tsarkinsa; ku yi rawar jiki a gabansa, dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS96_10","020_96_10","PSA","96","10","10","Ku faɗa cikin al’ummai, “Ubangiji yana mulki.” Duniya ta kahu daram, ba za a iya matsar da ita ba; zai yi wa mutane hukunci da gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PS96_11","020_96_11","PSA","96","11","11","Bari sammai su yi farin ciki, bari duniya tă yi murna; bari teku tă yi ruri, da kuma dukan abin da yake cikinsa; ");
INSERT INTO hausa_vpl VALUES ("PS96_12","020_96_12","PSA","96","12","12","bari gonaki su yi tsalle da murna, da kuma kome da yake cikinsu. Ta haka dukan itatuwan kurmi za su rera don farin ciki; ");
INSERT INTO hausa_vpl VALUES ("PS96_13","020_96_13","PSA","96","13","13","za su rera a gaban Ubangiji, gama yana zuwa, yana zuwa don yă hukunta duniya. Zai hukunta duniya cikin adalci mutane kuma cikin amincinsa. ");
INSERT INTO hausa_vpl VALUES ("PS97_1","020_97_1","PSA","97","1","1","Ubangiji yana mulki, bari duniya tă yi murna; bari tsibirai masu nesa su yi farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS97_2","020_97_2","PSA","97","2","2","Gizagizai da baƙin duhu sun kewaye shi; adalci da gaskiya su ne tushen kursiyinsa. ");
INSERT INTO hausa_vpl VALUES ("PS97_3","020_97_3","PSA","97","3","3","Wuta tana tafiya a gabansa tana kuma cinye maƙiyansa a kowane gefe. ");
INSERT INTO hausa_vpl VALUES ("PS97_4","020_97_4","PSA","97","4","4","Walƙiyarsa ta haskaka duniya; duniya ta gani ta kuma yi rawar jiki. ");
INSERT INTO hausa_vpl VALUES ("PS97_5","020_97_5","PSA","97","5","5","Duwatsu sun narke kamar kakin zuma a gaban Ubangiji, a gaban Ubangijin dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS97_6","020_97_6","PSA","97","6","6","Sammai sun yi shelar adalcinsa, dukan mutane kuma suka ga ɗaukakarsa. ");
INSERT INTO hausa_vpl VALUES ("PS97_7","020_97_7","PSA","97","7","7","Dukan waɗanda suke bauta wa siffofi sun sha kunya, waɗanda suke fariya da gumaka, ku yi masa sujada, dukanku alloli! ");
INSERT INTO hausa_vpl VALUES ("PS97_8","020_97_8","PSA","97","8","8","Sihiyona ta ji ta kuma yi farin ciki kuma dukan ƙauyukan Yahuda suna murna saboda hukunce-hukuncenka, ya Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS97_9","020_97_9","PSA","97","9","9","Gama kai, ya Ubangiji, kai ne Mafi Ɗaukaka a bisa dukan duniya; ana darjanta ka fiye da dukan alloli. ");
INSERT INTO hausa_vpl VALUES ("PS97_10","020_97_10","PSA","97","10","10","Bari masu ƙaunar Ubangiji su ƙi mugunta, gama yana tsaron rayukan amintattunsa yana kuma kuɓutar da su daga hannun mugaye. ");
INSERT INTO hausa_vpl VALUES ("PS97_11","020_97_11","PSA","97","11","11","An haskaka haske a kan masu adalci da kuma farin ciki a kan masu gaskiya a zuciya. ");
INSERT INTO hausa_vpl VALUES ("PS97_12","020_97_12","PSA","97","12","12","Ku yi farin ciki a cikin Ubangiji, ku da kuke masu adalci, ku kuma yabi sunansa mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("PS98_1","020_98_1","PSA","98","1","1","Zabura ce. Ku rera sabuwar waƙa ga Ubangiji, gama ya yi abubuwa masu banmamaki; hannunsa na dama da hannunsa mai tsarki sun yi masa aikin ceto. ");
INSERT INTO hausa_vpl VALUES ("PS98_2","020_98_2","PSA","98","2","2","Ubangiji ya sanar da cetonsa ya kuma bayyana adalcinsa ga al’ummai. ");
INSERT INTO hausa_vpl VALUES ("PS98_3","020_98_3","PSA","98","3","3","Ya tuna da ƙaunarsa da kuma amincinsa ga gidan Isra’ila; dukan iyakar duniya sun ga ceton Allahnmu. ");
INSERT INTO hausa_vpl VALUES ("PS98_4","020_98_4","PSA","98","4","4","Ku yi sowa don farin ciki ga Ubangiji, dukan duniya, ku ɓarke da waƙa ta murna tare da kiɗi; ");
INSERT INTO hausa_vpl VALUES ("PS98_5","020_98_5","PSA","98","5","5","ku yi kiɗi ga Ubangiji da garaya, da garaya da ƙarar rerawa, ");
INSERT INTO hausa_vpl VALUES ("PS98_6","020_98_6","PSA","98","6","6","tare da bushe-bushe da karar ƙahon rago, ku yi sowa don farin ciki a gaban Ubangiji, Sarki. ");
INSERT INTO hausa_vpl VALUES ("PS98_7","020_98_7","PSA","98","7","7","Bari teku su yi ruri, da kuma kome da yake cikinsa, duniya da kuma kome da yake cikinta. ");
INSERT INTO hausa_vpl VALUES ("PS98_8","020_98_8","PSA","98","8","8","Bari koguna su tafa hannuwansu, bari duwatsu su rera tare don farin ciki; ");
INSERT INTO hausa_vpl VALUES ("PS98_9","020_98_9","PSA","98","9","9","bari su rera a gaban Ubangiji, gama yana zuwa domin yă hukunta duniya. Zai hukunta duniya da adalci mutane kuma cikin gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PS99_1","020_99_1","PSA","99","1","1","Ubangiji yana mulki, bari al’ummai su yi rawan jiki; yana zaune a kursiyi tsakanin kerubobi, bari duniya ta girgiza. ");
INSERT INTO hausa_vpl VALUES ("PS99_2","020_99_2","PSA","99","2","2","Ubangiji mai girma yana a Sihiyona; an ɗaukaka shi a bisa dukan al’ummai. ");
INSERT INTO hausa_vpl VALUES ("PS99_3","020_99_3","PSA","99","3","3","Bari mu yabi girmanka da sunanka mai banrazana, shi mai tsarki ne. ");
INSERT INTO hausa_vpl VALUES ("PS99_4","020_99_4","PSA","99","4","4","Sarki mai iko ne, yana ƙaunar adalci ka kafa gaskiya; a cikin Yaƙub ka yi abin da yake mai adalci da kuma daidai. ");
INSERT INTO hausa_vpl VALUES ("PS99_5","020_99_5","PSA","99","5","5","Ku ɗaukaka Ubangiji Allahnmu ku kuma yi masa sujada a wurin sa ƙafafunsa; shi mai tsarki ne. ");
INSERT INTO hausa_vpl VALUES ("PS99_6","020_99_6","PSA","99","6","6","Musa da Haruna suna cikin firistocinsa, Sama’ila yana cikin waɗanda suka kira bisa sunansa; sun kira ga Ubangiji ya kuwa amsa musu. ");
INSERT INTO hausa_vpl VALUES ("PS99_7","020_99_7","PSA","99","7","7","Ya yi magana da su daga ginshiƙin girgije; ya kiyaye farillansa da ƙa’idodin da ya ba su. ");
INSERT INTO hausa_vpl VALUES ("PS99_8","020_99_8","PSA","99","8","8","Ya Ubangiji Allahnmu, ka amsa musu; ka kasance wa Isra’ila Allah mai gafartawa, ko da yake ka hukunta ayyukansu marasa kyau. ");
INSERT INTO hausa_vpl VALUES ("PS99_9","020_99_9","PSA","99","9","9","Ku ɗaukaka Ubangiji Allahnmu ku kuma yi sujada a dutsensa mai tsarki, gama Ubangiji Allahnmu mai tsarki ne. ");
INSERT INTO hausa_vpl VALUES ("PS100_1","020_100_1","PSA","100","1","1","Zabura ce. Don yin godiya. Ku yi sowa don farin ciki ga Ubangiji, dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS100_2","020_100_2","PSA","100","2","2","Yi wa Ubangiji sujada da murna; ku zo gabansa da waƙoƙin farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS100_3","020_100_3","PSA","100","3","3","Ku san cewa Ubangiji shi ne Allah. Shi ne ya yi mu, mu kuwa nasa ne; mu mutanensa ne, tumakin makiyayarsa. ");
INSERT INTO hausa_vpl VALUES ("PS100_4","020_100_4","PSA","100","4","4","Ku shiga ƙofofinsa da godiya filayen gidansa kuma da yabo; ku gode masa ku kuma yabi sunansa. ");
INSERT INTO hausa_vpl VALUES ("PS100_5","020_100_5","PSA","100","5","5","Gama Ubangiji yana da kyau kuma ƙaunarsa madawwamiya ce har abada; amincinsa na cin gaba a dukan zamanai. ");
INSERT INTO hausa_vpl VALUES ("PS101_1","020_101_1","PSA","101","1","1","Ta Dawuda. Zabura ce. Zan rera wa ƙauna da adalcinka; gare ka, ya Ubangiji, zan rera yabo. ");
INSERT INTO hausa_vpl VALUES ("PS101_2","020_101_2","PSA","101","2","2","Zan yi hankali ga yin rayuwa marar zargi, yaushe za ka zo gare ni? Zan bi da sha’anin gidana da zuciya marar abin zargi ");
INSERT INTO hausa_vpl VALUES ("PS101_3","020_101_3","PSA","101","3","3","Ba zan kafa a gaban idanuna 1 wani abu marar kyau ba. Na ƙi jinin ayyukan mutane marasa aminci; ba za su manne mini ba. ");
INSERT INTO hausa_vpl VALUES ("PS101_4","020_101_4","PSA","101","4","4","Mutane masu mugun zuciya za su nesa da ni; ba abin da zai haɗa ni da mugunta. ");
INSERT INTO hausa_vpl VALUES ("PS101_5","020_101_5","PSA","101","5","5","Duk wanda ya yi ɓatanci wa maƙwabcinsa a ɓoye shi za a kashe; duk mai renin wayo da mai girman kai, ba zan jure masa ba. ");
INSERT INTO hausa_vpl VALUES ("PS101_6","020_101_6","PSA","101","6","6","Idanuna za su kasance a kan amintattu a cikin ƙasar, don su zauna tare da ni; tafiyarsa ba ta da zargi zai yi mini hidima. ");
INSERT INTO hausa_vpl VALUES ("PS101_7","020_101_7","PSA","101","7","7","Babu mai ruɗun da zai zauna a gidana; babu mai ƙaryan da zai tsaya a gabana. ");
INSERT INTO hausa_vpl VALUES ("PS101_8","020_101_8","PSA","101","8","8","Kowace safiya zan rufe bakunan dukan mugaye a ƙasar; zan yanke kowane mai aikata mugunta daga birnin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS102_1","020_102_1","PSA","102","1","1","Addu’ar mutum mai shan wahala. Sa’ad da ya rasa ƙarfi ya kuma yi makoki a gaban Ubangiji. Ka ji addu’ata, ya Ubangiji; bari kukata ta neman taimako ta zo gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS102_2","020_102_2","PSA","102","2","2","Kada ka ɓoye fuskarka daga gare ni sa’ad da nake cikin damuwa. Ka juye kunnenka gare ni; sa’ad da na yi kira, ka amsa mini da sauri. ");
INSERT INTO hausa_vpl VALUES ("PS102_3","020_102_3","PSA","102","3","3","Gama kwanakina sun ɓace kamar hayaƙi; ƙasusuwana suna ƙuna kamar jan wuta. ");
INSERT INTO hausa_vpl VALUES ("PS102_4","020_102_4","PSA","102","4","4","Zuciyata ta kamu da ciwo ta kuma bushe kamar ciyawa; na manta in ci abinci. ");
INSERT INTO hausa_vpl VALUES ("PS102_5","020_102_5","PSA","102","5","5","Saboda nishina mai ƙarfi na rame na bar ƙasusuwa kawai. ");
INSERT INTO hausa_vpl VALUES ("PS102_6","020_102_6","PSA","102","6","6","Ni kamar mujiyar jeji ne, kamar mujiya a kufai. ");
INSERT INTO hausa_vpl VALUES ("PS102_7","020_102_7","PSA","102","7","7","Na kwanta a faɗake; na zama kamar tsuntsun da yake shi kaɗai a kan rufin ɗaki. ");
INSERT INTO hausa_vpl VALUES ("PS102_8","020_102_8","PSA","102","8","8","Dukan yini abokan gābana suna tsokanata; waɗanda suke mini ba’a suna amfani da sunana yă zama abin la’ana. ");
INSERT INTO hausa_vpl VALUES ("PS102_9","020_102_9","PSA","102","9","9","Gama ina cin toka a matsayin abincina ina kuma gauraye abin sha nawa da hawaye ");
INSERT INTO hausa_vpl VALUES ("PS102_10","020_102_10","PSA","102","10","10","saboda fushinka mai girma, gama ka ɗaga ni sama ka yar a gefe. ");
INSERT INTO hausa_vpl VALUES ("PS102_11","020_102_11","PSA","102","11","11","Kwanakina suna kamar inuwar yamma; na bushe kamar ciyawa. ");
INSERT INTO hausa_vpl VALUES ("PS102_12","020_102_12","PSA","102","12","12","Amma kai, ya Ubangiji, kana zaune a kursiyinka har abada; sunan da ka yi zai dawwama a dukan zamanai. ");
INSERT INTO hausa_vpl VALUES ("PS102_13","020_102_13","PSA","102","13","13","Za ka tashi ka kuma ji tausayin Sihiyona, gama lokaci ne na nuna alheri gare ta; ƙayyadadden lokacin ya zo. ");
INSERT INTO hausa_vpl VALUES ("PS102_14","020_102_14","PSA","102","14","14","Gama duwatsunta suna da daraja ga bayinka; ƙurarta kawai kan sa su ji tausayi. ");
INSERT INTO hausa_vpl VALUES ("PS102_15","020_102_15","PSA","102","15","15","Al’ummai za su ji tsoron sunan Ubangiji, dukan sarakunan duniya za su girmama ɗaukakarka. ");
INSERT INTO hausa_vpl VALUES ("PS102_16","020_102_16","PSA","102","16","16","Gama Ubangiji zai sāke gina Sihiyona ya kuma bayyana a ɗaukakarsa. ");
INSERT INTO hausa_vpl VALUES ("PS102_17","020_102_17","PSA","102","17","17","Zai amsa addu’ar marasa ƙarfi; ba zai ƙyale roƙonsu ba. ");
INSERT INTO hausa_vpl VALUES ("PS102_18","020_102_18","PSA","102","18","18","Bari a rubuta wannan don tsara mai zuwa, cewa mutanen da ba a riga an halitta ba za su yabi Ubangiji, ");
INSERT INTO hausa_vpl VALUES ("PS102_19","020_102_19","PSA","102","19","19","“Ubangiji ya duba ƙasa daga wurinsa mai tsarki a bisa, daga sama ya hangi duniya, ");
INSERT INTO hausa_vpl VALUES ("PS102_20","020_102_20","PSA","102","20","20","don yă ji nishe-nishen ’yan kurkuku yă kuma saki waɗanda aka yanke musu hukuncin mutuwa.” ");
INSERT INTO hausa_vpl VALUES ("PS102_21","020_102_21","PSA","102","21","21","Saboda haka za a furta sunan Ubangiji a Sihiyona yabonsa kuma a Urushalima ");
INSERT INTO hausa_vpl VALUES ("PS102_22","020_102_22","PSA","102","22","22","sa’ad da mutane da mulkoki suka tattaru don su yi wa Ubangiji sujada. ");
INSERT INTO hausa_vpl VALUES ("PS102_23","020_102_23","PSA","102","23","23","Cikin rayuwata, ya karye ƙarfina; ya gajartar da kwanakina. ");
INSERT INTO hausa_vpl VALUES ("PS102_24","020_102_24","PSA","102","24","24","Sai na ce, “Kada ka ɗauke ni a tsakiyar kwanakina, ya Allah; shekarunka suna bi cikin dukan zamanai. ");
INSERT INTO hausa_vpl VALUES ("PS102_25","020_102_25","PSA","102","25","25","A farkon fari ka kafa tushen duniya, sammai kuma aikin hannuwanka ne. ");
INSERT INTO hausa_vpl VALUES ("PS102_26","020_102_26","PSA","102","26","26","Za su hallaka, amma za ka ci gaba; duk za su tsufe kamar riga. Kamar riga za ka canja su za a kuwa zubar da su. ");
INSERT INTO hausa_vpl VALUES ("PS102_27","020_102_27","PSA","102","27","27","Amma kana nan yadda kake, kuma shekarunka ba za su taɓa ƙarewa ba. ");
INSERT INTO hausa_vpl VALUES ("PS102_28","020_102_28","PSA","102","28","28","’Ya’yan bayinka za su zauna a gabanka; zuriyarsu za su kahu a gabanka.” ");
INSERT INTO hausa_vpl VALUES ("PS103_1","020_103_1","PSA","103","1","1","Ta Dawuda. Yabi Ubangiji, ya raina; dukan abin da yake cikin cikina, yabi sunansa mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("PS103_2","020_103_2","PSA","103","2","2","Yabi Ubangiji, ya raina, kada kuma ka manta dukan alheransa, ");
INSERT INTO hausa_vpl VALUES ("PS103_3","020_103_3","PSA","103","3","3","wanda yake gafarta dukan zunubai yake kuma warkar da dukan cututtuka, ");
INSERT INTO hausa_vpl VALUES ("PS103_4","020_103_4","PSA","103","4","4","wanda ya fanshi ranka daga rami ya naɗa maka rawani da ƙauna da kuma tausayi, ");
INSERT INTO hausa_vpl VALUES ("PS103_5","020_103_5","PSA","103","5","5","Wanda ya ƙosar da kai da abubuwa masu kyau domin a sabunta ƙuruciyarka kamar na gaggafa. ");
INSERT INTO hausa_vpl VALUES ("PS103_6","020_103_6","PSA","103","6","6","Ubangiji yana aikata adalci da kuma gaskiya ga duk waɗanda aka danne. ");
INSERT INTO hausa_vpl VALUES ("PS103_7","020_103_7","PSA","103","7","7","Ya sanar da hanyoyinsa wa Musa, ayyukansa ga mutanen Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS103_8","020_103_8","PSA","103","8","8","Ubangiji mai tausayi ne da kuma alheri, mai jinkirin fushi, cike da ƙauna. ");
INSERT INTO hausa_vpl VALUES ("PS103_9","020_103_9","PSA","103","9","9","Ba zai yi ta zargi ba ba kuwa zai yi ta jin fushi har abada ba; ");
INSERT INTO hausa_vpl VALUES ("PS103_10","020_103_10","PSA","103","10","10","ba ya yin da mu gwargwadon zunubanmu ko yă sāka mana bisa ga laifofinmu. ");
INSERT INTO hausa_vpl VALUES ("PS103_11","020_103_11","PSA","103","11","11","Gama kamar yadda sammai suke can bisa duniya, haka girmar ƙaunarsa yake wa masu tsoronsa; ");
INSERT INTO hausa_vpl VALUES ("PS103_12","020_103_12","PSA","103","12","12","kamar yadda gabas yake daga yamma, haka ya cire laifofinmu daga gare mu. ");
INSERT INTO hausa_vpl VALUES ("PS103_13","020_103_13","PSA","103","13","13","Kamar yadda mahaifi yake jin tausayin ’ya’yansa, haka Ubangiji yake jin tausayin waɗanda suke tsoronsa; ");
INSERT INTO hausa_vpl VALUES ("PS103_14","020_103_14","PSA","103","14","14","gama ya san yadda aka yi mu, ya tuna cewa mu ƙura ne. ");
INSERT INTO hausa_vpl VALUES ("PS103_15","020_103_15","PSA","103","15","15","Game da mutum dai, kwanakinsa suna kamar ciyawa da suke haɓaka kamar fure a gona; ");
INSERT INTO hausa_vpl VALUES ("PS103_16","020_103_16","PSA","103","16","16","iska kan hura a kansa sai ya ɓace ba a kuwa sāke tuna da inda dā yake. ");
INSERT INTO hausa_vpl VALUES ("PS103_17","020_103_17","PSA","103","17","17","Amma daga madawwami zuwa madawwami ƙaunar Ubangiji tana tare da waɗanda suke tsoronsa, adalcinsa kuma tare da ’ya’yansu, ");
INSERT INTO hausa_vpl VALUES ("PS103_18","020_103_18","PSA","103","18","18","tare da waɗanda suke kiyaye alkawarinsa suna kuma tuna su yi biyayya da farillansa. ");
INSERT INTO hausa_vpl VALUES ("PS103_19","020_103_19","PSA","103","19","19","Ubangiji ya kafa kursiyinsa a sama, masarautarsa kuwa na mulki a bisa duka. ");
INSERT INTO hausa_vpl VALUES ("PS103_20","020_103_20","PSA","103","20","20","Yabi Ubangiji, ku mala’ikunsa, ku jarumawa masu yi masa aiki, waɗanda suke yin biyayya da maganarsa. ");
INSERT INTO hausa_vpl VALUES ("PS103_21","020_103_21","PSA","103","21","21","Yabi Ubangiji, dukanku rundunarsa ta sama, ku bayinsa waɗanda kuke aikata nufinsa. ");
INSERT INTO hausa_vpl VALUES ("PS103_22","020_103_22","PSA","103","22","22","Yabi Ubangiji, dukanku ayyukansa ko’ina a mulkinsa. Yabi Ubangiji, ya raina. ");
INSERT INTO hausa_vpl VALUES ("PS104_1","020_104_1","PSA","104","1","1","Yabi Ubangiji, ya raina. Ya Ubangiji Allahna, kana da girma ƙwarai; kana saye da daraja da ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("PS104_2","020_104_2","PSA","104","2","2","Ubangiji ya naɗe kansa da haske kamar riga ya shimfiɗa sammai kamar tenti ");
INSERT INTO hausa_vpl VALUES ("PS104_3","020_104_3","PSA","104","3","3","ya kafa ginshiƙan ɗakin samansa a kan ruwaye. Ya maido da gizagizai suka zama keken yaƙinsa yana hawa a kan fikafikan iska. ");
INSERT INTO hausa_vpl VALUES ("PS104_4","020_104_4","PSA","104","4","4","Ya mai da iska suka zama ’yan saƙonsa harsunan wuta kuma bayinsa. ");
INSERT INTO hausa_vpl VALUES ("PS104_5","020_104_5","PSA","104","5","5","Ya kafa duniya a kan tussanta; ba za a iya matsar da ita ba. ");
INSERT INTO hausa_vpl VALUES ("PS104_6","020_104_6","PSA","104","6","6","Ka rufe ta da zurfi kamar da riga ruwaye sun tsaya a bisa duwatsu. ");
INSERT INTO hausa_vpl VALUES ("PS104_7","020_104_7","PSA","104","7","7","Amma a tsawatawarka ruwaye suka gudu da jin ƙarar tsawanka suka ruga da gudu; ");
INSERT INTO hausa_vpl VALUES ("PS104_8","020_104_8","PSA","104","8","8","suka gudu a bisa duwatsu, suka gangara zuwa cikin kwaruruka, zuwa wurin da ka shirya musu. ");
INSERT INTO hausa_vpl VALUES ("PS104_9","020_104_9","PSA","104","9","9","Ka kafa iyakar da ba a iya tsallakawa; ba za su ƙara rufe duniya ba. ");
INSERT INTO hausa_vpl VALUES ("PS104_10","020_104_10","PSA","104","10","10","Ya sa maɓulɓulai suka zuba ruwa cikin kwaruruka; yana gudu tsakanin duwatsu. ");
INSERT INTO hausa_vpl VALUES ("PS104_11","020_104_11","PSA","104","11","11","Suna ba da ruwa ga dukan namun jeji; jakunan jeji suna kashe ƙishirwansu. ");
INSERT INTO hausa_vpl VALUES ("PS104_12","020_104_12","PSA","104","12","12","Tsuntsaye sarari suna sheƙunansu kusa da ruwan; suna rera cikin rassa. ");
INSERT INTO hausa_vpl VALUES ("PS104_13","020_104_13","PSA","104","13","13","Yana wa duwatsu banruwa daga ɗakinsa na sama; ƙasa tana ƙoshiya da amfanin aikinsa. ");
INSERT INTO hausa_vpl VALUES ("PS104_14","020_104_14","PSA","104","14","14","Yana sa ciyawa tă yi girma saboda shanu, tsire-tsire domin mutum ya nome, suna fid da abinci daga ƙasa, ");
INSERT INTO hausa_vpl VALUES ("PS104_15","020_104_15","PSA","104","15","15","ruwan inabi yakan sa zuciyar mutum tă yi murna, mai kuwa yakan sa fuska tă yi haske, abinci kuma da yake riƙe zuciyarsa. ");
INSERT INTO hausa_vpl VALUES ("PS104_16","020_104_16","PSA","104","16","16","Ana yi wa itatuwan Ubangiji banruwa sosai, al’ul na Lebanon da ya shuka. ");
INSERT INTO hausa_vpl VALUES ("PS104_17","020_104_17","PSA","104","17","17","A can tsuntsaye suke sheƙunnansu; shamuwa tana da gidanta a itatuwan fir. ");
INSERT INTO hausa_vpl VALUES ("PS104_18","020_104_18","PSA","104","18","18","Manyan duwatsu na awakin jeji ne; tsagaggun duwatsun mafaka ne ga rema. ");
INSERT INTO hausa_vpl VALUES ("PS104_19","020_104_19","PSA","104","19","19","Wata ne ke ƙididdigar lokuta, rana kuma ta san sa’ad da za tă fāɗi. ");
INSERT INTO hausa_vpl VALUES ("PS104_20","020_104_20","PSA","104","20","20","Ka yi duhu, sai ya zama dare, sai dukan namun jeji a kurmi suka fito a maƙe. ");
INSERT INTO hausa_vpl VALUES ("PS104_21","020_104_21","PSA","104","21","21","Zakoki sun yi ruri sa’ad da suke farauta suna kuma neman abincinsu daga Allah. ");
INSERT INTO hausa_vpl VALUES ("PS104_22","020_104_22","PSA","104","22","22","Rana ta fito, sai suka koma shiru; suka koma suka kwanta a kogwanninsu. ");
INSERT INTO hausa_vpl VALUES ("PS104_23","020_104_23","PSA","104","23","23","Mutum yakan tafi aikinsa, zuwa wurin aikinsa har yamma. ");
INSERT INTO hausa_vpl VALUES ("PS104_24","020_104_24","PSA","104","24","24","Ina misalin yawan aikinka, ya Ubangiji! Cikin hikima ka yi su duka; duniya ta cika da halittunka. ");
INSERT INTO hausa_vpl VALUES ("PS104_25","020_104_25","PSA","104","25","25","Akwai teku, babba da kuma fāɗi, cike da halittun da suka wuce ƙirga, abubuwa masu rai babba da ƙarami. ");
INSERT INTO hausa_vpl VALUES ("PS104_26","020_104_26","PSA","104","26","26","A can jiragen ruwa suna kai komo, kuma dodon ruwan da ka yi, yă yi wasa a can. ");
INSERT INTO hausa_vpl VALUES ("PS104_27","020_104_27","PSA","104","27","27","Waɗannan duka suna dogara gare ka don ka ba su abincinsu a daidai lokaci. ");
INSERT INTO hausa_vpl VALUES ("PS104_28","020_104_28","PSA","104","28","28","Sa’ad da ba su da shi, sai su tattara shi; sa’ad da ka buɗe hannunka, sukan ƙoshi da abubuwa masu kyau. ");
INSERT INTO hausa_vpl VALUES ("PS104_29","020_104_29","PSA","104","29","29","Sa’ad da ka ɓoye fuskarka, sai su razana; sa’ad da ka ɗauke numfashinsu, sai su mutu su kuma koma ga ƙura. ");
INSERT INTO hausa_vpl VALUES ("PS104_30","020_104_30","PSA","104","30","30","Sa’ad da ka aika da Ruhunka, sai su halittu, su kuma sabunta fuskar duniya. ");
INSERT INTO hausa_vpl VALUES ("PS104_31","020_104_31","PSA","104","31","31","Bari ɗaukakar Ubangiji ta dawwama har abada; bari Ubangiji yă yi farin ciki cikin aikinsa, ");
INSERT INTO hausa_vpl VALUES ("PS104_32","020_104_32","PSA","104","32","32","shi wanda ya dubi duniya, sai ta razana, wanda ya taɓa duwatsu, sai suka yi hayaƙi. ");
INSERT INTO hausa_vpl VALUES ("PS104_33","020_104_33","PSA","104","33","33","Zan rera ga Ubangiji dukan raina; zan rera yabo ga Allahna muddin ina raye. ");
INSERT INTO hausa_vpl VALUES ("PS104_34","020_104_34","PSA","104","34","34","Bari tunanina yă gamshe shi, yayinda nake farin ciki a cikin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS104_35","020_104_35","PSA","104","35","35","Amma bari masu zunubi su ɓace daga duniya mugaye kuma kada a ƙara ganinsu. Yabi Ubangiji, ya raina. Yabi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS105_1","020_105_1","PSA","105","1","1","Ku yi godiya ga Ubangiji, ku kira bisa sunansa; ku sanar a cikin al’ummai abin da ya yi. ");
INSERT INTO hausa_vpl VALUES ("PS105_2","020_105_2","PSA","105","2","2","Ku rera gare shi, ku rera yabo gare shi; ku faɗa dukan abubuwan mamakin da ya aikata. ");
INSERT INTO hausa_vpl VALUES ("PS105_3","020_105_3","PSA","105","3","3","Ku ɗaukaka a cikin sunansa mai tsarki; bari zukatan waɗanda suke neman Ubangiji su yi farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS105_4","020_105_4","PSA","105","4","4","Ku sa rai ga Ubangiji da kuma ƙarfinsa; ku nemi fuskarsa kullum. ");
INSERT INTO hausa_vpl VALUES ("PS105_5","020_105_5","PSA","105","5","5","Ku tuna da abubuwan mamakin da ya yi, mu’ujizansa, da kuma hukunce-hukuncen da ya zartar, ");
INSERT INTO hausa_vpl VALUES ("PS105_6","020_105_6","PSA","105","6","6","Ya ku zuriyar Ibrahim bawansa, Ya ku ’ya’yan Yaƙub, zaɓaɓɓensa. ");
INSERT INTO hausa_vpl VALUES ("PS105_7","020_105_7","PSA","105","7","7","Shi ne Ubangiji Allahnmu; kuma hukunce-hukuncensa suna a cikin dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS105_8","020_105_8","PSA","105","8","8","Yana tuna da alkawarinsa har abada, maganar da ya umarta, har tsararraki dubu, ");
INSERT INTO hausa_vpl VALUES ("PS105_9","020_105_9","PSA","105","9","9","alkawarin da ya yi da Ibrahim, rantsuwar da ya yi wa Ishaku. ");
INSERT INTO hausa_vpl VALUES ("PS105_10","020_105_10","PSA","105","10","10","Ya tabbatar da shi ga Yaƙub a matsayin ƙa’ida, Isra’ila a matsayin madawwamin alkawari, ");
INSERT INTO hausa_vpl VALUES ("PS105_11","020_105_11","PSA","105","11","11","“Gare ka zan ba da ƙasar Kan’ana a matsayin rabo za ka yi gādo.” ");
INSERT INTO hausa_vpl VALUES ("PS105_12","020_105_12","PSA","105","12","12","Sa’ad da suke kima kawai, kima sosai, da kuma baƙi a cikinta, ");
INSERT INTO hausa_vpl VALUES ("PS105_13","020_105_13","PSA","105","13","13","suka yi ta yawo daga al’umma zuwa al’umma, daga masarauta zuwa wata. ");
INSERT INTO hausa_vpl VALUES ("PS105_14","020_105_14","PSA","105","14","14","Bai bar kowa yă danne su ba; saboda su, ya tsawata wa sarakuna, ");
INSERT INTO hausa_vpl VALUES ("PS105_15","020_105_15","PSA","105","15","15","“Kada ku taɓa shafaffena; kada ku yi wa annabawa lahani.” ");
INSERT INTO hausa_vpl VALUES ("PS105_16","020_105_16","PSA","105","16","16","Ya sauko da yunwa a kan ƙasa ya kuma lalace dukan tanadinsu na abinci; ");
INSERT INTO hausa_vpl VALUES ("PS105_17","020_105_17","PSA","105","17","17","ya kuma aiki mutum a gabansu, Yusuf, da aka sayar a matsayin bawa. ");
INSERT INTO hausa_vpl VALUES ("PS105_18","020_105_18","PSA","105","18","18","Suka raunana ƙafafunsa da sarƙa aka sa wuyansa cikin ƙarafa, ");
INSERT INTO hausa_vpl VALUES ("PS105_19","020_105_19","PSA","105","19","19","sai abin da ya rigafaɗi ya cika sai da maganar Ubangiji ta tabbatar da shi mai gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PS105_20","020_105_20","PSA","105","20","20","Sarki ya aika aka kuma sake shi, mai mulkin mutane ya ’yantar da shi. ");
INSERT INTO hausa_vpl VALUES ("PS105_21","020_105_21","PSA","105","21","21","Ya mai da shi shugaban gidansa, mai mulki a bisa dukan abin da ya mallaka, ");
INSERT INTO hausa_vpl VALUES ("PS105_22","020_105_22","PSA","105","22","22","don yă umarci sarakunansa yadda ya ga dama yă kuma koya wa dattawa hikima. ");
INSERT INTO hausa_vpl VALUES ("PS105_23","020_105_23","PSA","105","23","23","Sa’an nan Isra’ila ya shiga Masar; Yaƙub ya yi zama kamar baƙo a ƙasar Ham. ");
INSERT INTO hausa_vpl VALUES ("PS105_24","020_105_24","PSA","105","24","24","Ubangiji ya mai da mutanensa suka yi ta haihuwa; ya sa suka yi yawa suka fi ƙarfin maƙiyansu, ");
INSERT INTO hausa_vpl VALUES ("PS105_25","020_105_25","PSA","105","25","25","waɗanda ya juya zukatansu su ƙi mutanensa don su haɗa baki a kan bayinsa. ");
INSERT INTO hausa_vpl VALUES ("PS105_26","020_105_26","PSA","105","26","26","Ya aiki Musa bawansa, da Haruna, wanda ya zaɓa. ");
INSERT INTO hausa_vpl VALUES ("PS105_27","020_105_27","PSA","105","27","27","Suka yi mu’ujizansa a cikinsu, abubuwan mamakinsa a cikin ƙasar Ham. ");
INSERT INTO hausa_vpl VALUES ("PS105_28","020_105_28","PSA","105","28","28","Ya aiko da duhu ya kuma sa ƙasar tă yi duhu, ba domin sun yi tawaye a kan maganarsa ba? ");
INSERT INTO hausa_vpl VALUES ("PS105_29","020_105_29","PSA","105","29","29","Ya mai da ruwaye suka zama jini, ya sa kifayensu suka mutu. ");
INSERT INTO hausa_vpl VALUES ("PS105_30","020_105_30","PSA","105","30","30","Ƙasarsu ta yi ta fid da kwaɗi, waɗanda suka haura cikin ɗakunan kwana na masu mulkinsu. ");
INSERT INTO hausa_vpl VALUES ("PS105_31","020_105_31","PSA","105","31","31","Ya yi magana, sai tarin ƙudaje suka fito, cinnaku kuma ko’ina a ƙasar. ");
INSERT INTO hausa_vpl VALUES ("PS105_32","020_105_32","PSA","105","32","32","Ya mai da ruwan samansu ya zama ƙanƙara, da walƙiya ko’ina a ƙasarsu; ");
INSERT INTO hausa_vpl VALUES ("PS105_33","020_105_33","PSA","105","33","33","ya lalace inabinsu da itatuwan ɓaurensu ya ragargaza itatuwan ƙasarsu. ");
INSERT INTO hausa_vpl VALUES ("PS105_34","020_105_34","PSA","105","34","34","Ya yi magana, sai fāri ɗango suka fito, fāran da ba su ƙidayuwa; ");
INSERT INTO hausa_vpl VALUES ("PS105_35","020_105_35","PSA","105","35","35","suka cinye kowane abu mai ruwan kore a cikin ƙasarsu, suka cinye amfanin gonarsu ");
INSERT INTO hausa_vpl VALUES ("PS105_36","020_105_36","PSA","105","36","36","Sa’an nan ya karkashe dukan ’yan fari a cikin ƙasarsu, nunan fari na dukan mazantakarsu. ");
INSERT INTO hausa_vpl VALUES ("PS105_37","020_105_37","PSA","105","37","37","Ya fitar da Isra’ila, ɗauke da azurfa da zinariya, kuma daga cikin kabilansu babu wani da ya kāsa. ");
INSERT INTO hausa_vpl VALUES ("PS105_38","020_105_38","PSA","105","38","38","Masar ta yi murna sa’ad da suka tafi, saboda tsoron Isra’ila ya fāɗo musu. ");
INSERT INTO hausa_vpl VALUES ("PS105_39","020_105_39","PSA","105","39","39","Ya shimfiɗa girgije kamar mayafi, da kuma wuta don ta ba su haske da dare. ");
INSERT INTO hausa_vpl VALUES ("PS105_40","020_105_40","PSA","105","40","40","Suka roƙa, ya kuwa ba su makware ya kuma ƙosar da su da abinci daga sama. ");
INSERT INTO hausa_vpl VALUES ("PS105_41","020_105_41","PSA","105","41","41","Ya buɗe dutse, sai ruwa ya ɓulɓulo, kamar kogi ya gudu zuwa cikin hamada. ");
INSERT INTO hausa_vpl VALUES ("PS105_42","020_105_42","PSA","105","42","42","Ya tuna da alkawarinsa mai tsarki da ya ba wa bawansa Ibrahim. ");
INSERT INTO hausa_vpl VALUES ("PS105_43","020_105_43","PSA","105","43","43","Ya fitar da mutanensa da farin ciki, zaɓaɓɓunsa da sowa ta farin ciki; ");
INSERT INTO hausa_vpl VALUES ("PS105_44","020_105_44","PSA","105","44","44","ya ba su ƙasashen al’ummai, suka kuma sami gādon abin da waɗansu sun sha wahala a kai, ");
INSERT INTO hausa_vpl VALUES ("PS105_45","020_105_45","PSA","105","45","45","don su kiyaye farillansa su kuma kiyaye dokokinsa. Yabo ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS106_1","020_106_1","PSA","106","1","1","Yabi Ubangiji. Yi godiya ga Ubangiji, gama nagari ne shi; ƙaunarsa madawwamiya ce har abada. ");
INSERT INTO hausa_vpl VALUES ("PS106_2","020_106_2","PSA","106","2","2","Wane ne zai furta manyan ayyukan Ubangiji ko yă furta cikakken yabonsa? ");
INSERT INTO hausa_vpl VALUES ("PS106_3","020_106_3","PSA","106","3","3","Masu albarka ne waɗanda suke yin adalci, waɗanda kullum suke yin abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("PS106_4","020_106_4","PSA","106","4","4","Ka tuna da ni, ya Ubangiji, sa’ad da ka nuna alheri ga mutanenka, ka zo ka taimake ni sa’ad da ka cece su, ");
INSERT INTO hausa_vpl VALUES ("PS106_5","020_106_5","PSA","106","5","5","don in ji daɗin nasarar zaɓaɓɓunka, don in sami rabo cikin farin cikin al’ummarka in kuma shiga gādonka cikin yin yabo. ");
INSERT INTO hausa_vpl VALUES ("PS106_6","020_106_6","PSA","106","6","6","Mun yi zunubi, kamar yadda kakanninmu suka yi; mun yi ba daidai ba muka kuma aikata mugunta. ");
INSERT INTO hausa_vpl VALUES ("PS106_7","020_106_7","PSA","106","7","7","Sa’ad da kakanninmu suke a Masar, ba su damu da mu’ujizanka ba; ba su tuna yawan alheranka ba, suka kuma yi tayarwa a teku, Jan Teku. ");
INSERT INTO hausa_vpl VALUES ("PS106_8","020_106_8","PSA","106","8","8","Duk da haka ya cece su saboda sunansa, don yă sanar da ikonsa mai girma. ");
INSERT INTO hausa_vpl VALUES ("PS106_9","020_106_9","PSA","106","9","9","Ya tsawata wa Jan Teku, ya kuwa bushe; ya bi da su ta cikin zurfafa sai ka ce a hamada. ");
INSERT INTO hausa_vpl VALUES ("PS106_10","020_106_10","PSA","106","10","10","Ya cece su daga hannun maƙiyi; daga hannun abokin gāba ya fanshe su. ");
INSERT INTO hausa_vpl VALUES ("PS106_11","020_106_11","PSA","106","11","11","Ruwaye suka rufe abokan gābansu; babu ko ɗaya da ya tsira. ");
INSERT INTO hausa_vpl VALUES ("PS106_12","020_106_12","PSA","106","12","12","Sa’an nan suka gaskata alkawarinsa suka kuma rera yabonsa. ");
INSERT INTO hausa_vpl VALUES ("PS106_13","020_106_13","PSA","106","13","13","Amma nan da nan suka manta abin da ya yi ba su kuwa jira shawararsa ba. ");
INSERT INTO hausa_vpl VALUES ("PS106_14","020_106_14","PSA","106","14","14","A cikin hamada suka bar sha’awarsu ta mamaye su a ƙasar da babu kome suka gwada Allah. ");
INSERT INTO hausa_vpl VALUES ("PS106_15","020_106_15","PSA","106","15","15","Sai ya ba su abin da suka roƙa, amma ya aika musu da muguwar cuta. ");
INSERT INTO hausa_vpl VALUES ("PS106_16","020_106_16","PSA","106","16","16","A sansani suka ji kishin Musa da kuma Haruna, wanda Ubangiji ya keɓe. ");
INSERT INTO hausa_vpl VALUES ("PS106_17","020_106_17","PSA","106","17","17","Ƙasa ta buɗe ta haɗiye Datan ta binne iyalin Abiram. ");
INSERT INTO hausa_vpl VALUES ("PS106_18","020_106_18","PSA","106","18","18","Wuta ta ƙuno a cikin mabiyansu; harshen wuta ya cinye mugaye. ");
INSERT INTO hausa_vpl VALUES ("PS106_19","020_106_19","PSA","106","19","19","A Horeb suka yi ɗan maraƙi suka yi wa gunkin zubi daga ƙarfe sujada. ");
INSERT INTO hausa_vpl VALUES ("PS106_20","020_106_20","PSA","106","20","20","Suka sauke Ɗaukakarsu saboda siffar bijimi, wanda yake cin ciyawa. ");
INSERT INTO hausa_vpl VALUES ("PS106_21","020_106_21","PSA","106","21","21","Suka manta da Allahn da ya cece su, wanda ya aikata manyan abubuwa a Masar, ");
INSERT INTO hausa_vpl VALUES ("PS106_22","020_106_22","PSA","106","22","22","mu’ujizai a ƙasar Ham ayyukan banrazana a Jan Teku. ");
INSERT INTO hausa_vpl VALUES ("PS106_23","020_106_23","PSA","106","23","23","Don haka ya ce zai hallaka su, amma Musa, zaɓaɓɓensa, ya yi godo a gabansa don yă kau da hasalarsa daga hallaka su. ");
INSERT INTO hausa_vpl VALUES ("PS106_24","020_106_24","PSA","106","24","24","Sai suka rena ƙasa mai ni’ima; ba su gaskata alkawarinsa ba. ");
INSERT INTO hausa_vpl VALUES ("PS106_25","020_106_25","PSA","106","25","25","Suka yi gunaguni a tentunansu ba su kuwa yi biyayya da Ubangiji ba. ");
INSERT INTO hausa_vpl VALUES ("PS106_26","020_106_26","PSA","106","26","26","Saboda haka ya rantse musu ya kuma ɗaga hannu cewa zai sa su mutu a cikin hamada, ");
INSERT INTO hausa_vpl VALUES ("PS106_27","020_106_27","PSA","106","27","27","ya sa zuriyarsu su mutu a cikin al’ummai ya kuma watsar da su cikin dukan ƙasashe. ");
INSERT INTO hausa_vpl VALUES ("PS106_28","020_106_28","PSA","106","28","28","Suka haɗa kai da Ba’al-Feyor suka kuma ci hadayun da aka miƙa wa allolin da ba su da rai; ");
INSERT INTO hausa_vpl VALUES ("PS106_29","020_106_29","PSA","106","29","29","suka tsokane Ubangiji ya yi fushi ta wurin mugayen ayyukansu, sai annoba ta ɓarke a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("PS106_30","020_106_30","PSA","106","30","30","Amma Finehas ya miƙe tsaye ya ɗauki mataki, sai annobar ta daina. ");
INSERT INTO hausa_vpl VALUES ("PS106_31","020_106_31","PSA","106","31","31","An ayana masa wannan a matsayin adalci har zamanai marar matuƙa masu zuwa. ");
INSERT INTO hausa_vpl VALUES ("PS106_32","020_106_32","PSA","106","32","32","A ruwan Meriba suka ba Ubangiji fushi, sai wahala ta zo wa Musa saboda su; ");
INSERT INTO hausa_vpl VALUES ("PS106_33","020_106_33","PSA","106","33","33","saboda sun yi tayarwa a kan Ruhun Allah, har mugayen kalmomi suka fito daga leɓunan Musa. ");
INSERT INTO hausa_vpl VALUES ("PS106_34","020_106_34","PSA","106","34","34","Ba su hallakar da mutanen yadda Ubangiji ya umarce su ba, ");
INSERT INTO hausa_vpl VALUES ("PS106_35","020_106_35","PSA","106","35","35","amma suka yi cuɗanya da al’ummai suka ɗauki al’adunsu. ");
INSERT INTO hausa_vpl VALUES ("PS106_36","020_106_36","PSA","106","36","36","Suka yi wa gumakansu sujada, waɗanda suka zama tarko gare su. ");
INSERT INTO hausa_vpl VALUES ("PS106_37","020_106_37","PSA","106","37","37","Suka miƙa ’ya’yansu maza hadaya ’yan matansu kuma ga aljanu. ");
INSERT INTO hausa_vpl VALUES ("PS106_38","020_106_38","PSA","106","38","38","Suka zub da jini marar laifi, jinin ’ya’yansu maza da mata, waɗanda suka miƙa hadaya ga gumakan Kan’ana, ƙasar kuwa ta ƙazantu ta wurin jininsu. ");
INSERT INTO hausa_vpl VALUES ("PS106_39","020_106_39","PSA","106","39","39","Suka ƙazantar da kansu ta wurin abin da suka yi; ta wurin ayyukansu suka yi karuwanci. ");
INSERT INTO hausa_vpl VALUES ("PS106_40","020_106_40","PSA","106","40","40","Saboda haka Ubangiji ya yi fushi da mutanensa ya ji ƙyamar gādonsa. ");
INSERT INTO hausa_vpl VALUES ("PS106_41","020_106_41","PSA","106","41","41","Ya miƙa su ga al’ummai, maƙiyansu kuma suka yi mulki a kansu. ");
INSERT INTO hausa_vpl VALUES ("PS106_42","020_106_42","PSA","106","42","42","Abokan gābansu suka danne su suka sa su a ƙarƙashin ikonsu. ");
INSERT INTO hausa_vpl VALUES ("PS106_43","020_106_43","PSA","106","43","43","Sau da yawa ya cece su, amma sun nace su yi tawaye suka kuma lalace cikin zunubinsu. ");
INSERT INTO hausa_vpl VALUES ("PS106_44","020_106_44","PSA","106","44","44","Amma ya lura da wahalarsu sa’ad da ya ji kukansu; ");
INSERT INTO hausa_vpl VALUES ("PS106_45","020_106_45","PSA","106","45","45","saboda su ya tuna da alkawarinsa kuma daga yawan ƙaunarsa ya ji tausayi. ");
INSERT INTO hausa_vpl VALUES ("PS106_46","020_106_46","PSA","106","46","46","Ya sa aka ji tausayinsu a wurin dukan waɗanda suka kame su. ");
INSERT INTO hausa_vpl VALUES ("PS106_47","020_106_47","PSA","106","47","47","Ka cece mu, Ubangiji Allahnmu, ka kuma tattara mu daga al’ummai, don mu yi wa sunanka mai tsarki godiya mu kuma ɗaukaka cikin yabonka. ");
INSERT INTO hausa_vpl VALUES ("PS106_48","020_106_48","PSA","106","48","48","Yabo ga Ubangiji, Allah na Isra’ila, daga madawwami zuwa madawwami. Bari dukan mutane su ce, “Amin!” Yabo ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS107_1","020_107_1","PSA","107","1","1","Ku yi godiya ga Ubangiji, gama nagari ne shi; ƙaunarsa madawwamiya ce har abada. ");
INSERT INTO hausa_vpl VALUES ("PS107_2","020_107_2","PSA","107","2","2","Bari fansassu na Ubangiji su faɗa wannan, su da aka fansa daga hannun maƙiyi, ");
INSERT INTO hausa_vpl VALUES ("PS107_3","020_107_3","PSA","107","3","3","su da ya tattara daga ƙasashe, daga gabas da yamma, daga arewa da kudu. ");
INSERT INTO hausa_vpl VALUES ("PS107_4","020_107_4","PSA","107","4","4","Waɗansu sun yi ta yawo a jejin hamada, ba su sami hanya zuwa birnin da za su zauna ba. ");
INSERT INTO hausa_vpl VALUES ("PS107_5","020_107_5","PSA","107","5","5","Sun ji yunwa da ƙishirwa, suka kuma fid da zuciya. ");
INSERT INTO hausa_vpl VALUES ("PS107_6","020_107_6","PSA","107","6","6","Sa’an nan suka yi kuka ga Ubangiji cikin wahalarsu, ya kuma cece su daga damuwarsu. ");
INSERT INTO hausa_vpl VALUES ("PS107_7","020_107_7","PSA","107","7","7","Ya bishe su ta miƙaƙƙiyar hanya zuwa birnin da za su zauna. ");
INSERT INTO hausa_vpl VALUES ("PS107_8","020_107_8","PSA","107","8","8","Bari su yi godiya ga Ubangiji saboda ƙaunarsa marar ƙarewa da kuma ayyukansa masu banmamaki saboda mutane, ");
INSERT INTO hausa_vpl VALUES ("PS107_9","020_107_9","PSA","107","9","9","gama yana shayar da masu ƙishirwa yana kuma ƙosar da mayunwata da abubuwa masu kyau. ");
INSERT INTO hausa_vpl VALUES ("PS107_10","020_107_10","PSA","107","10","10","Waɗansu sun zauna a cikin duhu da kuma zurfin ɓacin rai, ’yan kurkuku suna wahala cikin sarƙoƙin ƙarfe, ");
INSERT INTO hausa_vpl VALUES ("PS107_11","020_107_11","PSA","107","11","11","gama sun yi tayarwa a kan maganar Allah suka ƙi shawarar Mafi Ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("PS107_12","020_107_12","PSA","107","12","12","Saboda haka ya ba da su ga aiki mai wuya; suka yi tuntuɓe, kuma ba mai taimako. ");
INSERT INTO hausa_vpl VALUES ("PS107_13","020_107_13","PSA","107","13","13","Sa’an nan suka yi kuka ga Ubangiji cikin wahalarsu, ya kuwa cece su daga damuwarsu. ");
INSERT INTO hausa_vpl VALUES ("PS107_14","020_107_14","PSA","107","14","14","Ya fitar da su daga duhu da zurfin ɓaci rai ya tsintsinke sarƙoƙinsu. ");
INSERT INTO hausa_vpl VALUES ("PS107_15","020_107_15","PSA","107","15","15","Bari su yi godiya ga Ubangiji saboda ƙaunarsa marar ƙarewa da kuma ayyukansa masu banmamaki saboda mutane, ");
INSERT INTO hausa_vpl VALUES ("PS107_16","020_107_16","PSA","107","16","16","gama ya farfashe ƙofofin tagulla ya kuma ragargaza ƙyamaren ƙarfe. ");
INSERT INTO hausa_vpl VALUES ("PS107_17","020_107_17","PSA","107","17","17","Waɗansu suka zama wawaye ta wurin hanyoyinsu na tayarwa suka kuwa sha wahala saboda laifofinsu. ");
INSERT INTO hausa_vpl VALUES ("PS107_18","020_107_18","PSA","107","18","18","Ba su so su ga abinci ba suka kuwa kai bakin mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PS107_19","020_107_19","PSA","107","19","19","Sa’an nan suka yi kuka ga Ubangiji cikin wahalarsu, ya kuwa cece su daga damuwarsu. ");
INSERT INTO hausa_vpl VALUES ("PS107_20","020_107_20","PSA","107","20","20","Ya ba da umarninsa ya kuma warkar da su ya kuɓutar da su daga kabari. ");
INSERT INTO hausa_vpl VALUES ("PS107_21","020_107_21","PSA","107","21","21","Bari su yi godiya ga Ubangiji saboda ƙaunarsa marar ƙarewa da kuma ayyukansa masu banmamaki saboda mutane. ");
INSERT INTO hausa_vpl VALUES ("PS107_22","020_107_22","PSA","107","22","22","Bari su miƙa hadaya ta godiya su kuma ba da labarin ayyukansa da waƙoƙin farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS107_23","020_107_23","PSA","107","23","23","Waɗansu suka yi tafiya a teku cikin jiragen ruwa; su ’yan kasuwa ne a manyan ruwaye. ");
INSERT INTO hausa_vpl VALUES ("PS107_24","020_107_24","PSA","107","24","24","Sun ga ayyukan Ubangiji, ayyukansa masu banmamaki a cikin zurfin teku. ");
INSERT INTO hausa_vpl VALUES ("PS107_25","020_107_25","PSA","107","25","25","Gama ya yi magana ya kuma sa iska mai ƙarfi ta tashi ya ɗaga raƙuman ruwa sama. ");
INSERT INTO hausa_vpl VALUES ("PS107_26","020_107_26","PSA","107","26","26","Suka hau zuwa sammai suka kuma tsinduma cikin zurfafa; a cikin azabarsu sai ƙarfin halinsu ya karai. ");
INSERT INTO hausa_vpl VALUES ("PS107_27","020_107_27","PSA","107","27","27","Suka yi tangaɗi suna tuntuɓe kamar bugaggu; suka kuma kai ga ƙarshen dabararsu. ");
INSERT INTO hausa_vpl VALUES ("PS107_28","020_107_28","PSA","107","28","28","Sai suka yi kuka ga Ubangiji cikin wahalarsu, ya kuwa fitar da su daga damuwarsu. ");
INSERT INTO hausa_vpl VALUES ("PS107_29","020_107_29","PSA","107","29","29","Ya kwantar da hadiri suka yi tsit; raƙuman ruwan teku suka yi shiru. ");
INSERT INTO hausa_vpl VALUES ("PS107_30","020_107_30","PSA","107","30","30","Suka yi murna sa’ad da wuri ya kwanta, ya kuma bishe su zuwa inda suka so su kai. ");
INSERT INTO hausa_vpl VALUES ("PS107_31","020_107_31","PSA","107","31","31","Bari su yi godiya ga Ubangiji saboda ƙaunarsa marar ƙarewa da kuma ayyukansa masu banmamaki saboda mutane. ");
INSERT INTO hausa_vpl VALUES ("PS107_32","020_107_32","PSA","107","32","32","Bari su ɗaukaka shi cikin taron mutane su kuma yabe shi cikin taron dattawa. ");
INSERT INTO hausa_vpl VALUES ("PS107_33","020_107_33","PSA","107","33","33","Ya mai da koguna suka zama hamada, maɓulɓulai masu gudu suka zama ƙasa mai ƙishirwa, ");
INSERT INTO hausa_vpl VALUES ("PS107_34","020_107_34","PSA","107","34","34","ƙasa mai amfani kuma suka zama gishiri marar amfani, saboda muguntar waɗanda suka zauna a can. ");
INSERT INTO hausa_vpl VALUES ("PS107_35","020_107_35","PSA","107","35","35","Ya mai da hamada ya zama tafkunan ruwa busasshiyar ƙasa kuma zuwa maɓulɓulai masu gudu; ");
INSERT INTO hausa_vpl VALUES ("PS107_36","020_107_36","PSA","107","36","36","a can ya kai mayunwata su yi zama, ya kuma samo birnin da za su zauna. ");
INSERT INTO hausa_vpl VALUES ("PS107_37","020_107_37","PSA","107","37","37","Suka yi shuka a gonaki suka dasa inabi suka kuma girbe amfani gona; ");
INSERT INTO hausa_vpl VALUES ("PS107_38","020_107_38","PSA","107","38","38","ya albarkace su, yawansu kuma ya ƙaru, bai kuwa bar garkunansu suka ragu ba. ");
INSERT INTO hausa_vpl VALUES ("PS107_39","020_107_39","PSA","107","39","39","Sa’an nan yawansu ya ragu, aka kuma ƙasƙantar da su ta wurin danniya, bala’i da kuma baƙin ciki; ");
INSERT INTO hausa_vpl VALUES ("PS107_40","020_107_40","PSA","107","40","40","shi da yake kawo reni a kan manyan mutane ya sa suka yi ta yawo a cikin jejin da ba hanya. ");
INSERT INTO hausa_vpl VALUES ("PS107_41","020_107_41","PSA","107","41","41","Amma ya fid da mabukata daga wahalarsu ya kuma ƙara iyalansu da tumakinsu. ");
INSERT INTO hausa_vpl VALUES ("PS107_42","020_107_42","PSA","107","42","42","Masu yin gaskiya suka gani suka yi farin ciki amma dukan mugaye suka rufe bakunansu. ");
INSERT INTO hausa_vpl VALUES ("PS107_43","020_107_43","PSA","107","43","43","Duk mai hikima, bari yă ji waɗannan abubuwa yă kuma lura da ƙauna mai girma ta Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS108_1","020_108_1","PSA","108","1","1","Waƙa ce. Zabura ta Dawuda. Zuciyata tsayayyiya ce, ya Allah; zan rera in kuma yi kiɗi da dukan raina. ");
INSERT INTO hausa_vpl VALUES ("PS108_2","020_108_2","PSA","108","2","2","Ku farka, garaya da molo! Zan farkar da rana. ");
INSERT INTO hausa_vpl VALUES ("PS108_3","020_108_3","PSA","108","3","3","Zan yabe ka, ya Ubangiji, a cikin al’ummai; zan rera game da kai cikin mutane. ");
INSERT INTO hausa_vpl VALUES ("PS108_4","020_108_4","PSA","108","4","4","Gama ƙaunarka da girma take, bisa fiye da sammai; amincinka ya kai sarari. ");
INSERT INTO hausa_vpl VALUES ("PS108_5","020_108_5","PSA","108","5","5","A ɗaukaka ka, ya Allah, a bisa sammai, bari kuma ɗaukakarka ta kasance a bisa dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS108_6","020_108_6","PSA","108","6","6","Ka cece mu ka kuma taimake mu da hannunka na dama, domin waɗanda kake ƙauna su kuɓuta. ");
INSERT INTO hausa_vpl VALUES ("PS108_7","020_108_7","PSA","108","7","7","Allah ya yi magana daga wurinsa mai tsarki, “Ciki nasara zan raba Shekem in kuma auna Kwarin Sukkot. ");
INSERT INTO hausa_vpl VALUES ("PS108_8","020_108_8","PSA","108","8","8","Gileyad nawa ne, Manasse nawa ne; Efraim shi hulan kwanona, Yahuda ne sandana na sarauta. ");
INSERT INTO hausa_vpl VALUES ("PS108_9","020_108_9","PSA","108","9","9","Mowab shi ne kwanon wankina, a kan Edom zan jefa takalmina; a bisa Filistiya zan yi kirari cikin nasara.” ");
INSERT INTO hausa_vpl VALUES ("PS108_10","020_108_10","PSA","108","10","10","Wa zai kawo ni birni mai katanga? Wa zai jagorance ni zuwa Edom? ");
INSERT INTO hausa_vpl VALUES ("PS108_11","020_108_11","PSA","108","11","11","Ba kai ba ne, ya Allah, kai da ka ƙi mu ba ka kuwa fita tare da mayaƙanmu? ");
INSERT INTO hausa_vpl VALUES ("PS108_12","020_108_12","PSA","108","12","12","Ka ba mu taimako a kan abokin gāba, gama taimakon mutum banza ne. ");
INSERT INTO hausa_vpl VALUES ("PS108_13","020_108_13","PSA","108","13","13","Tare da Allah za mu yi nasara, zai kuma tattaka abokan gābanmu. ");
INSERT INTO hausa_vpl VALUES ("PS109_1","020_109_1","PSA","109","1","1","Don mai bi da kaɗe-kaɗe. Ta Dawuda. Zabura ce. Ya Allah, wanda nake yabo, kada ka yi shiru, ");
INSERT INTO hausa_vpl VALUES ("PS109_2","020_109_2","PSA","109","2","2","gama mugaye da masu ruɗu sun buɗe bakunansu a kaina; sun yi magana a kaina da harsunan ƙarya. ");
INSERT INTO hausa_vpl VALUES ("PS109_3","020_109_3","PSA","109","3","3","Da kalmomin ƙiyayya sun kewaye ni; sun tasar mini ba dalili. ");
INSERT INTO hausa_vpl VALUES ("PS109_4","020_109_4","PSA","109","4","4","A maimakon ƙauna sun sāka mini da zargi, amma ni mutum ne mai addu’a. ");
INSERT INTO hausa_vpl VALUES ("PS109_5","020_109_5","PSA","109","5","5","Sun sāka mini alheri da mugunta, ƙauna kuma da ƙiyayya. ");
INSERT INTO hausa_vpl VALUES ("PS109_6","020_109_6","PSA","109","6","6","Ka naɗa mugun mutum yă yi hamayya da shi; bari mai zargi yă tsaya a hannun damansa. ");
INSERT INTO hausa_vpl VALUES ("PS109_7","020_109_7","PSA","109","7","7","Sa’ad da aka yi masa shari’a, bari a same shi da laifi, bari kuma addu’o’insa su hukunta shi. ");
INSERT INTO hausa_vpl VALUES ("PS109_8","020_109_8","PSA","109","8","8","Bari kwanakinsa su zama kaɗan; bari wani yă ɗauki wurinsa na shugabanci. ");
INSERT INTO hausa_vpl VALUES ("PS109_9","020_109_9","PSA","109","9","9","Bari ’ya’yansa su zama marayu matarsa kuma gwauruwa. ");
INSERT INTO hausa_vpl VALUES ("PS109_10","020_109_10","PSA","109","10","10","Bari ’ya’yansa su zama masu yawo suna bara; bari a yi ta koransu daga gidajensu da suke kufai. ");
INSERT INTO hausa_vpl VALUES ("PS109_11","020_109_11","PSA","109","11","11","Bari mai binsa bashi yă ƙwace dukan abin da yake da shi; bari baƙi su washe amfanin aikinsa. ");
INSERT INTO hausa_vpl VALUES ("PS109_12","020_109_12","PSA","109","12","12","Bari kada kowa yă yi masa alheri ko yă ji tausayin marayunsa. ");
INSERT INTO hausa_vpl VALUES ("PS109_13","020_109_13","PSA","109","13","13","Bari duk zuriyarsa su mutu, a shafe sunayensu daga tsara mai zuwa. ");
INSERT INTO hausa_vpl VALUES ("PS109_14","020_109_14","PSA","109","14","14","Bari a tuna da laifin kakanninsa a gaban Ubangiji; bari kada a taɓa shafe zunubin mahaifiyarsa. ");
INSERT INTO hausa_vpl VALUES ("PS109_15","020_109_15","PSA","109","15","15","Bari zunubansu su kasance a gaban Ubangiji kullum, don yă sa a manta da su daga duniya. ");
INSERT INTO hausa_vpl VALUES ("PS109_16","020_109_16","PSA","109","16","16","Gama bai taɓa yin tunanin yin alheri ba, amma ya tsananta wa matalauta da mabukata da kuma masu fid da zuciya har suka mutu. ");
INSERT INTO hausa_vpl VALUES ("PS109_17","020_109_17","PSA","109","17","17","Yana jin daɗin la’antarwa, bari yă dawo a kansa; ba ya son sa albarka, bari kada kowa yă sa masa albarka. ");
INSERT INTO hausa_vpl VALUES ("PS109_18","020_109_18","PSA","109","18","18","Ya sa la’antarwa kamar rigarsa; ta shiga cikin jikinsa kamar ruwa, cikin ƙasusuwansa kamar mai. ");
INSERT INTO hausa_vpl VALUES ("PS109_19","020_109_19","PSA","109","19","19","Bari tă zama kamar mayafin da aka ɗaura kewaye da shi, kamar ɗamara da aka ɗaura kewaye da shi har abada. ");
INSERT INTO hausa_vpl VALUES ("PS109_20","020_109_20","PSA","109","20","20","Bari wannan yă zama sakayyar Ubangiji ga masu zargina, ga waɗanda suke mugayen maganganu a kaina. ");
INSERT INTO hausa_vpl VALUES ("PS109_21","020_109_21","PSA","109","21","21","Amma kai, ya Ubangiji Mai Iko Duka, ka yi da ni da kyau saboda sunanka; ta alherin ƙaunarka, ka cece ni. ");
INSERT INTO hausa_vpl VALUES ("PS109_22","020_109_22","PSA","109","22","22","Gama ni matalauci ne mai bukata kuma, zuciyata kuwa ta yi rauni a cikina. ");
INSERT INTO hausa_vpl VALUES ("PS109_23","020_109_23","PSA","109","23","23","Na ɓace kamar inuwar yamma; ana kakkaɓe ni kamar fāra. ");
INSERT INTO hausa_vpl VALUES ("PS109_24","020_109_24","PSA","109","24","24","Gwiwoyina suna mutuwa saboda azumi; jikina ya rame ba kuma ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("PS109_25","020_109_25","PSA","109","25","25","Na zama abin dariya ga masu zargina; sa’ad da suka gan ni, suka kaɗa kawunansu. ");
INSERT INTO hausa_vpl VALUES ("PS109_26","020_109_26","PSA","109","26","26","Ka taimake ni, ya Ubangiji Allahna; ka cece ni bisa ga ƙaunarka. ");
INSERT INTO hausa_vpl VALUES ("PS109_27","020_109_27","PSA","109","27","27","Bari su san cewa hannunka ne, cewa kai ne, ya Ubangiji, ka yi shi. ");
INSERT INTO hausa_vpl VALUES ("PS109_28","020_109_28","PSA","109","28","28","Za su iya la’anta, amma kai za ka sa albarka; sa’ad da suka tasar za su sha kunya, amma bawanka zai yi farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS109_29","020_109_29","PSA","109","29","29","Masu zargina za su sha kunya za a rufe su da kunya kamar mayafi. ");
INSERT INTO hausa_vpl VALUES ("PS109_30","020_109_30","PSA","109","30","30","Da bakina zan ɗaukaka Ubangiji sosai; cikin babban taro zan yabe shi. ");
INSERT INTO hausa_vpl VALUES ("PS109_31","020_109_31","PSA","109","31","31","Gama yana tsaya a hannun damar mai bukata, don yă cece ransa daga waɗanda suke hukunta shi. ");
INSERT INTO hausa_vpl VALUES ("PS110_1","020_110_1","PSA","110","1","1","Ta Dawuda. Zabura ce. Ubangiji ya ce wa Ubangijina, “Zauna a hannun damana, sai na sa abokan gābanka su zama matashin sawunka.” ");
INSERT INTO hausa_vpl VALUES ("PS110_2","020_110_2","PSA","110","2","2","Ubangiji zai fadada ikon sandan mulkinka daga Sihiyona za ka yi mulki a tsakiyar abokan gābanka. ");
INSERT INTO hausa_vpl VALUES ("PS110_3","020_110_3","PSA","110","3","3","Rundunarka za su so yin yaƙi a ranarka ta yaƙi. Saye cikin ɗaukaka mai tsarki, daga cikin ciki na safiya za ka karɓi raɓar ƙuruciyarka. ");
INSERT INTO hausa_vpl VALUES ("PS110_4","020_110_4","PSA","110","4","4","Ubangiji ya rantse ba zai kuma canja zuciyarsa ba, “Kai firist ne har abada, bisa ga tsarin Melkizedek.” ");
INSERT INTO hausa_vpl VALUES ("PS110_5","020_110_5","PSA","110","5","5","Ubangiji yana a hannun damanka; zai murƙushe sarakuna a ranar fushinsa. ");
INSERT INTO hausa_vpl VALUES ("PS110_6","020_110_6","PSA","110","6","6","Zai hukunta al’ummai, yana tarawa gawawwaki yana kuma murƙushe masu mulkin dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS110_7","020_110_7","PSA","110","7","7","Zai sha daga rafin da yake kusa da hanya; saboda haka zai ɗaga kansa sama. ");
INSERT INTO hausa_vpl VALUES ("PS111_1","020_111_1","PSA","111","1","1","Yabi Ubangiji. Zan ɗaukaka Ubangiji da dukan zuciyata a cikin majalisar masu aikata gaskiya da kuma a cikin taro. ");
INSERT INTO hausa_vpl VALUES ("PS111_2","020_111_2","PSA","111","2","2","Ayyukan Ubangiji da girma suke; dukan waɗanda suke farin ciki da su suna tunaninsu. ");
INSERT INTO hausa_vpl VALUES ("PS111_3","020_111_3","PSA","111","3","3","Ayyukansa masu ɗaukaka da kuma daraja ne, adalcinsa kuma zai dawwama har abada. ");
INSERT INTO hausa_vpl VALUES ("PS111_4","020_111_4","PSA","111","4","4","Ya sa a tuna da abubuwa masu banmamaki nasa; Ubangiji mai alheri ne mai tausayi kuma. ");
INSERT INTO hausa_vpl VALUES ("PS111_5","020_111_5","PSA","111","5","5","Yana ba da abinci ga waɗanda suke tsoronsa; yakan tuna da alkawarinsa har abada. ");
INSERT INTO hausa_vpl VALUES ("PS111_6","020_111_6","PSA","111","6","6","Ya nuna wa mutanensa ikon ayyukansa, yana ba su ƙasashen waɗansu al’ummai. ");
INSERT INTO hausa_vpl VALUES ("PS111_7","020_111_7","PSA","111","7","7","Ayyukan hannuwansa masu aminci ne da kuma gaskiya; dukan farillansa abin dogara ne. ");
INSERT INTO hausa_vpl VALUES ("PS111_8","020_111_8","PSA","111","8","8","Tsayayyu ne har abada abadin, ana yinsu cikin aminci da kuma gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PS111_9","020_111_9","PSA","111","9","9","Yana ba da ceto ga mutanensa; ya kafa alkawarinsa har abada, tsarki da banrazana ne sunansa. ");
INSERT INTO hausa_vpl VALUES ("PS111_10","020_111_10","PSA","111","10","10","Tsoron Ubangiji ne mafarin hikima; dukan waɗanda suke bin farillansa suna da ganewa mai kyau. Gare shi ne madawwamin yabo. ");
INSERT INTO hausa_vpl VALUES ("PS112_1","020_112_1","PSA","112","1","1","Yabi Ubangiji. Mai albarka ne mutumin da yake tsoron Ubangiji, wanda yakan sami farin ciki mai girma a umarnansa. ");
INSERT INTO hausa_vpl VALUES ("PS112_2","020_112_2","PSA","112","2","2","’Ya’yansa za su zama manya a ƙasar; tsaran masu aikata gaskiya za su sami albarka. ");
INSERT INTO hausa_vpl VALUES ("PS112_3","020_112_3","PSA","112","3","3","Wadata da arziki suna a cikin gidansa, adalcinsa zai dawwama har abada. ");
INSERT INTO hausa_vpl VALUES ("PS112_4","020_112_4","PSA","112","4","4","Ko a cikin duhu haske kan haskaka wa mai aikata gaskiya, mai alheri mai tausayi da kuma mai adalci. ");
INSERT INTO hausa_vpl VALUES ("PS112_5","020_112_5","PSA","112","5","5","Abu mai kyau zai zo masa shi da yake kyauta yake kuma ba da bashi hannu sake, shi da yake yin al’amuransa cikin gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PS112_6","020_112_6","PSA","112","6","6","Tabbatacce ba zai taɓa jijjigu ba; za a tuna da mai adalci har abada. ");
INSERT INTO hausa_vpl VALUES ("PS112_7","020_112_7","PSA","112","7","7","Ba zai ji tsoron labari marar daɗi ba; zuciyarsa tsayayyiya ce, tana dogara ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS112_8","020_112_8","PSA","112","8","8","Zuciyarsa tana da kāriya, ba zai ji tsoro ba; a ƙarshe zai zama mai nasara a kan maƙiyansa. ");
INSERT INTO hausa_vpl VALUES ("PS112_9","020_112_9","PSA","112","9","9","Ya rarraba kyautansa ga matalauta, adalcinsa zai dawwama har abada; za a ɗaga ƙahonsa sama da bangirma. ");
INSERT INTO hausa_vpl VALUES ("PS112_10","020_112_10","PSA","112","10","10","Mugun mutum zai gani yă kuma yi fushi, zai ciza haƙora yă kuma lalace; sha’awace-sha’awacen mugaye za su zo ga ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("PS113_1","020_113_1","PSA","113","1","1","Yabi Ubangiji. Ku yabe shi, ya ku bayin Ubangiji, ku yabi sunan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS113_2","020_113_2","PSA","113","2","2","Bari a yabi sunan Ubangiji, yanzu da har abada kuma. ");
INSERT INTO hausa_vpl VALUES ("PS113_3","020_113_3","PSA","113","3","3","Daga fitowar rana zuwa inda take fāɗuwa, a yabi sunan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS113_4","020_113_4","PSA","113","4","4","Ana ɗaukaka Ubangiji a bisa dukan al’ummai, ɗaukakarsa a bisa sammai ");
INSERT INTO hausa_vpl VALUES ("PS113_5","020_113_5","PSA","113","5","5","Wane ne yake kamar Ubangiji Allahnmu, Wannan mai zama a kursiyi can bisa, ");
INSERT INTO hausa_vpl VALUES ("PS113_6","020_113_6","PSA","113","6","6","wanda yake sunkuya yă dubi sammai da duniya? ");
INSERT INTO hausa_vpl VALUES ("PS113_7","020_113_7","PSA","113","7","7","Yakan tā da matalauta daga ƙura yakan ɗaga mabukata daga tarin toka; ");
INSERT INTO hausa_vpl VALUES ("PS113_8","020_113_8","PSA","113","8","8","ya zaunar da su tare da sarakuna, tare da sarakunan mutanensu. ");
INSERT INTO hausa_vpl VALUES ("PS113_9","020_113_9","PSA","113","9","9","Yakan zaunar da matar da ba haihuwa a gidanta ta zama kamar mahaifiyar ’ya’ya mai farin ciki. Yabi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS114_1","020_114_1","PSA","114","1","1","Sa’ad da Isra’ila ya fito daga Masar, gidan Yaƙub daga mutane masu baƙon harshe, ");
INSERT INTO hausa_vpl VALUES ("PS114_2","020_114_2","PSA","114","2","2","Yahuda ya zama wuri mai tsarki na Allah, Isra’ila mallakarsa. ");
INSERT INTO hausa_vpl VALUES ("PS114_3","020_114_3","PSA","114","3","3","Teku ya kalla ya kuma gudu, Urdun ya juye da baya; ");
INSERT INTO hausa_vpl VALUES ("PS114_4","020_114_4","PSA","114","4","4","duwatsu suka yi tsalle kamar raguna, tuddai kamar tumaki. ");
INSERT INTO hausa_vpl VALUES ("PS114_5","020_114_5","PSA","114","5","5","Me ya sa, ya teku, kika gudu, Ya Urdun, ka juya baya, ");
INSERT INTO hausa_vpl VALUES ("PS114_6","020_114_6","PSA","114","6","6","ku duwatsu, kuka yi tsalle kamar raguna, ku tuddai, kamar tumaki? ");
INSERT INTO hausa_vpl VALUES ("PS114_7","020_114_7","PSA","114","7","7","Ki yi rawar jiki, ya duniya, a gaban Ubangiji, a gaban Allah na Yaƙub, ");
INSERT INTO hausa_vpl VALUES ("PS114_8","020_114_8","PSA","114","8","8","wanda ya juye dutse ya zama tafki, dutse mai ƙarfi zuwa maɓulɓulan ruwa. ");
INSERT INTO hausa_vpl VALUES ("PS115_1","020_115_1","PSA","115","1","1","Ba gare mu ba, ya Ubangiji, ba gare mu ba amma ga sunanka yă sami ɗaukaka, saboda ƙaunarka da amincinka. ");
INSERT INTO hausa_vpl VALUES ("PS115_2","020_115_2","PSA","115","2","2","Me ya sa al’ummai suke cewa, “Ina Allahnsu?” ");
INSERT INTO hausa_vpl VALUES ("PS115_3","020_115_3","PSA","115","3","3","Allahnmu yana a sama; yana yin duk abin da ya ga dama. ");
INSERT INTO hausa_vpl VALUES ("PS115_4","020_115_4","PSA","115","4","4","Amma gumakansu azurfa da zinariya ne, da hannuwan mutane suka yi. ");
INSERT INTO hausa_vpl VALUES ("PS115_5","020_115_5","PSA","115","5","5","Suna da bakuna, amma ba sa magana, idanu, amma ba sa gani; ");
INSERT INTO hausa_vpl VALUES ("PS115_6","020_115_6","PSA","115","6","6","suna da kunnuwa, amma ba sa ji, hanci, amma ba sa jin ƙanshi ");
INSERT INTO hausa_vpl VALUES ("PS115_7","020_115_7","PSA","115","7","7","suna da hannuwa, amma ba sa iya taɓa kome, ƙafafu, amma ba sa iya tafiya; ba sa iya ce wani abu da maƙogwaronsu. ");
INSERT INTO hausa_vpl VALUES ("PS115_8","020_115_8","PSA","115","8","8","Masu yinsu za su zama kamar su, haka kuma zai kasance da duk wanda ya dogara da su. ");
INSERT INTO hausa_vpl VALUES ("PS115_9","020_115_9","PSA","115","9","9","Ya gidan Isra’ila, ku dogara ga Ubangiji, shi ne mai taimakonsu da garkuwarsu. ");
INSERT INTO hausa_vpl VALUES ("PS115_10","020_115_10","PSA","115","10","10","Ya gidan Haruna, ku dogara ga Ubangiji, shi ne mai taimakonsu da garkuwarsu. ");
INSERT INTO hausa_vpl VALUES ("PS115_11","020_115_11","PSA","115","11","11","Ku da kuke tsoronsa, ku dogara ga Ubangiji, shi ne mai taimakonsu da garkuwarsu. ");
INSERT INTO hausa_vpl VALUES ("PS115_12","020_115_12","PSA","115","12","12","Ubangiji yakan tuna da mu zai kuma albarkace mu. Zai albarkace gidan Isra’ila, zai albarkace gidan Haruna, ");
INSERT INTO hausa_vpl VALUES ("PS115_13","020_115_13","PSA","115","13","13","zai albarkace waɗanda suke tsoron Ubangiji, manya da ƙanana duka. ");
INSERT INTO hausa_vpl VALUES ("PS115_14","020_115_14","PSA","115","14","14","Bari Ubangiji yă sa ku ƙaru, da ku da ’ya’yanku. ");
INSERT INTO hausa_vpl VALUES ("PS115_15","020_115_15","PSA","115","15","15","Bari Ubangiji yă albarkace ku, shi Mahalicci sama da ƙasa. ");
INSERT INTO hausa_vpl VALUES ("PS115_16","020_115_16","PSA","115","16","16","Saman sammai na Ubangiji ne, amma ya ba da duniya ga mutum. ");
INSERT INTO hausa_vpl VALUES ("PS115_17","020_115_17","PSA","115","17","17","Ba matattu ba ne masu yabon Ubangiji, waɗanda suke gangara zuwa wurin da ake shiru; ");
INSERT INTO hausa_vpl VALUES ("PS115_18","020_115_18","PSA","115","18","18","mu ne masu ɗaukaka Ubangiji, yanzu da har abada kuma. Yabi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS116_1","020_116_1","PSA","116","1","1","Ina ƙaunar Ubangiji, gama ya ji muryata; ya ji kukata ta neman jinƙai. ");
INSERT INTO hausa_vpl VALUES ("PS116_2","020_116_2","PSA","116","2","2","Domin ya juye kunnensa gare ni, zan kira gare shi muddin ina da rai. ");
INSERT INTO hausa_vpl VALUES ("PS116_3","020_116_3","PSA","116","3","3","Igiyoyin mutuwa sun shaƙe ni, wahalar kabari sun zo a kaina; na cika da wahala da ɓacin rai. ");
INSERT INTO hausa_vpl VALUES ("PS116_4","020_116_4","PSA","116","4","4","Sai na kira ga sunan Ubangiji na ce, “Ya Ubangiji, ka cece ni!” ");
INSERT INTO hausa_vpl VALUES ("PS116_5","020_116_5","PSA","116","5","5","Ubangiji mai alheri ne da kuma mai adalci; Allahnmu yana cike da tausayi. ");
INSERT INTO hausa_vpl VALUES ("PS116_6","020_116_6","PSA","116","6","6","Ubangiji yana tsare masu tawali’u; sa’ad da nake cikin tsananin bukata, ya cece ni. ");
INSERT INTO hausa_vpl VALUES ("PS116_7","020_116_7","PSA","116","7","7","Ka kwantar da hankali, ya raina, gama Ubangiji mai alheri ne a gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS116_8","020_116_8","PSA","116","8","8","Gama kai, ya Ubangiji, ka ceci raina daga mutuwa, idanuna daga hawaye, ƙafafuna daga tuntuɓe, ");
INSERT INTO hausa_vpl VALUES ("PS116_9","020_116_9","PSA","116","9","9","don in iya tafiya a gaban Ubangiji a ƙasar masu rai. ");
INSERT INTO hausa_vpl VALUES ("PS116_10","020_116_10","PSA","116","10","10","Na gaskata, saboda haka na ce, “An azabtar da ni ƙwarai.” ");
INSERT INTO hausa_vpl VALUES ("PS116_11","020_116_11","PSA","116","11","11","Kuma cikin rikicewana na ce, “Dukan mutane maƙaryata ne.” ");
INSERT INTO hausa_vpl VALUES ("PS116_12","020_116_12","PSA","116","12","12","Yaya zan sāka wa Ubangiji saboda dukan alherinsa gare ni? ");
INSERT INTO hausa_vpl VALUES ("PS116_13","020_116_13","PSA","116","13","13","Zan daga kwaf na ceto in kuma kira ga sunan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS116_14","020_116_14","PSA","116","14","14","Zan cika alkawurana ga Ubangiji a gaban dukan mutanensa. ");
INSERT INTO hausa_vpl VALUES ("PS116_15","020_116_15","PSA","116","15","15","Abu mai daraja a gaban Ubangiji shi ne mutuwar tsarkakansa. ");
INSERT INTO hausa_vpl VALUES ("PS116_16","020_116_16","PSA","116","16","16","Ya Ubangiji, da gaske ni bawanka ne; ni bawanka ne, ɗan baiwarka; ka ’yantar da ni daga sarƙoƙi. ");
INSERT INTO hausa_vpl VALUES ("PS116_17","020_116_17","PSA","116","17","17","Zan yi hadayar godiya gare ka in kuma kira bisa sunan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS116_18","020_116_18","PSA","116","18","18","Zan cika alkawurana ga Ubangiji a gaban dukan mutanensa, ");
INSERT INTO hausa_vpl VALUES ("PS116_19","020_116_19","PSA","116","19","19","a filayen gidan Ubangiji, a tsakiyarki, ya Urushalima. Yabi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS117_1","020_117_1","PSA","117","1","1","Yabi Ubangiji, dukanku al’umma; ku ɗaukaka shi, dukanku mutane. ");
INSERT INTO hausa_vpl VALUES ("PS117_2","020_117_2","PSA","117","2","2","Gama ƙaunarsa da girma take gare mu, amincin Ubangiji kuma madawwami ne har abada. Yabi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS118_1","020_118_1","PSA","118","1","1","Ku gode wa Ubangiji, gama nagari ne shi; ƙaunarsa madawwamiya ce har abada. ");
INSERT INTO hausa_vpl VALUES ("PS118_2","020_118_2","PSA","118","2","2","Bari Isra’ila yă ce, “Ƙaunarsa madawwamiya ce har abada.” ");
INSERT INTO hausa_vpl VALUES ("PS118_3","020_118_3","PSA","118","3","3","Bari gidan Haruna yă ce, “Ƙaunarsa madawwamiya ce har abada.” ");
INSERT INTO hausa_vpl VALUES ("PS118_4","020_118_4","PSA","118","4","4","Bari waɗanda suke tsoron Ubangiji su ce, “Ƙaunarsa madawwamiya ce har abada.” ");
INSERT INTO hausa_vpl VALUES ("PS118_5","020_118_5","PSA","118","5","5","Cikin azabata na yi kuka ga Ubangiji, ya kuwa amsa ta wurin ’yantar da ni. ");
INSERT INTO hausa_vpl VALUES ("PS118_6","020_118_6","PSA","118","6","6","Ubangiji yana tare da ni; ba zan ji tsoro ba. Me mutum zai yi mini? ");
INSERT INTO hausa_vpl VALUES ("PS118_7","020_118_7","PSA","118","7","7","Ubangiji yana tare da ni; shi ne mai taimakona. Zan yi nasara a kan abokan gābana. ");
INSERT INTO hausa_vpl VALUES ("PS118_8","020_118_8","PSA","118","8","8","Ya fi kyau in nemi mafaka a wurin Ubangiji da in dogara ga mutum. ");
INSERT INTO hausa_vpl VALUES ("PS118_9","020_118_9","PSA","118","9","9","Ya fi kyau in nemi mafaka a wurin Ubangiji da in dogara ga sarakuna. ");
INSERT INTO hausa_vpl VALUES ("PS118_10","020_118_10","PSA","118","10","10","Dukan al’ummai sun kewaye ni, amma a cikin sunan Ubangiji na hallaka su. ");
INSERT INTO hausa_vpl VALUES ("PS118_11","020_118_11","PSA","118","11","11","Sun kewaye ni a kowane gefe, amma a cikin sunan Ubangiji na hallaka su. ");
INSERT INTO hausa_vpl VALUES ("PS118_12","020_118_12","PSA","118","12","12","Sun rufe ni kamar ƙudan zuma, amma suka mutu nan da nan kamar ƙayayyuwa masu cin wuta; a cikin sunan Ubangiji na hallaka su. ");
INSERT INTO hausa_vpl VALUES ("PS118_13","020_118_13","PSA","118","13","13","An ture ni baya na kusa fāɗuwa, amma Ubangiji ya taimake ni. ");
INSERT INTO hausa_vpl VALUES ("PS118_14","020_118_14","PSA","118","14","14","Ubangiji ne ƙarfina da waƙata; ya zama mai cetona. ");
INSERT INTO hausa_vpl VALUES ("PS118_15","020_118_15","PSA","118","15","15","Sowa ta farin ciki da nasara sun fito a cikin tentunan adalai, “Hannun dama na Ubangiji ya aikata manyan abubuwa! ");
INSERT INTO hausa_vpl VALUES ("PS118_16","020_118_16","PSA","118","16","16","An ɗaga hannun dama na Ubangiji sama; hannun dama na Ubangiji ya aikata manyan abubuwa!” ");
INSERT INTO hausa_vpl VALUES ("PS118_17","020_118_17","PSA","118","17","17","Ba zan mutu ba amma zan rayu, zan kuwa yi shelar abin da Ubangiji ya yi. ");
INSERT INTO hausa_vpl VALUES ("PS118_18","020_118_18","PSA","118","18","18","Ubangiji ya hore ni sosai, amma bai ba da ni ga mutuwa ba. ");
INSERT INTO hausa_vpl VALUES ("PS118_19","020_118_19","PSA","118","19","19","Buɗe mini ƙofofin adalci; zan shiga in kuma yi godiya ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS118_20","020_118_20","PSA","118","20","20","Wannan ne ƙofar Ubangiji inda adalai za su shiga. ");
INSERT INTO hausa_vpl VALUES ("PS118_21","020_118_21","PSA","118","21","21","Zan yi maka godiya, domin ka amsa mini; ka zama mai cetona. ");
INSERT INTO hausa_vpl VALUES ("PS118_22","020_118_22","PSA","118","22","22","Zabura Dutsen da magina suka ƙi ya zama mai amfani; ");
INSERT INTO hausa_vpl VALUES ("PS118_23","020_118_23","PSA","118","23","23","Ubangiji ne ya yi haka, kuma abu mai daraja ne a idanunmu. ");
INSERT INTO hausa_vpl VALUES ("PS118_24","020_118_24","PSA","118","24","24","Wannan ita ce ranar da Ubangiji ya yi; bari mu yi farin ciki mu kuma yi murna a cikinta. ");
INSERT INTO hausa_vpl VALUES ("PS118_25","020_118_25","PSA","118","25","25","Ya Ubangiji, ka cece mu; Ya Ubangiji, ka ba mu nasara. ");
INSERT INTO hausa_vpl VALUES ("PS118_26","020_118_26","PSA","118","26","26","Mai albarka ne shi mai zuwa cikin sunan Ubangiji. Daga gidan Ubangiji muna sa muku albarka. ");
INSERT INTO hausa_vpl VALUES ("PS118_27","020_118_27","PSA","118","27","27","Ubangiji shi ne Allah ya kuma sa haskensa ya haskaka a kanmu. Da kwanoni a hannunmu, muka shiga jerin gwanon biki ku kai su ƙahoni na bagade. ");
INSERT INTO hausa_vpl VALUES ("PS118_28","020_118_28","PSA","118","28","28","Kai ne Allahna, zan kuwa yi maka godiya; kai ne Allahna, zan kuwa ɗaukaka ka. ");
INSERT INTO hausa_vpl VALUES ("PS118_29","020_118_29","PSA","118","29","29","Ku gode wa Ubangiji, gama nagari ne shi; ƙaunarsa madawwamiya ce har abada. ");
INSERT INTO hausa_vpl VALUES ("PS119_1","020_119_1","PSA","119","1","1","Albarka ta tabbata ga waɗanda rayuwarsu ba ta da abin zargi, waɗanda suke tafiya bisa ga dokar Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS119_2","020_119_2","PSA","119","2","2","Albarka ta tabbata ga waɗanda suke kiyaye ƙa’idodinsa suke kuma nemansa da dukan zuciyarsu. ");
INSERT INTO hausa_vpl VALUES ("PS119_3","020_119_3","PSA","119","3","3","Ba sa yin wani abin da ba daidai ba; suna tafiya a hanyoyinsa. ");
INSERT INTO hausa_vpl VALUES ("PS119_4","020_119_4","PSA","119","4","4","Ka shimfiɗa farillan da dole a yi biyayya da su. ");
INSERT INTO hausa_vpl VALUES ("PS119_5","020_119_5","PSA","119","5","5","Kash, da a ce hanyoyina tsayayyu ne a yin biyayya da ƙa’idodinka mana! ");
INSERT INTO hausa_vpl VALUES ("PS119_6","020_119_6","PSA","119","6","6","Da ba zan sha kunya ba sa’ad da na lura da dukan umarnanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_7","020_119_7","PSA","119","7","7","Zan yabe ka da zuciya ta gaskiya yayinda nake koyon dokokinka masu adalci. ");
INSERT INTO hausa_vpl VALUES ("PS119_8","020_119_8","PSA","119","8","8","Zan yi biyayya da ƙa’idodinka; kada ka yashe ni ɗungum. ");
INSERT INTO hausa_vpl VALUES ("PS119_9","020_119_9","PSA","119","9","9","Yaya matashi zai kiyaye hanyarsa da tsabta? Sai ta yin rayuwa bisa ga maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_10","020_119_10","PSA","119","10","10","Na neme ka da dukan zuciyata; kada ka bar ni in kauce daga umarnanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_11","020_119_11","PSA","119","11","11","Na ɓoye maganarka a cikin zuciyata don kada in yi maka zunubi. ");
INSERT INTO hausa_vpl VALUES ("PS119_12","020_119_12","PSA","119","12","12","Yabo ya tabbata gare ka, ya Ubangiji; ka koya mini ƙa’idodinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_13","020_119_13","PSA","119","13","13","Da leɓunana na ba da labarin dukan dokokin da suka fito bakinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_14","020_119_14","PSA","119","14","14","Na yi farin ciki da bin farillanka yadda mutum yakan yi farin ciki da arziki mai yawa. ");
INSERT INTO hausa_vpl VALUES ("PS119_15","020_119_15","PSA","119","15","15","Na yi tunani a kan farillanka na kuma lura da hanyoyinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_16","020_119_16","PSA","119","16","16","Na yi murna a cikin ƙa’idodinka; ba zan ƙyale maganarka ba. ");
INSERT INTO hausa_vpl VALUES ("PS119_17","020_119_17","PSA","119","17","17","Ka yi alheri ga bawanka, zan kuwa rayu; zan yi biyayya da maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_18","020_119_18","PSA","119","18","18","Ka buɗe idanuna don in iya gani abubuwan banmamaki a cikin dokarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_19","020_119_19","PSA","119","19","19","Ni baƙo ne a duniya; kada ka ɓoye mini umarnanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_20","020_119_20","PSA","119","20","20","Zuciyata ta ƙosa saboda marmari don dokokinka koyaushe. ");
INSERT INTO hausa_vpl VALUES ("PS119_21","020_119_21","PSA","119","21","21","Ka tsawata wa masu fariya, waɗanda suke la’anta waɗanda kuma suka kauce daga umarnanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_22","020_119_22","PSA","119","22","22","Ka cire mini ba’a da reni, gama ina kiyaye farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_23","020_119_23","PSA","119","23","23","Ko da yake masu mulki sun zauna tare suna ɓata mini suna, bawanka zai yi tunani a kan ƙa’idodinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_24","020_119_24","PSA","119","24","24","Farillanka ne abin farin cikina; su ne mashawartana. ");
INSERT INTO hausa_vpl VALUES ("PS119_25","020_119_25","PSA","119","25","25","An kwantar da ni ƙasa cikin ƙura; ka kiyaye raina bisa ga maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_26","020_119_26","PSA","119","26","26","Na ba da labari hanyoyina ka kuma amsa mini; ka koya mini ƙa’idodinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_27","020_119_27","PSA","119","27","27","Bari in gane koyarwar farillanka; sa’an nan zan yi tunani a kan abubuwan banmamakinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_28","020_119_28","PSA","119","28","28","Raina ya gaji da baƙin ciki; ka ƙarfafa ni bisa ga maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_29","020_119_29","PSA","119","29","29","Ka kiyaye ni daga hanyoyin ruɗu; ka yi mini alheri ta wurin dokokinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_30","020_119_30","PSA","119","30","30","Na zaɓi hanyar gaskiya; na sa zuciyata a kan dokokinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_31","020_119_31","PSA","119","31","31","Na riƙe farillanka kankan, ya Ubangiji; kada ka sa in sha kunya. ");
INSERT INTO hausa_vpl VALUES ("PS119_32","020_119_32","PSA","119","32","32","Ina gudu a kan hanyar umarnanka, gama ka ’yantar da zuciyata. ");
INSERT INTO hausa_vpl VALUES ("PS119_33","020_119_33","PSA","119","33","33","Ka koya mini Ya Ubangiji, don in bi ƙa’idodinka; sa’an nan zan kiyaye su har ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("PS119_34","020_119_34","PSA","119","34","34","Ka ba ni ganewa, zan kuwa kiyaye dokarka in kuma yi biyayya da ita da dukan zuciyata. ");
INSERT INTO hausa_vpl VALUES ("PS119_35","020_119_35","PSA","119","35","35","Ka bi da ni a hanyar umarnanka, gama a can zan sami farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS119_36","020_119_36","PSA","119","36","36","Ka juye zuciyata wajen farillanka ba wajen riba ta sonkai ba. ");
INSERT INTO hausa_vpl VALUES ("PS119_37","020_119_37","PSA","119","37","37","Ka juye idanuna daga abubuwa marasa amfani; ka kiyaye raina bisa ga maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_38","020_119_38","PSA","119","38","38","Ka cika alkawarinka ga bawanka, saboda a ji tsoronka. ");
INSERT INTO hausa_vpl VALUES ("PS119_39","020_119_39","PSA","119","39","39","Ka kawar da shan kunyar da nake tsoro, gama dokokinka nagari ne. ");
INSERT INTO hausa_vpl VALUES ("PS119_40","020_119_40","PSA","119","40","40","Ina marmarin farillanka ƙwarai! Ka kiyaye raina cikin adalcinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_41","020_119_41","PSA","119","41","41","Bari ƙaunarka marar ƙarewa ta zo gare ni, ya Ubangiji, cetonka bisa ga alkawarinka; ");
INSERT INTO hausa_vpl VALUES ("PS119_42","020_119_42","PSA","119","42","42","sa’an nan zan amsa wa masu cin mutuncina, gama na dogara ga maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_43","020_119_43","PSA","119","43","43","Kada ka ƙwace maganarka daga bakina, gama na sa zuciyata a dokokinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_44","020_119_44","PSA","119","44","44","Kullayaumi zan yi biyayya da dokokinka, har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("PS119_45","020_119_45","PSA","119","45","45","Zan yi ta yawo a sake gama na nemi farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_46","020_119_46","PSA","119","46","46","Zan yi maganar farillanka a gaban sarakuna ba kuwa za a kunyata ni ba, ");
INSERT INTO hausa_vpl VALUES ("PS119_47","020_119_47","PSA","119","47","47","gama ina farin ciki da umarnanka saboda ina ƙaunarsu. ");
INSERT INTO hausa_vpl VALUES ("PS119_48","020_119_48","PSA","119","48","48","Na ɗaga hannuwana ga umarnanka, waɗanda nake ƙauna, ina kuma tunani a kan ƙa’idodinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_49","020_119_49","PSA","119","49","49","Tuna da maganarka ga bawanka, gama ka ba ni bege. ");
INSERT INTO hausa_vpl VALUES ("PS119_50","020_119_50","PSA","119","50","50","Ta’aziyyata cikin wahalata ita ce alkawarinka yana kiyaye raina. ");
INSERT INTO hausa_vpl VALUES ("PS119_51","020_119_51","PSA","119","51","51","Masu fariya suna yi mini ba’a ba tare da an hana su ba, amma ban rabu da dokar ba. ");
INSERT INTO hausa_vpl VALUES ("PS119_52","020_119_52","PSA","119","52","52","Na tuna da dokokinka na tun dā, ya Ubangiji, na kuwa sami ta’aziyya a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("PS119_53","020_119_53","PSA","119","53","53","Fushi ya kama ni saboda mugaye, waɗanda suka keta dokokinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_54","020_119_54","PSA","119","54","54","Ƙa’idodinka su ne kan waƙata a duk inda na sauka. ");
INSERT INTO hausa_vpl VALUES ("PS119_55","020_119_55","PSA","119","55","55","Da dare na tuna da sunanka, ya Ubangiji, zan kuwa kiyaye dokarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_56","020_119_56","PSA","119","56","56","Wannan shi ne na saba yi, ina yin biyayya da farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_57","020_119_57","PSA","119","57","57","Kai ne rabona, ya Ubangiji; na yi alkawarin in kiyaye maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_58","020_119_58","PSA","119","58","58","Na nemi fuskarka da dukan zuciyata; ka yi mini alheri bisa ga alkawarinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_59","020_119_59","PSA","119","59","59","Na lura da hanyoyina na kuma mayar da matakaina ga farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_60","020_119_60","PSA","119","60","60","Zan gaggauta ba zan ɓata lokaci ba in yi biyayya da umarnanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_61","020_119_61","PSA","119","61","61","Ko da yake mugaye sun ɗaura ni da igiyoyi, ba zan manta da dokokinka ba. ");
INSERT INTO hausa_vpl VALUES ("PS119_62","020_119_62","PSA","119","62","62","Da tsakar dare nakan tashi in gode maka saboda dokokinka masu adalci. ");
INSERT INTO hausa_vpl VALUES ("PS119_63","020_119_63","PSA","119","63","63","Ni aboki ne ga duk mai tsoronka, ga duk wanda yake bin farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_64","020_119_64","PSA","119","64","64","Duniya ta cika da ƙaunarka, ya Ubangiji; ka koya mini ƙa’idodinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_65","020_119_65","PSA","119","65","65","Ka yi wa bawanka alheri bisa ga maganarka, ya Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS119_66","020_119_66","PSA","119","66","66","Ka koya mini sani da kuma hukunci mai kyau, gama na gaskata a umarnanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_67","020_119_67","PSA","119","67","67","Kafin in sha wahala na kauce, amma yanzu ina biyayya da maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_68","020_119_68","PSA","119","68","68","Kai nagari ne, kuma abin da kake yi yana da kyau; ka koya mini ƙa’idodinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_69","020_119_69","PSA","119","69","69","Ko da yake masu fariya sun shafe ni da ƙarairayi, na kiyaye farillanka da dukan zuciyata. ");
INSERT INTO hausa_vpl VALUES ("PS119_70","020_119_70","PSA","119","70","70","Zukatansu sun yi tauri da kuma marasa tausayi amma ina farin ciki a dokarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_71","020_119_71","PSA","119","71","71","Ya yi kyau da na sha wahala don in koyi ƙa’idodinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_72","020_119_72","PSA","119","72","72","Doka daga bakinka ya fi mini daraja fiye da azurfa da zinariya guda dubu. ");
INSERT INTO hausa_vpl VALUES ("PS119_73","020_119_73","PSA","119","73","73","Hannuwanka ne suka yi suka kuma siffanta ni; ka ba ni ganewa don in koyi umarnanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_74","020_119_74","PSA","119","74","74","Bari waɗanda suke tsoronka su yi farin ciki sa’ad da suke gan ni, gama na sa zuciyata a maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_75","020_119_75","PSA","119","75","75","Ya Ubangiji na sani, cewa dokokinka masu adalci ne, kuma cikin aminci ka hore ni. ");
INSERT INTO hausa_vpl VALUES ("PS119_76","020_119_76","PSA","119","76","76","Bari ƙaunarka marar ƙarewa tă yi mini ta’aziyya, bisa ga alkawarinka ga bawanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_77","020_119_77","PSA","119","77","77","Bari tausayinka yă zo mini don in rayu, gama dokarka ce farin cikina. ");
INSERT INTO hausa_vpl VALUES ("PS119_78","020_119_78","PSA","119","78","78","Bari masu girman kai su sha kunya saboda abubuwa marasa kyau da suke yi mini ba dalili; amma zan yi tunani a kan farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_79","020_119_79","PSA","119","79","79","Bari waɗanda suke tsoronka su juya gare ni, waɗanda suka gane da farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_80","020_119_80","PSA","119","80","80","Bari zuciyata ta kasance marar abin zargi wajen ƙa’idodinka, don kada in sha kunya. ");
INSERT INTO hausa_vpl VALUES ("PS119_81","020_119_81","PSA","119","81","81","Raina ya tafke da marmari don cetonka, amma na sa zuciyata a maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_82","020_119_82","PSA","119","82","82","Idanuna sun gaji, suna jiran alkawarinka; Na ce, “Yaushe za ka ta’azantar da ni?” ");
INSERT INTO hausa_vpl VALUES ("PS119_83","020_119_83","PSA","119","83","83","Ko da yake ni kamar salkar ruwan inabi ne a cikin hayaƙi, ban manta da ƙa’idodinka ba. ");
INSERT INTO hausa_vpl VALUES ("PS119_84","020_119_84","PSA","119","84","84","Har yaushe bawanka zai yi ta jira? Yaushe za ka hukunta masu tsananta mini? ");
INSERT INTO hausa_vpl VALUES ("PS119_85","020_119_85","PSA","119","85","85","Masu girman kai sun haƙa mini rami, sun ƙetare dokarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_86","020_119_86","PSA","119","86","86","Dukan umarnanka abin dogara ne; ka taimake ni, gama mutane suna tsananta mini ba dalili. ");
INSERT INTO hausa_vpl VALUES ("PS119_87","020_119_87","PSA","119","87","87","Sun kusa gama da ni a duniya, amma ban bar bin farillanka ba. ");
INSERT INTO hausa_vpl VALUES ("PS119_88","020_119_88","PSA","119","88","88","Ka kiyaye raina bisa ga ƙaunarka, zan kuwa yi biyayya da farillan bakinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_89","020_119_89","PSA","119","89","89","Maganarka, ya Ubangiji madawwamiya ce; tana nan daram a cikin sammai. ");
INSERT INTO hausa_vpl VALUES ("PS119_90","020_119_90","PSA","119","90","90","Amincinka yana cin gaba cikin dukan zamanai; ka kafa duniya ta kuma dawwama. ");
INSERT INTO hausa_vpl VALUES ("PS119_91","020_119_91","PSA","119","91","91","Dokokinka sun dawwama har yă zuwa yau, gama dukan abubuwa suna maka hidima. ");
INSERT INTO hausa_vpl VALUES ("PS119_92","020_119_92","PSA","119","92","92","Da ba don dokarka ce farin cikina ba, da na hallaka a cikin azabana. ");
INSERT INTO hausa_vpl VALUES ("PS119_93","020_119_93","PSA","119","93","93","Ba zan taɓa manta da farillanka ba, gama ta wurinsu ne ka kiyaye raina. ");
INSERT INTO hausa_vpl VALUES ("PS119_94","020_119_94","PSA","119","94","94","Ka cece ni, gama ni naka ne; na yi ƙoƙarin neman farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_95","020_119_95","PSA","119","95","95","Mugaye suna jira su hallaka ni, amma zan yi ta tunani a kan farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_96","020_119_96","PSA","119","96","96","Ga duk cikakke na ga kāsawa; amma umarnanka ba su da iyaka. ");
INSERT INTO hausa_vpl VALUES ("PS119_97","020_119_97","PSA","119","97","97","Kash, ga yadda nake ƙaunar dokarka! Ina tunani a kanta dukan yini. ");
INSERT INTO hausa_vpl VALUES ("PS119_98","020_119_98","PSA","119","98","98","Umarnanka suna sa in zama mai hikima fiye da abokan gābana, gama kullum suna tare da ni. ");
INSERT INTO hausa_vpl VALUES ("PS119_99","020_119_99","PSA","119","99","99","Ina da ganewa sosai fiye da dukan malamaina, gama ina tunani a kan farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_100","020_119_100","PSA","119","100","100","Ina da ganewa fiye da dattawa, gama ina biyayya da farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_101","020_119_101","PSA","119","101","101","Na kiyaye ƙafafuna daga kowace muguwar hanya domin in yi biyayya da maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_102","020_119_102","PSA","119","102","102","Ban rabu da dokokinka ba, gama kai da kanka ne ka koya mini. ");
INSERT INTO hausa_vpl VALUES ("PS119_103","020_119_103","PSA","119","103","103","Ɗanɗanon maganarka akwai zaki, sun ma fi zuma zaki a bakina! ");
INSERT INTO hausa_vpl VALUES ("PS119_104","020_119_104","PSA","119","104","104","Na sami ganewa daga farillanka; saboda haka ina ƙin kowace hanyar da ba daidai ba. ");
INSERT INTO hausa_vpl VALUES ("PS119_105","020_119_105","PSA","119","105","105","Maganarka fitila ce ga ƙafafuna haske kuma a kan hanyata. ");
INSERT INTO hausa_vpl VALUES ("PS119_106","020_119_106","PSA","119","106","106","Na yi rantsuwa na kuma tabbatar da shi, cewa zan bi dokokinka masu adalci. ");
INSERT INTO hausa_vpl VALUES ("PS119_107","020_119_107","PSA","119","107","107","Na sha wahala sosai; ka kiyaye raina, ya Ubangiji, bisa ga maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_108","020_119_108","PSA","119","108","108","Ka karɓi yabon bakina da nake yi da yardar rai, ya Ubangiji, ka kuwa koya mini dokokinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_109","020_119_109","PSA","119","109","109","Ko da yake kullum ina riƙe da raina a hannuwana, ba zan manta da dokarka ba. ");
INSERT INTO hausa_vpl VALUES ("PS119_110","020_119_110","PSA","119","110","110","Mugaye sun kafa mini tarko, amma ban kauce daga farillanka ba. ");
INSERT INTO hausa_vpl VALUES ("PS119_111","020_119_111","PSA","119","111","111","Farillanka su ne gādona har abada; su ne farin cikin zuciyata. ");
INSERT INTO hausa_vpl VALUES ("PS119_112","020_119_112","PSA","119","112","112","Zuciyata ta shirya a kan kiyaye ƙa’idodinka har ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("PS119_113","020_119_113","PSA","119","113","113","Na ƙi mutane masu baki biyu, amma ina ƙauna dokarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_114","020_119_114","PSA","119","114","114","Kai ne mafakata da garkuwata; na sa zuciyata a maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_115","020_119_115","PSA","119","115","115","Ku rabu da ni, ku masu aikata mugunta, don in kiyaye umarnan Allahna! ");
INSERT INTO hausa_vpl VALUES ("PS119_116","020_119_116","PSA","119","116","116","Ka raya ni bisa ga alkawarinka, zan kuwa rayu; kada ka bari a gwale sa zuciyata. ");
INSERT INTO hausa_vpl VALUES ("PS119_117","020_119_117","PSA","119","117","117","Ka riƙe ni za a kuma cece ni; kullayaumi zan ɗauka ƙa’idodinka da muhimmanci. ");
INSERT INTO hausa_vpl VALUES ("PS119_118","020_119_118","PSA","119","118","118","Ka ki dukan waɗanda suka kauce daga ƙa’idodinka, gama yaudararsu banza ne. ");
INSERT INTO hausa_vpl VALUES ("PS119_119","020_119_119","PSA","119","119","119","Dukan mugayen duniya ka zubar kamar datti; saboda haka nake ƙaunar farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_120","020_119_120","PSA","119","120","120","Naman jikina na rawan jiki don tsoronka; na cika da tsoron dokokinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_121","020_119_121","PSA","119","121","121","Na aikata abin da yake mai adalci da kuma daidai; kada ka ni a hannun masu danne ni. ");
INSERT INTO hausa_vpl VALUES ("PS119_122","020_119_122","PSA","119","122","122","Ka tabbatar da lafiyar bawanka; kada ka bar masu girman kai su danne ni. ");
INSERT INTO hausa_vpl VALUES ("PS119_123","020_119_123","PSA","119","123","123","Idanuna sun gaji, da jiran cetonka, da jiran alkawarinka mai adalci. ");
INSERT INTO hausa_vpl VALUES ("PS119_124","020_119_124","PSA","119","124","124","Ka yi da bawanka bisa ga ƙaunarka ka kuma koya mini ƙa’idodinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_125","020_119_125","PSA","119","125","125","Ni bawanka ne, ka ba ni fahimi don in gane farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_126","020_119_126","PSA","119","126","126","Lokaci ya yi da za ka yi wani abu, ya Ubangiji; ana karya dokarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_127","020_119_127","PSA","119","127","127","Saboda ina ƙaunar umarnanka fiye da zinariya, kai, fiye da zinariya zalla, ");
INSERT INTO hausa_vpl VALUES ("PS119_128","020_119_128","PSA","119","128","128","saboda kuma ina lura da dukan farillanka da kyau, na ƙi kowace hanyar da ba daidai ba. ");
INSERT INTO hausa_vpl VALUES ("PS119_129","020_119_129","PSA","119","129","129","Farillanka masu banmamaki ne; saboda haka nake yin biyayya da su. ");
INSERT INTO hausa_vpl VALUES ("PS119_130","020_119_130","PSA","119","130","130","Fassarar maganganunka sukan ba da haske; sukan ba da ganewa ga marar ilimi. ");
INSERT INTO hausa_vpl VALUES ("PS119_131","020_119_131","PSA","119","131","131","Ina hakkin da bakina a buɗe, ina marmarin umarnanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_132","020_119_132","PSA","119","132","132","Ka juye wurina ka kuma yi mini jinƙai, yadda kullum ka yi wa waɗanda suke ƙaunar sunanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_133","020_119_133","PSA","119","133","133","Ka bi da sawuna bisa ga maganarka; kada ka bar zunubi yă mallake ni. ");
INSERT INTO hausa_vpl VALUES ("PS119_134","020_119_134","PSA","119","134","134","Ka fanshe ni daga mutane masu danniya, don in yi biyayya da farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_135","020_119_135","PSA","119","135","135","Ka sa fuskarka ta haskaka a kan bawanka ka kuma koya mini ƙa’idodinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_136","020_119_136","PSA","119","136","136","Hawaye suna malalowa daga idanuna kamar rafi, gama ba a biyayya da dokarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_137","020_119_137","PSA","119","137","137","Mai adalci ne kai, ya Ubangiji, dokokinka kuma daidai ne. ");
INSERT INTO hausa_vpl VALUES ("PS119_138","020_119_138","PSA","119","138","138","Farillan da ka shimfiɗa masu adalci ne; su kuma abin dogara ne ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("PS119_139","020_119_139","PSA","119","139","139","Kishina ya cinye ni ɗungum, gama abokan gābana sun yi biris da maganganunka. ");
INSERT INTO hausa_vpl VALUES ("PS119_140","020_119_140","PSA","119","140","140","An gwada alkawuranka sarai, bawanka kuwa yana ƙaunarsu. ");
INSERT INTO hausa_vpl VALUES ("PS119_141","020_119_141","PSA","119","141","141","Ko da yake ni ba kome ba ne an kuwa rena ni, ba na manta da farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_142","020_119_142","PSA","119","142","142","Adalcinka dawwammame ne dokar kuma gaskiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS119_143","020_119_143","PSA","119","143","143","Wahala da damuwa suna a kaina, amma umarnanka su ne farin cikina. ");
INSERT INTO hausa_vpl VALUES ("PS119_144","020_119_144","PSA","119","144","144","Farillanka daidai ne har abada; ka ba ni ganewa don in rayu. ");
INSERT INTO hausa_vpl VALUES ("PS119_145","020_119_145","PSA","119","145","145","Na yi kira da dukan zuciyata; ka amsa mini, ya Ubangiji, zan kuwa yi biyayya da ƙa’idodinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_146","020_119_146","PSA","119","146","146","Na yi kira gare ka; ka cece ni zan kuwa kiyaye farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_147","020_119_147","PSA","119","147","147","Na tashi kafin fitowar rana na kuma yi kukan neman taimako; na sa zuciyata a maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_148","020_119_148","PSA","119","148","148","Ban rufe idanuna ba dukan dare, don in yi tunani a kan alkawuranka. ");
INSERT INTO hausa_vpl VALUES ("PS119_149","020_119_149","PSA","119","149","149","Ka ji muryata bisa ga ƙaunarka; ka kiyaye raina, ya Ubangiji, bisa ga dokokinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_150","020_119_150","PSA","119","150","150","Waɗanda suke ƙirƙiro mugayen dabaru suna nan kusa, amma suna nesa da dokarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_151","020_119_151","PSA","119","151","151","Duk da haka kana kusa, ya Ubangiji, kuma dukan umarnanka gaskiya ne. ");
INSERT INTO hausa_vpl VALUES ("PS119_152","020_119_152","PSA","119","152","152","Tun tuni na koyi daga farillanka cewa ka kafa su su kasance har abada. ");
INSERT INTO hausa_vpl VALUES ("PS119_153","020_119_153","PSA","119","153","153","Ka dubi wahalata ka cece ni, gama ban manta da dokarka ba. ");
INSERT INTO hausa_vpl VALUES ("PS119_154","020_119_154","PSA","119","154","154","Ka kāre manufata ka kuma fanshe ni, ka cece rai na kamar yadda ka alkawarta! ");
INSERT INTO hausa_vpl VALUES ("PS119_155","020_119_155","PSA","119","155","155","Ceto yana nesa da mugaye, gama ba sa neman ƙa’idodinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_156","020_119_156","PSA","119","156","156","Tausayinka da girma yake, ya Ubangiji; ka kiyaye raina bisa ga dokokinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_157","020_119_157","PSA","119","157","157","Maƙiya masu yawa ne suke tsananta mini, amma ban rabu da farillanka ba. ");
INSERT INTO hausa_vpl VALUES ("PS119_158","020_119_158","PSA","119","158","158","Na dubi marasa aminci da ƙyama, gama ba sa yin biyayya da maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_159","020_119_159","PSA","119","159","159","Dubi yadda nake ƙaunar farillanka; ka kiyaye raina, ya Ubangiji, bisa ga ƙaunarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_160","020_119_160","PSA","119","160","160","Dukan maganganunka gaskiya ne; dukan dokokinka masu adalci madawwami ne. ");
INSERT INTO hausa_vpl VALUES ("PS119_161","020_119_161","PSA","119","161","161","Masu mulki suna tsananta mini ba dalili, amma zuciyata na rawan jiki game da maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_162","020_119_162","PSA","119","162","162","Ina farin ciki da alkawarinka kamar yadda wani kan sami ganima mai girma. ");
INSERT INTO hausa_vpl VALUES ("PS119_163","020_119_163","PSA","119","163","163","Na ƙi ina kuma ƙyamar ƙarya amma ina ƙaunar dokarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_164","020_119_164","PSA","119","164","164","Sau bakwai a rana ina yabonka saboda dokokinka masu adalci. ");
INSERT INTO hausa_vpl VALUES ("PS119_165","020_119_165","PSA","119","165","165","Waɗanda suke ƙaunar dokarka suna da babban salama, kuma babu abin da zai sa su yi tuntuɓe. ");
INSERT INTO hausa_vpl VALUES ("PS119_166","020_119_166","PSA","119","166","166","Ina jiran cetonka, ya Ubangiji, ina kuma bin umarnanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_167","020_119_167","PSA","119","167","167","Ina biyayya da farillanka, gama ina ƙaunarsu ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("PS119_168","020_119_168","PSA","119","168","168","Ina biyayya da farillanka da kuma koyarwarka, gama dukan hanyoyina sanannu ne gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS119_169","020_119_169","PSA","119","169","169","Bari kukata ta zo gare ka, ya Ubangiji; ka ba ni ganewa bisa ga maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS119_170","020_119_170","PSA","119","170","170","Bari roƙona yă zo gabanka; ka cece ni bisa ga alkawarinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_171","020_119_171","PSA","119","171","171","Bari leɓunana su cika da yabonka, gama ka koya mini ƙa’idodinka. ");
INSERT INTO hausa_vpl VALUES ("PS119_172","020_119_172","PSA","119","172","172","Bari harshena yă rera game da maganarka, gama dukan umarnanka masu adalci ne. ");
INSERT INTO hausa_vpl VALUES ("PS119_173","020_119_173","PSA","119","173","173","Bari hannunka yă kasance a shirye don yă taimake ni, gama na zaɓi farillanka. ");
INSERT INTO hausa_vpl VALUES ("PS119_174","020_119_174","PSA","119","174","174","Ina marmarin cetonka, ya Ubangiji, dokarka kuwa ita ce farin cikina. ");
INSERT INTO hausa_vpl VALUES ("PS119_175","020_119_175","PSA","119","175","175","Bari in rayu don in yabe ka, bari kuma dokokinka su raya ni. ");
INSERT INTO hausa_vpl VALUES ("PS119_176","020_119_176","PSA","119","176","176","Na kauce kamar ɓatacciyar tunkiya. Ka nemi bawanka, gama ban manta da umarnanka ba. ");
INSERT INTO hausa_vpl VALUES ("PS120_1","020_120_1","PSA","120","1","1","Waƙar haurawa. Na yi kira ga Ubangiji cikin damuwata, ya kuwa amsa mini. ");
INSERT INTO hausa_vpl VALUES ("PS120_2","020_120_2","PSA","120","2","2","Ka cece ni, ya Ubangiji, daga leɓuna masu ƙarya da kuma daga harsuna masu yaudara. ");
INSERT INTO hausa_vpl VALUES ("PS120_3","020_120_3","PSA","120","3","3","Me zai yi maka, me kuma ya fi, ya kai harshe mai yaudara? ");
INSERT INTO hausa_vpl VALUES ("PS120_4","020_120_4","PSA","120","4","4","Zai hukunta ku da kibiyoyi masu tsini na jarumi, tare da garwashin wuta na itacen tsintsiya. ");
INSERT INTO hausa_vpl VALUES ("PS120_5","020_120_5","PSA","120","5","5","Kaitona da nake zama a Meshek, da nake zama a ciki tentunan Kedar! ");
INSERT INTO hausa_vpl VALUES ("PS120_6","020_120_6","PSA","120","6","6","Da daɗewa na zauna a cikin waɗanda suke ƙin salama. ");
INSERT INTO hausa_vpl VALUES ("PS120_7","020_120_7","PSA","120","7","7","Ni mutum ne mai salama; amma sa’ad da na yi magana, su sai su yi ta yaƙi. ");
INSERT INTO hausa_vpl VALUES ("PS121_1","020_121_1","PSA","121","1","1","Waƙar haurawa. Na tā da idanuna zuwa wajen tuddai, ta ina ne taimakona zai zo? ");
INSERT INTO hausa_vpl VALUES ("PS121_2","020_121_2","PSA","121","2","2","Taimakona zai zo daga wurin Ubangiji, wanda ya kafa sama da ƙasa. ");
INSERT INTO hausa_vpl VALUES ("PS121_3","020_121_3","PSA","121","3","3","Ba zai bari ƙafarka tă yi santsi ba, shi da yake tsaronka ba zai yi gyangyaɗi ba; ");
INSERT INTO hausa_vpl VALUES ("PS121_4","020_121_4","PSA","121","4","4","tabbatacce, shi da yake tsaron Isra’ila ba ya gyangyaɗi ko barci. ");
INSERT INTO hausa_vpl VALUES ("PS121_5","020_121_5","PSA","121","5","5","Ubangiji yana tsaronka, Ubangiji ne inuwa a hannun damanka; ");
INSERT INTO hausa_vpl VALUES ("PS121_6","020_121_6","PSA","121","6","6","rana ba za tă buge ka cikin yini ba balle wata da dare. ");
INSERT INTO hausa_vpl VALUES ("PS121_7","020_121_7","PSA","121","7","7","Ubangiji zai kiyaye ka daga dukan masifa, zai tsare ranka; ");
INSERT INTO hausa_vpl VALUES ("PS121_8","020_121_8","PSA","121","8","8","Ubangiji zai kiyaye shigarka da fitarka yanzu da har abada kuma. ");
INSERT INTO hausa_vpl VALUES ("PS122_1","020_122_1","PSA","122","1","1","Waƙar haurawa. Ta Dawuda. Na yi farin ciki tare da waɗanda suka ce da ni, “Bari mu tafi gidan Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("PS122_2","020_122_2","PSA","122","2","2","Ƙafafunmu suna tsaye a ƙofofinki, ya Urushalima. ");
INSERT INTO hausa_vpl VALUES ("PS122_3","020_122_3","PSA","122","3","3","An gina Urushalima kamar birnin da aka yi a harhaɗe wuri guda. ");
INSERT INTO hausa_vpl VALUES ("PS122_4","020_122_4","PSA","122","4","4","A can ne kabilu suke haurawa, kabilan Ubangiji, don su yabi sunan Ubangiji bisa ga farillan da aka ba wa Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS122_5","020_122_5","PSA","122","5","5","A can kursiyoyin shari’a yake tsaye, kursiyoyin gidan Dawuda. ");
INSERT INTO hausa_vpl VALUES ("PS122_6","020_122_6","PSA","122","6","6","Ku yi addu’a don salamar Urushalima, “Bari waɗanda suke ƙaunarki su zauna lafiya. ");
INSERT INTO hausa_vpl VALUES ("PS122_7","020_122_7","PSA","122","7","7","Bari salama ta kasance a katangarki zaman lafiya kuma a fadodinki.” ");
INSERT INTO hausa_vpl VALUES ("PS122_8","020_122_8","PSA","122","8","8","Saboda ’yan’uwana da kuma abokaina, zan ce, “Salama tă kasance tare da ke.” ");
INSERT INTO hausa_vpl VALUES ("PS122_9","020_122_9","PSA","122","9","9","Saboda gidan Ubangiji Allahnmu, zan nemi wadatarki. ");
INSERT INTO hausa_vpl VALUES ("PS123_1","020_123_1","PSA","123","1","1","Waƙar haurawa. Na tā da idanuna gare ka, gare ka da kursiyinka yake cikin sama. ");
INSERT INTO hausa_vpl VALUES ("PS123_2","020_123_2","PSA","123","2","2","Kamar yadda idanun bayi suna duban hannun maigidansu, kamar yadda idanun baiwa suna duban hannun uwargijiyarta, haka idanunmu suna duban Ubangiji Allahnmu, sai ya nuna mana jinƙansa. ");
INSERT INTO hausa_vpl VALUES ("PS123_3","020_123_3","PSA","123","3","3","Ka yi mana jinƙai, ya Ubangiji, ka yi mana jinƙai, gama mun jimre da reni mai yawa. ");
INSERT INTO hausa_vpl VALUES ("PS123_4","020_123_4","PSA","123","4","4","Mun jimre da wulaƙanci daga masu girman kai, reni mai yawa daga masu fariya. ");
INSERT INTO hausa_vpl VALUES ("PS124_1","020_124_1","PSA","124","1","1","Waƙar haurawa. Ta Dawuda. Da ba don Ubangiji ya kasance a gefenmu ba, bari Isra’ila yă ce, ");
INSERT INTO hausa_vpl VALUES ("PS124_2","020_124_2","PSA","124","2","2","da ba don Ubangiji ya kasance a gefenmu ba sa’ad da aka auka mana, ");
INSERT INTO hausa_vpl VALUES ("PS124_3","020_124_3","PSA","124","3","3","sa’ad da fushinsu ya ƙuna a kanmu, ai, da sun haɗiye mu da rai; ");
INSERT INTO hausa_vpl VALUES ("PS124_4","020_124_4","PSA","124","4","4","da rigyawa ta kwashe mu, da ambaliya ta rufe mu. ");
INSERT INTO hausa_vpl VALUES ("PS124_5","020_124_5","PSA","124","5","5","Da ruwa mai hauka ya share mu ƙaf. ");
INSERT INTO hausa_vpl VALUES ("PS124_6","020_124_6","PSA","124","6","6","Yabo ya tabbata ga Ubangiji, wanda bai bari aka yayyage mu da haƙoransu ba. ");
INSERT INTO hausa_vpl VALUES ("PS124_7","020_124_7","PSA","124","7","7","Mun tsira kamar tsuntsu daga tarkon mai farauta; an tsinke tarko, muka kuwa tsira. ");
INSERT INTO hausa_vpl VALUES ("PS124_8","020_124_8","PSA","124","8","8","Taimakonmu yana a sunan Ubangiji, Wanda ya yi sama da ƙasa. ");
INSERT INTO hausa_vpl VALUES ("PS125_1","020_125_1","PSA","125","1","1","Waƙar haurawa. Waɗanda suke dogara ga Ubangiji suna kama da Dutsen Sihiyona, wanda ba ya jijjiguwa amma dawwammame ne har abada. ");
INSERT INTO hausa_vpl VALUES ("PS125_2","020_125_2","PSA","125","2","2","Kamar duwatsun da sun kewaye Urushalima, haka Ubangiji ya kewaye mutanensa yanzu da har abada kuma. ");
INSERT INTO hausa_vpl VALUES ("PS125_3","020_125_3","PSA","125","3","3","Sandar mulkin mugaye ba zai ci gaba da kasance a kan ƙasar da take rabon adalai ba, domin kada masu adalci su yi amfani da hannuwansu su aikata mugunta. ");
INSERT INTO hausa_vpl VALUES ("PS125_4","020_125_4","PSA","125","4","4","Ka yi alheri, ya Ubangiji, ga waɗanda suke nagartattu, ga waɗanda suke masu aikata gaskiya a zuciyarsu. ");
INSERT INTO hausa_vpl VALUES ("PS125_5","020_125_5","PSA","125","5","5","Amma waɗanda suka juye ga karkatattun hanyoyi Ubangiji zai kore su tare da masu aikata mugunta. Salama tă kasance tare da Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS126_1","020_126_1","PSA","126","1","1","Waƙar haurawa. Sa’ad da Ubangiji ya dawo da kamammu zuwa Sihiyona, mun kasance kamar mutanen da suka yi mafarki. ");
INSERT INTO hausa_vpl VALUES ("PS126_2","020_126_2","PSA","126","2","2","Bakunanmu sun cika da dariya, harsunanmu da waƙoƙin farin ciki. Sai ana faɗi a cikin al’ummai, “Ubangiji ya aikata manyan abubuwa dominsu.” ");
INSERT INTO hausa_vpl VALUES ("PS126_3","020_126_3","PSA","126","3","3","Ubangiji ya aikata manyan abubuwa dominmu, mun kuwa cika da farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS126_4","020_126_4","PSA","126","4","4","Ka maido da wadatarmu, ya Ubangiji kamar rafuffuka a Negeb. ");
INSERT INTO hausa_vpl VALUES ("PS126_5","020_126_5","PSA","126","5","5","Waɗanda suka yi shuka da hawaye za su yi girbi da waƙoƙin farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS126_6","020_126_6","PSA","126","6","6","Shi da ya fita yana kuka, riƙe da iri don shuki, zai dawo da waƙoƙin farin ciki, ɗauke da dammuna. ");
INSERT INTO hausa_vpl VALUES ("PS127_1","020_127_1","PSA","127","1","1","Waƙar haurawa. Ta Solomon. In ba Ubangiji ne ya gina gida ba, masu gininta suna wahala a banza ne. In ba Ubangiji ne yake tsaron birni ba, masu tsaro suna yin tsaro a banza. ");
INSERT INTO hausa_vpl VALUES ("PS127_2","020_127_2","PSA","127","2","2","Banza ne ka farka da wuri ka koma da latti, kana fama don abincin da za ka ci, gama yakan ba da barci ga waɗanda yake ƙauna. ");
INSERT INTO hausa_vpl VALUES ("PS127_3","020_127_3","PSA","127","3","3","’Ya’ya maza gādo ne daga Ubangiji, yara lada ne daga gare shi. ");
INSERT INTO hausa_vpl VALUES ("PS127_4","020_127_4","PSA","127","4","4","Kamar kibiyoyi a hannun jarumi haka ’ya’ya mazan da aka haifa wa mutum a ƙuruciya. ");
INSERT INTO hausa_vpl VALUES ("PS127_5","020_127_5","PSA","127","5","5","Mai albarka ne mutumin da korinsa sun cika da su. Ba za a kunyata su ba sa’ad da suke ƙarawa da abokan gābansu a ɗakin shari’a. ");
INSERT INTO hausa_vpl VALUES ("PS128_1","020_128_1","PSA","128","1","1","Waƙar haurawa. Masu albarka ne dukan masu tsoron Ubangiji, waɗanda suke tafiya a hanyoyinsa. ");
INSERT INTO hausa_vpl VALUES ("PS128_2","020_128_2","PSA","128","2","2","Za ka ci amfanin aikinka; albarku da wadata za su zama naka. ");
INSERT INTO hausa_vpl VALUES ("PS128_3","020_128_3","PSA","128","3","3","Matarka za tă zama kamar kuringar inabi mai ’ya’ya a cikin gidanka; ’ya’yanka maza za su zama kamar tohon zaitun kewaye da teburinka. ");
INSERT INTO hausa_vpl VALUES ("PS128_4","020_128_4","PSA","128","4","4","Ta haka mai albarka yake wanda yake tsoron Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS128_5","020_128_5","PSA","128","5","5","Bari Ubangiji ya albarkace ka daga Sihiyona dukan kwanakin ranka; bari ka ga wadatar Urushalima, ");
INSERT INTO hausa_vpl VALUES ("PS128_6","020_128_6","PSA","128","6","6","bari kuma ka rayu ka ga ’ya’ya ’ya’yanka. Salama tă kasance tare da Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS129_1","020_129_1","PSA","129","1","1","Waƙar haurawa. Sun yi mini danniya ƙwarai tun ina ƙarami, bari Isra’ila yă ce, ");
INSERT INTO hausa_vpl VALUES ("PS129_2","020_129_2","PSA","129","2","2","sun yi mini danniya ƙwarai tun ina ƙarami, amma ba su yi nasara a kaina ba. ");
INSERT INTO hausa_vpl VALUES ("PS129_3","020_129_3","PSA","129","3","3","Manoma sun nome bayana suka yi kunyoyinsu da tsayi. ");
INSERT INTO hausa_vpl VALUES ("PS129_4","020_129_4","PSA","129","4","4","Amma Ubangiji mai adalci ne; ya ’yantar da ni daga igiyoyin mugaye. ");
INSERT INTO hausa_vpl VALUES ("PS129_5","020_129_5","PSA","129","5","5","Bari dukan waɗanda suke ƙin Sihiyona a juye da su baya da kunya. ");
INSERT INTO hausa_vpl VALUES ("PS129_6","020_129_6","PSA","129","6","6","Bari su zama kamar ciyawa a kan rufi, wadda takan bushe kafin tă yi girma; ");
INSERT INTO hausa_vpl VALUES ("PS129_7","020_129_7","PSA","129","7","7","da ita mai girbi ba ya iya cika hannuwansa, balle wanda yake tarawa yă cika hannuwansa. ");
INSERT INTO hausa_vpl VALUES ("PS129_8","020_129_8","PSA","129","8","8","Kada masu wuce su ce, “Albarkar Ubangiji ta kasance a kanku; muna sa muku albarka a cikin sunan Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("PS130_1","020_130_1","PSA","130","1","1","Waƙar haurawa. Daga cikin zurfafa na yi kuka gare ka, ya Ubangiji; ");
INSERT INTO hausa_vpl VALUES ("PS130_2","020_130_2","PSA","130","2","2","Ya Ubangiji, ka ji muryata. Bari kunnuwanka su saurara ga kukata ta neman jinƙai. ");
INSERT INTO hausa_vpl VALUES ("PS130_3","020_130_3","PSA","130","3","3","In kai, ya Ubangiji, za ka lissafta zunubai, Ya Ubangiji, wa zai tsaya? ");
INSERT INTO hausa_vpl VALUES ("PS130_4","020_130_4","PSA","130","4","4","Amma tare da kai akwai gafartawa, saboda haka ake tsoronka. ");
INSERT INTO hausa_vpl VALUES ("PS130_5","020_130_5","PSA","130","5","5","Zan jira Ubangiji, raina zai jira, kuma a cikin maganarsa na sa zuciyata. ");
INSERT INTO hausa_vpl VALUES ("PS130_6","020_130_6","PSA","130","6","6","Raina na jiran Ubangiji fiye da yadda mai tsaro yakan jira safiya, fiye da yadda mai tsaro yakan jira safiya. ");
INSERT INTO hausa_vpl VALUES ("PS130_7","020_130_7","PSA","130","7","7","Ya Isra’ila, sa zuciya ga Ubangiji, gama tare da Ubangiji akwai ƙauna marar ƙarewa kuma tare da shi akwai cikakkiyar fansa. ");
INSERT INTO hausa_vpl VALUES ("PS130_8","020_130_8","PSA","130","8","8","Shi kansa zai fanshi Isra’ila daga dukan zunubansu. ");
INSERT INTO hausa_vpl VALUES ("PS131_1","020_131_1","PSA","131","1","1","Waƙar haurawa. Ta Dawuda. Zuciyata ba mai girman kai ba ce, ya Ubangiji, idanuna ba sa fariya; ban dami kaina da manyan al’amura ba ko abubuwan da suka sha ƙarfina. ");
INSERT INTO hausa_vpl VALUES ("PS131_2","020_131_2","PSA","131","2","2","Amma na haƙura na kuma kwantar da raina; kamar yaron da aka yaye tare da mahaifiyarsa, kamar yaron da aka yaye haka raina yake a cikina. ");
INSERT INTO hausa_vpl VALUES ("PS131_3","020_131_3","PSA","131","3","3","Ya Isra’ila, sa zuciyarka ga Ubangiji yanzu da har abada kuma. ");
INSERT INTO hausa_vpl VALUES ("PS132_1","020_132_1","PSA","132","1","1","Waƙar haurawa. Ya Ubangiji, ka tuna da Dawuda da kuma dukan irin wuyan da ya jimre. ");
INSERT INTO hausa_vpl VALUES ("PS132_2","020_132_2","PSA","132","2","2","Ya yi rantsuwa ga Ubangiji ya kuma yi alkawari ga Maɗaukaki na Yaƙub cewa, ");
INSERT INTO hausa_vpl VALUES ("PS132_3","020_132_3","PSA","132","3","3","“Ba zan shiga gidana ko in kwanta a gado ba, ");
INSERT INTO hausa_vpl VALUES ("PS132_4","020_132_4","PSA","132","4","4","ba zan ba wa idanuna barci ba, ba gyangyaɗi wa idanuna, ");
INSERT INTO hausa_vpl VALUES ("PS132_5","020_132_5","PSA","132","5","5","sai na sami wuri wa Ubangiji, mazauni domin Maɗaukaki na Yaƙub.” ");
INSERT INTO hausa_vpl VALUES ("PS132_6","020_132_6","PSA","132","6","6","Mun ji haka a Efrata, muka yi ƙaro da shi a filayen Ya’ar, ");
INSERT INTO hausa_vpl VALUES ("PS132_7","020_132_7","PSA","132","7","7","“Bari mu tafi wurin zamansa; bari mu yi sujada a wurin sa ƙafafunsa, ");
INSERT INTO hausa_vpl VALUES ("PS132_8","020_132_8","PSA","132","8","8","ka tashi, ya Ubangiji, ka kuma zo wurin hutunka, kai da akwatin alkawarin ƙarfinka. ");
INSERT INTO hausa_vpl VALUES ("PS132_9","020_132_9","PSA","132","9","9","Bari a suturta firistocinka da adalci; bari tsarkakanka su rera don farin ciki.” ");
INSERT INTO hausa_vpl VALUES ("PS132_10","020_132_10","PSA","132","10","10","Saboda Dawuda bawanka, kada ka ƙi shafaffenka. ");
INSERT INTO hausa_vpl VALUES ("PS132_11","020_132_11","PSA","132","11","11","Ubangiji ya rantse wa Dawuda tabbataccen rantsuwa cewa ba zai janye ba cewa, “Ɗaya daga cikin zuriyarka zan sa a kan kursiyinka, ");
INSERT INTO hausa_vpl VALUES ("PS132_12","020_132_12","PSA","132","12","12","in ’ya’yanka maza za su kiyaye alkawari da farillan da na koya musu, to ’ya’yansu maza za su zauna a kan kursiyinka har abada abadin.” ");
INSERT INTO hausa_vpl VALUES ("PS132_13","020_132_13","PSA","132","13","13","Gama Ubangiji ya zaɓi Sihiyona, ya so ta zama mazauninsa, ");
INSERT INTO hausa_vpl VALUES ("PS132_14","020_132_14","PSA","132","14","14","“Wannan shi ne wurin hutuna har abada abadin; a nan zan zauna ina mulki gama ina son ta, ");
INSERT INTO hausa_vpl VALUES ("PS132_15","020_132_15","PSA","132","15","15","zan albarkace ta da tanade-tanade masu yawa; matalautanta za su ƙoshi da abinci. ");
INSERT INTO hausa_vpl VALUES ("PS132_16","020_132_16","PSA","132","16","16","Zan suturta firistocinta da ceto, tsarkakanta kuma kullum za su rera don farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS132_17","020_132_17","PSA","132","17","17","“A nan zan sa ƙaho ya yi girma wa Dawuda in kuma kafa fitila saboda shafaffena. ");
INSERT INTO hausa_vpl VALUES ("PS132_18","020_132_18","PSA","132","18","18","Zan suturta abokan gābansa da kunya, amma rawanin da yake a kansa zai yi ta walƙiya.” ");
INSERT INTO hausa_vpl VALUES ("PS133_1","020_133_1","PSA","133","1","1","Waƙar haurawa. Ta Dawuda. Abu mai kyau ne, mai daɗi kuma sa’ad da ’yan’uwa suna zaman lafiya! ");
INSERT INTO hausa_vpl VALUES ("PS133_2","020_133_2","PSA","133","2","2","Yana kamar mai mai darajar da aka zuba a kai, yana gangarawa a gemu, yana gangarawa a gemun Haruna, har zuwa wuyan rigunansa. ");
INSERT INTO hausa_vpl VALUES ("PS133_3","020_133_3","PSA","133","3","3","Yana kamar raɓar Hermon da take zubowa a kan Dutsen Sihiyona. Gama a can Ubangiji ya tabbatar da albarkarsa, har ma rai na har abada. ");
INSERT INTO hausa_vpl VALUES ("PS134_1","020_134_1","PSA","134","1","1","Waƙar haurawa. Yabi Ubangiji, dukanku bayin Ubangiji waɗanda kuke hidima da dare a gidan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS134_2","020_134_2","PSA","134","2","2","Ku tā da hannuwanku a cikin wurinsa mai tsarki ku kuma yabi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS134_3","020_134_3","PSA","134","3","3","Bari Ubangiji, Mahaliccin sama da ƙasa, ya albarkace ku daga Sihiyona. ");
INSERT INTO hausa_vpl VALUES ("PS135_1","020_135_1","PSA","135","1","1","Yabi Ubangiji. Yabi sunan Ubangiji; yabe shi, ku bayin Ubangiji, ");
INSERT INTO hausa_vpl VALUES ("PS135_2","020_135_2","PSA","135","2","2","ku waɗanda kuke hidima a gidan Ubangiji, cikin filayen gidan Allahnmu. ");
INSERT INTO hausa_vpl VALUES ("PS135_3","020_135_3","PSA","135","3","3","Yabi Ubangiji, gama Ubangiji nagari ne; rera yabo ga sunansa, gama wannan yana da kyau. ");
INSERT INTO hausa_vpl VALUES ("PS135_4","020_135_4","PSA","135","4","4","Gama Ubangiji ya zaɓi Yaƙub ya zama nasa, Isra’ila ya zama mallakarsa mai daraja. ");
INSERT INTO hausa_vpl VALUES ("PS135_5","020_135_5","PSA","135","5","5","Na san cewa Ubangiji yana da girma, cewa shugabanmu ya fi dukan alloli girma. ");
INSERT INTO hausa_vpl VALUES ("PS135_6","020_135_6","PSA","135","6","6","Ubangiji yana yin abin da ya ga dama, a sammai da kuma a duniya, cikin tekuna da kuma cikin dukan zurfafansu. ");
INSERT INTO hausa_vpl VALUES ("PS135_7","020_135_7","PSA","135","7","7","Yakan sa gizagizai su taso daga iyakokin duniya; yakan aika da walƙiya tare da ruwan sama ya fito da iska daga ɗakunan ajiyarsa. ");
INSERT INTO hausa_vpl VALUES ("PS135_8","020_135_8","PSA","135","8","8","Ya kashe ’ya’yan fari na Masar, ’ya’yan fari na mutane da na dabbobi. ");
INSERT INTO hausa_vpl VALUES ("PS135_9","020_135_9","PSA","135","9","9","Ya aiko da alamu da abubuwan banmamaki a tsirkiyarku, ya Masar, a kan Fir’auna da kuma dukan bayinsa. ");
INSERT INTO hausa_vpl VALUES ("PS135_10","020_135_10","PSA","135","10","10","Ya bugi al’ummai masu yawa ya kuma karkashe manyan sarakuna, ");
INSERT INTO hausa_vpl VALUES ("PS135_11","020_135_11","PSA","135","11","11","Sihon sarkin Amoriyawa, Og sarkin Bashan da kuma dukan sarakunan Kan’ana, ");
INSERT INTO hausa_vpl VALUES ("PS135_12","020_135_12","PSA","135","12","12","ya kuma ba da ƙasarsa kamar abin gādo, abin gādo ga mutanensa Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS135_13","020_135_13","PSA","135","13","13","Sunanka, ya Ubangiji, dawwammame ne har abada, sanin da aka yi maka, ya Ubangiji, yana nan cikin dukan zamanai. ");
INSERT INTO hausa_vpl VALUES ("PS135_14","020_135_14","PSA","135","14","14","Gama Ubangiji zai nuna cewa mutanensa ba su da laifi ya kuma ji tausayin bayinsa. ");
INSERT INTO hausa_vpl VALUES ("PS135_15","020_135_15","PSA","135","15","15","Gumakan al’ummai azurfa ne da zinariya, da hannuwan mutane suka yi. ");
INSERT INTO hausa_vpl VALUES ("PS135_16","020_135_16","PSA","135","16","16","Suna da bakuna, amma ba sa magana, idanu, amma ba sa gani; ");
INSERT INTO hausa_vpl VALUES ("PS135_17","020_135_17","PSA","135","17","17","suna da kunnuwa, amma ba sa ji, ba kuwa numfashi a bakunansu. ");
INSERT INTO hausa_vpl VALUES ("PS135_18","020_135_18","PSA","135","18","18","Waɗanda suka yi su za su zama kamar su, haka kuma zai zama da dukan waɗanda suke dogara gare su. ");
INSERT INTO hausa_vpl VALUES ("PS135_19","020_135_19","PSA","135","19","19","Ya gidan Isra’ila, yabi Ubangiji; Ya gidan Haruna, yabi Ubangiji; ");
INSERT INTO hausa_vpl VALUES ("PS135_20","020_135_20","PSA","135","20","20","Ya gidan Lawi, yabi Ubangiji; ku da kuke tsoronsa, yabi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS135_21","020_135_21","PSA","135","21","21","Yabo ya tabbata ga Ubangiji daga Sihiyona, gare shi wanda yake zama a Urushalima. Yabi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS136_1","020_136_1","PSA","136","1","1","Ku yi godiya ga Ubangiji, gama nagari ne shi. Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_2","020_136_2","PSA","136","2","2","Ku yi godiya ga Allahn alloli. Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_3","020_136_3","PSA","136","3","3","Ku yi godiya ga Ubangijin iyayengiji. Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_4","020_136_4","PSA","136","4","4","Gare shi wanda shi kaɗai yake aikata abubuwan banmamaki, Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_5","020_136_5","PSA","136","5","5","Wanda ta wurin ganewarsa ya yi sammai, Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_6","020_136_6","PSA","136","6","6","Wanda ya shimfiɗa duniya a kan ruwaye, Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_7","020_136_7","PSA","136","7","7","Wanda ya yi manyan haskoki, Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_8","020_136_8","PSA","136","8","8","Rana don tă yi mulkin yini, Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_9","020_136_9","PSA","136","9","9","Wata da taurari kuma don su yi mulkin dare; Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_10","020_136_10","PSA","136","10","10","Gare shi wanda ya kashe ’ya’yan fari Masar Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_11","020_136_11","PSA","136","11","11","Ya kuma fitar da Isra’ila daga cikinsu Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_12","020_136_12","PSA","136","12","12","Da hannu mai ƙarfi da hannu mai iko; Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_13","020_136_13","PSA","136","13","13","Gare shi wanda ya raba Jan Teku biyu Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_14","020_136_14","PSA","136","14","14","Ya kawo Isra’ila ta tsakiyarsa, Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_15","020_136_15","PSA","136","15","15","Amma ya share Fir’auna da mayaƙansa cikin Jan Teku; Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_16","020_136_16","PSA","136","16","16","Gare shi wanda ya bi da mutanensa cikin hamada, Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_17","020_136_17","PSA","136","17","17","Wanda ya buge manyan sarakuna, Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_18","020_136_18","PSA","136","18","18","Ya karkashe manyan sarakuna, Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_19","020_136_19","PSA","136","19","19","Sihon sarkin Amoriyawa Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_20","020_136_20","PSA","136","20","20","Da kuma Og sarkin Bashan, Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_21","020_136_21","PSA","136","21","21","Ya kuma ba da ƙasarsu gādo, Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_22","020_136_22","PSA","136","22","22","Gādo ga bawansa Isra’ila; Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_23","020_136_23","PSA","136","23","23","Shi wanda ya tuna da mu cikin ƙasƙancinmu Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_24","020_136_24","PSA","136","24","24","Ya kuma ’yantar da mu daga abokan gābanmu, Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_25","020_136_25","PSA","136","25","25","Wanda kuma ke ba da abinci ga kowace halitta. Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS136_26","020_136_26","PSA","136","26","26","Ku yi godiya ga Allah na sama. Ƙaunarsa madawwamiya ce. ");
INSERT INTO hausa_vpl VALUES ("PS137_1","020_137_1","PSA","137","1","1","A bakin kogunan Babilon muka zauna muka yi kuka sa’ad da muka tuna da Sihiyona. ");
INSERT INTO hausa_vpl VALUES ("PS137_2","020_137_2","PSA","137","2","2","A can a kan rassan itatuwa muka rataye garayunmu, ");
INSERT INTO hausa_vpl VALUES ("PS137_3","020_137_3","PSA","137","3","3","gama a can masu kamunmu suka sa mu yi waƙoƙi, masu ba mu azaba suka nema waƙoƙin farin ciki; suka ce, “Ku rera mana ɗaya daga cikin waƙoƙin Sihiyona!” ");
INSERT INTO hausa_vpl VALUES ("PS137_4","020_137_4","PSA","137","4","4","Yaya za mu rera waƙoƙin Ubangiji a baƙuwar ƙasa? ");
INSERT INTO hausa_vpl VALUES ("PS137_5","020_137_5","PSA","137","5","5","In na manta da ke, ya Urushalima, bari hannuna na dama manta da iyawarsa. ");
INSERT INTO hausa_vpl VALUES ("PS137_6","020_137_6","PSA","137","6","6","Bari harshena yă manne wa rufin bakina in ban tuna da ke ba, in ban so Urushalima farin cikin mafi girma ba. ");
INSERT INTO hausa_vpl VALUES ("PS137_7","020_137_7","PSA","137","7","7","Ka tuna, ya Ubangiji, abin da mutanen Edom suka yi a ranar da Urushalima ta fāɗi. Suka yi ihu suka ce, “A ragargaza ta, A ragargaza ta har tushenta!” ");
INSERT INTO hausa_vpl VALUES ("PS137_8","020_137_8","PSA","137","8","8","Ya Diyar Babilon, an ƙaddara ke zuwa hallaka, mai farin ciki ne wanda ya sāka miki saboda abin da kika yi mana, ");
INSERT INTO hausa_vpl VALUES ("PS137_9","020_137_9","PSA","137","9","9","shi da ya ƙwace jariranki ya fyaɗa su a kan duwatsu. ");
INSERT INTO hausa_vpl VALUES ("PS138_1","020_138_1","PSA","138","1","1","Ta Dawuda. Zan yabe ka, ya Ubangiji, da dukan zuciyata; a gaban “alloli” zan rera yabo. ");
INSERT INTO hausa_vpl VALUES ("PS138_2","020_138_2","PSA","138","2","2","Zan rusuna ta wajen haikalinka mai tsarki zan kuma yabi sunanka saboda ƙaunarka da amincinka, saboda ka ɗaukaka a bisa kome sunanka da kuma maganarka. ");
INSERT INTO hausa_vpl VALUES ("PS138_3","020_138_3","PSA","138","3","3","Sa’ad da na kira, ka amsa mini; ka sa na zama mai ƙarfin hali ka kuma ƙarfafa ni. ");
INSERT INTO hausa_vpl VALUES ("PS138_4","020_138_4","PSA","138","4","4","Bari dukan sarakunan duniya su yabe ka, ya Ubangiji, sa’ad da suka ji maganganun bakinka. ");
INSERT INTO hausa_vpl VALUES ("PS138_5","020_138_5","PSA","138","5","5","Bari su rera game da hanyoyin Ubangiji, gama ɗaukakar Ubangiji da girma take. ");
INSERT INTO hausa_vpl VALUES ("PS138_6","020_138_6","PSA","138","6","6","Ko da yake Ubangiji yana bisa, yakan dubi kāsassu, amma tun da nesa ya san masu girman kai. ");
INSERT INTO hausa_vpl VALUES ("PS138_7","020_138_7","PSA","138","7","7","Ko da na yi tafiya a tsakiyar wahala, kana kiyaye raina; ka miƙa hannunka a kan fushin maƙiyana, da hannunka na dama ka cece ni. ");
INSERT INTO hausa_vpl VALUES ("PS138_8","020_138_8","PSA","138","8","8","Ubangiji zai cika manufarsa a kaina; ƙaunarka, ya Ubangiji, madawwamiya ce har abada, kada ka ƙyale ayyukan hannuwanka. ");
INSERT INTO hausa_vpl VALUES ("PS139_1","020_139_1","PSA","139","1","1","Don mai bi da kaɗe-kaɗe. Ta Dawuda. Zabura ce. Ya Ubangiji, ka bincike ni ka kuwa san ni. ");
INSERT INTO hausa_vpl VALUES ("PS139_2","020_139_2","PSA","139","2","2","Ka san sa’ad da na zauna da sa’ad da na tashi; ka san tunanina daga nesa. ");
INSERT INTO hausa_vpl VALUES ("PS139_3","020_139_3","PSA","139","3","3","Ka san fitata da kuma kwanciyata; ka saba da dukan hanyoyina. ");
INSERT INTO hausa_vpl VALUES ("PS139_4","020_139_4","PSA","139","4","4","Kafin in yi magana da harshena ka santa gaba ɗaya, ya Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS139_5","020_139_5","PSA","139","5","5","Ka kewaye ni, gaba da baya; ka sa hannunka a kaina. ");
INSERT INTO hausa_vpl VALUES ("PS139_6","020_139_6","PSA","139","6","6","Irin wannan sanin game da ni ya fi ƙarfin magana, ya fi ƙarfi in gane. ");
INSERT INTO hausa_vpl VALUES ("PS139_7","020_139_7","PSA","139","7","7","Ina zan tafi daga Ruhunka? Ina zan gudu in tafi daga gabanka? ");
INSERT INTO hausa_vpl VALUES ("PS139_8","020_139_8","PSA","139","8","8","In na haura zuwa sammai, kana a can; in na yi gado a zurfafa, kana a can. ");
INSERT INTO hausa_vpl VALUES ("PS139_9","020_139_9","PSA","139","9","9","In na tashi a fikafikan safiya, in na sauka a gefe mai nisa na teku, ");
INSERT INTO hausa_vpl VALUES ("PS139_10","020_139_10","PSA","139","10","10","can ma hannunka zai bishe ni, hannunka na dama zai riƙe ni gam. ");
INSERT INTO hausa_vpl VALUES ("PS139_11","020_139_11","PSA","139","11","11","In na ce, “Tabbatacce duhu zai ɓoye ni haske kuma zai zama dare kewaye da ni,” ");
INSERT INTO hausa_vpl VALUES ("PS139_12","020_139_12","PSA","139","12","12","duhu ma ba zai zama duhu gare ka ba; dare zai haskaka kamar rana, gama duhu ya yi kamar haske gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS139_13","020_139_13","PSA","139","13","13","Gama ka halicci ciki-cikina; ka gina ni gaba ɗaya a cikin mahaifar mahaifiyata. ");
INSERT INTO hausa_vpl VALUES ("PS139_14","020_139_14","PSA","139","14","14","Ina yabonka domin yadda ka yi ni abin tsoro ne da kuma abin mamaki; ayyukanka suna da banmamaki, na san da haka sosai. ");
INSERT INTO hausa_vpl VALUES ("PS139_15","020_139_15","PSA","139","15","15","Ƙasusuwana ba a ɓoye suke a gare ka ba sa’ad da aka yi ni asirce. Sa’ad da saƙa ni gaba ɗaya a zurfafan duniya. ");
INSERT INTO hausa_vpl VALUES ("PS139_16","020_139_16","PSA","139","16","16","Idanunka sun ga jikina marar fasali; dukan kwanakin da aka tsara mini a rubuce suke a littafinka kafin ɗayansu yă kasance. ");
INSERT INTO hausa_vpl VALUES ("PS139_17","020_139_17","PSA","139","17","17","Tunaninka suna da daraja gare ni, ya Allah! Yawansu ba su da iyaka! ");
INSERT INTO hausa_vpl VALUES ("PS139_18","020_139_18","PSA","139","18","18","A ce zan iya ƙirgansu, za su fi yashin teku yawa. Sa’ad da na farka, ina nan tare da kai har yanzu. ");
INSERT INTO hausa_vpl VALUES ("PS139_19","020_139_19","PSA","139","19","19","Da kawai za ka kashe mugaye, ya Allah! Ku rabu da ni, ku masu kisankai! ");
INSERT INTO hausa_vpl VALUES ("PS139_20","020_139_20","PSA","139","20","20","Suna magana game da kai da mugun nufi; maƙiyanka suna ɗaukan sunanka a banza. ");
INSERT INTO hausa_vpl VALUES ("PS139_21","020_139_21","PSA","139","21","21","Ba ina ƙin masu ƙinka ba, ya Ubangiji, ina kuma ƙyamar waɗanda suke tayar maka ba? ");
INSERT INTO hausa_vpl VALUES ("PS139_22","020_139_22","PSA","139","22","22","Ba ni da wani abu da nake musu sai kiyaye kawai; na ɗauke su abokan gābana. ");
INSERT INTO hausa_vpl VALUES ("PS139_23","020_139_23","PSA","139","23","23","Ka bincike ni, ya Allah ka kuma san zuciyata; ka gwada ni ka kuma san damuwata. ");
INSERT INTO hausa_vpl VALUES ("PS139_24","020_139_24","PSA","139","24","24","Duba ko akwai wani laifi a cikina, ka bishe ni a madawwamiyar hanya. ");
INSERT INTO hausa_vpl VALUES ("PS140_1","020_140_1","PSA","140","1","1","Don mai bi da kaɗe-kaɗe. Zabura ta Dawuda. Ka cece ni, ya Ubangiji, daga mugaye; ka tsare ni daga mutane masu rikici, ");
INSERT INTO hausa_vpl VALUES ("PS140_2","020_140_2","PSA","140","2","2","masu shirya maƙarƙashiya a zukatansu suna kuma kawo yaƙi kullum. ");
INSERT INTO hausa_vpl VALUES ("PS140_3","020_140_3","PSA","140","3","3","Suna sa harsunansu su yi kaifi kamar na maciji; dafin gamsheƙa yana a leɓunansu. Sela ");
INSERT INTO hausa_vpl VALUES ("PS140_4","020_140_4","PSA","140","4","4","Ka kiyaye ni, ya Ubangiji, daga hannuwan mugaye; ka tsare ni daga mutane masu rikici waɗanda suke shirin kwashe ni a ƙafafu. ");
INSERT INTO hausa_vpl VALUES ("PS140_5","020_140_5","PSA","140","5","5","Masu girman kai sun sa mini tarko; sun shimfiɗa igiyoyin ragarsu sun kuma shirya mini tarko a hanyata. Sela ");
INSERT INTO hausa_vpl VALUES ("PS140_6","020_140_6","PSA","140","6","6","Ya Ubangiji, na ce maka, “Kai ne Allahna.” Ka ji kukata ta neman jinƙai, ya Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS140_7","020_140_7","PSA","140","7","7","Ya Ubangiji Mai Iko Duka, mai fansana mai ƙarfi, wanda yake garkuwoyin kaina a ranar yaƙi. ");
INSERT INTO hausa_vpl VALUES ("PS140_8","020_140_8","PSA","140","8","8","Kada ka biya wa mugaye bukatunsu, ya Ubangiji; kada ka bar shirinsu su yi nasara, in ba haka ba za su yi fariya. Sela ");
INSERT INTO hausa_vpl VALUES ("PS140_9","020_140_9","PSA","140","9","9","Bari kawunan waɗanda suka kewaye ni su rufu da masifun da leɓunansu suka jawo. ");
INSERT INTO hausa_vpl VALUES ("PS140_10","020_140_10","PSA","140","10","10","Bari garwashin wuta yă zubo a kansu; bari a jefar da su cikin wuta, cikin rami mai zurfi, kada su sāke tashi. ");
INSERT INTO hausa_vpl VALUES ("PS140_11","020_140_11","PSA","140","11","11","Kada masu ɓata suna su taɓa kahu a ƙasar; bari masifa ta farauci mutane masu rikici. ");
INSERT INTO hausa_vpl VALUES ("PS140_12","020_140_12","PSA","140","12","12","Na san cewa Ubangiji ya shirya wa matalauta adalci yana kuma yi wa mabukata adalci. ");
INSERT INTO hausa_vpl VALUES ("PS140_13","020_140_13","PSA","140","13","13","Tabbatacce masu adalci za su yabi sunanka masu aikata gaskiya kuma za su zauna a gabanka. ");
INSERT INTO hausa_vpl VALUES ("PS141_1","020_141_1","PSA","141","1","1","Zabura ta Dawuda. Na yi kira gare ka, ya Ubangiji; ka zo da sauri. Ka ji muryata sa’ad da na yi kira. ");
INSERT INTO hausa_vpl VALUES ("PS141_2","020_141_2","PSA","141","2","2","Bari a sa addu’ata a gabanka kamar turaren ƙonawa; bari ɗagawa hannuwana ta zama kamar hadayar yamma. ");
INSERT INTO hausa_vpl VALUES ("PS141_3","020_141_3","PSA","141","3","3","Ka sa mai tsaro a bakina, ya Ubangiji; ka yi tsaron ƙofar leɓunana. ");
INSERT INTO hausa_vpl VALUES ("PS141_4","020_141_4","PSA","141","4","4","Kada ka bar zuciyata ta juya ga yin abin da yake mugu, ta sa kai ga aikata mugayen ayyuka tare da mutane masu aikata mugunta; kada ka bari in ci abincinsu. ");
INSERT INTO hausa_vpl VALUES ("PS141_5","020_141_5","PSA","141","5","5","Bari mutum mai adalci yă buge ni, alheri ne; bar shi yă tsawata mini, mai ne a kaina. Kaina ba zai ƙi shi ba, duk da haka addu’ata kullum tana gāba da mugayen ayyuka. ");
INSERT INTO hausa_vpl VALUES ("PS141_6","020_141_6","PSA","141","6","6","Za a jefar da masu mulkinsu ƙasa daga ƙwanƙolin dutse, mugaye kuwa za su san cewa maganata daidai ne. ");
INSERT INTO hausa_vpl VALUES ("PS141_7","020_141_7","PSA","141","7","7","Za su ce, “Kamar yadda mutum kan yi huda yă tsage ƙasa, haka aka watsar da ƙasusuwanmu a bakin kabari.” ");
INSERT INTO hausa_vpl VALUES ("PS141_8","020_141_8","PSA","141","8","8","Amma na kafa idanuna a kanka, ya Ubangiji Mai Iko Duka; a cikinka ina neman mafaka, kada ka miƙa ni ga mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PS141_9","020_141_9","PSA","141","9","9","Ka kiyaye ni daga tarkon da aka sa mini, daga tarkon da mugaye suka sa. ");
INSERT INTO hausa_vpl VALUES ("PS141_10","020_141_10","PSA","141","10","10","Bari mugaye su fāɗa a cikin ragarsu, amma bari ni in zo in wuce lafiya. ");
INSERT INTO hausa_vpl VALUES ("PS142_1","020_142_1","PSA","142","1","1","Maskil ne ta Dawuda. Sa’ad da yake cikin kogo. Addu’a ce. Na yi kuka mai ƙarfi ga Ubangiji; na tā da muryata ga Ubangiji neman jinƙai. ");
INSERT INTO hausa_vpl VALUES ("PS142_2","020_142_2","PSA","142","2","2","Na kawo gunagunina a gabansa; a gabansa na faɗa wahalata. ");
INSERT INTO hausa_vpl VALUES ("PS142_3","020_142_3","PSA","142","3","3","Sa’ad da ƙarfina ya kāre a cikina, kai ne wanda ya san hanyata. A hanyar da nake tafiya mutane sun kafa mini tarko. ");
INSERT INTO hausa_vpl VALUES ("PS142_4","020_142_4","PSA","142","4","4","Duba ta damata ka gani; babu wanda ya kula da ni. Ba ni da mafaka; babu wanda ya kula da raina. ");
INSERT INTO hausa_vpl VALUES ("PS142_5","020_142_5","PSA","142","5","5","Na yi kuka gare ka, ya Ubangiji; Na ce, “Kai ne mafakata, rabona a ƙasar masu rai.” ");
INSERT INTO hausa_vpl VALUES ("PS142_6","020_142_6","PSA","142","6","6","Ka saurari kukata, gama ina cikin matsananciyar bukata; ka cece ni daga waɗanda suke fafarata, gama sun fi ni ƙarfi sosai. ");
INSERT INTO hausa_vpl VALUES ("PS142_7","020_142_7","PSA","142","7","7","Ka ’yantar da ni daga kurkuku, don in yabi sunanka. Ta haka masu adalci za su taru kewaye da ni saboda alherinka gare ni. ");
INSERT INTO hausa_vpl VALUES ("PS143_1","020_143_1","PSA","143","1","1","Zabura ta Dawuda. Ya Ubangiji, ka ji addu’ata, ka saurari kukata don neman jinƙai; cikin amincinka da adalcinka ka amsa mini. ");
INSERT INTO hausa_vpl VALUES ("PS143_2","020_143_2","PSA","143","2","2","Kada ka gabatar da bawanka a gaban shari’a, gama babu wani mai rai da yake adali a gabanka. ");
INSERT INTO hausa_vpl VALUES ("PS143_3","020_143_3","PSA","143","3","3","Abokin gāba yana fafarata, ya murƙushe ni har ƙasa; ya sa ina zama a cikin duhu kamar waɗanda suka mutu tun tuni. ");
INSERT INTO hausa_vpl VALUES ("PS143_4","020_143_4","PSA","143","4","4","Ta haka ƙarfina ya ƙare a cikina zuciyata ta damu ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("PS143_5","020_143_5","PSA","143","5","5","Na tuna da kwanakin baya na yi tunani a kan dukan ayyukanka na kuma lura da abin da hannuwanka suka yi. ");
INSERT INTO hausa_vpl VALUES ("PS143_6","020_143_6","PSA","143","6","6","Na buɗe hannuwana gare ka; raina yana jin ƙishinka kamar busasshiyar ƙasa. Sela ");
INSERT INTO hausa_vpl VALUES ("PS143_7","020_143_7","PSA","143","7","7","Ka amsa mini da sauri, ya Ubangiji; ƙarfina ya ƙare. Kada ka ɓoye fuskarka daga gare ni in ba haka ba zan zama kamar waɗanda suka gangara zuwa rami. ");
INSERT INTO hausa_vpl VALUES ("PS143_8","020_143_8","PSA","143","8","8","Bari safiya ta kawo mini maganar ƙaunarka marar ƙarewa, gama na sa zuciyata a gare ka. Ka nuna mini hanyar da zan bi, gama a gare ka na miƙa raina. ");
INSERT INTO hausa_vpl VALUES ("PS143_9","020_143_9","PSA","143","9","9","Ka cece ni daga abokan gābana, ya Ubangiji, gama na ɓoye kaina a gare ka. ");
INSERT INTO hausa_vpl VALUES ("PS143_10","020_143_10","PSA","143","10","10","Ka koya mini in yi nufinka, gama kai ne Allahna; bari nagarin Ruhunka yă bi da ni a ƙasar da ba gargaɗa. ");
INSERT INTO hausa_vpl VALUES ("PS143_11","020_143_11","PSA","143","11","11","Saboda sunanka, ya Ubangiji, ka kiyaye raina; a cikin adalcinka, ka fid da ni daga wahala. ");
INSERT INTO hausa_vpl VALUES ("PS143_12","020_143_12","PSA","143","12","12","A cikin ƙaunarka marar ƙarewa, ka rufe bakunan abokan gābana; ka hallaka dukan maƙiyana, gama ni bawanka ne. ");
INSERT INTO hausa_vpl VALUES ("PS144_1","020_144_1","PSA","144","1","1","Ta Dawuda. Yabo ya tabbata ga Ubangiji dutsena, wanda ya horar da hannuwana don yaƙi, yatsotsina don faɗa. ");
INSERT INTO hausa_vpl VALUES ("PS144_2","020_144_2","PSA","144","2","2","Shi ne Allah mai ƙaunata da kuma kagarata, katangata da mai cetona, garkuwata, wanda nake neman mafaka daga gare shi, wanda ya sa mutane a ƙarƙashina. ");
INSERT INTO hausa_vpl VALUES ("PS144_3","020_144_3","PSA","144","3","3","Ya Ubangiji, wane ne mutum da ka kula da shi, ɗan mutum da har za ka yi tunaninsa? ");
INSERT INTO hausa_vpl VALUES ("PS144_4","020_144_4","PSA","144","4","4","Mutum yana kama da numfashi; kwanakinsa suna wucewa kamar inuwa. ");
INSERT INTO hausa_vpl VALUES ("PS144_5","020_144_5","PSA","144","5","5","Ka tsage sammanka, ya Ubangiji, ka sauko; ka taɓa duwatsu, domin su yi hayaƙi. ");
INSERT INTO hausa_vpl VALUES ("PS144_6","020_144_6","PSA","144","6","6","Ka aiko da walƙiya ka watsar da abokan gāba; ka karɓa kibiyoyinka ka sa su gudu. ");
INSERT INTO hausa_vpl VALUES ("PS144_7","020_144_7","PSA","144","7","7","Ka miƙa hannunka daga bisa; ka cece ni ka kuma kuɓutar da ni daga manyan ruwaye, daga hannuwan baƙi ");
INSERT INTO hausa_vpl VALUES ("PS144_8","020_144_8","PSA","144","8","8","waɗanda bakunansu sun cika da ƙarya, waɗanda hannuwansu na dama masu ruɗu ne. ");
INSERT INTO hausa_vpl VALUES ("PS144_9","020_144_9","PSA","144","9","9","Zan rera sabuwar waƙa gare ka, ya Allah; a kan molo mai tsirkiya goma zan yi maka kiɗi, ");
INSERT INTO hausa_vpl VALUES ("PS144_10","020_144_10","PSA","144","10","10","ga Wannan wanda yake ba wa sarakuna nasara, wanda ya cece bawansa Dawuda. Daga takobin kisa. ");
INSERT INTO hausa_vpl VALUES ("PS144_11","020_144_11","PSA","144","11","11","Ka cece ni ka kuma kuɓutar da ni daga hannuwan baƙi waɗanda bakunansu sun cika da ƙarya, waɗanda hannuwansu na dama masu ruɗu ne. ");
INSERT INTO hausa_vpl VALUES ("PS144_12","020_144_12","PSA","144","12","12","Ta haka ’ya’yanmu maza a ƙuruciyarsu za su zama kamar tsire-tsiren da aka kula da su, ’ya’yanmu mata kuma za su zama kamar ginshiƙai da sassaƙa don adon fada. ");
INSERT INTO hausa_vpl VALUES ("PS144_13","020_144_13","PSA","144","13","13","Rumbunanmu za su cika da kowane irin tanadi. Tumakinmu za su ƙaru ninki dubu, ninki dubu goma-goma a filayenmu; ");
INSERT INTO hausa_vpl VALUES ("PS144_14","020_144_14","PSA","144","14","14","shanunmu za su ja kaya masu nauyi. Ba za a sami tashin hankali a katangarmu ba, ba zuwan zaman bauta, ba jin kukan damuwa a titunanmu. ");
INSERT INTO hausa_vpl VALUES ("PS144_15","020_144_15","PSA","144","15","15","Masu albarka ne mutanen da wannan zai zama haka; masu albarka ne mutanen da Allah ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS145_1","020_145_1","PSA","145","1","1","Zabura ce ta yabo. Ta Dawuda. Zan ɗaukaka ka, ya Allahna, Sarki; zan yabi sunanka har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("PS145_2","020_145_2","PSA","145","2","2","Kowace rana zan yabe ka in kuma ɗaukaka sunanka har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("PS145_3","020_145_3","PSA","145","3","3","Ubangiji da girma yake ya kuma cancanci yabo girmansa ya fi ƙarfin ganewar mutum. ");
INSERT INTO hausa_vpl VALUES ("PS145_4","020_145_4","PSA","145","4","4","Tsara guda za tă yi maganar ayyukanka ga wata tsara; za su yi magana game da manyan ayyukanka. ");
INSERT INTO hausa_vpl VALUES ("PS145_5","020_145_5","PSA","145","5","5","Za su yi zancen ɗaukakarka mai daraja, zan kuma yi tunani a kan ayyukanka masu banmamaki. ");
INSERT INTO hausa_vpl VALUES ("PS145_6","020_145_6","PSA","145","6","6","Za su yi magana game da ikon ayyukanka masu bantsoro, zan kuma yi shelar manyan ayyukanka. ");
INSERT INTO hausa_vpl VALUES ("PS145_7","020_145_7","PSA","145","7","7","Za su yi bikin yalwar alherinka suka kuma rera adalcinka da farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PS145_8","020_145_8","PSA","145","8","8","Ubangiji mai alheri da kuma tausayi, mai jinkirin fushi cike kuma da ƙauna. ");
INSERT INTO hausa_vpl VALUES ("PS145_9","020_145_9","PSA","145","9","9","Ubangiji nagari ne ga duka; yana tausayin dukan abubuwan da ya yi. ");
INSERT INTO hausa_vpl VALUES ("PS145_10","020_145_10","PSA","145","10","10","Dukan abubuwan da ka yi za su yabe ka, ya Ubangiji; tsarkakanka za su ɗaukaka ka. ");
INSERT INTO hausa_vpl VALUES ("PS145_11","020_145_11","PSA","145","11","11","Za su yi maganar ɗaukakar mulkinka za su kuma yi zancen ikonka, ");
INSERT INTO hausa_vpl VALUES ("PS145_12","020_145_12","PSA","145","12","12","saboda dukan mutane su san manyan ayyukanka da ɗaukakar darajar mulkinka. ");
INSERT INTO hausa_vpl VALUES ("PS145_13","020_145_13","PSA","145","13","13","Mulkinka madawwamin mulki ne, sarautarka kuma za tă dawwama cikin dukan zamanai. Ubangiji mai aminci ne ga dukan alkawuransa mai ƙauna kuma ga dukan abubuwan da ya yi. ");
INSERT INTO hausa_vpl VALUES ("PS145_14","020_145_14","PSA","145","14","14","Ubangiji yana riƙe da dukan waɗanda suka faɗi yana kuma ɗaga dukan waɗanda aka rusunar da su ƙasa. ");
INSERT INTO hausa_vpl VALUES ("PS145_15","020_145_15","PSA","145","15","15","Idanun kowa yana dogara gare ka, kana kuma ba su abincinsu a lokacin da ya dace. ");
INSERT INTO hausa_vpl VALUES ("PS145_16","020_145_16","PSA","145","16","16","Ka buɗe hannunka ka kuma ƙosar da sha’awar kowane abu mai rai. ");
INSERT INTO hausa_vpl VALUES ("PS145_17","020_145_17","PSA","145","17","17","Ubangiji mai adalci ne cikin dukan hanyoyinsa yana kuma nuna ƙauna ga dukan abubuwan da ya yi. ");
INSERT INTO hausa_vpl VALUES ("PS145_18","020_145_18","PSA","145","18","18","Ubangiji yana kusa da kowa da ya kira gare shi, ga duk wanda ya kira gare shi cikin gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PS145_19","020_145_19","PSA","145","19","19","Yakan cika sha’awar waɗanda suke tsoronsa; yakan ji kukansu yă kuma cece su. ");
INSERT INTO hausa_vpl VALUES ("PS145_20","020_145_20","PSA","145","20","20","Ubangiji yakan lura da dukan waɗanda suke ƙaunarsa, amma dukan mugaye zai hallaka su. ");
INSERT INTO hausa_vpl VALUES ("PS145_21","020_145_21","PSA","145","21","21","Bakina zai yi magana cikin yabon Ubangiji. Bari kowace halitta ta yabi sunansa mai tsarki har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("PS146_1","020_146_1","PSA","146","1","1","Yabi Ubangiji. Yabi Ubangiji, ya raina. ");
INSERT INTO hausa_vpl VALUES ("PS146_2","020_146_2","PSA","146","2","2","Zan yabi Ubangiji dukan kwanakina; zan rera yabo ga Allahna muddin raina. ");
INSERT INTO hausa_vpl VALUES ("PS146_3","020_146_3","PSA","146","3","3","Kada ka sa zuciyarka ga sarakuna, ga mutane masu mutuwa, waɗanda ba sa iya ceto. ");
INSERT INTO hausa_vpl VALUES ("PS146_4","020_146_4","PSA","146","4","4","Sa’ad da numfashinsu ya rabu da su sai su koma ƙasa; a wannan rana shirye-shiryensu sun zama banza. ");
INSERT INTO hausa_vpl VALUES ("PS146_5","020_146_5","PSA","146","5","5","Mai albarka ne wanda Allah na Yaƙub ne taimakonsa, wanda sa zuciyarsa yana a kan Ubangiji Allahnsa. ");
INSERT INTO hausa_vpl VALUES ("PS146_6","020_146_6","PSA","146","6","6","Mahaliccin sama da ƙasa, teku, da kome da yake cikinsu, Ubangiji, wanda yake mai aminci har abada. ");
INSERT INTO hausa_vpl VALUES ("PS146_7","020_146_7","PSA","146","7","7","Yakan biya bukatun mutanen da aka danne ya kuma ba da abinci ga mayunwata. Ubangiji yakan ’yantar da ’yan kurkuku, ");
INSERT INTO hausa_vpl VALUES ("PS146_8","020_146_8","PSA","146","8","8","Ubangiji yakan ba wa makafi ido, Ubangiji yakan ɗaga waɗanda aka rusunar da su ƙasa, Ubangiji yana ƙaunar masu adalci. ");
INSERT INTO hausa_vpl VALUES ("PS146_9","020_146_9","PSA","146","9","9","Ubangiji yana tsaron baƙi yana kuma lura da marayu da kuma gwauruwa, amma yakan lalatar da hanyoyin mugaye. ");
INSERT INTO hausa_vpl VALUES ("PS146_10","020_146_10","PSA","146","10","10","Ubangiji yana mulki har abada, Allahnki, ya Sihiyona, daga zamani zuwa zamani. Yabi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS147_1","020_147_1","PSA","147","1","1","Yabi Ubangiji. Yana da kyau a rera yabai ga Allahnmu, abu mai daɗi ne daidai ne kuma a yabe shi! ");
INSERT INTO hausa_vpl VALUES ("PS147_2","020_147_2","PSA","147","2","2","Ubangiji ya gina Urushalima; ya tattara kamammu na Isra’ilan da aka kai bauta. ");
INSERT INTO hausa_vpl VALUES ("PS147_3","020_147_3","PSA","147","3","3","Ya warkar da masu raunanar zuciya ya ɗaɗɗaura miyakunsu. ");
INSERT INTO hausa_vpl VALUES ("PS147_4","020_147_4","PSA","147","4","4","Ya lissafta yawan taurari ya kuma kira kowannensu da suna. ");
INSERT INTO hausa_vpl VALUES ("PS147_5","020_147_5","PSA","147","5","5","Shugabanmu mai girma ne mai iko duka; ganewarsa ba shi da iyaka. ");
INSERT INTO hausa_vpl VALUES ("PS147_6","020_147_6","PSA","147","6","6","Ubangiji yana kula da masu sauƙinkai yakan yar da mugaye a ƙasa. ");
INSERT INTO hausa_vpl VALUES ("PS147_7","020_147_7","PSA","147","7","7","Rera wa Ubangiji waƙar godiya; ku kada garaya ga Allahnmu. ");
INSERT INTO hausa_vpl VALUES ("PS147_8","020_147_8","PSA","147","8","8","Ya rufe sararin sama da gizagizai; yana tanada wa duniya ruwan sama yana kuma sa ciyawa tă yi girma a kan tuddai. ");
INSERT INTO hausa_vpl VALUES ("PS147_9","020_147_9","PSA","147","9","9","Yakan tanada wa shanu abinci da kuma saboda ’ya’yan hankaki sa’ad da suka yi kira. ");
INSERT INTO hausa_vpl VALUES ("PS147_10","020_147_10","PSA","147","10","10","Jin daɗinsa ba ya a ƙarfin doki, balle farin cikinsa yă kasance a ƙafafun mutum; ");
INSERT INTO hausa_vpl VALUES ("PS147_11","020_147_11","PSA","147","11","11","Ubangiji yakan yi farin ciki a waɗanda suke tsoronsa, waɗanda suke sa zuciya a ƙaunarsa marar ƙarewa. ");
INSERT INTO hausa_vpl VALUES ("PS147_12","020_147_12","PSA","147","12","12","Ki ɗaukaka Ubangiji, ya Urushalima; ki yabi Allahnki, ya Sihiyona. ");
INSERT INTO hausa_vpl VALUES ("PS147_13","020_147_13","PSA","147","13","13","Gama yana ƙarfafa ƙyamaren ƙofofinki yana kuma albarkace mutanenki a cikinki. ");
INSERT INTO hausa_vpl VALUES ("PS147_14","020_147_14","PSA","147","14","14","Yana ba da salama ga iyakokinki yana kuma ƙosar da ke da alkama mafi kyau. ");
INSERT INTO hausa_vpl VALUES ("PS147_15","020_147_15","PSA","147","15","15","Yana ba da umarninsa ga duniya; maganarsa tana tafiya da sauri. ");
INSERT INTO hausa_vpl VALUES ("PS147_16","020_147_16","PSA","147","16","16","Yana shimfiɗa ƙanƙara kamar ulu yă kuma watsar da hazo kamar toka. ");
INSERT INTO hausa_vpl VALUES ("PS147_17","020_147_17","PSA","147","17","17","Yana zuba ƙanƙara kamar ƙananan duwatsu. Wa zai iya jure wa sanyin da ya aiko? ");
INSERT INTO hausa_vpl VALUES ("PS147_18","020_147_18","PSA","147","18","18","Yakan aiki maganarsa ta kuwa narkar da su; yakan tā da iskarsa, ruwaye kuwa su gudu. ");
INSERT INTO hausa_vpl VALUES ("PS147_19","020_147_19","PSA","147","19","19","Ya bayyana maganarsa ga Yaƙub, dokokinsa da ƙa’idodinsa ga Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PS147_20","020_147_20","PSA","147","20","20","Bai yi wannan ga wata al’umma ba; ba su san dokokinsa ba. Yabi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS148_1","020_148_1","PSA","148","1","1","Yabi Ubangiji. Yabi Ubangiji daga sammai, yabe shi a bisa sammai. ");
INSERT INTO hausa_vpl VALUES ("PS148_2","020_148_2","PSA","148","2","2","Yabe shi, dukanku mala’ikunsa, yabe shi, dukanku rundunarsa na sama. ");
INSERT INTO hausa_vpl VALUES ("PS148_3","020_148_3","PSA","148","3","3","Yabe shi, rana da wata, yabe shi, dukanku taurari masu haskakawa. ");
INSERT INTO hausa_vpl VALUES ("PS148_4","020_148_4","PSA","148","4","4","Yabe shi, ku bisa sammai da kuma ku ruwan bisa sarari. ");
INSERT INTO hausa_vpl VALUES ("PS148_5","020_148_5","PSA","148","5","5","Bari su yabi sunan Ubangiji, gama ya umarta aka kuwa halicce su. ");
INSERT INTO hausa_vpl VALUES ("PS148_6","020_148_6","PSA","148","6","6","Ya sa su a wurarensu har abada abadin; ya ba da umarnin da ba zai taɓa shuɗe ba. ");
INSERT INTO hausa_vpl VALUES ("PS148_7","020_148_7","PSA","148","7","7","Yabi Ubangiji daga duniya, ku manyan halittun teku da kuma dukan zurfafan teku, ");
INSERT INTO hausa_vpl VALUES ("PS148_8","020_148_8","PSA","148","8","8","walƙiya da ƙanƙara, dusar ƙanƙara da gizagizai, hadirin iskar da suke biyayya da umarnansa, ");
INSERT INTO hausa_vpl VALUES ("PS148_9","020_148_9","PSA","148","9","9","ku duwatsu da dukan tuddai, itatuwa masu ’ya’ya da dukan al’ul, ");
INSERT INTO hausa_vpl VALUES ("PS148_10","020_148_10","PSA","148","10","10","namun jeji da dukan dabbobin gida, ƙanana halittu da tsuntsaye masu firiya, ");
INSERT INTO hausa_vpl VALUES ("PS148_11","020_148_11","PSA","148","11","11","sarakunan duniya da dukan al’ummai, ku sarakuna da dukan masu mulkin duniya, ");
INSERT INTO hausa_vpl VALUES ("PS148_12","020_148_12","PSA","148","12","12","samari da ’yan mata, tsofaffi da yara. ");
INSERT INTO hausa_vpl VALUES ("PS148_13","020_148_13","PSA","148","13","13","Bari su yabi sunan Ubangiji, gama sunansa ne kaɗai mafi ɗaukaka; darajarsa ta fi ƙarfin duniya da sammai. ");
INSERT INTO hausa_vpl VALUES ("PS148_14","020_148_14","PSA","148","14","14","Ya tayar wa mutanensa ƙaho, yabon dukan tsarkakansa, na Isra’ila, mutanen da suke kurkusa da zuciyarsa. Yabi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS149_1","020_149_1","PSA","149","1","1","Yabi Ubangiji. Ku rera sabuwar waƙa ga Ubangiji, yabonsa a cikin taron tsarkaka. ");
INSERT INTO hausa_vpl VALUES ("PS149_2","020_149_2","PSA","149","2","2","Bari Isra’ila su yi farin ciki da Mahaliccinsu; bari mutanen Sihiyona su yi murna da Sarkinsu. ");
INSERT INTO hausa_vpl VALUES ("PS149_3","020_149_3","PSA","149","3","3","Bari su yabi sunansa tare da rawa suna kuma yin kiɗi gare shi da ganga da garaya. ");
INSERT INTO hausa_vpl VALUES ("PS149_4","020_149_4","PSA","149","4","4","Gama Ubangiji yana jin daɗin mutanensa; yakan darjanta masu sauƙinkai da ceto. ");
INSERT INTO hausa_vpl VALUES ("PS149_5","020_149_5","PSA","149","5","5","Bari tsarkaka su yi farin ciki a wannan bangirma su kuma rera don farin ciki a kan gadajensu. ");
INSERT INTO hausa_vpl VALUES ("PS149_6","020_149_6","PSA","149","6","6","Bari yabon Allah yă kasance a bakunansu takobi mai kaifi kuma a hannuwansu, ");
INSERT INTO hausa_vpl VALUES ("PS149_7","020_149_7","PSA","149","7","7","don su ɗau fansa a kan al’ummai da kuma hukunci a kan mutane, ");
INSERT INTO hausa_vpl VALUES ("PS149_8","020_149_8","PSA","149","8","8","don su ɗaura sarakuna da sarƙoƙi, manyan garinsu da sarƙoƙin ƙarfe, ");
INSERT INTO hausa_vpl VALUES ("PS149_9","020_149_9","PSA","149","9","9","don su yi hukuncin da aka rubuta a kansu. Wannan ne ɗaukakar dukan tsarkakansa. Yabi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PS150_1","020_150_1","PSA","150","1","1","Yabi Ubangiji. Yabi Allah a cikin wurinsa mai tsarki; yabe shi a cikin sammai na ikonsa. ");
INSERT INTO hausa_vpl VALUES ("PS150_2","020_150_2","PSA","150","2","2","Yabe shi saboda ayyukansa masu iko; yabe shi saboda mafificin girmansa. ");
INSERT INTO hausa_vpl VALUES ("PS150_3","020_150_3","PSA","150","3","3","Yabe shi da ƙarar kakaki, yabe shi da garaya da molo, ");
INSERT INTO hausa_vpl VALUES ("PS150_4","020_150_4","PSA","150","4","4","yabe shi da ganga kuna taka rawa, yabe shi da kayan kiɗi na tsirkiya kuna kuma busa, ");
INSERT INTO hausa_vpl VALUES ("PS150_5","020_150_5","PSA","150","5","5","yabe shi da kuge mai ƙara, yabe shi da kuge masu ƙara sosai. ");
INSERT INTO hausa_vpl VALUES ("PS150_6","020_150_6","PSA","150","6","6","Bari kowane abu mai numfashi yă yabi Ubangiji. Yabi Ubangiji.");
INSERT INTO hausa_vpl VALUES ("PR1_1","021_1_1","PRO","1","1","1","Karin maganar Solomon ɗan Dawuda, sarkin Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("PR1_2","021_1_2","PRO","1","2","2","Ga karin magana da za su taimake ka don samun hikima da horo; don ganewa kalmomi masu zurfi; ");
INSERT INTO hausa_vpl VALUES ("PR1_3","021_1_3","PRO","1","3","3","don neman rayuwa ta horo da kuma ta hankali, kana yin abin da yake daidai, mai adalci da kuma wanda ya dace; ");
INSERT INTO hausa_vpl VALUES ("PR1_4","021_1_4","PRO","1","4","4","don sa marar azanci yă yi hankali, yă sa matasa su sani, su kuma iya rarrabewa, ");
INSERT INTO hausa_vpl VALUES ("PR1_5","021_1_5","PRO","1","5","5","bari masu hikima su saurara, su kuma ƙara ga saninsu, bari masu tunani kuma su sami jagora, ");
INSERT INTO hausa_vpl VALUES ("PR1_6","021_1_6","PRO","1","6","6","don su fahimci karin magana da kuma misalai, kalmomi da kuma kacici-kacici masu hikima. ");
INSERT INTO hausa_vpl VALUES ("PR1_7","021_1_7","PRO","1","7","7","Tsoron Ubangiji shi ne masomin ilimi, amma wawaye sun rena hikima da horo. ");
INSERT INTO hausa_vpl VALUES ("PR1_8","021_1_8","PRO","1","8","8","Ɗana, ka saurari umarnin mahaifinka kada kuma ka ƙyale koyarwar mahaifiyarka. ");
INSERT INTO hausa_vpl VALUES ("PR1_9","021_1_9","PRO","1","9","9","Za su zama kayan ado don su inganta ka da kuma sarƙar wuya don su yi wa wuyanka ado. ");
INSERT INTO hausa_vpl VALUES ("PR1_10","021_1_10","PRO","1","10","10","Ɗana, in masu zunubi sun jarabce ka, kada ka yarda. ");
INSERT INTO hausa_vpl VALUES ("PR1_11","021_1_11","PRO","1","11","11","In suka ce, “Zo mu tafi; mu yi kwanton ɓauna, mu nemi wani mu kashe, mu fāɗa wa marasa laifi; ");
INSERT INTO hausa_vpl VALUES ("PR1_12","021_1_12","PRO","1","12","12","mu haɗiye su da rai gaba ɗaya kamar kabari, kamar waɗanda suke gangarawa zuwa rami; ");
INSERT INTO hausa_vpl VALUES ("PR1_13","021_1_13","PRO","1","13","13","za mu sami dukiya masu daraja iri-iri, mu kuma cika gidajenmu da ganima; ");
INSERT INTO hausa_vpl VALUES ("PR1_14","021_1_14","PRO","1","14","14","ka haɗa kai da mu, za mu kuwa raba abin da muka sato” ");
INSERT INTO hausa_vpl VALUES ("PR1_15","021_1_15","PRO","1","15","15","ɗana, kada ka tafi tare da su, kada ka taka ƙafarka a hanyarsu; ");
INSERT INTO hausa_vpl VALUES ("PR1_16","021_1_16","PRO","1","16","16","gama ƙafafunsu kan yi sauri ga yin zunubi, suna saurin yin kisankai. ");
INSERT INTO hausa_vpl VALUES ("PR1_17","021_1_17","PRO","1","17","17","Ba shi da amfani a kafa tarko a idanun dukan tsuntsaye! ");
INSERT INTO hausa_vpl VALUES ("PR1_18","021_1_18","PRO","1","18","18","Waɗannan irin mutane kansu suke kafa wa tarko; ba sa kama kome, sai rayukansu! ");
INSERT INTO hausa_vpl VALUES ("PR1_19","021_1_19","PRO","1","19","19","Dukan waɗanda suke neman ribar da ba a samu a hanya mai kyau; ƙarshen wannan yakan ɗauke rayukansu. ");
INSERT INTO hausa_vpl VALUES ("PR1_20","021_1_20","PRO","1","20","20","Hikima tana kira da ƙarfi a kan titi, tana ɗaga muryarta a dandalin taron jama’a; ");
INSERT INTO hausa_vpl VALUES ("PR1_21","021_1_21","PRO","1","21","21","tana kira da ƙarfi a kan tituna masu surutu, tana yin jawabinta a hanyoyin shiga gari. ");
INSERT INTO hausa_vpl VALUES ("PR1_22","021_1_22","PRO","1","22","22","“Har yaushe ku da kuke marasa azanci za ku ci gaba a hanyoyinku marasa azanci? Har yaushe ku masu ba’a za ku yi ta murna cikin ba’arku wawaye kuma ku ƙi ilimi? ");
INSERT INTO hausa_vpl VALUES ("PR1_23","021_1_23","PRO","1","23","23","Da a ce kun saurari tsawatata, da na faɗa muku dukan abin da yake zuciyata in kuma sanar da ku tunanina. ");
INSERT INTO hausa_vpl VALUES ("PR1_24","021_1_24","PRO","1","24","24","Amma da yake kun ƙi ni sa’ad da na yi kira ba kuma wanda ya saurara sa’ad da na miƙa hannuna, ");
INSERT INTO hausa_vpl VALUES ("PR1_25","021_1_25","PRO","1","25","25","da yake kun ƙi dukan shawarata ba ku kuma yarda da tsawatata ba, ");
INSERT INTO hausa_vpl VALUES ("PR1_26","021_1_26","PRO","1","26","26","Zan yi muku dariya sa’ad da masifa ta same ku, zan yi muku ba’a sa’ad da bala’i ya same ku, ");
INSERT INTO hausa_vpl VALUES ("PR1_27","021_1_27","PRO","1","27","27","sa’ad da bala’i ya sha kanku kamar hadiri, sa’ad da masifa ta share ku kamar guguwa, sa’ad damuwa da wahala suka mamaye ku. ");
INSERT INTO hausa_vpl VALUES ("PR1_28","021_1_28","PRO","1","28","28","“Sa’an nan za su kira gare ni amma ba zan amsa ba; za su neme ni amma ba za su same ni ba. ");
INSERT INTO hausa_vpl VALUES ("PR1_29","021_1_29","PRO","1","29","29","Da yake sun ƙi sani ba su kuwa zaɓi tsoron Ubangiji ba, ");
INSERT INTO hausa_vpl VALUES ("PR1_30","021_1_30","PRO","1","30","30","da yake ba su karɓi shawarata ba suka kuwa yi kunnen ƙashi ga tsawatata, ");
INSERT INTO hausa_vpl VALUES ("PR1_31","021_1_31","PRO","1","31","31","za su sami sakayyar abubuwan da suka yi su kuma ƙoshi da sakayyar makircinsu. ");
INSERT INTO hausa_vpl VALUES ("PR1_32","021_1_32","PRO","1","32","32","Gama rashin hankalin marasa azanci zai kashe su, rashin kulawar wawaye kuma zai hallaka su; ");
INSERT INTO hausa_vpl VALUES ("PR1_33","021_1_33","PRO","1","33","33","amma duk wanda ya saurare ni, zai zauna lafiya yă kuma kasance da rai kwance, ba tare da tsoron lahani ba.” ");
INSERT INTO hausa_vpl VALUES ("PR2_1","021_2_1","PRO","2","1","1","Ɗana, in ka yarda da kalmomina ka kuma ajiye umarnaina a cikinka, ");
INSERT INTO hausa_vpl VALUES ("PR2_2","021_2_2","PRO","2","2","2","kana kasa kunne ga abin da yake na hikima, kana kuma yin ƙoƙari ka fahimce shi, ");
INSERT INTO hausa_vpl VALUES ("PR2_3","021_2_3","PRO","2","3","3","in kuma ka kira ga tsinkaya ka kuma kira da ƙarfi don ganewa, ");
INSERT INTO hausa_vpl VALUES ("PR2_4","021_2_4","PRO","2","4","4","in ka neme shi yadda ake neman azurfa ka kuma neme shi kamar yadda ake neman ɓoyayyiyar dukiya, ");
INSERT INTO hausa_vpl VALUES ("PR2_5","021_2_5","PRO","2","5","5","to, za ka gane tsoron Ubangiji ka kuma sami sanin Allah. ");
INSERT INTO hausa_vpl VALUES ("PR2_6","021_2_6","PRO","2","6","6","Gama Ubangiji yana ba da hikima, daga bakinsa kuma, sani da ganewa sukan fito. ");
INSERT INTO hausa_vpl VALUES ("PR2_7","021_2_7","PRO","2","7","7","Yana riƙe da nasara a ma’aji don masu yin gaskiya, shi ne mafaka ga waɗanda tafiyarsu ba ta da laifi, ");
INSERT INTO hausa_vpl VALUES ("PR2_8","021_2_8","PRO","2","8","8","gama yana tsare abin da masu adalci suke bukata yana kuma tsare hanyar amintattunsa. ");
INSERT INTO hausa_vpl VALUES ("PR2_9","021_2_9","PRO","2","9","9","Sa’an nan za ku fahimci abin da yake daidai da abin da yake na adalci da abin da yake gaskiya, da kowace hanya mai kyau. ");
INSERT INTO hausa_vpl VALUES ("PR2_10","021_2_10","PRO","2","10","10","Gama hikima za tă shiga cikin zuciyarka, sani kuma zai faranta maka rai. ");
INSERT INTO hausa_vpl VALUES ("PR2_11","021_2_11","PRO","2","11","11","Tsinkaya za tă tsare ka, ganewa kuma za tă yi maka jagora. ");
INSERT INTO hausa_vpl VALUES ("PR2_12","021_2_12","PRO","2","12","12","Hikima za tă cece ka daga hanyoyin mugayen mutane, daga kalmomin mutane masu ɓatanci, ");
INSERT INTO hausa_vpl VALUES ("PR2_13","021_2_13","PRO","2","13","13","waɗanda suke barin miƙaƙƙun hanyoyi don su yi tafiya a hanyoyi masu duhu, ");
INSERT INTO hausa_vpl VALUES ("PR2_14","021_2_14","PRO","2","14","14","waɗanda suke jin daɗin yin abin da ba shi da kyau suna kuma farin ciki a mugayen ɓatanci, ");
INSERT INTO hausa_vpl VALUES ("PR2_15","021_2_15","PRO","2","15","15","waɗanda hanyoyinsu karkatattu ne waɗanda kuma suke cuku-cuku a hanyoyinsu. ");
INSERT INTO hausa_vpl VALUES ("PR2_16","021_2_16","PRO","2","16","16","Zai kiyaye ku kuma daga mazinaciya, daga mace mai lalata, mai ƙoƙarin kama ka da daɗin bakinta, ");
INSERT INTO hausa_vpl VALUES ("PR2_17","021_2_17","PRO","2","17","17","wadda ta bar mijin ƙuruciyarta ta kuma ƙyale alkawarin da ta yi a gaban Allah. ");
INSERT INTO hausa_vpl VALUES ("PR2_18","021_2_18","PRO","2","18","18","Gama gidanta yana kai ga mutuwa hanyarta kuma ga ruhohin matattu. ");
INSERT INTO hausa_vpl VALUES ("PR2_19","021_2_19","PRO","2","19","19","Duk wanda ya ziyarce ta ba ya ƙara komowa ba zai ƙara komowa ga hanyar rai. ");
INSERT INTO hausa_vpl VALUES ("PR2_20","021_2_20","PRO","2","20","20","Don haka dole ku yi tafiya a hanyoyin mutanen kirki ku kuma yi ta bi hanyoyin adalai. ");
INSERT INTO hausa_vpl VALUES ("PR2_21","021_2_21","PRO","2","21","21","Gama masu aikata gaskiya za su zauna a cikin ƙasar, marasa laifi kuma za su kasance a cikinta; ");
INSERT INTO hausa_vpl VALUES ("PR2_22","021_2_22","PRO","2","22","22","amma za a fid da mugaye daga ƙasar, za a tumɓuke marasa aminci kuma daga gare ta. ");
INSERT INTO hausa_vpl VALUES ("PR3_1","021_3_1","PRO","3","1","1","Ɗana, kada ka manta da koyarwata, amma ka kiyaye umarnaina a cikin zuciyarka, ");
INSERT INTO hausa_vpl VALUES ("PR3_2","021_3_2","PRO","3","2","2","gama za su ƙara maka tsawon rai da shekaru masu yawa su kuma kawo maka wadata. ");
INSERT INTO hausa_vpl VALUES ("PR3_3","021_3_3","PRO","3","3","3","Kada ka bar ƙauna da aminci su rabu da kai; ka ɗaura su kewaye da wuyanka, ka rubuta su a allon zuciyarka. ");
INSERT INTO hausa_vpl VALUES ("PR3_4","021_3_4","PRO","3","4","4","Sa’an nan za ka sami tagomashi da kuma suna mai kyau a gaban Allah da kuma a gaban mutane. ");
INSERT INTO hausa_vpl VALUES ("PR3_5","021_3_5","PRO","3","5","5","Ka dogara ga Ubangiji da dukan zuciyarka kada kuma ka dangana ga ganewarka; ");
INSERT INTO hausa_vpl VALUES ("PR3_6","021_3_6","PRO","3","6","6","cikin dukan hanyoyinka ka amince da shi, zai kuwa sa hanyoyinka su miƙe. ");
INSERT INTO hausa_vpl VALUES ("PR3_7","021_3_7","PRO","3","7","7","Kada ka zama mai hikima a ganinka; ka ji tsoron Ubangiji ka kuma guji mugunta. ");
INSERT INTO hausa_vpl VALUES ("PR3_8","021_3_8","PRO","3","8","8","Wannan zai ba wa jikinka lafiya yă kuma adana ƙasusuwanka. ");
INSERT INTO hausa_vpl VALUES ("PR3_9","021_3_9","PRO","3","9","9","Ka girmama Ubangiji da dukan dukiyarka, ta wurin miƙa masa nunan fari na dukan amfanin gonarka; ");
INSERT INTO hausa_vpl VALUES ("PR3_10","021_3_10","PRO","3","10","10","ta haka rumbunanka za su cika har su zuba, randunanka kuma su cika har baki da sabon ruwan inabi. ");
INSERT INTO hausa_vpl VALUES ("PR3_11","021_3_11","PRO","3","11","11","Ɗana, kada ka rena horon Ubangiji kada kuma ka ƙi tsawatawarsa, ");
INSERT INTO hausa_vpl VALUES ("PR3_12","021_3_12","PRO","3","12","12","domin Ubangiji yakan hori waɗanda yake ƙauna, kamar yadda mahaifi yake yin wa ɗa da yake fariya da shi. ");
INSERT INTO hausa_vpl VALUES ("PR3_13","021_3_13","PRO","3","13","13","Mai albarka ne mutumin da ya sami hikima, mutumin da ya sami fahimi, ");
INSERT INTO hausa_vpl VALUES ("PR3_14","021_3_14","PRO","3","14","14","gama ta fi azurfa riba tana kuma da amfani fiye da zinariya. ");
INSERT INTO hausa_vpl VALUES ("PR3_15","021_3_15","PRO","3","15","15","Ta fi lu’ulu’u daraja; ba a kwatanta abin da ka fi sha’awa da ita. ");
INSERT INTO hausa_vpl VALUES ("PR3_16","021_3_16","PRO","3","16","16","Tsawon rai yana a cikin hannunta na dama; a hannunta na hagu kuwa akwai arziki da bangirma. ");
INSERT INTO hausa_vpl VALUES ("PR3_17","021_3_17","PRO","3","17","17","Hanyoyinta hanyoyi ne masu daɗi, dukan hanyoyinta kuma salama ne. ");
INSERT INTO hausa_vpl VALUES ("PR3_18","021_3_18","PRO","3","18","18","Ita itacen rai ne ga waɗanda suka rungume ta; waɗanda suke riƙe da ta za su zama masu albarka. ");
INSERT INTO hausa_vpl VALUES ("PR3_19","021_3_19","PRO","3","19","19","Ta wurin hikima Ubangiji ya kafa harsashin duniya, ta wurin fahimi ya shirya sammai inda suke; ");
INSERT INTO hausa_vpl VALUES ("PR3_20","021_3_20","PRO","3","20","20","ta wurin sani aka rarraba zurfafa, gizagizai kuma suka zubo raɓa. ");
INSERT INTO hausa_vpl VALUES ("PR3_21","021_3_21","PRO","3","21","21","Ɗana, ka riƙe sahihiyar shari’a da kuma basira, kada ka bar su su rabu da kai; ");
INSERT INTO hausa_vpl VALUES ("PR3_22","021_3_22","PRO","3","22","22","za su zama rai a gare ka, abin adon da zai gyara wuyanka. ");
INSERT INTO hausa_vpl VALUES ("PR3_23","021_3_23","PRO","3","23","23","Sa’an nan za ka bi hanyarka lafiya, ƙafarka kuwa ba zai yi tuntuɓe ba; ");
INSERT INTO hausa_vpl VALUES ("PR3_24","021_3_24","PRO","3","24","24","sa’ad da ka kwanta, ba za ka ji tsoro ba; sa’ad da ka kwanta, barci zai yi maka daɗi. ");
INSERT INTO hausa_vpl VALUES ("PR3_25","021_3_25","PRO","3","25","25","Kada ka ji tsoron masifar da za tă faru farat ɗaya ko lalacin da yakan auka wa mugaye, ");
INSERT INTO hausa_vpl VALUES ("PR3_26","021_3_26","PRO","3","26","26","gama Ubangiji zai zama ƙarfin halinka zai kuwa kiyaye ƙafarka daga fāɗawa a tarko. ");
INSERT INTO hausa_vpl VALUES ("PR3_27","021_3_27","PRO","3","27","27","Kada ka ƙi yin alheri ga duk wanda ya dace, sa’ad da kana iya yin haka. ");
INSERT INTO hausa_vpl VALUES ("PR3_28","021_3_28","PRO","3","28","28","Kada ka ce wa maƙwabcinka “Ka yă dakata sai gobe,” idan kana iya taimakonsa yanzu. ");
INSERT INTO hausa_vpl VALUES ("PR3_29","021_3_29","PRO","3","29","29","Kada ka shirya kome da zai cuci maƙwabcinka, wanda yake zama da aminci kusa da kai. ");
INSERT INTO hausa_vpl VALUES ("PR3_30","021_3_30","PRO","3","30","30","Kada ka zargi mutum ba dalili, sa’ad da bai yi laifi ba. ");
INSERT INTO hausa_vpl VALUES ("PR3_31","021_3_31","PRO","3","31","31","Kada ka ji kishin mai tā-da-na-zaune-tsaye ko ka yi sha’awar aikata ayyukansu. ");
INSERT INTO hausa_vpl VALUES ("PR3_32","021_3_32","PRO","3","32","32","Gama Ubangiji yana ƙyama mai aikata mugunta amma yakan rungumi adalin da ya amince da shi. ");
INSERT INTO hausa_vpl VALUES ("PR3_33","021_3_33","PRO","3","33","33","La’anar Ubangiji tana a gidan mugaye, amma yakan albarkaci gidan adali. ");
INSERT INTO hausa_vpl VALUES ("PR3_34","021_3_34","PRO","3","34","34","Yakan yi wa masu girman kai ba’a amma yakan yi wa mai sauƙinkai alheri. ");
INSERT INTO hausa_vpl VALUES ("PR3_35","021_3_35","PRO","3","35","35","Masu hikima sukan sami kyakkyawan suna, amma wawaye sukan ƙara wa kansu shan kunya. ");
INSERT INTO hausa_vpl VALUES ("PR4_1","021_4_1","PRO","4","1","1","Ku saurara ’ya’yana ga koyarwar mahaifinku; ku mai da hankali, ku sami fahimi. ");
INSERT INTO hausa_vpl VALUES ("PR4_2","021_4_2","PRO","4","2","2","Ina ba ku sahihiyar koyarwa, saboda haka kada ku ƙyale koyarwata. ");
INSERT INTO hausa_vpl VALUES ("PR4_3","021_4_3","PRO","4","3","3","Sa’ad da nake yaro a gidan mahaifina, yaro kaɗai kuma na mahaifiyata, ");
INSERT INTO hausa_vpl VALUES ("PR4_4","021_4_4","PRO","4","4","4","ya koya mini ya ce, “Ka riƙe kalmomina da dukan zuciyarka; ka kiyaye umarnaina za ka kuwa rayu. ");
INSERT INTO hausa_vpl VALUES ("PR4_5","021_4_5","PRO","4","5","5","Ka nemi hikima, ka nemi fahimi; kada ka manta da kalmomina ko ka kauce daga gare su. ");
INSERT INTO hausa_vpl VALUES ("PR4_6","021_4_6","PRO","4","6","6","Kada ka ƙyale hikima, za tă kuwa tsare ka; ka ƙaunace ta, za tă kuwa lura da kai. ");
INSERT INTO hausa_vpl VALUES ("PR4_7","021_4_7","PRO","4","7","7","Hikima ce mafi girma duka; saboda haka ka nemi hikima. Ko da za tă ci duk abin da kake da shi, ka dai nemi fahimi. ");
INSERT INTO hausa_vpl VALUES ("PR4_8","021_4_8","PRO","4","8","8","Ka ƙaunace ta, za tă ɗaukaka ka; ka rungume ta, za tă kuwa girmama ka. ");
INSERT INTO hausa_vpl VALUES ("PR4_9","021_4_9","PRO","4","9","9","Za tă zama kayan ado da za su inganta kanka tă kuma zamar maka rawanin ɗaukaka.” ");
INSERT INTO hausa_vpl VALUES ("PR4_10","021_4_10","PRO","4","10","10","Ka saurara, ɗana, ka yarda da abin da na faɗa, shekarun rayuwarka kuwa za su zama masu yawa. ");
INSERT INTO hausa_vpl VALUES ("PR4_11","021_4_11","PRO","4","11","11","Na bishe ka a hanyar hikima na kuma jagorance ka a miƙaƙƙun hanyoyi. ");
INSERT INTO hausa_vpl VALUES ("PR4_12","021_4_12","PRO","4","12","12","Sa’ad da kake tafiya, ba abin da zai sa ka tuntuɓe; sa’ad da kake gudu, ba za ka fāɗi ba. ");
INSERT INTO hausa_vpl VALUES ("PR4_13","021_4_13","PRO","4","13","13","Ka riƙe umarni, kada ka bari yă kuɓuce; ka tsare shi sosai, gama ranka ne. ");
INSERT INTO hausa_vpl VALUES ("PR4_14","021_4_14","PRO","4","14","14","Kada ka sa ƙafa a kan hanyar mugaye kada ka bi gurbin mugaye. ");
INSERT INTO hausa_vpl VALUES ("PR4_15","021_4_15","PRO","4","15","15","Ka guji mugunta, kada ka yi tafiya a kanta; juya daga gare ta ka yi tafiyarka. ");
INSERT INTO hausa_vpl VALUES ("PR4_16","021_4_16","PRO","4","16","16","Mugaye ba sa iya barci, sai sun aikata mugunta; ba su barci sai sun cuci wani. ");
INSERT INTO hausa_vpl VALUES ("PR4_17","021_4_17","PRO","4","17","17","Mugunta da ta’adi kamar ci da sha suke a gare su. ");
INSERT INTO hausa_vpl VALUES ("PR4_18","021_4_18","PRO","4","18","18","Hanyar adali kamar fitowar rana ce, sai ƙara haske take yi, har ta kai tsaka. ");
INSERT INTO hausa_vpl VALUES ("PR4_19","021_4_19","PRO","4","19","19","Amma hanyar mugaye kamar zurfin duhu ne; ba sa sanin abin da ya sa suke tuntuɓe. ");
INSERT INTO hausa_vpl VALUES ("PR4_20","021_4_20","PRO","4","20","20","Ɗana, ka kula da abin da nake faɗa, ka saurara sosai ga kalmomina. ");
INSERT INTO hausa_vpl VALUES ("PR4_21","021_4_21","PRO","4","21","21","Kada ka bari su rabu da kai, ka kiyaye su a cikin zuciyarka; ");
INSERT INTO hausa_vpl VALUES ("PR4_22","021_4_22","PRO","4","22","22","gama rai ne ga waɗanda suke nemansu da kuma lafiya ga dukan jikin mutum. ");
INSERT INTO hausa_vpl VALUES ("PR4_23","021_4_23","PRO","4","23","23","Fiye da kome duka, ka tsare zuciyarka, gama maɓulɓulan ruwan rijiyar rai ne. ");
INSERT INTO hausa_vpl VALUES ("PR4_24","021_4_24","PRO","4","24","24","Ka kau da muguwar magana daga bakinka; ka yi nesa da magana marar kyau daga leɓunanka. ");
INSERT INTO hausa_vpl VALUES ("PR4_25","021_4_25","PRO","4","25","25","Bari idanunka su dubi gaba sosai, ka kafa idanunka kai tsaye a gabanka. ");
INSERT INTO hausa_vpl VALUES ("PR4_26","021_4_26","PRO","4","26","26","Ka san inda ƙafafunka suke takawa ka bi hanyoyin da suke daram kawai. ");
INSERT INTO hausa_vpl VALUES ("PR4_27","021_4_27","PRO","4","27","27","Kada ka kauce dama ko hagu; ka kiyaye ƙafarka daga mugunta. ");
INSERT INTO hausa_vpl VALUES ("PR5_1","021_5_1","PRO","5","1","1","Ɗana, ka mai da hankali ga hikimata ka saurara da kyau ga kalmomin basirata, ");
INSERT INTO hausa_vpl VALUES ("PR5_2","021_5_2","PRO","5","2","2","don ka ci gaba da yin kome daidai leɓunanka za su adana sani. ");
INSERT INTO hausa_vpl VALUES ("PR5_3","021_5_3","PRO","5","3","3","Gama leɓunan mazinaciya na ɗigan zuma, maganarta tana da sulɓi fiye da mai; ");
INSERT INTO hausa_vpl VALUES ("PR5_4","021_5_4","PRO","5","4","4","amma a ƙarshe tana da ɗaci kamar tafashiya, mai ci kamar takobi mai kaifi biyu. ");
INSERT INTO hausa_vpl VALUES ("PR5_5","021_5_5","PRO","5","5","5","Ƙafafunta na kaiwa ga mutuwa; sawunta na jagora kai tsaye zuwa kabari. ");
INSERT INTO hausa_vpl VALUES ("PR5_6","021_5_6","PRO","5","6","6","Ba ta wani tunanin rayuwa; hanyoyinta karkatacce ne, amma ba tă sani ba. ");
INSERT INTO hausa_vpl VALUES ("PR5_7","021_5_7","PRO","5","7","7","Yanzu fa, ’ya’yana, ku saurare ni; kada ku juye daga abin da nake faɗa. ");
INSERT INTO hausa_vpl VALUES ("PR5_8","021_5_8","PRO","5","8","8","Ku yi nesa da hanyarta, kana ku je kusa da ƙofar gidanta, ");
INSERT INTO hausa_vpl VALUES ("PR5_9","021_5_9","PRO","5","9","9","don kada ku ba da ƙarfi mafi kyau ga waɗansu da kuma shekarunku ga wani marar imani, ");
INSERT INTO hausa_vpl VALUES ("PR5_10","021_5_10","PRO","5","10","10","don kada baƙi su yi biki a kan dukiyarku wahalarku ta azurta gidan wani mutum dabam. ");
INSERT INTO hausa_vpl VALUES ("PR5_11","021_5_11","PRO","5","11","11","A ƙarshen rayuwarku za ku yi ta nishi, sa’ad da namanku da jikinku suka zagwanye. ");
INSERT INTO hausa_vpl VALUES ("PR5_12","021_5_12","PRO","5","12","12","Za ku ce, “Me ya sa na ƙi horo! Me ya sa zuciyata ta ƙi gyara! ");
INSERT INTO hausa_vpl VALUES ("PR5_13","021_5_13","PRO","5","13","13","Ban yi biyayya da malamaina ba ko in saurari masu koyar da ni. ");
INSERT INTO hausa_vpl VALUES ("PR5_14","021_5_14","PRO","5","14","14","Na zo gab da hallaka gaba ɗaya a tsakiyar dukan taron.” ");
INSERT INTO hausa_vpl VALUES ("PR5_15","021_5_15","PRO","5","15","15","Ku sha ruwa daga tankinku, ruwa mai gudu daga rijiyarku. ");
INSERT INTO hausa_vpl VALUES ("PR5_16","021_5_16","PRO","5","16","16","In maɓulɓulanku suka cika suna malala har waje, rafuffukan ruwanku a dandalin jama’a? ");
INSERT INTO hausa_vpl VALUES ("PR5_17","021_5_17","PRO","5","17","17","Bari su zama naka kaɗai, don kada ka raba da baƙi. ");
INSERT INTO hausa_vpl VALUES ("PR5_18","021_5_18","PRO","5","18","18","Bari maɓulɓulanka ya zama mai albarka, bari kuma ka yi farin ciki da matar ƙuruciyarka. ");
INSERT INTO hausa_vpl VALUES ("PR5_19","021_5_19","PRO","5","19","19","Ƙaunatacciyar mariri, barewa mai kyan gani, bari mamanta su ishe ka kullum, bari ƙaunarta ta ɗauke hankalinka kullum. ");
INSERT INTO hausa_vpl VALUES ("PR5_20","021_5_20","PRO","5","20","20","Ɗana, me ya sa za ka bari mazinaciya ta ɗauke maka hankali? Don me za ka rungume matar wani? ");
INSERT INTO hausa_vpl VALUES ("PR5_21","021_5_21","PRO","5","21","21","Gama hanyar mutum a bayyane take a gaban Ubangiji, yana kuma lura da dukan hanyoyinsa. ");
INSERT INTO hausa_vpl VALUES ("PR5_22","021_5_22","PRO","5","22","22","Ayyukan mugunta na mugun mutum tarko ne gare shi; igiyoyin zunubinsa za su daure shi kankan. ");
INSERT INTO hausa_vpl VALUES ("PR5_23","021_5_23","PRO","5","23","23","Zai mutu saboda rashin ɗa’a yawan wawancinsa zai sa yă kauce. ");
INSERT INTO hausa_vpl VALUES ("PR6_1","021_6_1","PRO","6","1","1","Ɗana, in ka shirya tsaya wa maƙwabcinka don yă karɓi bashi, in ka sa hannunka don ɗaukar lamunin wani, ");
INSERT INTO hausa_vpl VALUES ("PR6_2","021_6_2","PRO","6","2","2","in maganarka ta taɓa kama ka, ko kalmomin bakinka sun zama maka tarko, ");
INSERT INTO hausa_vpl VALUES ("PR6_3","021_6_3","PRO","6","3","3","to, sai ka yi haka, ɗana don ka ’yantar da kanka; da yake ka shiga hannuwan maƙwabcinka, ka tafi ka ƙasƙantar da kanka; ka roƙi maƙwabcinka! ");
INSERT INTO hausa_vpl VALUES ("PR6_4","021_6_4","PRO","6","4","4","Ka hana kanka barci, ko gyangyaɗi a idanunka ma. ");
INSERT INTO hausa_vpl VALUES ("PR6_5","021_6_5","PRO","6","5","5","Ka ’yantar da kanka, kamar barewa daga hannun mai farauta, kamar tsuntsu daga tarkon mai kafa tarko. ");
INSERT INTO hausa_vpl VALUES ("PR6_6","021_6_6","PRO","6","6","6","Ku tafi wurin kyashi, ku ragwaye; ku lura da hanyoyinsa ku zama masu hikima! ");
INSERT INTO hausa_vpl VALUES ("PR6_7","021_6_7","PRO","6","7","7","Ba shi da jagora ba shugaba ko mai mulki, ");
INSERT INTO hausa_vpl VALUES ("PR6_8","021_6_8","PRO","6","8","8","duk da haka yakan yi tanade-tanadensa da rani ya kuma tattara abincinsa a lokacin girbi. ");
INSERT INTO hausa_vpl VALUES ("PR6_9","021_6_9","PRO","6","9","9","Har yaushe za ku kwanta a can, ku ragwaye? Yaushe za ku farka daga barcinku? ");
INSERT INTO hausa_vpl VALUES ("PR6_10","021_6_10","PRO","6","10","10","Ɗan barci, ɗan gyangyaɗi, ɗan naɗin hannuwa don a huta, ");
INSERT INTO hausa_vpl VALUES ("PR6_11","021_6_11","PRO","6","11","11","talauci kuwa zai zo kamar ’yan hari rashi kuma kamar ɗan fashi. ");
INSERT INTO hausa_vpl VALUES ("PR6_12","021_6_12","PRO","6","12","12","Sakare da mutumin banza wanda yana yawo da magana banza a baki, ");
INSERT INTO hausa_vpl VALUES ("PR6_13","021_6_13","PRO","6","13","13","wanda yake ƙyifce da ido, yana yi alama da ƙafafunsa yana kuma nuni da yatsotsinsa, ");
INSERT INTO hausa_vpl VALUES ("PR6_14","021_6_14","PRO","6","14","14","wanda yake ƙulla mugunta da ruɗu a cikin zuciyarsa, kullum yana tā-da-na-zaune-tsaye ");
INSERT INTO hausa_vpl VALUES ("PR6_15","021_6_15","PRO","6","15","15","Saboda haka masifa za tă fāɗa farat ɗaya; za a hallaka shi nan da nan, ba makawa. ");
INSERT INTO hausa_vpl VALUES ("PR6_16","021_6_16","PRO","6","16","16","Akwai abubuwa shida da Ubangiji ya ƙi, abubuwa bakwai da suke abin ƙyama gare shi, ");
INSERT INTO hausa_vpl VALUES ("PR6_17","021_6_17","PRO","6","17","17","duban reni, harshe mai ƙarya, hannuwa masu zub da jinin marar laifi, ");
INSERT INTO hausa_vpl VALUES ("PR6_18","021_6_18","PRO","6","18","18","zuciyar da take ƙulla mugayen dabaru, ƙafafun da suke sauri zuwa aikata mugunta, ");
INSERT INTO hausa_vpl VALUES ("PR6_19","021_6_19","PRO","6","19","19","mai shaidar ƙarya wanda yake zuba ƙarairayi, da kuma mutumin da yake tā-da-na-zaune-tsaye a cikin ’yan’uwa. ");
INSERT INTO hausa_vpl VALUES ("PR6_20","021_6_20","PRO","6","20","20","Ɗana, ka kiyaye umarnan mahaifinka kada kuma ka ƙyale koyarwar mahaifiyarka. ");
INSERT INTO hausa_vpl VALUES ("PR6_21","021_6_21","PRO","6","21","21","Ka ɗaura su a zuciyarka har abada; ka ɗaura su kewaye da wuyanka. ");
INSERT INTO hausa_vpl VALUES ("PR6_22","021_6_22","PRO","6","22","22","Sa’ad da kake tafiya, za su bishe ka; sa’ad da kake barci, za su lura da kai; sa’ad da ka farka, za su yi maka magana. ");
INSERT INTO hausa_vpl VALUES ("PR6_23","021_6_23","PRO","6","23","23","Gama waɗannan umarnai fitila ne, wannan koyarwa haske ne, kuma gyare-gyaren horo hanyar rayuwa ce, ");
INSERT INTO hausa_vpl VALUES ("PR6_24","021_6_24","PRO","6","24","24","suna kiyaye ka daga mace marar ɗa’a daga sulɓin harshen mace marar aminci. ");
INSERT INTO hausa_vpl VALUES ("PR6_25","021_6_25","PRO","6","25","25","Kada ka yi sha’awarta a cikin zuciyarka kada ka bar ta tă ɗauki hankalinka da idanunta. ");
INSERT INTO hausa_vpl VALUES ("PR6_26","021_6_26","PRO","6","26","26","Gama karuwa takan mai da kai kamar burodin kyauta, mazinaciya kuma takan farauci ranka. ");
INSERT INTO hausa_vpl VALUES ("PR6_27","021_6_27","PRO","6","27","27","Mutum zai iya ɗiba wuta ya zuba a cinyarsa ba tare da rigunansa sun ƙone ba? ");
INSERT INTO hausa_vpl VALUES ("PR6_28","021_6_28","PRO","6","28","28","Mutum zai iya yin tafi a garwashi wuta mai zafi ba tare da ƙafafunsa sun ƙone ba? ");
INSERT INTO hausa_vpl VALUES ("PR6_29","021_6_29","PRO","6","29","29","Haka yake da wanda ya kwana da matar wani; babu wanda ya taɓa ta da zai tafi babu hukunci. ");
INSERT INTO hausa_vpl VALUES ("PR6_30","021_6_30","PRO","6","30","30","Mutane ba sa ƙyale ɓarawo in ya yi sata don yă ƙosar da yunwarsa sa’ad da yake jin yunwa. ");
INSERT INTO hausa_vpl VALUES ("PR6_31","021_6_31","PRO","6","31","31","Duk da haka in aka kama shi, dole yă biya sau bakwai ko da yake abin zai ci dukan arzikin gidansa. ");
INSERT INTO hausa_vpl VALUES ("PR6_32","021_6_32","PRO","6","32","32","Amma mutumin da ya yi zina ba shi da hankali; duk wanda ya yi haka yana hallaka kansa ne. ");
INSERT INTO hausa_vpl VALUES ("PR6_33","021_6_33","PRO","6","33","33","Dūka da kunya ne za su zama rabonsa, kuma kunyarsa za tă dawwama. ");
INSERT INTO hausa_vpl VALUES ("PR6_34","021_6_34","PRO","6","34","34","Gama kishi kan tā da hasalar miji, kuma ba zai ji tausayi ba sa’ad da yake ramawa. ");
INSERT INTO hausa_vpl VALUES ("PR6_35","021_6_35","PRO","6","35","35","Ba zai karɓi duk wata biya ba; zai ƙi cin hanci, kome yawansu. ");
INSERT INTO hausa_vpl VALUES ("PR7_1","021_7_1","PRO","7","1","1","Ɗana, ka kiyaye kalmomina ka kuma ajiye umarnaina a cikinka. ");
INSERT INTO hausa_vpl VALUES ("PR7_2","021_7_2","PRO","7","2","2","Ka kiyaye umarnaina za ka kuwa rayu; ka tsare koyarwata kamar ƙwayar idonka. ");
INSERT INTO hausa_vpl VALUES ("PR7_3","021_7_3","PRO","7","3","3","Ka daure su a yatsotsinka; ka rubuta su a allon zuciyarka. ");
INSERT INTO hausa_vpl VALUES ("PR7_4","021_7_4","PRO","7","4","4","Ka faɗa wa hikima, “Ke ’yar’uwata ce,” ka kuma kira fahimi danginka; ");
INSERT INTO hausa_vpl VALUES ("PR7_5","021_7_5","PRO","7","5","5","za su kiyaye ka daga mazinaciya, daga mace marar aminci da kalmominta masu ɗaukan hankali. ");
INSERT INTO hausa_vpl VALUES ("PR7_6","021_7_6","PRO","7","6","6","A tagar gidana na leƙa ta labule mai rammuka. ");
INSERT INTO hausa_vpl VALUES ("PR7_7","021_7_7","PRO","7","7","7","Sai na gani a cikin marasa azanci, na lura a cikin samari, wani matashi wanda ba shi da hankali. ");
INSERT INTO hausa_vpl VALUES ("PR7_8","021_7_8","PRO","7","8","8","Yana gangarawa a titi kusa da kusurwarta, yana tafiya a gefen wajen gidanta ");
INSERT INTO hausa_vpl VALUES ("PR7_9","021_7_9","PRO","7","9","9","da magariba, yayinda rana tana fāɗuwa, yayinda duhun dare yana farawa. ");
INSERT INTO hausa_vpl VALUES ("PR7_10","021_7_10","PRO","7","10","10","Sai ga mace ta fito don ta sadu da shi, saye da riga kamar karuwa shirye kuma don ta yaudare shi. ");
INSERT INTO hausa_vpl VALUES ("PR7_11","021_7_11","PRO","7","11","11","(Ba ta jin tsoro, ko kuma kunya, ƙafafunta ba sa zama a gida; ");
INSERT INTO hausa_vpl VALUES ("PR7_12","021_7_12","PRO","7","12","12","wani lokaci a titi, wani lokaci a dandali, tana yawo a kowace kusurwa.) ");
INSERT INTO hausa_vpl VALUES ("PR7_13","021_7_13","PRO","7","13","13","Sai ta kama shi ta rungume shi da duban soyayya a fuskarta ta ce, ");
INSERT INTO hausa_vpl VALUES ("PR7_14","021_7_14","PRO","7","14","14","“Ina da hadaya ta salama a gida; yau zan cika alkawarina. ");
INSERT INTO hausa_vpl VALUES ("PR7_15","021_7_15","PRO","7","15","15","Saboda haka na fito don in sadu da kai; na neme ka na kuma same ka! ");
INSERT INTO hausa_vpl VALUES ("PR7_16","021_7_16","PRO","7","16","16","Na lulluɓe gadona da lili masu launi dabam-dabam daga Masar. ");
INSERT INTO hausa_vpl VALUES ("PR7_17","021_7_17","PRO","7","17","17","Na yayyafa turare a gadona da mur, aloyes da kuma kirfa. ");
INSERT INTO hausa_vpl VALUES ("PR7_18","021_7_18","PRO","7","18","18","Zo, mu sha zurfin ƙauna har safe; bari mu ji wa ranmu daɗi da ƙauna! ");
INSERT INTO hausa_vpl VALUES ("PR7_19","021_7_19","PRO","7","19","19","Mijina ba ya gida; ya yi tafiya mai nisa. ");
INSERT INTO hausa_vpl VALUES ("PR7_20","021_7_20","PRO","7","20","20","Ya ɗauki jakarsa cike da kuɗi ba zai kuwa dawo gida ba sai tsakiyar wata.” ");
INSERT INTO hausa_vpl VALUES ("PR7_21","021_7_21","PRO","7","21","21","Da kalmomin rarrashi ta sa ya kauce; ta ɗauki hankalinsa da sulɓin maganarta. ");
INSERT INTO hausa_vpl VALUES ("PR7_22","021_7_22","PRO","7","22","22","Nan take, ya bi ta kamar saniyar da za a kai mayanka, kamar wawa zuwa wurin da za a ba shi horo ");
INSERT INTO hausa_vpl VALUES ("PR7_23","021_7_23","PRO","7","23","23","sai da kibiya ta soki hantarsa, kamar tsuntsun da ya ruga cikin tarko, ba tare da sani zai zama sanadin ransa ba. ");
INSERT INTO hausa_vpl VALUES ("PR7_24","021_7_24","PRO","7","24","24","Yanzu fa, ’ya’yana, ku saurare ni; ku kasa kunne ga abin da nake faɗa. ");
INSERT INTO hausa_vpl VALUES ("PR7_25","021_7_25","PRO","7","25","25","Kada ku bar zuciyarku ta juya zuwa hanyoyinta ko ku kauce zuwa hanyoyinta. ");
INSERT INTO hausa_vpl VALUES ("PR7_26","021_7_26","PRO","7","26","26","Ta zama sanadin fāɗuwar yawanci; kisan da ta yi ba ta ƙidayuwa. ");
INSERT INTO hausa_vpl VALUES ("PR7_27","021_7_27","PRO","7","27","27","Gidanta babbar hanya ce zuwa kabari mai yin jagora zuwa ɗakunan lahira. ");
INSERT INTO hausa_vpl VALUES ("PR8_1","021_8_1","PRO","8","1","1","Hikima ba ta yin kira ne? Fahimi ba ya tā da muryarsa ne? ");
INSERT INTO hausa_vpl VALUES ("PR8_2","021_8_2","PRO","8","2","2","A ƙwanƙoli a kan hanya, inda hanyoyi suka haɗu, ta ɗauki matsayinta; ");
INSERT INTO hausa_vpl VALUES ("PR8_3","021_8_3","PRO","8","3","3","kusa da ƙofofin shiga cikin birni, a mashigai, ta tā da murya, ");
INSERT INTO hausa_vpl VALUES ("PR8_4","021_8_4","PRO","8","4","4","“Gare ku, ya mutane, nake kira; na tā da muryata ga dukan ’yan adam. ");
INSERT INTO hausa_vpl VALUES ("PR8_5","021_8_5","PRO","8","5","5","Ku da kuke marasa azanci, ku yi hankali; ku da kuke wawaye, ku nemi fahimi. ");
INSERT INTO hausa_vpl VALUES ("PR8_6","021_8_6","PRO","8","6","6","Ku saurara, gama ina da abubuwa masu darajan da zan faɗa; na buɗe leɓunana don in faɗa abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("PR8_7","021_8_7","PRO","8","7","7","Bakina yana magana abin da yake gaskiya, gama leɓunana sun ƙi mugunta. ");
INSERT INTO hausa_vpl VALUES ("PR8_8","021_8_8","PRO","8","8","8","Dukan kalmomin bakina suna da adalci; babu waninsu da ya karkace ko kuwa ƙarya ne. ");
INSERT INTO hausa_vpl VALUES ("PR8_9","021_8_9","PRO","8","9","9","Ga mai tunani dukansu daidai ne; ba su da laifi ga waɗanda suke da sani. ");
INSERT INTO hausa_vpl VALUES ("PR8_10","021_8_10","PRO","8","10","10","Ku zaɓi umarnina a maimakon azurfa, sani a maimakon zinariya zalla, ");
INSERT INTO hausa_vpl VALUES ("PR8_11","021_8_11","PRO","8","11","11","gama hikima ta fi lu’ulu’ai daraja, kuma ba abin da kake sha’awa da za a kwatanta da ita. ");
INSERT INTO hausa_vpl VALUES ("PR8_12","021_8_12","PRO","8","12","12","“Ni, hikima, ina zama tare da hankali; ina da sani da iya rarrabewa. ");
INSERT INTO hausa_vpl VALUES ("PR8_13","021_8_13","PRO","8","13","13","Jin tsoron Ubangiji shi ne ƙin mugunta; ina ƙin girman kai da fariya, halin mugunta da kuma muguwar magana. ");
INSERT INTO hausa_vpl VALUES ("PR8_14","021_8_14","PRO","8","14","14","Shawara da yin tunani mai kyau nawa ne; ina da fahimi da kuma iko. ");
INSERT INTO hausa_vpl VALUES ("PR8_15","021_8_15","PRO","8","15","15","Ta wurina sarakuna suke mulki masu mulki kuma suke yin dokokin da suke da adalci; ");
INSERT INTO hausa_vpl VALUES ("PR8_16","021_8_16","PRO","8","16","16","ta wurina sarakuna suke mulki, da kuma dukan manyan mutanen da suke mulkin duniya. ");
INSERT INTO hausa_vpl VALUES ("PR8_17","021_8_17","PRO","8","17","17","Ina ƙaunar waɗanda suke ƙaunata, kuma waɗanda suke nemana sukan same ni. ");
INSERT INTO hausa_vpl VALUES ("PR8_18","021_8_18","PRO","8","18","18","Tare da ni akwai wadata da girmamawa, dukiya da wadata masu dawwama. ");
INSERT INTO hausa_vpl VALUES ("PR8_19","021_8_19","PRO","8","19","19","’Ya’yan itacena sun fi zinariya zalla; amfanin gonar da nake bayar ya fi azurfa mafi kyau. ");
INSERT INTO hausa_vpl VALUES ("PR8_20","021_8_20","PRO","8","20","20","Ina tafiya a hanyar adalci, a kan hanyoyin gaskiya, ");
INSERT INTO hausa_vpl VALUES ("PR8_21","021_8_21","PRO","8","21","21","ina ba da wadata ga waɗanda suke ƙaunata ina sa wuraren ajiyarsu su cika. ");
INSERT INTO hausa_vpl VALUES ("PR8_22","021_8_22","PRO","8","22","22","“Ubangiji ya kawo ni a matsayi na farko na ayyukansa, kafin ayyukansa na tuntuni; ");
INSERT INTO hausa_vpl VALUES ("PR8_23","021_8_23","PRO","8","23","23","an naɗa ni tun fil azal, daga farko, kafin duniya ta kasance. ");
INSERT INTO hausa_vpl VALUES ("PR8_24","021_8_24","PRO","8","24","24","Sa’ad da babu tekuna, aka haife ni, sa’ad da babu maɓulɓulai masu ruwa; ");
INSERT INTO hausa_vpl VALUES ("PR8_25","021_8_25","PRO","8","25","25","kafin a kafa duwatsu a wurarensu, kafin tuddai ma, an haife ni, ");
INSERT INTO hausa_vpl VALUES ("PR8_26","021_8_26","PRO","8","26","26","kafin ya yi duniya ko gonaki ko wata ƙurar duniya. ");
INSERT INTO hausa_vpl VALUES ("PR8_27","021_8_27","PRO","8","27","27","Ina nan sa’ad da ya kafa sammai a wurarensu, sa’ad da ya shata sararin sama a kan fuskar zurfafa, ");
INSERT INTO hausa_vpl VALUES ("PR8_28","021_8_28","PRO","8","28","28","sa’ad da ya kafa gizagizai a bisa ya kuma kafa maɓulɓulan zurfafa daram, ");
INSERT INTO hausa_vpl VALUES ("PR8_29","021_8_29","PRO","8","29","29","sa’ad da ya ba wa teku iyakarsa domin kada ruwaye su zarce umarninsa, da kuma sa’ad da ya shata tussan duniya. ");
INSERT INTO hausa_vpl VALUES ("PR8_30","021_8_30","PRO","8","30","30","A lokacin ni ne mai tsara abubuwa a gefensa. Na cika da murna kowace rana, kullum ina farin ciki a gabansa, ");
INSERT INTO hausa_vpl VALUES ("PR8_31","021_8_31","PRO","8","31","31","ina farin ciki da dukan duniyarsa ina murna da ’yan adam. ");
INSERT INTO hausa_vpl VALUES ("PR8_32","021_8_32","PRO","8","32","32","“Yanzu fa, ’ya’yana, ku saurare ni; masu albarka ne waɗanda suke kiyaye hanyoyina. ");
INSERT INTO hausa_vpl VALUES ("PR8_33","021_8_33","PRO","8","33","33","Ku saurari umarnina ku kuma zama masu hikima; kada ku ƙyale ta. ");
INSERT INTO hausa_vpl VALUES ("PR8_34","021_8_34","PRO","8","34","34","Mai albarka ne wanda ya saurare ni; yana tsaro kullum a ƙofofina, yana jira a ƙofar shigata. ");
INSERT INTO hausa_vpl VALUES ("PR8_35","021_8_35","PRO","8","35","35","Gama duk wanda ya same ni ya sami rai zai kuma sami tagomashi daga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PR8_36","021_8_36","PRO","8","36","36","Amma duk wanda ya kāsa samuna ya cuci kansa; dukan waɗanda suke ƙina suna ƙaunar mutuwa ke nan.” ");
INSERT INTO hausa_vpl VALUES ("PR9_1","021_9_1","PRO","9","1","1","Hikima ta gina gidanta; ta yi ginshiƙansa bakwai. ");
INSERT INTO hausa_vpl VALUES ("PR9_2","021_9_2","PRO","9","2","2","Ta shirya abincinta gauraye da ruwan inabinta; ta kuma shirya teburinta. ");
INSERT INTO hausa_vpl VALUES ("PR9_3","021_9_3","PRO","9","3","3","Ta aiki bayinta mata, tana kuma kira daga wurare masu tsayi na birnin. ");
INSERT INTO hausa_vpl VALUES ("PR9_4","021_9_4","PRO","9","4","4","“Bari dukan waɗanda suke marasa azanci su zo nan ciki!” Tana faɗa wa marasa hankali. ");
INSERT INTO hausa_vpl VALUES ("PR9_5","021_9_5","PRO","9","5","5","“Ku zo, ku ci abincina da ruwan inabin da na gauraye. ");
INSERT INTO hausa_vpl VALUES ("PR9_6","021_9_6","PRO","9","6","6","Ku bar hanyoyinku marasa hankali za ku kuwa rayu; yi tafiya a hanyar fahimi. ");
INSERT INTO hausa_vpl VALUES ("PR9_7","021_9_7","PRO","9","7","7","“Duk wanda ya yi wa mai ba’a gyara yana gayyatar zagi duk wanda ya tsawata wa mugu yakan gamu da cin mutunci. ");
INSERT INTO hausa_vpl VALUES ("PR9_8","021_9_8","PRO","9","8","8","Kada ka tsawata wa masu ba’a gama za su ƙi ka; ka tsawata wa mai hikima zai kuwa ƙaunace ka. ");
INSERT INTO hausa_vpl VALUES ("PR9_9","021_9_9","PRO","9","9","9","Ka koya wa mai hikima zai kuwa ƙara hikima; ka koya wa mai adalci zai kuwa ƙara koyonsa. ");
INSERT INTO hausa_vpl VALUES ("PR9_10","021_9_10","PRO","9","10","10","“Tsoron Ubangiji shi ne mafarin hikima, sanin Mai Tsarki kuwa fahimi ne. ");
INSERT INTO hausa_vpl VALUES ("PR9_11","021_9_11","PRO","9","11","11","Gama ta wurina kwanakinka za su yi yawa, za a kuwa ƙara wa ranka shekaru. ");
INSERT INTO hausa_vpl VALUES ("PR9_12","021_9_12","PRO","9","12","12","In kana da hikima, hikimarka za tă ba ka lada; in kai mai ba’a ne, kai kaɗai za ka sha wahala.” ");
INSERT INTO hausa_vpl VALUES ("PR9_13","021_9_13","PRO","9","13","13","Wawancin mace a bayyane yake; ba ta da ɗa’a kuma ba ta da sani. ");
INSERT INTO hausa_vpl VALUES ("PR9_14","021_9_14","PRO","9","14","14","Takan zauna a ƙofar gidanta, a wurin zama a wurin mafi tsayi na birni, ");
INSERT INTO hausa_vpl VALUES ("PR9_15","021_9_15","PRO","9","15","15","tana kira ga masu wucewa, waɗanda suke tafiya kai tsaye a hanyarsu. ");
INSERT INTO hausa_vpl VALUES ("PR9_16","021_9_16","PRO","9","16","16","“Bari dukan waɗanda suke marasa azanci su zo cikin nan!” Tana ce wa marasa hankali. ");
INSERT INTO hausa_vpl VALUES ("PR9_17","021_9_17","PRO","9","17","17","“Ruwan da aka sata ya fi daɗi; abincin da aka ci a ɓoye ya fi daɗi!” ");
INSERT INTO hausa_vpl VALUES ("PR9_18","021_9_18","PRO","9","18","18","Amma ba su san cewa matattu suna a can ba, cewa baƙinta suna a can cikin zurfin kabari ba. ");
INSERT INTO hausa_vpl VALUES ("PR10_1","021_10_1","PRO","10","1","1","Karin maganar Solomon. Ɗa mai hikima yakan kawo wa mahaifinsa farin ciki, amma wawan ɗa kan sa wa mahaifiyarsa baƙin ciki. ");
INSERT INTO hausa_vpl VALUES ("PR10_2","021_10_2","PRO","10","2","2","Dukiyar da aka samu a hanyar da ba tă dace ba, ba ta da albarka, amma adalci kan ceci mutum daga mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PR10_3","021_10_3","PRO","10","3","3","Ubangiji ba ya barin mai adalci da yunwa amma yakan lalace burin mugu. ");
INSERT INTO hausa_vpl VALUES ("PR10_4","021_10_4","PRO","10","4","4","Ragwanci kan sa mutum yă zama matalauci, amma aiki tuƙuru kan ba da dukiya. ");
INSERT INTO hausa_vpl VALUES ("PR10_5","021_10_5","PRO","10","5","5","Shi da ya tattara hatsi da rani ɗa ne mai hikima, amma shi da yakan yi barci a lokacin girbi ɗa ne wanda ya zama abin kunya. ");
INSERT INTO hausa_vpl VALUES ("PR10_6","021_10_6","PRO","10","6","6","Albarka kan zauna a kan mai adalci kamar rawani, amma rikici kan sha bakin mugu. ");
INSERT INTO hausa_vpl VALUES ("PR10_7","021_10_7","PRO","10","7","7","Tunawa da mai adalci albarka ne amma sunan mugu zai ruɓe. ");
INSERT INTO hausa_vpl VALUES ("PR10_8","021_10_8","PRO","10","8","8","Mai hikima a zuciya yakan yarda da umarni amma surutun wawa kan kai ga lalaci. ");
INSERT INTO hausa_vpl VALUES ("PR10_9","021_10_9","PRO","10","9","9","Mai mutunci yana tafiya lafiya, amma shi da yake tafiya a karkatattun hanyoyi za a kama shi. ");
INSERT INTO hausa_vpl VALUES ("PR10_10","021_10_10","PRO","10","10","10","Shi da ya ƙyifta ido da mugunta kan jawo baƙin ciki surutun wawa kuma kan zo da lalaci. ");
INSERT INTO hausa_vpl VALUES ("PR10_11","021_10_11","PRO","10","11","11","Bakin adali maɓulɓulan rai ne, amma kalmar mugun takan ɓoye makircinsa. ");
INSERT INTO hausa_vpl VALUES ("PR10_12","021_10_12","PRO","10","12","12","Ƙiyayya kan haddasa wahala, amma ƙauna kan rufe dukan laifofi. ");
INSERT INTO hausa_vpl VALUES ("PR10_13","021_10_13","PRO","10","13","13","Ana samun hikima a leɓunan masu fahimi, amma bulala domin bayan marasa azanci ne. ");
INSERT INTO hausa_vpl VALUES ("PR10_14","021_10_14","PRO","10","14","14","Mai hikima kan yi ajiyar sani, amma bakin wawa kan gayyaci lalaci. ");
INSERT INTO hausa_vpl VALUES ("PR10_15","021_10_15","PRO","10","15","15","Dukiyar masu arziki yakan zama mafakar birninsu, amma talauci shi ne lalacin matalauci. ");
INSERT INTO hausa_vpl VALUES ("PR10_16","021_10_16","PRO","10","16","16","Hakkin adalai kan kawo musu rai, amma albashin mugaye kan kawo musu hukunci. ");
INSERT INTO hausa_vpl VALUES ("PR10_17","021_10_17","PRO","10","17","17","Duk wanda ya mai da hankali ga horo kan nuna hanyar rai, amma duk wanda ya ƙyale gyara kan sa waɗansu su kauce. ");
INSERT INTO hausa_vpl VALUES ("PR10_18","021_10_18","PRO","10","18","18","Duk wanda ya ɓoye ƙiyayyarsa yana da ƙarya a leɓunansa, duk kuma wanda yake baza ƙarairayi wawa ne. ");
INSERT INTO hausa_vpl VALUES ("PR10_19","021_10_19","PRO","10","19","19","Sa’ad da magana ta yi yawa, ba a rasa zunubi a ciki, amma shi da ya ƙame harshensa mai hikima ne. ");
INSERT INTO hausa_vpl VALUES ("PR10_20","021_10_20","PRO","10","20","20","Harshen adali azurfa ce zalla, amma zuciyar mugu ba ta da wani amfani. ");
INSERT INTO hausa_vpl VALUES ("PR10_21","021_10_21","PRO","10","21","21","Leɓunan adalai kan amfane yawanci, amma wawa kan mutu saboda rashin azanci. ");
INSERT INTO hausa_vpl VALUES ("PR10_22","021_10_22","PRO","10","22","22","Albarkar Ubangiji kan kawo wadata, ba ya kuma ƙara wahala a kai. ");
INSERT INTO hausa_vpl VALUES ("PR10_23","021_10_23","PRO","10","23","23","Wawa yakan ji daɗi halin mugunta, amma mutum mai fahimi kan ji daɗin hikima. ");
INSERT INTO hausa_vpl VALUES ("PR10_24","021_10_24","PRO","10","24","24","Abin da mugu ke tsoro shi ne zai same shi; abin da adali ke bukata yakan sami biyan bukata. ");
INSERT INTO hausa_vpl VALUES ("PR10_25","021_10_25","PRO","10","25","25","Sa’ad da hadiri ya taso, yakan watsar da mugaye, amma adalai za su tsaya daram har abada. ");
INSERT INTO hausa_vpl VALUES ("PR10_26","021_10_26","PRO","10","26","26","Kamar yadda ruwan tsami yake ga haƙora hayaƙi kuma ga idanu, haka malalaci yake ga wanda ya aike shi. ");
INSERT INTO hausa_vpl VALUES ("PR10_27","021_10_27","PRO","10","27","27","Tsoron Ubangiji kan ƙara tsawon rai, amma akan gajartar da shekarun mugaye. ");
INSERT INTO hausa_vpl VALUES ("PR10_28","021_10_28","PRO","10","28","28","Abin da adali yake sa rai yakan kai ga farin ciki, amma sa zuciyar mugu ba ya haifar da kome. ");
INSERT INTO hausa_vpl VALUES ("PR10_29","021_10_29","PRO","10","29","29","Hanyar Ubangiji mafaka ce ga adalai amma lalaci ne ga waɗanda suke aikata mugunta. ");
INSERT INTO hausa_vpl VALUES ("PR10_30","021_10_30","PRO","10","30","30","Ba za a taɓa tumɓuke masu adalci ba, amma mugaye ba za su ci gaba da kasance a ƙasar ba. ");
INSERT INTO hausa_vpl VALUES ("PR10_31","021_10_31","PRO","10","31","31","Bakin adalai kan fitar da hikima, amma za a dakatar da mugun harshe. ");
INSERT INTO hausa_vpl VALUES ("PR10_32","021_10_32","PRO","10","32","32","Leɓunan adalai sun san abin da ya dace, amma bakunan mugaye sun san abin da yake mugu ne kawai. ");
INSERT INTO hausa_vpl VALUES ("PR11_1","021_11_1","PRO","11","1","1","Ubangiji yana ƙyamar ma’aunan zamba, amma ma’aunin da suke daidai ne abin farin cikinsa. ");
INSERT INTO hausa_vpl VALUES ("PR11_2","021_11_2","PRO","11","2","2","Sa’ad da girman kai ya zo, sai shan kunya ta zo, amma hikima kan zo tare da ƙasƙantar da kai. ");
INSERT INTO hausa_vpl VALUES ("PR11_3","021_11_3","PRO","11","3","3","Mutuncin masu aikata gaskiya takan bi da su, amma marasa aminci sukan hallaka ta wurin cin amanar da suke yi. ");
INSERT INTO hausa_vpl VALUES ("PR11_4","021_11_4","PRO","11","4","4","Dukiya ba ta da amfani a ranar fushi, amma adalci kan yi ceto daga mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PR11_5","021_11_5","PRO","11","5","5","Adalcin marasa laifi kan miƙe hanyarsu, amma akan ƙasƙantar da mugaye ta wurin muguntarsu. ");
INSERT INTO hausa_vpl VALUES ("PR11_6","021_11_6","PRO","11","6","6","Adalcin masu aikata gaskiya kan cece su, amma rashin aminci tarko ne ga mugayen sha’awace-sha’awace. ");
INSERT INTO hausa_vpl VALUES ("PR11_7","021_11_7","PRO","11","7","7","Sa’ad da mugu ya mutu, sa zuciyarsa kan hallaka; dukan abin da ya sa zuciya daga ikonsa ba ya amfana kome. ");
INSERT INTO hausa_vpl VALUES ("PR11_8","021_11_8","PRO","11","8","8","Akan kuɓutar da mai adalci daga wahala, sai ta dawo wa mugu a maimako. ");
INSERT INTO hausa_vpl VALUES ("PR11_9","021_11_9","PRO","11","9","9","Da bakinsa marar sanin Allah kan hallaka maƙwabcinsa, amma ta wurin sani mai adalci kan kuɓuta. ");
INSERT INTO hausa_vpl VALUES ("PR11_10","021_11_10","PRO","11","10","10","Sa’ad da adali ya yi nasara, birnin kan yi farin ciki; sa’ad da mugu ya hallaka, akwai sowa ta farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PR11_11","021_11_11","PRO","11","11","11","Ta wurin albarkar mai aikata gaskiya birni kan ƙasaita, amma ta wurin bakin mugu akan hallaka birnin. ");
INSERT INTO hausa_vpl VALUES ("PR11_12","021_11_12","PRO","11","12","12","Mutum da ba shi da azanci kan ki maƙwabci, amma mutum mai fahimi kan ƙame harshensa. ");
INSERT INTO hausa_vpl VALUES ("PR11_13","021_11_13","PRO","11","13","13","Gulma yakan lalace yarda, amma mutum mai aminci kan kiyaye asiri. ");
INSERT INTO hausa_vpl VALUES ("PR11_14","021_11_14","PRO","11","14","14","Saboda rashin jagora al’umma takan fāɗi, amma masu ba da shawara da yawa kan tabbatar da nasara. ");
INSERT INTO hausa_vpl VALUES ("PR11_15","021_11_15","PRO","11","15","15","Duk wanda ya ɗauki lamunin wani tabbatacce zai sha wahala, amma duk wanda ya ƙi ya sa hannu a ɗaukar lamuni ba ruwansa. ");
INSERT INTO hausa_vpl VALUES ("PR11_16","021_11_16","PRO","11","16","16","Mace mai hankali na samu bangirma, amma azzalumai za su sami dukiya. ");
INSERT INTO hausa_vpl VALUES ("PR11_17","021_11_17","PRO","11","17","17","Mutumin kirki kan ribance kansa, amma mugu kan kawo wa kansa wahala. ");
INSERT INTO hausa_vpl VALUES ("PR11_18","021_11_18","PRO","11","18","18","Mugun mutum kan sami albashin ƙarya amma shi da ya shuka adalci zai girbe lada tabbatacce. ");
INSERT INTO hausa_vpl VALUES ("PR11_19","021_11_19","PRO","11","19","19","Mutum mai adalci da gaske yakan sami rai, amma shi da ya duƙufa ga aikata mugunta kan tarar da mutuwarsa. ");
INSERT INTO hausa_vpl VALUES ("PR11_20","021_11_20","PRO","11","20","20","Ubangiji yana ƙyamar mutane masu muguwar zuciya amma yana jin daɗin waɗanda hanyoyinsu ba su da laifi. ");
INSERT INTO hausa_vpl VALUES ("PR11_21","021_11_21","PRO","11","21","21","Ka tabbata da wannan. Mugaye ba za su tafi babu hukunci ba, amma waɗanda suke masu adalci za su tafi babu hukunci. ");
INSERT INTO hausa_vpl VALUES ("PR11_22","021_11_22","PRO","11","22","22","Kamar zinariya a hancin alade haka kyan mace wadda ba ta da hankali. ");
INSERT INTO hausa_vpl VALUES ("PR11_23","021_11_23","PRO","11","23","23","Sha’awar adalai kan ƙare kawai a aikata alheri, amma sa zuciyar mugaye kan ƙarasa kawai a fushi. ");
INSERT INTO hausa_vpl VALUES ("PR11_24","021_11_24","PRO","11","24","24","Wani mutum kan bayar hannu sake, duk da haka yakan sami fiye; wani yakan riƙe abin da ba nasa ba, amma sai ya ƙarasa cikin talauci. ");
INSERT INTO hausa_vpl VALUES ("PR11_25","021_11_25","PRO","11","25","25","Mutum mai kyauta zai azurta; shi da yakan taimake waɗansu, za a taimake shi. ");
INSERT INTO hausa_vpl VALUES ("PR11_26","021_11_26","PRO","11","26","26","Mutane kan la’anci mai ɓoye hatsi yana jira ya yi tsada, amma albarka kan zauna a kan wanda yake niyya ya sayar. ");
INSERT INTO hausa_vpl VALUES ("PR11_27","021_11_27","PRO","11","27","27","Duk mai nema alheri kan sami alheri, amma mugu kan zo wa wanda yake nemansa. ");
INSERT INTO hausa_vpl VALUES ("PR11_28","021_11_28","PRO","11","28","28","Duk wanda ya dogara ga arzikinsa zai fāɗi, amma adali zai yi nasara kamar koren ganye. ");
INSERT INTO hausa_vpl VALUES ("PR11_29","021_11_29","PRO","11","29","29","Duk wanda ya kawo wahala wa iyalinsa zai gāji iska kawai, kuma wawa zai zama bawan masu hikima. ");
INSERT INTO hausa_vpl VALUES ("PR11_30","021_11_30","PRO","11","30","30","’Ya’yan itacen adali itacen rai ne, kuma duk mai samun rayuka mai hikima ne. ");
INSERT INTO hausa_vpl VALUES ("PR11_31","021_11_31","PRO","11","31","31","In masu adalci sun sami abin da ya dace da su a duniya, yaya zai zama ga marasa sanin Allah da kuma masu zunubi! ");
INSERT INTO hausa_vpl VALUES ("PR12_1","021_12_1","PRO","12","1","1","Duk mai ƙaunar horo yana ƙaunar sani, amma duk mai ƙin gyara wawa ne. ");
INSERT INTO hausa_vpl VALUES ("PR12_2","021_12_2","PRO","12","2","2","Mutumin kirki kan sami tagomashi daga Ubangiji, amma Ubangiji yakan hukunta mai son yin wayo. ");
INSERT INTO hausa_vpl VALUES ("PR12_3","021_12_3","PRO","12","3","3","Ba yadda mutum zai kahu ta wurin aikata mugunta, amma ba za a tumɓuke adali ba. ");
INSERT INTO hausa_vpl VALUES ("PR12_4","021_12_4","PRO","12","4","4","Mace mai halin kirki rawanin mijinta ne, amma mace marar kunya tana kama da ciwo a ƙasusuwansa. ");
INSERT INTO hausa_vpl VALUES ("PR12_5","021_12_5","PRO","12","5","5","Shirye-shiryen masu adalci daidai ne, amma shawarar mugaye ruɗu ne. ");
INSERT INTO hausa_vpl VALUES ("PR12_6","021_12_6","PRO","12","6","6","Kalmomin mugu sukan kwanta suna jira su yi kisankai, amma jawabin masu aikata gaskiya kan kuɓutar da su. ");
INSERT INTO hausa_vpl VALUES ("PR12_7","021_12_7","PRO","12","7","7","Akan tumɓuke mugaye ba a ƙara ganinsu, amma gidan masu adalci kan tsaya daram. ");
INSERT INTO hausa_vpl VALUES ("PR12_8","021_12_8","PRO","12","8","8","Akan yabi mutum bisa ga hikimarsa, amma mutane marasa azanci akan rena su. ");
INSERT INTO hausa_vpl VALUES ("PR12_9","021_12_9","PRO","12","9","9","Gara ka zama kai ba kome ba ne amma kana da bawa da ka mai da kanka kai wani ne alhali kuwa ba ka da abinci. ");
INSERT INTO hausa_vpl VALUES ("PR12_10","021_12_10","PRO","12","10","10","Mai adalci kan kula da bukatun dabbobinsa, amma halaye mafi kyau na mugaye su ne ƙeta. ");
INSERT INTO hausa_vpl VALUES ("PR12_11","021_12_11","PRO","12","11","11","Duk wanda ya nome gonarsa zai sami abinci a yalwace, amma shi da yake naushin iska marar azanci ne. ");
INSERT INTO hausa_vpl VALUES ("PR12_12","021_12_12","PRO","12","12","12","Mugaye suna sha’awar ganimar mugayen mutane, amma saiwar masu adalci kan haɓaka. ");
INSERT INTO hausa_vpl VALUES ("PR12_13","021_12_13","PRO","12","13","13","Mugun mutum kan fāɗa a tarkon maganarsa ta zunubi, amma adali kan kuɓuta daga wahala. ");
INSERT INTO hausa_vpl VALUES ("PR12_14","021_12_14","PRO","12","14","14","Daga abubuwan da suke fitowa daga leɓunansa mutum kan cika da abubuwa masu kyau tabbatacce yadda aikin hannuwansa suke ba shi lada. ");
INSERT INTO hausa_vpl VALUES ("PR12_15","021_12_15","PRO","12","15","15","Hanyar wawa daidai take a gare shi, amma mai hikima kan saurari shawara. ");
INSERT INTO hausa_vpl VALUES ("PR12_16","021_12_16","PRO","12","16","16","Wawa kan nuna fushinsa nan take, amma mai la’akari kan ƙyale zargi. ");
INSERT INTO hausa_vpl VALUES ("PR12_17","021_12_17","PRO","12","17","17","Mashaidin gaskiya kan ba da shaidar gaskiya, amma mashaidin ƙarya yana baza ƙarairayi ne. ");
INSERT INTO hausa_vpl VALUES ("PR12_18","021_12_18","PRO","12","18","18","Maganganun rashin tunani sukan soki mutum kamar takobi, amma harshen mai hikima kan kawo warkarwa. ");
INSERT INTO hausa_vpl VALUES ("PR12_19","021_12_19","PRO","12","19","19","Leɓunan gaskiya kan dawwama har abada, amma harshen ƙarya yakan dawwama na ɗan lokaci ne kawai. ");
INSERT INTO hausa_vpl VALUES ("PR12_20","021_12_20","PRO","12","20","20","Akwai ruɗu a zukatan waɗanda suke ƙulla mugunta, amma waɗanda suke aikata alheri za su yi farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PR12_21","021_12_21","PRO","12","21","21","Ba wani lahanin da zai sami masu adalci, amma mugaye suna da nasu cike da wahala. ");
INSERT INTO hausa_vpl VALUES ("PR12_22","021_12_22","PRO","12","22","22","Ubangiji yana ƙyamar leɓunan masu ƙarya, amma yana jin daɗin mutanen da suke masu gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PR12_23","021_12_23","PRO","12","23","23","Mai la’akari kan kiyaye saninsa wa kansa, amma zuciyar wawa kan yi ta tallar wawanci. ");
INSERT INTO hausa_vpl VALUES ("PR12_24","021_12_24","PRO","12","24","24","Hannuwan masu aiki tuƙuru za su yi mulki, amma ragwanci kan ƙarasa a aikin bauta. ");
INSERT INTO hausa_vpl VALUES ("PR12_25","021_12_25","PRO","12","25","25","Zuciya mai damuwa takan naƙasar da mutum, amma maganar alheri kan faranta masa rai. ");
INSERT INTO hausa_vpl VALUES ("PR12_26","021_12_26","PRO","12","26","26","Adali yakan yi hankali a abokantaka, amma hanyar mugaye kan kai su ga kaucewa. ");
INSERT INTO hausa_vpl VALUES ("PR12_27","021_12_27","PRO","12","27","27","Rago ba ya gashin abin da ya kama daga farauta, amma mai aiki tuƙuru yakan ɗauki mallakarsa da muhimmanci. ");
INSERT INTO hausa_vpl VALUES ("PR12_28","021_12_28","PRO","12","28","28","A hanyar adalci akwai rai; a wannan hanya akwai rashin mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PR13_1","021_13_1","PRO","13","1","1","Ɗa mai hikima yakan mai da hankali ga umarnin mahaifinsa, amma mai ba’a ba ya sauraran kwaɓi. ");
INSERT INTO hausa_vpl VALUES ("PR13_2","021_13_2","PRO","13","2","2","Daga abin da ya fito leɓunan mutum ne mutum kan ji daɗin abubuwa masu kyau, amma marar aminci yakan ƙosa ya tā-da-na-zaune-tsaye. ");
INSERT INTO hausa_vpl VALUES ("PR13_3","021_13_3","PRO","13","3","3","Duk mai lura da leɓunansa yakan lura da ransa, amma duk mai magana da haushi zai kai ga lalaci. ");
INSERT INTO hausa_vpl VALUES ("PR13_4","021_13_4","PRO","13","4","4","Rago ya ƙosa ya sami wani abu ainun amma ba ya samun kome, amma sha’awar mai aiki tuƙuru yakan ƙoshi sosai. ");
INSERT INTO hausa_vpl VALUES ("PR13_5","021_13_5","PRO","13","5","5","Adali yana ƙin abin da yake ƙarya, amma mugu kan jawo kunya da ƙasƙanci. ");
INSERT INTO hausa_vpl VALUES ("PR13_6","021_13_6","PRO","13","6","6","Adalci yakan lura da mutum mai mutunci, amma mugunta takan sha kan mai zunubi. ");
INSERT INTO hausa_vpl VALUES ("PR13_7","021_13_7","PRO","13","7","7","Wani mutum yakan ɗauki kansa mai arziki ne, alhali ba shi da kome, wani ya ɗauki kansa shi matalauci ne, alhali shi mawadaci ne ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("PR13_8","021_13_8","PRO","13","8","8","Arzikin mutum zai iya kuɓutar da ransa, amma matalauci ba ya jin barazana. ");
INSERT INTO hausa_vpl VALUES ("PR13_9","021_13_9","PRO","13","9","9","Hasken masu adalci kan haskaka ƙwarai, amma fitilar mugaye mutuwa take. ");
INSERT INTO hausa_vpl VALUES ("PR13_10","021_13_10","PRO","13","10","10","Girmankai kan jawo faɗa ne kawai, amma hikima tana samuwa a waɗanda suke jin shawara. ");
INSERT INTO hausa_vpl VALUES ("PR13_11","021_13_11","PRO","13","11","11","Kuɗin da aka same su a rashin gaskiya yakan ɓace da sauri, amma duk wanda ya tara kuɗi kaɗan-kaɗan za su yi ta ƙaruwa. ");
INSERT INTO hausa_vpl VALUES ("PR13_12","021_13_12","PRO","13","12","12","Sa zuciyar da aka ɗaga zuwa gaba kan sa zuciya tă yi ciwo, amma marmarin da aka ƙosar yana kamar itacen rai. ");
INSERT INTO hausa_vpl VALUES ("PR13_13","021_13_13","PRO","13","13","13","Duk wanda ya rena umarni zai ɗanɗana ƙodarsa, amma duk wanda ya yi biyayya da umarni zai sami lada. ");
INSERT INTO hausa_vpl VALUES ("PR13_14","021_13_14","PRO","13","14","14","Koyarwar mai hikima maɓulɓulan rai ne, mai juyar da mutum daga tarkon mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PR13_15","021_13_15","PRO","13","15","15","Fahimta mai kyau kan sami tagomashi, amma hanyar marar aminci tana da wuya. ");
INSERT INTO hausa_vpl VALUES ("PR13_16","021_13_16","PRO","13","16","16","Kowane mai azanci yakan nuna sani, amma wawa yakan yi tallen wawancinsa. ");
INSERT INTO hausa_vpl VALUES ("PR13_17","021_13_17","PRO","13","17","17","Mugun ɗan saƙo kan shiga wahala, amma jakadan da mai aminci yakan kawo warkarwa. ");
INSERT INTO hausa_vpl VALUES ("PR13_18","021_13_18","PRO","13","18","18","Duk wanda ya ƙyale horo yakan kai ga talauci da kuma kunya, amma duk wanda ya karɓi gyara yakan sami girma. ");
INSERT INTO hausa_vpl VALUES ("PR13_19","021_13_19","PRO","13","19","19","Marmarin da aka cika yana da daɗi ga rai, amma wawa yana ƙyamar juyewa daga mugunta. ");
INSERT INTO hausa_vpl VALUES ("PR13_20","021_13_20","PRO","13","20","20","Shi da yake tafiya tare da masu hikima yakan ƙaru da hikima, amma abokin wawaye zai yi fama da lahani. ");
INSERT INTO hausa_vpl VALUES ("PR13_21","021_13_21","PRO","13","21","21","Rashin sa’a kan fafare mai zunubi, amma wadata ce ladar adali. ");
INSERT INTO hausa_vpl VALUES ("PR13_22","021_13_22","PRO","13","22","22","Mutumin kirki kan bar gādo wa ’ya’ya ’ya’yansa, amma arzikin mai zunubi ajiye ne da aka yi wa mai adalci. ");
INSERT INTO hausa_vpl VALUES ("PR13_23","021_13_23","PRO","13","23","23","Gonar matalauci za tă iya ba da abinci a yalwace, amma rashin adalci kan share shi tas. ");
INSERT INTO hausa_vpl VALUES ("PR13_24","021_13_24","PRO","13","24","24","Duk wanda ba ya horon ɗansa ba ƙaunarsa yake yi ba, amma duk mai ƙaunarsa yakan kula ya hore shi. ");
INSERT INTO hausa_vpl VALUES ("PR13_25","021_13_25","PRO","13","25","25","Masu adalci sukan ci isashen abinci, amma cikin mugaye na fama da yunwa. ");
INSERT INTO hausa_vpl VALUES ("PR14_1","021_14_1","PRO","14","1","1","Mace mai hikima kan gina gidanta, amma da hannunta wawiya takan rushe shi ƙasa. ");
INSERT INTO hausa_vpl VALUES ("PR14_2","021_14_2","PRO","14","2","2","Wanda tafiyarsa ta aikata gaskiya ce kan ji tsoron Ubangiji, amma wanda hanyoyinsa ba a kan gaskiya ba ne yakan rena shi. ");
INSERT INTO hausa_vpl VALUES ("PR14_3","021_14_3","PRO","14","3","3","Maganar wawa kan kawo sanda a bayansa, amma leɓunan masu hikima kan tsare su. ");
INSERT INTO hausa_vpl VALUES ("PR14_4","021_14_4","PRO","14","4","4","Inda ba shanu, wurin sa wa dabbobi abinci zai kasance ba kome, amma daga ƙarfin saniya ce yalwar girbi kan fito. ");
INSERT INTO hausa_vpl VALUES ("PR14_5","021_14_5","PRO","14","5","5","Mashaidi na gaskiya ba ya ruɗu, amma mashaidin ƙarya kan baza ƙarairayi. ");
INSERT INTO hausa_vpl VALUES ("PR14_6","021_14_6","PRO","14","6","6","Mai ba’a kan nemi hikima amma ba ya samun kome, amma sani kan zo a sawwaƙe ga mai basira. ");
INSERT INTO hausa_vpl VALUES ("PR14_7","021_14_7","PRO","14","7","7","Ka guji wawa, gama ba za ka sami sani a leɓunansa ba. ");
INSERT INTO hausa_vpl VALUES ("PR14_8","021_14_8","PRO","14","8","8","Hikima masu la’akari shi ne su yi tunani a kan hanyoyinsu, amma wautar wawaye ruɗu ne. ");
INSERT INTO hausa_vpl VALUES ("PR14_9","021_14_9","PRO","14","9","9","Wawaye kan yi ba’a a gyaran zunubi, amma fatan alheri yana samuwa a cikin masu aikata gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PR14_10","021_14_10","PRO","14","10","10","Kowace zuciya ta san ɓacin ranta, kuma babu wani dabam da zai yi rabon jin daɗinsa. ");
INSERT INTO hausa_vpl VALUES ("PR14_11","021_14_11","PRO","14","11","11","Za a rushe gidan mugu, amma tentin mai aikata gaskiya zai haɓaka. ");
INSERT INTO hausa_vpl VALUES ("PR14_12","021_14_12","PRO","14","12","12","Akwai hanyar da ta yi kamar tana daidai ga mutum, amma a ƙarshe takan kai ga mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PR14_13","021_14_13","PRO","14","13","13","Ko cikin dariya zuciya takan yi ciwo, kuma farin ciki kan iya ƙarasa a baƙin ciki. ");
INSERT INTO hausa_vpl VALUES ("PR14_14","021_14_14","PRO","14","14","14","Marasa bangaskiya za su sami sakamako cikakke saboda hanyoyinsu, kuma mutumin kirki zai sami lada saboda nasa. ");
INSERT INTO hausa_vpl VALUES ("PR14_15","021_14_15","PRO","14","15","15","Marar azanci kan gaskata kome, amma mai la’akari kan yi tunani game da matakinsa. ");
INSERT INTO hausa_vpl VALUES ("PR14_16","021_14_16","PRO","14","16","16","Mai hikima kan ji tsoron Ubangiji ya kuma guji mugunta, amma wawa yana da girman kai yakan yi kome da garaje. ");
INSERT INTO hausa_vpl VALUES ("PR14_17","021_14_17","PRO","14","17","17","Mutum mai saurin fushi yakan yi ayyukan wauta, akan kuma ƙi mai son nuna wayo. ");
INSERT INTO hausa_vpl VALUES ("PR14_18","021_14_18","PRO","14","18","18","Marar azanci kan gāji wauta, amma mai la’akari kan sami rawanin sani. ");
INSERT INTO hausa_vpl VALUES ("PR14_19","021_14_19","PRO","14","19","19","Masu mugunta za su rusuna a gaban masu kirki, mugaye kuma za su yi haka a ƙofofin adalai. ");
INSERT INTO hausa_vpl VALUES ("PR14_20","021_14_20","PRO","14","20","20","Maƙwabta sukan gudu daga matalauta, amma masu arziki suna da abokai da yawa. ");
INSERT INTO hausa_vpl VALUES ("PR14_21","021_14_21","PRO","14","21","21","Duk wanda ya rena maƙwabci ya yi zunubi, amma mai albarka ne wanda yake alheri ga mabukata. ");
INSERT INTO hausa_vpl VALUES ("PR14_22","021_14_22","PRO","14","22","22","Ba waɗanda suke ƙulla mugunta sukan kauce ba? Amma waɗanda suke ƙulla abin da yake mai kyau sukan sami ƙauna da aminci. ");
INSERT INTO hausa_vpl VALUES ("PR14_23","021_14_23","PRO","14","23","23","Duk aiki tuƙuru yakan kawo riba, amma zama kana surutu kan kai ga talauci kawai. ");
INSERT INTO hausa_vpl VALUES ("PR14_24","021_14_24","PRO","14","24","24","Dukiyar masu hikima ita ce rawaninsu, amma wautar wawaye kan haifar da wauta ne kawai. ");
INSERT INTO hausa_vpl VALUES ("PR14_25","021_14_25","PRO","14","25","25","Mashaidin gaskiya kan ceci rayuka, amma mashaidin ƙarya mai ruɗu ne. ");
INSERT INTO hausa_vpl VALUES ("PR14_26","021_14_26","PRO","14","26","26","Duk mai tsoron Ubangiji yana da zaunannen mafaka, kuma ga ’ya’yansa zai zama mafaka. ");
INSERT INTO hausa_vpl VALUES ("PR14_27","021_14_27","PRO","14","27","27","Tsoron Ubangiji shi ne maɓulɓular rai yakan juye mutum daga tarkon mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PR14_28","021_14_28","PRO","14","28","28","Yawan mutane shi ne ɗaukakar sarki, amma in ba tare da mabiya ba sarki ba kome ba ne. ");
INSERT INTO hausa_vpl VALUES ("PR14_29","021_14_29","PRO","14","29","29","Mutum mai haƙuri yana da fahimi mai yawa, amma mai saurin fushi yakan nuna wautarsa a fili. ");
INSERT INTO hausa_vpl VALUES ("PR14_30","021_14_30","PRO","14","30","30","Zuciya mai salama kan ba jiki rai, amma kishi kan sa ƙasusuwa su yi ciwo. ");
INSERT INTO hausa_vpl VALUES ("PR14_31","021_14_31","PRO","14","31","31","Duk wanda ya zalunci matalauci ya zagi Mahaliccinsu ke nan, amma duk wanda ya yi alheri ga mabukata yana girmama Allah ne. ");
INSERT INTO hausa_vpl VALUES ("PR14_32","021_14_32","PRO","14","32","32","Sa’ad bala’i ya auku, mugaye kan fāɗi, amma ko a mutuwa masu adalci suna da mafaka. ");
INSERT INTO hausa_vpl VALUES ("PR14_33","021_14_33","PRO","14","33","33","Hikima tana a zuciyar mai azanci, kuma ko a cikin wawaye takan sa a santa. ");
INSERT INTO hausa_vpl VALUES ("PR14_34","021_14_34","PRO","14","34","34","Adalci yakan ɗaukaka al’umma, amma zunubi kan kawo kunya ga kowane mutane. ");
INSERT INTO hausa_vpl VALUES ("PR14_35","021_14_35","PRO","14","35","35","Sarki yakan yi murna a kan bawa mai hikima, amma bawa marar kunya kan jawo fushinsa. ");
INSERT INTO hausa_vpl VALUES ("PR15_1","021_15_1","PRO","15","1","1","Amsa da tattausar harshe kan kwantar da fushi, amma magana da kakkausan harshe kan kuta fushi. ");
INSERT INTO hausa_vpl VALUES ("PR15_2","021_15_2","PRO","15","2","2","Harshen mai hikima kan yi zance mai kyau a kan sani, amma bakin wawa kan fitar da wauta. ");
INSERT INTO hausa_vpl VALUES ("PR15_3","021_15_3","PRO","15","3","3","Idanun Ubangiji suna a ko’ina, suna lura da masu aikata mugunta da masu aikata alheri. ");
INSERT INTO hausa_vpl VALUES ("PR15_4","021_15_4","PRO","15","4","4","Harshen da ya kawo warkarwa shi ne itacen rai, amma harshe mai ƙarya kan ragargaza zuciya. ");
INSERT INTO hausa_vpl VALUES ("PR15_5","021_15_5","PRO","15","5","5","Wawa yakan ƙi kulawa da horon da mahaifinsa yake masa, amma duk wanda ya yarda da gyara kan nuna azanci. ");
INSERT INTO hausa_vpl VALUES ("PR15_6","021_15_6","PRO","15","6","6","Gidan adali yana da dukiya mai yawa, amma albashin mugaye kan kawo musu wahala. ");
INSERT INTO hausa_vpl VALUES ("PR15_7","021_15_7","PRO","15","7","7","Leɓunan masu hikima sukan baza sani; ba haka zukatan wawaye suke ba. ");
INSERT INTO hausa_vpl VALUES ("PR15_8","021_15_8","PRO","15","8","8","Ubangiji yana ƙyamar hadayar mugaye, amma addu’ar masu aikata gaskiya kan sa ya ji daɗi. ");
INSERT INTO hausa_vpl VALUES ("PR15_9","021_15_9","PRO","15","9","9","Ubangiji yana ƙin hanyar mugaye amma yana ƙaunar waɗanda suke neman adalci. ");
INSERT INTO hausa_vpl VALUES ("PR15_10","021_15_10","PRO","15","10","10","Horo mai tsanani yana jiran duk wanda ya bar hanya; wanda ya ƙi gyara zai mutu. ");
INSERT INTO hausa_vpl VALUES ("PR15_11","021_15_11","PRO","15","11","11","Mutuwa da Hallaka suna nan a fili a gaban Ubangiji, balle fa zukatan mutane! ");
INSERT INTO hausa_vpl VALUES ("PR15_12","021_15_12","PRO","15","12","12","Mai yin ba’a yakan ƙi gyara; ba zai nemi shawara mai hikima ba. ");
INSERT INTO hausa_vpl VALUES ("PR15_13","021_15_13","PRO","15","13","13","Zuciya mai farin ciki kan sa fuska tă yi haske, amma ciwon zuciya kan ragargaza rai. ");
INSERT INTO hausa_vpl VALUES ("PR15_14","021_15_14","PRO","15","14","14","Zuciya mai la’akari kan nemi sani, amma bakin wawa wauta ce ke ciyar da shi. ");
INSERT INTO hausa_vpl VALUES ("PR15_15","021_15_15","PRO","15","15","15","Dukan kwanakin mutumin da ake danniya fama yake yi, amma zuciya mai farin ciki yana yin biki kullum. ");
INSERT INTO hausa_vpl VALUES ("PR15_16","021_15_16","PRO","15","16","16","Gara a kasance da kaɗan da tsoron Ubangiji da a kasance da arziki mai yawa game da wahala. ");
INSERT INTO hausa_vpl VALUES ("PR15_17","021_15_17","PRO","15","17","17","Gara a ci abincin kayan ganye inda akwai ƙauna da a ci kiwotaccen saniya inda ƙiyayya take. ");
INSERT INTO hausa_vpl VALUES ("PR15_18","021_15_18","PRO","15","18","18","Mutum mai zafin rai kan kawo faɗa, amma mutum mai haƙuri kan kwantar da faɗa. ");
INSERT INTO hausa_vpl VALUES ("PR15_19","021_15_19","PRO","15","19","19","An tare hanyar rago da ƙayayyuwa, amma hanyar mai aikata gaskiya buɗaɗɗiyar hanya ce. ");
INSERT INTO hausa_vpl VALUES ("PR15_20","021_15_20","PRO","15","20","20","Ɗa mai hikima kan kawo farin ciki wa mahaifinsa, amma wawa yakan rena mahaifiyarsa. ");
INSERT INTO hausa_vpl VALUES ("PR15_21","021_15_21","PRO","15","21","21","Wauta kan sa mutum marar azanci ya yi farin ciki, amma mai basira kan kiyaye abin da yake yi daidai. ");
INSERT INTO hausa_vpl VALUES ("PR15_22","021_15_22","PRO","15","22","22","Shirye-shirye sukan lalace saboda rashin neman shawara, amma tare da mashawarta masu yawa za su yi nasara. ");
INSERT INTO hausa_vpl VALUES ("PR15_23","021_15_23","PRO","15","23","23","Mutum yakan yi farin ciki a ba da amsar da take daidai, kuma ina misali a yi magana a lokacin da ya dace! ");
INSERT INTO hausa_vpl VALUES ("PR15_24","021_15_24","PRO","15","24","24","Hanyar rai na yin jagora ya haura wa masu hikima don ta kiyaye shi daga gangarawa zuwa kabari. ");
INSERT INTO hausa_vpl VALUES ("PR15_25","021_15_25","PRO","15","25","25","Ubangiji yakan rushe gidan mai girman kai amma yakan kiyaye iyakokin gwauruwa daidai. ");
INSERT INTO hausa_vpl VALUES ("PR15_26","021_15_26","PRO","15","26","26","Ubangiji yana ƙyamar tunanin mugaye, amma waɗanda suke da tunani masu tsabta yakan ji daɗinsu. ");
INSERT INTO hausa_vpl VALUES ("PR15_27","021_15_27","PRO","15","27","27","Mutum mai haɗama kan kawo wahala ga iyalinsa, amma wanda yake ƙin cin hanci zai rayu. ");
INSERT INTO hausa_vpl VALUES ("PR15_28","021_15_28","PRO","15","28","28","Zuciyar mai adalci takan auna amsoshinta, amma bakin mugu yakan fitar da mugunta. ");
INSERT INTO hausa_vpl VALUES ("PR15_29","021_15_29","PRO","15","29","29","Ubangiji yana nesa da mugaye amma yakan ji addu’ar adalai. ");
INSERT INTO hausa_vpl VALUES ("PR15_30","021_15_30","PRO","15","30","30","Fuska mai fara’a takan kawo farin ciki ga zuciya, kuma labari mai daɗi na kawo lafiya ga ƙasusuwa. ");
INSERT INTO hausa_vpl VALUES ("PR15_31","021_15_31","PRO","15","31","31","Duk wanda ya mai da hankali sa’ad da ake tsawata masa ba zai kasance dabam a cikin masu hikima ba. ");
INSERT INTO hausa_vpl VALUES ("PR15_32","021_15_32","PRO","15","32","32","Duk waɗanda suka ƙi horon sun rena kansu ke nan, amma duk waɗanda sun yarda da gyara sukan ƙara basira. ");
INSERT INTO hausa_vpl VALUES ("PR15_33","021_15_33","PRO","15","33","33","Tsoron Ubangiji yakan koya wa mutum hikima, kuma sauƙinkai kan zo kafin girmamawa. ");
INSERT INTO hausa_vpl VALUES ("PR16_1","021_16_1","PRO","16","1","1","Ga mutum ne shirye-shiryen zuciya suke, amma daga Ubangiji ne amshin harshe kan zo. ");
INSERT INTO hausa_vpl VALUES ("PR16_2","021_16_2","PRO","16","2","2","Dukan hanyoyin mutum sukan yi kamar marar laifi ne gare shi, amma Ubangiji yakan auna manufofi. ");
INSERT INTO hausa_vpl VALUES ("PR16_3","021_16_3","PRO","16","3","3","Ka miƙa wa Ubangiji dukan abin da kake yi, shirye-shiryenka kuwa za su yi nasara. ");
INSERT INTO hausa_vpl VALUES ("PR16_4","021_16_4","PRO","16","4","4","Ubangiji yana yin kome domin amfaninsa, har ma da mugaye domin ranar masifa. ");
INSERT INTO hausa_vpl VALUES ("PR16_5","021_16_5","PRO","16","5","5","Ubangiji yana ƙyamar dukan zuciya mai girman kai. Ka tabbata da wannan. Ba za su kuɓuta daga hukunci ba. ");
INSERT INTO hausa_vpl VALUES ("PR16_6","021_16_6","PRO","16","6","6","Ta wurin ƙauna da aminci akan yi kafarar zunubi; ta wurin tsoron Ubangiji mutum kan guji mugunta. ");
INSERT INTO hausa_vpl VALUES ("PR16_7","021_16_7","PRO","16","7","7","Sa’ad da hanyoyin mutum sun gamshi Ubangiji, yakan sa abokan gāban mutumin ma su zauna lafiya da shi. ");
INSERT INTO hausa_vpl VALUES ("PR16_8","021_16_8","PRO","16","8","8","Gara ka sami kaɗan ta hanyar adalci da sami riba mai yawa ta hanyar rashin gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PR16_9","021_16_9","PRO","16","9","9","’Yan Adam sukan yi shirye-shiryensu a zukatansu, amma Ubangiji ne yake da ikon cika matakansa. ");
INSERT INTO hausa_vpl VALUES ("PR16_10","021_16_10","PRO","16","10","10","Leɓunan sarki kan yi magana kamar ta wurin ikon Allah, kuma bai kamata bakinsa ya yi kuskure a yanke shari’a ba. ");
INSERT INTO hausa_vpl VALUES ("PR16_11","021_16_11","PRO","16","11","11","Ma’aunai da magwajin gaskiya daga Ubangiji ne; dukan ma’aunai da suke cikin jaka yinsa ne. ");
INSERT INTO hausa_vpl VALUES ("PR16_12","021_16_12","PRO","16","12","12","Sarakuna suna ƙyamar abin da ba shi da kyau, gama an kafa kujerar sarauta ta wurin adalci ne. ");
INSERT INTO hausa_vpl VALUES ("PR16_13","021_16_13","PRO","16","13","13","Sarakuna sukan ji daɗi leɓuna masu yin gaskiya; sukan darjanta mutumin da yake faɗin gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PR16_14","021_16_14","PRO","16","14","14","Fushin sarki ɗan saƙon mutuwa ne, amma mai hikima yakan faranta masa rai. ");
INSERT INTO hausa_vpl VALUES ("PR16_15","021_16_15","PRO","16","15","15","Sa’ad da fuskar sarki ta haska, yana nufin rai ke nan; tagomashinsa yana kamar girgijen ruwa a bazara. ");
INSERT INTO hausa_vpl VALUES ("PR16_16","021_16_16","PRO","16","16","16","Ya ma fi kyau ka sami hikima fiye da zinariya, ka zaɓi fahimi a maimakon azurfa! ");
INSERT INTO hausa_vpl VALUES ("PR16_17","021_16_17","PRO","16","17","17","Buɗaɗɗiyar hanyar masu aikata gaskiya kan guje wa mugunta; duk wanda yake lura da hanyarsa yakan lura da ransa. ");
INSERT INTO hausa_vpl VALUES ("PR16_18","021_16_18","PRO","16","18","18","Girmankai yakan zo kafin hallaka, girman kai yakan zo kafin fāɗuwa. ");
INSERT INTO hausa_vpl VALUES ("PR16_19","021_16_19","PRO","16","19","19","Gara ka zama ɗaya daga cikin matalauta masu sauƙinkai, da ka raba ganima da masu girman kai. ");
INSERT INTO hausa_vpl VALUES ("PR16_20","021_16_20","PRO","16","20","20","Duk wanda ya mai da hankali ga umarni yakan yi nasara, kuma mai albarka ne wanda yake dogara ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PR16_21","021_16_21","PRO","16","21","21","Akan ce da masu hikima a zuciya hazikai, kuma kalmomi masu daɗi kan inganta umarni. ");
INSERT INTO hausa_vpl VALUES ("PR16_22","021_16_22","PRO","16","22","22","Fahimi shi ne maɓulɓular rai ga waɗanda suke da shi, amma wauta kan kawo hukunci ga wawaye. ");
INSERT INTO hausa_vpl VALUES ("PR16_23","021_16_23","PRO","16","23","23","Zuciyar mai hikima kan bi da bakinsa, kuma leɓunansa kan inganta umarni. ");
INSERT INTO hausa_vpl VALUES ("PR16_24","021_16_24","PRO","16","24","24","Kalmomi masu daɗi suna kama da kakin zuma, mai zaƙi ga rai da kuma warkarwa ga ƙasusuwa. ");
INSERT INTO hausa_vpl VALUES ("PR16_25","021_16_25","PRO","16","25","25","Akwai hanyar da ta yi kamar daidai ga mutum, amma a ƙarshe takan kai ga mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PR16_26","021_16_26","PRO","16","26","26","Marmarin cin abinci yakan yi wa ɗan ƙodago aiki; yunwarsa kan sa ya ci gaba. ");
INSERT INTO hausa_vpl VALUES ("PR16_27","021_16_27","PRO","16","27","27","Mutumin banza yakan ƙulla mugunta, kuma jawabinsa yana kama da wuta mai ƙuna. ");
INSERT INTO hausa_vpl VALUES ("PR16_28","021_16_28","PRO","16","28","28","Fitinannen mutum yakan zuga tashin hankali, mai gulma kuma yakan raba abokai na kusa. ");
INSERT INTO hausa_vpl VALUES ("PR16_29","021_16_29","PRO","16","29","29","Mutum mai tā-da-na-zaune-tsaye yakan ruɗi maƙwabcinsa ya kai shi a hanyar da ba ta da kyau. ");
INSERT INTO hausa_vpl VALUES ("PR16_30","021_16_30","PRO","16","30","30","Duk wanda ya ƙyifce da idonsa yana ƙulla maƙarƙashiya ce; duk wanda ya murguɗa leɓunansa yana niyya aikata mugunta ke nan. ");
INSERT INTO hausa_vpl VALUES ("PR16_31","021_16_31","PRO","16","31","31","Furfura rawani ne mai daraja; akan same ta ta wurin yin rayuwa ta adalci. ");
INSERT INTO hausa_vpl VALUES ("PR16_32","021_16_32","PRO","16","32","32","Gara ka zama mai haƙuri da ka zama jarumi, ya fi kyau ka iya mallakar kanka fiye da mallakar birane. ");
INSERT INTO hausa_vpl VALUES ("PR16_33","021_16_33","PRO","16","33","33","Akan jefa ƙuri’a a kan cinya, amma kowace shawara mai kyau daga Ubangiji ne. ");
INSERT INTO hausa_vpl VALUES ("PR17_1","021_17_1","PRO","17","1","1","Gara ka ci busasshen burodi da kwanciyar rai kuma shiru da ka je cin abinci a gidan da ke cike da biki amma da ɓacin rai. ");
INSERT INTO hausa_vpl VALUES ("PR17_2","021_17_2","PRO","17","2","2","Bawa mai hikima zai yi mulki a kan da mai rashin kunya, kuma zai raba gādo kamar ɗaya daga cikin ’yan’uwansa. ");
INSERT INTO hausa_vpl VALUES ("PR17_3","021_17_3","PRO","17","3","3","Ana gwajin azurfa da kuma zinariya da wuta, amma Ubangiji ne mai gwajin zuciya. ");
INSERT INTO hausa_vpl VALUES ("PR17_4","021_17_4","PRO","17","4","4","Mugun mutum kan mai da hankali ga mugayen leɓuna; maƙaryaci yakan kasa kunne ga harshen ƙarairayi. ");
INSERT INTO hausa_vpl VALUES ("PR17_5","021_17_5","PRO","17","5","5","Duk wanda yake wa matalauta ba’a yana zagin Mahaliccinsu ne; duk wanda ya yi murna akan masifar da ta sami wani za a hukunta shi. ");
INSERT INTO hausa_vpl VALUES ("PR17_6","021_17_6","PRO","17","6","6","Jikoki rawanin tsofaffi ne, kuma iyaye su ne abin taƙamar ’ya’yansu. ");
INSERT INTO hausa_vpl VALUES ("PR17_7","021_17_7","PRO","17","7","7","Leɓunan basira ba su dace da wawa ba, ya ma fi muni a ce mai mulki yana da leɓunan ƙarya! ");
INSERT INTO hausa_vpl VALUES ("PR17_8","021_17_8","PRO","17","8","8","Cin hanci kamar sihiri yake ga wanda yake ba da shi; ko’ina ya juye, yakan yi nasara. ");
INSERT INTO hausa_vpl VALUES ("PR17_9","021_17_9","PRO","17","9","9","Duk wanda ya rufe laifi yana inganta ƙauna ne, amma duk wanda ya yi ta maimaita batu yakan raba abokai na kusa. ");
INSERT INTO hausa_vpl VALUES ("PR17_10","021_17_10","PRO","17","10","10","Tsawata kan sa mutum ya koyi basira fiye da abin da wawa zai koya ko da an dūke shi sau ɗari. ");
INSERT INTO hausa_vpl VALUES ("PR17_11","021_17_11","PRO","17","11","11","Mugayen mutane sukan kuta tawaye da Allah; za a aika manzo mutuwa a kansu. ");
INSERT INTO hausa_vpl VALUES ("PR17_12","021_17_12","PRO","17","12","12","Gara a haɗu da beyar da aka ƙwace wa ’ya’ya fiye da a sadu da wawa cikin wautarsa. ");
INSERT INTO hausa_vpl VALUES ("PR17_13","021_17_13","PRO","17","13","13","In mutum ya sāka alheri da mugunta, mugunta ba za tă taɓa barin gidansa ba. ");
INSERT INTO hausa_vpl VALUES ("PR17_14","021_17_14","PRO","17","14","14","Farawar faɗa tana kamar ɓarkewa madatsar ruwa ne, saboda haka ka bar batun kafin faɗa ta ɓarke. ");
INSERT INTO hausa_vpl VALUES ("PR17_15","021_17_15","PRO","17","15","15","Baratar da mai laifi a kuma hukunta mai adalci, Ubangiji ya ƙi su biyu. ");
INSERT INTO hausa_vpl VALUES ("PR17_16","021_17_16","PRO","17","16","16","Mene ne amfanin kuɗi a hannun wawa, da yake ba shi da sha’awar samun hikima? ");
INSERT INTO hausa_vpl VALUES ("PR17_17","021_17_17","PRO","17","17","17","Aboki yakan yi ƙauna a koyaushe, ɗan’uwa kuma, ai, don ɗaukar nawayar juna ne aka haife shi. ");
INSERT INTO hausa_vpl VALUES ("PR17_18","021_17_18","PRO","17","18","18","Mutumin da ba shi da azanci yakan ɗauki lamunin wani ya kuma ɗauki nauyin biyan basusuwan maƙwabci. ");
INSERT INTO hausa_vpl VALUES ("PR17_19","021_17_19","PRO","17","19","19","Duk mai son faɗa yana son zunubi, duk wanda ya gina ƙofar shiga mai tsawo yana gayyatar hallaka. ");
INSERT INTO hausa_vpl VALUES ("PR17_20","021_17_20","PRO","17","20","20","Mutum mai muguwar zuciya ba ya cin gaba; duk wanda yake da harshen ruɗu kan shiga wahala. ");
INSERT INTO hausa_vpl VALUES ("PR17_21","021_17_21","PRO","17","21","21","Kasance da wawa kamar ɗa yakan kawo baƙin ciki babu farin ciki ga mahaifin wawa. ");
INSERT INTO hausa_vpl VALUES ("PR17_22","021_17_22","PRO","17","22","22","Zuciya mai farin ciki magani ne mai kyau, amma bakin rai kan busar da ƙasusuwa. ");
INSERT INTO hausa_vpl VALUES ("PR17_23","021_17_23","PRO","17","23","23","Mugun mutum yakan karɓa cin hanci a asirce don yă lalace yin adalci. ");
INSERT INTO hausa_vpl VALUES ("PR17_24","021_17_24","PRO","17","24","24","Mutum mai basira kan kafa idonsa a kan hikima, amma idanun wawa suna a kan ƙarshen duniya. ");
INSERT INTO hausa_vpl VALUES ("PR17_25","021_17_25","PRO","17","25","25","Da yake wawa yakan kawo baƙin ciki ga mahaifinsa da ɓacin rai ga wanda ya haife shi. ");
INSERT INTO hausa_vpl VALUES ("PR17_26","021_17_26","PRO","17","26","26","Ba shi da kyau a hukunta marar laifi, ko a bulale shugaba saboda mutuncinsu. ");
INSERT INTO hausa_vpl VALUES ("PR17_27","021_17_27","PRO","17","27","27","Mutum mai sani yakan yi la’akari da amfani da kalmomi, mutum mai basira kuma natsattse ne. ");
INSERT INTO hausa_vpl VALUES ("PR17_28","021_17_28","PRO","17","28","28","Ko wawa in bai buɗe bakinsa ba, za a zaci shi mai hikima ne, da kuma mai basira inda ya ƙame bakinsa. ");
INSERT INTO hausa_vpl VALUES ("PR18_1","021_18_1","PRO","18","1","1","Mutumin da ba ya abokantaka yakan nema ya cika burinsa ne kaɗai; yakan ƙi yarda da kowace maganar da take daidai. ");
INSERT INTO hausa_vpl VALUES ("PR18_2","021_18_2","PRO","18","2","2","Wawa ba ya sha’awa ya sami fahimta amma abin da yake so ya yi kaɗai, shi ne ya ba da ra’ayinsa. ");
INSERT INTO hausa_vpl VALUES ("PR18_3","021_18_3","PRO","18","3","3","Sa’ad da mugunci ya zo, reni ma kan zo, haka kuma sa’ad da kunya ta zo, shan kunya kan biyo. ");
INSERT INTO hausa_vpl VALUES ("PR18_4","021_18_4","PRO","18","4","4","Kalmomin bakin mutum suna da zurfi kamar ruwaye, amma maɓulɓulan hikima rafi ne mai gudu. ");
INSERT INTO hausa_vpl VALUES ("PR18_5","021_18_5","PRO","18","5","5","Ba shi da kyau ka yi wa mugu alheri ko ka hana wa marar laifi adalci. ");
INSERT INTO hausa_vpl VALUES ("PR18_6","021_18_6","PRO","18","6","6","Leɓunan wawa kan jawo masa faɗa, bakinsa kuma kan gayyaci dūka. ");
INSERT INTO hausa_vpl VALUES ("PR18_7","021_18_7","PRO","18","7","7","Bakin wawa lalatar da kansa yake yi leɓunansa kuma tarko ne ga ransa. ");
INSERT INTO hausa_vpl VALUES ("PR18_8","021_18_8","PRO","18","8","8","Kalmomin mai gulma kamar abinci mai daɗi suke; sukan gangara zuwa can cikin gaɓoɓin mutum. ");
INSERT INTO hausa_vpl VALUES ("PR18_9","021_18_9","PRO","18","9","9","Wanda yake ragwanci a aikinsa ɗan’uwa ne ga wanda yakan lalatar da abubuwa. ");
INSERT INTO hausa_vpl VALUES ("PR18_10","021_18_10","PRO","18","10","10","Sunan Ubangiji hasumiya ce mai ƙarfi; masu adalci kan gudu zuwa wurinta don su zauna lafiya. ");
INSERT INTO hausa_vpl VALUES ("PR18_11","021_18_11","PRO","18","11","11","Dukiyar masu arziki ita ce birninsu mai katanga; suna gani cewa ba za a iya huda katangar ba. ");
INSERT INTO hausa_vpl VALUES ("PR18_12","021_18_12","PRO","18","12","12","Kafin fāɗuwarsa zuciyar mutum takan yi girman kai, amma sauƙinkai kan zo kafin girmamawa. ");
INSERT INTO hausa_vpl VALUES ("PR18_13","021_18_13","PRO","18","13","13","Duk wanda yakan ba da amsa kafin ya saurara, wannan wauta ce da kuma abin kunya. ");
INSERT INTO hausa_vpl VALUES ("PR18_14","021_18_14","PRO","18","14","14","Sa rai da mutum ke yi kan taimake shi sa’ad da yake ciwo, amma in ya karai, to, tasa ta ƙare. ");
INSERT INTO hausa_vpl VALUES ("PR18_15","021_18_15","PRO","18","15","15","Zuciya mai la’akari kan nemi sani; kunnuwan mai hikima kan bincika don yă koya. ");
INSERT INTO hausa_vpl VALUES ("PR18_16","021_18_16","PRO","18","16","16","Kyauta kan buɗe hanya wa mai bayarwa yakan kuma kai shi a gaban babban mutum. ");
INSERT INTO hausa_vpl VALUES ("PR18_17","021_18_17","PRO","18","17","17","Wanda ya fara mai da jawabi yakan zama kamar shi ne mai gaskiya, sai wani ya fito ya yi masa tambaya tukuna. ");
INSERT INTO hausa_vpl VALUES ("PR18_18","021_18_18","PRO","18","18","18","Jefa ƙuri’a kan daidaita tsakanin masu faɗa ta kuma ajiye masu faɗan a rabe. ");
INSERT INTO hausa_vpl VALUES ("PR18_19","021_18_19","PRO","18","19","19","Ɗan’uwan da aka yi wa laifi ya fi birni mai katanga wuyan shiryawa, kuma faɗace-faɗace suna kama da ƙofofin ƙarfe na fada. ");
INSERT INTO hausa_vpl VALUES ("PR18_20","021_18_20","PRO","18","20","20","Daga abin da baki ya furta ne cikin mutum kan cika; girbi daga leɓunansa kuma yakan ƙoshi. ");
INSERT INTO hausa_vpl VALUES ("PR18_21","021_18_21","PRO","18","21","21","Harshe yana da ikon rai da mutuwa, kuma waɗanda suke ƙaunarsa za su ci amfaninsa. ");
INSERT INTO hausa_vpl VALUES ("PR18_22","021_18_22","PRO","18","22","22","Duk wanda ya sami mace ya sami abu mai kyau ya kuma sami tagomashi daga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PR18_23","021_18_23","PRO","18","23","23","Matalauci kan yi roƙo da taushi, amma mawadaci kan amsa da kakkausar murya. ");
INSERT INTO hausa_vpl VALUES ("PR18_24","021_18_24","PRO","18","24","24","Mutum mai abokai masu yawa kan lalace, amma akwai abokin da yakan manne kurkusa fiye da ɗan’uwa. ");
INSERT INTO hausa_vpl VALUES ("PR19_1","021_19_1","PRO","19","1","1","Gara matalauci wanda yake marar laifi da wawa wanda leɓunansa masu ƙarya ne. ");
INSERT INTO hausa_vpl VALUES ("PR19_2","021_19_2","PRO","19","2","2","Ba shi da kyau ka kasance da niyya babu sani, ko ka kasance mai garaje ka ɓace hanya. ");
INSERT INTO hausa_vpl VALUES ("PR19_3","021_19_3","PRO","19","3","3","Wautar mutum kan lalatar da ransa, duk da haka zuciyarsa kan ba wa Ubangiji laifi. ");
INSERT INTO hausa_vpl VALUES ("PR19_4","021_19_4","PRO","19","4","4","Wadata kan kawo abokai da yawa, amma abokin matalauci kan bar shi. ");
INSERT INTO hausa_vpl VALUES ("PR19_5","021_19_5","PRO","19","5","5","Mai ba da shaidar ƙarya ba zai tafi babu hukunci ba, kuma duk wanda ya baza ƙarairayi ba zai kuɓuta ba. ");
INSERT INTO hausa_vpl VALUES ("PR19_6","021_19_6","PRO","19","6","6","Kowa na ƙoƙari ya sami farin jini wurin mai mulki, kuma kowa na so a ce shi abokin mutumin nan mai yawan kyauta ne. ");
INSERT INTO hausa_vpl VALUES ("PR19_7","021_19_7","PRO","19","7","7","’Yan’uwan matalauci sukan guje shi, balle abokansa, su ma za su guje shi. Ko da yake matalaucin yana binsu yana roƙo, ba zai sam su ba. ");
INSERT INTO hausa_vpl VALUES ("PR19_8","021_19_8","PRO","19","8","8","Duk wanda ya sami hikima yana ƙaunar ransa; duka wanda yake jin daɗi fahimi kan ci gaba. ");
INSERT INTO hausa_vpl VALUES ("PR19_9","021_19_9","PRO","19","9","9","Mai shaidar ƙarya ba zai tafi babu hukunci ba, kuma duk mai baza ƙarairayi zai hallaka. ");
INSERT INTO hausa_vpl VALUES ("PR19_10","021_19_10","PRO","19","10","10","Bai dace da wawa ya yi rayuwa cikin jin daɗi ba, haka ya fi muni bawa ya yi mulki a kan sarki! ");
INSERT INTO hausa_vpl VALUES ("PR19_11","021_19_11","PRO","19","11","11","Hikimar mutum kan ba shi haƙuri; ɗaukakarsa ce ya ƙyale laifi. ");
INSERT INTO hausa_vpl VALUES ("PR19_12","021_19_12","PRO","19","12","12","Fushin sarki yana kama da rurin zaki, amma tagomashinsa yana kama da raba a kan ciyawa. ");
INSERT INTO hausa_vpl VALUES ("PR19_13","021_19_13","PRO","19","13","13","Wawan yaro lalacin mahaifinsa ne, mace mai yawan faɗa tana kama da ɗiɗɗigar ruwa. ");
INSERT INTO hausa_vpl VALUES ("PR19_14","021_19_14","PRO","19","14","14","Ana gādon dawakai da wadata daga iyaye ne, amma mace mai basira daga Ubangiji ne. ");
INSERT INTO hausa_vpl VALUES ("PR19_15","021_19_15","PRO","19","15","15","Ragwanci kan jawo zurfin barci, mutum mai sanyin jiki kuma yana tare da yunwa. ");
INSERT INTO hausa_vpl VALUES ("PR19_16","021_19_16","PRO","19","16","16","Duk wanda ya bi umarnai kan tsare ransa, amma duk wanda ya ƙi binsu zai mutu. ");
INSERT INTO hausa_vpl VALUES ("PR19_17","021_19_17","PRO","19","17","17","Duk wanda yake kirki ga matalauta yana ba wa Ubangiji bashi ne, zai kuwa sami lada game da abin da ya yi. ");
INSERT INTO hausa_vpl VALUES ("PR19_18","021_19_18","PRO","19","18","18","Ka hori ɗanka, gama yin haka akwai sa zuciya; kada ka goyi baya lalacewarsa. ");
INSERT INTO hausa_vpl VALUES ("PR19_19","021_19_19","PRO","19","19","19","Dole mai zafin rai yă biya tara; in ka fisshe shi sau ɗaya, to, sai ka sāke yin haka. ");
INSERT INTO hausa_vpl VALUES ("PR19_20","021_19_20","PRO","19","20","20","Ka kasa kunne ga shawara ka kuma yarda da umarni, a ƙarshe kuwa za ka yi hikima. ");
INSERT INTO hausa_vpl VALUES ("PR19_21","021_19_21","PRO","19","21","21","Da yawa ne shirye-shiryen zuciyar mutum, amma manufar Ubangiji ce takan cika. ");
INSERT INTO hausa_vpl VALUES ("PR19_22","021_19_22","PRO","19","22","22","Abin da mutum yake sha’awa shi ne ƙauna marar ƙarewa; gara ka zama matalauci da ka zama maƙaryaci. ");
INSERT INTO hausa_vpl VALUES ("PR19_23","021_19_23","PRO","19","23","23","Tsoron Ubangiji yakan kai ga rai. Sa’an nan mutum ya sami biyan bukata, ba abin da zai cuce shi. ");
INSERT INTO hausa_vpl VALUES ("PR19_24","021_19_24","PRO","19","24","24","Rago kan sa hannunsa a kwano ba ya ma iya ɗaga shi ya kai bakinsa! ");
INSERT INTO hausa_vpl VALUES ("PR19_25","021_19_25","PRO","19","25","25","Ka bulale mai ba’a, marasa azanci kuwa za su yi la’akari; ka tsawata wa mai basira, zai kuwa ƙara sani. ");
INSERT INTO hausa_vpl VALUES ("PR19_26","021_19_26","PRO","19","26","26","Duk wanda ya yi wa mahaifinsa fashi ya kuma kori mahaifiyarsa ɗa ne da kan kawo kunya da wulaƙanci. ");
INSERT INTO hausa_vpl VALUES ("PR19_27","021_19_27","PRO","19","27","27","In ka daina jin umarni, ɗana, za ka kuwa kauce daga kalmomin sani. ");
INSERT INTO hausa_vpl VALUES ("PR19_28","021_19_28","PRO","19","28","28","Mai shaidar da yake malalaci yana wa shari’a ba’a ne, bakin mugaye kuma na haɗiye mugunta. ");
INSERT INTO hausa_vpl VALUES ("PR19_29","021_19_29","PRO","19","29","29","An shirya tara saboda masu ba’a ne, dūka kuma saboda bayan wawaye. ");
INSERT INTO hausa_vpl VALUES ("PR20_1","021_20_1","PRO","20","1","1","Ruwan inabi mai yin ba’a ne, barasa kuma mai rikici ne; duk wanda suka sa ya kauce marar hikima ne. ");
INSERT INTO hausa_vpl VALUES ("PR20_2","021_20_2","PRO","20","2","2","Fushin sarki yana kama da rurin zaki; duk wanda ya sa shi fushi zai rasa ransa. ");
INSERT INTO hausa_vpl VALUES ("PR20_3","021_20_3","PRO","20","3","3","Bangirma ne ga mutum ya guji faɗa, amma kowane wawa yana saurin yin faɗa. ");
INSERT INTO hausa_vpl VALUES ("PR20_4","021_20_4","PRO","20","4","4","Rago ba ya noma a lokacin noma; saboda haka a lokacin girbi ba ya bukata samun kome. ");
INSERT INTO hausa_vpl VALUES ("PR20_5","021_20_5","PRO","20","5","5","Manufofin zuciyar mutum zurfafan ruwaye ne, amma mutum mai basira yakan jawo su. ");
INSERT INTO hausa_vpl VALUES ("PR20_6","021_20_6","PRO","20","6","6","Kowane mutum gani yake shi mai ƙauna marar ƙarewa ne, amma ina? Da ƙyar ka sami amintacce mutum guda. ");
INSERT INTO hausa_vpl VALUES ("PR20_7","021_20_7","PRO","20","7","7","Mai adalci kan yi rayuwa marar abin zargi; masu albarka ne ’ya’yan da za su biyo bayansa. ");
INSERT INTO hausa_vpl VALUES ("PR20_8","021_20_8","PRO","20","8","8","Sa’ad da sarki ya zauna kan kujerarsa don yă yi shari’a, yakan ga dukan mugunta da idanunsa. ");
INSERT INTO hausa_vpl VALUES ("PR20_9","021_20_9","PRO","20","9","9","Wa zai iya cewa, “Na kiyaye zuciyata da tsarki; ni mai tsabta ne marar zunubi kuma”? ");
INSERT INTO hausa_vpl VALUES ("PR20_10","021_20_10","PRO","20","10","10","Ma’auni marar gaskiya da magwajin da ba daidai ba, Ubangiji ya ƙi su duka. ");
INSERT INTO hausa_vpl VALUES ("PR20_11","021_20_11","PRO","20","11","11","Akan san ƙananan yara ta ayyukansu, ana iya sani ko rayuwarsu amintattu ne, mai nagarta. ");
INSERT INTO hausa_vpl VALUES ("PR20_12","021_20_12","PRO","20","12","12","Kunnuwan da suke ji da kuma idanun da suke gani, Ubangiji ne ya yi su duka. ");
INSERT INTO hausa_vpl VALUES ("PR20_13","021_20_13","PRO","20","13","13","Kada ka so barci in ba haka ba za ka talauce; ka zauna a faɗake za ka kuwa kasance da sauran abinci. ");
INSERT INTO hausa_vpl VALUES ("PR20_14","021_20_14","PRO","20","14","14","“Kai, ya yi tsada, ya yi tsada!” In ji mai saya; sa’ad da ya tafi yana taƙama a kan ya iya ciniki. ");
INSERT INTO hausa_vpl VALUES ("PR20_15","021_20_15","PRO","20","15","15","Zinariya akwai ta, lu’ulu’u kuma ga shi a yalwace, amma leɓunan da suke magana da sani suna da wuyan samu kamar duwatsu masu daraja. ");
INSERT INTO hausa_vpl VALUES ("PR20_16","021_20_16","PRO","20","16","16","A karɓi rigunan wanda ya ɗauki lamunin baƙo; a riƙe shi jingina in ya yi shi don mace marar aminci. ");
INSERT INTO hausa_vpl VALUES ("PR20_17","021_20_17","PRO","20","17","17","Abincin da aka samu ta hanyar zamba yakan zama da daɗi, amma mutum zai ƙarasa da baki cike da yashi. ");
INSERT INTO hausa_vpl VALUES ("PR20_18","021_20_18","PRO","20","18","18","Ka yi shirye-shirye ta wurin neman shawara; in kana yaƙi, ka sami bishewa. ");
INSERT INTO hausa_vpl VALUES ("PR20_19","021_20_19","PRO","20","19","19","Mai gulma yakan lalace yarda; saboda haka ka guji mutum mai yawan surutu. ");
INSERT INTO hausa_vpl VALUES ("PR20_20","021_20_20","PRO","20","20","20","In mutum ya zargi mahaifinsa ko mahaifiyarsa, fitilarsa za tă mutu a tsakiyar duhu. ");
INSERT INTO hausa_vpl VALUES ("PR20_21","021_20_21","PRO","20","21","21","Gādon da aka samu da sauri a farkon farawa ba zai zama mai albarka a ƙarshe ba. ");
INSERT INTO hausa_vpl VALUES ("PR20_22","021_20_22","PRO","20","22","22","Kada ka ce, “Zan rama wannan abin da aka yi mini!” Ka dogara ga Ubangiji, zai kuwa fisshe ka. ");
INSERT INTO hausa_vpl VALUES ("PR20_23","021_20_23","PRO","20","23","23","Ubangiji ya ƙi ma’aunin da ba daidai ba, da kuma magwajin da ba su gamshe shi ba. ");
INSERT INTO hausa_vpl VALUES ("PR20_24","021_20_24","PRO","20","24","24","Ubangiji ne yake bi da matakan mutum, Ta yaya wani zai fahimci hanyarsa? ");
INSERT INTO hausa_vpl VALUES ("PR20_25","021_20_25","PRO","20","25","25","Tarko ne ga mutum ya keɓe wani abu da ba tunani daga baya kuma ya yi la’akari da alkawarinsa. ");
INSERT INTO hausa_vpl VALUES ("PR20_26","021_20_26","PRO","20","26","26","Sarki mai hikima yakan gane mugunta; ya hukunta su ba tausayi. ");
INSERT INTO hausa_vpl VALUES ("PR20_27","021_20_27","PRO","20","27","27","Fitilar Ubangiji kan bincika zuciyar mutum takan bincika lamirinsa. ");
INSERT INTO hausa_vpl VALUES ("PR20_28","021_20_28","PRO","20","28","28","Ƙauna da aminci kan kiyaye sarki lafiya; ta wurin ƙauna sarautarsa za tă zauna a kafe. ");
INSERT INTO hausa_vpl VALUES ("PR20_29","021_20_29","PRO","20","29","29","Ɗaukakar matasa maza ita ce ƙarfinsu, furfura ita ce darajar tsofaffi. ");
INSERT INTO hausa_vpl VALUES ("PR20_30","021_20_30","PRO","20","30","30","Naushi da rauni kan share mugunta, dūka kuma kan tsabtacce lamiri. ");
INSERT INTO hausa_vpl VALUES ("PR21_1","021_21_1","PRO","21","1","1","A hannun Ubangiji zuciyar sarki kamar ruwan rafi ne wanda yake bi da shi duk inda ya so. ");
INSERT INTO hausa_vpl VALUES ("PR21_2","021_21_2","PRO","21","2","2","Mutum zai yi tunani hanyoyinsa daidai suke, amma Ubangiji yakan auna zuciya. ");
INSERT INTO hausa_vpl VALUES ("PR21_3","021_21_3","PRO","21","3","3","Yin abin da yake daidai da kuma nagari Ubangiji ya fi yarda da shi fiye da hadaya. ");
INSERT INTO hausa_vpl VALUES ("PR21_4","021_21_4","PRO","21","4","4","Girmankai da fariya, su ne fitilar mugaye, wannan kuwa zunubi ne! ");
INSERT INTO hausa_vpl VALUES ("PR21_5","021_21_5","PRO","21","5","5","Shirye-shiryen mai aiki tuƙuru kan kai ga riba in kuwa ka cika gaggawa zai kai ga talauci. ");
INSERT INTO hausa_vpl VALUES ("PR21_6","021_21_6","PRO","21","6","6","Dukiyar da aka samu ta wurin harshe mai yin ƙarya tarin tururi ne da kuma mugun tarko. ");
INSERT INTO hausa_vpl VALUES ("PR21_7","021_21_7","PRO","21","7","7","Rikicin mugaye zai yi gāba da su, gama sun ƙi su yi abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("PR21_8","021_21_8","PRO","21","8","8","Hanyar mai laifi karkatacciya ce, amma halin marar laifi sukan aikata gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PR21_9","021_21_9","PRO","21","9","9","Gara a zauna a kusurwar rufin ɗaki da a zauna a gida ɗaya da mace mai fitina. ");
INSERT INTO hausa_vpl VALUES ("PR21_10","021_21_10","PRO","21","10","10","Mugun mutum yakan zaƙu ya aikata mugunta; maƙwabcinsa ba ya samun jinƙai daga gare shi. ");
INSERT INTO hausa_vpl VALUES ("PR21_11","021_21_11","PRO","21","11","11","Sa’ad da aka hukunta mai ba’a marasa azanci suka yi wayo; sa’ad da aka yi wa mai hikima umarni yakan sami sani. ");
INSERT INTO hausa_vpl VALUES ("PR21_12","021_21_12","PRO","21","12","12","Mai Adalci kan lura da gidan mugu kan kuma zama sanadin lalacin mugu. ");
INSERT INTO hausa_vpl VALUES ("PR21_13","021_21_13","PRO","21","13","13","In mutum ya toshe kunnuwansa ga kukan matalauci, shi ma zai yi kukan neman taimako ba kuwa zai sami amsa ba. ");
INSERT INTO hausa_vpl VALUES ("PR21_14","021_21_14","PRO","21","14","14","Kyautar da aka yi a asirce takan kwantar da fushi, kuma cin hancin da aka rufe a cikin riga kan tā da fushi mai tsanani. ");
INSERT INTO hausa_vpl VALUES ("PR21_15","021_21_15","PRO","21","15","15","Sa’ad da aka yi adalci, yakan kawo farin ciki ga mai adalci amma fargaba ga masu aikata mugunta. ");
INSERT INTO hausa_vpl VALUES ("PR21_16","021_21_16","PRO","21","16","16","Mutumin da ya kauce daga hanyar fahimi kan zo ga hutu a ƙungiyar matattu. ");
INSERT INTO hausa_vpl VALUES ("PR21_17","021_21_17","PRO","21","17","17","Duk mai son jin daɗi zai zama matalauci; duk mai son ruwan inabi da mai ba zai taɓa zama mai arziki ba. ");
INSERT INTO hausa_vpl VALUES ("PR21_18","021_21_18","PRO","21","18","18","Mugu kan zama abin fansa don adali, marar aminci kuma don mai aikata gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PR21_19","021_21_19","PRO","21","19","19","Gara a zauna a hamada da a zauna da mace mai fitina da kuma mugun hali. ");
INSERT INTO hausa_vpl VALUES ("PR21_20","021_21_20","PRO","21","20","20","A gidan mai hikima akwai wuraren ajiya na abinci da mai masu kyau, amma wawa kan cinye duk abin da yake da shi. ");
INSERT INTO hausa_vpl VALUES ("PR21_21","021_21_21","PRO","21","21","21","Duk wanda ya nemi adalci da ƙauna kan sami rai, wadata da girmamawa. ");
INSERT INTO hausa_vpl VALUES ("PR21_22","021_21_22","PRO","21","22","22","Mutum mai hikima kan fāɗa wa birnin jarumawa ya kuma rushe katangar da suka dogara a kai. ");
INSERT INTO hausa_vpl VALUES ("PR21_23","021_21_23","PRO","21","23","23","Duk wanda yake lura da bakinsa da kuma harshensa kan kiyaye kansa daga masifa. ");
INSERT INTO hausa_vpl VALUES ("PR21_24","021_21_24","PRO","21","24","24","Mai girmankai da kuma mai fariya, “Mai ba’a” ne sunansa; yana yin abubuwa da girmankai ainun. ");
INSERT INTO hausa_vpl VALUES ("PR21_25","021_21_25","PRO","21","25","25","Marmarin rago zai zama mutuwarsa, domin hannuwansa sun ƙi su yi aiki. ");
INSERT INTO hausa_vpl VALUES ("PR21_26","021_21_26","PRO","21","26","26","Dukan yini yana marmari ya sami ƙari, amma mai adalci yakan bayar hannu sake. ");
INSERT INTO hausa_vpl VALUES ("PR21_27","021_21_27","PRO","21","27","27","Hadayar mugaye abin ƙyama ne, balle ma in aka kawo da mugun nufi! ");
INSERT INTO hausa_vpl VALUES ("PR21_28","021_21_28","PRO","21","28","28","Mai ba da shaidar ƙarya zai hallaka, kuma duk wanda ya saurare shi zai hallaka har abada. ");
INSERT INTO hausa_vpl VALUES ("PR21_29","021_21_29","PRO","21","29","29","Mugun mutum kan yi tsayin daka, amma mai aikata gaskiya kan yi tunani a kan abin da yake yi. ");
INSERT INTO hausa_vpl VALUES ("PR21_30","021_21_30","PRO","21","30","30","Babu hikima, babu tunani, babu shirin da zai yi nasara a kan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PR21_31","021_21_31","PRO","21","31","31","Akan shirya doki domin ranar yaƙi, amma nasara tana ga Ubangiji ne. ");
INSERT INTO hausa_vpl VALUES ("PR22_1","021_22_1","PRO","22","1","1","An fi son suna mai kyau fiye da wadata mai yawa; tagomashi kuma ya fi azurfa ko zinariya. ");
INSERT INTO hausa_vpl VALUES ("PR22_2","021_22_2","PRO","22","2","2","Mawadaci da matalauci suna da abu guda. Ubangiji ne Mahaliccinsu duka. ");
INSERT INTO hausa_vpl VALUES ("PR22_3","021_22_3","PRO","22","3","3","Mai basira kan ga damuwa tana zuwa yă nemi mafaka, amma marar azanci kan yi ta tafiya yă kuma sha wahala. ");
INSERT INTO hausa_vpl VALUES ("PR22_4","021_22_4","PRO","22","4","4","Sauƙinkai da tsoron Ubangiji sukan kawo wadata da girmamawa da kuma rai. ");
INSERT INTO hausa_vpl VALUES ("PR22_5","021_22_5","PRO","22","5","5","A hanyoyin mugu akwai kaya da tarko, amma duk wanda ya kiyaye ransa kan kauce musu. ");
INSERT INTO hausa_vpl VALUES ("PR22_6","021_22_6","PRO","22","6","6","Ka hori yaro a hanyar da ya kamata yă bi, kuma sa’ad da ya tsufa ba zai bar ta ba. ");
INSERT INTO hausa_vpl VALUES ("PR22_7","021_22_7","PRO","22","7","7","Mawadaci yakan yi mulki a kan matalauci, mai cin bashi kuwa bawan mai ba da bashi ne. ");
INSERT INTO hausa_vpl VALUES ("PR22_8","021_22_8","PRO","22","8","8","Duk wanda ya shuka mugunta yakan girbe wahala, za a kuma hallaka sandar fushinsa. ");
INSERT INTO hausa_vpl VALUES ("PR22_9","021_22_9","PRO","22","9","9","Mai bayarwa hannu sake shi kansa zai sami albarka, gama yakan raba abincinsa da matalauta. ");
INSERT INTO hausa_vpl VALUES ("PR22_10","021_22_10","PRO","22","10","10","Ka hori mai ba’a, hatsaniya kuwa za tă yi waje; fitina da zargi kuma za su ƙare. ");
INSERT INTO hausa_vpl VALUES ("PR22_11","021_22_11","PRO","22","11","11","Duk mai son tsabtar zuciya wanda kuma jawabinsa mai alheri ne zai zama aminin sarki. ");
INSERT INTO hausa_vpl VALUES ("PR22_12","021_22_12","PRO","22","12","12","Idanun Ubangiji na lura da sani, amma yakan ƙi kalmomin marar aminci. ");
INSERT INTO hausa_vpl VALUES ("PR22_13","021_22_13","PRO","22","13","13","Rago kan ce, “Akwai zaki a waje!” Ko kuma “Za a kashe ni a tituna!” ");
INSERT INTO hausa_vpl VALUES ("PR22_14","021_22_14","PRO","22","14","14","Bakin mazinaciya rami ne mai zurfi; duk wanda yake a ƙarƙashin fushin Ubangiji zai fāɗa a ciki. ");
INSERT INTO hausa_vpl VALUES ("PR22_15","021_22_15","PRO","22","15","15","Wauta tana da yawa a zuciyar yara, amma sandar horo zai kore ta nesa da su. ");
INSERT INTO hausa_vpl VALUES ("PR22_16","021_22_16","PRO","22","16","16","Duk wanda yake danne matalauta don yă azurta kuma duk wanda yake kyauta ga mawadata, dukansu kan talauta. ");
INSERT INTO hausa_vpl VALUES ("PR22_17","021_22_17","PRO","22","17","17","Ka kasa kunne ka kuma saurara ga maganganu masu hikima; ka yi amfani da abin da nake koyarwa, ");
INSERT INTO hausa_vpl VALUES ("PR22_18","021_22_18","PRO","22","18","18","gama yana da daɗi sa’ad da ka kiyaye su a zuciyarka ka kuma kasance da su a shirye a leɓunanka. ");
INSERT INTO hausa_vpl VALUES ("PR22_19","021_22_19","PRO","22","19","19","Domin dogarawarka ta kasance ga Ubangiji, ina koya maka yau, har kai ma. ");
INSERT INTO hausa_vpl VALUES ("PR22_20","021_22_20","PRO","22","20","20","Ban rubuta maka maganganu talatin ba, maganganun shawara da sani, ");
INSERT INTO hausa_vpl VALUES ("PR22_21","021_22_21","PRO","22","21","21","ina koya maka gaskiya da kalmomin da za ka dogara a kai, saboda ka iya ba da amsa daidai ga duk wanda ya aike ka? ");
INSERT INTO hausa_vpl VALUES ("PR22_22","021_22_22","PRO","22","22","22","Kada ka zalunci matalauta a kan suna matalauta kada kuma ka ƙwari wanda ba shi da mai taimako a gaban shari’a, ");
INSERT INTO hausa_vpl VALUES ("PR22_23","021_22_23","PRO","22","23","23","gama Ubangiji zai yi magana dominsu zai kuwa washe waɗanda suka washe su. ");
INSERT INTO hausa_vpl VALUES ("PR22_24","021_22_24","PRO","22","24","24","Kada ka yi abokantaka da mai zafin rai, kada ka haɗa kai da wanda ba shi da wuya ya yi fushi, ");
INSERT INTO hausa_vpl VALUES ("PR22_25","021_22_25","PRO","22","25","25","in ba haka ba za ka koyi hanyoyinsa ka kuma sa kanka a tarko. ");
INSERT INTO hausa_vpl VALUES ("PR22_26","021_22_26","PRO","22","26","26","Kada ka zama mai ɗaukar lamuni ko ka ba da jingina saboda bashi; ");
INSERT INTO hausa_vpl VALUES ("PR22_27","021_22_27","PRO","22","27","27","gama in ka kāsa biya za a ƙwace gadon da kake kwanciya a kai ma. ");
INSERT INTO hausa_vpl VALUES ("PR22_28","021_22_28","PRO","22","28","28","Kada ka matsar da shaidar kan iyakar da kakanninka suka kafa. ");
INSERT INTO hausa_vpl VALUES ("PR22_29","021_22_29","PRO","22","29","29","Kana ganin mutumin da yake da gwaninta a cikin aikinsa? Zai yi wa sarakuna hidima; ba zai yi hidima wa mutanen da ba su iya ba. ");
INSERT INTO hausa_vpl VALUES ("PR23_1","021_23_1","PRO","23","1","1","Sa’ad da ka zauna domin cin abinci da mai mulki, ka lura sosai da abin da yake gabanka, ");
INSERT INTO hausa_vpl VALUES ("PR23_2","021_23_2","PRO","23","2","2","ka kuma sa wuƙa a maƙogwaronka in kai mai ci da yawa ne. ");
INSERT INTO hausa_vpl VALUES ("PR23_3","021_23_3","PRO","23","3","3","Kada ka yi marmarin abincinsa mai daɗi gama wannan abinci ruɗu ne. ");
INSERT INTO hausa_vpl VALUES ("PR23_4","021_23_4","PRO","23","4","4","Kada ka gajiyar da kanka don ka yi arziki; ka kasance da hikimar dainawa. ");
INSERT INTO hausa_vpl VALUES ("PR23_5","021_23_5","PRO","23","5","5","Da ƙyiftawar ido a kan wadata ta ɓace, gama tabbatacce sukan yi fikafikai sukan tashi sama kamar gaggafa. ");
INSERT INTO hausa_vpl VALUES ("PR23_6","021_23_6","PRO","23","6","6","Kada ka ci abincin mai rowa, kada ka yi marmarin abincinsa mai daɗi; ");
INSERT INTO hausa_vpl VALUES ("PR23_7","021_23_7","PRO","23","7","7","gama shi wani irin mutum ne wanda kullum yana tunani game da tsadar abincin. Zai ce maka, “Ci ka sha,” amma zuciyarsa ba ta tare da kai. ");
INSERT INTO hausa_vpl VALUES ("PR23_8","021_23_8","PRO","23","8","8","Za ka yi amai ɗan abin da ka ci dukan daɗin bakinka kuwa zai tafi a banza. ");
INSERT INTO hausa_vpl VALUES ("PR23_9","021_23_9","PRO","23","9","9","Kada ka yi magana da wawa, gama zai yi wa maganar hikimarka ba’a. ");
INSERT INTO hausa_vpl VALUES ("PR23_10","021_23_10","PRO","23","10","10","Kada ka kawar da shaidar iyaka ta dā ko ka ɗiba gonar marayu, ");
INSERT INTO hausa_vpl VALUES ("PR23_11","021_23_11","PRO","23","11","11","gama mai Kāriyarsu yana da ƙarfi; zai kuwa yi magana dominsu. ");
INSERT INTO hausa_vpl VALUES ("PR23_12","021_23_12","PRO","23","12","12","Ka mai da hankali ga umarni ka kuma kasa kunne ga kalmomin sani. ");
INSERT INTO hausa_vpl VALUES ("PR23_13","021_23_13","PRO","23","13","13","Kada ka bar yaro ba horo; in ka yi masa horo da sanda, ba zai mutu ba. ");
INSERT INTO hausa_vpl VALUES ("PR23_14","021_23_14","PRO","23","14","14","Ka hukunta shi da sanda ka ceci ransa daga mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PR23_15","021_23_15","PRO","23","15","15","Ɗana, in zuciyarka mai hikima ce, to, zuciyata za tă yi murna; ");
INSERT INTO hausa_vpl VALUES ("PR23_16","021_23_16","PRO","23","16","16","cikin cikina zai yi farin ciki in leɓunanka suna maganar abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("PR23_17","021_23_17","PRO","23","17","17","Kada ka bar zuciyarka tă yi ƙyashin masu zunubi, amma kullum tsoron Ubangiji za ka yi kishi. ");
INSERT INTO hausa_vpl VALUES ("PR23_18","021_23_18","PRO","23","18","18","Tabbatacce akwai sa zuciya ta nan gaba dominka, kuma sa zuciyarka ba za tă zama a banza ba. ");
INSERT INTO hausa_vpl VALUES ("PR23_19","021_23_19","PRO","23","19","19","Ka saurara, ɗana, ka zama mai hikima, ka kafa zuciyarka a hanyar da take daidai. ");
INSERT INTO hausa_vpl VALUES ("PR23_20","021_23_20","PRO","23","20","20","Kada ka haɗa kai da waɗanda suke shan ruwan inabi da yawa ko masu haɗama kansu da abinci, ");
INSERT INTO hausa_vpl VALUES ("PR23_21","021_23_21","PRO","23","21","21","gama bugaggu da ruwan inabi da masu yawan ci sukan zama matalauta, gama jiri yakan yi musu sutura da tsummoki. ");
INSERT INTO hausa_vpl VALUES ("PR23_22","021_23_22","PRO","23","22","22","Ka kasa kunne ga mahaifinka, wanda ya ba ka rai, kada kuwa ka rena mahaifiyarka sa’ad da ta tsufa. ");
INSERT INTO hausa_vpl VALUES ("PR23_23","021_23_23","PRO","23","23","23","Ka saye gaskiya kada kuwa ka sayar da ita; ka nemi hikima, horo da fahimi. ");
INSERT INTO hausa_vpl VALUES ("PR23_24","021_23_24","PRO","23","24","24","Mahaifin adali yana da farin ciki sosai; duk wanda yake da ɗa mai hikima yakan ji daɗinsa. ");
INSERT INTO hausa_vpl VALUES ("PR23_25","021_23_25","PRO","23","25","25","Bari mahaifinka da mahaifiyarka su yi murna; bari wadda ta haife ka tă yi farin ciki! ");
INSERT INTO hausa_vpl VALUES ("PR23_26","021_23_26","PRO","23","26","26","Ɗana, ka ba ni zuciyarka bari kuma idanunka su kiyaye hanyoyina, ");
INSERT INTO hausa_vpl VALUES ("PR23_27","021_23_27","PRO","23","27","27","gama karuwa rami ne mai zurfi mace marar aminci matsattsiyar rijiya ce. ");
INSERT INTO hausa_vpl VALUES ("PR23_28","021_23_28","PRO","23","28","28","Kamar ’yan fashi, takan kwanta tana jira tana kuma ninka rashin aminci a cikin maza. ");
INSERT INTO hausa_vpl VALUES ("PR23_29","021_23_29","PRO","23","29","29","Wa yake wayyo? Wa yake baƙin ciki? Wa yake neman fada? Wa yake gunaguni? Wa yake da raunuka ba dalili? Wa yake da jan idanu? ");
INSERT INTO hausa_vpl VALUES ("PR23_30","021_23_30","PRO","23","30","30","Waɗanda suke daɗe suna shan ruwan inabi, waɗanda suke neman ƙoƙon damammen ruwan inabi. ");
INSERT INTO hausa_vpl VALUES ("PR23_31","021_23_31","PRO","23","31","31","Kada ka ƙyifce ido a ruwan inabi sa’ad da ya yi ja, sa’ad da yana da kyan gani a cikin ƙwarya, sa’ad da yana gangarawa sumul a maƙogwaro! ");
INSERT INTO hausa_vpl VALUES ("PR23_32","021_23_32","PRO","23","32","32","A ƙarshe yana sara kamar maciji da kuma dafi kamar gamsheƙa. ");
INSERT INTO hausa_vpl VALUES ("PR23_33","021_23_33","PRO","23","33","33","Idanunka za su riƙa gane-gane, zuciyarka kuma za su riƙa tunani abubuwa masu rikitarwa. ");
INSERT INTO hausa_vpl VALUES ("PR23_34","021_23_34","PRO","23","34","34","Za ka zama kamar wanda yake barci a tsakiyar tekuna, kwance a sama itacen jirgin ruwa. ");
INSERT INTO hausa_vpl VALUES ("PR23_35","021_23_35","PRO","23","35","35","Za ka ce “Sun buge ni, amma ban ji ciwo ba! Sun daddoke ni, amma ba na jin zafinsa! Yaushe zan farka don in ƙara shan wani?” ");
INSERT INTO hausa_vpl VALUES ("PR24_1","021_24_1","PRO","24","1","1","Kada ka yi ƙyashin mugaye, kada ka yi sha’awar ƙungiyarsu; ");
INSERT INTO hausa_vpl VALUES ("PR24_2","021_24_2","PRO","24","2","2","gama leɓunansu suna maganar tā-da-na-zaune-tsaye ne. ");
INSERT INTO hausa_vpl VALUES ("PR24_3","021_24_3","PRO","24","3","3","Ta wurin hikima ce ake gina gida, kuma ta wurin fahimi ake kafa ta; ");
INSERT INTO hausa_vpl VALUES ("PR24_4","021_24_4","PRO","24","4","4","ta wurin sani ɗakunanta sukan cika da kyawawan kayayyaki masu daraja. ");
INSERT INTO hausa_vpl VALUES ("PR24_5","021_24_5","PRO","24","5","5","Mutum mai hikima yana da iko sosai, kuma mutum mai sani yakan ƙaru da ƙarfi; ");
INSERT INTO hausa_vpl VALUES ("PR24_6","021_24_6","PRO","24","6","6","don yin yaƙi kana bukatar bishewa, kuma don ka yi nasara kana bukatar mashawarta masu yawa. ");
INSERT INTO hausa_vpl VALUES ("PR24_7","021_24_7","PRO","24","7","7","Hikima ta yi wa wawa nisa ƙwarai a cikin taro a ƙofar gari ba shi da ta cewa. ");
INSERT INTO hausa_vpl VALUES ("PR24_8","021_24_8","PRO","24","8","8","Duk mai ƙulla mugunta za a ɗauka shi mai kuta hargitsi ne. ");
INSERT INTO hausa_vpl VALUES ("PR24_9","021_24_9","PRO","24","9","9","Makircin wawa zunubi ne, mutane kuma sukan yi ƙyamar mai ba’a. ");
INSERT INTO hausa_vpl VALUES ("PR24_10","021_24_10","PRO","24","10","10","In ba ka da ƙarfi a lokacin wahala, ka tabbatar kai marar ƙarfi ne sosai! ");
INSERT INTO hausa_vpl VALUES ("PR24_11","021_24_11","PRO","24","11","11","Ka kuɓutar da waɗanda ake ja zuwa inda za a kashe su; ka riƙe waɗanda suke tangaɗi zuwa wajen yanka. ");
INSERT INTO hausa_vpl VALUES ("PR24_12","021_24_12","PRO","24","12","12","In kuka ce, “Ai, ba mu san wani abu a kai wannan ba,” shi da yake awon ba shi da zuciyar ganewa ne? Shi da yake tsare ranka bai sani ba ne? Ba zai sāka wa kowane mutum bisa ga abin da ya aikata ba? ");
INSERT INTO hausa_vpl VALUES ("PR24_13","021_24_13","PRO","24","13","13","Ka sha zuma, ɗana, ka sha zuma gama tana da kyau; zuma daga kaki yana da zaƙi a harshenka. ");
INSERT INTO hausa_vpl VALUES ("PR24_14","021_24_14","PRO","24","14","14","Ka kuma san cewa hikima tana da zaƙi ga rai; in ka same ta, akwai sa zuciya ta nan gaba dominka, kuma sa zuciyarka ba za tă zama a banza ba. ");
INSERT INTO hausa_vpl VALUES ("PR24_15","021_24_15","PRO","24","15","15","Kada ka kwanta kana fako kamar ɗan iska don ƙwace gidan adali, kada ka ƙwace masa wurin zama; ");
INSERT INTO hausa_vpl VALUES ("PR24_16","021_24_16","PRO","24","16","16","gama ko da adali ya fāɗi sau bakwai, yakan tashi kuma, amma bala’i kan kwantar da mugaye. ");
INSERT INTO hausa_vpl VALUES ("PR24_17","021_24_17","PRO","24","17","17","Kada ka yi dariya sa’ad da abokin gāba ya fāɗi; sa’ad da ya yi tuntuɓe, kada ka yi farin ciki, ");
INSERT INTO hausa_vpl VALUES ("PR24_18","021_24_18","PRO","24","18","18","in ba haka ba in Ubangiji ya gani ba zai amince ba ya kuma juye fushinsa daga gare shi. ");
INSERT INTO hausa_vpl VALUES ("PR24_19","021_24_19","PRO","24","19","19","Kada ka ji tsoro saboda masu mugunta ko ka yi ƙyashin mugaye, ");
INSERT INTO hausa_vpl VALUES ("PR24_20","021_24_20","PRO","24","20","20","gama mugu ba shi da zuciya ta nan gaba, kuma fitilar mugaye za tă mutu. ");
INSERT INTO hausa_vpl VALUES ("PR24_21","021_24_21","PRO","24","21","21","Ka ji tsoron Ubangiji da kuma sarki, ɗana, kuma kada ka haɗa kai da masu tayarwa, ");
INSERT INTO hausa_vpl VALUES ("PR24_22","021_24_22","PRO","24","22","22","gama za a tura waɗannan biyu zuwa hallaka nan da nan, kuma wa ya sani irin bala’in da za su iya kawowa? ");
INSERT INTO hausa_vpl VALUES ("PR24_23","021_24_23","PRO","24","23","23","Waɗannan ma maganganun masu hikima ne, Nunan sonkai a shari’a ba shi da kyau. ");
INSERT INTO hausa_vpl VALUES ("PR24_24","021_24_24","PRO","24","24","24","Duk wanda ya ce wa mai laifi, “Ba ka da laifi”, mutane za su la’ance shi al’umma kuma za tă ce ba a san shi ba. ");
INSERT INTO hausa_vpl VALUES ("PR24_25","021_24_25","PRO","24","25","25","Amma zai zama da lafiya ga duk waɗanda suka hukunta masu laifi, kuma babban albarka zai zo a kansu. ");
INSERT INTO hausa_vpl VALUES ("PR24_26","021_24_26","PRO","24","26","26","Amsa da take ta gaskiya tana kamar sumba a leɓuna. ");
INSERT INTO hausa_vpl VALUES ("PR24_27","021_24_27","PRO","24","27","27","Ka gama aikinka ka kuma shirya gonakinka; bayan haka, ka gina gidanka. ");
INSERT INTO hausa_vpl VALUES ("PR24_28","021_24_28","PRO","24","28","28","Kada ka ba da shaida a kan maƙwabcinka ba tare da isashen dalili ba, ko ka yi amfani da leɓunanka ka yi ruɗu. ");
INSERT INTO hausa_vpl VALUES ("PR24_29","021_24_29","PRO","24","29","29","Kada ka ce, “Zan yi masa kamar yadda ya yi mini; zan rama abin da wannan mutum ya yi mini.” ");
INSERT INTO hausa_vpl VALUES ("PR24_30","021_24_30","PRO","24","30","30","Na wuce cikin gonar rago, na wuce cikin gonar inabin mutumin da ba shi da azanci; ");
INSERT INTO hausa_vpl VALUES ("PR24_31","021_24_31","PRO","24","31","31","ƙayayyuwa sun yi girma ko’ina, ciyayi sun rufe ƙasar, katangar duwatsu duk ta rushe. ");
INSERT INTO hausa_vpl VALUES ("PR24_32","021_24_32","PRO","24","32","32","Na yi tunani a zuciyata na kuwa koyi darasi daga abin da na gani. ");
INSERT INTO hausa_vpl VALUES ("PR24_33","021_24_33","PRO","24","33","33","Ɗan barci, ɗan gyangyaɗi, ɗan naɗin hannuwa don a huta, ");
INSERT INTO hausa_vpl VALUES ("PR24_34","021_24_34","PRO","24","34","34","sai talauci ya shigo maka kamar ’yan fashi rashi kuma ya zo maka kamar mai hari. ");
INSERT INTO hausa_vpl VALUES ("PR25_1","021_25_1","PRO","25","1","1","Waɗannan ƙarin karin maganar Solomon ne waɗanda mutanen Hezekiya sarkin Yahuda suka tara. ");
INSERT INTO hausa_vpl VALUES ("PR25_2","021_25_2","PRO","25","2","2","Ɗaukakar Allah ce a ɓoye batun; a bayyana batun kuwa ɗaukakar sarakuna ne. ");
INSERT INTO hausa_vpl VALUES ("PR25_3","021_25_3","PRO","25","3","3","Kamar yadda sammai suna can bisa duniya kuma tana da zurfi, haka zukatan sarakuna suka wuce a bincika. ");
INSERT INTO hausa_vpl VALUES ("PR25_4","021_25_4","PRO","25","4","4","Ka tace azurfa sai kayan su fito don maƙerin azurfa; ");
INSERT INTO hausa_vpl VALUES ("PR25_5","021_25_5","PRO","25","5","5","ka cire mugaye daga gaban sarki, kursiyinsa kuwa zai kahu ta wurin adalci. ");
INSERT INTO hausa_vpl VALUES ("PR25_6","021_25_6","PRO","25","6","6","Kada ka ɗaukaka kanka a gaban sarki, kada kuma ka nemi wa kanka wuri a cikin manyan mutane; ");
INSERT INTO hausa_vpl VALUES ("PR25_7","021_25_7","PRO","25","7","7","gara ya ce maka, “Ka hauro nan,” da a ƙasƙantar da kai a gaban wani mai makami. Abin da ka gani da idanunka ");
INSERT INTO hausa_vpl VALUES ("PR25_8","021_25_8","PRO","25","8","8","kada ka yi garaje kai ƙara a majalisa, gama me za ka yi a ƙarshe in maƙwabcinka ya ba ka kunya? ");
INSERT INTO hausa_vpl VALUES ("PR25_9","021_25_9","PRO","25","9","9","In kai da maƙwabcinka kuka yi gardama, kada ka tona asirin wani, ");
INSERT INTO hausa_vpl VALUES ("PR25_10","021_25_10","PRO","25","10","10","in ba haka ba duk wanda ya ji zai kunyata ka ba za ka kuma taɓa rabuwa da wannan mummuna suna ba. ");
INSERT INTO hausa_vpl VALUES ("PR25_11","021_25_11","PRO","25","11","11","Kalmar da aka faɗa daidai tana kamar zubin zinariyar da aka yi a mazubin azurfa. ");
INSERT INTO hausa_vpl VALUES ("PR25_12","021_25_12","PRO","25","12","12","Kamar ’yan kunnen zinariya ko kuwa kayan ado na zinariya zalla haka yake da tsawatawar mai hikima ga kunne mai saurarawa. ");
INSERT INTO hausa_vpl VALUES ("PR25_13","021_25_13","PRO","25","13","13","Kamar sanyin ƙanƙara a lokacin girbi haka ɗan saƙo mai aminci wanda aka aika; ya wartsakar da ran waɗanda suka aike shi. ");
INSERT INTO hausa_vpl VALUES ("PR25_14","021_25_14","PRO","25","14","14","Kamar gizagizai da kuma iska marar ruwan sama haka mutumin da yake fariya a kan kyautan da ba ya bayarwa. ");
INSERT INTO hausa_vpl VALUES ("PR25_15","021_25_15","PRO","25","15","15","Ta wurin haƙuri akan rinjaye mai mulki, magana mai hankali kan karye ƙashi. ");
INSERT INTO hausa_vpl VALUES ("PR25_16","021_25_16","PRO","25","16","16","In ka sami zuma, ka sha isashe kawai, in ya yi yawa, za ka yi amai. ");
INSERT INTO hausa_vpl VALUES ("PR25_17","021_25_17","PRO","25","17","17","Kada ka cika ziyarar gidan maƙwabcinka yawan ganinka zai sa ya ƙi ka. ");
INSERT INTO hausa_vpl VALUES ("PR25_18","021_25_18","PRO","25","18","18","Kamar sanda ko takobi ko kibiya mai tsini haka yake da mutumin da yake ba da shaidar ƙarya a kan maƙwabcinsa. ");
INSERT INTO hausa_vpl VALUES ("PR25_19","021_25_19","PRO","25","19","19","Kamar haƙori mai ciwo ko yin tafiya da gurguwar ƙafa haka yake ga mai dogara da marasa aminci a lokacin wahala. ");
INSERT INTO hausa_vpl VALUES ("PR25_20","021_25_20","PRO","25","20","20","Kamar wanda ya tuɓe riga a ranar da ake sanyi, ko kuwa kamar zuba ruwan tsami a kanwa, haka yake da mai rera waƙoƙi ga mai baƙin ciki. ");
INSERT INTO hausa_vpl VALUES ("PR25_21","021_25_21","PRO","25","21","21","In abokin gābanka yana jin yunwa, ka ba shi abinci ya ci; in yana jin ƙishi, ka ba shi ruwa ya sha. ");
INSERT INTO hausa_vpl VALUES ("PR25_22","021_25_22","PRO","25","22","22","Ta yin haka, za ka tara garwashin wuta mai ci a kansa, Ubangiji kuma zai sāka maka. ");
INSERT INTO hausa_vpl VALUES ("PR25_23","021_25_23","PRO","25","23","23","Kamar yadda iskar arewa kan kawo ruwan sama, haka jita-jita kan kawo fushi. ");
INSERT INTO hausa_vpl VALUES ("PR25_24","021_25_24","PRO","25","24","24","Gara a zauna a kusurwar rufin ɗaki da a zauna a gida ɗaya da mace mai fitina. ");
INSERT INTO hausa_vpl VALUES ("PR25_25","021_25_25","PRO","25","25","25","Kamar ruwan sanyi ga ran da ya gaji haka yake da jin labari mai daɗi daga ƙasa mai nisa. ");
INSERT INTO hausa_vpl VALUES ("PR25_26","021_25_26","PRO","25","26","26","Kamar rafi mai laka ko rijiyar da ta gurɓace haka yake da mai adalci wanda ya miƙa wuya ga mugaye. ");
INSERT INTO hausa_vpl VALUES ("PR25_27","021_25_27","PRO","25","27","27","Ba shi da kyau ka sha zuma da yawa, haka ma ba shi da kyau ka nemi girma wa kanka. ");
INSERT INTO hausa_vpl VALUES ("PR25_28","021_25_28","PRO","25","28","28","Kamar birni da katangarsa sun rushe haka yake da mutumin da ba ya iya danne fushinsa. ");
INSERT INTO hausa_vpl VALUES ("PR26_1","021_26_1","PRO","26","1","1","Kamar ƙanƙara a rani ko ruwan sama a lokacin girbi, haka girmamawa bai dace da wawa ba. ");
INSERT INTO hausa_vpl VALUES ("PR26_2","021_26_2","PRO","26","2","2","Kamar gwara mai yawo ko alallaka mai firiya, haka yake da la’anar da ba tă dace tă kama ka ba take. ");
INSERT INTO hausa_vpl VALUES ("PR26_3","021_26_3","PRO","26","3","3","Bulala don doki, linzami don jaki, sanda kuma don bayan wawaye! ");
INSERT INTO hausa_vpl VALUES ("PR26_4","021_26_4","PRO","26","4","4","Kada ka amsa wa wawa bisa ga wautarsa, in ba haka ba kai kanka za ka zama kamar sa. ");
INSERT INTO hausa_vpl VALUES ("PR26_5","021_26_5","PRO","26","5","5","Ka amsa wa wawa bisa ga wautarsa, in ba haka ba zai ga kansa mai hikima ne. ");
INSERT INTO hausa_vpl VALUES ("PR26_6","021_26_6","PRO","26","6","6","Kamar datsewar ƙafafun wani ko shan dafi haka yake da a aika da saƙo ta hannun wawa. ");
INSERT INTO hausa_vpl VALUES ("PR26_7","021_26_7","PRO","26","7","7","Kamar ƙafafun gurgun da suka yi laƙwas haka karin magana yake a bakin wawa. ");
INSERT INTO hausa_vpl VALUES ("PR26_8","021_26_8","PRO","26","8","8","Kamar ɗaura dutse a majajjawa haka yake da girmama wawa. ");
INSERT INTO hausa_vpl VALUES ("PR26_9","021_26_9","PRO","26","9","9","Kamar suƙar ƙaya a hannun wanda ya bugu haka karin magana yake a bakin wawa. ");
INSERT INTO hausa_vpl VALUES ("PR26_10","021_26_10","PRO","26","10","10","Kamar maharbi wanda yake jin wa kowa rauni haka yake da duk wanda ya yi hayan wawa ko wani mai wucewa. ");
INSERT INTO hausa_vpl VALUES ("PR26_11","021_26_11","PRO","26","11","11","Kamar yadda kare kan koma ga amansa, haka wawa kan maimaita wautarsa. ");
INSERT INTO hausa_vpl VALUES ("PR26_12","021_26_12","PRO","26","12","12","Gwamma riƙaƙƙen wawa da mutum mai ganin kansa mai hikima ne. ");
INSERT INTO hausa_vpl VALUES ("PR26_13","021_26_13","PRO","26","13","13","Rago yakan ce, “Akwai zaki a kan hanya, zaki mai faɗa yana yawo a tituna!” ");
INSERT INTO hausa_vpl VALUES ("PR26_14","021_26_14","PRO","26","14","14","Kamar yadda ƙofa kan juya a ƙyaurensa, haka rago yake jujjuya a gadonsa. ");
INSERT INTO hausa_vpl VALUES ("PR26_15","021_26_15","PRO","26","15","15","Rago kan sa hannunsa a kwano ba ya ma iya ɗaga shi ya kai bakinsa. ");
INSERT INTO hausa_vpl VALUES ("PR26_16","021_26_16","PRO","26","16","16","Rago yana gani yana da hikima fiye da mutane bakwai da suke ba da amsa da dalilai a kan ra’ayinsu. ");
INSERT INTO hausa_vpl VALUES ("PR26_17","021_26_17","PRO","26","17","17","Kamar wani da ya kama kare a kunnuwa haka yake da mai wucewa da ya tsoma baki a faɗan da ba ruwansa. ");
INSERT INTO hausa_vpl VALUES ("PR26_18","021_26_18","PRO","26","18","18","Kamar yadda mahaukaci yake harbin cukwimai ko kibiyoyi masu dafi ");
INSERT INTO hausa_vpl VALUES ("PR26_19","021_26_19","PRO","26","19","19","haka yake da mutumin da ya ruɗe maƙwabci sa’an nan ya ce, “Wasa ne kawai nake yi!” ");
INSERT INTO hausa_vpl VALUES ("PR26_20","021_26_20","PRO","26","20","20","In ba itace wuta takan mutu; haka kuma in ba mai gulma ba za a yi faɗa ba. ");
INSERT INTO hausa_vpl VALUES ("PR26_21","021_26_21","PRO","26","21","21","Kamar yadda gawayi yake ga murhu, itace kuma ga wuta, haka mutum mai neman faɗa yake ga faɗa. ");
INSERT INTO hausa_vpl VALUES ("PR26_22","021_26_22","PRO","26","22","22","Kalmomin mai gulma suna kama da burodi mai daɗi; sukan gangara can cikin cikin mutum. ");
INSERT INTO hausa_vpl VALUES ("PR26_23","021_26_23","PRO","26","23","23","Kamar kaskon da aka dalaye da azurfar da ba a tace ba haka leɓuna masu mugun zuciya. ");
INSERT INTO hausa_vpl VALUES ("PR26_24","021_26_24","PRO","26","24","24","Mai yin ƙiyayya yakan ɓoye kansa da maganar bakinsa, amma a cikin zuciyarsa yana cike da munafunci ");
INSERT INTO hausa_vpl VALUES ("PR26_25","021_26_25","PRO","26","25","25","Ko da jawabinsa ya ɗauki hankali, kada ka gaskata shi, gama abubuwa ƙyama guda bakwai sun cika zuciyarsa. ");
INSERT INTO hausa_vpl VALUES ("PR26_26","021_26_26","PRO","26","26","26","Wataƙila ya ɓoye ƙiyayyarsa da ƙarya, duk da haka za a tone muguntarsa a cikin taro. ");
INSERT INTO hausa_vpl VALUES ("PR26_27","021_26_27","PRO","26","27","27","In mutum ya haƙa rami, shi zai fāɗi a ciki; in mutum ya mirgino dutse, dutsen zai mirgine a kansa. ");
INSERT INTO hausa_vpl VALUES ("PR26_28","021_26_28","PRO","26","28","28","Harshe mai faɗin ƙarya yana ƙin waɗanda yake ɓata musu rai, daɗin baki kuma yakan aikata ɓarna. ");
INSERT INTO hausa_vpl VALUES ("PR27_1","021_27_1","PRO","27","1","1","Kada ka yi fariya a kan gobe gama ba san abin da ranar za tă kawo ba. ");
INSERT INTO hausa_vpl VALUES ("PR27_2","021_27_2","PRO","27","2","2","Ka bar wani ya yabe ka, ba kai kanka ba; wani dabam, ba leɓunanka ba. ");
INSERT INTO hausa_vpl VALUES ("PR27_3","021_27_3","PRO","27","3","3","Dutse yana da nauyi yashi kuma wahala ce, amma tsokanar wawa ta fi su duka nauyi. ");
INSERT INTO hausa_vpl VALUES ("PR27_4","021_27_4","PRO","27","4","4","Fushi mugun abu ne mai hallakarwa, amma wa zai iya tsaya a gaban kishi? ");
INSERT INTO hausa_vpl VALUES ("PR27_5","021_27_5","PRO","27","5","5","Gara tsawatawar da ake yi a fili da ƙaunar da ake yi a ɓoye. ");
INSERT INTO hausa_vpl VALUES ("PR27_6","021_27_6","PRO","27","6","6","Za a iya amince da rauni daga aboki, amma abokin gāba ko da ya sumbace ka kada ka sake da shi! ");
INSERT INTO hausa_vpl VALUES ("PR27_7","021_27_7","PRO","27","7","7","Duk wanda ya ƙoshi da zuma, ba ya marmarinsa kuma amma wanda yake yunwa ko abin da yake da ɗaci ma zai ji shi da zaƙi. ");
INSERT INTO hausa_vpl VALUES ("PR27_8","021_27_8","PRO","27","8","8","Kamar tsuntsun da ya ɓace daga sheƙarsa haka yake da mutumin da ya bar gidansa. ");
INSERT INTO hausa_vpl VALUES ("PR27_9","021_27_9","PRO","27","9","9","Man shafawa mai ƙanshi da kuma turare kan faranta zuciya, gaisuwar amini kuma takan fito daga shawarar kirki. ");
INSERT INTO hausa_vpl VALUES ("PR27_10","021_27_10","PRO","27","10","10","Kada ka manta da abokinka da kuma abokin mahaifinka, kuma kada ka tafi gidan ɗan’uwanka sa’ad da masifa ta same ka, gara ka je wurin maƙwabci na kusa da ka je wurin ɗan’uwan da yake da nisa. ");
INSERT INTO hausa_vpl VALUES ("PR27_11","021_27_11","PRO","27","11","11","Ka zama mai hikima, ɗana, ka kuma faranta mini zuciya; zan iya amsa kowace irin suƙar da wani zai yi mini. ");
INSERT INTO hausa_vpl VALUES ("PR27_12","021_27_12","PRO","27","12","12","Mai basira kan hango hatsari ya kuma kauce, marar azanci zai yi ta kutsa kai ciki, daga baya ya yi da na sani. ");
INSERT INTO hausa_vpl VALUES ("PR27_13","021_27_13","PRO","27","13","13","A karɓe rigunan wanda ya ɗauki lamunin baƙo; a riƙe shi jingina in ya yi shi don mace marar aminci. ");
INSERT INTO hausa_vpl VALUES ("PR27_14","021_27_14","PRO","27","14","14","In mutum ya albarkaci maƙwabcinsa da murya mai ƙarfi da sassafe, za a ɗauka shi a matsayin la’ana. ");
INSERT INTO hausa_vpl VALUES ("PR27_15","021_27_15","PRO","27","15","15","Mace mai fitina kamar ɗiɗɗigar ruwa take ba ƙaƙƙautawa; ");
INSERT INTO hausa_vpl VALUES ("PR27_16","021_27_16","PRO","27","16","16","hana ta yana kamar yin ƙoƙari tsai da iska ne ko yin ƙoƙarin cafke mai a tafin hannunka. ");
INSERT INTO hausa_vpl VALUES ("PR27_17","021_27_17","PRO","27","17","17","Kamar yadda ƙarfe kan wasa ƙarfe haka mutum kan koyi daga mutum. ");
INSERT INTO hausa_vpl VALUES ("PR27_18","021_27_18","PRO","27","18","18","Duk wanda ya lura da itacen ɓaure, zai ci ’ya’yansa, kuma duk wanda ya lura da maigidansa za a girmama shi. ");
INSERT INTO hausa_vpl VALUES ("PR27_19","021_27_19","PRO","27","19","19","Kamar yadda ruwa kan nuna yadda fuska take, haka zuciyar mutum kan nuna irin mutumin. ");
INSERT INTO hausa_vpl VALUES ("PR27_20","021_27_20","PRO","27","20","20","Mutuwa da Hallaka ba sa ƙoshi, haka idanun mutum ba sa ƙoshi da gani. ");
INSERT INTO hausa_vpl VALUES ("PR27_21","021_27_21","PRO","27","21","21","Ana gwajin azurfa da kuma zinariya da wuta, amma akan gwada mutum ta wurin yabon da ya samu. ");
INSERT INTO hausa_vpl VALUES ("PR27_22","021_27_22","PRO","27","22","22","Ko da ka daka wawa a turmi, kana daka shi kamar hatsi da taɓarya, ba za ka fid da wauta daga gare shi ba. ");
INSERT INTO hausa_vpl VALUES ("PR27_23","021_27_23","PRO","27","23","23","Ka tabbata ka san lafiyar garken tumakinka, ka mai da hankali ga garken shanunka; ");
INSERT INTO hausa_vpl VALUES ("PR27_24","021_27_24","PRO","27","24","24","domin dukiya ba ta dawwama har abada, ba a kuma kasance da rawani daga tsara zuwa tsara. ");
INSERT INTO hausa_vpl VALUES ("PR27_25","021_27_25","PRO","27","25","25","Sa’ad da aka yanki ingirci sabon toho kuma ya bayyana aka kuma tattara ciyawa daga tuddai, ");
INSERT INTO hausa_vpl VALUES ("PR27_26","021_27_26","PRO","27","26","26","gashin raguna za su tanada maka tufafi, za ka iya sayi gonaki masu kyau da kuɗin awaki. ");
INSERT INTO hausa_vpl VALUES ("PR27_27","021_27_27","PRO","27","27","27","Za ka kasance da madarar awaki mai yawa don ka ciyar da kanka da kuma iyalinka ka kuma inganta bayinka mata. ");
INSERT INTO hausa_vpl VALUES ("PR28_1","021_28_1","PRO","28","1","1","Mugu yakan gudu ko babu wanda yake korarsa, amma adalai suna da ƙarfin hali kamar zaki. ");
INSERT INTO hausa_vpl VALUES ("PR28_2","021_28_2","PRO","28","2","2","Sa’ad da ƙasa ta yi tayarwa, takan kasance da masu mulki da yawa, amma mai fahimi da sani kan mai da zaman lafiya. ");
INSERT INTO hausa_vpl VALUES ("PR28_3","021_28_3","PRO","28","3","3","Mai mulkin da ya danne talakawa yana kama da ruwan saman da ya lalatar da hatsi. ");
INSERT INTO hausa_vpl VALUES ("PR28_4","021_28_4","PRO","28","4","4","Duk waɗanda ba sa bin doka yabon mugaye suke yi, amma waɗanda suke yin biyayya da doka suna gāba da mugaye ke nan. ");
INSERT INTO hausa_vpl VALUES ("PR28_5","021_28_5","PRO","28","5","5","Mugaye ba su san gaskiya ba, amma waɗanda suke neman Ubangiji sun santa sosai. ");
INSERT INTO hausa_vpl VALUES ("PR28_6","021_28_6","PRO","28","6","6","Gara matalauci wanda yake tafiya babu abin zargi da mai arziki wanda hanyoyinsa mugaye ne. ");
INSERT INTO hausa_vpl VALUES ("PR28_7","021_28_7","PRO","28","7","7","Duk wanda ya kiyaye doka ɗa ne mai la’akari, amma wanda yake abokantaka da masu zari yakan jawo wa mahaifinsa kunya. ");
INSERT INTO hausa_vpl VALUES ("PR28_8","021_28_8","PRO","28","8","8","Duk wanda ya tara dukiyarsa ta wurin ba da bashi da ruwan da ya wuce misali yana tara wa wani ne wanda zai yi wa talakawa alheri. ");
INSERT INTO hausa_vpl VALUES ("PR28_9","021_28_9","PRO","28","9","9","In wani ya yi kunnuwa ƙashi ga doka ko addu’arsa ma abar ƙyama ce. ");
INSERT INTO hausa_vpl VALUES ("PR28_10","021_28_10","PRO","28","10","10","Duk wanda ya jagorance masu aikata gaskiya a hanyar mugunta zai fāɗa cikin tarkonsa amma marasa abin zargi za su sami gādo mai kyau. ");
INSERT INTO hausa_vpl VALUES ("PR28_11","021_28_11","PRO","28","11","11","Mai arziki zai yi zato shi mai hikima ne a ganinsa, amma matalauci mai basira ya fi shi sanin abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("PR28_12","021_28_12","PRO","28","12","12","Sa’ad da adalai suka yi nasara, kowa yakan yi biki; amma sa’ad da mugu ya samu shugabanci, mutane sukan yi ta ɓuya. ");
INSERT INTO hausa_vpl VALUES ("PR28_13","021_28_13","PRO","28","13","13","Duk wanda ya ɓoye zunubansa ba ya taɓa cin nasara, amma duk wanda ya furta ya kuma ƙi su yakan sami jinƙai. ");
INSERT INTO hausa_vpl VALUES ("PR28_14","021_28_14","PRO","28","14","14","Mai albarka ne mutumin da kullum yake jin tsoron Allah, amma duk wanda ya taurare zuciyarsa yakan shiga wahala. ");
INSERT INTO hausa_vpl VALUES ("PR28_15","021_28_15","PRO","28","15","15","Kamar rurin zaki ko sanɗar beyar haka mugun mutum mai mulki a kan mutane marasa ƙarfi yake. ");
INSERT INTO hausa_vpl VALUES ("PR28_16","021_28_16","PRO","28","16","16","Mugu mai mulki ba shi da azanci, amma duk wanda yake ƙin ƙazamar riba yakan yi tsawon rai. ");
INSERT INTO hausa_vpl VALUES ("PR28_17","021_28_17","PRO","28","17","17","Mutumin da laifin kisa ya yi ta damunsa zai zama mai gudu don tsoro har mutuwa; kada wani ya taimake shi. ");
INSERT INTO hausa_vpl VALUES ("PR28_18","021_28_18","PRO","28","18","18","Duk wanda ya yi tafiya marar abin zargi zai zauna lafiya, amma duk wanda hanyoyinsa mugaye ne zai fāɗi nan da nan. ");
INSERT INTO hausa_vpl VALUES ("PR28_19","021_28_19","PRO","28","19","19","Duk wanda ya nome gonarsa zai sami amfani a yalwace, amma duk wanda yake zaman banza zai zama matalauci a koyaushe. ");
INSERT INTO hausa_vpl VALUES ("PR28_20","021_28_20","PRO","28","20","20","Mutum mai aminci zai cika da albarka, amma duk mai son yin arziki dare ɗaya zai sha hukunci. ");
INSERT INTO hausa_vpl VALUES ("PR28_21","021_28_21","PRO","28","21","21","Nuna sonkai ba shi da kyau, duk da haka mutum zai aikata abin da ba daidai ba saboda ’yar ƙaramar rashawa. ");
INSERT INTO hausa_vpl VALUES ("PR28_22","021_28_22","PRO","28","22","22","Mai rowa yana alla-alla ya yi arziki bai san cewa talauci ne ke jiransa ba. ");
INSERT INTO hausa_vpl VALUES ("PR28_23","021_28_23","PRO","28","23","23","Duk wanda ya tsawata wa wani mutum zai sami yabo a ƙarshe fiye da wanda yake mai daɗin baki. ");
INSERT INTO hausa_vpl VALUES ("PR28_24","021_28_24","PRO","28","24","24","Duk wanda ya yi wa mahaifin ko mahaifiyarsa sata ya kuma ce, “Ai, ba laifi ba ne” abokin mai hallakarwa ne shi. ");
INSERT INTO hausa_vpl VALUES ("PR28_25","021_28_25","PRO","28","25","25","Mai haɗama yakan jawo tā-da-na-zaune-tsaye, amma duk wanda ya dogara ga Ubangiji zai yi nasara. ");
INSERT INTO hausa_vpl VALUES ("PR28_26","021_28_26","PRO","28","26","26","Duk mai dogara ga kansa wawa ne, amma duk wanda yake tafiya da hikima zai zauna lafiya. ");
INSERT INTO hausa_vpl VALUES ("PR28_27","021_28_27","PRO","28","27","27","Duk wanda yake bayarwa ga matalauta ba zai rasa kome ba, amma duk wanda bai kula da su ba yana samu la’ana masu yawa. ");
INSERT INTO hausa_vpl VALUES ("PR28_28","021_28_28","PRO","28","28","28","Sa’ad da mugu ya samu shugabanci, mutane sukan yi ta ɓuya; amma sa’ad da mugu ya hallaka, adali kan ci gaba cikin arziki da lafiya. ");
INSERT INTO hausa_vpl VALUES ("PR29_1","021_29_1","PRO","29","1","1","Mutumin da ya ci gaba da taurinkai bayan an kwaɓe shi ba da daɗewa ba zai hallaka ba makawa. ");
INSERT INTO hausa_vpl VALUES ("PR29_2","021_29_2","PRO","29","2","2","Sa’ad da masu adalci suke cin nasara, mutane kan yi farin ciki sa’ad da mugaye suke mulki, mutane kan yi nishi. ");
INSERT INTO hausa_vpl VALUES ("PR29_3","021_29_3","PRO","29","3","3","Duk mai ƙaunar hikima kan kawo wa mahaifinsa farin ciki, amma wanda yake ma’amala da karuwai kan lalatar da dukiyarsa. ");
INSERT INTO hausa_vpl VALUES ("PR29_4","021_29_4","PRO","29","4","4","Ta wurin yin adalci sarki kan sa ƙasa tă yi ƙarƙo amma duk mai haɗama don cin hanci kan rushe ƙasar. ");
INSERT INTO hausa_vpl VALUES ("PR29_5","021_29_5","PRO","29","5","5","Duk wanda yake wa maƙwabcinsa daɗin baki yana sa wa ƙafafunsa tarko ne. ");
INSERT INTO hausa_vpl VALUES ("PR29_6","021_29_6","PRO","29","6","6","Mugun mutum tarko ne ta wurin zunubinsa, amma mai adalci zai iya rera ya kuma yi murna. ");
INSERT INTO hausa_vpl VALUES ("PR29_7","021_29_7","PRO","29","7","7","Masu adalci sun damu game da adalci don talakawa, amma mugaye ba su da wannan damuwa. ");
INSERT INTO hausa_vpl VALUES ("PR29_8","021_29_8","PRO","29","8","8","Masu ba’a kan kuta faɗa a birni, amma masu hikima sukan kwantar da fushi. ");
INSERT INTO hausa_vpl VALUES ("PR29_9","021_29_9","PRO","29","9","9","In mai hikima ya je wurin shari’a da wawa, wawa kan yi ta fushi yana ta dariya, ba kuwa za a sami salama ba. ");
INSERT INTO hausa_vpl VALUES ("PR29_10","021_29_10","PRO","29","10","10","Masu kisankai sukan ƙi mutum mai mutunci su kuma nema su kashe mai aikata gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PR29_11","021_29_11","PRO","29","11","11","Wawa yakan nuna fushinsa a fili, amma mai hikima kan kanne fushinsa. ");
INSERT INTO hausa_vpl VALUES ("PR29_12","021_29_12","PRO","29","12","12","In mai mulki yana sauraran ƙarairayi, dukan ma’aikatansa za su zama mugaye. ");
INSERT INTO hausa_vpl VALUES ("PR29_13","021_29_13","PRO","29","13","13","Matalauci da azzalumi suna da wannan abu ɗaya. Ubangiji ne yake ba dukansu gani. ");
INSERT INTO hausa_vpl VALUES ("PR29_14","021_29_14","PRO","29","14","14","In sarki yana hukunta talakawa da adalci kursiyinsa kullum zai kasance lafiya. ");
INSERT INTO hausa_vpl VALUES ("PR29_15","021_29_15","PRO","29","15","15","Sandar gyara kan ba da hikima, amma yaron da aka bari ba horo kan jawo kunya ga mahaifiyarsa. ");
INSERT INTO hausa_vpl VALUES ("PR29_16","021_29_16","PRO","29","16","16","Sa’ad da mugaye suke cin nasara, haka zunubi zai yi ta ƙaruwa, amma masu adalci za su ga fāɗuwar waɗannan mutane. ");
INSERT INTO hausa_vpl VALUES ("PR29_17","021_29_17","PRO","29","17","17","Ka hori ɗanka, zai kuwa ba ka salama; zai ba ka farin cikin da kake so. ");
INSERT INTO hausa_vpl VALUES ("PR29_18","021_29_18","PRO","29","18","18","Inda ba wahayi, mutane kan kangare; amma masu albarka ne waɗanda suke kiyaye doka. ");
INSERT INTO hausa_vpl VALUES ("PR29_19","021_29_19","PRO","29","19","19","Ba a yi wa bawa gyara ta wurin magana kawai; ko da ya fahimta ma, ba zai kula ba. ");
INSERT INTO hausa_vpl VALUES ("PR29_20","021_29_20","PRO","29","20","20","Ka ga mutum mai yin magana da garaje? To, gara a sa zuciya ga wawa da a sa zuciya gare shi. ");
INSERT INTO hausa_vpl VALUES ("PR29_21","021_29_21","PRO","29","21","21","In mutum ya yi wa bawansa shagwaɓa tun yana yaro, zai jawo baƙin ciki a ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("PR29_22","021_29_22","PRO","29","22","22","Mutum mai cika fushi yakan tā da faɗa, mai zafin rai kuma kan yi zunubai masu yawa. ");
INSERT INTO hausa_vpl VALUES ("PR29_23","021_29_23","PRO","29","23","23","Fariyar mutum kan jawo masa ƙasƙanci amma mai sauƙinkai kan sami girmamawa. ");
INSERT INTO hausa_vpl VALUES ("PR29_24","021_29_24","PRO","29","24","24","Duk wanda yake abokin ɓarawo abokin gāban kansa ne; yana jin sa yana ta rantsuwa, amma bai isa ya ce kome ba. ");
INSERT INTO hausa_vpl VALUES ("PR29_25","021_29_25","PRO","29","25","25","Jin tsoron mutum tarko ne, amma duk wanda ya dogara ga Ubangiji zai zauna lafiya. ");
INSERT INTO hausa_vpl VALUES ("PR29_26","021_29_26","PRO","29","26","26","Mutane sukan nemi samun farin jini daga wurin sarki, amma daga wurin Ubangiji ne mutum kan sami adalci. ");
INSERT INTO hausa_vpl VALUES ("PR29_27","021_29_27","PRO","29","27","27","Masu adalci suna ƙyamar masu rashin gaskiya; mugaye sukan yi ƙyamar masu aikata gaskiya. ");
INSERT INTO hausa_vpl VALUES ("PR30_1","021_30_1","PRO","30","1","1","Maganganun Agur ɗan Yake, magana ce horarriya. Wannan mutum ya furta wa Itiyel da kuma ga Ukal, ");
INSERT INTO hausa_vpl VALUES ("PR30_2","021_30_2","PRO","30","2","2","“Ni ne mafi jahilci a cikin mutane; ba ni da fahimi irin na mutum. ");
INSERT INTO hausa_vpl VALUES ("PR30_3","021_30_3","PRO","30","3","3","Ban koyi hikima ba, ba ni kuma da sani game da Mai Tsarkin nan, ");
INSERT INTO hausa_vpl VALUES ("PR30_4","021_30_4","PRO","30","4","4","Wane ne ya taɓa haura zuwa sama ya dawo? Wane ne ya tattara iska a tafin hannuwansa? Wane ne ya nannaɗe ruwaye a cikin rigarsa? Wane ne ya kafa dukan iyakokin duniya? Mene ne sunansa, da kuma sunan ɗansa? Faɗa mini in ka sani! ");
INSERT INTO hausa_vpl VALUES ("PR30_5","021_30_5","PRO","30","5","5","“Kowace maganar Allah ba ta da kuskure; shi ne garkuwa ga waɗanda suke neman mafaka daga gare shi. ");
INSERT INTO hausa_vpl VALUES ("PR30_6","021_30_6","PRO","30","6","6","Kada ka ƙara ga maganarsa, in ba haka ba zai tsawata maka ya kuma nuna kai maƙaryaci ne. ");
INSERT INTO hausa_vpl VALUES ("PR30_7","021_30_7","PRO","30","7","7","“Abu biyu ina roƙonka, ya Ubangiji; kada ka hana ni kafin in mutu. ");
INSERT INTO hausa_vpl VALUES ("PR30_8","021_30_8","PRO","30","8","8","Ka kawar da ƙarya da kuma ƙarairayi nesa da ni; kada ka ba ni talauci ko arziki, amma ka ba ni abincina na yini kaɗai. ");
INSERT INTO hausa_vpl VALUES ("PR30_9","021_30_9","PRO","30","9","9","In ba haka ba, zan wadace in ƙi ka har in ce, ‘Wane ne Ubangiji?’ Ko kuwa in zama matalauci in yi sata ta haka in kunyata sunan Allahna. ");
INSERT INTO hausa_vpl VALUES ("PR30_10","021_30_10","PRO","30","10","10","“Kada ka baza ƙarairayi game da bawa ga maigidansa, in ba haka ba, zai la’ance ka, za ka kuwa sha wahala a kan haka. ");
INSERT INTO hausa_vpl VALUES ("PR30_11","021_30_11","PRO","30","11","11","“Akwai waɗanda sukan zagi mahaifinsu ba sa kuma sa wa mahaifiyarsu albarka; ");
INSERT INTO hausa_vpl VALUES ("PR30_12","021_30_12","PRO","30","12","12","waɗanda sukan ɗauka su tsarkaka ne a ganinsu alhali kuwa ƙazamai ne su; ");
INSERT INTO hausa_vpl VALUES ("PR30_13","021_30_13","PRO","30","13","13","waɗanda kullum idanunsu masu kallon reni ne, waɗanda kallon da suke yi na daurin gira ne; ");
INSERT INTO hausa_vpl VALUES ("PR30_14","021_30_14","PRO","30","14","14","waɗanda haƙoransu takuba ne waɗanda kuma muƙamuƙansu tarin wuƙaƙe ne don su cinye matalauta daga duniya da kuma mabukata daga cikin mutane. ");
INSERT INTO hausa_vpl VALUES ("PR30_15","021_30_15","PRO","30","15","15","“Matsattsaku tana da ’ya’ya mata biyu. Suna kuka suna cewa, ‘Ba ni! Ba ni!’ “Akwai abubuwa uku da ba sa taɓa ƙoshi, guda huɗu ba sa taɓa cewa, ‘Ya isa!’ ");
INSERT INTO hausa_vpl VALUES ("PR30_16","021_30_16","PRO","30","16","16","Kabari, mahaifar da ba ta haihuwa, ƙasa, wadda ba ta taɓa ƙoshi da ruwa, da kuma wuta, wadda ba ta taɓa cewa ‘Ya isa!’ ");
INSERT INTO hausa_vpl VALUES ("PR30_17","021_30_17","PRO","30","17","17","“Idon da yake yi wa mahaifi ba’a, wanda yake wa mahaifiya dariyar rashin biyayya, hankakin kwari za su ƙwaƙule masa ido, ungulai za su cinye su. ");
INSERT INTO hausa_vpl VALUES ("PR30_18","021_30_18","PRO","30","18","18","“Akwai abubuwa uku da suke ba ni mamaki, abubuwa huɗu da ba na iya fahimtarsu, ");
INSERT INTO hausa_vpl VALUES ("PR30_19","021_30_19","PRO","30","19","19","yadda gaggafa take firiya a sararin sama, yadda maciji yake tafiya a kan dutse, yadda jirgin ruwa yake tafiya a teku, da kuma sha’ani tsakanin namiji da ’ya mace. ");
INSERT INTO hausa_vpl VALUES ("PR30_20","021_30_20","PRO","30","20","20","“Ga yadda mazinaciya take yi. Takan ci ta share bakinta ta ce, ‘Ban yi wani abu marar kyau ba.’ ");
INSERT INTO hausa_vpl VALUES ("PR30_21","021_30_21","PRO","30","21","21","“Akwai abubuwa uku da duniya kan yi rawan jiki, abubuwa huɗu da ba ta iya jurewa, ");
INSERT INTO hausa_vpl VALUES ("PR30_22","021_30_22","PRO","30","22","22","bawan da ya zama sarki, wawan da ya ƙoshi da abinci, ");
INSERT INTO hausa_vpl VALUES ("PR30_23","021_30_23","PRO","30","23","23","macen da ba a ƙauna wadda ta sami miji, da kuma baiwar da ta ɗauki matsayin uwargijiyarta. ");
INSERT INTO hausa_vpl VALUES ("PR30_24","021_30_24","PRO","30","24","24","“Akwai abubuwa huɗu a duniya da suke ƙanana, duk da haka suna da hikima ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("PR30_25","021_30_25","PRO","30","25","25","Kyashi halittu ne da ba su da ƙarfi sosai, duk da haka suna ajiyar abincinsu da rani; ");
INSERT INTO hausa_vpl VALUES ("PR30_26","021_30_26","PRO","30","26","26","remaye halittu ne da ba su da ƙarfi sosai, duk da haka sukan yi gidajensu a duwatsu; ");
INSERT INTO hausa_vpl VALUES ("PR30_27","021_30_27","PRO","30","27","27","fāra ba su da sarki, duk da haka suna tafiya tare bisa ga girma; ");
INSERT INTO hausa_vpl VALUES ("PR30_28","021_30_28","PRO","30","28","28","ana iya kama ƙadangare da hannu, duk da haka akan same shi a fadodin sarakuna. ");
INSERT INTO hausa_vpl VALUES ("PR30_29","021_30_29","PRO","30","29","29","“Akwai abubuwa uku da suke jan jiki da kuma taƙama a tafiyarsu abubuwa huɗu waɗanda suke kwarjini da taƙama a tafiyarsu, ");
INSERT INTO hausa_vpl VALUES ("PR30_30","021_30_30","PRO","30","30","30","zaki mai ƙarfi a cikin namun jeji, wanda ba ya ratse wa kowa; ");
INSERT INTO hausa_vpl VALUES ("PR30_31","021_30_31","PRO","30","31","31","zakara mai taƙama, da bunsuru, da kuma sarki mai sojoji kewaye da shi. ");
INSERT INTO hausa_vpl VALUES ("PR30_32","021_30_32","PRO","30","32","32","“In ka yi wauta ka kuma ɗaukaka kanka, ko kuwa wani yana ƙulla maka mugunta, ka dāfa hannunka a bisa bakinka! ");
INSERT INTO hausa_vpl VALUES ("PR30_33","021_30_33","PRO","30","33","33","Gama kamar yadda kaɗaɗɗen madara takan kawo mai, murɗa hanci kuma takan sa a yi haɓo, haka tsokanar fushi takan kawo faɗa.” ");
INSERT INTO hausa_vpl VALUES ("PR31_1","021_31_1","PRO","31","1","1","Maganganun Sarki Lemuwel, magana ce horarriya mahaifiyarsa ta koya masa, ");
INSERT INTO hausa_vpl VALUES ("PR31_2","021_31_2","PRO","31","2","2","“Ka saurara, ya ɗana! Ka saurara, ɗan cikina! Ka saurara, ya ɗan amshin addu’ata! ");
INSERT INTO hausa_vpl VALUES ("PR31_3","021_31_3","PRO","31","3","3","Kada ka ba da ƙarfinka a kan mata, ƙarfinka ga waɗanda suka hallaka sarakuna. ");
INSERT INTO hausa_vpl VALUES ("PR31_4","021_31_4","PRO","31","4","4","“Ba na sarakuna ba ne, ya Lemuwel, ba na sarakuna ba ne su sha ruwan inabi, ba na masu mulki ba ne su yi marmarin barasa, ");
INSERT INTO hausa_vpl VALUES ("PR31_5","021_31_5","PRO","31","5","5","don kada su sha su manta da abin da doka ta umarta, su hana wa waɗanda aka danne hakkinsu. ");
INSERT INTO hausa_vpl VALUES ("PR31_6","021_31_6","PRO","31","6","6","A ba da barasa ga waɗanda suke cikin halin ƙaƙa naka yi, ruwan inabi ga waɗanda suke cikin wahala; ");
INSERT INTO hausa_vpl VALUES ("PR31_7","021_31_7","PRO","31","7","7","bari su sha su manta da talaucinsu kada kuma su ƙara tunawa da ɓacin ransu. ");
INSERT INTO hausa_vpl VALUES ("PR31_8","021_31_8","PRO","31","8","8","“Yi magana domin bebaye, domin hakkin dukan waɗanda suke naƙasassu. ");
INSERT INTO hausa_vpl VALUES ("PR31_9","021_31_9","PRO","31","9","9","Yi magana a kuma yi shari’ar adalci; a tsare hakkin talakawa da masu bukata.” ");
INSERT INTO hausa_vpl VALUES ("PR31_10","021_31_10","PRO","31","10","10","Wa yake iya samun mace mai halin kirki? Darajarta ta fi ta lu’ulu’ai. ");
INSERT INTO hausa_vpl VALUES ("PR31_11","021_31_11","PRO","31","11","11","Mijinta yana da cikakken amincewa da ita kuma ba ya rasa wani abu mai daraja. ");
INSERT INTO hausa_vpl VALUES ("PR31_12","021_31_12","PRO","31","12","12","Takan yi masa alheri ba mugunta ba, dukan kwanakin ranta. ");
INSERT INTO hausa_vpl VALUES ("PR31_13","021_31_13","PRO","31","13","13","Takan zaɓi ulu da lilin ta yi ta saƙa da hannuwanta da farin ciki. ");
INSERT INTO hausa_vpl VALUES ("PR31_14","021_31_14","PRO","31","14","14","Ita kamar jirgin ’yan kasuwa ne tana kawo abincinta daga nesa. ");
INSERT INTO hausa_vpl VALUES ("PR31_15","021_31_15","PRO","31","15","15","Takan farka tun da sauran duhu; ta tanada wa iyalinta abinci ta kuma shirya wa ’yan matan gidanta ayyukan da za su yi. ");
INSERT INTO hausa_vpl VALUES ("PR31_16","021_31_16","PRO","31","16","16","Takan lura da gona sosai ta kuma saye ta; daga abin da take samu na kuɗin shiga take shuka gonar inabi. ");
INSERT INTO hausa_vpl VALUES ("PR31_17","021_31_17","PRO","31","17","17","Takan himmantu tă yi aikinta tuƙuru; hannuwanta suna da ƙarfi domin ayyukanta. ");
INSERT INTO hausa_vpl VALUES ("PR31_18","021_31_18","PRO","31","18","18","Takan tabbata akwai riba a kasuwancinta, kuma fitilarta ba ya mutuwa da dare. ");
INSERT INTO hausa_vpl VALUES ("PR31_19","021_31_19","PRO","31","19","19","Da hannunta take riƙe abin kaɗi ta kuma kama abin saƙa da yatsotsinta. ");
INSERT INTO hausa_vpl VALUES ("PR31_20","021_31_20","PRO","31","20","20","Takan marabci talakawa takan kuma taimaki masu bukata. ");
INSERT INTO hausa_vpl VALUES ("PR31_21","021_31_21","PRO","31","21","21","Sa’ad da ƙanƙara ta fāɗi, ba ta jin tsoro saboda gidanta; gama dukansu suna da tufafi masu kauri. ");
INSERT INTO hausa_vpl VALUES ("PR31_22","021_31_22","PRO","31","22","22","Takan yi wa gadonta kayan shimfiɗa; tufafinta kuma na lilin ne mai laushi na shunayya. ");
INSERT INTO hausa_vpl VALUES ("PR31_23","021_31_23","PRO","31","23","23","Ana girmama mijinta a ƙofar shiga birni inda yakan zauna a cikin dattawan gari. ");
INSERT INTO hausa_vpl VALUES ("PR31_24","021_31_24","PRO","31","24","24","Takan yi riguna na lilin ta sayar; takan kuma sayar wa ’yan kasuwa da ɗamara. ");
INSERT INTO hausa_vpl VALUES ("PR31_25","021_31_25","PRO","31","25","25","Ƙarfi da mutunci su ne suturarta; za tă iya yin dariyar kwanaki masu zuwa. ");
INSERT INTO hausa_vpl VALUES ("PR31_26","021_31_26","PRO","31","26","26","Tana magana da hikima, kuma umarnai mai aminci yana a harshenta. ");
INSERT INTO hausa_vpl VALUES ("PR31_27","021_31_27","PRO","31","27","27","Tana lura da sha’anin gidanta kuma ba ta cin abincin ƙyuya. ");
INSERT INTO hausa_vpl VALUES ("PR31_28","021_31_28","PRO","31","28","28","’Ya’yanta sukan tashi su ce da ita mai albarka; haka mijinta ma, yakan kuma yabe ta yana cewa, ");
INSERT INTO hausa_vpl VALUES ("PR31_29","021_31_29","PRO","31","29","29","“Mata da yawa suna yin abubuwan yabo, amma ke kin fi su duka.” ");
INSERT INTO hausa_vpl VALUES ("PR31_30","021_31_30","PRO","31","30","30","Kayan tsari yana ruɗu, kyau kuma kan shuɗe; amma mace mai tsoron Ubangiji abar yabo ce. ");
INSERT INTO hausa_vpl VALUES ("PR31_31","021_31_31","PRO","31","31","31","Ka ba ta ladar da ya dace tă samo wa kanta, bari kuma ayyukanta su kawo mata yabo a ƙofar shiga birni.");
INSERT INTO hausa_vpl VALUES ("EC1_1","022_1_1","ECC","1","1","1","Kalmomin Malami, ɗan Dawuda, Sarki a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("EC1_2","022_1_2","ECC","1","2","2","“Ba amfani! Ba amfani!” In ji Malami. “Gaba ɗaya ba amfani! Kome ba shi da amfani!” ");
INSERT INTO hausa_vpl VALUES ("EC1_3","022_1_3","ECC","1","3","3","Wace riba ce mutum yake samu daga wahalar da yake fama a duniya? ");
INSERT INTO hausa_vpl VALUES ("EC1_4","022_1_4","ECC","1","4","4","Zamanai sukan zo zamanai su wuce, amma duniya tana nan har abada. ");
INSERT INTO hausa_vpl VALUES ("EC1_5","022_1_5","ECC","1","5","5","Rana takan fito rana ta kuma fāɗi, ta kuma gaggauta zuwa inda takan fito. ");
INSERT INTO hausa_vpl VALUES ("EC1_6","022_1_6","ECC","1","6","6","Iska takan hura zuwa kudu ta kuma juya zuwa arewa; tă yi ta kewayewa, tă yi ta koma inda take fitowa. ");
INSERT INTO hausa_vpl VALUES ("EC1_7","022_1_7","ECC","1","7","7","Dukan rafuffuka sukan gangara zuwa teku, duk da haka teku ba ya cika. Daga inda rafuffukan suke fitowa, a can suke komawa kuma. ");
INSERT INTO hausa_vpl VALUES ("EC1_8","022_1_8","ECC","1","8","8","Dukan abubuwa suna kawo gajiya, gaban magana. Ido ba ya gaji da gani, haka ma kunne yă ƙoshi da ji. ");
INSERT INTO hausa_vpl VALUES ("EC1_9","022_1_9","ECC","1","9","9","Abin da ya taɓa kasancewa, zai sāke kasance, abin da aka yi za a sāke yi kuma; babu wani abu sabo a duniya. ");
INSERT INTO hausa_vpl VALUES ("EC1_10","022_1_10","ECC","1","10","10","Akwai wani abin da za a ce, “Duba! Ga wani abu sabo”? Abin yana nan, tun dā can, ya kasance kafin lokacinmu. ");
INSERT INTO hausa_vpl VALUES ("EC1_11","022_1_11","ECC","1","11","11","Ba a tunawa da mutanen dā, haka su ma da ba a haifa ba tukuna waɗanda za su biyo bayansu ba za a tuna da su ba. ");
INSERT INTO hausa_vpl VALUES ("EC1_12","022_1_12","ECC","1","12","12","Ni, Malami, sarki ne bisa Isra’ila a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("EC1_13","022_1_13","ECC","1","13","13","Na dauri aniyata in gwada don in bincika ta wurin hikima dukan abin da ake yi a duniya. Kaya mai nauyi ne Allah ya ɗora a kan mutane! ");
INSERT INTO hausa_vpl VALUES ("EC1_14","022_1_14","ECC","1","14","14","Na ga dukan abubuwan da ake yi a duniya, dukansu ba su da amfani, naushin iska ne kawai. ");
INSERT INTO hausa_vpl VALUES ("EC1_15","022_1_15","ECC","1","15","15","Abin da yake tanƙwararre ba zai miƙu ba; ba za a kuma iya ƙidaya abin da ba shi ba. ");
INSERT INTO hausa_vpl VALUES ("EC1_16","022_1_16","ECC","1","16","16","Na yi tunani a raina na ce, “Duba, na yi girma, na kuma ƙaru da hikima fiye da duk wanda ya taɓa mulki a bisa Urushalima kafin ni; na ɗanɗana hikima mai yawa da kuma ilimi.” ");
INSERT INTO hausa_vpl VALUES ("EC1_17","022_1_17","ECC","1","17","17","Sa’an nan na ɗaura aniyata ga fahimtar hikima, in kuma san bambanci tsakanin hauka da wauta, amma na koyi cewa wannan ma, naushin iska ne kawai. ");
INSERT INTO hausa_vpl VALUES ("EC1_18","022_1_18","ECC","1","18","18","Gama yawan hikima yakan kawo yawan baƙin ciki; yawan sani, yawan ɓacin rai. ");
INSERT INTO hausa_vpl VALUES ("EC2_1","022_2_1","ECC","2","1","1","Na ce wa kaina, “Zo, zan gwada ka da jin daɗi don in ga abin da yake da kyau.” Amma wannan ma ya zama ba amfani. ");
INSERT INTO hausa_vpl VALUES ("EC2_2","022_2_2","ECC","2","2","2","Sai na ce, “Dariya hauka ce. Kuma me jin daɗi yake kawowa?” ");
INSERT INTO hausa_vpl VALUES ("EC2_3","022_2_3","ECC","2","3","3","Na yi ƙoƙari in sa raina yă yi farin ciki da ruwan inabi, in kuma rungumi wauta, hankalina kuma yana yin mini jagora da hikima. Na so in ga abin da yake da daraja ga mutane a duniya a ’yan kwanakinsu. ");
INSERT INTO hausa_vpl VALUES ("EC2_4","022_2_4","ECC","2","4","4","Na yi ayyuka masu girma. Na gina gidaje wa kaina na kuma shuka gonakin inabi. ");
INSERT INTO hausa_vpl VALUES ("EC2_5","022_2_5","ECC","2","5","5","Na yi lambuna da wuraren shaƙatawa, na shuka itatuwa masu ’ya’ya iri-iri a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("EC2_6","022_2_6","ECC","2","6","6","Na yi tankuna don in yi banruwan kurmin itatuwa. ");
INSERT INTO hausa_vpl VALUES ("EC2_7","022_2_7","ECC","2","7","7","Na sayi bayi mata da maza, ina kuma da waɗansu bayin da aka haifa a gidana. Ina da garkunan shanu da na tumaki da na awaki fiye da duk wanda ya taɓa zama a Urushalima kafin ni. ");
INSERT INTO hausa_vpl VALUES ("EC2_8","022_2_8","ECC","2","8","8","Na tara wa kaina azurfa da zinariya, ina da ma’ajin sarakuna da yankuna. Na samo wa kaina mawaƙa mata da maza, da dukan irin matan da kowane namiji zai so. ");
INSERT INTO hausa_vpl VALUES ("EC2_9","022_2_9","ECC","2","9","9","Na ƙasaita fiye da kowane mutumin da ya riga ni zama a Urushalima. Cikin dukan wannan, hikimata ba tă rabu da ni ba. ");
INSERT INTO hausa_vpl VALUES ("EC2_10","022_2_10","ECC","2","10","10","Ban hana kaina duk wani abin da idona ya yi sha’awarsa ba; ban hana zuciyata wani jin daɗi ba. Zuciyata ta yi murna da dukan aikina, wannan kuwa shi ne ladan dukan famata. ");
INSERT INTO hausa_vpl VALUES ("EC2_11","022_2_11","ECC","2","11","11","Duk da haka sa’ad da na duba dukan aikin hannuwana, da abin da na yi fama don in samu, sai kome ya zama ba shi da amfani, naushin iska ne kawai; babu wata riba a duniya. ");
INSERT INTO hausa_vpl VALUES ("EC2_12","022_2_12","ECC","2","12","12","Sai na juya ga tunanina don in lura da hikima, da kuma hauka da wauta. Me ya rage wa magājin sarki yă yi fiye da abin da aka riga aka yi? ");
INSERT INTO hausa_vpl VALUES ("EC2_13","022_2_13","ECC","2","13","13","Na ga cewa hikima ta fi wauta, kamar yadda haske ya fi duhu. ");
INSERT INTO hausa_vpl VALUES ("EC2_14","022_2_14","ECC","2","14","14","Mai hikima ya san inda ya nufa, wawa kuwa yana tafiya a cikin duhu; amma sai na gane cewa ƙaddara ɗaya ce take samunsu. ");
INSERT INTO hausa_vpl VALUES ("EC2_15","022_2_15","ECC","2","15","15","Sai na yi tunani a zuciyata, “Ƙaddarar wawa za tă same ni ni ma. Wace riba ce hikimata za tă jawo mini?” Na ce a zuciyata, “Wannan ma ba shi da amfani.” ");
INSERT INTO hausa_vpl VALUES ("EC2_16","022_2_16","ECC","2","16","16","Gama ba za a ƙara tunawa da mai hikima ko wawa ba; nan gaba za a manta da su. Yadda wawa zai mutu, haka ma mai hikima! ");
INSERT INTO hausa_vpl VALUES ("EC2_17","022_2_17","ECC","2","17","17","Don haka na ƙi jinin rayuwa, gama aikin da ake yi a duniya yana ɓata mini rai. Dukan abin da yake cikinta kuwa ba shi da amfani, naushin iska ne kawai. ");
INSERT INTO hausa_vpl VALUES ("EC2_18","022_2_18","ECC","2","18","18","Na ƙi jinin dukan abubuwan da na yi wahala ina yi a duniya, gama dole in bar su wa na bayana. ");
INSERT INTO hausa_vpl VALUES ("EC2_19","022_2_19","ECC","2","19","19","Wa ya sani ko zai zama mai hikima ko kuma wawa? Duk da haka zai mallaki dukan aikin da na yi da ƙoƙarina da kuma dabarata a duniya. Wannan ma ba shi da amfani. ");
INSERT INTO hausa_vpl VALUES ("EC2_20","022_2_20","ECC","2","20","20","Saboda haka zuciyata ta fara karaya a kan dukan faman aikina a duniya. ");
INSERT INTO hausa_vpl VALUES ("EC2_21","022_2_21","ECC","2","21","21","Gama mutum zai yi aikinsa da dukan hikimarsa, da saninsa, da gwanintarsa, sa’an nan dole yă bar dukan abin da ya mallaka ga wani wanda bai yi wahalar kome a ciki ba. Wannan ma ba shi da amfani, hasara ce mai yawa. ");
INSERT INTO hausa_vpl VALUES ("EC2_22","022_2_22","ECC","2","22","22","Me mutum zai samu daga aikin da ya yi duka, da irin ɗawainiyar da ya sha a kan yin aikin a duniya? ");
INSERT INTO hausa_vpl VALUES ("EC2_23","022_2_23","ECC","2","23","23","Dukan kwanakinsa aikinsa damuwa ce da ɓacin zuciya; ko da dare ma hankalinsa ba a kwance yake ba. Wannan ma ba shi da amfani. ");
INSERT INTO hausa_vpl VALUES ("EC2_24","022_2_24","ECC","2","24","24","Ba abin da mutum zai yi da ya fi yă ci, yă sha, yă ji wa ransa daɗi daga aikinsa. Na lura cewa wannan ma, ya fito daga hannun Allah ne, ");
INSERT INTO hausa_vpl VALUES ("EC2_25","022_2_25","ECC","2","25","25","gama in ba tare da shi ba, wa zai iya ci yă sha yă kuma ji daɗi? ");
INSERT INTO hausa_vpl VALUES ("EC2_26","022_2_26","ECC","2","26","26","Ga wanda ya gamshe shi, Allah yakan ba da hikima da sani da farin ciki, amma ga mai zunubi yakan ba shi aikin tarawa da ajiyar dukiya domin yă miƙa wa wanda ya gamshi Allah. Wannan ma ba shi da amfani, naushin iska ne kawai. ");
INSERT INTO hausa_vpl VALUES ("EC3_1","022_3_1","ECC","3","1","1","Akwai lokaci domin kowane abu, da kuma lokaci domin kowane aiki a duniya. ");
INSERT INTO hausa_vpl VALUES ("EC3_2","022_3_2","ECC","3","2","2","Lokacin haihuwa da lokacin mutuwa, lokacin shuki da lokacin tumɓukewa. ");
INSERT INTO hausa_vpl VALUES ("EC3_3","022_3_3","ECC","3","3","3","Lokacin kisa da lokacin warkarwa, lokacin rushewa da lokacin ginawa. ");
INSERT INTO hausa_vpl VALUES ("EC3_4","022_3_4","ECC","3","4","4","Lokacin kuka da lokacin dariya, lokacin makoki da lokacin rawa. ");
INSERT INTO hausa_vpl VALUES ("EC3_5","022_3_5","ECC","3","5","5","Lokacin warwatsa duwatsu da lokacin tara su, lokacin runguma da lokacin dainawa. ");
INSERT INTO hausa_vpl VALUES ("EC3_6","022_3_6","ECC","3","6","6","Lokacin nema, da lokacin fid da zuciya, lokacin ajiyewa da lokacin zubarwa. ");
INSERT INTO hausa_vpl VALUES ("EC3_7","022_3_7","ECC","3","7","7","Lokacin yagewa da lokacin ɗinkewa, lokacin yin shiru da lokacin magana. ");
INSERT INTO hausa_vpl VALUES ("EC3_8","022_3_8","ECC","3","8","8","Lokacin ƙauna da lokacin ƙiyayya, lokacin yaƙi da lokacin salama. ");
INSERT INTO hausa_vpl VALUES ("EC3_9","022_3_9","ECC","3","9","9","Wace riba ce ma’aikaci yake da ita saboda wahalarsa? ");
INSERT INTO hausa_vpl VALUES ("EC3_10","022_3_10","ECC","3","10","10","Na ga nawayar da Allah ya ɗora a kan mutane. ");
INSERT INTO hausa_vpl VALUES ("EC3_11","022_3_11","ECC","3","11","11","Ya yi kowane abu da kyau a lokacinsa. Ya kuma sa matuƙa a zukatan mutane, duk da haka sun kāsa gane abin da Allah ya yi daga farko zuwa ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("EC3_12","022_3_12","ECC","3","12","12","Na san ba abin da ya fi wa mutane kyau fiye da su ji daɗi su kuma yi alheri yayinda suke da rai. ");
INSERT INTO hausa_vpl VALUES ("EC3_13","022_3_13","ECC","3","13","13","Cewa kowa yă ci, yă sha, yă kuma ji daɗi cikin dukan aikinsa, wannan kyautar Allah ce. ");
INSERT INTO hausa_vpl VALUES ("EC3_14","022_3_14","ECC","3","14","14","Na san cewa duk abin da Allah ya yi zai dawwama har abada; ba abin da za a ƙara ko a rage. Allah ya yi haka domin mutane su girmama shi. ");
INSERT INTO hausa_vpl VALUES ("EC3_15","022_3_15","ECC","3","15","15","Duk abin da yana nan ya taɓa kasancewa, kuma abin da zai kasance, ya taɓa kasancewa; Allah kuma zai nemi bayanin abubuwan da suka wuce. ");
INSERT INTO hausa_vpl VALUES ("EC3_16","022_3_16","ECC","3","16","16","Sai na ga wani abu kuma a duniya, a wurin shari’a, akwai mugunta a can, a wurin adalci, akwai mugunta a can. ");
INSERT INTO hausa_vpl VALUES ("EC3_17","022_3_17","ECC","3","17","17","Sai na yi tunani a zuciyata, “Allah zai shari’anta masu adalci da masu mugunta, gama za a kasance da lokaci domin kowane aiki, lokaci domin kowane abu.” ");
INSERT INTO hausa_vpl VALUES ("EC3_18","022_3_18","ECC","3","18","18","Na sāke yin tunani, “Game da mutane kam, Allah kan gwada su don su san cewa ba su fi dabba ba. ");
INSERT INTO hausa_vpl VALUES ("EC3_19","022_3_19","ECC","3","19","19","Ƙaddarar mutum ɗaya take da ta dabba; ƙaddara ɗaya ce take jiransu biyu. Yadda ɗayan yake mutuwa, haka ma ɗayan. Dukansu numfashinsu iri ɗaya ne; mutum bai fi dabba ba. Kowane abu ba shi da amfani. ");
INSERT INTO hausa_vpl VALUES ("EC3_20","022_3_20","ECC","3","20","20","Duka wuri ɗaya za su tafi; gama duka daga turɓaya suka fito, kuma ga turɓaya duka za su koma. ");
INSERT INTO hausa_vpl VALUES ("EC3_21","022_3_21","ECC","3","21","21","Wa ya tabbatar cewa ruhun mutum yakan tashi sama sa’an nan na dabba yă sauka ƙasa?” ");
INSERT INTO hausa_vpl VALUES ("EC3_22","022_3_22","ECC","3","22","22","Saboda haka na ga babu abin da ya fi kyau wa mutum fiye da yă more wahalar aikinsa, domin wannan ne rabonsa. Gama wa zai kawo shi yă ga abin da zai faru a bayansa? ");
INSERT INTO hausa_vpl VALUES ("EC4_1","022_4_1","ECC","4","1","1","Na sāke dubawa sai na ga zaluncin da ake yi a duniya. Na ga hawayen waɗanda ake zalunta kuma ba su da mai taimako; masu iko suna goyon bayan masu zalunci, ga shi ba su da mai taimako. ");
INSERT INTO hausa_vpl VALUES ("EC4_2","022_4_2","ECC","4","2","2","Sai na furta cewa matattu, waɗanda suka riga suka mutu, sun fi waɗanda suke a raye farin ciki, waɗanda har yanzu suke da rai. ");
INSERT INTO hausa_vpl VALUES ("EC4_3","022_4_3","ECC","4","3","3","Amma wanda ya fi su duka shi ne wanda bai riga ya kasance ba, wanda bai ga muguntar da ake yi a duniya ba. ");
INSERT INTO hausa_vpl VALUES ("EC4_4","022_4_4","ECC","4","4","4","Sai na gane cewa, duk wata fama da duk wata nasara sun samo asali daga kishin da mutum yake yi na maƙwabcinsa ne. Wannan ma ba shi da amfani, naushin iska ne kawai. ");
INSERT INTO hausa_vpl VALUES ("EC4_5","022_4_5","ECC","4","5","5","Wawa yakan kame hannuwansa yă kuma lalatar da kansa. ");
INSERT INTO hausa_vpl VALUES ("EC4_6","022_4_6","ECC","4","6","6","Gara tafin hannu guda cike da kwanciyar rai da tafin hannu biyu cike da tashin hankali da harbin iska kawai. ");
INSERT INTO hausa_vpl VALUES ("EC4_7","022_4_7","ECC","4","7","7","Na kuma ga wani abu marar amfani a duniya. ");
INSERT INTO hausa_vpl VALUES ("EC4_8","022_4_8","ECC","4","8","8","Akwai wani mutum shi kaɗai; bai shi da ɗa ko ɗan’uwa. Ba shi da hutu daga wahalarsa, duk da haka bai ƙoshi da dukiyarsa ba. Ya tambayi kansa, “Ma wane ne nake wannan wahala, kuma me ya sa nake hana kaina jin daɗi?” Wannan ma ba shi da amfani, harkar baƙin cikin ne kawai! ");
INSERT INTO hausa_vpl VALUES ("EC4_9","022_4_9","ECC","4","9","9","Biyu sun fi ɗaya, gama suna samun riba mai kyau na aikinsu. ");
INSERT INTO hausa_vpl VALUES ("EC4_10","022_4_10","ECC","4","10","10","In ɗaya ya fāɗi, abokinsa zai taimake shi yă tashi. Amma abin tausayi ne ga mutumin da ya fāɗi ba shi kuma da wanda zai taimake shi yă tashi! ");
INSERT INTO hausa_vpl VALUES ("EC4_11","022_4_11","ECC","4","11","11","In mutum biyu sun kwanta tare, za su ji ɗumin juna. Amma yaya mutum ɗaya zai ji ɗumi yana shi kaɗai? ");
INSERT INTO hausa_vpl VALUES ("EC4_12","022_4_12","ECC","4","12","12","Ana iya shan ƙarfin mutum ɗaya, mutum biyu za su iya kāre kansu. Igiya riɓi uku tana da wuya tsinkawa. ");
INSERT INTO hausa_vpl VALUES ("EC4_13","022_4_13","ECC","4","13","13","Gara saurayi wanda yake matalauci amma yake da hikima da sarkin da ya tsufa mai wauta, wanda ba ya karɓar shawara. ");
INSERT INTO hausa_vpl VALUES ("EC4_14","022_4_14","ECC","4","14","14","Yana yiwuwa saurayin yă fito daga kurkuku yă hau gadon sarauta, ko kuma dai an haife shi cikin talauci a ƙasarsa. ");
INSERT INTO hausa_vpl VALUES ("EC4_15","022_4_15","ECC","4","15","15","Na ga cewa dukan waɗanda suka rayu suka kuma yi tafiya a duniya sun bi saurayin, magājin sarkin. ");
INSERT INTO hausa_vpl VALUES ("EC4_16","022_4_16","ECC","4","16","16","Babu ƙarshe ga dukan mutanen da suka riga su. Amma waɗanda suka zo daga baya, ba su gamsu da magājin ba. Wannan ma ba shi da amfani, naushin iska ne kawai. ");
INSERT INTO hausa_vpl VALUES ("EC5_1","022_5_1","ECC","5","1","1","Ka lura da matakanka sa’ad da ka tafi gidan Allah. Ka je kusa don ka saurara a maimakon miƙa hadaya kamar wawaye, waɗanda ba su san sun yi laifi ba. ");
INSERT INTO hausa_vpl VALUES ("EC5_2","022_5_2","ECC","5","2","2","Kada ka yi subul da bakinka, kada zuciyarka tă yi garajen furta wani abu a gaban Allah. Allah yana sama kai kuma kana duniya, saboda haka, kada kalmominka su zama da yawa. ");
INSERT INTO hausa_vpl VALUES ("EC5_3","022_5_3","ECC","5","3","3","Kamar yadda son cika buri yakan zo sa’ad da kana da yawan damuwa, haka jawabin wawa yake sa’ad da yake yawan magana. ");
INSERT INTO hausa_vpl VALUES ("EC5_4","022_5_4","ECC","5","4","4","Sa’ad da ka yi alkawari ga Allah, kada ka ɓata lokaci wajen cika shi. Ba ya jin daɗin wawaye; ka cika alkawarinka. ");
INSERT INTO hausa_vpl VALUES ("EC5_5","022_5_5","ECC","5","5","5","Gara kada ka yi alkawari, da ka yi amma ba ka cika ba. ");
INSERT INTO hausa_vpl VALUES ("EC5_6","022_5_6","ECC","5","6","6","Kada ka bar bakinka ya kai ga yin zunubi. Kada kuma ka kai ƙara wurin ɗan saƙon haikali cewa, “Alkawarin da na yi kuskure ne.” Me ya sa Allah yake fushi a kan abin da ka faɗa har yă lalatar da aikin hannuwanka? ");
INSERT INTO hausa_vpl VALUES ("EC5_7","022_5_7","ECC","5","7","7","Yawan buri da yawan magana ba su da amfani. Saboda haka, ka ji tsoron Allah. ");
INSERT INTO hausa_vpl VALUES ("EC5_8","022_5_8","ECC","5","8","8","In ka ga ana zaluntar matalauta a wani yanki, ba a yin adalci, ana kuma tauye hakki, kada ka yi mamakin waɗannan abubuwa; domin akwai wani jami’in da yake bisa da wani, a bisansu biyu kuwa akwai wani. ");
INSERT INTO hausa_vpl VALUES ("EC5_9","022_5_9","ECC","5","9","9","Kowa yakan amfana da bunkasar amfanin ƙasa, sarki kansa yana samun riba daga gonaki. ");
INSERT INTO hausa_vpl VALUES ("EC5_10","022_5_10","ECC","5","10","10","Duk mai ƙaunar kuɗi ba ya samun isashe; duk ma ƙaunar dukiya ba ya ƙoshi da abin da yake samu. Wannan ma ba shi da amfani. ");
INSERT INTO hausa_vpl VALUES ("EC5_11","022_5_11","ECC","5","11","11","Kamar yadda kaya suke haɓaka, haka ma masu amfani da su. Kuma wane amfani ne suke ga mai shi in ba ciyar da idanunsa a kansu ba? ");
INSERT INTO hausa_vpl VALUES ("EC5_12","022_5_12","ECC","5","12","12","Barcin ma’aikaci daɗi gare shi, ko yă ci kaɗan ko da yawa, amma yalwar mai arziki ba ta barinsa yă iya yin barci. ");
INSERT INTO hausa_vpl VALUES ("EC5_13","022_5_13","ECC","5","13","13","Na ga wani mugun abu a duniya, arzikin da aka ajiye don yă cuce mai shi, ");
INSERT INTO hausa_vpl VALUES ("EC5_14","022_5_14","ECC","5","14","14","ko kuwa dukiyar da ta ɓace ta wata hasara, har ya zama sa’ad da ya haifi ɗa, babu abin da ya bar masa. ");
INSERT INTO hausa_vpl VALUES ("EC5_15","022_5_15","ECC","5","15","15","Tsirara mutum yakan fito daga cikin mahaifiyarsa, kuma kamar yadda ya fito, haka zai koma. Ba ya ɗaukan kome daga wahalarsa da zai riƙe a hannunsa. ");
INSERT INTO hausa_vpl VALUES ("EC5_16","022_5_16","ECC","5","16","16","Wannan ma mugun abu ne, Yadda mutum ya zo, haka zai koma, to, wace riba ce ya ci, da yake ya yi wahalar iska ce kawai? ");
INSERT INTO hausa_vpl VALUES ("EC5_17","022_5_17","ECC","5","17","17","Duk rayuwarsa ya ci abinci a cikin duhu, da ɓacin rai mai tsanani, da azaba, da fushi. ");
INSERT INTO hausa_vpl VALUES ("EC5_18","022_5_18","ECC","5","18","18","Sa’an nan na gane cewa abu mai kyau ne, daidai ne kuma mutum yă ci, yă sha, yă kuma ji daɗin aikin da ya yi a ’yan kwanakin da Allah ya ba shi, gama wannan shi aka ƙaddara wa mutum daga faman wahalarsa a duniya a cikin ’yan kwanakin da Allah ya ba shi a duniya, gama wannan shi ne rabonsa. ");
INSERT INTO hausa_vpl VALUES ("EC5_19","022_5_19","ECC","5","19","19","Ban da haka ma, sa’ad da Allah ya ba wa mutum dukiya da wadata, ya kuma ba shi zarafi yă ji daɗinsu, ya kuma amince da rabonsa, sai yă ji daɗin aikinsa, wannan kyauta ce ta Allah. ");
INSERT INTO hausa_vpl VALUES ("EC5_20","022_5_20","ECC","5","20","20","Da ƙyar yake tunani a kan kwanakin rayuwarsa, domin Allah ya yarje masa, yă zauna da farin ciki. ");
INSERT INTO hausa_vpl VALUES ("EC6_1","022_6_1","ECC","6","1","1","Na ga wani mugun abu a duniya, ya kuma nawaita wa mutane ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("EC6_2","022_6_2","ECC","6","2","2","Allah yakan ba mutum dukiya, da wadata da kuma girma, don kada yă rasa abin da ransa yake so, amma Allah bai ba shi zarafin more su ba, a maimakon haka ma sai baƙo ne yă more su. Wannan ba shi da amfani, mugun abu ne ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("EC6_3","022_6_3","ECC","6","3","3","Mutum zai iya kasance da ’ya’ya ɗari, yă kuma yi shekaru masu yawa; duk da haka kome daɗewarsa, in bai more wadatarsa ba, bai kuma sami kyakkyawar binnewa ba, na ce, gara wanda aka haife shi gawa. ");
INSERT INTO hausa_vpl VALUES ("EC6_4","022_6_4","ECC","6","4","4","Haihuwa ba tă amfane wanda aka haifa gawa ba, gama ya zo daga duhu ya koma duhu inda aka manta da shi. ");
INSERT INTO hausa_vpl VALUES ("EC6_5","022_6_5","ECC","6","5","5","Ko da yake bai ga hasken rana ba, bai kuma san kome ba, duk da haka ya dai huta, fiye da mutumin da bai more wa ransa ba, ");
INSERT INTO hausa_vpl VALUES ("EC6_6","022_6_6","ECC","6","6","6","ko da ya yi shekara dubu biyu amma bai more wadatarsa ba. Ba wuri ɗaya dukansu biyu za su tafi ba? ");
INSERT INTO hausa_vpl VALUES ("EC6_7","022_6_7","ECC","6","7","7","Dukan ƙoƙarin da mutum yake yi, yana yi ne domin bakinsa, duk da haka bai taɓa gamsar da abin da yake marmari. ");
INSERT INTO hausa_vpl VALUES ("EC6_8","022_6_8","ECC","6","8","8","Da me mai hikima ya fi wawa? Wace riba ce matalauci yakan samu don yă iya zama da mutane? ");
INSERT INTO hausa_vpl VALUES ("EC6_9","022_6_9","ECC","6","9","9","Gara abin da ido ya gani da kwaɗayin da bai sami biyan bukata ba. Wannan ma ba shi da amfani, naushin iska ne kawai. ");
INSERT INTO hausa_vpl VALUES ("EC6_10","022_6_10","ECC","6","10","10","Duk abin da ya kasance, to, yana da suna, kuma duk abin da mutum yake, an riga an sani. Ba mutumin da zai iya ƙarawa da wanda ya fi shi ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("EC6_11","022_6_11","ECC","6","11","11","Yadda yawan magana take haka ƙarancin amfaninta, yaya wannan zai amfane wani? ");
INSERT INTO hausa_vpl VALUES ("EC6_12","022_6_12","ECC","6","12","12","Gama wa ya san abin da ya fi dacewa ga mutum a ’yan kwanakinsa marasa amfani da sukan wuce kamar inuwa? Wa kuma zai iya faɗa masa abin da zai faru a duniya bayan ya rasu? ");
INSERT INTO hausa_vpl VALUES ("EC7_1","022_7_1","ECC","7","1","1","Suna mai kyau ya fi turare mai ƙanshi, kuma ranar mutuwa ta fi ranar haihuwa. ");
INSERT INTO hausa_vpl VALUES ("EC7_2","022_7_2","ECC","7","2","2","Gara a tafi gidan makoki da a je gidan biki, gama mutuwa ce ƙaddarar kowane mutum; ya kamata masu rai su lura da haka. ");
INSERT INTO hausa_vpl VALUES ("EC7_3","022_7_3","ECC","7","3","3","Baƙin ciki ya fi dariya, gama baƙin ciki yakan kawo gyara. ");
INSERT INTO hausa_vpl VALUES ("EC7_4","022_7_4","ECC","7","4","4","Zuciyar masu hikima tana a gidan makoki, amma zuciya wawaye tana a gidan shagali. ");
INSERT INTO hausa_vpl VALUES ("EC7_5","022_7_5","ECC","7","5","5","Gara ka saurari tsawatawar mai hikima da ka saurari waƙar wawaye. ");
INSERT INTO hausa_vpl VALUES ("EC7_6","022_7_6","ECC","7","6","6","Kamar ƙarar ƙayar da take karce gindin tukunya, haka dariyar wawaye take. Wannan ma ba shi da amfani. ");
INSERT INTO hausa_vpl VALUES ("EC7_7","022_7_7","ECC","7","7","7","Zalunci yakan mai da mutum mai hikima wawa, cin hanci kuma yakan lalace hali. ");
INSERT INTO hausa_vpl VALUES ("EC7_8","022_7_8","ECC","7","8","8","Ƙarshen abu ya fi farkonsa, haƙuri kuma ya fi girman kai. ");
INSERT INTO hausa_vpl VALUES ("EC7_9","022_7_9","ECC","7","9","9","Kada ranka yă yi saurin tashi, gama fushi yana zama a cinyar wawaye. ");
INSERT INTO hausa_vpl VALUES ("EC7_10","022_7_10","ECC","7","10","10","Kada ka ce, “Me ya sa kwanakin dā sun fi waɗannan?” Gama ba daidai ba ne a yi irin waɗannan tambayoyi. ");
INSERT INTO hausa_vpl VALUES ("EC7_11","022_7_11","ECC","7","11","11","Hikima, kamar gādo, abu mai kyau ne tana kuma da amfani ga waɗanda suka ga rana. ");
INSERT INTO hausa_vpl VALUES ("EC7_12","022_7_12","ECC","7","12","12","Hikima mafaka ce takan kāre mutum kamar yadda kuɗi suke yi. Kiyayewar da hikima takan yi wa mai ita ita ce amfanin ilimi. ");
INSERT INTO hausa_vpl VALUES ("EC7_13","022_7_13","ECC","7","13","13","Ku lura da abin da Allah ya yi. Wa zai iya miƙe abin da ya tanƙware? ");
INSERT INTO hausa_vpl VALUES ("EC7_14","022_7_14","ECC","7","14","14","Sa’ad da al’amura suke tafiya daidai, ka yi farin ciki, amma sa’ad da suka lalace, ka tuna, Allah ne ya yi wancan shi ne kuma ya yi wannan. Saboda haka, mutum ba zai san wani abu game da nan gabansa ba. ");
INSERT INTO hausa_vpl VALUES ("EC7_15","022_7_15","ECC","7","15","15","A cikin rayuwan nan ta rashin amfani nawa, na lura da waɗannan abubuwa biyu, mai adalci yana hallakawa cikin adalcinsa, mai mugunta kuma yana tsawon rai cikin muguntarsa. ");
INSERT INTO hausa_vpl VALUES ("EC7_16","022_7_16","ECC","7","16","16","Kada ka cika yin adalci, fiye da kima, kada kuma ka cika yin hikima, don me za ka hallaka kanka! ");
INSERT INTO hausa_vpl VALUES ("EC7_17","022_7_17","ECC","7","17","17","Kada ka cika yin mugunta, kada kuma ka cika yin wauta, don me za ka mutu kafin lokacinka? ");
INSERT INTO hausa_vpl VALUES ("EC7_18","022_7_18","ECC","7","18","18","Yana da kyau ka kama ɗaya ba tare da ka saki wancan ba. Mai tsoron Allah zai guji wuce gona da iri. ");
INSERT INTO hausa_vpl VALUES ("EC7_19","022_7_19","ECC","7","19","19","Hikima takan sa mutum guda mai hikima yă yi ƙarfi fiye da masu mulki goma a cikin birni. ");
INSERT INTO hausa_vpl VALUES ("EC7_20","022_7_20","ECC","7","20","20","Babu mai adalci a duniya wanda yake yin abin da yake daidai da bai taɓa yin zunubi ba. ");
INSERT INTO hausa_vpl VALUES ("EC7_21","022_7_21","ECC","7","21","21","Kada ka mai da hankali ga dukan abin da mutane suke faɗi, in ba haka ba wata rana za ka ji bayinka suna zaginka. ");
INSERT INTO hausa_vpl VALUES ("EC7_22","022_7_22","ECC","7","22","22","Gama kai kanka ka sani cewa sau da yawa ka zagi waɗansu. ");
INSERT INTO hausa_vpl VALUES ("EC7_23","022_7_23","ECC","7","23","23","Dukan waɗannan na gwada su ta wurin hikima na kuma ce, “Na ƙudurta in zama mai hikima,” amma abin ya fi ƙarfina. ");
INSERT INTO hausa_vpl VALUES ("EC7_24","022_7_24","ECC","7","24","24","Ko da me hikima take, Abin ya yi mana zurfi ƙwarai, yana da wuyar ganewa, wa zai iya gane shi? ");
INSERT INTO hausa_vpl VALUES ("EC7_25","022_7_25","ECC","7","25","25","Saboda haka na mai da hankalina ga fahimi, don in bincika in nemi hikima da yadda aka tsara abubuwa, in kuma fahimci wawancin mugunta da haukar wauta. ");
INSERT INTO hausa_vpl VALUES ("EC7_26","022_7_26","ECC","7","26","26","Sai na iske wani abin da ya fi mutuwa ɗaci mace wadda take tarko ne, wadda zuciyarta tarko ne wadda kuma hannuwanta sarƙa ne. Mutumin da ya gamshi Allah zai tsere mata, amma za tă kama mai zunubi. ");
INSERT INTO hausa_vpl VALUES ("EC7_27","022_7_27","ECC","7","27","27","Malami ya ce, “Duba, abin da na gane ke nan. “Na tara abu guda da wani, don in gane tsarin abubuwa, ");
INSERT INTO hausa_vpl VALUES ("EC7_28","022_7_28","ECC","7","28","28","yayinda nake cikin nema amma ban samu ba, sai na sami adali guda cikin dubu, amma ba mace mai adalci guda a cikinsu duka. ");
INSERT INTO hausa_vpl VALUES ("EC7_29","022_7_29","ECC","7","29","29","Wannan ne kaɗai abin da na gane. Allah ya yi mutum tsab amma sai muka rikitar da kanmu.” ");
INSERT INTO hausa_vpl VALUES ("EC8_1","022_8_1","ECC","8","1","1","Wa yake kama da mai hikima? Wa ya san bayanin abubuwa? Hikima takan haskaka fuskar mutum, ta kuma kawo sakin fuska. ");
INSERT INTO hausa_vpl VALUES ("EC8_2","022_8_2","ECC","8","2","2","Ka yi biyayya da umarnin sarki, na ce, saboda alkawarin da ka yi a gaban Allah. ");
INSERT INTO hausa_vpl VALUES ("EC8_3","022_8_3","ECC","8","3","3","Kada ka yi hanzarin tashi daga gaban sarki. Kada ka kāre abin da ba daidai ba, gama zai iya yin duk abin da ya ga dama. ");
INSERT INTO hausa_vpl VALUES ("EC8_4","022_8_4","ECC","8","4","4","Da yake maganar sarki ita ce mafificiya, wa zai iya ce masa, “Me kake yi?” ");
INSERT INTO hausa_vpl VALUES ("EC8_5","022_8_5","ECC","8","5","5","Duk wanda ya yi biyayya da umarninsa ba zai sami lahani ba, zuciya mai hikima kuma zai san lokacin da ya dace da kuma hanyoyin da suka fi. ");
INSERT INTO hausa_vpl VALUES ("EC8_6","022_8_6","ECC","8","6","6","Gama akwai lokaci da hanyoyin da suka dace da yin kowane abu, ko da yake wahalar mutum ta yi masa yawa. ");
INSERT INTO hausa_vpl VALUES ("EC8_7","022_8_7","ECC","8","7","7","Da yake ba wanda ya san nan gaba, wa zai iya faɗa masa abin da zai faru? ");
INSERT INTO hausa_vpl VALUES ("EC8_8","022_8_8","ECC","8","8","8","Ba wanda yake da iko a kan iska har da zai riƙe ta, saboda haka babu mai iko kan ranar mutuwarsa. Kamar yadda ba a sallamar mutum a lokacin yaƙi, haka ma mugunta ba za tă saki masu aikata ta ba. ");
INSERT INTO hausa_vpl VALUES ("EC8_9","022_8_9","ECC","8","9","9","Na ga dukan waɗannan, yayinda na lura da kowane abin da ake yi a duniya. Akwai lokacin da mutum yakan nauyaya wa waɗansu ba da sonsa ba. ");
INSERT INTO hausa_vpl VALUES ("EC8_10","022_8_10","ECC","8","10","10","Sa’an nan kuma, na ga an binne masu mugunta, waɗanda suke shiga da fita daga tsattsarkan wuri suke kuma samun yabo a birnin da suka yi wannan. Wannan ma ba shi da amfani. ");
INSERT INTO hausa_vpl VALUES ("EC8_11","022_8_11","ECC","8","11","11","In ba a hanzarta aka yanke hukunci a kan laifi ba, zukatan mutane sukan cika da ƙulle-ƙullen aikata abubuwan da ba daidai ba. ");
INSERT INTO hausa_vpl VALUES ("EC8_12","022_8_12","ECC","8","12","12","Ko da yake mugu ya aikata laifi ɗari ya kuma yi tsawon rai, na san cewa zai fi wa masu tsoron Allah kyau, waɗanda suke girmama Allah. ");
INSERT INTO hausa_vpl VALUES ("EC8_13","022_8_13","ECC","8","13","13","Duk da haka, domin masu mugunta ba su ji tsoron Allah ba, abubuwa ba za su yi musu kyau ba, ransu kamar inuwa yake ba zai yi tsawo ba. ");
INSERT INTO hausa_vpl VALUES ("EC8_14","022_8_14","ECC","8","14","14","Akwai kuma wani abu marar amfani da yake faruwa a duniya, masu adalci sukan sha hukuncin da ya dace da masu mugunta, masu mugunta kuma sukan karɓi sakayyar da ya cancanci masu adalci su samu. Na ce, wannan ma, ba shi da amfani. ");
INSERT INTO hausa_vpl VALUES ("EC8_15","022_8_15","ECC","8","15","15","Saboda haka abin da na ce, shi ne mutum yă ji daɗi, domin iyakar jin daɗinsa a wannan rai, shi ne yă ci, yă sha, yă ji wa kansa daɗi. Aƙalla yana iya yin wannan in ya yi aiki a kwanakin da Allah ya ba shi a wannan duniya. ");
INSERT INTO hausa_vpl VALUES ("EC8_16","022_8_16","ECC","8","16","16","Da na mai da hankalina don in sami hikima in kuma lura da wahalar mutum a duniya, ko da a ce idanunsa ba sa barci dare da rana, ");
INSERT INTO hausa_vpl VALUES ("EC8_17","022_8_17","ECC","8","17","17","sam, ba zai taɓa fahimci abin da Allah yake yi ba. Iyakar ƙoƙarin da ka yi duk ba za ka iya ganewa ba. Masu hikima suna iya cewa sun sani, amma kuwa ba su sani ba. ");
INSERT INTO hausa_vpl VALUES ("EC9_1","022_9_1","ECC","9","1","1","Sai na yi tunani a kan wannan na kuma gane cewa masu adalci da masu hikima da kuma abubuwan da suke yi suna a hannun Allah ne, amma ba wanda ya san ko ƙauna ko ƙiyayya ce take jiransa. ");
INSERT INTO hausa_vpl VALUES ("EC9_2","022_9_2","ECC","9","2","2","Dukansu makomarsu ɗaya ce, masu adalci da masu mugunta, masu kirki da marasa kirki, masu tsabta da marasa tsabta, masu miƙa hadaya da waɗanda ba sa yi. Kamar yadda yake ga mutumin kirki, haka yake ga mai zunubi. Kamar yadda yake ga masu yin rantsuwa, haka ma da masu tsoron yi. ");
INSERT INTO hausa_vpl VALUES ("EC9_3","022_9_3","ECC","9","3","3","Wannan ita ce muguntar da take faruwa a cikin dukan abubuwa a duniya. Ƙaddara ɗaya ce take a kan kowa. Amma zukatan mutane cike suke da mugunta, akwai kuma hauka a zukatansu yayinda suke a raye, bayan haka kuma sai su mutu. ");
INSERT INTO hausa_vpl VALUES ("EC9_4","022_9_4","ECC","9","4","4","Duk wanda yake da rai a wannan duniya ta rayayyu, yana sa zuciya, gara rayayyen kare da mataccen zaki! ");
INSERT INTO hausa_vpl VALUES ("EC9_5","022_9_5","ECC","9","5","5","Gama rayayyu sun san za su mutu, amma matattu ba su san kome ba; ba su da wata lada nan gaba an manta da su ke nan gaba ɗaya. ");
INSERT INTO hausa_vpl VALUES ("EC9_6","022_9_6","ECC","9","6","6","Ƙaunarsu, ƙiyayyarsu, da kuma kishinsu tuni sun ɓace; ba za su taɓa zama sashen wani abin da yake faruwa a duniya ba. ");
INSERT INTO hausa_vpl VALUES ("EC9_7","022_9_7","ECC","9","7","7","Yi tafiyarka, ka ci abincinka da farin ciki, ka sha ruwan inabinka da farin zuciya, gama abin da ka yi duka daidai ne a wurin Allah. ");
INSERT INTO hausa_vpl VALUES ("EC9_8","022_9_8","ECC","9","8","8","Kullum ka kasance cikin farin riguna, ka kuma shafe kanka da mai kullum, ");
INSERT INTO hausa_vpl VALUES ("EC9_9","022_9_9","ECC","9","9","9","Ka more rayuwa da matarka, wadda kake ƙauna, dukan kwanakin nan marasa amfani da Allah ya ba ka a duniya. Gama wannan ne rabonka a rayuwa da kuma na faman aikinka a duniya. ");
INSERT INTO hausa_vpl VALUES ("EC9_10","022_9_10","ECC","9","10","10","Duk abin da hannunka yake yi, ka yi shi da dukan ƙarfinka, gama a cikin kabari in da za ka, babu aiki ko shirye-shirye, ko sani, ko hikima. ");
INSERT INTO hausa_vpl VALUES ("EC9_11","022_9_11","ECC","9","11","11","Na kuma ga wani abu a duniya. Ba kullum maguji ne yake nasara a tsere ba, ba kullum jarumi ne yake yin nasara ba, ba kullum mai hikima ne da abinci ba ba kullum mai basira ne yake da wadata ba ba kullum gwani ne yake samun tagomashi ba; amma sa’a, da tsautsayi, sukan sami kowannensu. ");
INSERT INTO hausa_vpl VALUES ("EC9_12","022_9_12","ECC","9","12","12","Ban da haka ma, ba wanda ya san sa’ad da lokacin mutuwarsa zai yi. Kamar yadda akan kama kifi a muguwar raga, ko a kama tsuntsu a tarko, haka mugun lokaci yakan auko wa mutane, ba tsammani. ");
INSERT INTO hausa_vpl VALUES ("EC9_13","022_9_13","ECC","9","13","13","Na kuma ga wani misali game da hikima a duniya wanda ya burge ni sosai. ");
INSERT INTO hausa_vpl VALUES ("EC9_14","022_9_14","ECC","9","14","14","An yi wani ɗan ƙaramin birni mai mutane kaɗan a ciki. Sai wani babban sarki ya kawo masa yaƙi, ya kafa masa babban sansani. ");
INSERT INTO hausa_vpl VALUES ("EC9_15","022_9_15","ECC","9","15","15","A cikin birnin nan kuwa akwai wani mutum matalauci amma mai hikima, ya kuma ceci birnin ta wurin hikimarsa. Amma ba wanda ya tuna da matalaucin nan. ");
INSERT INTO hausa_vpl VALUES ("EC9_16","022_9_16","ECC","9","16","16","Sai na ce, “Hikima ta fi ƙarfe ƙarfi.” Amma aka rena hikimar matalaucin, ba a ma jin maganarsa. ");
INSERT INTO hausa_vpl VALUES ("EC9_17","022_9_17","ECC","9","17","17","Raɗar mai hikima da aka saurara cikin natsuwa ta fi ihun mai mulkin wawaye. ");
INSERT INTO hausa_vpl VALUES ("EC9_18","022_9_18","ECC","9","18","18","Hikima ta fi kayan yaƙi, amma mai zunubi ɗaya yakan rushe alheri mai yawa. ");
INSERT INTO hausa_vpl VALUES ("EC10_1","022_10_1","ECC","10","1","1","Kamar yadda matattun ƙudaje sukan ɓata ƙanshin turare, haka ’yar wauta takan ɓata hikima da daraja. ");
INSERT INTO hausa_vpl VALUES ("EC10_2","022_10_2","ECC","10","2","2","Zuciyar mai hikima takan karkata ga yin abin da yake daidai, amma zuciyar wawa takan karkata ga yin mugun abu. ");
INSERT INTO hausa_vpl VALUES ("EC10_3","022_10_3","ECC","10","3","3","Ko yayinda yake tafiya a kan hanya wawa yakan nuna cewa ba shi da hankali, yakan nuna wa kowa wawancinsa. ");
INSERT INTO hausa_vpl VALUES ("EC10_4","022_10_4","ECC","10","4","4","In hankalin mai mulki ya tashi game da kai, kada ka bar inda kake, gama kwantar da hankali yakan sa a yafe manyan laifofi. ");
INSERT INTO hausa_vpl VALUES ("EC10_5","022_10_5","ECC","10","5","5","Akwai muguntar da na gani a duniya, irin kuskuren da yake fitowa daga masu mulki. ");
INSERT INTO hausa_vpl VALUES ("EC10_6","022_10_6","ECC","10","6","6","Akan sa wawaye a manyan matsayi, yayinda masu arziki suna ƙarƙashi. ");
INSERT INTO hausa_vpl VALUES ("EC10_7","022_10_7","ECC","10","7","7","Na taɓa ganin bayi a kan dawakai, yayinda ’ya’yan sarki suna takawa a ƙasa kamar bayi. ");
INSERT INTO hausa_vpl VALUES ("EC10_8","022_10_8","ECC","10","8","8","Duk wanda ya haƙa rami shi ne zai fāɗa a ciki; duk wanda ya rushe katanga, shi maciji zai sara. ");
INSERT INTO hausa_vpl VALUES ("EC10_9","022_10_9","ECC","10","9","9","Duk mai farfasa duwatsu shi za su yi wa rauni; duk mai faskaren itace yana cikin hatsarinsu. ");
INSERT INTO hausa_vpl VALUES ("EC10_10","022_10_10","ECC","10","10","10","In gatari ya dakushe ba a kuma wasa shi ba, dole a yi amfani da ƙarfi da yawa, amma ƙwarewa yana kawo nasara. ");
INSERT INTO hausa_vpl VALUES ("EC10_11","022_10_11","ECC","10","11","11","In maciji ya sari mutum kafin a ba shi makarin gardi, ina amfanin maganin? ");
INSERT INTO hausa_vpl VALUES ("EC10_12","022_10_12","ECC","10","12","12","Kalmomi daga bakin mai hikima alheri ne, amma maganganun wawa za su hallaka shi. ");
INSERT INTO hausa_vpl VALUES ("EC10_13","022_10_13","ECC","10","13","13","Farkon maganarsa wauta ce, ƙarshenta kuma takan zama muguwar hauka, ");
INSERT INTO hausa_vpl VALUES ("EC10_14","022_10_14","ECC","10","14","14","wawa kuma yakan yi ta surutu. Ba wanda ya san abin da zai zo wa zai iya faɗa masa abin da zai faru bayan rasuwarsa? ");
INSERT INTO hausa_vpl VALUES ("EC10_15","022_10_15","ECC","10","15","15","Aikin wawa yakan gajiyar da shi, har bai san hanyar zuwa gari ba. ");
INSERT INTO hausa_vpl VALUES ("EC10_16","022_10_16","ECC","10","16","16","Kaitonki, ya ke ƙasa wadda sarkinki bawa ne wadda kuma hakimanta ke ta shagali tun da safe. ");
INSERT INTO hausa_vpl VALUES ("EC10_17","022_10_17","ECC","10","17","17","Mai albarka ce, ya ke ƙasa wadda sarkinki haifaffen gidan sarauta ne, wadda hakimanta suke samun abincinsu a daidai lokacin don samun ƙarfi ba don buguwa ba. ");
INSERT INTO hausa_vpl VALUES ("EC10_18","022_10_18","ECC","10","18","18","In mutum rago ne, sai tsaiko yă lotsa, in hannuwansa ba masa yin kome, ɗaki yakan yi yoyo. ");
INSERT INTO hausa_vpl VALUES ("EC10_19","022_10_19","ECC","10","19","19","Akan shirya abinci don jin daɗi, ruwan inabi kuwa don faranta zuciya, amma kuɗi ne amsar kome. ");
INSERT INTO hausa_vpl VALUES ("EC10_20","022_10_20","ECC","10","20","20","Kada ka zagi sarki ko da a cikin tunaninka ne, ko ka zagi mai arziki ko da a ɗakin kwananka ne, gama tsuntsun sararin sama zai iya ɗauki maganarka, tsuntsu mai fikafikai zai sanar da abin da ka ce. ");
INSERT INTO hausa_vpl VALUES ("EC11_1","022_11_1","ECC","11","1","1","Ka jefa burodinka a bisa ruwaye, gama bayan kwanaki masu yawa, za ka sāke samunsa. ");
INSERT INTO hausa_vpl VALUES ("EC11_2","022_11_2","ECC","11","2","2","Ka raba abin hannunka ga mutum bakwai, I, har ma takwas, gama ba ka san bala’in da zai auko wa ƙasar ba. ");
INSERT INTO hausa_vpl VALUES ("EC11_3","022_11_3","ECC","11","3","3","In gizagizai sun cika da ruwa, sukan zub da ruwan sama bisa duniya. Itace ya fāɗi, ko wajen kudu ne, ko wajen arewa, inda ya fāɗi a nan zai kwanta. ");
INSERT INTO hausa_vpl VALUES ("EC11_4","022_11_4","ECC","11","4","4","Duk mai la’akari da iska, ba zai yi shuka ba, mai la’akari da gizagizai kuma, ba zai yi girbi ba. ");
INSERT INTO hausa_vpl VALUES ("EC11_5","022_11_5","ECC","11","5","5","Kamar yadda ba ka san hanyar iska ba, ko yadda aka siffanta jiki a cikin mahaifiya, haka ba za ka fahimci aikin Allah Mahaliccin dukan abubuwa ba. ");
INSERT INTO hausa_vpl VALUES ("EC11_6","022_11_6","ECC","11","6","6","Ka shuka irinka da safe, da yamma kuma kada ka janye hannunka, gama ba ka san wanda zai yi albarka ba, ko wannan ko wancan, ko kuma duka biyunsu su yi albarka. ");
INSERT INTO hausa_vpl VALUES ("EC11_7","022_11_7","ECC","11","7","7","Haske da yana da kyau, abu mai kyau ne kuma idanu su dubi rana. ");
INSERT INTO hausa_vpl VALUES ("EC11_8","022_11_8","ECC","11","8","8","Kome tsawon rayuwar mutum, bari yă more su duka. Amma bari kuma yă tuna da kwanakin duhu, gama su ma za su yi yawa. Duk abin da zai faru ba shi da amfani. ");
INSERT INTO hausa_vpl VALUES ("EC11_9","022_11_9","ECC","11","9","9","Ka yi murna, kai matashi, a ƙuruciyarka, bari zuciyarka kuma tă yi farin ciki a kwanakin ƙuruciyarka. Ka bi shawarar zuciyarka da kuma duk abin da idanunka suka gani, amma ka sani fa, cikin dukan al’amuran nan Allah zai shari’anta ka. ");
INSERT INTO hausa_vpl VALUES ("EC11_10","022_11_10","ECC","11","10","10","Saboda haka, ka fid da tsoro daga zuciyarka ka kakkaɓe duk wani abin da ya dami rayuwarka, gama ƙuruciya da ƙarfi ba su da amfani. ");
INSERT INTO hausa_vpl VALUES ("EC12_1","022_12_1","ECC","12","1","1","Ka tuna da Mahaliccinka a kwanakin ƙuruciyarka, kafin lokacin wahala ta zo shekaru kuma su ƙarato sa’ad da za ka ce, “Ba na jin daɗinsu,” ");
INSERT INTO hausa_vpl VALUES ("EC12_2","022_12_2","ECC","12","2","2","kafin rana da haske wata da taurari su daina haske, gizagizai kuma su tattaru bayan da suka sheƙa ruwa; ");
INSERT INTO hausa_vpl VALUES ("EC12_3","022_12_3","ECC","12","3","3","sa’ad da masu tsaron gida suke rawar jiki, majiya ƙarfi kuma suka rasa ƙarfi, sa’ad da masu niƙa suka daina don ba su da yawa, idanun da suke duba ta taga suka duhunta; ");
INSERT INTO hausa_vpl VALUES ("EC12_4","022_12_4","ECC","12","4","4","sa’ad da aka rufe ƙofofin shiga tituna ƙarar niƙa kuma ya tsagaita; sa’ad da kukan tsuntsaye ta farkar da mutane, ba a kuwa jin waƙoƙinsu, ");
INSERT INTO hausa_vpl VALUES ("EC12_5","022_12_5","ECC","12","5","5","sa’ad da mutane suke jin tsoron tudu da kuma hatsarori a tituna; sa’ad da itacen almon ya toho, fāra kuma ya yi ta jan jikinsa da ƙyar, sha’awace-sha’awace sun kafe. Daga nan mutum ya tafi madawwamiyar gidansa ya bar masu makoki suna ta yi. ");
INSERT INTO hausa_vpl VALUES ("EC12_6","022_12_6","ECC","12","6","6","Ka tuna da shi, kafin igiyar azurfa ta katse, ko tasar zinariya ta fashe; kafin tulu yă ragargaje a maɓulɓula, ko guga ta tsinke a rijiya, ");
INSERT INTO hausa_vpl VALUES ("EC12_7","022_12_7","ECC","12","7","7","turɓaya ta koma ƙasar da ta fito, rai kuma yă koma ga Allah wanda ya ba da shi. ");
INSERT INTO hausa_vpl VALUES ("EC12_8","022_12_8","ECC","12","8","8","“Ba amfani! Ba amfani!” In ji Malami, “Gaba ɗaya ba amfani!” ");
INSERT INTO hausa_vpl VALUES ("EC12_9","022_12_9","ECC","12","9","9","Ba kawai Malami ya kasance mai hikima ba, amma kuma ya koyar da mutane. Ya yi tunani ya kuma yi binciken da ya tsara karin magana masu yawa. ");
INSERT INTO hausa_vpl VALUES ("EC12_10","022_12_10","ECC","12","10","10","Malami ya yi bincike don yă sami kalmomin da suka dace, kuma abin da ya rubuta daidai ne da kuma gaskiya. ");
INSERT INTO hausa_vpl VALUES ("EC12_11","022_12_11","ECC","12","11","11","Kalmomin masu hikima kamar tsinken tsokanar dabba ne, tarin maganganunsu kuma kamar ƙusoshi ne da aka kafa daram, da aka ba wa Makiyayi guda. ");
INSERT INTO hausa_vpl VALUES ("EC12_12","022_12_12","ECC","12","12","12","Ka yi hankali ɗana, game da duk wani ƙari a kan waɗannan. Wallafa littattafai ba shi da iyaka, kuma yawan karatu yakan gajiyar da jiki. ");
INSERT INTO hausa_vpl VALUES ("EC12_13","022_12_13","ECC","12","13","13","Yanzu an ji kome; ga ƙarshen magana. Ka ji tsoron Allah ka kuma kiyaye umarnansa, gama wannan shi ne dukan hakkin mutum. ");
INSERT INTO hausa_vpl VALUES ("EC12_14","022_12_14","ECC","12","14","14","Gama Allah zai shari’anta kowane irin aiki, har da waɗanda aka yi a ɓoye, ko nagari ne, ko mugu.");
INSERT INTO hausa_vpl VALUES ("SS1_1","023_1_1","SNG","1","1","1","Waƙar Waƙoƙin Solomon. ");
INSERT INTO hausa_vpl VALUES ("SS1_2","023_1_2","SNG","1","2","2","Bari yă sumbace ni da sumbar bakinsa, gama ƙaunarka ta fi ruwan inabi zaƙi. ");
INSERT INTO hausa_vpl VALUES ("SS1_3","023_1_3","SNG","1","3","3","Ƙanshin turarenka mai daɗi ne; sunanka kuwa kamar turaren da aka tsiyaye ne. Shi ya sa mata suke ƙaunarka! ");
INSERT INTO hausa_vpl VALUES ("SS1_4","023_1_4","SNG","1","4","4","Ka ɗauke ni mu gudu, mu yi sauri! Bari sarki yă kai ni gidansa. Ƙawaye Muna farin ciki muna kuma murna tare da kai, za mu yabi ƙaunarka fiye da ruwan inabi. Ƙaunatacciya Daidai ne su girmama ka! ");
INSERT INTO hausa_vpl VALUES ("SS1_5","023_1_5","SNG","1","5","5","Ni baƙa ce, duk da haka kyakkyawa. Ya ku ’yan matan Urushalima, ni baƙa ce kamar tentunan Kedar, kamar labulen tentin Solomon. ");
INSERT INTO hausa_vpl VALUES ("SS1_6","023_1_6","SNG","1","6","6","Kada ku harare ni domin ni baƙa ce, gama rana ta dafa ni na yi baƙa. ’Ya’yan mahaifiyata maza sun yi fushi da ni suka sa ni aiki a gonakin inabi; na ƙyale gonar inabi na kaina. ");
INSERT INTO hausa_vpl VALUES ("SS1_7","023_1_7","SNG","1","7","7","Faɗa mini, kai da nake ƙauna, ina kake kiwon garkenka kuma ina kake kai tumakinka su huta da tsakar rana. Me ya sa zan kasance kamar macen da aka lulluɓe kusa da garkunan abokanka? ");
INSERT INTO hausa_vpl VALUES ("SS1_8","023_1_8","SNG","1","8","8","Ke mafiya kyau a cikin mata, in ba ki sani ba, to, ki dai bi labin da tumaki suke bi ki yi kiwon ’yan awakinki kusa da tentunan makiyaya. ");
INSERT INTO hausa_vpl VALUES ("SS1_9","023_1_9","SNG","1","9","9","Ina kwatanta ke ƙaunatacciyata, da goɗiya mai jan keken yaƙin kayan Fir’auna. ");
INSERT INTO hausa_vpl VALUES ("SS1_10","023_1_10","SNG","1","10","10","’Yan kunne sun ƙara wa kumatunki kyau, wuyanki yana da jerin kayan wuya masu daraja. ");
INSERT INTO hausa_vpl VALUES ("SS1_11","023_1_11","SNG","1","11","11","Za mu yi ’yan kunnenki na zinariya, da adon azurfa. ");
INSERT INTO hausa_vpl VALUES ("SS1_12","023_1_12","SNG","1","12","12","Yayinda sarki yake a teburinsa, turarena ya bazu da ƙanshi. ");
INSERT INTO hausa_vpl VALUES ("SS1_13","023_1_13","SNG","1","13","13","Ƙaunataccena yana kamar ƙanshin mur a gare ni, kwance a tsakanin ƙirjina. ");
INSERT INTO hausa_vpl VALUES ("SS1_14","023_1_14","SNG","1","14","14","Ƙaunataccena kamar tarin furanni jeji ne gare ni daga gonakin inabin En Gedi. ");
INSERT INTO hausa_vpl VALUES ("SS1_15","023_1_15","SNG","1","15","15","Ke kyakkyawa ce, ƙaunatacciyata! Kai, ke kyakkyawa ce! Idanunki kamar na kurciya ne. ");
INSERT INTO hausa_vpl VALUES ("SS1_16","023_1_16","SNG","1","16","16","Kai kyakkyawa ne, ƙaunataccena! Kai, kana ɗaukan hankali! Gadonmu koriyar ciyawa ce. ");
INSERT INTO hausa_vpl VALUES ("SS1_17","023_1_17","SNG","1","17","17","Al’ul su ne ginshiƙan gidanmu; fir su ne katakan rufin gidanmu. ");
INSERT INTO hausa_vpl VALUES ("SS2_1","023_2_1","SNG","2","1","1","Ni furen bi-rana ne na Sharon, furen bi-rana na kwari. ");
INSERT INTO hausa_vpl VALUES ("SS2_2","023_2_2","SNG","2","2","2","Kamar furen bi-rana a cikin ƙayayyuwa haka ƙaunatacciyata take a cikin ’yan mata. ");
INSERT INTO hausa_vpl VALUES ("SS2_3","023_2_3","SNG","2","3","3","Kamar itacen gawasa a cikin itatuwan jeji haka ƙaunataccena yake a cikin samari. Ina farin ciki in zauna a inuwarsa, ’ya’yan itacensa suna da daɗin ɗanɗanon da nake so ");
INSERT INTO hausa_vpl VALUES ("SS2_4","023_2_4","SNG","2","4","4","Ya kai ni babban zauren da ake liyafa, ƙauna ita ce tutarsa a gare ni. ");
INSERT INTO hausa_vpl VALUES ("SS2_5","023_2_5","SNG","2","5","5","Ka ƙarfafa ni da zabibi ka wartsake ni da gawasa, gama ina suma don ƙauna. ");
INSERT INTO hausa_vpl VALUES ("SS2_6","023_2_6","SNG","2","6","6","Hannunsa na hagu yana a ƙarƙashin kaina, hannunsa na dama kuma ya rungume ni. ");
INSERT INTO hausa_vpl VALUES ("SS2_7","023_2_7","SNG","2","7","7","’Yan matan Urushalima, ku yi mini alkawari da bareyi da ƙishimai na jeji. Ba za ku tā da ko ku farka ƙauna ba sai haka ya zama lalle. ");
INSERT INTO hausa_vpl VALUES ("SS2_8","023_2_8","SNG","2","8","8","Saurara! Ƙaunataccena! Duba! Ga shi ya iso, yana tsalle a duwatsu, yana rawa a bisa tuddai. ");
INSERT INTO hausa_vpl VALUES ("SS2_9","023_2_9","SNG","2","9","9","Ƙaunataccena yana kama da barewa ko sagarin ƙishimi Duba! Ga shi can tsaye a bayan katangarmu, yana leƙe ta tagogi, yana kallo ta cikin asabari. ");
INSERT INTO hausa_vpl VALUES ("SS2_10","023_2_10","SNG","2","10","10","Ƙaunataccena ya yi magana ya ce mini, “Tashi, ƙaunatacciyata, kyakkyawata, ki zo tare da ni. ");
INSERT INTO hausa_vpl VALUES ("SS2_11","023_2_11","SNG","2","11","11","Duba! Damina ta wuce; ruwan sama ya ɗauke ya kuma ƙare. ");
INSERT INTO hausa_vpl VALUES ("SS2_12","023_2_12","SNG","2","12","12","Furanni sun hudo a duniya; lokaci yin waƙa ya zo, ana jin kukan kurciyoyi ko’ina a ƙasarmu. ");
INSERT INTO hausa_vpl VALUES ("SS2_13","023_2_13","SNG","2","13","13","Itacen ɓaure ya fid da ’ya’yansa da sauri; tohon inabi suna ba da ƙanshinsu. Tashi, zo, ƙaunatacciyata; kyakkyawata, zo tare da ni.” ");
INSERT INTO hausa_vpl VALUES ("SS2_14","023_2_14","SNG","2","14","14","Kurciyata a kogon dutse, a wuraren ɓuya a gefen dutse, nuna mini fuskarki, bari in ji muryarki; gama muryarki da daɗi take, fuskarki kuma kyakkyawa ce. ");
INSERT INTO hausa_vpl VALUES ("SS2_15","023_2_15","SNG","2","15","15","Kama mana ɓeraye, ƙananan ɓerayen da suke lalatar da gonakin inabi, gonakin inabinmu da suke cikin yin fure. ");
INSERT INTO hausa_vpl VALUES ("SS2_16","023_2_16","SNG","2","16","16","Ƙaunataccena nawa ne ni kuma tasa ce; yana kiwon garkensa a cikin furannin bi-rana. ");
INSERT INTO hausa_vpl VALUES ("SS2_17","023_2_17","SNG","2","17","17","Sai gari ya waye inuwa kuma ta watse, ka juye, ƙaunataccena, ka zama kamar barewa ko kamar sagarin ƙishimi a kan tuddai masu ciyawa. ");
INSERT INTO hausa_vpl VALUES ("SS3_1","023_3_1","SNG","3","1","1","Dare farai a kan gadona na nemi wanda zuciyata take ƙauna; na neme shi amma ban same shi ba. ");
INSERT INTO hausa_vpl VALUES ("SS3_2","023_3_2","SNG","3","2","2","Zan tashi yanzu in zagaya gari, in ratsa titunansa da dandalinsa; zan nemi wanda zuciyata take ƙauna. Saboda haka na neme shi, amma ban same shi ba. ");
INSERT INTO hausa_vpl VALUES ("SS3_3","023_3_3","SNG","3","3","3","Masu tsaro suka gamu da ni yayinda suke kai kawo a cikin birni, sai na ce, “Kun ga mini wanda zuciyata take ƙauna?” ");
INSERT INTO hausa_vpl VALUES ("SS3_4","023_3_4","SNG","3","4","4","Rabuwata da su ke nan sai na sami wanda zuciyata take ƙauna. Na riƙe shi, ban yarda yă tafi ba sai da na kawo shi gidan mahaifiyata, zuwa ɗakin wadda ta yi cikina. ");
INSERT INTO hausa_vpl VALUES ("SS3_5","023_3_5","SNG","3","5","5","’Yan matan Urushalima, ku yi mini alkawari da bareyi da ƙishimai na jeji. Ba za ku tā da ko ku farka ƙauna ba sai haka ya zama lalle. ");
INSERT INTO hausa_vpl VALUES ("SS3_6","023_3_6","SNG","3","6","6","Wane ne wannan mai zuwa daga hamada kamar tunnuƙewar hayaƙi, cike da ƙanshin turaren mur da lubban da aka yi da kayan yajin ’yan kasuwa? ");
INSERT INTO hausa_vpl VALUES ("SS3_7","023_3_7","SNG","3","7","7","Duba! Abin ɗaukar Solomon ne, jarumawa sittin suke rakiya, zaɓaɓɓun sojojin Isra’ila, ");
INSERT INTO hausa_vpl VALUES ("SS3_8","023_3_8","SNG","3","8","8","dukansu suna saye da takobi dukansu ƙwararru ne a yaƙi, kowanne da takobinsa a rataye a gefensa, a shirye don abubuwan bantsoro na dare. ");
INSERT INTO hausa_vpl VALUES ("SS3_9","023_3_9","SNG","3","9","9","Sarki Solomon ya yi wa kansa abin ɗauka; ya yi shi da katako daga Lebanon. ");
INSERT INTO hausa_vpl VALUES ("SS3_10","023_3_10","SNG","3","10","10","An yi sandunansa da azurfa, aka yi ƙasarsa da zinariya. An lulluɓe wurin zaman da zanen shunayya, ’yan matan Urushalima sun yi mata irin yayen da ake yi na ƙauna. ");
INSERT INTO hausa_vpl VALUES ("SS3_11","023_3_11","SNG","3","11","11","Fito, ku ’yan matan Sihiyona, ku ga Sarki Solomon yana saye da rawani, rawanin da mahaifiyarsa ta naɗa masa, a ranar aurensa, a ranar da zuciyarsa ta yi farin ciki. ");
INSERT INTO hausa_vpl VALUES ("SS4_1","023_4_1","SNG","4","1","1","Ke kyakkyawa ce, ƙaunatacciyata! Kai, ke kyakkyawa ce! Idanunki sun yi kamar na kurciya a cikin lulluɓinki. Gashinki ya yi kamar garken awaki da suke gangarawa daga Dutsen Gileyad. ");
INSERT INTO hausa_vpl VALUES ("SS4_2","023_4_2","SNG","4","2","2","Haƙoranki sun yi kamar garken tumakin da ba a daɗe da yin musu sausaya ba, da suke haurawa daga inda aka yi musu wanka. Kowanne yana tare da ɗan’uwansa; babu waninsu da yake shi kaɗai. ");
INSERT INTO hausa_vpl VALUES ("SS4_3","023_4_3","SNG","4","3","3","Leɓunanki kamar zaren jan garura bakinki yana da kyau. Kumatunki sun yi kamar rumman da aka tsaga biyu a cikin lulluɓinki. ");
INSERT INTO hausa_vpl VALUES ("SS4_4","023_4_4","SNG","4","4","4","Wuyanki ya yi kamar hasumiyar Dawuda, da aka gina da daraja; a kansa an rataye garkuwoyi dubu, dukansu garkuwoyin jarumawa ne. ");
INSERT INTO hausa_vpl VALUES ("SS4_5","023_4_5","SNG","4","5","5","Nonanki biyu sun yi kamar bareyi biyu, kamar tagwayen barewa da suke kiwo a cikin furen bi-rana. ");
INSERT INTO hausa_vpl VALUES ("SS4_6","023_4_6","SNG","4","6","6","Sai gari ya waye inuwa kuma ta watse, zan je dutsen mur da kuma tudun turare. ");
INSERT INTO hausa_vpl VALUES ("SS4_7","023_4_7","SNG","4","7","7","Duk, ke kyakkyawa ce, ƙaunatacciyata; babu wani lahani a cikinki. ");
INSERT INTO hausa_vpl VALUES ("SS4_8","023_4_8","SNG","4","8","8","Ki tare da ni daga Lebanon, amaryata, zo tare da ni daga Lebanon. Ki gangara daga ƙwanƙolin Amana, daga ƙwanƙolin Senir, ƙwanƙolin Hermon, daga ramin zaki da kuma dutsen da damisoshi suke zama. ");
INSERT INTO hausa_vpl VALUES ("SS4_9","023_4_9","SNG","4","9","9","Kin saci zuciyata, ’yar’uwata, amaryata; kin saci zuciyata da hararar idanunki, da dutse mai daraja guda na abin wuyanki. ");
INSERT INTO hausa_vpl VALUES ("SS4_10","023_4_10","SNG","4","10","10","Ƙaunarki abar farin ciki ne, ’yar’uwata, amaryata! Ƙaunarki ta fi ruwan inabi gamsuwa, ƙanshin turarenki kuma ya fi duk wani kayan yaji! ");
INSERT INTO hausa_vpl VALUES ("SS4_11","023_4_11","SNG","4","11","11","Leɓunanki suna zub da zaƙi kamar kakin zuma, amaryata; madara da zuma suna a ƙarƙashin harshenki. Ƙanshin rigunanki ya yi kamar na Lebanon. ");
INSERT INTO hausa_vpl VALUES ("SS4_12","023_4_12","SNG","4","12","12","Ke lambu ne da aka kulle, ’yar’uwata, amaryata; ke maɓulɓula ce da aka kewaye, maɓulɓular da aka rufe. ");
INSERT INTO hausa_vpl VALUES ("SS4_13","023_4_13","SNG","4","13","13","Shuke-shukenki gonar rumman ne da ’ya’yan itace masu kyau na lalle da nardi, ");
INSERT INTO hausa_vpl VALUES ("SS4_14","023_4_14","SNG","4","14","14","nardi, da asfaran, kalamus, da kirfa, da kowane irin itacen turare, da mur da aloyes da kuma dukan kayan yaji masu kyau. ");
INSERT INTO hausa_vpl VALUES ("SS4_15","023_4_15","SNG","4","15","15","Ke lambun maɓulɓula ne, rijiya mai ruwan da yake gudu yana gangarawa daga Lebanon. ");
INSERT INTO hausa_vpl VALUES ("SS4_16","023_4_16","SNG","4","16","16","Farka, iskar arewa, ki kuma zo, iskar kudu! Hura a kan lambuna, don ƙanshinsa yă bazu har waje. Bari ƙaunataccena yă zo cikin lambunsa yă ɗanɗana ’ya’yan itacensa mafi kyau. ");
INSERT INTO hausa_vpl VALUES ("SS5_1","023_5_1","SNG","5","1","1","Na zo lambuna, ’yar’uwata, amaryata; na tattara mur nawa da kayan yajina. Na sha zumana da kuma kakinsa na sha ruwan inabina da kuma madarana. Ƙawaye Ku ci, ku kuma sha, ya ku ƙawaye; ku sha ku ƙoshi, ya ƙaunatattu. ");
INSERT INTO hausa_vpl VALUES ("SS5_2","023_5_2","SNG","5","2","2","Na yi barci amma zuciyata tana a farke. Ku saurara! Ƙaunataccena yana ƙwanƙwasa ƙofa. “Buɗe mini, ’yar’uwata, ƙaunatacciyata, kurciyata, marar laifina. Kaina ya jiƙe da raɓa, gashina ya yi danshin ɗiɗɗigar dare.” ");
INSERT INTO hausa_vpl VALUES ("SS5_3","023_5_3","SNG","5","3","3","Na tuɓe rigata, sai in sāke sa ta kuma? Na wanke ƙafafuna, sai in sāke ɓata su? ");
INSERT INTO hausa_vpl VALUES ("SS5_4","023_5_4","SNG","5","4","4","Ƙaunataccena ya turo hannunsa ta cikin ramin ƙofar; zuciyata ta fara juyayi a kansa. ");
INSERT INTO hausa_vpl VALUES ("SS5_5","023_5_5","SNG","5","5","5","Na tashi don in buɗe wa ƙaunataccena, sai hannuna ya jiƙe sharkaf da mur, yatsotsina suna ɗiga da mur, a hannuwan ƙofar. ");
INSERT INTO hausa_vpl VALUES ("SS5_6","023_5_6","SNG","5","6","6","Na buɗe wa ƙaunataccena ƙofa, amma ƙaunataccena ba ya nan, ya riga ya tafi. Zuciyata ta damu da tafiyarsa. Na neme shi amma ban same shi ba. Na yi ta kiransa amma bai amsa ba. ");
INSERT INTO hausa_vpl VALUES ("SS5_7","023_5_7","SNG","5","7","7","Masu gadi suka gamu da ni yayinda suke kai kawo a cikin birni. Suka yi mini dūka, suka yi mini rauni; suka ƙwace gyalena waɗannan masu gadin katanga! ");
INSERT INTO hausa_vpl VALUES ("SS5_8","023_5_8","SNG","5","8","8","’Yan matan Urushalima, ina roƙonku, in kun sami ƙaunataccena me za ku ce masa? Ku ce masa na suma saboda ƙauna. ");
INSERT INTO hausa_vpl VALUES ("SS5_9","023_5_9","SNG","5","9","9","Mafiya kyau a cikin mata me ya sa ƙaunataccenki ya fi sauran? Don me kike roƙonmu mu faɗa masa yadda kike ji? ");
INSERT INTO hausa_vpl VALUES ("SS5_10","023_5_10","SNG","5","10","10","Ƙaunataccena kyakkyawa ne ƙaƙƙarfa kuma, da ƙyar a sami irinsa ɗaya a cikin dubu goma. ");
INSERT INTO hausa_vpl VALUES ("SS5_11","023_5_11","SNG","5","11","11","Kansa zinariya ce zalla; gashinsa dogaye ne baƙi wuluk kamar hankaka. ");
INSERT INTO hausa_vpl VALUES ("SS5_12","023_5_12","SNG","5","12","12","Idanunsa sun yi kamar na kurciyoyin da suke kusa da ruwan rafi, da aka wanke da madara aka kuma kafa kamar kayan ado masu daraja. ");
INSERT INTO hausa_vpl VALUES ("SS5_13","023_5_13","SNG","5","13","13","Kumatunsa kamar lambun kayan yaji suna ba da turare. Leɓunansa sun yi kamar furen bi-rana suna ɗiga da mur. ");
INSERT INTO hausa_vpl VALUES ("SS5_14","023_5_14","SNG","5","14","14","Hannuwansa kamar sandunan zinariyar da aka sa musu duwatsu masu daraja. Jikinsa ya yi kamar gogaggen hauren giwan da aka yi masa ado da duwatsun saffaya. ");
INSERT INTO hausa_vpl VALUES ("SS5_15","023_5_15","SNG","5","15","15","Ƙafafunsa sun yi kamar ginshiƙan dutsen alabastar da aka kafa su a cikin rammukar zinariya. Kamanninsa ya yi kamar Lebanon, mafi kyau kamar itacen al’ul nasa. ");
INSERT INTO hausa_vpl VALUES ("SS5_16","023_5_16","SNG","5","16","16","Bakinsa zaƙi ne kansa; komensa yana da kyau. Haka ƙaunataccena, abokina, yake ’yan matan Urushalima. ");
INSERT INTO hausa_vpl VALUES ("SS6_1","023_6_1","SNG","6","1","1","Ina ƙaunataccenki ya tafi, yake mafiya kyau cikin mata? Wace hanya ce ƙaunataccenki ya bi, don mu taimake ki nemansa. ");
INSERT INTO hausa_vpl VALUES ("SS6_2","023_6_2","SNG","6","2","2","Ƙaunataccena ya gangara zuwa lambunsa, zuwa inda fangulan kayan yaji suke, don yă yi kiwo a cikin lambun don kuma yă tattara furen bi-rana. ");
INSERT INTO hausa_vpl VALUES ("SS6_3","023_6_3","SNG","6","3","3","Ni na ƙaunataccena ce, ƙaunataccena kuma nawa ne; yana kiwo a cikin furen bi-rana. ");
INSERT INTO hausa_vpl VALUES ("SS6_4","023_6_4","SNG","6","4","4","Ke kyakkyawa ce, ƙaunatacciyata, kamar Tirza, kyakkyawa kuma kamar Urushalima, mai daraja kamar mayaƙa da tutoti. ");
INSERT INTO hausa_vpl VALUES ("SS6_5","023_6_5","SNG","6","5","5","Ki kau da idanu daga gare ni; gama suna rinjayata. Gashinki yana kama da garken awakin da suke gangarawa daga Gileyad. ");
INSERT INTO hausa_vpl VALUES ("SS6_6","023_6_6","SNG","6","6","6","Haƙoranki suna kama da garken tumakin da suke haurawa daga inda aka yi musu wanka. Kowanne yana tare da ɗan’uwansa; babu waninsu da yake shi kaɗai. ");
INSERT INTO hausa_vpl VALUES ("SS6_7","023_6_7","SNG","6","7","7","Kumatunki sun yi kamar rumman da aka tsaga biyu a cikin lulluɓinki. ");
INSERT INTO hausa_vpl VALUES ("SS6_8","023_6_8","SNG","6","8","8","Sarauniyoyi sittin za su iya kasance a can, da ƙwarƙwarai tamanin da kuma budurwai da suka wuce ƙirge; ");
INSERT INTO hausa_vpl VALUES ("SS6_9","023_6_9","SNG","6","9","9","amma kurciyata, cikakkiyata, dabam take, tilo kuwa ga mahaifiyarta, ’yar lele ga wadda ta haife ta. ’Yan mata sun gan ta suka ce da ita mai albarka; sarauniyoyi da ƙwarƙwarai sun yabe ta. ");
INSERT INTO hausa_vpl VALUES ("SS6_10","023_6_10","SNG","6","10","10","Wace ce wannan da ta bayyana sai ka ce ketowar alfijir? Kyakkyawa kamar wata, mai haske kamar rana, mai daraja kamar taurari a jere? ");
INSERT INTO hausa_vpl VALUES ("SS6_11","023_6_11","SNG","6","11","11","Na gangara zuwa cikin itatuwan almon don in ga ƙananan itatuwan da suke girma a kwari, don in ga ko inabi sun yi ’ya’ya ko rumman suna fid da furanni. ");
INSERT INTO hausa_vpl VALUES ("SS6_12","023_6_12","SNG","6","12","12","Kafin in san wani abu, sha’awarta ta sa ni a cikin keken yaƙin sarkin mutanena. ");
INSERT INTO hausa_vpl VALUES ("SS6_13","023_6_13","SNG","6","13","13","Ki dawo, ki dawo, ya Bashulammiya; ki dawo, ki dawo, don mu dube ki! Ƙaunatacce Don me kuke duban Bashulammiya sai ka ce rawar Mahanayim? ");
INSERT INTO hausa_vpl VALUES ("SS7_1","023_7_1","SNG","7","1","1","Ƙafafunki a cikin takalma kyakkyawa ne, Ya diyar sarki! Tsarin ƙafafunki sun yi kamar kayan ado masu daraja, aikin hannun gwanin sassaƙa. ");
INSERT INTO hausa_vpl VALUES ("SS7_2","023_7_2","SNG","7","2","2","Cibinki kamar kwaf ne da bai taɓa rasa gaurayayyen ruwan inabi ba. Kwankwasonki ya yi kamar damin alkama wanda furen bi-rana ya kewaye. ");
INSERT INTO hausa_vpl VALUES ("SS7_3","023_7_3","SNG","7","3","3","Nonanki sun yi kamar bareyi biyu, tagwayen barewa. ");
INSERT INTO hausa_vpl VALUES ("SS7_4","023_7_4","SNG","7","4","4","Wuyanki ya yi kamar hasumiyar hauren giwa. Idanunki sun yi kamar tafkin Heshbon kusa da ƙofar Bat Rabbim. Hancinki ya yi kamar hasumiyar Lebanon wadda take duban Damaskus. ");
INSERT INTO hausa_vpl VALUES ("SS7_5","023_7_5","SNG","7","5","5","Kanki ya yi miki rawani kamar Dutsen Karmel. Gashinki ya yi kamar shunayya; yakan ɗauke hankalin sarki. ");
INSERT INTO hausa_vpl VALUES ("SS7_6","023_7_6","SNG","7","6","6","Kai! Ke kyakkyawa ce kuma kina sa ni jin daɗi, Ya ƙaunatacciya, da farin cikin da kike kawo! ");
INSERT INTO hausa_vpl VALUES ("SS7_7","023_7_7","SNG","7","7","7","Tsayinki ya yi kamar itacen dabino, kuma nonanki sun yi kamar ’ya’yan itace. ");
INSERT INTO hausa_vpl VALUES ("SS7_8","023_7_8","SNG","7","8","8","Na ce, “Zan hau itacen dabino; zan kama ’ya’yansa.” Bari nonanki su zama kamar nonna kuringa, ƙanshin numfashinki ya yi kamar gawasa, ");
INSERT INTO hausa_vpl VALUES ("SS7_9","023_7_9","SNG","7","9","9","kuma bakinki ya yi kamar ruwan inabi mafi kyau. Ƙaunatacciya Bari ruwan inabi yă wuce kai tsaye zuwa ga ƙaunataccena, yana gudu a hankali a leɓuna da kuma haƙora. ");
INSERT INTO hausa_vpl VALUES ("SS7_10","023_7_10","SNG","7","10","10","Ni ta ƙaunataccena ce, kuma sha’awarsa domina ne. ");
INSERT INTO hausa_vpl VALUES ("SS7_11","023_7_11","SNG","7","11","11","Ka zo, ƙaunataccena, bari mu je bayan gari, bari mu kwana a ƙauye. ");
INSERT INTO hausa_vpl VALUES ("SS7_12","023_7_12","SNG","7","12","12","Bari mu tafi gonar inabi da sassafe don mu ga ko kuringar ta yi ’ya’ya, ko furanninsu sun buɗe, ko rumman sun yi fure, a can zan nuna maka ƙaunata. ");
INSERT INTO hausa_vpl VALUES ("SS7_13","023_7_13","SNG","7","13","13","Manta-uwa sun ba da ƙanshinsu, a bakin ƙofa kuwa akwai kowane abinci mai daɗi, sabo da tsoho, da na ajiye dominka, ƙaunataccena. ");
INSERT INTO hausa_vpl VALUES ("SS8_1","023_8_1","SNG","8","1","1","Da a ce kai ɗan’uwa ne gare ni, wanda nonon mahaifiyata sun shayar! Da in na same ka a waje, na sumbace ka, babu wanda zai rena ni. ");
INSERT INTO hausa_vpl VALUES ("SS8_2","023_8_2","SNG","8","2","2","Da sai in bi da kai in kawo ka gidan mahaifiyata, ita da ta koyar da ni. Da na ba ka ruwan inabi gaurayayye da kayan yaji ka sha, zaƙin rumman nawa. ");
INSERT INTO hausa_vpl VALUES ("SS8_3","023_8_3","SNG","8","3","3","Hannunsa na hagu yana a ƙarƙashin kaina, hannunsa na dama kuma ya rungume ni. ");
INSERT INTO hausa_vpl VALUES ("SS8_4","023_8_4","SNG","8","4","4","’Yan matan Urushalima, ku yi mini alkawari. Ba za ku tā da ko ku farka ƙauna ba sai haka ya zama lalle. ");
INSERT INTO hausa_vpl VALUES ("SS8_5","023_8_5","SNG","8","5","5","Wace ce wannan da take haurawa daga hamada tana dogara a kan ƙaunataccenta? Ƙaunatacciya A ƙarƙashin itacen gawasa na farkar da ke, a wurin da aka haife ki, wurin da mahaifiyarki ta haife ki. ");
INSERT INTO hausa_vpl VALUES ("SS8_6","023_8_6","SNG","8","6","6","Ka sa ni kamar hatimi a zuciyarka, kamar hatimi a hannunka; gama ƙauna tana da ƙarfi kamar mutuwa, kishinta yana kamar muguntar kabari, yana ƙuna kamar wuta mai ci, kamar gagarumar wuta. ");
INSERT INTO hausa_vpl VALUES ("SS8_7","023_8_7","SNG","8","7","7","Ruwa da yawa ba zai iya kashe ƙauna ba, koguna ba za su iya kwashe ta ba. In wani zai bayar da dukan dukiyar gidansa don ƙauna, za a yi masa dariya ne kawai. ");
INSERT INTO hausa_vpl VALUES ("SS8_8","023_8_8","SNG","8","8","8","Muna da ƙanuwa, nonanta ba su riga sun yi girma ba. Me za mu yi da ƙanuwarmu a ranar da za a yi maganar sonta? ");
INSERT INTO hausa_vpl VALUES ("SS8_9","023_8_9","SNG","8","9","9","Da a ce ita katanga ce, da sai mu gina hasumiyar azurfa a kanta. Da a ce ita ƙofa ce, da sai mun yi mata ƙyauren itacen al’ul. ");
INSERT INTO hausa_vpl VALUES ("SS8_10","023_8_10","SNG","8","10","10","Ni katanga ce kuma nonaina sun yi kamar hasumiya. Ta haka na zama idanunsa kamar wanda yake kawo gamsuwa. ");
INSERT INTO hausa_vpl VALUES ("SS8_11","023_8_11","SNG","8","11","11","Solomon ya kasance da gonar inabi a Ba’al-Hamon; ya ba da hayar gonar inabi ga ’yan haya. Kowanne zai biya shekel dubu na azurfa don ’ya’yan inabin. ");
INSERT INTO hausa_vpl VALUES ("SS8_12","023_8_12","SNG","8","12","12","Amma gonar inabina nawa ne da zan bayar; shekel dubu naka ne, ya Solomon, kuma ɗari biyu na waɗanda suke lura da ’ya’yan itatuwansa ne. ");
INSERT INTO hausa_vpl VALUES ("SS8_13","023_8_13","SNG","8","13","13","Ke da kike zaune a cikin lambu da ƙawaye suna lura da ke, bari in ji muryarki! ");
INSERT INTO hausa_vpl VALUES ("SS8_14","023_8_14","SNG","8","14","14","Ka zo, ƙaunataccena, ka zama kamar barewa ko kuwa kamar ’yar batsiya a kan dutsen da kayan yaji suke a shimfiɗe.");
INSERT INTO hausa_vpl VALUES ("IS1_1","024_1_1","ISA","1","1","1","Wahayi game da Yahuda da Urushalima wanda Ishaya ɗan Amoz ya gani a zamanin da Uzziya, Yotam, Ahaz da Hezekiya, suka yi mulkin Yahuda. ");
INSERT INTO hausa_vpl VALUES ("IS1_2","024_1_2","ISA","1","2","2","Ku kasa kunne, ya sammai! Ki saurara, ya duniya! Gama Ubangiji ya yi magana, “Na yi renon ’ya’ya, na kuma raya su, amma sun tayar mini. ");
INSERT INTO hausa_vpl VALUES ("IS1_3","024_1_3","ISA","1","3","3","Saniya ta san maigidanta, jaki ya san wurin sa wa dabbobi abinci maigidansa, amma Isra’ila ba su sani, mutanena ba su gane ba.” ");
INSERT INTO hausa_vpl VALUES ("IS1_4","024_1_4","ISA","1","4","4","Kash, ya ke al’umma mai zunubi, mutane cike da laifi, tarin masu aikata mugunta, ’ya’yan da aka miƙa wa lalaci! Sun yashe Ubangiji; sun rena Mai Tsarkin nan na Isra’ila suka juya masa baya. ");
INSERT INTO hausa_vpl VALUES ("IS1_5","024_1_5","ISA","1","5","5","Me ya sa za a ƙara yin muku dūka? Me ya sa kuka nace ga yin tayarwa? An yi wa dukan kanku rauni, zuciyarku duk tana ciwo. ");
INSERT INTO hausa_vpl VALUES ("IS1_6","024_1_6","ISA","1","6","6","Daga tafin ƙafarku zuwa saman kanku ba lafiya, sai miyaku da ƙujewa da manyan gyambuna, ba a tsabtacce su ba ko a daure ko shafa musu magani. ");
INSERT INTO hausa_vpl VALUES ("IS1_7","024_1_7","ISA","1","7","7","Ƙasarku ta zama kufai, an ƙone biranenku da wuta; baƙi suna ƙwace gonakinku a idanunku, ta zama kango kamar sa’ad da baƙi suka rushe ta. ");
INSERT INTO hausa_vpl VALUES ("IS1_8","024_1_8","ISA","1","8","8","An bar diyar Sihiyona kamar rumfar mai ƙumu a gonar inabi, kamar bukka a gonar kabewa, kamar birnin da aka kewaye da yaƙi. ");
INSERT INTO hausa_vpl VALUES ("IS1_9","024_1_9","ISA","1","9","9","Da ba a ce Ubangiji Maɗaukaki ya bar mana raguwar masu rai ba, da mun zama kamar Sodom, da mun zama kamar Gomorra. ");
INSERT INTO hausa_vpl VALUES ("IS1_10","024_1_10","ISA","1","10","10","Ku saurari maganar Ubangiji, ku masu mulkin Sodom; ku kasa kunne ga dokar Allahnmu, ku mutanen Gomorra! ");
INSERT INTO hausa_vpl VALUES ("IS1_11","024_1_11","ISA","1","11","11","Ubangiji ya ce, “Yawan hadayunku, mene ne suke a gare ni?” Ina da isashen hadayun ƙonawa, na raguna da na kitsen dabbobi masu ƙiba; ba na jin daɗin jinin bijimai da na tumaki da kuma na awaki. ");
INSERT INTO hausa_vpl VALUES ("IS1_12","024_1_12","ISA","1","12","12","Sa’ad da kuka zo don ku bayyana a gabana, wa ya nemi wannan daga gare ku, da kuke kai da kawowa a filayen gidana? ");
INSERT INTO hausa_vpl VALUES ("IS1_13","024_1_13","ISA","1","13","13","Ku daina kawo hadayu marasa amfani! Turarenku abin ƙyama ne gare ni. Ina ƙin bukukkuwanku na Sabon Wata, da na ranakun Asabbaci, da taronku na addini, ba zan iya jure wa mugun taronku ba. ");
INSERT INTO hausa_vpl VALUES ("IS1_14","024_1_14","ISA","1","14","14","Bukukkuwanku na Sabon Wata da na tsarkakan ranaku na ƙi su. Sun zama mini kaya; na gaji da ɗaukansu. ");
INSERT INTO hausa_vpl VALUES ("IS1_15","024_1_15","ISA","1","15","15","Sa’ad da kuka ɗaga hannuwanku wajen yin addu’a, zan ɓoye fuskata daga gare ku; ko da kun miƙa addu’o’i masu yawa, ba zan kasa kunne ba. Hannuwanku sun cika da jini! ");
INSERT INTO hausa_vpl VALUES ("IS1_16","024_1_16","ISA","1","16","16","Ku yi wanka ku kuma tsabtacce kanku. Ku kawar da mugayen ayyukanku daga gabana; Ku daina aikata mugunta. ");
INSERT INTO hausa_vpl VALUES ("IS1_17","024_1_17","ISA","1","17","17","Ku koyi yin nagarta; ku nemi adalci. Ku ƙarfafa waɗanda aka zalunta. Ku ba wa marayu hakkinsu, ku taimaki gwauruwa. ");
INSERT INTO hausa_vpl VALUES ("IS1_18","024_1_18","ISA","1","18","18","Ubangiji ya ce, “Yanzu fa ku zo, bari mu dubi batun nan tare, Ko da zunubanku sun yi ja kamar garura, za su zama fari kamar ƙanƙara; ko da sun yi ja kamar mulufi, za su zama kamar ulu. ");
INSERT INTO hausa_vpl VALUES ("IS1_19","024_1_19","ISA","1","19","19","In kuna da niyya kuna kuma yi mini biyayya, za ku ci abubuwa masu kyau daga ƙasar; ");
INSERT INTO hausa_vpl VALUES ("IS1_20","024_1_20","ISA","1","20","20","amma in kuka yi tsayayya kuka kuma yi tayarwa, za a kashe ku da takobi.” Ni Ubangiji na faɗa. ");
INSERT INTO hausa_vpl VALUES ("IS1_21","024_1_21","ISA","1","21","21","Dubi yadda amintacciyar birni ta zama karuwa! Dā ta cika da yin gaskiya; dā masu adalci a can suke zama, amma yanzu sai masu kisankai kaɗai! ");
INSERT INTO hausa_vpl VALUES ("IS1_22","024_1_22","ISA","1","22","22","Azurfarki ta zama jebu, an gauraye ruwan inabinki mafi kyau da ruwa. ");
INSERT INTO hausa_vpl VALUES ("IS1_23","024_1_23","ISA","1","23","23","Masu mulkinki ’yan tawaye ne, abokan ɓarayi; dukansu suna ƙaunar cin hanci suna bin kyautai. Ba sa taɓa tsare marayu a ɗakin shari’a; ba sa taimakon gwauruwa. ");
INSERT INTO hausa_vpl VALUES ("IS1_24","024_1_24","ISA","1","24","24","Saboda haka Ubangiji, Ubangiji Maɗaukaki, Mai Iko nan na Isra’ila, ya furta, “Kai, zan sami hutu daga maƙiyana in kuma yi ramuwa a kan abokan gābana. ");
INSERT INTO hausa_vpl VALUES ("IS1_25","024_1_25","ISA","1","25","25","Zan juye hannuna a kanki; zan wanke ke sarai in fitar da dukan ƙazantarki. ");
INSERT INTO hausa_vpl VALUES ("IS1_26","024_1_26","ISA","1","26","26","Zan maido da alƙalanki kamar yadda suke a dā can, mashawartanki kamar yadda suke da fari. Bayan haka za a ce da ke Birnin Masu Adalci, Amintacciyar Birni.” ");
INSERT INTO hausa_vpl VALUES ("IS1_27","024_1_27","ISA","1","27","27","Za a fanshi Sihiyona da adalci, masu tubanta kuma da aikin gaskiya. ");
INSERT INTO hausa_vpl VALUES ("IS1_28","024_1_28","ISA","1","28","28","Amma za a karye ’yan tawaye da masu zunubi, waɗanda suka rabu da Ubangiji kuma za su hallaka. ");
INSERT INTO hausa_vpl VALUES ("IS1_29","024_1_29","ISA","1","29","29","“Za ku ji kunya saboda masujadan ƙarƙashin itatuwan oak da kuka yi farin ciki; za a kunyata ku saboda lambun da kuka zaɓa. ");
INSERT INTO hausa_vpl VALUES ("IS1_30","024_1_30","ISA","1","30","30","Za ku zama kamar itacen oak mai busasshen ganyaye, kamar lambu marar ruwa. ");
INSERT INTO hausa_vpl VALUES ("IS1_31","024_1_31","ISA","1","31","31","Mutum mai ƙarfi zai zama kamar rama, aikinsa kuma kamar tartsatsin wuta; duka za su ƙone tare, ba kuwa wanda zai kashe wutar.” ");
INSERT INTO hausa_vpl VALUES ("IS2_1","024_2_1","ISA","2","1","1","Ga abin da Ishaya ɗan Amoz ya gani game da Yahuda da Urushalima. ");
INSERT INTO hausa_vpl VALUES ("IS2_2","024_2_2","ISA","2","2","2","A kwanaki masu zuwa za a kafa dutsen haikalin Ubangiji a matsayin babba cikin duwatsu; za a daga shi bisa tuddai, kuma dukan al’ummai za su bumbunto zuwa gare shi. ");
INSERT INTO hausa_vpl VALUES ("IS2_3","024_2_3","ISA","2","3","3","Mutane da yawa za su zo su ce, “Ku zo, bari mu haura zuwa dutsen Ubangiji, zuwa gidan Allah na Yaƙub. Zai koya mana hanyoyinsa, domin mu yi tafiya cikin hanyoyinsa.” Dokar za tă fito daga Sihiyona, maganar Ubangiji daga Urushalima. ");
INSERT INTO hausa_vpl VALUES ("IS2_4","024_2_4","ISA","2","4","4","Zai shari’anta tsakanin al’ummai zai kuma sulhunta faɗar mutane masu yawa. Za su mai da takubansu su zama garemani māsunsu su zama wuƙaƙen askin itatuwa. Al’umma ba za tă ƙara ɗauki takobi a kan al’umma ba, ba kuwa za su ƙara yin horarwar yaƙi. ");
INSERT INTO hausa_vpl VALUES ("IS2_5","024_2_5","ISA","2","5","5","Ki zo, ya gidan Yaƙub, bari mu yi tafiya a hasken Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS2_6","024_2_6","ISA","2","6","6","Ka rabu da mutanenka, gidan Yaƙub. Sun cika da ayyukan sihiri da aka kawo daga Gabas; suna yin duba kamar Filistiyawa suna tafa hannuwa tare da marasa sanin Allah. ");
INSERT INTO hausa_vpl VALUES ("IS2_7","024_2_7","ISA","2","7","7","Ƙasarsu ta cika da azurfa da zinariya; dukiyarsu kuma ba iyaka. Ƙasarsu ta cika da dawakai; kekunan yaƙinsu kuma ba iyaka. ");
INSERT INTO hausa_vpl VALUES ("IS2_8","024_2_8","ISA","2","8","8","Ƙasarsu ta cika da gumaka; sukan rusuna ga aikin hannuwansu, ga abin da yatsotsinsu suka yi. ");
INSERT INTO hausa_vpl VALUES ("IS2_9","024_2_9","ISA","2","9","9","Saboda an jawo mutum ƙasa aka kuma ƙasƙantar da ɗan adam, kada ku gafarta musu. ");
INSERT INTO hausa_vpl VALUES ("IS2_10","024_2_10","ISA","2","10","10","Ku tafi cikin duwatsu, ku ɓuya cikin ƙasa daga razanar Ubangiji da kuma darajar ɗaukakarsa! ");
INSERT INTO hausa_vpl VALUES ("IS2_11","024_2_11","ISA","2","11","11","Za a ƙasƙantar da mai girman kai za a kuma lalatar da fariyar masu ɗaga kai; Ubangiji kaɗai za a ɗaukaka a wannan rana. ");
INSERT INTO hausa_vpl VALUES ("IS2_12","024_2_12","ISA","2","12","12","Ubangiji Maɗaukaki yana da rana ajiye domin dukan masu girman kai da masu fariya domin dukan waɗanda aka ɗaukaka (zai kuwa ƙasƙantar da su), ");
INSERT INTO hausa_vpl VALUES ("IS2_13","024_2_13","ISA","2","13","13","domin dukan al’ul na Lebanon, masu tsayi da masu fariya, da kuma dukan itatuwan oak na Bashan, ");
INSERT INTO hausa_vpl VALUES ("IS2_14","024_2_14","ISA","2","14","14","domin dukan dogayen duwatsu da kuma tuddai masu tsayi, ");
INSERT INTO hausa_vpl VALUES ("IS2_15","024_2_15","ISA","2","15","15","domin kowace doguwar hasumiya da kowace katanga mai ƙarfi, ");
INSERT INTO hausa_vpl VALUES ("IS2_16","024_2_16","ISA","2","16","16","domin kowane jirgin ruwan kasuwanci da kuma jirgi mafi girma mafi kyau. ");
INSERT INTO hausa_vpl VALUES ("IS2_17","024_2_17","ISA","2","17","17","Za a jawo mai girman kai ƙasa a kuma ƙasƙantar da mai ɗaga kai; Ubangiji kaɗai za a ɗaukaka a wannan rana, ");
INSERT INTO hausa_vpl VALUES ("IS2_18","024_2_18","ISA","2","18","18","za a kuma kawar da gumaka ƙaƙaf. ");
INSERT INTO hausa_vpl VALUES ("IS2_19","024_2_19","ISA","2","19","19","Mutane za su gudu zuwa kogwannin duwatsu da kuma ramummuka a ƙasa daga razanar Ubangiji da kuma darajar ɗaukakarsa, sa’ad da ya tashi don yă girgiza duniya. ");
INSERT INTO hausa_vpl VALUES ("IS2_20","024_2_20","ISA","2","20","20","A wannan rana mutane za su zubar wa jaba da jamage gumakansu na azurfa da gumakansu na zinariya da suka yi don su bauta musu. ");
INSERT INTO hausa_vpl VALUES ("IS2_21","024_2_21","ISA","2","21","21","Za su gudu zuwa kogwannin duwatsu da kuma zuwa tsagaggun duwatsu daga razanar Ubangiji da kuma darajar ɗaukakarsa, sa’ad da ya tashi don yă girgiza duniya. ");
INSERT INTO hausa_vpl VALUES ("IS2_22","024_2_22","ISA","2","22","22","Ku daina dogara ga mutum, wanda numfashi ne kawai yake da shi a hancinsa. Wace daraja gare shi? ");
INSERT INTO hausa_vpl VALUES ("IS3_1","024_3_1","ISA","3","1","1","Yanzu ka duba fa, Ubangiji, Ubangiji Maɗaukaki, yana shirin yă ɗauke kowane tanadi da taimako daga Urushalima da Yahuda dukan tanade-tanaden abinci da kuma dukan tanade-tanaden ruwa, ");
INSERT INTO hausa_vpl VALUES ("IS3_2","024_3_2","ISA","3","2","2","jarumi, da soja, alƙali da annabi masu duba da dattijo, ");
INSERT INTO hausa_vpl VALUES ("IS3_3","024_3_3","ISA","3","3","3","shugaban sojojin hamsin da mutum mai makami, mai ba da shawara, gwanin sarrafa abubuwa da mai gwanintan dabo. ");
INSERT INTO hausa_vpl VALUES ("IS3_4","024_3_4","ISA","3","4","4","“Zan sa ’yan yara su zama shugabanninsu; ’yan yara kurum za su yi mulkinsu.” ");
INSERT INTO hausa_vpl VALUES ("IS3_5","024_3_5","ISA","3","5","5","Mutane za su zalunci juna mutum da mutum, maƙwabci da maƙwabci. Yara za su rena tsofaffi, ƙasƙantacce zai rena mai daraja. ");
INSERT INTO hausa_vpl VALUES ("IS3_6","024_3_6","ISA","3","6","6","Mutum zai kama ɗaya daga cikin ’yan’uwansa a gidan mahaifinsa ya ce, “Kana da abin sawa, ka zama shugabanmu; wannan kango kuma yă zama a ƙarƙashinka!” ");
INSERT INTO hausa_vpl VALUES ("IS3_7","024_3_7","ISA","3","7","7","Amma a ranan nan zai tā da murya ya ce, “Ba ni ba dai. Ba ni da abinci ko abin sawa a gidana; kada ka mai da ni shugaban mutane.” ");
INSERT INTO hausa_vpl VALUES ("IS3_8","024_3_8","ISA","3","8","8","Urushalima tana tangaɗi, Yahuda yana fāɗuwa; maganganunsu da ayyukansu suna gāba da Ubangiji, suna rena ɗaukakar kasancewarsa. ");
INSERT INTO hausa_vpl VALUES ("IS3_9","024_3_9","ISA","3","9","9","Fuskokinsu shaidu ne a kansu; suna nuna zunubinsu a fili kamar yadda Sodom ya yi; ba sa ma ɓoye shi. Kaitonsu! Sun jawo wa kansu masifa. ");
INSERT INTO hausa_vpl VALUES ("IS3_10","024_3_10","ISA","3","10","10","Ku faɗa wa masu adalci cewa kome zai zama musu da kyau, gama za su ji daɗin aikin da hannuwansu suka yi. ");
INSERT INTO hausa_vpl VALUES ("IS3_11","024_3_11","ISA","3","11","11","Kaiton masu mugunta! Masifa tana a kansu! Za a rama abin da hannuwansu suka yi. ");
INSERT INTO hausa_vpl VALUES ("IS3_12","024_3_12","ISA","3","12","12","Matasa suna zalunta mutanena, mata suna mulki a bisansu. Ya mutanena, jagorarinku suna ɓad da ku; suna karkatar da ku daga hanya. ");
INSERT INTO hausa_vpl VALUES ("IS3_13","024_3_13","ISA","3","13","13","Ubangiji ya ɗauki mazauninsa a cikin ɗakin shari’a; ya tashi don yă shari’anta mutane. ");
INSERT INTO hausa_vpl VALUES ("IS3_14","024_3_14","ISA","3","14","14","Ubangiji yana shari’a da dattawa da kuma shugabannin mutanensa, “Ku ne kuka lalace gonar inabina; ganimar talakawa suna a gidajenku. ");
INSERT INTO hausa_vpl VALUES ("IS3_15","024_3_15","ISA","3","15","15","Ina dalilin da kuke marmatsa mutanena kuna gurgurje fuskokin talakawa?” Ni Ubangiji Maɗaukaki na faɗa. ");
INSERT INTO hausa_vpl VALUES ("IS3_16","024_3_16","ISA","3","16","16","Ubangiji ya ce, “Matan Sihiyona suna da girman kai, suna tafiya da wuya a miƙe, da idanu masu yaudara, suna takawa ɗaya-ɗaya a hankali, da mundaye a ƙafafunsu, suna cas-cas. ");
INSERT INTO hausa_vpl VALUES ("IS3_17","024_3_17","ISA","3","17","17","Saboda haka Ubangiji zai kawo gyambuna a kawunan matan Sihiyona; Ubangiji zai sa a aske kawunansu, a bar su ƙwal.” ");
INSERT INTO hausa_vpl VALUES ("IS3_18","024_3_18","ISA","3","18","18","A wannan rana Ubangiji zai ƙwace abin da suke taƙama da shi, mundayensu, ɗankwalin kansu da abin wuyansu, ");
INSERT INTO hausa_vpl VALUES ("IS3_19","024_3_19","ISA","3","19","19","’yan kunnensu, kwandagansu da lulluɓinsu, ");
INSERT INTO hausa_vpl VALUES ("IS3_20","024_3_20","ISA","3","20","20","kitsonsu, sarƙar da suke sa wa damatsansu da ɗamararsu, kwalabai turare da layu, ");
INSERT INTO hausa_vpl VALUES ("IS3_21","024_3_21","ISA","3","21","21","da ƙawanen da suka sa a yatsotsinsu da hancinsu, ");
INSERT INTO hausa_vpl VALUES ("IS3_22","024_3_22","ISA","3","22","22","tufafi masu kyau, da manyan rigunansu, da mayafansu, da jakar kuɗinsu ");
INSERT INTO hausa_vpl VALUES ("IS3_23","024_3_23","ISA","3","23","23","da madubi, da kuma tufafin lilin da adikai, da gyale. ");
INSERT INTO hausa_vpl VALUES ("IS3_24","024_3_24","ISA","3","24","24","A maimakon ƙanshi, wari ne za a ji; a maimakon abin ɗamara, igiya ce za a samu; a maimakon kyakkyawan gashi, sanƙo za su kasance da shi a kai; a maimakon tufafi masu kyau, za su sa tsummoki; a maimakon kyau, za su zama munana. ");
INSERT INTO hausa_vpl VALUES ("IS3_25","024_3_25","ISA","3","25","25","Mazanku za su mutu ta wurin takobi, jarumawanku za su mutu a yaƙi. ");
INSERT INTO hausa_vpl VALUES ("IS3_26","024_3_26","ISA","3","26","26","Ƙofofin Sihiyona za su yi makoki su kuma yi kuka; za tă zama wofi, za tă zauna a ƙasa. ");
INSERT INTO hausa_vpl VALUES ("IS4_1","024_4_1","ISA","4","1","1","A wannan rana mata guda bakwai za su cafke namiji guda su ce, “Ma ciyar da kanmu mu kuma yi wa kanmu sutura; ka dai bari mu ce kai ne mijinmu. Ka ɗauke mana kunyar da za mu sha.” ");
INSERT INTO hausa_vpl VALUES ("IS4_2","024_4_2","ISA","4","2","2","A wannan rana Reshen Ubangiji zai zama kyakkyawa da kuma ɗaukaka, kuma amfanin ƙasar zai zama abin fariya da ɗaukakar waɗanda suka rayu a Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS4_3","024_4_3","ISA","4","3","3","Waɗanda suka rage a Sihiyona, waɗanda suka rage a Urushalima, za a ce da su masu tsarki, wato, dukan waɗanda aka rubuta a cikin masu rai a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("IS4_4","024_4_4","ISA","4","4","4","Ubangiji zai wanke duk wani ƙazantar matan Sihiyona; ya tsabtacce jinin da aka zubar daga Urushalima ta wurin ruhun hukunci da yake ƙuna kamar wuta. ");
INSERT INTO hausa_vpl VALUES ("IS4_5","024_4_5","ISA","4","5","5","Sa’an nan Ubangiji zai sa girgijen hayaƙi da rana da harshen wuta da dare a bisa dukan Dutsen Sihiyona da kuma bisa waɗanda suka tattaru a can; a bisa duka kuwa ɗaukakar za tă zama rumfa. ");
INSERT INTO hausa_vpl VALUES ("IS4_6","024_4_6","ISA","4","6","6","Za tă zama rumfa da inuwar da za tă tare zafin rana, da kuma mafaka da wurin ɓuya daga hadari da ruwan sama. ");
INSERT INTO hausa_vpl VALUES ("IS5_1","024_5_1","ISA","5","1","1","Zan rera waƙa wa ƙaunataccena waƙa game da gonar inabinsa. Ƙaunataccena yana da gonar inabi a gefen tudu mai dausayi. ");
INSERT INTO hausa_vpl VALUES ("IS5_2","024_5_2","ISA","5","2","2","Ya haƙa ƙasa ya kuma tsintsince duwatsun ya shuka mata inabi mafi kyau. Ya gina hasumiyar tsaro a cikinta ya kuma shirya wurin matsin ruwan inabi. Sa’an nan ya sa rai ga samun girbi mai kyau na inabin, amma sai ga shi inabin ya ba da munanan ’ya’ya. ");
INSERT INTO hausa_vpl VALUES ("IS5_3","024_5_3","ISA","5","3","3","“Yanzu fa ku mazauna cikin Urushalima da mutanen Yahuda, ku shari’anta tsakanina da gonar inabina. ");
INSERT INTO hausa_vpl VALUES ("IS5_4","024_5_4","ISA","5","4","4","Me kuma ya rage da za a yi wa gonar inabina fiye da abin da na yi mata? Da na nemi inabi masu kyau, me ya sa ta ba da munana ’ya’ya? ");
INSERT INTO hausa_vpl VALUES ("IS5_5","024_5_5","ISA","5","5","5","Yanzu zan faɗa muku abin da zan yi da gonar inabina. Zan cire katangar da ta kewaye ta, za tă kuwa lalace; zan rushe bangonta, za a kuwa tattake ta. ");
INSERT INTO hausa_vpl VALUES ("IS5_6","024_5_6","ISA","5","6","6","Zan mai da ita kango, ba zan aske ta ba, ba kuwa zan nome ta ba, sarƙaƙƙiya da ƙayayyuwa kuwa za su yi girma a can Zan umarci gizagizai kada su yi ruwan sama a kanta.” ");
INSERT INTO hausa_vpl VALUES ("IS5_7","024_5_7","ISA","5","7","7","Gonar inabin Ubangiji Maɗaukaki ita ce gidan Isra’ila, mutanen Yahuda kuma su ne lambun farin cikinsa. Yana kuma nema ganin gaskiya, amma sai ga zub da jini; yana neman adalci, amma sai ga shi kukan azaba yake ji. ");
INSERT INTO hausa_vpl VALUES ("IS5_8","024_5_8","ISA","5","8","8","Kaitonku ku waɗanda kuke ƙara wa kanku gidaje kuke kuma haɗa gonaki da gonaki har babu sauran filin da ya rage ku kuma zauna ku kaɗai a ƙasar. ");
INSERT INTO hausa_vpl VALUES ("IS5_9","024_5_9","ISA","5","9","9","Ubangiji Maɗaukaki ya furta a kunnuwana, “Tabbatacce manyan gidajen za su zama kango, za a bar kyawawan gidajen nan ba kowa. ");
INSERT INTO hausa_vpl VALUES ("IS5_10","024_5_10","ISA","5","10","10","Kadada goma na gonar inabi zai ba da garwan ruwan inabi ɗaya kaɗai, mudu guda na iri kuma zai ba da efa na hatsi guda kurum.” ");
INSERT INTO hausa_vpl VALUES ("IS5_11","024_5_11","ISA","5","11","11","Kaiton waɗanda suke tashi da sassafe don su nufi wurin shaye-shaye, waɗanda suke raba dare har sai sun bugu da ruwan inabi. ");
INSERT INTO hausa_vpl VALUES ("IS5_12","024_5_12","ISA","5","12","12","Suna kaɗa garaya, da molaye a bukukkuwansu, ganguna da busa da ruwan inabi, amma ba su kula da ayyukan Ubangiji ba, ba sa biyayya ga aikin hannuwansa. ");
INSERT INTO hausa_vpl VALUES ("IS5_13","024_5_13","ISA","5","13","13","Saboda haka mutanena za su yi zaman bauta domin rashin fahimi; manyan mutanensu za su mutu da yunwa talakawansu kuma su mutu da ƙishirwa. ");
INSERT INTO hausa_vpl VALUES ("IS5_14","024_5_14","ISA","5","14","14","Saboda haka kabari ya fadada marmarinsa ya kuma buɗe bakinsa babu iyaka; cikinsa manyan mutanensu da talakawansu za su gangara tare da dukan masu hayaniyarsu da masu murnansu. ");
INSERT INTO hausa_vpl VALUES ("IS5_15","024_5_15","ISA","5","15","15","Ta haka za a ƙasƙantar da mutum kuma za a ƙasƙantar da ’yan adam, za a ƙasƙanta da masu girman kai. ");
INSERT INTO hausa_vpl VALUES ("IS5_16","024_5_16","ISA","5","16","16","Amma Ubangiji Maɗaukaki zai sami ɗaukaka ta wurin aikata gaskiya, kuma Allah mai tsarki zai nuna kansa ta wurin adalcinsa. ");
INSERT INTO hausa_vpl VALUES ("IS5_17","024_5_17","ISA","5","17","17","Sa’an nan tumaki za su yi kiwo kamar yadda suke yi a wurin kiwonsu; raguna za su yi kiwo cikin abubuwa masu kyau da suka lalace. ");
INSERT INTO hausa_vpl VALUES ("IS5_18","024_5_18","ISA","5","18","18","Kaiton waɗanda suke jan zunubi da igiyar ruɗu, da kuma mugunta da igiyoyin keken yaƙin, ");
INSERT INTO hausa_vpl VALUES ("IS5_19","024_5_19","ISA","5","19","19","waɗanda suke cewa, “Bari Allah yă gaggauta, bari yă hanzarta aikinsa don mu gani. Bari yă iso, bari shirin Mai Tsarkin nan na Isra’ila yă zo, don mu sani.” ");
INSERT INTO hausa_vpl VALUES ("IS5_20","024_5_20","ISA","5","20","20","Kaiton waɗanda suke ce da mugunta nagarta nagarta kuma mugunta, waɗanda suke mai da duhu haske haske kuma duhu, waɗanda suke mai da ɗaci zaƙi zaƙi kuma ɗaci. ");
INSERT INTO hausa_vpl VALUES ("IS5_21","024_5_21","ISA","5","21","21","Kaiton waɗanda suke tsammani suna da hikima da kuma wayo a idonsu. ");
INSERT INTO hausa_vpl VALUES ("IS5_22","024_5_22","ISA","5","22","22","Kaiton waɗanda suke jarumawa a shan ruwan inabi da gwanaye a haɗin abubuwan sha, ");
INSERT INTO hausa_vpl VALUES ("IS5_23","024_5_23","ISA","5","23","23","waɗanda suke ƙyale masu laifi don sun ba da cin hanci, amma su hana a yi gaskiya wa marasa laifi. ");
INSERT INTO hausa_vpl VALUES ("IS5_24","024_5_24","ISA","5","24","24","Saboda haka kamar yadda harshen wuta yakan lashe kara kuma kamar yadda busasshiyar ciyawa takan ƙone ƙurmus a cikin wuta, haka saiwarsu za su ruɓa iska kuma ta hura furanninsu kamar ƙura; gama sun ƙi dokar Ubangiji Maɗaukaki suka kuma ƙyale maganar Mai Tsarkin nan na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS5_25","024_5_25","ISA","5","25","25","Saboda haka fushin Ubangiji ya yi ƙuna a kan mutanensa; ya ɗaga hannunsa ya kuma buge su. Duwatsu sun jijjigu, gawawwaki kuwa suka zama kamar juji a tituna. Saboda wannan duka, fushinsa bai huce ba, bai kuwa janye hannunsa ba. ");
INSERT INTO hausa_vpl VALUES ("IS5_26","024_5_26","ISA","5","26","26","Ya ɗaga tuta don al’ummai masu nisa, ya yi feɗuwa wa waɗanda suke a iyakar duniya. Ga shi sun iso, da sauri da kuma gaggawa! ");
INSERT INTO hausa_vpl VALUES ("IS5_27","024_5_27","ISA","5","27","27","Babu ko ɗayansu da ya gaji ko ya yi tuntuɓe, babu ko ɗaya da ya yi gyangyaɗi ko barci; babu abin ɗamarar da ya kunce a gindi, ba igiyar takalmin da ta tsinke. ");
INSERT INTO hausa_vpl VALUES ("IS5_28","024_5_28","ISA","5","28","28","Kibiyoyinsu masu tsini ne, an ɗaura dukan bakkunansu; kofatan dawakansu sun yi kamar dutsen ƙanƙara, ƙafafun keken yaƙinsu kamar guguwa ne. ");
INSERT INTO hausa_vpl VALUES ("IS5_29","024_5_29","ISA","5","29","29","Rurinsu ya yi kamar na zaki, suna ruri kamar ’yan zakoki; suna yin gurnani yayinda suke kamun abin da suke farauta su ɗauke shi ba mai ƙwace shi. ");
INSERT INTO hausa_vpl VALUES ("IS5_30","024_5_30","ISA","5","30","30","A wannan rana za su yi ta ruri a kansa kamar rurin teku. Kuma in wani ya dubi ƙasar, zai ga duhu da damuwa; haske ma zai zama duhu ta wurin gizagizai. ");
INSERT INTO hausa_vpl VALUES ("IS6_1","024_6_1","ISA","6","1","1","A shekarar da Sarki Uzziya ya mutu, na ga Ubangiji zaune a kan kujerar sarauta a sama cike da ɗaukaka, zatinsa ya cika haikali. ");
INSERT INTO hausa_vpl VALUES ("IS6_2","024_6_2","ISA","6","2","2","A bisansa akwai serafofi, kowanne yana da fikafikai shida. Fikafikai biyu sun rufe fuskokinsu, da biyu suka rufe ƙafafunsu, biyu kuma da su suke tashi. ");
INSERT INTO hausa_vpl VALUES ("IS6_3","024_6_3","ISA","6","3","3","Suna kiran juna, “Mai Tsarki, Mai Tsarki, Mai Tsarki! Ubangiji Maɗaukaki ne; duniya ta cika da ɗaukakarsa.” ");
INSERT INTO hausa_vpl VALUES ("IS6_4","024_6_4","ISA","6","4","4","Da jin ƙarar muryoyinsu madogarai da madogaran ƙofa suka girgiza, haikali kuma ya cika da hayaƙi. ");
INSERT INTO hausa_vpl VALUES ("IS6_5","024_6_5","ISA","6","5","5","Sai na tā da murya na ce, “Kaitona! Na shiga uku! Gama ni mutum ne mai leɓuna marar tsarki, kuma ina raye a cikin mutane masu leɓuna marasa tsarki, idanuna kuma sun ga Sarki, Ubangiji Maɗaukaki.” ");
INSERT INTO hausa_vpl VALUES ("IS6_6","024_6_6","ISA","6","6","6","Sai ɗaya daga cikin serafofin ya yi firiya zuwa wurina tare da garwashi mai wuta a hannunsa, wanda ya ɗiba da arautaki daga bagade. ");
INSERT INTO hausa_vpl VALUES ("IS6_7","024_6_7","ISA","6","7","7","Da shi ne ya taɓa bakina ya ce, “Duba, wannan ya taɓa leɓunanka, yanzu fa an kawar da laifofinka, an kuma gafarta maka zunubanka.” ");
INSERT INTO hausa_vpl VALUES ("IS6_8","024_6_8","ISA","6","8","8","Sa’an nan na ji muryar Ubangiji tana cewa, “Wa zan aika? Wa zai tafi mana?” Sai na ce, “Ga ni! Ka aike ni!” ");
INSERT INTO hausa_vpl VALUES ("IS6_9","024_6_9","ISA","6","9","9","Ya ce, “Je ka ka faɗa wa wannan mutane, “ ‘Kome yawan kasa kunne da za ku yi, ba za ku fahimta ba; Kome yawan dubar da za ku yi, ba za ku san abin da yake faruwa ba.’ ");
INSERT INTO hausa_vpl VALUES ("IS6_10","024_6_10","ISA","6","10","10","Ka sa zuciyar mutanen nan ta dushe; kunnuwansu su kurunce, idanunsu kuma su makance. In ba haka ba za su iya gani da idanunsu, su ji da kunnuwansu, su fahimta da zuciyarsu, su kuma juyo a kuma warkar da su.” ");
INSERT INTO hausa_vpl VALUES ("IS6_11","024_6_11","ISA","6","11","11","Sa’an nan na ce, “Har yaushe, ya Ubangiji?” Ya kuma amsa, “Sai an lalatar da biranen ba kowa a ciki, sai an mai da gidaje kangwaye ƙasa kuma ta zama kango ba amfani, ");
INSERT INTO hausa_vpl VALUES ("IS6_12","024_6_12","ISA","6","12","12","sai lokacin da Ubangiji ya kori kowa aka kuma yashe ƙasar gaba ɗaya. ");
INSERT INTO hausa_vpl VALUES ("IS6_13","024_6_13","ISA","6","13","13","Ko da yake kashi ɗaya bisa goma zai ragu a ƙasar, za tă sāke zama kango. Amma kamar yadda katambiri da itacen oak sukan bar kututturai sa’ad da aka yanke su, haka iri mai tsarkin nan zai zama kututture a ƙasar mai tsarki.” ");
INSERT INTO hausa_vpl VALUES ("IS7_1","024_7_1","ISA","7","1","1","Sa’ad da Ahaz ɗan Yotam, ɗan Uzziya, yake sarkin Yahuda, Sarki Rezin na Aram da Feka ɗan Remaliya sarkin Isra’ila suka haura don su yaƙi Urushalima, amma ba su iya cinta da yaƙi ba. ");
INSERT INTO hausa_vpl VALUES ("IS7_2","024_7_2","ISA","7","2","2","Sai fa aka faɗa wa gidan Dawuda cewa, “Aram ya haɗa kansa da Efraim”; saboda haka zuciyar Ahaz da ta mutanensa suka firgita, sai ka ce itatuwa a kurmin da iska ta girgiza. ");
INSERT INTO hausa_vpl VALUES ("IS7_3","024_7_3","ISA","7","3","3","Sai Ubangiji ya ce wa Ishaya, “Fita, kai da ɗanka Sheyar-Yashub, don ku sadu da Ahaz a ƙarshen wuriyar da take kawo ruwa daga Tafkin Tudu, a hanyar Filin Mai Wanki. ");
INSERT INTO hausa_vpl VALUES ("IS7_4","024_7_4","ISA","7","4","4","Ka faɗa masa, ‘Ka yi hankali, ka natsu kada kuma ka ji tsoro ko ka damu, kada ka ji tsoron fushin sarki Rezin da na Aram da na ɗan Remaliya, ba wani abu mai hatsari ba ne, bai fi hayaƙin ’yan ƙirare biyu da suke cin wuta ba. ");
INSERT INTO hausa_vpl VALUES ("IS7_5","024_7_5","ISA","7","5","5","Aram, Efraim da ɗan Remaliya sun ƙulla maƙarƙashiya, suna cewa, ");
INSERT INTO hausa_vpl VALUES ("IS7_6","024_7_6","ISA","7","6","6","“Bari mu kai wa Yahuda hari; bari mu yayyage su mu rarraba su a tsakaninmu, mu naɗa Tabeyel sarki a kansu.” ");
INSERT INTO hausa_vpl VALUES ("IS7_7","024_7_7","ISA","7","7","7","Duk da haka ga abin da Ubangiji Mai Iko Duka ya ce, “ ‘Ba zai faru ba, ba zai auku ba, ");
INSERT INTO hausa_vpl VALUES ("IS7_8","024_7_8","ISA","7","8","8","gama kan Aram shi ne Damaskus, kan Damaskus kuma kawai shi ne Rezin. Cikin shekaru sittin da biyar za a wargaje Efraim har ba za tă iya rayuwa ta zama al’umma ba. ");
INSERT INTO hausa_vpl VALUES ("IS7_9","024_7_9","ISA","7","9","9","Kan Efraim shi ne Samariya, kan Samariya kuma kawai shi ne ɗan Remaliya. In ba ku tsaya da ƙarfi cikin bangaskiyarku ba, ba za ku dawwama ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("IS7_10","024_7_10","ISA","7","10","10","Ubangiji ya kuma yi magana wa Ahaz ya ce, ");
INSERT INTO hausa_vpl VALUES ("IS7_11","024_7_11","ISA","7","11","11","“Ka roƙi Ubangiji Allahnka yă ba ka alama, ko daga zurfafa masu zurfi ko kuwa daga can cikin sama.” ");
INSERT INTO hausa_vpl VALUES ("IS7_12","024_7_12","ISA","7","12","12","Amma Ahaz ya ce, “Ba zan nema ba; ba zan gwada Ubangiji ba.” ");
INSERT INTO hausa_vpl VALUES ("IS7_13","024_7_13","ISA","7","13","13","Sa’an nan Ishaya ya ce, “To, ku saurara, ya ku gidan Dawuda! Abin kirki kuke yi ne da kuka ƙure haƙurin jama’a? Ko haƙurin Allah ne kuma kuke so ku ƙure? ");
INSERT INTO hausa_vpl VALUES ("IS7_14","024_7_14","ISA","7","14","14","Saboda haka Ubangiji kansa zai ba ku alama. Ga shi budurwa za tă yi ciki, za tă haifi ɗa, za tă kuwa kira shi Immanuwel. ");
INSERT INTO hausa_vpl VALUES ("IS7_15","024_7_15","ISA","7","15","15","In ya yi girma har ya isa yanke shawara don kansa, madara da zuma ne abincinsa. ");
INSERT INTO hausa_vpl VALUES ("IS7_16","024_7_16","ISA","7","16","16","Amma kafin yaron yă isa yanke shawara yă ƙi abin da yake mummuna, yă zaɓi abin da yake nagari, ƙasashen sarakunan nan biyu da kuke tsoro za su zama kango. ");
INSERT INTO hausa_vpl VALUES ("IS7_17","024_7_17","ISA","7","17","17","Ubangiji zai aukar maka da kwanakin wahala, kai da jama’arka, da dukan iyalin gidan sarauta, waɗanda suka fi muni tun lokacin da aka raba mulkin Efraim daga na Yahuda, zai kawo sarkin Assuriya.” ");
INSERT INTO hausa_vpl VALUES ("IS7_18","024_7_18","ISA","7","18","18","A wannan rana Ubangiji zai yi feɗuwa yă kira ƙudaje daga rafuffuka masu nisa na Masar da kuma ƙudan zuma daga ƙasar Assuriya. ");
INSERT INTO hausa_vpl VALUES ("IS7_19","024_7_19","ISA","7","19","19","Za su zo su mamaye kwazazzabai da kogwanni cikin duwatsu, a kan dukan ƙayayyuwa da dukan rammukan ruwa. ");
INSERT INTO hausa_vpl VALUES ("IS7_20","024_7_20","ISA","7","20","20","A wannan rana Ubangiji zai yi amfani da rezan da aka yi haya daga ƙetaren Kogi, sarkin Assuriya ke nan, yă aske kanku da gashin ƙafafunku, zai kuma aske gemunku. ");
INSERT INTO hausa_vpl VALUES ("IS7_21","024_7_21","ISA","7","21","21","A ranar, mutum zai bar karsana ɗaya da awaki biyu da rai. ");
INSERT INTO hausa_vpl VALUES ("IS7_22","024_7_22","ISA","7","22","22","Kuma saboda yalwa madarar da suke bayarwa, zai kasance da madarar da zai sha. Dukan waɗanda suka rage a ƙasar za su sha madara da zuma. ");
INSERT INTO hausa_vpl VALUES ("IS7_23","024_7_23","ISA","7","23","23","A wannan rana, a kowane wuri inda akwai kuringa dubu da kuɗinsu ya kai shekel dubu na azurfa, ƙayayyuwa da sarƙaƙƙiya ne kawai za su kasance a can. ");
INSERT INTO hausa_vpl VALUES ("IS7_24","024_7_24","ISA","7","24","24","Mutane za su je can da baka da kibiyoyi, gama ƙayayyuwa da sarƙaƙƙiya ne za su rufe ƙasar. ");
INSERT INTO hausa_vpl VALUES ("IS7_25","024_7_25","ISA","7","25","25","Game da dukan tuddai da dā ake nome da garemani kuwa, ba za ku ƙara je wurin ba saboda tsoron ƙayayyuwa da sarƙaƙƙiya; za su zama wuraren da ake kai shanu a sake su su yi ta yawo da kansu, tumaki kuma su yi ta gudu. ");
INSERT INTO hausa_vpl VALUES ("IS8_1","024_8_1","ISA","8","1","1","Ubangiji ya ce mini, “Ka ɗauki naɗaɗɗen littafi mai girma ka yi rubutu a kai da alƙalami kurum, Maher-Shalal-Hash-Baz. ");
INSERT INTO hausa_vpl VALUES ("IS8_2","024_8_2","ISA","8","2","2","Zan kuma kira Uriya firist da Zakariya ɗan Yeberekiya su zama mini amintattun shaidu.” ");
INSERT INTO hausa_vpl VALUES ("IS8_3","024_8_3","ISA","8","3","3","Sa’an nan na tafi na yi jima’i da annabiya, ta kuwa yi ciki ta haifi ɗa. Ubangiji kuma ya ce mini, “Raɗa masa suna, Maher-Shalal-Hash-Baz. ");
INSERT INTO hausa_vpl VALUES ("IS8_4","024_8_4","ISA","8","4","4","Kafin yaron yă san yadda zai ce ‘Babana’ ko ‘Mamana,’ sarkin Assuriya zai kwashe arzikin Damaskus da ganimar Samariya.” ");
INSERT INTO hausa_vpl VALUES ("IS8_5","024_8_5","ISA","8","5","5","Ubangiji ya sāke yi mini magana ya ce, ");
INSERT INTO hausa_vpl VALUES ("IS8_6","024_8_6","ISA","8","6","6","“Domin wannan jama’a ta ƙi natsattsen ruwan rafin Shilowa suka yi ta farin ciki a kan Rezin ɗan Remaliya, ");
INSERT INTO hausa_vpl VALUES ("IS8_7","024_8_7","ISA","8","7","7","saboda haka Ubangiji yana shirin yă kawo musu rigyawar ruwan Kogi, wato, sarkin Assuriya da dukan sojojinsa. Zai cika dukan gaɓoɓinsa, yă kuma malala har zuwa bakin kogi. ");
INSERT INTO hausa_vpl VALUES ("IS8_8","024_8_8","ISA","8","8","8","Yă yi ta malala har zuwa cikin Yahuda, yă shafe ta, yana ratsa ta ciki har yă kai kafaɗa. Fikafikansa da ya buɗe za su rufe fāɗin ƙasarka, Ya Immanuwel!” ");
INSERT INTO hausa_vpl VALUES ("IS8_9","024_8_9","ISA","8","9","9","Ku yi kururuwar yaƙi, ku ƙasashe, ku kuma ji tsoro! Ku saurara, dukanku manisantan ƙasashe. Ku shirya don yaƙi, ku kuma ji tsoro! ");
INSERT INTO hausa_vpl VALUES ("IS8_10","024_8_10","ISA","8","10","10","Ku ƙirƙiro dabarunku, amma ba za su yi nasara ba; ku ƙulla shirye-shiryenku, amma ba za su yi amfani ba, gama Allah yana tare da mu. ");
INSERT INTO hausa_vpl VALUES ("IS8_11","024_8_11","ISA","8","11","11","Ubangiji ya yi mini magana da hannunsa mai ƙarfi a kaina, yana yi mini gargaɗi kada in bi hanyar waɗannan mutane. Ya ce, ");
INSERT INTO hausa_vpl VALUES ("IS8_12","024_8_12","ISA","8","12","12","“Kada ka kira wani abu makirci game da kome da waɗannan mutane suke kira makirci; kada ji tsoron abin da suke tsoro, kada kuma ka firgita game da shi. ");
INSERT INTO hausa_vpl VALUES ("IS8_13","024_8_13","ISA","8","13","13","Ubangiji Maɗaukaki shi ne za ka ɗauka a matsayi mai tsarki, shi ne wanda za ka ji tsoro, shi ne za ka yi rawar jiki a gabansa, ");
INSERT INTO hausa_vpl VALUES ("IS8_14","024_8_14","ISA","8","14","14","zai kuwa kasance a wuri mai tsarki; amma ga dukan gidajen Isra’ila zai zama dutsen da zai sa mutane su yi tuntuɓe dutse kuma da zai sa su fāɗi. Ga dukan mutanen Urushalima kuma zai zama tarko da raga. ");
INSERT INTO hausa_vpl VALUES ("IS8_15","024_8_15","ISA","8","15","15","Yawancinsu za su yi tuntuɓe; za su fāɗi a kuwa ragargaza su, za a sa musu tarko a kuma kama su.” ");
INSERT INTO hausa_vpl VALUES ("IS8_16","024_8_16","ISA","8","16","16","Ɗaura shaidar nan ta gargadi ka kuma yimƙe umarnin Allah a cikin almajiraina. ");
INSERT INTO hausa_vpl VALUES ("IS8_17","024_8_17","ISA","8","17","17","Zan saurari Ubangiji, wanda ya ɓoye fuskarsa daga gidan Yaƙub. Zan dogara gare shi. ");
INSERT INTO hausa_vpl VALUES ("IS8_18","024_8_18","ISA","8","18","18","Ga ni, da yaran da Ubangiji ya ba ni. Mu alamu ne da shaidu a cikin Isra’ila daga Ubangiji Maɗaukaki, wanda yake zama a Dutsen Sihiyona. ");
INSERT INTO hausa_vpl VALUES ("IS8_19","024_8_19","ISA","8","19","19","Sa’ad da mutane suka ce muku ku nemi shawarar ’yan bori da masu sihiri, waɗanda suke shaƙe murya har ba a jin abin da suke faɗi, bai kamata mutane su nemi shawara daga Allahnsu ba? Me zai sa ku nemi shawara daga matattu a madadin masu rai? ");
INSERT INTO hausa_vpl VALUES ("IS8_20","024_8_20","ISA","8","20","20","Nemi umarnin Allah da kuma shaidar jan kunne. Duk wanda bai yi magana bisa ga wannan kalma ba, ba su da amfani. ");
INSERT INTO hausa_vpl VALUES ("IS8_21","024_8_21","ISA","8","21","21","Cikin matsuwa da yunwa, za su yi ta kai komo ko’ina a ƙasar; sa’ad da suka ji yunwa, za su yi fushi su tā da idanu sama, su zagi sarkinsu da Allahnsu. ");
INSERT INTO hausa_vpl VALUES ("IS8_22","024_8_22","ISA","8","22","22","Sa’an nan za su zura wa ƙasa idanu, abin da za su gani kawai shi ne matsuwa da duhu da kuma abin banrazana, za a kuma jefa su cikin baƙin duhu. ");
INSERT INTO hausa_vpl VALUES ("IS9_1","024_9_1","ISA","9","1","1","Duk da haka, babu sauran baƙin ciki ga waɗanda suke shan azaba. Dā ya ƙasƙantar da ƙasar kabilan Zebulun da ƙasar Naftali, amma nan gaba zai girmama Galili na Al’ummai, ta hanyar teku wadda take ta Urdun. ");
INSERT INTO hausa_vpl VALUES ("IS9_2","024_9_2","ISA","9","2","2","Mutanen da suke tafiya cikin duhu sun ga babban haske; a kan waɗanda suke zama a ƙasar inuwar mutuwa haske ya haskaka. ");
INSERT INTO hausa_vpl VALUES ("IS9_3","024_9_3","ISA","9","3","3","Ka fadada al’umma ka kuma ƙara farin cikinsu; suna farin ciki a gabanka yadda mutane sukan yi murna a lokacin girbi, kamar yadda mutane sukan yi farin ciki sa’ad da suke raba ganima. ");
INSERT INTO hausa_vpl VALUES ("IS9_4","024_9_4","ISA","9","4","4","Gama kamar yadda yake a kwanakin da aka ci Midiyan da yaƙi, kuka ji tsoro nauyin da ya nawaita musu, sandar da yake a kafaɗunsu, sandar masu zaluncinsu. ");
INSERT INTO hausa_vpl VALUES ("IS9_5","024_9_5","ISA","9","5","5","Kowane takalmin jarumin da aka yi amfani da shi a yaƙi da kuma kowane rigar da ka naɗe cikin jini zai kasance an ƙone shi zai kuma zama abin hura wuta. ");
INSERT INTO hausa_vpl VALUES ("IS9_6","024_9_6","ISA","9","6","6","Gama a gare mu an haifa mana yaro, a gare mu an ba da ɗa, gwamnati za tă kasance a kafaɗarsa. Za a ce da shi Mashawarci Mai Banmamaki, Allah Maɗaukaki Uban Madawwami, Sarkin Salama. ");
INSERT INTO hausa_vpl VALUES ("IS9_7","024_9_7","ISA","9","7","7","Game da girmar gwamnatinsa da salama babu iyaka. Zai gāji sarki Dawuda, yă yi mulki a matsayinsa, zai kafa mulkinsa a kan adalci da gaskiya, tun daga yanzu har zuwa ƙarshen zamani. Ubangiji Maɗaukaki ne ya yi niyyar aikata wannan duka. ");
INSERT INTO hausa_vpl VALUES ("IS9_8","024_9_8","ISA","9","8","8","Ubangiji ya aika da saƙon gāba da Yaƙub; zai auka wa Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS9_9","024_9_9","ISA","9","9","9","Dukan mutane za su san shi, Efraim da mazaunan Samariya, waɗanda suke magana da fariya suna kuma ɗaga kai, ");
INSERT INTO hausa_vpl VALUES ("IS9_10","024_9_10","ISA","9","10","10","“Tubalai sun zube a ƙasa, amma za mu sāke gina su da dutse; an sassare itatuwan ɓaure, amma za mu maya su da al’ul.” ");
INSERT INTO hausa_vpl VALUES ("IS9_11","024_9_11","ISA","9","11","11","Amma Ubangiji ya ƙarfafa maƙiyan Rezin gāba da su ya kuma ingiza abokan gāba. ");
INSERT INTO hausa_vpl VALUES ("IS9_12","024_9_12","ISA","9","12","12","Arameyawa daga gabas da Filistiyawa daga yamma sun cinye Isra’ila da buɗaɗɗen baki. Duk da haka, fushinsa bai huce ba, hannunsa har yanzu yana a miƙe. ");
INSERT INTO hausa_vpl VALUES ("IS9_13","024_9_13","ISA","9","13","13","Amma mutanen ba su juyo wurin wanda ya buge su ba, balle su nemi Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("IS9_14","024_9_14","ISA","9","14","14","Saboda haka Ubangiji zai yanke Isra’ila kai da wutsiya, da reshen dabino da iwa a rana guda; ");
INSERT INTO hausa_vpl VALUES ("IS9_15","024_9_15","ISA","9","15","15","dattawa da manyan mutane su ne kai, annabawa waɗanda suke koyar da ƙarairayi su ne wutsiya. ");
INSERT INTO hausa_vpl VALUES ("IS9_16","024_9_16","ISA","9","16","16","Waɗanda suke jagorar wannan mutane suna ɓad da su, su ne waɗanda ake jagora aka sa suka kauce. ");
INSERT INTO hausa_vpl VALUES ("IS9_17","024_9_17","ISA","9","17","17","Saboda haka Ubangiji ba zai ji daɗin matasa ba, ba kuwa zai ji tausayin marayu da gwauraye ba, gama kowa marar sanin Allah ne da kuma mugu, kowane baki yana faɗin mugayen maganganu. Duk da haka, fushinsa bai huce ba, hannunsa har yanzu yana a miƙe. ");
INSERT INTO hausa_vpl VALUES ("IS9_18","024_9_18","ISA","9","18","18","Tabbatacce mugunta tana ƙuna kamar wuta; tana cin ƙayayyuwa da sarƙaƙƙiya, ta sa wuta a jeji mai itatuwa masu yawa, don yă yi murtuke hayaƙi har zuwa sama. ");
INSERT INTO hausa_vpl VALUES ("IS9_19","024_9_19","ISA","9","19","19","Ta wurin fushin Ubangiji Maɗaukaki ƙasar za tă ci wuta mutane kuma za su zama abin hura wutar, babu wanda zai ji tausayin ɗan’uwansa. ");
INSERT INTO hausa_vpl VALUES ("IS9_20","024_9_20","ISA","9","20","20","A dama za su ci, amma su ci gaba da jin yunwa; a hagu za su ci, amma ba za su ƙoshi ba. Kowa zai mai da naman ’ya’yansa abinci. ");
INSERT INTO hausa_vpl VALUES ("IS9_21","024_9_21","ISA","9","21","21","Manasse zai mai da Efraim abinci, Efraim kuma yă cinye Manasse; tare za su yi gāba da Yahuda. Duk da haka, fushinsa bai huce ba, hannunsa har yanzu yana a miƙe. ");
INSERT INTO hausa_vpl VALUES ("IS10_1","024_10_1","ISA","10","1","1","Kaiton waɗanda suke kafa dokokin rashin gaskiya, waɗanda suke ba da ƙa’idodin danniya, ");
INSERT INTO hausa_vpl VALUES ("IS10_2","024_10_2","ISA","10","2","2","don su hana matalauta hakkinsu su kuma ƙi yin shari’ar gaskiya a kan waɗanda suke zaluntar mutanena, suna ƙwace wa gwauraye dukiyarsu suna kuma yi wa marayu ƙwace. ");
INSERT INTO hausa_vpl VALUES ("IS10_3","024_10_3","ISA","10","3","3","Me za ku yi a ranan nan ta hukunci, sa’ad da masifa ta zo daga nesa? Ga wa za ku tafi don neman taimako? Ina za ku bar dukiyarku? ");
INSERT INTO hausa_vpl VALUES ("IS10_4","024_10_4","ISA","10","4","4","Babu abin da zai rage sai cizon haƙora a cikin kamammu ko mutuwa cikin waɗanda aka kashe. Duk da haka, fushinsa bai huce ba, hannunsa har yanzu yana a miƙe. ");
INSERT INTO hausa_vpl VALUES ("IS10_5","024_10_5","ISA","10","5","5","“Kaiton Assuriya, sandar fushina, a hannun da kulkin fushina yake! ");
INSERT INTO hausa_vpl VALUES ("IS10_6","024_10_6","ISA","10","6","6","Na aike shi gāba da al’umma marar sanin Allah, na tura shi gāba da mutanen da suka ba ni fushi, don yă kwashe ganima yă kuma yi wason ganima, yă tattake su kamar laka a tituna. ");
INSERT INTO hausa_vpl VALUES ("IS10_7","024_10_7","ISA","10","7","7","Amma ba abin da ya yi niyya ke nan ba, ba abin da yake da shi a zuciya ba; manufarsa shi ne yă hallaka, yă kuma kawo ƙarshen al’ummai da yawa. ");
INSERT INTO hausa_vpl VALUES ("IS10_8","024_10_8","ISA","10","8","8","Ya ce, ‘Dukan shugabannin yaƙina ba sarakuna ba ne?’ ");
INSERT INTO hausa_vpl VALUES ("IS10_9","024_10_9","ISA","10","9","9","‘Kalno bai kasance kamar Karkemish ba? Hamat bai zama kamar Arfad Samariya kuma kamar Damaskus ba? ");
INSERT INTO hausa_vpl VALUES ("IS10_10","024_10_10","ISA","10","10","10","Yadda hannuna ya ƙwace mulkokin gumaka, mulkokin da siffofinsu suka fi na Urushalima da Samariya, ");
INSERT INTO hausa_vpl VALUES ("IS10_11","024_10_11","ISA","10","11","11","ba zan yi da Urushalima da siffofinta yadda na yi da Samariya da gumakanta ba?’ ” ");
INSERT INTO hausa_vpl VALUES ("IS10_12","024_10_12","ISA","10","12","12","Sa’ad da Ubangiji ya gama dukan aikinsa gāba da Dutsen Sihiyona da Urushalima, zai ce, “Zan hukunta sarkin Assuriya saboda fariya na gangancin zuciyarsa da kuma kallon reni na idanunsa. ");
INSERT INTO hausa_vpl VALUES ("IS10_13","024_10_13","ISA","10","13","13","Gama ya ce, “ ‘Ta wurin ƙarfin hannuna ne na aikata wannan, da kuma ta wurin hikimata, gama ina da fahimi. Na kau da iyakokin ƙasashe, na washe dukiyarsu; a matsayina na mai iko, na mamaye sarakunansu. ");
INSERT INTO hausa_vpl VALUES ("IS10_14","024_10_14","ISA","10","14","14","Kamar yadda mutum yakan miƙa hannu cikin sheƙar tsuntsu haka hannuna ya je ya washe dukiyar al’ummai; kamar yadda mutane sukan tattara ƙwai, haka na tattara dukan ƙasashe; ba tsuntsun da ya kakkaɓe fikafiki, ko yă buɗe baki don yă yi kuka.’ ” ");
INSERT INTO hausa_vpl VALUES ("IS10_15","024_10_15","ISA","10","15","15","Gatari ya taɓa fin wanda yake amfani da shi girma, ko zarto yă yi wa wanda yake amfani da shi taƙama? Sanda za tă girgiza mutumin da yake riƙe da ita, ko kuwa kulki yă jijjiga mutumin da yake riƙe da katako! ");
INSERT INTO hausa_vpl VALUES ("IS10_16","024_10_16","ISA","10","16","16","Saboda haka Ubangiji Maɗaukaki, zai aukar da cuta mai kisa a kan ƙosassu jarumawa; a ƙarƙashin sansaninsa zai ƙuna wuta kamar harshen wuta. ");
INSERT INTO hausa_vpl VALUES ("IS10_17","024_10_17","ISA","10","17","17","Hasken Isra’ila zai zo kamar wuta, Mai Tsarkinsu zai zama kamar wuta; a rana guda zai ƙone yă kuma cinye ƙayayyuwa da sarƙaƙƙiyarsa. ");
INSERT INTO hausa_vpl VALUES ("IS10_18","024_10_18","ISA","10","18","18","Darajar jejinsa da gonakinsa masu dausayi za a hallaka su ɗungum, kamar yadda ciwo yakan kashe mutum. ");
INSERT INTO hausa_vpl VALUES ("IS10_19","024_10_19","ISA","10","19","19","Sauran itatuwan jejinsa kuma za su ragu ko ɗan ƙaramin yaro ma zai iya ƙidaya su. ");
INSERT INTO hausa_vpl VALUES ("IS10_20","024_10_20","ISA","10","20","20","A wannan rana raguwar Isra’ila, waɗanda suka ragu na gidan Yaƙub, ba za su ƙara dogara ga wanda ya kusa hallaka su ba amma za su dogara ga Ubangiji, Mai Tsarkin nan na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS10_21","024_10_21","ISA","10","21","21","Raguwa za tă komo, raguwar Yaƙub za su komo ga Maɗaukaki Allah. ");
INSERT INTO hausa_vpl VALUES ("IS10_22","024_10_22","ISA","10","22","22","Ko da yake mutanenka, ya Isra’ila, sun zama kamar yashin bakin teku, raguwa ce kurum za tă komo. A ƙaddara hallaka, mai mamayewa da mai adalci. ");
INSERT INTO hausa_vpl VALUES ("IS10_23","024_10_23","ISA","10","23","23","Ubangiji Maɗaukaki, zai sa hallakar da aka ƙaddara a kan dukan ƙasa ta faru. ");
INSERT INTO hausa_vpl VALUES ("IS10_24","024_10_24","ISA","10","24","24","Saboda haka, ga abin da Ubangiji Maɗaukaki ya ce, “Ya mutanena masu zama a Sihiyona, kada ku ji tsoron Assuriyawa, waɗanda suka dūke ku da sanda suka kuma ɗaga kulki a kanku, kamar yadda Masar ta yi. ");
INSERT INTO hausa_vpl VALUES ("IS10_25","024_10_25","ISA","10","25","25","Ba da daɗewa ba fushina a kanku zai zo ga ƙarshe hasalata kuma za tă koma ga hallakarsu.” ");
INSERT INTO hausa_vpl VALUES ("IS10_26","024_10_26","ISA","10","26","26","Ubangiji Maɗaukaki zai bulale su da tsumagiya, kamar sa’ad da ya bugi Midiyan a dutsen Oreb; zai kuma ɗaga sandarsa a bisa ruwaye, yadda ya yi a Masar. ");
INSERT INTO hausa_vpl VALUES ("IS10_27","024_10_27","ISA","10","27","27","A wannan rana zai ɗauke nauyi daga kafaɗarku, nauyinsu daga wuyanku; za a karye karkiya domin kun yi ƙiba ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("IS10_28","024_10_28","ISA","10","28","28","Sun shiga Ayiyat; sun bi ta Migron; sun adana tanade-tanade a Mikmash. ");
INSERT INTO hausa_vpl VALUES ("IS10_29","024_10_29","ISA","10","29","29","Suka ƙetare ta hanya, suka kuma ce, “Za mu kwana a Geba.” Rama ta firgita; Gibeya ta Shawulu ta gudu. ");
INSERT INTO hausa_vpl VALUES ("IS10_30","024_10_30","ISA","10","30","30","Ki yi ihu, ya Diyar Gallim! Ki saurara, ya Layisha! Kayya, Anatot abin tausayi! ");
INSERT INTO hausa_vpl VALUES ("IS10_31","024_10_31","ISA","10","31","31","Madmena tana gudu; mutanen Gebim sun ɓuya. ");
INSERT INTO hausa_vpl VALUES ("IS10_32","024_10_32","ISA","10","32","32","A wannan rana za su dakata a Nob; za su jijjiga ƙarfinsu a dutsen Diyar Sihiyona, a tudun Urushalima. ");
INSERT INTO hausa_vpl VALUES ("IS10_33","024_10_33","ISA","10","33","33","Duba, Ubangiji Maɗaukaki, zai ragargaza rassa da iko mai girma. Za a sassare itatuwa masu ganyaye, za a yanke dogayen itatuwa har ƙasa. ");
INSERT INTO hausa_vpl VALUES ("IS10_34","024_10_34","ISA","10","34","34","Zai sassare itatuwan jeji da gatari har ƙasa; Lebanon zai fāɗi a gaban Mai Iko. ");
INSERT INTO hausa_vpl VALUES ("IS11_1","024_11_1","ISA","11","1","1","Toho zai fito daga kututturen Yesse; daga saiwarsa Reshe zai ba da ’ya’ya. ");
INSERT INTO hausa_vpl VALUES ("IS11_2","024_11_2","ISA","11","2","2","Ruhun Ubangiji zai kasance a kansa, Ruhun hikima da na fahimta, Ruhun shawara da na iko, Ruhun sani da na tsoron Ubangiji, ");
INSERT INTO hausa_vpl VALUES ("IS11_3","024_11_3","ISA","11","3","3","zai kuwa ji daɗin tsoron Ubangiji. Ba zai yi hukunci ta wurin abin da ya gani da idanunsa ba, ba zai kuwa yanke shawara ta wurin abin da ya ji da kunnuwansa ba; ");
INSERT INTO hausa_vpl VALUES ("IS11_4","024_11_4","ISA","11","4","4","amma da adalci zai yi wa masu bukata shari’a, da gaskiya zai yanke shawarwari saboda matalautan duniya. Kamar sanda zai bugi duniya da maganar bakinsa; da numfashin leɓunansa zai yanke mugaye. ");
INSERT INTO hausa_vpl VALUES ("IS11_5","024_11_5","ISA","11","5","5","Adalci ne zai zama abin ɗamararsa aminci kuma igiyar da zai ɗaura kewaye da gindinsa. ");
INSERT INTO hausa_vpl VALUES ("IS11_6","024_11_6","ISA","11","6","6","Kyarkeci zai zauna tare da ɗan rago damisa za tă kwanta tare da akuya, ɗan maraƙi da zaki da ɗan saniya za su yi kiwo tare; ɗan yaro ne zai lura da su. ");
INSERT INTO hausa_vpl VALUES ("IS11_7","024_11_7","ISA","11","7","7","Saniya da beyar za su yi kiwo tare, ƙananansu za su kwanta tare, zaki kuma zai ci ciyawa kamar saniya. ");
INSERT INTO hausa_vpl VALUES ("IS11_8","024_11_8","ISA","11","8","8","Jariri zai yi wasa kurkusa da ramin gamsheƙa, ɗan yaro kuma zai sa hannunsa a ramin maciji mai mugun dafi. ");
INSERT INTO hausa_vpl VALUES ("IS11_9","024_11_9","ISA","11","9","9","Ba za su yi lahani ko su hallaka wani a dutsena mai tsarki ba, gama duniya za tă cika da sanin Ubangiji kamar yadda ruwaye suka rufe teku. ");
INSERT INTO hausa_vpl VALUES ("IS11_10","024_11_10","ISA","11","10","10","A wannan rana Saiwar Yesse zai miƙe kamar tuta don mutanenta; al’ummai za su tattaru wurinsa, wurin hutunsa kuma zai zama mai daraja. ");
INSERT INTO hausa_vpl VALUES ("IS11_11","024_11_11","ISA","11","11","11","A wannan rana Ubangiji zai miƙa hannunsa sau na biyu don yă maido da raguwar da ta rage na mutanensa daga Assuriya, daga Masar ta Ƙasa, daga Masar ta Bisa, daga Kush, daga Elam, daga Babiloniya, daga Hamat da kuma daga tsibiran teku. ");
INSERT INTO hausa_vpl VALUES ("IS11_12","024_11_12","ISA","11","12","12","Zai tā da tuta saboda al’ummai yă kuma tattara masu zaman bauta na Isra’ila; zai tattara mutanen Yahuda da suke a warwatse kusurwoyi huɗu na duniya. ");
INSERT INTO hausa_vpl VALUES ("IS11_13","024_11_13","ISA","11","13","13","Kishin Efraim zai ɓace, za a kuma kau da abokan gāban Yahuda; Efraim ba zai yi kishin Yahuda ba, haka ma Yahuda ba zai yi gāba da Efraim ba. ");
INSERT INTO hausa_vpl VALUES ("IS11_14","024_11_14","ISA","11","14","14","Tare za su fāɗa wa Filistiyawa da yaƙi daga yamma; tare za su washe mutane wajen gabas. Za su ɗibiya hannuwa a kan Edom da Mowab, Ammonawa kuma za su yi musu biyayya. ");
INSERT INTO hausa_vpl VALUES ("IS11_15","024_11_15","ISA","11","15","15","Ubangiji zai busar da bakin tekun Masar; da iska mai zafi zai share hannunsa a bisa Kogin Yuferites Zai rarraba shi yă zama ƙanana rafuffuka bakwai saboda mutane su iya hayewa da ƙafa. ");
INSERT INTO hausa_vpl VALUES ("IS11_16","024_11_16","ISA","11","16","16","Za a yi babbar hanya saboda raguwa mutanensa da ta rage daga Assuriya, kamar yadda ta kasance wa Isra’ila sa’ad da suka fito daga Masar. ");
INSERT INTO hausa_vpl VALUES ("IS12_1","024_12_1","ISA","12","1","1","A wannan rana za ku ce, “Zan yabe ka, ya Ubangiji. Ko da yake a dā ka yi fushi da ni, amma yanzu ka daina fushi da ni ka kuwa ta’azantar da ni. ");
INSERT INTO hausa_vpl VALUES ("IS12_2","024_12_2","ISA","12","2","2","Tabbatacce Allah shi ne mai cetona; zan dogara gare shi ba kuwa zan ji tsoro ba. Ubangiji, Ubangiji, ne ƙarfina da waƙata; ya zama mai cetona.” ");
INSERT INTO hausa_vpl VALUES ("IS12_3","024_12_3","ISA","12","3","3","Da farin ciki zan ɗebo ruwa daga rijiyoyin ceto. ");
INSERT INTO hausa_vpl VALUES ("IS12_4","024_12_4","ISA","12","4","4","A wannan rana za ku ce, “Yi godiya ga Ubangiji, ku kira bisa sunansa; a sanar da wannan abin da ya aikata a cikin al’ummai, a kuma yi shela cewa sunansa mai girma ne. ");
INSERT INTO hausa_vpl VALUES ("IS12_5","024_12_5","ISA","12","5","5","Ku rera ga Ubangiji, gama ya aikata manyan abubuwa; bari a sanar da wannan ga dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("IS12_6","024_12_6","ISA","12","6","6","Ku tā da murya ku kuma rera don farin ciki, ya ku mutanen Sihiyona, gama Mai Tsarki na Isra’ila da girma yake a cikinku.” ");
INSERT INTO hausa_vpl VALUES ("IS13_1","024_13_1","ISA","13","1","1","Abubuwan da Allah ya yi magana a kai game da Babilon da Ishaya ɗan Amoz ya gani. ");
INSERT INTO hausa_vpl VALUES ("IS13_2","024_13_2","ISA","13","2","2","A tā da tuta a kan tudun da yake mai fili, ka tā da murya gare su; ka ɗaga hannu ka ba su alama don su shiga ƙofofi masu alfarma. ");
INSERT INTO hausa_vpl VALUES ("IS13_3","024_13_3","ISA","13","3","3","Na umarci tsarkakana; na umarci jarumawan yaƙina su gamsar da fushina, waɗanda suke farin ciki a nasarata. ");
INSERT INTO hausa_vpl VALUES ("IS13_4","024_13_4","ISA","13","4","4","Ka saurara, akwai surutu a kan duwatsu, sai ka ce na babban taron jama’a! Ka saurara, akwai hayaniya a cikin mulkoki, sai ka ce al’ummai ne suna ta tattaruwa! Ubangiji Maɗaukaki yana shirya mayaƙa don yaƙi. ");
INSERT INTO hausa_vpl VALUES ("IS13_5","024_13_5","ISA","13","5","5","Suna zuwa daga ƙasashe masu nesa, daga iyakokin duniya, Ubangiji da kuma fushinsa, zai hallaka dukan ƙasar. ");
INSERT INTO hausa_vpl VALUES ("IS13_6","024_13_6","ISA","13","6","6","Ku yi ihu, gama ranar Ubangiji ta yi kusa za tă zo kamar hallaka daga Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("IS13_7","024_13_7","ISA","13","7","7","Saboda wannan, hannun kowane mutum zai yi rauni, ƙarfin halin kowane mutum zai kāsa. ");
INSERT INTO hausa_vpl VALUES ("IS13_8","024_13_8","ISA","13","8","8","Tsoro zai kama su, zafi da azaba za su ci ƙarfinsu; za su yi ta murɗewa kamar mace mai naƙuda. Za su dubi juna a tsorace, fuskokinsu a ɓace. ");
INSERT INTO hausa_vpl VALUES ("IS13_9","024_13_9","ISA","13","9","9","Duba, ranar Ubangiji tana zuwa, muguwar rana, mai hasala da zafin fushi, don ta mai da ƙasar kango ta kuma hallakar da masu zunubi da suke cikinta. ");
INSERT INTO hausa_vpl VALUES ("IS13_10","024_13_10","ISA","13","10","10","Taurarin sama da ƙungiyoyinsu ba za su ba da haskensu ba. Rana za tă yi duhu wata kuma ba zai ba da haskensa ba. ");
INSERT INTO hausa_vpl VALUES ("IS13_11","024_13_11","ISA","13","11","11","Zan hukunta duniya saboda muguntarta, mugaye saboda zunubansu. Zan kawo ƙarshe ga girman kan masu taƙama in kuma ƙasƙantar da ɗaga kan marasa tausayi. ");
INSERT INTO hausa_vpl VALUES ("IS13_12","024_13_12","ISA","13","12","12","Zan sa mutum yă fi zinariya zalla wuyar samuwa, fiye da zinariyar Ofir wuyan gani. ");
INSERT INTO hausa_vpl VALUES ("IS13_13","024_13_13","ISA","13","13","13","Saboda haka zan sa sammai su yi rawar jiki; duniya kuma za tă girgiza daga inda take a fushin Ubangiji Maɗaukaki, a ranar fushinsa mai ƙuna. ");
INSERT INTO hausa_vpl VALUES ("IS13_14","024_13_14","ISA","13","14","14","Kamar barewar da ake farautarta kamar tumaki marasa makiyayi, haka nan kowane mutum zai koma ga mutanensa, kowane mutum zai gudu zuwa ƙasarsa. ");
INSERT INTO hausa_vpl VALUES ("IS13_15","024_13_15","ISA","13","15","15","Duk wanda aka kama za a soke shi yă mutu; dukan waɗanda aka kama za su mutu ta takobi. ");
INSERT INTO hausa_vpl VALUES ("IS13_16","024_13_16","ISA","13","16","16","Za a fyaɗa ’ya’yansu a ƙasa su yi kucu-kucu a idanunsu; za a washe gidajensu, a kuma kwana da matansu. ");
INSERT INTO hausa_vpl VALUES ("IS13_17","024_13_17","ISA","13","17","17","Duba, zan zuga mutanen Medes su yi gāba da su, su da ba su kula da azurfa ba kuma ba sa damuwa da zinariya. ");
INSERT INTO hausa_vpl VALUES ("IS13_18","024_13_18","ISA","13","18","18","Bakkunansu za su kashe samari; ba za su ji tausayin jarirai ba ba za su kuwa nuna jinƙai ga ’yan yara ba. ");
INSERT INTO hausa_vpl VALUES ("IS13_19","024_13_19","ISA","13","19","19","Babilon, kayan daraja na mulkoki, abin fariyar Babiloniyawa, Allah zai kaɓantar da ita kamar yadda ya yi da Sodom da Gomorra. ");
INSERT INTO hausa_vpl VALUES ("IS13_20","024_13_20","ISA","13","20","20","Ba za ƙara kasance da mazauna kuma ba ko a yi zama a cikinta dukan zamanai; Ba wani mutumin Arab da zai kafa tentinsa a can, ba makiyayin da zai taɓa kiwon garkensa a can. ");
INSERT INTO hausa_vpl VALUES ("IS13_21","024_13_21","ISA","13","21","21","Amma halittun hamada za su kwanta a can, diloli za su cika gidajenta; a can mujiyoyi za su zauna, a can kuma awakin jeji za su yi ta tsalle. ");
INSERT INTO hausa_vpl VALUES ("IS13_22","024_13_22","ISA","13","22","22","Kuraye za su yi ta kuka a kagarorinta, diloli kuma a cikin fadodinta masu alfarma. Lokacinta ya yi kusa, kwanakinta kuma ba za su yi tsawo ba. ");
INSERT INTO hausa_vpl VALUES ("IS14_1","024_14_1","ISA","14","1","1","Ubangiji zai yi wa Yaƙub jinƙai; zai sāke zaɓi Isra’ila yă kuma zaunar da su a ƙasarsu. Baƙi ma za su zo su zauna tare da su su haɗa kai da gidan Yaƙub. ");
INSERT INTO hausa_vpl VALUES ("IS14_2","024_14_2","ISA","14","2","2","Al’ummai za su ɗauke su su kuma kawo wurin da yake nasu. Gidan Isra’ila kuwa za tă mallaki al’ummai a matsayin bayi maza da mata a ƙasar Ubangiji. Za su mai da waɗanda suka kama su su zama kamammu su kuma yi mulki a kan waɗanda suka taɓa danne su. ");
INSERT INTO hausa_vpl VALUES ("IS14_3","024_14_3","ISA","14","3","3","A ranar da Ubangiji ya hutashe ku daga wahala da azaba da muguwar bauta, ");
INSERT INTO hausa_vpl VALUES ("IS14_4","024_14_4","ISA","14","4","4","za ku yi wa sarkin Babilon wannan ba’a. Mai danniya ya zo ga ƙarshe! Dubi yadda fushinsa ya ƙare! ");
INSERT INTO hausa_vpl VALUES ("IS14_5","024_14_5","ISA","14","5","5","Ubangiji ya karye sandar mugaye, sandan mulkin masu mulki, ");
INSERT INTO hausa_vpl VALUES ("IS14_6","024_14_6","ISA","14","6","6","wanda cikin fushi ya kashe mutane da bugu marar ƙarewa, kuma cikin fushi ya mamaye al’ummai da fushi ba ƙaƙƙautawa. ");
INSERT INTO hausa_vpl VALUES ("IS14_7","024_14_7","ISA","14","7","7","Dukan ƙasashe suna hutawa suna kuma cikin salama; sun ɓarke da waƙa. ");
INSERT INTO hausa_vpl VALUES ("IS14_8","024_14_8","ISA","14","8","8","Har itatuwan fir ma da kuma al’ul na Lebanon suna murna a kanka suna cewa, “Yanzu da aka ƙasƙantar da kai, babu wani mai yankan katakon da ya zo yă yanka mu.” ");
INSERT INTO hausa_vpl VALUES ("IS14_9","024_14_9","ISA","14","9","9","Kabari a ƙarƙashi duk ya shirya don yă sadu da kai a zuwanka; yana tā da ruhohin da suka rasu don su gaishe ka, dukan waɗanda sun taɓa zama shugabanni a duniya; ya sa suka tashi daga kujerun sarauta, dukan waɗanda suke sarakuna a kan al’ummai. ");
INSERT INTO hausa_vpl VALUES ("IS14_10","024_14_10","ISA","14","10","10","Duk za su amsa, za su ce maka, “Ashe kai ma raunana ne, kamar mu; ka zama kamar mu.” ");
INSERT INTO hausa_vpl VALUES ("IS14_11","024_14_11","ISA","14","11","11","An yi ƙasa da dukan alfarmarka zuwa kabari, tare da surutan garayunka; tsutsotsi sun bazu a ƙarƙashinka tsutsotsi kuma suka rufe ka. ");
INSERT INTO hausa_vpl VALUES ("IS14_12","024_14_12","ISA","14","12","12","Yaya aka yi ka fāɗo daga sama Ya tauraron safiya, ɗan hasken asuba! An fyaɗa ka da ƙasa, kai da ka taɓa ƙasƙantar da al’ummai! ");
INSERT INTO hausa_vpl VALUES ("IS14_13","024_14_13","ISA","14","13","13","Ka yi tunani a ranka ka ce, “Zan hau zuwa sama; zan ɗaga kursiyina sama da taurarin Allah; zan zauna a kursiyi a kan dutsen taro, a can ƙurewar saman dutse mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("IS14_14","024_14_14","ISA","14","14","14","Zan haura can bisa gizagizai; zan mai da kaina kamar Mafi Ɗaukaka.” ");
INSERT INTO hausa_vpl VALUES ("IS14_15","024_14_15","ISA","14","15","15","Amma ga shi an gangara da kai zuwa kabari, zuwa zurfafan rami. ");
INSERT INTO hausa_vpl VALUES ("IS14_16","024_14_16","ISA","14","16","16","Waɗanda suka gan ka sun zura maka ido, suna tunani abin da zai same ka. “Wannan mutumin ne ya girgiza duniya ya kuma sa mulkoki suka razana, ");
INSERT INTO hausa_vpl VALUES ("IS14_17","024_14_17","ISA","14","17","17","mutumin da ya mai da duniya ta zama hamada, wanda ya tumɓuke biranenta bai kuma bar kamammunsa suka tafi ba?” ");
INSERT INTO hausa_vpl VALUES ("IS14_18","024_14_18","ISA","14","18","18","Dukan sarakunan duniya suna kwance a mace, kowa a kabarinsa. ");
INSERT INTO hausa_vpl VALUES ("IS14_19","024_14_19","ISA","14","19","19","Amma an jefar da kabarinka kamar reshen da aka ƙi; an rufe ka da waɗanda aka kashe, tare da waɗanda aka soke da takobi, waɗanda suka gangara zuwa duwatsun rami. Kamar gawar da aka tattake da ƙafa, ");
INSERT INTO hausa_vpl VALUES ("IS14_20","024_14_20","ISA","14","20","20","ba za a haɗa ka tare da su a jana’iza ba, gama ka hallaka ƙasarka ka kuma kashe mutanenka. Ba za a ƙara ambaci zuriyarka masu aikata mugunta ba. ");
INSERT INTO hausa_vpl VALUES ("IS14_21","024_14_21","ISA","14","21","21","A shirya wuri don a yayyanka ’ya’yansa maza saboda zunuban kakanninsu; kada a reno su su gāji ƙasar su cika duniya da biranensu. ");
INSERT INTO hausa_vpl VALUES ("IS14_22","024_14_22","ISA","14","22","22","“Zan yi gāba da su,” in ji Ubangiji Maɗaukaki. “Zan kau da sunan Babilon da waɗanda suka rage da rai a cikinta, ’ya’yanta da zuriyarta,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS14_23","024_14_23","ISA","14","23","23","“Zan mai da ita wuri domin mujiyoyi da kuma fadama; zan share ta da tsintsiyar hallaka,” Ni Ubangiji Maɗaukaki na faɗa. ");
INSERT INTO hausa_vpl VALUES ("IS14_24","024_14_24","ISA","14","24","24","Ubangiji Maɗaukaki ya rantse, “Tabbatacce, kamar yadda na riga na shirya, haka zai kasance, kuma kamar yadda na nufa, haka zai zama. ");
INSERT INTO hausa_vpl VALUES ("IS14_25","024_14_25","ISA","14","25","25","Zan ragargazar da Assuriya a cikin ƙasata; a kan duwatsuna zan tattake shi. Za a ɗauke nauyin da ya sa wa mutanena, a kuma ɗauke nauyinsa daga kafaɗunsu.” ");
INSERT INTO hausa_vpl VALUES ("IS14_26","024_14_26","ISA","14","26","26","Wannan shi ne shirin da na yi domin dukan duniya; wannan shi ne hannun da aka miƙa a bisa dukan al’ummai ke nan. ");
INSERT INTO hausa_vpl VALUES ("IS14_27","024_14_27","ISA","14","27","27","Gama Ubangiji Maɗaukaki ya ƙudura ya yi wannan, wa kuwa zai hana shi? Ya riga ya miƙa hannunsa, wa zai komar da shi? ");
INSERT INTO hausa_vpl VALUES ("IS14_28","024_14_28","ISA","14","28","28","Wannan abin da Allah ya yi magana ya zo ne a shekarar da Sarki Ahaz ya mutu. ");
INSERT INTO hausa_vpl VALUES ("IS14_29","024_14_29","ISA","14","29","29","Kada ku yi farin ciki, dukanku Filistiyawa, cewa sandar da ta buge ku ta karye; daga saiwar wannan maciji wani mugun maciji mai dafi zai taso, ’ya’yansa za su zama wani maciji masu dafi mai tashi sama. ");
INSERT INTO hausa_vpl VALUES ("IS14_30","024_14_30","ISA","14","30","30","Mafi talauci na matalauta zai sami wurin kiwo, mabukata kuma za su kwana lafiya. Amma zan hallakar da saiwarka da matsananciyar yunwa; za tă kashe naka da suka rage da rai. ");
INSERT INTO hausa_vpl VALUES ("IS14_31","024_14_31","ISA","14","31","31","Ki yi ihu, ya ke ƙofa! Yi kururuwa, ya ke birni! Ku razana, dukanku Filistiyawa! Ƙunshin hayaƙi yana tasowa daga arewa, kuma babu matsorata a cikin sojojinsa. ");
INSERT INTO hausa_vpl VALUES ("IS14_32","024_14_32","ISA","14","32","32","Wace amsa ce za a bayar wa jakadun wannan al’umma? “Ubangiji ya kafa Sihiyona, kuma a cikinta mutanensa masu shan azaba za su sami mafaka.” ");
INSERT INTO hausa_vpl VALUES ("IS15_1","024_15_1","ISA","15","1","1","Abin da Allah ya yi magana a kan Mowab shi ne, An lalatar da Ar a Mowab, an hallaka ta da dare! An lalatar da Kir a Mowab, an hallaka ta da dare! ");
INSERT INTO hausa_vpl VALUES ("IS15_2","024_15_2","ISA","15","2","2","Dibon ya haura zuwa haikalinta, zuwa masujadan kan tudu don tă yi kuka; Mowab ta yi ihu a kan Nebo da Medeba. An aske kowane kai an kuma yanke kowane gemu. ");
INSERT INTO hausa_vpl VALUES ("IS15_3","024_15_3","ISA","15","3","3","A tituna sun sa tsummoki a jikunansu; a kan rufin ɗakuna da kuma dandalin taruwa dukansu sai makoki suke yi, sun kwanta suna kuka. ");
INSERT INTO hausa_vpl VALUES ("IS15_4","024_15_4","ISA","15","4","4","Heshbon da Eleyale sun yi kuka da ƙarfi, aka ji muryoyinsu ko’ina har zuwa Yahaz. Saboda haka mayaƙan Mowab suka yi kuka da ƙarfi, har zuciyarsu ta karai. ");
INSERT INTO hausa_vpl VALUES ("IS15_5","024_15_5","ISA","15","5","5","Zuciyata ta yi kuka a kan Mowab; mutanenta sun gudu har zuwa Zowar, har zuwa Eglat Shelishiya. Sun haura zuwa Luhit, suna tafe suna kuka; a kan hanyar zuwa Horonayim suna makoki saboda hallakawarsu. ");
INSERT INTO hausa_vpl VALUES ("IS15_6","024_15_6","ISA","15","6","6","Ruwayen Nimrim sun ƙafe ciyayin kuma sun bushe; tsire-tsire duk sun ɓace babu sauran ɗanyen abu. ");
INSERT INTO hausa_vpl VALUES ("IS15_7","024_15_7","ISA","15","7","7","Saboda haka dukiyar da suka tara suka kuma ajiye sun ɗauka suka ƙetare Rafin Arabim da su. ");
INSERT INTO hausa_vpl VALUES ("IS15_8","024_15_8","ISA","15","8","8","Ƙugin kukansu ya kai ko’ina a iyakar Mowab; kururuwarsu ta kai har zuwa Eglayim, makokinsu ya kai har zuwa Beyer-Elim. ");
INSERT INTO hausa_vpl VALUES ("IS15_9","024_15_9","ISA","15","9","9","Ruwayen Dimon sun cika da jini, amma zan yi ƙari a kan Dimon, zan kawo zaki a kan masu gudu na Mowab da kuma a kan waɗanda suka ragu a ƙasar. ");
INSERT INTO hausa_vpl VALUES ("IS16_1","024_16_1","ISA","16","1","1","Ku aiko da raguna a matsayin haraji ga mai mulkin ƙasar, daga Sela a hamada, zuwa dutsen Diyar Sihiyona. ");
INSERT INTO hausa_vpl VALUES ("IS16_2","024_16_2","ISA","16","2","2","Kamar tsuntsaye masu firiya da aka kora daga sheƙa, haka matan Mowab suke a kogunan Arnon. ");
INSERT INTO hausa_vpl VALUES ("IS16_3","024_16_3","ISA","16","3","3","“Ku ba mu shawara, ku yanke shawara. Ku mai da inuwarku kamar dare, a tsakar rana. Ku ɓoye masu gudun hijira, kada ku bashe masu neman mafaka. ");
INSERT INTO hausa_vpl VALUES ("IS16_4","024_16_4","ISA","16","4","4","Ku bar Mowabawa masu gudun hijira su zauna tare da ku; ku zama mafakarsu daga mai neman hallaka su.” Mai danniya zai zo ga ƙarshe hallaka kuma za tă daina; masu lalatar da ƙasa za su kare ");
INSERT INTO hausa_vpl VALUES ("IS16_5","024_16_5","ISA","16","5","5","Da ƙauna za a kafa kursiyi; da aminci mutum zai zauna a kansa, wani daga gidan Dawuda, wani wanda ta shari’antawa yakan nuna gaskiya ya hanzarta yin adalci. ");
INSERT INTO hausa_vpl VALUES ("IS16_6","024_16_6","ISA","16","6","6","Mun ji fariyar Mowab, mun ji yawan fariyarta da girmankanta, fariyarta da reninta, amma taƙamarsu ta banza ce. ");
INSERT INTO hausa_vpl VALUES ("IS16_7","024_16_7","ISA","16","7","7","Saboda haka Mowabawa za su yi kuka mai zafi, za su yi kuka mai zafi tare saboda Mowab. Ku yi makoki ku kuma yi baƙin ciki saboda ƙosai da kuka riƙa ci a Kir Hareset. ");
INSERT INTO hausa_vpl VALUES ("IS16_8","024_16_8","ISA","16","8","8","Gonakin Heshbon sun bushe, inabin Sibma ma haka. Masu mulkin al’ummai sun tattake inabi mafi kyau, waɗanda suka taɓa yaɗuwa zuwa Yazer suka bazu ta wajen hamada. Tohonsu sun buɗu suka kai har teku. ");
INSERT INTO hausa_vpl VALUES ("IS16_9","024_16_9","ISA","16","9","9","Saboda haka na yi kuka, yadda Yazer take kuka, saboda inabin Sibma. Ya Heshbon, ya Eleyale, na cika ku da hawaye! Sowa ta murna a kanku saboda ’ya’yan itatuwanku da suka nuna da kuma girbinku sun ɓace. ");
INSERT INTO hausa_vpl VALUES ("IS16_10","024_16_10","ISA","16","10","10","An ɗauke farin ciki da murna daga gonakin itatuwa masu ’ya’ya; babu wanda yake rerawa ko yake sowa a cikin gonakin inabi; babu wanda yake matsin ruwan inabi a wuraren matsi, gama na kawo ƙarshen yin sowa. ");
INSERT INTO hausa_vpl VALUES ("IS16_11","024_16_11","ISA","16","11","11","Zuciyata tana makoki saboda Mowab kamar garaya, na yi baƙin ciki saboda Kir Hareset. ");
INSERT INTO hausa_vpl VALUES ("IS16_12","024_16_12","ISA","16","12","12","Sa’ad Mowab ta bayyana a masujadar bisa tudu, tana gajiyar da kanta ne kawai; sa’ad da ta tafi wurin tsafinta don tă yi addu’a, babu wani amfani. ");
INSERT INTO hausa_vpl VALUES ("IS16_13","024_16_13","ISA","16","13","13","Wannan ita ce maganar da Ubangiji ya riga ya yi game da Mowab. ");
INSERT INTO hausa_vpl VALUES ("IS16_14","024_16_14","ISA","16","14","14","Amma yanzu Ubangiji ya ce, “Cikin shekara uku, kamar yadda bawan da aka bautar da shi bisa ga yarjejjeniya zai lissafta, haka za a mai da daraja da kuma dukan yawan mutanen Mowab abin reni, daga ɗumbun mutanenta, ’yan kaɗan ne kaɗai za su ragu, za su kuma zama marasa ƙarfi.” ");
INSERT INTO hausa_vpl VALUES ("IS17_1","024_17_1","ISA","17","1","1","Abin da Allah ya faɗa game da Damaskus. “Duba, Damaskus ba za tă ƙara zama birni ba amma za tă zama tsibin juji. ");
INSERT INTO hausa_vpl VALUES ("IS17_2","024_17_2","ISA","17","2","2","Za a watse a bar biranen Arower a bar wa tumaki da shanu, waɗanda za su kwanta, ba tare da wani wanda zai tsorata su ba. ");
INSERT INTO hausa_vpl VALUES ("IS17_3","024_17_3","ISA","17","3","3","Birni mai katanga za tă ɓace daga Efraim, ikon sarauta kuma daga Damaskus; raguwar Aram za tă zama kamar darajar Isra’ila,” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("IS17_4","024_17_4","ISA","17","4","4","“A wannan rana ɗaukakar Yaƙub za tă ƙare; kitsen jikinsa zai lalace. ");
INSERT INTO hausa_vpl VALUES ("IS17_5","024_17_5","ISA","17","5","5","Zai zama kamar sa’ad da mai girbi ya tara hatsin da yake tsaye ya kuma girbe hatsin da hannunsa kamar sa’ad da mutum ya yi kala kawunan hatsi a Kwarin Refayim. ");
INSERT INTO hausa_vpl VALUES ("IS17_6","024_17_6","ISA","17","6","6","Duk da haka waɗansu kala za su ragu, sai ka ce sa’ad da an karkaɗe itace zaitun, aka bar ’ya’yan zaitun biyu ko uku a can ƙwanƙolin rassan, ko kuma aka bar huɗu ko biyar a rassa na gefe na itace mai ’ya’ya,” in ji Ubangiji, Allah na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS17_7","024_17_7","ISA","17","7","7","A wannan rana mutane za su nemi Mahaliccinsu su kuma juye idanunsu ga Mai Tsarkin nan na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS17_8","024_17_8","ISA","17","8","8","Ba za su dubi bagade ba, waɗanda suke aikin hannuwansu, ba za su kuma kula da ginshiƙan Ashera ba da kuma bagadan turaren da yatsotsinsu suka yi. ");
INSERT INTO hausa_vpl VALUES ("IS17_9","024_17_9","ISA","17","9","9","A wannan rana biranensu masu ƙarfi, waɗanda suka bari saboda Isra’ilawa, za su zama kamar wuraren da aka ƙyale suka zama kufai a jeji. Za su kuma zama kango. ");
INSERT INTO hausa_vpl VALUES ("IS17_10","024_17_10","ISA","17","10","10","Kun manta da Allah Mai Cetonku; ba ku tuna da Dutse, kagararku ba. Saboda haka, ko da yake kun fita ku shuka tsire-tsire mafi kyau kuka kuma shuka inabin da aka sayo daga waje, ");
INSERT INTO hausa_vpl VALUES ("IS17_11","024_17_11","ISA","17","11","11","ko da yake a ranar kun shuka su, kuka sa su yi girma, da safe kuma sa’ad da kuka shuka su, kuka sa suka yi toho suka yi fure, duk da haka girbin ba zai zama kome ba a ranar cuta da zafin da ba ta da magani. ");
INSERT INTO hausa_vpl VALUES ("IS17_12","024_17_12","ISA","17","12","12","Kash, ga hayaniyar al’ummai masu yawa suna hayaniya kamar rurin teku! Kash, ga fushin mutane suna ruri kamar rugugi kamar manyan ruwaye! ");
INSERT INTO hausa_vpl VALUES ("IS17_13","024_17_13","ISA","17","13","13","Ko da yake mutane suna ruri kamar sukuwar raƙuman ruwa, sa’ad da ya tsawata musu za su gudu can da nisa, aka kore su kamar yayinda iska ya hura a kan tuddai, kamar tattake kuma a cikin guguwa. ");
INSERT INTO hausa_vpl VALUES ("IS17_14","024_17_14","ISA","17","14","14","Da yamma, sai razana ba tsammani! Kafin safiya, duk sun ɓace! Wannan ne rabon waɗanda suka washe mu, rabon waɗanda suka yi mana ƙwace. ");
INSERT INTO hausa_vpl VALUES ("IS18_1","024_18_1","ISA","18","1","1","Kaiton ƙasar da ake jin ƙarar fikafikai a bakin kogunan Kush, ");
INSERT INTO hausa_vpl VALUES ("IS18_2","024_18_2","ISA","18","2","2","wadda ta aiko da jakadu ta teku cikin jiragen ruwan da aka yi da kyauro a bisa ruwa. Ku tafi, ku ’yan saƙo masu sauri, zuwa ga dogayen mutane masu sulɓin jiki, zuwa ga mutanen da ake jin tsoro a ko’ina, al’umma mai ƙarfin iko tana jawabin da ba a saba ji ba, mai ƙasar da koguna suka raba. ");
INSERT INTO hausa_vpl VALUES ("IS18_3","024_18_3","ISA","18","3","3","Ku dukan mutanen duniya, ku da kuke zama a duniya, sa’ad da aka ɗaga tutar a kan duwatsu, za ku gan shi, sa’ad da kuma aka busa ƙaho, za ku ji shi. ");
INSERT INTO hausa_vpl VALUES ("IS18_4","024_18_4","ISA","18","4","4","Ga abin da Ubangiji ya faɗa mini, “Zan yi shiru in kuma duba a hankali daga mazaunina, kamar ƙuna mai zafi a hasken rana, kamar girgijen raba a lokacin girbi.” ");
INSERT INTO hausa_vpl VALUES ("IS18_5","024_18_5","ISA","18","5","5","Gama kafin girbi, sa’ad da furanni suka karkaɗe furanni kuma suka zama ’ya’yan inabin da suka nuna, zai faffalle rassan kuringar inabi da wuƙa, ya yanke ya kuma kwashe rassan da suka bazu. ");
INSERT INTO hausa_vpl VALUES ("IS18_6","024_18_6","ISA","18","6","6","Duk za a bar su wa tsuntsayen dutse su ci da kuma namun jeji; tsuntsaye kuma za su ci rani a kansu, namun jeji kuma za su yi damina a kansu. ");
INSERT INTO hausa_vpl VALUES ("IS18_7","024_18_7","ISA","18","7","7","A wannan lokaci za a kawo kyautai wa Ubangiji Maɗaukaki daga dogayen mutane masu sulɓin jiki, daga mutanen da ake jin tsoro a ko’ina, al’umma mai ƙarfin iko na jawabin da ba a saba ji ba, mai ƙasar da koguna suka raba. Za a kawo kyautai zuwa Dutsen Sihiyona, wurin da Sunan Ubangiji Maɗaukaki yake. ");
INSERT INTO hausa_vpl VALUES ("IS19_1","024_19_1","ISA","19","1","1","Abin da Allah ya faɗa game da Masar, Duba, Ubangiji yana a kan girgije a sukwane yana kuwa zuwa Masar. Gumakan Masar sun firgita a gabansa, zukatan Masarawa sun karai. ");
INSERT INTO hausa_vpl VALUES ("IS19_2","024_19_2","ISA","19","2","2","“Zan tā da hargitsi tsakanin mutumin Masar da mutumin Masar, ɗan’uwa zai yi gāba da ɗan’uwa maƙwabci ya yi gāba da maƙwabci, birni ya yi gāba da birni, mulki ya yi gāba da mulki. ");
INSERT INTO hausa_vpl VALUES ("IS19_3","024_19_3","ISA","19","3","3","Masarawa za su karai, zan kuma sa shirye-shiryensu su zama banza; za su nemi shawarar gumaka da kuma ruhohin matattu, za su nemi shawarar mabiya da na masu duba. ");
INSERT INTO hausa_vpl VALUES ("IS19_4","024_19_4","ISA","19","4","4","Zan ba da Masarawa ga ikon azzalumi shugaba, mugun sarki kuma zai yi mulki a kansu,” in ji mai girma, Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("IS19_5","024_19_5","ISA","19","5","5","Ruwayen kogi za su ƙafe, bakin kogi zai shanye yă kuma bushe. ");
INSERT INTO hausa_vpl VALUES ("IS19_6","024_19_6","ISA","19","6","6","Wuriyoyi za su yi wari; rafuffukan Masar za su yi ta raguwa har su ƙafe. Iwa da jema za su bushe, ");
INSERT INTO hausa_vpl VALUES ("IS19_7","024_19_7","ISA","19","7","7","haka ma tsire-tsire kusa da Nilu, a bakin kogi. Kowane abin da aka shuka a gefen Nilu zai bushe, iska ta kwashe su ƙaf. ");
INSERT INTO hausa_vpl VALUES ("IS19_8","024_19_8","ISA","19","8","8","Masu kamun kifi za su yi nishi su kuma yi makoki, dukan waɗanda suke jefan ƙugiyoyi a Nilu; waɗanda suke jefan abin kamun kifi a ruwa abin kamun kifin za su zama marasa amfani. ");
INSERT INTO hausa_vpl VALUES ("IS19_9","024_19_9","ISA","19","9","9","Waɗanda suke aiki da kaɗin auduga za su karai, masu yin lilin mai kyau za su fid da zuciya. ");
INSERT INTO hausa_vpl VALUES ("IS19_10","024_19_10","ISA","19","10","10","Masu aikin tufafi ransu zai ɓace, kuma dukan masu samun albashi za su damu. ");
INSERT INTO hausa_vpl VALUES ("IS19_11","024_19_11","ISA","19","11","11","Shugabannin Zowan ba kome ba ne, wawaye ke kawai; mashawarta masu hikima na Fir’auna suna ba da shawarwari marasa amfani. Yaya za ka ce wa Fir’auna, “Ni ɗaya ne cikin masu hikima, almajirin sarakuna na dā can”? ");
INSERT INTO hausa_vpl VALUES ("IS19_12","024_19_12","ISA","19","12","12","Ina masu hikima suke yanzu? Bari su nuna maka su kuma sanar da abin da Ubangiji Maɗaukaki ya shirya a kan Masar. ");
INSERT INTO hausa_vpl VALUES ("IS19_13","024_19_13","ISA","19","13","13","Shugabannin Zowan sun zama wawaye, an ruɗe shugabannin Memfis dutsen kan kusurwa na mutanenta su sa Masar ta kauce. ");
INSERT INTO hausa_vpl VALUES ("IS19_14","024_19_14","ISA","19","14","14","Ubangiji ya sa zuba musu ruhun jiri; suka sa Masar ta yi tangaɗi cikin kome da take yi, kamar yadda mutumin da ya bugu yake tangaɗi cikin amansa. ");
INSERT INTO hausa_vpl VALUES ("IS19_15","024_19_15","ISA","19","15","15","Babu abin da Masar za tă yi, kai ko wutsiya, reshen dabino ko iwa. ");
INSERT INTO hausa_vpl VALUES ("IS19_16","024_19_16","ISA","19","16","16","A wannan rana Masarawa za su zama kamar mata. Za su yi rawar jiki lokacin da Ubangiji Maɗaukaki ya ɗaga hannu a kansu. ");
INSERT INTO hausa_vpl VALUES ("IS19_17","024_19_17","ISA","19","17","17","Ƙasar Yahuda kuma za kawo fargaba ga Masarawa; kowanne da Yahuda ya ambace zai firgita, saboda abin da Ubangiji Maɗaukaki yake shiri a kansu. ");
INSERT INTO hausa_vpl VALUES ("IS19_18","024_19_18","ISA","19","18","18","A wannan rana birane biyar a Masar za su yi yaren Kan’ana su kuma miƙa kai cikin yarjejjeniya ga Ubangiji Maɗaukaki. Za a ce da ɗayansu Birnin Hallaka. ");
INSERT INTO hausa_vpl VALUES ("IS19_19","024_19_19","ISA","19","19","19","A wannan rana za a kasance da bagade ga Ubangiji a tsakiyar Masar, da kuma ginshiƙin dutse Ubangiji a iyakarta. ");
INSERT INTO hausa_vpl VALUES ("IS19_20","024_19_20","ISA","19","20","20","Zai zama alama da kuma shaida ga Ubangiji Maɗaukaki a ƙasar Masar. Sa’ad da suka yi kuka ga Ubangiji saboda masu zaluntarsu, zai aiko musu mai ceto da mai kāriya, zai kuma cece su. ");
INSERT INTO hausa_vpl VALUES ("IS19_21","024_19_21","ISA","19","21","21","Saboda haka Ubangiji zai sanar da kansa ga Masarawa, kuma a wannan rana za su yarda da Ubangiji. Za su yi masa sujada da hadayu da hadayun hatsi; za su yi alkawura ga Ubangiji su kuma kiyaye su. ");
INSERT INTO hausa_vpl VALUES ("IS19_22","024_19_22","ISA","19","22","22","Ubangiji zai bugi Masar da annoba; zai buge su ya kuma warkar da su. Za su juyo wurin Ubangiji, zai amsa roƙonsu ya kuma warkar da su. ");
INSERT INTO hausa_vpl VALUES ("IS19_23","024_19_23","ISA","19","23","23","A wannan rana za a kasance da babban hanya daga Masar zuwa Assuriya. Assuriyawa za su tafi Masar, Masarawa kuma za su tafi Assuriya. Masarawa da Assuriyawa za su yi sujada tare. ");
INSERT INTO hausa_vpl VALUES ("IS19_24","024_19_24","ISA","19","24","24","A wannan rana Isra’ila za tă zama na uku, tare da Masar da Assuriya, abin albarka ga duniya. ");
INSERT INTO hausa_vpl VALUES ("IS19_25","024_19_25","ISA","19","25","25","Ubangiji Maɗaukaki zai albarkace su, yana cewa, “Albarka ta tabbata ga Masar, mutanena, Assuriya aikin hannuna, da kuma Isra’ila gādona.” ");
INSERT INTO hausa_vpl VALUES ("IS20_1","024_20_1","ISA","20","1","1","A shekarar da babban shugaban yaƙin da Sargon sarkin Assuriya ya aika, ya zo Ashdod ya kuma fāɗa mata ya kuma ci ta da yaƙi, ");
INSERT INTO hausa_vpl VALUES ("IS20_2","024_20_2","ISA","20","2","2","a wannan lokaci Ubangiji ya yi magana ta wurin Ishaya ɗan Amoz. Ya ce masa, “Tuɓe tsummokin da kake saye da su, da kuma takalman da ka sa a ƙafafu.” Ya kuwa yi haka, yana yawo tsirara kuma ba takalma a ƙafa. ");
INSERT INTO hausa_vpl VALUES ("IS20_3","024_20_3","ISA","20","3","3","Sa’an nan Ubangiji ya ce, “Kamar dai yadda bawana Ishaya ya yi ta yawo tsirara kuma ba takalmi a ƙafa shekara uku, a matsayin alama da shaida a kan Masar da Kush, ");
INSERT INTO hausa_vpl VALUES ("IS20_4","024_20_4","ISA","20","4","4","haka sarkin Assuriya zai kwashe kamammun Masarawa da Kushawa tsirara kuma ba takalma a ƙafa, yaro da babba, asirinsu a tsiraice, don a kunyata Masar. ");
INSERT INTO hausa_vpl VALUES ("IS20_5","024_20_5","ISA","20","5","5","Waɗanda suka dogara ga Kush suka yi taƙama da Masar za su ji tsoro su kuma sha kunya. ");
INSERT INTO hausa_vpl VALUES ("IS20_6","024_20_6","ISA","20","6","6","A wannan rana mutanen da suke zama a bakin teku za su ce, ‘Dubi abin da ya faru da waɗanda muka dogara a kai, waɗanda muka gudu muka je don neman taimako da ceto daga sarkin Assuriya! Yaya za mu tsira?’ ” ");
INSERT INTO hausa_vpl VALUES ("IS21_1","024_21_1","ISA","21","1","1","Abin da Allah ya faɗa game da Hamada da take kusa da Teku. Kamar guguwa mai share cikin ƙasar kudu, mai hari ya zo daga hamada, daga ƙasar mai banrazana. ");
INSERT INTO hausa_vpl VALUES ("IS21_2","024_21_2","ISA","21","2","2","An nuna mini mugun wahayi, mai bashewa ya bashe, mai washewa ya washe. Elam, ki yi yaƙi! Mediya, ki yi kwanto! Zan kawo ƙarshen dukan nishe-nishen da ta jawo. ");
INSERT INTO hausa_vpl VALUES ("IS21_3","024_21_3","ISA","21","3","3","Game da wannan jikina yana ciwo, zafi ya kama ni, kamar na mace mai naƙuda; na razana game da abin da na ji, na yi mamakin abin da na gani. ");
INSERT INTO hausa_vpl VALUES ("IS21_4","024_21_4","ISA","21","4","4","Gabana tana ta fāɗuwa, tsoro ya sa ina rawan jiki; hasken da nake marmari ya zo da razana gare ni. ");
INSERT INTO hausa_vpl VALUES ("IS21_5","024_21_5","ISA","21","5","5","Sun shirya teburori, sun shimfiɗa dardumai, sun ci, sun sha! Tashi, ku hafsoshi, sa mai a garkuwoyi! ");
INSERT INTO hausa_vpl VALUES ("IS21_6","024_21_6","ISA","21","6","6","Ga abin da mai girma ya ce mini, “Tafi, ka sa mai tsaro ka kuma sa ya ba da rahoton abin da ya gani. ");
INSERT INTO hausa_vpl VALUES ("IS21_7","024_21_7","ISA","21","7","7","Sa’ad da ya ga kekunan yaƙi tare da ƙungiyoyin dawakai, mahaya a kan jakuna, ko mahaya a kan raƙuma, to, fa ya zauna a faɗake, ya kintsa sosai.” ");
INSERT INTO hausa_vpl VALUES ("IS21_8","024_21_8","ISA","21","8","8","Mai tsaron kuma ya yi ihu, “Kowace rana, ranka yă daɗe, nakan tsaya a hasumiyar tsaro; kowane dare nakan tsaya a wurin aikina. ");
INSERT INTO hausa_vpl VALUES ("IS21_9","024_21_9","ISA","21","9","9","Duba, ga wani mutum tafe a keken yaƙin tare da ƙungiyar dawakai. Ya kuma mayar da amsa, ‘Babilon ta fāɗi, ta fāɗi! Dukan siffofin allolinta kwance a ragargaje a ƙasa!’ ” ");
INSERT INTO hausa_vpl VALUES ("IS21_10","024_21_10","ISA","21","10","10","Ya mutanena, an ragargaje ku a masussuka, na faɗa muku abin da na ji daga Ubangiji Maɗaukaki, daga Allah na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS21_11","024_21_11","ISA","21","11","11","Abin da Allah ya faɗa game da Duma, Wani ya kira ni daga Seyir, “Mai tsaro, me ya rage a daren? Mai tsaro, me ya rage a daren?” ");
INSERT INTO hausa_vpl VALUES ("IS21_12","024_21_12","ISA","21","12","12","Mai tsaro ya amsa, “Safiya ta gabato, haka kuma dare. In za ka yi tambaya, to, yi tambaya; sai ka sāke zuwa, ka tambaya.” ");
INSERT INTO hausa_vpl VALUES ("IS21_13","024_21_13","ISA","21","13","13","Abin da Allah ya faɗa game da Arabiya. Ku ayarin Dedanawa, ku da kuka sauka a jejin Arabiya, ");
INSERT INTO hausa_vpl VALUES ("IS21_14","024_21_14","ISA","21","14","14","ku kawo ruwa don ƙishirwa; ku da kuke zama a Tema, ku kawo abinci don masu gudun hijira. ");
INSERT INTO hausa_vpl VALUES ("IS21_15","024_21_15","ISA","21","15","15","Sun gudu daga takobi, daga takobin da aka janye, daga bakan da aka tanƙware da kuma daga zafin yaƙi. ");
INSERT INTO hausa_vpl VALUES ("IS21_16","024_21_16","ISA","21","16","16","Ga abin da mai girma ya ce mini, “Cikin shekara ɗaya, kamar yadda bawan da aka bautar da shi bisa ga yarjejjeniya zai lissafta, dukan sojojin Kedar za su zo ga ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("IS21_17","024_21_17","ISA","21","17","17","Waɗanda suka yi rai na maharba, jarumawan Kedar, za su zama kaɗan.” Ubangiji, Allah na Isra’ila, ya faɗa. ");
INSERT INTO hausa_vpl VALUES ("IS22_1","024_22_1","ISA","22","1","1","Abin da Allah ya faɗa game da Kwarin Wahayi. Mene ne ya dame ku a yanzu, da dukanku kuka hau kan rufin gidaje. ");
INSERT INTO hausa_vpl VALUES ("IS22_2","024_22_2","ISA","22","2","2","Ya kai gari cike da hayaniya, Ya ke birnin tashin hankali da alkarya mai murna? Mutanenki ba su mutu ta wurin takobi ba, ba kuwa za su mutu a yaƙi ba. ");
INSERT INTO hausa_vpl VALUES ("IS22_3","024_22_3","ISA","22","3","3","Dukan shugabanninki sun gudu gaba ɗaya; an kama su ba tare da an yi amfani da baka ba. Dukanku da aka kama an kwashe ku ɗaurarru gaba ɗaya, kun gudu tun abokin gāba yana da nisa. ");
INSERT INTO hausa_vpl VALUES ("IS22_4","024_22_4","ISA","22","4","4","Saboda haka na ce, “Ƙyale ni kurum; bari in yi kuka mai zafi. Kada ka yi ƙoƙarin ta’azantar da ni a kan hallakar mutanena.” ");
INSERT INTO hausa_vpl VALUES ("IS22_5","024_22_5","ISA","22","5","5","Ubangiji, Ubangiji Maɗaukaki, yana da ranar giggicewa da tattakewa da banrazana a cikin Kwarin Wahayi, ranar ragargazawar katanga da ta yin kuka ga duwatsu. ");
INSERT INTO hausa_vpl VALUES ("IS22_6","024_22_6","ISA","22","6","6","Elam ya ɗauki kwari da baka, tare da mahayan kekunan yaƙinta da dawakai; Kir ta buɗe garkuwoyi. ");
INSERT INTO hausa_vpl VALUES ("IS22_7","024_22_7","ISA","22","7","7","Kwarurukanku mafi kyau sun cika da kekunan yaƙi, an kuma tsai da mahayan dawakai a ƙofofin birni. ");
INSERT INTO hausa_vpl VALUES ("IS22_8","024_22_8","ISA","22","8","8","An rurrushe kāriyar Yahuda, a ranan nan kuwa kun yi la’akari da makamai a cikin Fadan Kurmi; ");
INSERT INTO hausa_vpl VALUES ("IS22_9","024_22_9","ISA","22","9","9","kuka ga cewa Birnin Dawuda tana da wuraren kāriya masu yawa da suka tsattsage; kuka tattara ruwa a Tafkin Ƙasa. ");
INSERT INTO hausa_vpl VALUES ("IS22_10","024_22_10","ISA","22","10","10","Kuka ƙirga gine-gine a Urushalima kuka kuma rurrushe gidaje don ku ƙarfafa katanga. ");
INSERT INTO hausa_vpl VALUES ("IS22_11","024_22_11","ISA","22","11","11","Kuka gina matarar ruwa tsakanin katanga biyu saboda ruwan Tsohon Tafki, amma ba ku yi la’akari da Wannan da ya yi su ba, ko ku kula da Wannan da ya shirya shi tuntuni. ");
INSERT INTO hausa_vpl VALUES ("IS22_12","024_22_12","ISA","22","12","12","Ubangiji, Ubangiji Maɗaukaki ya kira ku a wannan rana don ku yi kuka ku yi ihu, don ku aske gashinku ku kuma sa tsummoki. ");
INSERT INTO hausa_vpl VALUES ("IS22_13","024_22_13","ISA","22","13","13","Amma duba, sai ga shi kuna farin ciki kuna kuma murna, kuna yankan shanu kuna kashe tumaki, kuna cin nama kuna kuma shan ruwan inabi! Kuna cewa, “Bari mu ci mu kuma sha, gama gobe za mu mutu!” ");
INSERT INTO hausa_vpl VALUES ("IS22_14","024_22_14","ISA","22","14","14","Ubangiji Maɗaukaki ya bayyana wannan a kunnena cewa, “Har ranar mutuwarka ba za a yi kafarar wannan zunubi ba,” in ji mai girma Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("IS22_15","024_22_15","ISA","22","15","15","Ga abin da Ubangiji, Ubangiji Maɗaukaki, ya faɗa, “Je, ka faɗa wa wannan mai hidima, Shebna, sarkin fada. ");
INSERT INTO hausa_vpl VALUES ("IS22_16","024_22_16","ISA","22","16","16","Mene ne kake yi a nan kuma wa ya ba ka izini ka haƙa kabari wa kanka a nan, kana fafe kabarinka a bisa kana sassaƙa wurin hutunka a dutse? ");
INSERT INTO hausa_vpl VALUES ("IS22_17","024_22_17","ISA","22","17","17","“Ka yi hankali, Ubangiji yana shirin ya kama ka da ƙarfi ya kuma ɗauke ka, ya kai mai ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("IS22_18","024_22_18","ISA","22","18","18","Zai dunƙule ka kamar ƙwallo ya jefa ka a cikin ƙasa mai girma. A can za ka mutu a can kuma kekunan yaƙinka masu daraja za su kasance, abin kunya kake ga gidan maigidanka! ");
INSERT INTO hausa_vpl VALUES ("IS22_19","024_22_19","ISA","22","19","19","Zan tumɓuke ka daga makaminka, za a kuma kore ka daga matsayinka. ");
INSERT INTO hausa_vpl VALUES ("IS22_20","024_22_20","ISA","22","20","20","“A wannan rana zan kira bawana, Eliyakim ɗan Hilkiya. ");
INSERT INTO hausa_vpl VALUES ("IS22_21","024_22_21","ISA","22","21","21","Zan rufe shi da rigarka in kuma yi masa ɗamara in miƙa masa ikonka. Zai zama mahaifi ga waɗanda suke zama a Urushalima da kuma gidan Yahuda. ");
INSERT INTO hausa_vpl VALUES ("IS22_22","024_22_22","ISA","22","22","22","Zan sa mabuɗin gidan Dawuda a kafaɗarsa; abin da ya buɗe ba mai rufewa, kuma abin da ya rufe ba mai buɗewa. ");
INSERT INTO hausa_vpl VALUES ("IS22_23","024_22_23","ISA","22","23","23","Zan kafa shi kamar turke a tsayayyen wuri; zai zama mazaunin daraja domin gidan mahaifinsa. ");
INSERT INTO hausa_vpl VALUES ("IS22_24","024_22_24","ISA","22","24","24","Dukan ɗaukakar iyalinsa za tă rataya a kansa daga ’ya’yansa da zuriyarsa har zuwa dukan ƙananan kayan aikinsa, wato, daga kwanoni har zuwa tuluna. ");
INSERT INTO hausa_vpl VALUES ("IS22_25","024_22_25","ISA","22","25","25","“A ranan nan, in ji Ubangiji Maɗaukaki, turken da aka kafa a tsayayyen wuri zai sumɓule; za a sare shi ya fāɗi, za a kuma datse nauyin da yake rataya a kansa.” Ni Ubangiji na faɗa. ");
INSERT INTO hausa_vpl VALUES ("IS23_1","024_23_1","ISA","23","1","1","Abin da Allah ya faɗa game da Taya. Ku yi kuka mai zafi, ya jiragen ruwan Tarshish! Gama an hallaka Taya aka kuma bar su babu gida ko tasha. Daga ƙasar Saifurus magana ta zo musu. ");
INSERT INTO hausa_vpl VALUES ("IS23_2","024_23_2","ISA","23","2","2","Ku yi shiru, ku mutanen tsibiri da ku ’yan kasuwan Sidon waɗanda masu ciniki a teku suka azurta. ");
INSERT INTO hausa_vpl VALUES ("IS23_3","024_23_3","ISA","23","3","3","A manyan ruwaye hatsin Shihor suka iso; girbin Nilu ne kuɗin shiga na Taya ta kuma zama kasuwar al’ummai. ");
INSERT INTO hausa_vpl VALUES ("IS23_4","024_23_4","ISA","23","4","4","Ki ji kunya, ya ke Sidon, da ke kuma, kagarar teku, gama teku ya yi magana ya ce, “Ban taɓa naƙuda ba balle in haifi ’ya’ya; ban taɓa goyon ’ya’ya maza ba balle in reno ’ya’ya mata.” ");
INSERT INTO hausa_vpl VALUES ("IS23_5","024_23_5","ISA","23","5","5","Sa’ad da magana ta kai Masar, za su razana da jin labari daga Taya. ");
INSERT INTO hausa_vpl VALUES ("IS23_6","024_23_6","ISA","23","6","6","Ku haye zuwa Tarshish; ku yi kuka mai zafi, ku mutanen tsibiri. ");
INSERT INTO hausa_vpl VALUES ("IS23_7","024_23_7","ISA","23","7","7","Wannan ce birnin murnanku, birnin nan na tun dā wadda ƙafafunta suka kai ta zama a ƙasashe masu nesa? ");
INSERT INTO hausa_vpl VALUES ("IS23_8","024_23_8","ISA","23","8","8","Wane ne ya ƙulla wannan a kan Taya ita da take ba da rawanin sarauta, wadda ’yan kasuwanta sarakuna ne, wadda masu cinikinta sanannu ne a duniya? ");
INSERT INTO hausa_vpl VALUES ("IS23_9","024_23_9","ISA","23","9","9","Ubangiji Maɗaukaki ya ƙulla shi, don yă kawo ƙarshen girman kan dukan darajarta ya kuma ƙasƙantar da dukan waɗanda suke sanannu a duniya. ");
INSERT INTO hausa_vpl VALUES ("IS23_10","024_23_10","ISA","23","10","10","Ki nome ƙasarki har zuwa wajen Nilu, Ya Diyar Tarshish, gama ba ki da tashan jirgin ruwa kuma. ");
INSERT INTO hausa_vpl VALUES ("IS23_11","024_23_11","ISA","23","11","11","Ubangiji ya miƙa hannunsa a bisa teku ya kuma sa mulkokinsa suka yi rawar jiki. Ya ba da umarni game da Funisiya cewa a hallaka kagararta. ");
INSERT INTO hausa_vpl VALUES ("IS23_12","024_23_12","ISA","23","12","12","Ya ce, “Ba za ki ƙara yin murna ba, Ya ke Budurwa Diyar Sidon, yanzu da kike ragargajiya! “Tashi, ki ƙetare zuwa Saifurus; a can ɗin ma ba za ki huta ba.” ");
INSERT INTO hausa_vpl VALUES ("IS23_13","024_23_13","ISA","23","13","13","Dubi ƙasar Babiloniyawa, wannan mutanen da yanzu ba su da wani amfani! Assuriyawa sun mai da ita wurin zaman halittun hamada; sun gina hasumiyoyin kwanto, suka ragargaza kagararta ƙaf suka mai da ita kango. ");
INSERT INTO hausa_vpl VALUES ("IS23_14","024_23_14","ISA","23","14","14","Ku yi kuka mai zafi, ku jiragen ruwan Tarshish; an rurrushe kagararku! ");
INSERT INTO hausa_vpl VALUES ("IS23_15","024_23_15","ISA","23","15","15","A wannan lokaci za a manta da Taya har shekaru saba’in, tsawon rayuwar sarki. Amma a ƙarshen waɗannan shekaru saba’in, zai zama wa Taya kamar yadda yake a waƙar karuwa cewa, ");
INSERT INTO hausa_vpl VALUES ("IS23_16","024_23_16","ISA","23","16","16","“Ɗauki garaya, ki ratsa birni, Ya ke karuwar da aka manta da ita; kaɗa garaya da kyau, ki rera waƙoƙi masu yawa, saboda a tuna da ke.” ");
INSERT INTO hausa_vpl VALUES ("IS23_17","024_23_17","ISA","23","17","17","A ƙarshen shekaru saba’in, Ubangiji zai magance Taya. Za tă koma ga aikinta na karuwanci za tă kuma yi kasuwancinta da dukan mulkokin duniya. ");
INSERT INTO hausa_vpl VALUES ("IS23_18","024_23_18","ISA","23","18","18","Duk da haka za a keɓe ribarta da kuɗin shigarta wa Ubangiji; ba za a yi ajiyarsu ko a ɓoye su. Ribarta za tă tafi ga waɗanda suke yi wa Ubangiji sujada, don su sami yalwataccen abinci da tufafi masu kyau. ");
INSERT INTO hausa_vpl VALUES ("IS24_1","024_24_1","ISA","24","1","1","Duba, Ubangiji zai wofinta duniya ya kuma yi kaca-kaca da ita; zai ɓata fuskarta ya watsar da mazaunanta, ");
INSERT INTO hausa_vpl VALUES ("IS24_2","024_24_2","ISA","24","2","2","zai zama abu ɗaya ga firist kamar yadda yake ga mutane, ga maigida kamar yadda yake ga bawa, ga uwargijiya kamar yadda yake ga baiwa, ga mai sayarwa kamar yadda yake ga mai saya, ga mai karɓan rance kamar yadda yake ga mai ba da rance, ga mai karɓan bashi kamar yadda yake ga mai ba da bashi. ");
INSERT INTO hausa_vpl VALUES ("IS24_3","024_24_3","ISA","24","3","3","Za a wofinta duniya ƙaƙaf a kuma washe ta sarai. Ubangiji ne ya faɗa haka. ");
INSERT INTO hausa_vpl VALUES ("IS24_4","024_24_4","ISA","24","4","4","Duniya ta bushe ta kuma yanƙwane, duniya tana shan azaba ta kuma raunana, masu daraja na duniya suna shan azaba. ");
INSERT INTO hausa_vpl VALUES ("IS24_5","024_24_5","ISA","24","5","5","Duniya ta ƙazantu ta wurin mutanenta sun ƙi yin biyayya da dokoki, sun keta farillai suka kuma karya madawwamin alkawari. ");
INSERT INTO hausa_vpl VALUES ("IS24_6","024_24_6","ISA","24","6","6","Saboda haka la’ana za tă auko wa duniya; dole mutanenta su ɗauki hakkin laifinsu. Saboda haka aka ƙone mazaunan duniya, kuma kaɗan ne kurum suka rage. ");
INSERT INTO hausa_vpl VALUES ("IS24_7","024_24_7","ISA","24","7","7","Sabon ruwan inabi ya bushe kuringar inabi kuma sun yanƙwane; dukan masu farin ciki suna nishi. ");
INSERT INTO hausa_vpl VALUES ("IS24_8","024_24_8","ISA","24","8","8","Kaɗe-kaɗen garayu sun yi shiru, surutun masu murna ya daina, garayan farin ciki ya yi shiru. ");
INSERT INTO hausa_vpl VALUES ("IS24_9","024_24_9","ISA","24","9","9","Babu sauran shan ruwan inabi suna rera waƙa; barasa ya zama da ɗaci ga masu shanta. ");
INSERT INTO hausa_vpl VALUES ("IS24_10","024_24_10","ISA","24","10","10","Birnin da aka birkice ta zama kango; an kulle ƙofar shiga kowane gida. ");
INSERT INTO hausa_vpl VALUES ("IS24_11","024_24_11","ISA","24","11","11","A tituna suna kukan neman ruwan inabi; dukan farin ciki ya dawo baƙin ciki, an hana dukan kaɗe-kaɗe a duniya. ");
INSERT INTO hausa_vpl VALUES ("IS24_12","024_24_12","ISA","24","12","12","An bar birnin kango, aka yi kaca-kaca da ƙofofinta. ");
INSERT INTO hausa_vpl VALUES ("IS24_13","024_24_13","ISA","24","13","13","Haka zai zama a duniya da kuma a cikin al’ummai, kamar sa’ad da akan karkaɗe itacen zaitun, ko kuma kamar sa’ad da ake barin kala bayan an girbe inabi. ");
INSERT INTO hausa_vpl VALUES ("IS24_14","024_24_14","ISA","24","14","14","Sun daga muryoyinsu, sun yi sowa ta farin ciki; daga yamma sun furta darajar Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS24_15","024_24_15","ISA","24","15","15","Saboda haka a gabas sun ɗaukaka Ubangiji, a ɗaukaka sunan Ubangiji, Allah na Isra’ila, a cikin tsibiran teku. ");
INSERT INTO hausa_vpl VALUES ("IS24_16","024_24_16","ISA","24","16","16","Daga iyakokin duniya mun ji waƙoƙi, “Ɗaukaka ga Mai Adalcin nan.” Amma na ce, “Na lalace, na lalace! Kaitona! Munafukai sun ci amana! Da munafunci munafukai sun ci amana!” ");
INSERT INTO hausa_vpl VALUES ("IS24_17","024_24_17","ISA","24","17","17","Razana da rami da tarko suna jiranku, Ya mutanen duniya. ");
INSERT INTO hausa_vpl VALUES ("IS24_18","024_24_18","ISA","24","18","18","Duk wanda ya yi ƙoƙarin tserewa daga ƙarar razana zai fāɗa cikin rami; wanda kuma ya tsere daga rami za a kama shi a tarko. An buɗe ƙofofin ambaliyar ruwan sama, harsashen ginin duniya suna rawa. ");
INSERT INTO hausa_vpl VALUES ("IS24_19","024_24_19","ISA","24","19","19","An tsage duniya, duniya ta farfashe ta wage, an girgiza duniya ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("IS24_20","024_24_20","ISA","24","20","20","Duniya tana tangaɗi kamar mashayi, tana lilo kamar rumfa a cikin iska; laifin tayarwarta ya yi nauyi sosai har ta fāɗi ba kuwa za tă ƙara tashi ba. ");
INSERT INTO hausa_vpl VALUES ("IS24_21","024_24_21","ISA","24","21","21","A wannan rana Ubangiji zai hukunta ikokin da suke cikin sama da kuma sarakunan da suke a duniya. ");
INSERT INTO hausa_vpl VALUES ("IS24_22","024_24_22","ISA","24","22","22","Za a tattara su tare kamar ɗaurarru a kurkuku; za a rufe su a kurkuku a kuma hukunta su bayan kwanaki masu yawa. ");
INSERT INTO hausa_vpl VALUES ("IS24_23","024_24_23","ISA","24","23","23","Sa’an nan wata zai ruɗe, rana ta ji kunya; gama Ubangiji Maɗaukaki zai yi mulki a kan Dutsen Sihiyona da kuma a cikin Urushalima, da kuma a gaban dattawanta, da ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("IS25_1","024_25_1","ISA","25","1","1","Ya Ubangiji, kai ne Allahna; zan ɗaukaka ka in kuma yabi sunanka, gama cikin cikakken aminci ka yi abubuwa masu banmamaki, abubuwan da aka shirya tun da. ");
INSERT INTO hausa_vpl VALUES ("IS25_2","024_25_2","ISA","25","2","2","Ka mai da birnin tsibin tarkace, ka lalatar da gari mai katanga, birnin baƙi mai ƙarfi, ta ɓace; ba za a ƙara gina ta ba. ");
INSERT INTO hausa_vpl VALUES ("IS25_3","024_25_3","ISA","25","3","3","Saboda haka mutane masu ƙarfi za su girmama ka; biranen mugayen al’ummai za su ji tsoronka. ");
INSERT INTO hausa_vpl VALUES ("IS25_4","024_25_4","ISA","25","4","4","Kai ka zama mafakar matalauta, mafaka don mabukata cikin damuwa, wurin ɓuya daga hadari, inuwa kuma daga zafin rana. Gama numfashin mugaye yana kamar da hadari mai bugun bango ");
INSERT INTO hausa_vpl VALUES ("IS25_5","024_25_5","ISA","25","5","5","kuma kamar zafin hamada. Ka kwantar da hayaniyar baƙi; kamar yadda inuwar girgije kan rage zafin rana, haka ake kwantar da waƙar mugaye. ");
INSERT INTO hausa_vpl VALUES ("IS25_6","024_25_6","ISA","25","6","6","A kan wannan dutse Ubangiji Maɗaukaki zai shirya bikin abinci mai kyau don dukan mutane, liyafar ajiyayyen ruwan inabi da nama mafi kyau da ruwan inabi mafi kyau. ");
INSERT INTO hausa_vpl VALUES ("IS25_7","024_25_7","ISA","25","7","7","A wannan dutse zai kawar da baƙin cikin da ya lulluɓe dukan mutane, ƙyallen da ya rufe dukan al’ummai; ");
INSERT INTO hausa_vpl VALUES ("IS25_8","024_25_8","ISA","25","8","8","zai haɗiye mutuwa har abada. Ubangiji Mai Iko Duka zai share hawaye daga dukan fuskoki; zai kawar da kunyar mutanensa daga dukan duniya. Ubangiji ne ya faɗa. ");
INSERT INTO hausa_vpl VALUES ("IS25_9","024_25_9","ISA","25","9","9","A wannan rana za su ce, “Tabbatacce wannan shi ne Allah; mun dogara a gare shi, ya kuma cece mu. Wannan shi ne Ubangiji, mun dogara a gare shi; bari mu yi murna mu kuma yi farin ciki a cikin cetonsa.” ");
INSERT INTO hausa_vpl VALUES ("IS25_10","024_25_10","ISA","25","10","10","Hannun Ubangiji zai zauna a kan wannan dutse; amma za a tattake Mowab a ƙarƙashinsa kamar yadda ake tattaka kara a cikin taki. ");
INSERT INTO hausa_vpl VALUES ("IS25_11","024_25_11","ISA","25","11","11","Za su buɗe hannuwansa a cikinsa, yadda mai iyo kan buɗe hannuwansa don yă yi iyo. Allah ya ƙasƙantar da girmankansu duk da wayon hannuwansu. ");
INSERT INTO hausa_vpl VALUES ("IS25_12","024_25_12","ISA","25","12","12","Zai rurrushe manyan katangar kagaru ya kuma ƙasƙantar da su; zai rushe su har ƙasa, su zama ƙura. ");
INSERT INTO hausa_vpl VALUES ("IS26_1","024_26_1","ISA","26","1","1","A wannan rana za a rera wannan waƙa a ƙasar Yahuda. Muna da birni mai ƙarfi; Allah yake ceton katanga da kuma kagarunta. ");
INSERT INTO hausa_vpl VALUES ("IS26_2","024_26_2","ISA","26","2","2","A buɗe ƙofofi saboda al’umma mai adalci ta shiga, al’ummar da mai aminci. ");
INSERT INTO hausa_vpl VALUES ("IS26_3","024_26_3","ISA","26","3","3","Za ka kiyaye shi da cikakken salama shi wanda ya kafa zuciyarsa gare ka, domin ya dogara a gare ka. ");
INSERT INTO hausa_vpl VALUES ("IS26_4","024_26_4","ISA","26","4","4","Ku dogara ga Ubangiji, gama shi Ubangiji, ne madawwamin Dutse. ");
INSERT INTO hausa_vpl VALUES ("IS26_5","024_26_5","ISA","26","5","5","Yakan ƙasƙantar da waɗanda suke zama a bisa ya kawar da birni mai alfarma ƙasa; ya rusa ta har ƙasa ya jefar da ita cikin ƙura. ");
INSERT INTO hausa_vpl VALUES ("IS26_6","024_26_6","ISA","26","6","6","Ƙafafu sukan tattake ta, ƙafafu waɗanda aka zalunta, wato, sawun matalauta. ");
INSERT INTO hausa_vpl VALUES ("IS26_7","024_26_7","ISA","26","7","7","Hanyar masu adalci sumul take; Ya Mai Aikata Gaskiya, ka sa hanyar masu adalci ta yi sumul. ");
INSERT INTO hausa_vpl VALUES ("IS26_8","024_26_8","ISA","26","8","8","I, Ubangiji, cikin tafiya a hanyar dokokinka, muna sa zuciya gare ka; sunanka da tunani a kanka su ne marmarin zukatanmu. ");
INSERT INTO hausa_vpl VALUES ("IS26_9","024_26_9","ISA","26","9","9","Raina yana marmarinka da dare; da safe kuma raina yana son ganinka. Sa’ad da hukunce-hukuncenka suka sauko duniya, mutanen duniya kan koyi adalci. ");
INSERT INTO hausa_vpl VALUES ("IS26_10","024_26_10","ISA","26","10","10","Ko da yake akan nuna wa mugaye alheri, ba sa koyi adalci; har ma a ƙasar masu aikata gaskiya sukan ci gaba da aikata mugunta ba sa ganin girmar darajar Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS26_11","024_26_11","ISA","26","11","11","Ya Ubangiji an ɗaga hannunka sama, amma ba sa ganinsa. Bari su ga himmarka don mutanenka su kuma sha kunya; bari wutar da aka ajiye don abokan gābanka ta cinye su. ");
INSERT INTO hausa_vpl VALUES ("IS26_12","024_26_12","ISA","26","12","12","Ubangiji ka kafa salama dominmu; duk abin da muka iya yi kai ne ka yi mana. ");
INSERT INTO hausa_vpl VALUES ("IS26_13","024_26_13","ISA","26","13","13","Ya Ubangiji, Allahnmu, waɗansu iyayengiji ban da kai sun yi mulki a kanmu, amma sunanka kaɗai muka girmama. ");
INSERT INTO hausa_vpl VALUES ("IS26_14","024_26_14","ISA","26","14","14","Yanzu duk sun mutu, ba za su ƙara rayuwa ba; waɗannan ruhohin da suka rasu ba za su tashi ba. Ka hukunta su ka kuma kawo su ga hallaka; ka sa ba za a ƙara tunawa da su ba. ");
INSERT INTO hausa_vpl VALUES ("IS26_15","024_26_15","ISA","26","15","15","Ka fadada al’umma, ya Ubangiji; ka fadada al’umma. Ka samo wa kanka ɗaukaka; ka fadada dukan iyakokin ƙasar. ");
INSERT INTO hausa_vpl VALUES ("IS26_16","024_26_16","ISA","26","16","16","Ubangiji, sun zo gare ka a cikin damuwarsu; sa’ad da ka hore su, da ƙyar suna iya yin addu’a. ");
INSERT INTO hausa_vpl VALUES ("IS26_17","024_26_17","ISA","26","17","17","Kamar mace mai ciki da take gab da haihuwa takan yi ta murɗawa tana kuka saboda zafi, haka muka kasance a gabanka, ya Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS26_18","024_26_18","ISA","26","18","18","Muna da ciki, mun yi ta murɗewa saboda zafi, amma mun haifi iska. Ba mu kawo ceto ga duniya ba; ba mu haifi mutanen duniya ba. ");
INSERT INTO hausa_vpl VALUES ("IS26_19","024_26_19","ISA","26","19","19","Amma matattunka za su rayu; jikunansu za su tashi. Ku da kuke zama a ƙura, ku farka ku kuma yi sowa don farin ciki. Raɓarka kamar raɓar safiya ce; duniya za tă haifi matattunta. ");
INSERT INTO hausa_vpl VALUES ("IS26_20","024_26_20","ISA","26","20","20","Ku tafi, mutanena, ku shiga ɗakunanku ku kuma kulle ƙofofi; ku ɓoye kanku na ɗan lokaci sai ya huce fushinsa. ");
INSERT INTO hausa_vpl VALUES ("IS26_21","024_26_21","ISA","26","21","21","Duba, Ubangiji yana fitowa daga mazauninsa don yă hukunta mutanen duniya saboda zunubansu. Duniya za tă bayyana zub da jinin da aka yi a kanta; ba za tă ƙara ɓoye waɗanda aka kashe a cikinta ba. ");
INSERT INTO hausa_vpl VALUES ("IS27_1","024_27_1","ISA","27","1","1","A wannan rana, Ubangiji zai yi hukunci da takobi, takobinsa mai tsanani, mai ƙarfi da kuma mai muguwar ɓarna, zai hukunta dodon ruwa macijin nan da ya kanannaɗe, dodon ruwa macijin nan mai murɗewa; zai kashe dodon nan na teku. ");
INSERT INTO hausa_vpl VALUES ("IS27_2","024_27_2","ISA","27","2","2","A wannan rana, “Ku rera game da gonar inabi mai ba da ’ya’ya ku ce ");
INSERT INTO hausa_vpl VALUES ("IS27_3","024_27_3","ISA","27","3","3","Ni, Ubangiji na lura da ita; na yi ta yin mata banruwa. Na yi tsaronta dare da rana don kada wani yă yi mata ɓarna. ");
INSERT INTO hausa_vpl VALUES ("IS27_4","024_27_4","ISA","27","4","4","Ban yi fushi ba. Da a ce ƙayayyuwa da sarƙaƙƙiya ne suke kalubalanta na mana! Zan fita in yi yaƙi da su; da na sa musu wuta duka. ");
INSERT INTO hausa_vpl VALUES ("IS27_5","024_27_5","ISA","27","5","5","Ko kuma bari su zo wurina don mafaka; bari su yi sulhu da ni, I, bari su yi sulhu da ni.” ");
INSERT INTO hausa_vpl VALUES ("IS27_6","024_27_6","ISA","27","6","6","A kwanaki masu zuwa Yaƙub zai yi saiwa, Isra’ila zai yi toho ya kuma yi fure ya cika dukan duniya da ’ya’ya. ");
INSERT INTO hausa_vpl VALUES ("IS27_7","024_27_7","ISA","27","7","7","Ubangiji ya buge shi kamar yadda ya bugi waɗanda suka buge shi? An kashe shi kamar yadda aka kashe waɗanda suka kashe shi? ");
INSERT INTO hausa_vpl VALUES ("IS27_8","024_27_8","ISA","27","8","8","Ta wurin yaƙi da zaman bauta ka hukunta shi, da tsananin tsawa kuma ka kore shi, kamar a ranar da iskar gabas ta hura. ");
INSERT INTO hausa_vpl VALUES ("IS27_9","024_27_9","ISA","27","9","9","A ta haka fa, za a yi kafarar laifin Yaƙub, wannan kuma zai zama cikakken amfanin kau da zunubinsa. Sa’ad da ya niƙa duwatsun bagade suka zama kamar allin da aka farfashe kucu-kucu, har ba sauran ginshiƙan Ashera ko bagadan ƙona turare da za a bari a tsaye. ");
INSERT INTO hausa_vpl VALUES ("IS27_10","024_27_10","ISA","27","10","10","Birni mai katanga ya zama kufai, yasasshen mazauni, an yashe shi kamar hamada; a can ’yan maruƙa suke kiwo, a can suke kwance; sun kakkaɓe rassanta ƙaf. ");
INSERT INTO hausa_vpl VALUES ("IS27_11","024_27_11","ISA","27","11","11","Sa’ad da rassanta suka bushe, sai su kakkarye su mata kuma su zo su yi itacen wuta da su. Gama mutane ne marar azanci; saboda haka Mahaliccinsu bai ji tausayinsu ba, Mahaliccinsu bai nuna musu jinƙai ba. ");
INSERT INTO hausa_vpl VALUES ("IS27_12","024_27_12","ISA","27","12","12","A wannan rana Ubangiji zai tankaɗe daga Yuferites mai gudu zuwa Rafin Masar, ku kuma, ya Isra’ilawa, za a tattara ku ɗaya-ɗaya. ");
INSERT INTO hausa_vpl VALUES ("IS27_13","024_27_13","ISA","27","13","13","Kuma a wannan rana zai busa ƙaho mai kāra sosai. Waɗanda suke mutuwa a Assuriya da kuma waɗanda aka kai zaman bauta a Masar za su zo su kuma yi wa Ubangiji sujada a dutse mai tsarki a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("IS28_1","024_28_1","ISA","28","1","1","Kaito ga wannan rawani, girman kai na mashayan Efraim, ga fure mai yanƙwanewa, darajar kyansa, da aka sa a kan kwari mai ba da amfani, ga birnin nan, wadda take girman kan waɗanda aka ƙasƙantar da ruwan inabinsu! ");
INSERT INTO hausa_vpl VALUES ("IS28_2","024_28_2","ISA","28","2","2","Duba, Ubangiji yana da wanda yake da iko da kuma ƙarfi. Kamar dutsen ƙanƙara da kuma iska mai ɓarna, kamar kwararowar ruwa da rigyawa mai kirmewa, zai jefa shi har ƙasa da ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("IS28_3","024_28_3","ISA","28","3","3","Za a tattaka wannan rawani, girman kai na mashayan Efraim da ƙafa. ");
INSERT INTO hausa_vpl VALUES ("IS28_4","024_28_4","ISA","28","4","4","Wannan fure mai yanƙwanewa, darajarar kyansa, da aka sa a kan kwari mai ba da amfani, zai zama kamar ’ya’yan ɓaure, nunan fari, da zarar wani ya gani ya kuma tsinka, zai haɗiye shi. ");
INSERT INTO hausa_vpl VALUES ("IS28_5","024_28_5","ISA","28","5","5","A wannan rana Ubangiji Maɗaukaki zai zama rawani mai daraja kyakkyawan rawani wa mutanensa da suka ragu. ");
INSERT INTO hausa_vpl VALUES ("IS28_6","024_28_6","ISA","28","6","6","Zai zama ruhun adalci gare shi wanda yake zaune a kujerar shari’a, wurin samun ƙarfi ga waɗanda suka kori abokan gāban da suka fāɗa musu da yaƙi a ƙofofi. ");
INSERT INTO hausa_vpl VALUES ("IS28_7","024_28_7","ISA","28","7","7","Da waɗannan kuma masu tangaɗi saboda sun sha ruwan inabi suke jiri don sun sha barasa Firistoci da annabawa suna tangaɗi saboda sun sha barasa sun kuma yi tatur da ruwan inabi; suna jiri saboda sun sha barasa, suna tangaɗi sa’ad da suke ganin wahayi, suna tuntuɓe sa’ad da suke ba da shawara. ");
INSERT INTO hausa_vpl VALUES ("IS28_8","024_28_8","ISA","28","8","8","Duk amai ya rufe teburori kuma babu wani wurin da ba a ɓata ba. ");
INSERT INTO hausa_vpl VALUES ("IS28_9","024_28_9","ISA","28","9","9","“Wane ne yake so ya koyar? Ga wa yake bayyana saƙonsa? Ga yaran da aka yaye, ga waɗanda ba a daɗe da yayewa ba ne? ");
INSERT INTO hausa_vpl VALUES ("IS28_10","024_28_10","ISA","28","10","10","Gama haka yake. Yi ka kuma yi, yi ka kuma yi, mulki a kan mulki, mulki a kan mulki; nan kaɗan, can kaɗan.” ");
INSERT INTO hausa_vpl VALUES ("IS28_11","024_28_11","ISA","28","11","11","To da kyau, da leɓunan baƙi da ku harsunan da ba sani ba Allah zai yi magana da wannan mutane, ");
INSERT INTO hausa_vpl VALUES ("IS28_12","024_28_12","ISA","28","12","12","waɗanda zai ce, “Wannan shi ne wurin hutu, bari waɗanda suka gaji su huta”; da kuma, “Wannan shi ne wurin wartsakewa” amma sun ƙi su saurara. ");
INSERT INTO hausa_vpl VALUES ("IS28_13","024_28_13","ISA","28","13","13","Saboda haka fa, maganar Ubangiji gare su za tă zama, Yi ka kuma yi, yi ka kuma yi, mulki akan mulki, mulki a kan mulki; nan kaɗan, can kaɗan, domin su tafi su kuma fāɗi da baya, su ji rauni a kuma kama su da tarko, a kai su zaman bauta. ");
INSERT INTO hausa_vpl VALUES ("IS28_14","024_28_14","ISA","28","14","14","Saboda haka ku saurari maganar Ubangiji, ku masu ba’a ku da kuke mulkin wannan mutane a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("IS28_15","024_28_15","ISA","28","15","15","Kuna fariya cewa, “Mun yi alkawari da mutuwa, mun kuma yi yarjejjeniya da kabari. Sa’ad da zafi ya ratsa, ba zai taɓa mu ba, gama mun mai da ƙarya mafakarmu ruɗu kuma wurin ɓuyanmu.” ");
INSERT INTO hausa_vpl VALUES ("IS28_16","024_28_16","ISA","28","16","16","Saboda haka ga abin da Ubangiji Mai Iko Duka ya ce, “Duba, na kafa dutse a Sihiyona, dutsen da aka gwada, dutsen kusurwa mai daraja don tabbataccen tushe; wanda ya dogara gare shi ba zai taɓa shan kunya ba. ");
INSERT INTO hausa_vpl VALUES ("IS28_17","024_28_17","ISA","28","17","17","Zan mai da gaskiya igiyar gwaji adalci kuma ɗan katakon gwajin ginin; ƙanƙara za tă share mafakarku, ƙarya, da ruwa kuma za su mamaye maɓuyanku. ");
INSERT INTO hausa_vpl VALUES ("IS28_18","024_28_18","ISA","28","18","18","Za a soke alkawarinku da mutuwa; yarjejjeniyarku da kabari ba zai zaunu ba. Sa’ad da zafi mai ɓarna ya ratsa, zai hallaka ku. ");
INSERT INTO hausa_vpl VALUES ("IS28_19","024_28_19","ISA","28","19","19","A duk sa’ad da ya zo; ko da safiya, ko dare ko kuma da rana, zai yi ta ratsawa yana kwasanku.” Za ku zama kamar mutumin da ya zama abin karin magana, ");
INSERT INTO hausa_vpl VALUES ("IS28_20","024_28_20","ISA","28","20","20","wanda ya yi ƙoƙari yă kwanta a gajeren gado, yă kuma rufa da ɗan siririn bargo. ");
INSERT INTO hausa_vpl VALUES ("IS28_21","024_28_21","ISA","28","21","21","Ubangiji zai tashi kamar yadda ya yi a Dutsen Feratsim, zai tā da kansa kamar a Kwarin Gibeyon don yă aikata aikinsa, aikinsa da ba a saba gani ba, yă kuma yi aikinsa, baƙon aikinsa. ");
INSERT INTO hausa_vpl VALUES ("IS28_22","024_28_22","ISA","28","22","22","Yanzu ku daina ba’arku, in ba haka ba sarƙoƙinku za su ƙara nauyi; Ubangiji, Ubangiji Maɗaukaki, ya faɗa mini game da hallakar da aka ƙaddara a kan dukan ƙasar. ");
INSERT INTO hausa_vpl VALUES ("IS28_23","024_28_23","ISA","28","23","23","Ku saurara ku kuma ji muryata; ku kasa kunne ku kuma ji abin da na faɗa. ");
INSERT INTO hausa_vpl VALUES ("IS28_24","024_28_24","ISA","28","24","24","Sa’ad da manomi ya yi noma don shuki, yakan ci gaba da noma ne? Yakan ci gaba da sara yana yin kunyoyi a ƙasa ne? ");
INSERT INTO hausa_vpl VALUES ("IS28_25","024_28_25","ISA","28","25","25","Sa’ad da ya shirya wuri da kyau, ba yakan shuka kanumfari ya kuma yayyafa ɗaɗɗoya ba? Ba yakan shuka alkama a kunyoyinsa sha’ir a kunyoyinsa, tamba kuma a filinsa ba? ");
INSERT INTO hausa_vpl VALUES ("IS28_26","024_28_26","ISA","28","26","26","Allahnsa ya umarce shi ya kuma koya masa hanyar da take daidai. ");
INSERT INTO hausa_vpl VALUES ("IS28_27","024_28_27","ISA","28","27","27","Ba a bugan kanumfari da ƙaton sanda ko a yi ta jujjuye ƙafar keke a kan ɗaɗɗoya; akan buga kanumfari da siririn sanda ɗaɗɗoya kuma da tsumagiya. ");
INSERT INTO hausa_vpl VALUES ("IS28_28","024_28_28","ISA","28","28","28","Dole a niƙa hatsi don a yi burodi; saboda haka mutum ba zai yi ta bugun alkama, har yă ɓata tsabar ba. Ya san yadda zai sussuke alkamarsa, ba tare da ya ɓata tsabarta ba. ");
INSERT INTO hausa_vpl VALUES ("IS28_29","024_28_29","ISA","28","29","29","Dukan wannan hikimar takan zo daga Ubangiji Maɗaukaki ne, shi da yake mashawarci mai banmamaki, mafifici kuma cikin hikima. ");
INSERT INTO hausa_vpl VALUES ("IS29_1","024_29_1","ISA","29","1","1","Kaitonki, Ariyel, Ariyel birnin da Dawuda ya zauna! Ƙara shekara ga shekara a kuma bar shagulgulanki su yi ta kewayewa. ");
INSERT INTO hausa_vpl VALUES ("IS29_2","024_29_2","ISA","29","2","2","Duk da haka zan yi wa Ariyel kwanto za tă kuma yi kuka da makoki, za tă zama mini kamar bagaden jini. ");
INSERT INTO hausa_vpl VALUES ("IS29_3","024_29_3","ISA","29","3","3","Zan kafa sansani kewaye da ke duka; zan kewaye ki da hasumiyoyi in tasar miki da ayyukan kwantona na yaƙi. ");
INSERT INTO hausa_vpl VALUES ("IS29_4","024_29_4","ISA","29","4","4","Za a ƙasƙantar da ke, za ki ƙi yin magana daga ƙasa; maganarki za tă yi ƙasa-ƙasa daga ƙura. Muryarki za tă zama kamar fatalwa daga ƙasa; daga ƙura maganarki zai fito ƙasa-ƙasa. ");
INSERT INTO hausa_vpl VALUES ("IS29_5","024_29_5","ISA","29","5","5","Amma abokan gābanki masu yawa za su zama kamar ƙura mai laushi, sojojinsu masu firgitarwa za su yi ta tashi kamar yayin da iska ta hura. Farat ɗaya, cikin ɗan lokaci, ");
INSERT INTO hausa_vpl VALUES ("IS29_6","024_29_6","ISA","29","6","6","Ubangiji Maɗaukaki zai zo da tsawa da rawar ƙasa da ƙara mai girma, da hadarin iska da guguwa da harshe na wuta mai ci. ");
INSERT INTO hausa_vpl VALUES ("IS29_7","024_29_7","ISA","29","7","7","Sa’an nan sojojin dukan al’umman da suka yi yaƙi da Ariyel, da suka fāɗa mata da kagararta suka kuma yi mata kwanto, za su zama kamar yadda yake da mafarki, wahayi da dare, ");
INSERT INTO hausa_vpl VALUES ("IS29_8","024_29_8","ISA","29","8","8","kamar sa’ad da mai yunwa yana mafarki cewa yana cin abinci, amma sai ya farka, yunwan tana nan; kamar sa’ad da mai ƙishirwa yana mafarki cewa yana shan ruwa, amma sai ya farka yana suma, da ƙishinsa. Haka zai zama da sojoji na dukan al’ummai da suka yi yaƙi da Dutsen Sihiyona. ");
INSERT INTO hausa_vpl VALUES ("IS29_9","024_29_9","ISA","29","9","9","Ku firgita ku kuma yi mamaki, ku makance kanku ku kuma zama a makance; ku bugu, amma ba da ruwan inabi ba, ku yi tangaɗi, amma ba daga barasa ba. ");
INSERT INTO hausa_vpl VALUES ("IS29_10","024_29_10","ISA","29","10","10","Ubangiji ya kawo muku barci mai nauyi, Ya rufe idanunku (annabawa); ya rufe kawunanku (masu duba). ");
INSERT INTO hausa_vpl VALUES ("IS29_11","024_29_11","ISA","29","11","11","Gare ku duk wannan wahayi ba kome ba ne sai dai maganganun da aka rufe a cikin littafi. In kuma kun ba da littafin ga wani wanda zai iya karanta, kuka kuma ce masa, “Karanta wannan, muna roƙonka,” zai amsa ya ce, “Ba zan iya ba; an rufe shi.” ");
INSERT INTO hausa_vpl VALUES ("IS29_12","024_29_12","ISA","29","12","12","Ko kuwa in kun ba da littafin ga wani wanda ba zai iya karantawa ba, kuka kuma ce, “Karanta wannan, muna roƙonka,” zai amsa ya ce, “Ban iya karatu ba.” ");
INSERT INTO hausa_vpl VALUES ("IS29_13","024_29_13","ISA","29","13","13","Ubangiji ya ce, “Waɗannan mutane sun zo kusa da ni da bakinsu suka kuma girmama ni da leɓunansu, amma zukatansu suna nesa daga gare ni. Sujadar da suke mini cike take da dokokin da mutane suka koyar. ");
INSERT INTO hausa_vpl VALUES ("IS29_14","024_29_14","ISA","29","14","14","Saboda haka zan firgita waɗannan mutane sau ɗaya da abubuwan banmamaki a kan abubuwan banmamaki; hikimar masu hikima za tă lalace, azancin masu azanci zai ɓace.” ");
INSERT INTO hausa_vpl VALUES ("IS29_15","024_29_15","ISA","29","15","15","Kaiton waɗanda suke zuwa manyan zurfafa don su ɓoye shirye-shiryensu daga Ubangiji, waɗanda suke aikinsu cikin duhu su yi tunani, “Wa yake ganinmu? Wa zai sani?” ");
INSERT INTO hausa_vpl VALUES ("IS29_16","024_29_16","ISA","29","16","16","Kuna birkitar abubuwa, sai ka ce an mayar da mai ginin tukwane ya zama yumɓu! Abin da aka yi zai ce wa wanda ya yi shi, “Ba shi ne ya yi ni ba”? Tukunya za tă iya ce wa mai ginin tukwane, “Ba ka san kome ba”? ");
INSERT INTO hausa_vpl VALUES ("IS29_17","024_29_17","ISA","29","17","17","Cikin ɗan lokaci, za a mai da Lebanon gona mai taƙi kuma gona mai taƙi za tă zama kamar kurmi? ");
INSERT INTO hausa_vpl VALUES ("IS29_18","024_29_18","ISA","29","18","18","A wannan rana kurame za su ji maganganun littafi, daga duruduru da duhu kuma idanun makafi za su gani. ");
INSERT INTO hausa_vpl VALUES ("IS29_19","024_29_19","ISA","29","19","19","Masu tawali’u za su sāke yin farin ciki a cikin Ubangiji; mabukata za su yi farin ciki cikin Mai Tsarkin nan na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS29_20","024_29_20","ISA","29","20","20","Masu zalunci za su ƙare, masu ba’a za su ɓace, kuma dukan waɗanda suke da ido don mugunta za su hallaka, ");
INSERT INTO hausa_vpl VALUES ("IS29_21","024_29_21","ISA","29","21","21","waɗanda ta magana kawai sukan mai da mutum mai laifi, waɗanda suke kafa tarko wa mai ba da kāriya a ɗakin shari’a da shaidar ƙarya kuma su hana marar laifi samun shari’ar adalci. ");
INSERT INTO hausa_vpl VALUES ("IS29_22","024_29_22","ISA","29","22","22","Saboda haka ga abin da Ubangiji wanda ya fanshi Ibrahim, ya ce wa gidan Yaƙub, “Ba za a ƙara kunyata Yaƙub ba; fuskokinsu kuma ba za su ƙara yanƙwanewa ba. ");
INSERT INTO hausa_vpl VALUES ("IS29_23","024_29_23","ISA","29","23","23","Sa’ad da suka ga ’ya’yansu a tsakiyarsu, aikin hannuwansu, za su kiyaye sunana da tsarki; za su san tsarkin Mai Tsarkin nan na Yaƙub, za su kuma ji tsoron Allah na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS29_24","024_29_24","ISA","29","24","24","Su da suke marasa azanci a ruhu za su sami fahimtar; waɗanda suke gunaguni za su yarda da koyarwa.” ");
INSERT INTO hausa_vpl VALUES ("IS30_1","024_30_1","ISA","30","1","1","“Kaiton ’ya’ya masu tayarwa,” in ji Ubangiji, “ga waɗanda suke ƙulle-ƙullen da ba nawa ba, suna yin yarjejjeniya, amma ba ta Ruhuna ba, suna jibga zunubi a kan zunubi; ");
INSERT INTO hausa_vpl VALUES ("IS30_2","024_30_2","ISA","30","2","2","waɗanda suka gangara zuwa Masar ba tare da sun nemi shawarata; waɗanda suke neman taimakon kāriyar Fir’auna, don neman inuwar mafakar Masar. ");
INSERT INTO hausa_vpl VALUES ("IS30_3","024_30_3","ISA","30","3","3","Amma kāriyar Fir’auna za tă zama muku abin kunya, inuwar Masar za tă jawo muku kunya. ");
INSERT INTO hausa_vpl VALUES ("IS30_4","024_30_4","ISA","30","4","4","Ko da yake suna da shugabanni a Zowan kuma jakadunsu sun iso Hanes, ");
INSERT INTO hausa_vpl VALUES ("IS30_5","024_30_5","ISA","30","5","5","kowa zai sha kunya saboda mutanen da ba su da amfani gare su, waɗanda ba sa taimako ko amfani, sai dai jawo kunya da da-na-sani.” ");
INSERT INTO hausa_vpl VALUES ("IS30_6","024_30_6","ISA","30","6","6","Allah ya faɗa game da dabbobin Negeb cewa, Ta cikin ƙasa mai wahala da mai hatsari inda zakoki da zakanya, inda macizai masu dafi da macizai masu tashi sama suke, jakadu na ɗaukan arzikinsu a kan jakuna, dukiyarsu a kan raƙuma, zuwa ƙasan nan marar riba, ");
INSERT INTO hausa_vpl VALUES ("IS30_7","024_30_7","ISA","30","7","7","zuwa Masar, wadda taimakonta marar amfani ne. Saboda haka na yi mata laƙabi Rahab Marar Yin Kome. ");
INSERT INTO hausa_vpl VALUES ("IS30_8","024_30_8","ISA","30","8","8","Tafi yanzu, ka rubuta musu a kan allo, ka rubuta shi a kan littafi, cewa kwanaki suna zuwa zai zama madawwamin shaida. ");
INSERT INTO hausa_vpl VALUES ("IS30_9","024_30_9","ISA","30","9","9","Waɗannan mutane masu tawaye, ’ya’ya masu ruɗu, ’ya’yan da ba sa niyya su saurara ga umarnan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS30_10","024_30_10","ISA","30","10","10","Sukan ce wa masu gani, “Kada ku ƙara ganin wahayi!” Ga annabawa kuwa sukan ce, “Kada ku ƙara ba mu wahayin abin da yake daidai! Faɗa mana abubuwan da muke so mu ji ne kawai, ku yi annabcin abin da zai ruɗe mu. ");
INSERT INTO hausa_vpl VALUES ("IS30_11","024_30_11","ISA","30","11","11","Ku bar wannan hanya, ku tashi daga wannan hanya, ku kuma daina kalubalantarmu da Mai Tsarkin nan na Isra’ila!” ");
INSERT INTO hausa_vpl VALUES ("IS30_12","024_30_12","ISA","30","12","12","Saboda haka, ga abin da Mai Tsarkin nan na Isra’ila yake cewa, “Saboda haka kun ƙi wannan saƙo, kuka dogara ga aikin kama-karya kuka kuma dogara ga yin ruɗu, ");
INSERT INTO hausa_vpl VALUES ("IS30_13","024_30_13","ISA","30","13","13","wannan zunubi zai zama muku kamar bango mai tsayi, tsagagge da yake kuma fāɗuwa, da zai rushe nan da nan, ba tsammani. ");
INSERT INTO hausa_vpl VALUES ("IS30_14","024_30_14","ISA","30","14","14","Zai rushe kucu-kucu kamar tukunyar yumɓu, ya ragargaje ƙaf har cikin gutsattsarinsa ba za a sami ko ɗan katanga don ɗiba garwashin wuta ko a ɗiba ruwa daga tanki ba.” ");
INSERT INTO hausa_vpl VALUES ("IS30_15","024_30_15","ISA","30","15","15","Ga abin da Ubangiji Mai Iko Duka, Mai Tsarkin nan na Isra’ila ya faɗa, “Cikin tuba da hutu ne kaɗai cetonku yake, cikin shiru da dogara gare ni ne za ku sami ƙarfinku, amma ba za ku sami ko ɗaya a cikinsu ba. ");
INSERT INTO hausa_vpl VALUES ("IS30_16","024_30_16","ISA","30","16","16","Kun ce, ‘A’a, za mu gudu a kan dawakai.’ Saboda haka za ku gudu! Kun ce, ‘Za mu hau dawakai masu sauri mu gudu.’ Saboda haka masu fafararku za su fi ku gudu! ");
INSERT INTO hausa_vpl VALUES ("IS30_17","024_30_17","ISA","30","17","17","Dubu za su gudu don barazanar mutum guda; da jin barazanar mutane biyar dukanku za ku yi ta gudu sai an bar ku kamar sandar tuta a kan dutse, kamar tuta a kan tudu.” ");
INSERT INTO hausa_vpl VALUES ("IS30_18","024_30_18","ISA","30","18","18","Duk da haka Ubangiji yana marmari ya yi muku alheri; ya tashi don yă nuna muku jinƙai. Gama Ubangiji Allah ne mai aikata gaskiya. Masu albarka ne dukanku waɗanda suke dogara gare shi! ");
INSERT INTO hausa_vpl VALUES ("IS30_19","024_30_19","ISA","30","19","19","Ya mutanen Sihiyona, waɗanda suke zama a Urushalima, ba za ku ƙara kuka ba. Zai zama mai alheri sa’ad da kuka yi kukan neman taimako! Da zarar ya ji, zai amsa muku. ");
INSERT INTO hausa_vpl VALUES ("IS30_20","024_30_20","ISA","30","20","20","Ko da yake Ubangiji yakan ba da abincin azaba da ruwan wahala, ba za a ƙara ɓoye malamanku ba; da idanunku za ku gan su. ");
INSERT INTO hausa_vpl VALUES ("IS30_21","024_30_21","ISA","30","21","21","Ko kun juye dama ko hagu, kunnuwanku za su ji murya a bayanku tana cewa, “Ga hanya; ku yi tafiya a kai.” ");
INSERT INTO hausa_vpl VALUES ("IS30_22","024_30_22","ISA","30","22","22","Sa’an nan za ku ƙazantar da gumakanku da kuka dalaye da zinariya; za ku zubar da su kamar rigar al’adar mace ku kuma ce musu, “Ku ɓace mana da gani!” ");
INSERT INTO hausa_vpl VALUES ("IS30_23","024_30_23","ISA","30","23","23","Zai kuma aiko muku da ruwan sama don shuki a ƙasa, kuma abincin da zai fito daga gona zai zama mai albarka da kuma mai yawa. A wannan rana shanu za su yi kiwo a wadatacciyar makiyaya. ");
INSERT INTO hausa_vpl VALUES ("IS30_24","024_30_24","ISA","30","24","24","Shanunku da jakunanku da suke huɗar gonakinku za su ci harawa mafi kyau, wanda an sheƙe shi da babban cokali mai yatsu da kuma babban cokali. ");
INSERT INTO hausa_vpl VALUES ("IS30_25","024_30_25","ISA","30","25","25","A ranar babban kisa, sa’ad da hasumiyoyi za su fāɗi, rafuffukan ruwa za su malalo a kan kowane dutse da kowane tudu mai tsawo. ");
INSERT INTO hausa_vpl VALUES ("IS30_26","024_30_26","ISA","30","26","26","Wata zai yi haske kamar rana, kuma hasken rana zai ma yi sau bakwai na haskenta, kamar hasken cikakku ranaku bakwai, sa’ad da Ubangiji zai ɗaura raunukan mutanensa ya kuma warkar da raunukan da ya yi musu. ");
INSERT INTO hausa_vpl VALUES ("IS30_27","024_30_27","ISA","30","27","27","Duba, Sunan Ubangiji yana zuwa daga nesa, tare da fushi mai ƙuna da kuma baƙin hayaƙi; leɓunansa sun cika da fushi, harshensa kuma wuta ce mai cinyewa. ");
INSERT INTO hausa_vpl VALUES ("IS30_28","024_30_28","ISA","30","28","28","Numfashinsa kamar raƙuman ruwa masu gudu yana tashi har zuwa wuya. Yakan tankaɗe al’ummai cikin lariyar hallaka; yakan sa a muƙamuƙan mutane linzamin da zai jagorance su su kauce. ");
INSERT INTO hausa_vpl VALUES ("IS30_29","024_30_29","ISA","30","29","29","Za ku kuma rera kamar a daren da kuke shagalin biki mai tsarki; zukatanku za su yi farin ciki kamar sa’ad da mutane sukan haura da busa zuwa dutsen Ubangiji, zuwa Dutse na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS30_30","024_30_30","ISA","30","30","30","Ubangiji zai sa mutane su ji muryarsa mai daraja ya kuma sa su ga hannunsa na saukowa tare da fushi mai ƙuna da kuma wuta mai cinyewa, gizagizai za su ɓarke, za a yi hadarin tsawa da ƙanƙara. ");
INSERT INTO hausa_vpl VALUES ("IS30_31","024_30_31","ISA","30","31","31","Muryar Ubangiji za tă firgita Assuriya da sandar mulkinsa zai kashe su. ");
INSERT INTO hausa_vpl VALUES ("IS30_32","024_30_32","ISA","30","32","32","Kowane bugun da Ubangiji zai yi musu da bulalarsa na hukunci zai zama kiɗi ga ganguna da garaya, yayinda yake yaƙi da su da naushin hannunsa. ");
INSERT INTO hausa_vpl VALUES ("IS30_33","024_30_33","ISA","30","33","33","An riga an shirya wurin ƙonawa; an shirya shi saboda sarki. An haƙa ramin wutarsa da zurfi da kuma fāɗi, da isashen wuta da itacen wuta; numfashin Ubangiji, yana kamar kibiritu mai ƙuna, da aka sa masa wuta. ");
INSERT INTO hausa_vpl VALUES ("IS31_1","024_31_1","ISA","31","1","1","Kaiton waɗanda suka gangara zuwa Masar don neman taimako, waɗanda suke dogara ga dawakai, waɗanda suke dogara ga yawan kekunan yaƙinsu da kuma a girman ƙarfin mahayan dawakansu, amma ba sa dogara ga Mai Tsarkin nan na Isra’ila, ko ya nemi taimako daga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS31_2","024_31_2","ISA","31","2","2","Shi ma yana da hikima kuma zai iya kawo masifa; ba ya janye kalmominsa. Zai yi gāba da gidan mugu, gāba da waɗanda suke taimakon masu aikata mugunta. ");
INSERT INTO hausa_vpl VALUES ("IS31_3","024_31_3","ISA","31","3","3","Amma Masarawa mutane ne ba Allah ba; dawakansu nama da jini ne ba ruhu ba. Sa’ad da Ubangiji ya miƙa hannunsa, shi da yake taimako zai yi tuntuɓe shi da aka taimaka zai fāɗi; dukansu biyu za su hallaka tare. ");
INSERT INTO hausa_vpl VALUES ("IS31_4","024_31_4","ISA","31","4","4","Ga abin da Ubangiji ya faɗa mini, “Kamar yadda zaki kan yi ruri babban zaki a kan abin da ya yi farauta, kuma ko da yake dukan ƙungiyar makiyaya sun taru wuri ɗaya a kansa, ba zai jijjigu ta wurin ihunsu ba ko ya damu da kiraye-kirayensu, ta haka Ubangiji Maɗaukaki zai sauko don yă yi yaƙi a kan Dutsen Sihiyona da kuma a kan ƙwanƙolinsa. ");
INSERT INTO hausa_vpl VALUES ("IS31_5","024_31_5","ISA","31","5","5","Kamar tsuntsaye masu shawagi a sama haka Ubangiji Maɗaukaki zai kiyaye Urushalima; zai kāre ta ya kuma fanshe ta, zai ‘ƙetare’ ta ya kuma kuɓutar da ita.” ");
INSERT INTO hausa_vpl VALUES ("IS31_6","024_31_6","ISA","31","6","6","Ku dawo gare shi ku da kuka yi masa babban tayarwa, ya Isra’ilawa. ");
INSERT INTO hausa_vpl VALUES ("IS31_7","024_31_7","ISA","31","7","7","Gama a wannan rana kowannenku zai ƙi gumakan azurfa da zinariya da hannuwanku masu zunubi suka yi. ");
INSERT INTO hausa_vpl VALUES ("IS31_8","024_31_8","ISA","31","8","8","“Za a karkashe Assuriyawa da takobin da ba na yin mutum ba; takobi, da ba na yin mutum ba, zai cinye. Za su gudu daga takobi za a kuma sa samarinsu aikin dole. ");
INSERT INTO hausa_vpl VALUES ("IS31_9","024_31_9","ISA","31","9","9","Kagararsu za tă fāɗi saboda razana; da ganin matsayin yaƙin, shugabannin yaƙinsu za su firgita,” in ji Ubangiji, wanda wutarsa tana a Sihiyona, wanda matoyarsa tana a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("IS32_1","024_32_1","ISA","32","1","1","Duba, sarki zai yi mulki cikin adalci masu mulki kuma su yi mulki da adalci. ");
INSERT INTO hausa_vpl VALUES ("IS32_2","024_32_2","ISA","32","2","2","Kowane mutum zai zama kamar wurin fakewa daga iska mafaka kuma daga hadari, kamar rafuffukan ruwa a hamada da kuma inuwar babban dutse a ƙeƙasasshiyar ƙasa. ");
INSERT INTO hausa_vpl VALUES ("IS32_3","024_32_3","ISA","32","3","3","Sa’an nan idanun waɗanda suka gani ba za su ƙara rufewa ba, kunnuwan waɗanda suka ji kuma za su saurara. ");
INSERT INTO hausa_vpl VALUES ("IS32_4","024_32_4","ISA","32","4","4","Zuciya marasa haƙuri za su sani su kuma fahimta, harshen masu ana’ana kuma zai sāke su yi magana sosai. ");
INSERT INTO hausa_vpl VALUES ("IS32_5","024_32_5","ISA","32","5","5","Ba za a ƙara ce da wawa mai girma ba ko kuwa a ɗaukaka mazambaci. ");
INSERT INTO hausa_vpl VALUES ("IS32_6","024_32_6","ISA","32","6","6","Gama wawa maganar wauta yakan yi, zuciyarsa ta cika da mugunta, yana aikata abubuwan rashin sanin Allah yana baza kurakurai game da Ubangiji; yana barin mayunwata da yunwa ya kuma hana masu ƙishirwa ruwan sha. ");
INSERT INTO hausa_vpl VALUES ("IS32_7","024_32_7","ISA","32","7","7","Matakan mazambaci mugaye ne, yana ƙulla mugayen shirye-shirye don yă hallaka talakawa da ƙarairayi, ko sa’ad da roƙon mai bukata da gaskiya ne. ");
INSERT INTO hausa_vpl VALUES ("IS32_8","024_32_8","ISA","32","8","8","Amma mutumin kirki kan yi shirye-shirye masu kirki, kuma yakan tsaya a kan ayyukan kirki. ");
INSERT INTO hausa_vpl VALUES ("IS32_9","024_32_9","ISA","32","9","9","Ku matan da kuke zaman jin daɗi, ku tashi ku saurare ni; ku ’yan matan da kuke tsammani kuna da kāriya, ku ji abin da zan faɗa! ");
INSERT INTO hausa_vpl VALUES ("IS32_10","024_32_10","ISA","32","10","10","Cikin ɗan lokaci ƙasa da shekara guda ku da kuke tsammani kuna da kāriya za ku yi rawar jiki; girbin ’ya’yan inabi zai kāsa, girbin ’ya’yan itatuwa kuma ba zai zo ba. ");
INSERT INTO hausa_vpl VALUES ("IS32_11","024_32_11","ISA","32","11","11","Ku yi rawar jiki, ku mata masu jin daɗi, ku sha wahala, ku ’yan matan da kuke tsammani kuna da kāriya! Ku tuɓe rigunanku, ku ɗaura tsummoki a kwankwasonku. ");
INSERT INTO hausa_vpl VALUES ("IS32_12","024_32_12","ISA","32","12","12","Ku bugi ƙirjinku don gonaki masu kyau don ’ya’yan inabi ");
INSERT INTO hausa_vpl VALUES ("IS32_13","024_32_13","ISA","32","13","13","da kuma don ƙasar mutanena, da ƙasar da ƙayayyuwa da sarƙaƙƙiya ne suka yi girma, I, ku yi kuka saboda dukan gidajen da dā ake biki da kuma domin wannan birnin da dā ake murna a ciki. ");
INSERT INTO hausa_vpl VALUES ("IS32_14","024_32_14","ISA","32","14","14","Za a ƙyale kagarar, a gudu a bar birnin da dā ake hayaniya; mafaka da hasumiyar tsaro za su zama kango har abada, jin daɗin jakuna, makiyaya don garkuna, ");
INSERT INTO hausa_vpl VALUES ("IS32_15","024_32_15","ISA","32","15","15","sai an zubo Ruhu a kanmu daga sama, hamada kuma ta zama ƙasar mai taƙi, gona mai taƙi kuma ta zama kamar kurmi. ");
INSERT INTO hausa_vpl VALUES ("IS32_16","024_32_16","ISA","32","16","16","Aikin gaskiya zai zauna a hamada adalci kuma zai zauna a ƙasa mai taƙi. ");
INSERT INTO hausa_vpl VALUES ("IS32_17","024_32_17","ISA","32","17","17","Aikin adalci zai zama salama; tasirin adalci zai zama natsuwa da tabbaci har abada. ");
INSERT INTO hausa_vpl VALUES ("IS32_18","024_32_18","ISA","32","18","18","Mutanena za su zauna lafiya a wuraren salama, a gidaje masu kāriya, a wuraren hutun da babu fitina. ");
INSERT INTO hausa_vpl VALUES ("IS32_19","024_32_19","ISA","32","19","19","Ko da yake ƙanƙara za tă fāɗo a jeji, a kuma rurrushe birni gaba ɗaya, ");
INSERT INTO hausa_vpl VALUES ("IS32_20","024_32_20","ISA","32","20","20","zai zama muku da albarka, ku da kuke shuki iri kusa da kowane rafi, kuna kuma barin lafiyayyiyar makiyaya domin shanu da jakunanku. ");
INSERT INTO hausa_vpl VALUES ("IS33_1","024_33_1","ISA","33","1","1","Kaitonka, ya kai mai hallakarwa, kai da ba a hallakar da kai ba! Kaitonka, ya maciya amana, kai da ba a ci amanarka ba! Sa’ad da ka daina hallakarwa, za a hallaka ka; sa’ad da ka daina cin amana, za a ci amanarka. ");
INSERT INTO hausa_vpl VALUES ("IS33_2","024_33_2","ISA","33","2","2","Ya Ubangiji, ka yi mana jinƙai; muna marmarinka. Ka zama ƙarfinmu kowace safiya, cetonmu a lokacin damuwa. ");
INSERT INTO hausa_vpl VALUES ("IS33_3","024_33_3","ISA","33","3","3","Da tsawar muryarka, mutane za su gudu; sa’ad da ka tashi, al’ummai za su watse. ");
INSERT INTO hausa_vpl VALUES ("IS33_4","024_33_4","ISA","33","4","4","Ganimarku, ya al’ummai ƙanana fāri sun girbe; kamar tarin fārin da mutane sun fāɗa wa. ");
INSERT INTO hausa_vpl VALUES ("IS33_5","024_33_5","ISA","33","5","5","Ubangiji da girma yake, gama yana zaune a bisa; zai cika Sihiyona cikin gaskiya da adalci. ");
INSERT INTO hausa_vpl VALUES ("IS33_6","024_33_6","ISA","33","6","6","Zai zama tabbataccen harsashi na koyaushe, ma’ajin ceto da hikima da sani a yalwace; tsoron Ubangiji shi ne mabuɗin wannan dukiya. ");
INSERT INTO hausa_vpl VALUES ("IS33_7","024_33_7","ISA","33","7","7","Duba, jarumawansu suna kuka da ƙarfi a tituna; jakadun salama suna kuka mai zafi. ");
INSERT INTO hausa_vpl VALUES ("IS33_8","024_33_8","ISA","33","8","8","An gudu an bar manyan hanyoyi, babu matafiye a kan hanyoyi. Aka keta yarjejjeniya, an rena shaidunsa ba a kuwa ganin girman kowa. ");
INSERT INTO hausa_vpl VALUES ("IS33_9","024_33_9","ISA","33","9","9","Ƙasa tana kuka an kuma gudu an bar ta, Lebanon ta sha kunya ta kuma yanƙwane; Sharon ta zama kamar Araba, Bashan da Karmel sun kakkaɓe ganyayensu. ");
INSERT INTO hausa_vpl VALUES ("IS33_10","024_33_10","ISA","33","10","10","“Yanzu zan tashi,” in ji Ubangiji. “Yanzu ne za a ɗaukaka ni; yanzu za a ɗaga ni sama. ");
INSERT INTO hausa_vpl VALUES ("IS33_11","024_33_11","ISA","33","11","11","Kun yi cikin yayi, kuka haifi kara; numfashinku wuta ne da zai cinye ku. ");
INSERT INTO hausa_vpl VALUES ("IS33_12","024_33_12","ISA","33","12","12","Za a ƙone mutane kamar da ƙuna farar ƙasa; kamar ƙayayyuwan da aka sare aka kuma sa musu wuta.” ");
INSERT INTO hausa_vpl VALUES ("IS33_13","024_33_13","ISA","33","13","13","Ku da kuke da nesa, ku ji abin da na yi; ku da kuke kusa, ku san ikona! ");
INSERT INTO hausa_vpl VALUES ("IS33_14","024_33_14","ISA","33","14","14","Masu zunubi a Sihiyona sun firgita; rawar jiki ya kama marasa sanin Allah suna cewa, “Wane ne a cikinmu zai iya zama da wuta mai ci? Wane ne a cikinmu zai iya zama da madawwamiyar ƙonewa?” ");
INSERT INTO hausa_vpl VALUES ("IS33_15","024_33_15","ISA","33","15","15","Shi da yake tafiya cikin adalci yana kuma magana abin da yake daidai, wanda yake ƙin riba daga cuta yana kuma kiyaye hannunsa daga karɓan cin hanci, wanda yake hana kunnuwansa daga ƙulla kisa ya kuma rufe idanunsa a kan tunanin aikata mugunta, ");
INSERT INTO hausa_vpl VALUES ("IS33_16","024_33_16","ISA","33","16","16","shi ne mutumin da zai zauna a bisa, wanda mafakarsa za tă zama kagarar dutse. Za a tanada abincinsa, kuma ruwa ba zai kāsa masa ba. ");
INSERT INTO hausa_vpl VALUES ("IS33_17","024_33_17","ISA","33","17","17","Idanunku za su ga sarki a cikin kyansa ku kuma hangi ƙasar da take shimfiɗe can da nisa. ");
INSERT INTO hausa_vpl VALUES ("IS33_18","024_33_18","ISA","33","18","18","Cikin tunaninku za ku yi tunani firgitar da ta faru tun dā kuna cewa, “Ina hafsan nan? Ina wannan wanda yake karɓar haraji? Ina hafsan da yake lura da hasumiyoyi?” ");
INSERT INTO hausa_vpl VALUES ("IS33_19","024_33_19","ISA","33","19","19","Ba za ku ƙara ganin waɗannan mutane masu girman kai kuma ba, waɗannan mutane masu magana da harshen da ba ku fahimta ba. ");
INSERT INTO hausa_vpl VALUES ("IS33_20","024_33_20","ISA","33","20","20","Ku duba Sihiyona, birnin shagulgulanmu; idanunku za su ga Urushalima, mazauni mai lafiya, tentin da ba za a taɓa gusar ba; wanda ba a taɓa tumɓuke turakunsa ba, ko a tsinke igiyoyinta. ");
INSERT INTO hausa_vpl VALUES ("IS33_21","024_33_21","ISA","33","21","21","A can Ubangiji zai zama Mai Iko Duka namu. Zai zama kamar inda manyan koguna da rafuffuka suke. Matuƙan jirgin ruwa ba za su kai wurinsu ba, manyan jiragen ruwa ba za su yi zirga-zirga a kansu ba. ");
INSERT INTO hausa_vpl VALUES ("IS33_22","024_33_22","ISA","33","22","22","Gama Ubangiji ne alƙalinmu, Ubangiji ne mai ba mu dokoki, Ubangiji ne sarkinmu; shi ne wanda zai cece mu. ");
INSERT INTO hausa_vpl VALUES ("IS33_23","024_33_23","ISA","33","23","23","Maɗaurinku sun kunce ƙarfafan itacen jirgin ba su da kāriya, fikafikan jirgin ba su buɗu ba. Ta haka za a raba yalwar ganima har ma guragu za su kwashe ganimar. ");
INSERT INTO hausa_vpl VALUES ("IS33_24","024_33_24","ISA","33","24","24","Ba wani mazauna a Sihiyona da zai ce, “Ina ciwo”; za a kuma gafarta zunuban waɗanda suke zama a can. ");
INSERT INTO hausa_vpl VALUES ("IS34_1","024_34_1","ISA","34","1","1","Ku zo kusa, ku al’ummai, ku kuwa saurara ku kasa kunne, ku mutane! Bari duniya ta ji, da kuma dukan abin da yake cikinta, duniya, da dukan abin da yake fitowa daga gare ta! ");
INSERT INTO hausa_vpl VALUES ("IS34_2","024_34_2","ISA","34","2","2","Ubangiji yana fushi da dukan al’ummai; hasalarsa tana a kan mayaƙansu. Zai hallaka su tas, zai ba da su a karkashe. ");
INSERT INTO hausa_vpl VALUES ("IS34_3","024_34_3","ISA","34","3","3","Za a jefar da waɗanda aka kashe gawawwakinsu za su yi wari; duwatsu za su jiƙu da jininsu. ");
INSERT INTO hausa_vpl VALUES ("IS34_4","024_34_4","ISA","34","4","4","Za a tumɓuke dukan taurarin sammai za a kuma nannaɗe sararin sama kamar littafi; dukan rundunar sama za su fāffāɗi kamar ganyayen da suka yanƙwane daga kuringa, kamar ’ya’yan ɓauren da suka bushe daga itacen ɓaure. ");
INSERT INTO hausa_vpl VALUES ("IS34_5","024_34_5","ISA","34","5","5","Takobina ya sha zararsa a cikin sammai; duba, ya sauko cikin hukunci a kan Edom, mutanen da zan hallaka tas. ");
INSERT INTO hausa_vpl VALUES ("IS34_6","024_34_6","ISA","34","6","6","Takobin Ubangiji ya jiƙu da jini, ya rufu da kitse, jinin raguna da na awaki, kitse daga ƙodar raguna. Gama Ubangiji ya yi hadayar Bozra da kuma babban kisa a Edom. ");
INSERT INTO hausa_vpl VALUES ("IS34_7","024_34_7","ISA","34","7","7","Babban bijimin jeji zai fāɗi tare da su, maruƙan bijimi da manyan bijimai. Ƙasarsu za tă cika da jini, ƙura kuma zai cika da kitse. ");
INSERT INTO hausa_vpl VALUES ("IS34_8","024_34_8","ISA","34","8","8","Gama Ubangiji yana da ranar ɗaukar fansa, shekarar ramuwa, don biya wa Sihiyona bukata. ");
INSERT INTO hausa_vpl VALUES ("IS34_9","024_34_9","ISA","34","9","9","Za a mai da rafuffukan Edom rami, ƙurarta za tă zama kibiritun farar wuta; ƙasarta za tă zama rami mai ƙuna! ");
INSERT INTO hausa_vpl VALUES ("IS34_10","024_34_10","ISA","34","10","10","Ba za a kashe ta ba dare da rana; hayaƙinta za tă yi ta tashi har abada. Daga tsara zuwa tsara za tă zama kango; babu wani da zai ƙara wucewa ta wurin. ");
INSERT INTO hausa_vpl VALUES ("IS34_11","024_34_11","ISA","34","11","11","Mujiyar hamada da mujiya mai kuka za su mallake ta; babban mujiya da hankaka za su yi sheƙa a can. Allah zai miƙe a kan Edom magwajin bala’i da ma’aunin kango. ");
INSERT INTO hausa_vpl VALUES ("IS34_12","024_34_12","ISA","34","12","12","Sarakunanta ba za su kasance da wani abin da ake kira masarauta ba, dukan sarakunanta za su ɓace. ");
INSERT INTO hausa_vpl VALUES ("IS34_13","024_34_13","ISA","34","13","13","Ƙayayuwa za su mamaye fadodinta ƙayayyuwa da sarƙaƙƙiya za su cika kagaranta. Za tă zama mazaunin diloli da gida don mujiyoyi. ");
INSERT INTO hausa_vpl VALUES ("IS34_14","024_34_14","ISA","34","14","14","Halittun hamada za su sadu da kuraye, awakin jeji za su yi ta kiran juna; a can halittun dare su ma za su huta su kuma nemi wurin hutu wa kansu. ");
INSERT INTO hausa_vpl VALUES ("IS34_15","024_34_15","ISA","34","15","15","Mujiya za tă yi sheƙa a can ta zuba ƙwai; za tă ƙyanƙyashe su, ta kuma kula da ’ya’yanta a inuwar fikafikanta; a can kuma shirwa za su taru, kowa da abokinsa. ");
INSERT INTO hausa_vpl VALUES ("IS34_16","024_34_16","ISA","34","16","16","Duba a cikin littafin Ubangiji ka kuma karanta. Babu wani a cikin waɗannan da ya ɓace, babu ko ɗaya da ba ta da abokiya. Gama bakinsa ne ya ba da umarni, Ruhunsa kuma zai tara su wuri ɗaya. ");
INSERT INTO hausa_vpl VALUES ("IS34_17","024_34_17","ISA","34","17","17","Ya ba su rabonsu; hannunsa ya rarraba musu ta wurin awo. Za su mallake ta har abada su kuma zauna a can daga tsara zuwa tsara. ");
INSERT INTO hausa_vpl VALUES ("IS35_1","024_35_1","ISA","35","1","1","Hamada da ƙeƙasasshiyar ƙasa za su yi murna; jeji zai yi farin ciki ya kuma hudo. Kamar fure, ");
INSERT INTO hausa_vpl VALUES ("IS35_2","024_35_2","ISA","35","2","2","zai buɗu ya hudo; zai yi farin ciki mai girma ya kuma yi sowa don farin ciki. Za a maido wa Lebanon da darajarta, darajar Karmel da Sharon; za su ga ɗaukakar Ubangiji, darajar Allahnmu. ");
INSERT INTO hausa_vpl VALUES ("IS35_3","024_35_3","ISA","35","3","3","Ku ƙarfafa hannuwa marasa ƙarfi, ku ƙarfafa gwiwoyin da suka gaji; ");
INSERT INTO hausa_vpl VALUES ("IS35_4","024_35_4","ISA","35","4","4","ku faɗa wa waɗanda suka karai a zukata, “Ku yi ƙarfin hali, kada ku ji tsoro; Allahnku zai zo, zai zo domin ya ɗau fansa; da ramuwar Allah zai zo don yă cece ku.” ");
INSERT INTO hausa_vpl VALUES ("IS35_5","024_35_5","ISA","35","5","5","Sa’an nan idanun makafi za su buɗe kunnuwan kurame kuma su ji. ");
INSERT INTO hausa_vpl VALUES ("IS35_6","024_35_6","ISA","35","6","6","Sa’an nan guragu za su yi tsalle kamar barewa, bebaye kuma su yi sowa don farin ciki. Ruwa zai kwararo daga jeji rafuffuka kuma a cikin hamada. ");
INSERT INTO hausa_vpl VALUES ("IS35_7","024_35_7","ISA","35","7","7","Yashi mai ƙuna zai zama tafki, ƙeƙasasshiyar ƙasa kuma za tă cika da maɓulɓulan rafuffuka. A mazaunin diloli, inda suka taɓa zama, ciyawa da iwa da kyauro za su yi girma. ");
INSERT INTO hausa_vpl VALUES ("IS35_8","024_35_8","ISA","35","8","8","Kuma babbar hanya za tă kasance a can; za a ce ta ita Hanyar Mai Tsarki. Marasa tsarki ba za su yi tafiya a kanta ba; za tă zama domin waɗanda suka yi tafiya a wannan Hanya ce; mugaye da wawaye ba za su yi ta yawo a kanta ba. ");
INSERT INTO hausa_vpl VALUES ("IS35_9","024_35_9","ISA","35","9","9","Zaki ba zai kasance a can ba, balle wani naman jeji mai faɗa ya haura kanta; ba za a same su a can ba. Amma fansassu ne kaɗai za su yi tafiya a can, ");
INSERT INTO hausa_vpl VALUES ("IS35_10","024_35_10","ISA","35","10","10","kuma fansassu na Ubangiji za su komo. Za su shiga Sihiyona da rerawa; matuƙar farin ciki zai mamaye su. Murna da farin ciki za su sha kansu, baƙin ciki kuma da nishi za su gudu. ");
INSERT INTO hausa_vpl VALUES ("IS36_1","024_36_1","ISA","36","1","1","A shekara ta goma sha huɗu ta mulkin Sarki Hezekiya, Sennakerib sarkin Assuriya ya kai wa dukan birane masu kagaran Yahuda yaƙi ya kuma kame su. ");
INSERT INTO hausa_vpl VALUES ("IS36_2","024_36_2","ISA","36","2","2","Sai sarkin Assuriya ya aiki sarkin yaƙinsa tare da mayaƙa masu yawa daga Lakish zuwa wurin Sarki Hezekiya a Urushalima. Sa’ad da sarkin yaƙi ya tsaya a wuriyar Tafkin Tudu, a hanya zuwa Filin Mai Wanki, ");
INSERT INTO hausa_vpl VALUES ("IS36_3","024_36_3","ISA","36","3","3","Eliyakim ɗan Hilkiya sarkin fada, Shebna magatakarda, da Yowa ɗan Asaf marubuci suka fita zuwa wurinsa. ");
INSERT INTO hausa_vpl VALUES ("IS36_4","024_36_4","ISA","36","4","4","Sai sarkin yaƙin ya ce musu, “Ku faɗa wa Hezekiya. “ ‘Ga abin da babban sarki, sarkin Assuriya, ya faɗa. A kan me kake dangana wannan ƙarfin halinka? ");
INSERT INTO hausa_vpl VALUES ("IS36_5","024_36_5","ISA","36","5","5","Ka ce kana da dabara da kuma ƙarfin mayaƙa, amma kana magana banza ce kawai. Ga wa ka dogara, da kake tayar mini? ");
INSERT INTO hausa_vpl VALUES ("IS36_6","024_36_6","ISA","36","6","6","Yanzu duba, kana dogara ga Masar, wannan ɗan tsinken kyauron dogarawa, wanda zai soki hannun mutum yă kuma ji masa rauni in ya dangana a kansa! Haka Fir’auna sarkin Masar yake ga duk wanda ya dogara da shi. ");
INSERT INTO hausa_vpl VALUES ("IS36_7","024_36_7","ISA","36","7","7","Kuma in ka ce mini, “Mun dogara ga Ubangiji Allahnmu ne” ba shi ba ne Hezekiya ya rurrushe masujadan kan tudunsa da bagadansa, yana ce wa Yahuda da Urushalima, “Dole ku yi sujada wa gaban wannan bagade”? ");
INSERT INTO hausa_vpl VALUES ("IS36_8","024_36_8","ISA","36","8","8","“ ‘Yanzu fa, bari in yi ciniki da maigidana, sarki Assuriya. Zan ba ka dawakai dubu biyu, in za ka sa mahaya a kansu! ");
INSERT INTO hausa_vpl VALUES ("IS36_9","024_36_9","ISA","36","9","9","Yaya za ka ƙi hafsan mafi ƙanƙanci na hafsoshin maigidana, ko da yake kana dogara ga Masar don kekunan yaƙi da mahayan dawakai? ");
INSERT INTO hausa_vpl VALUES ("IS36_10","024_36_10","ISA","36","10","10","Ban da haka kuma, na zo ne in faɗa in kuma hallaka wannan ƙasa ba tare da Ubangiji ba? Ubangiji kansa ya faɗa mini in tasar wa wannan ƙasa in kuma hallaka ta.’ ” ");
INSERT INTO hausa_vpl VALUES ("IS36_11","024_36_11","ISA","36","11","11","Sai Eliyakim, Shebna da Yowa suka ce wa sarkin yaƙin, “Ka yi haƙuri ka yi wa bayinka magana da Arameyanci, da yake muna jinsa. Kada ka yi mana magana da Yahudanci a kunnen mutanen da suke kan katanga.” ");
INSERT INTO hausa_vpl VALUES ("IS36_12","024_36_12","ISA","36","12","12","Amma sarkin yaƙin ya amsa ya ce, “Kuna tsammani ga maigidanku da ku ne kawai maigidana ya aiko ni in yi waɗannan maganganu, ba ga mutanen da suke zama a kan katanga ba, waɗanda kamar ku, za su ci kashinsu su kuma sha fitsarinsu?” ");
INSERT INTO hausa_vpl VALUES ("IS36_13","024_36_13","ISA","36","13","13","Sa’an nan sarkin yaƙin ya tsaya ya kuma yi kira da Yahudanci ya ce, “Ku ji kalmomin babban sarki, sarkin Assuriya! ");
INSERT INTO hausa_vpl VALUES ("IS36_14","024_36_14","ISA","36","14","14","Ga abin da sarki ya ce kada ku bar Hezekiya ya ruɗe ku. Ba zai cece ku ba! ");
INSERT INTO hausa_vpl VALUES ("IS36_15","024_36_15","ISA","36","15","15","Kada ku bar Hezekiya ya rarashe ku ku dogara ga Ubangiji sa’ad da ya ce, ‘Tabbatacce Ubangiji zai cece mu; ba za a ba da wannan birni a hannun sarkin Assuriya ba.’ ");
INSERT INTO hausa_vpl VALUES ("IS36_16","024_36_16","ISA","36","16","16","“Kada ku saurari Hezekiya. Ga abin da sarkin Assuriya ya faɗa. Ku nemi salama da ni ku kuma fito zuwa wurina. Ta haka kowa zai ci daga kuringarsa da kuma itacen ɓaurensa ya kuma sha ruwa daga tankinsa, ");
INSERT INTO hausa_vpl VALUES ("IS36_17","024_36_17","ISA","36","17","17","sai na zo na kuma kwashe ku zuwa ƙasa kamar taku, ƙasar hatsi da kuma sabon ruwan inabi, ƙasar abinci da gonakin inabi. ");
INSERT INTO hausa_vpl VALUES ("IS36_18","024_36_18","ISA","36","18","18","“Kada ku bar Hezekiya ya ruɗe ku sa’ad da ya ce, ‘Ubangiji zai cece mu.’ Allahn wata al’umma ya taɓa ceci ƙasarsa daga hannun sarkin Assuriya? ");
INSERT INTO hausa_vpl VALUES ("IS36_19","024_36_19","ISA","36","19","19","Ina allolin Hamat da na Arfad? Ina allolin Sefarfayim? Sun fanshi Samariya daga hannuna? ");
INSERT INTO hausa_vpl VALUES ("IS36_20","024_36_20","ISA","36","20","20","Wanne cikin dukan allolin ƙasashen nan ya iya ceton ƙasarsa daga gare ni? Yaya kuwa Ubangiji zai iya ceci Urushalima daga hannuna?” ");
INSERT INTO hausa_vpl VALUES ("IS36_21","024_36_21","ISA","36","21","21","Amma mutanen suka yi shiru ba su kuwa ce kome ba, gama sarki ya yi umarni cewa, “Kada ku amsa masa.” ");
INSERT INTO hausa_vpl VALUES ("IS36_22","024_36_22","ISA","36","22","22","Sai Eliyakim ɗan Hilkiya sarkin fada, Shebna magatakarda, da kuma Yowa ɗan Asaf marubuci suka tafi wurin Hezekiya, da rigunansu a kyakkece, suka kuwa faɗa masa abin da sarkin yaƙin ya yi ta farfaɗa. ");
INSERT INTO hausa_vpl VALUES ("IS37_1","024_37_1","ISA","37","1","1","Sa’ad da Sarki Hezekiya ya ji haka, sai ya kyakkece rigunansa ya kuma sanya tsummoki ya tafi ya shiga haikalin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS37_2","024_37_2","ISA","37","2","2","Ya aiki Eliyakim sarkin fada, Shebna magatakarda da kuma manyan firistoci, duka sanye da tsummoki, wurin Ishaya ɗan Amoz. ");
INSERT INTO hausa_vpl VALUES ("IS37_3","024_37_3","ISA","37","3","3","Suka faɗa masa cewa, “Ga abin da Hezekiya ya ce wannan rana ce ta baƙin ciki da tsawatawa da shan kunya, sai ka ce sa’ad da ’ya’ya kan zo matakin haihuwa sa’an nan a rasa ƙarfin haihuwarsu. ");
INSERT INTO hausa_vpl VALUES ("IS37_4","024_37_4","ISA","37","4","4","Mai yiwuwa Ubangiji Allahnka zai ji maganganun sarkin yaƙin da maigidansa, sarkin Assuriya, ya aika don yă zagi Allah mai rai, ya kuma tsawata masa saboda maganganun da Ubangiji Allahnka ya ji. Saboda haka ka yi addu’a saboda raguwar da suke da rai.” ");
INSERT INTO hausa_vpl VALUES ("IS37_5","024_37_5","ISA","37","5","5","Sa’ad da shugabannin Sarki Hezekiya suka zo wurin Ishaya, ");
INSERT INTO hausa_vpl VALUES ("IS37_6","024_37_6","ISA","37","6","6","sai Ishaya ya ce musu, “Ku faɗa wa maigidanku cewa, ‘Ga abin da Ubangiji ya faɗa. Kada ka ji tsoron abin da ka ji, maganganun nan da bayin sarkin Assuriya suka yi mini saɓo. ");
INSERT INTO hausa_vpl VALUES ("IS37_7","024_37_7","ISA","37","7","7","Ka saurara! Zan sa ruhuna a cikinsa saboda sa’ad da ya ji wani labari, zai koma zuwa ƙasarsa, a can kuwa zan sa a kashe shi da takobi.’ ” ");
INSERT INTO hausa_vpl VALUES ("IS37_8","024_37_8","ISA","37","8","8","Sa’ad da sarkin yaƙin ya ji cewa sarkin Assuriya ya bar Lakish, sai ya janye ya kuma sami sarki yana yaƙi da Libna. ");
INSERT INTO hausa_vpl VALUES ("IS37_9","024_37_9","ISA","37","9","9","To, fa, Sennakerib ya sami labari cewa Tirhaka, mutumin Kush sarkin Masar, yana fitowa don yă yi yaƙi da shi. Sa’ad da ya ji haka, sai ya aiki jakadu zuwa wurin Hezekiya da wannan magana. ");
INSERT INTO hausa_vpl VALUES ("IS37_10","024_37_10","ISA","37","10","10","“Ku faɗa wa Hezekiya sarkin Yahuda cewa kada ka bar allahn da ka dogara a kai ya ruɗe ka sa’ad da ya ce, ‘Ba za a ba da Urushalima ga sarkin Assuriya ba.’ ");
INSERT INTO hausa_vpl VALUES ("IS37_11","024_37_11","ISA","37","11","11","Tabbatacce ka ji abin da sarakunan Assuriya suka aikata ga dukan ƙasashe, suna hallaka su tas. Kai kuwa za ka tsira ne? ");
INSERT INTO hausa_vpl VALUES ("IS37_12","024_37_12","ISA","37","12","12","Allolin al’umman da kakannina suka hallaka sun cece su ne, allolin Gozan, Haran, Rezef da kuma na mutanen Eden waɗanda suke zama a Tel Assar? ");
INSERT INTO hausa_vpl VALUES ("IS37_13","024_37_13","ISA","37","13","13","Ina sarkin Hamat yake, sarkin Arfad fa, sarkin Sefarfayim, ko na Hena ko na Iffa?” ");
INSERT INTO hausa_vpl VALUES ("IS37_14","024_37_14","ISA","37","14","14","Hezekiya ya karɓi wasiƙar daga jakadun ya karanta ta. Sa’an nan ya haura zuwa haikalin Ubangiji ya shimfiɗa ta a gaban Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS37_15","024_37_15","ISA","37","15","15","Sai Hezekiya ya yi addu’a ga Ubangiji ya ce, ");
INSERT INTO hausa_vpl VALUES ("IS37_16","024_37_16","ISA","37","16","16","“Ya Ubangiji Allah Maɗaukaki, Allah na Isra’ila, zaune a tsakanin kerubobi, kai kaɗai ne Allah a kan dukan masarautan duniya. ");
INSERT INTO hausa_vpl VALUES ("IS37_17","024_37_17","ISA","37","17","17","Ka kasa kunne, ya Ubangiji, ka kuma ji; ka buɗe idanunka, ya Ubangiji, ka kuma gani; ka saurara ga dukan maganganun da Sennakerib ya aika don yă zagi Allah mai rai. ");
INSERT INTO hausa_vpl VALUES ("IS37_18","024_37_18","ISA","37","18","18","“Gaskiya ce, ya Ubangiji, cewa sarakunan Assuriyawa sun mai da dukan waɗannan mutane da ƙasashensu kango. ");
INSERT INTO hausa_vpl VALUES ("IS37_19","024_37_19","ISA","37","19","19","Sun jefar da gumakansu cikin wuta suka kuma hallaka su, gama su ba alloli ba ne itace ne kawai da dutse, da hannuwan mutane suka sarrafa. ");
INSERT INTO hausa_vpl VALUES ("IS37_20","024_37_20","ISA","37","20","20","Yanzu, ya Ubangiji Allahnmu, ka cece mu daga hannunsa, saboda masarautai a duniya su san cewa kai kaɗai ne, ya Ubangiji, Allah.” ");
INSERT INTO hausa_vpl VALUES ("IS37_21","024_37_21","ISA","37","21","21","Sa’an nan Ishaya ɗan Amoz ya aika da saƙo wa Hezekiya cewa, “Ga abin da Ubangiji, Allah na Isra’ila, ya faɗa. Saboda ka yi addu’a gare ni game da Sennakerib sarkin Assuriya, ");
INSERT INTO hausa_vpl VALUES ("IS37_22","024_37_22","ISA","37","22","22","ga abin da maganar Ubangiji ya faɗa a kansa, “Budurwa Diyar Sihiyona ta rena tana kuma maka ba’a. Diyar Urushalima tana kada kai yayinda kake gudu. ");
INSERT INTO hausa_vpl VALUES ("IS37_23","024_37_23","ISA","37","23","23","Wane ne ka zargi ka kuma yi wa saɓo? A kan wa ka tā da muryarka ka kuma daga idanu cikin fariya? A kan Mai Tsarkin nan na Isra’ila! ");
INSERT INTO hausa_vpl VALUES ("IS37_24","024_37_24","ISA","37","24","24","Ta wurin jakadunka ka jibge zage-zage a kan Ubangiji. Ka kuma ce, ‘Da kekunan yaƙina masu yawa na hau ƙwanƙolin duwatsu, ƙwanƙolin mafi tsayi na Lebanon. Na sassare al’ul mafi tsayi fir mafi kyau. Na kai can wuri mafi nisa na kurminsa. ");
INSERT INTO hausa_vpl VALUES ("IS37_25","024_37_25","ISA","37","25","25","Na haƙa rijiyoyi a baƙuwar ƙasa na kuma sha ruwa a can. Da tafin ƙafafuna na busar da dukan rafuffukan Masar.’ ");
INSERT INTO hausa_vpl VALUES ("IS37_26","024_37_26","ISA","37","26","26","“Ba ka ji ba cewa tun dā can na shirya ya zama haka? A kwanakin dā na kafa shi; yanzu na sa ya faru, cewa ka mai da birane masu mafaka zuwa tsibin ɓuraguzai. ");
INSERT INTO hausa_vpl VALUES ("IS37_27","024_37_27","ISA","37","27","27","Mutanensu, suka rasa ƙarfi, sun firgita suka kuma sha kunya. Suka zama kamar tsire-tsire a gona, kamar tsire-tsiren ta suka tohu, kamar ciyawar da ya tsiro a kan rufi, wadda zafi ya yi wa ƙuna kafin tă yi girma. ");
INSERT INTO hausa_vpl VALUES ("IS37_28","024_37_28","ISA","37","28","28","“Amma na san inda kake zama da sa’ad da kakan fita ka kuma koma da yadda ka harzuƙa gāba da ni. ");
INSERT INTO hausa_vpl VALUES ("IS37_29","024_37_29","ISA","37","29","29","Saboda ka harzuƙa gāba da ni kuma saboda girmankanka ya kai kunnuwana, zan sa ƙugiya a hancinka linzamina a bakinka, zan kuma sa ka koma ta hanyar da ka zo. ");
INSERT INTO hausa_vpl VALUES ("IS37_30","024_37_30","ISA","37","30","30","“Wannan zai zama alama gare ka, ya Hezekiya, “Wannan shekara za ka ci abin da ya yi girma da kansa, shekara ta biyu kuma abin da ya tsiro daga wancan. Amma a shekara ta uku za ka yi shuki ka kuma girba, za ka dasa gonakin inabi ka kuma ci ’ya’yansu. ");
INSERT INTO hausa_vpl VALUES ("IS37_31","024_37_31","ISA","37","31","31","Sauran da suka rage na gidan Yahuda kuwa za su yi saiwa a ƙarƙashi su kuma ba da ’ya’ya a bisa. ");
INSERT INTO hausa_vpl VALUES ("IS37_32","024_37_32","ISA","37","32","32","Gama daga Urushalima raguwa za tă fito, kuma daga Dutsen Sihiyona ƙungiyar waɗanda suka tsira. Himmar Ubangiji Maɗaukaki zai cika wannan. ");
INSERT INTO hausa_vpl VALUES ("IS37_33","024_37_33","ISA","37","33","33","“Saboda haka ga abin da Ubangiji yana cewa game da sarkin Assuriya, “Ba zai shiga wannan birni ba ya harbe kibiya a nan. Ba zai zo gabansa da garkuwa ba ko ya gina mahaurai kewaye a kansa ba. ");
INSERT INTO hausa_vpl VALUES ("IS37_34","024_37_34","ISA","37","34","34","Ta hanyar da ya zo da ita zai koma; ba zai shiga wannan birni ba,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS37_35","024_37_35","ISA","37","35","35","“Zan kāre wannan birni in kuma cece shi, saboda girmana da kuma saboda sunan Dawuda bawana!” ");
INSERT INTO hausa_vpl VALUES ("IS37_36","024_37_36","ISA","37","36","36","Sai mala’ikan Ubangiji ya fita ya kuma karkashe mutane dubu ɗari da dubu tamanin da dubu biyar a sansanin Assuriya. Sa’ad da mutane suka farka kashegari, sai ga gawawwaki duk a kwance! ");
INSERT INTO hausa_vpl VALUES ("IS37_37","024_37_37","ISA","37","37","37","Saboda haka Sennakerib sarkin Assuriya ya janye. Ya koma zuwa Ninebe ya zauna a can. ");
INSERT INTO hausa_vpl VALUES ("IS37_38","024_37_38","ISA","37","38","38","Wata rana, yayinda yake yin sujada a haikalin allahnsa Nisrok, ’ya’yansa maza Adrammelek da Sharezer suka kashe shi da takobi, suka kuma gudu zuwa ƙasar Ararat. Esar-Haddon ɗansa kuwa ya gāje shi a matsayin sarki. ");
INSERT INTO hausa_vpl VALUES ("IS38_1","024_38_1","ISA","38","1","1","A kwanakin nan sai Hezekiya ya kamu da ciwo ya kuma kusa ya mutu. Annabi Ishaya ɗan Amoz ya tafi wurinsa ya kuma ce, “Ga abin da Ubangiji ya ce ka shirya gidanka, domin za ka mutu; ba za ka warke ba.” ");
INSERT INTO hausa_vpl VALUES ("IS38_2","024_38_2","ISA","38","2","2","Hezekiya ya juye fuskarsa wajen bango ya kuma yi addu’a ga Ubangiji, ");
INSERT INTO hausa_vpl VALUES ("IS38_3","024_38_3","ISA","38","3","3","“Ka tuna, ya Ubangiji, yadda na yi tafiya a gabanka da aminci da dukan zuciya na kuma yi abin da yake nagari a idanunka.” Sai Hezekiya ya yi kuka mai zafi. ");
INSERT INTO hausa_vpl VALUES ("IS38_4","024_38_4","ISA","38","4","4","Sai maganar Ubangiji ta zo wa Ishaya cewa, ");
INSERT INTO hausa_vpl VALUES ("IS38_5","024_38_5","ISA","38","5","5","“Ka tafi ka faɗa wa Hezekiya, ‘Ga abin da Ubangiji Allah na kakanka Dawuda, ya ce na ji addu’arka na kuma ga hawayenka; zan ƙara maka shekaru goma sha biyar ga rayuwarka. ");
INSERT INTO hausa_vpl VALUES ("IS38_6","024_38_6","ISA","38","6","6","Zan kuwa cece ka da wannan birni daga hannun sarkin Assuriya. Zan kiyaye wannan birni. ");
INSERT INTO hausa_vpl VALUES ("IS38_7","024_38_7","ISA","38","7","7","“ ‘Ga alamar Ubangiji gare ka cewa Ubangiji zai aikata kamar yadda ya yi alkawari. ");
INSERT INTO hausa_vpl VALUES ("IS38_8","024_38_8","ISA","38","8","8","Zan sa inuwar da rana ta yi a kan matakalar Ahaz ta koma baya da taki goma.’ ” Saboda haka inuwar ta koma da baya daga fuskar rana har taki goma. ");
INSERT INTO hausa_vpl VALUES ("IS38_9","024_38_9","ISA","38","9","9","Rubutun Hezekiya sarkin Yahuda bayan ciwonsa da kuma warkarwarsa. ");
INSERT INTO hausa_vpl VALUES ("IS38_10","024_38_10","ISA","38","10","10","Na ce, “Cikin tsakiyar rayuwata dole in bi ta ƙofofin mutuwa a kuma raba ni da sauran shekaruna?” ");
INSERT INTO hausa_vpl VALUES ("IS38_11","024_38_11","ISA","38","11","11","Na ce, “Ba zan ƙara ganin Ubangiji ba, Ubangiji a ƙasa ta masu rai; ba zan ƙara ga wani mutum, ko in kasance tare da waɗanda suke zama a wannan duniya ba. ");
INSERT INTO hausa_vpl VALUES ("IS38_12","024_38_12","ISA","38","12","12","Kamar tentin makiyayi an rushe gidana aka kuma ƙwace ta daga gare ni. Kamar mai saƙa, na nannaɗe rayuwata, ya kuma yanke ni daga sandar saƙa; dare da rana ka kawo ni ga ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("IS38_13","024_38_13","ISA","38","13","13","Na yi jira da haƙuri har safiya, amma kamar zaki ya kakkarya ƙasusuwana duka; dare da rana ka kawo ni ga ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("IS38_14","024_38_14","ISA","38","14","14","Na yi kuka kamar mashirare ko zalɓe, na yi kuka kamar kurciya mai makoki. Idanuna suka rasa ƙarfi yayinda na duba sammai. Na damu; Ya Ubangiji, ka taimake ni!” ");
INSERT INTO hausa_vpl VALUES ("IS38_15","024_38_15","ISA","38","15","15","Amma me zan ce? Ya riga ya yi mini magana, shi kansa ne kuma ya aikata. Zan yi tafiya da tawali’u dukan kwanakina saboda wahalar raina. ");
INSERT INTO hausa_vpl VALUES ("IS38_16","024_38_16","ISA","38","16","16","Ubangiji, ta waɗannan abubuwa ne mutane suke rayuwa; ruhuna kuma yana samun rai a cikinsu shi ma. Ka maido mini da lafiya ka kuma sa na rayu. ");
INSERT INTO hausa_vpl VALUES ("IS38_17","024_38_17","ISA","38","17","17","Tabbatacce wannan kuwa saboda ribata ne cewa in sha irin wahalan nan. Cikin ƙaunarka ka kiyaye ni daga ramin hallaka; ka sa dukan zunubaina a bayanka. ");
INSERT INTO hausa_vpl VALUES ("IS38_18","024_38_18","ISA","38","18","18","Gama kabari ba zai yabe ka ba, matattu ba za su rera yabonka ba; waɗanda suka gangara zuwa rami ba za su sa zuciya ga amincinka ba. ");
INSERT INTO hausa_vpl VALUES ("IS38_19","024_38_19","ISA","38","19","19","Masu rai, masu rai, su suke yabonka, kamar yadda nake yi a yau; iyaye za su faɗa wa ’ya’yansu game da amincinka. ");
INSERT INTO hausa_vpl VALUES ("IS38_20","024_38_20","ISA","38","20","20","Ubangiji zai cece ni, za mu kuma rera da kayan kiɗi masu tsirkiya dukan kwanakinmu a cikin haikalin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS38_21","024_38_21","ISA","38","21","21","Ishaya ya riga ya ce, “Ku shirya curin da aka yi da ’ya’yan ɓaure ku kuma shafa a marurun, zai kuwa warke.” ");
INSERT INTO hausa_vpl VALUES ("IS38_22","024_38_22","ISA","38","22","22","Hezekiya ya riga ya yi tambaya ya ce, “Me zai zama alama ta cewa zan haura zuwa haikalin Ubangiji?” ");
INSERT INTO hausa_vpl VALUES ("IS39_1","024_39_1","ISA","39","1","1","A wannan lokaci Merodak-Baladan ɗan Baladan sarkin Babilon ya aika wa Hezekiya wasiƙu da kuma kyauta, domin ya ji rashin lafiyarsa da kuma warkarwarsa. ");
INSERT INTO hausa_vpl VALUES ("IS39_2","024_39_2","ISA","39","2","2","Hezekiya ya marabci jakadun da murna ya kuma nuna musu abin da gidajen ajiyarsa sun ƙunsa, azurfa, zinariya, yaji, tatsatsen mai, dukan kayan yaƙinsa da kuma kome da yake a ma’ajinsa. Babu abin da yake a cikin fadansa ko cikin dukan masarautarsa da Hezekiya bai nuna musu ba. ");
INSERT INTO hausa_vpl VALUES ("IS39_3","024_39_3","ISA","39","3","3","Sai Ishaya annabi ya tafi wurin Sarki Hezekiya ya kuma tambaye shi ya ce, “Mene ne waɗannan mutane suka faɗa, kuma daga ina suka fito?” Hezekiya ya amsa ya ce, “Daga ƙasa mai nisa. Sun zo ne daga Babilon.” ");
INSERT INTO hausa_vpl VALUES ("IS39_4","024_39_4","ISA","39","4","4","Annabi ya yi tambaya ya ce, “Mene ne suka gani a fadanka?” Hezekiya ya ce, “Sun ga kome da kome a fadana. Babu abin da ban nuna musu a cikin ma’ajina ba.” ");
INSERT INTO hausa_vpl VALUES ("IS39_5","024_39_5","ISA","39","5","5","Sai Ishaya ya ce wa Hezekiya, “Ka ji maganar Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("IS39_6","024_39_6","ISA","39","6","6","Tabbatacce lokaci yana zuwa sa’ad da kome da yake cikin fadanka, da kuma dukan abin da kakanninka suka ajiye har yă zuwa yau, za a kwashe zuwa Babilon babu abin da za a bari, in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS39_7","024_39_7","ISA","39","7","7","Waɗansu cikin zuriyarka, nama da jininka waɗanda za a haifa maka, za a kwashe su a tafi, za su zama bābānni a fadan sarkin Babilon.” ");
INSERT INTO hausa_vpl VALUES ("IS39_8","024_39_8","ISA","39","8","8","Hezekiya ya ce, “Maganar Ubangiji da ka yi tana da kyau.” Gama ya yi tunani a ransa cewa, “Salama da kāriya za su kasance a zamanina.” ");
INSERT INTO hausa_vpl VALUES ("IS40_1","024_40_1","ISA","40","1","1","Ta’aziyya, ku ta’azantu mutanena, in ji Allahnku. ");
INSERT INTO hausa_vpl VALUES ("IS40_2","024_40_2","ISA","40","2","2","Yi magana mai kwantar da rai ga Urushalima, ku kuma furta mata cewa aiki mai zafinta ya isa, cewa an fanshi zunubinta, cewa ta karɓi daga hannun Ubangiji ninki biyu saboda dukan zunubanta. ");
INSERT INTO hausa_vpl VALUES ("IS40_3","024_40_3","ISA","40","3","3","Muryar wani tana kira cewa, “A cikin hamada ku shirya hanya saboda Ubangiji; ku miƙe manyan hanyoyi domin Allahnmu a cikin jeji. ");
INSERT INTO hausa_vpl VALUES ("IS40_4","024_40_4","ISA","40","4","4","Za a cike kowane kwari, a baje kowane dutse da kowane tudu; za a mayar da karkatattun wurare su zama sumul, munanan wurare kuma su zama da kyau. ");
INSERT INTO hausa_vpl VALUES ("IS40_5","024_40_5","ISA","40","5","5","Za a kuma bayyana ɗaukakar Ubangiji, dukan mutane kuwa za su gan ta. Gama Ubangiji da kansa ne ya yi magana.” ");
INSERT INTO hausa_vpl VALUES ("IS40_6","024_40_6","ISA","40","6","6","Muryar tana cewa, “Ka yi shela.” Na kuwa ce, “Me zan yi shelar?” “Dukan mutane kamar ciyawa suke, kuma dukan ɗaukakarsu kamar furannin jeji ne. ");
INSERT INTO hausa_vpl VALUES ("IS40_7","024_40_7","ISA","40","7","7","Ciyawa takan yanƙwane, furanni kuma su yi yaushi, domin Ubangiji ya hura iska a kansu. Tabbatacce mutane ciyawa ne. ");
INSERT INTO hausa_vpl VALUES ("IS40_8","024_40_8","ISA","40","8","8","Hakika ciyawa takan yanƙwane, furanni kuma su yi yaushi, amma maganar Allahnmu tana nan daram har abada.” ");
INSERT INTO hausa_vpl VALUES ("IS40_9","024_40_9","ISA","40","9","9","Kai da ka kawo labari mai daɗi wa Sihiyona, ka haura a bisa dutse. Kai da ka kawo labari mai daɗi wa Urushalima, ka tā da muryarka ka yi ihu, ka ɗaga ta, kada ka ji tsoro; faɗa wa garuruwan Yahuda, “Ga Allahnku!” ");
INSERT INTO hausa_vpl VALUES ("IS40_10","024_40_10","ISA","40","10","10","Duba, Ubangiji Mai Iko Duka yana zuwa da iko, hannunsa kuma yana yin mulki dominsa. Duba, ladarsa tana tare da shi, sakamakonsa kuma na rakiyarsa. ");
INSERT INTO hausa_vpl VALUES ("IS40_11","024_40_11","ISA","40","11","11","Yakan lura da garkensa kamar makiyayi. Yakan tattara tumaki wuri ɗaya yă riƙe su kurkusa da ƙirjinsa; a hankali kuma yakan bi da masu ba da mama. ");
INSERT INTO hausa_vpl VALUES ("IS40_12","024_40_12","ISA","40","12","12","Wane ne ya auna ruwaye a tafin hannunsa, ko kuwa ya gwada tsawon sammai da fāɗin tafin hannunsa? Wane ne ya riƙe ƙurar ƙasa a kwando, ko kuwa ya auna nauyin duwatsu a magwaji, tuddai kuma a ma’auni? ");
INSERT INTO hausa_vpl VALUES ("IS40_13","024_40_13","ISA","40","13","13","Wane ne ya fahimci zuciyarUbangiji, ko kuwa ya koya masa a matsayin mashawarcinsa? ");
INSERT INTO hausa_vpl VALUES ("IS40_14","024_40_14","ISA","40","14","14","Wane ne Ubangiji ya nemi shawararsa don yă ganar da shi, wane ne kuma ya koya masa hanyar da ta dace? Wane ne ya koya masa sani ko ya nuna masa hanyar fahimta? ");
INSERT INTO hausa_vpl VALUES ("IS40_15","024_40_15","ISA","40","15","15","Tabbatacce al’ummai suna kama da ɗigon ruwa a cikin bokiti an ɗauke su a matsayin ƙura a kan magwaji; yakan auna tsibirai sai ka ce ƙura mai laushi. ");
INSERT INTO hausa_vpl VALUES ("IS40_16","024_40_16","ISA","40","16","16","Itatuwan Lebanon ba su isa a yi wutar bagade da su ba, balle dabbobinsa su isa yin hadayun ƙonawa. ");
INSERT INTO hausa_vpl VALUES ("IS40_17","024_40_17","ISA","40","17","17","A gabansa dukan al’ummai ba kome ba ne; ya ɗauke su ba a bakin kome ba kuma banza ne kurum. ");
INSERT INTO hausa_vpl VALUES ("IS40_18","024_40_18","ISA","40","18","18","To, ga wane ne za ka kwatanta Allah? Wace siffa za ka kwatanta shi da ita? ");
INSERT INTO hausa_vpl VALUES ("IS40_19","024_40_19","ISA","40","19","19","Gunki dai, maƙeri kan yi zubinsa, maƙerin zinariya kuma yă ƙera shi da zinariya yă kuma sarrafa masa sarƙoƙin azurfa. ");
INSERT INTO hausa_vpl VALUES ("IS40_20","024_40_20","ISA","40","20","20","Mutumin da talauci ya sha kansa da ba zai iya miƙa irin hadayar nan ba kan zaɓi itacen da ba zai ruɓe ba. Yakan nemi gwanin sassaƙa don yă sassaƙa masa gunkin da ba zai fāɗi ba. ");
INSERT INTO hausa_vpl VALUES ("IS40_21","024_40_21","ISA","40","21","21","Ba ku sani ba? Ba ku taɓa ji ba? Ba a faɗa muku daga farko ba? Ba ku fahimta ba tun kafawar duniya? ");
INSERT INTO hausa_vpl VALUES ("IS40_22","024_40_22","ISA","40","22","22","Yana zaune a kursiyi a bisa iyakar duniya, kuma mutanenta suna kama da fāra. Ya miƙa sammai kamar rumfa, ya kuma shimfiɗa su kamar tentin da za a zauna a ciki. ");
INSERT INTO hausa_vpl VALUES ("IS40_23","024_40_23","ISA","40","23","23","Yakan mai da sarakuna ba kome ba yă mai da masu mulkin wannan duniya wofi. ");
INSERT INTO hausa_vpl VALUES ("IS40_24","024_40_24","ISA","40","24","24","Ba da jimawa ba bayan an shuka su, ba da jimawa ba bayan an dasa su, ba da jimawa ba bayan sun yi saiwa a ƙasa, sai yă hura musu iska su yanƙwane, guguwa kuma ta kwashe su kamar yayi. ");
INSERT INTO hausa_vpl VALUES ("IS40_25","024_40_25","ISA","40","25","25","“Ga wa za ku kwatanta ni? Ko kuwa wa yake daidai da ni?” In ji Mai Tsarkin nan. ");
INSERT INTO hausa_vpl VALUES ("IS40_26","024_40_26","ISA","40","26","26","Ku ɗaga idanunku ku duba sammai. Wane ne ya halicce dukan waɗannan? Wane ne ya fitar da rundunar taurari ɗaya-ɗaya, yana kiransu, kowanne da sunansa. Saboda ikonsa mai girma da kuma ƙarfinsa mai girma, babu ko ɗayansu da ya ɓace. ");
INSERT INTO hausa_vpl VALUES ("IS40_27","024_40_27","ISA","40","27","27","Ya Yaƙub, ya Isra’ila, me ya sa kake ce kana kuma gunaguni cewa, “Hanyata tana a ɓoye daga Ubangiji; Allah bai kula da abin da yake damuna ba”? ");
INSERT INTO hausa_vpl VALUES ("IS40_28","024_40_28","ISA","40","28","28","Ba ku sani ba? Ba ku ji ba? Ubangiji madawwamin Allah ne, Mahaliccin iyakokin duniya. Ba zai taɓa gaji ko yă kasala ba, kuma fahimtarsa ya wuce gaban ganewar mutum. ");
INSERT INTO hausa_vpl VALUES ("IS40_29","024_40_29","ISA","40","29","29","Yakan ba da ƙarfi ga waɗanda suka gaji yă kuma ƙara ƙarfi ga marasa ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("IS40_30","024_40_30","ISA","40","30","30","Ko matasa ma kan gaji su kuma kasala, samari kuma kan yi tuntuɓe su fāɗi; ");
INSERT INTO hausa_vpl VALUES ("IS40_31","024_40_31","ISA","40","31","31","amma waɗanda suka dogara ga Ubangiji za su sabunta ƙarfinsu. Za su yi firiya da fikafikai kamar gaggafa; za su kuma yi gudu ba kuwa za su gaji ba, za su yi tafiya ba kuwa za su kasala ba. ");
INSERT INTO hausa_vpl VALUES ("IS41_1","024_41_1","ISA","41","1","1","“Ku yi shiru a gabana, ku tsibirai! Bari al’ummai su sabunta ƙarfinsu! Bari su zo gaba su yi magana; bari mu sadu a wurin shari’a. ");
INSERT INTO hausa_vpl VALUES ("IS41_2","024_41_2","ISA","41","2","2","“Wa ya zuga wannan daga gabas, yana kiransa cikin adalci ga yin hidima? Ya miƙa masa al’ummai ya kuma yi nasara da sarakuna a gabansa. Ya mai da su ƙura da takobinsa, zuwa inda iska ke hurawa ta wurin bugun da ya yi musu. ");
INSERT INTO hausa_vpl VALUES ("IS41_3","024_41_3","ISA","41","3","3","Ya fafare su ya kuma yi tafiyarsa lafiya ƙalau, a hanyar da ƙafafunsa ba su taɓa bi ba. ");
INSERT INTO hausa_vpl VALUES ("IS41_4","024_41_4","ISA","41","4","4","Wane ne ya taɓa yin haka ya kuma sa ya faru, yana kira ga tsararraki daga farko? Ni, Ubangiji ina can tun farkonsu ni kuma ina can har ƙarshe, Ni ne shi.” ");
INSERT INTO hausa_vpl VALUES ("IS41_5","024_41_5","ISA","41","5","5","Tsibirai sun gan shi suka kuma ji tsoro; iyakokin duniya sun yi rawar jiki. Suka kusato suka kuma zo gaba; ");
INSERT INTO hausa_vpl VALUES ("IS41_6","024_41_6","ISA","41","6","6","kowa na taimakon wani yana ce wa ɗan’uwansa, “Ka ƙarfafa!” ");
INSERT INTO hausa_vpl VALUES ("IS41_7","024_41_7","ISA","41","7","7","Masassaƙi yakan ƙarfafa maƙerin zinariya, kuma shi mai gyara da guduma ya yi sumul yakan ƙarfafa mai harhaɗawa. Ya ce game da haɗin, “Ya yi kyau.” Yakan buga ƙusoshi su riƙe gunkin don kada yă fāɗi. ");
INSERT INTO hausa_vpl VALUES ("IS41_8","024_41_8","ISA","41","8","8","“Amma kai, ya Isra’ila, bawana, Yaƙub, wanda na zaɓa, zuriyar Ibrahim abokina, ");
INSERT INTO hausa_vpl VALUES ("IS41_9","024_41_9","ISA","41","9","9","na ɗauke ka daga iyakar duniya, daga kusurwoyi masu nesa na kira ka. Na ce, ‘Kai bawana ne’; na zaɓe ka ban kuwa ƙi ka ba. ");
INSERT INTO hausa_vpl VALUES ("IS41_10","024_41_10","ISA","41","10","10","Saboda haka kada ka ji tsoro, gama ina tare da kai; kada ka karai, gama ni ne Allahnka. Zan ƙarfafa ka in kuma taimake ka; zan riƙe ka da hannun damana mai adalci. ");
INSERT INTO hausa_vpl VALUES ("IS41_11","024_41_11","ISA","41","11","11","“Duk wanda ya yi fushi da kai tabbatacce zai sha kunya da ƙasƙanci; waɗanda suka yi hamayya da kai za su zama kamar ba kome ba su kuma hallaka. ");
INSERT INTO hausa_vpl VALUES ("IS41_12","024_41_12","ISA","41","12","12","Ko ka nemi abokan gābanka, ba za ka same su ba. Waɗanda suke yaƙi da kai za su zama kamar ba kome ba. ");
INSERT INTO hausa_vpl VALUES ("IS41_13","024_41_13","ISA","41","13","13","Gama ni ne Ubangiji Allahnka, wanda ya riƙe ka da hannun damana ya kuma ce maka, Kada ka ji tsoro; zan taimake ka. ");
INSERT INTO hausa_vpl VALUES ("IS41_14","024_41_14","ISA","41","14","14","Kada ka ji tsoro, ya Yaƙub marar ƙarfi, ya ƙaramin Isra’ila, gama ni kaina zan taimake ka,” in ji Ubangiji, Mai Fansarka, Mai Tsarkin nan na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS41_15","024_41_15","ISA","41","15","15","“Duba, zan sa ka cikin abin sussuka, saboda kuma mai kaifi mai haƙora da yawa. Za ka yi sussukar duwatsu ka ragargaza su, ka kuma farfashe tuddai su zama kamar yayi. ");
INSERT INTO hausa_vpl VALUES ("IS41_16","024_41_16","ISA","41","16","16","Za ka tankaɗe su, iska kuma ta kwashe su, guguwa kuma za tă warwatsa su. Amma za ka yi farin ciki a cikin Ubangiji ka kuma ɗaukaka a cikin Mai Tsarkin nan na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS41_17","024_41_17","ISA","41","17","17","“Matalauta da mabukata suna neman ruwa, amma babu kome; harsunansu sun bushe saboda ƙishi. Amma Ni Ubangiji zan amsa musu; Ni, Allah na Isra’ila, ba zan yashe su ba. ");
INSERT INTO hausa_vpl VALUES ("IS41_18","024_41_18","ISA","41","18","18","Zan sa koguna su malalo a ƙeƙasassun tuddai, maɓulɓulan ruwa kuma a kwaruruka. Zan mai da hamada tafkunan ruwa, busasshiyar ƙasa kuma ta zama maɓulɓulan ruwa. ");
INSERT INTO hausa_vpl VALUES ("IS41_19","024_41_19","ISA","41","19","19","Zan sa a hamada ta tsiro da al’ul da itacen ƙirya, da itacen ci-zaƙi, da zaitun. Zan sa itace mai girma a ƙasashe masu sanyi ya tsiro a ƙeƙasasshiyar ƙasa, tare da fir da kuma saifires, ");
INSERT INTO hausa_vpl VALUES ("IS41_20","024_41_20","ISA","41","20","20","don mutane su gani su kuma sani, su lura su kuma fahimci, cewa hannun Ubangiji ne ya aikata haka, cewa Mai Tsarkin nan na Isra’ila ya sa abin ya faru. ");
INSERT INTO hausa_vpl VALUES ("IS41_21","024_41_21","ISA","41","21","21","“Ka gabatar da damuwarka,” in ji Ubangiji. “Ka kawo gardandaminka,” in ji Sarki na Yaƙub. ");
INSERT INTO hausa_vpl VALUES ("IS41_22","024_41_22","ISA","41","22","22","“Ka shigar da gumakanka don su faɗa mana abin da zai faru. Faɗa mana abubuwan da suka riga suka faru, domin mu lura da su mu kuma san abin da zai faru a ƙarshe. Ko kuwa ku furta mana abubuwan da za su faru, ");
INSERT INTO hausa_vpl VALUES ("IS41_23","024_41_23","ISA","41","23","23","faɗa mana abin da nan gaba ta ƙunsa, don mu san cewa ku alloli ne. Ku yi wani abu, mai kyau ko mummuna, don mu ji tsoro da fargaba. ");
INSERT INTO hausa_vpl VALUES ("IS41_24","024_41_24","ISA","41","24","24","Amma ku ba kome ba ne kuma ayyukanku banza da wofi ne; duk wanda ya zaɓe ku abin ƙyama ne. ");
INSERT INTO hausa_vpl VALUES ("IS41_25","024_41_25","ISA","41","25","25","“Na zuga wani daga arewa, ya kuwa zo, wani daga inda rana ke fitowa wanda yake kira bisa sunana. Yana takawa a kan masu mulki kamar da taɓarya, sai ka ce maginin tukwane yana taka laka. ");
INSERT INTO hausa_vpl VALUES ("IS41_26","024_41_26","ISA","41","26","26","Wa ya faɗi wannan tun daga farko, don mu sani, ko kafin ya faru, don mu ce, ‘Ya faɗi daidai’? Ba wanda ya faɗa wannan, ba wanda ya riga faɗe shi, ba wanda ya ji wata magana daga gare ku. ");
INSERT INTO hausa_vpl VALUES ("IS41_27","024_41_27","ISA","41","27","27","Ni ne na farkon da ya ce wa Sihiyona, ‘Duba, ga su nan!’ Na ba wa Urushalima saƙon labari mai daɗi. ");
INSERT INTO hausa_vpl VALUES ("IS41_28","024_41_28","ISA","41","28","28","Na duba amma ba kowa ba wani a cikinsu da zai ba da shawara, ba wani da zai ba da amsa sa’ad da na tambaye su. ");
INSERT INTO hausa_vpl VALUES ("IS41_29","024_41_29","ISA","41","29","29","Duba, dukansu masu ƙarya ne! Ayyukansu ba su da riba; siffofinsu iska ne kawai da ruɗami. ");
INSERT INTO hausa_vpl VALUES ("IS42_1","024_42_1","ISA","42","1","1","“Ga bawana, wanda na ɗaukaka, zaɓaɓɓen nan nawa wanda nake jin daɗi; Zan sa Ruhuna a cikinsa zai kuwa kawo adalci ga al’ummai. ");
INSERT INTO hausa_vpl VALUES ("IS42_2","024_42_2","ISA","42","2","2","Ba zai yi ihu ko ya tā da murya, ko ya daga muryarsa a tituna ba. ");
INSERT INTO hausa_vpl VALUES ("IS42_3","024_42_3","ISA","42","3","3","Iwan da ta tanƙware ba zai karye ba, ba zai kashe lagwani mai hayaƙi ba. Cikin aminci zai kawo adalci; ");
INSERT INTO hausa_vpl VALUES ("IS42_4","024_42_4","ISA","42","4","4","ba zai kāsa ko ya karai ba sai ya kafa adalci a duniya. Cikin dokarsa tsibirai za su sa zuciya.” ");
INSERT INTO hausa_vpl VALUES ("IS42_5","024_42_5","ISA","42","5","5","Ga abin da Allah Ubangiji ya ce, shi da ya halicci sammai ya kuma miƙe su, wanda ya shimfiɗa duniya da dukan abin da ya fito cikinta, wanda ya ba wa mutanenta numfashi, da rai ga waɗanda suke tafiya a kanta. ");
INSERT INTO hausa_vpl VALUES ("IS42_6","024_42_6","ISA","42","6","6","“Ni Ubangiji, na kira ka cikin adalci; zan riƙe hannunka. Zan kiyaye ka in kuma sa ka zama alkawari ga mutane haske kuma ga Al’ummai, ");
INSERT INTO hausa_vpl VALUES ("IS42_7","024_42_7","ISA","42","7","7","don ka buɗe idanun makafi ka ’yantar da kamammu daga kurkuku kuma kunce ɗaurarrun kurkuku masu zama cikin duhu. ");
INSERT INTO hausa_vpl VALUES ("IS42_8","024_42_8","ISA","42","8","8","“Ni ne Ubangiji; sunana ke nan! Ba zan ba da ɗaukakata ga wani ba ko yabona ga gumaka. ");
INSERT INTO hausa_vpl VALUES ("IS42_9","024_42_9","ISA","42","9","9","Duba, abubuwan da sun tabbata, sababbin abubuwa kuwa nake furtawa; kafin ma su soma faruwa na sanar da su gare ku.” ");
INSERT INTO hausa_vpl VALUES ("IS42_10","024_42_10","ISA","42","10","10","Ku rera sabuwar waƙa ga Ubangiji, ku yi yabonsa daga iyakar duniya, ku da kuka gangara zuwa teku, da kome da yake cikinsa, ku tsibirai, da waɗanda suke zama a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("IS42_11","024_42_11","ISA","42","11","11","Bari hamada da garuruwanta su tā da muryoyinsu; bari wuraren zaman da Kedar ke zama su yi farin ciki. Bari mutanen Sela su rera don farin ciki; bari su yi sowa daga ƙwanƙolin duwatsu. ");
INSERT INTO hausa_vpl VALUES ("IS42_12","024_42_12","ISA","42","12","12","Bari su ɗaukaka Ubangiji su kuma yi shelar yabonsa a tsibirai. ");
INSERT INTO hausa_vpl VALUES ("IS42_13","024_42_13","ISA","42","13","13","Ubangiji zai fita ya yi yaƙi kamar mai ƙarfi, kamar jarumi zai yi himma; da ihu zai tā da kirarin yaƙi zai kuma yi nasara a kan abokan gābansa. ");
INSERT INTO hausa_vpl VALUES ("IS42_14","024_42_14","ISA","42","14","14","“Na daɗe ina shiru, na yi shiru na kuma ƙame kaina. Amma yanzu, kamar mace mai naƙuda, na yi ƙara, ina nishi ina kuma haki. ");
INSERT INTO hausa_vpl VALUES ("IS42_15","024_42_15","ISA","42","15","15","Zan lalatar da duwatsu da tuddai in busar da dukan itatuwansu; zan mai da koguna su zama tsibirai in kuma busar da tafkuna. ");
INSERT INTO hausa_vpl VALUES ("IS42_16","024_42_16","ISA","42","16","16","Zan yi wa makafi jagora a hanyoyin da ba su taɓa sani ba, a hanyoyin da ba a saba ba zan bishe su; zan mai da duhu ya zama haske a gabansu in kuma mai da ƙasa mai kururrumai ta zama sumul. Abubuwan da zan yi ke nan; ba zan yashe su ba. ");
INSERT INTO hausa_vpl VALUES ("IS42_17","024_42_17","ISA","42","17","17","Amma waɗanda suka dogara ga gumaka, waɗanda suke ce wa siffofi, ‘Ku ne allolinmu,’ za a mai da su baya da kunya. ");
INSERT INTO hausa_vpl VALUES ("IS42_18","024_42_18","ISA","42","18","18","“Ka ji, kai kurma; duba, kai makaho, ka kuma gani! ");
INSERT INTO hausa_vpl VALUES ("IS42_19","024_42_19","ISA","42","19","19","Wane ne makaho in ba bawana ba, da kuma kurma in ba ɗan aikan da na aika ba? Wane ne makaho kamar wanda ya miƙa kai gare ni, makaho kamar bawan Ubangiji? ");
INSERT INTO hausa_vpl VALUES ("IS42_20","024_42_20","ISA","42","20","20","Kun ga abubuwa masu yawa, amma ba ku kula ba; kunnuwanku suna a buɗe, amma ba kwa jin wani abu.” ");
INSERT INTO hausa_vpl VALUES ("IS42_21","024_42_21","ISA","42","21","21","Yakan gamsar da Ubangiji saboda adalcinsa ya sa dokarsa ta zama mai girma da kuma mai ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("IS42_22","024_42_22","ISA","42","22","22","Amma ga mutanen da aka washe aka kuma kwashe ganima, an yi wa dukansu tarko a cikin rammuka ko kuma an ɓoye su cikin kurkuku. Sun zama ganima, babu wani da zai kuɓutar da su; an mai da su ganima, ba wanda zai ce, “Mayar da su.” ");
INSERT INTO hausa_vpl VALUES ("IS42_23","024_42_23","ISA","42","23","23","Wane ne a cikinku zai saurari wannan ko ya kasa kunne sosai a cikin kwanaki masu zuwa? ");
INSERT INTO hausa_vpl VALUES ("IS42_24","024_42_24","ISA","42","24","24","Wa ya ba da Yaƙub don yă zama ganima Isra’ila kuma ga masu kwasar ganima? Ba Ubangiji ba ne, wanda kuka yi wa zunubi? Gama ba su bi hanyoyinsa ba; ba su yi biyayya da dokarsa ba. ");
INSERT INTO hausa_vpl VALUES ("IS42_25","024_42_25","ISA","42","25","25","Saboda haka ya zuba musu zafin fushinsa, yaƙi mai tsanani. Ya rufe su cikin harsunan wuta, duk da haka ba su gane ba; ya cinye su, amma ba su koyi kome ba. ");
INSERT INTO hausa_vpl VALUES ("IS43_1","024_43_1","ISA","43","1","1","To, fa, ga abin da Ubangiji yana cewa, shi da ya halicce ka, ya Yaƙub, shi da ya siffanta ka, ya Isra’ila, “Kada ka ji tsoro, gama na fanshe ka; na kira ka da suna; kai nawa ne. ");
INSERT INTO hausa_vpl VALUES ("IS43_2","024_43_2","ISA","43","2","2","Sa’ad da kuka bi ta ruwaye, zan kasance tare da ku; sa’ad da kuka bi ta koguna, ba za su kwashe ku ba. Sa’ad da kuke tafiyata cikin wuta, ba za tă ƙone ku ba; harsunan wutar ba za su ƙone ku ba. ");
INSERT INTO hausa_vpl VALUES ("IS43_3","024_43_3","ISA","43","3","3","Gama ni ne Ubangiji, Allahnku, Mai Tsarkin nan na Isra’ila, Mai Cetonku; na bayar da Masar don fansa, Kush da Seba a maimakonku. ");
INSERT INTO hausa_vpl VALUES ("IS43_4","024_43_4","ISA","43","4","4","Da yake ku masu daraja da kuma girma ne a idona, saboda kuma ina ƙaunarku, zan ba da mutane a maimakonku, al’umma kuma domin ranku. ");
INSERT INTO hausa_vpl VALUES ("IS43_5","024_43_5","ISA","43","5","5","Kada ku ji tsoro, gama ina tare da ku; zan kawo yaranku daga gabas in kuma tattara ku daga yamma. ");
INSERT INTO hausa_vpl VALUES ("IS43_6","024_43_6","ISA","43","6","6","Zan ce wa arewa, ‘Ku miƙa su!’ Ga kudu kuma, ‘Kada ku riƙe su.’ Kawo ’ya’yana maza daga nesa ’ya’yana mata kuma daga iyakar duniya, ");
INSERT INTO hausa_vpl VALUES ("IS43_7","024_43_7","ISA","43","7","7","kowa da ake kira da sunana, wanda aka halitta saboda ɗaukakata, wanda na siffanta na kuma yi.” ");
INSERT INTO hausa_vpl VALUES ("IS43_8","024_43_8","ISA","43","8","8","Jagoranci waɗanda suke da idanu amma suke makafi, waɗanda suke da kunnuwa amma suke kurame. ");
INSERT INTO hausa_vpl VALUES ("IS43_9","024_43_9","ISA","43","9","9","Dukan al’ummai su taru mutane kuma su tattaru. Wane ne a cikinsu ya yi faɗar wannan ya kuma yi mana shelar abubuwan da suka riga suka faru? Bari su kawo shaidunsu don su tabbatar cewa sun yi daidai, don waɗansu su ji su kuma ce, “Gaskiya ne.” ");
INSERT INTO hausa_vpl VALUES ("IS43_10","024_43_10","ISA","43","10","10","“Ku ne shaiduna,” in ji Ubangiji, “bawana kuma wanda na zaɓa, saboda ka sani ka kuma gaskata ni ka kuma fahimci cewa ni ne shi. Kafin ni babu allahn da aka siffanta, ba kuwa za a yi wani a bayana ba. ");
INSERT INTO hausa_vpl VALUES ("IS43_11","024_43_11","ISA","43","11","11","Ni kaɗai, ni ne Ubangiji, kuma in ban da ni babu wani mai ceto. ");
INSERT INTO hausa_vpl VALUES ("IS43_12","024_43_12","ISA","43","12","12","Na bayyana na ceci na kuma furta, Ni ne, ba wani baƙon allah a cikinku. Ku ne shaiduna,” in ji Ubangiji, “cewa ni ne Allah. ");
INSERT INTO hausa_vpl VALUES ("IS43_13","024_43_13","ISA","43","13","13","I, kuma tun fil azal ni ne shi. Babu wani da zai amshi daga hannuna. Sa’ad da na aikata, wa zai iya sauyawa?” ");
INSERT INTO hausa_vpl VALUES ("IS43_14","024_43_14","ISA","43","14","14","Ga abin da Ubangiji yana cewa, Mai Fansarku, Mai Tsarkin nan na Isra’ila, “Saboda ku zan aika Babilon in kawo dukan Babiloniyawa kamar masu gudun hijira, a cikin jiragen ruwa waɗanda suke taƙama da su. ");
INSERT INTO hausa_vpl VALUES ("IS43_15","024_43_15","ISA","43","15","15","Ni ne Ubangiji, Mai Tsarkin nan, Mahaliccin Isra’ila, Sarkinku.” ");
INSERT INTO hausa_vpl VALUES ("IS43_16","024_43_16","ISA","43","16","16","Ga abin da Ubangiji yana cewa, shi da ya yi hanya ta cikin teku, hanya ta cikin manyan ruwaye, ");
INSERT INTO hausa_vpl VALUES ("IS43_17","024_43_17","ISA","43","17","17","wanda ya ja kekunan yaƙi da dawakai, mayaƙa da kuma ƙarin mayaƙa tare ya kwantar da su a can, ba kuwa za su ƙara tashi ba, ya kashe hayaƙi daga lagwani, ");
INSERT INTO hausa_vpl VALUES ("IS43_18","024_43_18","ISA","43","18","18","“Ku manta da abubuwan da suka riga suka faru; kada ku yi tunanin abin da ya riga ya wuce. ");
INSERT INTO hausa_vpl VALUES ("IS43_19","024_43_19","ISA","43","19","19","Duba, ina yi abu sabo! Yanzu yana faruwa; ba ku gan shi ba? Ina yin hanya a cikin hamada rafuffuka kuma a cikin ƙeƙasasshiyar ƙasa. ");
INSERT INTO hausa_vpl VALUES ("IS43_20","024_43_20","ISA","43","20","20","Namun jeji suna girmama ni, diloli da mujiyoyi ma haka, domin na tanada musu ruwa a hamada da rafuffuka a ƙeƙasasshiyar ƙasa, don a ba da abin sha ga mutanena, zaɓaɓɓuna, ");
INSERT INTO hausa_vpl VALUES ("IS43_21","024_43_21","ISA","43","21","21","mutanen da na yi saboda kaina don su furta yabona. ");
INSERT INTO hausa_vpl VALUES ("IS43_22","024_43_22","ISA","43","22","22","“Duk da haka ba ku kira bisa sunana ba, ya Yaƙub, ba ku gajiyar da kanku saboda ni ba, ya Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS43_23","024_43_23","ISA","43","23","23","Ba ku kawo mini tumaki don hadaya ta ƙonewa ba, balle ku girmama ni da hadayunku. Ban nawaita muku da hadaya ta gari ba balle in gajiyar da ku da bukatar turare. ");
INSERT INTO hausa_vpl VALUES ("IS43_24","024_43_24","ISA","43","24","24","Ba ku saya wani turaren kalamus domina ba ko ku gamshe ni da kitsen hadayunku. Amma kun nawaita ni da zunubanku kuka kuma gajiyar da ni da laifofinku. ");
INSERT INTO hausa_vpl VALUES ("IS43_25","024_43_25","ISA","43","25","25","“Ni kaɗai ne na shafe laifofinku, saboda sunana, ban kuma ƙara tunawa da zunubanku ba. ");
INSERT INTO hausa_vpl VALUES ("IS43_26","024_43_26","ISA","43","26","26","Ku tunashe ni abin da ya riga ya wuce, bari mu yi muhawwara wannan batu tare; ku kawo hujjarku na nuna rashin laifinku. ");
INSERT INTO hausa_vpl VALUES ("IS43_27","024_43_27","ISA","43","27","27","Mahaifinku na farko ya yi zunubi; masu magana a madadinku suka yi mini tayarwa. ");
INSERT INTO hausa_vpl VALUES ("IS43_28","024_43_28","ISA","43","28","28","Saboda haka zan kunyata manyan baƙi na haikalinku, zan tura Yaƙub ga hallaka Isra’ila kuwa yă zama abin dariya. ");
INSERT INTO hausa_vpl VALUES ("IS44_1","024_44_1","ISA","44","1","1","“Amma yanzu ka saurara, ya Yaƙub, bawana, Isra’ila, wanda zaɓa. ");
INSERT INTO hausa_vpl VALUES ("IS44_2","024_44_2","ISA","44","2","2","Ga abin da Ubangiji yana cewa, shi wanda ya yi ka, wanda ya siffanta ka a cikin mahaifa, wanda kuma zai taimake ka. Kada ka ji tsoro, ya Yaƙub, bawana, Yeshurun, wanda na zaɓa. ");
INSERT INTO hausa_vpl VALUES ("IS44_3","024_44_3","ISA","44","3","3","Gama zan zuba ruwa a ƙeƙasasshiyar ƙasa, rafuffuka kuma a busasshiyar ƙasa; zan ba da Ruhuna ga ’ya’yanka, albarkata kuma ga zuriyarka. ");
INSERT INTO hausa_vpl VALUES ("IS44_4","024_44_4","ISA","44","4","4","Za su tsiro kamar ciyawa a wuriyar ruwa, kamar kurmi kusa da rafuffuka masu gudu. ");
INSERT INTO hausa_vpl VALUES ("IS44_5","024_44_5","ISA","44","5","5","Wani zai ce, ‘Ni na Ubangiji ne’; wani kuma zai kira kansa da sunan Yaƙub; har yanzu wani zai rubuta a hannunsa, ‘Na Ubangiji,’ ya kuma ɗauki sunan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS44_6","024_44_6","ISA","44","6","6","“Ga abin da Ubangiji yana cewa, Sarki da kuma Mai Fansar Isra’ila, Ubangiji Maɗaukaki. Ni ne farko ni ne kuma ƙarshe; in ban da ni babu wani Allah. ");
INSERT INTO hausa_vpl VALUES ("IS44_7","024_44_7","ISA","44","7","7","Wane ne kuwa kama da ni? Ya faɗa a ji. Bari yă yi shela ya kuma nuna shi a gabana mene ne ya faru tun da na kafa mutanena na dā, mene ne kuma bai riga ya faru ba, I, bari yă faɗa abin da zai zo. ");
INSERT INTO hausa_vpl VALUES ("IS44_8","024_44_8","ISA","44","8","8","Kada ku firgita kada kuma ku ji tsoro. Ban furta wannan na kuma yi faɗar haka tuntuni ba? Ku ne shaiduna. Akwai wani Allah in ban da ni? A’a, babu wani Dutse; ban san da wani ba.” ");
INSERT INTO hausa_vpl VALUES ("IS44_9","024_44_9","ISA","44","9","9","Duk masu yin gumaka ba kome ba ne, da kuma abubuwan da suke ɗauka da daraja banza ne. Waɗanda za su yi magana a madadinsu makafi ne; jahilai ne, marasa kunya. ");
INSERT INTO hausa_vpl VALUES ("IS44_10","024_44_10","ISA","44","10","10","Waɗanda suke siffanta allah su kuma yi zubin gunki, waɗanda ba za su yi musu ribar kome ba? ");
INSERT INTO hausa_vpl VALUES ("IS44_11","024_44_11","ISA","44","11","11","Shi da irinsa za su sha kunya; masu sassaƙa ba kome ba mutane ne kurum. Bari su tattaru su ɗauki matsayinsu; za su firgita su kuma sha mummunan kunya. ");
INSERT INTO hausa_vpl VALUES ("IS44_12","024_44_12","ISA","44","12","12","Maƙeri yakan ɗauki kayan aiki ya yi aiki da shi a cikin garwashi; ya ƙera gunki da guduma, ya gyara shi da hannuwansa masu ƙarfi. Yakan ji yunwa ya kuma rasa ƙarfi; yakan sha ruwa ya kuma ji gajiya. ");
INSERT INTO hausa_vpl VALUES ("IS44_13","024_44_13","ISA","44","13","13","Kafinta yakan gwada katako yă kuma zāna siffar da alli; yă goge shi da kayan aiki yă kuma zāna shi da alƙalami. Yă siffanta shi a kamannin mutum, mutum cikin dukan darajarsa, don yă ajiye shi a cikin masujada. ");
INSERT INTO hausa_vpl VALUES ("IS44_14","024_44_14","ISA","44","14","14","Yakan ka da itacen saifires, ko kuwa ya ɗauki saifires ko oak. Yă bar shi yă yi girma a cikin itatuwan kurmi, ko yă shuka itacen fir, ruwan sama kuma yă sa yă yi girma. ");
INSERT INTO hausa_vpl VALUES ("IS44_15","024_44_15","ISA","44","15","15","Abin hura wutar mutum ne; yakan ɗebi waɗansu yă hura wuta don yă ji ɗumi, ya hura wuta yă gasa burodi. Amma yakan ƙera zinariya yă kuma yi masa sujada; yakan yi gunki sa’an nan yă rusuna masa. ");
INSERT INTO hausa_vpl VALUES ("IS44_16","024_44_16","ISA","44","16","16","Rabin katakon yakan ƙone a wuta; a kansa yakan dafa abincinsa, yă gasa namansa yă kuma ci sai ya ƙoshi. Yakan ji ɗumi yă kuma ce, “Aha! Na ji ɗumi; na gan wutar.” ");
INSERT INTO hausa_vpl VALUES ("IS44_17","024_44_17","ISA","44","17","17","Da sauran itacen yakan yi allah, gunkinsa; yă rusuna masa yă kuma yi sujada. Yakan yi masa addu’a yă ce, “Ka cece ni; kai ne allahna.” ");
INSERT INTO hausa_vpl VALUES ("IS44_18","024_44_18","ISA","44","18","18","Ba su san kome ba, ba su fahimci kome ba; an rufe idanunsu don kada su gani, tunaninsu kuma a rufe don kada su fahimta. ");
INSERT INTO hausa_vpl VALUES ("IS44_19","024_44_19","ISA","44","19","19","Ba wanda yakan dakata ya yi tunani, ba wanda yake da sani ko fahimi ya ce, “Da rabinsa na yi amfani da shi don hura wuta; na ma gasa burodi a kan garwashinsa, na gasa nama na kuma ci. Ya kamata in yi abin ƙyama daga abin da ya rage? Ya kamata in rusuna wa guntun katako?” ");
INSERT INTO hausa_vpl VALUES ("IS44_20","024_44_20","ISA","44","20","20","Yana cin toka, zuciyar da ta ruɗe tana ɓad da shi; ba zai iya cece kansa ba, ko ya ce, “Wannan abin da yake hannun dama na ba ƙarya ba ne?” ");
INSERT INTO hausa_vpl VALUES ("IS44_21","024_44_21","ISA","44","21","21","“Tuna da waɗannan abubuwa, ya Yaƙub, gama kai bawana ne, ya Isra’ila. Na yi ka, kai bawana ne; Ya Isra’ila, ba zan manta da kai ba. ");
INSERT INTO hausa_vpl VALUES ("IS44_22","024_44_22","ISA","44","22","22","Na shafe laifofinka kamar girgije, zunubanka kamar hazon safe. Ka komo wurina, gama na kuɓutar da kai.” ");
INSERT INTO hausa_vpl VALUES ("IS44_23","024_44_23","ISA","44","23","23","Ku rera don farin ciki, ya sammai, gama Ubangiji ya aikata wannan; ku yi sowa, ya duniya a ƙarƙashi. Ku ɓarke da waƙoƙi, ku duwatsu, ku jeji da dukan itatuwanku, gama Ubangiji ya kuɓutar da Yaƙub, ya nuna ɗaukakarsa a cikin Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS44_24","024_44_24","ISA","44","24","24","“Ga abin da Ubangiji yana cewa, Mai Fansarka, wanda ya yi ka a cikin mahaifa. “Ni ne Ubangiji, wanda ya yi dukan abubuwa, wanda ya shimfiɗa sammai ya kuma kafa harsashen duniya da kansa, ");
INSERT INTO hausa_vpl VALUES ("IS44_25","024_44_25","ISA","44","25","25","wanda ya sassāke alamun annabawan ƙarya ya masu duba suka zama wawaye, wanda ya tumɓuke koyon masu hikima ya mai da shi banza, ");
INSERT INTO hausa_vpl VALUES ("IS44_26","024_44_26","ISA","44","26","26","wanda ya tabbatar da maganganun bayinsa ya kuma cika annabce-annabcen ’yan aikansa, “wanda ya ce game da Urushalima, ‘Za a zauna a cikinta,’ game da garuruwan Yahuda, ‘Za a gina su,’ ");
INSERT INTO hausa_vpl VALUES ("IS44_27","024_44_27","ISA","44","27","27","wanda ya ce wa zurfin ruwaye, ‘Ku bushe, zan kuma busar da rafuffukanku,’ ");
INSERT INTO hausa_vpl VALUES ("IS44_28","024_44_28","ISA","44","28","28","wanda ya yi zancen Sairus ya ce, ‘Shi ne makiyayina zan kuma cika dukan abin da na gan dama; zai yi zancen Urushalima cewa, “Bari a sāke gina ta,” game da haikali kuma cewa, “Bari a kafa harsashinsa.” ’ ");
INSERT INTO hausa_vpl VALUES ("IS45_1","024_45_1","ISA","45","1","1","“Ga abin da Ubangiji ya faɗa wa shafaffensa, ga Sairus, wanda hannun damansa yana riƙe da shi don yă ci al’ummai a gabansa ya kuma tuɓe makaman sarakuna, don yă buɗe ƙofofi a gabansa don kada a kulle ƙofofi. ");
INSERT INTO hausa_vpl VALUES ("IS45_2","024_45_2","ISA","45","2","2","Zan sha gabanka in baje duwatsu; zan farfashe ƙofofin tagulla in kuma kakkarye ƙyamaren ƙarfe. ");
INSERT INTO hausa_vpl VALUES ("IS45_3","024_45_3","ISA","45","3","3","Zan ba ka dukiyar duhu, arzikin da aka ajiye a asirtattun wurare, saboda ka san cewa ni ne Ubangiji, Allah na Isra’ila, wanda ya kira ka da suna. ");
INSERT INTO hausa_vpl VALUES ("IS45_4","024_45_4","ISA","45","4","4","Saboda sunan Yaƙub bawana, Isra’ila zaɓaɓɓena, na kira ka da suna na ba ka matsayin bangirma, ko da yake ba ka san ni ba. ");
INSERT INTO hausa_vpl VALUES ("IS45_5","024_45_5","ISA","45","5","5","Ni ne Ubangiji, kuma babu wani; in ban da ni babu wani Allah. Zan ƙarfafa ka, ko da yake ba ka san ni ba, ");
INSERT INTO hausa_vpl VALUES ("IS45_6","024_45_6","ISA","45","6","6","saboda daga fitowar rana har zuwa fāɗuwarta mutane za su san cewa babu wani in ban da ni. Ni ne Ubangiji, kuma babu wani. ");
INSERT INTO hausa_vpl VALUES ("IS45_7","024_45_7","ISA","45","7","7","Ni ne na siffanta haske na kuma halicci duhu, ni ne nake ba da nasara in kuma jawo bala’i; ni, Ubangiji ne ke aikata dukan waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("IS45_8","024_45_8","ISA","45","8","8","“Ku sammai, ku sauko da adalci kamar ruwan sama; bari gizagizai su zubar da yayyafi kamar adalci. Bari ƙasa ta buɗe, bari ceto ya tsiro, bari adalci ya yi girma tare da shi; ni, Ubangijine, na sa ya faru. ");
INSERT INTO hausa_vpl VALUES ("IS45_9","024_45_9","ISA","45","9","9","“Kaitonka mai gardama da Wanda ya yi ka, da wanda yake kasko a cikin kasko a ƙasa. Yumɓu ya iya ce wa magini, ‘Me kake yi?’ Aikinka na iya cewa, ‘Ba shi da hannuwa’? ");
INSERT INTO hausa_vpl VALUES ("IS45_10","024_45_10","ISA","45","10","10","Kaiton wanda yake cewa mahaifinsa, ‘Me ka manta?’ Ko kuwa ga mahaifiyarsa, ‘Me kin haifa?’ ");
INSERT INTO hausa_vpl VALUES ("IS45_11","024_45_11","ISA","45","11","11","“Ga abin da Ubangiji yana cewa, Mai Tsarkin nan na Isra’ila, da kuma Mahaliccinsa. Game da abubuwan da ke zuwa, kun tambaye ni game da ’ya’yana, ko kuwa kun ba ni umarni game da aikin hannuwana? ");
INSERT INTO hausa_vpl VALUES ("IS45_12","024_45_12","ISA","45","12","12","Ai, ni ne wanda ya yi duniya na kuma halicci mutum a kanta. Hannuwana ne sun miƙe sammai; na umarci rundunar sararin sama. ");
INSERT INTO hausa_vpl VALUES ("IS45_13","024_45_13","ISA","45","13","13","Zan tā da Sairus cikin adalcina. Zan sa dukan hanyoyinsa su miƙe. Zai sāke gina birnina ya kuma ’yantar da mutanena masu bautar talala, amma ba don wata haya ko lada ba, in ji Ubangiji Maɗaukaki.” ");
INSERT INTO hausa_vpl VALUES ("IS45_14","024_45_14","ISA","45","14","14","Ga abin da Ubangiji yana cewa, “Kayayyakin Masar da hajar Kush, da waɗannan dogayen Sabenawa, za su ƙetaro zuwa wurinku za su kuma zama naku; za su bi bayanku, suna zuwa cikin sarƙoƙi. Za su rusuna a gabanku su roƙe ku, suna cewa, ‘Tabbas Allah yana tare da ku, babu kuma wani; babu wani allah.’ ” ");
INSERT INTO hausa_vpl VALUES ("IS45_15","024_45_15","ISA","45","15","15","Tabbatacce kai ne Allah wanda ya ɓoye kanka, Ya Allah da Mai Ceton Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS45_16","024_45_16","ISA","45","16","16","Dukan masu yin gumaka za su sha kunya; za su fita da kunya gaba ɗaya. ");
INSERT INTO hausa_vpl VALUES ("IS45_17","024_45_17","ISA","45","17","17","Amma Ubangiji zai ceci Isra’ila da madawwamin ceto; ba za ku sāke shan kunya ko ƙasƙanci ba, har abada. ");
INSERT INTO hausa_vpl VALUES ("IS45_18","024_45_18","ISA","45","18","18","Gama ga abin da Ubangiji yana cewa, shi da ya halicci sammai, shi ne Allah; shi da ya sarrafa ya kuma yi duniya, ya kafa ta; bai halicce ta don ta zama ba kome ba, amma ya yi ta don a zauna a ciki, ya ce, “Ni ne Ubangiji, kuma babu wani. ");
INSERT INTO hausa_vpl VALUES ("IS45_19","024_45_19","ISA","45","19","19","Ban yi magana asirce ba, daga wani wuri a ƙasar duhu ba; ban faɗa wa zuriyar Yaƙub, ‘Ku neme ni a banza ba.’ Ni, Ubangiji maganar gaskiya nake yi; na furta abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("IS45_20","024_45_20","ISA","45","20","20","“Ku tattaru ku zo; ku taru, ku masu gudun hijira daga al’ummai. Masu jahilci ne waɗanda suke ɗaukan gumakan katakai suna yawo, waɗanda suke addu’a ga allolin da ba za su cece su ba. ");
INSERT INTO hausa_vpl VALUES ("IS45_21","024_45_21","ISA","45","21","21","Furta abin da zai kasance, ku gabatar da shi, bari su yi shawara tare. Wa ya faɗa wannan tuntuni, wa ya yi shelar sa a kwanakin dā? Ba ni ba ne, Ubangiji? Kuma babu Allah in ban da ni, Allah mai adalci da kuma Mai Ceto; babu wani sai ni. ");
INSERT INTO hausa_vpl VALUES ("IS45_22","024_45_22","ISA","45","22","22","“Ku juyo gare ni ku sami ceto, dukanku iyakokin duniya; gama ni ne Allah, kuma babu wani. ");
INSERT INTO hausa_vpl VALUES ("IS45_23","024_45_23","ISA","45","23","23","Da kaina na rantse, bakina ya furta cikin dukan mutunci kalmar da ba za a janye ba. A gabana kowace gwiwa za tă durƙusa; ta wurina kowane harshe zai rantse. ");
INSERT INTO hausa_vpl VALUES ("IS45_24","024_45_24","ISA","45","24","24","Za su yi zance game da ni su ce, ‘A cikin Ubangiji kaɗai akwai adalci da kuma ƙarfafawa.’ ” Duk wanda ya yi fushi da shi zai zo wurinsa ya kuma sha kunya. ");
INSERT INTO hausa_vpl VALUES ("IS45_25","024_45_25","ISA","45","25","25","Amma a cikin Ubangiji dukan zuriyar Isra’ila za su sami adalci za su kuwa yi yabo. ");
INSERT INTO hausa_vpl VALUES ("IS46_1","024_46_1","ISA","46","1","1","Bel ya rusuna, Nebo ya durƙusa ƙasa; ana ɗaukan gumakansu a kan dabbobi ne. Siffofin da ake yawo da su nawaya ne, kayan nauyi masu gajiyarwa. ");
INSERT INTO hausa_vpl VALUES ("IS46_2","024_46_2","ISA","46","2","2","Sun durƙusa suka kuma rusuna tare; ba su iya kuɓutar da nauyin kaya su kansu sukan tafi bauta. ");
INSERT INTO hausa_vpl VALUES ("IS46_3","024_46_3","ISA","46","3","3","“Ku kasa kunne gare ni, ya ku gidan Yaƙub, dukanku waɗanda kuka rage na gidan Isra’ila, ku da na lura da ku tun da aka yi cikinku, na kuma riƙe ku tun haihuwarku. ");
INSERT INTO hausa_vpl VALUES ("IS46_4","024_46_4","ISA","46","4","4","Har lokacin da kuka tsufa kuka yi furfura ni ne shi, ni ne shi wanda zai lura da ku. Na yi ku zan kuma riƙe ku; zan lura da ku in kuma kuɓutar da ku. ");
INSERT INTO hausa_vpl VALUES ("IS46_5","024_46_5","ISA","46","5","5","“Da wa za ku kwatanta ni ko ku ɗauka daidai da ni? Da wa nake kama da har da za ku kwatanta ni? ");
INSERT INTO hausa_vpl VALUES ("IS46_6","024_46_6","ISA","46","6","6","Waɗansu sukan zubar da zinariya daga jaka su kuma auna azurfa a ma’auni; sukan yi haya maƙerin zinariya don yă ƙera allah, su kuma rusuna su yi masa sujada. ");
INSERT INTO hausa_vpl VALUES ("IS46_7","024_46_7","ISA","46","7","7","Sukan daga shi a kafaɗunsu su kuma ɗauke shi; sukan kafa shi a tsaye a wurinsa, a can kuwa zai tsaya. Daga wannan wuri ba zai iya gusawa ba. Ko da wani ya nemi taimakonsa, ba ya amsawa; ba zai iya cetonsa daga wahala ba. ");
INSERT INTO hausa_vpl VALUES ("IS46_8","024_46_8","ISA","46","8","8","“Ku tuna da wannan, ku sa shi a zuciya, ku riƙe shi a zuciya, ku ’yan tawaye. ");
INSERT INTO hausa_vpl VALUES ("IS46_9","024_46_9","ISA","46","9","9","Ku tuna da abubuwan da suka riga suka faru, waɗannan na tun dā; ni ne Allah, kuma babu wani; ni ne Allah kuma babu wani kamar ni. ");
INSERT INTO hausa_vpl VALUES ("IS46_10","024_46_10","ISA","46","10","10","Nakan sanar da ƙarshe tun daga farko, daga fil azal, abin da yake zuwa nan gaba. Na ce nufina zai tabbata, kuma zan aikata dukan abin da na gan dama. ");
INSERT INTO hausa_vpl VALUES ("IS46_11","024_46_11","ISA","46","11","11","Daga gabas na kira tsuntsun da yake farauta; daga can ƙasa mai nesa, wani mutumin da zai cika nufina. Abin da na riga na faɗa, shi zan sa ya faru; abin da na shirya, shi zan aikata. ");
INSERT INTO hausa_vpl VALUES ("IS46_12","024_46_12","ISA","46","12","12","Ku kasa kunne, ku masu taurinkai, ku da kuke nesa da adalci. ");
INSERT INTO hausa_vpl VALUES ("IS46_13","024_46_13","ISA","46","13","13","Ina kawo adalcina kusa, ba shi da nisa; kuma cetona ba zai jinkirta ba. Zan yi wa Sihiyona ceto, darajata ga Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS47_1","024_47_1","ISA","47","1","1","“Ki gangara, ki zauna a ƙura, Budurwa Diyar Babilon; ki zauna a ƙasa ba tare da rawani ba, Diyar Babiloniyawa. Ba za a ƙara kira ke marar ƙarfi ’yar gata ba. ");
INSERT INTO hausa_vpl VALUES ("IS47_2","024_47_2","ISA","47","2","2","Ɗauki dutsen niƙa ki niƙa gari; ki kware lulluɓinki. Ki ɗaga fatarinki ki bar ƙafafunki tsirara, ki kuma yi ta ratsa cikin rafuffuka. ");
INSERT INTO hausa_vpl VALUES ("IS47_3","024_47_3","ISA","47","3","3","Tsirararki zai bayyana za a kuma buɗe kunyarki. Zan ɗauki fansa; ba zan bar wani ba.” ");
INSERT INTO hausa_vpl VALUES ("IS47_4","024_47_4","ISA","47","4","4","Mai Fansarmu, Ubangiji Maɗaukaki shi ne sunansa, shi ne Mai Tsarkin nan na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS47_5","024_47_5","ISA","47","5","5","“Zauna shiru, tafi cikin duhu, Diyar Babiloniya; ba za a ƙara kira ke sarauniyar masarautai. ");
INSERT INTO hausa_vpl VALUES ("IS47_6","024_47_6","ISA","47","6","6","Na yi fushi da mutanena na ƙazantar da gādona; na ba su ga hannunki, ba ki kuwa nuna musu jinƙai ba. Har ma da tsofaffi kin jibga musu kaya masu nauyi sosai. ");
INSERT INTO hausa_vpl VALUES ("IS47_7","024_47_7","ISA","47","7","7","Kika ce, ‘Zan ci gaba har abada, madawwamiyar sarauniya!’ Amma ba ki lura da waɗannan abubuwa ko ki yi la’akari a kan abin da zai faru ba. ");
INSERT INTO hausa_vpl VALUES ("IS47_8","024_47_8","ISA","47","8","8","“To, yanzu fa, ki kasa kunne, ke mai ƙaunar nishaɗi, mai zama da rai kwance kina kuma ce wa kanki, ‘Ni ce, kuma babu wani in ban da ni. Ba zan taɓa zama gwauruwa ko in sha wahalar rashin ’ya’ya ba.’ ");
INSERT INTO hausa_vpl VALUES ("IS47_9","024_47_9","ISA","47","9","9","Duk waɗannan za su sha kanki cikin farat ɗaya, a rana guda, rashin ’ya’ya da gwauranci. Za su zo a kanki da cikakken minzani, duk da yawan masu dubanki da kuma dukan sihirinki. ");
INSERT INTO hausa_vpl VALUES ("IS47_10","024_47_10","ISA","47","10","10","Kin dogara a muguntarki kika kuma ce, ‘Babu wanda ya gan ni.’ Hikimarki da saninki sun ɓad da ke sa’ad da kika ce wa kanki, ‘Ni ce, kuma babu wani in ban da ni.’ ");
INSERT INTO hausa_vpl VALUES ("IS47_11","024_47_11","ISA","47","11","11","Bala’i zai fāɗo a kanki, kuma ba za ki san yadda za ki rinjaye shi yă janye ba. Masifa za tă fāɗo a kanki da ba za ki iya tsai da ita da kuɗin fansa ba; lalacewar da ba ki taɓa mafarkinta ba za tă auko miki nan da nan. ");
INSERT INTO hausa_vpl VALUES ("IS47_12","024_47_12","ISA","47","12","12","“Ki dai ci gaba, da sihirinki da kuma makarunki masu yawa, waɗanda kika yi ta wahala tun kina jaririya. Mai yiwuwa ki yi nasara, mai yiwuwa ki jawo fargaba. ");
INSERT INTO hausa_vpl VALUES ("IS47_13","024_47_13","ISA","47","13","13","Dukan shawarwarin da kika samu sun dai gajiyar da ke ne kawai! Bari masananki na taurari su zo gaba, waɗannan masu zāna taswirar sammai suna kuma faɗa miki dukan abin da zai faru da ke wata-wata, bari su cece ki daga abin da zai faru da ke. ");
INSERT INTO hausa_vpl VALUES ("IS47_14","024_47_14","ISA","47","14","14","Tabbas suna kama da bunnu; wuta za tă cinye su ƙaf. Ba za su ma iya ceton kansu daga ikon wutar ba. Ba wutar da wani zai ji ɗumi; ba wutar da za a zauna kusa da ita. ");
INSERT INTO hausa_vpl VALUES ("IS47_15","024_47_15","ISA","47","15","15","Abin da za su iya yi miki ke nan kawai, waɗannan da kika yi ta fama da su kika kuma yi ciniki da su tun kina jaririya. Kowannensu zai tafi cikin kuskurensa; babu ko ɗayan da zai cece ki. ");
INSERT INTO hausa_vpl VALUES ("IS48_1","024_48_1","ISA","48","1","1","“Ku kasa kunne ga wannan, ya gidan Yaƙub, waɗanda ake kira da sunan Isra’ila suka kuma fito daga zuriyar Yahuda, ku da kuke yin rantsuwa da sunan Ubangiji kuna kuma kira sunan Allah na Isra’ila, amma ba da gaskiya ko adalci ba, ");
INSERT INTO hausa_vpl VALUES ("IS48_2","024_48_2","ISA","48","2","2","ku da kuke kiran kanku ’yan ƙasar birni mai tsarki kuna kuma dogara ga Allah na Isra’ila, Ubangiji Maɗaukaki ne sunansa, ");
INSERT INTO hausa_vpl VALUES ("IS48_3","024_48_3","ISA","48","3","3","na nanata abubuwan da suka riga suka faru tuntuni, bakina ya yi shelar su na kuma sanar da su; sai nan da nan na aikata, suka kuma faru. ");
INSERT INTO hausa_vpl VALUES ("IS48_4","024_48_4","ISA","48","4","4","Gama na san yadda kuke da taurinkai; jijiyoyin wuyanku ƙarafa ne, goshinku tagulla ne. ");
INSERT INTO hausa_vpl VALUES ("IS48_5","024_48_5","ISA","48","5","5","Saboda haka na faɗa waɗannan abubuwa tuntuni; kafin su faru na yi shelarsu gare ku saboda kada ku ce, ‘Gumakana ne suka yi su; siffar itacena da allahn zinariyana ne ya ƙaddara su.’ ");
INSERT INTO hausa_vpl VALUES ("IS48_6","024_48_6","ISA","48","6","6","Kun riga kun ji waɗannan abubuwa; kuka gan su duka. Ba za ku yarda da su ba? “Daga yanzu zuwa gaba zan faɗa muku sababbin abubuwa, na ɓoyayyun abubuwan da ba ku sani ba. ");
INSERT INTO hausa_vpl VALUES ("IS48_7","024_48_7","ISA","48","7","7","Yanzu an halicce su, ba da daɗewa ba; ba ku riga kun ji game da su kafin yau ba. Saboda haka ba za ku ce, ‘I, na san da su ba.’ ");
INSERT INTO hausa_vpl VALUES ("IS48_8","024_48_8","ISA","48","8","8","Ba ku ji ko balle ku gane ba; tun da kunnenku bai buɗu ba. Tabbatacce na san yadda kun zama masu tayarwa; an kira ku ’yan tawaye daga haihuwa. ");
INSERT INTO hausa_vpl VALUES ("IS48_9","024_48_9","ISA","48","9","9","Saboda girman sunana na jinkirta fushina; saboda girman yabona na janye shi daga gare ku, don dai kada a yanke ku. ");
INSERT INTO hausa_vpl VALUES ("IS48_10","024_48_10","ISA","48","10","10","Duba, na tace ku, ko da yake ba kamar azurfa ba; na gwada ku cikin wutar wahala. ");
INSERT INTO hausa_vpl VALUES ("IS48_11","024_48_11","ISA","48","11","11","Saboda girmana, saboda girmana, na yi haka. Yaya zan ƙyale a ƙazantar da kaina? Ba zan raba ɗaukakata da wani ba. ");
INSERT INTO hausa_vpl VALUES ("IS48_12","024_48_12","ISA","48","12","12","“Ka kasa kunne gare ni, ya Yaƙub, Isra’ila, wanda na kira cewa, Ni ne shi; ni ne na farko ni ne kuma na ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("IS48_13","024_48_13","ISA","48","13","13","Hannuna ne ya kafa harsashen duniya, hannuna na dama kuma ya shimfiɗa sammai; sa’ad da na kira su, duka suka miƙe tsaye gaba ɗaya. ");
INSERT INTO hausa_vpl VALUES ("IS48_14","024_48_14","ISA","48","14","14","“Ku tattaru, dukanku ku kuma saurara, Wanne a cikin gumakan ya iya faɗa waɗannan abubuwa? Zaɓaɓɓen da Ubangiji yake ƙauna zai aikata nufinsa a kan Babilon; hannunsa zai yi gāba da Babiloniyawa. ");
INSERT INTO hausa_vpl VALUES ("IS48_15","024_48_15","ISA","48","15","15","Ni kaina, na faɗa; I, na kira shi. Zan kawo shi, zai kuma yi nasara a cikin aikinsa. ");
INSERT INTO hausa_vpl VALUES ("IS48_16","024_48_16","ISA","48","16","16","“Ku zo kusa da ni ku kuma saurari wannan. “Daga farkon shela ban yi magana a ɓoye ba; a lokacin da ya faru, ina nan a wurin.” Yanzu kuwa Ubangiji Mai Iko Duka ya aiko ni, da Ruhunsa. ");
INSERT INTO hausa_vpl VALUES ("IS48_17","024_48_17","ISA","48","17","17","Ga abin da Ubangiji yana cewa, Mai Fansarku, Mai Tsarkin nan na Isra’ila ya ce, “Ni ne Ubangiji Allahnku, wanda ya koya muku abin da ya fi muku kyau, wanda ya muku hanyar da za ku bi. ");
INSERT INTO hausa_vpl VALUES ("IS48_18","024_48_18","ISA","48","18","18","Da a ce kawai za ku mai da hankali ga umarnaina, da salamarku ta zama kamar kogi, adalcinku kamar raƙuman teku. ");
INSERT INTO hausa_vpl VALUES ("IS48_19","024_48_19","ISA","48","19","19","Da zuriyarku ta zama kamar yashi, ’ya’yanku kamar tsabar hatsin da ba a iya ƙidayawa; da ba za a taɓa yanke sunansu balle a hallaka su daga gabana ba.” ");
INSERT INTO hausa_vpl VALUES ("IS48_20","024_48_20","ISA","48","20","20","Ku bar Babilon, ku gudu daga Babiloniyawa! Ku yi shelar wannan da sowa ta farin ciki ku kuma furta shi. Ku aika shi zuwa iyakokin duniya; ku ce, “Ubangiji ya fanshi bawansa Yaƙub.” ");
INSERT INTO hausa_vpl VALUES ("IS48_21","024_48_21","ISA","48","21","21","Ba su ji ƙishi ba sa’ad da ya bishe su a cikin hamada; ya sa ruwa ya malalo dominsu daga dutse; ya tsage dutse ruwa kuwa ya kwararo. ");
INSERT INTO hausa_vpl VALUES ("IS48_22","024_48_22","ISA","48","22","22","“Babu salama ga mugaye” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS49_1","024_49_1","ISA","49","1","1","Ku kasa kunne gare ni, ku tsibirai; ku ji wannan, ku al’ummai masu nesa. Kafin a haife Ni Ubangiji ya kira ni; tun daga haihuwata ya ambaci sunana. ");
INSERT INTO hausa_vpl VALUES ("IS49_2","024_49_2","ISA","49","2","2","Ya yi bakina kamar takobi mai kaifi, cikin inuwar hannunsa ya ɓoye ni; ya sa na zama kamar kibiya mai tsini ya kuma ɓoye ni cikin kwarinsa. ");
INSERT INTO hausa_vpl VALUES ("IS49_3","024_49_3","ISA","49","3","3","Ya ce mini, “Kai bawana ne, Isra’ila, a cikinka zan bayyana darajata.” ");
INSERT INTO hausa_vpl VALUES ("IS49_4","024_49_4","ISA","49","4","4","Amma na ce, “Na yi aiki a banza; na kashe duk ƙarfina a banza da wofi. Duk da haka abin da yake nawa yana a hannun Ubangiji, ladana kuma tana a wurin Allahna.” ");
INSERT INTO hausa_vpl VALUES ("IS49_5","024_49_5","ISA","49","5","5","Yanzu fa Ubangiji ya ce ya siffanta ni a cikin mahaifa don in zama bawansa don in dawo da Yaƙub gare shi in kuma tattara Isra’ila gare shi, gama an girmama ni a gaban Ubangiji Allahna kuma ne ƙarfina ");
INSERT INTO hausa_vpl VALUES ("IS49_6","024_49_6","ISA","49","6","6","ya ce, “Ɗan ƙaramin abu ne ka zama bawana don ka maido da kabilar Yaƙub ka kuma dawo da waɗannan na Isra’ilawan da na kiyaye. Zan kuma mai da kai haske ga Al’ummai, don ka kawo cetona zuwa iyakokin duniya.” ");
INSERT INTO hausa_vpl VALUES ("IS49_7","024_49_7","ISA","49","7","7","Ga abin da Ubangiji yana cewa, Mai Fansa da kuma Mai Tsarkin nan na Isra’ila gare shi wanda al’ummai suka rena suka kuma ki, ga bawan masu mulki. “Sarakuna za su gan ka su kuma miƙe tsaye, sarakuna za su gani su kuma rusuna, saboda Ubangiji, wanda yake mai aminci, Mai Tsarkin nan na Isra’ila, wanda ya zaɓe ka.” ");
INSERT INTO hausa_vpl VALUES ("IS49_8","024_49_8","ISA","49","8","8","Ga abin da Ubangiji yana cewa, “A lokacin tagomashina zan amsa muku, kuma a ranar ceto zan taimake ku; zan kiyaye ku zan kuma sa ku zama alkawari ga mutane, don ku maido da ƙasa ku kuma sāke raba gādon kufai, ");
INSERT INTO hausa_vpl VALUES ("IS49_9","024_49_9","ISA","49","9","9","don ku ce wa waɗanda suke cikin kurkuku, ‘Ku fito,’ ga waɗanda suke cikin duhu kuma, ‘Ku ’yantu!’ “Za su yi kiwo kusa da hanyoyi su kuma sami wurin kiwo a kowane tudu. ");
INSERT INTO hausa_vpl VALUES ("IS49_10","024_49_10","ISA","49","10","10","Ba za su taɓa jin yunwa ko ƙishi ba, ba kuwa zafin hamada ko rana ta buge su ba. Shi da ya yi musu jinƙai zai jagorance su ya kuma bishe su kusa da maɓulɓulan ruwa. ");
INSERT INTO hausa_vpl VALUES ("IS49_11","024_49_11","ISA","49","11","11","Zan mayar da dukan duwatsu su zama hanyoyi, a kuma gyara manyan hanyoyina. ");
INSERT INTO hausa_vpl VALUES ("IS49_12","024_49_12","ISA","49","12","12","Duba, za su zo daga nesa waɗansu daga arewa, waɗansu daga yamma, waɗansu daga yankin Aswan.” ");
INSERT INTO hausa_vpl VALUES ("IS49_13","024_49_13","ISA","49","13","13","Ku yi sowa don farin ciki, ya ku sammai; ki yi farin ciki, ya ke duniya; ku ɓarke da waƙa, ya ku duwatsu! Gama Ubangiji ya ta’azantar da mutanensa zai kuma ji tausayin mutanensa da suke shan wahala. ");
INSERT INTO hausa_vpl VALUES ("IS49_14","024_49_14","ISA","49","14","14","Amma Sihiyona ta ce, “Ubangiji ya yashe ni, Ubangiji ya manta da ni.” ");
INSERT INTO hausa_vpl VALUES ("IS49_15","024_49_15","ISA","49","15","15","“Yana yiwuwa mahaifiya ta manta da jariri a ƙirjinta ta kuma kāsa nuna tausayi ga yaron da ta haifa? Mai yiwuwa ta manta, amma ba zan taɓa manta da ke ba! ");
INSERT INTO hausa_vpl VALUES ("IS49_16","024_49_16","ISA","49","16","16","Duba, na zāna ki a tafin hannuwana; katangarki kullum suna a gabana. ");
INSERT INTO hausa_vpl VALUES ("IS49_17","024_49_17","ISA","49","17","17","’Ya’yanki maza su komo da gaggawa, waɗanda suka lalatar da ke kuwa za su bar ki. ");
INSERT INTO hausa_vpl VALUES ("IS49_18","024_49_18","ISA","49","18","18","Ki ɗaga idanunki ki duba kewaye; dukan ’ya’yanki sun taru suka kuma dawo gare ki. Muddin ina raye,” in ji Ubangiji, “Za ki yafa su duka kamar kayan ado; za ki yi ado da su, kamar amarya. ");
INSERT INTO hausa_vpl VALUES ("IS49_19","024_49_19","ISA","49","19","19","“Ko da yake an lalatar da ke aka kuma mai da ke kufai ƙasarki kuma ta zama kango, yanzu za ki kāsa sosai saboda yawan mutanenki, kuma waɗanda suka cinye ki za su kasance can da nisa. ");
INSERT INTO hausa_vpl VALUES ("IS49_20","024_49_20","ISA","49","20","20","’Ya’yan da aka haifa a lokacin baƙin cikinki za su ce a kunnenki, ‘Wannan wuri ya yi mana kaɗan ƙwarai; ki ƙara mana wurin zama.’ ");
INSERT INTO hausa_vpl VALUES ("IS49_21","024_49_21","ISA","49","21","21","Sa’an nan za ki ce a zuciyarki, ‘Wa ya haifa waɗannan? Na yi baƙin ciki na kuma zama wadda ba ta haihuwa; an yi mini daurin talala aka kuma ƙi ni. Wane ne ya yi renon waɗannan? An bar ni ni kaɗai, amma waɗannan, ina suka fito?’ ” ");
INSERT INTO hausa_vpl VALUES ("IS49_22","024_49_22","ISA","49","22","22","Ga abin da Ubangiji Mai Iko Duka ya ce, “Duba, zan yi alama wa Al’ummai, zan ɗaga tutana wa mutane; za su kawo ’ya’yanki maza a hannuwansu su riƙe ’ya’yanki mata a kafaɗunsu. ");
INSERT INTO hausa_vpl VALUES ("IS49_23","024_49_23","ISA","49","23","23","Sarakuna za su zama kamar iyayen reno, sarauniyoyinsu kuma za su yi renonku kamar uwaye. Za su rusuna a gabanki da fuskokinsu har ƙasa; za su lashe ƙura a ƙafafunki. Sa’an nan za ki san cewa ni ne Ubangiji; waɗanda suke sa zuciya gare ni ba za su sha kunya ba.” ");
INSERT INTO hausa_vpl VALUES ("IS49_24","024_49_24","ISA","49","24","24","Za a iya ƙwace ganima daga jarumawa, ko a kuɓutar da kamammu daga hannun marasa tsoro? ");
INSERT INTO hausa_vpl VALUES ("IS49_25","024_49_25","ISA","49","25","25","Amma ga abin da Ubangiji yana cewa, “I, za a ƙwace kamammu daga jarumawa, a kuma karɓe ganima daga hannun marasa tsoro; zan gwabza da waɗanda suke gwabzawa da ke, zan kuwa ceci ’ya’yanki. ");
INSERT INTO hausa_vpl VALUES ("IS49_26","024_49_26","ISA","49","26","26","Zan sa masu zaluntarki su ci naman jikinsu; za su bugu da jininsu, sai ka ce sun sha ruwan inabi. Sa’an nan dukan mutane za su sani cewa ni, Ubangiji, ni ne Mai Cetonki, Mai Fansarki, Maɗaukakin nan na Yaƙub.” ");
INSERT INTO hausa_vpl VALUES ("IS50_1","024_50_1","ISA","50","1","1","Ga abin da Ubangiji yana cewa, “Ina takardar shaida na saki mahaifiyarka daga aure wadda na kora? Ko kuwa ga wanda mutumin da nake bin bashi ne na sayar da kai? Saboda zunubanka aka sayar da kai; saboda laifofinka ne ya sa aka kori mahaifiyarka. ");
INSERT INTO hausa_vpl VALUES ("IS50_2","024_50_2","ISA","50","2","2","Sa’ad da na zo, me ya sa babu kowa? Sa’ad da na yi kira, me ya sa babu wani da ya amsa? Hannuna ya kāsa ne sosai don fansarka? Na rasa ƙarfin kuɓutar da kai ne? Ta wurin tsawatawa kawai na busar da teku, na mai da koguna hamada; kifayensu duk sun ruɓe saboda rashin ruwa suka kuma mutu saboda ƙishi. ");
INSERT INTO hausa_vpl VALUES ("IS50_3","024_50_3","ISA","50","3","3","Na suturar da sararin sama da duhu na kuma mai da tsummoki abin rufuwarsa.” ");
INSERT INTO hausa_vpl VALUES ("IS50_4","024_50_4","ISA","50","4","4","Ubangiji Mai Iko Duka ya ba ni harshen umarni, don in san maganar da za tă ƙarfafa gajiyayye. Ya farkar da ni da safe, ya farkar da kunnena don in saurara kamar wanda ake koya masa. ");
INSERT INTO hausa_vpl VALUES ("IS50_5","024_50_5","ISA","50","5","5","Ubangiji Mai Iko Duka ya buɗe kunnuwana, kuma ban yi tayarwa ba; ban ja da baya ba. ");
INSERT INTO hausa_vpl VALUES ("IS50_6","024_50_6","ISA","50","6","6","Na ba da bayana ga masu dūkana, kumatuna ga masu jan gemuna; ban ɓoye fuskata daga masu ba’a da masu tofa mini miyau ba. ");
INSERT INTO hausa_vpl VALUES ("IS50_7","024_50_7","ISA","50","7","7","Gama Ubangiji Mai Iko Duka zai taimake ni, ba zan sha kunya ba. Saboda haka na kafa fuskata kamar dutsen ƙanƙara, na kuma sani ba zan sha kunya ba. ");
INSERT INTO hausa_vpl VALUES ("IS50_8","024_50_8","ISA","50","8","8","Gama shi da zai tabbatar da ni, marar laifi ne yana kusa. Wane ne zai kawo ƙararraki game da ni? Bari mu je ɗakin shari’a tare! Wane ne mai zargina? Bari yă kalubalance ni! ");
INSERT INTO hausa_vpl VALUES ("IS50_9","024_50_9","ISA","50","9","9","Ubangiji Mai Iko Duka ne zai taimake ni. Wane ne zai iya tabbatar da ni mai laifi? Duk za su koɗe kamar riga; asu za su cinye su. ");
INSERT INTO hausa_vpl VALUES ("IS50_10","024_50_10","ISA","50","10","10","Wane ne a cikinku yake tsoron Ubangiji yana kuma yin biyayya ga maganar bawansa? Bari wanda yake tafiya cikin duhu, wanda ba shi da haske, ya dogara a sunan Ubangiji ya kuma dogara ga Allahnsa. ");
INSERT INTO hausa_vpl VALUES ("IS50_11","024_50_11","ISA","50","11","11","Amma yanzu fa, dukanku waɗanda kuke ƙuna wuta kuna kuma tanada wa kanku fitilu masu ci, ku je ku yi tafiya a cikin hasken wutarku da na fitilun da kuka ƙuna. Abin da za ku karɓa ke nan daga hannuna. Za ku kwanta a cikin azaba. ");
INSERT INTO hausa_vpl VALUES ("IS51_1","024_51_1","ISA","51","1","1","“Ku kasa kunne gare ni, ku da kuna neman adalci kuke kuma neman Ubangiji. Dubi dutse daga inda aka yanke ku da kuma mahaƙar duwatsu inda aka fafe ku; ");
INSERT INTO hausa_vpl VALUES ("IS51_2","024_51_2","ISA","51","2","2","dubi Ibrahim, mahaifinku, da Saratu, wadda ta haife ku. Sa’ad da na kira shi kaɗai ne, na kuma albarkace shi na kuma mai da shi da yawa. ");
INSERT INTO hausa_vpl VALUES ("IS51_3","024_51_3","ISA","51","3","3","Tabbatacce Ubangiji zai ta’azantar da Sihiyona zai kuma duba da tausayi a kan dukan kufanta; zai sa hamadanta ta zama kamar Eden, ƙeƙasasshiyar ƙasarta kamar lambun Ubangiji. Za a sami farin ciki da murna a cikinta, godiya da ƙarar rerawa. ");
INSERT INTO hausa_vpl VALUES ("IS51_4","024_51_4","ISA","51","4","4","“Ku kasa kunne gare ni, mutanena; ku ji ni, al’ummata. Doka za tă fito daga gare ni; shari’ata za tă zama haske ga al’ummai. ");
INSERT INTO hausa_vpl VALUES ("IS51_5","024_51_5","ISA","51","5","5","Adalcina na zuwa da sauri, cetona yana a kan hanya, hannuna kuma zai kawo adalci ga al’ummai. Tsibirai za su dube ni su kuma jira da sa zuciya don hannuna. ");
INSERT INTO hausa_vpl VALUES ("IS51_6","024_51_6","ISA","51","6","6","Ku daga idanunku zuwa sammai ku dubi duniya a ƙasa; sammai za su ɓace kamar hayaƙi, duniya za tă shuɗe kamar riga mazaunanta kuma su mutu kamar ƙudaje. Amma cetona zai dawwama har abada, adalcina ba zai taɓa kāsa ba. ");
INSERT INTO hausa_vpl VALUES ("IS51_7","024_51_7","ISA","51","7","7","“Ku ji ni, ku da kuka san abin da yake daidai, ku mutanen da kuke da dokata a zukatanku. Kada ku ji tsoron ba’ar da mutane suke yi ko ku firgita saboda zargin da suke yi. ");
INSERT INTO hausa_vpl VALUES ("IS51_8","024_51_8","ISA","51","8","8","Gama asu za su cinye su kamar riga; tsutsotsi za su cinye su kamar ulu. Amma adalcina zai dawwama har abada, cetona har dukan zamanai.” ");
INSERT INTO hausa_vpl VALUES ("IS51_9","024_51_9","ISA","51","9","9","Ka tashi, ka tashi! Ka yafa wa kanka ƙarfi, Ya hannun Ubangiji; ka farka, kamar a kwanakin da suka wuce, kamar a zamanai na dā. Ba kai ba ne wanda ya yayyanka Rahab gunduwa-gunduwa, wanda ya soki dodon ruwan nan? ");
INSERT INTO hausa_vpl VALUES ("IS51_10","024_51_10","ISA","51","10","10","Ba kai ba ne ka busar da teku, ka busar da ruwan zurfafa masu girma, wanda ya yi hanya a cikin zurfafan teku saboda fansassu su ƙetare? ");
INSERT INTO hausa_vpl VALUES ("IS51_11","024_51_11","ISA","51","11","11","Waɗanda Ubangiji ya fansar za su dawo. Za su shiga Sihiyona da waƙoƙi; madawwamin farin ciki zai rufe kansu da rawani. Murna da farin ciki zai cika su, baƙin ciki da nishi zai ɓace. ");
INSERT INTO hausa_vpl VALUES ("IS51_12","024_51_12","ISA","51","12","12","“Ni kaɗai ne na ta’azantar da ku. Wane ne ku da kuke tsoron mutane masu mutuwa, ’ya’yan mutane waɗanda suke ciyawa ne kawai, ");
INSERT INTO hausa_vpl VALUES ("IS51_13","024_51_13","ISA","51","13","13","har da kuka manta da Ubangiji Mahaliccinku, wanda ya shimfiɗa sammai ya kuma kafa harsashen duniya, har kuna zama da tsoro kowace rana saboda fushin masu zalunci, waɗanda sun ƙudura sai sun hallaka? Gama ina fushin mai zalunci? ");
INSERT INTO hausa_vpl VALUES ("IS51_14","024_51_14","ISA","51","14","14","Ba da daɗewa za a ’yantar da ’yan kurkuku; ba za su mutu a kurkuku ba, ba kuwa za su rasa abinci ba. ");
INSERT INTO hausa_vpl VALUES ("IS51_15","024_51_15","ISA","51","15","15","Gama ni ne Ubangiji Allahnku, wanda ya dama teku domin raƙumansa su yi ruri, Ubangiji Maɗaukaki ne sunansa. ");
INSERT INTO hausa_vpl VALUES ("IS51_16","024_51_16","ISA","51","16","16","Na sa maganata a bakinka na kuma rufe ka da inuwar hannuna, Na shimfiɗa sammai, na kafa harsashen duniya, na kuma ce wa Sihiyona, ‘Ku mutanena ne.’ ” ");
INSERT INTO hausa_vpl VALUES ("IS51_17","024_51_17","ISA","51","17","17","Ki farka, ki farka! Ki tashi, ya Urushalima, ke da kika sha daga hannun Ubangiji kwaf na fushinsa, ke da kika shanye har ƙasar kwaf kwaf da ya sa mutane suna tangaɗi. ");
INSERT INTO hausa_vpl VALUES ("IS51_18","024_51_18","ISA","51","18","18","Cikin dukan ’ya’yan da ta haifa; cikin dukan ’ya’yan da ta yi reno babu wani da zai kama hannunta. ");
INSERT INTO hausa_vpl VALUES ("IS51_19","024_51_19","ISA","51","19","19","Waɗannan masifu riɓi biyu sun auko miki, wa zai ta’azantar da ke? Lalaci da hallaka, yunwa da takobi, wa zai ƙarfafa ki? ");
INSERT INTO hausa_vpl VALUES ("IS51_20","024_51_20","ISA","51","20","20","’Ya’yanki sun sume; sun kwanta kusurwar kowane titi, kamar barewar da aka kama da tarko. Sun cika da fushin Ubangiji da kuma tsawatawar Allahnki. ");
INSERT INTO hausa_vpl VALUES ("IS51_21","024_51_21","ISA","51","21","21","Saboda haka ki ji wannan, ke mai wahala, wadda ta bugu, amma ba da ruwan inabi. ");
INSERT INTO hausa_vpl VALUES ("IS51_22","024_51_22","ISA","51","22","22","Ga abin da Ubangiji Mai Iko Duka yana cewa, Allahnki, wanda ya kāre mutanensa, “Duba, na ƙwace daga hannunki kwaf da ya sa ki tangaɗi; daga wannan kwaf, kwaf na fushina, ba za ki ƙara sha ba. ");
INSERT INTO hausa_vpl VALUES ("IS51_23","024_51_23","ISA","51","23","23","Zan sa shi a hannuwan masu gwada miki azaba, waɗanda suke ce miki, ‘Fāɗi rubda ciki don mu iya taka a kanki.’ Kika kuma mai da bayanki kamar ƙasa, kamar titin da ake takawa a kai.” ");
INSERT INTO hausa_vpl VALUES ("IS52_1","024_52_1","ISA","52","1","1","Ki farka, ki farka, ya Sihiyona, ki sanya wa kanki ƙarfi. Ki sa rigarki na daraja, Ya Urushalima, birni mai tsarki. Marasa kaciya da maƙazanta ba za su shi cikinki ba. ");
INSERT INTO hausa_vpl VALUES ("IS52_2","024_52_2","ISA","52","2","2","Ki kakkaɓe ƙurarki; ki tashi, ki zauna a kursiyinki, ya Urushalima. Ki ’yantar da kanki daga sarƙoƙi a wuyanki, Ke kamammiyar Diyar Sihiyona. ");
INSERT INTO hausa_vpl VALUES ("IS52_3","024_52_3","ISA","52","3","3","Gama ga abin Ubangiji yana cewa, “An sayar da ke ba da kuɗi ba, kuma ba da kuɗi za a fanshe ki ba.” ");
INSERT INTO hausa_vpl VALUES ("IS52_4","024_52_4","ISA","52","4","4","Gama ga abin da Ubangiji Mai Iko Duka yana cewa, “Da farko mutanena suka gangara zuwa Masar don su zauna; a baya-bayan nan, Assuriya sun zalunce su. ");
INSERT INTO hausa_vpl VALUES ("IS52_5","024_52_5","ISA","52","5","5","“Yanzu kuma me nake da shi a nan?” In ji Ubangiji. “Gama an kwashe mutanena ba a bakin kome ba kuma waɗanda suka mallake su sun yi musu ba’a, Kullum ana cin gaba da yin wa sunana saɓo. ");
INSERT INTO hausa_vpl VALUES ("IS52_6","024_52_6","ISA","52","6","6","Saboda haka mutanena za su san sunana; saboda haka a wannan rana za su san cewa ni ne wanda ya faɗa wannan. I, ni ne.” ");
INSERT INTO hausa_vpl VALUES ("IS52_7","024_52_7","ISA","52","7","7","Me ya fi wannan kyau a kan duwatsu a ga ƙafafu na masu kawo labari mai daɗi waɗanda suke shelar salama, waɗanda suke kawo labari mai daɗi, waɗanda suke shelar ceto, waɗanda suke ce wa Sihiyona, “Allahnki yana mulki!” ");
INSERT INTO hausa_vpl VALUES ("IS52_8","024_52_8","ISA","52","8","8","Ki kasa kunne! Masu tsaronki sun tā da muryoyinsu; tare sun yi sowa ta farin ciki. Sa’ad da Ubangiji ya komo Sihiyona, za su gan shi da idanunsu. ");
INSERT INTO hausa_vpl VALUES ("IS52_9","024_52_9","ISA","52","9","9","Ku ɓarke cikin waƙoƙin farin ciki gaba ɗaya, kangonki na Urushalima, gama Ubangiji ya ta’azantar da mutanensa, ya fanshi Urushalima. ");
INSERT INTO hausa_vpl VALUES ("IS52_10","024_52_10","ISA","52","10","10","Ubangiji zai nuna hannunsa mai tsarki a fili a idanun dukan al’ummai, da kuma dukan iyakokin duniya za su gani ceton Allahnmu. ");
INSERT INTO hausa_vpl VALUES ("IS52_11","024_52_11","ISA","52","11","11","Ku fita, ku fita daga can! Kada ku taɓa wani abu marar tsarki! Ku fita daga cikinta ku zama da tsarki, ku da kuke ɗaukan kayan aikin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS52_12","024_52_12","ISA","52","12","12","Amma ba za ku fita a gaggauce ba ko ku tafi da gudu; gama Ubangiji zai ja gabanku, Allah na Isra’ila zai kasance mai tsaron bayanku. ");
INSERT INTO hausa_vpl VALUES ("IS52_13","024_52_13","ISA","52","13","13","Duba, bawana zai aikata abubuwa da hikima; za a tā da shi a kuma ɗaga shi da ɗaukaka ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("IS52_14","024_52_14","ISA","52","14","14","Kamar dai yadda aka kasance da mutane masu yawa waɗanda suka giggice sa’ad da suka gan shi, kamanninsa ya lalace ƙwarai fiye da na kowane mutum siffarsa kuma ta yi muni fiye da yadda ta mutum take, ");
INSERT INTO hausa_vpl VALUES ("IS52_15","024_52_15","ISA","52","15","15","haka zai ba al’ummai masu yawa mamaki, sarakuna kuma za su riƙe bakunansu don mamaki. Gama abin da ba a faɗa musu ba, shi za su gani, kuma abin da ba su ji ba, shi za su fahimta. ");
INSERT INTO hausa_vpl VALUES ("IS53_1","024_53_1","ISA","53","1","1","Wa ya gaskata saƙonmu kuma ga wa hannun Ubangiji ya bayyana? ");
INSERT INTO hausa_vpl VALUES ("IS53_2","024_53_2","ISA","53","2","2","Ya yi girma kamar dashe marar ƙarfi, kamar saiwa kuma daga ƙeƙasasshiyar ƙasa. Ba shi da kyan gani ko wani makamin da zai ja hankalinmu, babu wani abin da yake da shi da zai sa mu yi sha’awarsa. ");
INSERT INTO hausa_vpl VALUES ("IS53_3","024_53_3","ISA","53","3","3","Mutane suka rena shi suka ƙi shi, mutum ne cike da baƙin ciki, ya kuma saba da wahala. Kamar wanda mutane suna ɓuya fuskokinsu daga gare shi aka rena shi aka yi banza da shi. ");
INSERT INTO hausa_vpl VALUES ("IS53_4","024_53_4","ISA","53","4","4","Tabbatacce ya ɗauki cututtukanmu ya kuma daure da baƙin cikinmu duk da haka muka ɗauka Allah ya hukunta shi ne, ya buge shi ya kuma sa ya sha azaba. ");
INSERT INTO hausa_vpl VALUES ("IS53_5","024_53_5","ISA","53","5","5","Amma aka yi masa rauni saboda laifofinmu, aka ƙuje shi saboda kurakuranmu; hukuncin da ya kawo mana salama ya kasance a kansa, kuma ta wurin mikinsa ya sa muka warke. ");
INSERT INTO hausa_vpl VALUES ("IS53_6","024_53_6","ISA","53","6","6","Dukanmu, muna kama da tumakin da suka ɓata, kowannenmu ya kama hanyarsa; Ubangiji kuwa ya sa hukunci ya auko a kansa hukuncin da ya wajaba a kanmu. ");
INSERT INTO hausa_vpl VALUES ("IS53_7","024_53_7","ISA","53","7","7","Aka wulaƙanta shi aka kuma yi masa azaba, duk da haka bai buɗe bakinsa ba; aka kai shi kamar ɗan rago zuwa wurin yanka, kuma kamar tunkiya a gaban masu askinta tana shiru, haka bai buɗe bakinsa ba. ");
INSERT INTO hausa_vpl VALUES ("IS53_8","024_53_8","ISA","53","8","8","Da wulaƙanci da kuma hukunci aka ɗauke shi aka tafi. Wa kuwa zai yi maganar zuriyarsa? Gama an kawar da shi daga ƙasar masu rai; saboda laifin mutanena aka kashe shi. ");
INSERT INTO hausa_vpl VALUES ("IS53_9","024_53_9","ISA","53","9","9","Aka yi jana’izarsa tare da mugaye, aka binne shi tare da masu arziki, ko da yake bai taɓa yin wani tashin hankali ba, ko a sami ƙarya a bakinsa. ");
INSERT INTO hausa_vpl VALUES ("IS53_10","024_53_10","ISA","53","10","10","Duk da haka nufin Ubangiji ne a ƙuje shi yă kuma sa yă sha wahala, kuma ko da yake Ubangiji ya sa ransa ya zama hadaya don zunubi, zai ga zuriyarsa zai kuma kawo masa tsawon rai, nufin Ubangiji kuma zai yi nasara a hannunsa. ");
INSERT INTO hausa_vpl VALUES ("IS53_11","024_53_11","ISA","53","11","11","Bayan wahalar ransa, zai ga hasken rai, ya kuma gamsu; ta wurin saninsa bawana mai adalci zai ’yantar da mutane masu yawa, zai kuma ɗauki laifofinsu. ");
INSERT INTO hausa_vpl VALUES ("IS53_12","024_53_12","ISA","53","12","12","Saboda haka zan ba shi rabo tare da manya, zai kuma raba ganima tare da masu ƙarfi, domin ya ba da ransa har mutuwa, aka kuma lissafta shi tare da masu laifofi. Gama ya ɗauki zunubin mutane masu yawa, ya kuma yi roƙo saboda laifofinsu. ");
INSERT INTO hausa_vpl VALUES ("IS54_1","024_54_1","ISA","54","1","1","“Ki rera, ya ke bakararriya, ke da ba ki taɓa haihuwa ba; ki ɓarke da waƙa, ki yi sowa don farin ciki, ke da ba ki taɓa naƙuda ba; domin ’ya’yan mace mai kaɗaici sun fi na mai miji yawa,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS54_2","024_54_2","ISA","54","2","2","“Ki fadada wurin tentinki, ki miƙe labulen tentinki da fāɗi, kada ki janye; ƙara tsawon igiyoyinta, ki kuma ƙara ƙarfin turakunta. ");
INSERT INTO hausa_vpl VALUES ("IS54_3","024_54_3","ISA","54","3","3","Gama za ki fadada zuwa dama da hagu; zuriyarki za su kori al’ummai su kuma zauna a kufan biranensu. ");
INSERT INTO hausa_vpl VALUES ("IS54_4","024_54_4","ISA","54","4","4","“Kada ki ji tsoro; ba za ki sha kunya ba. Kada ki ji tsoron wulaƙanci, ba za a ƙasƙantar da ke ba. Za ki manta da kunyar ƙuruciyarki ba kuwa za ki tuna da zargin zaman gwauruwarki ba. ");
INSERT INTO hausa_vpl VALUES ("IS54_5","024_54_5","ISA","54","5","5","Gama Mahaliccinki shi ne mijinki, Ubangiji Maɗaukaki ne sunansa, Mai Tsarkin nan na Isra’ila ne Mai Fansarki; ana ce da shi Allahn dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("IS54_6","024_54_6","ISA","54","6","6","Ubangiji zai kira sai ka ce ke mace ce da aka yashe ta tana kuma damuwa a ranta, macen da ta yi aure a ƙuruciya, sai kawai aka ƙi ta,” in ji Allahnki. ");
INSERT INTO hausa_vpl VALUES ("IS54_7","024_54_7","ISA","54","7","7","“Gama a ɗan ƙanƙanen lokaci na rabu da ke, amma da ƙauna mai zurfi zan sāke dawo da ke. ");
INSERT INTO hausa_vpl VALUES ("IS54_8","024_54_8","ISA","54","8","8","Cikin fushi mai zafi na ɓoye fuskata daga gare ki na ɗan lokaci, amma da madawwamin alheri zan ji tausayinki,” in ji Ubangiji Mai Fansarki. ");
INSERT INTO hausa_vpl VALUES ("IS54_9","024_54_9","ISA","54","9","9","“A gare ni wannan ya yi kamar kwanakin Nuhu, sa’ad da na rantse cewa ruwan Nuhu ba za su ƙara rufe duniya ba. Yanzu fa na rantse ba zan yi fushi da ke ba, ba zan ƙara tsawata miki kuma ba. ");
INSERT INTO hausa_vpl VALUES ("IS54_10","024_54_10","ISA","54","10","10","Ko da duwatsu za su girgiza a kuma tumɓuke tuddai, duk da haka madawwamiyar ƙaunata da nake yi miki ba za tă jijjigu ba ba kuwa za a kawar da alkawarin salamata ba,” in ji Ubangiji, wanda ya ji tausayinki. ");
INSERT INTO hausa_vpl VALUES ("IS54_11","024_54_11","ISA","54","11","11","“Ya ke birni mai shan azaba, wadda hadari ya bulale ki ba a kuma ta’azantar da ke ba, zan gina ke da duwatsu turkuwoyis, zan kafa harsashenki da duwatsun saffaya. ");
INSERT INTO hausa_vpl VALUES ("IS54_12","024_54_12","ISA","54","12","12","Zan gina hasumiyarki da jan yakutu, ƙofofinki kuma da duwatsu masu haske, dukan katangarki kuma da duwatsu masu daraja. ");
INSERT INTO hausa_vpl VALUES ("IS54_13","024_54_13","ISA","54","13","13","Ubangiji zai koya wa dukan ’ya’yanki maza, da girma kuma salamar ’ya’yanki zai zama. ");
INSERT INTO hausa_vpl VALUES ("IS54_14","024_54_14","ISA","54","14","14","Da adalci za a kafa ke. Zalunci zai yi nesa da ke; ba za ki kasance da wani abin da za ki ji tsoro ba. Za a kawar da duk wani abin banrazana; ba zai yi kusa da ke ba. ");
INSERT INTO hausa_vpl VALUES ("IS54_15","024_54_15","ISA","54","15","15","In wani ya far miki, ba daga wurina ba ne; duk wanda ya far miki zai miƙa wuya gare ki. ");
INSERT INTO hausa_vpl VALUES ("IS54_16","024_54_16","ISA","54","16","16","“Duba, ni ne wanda na halicci maƙeri wanda yake zuga garwashi ya zama harshen wuta ya kuma ƙera makamin da ya dace da aikinsa. Ni ne kuma na halicci mai hallakarwa ya yi ɓarna; ");
INSERT INTO hausa_vpl VALUES ("IS54_17","024_54_17","ISA","54","17","17","ba makamin da aka ƙera don yă cuce ki da zai yi nasara, za ki kuma mayar da magana ga duk wanda ya zarge ki. Wannan ne gādon bayin Ubangiji, kuma wannan ita ce nasararsu daga gare ni,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS55_1","024_55_1","ISA","55","1","1","“Ku zo, dukanku masu jin ƙishi, ku zo wurin ruwaye; ku kuma da ba ku da kuɗi, ku zo, ku saya ku kuma ci! Ku zo, ku saya ruwan inabi da madara ba tare da kuɗi ba ba za ku kuma biya kome ba. ");
INSERT INTO hausa_vpl VALUES ("IS55_2","024_55_2","ISA","55","2","2","Don me za ku kashe kuɗi a kan abin da ba abinci ba, ku kuma yi wahala a kan abin da ba za ku ƙoshi ba? Ku saurara, ku saurare ni, ku kuma ci abin da yake da kyau, ranku kuma zai ji daɗin abinci mafi kyau. ");
INSERT INTO hausa_vpl VALUES ("IS55_3","024_55_3","ISA","55","3","3","Ku kasa kunne ku kuma zo gare ni; ku saurare ni, don ranku ya rayu. Zan yi madawwamin alkawari da ku, zan nuna muku ƙaunata marar ƙarewa da na yi wa Dawuda alkawari. ");
INSERT INTO hausa_vpl VALUES ("IS55_4","024_55_4","ISA","55","4","4","Duba, na mai da shi shaida ga mutane, shugaba da kuma jagorar mutane. ");
INSERT INTO hausa_vpl VALUES ("IS55_5","024_55_5","ISA","55","5","5","Tabbatacce za ku kira al’umman da ba ku sani ba, kuma al’umman da ba ku sani ba za su sheƙo a guje zuwa wurinku, saboda Ubangiji Allahnku, Mai Tsarkin nan na Isra’ila, gama ya darjanta ku.” ");
INSERT INTO hausa_vpl VALUES ("IS55_6","024_55_6","ISA","55","6","6","Ku nemi Ubangiji tun yana samuwa; ku yi kira gare shi tun yana kusa. ");
INSERT INTO hausa_vpl VALUES ("IS55_7","024_55_7","ISA","55","7","7","Bari mugu ya bar irin halinsa mugu kuma ya sāke irin tunaninsa. Bari yă juyo ga Ubangiji, zai kuwa ji tausayinsa, ya juyo ga Allahnmu kuma, gama shi mai gafartawa ne a sauƙaƙe. ");
INSERT INTO hausa_vpl VALUES ("IS55_8","024_55_8","ISA","55","8","8","“Gama tunanina ba tunaninku ba ne, yadda kuke yin abubuwa ba yadda nake yin abubuwa ba ne,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS55_9","024_55_9","ISA","55","9","9","“Kamar yadda sammai suke can nesa da ƙasa, haka yadda nake yin abubuwa suke dabam da yadda kuke yin abubuwa tunanina kuma dabam da naku. ");
INSERT INTO hausa_vpl VALUES ("IS55_10","024_55_10","ISA","55","10","10","Kamar yadda ruwan sama da dusar ƙanƙara suke saukowa daga sama, ba sa komowa ba tare da sun jiƙe duniya sun kuma sa su yi ’ya’ya su kuma yi toho, don su ba da iri ga mai shuki da kuma abinci ga mai ci, ");
INSERT INTO hausa_vpl VALUES ("IS55_11","024_55_11","ISA","55","11","11","haka maganata da take fitowa daga bakina. Ba za tă koma gare ni wofi ba, amma za tă cika abin da nake so ta kuma cika abin da na aike ta tă yi. ");
INSERT INTO hausa_vpl VALUES ("IS55_12","024_55_12","ISA","55","12","12","Za ku fita da farin ciki a kuma bi da ku da salama; duwatsu da tuddai za su ɓarke da waƙa a gabanku, dukan itatuwan jeji kuma za su tafa hannuwansu. ");
INSERT INTO hausa_vpl VALUES ("IS55_13","024_55_13","ISA","55","13","13","A maimakon sarƙaƙƙiya, itacen fir ne zai tsiro, a maimakon ƙayayyuwa kuma, itacen ci-zaƙi ne zai tsiro. Wannan zai zama matuni na abin da Ni Ubangiji na yi, madawwamiyar alama ce, wadda ba za a datse ba.” ");
INSERT INTO hausa_vpl VALUES ("IS56_1","024_56_1","ISA","56","1","1","Ga abin da Ubangiji yana cewa, “Ku riƙe gaskiya ku yi abin da yake daidai, gama cetona yana kusa za a kuma bayyana adalcina nan da nan. ");
INSERT INTO hausa_vpl VALUES ("IS56_2","024_56_2","ISA","56","2","2","Mai albarka ne mutumin da ya aikata wannan, mutumin da ya riƙe kam yana kiyaye Asabbaci ba tare da ƙazantar da shi ba, yana kuma kiyaye kansa daga yin mugun abu.” ");
INSERT INTO hausa_vpl VALUES ("IS56_3","024_56_3","ISA","56","3","3","Kada baƙon da ya miƙa kansa ga Ubangiji ya ce, “Ai Ubangiji zai ware ni daga mutanensa.” Kada kuma wani bābā ya yi gunaguni cewa, “Ni busasshen itace ne kawai.” ");
INSERT INTO hausa_vpl VALUES ("IS56_4","024_56_4","ISA","56","4","4","Gama ga abin da Ubangiji ya faɗa, “Wa bābānnin da suna kiyaye Asabbatai, waɗanda suka zaɓi yin abin da ya gamshe ni suna kuma riƙe da alkawarina kankan, ");
INSERT INTO hausa_vpl VALUES ("IS56_5","024_56_5","ISA","56","5","5","a gare su cikin haikalina da kuma bangayensa zan ba da matuni da kuma suna mafi kyau fiye da ’ya’ya maza da kuma ’ya’ya mata; zan ba su madawwamin sunan da ba za a raba su da shi ba. ");
INSERT INTO hausa_vpl VALUES ("IS56_6","024_56_6","ISA","56","6","6","Baƙin da suka miƙa kansu ga Ubangiji don su bauta masa, su kuma ƙaunaci sunan Ubangiji, waɗanda kuma suke yin masa sujada, duk waɗanda suka kiyaye Asabbaci ba tare da ƙazantar da shi ba suka kuma riƙe alkawarina kankan, ");
INSERT INTO hausa_vpl VALUES ("IS56_7","024_56_7","ISA","56","7","7","waɗannan ne zan kai tsattsarkan dutsena in sa su yi farin ciki a gidana na addu’a. Hadayunsu na ƙonawa da sadakokinsu za su zama abin karɓa a bagadena; gama za a ce da gidana gidan addu’a domin dukan al’ummai.” ");
INSERT INTO hausa_vpl VALUES ("IS56_8","024_56_8","ISA","56","8","8","Ubangiji Mai Iko Duka ya furta cewa, zai tattara korarru na Isra’ila, “Zan ƙara tattaro waɗansu bayan waɗanda na riga na tattara.” ");
INSERT INTO hausa_vpl VALUES ("IS56_9","024_56_9","ISA","56","9","9","Ku zo, dukanku namun jeji, ku zo ku ci, dukanku namun jeji! ");
INSERT INTO hausa_vpl VALUES ("IS56_10","024_56_10","ISA","56","10","10","Matsaran Isra’ila makafi ne, dukansu jahilai ne; dukansu bebayen karnuka ne ba za su iya haushi ba; suna kwance ne kawai suna mafarki, suna son barci ba dama. ");
INSERT INTO hausa_vpl VALUES ("IS56_11","024_56_11","ISA","56","11","11","Su karnuka ne masu kwaɗayi; ba su taɓa ƙoshi. Su makiyaya ne marasa ganewa; duk sun nufi inda suka ga dama, kowa yana nemar wa kansa riba. ");
INSERT INTO hausa_vpl VALUES ("IS56_12","024_56_12","ISA","56","12","12","Kowanne yakan ce, “Zo, bari in samo ruwan inabi! Bari mu cika cikinmu da barasa! Gobe ma zai zama kamar yau, ko ma fiye da haka.” ");
INSERT INTO hausa_vpl VALUES ("IS57_1","024_57_1","ISA","57","1","1","Mai adalci yakan mutu, ba kuwa wanda yakan yi tunani a zuciyarsa; an kwashe mutanen kirki, ba kuwa wanda ya fahimta cewa an kwashe masu adalci don a tsame su daga mugunta. ");
INSERT INTO hausa_vpl VALUES ("IS57_2","024_57_2","ISA","57","2","2","Waɗanda suke aikata abin da yake daidai sukan shiga da salama; sukan huta yayinda suka kwanta cikin kabari. ");
INSERT INTO hausa_vpl VALUES ("IS57_3","024_57_3","ISA","57","3","3","“Amma ku, ku matso nan, ku ’ya’ya maza na masu sihiri, ku zuriyar mazinata da karuwai! ");
INSERT INTO hausa_vpl VALUES ("IS57_4","024_57_4","ISA","57","4","4","Wane ne kuke yi wa ba’a? Ga wa kuke masa gwalo kuna kuma fitar da harshe? Ashe, ku ba tarin ’yan tawaye ba ne, zuriyar maƙaryata? ");
INSERT INTO hausa_vpl VALUES ("IS57_5","024_57_5","ISA","57","5","5","Kuna cike da muguwar sha’awa mai ƙonawa a cikin itatuwan oak da kuma a ƙarƙashin kowane itace mai inuwa; kuna miƙa hadayar ’ya’yanku a rafuffuka da kuma a ƙarƙashin tsagaggun duwatsu. ");
INSERT INTO hausa_vpl VALUES ("IS57_6","024_57_6","ISA","57","6","6","Gumakan da suke cikin duwatsu masu sulɓi su ne rabonku; su ɗin, su ne rabonku. I, gare su kuka kwarara hadayu na sha kuka kuma miƙa hadayu na gari. Saboda waɗannan abubuwa, zan yi haƙuri? ");
INSERT INTO hausa_vpl VALUES ("IS57_7","024_57_7","ISA","57","7","7","Kun yi gadonku a dogayen duwatsu masu tsayi da kuma a tudu mai tsawo; a can kuka haura don ku miƙa hadayunku. ");
INSERT INTO hausa_vpl VALUES ("IS57_8","024_57_8","ISA","57","8","8","A bayan ƙofofi da madogaran ƙofofi kuka kafa alamun gumakanku. Kuka yashe ni, kuka kware gadonku, kuka kwanta a kansa kuka fadada shi; kuka kuma ƙulla yarjejjeniya da waɗanda kuke ƙaunar gadajensu, kuka dubi tsiraicinsu. ");
INSERT INTO hausa_vpl VALUES ("IS57_9","024_57_9","ISA","57","9","9","Kuka tafi wurin Molek da man zaitun kuka kuma riɓaɓɓanya turarenku. Kuka aika jakadunku can da nisa; kuka gangara zuwa cikin kabari kansa! ");
INSERT INTO hausa_vpl VALUES ("IS57_10","024_57_10","ISA","57","10","10","Kuka gaji cikin dukan al’amuranku, amma ba ku iya cewa, ‘Aikin banza ne ba.’ Kuka sami sabuntar ƙarfinku, ta haka ba ku suma ba. ");
INSERT INTO hausa_vpl VALUES ("IS57_11","024_57_11","ISA","57","11","11","“Wa ya sa ku fargaba, kuna jin tsoro har kuka yi mini ƙarya, ba ku kuma tuna da ni ba balle ku yi tunanin wannan a zukatanku? Ba don na daɗe ina shiru ba ne ya sa ba kwa tsorona? ");
INSERT INTO hausa_vpl VALUES ("IS57_12","024_57_12","ISA","57","12","12","Zan bayyana adalcinku da kuma ayyukanku, ba kuwa za su amfane ku ba. ");
INSERT INTO hausa_vpl VALUES ("IS57_13","024_57_13","ISA","57","13","13","Sa’ad da kuka nemi taimako, bari tarin gumakanku su cece ku! Iska za tă kwashe dukansu tă tafi, ɗan numfashi kawai zai hura su. Amma mutumin da ya mai da ni mafakarsa zai gāji ƙasar ya kuma mallaki dutsena mai tsarki.” ");
INSERT INTO hausa_vpl VALUES ("IS57_14","024_57_14","ISA","57","14","14","Za a kuma ce, “Ku gina, ku gina, ku gyara hanya! Ku kawar da abubuwan sa tuntuɓe a hanyar mutanena.” ");
INSERT INTO hausa_vpl VALUES ("IS57_15","024_57_15","ISA","57","15","15","Gama abin da Maɗaukaki da kuma Mai daraja ya faɗa wanda yake raye har abada, wanda sunansa mai tsarki ne, “Ina zama a bisa da kuma a tsattsarkan wuri, amma kuma tare da shi wanda yake mai halin tuba mai tawali’u a ruhu, don in farfaɗo da ruhu mai tawali’u in kuma farfaɗo da zuciyar mai halin tuba. ");
INSERT INTO hausa_vpl VALUES ("IS57_16","024_57_16","ISA","57","16","16","Ba zan tuhume su har abada ba, ba kuwa kullum zai yi fushi ba, gama a haka ruhun mutumin zan yi suma a gabana, shi numfashin mutumin da na halitta. ");
INSERT INTO hausa_vpl VALUES ("IS57_17","024_57_17","ISA","57","17","17","Na yi fushi saboda kwaɗayin zunubinsa; na yi masa horo, na kuma ɓoye fuskata saboda fushi, duk da haka ya ci gaba da ayyukan zunubinsa. ");
INSERT INTO hausa_vpl VALUES ("IS57_18","024_57_18","ISA","57","18","18","Na ga al’amuransa, amma zan warkar da shi; zan bi da shi in mayar da ta’aziyya a gare shi, ");
INSERT INTO hausa_vpl VALUES ("IS57_19","024_57_19","ISA","57","19","19","ina ƙirƙiro yabo a leɓunan masu makoki a Isra’ila. Salama, salama, ga waɗanda suke nesa da kuma kusa,” in ji Ubangiji. “Zan kuma warkar da su.” ");
INSERT INTO hausa_vpl VALUES ("IS57_20","024_57_20","ISA","57","20","20","Amma mugaye suna kama da tumbatsar teku, wanda ba ya natsuwa, wanda raƙumansa sukan kawo gurɓacewa da tabo. ");
INSERT INTO hausa_vpl VALUES ("IS57_21","024_57_21","ISA","57","21","21","“Babu salama ga mugaye,” in ji Allahna. ");
INSERT INTO hausa_vpl VALUES ("IS58_1","024_58_1","ISA","58","1","1","“Ku yi ihu da ƙarfi, ba ƙaƙƙautawa. Ku tā da muryarku kamar busar ƙaho. Ku furta wa mutanena tawayensu da kuma ga gidan Yaƙub zunubansu. ");
INSERT INTO hausa_vpl VALUES ("IS58_2","024_58_2","ISA","58","2","2","Gama kowace rana suna nemana; suna marmarin sanin hanyoyina, sai ka ce al’ummar da take yin abin da yake daidai ba ta kuma yashe umarnan Allahnta ba. Sun nemi shawarwaran da suke daidai daga gare ni suna kuma marmari Allah ya zo kusa da su. ");
INSERT INTO hausa_vpl VALUES ("IS58_3","024_58_3","ISA","58","3","3","Suna cewa, ‘Don me muka yi azumi, ba ka kuma gani ba? Me ya sa muka ƙasƙantar da kanmu, ba ka kuma lura da wannan ba?’ “Duk da haka a ranar azuminku, kuna yi yadda kuka ga dama kuna kuma zaluntar dukan ma’aikata. ");
INSERT INTO hausa_vpl VALUES ("IS58_4","024_58_4","ISA","58","4","4","Azuminku yakan ƙare a faɗa da kuma hargitsi, kuna ta naushin juna da mugayen naushe-naushe. Ba za ku iya azumi kamar yadda kuke yi a yau ku zaci za a ji muryarku can sama. ");
INSERT INTO hausa_vpl VALUES ("IS58_5","024_58_5","ISA","58","5","5","Irin azumin da na zaɓa ke nan, rana guda kawai don mutum ya ƙasƙantar da kansa? Sunkuyar da kanku kamar iwa kawai kuna kuma kwance a tsummoki da toka? Abin da kuke kira azumi ke nan rana yardajje ga Ubangiji? ");
INSERT INTO hausa_vpl VALUES ("IS58_6","024_58_6","ISA","58","6","6","“Irin azumin da na zaɓa shi ne, a kunce sarƙoƙin rashin adalci a kuma kunce igiyoyin karkiya, a ’yantar da waɗanda ake zalunta a kuma kakkarye kowace karkiya? ");
INSERT INTO hausa_vpl VALUES ("IS58_7","024_58_7","ISA","58","7","7","Ba shi ne ku rarraba abincinku da mayunwata ku kuma tanada wa matalauta masu yawo mahalli, sa’ad da kuka ga wanda yake tsirara, ku yi masa sutura, kada kuma ku ba wa namanku da jininku baya? ");
INSERT INTO hausa_vpl VALUES ("IS58_8","024_58_8","ISA","58","8","8","Sa’an nan haskenku zai keto kamar ketowar alfijir, warkarwarku kuma zai bayyana nan da nan; sa’an nan adalcinku zai tafi a gabanku, ɗaukakar Ubangiji kuma zai tsare ku daga baya. ");
INSERT INTO hausa_vpl VALUES ("IS58_9","024_58_9","ISA","58","9","9","Sa’an nan za ku yi kira, Ubangiji kuma zai amsa; za ku yi kuka don neman taimako, zai kuwa ce ga ni nan. “In kuka kawar da karkiyar zalunci, kuka daina nuna wa juna yatsa da kuma faɗar mugayen maganganu, ");
INSERT INTO hausa_vpl VALUES ("IS58_10","024_58_10","ISA","58","10","10","in kuma kuka ɗauki lokaci kuka ƙosar da mayunwata kuka kuma biya bukatun waɗanda suke shan tsanani, sa’an nan ne haskenku zai haskaka cikin duhu darenku kuma zai zama kamar tsakar rana. ");
INSERT INTO hausa_vpl VALUES ("IS58_11","024_58_11","ISA","58","11","11","Ubangiji zai bishe ku kullum; zai biya muku bukatunku a ƙasa mai zafin rana ya kuma ƙarfafa ƙasusuwanku. Za ku zama kamar lambun da aka yi masa banruwa, kamar rafin da ruwansa ba ya ƙafewa. ");
INSERT INTO hausa_vpl VALUES ("IS58_12","024_58_12","ISA","58","12","12","Mutanenku za su sāke gina kufai na da su kuma daga tsofaffin harsashai; za a ce da ku Masu Gyaran Katangar da ta Rushe, Masu Farfaɗo da Tituna da kuma Wuraren zama. ");
INSERT INTO hausa_vpl VALUES ("IS58_13","024_58_13","ISA","58","13","13","“In kun kiyaye ƙafafunku daga take Asabbaci da kuma daga aikata abin da kuka gan dama a ranata mai tsarki, in kuka kira Asabbaci ranar murna rana mai tsarki ta Ubangiji kuma mai bangirma, in kuka girmama ta ta wurin ƙin yin abin da kuka gan dama da kuma yin al’amuranku ko yin mugayen maganganu, ");
INSERT INTO hausa_vpl VALUES ("IS58_14","024_58_14","ISA","58","14","14","sa’an nan za ku yi farin ciki a cikin Ubangiji, zan kuma sa ku a kan maɗaukaka ƙasashe ku kuma yi biki a gādon mahaifinku Yaƙub.” Ni Ubangiji ne na faɗa. ");
INSERT INTO hausa_vpl VALUES ("IS59_1","024_59_1","ISA","59","1","1","Tabbatacce hannun Ubangiji bai kāsa yin ceto ba, kunnensa kuma bai kurmance da zai kāsa ji ba. ");
INSERT INTO hausa_vpl VALUES ("IS59_2","024_59_2","ISA","59","2","2","Amma laifofinku sun raba ku da Allahnku; zunubanku sun ɓoye fuskarsa daga gare ku, saboda kada yă ji. ");
INSERT INTO hausa_vpl VALUES ("IS59_3","024_59_3","ISA","59","3","3","Gama hannuwanku sun ƙazantu da jini, yatsotsinku kuma da alhaki. Leɓunanku suna faɗin ƙarairayi, harshenku kuma yana raɗar mugayen abubuwa. ");
INSERT INTO hausa_vpl VALUES ("IS59_4","024_59_4","ISA","59","4","4","Babu wani mai ce a yi adalci; babu wani mai nema a dubi al’amarinsa da mutunci. Sun dogara a gardandamin banza suna ƙarairayi; suna ɗaukar cikin ɓarna, su haifi mugunta. ");
INSERT INTO hausa_vpl VALUES ("IS59_5","024_59_5","ISA","59","5","5","Suna ƙyanƙyashe ƙwan kāsā su kuma saƙa yanar gizo-gizo. Duk wanda ya ci ƙwansu zai mutu, kuma sa’ad da ƙwan ya fashe, zai ƙyanƙyashe kububuwa. ");
INSERT INTO hausa_vpl VALUES ("IS59_6","024_59_6","ISA","59","6","6","Yanar gizo-gizonsu ba amfani don tufa; ba za su iya rufuwa da abin da suka yi ba. Ayyukansu mugaye ne, ayyukan tā da hargitsi kuma suna a hannuwansu. ");
INSERT INTO hausa_vpl VALUES ("IS59_7","024_59_7","ISA","59","7","7","Ƙafafunsu sukan gaggauta zuwa aikata zunubi; suna da saurin zub da jini. Tunaninsu mugaye ne; lalaci da hallaka sun shata hanyoyinsu. ");
INSERT INTO hausa_vpl VALUES ("IS59_8","024_59_8","ISA","59","8","8","Ba su san hanyar salama ba; babu adalci a hanyoyinsu. Sun mai da su karkatattun hanyoyi; babu wanda zai yi tafiya a kansu ya sami salama. ");
INSERT INTO hausa_vpl VALUES ("IS59_9","024_59_9","ISA","59","9","9","Saboda haka gaskiya ta yi nisa da mu, adalci kuma ba ya kaiwa gare mu. Muna neman haske, sai ga duhu; muna neman haske, sai muka yi ta tafiya cikin baƙin inuwa. ");
INSERT INTO hausa_vpl VALUES ("IS59_10","024_59_10","ISA","59","10","10","Kamar makafi, sai lallubar bango muke yi, muna lallubawar hanyarmu kamar marasa idanu. Da tsakar rana muna tuntuɓe sai ka ce wuri ya fara duhu; cikin ƙarfafa, mun zama kamar matattu. ");
INSERT INTO hausa_vpl VALUES ("IS59_11","024_59_11","ISA","59","11","11","Muna gurnani kamar beyar; muna ta ƙugi kamar kurciyoyi. Muna ta neman adalci amma ina; mun nemi fansa, amma yana can da nisa. ");
INSERT INTO hausa_vpl VALUES ("IS59_12","024_59_12","ISA","59","12","12","Gama laifofinmu suna da yawa a gabanka, zunubanmu kuma suna ba da shaida gāba da mu. Laifofinmu kullum suna a gabanmu, muna kuma sane da laifofinmu, ");
INSERT INTO hausa_vpl VALUES ("IS59_13","024_59_13","ISA","59","13","13","tawaye da mūsun Ubangiji, mun juye bayanmu ga Allahnmu, zugawa a yi zalunci da tayarwa, faɗin ƙarairayi da zukatanmu suka shirya. ");
INSERT INTO hausa_vpl VALUES ("IS59_14","024_59_14","ISA","59","14","14","Saboda haka aka kau da yin gaskiya adalci kuma ya tsaya can da nesa; gaskiya ta yi tuntuɓe a tituna, sahihanci ba zai shiga ba. ");
INSERT INTO hausa_vpl VALUES ("IS59_15","024_59_15","ISA","59","15","15","Gaskiya ta ɓace gaba ɗaya, kuma duk wanda ya guji mugunta zai zama ganima. Ubangiji ya duba bai kuwa ji daɗi cewa babu adalci ba. ");
INSERT INTO hausa_vpl VALUES ("IS59_16","024_59_16","ISA","59","16","16","Ya ga cewa babu wani, ya yi mamaki cewa babu wanda zai shiga tsakani; saboda haka hannunsa ya aikata masa ceto, adalcinsa kuma ya raya shi. ");
INSERT INTO hausa_vpl VALUES ("IS59_17","024_59_17","ISA","59","17","17","Ya yafa sulke a matsayin rigar ƙirji, da hulan kwanon ceto a kansa; ya sa rigunan ɗaukar fansa ya kuma nannaɗe kansa da kishi kamar a cikin alkyabba. ");
INSERT INTO hausa_vpl VALUES ("IS59_18","024_59_18","ISA","59","18","18","Bisa ga abin da suka yi, haka za a sāka fushi a kan abokan gābansa ramuwa kuma a kan maƙiyansa; zai sāka wa tsibirai abin da ya dace da su. ");
INSERT INTO hausa_vpl VALUES ("IS59_19","024_59_19","ISA","59","19","19","Daga yamma, mutane za su ji tsoron Ubangiji, daga mafitar rana kuma, za su girmama ɗaukakarsa. Gama zai zo kamar rigyawa mai tsananin gudu cewa numfashin Ubangiji zai tafi tare da shi. ");
INSERT INTO hausa_vpl VALUES ("IS59_20","024_59_20","ISA","59","20","20","“Mai fansa zai zo Sihiyona, zuwa waɗanda suke cikin Yaƙub da suka tuba daga zunubansu,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS59_21","024_59_21","ISA","59","21","21","“Game da ni dai, ga alkawarina da su,” in ji Ubangiji. “Ruhuna, wanda yake a kanka, da kuma maganata da na sa a bakinka ba za tă rabu da bakinka ba, ko daga bakunan ’ya’yanka ba, ko kuwa daga bakunan zuriyarsu ba daga wannan lokaci zuwa gaba da kuma har abada,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS60_1","024_60_1","ISA","60","1","1","“Ki tashi, ki haskaka, gama haskenki ya zo, ɗaukakar Ubangiji ya taso a kanki. ");
INSERT INTO hausa_vpl VALUES ("IS60_2","024_60_2","ISA","60","2","2","Duba, duhu ya rufe duniya duhu mai kauri kuma yana bisa mutane, amma Ubangiji ya taso a kanki ɗaukakarsa kuma ya bayyana a bisanki. ");
INSERT INTO hausa_vpl VALUES ("IS60_3","024_60_3","ISA","60","3","3","Al’ummai za su zo wurin haskenki, sarakuna kuma zuwa asubahin sabon yininki. ");
INSERT INTO hausa_vpl VALUES ("IS60_4","024_60_4","ISA","60","4","4","“Ki ɗaga idanunki ki duba kewaye da ke. Duka sun tattaru suka kuma zo wurinki; ’ya’yanki maza daga nesa, ana kuma ɗaukan ’ya’yanki mata a hannu. ");
INSERT INTO hausa_vpl VALUES ("IS60_5","024_60_5","ISA","60","5","5","Sa’an nan za ki duba ki kuma haskaka zuciyarki zai motsa ya kuma cika da farin ciki; za a kawo miki wadata daga tekuna, za a kawo miki arzikin al’ummai. ");
INSERT INTO hausa_vpl VALUES ("IS60_6","024_60_6","ISA","60","6","6","Manyan ayarin raƙuma za su cika ƙasar, ƙananan raƙuma ke nan daga Midiyan da Efa. Daga Sheba kuma duka za su zo, suna ɗauke da zinariya da turare suna shelar yabon Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS60_7","024_60_7","ISA","60","7","7","Dukan garkunan Kedar za su taru a wurinki ragunan Nebayiwot za su yi miki hidima; za a karɓe su kamar hadayu a kan bagadenki, zan kuma darjanta haikalina mai ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("IS60_8","024_60_8","ISA","60","8","8","“Su wane ne waɗannan da suke firiya kamar gizagizai, kamar kurciyoyi suna zuwa sheƙarsu? ");
INSERT INTO hausa_vpl VALUES ("IS60_9","024_60_9","ISA","60","9","9","Babu shakka tsibirai suna dogara gare ni; jiragen Tarshish kuma su ne a gaba, suna kawo ’ya’yanki maza daga nesa, tare da azurfa da zinariya, domin su girmama Ubangiji Allahnki, Mai Tsarkin nan na Isra’ila, gama ya cika ki da daraja. ");
INSERT INTO hausa_vpl VALUES ("IS60_10","024_60_10","ISA","60","10","10","“Baƙi za su sāke gina katangarki, sarakunansu kuma za su yi miki hidima. Ko da yake a cikin fushi na buge ki, da tagomashi zan yi miki jinƙai. ");
INSERT INTO hausa_vpl VALUES ("IS60_11","024_60_11","ISA","60","11","11","Ƙofofinki kullum za su kasance a buɗe, ba za a ƙara rufe su da rana ko da dare ba, saboda mutane su kawo miki dukiyar al’ummai, sarakunansu za su kasance a gaba a jerin gwanon nasara. ");
INSERT INTO hausa_vpl VALUES ("IS60_12","024_60_12","ISA","60","12","12","Gama al’umma ko masarautar da ba tă bauta miki ba, za tă hallaka; za tă lalace sarai. ");
INSERT INTO hausa_vpl VALUES ("IS60_13","024_60_13","ISA","60","13","13","“Darajar Lebanon za tă zo wurinki, itatuwan fir da dai ire-irensu da kuma itatuwan saifires duka za su zo don su ƙayatar da wurina mai tsarki; zan kuma ɗaukaka wurin ƙafafuna. ");
INSERT INTO hausa_vpl VALUES ("IS60_14","024_60_14","ISA","60","14","14","’Ya’ya maza masu zaluntarku za su zo suna rusunawa a gabanki; dukan waɗanda suka rena ki za su rusuna a ƙafafunki su kuma ce da ke Birnin Ubangiji, Sihiyona na Mai Tsarkin nan na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("IS60_15","024_60_15","ISA","60","15","15","“Ko da yake an yashe ki aka kuma ƙi ki, har babu wani da ya ratsa a cikinki, zan mai da ke madawwamiyar abar taƙama da kuma farin cikin dukan zamanai. ");
INSERT INTO hausa_vpl VALUES ("IS60_16","024_60_16","ISA","60","16","16","Za ki sha madarar al’ummai a kuma shayar da ke da nonon sarauta. Sa’an nan za ki san cewa ni, Ubangiji, ni ne Mai Cetonki, Mai Fansarki, Mai Ikon nan na Yaƙub. ");
INSERT INTO hausa_vpl VALUES ("IS60_17","024_60_17","ISA","60","17","17","A maimakon tagulla zan kawo zinariya, azurfa kuma a maimakon baƙin ƙarfe. A maimakon katako zan kawo tagulla, baƙin ƙarfe kuma a maimakon duwatsu. Zan sa salama ta zama gwamnarki adalci kuma mai mulkinki. ");
INSERT INTO hausa_vpl VALUES ("IS60_18","024_60_18","ISA","60","18","18","Ba za a ƙara jin hayaniyar tashin hankali a ƙasarki ba, balle lalacewa ko hallaka a cikin iyakokinki, amma za ki kira katangarki Ceto ƙofofinki kuma Yabo. ");
INSERT INTO hausa_vpl VALUES ("IS60_19","024_60_19","ISA","60","19","19","Rana ba za tă ƙara zama haskenki a yini ba, balle hasken wata ya haskaka a kanki, gama Ubangiji zai zama madawwamin haskenki, Allahnki kuma zai zama ɗaukakarki. ");
INSERT INTO hausa_vpl VALUES ("IS60_20","024_60_20","ISA","60","20","20","Ranarki ba za tă ƙara fāɗuwa ba watanki kuma ba zai ƙara shuɗewa ba; Ubangiji zai zama madawwamin haskenki, kwanakin baƙin cikinki za su ƙare. ");
INSERT INTO hausa_vpl VALUES ("IS60_21","024_60_21","ISA","60","21","21","Sa’an nan dukan mutanenki za su zama masu adalci za su kuma mallaki ƙasar har abada. Su ne reshen da na shuka, aikin hannuwana, don nuna darajata. ");
INSERT INTO hausa_vpl VALUES ("IS60_22","024_60_22","ISA","60","22","22","Mafi ƙanƙanta a cikinki za tă zama dubu, ƙarami zai zama al’umma mai girma. Ni ne Ubangiji, cikin lokacinsa zan yi haka da sauri.” ");
INSERT INTO hausa_vpl VALUES ("IS61_1","024_61_1","ISA","61","1","1","Ruhun Ubangiji Mai Iko Duka yana a kaina, domin Ubangiji ya shafe ni domin in yi wa’azi labari mai daɗi ga matalauta. Ya aiko ni in warkar da waɗanda suka karai a zuci, don in yi shelar ’yanci don ɗaurarru in kuma kunce ’yan kurkuku daga duhu ");
INSERT INTO hausa_vpl VALUES ("IS61_2","024_61_2","ISA","61","2","2","don in yi shelar shekarar tagomashin Ubangiji da kuma ranar ɗaukan fansar Allahnmu, don in ta’azantar da dukan waɗanda suke makoki, ");
INSERT INTO hausa_vpl VALUES ("IS61_3","024_61_3","ISA","61","3","3","in tanada wa waɗanda suke baƙin ciki a Sihiyona, in maido musu rawani mai kyau a maimako na toka, man murna a maimako na makoki, da kuma rigar yabo a maimako na ruhun fid da zuciya. Za a ce da su itatuwan oak na adalci, shukin Ubangiji don bayyana darajarsa. ");
INSERT INTO hausa_vpl VALUES ("IS61_4","024_61_4","ISA","61","4","4","Za su sāke gina kufai na dā su raya wurare da aka lalace tun da daɗewa; za su sabunta biranen da aka rurrushe da aka lalace tun zamanai masu yawa da suka wuce. ");
INSERT INTO hausa_vpl VALUES ("IS61_5","024_61_5","ISA","61","5","5","Baƙi za su yi kiwon garkunanki; baƙi za su yi miki noman gonaki da gonakin inabinki. ");
INSERT INTO hausa_vpl VALUES ("IS61_6","024_61_6","ISA","61","6","6","Za a kuma kira ku firistocin Ubangiji, za a kira ku masu hidimar Allahnmu. Za ku ci wadatar waɗansu al’ummai, kuma a cikin dukiyarsu za ku yi taƙama. ");
INSERT INTO hausa_vpl VALUES ("IS61_7","024_61_7","ISA","61","7","7","A maimakon kunyarsu mutanena za su sami rabi riɓi biyu, a maimakon wulaƙanci za su yi farin ciki cikin gādonsu; ta haka za su gāji rabo riɓi biyu a ƙasarsu, da kuma madawwamin farin ciki zai zama nasu. ");
INSERT INTO hausa_vpl VALUES ("IS61_8","024_61_8","ISA","61","8","8","“Gama ni, Ubangiji, ina ƙaunar adalci; na ƙi fashi da aikata laifi. Cikin adalcina zan sāka musu in kuma yi madawwamin alkawari da su. ");
INSERT INTO hausa_vpl VALUES ("IS61_9","024_61_9","ISA","61","9","9","Za a san da zuriyarsu a cikin al’ummai ’ya’yansu kuma a cikin mutane. Dukan waɗanda suka gan su za su san cewa su mutane ne da Ubangiji ya sa wa albarka.” ");
INSERT INTO hausa_vpl VALUES ("IS61_10","024_61_10","ISA","61","10","10","Ina jin daɗi ƙwarai a cikin Ubangiji; raina yana farin ciki a cikin Allahna. Gama ya suturce ni da rigunan ceto ya yi mini ado da rigar adalci, yadda ango yakan yi wa kansa ado kamar firist kamar kuma yadda amarya takan sha ado da duwatsunta masu daraja. ");
INSERT INTO hausa_vpl VALUES ("IS61_11","024_61_11","ISA","61","11","11","Gama kamar yadda ƙasa takan sa tsire-tsire su tohu lambu kuma ya sa iri ya yi girma, haka Ubangiji Mai Iko Duka zai sa adalci da yabo su tsiro a gaban dukan al’ummai. ");
INSERT INTO hausa_vpl VALUES ("IS62_1","024_62_1","ISA","62","1","1","Saboda Sihiyona ba zan yi shiru ba, saboda Urushalima ba zan huta ba, sai adalcinta ya haskaka kamar hasken safiya, cetonta kuma ya haskaka kamar fitila mai haske. ");
INSERT INTO hausa_vpl VALUES ("IS62_2","024_62_2","ISA","62","2","2","Al’ummai za su ga adalcinki, sarakuna kuma za su ga ɗaukakarki; za a kira ki da sabon suna sunan da bakin Ubangiji zai ambata. ");
INSERT INTO hausa_vpl VALUES ("IS62_3","024_62_3","ISA","62","3","3","Za ki zama rawanin daraja a hannun Ubangiji, rawanin sarauta a hannun Allahnki. ");
INSERT INTO hausa_vpl VALUES ("IS62_4","024_62_4","ISA","62","4","4","Ba za a ƙara ce da ke Yasasshiya ba, ko a kira ƙasarki Kango. Amma za a ce da ke Hefziba ƙasarki kuma Bewula; gama Ubangiji zai ji daɗinki, ƙasarki kuma za tă yi aure. ");
INSERT INTO hausa_vpl VALUES ("IS62_5","024_62_5","ISA","62","5","5","Kamar yadda saurayi kan auri yarinya, haka ’ya’yanki maza za su aure ki; kamar kuma yadda ango yakan yi farin ciki da amaryarsa, haka Allahnki zai yi farin ciki da ke. ");
INSERT INTO hausa_vpl VALUES ("IS62_6","024_62_6","ISA","62","6","6","Na sa matsara a kan katangarki, ya Urushalima; ba za su taɓa yin shiru ba, dare da rana. Ku da kuke kira bisa sunan Ubangiji, kada ku ba kanku hutu, ");
INSERT INTO hausa_vpl VALUES ("IS62_7","024_62_7","ISA","62","7","7","kuma kada ku ba shi hutu sai ya kafa Urushalima ya kuma mai da ita yabon duniya. ");
INSERT INTO hausa_vpl VALUES ("IS62_8","024_62_8","ISA","62","8","8","Ubangiji ya rantse da hannunsa na dama ta hannunsa kuma mai iko cewa, “Ba zan ƙara ba da hatsinki ya zama abinci ga abokan gābanki ba, baƙi kuma ba za su ƙara shan ruwan inabin wanda kika sha wahala samu ba; ");
INSERT INTO hausa_vpl VALUES ("IS62_9","024_62_9","ISA","62","9","9","amma waɗanda suka girbe shi za su ci shi su kuma yabi Ubangiji, waɗanda kuma suka tattara ’ya’yan inabi za su sha shi a filayen wurina mai tsarki.” ");
INSERT INTO hausa_vpl VALUES ("IS62_10","024_62_10","ISA","62","10","10","Ku wuce, ku wuce ƙofofi! Ku shirya hanya saboda mutane. Ku gina, ku gina babbar hanya! Ku kawar da duwatsu. Ku ɗaga tuta saboda al’ummai. ");
INSERT INTO hausa_vpl VALUES ("IS62_11","024_62_11","ISA","62","11","11","Ubangiji ya yi shela ga iyakokin duniya cewa, “Faɗa wa Diyar Sihiyona, ‘Ga Mai Cetonki yana zuwa! Ga ladarsa tana tare da shi, sakamakonsa yana raka shi.’ ” ");
INSERT INTO hausa_vpl VALUES ("IS62_12","024_62_12","ISA","62","12","12","Za a ce da shi Tsattsarkar Mutane, Fansassu na Ubangiji; za a kuma ce da ke Wadda Aka Nema Birnin da Ba Za a Ƙara Yashe ta ba. ");
INSERT INTO hausa_vpl VALUES ("IS63_1","024_63_1","ISA","63","1","1","Wane ne wannan mai zuwa daga Edom, daga Bozra, saye da jajjayen rigunarsa? Wane ne wannan, sanye cikin daraja, tafe cikin girmar ƙarfinsa? “Ni ne, mai magana cikin adalci, mai ikon ceto.” ");
INSERT INTO hausa_vpl VALUES ("IS63_2","024_63_2","ISA","63","2","2","Me ya sa rigunanka suka yi ja, sai ka ce na wanda yake tattaka ’ya’yan inabi? ");
INSERT INTO hausa_vpl VALUES ("IS63_3","024_63_3","ISA","63","3","3","“Na tattake ’ya’yan inabi ni kaɗai; cikin al’ummai kuma babu wani tare da ni. Na tattake su cikin fushina Na matse su cikin hasalata; jininsu ya fantsamar wa rigunana, na kuma ɓata dukan tufafina. ");
INSERT INTO hausa_vpl VALUES ("IS63_4","024_63_4","ISA","63","4","4","Gama ranar ɗaukan fansa tana a cikin zuciyata, kuma shekarar fansata ta zo. ");
INSERT INTO hausa_vpl VALUES ("IS63_5","024_63_5","ISA","63","5","5","Na duba, amma babu wanda zai taimaka, na yi mamaki cewa ba wanda ya goyi baya; saboda haka hannuna ya yi mini ceto, fushina kuma ya rayar da ni. ");
INSERT INTO hausa_vpl VALUES ("IS63_6","024_63_6","ISA","63","6","6","Na tattake al’ummai cikin fushina; cikin hasalata kuma na sa sun bugu na kuma zub da jininsu a ƙasa.” ");
INSERT INTO hausa_vpl VALUES ("IS63_7","024_63_7","ISA","63","7","7","Zan ba da labarin alherin Ubangiji, ayyukan da suka sa a yabe shi, bisa ga dukan abubuwan da Ubangiji ya yi mana, I, ayyuka masu kyan da ya yi domin gidan Isra’ila, bisa ga jinƙansa da yawan alheransa. ");
INSERT INTO hausa_vpl VALUES ("IS63_8","024_63_8","ISA","63","8","8","Ya ce, “Babu shakka su mutanena ne, ’ya’ya maza waɗanda ba za su ruɗe ni ba”; ta haka ya zama Mai Cetonsu. ");
INSERT INTO hausa_vpl VALUES ("IS63_9","024_63_9","ISA","63","9","9","Cikin dukan damuwarsu shi ma ya damu, mala’ikan da yake gabansa ya cece su. Cikin ƙauna da jinƙai ya fanshe su; ya kuma ɗaga su ya riƙe su dukan kwanakin dā ");
INSERT INTO hausa_vpl VALUES ("IS63_10","024_63_10","ISA","63","10","10","Duk da haka suka yi tawaye suka ɓata wa Ruhu Mai Tsarki rai. Saboda haka ya juya ya kuma zama abokin gābansu shi kansa kuma ya yaƙe su. ");
INSERT INTO hausa_vpl VALUES ("IS63_11","024_63_11","ISA","63","11","11","Sa’an nan mutanensa suka tuna kwanakin dā, kwanakin Musa da mutanensa, ina yake shi wanda ya fitar da su ta teku, da makiyayan garkensa? Ina shi yake wanda ya sa Ruhunsa Mai Tsarki a cikinsu, ");
INSERT INTO hausa_vpl VALUES ("IS63_12","024_63_12","ISA","63","12","12","wanda ya aika hannu ɗaukakarsa mai iko ya kasance a hannun dama na Musa, wanda ya raba ruwaye a gabansu, don yă sami wa kansa madawwamin suna, ");
INSERT INTO hausa_vpl VALUES ("IS63_13","024_63_13","ISA","63","13","13","wanda ya bishe su cikin zurfafa? Kamar doki a fili, ba su yi tuntuɓe ba; ");
INSERT INTO hausa_vpl VALUES ("IS63_14","024_63_14","ISA","63","14","14","kamar shanun da suke gangarawa zuwa kwari, haka Ruhun Ubangiji ya ba su hutu. Ga yadda ka bishe mutanenka don ka ba wa kanka suna mai ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("IS63_15","024_63_15","ISA","63","15","15","Ka duba daga sama ka gani daga kursiyinka da yake bisa, mai tsarki da kuma mai ɗaukaka. Ina kishinka da kuma ikonka? Ka janye juyayi da kuma tausayin da kake yi mana daga gare mu. ");
INSERT INTO hausa_vpl VALUES ("IS63_16","024_63_16","ISA","63","16","16","Amma kai Ubanmu ne, ko Ibrahim bai san mu ba Isra’ila kuma bai yarda da mu ba; kai, ya Ubangiji, kai ne Ubanmu, Mai Fansarmu tun fil azal ne sunanka. ");
INSERT INTO hausa_vpl VALUES ("IS63_17","024_63_17","ISA","63","17","17","Don me, ya Ubangiji, ka sa muna barin hanyoyinka muka kuma taurare zukatanmu don kada mu girmama ka? Ka komo domin darajar bayinka, kabilan da suke abin gādonka. ");
INSERT INTO hausa_vpl VALUES ("IS63_18","024_63_18","ISA","63","18","18","Gama a ɗan lokaci mutanenka suka mallaki wurinka mai tsarki, amma yanzu abokan gābanmu sun tattake wurinka mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("IS63_19","024_63_19","ISA","63","19","19","Mu naka tun fil azal; ba ka taɓa yin mulki a kansu ba, ba a taɓa kira su da sunanka ba. ");
INSERT INTO hausa_vpl VALUES ("IS64_1","024_64_1","ISA","64","1","1","Da ma za ka tsage sammai ka sauko, ai, da duwatsu za su yi rawar jiki a gabanka! ");
INSERT INTO hausa_vpl VALUES ("IS64_2","024_64_2","ISA","64","2","2","Kamar sa’ad da wuta takan ci rassa ta sa ruwa ya tafasa, ka sauko ka sanar da sunanka ga abokan gābanka ka kuma sa al’ummai su yi rawan jiki a gabanka! ");
INSERT INTO hausa_vpl VALUES ("IS64_3","024_64_3","ISA","64","3","3","Gama sa’ad da ka aikata abubuwan bantsoron da ba mu sa tsammani ba, ka sauko, duwatsu kuma suka yi rawar jiki a gabanka. ");
INSERT INTO hausa_vpl VALUES ("IS64_4","024_64_4","ISA","64","4","4","Tun fil azal babu wanda ya taɓa ji, babu kunnen da ya gane, babu idon da ya ga wani Allah in ban da kai, wanda ya aikata waɗannan al’amura a madadin waɗanda suke sa zuciya a gare shi. ");
INSERT INTO hausa_vpl VALUES ("IS64_5","024_64_5","ISA","64","5","5","Kakan taimaki waɗanda suke murnan yin abin da yake daidai, waɗanda sukan tuna da hanyoyinka. Amma sa’ad da muka ci gaba da yin zunubi, kakan yi fushi. Ta yaya za mu sami ceto ke nan? ");
INSERT INTO hausa_vpl VALUES ("IS64_6","024_64_6","ISA","64","6","6","Dukanmu mun zama kamar wanda yake marar tsabta, kuma dukan ayyukanmu masu adalci sun zama kamar ƙazaman tsummoki; duk mun zama kamar busasshen ganye, kamar iska haka zunubanmu sukan share mu. ");
INSERT INTO hausa_vpl VALUES ("IS64_7","024_64_7","ISA","64","7","7","Babu wanda yake kira bisa sunanka ko ya yi ƙoƙarin riƙe ka; gama ka ɓoye fuskarka daga gare mu ka kuma sa muka lalace saboda zunubanmu. ");
INSERT INTO hausa_vpl VALUES ("IS64_8","024_64_8","ISA","64","8","8","Duk da haka, Ubangiji, kai ne Ubanmu. Mu yumɓu ne, kai kuma mai ginin tukwane; dukanmu aikin hannunka ne. ");
INSERT INTO hausa_vpl VALUES ("IS64_9","024_64_9","ISA","64","9","9","Kada ka yi fushi fiye da kima, ya Ubangiji; kada ka tuna da zunubanmu har abada. Da ma ka dube mu, muna roƙonka, gama dukanmu mutanenka ne. ");
INSERT INTO hausa_vpl VALUES ("IS64_10","024_64_10","ISA","64","10","10","Biranenka masu tsarki sun zama hamada; har Sihiyona ma ta zama hamada; Urushalima ta zama kango. ");
INSERT INTO hausa_vpl VALUES ("IS64_11","024_64_11","ISA","64","11","11","Haikalinmu mai tsarki da kuma mai daraja, inda kakanninmu suka yabe ka, an ƙone da wuta, kuma dukan abubuwan da muke ƙauna sun lalace. ");
INSERT INTO hausa_vpl VALUES ("IS64_12","024_64_12","ISA","64","12","12","Bayan dukan wannan, ya Ubangiji, ba za ka yi wani abu ba? Za ka yi shiru ka hore mu fiye da kima? ");
INSERT INTO hausa_vpl VALUES ("IS65_1","024_65_1","ISA","65","1","1","“Na bayyana kaina ga waɗanda ba su tambaye ni ba; ina samuwa ga waɗanda ba su neme ni ba. Ga al’ummar da ba tă kira bisa sunana ba, Na ce, ‘Ga ni, ga ni.’ ");
INSERT INTO hausa_vpl VALUES ("IS65_2","024_65_2","ISA","65","2","2","Dukan yini ina miƙa hannuwana ga mutane masu tayarwa, waɗanda suna tafiya a hanyoyin da ba su da kyau, suna bin tunaninsu, ");
INSERT INTO hausa_vpl VALUES ("IS65_3","024_65_3","ISA","65","3","3","mutanen da suna cin gaba da tsokanata a fuskata, suna miƙa hadayu a gonaki suna ƙone turare a bagadan tubali; ");
INSERT INTO hausa_vpl VALUES ("IS65_4","024_65_4","ISA","65","4","4","suna zama a kaburbura su kwana suna yin asirtattun ayyuka; suna cin naman aladu, tukwanensu kuma sun cika da nama marar tsabta; ");
INSERT INTO hausa_vpl VALUES ("IS65_5","024_65_5","ISA","65","5","5","suna cewa, ‘Ku tsaya a can; kada ku yi kusa da ni, gama na fi ku tsarki!’ Irin mutanen nan hayaƙi ne a hancina, wuta kuma da take cin gaba da ci dukan yini. ");
INSERT INTO hausa_vpl VALUES ("IS65_6","024_65_6","ISA","65","6","6","“Ga shi, yana nan a rubuce a gabana cewa ba zan ƙyale ba, zan yi cikakken ramuwa; zan yi ramuwa a cinyoyinsu ");
INSERT INTO hausa_vpl VALUES ("IS65_7","024_65_7","ISA","65","7","7","saboda zunubanku da kuma zunuban kakanninku,” in ji Ubangiji. “Gama sun ƙone turare a kan duwatsu suka kuma ƙazantar da ni a kan tuddai, zan yi musu awo in zuba a cinyoyinsu cikakken ramuwa saboda ayyukansu na dā.” ");
INSERT INTO hausa_vpl VALUES ("IS65_8","024_65_8","ISA","65","8","8","Ga abin da Ubangiji yana cewa, “Kamar sa’ad da ruwan ’ya’yan itace yana samuwa a cikin tarin ’ya’yan inabi mutane kuma su ce, ‘Kada a lalace shi, har yanzu akwai abu mai kyau a ciki,’ haka nan zan yi a madadin bayina; ba zan hallaka su duka ba. ");
INSERT INTO hausa_vpl VALUES ("IS65_9","024_65_9","ISA","65","9","9","Zan fitar da zuriyar Yaƙub, daga Yahuda kuma waɗanda za su mallaki duwatsuna; zaɓaɓɓun mutanena za su gāje su, a can kuma bayina za su zauna. ");
INSERT INTO hausa_vpl VALUES ("IS65_10","024_65_10","ISA","65","10","10","Sharon zai zama wurin kiwo don shanu, Kwarin Akor kuma wurin hutun garkuna, domin mutanena da suke nemana. ");
INSERT INTO hausa_vpl VALUES ("IS65_11","024_65_11","ISA","65","11","11","“Amma game da ku waɗanda kuka yashe Ubangiji kuka manta da dutsena mai tsarki kuwa, ku da kuka shimfiɗa tebur don sa’a kuka kuma cika darunan ruwan inabin da aka dama don Ƙaddara, ");
INSERT INTO hausa_vpl VALUES ("IS65_12","024_65_12","ISA","65","12","12","zan ƙaddara ku ga kaifin takobi, dukanku kuma za ku sunkuya wa mai yanka; gama na yi kira amma ba ku amsa ba, na yi magana amma ba ku saurara ba. Kuka aikata mugunta a gabana kuka kuma zaɓi abin da ba na jin daɗi.” ");
INSERT INTO hausa_vpl VALUES ("IS65_13","024_65_13","ISA","65","13","13","Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa, “Bayin za su ci, amma ku za ku ji yunwa; bayina za su sha, amma ku za ku ji ƙishi; bayina za su yi farin ciki amma ku za ku sha kunya. ");
INSERT INTO hausa_vpl VALUES ("IS65_14","024_65_14","ISA","65","14","14","Bayina za su rera da farin cikin zukatansu, amma ku za ku yi kuka daga wahalar zuciya ku kuma yi kururuwa da karayar zuci. ");
INSERT INTO hausa_vpl VALUES ("IS65_15","024_65_15","ISA","65","15","15","Za ku bar sunanku ga zaɓaɓɓuna yă zama abin la’antarwa; Ubangiji Mai Iko Duka zai kashe ku, amma ga bayina zai ba su wani suna. ");
INSERT INTO hausa_vpl VALUES ("IS65_16","024_65_16","ISA","65","16","16","Duk wanda zai roƙi albarka a cikin ƙasar zai yi haka da gaskiyar Allah; wanda zai yi rantsuwa a cikin ƙasar zai rantse da gaskiyar Allah. Gama za a manta da wahalolin baya a kuma ɓoye su daga idanuna. ");
INSERT INTO hausa_vpl VALUES ("IS65_17","024_65_17","ISA","65","17","17","“Ga shi, na halicci sabuwar sama da kuma sabuwar duniya. Abubuwa na dā za a manta da su, ba kuwa za a ƙara tuna da su ba. ");
INSERT INTO hausa_vpl VALUES ("IS65_18","024_65_18","ISA","65","18","18","Amma ku yi murna ku kuma yi farin ciki har abada a abin da na halitta, gama zan halicci Urushalima ta zama abin murna mutanenta kuwa abin farin ciki. ");
INSERT INTO hausa_vpl VALUES ("IS65_19","024_65_19","ISA","65","19","19","Zan yi farin ciki a kan Urushalima in kuma yi murna saboda mutanena; a can ba za a ƙara jin karar makoki da na kuka ba. ");
INSERT INTO hausa_vpl VALUES ("IS65_20","024_65_20","ISA","65","20","20","“A cikinta ba za a ƙara jin jariri ya rayu na ’yan kwanaki kawai ba, ko kuwa wani tsohon da bai cika kwanakinsa ba; duk wanda ya mutu yana da shekaru ɗari za a ce ya mutu a kurciya ne kawai; duk wanda bai kai ɗari ba za a ɗauka la’antacce ne. ");
INSERT INTO hausa_vpl VALUES ("IS65_21","024_65_21","ISA","65","21","21","Za su gina gidaje su kuma zauna a cikinsu; za su yi shuki a gonakin inabi su kuma ci ’ya’yansu. ");
INSERT INTO hausa_vpl VALUES ("IS65_22","024_65_22","ISA","65","22","22","Ba za su ƙara gina gidaje waɗansu kuma su zauna a cikinsu ba, ko su yi shuki waɗansu kuma su ci ba. Gama kamar yadda kwanakin itace suke, haka kwanakin mutanena za su kasance; zaɓaɓɓuna za su daɗe suna jin daɗin ayyukan hannuwansu. ");
INSERT INTO hausa_vpl VALUES ("IS65_23","024_65_23","ISA","65","23","23","Ba za su yi wahala a banza ba ko su haifi ’ya’yan da aka ƙaddara da rashin sa’a; gama za su zama mutanen da Ubangiji ya yi wa albarka, su da zuriyarsu tare da su. ");
INSERT INTO hausa_vpl VALUES ("IS65_24","024_65_24","ISA","65","24","24","Kafin su yi kira zan amsa; yayinda suke cikin magana zan ji. ");
INSERT INTO hausa_vpl VALUES ("IS65_25","024_65_25","ISA","65","25","25","Kyarketai da ’yan raguna za su ci abinci tare, zaki kuma zai ci buɗu kamar yadda shanu suke yi, amma ƙura ce za tă zama abincin maciji. Ba za su ƙara cuci ko su yi ɓarna a kan dukan dutsena mai tsarki ba,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS66_1","024_66_1","ISA","66","1","1","Ga abin da Ubangiji yana cewa, “Sama kursiyina ce, duniya kuma matashin sawuna. Ina gidan da za ku gina mini? Ina wurin hutuna zai kasance? ");
INSERT INTO hausa_vpl VALUES ("IS66_2","024_66_2","ISA","66","2","2","Ba hannuna ba ne ya yi dukan waɗannan abubuwa, ta haka suka kasance?” In ji Ubangiji. “Wannan mutum ne nake jin daɗi, shi da yake mai ƙasƙanci da kuma zuciyar yin tuba, yana kuma rawar jiki ga maganata. ");
INSERT INTO hausa_vpl VALUES ("IS66_3","024_66_3","ISA","66","3","3","Amma duk ya miƙa hadayar bijimi yana kama da wanda ya kashe mutum, kuma duk wanda ya miƙa ɗan rago, kamar wanda ya karye wuyan kare; duk wanda ya miƙa hadaya ta gari yana kama da wanda ya yi sadakar jinin alade, kuma duk wanda ya ƙone turaren tuni, kamar wanda yake bauta gunki ne. Sun zaɓi hanyoyinsu, rayukansu kuma suna jin daɗin abubuwan banƙyamarsu; ");
INSERT INTO hausa_vpl VALUES ("IS66_4","024_66_4","ISA","66","4","4","saboda haka ni ma zan aukar musu da masifa mai zafi in kuma kawo musu abin da suke tsoro. Gama sa’ad da na yi kira, ba wanda ya amsa, sa’ad da na yi magana, ba wanda ya saurara, Sun aikata mugunta a idona suka kuma zaɓa abin da ba na jin daɗi.” ");
INSERT INTO hausa_vpl VALUES ("IS66_5","024_66_5","ISA","66","5","5","Ku ji maganar Ubangiji, ku da kuke rawar jiki ga maganarsa, “’Yan’uwanku da suke ƙinku, suna kuma ware ku saboda sunana, sun ce, ‘Bari a ɗaukaka Ubangiji, don mu ga farin cikinku!’ Duk da haka za su sha kunya. ");
INSERT INTO hausa_vpl VALUES ("IS66_6","024_66_6","ISA","66","6","6","Ku ji wannan hayaniya daga birni, ku ji surutu daga haikali! Amon Ubangiji ne yana sāka wa abokan gābansa abin da ya dace da su. ");
INSERT INTO hausa_vpl VALUES ("IS66_7","024_66_7","ISA","66","7","7","“Kafin naƙuda ya fara mata, ta haihu; kafin zafi ya zo mata, ta haifi ɗa. ");
INSERT INTO hausa_vpl VALUES ("IS66_8","024_66_8","ISA","66","8","8","Wa ya taɓa jin irin wannan abu? Wa ya taɓa gani irin abubuwan nan? Za a iya ƙirƙiro ƙasa a rana ɗaya ko a haifi al’umma farat ɗaya? Duk da haka da zarar Sihiyona ta fara naƙuda sai ta haifi ’ya’yanta. ");
INSERT INTO hausa_vpl VALUES ("IS66_9","024_66_9","ISA","66","9","9","Zan kai mace har haihuwa in kuma sa ta kāsa haihu?” In ji Ubangiji. “Zan rufe mahaihuwa sa’ad da lokacin haihuwa ya yi?” In ji Allahnku. ");
INSERT INTO hausa_vpl VALUES ("IS66_10","024_66_10","ISA","66","10","10","“Ku yi farin ciki tare da Urushalima ku kuma yi murna saboda ita, dukanku waɗanda kuke ƙaunarta; ku yi farin ciki matuƙa tare da ita, dukanku waɗanda kuke makoki a kanta. ");
INSERT INTO hausa_vpl VALUES ("IS66_11","024_66_11","ISA","66","11","11","Gama za ku tsotsa ku kuma ƙoshi da nonon ta’aziyyarta; za ku sha sosai ku kuma ji daɗin yalwarta.” ");
INSERT INTO hausa_vpl VALUES ("IS66_12","024_66_12","ISA","66","12","12","Gama ga abin da Ubangiji ya faɗa, “Zan fadada salama gare ta kamar kogi, wadatar al’ummai kuma kamar rafi mai gudu; za ku tsotsa a kuma riƙe ku a hannunta ku kuma yi wasa a gwiwoyinta. ");
INSERT INTO hausa_vpl VALUES ("IS66_13","024_66_13","ISA","66","13","13","Kamar yadda uwa takan ta’azantar da ɗanta haka zan ta’azantar da ku; za ku kuma ta’azantu a Urushalima.” ");
INSERT INTO hausa_vpl VALUES ("IS66_14","024_66_14","ISA","66","14","14","Sa’ad da kuka ga wannan, zuciyarku za tă yi farin ciki za ku kuma haɓaka kamar ciyawa; za a sanar da hannun Ubangiji ga bayinsa, amma za a nuna wa maƙiyansa fushinsa. ");
INSERT INTO hausa_vpl VALUES ("IS66_15","024_66_15","ISA","66","15","15","Ga shi, Ubangiji yana zuwa da wuta, kuma kekunan yaƙinsa suna kama da guguwa; zai sauko da fushinsa da zafi, tsawatawarsa kuma da harsunan wuta. ");
INSERT INTO hausa_vpl VALUES ("IS66_16","024_66_16","ISA","66","16","16","Gama da wuta da kuma takobi Ubangiji zai yi hukunci a kan dukan mutane, kuma yawanci za su kasance waɗanda Ubangiji zai kashe. ");
INSERT INTO hausa_vpl VALUES ("IS66_17","024_66_17","ISA","66","17","17","“Waɗanda suka tsarkake suka kuma tsabtacce kansu don su je lambu, suna bin wannan da yake tsakiya waɗannan da suke cin naman aladu da ɓeraye da waɗansu abubuwan banƙyama, za su sadu da ƙarshensu tare,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS66_18","024_66_18","ISA","66","18","18","“Ni kuwa, saboda ayyukansu da kuma tunaninsu, ina dab da zuwa in tattara dukan al’ummai da harsuna, za su kuma zo su ga ɗaukakata. ");
INSERT INTO hausa_vpl VALUES ("IS66_19","024_66_19","ISA","66","19","19","“Zan kafa alama a cikinsu, zan kuma aika waɗansu da suka tsira zuwa al’ummai, zuwa Tarshish, zuwa Libiya da Lidiya (sanannun ’yan aika), zuwa Tubal da kuma Girka, da kuma zuwa manisantan tsibirai da ba su taɓa jin labarin sunana ba ko su ga ɗaukakata. Za su yi shelar ɗaukakata a cikin al’ummai. ");
INSERT INTO hausa_vpl VALUES ("IS66_20","024_66_20","ISA","66","20","20","Za su kuma dawo da dukan ’yan’uwanku, daga dukan al’ummai, zuwa dutsena mai tsarki a Urushalima kamar hadaya ga Ubangiji, a kan dawakai, a kekunan yaƙi da wagonu, da kuma a kan alfadarai da kuma raƙuma,” in ji Ubangiji. “Za su kawo su, kamar yadda Isra’ilawa suke kawo hadayun hatsi, zuwa haikalin Ubangiji a cikin tsabtatattun kore. ");
INSERT INTO hausa_vpl VALUES ("IS66_21","024_66_21","ISA","66","21","21","Zan kuwa zaɓa waɗansunsu kuma su zama firistoci da Lawiyawa,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS66_22","024_66_22","ISA","66","22","22","“Kamar yadda sabuwar duniya da sabuwar sama za su tabbata a gabana,” in ji Ubangiji, “haka sunanku da zuriyarku za su tabbata. ");
INSERT INTO hausa_vpl VALUES ("IS66_23","024_66_23","ISA","66","23","23","Daga wannan sabon wata zuwa wancan, kuma daga wannan Asabbaci zuwa wancan, dukan mutane za su zo su rusuna a gabana,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("IS66_24","024_66_24","ISA","66","24","24","“Za su kuma fita su ga gawawwakin mutanen da suka yi mini tayarwa; tsutsotsin da suke cinsu ba za su taɓa mutuwa ba, balle wutar da take ƙona su ta mutu, za su kuma zama abin ƙyama ga dukan mutane.”");
INSERT INTO hausa_vpl VALUES ("JR1_1","025_1_1","JER","1","1","1","Kalmomin Irmiya ɗan Hilkiya, ɗaya daga cikin firistoci a Anatot a yankin Benyamin. ");
INSERT INTO hausa_vpl VALUES ("JR1_2","025_1_2","JER","1","2","2","Maganar Ubangiji ta zo gare shi a shekara ta goma sha uku ta sarautar Yosiya ɗan Amon sarkin Yahuda, ");
INSERT INTO hausa_vpl VALUES ("JR1_3","025_1_3","JER","1","3","3","da kuma a zamanin Yehohiyakim ɗan Yosiya sarkin Yahuda, har zuwa watan biyar na shekara goma sha ɗaya na Zedekiya ɗan Yosiya sarkin Yahuda, sa’ad da aka kai mutanen Urushalima zaman bauta. ");
INSERT INTO hausa_vpl VALUES ("JR1_4","025_1_4","JER","1","4","4","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("JR1_5","025_1_5","JER","1","5","5","“Kafin in siffanta ka a cikin ciki na san ka, kafin a haife ka, na keɓe ka; na naɗa ka ka zama annabi ga al’ummai.” ");
INSERT INTO hausa_vpl VALUES ("JR1_6","025_1_6","JER","1","6","6","Sai na ce, “Kayya, Ubangiji Mai Iko Duka, ban iya magana ba; ni ɗan yaro ne kawai.” ");
INSERT INTO hausa_vpl VALUES ("JR1_7","025_1_7","JER","1","7","7","Amma Ubangiji ya ce mini, “Kada ka ce, ‘Ni ɗan yaro ne kawai.’ Dole ka je wurin kowane mutumin da na aike ka ka kuma faɗa abin da na umarce ka. ");
INSERT INTO hausa_vpl VALUES ("JR1_8","025_1_8","JER","1","8","8","Kada ka ji tsoronsu, gama ina tare da kai kuma zan kiyaye ka,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR1_9","025_1_9","JER","1","9","9","Sai Ubangiji ya miƙa hannunsa ya taɓa bakina ya ce mini, “Yanzu na sa kalmomina a bakinka. ");
INSERT INTO hausa_vpl VALUES ("JR1_10","025_1_10","JER","1","10","10","Duba, yau na naɗa ka a kan al’ummai da mulkoki don ka tumɓuke ka kuma rusar, ka hallaka ka kuma kakkaɓe, ka gina ka kuma shuka.” ");
INSERT INTO hausa_vpl VALUES ("JR1_11","025_1_11","JER","1","11","11","Maganar Ubangiji ta zo mini cewa, “Me ka gani, Irmiya?” Sai na amsa na ce, “Na ga reshen itacen almon.” ");
INSERT INTO hausa_vpl VALUES ("JR1_12","025_1_12","JER","1","12","12","Ubangiji ya ce mini, “Daidai ne ka gani, gama ina lura in ga cewa maganata ta cika.” ");
INSERT INTO hausa_vpl VALUES ("JR1_13","025_1_13","JER","1","13","13","Maganar Ubangiji ta sāke zo mini cewa, “Me ka gani?” Na amsa na ce, “Na ga tukunya tana tafasa, tana juyewa daga arewa.” ");
INSERT INTO hausa_vpl VALUES ("JR1_14","025_1_14","JER","1","14","14","Ubangiji ya ce mini, “Daga arewa za a zubo masifa a kan dukan mazaunan ƙasar. ");
INSERT INTO hausa_vpl VALUES ("JR1_15","025_1_15","JER","1","15","15","Ina shirin kiran dukan mutanen masarautar arewanci,” in ji Ubangiji. “Sarakunansu za su zo su kafa kursiyoyinsu a mashigin ƙofofin Urushalima; za su zo su kewaye dukan katangarta su kewaye dukan garuruwan Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR1_16","025_1_16","JER","1","16","16","Zan furta hukunci a kan mutanena saboda muguntarsu na yashe ni, suna ƙona turare ga waɗansu alloli suna kuma bauta wa abin da hannuwansu suka yi. ");
INSERT INTO hausa_vpl VALUES ("JR1_17","025_1_17","JER","1","17","17","“Ka kintsa kanka! Ka tashi tsaye ka faɗa musu abin da na umarce ka. Kada su firgita ka, in ba haka ba zan firgita ka a gabansu. ");
INSERT INTO hausa_vpl VALUES ("JR1_18","025_1_18","JER","1","18","18","Yau na mai da kai birni mai katanga, ginshiƙin ƙarfe da bangon tagulla don ka tsaya gāba da dukan ƙasar, ya kuma yi gāba da sarakunan Yahuda da fadawan, da firistoci da kuma mutanenta. ");
INSERT INTO hausa_vpl VALUES ("JR1_19","025_1_19","JER","1","19","19","Za su yi yaƙi da kai amma ba za su ci nasara a kanka ba, gama ina tare da kai, zan kuma kiyaye ka,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR2_1","025_2_1","JER","2","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("JR2_2","025_2_2","JER","2","2","2","“Tafi ka yi shela a kunnuwar Urushalima cewa, “ ‘Na tuna da amincin ƙuruciyarki, yadda kamar amarya kika ƙaunace ni kika kuma bi ni cikin hamada, cikin ƙasar da ba a yi shuka ba. ");
INSERT INTO hausa_vpl VALUES ("JR2_3","025_2_3","JER","2","3","3","Isra’ila tsattsarka ce ga Ubangiji, nunan fari na girbinsa; dukan waɗanda suka cinye ta an same su da laifi, masifa kuwa ta same su,’ ” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR2_4","025_2_4","JER","2","4","4","Ka saurari maganar Ubangiji, ya gidan Yaƙub, dukanku zuriyar gidan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("JR2_5","025_2_5","JER","2","5","5","Ga abin da Ubangiji yana cewa, “Wane laifi ne kakanninku sun same ni da shi, da suka tsaya nesa da ni? Sun bi gumakan banza su kansu suka kuma zama banza da kansu. ");
INSERT INTO hausa_vpl VALUES ("JR2_6","025_2_6","JER","2","6","6","Ba su yi tambaya, ‘Ina Ubangiji, wanda ya fitar da su daga Masar ya bishe su cikin jeji cikin hamada da kwazazzabai ƙasa mai fări da kuma duhu, ƙasar da ba kowa mai ratsa ta ba kowa kuma mai zama a cikinta?’ ");
INSERT INTO hausa_vpl VALUES ("JR2_7","025_2_7","JER","2","7","7","Na kawo ku zuwa ƙasa mai albarka don ku ci amfaninta da abubuwa masu yalwar da take bayarwa. Amma kuka zo kuka ƙazantar da ƙasata kuka kuma mai da gādona abin ƙyama. ");
INSERT INTO hausa_vpl VALUES ("JR2_8","025_2_8","JER","2","8","8","Firistoci ba su yi tambaya, ‘Ina Ubangiji ba.’ Waɗanda suke amfani da doka ba su san ni ba; shugabanni suka yi mini tawaye. Annabawa suka yi annabci ta wurin Ba’al, suna bin gumakan banza. ");
INSERT INTO hausa_vpl VALUES ("JR2_9","025_2_9","JER","2","9","9","“Saboda haka ina sāke tuhumarku,” in ji Ubangiji. “Zan kuma tuhumi ’ya’ya ’ya’yanku. ");
INSERT INTO hausa_vpl VALUES ("JR2_10","025_2_10","JER","2","10","10","Ku ƙetare zuwa tsibiran Kittim ku gani, ku aika zuwa Kedar ku duba da kyau; ku ga ko an taɓa yin wani abu haka. ");
INSERT INTO hausa_vpl VALUES ("JR2_11","025_2_11","JER","2","11","11","Akwai wata al’ummar da ta canja allolinta? (Duk da haka su ba alloli ba ne sam.) Amma mutanena sun musayar da ɗaukakarsu da gumakan banza. ");
INSERT INTO hausa_vpl VALUES ("JR2_12","025_2_12","JER","2","12","12","Ku girgiza saboda wannan, ya sammai, ku kuma razana don tsoro mai girma,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR2_13","025_2_13","JER","2","13","13","“Mutanena sun aikata zunubai guda biyu. Sun rabu da ni, ni da nake maɓulɓular ruwan rai, sun kuma haƙa tankunan ruwansu, tankuna ruwan da suka fashe da ba za su iya riƙe ruwa ba. ");
INSERT INTO hausa_vpl VALUES ("JR2_14","025_2_14","JER","2","14","14","Isra’ila bawa ne, bawa ne ta wurin haihuwa? Me ya sa ya zama ganima? ");
INSERT INTO hausa_vpl VALUES ("JR2_15","025_2_15","JER","2","15","15","Zakoki sun yi ruri; sun yi masa ruri. Sun lalatar da ƙasarsa; an ƙone garuruwansa aka kuma watse daga ciki. ");
INSERT INTO hausa_vpl VALUES ("JR2_16","025_2_16","JER","2","16","16","Haka ma, mutanen Memfis da Tafanes sun aske rawanin kanka ");
INSERT INTO hausa_vpl VALUES ("JR2_17","025_2_17","JER","2","17","17","Ba kai ne ba ka jawo wa kanka ba ta wurin rabuwa da Ubangiji Allahnka sa’ad da ya bi da kai a hanya? ");
INSERT INTO hausa_vpl VALUES ("JR2_18","025_2_18","JER","2","18","18","To, me ya sa za ka Masar don shan ruwa daga Shihor? Kuma me ya sa za ka Assuriya don shan ruwa daga Kogi? ");
INSERT INTO hausa_vpl VALUES ("JR2_19","025_2_19","JER","2","19","19","Muguntarka za tă hukunta ka; jan bayanka zai tsawata maka. Sai ka lura ka kuma gane yaya mugu da kuma ɗaci suke a gare ka sa’ad da ka rabu da Ubangiji Allahnka kuma ba ka tsorona,” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("JR2_20","025_2_20","JER","2","20","20","“Tun da daɗewa ka karya karkiyarka ka kuma tsintsinke sarƙoƙinka; sai ka ce, ‘Ba zan bauta maka ba!’ Tabbatacce, a kan kowane tudu mai tsayi da kuma a ƙarƙashin kowane ɗanyen itace ka kwanta kamar karuwa. ");
INSERT INTO hausa_vpl VALUES ("JR2_21","025_2_21","JER","2","21","21","Na shuka ka kamar zaɓaɓɓen inabi iri mai kyau da kuma wanda za a dogara a kai. Yaya kuma ka juya kana gāba da ni ka lalace, ka zama inabin jeji? ");
INSERT INTO hausa_vpl VALUES ("JR2_22","025_2_22","JER","2","22","22","Ko da yake ka wanke kanka da sabulu ka yi amfani da sabulu mai yawa, duk da haka har yanzu tabon laifinka yana nan a gabana,” in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("JR2_23","025_2_23","JER","2","23","23","“Yaya za ka ce, ‘Ban ƙazantu ba; ban bi Ba’al ba’? Duba yadda ka yi a cikin kwari; ka ga abin da ka yi. Kai kamar makwaɗaciyar raƙuma ce mai zafin gudu kana gudu nan da can, ");
INSERT INTO hausa_vpl VALUES ("JR2_24","025_2_24","JER","2","24","24","kamar jakar jejin da ta saba da hamada, mai busar iska cikin son barbaranta sa’ad da take son barbara wa zai iya hana ta? Jakin da yake nemanta, ba ya bukatar wahalar da kansa; a lokacin barbara za a same ta. ");
INSERT INTO hausa_vpl VALUES ("JR2_25","025_2_25","JER","2","25","25","Kada ka yi gudu har ƙafafunka su zama ba takalma maƙogwaronka kuma ya bushe. Amma sai ka ce, ‘Ba amfani! Ina ƙaunar baƙin alloli kuma dole in bi su.’ ");
INSERT INTO hausa_vpl VALUES ("JR2_26","025_2_26","JER","2","26","26","“Kamar yadda akan kunyatar da ɓarawo sa’ad da aka kama shi, haka gidan Isra’ila zai sha kunya, su, sarakunansu da shugabanninsu, firistocinsu da kuma annabawansu. ");
INSERT INTO hausa_vpl VALUES ("JR2_27","025_2_27","JER","2","27","27","Kuna ce wa itace, ‘Kai ne mahaifina,’ ga dutse kuma, ‘Kai ne ka haife ni.’ Sun juye mini bayansu ba fuskokinsu ba; duk da haka sa’ad da suna cikin wahala, sukan ce, ‘Zo ka cece mu!’ ");
INSERT INTO hausa_vpl VALUES ("JR2_28","025_2_28","JER","2","28","28","To ina allolin da kuka yi wa kanku? Bari su zo in suna iya cetonku sa’ad da kuke cikin wahala! Gama kuna da alloli masu yawa kamar yadda kuke da garuruwa, ya Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR2_29","025_2_29","JER","2","29","29","“Me ya sa kuke tuhumana? Dukanku kun yi mini tawaye,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR2_30","025_2_30","JER","2","30","30","“A banza na hukunta mutanenku; ba su yi gyara ba. Takobinku ya cinye annabawanku kamar zaki mai jin yunwa. ");
INSERT INTO hausa_vpl VALUES ("JR2_31","025_2_31","JER","2","31","31","“Ku na wannan zamani, ku saurari maganar Ubangiji. “Na zama wa Isra’ila hamada ne ko ƙasa mai babban duhu? Me ya sa mutanena suke cewa, ‘Muna da ’yanci mu yi ta yawo; ba za mu ƙara zuwa wurinka ba’? ");
INSERT INTO hausa_vpl VALUES ("JR2_32","025_2_32","JER","2","32","32","Budurwa za tă manta da kayan adonta amarya ta manta da kayan adon aurenta? Duk da haka mutanena sun manta da ni, kwanaki ba iyaka. ");
INSERT INTO hausa_vpl VALUES ("JR2_33","025_2_33","JER","2","33","33","Kuna da azanci sosai a bin masoya! Kai, ko mafiya muni cikin mata tana iya koya daga hanyoyinku. ");
INSERT INTO hausa_vpl VALUES ("JR2_34","025_2_34","JER","2","34","34","A rigunanku mutane kan sami jinin matalauta marasa laifi, ko da yake ba ku kama su suna fasawa su shiga ba. Duk da haka ");
INSERT INTO hausa_vpl VALUES ("JR2_35","025_2_35","JER","2","35","35","kuna cewa, ‘Ba ni da laifi; ba ya fushi da ni.’ Amma zan zartar da hukunci a kanku domin kun ce, ‘Ban yi zunubi ba.’ ");
INSERT INTO hausa_vpl VALUES ("JR2_36","025_2_36","JER","2","36","36","Don me kuke yawo da yawa haka, kuna ta canjin hanyoyinku? Masar za tă kunyata ku yadda kuka sha kunya a wurin Assuriya. ");
INSERT INTO hausa_vpl VALUES ("JR2_37","025_2_37","JER","2","37","37","Za ku kuma bar wurin da hannuwanku a kanku, gama Ubangiji ya ƙi waɗanda kuka amince da su; ba za ku zama abin taimako a gare su ba. ");
INSERT INTO hausa_vpl VALUES ("JR3_1","025_3_1","JER","3","1","1","“In mutum ya saki matarsa ta kuwa bar shi ta auri wani mutum, zai iya komo da ita kuma? Ƙasar ba za tă ƙazantu gaba ɗaya ba? Amma kun yi rayuwa kamar karuwa da masoya masu yawa yanzu za ki komo wurina?” In ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR3_2","025_3_2","JER","3","2","2","“Ta da idanu ki duba tsaunuka ki gani. Akwai wani wurin da ba a kwana da ke ba? A gefen hanya kin zauna kina jiran masoyanki, kin zauna kamar makiyayi a hamada. Kin ƙazantar da ƙasar da karuwancinki da muguntarki. ");
INSERT INTO hausa_vpl VALUES ("JR3_3","025_3_3","JER","3","3","3","Saboda haka an hana yayyafi, kuma babu ruwan bazara da ya sauka. Duk da haka kina da irin kallon da karuwa takan yi; kin ƙi ki ji kunya. ");
INSERT INTO hausa_vpl VALUES ("JR3_4","025_3_4","JER","3","4","4","Yanzu ba kin kira ni, ‘Mahaifina, abokina daga ƙuruciyata ba, ");
INSERT INTO hausa_vpl VALUES ("JR3_5","025_3_5","JER","3","5","5","kullum za ka riƙa fushi? Hasalarka za tă ci gaba har abada ne?’ Haka kike magana, amma kina aikata dukan muguntar da kika iya yi.” ");
INSERT INTO hausa_vpl VALUES ("JR3_6","025_3_6","JER","3","6","6","A zamanin Sarki Yosiya, Ubangiji ya ce mini, “Ka ga abin da marar amincin nan, Isra’ila ta yi? Ta haura kan kowane tudu mai tsayi da kowane gindin itace mai duhuwa ta yi zina a can. ");
INSERT INTO hausa_vpl VALUES ("JR3_7","025_3_7","JER","3","7","7","Na yi zaton bayan ta yi wannan duka, za tă komo wurina amma ba tă yi haka ba, ’yar’uwarta marar aminci nan Yahuda ta gani. ");
INSERT INTO hausa_vpl VALUES ("JR3_8","025_3_8","JER","3","8","8","Na ba wa Isra’ila marar bangaskiya takardar saki na kuwa kore ta saboda duk zinanta. Duk da haka na ga cewa ’yar’uwarta marar amincin nan Yahuda ba ta da tsoro; ita ma ta fita ta yi zina. ");
INSERT INTO hausa_vpl VALUES ("JR3_9","025_3_9","JER","3","9","9","Domin fasikancin Isra’ila bai yi tasiri gare ta ba, sai ta ƙazantar da ƙasar ta kuma yi zina da dutse da kuma itace. ");
INSERT INTO hausa_vpl VALUES ("JR3_10","025_3_10","JER","3","10","10","Duk da wannan duka, Yahuda ’yar’uwarta rashin amincin ba tă komo gare ni da dukan zuciyarta ba, sai a munafunce,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR3_11","025_3_11","JER","3","11","11","Ubangiji ya ce mini, “Isra’ila marar bangaskiya ta fi Yahuda marar aminci. ");
INSERT INTO hausa_vpl VALUES ("JR3_12","025_3_12","JER","3","12","12","Ka tafi, ka yi shelar saƙon nan wajen arewa cewa, “ ‘Ki komo, Isra’ila marar bangaskiya,’ in ji Ubangiji, ‘Ba zan ƙara yin fushi da ke ba, gama ni mai jinƙai ne,’ in ji Ubangiji, ‘Ba zan yi fushi da ke har abada ba. ");
INSERT INTO hausa_vpl VALUES ("JR3_13","025_3_13","JER","3","13","13","Ki dai yarda da laifinki kin yi wa Ubangiji Allahnki tawaye, kin watsar da alheranki ga baƙin alloli a ƙarƙashin kowane itace mai duhuwa, ba ki kuwa yi mini biyayya ba,’ ” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR3_14","025_3_14","JER","3","14","14","“Ku komo, ku mutane marasa bangaskiya,” in ji Ubangiji, “gama ni ne mijinku. Zan ɗauke ku, ɗaya daga garuruwanku da kuma biyu daga zuriyarku in kawo ku a Sihiyona. ");
INSERT INTO hausa_vpl VALUES ("JR3_15","025_3_15","JER","3","15","15","Sa’an nan zan ba ku makiyaya da suke yin abin da zuciyata take so, waɗanda za su bishe ku da sani da kuma fahimi. ");
INSERT INTO hausa_vpl VALUES ("JR3_16","025_3_16","JER","3","16","16","A kwanakin, sa’ad da kuka ƙaru sosai a ƙasar,” in ji Ubangiji, “mutane ba za su ƙara yin magana a kan, ‘Akwatin alkawarin Ubangiji ba.’ Ba zai ƙara shiga zuciyarsu ko su tuna ba; ko su bukace shi, ko kuwa su yi wani irinsa ba. ");
INSERT INTO hausa_vpl VALUES ("JR3_17","025_3_17","JER","3","17","17","A lokacin za su ce da Urushalima Kursiyin Ubangiji, kuma dukan al’ummai za su taru a Urushalima don su girmama sunan Ubangiji. Ba za su ƙara bin taurinkai zuciyarsu mai mugunta ba. ");
INSERT INTO hausa_vpl VALUES ("JR3_18","025_3_18","JER","3","18","18","A kwanakin gidan Yahuda zai haɗu da gidan Isra’ila, tare kuma za su zo daga ƙasar da take wajen arewa zuwa ƙasar da na ba kakanninsu gādo. ");
INSERT INTO hausa_vpl VALUES ("JR3_19","025_3_19","JER","3","19","19","“Ni kaina na faɗa, “ ‘Da farin ciki zan ɗauke ki kamar ’ya’yana maza in ba ki ƙasa mai daɗi, gādo mafi kyau da wata al’umma.’ Na zaci za ki kira ni ‘Mahaifi’ ba za ki ƙara rabuwa da bina ba. ");
INSERT INTO hausa_vpl VALUES ("JR3_20","025_3_20","JER","3","20","20","Amma kamar mace marar aminci ga mijinta, haka kika kasance marar aminci gare ni, ya gidan Isra’ila,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR3_21","025_3_21","JER","3","21","21","An ji kuka a filayen tuddai, kuka da roƙon mutanen Isra’ila, domin sun lalace hanyoyinsu sun kuma manta da Ubangiji Allahnsu. ");
INSERT INTO hausa_vpl VALUES ("JR3_22","025_3_22","JER","3","22","22","“Ku komo, mutane marasa bangaskiya; zan warkar da ku daga ja da bayanku.” “I, za mu zo wurinka, gama kai ne Ubangiji Allahnmu. ");
INSERT INTO hausa_vpl VALUES ("JR3_23","025_3_23","JER","3","23","23","Tabbatacce hayaniyar bin gumaka a kan tuddai da duwatsu banza ne; tabbatacce a wurin Ubangiji Allahnmu ne akwai ceton Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("JR3_24","025_3_24","JER","3","24","24","Daga ƙuruciyarmu allolin kunya sun cinye mu amfanin wahalar kakanninmu garkunan tumakinsu da na awakinsu, yaransu maza da mata. ");
INSERT INTO hausa_vpl VALUES ("JR3_25","025_3_25","JER","3","25","25","Bari mu kwanta mu sha kunya, bari kuma kunyarmu ta rufe mu. Mun yi wa Ubangiji Allahnmu zunubi, da mu da kakanninmu; daga ƙuruciyarmu har yă zuwa yau ba mu yi wa Ubangiji Allahnmu biyayya ba.” ");
INSERT INTO hausa_vpl VALUES ("JR4_1","025_4_1","JER","4","1","1","“In za ka komo, ya Isra’ila, ka komo gare ni,” in ji Ubangiji. “In ka kau da gumakanka masu banƙyama daga gabana ba ka ƙara karkace ba, ");
INSERT INTO hausa_vpl VALUES ("JR4_2","025_4_2","JER","4","2","2","kuma in cikin gaskiya da adalci ka rantse, ‘Muddin Ubangiji yana raye,’ to al’ummai za su sami albarka ta wurinsa kuma a cikinsa za su ɗaukaka.” ");
INSERT INTO hausa_vpl VALUES ("JR4_3","025_4_3","JER","4","3","3","Ga abin da Ubangiji yana ce wa mutanen Yahuda da kuma na Urushalima. “Ku nome ƙasarku kuma kada ku yi shuka cikin ƙayayyuwa. ");
INSERT INTO hausa_vpl VALUES ("JR4_4","025_4_4","JER","4","4","4","Ku yi wa kanku kaciya ga Ubangiji ku yi wa zukatanku kaciya, ku mutanen Yahuda da mutanen Urushalima, in ba haka ba hasalata za tă sauko ta ci kamar wuta saboda muguntar da kuka aikata za tă ci ba wanda zai kashe ta. ");
INSERT INTO hausa_vpl VALUES ("JR4_5","025_4_5","JER","4","5","5","“Ku yi shela a Yahuda ku kuma furta a Urushalima ku ce, ‘Ku busa ƙaho a ko’ina a ƙasar!’ Ku tā da murya da ƙarfi ku ce, ‘Ku tattaru! Bari mu gudu zuwa birane masu katanga!’ ");
INSERT INTO hausa_vpl VALUES ("JR4_6","025_4_6","JER","4","6","6","Ku tā da tuta don zuwa Sihiyona! Ku gudu ku nemi mafaka ba tare da jinkiri ba! Gama ina kawowa masifa daga arewa, mummunan hallaka kuwa.” ");
INSERT INTO hausa_vpl VALUES ("JR4_7","025_4_7","JER","4","7","7","Zaki ya fito daga ruƙuƙinsa; mai hallakarwar al’ummai ya kama hanya. Ya bar wurinsa don yă lalace ƙasarku. Garuruwanku za su zama kufai babu mazauna. ");
INSERT INTO hausa_vpl VALUES ("JR4_8","025_4_8","JER","4","8","8","Saboda haka ku yafa tufafin makoki, ku yi makoki da kuka, gama fushin Ubangiji bai juye daga gare mu ba. ");
INSERT INTO hausa_vpl VALUES ("JR4_9","025_4_9","JER","4","9","9","“A wannan rana,” in ji Ubangiji, “sarki da shugabanni za su fid da zuciya, firistoci za su razana, annabawa kuma za su yi mamaki.” ");
INSERT INTO hausa_vpl VALUES ("JR4_10","025_4_10","JER","4","10","10","Sai na ce, “Kash, Ubangiji Mai Iko Duka, yaya ka ruɗi mutanen nan da kuma Urushalima gaba ɗaya haka ta wurin cewa, ‘Za ku zauna lafiya,’ sa’ad da takobi yana a maƙogwaronmu.” ");
INSERT INTO hausa_vpl VALUES ("JR4_11","025_4_11","JER","4","11","11","A lokacin za a faɗa wa mutanen nan da kuma Urushalima cewa, “Iska mai zafi daga tuddan hamada za tă hura zuwa wajen mutanena, amma ba don ta sheƙe ko ta rairaye; ba; ");
INSERT INTO hausa_vpl VALUES ("JR4_12","025_4_12","JER","4","12","12","iska mafificin ƙarfi da ta fito daga gare ni. Yanzu na zartar da hukuncina a kansu.” ");
INSERT INTO hausa_vpl VALUES ("JR4_13","025_4_13","JER","4","13","13","Duba! Yana zuwa kamar gizagizai, kekunan yaƙinsa suna zuwa kamar guguwa, dawakansa sun fi gaggafa sauri. Kaiton mu! Mun shiga uku! ");
INSERT INTO hausa_vpl VALUES ("JR4_14","025_4_14","JER","4","14","14","Ya Urushalima, ki wanke mugunta daga zuciyarki ki sami ceto. Har yaushe za ki zauna riƙe da mugayen tunani? ");
INSERT INTO hausa_vpl VALUES ("JR4_15","025_4_15","JER","4","15","15","Murya ta shela daga Dan, tana furtawa masifa daga tuddan Efraim. ");
INSERT INTO hausa_vpl VALUES ("JR4_16","025_4_16","JER","4","16","16","“A faɗa wa al’ummai wannan, a furta wannan game Urushalima. ‘Sojoji masu ƙawanya suna zuwa daga ƙasa mai nisa, suna tā da kirarin yaƙi a kan biranen Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR4_17","025_4_17","JER","4","17","17","Sun kewaye ta kamar masu gadin fili, domin ta yi mini tawaye,’ ” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR4_18","025_4_18","JER","4","18","18","“Halinki da ayyukanki sun kawo wannan a kanki. Hukuncinki ke nan. Yana da ɗaci! Ya soke ki har zuciyarki!” ");
INSERT INTO hausa_vpl VALUES ("JR4_19","025_4_19","JER","4","19","19","Azabana, azabana! Ina birgima cikin zafi. Azabana, azabar zuciyata! Zuciyata yana bugu a cikina, Ba zan yi shiru ba. Gama na ji karan ƙaho; na ji kirarin yaƙi. ");
INSERT INTO hausa_vpl VALUES ("JR4_20","025_4_20","JER","4","20","20","Masifa kan masifa; dukan ƙasar ta zama kufai. Cikin ɗan lokaci aka rurrushe tentuna nawa, mafakata ba zato. ");
INSERT INTO hausa_vpl VALUES ("JR4_21","025_4_21","JER","4","21","21","Har yaushe zan dubi tutar yaƙi in kuma ji karar ƙaho? ");
INSERT INTO hausa_vpl VALUES ("JR4_22","025_4_22","JER","4","22","22","“Mutanena wawaye ne; ba su san ni ba. Su ’ya’ya ne marasa azanci; ba su da fahimi. Suna da dabarar aikata mugunta; ba su san yadda za su aikata alheri ba.” ");
INSERT INTO hausa_vpl VALUES ("JR4_23","025_4_23","JER","4","23","23","Na dubi duniya, na ga cewa marar siffa ce babu kome; sammai kuma, haskensu ya tafi. ");
INSERT INTO hausa_vpl VALUES ("JR4_24","025_4_24","JER","4","24","24","Na dubi duwatsu, sai na ga suna makyarkyata; dukan tuddai kuwa suna lilo. ");
INSERT INTO hausa_vpl VALUES ("JR4_25","025_4_25","JER","4","25","25","Na duba, sai na ga ba kowa; kowane tsuntsu a sarari da ya tsere. ");
INSERT INTO hausa_vpl VALUES ("JR4_26","025_4_26","JER","4","26","26","Na duba, sai na ga ƙasa mai amfani ta zama hamada; dukan garuruwanta sun zama kufai a gaban Ubangiji, a gaban zafin fushinsa. ");
INSERT INTO hausa_vpl VALUES ("JR4_27","025_4_27","JER","4","27","27","Ga abin da Ubangiji yana cewa, “Dukan ƙasar za tă zama kufai, ko da yake ba zan hallaka ta gaba ɗaya ba. ");
INSERT INTO hausa_vpl VALUES ("JR4_28","025_4_28","JER","4","28","28","Saboda haka duniya za tă yi kuka sammai a bisa kuma za su yi duhu, domin na yi magana kuma ba zan fasa ba, na yanke shawara ba kuwa zan janye ba.” ");
INSERT INTO hausa_vpl VALUES ("JR4_29","025_4_29","JER","4","29","29","Da jin motsin mahayan dawakai da maharba kowane gari ya ruga da gudu. Waɗansu suka shiga kurmi; waɗansu suka hau cikin duwatsu. Dukan garuruwan sun fashe tas; babu wani da yake zama a ciki. ");
INSERT INTO hausa_vpl VALUES ("JR4_30","025_4_30","JER","4","30","30","Me kike yi, ya wadda aka ragargaza? Me ya sa kika sanya mulufi kika sa kayan adon zinariya? Me ya sa kika sa wa idanunki tozali? Kin yi kwalliyarki a banza. Masoyanki sun bar ki; suna neman ranki. ");
INSERT INTO hausa_vpl VALUES ("JR4_31","025_4_31","JER","4","31","31","Na ji kuka kamar na mace mai naƙuda, nishi kamar na wadda take haihuwa ɗanta na fari, kukan Diyar Sihiyona tana haki, da ƙyar take numfashi, tana miƙa hannuwanta tana cewa, “Wayyo ni kaina! Na suma; an ba da raina ga masu kisana.” ");
INSERT INTO hausa_vpl VALUES ("JR5_1","025_5_1","JER","5","1","1","“Ku yi ta kai da kawowa a titunan Urushalima, ku dudduba ko’ina ku kuma lura, ku bincika cikin dandalinta. Ko za ku sami mutum guda wanda yake aikata adalci wanda yake kuma son bin gaskiya, sai in gafarta wa wannan birni. ");
INSERT INTO hausa_vpl VALUES ("JR5_2","025_5_2","JER","5","2","2","Ko da yake suna cewa, ‘Muddin Ubangiji yana raye,’ duk da haka suna rantsuwar ƙarya.” ");
INSERT INTO hausa_vpl VALUES ("JR5_3","025_5_3","JER","5","3","3","Ya Ubangiji, idanunka ba sa ganin gaskiya? Ka buge su, amma ba su ji zafi ba; ka ragargaza su, amma suka ƙi su gyara. Fuskarsu ta ƙeƙashe fiye da dutse suka ƙi su tuba. ");
INSERT INTO hausa_vpl VALUES ("JR5_4","025_5_4","JER","5","4","4","Na yi tunani, “Waɗannan ne kawai matalauta; su wawaye ne, gama ba su san hanyar Ubangiji ba, ko abubuwan da Allahnsu yake bukata ba. ");
INSERT INTO hausa_vpl VALUES ("JR5_5","025_5_5","JER","5","5","5","Saboda haka zan tafi wurin shugabanni in yi musu magana; tabbatacce sun san hanyar Ubangiji, da abubuwan da Allahnsu yake bukata.” Amma da nufi guda su ma suka karye karkiyar suka tsintsinke sarƙoƙin. ");
INSERT INTO hausa_vpl VALUES ("JR5_6","025_5_6","JER","5","6","6","Saboda haka zaki daga kurmi zai fāɗa musu, kyarkeci kuma daga hamada zai cinye su, damisa za tă yi musu ƙawanya kusa da garuruwansu yă yayyage duk wanda ya kuskura ya fita, gama tawayensu da girma yake jan bayansu kuma yana da yawa. ");
INSERT INTO hausa_vpl VALUES ("JR5_7","025_5_7","JER","5","7","7","“Me zai sa in gafarta muku? ’Ya’yanku sun yashe ni sun yi rantsuwa da allolin da ba alloli ba ne. Na biya musu dukan bukatunsu, duk da haka suka yi zina suka tattaru a gidajen karuwai. ");
INSERT INTO hausa_vpl VALUES ("JR5_8","025_5_8","JER","5","8","8","An ciyar da su sosai, kamar ƙosassun ingarmu, masu jaraba, kowanne yana haniniya, yana neman matar maƙwabcinsa. ");
INSERT INTO hausa_vpl VALUES ("JR5_9","025_5_9","JER","5","9","9","Ba zan hukunta su saboda wannan ba?” In ji Ubangiji. “Bai kamata in yi ramuwa a kan irin al’ummar nan ba? ");
INSERT INTO hausa_vpl VALUES ("JR5_10","025_5_10","JER","5","10","10","“Ku ratsa cikin gonakin inabinta ku cinye su, amma kada ku hallaka su gaba ɗaya. Ku kakkaɓe rassanta, gama waɗannan mutane ba na Ubangiji ba ne. ");
INSERT INTO hausa_vpl VALUES ("JR5_11","025_5_11","JER","5","11","11","Gidan Isra’ila da gidan Yahuda sun zama marasa aminci gaba ɗaya gare ni” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR5_12","025_5_12","JER","5","12","12","Sun yi ƙarya a kan Ubangiji; sun ce, “Ba zai yi kome ba! Ba wata masifar da za tă same mu; ba za mu taɓa ganin takobi ko yunwa ba. ");
INSERT INTO hausa_vpl VALUES ("JR5_13","025_5_13","JER","5","13","13","Annabawa holoƙo ne kawai maganar kuwa ba ta cikinsu; saboda haka bari abin da suke faɗi ya koma kansu.” ");
INSERT INTO hausa_vpl VALUES ("JR5_14","025_5_14","JER","5","14","14","Saboda haka ga abin Ubangiji Allah Maɗaukaki yana cewa, “Domin mutanen sun yi waɗannan maganganu, zan mai da maganata a bakinku wuta waɗannan mutane kuwa su zama itacen da za tă ci. ");
INSERT INTO hausa_vpl VALUES ("JR5_15","025_5_15","JER","5","15","15","Ya gidan Isra’ila,” in ji Ubangiji, “Ina kawo al’umma daga nesa a kanku al’umma ce ta tun dā mai ƙarfin hali, mutane ne da ba ku san harshensu ba, waɗanda ba za ku fahimci abin da suke faɗa ba. ");
INSERT INTO hausa_vpl VALUES ("JR5_16","025_5_16","JER","5","16","16","Kwarinsu kamar buɗaɗɗen kabari ne; dukansu jarumawa ne. ");
INSERT INTO hausa_vpl VALUES ("JR5_17","025_5_17","JER","5","17","17","Za su cinye amfanin gonakinku da abincinku, za su cinye ’ya’yanku maza da mata; za su cinye garkunan tumakinku da na awakinku, za su cinye ’ya’yan inabinku da na ɓaurenku. Da takobi za su hallaka biranenku masu katanga. ");
INSERT INTO hausa_vpl VALUES ("JR5_18","025_5_18","JER","5","18","18","“Amma ko a cikin waɗancan kwanaki,” in ji Ubangiji, “ba zan hallaka ku gaba ɗaya ba. ");
INSERT INTO hausa_vpl VALUES ("JR5_19","025_5_19","JER","5","19","19","Sa’ad da kuma mutanen suka yi tambaya, ‘Me ya sa Ubangiji Allahnmu ya yi dukan wannan gare mu?’ Sai ka amsa musu, ‘Yadda kuka yashe ni kuka kuma bauta wa baƙin alloli a ƙasarku, haka yanzu za ku bauta wa baƙi a ƙasar da ba taku ba.’ ");
INSERT INTO hausa_vpl VALUES ("JR5_20","025_5_20","JER","5","20","20","“Ka sanar da wannan ga gidan Yaƙub ka yi shelarsa a Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR5_21","025_5_21","JER","5","21","21","Ku ji wannan, ku wawaye marasa azanci, waɗanda suke da idanu amma ba sa gani, waɗanda suke da kunnuwa amma ba sa ji. ");
INSERT INTO hausa_vpl VALUES ("JR5_22","025_5_22","JER","5","22","22","Bai kamata ku ji tsorona ba?” In ji Ubangiji. “Bai kamata ku yi rawar jiki a gabana ba? Na sa yashi ya zama iyakar teku, madawwamiyar iyakar da ba zai tsallake ba. Raƙuman ruwa za su iya yin hauka, amma ba za su iya haye ta ba; za su iya yin ruri, amma ba za su iya ƙetare ta ba. ");
INSERT INTO hausa_vpl VALUES ("JR5_23","025_5_23","JER","5","23","23","Amma mutanen nan suna da tauraren zukata, kuma ’yan tawaye ne; sun kauce suka kuma rabu da ni. ");
INSERT INTO hausa_vpl VALUES ("JR5_24","025_5_24","JER","5","24","24","Ba sa faɗa wa kansu, ‘Bari mu ji tsoron Ubangiji Allahnmu, wanda yake ba mu ruwan sama a kan kari na kaka da na bazara, wanda kullum yake tabbatar mana da girbi.’ ");
INSERT INTO hausa_vpl VALUES ("JR5_25","025_5_25","JER","5","25","25","Laifofinku sun raba ku da waɗannan abubuwa; zunubanku sun hana ku samun alheri. ");
INSERT INTO hausa_vpl VALUES ("JR5_26","025_5_26","JER","5","26","26","“A cikin mutanena an sami mugaye waɗanda suke kwanton ɓauna kamar masu sa tarko wa tsuntsaye kamar waɗanda suke kafa tarko don su kama mutane. ");
INSERT INTO hausa_vpl VALUES ("JR5_27","025_5_27","JER","5","27","27","Kamar keji cike da tsuntsaye, gidajensu sun cika da ruɗu; sun yi arziki suka kuma zama masu iko ");
INSERT INTO hausa_vpl VALUES ("JR5_28","025_5_28","JER","5","28","28","suka kuma yi ƙiba, suka yi bul-bul. Mugayen ayyukansu ba su da iyaka; ba sa wa marayu shari’ar adalci, ba sa kāre ’yancin matalauta. ");
INSERT INTO hausa_vpl VALUES ("JR5_29","025_5_29","JER","5","29","29","Bai kamata in hukunta su saboda wannan ba?” In ji Ubangiji. “Bai kamata in yi ramuwa a kan irin al’umma kamar wannan ba? ");
INSERT INTO hausa_vpl VALUES ("JR5_30","025_5_30","JER","5","30","30","“Abin banmamaki da bantsoro ya faru a ƙasar. ");
INSERT INTO hausa_vpl VALUES ("JR5_31","025_5_31","JER","5","31","31","Annabawa suna annabcin ƙarya, firistoci suna mulki da ikon kansu, mutanena kuma suna son haka. Amma me za ku yi a ƙarshe? ");
INSERT INTO hausa_vpl VALUES ("JR6_1","025_6_1","JER","6","1","1","“Ku gudu neman mafaka, mutanen Benyamin! Ku gudu daga Urushalima! Ku busa ƙaho a Tekowa! Ku ba da alama a Bet-Hakkerem! Gama masifa tana zuwa daga arewa, mummunar hallaka ce kuwa. ");
INSERT INTO hausa_vpl VALUES ("JR6_2","025_6_2","JER","6","2","2","Zan hallaka Diyar Sihiyona, kyakkyawa da kuma mai laulayi. ");
INSERT INTO hausa_vpl VALUES ("JR6_3","025_6_3","JER","6","3","3","Makiyaya da garkunansu za su taso mata; za su kafa tentunansu kewaye da ita, kowanne yana lura da sashensa.” ");
INSERT INTO hausa_vpl VALUES ("JR6_4","025_6_4","JER","6","4","4","“Mu shirya don yaƙi da ita! Ku tashi, bari mu fāɗa mata da tsakar rana! Amma, kaito, rana tana fāɗuwa, inuwar yamma kuwa sai ƙaran tsawo take. ");
INSERT INTO hausa_vpl VALUES ("JR6_5","025_6_5","JER","6","5","5","Saboda haka ku tashi, bari mu fāɗa mata da dare mu rurrushe kagaranta!” ");
INSERT INTO hausa_vpl VALUES ("JR6_6","025_6_6","JER","6","6","6","Ga abin da Ubangiji Maɗaukaki yana cewa, “Ku sassare itatuwan ku tula ƙasa kewaye da Urushalima. Dole a hukunta wannan birni; saboda ya cika da zalunci. ");
INSERT INTO hausa_vpl VALUES ("JR6_7","025_6_7","JER","6","7","7","Kamar yadda rijiya takan ba da ruwarta, haka birnin yake da muguntarsa. Ana jin labarin rikici da hallaka a cikinsa; ciwonsa da mikinsa kullum suna a gabana. ");
INSERT INTO hausa_vpl VALUES ("JR6_8","025_6_8","JER","6","8","8","Ki ji gargaɗi, ya Urushalima, ko kuwa in juya daga gare ki in mai da ƙasarki kufai don kada wani ya zauna a cikinta.” ");
INSERT INTO hausa_vpl VALUES ("JR6_9","025_6_9","JER","6","9","9","Ga abin da Ubangiji Maɗaukaki yana cewa, “Bari su yi kalan raguwar Isra’ila a yi kalan sarai yadda ake yi wa inabi; ka sāke miƙa hannunka a kan rassan, kamar mai tattara inabi.” ");
INSERT INTO hausa_vpl VALUES ("JR6_10","025_6_10","JER","6","10","10","Ga wa zan yi magana in kuma gargaɗar? Wa zai saurare ni? Kunnuwansu sun toshe don kada su ji. Maganar Ubangiji ta zama abin zargi a gare su; ba sa jin daɗinta. ");
INSERT INTO hausa_vpl VALUES ("JR6_11","025_6_11","JER","6","11","11","Amma ina cike da fushin Ubangiji, kuma ba na iya kannewa. “Ka kwararo shi a kan yara a titi da kuma a kan samarin da suka tattaru; za a kama miji da mata a cikinsa, tsofaffi da suka tsufa tukub. ");
INSERT INTO hausa_vpl VALUES ("JR6_12","025_6_12","JER","6","12","12","Za a ba da gidajensu ga waɗansu, tare da gonakinsu da matansu, sa’ad da na miƙa hannuna gāba da waɗanda suke zama a ƙasar,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR6_13","025_6_13","JER","6","13","13","“Daga ƙarami zuwa babba, dukansu masu haɗama ne don riba; har da annabawa da firistoci, dukansu suna aikata rashin gaskiya. ");
INSERT INTO hausa_vpl VALUES ("JR6_14","025_6_14","JER","6","14","14","Sukan ɗaura mikin mutanena sai ka ce mikin ba shi da matsala. Suna cewa, ‘Lafiya, Lafiya,’ alhali kuwa ba lafiya. ");
INSERT INTO hausa_vpl VALUES ("JR6_15","025_6_15","JER","6","15","15","Suna jin kunyar halinsu na banƙyama? A’a, ba sa jin kunya sam; ba su ma san yadda za su soke kai ba. Saboda haka za su fāɗi tare da fāɗaɗɗu; za a hamɓarar da su sa’ad da na hukunta su,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR6_16","025_6_16","JER","6","16","16","Ga abin da Ubangiji yana cewa, “Ku tsaya kan hanyoyi, ku duba; ku nemi hanyoyin dā, ku tambaya inda hanyar mai kyau take, ku yi tafiya a kanta, za ku kuwa sami hutu wa rayukanku. Amma kun ce, ‘Ba za mu bi ta ba.’ ");
INSERT INTO hausa_vpl VALUES ("JR6_17","025_6_17","JER","6","17","17","Na naɗa muku masu tsaro a kanku na kuma ce, ‘Ku saurari karan ƙaho!’ Amma kuka ce, ‘Ba za mu saurara ba.’ ");
INSERT INTO hausa_vpl VALUES ("JR6_18","025_6_18","JER","6","18","18","Saboda haka ku, ya al’ummai; ku lura Ya shaidu, abin da zai faru da su. ");
INSERT INTO hausa_vpl VALUES ("JR6_19","025_6_19","JER","6","19","19","Ki ji, ya duniya. Zan kawo masifa a kan waɗannan mutane, sakayyar ƙulle-ƙullensu, domin ba su saurari maganata ba suka kuma ƙi dokata. ");
INSERT INTO hausa_vpl VALUES ("JR6_20","025_6_20","JER","6","20","20","Babu riba a kawo mini turare daga Sheba ko rake mai zaƙi daga ƙasa mai nisa? Ba zan karɓi hadayunku na ƙonawa ba; ba na jin daɗin sadakokinku.” ");
INSERT INTO hausa_vpl VALUES ("JR6_21","025_6_21","JER","6","21","21","Saboda haka ga abin da Ubangiji yana cewa, “Zan sa abin tuntuɓe gaban mutanena. Mahaifi da ’ya’yansa maza za su yi tuntuɓe a kan juna; maƙwabci da abokansa za su hallaka.” ");
INSERT INTO hausa_vpl VALUES ("JR6_22","025_6_22","JER","6","22","22","Ga abin da Ubangiji yana cewa, “Duba, sojoji suna zuwa daga ƙasar arewa; babbar al’umma ce ta yunƙuro daga iyakokin duniya. ");
INSERT INTO hausa_vpl VALUES ("JR6_23","025_6_23","JER","6","23","23","Suna riƙe da baka da māshi; mugaye ne kuma marasa tausayi. Motsinsu kamar ƙugin teku ne yayinda suke hawan dawakansu; suna zuwa a jere kamar wanda ya yi shirin yaƙi don su fāɗa miki, ya Diyar Sihiyona.” ");
INSERT INTO hausa_vpl VALUES ("JR6_24","025_6_24","JER","6","24","24","Mun ji labari a kansu, hannuwanmu kuwa suka yi laƙwas. Azaba ta kama mu, zafi kamar na mace mai naƙuda. ");
INSERT INTO hausa_vpl VALUES ("JR6_25","025_6_25","JER","6","25","25","Kada ku fita zuwa gonaki ko ku yi tafiya a hanyoyi, gama abokin gāba yana da takobi, kuma akwai razana ko’ina. ");
INSERT INTO hausa_vpl VALUES ("JR6_26","025_6_26","JER","6","26","26","Ya mutanena, ku sanya tufafin makoki ku yi birgima a toka; ku yi kuka mai zafi irin wanda akan yi wa ɗa tilo, gama nan da nan mai hallakarwa zai auko mana. ");
INSERT INTO hausa_vpl VALUES ("JR6_27","025_6_27","JER","6","27","27","“Na maishe ka mai jarrabawar ƙarfe mutanena ne kuwa ƙarfen, don ka lura ka kuma gwada hanyoyinsu. ");
INSERT INTO hausa_vpl VALUES ("JR6_28","025_6_28","JER","6","28","28","Su duka masu taurinkai ne, ’yan tawaye, suna yawo suna baza jita-jita. Su tagulla ne da ƙarfe; dukansu lalatattu ne. ");
INSERT INTO hausa_vpl VALUES ("JR6_29","025_6_29","JER","6","29","29","Mazuga yana zuga da ƙarfi don yă ƙone dalma da wuta, amma tacewa yana tafiya a banza; ba a fitar da mugaye. ");
INSERT INTO hausa_vpl VALUES ("JR6_30","025_6_30","JER","6","30","30","Ana ce da su azurfar da aka ƙi, gama Ubangiji ya ƙi su.” ");
INSERT INTO hausa_vpl VALUES ("JR7_1","025_7_1","JER","7","1","1","Maganar da ta zo wa Irmiya ke nan daga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR7_2","025_7_2","JER","7","2","2","“Ka tsaya a ƙofar gidan Ubangiji, a can kuwa ka yi shelar wannan saƙo. “ ‘Ku ji maganar Ubangiji, dukanku mutanen Yahuda waɗanda suke shiga ta waɗannan ƙofofi don yin sujada ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR7_3","025_7_3","JER","7","3","3","Ga abin da Ubangiji Maɗaukaki, Allahna Isra’ila, yana cewa ku gyara hanyoyinku da ayyukanku, zan kuwa bar ku ku zauna a wannan wuri. ");
INSERT INTO hausa_vpl VALUES ("JR7_4","025_7_4","JER","7","4","4","Kada ku dogara ga maganganun nan na ruɗarwa cewa, “Wannan shi ne haikalin Ubangiji, haikalin Ubangiji, haikalin Ubangiji!” ");
INSERT INTO hausa_vpl VALUES ("JR7_5","025_7_5","JER","7","5","5","In dai kuka canja hanyoyinku da ayyukanku kuma kuna aikata adalci da junanku, ");
INSERT INTO hausa_vpl VALUES ("JR7_6","025_7_6","JER","7","6","6","in ba ku zalunci baƙo, maraya ko gwauruwa ba kuma in ba ku zub da jinin marar laifi a wannan wuri ba, in kuma ba ku bi waɗansu alloli da za su cuce ku ba, ");
INSERT INTO hausa_vpl VALUES ("JR7_7","025_7_7","JER","7","7","7","to, zan bar ku ku zauna a wannan wuri, a ƙasar da na ba kakanninku har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("JR7_8","025_7_8","JER","7","8","8","Amma ga shi, kuna dogara ga maganganu na ruɗami marasa amfani. ");
INSERT INTO hausa_vpl VALUES ("JR7_9","025_7_9","JER","7","9","9","“ ‘Za ku yi sata da kisa, ku yi zina da rantsuwar ƙarya, kuna ƙone turare wa Ba’al kuna kuma bin waɗansu allolin da ba ku sani ba, ");
INSERT INTO hausa_vpl VALUES ("JR7_10","025_7_10","JER","7","10","10","sa’an nan ku zo ku tsaya a gabana a wannan gida, wanda ake kira da Sunana, kuna cewa, “An cece mu,” mun dace mu aikata waɗannan abubuwa banƙyama? ");
INSERT INTO hausa_vpl VALUES ("JR7_11","025_7_11","JER","7","11","11","Wannan gidan da ake kira da Sunana ya zama kogon ’yan fashi ne a gare ku? Amma ina kallo! In ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR7_12","025_7_12","JER","7","12","12","“ ‘Yanzu ku fita zuwa Shilo inda na fara maishe shi wurin zama don Sunana, ku ga abin da na yi masa saboda muguntar mutanen Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("JR7_13","025_7_13","JER","7","13","13","Yayinda kuke yin dukan waɗannan abubuwa, in ji Ubangiji, na yi muku magana sau da sau, amma ba ku ji ba; na kira ku, amma ba ku amsa ba. ");
INSERT INTO hausa_vpl VALUES ("JR7_14","025_7_14","JER","7","14","14","Saboda haka, abin da na yi wa Shilo shi ne yanzu zan yi wa gidan da ake kira da Sunana, haikalin da kuka dogara a kai, wurin da na ba ku da kuma kakanninku. ");
INSERT INTO hausa_vpl VALUES ("JR7_15","025_7_15","JER","7","15","15","Zan kore ku daga gabana, kamar yadda na yi ga dukan ’yan’uwanku, mutanen Efraim.’ ");
INSERT INTO hausa_vpl VALUES ("JR7_16","025_7_16","JER","7","16","16","“Saboda haka kada ka yi addu’a don wannan mutane ko ka yi wani kuka ko roƙo dominsu, gama ba zan ji ka ba. ");
INSERT INTO hausa_vpl VALUES ("JR7_17","025_7_17","JER","7","17","17","Ba ka gani abin da suke yi a biranen Yahuda da kuma a titunan Urushalima? ");
INSERT INTO hausa_vpl VALUES ("JR7_18","025_7_18","JER","7","18","18","Yara sukan tara itace, iyaye suka hura wuta, mata kuma sukan kwaɓa kullu don su yi wa Sarauniyar Sama waina. Sukan miƙa hadayun sha ga waɗansu alloli don su tsokane ni in yi fushi. ");
INSERT INTO hausa_vpl VALUES ("JR7_19","025_7_19","JER","7","19","19","Amma ni ne suke tsokana? In ji Ubangiji Ashe, ba kansu ne suke cuta, suna kunyata kansu ba? ");
INSERT INTO hausa_vpl VALUES ("JR7_20","025_7_20","JER","7","20","20","“ ‘Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa fushina da hasalata za su kwarara a wannan wuri, a kan mutum da dabba, a kan itatuwan fili da a kan amfanin gona, za su yi ta kuna, ba kuwa za a kashe ba. ");
INSERT INTO hausa_vpl VALUES ("JR7_21","025_7_21","JER","7","21","21","“ ‘Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila yana cewa ci gaba, ku ƙara hadayun ƙonawarku da sauran sadakoki ku kuma yi ta cin naman! ");
INSERT INTO hausa_vpl VALUES ("JR7_22","025_7_22","JER","7","22","22","Gama sa’ad da na fitar da kakanninku daga Masar na kuma yi musu magana, ban ba su dokoki kawai game da hadayun ƙonawa da sadakoki ba, ");
INSERT INTO hausa_vpl VALUES ("JR7_23","025_7_23","JER","7","23","23","amma na ba su wannan umarni cewa ku yi mini biyayya, zan kuwa zama Allahnku ku kuma ku zama mutanena. Ku yi tafiya cikin dukan hanyoyin da na umarce ku, don ku zauna lafiya. ");
INSERT INTO hausa_vpl VALUES ("JR7_24","025_7_24","JER","7","24","24","Amma ba su saurara ba, ba su kuwa kula ba; a maimako, suka bi shawarar kansu da ta taurare muguwar zukatansu. Su ja da baya a maimakon yin gaba. ");
INSERT INTO hausa_vpl VALUES ("JR7_25","025_7_25","JER","7","25","25","Daga lokacin da kakanninku suka bar Masar har yă zuwa yau, kullum na yi ta aikan bayina annabawa. ");
INSERT INTO hausa_vpl VALUES ("JR7_26","025_7_26","JER","7","26","26","Amma ba su saurare ni ba, ba su kula ba. Sai suka taurare zukatansu suka aikata mugun abu fiye da na kakanninsu.’ ");
INSERT INTO hausa_vpl VALUES ("JR7_27","025_7_27","JER","7","27","27","“Sa’ad da ka faɗa musu wannan duka, ba za su saurare ka ba; sa’ad da ka kira su, ba za su amsa ba. ");
INSERT INTO hausa_vpl VALUES ("JR7_28","025_7_28","JER","7","28","28","Saboda haka ka faɗa musu cewa, ‘Wannan ce al’ummar da ba tă yi biyayya ga Ubangiji Allahnta ba, ba kuwa ta karɓi gyara ba. Gaskiya ta ƙare; ta ɓace gaba ɗaya daga leɓunansu. ");
INSERT INTO hausa_vpl VALUES ("JR7_29","025_7_29","JER","7","29","29","“ ‘Ku aske gashin kanku ku zubar; ku yi makoki a filayen tuddai, gama Ubangiji ya ƙi ’yan zamanin nan ya kuma rabu da su saboda fushin da suka ba shi. ");
INSERT INTO hausa_vpl VALUES ("JR7_30","025_7_30","JER","7","30","30","“ ‘Mutanen Yahuda sun yi mugunta a gabana, in ji Ubangiji. Sun kafa gumakansu masu banƙyama a gidan da ake kira da Sunana suka ƙazantar da shi. ");
INSERT INTO hausa_vpl VALUES ("JR7_31","025_7_31","JER","7","31","31","Sun gida masujadan Tofet a Kwarin Ben Hinnom don miƙa ’ya’yansu maza da mata a wuta, abin da ban yi umarni ba, ba kuwa yi tunaninsa ba. ");
INSERT INTO hausa_vpl VALUES ("JR7_32","025_7_32","JER","7","32","32","Saboda haka ku yi hankali, kwanaki suna zuwa in ji Ubangiji, sa’ad da mutane ba za su ƙara kira wurin Tofet ko Kwarin Ben Hinnom ba, amma Kwarin Kisa, gama za su binne matattu a Tofet sai har ba sauran wuri. ");
INSERT INTO hausa_vpl VALUES ("JR7_33","025_7_33","JER","7","33","33","Sa’an nan gawawwakin wannan mutane za su zama abinci ga tsuntsayen sama da kuma namun jeji, ba za a kuwa sami wani da zai kore su ba. ");
INSERT INTO hausa_vpl VALUES ("JR7_34","025_7_34","JER","7","34","34","Zan kawo ƙarshen muryar murna da farin ciki da muryar amarya da ango a garuruwan Yahuda da kuma a titunan Urushalima, gama ƙasar za tă zama kufai. ");
INSERT INTO hausa_vpl VALUES ("JR8_1","025_8_1","JER","8","1","1","“ ‘A wancan lokaci, in ji Ubangiji, za a fitar da ƙasusuwan sarakuna da na shugabannin Yahuda, ƙasusuwan firistoci da na annabawa, da kuma ƙasusuwan mutanen Urushalima daga kaburbura. ");
INSERT INTO hausa_vpl VALUES ("JR8_2","025_8_2","JER","8","2","2","Za a shimfiɗa su a rana da wata da kuma dukan taurarin sammai, waɗanda suka ƙaunata suka kuma bauta wa, waɗanda suka bi suka nemi shawarar suka kuma yi wa sujada. Ba za a tattara su ko a binne su ba, amma za su zama kamar juji a jibge a ƙasa. ");
INSERT INTO hausa_vpl VALUES ("JR8_3","025_8_3","JER","8","3","3","Duk inda na kore su zuwa, dukan waɗanda suka ragu na wannan muguwar al’umma za su gwammaci mutuwa da rai, in ji Ubangiji Maɗaukaki.’ ");
INSERT INTO hausa_vpl VALUES ("JR8_4","025_8_4","JER","8","4","4","“Fada musu cewa, ‘Ga abin da Ubangiji yana cewa, “ ‘Sa’ad da mutane suka fāɗi, ba sa tashi ne? Sa’ad da mutum ya kauce, ba ya dawowa? ");
INSERT INTO hausa_vpl VALUES ("JR8_5","025_8_5","JER","8","5","5","To, me ya sa waɗannan mutane suka kauce? Me ya sa Urushalima kullum take kaucewa? Sun manne wa ƙarya; suka ƙi su dawo. ");
INSERT INTO hausa_vpl VALUES ("JR8_6","025_8_6","JER","8","6","6","Na saurara sosai, amma ba su faɗi wata maganar kirki ba. Ba wanda ya tuba daga muguntarsa, sai ma cewa yake, “Me na yi?” Kowa ta kai-ta-kai yake kamar dokin da ya kutsa kai a fagen fama. ");
INSERT INTO hausa_vpl VALUES ("JR8_7","025_8_7","JER","8","7","7","Ko shamuwa ta sararin sama ma takan san lokutan da aka tsara mata, kurciya, mashirare da kuma zalɓe sukan lura da lokacin ƙauransu. Amma mutanena ba su san abubuwan da Ubangiji yake bukata ba. ");
INSERT INTO hausa_vpl VALUES ("JR8_8","025_8_8","JER","8","8","8","“ ‘Yaya za ku ce, “Muna da hikima, gama muna da dokar Ubangiji,” alhali alƙalamin ƙarya na magatakarda ya yi ƙarya? ");
INSERT INTO hausa_vpl VALUES ("JR8_9","025_8_9","JER","8","9","9","Za a kunyatar da masu hikima; za su yi fargaba a kuma kama su. Da yake sun ƙi maganar Ubangiji, wace irin hikima kuka ce kuke da ita? ");
INSERT INTO hausa_vpl VALUES ("JR8_10","025_8_10","JER","8","10","10","Saboda haka zan ba da matansu ga waɗansu gonakinsu kuma ga waɗansu da suka ci da yaƙi. Tun daga ƙarami har zuwa babba, kowannensu yana haɗamar cin muguwar riba; har da annabawa da firistoci ma, kowannensu yana ƙarya. ");
INSERT INTO hausa_vpl VALUES ("JR8_11","025_8_11","JER","8","11","11","Sukan ɗaura mikin mutanena sai ka ce mikin ba shi da matsala. Suna cewa, “Lafiya, Lafiya,” alhali kuwa ba lafiya. ");
INSERT INTO hausa_vpl VALUES ("JR8_12","025_8_12","JER","8","12","12","Sukan ji kunyar halin banƙyamarsu kuwa? Sam, ba su da kunya ko kaɗan; ba su ma san yadda za su ji kunya ba. Saboda haka sukan fāɗi tare da fāɗaɗɗu; za su fāɗi sa’ad da aka hukunta su, in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR8_13","025_8_13","JER","8","13","13","“ ‘Zan ƙwace girbinsu, in ji Ubangiji. Ba a za sami inabi a kuringa ba. Ba za a sami ’ya’ya a itacen ɓaure ba, ganyayensu kuwa za su bushe. Abin da na ba su za a ƙwace.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR8_14","025_8_14","JER","8","14","14","Me ya sa muke zama a nan? Mu tattaru! Mu gudu zuwa birane masu katanga mu mutu a can! Gama Ubangiji Allahnmu ya ƙaddara mana mutuwa ya kuma ba mu ruwan dafi mu sha, domin mun yi masa zunubi. ");
INSERT INTO hausa_vpl VALUES ("JR8_15","025_8_15","JER","8","15","15","Mun sa zuciya ga salama amma ba lafiya, mun sa zuciya ga lokacin warkarwa amma sai ga razana. ");
INSERT INTO hausa_vpl VALUES ("JR8_16","025_8_16","JER","8","16","16","Daga Dan ana jin tirjin dawakan abokin gāba; da jin haniniyar ingarmunsu dukan ƙasar ta girgiza. Sun zo su cinye ƙasar da kome da yake cikinta, birni da dukan mazaunanta. ");
INSERT INTO hausa_vpl VALUES ("JR8_17","025_8_17","JER","8","17","17","“Duba, zan aika macizai masu dafi a cikinku, kāsā, waɗanda ba su da maƙari, za su kuwa sassare ku,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR8_18","025_8_18","JER","8","18","18","Ya mai ta’aziyyata a cikin baƙin ciki, zuciyata ta ɓaci ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("JR8_19","025_8_19","JER","8","19","19","Ka saurari kukan mutanena daga ƙasa mai nisa suna cewa, “Ubangiji ba ya a Sihiyona ne? Sarkinta ba ya can ne kuma?” “Me ya sa suka tsokane ni da gumakansu har na yi fushi, da baƙin gumakansu marasa amfani?” ");
INSERT INTO hausa_vpl VALUES ("JR8_20","025_8_20","JER","8","20","20","“Girbi ya wuce, damuna ta ƙare, ba a kuwa cece mu ba.” ");
INSERT INTO hausa_vpl VALUES ("JR8_21","025_8_21","JER","8","21","21","Da yake an ragargazar da mutanena, an ragargaza ni ke nan; na yi kuka, tsoro ya kama ni. ");
INSERT INTO hausa_vpl VALUES ("JR8_22","025_8_22","JER","8","22","22","Ba magani ne a Gileyad? Ba likita ne a can? To, me ya sa ba warkarwa wa raunin mutanena? ");
INSERT INTO hausa_vpl VALUES ("JR9_1","025_9_1","JER","9","1","1","Da ma kaina maɓulɓulan ruwa ne idanuna kuma maɓulɓulan hawaye! Da sai in yi kuka dare da rana saboda mutanena da aka kashe. ");
INSERT INTO hausa_vpl VALUES ("JR9_2","025_9_2","JER","9","2","2","Da ma a hamada ina da wurin da matafiye za su sauka, don in bar mutanena in tafi in bar su; gama dukansu mazinata ne, taron mutane marasa aminci. ");
INSERT INTO hausa_vpl VALUES ("JR9_3","025_9_3","JER","9","3","3","“Sun tanƙwasa harshensu kamar baka, don su harba ƙarya; ba da gaskiya ba ne suke nasara a cikin ƙasar. Sukan tashi daga wannan zunubi zuwa wancan; ba su san ni ba,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR9_4","025_9_4","JER","9","4","4","“Ka yi hankali da abokanka; kada ka amince da ’yan’uwanka. Gama kowane ɗan’uwa munafuki ne, kowane aboki kuma mai kushe ne. ");
INSERT INTO hausa_vpl VALUES ("JR9_5","025_9_5","JER","9","5","5","Aboki kan ruɗi aboki, ba mai faɗar gaskiya. Sun koya wa harshensu faɗar ƙarya; sun gajiyar da kansu da yin zunubi. ");
INSERT INTO hausa_vpl VALUES ("JR9_6","025_9_6","JER","9","6","6","Kai kana zama a tsakiyar ruɗu; cikin ruɗunsu sun ƙi su san ni,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR9_7","025_9_7","JER","9","7","7","Saboda haka ga abin da Ubangiji Maɗaukaki yana cewa, “Ga shi zan tace in kuma gwada su, gama me kuwa zan yi saboda zunubin mutanena? ");
INSERT INTO hausa_vpl VALUES ("JR9_8","025_9_8","JER","9","8","8","Harshensu kibiya ce mai dafi; yana magana da ruɗu. Da bakinsa kowa yana maganar alheri da maƙwabcinsa, amma a zuciyarsa ya sa masa tarko. ");
INSERT INTO hausa_vpl VALUES ("JR9_9","025_9_9","JER","9","9","9","Bai kamata in hukunta su saboda wannan ba?” In ji Ubangiji. “Bai kamata in ɗau fansa a kan irin al’umma kamar wannan ba?” ");
INSERT INTO hausa_vpl VALUES ("JR9_10","025_9_10","JER","9","10","10","Zan yi kuka in yi kururuwa saboda duwatsu in kuma yi makoki game da wuraren kiwon hamada. Sun zama kango ba wanda yake bi cikinta, ba a kuma jin kukan shanu. Tsuntsaye sararin sama sun gudu namun jeji ma duk sun watse. ");
INSERT INTO hausa_vpl VALUES ("JR9_11","025_9_11","JER","9","11","11","“Zan mai da Urushalima tsibin kufai, wurin zaman diloli; zan kuma lalace garuruwan Yahuda saboda haka ba wanda zai zauna a can.” ");
INSERT INTO hausa_vpl VALUES ("JR9_12","025_9_12","JER","9","12","12","Wane mutum ne yana da isashiyar hikimar fahimtar wannan? Wa Ubangiji ya umarta da zai iya yin bayani? Me ya sa aka lalace ƙasar ta zama kufai kamar hamada da ba wanda zai iya ratsa ta? ");
INSERT INTO hausa_vpl VALUES ("JR9_13","025_9_13","JER","9","13","13","Ubangiji ya ce, “Domin sun bar dokata, wadda na sa a gabansu; ba su yi biyayya da ni ko su bi dokata ba. ");
INSERT INTO hausa_vpl VALUES ("JR9_14","025_9_14","JER","9","14","14","A maimako, sun bi taurin zuciyarsu; suka bi Ba’al, yadda kakanninsu suka koya musu.” ");
INSERT INTO hausa_vpl VALUES ("JR9_15","025_9_15","JER","9","15","15","Saboda haka, ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila yana cewa, “Ga shi zan sa wannan mutane su ci abinci mai ɗaci su kuma sha ruwan dafi. ");
INSERT INTO hausa_vpl VALUES ("JR9_16","025_9_16","JER","9","16","16","Zan watsar da su a cikin al’ummai da su da kakanninsu ba su sani ba, zan kuma fafare su da takobi sai na hallaka su.” ");
INSERT INTO hausa_vpl VALUES ("JR9_17","025_9_17","JER","9","17","17","Ga abin da Ubangiji Maɗaukaki yana cewa, “Ku lura yanzu! Ku kira mata masu makoki su zo ku aika wa gwanaye a cikinsu su zo. ");
INSERT INTO hausa_vpl VALUES ("JR9_18","025_9_18","JER","9","18","18","Bari su zo da sauri su yi kuka a kanmu sai idanunmu sun cika da hawaye giranmu kuma su jiƙe sharkaf. ");
INSERT INTO hausa_vpl VALUES ("JR9_19","025_9_19","JER","9","19","19","An ji karar kuka daga Sihiyona cewa, ‘Duba yadda muka lalace! Duba irin babban kunyar da muka sha! Dole mu bar ƙasar domin gidajenmu sun lalace.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR9_20","025_9_20","JER","9","20","20","Yanzu, ya mata, ku ji maganar Ubangiji; ku buɗe kunnuwanku ga maganar bakina. Ku koya wa ’yan matanku yadda za su yi kuka; ku koya wa juna makoki. ");
INSERT INTO hausa_vpl VALUES ("JR9_21","025_9_21","JER","9","21","21","Mutuwa ta haura ta tagoginmu ta kuma shiga katangarmu; ta karkashe ’ya’ya a tituna ta kuma karkashe samari a dandali. ");
INSERT INTO hausa_vpl VALUES ("JR9_22","025_9_22","JER","9","22","22","Ka ce, “Ga abin da Ubangiji ya furta, “ ‘Gawawwakin mutane za su fāɗi kamar juji a fili, kamar hatsin da aka yanka a bayan mai girbi, da ba mai tara su.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR9_23","025_9_23","JER","9","23","23","Ga abin da Ubangiji yana cewa, “Kada mai hikima ya yi fariya da hikimarsa ko mai ƙarfi ya yi fariya da ƙarfinsa ko mai arziki ya yi fariya da arzikinsa, ");
INSERT INTO hausa_vpl VALUES ("JR9_24","025_9_24","JER","9","24","24","amma bari shi wanda yake taƙama ya yi taƙama da wannan, cewa ya fahimci ya kuma san ni, cewa ni ne Ubangiji, wanda yake yin alheri, gaskiya da kuma adalci a duniya, gama a waɗannan ne nake jin daɗi,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR9_25","025_9_25","JER","9","25","25","“Kwanaki suna zuwa,” in ji Ubangiji, “sa’ad da zan hukunta dukan waɗanda aka yi musu kaciya kawai a jiki, ");
INSERT INTO hausa_vpl VALUES ("JR9_26","025_9_26","JER","9","26","26","Masar, Yahuda, Edom, Ammon, Mowab da dukan waɗanda suke zaune a hamada a wurare masu nisa. Gama dukan waɗannan al’ummai marasa kaciya ne, har dukan gidan Isra’ila ma marasa kaciya ne a zuciya.” ");
INSERT INTO hausa_vpl VALUES ("JR10_1","025_10_1","JER","10","1","1","Ku ji abin da Ubangiji yana ce muku, ya gidan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("JR10_2","025_10_2","JER","10","2","2","Ga abin da Ubangiji yana cewa, “Kada ku koyi hanyoyin al’ummai ko ku razana game da alamun sararin sama, ko da yake al’ummai sun razana saboda su. ");
INSERT INTO hausa_vpl VALUES ("JR10_3","025_10_3","JER","10","3","3","Gama al’adun mutane banza ne; sukan yanke itace daga kurmi, sai mai sassaƙa yă sassaƙa shi da gizago. ");
INSERT INTO hausa_vpl VALUES ("JR10_4","025_10_4","JER","10","4","4","Sukan yi masa ado da azurfa da kuma zinariya; sukan ɗauki guduma su kafa shi da ƙusoshi, don kada yă fāɗi. ");
INSERT INTO hausa_vpl VALUES ("JR10_5","025_10_5","JER","10","5","5","Kamar dodon gona cikin gonar kabewa, haka gumakansu ba sa iya magana; dole a yi ta ɗaukansu domin ba za su iya tafiya ba. Kada ku ji tsoronsu; ba za su iya yi wa wani lahani ba ba sa iya yin wani abin kirki.” ");
INSERT INTO hausa_vpl VALUES ("JR10_6","025_10_6","JER","10","6","6","Babu wani kamar ka, ya Ubangiji; kai mai girma ne, kuma sunanka yana da girma da kuma iko. ");
INSERT INTO hausa_vpl VALUES ("JR10_7","025_10_7","JER","10","7","7","Wane ne ba zai girmama ka ba, Ya Sarkin al’ummai? Tsoronka wajibi ne. A cikin dukan masu hikima na al’ummai kuma cikin dukan mulkokinsu, babu kamar ka. ");
INSERT INTO hausa_vpl VALUES ("JR10_8","025_10_8","JER","10","8","8","Dukansu marasa azanci ne wawaye; gumakan itacen banza ne suke koya musu. ");
INSERT INTO hausa_vpl VALUES ("JR10_9","025_10_9","JER","10","9","9","An kawo ƙeraren azurfa daga Tarshish zinariya kuma daga Ufaz. Abin da gwani da maƙerin zinariya suka yi sa’an nan aka yi masa ado da mulufi da shunayya dukan aikin gwanaye. ");
INSERT INTO hausa_vpl VALUES ("JR10_10","025_10_10","JER","10","10","10","Amma Ubangiji shi ne Allah na gaskiya; shi ne Allah mai rai, madawwamin sarki. Sa’ad da ya yi fushi, ƙasa takan girgiza; al’ummai ba sa iya jure da hasalarsa. ");
INSERT INTO hausa_vpl VALUES ("JR10_11","025_10_11","JER","10","11","11","“Ka faɗa musu wannan, ‘Waɗannan alloli, waɗanda ba su yi sammai da ƙasa ba, za su hallaka daga duniya da kuma daga ƙarƙashin sammai.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR10_12","025_10_12","JER","10","12","12","Amma Allah ya yi duniya ta wurin ikonsa; ya kafa duniya ta wurin hikimarsa ya shimfiɗa sammai ta wurin fahiminsa. ");
INSERT INTO hausa_vpl VALUES ("JR10_13","025_10_13","JER","10","13","13","Sa’ad da ya yi tsawa, ruwaye a cikin sammai sukan yi ƙugi; yakan sa gizagizai su taso daga iyakokin duniya. Yakan aiki walƙiya da ruwan sama ya fitar da iska daga gidajen ajiyarsa. ");
INSERT INTO hausa_vpl VALUES ("JR10_14","025_10_14","JER","10","14","14","Kowa marar azanci ne, marar ilimi; kowane maƙerin zinariya zai sha kunya saboda gumakansa. Siffofinsa ƙarya ne; ba su da numfashi a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("JR10_15","025_10_15","JER","10","15","15","Su ba kome ba ne, aikin ruɗami ne; Sa’ad da hukuncinsu ya yi za su lalace. ");
INSERT INTO hausa_vpl VALUES ("JR10_16","025_10_16","JER","10","16","16","Shi da yake Rabon Yaƙub ba kamar waɗannan yake ba, gama shi ne Mahaliccin abubuwa duka, har da Isra’ila, kabilar gādonsa Ubangiji Maɗaukaki ne sunansa. ");
INSERT INTO hausa_vpl VALUES ("JR10_17","025_10_17","JER","10","17","17","Ku tattara kayayyakinku don ku bar ƙasar, ku da kuke zaune a wurin da aka kewaye da yaƙi. ");
INSERT INTO hausa_vpl VALUES ("JR10_18","025_10_18","JER","10","18","18","Gama haka Ubangiji ya faɗa, “A wannan lokaci zan jefar da waɗanda suke zaune a ƙasar; zan kawo damuwa a kansu domin a kama su.” ");
INSERT INTO hausa_vpl VALUES ("JR10_19","025_10_19","JER","10","19","19","Tawa ta ƙare, saboda raunin da aka yi mini! Raunina ba mai warkewa ba ne! Duk da haka na ce wa kaina, “Wannan ciwona ne, dole kuma in jure da shi.” ");
INSERT INTO hausa_vpl VALUES ("JR10_20","025_10_20","JER","10","20","20","An lalatar da tentina; dukan igiyoyinsa sun tsintsinke. ’Ya’yana maza sun bar ni ba sa nan; ba wanda aka bari da zai kafa tentina ko ya kafa mini mafaka. ");
INSERT INTO hausa_vpl VALUES ("JR10_21","025_10_21","JER","10","21","21","Makiyaya marasa azanci ne kuma ba sa neman nufin Ubangiji; saboda haka ba sa nasara dukan garkensu kuwa ya watse. ");
INSERT INTO hausa_vpl VALUES ("JR10_22","025_10_22","JER","10","22","22","Ku saurara! Rahoto yana zuwa babban hargitsi daga ƙasar arewa! Zai mai da garuruwan Yahuda kufai, mazaunin diloli. ");
INSERT INTO hausa_vpl VALUES ("JR10_23","025_10_23","JER","10","23","23","Na sani, ya Ubangiji, cewa ran mutum ba nasa ba ne; ba mutum ne yake kiyaye takawarsa ba. ");
INSERT INTO hausa_vpl VALUES ("JR10_24","025_10_24","JER","10","24","24","Ka yi mini gyara, Ubangiji, amma fa da adalci kaɗai ba cikin fushinka ba, don kada ka wofinta ni. ");
INSERT INTO hausa_vpl VALUES ("JR10_25","025_10_25","JER","10","25","25","Ka zuba hasalarka a kan al’umman da ba su san ka ba, a kan mutanen da ba sa kira bisa sunanka. Gama sun cinye Yaƙub; sun cinye shi gaba ɗaya suka kuma lalace wurin zamansa. ");
INSERT INTO hausa_vpl VALUES ("JR11_1","025_11_1","JER","11","1","1","Ga maganar da ta zo wa Irmiya daga wurin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR11_2","025_11_2","JER","11","2","2","“Ka saurari zancen wannan alkawari ka kuma faɗe su ga mutanen Yahuda da kuma waɗanda suke zaune a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR11_3","025_11_3","JER","11","3","3","Ka faɗa musu cewa ga abin da Ubangiji, Allah na Isra’ila yana cewa, ‘La’ananne ne wanda bai kula da zancen alkawarin nan ba, ");
INSERT INTO hausa_vpl VALUES ("JR11_4","025_11_4","JER","11","4","4","zancen da na umarci kakanni-kakanninku sa’ad da na fitar da su daga Masar, daga cikin tanderun narkewar ƙarfe.’ Na ce, ‘Ku yi mini biyayya ku kuma aikata kowane abin da na umarce ku, za ku kuwa zama mutanena, ni kuwa zan zama Allahnku. ");
INSERT INTO hausa_vpl VALUES ("JR11_5","025_11_5","JER","11","5","5","Sa’an nan zan cika rantsuwar da na yi wa kakanni-kakanninku, da zan ba su ƙasa mai zub da madara da kuma zuma’ ƙasar da kuka mallaka a yau.” Sai na amsa na ce, “Amin, Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("JR11_6","025_11_6","JER","11","6","6","Sai Ubangiji ya ce mini, “Ka yi shelar dukan maganan nan a biranen Yahuda da titunan Urushalima duka cewa, ‘Su saurari zancen alkawarin nan, su aikata. ");
INSERT INTO hausa_vpl VALUES ("JR11_7","025_11_7","JER","11","7","7","Daga lokacin da na fitar da kakanni-kakanninku daga Masar har yă zuwa yau, na gargaɗe su sau da sau, ina cewa, “Ku yi mini biyayya.” ");
INSERT INTO hausa_vpl VALUES ("JR11_8","025_11_8","JER","11","8","8","Amma ba su kasa kunne ko su saurara ba, a maimako, sai suka bi taurinkai na mugayen zukatansu. Saboda haka na kawo musu dukan la’anonin alkawarin da na riga na umarce su, su bi amma ba su kiyaye ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR11_9","025_11_9","JER","11","9","9","Sa’an nan Ubangiji ya ce mini, “Akwai maƙarƙashiya a cikin mutanen Yahuda da waɗanda suke zaune a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR11_10","025_11_10","JER","11","10","10","Sun koma ga zunuban kakanni kakanninsu, waɗanda suka ƙi su saurari maganata. Suka bi waɗansu alloli don su bauta musu. Da gidan Isra’ila da kuma gidan Yahuda duk sun take alkawarin da na yi da kakanni kakanninsu. ");
INSERT INTO hausa_vpl VALUES ("JR11_11","025_11_11","JER","11","11","11","Saboda haka ga abin da Ubangiji yana cewa, ‘Zan kawo masifa a kansu wadda ba za su iya tsere mata ba. Ko da yake suna kuka gare ni, ba zan saurare su ba. ");
INSERT INTO hausa_vpl VALUES ("JR11_12","025_11_12","JER","11","12","12","Garuruwan Yahuda da mutanen Urushalima za su tafi su yi kuka ga allolin da suke ƙona wa turare, amma ba za su taimake su ba sam sa’ad da masifar ta auku. ");
INSERT INTO hausa_vpl VALUES ("JR11_13","025_11_13","JER","11","13","13","Kuna da alloli masu yawa yadda kuke da garuruwa, ya Yahuda; kuma bagadan da kuka yi don ƙona turare wa allahn nan Ba’al abin kunya sun yi yawa kamar titunan Urushalima.’ ");
INSERT INTO hausa_vpl VALUES ("JR11_14","025_11_14","JER","11","14","14","“Kada ka yi addu’a domin wannan mutane ko ka miƙa wani roƙo ko kuka dominsu, domin ba zan saurara ba sa’ad da suka kira gare ni a lokacin ƙuncinsu. ");
INSERT INTO hausa_vpl VALUES ("JR11_15","025_11_15","JER","11","15","15","“Mene ne ƙaunatacciyata take yi a haikali da yake ta yin ƙulle-ƙullen mugayen makircinta tare da mutane masu yawa? Tsarkakar nama zai iya kawar da hukuncinki? Sa’ad da kike yin muguntarki sa’an nan ki yi farin ciki.” ");
INSERT INTO hausa_vpl VALUES ("JR11_16","025_11_16","JER","11","16","16","Ubangiji ya kira ki itacen zaitun mai inuwa kyakkyawa mai ’ya’ya masu kyau. Amma da ƙugin babbar hadari zai cinna masa wuta, rassansa za su kakkarye. ");
INSERT INTO hausa_vpl VALUES ("JR11_17","025_11_17","JER","11","17","17","Ubangiji Maɗaukaki, wanda ya dasa ki, ya furta miki masifa, domin gidan Isra’ila da kuma gidan Yahuda sun aikata mugunta suka kuma tsokane ni in yi fushi ta wurin ƙona wa Ba’al turare. ");
INSERT INTO hausa_vpl VALUES ("JR11_18","025_11_18","JER","11","18","18","Domin Ubangiji ya bayyana mini maƙarƙashiyarsu, na santa, gama a wannan lokaci ya nuna mini abin da suke yi. ");
INSERT INTO hausa_vpl VALUES ("JR11_19","025_11_19","JER","11","19","19","Na kasance kamar ɗan rago marar faɗa wanda aka kai mayanka; ban gane cewa sun ƙulla mini maƙarƙashiya, suna cewa, “Bari mu lalatar da itacen duk da ’ya’yansa; bari mu datse shi daga ƙasar masu rai, har da ba za a ƙara tunawa da sunansa ba.” ");
INSERT INTO hausa_vpl VALUES ("JR11_20","025_11_20","JER","11","20","20","Amma, ya Ubangiji Maɗaukaki, kai da kake yin shari’a da adalci kake gwada zuciya da kuma tunani, ka sa in ga sakayyar da za ka yi musu, gama a gare ka na danƙa maganata. ");
INSERT INTO hausa_vpl VALUES ("JR11_21","025_11_21","JER","11","21","21","“Saboda haka ga abin da Ubangiji yana cewa game da mutanen Anatot, waɗanda suke neman ranka suna kuma cewa, ‘Kada ka yi annabci da sunan Ubangiji in ba haka za ka mutu a hannunmu’ ");
INSERT INTO hausa_vpl VALUES ("JR11_22","025_11_22","JER","11","22","22","saboda haka ga abin da Ubangiji Maɗaukaki yana cewa, ‘Zan hukunta su. Samarinsu za su mutu ta wurin takobi, ’ya’yansu maza da mata kuwa ta wurin yunwa. ");
INSERT INTO hausa_vpl VALUES ("JR11_23","025_11_23","JER","11","23","23","Babu raguwar da za a bar musu, domin zan kawo masifa a kan mutanen Anatot a shekarar hukuncinsu.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR12_1","025_12_1","JER","12","1","1","Kullum kai mai adalci ne, ya Ubangiji, sa’ad da na kawo ƙara a gabanka. Duk da haka zan yi magana da kai game da shari’arka. Me ya sa mugaye suke nasara? Me ya sa dukan maciya amana suke zama ba damuwa? ");
INSERT INTO hausa_vpl VALUES ("JR12_2","025_12_2","JER","12","2","2","Ka dasa su, sun kuwa yi saiwa; sun yi girma suna ba da ’ya’ya. Kullum sunanka yana a bakinsu amma kana nesa da zuciyarsu. ");
INSERT INTO hausa_vpl VALUES ("JR12_3","025_12_3","JER","12","3","3","Duk da haka ka san ni, ya Ubangiji; kana ganina ka kuma gwada tunanina game da kai. Ka ja su kamar tumakin da za a yanka! Ka ware su don ranar yanka! ");
INSERT INTO hausa_vpl VALUES ("JR12_4","025_12_4","JER","12","4","4","Har yaushe ƙasar za tă kasance busasshiya ciyawar kowane fili ta bushe? Domin waɗanda suke zaune cikinta mugaye ne, dabbobi da tsuntsaye sun hallaka. Ban da haka ma, mutane suna cewa, “Ba zai ga abin da yake faruwa da mu ba.” ");
INSERT INTO hausa_vpl VALUES ("JR12_5","025_12_5","JER","12","5","5","“In ka yi tsere da mutane a ƙafa suka kuma gajiyar da kai, yaya za ka yi gasa da dawakai? In ka yi tuntuɓe a lafiyayyiyar ƙasa, ƙaƙa za ka yi a kurmin Urdun? ");
INSERT INTO hausa_vpl VALUES ("JR12_6","025_12_6","JER","12","6","6","’Yan’uwanka, iyalinka har su ma sun bashe ka; sun tā da kuka mai ƙarfi a kanka. Kada ka amince da su, ko da yake suna faɗa maganganu masu kyau game da kai. ");
INSERT INTO hausa_vpl VALUES ("JR12_7","025_12_7","JER","12","7","7","“Zan yashe gidana, in rabu da gādona; Zan ba da wadda nake ƙauna a hannuwan abokan gābanta. ");
INSERT INTO hausa_vpl VALUES ("JR12_8","025_12_8","JER","12","8","8","Gādona ya zama mini kamar zaki a kurmi. Yana mini ruri; saboda haka na ƙi shi. ");
INSERT INTO hausa_vpl VALUES ("JR12_9","025_12_9","JER","12","9","9","Ashe, gādona bai zama mini kamar dabbare dabbaren tsuntsu mai cin nama da sauran tsuntsaye masu cin nama suka kewaye shi da faɗa ba? Tafi ka tattaro dukan namun jeji; ka kawo su su ci. ");
INSERT INTO hausa_vpl VALUES ("JR12_10","025_12_10","JER","12","10","10","Makiyaya masu yawa za su lalace gonar inabina su tattake gonata; za su mai da gonata mai kyau kango marar amfani. ");
INSERT INTO hausa_vpl VALUES ("JR12_11","025_12_11","JER","12","11","11","Za tă zama kango, busasshiya da kuma kango a gabana; ƙasar duka za tă zama kango domin ba wanda ya kula. ");
INSERT INTO hausa_vpl VALUES ("JR12_12","025_12_12","JER","12","12","12","A kan dukan tsaunukan nan na hamada masu hallakarwa za su zo, gama takobin Ubangiji zai ci daga wannan iyaka ƙasa zuwa wancan; ba wanda zai zauna lafiya. ");
INSERT INTO hausa_vpl VALUES ("JR12_13","025_12_13","JER","12","13","13","Za su shuka alkama, su girbe ƙayayyuwa; za su gajiyar da kansu, ba za su kuwa sami kome ba. Saboda haka ku sha kunyar abin da kuka girbe saboda zafin fushin Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("JR12_14","025_12_14","JER","12","14","14","Ga abin da Ubangiji yana cewa, “Game da dukan mugayen maƙwabtana waɗanda suka ƙwace gādon da na ba wa mutanena Isra’ila kuwa, zan tumɓuke su daga ƙasashensu zan kuma tumɓuke gidan Yahuda daga cikinsu. ");
INSERT INTO hausa_vpl VALUES ("JR12_15","025_12_15","JER","12","15","15","Amma bayan na tumɓuke su, zan sāke jin tausayi in komo da kowannensu zuwa gādonsa da kuma ƙasarsa. ");
INSERT INTO hausa_vpl VALUES ("JR12_16","025_12_16","JER","12","16","16","In kuma suka koyi al’amuran mutanena sosai suka kuma yi rantsuwa da sunana, suna cewa, ‘Muddin Ubangiji yana raye’ kamar yadda sun taɓa koya wa jama’ata yin rantsuwa da Ba’al, sa’an nan za su kahu a cikin jama’ata. ");
INSERT INTO hausa_vpl VALUES ("JR12_17","025_12_17","JER","12","17","17","Amma duk al’ummar da ba tă saurara ba, zan tumɓuke ta ɗungum in kuma hallaka ta,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR13_1","025_13_1","JER","13","1","1","Ga abin da Ubangiji ya faɗa mini, “Tafi ka sayo abin ɗamara na lilin ka sha ɗamara da shi, amma kada ka bari yă taɓa ruwa.” ");
INSERT INTO hausa_vpl VALUES ("JR13_2","025_13_2","JER","13","2","2","Saboda haka na sayo abin ɗamara, yadda Ubangiji ya umarce ni, na kuwa sha ɗamara da shi. ");
INSERT INTO hausa_vpl VALUES ("JR13_3","025_13_3","JER","13","3","3","Sai maganar Ubangiji ta zo mini sau na biyu cewa, ");
INSERT INTO hausa_vpl VALUES ("JR13_4","025_13_4","JER","13","4","4","“Ka ɗauki abin ɗamara da ka sayo, wanda ka ɗaura, ka tafi yanzu zuwa Fera ka ɓoye shi a cikin kogon dutse.” ");
INSERT INTO hausa_vpl VALUES ("JR13_5","025_13_5","JER","13","5","5","Saboda haka na tafi na ɓoye shi a Fera, yadda Ubangiji ya ce mini. ");
INSERT INTO hausa_vpl VALUES ("JR13_6","025_13_6","JER","13","6","6","Bayan ’yan kwanaki sai Ubangiji ya ce mini, “Tafi yanzu zuwa Fera ka ɗauko abin ɗamara da na ce maka ka ɓoye a can.” ");
INSERT INTO hausa_vpl VALUES ("JR13_7","025_13_7","JER","13","7","7","Sai na tafi Fera da haka na ɗauko abin ɗamara daga wurin da na ɓoye shi, amma abin ɗamara yanzu ya lalace ya zama ba shi da amfani sam. ");
INSERT INTO hausa_vpl VALUES ("JR13_8","025_13_8","JER","13","8","8","Sai maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("JR13_9","025_13_9","JER","13","9","9","“Ga abin da Ubangiji yana cewa, ‘Haka zan lalatar da alfarmar Yahuda da yawan alfarmar Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR13_10","025_13_10","JER","13","10","10","Waɗannan mugayen mutane, waɗanda suka ƙi saurari maganata, waɗanda suka biye wa taurin zuciyarsu suka bi waɗansu alloli don su bauta su kuma yi musu sujada, za su zama kamar wannan abin ɗamara gaba ɗaya marasa amfani! ");
INSERT INTO hausa_vpl VALUES ("JR13_11","025_13_11","JER","13","11","11","Gama kamar yadda abin ɗamara kan kame gindin mutum tam, haka zan daure dukan gidan Isra’ila da dukan gidan Yahuda gare ni,’ in ji Ubangiji, ‘domin su zama jama’a, da suna, da yabo, da daraja a gare ni, amma sun ƙi ji.’ ");
INSERT INTO hausa_vpl VALUES ("JR13_12","025_13_12","JER","13","12","12","“Faɗa musu cewa, ‘Ga abin da Ubangiji, Allah na Isra’ila, yana cewa a cika kowace salkar ruwan inabi da ruwan inabi.’ In kuwa suka ce maka, ‘Ba mu san cewa ya kamata a cika kowace salkar ruwan inabi da ruwan inabi ba?’ ");
INSERT INTO hausa_vpl VALUES ("JR13_13","025_13_13","JER","13","13","13","Sai ka ce musu, ‘Ga abin da Ubangiji yana cewa, zan cika dukan waɗanda suke zama a ƙasar da buguwa, har ma da sarakunan da suke zama a kursiyin Dawuda, firistoci, annabawa da dukan waɗanda suke zaune a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR13_14","025_13_14","JER","13","14","14","Zan fyaɗe su a kan juna, iyaye da ’ya’yansu maza, in ji Ubangiji. Tausayi ko jinƙai, ko juyayi ba zai hana ni hallaka su ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR13_15","025_13_15","JER","13","15","15","Ku ji ku kuma saurara, kada ku yi girman kai, gama Ubangiji ya yi magana. ");
INSERT INTO hausa_vpl VALUES ("JR13_16","025_13_16","JER","13","16","16","Ku ɗaukaka Ubangiji Allahnku kafin ya kawo duhu, kafin ƙafafunku su yi tuntuɓe a kan tuddai masu duhu. Za ku sa zuciya ganin haske amma zai mai da shi duhu mai kauri ya kuma canja shi zuwa duhu baƙi ƙirin. ");
INSERT INTO hausa_vpl VALUES ("JR13_17","025_13_17","JER","13","17","17","Amma in ba ku saurara ba, zan yi kuka a ɓoye saboda girmankanku; idanuna za su yi kuka mai zafi, suna zub da hawaye ƙwarai, domin zan kwashe garken Ubangiji zuwa zaman bauta. ");
INSERT INTO hausa_vpl VALUES ("JR13_18","025_13_18","JER","13","18","18","Ka faɗa wa sarki da kuma mahaifiyar sarauniya cewa, “Ku sauko daga kursiyinku, gama rawaninku na ɗaukaka za su fāɗi daga kawunanku.” ");
INSERT INTO hausa_vpl VALUES ("JR13_19","025_13_19","JER","13","19","19","Za a kulle biranen da suke a Negeb, kuma babu wanda zai buɗe su. Za a kwashe dukan Yahuda zuwa zaman bauta, za a kwashe su tas. ");
INSERT INTO hausa_vpl VALUES ("JR13_20","025_13_20","JER","13","20","20","Ku tā da idanunku ku ga waɗanda suke zuwa daga arewa. Ina garken da aka ba ku tumakin da kuke taƙama a kai? ");
INSERT INTO hausa_vpl VALUES ("JR13_21","025_13_21","JER","13","21","21","Me za ku ce sa’ad da Ubangiji ya naɗa muku waɗanda ku kanku kuka koya musu a matsayi abokai na musamman? Ashe, azaba ba za tă auko muku kamar na mace mai naƙuda ba? ");
INSERT INTO hausa_vpl VALUES ("JR13_22","025_13_22","JER","13","22","22","In kuma kuka tambaye kanku “Me ya sa wannan ya faru da mu?” Wannan kuwa saboda yawan zunubanku ne ya sa fatarinku ya yage aka kuma wahalshe jikinku. ");
INSERT INTO hausa_vpl VALUES ("JR13_23","025_13_23","JER","13","23","23","Mutumin Habasha zai iya canja launin fatar jikinsa ko damisa ta canja dabbare dabbarenta? Ba za ku iya yin alheri ku da kuka saba da yin mugunta ba. ");
INSERT INTO hausa_vpl VALUES ("JR13_24","025_13_24","JER","13","24","24","“Zan watsar da ku kamar yayin da iskar hamada take hurawa. ");
INSERT INTO hausa_vpl VALUES ("JR13_25","025_13_25","JER","13","25","25","Rabonku ne wannan, sashen da na auka muku,” in ji Ubangiji “domin kun manta da ni kuka kuma dogara ga allolin ƙarya. ");
INSERT INTO hausa_vpl VALUES ("JR13_26","025_13_26","JER","13","26","26","Zan kware fatarinku sama ya rufe fuskarku don a iya ga tsiraicinku ");
INSERT INTO hausa_vpl VALUES ("JR13_27","025_13_27","JER","13","27","27","zinace zinacenku da haniniya kamar dawakai, karuwancinku na bankunya! Na ga ayyukanku na banƙyama a kan tuddai da kuma a filaye. Kaitonki, ya Urushalima! Har yaushe za ki ci gaba da rashin tsarki?” ");
INSERT INTO hausa_vpl VALUES ("JR14_1","025_14_1","JER","14","1","1","Ga maganar Ubangiji da ta zo wa Irmiya game da fări cewa, ");
INSERT INTO hausa_vpl VALUES ("JR14_2","025_14_2","JER","14","2","2","“Yahuda tana makoki biranenta suna fama; suna kuka saboda ƙasar, kuka kuma tana tasowa daga Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR14_3","025_14_3","JER","14","3","3","Manyan mutane suna aika bayinsu su ɗebo ruwa a maɓulɓulai amma babu ruwa. Suka dawo da tulunansu haka nan; da kunya da kuma ƙasƙanci, da kawunansu a rufe. ");
INSERT INTO hausa_vpl VALUES ("JR14_4","025_14_4","JER","14","4","4","Ƙasa ta tsattsage saboda babu ruwan sama a ƙasar; manoma sun sha kunya suka kuma rufe kawunansu. ");
INSERT INTO hausa_vpl VALUES ("JR14_5","025_14_5","JER","14","5","5","Har barewa a kurmi ma ta gudu ta bar ’ya’yan da ta haihu sababbi saboda babu ciyawa. ");
INSERT INTO hausa_vpl VALUES ("JR14_6","025_14_6","JER","14","6","6","Jakan jeji suna tsaye a kan tuddai suna haki kamar diloli; idanunsu sun kāsa gani saboda rashin makiyaya.” ");
INSERT INTO hausa_vpl VALUES ("JR14_7","025_14_7","JER","14","7","7","Ko da yake zunubanmu suna ba da shaida a kanmu, Ya Ubangiji, ka yi wani abu saboda sunanka. Gama jan bayanmu ya yi yawa; mun yi maka zunubi. ");
INSERT INTO hausa_vpl VALUES ("JR14_8","025_14_8","JER","14","8","8","Ya kai, Sa Zuciyar Isra’ila, Mai Cetonsa a lokutan wahala, me ya sa kake yi kamar baƙo a ƙasar, kamar matafiyi wanda yake shirya wuri don yă kwana gari ya waye ya wuce? ");
INSERT INTO hausa_vpl VALUES ("JR14_9","025_14_9","JER","14","9","9","Me ya sa kake yi kamar mutumin da aka far masa kwasam ba zato, kamar jarumi marar ƙarfin ceto? Kana a cikinmu, ya Ubangiji, da sunanka ake kiranmu; kada ka yashe mu! ");
INSERT INTO hausa_vpl VALUES ("JR14_10","025_14_10","JER","14","10","10","Ga abin da Ubangiji ya ce game da wannan mutane, “Suna son yawace-yawace ƙwarai; ba sa hana ƙafafunsu yawo. Saboda haka Ubangiji bai yarda da su ba; yanzu zai tuna da muguntarsu zai kuma hukunta su saboda zunubansu.” ");
INSERT INTO hausa_vpl VALUES ("JR14_11","025_14_11","JER","14","11","11","Sa’an nan Ubangiji ya ce mini, “Kada ka yi addu’a domin zaman lafiyar mutanen nan. ");
INSERT INTO hausa_vpl VALUES ("JR14_12","025_14_12","JER","14","12","12","Ko da yake suna azumi, ba zan saurari kukansu ba, ko da yake suna miƙa hadayun ƙonawa da hadayun gari, ba zan yarda da su ba. A maimako zan hallaka su da takobi, yunwa da annoba.” ");
INSERT INTO hausa_vpl VALUES ("JR14_13","025_14_13","JER","14","13","13","Amma na ce, “A, Ubangiji Mai Iko Duka, annabawa sun riƙa ce musu, ‘Ba za ku ga takobi ko ku yi fama da yunwa ba. A maimako, zan ba ku madawwamiyar salama.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR14_14","025_14_14","JER","14","14","14","Sai Ubangiji ya ce mini, “Annabawa suna ta annabcin ƙarya da sunana. Ban aike su ba, ban kuma naɗa su ba, ban yi musu magana ba. Suna muku annabci wahayin ƙarya, suna muku duba marar amfani, suna bautar gumaka suna kuma bayyana tunanin kansu ne. ");
INSERT INTO hausa_vpl VALUES ("JR14_15","025_14_15","JER","14","15","15","Saboda haka, ga abin da Ubangiji ya ce game da annabawan da suke annabci da sunana. Ban aike su ba, duk da haka suna cewa, ‘Babu takobi ko yunwar da zai taɓa wannan ƙasa.’ Waɗannan annabawa takobi da yunwa za su hallaka su. ");
INSERT INTO hausa_vpl VALUES ("JR14_16","025_14_16","JER","14","16","16","Mutanen da suke musu annabcin kuwa za a kore su zuwa titunan Urushalima saboda yunwa da kuma takobi. Babu wanda zai binne su, ko ya binne matansu, ko ’ya’yansu maza da mata. Zan aukar musu da masifar da ya dace da su. ");
INSERT INTO hausa_vpl VALUES ("JR14_17","025_14_17","JER","14","17","17","“Ka yi musu wannan magana, “ ‘Bari idanuna su yi ta zub da hawaye dare da rana kada su daina; saboda ’yata budurwa, mutanena, sun sha wahalar babban rauni, an yi musu bugu mai ragargazawa. ");
INSERT INTO hausa_vpl VALUES ("JR14_18","025_14_18","JER","14","18","18","In na shiga cikin ƙasar, na ga waɗanda takobi ya kashe; in na shiga cikin birni, na ga waɗanda suke fama da yunwa. Da Annabi da firist duk sun tafi ƙasar da ba su sani ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR14_19","025_14_19","JER","14","19","19","Ka ƙi Yahuda ɗungum ke nan? Kana ƙyamar Sihiyona ne? Me ya sa ka buge mu don kada mu warke? Mun sa zuciya ga salama babu abin alherin da ya zo, mun sa rai ga lokacin warkarwa amma sai ga razana. ");
INSERT INTO hausa_vpl VALUES ("JR14_20","025_14_20","JER","14","20","20","Ya Ubangiji, mun gane da muguntarmu da kuma laifin kakanninmu; tabbatacce mun yi maka zunubi. ");
INSERT INTO hausa_vpl VALUES ("JR14_21","025_14_21","JER","14","21","21","Saboda sunanka kada ka ƙi mu; kada ka ƙasƙantar da kursiyoyinka mai ɗaukaka. Ka tuna da alkawarinka da mu kada ka tā da shi. ");
INSERT INTO hausa_vpl VALUES ("JR14_22","025_14_22","JER","14","22","22","Akwai wani daga cikin gumaka marasa amfani na al’ummai da ya kawo ruwan sama? Sararin sama kansu sukan yi yayyafi? A’a, kai ne, ya Ubangiji Allahnmu. Saboda haka sa zuciyarmu tana a kanka, gama kai ne kake yi wannan duka. ");
INSERT INTO hausa_vpl VALUES ("JR15_1","025_15_1","JER","15","1","1","Sai Ubangiji ya ce mini, “Ko da Musa da Sama’ila za su tsaya a gabana, zuciyata ba za tă komo ga mutanen nan ba. Ka kore su daga gabana! Su tafi! ");
INSERT INTO hausa_vpl VALUES ("JR15_2","025_15_2","JER","15","2","2","In kuma suka tambaye ka, ‘Ina za mu tafi?’ Sai ka faɗa musu, ‘Ga abin da Ubangiji yana cewa, “ ‘Waɗanda aka ƙaddara ga mutuwa, ga mutuwa za su; waɗanda aka ƙaddara ga takobi, ga takobi za su; waɗanda aka ƙaddara ga yunwa, ga yunwa za su; waɗanda aka ƙaddara ga zaman bauta, ga zaman bauta za su.’ ");
INSERT INTO hausa_vpl VALUES ("JR15_3","025_15_3","JER","15","3","3","“Zan aika musu da iri masu hallakarwa guda huɗu,” in ji Ubangiji, “takobi zai kashe, karnuka za su kwashe, tsuntsaye da namun jeji kuma su cinye su kuma hallaka. ");
INSERT INTO hausa_vpl VALUES ("JR15_4","025_15_4","JER","15","4","4","Zan sa su zama abin ƙyama ga dukan mulkokin duniya saboda abin da Manasse ɗan Hezekiya sarkin Yahuda ya aikata a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR15_5","025_15_5","JER","15","5","5","“Wa zai ji tausayinki, ya Urushalima? Wa zai yi makoki dominki? Wa zai dakata ya tambayi lafiyarki? ");
INSERT INTO hausa_vpl VALUES ("JR15_6","025_15_6","JER","15","6","6","Kin ƙi ni,” in ji Ubangiji. “Ki ci gaba da ja da baya. Ta haka zan ɗibiya hannuwana a kanki in hallaka ki; ba zan ƙara nuna miki jinƙai ba. ");
INSERT INTO hausa_vpl VALUES ("JR15_7","025_15_7","JER","15","7","7","Zan sheƙe ki da abin sheƙewa a ƙofofin birnin ƙasar. Zan kawo baƙin ciki da hallaka a kan mutanena, gama ba su canja hanyoyinsu ba. ");
INSERT INTO hausa_vpl VALUES ("JR15_8","025_15_8","JER","15","8","8","Zan ƙara yawan gwaurayensu su fi yashin teku yawa. Da tsakar rana zan kawo mai hallakarwa a kan iyaye mata na samarinsu; farat ɗaya zan kawo musu wahala da razana. ");
INSERT INTO hausa_vpl VALUES ("JR15_9","025_15_9","JER","15","9","9","Mahaifiya ’ya’ya bakwai za tă suma ta ja numfashinta na ƙarshe. Ranarta zai fāɗi tun lokacin bai yi ba; za tă sha kunya a kuma wulaƙanta ta. Zan sa a kashe raguwa da takobi a gaban abokan gābansu,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR15_10","025_15_10","JER","15","10","10","Kaitona, mahaifiyata, da kika haife ni, mutumin da dukan ƙasa take faɗa take kuma gardama da shi! Ban ba da bashi ko in ci bashi ba, duk da haka kowa yana zagina. ");
INSERT INTO hausa_vpl VALUES ("JR15_11","025_15_11","JER","15","11","11","Ubangiji ya ce, “Tabbatacce zan cece ka don alheri; tabbatacce zan sa abokan gābanka su yi roƙo gare ka a lokacin masifa da kuma lokacin wahala. ");
INSERT INTO hausa_vpl VALUES ("JR15_12","025_15_12","JER","15","12","12","“Mutum zai iya karye ƙarfe ƙarfe daga arewa, ko tagulla? ");
INSERT INTO hausa_vpl VALUES ("JR15_13","025_15_13","JER","15","13","13","“Dukiyarku da arzikinku zan ba da su ganima, babu tara, saboda duka zunubanku ko’ina a ƙasar. ");
INSERT INTO hausa_vpl VALUES ("JR15_14","025_15_14","JER","15","14","14","Zan bautar da ku ga abokan gābanku a ƙasar da ba ku sani ba, gama fushina zai yi ƙuna kamar wuta da za tă yi ƙuna a kanku.” ");
INSERT INTO hausa_vpl VALUES ("JR15_15","025_15_15","JER","15","15","15","Ka gane, ya Ubangiji; ka tuna da ni ka kuma lura da ni. Ka yi mini ramuwa a kan masu tsananta mini. Cikin jimirinka, kada ka ɗauke ni; ka tuna yadda na sha zagi saboda kai. ");
INSERT INTO hausa_vpl VALUES ("JR15_16","025_15_16","JER","15","16","16","Sa’ad da maganganunka suka zo, na cinye su; suka zama abin farin ciki zuciyata kuma ta yi murna, gama ana kirana da sunanka, Ya Ubangiji Allah Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("JR15_17","025_15_17","JER","15","17","17","Ban taɓa zauna a cikin ’yan tawaye ba, ban taɓa yi murna da su ba; na zauna ni kaɗai domin hannunka yana a kaina ka kuma sa na cika da haushi. ");
INSERT INTO hausa_vpl VALUES ("JR15_18","025_15_18","JER","15","18","18","Me ya sa wahalata ba ta ƙarewa mikina kuma ba ya warkuwa? Za ka zama mini kamar rafi mai yaudara ne, kamar maɓulɓulan da ta kafe ne? ");
INSERT INTO hausa_vpl VALUES ("JR15_19","025_15_19","JER","15","19","19","Saboda haka ga abin da Ubangiji yana cewa, “In ka tuba, zan maido da kai don ka bauta mini; in ka ambaci maganganu masu kyau, ba marasa kyau ba, za ka zama kakakina. Bari wannan mutane su juyo gare ka, amma kada ka juye gare su. ");
INSERT INTO hausa_vpl VALUES ("JR15_20","025_15_20","JER","15","20","20","Zan mai da kai katanga ga wannan mutane, katanga mai ƙarfi na tagulla; za su yi yaƙi da kai amma ba za su yi nasara a kanka ba, gama ina tare da kai don in kuɓutar in kuma cece ka,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR15_21","025_15_21","JER","15","21","21","“Zan cece ka daga hannuwan mugaye in ɓamɓare ka daga hannun marasa tausayi.” ");
INSERT INTO hausa_vpl VALUES ("JR16_1","025_16_1","JER","16","1","1","Sai maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("JR16_2","025_16_2","JER","16","2","2","“Kada ka yi aure ka haifi ’ya’ya maza da mata a wannan wuri.” ");
INSERT INTO hausa_vpl VALUES ("JR16_3","025_16_3","JER","16","3","3","Gama ga abin da Ubangiji yana cewa game da ’ya’ya maza da matan da aka haifa a wannan ƙasa da kuma game da matan da suke iyayensu da suke mazan da iyayensu. ");
INSERT INTO hausa_vpl VALUES ("JR16_4","025_16_4","JER","16","4","4","“Za su mutu da muguwar cuta. Ba za a yi kuka dominsu ba, ba kuwa za a binne su ba, amma za a bar su a juji. Takobi da yunwa ne za su hallaka su, gawawwakinsu za su zama abincin tsuntsayen sararin sama da kuma namun jeji na duniya.” ");
INSERT INTO hausa_vpl VALUES ("JR16_5","025_16_5","JER","16","5","5","Gama ga abin da Ubangiji yana cewa, “Kada ka shiga gidan da akwai abincin makoki; kada ka tafi ka yi makoki ko ka nuna juyayi, domin na janye albarkata, ƙaunata da tausayina daga wannan mutane,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR16_6","025_16_6","JER","16","6","6","“Manya da ƙanana duka za su mutu a wannan ƙasa. Ba za a binne su ba, ba kuwa za a yi makokinsu ba, kuma ba wanda zai tsaga kansa ko ya aske kansa saboda su. ");
INSERT INTO hausa_vpl VALUES ("JR16_7","025_16_7","JER","16","7","7","Ba wanda zai ba da abinci don yă ta’azantar da waɗanda suke makoki saboda matattu, kai, ko saboda mahaifi ko mahaifiya ma ba kuwa wani da zai ba da abin sha don yă ta’azantar da su. ");
INSERT INTO hausa_vpl VALUES ("JR16_8","025_16_8","JER","16","8","8","“Kada kuma ka shiga gidan da ake biki ka zauna don ci da sha. ");
INSERT INTO hausa_vpl VALUES ("JR16_9","025_16_9","JER","16","9","9","Gama ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa a idanunka da kuma a kwanakinka zan kawo ƙarshen muryar farin ciki da murna da kuma muryoyin amarya da ango a wannan wuri. ");
INSERT INTO hausa_vpl VALUES ("JR16_10","025_16_10","JER","16","10","10","“Sa’ad da ka faɗa wa waɗannan mutane wannan duka suka kuma tambaye ka, ‘Me ya sa Ubangiji ya ƙaddara irin wannan babban masifa a kanmu? Wace mugunta muka yi? Wane zunubi muka aikata wa Ubangiji Allahnmu?’ ");
INSERT INTO hausa_vpl VALUES ("JR16_11","025_16_11","JER","16","11","11","Sai ka ce musu, ‘Wannan ya zama haka domin kakanninku sun rabu da ni,’ in ji Ubangiji, ‘suka bi waɗansu alloli suka kuma bauta musu. Suka rabu da ni, ba su kuwa kiyaye dokata ba. ");
INSERT INTO hausa_vpl VALUES ("JR16_12","025_16_12","JER","16","12","12","Amma kun yi laifi fiye da kakanninku. Duba yadda kowannenku yana bin taurin muguwar zuciyarsa a maimakon yin mini biyayya. ");
INSERT INTO hausa_vpl VALUES ("JR16_13","025_16_13","JER","16","13","13","Saboda haka zan fitar da ku daga wannan ƙasa zuwa wata ƙasar da ku da kakanninku ba ku taɓa sani ba, a can kuwa za ku bauta wa waɗansu alloli dare da rana, gama ba zan nuna muku tagomashi ba.’ ");
INSERT INTO hausa_vpl VALUES ("JR16_14","025_16_14","JER","16","14","14","“Amma fa, kwanaki suna zuwa,” in ji Ubangiji, “da mutane ba za su ƙara cewa, ‘Muddin Ubangiji yana raye, wanda ya fitar da Isra’ilawa daga Masar,’ ");
INSERT INTO hausa_vpl VALUES ("JR16_15","025_16_15","JER","16","15","15","amma za su ce, ‘Muddin Ubangiji yana raye, wanda ya fitar da Isra’ilawa daga ƙasar arewa da kuma daga dukan ƙasashe da ya kora su.’ Gama zan komo da su zuwa ƙasar da na ba wa kakanninsu. ");
INSERT INTO hausa_vpl VALUES ("JR16_16","025_16_16","JER","16","16","16","“Amma yanzu zan aiko a kira masunta masu yawa su zo,” in ji Ubangiji, “za su kuma kama su. Bayan wannan zan aiko a kira mafarauta su zo, su farauce su daga kowane dutse da tudu da kuma daga kogwannin duwatsu. ");
INSERT INTO hausa_vpl VALUES ("JR16_17","025_16_17","JER","16","17","17","Idanuna suna a kan dukan hanyoyinsu; ba a ɓoye suke daga gare ni, kuma zunubansu ba a ɓoye suke a idanuna ba. ");
INSERT INTO hausa_vpl VALUES ("JR16_18","025_16_18","JER","16","18","18","Zan riɓaɓɓanya sakayyar da zan yi musu saboda muguntarsu da zunubinsu, domin sun ƙazantar da ƙasata da ƙazantattun gumakansu marasa rai, suka kuma cika abin gādona da gumakansu na banƙyama.” ");
INSERT INTO hausa_vpl VALUES ("JR16_19","025_16_19","JER","16","19","19","Ya Ubangiji, ƙarfina da katangana, mafakata a lokacin damuwa, gare ka al’ummai za su zo daga iyakokin duniya su ce, “Kakanninmu ba su mallaki kome ba sai allolin ƙarya, gumakan banza da ba su yi musu amfani ba. ");
INSERT INTO hausa_vpl VALUES ("JR16_20","025_16_20","JER","16","20","20","Mutane kan yi allolinsu ne? I, amma waɗannan ba alloli ba ne!” ");
INSERT INTO hausa_vpl VALUES ("JR16_21","025_16_21","JER","16","21","21","“Saboda haka zan koya musu a wannan lokaci zan koya musu ikona da ƙarfina. Sa’an nan za su sani cewa sunana Ubangiji ne. ");
INSERT INTO hausa_vpl VALUES ("JR17_1","025_17_1","JER","17","1","1","“An rubuta zunubin Yahuda da alƙalamin ƙarfe, an rubuta da tsinin dutse, a kan allunan zukatansu da kuma a kan ƙahonin bagadansu. ");
INSERT INTO hausa_vpl VALUES ("JR17_2","025_17_2","JER","17","2","2","Har ’ya’yansu ma sun tuna bagadansu da ginshiƙan Asheransu kusa da itatuwa masu duhuwa da kuma a kan tuddai masu tsayi. ");
INSERT INTO hausa_vpl VALUES ("JR17_3","025_17_3","JER","17","3","3","Dutsena a ƙasar da dukiyarku na ƙasar da dukan arzikinku za a ba da su ganima, tare da masujadanku na kan tuddai, saboda zunubi ko’ina a ƙasarku. ");
INSERT INTO hausa_vpl VALUES ("JR17_4","025_17_4","JER","17","4","4","Saboda laifinku za ku rasa gādon da na ba ku. Zan bautar da ku ga abokan gābanku a ƙasar da ba ku sani ba, domin kun husata ni, zai kuwa ci har abada.” ");
INSERT INTO hausa_vpl VALUES ("JR17_5","025_17_5","JER","17","5","5","Ga abin da Ubangiji yana cewa, “La’ananne ne mutumin da yake dogara ga mutum, wanda ya dogara ga jiki don ƙarfi wanda kuma zuciyarsa ta juya wa Ubangiji baya. ");
INSERT INTO hausa_vpl VALUES ("JR17_6","025_17_6","JER","17","6","6","Zai zama kamar ɗan kurmi a ƙasar da take kango; ba za su ga arziki sa’ad da ya zo ba. Za su zauna a busassun wuraren hamada, a cikin ƙasar gishiri inda ba kowa. ");
INSERT INTO hausa_vpl VALUES ("JR17_7","025_17_7","JER","17","7","7","“Amma mai albarka ne mutumin da yake dogara ga Ubangiji, wanda ƙarfin halinsa yana daga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR17_8","025_17_8","JER","17","8","8","Za su zama kamar itacen da aka dasa kusa da ruwa wanda ya miƙa saiwoyinsa zuwa cikin rafi. Ba ya jin tsoro sa’ad da zafi ya zo; ganyayensa kullum kore suke. Ba shi da damuwa a shekarar fări ba ya taɓa fasa ba da ’ya’ya.” ");
INSERT INTO hausa_vpl VALUES ("JR17_9","025_17_9","JER","17","9","9","Zuciya ta fi kome ruɗu ta fi ƙarfin warkewa. Wa zai iya gane ta? ");
INSERT INTO hausa_vpl VALUES ("JR17_10","025_17_10","JER","17","10","10","“Ni Ubangiji nakan bincike zuciya in gwada tunani, don in sāka wa kowane mutum bisa ga halinsa, bisa ga ayyukansa.” ");
INSERT INTO hausa_vpl VALUES ("JR17_11","025_17_11","JER","17","11","11","Kamar makwarwar da ta kwanta a kan ƙwan da ba ita ta zuba ba haka yake da mutumin da ya sami arziki a hanyar da ba daidai ba. A tsakiyar rayuwarsa za su rabu da shi, a ƙarshe kuma zai zama wawa. ");
INSERT INTO hausa_vpl VALUES ("JR17_12","025_17_12","JER","17","12","12","Kursiyi mai daraja, da aka ɗaukaka tun daga farko, shi ne wuri mai tsarkinmu. ");
INSERT INTO hausa_vpl VALUES ("JR17_13","025_17_13","JER","17","13","13","Ya Ubangiji, sa zuciyar Isra’ila, duk waɗanda suka rabu da kai za su sha kunya. Waɗanda suka juya maka baya za a rubuta su a ƙura domin sun yashe Ubangiji, maɓulɓular ruwan rai. ");
INSERT INTO hausa_vpl VALUES ("JR17_14","025_17_14","JER","17","14","14","Ka warkar da ni, ya Ubangiji, zan kuwa warke; ka cece ni zan kuwa cetu, gama kai ne nake yabo. ");
INSERT INTO hausa_vpl VALUES ("JR17_15","025_17_15","JER","17","15","15","Sun riƙa ce mini, “Ina maganar Ubangiji take? Bari tă cika yanzu!” ");
INSERT INTO hausa_vpl VALUES ("JR17_16","025_17_16","JER","17","16","16","Ban gudu zaman mai yin maka kiwo ba; ka sani ban marmarin ranan nan ta masifa ba. Abin da ya fito daga leɓunana kuwa, a bayyane suke gare ka. ");
INSERT INTO hausa_vpl VALUES ("JR17_17","025_17_17","JER","17","17","17","Kada ka zama mini abin razana; kai ne mafakata a ranar masifa. ");
INSERT INTO hausa_vpl VALUES ("JR17_18","025_17_18","JER","17","18","18","Bari masu tsananta mini su sha kunya, amma ka kiyaye ni daga shan kunya; bari su tsorata, amma ka kiyaye ni da razana. Ka kawo musu ranar masifa; ka hallaka su da hallaka riɓi biyu. ");
INSERT INTO hausa_vpl VALUES ("JR17_19","025_17_19","JER","17","19","19","Ga abin da Ubangiji ya ce mini, “Ka je ka tsaya a ƙofar mutane, inda sarakunan Yahuda sukan shiga su fita; ka tsaya kuma a dukan sauran ƙofofin Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR17_20","025_17_20","JER","17","20","20","Ka ce musu, ‘Ku ji maganar Ubangiji, ku sarakunan Yahuda, da dukan mutanen Yahuda da dukan mazaunan Urushalima waɗanda suke bi ta waɗannan ƙofofi. ");
INSERT INTO hausa_vpl VALUES ("JR17_21","025_17_21","JER","17","21","21","Ga abin da Ubangiji yana cewa, ku yi hankali kada ku ɗauki kaya a ranar Asabbaci ko ku shigar da shi ta ƙofofin Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR17_22","025_17_22","JER","17","22","22","Kada ku fitar da kayan gidajenku ko ku yi wani aiki a ranar Asabbaci mai tsarki, yadda na umarci kakanni-kakanninku. ");
INSERT INTO hausa_vpl VALUES ("JR17_23","025_17_23","JER","17","23","23","Duk da haka ba su saurara ba, ba su kuwa mai da hankali ba; suka taurare ba su kuwa saurara ko su karɓi horo ba. ");
INSERT INTO hausa_vpl VALUES ("JR17_24","025_17_24","JER","17","24","24","Amma in kuka yi hankali kuka yi mini biyayya, in ji Ubangiji, ba ku kuwa shigar da kaya ta ƙofofi a ranar Asabbaci ba, amma kuka kiyaye ranar Asabbaci da tsarki ba tare da yin wani aiki a cikinta ba, ");
INSERT INTO hausa_vpl VALUES ("JR17_25","025_17_25","JER","17","25","25","sa’an nan sarakuna da suke zama a kursiyin Dawuda za su shiga ta ƙofofin wannan birni tare da fadawansu. Su da fadawansu za su shiga a kan kekunan yaƙi da kuma a kan dawakai, mutanen Yahuda suna musu rakiya tare da waɗanda suke zaune a Urushalima, wannan birni kuwa za tă kasance da mazauna har abada. ");
INSERT INTO hausa_vpl VALUES ("JR17_26","025_17_26","JER","17","26","26","Mutane za su zo daga garuruwan Yahuda da ƙauyukan kewaye da Urushalima, daga iyakar Benyamin da gindin tuddan yamma, daga ƙasar tudu da kuma Negeb, suna kawo hadayun ƙonawa da hadayun gari, sadakokin turare da na godiya zuwa gidan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR17_27","025_17_27","JER","17","27","27","Amma in ba ku yi mini biyayya ba, ba ku kiyaye ranar Asabbaci da tsarki ba, kuka ɗauki wani kaya yayinda kuke shiga ƙofofin Urushalima a ranar Asabbaci, to, sai in cinna wa ƙofofin Urushalima wutar da ba a iya kashewa, tă cinye kagaranta.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR18_1","025_18_1","JER","18","1","1","Ga maganar da ta zo wa Irmiya daga wurin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR18_2","025_18_2","JER","18","2","2","“Ka gangara zuwa gidan mai ginin tukwane, a can zan ba ka saƙona.” ");
INSERT INTO hausa_vpl VALUES ("JR18_3","025_18_3","JER","18","3","3","Sai na gangara zuwa gidan mai ginin tukwane, na gan shi yana aiki a na’urar ginin tukwanen. ");
INSERT INTO hausa_vpl VALUES ("JR18_4","025_18_4","JER","18","4","4","Amma tukunyar da yake ginawa ta lalace a hannuwansa, sai mai ginin tukwanen ya sāke gina wata tukunya dabam, yana gyara ta yadda ya ga dama. ");
INSERT INTO hausa_vpl VALUES ("JR18_5","025_18_5","JER","18","5","5","Sai maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("JR18_6","025_18_6","JER","18","6","6","“Ya gidan Isra’ila, ashe, ba zan yi da ku yadda mai ginin tukwanen nan yake yi ba?” In ji Ubangiji. “Kamar yumɓu a hannun mai ginin tukwane, haka kuke a hannuna, ya gidan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("JR18_7","025_18_7","JER","18","7","7","A duk lokacin da na yi shela cewa za a tumɓuke, a kakkarya a kuma hallaka wata al’umma ko mulki, ");
INSERT INTO hausa_vpl VALUES ("JR18_8","025_18_8","JER","18","8","8","in wannan al’ummar da na yi wa gargaɗi ta tuba daga muguntarta, sai in janye in kuma fasa kawo mata masifar da na yi niyya aukar mata. ");
INSERT INTO hausa_vpl VALUES ("JR18_9","025_18_9","JER","18","9","9","In kuma wani lokaci na yi shela cewa za a gina wata al’umma ko mulki a kuma kafa ta, ");
INSERT INTO hausa_vpl VALUES ("JR18_10","025_18_10","JER","18","10","10","in ta yi mugunta a gabana ba tă kuwa yi mini biyayya ba, sai in janye alherin da na yi niyya in yi mata. ");
INSERT INTO hausa_vpl VALUES ("JR18_11","025_18_11","JER","18","11","11","“Yanzu fa, sai ka faɗa wa mutanen Yahuda da waɗanda suke zaune a Urushalima, ‘Ga abin da Ubangiji yana cewa ga shi! Ina shirya muku masifa ina ƙirƙiro dabara a kanku. Saboda haka ku juya daga mugayen hanyoyinku, kowannenku, ku canja hanyoyinku da kuma ayyukanku.’ ");
INSERT INTO hausa_vpl VALUES ("JR18_12","025_18_12","JER","18","12","12","Amma za su amsa su ce, ‘Ba amfani. Za mu ci gaba da shirye-shiryenmu; kowannenmu zai bi taurin muguwar zuciyarsa.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR18_13","025_18_13","JER","18","13","13","Saboda haka ga abin da Ubangiji yana cewa, “Ku tattambaya a cikin al’ummai. Wa ya taɓa jin irin wannan abu? Budurwa Isra’ila ta yi mugun abu mafi banƙyama. ");
INSERT INTO hausa_vpl VALUES ("JR18_14","025_18_14","JER","18","14","14","Dusar ƙanƙarar Lebanon ta taɓa rabuwa da kan duwatsun Lebanon? Ruwan mai sanyinsa daga rafuffukansa masu nesa sun taɓa daina gudu? ");
INSERT INTO hausa_vpl VALUES ("JR18_15","025_18_15","JER","18","15","15","Duk da haka mutanena sun manta da ni; sun ƙone turare wa gumaka marasa amfani, waɗanda suka sa su tuntuɓe a al’amuransu a hanyoyin dā. Sun sa suka yi tafiya a ɓarayin hanyoyi a hanyoyin da ba a gina ba. ");
INSERT INTO hausa_vpl VALUES ("JR18_16","025_18_16","JER","18","16","16","Ƙasarsu za tă zama kufai, abin reni har abada; dukan waɗanda suka wuce za su yi mamaki su kaɗa kai. ");
INSERT INTO hausa_vpl VALUES ("JR18_17","025_18_17","JER","18","17","17","Kamar iska daga gabas zan warwatsa su a gaban abokan gābansu; zan juya musu bayana, ba zan nuna musu fuskata ba a ranar masifarsu.” ");
INSERT INTO hausa_vpl VALUES ("JR18_18","025_18_18","JER","18","18","18","Suka ce, “Zo mu shirya wa Irmiya maƙarƙashiya; gama koyarwar doka da firist ya yi ba za tă ɓace ba, haka ma shawara daga mai hikima da kuma magana daga annabawa. Saboda haka ku zo, mu fāɗa masa da harsunanmu kada mu saurari wani abin da zai faɗa.” ");
INSERT INTO hausa_vpl VALUES ("JR18_19","025_18_19","JER","18","19","19","Ka saurare ni, ya Ubangiji ka ji abin da masu zargina suke cewa! ");
INSERT INTO hausa_vpl VALUES ("JR18_20","025_18_20","JER","18","20","20","Ya kamata a sāka wa alheri da mugunta? Duk da haka sun haƙa mini rami. Ka tuna cewa na tsaya a gabanka na kuma yi magana a madadinsu don ka janye fushinka daga gare su. ");
INSERT INTO hausa_vpl VALUES ("JR18_21","025_18_21","JER","18","21","21","Saboda haka ka kawo wa ’ya’yansu yunwa; ka miƙa su ga ikon takobi. Bari matansu su zama marasa ’ya’ya da gwauraye; bari a kashe mazansu, a kuma kashe samarinsu da takobi a yaƙi. ");
INSERT INTO hausa_vpl VALUES ("JR18_22","025_18_22","JER","18","22","22","Bari a ji kuka daga gidajensu sa’ad da ka kawo masu hari a kansu farat ɗaya, gama sun haƙa rami don su kama ni suka kuma kafa tarko wa ƙafafuna. ");
INSERT INTO hausa_vpl VALUES ("JR18_23","025_18_23","JER","18","23","23","Amma Ya Ubangiji, ka san duk maƙarƙashiyarsu, na neman su kashe ni. Kada ka gafarta musu laifofinsu ko ka shafe zunubansu daga gabanka. Bari a tumɓuke su a gabanka; ka yi da su sa’ad da kake fushi. ");
INSERT INTO hausa_vpl VALUES ("JR19_1","025_19_1","JER","19","1","1","Ga abin da Ubangiji yana cewa, “Tafi ka sayo tulu a wurin mai ginin tukwane. Ka ɗauki waɗansu dattawan jama’a da kuma na firistoci ");
INSERT INTO hausa_vpl VALUES ("JR19_2","025_19_2","JER","19","2","2","ku fita zuwa Kwarin Ben Hinnom, kusa da mashigin Ƙofar Kasko. A can ka furta maganganun da na faɗa maka, ");
INSERT INTO hausa_vpl VALUES ("JR19_3","025_19_3","JER","19","3","3","ka ce, ‘Ku ji maganar Ubangiji, ya sarakunan Yahuda da kuma mutanen Urushalima. Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa ku saurara! Zan kawo masifa a wannan wuri, wanda duk ya ji, kunnuwansa za su kaɗa. ");
INSERT INTO hausa_vpl VALUES ("JR19_4","025_19_4","JER","19","4","4","Gama sun yashe ni suka kuma mai da wannan wuri ya zama na baƙin alloli; sun ƙone hadayu a cikinsa wa allolin da ko su ko kakanninsu ko sarakunan Yahuda ba su taɓa sani ba, suka kuma cika wannan wuri da jini marasa laifi. ");
INSERT INTO hausa_vpl VALUES ("JR19_5","025_19_5","JER","19","5","5","Suka gina masujadai na kan tudu na Ba’al don su ƙona ’ya’yansu maza a cikin wuta a matsayin hadaya ga Ba’al abin da ban umarta ba, ban ambata ba, bai kuma zo mini ba. ");
INSERT INTO hausa_vpl VALUES ("JR19_6","025_19_6","JER","19","6","6","Saboda haka ku lura, kwanaki suna zuwa, in ji Ubangiji, sa’ad da mutane ba za su ƙara ce da wannan wuri Tofet ko Kwarin Ben Hinnom ba, amma za su ce da shi Kwarin Kisa. ");
INSERT INTO hausa_vpl VALUES ("JR19_7","025_19_7","JER","19","7","7","“ ‘A wannan wuri zan lalace dabarun Yahuda da na Urushalima. Zan sa a kashe su da takobi a gaban abokan gābansu, a hannuwan waɗanda suke neman ransu, zan kuma ba da gawawwakinsu su zama abinci ga tsuntsayen sararin sama da kuma namun jeji. ");
INSERT INTO hausa_vpl VALUES ("JR19_8","025_19_8","JER","19","8","8","Zan ragargazar da wannan birni in mai da shi abin reni, duk wanda ya wuce zai yi mamaki ya kuma yi tsaki saboda dukan masifunsa. ");
INSERT INTO hausa_vpl VALUES ("JR19_9","025_19_9","JER","19","9","9","Zan sa su ci naman ’ya’yansu maza da mata, za su kuma ci naman juna a lokacin damuwar ƙawanya da abokan gāban da suke neman ransu za su yi musu.’ ");
INSERT INTO hausa_vpl VALUES ("JR19_10","025_19_10","JER","19","10","10","“Sa’an nan ka fasa tulun yayinda waɗanda suka tafi tare da kai suna duba, ");
INSERT INTO hausa_vpl VALUES ("JR19_11","025_19_11","JER","19","11","11","ka kuma ce musu, ‘Ga abin da Ubangiji Maɗaukaki yana cewa zan farfasa wannan al’umma da wannan birni kamar yadda aka farfasa wannan tulu mai ginin tukwane ba kuwa zai gyaru ba. Za a binne matattu a Tofet har sai ba sauran wuri. ");
INSERT INTO hausa_vpl VALUES ("JR19_12","025_19_12","JER","19","12","12","Ga abin da zan yi wa wannan wuri da waɗanda suke zaune a nan, in ji Ubangiji. Zan mai da wannan birni kamar Tofet. ");
INSERT INTO hausa_vpl VALUES ("JR19_13","025_19_13","JER","19","13","13","Gidaje a Urushalima da waɗannan na sarakunan Yahuda za su ƙazantu kamar wannan wuri, Tofet, dukan gidajen da suke ƙone turare a kan rufi wa duk rundunan taurari suna kuma zuba hadayun sha ga sauran alloli.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR19_14","025_19_14","JER","19","14","14","Sa’an nan Irmiya ya komo daga Tofet, inda Ubangiji ya aike shi don yă yi annabci, ya tsaya a filin haikalin Ubangiji ya ce wa mutane duka, ");
INSERT INTO hausa_vpl VALUES ("JR19_15","025_19_15","JER","19","15","15","“Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa, ‘Ku saurara! Zan kawo wa wannan birni da ƙauyukan da suke kewayensa kowace masifar da na furta a kansu, domin sun yi taurinkai, ba su kuwa saurari maganata ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR20_1","025_20_1","JER","20","1","1","Da firist nan Fashhur ɗan Immer, babban ma’aikaci a cikin haikalin Ubangiji, ya ji Irmiya yana annabcin waɗannan abubuwa, ");
INSERT INTO hausa_vpl VALUES ("JR20_2","025_20_2","JER","20","2","2","sai ya sa aka yi wa Irmiya dūka aka kuma sa shi a turu a Ƙofar Bisa na Benyamin a haikalin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR20_3","025_20_3","JER","20","3","3","Kashegari, sa’ad da Fashhur ya fitar da shi daga turu, sai Irmiya ya ce masa, “Ubangiji ba zai kira ka Fashhur ba, amma ya ba ka suna Magor-Missabib. ");
INSERT INTO hausa_vpl VALUES ("JR20_4","025_20_4","JER","20","4","4","Gama ga abin da Ubangiji yana cewa, ‘Zan maishe ka abin razana ga kanka da kuma ga dukan abokanka; da idanunka za ka gan takobin abokan gāba yana kashe su. Zan miƙa Yahuda duka ga sarkin Babilon, wanda zai kwashe su zuwa Babilon ya kuma kashe su da takobi. ");
INSERT INTO hausa_vpl VALUES ("JR20_5","025_20_5","JER","20","5","5","Zan ba wa abokan gābansu dukan dukiyar wannan birni dukan amfaninsa, dukan abubuwa masu daraja na sarakunan Yahuda. Za su kwashe su ganima su kai su Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR20_6","025_20_6","JER","20","6","6","Kai kuma Fashhur, da dukan waɗanda suke a gidanka za ku tafi zaman bauta a Babilon. A can za ku mutu a kuma binne ku, da kai da dukan abokanka waɗanda ka yi musu annabce-annabcen ƙarya.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR20_7","025_20_7","JER","20","7","7","Ya Ubangiji, ka ruɗe ni, na kuwa ruɗu; ka fi ni ƙarfi, ka kuwa yi nasara. Na zama abin dariya dukan yini; kowa yana yi mini ba’a. ");
INSERT INTO hausa_vpl VALUES ("JR20_8","025_20_8","JER","20","8","8","Duk sa’ad da na yi magana, nakan tā da murya ina furta hargitsi da hallaka. Haka maganar Ubangiji ta kawo mini zagi da reni dukan yini. ");
INSERT INTO hausa_vpl VALUES ("JR20_9","025_20_9","JER","20","9","9","Amma in na ce, “Ba zan ambace shi ba ba zan ƙara yin magana da sunansa ba,” sai in ji maganarsa a cikina kamar wuta, wutar da aka kulle a ƙasusuwana. Na gaji da danne ta a cikina; tabbatacce ba zan iya ba. ");
INSERT INTO hausa_vpl VALUES ("JR20_10","025_20_10","JER","20","10","10","Na ji mutane da yawa suna raɗa cewa, “Razana ta kowace fuska! Mu kai kararsa! Bari mu kai kararsa!” Dukan abokaina suna jira in yi tuntuɓe, suna cewa, “Mai yiwuwa a ruɗe shi; sai mu yi nasara a kansa mu ɗau fansa a kansa.” ");
INSERT INTO hausa_vpl VALUES ("JR20_11","025_20_11","JER","20","11","11","Amma Ubangiji yana tare da ni kamar babban jarumi; saboda haka masu tsananta mini za su yi tuntuɓe ba kuwa za su yi nasara ba. Za su fāɗi su kuma sha mummunar kunya; ba za a taɓa manta da rashin bangirmansu ba. ");
INSERT INTO hausa_vpl VALUES ("JR20_12","025_20_12","JER","20","12","12","Ya Ubangiji Maɗaukaki, kai da kake gwada adali kana bincika zuciya duk da tunani, bari in ga sakayyarka a kansu, gama a gare ka na miƙa damuwata. ");
INSERT INTO hausa_vpl VALUES ("JR20_13","025_20_13","JER","20","13","13","Ku rera ga Ubangiji! Ku yabi Ubangiji! Ya kuɓutar da ran mabukaci daga hannuwan mugaye. ");
INSERT INTO hausa_vpl VALUES ("JR20_14","025_20_14","JER","20","14","14","La’ananniya ce ranar da aka haife ni! Kada ranar da mahaifiyata ta haife ni ta zama mai albarka! ");
INSERT INTO hausa_vpl VALUES ("JR20_15","025_20_15","JER","20","15","15","La’ananne ne mutumin da ya kawo wa mahaifina labari, wanda ya sa shi ya yi murna cewa, “An haifa maka yaro, ɗa namiji!” ");
INSERT INTO hausa_vpl VALUES ("JR20_16","025_20_16","JER","20","16","16","Bari mutumin ya zama kamar garuruwan da Ubangiji ya tumɓuke ba tausayi. Bari yă ji kuka da safe kururuwan yaƙi kuma da tsakar rana. ");
INSERT INTO hausa_vpl VALUES ("JR20_17","025_20_17","JER","20","17","17","Gama bai kashe ni a cikin ciki ba, da ma ya sa cikin mahaifiyata ya zama kabarina, cikinta ya fadada har abada. ");
INSERT INTO hausa_vpl VALUES ("JR20_18","025_20_18","JER","20","18","18","Me ya sa na ma fito daga cikin ciki in ga wahala da baƙin ciki in kuma ƙare kwanakina da kunya? ");
INSERT INTO hausa_vpl VALUES ("JR21_1","025_21_1","JER","21","1","1","Magana ta zo wa Irmiya daga Ubangiji sa’ad da Sarki Zedekiya ya aiki Fashhur ɗan Malkiya da firist Zefaniya ɗan Ma’asehiya gare shi. Suka ce masa, ");
INSERT INTO hausa_vpl VALUES ("JR21_2","025_21_2","JER","21","2","2","“Yanzu ka roƙi mana Ubangiji saboda Nebukadnezzar sarkin Babilon yana kawo mana yaƙi. Wataƙila Ubangiji zai yi mana waɗansu abubuwa banmamaki kamar a lokacin baya don yă janye daga gare mu.” ");
INSERT INTO hausa_vpl VALUES ("JR21_3","025_21_3","JER","21","3","3","Amma Irmiya ya amsa musu ya ce, “Ku faɗa wa Zedekiya cewa, ");
INSERT INTO hausa_vpl VALUES ("JR21_4","025_21_4","JER","21","4","4","‘Ga abin da Ubangiji, Allah na Isra’ila, yake cewa ina shirin juya kayan yaƙin da suke a hannuwanka a kanka, waɗanda kake amfani don ka yaƙi sarki Babilon da kuma Babiloniyawa waɗanda suka kewaye katangar birnin, zan kuwa tsiba kayan yaƙinka a tsakiyar birnin nan. ");
INSERT INTO hausa_vpl VALUES ("JR21_5","025_21_5","JER","21","5","5","Ni da kaina zan yi yaƙi da kai da miƙaƙƙen hannu mai ƙarfi cikin fushi da hasala mai girma. ");
INSERT INTO hausa_vpl VALUES ("JR21_6","025_21_6","JER","21","6","6","Zan kashe waɗanda suke zaune a wannan birni, mutane da dabbobi za su kuwa mutu da muguwar annoba. ");
INSERT INTO hausa_vpl VALUES ("JR21_7","025_21_7","JER","21","7","7","Bayan wannan, in ji Ubangiji, zan ba da Zedekiya sarkin Yahuda, fadawansa da kuma mutanen wannan birni waɗanda suka tsira daga annoba, takobi da kuma yunwa, ga Nebukadnezzar sarkin Babilon da kuma ga abokan gābansu waɗanda suke neman ransu. Zai kashe su da takobi; ba zai ji tausayinsu ko ya yi musu jinƙai ko ya yi juyayinsu ba.’ ");
INSERT INTO hausa_vpl VALUES ("JR21_8","025_21_8","JER","21","8","8","“Bugu da ƙari, ka faɗa wa mutanen cewa, ‘Ga abin da Ubangiji yana cewa, ga shi na sa a gabanku hanyar rai da hanyar mutuwa. ");
INSERT INTO hausa_vpl VALUES ("JR21_9","025_21_9","JER","21","9","9","Duk wanda ya zauna a wannan birni zai mutu ta takobi, yunwa ko annoba. Amma duk wanda ya fita ya miƙa kansa ga Babiloniyawa waɗanda suka kewaye ku zai rayu; zai kuɓutar da ransa. ");
INSERT INTO hausa_vpl VALUES ("JR21_10","025_21_10","JER","21","10","10","Na ƙudura in yi wa wannan birni lahani ba alheri ba, in ji Ubangiji. Za a ba da shi a hannuwan sarki Babilon, zai kuwa hallaka shi da wuta.’ ");
INSERT INTO hausa_vpl VALUES ("JR21_11","025_21_11","JER","21","11","11","“Ban haka ma, ka faɗa wa gidan sarauta na Yahuda cewa, ‘Ku saurari maganar Ubangiji; ");
INSERT INTO hausa_vpl VALUES ("JR21_12","025_21_12","JER","21","12","12","Ya gidan Dawuda ga abin da Ubangiji yana cewa, “ ‘Ku yi gaskiya kowace safiya; ku kuɓuta daga hannun mai danniya wannan da aka yi wa fashi in ba haka ba hasalata za tă sauka ta kuma ci kamar wuta saboda muguntar da kuka aikata za tă ci babu wanda zai kashe ta. ");
INSERT INTO hausa_vpl VALUES ("JR21_13","025_21_13","JER","21","13","13","Ina gāba da ku, mazaunan Urushalima, ku da kuke zama a bisa wannan kwari kan dutsen da yake a fili, in ji Ubangiji ku da kuke cewa, “Wa zai iya yaƙe mu? Wa zai iya shiga mafakarmu?” ");
INSERT INTO hausa_vpl VALUES ("JR21_14","025_21_14","JER","21","14","14","Zan hukunta ku gwargwadon ayyukanku, in ji Ubangiji. Zan sa wuta a kurminku da za tă cinye kome da yake kewaye da ku.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR22_1","025_22_1","JER","22","1","1","Ga abin da Ubangiji yana cewa, “Ka gangara zuwa fadan sarkin Yahuda ka yi shelar wannan saƙo a can ka ce, ");
INSERT INTO hausa_vpl VALUES ("JR22_2","025_22_2","JER","22","2","2","‘Ka ji maganar Ubangiji, ya sarkin Yahuda, kai da kake zaune kan gadon sarautar Dawuda, kai, da fadawanka da mutanenka waɗanda suke shiga ta waɗannan ƙofofi. ");
INSERT INTO hausa_vpl VALUES ("JR22_3","025_22_3","JER","22","3","3","Ga abin da Ubangiji yana cewa, ka yi abin da yake gaskiya da kuma daidai. Ka kuɓutar da wannan da aka yi masa ƙwace daga hannun mai zaluntarsa. Kada ka yi abin da ba daidai ba ko ka cuci baƙo, maraya ko gwauruwa, kuma kada ka zub da jini marar laifi a wannan wuri. ");
INSERT INTO hausa_vpl VALUES ("JR22_4","025_22_4","JER","22","4","4","Gama in ka lura da bin waɗannan umarnai, to, sarakunan da suke zaune a gadon sarautar Dawuda za su shiga ta ƙofofin wannan fada, suna hawan kekunan yaƙi da dawakai, fadawansu da mutanensu suna musu rakiya. ");
INSERT INTO hausa_vpl VALUES ("JR22_5","025_22_5","JER","22","5","5","Amma in ba ku kiyaye waɗannan umarnai ba, in ji Ubangiji, na rantse da kaina cewa wannan fada za tă zama kufai.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR22_6","025_22_6","JER","22","6","6","Gama ga abin da Ubangiji yana cewa game da wannan fadar sarkin Yahuda, “Ko da yake kina kamar Gileyad a gare ni, kamar ƙwanƙolin Lebanon, tabbatacce zan maishe ki hamada, kamar garuruwan da ba mazauna. ");
INSERT INTO hausa_vpl VALUES ("JR22_7","025_22_7","JER","22","7","7","Zan aika da mai hallakarwa a kanki, kowane mutum da makamansa, za su kuma yayyanka gumaguman al’ul na ki masu kyau su jefa su cikin wuta. ");
INSERT INTO hausa_vpl VALUES ("JR22_8","025_22_8","JER","22","8","8","“Mutane daga al’ummai da yawa za su ratsa cikin wannan birni su kuma tambayi juna suna cewa, ‘Me ya sa Ubangiji ya yi haka da wannan babban birni?’ ");
INSERT INTO hausa_vpl VALUES ("JR22_9","025_22_9","JER","22","9","9","Amsar kuwa za tă zama, ‘Domin sun keta alkawarin Ubangiji Allahnsu, suka yi sujada suka kuma bauta wa waɗansu alloli.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR22_10","025_22_10","JER","22","10","10","Kada ku yi kuka domin sarkin da ya mutu ko ku yi makoki saboda rashinsa; a maimako, ku yi kuka mai zafi saboda wanda aka kai zaman bauta, domin ba zai ƙara dawowa ba ko ya ƙara ganin ƙasarsa ta haihuwa. ");
INSERT INTO hausa_vpl VALUES ("JR22_11","025_22_11","JER","22","11","11","Gama ga abin da Ubangiji yana cewa game da Shallum ɗan Yosiya, wanda ya gāji mahaifinsa a matsayin sarkin Yahuda amma bai bar wurin nan ba, “Ba zai ƙara dawowa ba. ");
INSERT INTO hausa_vpl VALUES ("JR22_12","025_22_12","JER","22","12","12","Zai mutu a inda suka kai shi zaman bauta; ba zai ƙara ganin wannan ƙasa ba.” ");
INSERT INTO hausa_vpl VALUES ("JR22_13","025_22_13","JER","22","13","13","“Kaiton wanda ya gina gidansa ta hanyar rashin adalci, ɗakunansa na sama kuma ta hanyar rashin gaskiya, yana sa mutanen ƙasarsa suna aiki a banza ba ya biyansu wahalarsu. ");
INSERT INTO hausa_vpl VALUES ("JR22_14","025_22_14","JER","22","14","14","Yana cewa, ‘Zan gina wa kaina babban fada da manyan ɗakuna.’ Ta haka sai ya yi musu manyan tagogi ya manne musu al’ul ya yi musu ado kuma da ruwan ja. ");
INSERT INTO hausa_vpl VALUES ("JR22_15","025_22_15","JER","22","15","15","“Wannan zai mai da kai sarki ne in kana da al’ul a kai a kai? Mahaifinka bai kasance da abinci da abin sha ba? Ya yi abin da yake gaskiya da kuma daidai saboda haka kome ya kasance da lafiya da shi. ");
INSERT INTO hausa_vpl VALUES ("JR22_16","025_22_16","JER","22","16","16","Ya kāre muradin matalauta da mabukata, ta haka kome ya tafi masa daidai. Ba abin da ake nufi da ba san ni ke nan ba?” In ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR22_17","025_22_17","JER","22","17","17","“Amma idanunka da zuciyarka sun kahu kawai a kan ƙazamar riba, da a kan zub da jinin marar laifi da kuma a kan danniya da zalunci.” ");
INSERT INTO hausa_vpl VALUES ("JR22_18","025_22_18","JER","22","18","18","Saboda haka ga abin da Ubangiji yana cewa game da Yehohiyakim ɗan Yosiya sarkin Yahuda, “Ba za su yi kuka dominsa ba, ‘Kaito, ɗan’uwana! Kaito, ’yar’uwata!’ Ba za su yi kuka dominsa ba, ‘Kaito, maigidana! Kaito, darajarsa!’ ");
INSERT INTO hausa_vpl VALUES ("JR22_19","025_22_19","JER","22","19","19","Za a binne shi kamar jaki za a ja shi a ƙasa a jefar a bayan ƙofofin Urushalima.” ");
INSERT INTO hausa_vpl VALUES ("JR22_20","025_22_20","JER","22","20","20","“Ka haura zuwa Lebanon ka yi kuka, bari a ji muryarka a Bashan, yi kuka daga Abarim, gama an murƙushe dukan abokanka. ");
INSERT INTO hausa_vpl VALUES ("JR22_21","025_22_21","JER","22","21","21","Na ja maka kunne sa’ad da kake zama lafiya, amma sai ka ce, ‘Ba zan saurara ba!’ Wannan halinka ne tun kana matashi; ba ka yi mini biyayya ba. ");
INSERT INTO hausa_vpl VALUES ("JR22_22","025_22_22","JER","22","22","22","Iska za tă koro dukan makiyayanka abokanka kuma za su tafi zaman bauta. Sa’an nan za ka sha kunya a kuma walaƙanta ka saboda dukan muguntarka. ");
INSERT INTO hausa_vpl VALUES ("JR22_23","025_22_23","JER","22","23","23","Kai da kake zama a ‘Lebanon,’ kai da kake sheƙa a gine-ginen al’ul za ka yi nishi sa’ad da zafi ya auka maka, zafi kamar na mace mai naƙuda! ");
INSERT INTO hausa_vpl VALUES ("JR22_24","025_22_24","JER","22","24","24","“Muddin ina raye,” in ji Ubangiji, “ko kai, Yehohiyacin ɗan Yehohiyakim sarkin Yahuda, ka zama zoben hatimin dama a hannuna na dama, zan kwaɓe ka. ");
INSERT INTO hausa_vpl VALUES ("JR22_25","025_22_25","JER","22","25","25","Zan ba da kai ga waɗanda suke neman ranka, waɗanda kake tsoro, ga Nebukadnezzar sarkin Babilon da kuma ga Babiloniyawa. ");
INSERT INTO hausa_vpl VALUES ("JR22_26","025_22_26","JER","22","26","26","Zan jefar da kai da mahaifiyar da ta haife ka zuwa wata ƙasa, inda babu ɗayanku da aka haifa a wurin, a can kuma za ka mutu. ");
INSERT INTO hausa_vpl VALUES ("JR22_27","025_22_27","JER","22","27","27","Ba za ka ƙara dawo ƙasar da kake marmarin dawowa ba.” ");
INSERT INTO hausa_vpl VALUES ("JR22_28","025_22_28","JER","22","28","28","Wannan mutum Yehohiyacin ne da aka rena, fasasshen tukunya, abin da babu wanda yake so? Me ya sa za a jefar da shi da ’ya’yansa a jefar da su a ƙasar da ba su sani ba? ");
INSERT INTO hausa_vpl VALUES ("JR22_29","025_22_29","JER","22","29","29","Ya ke ƙasa, ƙasa, ƙasa, ki ji maganar Ubangiji! ");
INSERT INTO hausa_vpl VALUES ("JR22_30","025_22_30","JER","22","30","30","Ga abin da Ubangiji yana cewa, “Ka rabu da wannan mutum sai ka ce marar ’ya’ya, mutumin da ba zai yi nasara a rayuwarsa ba, gama babu zuriyarsa da za tă yi nasara babu wani da zai zauna a kursiyin Dawuda ko ya ƙara yin mulkin Yahuda.” ");
INSERT INTO hausa_vpl VALUES ("JR23_1","025_23_1","JER","23","1","1","“Kaiton makiyayan da suka hallakar suka kuma warwatsar da tumakin makiyayanta!” In ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR23_2","025_23_2","JER","23","2","2","Saboda haka ga abin da Ubangiji, Allah na Isra’ila yana ce wa makiyayan da suke lura da mutanena, “Domin kun watsar da garkena kuka kuma kore su ba ku kuma lura da su ba, zan kawo hukunci a kanku saboda muguntar da kuka yi,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR23_3","025_23_3","JER","23","3","3","“Ni kaina zan tattara raguwar garkena daga ƙasashen da na kore su zuwa zan kuma dawo da su ga makiyayansu, inda za su yi ta haihuwa su riɓaɓɓanya. ");
INSERT INTO hausa_vpl VALUES ("JR23_4","025_23_4","JER","23","4","4","Zan sa makiyaya a kansu waɗanda za su lura da su, ba za su ƙara jin tsoro ko razana ba, ba kuwa waninsu da zai ɓace,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR23_5","025_23_5","JER","23","5","5","“Kwanaki suna zuwa,” in ji Ubangiji, “sa’ad da zan tā da wa Dawuda Reshen adalci, Sarki wanda zai yi mulki da hikima ya kuma yi abin da yake gaskiya da kuma daidai a ƙasar. ");
INSERT INTO hausa_vpl VALUES ("JR23_6","025_23_6","JER","23","6","6","A cikin zamaninsa za a ceci Yahuda Isra’ila kuma zai zauna lafiya. Sunan da za a kira shi ke nan, Ubangiji Adalcinmu. ");
INSERT INTO hausa_vpl VALUES ("JR23_7","025_23_7","JER","23","7","7","“Saboda haka fa, kwanaki suna zuwa,” in ji Ubangiji, “sa’ad da mutanen ba za su ƙara cewa, ‘Muddin Ubangiji yana raye, wanda ya fito da Isra’ila daga Masar ba,’ ");
INSERT INTO hausa_vpl VALUES ("JR23_8","025_23_8","JER","23","8","8","amma za su ce, ‘Muddin Ubangiji yana raye, wanda ya fito da zuriyar Isra’ila daga ƙasar arewa da kuma daga dukan ƙasashen da ya yashe su.’ Sa’an nan za su zauna a ƙasarsu.” ");
INSERT INTO hausa_vpl VALUES ("JR23_9","025_23_9","JER","23","9","9","Game da annabawa kuwa, Zuciyata ta karai; dukan ƙasusuwana suna kaɗuwa. Na zama kamar wanda ya bugu, kamar mutumin da ruwan inabi ya sha kansa, saboda Ubangiji da kuma maganarsa mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("JR23_10","025_23_10","JER","23","10","10","Ƙasar ta cika da mazinata; saboda la’ana ƙasar ta zama kango makiyaya a hamada ta bushe. Annabawa suna bin mugayen muradu suna kuma amfani da ƙarfinsu a hanyar marar kyau. ");
INSERT INTO hausa_vpl VALUES ("JR23_11","025_23_11","JER","23","11","11","“Annabi da firist dukansu biyu marasa sanin Allah ne; har ma a cikin haikalina na tarar da muguntarsu,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR23_12","025_23_12","JER","23","12","12","“Saboda haka hanyarsu za tă yi santsi; za a jefar da su cikin duhu a can kuwa za su fāɗi. Zan kawo musu masifa a shekarar da za a hukunta su,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR23_13","025_23_13","JER","23","13","13","“A cikin annabawan Samariya na ga wannan abin banƙyama. Suna annabci ta wurin Ba’al suna ɓad da mutanena Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("JR23_14","025_23_14","JER","23","14","14","A cikin annabawan Urushalima kuma na ga wani abin bantsoro. Suna zina suna kuma rayuwar ƙarya. Sun ƙarfafa hannuwa masu aikata mugunta, domin kada wani ya juya daga muguntarsa. Dukansu sun yi kama da Sodom a gare ni; mutanen Urushalima sun yi kama da Gomorra.” ");
INSERT INTO hausa_vpl VALUES ("JR23_15","025_23_15","JER","23","15","15","Saboda haka, ga abin da Ubangiji Maɗaukaki yana cewa game da annabawa, “Zan sa su ci abinci mai ɗaci su kuma sha ruwa mai dafi, domin daga annabawan Urushalima rashin sani Allah ya bazu ko’ina a ƙasar.” ");
INSERT INTO hausa_vpl VALUES ("JR23_16","025_23_16","JER","23","16","16","Ga abin da Ubangiji Maɗaukaki yana cewa, “Kada ku saurari abin da annabawan suke muku annabci; suna cika ku da sa zuciyar ƙarya. Suna maganar wahayi daga tunaninsu, ba daga bakin Ubangiji ba. ");
INSERT INTO hausa_vpl VALUES ("JR23_17","025_23_17","JER","23","17","17","Suna cin gaba da ce wa waɗanda suka rena ni, ‘Ubangiji ya ce za ku zauna lafiya.’ Ga duka waɗanda suke bin taurin zukatansu kuwa sukan ce, ‘Babu lahanin da zai same ku.’ ");
INSERT INTO hausa_vpl VALUES ("JR23_18","025_23_18","JER","23","18","18","Amma wane ne a cikinsu ya taɓa tsaya a majalisar Ubangiji yă ga ko ya ji maganarsa? Wa ya saurari ya kuma ji maganarsa? ");
INSERT INTO hausa_vpl VALUES ("JR23_19","025_23_19","JER","23","19","19","Ga shi, hadarin Ubangiji zai taso cikin hasala guguwa tana kaɗawa a kan kawunan mugaye. ");
INSERT INTO hausa_vpl VALUES ("JR23_20","025_23_20","JER","23","20","20","Fushin Ubangiji ba zai kau ba sai ya aikata nufin zuciyarsa. A kwanakin masu zuwa za ku gane sarai. ");
INSERT INTO hausa_vpl VALUES ("JR23_21","025_23_21","JER","23","21","21","Ban aiki waɗannan annabawa ba, duk da haka sun tafi da saƙonsu; ban yi musu magana ba, duk da haka sun yi annabci. ");
INSERT INTO hausa_vpl VALUES ("JR23_22","025_23_22","JER","23","22","22","Amma da a ce sun tsaya a majalisata, da sun yi shelar maganata ga mutanena sun kuma juyar da su daga mugayen hanyoyinsu da kuma daga mugayen ayyukansu. ");
INSERT INTO hausa_vpl VALUES ("JR23_23","025_23_23","JER","23","23","23","“Ni ɗin Allah na kusa ne kawai,” in ji Ubangiji, “ba Allah na nesa ba? ");
INSERT INTO hausa_vpl VALUES ("JR23_24","025_23_24","JER","23","24","24","Akwai wanda zai iya ɓuya a lungu har da ba zan iya ganinsa ba?” In ji Ubangiji “Ban cika sama da ƙasa ba?” In ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR23_25","025_23_25","JER","23","25","25","“Na ji abin da annabawa suna cewa su da suke annabcin ƙarya a sunana. Suna cewa, ‘Na yi mafarki! Na yi mafarki!’ ");
INSERT INTO hausa_vpl VALUES ("JR23_26","025_23_26","JER","23","26","26","Har yaushe wannan zai ci gaba a cikin zukata annabawa masu ƙarya, waɗanda suke annabcin ruɗun tunaninsu? ");
INSERT INTO hausa_vpl VALUES ("JR23_27","025_23_27","JER","23","27","27","Suna tsammanin mafarkan da suke faɗa wa juna za su sa mutane su manta da sunana, kamar yadda kakanninsu suka manta da sunana ta wurin yin wa Ba’al sujada. ");
INSERT INTO hausa_vpl VALUES ("JR23_28","025_23_28","JER","23","28","28","Bari annabin da ya yi mafarki ya faɗa mafarkinsa, amma bari wanda yake da maganata ya yi ta da aminci. Gama me ya haɗa ciyawa da alkama?” In ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR23_29","025_23_29","JER","23","29","29","“Maganata ba wuta ba ce,” in ji Ubangiji, “kuma kamar gudumar da kan ragargaza dutse? ");
INSERT INTO hausa_vpl VALUES ("JR23_30","025_23_30","JER","23","30","30","“Saboda haka,” in ji Ubangiji, “Ina gāba da annabawan da suke satar maganganuna daga juna. ");
INSERT INTO hausa_vpl VALUES ("JR23_31","025_23_31","JER","23","31","31","I,” in ji Ubangiji, “Ina gāba da annabawan da suke kaɗa harsunansu sa’an nan su ce, ‘Ubangiji ne ya furta.’ ");
INSERT INTO hausa_vpl VALUES ("JR23_32","025_23_32","JER","23","32","32","Tabbatacce, ina gāba da waɗannan da suke annabci mafarkan karya,” in ji Ubangiji. “Suna faɗarsu suna ɓad da mutanena da ƙarairayinsu na rashin hankali, duk da haka ban aike su ba, ban kuwa umarce su ba. Ba su amfani wannan mutane ba ko kaɗan,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR23_33","025_23_33","JER","23","33","33","“Sa’ad da waɗannan mutane, ko annabi ko firist, ya tambaye ka, ‘Mece ce maganarUbangiji?’ Ka ce musu, ‘Wace magana? Zan yashe ku, in ji Ubangiji.’ ");
INSERT INTO hausa_vpl VALUES ("JR23_34","025_23_34","JER","23","34","34","In annabi ko firist ko da wani dabam ya ce, ‘Wannan ne abin da Ubangiji yake cewa,’ zan hukunta wannan mutum da kuma gidansa. ");
INSERT INTO hausa_vpl VALUES ("JR23_35","025_23_35","JER","23","35","35","Ga abin da kowannenku yana cin gaba da ce wa abokinsa ko danginsa, ‘Mece ce amsar Ubangiji?’ Ko kuwa ‘mene ne Ubangiji ya faɗa?’ ");
INSERT INTO hausa_vpl VALUES ("JR23_36","025_23_36","JER","23","36","36","Amma kada ku ƙara ambatar ‘maganar Ubangiji’ domin kowace maganar mutum kan zama maganarsa. Ta haka kukan lalace maganar Allah mai rai, Ubangiji Maɗaukaki, Allahnmu. ");
INSERT INTO hausa_vpl VALUES ("JR23_37","025_23_37","JER","23","37","37","Ga abin da za ku ci gaba da faɗa wa annabi, ‘Mece ce amsar Ubangiji gare ka?’ Ko kuwa ‘mene ne Ubangiji ya faɗa?’ ");
INSERT INTO hausa_vpl VALUES ("JR23_38","025_23_38","JER","23","38","38","Ko da yake kuna cewa, ‘Wannan ce maganar Ubangiji,’ ga abin da Ubangiji yana cewa kuna amfani da kalmomi, ‘Wannan ce maganar Ubangiji,’ ko da yake na ce muku kada ku ce, ‘Wannan ce maganar Ubangiji.’ ");
INSERT INTO hausa_vpl VALUES ("JR23_39","025_23_39","JER","23","39","39","Saboda haka, tabbatacce zan manta da ku in kuma jefar da ku daga gabana tare da birnin da na ba ku da kuma kakanninku. ");
INSERT INTO hausa_vpl VALUES ("JR23_40","025_23_40","JER","23","40","40","Zan kawo muku madawwamiyar kunya, kunya ta har abada wadda ba za a taɓa manta ba.” ");
INSERT INTO hausa_vpl VALUES ("JR24_1","025_24_1","JER","24","1","1","Bayan Nebukadnezzar ya kwashi Yekoniya ɗan Yehohiyakim sarkin Yahuda da fadawa, da masu sana’a da masu zane zanen Yahuda daga Urushalima zuwa Babilon zaman bauta, Ubangiji ya nuna mini kwanduna biyu na ’ya’yan ɓaure ajiye a gaban haikalin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR24_2","025_24_2","JER","24","2","2","Kwando guda yana da ’ya’yan ɓaure masu kyau sosai, kamar waɗanda suka nuna da wuri; ɗayan kwandon kuma yana da ’ya’yan ɓaure marasa kyau, sun yi muni har ba a iya ci. ");
INSERT INTO hausa_vpl VALUES ("JR24_3","025_24_3","JER","24","3","3","Sa’an nan Ubangiji ya tambaye ni ya ce, “Me ka gani, Irmiya?” Na ce, “’Ya’yan ɓaure. Masu kyau ɗin suna da kyau sosai, amma munanan sun yi muni har ba a iya ci.” ");
INSERT INTO hausa_vpl VALUES ("JR24_4","025_24_4","JER","24","4","4","Sai maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("JR24_5","025_24_5","JER","24","5","5","“Ga abin da Ubangiji, Allah na Isra’ila, yana cewa, ‘Kamar ’ya’yan ɓauren nan masu kyau, haka zan kula da mutanen Yahuda waɗanda aka kwaso waɗanda na fisshe su daga wannan wuri zuwa ƙasar Babiloniyawa ");
INSERT INTO hausa_vpl VALUES ("JR24_6","025_24_6","JER","24","6","6","Idanuna za su kula da su don kyautatawarsu, zan kuma komo da su wannan ƙasa. Zan gina su ba zan rushe su ba; zan dasa su ba kuwa zan tumɓuke su ba. ");
INSERT INTO hausa_vpl VALUES ("JR24_7","025_24_7","JER","24","7","7","Zan ba su zuciya don su san ni, cewa ni ne Ubangiji. Za su zama mutanena, zan zama Allahnsu, gama za su komo gare ni da dukan zuciyarsu. ");
INSERT INTO hausa_vpl VALUES ("JR24_8","025_24_8","JER","24","8","8","“ ‘Amma kamar ’ya’yan ɓauren nan marasa kyau, waɗanda sun yi muni har ba a iya ci,’ in ji Ubangiji, ‘haka zan yi da Zedekiya sarkin Yahuda, fadawansa da sauran mutanen da suka tsira a Urushalima, ko suna a wannan ƙasa ko suna zama a Masar. ");
INSERT INTO hausa_vpl VALUES ("JR24_9","025_24_9","JER","24","9","9","Zan mai da su abin ƙyama da masifa ga dukan mulkokin duniya, abin zargi da abin karin magana, abin ba’a da abin la’ana a duk inda zan kore su zuwa. ");
INSERT INTO hausa_vpl VALUES ("JR24_10","025_24_10","JER","24","10","10","Zan aika da takobi, yunwa da annoba a kansu sai an hallaka su sarai daga ƙasar da na ba su da kuma kakanninsu.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR25_1","025_25_1","JER","25","1","1","Magana ta zo wa Irmiya game da dukan mutanen Yahuda a shekara ta huɗu ta Yehohiyakim ɗan Yosiya sarkin Yahuda, wadda ta kasance shekara ta fari ta Nebukadnezzar sarkin Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR25_2","025_25_2","JER","25","2","2","Saboda haka Irmiya annabi ya ce wa dukan mutanen Yahuda da dukan mazaunan Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR25_3","025_25_3","JER","25","3","3","Shekaru ashirin da uku, daga shekara ta goma sha uku ta Yosiya ɗan Amon sarkin Yahuda har zuwa wannan rana, maganar Ubangiji ta zo mini na kuma yi muku magana sau da sau, amma ba ku saurara ba. ");
INSERT INTO hausa_vpl VALUES ("JR25_4","025_25_4","JER","25","4","4","Ko da yake Ubangiji ya aika dukan bayinsa annabawa gare ku sau da sau, ba ku saurara ba, ba ku kuma kula ba. ");
INSERT INTO hausa_vpl VALUES ("JR25_5","025_25_5","JER","25","5","5","Sun ce, “Ku juye yanzu, kowannenku, daga mugayen hanyoyinku da mugayen ayyukanku, za ku kuwa iya zauna a ƙasar da Ubangiji ya ba ku da kuma kakanninku har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("JR25_6","025_25_6","JER","25","6","6","Kada ku bi waɗansu alloli don ku bauta ku kuma yi musu sujada; kada ku tsokane ni in yi fushi da abin da hannuwanku suka yi. Sa’an nan ba zan kawo muku lahani ba.” ");
INSERT INTO hausa_vpl VALUES ("JR25_7","025_25_7","JER","25","7","7","“Amma ba ku saurare ni ba,” in ji Ubangiji, “kun tsokane ni da abin da kuka yi da hannuwanku, kuka kuma kawo lahani wa kanku.” ");
INSERT INTO hausa_vpl VALUES ("JR25_8","025_25_8","JER","25","8","8","Saboda haka Ubangiji Maɗaukaki ya ce, “Domin kun ƙi ku saurara ga maganata, ");
INSERT INTO hausa_vpl VALUES ("JR25_9","025_25_9","JER","25","9","9","zan kira dukan mutanen arewa da bawana Nebukadnezzar sarkin Babilon,” in ji Ubangiji, “zan kuma kawo su su yi gāba da wannan ƙasa da mazaunanta da kuma gāba da dukan al’ummai da suke kewaye. Zan hallaka su sarai in kuma mai da su abin bantsoro da abin dariya, za su kuma zama kufai har abada. ");
INSERT INTO hausa_vpl VALUES ("JR25_10","025_25_10","JER","25","10","10","Zan kawar da muryoyin farin ciki da murna daga gare su, muryoyin amarya da na ango, ƙarar dutsen niƙa da hasken fitila. ");
INSERT INTO hausa_vpl VALUES ("JR25_11","025_25_11","JER","25","11","11","Dukan wannan ƙasa za tă zama kango, kuma waɗannan al’ummai za su bauta wa sarkin Babilon shekaru saba’in. ");
INSERT INTO hausa_vpl VALUES ("JR25_12","025_25_12","JER","25","12","12","“Amma sa’ad da shekaru saba’in ɗin suka cika, zan hukunta sarkin Babilon da kuma al’ummarsa, ƙasar Babiloniyawa, saboda laifinsu,” in ji Ubangiji, “in kuma mai da ita kango har abada. ");
INSERT INTO hausa_vpl VALUES ("JR25_13","025_25_13","JER","25","13","13","Zan kawo wa wannan ƙasa dukan abubuwan na yi magana a kanta, dukan abubuwan da aka rubuta a wannan littafi, abubuwan da Irmiya kuma ya yi annabci a kan dukan al’ummai. ");
INSERT INTO hausa_vpl VALUES ("JR25_14","025_25_14","JER","25","14","14","Su kansu al’ummai da sarakuna masu yawa za su bautar da su; zan sāka musu bisa ga ayyukansu da aikin hannuwansu.” ");
INSERT INTO hausa_vpl VALUES ("JR25_15","025_25_15","JER","25","15","15","Ga abin da Ubangiji, Allah na Isra’ila, ya faɗa mini, “Ka karɓi kwaf ruwan inabin nan na fushina a wurina, ka sa dukan al’umman da na aike ka gare su, su sha. ");
INSERT INTO hausa_vpl VALUES ("JR25_16","025_25_16","JER","25","16","16","Sa’ad da suka sha, za su yi ta tangaɗi su kuma yi hauka saboda takobin da zan aika a cikinsu.” ");
INSERT INTO hausa_vpl VALUES ("JR25_17","025_25_17","JER","25","17","17","Saboda haka na karɓi kwaf daga hannun Ubangiji na sa dukan al’ummai waɗanda ya aiko ni wurinsu su sha. ");
INSERT INTO hausa_vpl VALUES ("JR25_18","025_25_18","JER","25","18","18","Urushalima da garuruwan Yahuda, sarakunan da fadawanta, don su mai da su kufai da kuma abin bantsoro da ba’a da la’ana, yadda suke a yau; ");
INSERT INTO hausa_vpl VALUES ("JR25_19","025_25_19","JER","25","19","19","Fir’auna sarkin Masar, ma’aikatansa, fadawansa da dukan mutanensa, ");
INSERT INTO hausa_vpl VALUES ("JR25_20","025_25_20","JER","25","20","20","da dukan baƙin da suke can; dukan sarakunan Uz; dukan sarakunan Filistiyawa (waɗannan na Ashkelon, Gaza, Ekron da mutanen da aka bari a Ashdod); ");
INSERT INTO hausa_vpl VALUES ("JR25_21","025_25_21","JER","25","21","21","Edom, Mowab da Ammon; ");
INSERT INTO hausa_vpl VALUES ("JR25_22","025_25_22","JER","25","22","22","dukan sarakunan Taya da Sidon; sarakunan bakin teku a ƙetaren teku; ");
INSERT INTO hausa_vpl VALUES ("JR25_23","025_25_23","JER","25","23","23","Dedan, Tema, Buz da dukan waɗanda suke a manisantan wurare; ");
INSERT INTO hausa_vpl VALUES ("JR25_24","025_25_24","JER","25","24","24","dukan sarakunan Arabiya da dukan sarakunan baƙin da suke zama a hamada; ");
INSERT INTO hausa_vpl VALUES ("JR25_25","025_25_25","JER","25","25","25","dukan sarakunan Zimri, Elam da Mediya; ");
INSERT INTO hausa_vpl VALUES ("JR25_26","025_25_26","JER","25","26","26","da kuma dukan sarakunan arewa, nesa da kuma kusa, bi da bi, dukan mulkokin duniya. Bayan dukansu kuma, sai sarkin Sheshak ma yă sha. ");
INSERT INTO hausa_vpl VALUES ("JR25_27","025_25_27","JER","25","27","27","“Sa’an nan na faɗa musu cewa, ‘Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa ku sha, ku bugu ku kuma yi amai, ku fāɗi, kada kuma ku ƙara tashi saboda takobin da zan aiko muku.’ ");
INSERT INTO hausa_vpl VALUES ("JR25_28","025_25_28","JER","25","28","28","Amma in suka ki su karɓi kwaf ɗin daga hannunka su sha, ka faɗa musu cewa, ‘Ga abin da Ubangiji Maɗaukaki yana cewa dole ku sha! ");
INSERT INTO hausa_vpl VALUES ("JR25_29","025_25_29","JER","25","29","29","Ga shi, na sa masifa tă yi aiki cikin birnin da ake kira da sunana, kuna gani za ku tafi ba hukunci? Ba za ku tafi ba hukunci ba, gama ina kawo wa dukan mazaunan duniya takobi, in ji Ubangiji Maɗaukaki.’ ");
INSERT INTO hausa_vpl VALUES ("JR25_30","025_25_30","JER","25","30","30","“Yanzu ka yi annabcin dukan waɗannan maganganu a kansu ka kuma ce musu, “ ‘Ubangiji zai yi ruri daga bisa; zai yi tsawa daga mazauninsa mai tsarki ya kuma yi ruri da ƙarfi a kan ƙasarsa. Zai yi ihu kamar waɗanda suke matsin ’ya’yan inabi, yi ihu a kan dukan waɗanda suke zaune a duniya. ");
INSERT INTO hausa_vpl VALUES ("JR25_31","025_25_31","JER","25","31","31","Hayaniya za tă taso har iyakar duniya, gama Ubangiji zai kawo tuhume-tuhume a kan al’ummai; zai kawo shari’a a kan dukan ’yan adam ya kuma kashe mugaye da takobi,’ ” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR25_32","025_25_32","JER","25","32","32","Ga abin da Ubangiji Maɗaukaki yana cewa, “Duba! Masifa tana yaɗuwa daga al’umma zuwa al’umma; hadari mai girma yana tasowa daga iyakar duniya.” ");
INSERT INTO hausa_vpl VALUES ("JR25_33","025_25_33","JER","25","33","33","A lokacin waɗanda Ubangiji ya kashe za su kasance a ko’ina, daga wannan bangon duniya zuwa wancan. Ba za a yi kuka dominsu, ba za a tattara su don a binne ba, amma za su zama kamar juji da an tsiba a ƙasa. ");
INSERT INTO hausa_vpl VALUES ("JR25_34","025_25_34","JER","25","34","34","Ku yi kuka ku kuma yi makoki, ku makiyaya; ku yi ta birgima a ƙura, ku shugabannin garke. Gama lokacin da za a yanka ku ya zo; za ku fāɗi ku kuma farfasa kamar tukunyar yumɓu mai kyau. ");
INSERT INTO hausa_vpl VALUES ("JR25_35","025_25_35","JER","25","35","35","Makiyaya ba za su sami wurin da za su gudu su tafi ba, shugabannin garke ba za su sami wurin kuɓuta ba. ");
INSERT INTO hausa_vpl VALUES ("JR25_36","025_25_36","JER","25","36","36","Ji kukan makiyaya, kururuwan shugabannin garke, gama Ubangiji yana hallaka wurin kiwo. ");
INSERT INTO hausa_vpl VALUES ("JR25_37","025_25_37","JER","25","37","37","Rafi mai gudu a hankali zai zama kango saboda zafin fushin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR25_38","025_25_38","JER","25","38","38","Kamar zaki zai bar wurin ɓuyarsa, ƙasarsu kuma za tă zama kufai saboda takobin masu danniya da kuma saboda zafin fushin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR26_1","025_26_1","JER","26","1","1","A farkon sarautar Yehohiyakim ɗan Yosiya sarkin Yahuda, wannan magana ta zo daga wurin Ubangiji, ");
INSERT INTO hausa_vpl VALUES ("JR26_2","025_26_2","JER","26","2","2","“Ga abin da Ubangiji yana cewa, ka tsaya a filin gidan Ubangiji ka kuma yi magana ga dukan mutanen garuruwan Yahuda waɗanda suka zo sujada a gidan Ubangiji. Ka faɗa musu kome da na umarce ka; kada ka bar wata magana. ");
INSERT INTO hausa_vpl VALUES ("JR26_3","025_26_3","JER","26","3","3","Wataƙila su saurara kowanne kuma ya juyo daga mugun hanyarsa. Sa’an nan in yi juyayi in kuma janye masifar da nake shirin kawo a kansu saboda muguntar da suka aikata. ");
INSERT INTO hausa_vpl VALUES ("JR26_4","025_26_4","JER","26","4","4","Ka faɗa musu, ‘Ga abin da Ubangiji yana cewa, in ba ku saurare ni, ku kuma bi dokata, wadda na sa a gabanku ba, ");
INSERT INTO hausa_vpl VALUES ("JR26_5","025_26_5","JER","26","5","5","in kuma ba ku saurari maganganun bayina annabawa, waɗanda na aika muku sau da sau ba (ko da yake ba ku saurara ba), ");
INSERT INTO hausa_vpl VALUES ("JR26_6","025_26_6","JER","26","6","6","to, sai in mai da gidan nan kamar Shilo, birnin nan kuma abin la’ana a cikin al’umman duniya.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR26_7","025_26_7","JER","26","7","7","Firistoci, annabawa da dukan mutane suka ji Irmiya yana waɗannan maganganu a gidan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR26_8","025_26_8","JER","26","8","8","Amma da Irmiya ya gama faɗar wa dukan mutanen abin da Ubangiji ya umarce shi ya faɗa, sai firistoci, annabawa da dukan mutane suka kama shi suka ce, “Mutuwa za ka yi! ");
INSERT INTO hausa_vpl VALUES ("JR26_9","025_26_9","JER","26","9","9","Me ya sa ka yi annabci da sunan Ubangiji cewa wannan gida zai zama kamar Shilo, wannan birni kuma zai zama kango da hamada?” Sai duk mutane suka tattaru kewaye da Irmiya a cikin gidan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR26_10","025_26_10","JER","26","10","10","Da fadawan Yahuda suka ji haka, sai suka haura daga fada zuwa gidan Ubangiji suka zazzauna a wuraren zamansu a mashigin Sabuwar Ƙofar gidan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR26_11","025_26_11","JER","26","11","11","Sa’an nan firistoci da annabawa suka ce wa fadawan da dukan mutane, “Mutumin nan ya cancanci hukuncin kisa gama ya yi annabci gāba da wannan birni. Ku kun ji da kunnuwanku!” ");
INSERT INTO hausa_vpl VALUES ("JR26_12","025_26_12","JER","26","12","12","Sai Irmiya ya ce wa dukan fadawa da kuma dukan mutane, “Ubangiji ya aiko ni in yi annabci gāba da wannan gida da wannan birni dukan abin da na faɗa. ");
INSERT INTO hausa_vpl VALUES ("JR26_13","025_26_13","JER","26","13","13","Yanzu sai ku gyara hanyoyinku da kuma ayyukanku ku yi biyayya da Ubangiji Allahnku. Sa’an nan Ubangiji zai yi juyayi ya kuma janye masifar da ya furta zai kawo a kanku. ");
INSERT INTO hausa_vpl VALUES ("JR26_14","025_26_14","JER","26","14","14","Game da ni dai, ina a hannuwanku; ku yi duk abin da kuka ga ya yi kyau, ya kuma dace a gare ku. ");
INSERT INTO hausa_vpl VALUES ("JR26_15","025_26_15","JER","26","15","15","Ku tabbata dai, cewa in kuka kashe ni, za ku jawo wa kanku alhakin jini marar laifi a kanku da a kan birnin nan da kuma a kan masu zama a cikinsa, gama a gaskiya Ubangiji ne ya aiko ni wurinku domin in faɗa muku dukan maganan nan a kunnuwanku.” ");
INSERT INTO hausa_vpl VALUES ("JR26_16","025_26_16","JER","26","16","16","Sai fadawa da dukan mutane suka ce wa firistoci da annabawa. “Wannan mutum bai yi abin da ya isa hukuncin kisa ba, gama ya yi magana da sunan Ubangiji Allahnmu.” ");
INSERT INTO hausa_vpl VALUES ("JR26_17","025_26_17","JER","26","17","17","Waɗansu daga cikin dattawan ƙasar suka zo gaba suka ce wa dukan taron jama’a, ");
INSERT INTO hausa_vpl VALUES ("JR26_18","025_26_18","JER","26","18","18","“Mika mutumin Moreshet, ya yi annabci a kwanakin Hezekiya sarkin Yahuda. Ya ce wa dukan mutanen Yahuda, ‘Ga abin da Ubangiji Maɗaukaki yana cewa, “ ‘Za a nome Sihiyona kamar gona, Urushalima kuwa za tă zama tsibin juji, ƙwanƙolin dutsen haikali kuwa zai zama kurmi.’ ");
INSERT INTO hausa_vpl VALUES ("JR26_19","025_26_19","JER","26","19","19","“Hezekiya sarkin Yahuda ko kuwa wani a Yahuda ya kashe shi? Ashe, Hezekiya bai ji tsoron Ubangiji ya nemi tagomashinsa ba? Ubangiji kuwa bai yi juyayi ya kuma janye masifar da ya furta zai kawo a kansu ba? Muna gab da jawo wa kanmu muguwar masifa!” ");
INSERT INTO hausa_vpl VALUES ("JR26_20","025_26_20","JER","26","20","20","(To, fa, Uriya ɗan Shemahiya daga Kiriyat Yeyarim wani mutum ne wanda ya yi annabci da sunan Ubangiji; ya yi annabci irin abu ɗaya gāba da wannan birni da wannan ƙasa yadda Irmiya ya yi. ");
INSERT INTO hausa_vpl VALUES ("JR26_21","025_26_21","JER","26","21","21","Da sarki Yehohiyakim da dukan fadawansa da ma’aikatansa suka ji wannan magana, sai sarki ya nemi a kashe shi. Amma Uriya ya ji wannan shiri sai ya gudu zuwa Masar don tsoro. ");
INSERT INTO hausa_vpl VALUES ("JR26_22","025_26_22","JER","26","22","22","Sarki Yehohiyakim ya aiki Elnatan ɗan Akbor zuwa Masar, tare da waɗansu mutane. ");
INSERT INTO hausa_vpl VALUES ("JR26_23","025_26_23","JER","26","23","23","Suka dawo da Uriya daga Masar suka kawo shi wurin Sarki Yehohiyakim, wanda ya kashe shi da takobi aka kuma jefar da gawarsa a makabartar talakawa.) ");
INSERT INTO hausa_vpl VALUES ("JR26_24","025_26_24","JER","26","24","24","Bugu da ƙari, Ahikam ɗan Shafan ya goyi bayan Irmiya, saboda haka ba a ba da shi ga mutane don su kashe shi ba. ");
INSERT INTO hausa_vpl VALUES ("JR27_1","025_27_1","JER","27","1","1","A farkon sarautar Zedekiya ɗan Yosiya sarkin Yahuda, wannan magana ta zo wa Irmiya daga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR27_2","025_27_2","JER","27","2","2","Ga abin da Ubangiji ya ce mini, “Ka yi karkiyar itace da maɗaurai ka ɗaura a wuyanka. ");
INSERT INTO hausa_vpl VALUES ("JR27_3","025_27_3","JER","27","3","3","Sa’an nan ka aika da saƙo zuwa wurin sarakunan Edom, Mowab, Ammon, Taya da Sidon ta bakin jakadu waɗanda suka zo Urushalima wurin Zedekiya sarkin Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR27_4","025_27_4","JER","27","4","4","Ka ba su saƙo wa iyayengijinsu su ce, ‘Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa, “Ku faɗa wa iyayengijinku wannan. ");
INSERT INTO hausa_vpl VALUES ("JR27_5","025_27_5","JER","27","5","5","Da ikon mai ƙarfi da kuma hannuna da na miƙa na yi duniya da mutanenta da kuma dabbobin da suke ciki, na ba da ita ga duk wanda na ga dama. ");
INSERT INTO hausa_vpl VALUES ("JR27_6","025_27_6","JER","27","6","6","Yanzu zan ba da dukan ƙasashenku ga bawana Nebukadnezzar sarkin Babilon; zan sa namun jeji ma su bauta masa. ");
INSERT INTO hausa_vpl VALUES ("JR27_7","025_27_7","JER","27","7","7","Dukan al’ummai za su bauta masa da ɗansa da kuma jikansa har sai har lokacin ƙasarsa ya kai; sa’an nan al’ummai masu yawa da kuma manyan sarakuna za su kasance a ƙarƙashinsa. ");
INSERT INTO hausa_vpl VALUES ("JR27_8","025_27_8","JER","27","8","8","“ ‘ “Amma fa, duk al’umma ko mulkin da bai bauta wa Nebukadnezzar sarkin Babilon ba bai kuwa rusunar da wuyarsa ga karkiyarsa ba, zan hukunta wannan al’umma da takobi, yunwa da annoba, in ji Ubangiji, har sai na hallaka ta ta wurin hannunsa. ");
INSERT INTO hausa_vpl VALUES ("JR27_9","025_27_9","JER","27","9","9","Saboda haka kada ku saurari annabawanku, masu dubanku, masu fassarar mafarkanku, bokayenku ko masu maitancinku waɗanda suke ce muku, ‘Ba za ku bauta wa sarkin Babilon ba.’ ");
INSERT INTO hausa_vpl VALUES ("JR27_10","025_27_10","JER","27","10","10","Suna muku annabcin ƙaryar ne kawai da za tă kau da ku daga ƙasarku; zan kore ku za ku kuwa hallaka. ");
INSERT INTO hausa_vpl VALUES ("JR27_11","025_27_11","JER","27","11","11","Amma duk al’ummar da ta rusuna da wuyarta a ƙarƙashin karkiyar sarkin Babilon ta kuma bauta masa, zan bar al’ummar ta zauna a ƙasarta ta noma ta, ta kuma zauna a can, in ji Ubangiji.” ’ ” ");
INSERT INTO hausa_vpl VALUES ("JR27_12","025_27_12","JER","27","12","12","Na ba da wannan saƙo guda ga Zedekiya sarkin Yahuda. Na ce, “Ka rusunar da wuyanka a ƙarƙashin sarkin Babilon; ka bauta masa da kuma mutanensa, za ka kuwa rayu. ");
INSERT INTO hausa_vpl VALUES ("JR27_13","025_27_13","JER","27","13","13","Me ya sa kai da mutanenka za ku mutu saboda takobi, yunwa da annoba waɗanda Ubangiji ya yi barazana wa duk al’ummar da ba za tă bauta wa sarkin Babilon ba? ");
INSERT INTO hausa_vpl VALUES ("JR27_14","025_27_14","JER","27","14","14","Kada ku saurari maganganun annabawa waɗanda suke ce muku, ‘Ba za ku bauta wa sarkin Babilon ba,’ gama annabcin ƙarya suke muku. ");
INSERT INTO hausa_vpl VALUES ("JR27_15","025_27_15","JER","27","15","15","‘Ban aike su ba,’ in ji Ubangiji. ‘Suna annabcin ƙarya ne da sunana. Saboda haka, zan kore ku za ku kuwa hallaka, da ku da kuma annabawan da suke muku annabci.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR27_16","025_27_16","JER","27","16","16","Sai na ce wa firistoci da dukan waɗannan mutane, “Ga abin da Ubangiji yana cewa, kada ku saurari annabawan da suke cewa, ‘Ba daɗewa ba za a komo da kayan gidan Ubangiji daga Babilon.’ Suna muku annabcin ƙarya ne. ");
INSERT INTO hausa_vpl VALUES ("JR27_17","025_27_17","JER","27","17","17","Kada ku saurare su. Ku bauta wa sarkin Babilon, za ku kuwa rayu. Don me wannan birni zai zama kufai? ");
INSERT INTO hausa_vpl VALUES ("JR27_18","025_27_18","JER","27","18","18","In su annabawa ne da gaske suna kuma da maganar Ubangiji, bari su roƙi Ubangiji Maɗaukaki ya sa kada a kwashe kayayyakin da suka ragu a gidan Ubangiji da kuma a cikin fadar sarkin Yahuda da kuma cikin Urushalima a kai Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR27_19","025_27_19","JER","27","19","19","Gama ga abin da Ubangiji Maɗaukaki yana cewa game da ginshiƙai, kwatarniya, da dakalai, da sauran kayayyaki da aka bar su a birnin nan, ");
INSERT INTO hausa_vpl VALUES ("JR27_20","025_27_20","JER","27","20","20","waɗanda Nebukadnezzar sarkin Babilon ya kwashe sa’ad da ya kame Yekoniya ɗan Yehohiyakim sarkin Yahuda zuwa zaman bauta daga Urushalima zuwa Babilon tare da dukan manyan mutanen Yahuda da Urushalima, ");
INSERT INTO hausa_vpl VALUES ("JR27_21","025_27_21","JER","27","21","21","I, ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila yana cewa game da abubuwan da aka bari a gidan Ubangiji da kuma a cikin fadar sarkin Yahuda da Urushalima, ");
INSERT INTO hausa_vpl VALUES ("JR27_22","025_27_22","JER","27","22","22","‘Za a kwashe su zuwa Babilon a can kuwa za su kasance sai ranar da na neme su,’ in ji Ubangiji. ‘Sa’an nan zan komo da su in maido da su wannan wuri.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR28_1","025_28_1","JER","28","1","1","A wata na biyar na wannan shekara, shekara ta huɗu, a farkon sarautar Zedekiya sarkin Yahuda, sai annabi Hananiya ɗan Azzur, wanda ya fito daga Gibeyon, ya zo wurina a gidan Ubangiji a gaban firistoci da kuma dukan mutane, ");
INSERT INTO hausa_vpl VALUES ("JR28_2","025_28_2","JER","28","2","2","“Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila ya ce, ‘Zan karya karkiyar sarkin Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR28_3","025_28_3","JER","28","3","3","Cikin shekaru biyu zan komo da dukan kayayyakin gidan Ubangiji da Nebukadnezzar sarkin Babilon ya kwashe daga wannan wuri ya kai Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR28_4","025_28_4","JER","28","4","4","Zan kuma komo da Yekoniya ɗan Yehohiyakim sarkin Yahuda da kuma dukan sauran masu zaman bauta daga Yahuda waɗanda suka tafi Babilon,’ in ji Ubangiji, ‘gama zan karya karkiyar sarkin Babilon.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR28_5","025_28_5","JER","28","5","5","Sai annabi Irmiya ya amsa wa annabi Hananiya a gaban firistoci da kuma dukan mutane waɗanda suke tsaye a gidan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR28_6","025_28_6","JER","28","6","6","Ya ce, “Amin! Ubangiji yă sa yă zama haka! Ubangiji yă cika maganar da ka yi annabci ta wurin komo da kayayyakin gidan Ubangiji da kuma dukan masu zaman bauta zuwa wannan wuri daga Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR28_7","025_28_7","JER","28","7","7","Duk da haka, ka saurari abin da zan faɗa a kunnenka da kuma a kunnen duka mutane, ");
INSERT INTO hausa_vpl VALUES ("JR28_8","025_28_8","JER","28","8","8","Daga farko fari annabawan da suka riga ka da ni sun yi annabcin yaƙi, masifa da annoba a kan ƙasashe masu yawa da kuma manyan mulkoki. ");
INSERT INTO hausa_vpl VALUES ("JR28_9","025_28_9","JER","28","9","9","Amma annabin da ya yi annabcin salama shi za a ɗauka a matsayin wanda Ubangiji ya aika in har abin da ya furta ya zama gaskiya.” ");
INSERT INTO hausa_vpl VALUES ("JR28_10","025_28_10","JER","28","10","10","Sai annabi Hananiya ya cire karkiya daga wuyar annabi Irmiya ya karya ta, ");
INSERT INTO hausa_vpl VALUES ("JR28_11","025_28_11","JER","28","11","11","ya ce a gaban dukan mutane, “Ga abin da Ubangiji yana cewa, ‘A haka zan karya karkiyar Nebukadnezzar sarkin Babilon daga wuyan dukan al’ummai a cikin shekaru biyu.’ ” Da wannan, annabi Irmiya ya yi tafiyarsa. ");
INSERT INTO hausa_vpl VALUES ("JR28_12","025_28_12","JER","28","12","12","Ba a daɗe ba bayan annabi Hananiya ya karya karkiya daga wuyan annabi Irmiya, sai maganar Ubangiji ta zo wa Irmiya cewa, ");
INSERT INTO hausa_vpl VALUES ("JR28_13","025_28_13","JER","28","13","13","“Je ka faɗa wa Hananiya cewa, ‘Ga abin da Ubangiji yana cewa, ka karya karkiyar katako, amma a wurinsa za ka sami karkiyar ƙarfe. ");
INSERT INTO hausa_vpl VALUES ("JR28_14","025_28_14","JER","28","14","14","Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa zan sa karkiyar ƙarfe a wuyan dukan waɗannan al’ummai don in sa su bauta wa Nebukadnezzar sarkin Babilon, za su kuwa bauta masa. Zan ma sa shi ya mallaki namun jeji.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR28_15","025_28_15","JER","28","15","15","Sa’an nan annabi Irmiya ya ce wa annabi Hananiya, “Ka saurara, Hananiya! Ubangiji bai aike ka ba, duk da haka ka lallashe wannan al’umma su dogara ga ƙarya. ");
INSERT INTO hausa_vpl VALUES ("JR28_16","025_28_16","JER","28","16","16","Saboda haka, ga abin da Ubangiji yana cewa, ‘Ina shirin kawar da kai daga fuskar duniya. A wannan shekara za ka mutu, domin ka yi wa’azin tawaye a kan Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR28_17","025_28_17","JER","28","17","17","A wata na bakwai na wannan shekara, annabi Hananiya ya mutu. ");
INSERT INTO hausa_vpl VALUES ("JR29_1","025_29_1","JER","29","1","1","Ga abin da yake cikin wasiƙar annabi Irmiya da ya aika daga Urushalima zuwa ga sauran dattawan da suka ragu a cikin masu zaman bauta da kuma zuwa ga firistoci, annabawa da kuma dukan sauran mutanen da Nebukadnezzar ya kwashe zuwa zaman bauta daga Urushalima zuwa Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR29_2","025_29_2","JER","29","2","2","(Wannan ya faru bayan Sarki Yekoniya da mahaifiyar sarauniya, shugabannin fada da kuma dukan shugabannin Yahuda da Urushalima, gwanayen sana’a da masu sassaƙa suka tafi zaman bauta daga Urushalima.) ");
INSERT INTO hausa_vpl VALUES ("JR29_3","025_29_3","JER","29","3","3","Ya ba da wasiƙar ta hannun Eleyasa ɗan Shafan da Gemariya ɗan Hilkiya, waɗanda Zedekiya sarkin Yahuda ya aika wurin Sarki Nebukadnezzar a Babilon. Wasiƙar ta ce, ");
INSERT INTO hausa_vpl VALUES ("JR29_4","025_29_4","JER","29","4","4","Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa ga dukan waɗanda aka kwashe zuwa zaman bauta daga Urushalima zuwa Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR29_5","025_29_5","JER","29","5","5","“Ku gina gidaje ku zauna; ku dasa gonaki ku kuma ci abin da suka haifar. ");
INSERT INTO hausa_vpl VALUES ("JR29_6","025_29_6","JER","29","6","6","Ku yi aure ku kuma haifi ’ya’ya maza da mata; ku nemi mata wa ’ya’yanku maza, ku kuma ba da ’ya’yanku mata ga aure, saboda su ma za su haifi ’ya’ya maza da mata. Ku riɓaɓɓanya a can, kada ku ragu. ");
INSERT INTO hausa_vpl VALUES ("JR29_7","025_29_7","JER","29","7","7","Haka kuma, ku nemi zaman salama da cin gaba a birnin da aka kai ku zaman bauta. Ku yi addu’a ga Ubangiji saboda birnin, domin in ya ci gaba, ku ma za ku ci gaba.” ");
INSERT INTO hausa_vpl VALUES ("JR29_8","025_29_8","JER","29","8","8","I, ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila yana cewa, “Kada ku bar annabawa da masu sihiri a cikinku su ruɗe ku. Kada ku saurari mafarkan da dā kuke ƙarfafa su su yi. ");
INSERT INTO hausa_vpl VALUES ("JR29_9","025_29_9","JER","29","9","9","Suna muku annabcin ƙarya da sunana. Ban aike su ba,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR29_10","025_29_10","JER","29","10","10","Ga abin da Ubangiji yana cewa, “Sa’ad da shekaru saba’in suka cika a Babilon, zan zo muku in cika alkawarin alherina don in komo da ku zuwa wannan wuri. ");
INSERT INTO hausa_vpl VALUES ("JR29_11","025_29_11","JER","29","11","11","Gama na san shirye-shiryen da na yi muku,” in ji Ubangiji, “shirye-shiryen cin gaba ba na cutarwa ba, shirye-shiryen ba ku sa zuciya da kuma na nan gaba. ");
INSERT INTO hausa_vpl VALUES ("JR29_12","025_29_12","JER","29","12","12","Sa’an nan za ku kira gare ni ku zo ku kuma yi addu’a gare ni, zan kuwa ji ku. ");
INSERT INTO hausa_vpl VALUES ("JR29_13","025_29_13","JER","29","13","13","Za ku neme ni ku kuwa same ni sa’ad da kuka neme ni da dukan zuciyarku. ");
INSERT INTO hausa_vpl VALUES ("JR29_14","025_29_14","JER","29","14","14","Za ku same ni,” in ji Ubangiji, “zan kuma komo da ku daga bauta. Zan tattaro ku daga dukan al’ummai in sa ku inda na kore ku,” in ji Ubangiji, “zan kuma komo da ku zuwa wurin da na kwashe ku zuwa zaman bauta.” ");
INSERT INTO hausa_vpl VALUES ("JR29_15","025_29_15","JER","29","15","15","Za ku iya ce, “Ubangiji ya tā da annabawa saboda mu a Babilon.” ");
INSERT INTO hausa_vpl VALUES ("JR29_16","025_29_16","JER","29","16","16","Amma ga abin da Ubangiji yana cewa game da sarki, wanda yake zaune a kursiyin Dawuda da kuma dukan mutanen da suka ragu a wannan birni, ’yan’uwanku waɗanda ba su tafi tare da ku zuwa zaman bauta ba. ");
INSERT INTO hausa_vpl VALUES ("JR29_17","025_29_17","JER","29","17","17","I, ga abin da Ubangiji Maɗaukaki yana cewa, “Zan aika da takobi, yunwa da annoba a kansu zan kuma sa su zama kamar ɓaure marar amfani da suka yi munin da ba a iya ci. ");
INSERT INTO hausa_vpl VALUES ("JR29_18","025_29_18","JER","29","18","18","Zan fafare su da takobi, yunwa da annoba zan kuma sa su zama abin ƙyama ga dukan mulkokin duniya da kuma abin la’ana da abin bantsoro, abin dariya da abin reni, a cikin dukan al’umman da aka kore su zuwa. ");
INSERT INTO hausa_vpl VALUES ("JR29_19","025_29_19","JER","29","19","19","Gama ba su saurari maganata ba,” in ji Ubangiji, “maganar da na aika gare su sau da sau ta bayina annabawa. Ku kuma masu zaman bauta ba ku saurara ba,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR29_20","025_29_20","JER","29","20","20","Saboda haka, ku ji maganar Ubangiji, dukanku masu zaman bauta waɗanda na aika daga Urushalima zuwa Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR29_21","025_29_21","JER","29","21","21","Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa game da Ahab ɗan Kolahiya da Zedekiya ɗan Ma’asehiya, waɗanda suke muku annabcin ƙarya da sunana. “Zan ba da su ga Nebukadnezzar sarkin Babilon, zai kuwa kashe su a gaban idanunku. ");
INSERT INTO hausa_vpl VALUES ("JR29_22","025_29_22","JER","29","22","22","Saboda su, dukan masu zaman bauta daga Yahuda waɗanda suke a Babilon za su yi amfani da wannan la’ana cewa, ‘Ubangiji ka yi da mu kamar Zedekiya da Ahab waɗanda sarkin Babilon ya ƙone da wuta.’ ");
INSERT INTO hausa_vpl VALUES ("JR29_23","025_29_23","JER","29","23","23","Gama sun aikata munanan abubuwa a Isra’ila; sun yi zina da matan maƙwabtansu kuma da sunana suka yi ƙarya, waɗanda ban faɗa musu su yi ba. Na san wannan kuma ni shaida ne ga haka,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR29_24","025_29_24","JER","29","24","24","Faɗa wa Shemahiya mutumin Nehelam, ");
INSERT INTO hausa_vpl VALUES ("JR29_25","025_29_25","JER","29","25","25","“Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa ka aika da wasiƙu da sunanka ga dukan mutane a Urushalima, zuwa ga Zefaniya ɗan Ma’asehiya firist da kuma ga sauran firistoci. Ka ce wa Zefaniya, ");
INSERT INTO hausa_vpl VALUES ("JR29_26","025_29_26","JER","29","26","26","‘Ubangiji ya naɗa ka firist a wurin Yehohiyada don ka lura da gidan Ubangiji; ya kamata ka sa kowane mahaukaci wanda yake yi kamar annabi cikin turu da kuma a kangi. ");
INSERT INTO hausa_vpl VALUES ("JR29_27","025_29_27","JER","29","27","27","To, me ya sa ba ka tsawata wa Irmiya daga Anatot, wanda yana ɗauka kansa annabi a cikinku ba? ");
INSERT INTO hausa_vpl VALUES ("JR29_28","025_29_28","JER","29","28","28","Ya aiko mana da saƙonsa a Babilon cewa zai ɗauki lokaci ƙwarai. Saboda haka ku gina gidaje ku zauna; ku dasa gonaki ku kuma ci abin da suka haifar.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR29_29","025_29_29","JER","29","29","29","Zefaniya firist kuwa, ya karanta wasiƙar annabi Irmiya. ");
INSERT INTO hausa_vpl VALUES ("JR29_30","025_29_30","JER","29","30","30","Sa’an nan maganar Ubangiji ta zo wa Irmiya cewa, ");
INSERT INTO hausa_vpl VALUES ("JR29_31","025_29_31","JER","29","31","31","“Ka aika da wannan saƙo zuwa ga dukan masu zaman bauta cewa, ‘Ga abin da Ubangiji yana cewa game da Shemahiya, mutumin Nehelam. Domin Shemahiya ya yi muku annabci, ko da yake ban aike shi ba, ya kuma sa kuka gaskata ƙarya, ");
INSERT INTO hausa_vpl VALUES ("JR29_32","025_29_32","JER","29","32","32","ga abin da Ubangiji yana cewa, tabbatacce zan hukunta Shemahiya mutumin Nehelam da zuriyarsa. Ba zai kasance da wani da ya rage a cikin wannan mutane ba, ba kuwa zai ga abubuwa alherin da zan yi wa mutanena ba, in ji Ubangiji, domin ya yi wa’azin tawaye a kaina.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR30_1","025_30_1","JER","30","1","1","Ga maganar da ta zo wa Irmiya daga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR30_2","025_30_2","JER","30","2","2","“Ga abin da Ubangiji, Allah na Isra’ila, yana cewa, ‘Ka rubuta a cikin littafi dukan maganganun da na yi maka. ");
INSERT INTO hausa_vpl VALUES ("JR30_3","025_30_3","JER","30","3","3","Kwanaki suna zuwa,’ in ji Ubangiji, ‘sa’ad da zan komo da mutanena Isra’ila da Yahuda daga bauta in kuma maido da su ga ƙasar da na ba wa kakanninsu mallaka,’ in ji Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("JR30_4","025_30_4","JER","30","4","4","Ga kalmomin Ubangiji da ya yi game da Isra’ila da Yahuda, ");
INSERT INTO hausa_vpl VALUES ("JR30_5","025_30_5","JER","30","5","5","“Ga abin da Ubangiji yana cewa, “ ‘Ana jin kukan tsoro, razana, ba salama ba. ");
INSERT INTO hausa_vpl VALUES ("JR30_6","025_30_6","JER","30","6","6","Ku tambaya ku ji. Namiji zai iya haifi ’ya’ya? To, me ya sa kuke ganin kowane mai ƙarfi da hannuwansa a kwankwaso kamar mace mai naƙuda, kowace fuska ta koma fari? ");
INSERT INTO hausa_vpl VALUES ("JR30_7","025_30_7","JER","30","7","7","Kaito, gama wannan rana za tă zama mai girma! Babu kamar ta. Zai zama lokacin wahala wa Yaƙub, amma za a cece shi daga cikinta. ");
INSERT INTO hausa_vpl VALUES ("JR30_8","025_30_8","JER","30","8","8","“ ‘A wannan rana,’ in ji Ubangiji Maɗaukaki, ‘Zan karya karkiya daga wuyansu zan kuma cire musu kangi; baƙi ba za su ƙara bautar da su ba. ");
INSERT INTO hausa_vpl VALUES ("JR30_9","025_30_9","JER","30","9","9","A maimakon haka, za su bauta wa Ubangiji Allahnsu Dawuda sarkinsu kuwa, wanda na tayar musu. ");
INSERT INTO hausa_vpl VALUES ("JR30_10","025_30_10","JER","30","10","10","“ ‘Saboda haka kada ka ji tsoro, ya Yaƙub bawana; kada ka karai, ya Isra’ila,’ in ji Ubangiji. ‘Tabbatacce zan cece ka daga wuri mai nesa, zuriyarka daga ƙasar zaman bautansu. Yaƙub zai sami salama da zaman lafiya, kuma ba wanda zai sa ya ji tsoro. ");
INSERT INTO hausa_vpl VALUES ("JR30_11","025_30_11","JER","30","11","11","Ina tare da kai zan kuma cece ka,’ in ji Ubangiji. ‘Ko da yake na hallakar da dukan al’umma gaba ɗaya a inda na warwatsa ku, ba zan hallaka ku gaba ɗaya ba. Zan hore ku amma da adalci kaɗai; ba zan ƙyale ku ku tafi gaba ɗaya ba hukunci ba.’ ");
INSERT INTO hausa_vpl VALUES ("JR30_12","025_30_12","JER","30","12","12","“Ga abin da Ubangiji yana cewa, “ ‘Mikinku marar warkewa ne, raunin da kuka ji ya sha ƙarfin warkarwa. ");
INSERT INTO hausa_vpl VALUES ("JR30_13","025_30_13","JER","30","13","13","Babu wanda zai yi roƙo saboda damuwarku, ba magani domin mikinku babu warkarwa dominku. ");
INSERT INTO hausa_vpl VALUES ("JR30_14","025_30_14","JER","30","14","14","Dukan abokanku sun manta da ku; ba su ƙara kulawa da ku. Na buge ku kamar yadda abokin gāba zai yi na kuma hukunta ku yadda mai mugunta zai yi, domin laifinku da girma yake zunubanku kuma da yawa suke. ");
INSERT INTO hausa_vpl VALUES ("JR30_15","025_30_15","JER","30","15","15","Me ya sa kuke kuka a kan mikinku, wahalarku da ba ta da magani? Domin laifinku da girma yake da kuma zunubanku masu yawa na yi muku waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("JR30_16","025_30_16","JER","30","16","16","“ ‘Amma duk wanda ya cinye ku za a cinye shi; dukan abokan gābanku za su tafi zaman bauta. Waɗanda suka washe ku su ma za a washe su; dukan waɗanda suka mai da ku ganima su ma zan mai da su ganima. ");
INSERT INTO hausa_vpl VALUES ("JR30_17","025_30_17","JER","30","17","17","Amma zan mayar muku da lafiya in kuma warkar da mikinku,’ in ji Ubangiji, ‘domin ana ce da ku yasassu, Sihiyona wadda ba wanda ya kula da ita.’ ");
INSERT INTO hausa_vpl VALUES ("JR30_18","025_30_18","JER","30","18","18","“Ga abin da Ubangiji yana cewa, “ ‘Zan mayar da wadatar tentin Yaƙub in kuma ji tausayin wuraren zamansa; za a sāke gina birnin a kufansa, fadar kuwa za tă tsaya a wurin da ya dace da ita. ");
INSERT INTO hausa_vpl VALUES ("JR30_19","025_30_19","JER","30","19","19","Daga gare su waƙoƙi za su fito na godiya da kuma sowa ta farin ciki. Zan riɓaɓɓanya su, ba za su kuwa ragu ba; zan kawo musu ɗaukaka, ba kuwa za a ƙasƙanta su ba. ");
INSERT INTO hausa_vpl VALUES ("JR30_20","025_30_20","JER","30","20","20","’Ya’yansu za su kasance kamar a kwanakin dā jama’arsu kuma za su kahu a gabana; zan hukunta duk wanda ya zalunce su. ");
INSERT INTO hausa_vpl VALUES ("JR30_21","025_30_21","JER","30","21","21","Shugabansu zai zama ɗaya daga cikinsu; mai mulkinsu zai taso daga cikinsu. Zan kawo shi kusa zai kuma zo kusa da ni, gama wane ne zai miƙa kansa don yă yi kusa da ni?’ In ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR30_22","025_30_22","JER","30","22","22","‘Saboda haka za ku zama mutanena, ni kuwa in zama Allahnku.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR30_23","025_30_23","JER","30","23","23","Ga shi, hadarin Ubangiji zai fasu cikin hasala, iskar guguwa mai hurawa a kan kawunan mugaye. ");
INSERT INTO hausa_vpl VALUES ("JR30_24","025_30_24","JER","30","24","24","Fushi mai zafi na Ubangiji ba zai kawu ba sai ya cika manufofin zuciyarsa gaba ɗaya. A kwanaki masu zuwa za ku gane wannan. ");
INSERT INTO hausa_vpl VALUES ("JR31_1","025_31_1","JER","31","1","1","“A lokacin nan, zan zama Allah na dukan kabilan Isra’ila, za su kuma zama mutanena,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR31_2","025_31_2","JER","31","2","2","Ga abin da Ubangiji yana cewa, “Mutanen da suka tsere wa takobi za su sami tagomashi a hamada; zan zo don in ba da hutu ga Isra’ila.” ");
INSERT INTO hausa_vpl VALUES ("JR31_3","025_31_3","JER","31","3","3","Ubangiji ya bayyana mana a dā, yana cewa, “Na ƙaunace ku da madawwamiyar ƙauna; na janye ku da ƙauna marar iyaka. ");
INSERT INTO hausa_vpl VALUES ("JR31_4","025_31_4","JER","31","4","4","Zan sāke gina ki za ki kuwa sāke ginuwa, ya Budurwar Isra’ila. Za ki kuma ɗauki ganganki ki fita don ki yi rawa da masu farin ciki. ");
INSERT INTO hausa_vpl VALUES ("JR31_5","025_31_5","JER","31","5","5","Za ki sāke dasa gonakin inabi a kan tussan Samariya; manoma za su yi shuka a kansu su kuma ji daɗin amfaninsu. ");
INSERT INTO hausa_vpl VALUES ("JR31_6","025_31_6","JER","31","6","6","Za a yi ranar da matsara za su tā da murya a kan tuddan Efraim su ce, ‘Ku zo, bari mu haura Sihiyona, zuwa wurin Ubangiji Allahnmu.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR31_7","025_31_7","JER","31","7","7","Ga abin da Ubangiji yana cewa, “Ku rera don farin ciki wa Yaƙub; ku yi sowa don al’ummai da suke nesa. Ka sa a ji yabanku, ku kuma ce, ‘Ya Ubangiji ka ceci mutanenka, raguwar Isra’ila.’ ");
INSERT INTO hausa_vpl VALUES ("JR31_8","025_31_8","JER","31","8","8","Ga shi, zan kawo su daga ƙasar arewa in tattara su daga iyakar duniya. A cikinsu makafi da guragu za su kasance, mata masu ciki da matan da suke naƙuda; jama’a mai yawan gaske za su komo. ");
INSERT INTO hausa_vpl VALUES ("JR31_9","025_31_9","JER","31","9","9","Za su zo da kuka; za su yi addu’a yayinda nake komo da su. Zan bishe su kusa da rafuffukan ruwa a miƙaƙƙiyar hanya inda ba za su yi tuntuɓe ba, domin ni ne mahaifin Isra’ila, Efraim kuma ɗan farina ne. ");
INSERT INTO hausa_vpl VALUES ("JR31_10","025_31_10","JER","31","10","10","“Ku ji maganar Ubangiji, ya al’ummai; ku yi shelarta a gaban teku masu nesa cewa, ‘Shi wanda ya watsar da Isra’ila zai tattara su zai kuma lura da garkensa kamar makiyayi.’ ");
INSERT INTO hausa_vpl VALUES ("JR31_11","025_31_11","JER","31","11","11","Gama Ubangiji zai fanshi Yaƙub zai cece su daga hannun waɗanda suka fi su ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("JR31_12","025_31_12","JER","31","12","12","Za su zo su yi sowa don farin ciki a ƙwanƙolin Sihiyona; za su yi farin ciki cikin yalwar Ubangiji hatsi, sabon ruwan inabi da mai, ’ya’yan garken tumaki da na shanu. Za su zama kamar gonar da aka yi wa banruwa, ba za su ƙara yin baƙin ciki ba. ");
INSERT INTO hausa_vpl VALUES ("JR31_13","025_31_13","JER","31","13","13","’Yan mata za su yi rawa su kuma yi murna, haka ma samari da tsofaffi. Zan mai da makokinsu farin ciki; zan ta’azantar da su in kuma sa su yi farin ciki a maimakon baƙin ciki. ");
INSERT INTO hausa_vpl VALUES ("JR31_14","025_31_14","JER","31","14","14","Zan ƙosar da firistoci da yalwa, mutanena kuma za su cika da yalwa,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR31_15","025_31_15","JER","31","15","15","Ga abin da Ubangiji yana cewa, “An ji murya daga Rama, makoki da kuka mai zafi, Rahila tana kuka domin ’ya’yanta ta kuma ƙi a ta’azantar da ita domin ’ya’yanta ba su.” ");
INSERT INTO hausa_vpl VALUES ("JR31_16","025_31_16","JER","31","16","16","Ga abin da Ubangiji yana cewa, “Hana muryarki kuka da kuma idanunki hawaye, gama za a sāka wa aikinki,” in ji Ubangiji. “Za su komo daga ƙasar abokin gāba. ");
INSERT INTO hausa_vpl VALUES ("JR31_17","025_31_17","JER","31","17","17","Saboda haka akwai sa zuciya domin nan gaba,” in ji Ubangiji. “’Ya’yanki za su komo ƙasarsu. ");
INSERT INTO hausa_vpl VALUES ("JR31_18","025_31_18","JER","31","18","18","“Tabbatacce na ji gurnanin Efraim yana cewa, ‘Ka hore ni kamar ɗan maraƙi mai ƙin ji, na kuwa horu. Ka mayar da ni, zan kuwa dawo, domin kai ne Ubangiji Allahna. ");
INSERT INTO hausa_vpl VALUES ("JR31_19","025_31_19","JER","31","19","19","Bayan na kauce, sai na tuba; bayan na gane, sai na sunkuyar da kaina. Na ji kunya da ƙasƙanci domin ina ɗauke da kunyar ƙuruciyata.’ ");
INSERT INTO hausa_vpl VALUES ("JR31_20","025_31_20","JER","31","20","20","Efraim ba ƙaunataccen ɗana ba ne, ɗan da nake jin daɗinsa? Ko da yake sau da dama ina maganar gāba a kansa, duk da haka nakan tuna da shi. Saboda haka zuciyata tana marmarinsa; ina da jinƙai mai girma dominsa,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR31_21","025_31_21","JER","31","21","21","“Ki kafa alamun hanya; ki sa shaidun bishewa. Ki lura da babbar hanya da kyau, hanyar da kika bi. Ki komo, ya Budurwar Isra’ila, ki komo zuwa garuruwanki. ");
INSERT INTO hausa_vpl VALUES ("JR31_22","025_31_22","JER","31","22","22","Har yaushe za ki yi ta yawo, Ya ’ya marar aminci? Ubangiji zai ƙirƙiro sabon abu a duniya mace za tă kewaye namiji.” ");
INSERT INTO hausa_vpl VALUES ("JR31_23","025_31_23","JER","31","23","23","Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila yana cewa, “Sa’ad da na komo da su daga bauta mutane a ƙasar Yahuda da cikin garuruwanta za su sāke yi amfani da waɗannan kalmomi. ‘Ubangiji ya albarkace ka, ya mazauni mai adalci, ya tsarkakan dutse.’ ");
INSERT INTO hausa_vpl VALUES ("JR31_24","025_31_24","JER","31","24","24","Mutane za su zauna tare a Yahuda da dukan garuruwansa, manoma da waɗanda suke yawo da garkunansu. ");
INSERT INTO hausa_vpl VALUES ("JR31_25","025_31_25","JER","31","25","25","Zan wartsake waɗanda suka gaji in kuma ƙosar da waɗanda ransu ya yi yaushi.” ");
INSERT INTO hausa_vpl VALUES ("JR31_26","025_31_26","JER","31","26","26","A kan wannan na farka na duba kewaye. Barcina ya yi mini daɗi. ");
INSERT INTO hausa_vpl VALUES ("JR31_27","025_31_27","JER","31","27","27","“Kwanaki suna zuwa,” in ji Ubangiji, “sa’ad da zan kafa gidan Isra’ila da gidan Yahuda da ’ya’yan mutane da na dabbobi. ");
INSERT INTO hausa_vpl VALUES ("JR31_28","025_31_28","JER","31","28","28","Kamar yadda na lura da su don su tumɓuke su kuma rusar, su lalatar, su hallaka su kuma kawo masifa, haka zan lura da su don su gina su kuma dasa,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR31_29","025_31_29","JER","31","29","29","“A waɗannan kwanaki mutane ba za su ƙara ce, “ ‘Ubanni suka ci ’ya’yan inabi masu tsami, haƙoran ’ya’ya suka mutu ba.’ ");
INSERT INTO hausa_vpl VALUES ("JR31_30","025_31_30","JER","31","30","30","A maimako, kowa zai mutu saboda zunubinsa; duk wanda ya ci ’ya’yan inabi masu tsami, haƙoransa ne za su mutu. ");
INSERT INTO hausa_vpl VALUES ("JR31_31","025_31_31","JER","31","31","31","“Lokaci yana zuwa,” in ji Ubangiji, “sa’ad da zan yi sabon alkawari da gidan Isra’ila da kuma gidan Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR31_32","025_31_32","JER","31","32","32","Ba zai zama kamar alkawarin da na yi da kakanni kakanninsu ba sa’ad da na kama su da hannu na bishe su daga Masar, domin sun take alkawarina, ko da yake na zama miji a gare su,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR31_33","025_31_33","JER","31","33","33","“Ga alkawarin da zan yi da gidan Isra’ila bayan wannan lokaci,” in ji Ubangiji. “Zan sa dokata a tunaninsu in kuma rubuta ta a zukatansu. Zan zama Allahnsu, za su kuma zama mutanena. ");
INSERT INTO hausa_vpl VALUES ("JR31_34","025_31_34","JER","31","34","34","Mutum ba zai ƙara koya wa maƙwabci ba, ko ya koya wa ɗan’uwansa cewa, ‘Ka san Ubangiji,’ domin duk za su san ni, daga ƙaraminsu har zuwa babba,” in ji Ubangiji. “Gama zan gafarta muguntarsu ba zan kuwa ƙara tuna da zunubansu ba.” ");
INSERT INTO hausa_vpl VALUES ("JR31_35","025_31_35","JER","31","35","35","Ga abin da Ubangiji yana cewa, shi da ya kafa rana don tă yi haske a yini shi da ya sa wata da taurari su yi haske da dare, shi da yake dama teku don raƙuman ruwansa su yi ruri Ubangiji Maɗaukaki ne sunansa. ");
INSERT INTO hausa_vpl VALUES ("JR31_36","025_31_36","JER","31","36","36","“In dai wannan kafaffiyar ƙa’ida ta daina aiki a gabana,” in ji Ubangiji, “to, sai zuriyar Isra’ila ta daina zama al’umma a gabana.” ");
INSERT INTO hausa_vpl VALUES ("JR31_37","025_31_37","JER","31","37","37","Ga abin da Ubangiji yana cewa, “In a iya auna sammai a kuma bincike tushen duniya a ƙarƙas to, sai in ƙi dukan zuriyar Isra’ila ke nan saboda dukan abin da suka yi,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR31_38","025_31_38","JER","31","38","38","“Kwanaki suna zuwa,” in ji Ubangiji, “sa’ad da za a sāke gina wannan birni domina daga Hasumiyar Hananel zuwa Ƙofar Kusurwa. ");
INSERT INTO hausa_vpl VALUES ("JR31_39","025_31_39","JER","31","39","39","Ma’auni zai miƙe daga can ya nausa kai tsaye zuwa tudun Gareb sa’an nan ya juya zuwa Gowa. ");
INSERT INTO hausa_vpl VALUES ("JR31_40","025_31_40","JER","31","40","40","Dukan kwarin da ake zubar da toka da kuma gawawwaki, da dukan lambatun da suke can har zuwa Kwarin Kidron a gabas zuwa kusurwar Ƙofar Doki, za su zama mai tsarki ga Ubangiji. Ba za a ƙara tumɓuke birnin ko a rushe shi ba.” ");
INSERT INTO hausa_vpl VALUES ("JR32_1","025_32_1","JER","32","1","1","Ga maganar da ta zo wa Irmiya daga Ubangiji a shekara ta goma ta Zedekiya sarkin Yahuda, wanda ya kasance shekara ta goma sha takwas ta Nebukadnezzar. ");
INSERT INTO hausa_vpl VALUES ("JR32_2","025_32_2","JER","32","2","2","Sojojin sarkin Babilon a lokacin suna ƙawanya wa Urushalima annabi Irmiya kuwa yana a tsare a sansanin matsara a fadar Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR32_3","025_32_3","JER","32","3","3","Zedekiya sarkin Yahuda fa ya sa shi a kurkuku yana cewa, “Don me kake yin annabci? Ka ce, ‘Ga abin da Ubangiji yana cewa, ina gab da ba da wannan birni ga sarkin Babilon, zai kuwa cinye ta. ");
INSERT INTO hausa_vpl VALUES ("JR32_4","025_32_4","JER","32","4","4","Zedekiya sarkin Yahuda ba zai kuɓuta daga hannuwan Babiloniyawa ba amma tabbatacce za a ba da shi ga sarkin Babilon, zai kuwa yi masa magana fuska da fuska ya kuma gan shi da idanunsa. ");
INSERT INTO hausa_vpl VALUES ("JR32_5","025_32_5","JER","32","5","5","Zai kai Zedekiya Babilon, inda zai zauna har sai ya magance shi, in ji Ubangiji. In ka yi yaƙi da Babiloniyawa, ba za ka yi nasara ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR32_6","025_32_6","JER","32","6","6","Irmiya ya ce, “Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("JR32_7","025_32_7","JER","32","7","7","Hananel ɗan Shallum ɗan’uwan mahaifinka zai zo wurinka ya ce, ‘Saya filina a Anatot, domin a matsayinka na dangi na kurkusa hakkinka ne kuma kai ya wajaba ka saye shi.’ ");
INSERT INTO hausa_vpl VALUES ("JR32_8","025_32_8","JER","32","8","8","“Sa’an nan, kamar dai yadda Ubangiji ya faɗa, sai ga Hananel yaron ɗan’uwan mahaifina ya zo wurina a sansanin matsara ya ce, ‘Saya filina a Anatot a yankin Benyamin. Da yake hakkinka ne ka fanshe shi ka kuma mallake shi, ka sayo shi wa kanka.’ “Sai na gane cewa wannan maganar Ubangiji ce; ");
INSERT INTO hausa_vpl VALUES ("JR32_9","025_32_9","JER","32","9","9","saboda haka sai na saye filin a Anatot daga hannun Hananel yaron ɗan’uwan mahaifina na kuma auna masa shekel goma sha bakwai na azurfa. ");
INSERT INTO hausa_vpl VALUES ("JR32_10","025_32_10","JER","32","10","10","Na sa hannu a takarda, na buga hatimi na liƙe, na sami shaidu na kuwa auna shekel a ma’auni. ");
INSERT INTO hausa_vpl VALUES ("JR32_11","025_32_11","JER","32","11","11","Na ɗauki takardar ciniki, takardar da aka rubuta sharuɗan a ciki, da kuma takardar da ba a liƙe ba, ");
INSERT INTO hausa_vpl VALUES ("JR32_12","025_32_12","JER","32","12","12","na kuma ba wa Baruk ɗan Neriya, ɗan Masehiya, wannan takarda a gaban Hananel yaron ɗan’uwan mahaifina da kuma a gaban shaidun da suka sa hannu a takardan ciniki da kuma a gaban dukan Yahudawan da suke zaune a sansanin matsaran. ");
INSERT INTO hausa_vpl VALUES ("JR32_13","025_32_13","JER","32","13","13","“A gabansu na yi wa Baruk waɗannan umarnai cewa, ");
INSERT INTO hausa_vpl VALUES ("JR32_14","025_32_14","JER","32","14","14","‘Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa ka ɗauki waɗannan takardun ciniki, wanda aka liƙe da wanda ba a liƙe ba, ka sa su a cikin tulun yumɓu don kada su lalace. ");
INSERT INTO hausa_vpl VALUES ("JR32_15","025_32_15","JER","32","15","15","Gama ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa za a sāke saye gidaje, filaye da gonakin inabi a wannan ƙasa.’ ");
INSERT INTO hausa_vpl VALUES ("JR32_16","025_32_16","JER","32","16","16","“Bayan na ba da takardun ciniki ga Baruk ɗan Neriya, sai na yi addu’a ga Ubangiji na ce, ");
INSERT INTO hausa_vpl VALUES ("JR32_17","025_32_17","JER","32","17","17","“A, Ubangiji Mai Iko Duka, ka yi sammai da duniya ta wurin ikonka mai girma da kuma hannunka mai iko. Ba abin da ya gagare ka. ");
INSERT INTO hausa_vpl VALUES ("JR32_18","025_32_18","JER","32","18","18","Kakan nuna ƙauna ga dubbai amma kakan hukunta ’ya’ya saboda laifin ubanninsu a bayansu. Ya mai girma da kuma Allah mai iko, wanda sunansa ne Ubangiji Maɗaukaki, ");
INSERT INTO hausa_vpl VALUES ("JR32_19","025_32_19","JER","32","19","19","manufofinka da girma suke, ayyukanka kuma masu girma ne. Idanunka suna a buɗe ga dukan hanyoyin mutane; kakan sāka wa kowa gwargwadon halinsa yadda ya dace. ");
INSERT INTO hausa_vpl VALUES ("JR32_20","025_32_20","JER","32","20","20","Ka aikata ayyukan banmamaki da kuma al’ajabai a Masar ka kuma ci gaba da su har yă zuwa yau, a Isra’ila da kuma a cikin dukan ’yan adam, ka kuma sami sunan da har yanzu yake naka. ");
INSERT INTO hausa_vpl VALUES ("JR32_21","025_32_21","JER","32","21","21","Ka fitar da mutanenka Isra’ila daga Masar da alamu da abubuwa banmamaki, ta wurin hannu mai iko da kuma hannu mai ƙarfi tare da banrazana mai girma. ");
INSERT INTO hausa_vpl VALUES ("JR32_22","025_32_22","JER","32","22","22","Ka ba su wannan ƙasa da ka rantse za ka ba wa kakanni kakanninsu, ƙasa mai zub da madara da zuma. ");
INSERT INTO hausa_vpl VALUES ("JR32_23","025_32_23","JER","32","23","23","Suka shiga suka mallake ta, amma ba su yi maka biyayya ba, ba su kuma bi dokarka ba; ba su yi abin da ka umarce su ba. Saboda haka ka kawo masifa a kansu. ");
INSERT INTO hausa_vpl VALUES ("JR32_24","025_32_24","JER","32","24","24","“Duba yadda aka gina mahaurai don a kame birni. Saboda takobi, yunwa da annoba, za a ba da birnin ga Babiloniyawa waɗanda suka kewaye shi da yaƙi. Abin da ka faɗa ya faru, yadda kake gani yanzu. ");
INSERT INTO hausa_vpl VALUES ("JR32_25","025_32_25","JER","32","25","25","Ko da yake za a ba da birnin ga Babiloniyawa, kai, ya Ubangiji Mai Iko Duka, ka ce mini, ‘Saye fili da azurfa ka kuma sa a shaida cinikin.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR32_26","025_32_26","JER","32","26","26","Sa’an nan maganar Ubangiji ta zo wa Irmiya cewa, ");
INSERT INTO hausa_vpl VALUES ("JR32_27","025_32_27","JER","32","27","27","“Ni ne Ubangiji Allah na dukan ’yan adam. Akwai wani abin da ya gagare ni? ");
INSERT INTO hausa_vpl VALUES ("JR32_28","025_32_28","JER","32","28","28","Saboda haka, ga abin da Ubangiji yana cewa, ina gab da ba da wannan birni ga Babiloniyawa da kuma ga Nebukadnezzar sarkin Babilon, wanda zai yaƙe ta. ");
INSERT INTO hausa_vpl VALUES ("JR32_29","025_32_29","JER","32","29","29","Babiloniyawan da suke yaƙi da wannan birni za su zo ciki su cinna masa wuta; tare da gidaje inda mutane suka tsokane ni na yi fushi ta wurin ƙona turare a rufin ɗakuna wa Ba’al suka zub da hadayun sha wa waɗansu alloli. ");
INSERT INTO hausa_vpl VALUES ("JR32_30","025_32_30","JER","32","30","30","“Mutanen Isra’ila da na Yahuda ba abin da suka yi sai mugunta a gabana daga ƙuruciyarsu; tabbatacce, mutanen Isra’ila ba su yi kome ba sai dai tsokane ni da abin da hannuwansu suka yi, in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR32_31","025_32_31","JER","32","31","31","Daga ranar da aka gina ta har zuwa yanzu, wannan birni ta tā da fushina da hasalata da dole a kawar da ita daga gabana. ");
INSERT INTO hausa_vpl VALUES ("JR32_32","025_32_32","JER","32","32","32","Mutanen Isra’ila da na Yahuda sun tsokane ni ta wurin dukan muguntar da suka aikata su, sarakunansu da fadawansu, firistocinsu da annabawa, mutanen Yahuda da mutanen Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR32_33","025_32_33","JER","32","33","33","Sun juya mini bayansu ba fuskokinsu ba; ko da yake na koyar da su sau da sau, ba su saurara ko bi horo na ba. ");
INSERT INTO hausa_vpl VALUES ("JR32_34","025_32_34","JER","32","34","34","Sun kafa gumakansu na banƙyama a cikin haikalina wanda ake kira da sunana, sun kuwa ƙazantar da shi. ");
INSERT INTO hausa_vpl VALUES ("JR32_35","025_32_35","JER","32","35","35","Sun gina masujadai kan tudu wa Ba’al a Kwarin Ben Hinnom don su miƙa ’ya’yansu maza da mata hadaya ga Molek, ko da yake ban taɓa umarce su ba, bai kuma zo mini cewa su yi abin banƙyama irin wannan ba ta haka suka sa Yahuda ya yi zunubi. ");
INSERT INTO hausa_vpl VALUES ("JR32_36","025_32_36","JER","32","36","36","“Kana cewa game da wannan birni, ‘Ta wurin takobi, yunwa da annoba za a ba da shi ga sarkin Babilon’; amma ga abin da Ubangiji, Allah na Isra’ila yana cewa ");
INSERT INTO hausa_vpl VALUES ("JR32_37","025_32_37","JER","32","37","37","tabbatacce zan tattara su daga dukan ƙasashen da na kore su zuwa cikin fushina da hasalata mai girma; zan komo da su wurin nan in sa su zauna lafiya. ");
INSERT INTO hausa_vpl VALUES ("JR32_38","025_32_38","JER","32","38","38","Za su zama mutanena, ni kuwa in zama Allahnsu. ");
INSERT INTO hausa_vpl VALUES ("JR32_39","025_32_39","JER","32","39","39","Zan ba su zuciya ɗaya da aiki ɗaya, don kullum su ji tsorona domin amfaninsu da kuma amfanin ’ya’yansu a bayansu. ");
INSERT INTO hausa_vpl VALUES ("JR32_40","025_32_40","JER","32","40","40","Zan yi madawwamin alkawari da su. Ba zan taɓa barin aikata musu alheri ba, zan kuma iza su su ji tsorona, don kada su ƙara juya daga gare ni. ");
INSERT INTO hausa_vpl VALUES ("JR32_41","025_32_41","JER","32","41","41","Zan yi farin ciki a yin musu alheri, tabbatacce zan su dasa a wannan ƙasa da dukan zuciyata da dukan raina. ");
INSERT INTO hausa_vpl VALUES ("JR32_42","025_32_42","JER","32","42","42","“Ga abin da Ubangiji yana cewa, yadda na kawo dukan wannan masifa a kan wannan mutane, haka zan ba su wadatar da na yi musu alkawari. ");
INSERT INTO hausa_vpl VALUES ("JR32_43","025_32_43","JER","32","43","43","Za a sāke sayi filaye a wannan ƙasa da kuka ce, ‘Kango ce, ba mutane ko dabbobi, gama an ba da ita ga Babiloniyawa.’ ");
INSERT INTO hausa_vpl VALUES ("JR32_44","025_32_44","JER","32","44","44","Za a sayi filaye da azurfa, a kuma sa hannu a takardan ciniki, a liƙe a kuma shaida a yankin Benyamin, a ƙauyukan kewayen Urushalima, a garuruwan Yahuda da kuma a garuruwan ƙasar tudu, na yammancin gindin dutse da na Negeb, domin zan maido da wadatarsu, in ji Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("JR33_1","025_33_1","JER","33","1","1","Yayinda Irmiya yana a tsare a sansanin matsara, sai maganar Ubangiji ta zo masa sau na biyu cewa, ");
INSERT INTO hausa_vpl VALUES ("JR33_2","025_33_2","JER","33","2","2","“Ga abin da Ubangiji yana cewa, shi da ya halicci duniya, Ubangiji wanda ya siffanta ta ya kuma kafa ta, Ubangiji ne sunansa. ");
INSERT INTO hausa_vpl VALUES ("JR33_3","025_33_3","JER","33","3","3","‘Kira gare ni zan kuwa amsa maka in kuma faɗa maka manyan abubuwan da ba a iya kaiwa, da ba ka sani ba.’ ");
INSERT INTO hausa_vpl VALUES ("JR33_4","025_33_4","JER","33","4","4","Gama ga abin da Ubangiji, Allah na Isra’ila yana cewa game da gidaje a wannan birni da fadodin Yahuda da aka rurrushe domin a yi amfani da su a kan mahaurai da kuma takobi ");
INSERT INTO hausa_vpl VALUES ("JR33_5","025_33_5","JER","33","5","5","a yaƙi da Babiloniyawa. ‘Za su cika da gawawwakin mutane waɗanda na kashe da fushina da hasalata. Zan ɓoye fuskata wa wannan birni saboda dukan muguntarsu. ");
INSERT INTO hausa_vpl VALUES ("JR33_6","025_33_6","JER","33","6","6","“ ‘Duk da haka, zan kawo lafiya da warkarwa gare ta; zan warkar da mutanena in kuma wadata su da salama da zama lafiya. ");
INSERT INTO hausa_vpl VALUES ("JR33_7","025_33_7","JER","33","7","7","Zan komo da Yahuda da Isra’ila daga bauta zan kuma sāke gina su kamar yadda suke a dā. ");
INSERT INTO hausa_vpl VALUES ("JR33_8","025_33_8","JER","33","8","8","Zan tsarkake su daga dukan zunubin da suka yi mini zan kuma gafarta musu dukan zunubansu na yin mini tawaye. ");
INSERT INTO hausa_vpl VALUES ("JR33_9","025_33_9","JER","33","9","9","Sa’an nan birnin nan za tă sa in zama sananne, farin ciki, yabo da girma a gaban dukan al’ummai a duniya da suka ji abubuwa masu kyau da na yi mata; za su kuma yi mamaki su kuma yi rawan jiki saboda yalwar wadata da salamar da na ba ta.’ ");
INSERT INTO hausa_vpl VALUES ("JR33_10","025_33_10","JER","33","10","10","“Ga abin da Ubangiji yana cewa, ‘Kuna cewa game da wannan wuri, “Kango ne, babu mutane ko dabbobi.” Duk da haka a cikin garuruwan Yahuda da titunan Urushalima da aka yashe, inda ba mutane ko dabbobi, za a sāke jin ");
INSERT INTO hausa_vpl VALUES ("JR33_11","025_33_11","JER","33","11","11","sowa ta farin ciki da murna, muryoyin amarya da na ango, da muryoyin waɗanda suka kawo hadayun salama a gidan Ubangiji suna cewa, “ ‘ “Ku yi godiya ga Ubangiji Maɗaukaki, gama Ubangiji mai alheri ne; ƙaunarsa za tă dawwama har abada.” Gama zan mayar da wadatar ƙasar kamar yadda suke a dā,’ in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR33_12","025_33_12","JER","33","12","12","“Ga abin da Ubangiji Maɗaukaki yana cewa, ‘A wannan wuri, kango da babu mutane ko dabbobi, cikin dukan garuruwansa za a sāke kasance da wurin kiwo don makiyaya su hutar da garkunansu. ");
INSERT INTO hausa_vpl VALUES ("JR33_13","025_33_13","JER","33","13","13","A cikin garuruwan ƙasar tudu, garuruwan yammancin gindin dutse da na Negeb, a yankin Benyamin, a cikin ƙauyuka kewayen Urushalima da kuma a cikin garuruwan Yahuda, garkuna za su sāke bi a ƙarƙashin hannun mai ƙidayawa,’ in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR33_14","025_33_14","JER","33","14","14","“ ‘Kwanaki suna zuwa,’ in ji Ubangiji, ‘sa’ad da zan cika alkawarin alheri da na yi wa gidan Isra’ila da kuma gidan Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR33_15","025_33_15","JER","33","15","15","“ ‘A waɗannan kwanaki da kuma a wannan lokaci zan tā da Reshe mai adalci daga zuriyar Dawuda; zai yi abin da yake daidai da kuma gaskiya a ƙasar. ");
INSERT INTO hausa_vpl VALUES ("JR33_16","025_33_16","JER","33","16","16","A kwanakin nan zan ceci Yahuda Urushalima kuma za tă zauna lafiya. Sunan da za a kira ta shi ne, Ubangiji Adalcinmu.’ ");
INSERT INTO hausa_vpl VALUES ("JR33_17","025_33_17","JER","33","17","17","Gama ga abin da Ubangiji yana cewa, ‘Dawuda ba zai taɓa rasa mutumin da zai zauna a gadon sarautar Isra’ila ba, ");
INSERT INTO hausa_vpl VALUES ("JR33_18","025_33_18","JER","33","18","18","ba kuwa firistoci waɗanda suke Lawiyawa za su rasa mutumin da zai ci gaba da tsaya a gabana don miƙa hadayun ƙonawa, ya ƙona hadayun hatsi ya kuma miƙa sadakoki ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR33_19","025_33_19","JER","33","19","19","Sai maganar Ubangiji ta zo wa Irmiya cewa, ");
INSERT INTO hausa_vpl VALUES ("JR33_20","025_33_20","JER","33","20","20","“Ga abin da Ubangiji yana cewa, ‘In ka tā da alkawarina na rana da kuma alkawarina na dare, har dare da rana ba za su ƙara bayyana a ƙayyadaddun lokutansu ba, ");
INSERT INTO hausa_vpl VALUES ("JR33_21","025_33_21","JER","33","21","21","to, sai a tā da alkawarina da Dawuda bawana da alkawarina da Lawiyawan da suke firistoci masu hidima a gabana, Dawuda kuma ba zai ƙara kasance da zuriyar da za tă yi mulki. ");
INSERT INTO hausa_vpl VALUES ("JR33_22","025_33_22","JER","33","22","22","Zan sa zuriyar Dawuda bawana da kuma Lawiyawan da suke hidima a gabana su yi yawa kamar taurarin sararin sama da kuma yashin bakin tekun da ba a iya ƙidaya.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR33_23","025_33_23","JER","33","23","23","Sai maganar Ubangiji ta zo wa Irmiya cewa, ");
INSERT INTO hausa_vpl VALUES ("JR33_24","025_33_24","JER","33","24","24","“Ba ka lura ba cewa waɗannan mutane suna cewa, ‘Ubangiji ya ƙi masarautai biyu da ya zaɓa’? Saboda haka suka rena mutanena ba sa ƙara ɗaukansu a matsayin al’umma. ");
INSERT INTO hausa_vpl VALUES ("JR33_25","025_33_25","JER","33","25","25","Ga abin da Ubangiji yana cewa, ‘In ban kafa alkawarina game da rana da kuma game da dare ba in kuma gyara dokokin sama da duniya ba, ");
INSERT INTO hausa_vpl VALUES ("JR33_26","025_33_26","JER","33","26","26","to zan ƙi zuriyar Yaƙub da na Dawuda bawana ba zan kuma zaɓi ɗaya daga cikin ’ya’yansa maza ya yi mulki a kan zuriyar Ibrahim, Ishaku da Yaƙub ba. Gama zan mayar da wadatarsu in kuma yi musu jinƙai.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR34_1","025_34_1","JER","34","1","1","Yayinda Nebukadnezzar sarkin Babilon da dukan sojojinsa da kuma dukan mulkokinsa da mutanen masarautar da yake mulki suna yaƙi da Urushalima da dukan garuruwan da suke kewaye, sai wannan magana ta zo wa Irmiya daga wurin Ubangiji cewa, ");
INSERT INTO hausa_vpl VALUES ("JR34_2","025_34_2","JER","34","2","2","“Ga abin da Ubangiji, Allah na Isra’ila, yana cewa ka tafi wurin Zedekiya sarkin Yahuda ka faɗa masa, ‘Ga abin da Ubangiji yana cewa, ina gab da ba da wannan birni ga sarkin Babilon, zai kuwa ƙone ta. ");
INSERT INTO hausa_vpl VALUES ("JR34_3","025_34_3","JER","34","3","3","Ba za ka tsere daga hannunsa ba amma tabbatacce za a kama ka a kuma ba da kai gare shi. Za ka ga sarkin Babilon da idanunka, zai kuwa yi magana da kai fuska da fuska. Za ka kuwa tafi Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR34_4","025_34_4","JER","34","4","4","“ ‘Duk da haka ka ji alkawarin Ubangiji, ya Zedekiya sarkin Yahuda. Ga abin da Ubangiji yake cewa game da kai. Ba za ka mutu ta takobi ba; ");
INSERT INTO hausa_vpl VALUES ("JR34_5","025_34_5","JER","34","5","5","za ka mutu cikin salama. Yadda mutane suka ƙuna wutar jana’iza don girmama kakanninka, sarakunan da suka riga ka, haka za su ƙuna wuta don girmama da kuma makokinka suna cewa, “Kaito, ya maigida!” Ni kaina na yi wannan alkawari, in ji Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR34_6","025_34_6","JER","34","6","6","Sa’an nan annabi Irmiya ya faɗi dukan wannan wa Zedekiya sarkin Yahuda, a Urushalima, ");
INSERT INTO hausa_vpl VALUES ("JR34_7","025_34_7","JER","34","7","7","yayinda sojojin sarkin Babilon suna yaƙi da Urushalima da sauran garuruwan Yahuda waɗanda suka ragu, Lakish da Azeka. Waɗannan su ne birane masu katanga kaɗai a Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR34_8","025_34_8","JER","34","8","8","Maganar ta zo wa Irmiya daga Ubangiji bayan Sarki Zedekiya ya yi yarjejjeniya da duka mutane a Urushalima ya yi shelar ’yanci wa bayi. ");
INSERT INTO hausa_vpl VALUES ("JR34_9","025_34_9","JER","34","9","9","Kowa ya ’yantar da bayinsa da suke Ibraniyawa, maza da mata; kada kowa ya riƙe bawa wanda yake mutumin Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR34_10","025_34_10","JER","34","10","10","Saboda haka dukan fadawa da mutane suka yi yarjejjeniyar cewa za su ’yantar da bayinsu maza da mata ba za su kuwa ƙara riƙe su bayi ba. Suka yarda, suka kuma sake su. ");
INSERT INTO hausa_vpl VALUES ("JR34_11","025_34_11","JER","34","11","11","Amma daga baya suka canja ra’ayoyinsu suka maido bayinsu suka kuma sāke bautar da su. ");
INSERT INTO hausa_vpl VALUES ("JR34_12","025_34_12","JER","34","12","12","Sai maganar Ubangiji ta zo wa Irmiya cewa, ");
INSERT INTO hausa_vpl VALUES ("JR34_13","025_34_13","JER","34","13","13","“Ga abin da Ubangiji, Allah na Isra’ila, yana cewa na yi alkawari da kakanni-kakanninku sa’ad da na fitar da su daga Masar, daga ƙasar bauta. Na ce, ");
INSERT INTO hausa_vpl VALUES ("JR34_14","025_34_14","JER","34","14","14","‘A kowace shekara ta bakwai dole kowannenku yă ’yantar da duk wani ɗan’uwa mutumin Ibraniyawa wanda aka sayar masa. Bayan ya yi muku hidima shekaru shida, dole ku bar shi yă tafi ’yantacce.’ Amma kakanninku ba su saurare ni ba, ba su ji ni ba. ");
INSERT INTO hausa_vpl VALUES ("JR34_15","025_34_15","JER","34","15","15","Bai daɗe ba da kuka tuba, kuka kuma yi abin da yake mai kyau a idona. Kowannenku ya yi shelar ’yanci ga ɗan’uwansa. Kun ma yi yarjejjeniya a gabana a gidan da ake kira da Sunana. ");
INSERT INTO hausa_vpl VALUES ("JR34_16","025_34_16","JER","34","16","16","Amma yanzu kun juya kun kuma ɓata sunana; kowannenku ya mayar da bayi maza da matan da kuka ’yantar su tafi inda suka ga dama. Kun sāke tilasta su su zama bayinku. ");
INSERT INTO hausa_vpl VALUES ("JR34_17","025_34_17","JER","34","17","17","“Saboda haka, ga abin da Ubangiji yana cewa, kun yi mini rashin biyayya; ba ku yi shelar ’yanci don ’yan’uwanku ba. Saboda haka yanzu na yi muku shelar ’yanci in ji Ubangiji, ’yanci ga mutuwa ta takobi, annoba da kuma yunwa. Zan sa ku zama abin ƙyama ga sauran mulkokin duniya. ");
INSERT INTO hausa_vpl VALUES ("JR34_18","025_34_18","JER","34","18","18","Mutanen da suka keta alkawarina da ba su cika sharuɗan alkawarin da suka yi a gabana ba, zan yi da su kamar ɗan maraƙin da suka yanka biyu suka bi ta tsakiyarsa. ");
INSERT INTO hausa_vpl VALUES ("JR34_19","025_34_19","JER","34","19","19","Shugabannin Yahuda da Urushalima, fadawa, firistoci da kuma dukan mutanen ƙasar waɗanda suka bi tsakanin ɗan maraƙin da aka yanka, ");
INSERT INTO hausa_vpl VALUES ("JR34_20","025_34_20","JER","34","20","20","zan ba da su ga abokan gābansu waɗanda suke neman ransu. Gawawwakinsu za su zama abincin tsuntsayen sararin sama da na namun jeji. ");
INSERT INTO hausa_vpl VALUES ("JR34_21","025_34_21","JER","34","21","21","“Zan ba da Zedekiya sarkin Yahuda da fadawansa ga abokan gābansu waɗanda suke neman ransu, ga sojojin sarkin Babilon, waɗanda suke janye daga gare ku. ");
INSERT INTO hausa_vpl VALUES ("JR34_22","025_34_22","JER","34","22","22","Zan yi umarni, in ji Ubangiji, zan kuma komo da su wannan birni. Za su kuwa yi yaƙi da ita, su ƙwace ta su kuma ƙone ta. Zan kuma mai da garuruwan Yahuda kufai don kada wani ya zauna a can.” ");
INSERT INTO hausa_vpl VALUES ("JR35_1","025_35_1","JER","35","1","1","Ga maganar da ta zo wa Irmiya daga wurin Ubangiji a lokacin mulkin Yehohiyakim ɗan Yosiya sarkin Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR35_2","025_35_2","JER","35","2","2","“Ka tafi wurin iyalin Rekabawa ka gayyace su su zo a ɗaya daga cikin ɗakunan da suke gefe a gidan Ubangiji ka kuma ba su ruwan inabi su sha.” ");
INSERT INTO hausa_vpl VALUES ("JR35_3","025_35_3","JER","35","3","3","Sai na tafi don in kawo Ya’azaniya ɗan Irmiya, ɗan Habazziniya, da ’yan’uwansa da kuma dukan ’ya’yansa maza, dukan iyalin Rekabawa. ");
INSERT INTO hausa_vpl VALUES ("JR35_4","025_35_4","JER","35","4","4","Na kawo su cikin gidan Ubangiji, a cikin ɗakin ’ya’yan Hanan ɗan Igdaliya maza mutumin Allah. Ɗakin ne kusa da ɗakin fadawa, wanda yake bisa na Ma’asehiya ɗan Shallum mai tsaron ƙofa. ");
INSERT INTO hausa_vpl VALUES ("JR35_5","025_35_5","JER","35","5","5","Sai na ajiye ƙwarya cike da ruwan inabi da waɗansu kwaf a gaban iyalin Rekabawan na kuma ce musu, “Ku sha ruwan inabin.” ");
INSERT INTO hausa_vpl VALUES ("JR35_6","025_35_6","JER","35","6","6","Amma sai suka amsa suka ce, “Ba ma shan ruwan inabi, domin kakanmu Yehonadab ɗan Rekab ya umarce mu cewa, ‘Ko ku, ko zuriyarku kada ku sha ruwan inabi. ");
INSERT INTO hausa_vpl VALUES ("JR35_7","025_35_7","JER","35","7","7","Haka kuma ba za ku gina gidaje, ku dasa iri ko ku nome gonakin inabi ba; kada ku kasance da wani daga cikin waɗannan abubuwa, amma dole kullum ku zauna a tentuna. Ta haka za ku yi dogon rai a cikin ƙasar baƙuncinku.’ ");
INSERT INTO hausa_vpl VALUES ("JR35_8","025_35_8","JER","35","8","8","Mun yi biyayya da kome da kakanmu Yehonadab ɗan Rekab ya umarce mu. Mu ko matanmu ko ’ya’yanmu maza da mata ba mu taɓa shan ruwan inabi ba ");
INSERT INTO hausa_vpl VALUES ("JR35_9","025_35_9","JER","35","9","9","ba mu kuma gina gidaje mu zauna a ciki ba ko mu yi gonakin inabi, gonaki ko hatsi ba. ");
INSERT INTO hausa_vpl VALUES ("JR35_10","025_35_10","JER","35","10","10","Mun yi rayuwarmu a cikin tentuna mun kuma yi biyayya ƙwarai da kowane abin da kakanmu Yehonadab ya umarce mu. ");
INSERT INTO hausa_vpl VALUES ("JR35_11","025_35_11","JER","35","11","11","Amma da Nebukadnezzar sarkin Babilon ya kawo wa ƙasan nan hari, sai muka ce, ‘Ku zo, dole mu tafi Urushalima don mu tsira daga Babiloniyawa da kuma sojojin Arameyawa.’ Saboda haka ne muke a Urushalima.” ");
INSERT INTO hausa_vpl VALUES ("JR35_12","025_35_12","JER","35","12","12","Sai maganar Ubangiji ta zo wa Irmiya cewa, ");
INSERT INTO hausa_vpl VALUES ("JR35_13","025_35_13","JER","35","13","13","“Ga abin da Ubangiji, Maɗaukaki, Allah na Isra’ila, yana cewa ka tafi ka faɗa wa mutanen Yahuda da kuma mutanen Urushalima cewa, ‘Ba za ku koyi darasi ku kuma yi biyayya da maganata ba?’ In ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR35_14","025_35_14","JER","35","14","14","‘Yehonadab ɗan Rekab ya umarci ’ya’yansa maza kada su sha ruwan inabi sun kuma kiyaye wannan umarni. Har yă zuwa yau ba sa shan ruwan inabi, domin sun yi biyayya da umarnin kakansu. Amma na yi muku magana sau da sau, duk da haka ba ku yi biyayya ba. ");
INSERT INTO hausa_vpl VALUES ("JR35_15","025_35_15","JER","35","15","15","Sau da sau na aika dukan bayina annabawa gare ku. Suka ce, “Kowannenku ya juyo daga mugayen hanyoyinsa ya sabunta ayyukansa; kada yă bi waɗansu alloli don yă bauta musu. Ta haka za ku zauna a cikin ƙasar da na ba ku da kuma kakanninku.” Amma ba ku saurara ba, ba ku kuwa ji ni ba. ");
INSERT INTO hausa_vpl VALUES ("JR35_16","025_35_16","JER","35","16","16","Zuriyar Yehonadab ɗan Rekab sun yi biyayya da umarnin da kakansu ya ba su, amma waɗannan mutane ba su yi mini biyayya ba.’ ");
INSERT INTO hausa_vpl VALUES ("JR35_17","025_35_17","JER","35","17","17","“Saboda haka, ga abin da Ubangiji Allah Maɗaukaki, Allah na Isra’ila, yana cewa, ‘Ku saurara! Zan kawo wa Yahuda da kuma kowane mutumin da yake zama a Urushalima kowace masifar da na ambata a kansu. Na yi musu magana, amma ba su saurara ba; na kira su, amma ba su amsa ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR35_18","025_35_18","JER","35","18","18","Sai Irmiya ya ce wa iyalin Rekabawa, “Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa, ‘Kun yi biyayya da umarnin kakanku Yehonadab kuka kuma kiyaye dukan umarnansa kuka yi kome bisa ga tsari.’ ");
INSERT INTO hausa_vpl VALUES ("JR35_19","025_35_19","JER","35","19","19","Saboda haka, ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa, ‘Yehonadab ɗan Rekab ba zai taɓa rasa mutumin da zai yi mini hidima ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR36_1","025_36_1","JER","36","1","1","A shekara ta huɗu ta Yehohiyakim ɗan Yosiya sarkin Yahuda, wannan magana ta zo wa Irmiya daga wurin Ubangiji cewa, ");
INSERT INTO hausa_vpl VALUES ("JR36_2","025_36_2","JER","36","2","2","“Ka ɗauki littafi ka rubuta dukan maganganun da na yi maka game da Isra’ila, Yahuda da kuma dukan sauran al’ummai daga lokacin da na fara maka magana a mulkin Yosiya har zuwa yanzu. ");
INSERT INTO hausa_vpl VALUES ("JR36_3","025_36_3","JER","36","3","3","Wataƙila sa’ad da mutanen Yahuda suka ji game da kowace masifar da na shirya in auka musu, kowa ya juya daga muguwar hanyarsa; sa’an nan in gafarta musu muguntarsu da kuma zunubinsu.” ");
INSERT INTO hausa_vpl VALUES ("JR36_4","025_36_4","JER","36","4","4","Saboda haka Irmiya ya kira Baruk ɗan Neriya, yayinda Irmiya yake fadar dukan waɗannan maganganun da Ubangiji ya faɗa masa, Baruk ya rubuta su a littafin. ");
INSERT INTO hausa_vpl VALUES ("JR36_5","025_36_5","JER","36","5","5","Sai Irmiya ya ce wa Baruk, “An hana ni, ba zan tafi haikalin Ubangiji ba. ");
INSERT INTO hausa_vpl VALUES ("JR36_6","025_36_6","JER","36","6","6","Saboda haka ka tafi gidan Ubangiji a ranar azumi ka karanta wa mutane daga littafin maganar Ubangiji da na shibta maka ka rubuta. Ka karanta su ga dukan mutanen Yahuda waɗanda suka zo daga garuruwansu. ");
INSERT INTO hausa_vpl VALUES ("JR36_7","025_36_7","JER","36","7","7","Wataƙila za su kawo kukansu a gaban Ubangiji, kowanne kuma ya juya daga muguwar hanyarsa, gama fushi da hasalar da Ubangiji ya furta a kan mutanen nan yana da girma.” ");
INSERT INTO hausa_vpl VALUES ("JR36_8","025_36_8","JER","36","8","8","Sai Baruk ɗan Neriya ya yi dukan abin da annabi Irmiya ya ce ya yi; a haikalin Ubangiji kuwa ya karanta maganar Ubangiji daga littafin ");
INSERT INTO hausa_vpl VALUES ("JR36_9","025_36_9","JER","36","9","9","A watan tara na shekara ta biyar ta Yehohiyakim ɗan Yosiya sarkin Yahuda, an yi shela a yi azumi a gaban Ubangiji ga dukan mutanen Urushalima da waɗanda suka zo daga garuruwan Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR36_10","025_36_10","JER","36","10","10","Daga ɗakin Gemariya ɗan Shafan magatakarda, wanda yake a fili na bisa a mashigin Sabuwar Ƙofar haikali, Baruk ya karanta wa dukan mutane a haikalin Ubangiji maganar Irmiya daga littafin. ");
INSERT INTO hausa_vpl VALUES ("JR36_11","025_36_11","JER","36","11","11","Sa’ad da Mikahiya ɗan Gemariya, ɗan Shafan, ya ji dukan maganar Ubangiji daga littafin, ");
INSERT INTO hausa_vpl VALUES ("JR36_12","025_36_12","JER","36","12","12","sai ya sauka zuwa ɗakin magatakarda a fada, inda dukan fadawa suke zaune, Elishama magatakarda, Delahiya ɗan Shemahiya, Elnatan ɗan Akbor, Gemariya ɗan Shafan, Zedekiya ɗan Hananiya, da dukan sauran fadawa. ");
INSERT INTO hausa_vpl VALUES ("JR36_13","025_36_13","JER","36","13","13","Bayan Mikahiya ya faɗa musu kome da ya ji Baruk ya karanta wa mutane daga littafin, ");
INSERT INTO hausa_vpl VALUES ("JR36_14","025_36_14","JER","36","14","14","sai dukan fadawan suka aiki Yehudi ɗan Netaniya, ɗan Shelemiya, ɗan Kushi, ya ce wa Baruk, “Ka zo tare da littafin da ka karanta wa mutane.” Saboda haka Baruk ɗan Neriya ya tafi wurinsu tare da littafin a hannunsa. ");
INSERT INTO hausa_vpl VALUES ("JR36_15","025_36_15","JER","36","15","15","Suka ce masa, “Zauna, ka karanta mana littafin.” Sai Baruk ya karanta musu littafin. ");
INSERT INTO hausa_vpl VALUES ("JR36_16","025_36_16","JER","36","16","16","Da suka ji dukan maganar, sai suka dubi juna a firgice suka ce wa Baruk, “Dole mu sanar da dukan maganan nan ga sarki.” ");
INSERT INTO hausa_vpl VALUES ("JR36_17","025_36_17","JER","36","17","17","Sa’an nan suka ce wa Baruk, “Faɗa mana yadda ka yi ka rubuta dukan wannan. Irmiya ne ya yi maka shibtar ta?” ");
INSERT INTO hausa_vpl VALUES ("JR36_18","025_36_18","JER","36","18","18","Baruk ya amsa ya ce, “I, shi ne ya faɗa mini dukan wannan magana, na kuwa rubuta su a takarda.” ");
INSERT INTO hausa_vpl VALUES ("JR36_19","025_36_19","JER","36","19","19","Sa’an nan fadawan suka ce wa Baruk, “Kai da Irmiya ku je ku ɓuya. Kada ku bari wani ya san inda kuke.” ");
INSERT INTO hausa_vpl VALUES ("JR36_20","025_36_20","JER","36","20","20","Bayan da suka ajiye littafin a ɗakin Elishama magatakarda, sai suka tafi wurin sarki a fili suka sanar da shi kome. ");
INSERT INTO hausa_vpl VALUES ("JR36_21","025_36_21","JER","36","21","21","Sai sarki ya aiki Yehudi ya kawo littafin daga ɗakin Elishama magatakarda ya kuma karanta wa sarki da kuma dukan fadawan da suke tsaye kusa da shi. ");
INSERT INTO hausa_vpl VALUES ("JR36_22","025_36_22","JER","36","22","22","A watan tara ne sarki kuwa yana zaune a gidansa na rani, wuta kuwa tana ci a kasko a gabansa. ");
INSERT INTO hausa_vpl VALUES ("JR36_23","025_36_23","JER","36","23","23","Duk sa’ad da Yehudi ya karanta sashi uku ko huɗu na littafin, sai sarkin ya sa wuƙa ya yanke su, ya zuba a wutar da take ci a kasko, da haka ya ƙone dukan littafin. ");
INSERT INTO hausa_vpl VALUES ("JR36_24","025_36_24","JER","36","24","24","Sai sarki da dukan masu yin masa hidima waɗanda suke jin maganan nan ba su firgita ba, balle su keta rigunansu. ");
INSERT INTO hausa_vpl VALUES ("JR36_25","025_36_25","JER","36","25","25","Ko da yake Elnatan, Delahiya da Gemariya sun roƙi sarki kada yă ƙone littafin, bai saurare su ba. ");
INSERT INTO hausa_vpl VALUES ("JR36_26","025_36_26","JER","36","26","26","A maimakon haka, sai sarki ya umarci Yerameyel ɗan sarki, Serahiya ɗan Azriyel da Shelemiya ɗan Abdeyel su kama Baruk marubuci da Irmiya annabi. Amma Ubangiji ya ɓoye su. ");
INSERT INTO hausa_vpl VALUES ("JR36_27","025_36_27","JER","36","27","27","Bayan sarki ya ƙone littafin da ya ƙunshi maganar da Baruk ya rubuta daga shibtar Irmiya, sai maganar Ubangiji ta zo wa Irmiya cewa, ");
INSERT INTO hausa_vpl VALUES ("JR36_28","025_36_28","JER","36","28","28","“Ka ɗauki wani littafi ka rubuta a kansa dukan maganar da littafi na farin ya ƙunsa, wanda Yehohiyakim sarkin Yahuda ya ƙone. ");
INSERT INTO hausa_vpl VALUES ("JR36_29","025_36_29","JER","36","29","29","Ka kuma faɗa wa Yehohiyakim sarkin Yahuda cewa, ‘Ga abin da Ubangiji yana cewa, ka ƙone wancan littafin ka kuma ce, “Don me ka rubuta a cikinsa, cewa lalle sarkin Babilon zai zo ya hallaka wannan ƙasa, zai kashe mutum duk da dabba?” ");
INSERT INTO hausa_vpl VALUES ("JR36_30","025_36_30","JER","36","30","30","Saboda haka, ga abin da Ubangiji yana cewa game da Yehohiyakim sarkin Yahuda. Ba zai kasance da wani wanda zai zauna a kan gadon sarautar Dawuda ba; za a jefar da gawarsa ta sha zafi da rana da dare kuma ta sha matsanancin sanyi. ");
INSERT INTO hausa_vpl VALUES ("JR36_31","025_36_31","JER","36","31","31","Zan hukunta shi da kuma ’ya’yansa da masu hidimarsa saboda muguntarsu; zan kawo kowace masifar da na furta a kansu da kuma waɗanda suke zama a Urushalima da na Yahuda, domin sun ƙi su saurara.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR36_32","025_36_32","JER","36","32","32","Sai Irmiya ta ɗauko wani littafi ya ba wa Baruk ɗan Neriya marubuci, kuma yayinda Irmiya yake shibtawa, Baruk ya rubuta a littafin dukan maganar da take a littafin da Yehohiyakim sarkin Yahuda ya ƙone. Ya kuma ƙara ire-iren maganganun nan a kansu. ");
INSERT INTO hausa_vpl VALUES ("JR37_1","025_37_1","JER","37","1","1","Nebukadnezzar sarkin Babilon ya naɗa Zedekiya ɗan Yosiya sarkin Yahuda; ya yi mulki a madadin Yehohiyacin ɗan Yehohiyakim. ");
INSERT INTO hausa_vpl VALUES ("JR37_2","025_37_2","JER","37","2","2","Shi da masu yin masa hidima da mutanen ƙasar ba su kula da maganar da Ubangiji ya yi ta wurin Irmiya annabi ba. ");
INSERT INTO hausa_vpl VALUES ("JR37_3","025_37_3","JER","37","3","3","Sai sarki Zedekiya ya aiki Yehukal ɗan Shelemiya tare da firist nan Zefaniya ɗan Ma’asehiya da wannan saƙo cewa, “Ina roƙonka ka yi addu’a ga Ubangiji Allahnmu saboda mu.” ");
INSERT INTO hausa_vpl VALUES ("JR37_4","025_37_4","JER","37","4","4","To, fa, Irmiya ya sami ’yancin kai da kawowa a cikin mutane, gama ba a riga an sa shi a kurkuku ba. ");
INSERT INTO hausa_vpl VALUES ("JR37_5","025_37_5","JER","37","5","5","Sojojin Fir’auna suka fita daga Masar, sa’ad da Babiloniyawa waɗanda suke ƙawanya wa Urushalima suka ji labari game da su, sai suka janye daga Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR37_6","025_37_6","JER","37","6","6","Sai maganar Ubangiji ta zo wa Irmiya annabi cewa, ");
INSERT INTO hausa_vpl VALUES ("JR37_7","025_37_7","JER","37","7","7","“Ga abin da Ubangiji, Allah na Isra’ila, yana cewa ka faɗa wa sarkin Yahuda, wanda ya aika a neme ni cewa, ‘Sojojin Fir’aunan da suka fito su taimake ka, za su koma ƙasarsu, Masar. ");
INSERT INTO hausa_vpl VALUES ("JR37_8","025_37_8","JER","37","8","8","Sa’an nan Babiloniyawa za su koma su yaƙi wannan birni su ci ta su kuma ƙone shi.’ ");
INSERT INTO hausa_vpl VALUES ("JR37_9","025_37_9","JER","37","9","9","“Ga abin da Ubangiji yana cewa, kada ku ruɗe kanku, kuna tsammani, ‘Tabbatacce Babiloniyawa sun bar mu.’ Ba za su bari ba! ");
INSERT INTO hausa_vpl VALUES ("JR37_10","025_37_10","JER","37","10","10","Ko da a ce za ku ci dukan sojojin Babiloniyawan da suke yaƙi da ku har raunana ne kawai aka bari a tentunansu, za su fito su ƙone wannan birni.” ");
INSERT INTO hausa_vpl VALUES ("JR37_11","025_37_11","JER","37","11","11","Bayan sojojin Babiloniyawa suka janye daga Urushalima saboda sojojin Fir’auna, ");
INSERT INTO hausa_vpl VALUES ("JR37_12","025_37_12","JER","37","12","12","sai Irmiya ya bar birnin don yă je yankin Benyamin ya sami rabon mallaka a cikin mutane a can. ");
INSERT INTO hausa_vpl VALUES ("JR37_13","025_37_13","JER","37","13","13","Amma sa’ad da ya kai Ƙofar Benyamin, sai hafsa mai tsaro, wanda ake kira Iriya ɗan Shelemiya, ɗan Hananiya, ya kama shi ya kuma ce, “Kana gudu daga Babiloniyawa ne!” ");
INSERT INTO hausa_vpl VALUES ("JR37_14","025_37_14","JER","37","14","14","Sai Irmiya ya ce, “Ba gaskiya ba ce, ba na gudu daga Babiloniyawa.” Amma Iriya bai saurare shi ba; a maimako, ya kama Irmiya ya kawo shi wurin fadawa. ");
INSERT INTO hausa_vpl VALUES ("JR37_15","025_37_15","JER","37","15","15","Suka yi fushi da Irmiya suka sa aka yi masa dūka aka kuma jefa shi cikin kurkuku a gidan Yonatan magatakarda, gama an mai da gidansa ya zama kurkuku. ");
INSERT INTO hausa_vpl VALUES ("JR37_16","025_37_16","JER","37","16","16","Aka sa Irmiya a can cikin kurkuku, inda ya kasance kwanaki masu yawa. ");
INSERT INTO hausa_vpl VALUES ("JR37_17","025_37_17","JER","37","17","17","Sa’an nan Sarki Zedekiya ya aika a kawo shi aka kuma kawo shi fada, inda ya tambaye shi a kaɗaice ya ce, “Akwai wata magana daga Ubangiji?” Irmiya ya amsa ya ce, “I, za a ba da kai ga sarkin Babilon.” ");
INSERT INTO hausa_vpl VALUES ("JR37_18","025_37_18","JER","37","18","18","Sai Irmiya ya ce wa Sarki Zedekiya, “Wane laifi na yi maka ko fadawanka ko kuwa wannan mutane, da ka sa aka jefa ni cikin kurkuku? ");
INSERT INTO hausa_vpl VALUES ("JR37_19","025_37_19","JER","37","19","19","Ina annabawanka waɗanda suka yi maka annabci suna cewa, ‘Sarkin Babilon ba zai yaƙe ka ko wannan ƙasa ba’? ");
INSERT INTO hausa_vpl VALUES ("JR37_20","025_37_20","JER","37","20","20","Amma yanzu, ranka yă daɗe, sarkina, ka saurara. Bari in kawo kukata a gabanka. Kada ka mai da ni gidan Yonatan magatakarda, in ba haka zan mutu a can.” ");
INSERT INTO hausa_vpl VALUES ("JR37_21","025_37_21","JER","37","21","21","Sarki Zedekiya ya yi umarni a ajiye Irmiya a sansanin matsara a kuma ba shi burodi daga titin masu gashin burodi kowace rana sai duka burodi a birnin ya ƙare. Saboda haka Irmiya ya zauna a sansanin matsara. ");
INSERT INTO hausa_vpl VALUES ("JR38_1","025_38_1","JER","38","1","1","Shefatiya ɗan Mattan, Gedaliya ɗan Fashhur, Yukal ɗan Shelemiya da Fashhur ɗan Malkiya ya ji abin da Irmiya yana faɗa wa dukan mutane sa’ad da ya ce, ");
INSERT INTO hausa_vpl VALUES ("JR38_2","025_38_2","JER","38","2","2","“Ga abin da Ubangiji yana cewa, ‘Duk wanda ya zauna a wannan birni zai mutu ta takobi, yunwa ko annoba, amma duk wanda ya je wurin Babiloniyawa zai rayu. Zai tsira da ransa, ya rayu.’ ");
INSERT INTO hausa_vpl VALUES ("JR38_3","025_38_3","JER","38","3","3","Kuma ga abin da Ubangiji yana cewa, ‘Tabbatacce za a ba da wannan birni ga sojojin sarkin Babilon, wanda zai ci shi.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR38_4","025_38_4","JER","38","4","4","Sai fadawa suka ce wa sarki, “Ya kamata a kashe wannan mutum. Yana karya zuciyar sojojin da suka ragu a birnin, da zuciyar sauran mutane, ta wurin abubuwan da yake faɗa musu. Wannan mutum ba ya neman jin daɗin zaman wannan sai dai wahala.” ");
INSERT INTO hausa_vpl VALUES ("JR38_5","025_38_5","JER","38","5","5","“Yana a hannuwanku” Sarki Zedekiya ya amsa. “Sarki ba zai iya yin kome ya hana ku ba.” ");
INSERT INTO hausa_vpl VALUES ("JR38_6","025_38_6","JER","38","6","6","Saboda haka suka kama Irmiya suka sa a rijiyar da ba ruwa a ciki ta Malkiya, ɗan sarki, wadda take a sansanin matsara. Suka saukar da Irmiya cikin rijiyar da ba ruwa da igiya; babu ruwa a cikinta, sai laka, Irmiya ya nutse cikin laka. ");
INSERT INTO hausa_vpl VALUES ("JR38_7","025_38_7","JER","38","7","7","Amma Ebed-Melek mutumin Kush, wani hafsa a fada, ya ji cewa sun sa Irmiya a rijiyar da ba ruwa. Yayinda sarki yana zama a Ƙofar Benyamin, ");
INSERT INTO hausa_vpl VALUES ("JR38_8","025_38_8","JER","38","8","8","Ebed-Melek ya fita daga fadar ya ce masa, ");
INSERT INTO hausa_vpl VALUES ("JR38_9","025_38_9","JER","38","9","9","“Ranka yă daɗe sarki, waɗannan mutane sun yi mugun abu a duk abin da suka yi wa Irmiya annabi. Sun jefa shi cikin rijiyar da ba ruwa, inda zai mutu da yunwa gama ba sauran wani burodi a birnin.” ");
INSERT INTO hausa_vpl VALUES ("JR38_10","025_38_10","JER","38","10","10","Sai sarki ya umarce Ebed-Melek mutumin Kush, “Ka ɗauko mutane talatin daga nan ku fid da Irmiya annabi daga rijiyar kafin ya mutu.” ");
INSERT INTO hausa_vpl VALUES ("JR38_11","025_38_11","JER","38","11","11","Saboda haka Ebed-Melek ya ɗauki mutane tare da shi suka shiga ɗaki a ƙarƙashin baitulmali a cikin fada. Ya ɗauko waɗansu tsofaffin tsummoki da tsofaffi riguna daga can ya kuma zurara su da igiya wa Irmiya a cikin rijiyar. ");
INSERT INTO hausa_vpl VALUES ("JR38_12","025_38_12","JER","38","12","12","Ebed-Melek mutumin Kush ya ce wa Irmiya, “Ka sa waɗannan tsummoki da tsofaffin rigunan a hammatarka, ya zarga igiya.” Irmiya ya yi haka, ");
INSERT INTO hausa_vpl VALUES ("JR38_13","025_38_13","JER","38","13","13","suka kuma ja shi sama da igiya suka fid da shi daga rijiyar. Irmiya kuwa ya zauna a sansanin matsara. ");
INSERT INTO hausa_vpl VALUES ("JR38_14","025_38_14","JER","38","14","14","Sai Sarki Zedekiya ya aika a kawo Irmiya annabi, ya sa aka kawo shi a ƙofa ta uku ta haikalin Ubangiji. Sai sarki ya ce wa Irmiya, “Zan tambaye ka wani abu, kada ka ɓoye mini wani abu.” ");
INSERT INTO hausa_vpl VALUES ("JR38_15","025_38_15","JER","38","15","15","Irmiya ya ce wa Zedekiya, “In na ba ka amsa, ba za ka kashe ni ba? Ko da na ba ka shawara, ba za ka saurare ni ba.” ");
INSERT INTO hausa_vpl VALUES ("JR38_16","025_38_16","JER","38","16","16","Amma Sarki Zedekiya ya yi wannan rantsuwa a kaɗaice ga Irmiya cewa, “Muddin Ubangiji yana a raye, wanda ya ba mu numfashi, ba zan kashe ka ko in ba da kai ga waɗanda suke neman ranka ba.” ");
INSERT INTO hausa_vpl VALUES ("JR38_17","025_38_17","JER","38","17","17","Sa’an nan Irmiya ya ce wa Zedekiya, “Ga abin da Ubangiji Allah Maɗaukaki, Allah na Isra’ila, yana cewa, ‘In ka miƙa wuya ga hafsoshin sarkin Babilon, za a bar ka da rai ba za a kuma ƙone wannan birni ba; da kai da iyalinka za ku rayu. ");
INSERT INTO hausa_vpl VALUES ("JR38_18","025_38_18","JER","38","18","18","Amma in ba ka miƙa wuya ga hafsoshin sarkin Babilon ba, za a ba da wannan birni ga Babiloniyawa za su kuma cinna mata wuta; kai kanka ba za ka tsira daga hannuwansu ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR38_19","025_38_19","JER","38","19","19","Sarki Zedekiya ya ce wa Irmiya, “Ina jin tsoron Yahudawan da suka tafi wurin Babiloniyawa, gama Babiloniyawa mai yiwuwa su ba da ni gare su su kuma wulaƙanta ni.” ");
INSERT INTO hausa_vpl VALUES ("JR38_20","025_38_20","JER","38","20","20","Irmiya ya ce, “Ba za su ba da kai ba, ka yi biyayya ga Ubangiji ta wurin yin abin da na faɗa maka. Ta haka zai zama maka da amfani, za ka kuwa rayu. ");
INSERT INTO hausa_vpl VALUES ("JR38_21","025_38_21","JER","38","21","21","Amma in ka ƙi miƙa wuya, ga abin da Ubangiji ya bayyana mini. ");
INSERT INTO hausa_vpl VALUES ("JR38_22","025_38_22","JER","38","22","22","Za a fitar da dukan matan da suka ragu a fadan sarkin Yahuda wa hafsoshin sarkin Babilon. Waɗannan mata za su ce maka, “ ‘Sun ruɗe ka suka kuma rinjaye ka, waɗannan abokanka. Ƙafafunka sun nutse a cikin laka; abokanka sun yashe ka.’ ");
INSERT INTO hausa_vpl VALUES ("JR38_23","025_38_23","JER","38","23","23","“Za a kawo dukan matanka da ’ya’yanka wa Babiloniyawa. Kai kanka ba za ka tsira daga hannuwansu ba amma za su sa sarkin Babilon zai kama ka; za a kuma ƙone wannan birni.” ");
INSERT INTO hausa_vpl VALUES ("JR38_24","025_38_24","JER","38","24","24","Sai Zedekiya ya ce wa Irmiya, “Kada ka bar wani ya san wannan zance, in ba haka ba za ka mutu. ");
INSERT INTO hausa_vpl VALUES ("JR38_25","025_38_25","JER","38","25","25","In fadawa suka ji cewa na yi magana da kai, suka kuma zo wurinka suka ce, ‘Faɗa mana abin da ka faɗa wa sarki da kuma abin da sarki ya faɗa maka; kada ka ɓoye mana, in ba haka za mu kashe ka,’ ");
INSERT INTO hausa_vpl VALUES ("JR38_26","025_38_26","JER","38","26","26","sai ka ce musu cewa, ‘Na roƙi sarki kada yă mai da ni gidan Yonatan in mutu a can.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR38_27","025_38_27","JER","38","27","27","Dukan fadawa kuwa suka zo wurin Irmiya suka tambaye shi, ya kuma faɗa musu dukan abin da sarki ya umarce shi ya faɗa. Saboda haka ba su ƙara ce masa kome ba, gama ba wanda ya ji zance da suka yi da sarki. ");
INSERT INTO hausa_vpl VALUES ("JR38_28","025_38_28","JER","38","28","28","Irmiya kuwa ya zauna a sansanin masu gadi har ranar da aka ci Urushalima da yaƙi. Ga yadda aka ci Urushalima, ");
INSERT INTO hausa_vpl VALUES ("JR39_1","025_39_1","JER","39","1","1","A shekara ta tara ta Zedekiya sarkin Yahuda, a wata na goma, Nebukadnezzar sarkin Babilon ya fita yaƙi da Urushalima da dukan sojojinsa ya kuma yi mata ƙawanya. ");
INSERT INTO hausa_vpl VALUES ("JR39_2","025_39_2","JER","39","2","2","A rana ta tara ga watan huɗu a shekara ta goma sha ɗaya ta mulkin Zedekiya, sai aka huda katanga. ");
INSERT INTO hausa_vpl VALUES ("JR39_3","025_39_3","JER","39","3","3","Sa’an nan dukan fadawan sarkin Babilon suka shiga suka zazzauna a Ƙofar Tsakiya. Wato, Nergal-Sharezer na Samgar-Nebo, Sarsekim wani babban hafsa, Nergal-Sharezer bafade mai girma da dukan sauran fadawan sarkin Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR39_4","025_39_4","JER","39","4","4","Sa’ad da Zedekiya sarkin Yahuda da dukan sojoji suka gan su, sai suka gudu; suka bar birnin da dare ta hanyar lambun sarki, ta ƙofar da take tsakanin katanga biyu, suka nufi waje Araba. ");
INSERT INTO hausa_vpl VALUES ("JR39_5","025_39_5","JER","39","5","5","Amma sojojin Babiloniyawa suka bi su, suka ci wa Zedekiya a filayen Yeriko. Suka kama shi suka kai shi wurin Nebukadnezzar a Ribla a ƙasar Hamat, inda aka yanke masa hukunci. ");
INSERT INTO hausa_vpl VALUES ("JR39_6","025_39_6","JER","39","6","6","A can Ribla sarkin Babilon ya kashe ’ya’yan Zedekiya a idanunsa aka kuma kashe dukan manyan mutanen Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR39_7","025_39_7","JER","39","7","7","Sa’an nan ya ƙwaƙule idanun Zedekiya ya kuma buga masa ƙuƙumi, ya kai shi Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR39_8","025_39_8","JER","39","8","8","Sai Babiloniyawa suka cinna wa fadar da kuma gidajen mutane wuta suka farfasa katangar Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR39_9","025_39_9","JER","39","9","9","Nebuzaradan shugaban matsaran sarki ya kwashi mutanen da suka rage a birnin zuwa zaman bauta a Babilon, tare da waɗanda suka riga suka tafi wurinsa, da kuma sauran mutanen. ");
INSERT INTO hausa_vpl VALUES ("JR39_10","025_39_10","JER","39","10","10","Amma Nebuzaradan shugaban matsaran ya bar waɗansu matalauta a ƙasar Yahuda, su da ba su da kome; a lokacin kuwa ya ba su gonakin inabi da kuma filaye. ");
INSERT INTO hausa_vpl VALUES ("JR39_11","025_39_11","JER","39","11","11","To, fa, Nebukadnezzar sarkin Babilon ya ba da wannan umarnai game da Irmiya ta wurin Nebuzaradan shugaban matsaran sarki cewa, ");
INSERT INTO hausa_vpl VALUES ("JR39_12","025_39_12","JER","39","12","12","“Ka ɗauke shi ka lura da shi da kyau, kada ka yi masa wani mugun abu, amma ka yi masa dukan abin da yake so.” ");
INSERT INTO hausa_vpl VALUES ("JR39_13","025_39_13","JER","39","13","13","Saboda haka Nebuzaradan shugaban matsara, Nebushazban babban hafsa, Nergal-Sharezer bafade mai girma da sauran hafsoshin sarkin Babilon ");
INSERT INTO hausa_vpl VALUES ("JR39_14","025_39_14","JER","39","14","14","suka aika aka kawo Irmiya daga filin matsar. Suka miƙa shi ga Gedaliya ɗan Ahikam, ɗan Shafan, don yă kai shi gidansa. Saboda haka ya zauna a can a cikin mutanensa. ");
INSERT INTO hausa_vpl VALUES ("JR39_15","025_39_15","JER","39","15","15","Yayinda aka kulle Irmiya a sansanin matsara, maganar Ubangiji ta zo masa cewa, ");
INSERT INTO hausa_vpl VALUES ("JR39_16","025_39_16","JER","39","16","16","“Tafi ka faɗa wa Ebed-Melek mutumin Kush, ‘Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa ina gab da cika maganata a kan wannan birni ta wurin masifa, ba wadata ba. A lokacin za tă cika a idanunka. ");
INSERT INTO hausa_vpl VALUES ("JR39_17","025_39_17","JER","39","17","17","Amma zan kuɓutar da kai a wannan rana, in ji Ubangiji; ba zan ba da kai ga waɗanda kake tsoronsu ba. ");
INSERT INTO hausa_vpl VALUES ("JR39_18","025_39_18","JER","39","18","18","Zan cece ka; ba za ka mutu ta wurin takobi ba amma za ka tsira da ranka, domin ka dogara gare ni, in ji Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR40_1","025_40_1","JER","40","1","1","Sai magana ta zo wa Irmiya daga Ubangiji bayan Nebuzaradan shugaban matsaran sarki ya sake shi a Rama. Ya sami Irmiya a daure da sarƙoƙi a cikin sauran kamammu daga Urushalima da kuma Yahuda waɗanda ake kaiwa zaman bauta a Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR40_2","025_40_2","JER","40","2","2","Sa’ad da shugaban matsaran ya sami Irmiya sai ya ce masa, “Ubangiji Allahnka ya sa wannan masifa saboda wannan wuri. ");
INSERT INTO hausa_vpl VALUES ("JR40_3","025_40_3","JER","40","3","3","Yanzu kuma Ubangiji ya cika shi; ya yi kamar yadda ya faɗa. Dukan wannan ya faru domin kun yi zunubi ga Ubangiji ba ku kuwa yi masa biyayya ba. ");
INSERT INTO hausa_vpl VALUES ("JR40_4","025_40_4","JER","40","4","4","Amma yau ina ’yantar da kai daga sarƙoƙin da suke a hannuwanka. Zo mu tafi Babilon, in kana so, zan kuwa lura da kai; amma in ba ka so, kada ka zo. Ga shi, dukan ƙasar tana a gabanka; ka tafi duk inda ka so.” ");
INSERT INTO hausa_vpl VALUES ("JR40_5","025_40_5","JER","40","5","5","Amma, kafin Irmiya yă juya yă tafi, Nebuzaradan ya ƙara da cewa, “Ka koma wurin Gedaliya ɗan Ahikam, ɗan Shafan, wanda sarkin Babilon ya naɗa a kan garuruwan Yahuda, ka zauna da shi a cikin mutane, ko kuwa ka tafi duk inda ka ga dama.” Sa’an nan shugaban ya ba shi abinci da kuma kyauta sai ya bar shi ya tafi. ");
INSERT INTO hausa_vpl VALUES ("JR40_6","025_40_6","JER","40","6","6","Saboda haka Irmiya ya tafi wurin Gedaliya ɗan Ahikam, a Mizfa ya zauna tare da shi a cikin mutanen da aka bari a ƙasar. ");
INSERT INTO hausa_vpl VALUES ("JR40_7","025_40_7","JER","40","7","7","Sa’ad da dukan shugabannin hafsoshin tare da mutanen da suke a karkara suka ji cewa sarkin Babilon ya naɗa Gedaliya ɗan Ahikam gwamna a kan ƙasar ya kuma sa shi ya lura da maza, mata da ’ya’yan da suke mafi talauci a ƙasar da waɗanda ba a kwashe zuwa zaman bauta a Babilon ba, ");
INSERT INTO hausa_vpl VALUES ("JR40_8","025_40_8","JER","40","8","8","sai suka zo wurin Gedaliya a Mizfa, Ishmayel ɗan Netaniya, Yohanan da Yonatan ’ya’yan Kareya, da Serahiya ɗan Tanhumet maza, ’ya’yan Efai maza, mutumin Netofa, da Yezaniya ɗan mutumin Ma’aka da mutanensu. ");
INSERT INTO hausa_vpl VALUES ("JR40_9","025_40_9","JER","40","9","9","Gedaliya ɗan Ahikam, ɗan Shafan, ya yi rantsuwa don yă tabbatar musu da mutanensu. Ya ce, “Kada ku ji tsoron bauta wa Babiloniyawa. Ku zauna a ƙasar ku bauta wa sarkin Babilon, zai kuma yi muku amfani. ");
INSERT INTO hausa_vpl VALUES ("JR40_10","025_40_10","JER","40","10","10","Ni kaina zan zauna a Mizfa in zama wakilinku a gaban Babiloniyawa waɗanda za su zo wurinmu, amma ku girbe ruwan inabi, ’ya’yan itatuwa na kaka, da mai, ku zuba su a tulunan ajiyarku, ku kuma zauna a garuruwan da kuka ci.” ");
INSERT INTO hausa_vpl VALUES ("JR40_11","025_40_11","JER","40","11","11","Sa’ad da dukan Yahudawan da suke a Mowab, Ammon, Edom da sauran ƙasashe suka ji cewa sarkin Babilon ya bar raguwa a Yahuda ya kuma naɗa Gedaliya ɗan Ahikam, ɗan Shafan gwamna a kansu, ");
INSERT INTO hausa_vpl VALUES ("JR40_12","025_40_12","JER","40","12","12","sai suka dawo ƙasar Yahuda, wurin Gedaliya a Mizfa, daga dukan ƙasashen da suke a warwatse. Suka girbe ruwan inabi a yalwace da ’ya’yan itatuwan kaka. ");
INSERT INTO hausa_vpl VALUES ("JR40_13","025_40_13","JER","40","13","13","Yohanan ɗan Kareya da dukan manyan sojoji da suke a karkara suka zo wurin Gedaliya a Mizfa ");
INSERT INTO hausa_vpl VALUES ("JR40_14","025_40_14","JER","40","14","14","suka ce masa, “Ba ka san cewa Ba’alis sarkin Ammonawa ya aiki Ishmayel ɗan Netaniya ya ɗauke ranka ba?” Amma Gedaliya ɗan Ahikam bai gaskata su ba. ");
INSERT INTO hausa_vpl VALUES ("JR40_15","025_40_15","JER","40","15","15","Sai Yohanan ɗan Kareya ya yi wa Gedaliya a Mizfa magana a asirce ya ce, “Bari in tafi in kashe Ishmayel ɗan Netaniya, ba kuwa wanda zai sani. Me zai sa ya ɗauke ranka ya watsar da dukan Yahudawan da suka taru kewaye da kai har waɗanda suka ragu na Yahuda su hallaka?” ");
INSERT INTO hausa_vpl VALUES ("JR40_16","025_40_16","JER","40","16","16","Amma Gedaliya ɗan Ahikam ya ce wa Yohanan ɗan Kareya, “Kada ka yi irin wannan abu! Abin da kake faɗa game da Ishmayel ba gaskiya ba ne.” ");
INSERT INTO hausa_vpl VALUES ("JR41_1","025_41_1","JER","41","1","1","A wata na goma sha bakwai sai Ishmayel ɗan Netaniya, ɗan Elishama, wanda yake mai jinin sarauta yake kuma ɗaya daga cikin hafsoshin sarki, ya zo tare da mutum goma wurin Gedaliya ɗan Ahikam a Mizfa. Yayinda suke ci tare a can, ");
INSERT INTO hausa_vpl VALUES ("JR41_2","025_41_2","JER","41","2","2","sai Ishmayel ɗan Netaniya da mutum goma waɗanda suke tare da shi suka kashe Gedaliya ɗan Ahikam, ɗan Shafan, da takobi, suka kashe wannan da sarkin Babilon ya naɗa a matsayin gwamna a kan ƙasar. ");
INSERT INTO hausa_vpl VALUES ("JR41_3","025_41_3","JER","41","3","3","Ishmayel ya kuma kashe dukan Yahudawan da suke tare da Gedaliya a Mizfa, haka ma ya yi da sojojin Babiloniyawan da suke can. ");
INSERT INTO hausa_vpl VALUES ("JR41_4","025_41_4","JER","41","4","4","Kashegari bayan an kashe Gedaliya, kafin wani ya san abin da ya faru, ");
INSERT INTO hausa_vpl VALUES ("JR41_5","025_41_5","JER","41","5","5","sai ga mutane tamanin daga Shekem, Shilo da Samariya suka zo da gemunsu a aske, da tufafinsu a kece, da jikunansu a tsage, suka kawo hadayun gari da turare tare da su a gidan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR41_6","025_41_6","JER","41","6","6","Ishmayel ɗan Netaniya ya fito daga Mizfa don yă sadu da su. Sa’ad da ya sadu da su, sai ya ce, “Ku zo wurin Gedaliya ɗan Ahikam.” ");
INSERT INTO hausa_vpl VALUES ("JR41_7","025_41_7","JER","41","7","7","Da suka shiga cikin birni, sai Ishmayel ɗan Netaniya da mutanen da suke tare da shi suka karkashe su suka zubar a rijiya. ");
INSERT INTO hausa_vpl VALUES ("JR41_8","025_41_8","JER","41","8","8","Amma goma daga cikinsu suka ce wa Ishmayel, “Kada ka kashe mu, muna da alkama da sha’ir, mai da kuma zuma, a ɓoye a gona.” Saboda haka ka bar mu kada ka kashe mu tare da sauran. ");
INSERT INTO hausa_vpl VALUES ("JR41_9","025_41_9","JER","41","9","9","To, rijiyar da ya zubar da gawawwakin mutanen da ya kashe tare da ta Gedaliya ita ce wadda Sarki Asa ya haƙa a matsayin kāriya saboda Ba’asha sarkin Isra’ila. Ishmayel ɗan Netaniya ya cika ta da gawawwaki. ");
INSERT INTO hausa_vpl VALUES ("JR41_10","025_41_10","JER","41","10","10","Ishmayel ya mai da dukan sauran mutanen da suke Mizfa bayi ’ya’yan sarki mata tare da dukan sauran da aka bari a can, waɗanda Nebuzaradan shugaban matsaran sarki ya bari a hannun Gedaliya ɗan Ahikam. Ishmayel ɗan Netaniya ya kwashe su ganima, ya tashi don yă haye zuwa wurin Ammonawa. ");
INSERT INTO hausa_vpl VALUES ("JR41_11","025_41_11","JER","41","11","11","Sa’ad da Yohanan ɗan Kareya da dukan shugabannin sojojin da suke tare da shi suka ji dukan laifofin da Ishmayel ɗan Netaniya ya aikata, ");
INSERT INTO hausa_vpl VALUES ("JR41_12","025_41_12","JER","41","12","12","sai suka kwashe dukan mutanensu suka tafi don su yaƙi Ishmayel ɗan Netaniya. Suka iske shi kusa da babban tafki a Gibeyon. ");
INSERT INTO hausa_vpl VALUES ("JR41_13","025_41_13","JER","41","13","13","Sa’ad da dukan mutanen da suke tare da Ishmayel suka ga Yohanan ɗan Kareya da shugabannin sojojin da suke tare da shi, sai suka yi farin ciki. ");
INSERT INTO hausa_vpl VALUES ("JR41_14","025_41_14","JER","41","14","14","Dukan mutanen da Ishmayel ya kame a Mizfa suka juya, suka tafi wurin Yohanan ɗan Kareya. ");
INSERT INTO hausa_vpl VALUES ("JR41_15","025_41_15","JER","41","15","15","Amma Ishmayel ɗan Netaniya da mutanensa takwas suka tsere daga Yohanan suka gudu zuwa wurin Ammonawa. ");
INSERT INTO hausa_vpl VALUES ("JR41_16","025_41_16","JER","41","16","16","Sai Yohanan ɗan Kareya da dukan shugabannin sojojin da suke tare da shi suka bi da dukan waɗanda suka tsira daga Mizfa waɗanda ya karɓe daga Ishmayel ɗan Netaniya bayan ya kashe Gedaliya ɗan Ahikam, wato, sojoji, mata, yara da fadawan da ya kawo daga Gibeyon ");
INSERT INTO hausa_vpl VALUES ("JR41_17","025_41_17","JER","41","17","17","Sai suka ci gaba, suka dakata a Gerut Kimham kusa da Betlehem a kan hanyarsu zuwa Masar ");
INSERT INTO hausa_vpl VALUES ("JR41_18","025_41_18","JER","41","18","18","don su kuɓuce wa Babiloniyawa. Sun ji tsoronsu domin Ishmayel ɗan Netaniya ya kashe Gedaliya ɗan Ahikam, wanda sarkin Babilon ya naɗa gwamna a kan ƙasar. ");
INSERT INTO hausa_vpl VALUES ("JR42_1","025_42_1","JER","42","1","1","Sa’an nan dukan shugabannin sojoji, haɗe da Yohanan ɗan Kareya da Yezaniya ɗan Hoshahiya, da dukan mutane daga ƙarami zuwa babba, suka zo wurin ");
INSERT INTO hausa_vpl VALUES ("JR42_2","025_42_2","JER","42","2","2","Irmiya annabi suka ce masa, “Muna roƙonka ka ji kukanmu ka kuma yi addu’a ga Ubangiji Allahnka saboda dukan wannan raguwar mutane. Gama kamar yadda kake gani yanzu, ko da yake dā muna da yawa, yanzu ɗan kaɗan muka rage. ");
INSERT INTO hausa_vpl VALUES ("JR42_3","025_42_3","JER","42","3","3","Ka yi addu’a cewa Ubangiji Allahnka zai faɗa mana inda za mu tafi da kuma abin da za mu yi.” ");
INSERT INTO hausa_vpl VALUES ("JR42_4","025_42_4","JER","42","4","4","Sai Irmiya ya amsa ya ce, “Na ji ku, tabbatacce zan yi addu’a ga Ubangiji Allahnku yadda kuka roƙa; zan faɗa muku duk abin da Ubangiji ya faɗa ba kuwa zan ɓoye muku kome ba.” ");
INSERT INTO hausa_vpl VALUES ("JR42_5","025_42_5","JER","42","5","5","Sa’an nan suka ce wa Irmiya, “Ubangiji ya zama shaida na gaskiya da kuma aminci a kanmu in ba mu yi bisa da duk abin da Ubangiji Allahnka ya aike ka ka faɗa mana ba. ");
INSERT INTO hausa_vpl VALUES ("JR42_6","025_42_6","JER","42","6","6","Ko ya gamshe mu ko bai gamshe mu ba, za mu yi biyayya da Ubangiji Allahnmu, ga wanda muke aikan ka, saboda ya zama mana da amfani, gama za mu yi biyayya da Ubangiji Allahnmu.” ");
INSERT INTO hausa_vpl VALUES ("JR42_7","025_42_7","JER","42","7","7","Bayan kwana goma sai maganar Ubangiji ta zo wa Irmiya. ");
INSERT INTO hausa_vpl VALUES ("JR42_8","025_42_8","JER","42","8","8","Saboda haka ya kira Yohanan ɗan Kareya da dukan shugabannin sojoji waɗanda suke tare da shi da dukan jama’a daga ƙarami zuwa babba. ");
INSERT INTO hausa_vpl VALUES ("JR42_9","025_42_9","JER","42","9","9","Ya ce musu, “Ga abin da Ubangiji, Allah na Isra’ila, wanda kuka aike ni gare shi don in gabatar da kukanku, yana cewa, ");
INSERT INTO hausa_vpl VALUES ("JR42_10","025_42_10","JER","42","10","10","‘In kuka zauna a wannan ƙasa, zan gina ku ba zan kuwa rushe ku ba; zan dasa ku ba kuwa zan tumɓuke ku ba, gama ina baƙin ciki a kan masifar da na aukar a kanku. ");
INSERT INTO hausa_vpl VALUES ("JR42_11","025_42_11","JER","42","11","11","Kada ku ji tsoron sarkin Babilon, wanda kuke tsoro a yanzu. Kada ku ji tsoronsa, in ji Ubangiji, gama ina tare da ku zan kuma cece ku daga hannuwansa. ");
INSERT INTO hausa_vpl VALUES ("JR42_12","025_42_12","JER","42","12","12","Zan nuna muku jinƙai don yă nuna muku jinƙai ya kuma maido da ku ƙasarku.’ ");
INSERT INTO hausa_vpl VALUES ("JR42_13","025_42_13","JER","42","13","13","“Amma fa, in kuka ce, ‘Ba za mu zauna a wannan ƙasa ba,’ ta haka kuka kuma nuna rashin biyayya ga Ubangiji Allahnku, ");
INSERT INTO hausa_vpl VALUES ("JR42_14","025_42_14","JER","42","14","14","in kuma kuka ce, ‘A’a, za mu tafi mu zauna a Masar, inda ba za mu ga yaƙi ko mu ji ƙarar ƙaho ko mu ji yunwa ba,’ ");
INSERT INTO hausa_vpl VALUES ("JR42_15","025_42_15","JER","42","15","15","to, ku ji maganar Ubangiji, ya raguwar Yahuda. Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa, ‘In kun ƙudura ku tafi Masar kuka kuma tafi kun zauna a can, ");
INSERT INTO hausa_vpl VALUES ("JR42_16","025_42_16","JER","42","16","16","takobin da kuke tsoro zai same ku a can, kuma yunwar da kuke tsoro za tă bi ku zuwa Masar, a can kuwa za ku mutu. ");
INSERT INTO hausa_vpl VALUES ("JR42_17","025_42_17","JER","42","17","17","Tabbatacce, duk waɗanda suka ƙudura suka tafi Masar su zauna a can za su mutu ta wurin takobi, yunwa da annoba; ba ko ɗayansu zai tsira ko ya kuɓuta wa masifar da zan aukar a kansu.’ ");
INSERT INTO hausa_vpl VALUES ("JR42_18","025_42_18","JER","42","18","18","Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa, ‘Kamar yadda na kwararo fushina da hasalata a kan mazaunan Urushalima, haka kuma zan kwararo fushina a kanku sa’ad da kuka tafi Masar. Za ku zama abin la’ana da abin tsoro, abin ƙyama da abin ba’a; ba za ku ƙara ganin wannan wuri ba.’ ");
INSERT INTO hausa_vpl VALUES ("JR42_19","025_42_19","JER","42","19","19","“Ya ku raguwar Yahuda, Ubangiji ya ce muku, ‘Kada ku je Masar.’ Ku tabbatar da wannan. Na gargaɗe ku yau ");
INSERT INTO hausa_vpl VALUES ("JR42_20","025_42_20","JER","42","20","20","cewa in kun yi kuskure sa’ad da kuka aike ni wurin Ubangiji Allahnku kuka kuma ce, ‘Yi mana addu’a ga Ubangiji Allahnmu; ka faɗa mana duk abin da ya faɗa za mu kuwa aikata.’ ");
INSERT INTO hausa_vpl VALUES ("JR42_21","025_42_21","JER","42","21","21","Na faɗa muku yau, amma har yanzu ba ku yi biyayya ga Ubangiji Allahnku cikin dukan abin da ya aiko ni in faɗa muku ba. ");
INSERT INTO hausa_vpl VALUES ("JR42_22","025_42_22","JER","42","22","22","Saboda haka yanzu, ku tabbatar da wannan. Za ku mutu ta wurin takobi, yunwa da annoba a wurin da kuke so ku tafi ku zauna.” ");
INSERT INTO hausa_vpl VALUES ("JR43_1","025_43_1","JER","43","1","1","Sa’ad da Irmiya ya gama faɗa wa mutane dukan maganar Ubangiji Allahnsu, duk abin da Ubangiji ya aike shi ya faɗa musu, ");
INSERT INTO hausa_vpl VALUES ("JR43_2","025_43_2","JER","43","2","2","Azariya ɗan Hoshahiya da Yohanan ɗan Kareya da dukan masu ɗaga kai suka ce wa Irmiya, “Kana ƙarya ne! Ubangiji Allahnmu bai aike ka ka ce, ‘Kada ku tafi Masar don ku zauna a can.’ ");
INSERT INTO hausa_vpl VALUES ("JR43_3","025_43_3","JER","43","3","3","Amma Baruk ɗan Neriya yana zuga ka a kanmu don ka ba da mu ga Babiloniyawa, don su kashe mu ko su kai mu zaman bauta a Babilon.” ");
INSERT INTO hausa_vpl VALUES ("JR43_4","025_43_4","JER","43","4","4","Saboda haka Yohanan ɗan Kareya da dukan shugabannin sojoji da dukan mutane suka yi rashin biyayya ga umarnin Ubangiji da su zauna a ƙasar Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR43_5","025_43_5","JER","43","5","5","A maimako, Yohanan ɗan Kareya da dukan shugabannin sojoji suka kwashe raguwar Yahuda waɗanda suka dawo su zauna a ƙasar Yahuda daga dukan al’umman inda aka kora su. ");
INSERT INTO hausa_vpl VALUES ("JR43_6","025_43_6","JER","43","6","6","Suka kuma kwashe dukan maza, mata da yara da ’ya’yan sarki mata waɗanda Nebuzaradan shugaban matsaran sarki ya bari tare da Gedaliya ɗan Ahikam, ɗan Shafan, da Irmiya annabi da kuma Baruk ɗan Neriya. ");
INSERT INTO hausa_vpl VALUES ("JR43_7","025_43_7","JER","43","7","7","Saboda haka suka shiga Masar cikin rashin biyayya ga Ubangiji suka tafi har can Tafanes. ");
INSERT INTO hausa_vpl VALUES ("JR43_8","025_43_8","JER","43","8","8","A Tafanes maganar Ubangiji ta zo wa Irmiya cewa, ");
INSERT INTO hausa_vpl VALUES ("JR43_9","025_43_9","JER","43","9","9","“Yayinda Yahudawa suna kallo, ka ɗauki waɗansu manyan duwatsu tare da kai ka kuma binne su cikin yumɓu a tubalin dakalin ƙofar shiga fadar Fir’auna a Tafanes. ");
INSERT INTO hausa_vpl VALUES ("JR43_10","025_43_10","JER","43","10","10","Sa’an nan ka faɗa musu cewa, ‘Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa, zan aika wa bawana Nebukadnezzar sarkin Babilon, zan kuma sa kursiyinsa a kan waɗannan duwatsun da na binne a nan; zai fadada bukkar mulkinsa a bisansu. ");
INSERT INTO hausa_vpl VALUES ("JR43_11","025_43_11","JER","43","11","11","Zai zo ya yaƙi Masar, ya kawo mutuwa ga waɗanda aka ƙaddara musu mutuwa, zaman bauta ga waɗanda aka ƙaddara musu zaman bauta, da kuma takobi ga waɗanda aka ƙaddara su mutu ta takobi. ");
INSERT INTO hausa_vpl VALUES ("JR43_12","025_43_12","JER","43","12","12","Zai sa wuta wa haikalan allolin Masar; zai ƙone haikalansu yă kuma kwashe allolinsu bayi. Kamar yadda makiyayi yakan yafa mayafinsa kewaye da shi, haka zai yafa Masar kewaye da kansa ya kuma tashi a wurin babu abin da ya same shi. ");
INSERT INTO hausa_vpl VALUES ("JR43_13","025_43_13","JER","43","13","13","A can cikin haikalin rana a Masar zai rushe al’amudan duwatsu yă kuma ƙone haikalan allolin Masar.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR44_1","025_44_1","JER","44","1","1","Wannan maganata zo wa Irmiya game da dukan Yahudawa masu zama a Masar ta Ƙasa, a Migdol, Tafanes da Memfis, da kuma a Masar ta Bisa. ");
INSERT INTO hausa_vpl VALUES ("JR44_2","025_44_2","JER","44","2","2","“Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila yana cewa kun ga masifa mai girmar da na kawo a kan Urushalima da kuma a kan dukan garuruwan Yahuda. A yau sun zama hamada da kuma kango ");
INSERT INTO hausa_vpl VALUES ("JR44_3","025_44_3","JER","44","3","3","saboda muguntar da suka aikata. Sun tsokane ni na yi fushi ta wurin ƙone turare da kuma ta wurin bauta wa waɗansu allolin da su ko ku ko kakanninku ba su taɓa sani ba. ");
INSERT INTO hausa_vpl VALUES ("JR44_4","025_44_4","JER","44","4","4","Sau da sau na aiki bayina annabawa, waɗanda suka ce, ‘Kada ku yi wannan abin ƙyama da na ƙi!’ ");
INSERT INTO hausa_vpl VALUES ("JR44_5","025_44_5","JER","44","5","5","Amma ba su saurara ko su kasa kunne ba; ba su juye daga muguntarsu ko su daina ƙone turare wa waɗansu alloli ba. ");
INSERT INTO hausa_vpl VALUES ("JR44_6","025_44_6","JER","44","6","6","Saboda haka, fushina mai ƙuna ya fāɗo a kan garuruwan Yahuda da kuma titunan Urushalima na kuma mai da su kufai da suke a yau. ");
INSERT INTO hausa_vpl VALUES ("JR44_7","025_44_7","JER","44","7","7","“To, ga abin da Ubangiji Allah Maɗaukaki, Allah na Isra’ila, yana cewa don me kuka kawo irin masifa mai girma haka a kanku ta wurin warewa daga Yahuda maza da mata, yara da jarirai, kun kuma bar kanku babu raguwa? ");
INSERT INTO hausa_vpl VALUES ("JR44_8","025_44_8","JER","44","8","8","Me ya sa kuka tsokane ni in yi fushi saboda abin da hannuwanku suka yi, kuna ƙone turare wa waɗansu alloli a Masar, inda kuka zo don ku zauna? Za ku hallakar da kanku ku kuma mai da kanku abin la’ana da abin zargi da abin ba’a a cikin dukan al’umman duniya. ");
INSERT INTO hausa_vpl VALUES ("JR44_9","025_44_9","JER","44","9","9","Kun manta mugayen ayyukan kakanninku, da na sarakuna da sarauniyoyin Yahuda da mugayen ayyukanku, da na matanku a cikin Yahuda da kan titunan Urushalima? ");
INSERT INTO hausa_vpl VALUES ("JR44_10","025_44_10","JER","44","10","10","Har yă zuwa yau ba su ƙasƙantar da kansu ko su nuna bangirma, ko su kiyaye dokata da ƙa’idodin da na sa a gabanku da kakanninku ba. ");
INSERT INTO hausa_vpl VALUES ("JR44_11","025_44_11","JER","44","11","11","“Saboda haka ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa na ƙudura in aukar muku da masifa in kuma hallaka dukan Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR44_12","025_44_12","JER","44","12","12","Zan ɗauke raguwar Yahuda waɗanda suka ƙudurta su je Masar su zauna a can. Duk za su hallaka a Masar; za su mutu ta wurin takobi ko su mutu da yunwa. Daga ƙarami zuwa babba, za su mutu ta wurin takobi ko yunwa. Za su zama abin zarge da abin tsoro, abin la’ana da abin ba’a. ");
INSERT INTO hausa_vpl VALUES ("JR44_13","025_44_13","JER","44","13","13","Zan hukunta waɗanda suke zama a Masar da takobi, yunwa da annoba, yadda na hukunta Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR44_14","025_44_14","JER","44","14","14","Babu wani daga raguwar Yahuda wanda ya tafi Masar da zai kuɓuta ko ya tsira har ya komo zuwa ƙasar Yahuda, wadda za su yi marmari su komo su zauna; babu wani da zai komo sai dai ’yan gudun hijira.” ");
INSERT INTO hausa_vpl VALUES ("JR44_15","025_44_15","JER","44","15","15","Sai dukan mazan da suka san cewa matansu suna ƙone turare wa waɗansu alloli, tare da dukan matan da suke a nan babban taro, da kuma dukan mutanen da suke zama a Masar ta Ƙasa da ta Bisa, suka ce wa Irmiya, ");
INSERT INTO hausa_vpl VALUES ("JR44_16","025_44_16","JER","44","16","16","“Ba za mu saurari saƙon da ka yi mana magana a sunan Ubangiji ba! ");
INSERT INTO hausa_vpl VALUES ("JR44_17","025_44_17","JER","44","17","17","Lalle za mu aikata duk abin da muka ce za mu yi. Za mu ƙone turare ga Sarauniyar Sama za mu kuma miƙa hadayun sha gare ta kamar dai yadda mu da kakanninmu, sarakunanmu da fadawanmu muka yi a garuruwan Yahuda da kuma kan titunan Urushalima. A lokacin muna da abinci a yalwace muna kuma da arziki ba mu kuma da wata damuwa. ");
INSERT INTO hausa_vpl VALUES ("JR44_18","025_44_18","JER","44","18","18","Amma tun da muka daina ƙone turare ga Sarauniyar Sama da kuma miƙa mata hadayun sha, muka rasa kome muna ta mutuwa ta wurin takobi da yunwa.” ");
INSERT INTO hausa_vpl VALUES ("JR44_19","025_44_19","JER","44","19","19","Matan suka ƙara da cewa, “Sa’ad da muka ƙone turare ga Sarauniyar Sama muka kuma miƙa mata hadayun sha, mazanmu ba su san muna yin waina kamar siffarta muna kuma miƙa mata hadayun sha ba?” ");
INSERT INTO hausa_vpl VALUES ("JR44_20","025_44_20","JER","44","20","20","Sai Irmiya ya ce wa dukan mutanen, maza da mata, waɗanda suke ba shi amsa, ");
INSERT INTO hausa_vpl VALUES ("JR44_21","025_44_21","JER","44","21","21","“Ubangiji bai tuna ya kuma yi tunani game da turaren da aka ƙone a garuruwan Yahuda da kan titunan Urushalima wanda ku da kakanninku, sarakunanku da fadawanku da mutanen ƙasar ba ne? ");
INSERT INTO hausa_vpl VALUES ("JR44_22","025_44_22","JER","44","22","22","Sa’ad da Ubangiji bai iya jurewa da mugayen ayyukanku da kuma abubuwa banƙyama da kuka aikata ba, sai ƙasarku ta zama abin la’ana da kufai babu mazauna yadda yake a yau. ");
INSERT INTO hausa_vpl VALUES ("JR44_23","025_44_23","JER","44","23","23","Domin kun ƙone turare kuka kuma yi wa Ubangiji zunubi ba ku kuma yi masa biyayya ko ku kiyaye dokarsa ko ƙa’idodinsa ko farillansa ba, wannan masifa ta aukar muku, yadda yanzu kuka gani.” ");
INSERT INTO hausa_vpl VALUES ("JR44_24","025_44_24","JER","44","24","24","Sai Irmiya ya ce wa dukan mutane, har da mata, “Ku saurari maganar Ubangiji, dukanku mutanen Yahuda a Masar. ");
INSERT INTO hausa_vpl VALUES ("JR44_25","025_44_25","JER","44","25","25","Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa ku da matanku kun nuna ta wurin ayyukanku abin da kuka yi alkawari sa’ad da kuka ce, ‘Lalle za mu yi abin da muka yi alkawari na ƙone turare da kuma miƙa hadayun sha ga Sarauniyar Sama.’ “To, sai ku ci gaba, ku aikata abin da kuka yi alkawari! Ku cika alkawarinku! ");
INSERT INTO hausa_vpl VALUES ("JR44_26","025_44_26","JER","44","26","26","Amma ku ji maganar Ubangiji, dukan Yahudawan da suke zama a Masar, ‘Na rantse da sunana,’ in ji Ubangiji, ‘cewa babu wani daga Yahuda wanda yake zama a ko’ina a Masar zai ƙara kira bisa sunana ko ya rantse ya ce, “Muddin Ubangiji Mai Iko Duka yana raye.” ");
INSERT INTO hausa_vpl VALUES ("JR44_27","025_44_27","JER","44","27","27","Gama ina lura da su don lahani, ba alheri ba; mutanen Yahuda da suke a Masar za su hallaka ta wurin takobi da yunwa sai dukansu sun hallaka. ");
INSERT INTO hausa_vpl VALUES ("JR44_28","025_44_28","JER","44","28","28","Waɗanda suka kuɓuta wa takobi suka komo zuwa ƙasar Yahuda daga Masar za su zama kima kawai. Sa’an nan dukan raguwar Yahuda waɗanda suka zo don su yi zama a Masar za su san maganar wane ne za tă tabbata, tawa ko tasu. ");
INSERT INTO hausa_vpl VALUES ("JR44_29","025_44_29","JER","44","29","29","“ ‘Wannan zai zama alama a gare ku cewa zan hukunta ku a wannan wuri,’ in ji Ubangiji, ‘saboda ku san cewa barazanata ta lahani a kanku tabbatacce za tă cika.’ ");
INSERT INTO hausa_vpl VALUES ("JR44_30","025_44_30","JER","44","30","30","Ga abin da Ubangiji yana cewa, ‘Zan bayar da Fir’auna Hofra sarkin Masar ga abokan gābansa waɗanda suke neman ransa, kamar yadda na ba da Zedekiya sarkin Yahuda ga Nebukadnezzar sarkin Babilon, abokin gāban da ya nemi ransa.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR45_1","025_45_1","JER","45","1","1","Ga abin da Irmiya annabi ya faɗa wa Baruk ɗan Neriya a shekara ta huɗu ta Yehohiyakim ɗan Yosiya sarkin Yahuda, bayan Baruk ya rubuta maganar da Irmiya ya shibta masa a kan littafi cewa, ");
INSERT INTO hausa_vpl VALUES ("JR45_2","025_45_2","JER","45","2","2","“Ga abin da Ubangiji, Allah na Isra’ila, yana ce maka, Baruk. ");
INSERT INTO hausa_vpl VALUES ("JR45_3","025_45_3","JER","45","3","3","Ka ce, ‘Kaitona! Ubangiji ya ƙara baƙin ciki da wahalata; na gaji da nishe-nishe ban kuma huta ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR45_4","025_45_4","JER","45","4","4","Ubangiji ya ce, “Ka faɗa masa wannan, ‘Ga abin da Ubangiji yana cewa, zan rushe abin da na gina in kuma tumɓuke abin da na dasa, a duk fāɗin ƙasar. ");
INSERT INTO hausa_vpl VALUES ("JR45_5","025_45_5","JER","45","5","5","Ya kamata ka nemi manyan abubuwa wa kanka? Kada ka neme su. Gama zan aukar da masifa a kan dukan mutane, in ji Ubangiji, amma duk inda ka tafi zan bar ka ka kuɓutar da ranka.’ ” ");
INSERT INTO hausa_vpl VALUES ("JR46_1","025_46_1","JER","46","1","1","Ga maganar Ubangiji da ta zo wa Irmiya annabi game da al’ummai. ");
INSERT INTO hausa_vpl VALUES ("JR46_2","025_46_2","JER","46","2","2","Game da Masar. Ga saƙo game da sojojin Fir’auna Neko sarkin Masar, wanda Nebukadnezzar sarkin Babilon ya ci da yaƙi a Karkemish a Kogin Yuferites a shekara ta huɗu ta Yehohiyakim ɗan Yosiya sarkin Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR46_3","025_46_3","JER","46","3","3","“Ku shirya garkuwoyinku, manya da ƙanana, ku kuma fito don yaƙi! ");
INSERT INTO hausa_vpl VALUES ("JR46_4","025_46_4","JER","46","4","4","Ku shirya dawakai, ku sa musu sirdi! Ku tsaya a wurarenku saye da hulunan kwano a kai! Ku wasa māsunku, ku yafa kayan yaƙinku! ");
INSERT INTO hausa_vpl VALUES ("JR46_5","025_46_5","JER","46","5","5","Me nake gani? Sun tsorata, suna ja da baya, an ci jarumawansu. Suna gudu da sauri ba waiwayawa, akwai razana a kowane gefe,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR46_6","025_46_6","JER","46","6","6","“Masu saurin gudu ba sa iya gudu haka ma masu ƙarfi ba sa iya kuɓuta. A arewa ta Kogin Yuferites sun yi tuntuɓe sun fāɗi. ");
INSERT INTO hausa_vpl VALUES ("JR46_7","025_46_7","JER","46","7","7","“Wane ne wannan mai tashi kamar Nilu, kamar koguna masu tafasar ruwaye? ");
INSERT INTO hausa_vpl VALUES ("JR46_8","025_46_8","JER","46","8","8","Masar tana tashi kamar Nilu, kamar koguna masu tafasa. Tana cewa, ‘Zan tashi in rufe duniya; zan hallakar da birane da kuma mutanensu.’ ");
INSERT INTO hausa_vpl VALUES ("JR46_9","025_46_9","JER","46","9","9","Ku yi sukuwar hauka, ya dawakai! Ku tashi a guje, ya mahayan kekunan yaƙi! Ku yi ta fitowa, ya jarumawa, mutanen Kush da kuma Ludim masu riƙon garkuwoyi, mutanen Lidiya, masu iya jan baka. ");
INSERT INTO hausa_vpl VALUES ("JR46_10","025_46_10","JER","46","10","10","Amma wannan rana ta Ubangiji, Ubangiji Maɗaukaki ranar ɗaukar fansa, gama ɗaukar fansa a kan maƙiyansa. Takobi zai yi ta ci sai ya gamsu, sai ya kashe ƙishirwansa da jini. Gama Ubangiji, Ubangiji Maɗaukaki, zai miƙa hadaya a ƙasar arewa kusa da Kogin Yuferites. ");
INSERT INTO hausa_vpl VALUES ("JR46_11","025_46_11","JER","46","11","11","“Ki haura Gileyad ki samo magani, Ya Budurwa ’Yar Masar. Amma kin riɓanya magani a banza; ba magani dominki. ");
INSERT INTO hausa_vpl VALUES ("JR46_12","025_46_12","JER","46","12","12","Al’ummai za su ji game da kunyar da kika sha; kukanki zai cika duniya. Jarumi zai yi tuntuɓe a kan wani; dukansu biyu za su fāɗi tare.” ");
INSERT INTO hausa_vpl VALUES ("JR46_13","025_46_13","JER","46","13","13","Ga saƙon da Ubangiji ya yi wa Irmiya annabi game da zuwan Nebukadnezzar sarkin Babilon don yă yaƙi Masar. ");
INSERT INTO hausa_vpl VALUES ("JR46_14","025_46_14","JER","46","14","14","“Ka yi shelar wannan a Masar, ka kuma furta shi a Migdol; ka yi shelarsa kuma a Memfis da Tafanes. ‘Ku ɗauki matsayinku ku kuma shirya, gama takobi na cin waɗanda suke kewaye da ku.’ ");
INSERT INTO hausa_vpl VALUES ("JR46_15","025_46_15","JER","46","15","15","Me zai sa a wulaƙanta jarumawanka haka? Ba za su iya tsayawa ba, gama Ubangiji zai ture su ƙasa. ");
INSERT INTO hausa_vpl VALUES ("JR46_16","025_46_16","JER","46","16","16","Za su yi ta tuntuɓe; za su fāɗi akan juna. Za su ce, ‘Mu tashi, mu koma zuwa wurin mutanenmu da kuma ƙasashenmu, daga takobin masu danniya.’ ");
INSERT INTO hausa_vpl VALUES ("JR46_17","025_46_17","JER","46","17","17","A can za su tā da murya su ce, ‘Fir’auna sarkin Masar mai yawan surutu ne kawai; ya bar zarafi ya wuce masa.’ ");
INSERT INTO hausa_vpl VALUES ("JR46_18","025_46_18","JER","46","18","18","“Muddin ina raye,” in ji Sarki, wanda sunansa ne Ubangiji Maɗaukaki, “wani zai ɓullo wanda yake kamar Tabor a cikin duwatsu, kamar Karmel kusa da teku. ");
INSERT INTO hausa_vpl VALUES ("JR46_19","025_46_19","JER","46","19","19","Ku tattara kayanku don shirin zuwa zaman bauta, ku da kuke zama a Masar, gama Memfis za tă zama kufai ta zama kango, babu mazauna. ");
INSERT INTO hausa_vpl VALUES ("JR46_20","025_46_20","JER","46","20","20","“Masar kyakkyawar karsana ce, amma bobuwa tana zuwa a kanta daga arewa. ");
INSERT INTO hausa_vpl VALUES ("JR46_21","025_46_21","JER","46","21","21","Sojojin da ta yi hayarsu a cikinta suna kamar ’yan maruƙa masu kitse. Su ma za su juya su kuma gudu gaba ɗaya, ba za su iya tsayawa ba, gama ranar masifa tana zuwa a kansu, lokacin da za su sha hukunci. ");
INSERT INTO hausa_vpl VALUES ("JR46_22","025_46_22","JER","46","22","22","Masar za tă yi huci kamar macijin da yake gudu yayinda abokin gāba yana matsowa da ƙarfi; za su fāɗo mata gatura kamar mutanen da suke saran itatuwa. ");
INSERT INTO hausa_vpl VALUES ("JR46_23","025_46_23","JER","46","23","23","Za su sari kurminta,” in ji Ubangiji, “ko da yake yana maƙare da itatuwa. Sun fi fāra yawa, ba su ƙidayuwa. ");
INSERT INTO hausa_vpl VALUES ("JR46_24","025_46_24","JER","46","24","24","Za a kunyatar da Diyar Masar, da aka bashe ga mutanen arewa.” ");
INSERT INTO hausa_vpl VALUES ("JR46_25","025_46_25","JER","46","25","25","Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa, “Ina gab da kawo hukunci a kan allahn Amon na Tebes, a kan Fir’auna, a kan Masar da allolinta da sarakunanta, da kuma a kan waɗanda suka dogara ga Fir’auna. ");
INSERT INTO hausa_vpl VALUES ("JR46_26","025_46_26","JER","46","26","26","Zan ba da su ga waɗanda suke neman ransu, ga Nebukadnezzar sarkin Babilon da fadawansa. Amma daga baya, Masar za tă kasance da mazauna kamar dā,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR46_27","025_46_27","JER","46","27","27","“Kada ka ji tsoro, ya Yaƙub bawana; kada ka karai, ya Isra’ila. Tabbatacce zan cece ka daga wuri mai nisa, zuriyarka daga ƙasar bautarsu. Yaƙub zai sāke kasance cikin salama, rai kwance, babu kuma wanda zai sa ya ji tsoro. ");
INSERT INTO hausa_vpl VALUES ("JR46_28","025_46_28","JER","46","28","28","Kada ka ji tsoro, ya Yaƙub bawana, gama ina tare da kai,” in ji Ubangiji. “Ko da na hallaka dukan al’ummai sarai inda na kora ka, ba zan hallaka ka sarai ba. Zan hore ka amma da adalci kaɗai; ba zan bar ka ba hukunci ba.” ");
INSERT INTO hausa_vpl VALUES ("JR47_1","025_47_1","JER","47","1","1","Ga maganar Ubangiji da ta zo wa Irmiya annabi game da Filistiyawa kafin Fir’auna ya yaƙi Gaza. ");
INSERT INTO hausa_vpl VALUES ("JR47_2","025_47_2","JER","47","2","2","Ga abin da Ubangiji yana cewa, “Dubi yadda ruwaye suna tasowa a arewa; za su zama kogi mai rigyawa. Za su malala a ƙasa da kuma a kan kome da yake cikinta, garuruwa da waɗanda suke zaune a cikinsu. Mutane za su yi kuka; dukan mazaunan ƙasar za su yi kururuwa ");
INSERT INTO hausa_vpl VALUES ("JR47_3","025_47_3","JER","47","3","3","da jin motsin takawar kofatan dawakai, da jin surutun kekunan yaƙin abokin gāba da motsin ƙafafunsu. Ubanni ba za su juye don su taimaki ’ya’yansu ba; hannuwansu za su yi laƙwas. ");
INSERT INTO hausa_vpl VALUES ("JR47_4","025_47_4","JER","47","4","4","Gama rana ta zo da za a hallaka Filistiyawa a kuma datse dukan waɗanda suka ragu waɗanda za su iya taimakon Taya da Sidon. Ubangiji yana gab da hallaka Filistiyawa, raguwa daga bakin tekun Kaftor. ");
INSERT INTO hausa_vpl VALUES ("JR47_5","025_47_5","JER","47","5","5","Gaza za tă aske kanta cikin baƙin ciki; Ashkelon zai yi shiru. Ya raguwar da suke zama a fili, har yaushe za ku tsattsage kanku? ");
INSERT INTO hausa_vpl VALUES ("JR47_6","025_47_6","JER","47","6","6","“Za ku yi kuka kuna cewa, ‘Wayyo, takobin Ubangiji sai yaushe za ka huta? Ka koma kubenka; ka huta, ka yi shiru.’ ");
INSERT INTO hausa_vpl VALUES ("JR47_7","025_47_7","JER","47","7","7","Amma ta yaya zai huta sa’ad da Ubangiji ya umarta, sa’ad da ya umarta shi don yă faɗa wa Ashkelon da kuma bakin teku?” ");
INSERT INTO hausa_vpl VALUES ("JR48_1","025_48_1","JER","48","1","1","Game da Mowab. Ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa, “Kaito ga Nebo, gama za tă lalace. Kiriyatayim za su kunyata a kuma kame ta; katagar za tă sha kunya ta kuma wargaje. ");
INSERT INTO hausa_vpl VALUES ("JR48_2","025_48_2","JER","48","2","2","Ba za a ƙara yabi Mowab ba; a Heshbon mutane za su shirya mata maƙarƙashiya. ‘Zo, mu tafi mu kawo ƙarshe ga wannan al’umma.’ Ke kuma, ya Madmen za ki yi shiru; takobi zai fafare ki. ");
INSERT INTO hausa_vpl VALUES ("JR48_3","025_48_3","JER","48","3","3","Saurari kuka daga Horonayim, kukan risɓewa mai girma da hallaka. ");
INSERT INTO hausa_vpl VALUES ("JR48_4","025_48_4","JER","48","4","4","Za a karye Mowab; ƙanananta za su yi kuka. ");
INSERT INTO hausa_vpl VALUES ("JR48_5","025_48_5","JER","48","5","5","Sun haura hanyar zuwa Luhit, suna kuka mai zafi yayinda suke tafiya; a hanyar da ta gangara zuwa Horonayim suna kuka a kan hallakar da aka ji. ");
INSERT INTO hausa_vpl VALUES ("JR48_6","025_48_6","JER","48","6","6","Ku gudu! Ku gudu don tserar da ranku; ku zama kamar kurmi a hamada. ");
INSERT INTO hausa_vpl VALUES ("JR48_7","025_48_7","JER","48","7","7","Da yake kun dogara ga ayyukanku da arzikinku, ku ma za a kwashe ku bayi, Kemosh zai tafi bauta, tare da firistocinsa da fadawansa. ");
INSERT INTO hausa_vpl VALUES ("JR48_8","025_48_8","JER","48","8","8","Mai hallakarwa zai aukar wa kowane gari, kuma ba wani garin da zai kuɓuta. Kwari zai lalace tudu kuma ya hallaka, domin Ubangiji ya faɗa. ");
INSERT INTO hausa_vpl VALUES ("JR48_9","025_48_9","JER","48","9","9","Ku sa gishiri a kan Mowab, gama za tă zama kango; garuruwanta za su zama kufai, ba mazauna a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("JR48_10","025_48_10","JER","48","10","10","“La’ananne ne shi wanda yake sake a yin aikin Ubangiji! La’ananne ne wanda ya janye takobinsa daga zub da jini! ");
INSERT INTO hausa_vpl VALUES ("JR48_11","025_48_11","JER","48","11","11","“Mowab ta kasance cikin kwanciyar rai tun ƙuruciyarta, kamar ruwan inabin da aka bari lis, ba a juya daga tulu zuwa wani tulu ba ba tă tafi bauta ba. Saboda haka tana da ɗanɗanonta, kuma ƙanshinta bai canja ba. ");
INSERT INTO hausa_vpl VALUES ("JR48_12","025_48_12","JER","48","12","12","Kwanaki suna zuwa,” in ji Ubangiji, “sa’ad da zan aika da mutanen da za su tuntsurar da tuluna, su kuma zubar da ita waje. Za su bar tulunan ba kome a ciki su kuma farfashe tulunanta. ");
INSERT INTO hausa_vpl VALUES ("JR48_13","025_48_13","JER","48","13","13","Sa’an nan Mowab za tă ji kunyar Kemosh, yadda gidan Isra’ila ya ji kunya sa’ad da suka dogara ga Betel. ");
INSERT INTO hausa_vpl VALUES ("JR48_14","025_48_14","JER","48","14","14","“Yaya za ku ce, ‘Mu jarumawa ne, mutane masu ƙarfi a yaƙi?’ ");
INSERT INTO hausa_vpl VALUES ("JR48_15","025_48_15","JER","48","15","15","Mowab za tă hallaka a kuma kai wa garuruwanta hari; samarinta kyawawa za su gangara cikin mayanka,” in ji Sarki, wanda sunansa Ubangiji Maɗaukaki ne. ");
INSERT INTO hausa_vpl VALUES ("JR48_16","025_48_16","JER","48","16","16","“Fāɗuwar Mowab ta yi kusa; bala’inta zai auku nan da nan. ");
INSERT INTO hausa_vpl VALUES ("JR48_17","025_48_17","JER","48","17","17","Yi kuka saboda ita, dukanku mazaunan kewayenta, duk waɗanda suka san shahararta; ku ce, ‘Dubi yadda sandan sarauta mai iko ya karye, dubi yadda sanda mai daraja ya karye!’ ");
INSERT INTO hausa_vpl VALUES ("JR48_18","025_48_18","JER","48","18","18","“Sauko daga darajarku ku zauna a busasshiyar ƙasa, Ya mazaunan Diyar Dibon, gama shi mai hallaka Mowab zai haura a kanku zai kuma lalace biranenku masu kagarai. ");
INSERT INTO hausa_vpl VALUES ("JR48_19","025_48_19","JER","48","19","19","Ku tsaya a bakin hanya ku duba, ku da kuke zama a Arower. Ku tambayi mutumin da yake gudu da macen da take tserewa, tambaye su, ‘Me ya faru?’ ");
INSERT INTO hausa_vpl VALUES ("JR48_20","025_48_20","JER","48","20","20","An kunyata Mowab, gama ta wargaje. Ku yi kuka ku kuma tā da murya! Ku yi shela kusa da Arnon cewa an hallaka Mowab. ");
INSERT INTO hausa_vpl VALUES ("JR48_21","025_48_21","JER","48","21","21","Hukunci ya zo wa tudu, zuwa Holon, Yahza da Mefa’at, ");
INSERT INTO hausa_vpl VALUES ("JR48_22","025_48_22","JER","48","22","22","zuwa Dibon, Nebo da Bet-Dibilatayim, ");
INSERT INTO hausa_vpl VALUES ("JR48_23","025_48_23","JER","48","23","23","zuwa Kiriyatayim, Bet-Gamul da Bet-Meyon, ");
INSERT INTO hausa_vpl VALUES ("JR48_24","025_48_24","JER","48","24","24","zuwa Keriyot da Bozra zuwa dukan garuruwan Mowab, nesa da kusa. ");
INSERT INTO hausa_vpl VALUES ("JR48_25","025_48_25","JER","48","25","25","An karye ƙahon Mowab; an karye hannunta,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR48_26","025_48_26","JER","48","26","26","“Ku bugar da ita domin ta tayar wa Ubangiji. Bari Mowab tă yi ta birgima a cikin amanta; bari tă zama abin dariya. ");
INSERT INTO hausa_vpl VALUES ("JR48_27","025_48_27","JER","48","27","27","Isra’ila ma bai zama abin dariya a gare ki ba? Ba a kama shi cikin ɓarayi, har kaɗa kai na ba’a kike yi a duka sa’ad da kike magana game da shi? ");
INSERT INTO hausa_vpl VALUES ("JR48_28","025_48_28","JER","48","28","28","Ku bar garuruwanku ku zauna a cikin duwatsu, ku da kuke zama a Mowab. Ku zama kamar kurciyar da take sheƙarta a bakin kogo. ");
INSERT INTO hausa_vpl VALUES ("JR48_29","025_48_29","JER","48","29","29","“Mun ji labarin girman kan Mowab mun ji alfarma girmankanta da kumburinta girmankanta da fariyarta da renin zuciyarta. ");
INSERT INTO hausa_vpl VALUES ("JR48_30","025_48_30","JER","48","30","30","Na san alfarmanta amma a banza ne,” in ji Ubangiji, “kuma taƙamarta ba ya cimma kome. ");
INSERT INTO hausa_vpl VALUES ("JR48_31","025_48_31","JER","48","31","31","Saboda haka zan yi kuka a kan Mowab gama dukan Mowab zan yi kuka, Zan yi gurnani don mutanen Kir Hareset. ");
INSERT INTO hausa_vpl VALUES ("JR48_32","025_48_32","JER","48","32","32","Zan yi kuka saboda kai, yadda Yazer ya yi kuka Ya kuringar Sibma. Rassanki sun kai har teku; sun kai har tekun Yazer. Mai hallakarwa ya fāɗo a kan ’ya’yan itatuwanku da kuma inabinku da suka nuna. ");
INSERT INTO hausa_vpl VALUES ("JR48_33","025_48_33","JER","48","33","33","Farin ciki da murna su ɓace daga lambunan itatuwa da kuma gonakin Mowab. Na dakatar da malalar ruwan inabi daga wurin matsi; ba wanda zai matse su da ihun farin ciki. Ko da yake akwai sowa sowar ba ta farin ciki ba ce. ");
INSERT INTO hausa_vpl VALUES ("JR48_34","025_48_34","JER","48","34","34","“Muryar kukansu na tashi daga Heshbon zuwa Eleyale da Yahaz, daga Zowar har zuwa Horonayim da Eglat Shelishiya, gama har ruwan Nimrim ma sun bushe. ");
INSERT INTO hausa_vpl VALUES ("JR48_35","025_48_35","JER","48","35","35","A Mowab zan kawo ƙarshen waɗanda suke miƙa hadayu a masujadan kan tudu suna kuma ƙone turare ga allolinsu,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR48_36","025_48_36","JER","48","36","36","“Saboda haka zuciyata na makoki don Mowab kamar busa; tana makoki kamar busa saboda mutanen Kir Hareset. Arzikin da suka samu ta ƙare. ");
INSERT INTO hausa_vpl VALUES ("JR48_37","025_48_37","JER","48","37","37","An aske kowane kai aka kuma yanke kowane gemu aka kuma sa wa kowane kwankwaso rigar makoki. ");
INSERT INTO hausa_vpl VALUES ("JR48_38","025_48_38","JER","48","38","38","A kan dukan rufi a Mowab da kuma a dandalin jama’a babu wani abu sai kuka gama na karye Mowab kamar tulun da babu mai so,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR48_39","025_48_39","JER","48","39","39","“Duba yadda aka ragargazar ta ita! Duba yadda suke kuka! Duba yadda Mowab ta juya bayanta da kunya! Mowab ta zama abin ba’a abin tsoro ga dukan waɗanda suke kewaye da ita.” ");
INSERT INTO hausa_vpl VALUES ("JR48_40","025_48_40","JER","48","40","40","Ga abin da Ubangiji yana cewa, “Ga shi! Gaggafa tana firiya zuwa ƙasa, tana shimfiɗa fikafikanta a kan Mowab. ");
INSERT INTO hausa_vpl VALUES ("JR48_41","025_48_41","JER","48","41","41","Za a ci Keriyot a kuma kame kagarai. A wannan rana zukatan jarumawan Mowab za su zama kamar zuciyar macen da take naƙuda. ");
INSERT INTO hausa_vpl VALUES ("JR48_42","025_48_42","JER","48","42","42","Za a hallakar da Mowab a matsayin al’umma domin ta tayar wa Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR48_43","025_48_43","JER","48","43","43","Razana da rami da tarko suna jiranku, Ya mutanen Mowab,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR48_44","025_48_44","JER","48","44","44","“Duk wanda ya gudu daga razana zai fāɗa cikin rami, duk wanda ya haura daga rami zai fāɗa cikin tarko; gama zan kawo wa Mowab shekarar hukuncinta,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR48_45","025_48_45","JER","48","45","45","“A ƙarƙashin Heshbon masu gudun hijira suna tsaye ba mai taimako, gama wuta ta mutu daga Heshbon, harshen wuta daga tsakiyar Sihon; ta ƙone goshin Mowab, ƙoƙon kai na ’yan tayarwa masu surutu. ");
INSERT INTO hausa_vpl VALUES ("JR48_46","025_48_46","JER","48","46","46","Kaitonki, ya Mowab! Mutanen Kemosh sun hallaka; an kai ’ya’yanki maza daurin talala ’ya’yanki mata zaman bauta. ");
INSERT INTO hausa_vpl VALUES ("JR48_47","025_48_47","JER","48","47","47","“Duk da haka zan maido da wadatar Mowab a kwanaki masu zuwa,” in ji Ubangiji. A nan hukuncin Mowab ya ƙare. ");
INSERT INTO hausa_vpl VALUES ("JR49_1","025_49_1","JER","49","1","1","Game da Ammonawa. Ga abin da Ubangiji yana cewa, “Isra’ila ba shi da ’ya’ya maza ne? Ba shi da magāda ne? To, me ya sa Molek ya mallaki Gad? Me ya sa mutanensa suka zama a garuruwansa? ");
INSERT INTO hausa_vpl VALUES ("JR49_2","025_49_2","JER","49","2","2","Amma kwanaki suna zuwa,” in ji Ubangiji, “sa’ad da zan yi kirarin yaƙi a kan Rabba ta Ammonawa; zai zama tarin juji, za a sa wuta a ƙauyukan da suke kewayenta. Sa’an nan Isra’ila zai kori waɗanda suka kore shi,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR49_3","025_49_3","JER","49","3","3","“Ki yi kuka, ya Heshbon, gama an hallaka Ai! Ku tā da murya ku yi kuka, ya mazaunan Rabba! Ku sa tufafin makoki; ku ruga nan da can a cikin katanga, gama Molek zai tafi bauta, tare da firistocinsa da kuma fadawansa. ");
INSERT INTO hausa_vpl VALUES ("JR49_4","025_49_4","JER","49","4","4","Me ya sa kuke taƙama da kwarurukanku, taƙama da kwarurukanku masu amfani? Ya ke diya marar aminci, kin dogara a wadatarki kika kuma ce, ‘Wa zai iya fāɗa mini?’ ");
INSERT INTO hausa_vpl VALUES ("JR49_5","025_49_5","JER","49","5","5","Zan kawo razana a kanki daga waɗanda suke kewaye da ke,” in ji Ubangiji Maɗaukaki. “Za a kore kowannenku, babu wani da zai tattara masu gudun hijira. ");
INSERT INTO hausa_vpl VALUES ("JR49_6","025_49_6","JER","49","6","6","“Duk da haka, daga baya, zan maido da wadatar Ammonawa,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR49_7","025_49_7","JER","49","7","7","Game da Edom. Ga abin da Ubangiji Maɗaukaki yana cewa, “Babu sauran hikima a Teman ne? Shawara ta ɓace daga masu basira ne? Hikimarsu ta ruɓe ne? ");
INSERT INTO hausa_vpl VALUES ("JR49_8","025_49_8","JER","49","8","8","Ku juya ku gudu, ku ɓuya a cikin kogwanni masu zurfi, ku da kuke zama a Dedan, gama zan kawo masifa a kan Isuwa a lokacin da zan hukunta shi. ");
INSERT INTO hausa_vpl VALUES ("JR49_9","025_49_9","JER","49","9","9","In masu tsinkar ’ya’yan inabi suka zo maka, ba za su rage ’ya’yan inabi kaɗan ba? In ɓarayi suka zo da dare, ba za su sata abin da kawai suke bukata ba? ");
INSERT INTO hausa_vpl VALUES ("JR49_10","025_49_10","JER","49","10","10","Amma zan washe Isuwa sarai; zan bubbuɗe wuraren ɓuyarsa, don kada yă ɓoye kansa. ’Ya’yansa, danginsa da maƙwabtansa za su hallaka, ba kuwa zai ƙara kasancewa ba. ");
INSERT INTO hausa_vpl VALUES ("JR49_11","025_49_11","JER","49","11","11","Ka bar marayunka; zan tsare ransu. Gwaurayenka kuma za su dogara a gare ni.” ");
INSERT INTO hausa_vpl VALUES ("JR49_12","025_49_12","JER","49","12","12","Ga abin da Ubangiji yana cewa, “In waɗanda ba su dace su sha kwaf ɗin ba suka sha shi, me ya sa za ka kuɓuta? Ba za ka kuɓuta ba, sai ka sha shi. ");
INSERT INTO hausa_vpl VALUES ("JR49_13","025_49_13","JER","49","13","13","Na rantse da kaina,” in ji Ubangiji, “cewa Bozra za tă zama kufai da kuma abin tsoro, abin dariya da abin la’ana; kuma dukan garuruwanta za su kasance kufai har abada.” ");
INSERT INTO hausa_vpl VALUES ("JR49_14","025_49_14","JER","49","14","14","Na ji saƙo daga Ubangiji cewa; an aiki jakada zuwa ga al’ummai ya ce, “Ku tattara kanku don ku fāɗa mata! Ku tashi don yaƙi!” ");
INSERT INTO hausa_vpl VALUES ("JR49_15","025_49_15","JER","49","15","15","“Yanzu zan mai da kai ƙanƙani a cikin al’ummai abin reni a cikin mutane. ");
INSERT INTO hausa_vpl VALUES ("JR49_16","025_49_16","JER","49","16","16","Tsoron da ka sa ake ji da kuma girman kan zuciyarka ya ruɗe ka, kai da kake zama a kogon dutse, kai da kake kan tudu. Ko da yake ka gina wa kanka sheƙa can bisa kamar na gaggafa, daga can zan sauko da kai ƙasa,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR49_17","025_49_17","JER","49","17","17","“Edom za tă zama abin tsoro; dukan wanda ya wuce zai giggice ya yi tsaki saboda dukan mikinta. ");
INSERT INTO hausa_vpl VALUES ("JR49_18","025_49_18","JER","49","18","18","Kamar yadda aka tumɓuke Sodom da Gomorra, tare da garuruwan da suke maƙwabtaka da su,” in ji Ubangiji, “haka ba wanda zai zauna a can; ba wani da zai zauna a cikinta. ");
INSERT INTO hausa_vpl VALUES ("JR49_19","025_49_19","JER","49","19","19","“Kamar zaki mai haurawa daga kurmin Urdun zuwa wurin kiwo mai kyau, zan kori Edom daga ƙasarta nan da nan. Wane ne zaɓaɓɓen da zan naɗa don wannan? Wane ne yake kama da ni kuma wa zai kalubalance ni? Kuma wane makiyayi ne zai yi gāba da ni?” ");
INSERT INTO hausa_vpl VALUES ("JR49_20","025_49_20","JER","49","20","20","Saboda haka, ku ji abin da Ubangiji ya shirya a kan Edom, abin da ya nufa wa waɗanda suke zama a Teman. Za a ja ƙanana na garken tumaki a tafi; zai hallaka wurin kiwonsu sarai saboda su. ");
INSERT INTO hausa_vpl VALUES ("JR49_21","025_49_21","JER","49","21","21","Amon fāɗuwarsu zai sa ƙasa ta girgiza; za a kuma ji muryar kukansu a Jan Teku. ");
INSERT INTO hausa_vpl VALUES ("JR49_22","025_49_22","JER","49","22","22","Duba! Gaggafa tana firiya tana kuma saukowa, tana buɗe fikafikanta a bisa Bozra. A wannan rana zukatan jarumawan Edom za su zama kamar macen da take naƙuda. ");
INSERT INTO hausa_vpl VALUES ("JR49_23","025_49_23","JER","49","23","23","Game da Damaskus. “Hamat da Arfad sun giggice, gama sun ji mummunar labari. Suna damuwa, sun damu kamar tekun da baya hutu. ");
INSERT INTO hausa_vpl VALUES ("JR49_24","025_49_24","JER","49","24","24","Damaskus ta karai ta juya don ta gudu tsoro kuma ya kama ta; wahala da zafi sun kama ta, zafi kamar na mace mai naƙuda. ");
INSERT INTO hausa_vpl VALUES ("JR49_25","025_49_25","JER","49","25","25","Me ya sa ba a tafi aka bar sanannen birnin nan ba, birnin da nake jin daɗi? ");
INSERT INTO hausa_vpl VALUES ("JR49_26","025_49_26","JER","49","26","26","Tabbatacce, samarinta za su fāɗi a tituna; dukan sojojinta za su yi shiru a wannan rana,” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("JR49_27","025_49_27","JER","49","27","27","“Zan cinna wa katangar Damaskus wuta; za tă ci kagaran Ben-Hadad.” ");
INSERT INTO hausa_vpl VALUES ("JR49_28","025_49_28","JER","49","28","28","Game da Kedar da mulkokin Hazor, waɗanda Nebukadnezzar sarkin Babilon ya fāɗa wa. Ga abin da Ubangiji yana cewa, “Tashi, ku fāɗa wa Kedar ku kuma hallaka mutanen Gabas. ");
INSERT INTO hausa_vpl VALUES ("JR49_29","025_49_29","JER","49","29","29","Za a ƙwace tentunansu da garkunansu; za a tafi da mafakanta tare da dukan kayayyakinsu da raƙumansu. Mutane za su yi musu ihu, ‘Razana ko’ina!’ ");
INSERT INTO hausa_vpl VALUES ("JR49_30","025_49_30","JER","49","30","30","“Ku yi maza ku gudu! Ku zauna a kogo masu zurfi, ku da kuke zama a Hazor,” in ji Ubangiji. “Nebukadnezzar sarkin Babilon ya shirya muku maƙarƙashiya; ya ƙulla maƙarƙashiya a kanku. ");
INSERT INTO hausa_vpl VALUES ("JR49_31","025_49_31","JER","49","31","31","“Ku tashi ku kuma fāɗa wa al’umma da sauƙi wadda take zama da ƙarfin hali,” in ji Ubangiji, “al’ummar da ba ta da ƙofofi ko ƙyamare; mutanenta suna zama su kaɗai. ");
INSERT INTO hausa_vpl VALUES ("JR49_32","025_49_32","JER","49","32","32","Za a washe raƙumansu, garkunansu mai girma za su zama ganima. Zan watsar da waɗanda suke a wurare masu nesa a ko’ina zan kuma kawo musu masifa a kowane gefe,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR49_33","025_49_33","JER","49","33","33","“Hazor za tă zama mazaunin diloli, kufai har abada. Ba wanda zai zauna a can; ba wanda zai zauna a cikinta.” ");
INSERT INTO hausa_vpl VALUES ("JR49_34","025_49_34","JER","49","34","34","Ga maganar Ubangiji da ta zo wa Irmiya annabi game da Elam, a farkon mulkin Zedekiya sarkin Yahuda. ");
INSERT INTO hausa_vpl VALUES ("JR49_35","025_49_35","JER","49","35","35","Ga abin da Ubangiji Maɗaukaki yana cewa, “Ga shi, zan karye ƙarfin Elam, zaunannen ƙarfinsu. ");
INSERT INTO hausa_vpl VALUES ("JR49_36","025_49_36","JER","49","36","36","Zan kawo a kan Elam a kusurwoyi huɗu daga kusurwoyi huɗu na duniya; zan watsar da su zuwa kusurwoyi huɗu, kuma ba al’ummar da masu gudun hijirar Elam ba za su kai ba. ");
INSERT INTO hausa_vpl VALUES ("JR49_37","025_49_37","JER","49","37","37","Zan ragargaza Elam a gaban maƙiyansu, a gaban waɗanda suke neman ransu; zan kawo masifa a kansu, da zafin fushina,” in ji Ubangiji. “Zan runtume su da takobi sai na kawo ƙarshensu. ");
INSERT INTO hausa_vpl VALUES ("JR49_38","025_49_38","JER","49","38","38","Zan sa kursiyina a Elam in kuma hallaka sarkinta da fadawanta,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR49_39","025_49_39","JER","49","39","39","“Duk da haka zan maido da wadatar Elam a kwanaki masu zuwa,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR50_1","025_50_1","JER","50","1","1","Ga maganar Ubangiji da ya yi ta wurin Irmiya annabi game da Babilon da kuma ƙasar Babiloniyawa. ");
INSERT INTO hausa_vpl VALUES ("JR50_2","025_50_2","JER","50","2","2","“Ka yi shela ka kuma furta a cikin al’ummai, ka tā da tuta ka kuma furta; kada ku ɓoye kome, amma ku ce, ‘Za a ci Babilon da yaƙi; za a kunyata Bel, Marduk ya cika da tsoro. Siffofinta za su sha kunya gumakanta za su cika da tsoro.’ ");
INSERT INTO hausa_vpl VALUES ("JR50_3","025_50_3","JER","50","3","3","Al’umma daga arewa za tă fāɗa mata su mai da ƙasar kango. Ba wanda zai zauna a cikinta; mutane da dabbobi za su gudu. ");
INSERT INTO hausa_vpl VALUES ("JR50_4","025_50_4","JER","50","4","4","“A kwanakin nan, a wannan lokaci,” in ji Ubangiji, “mutanen Isra’ila da mutanen Yahuda gaba ɗaya za su tafi cikin hawaye su nemi Ubangiji Allahnsu. ");
INSERT INTO hausa_vpl VALUES ("JR50_5","025_50_5","JER","50","5","5","Za su tambayi hanyar zuwa Sihiyona su kuma juya fuskokinsu wajenta. Za su zo su haɗa kansu ga Ubangiji a madawwamin alkawari da ba za a manta da shi ba. ");
INSERT INTO hausa_vpl VALUES ("JR50_6","025_50_6","JER","50","6","6","“Mutanena sun zama ɓatattun tumaki; makiyayansu sun bauɗar da su suka sa suna ta yawo a cikin duwatsu. Sun yi ta yawo a bisa dutse da tudu suka manta wurin hutunsu. ");
INSERT INTO hausa_vpl VALUES ("JR50_7","025_50_7","JER","50","7","7","Duk wanda ya same su ya cinye su; abokan gābansu suka ce, ‘Ba mu da laifi, gama sun yi zunubi wa Ubangiji, wurin kiwonsu na gaske, Ubangiji, abin sa zuciyar kakanninsu.’ ");
INSERT INTO hausa_vpl VALUES ("JR50_8","025_50_8","JER","50","8","8","“Ku gudu daga Babilon; ku bar ƙasar Babiloniyawa, ku zama kamar awakin da suke bi da garke. ");
INSERT INTO hausa_vpl VALUES ("JR50_9","025_50_9","JER","50","9","9","Gama zan kuta in kuma kawo a kan Babilon haɗinkan manyan al’ummai na arewa. Za su ja dāgār gāba da ita, kuma daga arewa za a ci ta da yaƙi. Kibiyoyinsu za su zama kamar na gwanayen jarumawa waɗanda ba sa dawowa hannu wofi. ");
INSERT INTO hausa_vpl VALUES ("JR50_10","025_50_10","JER","50","10","10","Saboda haka za a washe Babiloniyawa; dukan waɗanda suka washe ta za su ƙoshi,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR50_11","025_50_11","JER","50","11","11","“Saboda kuna farin ciki kuna kuma murna, ku da kuka washe gādona, domin kuna tsalle kamar karsana mai sussuka hatsi kuna kuma haniniya kamar ingarmu. ");
INSERT INTO hausa_vpl VALUES ("JR50_12","025_50_12","JER","50","12","12","Mahaifiyarku za tă sha babbar kunya; ita da ta haife ku za tă sha kunya. Za tă zama mafi ƙanƙanta na al’ummai, jeji, busasshiyar ƙasa, hamada. ");
INSERT INTO hausa_vpl VALUES ("JR50_13","025_50_13","JER","50","13","13","Saboda fushin Ubangiji ba za tă zauna a cikinta ba amma za tă zama kufai gaba ɗaya. Duk waɗanda suka wuce Babilon za su ji tsoro su kuma yi tsaki saboda dukan mikinta. ");
INSERT INTO hausa_vpl VALUES ("JR50_14","025_50_14","JER","50","14","14","“Ku ja dāgā kewaye da Babilon, dukanku waɗanda kuke jan baka. Ku harbe ta! Kada ku rage kibiyoyi, gama ta yi zunubi ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR50_15","025_50_15","JER","50","15","15","Ku yi kuwwa a kanta a kowane gefe! Ta miƙa wuya, hasumiyarta ta fāɗi, katangarta sun rushe. Da yake wannan sakayya ce ta Ubangiji, ku ɗauki fansa a kanta; yi mata yadda ta yi wa waɗansu. ");
INSERT INTO hausa_vpl VALUES ("JR50_16","025_50_16","JER","50","16","16","Ku datse wa Babilon mai shuka, da mai girbi lauje a lokacin girbi. Saboda takobin mai zalunci bari kowa ya koma ga mutanensa, bari kowa ya gudu zuwa ga ƙasarsa. ");
INSERT INTO hausa_vpl VALUES ("JR50_17","025_50_17","JER","50","17","17","“Isra’ila garke ne da ya watse da zakoki suka kora. Na farkon da ya cinye shi sarkin Assuriya ne; na ƙarshen da ya ragargaza ƙasusuwansa Nebukadnezzar sarkin Babilon ne.” ");
INSERT INTO hausa_vpl VALUES ("JR50_18","025_50_18","JER","50","18","18","Saboda haka ga abin da Ubangiji Maɗaukaki, Allah na Isra’ila, yana cewa, “Zan hukunta sarkin Babilon da ƙasarsa yadda na hukunta sarkin Assuriya. ");
INSERT INTO hausa_vpl VALUES ("JR50_19","025_50_19","JER","50","19","19","Amma zan komo da Isra’ila zuwa wurin kiwonsa zai kuwa yi kiwo a Karmel da Bashan; zai ƙosar da marmarinsa a tuddan Efraim da Gileyad. ");
INSERT INTO hausa_vpl VALUES ("JR50_20","025_50_20","JER","50","20","20","A kwanakin nan, da kuma a lokacin nan,” in ji Ubangiji, “za a yi bincike don laifin Isra’ila, amma ba za a samu ba, kuma don zunubin Yahuda, amma ba za a sami wani abu ba, gama zan gafarta wa raguwar da na rage. ");
INSERT INTO hausa_vpl VALUES ("JR50_21","025_50_21","JER","50","21","21","“Ku fāɗa wa ƙasar Meratayim da waɗanda suke zama a Fekod. Ku fafara, ku kashe kuma hallaka su sarai,” in ji Ubangiji. “Ku aikata dukan abin da na umarce ku. ");
INSERT INTO hausa_vpl VALUES ("JR50_22","025_50_22","JER","50","22","22","Hargowar yaƙi tana a ƙasar, hargowar babbar hallaka! ");
INSERT INTO hausa_vpl VALUES ("JR50_23","025_50_23","JER","50","23","23","Dubi yadda aka karya aka kuma ragargaza gudumar dukan duniya! Dubi yadda Babilon ta zama kufai a cikin al’ummai! ");
INSERT INTO hausa_vpl VALUES ("JR50_24","025_50_24","JER","50","24","24","Na sa miki tarko, Babilon, kika kuwa kamu kafin ki sani; aka same ki aka kuma kama ki domin kin tayar wa Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR50_25","025_50_25","JER","50","25","25","Ubangiji ya buɗe taskar makamansa ya fitar da makaman fushinsa, gama Maɗaukaki Ubangiji Mai Iko Duka yana da aikin da zai yi a ƙasar Babiloniyawa. ");
INSERT INTO hausa_vpl VALUES ("JR50_26","025_50_26","JER","50","26","26","Ku zo ku yi gāba da ita daga nesa. Ku buɗe rumbunanta; ku jibga ta kamar tsibin hatsi. Ku hallaka ta sarai kada ku bar mata raguwa. ");
INSERT INTO hausa_vpl VALUES ("JR50_27","025_50_27","JER","50","27","27","Ku kashe dukan ’yan bijimanta bari su gangara zuwa mayanka! Kaitonsu! Gama ranansu ta zo, lokaci ya yi da za a hukunta su. ");
INSERT INTO hausa_vpl VALUES ("JR50_28","025_50_28","JER","50","28","28","Ku saurari masu gudun hijira da masu neman mafaka daga Babilon suna furtawa a Sihiyona yadda Ubangiji Allahnmu ya ɗauki fansa, fansa domin haikalinsa. ");
INSERT INTO hausa_vpl VALUES ("JR50_29","025_50_29","JER","50","29","29","“Ku kira ’yan baka a kan Babilon, dukan waɗanda suke jan baka. Ku yi sansani kewaye da ita duka; kada ku bar wani ya tsira. Ku sāka mata don ayyukanta; ku yi mata yadda ta yi. Gama ta tayar wa Ubangiji, Mai Tsarkin nan na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("JR50_30","025_50_30","JER","50","30","30","Saboda haka, samarinta za su fāɗi a tituna; za a kawar da dukan sojojinta a wannan rana,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR50_31","025_50_31","JER","50","31","31","“Ga shi, ina gāba da ke, ya ke mai girman kai,” in ji Ubangiji, Ubangiji Maɗaukaki, “gama ranarki ta zo, lokacin da za a hukunta ki. ");
INSERT INTO hausa_vpl VALUES ("JR50_32","025_50_32","JER","50","32","32","Mai ɗaga kai za tă yi tuntuɓe ta kuma fāɗi kuma ba wanda zai taimake ta tă tashi; zan hura wuta a garuruwanta da za tă cinye duk waɗanda suke kewaye da ita.” ");
INSERT INTO hausa_vpl VALUES ("JR50_33","025_50_33","JER","50","33","33","Ga abin da Ubangiji Maɗaukaki yana cewa, “An danne mutanen Isra’ila, haka ma mutanen Yahuda. Dukan waɗanda suka kama su suna riƙe su kankan, suna kin barinsu su tafi. ");
INSERT INTO hausa_vpl VALUES ("JR50_34","025_50_34","JER","50","34","34","Duk da haka Mai Fansarsu yana da ƙarfi; Ubangiji Maɗaukaki ne sunansa. Zai kāre muradunsu gabagadi don yă kawo hutu ga ƙasarsu, amma rashin hutu ga waɗanda suke zaune a Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR50_35","025_50_35","JER","50","35","35","“Akwai takobi a kan Babiloniyawa!” In ji Ubangiji “a kan waɗanda suke zama a Babilon da kuma a kan fadawanta da masu hikimarta! ");
INSERT INTO hausa_vpl VALUES ("JR50_36","025_50_36","JER","50","36","36","Akwai takobi a kan annabawan ƙaryanta! Za su zama wawaye. Akwai takobi a kan jarumawanta! Za su cika da tsoro. ");
INSERT INTO hausa_vpl VALUES ("JR50_37","025_50_37","JER","50","37","37","Akwai takobi a kan dawakanta da kekunan yaƙinta da kuma dukan baƙin da suke cikin mayaƙanta! Za su zama mata. Akwai takobi a kan dukiyarta! Za a washe su. ");
INSERT INTO hausa_vpl VALUES ("JR50_38","025_50_38","JER","50","38","38","Fări a kan ruwanta! Za su bushe ƙaf. Gama ƙasa ce ta gumaka, gumakan da za su haukace da tsoro. ");
INSERT INTO hausa_vpl VALUES ("JR50_39","025_50_39","JER","50","39","39","“Saboda haka halittun hamada da kuraye za su zauna a can, a can kuma mujiya za tă zauna. Ba za a ƙara zauna ko a yi zama a cikinta ba daga tsara zuwa tsara. ");
INSERT INTO hausa_vpl VALUES ("JR50_40","025_50_40","JER","50","40","40","Yadda Allah ya tumɓuke Sodom da Gomorra tare da maƙwabtan garuruwansu,” in ji Ubangiji “haka ma ba wanda zai zauna a can; ba wani da zai zauna a cikinta. ");
INSERT INTO hausa_vpl VALUES ("JR50_41","025_50_41","JER","50","41","41","“Duba! Ga sojoji suna zuwa daga arewa; babbar al’umma da sarakuna masu yawa suna tahowa daga iyakokin duniya. ");
INSERT INTO hausa_vpl VALUES ("JR50_42","025_50_42","JER","50","42","42","Suna riƙe da baka da māshi; mugaye ne marasa tausayi. Amonsu ya yi kamar rurin teku yayinda suke hawan dawakansu; suna zuwa kamar mutane a dāgār yaƙi don su fāɗa miki, ya Diyar Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR50_43","025_50_43","JER","50","43","43","Sarkin Babilon ya ji rahotanni game da su, hannunsa kuma ya yi laƙwas. Wahala ta kama shi, zafi kamar na mace mai naƙuda. ");
INSERT INTO hausa_vpl VALUES ("JR50_44","025_50_44","JER","50","44","44","Kamar zaki mai haurawa daga kurmin Urdun zuwa wurin kiwo mai dausayi, zan fafare Babilon daga ƙasan nan da nan. Wane ne zaɓaɓɓen da zan naɗa domin wannan? Wane ne kamar ni da zai kalubalance ni? Kuma wanda makiyayi zai iya tsaya gāba da ni?” ");
INSERT INTO hausa_vpl VALUES ("JR50_45","025_50_45","JER","50","45","45","Saboda haka, ku ji abin da Ubangiji ya shirya a kan Babilon, abin da ya nufa gāba da ƙasar Babiloniyawa. Za a kwashe ƙananan garkensu a tafi; zai hallaka wurin kiwonsu sarai saboda su. ");
INSERT INTO hausa_vpl VALUES ("JR50_46","025_50_46","JER","50","46","46","Da jin an ci Babilon da yaƙi sai duniya ta girgiza; za a ji kukanta cikin al’ummai. ");
INSERT INTO hausa_vpl VALUES ("JR51_1","025_51_1","JER","51","1","1","Ubangiji ya ce, “Ga shi, zan zuga ruhun mai hallakarwa a kan Babilon da mutanen Leb Kamai. ");
INSERT INTO hausa_vpl VALUES ("JR51_2","025_51_2","JER","51","2","2","Zan aika da baƙi zuwa Babilon su casa ta su kuma yi kaca-kaca da ƙasarta; za su yi hamayya da ita a kowane gefe a ranar masifarta. ");
INSERT INTO hausa_vpl VALUES ("JR51_3","025_51_3","JER","51","3","3","Kada ku bar maharbi yă ja bakansa, kada kuma ku bari yă sa kayan yaƙinsa. Kada ku rage samarinta, ku hallaka sojojinta ƙaf. ");
INSERT INTO hausa_vpl VALUES ("JR51_4","025_51_4","JER","51","4","4","Za su fāɗi matattu a ƙasar Babilon, da munanan raunuka a titunanta. ");
INSERT INTO hausa_vpl VALUES ("JR51_5","025_51_5","JER","51","5","5","Gama Ubangiji Maɗaukaki, Allah na Isra’ila da Yahuda bai yashe su ba, ko da yake ƙasarsu cike da take da laifi a gaban Mai Tsarki na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("JR51_6","025_51_6","JER","51","6","6","“Ku gudu daga cikin Babilon! Bari kowa yă ceci ransa! Kada a hallaka saboda zunubanta. Gama lokaci ne don ramuwar Ubangiji, zai sāka mata bisa ga alhakinta. ");
INSERT INTO hausa_vpl VALUES ("JR51_7","025_51_7","JER","51","7","7","Babilon ta zama ƙoƙon zinariya a hannun Ubangiji, ta sa dukan duniya ta yi maye. Ƙasashe sun sha ruwan inabinta, saboda haka yanzu sun haukace. ");
INSERT INTO hausa_vpl VALUES ("JR51_8","025_51_8","JER","51","8","8","Farat ɗaya Babilon za tă fāɗi ta farfashe. Ku yi kuka dominta! Ku samo mata magani saboda azabarta; wataƙila za a iya warkar da ita. ");
INSERT INTO hausa_vpl VALUES ("JR51_9","025_51_9","JER","51","9","9","“ ‘Da mun warkar da Babilon, amma ba za tă warke ba; mu ƙyale ta kowane yă koma garinsu, gama hukuncinta ya kai sammai, ya yi tsawo kamar gizagizai.’ ");
INSERT INTO hausa_vpl VALUES ("JR51_10","025_51_10","JER","51","10","10","“ ‘Ubangiji ya baratar da mu; zo mu tafi mu yi shelarsa a Sihiyona mu faɗa abin da Ubangiji Allahnmu ya yi.’ ");
INSERT INTO hausa_vpl VALUES ("JR51_11","025_51_11","JER","51","11","11","“Ku wasa kibiyoyi, ku ɗauko garkuwoyi! Ubangiji ya zuga sarakunan Medes, domin niyyarsa ce yă hallaka Babilon. Ubangiji zai yi ramuwa, zai yi ramuwa saboda haikalinsa. ");
INSERT INTO hausa_vpl VALUES ("JR51_12","025_51_12","JER","51","12","12","Ku tā da tuta gāba da katangan Babilon! Ku ƙara matsara, ku kafa masu tsaro, ku shirya kwanto! Ga shi, Ubangiji zai aikata abin da ya faɗa umarninsa a kan mutanen Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR51_13","025_51_13","JER","51","13","13","Ke da kike zama kusa da ruwaye da kike kuma wadatar dukiya, ƙarshenki ya zo, lokaci ya yi da za a kau da ke. ");
INSERT INTO hausa_vpl VALUES ("JR51_14","025_51_14","JER","51","14","14","Ubangiji Maɗaukaki ya rantse da zatinsa, ya ce Tabbatacce zan cika ka da mutane kamar fāra, za su kuwa yi sowa don nasara a kanka. ");
INSERT INTO hausa_vpl VALUES ("JR51_15","025_51_15","JER","51","15","15","“Ya halicci ƙasa ta wurin ikonsa; ya kafa duniya ta wurin hikimarsa, ya kuma shimfiɗa sammai ta wurin fahiminsa. ");
INSERT INTO hausa_vpl VALUES ("JR51_16","025_51_16","JER","51","16","16","Sa’ad da ya yi tsawa ruwan da suke sammai sukan yi ruri; yakan sa gizagizai su tashi daga ƙarshen duniya. Yakan tura walƙiya tare da ruwan sama yakan kuma saki iska daga cikin taskokinsa. ");
INSERT INTO hausa_vpl VALUES ("JR51_17","025_51_17","JER","51","17","17","“Kowane mutum marar azanci ne kuma ba shi da sani; kowane maƙerin zinariya yakan sha kunya daga wurin gumakansa. Siffofinsa na ƙarya ne; babu numfashi a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("JR51_18","025_51_18","JER","51","18","18","Su marasa amfani ne, abubuwan ba’a ne kawai; sa’ad da lokacin hukuncinsu ya kai, za su hallaka. ");
INSERT INTO hausa_vpl VALUES ("JR51_19","025_51_19","JER","51","19","19","Wanda yake na wajen Yaƙub ba kamar waɗannan ba ne, gama shi ne Mahalicci dukan abu, har da kabilar abin gādonsa, Ubangiji Maɗaukaki ne sunansa. ");
INSERT INTO hausa_vpl VALUES ("JR51_20","025_51_20","JER","51","20","20","“Kai ne kulkin yaƙina, kayan yaƙina, da kai ne na ragargaza ƙasashe, da kai ne na hallaka mulkoki, ");
INSERT INTO hausa_vpl VALUES ("JR51_21","025_51_21","JER","51","21","21","da kai ne na ragargaza doki da mahayi, da kai ne na ragargaza keken yaƙin da matuƙi, ");
INSERT INTO hausa_vpl VALUES ("JR51_22","025_51_22","JER","51","22","22","da kai ne na ragargaza miji da mata, da kai ne na ragargaza tsoho da saurayi, da kai ne na ragargaza saurayi da budurwa, ");
INSERT INTO hausa_vpl VALUES ("JR51_23","025_51_23","JER","51","23","23","da kai ne na ragargaza makiyayi da garke, da kai ne na ragargaza manoma da dawakan noma, da kai ne na ragargaza masu mulki da shugabanni. ");
INSERT INTO hausa_vpl VALUES ("JR51_24","025_51_24","JER","51","24","24","“Zan sāka wa Babilon da dukan mazaunan Babilon a idanunku saboda dukan muguntar da suka aikata a Sihiyona,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR51_25","025_51_25","JER","51","25","25","“Ga shi, ina gāba da kai, ya ke dutse mai hallakarwa, wadda ta hallaka duniya duka,” in ji Ubangiji. “Zan miƙa hannuna gāba da ke, zan mirgina ƙasa daga ƙwanƙolin dutse, zan maishe ki ƙonannen dutse. ");
INSERT INTO hausa_vpl VALUES ("JR51_26","025_51_26","JER","51","26","26","Ba za a ɗauki dutsen yin kusurwa daga gare ki ba ko na kafa harsashen gini, gama za ki zama marar amfani har abada,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR51_27","025_51_27","JER","51","27","27","“Ku tā da tuta a ƙasa! Ku busa ƙahoni a cikin ƙasashe! Ku shirya ƙasashe don yaƙi da ita, ku kira waɗannan mulkokin gāba da ita. Ararat, Minni, da Ashkenaz. A naɗa shugaba gāba da ita; ku shirya dawakai kamar fāra. ");
INSERT INTO hausa_vpl VALUES ("JR51_28","025_51_28","JER","51","28","28","Ku shirya ƙasashe don yaƙi da ita, sarakunan Medes, gwamnoninsu da dukan masu shugabancinsu da kowace ƙasar da take ƙarƙashin mulkinsu. ");
INSERT INTO hausa_vpl VALUES ("JR51_29","025_51_29","JER","51","29","29","Ƙasa ta girgiza tana makyarkyata saboda nufin Ubangiji na gāba da Babilon ya tabbata, nufinsa na mai da ƙasar Babilon kufai don kada kowa yă zauna a can. ");
INSERT INTO hausa_vpl VALUES ("JR51_30","025_51_30","JER","51","30","30","Sojojin Babilon sun daina yaƙi, suna zaune a cikin kagaransu. Ƙarfinsu ya ƙare, sun zama mata. An sa wa wuraren zamanta wuta, an karya ƙyamaren ƙofofin garinta. ");
INSERT INTO hausa_vpl VALUES ("JR51_31","025_51_31","JER","51","31","31","Maguji yana biye da maguji a guje, jakada yana biye da jakada, don su faɗa wa sarkin Babilon, cewa an ci birninsa a kowane gefe. ");
INSERT INTO hausa_vpl VALUES ("JR51_32","025_51_32","JER","51","32","32","An ƙwace mashigai aka ƙone fadamu da wuta, sojoji kuma suka giggice.” ");
INSERT INTO hausa_vpl VALUES ("JR51_33","025_51_33","JER","51","33","33","Ni Ubangiji Maɗaukaki, Allah na Isra’ila na ce, “’Yar Babilon kamar daɓen masussuka a lokacin da ake sussuka, ba da daɗewa ba lokacin girbe ta zai zo.” ");
INSERT INTO hausa_vpl VALUES ("JR51_34","025_51_34","JER","51","34","34","“Nebukadnezzar sarkin Babilon ya cinye mu, ya sa muka rikice, ya maishe mu kamar tulun da babu kome a cikinsa. Ya cinye mu kamar yadda dodon ruwa yakan yi ya kuma cika cikinsa da kayan marmarinmu, sa’an nan kuma ya yi amanmu. ");
INSERT INTO hausa_vpl VALUES ("JR51_35","025_51_35","JER","51","35","35","Bari abin da aka yi wa jikinmu yă kasance a bisa Babilon,” in ji mazaunan Sihiyona. “Bari jininmu yă kasance a kan waɗanda suke zama a Babilon,” in ji Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR51_36","025_51_36","JER","51","36","36","Saboda haka ga abin da Ubangiji ya ce, “Duba, zan tsaya muku, zan ɗaukar muku fansa, zan sa tekunta kafe in kuma sa maɓulɓulanta su ƙafe. ");
INSERT INTO hausa_vpl VALUES ("JR51_37","025_51_37","JER","51","37","37","Babilon za tă zama tarin juji, wurin zaman diloli, abin ƙyama da abar ba’a, inda ba kowa. ");
INSERT INTO hausa_vpl VALUES ("JR51_38","025_51_38","JER","51","38","38","Mutanenta duk suna ruri kamar zakoki, suna gurnani kamar ’ya’yan zaki. ");
INSERT INTO hausa_vpl VALUES ("JR51_39","025_51_39","JER","51","39","39","Amma sa’ad da aka farkar da su, zan yi musu biki in sa su sha su bugu, domin yi sowa da dariya, sa’an nan su shiga barcin da ba za su farka ba,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR51_40","025_51_40","JER","51","40","40","“Zan sauko da su kamar tumaki zuwa mayanka, kamar raguna da bunsurai. ");
INSERT INTO hausa_vpl VALUES ("JR51_41","025_51_41","JER","51","41","41","“Yadda za a ci Sheshak, taƙamar duniya duka za tă daina! Babilon za tă zama abar ƙyama a cikin al’ummai! ");
INSERT INTO hausa_vpl VALUES ("JR51_42","025_51_42","JER","51","42","42","Teku zai malalo a kan Babilon, raƙumansa masu hauka za su rufe ta. ");
INSERT INTO hausa_vpl VALUES ("JR51_43","025_51_43","JER","51","43","43","Garuruwanta sun zama abin kufai, za tă zama hamada inda ba ruwa, ƙasar da ba mazauna, ba kuma mutumin da zai ratsa ta cikinta. ");
INSERT INTO hausa_vpl VALUES ("JR51_44","025_51_44","JER","51","44","44","Zan hukunta Bel a Babilon, in sa ya yi aman abin da ya haɗiye. Ƙasashe ba za su ƙara bumbuntowa wurinsa ba. Katangan Babilon kuwa za tă rushe! ");
INSERT INTO hausa_vpl VALUES ("JR51_45","025_51_45","JER","51","45","45","“Ku fito daga cikinta, jama’ata! Ku tsere da ranku! Ku tsere daga zafin fushin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR51_46","025_51_46","JER","51","46","46","Kada zuciyarku tă yi suwu ko ku ji tsoro sa’ad da aka ji labarin a ƙasar, labari guda a wannan shekara, wani kuma a ta biye, labarin hargitsi a ƙasar mai mulki ya tasar wa mai mulki. ");
INSERT INTO hausa_vpl VALUES ("JR51_47","025_51_47","JER","51","47","47","Gama kwanaki tabbatacce suna zuwa, sa’ad da zan hukunta gumakan Babilon, zan kunyatar da dukan ƙasar kuma matattunta duk za su kwanta a cikinta. ");
INSERT INTO hausa_vpl VALUES ("JR51_48","025_51_48","JER","51","48","48","Sa’an nan sama da ƙasa da dukan abin da yake cikinsu, za su yi sowa ta murna a kan Babilon, gama daga arewa masu hallakarwa su auko mata,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR51_49","025_51_49","JER","51","49","49","“Babilon za tă fāɗi saboda kisassun mutanen Isra’ila, kamar dai yadda kisassu dukan duniya suka fāɗi saboda Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR51_50","025_51_50","JER","51","50","50","Ku waɗanda kuka tsere wa takobi, ku gudu kada ku tsaya! Ku tuna da Ubangiji a ƙasa mai nesa, ku kuma yi ta tunani a kan Urushalima.” ");
INSERT INTO hausa_vpl VALUES ("JR51_51","025_51_51","JER","51","51","51","“Mun sha kunya saboda zargin da ake yi mana kunya ta rufe mu, domin baƙi sun shiga tsarkakan wurare na gidan Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("JR51_52","025_51_52","JER","51","52","52","“Amma kwanaki suna zuwa,” in ji Ubangiji, “sa’ad da zan hukunta gumakanta, da kuma a dukan ƙasarta waɗanda aka yi wa rauni, za su yi nishi. ");
INSERT INTO hausa_vpl VALUES ("JR51_53","025_51_53","JER","51","53","53","Ko da Babilon za tă kai sararin sama ne, ta gina kagaranta mai ƙarfi, duk da haka zan aiki masu hallakarwa a kanta,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JR51_54","025_51_54","JER","51","54","54","“Ku ji muryar kuka daga Babilon, Da hargowar babbar hallakarwa daga ƙasar Babiloniyawa! ");
INSERT INTO hausa_vpl VALUES ("JR51_55","025_51_55","JER","51","55","55","Gama Ubangiji zai rushe Babilon, zai sa ta ƙame bakinta na alfarma. Sojoji za su yi ta kutsawa kamar raƙuman ruwa; suna tā da muryoyinsu. ");
INSERT INTO hausa_vpl VALUES ("JR51_56","025_51_56","JER","51","56","56","Gama mai hallakarwa ya auka wa Babilon, a kama sojojinta, a kuma kakkarya bakkunansu. Gama Ubangiji shi Allah ne mai sakayya; zai yi sakayya sosai. ");
INSERT INTO hausa_vpl VALUES ("JR51_57","025_51_57","JER","51","57","57","Zan sa mahukuntanta da masu hikimarta, gwamnoninta, shugabanninta da sojojinta su sha su bugu; za su dinga yin barcin da ba za su farka ba,” in ji Sarkin, mai suna Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("JR51_58","025_51_58","JER","51","58","58","Ni Ubangiji Maɗaukaki, na ce, “Za a baje katangan nan na Babilon mai kauri za a kuma ƙone dogayen ƙyamarenta da wuta; mutane sun wahalar da kansu a banza, al’umma sun yi wahala kawai domin wutar lalata.” ");
INSERT INTO hausa_vpl VALUES ("JR51_59","025_51_59","JER","51","59","59","Jawabin da annabi Irmiya ya ba Serahiya, ɗan Neriya, wato, jikan Ma’asehiya, lokacin da ya tafi tare da Zedekiya, Sarkin Yahuda, zuwa Babilon a shekara ta huɗu ta mulkinsa. Serahiya shi ne shugaba mai lura da gidajen saukar baƙi. ");
INSERT INTO hausa_vpl VALUES ("JR51_60","025_51_60","JER","51","60","60","Irmiya ya rubuta a littafi dukan masifun da za su auko wa Babilon, wato, dukan wannan magana da aka rubuta a kan Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR51_61","025_51_61","JER","51","61","61","Irmiya kuwa ya ce wa Serahiya, “Lokacin da ka kai Babilon, sai ka karanta dukan maganan nan. ");
INSERT INTO hausa_vpl VALUES ("JR51_62","025_51_62","JER","51","62","62","Ka kuma ce, ‘Ya Ubangiji, kai ne ka yi magana a kan wannan wuri, cewa za ka lalatar da shi, har ba abin da zai zauna a ciki, mutum ko dabba. Wurin zai zama kufai har abada.’ ");
INSERT INTO hausa_vpl VALUES ("JR51_63","025_51_63","JER","51","63","63","Sa’ad da ka gama karanta wannan littafi, sai ka ɗaura wa littafin dutse, sa’an nan ka jefar da shi tsakiyar Kogin Yuferites. ");
INSERT INTO hausa_vpl VALUES ("JR51_64","025_51_64","JER","51","64","64","Sa’an nan ka ce, ‘Haka Babilon za tă nutse, ba za tă ƙara tashi ba saboda masifar da zan kawo mata. Mutanenta kuwa za su fāɗi.’ ” Wannan shi ne ƙarshen kalmomin Irmiya. ");
INSERT INTO hausa_vpl VALUES ("JR52_1","025_52_1","JER","52","1","1","Zedekiya yana da shekara ashirin da ɗaya sa’ad da ya ci sarauta. Ya yi mulki a Urushalima shekara goma sha ɗaya. Sunan uwarsa Hamutal, ’yar Irmiya, wanda yake zaune a Libna. ");
INSERT INTO hausa_vpl VALUES ("JR52_2","025_52_2","JER","52","2","2","Sarki Zedekiya ya aikata abin da yake mugu a gaban Ubangiji kamar yadda Sarki Yehohiyakim ya yi. ");
INSERT INTO hausa_vpl VALUES ("JR52_3","025_52_3","JER","52","3","3","Al’amarin ya zama da muni ƙwarai a cikin Isra’ila da Yahuda, don haka Ubangiji ya husata har ya sa aka kai mutanen bautar talala. Zedekiya kuwa ya tayar wa Sarkin Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR52_4","025_52_4","JER","52","4","4","A kan rana ta goma ga watan goma, a shekara ta tara ta mulkin Zedekiya, Sarkin Yahuda, sai Nebukadnezzar, Sarkin Babilon, ya zo yaƙi da Urushalima tare da dukan sojojinsa. Suka kewaye ta da yaƙi, suka gina katanga kewaye da ita. ");
INSERT INTO hausa_vpl VALUES ("JR52_5","025_52_5","JER","52","5","5","An kewaye birnin da yaƙi har shekara ta goma sha ɗaya ta mulkin Zedekiya. ");
INSERT INTO hausa_vpl VALUES ("JR52_6","025_52_6","JER","52","6","6","A kan rana ta tara a watan huɗu na wannan shekara, yunwa ta tsananta ƙwarai a birnin. Mutane suka rasa abin da za su ci. ");
INSERT INTO hausa_vpl VALUES ("JR52_7","025_52_7","JER","52","7","7","Sai aka huda katangan birnin, sojojin kuwa suka gudu, suka fita daga cikin birnin da dare ta hanyar ƙofar da take tsakanin bango biyu, kusa da gonar sarki, sa’ad da Babiloniyawa suke kewaye da birnin. Sojojin suka nufi wajen Araba. ");
INSERT INTO hausa_vpl VALUES ("JR52_8","025_52_8","JER","52","8","8","Amma sojojin Babiloniyawa suka runtumi sarki Zedekiya, suka ci masa a filayen Yeriko. Dukan sojoji suka yashe shi. ");
INSERT INTO hausa_vpl VALUES ("JR52_9","025_52_9","JER","52","9","9","Da aka kama Zedekiya, sai aka kai shi wurin Sarkin Babilon a Ribla a ƙasar Hamat, a nan ne Sarkin Babilon ya yanke masa shari’a. ");
INSERT INTO hausa_vpl VALUES ("JR52_10","025_52_10","JER","52","10","10","Sarkin Babilon ya kashe ’ya’yan Zedekiya a idonsa. Ya kuma kashe dukan shugabannin Yahuda a Ribla. ");
INSERT INTO hausa_vpl VALUES ("JR52_11","025_52_11","JER","52","11","11","Sa’an nan ya ƙwaƙule idanun Zedekiya, ya kuma sa masa ƙuƙumi, aka kai shi Babilon inda aka sa shi a kurkuku har ran da ya mutu. ");
INSERT INTO hausa_vpl VALUES ("JR52_12","025_52_12","JER","52","12","12","A kan rana ta goma ga watan biyar a shekara ta goma sha tara ta sarautar Nebukadnezzar, Sarkin Babilon, sai Nebuzaradan shugaban matsara da kuma ɗan majalisar sarki, ya zo Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR52_13","025_52_13","JER","52","13","13","Sai ya ƙone haikalin Ubangiji, da gidan sarki, da dukan gine-gine masu alfarman da suke Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR52_14","025_52_14","JER","52","14","14","Sojojin Babiloniyawa da suke tare da shugaban matsara, suka rushe dukan katangan Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JR52_15","025_52_15","JER","52","15","15","Sa’an nan Nebuzaradan shugaban matsara ya kwashe waɗansu matalauta, da sauran mutane da aka bari a birnin, da waɗanda suka gudu zuwa wurin Sarkin Babilon, da sauran masu sana’a, ya kai su bautar talala a Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR52_16","025_52_16","JER","52","16","16","Amma ya bar waɗansu matalauta na gaske a ƙasar don su yi aiki a gonakin inabi, da sauran gonaki. ");
INSERT INTO hausa_vpl VALUES ("JR52_17","025_52_17","JER","52","17","17","Babiloniyawa kuwa suka farfasa ginshiƙan tagulla, da dakalai, da babbar kwatarniya, waɗanda suke a haikalin Ubangiji. Suka kwashe tagulla duka suka kai Babilon. ");
INSERT INTO hausa_vpl VALUES ("JR52_18","025_52_18","JER","52","18","18","Suka kwashe tukwanen ƙarfe, da manyan cokula, da hantsuka, da daruna, da tasoshin ƙona turare, da kayayyakin tagulla waɗanda ake amfani da su domin hidimar haikali. ");
INSERT INTO hausa_vpl VALUES ("JR52_19","025_52_19","JER","52","19","19","Suka kuma kwashe ƙananan kwanonin sha, da farantan wuta, da daruna, da tukwane, da alkukai, da tasoshin ƙona turare, da kwanonin miƙa hadayar sha. Duk abin da yake na zinariya da azurfa, shugaban matsara ya kwashe. ");
INSERT INTO hausa_vpl VALUES ("JR52_20","025_52_20","JER","52","20","20","Tagullar da sarki Solomon ya yi wa haikalin Ubangiji da ita, wato, ginshiƙai biyu, da ƙaton kwano mai suna Teku na tagulla, da bijimai goma sha biyu, waɗanda suke ɗauke da kwatarniya, da dakalai, ta fi ƙarfin a auna. ");
INSERT INTO hausa_vpl VALUES ("JR52_21","025_52_21","JER","52","21","21","Tsawon kowane ginshiƙi kamu goma sha takwas ne, kewayensa kuwa kamu goma sha biyu ne, kaurinsa kuma huɗu ne. Kowannensu yana da rami a ciki. ");
INSERT INTO hausa_vpl VALUES ("JR52_22","025_52_22","JER","52","22","22","A kan kowane ginshiƙi, an yi masa dajiyar tagulla, tsayinta kamu biyar. A bisa kan kowace dajiya akwai raga da siffofin rumman na tagulla kewaye da dajiyar. Ginshiƙi na biyu ma haka yake da siffofin rumman. ");
INSERT INTO hausa_vpl VALUES ("JR52_23","025_52_23","JER","52","23","23","Akwai siffofin rumman tasa’in da shida da ake gani a gefen. Dukan siffofin rumman da suke a kan ragar kewaye, guda ɗari ne. ");
INSERT INTO hausa_vpl VALUES ("JR52_24","025_52_24","JER","52","24","24","Shugaban matsara kuma ya ɗauki Serahiya babban firist, da Zefaniya wanda yake biye da babban firist, da mutum uku masu tsaron ƙofar, ya tafi da su. ");
INSERT INTO hausa_vpl VALUES ("JR52_25","025_52_25","JER","52","25","25","Daga cikin birnin kuma ya ɗauki shugaban sojojin, da mutum bakwai ’yan majalisar sarki, da magatakardan shugaban sojojin wanda yakan tara sojojin ƙasar, da mutane sittin na ƙasar, waɗanda aka same su a birnin, ya tafi da su. ");
INSERT INTO hausa_vpl VALUES ("JR52_26","025_52_26","JER","52","26","26","Nebuzaradan shugaban matsara ya tafi da waɗannan mutane wurin Sarkin Babilon a Ribla, ");
INSERT INTO hausa_vpl VALUES ("JR52_27","025_52_27","JER","52","27","27","Sarkin Babilon kuwa ya kashe su a Ribla a ƙasar Hamat. Haka aka tafi da mutanen Yahuda bautar talala, daga ƙasarta. ");
INSERT INTO hausa_vpl VALUES ("JR52_28","025_52_28","JER","52","28","28","Wannan shi ne yawan mutanen da Nebukadnezzar ya kai su bauta. A shekara ta bakwai ta sarautarsa, ya tafi da Yahudawa 3,023; ");
INSERT INTO hausa_vpl VALUES ("JR52_29","025_52_29","JER","52","29","29","a shekara ta goma sha takwas ta sarautar Nebukadnezzar, ya tafi da Yahudawa daga Urushalima 832; ");
INSERT INTO hausa_vpl VALUES ("JR52_30","025_52_30","JER","52","30","30","a shekara ta ashirin da uku ta sarautarsa, Nebuzaradan shugaban matsara ya tafi da Yahudawa 745. Jimillarsu duka 4,600 ne. ");
INSERT INTO hausa_vpl VALUES ("JR52_31","025_52_31","JER","52","31","31","A shekarar da Ewil-Merodak ya zama Sarkin Babilon, sai ya nuna wa Yehohiyacin Sarkin Yahuda alheri. Ya fisshe shi daga kurkuku. Wannan ya faru ran ashirin da biyar ga watan goma sha biyu a shekara ta talatin da bakwai bayan da aka kai Yehohiyacin bauta. ");
INSERT INTO hausa_vpl VALUES ("JR52_32","025_52_32","JER","52","32","32","Ewil-Merodak ya nuna wa Yehohiyacin alheri, ya ba shi matsayi na daraja fiye da waɗansu sarakunan da aka kai su bautar talala a Babilon tare da shi. ");
INSERT INTO hausa_vpl VALUES ("JR52_33","025_52_33","JER","52","33","33","Yehohiyacin ya tuɓe tufafin kurkuku, ya riƙa cin abinci kullum a teburin sarki, har dukan sauran kwanakin ransa. ");
INSERT INTO hausa_vpl VALUES ("JR52_34","025_52_34","JER","52","34","34","Kowace rana akan ba shi kyauta bisa ga umarnin sarkin Babilon, saboda bukatarsa. Haka aka yi masa har rasuwarsa.");
INSERT INTO hausa_vpl VALUES ("LM1_1","026_1_1","LAM","1","1","1","Yanzu birnin ya zama babu kowa a ciki, birnin da a dā yake cike da mutane! Yanzu birnin ya zama kamar gwauruwa, wadda a dā babba ce ita a cikin ƙasashe! Ita da take sarauniya a cikin larduna yanzu ta zama baiwa. ");
INSERT INTO hausa_vpl VALUES ("LM1_2","026_1_2","LAM","1","2","2","Tana yin kuka mai zafi da dare, hawaye na gangara a kan kumatunta. A cikin masoyanta duka babu wanda ya yi mata ta’aziyya. Duk abokanta sun yashe ta; sun zama abokan gābanta. ");
INSERT INTO hausa_vpl VALUES ("LM1_3","026_1_3","LAM","1","3","3","Bayan wahala da baƙin ciki, Yahuda ta tafi bauta. Ta zauna a cikin ƙasashe, ba tă samu wurin hutawa ba. Duk masu fafararta sun same ta sa’ad da take cikin matuƙar ɓacin rai. ");
INSERT INTO hausa_vpl VALUES ("LM1_4","026_1_4","LAM","1","4","4","Hanyoyin zuwa Sihiyona suna makoki, gama ba wanda ya zo bikin da ta shirya. Ba kowa a hanyoyin shiganta. Firistocinta suna gurnani, ’yan matana kuma suna wahala, kuma tana cikin shan wahala ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("LM1_5","026_1_5","LAM","1","5","5","Maƙiyanta sun zama shugabanninta; Abokan gābanta suna da kwanciyar rai. Ubangiji ya kawo mata ɓacin rai domin yawan zunubanta. ’Ya’yanta sun tafi bauta, a ƙarƙashin maƙiyanta. ");
INSERT INTO hausa_vpl VALUES ("LM1_6","026_1_6","LAM","1","6","6","Diyar Sihiyona ba ta da sauran daraja. ’Ya’yan sarakunanta sun zama kamar bareyi waɗanda suka rasa wurin kiwo; cikin rashin ƙarfi suka guje wa masu fafararsu. ");
INSERT INTO hausa_vpl VALUES ("LM1_7","026_1_7","LAM","1","7","7","A cikin kwanakin da take shan wahala take kuma yawo Urushalima ta tuna da dukan dukiyar da take da ita a kwanakin dā can. Sa’ad da mutanenta suka faɗa cikin hannun abokan gābanta, ba wanda ya taimake ta. Maƙiyanta suka dube ta suka yi mata dariya don hallakar da ta auko mata. ");
INSERT INTO hausa_vpl VALUES ("LM1_8","026_1_8","LAM","1","8","8","Urushalima ta yi zunubi ƙwarai saboda haka ta zama marar tsarki. Dukan masu martaba ta sun raina ta, gama sun ga tsiraicinta; ita ma da kanta tana nishi da ƙyar ta kuma juya baya. ");
INSERT INTO hausa_vpl VALUES ("LM1_9","026_1_9","LAM","1","9","9","Ƙazantarta ta manne wa rigunanta; ba tă kula da nan gaba ba, fāɗuwarta kuwa babban abu ne; babu wanda zai yi mata ta’aziyya. “Duba, ya Ubangiji, ka ga wahalata, gama maƙiyi ya yi nasara.” ");
INSERT INTO hausa_vpl VALUES ("LM1_10","026_1_10","LAM","1","10","10","Maƙiya ya kwashe dukiyarta duka; ta ga mutanen da ba su san Allah ba sun shiga wuri mai tsarkinta waɗanda ka hana su shiga taron jama’arka. ");
INSERT INTO hausa_vpl VALUES ("LM1_11","026_1_11","LAM","1","11","11","Dukan mutanenta suna nishi da ƙyar suna neman burodi; sun sayar da dukiyarsu don su samu abinci don kada su mutu da yunwa. “Ubangiji, ka duba ka gani, gama an yashe ni.” ");
INSERT INTO hausa_vpl VALUES ("LM1_12","026_1_12","LAM","1","12","12","“Ko wannan ba wani abu ba ne a wurinku, dukanku masu wucewa? Ku duba ku gani. Ko akwai wata wahala kamar irin wadda nake sha, wadda Ubangiji ya auko mini a cikin zafin fushinsa? ");
INSERT INTO hausa_vpl VALUES ("LM1_13","026_1_13","LAM","1","13","13","“Daga sama ya aiko da wuta, ya aiko ta cikin ƙasusuwana. Ya shimfiɗa raga a ƙafafuna ya juyo da ni. Ya bar ni ni kaɗai, sumamme dukan yini. ");
INSERT INTO hausa_vpl VALUES ("LM1_14","026_1_14","LAM","1","14","14","“Ya ɗaura zunubaina a wuyana; aka naɗe su a hannuwansa. Aka rataye su a wuyana Ubangiji ya kwashe ƙarfina. Ya bashe ni ga waɗanda suka fi ni ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("LM1_15","026_1_15","LAM","1","15","15","“Ubangiji ya ƙi duk mayaƙan da suke tare da ni; ya sa wata runduna ta tayar mini ta kuma tattake samarina. Ubangiji ya tattake budurwa Diyar Yahuda kamar ’ya’yan inabi a wurin matsewa. ");
INSERT INTO hausa_vpl VALUES ("LM1_16","026_1_16","LAM","1","16","16","“Dalilin da ya sa nake kuka ke nan idanuna kuma suna ta zubar da hawaye. Babu wani a kusa da zai yi mini ta’aziyya, ba wanda zai sabunta ruhuna. ’Ya’yana sun zama fakirai domin maƙiyina ya yi nasara.” ");
INSERT INTO hausa_vpl VALUES ("LM1_17","026_1_17","LAM","1","17","17","Sihiyona ta miƙa hannunta, amma ba wani da zai yi mata ta’aziyya. Ubangiji ya umarta cewa maƙwabtansa za su zama maƙiyansa; Urushalima ta zama abar ƙyama a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("LM1_18","026_1_18","LAM","1","18","18","“Ubangiji mai adalci ne, duk da haka na yi tawaye da umarninsa. Ku saurara, jama’a duka; ku dubi wahalar da nake sha. Samarina da ’yan matana duka sun tafi bauta. ");
INSERT INTO hausa_vpl VALUES ("LM1_19","026_1_19","LAM","1","19","19","“Na kira abokaina amma sun yashe ni. Firistocina da dattawana sun hallaka a cikin birnin yayinda suke neman abinci don kada su mutu da yunwa. ");
INSERT INTO hausa_vpl VALUES ("LM1_20","026_1_20","LAM","1","20","20","“Duba, Ubangiji, ka ga ƙuncin da nake ciki! Ina shan azaba a raina, ba ni da kwanciyar rai a cikin zuciyata, domin na yi tawaye sosai. A waje takobi na kisa; a ciki kuma akwai mutuwa. ");
INSERT INTO hausa_vpl VALUES ("LM1_21","026_1_21","LAM","1","21","21","“Mutane suna ji ina nishi da ƙyar, amma ba wanda zai yi mini ta’aziyya. Dukan maƙiyana sun ji wahalar da nake ciki; suna farin ciki da abin da ka yi. Ka kawo ranan nan da ka sanar domin su ma su zama kamar ni. ");
INSERT INTO hausa_vpl VALUES ("LM1_22","026_1_22","LAM","1","22","22","“Bari ka ga muguntarsu duka; ka yi musu yadda ka yi mini domin dukan zunubansu. Nishina da yawa kuma zuciyata ta gaji.” ");
INSERT INTO hausa_vpl VALUES ("LM2_1","026_2_1","LAM","2","1","1","Yadda Ubangiji ya rufe Diyar Sihiyona da gizagizan fushi! Ya jefar da darajar Isra’ila daga sama zuwa ƙasa; bai tuna da wurin ɗora ƙafafunsa ba a ranar fushinsa. ");
INSERT INTO hausa_vpl VALUES ("LM2_2","026_2_2","LAM","2","2","2","Ubangiji ya hallakar da wurin zaman Yaƙub ba tausayi; A cikin fushinsa kuma zai rurrushe kagaran Diyar Yahuda. Ya ƙasƙantar da mulki da masu mulki. ");
INSERT INTO hausa_vpl VALUES ("LM2_3","026_2_3","LAM","2","3","3","A cikin zafin fushi ya fasa kowane ƙaho na Isra’ila. Ya janye hannun damansa sa’ad da maƙiyi ya zo. Ya yi ƙuna a cikin Yaƙub kamar wuta mai ƙone duk abin da yake kusa da ita. ");
INSERT INTO hausa_vpl VALUES ("LM2_4","026_2_4","LAM","2","4","4","Kamar abokin gāba, ya ɗana bakansa; hannun damansa na shirye. Kamar maƙiyi, ya kashe duk wanda idonsa ya ji daɗin gani; ya zuba fushinsa kamar wuta a kan tenti na Diyar Sihiyona. ");
INSERT INTO hausa_vpl VALUES ("LM2_5","026_2_5","LAM","2","5","5","Ubangiji kamar maƙiyi ne; ya hallaka Isra’ila. Ya hallaka wurarenta duka ya kuma hallaka kagaranta. Ya ƙara yawan makoki da baƙin ciki wa Diyar Yahuda. ");
INSERT INTO hausa_vpl VALUES ("LM2_6","026_2_6","LAM","2","6","6","Ya rushe haikalinsa kamar lambu; ya hallaka wurin yi masa sujada. Ubangiji ya sa Sihiyona ta manta da bukukkuwanta da kuma ranakunta na Asabbaci; a cikin zafin fushinsa ya watsar da sarki da firist. ");
INSERT INTO hausa_vpl VALUES ("LM2_7","026_2_7","LAM","2","7","7","Ubangiji ya ƙi bagadensa ya kuma yi wofi da haikalinsa. Ya ba maƙiyinta fadodinta; suka yi sowa a cikin gidan Ubangiji kamar a ranar da ake yin biki. ");
INSERT INTO hausa_vpl VALUES ("LM2_8","026_2_8","LAM","2","8","8","Ubangiji ya ƙuduri niyya yă rushe bangon da yake kewaye da Diyar Sihiyona. Ya auna da igiyar awo bai fasa hallaka ta ba. Ya sa katanga da katanga duk suka lalace. ");
INSERT INTO hausa_vpl VALUES ("LM2_9","026_2_9","LAM","2","9","9","Ƙofofinta sun nutse a cikin ƙasa; ya kakkarya ƙarafanta. Sarakunanta da ’ya’yan sarakunanta duk an kai su bauta cikin waɗansu ƙasashe, babu sauran doka, annabawa kuma ba su samun wahayi daga wurin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("LM2_10","026_2_10","LAM","2","10","10","Dattawan Diyar Sihiyona sun zauna shiru a ƙasa; suka kuma sa rigar buhu. ’Yan matan Urushalima suka sunkuyar da kawunansu ƙasa. ");
INSERT INTO hausa_vpl VALUES ("LM2_11","026_2_11","LAM","2","11","11","Idanuna sun dushe don yawan kuka, raina na cike da baƙin ciki; zuciyata ta karaya domin mutanena sun hallaka, domin yara da jarirai suna suma a kan hanyoyi a cikin birni. ");
INSERT INTO hausa_vpl VALUES ("LM2_12","026_2_12","LAM","2","12","12","Suna ce wa uwayensu, “Ina burodi da ruwan inabi?” Yayinda suke suma kamar mutanen da aka ji masu ciwo a cikin birni, sa’ad da suke mutuwa a hannuwan uwayensu. ");
INSERT INTO hausa_vpl VALUES ("LM2_13","026_2_13","LAM","2","13","13","Me zan ce miki? Da me zan kwatanta ki, ke Diyar Urushalima? Da me zan misalta ki, yadda zan iya yi miki ta’aziyya, Ke Budurwa Diyar Sihiyona? Ciwonki yana da zurfi kamar teku. Wane ne zai iya warkar da ke? ");
INSERT INTO hausa_vpl VALUES ("LM2_14","026_2_14","LAM","2","14","14","Wahayin annabawanki ƙarya ne kuma marasa amfani; ba su tona zunubanki ba yadda za su iya ceto ki daga bauta ba. Sun yi miki annabcin ƙarya marar amfani. ");
INSERT INTO hausa_vpl VALUES ("LM2_15","026_2_15","LAM","2","15","15","Duk masu wucewa suna yi miki tafi na reni; suna yi wa Diyar Urushalima tsaki suna kaɗa kai suna cewa, “Wannan ne birnin da aka ce kyakkyawa ne, mai farantawa dukan duniya rai?” ");
INSERT INTO hausa_vpl VALUES ("LM2_16","026_2_16","LAM","2","16","16","Maƙiyanki duka suna ta surutu game da ke; suna tsaki suna cizon haƙora suna cewa, “Mun hallaka ta. Wannan ce ranar da muke jira; yau mun gan ta.” ");
INSERT INTO hausa_vpl VALUES ("LM2_17","026_2_17","LAM","2","17","17","Ubangiji ya yi abin da ya shirya; ya cika maganarsa, wadda ya umarta tun daɗewa. Ya jefar da ke ba tausayi, ya bari maƙiya sun yi nasara da ke, ya ɗaukaka ƙahon maƙiyanki. ");
INSERT INTO hausa_vpl VALUES ("LM2_18","026_2_18","LAM","2","18","18","Zuciyar mutane ta yi kuka ga Ubangiji. Ya bangon Diyar Urushalima, bar hawayenki su zuba kamar rafi dare da rana; kada ki huta, kada idanunki su huta. ");
INSERT INTO hausa_vpl VALUES ("LM2_19","026_2_19","LAM","2","19","19","Ki tashi, ki yi kuka cikin dare, dare na yi sai ki fara kuka; kina buɗewa Ubangiji zuciyarki. Ki ɗaga hannuwanki gare shi domin rayukan ’ya’yanki, waɗanda suka suma don yunwa a kan kowane titi. ");
INSERT INTO hausa_vpl VALUES ("LM2_20","026_2_20","LAM","2","20","20","“Ka duba, ka gani ya Ubangiji. Wane ne ka taɓa yi wa haka? Ko ya kamata uwaye su ci ’ya’yansu, ’ya’yan da suka yi reno? Ko ya kamata a kashe firistoci da annabawa a cikin haikalin Ubangiji? ");
INSERT INTO hausa_vpl VALUES ("LM2_21","026_2_21","LAM","2","21","21","“Matasa da tsofaffi duk suna kwanciya a cikin ƙurar tituna; an karkashe matasa da ’yan matana da takobi. Ka kashe su a ranar fushinka; ka kashe su ba tausayi. ");
INSERT INTO hausa_vpl VALUES ("LM2_22","026_2_22","LAM","2","22","22","“Kamar yadda kake yin gayyata a ranar biki, haka kake kawo mini tsoro a kowane gefe. A ranar fushin Ubangiji ba mai tserewa ba wanda zai tsira; maƙiyina ya kashe waɗanda na yi renonsu, na kuma lura da su.” ");
INSERT INTO hausa_vpl VALUES ("LM3_1","026_3_1","LAM","3","1","1","Ni ne mutumin da ya ga azaba ta wurin bulalar fushin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("LM3_2","026_3_2","LAM","3","2","2","Ya kore ni, ya sa na yi tafiya a cikin duhu maimakon a cikin haske; ");
INSERT INTO hausa_vpl VALUES ("LM3_3","026_3_3","LAM","3","3","3","ba shakka, ya juya mini baya, yana gāba da ni sau da sau, dukan yini. ");
INSERT INTO hausa_vpl VALUES ("LM3_4","026_3_4","LAM","3","4","4","Ya sa fatar jikina da naman jikina sun tsufa ya kuma karya ƙasusuwana. ");
INSERT INTO hausa_vpl VALUES ("LM3_5","026_3_5","LAM","3","5","5","Ya yi mini kwanton ɓauna ya kuma kewaye ni da baƙin ciki da kuma wahala. ");
INSERT INTO hausa_vpl VALUES ("LM3_6","026_3_6","LAM","3","6","6","Ya sa na zauna a cikin duhu kamar waɗanda suka mutu da jimawa. ");
INSERT INTO hausa_vpl VALUES ("LM3_7","026_3_7","LAM","3","7","7","Ya kewaye ni yadda ba zan iya gudu ba; Ya daure ni da sarƙa mai nauyi. ");
INSERT INTO hausa_vpl VALUES ("LM3_8","026_3_8","LAM","3","8","8","Ko lokacin da nake kira don neman taimako, ba ya jin addu’ata. ");
INSERT INTO hausa_vpl VALUES ("LM3_9","026_3_9","LAM","3","9","9","Ya tare hanyata da tubula na duwatsu; ya sa hanyata ta karkace. ");
INSERT INTO hausa_vpl VALUES ("LM3_10","026_3_10","LAM","3","10","10","Kamar beyar da take a laɓe tana jira, kamar zaki a ɓoye, ");
INSERT INTO hausa_vpl VALUES ("LM3_11","026_3_11","LAM","3","11","11","ya janye ni daga kan hanya ya ɓatar da ni ya bar ni ba taimako. ");
INSERT INTO hausa_vpl VALUES ("LM3_12","026_3_12","LAM","3","12","12","Ya ja kwarinsa ya sa in zama abin baratarsa. ");
INSERT INTO hausa_vpl VALUES ("LM3_13","026_3_13","LAM","3","13","13","Ya harbi zuciyata da kibiyoyin kwarinsa. ");
INSERT INTO hausa_vpl VALUES ("LM3_14","026_3_14","LAM","3","14","14","Na zama abin dariya ga mutanena duka; suna yi mini ba’a cikin waƙa dukan yini. ");
INSERT INTO hausa_vpl VALUES ("LM3_15","026_3_15","LAM","3","15","15","Ya cika ni da kayan ɗaci ya gundure ni da abinci mai ɗaci. ");
INSERT INTO hausa_vpl VALUES ("LM3_16","026_3_16","LAM","3","16","16","Ya kakkarya haƙorana da tsakuwa; ya tattake ni cikin ƙura. ");
INSERT INTO hausa_vpl VALUES ("LM3_17","026_3_17","LAM","3","17","17","An hana ni salama; na manta da ko mene ne ake kira wadata. ");
INSERT INTO hausa_vpl VALUES ("LM3_18","026_3_18","LAM","3","18","18","Saboda haka na ce, “Darajata ta ƙare da kuma duk abin da nake begen samu daga wurin Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("LM3_19","026_3_19","LAM","3","19","19","Na tuna da azabata da kuma sintiri, da na yi ta yi da ɗacin rai. ");
INSERT INTO hausa_vpl VALUES ("LM3_20","026_3_20","LAM","3","20","20","Na tuna su sosai, sai kuma na ji ba daɗi a raina. ");
INSERT INTO hausa_vpl VALUES ("LM3_21","026_3_21","LAM","3","21","21","Duk da haka na tuna da wannan na kuma sa bege ga nan gaba. ");
INSERT INTO hausa_vpl VALUES ("LM3_22","026_3_22","LAM","3","22","22","Domin ƙaunar Ubangiji ba mu hallaka ba; gama jiyejiyanƙansa ba su ƙarewa. ");
INSERT INTO hausa_vpl VALUES ("LM3_23","026_3_23","LAM","3","23","23","Sababbi ne kowace safiya; amincinka kuwa mai girma ne. ");
INSERT INTO hausa_vpl VALUES ("LM3_24","026_3_24","LAM","3","24","24","Na ce wa kaina, “Ubangiji shi ne nawa; saboda haka zan jira shi.” ");
INSERT INTO hausa_vpl VALUES ("LM3_25","026_3_25","LAM","3","25","25","Ubangiji mai alheri ne ga waɗanda suke da bege a cikinsa, ga kuma wanda yake neman shi; ");
INSERT INTO hausa_vpl VALUES ("LM3_26","026_3_26","LAM","3","26","26","yana da kyau ka jira shiru domin samun ceton Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("LM3_27","026_3_27","LAM","3","27","27","Yana da kyau mutum yă sha wuya tun yana yaro. ");
INSERT INTO hausa_vpl VALUES ("LM3_28","026_3_28","LAM","3","28","28","Bari yă zauna shiru shi kaɗai, gama haka Ubangiji ya sa yă yi. ");
INSERT INTO hausa_vpl VALUES ("LM3_29","026_3_29","LAM","3","29","29","Bari yă ɓoye fuskarsa cikin ƙura kila akwai bege. ");
INSERT INTO hausa_vpl VALUES ("LM3_30","026_3_30","LAM","3","30","30","Bari yă ba da kumatunsa a mare shi, yă kuma bari a ci masa mutunci. ");
INSERT INTO hausa_vpl VALUES ("LM3_31","026_3_31","LAM","3","31","31","Gama Ubangiji ba ya yashe mutane har abada. ");
INSERT INTO hausa_vpl VALUES ("LM3_32","026_3_32","LAM","3","32","32","Ko da ya kawo ɓacin rai, zai nuna tausayi sosai, ƙaunarsa tana da yawa. ");
INSERT INTO hausa_vpl VALUES ("LM3_33","026_3_33","LAM","3","33","33","Gama ba haka kawai yake kawo wahala ko ɓacin rai ga ’yan adam ba. ");
INSERT INTO hausa_vpl VALUES ("LM3_34","026_3_34","LAM","3","34","34","Bai yarda a tattake ’yan kurkuku a ƙasa ba, ");
INSERT INTO hausa_vpl VALUES ("LM3_35","026_3_35","LAM","3","35","35","ko kuma a danne wa mutum hakkinsa a gaban Maɗaukaki, ");
INSERT INTO hausa_vpl VALUES ("LM3_36","026_3_36","LAM","3","36","36","ko kuma a danne wa mutum shari’ar gaskiya ashe Ubangiji ba zai ga irin waɗannan abubuwa ba? ");
INSERT INTO hausa_vpl VALUES ("LM3_37","026_3_37","LAM","3","37","37","Wane ne ya isa yă yi magana kuma ta cika in ba Ubangiji ne ya umarta ba? ");
INSERT INTO hausa_vpl VALUES ("LM3_38","026_3_38","LAM","3","38","38","Ba daga bakin Maɗaukaki ne bala’i da abubuwa masu kyau suke fitowa ba? ");
INSERT INTO hausa_vpl VALUES ("LM3_39","026_3_39","LAM","3","39","39","Don mene ne wani mai rai zai yi gunaguni sa’ad da aka ba shi horo domin zunubansa? ");
INSERT INTO hausa_vpl VALUES ("LM3_40","026_3_40","LAM","3","40","40","Bari mu auna tafiyarmu mu gwada ta, sai mu kuma koma ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("LM3_41","026_3_41","LAM","3","41","41","Bari mu ɗaga zuciyarmu da hannuwanmu ga Allah na cikin sama, mu ce, ");
INSERT INTO hausa_vpl VALUES ("LM3_42","026_3_42","LAM","3","42","42","“Mun yi zunubi mun yi tawaye ba ka kuwa gafarta ba. ");
INSERT INTO hausa_vpl VALUES ("LM3_43","026_3_43","LAM","3","43","43","“Ka rufe kanka da fushi, ka fafare mu; ka karkashe mu ba tausayi. ");
INSERT INTO hausa_vpl VALUES ("LM3_44","026_3_44","LAM","3","44","44","Ka rufe kanka da gajimare don kada addu’armu ta kai wurinka. ");
INSERT INTO hausa_vpl VALUES ("LM3_45","026_3_45","LAM","3","45","45","Ka mai da mu tarkace da juji a cikin mutane. ");
INSERT INTO hausa_vpl VALUES ("LM3_46","026_3_46","LAM","3","46","46","“Dukan maƙiyanmu suna ta yin mana magana marar daɗi. ");
INSERT INTO hausa_vpl VALUES ("LM3_47","026_3_47","LAM","3","47","47","Muna cika da tsoro, da lalatarwa da hallakarwa.” ");
INSERT INTO hausa_vpl VALUES ("LM3_48","026_3_48","LAM","3","48","48","Hawaye na kwararowa daga idanuna domin an hallaka mutanena. ");
INSERT INTO hausa_vpl VALUES ("LM3_49","026_3_49","LAM","3","49","49","Idanuna za su ci gaba da kwararowa da hawaye, ba hutawa. ");
INSERT INTO hausa_vpl VALUES ("LM3_50","026_3_50","LAM","3","50","50","Har sai in Ubangiji ya duba daga sama ya gani. ");
INSERT INTO hausa_vpl VALUES ("LM3_51","026_3_51","LAM","3","51","51","Abin da nake gani yana kawo mini baƙin ciki domin dukan matan birnina. ");
INSERT INTO hausa_vpl VALUES ("LM3_52","026_3_52","LAM","3","52","52","Maƙiyana suna farauta ta ba dalili kamar tsuntsu. ");
INSERT INTO hausa_vpl VALUES ("LM3_53","026_3_53","LAM","3","53","53","Sun yi ƙoƙari su kashe ni a cikin rami suka kuma jajjefe ni da duwatsu; ");
INSERT INTO hausa_vpl VALUES ("LM3_54","026_3_54","LAM","3","54","54","ruwaye suka rufe kaina, sai na yi tunani cewa na kusa mutuwa. ");
INSERT INTO hausa_vpl VALUES ("LM3_55","026_3_55","LAM","3","55","55","Na yi kira ga sunanka, ya Ubangiji, daga rami mai zurfi. ");
INSERT INTO hausa_vpl VALUES ("LM3_56","026_3_56","LAM","3","56","56","Ka ji roƙona, “Kada ka toshe kunnuwanka ka ƙi jin roƙona na neman taimako.” ");
INSERT INTO hausa_vpl VALUES ("LM3_57","026_3_57","LAM","3","57","57","Ka zo kusa lokacin da na kira ka, kuma ka ce mini, “Kada ka ji tsoro.” ");
INSERT INTO hausa_vpl VALUES ("LM3_58","026_3_58","LAM","3","58","58","Ya Ubangiji, ka goyi bayana; ka fanshi raina. ");
INSERT INTO hausa_vpl VALUES ("LM3_59","026_3_59","LAM","3","59","59","Ya Ubangiji, ka ga inda aka yi mini ba daidai ba. Ka shari’anta, ka ba ni gaskiya! ");
INSERT INTO hausa_vpl VALUES ("LM3_60","026_3_60","LAM","3","60","60","Ka ga zurfin ramakonsu, da duk mugun shirin da suke yi mini. ");
INSERT INTO hausa_vpl VALUES ("LM3_61","026_3_61","LAM","3","61","61","Ya Ubangiji, ka ji zaginsu, da duka mugun shirin da suke yi mini ");
INSERT INTO hausa_vpl VALUES ("LM3_62","026_3_62","LAM","3","62","62","Abin da maƙiyana suke yin raɗa a kai game da ni duk yini. ");
INSERT INTO hausa_vpl VALUES ("LM3_63","026_3_63","LAM","3","63","63","Dube su! A zaune ko a tsaye, suna yi mini ba’a cikin waƙoƙinsu. ");
INSERT INTO hausa_vpl VALUES ("LM3_64","026_3_64","LAM","3","64","64","Ka ba su abin da ya dace su samu, ya Ubangiji, domin abin da hannuwansu suka yi. ");
INSERT INTO hausa_vpl VALUES ("LM3_65","026_3_65","LAM","3","65","65","Ka sa yana ta rufe zuciyarsu, kuma bari la’anarka ta bi su. ");
INSERT INTO hausa_vpl VALUES ("LM3_66","026_3_66","LAM","3","66","66","Ka fafare su cikin fushi ka hallaka su daga cikin duniya ta Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("LM4_1","026_4_1","LAM","4","1","1","Zinariya ta rasa kyanta, hasken zinariya ya dushe! An warwatsar da tsarkakakkun duwatsu masu daraja a kan tituna. ");
INSERT INTO hausa_vpl VALUES ("LM4_2","026_4_2","LAM","4","2","2","Dubi samarin Sihiyona masu daraja, waɗanda a dā darajarsu ta isa nauyin zinariya, yanzu ana ɗaukar su a matsayin tukwanen ƙasa, aikin maginin tukwane! ");
INSERT INTO hausa_vpl VALUES ("LM4_3","026_4_3","LAM","4","3","3","Ko diloli suna ba ’ya’yansu nono su sha, amma mutanena sun zama marasa zuciya kamar jiminai a cikin jeji. ");
INSERT INTO hausa_vpl VALUES ("LM4_4","026_4_4","LAM","4","4","4","Domin ƙishirwa harshen jarirai ya manne a rufin bakinsu; yaran suna roƙo a ba su burodi, amma ba wanda ya ba su. ");
INSERT INTO hausa_vpl VALUES ("LM4_5","026_4_5","LAM","4","5","5","Waɗanda a dā sukan ci abinci mai daɗi yanzu su ne masu bara a tituna. Waɗanda a dā suke sa kaya masu kyau yanzu suna kwance a kan tarin toka. ");
INSERT INTO hausa_vpl VALUES ("LM4_6","026_4_6","LAM","4","6","6","Horon mutanena ya fi na Sodom girma, wadda aka hallaka farat ɗaya ba wani hannu da ya juya ya taimake ta. ");
INSERT INTO hausa_vpl VALUES ("LM4_7","026_4_7","LAM","4","7","7","’Ya’yan sarakunansu sun fi ƙanƙara haske sun kuma fi madara fari, jikunansu sun fi murjani ja, kyansu kamar shuɗin yakutu. ");
INSERT INTO hausa_vpl VALUES ("LM4_8","026_4_8","LAM","4","8","8","Amma yanzu sun fi dare duhu; ba a iya gane su a tituna. Fatar jikinsu ta manne da ƙasusuwansu; sun bushe kamar itace. ");
INSERT INTO hausa_vpl VALUES ("LM4_9","026_4_9","LAM","4","9","9","Gara waɗanda aka kashe su da takobi da waɗanda suke mutuwa da yunwa; sun rame domin rashin abinci a gona. ");
INSERT INTO hausa_vpl VALUES ("LM4_10","026_4_10","LAM","4","10","10","Da hannuwansu mata masu tausayi sun dafa yaransu, suka zama masu abinci sa’ad da aka hallaka mutanena. ");
INSERT INTO hausa_vpl VALUES ("LM4_11","026_4_11","LAM","4","11","11","Ubangiji ya saki fushinsa; ya zuba zafin fushinsa. Ya hura wuta a Sihiyona ta kuma cinye harsashin gininta. ");
INSERT INTO hausa_vpl VALUES ("LM4_12","026_4_12","LAM","4","12","12","Sarakunan duniya ba su gaskata ba, haka ma mutanen duniya, cewa magabta da maƙiya za su iya shiga ƙofofin Urushalima. ");
INSERT INTO hausa_vpl VALUES ("LM4_13","026_4_13","LAM","4","13","13","Amma ya faru domin zunuban annabawanta da muguntar firistocinta, waɗanda suka zub da jinin masu adalci a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("LM4_14","026_4_14","LAM","4","14","14","Yanzu suna yawo barkatai a tituna kamar makafi. Sun ƙazantu da jini yadda ba wanda zai kuskura ya taɓa rigunansu. ");
INSERT INTO hausa_vpl VALUES ("LM4_15","026_4_15","LAM","4","15","15","“Ku tafi! Ba ku da tsabta!” Haka mutane suke ihu suke ce musu. “Ku tashi daga nan! Ku tashi daga nan! Kada ku taɓa mu!” Sa’ad da suka gudu suna yawo, mutanen waɗansu ƙasashe suka ce, “Ba za su ci gaba da zama a nan ba.” ");
INSERT INTO hausa_vpl VALUES ("LM4_16","026_4_16","LAM","4","16","16","Ubangiji kansa ya warwatsa su; ya daina duban su. Ba a ba firistoci girma, ba su ba dattawa gata. ");
INSERT INTO hausa_vpl VALUES ("LM4_17","026_4_17","LAM","4","17","17","Idanunmu sun gaji, suna ta dubawa ko taimako zai zo; mu sa ido ko za mu ga ƙasar da za tă iya taimakon mu. ");
INSERT INTO hausa_vpl VALUES ("LM4_18","026_4_18","LAM","4","18","18","Ana bin sawunmu, ba za mu iya tafiya kan tituna ba. Ƙarshenmu ya kusa, kwanakinmu sun ƙare, gama ƙarshenmu ya zo. ");
INSERT INTO hausa_vpl VALUES ("LM4_19","026_4_19","LAM","4","19","19","Masu fafarar mu sun fi gaggafa mai firiya a sararin sama sauri; sun fafare mu a kan duwatsu suna fakon mu a jeji. ");
INSERT INTO hausa_vpl VALUES ("LM4_20","026_4_20","LAM","4","20","20","Shafaffe na Ubangiji, numfashin ranmu, ya fāɗi cikin tarkonsu. Muna tunani cewa za mu iya rayuwa cikin sauran mutane a ƙarƙashin inuwarsa. ");
INSERT INTO hausa_vpl VALUES ("LM4_21","026_4_21","LAM","4","21","21","Ku yi murna da farin ciki, ya Diyar Edom, ke mai zama a ƙasar Uz. Amma ke ma za a ba ki kwaf; za ki bugu ki zama tsirara. ");
INSERT INTO hausa_vpl VALUES ("LM4_22","026_4_22","LAM","4","22","22","Ya Diyar Sihiyona, hukuncinki zai ƙare; ba zai sa zaman bautarki yă yi tsayi ba. Amma ya Diyar Edom, zai hukunta zunubinki yă tona tsiraicinki. ");
INSERT INTO hausa_vpl VALUES ("LM5_1","026_5_1","LAM","5","1","1","Ka tuna, ya Ubangiji, abin da ya faru da mu; duba, ka ga kunyar da muka sha. ");
INSERT INTO hausa_vpl VALUES ("LM5_2","026_5_2","LAM","5","2","2","An ba wa baƙi gādonmu, gidajenmu kuma aka ba bare. ");
INSERT INTO hausa_vpl VALUES ("LM5_3","026_5_3","LAM","5","3","3","Mun zama marayu marasa ubanni, uwayenmu kamar gwauraye. ");
INSERT INTO hausa_vpl VALUES ("LM5_4","026_5_4","LAM","5","4","4","Dole mu sayi ruwan da muke sha; sai mun biya mu sami itace. ");
INSERT INTO hausa_vpl VALUES ("LM5_5","026_5_5","LAM","5","5","5","Masu fafararmu sun kusa kama mu; mun gaji kuma ba dama mu huta. ");
INSERT INTO hausa_vpl VALUES ("LM5_6","026_5_6","LAM","5","6","6","Mun miƙa kanmu ga Masar da Assuriya don mu sami isashen abinci. ");
INSERT INTO hausa_vpl VALUES ("LM5_7","026_5_7","LAM","5","7","7","Kakanninmu sun yi zunubi kuma ba sa nan yanzu, mu ne aka bari muna shan hukuncinsu. ");
INSERT INTO hausa_vpl VALUES ("LM5_8","026_5_8","LAM","5","8","8","Bayi suna mulki a kanmu, kuma ba wanda zai ’yantar da mu daga hannuwansu. ");
INSERT INTO hausa_vpl VALUES ("LM5_9","026_5_9","LAM","5","9","9","Muna samun burodi a bakin rayukanmu domin takobin da yake a jeji. ");
INSERT INTO hausa_vpl VALUES ("LM5_10","026_5_10","LAM","5","10","10","Fatar jikinmu ta yi zafi kamar murhu, muna jin zazzaɓi domin yunwa. ");
INSERT INTO hausa_vpl VALUES ("LM5_11","026_5_11","LAM","5","11","11","An yi wa mata fyaɗe a cikin Sihiyona, da kuma budurwai a cikin garuruwan Yahuda. ");
INSERT INTO hausa_vpl VALUES ("LM5_12","026_5_12","LAM","5","12","12","An rataye ’ya’yan sarakuna da hannuwansu; ba a ba wa dattawa girma. ");
INSERT INTO hausa_vpl VALUES ("LM5_13","026_5_13","LAM","5","13","13","Samari suna faman yin niƙa; yara kuma suna fama da ƙyar da nauyin kayan itace. ");
INSERT INTO hausa_vpl VALUES ("LM5_14","026_5_14","LAM","5","14","14","Dattawan sun bar ƙofar birnin, samari sun daina rera waƙa. ");
INSERT INTO hausa_vpl VALUES ("LM5_15","026_5_15","LAM","5","15","15","Farin ciki ya rabu da zuciyarmu; rayuwarmu ta zama makoki. ");
INSERT INTO hausa_vpl VALUES ("LM5_16","026_5_16","LAM","5","16","16","Rawani ya fāɗi daga kanmu. Kaiton mu gama mun yi zunubi! ");
INSERT INTO hausa_vpl VALUES ("LM5_17","026_5_17","LAM","5","17","17","Domin wannan zuciyarmu ta yi sanyi; domin waɗannan abubuwa idanunmu sun dushe ");
INSERT INTO hausa_vpl VALUES ("LM5_18","026_5_18","LAM","5","18","18","gama Tudun Sihiyona ya zama kufai, sai diloli ke yawo a wurin. ");
INSERT INTO hausa_vpl VALUES ("LM5_19","026_5_19","LAM","5","19","19","Ya Ubangiji, kai ne mai iko har abada; kursiyinka ya dawwama cikin dukan zamani. ");
INSERT INTO hausa_vpl VALUES ("LM5_20","026_5_20","LAM","5","20","20","Don mene ne kake mantawa da mu koyaushe? Me ya sa ka yashe mu da jimawa? ");
INSERT INTO hausa_vpl VALUES ("LM5_21","026_5_21","LAM","5","21","21","Ka sāke jawo mu gare ka, ya Ubangiji, don mu komo; ka sabunta kwanakinmu su zama kamar yadda suke a dā ");
INSERT INTO hausa_vpl VALUES ("LM5_22","026_5_22","LAM","5","22","22","sai dai in ka ƙi mu gaba ɗaya kana fushi da mu fiye da yadda za a iya aunawa.");
INSERT INTO hausa_vpl VALUES ("EK1_1","027_1_1","EZK","1","1","1","A shekara ta talatin, a wata na huɗu a rana biyar, yayinda nake cikin ’yan zaman bauta kusa da Kogin Kebar, sai sammai suka buɗe na kuwa ga wahayoyin Allah. ");
INSERT INTO hausa_vpl VALUES ("EK1_2","027_1_2","EZK","1","2","2","A rana biyar ga wata, a shekara ta biyar ne ta zaman bautan Sarki Yehohiyacin, ");
INSERT INTO hausa_vpl VALUES ("EK1_3","027_1_3","EZK","1","3","3","maganar Ubangiji ta zo wa Ezekiyel firist, ɗan Buzi, kusa da Kogin Kebar a ƙasar Babiloniyawa. A can hannun Ubangiji yana a kansa. ");
INSERT INTO hausa_vpl VALUES ("EK1_4","027_1_4","EZK","1","4","4","Na duba, sai na ga guguwa ta taso daga arewa babban hadari cike da walƙiya kewaye da haske mai haske sosai. Tsakiyar wutar ta yi kamar ƙarfe mai cin wuta balbal, ");
INSERT INTO hausa_vpl VALUES ("EK1_5","027_1_5","EZK","1","5","5","a cikin wutar kuwa akwai abin da ya yi kamar halittu guda huɗu. A bayyane kamanninsu ya yi kamar siffar mutum, ");
INSERT INTO hausa_vpl VALUES ("EK1_6","027_1_6","EZK","1","6","6","amma kowannensu yana da fuskoki huɗu da fikafikai guda huɗu. ");
INSERT INTO hausa_vpl VALUES ("EK1_7","027_1_7","EZK","1","7","7","Ƙafafunsu miƙaƙƙu ne; kuma ƙafafunsu sun yi kamar na maraƙi suna kuma walƙiya kamar tagullar da aka goge. ");
INSERT INTO hausa_vpl VALUES ("EK1_8","027_1_8","EZK","1","8","8","A ƙarƙashin fikafikansu huɗu suna da hannuwan mutum a kowane gefe. Dukansu huɗu suna da fuskoki da fikafikai, ");
INSERT INTO hausa_vpl VALUES ("EK1_9","027_1_9","EZK","1","9","9","kuma fikafikansu suna taɓan juna. Kowanne ya miƙe gaba; ba sa juyawa sa’ad da suke tafiya. ");
INSERT INTO hausa_vpl VALUES ("EK1_10","027_1_10","EZK","1","10","10","Fuskokinsu sun yi kamar haka. Kowanne a cikin huɗun yana da fuskar mutum, kuma a gefen dama kowanne yana da fuskar zaki, a hagu kuma fuskar maraƙi; kowanne yana kuma da fuskar gaggafa. ");
INSERT INTO hausa_vpl VALUES ("EK1_11","027_1_11","EZK","1","11","11","Haka fuskokinsu suka kasance. Fikafikansu sun buɗu sama; kowanne yana da fikafikai biyu, ɗaya yana taɓa fikafikan ɗayan halittar a ɗayan gefe, fikafikai biyu kuma suna rufe jikinsa. ");
INSERT INTO hausa_vpl VALUES ("EK1_12","027_1_12","EZK","1","12","12","Kowanne ya miƙe gaba sosai. Duk inda ruhu zai tafi, can za su, ba tare da juyawa ba yayinda suke tafiya. ");
INSERT INTO hausa_vpl VALUES ("EK1_13","027_1_13","EZK","1","13","13","Kamannin halittun ya yi kamar garwashi mai cin wuta ko kuwa kamar fitilu. Wuta tana kai da kawowa a cikin halittun; ta yi haske ƙwarai, walƙiya kuma tana wulgawa daga cikinta. ");
INSERT INTO hausa_vpl VALUES ("EK1_14","027_1_14","EZK","1","14","14","Halittun suna gaggauta kai da kawowa kamar walƙiya. ");
INSERT INTO hausa_vpl VALUES ("EK1_15","027_1_15","EZK","1","15","15","Yayinda nake kallon rayayyun halittun nan, sai na ga da’ira a ƙasa kusa da kowace halitta da fuskokinsa huɗu. ");
INSERT INTO hausa_vpl VALUES ("EK1_16","027_1_16","EZK","1","16","16","Ga kamanni da fasalin da’irorin. Suna ƙyalƙyali kamar kirisolit, kuma dukan huɗun sun yi kama da juna. Kowacce ta yi kamar da’ira a cikin da’ira. ");
INSERT INTO hausa_vpl VALUES ("EK1_17","027_1_17","EZK","1","17","17","Yayinda suke tafiya, sukan nufi duk wani gefe guda cikin gefe huɗun da halittun suka nufa; da’irorin ba za su juya ba sa’ad da halittun suke tafiya. ");
INSERT INTO hausa_vpl VALUES ("EK1_18","027_1_18","EZK","1","18","18","Ƙarafansu da suka yi kamar zobe sun yi tsayi suna kuma da bantsoro, dukan ƙarafan nan huɗu kuwa da suka yi kamar zobe suna cike da idanu a kewaye. ");
INSERT INTO hausa_vpl VALUES ("EK1_19","027_1_19","EZK","1","19","19","Sa’ad da rayayyun halittun suke tafiya, da’irorin da suke kusa da su kan motsa; kuma sa’ad da rayayyun halittun sun tashi sama, da’irorin su ma sukan tashi sama. ");
INSERT INTO hausa_vpl VALUES ("EK1_20","027_1_20","EZK","1","20","20","Duk inda ruhu za shi, su ma can za su, kuma da’irorin za su tashi tare da su, domin ruhun rayayyun halittun nan yana a cikin da’irorin. ");
INSERT INTO hausa_vpl VALUES ("EK1_21","027_1_21","EZK","1","21","21","Sa’ad da halittun sun motsa, sai su ma su motsa; sa’ad da halittun sun tsaya cik, su ma sai su tsaya cik, sa’ad da kuma halittun sukan tashi sama, da’irorin suka tashi tare da su, domin ruhun rayayyun halittun nan yana a cikin da’irorin. ");
INSERT INTO hausa_vpl VALUES ("EK1_22","027_1_22","EZK","1","22","22","A bisa kawunan rayayyun halittun nan akwai abin da ya yi kamar ƙanƙara, mai bantsoro. ");
INSERT INTO hausa_vpl VALUES ("EK1_23","027_1_23","EZK","1","23","23","A ƙarƙashin al’arshin fikafikansu sun miƙe kyam ɗaura da juna, kuma kowanne yana da fikafikai biyu da suka rufe jikinsa. ");
INSERT INTO hausa_vpl VALUES ("EK1_24","027_1_24","EZK","1","24","24","Sa’ad da halittun suke tafiya, sai na ji ƙarar fikafikansu, kamar rurin ruwaye masu gudu, kamar muryar Maɗaukaki, kamar hayaniyar rundunar mayaƙa. In sun tsaya cik, sukan sauko da fikafikansu. ");
INSERT INTO hausa_vpl VALUES ("EK1_25","027_1_25","EZK","1","25","25","Sai aka ji murya daga al’arshi a kan kawunansu yayinda suke tsaye da fikafikansu a sauke. ");
INSERT INTO hausa_vpl VALUES ("EK1_26","027_1_26","EZK","1","26","26","A bisa al’arshin a kan kawunansu akwai abin da ya yi kamar saffaya, kuma a can bisa a kan kursiyin akwai siffa kamar na mutum. ");
INSERT INTO hausa_vpl VALUES ("EK1_27","027_1_27","EZK","1","27","27","Na ga daga abin da ya yi kamar kwankwasonsa zuwa bisa ya yi kamar ƙarfe mai walƙiya, sai ka ce wuta, kuma daga kwankwasonsa zuwa ƙasa ya yi kamar wuta; haske kuma mai walƙiya sosai kewaye da shi. ");
INSERT INTO hausa_vpl VALUES ("EK1_28","027_1_28","EZK","1","28","28","Kamar kamannin bakan gizo a cikin gizagizai a ranar da aka yi ruwan sama, haka hasken da ya kewaye shi. Wannan shi ne kwatancin kamannin ɗaukakar Ubangiji. Sa’ad da na gani, sai na fāɗi rubda ciki, na kuma ji muryar wani tana magana. ");
INSERT INTO hausa_vpl VALUES ("EK2_1","027_2_1","EZK","2","1","1","Ya ce mini, “Ɗan mutum, tashi ka tsaya a ƙafafunka zan kuma yi maka magana.” ");
INSERT INTO hausa_vpl VALUES ("EK2_2","027_2_2","EZK","2","2","2","Yayinda yake magana, sai Ruhu ya sauko mini ya kuma tā da ni a ƙafafuna, na kuma ji shi yana mini magana. ");
INSERT INTO hausa_vpl VALUES ("EK2_3","027_2_3","EZK","2","3","3","Ya ce, “Ɗan mutum, ina aikan ka zuwa ga Isra’ilawa, zuwa ga al’ummar ’yan tawayen nan da suka yi mini tayarwa; su da kakanninsu sun yi mini tawaye har yă zuwa yau. ");
INSERT INTO hausa_vpl VALUES ("EK2_4","027_2_4","EZK","2","4","4","Mutanen da nake aikan ka masu ƙin ji ne da kuma taurinkai. Ka faɗa musu cewa, ‘Ga abin da Ubangiji Mai Iko Duka ya faɗa.’ ");
INSERT INTO hausa_vpl VALUES ("EK2_5","027_2_5","EZK","2","5","5","Kuma ko su ji ko kada su ji, gama su gida ne mai tawaye, za su san cewa akwai annabi a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("EK2_6","027_2_6","EZK","2","6","6","Kai kuwa, ɗan mutum, kada ka ji tsoro, ko da sarƙaƙƙiya da ƙayayyuwa duk sun kewaye ka kana kuma zama a cikin kunamai. Kada ka ji tsoron abin da za ka faɗa ko ka firgita ta wurinsu, ko da yake su gida ne mai tawaye. ");
INSERT INTO hausa_vpl VALUES ("EK2_7","027_2_7","EZK","2","7","7","Dole ka yi maganata gare su, ko su ji ko kada su ji, gama su ’yan tawaye ne. ");
INSERT INTO hausa_vpl VALUES ("EK2_8","027_2_8","EZK","2","8","8","Amma kai, ɗan mutum, ka saurari abin da zan faɗa maka. Kada ka yi tawaye kamar wannan gidan ’yan tawaye; ka buɗe bakinka ka kuma ci abin da na ba ka.” ");
INSERT INTO hausa_vpl VALUES ("EK2_9","027_2_9","EZK","2","9","9","Sai na duba, na kuma ga hannu ya miƙe zuwa wurina. A cikinsa akwai littafi, ");
INSERT INTO hausa_vpl VALUES ("EK2_10","027_2_10","EZK","2","10","10","wanda ya nannaɗe a gabana. A kowane gefensa akwai rubutun kalmomin makoki da kuka da kuma kaito. ");
INSERT INTO hausa_vpl VALUES ("EK3_1","027_3_1","EZK","3","1","1","Ya kuma ce mini, “Ɗan mutum, ka ci abin da yake a gabanka, ka ci wannan littafi; sa’an nan ka tafi ka yi magana wa gidan Isra’ila.” ");
INSERT INTO hausa_vpl VALUES ("EK3_2","027_3_2","EZK","3","2","2","Saboda haka na buɗe bakina, ya kuma ba ni littafin in ci. ");
INSERT INTO hausa_vpl VALUES ("EK3_3","027_3_3","EZK","3","3","3","Sai ya ce mini, “Ɗan mutum, ka ci wannan littafin da nake ba ka, ka kuma cika cikinka da shi.” Sai na ci shi, ya kuma yi zaki kamar zuma a bakina. ");
INSERT INTO hausa_vpl VALUES ("EK3_4","027_3_4","EZK","3","4","4","Sa’an nan ya ce mini, “Ɗan mutum, yanzu ka tafi gidan Isra’ila ka faɗa kalmomina gare su. ");
INSERT INTO hausa_vpl VALUES ("EK3_5","027_3_5","EZK","3","5","5","Ba ina aikan ka wurin mutanen da suke da baƙon harshe da kuma yare mai wuya ba ne, amma zuwa ga gidan Isra’ila ne, ");
INSERT INTO hausa_vpl VALUES ("EK3_6","027_3_6","EZK","3","6","6","ba ga mutane da yawa na baƙon harshe da yare mai wuya, waɗanda ba ka san kalmominsu ba. Tabbatacce da na aike ka wurin irinsu, da sun saurare ka. ");
INSERT INTO hausa_vpl VALUES ("EK3_7","027_3_7","EZK","3","7","7","Amma gidan Isra’ila ba sa niyya su saurare ka domin ba sa niyya su saurare ni, gama dukan gidan Isra’ila sun taurare suna kuma kin ji. ");
INSERT INTO hausa_vpl VALUES ("EK3_8","027_3_8","EZK","3","8","8","Amma zan sa ka zama mai taurinkai da taurin zuciya kamar su. ");
INSERT INTO hausa_vpl VALUES ("EK3_9","027_3_9","EZK","3","9","9","Zan sa goshinka ya zama da tauri kamar dutse, da tauri fiye da dutsen ƙanƙara ƙarfi. Kada ka ji tsoronsu ko ka firgita ta wurinsu, ko da yake su gidan ’yan tawaye ne.” ");
INSERT INTO hausa_vpl VALUES ("EK3_10","027_3_10","EZK","3","10","10","Ya kuma ce mini, “Ɗan mutum, ka ji da kyau ka kuma lura da dukan kalmomin da nake maka magana. ");
INSERT INTO hausa_vpl VALUES ("EK3_11","027_3_11","EZK","3","11","11","Ka tafi yanzu zuwa ga ’yan’uwanka waɗanda suke zaman bauta ka yi musu magana. Ka ce musu, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa,’ ko ku ji, ko kada ku ji.” ");
INSERT INTO hausa_vpl VALUES ("EK3_12","027_3_12","EZK","3","12","12","Sa’an nan Ruhu ya ɗaga ni sama, a bayana na ji wata karar babban motsi na cewa, Bari a yabi ɗaukakar Ubangiji a wurin zamansa! ");
INSERT INTO hausa_vpl VALUES ("EK3_13","027_3_13","EZK","3","13","13","Karar fikafikan rayayyun halittun nan ne suke goge junansu da kuma karar da’irorin nan da suke kusa da su, ƙarar babban motsi. ");
INSERT INTO hausa_vpl VALUES ("EK3_14","027_3_14","EZK","3","14","14","Sa’an nan Ruhu ya ɗaga ni sama ya kuma tafi da ni, na kuwa tafi da ɓacin rai da kuma fushin ruhuna, tare da hannu mai ƙarfi na Ubangiji a bisa na. ");
INSERT INTO hausa_vpl VALUES ("EK3_15","027_3_15","EZK","3","15","15","Na zo wurin masu zaman bautan da suke zama a Tel Abib kusa da Kogin Kebar, A can kuwa, inda suke zama, na zauna a cikinsu kwana bakwai, ina mamaki. ");
INSERT INTO hausa_vpl VALUES ("EK3_16","027_3_16","EZK","3","16","16","A ƙarshen kwana bakwai ɗin maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK3_17","027_3_17","EZK","3","17","17","“Ɗan mutum, na mai da kai mai tsaro don gidan Isra’ila; saboda haka ka ji maganar da zan yi ka kuma yi musu kashedin nan da ya fito daga gare ni. ");
INSERT INTO hausa_vpl VALUES ("EK3_18","027_3_18","EZK","3","18","18","In na ce wa mugu, ‘Lalle za ka mutu,’ ba ka kuwa yi masa kashedi ko ka tsawata masa a kan mugayen hanyoyinsa don yă ceci ransa ba, wannan mugun zai mutu saboda zunubinsa, zan kuwa nemi hakkin jininsa a hannunka. ");
INSERT INTO hausa_vpl VALUES ("EK3_19","027_3_19","EZK","3","19","19","Amma in ka yi wa mugun kashedi bai kuwa juya daga mugayen hanyoyinsa ba, zai mutu saboda zunubinsa; amma kai kam za ka kuɓuta. ");
INSERT INTO hausa_vpl VALUES ("EK3_20","027_3_20","EZK","3","20","20","“Har yanzu, in mai adalci ya juya daga adalcinsa ya aikata mugunta, na kuma sa abin tuntuɓe a gabansa, zai mutu. Da yake ba ka yi masa kashedi ba, zai mutu saboda zunubinsa. Ba za a tuna da abin adalcin da ya yi ba, zan kuwa nemi hakkin jininsa a hannunka. ");
INSERT INTO hausa_vpl VALUES ("EK3_21","027_3_21","EZK","3","21","21","Amma in ka yi wa mai adalcin kashedi kada yă yi zunubi bai kuwa yi zunubi ba, tabbatacce zai rayu saboda ya ji kashedin, kuma kai kam za ka kuɓuta.” ");
INSERT INTO hausa_vpl VALUES ("EK3_22","027_3_22","EZK","3","22","22","Hannun Ubangiji ya kasance a kaina a can, ya kuma ce mini, “Tashi ka fita zuwa fili, a can kuwa zan yi maka magana.” ");
INSERT INTO hausa_vpl VALUES ("EK3_23","027_3_23","EZK","3","23","23","Saboda haka na tashi da tafi fili. Ɗaukakar Ubangiji kuwa ta tsaya a can, kamar ɗaukakar da na gani kusa da Kogin Kebar, sai na fāɗi rubda ciki. ");
INSERT INTO hausa_vpl VALUES ("EK3_24","027_3_24","EZK","3","24","24","Sai Ruhu ya sauko a kaina ya kuma ɗaga ni na tsaya a ƙafafuna. Ya yi mini magana ya ce, “Ka fita, ka rufe kanka a cikin gida. ");
INSERT INTO hausa_vpl VALUES ("EK3_25","027_3_25","EZK","3","25","25","Kuma kai, ɗan mutum, za su ɗaura ka da igiyoyi; za a daure ka yadda ba za ka iya fita a cikin mutane ba. ");
INSERT INTO hausa_vpl VALUES ("EK3_26","027_3_26","EZK","3","26","26","Zan sa harshenka ya manne wa dasashinka don ka yi shiru ka kuma kāsa tsawata musu, ko da yake su gidan ’yan tawaye ne. ");
INSERT INTO hausa_vpl VALUES ("EK3_27","027_3_27","EZK","3","27","27","Amma sa’ad da na yi maka magana, zan buɗe bakinka za ka kuwa faɗa musu cewa, ‘Ga abin da Ubangiji Mai Iko Duka ya faɗa.’ Duk mai ji ya ji, kuma duk wanda ya ƙi ji, ya ƙi ji; gama su gida ne na ’yan tawaye. ");
INSERT INTO hausa_vpl VALUES ("EK4_1","027_4_1","EZK","4","1","1","“Yanzu, ɗan mutum, ka ɗauki tubalin yumɓu, ka ajiye shi a gabanka ka kuma zāna birnin Urushalima a kansa. ");
INSERT INTO hausa_vpl VALUES ("EK4_2","027_4_2","EZK","4","2","2","Sa’an nan ka yi mata ƙawanya. Ka kafa mata katangar ƙawanya, ka gina katangar da ɗan tudu ka kewaye ta da dundurusai. ");
INSERT INTO hausa_vpl VALUES ("EK4_3","027_4_3","EZK","4","3","3","Sa’an nan ka ɗauki kwanon ƙarfe, ka shirya shi kamar katangar ƙarfe tsakaninka da birnin ka kuma zuba mata ido. Za tă kasance a ƙarƙashin ƙawanya, kai kuwa za ka yi mata ƙawanya. Wannan zai zama alama ga gidan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK4_4","027_4_4","EZK","4","4","4","“Sa’an nan ka kwanta a hagunka ka kuma sa zunubin gidan Isra’ila a kanka. Za ka ɗauki zunubinsu na waɗansu kwanakin da kake kwance a gefenka. ");
INSERT INTO hausa_vpl VALUES ("EK4_5","027_4_5","EZK","4","5","5","Na ɗora maka kwanaki bisa ga shekarun zunubinsu. Saboda haka cikin kwana 390 za ka ɗauki zunubin gidan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK4_6","027_4_6","EZK","4","6","6","“Bayan ka gama haka, ka sāke kwantawa, a wannan lokaci a gefen damarka, ka kuma ɗauki zunubin gidan Yahuda. Na ɗora maka kwanaki 40, kwana guda a madadin shekara guda. ");
INSERT INTO hausa_vpl VALUES ("EK4_7","027_4_7","EZK","4","7","7","Ka juya fuskarka wajen ƙawanyar Urushalima da hannunka a buɗe ka yi annabci a kanta. ");
INSERT INTO hausa_vpl VALUES ("EK4_8","027_4_8","EZK","4","8","8","Zan ɗaura ka da igiyoyi don kada ka juya daga wannan gefe zuwa wani gefe sai ka gama kwanakin ƙawanyarka. ");
INSERT INTO hausa_vpl VALUES ("EK4_9","027_4_9","EZK","4","9","9","“Ka ɗauki alkama da sha’ir, wake da acca, gero da maiwa; ka sa su a tulun ajiya ka kuma yi amfani da su don yin burodi wa kanka. Za ka ci shi a kwanaki 390 da za ka kwanta a gefenka. ");
INSERT INTO hausa_vpl VALUES ("EK4_10","027_4_10","EZK","4","10","10","Ka auna shekel ashirin na abinci don kowace rana ka kuma ci shi a ƙayyadadden lokaci. ");
INSERT INTO hausa_vpl VALUES ("EK4_11","027_4_11","EZK","4","11","11","Haka ma ka auna kashi ɗaya bisa shida na garwan ruwa ka sha shi a ƙayyadadden lokaci. ");
INSERT INTO hausa_vpl VALUES ("EK4_12","027_4_12","EZK","4","12","12","Ka ci abinci yadda za ka ci ƙosai sha’ir, ka gasa shi a gaban mutane, ka yi amfani da najasar mutane kamar itacen wuta.” ");
INSERT INTO hausa_vpl VALUES ("EK4_13","027_4_13","EZK","4","13","13","Ubangiji ya ce, “Ta haka mutanen Isra’ila za su ci ƙazantaccen abinci a cikin al’ummai inda zan kore su in kai.” ");
INSERT INTO hausa_vpl VALUES ("EK4_14","027_4_14","EZK","4","14","14","Sai na ce, “Ba haka ba ne, Ubangiji Mai Iko Duka! Ban taɓa ƙazantar da kaina ba. Daga ƙuruciyata har zuwa yanzu ban taɓa cin wani abin da aka samu ya mutu ko abin da namun jeji suka kashe ba. Ba nama marar tsabtan da ya taɓa shiga bakina.” ");
INSERT INTO hausa_vpl VALUES ("EK4_15","027_4_15","EZK","4","15","15","Sai ya ce, “To da kyau, zan bari ka gasa burodin a kan kashin shanu a maimakon najasar mutane.” ");
INSERT INTO hausa_vpl VALUES ("EK4_16","027_4_16","EZK","4","16","16","Sa’an nan ya ce mini, “Ɗan mutum, zan yanke tanadin abinci a Urushalima. Mutane za su auna abincin da za su ci da tsoro su kuma auna ruwan da za su sha cikin fargaba, ");
INSERT INTO hausa_vpl VALUES ("EK4_17","027_4_17","EZK","4","17","17","domin abinci da ruwa za su kāsa. Za su damu da ganin juna za su kuma lalace saboda zunubinsu. ");
INSERT INTO hausa_vpl VALUES ("EK5_1","027_5_1","EZK","5","1","1","“Yanzu, ɗan mutum, ka ɗauki takobi mai kaifi ka kuma yi amfani da shi kamar rezan mai aski don askin kanka da gemunka. Sa’an nan ka ɗauki ma’auni ka kuma raba gashin. ");
INSERT INTO hausa_vpl VALUES ("EK5_2","027_5_2","EZK","5","2","2","Sa’ad da kwanakin ƙawanyarka sun ƙare, sai ka ƙone kashi ɗaya bisa uku na gashin da wuta a cikin birnin. Ka ɗauki kashi ɗaya bisa uku ka yayyanka shi da takobi kewaye da birnin. Ka kuma watsar da kashi ɗaya bisa uku a iska. Gama zan fafare su da takobin da aka zāre. ");
INSERT INTO hausa_vpl VALUES ("EK5_3","027_5_3","EZK","5","3","3","Amma ka ɗibi gashi kaɗan ka daure a shafin rigarka. ");
INSERT INTO hausa_vpl VALUES ("EK5_4","027_5_4","EZK","5","4","4","Har yanzu, ka ɗibi kaɗan na waɗannan ka zuba su cikin wuta su kuma ƙone. Wuta zai bazu daga nan zuwa dukan gidan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK5_5","027_5_5","EZK","5","5","5","“Ga abin da Ubangiji Mai Iko Duka ya ce Urushalima ce wannan, wadda na kafa a tsakiyar al’ummai, da ƙasashe kewaye da ita a ko’ina. ");
INSERT INTO hausa_vpl VALUES ("EK5_6","027_5_6","EZK","5","6","6","Duk da haka cikin muguntarta ta yi tayarwa a kan dokokina da ƙa’idodina fiye da al’ummai da ƙasashe kewaye da ita. Ta ƙi dokokina ba tă kuwa bi ƙa’idodina ba. ");
INSERT INTO hausa_vpl VALUES ("EK5_7","027_5_7","EZK","5","7","7","“Saboda haka ga abin da Ubangiji Mai Iko Duka ya ce kin yi ƙin ji fiye da al’umman da suke kewaye da ke ba ki kuma bi ƙa’idodina ko ki kiyaye dokokina ba. Ba ki ma dace da matsayin al’umman da suke kewaye da ke ba. ");
INSERT INTO hausa_vpl VALUES ("EK5_8","027_5_8","EZK","5","8","8","“Saboda haka ga abin da Ubangiji Mai Iko Duka ya ce Ni kaina ina gāba da ke, Urushalima, kuma zan hukunta ki a gaban al’ummai. ");
INSERT INTO hausa_vpl VALUES ("EK5_9","027_5_9","EZK","5","9","9","Saboda dukan gumakan banƙyamarki, zan yi abin da ban taɓa yi ba, ba kuwa zan ƙara yinsa ba. ");
INSERT INTO hausa_vpl VALUES ("EK5_10","027_5_10","EZK","5","10","10","Saboda haka a cikinki ubanni za su ci ’ya’yansu, ’ya’ya kuma za su ci ubanninsu. Zan hukunta ki zan kuma watsar da dukan waɗanda suke tsira da suke naki a iska. ");
INSERT INTO hausa_vpl VALUES ("EK5_11","027_5_11","EZK","5","11","11","Saboda haka muddin ina a raye, in ji Ubangiji Mai Iko Duka, domin kin ƙazantar da wuri mai tsarkina da dukan mugayen siffofinki da kuma ayyukanki masu banƙyama, ni kaina zan janye alherina; ba zan ji tausayinki ko in haƙura da ke ba. ");
INSERT INTO hausa_vpl VALUES ("EK5_12","027_5_12","EZK","5","12","12","Kashi ɗaya bisa uku na mutanenki za su mutu da annoba ko su mutu da yunwa a cikinki; kashi ɗaya bisa uku takobi ne zai kashe su a waje da katangarki; kashi ɗaya bisa uku kuma zan watsar a iska in kuma fafare su da takobin da aka zāre. ");
INSERT INTO hausa_vpl VALUES ("EK5_13","027_5_13","EZK","5","13","13","“Sa’an nan ne fushina zai huce hasalata a kanki kuma ta lafa, in kuma wartsake. Kuma sa’ad da na zuba fushina a kansu, a sa’an nan ne za su san cewa Ni Ubangiji na yi magana a cikin fushin kishina a kansu. ");
INSERT INTO hausa_vpl VALUES ("EK5_14","027_5_14","EZK","5","14","14","“Zan mai da ki kufai da kuma abin dariya a cikin al’ummai kewaye da ke, a gaban dukan waɗanda suke wucewa. ");
INSERT INTO hausa_vpl VALUES ("EK5_15","027_5_15","EZK","5","15","15","Za ki zama abin dariya da abin ba’a, kashedi da abin banrazana ga al’ummai kewaye da ke sa’ad da na hukunta ki cikin fushi da cikin hasala da kuma tsawatawa mai zafi. Ni Ubangiji na faɗa. ");
INSERT INTO hausa_vpl VALUES ("EK5_16","027_5_16","EZK","5","16","16","Sa’ad da na harbe ki da mugayen kibiyoyina da kuma kibiyoyi masu hallakarwa na yunwa, zan yi harbi don in kashe ki. Zan kawo ƙarin yunwa a kanki in kuma yanke tanadin abincinki. ");
INSERT INTO hausa_vpl VALUES ("EK5_17","027_5_17","EZK","5","17","17","Zan aika da yunwa da namun jeji a kanki, za su kuma bar ku ba ’ya’ya. Annoba da zub da jini za su ratsa cikinki, zan kuma kawo takobi a kanki. Ni Ubangiji na faɗa.” ");
INSERT INTO hausa_vpl VALUES ("EK6_1","027_6_1","EZK","6","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK6_2","027_6_2","EZK","6","2","2","“Ɗan mutum, ka kafa idonka a kan duwatsun Isra’ila; ka yi annabci a kansu ");
INSERT INTO hausa_vpl VALUES ("EK6_3","027_6_3","EZK","6","3","3","ka ce, ‘Ya ku duwatsun Isra’ila, ku ji maganar Ubangiji Mai Iko Duka. Ga abin da Ubangiji Mai Iko Duka ya ce wa duwatsu da tuddai, ga rafuffuka da kuma kwaruruka. Ina shirin kawo takobi a kanku, kuma zan hallaka masujadanku. ");
INSERT INTO hausa_vpl VALUES ("EK6_4","027_6_4","EZK","6","4","4","Za a ragargaza bagadanku a kuma farfasa bagadanku na ƙone turare; zan kuma kashe mutanenku a gaban gumakanku. ");
INSERT INTO hausa_vpl VALUES ("EK6_5","027_6_5","EZK","6","5","5","Zan shimfiɗa gawawwakin Isra’ilawa a gaban gumakansu, in kuma watsar da ƙasusuwanku kewaye da bagadanku. ");
INSERT INTO hausa_vpl VALUES ("EK6_6","027_6_6","EZK","6","6","6","Duk inda kuke zama, garuruwa za su zama kango, za a kuma ragargaza masujadai, saboda bagadanku su rurrushe su zama kango, a kuma farfasa gumakanku su lalace, za a rurrushe bagadan ƙone turarenku, a kuma shafe dukan abin da kuka yi. ");
INSERT INTO hausa_vpl VALUES ("EK6_7","027_6_7","EZK","6","7","7","Za a kashe mutanenku a cikinku, za ku kuwa sani ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK6_8","027_6_8","EZK","6","8","8","“ ‘Amma zan bar waɗansu, gama waɗansunku za su tsere wa takobi sa’ad da aka watsar da ku a cikin ƙasashe da al’ummai. ");
INSERT INTO hausa_vpl VALUES ("EK6_9","027_6_9","EZK","6","9","9","Sa’an nan a cikin al’ummai inda aka kai ku zaman bauta, waɗanda suka a tsere za su tuna da ni, yadda raina ya ɓaci ta wurin zukatansu marasa imani, waɗanda suka rabu da ni, da kuma ta wurin idanunsu, waɗanda suka yi sha’awace-sha’awacen gumakansu. Za su ji ƙyamar kansu saboda mugayen abubuwan da suka aikata. ");
INSERT INTO hausa_vpl VALUES ("EK6_10","027_6_10","EZK","6","10","10","Za su kuwa san cewa ni ne Ubangiji; ba a banza na ce zan kawo musu wannan masifa ba. ");
INSERT INTO hausa_vpl VALUES ("EK6_11","027_6_11","EZK","6","11","11","“ ‘Ga abin da Ubangiji Mai Iko Duka ya ce ku tafa hannuwanku tare ku kuma taka ƙafafunku ku yi ihu ku ce, “Kaito!” Saboda dukan mugaye da kuma abubuwan banƙyama na gidan Isra’ila, gama za su mutu ta wurin takobi, yunwa da annoba. ");
INSERT INTO hausa_vpl VALUES ("EK6_12","027_6_12","EZK","6","12","12","Wanda yake da nisa zai mutu da annoba, shi da yake kusa kuma zai mutu ta takobi, wanda kuma ya tsira aka kuma bari zai mutu da yunwa. Ta haka zan aukar da fushina a kansu. ");
INSERT INTO hausa_vpl VALUES ("EK6_13","027_6_13","EZK","6","13","13","Za su kuwa san cewa ni ne Ubangiji, sa’ad da gawawwakin mutanensu suna kwance a kusa da gumakansu da kewaye da bagadansu, a kowane kan tudu mai tsawo da kuma a kan dukan kan duwatsu, a ƙarƙashin kowane inuwar itace da kuma kowane oak mai ganye, wuraren da suke ƙone turare masu ƙanshi wa dukan gumakansu. ");
INSERT INTO hausa_vpl VALUES ("EK6_14","027_6_14","EZK","6","14","14","Zan kuma miƙa hannuna a kansu in mai da ƙasarsu kango daga hamadan Dibila, a duk inda suke zama. Sa’an nan za su san cewa ni ne Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK7_1","027_7_1","EZK","7","1","1","Maganar Ubangiji ta zo gare ni cewa, ");
INSERT INTO hausa_vpl VALUES ("EK7_2","027_7_2","EZK","7","2","2","“Ɗan mutum, ga abin da Ubangiji Mai Iko Duka yake cewa wa ƙasar Isra’ila, “ ‘Ƙarshe ya zo! Ƙarshe ya zo a kan kusurwoyi huɗu na ƙasar. ");
INSERT INTO hausa_vpl VALUES ("EK7_3","027_7_3","EZK","7","3","3","Ƙarshe yanzu yana a kanki. Zan fashe fushina a kanki. Zan shari’anta ki bisa ga halinki in sāka miki kuma saboda dukan ayyukan banƙyamar da kika yi. ");
INSERT INTO hausa_vpl VALUES ("EK7_4","027_7_4","EZK","7","4","4","Ba zan dube ki da tausayi; ko in ƙyale ki ba. Tabbatacce zan sāka miki saboda halinki da kuma ayyukanki masu banƙyama a cikinki. Sa’an nan za ki san cewa ni ne Ubangiji.’ ");
INSERT INTO hausa_vpl VALUES ("EK7_5","027_7_5","EZK","7","5","5","“Ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Masifa! Masifar da ba a taɓa gani ba tana zuwa. ");
INSERT INTO hausa_vpl VALUES ("EK7_6","027_7_6","EZK","7","6","6","Ƙarshe ya zo! Ƙarshe ya zo! Ya farka a kanki. Ga shi, ya zo! ");
INSERT INTO hausa_vpl VALUES ("EK7_7","027_7_7","EZK","7","7","7","Ƙaddara ta auko miki, ya ke wadda ke zama cikin ƙasar. Lokaci ya yi, rana ta gabato; akwai fargaba, ba farin ciki ba, a kan duwatsu. ");
INSERT INTO hausa_vpl VALUES ("EK7_8","027_7_8","EZK","7","8","8","Ina gab da fasa hasalata a kanki in kuma aukar da fushina a kanki; zan shari’anta ke bisa ga halinki in kuma sāka miki saboda dukan ayyukanki masu banƙyama. ");
INSERT INTO hausa_vpl VALUES ("EK7_9","027_7_9","EZK","7","9","9","Ba zan dube ki da tausayi ko in ƙyale ke ba; zan sāka miki bisa ga halinki da kuma ayyukan masu banƙyama a cikinki. Sa’an nan za ki san cewa ni ne Ubangiji wanda yake bugunki. ");
INSERT INTO hausa_vpl VALUES ("EK7_10","027_7_10","EZK","7","10","10","“ ‘Ga shi ranar ta zo! Ta iso! Ƙaddararki ta keto, sandar ta yi toho, girman kai ya yi fure! ");
INSERT INTO hausa_vpl VALUES ("EK7_11","027_7_11","EZK","7","11","11","Rikici ya yi girma ya zama sandar da za a hukunta mugunta; babu wani daga cikin mutanen da za a bari, babu wani dukiyarsu da za a bari, babu wani abin amfani. ");
INSERT INTO hausa_vpl VALUES ("EK7_12","027_7_12","EZK","7","12","12","Lokaci ya yi! Ranar ta gabato! Kada mai saya ya yi farin ciki ko kuwa mai sayarwa ya yi baƙin ciki, gama hasala tana a kan dukan jama’a. ");
INSERT INTO hausa_vpl VALUES ("EK7_13","027_7_13","EZK","7","13","13","Mai sayarwa ba zai mayar da ƙasar da ya sayar tuntuni ba muddin dukansu suna da rai, gama ba za a sauya wahayin da ya shafi dukan jama’a ba. Saboda zunubansu, babu ɗayansu da zai adana ransa. ");
INSERT INTO hausa_vpl VALUES ("EK7_14","027_7_14","EZK","7","14","14","“ ‘Ko da yake suna busa ƙaho suna kuma shirya kome, ba wanda zai tafi yaƙi, gama hasalata tana a kan dukan jama’a. ");
INSERT INTO hausa_vpl VALUES ("EK7_15","027_7_15","EZK","7","15","15","A waje takobi ne, a ciki annoba ne da yunwa; waɗanda suke fili za su mutu ta wurin takobi, waɗanda kuma suke cikin birni yunwa da annoba za su cinye su. ");
INSERT INTO hausa_vpl VALUES ("EK7_16","027_7_16","EZK","7","16","16","Duk waɗanda suka tsira suka tsere za su kasance a cikin duwatsu, suna kuka kamar kurciyoyin kwaruruka, kowanne saboda zunubansa. ");
INSERT INTO hausa_vpl VALUES ("EK7_17","027_7_17","EZK","7","17","17","Kowane hannu zai raunana, kowace gwiwa kuma za tă zama marar ƙarfi kamar ruwa. ");
INSERT INTO hausa_vpl VALUES ("EK7_18","027_7_18","EZK","7","18","18","Za su sa tufafin makoki su kuma rufu da fargaba. Fuskokinsu kuma za su rufu da kunya a kuma aske kawunansu. ");
INSERT INTO hausa_vpl VALUES ("EK7_19","027_7_19","EZK","7","19","19","“ ‘Za su zubar da azurfarsu a tituna, zinariyarsu kuma za tă zama ƙazantacciyar aba. Azurfarsu da zinariyarsu ba za su iya cetonsu a ranar hasalar Ubangiji ba. Ba za su ƙosar da yunwansu ko su cika cikinsu da shi ba, gama su ne sanadin tuntuɓensu cikin zunubi. ");
INSERT INTO hausa_vpl VALUES ("EK7_20","027_7_20","EZK","7","20","20","Sun yi fariya kyan kayan adonsu suka kuma yi amfani da su don su yi gumakansu masu banƙyama, da ƙazantattun abubuwa. ");
INSERT INTO hausa_vpl VALUES ("EK7_21","027_7_21","EZK","7","21","21","Zan ba da su duka kamar ganima ga baƙi da kuma kamar abin da aka washe ga mugayen duniya, za su kuma ƙazantar da su. ");
INSERT INTO hausa_vpl VALUES ("EK7_22","027_7_22","EZK","7","22","22","Zan juye fuskata daga gare su, za su kuwa ƙazantar da wurina mai daraja; ’yan fashi za su shiga su kuma ƙazantar da shi. ");
INSERT INTO hausa_vpl VALUES ("EK7_23","027_7_23","EZK","7","23","23","“ ‘Ka shirya sarƙoƙi, domin ƙasar ta cika da alhakin jini, birnin kuma ya cika da rikici. ");
INSERT INTO hausa_vpl VALUES ("EK7_24","027_7_24","EZK","7","24","24","Zan kawo al’ummai mafi mugunta su mallaki gidajenku; zan kawo ƙarshen fariyar masu ƙarfi, Wurare Masu Tsarkinsu za su ƙazantu. ");
INSERT INTO hausa_vpl VALUES ("EK7_25","027_7_25","EZK","7","25","25","Sa’ad da wahala ta zo, za su nemi salama, amma ba za su same ta ba. ");
INSERT INTO hausa_vpl VALUES ("EK7_26","027_7_26","EZK","7","26","26","Masifa a kan masifa za su zo, jita-jita kuma a kan jita-jita. Za su yi ƙoƙarin samun wahayi daga annabi; koyarwar doka ta wurin firist za tă ɓace, kamar yadda shawarar dattawa za tă ɓace. ");
INSERT INTO hausa_vpl VALUES ("EK7_27","027_7_27","EZK","7","27","27","Sarki zai yi makoki, yerima zai fid da zuciya, hannuwan mutanen ƙasar kuma za su yi rawa. Zan sāka musu bisa ga ayyukansu, zan kuma hukunta su bisa ga ma’auninsu. Sa’an nan za su san cewa ni ne Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK8_1","027_8_1","EZK","8","1","1","A shekara ta shida, a wata shida a ranar ta biya, yayinda nake zaune a gidana dattawan Yahuda kuma suna zaune a gabana, hannun Ubangiji Mai Iko Duka ya zo a kaina a can. ");
INSERT INTO hausa_vpl VALUES ("EK8_2","027_8_2","EZK","8","2","2","Na duba, sai na ga siffa kamar na mutum. Daga kwankwaso zuwa ƙasa ya yi kamar wuta, kuma daga kwankwaso zuwa sama kamanninsa ya yi haske yana ƙyalli kamar ƙarfe mai haske. ");
INSERT INTO hausa_vpl VALUES ("EK8_3","027_8_3","EZK","8","3","3","Ya miƙa abin da ya yi kamar hannu ya kama a gashin kaina. Ruhu ya ɗaga ni tsakanin sama da ƙasa, a cikin wahayoyi kuma Allah ya ɗauke ni zuwa Urushalima, zuwa ƙofa zuwa gabas na cikin fili, inda gunki mai tsokanar kishi yake tsaye. ");
INSERT INTO hausa_vpl VALUES ("EK8_4","027_8_4","EZK","8","4","4","A can gabana kuwa ga ɗaukakar Allah na Isra’ila, kamar a wahayin da na gani a fili. ");
INSERT INTO hausa_vpl VALUES ("EK8_5","027_8_5","EZK","8","5","5","Sai ya ce mini, “Ɗan mutum, duba waje arewa.” Sai na duba, a mashigin arewa na ƙofar bagaden kuwa na ga wannan gunki na tsokanar kishi. ");
INSERT INTO hausa_vpl VALUES ("EK8_6","027_8_6","EZK","8","6","6","Ya kuma ce mini, “Ɗan mutum, ka ga abin da suke yi, abubuwan banƙyamar da gidan Isra’ila ke yi a nan, abubuwan da za su kore ni daga wuri mai tsarkina? Amma za ka ga abubuwan da suka ma fi banƙyama.” ");
INSERT INTO hausa_vpl VALUES ("EK8_7","027_8_7","EZK","8","7","7","Sa’an nan ya kawo ni mashigin filin. Na duba, na kuma ga rami a bango. ");
INSERT INTO hausa_vpl VALUES ("EK8_8","027_8_8","EZK","8","8","8","Ya ce mini, “Ɗan mutum, yanzu ka haƙa cikin bangon.” Da na haƙa cikin bangon sai na ga ƙofar shiga a can. ");
INSERT INTO hausa_vpl VALUES ("EK8_9","027_8_9","EZK","8","9","9","Sai ya ce mini, “Shiga ka ga mugaye da kuma abubuwa banƙyamar da suke yi a can.” ");
INSERT INTO hausa_vpl VALUES ("EK8_10","027_8_10","EZK","8","10","10","Na kuwa shiga na duba, sai na ga zāne-zāne ko’ina a bangon na kowane irin abubuwa masu rarrafe da kuma dabbobi masu ƙazanta da dukan gumakan gidan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK8_11","027_8_11","EZK","8","11","11","A gabansu ga dattawa saba’in na gidan Isra’ila tsaye a cikinsu, Ya’azaniya ɗan Shafan kuwa yana tsaye a cikinsu. Kowa yana da farantin ƙona turare a hannunsa, tulin hayaƙin turare mai ƙanshi ya tunnuƙe zuwa sama. ");
INSERT INTO hausa_vpl VALUES ("EK8_12","027_8_12","EZK","8","12","12","Ya ce mini, “Ɗan mutum, ka ga abin da dattawan gidan Isra’ila suke yi a cikin duhu, kowa yana a ɗakin tsafin gunkinsa? Suna cewa, ‘Ubangiji ba ya ganinmu; Ubangiji ya yashe ƙasar.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK8_13","027_8_13","EZK","8","13","13","Ya kuma ce, “Za ka gan su suna yin abubuwan da suka fi waɗannan banƙyama.” ");
INSERT INTO hausa_vpl VALUES ("EK8_14","027_8_14","EZK","8","14","14","Sa’an nan ya kawo ni mashigin arewa na ƙofar gidan Ubangiji, sai na ga mata zaune a can, suna makokin Tammuz. ");
INSERT INTO hausa_vpl VALUES ("EK8_15","027_8_15","EZK","8","15","15","Ya ce mini, “Ɗan mutum, ka ga wannan? Za ka ga abubuwan da suke masu banƙyama fiye da wannan.” ");
INSERT INTO hausa_vpl VALUES ("EK8_16","027_8_16","EZK","8","16","16","Sa’an nan ya kawo ni cikin fili na cikin gidan Ubangiji, a can kuwa a ƙofar haikali, tsakanin shirayi da bagade, akwai kamar mutum ashirin da biyar. Suka ba haikalin Ubangiji baya suna fuskanta wajen gabas, suna rusuna wa rana a gabas. ");
INSERT INTO hausa_vpl VALUES ("EK8_17","027_8_17","EZK","8","17","17","Ya ce mini, “Ka ga wannan, ɗan mutum? Ƙaramin abu ne gidan Yahuda su yi abubuwan banƙyamar da suke yi a nan? Dole ne su cika ƙasar da rikici su kuma ci gaba da tsokane ni in yi fushi? Dube su suna tsokanata! ");
INSERT INTO hausa_vpl VALUES ("EK8_18","027_8_18","EZK","8","18","18","Saboda haka zan hukunta su cikin fushi; Ba zan dube su da tausayi ko kuwa in ƙyale su ba. Ko da yake suna ihu a kunnuwana, ba zan saurare su ba.” ");
INSERT INTO hausa_vpl VALUES ("EK9_1","027_9_1","EZK","9","1","1","Sai na ji ya yi kira da babbar murya yana cewa, “Kawo matsaran birni a nan, kowanne da makami a hannunsa.” ");
INSERT INTO hausa_vpl VALUES ("EK9_2","027_9_2","EZK","9","2","2","Na kuma ga mutane shida suna zuwa daga kowane gefen ƙofar ta bisa, wadda take fuskantar arewa, kowanne da makamin kisa a hannunsa. Tare da su akwai mutum saye da lilin yana rataye da jaka ƙunshe da kayan rubutu a gefensa. Suka shiga suka tsaya kusa da bagaden tagulla. ");
INSERT INTO hausa_vpl VALUES ("EK9_3","027_9_3","EZK","9","3","3","To, fa, ɗaukakar Allah na Isra’ila ta haura daga bisa kerubobi, inda ta kasance, ta tashi zuwa bakin madogarar ƙofar haikali. Sai Ubangiji ya kira mutumin da yake saye da lilin wanda ya rataye jaka ƙunshe da kayan rubutu a gefensa ");
INSERT INTO hausa_vpl VALUES ("EK9_4","027_9_4","EZK","9","4","4","ya ce masa, “Ka ratsa birnin Urushalima ka sa shaida a goshin waɗanda suke baƙin ciki da kuma makoki a kan dukan abubuwan banƙyamar da ake yi a cikinsa.” ");
INSERT INTO hausa_vpl VALUES ("EK9_5","027_9_5","EZK","9","5","5","Yayinda nake saurara, sai ya ce wa waɗansu, “Ku bi shi ta birnin ku kuma kashe, babu tausayi ko kuwa jinƙai. ");
INSERT INTO hausa_vpl VALUES ("EK9_6","027_9_6","EZK","9","6","6","Ku kashe tsofaffi da samari da ’yan mata, mata da yara, amma kada ku taɓa wani wanda yake da shaida. Ku fara a wuri mai tsarkina.” Saboda haka suka fara da dattawan da suke gaban haikali. ");
INSERT INTO hausa_vpl VALUES ("EK9_7","027_9_7","EZK","9","7","7","Sa’an nan ya ce musu, “Ku ƙazantar da haikalin ku kuma cika filayen da kisassu. Ku tafi!” Saboda haka suka fita suka kuma fara kisa a duk birnin. ");
INSERT INTO hausa_vpl VALUES ("EK9_8","027_9_8","EZK","9","8","8","Yayinda suke kisan sai aka bar ni kaɗai, na fāɗi rubda ciki, na yi kuka na ce, “Kash, Ubangiji Mai Iko Duka! Za ka hallaka dukan raguwar Isra’ila a wannan zafin fushinka a Urushalima?” ");
INSERT INTO hausa_vpl VALUES ("EK9_9","027_9_9","EZK","9","9","9","Ya amsa mini ya ce, “Zunubin gidan Isra’ila da Yahuda ya yi girma ainun; ƙasar ta cika da rashin adalci. Suna cewa, ‘Ubangiji ya yashe ƙasar; Ubangiji ba ya gani.’ ");
INSERT INTO hausa_vpl VALUES ("EK9_10","027_9_10","EZK","9","10","10","Saboda haka ba zan dube su da tausayi ko kuwa in ƙyale su ba, amma zan kawo wa kansu abin da suka yi.” ");
INSERT INTO hausa_vpl VALUES ("EK9_11","027_9_11","EZK","9","11","11","Sai mutumin da yana saye da lilin yake kuma rataye da jaka ƙunshe da kayan rubutu a gefensa ya mayar da magana, yana cewa, “Na yi yadda ka umarci ni.” ");
INSERT INTO hausa_vpl VALUES ("EK10_1","027_10_1","EZK","10","1","1","Na duba, sai na ga kamannin kursiyin saffaya a kan sararin da yake a bisa kawunan kerubobi. ");
INSERT INTO hausa_vpl VALUES ("EK10_2","027_10_2","EZK","10","2","2","Sai Ubangiji ya ce wa mutumin da yake saye da lilin, “Ka shiga cikin da’irorin da suke ƙarƙashin kerubobi. Ka cika hannuwanka da garwashin wuta wanda yake tsakanin kerubobin ka kuma watsar da su a kan birnin.” Yayinda nake dubawa, sai ya shiga. ");
INSERT INTO hausa_vpl VALUES ("EK10_3","027_10_3","EZK","10","3","3","Kerubobin kuwa suna tsaye a gefen kudu na haikali sa’ad da mutumin ya shiga, sai girgije ya cika filin da yake can ciki. ");
INSERT INTO hausa_vpl VALUES ("EK10_4","027_10_4","EZK","10","4","4","Sai ɗaukakar Ubangiji ya tashi daga bisa kerubobi ya tafi zuwa madogarar ƙofar haikali. Girgijen ya cika haikali, filin kuwa ya cika da hasken ɗaukakar Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK10_5","027_10_5","EZK","10","5","5","Sai aka ji ƙarar fikafikan kerubobin har a filin waje, kamar muryar Allah Maɗaukaki sa’ad da ya yi magana. ");
INSERT INTO hausa_vpl VALUES ("EK10_6","027_10_6","EZK","10","6","6","Sa’ad da Ubangiji ya umarci mutumin da yake saye da lilin cewa, “Ka ɗibi wuta daga cikin tsakanin da’irorin, daga tsakanin kerubobin,” sai mutumin ya shiga ya tsaya kusa da da’irar. ");
INSERT INTO hausa_vpl VALUES ("EK10_7","027_10_7","EZK","10","7","7","Sa’an nan ɗaya daga cikin kerubobin ya miƙa hannu zuwa wurin wutar da take tsakaninsu. Ya ɗebo wutar daga ciki ya zuba a hannuwan mutumin da yake saye da lilin, shi kuwa ya karɓa ya fita. ");
INSERT INTO hausa_vpl VALUES ("EK10_8","027_10_8","EZK","10","8","8","(A ƙarƙashin fikafikan kerubobin ana iya ganin abin da ya yi kamar hannuwan mutum.) ");
INSERT INTO hausa_vpl VALUES ("EK10_9","027_10_9","EZK","10","9","9","Na duba, sai na ga kusa da kerubobin akwai da’irori huɗu, kowanne kusa da kerub guda; da’irorin suna ƙyalli kamar wani dutse mai daraja. ");
INSERT INTO hausa_vpl VALUES ("EK10_10","027_10_10","EZK","10","10","10","Game da kamanninsu kuwa, huɗu a cikinsu sun yi kama da juna; kowanne ya yi kamar da da’ira a cikin da’ira. ");
INSERT INTO hausa_vpl VALUES ("EK10_11","027_10_11","EZK","10","11","11","Yayinda suke tafiya, sukan tafi kowane gefe huɗun da kerubobin suka nufa; da’irorin ba sa juyawa yayinda kerubobin suke tafiya. Kerubobin suka tafi kowane gefen da kan ya nufa, ba tare da juyawa ba sa’ad da suke tafiya. ");
INSERT INTO hausa_vpl VALUES ("EK10_12","027_10_12","EZK","10","12","12","Jikunansu gaba ɗaya, har da bayansu, hannuwansu da fikafikansu, sun cika gaba ɗaya da idanu, kamar yadda suke a da’irori huɗun. ");
INSERT INTO hausa_vpl VALUES ("EK10_13","027_10_13","EZK","10","13","13","Na ji ana kiran da’irorin “da’irorin guguwa.” ");
INSERT INTO hausa_vpl VALUES ("EK10_14","027_10_14","EZK","10","14","14","Kowane daga kerubobin yana da fuskoki huɗu. Fuska ɗaya na kerub ne, na biyun fuskar mutum ne, na ukun fuskar zaki ne, na huɗun kuwa fuskar gaggafa ce. ");
INSERT INTO hausa_vpl VALUES ("EK10_15","027_10_15","EZK","10","15","15","Sai kerubobin suka tashi sama. Waɗannan ne halittu masu ran da na gani kusa da Kogin Kebar. ");
INSERT INTO hausa_vpl VALUES ("EK10_16","027_10_16","EZK","10","16","16","Sa’ad da kerubobin suka motsa, sai da’irorin da suke kusa da su su motsa; kuma sa’ad da kerubobin suka buɗe fikafikansu don su tashi daga ƙasa, da’irorin ba sa barin wurarensu. ");
INSERT INTO hausa_vpl VALUES ("EK10_17","027_10_17","EZK","10","17","17","Sa’ad da kerubobin suka tsaya cik, su ma sukan tsaya cik; kuma sa’ad da kerubobin suka tashi, sai su ma su tashi tare da su, domin ruhun rayayyun halittun yana a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("EK10_18","027_10_18","EZK","10","18","18","Sai ɗaukakar Ubangiji ya tashi daga bisa madogarar ƙofar haikali ya kuma tsaya a bisa kerubobi. ");
INSERT INTO hausa_vpl VALUES ("EK10_19","027_10_19","EZK","10","19","19","Yayinda nake duba, kerubobin suka buɗe fikafikansu suka kuma tashi daga ƙasa, yayinda suka tafi kuwa, da’irorin suka tafi tare da su. Suka tsaya a mashigin ƙofar gabas na gidan Ubangiji, ɗaukakar Allah na Isra’ila kuwa yana a kansu. ");
INSERT INTO hausa_vpl VALUES ("EK10_20","027_10_20","EZK","10","20","20","Waɗannan ne rayayyun halittun da na gani a ƙarƙashin Allah na Isra’ila kusa da Kogin Kebar, na kuma gane cewa su kerubobi ne. ");
INSERT INTO hausa_vpl VALUES ("EK10_21","027_10_21","EZK","10","21","21","Kowanne yana da fuskoki huɗu da fikafikai huɗu, a ƙarƙashin kuwa akwai wani abin da ya yi kamar hannuwan mutum. ");
INSERT INTO hausa_vpl VALUES ("EK10_22","027_10_22","EZK","10","22","22","Fuskokinsu suna da kamanni ɗaya da waɗanda na gani kusa da Kogin Kebar. Kowanne ya tafi kai tsaye sosai. ");
INSERT INTO hausa_vpl VALUES ("EK11_1","027_11_1","EZK","11","1","1","Sa’an nan Ruhu ya ɗaga ni sama ya kawo ni ƙofar gidan Ubangiji wadda take fuskantar gabas. Can a mashigi zuwa ƙofar akwai mutum ashirin da biyar, na kuma ga a cikinsu akwai Ya’azaniya ɗan Azzur da Felatiya ɗan Benahiya, shugabannin jama’a. ");
INSERT INTO hausa_vpl VALUES ("EK11_2","027_11_2","EZK","11","2","2","Ubangiji ya ce mini, “Ɗan mutum, waɗannan su ne mutanen da suke ƙulla mugunta suna kuma ba da muguwa shawara a cikin wannan birni. ");
INSERT INTO hausa_vpl VALUES ("EK11_3","027_11_3","EZK","11","3","3","Suna cewa, ‘Lokaci bai yi kusa da za a gina gidaje ba? Wannan birni yana tukunyar dahuwa, mu ne kuwa naman.’ ");
INSERT INTO hausa_vpl VALUES ("EK11_4","027_11_4","EZK","11","4","4","Saboda haka yi annabci a kansu; yi annabci, ɗan mutum.” ");
INSERT INTO hausa_vpl VALUES ("EK11_5","027_11_5","EZK","11","5","5","Sai Ruhun Ubangiji ya sauko a kaina, ya kuma faɗa mini in ce, “Ga abin da Ubangiji yana cewa, haka kuke cewa, ya gidan Isra’ila, amma na san abin da yake a zuciyarku. ");
INSERT INTO hausa_vpl VALUES ("EK11_6","027_11_6","EZK","11","6","6","Kun kashe mutane da yawa a wannan birni kuka kuma cika titunanta da gawawwaki. ");
INSERT INTO hausa_vpl VALUES ("EK11_7","027_11_7","EZK","11","7","7","“Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa gawawwakin da kuka zubar a can su ne naman, wannan birni kuwa ita ce tukunya, amma zan kore ku daga cikinta. ");
INSERT INTO hausa_vpl VALUES ("EK11_8","027_11_8","EZK","11","8","8","Kuna jin tsoron takobi, kuma takobi ne zan kawo muku, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK11_9","027_11_9","EZK","11","9","9","Zan kore ku daga birnin in miƙa ku a hannuwan baƙi in kuma azabtar da ku. ");
INSERT INTO hausa_vpl VALUES ("EK11_10","027_11_10","EZK","11","10","10","Za ku mutu ta wurin takobi, zan kuma hukunta ku a iyakokin Isra’ila. Sa’an nan za ku san cewa ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK11_11","027_11_11","EZK","11","11","11","Wannan birni ba za tă zama muku tukunya ba, ba kuwa za ku zama nama a cikinta ba; zan hukunta ku a iyakokin Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK11_12","027_11_12","EZK","11","12","12","Za ku kuwa san cewa ni ne Ubangiji, gama ba ku bi ƙa’idodina ba balle ku kiyaye dokokina, amma kuka bi hanyoyin al’ummai kewaye da ku.” ");
INSERT INTO hausa_vpl VALUES ("EK11_13","027_11_13","EZK","11","13","13","Yanzu yayinda nake yin annabci, sai Felatiya ɗan Benahiya ya mutu. Sai na fāɗi rubda ciki na kuma yi kuka da babbar murya na ce, “Kash, Ubangiji Mai Iko Duka! Za ka hallaka raguwar Isra’ila ƙaƙaf ne?” ");
INSERT INTO hausa_vpl VALUES ("EK11_14","027_11_14","EZK","11","14","14","Sai maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK11_15","027_11_15","EZK","11","15","15","“Ɗan mutum, ’yan’uwanka, ’yan’uwanka waɗanda suke danginka na cikinka da kuma dukan gidan Isra’ila su ne waɗanda mutanen Urushalima suka ce, ‘Su ne da nisa daga Ubangiji; an ba mu wannan ƙasa ta zama mallakarmu.’ ");
INSERT INTO hausa_vpl VALUES ("EK11_16","027_11_16","EZK","11","16","16","“Saboda haka ka ce, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa ko da yake na kore su zuwa cikin al’ummai na kuma warwatsa su cikin ƙasashe, duk da haka na zama wuri mai tsarki a gare su a ƙasashen da suka tafi.’ ");
INSERT INTO hausa_vpl VALUES ("EK11_17","027_11_17","EZK","11","17","17","“Saboda haka, ka ce, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa zan tattaro ku daga al’ummai in kuma dawo da ku daga ƙasashen da aka warwatsa ku, zan kuwa sāke mayar muku da ƙasar Isra’ila.’ ");
INSERT INTO hausa_vpl VALUES ("EK11_18","027_11_18","EZK","11","18","18","“Za su dawo gare ta su kawar da dukan mugayen siffofi da gumaka masu banƙyama. ");
INSERT INTO hausa_vpl VALUES ("EK11_19","027_11_19","EZK","11","19","19","Zan ba su zuciya ɗaya in kuma sa sabon ruhu a cikinsu; zan fid da zuciyar dutse daga gare su in kuma ba su zuciya ta nama. ");
INSERT INTO hausa_vpl VALUES ("EK11_20","027_11_20","EZK","11","20","20","Sa’an nan za su bi ƙa’idodina su kuma yi hankali ga kiyaye dokokina. Za su zama mutanena, ni kuwa zan zama Allahnsu. ");
INSERT INTO hausa_vpl VALUES ("EK11_21","027_11_21","EZK","11","21","21","Amma game da waɗanda zukatansu suka karkata ga bin mugayen siffofi da gumakan banƙyama, zan sāka musu gwargwadon ayyukansu, in ji Ubangiji Mai Iko Duka.” ");
INSERT INTO hausa_vpl VALUES ("EK11_22","027_11_22","EZK","11","22","22","Sa’an nan kerubobi, tare da da’irori kusa da su, suka buɗe fikafikansu, ɗaukakar Allah kuwa tana a bisansu. ");
INSERT INTO hausa_vpl VALUES ("EK11_23","027_11_23","EZK","11","23","23","Ɗaukakar Ubangiji ta haura daga cikin birnin ta sauka a bisa dutse gabas da shi. ");
INSERT INTO hausa_vpl VALUES ("EK11_24","027_11_24","EZK","11","24","24","Ruhu ya ɗaga ni sama ya kuma kawo ni ga masu zaman bauta a ƙasar Babilon cikin wahayin da Ruhun Allah ya bayar. Sa’an nan wahayin da na gani ya rabu da ni, ");
INSERT INTO hausa_vpl VALUES ("EK11_25","027_11_25","EZK","11","25","25","na kuwa faɗa wa masu zaman bautan dukan abin da Ubangiji ya nuna mini. ");
INSERT INTO hausa_vpl VALUES ("EK12_1","027_12_1","EZK","12","1","1","Maganar Ubangiji ta zo mini cewa ");
INSERT INTO hausa_vpl VALUES ("EK12_2","027_12_2","EZK","12","2","2","ɗan mutum, kana zama a cikin mutane masu tawaye, Suna da idanun gani amma ba sa gani, suna da kunnuwan ji amma ba sa ji, gama ’yan tawaye ne. ");
INSERT INTO hausa_vpl VALUES ("EK12_3","027_12_3","EZK","12","3","3","“Saboda haka ɗan mutum, ka tattara kayanka don zuwa zaman bauta, ka tashi da rana suna gani ka ƙaura a inda kake zuwa wani wuri. Mai yiwuwa za su gane, ko da yake su gidan ’yan tawaye ne. ");
INSERT INTO hausa_vpl VALUES ("EK12_4","027_12_4","EZK","12","4","4","Da rana, yayinda suke kallo, ka fid da kayanka da ka tattara don zuwa zaman bauta. Sa’an nan da yamma, yayinda suke kallo, ka fita kamar yadda mutane masu tafiyar zaman bauta sukan yi. ");
INSERT INTO hausa_vpl VALUES ("EK12_5","027_12_5","EZK","12","5","5","Yayinda suke kallo, ka huda katanga ka fitar da kayanka daga ciki. ");
INSERT INTO hausa_vpl VALUES ("EK12_6","027_12_6","EZK","12","6","6","Ka sa su a kafaɗarka yayinda suke kallo ka kuma fitar da su da dare. Ka rufe fuskarka don kada ka ga ƙasar, gama na mai da kai alama ga gidan Isra’ila.” ");
INSERT INTO hausa_vpl VALUES ("EK12_7","027_12_7","EZK","12","7","7","Sai na yi kamar yadda aka umarce ni. Da rana na fitar da kayana da na tattara don zuwa zaman bauta. Sa’an nan da yamma na huda katanga da hannuwana. Na kwashe kayana da dare, na ɗauke su a kafaɗuna yayinda suke kallo. ");
INSERT INTO hausa_vpl VALUES ("EK12_8","027_12_8","EZK","12","8","8","Da safe maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK12_9","027_12_9","EZK","12","9","9","“Ɗan mutum, gidan ’yan tawayen nan na Isra’ila ba su tambaye ka, ‘Me kake yi ba?’ ");
INSERT INTO hausa_vpl VALUES ("EK12_10","027_12_10","EZK","12","10","10","“Ka ce musu, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa wannan abin da Allah ya yi magana a kai ya shafi sarki a Urushalima da kuma dukan gidan Isra’ila waɗanda suke a can.’ ");
INSERT INTO hausa_vpl VALUES ("EK12_11","027_12_11","EZK","12","11","11","Ka ce musu, ‘Ni alama ne a gare ku.’ “Kamar yadda na yi, haka za a yi da su. Za a kai su zaman bauta kamar kamammu. ");
INSERT INTO hausa_vpl VALUES ("EK12_12","027_12_12","EZK","12","12","12","“Sarkin da yake a cikinsu zai ɗauki kayansa ya saɓa a kafaɗarsa da dare ya tafi, za a huda masa rami a katanga ya fita. Zai rufe fuskarsa don kada yă ga ƙasar. ");
INSERT INTO hausa_vpl VALUES ("EK12_13","027_12_13","EZK","12","13","13","Zan shimfiɗa masa ragata, za a kuwa kama shi da tarkona; zan kawo shi Babiloniya, ƙasar Kaldiyawa, amma ba zai gan ta ba, a can kuwa zai mutu. ");
INSERT INTO hausa_vpl VALUES ("EK12_14","027_12_14","EZK","12","14","14","Zan warwatsa dukan waɗanda suke kewaye da shi a dukan fuskokin iska, ma’aikatansa da dukan rundunoninsa, zan fafare su da takobin da aka zāre. ");
INSERT INTO hausa_vpl VALUES ("EK12_15","027_12_15","EZK","12","15","15","“Za su san cewa ni ne Ubangiji sa’ad da na watsar da su a cikin al’ummai na kuma warwatsa su cikin ƙasashe. ");
INSERT INTO hausa_vpl VALUES ("EK12_16","027_12_16","EZK","12","16","16","Amma zan bar kaɗan daga cikinsu su tsere wa takobi, yunwa da annoba, saboda a cikin al’umman da suka tafi su furta dukan ayyukansu masu banƙyama. Sa’an nan za su san cewa ni ne Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("EK12_17","027_12_17","EZK","12","17","17","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK12_18","027_12_18","EZK","12","18","18","“Ɗan mutum, ka yi rawar jiki yayinda kake cin abincinka, ka kuma yi makyarkyata don tsoro yayinda kake shan ruwanka. ");
INSERT INTO hausa_vpl VALUES ("EK12_19","027_12_19","EZK","12","19","19","Ka faɗa wa mutanen ƙasar cewa, ‘Ga abin Ubangiji Mai Iko Duka yana cewa game da waɗanda suke zama a Urushalima da kuma cikin ƙasar Isra’ila. Za su ci abincinsu da razana, su sha ruwansu da tsoro, gama za a washe dukan abin da yake ƙasarsu saboda hargitsin dukan waɗanda suna zama a can. ");
INSERT INTO hausa_vpl VALUES ("EK12_20","027_12_20","EZK","12","20","20","Garuruwan da mutane suna ciki za su zama kufai ƙasar kuma za tă zama kango. Sa’an nan za ku san cewa ni ne Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK12_21","027_12_21","EZK","12","21","21","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK12_22","027_12_22","EZK","12","22","22","“Ɗan mutum, mene ne wannan karin magana da kuke da shi a ƙasar Isra’ila mai cewa, ‘Kwanaki suna ta wucewa, wahayi bai gudana ba’? ");
INSERT INTO hausa_vpl VALUES ("EK12_23","027_12_23","EZK","12","23","23","Ka ce musu, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa zan kawo ƙarshen wannan karin magana, ba za su ƙara faɗar wannan karin magana a Isra’ila ba.’ Ka ce musu, ‘Kwanaki sun gabato da za a tabbatar da kowane wahayi. ");
INSERT INTO hausa_vpl VALUES ("EK12_24","027_12_24","EZK","12","24","24","Gama ba za a ƙara ganin wahayin ƙarya ko a yi duba na daɗin baki a cikin mutanen Isra’ila ba. ");
INSERT INTO hausa_vpl VALUES ("EK12_25","027_12_25","EZK","12","25","25","Amma Ni Ubangiji zan yi magana abin da na nufa, za tă kuwa tabbata ba tare da jinkiri ba. Gama cikin kwanakinku, kai gidan ’yan tawaye, zan cika duk abin da na faɗa, in ji Ubangiji Mai Iko Duka.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK12_26","027_12_26","EZK","12","26","26","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK12_27","027_12_27","EZK","12","27","27","“Ɗan mutum, gidan Isra’ila suna cewa, ‘Wahayin da yake gani na shekaru masu yawa ne nan gaba, yana kuma annabce-annabce game da wani zamani ne can.’ ");
INSERT INTO hausa_vpl VALUES ("EK12_28","027_12_28","EZK","12","28","28","“Saboda haka ka ce musu, ‘Ga abin da Ubangiji Mai Iko Duka yake cewa ba wata maganata da za tă ƙara yin jinkiri; duk abin da na faɗa zai cika, in ji Ubangiji Mai Iko Duka.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK13_1","027_13_1","EZK","13","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK13_2","027_13_2","EZK","13","2","2","“Ɗan mutum, yi annabci a kan annabawan Isra’ila waɗanda suke annabci yanzu. Ka faɗa wa waɗanda suke annabci bisa ga ra’ayinsu cewa, ‘Ku ji maganar Ubangiji! ");
INSERT INTO hausa_vpl VALUES ("EK13_3","027_13_3","EZK","13","3","3","Ga abin da Ubangiji Mai Iko Duka yake faɗa, Kaiton wawaye annabawan da suke bin ruhunsu kuma ba su ga kome ba! ");
INSERT INTO hausa_vpl VALUES ("EK13_4","027_13_4","EZK","13","4","4","Annabawanki, ya Isra’ila, suna kama da diloli a kufai. ");
INSERT INTO hausa_vpl VALUES ("EK13_5","027_13_5","EZK","13","5","5","Ba ku haura don ku rushe katanga don ku gyara gidan Isra’ila saboda ya tsaya daram a yaƙi a ranar Ubangiji ba. ");
INSERT INTO hausa_vpl VALUES ("EK13_6","027_13_6","EZK","13","6","6","Wahayoyinsu ƙarya ne suna yin dubansu na ƙarya ne. Sukan ce, Ubangiji ya furta, alhali kuwa Ubangiji bai aike su ba; duk da haka sukan sa zuciya ga cikawar maganarsu. ");
INSERT INTO hausa_vpl VALUES ("EK13_7","027_13_7","EZK","13","7","7","Ba ku ga wahayin ƙarya kuka kuma faɗa yin duban ƙarya sa’ad da kuka ce, “Ubangiji ya furta,” ko da yake bai yi magana ba? ");
INSERT INTO hausa_vpl VALUES ("EK13_8","027_13_8","EZK","13","8","8","“ ‘Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa saboda maganganunku na ƙarya da wahayinku na ƙarya, ina gāba da ku, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK13_9","027_13_9","EZK","13","9","9","Hannuna zai yi gāba da annabawan da suke ganin wahayin ƙarya suna kuma yin duban ƙarya. Ba za su kasance cikin taron mutanena ba, ba kuwa za a rubuta su a littafin gidan Isra’ila ba, ba za su shiga ƙasar Isra’ila ba. Ta haka za ku san cewa ni ne Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK13_10","027_13_10","EZK","13","10","10","“ ‘Domin sun ɓad da mutanena, suna cewa, “Salama,” sa’ad da ba salama, kuma saboda, sa’ad da ana gina katanga marar ƙarfi, sukan shafe ta da farar ƙasa, ");
INSERT INTO hausa_vpl VALUES ("EK13_11","027_13_11","EZK","13","11","11","saboda haka ka faɗa wa waɗanda suka shafe da farar ƙasa cewa za tă fāɗi. Ruwan sama zai sauko da rigyawa, zan kuma aika da ƙanƙara, kuma babbar iska za tă ɓarke. ");
INSERT INTO hausa_vpl VALUES ("EK13_12","027_13_12","EZK","13","12","12","Sa’ad da katangar ta fāɗi, mutane ba za su tambaye ku ba cewa, “Ina shafen farar ƙasar da kuka yi mata?” ");
INSERT INTO hausa_vpl VALUES ("EK13_13","027_13_13","EZK","13","13","13","“ ‘Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa a cikin hasalata zan saki babbar iska, kuma cikin fushina zan tura ƙanƙara kuma rigyawan ruwan sama zai sauko da fushin hallaka. ");
INSERT INTO hausa_vpl VALUES ("EK13_14","027_13_14","EZK","13","14","14","Zan rushe katangar da kuka shafe da farar ƙasa zan baje ta har ƙasa saboda tushenta zai tsaya tsirara. Sa’ad da ta fāɗi, za a hallaka ku a cikinta; kuma za ku san cewa ni ne Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK13_15","027_13_15","EZK","13","15","15","Ta haka zan aukar wa katangar da hasalata da kuma a kan waɗanda suka yi shafenta da farar ƙasa. Zan ce muku, “Katangar ta fāɗi haka kuma mutanen da suka shafe ta da farar ƙasa, ");
INSERT INTO hausa_vpl VALUES ("EK13_16","027_13_16","EZK","13","16","16","waɗannan annabawan Isra’ila waɗanda suka yi annabci wa Urushalima suka kuma ga mata wahayin salama sa’ad da ba salama, in ji Ubangiji Mai Iko Duka.” ’ ");
INSERT INTO hausa_vpl VALUES ("EK13_17","027_13_17","EZK","13","17","17","“To, ɗan mutum, ka kafa idonka a kan ’yan matan mutanenka waɗanda suke annabci bisa ga ra’ayinsu. Yi annabci a kansu ");
INSERT INTO hausa_vpl VALUES ("EK13_18","027_13_18","EZK","13","18","18","ka kuma ce, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa kaiton matan da suke ɗinka kambuna a hannuwansu suna kuma yin gyale masu tsawo dabam-dabam wa kawunansu don su farauci mutane. Za ku farauci rayukan mutanena ku bar naku? ");
INSERT INTO hausa_vpl VALUES ("EK13_19","027_13_19","EZK","13","19","19","Kun jawo mini kunya a cikin mutanena don a tafa muku sha’ir da ɗan dunƙulen burodi. Ta wurin yin ƙarya wa mutanena, waɗanda suke jin ƙarairayi, kuka kashe waɗanda bai kamata su mutu ba kuka bar waɗanda ya kamata su mutu. ");
INSERT INTO hausa_vpl VALUES ("EK13_20","027_13_20","EZK","13","20","20","“ ‘Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa ina gāba da kambunanku waɗanda kuke farautar mutane da su kamar tsuntsaye don haka zan kuma tsintsinke su daga hannuwanku; zan ’yantar da mutanen da kuka farauto kamar tsuntsaye. ");
INSERT INTO hausa_vpl VALUES ("EK13_21","027_13_21","EZK","13","21","21","Zan kyakketa gyalenku in ceci mutanena daga hannuwanku, ba za su kuma ƙara zama ganima a hannunku ba. Sa’an nan za ku san cewa ni ne Ubangiji ");
INSERT INTO hausa_vpl VALUES ("EK13_22","027_13_22","EZK","13","22","22","Domin kun karya zuciyar masu adalci da ƙarairayinku, sa’ad da na fitar da su babu damuwa, kuma domin kun ƙarfafa mugaye kada su juye daga mugayen hanyoyinsu su ceci rayukansu, ");
INSERT INTO hausa_vpl VALUES ("EK13_23","027_13_23","EZK","13","23","23","saboda haka ba za ku ƙara ganin wahayin ƙarya ba, ko ku yi duba. Zan ceci mutanena daga hannuwanku. A sa’an nan za ku san cewa ni ne Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK14_1","027_14_1","EZK","14","1","1","Waɗansu dattawan Isra’ila suka zo wurina suka zauna a ƙasa a gabana. ");
INSERT INTO hausa_vpl VALUES ("EK14_2","027_14_2","EZK","14","2","2","Sai maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK14_3","027_14_3","EZK","14","3","3","“Ɗan mutum, waɗannan mutane sun kafa gumaka a cikin zukatansu suka sa mugayen abubuwan sa tuntuɓe a gabansu. Zan bar su, su taɓa nemi ni? ");
INSERT INTO hausa_vpl VALUES ("EK14_4","027_14_4","EZK","14","4","4","Saboda haka ka yi musu magana ka faɗa musu cewa, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa sa’ad da wani mutumin Isra’ila ya kafa gumaka a cikin zuciyarsa ya kuma sa mugun abin tuntuɓe a gabansa sa’an nan ya tafi wurin annabi, Ni Ubangiji zan amsa masa da kaina game da babban bautar gumakarsa. ");
INSERT INTO hausa_vpl VALUES ("EK14_5","027_14_5","EZK","14","5","5","Zan yi haka don in sāke ƙame zukatan mutanen Isra’ila, waɗanda duk suka yashe ni don gumakansu.’ ");
INSERT INTO hausa_vpl VALUES ("EK14_6","027_14_6","EZK","14","6","6","“Saboda haka ka faɗa wa gidan Isra’ila cewa, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa ku tuba! Ku juyo daga gumakanku ku kuma furta dukan ayyukanku masu banƙyama! ");
INSERT INTO hausa_vpl VALUES ("EK14_7","027_14_7","EZK","14","7","7","“ ‘Duk sa’ad da mutumin Isra’ila ko baƙo mai zama a Isra’ila ya rabu da ni ya kuma kafa gumaka a cikin zuciyarsa ya kuna sa mugun abin tuntuɓe a gabansa sa’an nan ya tafi wurin annabi don yă neme ni, Ni Ubangiji zan amsa masa da kaina. ");
INSERT INTO hausa_vpl VALUES ("EK14_8","027_14_8","EZK","14","8","8","Zan yi gāba da mutumin in kuma sa ya zama misali da kuma abin karin magana. Zan ware shi daga mutanena. Sa’an nan za ku san cewa ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK14_9","027_14_9","EZK","14","9","9","“ ‘In kuma aka ruɗi annabin har ya yi annabci, Ni Ubangiji na rinjayi wannan annabi, zan kuma miƙa hannuna gāba da shi in hallaka shi daga cikin mutanena Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK14_10","027_14_10","EZK","14","10","10","Za su ɗauki hakkin laifinsu annabin zai zama mai laifi daidai da wanda ya zo neman shawararsa. ");
INSERT INTO hausa_vpl VALUES ("EK14_11","027_14_11","EZK","14","11","11","Sa’an nan mutanen Isra’ila ba za su ƙara kauce daga gare ni ba, ba kuwa za su ƙara ƙazantar da kansu da dukan zunubansu ba. Za su zama mutanena, ni kuma zan zama Allahnsu, in ji Ubangiji Mai Iko Duka.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK14_12","027_14_12","EZK","14","12","12","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK14_13","027_14_13","EZK","14","13","13","“Ɗan mutum, in wata ƙasa ta yi mini zunubi ta wurin rashin aminci na kuma miƙa hannuna gāba da ita don in toshe hanyar samun abincinta na kuma aika da yunwa a kanta na kashe mutanenta da dabbobinta, ");
INSERT INTO hausa_vpl VALUES ("EK14_14","027_14_14","EZK","14","14","14","ko da waɗannan mutum uku Nuhu, Daniyel da kuma Ayuba suna a cikinta, za su iya ceton kansu ne kawai ta wurin adalcinsu, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK14_15","027_14_15","EZK","14","15","15","“Ko kuwa in na aika da namun jeji su ratsa cikin wannan ƙasa suka kuma bar ta babu yaro, ta kuma zama kufai har babu wanda zai ratsa cikinta saboda namun jeji, ");
INSERT INTO hausa_vpl VALUES ("EK14_16","027_14_16","EZK","14","16","16","muddin ina raye, in ji Ubangiji Mai Iko Duka, ko da ma waɗannan mutum uku suna a cikinta, ba za su iya ceton ’ya’yansu maza ko mata ba. Su kaɗai za a iya ceto, amma ƙasar za tă zama kufai. ");
INSERT INTO hausa_vpl VALUES ("EK14_17","027_14_17","EZK","14","17","17","“Ko kuma in na kawo takobi a kan wannan ƙasa na kuma ce, ‘Bari takobin ya ratsa cikin dukan ƙasar,’ na kuma kashe mutanenta da dabbobinsu, ");
INSERT INTO hausa_vpl VALUES ("EK14_18","027_14_18","EZK","14","18","18","muddin ina raye, in ji Ubangiji Mai Iko Duka, ko da waɗannan mutum uku suna cikinta, ba za su iya ceton ’ya’yansu maza ko mata ba. Su kaɗai za a iya ceto. ");
INSERT INTO hausa_vpl VALUES ("EK14_19","027_14_19","EZK","14","19","19","“Ko kuma in na aika da annoba a cikin wannan ƙasa na kuma yi fushi a kanta ta wurin kisa, ina kisan mutanenta da dabbobinsu, ");
INSERT INTO hausa_vpl VALUES ("EK14_20","027_14_20","EZK","14","20","20","muddin ina raye, in ji Ubangiji Mai Iko Duka, ko da Nuhu, Daniyel da Ayuba suna a cikinta, ba za su iya ceton ɗansu ko ’yarsu ba. Za su iya ceton kansu ne kaɗai ta wurin adalcinsu. ");
INSERT INTO hausa_vpl VALUES ("EK14_21","027_14_21","EZK","14","21","21","“Gama ga abin da Ubangiji Mai Iko Duka yana cewa balle fa sa’ad da na aika wa Urushalima da hukuntaina guda huɗu masu zafi takobi da yunwa da namun jeji da annoba don su kashe mutanenta da dabbobinsu! ");
INSERT INTO hausa_vpl VALUES ("EK14_22","027_14_22","EZK","14","22","22","Duk da haka za a sami mutanen da za su ragu ’ya’ya maza da matan da za a fitar daga cikinta. Za su zo wurinka, kuma sa’ad da ka gan halinsu da ayyukansu, za ka ta’azantu game da bala’in da na kawo a kan Urushalima kowane bala’in da na kawo a kanta. ");
INSERT INTO hausa_vpl VALUES ("EK14_23","027_14_23","EZK","14","23","23","Za ka ta’azantu sa’ad da ka ga halinsu da kuma ayyukansu, gama za ka san cewa ban aikata wani abu a cikinta ba dalili ba, in ji Ubangiji Mai Iko Duka.” ");
INSERT INTO hausa_vpl VALUES ("EK15_1","027_15_1","EZK","15","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK15_2","027_15_2","EZK","15","2","2","“Ɗan mutum, da me itacen kuringa ya fi reshen waɗansu itatuwa kyau a cikin kurmi? ");
INSERT INTO hausa_vpl VALUES ("EK15_3","027_15_3","EZK","15","3","3","An taɓa ɗaukan itacensa an yi wani abu mai amfani? Akan yi maratayi da ita da za a rataya wani abu a kai? ");
INSERT INTO hausa_vpl VALUES ("EK15_4","027_15_4","EZK","15","4","4","Bayan kuma a jefa ta cikin wuta, wuta kuma ta cinye kowane gefe ta kuma babbaka tsakiyarta, tana da amfani don yin wani abu kuma? ");
INSERT INTO hausa_vpl VALUES ("EK15_5","027_15_5","EZK","15","5","5","In ba ta da amfanin wani abu sa’ad da take cikakkiya, balle bayan da wuta ta babbake ta, za a iya yin amfani da ita? ");
INSERT INTO hausa_vpl VALUES ("EK15_6","027_15_6","EZK","15","6","6","“Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa kamar yadda na ba da itacen kuringa a cikin itatuwan kurmi ya zama itacen wuta, haka zan sa mazaunan Urushalima su zama. ");
INSERT INTO hausa_vpl VALUES ("EK15_7","027_15_7","EZK","15","7","7","Zan yi gāba da su. Ko da yake sun fito daga wuta, wuta za tă cinye su. Kuma sa’ad da na yi gāba da su, za ku san cewa ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK15_8","027_15_8","EZK","15","8","8","Zan mai da ƙasar kufai domin sun yi rashin aminci, in ji Ubangiji Mai Iko Duka.” ");
INSERT INTO hausa_vpl VALUES ("EK16_1","027_16_1","EZK","16","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK16_2","027_16_2","EZK","16","2","2","“Ɗan mutum, ka sa Urushalima ta san ayyukanta masu banƙyama ");
INSERT INTO hausa_vpl VALUES ("EK16_3","027_16_3","EZK","16","3","3","ka ce, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa wa Urushalima, Asalinki da haihuwarki daga ƙasar Kan’ana ne; mahaifinki mutumin Amoriyawa ne, mahaifiyarki kuma mutuniyar Hitti ce. ");
INSERT INTO hausa_vpl VALUES ("EK16_4","027_16_4","EZK","16","4","4","A ranar da aka haife ki ba a yanke cibiyarki ba, ba a kuma yi miki wanka don a tsabtacce ki ba, ba a kuma goge ki da gishiri ba ko a naɗe ki cikin tsummoki. ");
INSERT INTO hausa_vpl VALUES ("EK16_5","027_16_5","EZK","16","5","5","Ba wanda ya dube ki da tausayi ko ya nuna miki isashen jinƙai don yă yi miki ɗaya daga cikin waɗannan abubuwa. A maimako, sai aka jefar da ke a fili, gama a ranar da aka haife ki an ji ƙyamarki. ");
INSERT INTO hausa_vpl VALUES ("EK16_6","027_16_6","EZK","16","6","6","“ ‘Sa’an nan na wuce na ga kina birgima cikin jininki, yayinda kike kwance can cikin jininki sai na ce miki, “Ki rayu!” ");
INSERT INTO hausa_vpl VALUES ("EK16_7","027_16_7","EZK","16","7","7","Na sa kin yi girma kamar tsiro a fili. Kin yi girma kika kuma yi tsayi kika zama mafiya kyau na kayan ado. Nononki suka fito, gashinki kuwa suka yi girma, duk da haka tsirara kike tik. ");
INSERT INTO hausa_vpl VALUES ("EK16_8","027_16_8","EZK","16","8","8","“ ‘Daga baya na wuce, da na dube ki sai na ga cewa kin yi girma sosai har kin kai a ƙaunace ki, na yafa gefen tufafina a kanki na kuma rufe tsiraincinki. Na rantse miki, na ƙulla alkawari da ke, kin kuwa zama tawa, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK16_9","027_16_9","EZK","16","9","9","“ ‘Na yi miki wanka na wanke miki jini daga gare ki na kuma shafa miki mai. ");
INSERT INTO hausa_vpl VALUES ("EK16_10","027_16_10","EZK","16","10","10","Na rufe ki da rigar da aka yi wa ado na kuma sa miki takalman fata. Na sa miki riga ta lilin mai kyau na kuma rufe ki da riguna masu tsada. ");
INSERT INTO hausa_vpl VALUES ("EK16_11","027_16_11","EZK","16","11","11","Na yi miki ado da kayan ado masu daraja, na sa miki mundaye a hannuwanki da abin wuya a wuyanki, ");
INSERT INTO hausa_vpl VALUES ("EK16_12","027_16_12","EZK","16","12","12","na kuma sa miki zobe a hancinki, abin kunne a kunnuwanki da rawani mai kyau a kanki. ");
INSERT INTO hausa_vpl VALUES ("EK16_13","027_16_13","EZK","16","13","13","Haka kuwa aka caɓa miki zinariya da azurfa; tufafinki kuwa na lilin mai kyau da riguna masu tsada waɗanda aka yi musu ado. Abincinki na gari mai laushi ne, zuma da man zaitun. Kika zama kyakkyawa har kika kuma zama sarauniya. ");
INSERT INTO hausa_vpl VALUES ("EK16_14","027_16_14","EZK","16","14","14","Sunanki ya yaɗu a cikin al’ummai saboda kyanki, domin darajar da na ba ki ya sa kyanki ya zama cikakke, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK16_15","027_16_15","EZK","16","15","15","“ ‘Amma kika dogara ga kyanki kika kuma yi amfani da sunan da kika yi don ki zama karuwa. Kin yi ta jibga alherai a kan kowa da ya wuce, sai kyanki ya zama naki. ");
INSERT INTO hausa_vpl VALUES ("EK16_16","027_16_16","EZK","16","16","16","Kin ɗauki waɗansu tufafinki don ki yi wa kanki masujadai masu ado, inda kike karuwancinki. Irin waɗannan abubuwa bai kamata su faru ba, bai kuma kamata su taɓa faruwa ba. ");
INSERT INTO hausa_vpl VALUES ("EK16_17","027_16_17","EZK","16","17","17","Kika kuma ɗauki kayan ado masu kyau da na ba ki, kayan adon da aka yi da zinariya da azurfa, kika yi wa kanki gumakan maza kika kuma yi ta yin karuwanci da su. ");
INSERT INTO hausa_vpl VALUES ("EK16_18","027_16_18","EZK","16","18","18","Kika ɗauki rigunanki masu ado don ki sa a kansu, kika kuma miƙa maina da turarena a gabansu. ");
INSERT INTO hausa_vpl VALUES ("EK16_19","027_16_19","EZK","16","19","19","Haka ma abincin da na tanada miki, lallausan gari, man zaitun, da zuman da na ba ki ki ci, kin miƙa su kamar turare mai ƙanshi a gabansu, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK16_20","027_16_20","EZK","16","20","20","“ ‘Kika kuma kwashe ’ya’yanki maza da mata waɗanda kin haifa mini kika miƙa su kamar abinci ga gumakanki. Karuwancinki bai isa ba ne? ");
INSERT INTO hausa_vpl VALUES ("EK16_21","027_16_21","EZK","16","21","21","Kin kashe ’ya’yana kika kuma miƙa su ga gumaka. ");
INSERT INTO hausa_vpl VALUES ("EK16_22","027_16_22","EZK","16","22","22","Cikin dukan ayyukan banƙyamarki da karuwancinki ba ki tuna da kwanakin ƙuruciyarki ba, sa’ad da kike tsirara tik, kina birgima cikin jininki. ");
INSERT INTO hausa_vpl VALUES ("EK16_23","027_16_23","EZK","16","23","23","“ ‘Kaito! Kaitonki, in ji Ubangiji Mai Iko Duka. Bugu da ƙari a kan dukan waɗansu muguntarki, ");
INSERT INTO hausa_vpl VALUES ("EK16_24","027_16_24","EZK","16","24","24","kin gina wa kanki ɗakunan sama da gidajen tsafi a kowane dandali. ");
INSERT INTO hausa_vpl VALUES ("EK16_25","027_16_25","EZK","16","25","25","A kowane titi kin gina ɗakin tsafi kika kuma wulaƙanta kyanki, kina miƙa jikinki da ƙarin fasikanci ga duk mai wucewa. ");
INSERT INTO hausa_vpl VALUES ("EK16_26","027_16_26","EZK","16","26","26","Kin yi karuwanci da Masarawa, maƙwabtanki masu kwaɗayi, kika tsokane ni har na yi fushi da ƙarin fasikancinki. ");
INSERT INTO hausa_vpl VALUES ("EK16_27","027_16_27","EZK","16","27","27","Saboda haka na miƙa hannuna gāba da ke na kuma rage iyakarki; na ba da ke ga abokan gābanki masu haɗama, ’yan matan Filistiyawa, waɗanda suka sha mamaki saboda halinki na lalata. ");
INSERT INTO hausa_vpl VALUES ("EK16_28","027_16_28","EZK","16","28","28","Kin kuma yi karuwanci da Assuriyawa, domin ba kya ƙoshi; kai ko bayan wannan, ba ki ƙoshi ba. ");
INSERT INTO hausa_vpl VALUES ("EK16_29","027_16_29","EZK","16","29","29","Sai kika ƙara fasikancinki da ya haɗa da ƙasar cinikin Babilon, amma duk da haka ba ki ƙoshi ba. ");
INSERT INTO hausa_vpl VALUES ("EK16_30","027_16_30","EZK","16","30","30","“ ‘Kina da rashin ƙarfi a zuci, in ji Ubangiji Mai Iko Duka, sa’ad da kika yi duk waɗannan abubuwa, kina yi kamar karuwar da aka watsa! ");
INSERT INTO hausa_vpl VALUES ("EK16_31","027_16_31","EZK","16","31","31","Sa’ad da kika gina ɗakunan samanki a kowane gefen titi kika kuma gina ɗakunan tsafinki a kowane dandali, ba kamar karuwa kike ba, domin kin karɓi kuɗi. ");
INSERT INTO hausa_vpl VALUES ("EK16_32","027_16_32","EZK","16","32","32","“ ‘Ke mazinaciyar mace! Kin gwammace baƙi a maimakon mijinki! ");
INSERT INTO hausa_vpl VALUES ("EK16_33","027_16_33","EZK","16","33","33","Kowace karuwa kan karɓi kuɗi, amma kina ba da kyautai ga dukan kwartayenki, kina ba su cin hanci don su zo wurinki daga ko’ina don alherai marasa ƙa’ida. ");
INSERT INTO hausa_vpl VALUES ("EK16_34","027_16_34","EZK","16","34","34","Saboda haka cikin karuwancinki kin sha bamban da saura; babu wanda yake binki saboda alheranki. Ke dai dabam ce, gama kikan biya kuma ba mai biyanki. ");
INSERT INTO hausa_vpl VALUES ("EK16_35","027_16_35","EZK","16","35","35","“ ‘Saboda haka, ke karuwa, ki ji maganar Ubangiji! ");
INSERT INTO hausa_vpl VALUES ("EK16_36","027_16_36","EZK","16","36","36","Ga abin da Ubangiji Mai Iko Duka yana cewa domin kin zubar da dukiyarki kika bayyana tsiraicinki cikin fasikancinki da kwartayenki, kuma saboda dukan gumakan banƙyamarki, kuma saboda kin ba su jinin ’ya’yansu, ");
INSERT INTO hausa_vpl VALUES ("EK16_37","027_16_37","EZK","16","37","37","saboda haka zan tattara dukan kwartayenki, waɗanda kike jin daɗinsu, waɗanda kike ƙauna da waɗanda kike ƙi. Zan tattara su gāba da ke daga dukan kewaye zan kuma tuɓe ki a gabansu, za su kuwa ga dukan tsiraicinki. ");
INSERT INTO hausa_vpl VALUES ("EK16_38","027_16_38","EZK","16","38","38","Zan hukunta ki da hukuncin matan da suke zina da kuma waɗanda suke zub da jini; zan kawo hakkin jini na fushina da kuma fushin kishina. ");
INSERT INTO hausa_vpl VALUES ("EK16_39","027_16_39","EZK","16","39","39","Sa’an nan zan miƙa ki ga kwartayenki, za su kuwa rurrushe ɗakunan samanki su kuma farfashe ɗakunan tsafinki. Za su tuɓe miki tufafinki su kuma kwashe kayan adonki masu kyau su bar ki tsirara tik. ");
INSERT INTO hausa_vpl VALUES ("EK16_40","027_16_40","EZK","16","40","40","Za su kawo taron jama’a a kanki, waɗanda za su jajjefe ki da dutse su sassare ki gunduwa-gunduwa da takubansu. ");
INSERT INTO hausa_vpl VALUES ("EK16_41","027_16_41","EZK","16","41","41","Za su ƙone gidajenki su kuma hukunta ki a idon mata masu yawa. Zan kawo ƙarshen karuwancinki, ba za ki kuma ƙara biyan kwartayenki ba. ");
INSERT INTO hausa_vpl VALUES ("EK16_42","027_16_42","EZK","16","42","42","Sa’an nan fushina a kanki zai huce fushin kishina kuma ya kwanta; zan huce ba kuwa zan ƙara yin fushi ba. ");
INSERT INTO hausa_vpl VALUES ("EK16_43","027_16_43","EZK","16","43","43","“ ‘Domin ba ki tuna da kwanakin ƙuruciyarki ba amma kika husatar da ni da waɗannan abubuwa, tabbatacce zan sāka miki alhakin ayyukanki, in ji Ubangiji Mai Iko Duka. Ba kin ƙara lalata ga dukan waɗansu ayyuka masu banƙyamarki ba? ");
INSERT INTO hausa_vpl VALUES ("EK16_44","027_16_44","EZK","16","44","44","“ ‘Duk mai yin amfani da karin magana zai faɗi wannan karin magana a kanki cewa, “Kamar yadda mahaifiya take haka ’yar take.” ");
INSERT INTO hausa_vpl VALUES ("EK16_45","027_16_45","EZK","16","45","45","Ke ’yar mahaifiyarki ce da gaske, wadda ta ƙi mijinta da ’ya’yanta; ke kuma ’yar’uwar ’yar’uwanki mata ce da gaske, waɗanda suka ƙi mazansu da ’ya’yansu. Mahaifiyarki mutuniyar Hitti ce, mahaifinki kuma mutumin Amoriyawa ne. ");
INSERT INTO hausa_vpl VALUES ("EK16_46","027_16_46","EZK","16","46","46","Babbar ’yar’uwarki mutuniyar Samariya ce, wadda take zaune da ’ya’yanta mata wajen arewa da ke; ƙanuwarki ita ce Sodom wadda take zaune kudu da ke tare da ’ya’yanta mata. ");
INSERT INTO hausa_vpl VALUES ("EK16_47","027_16_47","EZK","16","47","47","Ba ki bi hanyoyinsu da abubuwansu na banƙyama kaɗai ba, sai ka ce wannan ya yi miki kaɗan, amma kin lalace fiye da su. ");
INSERT INTO hausa_vpl VALUES ("EK16_48","027_16_48","EZK","16","48","48","Muddin in raye, in ji Ubangiji Mai Iko Duka, ’yar’uwarki Sodom da ’ya’yanta mata ba su yi abin da ’ya’yanki mata suka yi ba. ");
INSERT INTO hausa_vpl VALUES ("EK16_49","027_16_49","EZK","16","49","49","“ ‘To, fa, ga zunubin ’yar’uwarki Sodom. Ita da ’ya’yanta mata sun yi girman kai, sun ƙoshi fiye da kima kuma ba su kula da wani abu ba; ba su taimaki matalauta da kuma masu bukata ba. ");
INSERT INTO hausa_vpl VALUES ("EK16_50","027_16_50","EZK","16","50","50","Su masu girman kai ne kuma suka aikata abubuwa masu banƙyama a gabana. Saboda haka na kau da su kamar yadda ka gani. ");
INSERT INTO hausa_vpl VALUES ("EK16_51","027_16_51","EZK","16","51","51","Samariya ba tă aikata ko rabin zunubanki ba. Kin aikata abubuwa masu banƙyama fiye da su, suka kuma sa ’yan’uwanki mata suka zama kamar masu adalci ta wurin dukan waɗannan abubuwa da kika aikata. ");
INSERT INTO hausa_vpl VALUES ("EK16_52","027_16_52","EZK","16","52","52","Ki sha kunyarki, gama kin yi rangwame wa ’yan’uwanki mata. Saboda zunubanki sun yi muni fiye da nasu, sai suka zama kamar sun fi ki adalci. Saboda haka, ki sha kunya ki kuma sha ƙasƙancinki, gama kin sa ’yan’uwanki mata suka zama kamar su masu adalci ne. ");
INSERT INTO hausa_vpl VALUES ("EK16_53","027_16_53","EZK","16","53","53","“ ‘Amma fa, zan komo da nasarar Sodom da ’ya’yanta mata da ta Samariya da ’ya’yanta mata, nasararki kuma tare da su, ");
INSERT INTO hausa_vpl VALUES ("EK16_54","027_16_54","EZK","16","54","54","domin ki sha ƙasƙancinki ki kuma sha kunyar dukan abin da kika aikata ta wurin ta’azantar da su. ");
INSERT INTO hausa_vpl VALUES ("EK16_55","027_16_55","EZK","16","55","55","’Yan’uwanki kuwa, Sodom da ’ya’yanta mata da Samariya tare da ’ya’yanta mata, za su koma kamar yadda suke a dā; ke kuma da ’ya’yanki mata za ku koma kamar yadda kike a dā. ");
INSERT INTO hausa_vpl VALUES ("EK16_56","027_16_56","EZK","16","56","56","Ba za ki ma iya ambaci ’yar’uwarki Sodom a ranar fariyarki ba, ");
INSERT INTO hausa_vpl VALUES ("EK16_57","027_16_57","EZK","16","57","57","kafin a tone muguntarki. Ko da ma haka, yanzu ’ya’yan Arameyawa mata da dukan maƙwabtanta da kuma ’ya’yan Filistiyawa mata suna miki dariyar, dukan waɗanda suke kewaye da ke da suka rena ki. ");
INSERT INTO hausa_vpl VALUES ("EK16_58","027_16_58","EZK","16","58","58","Za ki ɗauki hakkin lalatarki da kuma ayyukanki masu banƙyama, in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK16_59","027_16_59","EZK","16","59","59","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa zan hukunta kamar yadda ya dace da ke, domin kin ƙyale rantsuwana ta wurin karya alkawari. ");
INSERT INTO hausa_vpl VALUES ("EK16_60","027_16_60","EZK","16","60","60","Duk da haka zan tuna da alkawarin da na yi da ke a kwanakin ƙuruciyarki, zan kuma kafa madawwamin alkawari da ke. ");
INSERT INTO hausa_vpl VALUES ("EK16_61","027_16_61","EZK","16","61","61","Sa’an nan za ki tuna da hanyoyinki ki kuma ji kunya sa’ad da kika karɓi ’yan’uwanki mata, waɗanda suka girme ki da kuma waɗanda kika girme su. Zan ba da su kamar ’ya’ya mata gare ki, amma ba bisa alkawarina da ke ba. ");
INSERT INTO hausa_vpl VALUES ("EK16_62","027_16_62","EZK","16","62","62","Ta haka zan kafa alkawarina da ke, za ki kuma san cewa ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK16_63","027_16_63","EZK","16","63","63","Sa’an nan, sa’ad da na yi kafara saboda ke domin dukan abin da kika aikata, za ki tuna ki kuma ji kunya har ki kāsa buɗe bakinki saboda kunya, in ji Ubangiji Mai Iko Duka.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK17_1","027_17_1","EZK","17","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK17_2","027_17_2","EZK","17","2","2","“Ɗan mutum, ka shirya kacici-kacici ka faɗa wa gidan Isra’ila misali. ");
INSERT INTO hausa_vpl VALUES ("EK17_3","027_17_3","EZK","17","3","3","Ka ce musu, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa babbar gaggafa mai manyan fikafikai, dogayen gasusuwa da gasusuwa da yawa masu launi iri-iri ta zo Lebanon. Ta cire kan al’ul, ");
INSERT INTO hausa_vpl VALUES ("EK17_4","027_17_4","EZK","17","4","4","ta karya kan tohonsa da yake can bisansa ta kai ƙasar ciniki, inda ta shuka shi a birnin ’yan kasuwa. ");
INSERT INTO hausa_vpl VALUES ("EK17_5","027_17_5","EZK","17","5","5","“ ‘Ta ɗebi waɗansu irin ƙasarku ta sa a ƙasa mai taƙi. Ta shuka shi kamar itacen wardi kusa da ruwa mai yawa, ");
INSERT INTO hausa_vpl VALUES ("EK17_6","027_17_6","EZK","17","6","6","ya kuwa yi toho ya zama kuringa gajeruwa mai yaɗuwa. Rassanta suka tanƙwasa wajen gaggafar, amma saiwoyinta suka zauna a ƙarƙashinta. Ta haka ta zama kuringa, ta yi rassa ta kuma fid da ganyaye. ");
INSERT INTO hausa_vpl VALUES ("EK17_7","027_17_7","EZK","17","7","7","“ ‘Akwai kuma wata babbar gaggafa mai manyan fikafikai da gashi mai yawa. Kuringan nan ta tanƙwasa saiwoyinta zuwa wajen wannan gaggafa daga inda aka shuka ta, ta kuma miƙe rassanta wajenta don gaggafar ta yi mata banruwa. ");
INSERT INTO hausa_vpl VALUES ("EK17_8","027_17_8","EZK","17","8","8","An shuka ta a ƙasa mai kyau kusa da ruwa mai yawa don tă yi rassa masu yawa, ta ba da ’ya’ya ta kuma zama kuringa mai daraja.’ ");
INSERT INTO hausa_vpl VALUES ("EK17_9","027_17_9","EZK","17","9","9","“Ka gaya musu cewa, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa wannan za tă ci gaba? Ba za a tumɓuke ta a kuma kakkaɓe ’ya’yanta don ta bushe ba? Dukan sababbin tohonta za su bushe. Ba sai da hannu mai ƙarfi, ko kuwa da yawan mutane za a tumɓuke ta daga saiwoyinta ba. ");
INSERT INTO hausa_vpl VALUES ("EK17_10","027_17_10","EZK","17","10","10","Ko da an sāke shuka ta, za tă yi amfani ne? Ba za tă bushe gaba ɗaya sa’ad da iskar gabas ta hura ba, tă bushe a ƙasar da ta yi girma?’ ” ");
INSERT INTO hausa_vpl VALUES ("EK17_11","027_17_11","EZK","17","11","11","Sai maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK17_12","027_17_12","EZK","17","12","12","“Ka faɗa wa gidan ’yan tawayen nan, ‘Ba ka san abin da waɗannan abubuwa suke nufi ba?’ Ka faɗa musu cewa, ‘Sarkin Babilon ya tafi Urushalima ya tafi da sarkinta da kuma manyan garinta, ya dawo da su Babilon. ");
INSERT INTO hausa_vpl VALUES ("EK17_13","027_17_13","EZK","17","13","13","Sa’an nan ya ɗauki wani daga iyalin sarauta ya yi yarjejjeniya da shi, ya sa shi ya yi rantsuwa. Ya kuma tafi da shugabannin ƙasar, ");
INSERT INTO hausa_vpl VALUES ("EK17_14","027_17_14","EZK","17","14","14","don a raunana masarautar, kada tă ƙara tashi, amma ta tsaya dai kan cika yarjejjeniyarsa. ");
INSERT INTO hausa_vpl VALUES ("EK17_15","027_17_15","EZK","17","15","15","Amma sarkin nan ya yi tawaye a kan sarkin Babilon ta wurin aika jakadunsa zuwa Masar don a ba shi dawakai da sojoji masu yawa. Zai ci nasara? Shi da ya yi wannan abu zai tsira? Zai iya taka yarjejjeniya har ya tsere? ");
INSERT INTO hausa_vpl VALUES ("EK17_16","027_17_16","EZK","17","16","16","“ ‘Muddin in raye, in ji Ubangiji Mai Iko Duka, zai mutu a Babilon, a ƙasar sarkin nan da ya naɗa shi, domin bai cika rantsuwa da alkawarin da ya yi ba. ");
INSERT INTO hausa_vpl VALUES ("EK17_17","027_17_17","EZK","17","17","17","Fir’auna da yawan sojojinsa da kuma yawan jama’arsa ba zai zama da taimako gare shi a yaƙi ba, sa’ad da sarkin Babilon zai gina mahaurai ya kuma yi ƙawanya don yă hallaka rayuka masu yawa. ");
INSERT INTO hausa_vpl VALUES ("EK17_18","027_17_18","EZK","17","18","18","Bai cika rantsuwa ba ta wurin take alkawari. Domin sarkin Isra’ila ya ƙulla alkawari ya kuma aikata dukan waɗannan abubuwa, ba zai tsira ba. ");
INSERT INTO hausa_vpl VALUES ("EK17_19","027_17_19","EZK","17","19","19","“ ‘Saboda haka ga abin da Ubangiji Mai Iko Duka ya ce muddin ina raye, zan nemi hakkin rantsuwata da ya ƙi cikawa da kuma alkawarin da ya take. ");
INSERT INTO hausa_vpl VALUES ("EK17_20","027_17_20","EZK","17","20","20","Zan kafa masa tarkona, zai kuma fāɗi a tarkona. Zan kawo shi a Babilon in kuma hukunta shi a can domin ya yi mini rashin aminci. ");
INSERT INTO hausa_vpl VALUES ("EK17_21","027_17_21","EZK","17","21","21","Dukan sojojinsa zaɓaɓɓu za a kashe su da takobi, za a kuma watsar da waɗanda suka ragu ko’ina. Ta haka za ku san cewa Ni Ubangiji na faɗa. ");
INSERT INTO hausa_vpl VALUES ("EK17_22","027_17_22","EZK","17","22","22","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa ni kaina zan cire toho a kan itacen al’ul da yake can bisa in shuka; zan kuma karya ƙanƙanin reshe daga can bisan tohon in shuka a dutse mai tsayi. ");
INSERT INTO hausa_vpl VALUES ("EK17_23","027_17_23","EZK","17","23","23","A ƙwanƙolin dutsen Isra’ila zan shuka shi; zai yi rassa yă ba da ’ya’ya yă kuma zama al’ul mai daraja. Tsuntsaye iri-iri za su yi sheƙa a cikinsa; za su sami mafaka a inuwar rassansa. ");
INSERT INTO hausa_vpl VALUES ("EK17_24","027_17_24","EZK","17","24","24","Dukan itatuwan jeji za su san cewa Ni Ubangiji ne mai sa manyan itatuwa su zama ƙanana in kuma sa ƙananan itatuwa su zama manya. Nakan sa ɗanyen itace ya bushe, busasshen itace kuma ya zama ɗanye. “ ‘Ni Ubangiji na faɗa, zan kuma aikata.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK18_1","027_18_1","EZK","18","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK18_2","027_18_2","EZK","18","2","2","“Me ku mutane kuke nufi da faɗar wannan karin magana a kan ƙasar Isra’ila cewa, “ ‘Ubanni sun ci ’ya’yan inabi masu tsami, haƙoran ’ya’ya kuwa sun mutu’? ");
INSERT INTO hausa_vpl VALUES ("EK18_3","027_18_3","EZK","18","3","3","“Muddin ina raye, in ji Ubangiji Mai Iko Duka, ba za ku ƙara faɗar wannan karin magana a Isra’ila ba. ");
INSERT INTO hausa_vpl VALUES ("EK18_4","027_18_4","EZK","18","4","4","Gama kowane mai rai nawa ne, mahaifi da ɗa, duk nawa ne. Mutumin da ya yi zunubi shi zai mutu. ");
INSERT INTO hausa_vpl VALUES ("EK18_5","027_18_5","EZK","18","5","5","“A ce akwai mai adalci wanda yake aikata abin da yake daidai da kuma gaskiya; ");
INSERT INTO hausa_vpl VALUES ("EK18_6","027_18_6","EZK","18","6","6","ba ya cin abinci a duwatsun tsafi ko ya dogara ga gumakan gidan Isra’ila. Ba ya ƙazantar da matar maƙwabcinsa ko ya kwana da mace lokacin al’adarta ba. ");
INSERT INTO hausa_vpl VALUES ("EK18_7","027_18_7","EZK","18","7","7","Ba ya cin zalin wani, amma yakan mayar wa wanda ya ba shi jingina abin da ya jinginar masa. Ba ya yi fashi amma yakan ba wa mayunwata abinci ya kuma tanada wa marasa tufafi riga. ");
INSERT INTO hausa_vpl VALUES ("EK18_8","027_18_8","EZK","18","8","8","Ba ya ba da bashi da ruwa ko ya karɓa ƙarin riba. Yakan janye hannunsa daga aikata mugunta yakan kuma yi shari’a cikin gaskiya tsakanin mutum da mutum. ");
INSERT INTO hausa_vpl VALUES ("EK18_9","027_18_9","EZK","18","9","9","Yana bin ƙa’idodina yana kuma kiyaye dokokina da aminci. Wannan mutumin adali ne; tabbatacce zai rayu, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK18_10","027_18_10","EZK","18","10","10","“A ce yana da ɗa wanda yana kisa ko yana yin ɗaya daga cikin waɗannan abubuwa ");
INSERT INTO hausa_vpl VALUES ("EK18_11","027_18_11","EZK","18","11","11","(ko da yake mahaifin bai yi ko ɗaya daga cikinsu ba). “Yakan ci abinci a duwatsun tsafi. Yakan ƙazantar da matar maƙwabci. ");
INSERT INTO hausa_vpl VALUES ("EK18_12","027_18_12","EZK","18","12","12","Yakan ci zalin matalauta da mabukata. Yakan yi fashi. Ba ya mayar da abin da aka jinginar masa. Ya dogara ga gumaka. Yana aikata ayyukan banƙyama. ");
INSERT INTO hausa_vpl VALUES ("EK18_13","027_18_13","EZK","18","13","13","Yakan ba da bashi da ruwa ya kuma karɓi riba mai yawa. Irin wannan mutum zai rayu? Ba zai rayu ba! Domin ya aikata dukan waɗannan abubuwa masu banƙyama, tabbatacce za a kashe shi, kuma hakkin jininsa zai zauna a kansa. ");
INSERT INTO hausa_vpl VALUES ("EK18_14","027_18_14","EZK","18","14","14","“Amma a ce wannan ɗa yana da ɗa wanda ya ga dukan zunuban da mahaifinsa yake aikata, kuma ko da yake ya gan su, bai yi ko ɗaya daga cikin irin abubuwan nan ba, wato, ");
INSERT INTO hausa_vpl VALUES ("EK18_15","027_18_15","EZK","18","15","15","“Bai ci abinci a duwatsun tsafi ba ko ya dogara ga gumakan gidan Isra’ila. Bai ƙazantar da matar maƙwabcinsa ba. ");
INSERT INTO hausa_vpl VALUES ("EK18_16","027_18_16","EZK","18","16","16","Bai ci zalin wani ko ya karɓi jingina ba. Ba ya fashi amma yakan ba da abincinsa ga mayunwata ya tanada tufafi wa marasa tufafi. ");
INSERT INTO hausa_vpl VALUES ("EK18_17","027_18_17","EZK","18","17","17","Yakan janye hannunsa daga zunubi ba ya kuma ba da bashi da ruwa ko karɓan riba da yawa. Yakan kiyaye dokokina ya kuma bi ƙa’idodina. Ba zai mutu saboda zunubin mahaifinsa ba; tabbatacce zai rayu. ");
INSERT INTO hausa_vpl VALUES ("EK18_18","027_18_18","EZK","18","18","18","Amma mahaifinsa zai mutu saboda zunubinsa, domin ya yi ƙwace, ya yi wa ɗan’uwansa fashi ya kuma yi abin da ba daidai ba a cikin mutanensa. ");
INSERT INTO hausa_vpl VALUES ("EK18_19","027_18_19","EZK","18","19","19","“Duk da haka kukan yi tambaya, ‘Me ya sa ɗan ba zai sami rabo a laifin mahaifinsa ba?’ Da yake ɗan ya yi abin da yake daidai da kuma gaskiya, ya kuma kiyaye dukan ƙa’idodina, tabbatacce zai rayu. ");
INSERT INTO hausa_vpl VALUES ("EK18_20","027_18_20","EZK","18","20","20","Mutumin da ya yi zunubi shi zai mutu. Ɗa ba zai sami rabo a laifin mahaifi ba, mahaifi ba zai sami rabo a laifi ɗa ba. Adalcin adali zai zama nasa, muguntar mugu za tă koma kansa. ");
INSERT INTO hausa_vpl VALUES ("EK18_21","027_18_21","EZK","18","21","21","“Amma in mugun mutum ya juya daga dukan zunubin da ya aikata ya kuma kiyaye dukan ƙa’idodina ya kuwa yi abin da yake daidai da kuma gaskiya, tabbatacce zai rayu; ba zai mutu ba. ");
INSERT INTO hausa_vpl VALUES ("EK18_22","027_18_22","EZK","18","22","22","Babu laifin da ya yi da za a tuna da su. Saboda abubuwan adalcin da ya aikata, zai rayu. ");
INSERT INTO hausa_vpl VALUES ("EK18_23","027_18_23","EZK","18","23","23","Ina jin daɗin mutuwar mugu ne? In ji Ubangiji Mai Iko Duka. A maimako, ban fi jin daɗi sa’ad da suka juyo daga hanyoyinsu suka rayu ba? ");
INSERT INTO hausa_vpl VALUES ("EK18_24","027_18_24","EZK","18","24","24","“Amma in mai adalci ya juya daga adalcinsa ya yi zunubi ya kuma aikata abubuwa masu banƙyamar da mugun mutum ke aikatawa, zai rayu? Babu abubuwan adalcin da ya aikata da za a tuna da su. Saboda rashin amincinsa da kuma saboda zunubai da ya yi, zai mutu. ");
INSERT INTO hausa_vpl VALUES ("EK18_25","027_18_25","EZK","18","25","25","“Duk da haka kun ce, ‘Hanyar Ubangiji ba daidai ba ce.’ Ka ji, ya gidan Isra’ila. Hanyata ba daidai ba ce? ");
INSERT INTO hausa_vpl VALUES ("EK18_26","027_18_26","EZK","18","26","26","In mai adalci ya juye daga adalcinsa ya yi zunubi, zai mutu saboda wannan; saboda zunubin da ya yi, zai mutu. ");
INSERT INTO hausa_vpl VALUES ("EK18_27","027_18_27","EZK","18","27","27","Amma in mugun mutum ya juye daga muguntarsa ya kuma yi abin da yake daidai da kuma gaskiya, zai ceci ransa. ");
INSERT INTO hausa_vpl VALUES ("EK18_28","027_18_28","EZK","18","28","28","Domin ya lura da dukan laifofin da ya yi ya kuma juye daga gare su, tabbatacce zai rayu; ba zai mutu ba. ");
INSERT INTO hausa_vpl VALUES ("EK18_29","027_18_29","EZK","18","29","29","Duk da haka mutanen Isra’ila sun ce, ‘Hanyar Ubangiji ba daidai ba ce.’ Hanyoyina ba daidai ba ne, ya gidan Isra’ila? Ba hanyoyinku ne ba daidai ba? ");
INSERT INTO hausa_vpl VALUES ("EK18_30","027_18_30","EZK","18","30","30","“Saboda haka, ya gidan Isra’ila, zan hukunta ku, kowa bisa ga hanyarsa, in ji Ubangiji Mai Iko Duka. Ku tuba! Ku juye daga dukan laifofinku; sa’an nan zunubi ba zai zama sanadin fāɗuwarku ba. ");
INSERT INTO hausa_vpl VALUES ("EK18_31","027_18_31","EZK","18","31","31","Ku raba kanku da dukan laifofin da kuka yi, ku sami sabuwar zuciya da sabon ruhu. Don me za ku mutu, ya gidan Isra’ila? ");
INSERT INTO hausa_vpl VALUES ("EK18_32","027_18_32","EZK","18","32","32","Gama ba na jin daɗin mutuwar wani, in ji Ubangiji Mai Iko Duka. Ku tuba don ku rayu! ");
INSERT INTO hausa_vpl VALUES ("EK19_1","027_19_1","EZK","19","1","1","“Ka yi makoki game da sarakunan Isra’ila ");
INSERT INTO hausa_vpl VALUES ("EK19_2","027_19_2","EZK","19","2","2","ka ce, “ ‘Mahaifiyarki zakanya ce cikin zakoki! Takan kwanta cikin ’yan zakoki ta kuma yi renon kwiyakwiyanta. ");
INSERT INTO hausa_vpl VALUES ("EK19_3","027_19_3","EZK","19","3","3","Ta goyi ɗaya daga cikin kwiyakwiyanta, ya yi girma ya zama zaki mai ƙarfi. Ya koyi yayyage abin da ya yi farauta yakan kuma cinye mutane. ");
INSERT INTO hausa_vpl VALUES ("EK19_4","027_19_4","EZK","19","4","4","Al’ummai suka ji labarinsa, aka kuma kama shi cikin raminsu. Suka ja shi da ƙugiyoyi zuwa ƙasar Masar. ");
INSERT INTO hausa_vpl VALUES ("EK19_5","027_19_5","EZK","19","5","5","“ ‘Sa’ad da ta ga sa zuciyarta bai cika ba, abin da take fata gani ya tafi, sai ta ɗauki wani daga cikin kwiyakwiyanta ta mai da shi zaki mai ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("EK19_6","027_19_6","EZK","19","6","6","Ya yi ta yawo a cikin zakoki, gama yanzu shi zaki ne mai ƙarfi. Ya koyi yayyage abin da ya yi farauta yakan kuma cinye mutane. ");
INSERT INTO hausa_vpl VALUES ("EK19_7","027_19_7","EZK","19","7","7","Ya rurrushe kagaransu ya kuma ragargaza biranensu. Ƙasar da dukan waɗanda suke cikinta sun tsorata da jin rurinsa. ");
INSERT INTO hausa_vpl VALUES ("EK19_8","027_19_8","EZK","19","8","8","Sai al’ummai suka tayar masa, waɗannan daga yankunan da suke kewaye. Suka yafa raga dominsa ya kuwa fāɗa cikin raminsu. ");
INSERT INTO hausa_vpl VALUES ("EK19_9","027_19_9","EZK","19","9","9","Da ƙugiyoyi suka ja shi cikin keji suka kawo shi wurin sarkin Babilon. Suka sa shi cikin kurkuku, saboda haka ba a ƙara jin rurinsa a kan duwatsun Isra’ila ba. ");
INSERT INTO hausa_vpl VALUES ("EK19_10","027_19_10","EZK","19","10","10","“ ‘Mahaifiyarku kamar kuringa ce a cikin gonar inabi da aka shuka kusa da ruwa; ta ba da ’ya’ya da kuma cikakkun rassa saboda yalwan ruwa. ");
INSERT INTO hausa_vpl VALUES ("EK19_11","027_19_11","EZK","19","11","11","Rassanta suka yi ƙarfi, suka dace da sandar mai mulki. Ta yi tsayi zuwa sama ana ganin ta saboda tsayinta da kuma saboda yawan rassanta. ");
INSERT INTO hausa_vpl VALUES ("EK19_12","027_19_12","EZK","19","12","12","Amma aka tumɓuke ta cikin fushi aka jefar da ita a ƙasa. Iskar gabas ta sa ta yanƙwane, aka kakkaɓe ’ya’yanta; rassanta masu ƙarfi suka bushe wuta kuma ta cinye su. ");
INSERT INTO hausa_vpl VALUES ("EK19_13","027_19_13","EZK","19","13","13","Yanzu an shuka ta a hamada, a busasshiyar ƙasa marar ruwa. ");
INSERT INTO hausa_vpl VALUES ("EK19_14","027_19_14","EZK","19","14","14","Wuta ta fito daga jikin rassanta ta cinye ’ya’yanta. Babu sauran reshe mai ƙarfin da ya rage a kanta da ya dace da sandar mai mulki.’ Wannan waƙa ce kuma za a yi amfani da ita a matsayin makoki.” ");
INSERT INTO hausa_vpl VALUES ("EK20_1","027_20_1","EZK","20","1","1","A shekara ta bakwai, a wata na biyar a rana ta goma, waɗansu dattawan Isra’ila suka zo don su nemi nufin Ubangiji, suka kuwa zauna a ƙasa a gabana. ");
INSERT INTO hausa_vpl VALUES ("EK20_2","027_20_2","EZK","20","2","2","Sai maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK20_3","027_20_3","EZK","20","3","3","“Ɗan mutum, ka yi magana da dattawan Isra’ila ka ce musu, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa kun zo ne ku nemi shawarata? Muddin ina raye, ba zan bari ku nemi shawarata ba, in ji Ubangiji Mai Iko Duka.’ ");
INSERT INTO hausa_vpl VALUES ("EK20_4","027_20_4","EZK","20","4","4","“Za ka hukunta su? Za ka hukunta su, ɗan mutum? To, sai ka kalubalance su da ayyukan banƙyamar kakanninsu ");
INSERT INTO hausa_vpl VALUES ("EK20_5","027_20_5","EZK","20","5","5","ka ce musu, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa a ranar da na zaɓi Isra’ila, na ɗaga hannuna, na rantse wa zuriyar gidan Yaƙub na kuma bayyana kaina gare su a Masar da hannun da na ɗaga na ce musu, “Ni ne Ubangiji Allahnku.” ");
INSERT INTO hausa_vpl VALUES ("EK20_6","027_20_6","EZK","20","6","6","A ranar na yi musu rantsuwa cewa zan fitar da su daga Masar zuwa ƙasar da na samo musu, ƙasa mai zub da madara da zuma, ƙasa mafi kyau cikin dukan ƙasashe. ");
INSERT INTO hausa_vpl VALUES ("EK20_7","027_20_7","EZK","20","7","7","Na kuma ce musu, “Kowannenku ya zubar da mugayen siffofin da kuka kafa idanunku a kai, kuma kada ku ƙazantar da kanku da gumakan Masar. Ni ne Ubangiji Allahnku.” ");
INSERT INTO hausa_vpl VALUES ("EK20_8","027_20_8","EZK","20","8","8","“ ‘Amma sai suka yi tawaye a kaina ba su kuwa saurare ni ba; ba su zubar da mugayen siffofin da suka kafa idanunsu a kai ba, balle su ƙi gumakan Masar. Saboda haka zan zubo hasalata a kansu in kuma aukar musu da fushina a Masar. ");
INSERT INTO hausa_vpl VALUES ("EK20_9","027_20_9","EZK","20","9","9","Amma saboda sunana na yi abin da zai kiyaye shi daga ƙazantuwa a idanun al’umman da suka zauna a ciki da kuma a idanun al’ummai da na bayyana kaina ga Isra’ilawa ta wurin fitar da su daga Masar. ");
INSERT INTO hausa_vpl VALUES ("EK20_10","027_20_10","EZK","20","10","10","Saboda haka na fisshe su daga Masar na kawo su cikin hamada. ");
INSERT INTO hausa_vpl VALUES ("EK20_11","027_20_11","EZK","20","11","11","Na ba su ƙa’idodina na kuma sanar musu da dokokina, gama mutumin da ya yi biyayya da su zai rayu ta wurinsu. ");
INSERT INTO hausa_vpl VALUES ("EK20_12","027_20_12","EZK","20","12","12","Na kuma ba su Asabbataina kamar alama tsakaninmu, domin su san cewa Ni Ubangiji ne yake tsarkake su. ");
INSERT INTO hausa_vpl VALUES ("EK20_13","027_20_13","EZK","20","13","13","“ ‘Duk da haka mutanen Isra’ila suka yi mini tawaye a cikin hamada. Ba su bi ƙa’idodina ba amma suka ki dokokina, ko da yake mutumin da ya yi biyayya da su zai rayu ta wurinsu, suka ɓata Asabbataina ƙwarai. Saboda haka na ce zan zuba hasalata a kansu in kuma hallaka su a hamada. ");
INSERT INTO hausa_vpl VALUES ("EK20_14","027_20_14","EZK","20","14","14","Amma saboda sunana na yi abin da zai kiyaye shi daga ƙazantuwa a idanun al’umman da a idonsu na fisshe su. ");
INSERT INTO hausa_vpl VALUES ("EK20_15","027_20_15","EZK","20","15","15","Na kuma ɗaga hannu na rantse musu a hamada cewa ba zan kawo su ƙasar da na ba su ba, ƙasa mai zub da madara da zuma, ƙasa mafi kyau cikin dukan ƙasashe, ");
INSERT INTO hausa_vpl VALUES ("EK20_16","027_20_16","EZK","20","16","16","domin sun ƙi dokokina ba su kuwa bi ƙa’idodina ba suka kuma ƙazantar da Asabbataina. Gama zukatansu sun fi so su bauta wa gumakansu. ");
INSERT INTO hausa_vpl VALUES ("EK20_17","027_20_17","EZK","20","17","17","Duk da haka na dube su ta tausayi ba zan hallaka su ko in kawo ƙarshensu a hamada ba. ");
INSERT INTO hausa_vpl VALUES ("EK20_18","027_20_18","EZK","20","18","18","Na faɗa wa ’ya’yansu a hamada, “Kada ku bi farillai kakanninku ko ku kiyaye dokokinsu ko ku ƙazantar da kanku da gumakansu. ");
INSERT INTO hausa_vpl VALUES ("EK20_19","027_20_19","EZK","20","19","19","Ni ne Ubangiji Allahnku; ku bi ƙa’idodina ku kuma kula ku kiyaye dokokina. ");
INSERT INTO hausa_vpl VALUES ("EK20_20","027_20_20","EZK","20","20","20","Ku kiyaye Asabbataina da tsarki, don su zama alama tsakaninmu. Ta haka za ku san cewa ni ne Ubangiji Allahnku.” ");
INSERT INTO hausa_vpl VALUES ("EK20_21","027_20_21","EZK","20","21","21","“ ‘Amma ’ya’yan suka yi mini tawaye. Ba su bi ƙa’idodina ba, ba su kula su kiyaye dokokina ba, ko da yake mutumin da ya kiyaye su zai rayu ta wurinsu, suka kuma ƙazantar da Asabbataina. Saboda haka na ce zan zuba hasalata a kansu in kuma aukar musu da fushina a hamada. ");
INSERT INTO hausa_vpl VALUES ("EK20_22","027_20_22","EZK","20","22","22","Amma na janye hannuna, kuma saboda sunana na yi abin da zai kiyaye shi daga ƙazantuwa a idanun al’umman da a idonsu na fisshe su. ");
INSERT INTO hausa_vpl VALUES ("EK20_23","027_20_23","EZK","20","23","23","Na kuma ɗaga hannu na rantse musu cewa zan watsar da su cikin al’ummai in kuma warwatsa su cikin ƙasashe, ");
INSERT INTO hausa_vpl VALUES ("EK20_24","027_20_24","EZK","20","24","24","domin ba su kiyaye dokokina ba amma suka ƙi ƙa’idodina suka kuma ƙazantar da Asabbataina, idanunsu suka yi sha’awar gumakan kakanninsu. ");
INSERT INTO hausa_vpl VALUES ("EK20_25","027_20_25","EZK","20","25","25","Na kuma ba da su ga farillan da ba su da kyau da dokokin da ba za su rayu ta wurinsu ba; ");
INSERT INTO hausa_vpl VALUES ("EK20_26","027_20_26","EZK","20","26","26","na bari suka ƙazantu ta wurin kyautai, hadayar kowane ɗan fari don in cika su da abin tsoro domin su san cewa ni ne Ubangiji.’ ");
INSERT INTO hausa_vpl VALUES ("EK20_27","027_20_27","EZK","20","27","27","“Saboda haka, ɗan mutum, ka yi magana da mutanen Isra’ila ka faɗa musu cewa, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa a wannan kuma kakanninku suka saɓe ni ta wurin yashe ni. ");
INSERT INTO hausa_vpl VALUES ("EK20_28","027_20_28","EZK","20","28","28","Sa’ad da na kawo su cikin ƙasar da na rantse zan ba su suka kuma ga tudu mai tsawo ko itace mai ganye, a can suka miƙa hadayunsu, suka yi sadakokin da suka tsokane ni na yi fushi, suka miƙa turaren ƙanshinsu suka kuma zuba sadakokinsu na sha. ");
INSERT INTO hausa_vpl VALUES ("EK20_29","027_20_29","EZK","20","29","29","Sai na ce musu, Wane ɗakin tsafi kuke tafiya?’ ” (Ana ce da shi Bama har wa yau.) ");
INSERT INTO hausa_vpl VALUES ("EK20_30","027_20_30","EZK","20","30","30","“Domin haka ka faɗa wa gidan Isra’ila, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa za ku ƙazantar da kanku yadda kakanninku suka yi ne ku yi sha’awar mugayen siffofinsu? ");
INSERT INTO hausa_vpl VALUES ("EK20_31","027_20_31","EZK","20","31","31","Sa’ad da kuka miƙa kyautai naku, hadayar ’ya’yanku maza a wuta, kuna cin gaba da ƙazantar da kanku da duka gumakanku har wa yau. Zan bari ku nemi shawarata, ya gidan Isra’ila? Muddin ina raye, in ji Ubangiji Mai Iko Duka, ba zan bari ku nemi shawarata ba. ");
INSERT INTO hausa_vpl VALUES ("EK20_32","027_20_32","EZK","20","32","32","“ ‘Kukan ce, “Kuna so ku zama kamar sauran al’ummai, kamar sauran mutanen duniya, waɗanda suke bauta wa itace da dutse.” Amma abin da kuke tunani ba zai taɓa faruwa ba. ");
INSERT INTO hausa_vpl VALUES ("EK20_33","027_20_33","EZK","20","33","33","Muddin ina raye, in ji Ubangiji Mai Iko Duka, zan yi mulki a kanku da hannu mai iko da kuma hannu mai ƙarfi da kuma fushi. ");
INSERT INTO hausa_vpl VALUES ("EK20_34","027_20_34","EZK","20","34","34","Zan fitar da ku daga al’ummai in tattara ku daga ƙasashe inda aka warwatsa ku, da hannu mai iko da kuma hannu mai ƙarfi da kuma fushi. ");
INSERT INTO hausa_vpl VALUES ("EK20_35","027_20_35","EZK","20","35","35","Zan kawo ku cikin hamadar al’ummai a can kuwa, fuska da fuska, zan hukunta ku. ");
INSERT INTO hausa_vpl VALUES ("EK20_36","027_20_36","EZK","20","36","36","Yadda na hukunta kakanninku a hamadar ƙasar Masar, haka zan hukunta ku, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK20_37","027_20_37","EZK","20","37","37","Zan lura da ku yayinda kuke wucewa ƙarƙashin sanda, zan kuma kawo ku cikin daurin alkawari. ");
INSERT INTO hausa_vpl VALUES ("EK20_38","027_20_38","EZK","20","38","38","Zan fitar da waɗanda suke mini tayarwa da kuma ’yan tawaye. Ko da yake zan fitar da su daga ƙasar da suke zama, duk da haka ba za su shiga ƙasar Isra’ila ba. Sa’an nan za ku san cewa ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK20_39","027_20_39","EZK","20","39","39","“ ‘Game da ku, ya gidan Isra’ila, ga abin da Ubangiji Mai Iko Duka yana cewa ku tafi ku bauta wa gumakanku, kowannenku! Amma daga baya tabbatacce za ku saurare ni ba kuwa za ku ƙara ɓata sunana mai tsarki da hadayunku da gumakanku ba. ");
INSERT INTO hausa_vpl VALUES ("EK20_40","027_20_40","EZK","20","40","40","Gama a kan dutsena mai tsarki, dutse mai tsayi na Isra’ila, in ji Ubangiji Mai Iko Duka, a can a ƙasar gidan Isra’ila gaba ɗaya za su bauta mini, a can kuwa zan karɓe su. A can zan bukaci hadayunku da sadake sadakenku mafi kyau, tare da dukan tsarkakan hadayunku. ");
INSERT INTO hausa_vpl VALUES ("EK20_41","027_20_41","EZK","20","41","41","Zan karɓe ku kamar turare mai ƙanshi sa’ad da na fitar da ku daga al’ummai na kuma tattara ku daga ƙasashe inda aka warwatsa ku, zan kuma nuna kaina mai tsarki a cikinku a idon al’ummai. ");
INSERT INTO hausa_vpl VALUES ("EK20_42","027_20_42","EZK","20","42","42","Sa’an nan za ku san cewa ni ne Ubangiji sa’ad da na kawo ku cikin ƙasar Isra’ila, ƙasar da na ɗaga hannu na rantse zan ba wa kakanninku. ");
INSERT INTO hausa_vpl VALUES ("EK20_43","027_20_43","EZK","20","43","43","A can za ku tuna da halinku da kuma dukan ayyukanku waɗanda kuka ɓata kanku da su, za ku kuwa ji ƙyamar kanku saboda mugayen abubuwan da kuka aikata. ");
INSERT INTO hausa_vpl VALUES ("EK20_44","027_20_44","EZK","20","44","44","Za ku san cewa ni ne Ubangiji, sa’ad da na yi muku haka saboda sunana ba bisa ga mugayen hanyoyinku da ayyukanku marasa kyau ba, ya gidan Isra’ila, in ji Ubangiji Mai Iko Duka.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK20_45","027_20_45","EZK","20","45","45","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK20_46","027_20_46","EZK","20","46","46","“Ɗan mutum, ka kafa fuskarka wajen kudu; ka yi wa’azi a kan kudu ka kuma yi annabci a kan kurmin ƙasar kudu. ");
INSERT INTO hausa_vpl VALUES ("EK20_47","027_20_47","EZK","20","47","47","Ka faɗa wa kurmin kudanci, ‘Ji maganar Ubangiji. Ga abin da Ubangiji Mai Iko Duka yana cewa ina gab da sa maka wuta, za tă kuwa cinye dukan itatuwanki sarai, da ɗanye da busasshe. Ba za a kashe wutar da take ci ba, kuma kowace fuska a kudu zuwa arewa za tă ƙone. ");
INSERT INTO hausa_vpl VALUES ("EK20_48","027_20_48","EZK","20","48","48","Kowa zai san cewa Ni Ubangiji ne ya ƙuna ta; ba za a kashe ta ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK20_49","027_20_49","EZK","20","49","49","Sai na ce, “Kash, Ubangiji Mai Iko Duka! Suna zance a kaina cewa, ‘Ba misalai kawai yake yi ba?’ ” ");
INSERT INTO hausa_vpl VALUES ("EK21_1","027_21_1","EZK","21","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK21_2","027_21_2","EZK","21","2","2","“Ɗan mutum, ka kafa fuskarka gāba da Urushalima ka kuma yi wa’azi a kan wuri mai tsarki. Ka yi annabci gāba da ƙasar Isra’ila ");
INSERT INTO hausa_vpl VALUES ("EK21_3","027_21_3","EZK","21","3","3","ka faɗa mata, ‘Ga abin da Ubangiji ya ce ina gāba da ke. Zan ja takobina daga kubensa in karkashe adalai da mugaye daga cikinki. ");
INSERT INTO hausa_vpl VALUES ("EK21_4","027_21_4","EZK","21","4","4","Domin zan karkashe adalai da kuma mugaye, ba zan rufe takobina a kan kowa daga kudu zuwa arewa ba. ");
INSERT INTO hausa_vpl VALUES ("EK21_5","027_21_5","EZK","21","5","5","Sa’an nan duka mutane za su san cewa Ni Ubangiji na ja takobina daga kubensa; ba zai sāke koma kuma ba.’ ");
INSERT INTO hausa_vpl VALUES ("EK21_6","027_21_6","EZK","21","6","6","“Saboda ka yi nishi, ɗan mutum! Yi nishi a gabansu da ajiyar zuciya da ɓacin rai. ");
INSERT INTO hausa_vpl VALUES ("EK21_7","027_21_7","EZK","21","7","7","Kuma sa’ad da suka tambaye ka, ‘Me ya sa kake nishi?’ Sai ka ce musu, ‘Domin labarun da suke fitowa. Kowace zuciya za tă narke kowane hannu kuma ya gurgunta; kowane ruhu zai sume kowane gwiwa kuma ta rasa ƙarfi kamar ruwa.’ Yana zuwa! Tabbatacce zai faru, in ji Ubangiji Mai Iko Duka.” ");
INSERT INTO hausa_vpl VALUES ("EK21_8","027_21_8","EZK","21","8","8","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK21_9","027_21_9","EZK","21","9","9","“Ɗan mutum, yi annabci ka ce, ‘Ga abin da Ubangiji ya faɗa, “ ‘Takobi, takobi, wasasshe da kuma gogagge, ");
INSERT INTO hausa_vpl VALUES ("EK21_10","027_21_10","EZK","21","10","10","wasasshe don kisa, gogagge har yana walwal kamar walƙiya! “ ‘Kada ku yi farin ciki, hukunci yana zuwa, domin kowa ya ƙi jin abin da na yi gargaɗi a kai. ");
INSERT INTO hausa_vpl VALUES ("EK21_11","027_21_11","EZK","21","11","11","“ ‘An ba da wannan takobi don a goge, don a kama da hannu; an washe shi aka kuma goge, shiryayye don a yi kisa da shi. ");
INSERT INTO hausa_vpl VALUES ("EK21_12","027_21_12","EZK","21","12","12","Ka yi kuka ka yi makoki, ɗan mutum, gama yana gāba da dukan sarakunan Isra’ila. An jefa su ga takobi tare da jama’ata. Saboda haka ku buga ƙirjinku. ");
INSERT INTO hausa_vpl VALUES ("EK21_13","027_21_13","EZK","21","13","13","“ ‘Gwaji tabbatacce zai zo. Kuma a ce sandan Yahuda, wanda takobi ya ƙi, ya ci gaba? In ji Ubangiji Mai Iko Duka.’ ");
INSERT INTO hausa_vpl VALUES ("EK21_14","027_21_14","EZK","21","14","14","“Saboda haka fa, ɗan mutum ka yi annabci ka kuma tafa hannuwanka. Bari takobi ya yi sara sau biyu, har sau uku ma. Takobin kisa ne, takobi ne don kisa mai girma, zai kewaye su a kowane gefe. ");
INSERT INTO hausa_vpl VALUES ("EK21_15","027_21_15","EZK","21","15","15","Domin zukata su narke da yawa kuma su fāɗi, na tsai da takobin kisa a dukan ƙofofinsu. Kash! A sa ya haska kamar walƙiya, ana riƙe da shi don kisa. ");
INSERT INTO hausa_vpl VALUES ("EK21_16","027_21_16","EZK","21","16","16","Ya takobi, yi sara zuwa dama ka yi kuma zuwa hagu, duk inda aka juya ka. ");
INSERT INTO hausa_vpl VALUES ("EK21_17","027_21_17","EZK","21","17","17","Zan tafa hannuwana, fushina kuwa zai sauka. Ni Ubangiji na faɗa.” ");
INSERT INTO hausa_vpl VALUES ("EK21_18","027_21_18","EZK","21","18","18","Sai maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK21_19","027_21_19","EZK","21","19","19","“Ɗan mutum, ka nuna hanyoyi biyu inda takobin sarkin Babilon zai bi, duka biyun su fara daga ƙasa guda. Ka kafa shaida inda hanyar za tă rabu zuwa cikin birni. ");
INSERT INTO hausa_vpl VALUES ("EK21_20","027_21_20","EZK","21","20","20","Ka nuna hanya guda wadda takobi zai fāɗo wa Rabba ta Ammonawa ɗayan kuma da zai fāɗo a kan Yahuda da kuma Urushalima mai katanga. ");
INSERT INTO hausa_vpl VALUES ("EK21_21","027_21_21","EZK","21","21","21","Gama sarkin Babilon zai tsaya a mararrabar hanya, a inda hanyar ta rabu biyu, don yă yi duba. Zai jefa ƙuri’a da kibiyoyinsa, zai nemi shawarar gumakansa, zai bincike hanta. ");
INSERT INTO hausa_vpl VALUES ("EK21_22","027_21_22","EZK","21","22","22","A hannunsa na dama ƙuri’a don Urushalima za tă fito, inda zai kafa dundurusai, ya ba da umarni kisa, a yi kururuwar yaƙi, a kafa dundurusai a kan ƙofofi, a gina mahaurai a kuma yi ƙawanya. ");
INSERT INTO hausa_vpl VALUES ("EK21_23","027_21_23","EZK","21","23","23","Zai zama kamar duban ƙarya ne ga waɗanda suka yi rantsuwar yin masa biyayya, amma zai tunashe su game da laifinsu ya kuma kama su. ");
INSERT INTO hausa_vpl VALUES ("EK21_24","027_21_24","EZK","21","24","24","“Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa, ‘Domin ku mutanen nan kun tuna da laifinku ta wurin tawaye, kun kuma bayyana zunubanku cikin dukan abin da kuke yi, domin kun yi haka, za a kama ku. ");
INSERT INTO hausa_vpl VALUES ("EK21_25","027_21_25","EZK","21","25","25","“ ‘Ya kai ƙazantaccen mugu, yerima Isra’ila, wanda kwanansa ta zo, wanda lokacin hukuncinsa ya cika fal, ");
INSERT INTO hausa_vpl VALUES ("EK21_26","027_21_26","EZK","21","26","26","ga abin da Ubangiji Mai Iko Duka yana cewa ka kunce rawanin, ka ɗauke rawanin nan. Ba zai zama kamar yadda yake ba. Za a ɗaukaka ƙasƙantacce, amma a ƙasƙantar da mai girma. ");
INSERT INTO hausa_vpl VALUES ("EK21_27","027_21_27","EZK","21","27","27","Hallaka! Hallaka! Zan hallaka shi! Ba za a maido da shi ba sai ya ga ainihin mai shi; gare shi zan bayar da shi.’ ");
INSERT INTO hausa_vpl VALUES ("EK21_28","027_21_28","EZK","21","28","28","“Kai kuma, ɗan mutum, ka yi annabci ka ce, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa game da Ammonawa da kuma zarginsu. “ ‘Takobi, takobi, an ja don kisa, an goge don cinyewa yana haske kamar walƙiya! ");
INSERT INTO hausa_vpl VALUES ("EK21_29","027_21_29","EZK","21","29","29","Duk da wahayin ƙarya game da kai, duban ƙarya game da kai, za a sa shi a wuyan mugaye waɗanda za a kashe, waɗanda kwanansu ta zo, waɗanda lokacin hukuncinsu ya cika fal. ");
INSERT INTO hausa_vpl VALUES ("EK21_30","027_21_30","EZK","21","30","30","“ ‘Ka mai da takobi a kubensa. A inda aka halicce ka, a ƙasar kakanninka, zan hukunta ka. ");
INSERT INTO hausa_vpl VALUES ("EK21_31","027_21_31","EZK","21","31","31","Zan zub da hasalata a kanka in hura maka wutar fushina; Zan ba da kai a hannun mugayen mutanen da suka gwanince a hallakarwa. ");
INSERT INTO hausa_vpl VALUES ("EK21_32","027_21_32","EZK","21","32","32","Za ka zama itacen wuta, za a zub da jininka a ƙasarka, ba za a ƙara tuna da kai ba; gama Ni Ubangiji na faɗa.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK22_1","027_22_1","EZK","22","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK22_2","027_22_2","EZK","22","2","2","“Ɗan mutum, za ka shari’anta ta? Za ka shari’anta wannan birni mai kisankai? To, sai ka kalubalance ta da dukan ayyukanta na banƙyama ");
INSERT INTO hausa_vpl VALUES ("EK22_3","027_22_3","EZK","22","3","3","ka kuma ce, ‘Ga abin da Ubangiji Mai Iko Duka ya ce ya birnin da take kawo wa kansa hallaka ta wurin kisankai a cikinta kina kuma ƙazantar da kanki ta wurin yin gumaka, ");
INSERT INTO hausa_vpl VALUES ("EK22_4","027_22_4","EZK","22","4","4","kin zama mai laifi saboda jinin da kika zubar kika kuma zama ƙazantacciya ta wurin gumakan da kika yi. Kin kawo kwanakinki ga ƙarshe, kuma ƙarshen shekarunki sun zo. Saboda haka zan mai da ke abar ba’a ga al’ummai da abin dariya ga dukan ƙasashe. ");
INSERT INTO hausa_vpl VALUES ("EK22_5","027_22_5","EZK","22","5","5","Waɗanda suke kusa da waɗanda suke nesa za su yi miki ba’a, ya ke birni marar kunya, cike da rigima. ");
INSERT INTO hausa_vpl VALUES ("EK22_6","027_22_6","EZK","22","6","6","“ ‘Duba yadda kowane yerima Isra’ila waɗanda suke cikinki yake yin amfani da ikonsa yana kisankai. ");
INSERT INTO hausa_vpl VALUES ("EK22_7","027_22_7","EZK","22","7","7","A cikinki sun rena mahaifi da mahaifiya; a cikinki sun zalunci baƙo suka wulaƙanta maraya da gwauruwa. ");
INSERT INTO hausa_vpl VALUES ("EK22_8","027_22_8","EZK","22","8","8","Kin rena abubuwana masu tsarki kika kuma ƙazantar da Asabbataina. ");
INSERT INTO hausa_vpl VALUES ("EK22_9","027_22_9","EZK","22","9","9","A cikinki akwai mutane waɗanda suka nace su yi kisankai; a cikinki akwai waɗanda suke ci a dutsen tsafi suna yin ayyukan lalata. ");
INSERT INTO hausa_vpl VALUES ("EK22_10","027_22_10","EZK","22","10","10","A cikinki akwai waɗanda suke kwana da matan mahaifansu; a cikinki akwai waɗanda suke kwana da mata a lokacin da suke al’adarsu, sa’ad da suke da rashin tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK22_11","027_22_11","EZK","22","11","11","A cikinki mutum guda yakan yi laifi abin ƙyama da matar maƙwabcinsa, wani cikin rashin kunya ya ƙazantar da matar ɗansa, wani kuma ya kwana da ’yar’uwansa, ’yar mahaifinsa. ");
INSERT INTO hausa_vpl VALUES ("EK22_12","027_22_12","EZK","22","12","12","A cikinki mutane suna karɓan cin hanci don su yi kisankai; kina ba da rance da ruwa da ƙari, kina kuma cin riba a kan maƙwabcinki ta wurin ƙwace. Kina kuma manta da ni, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK22_13","027_22_13","EZK","22","13","13","“ ‘Tabbatacce zan tafa hannuwana a kan ƙazamar riba da kika ci da jinin da kin zubar a cikinki. ");
INSERT INTO hausa_vpl VALUES ("EK22_14","027_22_14","EZK","22","14","14","Ƙarfin halinki zai jure ko kuwa hannuwanki za su yi ƙarfi a ranar da na gamu da ke? Ni Ubangiji na faɗa, zan kuma aikata. ");
INSERT INTO hausa_vpl VALUES ("EK22_15","027_22_15","EZK","22","15","15","Zan watsar da ke cikin al’ummai in warwatsa ke cikin ƙasashe; zan kuma kawo ƙarshen rashin tsarkinki. ");
INSERT INTO hausa_vpl VALUES ("EK22_16","027_22_16","EZK","22","16","16","Sa’ad da ki ƙazantu a idanun al’umma, za ki san cewa ni ne Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK22_17","027_22_17","EZK","22","17","17","Sai maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK22_18","027_22_18","EZK","22","18","18","“Ɗan mutum, gidan Isra’ila ta zama ƙwan maƙera a gare ni; dukansu tagulla ne, kuza, ƙarfe da darma da suka rage a tanderu. Su ƙwan maƙerar azurfa ne kawai. ");
INSERT INTO hausa_vpl VALUES ("EK22_19","027_22_19","EZK","22","19","19","Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa, ‘Domin ku duka kun zama ƙwan maƙera, zan tattara ku a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("EK22_20","027_22_20","EZK","22","20","20","Kamar yadda mutane sukan tattara azurfa, tagulla, ƙarfe, darma da kuza a cikin tanderu don su narkar da su da wuta, haka zan tattara ku cikin fushina da kuma hasalata in sa ku cikin birnin in narkar da ku. ");
INSERT INTO hausa_vpl VALUES ("EK22_21","027_22_21","EZK","22","21","21","Zan tattara ku zan kuma hura muku wutar hasalata, za ku kuma narke a cikinta. ");
INSERT INTO hausa_vpl VALUES ("EK22_22","027_22_22","EZK","22","22","22","Kamar yadda azurfa kan narke a tanderu, haka za ku narke a cikinta, kuma za ku san cewa Ni Ubangiji na zubo muku da zafin fushina.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK22_23","027_22_23","EZK","22","23","23","Har yanzu maganar Ubangiji ta zo gare ni cewa, ");
INSERT INTO hausa_vpl VALUES ("EK22_24","027_22_24","EZK","22","24","24","“Ɗan mutum, ka faɗa wa ƙasar, ‘Ke ƙasa ce marar ruwan sama ko yayyafi a ranar hasala.’ ");
INSERT INTO hausa_vpl VALUES ("EK22_25","027_22_25","EZK","22","25","25","Akwai haɗin bakin sarakunanki a cikinki kamar rurin zaki mai yayyage ganimarsa; suna cin mutane, suna kwashe dukiya da abubuwa masu daraja suna mai da yawanci gwauraye a cikinki. ");
INSERT INTO hausa_vpl VALUES ("EK22_26","027_22_26","EZK","22","26","26","Firistocinki suna karya dokokina, sun ƙazantar da tsarkakan abubuwana; ba sa bambanta tsakanin tsarki da marar tsarki; suna koyarwa cewa babu bambanci tsakanin marar tsarki da mai tsarki; suna kuma rufe idanunsu ga kiyaye Asabbataina, da haka suke saɓon sunana. ");
INSERT INTO hausa_vpl VALUES ("EK22_27","027_22_27","EZK","22","27","27","Shugabanninki a cikinki suna kama da kyarketai masu yayyage ganimarsu; suna kisa suna kuma kashe mutane don samun ƙazamar riba. ");
INSERT INTO hausa_vpl VALUES ("EK22_28","027_22_28","EZK","22","28","28","Annabawanki sun yi wa waɗannan ayyuka shafe da farar ƙasa ta wurin wahayin ƙarya da duban ƙarya. Suna cewa, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa’ alhali kuwa Ubangiji bai faɗa ba. ");
INSERT INTO hausa_vpl VALUES ("EK22_29","027_22_29","EZK","22","29","29","Mutanen ƙasar na yin ƙwace suna yin fashi; suna cin zalin matalauta da mabukata suna wulaƙanta baƙo suna hana musu adalci. ");
INSERT INTO hausa_vpl VALUES ("EK22_30","027_22_30","EZK","22","30","30","“Na nemi mutum guda a cikinsu wanda zai gina katanga ya tsaya a gabana a tsakani a madadin ƙasar don kada in hallaka ta, amma ban sami ko ɗaya ba. ");
INSERT INTO hausa_vpl VALUES ("EK22_31","027_22_31","EZK","22","31","31","Saboda haka zan zuba hasalata a kansu in cinye su da wutar fushina, ina ɗora alhakin ayyukansu a bisa kawunansu, in ji Ubangiji Mai Iko Duka.” ");
INSERT INTO hausa_vpl VALUES ("EK23_1","027_23_1","EZK","23","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK23_2","027_23_2","EZK","23","2","2","“Ɗan mutum, an yi mata biyu, ’yan matan mahaifiya guda. ");
INSERT INTO hausa_vpl VALUES ("EK23_3","027_23_3","EZK","23","3","3","Suka zama karuwai a Masar, suka yi karuwanci tun daga ƙuruciyarsu. A wancan ƙasar an rungumi mamansu da ƙirjinsu na budurwanci. ");
INSERT INTO hausa_vpl VALUES ("EK23_4","027_23_4","EZK","23","4","4","Sunan babbar Ohola, ƙanuwarta kuwa Oholiba. Sun zama nawa suka kuma haifi ’ya’ya maza da mata. Ohola ita ce Samariya, Oholiba kuwa ita ce Urushalima. ");
INSERT INTO hausa_vpl VALUES ("EK23_5","027_23_5","EZK","23","5","5","“Ohola ta shiga karuwanci yayinda take zamana; ta kuwa yi ta kai da kawowa da kwartayenta, Assuriyawa, mayaƙa ");
INSERT INTO hausa_vpl VALUES ("EK23_6","027_23_6","EZK","23","6","6","waɗanda suke saye da shunayya, gwamnoni da manyan sojoji, dukansu samari ne masu bansha’awa, suna bisa kan dawakai. ");
INSERT INTO hausa_vpl VALUES ("EK23_7","027_23_7","EZK","23","7","7","Ta ba da kanta ga duk waɗanda suke masu ilimin Assuriya ta kuma ƙazantar da kanta da dukan gumaka na kowa da take kai da kawowa a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("EK23_8","027_23_8","EZK","23","8","8","Ba ta bar karuwancin da ta fara a Masar ba, sa’ad da take budurwa maza sun kwana da ita, suka rungumi ƙirjinta suka kuma biya kwaɗayinsu a kanta. ");
INSERT INTO hausa_vpl VALUES ("EK23_9","027_23_9","EZK","23","9","9","“Saboda haka na bashe ta ga kwartayenta, Assuriyawa, waɗanda ta yi ta kai da kawowa a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("EK23_10","027_23_10","EZK","23","10","10","Suka tuɓe ta tsirara, suka kwashe ’ya’yanta maza da mata suka kuma kashe ta da takobi. Ta kuwa zama abin karin magana a cikin mata, aka kuma yi mata hukunci. ");
INSERT INTO hausa_vpl VALUES ("EK23_11","027_23_11","EZK","23","11","11","“Ƙanuwarta Oholiba kuwa ta ga wannan, duk da haka cikin kai da kawowarta da karuwancinta ta fi ’yar’uwar lalacewa. ");
INSERT INTO hausa_vpl VALUES ("EK23_12","027_23_12","EZK","23","12","12","Ita ma ta yi ta kai da kawowa cikin Assuriyawa, gwamnoni da manyan sojoji; mayaƙa masu saye da kayan yaƙi, suna bisa dawakai, dukansu samari ne masu bansha’awa. ");
INSERT INTO hausa_vpl VALUES ("EK23_13","027_23_13","EZK","23","13","13","Na ga cewa ita ma ta ƙazantar da kanta; dukansu biyu sun bi hanya guda. ");
INSERT INTO hausa_vpl VALUES ("EK23_14","027_23_14","EZK","23","14","14","“Amma karuwancinta ya zarce. Ta ga an zāna mutane a kan bango, siffofin sojojin Kaldiyawa suna cikin jajjayen riguna, ");
INSERT INTO hausa_vpl VALUES ("EK23_15","027_23_15","EZK","23","15","15","da ɗamara a gindinsu da rawuna a kansu suna kaɗawa falfal; dukansu sun yi kamar jarumawan kekunan yaƙin Babiloniyawa ’yan Kaldiya. ");
INSERT INTO hausa_vpl VALUES ("EK23_16","027_23_16","EZK","23","16","16","Nan da nan da ta gan su, sai ta yi sha’awarsu ta aika da ’yan aika zuwa wurinsu a Kaldiya. ");
INSERT INTO hausa_vpl VALUES ("EK23_17","027_23_17","EZK","23","17","17","Sai Babiloniyawan suka zo wurinta, zuwa gadon soyayya, cikin kai da kawowarsu suka ƙazantar da ita. Bayan sun ƙazantar da ita, sai ta ji ƙyamarsu, ta rabu da su. ");
INSERT INTO hausa_vpl VALUES ("EK23_18","027_23_18","EZK","23","18","18","Sa’ad da ta ci gaba da yin karuwancinta a fili ta kuma nuna tsiraicinta, sai na ji ƙyamarta, na rabu da ita, kamar dai yadda na rabu da ’yar’uwarta. ");
INSERT INTO hausa_vpl VALUES ("EK23_19","027_23_19","EZK","23","19","19","Duk da haka sai ta yi ta ƙara fasikanci tana tuna da kwanakin budurcinta, sa’ad da take karuwa a Masar. ");
INSERT INTO hausa_vpl VALUES ("EK23_20","027_23_20","EZK","23","20","20","A can ta yi ta kai da kawowa da kwartayenta, waɗanda al’auransu kamar na jakuna ne waɗanda maniyyinsu kuwa kamar na dawakai ne. ");
INSERT INTO hausa_vpl VALUES ("EK23_21","027_23_21","EZK","23","21","21","Haka kika yi ta lalacin budurcinki, sa’ad da a Masar aka rungumi ƙirjinta aka tattaɓa nononta. ");
INSERT INTO hausa_vpl VALUES ("EK23_22","027_23_22","EZK","23","22","22","“Saboda haka, Oholiba, ga abin da Ubangiji Mai Iko Duka yana cewa zan zuga kwartayenki su yi gāba da ke, su waɗanda kika ji ƙyamarsu, zan kuma kawo su su yi gāba da ke daga kowane gefe, ");
INSERT INTO hausa_vpl VALUES ("EK23_23","027_23_23","EZK","23","23","23","Babiloniyawa da dukan Kaldiyawa, mutanen Fekod da Showa da Kowa, da dukan Assuriyawa, samari masu bansha’awa, dukan gwamnoni da manyan sojoji, hafsoshin keken yaƙin da mutane masu manyan matsayi, dukansu a bisa dawakai. ");
INSERT INTO hausa_vpl VALUES ("EK23_24","027_23_24","EZK","23","24","24","Za su yi gāba da ke da kayan yaƙi, kekunan yaƙi da kekunan doki da mutane masu yawa; za su ja dāgā a kanki a kowane gefe da garkuwoyi manya da ƙanana da kuma hulunan kwano. Zan miƙa ke gare su don hukunci, za su kuma hukunta ki bisa ga shari’arsu. ");
INSERT INTO hausa_vpl VALUES ("EK23_25","027_23_25","EZK","23","25","25","Zan nuna fushin kishina a kanki, za su kuwa wulaƙanta ki da fushi. Za su yanke hancinki da kunnuwanki, waɗanda suka rage miki kuma za a kashe su da takobi. Za su kama ’ya’yanki maza da mata, waɗanda suka rage miki kuwa za a ƙone su da wuta. ");
INSERT INTO hausa_vpl VALUES ("EK23_26","027_23_26","EZK","23","26","26","Za su tuɓe tufafinki su kuma kwashe kayan adonki masu kyau. ");
INSERT INTO hausa_vpl VALUES ("EK23_27","027_23_27","EZK","23","27","27","Ta haka zan tsai da marmari da kuma karuwancin da kika fara a Masar. Ba za ki dubi waɗannan abubuwa da marmari ko ki ƙara tuna da Masar ba. ");
INSERT INTO hausa_vpl VALUES ("EK23_28","027_23_28","EZK","23","28","28","“Gama ga abin da Ubangiji Mai Iko Duka yana cewa ina shirin miƙa ki ga waɗanda suke ƙinki, ga waɗanda kika ji ƙyamarsu kika rabu da su. ");
INSERT INTO hausa_vpl VALUES ("EK23_29","027_23_29","EZK","23","29","29","Za su hukunta ki da ƙiyayya su kuma kwashe kome da kika yi wahalarsa. Za su bar ki tsirara tik, kunyan karuwancinki kuma zai tonu. Marmarinki da fasikancinki ");
INSERT INTO hausa_vpl VALUES ("EK23_30","027_23_30","EZK","23","30","30","sun jawo miki wannan, domin ki yi ta kai da kawowa cikin ƙasashe kina ƙazantar da kanki da gumakansu. ");
INSERT INTO hausa_vpl VALUES ("EK23_31","027_23_31","EZK","23","31","31","Kin bi hanyar ’yar’uwarki; saboda haka zan sa kwaf nata a hannunki. ");
INSERT INTO hausa_vpl VALUES ("EK23_32","027_23_32","EZK","23","32","32","“Ga abin da Ubangiji Mai Iko Duka yana cewa, “Za ki sha kwaf na ’yar’uwarki, kwaf wanda yake da girma da kuma zurfi; zai jawo dariya da kuma reni gama yana ɗauke da abubuwa da yawa. ");
INSERT INTO hausa_vpl VALUES ("EK23_33","027_23_33","EZK","23","33","33","Za ki cika da buguwa da baƙin ciki, kwaf lalaci da kaɗaici, kwaf na ’yar’uwarki Samariya. ");
INSERT INTO hausa_vpl VALUES ("EK23_34","027_23_34","EZK","23","34","34","Za ki sha shi ki kuma lashe shi ƙaf; za ki buga shi da ƙasa ya yi rugu-rugu ki tsattsage nononki. Ni Ubangiji Mai Iko Duka na faɗa. ");
INSERT INTO hausa_vpl VALUES ("EK23_35","027_23_35","EZK","23","35","35","“Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa da yake kin manta da ni kika tura ni bayanki, dole ki sha sakamakon marmarinki da karuwancinki.” ");
INSERT INTO hausa_vpl VALUES ("EK23_36","027_23_36","EZK","23","36","36","Ubangiji ya ce mini, “Ɗan mutum, za ka shari’anta Ohola da Oholiba? To, sai ka kalubalance su da ayyukansu masu banƙyama, ");
INSERT INTO hausa_vpl VALUES ("EK23_37","027_23_37","EZK","23","37","37","gama sun yi zina kuma jinin yana a hannuwansu. Sun yi zina da gumakansu; har suka miƙa ’ya’yansu da suka haifa mini, su zama musu abinci. ");
INSERT INTO hausa_vpl VALUES ("EK23_38","027_23_38","EZK","23","38","38","Sun kuma yi mini wannan. A lokaci guda sun ƙazantar da wuri mai tsarkina suka ɓata Asabbataina. ");
INSERT INTO hausa_vpl VALUES ("EK23_39","027_23_39","EZK","23","39","39","A ranar da suka miƙa ’ya’yansu ga gumakansu, sai suka shiga wuri mai tsarkina suka kuma ƙazantar da shi. Abin da suka yi a gidana ke nan. ");
INSERT INTO hausa_vpl VALUES ("EK23_40","027_23_40","EZK","23","40","40","“Sun ma aiki manzanni wa mutanen da suka zo daga nesa, kuma da suka iso kun yi wanka dominsu, kuka yi shafe-shafen idanunku, kuka kuma sa kayan adonku. ");
INSERT INTO hausa_vpl VALUES ("EK23_41","027_23_41","EZK","23","41","41","Kuka zauna a gado mai daraja, da tebur a shirye a gabanku wanda kun ajiye turare da maina. ");
INSERT INTO hausa_vpl VALUES ("EK23_42","027_23_42","EZK","23","42","42","“Surutun taron mutane marasa kula suna kewaye da ita; aka kawo Sabenawa daga hamada tare da mutane daga mashaya, suka sa mundaye a hannuwan macen da kuma ’yar’uwarta suka kuma sa rawani masu kyau a kawunansu. ");
INSERT INTO hausa_vpl VALUES ("EK23_43","027_23_43","EZK","23","43","43","Sai na yi magana a kan wadda ta ƙare ƙarfi ta wurin karuwanci na ce, ‘Yanzu bari su yi amfani da ita kamar karuwa, gama abin da take ke nan.’ ");
INSERT INTO hausa_vpl VALUES ("EK23_44","027_23_44","EZK","23","44","44","Suka kuwa kwana da ita. Kamar yadda maza suke kwana ta karuwa, haka suka kwana da waɗannan lalatattun mata, Ohola da Oholiba. ");
INSERT INTO hausa_vpl VALUES ("EK23_45","027_23_45","EZK","23","45","45","Amma masu adalci za su hukunta su irin da akan yi wa matan da suka yi zina suka kuma yi kisa, domin su mazinata ne kuma jini yana a hannuwansu. ");
INSERT INTO hausa_vpl VALUES ("EK23_46","027_23_46","EZK","23","46","46","“Ga abin da Ubangiji Mai Iko Duka yana cewa kawo taron mutane a kansu a kuma miƙa su don a firgitar da su a kuma washe su. ");
INSERT INTO hausa_vpl VALUES ("EK23_47","027_23_47","EZK","23","47","47","Taron mutanen za su jajjefe su, su kuma sassare su da takuba; za su kashe ’ya’yansu maza da mata su kuma ƙone gidajensu. ");
INSERT INTO hausa_vpl VALUES ("EK23_48","027_23_48","EZK","23","48","48","“Ta haka zan kawo ƙarshe ga lalaci a ƙasar, don dukan mata su ji gargaɗi kada kuma su kwaikwaye ku ");
INSERT INTO hausa_vpl VALUES ("EK23_49","027_23_49","EZK","23","49","49","Za ku sha hukuncin lalacinku ku kuma ɗauki hakkin zunuban bautar gumaka. Sa’an nan za ku san cewa Ni ne Ubangiji Mai Iko Duka.” ");
INSERT INTO hausa_vpl VALUES ("EK24_1","027_24_1","EZK","24","1","1","A shekara ta tara, a wata na goma, a rana ta goma, maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK24_2","027_24_2","EZK","24","2","2","“Ɗan mutum, ka rubuta wannan rana, wannan rana, domin sarkin Babilon ya yi ƙawanya wa Urushalima a wannan rana. ");
INSERT INTO hausa_vpl VALUES ("EK24_3","027_24_3","EZK","24","3","3","Ka faɗa wa wannan gidan ’yan tawaye wani misali ka kuma faɗa musu cewa, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Ka sa tukunyar dahuwa; ka sa ta a kan wuta ka kuma zuba ruwa a cikinta. ");
INSERT INTO hausa_vpl VALUES ("EK24_4","027_24_4","EZK","24","4","4","Ka sa gunduwoyin nama a cikinta dukan gunduwoyi masu kyau, cinya da kafaɗa. Ka cika ta da waɗannan ƙasusuwa mafi kyau; ");
INSERT INTO hausa_vpl VALUES ("EK24_5","027_24_5","EZK","24","5","5","ka kama mafi kyau daga cikin garken. Ka tara itace a ƙarƙashinta saboda ƙasusuwan; ka sa ta tafasa ka kuma dafa ƙasusuwan a cikinta. ");
INSERT INTO hausa_vpl VALUES ("EK24_6","027_24_6","EZK","24","6","6","“ ‘Gama wannan shi ne abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Kaito birnin nan mai zubar da jini, ga tukunya wadda take da tsatsa, wadda tsatsarta ba za tă fita ba! Ka fitar da shi gunduwa-gunduwa ba tare da jefa ƙuri’a a kansu ba. ");
INSERT INTO hausa_vpl VALUES ("EK24_7","027_24_7","EZK","24","7","7","“ ‘Gama zubar da jini yana a tsakiyarta, ta zubar da shi a dutsen da yake a fili; ba tă zubar da shi a ƙasa ba, inda ƙura za tă rufe shi. ");
INSERT INTO hausa_vpl VALUES ("EK24_8","027_24_8","EZK","24","8","8","Don a zuga hasala a kuma yi sakayya na sa jininta a dutsen da ba a rufe ba, saboda kada a rufe. ");
INSERT INTO hausa_vpl VALUES ("EK24_9","027_24_9","EZK","24","9","9","“ ‘Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Kaito birnin nan mai zubar da jini! Ni ma zan jibge itace da yawa. ");
INSERT INTO hausa_vpl VALUES ("EK24_10","027_24_10","EZK","24","10","10","Ka tula gumagumai ka kuma ƙuna wuta. Ka dafa naman da kyau, kana haɗawa da yaji; ka kuma bar ƙasusuwan su ƙone. ");
INSERT INTO hausa_vpl VALUES ("EK24_11","027_24_11","EZK","24","11","11","Sa’an nan ka sa tukunyan nan da babu kome a kan garwashi sai ta yi zafi har darmarta ta yi ja wur domin dattinta ya narke tsatsarta kuma ta ƙone. ");
INSERT INTO hausa_vpl VALUES ("EK24_12","027_24_12","EZK","24","12","12","Ta gajiyar da dukan ƙoƙari; ba a fid da tsatsarta nan mai yawa ba, kai, ko a wuta ma. ");
INSERT INTO hausa_vpl VALUES ("EK24_13","027_24_13","EZK","24","13","13","“ ‘Yanzu ƙazantarki ita ce lalaci. Domin na yi ƙoƙari in tsabtacce ke amma ba ki tsabtattu daga ƙazantarki ba, ba za ki ƙara yin tsabta ba sai hasalata a kanki ya kwanta. ");
INSERT INTO hausa_vpl VALUES ("EK24_14","027_24_14","EZK","24","14","14","“ ‘Ni Ubangiji na faɗa. Lokaci ya zo da zan aikata. Ba zan janye ba; ba zan ji tausayi ba, ba kuwa zan bari ba. Za a hukunta ki bisa ga hali da ayyukanki, in ji Ubangiji Mai Iko Duka.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK24_15","027_24_15","EZK","24","15","15","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK24_16","027_24_16","EZK","24","16","16","“Ɗan mutum, da farat ɗaya ina gab da ɗauke abin da idanunka suke jin daɗin gani. Duk da haka kada ka yi makoki ko ka yi kuka ko ka zub da hawaye. ");
INSERT INTO hausa_vpl VALUES ("EK24_17","027_24_17","EZK","24","17","17","Ka yi nishi shiru; kada ka yi makoki saboda matacciyar. Ka naɗa rawaninka ka kuma sa takalmanka a ƙafa; kada ka rufe sashen fuskarka daga ƙasa ko ka ci abincin da masu kuka sukan ci.” ");
INSERT INTO hausa_vpl VALUES ("EK24_18","027_24_18","EZK","24","18","18","Da gari ya waye, sai na yi magana da mutane, da yamma kuwa matata ta rasu. Kashegari na yi yadda aka umarce ni. ");
INSERT INTO hausa_vpl VALUES ("EK24_19","027_24_19","EZK","24","19","19","Sai mutane suka tambaye ni suka ce, “Ba za ka faɗa mana abin da waɗannan abubuwa suke nufi a gare mu ba?” ");
INSERT INTO hausa_vpl VALUES ("EK24_20","027_24_20","EZK","24","20","20","Sai na ce musu, “Maganar Ubangiji ta zo mini cewa ");
INSERT INTO hausa_vpl VALUES ("EK24_21","027_24_21","EZK","24","21","21","faɗa wa gidan Isra’ila, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa ina gab da ƙazantar da wuri mai tsarkina, kagarar da kuke taƙama, abin da idanunku suke jin daɗin gani, abin faranta zuciyarku. ’Ya’yanku maza da mata waɗanda kun bari a baya za su mutu ta wurin takobi. ");
INSERT INTO hausa_vpl VALUES ("EK24_22","027_24_22","EZK","24","22","22","Za ku kuma yi yadda na yi. Ba za ku rufe sashe ƙasa na fuskarku ko ku ci abinci da masu kuka sukan ci ba. ");
INSERT INTO hausa_vpl VALUES ("EK24_23","027_24_23","EZK","24","23","23","Za ku naɗa rawunanku a kai ku sa takalmanku a ƙafafunku. Ba za ku yi kuka ko makoki ba amma za ku lalace saboda zunubanku ku kuma yi ta yin nishi. ");
INSERT INTO hausa_vpl VALUES ("EK24_24","027_24_24","EZK","24","24","24","Ezekiyel zai zama alama gare ku; za ku yi daidai yadda ya yi. Sa’ad da wannan ya faru, za ku san cewa ni ne Ubangiji Mai Iko Duka.’ ");
INSERT INTO hausa_vpl VALUES ("EK24_25","027_24_25","EZK","24","25","25","“Kai kuma ɗan mutum, a ranar da zan ɗauke musu kagararsu, farin cikinsu da darajarsu, abin da idanunsu ke jin daɗin gani, abin da yake faranta musu zuciya, da kuka ’ya’yansu maza da mata, ");
INSERT INTO hausa_vpl VALUES ("EK24_26","027_24_26","EZK","24","26","26","a ranan nan wanda ya tsere zai zo don yă ba ka labari. ");
INSERT INTO hausa_vpl VALUES ("EK24_27","027_24_27","EZK","24","27","27","A lokacin bakinka zai buɗe, za ka yi magana da shi ba kuwa za ka ƙara yin shiru ba. Ta haka za ka zama alama gare su, za su kuwa san cewa ni ne Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("EK25_1","027_25_1","EZK","25","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK25_2","027_25_2","EZK","25","2","2","“Ɗan mutum, ka fuskanci wajen Ammonawa ka kuma yi annabci a kansu. ");
INSERT INTO hausa_vpl VALUES ("EK25_3","027_25_3","EZK","25","3","3","Ka ce musu, ‘Ku ji maganar Ubangiji Mai Iko Duka. Ga abin da Ubangiji Mai Iko Duka yana cewa domin kun ce “Yauwa” a kan wuri mai tsarkina sa’ad da aka ƙazantar da shi da kuma a kan ƙasar Isra’ila sa’ad da aka mai da ita kufai da lokacin da aka kai mutanen Yahuda bautar talala, ");
INSERT INTO hausa_vpl VALUES ("EK25_4","027_25_4","EZK","25","4","4","saboda haka zan ba da ku ga mutanen Gabas abin mallaka. Za su kafa sansanoninsu su yi tentunansu a cikinku; za su ci ’ya’yan itatuwanku su kuma sha madararku. ");
INSERT INTO hausa_vpl VALUES ("EK25_5","027_25_5","EZK","25","5","5","Zan mai da Rabba wurin kiwo don raƙuma, Ammon kuma wurin hutu don tumaki. Sa’an nan za ku san cewa ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK25_6","027_25_6","EZK","25","6","6","Gama ga abin da Ubangiji Mai Iko Duka yana cewa domin kun tafa hannuwanku kuka kuma buga ƙafafunku, kuna farin ciki don nuna dukan ƙiyayyarku a kan ƙasar Isra’ila, ");
INSERT INTO hausa_vpl VALUES ("EK25_7","027_25_7","EZK","25","7","7","saboda haka zan miƙa hannuna gāba da ku in kuma ba da ku ganima ga al’ummai. Zan datse ku daga al’ummai in kuma kore ku daga ƙasashe. Zan hallaka ku, za ku kuwa san cewa ni ne Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK25_8","027_25_8","EZK","25","8","8","“Ga abin da Ubangiji Mai Iko Duka yana cewa, ‘Domin Mowab da Seyir sun ce, “Duba, gidan Yahuda ta zama sauran al’ummai,” ");
INSERT INTO hausa_vpl VALUES ("EK25_9","027_25_9","EZK","25","9","9","saboda haka zan buɗe ƙofar shiga Mowab, farawa daga garuruwan da suke kan iyaka, Bet-Yeshimot, Ba’al-Meyon da Kiriyatayim, darajar ƙasar. ");
INSERT INTO hausa_vpl VALUES ("EK25_10","027_25_10","EZK","25","10","10","Zan ba da Mowabawa tare da Ammonawa ga mutanen Gabas abin mallaka, don kada a ƙara tuna da Ammonawa a cikin al’ummai; ");
INSERT INTO hausa_vpl VALUES ("EK25_11","027_25_11","EZK","25","11","11","zan hukunta Mowabawa. Ta haka za su san cewa ni ne Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK25_12","027_25_12","EZK","25","12","12","“Ga abin da Ubangiji Mai Iko Duka yana cewa, ‘Domin Edom ya ɗauki wa kanta fansa a kan gida Yahuda, ta yi babban laifi ta wurin yin haka, ");
INSERT INTO hausa_vpl VALUES ("EK25_13","027_25_13","EZK","25","13","13","saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa zan miƙa hannuna a kan Edom in kashe mutanenta da dabbobinsu. Zan sa ta zama kufai, kuma tun daga Teman har zuwa Dedan za a kashe su da takobi. ");
INSERT INTO hausa_vpl VALUES ("EK25_14","027_25_14","EZK","25","14","14","Zan ɗau fansa a kan Edom ta hannun mutanena Isra’ila, za su kuwa hukunta Edom bisa ga fushina da hasalata; za su san sakayyata, in ji Ubangiji Mai Iko Duka.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK25_15","027_25_15","EZK","25","15","15","“Ga abin da Ubangiji Mai Iko Duka yana cewa, ‘Domin Filistiyawa sun yi sakayya, suka ɗauki fansa da mugunta a zukatansu, da kuma daɗaɗɗen ƙiyayya sun nemi su hallaka Yahuda, ");
INSERT INTO hausa_vpl VALUES ("EK25_16","027_25_16","EZK","25","16","16","saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa ina gab da miƙa hannuna a kan Filistiyawa, zan kuwa datse Keretawa in kuma hallaka waɗanda suka rage a bakin teku. ");
INSERT INTO hausa_vpl VALUES ("EK25_17","027_25_17","EZK","25","17","17","Zan yi musu babbar sakayya da hukunci mai tsanani cikin hasalata. Sa’an nan za su san cewa ni ne Ubangiji, sa’ad da na ɗauki fansa a kansu.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK26_1","027_26_1","EZK","26","1","1","A shekara ta goma sha ɗaya, a rana ta fari ga wata, maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK26_2","027_26_2","EZK","26","2","2","“Ɗan mutum, domin Taya ta yi magana a kan Urushalima ta ce, ‘Yauwa! Ƙofar zuwa al’ummai ta karye, an kuma buɗe mini ƙofofinta; yanzu da take kufai zan wadace,’ ");
INSERT INTO hausa_vpl VALUES ("EK26_3","027_26_3","EZK","26","3","3","saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa ina gāba da ke, ya Taya, zan kuwa kawo al’ummai masu yawa su yi gāba da ke, kamar yadda teku takan kawo raƙuman ruwa. ");
INSERT INTO hausa_vpl VALUES ("EK26_4","027_26_4","EZK","26","4","4","Za su hallaka katangar Taya su kuma rurrushe hasumiyoyinta; zan kankare tarkacenta, in maishe ta fā. ");
INSERT INTO hausa_vpl VALUES ("EK26_5","027_26_5","EZK","26","5","5","Za tă zama wurin shanya abin kamun kifi a tsakiyar teku, gama na faɗa, in ji Ubangiji Mai Iko Duka. Za tă zama ganima ga sauran al’ummai, ");
INSERT INTO hausa_vpl VALUES ("EK26_6","027_26_6","EZK","26","6","6","za a kashe mazaunan filin ƙasar da takobi. Ta haka za su san cewa ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK26_7","027_26_7","EZK","26","7","7","“Gama ga abin da Ubangiji Mai Iko Duka yana cewa daga arewa zan kawo wa Taya Nebukadnezzar sarkin Babilon, sarkin sarakuna, tare da dawakai da kekunan yaƙi, da mahayan dawakai da babbar rundunar soja. ");
INSERT INTO hausa_vpl VALUES ("EK26_8","027_26_8","EZK","26","8","8","Zai kashe mazaunan filin ƙasar da takobi; zai yi miki ƙawanya, ya gina miki mahaurai, sa’an nan ya rufe ki da garkuwoyi. ");
INSERT INTO hausa_vpl VALUES ("EK26_9","027_26_9","EZK","26","9","9","Zai rushe katangarki da dundurusai, ya rurrushe hasumiyoyinki da makamai. ");
INSERT INTO hausa_vpl VALUES ("EK26_10","027_26_10","EZK","26","10","10","Dawakansa za su yi yawa har su rufe ke da ƙura. Katanga za su girgiza saboda motsin dawakan yaƙi, kekunan doki da keken yaƙin sa’ad da suka shiga birnin da aka rushe katangar. ");
INSERT INTO hausa_vpl VALUES ("EK26_11","027_26_11","EZK","26","11","11","Kofatan dawakansa za su tattake dukan titunanki; zai kashe mutanenki da takobi, ginshiƙanki masu ƙarfi kuma za su fāɗi a ƙasa. ");
INSERT INTO hausa_vpl VALUES ("EK26_12","027_26_12","EZK","26","12","12","Za su washe dukiyarki, kayan cinikinki kuma su zama ganima; za su rurrushe katangarki su ragargaza gidajenki masu kyau su kuma zubar da duwatsunki, katakanki da kuma tarkacenki a cikin teku. ");
INSERT INTO hausa_vpl VALUES ("EK26_13","027_26_13","EZK","26","13","13","Zan kawo ƙarshen waƙoƙinki masu surutu, ba kuwa za a ƙara jin kaɗe-kaɗen garayunki ba. ");
INSERT INTO hausa_vpl VALUES ("EK26_14","027_26_14","EZK","26","14","14","Zan maishe ki fā, za ki kuma zama wurin shanya abin kamun kifi. Ba za a sāke gina ki ba, gama Ni Ubangiji na faɗa, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK26_15","027_26_15","EZK","26","15","15","“Ga abin da Ubangiji Mai Iko Duka yana cewa wa Taya. Ƙasashen da suke a bakin teku ba za su girgiza saboda ƙarar fāɗuwarki, sa’ad da nishin waɗanda aka yi wa rauni da kashe-kashen da aka yi a cikinki suka faru ba? ");
INSERT INTO hausa_vpl VALUES ("EK26_16","027_26_16","EZK","26","16","16","Sa’an nan sarakunan bakin teku za su sauka daga gadajen sarautarsu, su tuɓe rigunansu, da rigunansu waɗanda aka yi wa ado. Za su zauna a ƙasa suna rawar jiki a kowane lokaci suna razana saboda abin da ya same ki. ");
INSERT INTO hausa_vpl VALUES ("EK26_17","027_26_17","EZK","26","17","17","Sa’an nan za su yi makoki game da ke su ce, “ ‘Yaya kika hallaka haka nan, ya birnin da ta yi suna, cike da mutanen teku! Ke da kika zama mai ƙarfi cikin tekuna, ke da mazauna cikinki; kin sa tsoronki a kan dukan waɗanda suka zauna a can. ");
INSERT INTO hausa_vpl VALUES ("EK26_18","027_26_18","EZK","26","18","18","Yanzu tsibirai suna rawar jiki a ranar fāɗuwarki; tsibirai a cikin teku sun tsorata a ɓacewarki.’ ");
INSERT INTO hausa_vpl VALUES ("EK26_19","027_26_19","EZK","26","19","19","“Ga abin da Ubangiji Mai Iko Duka yana cewa sa’ad da na maishe ki kufai, kamar sauran biranen da ba a ƙara zama a ciki, sa’ad da kuma na kawo zurfafan teku a kanki da yawan ruwansa suka rufe ki, ");
INSERT INTO hausa_vpl VALUES ("EK26_20","027_26_20","EZK","26","20","20","a sa’an nan zan sauko da ke ƙasa tare da waɗanda suke gangarawa zuwa rami, zuwa wurin mutanen dā. Zan sa ki zauna ƙarƙashin ƙasa, kamar a kufai na tun dā, tare da waɗanda suke gangarawa zuwa rami, ba kuwa za ki ƙara dawowa ba ko ki ɗauki matsayinki a ƙasar masu rai. ");
INSERT INTO hausa_vpl VALUES ("EK26_21","027_26_21","EZK","26","21","21","Zan sa ki yi mummunan ƙarshe kuma ba za ki ƙara kasancewa ba. Za a neme ki, amma ba za a ƙara same ki ba, in ji Ubangiji Mai Iko Duka.” ");
INSERT INTO hausa_vpl VALUES ("EK27_1","027_27_1","EZK","27","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK27_2","027_27_2","EZK","27","2","2","“Ɗan mutum, ka yi makoki domin Taya. ");
INSERT INTO hausa_vpl VALUES ("EK27_3","027_27_3","EZK","27","3","3","Ka ce wa Taya, wadda take zaune a hanyar shiga zuwa teku, kasuwar masu yawa mutane a bakin teku, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Kin ce, ya Taya, “Ni kyakkyawa ce cikakkiya.” ");
INSERT INTO hausa_vpl VALUES ("EK27_4","027_27_4","EZK","27","4","4","Manyan tekuna ne wurin zamanki; maginanki sun sa kyanki ya zama cikakke. ");
INSERT INTO hausa_vpl VALUES ("EK27_5","027_27_5","EZK","27","5","5","Sun yi dukan katakanki daga itatuwan fir daga Senir; sun kwaso itatuwan al’ul daga Lebanon don su yi miki jigon jirgin ruwa. ");
INSERT INTO hausa_vpl VALUES ("EK27_6","027_27_6","EZK","27","6","6","Da oak daga Bashan suka yi sandunan tuƙan jirgin ruwa da itatuwan kasharina daga bakin tekun Saifurus suka yi daɓe jirgin ruwanki, suka kuma manne masa hauren giwa. ");
INSERT INTO hausa_vpl VALUES ("EK27_7","027_27_7","EZK","27","7","7","Lilin mai kyau mai ado daga Masar ne filafilan jirgin ruwanki suka kuma zama tutarki; an yi tutarki da shuɗi da shunayya daga bakin tekun Elisha. ");
INSERT INTO hausa_vpl VALUES ("EK27_8","027_27_8","EZK","27","8","8","Mutanen Sidon da Arfad su ne matuƙan jirgin ruwanki; gwanayenki, ya Taya, suna ciki a matsayi matuƙan jiragen ruwa. ");
INSERT INTO hausa_vpl VALUES ("EK27_9","027_27_9","EZK","27","9","9","Masu hikima na Gebal suna ciki a matsayin masu tattoshe mahaɗan katakon jirginki. Dukan jiragen ruwa da matuƙansu sukan zo wurinki don kasuwanci. ");
INSERT INTO hausa_vpl VALUES ("EK27_10","027_27_10","EZK","27","10","10","“ ‘Mutanen Farisa, Lidiya da Fut su ne suka zama sojoji a cikin mayaƙanki. Sun rataye garkuwoyinsu da hulunan kwano a katangarki, suna kawo miki daraja. ");
INSERT INTO hausa_vpl VALUES ("EK27_11","027_27_11","EZK","27","11","11","Mutanen Arfad da Helek sun yi tsaron katangar a kowace gefe; mutanen Gammad su ne a hasumiyoyinki. Sun rataye garkuwoyinsu kewaye da katangarki; sun sa kyanki ya zama cikakke. ");
INSERT INTO hausa_vpl VALUES ("EK27_12","027_27_12","EZK","27","12","12","“ ‘Tarshish ta yi ciniki da ke saboda yawan wadatar kayayyakinki; sun sayi kayan cinikinki da azurfa, ƙarfe, kuza da dalma. ");
INSERT INTO hausa_vpl VALUES ("EK27_13","027_27_13","EZK","27","13","13","“ ‘Girka, Tubal da Meshek sun yi kasuwanci da ke; sun sayi kayanki suka biya da bayi da kuma abubuwan da aka yi da tagulla. ");
INSERT INTO hausa_vpl VALUES ("EK27_14","027_27_14","EZK","27","14","14","“ ‘Mutanen Bet Togarma sun sayi kayan cinikinki da dawakai, dawakan yaƙi da alfadarai. ");
INSERT INTO hausa_vpl VALUES ("EK27_15","027_27_15","EZK","27","15","15","“ ‘Mutanen Dedan sun yi kasuwanci da ke, bakin teku masu yawa abokan cinikinki ne; sun biya ki da hauren giwa da katakon kanya. ");
INSERT INTO hausa_vpl VALUES ("EK27_16","027_27_16","EZK","27","16","16","“ ‘Mutanen Aram sun yi ciniki da ke saboda yawan kayanki; suka sayi kayan cinikinki da zumurrudu, da shunayya, da kayan ado, da lilin mai taushi, da murjani, da yakutu. ");
INSERT INTO hausa_vpl VALUES ("EK27_17","027_27_17","EZK","27","17","17","“ ‘Yahuda da Isra’ila sun yi kasuwanci da ke; sun sayi kayanki da alkama da Minnit da alawa, da zuma, da mai, da ganyaye masu ƙanshi. ");
INSERT INTO hausa_vpl VALUES ("EK27_18","027_27_18","EZK","27","18","18","“ ‘Mutanen Damaskus sun ga abin da za ki iya bayarwa sai suka yi ciniki da ke, ta sayi kayanki da ruwan inabi daga Helbon, da ulu daga Zahar. ");
INSERT INTO hausa_vpl VALUES ("EK27_19","027_27_19","EZK","27","19","19","Wedan da Yaban kusa da Uzal, suka sayi kayanki; wato gyararren ƙarfe da kayan yaji. ");
INSERT INTO hausa_vpl VALUES ("EK27_20","027_27_20","EZK","27","20","20","“ ‘Mutanen Dedan sun sayi kayanki da sirdin zama a kan dawakai. ");
INSERT INTO hausa_vpl VALUES ("EK27_21","027_27_21","EZK","27","21","21","“ ‘Mutanen Arabiya da dukan sarakunan Kedar abokan cinikinki ne; sun yi ciniki da ke suka sayi kayanki da ’yan raguna, da raguna, da awaki. ");
INSERT INTO hausa_vpl VALUES ("EK27_22","027_27_22","EZK","27","22","22","“ ‘’Yan kasuwan Sheba da Ra’ama sun yi ciniki da ke; suka sayi kayanki da kayan yaji mafi kyau iri-iri, da duwatsu masu daraja iri-iri, da zinariya. ");
INSERT INTO hausa_vpl VALUES ("EK27_23","027_27_23","EZK","27","23","23","“ ‘Haran, Kanne da Eden da kuma ’yan kasuwan Sheba, Assuriya da Kilmad sun yi ciniki da ke. ");
INSERT INTO hausa_vpl VALUES ("EK27_24","027_27_24","EZK","27","24","24","A kasuwarki sun yi ciniki da ke suka sayar miki tufafi masu tsada, da na shuɗi, da masu ado, da dardumai masu ƙyalƙyali da kirtani, da igiyoyi waɗanda aka tuƙa da kyau. ");
INSERT INTO hausa_vpl VALUES ("EK27_25","027_27_25","EZK","27","25","25","“ ‘Jiragen ruwan Tarshish sun zama masu jigilar kayanki. Kin cika da kaya masu nauyi a tsakiyar teku. ");
INSERT INTO hausa_vpl VALUES ("EK27_26","027_27_26","EZK","27","26","26","Matuƙan jiragenki sun kai ki can cikin manyan tekuna. Amma iskar gabas za tă farfasa ki kucu-kucu a tsakiyar teku. ");
INSERT INTO hausa_vpl VALUES ("EK27_27","027_27_27","EZK","27","27","27","Dukiyarki, cinikinki da kayan kasuwarki, ma’aikatanki na jirgi, matuƙan jiragenki da masu tattoshe mahaɗan katakan jiragenki, ’yan kasuwarki da dukan sojojinki, da kuma kowa da yake cikin jirgi zai nutsa a tsakiyar teku a ranar da jirginki zai nutse. ");
INSERT INTO hausa_vpl VALUES ("EK27_28","027_27_28","EZK","27","28","28","Ƙasashen bakin teku za su girgiza sa’ad da matuƙan jirginki suka yi kuka. ");
INSERT INTO hausa_vpl VALUES ("EK27_29","027_27_29","EZK","27","29","29","Dukan waɗanda suke riƙe da matuƙi za su ƙyale jiragensu; ma’aikatan jirage da dukan matuƙan jirage za su tsaya a bakin teku. ");
INSERT INTO hausa_vpl VALUES ("EK27_30","027_27_30","EZK","27","30","30","Za su tā da muryarsu su yi kuka mai zafi a kanki; za su yayyafa ƙura a kawunansu, su yi ta birgima a cikin toka. ");
INSERT INTO hausa_vpl VALUES ("EK27_31","027_27_31","EZK","27","31","31","Za su aske kawunansu saboda ke za su kuma sa tufafin makoki. Za su yi kuka dominki su yi ɓacin rai da kuma kuka mai zafi. ");
INSERT INTO hausa_vpl VALUES ("EK27_32","027_27_32","EZK","27","32","32","Yayinda suke kuka a kanki kuwa, za su yi makoki dominki suna cewa, “Wa ya taɓa yin shiru kamar Taya, kewaye da teku?” ");
INSERT INTO hausa_vpl VALUES ("EK27_33","027_27_33","EZK","27","33","33","Sa’ad da kayan cinikinki suka tafi ƙasashen hayi, kin gamsar da al’ummai masu yawa; da dukiyarki masu yawa da kuma kayan cinikinki kin azurtar da sarakunan duniya. ");
INSERT INTO hausa_vpl VALUES ("EK27_34","027_27_34","EZK","27","34","34","Yanzu teku ta farfashe ki cikin zurfafan ruwaye; kayan cinikinki da dukan kamfaninki sun nutse tare da ke. ");
INSERT INTO hausa_vpl VALUES ("EK27_35","027_27_35","EZK","27","35","35","Dukan mazaunan bakin teku sun giggice saboda masifarki; sarakunansu sun tsorata ƙwarai fuskokinsu kuwa sun yamutse don tsoro. ");
INSERT INTO hausa_vpl VALUES ("EK27_36","027_27_36","EZK","27","36","36","’Yan kasuwa a cikin al’ummai suna yin miki tsaki; kin zo ga mummunar ƙarshe ba za ki ƙara kasancewa ba har abada.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK28_1","027_28_1","EZK","28","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK28_2","027_28_2","EZK","28","2","2","“Ɗan mutum, ka faɗa wa mai mulkin Taya cewa, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Cikin alfarmar zuciyarka ka ce, “Ni allah ne; ina zama a kan kursiyin allah a tsakiyar tekuna.” Amma kai mutum ne ba allah ba, ko da yake ka ɗauka kana da hikima kamar allah. ");
INSERT INTO hausa_vpl VALUES ("EK28_3","027_28_3","EZK","28","3","3","Ka fi Daniyel hikima ne? Ba asirin da yake ɓoye a gare ka? ");
INSERT INTO hausa_vpl VALUES ("EK28_4","027_28_4","EZK","28","4","4","Ta wurin hikimarka da ganewarka ka sami dukiya wa kanka ka kuma tara zinariya da azurfa cikin wuraren ajiyarka. ");
INSERT INTO hausa_vpl VALUES ("EK28_5","027_28_5","EZK","28","5","5","Ta wurin dabararka mai girma cikin kasuwanci ka ƙara dukiyarka, kuma saboda dukiyarka zuciyarka ta cika da alfarma. ");
INSERT INTO hausa_vpl VALUES ("EK28_6","027_28_6","EZK","28","6","6","“ ‘Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Domin ka ɗauka kai mai hikima ne, mai hikima kamar allah, ");
INSERT INTO hausa_vpl VALUES ("EK28_7","027_28_7","EZK","28","7","7","zan kawo baƙi a kanka, waɗanda suka fi mugunta cikin sauran al’ummai; za su zāre takubansu a kan kyakkyawar hikimarka su kuma ɓarke darajarka mai walƙiya. ");
INSERT INTO hausa_vpl VALUES ("EK28_8","027_28_8","EZK","28","8","8","Za su jefar da kai cikin rami, za ka kuwa yi muguwar mutuwa a tsakiyar tekuna. ");
INSERT INTO hausa_vpl VALUES ("EK28_9","027_28_9","EZK","28","9","9","Za ka iya ce yanzu, “Ni allah ne,” a gaban waɗanda suka kashe ka? Za ka zama mutum kurum, ba allah ba, a hannuwan waɗanda suka kashe ka. ");
INSERT INTO hausa_vpl VALUES ("EK28_10","027_28_10","EZK","28","10","10","Za ka yi mutuwar marar kaciya a hannuwan baƙi. Na faɗa, in ji Ubangiji Mai Iko Duka.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK28_11","027_28_11","EZK","28","11","11","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK28_12","027_28_12","EZK","28","12","12","“Ɗan mutum, ka yi makoki domin sarkin Taya ka kuma ce masa, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Ka kasance hatimin cikakke, cike da hikima da cikakke a kyau. ");
INSERT INTO hausa_vpl VALUES ("EK28_13","027_28_13","EZK","28","13","13","Ka kasance a Eden, a lambun Allah; aka yi maka ado da kowane dutse mai daraja, yakutu, tofaz, da zumurrudu, kirisolit, onis da yasfa, saffaya, turkuwoyis da beril. Tsare-tsare da shirye-shiryenka an yi su da zinariya ne; a ranar da aka halicce ka an shirya su. ");
INSERT INTO hausa_vpl VALUES ("EK28_14","027_28_14","EZK","28","14","14","An shafe ka kamar kerub mai tsaro, gama haka na naɗa ka. Kana a tsattsarkan dutsen Allah; ka yi tafiya a tsakiyar duwatsun wuta. ");
INSERT INTO hausa_vpl VALUES ("EK28_15","027_28_15","EZK","28","15","15","Ka kasance marar laifi cikin dukan hanyoyinka daga ranar da aka halicce ka sai da aka sami mugunta a cikinka. ");
INSERT INTO hausa_vpl VALUES ("EK28_16","027_28_16","EZK","28","16","16","Ta wurin yawan kasuwancinka ka cika da rikici, ka kuma yi zunubi. Saboda haka na kore ka da kunya daga dutsen Allah, na kore ka, ya kerub mai tsaro, daga cikin duwatsun wuta. ");
INSERT INTO hausa_vpl VALUES ("EK28_17","027_28_17","EZK","28","17","17","Zuciyarka ta cika da alfarma saboda kyanka, ka kuma lalace hikimarka saboda darajarka. Saboda haka na jefar da kai zuwa ƙasa; na sa ka zama abin kallo a gaban sarakuna. ");
INSERT INTO hausa_vpl VALUES ("EK28_18","027_28_18","EZK","28","18","18","Ta wurin yawan zunubanka da kasuwancinka na cuta ka ƙazantar da wuri mai tsarkinka. Saboda haka na sa wuta ta fito daga cikinka, ta cinye ka, na maishe ka toka a bisa ƙasa a kan idon dukan waɗanda suke kallonka. ");
INSERT INTO hausa_vpl VALUES ("EK28_19","027_28_19","EZK","28","19","19","Dukan al’umman da suka san ka sun giggice saboda masifar da ta auko maka; ka zo ga mummunar ƙarshe ba za ka ƙara kasancewa ba har abada.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK28_20","027_28_20","EZK","28","20","20","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK28_21","027_28_21","EZK","28","21","21","“Ɗan mutum, ka fuskanci Sidon; ka yi annabci a kanta ");
INSERT INTO hausa_vpl VALUES ("EK28_22","027_28_22","EZK","28","22","22","ka ce, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Ina gāba da ke, ya Sidon, zan sami ɗaukaka a cikinki. Za su san cewa ni ne Ubangiji, sa’ad da na zartar da hukunci a kanta na kuma nuna kaina mai tsarki a cikinta. ");
INSERT INTO hausa_vpl VALUES ("EK28_23","027_28_23","EZK","28","23","23","Zan aika da annoba a kanta in kuma sa jini ya zuba a titunanta. Kisassu za su fāɗi a cikinta, da takobi yana gāba da ita a kowane gefe. Sa’an nan za su san cewa ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK28_24","027_28_24","EZK","28","24","24","“ ‘Mutanen Isra’ila ba za su ƙara kasance da mugayen maƙwabta waɗanda za su zama sarƙaƙƙiya masu zafi da ƙaya mai tsini ba. Sa’an nan za su san cewa ni ne Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK28_25","027_28_25","EZK","28","25","25","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa sa’ad da na tattara mutanen Isra’ila daga al’ummai inda suke a warwatse, zan nuna kaina mai tsarki a cikinsu a idon al’ummai. Sa’an nan za su zauna a ƙasarsu, wadda na ba wa bawana Yaƙub. ");
INSERT INTO hausa_vpl VALUES ("EK28_26","027_28_26","EZK","28","26","26","Za su zauna a can lafiya su kuma gina gidaje su nome gonakin inabi; za su zauna lafiya sa’ad da zan zartar da hukunci a kan dukan maƙwabtansu da suka wulaƙanta su. Sa’an nan za su san cewa ni ne Ubangiji Allahnsu.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK29_1","027_29_1","EZK","29","1","1","A shekara ta goma, a wata na goma, a rana ta goma sha biyu, maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK29_2","027_29_2","EZK","29","2","2","“Ɗan mutum, ka fuskanci Fir’auna sarkin Masar ka kuma yi annabci gāba da shi da dukan Masar. ");
INSERT INTO hausa_vpl VALUES ("EK29_3","027_29_3","EZK","29","3","3","Yi masa magana ka ce, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Ina gāba da kai, Fir’auna sarkin Masar, kai babban mugun dodon ruwa kwance cikin rafuffukanka. Ka ce, “Nilu nawa ne; na yi shi wa kaina.” ");
INSERT INTO hausa_vpl VALUES ("EK29_4","027_29_4","EZK","29","4","4","Amma zan sa ƙugiyoyi a muƙamuƙanka in sa kifin rafuffukanka su manne wa kamɓorinka. Zan jawo ka daga cikin tsakiyar rafuffukanka, da dukan kifayen rafuffukanka, waɗanda suka manne a ƙamborinka, ");
INSERT INTO hausa_vpl VALUES ("EK29_5","027_29_5","EZK","29","5","5","Zan bar ka a cikin hamada, kai da dukan kifin rafuffukanka. Za ka fāɗi a fili ba kuwa za a tattara ka ko a kwashe ba. Zan ba da kai kamar abinci ga namun jeji na duniya da tsuntsayen sararin sama. ");
INSERT INTO hausa_vpl VALUES ("EK29_6","027_29_6","EZK","29","6","6","Ta haka dukan waɗanda suke zama a Masar za su san cewa ni ne Ubangiji. “ ‘Ka zama sandan iwa domin gidan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK29_7","027_29_7","EZK","29","7","7","Sa’ad da suka kama ka da hannuwansu, ka tsattsage, ka kuma buɗu a kafaɗunsu; sa’ad da suka jingina a kanka, sai ka karye, bayansu kuwa ya firgita. ");
INSERT INTO hausa_vpl VALUES ("EK29_8","027_29_8","EZK","29","8","8","“ ‘Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa zan kawo takobi a kanka in kashe mutane da dabbobi. ");
INSERT INTO hausa_vpl VALUES ("EK29_9","027_29_9","EZK","29","9","9","Masar za tă zama kufai. Sa’an nan za su san cewa ni ne Ubangiji. “ ‘Domin ka ce, “Nilu nawa ne; ni na yi shi,” ");
INSERT INTO hausa_vpl VALUES ("EK29_10","027_29_10","EZK","29","10","10","saboda haka ina gāba da kai da rafuffukanka, zan kuma maishe ƙasar Masar ta lalace ta kuma zama kango daga Migdol zuwa Aswan, har iyakar Kush. ");
INSERT INTO hausa_vpl VALUES ("EK29_11","027_29_11","EZK","29","11","11","Ba ƙafar mutum ko ta dabbar da za tă ratsa ta; ba wanda zai zauna a can har shekaru arba’in. ");
INSERT INTO hausa_vpl VALUES ("EK29_12","027_29_12","EZK","29","12","12","Zan mai da ƙasar Masar kufai a cikin ƙasashen da aka ragargaza, biranenta kuma za su zama kango har shekaru arba’in a cikin biranen da aka lalace. Zan watsar da Masarawa a cikin al’ummai in warwatsa su cikin ƙasashe. ");
INSERT INTO hausa_vpl VALUES ("EK29_13","027_29_13","EZK","29","13","13","“ ‘Duk da haka ga abin da Ubangiji Mai Iko Duka yana cewa a ƙarshen shekaru arba’in ɗin zan tattara Masarawa daga al’ummai inda aka warwatsa su. ");
INSERT INTO hausa_vpl VALUES ("EK29_14","027_29_14","EZK","29","14","14","Zan komo da su daga zaman bauta in mai da su zuwa Masar ta Bisa, ƙasarsu ta ainihi. A can za su zama masarauta marar ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("EK29_15","027_29_15","EZK","29","15","15","Za tă zama masarauta mafi rarrauna cikin masarautai, ba kuwa za tă ƙara ɗaga kanta a kan sauran al’ummai ba. Zan sa tă zama marar ƙarfi ƙwarai, har da ba za tă ƙara yin mulkin a kan al’ummai ba. ");
INSERT INTO hausa_vpl VALUES ("EK29_16","027_29_16","EZK","29","16","16","Masar ba za tă ƙara zama abin dogara ga mutanen Isra’ila ba amma za tă zama abin tunin zunubinsu na juyawa gare ta don taimako. Sa’an nan za su san cewa ni ne Ubangiji Mai Iko Duka.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK29_17","027_29_17","EZK","29","17","17","A shekara ta ashirin da bakwai, a wata na fari a rana ta farko, maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK29_18","027_29_18","EZK","29","18","18","“Ɗan mutum, Nebukadnezzar sarkin Babilon ya sa sojojinsa su matsa wa Taya; kowane kai ya koɗe, kowace kafaɗa kuma ta goge. Duk da haka shi da sojojinsa ba su sami wani lada daga matsin da suka yi a kan Taya ba. ");
INSERT INTO hausa_vpl VALUES ("EK29_19","027_29_19","EZK","29","19","19","Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa zan ba da Masar ga Nebukadnezzar sarkin Babilon, zai washe dukiyarta. Zai kwashe ya washe ƙasar ganima a matsayin abin biyan sojojinsa. ");
INSERT INTO hausa_vpl VALUES ("EK29_20","027_29_20","EZK","29","20","20","Saboda haka na ba shi Masar a matsayin lada don ƙoƙarinsa domin shi da sojojinsa sun yi wannan domina ne, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK29_21","027_29_21","EZK","29","21","21","“A wannan rana zan sa ƙaho ya tsiro wa gidan Isra’ila, zan kuma buɗe bakinka a cikinsu. Sa’an nan za su san cewa ni ne Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("EK30_1","027_30_1","EZK","30","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK30_2","027_30_2","EZK","30","2","2","“Ɗan mutum, ka yi annabci ka ce, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Yi kuka kana cewa, “Kaito saboda wannan rana!” ");
INSERT INTO hausa_vpl VALUES ("EK30_3","027_30_3","EZK","30","3","3","Gama ranar ta yi kusa, ranar Ubangiji ta gabato, ranar gizagizai, lokacin hallaka wa al’ummai. ");
INSERT INTO hausa_vpl VALUES ("EK30_4","027_30_4","EZK","30","4","4","Takobi zai zo a kan Masar, azaba za tă zo a kan Kush. Sa’ad da kisassu za su fāɗi a Masar, za a kwashe dukiyarta a tafi a rushe harsashinta. ");
INSERT INTO hausa_vpl VALUES ("EK30_5","027_30_5","EZK","30","5","5","Kush da Fut, Lidiya da dukan Arabiya, Libiya da kuma mutanen ƙasar alkawari za su mutu ta wurin takobi tare da Masar. ");
INSERT INTO hausa_vpl VALUES ("EK30_6","027_30_6","EZK","30","6","6","“ ‘Ga abin da Ubangiji ya faɗa, “ ‘Waɗanda suke goyon bayan Masar za su fāɗi ƙarfinta da take fariya da shi zai ƙare. Daga Migdol zuwa Aswan za su mutu ta wurin takobi a cikinta, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK30_7","027_30_7","EZK","30","7","7","Za su zama kango a cikin ƙasashen da suke kango, biranensu kuwa za su zama kufai a cikin biranen da suka lalace. ");
INSERT INTO hausa_vpl VALUES ("EK30_8","027_30_8","EZK","30","8","8","Sa’an nan za su san cewa ni ne Ubangiji, sa’ad da suka ga na sa wuta wa Masar aka kuma ragargaza masu taimakonta. ");
INSERT INTO hausa_vpl VALUES ("EK30_9","027_30_9","EZK","30","9","9","“ ‘A wannan rana manzanni za su fito daga wurina a jiragen ruwa don su tsorata Kush daga sake jikinta. Azaba za tă kama su a ranar hallakar Masar, gama tabbatacce za tă zo. ");
INSERT INTO hausa_vpl VALUES ("EK30_10","027_30_10","EZK","30","10","10","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Zan kawo ƙarshen mutanen Masar ta hannun Nebukadnezzar sarkin Babilon. ");
INSERT INTO hausa_vpl VALUES ("EK30_11","027_30_11","EZK","30","11","11","Shi da sojojinsa, mafi bantsoro cikin al’ummai, za a kawo don su hallaka ƙasar. Za su zāre takuba a kan Masar su kuma cika ƙasar da kisassu. ");
INSERT INTO hausa_vpl VALUES ("EK30_12","027_30_12","EZK","30","12","12","Zan kafe rafuffukan Nilu in sayar da ƙasar ga mugayen mutane; ta hannun baƙi zan sa ƙasar ta lalace da kome da yake cikinta. Ni Ubangiji na faɗa. ");
INSERT INTO hausa_vpl VALUES ("EK30_13","027_30_13","EZK","30","13","13","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Zan hallaka gumaka in kuma kawo ƙarshen siffofi a Memfis. Ba za a ƙara samun yerima a ƙasar Masar ba, zan kuma baza tsoro a duk fāɗin ƙasar. ");
INSERT INTO hausa_vpl VALUES ("EK30_14","027_30_14","EZK","30","14","14","Zan lalace Masar ta Bisa in ƙuna wuta wa Zowan in zartar da hukunci a kan Tebes. ");
INSERT INTO hausa_vpl VALUES ("EK30_15","027_30_15","EZK","30","15","15","Zan kwarara hasalata a kan Felusiyum, kagarar Masar, in kuma datse mutanen Tebes. ");
INSERT INTO hausa_vpl VALUES ("EK30_16","027_30_16","EZK","30","16","16","Zan ƙuna wuta wa Masar; Felusiyum za tă sha azaba mai zafi. Za a tayar wa Tebes da hankali; Memfis za tă riƙa kasance cikin ɓacin rai. ");
INSERT INTO hausa_vpl VALUES ("EK30_17","027_30_17","EZK","30","17","17","Samarin Heliyofolis da Bubastis za su mutu ta wurin takobi, biranen kansu za su tafi bauta. ");
INSERT INTO hausa_vpl VALUES ("EK30_18","027_30_18","EZK","30","18","18","Duhu ne zai zama rana a Tafanes sa’ad da na karye ikon Masar; a can ƙarfin da take fariya zai ƙare. Za a rufe ta da gizagizai ƙauyukanta kuma za su tafi bauta. ");
INSERT INTO hausa_vpl VALUES ("EK30_19","027_30_19","EZK","30","19","19","Ta haka zan zartar da hukunci a kan Masar, za su kuwa san cewa ni ne Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK30_20","027_30_20","EZK","30","20","20","A shekara ta goma sha ɗaya, a wata na fari a rana ta goma sha bakwai, maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK30_21","027_30_21","EZK","30","21","21","“Ɗan mutum, na karye hannun Fir’auna sarkin Masar. Ba a daure shi don warkarwa ba ko a sa tsinke saboda kada yă zama da ƙarfi har ya riƙe takobi. ");
INSERT INTO hausa_vpl VALUES ("EK30_22","027_30_22","EZK","30","22","22","Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa ina gāba da Fir’auna sarkin Masar. Zan karye hannuwansa biyu, hannun da yake da kyau da kuma wanda an riga an karya, in kuma sa takobi ya fāɗi daga hannunsa. ");
INSERT INTO hausa_vpl VALUES ("EK30_23","027_30_23","EZK","30","23","23","Zan watsar da Masarawa a cikin al’ummai in warwatsa su cikin ƙasashe. ");
INSERT INTO hausa_vpl VALUES ("EK30_24","027_30_24","EZK","30","24","24","Zan ƙarfafa hannuwan sarkin Babilon in kuma sa takobina a hannunsa, amma zan karya hannuwan Fir’auna, zai kuwa yi nishi a gabansa kamar mutumin da aka yi wa raunin mutuwa. ");
INSERT INTO hausa_vpl VALUES ("EK30_25","027_30_25","EZK","30","25","25","Zan ƙarfafa hannuwan sarkin Babilon, amma hannuwan Fir’auna za su shanye. Sa’an nan za su san cewa ni ne Ubangiji, sa’ad da na sa takobi a hannun sarkin Babilon na kuma miƙa shi a kan Masar. ");
INSERT INTO hausa_vpl VALUES ("EK30_26","027_30_26","EZK","30","26","26","Zan watsar da Masarawa a cikin al’ummai in warwatsa su cikin ƙasashe. Sa’an nan za su san cewa ni ne Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("EK31_1","027_31_1","EZK","31","1","1","A shekara ta goma sha ɗaya, a wata na uku a rana ta farko, maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK31_2","027_31_2","EZK","31","2","2","“Ɗan mutum, faɗa wa Fir’auna sarkin Masar da jama’arsa cewa, “ ‘Da wa za a kwatanta girmanka? ");
INSERT INTO hausa_vpl VALUES ("EK31_3","027_31_3","EZK","31","3","3","Ka dubi Assuriya, ta taɓa zama kamar al’ul a Lebanon da rassa masu kyau suna inuwartar da kurmi; ya yi tsayi ainun kansa ya kai cikin gizagizai. ");
INSERT INTO hausa_vpl VALUES ("EK31_4","027_31_4","EZK","31","4","4","Ruwa ya sa ya yi girma, zurfafan maɓulɓulai sun sa ya yi tsayi; rafuffuka suna gudu kewaye da tushensa yana aika da rafuffukansa zuwa dukan itatuwan kurmi. ");
INSERT INTO hausa_vpl VALUES ("EK31_5","027_31_5","EZK","31","5","5","Saboda haka ya yi tsayi fiye da sauran itatuwan kurmi; rassansa suka ƙaru suka yi tsayi, suka bazu saboda yalwar ruwaye. ");
INSERT INTO hausa_vpl VALUES ("EK31_6","027_31_6","EZK","31","6","6","Dukan tsuntsayen sararin sama suka yi sheƙa a rassansa, dukan namun jeji suka haihu a ƙarƙashin rassansa; dukan al’ummai suka zauna a inuwarsa. ");
INSERT INTO hausa_vpl VALUES ("EK31_7","027_31_7","EZK","31","7","7","Yana da girma a kyau, da dogayen rassansa da ya baza, gama saiwoyinsa sun nutse can ƙasa har cikin yalwar ruwaye. ");
INSERT INTO hausa_vpl VALUES ("EK31_8","027_31_8","EZK","31","8","8","Al’ul a cikin lambun Allah ba su kai shi ba, balle itatuwan kasharina su kai rassansa, ko itatuwan durumi su kai rassansa, ko itace a lambun Allah ya kai kyansa. ");
INSERT INTO hausa_vpl VALUES ("EK31_9","027_31_9","EZK","31","9","9","Na sa ya yi kyau da yalwar rassa, abin ƙyashi na dukan itatuwan Eden a lambun Allah. ");
INSERT INTO hausa_vpl VALUES ("EK31_10","027_31_10","EZK","31","10","10","“ ‘Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa domin ya yi tsayi, kansa kuma ya kai cikin gizagizai, kuma domin ya yi fariya saboda tsayinsa, ");
INSERT INTO hausa_vpl VALUES ("EK31_11","027_31_11","EZK","31","11","11","na miƙa shi ga mai mulkin al’ummai, don yă sāka masa gwargwadon muguntarsa. Na jefar da shi a gefe, ");
INSERT INTO hausa_vpl VALUES ("EK31_12","027_31_12","EZK","31","12","12","kuma baƙi mafi mugunta na al’ummai suka sare shi suka bar shi. Rassansa sun fāɗi a kan duwatsun da suke cikin dukan kwaruruka; rassansa kuma sun kakkarye, sun fāɗi a cikin dukan magudanan ruwa na ƙasa. Dukan al’umman duniya suka fito daga ƙarƙashin inuwarsa suka bar shi. ");
INSERT INTO hausa_vpl VALUES ("EK31_13","027_31_13","EZK","31","13","13","Dukan tsuntsaye sararin sama suka zauna a itacen da ya fāɗi, dukan namun jeji kuma suna cikin rassansa. ");
INSERT INTO hausa_vpl VALUES ("EK31_14","027_31_14","EZK","31","14","14","Saboda haka ba wani daga cikin itatuwan da suke kusa da ruwan da zai taɓa yin fariyar tsawonsa, har kawunansu su kai cikin gizagizai. Ba wani daga cikin itatuwan da ya sha ruwa sosai da zai taɓa yi wannan tsayi; duk an bashe su ga mutuwa, zuwa can ƙasa, a cikin matattu, tare da waɗanda suka gangara zuwa rami. ");
INSERT INTO hausa_vpl VALUES ("EK31_15","027_31_15","EZK","31","15","15","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa a ranar da aka yi ƙasa da shi zuwa kabari na rufe zurfafa maɓulɓulai da makoki dominsa; na janye rafuffukansa, aka kuma hana yalwan ruwansa. Saboda shi na rufe Lebanon da baƙin ciki, dukan itatuwan kurmi suka bushe. ");
INSERT INTO hausa_vpl VALUES ("EK31_16","027_31_16","EZK","31","16","16","Na sa al’ummai suka yi rawar jiki da jin ƙarar fāɗuwarsa sa’ad da na yi ƙasa da shi zuwa kabari tare da waɗanda suka gangara rami. Sai dukan itatuwan Eden, zaɓaɓɓu da kuma mafi kyau na Lebanon, dukan itatuwan da aka yi musu banruwa, sun ta’azantu a ƙarƙashin ƙasa. ");
INSERT INTO hausa_vpl VALUES ("EK31_17","027_31_17","EZK","31","17","17","Waɗanda suka zauna a inuwarsa, dukan masu tarayyarsa a cikin al’ummai, su ma sun gangara zuwa kabari tare da shi, sun haɗu da waɗanda aka kashe da takobi. ");
INSERT INTO hausa_vpl VALUES ("EK31_18","027_31_18","EZK","31","18","18","“ ‘Da wa cikin itatuwan Eden za a kwatanta da kai cikin girma da daraja? Duk da haka kai ma, za a yi ƙasa da kai tare da itatuwan Eden zuwa ƙarƙashin ƙasa; za ka kwanta a cikin marasa kaciya, tare da waɗanda aka kashe da takobi. “ ‘Fir’auna ke nan da dukan jama’arsa, in ji Ubangiji Mai Iko Duka.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK32_1","027_32_1","EZK","32","1","1","A shekara ta goma sha biyu, a wata na goma sha biyu a rana ta fari, maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK32_2","027_32_2","EZK","32","2","2","“Ɗan mutum, ka yi makoki a kan Fir’auna sarkin Masar ka faɗa masa. “ ‘Kai kamar zaki ne a cikin al’ummai; kai kamar dodon ruwa a cikin tekuna kana ɓullowa cikin rafuffukanka, kana gurɓata ruwa da ƙafafunka kana kuma dama rafuffuka. ");
INSERT INTO hausa_vpl VALUES ("EK32_3","027_32_3","EZK","32","3","3","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Da taron jama’a masu yawa zan jefa abin kamun kifi a kanka, za su kuwa jawo ka da abin kamun kifi. ");
INSERT INTO hausa_vpl VALUES ("EK32_4","027_32_4","EZK","32","4","4","Zan jefar da kai a ƙasa zan jefa ka a fili. Zan sa dukan tsuntsayen sararin sama su zauna a kanka dukan namun jeji na duniya kuma za su ƙosar da kansu a kanka. ");
INSERT INTO hausa_vpl VALUES ("EK32_5","027_32_5","EZK","32","5","5","Zan baza namanka a kan duwatsu in kuma cika kwaruruka da gawarka. ");
INSERT INTO hausa_vpl VALUES ("EK32_6","027_32_6","EZK","32","6","6","Zan jiƙa ƙasar da jininka mai gudu har zuwa duwatsu, magudanan ruwa za su cika da namanka. ");
INSERT INTO hausa_vpl VALUES ("EK32_7","027_32_7","EZK","32","7","7","Sa’ad da na shafe ka, zan rufe sammai in duhunta taurarinsu; zan rufe rana da girgije, wata kuwa ba zai ba da haskensa ba. ");
INSERT INTO hausa_vpl VALUES ("EK32_8","027_32_8","EZK","32","8","8","Dukan haskokin sammai za su zama duhu a kanka; zan kawo duhu a kan ƙasarka, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK32_9","027_32_9","EZK","32","9","9","Zan dami zukatan mutane masu yawa sa’ad da na kawo maka hallaka a cikin al’ummai, a cikin ƙasashen da ba ka taɓa sani ba. ");
INSERT INTO hausa_vpl VALUES ("EK32_10","027_32_10","EZK","32","10","10","Zan sa mutane da yawa su giggice saboda abin da ya same ka, sarakunansu kuma za su yi rawar jiki saboda kai sa’ad da na kaɗa takobina a gabansu. A ranar fāɗuwarka kowannensu zai yi rawar jiki a kowane lokaci saboda ransa. ");
INSERT INTO hausa_vpl VALUES ("EK32_11","027_32_11","EZK","32","11","11","“ ‘Gama ga abin da Ubangiji Mai Iko Duka yana cewa, “ ‘Takobin sarkin Babilon zai auko maka. ");
INSERT INTO hausa_vpl VALUES ("EK32_12","027_32_12","EZK","32","12","12","Zan sa jama’arka su mutu ta wurin takuban ƙarfafan mutane, masu bantsoro na dukan al’ummai. Za su lalatar da girman kan Masar, su kuma tumɓuke dukan jama’arta. ");
INSERT INTO hausa_vpl VALUES ("EK32_13","027_32_13","EZK","32","13","13","Zan hallaka dukan dabbobinta da suke kusa da ruwaye masu yawa ƙafar mutum ba zai ƙara damunsa ko kofaton dabba ya gurɓata shi. ");
INSERT INTO hausa_vpl VALUES ("EK32_14","027_32_14","EZK","32","14","14","Sa’an nan zan sa ruwanta su kwanta in sa rafuffukanta su gudu kamar mai, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK32_15","027_32_15","EZK","32","15","15","Sa’ad da na mai da Masar kufai na kuma raba ƙasar da abin da take cike da shi, sa’ad da na bugi dukan waɗanda suke cikinta, a sa’an nan ne za su san cewa ni ne Ubangiji.’ ");
INSERT INTO hausa_vpl VALUES ("EK32_16","027_32_16","EZK","32","16","16","“Wannan ne makokin da za a yi mata. ’Yan matan al’ummai za su rera shi; gama Masar da dukan jama’arta za su rera shi, in ji Ubangiji Mai Iko Duka.” ");
INSERT INTO hausa_vpl VALUES ("EK32_17","027_32_17","EZK","32","17","17","A shekara ta goma sha biyu, a rana ta goma sha biyar ga wata, maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK32_18","027_32_18","EZK","32","18","18","“Ɗan mutum, yi kuka saboda jama’ar Masar ka kuma tura ta da ’yan matan manyan al’ummai zuwa ƙarƙashin ƙasa, tare da waɗanda suka gangara zuwa rami. ");
INSERT INTO hausa_vpl VALUES ("EK32_19","027_32_19","EZK","32","19","19","Ka ce, ‘Kin fi sauran tagomashi ne? Ki gangara, ki kwanta cikin marasa kaciya.’ ");
INSERT INTO hausa_vpl VALUES ("EK32_20","027_32_20","EZK","32","20","20","Za su fāɗi cikin waɗanda aka kashe da takobi. Takobin da an zāre; bari a ja ta a tafi tare da dukan jama’arta. ");
INSERT INTO hausa_vpl VALUES ("EK32_21","027_32_21","EZK","32","21","21","Daga cikin kabari manyan shugabanni za su yi maganar Masar da abokanta su ce, ‘Sun gangara sun kuma kwanta da marasa kaciya, tare da waɗanda aka kashe da takobi.’ ");
INSERT INTO hausa_vpl VALUES ("EK32_22","027_32_22","EZK","32","22","22","“Assuriya tana can tare da dukan sojojinta; an kewaye ta da kaburburan dukan waɗanda aka kashe, dukan waɗanda suka mutu ta wurin takobi. ");
INSERT INTO hausa_vpl VALUES ("EK32_23","027_32_23","EZK","32","23","23","Kaburburansu suna cikin zurfafan rami kuma sojojinta suna kwance kewaye da kabarinta. Dukan waɗanda suka haddasa tsoro a ƙasar masu rai sun mutu, an kashe su da takobi. ");
INSERT INTO hausa_vpl VALUES ("EK32_24","027_32_24","EZK","32","24","24","“Elam tana can, tare da dukan jama’arta kewaye da kabarinta. Dukansu sun mutu, an kashe su da takobi. Dukan waɗanda suka haddasa tsoro a ƙasar masu rai sun gangara wurin marasa kaciya a duniyar da take ƙarƙashi. Suna shan kunya tare da waɗanda suka gangara zuwa rami. ");
INSERT INTO hausa_vpl VALUES ("EK32_25","027_32_25","EZK","32","25","25","An yi mata gado a cikin matattu, tare da dukan jama’arta kewaye da kabarinta. Dukansu marasa kaciya ne, da aka kashe da takobi. Domin tsoronsu ya bazu cikin ƙasar masu rai, suna shan kunya tare da waɗanda suka gangara zuwa rami; an kwantar da su tare da waɗanda aka kashe. ");
INSERT INTO hausa_vpl VALUES ("EK32_26","027_32_26","EZK","32","26","26","“Meshek da Tubal suna can, tare da dukan jama’arsu kewaye da kaburburansu. Dukansu marasa kaciya ne, da aka kashe da takobi domin sun haddasa tsoronsu a ƙasar masu rai. ");
INSERT INTO hausa_vpl VALUES ("EK32_27","027_32_27","EZK","32","27","27","Ba sun kwanta tare da sauran jarumawa marasa kaciyan da aka kashe, waɗanda suka gangara kabari tare da makaman yaƙinsu, waɗanda aka yi musu matashin kai da takubansu ba? Hukuncin zunubansu yana a bisa ƙasusuwansu, ko da yake tsoron waɗannan jarumawa ya manne cikin ƙasar masu rai. ");
INSERT INTO hausa_vpl VALUES ("EK32_28","027_32_28","EZK","32","28","28","“Kai kuma, ya Fir’auna, za a kakkarye ka za ka kuma kwanta a cikin marasa kaciya, tare da waɗanda aka kashe da takobi. ");
INSERT INTO hausa_vpl VALUES ("EK32_29","027_32_29","EZK","32","29","29","“Edom tana can, sarakunanta da dukan yerimanta; duk da ikonsu, sun kwanta tare da waɗanda aka kashe da takobi. Suna kwance tare da marasa kaciya, tare da waɗanda suka gangara zuwa rami. ");
INSERT INTO hausa_vpl VALUES ("EK32_30","027_32_30","EZK","32","30","30","“Dukan yerima arewa da dukan Sidoniyawa suna can; sun gangara tare da waɗanda aka kashe cikin kunya duk da tsoron da suka haddasa ta wurin ikonsu. Sun kwanta tare da marasa kaciya tare da waɗanda aka kashe da takobi suna kuma shan kunya tare da waɗanda suka gangara zuwa rami. ");
INSERT INTO hausa_vpl VALUES ("EK32_31","027_32_31","EZK","32","31","31","“Fir’auna, shi da dukan sojojinsa, za su gan su zai kuma ta’azantu domin dukan jama’arsa da aka kashe da takobi, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK32_32","027_32_32","EZK","32","32","32","Ko da yake na sa ta haddasa tsoro a ƙasar masu rai, Fir’auna da dukan jama’arsa za su kwanta a cikin marasa kaciya, tare da waɗanda aka kashe da takobi, in ji Ubangiji Mai Iko Duka.” ");
INSERT INTO hausa_vpl VALUES ("EK33_1","027_33_1","EZK","33","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK33_2","027_33_2","EZK","33","2","2","“Ɗan mutum, yi magana da mutanen ƙasarka ka faɗa musu cewa, ‘Sa’ad da na kawo takobi a kan ƙasar, mutanen ƙasar kuwa suka zaɓi ɗaya daga cikin mutanensu suka mai da shi mai tsaro, ");
INSERT INTO hausa_vpl VALUES ("EK33_3","027_33_3","EZK","33","3","3","ya kuma ga takobi yana zuwa a kan ƙasar ya kuwa busa ƙaho don yă faɗakar da mutane, ");
INSERT INTO hausa_vpl VALUES ("EK33_4","027_33_4","EZK","33","4","4","in wani ya ji busar amma bai kula ba, takobin zai zo ya ɗauki ransa, jininsa kuwa zai zauna a kansa. ");
INSERT INTO hausa_vpl VALUES ("EK33_5","027_33_5","EZK","33","5","5","Da yake ya ji ƙarar busar amma bai kula ba, jininsa zai zauna a kansa. Da a ce ya kula, da ya ceci kansa. ");
INSERT INTO hausa_vpl VALUES ("EK33_6","027_33_6","EZK","33","6","6","Amma a ce mai tsaron ya ga takobi yana zuwa bai kuwa busa ƙaho don yă faɗakar da mutane ba sai takobi ya zo ya ɗauki ran waninsu, za a kawar da wannan mutum saboda zunubinsa, amma zan nemi hakkin jinin mutumin a kan mai tsaron.’ ");
INSERT INTO hausa_vpl VALUES ("EK33_7","027_33_7","EZK","33","7","7","“Ɗan mutum, na mai da kai mai tsaro bisa gidan Isra’ila; saboda haka ka ji abin da zan faɗa ka kuma gargaɗe su. ");
INSERT INTO hausa_vpl VALUES ("EK33_8","027_33_8","EZK","33","8","8","Sa’ad da na ce wa mugu, ‘Ya mugun mutum, tabbatacce za ka mutu,’ kai kuma ba ka yi magana don ka juyar da shi daga hanyoyinsa ba, wannan mugun mutum zai mutu domin zunubinsa, zan kuma nemi hakkin jininsa a kanka. ");
INSERT INTO hausa_vpl VALUES ("EK33_9","027_33_9","EZK","33","9","9","Amma in ka faɗakar da mugun mutumin don yă juye daga hanyoyinsa bai kuwa yi haka ba, zai mutu saboda zunubinsa, amma kai za ka kuɓutar da kanka. ");
INSERT INTO hausa_vpl VALUES ("EK33_10","027_33_10","EZK","33","10","10","“Ɗan mutum, faɗa wa gidan Isra’ila, ‘Ga abin da kuke cewa, “Laifofinmu da zunubanmu suna nawaita mana, muna kuma lalacewa saboda su. Ta ƙaƙa za mu rayu?” ’ ");
INSERT INTO hausa_vpl VALUES ("EK33_11","027_33_11","EZK","33","11","11","Ka faɗa musu, ‘Muddin ina raye, in ji Ubangiji Mai Iko Duka, ba na jin daɗin mutuwar mugu, amma a maimako haka ya fi su juye daga hanyoyinsu su rayu. Ku juye! Ku juye daga mugayen hanyoyinku! Don me za ku mutu, ya gidan Isra’ila?’ ");
INSERT INTO hausa_vpl VALUES ("EK33_12","027_33_12","EZK","33","12","12","“Saboda haka, ɗan mutum, ka faɗa wa mutanen ƙasarka, ‘Adalcin adali ba zai cece shi sa’ad da ya ƙi yin biyayya ba, kuma muguntar mugu ba za tă sa ya fāɗi sa’ad da ya juya daga gare ta ba. Adali, in ya yi zunubi, ba za a bari yă rayu saboda adalcinsa na dā ba.’ ");
INSERT INTO hausa_vpl VALUES ("EK33_13","027_33_13","EZK","33","13","13","In na faɗa wa adali cewa tabbatacce zai rayu, amma sai ya dogara ga adalcinsa ya kuma aikata mugunta, babu ayyukan adalcinsa da za a tuna; zai mutu saboda muguntar da ya aikata. ");
INSERT INTO hausa_vpl VALUES ("EK33_14","027_33_14","EZK","33","14","14","Kuma in na ce wa mugu, ‘Tabbatacce za ka mutu,’ amma sai ya juye daga zunubinsa ya kuma yi abin da yake gaskiya da kuma daidai, ");
INSERT INTO hausa_vpl VALUES ("EK33_15","027_33_15","EZK","33","15","15","in ya mayar da jingina, ya mayar da abin da ya sata, ya kiyaye ƙa’idodin da suke ba da rai, ya daina yin mugunta, tabbatacce zai rayu; ba zai mutu ba. ");
INSERT INTO hausa_vpl VALUES ("EK33_16","027_33_16","EZK","33","16","16","Babu wani zunubin da ya aikata da za a tuna da shi. Ya yi abin da yake gaskiya da kuma daidai; tabbatacce zai rayu. ");
INSERT INTO hausa_vpl VALUES ("EK33_17","027_33_17","EZK","33","17","17","“Duk da haka mutanen ƙasarka sun ce, ‘Hanyar Ubangiji ba daidai ba ce.’ Alhali kuwa tasu ce ba daidai ba. ");
INSERT INTO hausa_vpl VALUES ("EK33_18","027_33_18","EZK","33","18","18","In adali ya juye daga adalcinsa ya yi mugunta, zai mutu saboda haka. ");
INSERT INTO hausa_vpl VALUES ("EK33_19","027_33_19","EZK","33","19","19","Kuma in mugu ya juye daga muguntarsa ya aikata abin da yake gaskiya da kuma daidai, zai rayu ta yin haka. ");
INSERT INTO hausa_vpl VALUES ("EK33_20","027_33_20","EZK","33","20","20","Duk da haka, ya gidan Isra’ila kun ce, ‘Hanyar Ubangiji ba daidai ba ce.’ Amma zan hukunta kowane ɗayanku gwargwadon ayyukansa.” ");
INSERT INTO hausa_vpl VALUES ("EK33_21","027_33_21","EZK","33","21","21","A shekara ta goma sha biyu ta zaman bautanmu, a wata na goma a rana ta biyar, wani mutumin da ya gudu daga Urushalima ya zo wurina ya ce, “Birnin ya fāɗi!” ");
INSERT INTO hausa_vpl VALUES ("EK33_22","027_33_22","EZK","33","22","22","To a yamman da ya wuce kafin mutumin ya iso, hannun Ubangiji yana a kaina, ya kuma buɗe bakina kafin mutumin ya iso wurina da safe. Sai bakina ya buɗu ban kuma yi shiru ba. ");
INSERT INTO hausa_vpl VALUES ("EK33_23","027_33_23","EZK","33","23","23","Sai maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK33_24","027_33_24","EZK","33","24","24","“Ɗan mutum, mutanen da suke zama a waɗannan kufai a ƙasar Isra’ila suna cewa, ‘Ibrahim mutum ɗaya ne kaɗai, duk da haka Ibrahim ya mallaki ƙasar. Amma mu da muke da yawa; lalle an ba mu ƙasar ta zama mallakarmu.’ ");
INSERT INTO hausa_vpl VALUES ("EK33_25","027_33_25","EZK","33","25","25","Saboda haka ka faɗa musu, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa da yake kun ci nama da jini a cikinsa kuka kuma bauta wa gumakanku kuka zub da jini, kuna gani za ku mallaki ƙasar? ");
INSERT INTO hausa_vpl VALUES ("EK33_26","027_33_26","EZK","33","26","26","Kun dogara ga takobinku, kuka aikata abubuwan banƙyama, kowannenku kuma ya ƙazantar da matar maƙwabcinsa. Kuna gani za ku mallaki ƙasar?’ ");
INSERT INTO hausa_vpl VALUES ("EK33_27","027_33_27","EZK","33","27","27","“Ka faɗa musu wannan, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa muddin ina raye, waɗanda aka rage a kufai za su fāɗi ga takobi, waɗanda suke bayan gari kuwa namun jeji za su cinye su, waɗanda suke a mafaka da kogwannin duwatsu annoba za tă kashe su. ");
INSERT INTO hausa_vpl VALUES ("EK33_28","027_33_28","EZK","33","28","28","Zan mai da ƙasar kango, kuma fariyar ƙarfinta zai ƙare, duwatsun Isra’ila za su zama kufai don kada wani ya ratsa su. ");
INSERT INTO hausa_vpl VALUES ("EK33_29","027_33_29","EZK","33","29","29","Sa’an nan za su san cewa ni ne Ubangiji, sa’ad da na mai da ƙasar kango saboda dukan abubuwan banƙyamar da suka yi.’ ");
INSERT INTO hausa_vpl VALUES ("EK33_30","027_33_30","EZK","33","30","30","“Game da kai kuma, ɗan mutum, mutanen ƙasarka suna magana da juna game da kai a katanga da kuma ƙofofin gidaje, suna ce wa juna, ‘Ku zo mu tafi mu ji maganar da ta zo daga wurin Ubangiji.’ ");
INSERT INTO hausa_vpl VALUES ("EK33_31","027_33_31","EZK","33","31","31","Mutanena sukan zo wurinka, yadda suka saba su zauna a gabanka don su saurari maganarka, amma ba sa aiki da abin da suka ji. Da bakunansu suna nuna ƙauna, amma zukatansu cike da haɗama suke don ƙazamar riba. ");
INSERT INTO hausa_vpl VALUES ("EK33_32","027_33_32","EZK","33","32","32","Tabbatacce, gare su ba ka fi mai waƙar ƙauna da murya mai daɗi kana kuma yin kiɗa sosai ba, gama sukan ji maganarka amma ba sa amfani da ita. ");
INSERT INTO hausa_vpl VALUES ("EK33_33","027_33_33","EZK","33","33","33","“Sa’ad da dukan wannan ya cika kuma zai cika ɗin, sa’an nan za su sani akwai annabi a tsakiyarsu.” ");
INSERT INTO hausa_vpl VALUES ("EK34_1","027_34_1","EZK","34","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK34_2","027_34_2","EZK","34","2","2","“Ɗan mutum, ka yi annabci a kan makiyayan Isra’ila; ka yi annabci ka ce musu, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa kaiton makiyayan Isra’ila waɗanda suke kula da kansu ne kawai! Ashe, bai kamata makiyaya ne su lura da tumaki ba? ");
INSERT INTO hausa_vpl VALUES ("EK34_3","027_34_3","EZK","34","3","3","Kuna cin kitsensu, kuna yi wa kanku tufafi da gashinsu, kukan yanka turkakkun, amma ba ku yi kiwon tumakin ba. ");
INSERT INTO hausa_vpl VALUES ("EK34_4","027_34_4","EZK","34","4","4","Ba ku ƙarfafa marasa ƙarfi ba, ko ku warkar da marasa lafiya ko ku ɗaura waɗanda suka ji rauni. Ba ku dawo da waɗanda suka yi makuwa ko ku nemi waɗanda suka ɓace ba. Amma sai kuka mallake su ƙarfi da yaji. ");
INSERT INTO hausa_vpl VALUES ("EK34_5","027_34_5","EZK","34","5","5","Saboda haka suka warwatse domin babu makiyayi, kuma da suka warwatsu sai suka zama abincin namun jeji. ");
INSERT INTO hausa_vpl VALUES ("EK34_6","027_34_6","EZK","34","6","6","Tumakina suna ta yawo a kan dukan duwatsu da kuma kowane tudu. Sun watsu a dukan duniya, kuma ba wanda ya neme su. ");
INSERT INTO hausa_vpl VALUES ("EK34_7","027_34_7","EZK","34","7","7","“ ‘Saboda haka, ku makiyaya, ku ji maganar Ubangiji, ");
INSERT INTO hausa_vpl VALUES ("EK34_8","027_34_8","EZK","34","8","8","Muddin ina raye, in ji Ubangiji Mai Iko Duka, domin tumaki sun rasa makiyayi ta haka aka washe su suka kuma zama abincin dukan namun jeji, kuma domin makiyayana ba su nemi tumakina ba amma suka kula da kansu a maimakon tumakina, ");
INSERT INTO hausa_vpl VALUES ("EK34_9","027_34_9","EZK","34","9","9","saboda haka, ya ku makiyaya, ku ji maganar Ubangiji, ");
INSERT INTO hausa_vpl VALUES ("EK34_10","027_34_10","EZK","34","10","10","Ga abin da Ubangiji Mai Iko Duka yana cewa ina gāba da makiyaya kuma zan nemi hakkin tumakina daga gare su. Zan hana su yin kiwon tumakin don kada makiyayan su ƙara yin kiwon kansu. Zan ƙwace tumakina daga bakunansu, ba kuwa za su ƙara zama abincinsu. ");
INSERT INTO hausa_vpl VALUES ("EK34_11","027_34_11","EZK","34","11","11","“ ‘Gama ga abin da Ubangiji Mai Iko Duka yana cewa ni kaina zan nemi tumakina. ");
INSERT INTO hausa_vpl VALUES ("EK34_12","027_34_12","EZK","34","12","12","Kamar yadda makiyayi yakan lura da tumakinsa da suka watse sa’ad da yake tare da su, haka zan lura da tumakina. Zan cece su daga dukan wuraren da aka watsar da su a ranar gizagizai da baƙin duhu. ");
INSERT INTO hausa_vpl VALUES ("EK34_13","027_34_13","EZK","34","13","13","Zan dawo da su daga al’ummai in kuma tattara su daga ƙasashe, zan kuma kawo su cikin ƙasarsu. Zan yi kiwonsu a kan duwatsun Isra’ila, a maɓulɓulai da kuma cikin wuraren zamansu a ƙasar. ");
INSERT INTO hausa_vpl VALUES ("EK34_14","027_34_14","EZK","34","14","14","Zan kula da su a wurin kiwo mai kyau, kuma ƙwanƙolin duwatsun Isra’ila ne zai zama wurin kiwonsu. Za su kwanta a wurin kiwo mai kyau, a can kuma za su yi kiwo a wurin kiwo mai kyau a kan duwatsun Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK34_15","027_34_15","EZK","34","15","15","Ni kaina zan lura da tumakina in kuma sa su kwanta, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK34_16","027_34_16","EZK","34","16","16","Zan nemi ɓatattuna in kuma dawo da waɗanda suka yi makuwa. Zan ɗaura raunin waɗanda suka ji ciwo in kuma ƙarfafa marasa ƙarfi, amma zan hallaka ƙarfafa da kuma masu ƙiba. Zan yi kiwo tumaki da adalci. ");
INSERT INTO hausa_vpl VALUES ("EK34_17","027_34_17","EZK","34","17","17","“ ‘Game da ku, tumakina, ga abin da Ubangiji Mai Iko Duka yana cewa zan hukunta tsakanin tunkiya da tunkiya, da tsakanin raguna da awaki. ");
INSERT INTO hausa_vpl VALUES ("EK34_18","027_34_18","EZK","34","18","18","Bai isa ba a ce kun yi kiwo a wuri mai kyau? Sai kun tattake sauran wurin kiwonku da ƙafafunku tukuna? Bai isa ba a ce kun sha ruwa mai tsabta? Sai kun kuma gurɓata sauran da ƙafafunku? ");
INSERT INTO hausa_vpl VALUES ("EK34_19","027_34_19","EZK","34","19","19","Dole ne tumakina su ci abin da kuka tattake su kuma sha abin da kuka gurɓata da ƙafafunku? ");
INSERT INTO hausa_vpl VALUES ("EK34_20","027_34_20","EZK","34","20","20","“ ‘Saboda haka ga abin da Ubangiji Mai Iko Duka ya ce musu, duba, ni kaina zan hukunta tsakanin turkakkun tumaki da ramammun tumaki. ");
INSERT INTO hausa_vpl VALUES ("EK34_21","027_34_21","EZK","34","21","21","Domin kun tunkuɗe marasa ƙarfi da kafaɗunku, kun kuma tunkuye su da ƙahoninku sai da suka gudu, ");
INSERT INTO hausa_vpl VALUES ("EK34_22","027_34_22","EZK","34","22","22","zan cece tumakina ba za su ƙara zama ganima ba. Zan hukunta tsakanin tunkiya da tunkiya. ");
INSERT INTO hausa_vpl VALUES ("EK34_23","027_34_23","EZK","34","23","23","Zan sa musu makiyaya guda, bawana Dawuda, zai kuwa lura da su; zai kula da su ya kuma zama makiyayinsu. ");
INSERT INTO hausa_vpl VALUES ("EK34_24","027_34_24","EZK","34","24","24","Ni Ubangiji zan zama Allahnsu, bawana kuma Dawuda zai zama yerima a cikinsu. Ni Ubangiji na faɗa. ");
INSERT INTO hausa_vpl VALUES ("EK34_25","027_34_25","EZK","34","25","25","“ ‘Zan yi alkawarin salama da su in kuma kawar wa ƙasar da namun jeji domin su zauna a hamada su kuma kwana a kurmi lafiya lau. ");
INSERT INTO hausa_vpl VALUES ("EK34_26","027_34_26","EZK","34","26","26","Zan albarkace su in kuma sa tuduna kewaye da su. Zan zubo yayyafi a lokacinsa; za a kasance da yayyafin albarka. ");
INSERT INTO hausa_vpl VALUES ("EK34_27","027_34_27","EZK","34","27","27","Itatuwan gona za su ba da ’ya’yansu, ƙasa kuma za tă ba da amfaninta; mutane za su zauna lafiya a ƙasarsu. Za su san cewa ni ne Ubangiji, sa’ad da na karya karkiyarsu, na cece su daga hannun waɗanda suka bautar da su. ");
INSERT INTO hausa_vpl VALUES ("EK34_28","027_34_28","EZK","34","28","28","Ba za su ƙara zama ganimar al’ummai ba, ba kuwa namun jeji za su cinye su ba. Za su zauna lafiya, kuma babu wani da zai sa su ji tsoro. ");
INSERT INTO hausa_vpl VALUES ("EK34_29","027_34_29","EZK","34","29","29","Zan tanada musu ƙasar da aka sani don hatsinta, ba za su kuma ƙara zama abin da yunwa za tă fara musu a ƙasa ba ko su sha zargin sauran al’ummai. ");
INSERT INTO hausa_vpl VALUES ("EK34_30","027_34_30","EZK","34","30","30","Sa’an nan za su san cewa ni, Ubangiji Allahnsu, ina tare da su kuma cewa su, gidan Isra’ila, mutanena ne, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK34_31","027_34_31","EZK","34","31","31","Ku tumakina, tumakin wurin kiwona, mutanena ne, ni kuwa Allahnku ne, in ji Ubangiji Mai Iko Duka.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK35_1","027_35_1","EZK","35","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK35_2","027_35_2","EZK","35","2","2","“Ɗan mutum, ka fuskanci Dutsen Seyir; ka yi annabci a kansa ");
INSERT INTO hausa_vpl VALUES ("EK35_3","027_35_3","EZK","35","3","3","ka ce, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa ina gāba da kai, Dutsen Seyir, zan kuma miƙa hannuna gāba da kai in mai da kai kango. ");
INSERT INTO hausa_vpl VALUES ("EK35_4","027_35_4","EZK","35","4","4","Zan mai da garuruwanka kufai za ka kuma zama kango. Sa’an nan za ka san cewa ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK35_5","027_35_5","EZK","35","5","5","“ ‘Domin ka riƙe ƙiyayya ta tun dā, ka kuma ba da mutanen Isra’ila domin a kashe su da takobi a lokacin masifarsu, lokacin da adadin horonsu ya cika, ");
INSERT INTO hausa_vpl VALUES ("EK35_6","027_35_6","EZK","35","6","6","saboda haka muddin ina raye, in ji Ubangiji Mai Iko Duka, zan sa a zub da jininka zan kuwa fafare ka. Da yake ba ka ƙi zub da jini ba, zub da jini zai fafare ka. ");
INSERT INTO hausa_vpl VALUES ("EK35_7","027_35_7","EZK","35","7","7","Zan mai da Dutsen Seyir kango in kuma yanke dukan waɗanda suke shiga da fita a cikinka. ");
INSERT INTO hausa_vpl VALUES ("EK35_8","027_35_8","EZK","35","8","8","Zan cika duwatsunka da matattu; waɗanda aka kashe da takobi za su fāɗi a kan tuddanka, da cikin kwarurukanka, da cikin dukan kwazazzabanka. ");
INSERT INTO hausa_vpl VALUES ("EK35_9","027_35_9","EZK","35","9","9","Zan mai da kai kango har abada; ba za a zauna a cikin garuruwanka ba. Sa’an nan za ka san cewa ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK35_10","027_35_10","EZK","35","10","10","“ ‘Domin kun ce, “Waɗannan al’ummai biyu da ƙasashe za su zama namu za mu kuma mallake su,” ko da yake Ni Ubangiji ina a can, ");
INSERT INTO hausa_vpl VALUES ("EK35_11","027_35_11","EZK","35","11","11","saboda haka muddin ina raye, in ji Ubangiji Mai Iko Duka, zan sāka maka gwargwadon fushi da kuma kishin da ka nuna a ƙiyayyarsu da ka yi zan kuma sanar da kaina a cikinsu sa’ad da na hukunta ka. ");
INSERT INTO hausa_vpl VALUES ("EK35_12","027_35_12","EZK","35","12","12","Sa’an nan za ka san cewa Ni Ubangiji na ji duk abubuwan banzan da ka faɗa a kan duwatsun Isra’ila. Ka ce, “An mai da su kango an kuma ba mu su mu cinye.” ");
INSERT INTO hausa_vpl VALUES ("EK35_13","027_35_13","EZK","35","13","13","Ka yi fariya a kaina, ka kuma yi magana a kaina ba gaggautawa, na ji shi sarai. ");
INSERT INTO hausa_vpl VALUES ("EK35_14","027_35_14","EZK","35","14","14","Ga abin da Ubangiji Mai Iko Duka yana cewa yayinda dukan duniya take farin ciki, zan mai da kai kango. ");
INSERT INTO hausa_vpl VALUES ("EK35_15","027_35_15","EZK","35","15","15","Domin ka yi farin ciki sa’ad da gādon gidan Isra’ila ya zama kufai, haka zan yi da kai, ya Dutsen Seyir, kai da dukan Edom. Sa’an nan za ka san cewa ni ne Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK36_1","027_36_1","EZK","36","1","1","“Ɗan mutum, ka yi annabci wa duwatsun Isra’ila ka ce, ‘Ya duwatsun Isra’ila, ku ji maganar Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK36_2","027_36_2","EZK","36","2","2","Ga abin da Ubangiji Mai Iko Duka yana cewa abokin gāba yana magana game da ku cewa, “Yauwa! Tsofaffin tuddai sun zama mallakarmu yanzu.” ’ ");
INSERT INTO hausa_vpl VALUES ("EK36_3","027_36_3","EZK","36","3","3","Saboda haka ka yi annabci ka ce, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa domin sun lalace ku suka kuma maishe ku kufai marar amfani a kowane gefe saboda ku zama mallakar sauran al’ummai da kuma abin magana da tsegumi ga mutane, ");
INSERT INTO hausa_vpl VALUES ("EK36_4","027_36_4","EZK","36","4","4","saboda haka, ya duwatsun Isra’ila, ku ji maganar Ubangiji Mai Iko Duka, ga abin da Ubangiji Mai Iko Duka yana faɗa wa duwatsu da tuddai, wa kwazazzabai da kwaruruka, wa kufai da garuruwan da suka zama kango waɗanda aka washe aka wulaƙanta suka zama ganimar sauran al’ummai da suke kewaye da ku, ");
INSERT INTO hausa_vpl VALUES ("EK36_5","027_36_5","EZK","36","5","5","ga abin da Ubangiji Mai Iko Duka yana cewa cikin kishina mai ƙuna na yi magana gāba da sauran al’ummai, da kuma gāba da Edom, gama da farin ciki da reni a zukatansu suka mai da ƙasata mallakarsu don su washe wuraren kiwonta.’ ");
INSERT INTO hausa_vpl VALUES ("EK36_6","027_36_6","EZK","36","6","6","Saboda haka ka yi annabci game da ƙasar Isra’ila ka kuma ce wa duwatsu da tuddai, wa kwazazzabai da kwaruruka, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa ga shi, na yi magana da kishina da hasalata saboda sun sha zargi wurin al’ummai. ");
INSERT INTO hausa_vpl VALUES ("EK36_7","027_36_7","EZK","36","7","7","Ga abin da Ubangiji Mai Iko Duka yana cewa na ɗaga hannuna sama na rantse cewa al’ummai da suke kewaye da ku za su sha ba’a. ");
INSERT INTO hausa_vpl VALUES ("EK36_8","027_36_8","EZK","36","8","8","“ ‘Amma ku, ya duwatsun Isra’ila, za ku miƙa rassanku ku ba da amfani ga mutanena Isra’ila, gama ba da daɗewa ba za su komo gida. ");
INSERT INTO hausa_vpl VALUES ("EK36_9","027_36_9","EZK","36","9","9","Na damu da ku kuma zan dube ku da tausayi; za ku nome ku kuma shuka, ");
INSERT INTO hausa_vpl VALUES ("EK36_10","027_36_10","EZK","36","10","10","zan kuma riɓaɓɓanya mutane a kanku, dukan gidan Isra’ila ke nan. Za a zauna a birane a kuma sāke gina rusassun wurare. ");
INSERT INTO hausa_vpl VALUES ("EK36_11","027_36_11","EZK","36","11","11","Zan sa mutane da dabbobi su yi yawa a kanku, za su kuma ba da ’ya’ya su kuma yi yawa. Zan zaunar da mutane a kanku kamar dā zan kuma sa ku wadaita fiye da dā. Sa’an nan za ku san cewa ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK36_12","027_36_12","EZK","36","12","12","Zan sa mutanena Isra’ila su yi tafiya a kanku. Za su mallake ku, za ku kuma zama gādonsu; ba za ku ƙara sa su rasa ’ya’yansu ba. ");
INSERT INTO hausa_vpl VALUES ("EK36_13","027_36_13","EZK","36","13","13","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa domin mutane suna magana game da ku cewa, “Kun cinye mutane kuka kuma sa al’ummarku ta rasa ’ya’yanta,” ");
INSERT INTO hausa_vpl VALUES ("EK36_14","027_36_14","EZK","36","14","14","saboda haka ba za ku ƙara cinye mutane ko ku sa al’ummarku ta rasa ’ya’ya ba, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK36_15","027_36_15","EZK","36","15","15","Ba zan ƙara bari ku ji maganar banza ta al’ummai ba, ba kuwa za ku ƙara shan ba’ar mutane ko in sa al’ummarku ta fāɗi ba, in ji Ubangiji Mai Iko Duka.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK36_16","027_36_16","EZK","36","16","16","Maganar Ubangiji ta sāke zuwa mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK36_17","027_36_17","EZK","36","17","17","“Ɗan mutum, sa’ad da mutanen Isra’ila suke zama a ƙasarsu, sun ƙazantar da ita ta wurin halinsu da kuma ayyukansu. Halinsu ya yi kamar rashin tsarkin mace a lokacin al’adarta a gabana. ");
INSERT INTO hausa_vpl VALUES ("EK36_18","027_36_18","EZK","36","18","18","Saboda haka na husata da su domin sun yi kisankai a ƙasar kuma domin sun ƙazantar da ita da gumakansu. ");
INSERT INTO hausa_vpl VALUES ("EK36_19","027_36_19","EZK","36","19","19","Na warwatsa su cikin al’ummai, suka kuwa warwatsu cikin dukan ƙasashe; na hukunta su gwargwadon halinsu da ayyukansu. ");
INSERT INTO hausa_vpl VALUES ("EK36_20","027_36_20","EZK","36","20","20","Kuma ko’ina da suka tafi a cikin al’ummai sun ɓata sunana mai tsarki, gama an yi magana a kansu cewa, ‘Waɗannan mutanen Ubangiji ne, duk da haka dole su bar ƙasarsa.’ ");
INSERT INTO hausa_vpl VALUES ("EK36_21","027_36_21","EZK","36","21","21","Na damu saboda sunana mai tsarki, wanda gidan Isra’ila ya ɓata a cikin al’ummai inda suka tafi. ");
INSERT INTO hausa_vpl VALUES ("EK36_22","027_36_22","EZK","36","22","22","“Saboda haka ka faɗa musu cewa, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa ba dominku ba ne, ya gidan Isra’ila da nake yin waɗannan abubuwa, amma saboda sunana ne mai tsarki, wanda kuka ɓata a cikin al’ummai inda kuka tafi. ");
INSERT INTO hausa_vpl VALUES ("EK36_23","027_36_23","EZK","36","23","23","Zan nuna tsarkin girman sunana, wanda aka ɓata a cikin al’umma, sunana da kuka ɓata a cikinsu. Sa’an nan al’ummai za su san cewa ni ne Ubangiji, in ji Ubangiji Mai Iko Duka, sa’ad da na nuna kaina mai tsarki ta wurinku a idanunsu. ");
INSERT INTO hausa_vpl VALUES ("EK36_24","027_36_24","EZK","36","24","24","“ ‘Gama zan fitar da ku daga al’ummai; zan tattara ku daga dukan ƙasashe in komo da ku zuwa ƙasarku. ");
INSERT INTO hausa_vpl VALUES ("EK36_25","027_36_25","EZK","36","25","25","Zan yayyafa muku ruwa mai tsabta, zan kuwa tsarkake ku daga dukan ƙazantarku daga kuma dukan gumakanku. ");
INSERT INTO hausa_vpl VALUES ("EK36_26","027_36_26","EZK","36","26","26","Zan ba ku sabuwa zuciya in kuma sa sabon ruhu a cikinku; zan fid da zuciyar dutse in kuma ba ku zuciyar nama. ");
INSERT INTO hausa_vpl VALUES ("EK36_27","027_36_27","EZK","36","27","27","Zan kuma sa Ruhuna a cikinku in kuma motsa ku ku bi ƙa’idodina ku kuma kiyaye dokokina. ");
INSERT INTO hausa_vpl VALUES ("EK36_28","027_36_28","EZK","36","28","28","Za ku zauna a ƙasar da na ba wa kakanninku; za ku zama mutanena, ni kuwa zan zama Allahnku. ");
INSERT INTO hausa_vpl VALUES ("EK36_29","027_36_29","EZK","36","29","29","Zan cece ku daga dukan rashin tsabtarku. Zan sa hatsi ya yi yalwa ba zan kawo yunwa a kanku ba. ");
INSERT INTO hausa_vpl VALUES ("EK36_30","027_36_30","EZK","36","30","30","Zan ƙara ’ya’yan itatuwa da amfanin gona, saboda kada ku ƙara shan kunya a cikin al’ummai saboda yunwa. ");
INSERT INTO hausa_vpl VALUES ("EK36_31","027_36_31","EZK","36","31","31","Sa’an nan za ku tuna mugayen hanyoyinku da mugayen ayyukanku, za ku kuwa ji ƙyamar kanku saboda zunubanku da kuma ayyukanku na banƙyama. ");
INSERT INTO hausa_vpl VALUES ("EK36_32","027_36_32","EZK","36","32","32","Ina so ku san cewa ba na yi wannan saboda ku, in ji Ubangiji Mai Iko Duka. Ku ji kunya ku kuma giggita saboda halinku, ya gidan Isra’ila! ");
INSERT INTO hausa_vpl VALUES ("EK36_33","027_36_33","EZK","36","33","33","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa a ranar da na tsarkake ku daga dukan zunubanku, zan sāke zaunar da ku a garuruwanku, a kuma sāke gina kufai. ");
INSERT INTO hausa_vpl VALUES ("EK36_34","027_36_34","EZK","36","34","34","Ƙasar da take kango a dā za ku nome ta a maimakon zama kango a idon dukan masu ratsawa a cikinta. ");
INSERT INTO hausa_vpl VALUES ("EK36_35","027_36_35","EZK","36","35","35","Za su ce, “Wannan ƙasar da take kango a dā ta zama kamar lambu Eden; biranen da dā suke kufai, kango da kuma aka lalata, yanzu suna da katanga ana kuma zama a ciki.” ");
INSERT INTO hausa_vpl VALUES ("EK36_36","027_36_36","EZK","36","36","36","Sa’an nan al’ummai kewaye da ku da suka rage za su san cewa Ni Ubangiji na sāke gina abin da aka lalace na kuma sāke shuka abin da yake kango. Ni Ubangiji na faɗa, kuma zan aikata.’ ");
INSERT INTO hausa_vpl VALUES ("EK36_37","027_36_37","EZK","36","37","37","“Ga abin da Ubangiji Mai Iko Duka yana cewa har yanzu zan ji roƙon gidan Isra’ila in kuma yi musu wannan. Zan sa mutanensu su yi yawa kamar tumaki, ");
INSERT INTO hausa_vpl VALUES ("EK36_38","027_36_38","EZK","36","38","38","yawansu ya yi kamar garken tumaki don hadaya a Urushalima a ƙayyadaddun lokuta bukukkuwarta. Haka biranen da suke kufai za su cika da ɗumbun mutane. Sa’an nan za su san cewa ni ne Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("EK37_1","027_37_1","EZK","37","1","1","Hannun Ubangiji yana a kaina, ya kuma fitar da ni ta wurin Ruhun Ubangiji ya sa ni a tsakiyar kwarin; yana cike da ƙasusuwa. ");
INSERT INTO hausa_vpl VALUES ("EK37_2","027_37_2","EZK","37","2","2","Ya sa na kai na komo a ciki, na kuma ga ƙasusuwa masu girma da yawa a ƙasar kwarin, ƙasusuwan da suka bushe ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("EK37_3","027_37_3","EZK","37","3","3","Sai ya tambaye ni cewa, “Ɗan mutum, waɗannan ƙasusuwa za su iya rayu?” Ni kuwa na ce, “Ya Ubangiji Mai Iko Duka, kai kaɗai ka sani.” ");
INSERT INTO hausa_vpl VALUES ("EK37_4","027_37_4","EZK","37","4","4","Sai ya ce mini, “Ka yi wa waɗannan ƙasusuwa annabci ka ce musu, ‘Busassun ƙasusuwa, ku ji maganar Ubangiji! ");
INSERT INTO hausa_vpl VALUES ("EK37_5","027_37_5","EZK","37","5","5","Ga abin da Ubangiji Mai Iko Duka ya ce wa waɗannan ƙasusuwa. Zan sa numfashi ya shiga muku, za ku kuwa rayu. ");
INSERT INTO hausa_vpl VALUES ("EK37_6","027_37_6","EZK","37","6","6","Zan harhaɗa muku jijiyoyi in sa muku tsoka in kuma rufe ku da fata; zan sa numfashi a cikinku, za ku kuwa rayu. Sa’an nan za ku san cewa ni ne Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK37_7","027_37_7","EZK","37","7","7","Saboda haka sai na yi annabci yadda aka umarce ni. Da nake annabcin, sai aka ji motsi, ƙarar girgiza, sai ƙasusuwan suka harhaɗu, ƙashi ya haɗu da ƙashi. ");
INSERT INTO hausa_vpl VALUES ("EK37_8","027_37_8","EZK","37","8","8","Na duba, sai ga jijiyoyi da nama suka bayyana a kansu fata kuma ta rufe su, amma ba numfashi a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("EK37_9","027_37_9","EZK","37","9","9","Sa’an nan ya ce mini, “Ka yi annabci wa numfashi; ka yi annabci, ɗan mutum, ka ce masa, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa ka fito daga kusurwoyi huɗu, ya numfashi, ka kuma numfasa cikin waɗannan matattu, don su rayu.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK37_10","027_37_10","EZK","37","10","10","Saboda haka na yi annabci yadda aka umarce ni, sai numfashi ya shiga musu; suka rayu suka kuma miƙe tsaye a ƙafafunsu babbar runduna ce ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("EK37_11","027_37_11","EZK","37","11","11","Sa’an nan ya ce mini, “Ɗan mutum, waɗannan ƙasusuwa su ne dukan gidan Isra’ila. Suna cewa, ‘Ƙasusuwanmu sun bushe, sa zuciyarmu duk ya tafi; an share mu ƙaf.’ ");
INSERT INTO hausa_vpl VALUES ("EK37_12","027_37_12","EZK","37","12","12","Saboda haka yi annabci ka ce musu, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa ya mutanena, zan buɗe kaburburanku in fitar da ku daga cikinsu; zan mai da ku ƙasar Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK37_13","027_37_13","EZK","37","13","13","Sa’an nan ku, mutanena, za ku san cewa ni ne Ubangiji, sa’ad da na buɗe kaburburanku na fitar da ku daga cikinsu. ");
INSERT INTO hausa_vpl VALUES ("EK37_14","027_37_14","EZK","37","14","14","Zan sa Ruhuna a cikinku za ku kuwa rayu, zan kuma zaunar da ku a ƙasarku. Sa’an nan za ku san cewa Ni Ubangiji na faɗa, zan kuma aikata, in ji Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK37_15","027_37_15","EZK","37","15","15","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK37_16","027_37_16","EZK","37","16","16","“Ɗan mutum, ka ɗauki sanda ka rubuta a kansa, ‘Na Yahuda da Isra’ilawan da suke tare da shi.’ Sa’an nan ka ɗauki wani sanda, ka rubuta a kansa, ‘Sandan Efraim, na Yusuf da dukan gidan Isra’ilan da suke tare da shi.’ ");
INSERT INTO hausa_vpl VALUES ("EK37_17","027_37_17","EZK","37","17","17","Ka haɗa su su zama sanda guda saboda su kasance ɗaya a hannunka. ");
INSERT INTO hausa_vpl VALUES ("EK37_18","027_37_18","EZK","37","18","18","“In mutanen ƙasarka suka tambaye ka cewa, ‘Ba za ka faɗa mana abin da kake nufi da wannan ba?’ ");
INSERT INTO hausa_vpl VALUES ("EK37_19","027_37_19","EZK","37","19","19","Ka ce musu, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa, Zan ɗauki sandan Yusuf, wanda yake a hannun Efraim, da na kabilan Isra’ilawan da suke tare da shi, in haɗa shi da sandan Yahuda, in mai da su sanda guda, za su kuwa zama ɗaya a hannuna.’ ");
INSERT INTO hausa_vpl VALUES ("EK37_20","027_37_20","EZK","37","20","20","Ka riƙe sandunan da ka yi rubutun a gabansu ");
INSERT INTO hausa_vpl VALUES ("EK37_21","027_37_21","EZK","37","21","21","ka ce musu, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa zan fitar da Isra’ilawa daga al’ummai inda suka tafi. Zan tattara su daga dukan kewaye in komo da su ƙasarsu. ");
INSERT INTO hausa_vpl VALUES ("EK37_22","027_37_22","EZK","37","22","22","Zan mai da su al’umma ɗaya a cikin ƙasar, a kan duwatsun Isra’ila. Za a kasance da sarki guda a kan dukansu ba za su ƙara zama al’ummai biyu ko su rabu su zama masarautai biyu ba. ");
INSERT INTO hausa_vpl VALUES ("EK37_23","027_37_23","EZK","37","23","23","Ba za su ƙara ƙazantar da kansu da gumaka da mugayen siffofi ko kuma da wani daga laifofinsu ba, gama zan cece su daga dukan zunubinsu na ridda, zan kuma tsarkake su. Za su zama mutanena, ni kuma zan zama Allahnsu. ");
INSERT INTO hausa_vpl VALUES ("EK37_24","027_37_24","EZK","37","24","24","“ ‘Bawana Dawuda zai zama sarki a kansu, dukansu kuwa za su kasance da makiyayi guda. Za su bi dokokina su kuma kiyaye ƙa’idodina. ");
INSERT INTO hausa_vpl VALUES ("EK37_25","027_37_25","EZK","37","25","25","Za su zauna a ƙasar da na ba wa bawana Yaƙub, ƙasar da kakanninsu suka zauna. Su da ’ya’yansu da ’ya’ya ’ya’yansu za su zauna a can har abada, kuma Dawuda bawana zai zama sarkinsu har abada. ");
INSERT INTO hausa_vpl VALUES ("EK37_26","027_37_26","EZK","37","26","26","Zan yi alkawarin salama da su; zai zama madawwamin alkawari. Zan kafa su in ƙara yawansu, zan kuma sa wuri mai tsarkina a cikinsu har abada. ");
INSERT INTO hausa_vpl VALUES ("EK37_27","027_37_27","EZK","37","27","27","Mazaunina zai kasance da su; zan kuwa zama Allahnsu, za su kuma zama mutanena. ");
INSERT INTO hausa_vpl VALUES ("EK37_28","027_37_28","EZK","37","28","28","Sa’an nan al’ummai za su san cewa Ni Ubangiji na mai da Isra’ila mai tsarki, sa’ad da wuri mai tsarkina yana a cikinsu har abada.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK38_1","027_38_1","EZK","38","1","1","Maganar Ubangiji ta zo mini cewa, ");
INSERT INTO hausa_vpl VALUES ("EK38_2","027_38_2","EZK","38","2","2","“Ɗan mutum, ka fuskanci Gog, na ƙasar Magog, babban sarkin Meshek da Tubal; ka yi annabci a kansa ");
INSERT INTO hausa_vpl VALUES ("EK38_3","027_38_3","EZK","38","3","3","ka ce, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa ina gāba da kai, ya Gog, babban sarkin Meshek da Tubal. ");
INSERT INTO hausa_vpl VALUES ("EK38_4","027_38_4","EZK","38","4","4","Zan juyar da kai, in sa ƙugiyoyi a muƙamuƙanka in fitar da kai tare da dukan sojojinka, dawakanka, mahayan dawakanka saye da makamai, da kuma jama’a mai girma masu riƙe da garkuwoyi manya da ƙanana, dukansu da takuba a zāre. ");
INSERT INTO hausa_vpl VALUES ("EK38_5","027_38_5","EZK","38","5","5","Farisa, Kush da Fut za su kasance tare da su, duka riƙe da garkuwoyi da hulunan kwano, ");
INSERT INTO hausa_vpl VALUES ("EK38_6","027_38_6","EZK","38","6","6","haka ma Gomer da dukan sojojinsa, da Bet Togarma daga can arewa tare da dukan sojojinsa, al’ummai masu yawa tare da kai. ");
INSERT INTO hausa_vpl VALUES ("EK38_7","027_38_7","EZK","38","7","7","“ ‘Ka shirya; ka kintsa, kai da dukan jama’arka da suka taru kewaye da kai, ka kuma zama mai ba su umarni. ");
INSERT INTO hausa_vpl VALUES ("EK38_8","027_38_8","EZK","38","8","8","Bayan kwanaki masu yawa za a kira ka. A shekaru masu zuwa za ka kai hari a ƙasar da ta farfaɗo daga yaƙi, wadda aka tattara mutanenta daga al’ummai masu yawa zuwa duwatsun Isra’ila, dā kango ne sosai. An fitar da su daga al’ummai, yanzu kuwa dukansu suna zama lafiya. ");
INSERT INTO hausa_vpl VALUES ("EK38_9","027_38_9","EZK","38","9","9","Kai da dukan sojojinka da kuma al’ummai masu yawa da suke tare da kai za ku haura, kuna cin gaba kamar hadari; za ku zama kamar girgijen da yake rufewa ƙasa. ");
INSERT INTO hausa_vpl VALUES ("EK38_10","027_38_10","EZK","38","10","10","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa a ranar, tunani zai shiga cikin zuciyarka za ka kuma ƙirƙiro muguwar dabara. ");
INSERT INTO hausa_vpl VALUES ("EK38_11","027_38_11","EZK","38","11","11","Za ka ce, “Zan kai hari wa ƙasar da ƙauyukanta ba su da katanga; zan fāɗa wa mutanen da suke zamansu kurum cikin salama, dukansu suna zama babu katanga babu ƙofofi ko ƙyamare. ");
INSERT INTO hausa_vpl VALUES ("EK38_12","027_38_12","EZK","38","12","12","Zan washe in kwashe ganima in kuma juye hannuna gāba da kufai da aka sāke zaunar da mutanen da aka tattara daga al’ummai, masu yawan shanu da kayayyaki, masu zama a tsakiyar ƙasa.” ");
INSERT INTO hausa_vpl VALUES ("EK38_13","027_38_13","EZK","38","13","13","Sheba da Dedan da ’yan kasuwar Tarshish da dukan ƙauyukanta za su ce maka, “Ka zo ka kwashe ganima ne? Ka tattara jama’arka don ka yi waso, ka kuma kwashe azurfa da zinariya, ka kwashe shanu da kayayyaki ka kuma ƙwace ganima mai yawa?” ’ ");
INSERT INTO hausa_vpl VALUES ("EK38_14","027_38_14","EZK","38","14","14","“Saboda haka ɗan mutum, ka yi annabci ka ce wa Gog, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa a ranar, sa’ad da mutanena Isra’ila suna zaman lafiya, ba za ka sani ba? ");
INSERT INTO hausa_vpl VALUES ("EK38_15","027_38_15","EZK","38","15","15","Za ka zo daga wurinka a can arewa, kai da al’ummai masu yawa tare da kai, dukansu suna hawan dawakai, jama’a mai yawa, babbar runduna. ");
INSERT INTO hausa_vpl VALUES ("EK38_16","027_38_16","EZK","38","16","16","Za ka ci gaba a kan mutanena Isra’ila kamar yadda girgijen yakan rufe ƙasa. A kwanaki masu zuwa, ya Gog, zan kawo ka, ka yi yaƙi da ƙasata, domin al’ummai su san ni sa’ad da na nuna kaina mai tsarki ta wurinka a gabansu. ");
INSERT INTO hausa_vpl VALUES ("EK38_17","027_38_17","EZK","38","17","17","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa ba kai ba ne na yi magana da kai a kwanakin dā ta wurin bayina annabawan Isra’ila? A lokacin sun yi annabci shekaru masu yawa cewa zan kawo ka, ka yaƙe su. ");
INSERT INTO hausa_vpl VALUES ("EK38_18","027_38_18","EZK","38","18","18","Ga abin da zai faru a ranar. Sa’ad da Gog ya fāɗa wa ƙasar Isra’ila, fushina mai zafi zai ƙuna, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK38_19","027_38_19","EZK","38","19","19","Cikin kishina da hasalata mai zafi zan furta cewa a wannan lokaci za a yi babbar girgizar ƙasa a ƙasar Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK38_20","027_38_20","EZK","38","20","20","Kifin teku, tsuntsayen sarari, namun jeji, kowace halitta mai rarrafe da kuma dukan mutane a duniya za su yi rawar jiki a gabana. Za a tumɓuke duwatsu, a ragargaza tsaunuka, kuma kowane bango zai fāɗi ƙasa. ");
INSERT INTO hausa_vpl VALUES ("EK38_21","027_38_21","EZK","38","21","21","Zan kira takobi a kan Gog a dukan duwatsuna, in ji Ubangiji Mai Iko Duka. Kowane takobin mutum zai yi gāba da ɗan’uwansa. ");
INSERT INTO hausa_vpl VALUES ("EK38_22","027_38_22","EZK","38","22","22","Zan yi hukunci a kansa da annoba da kuma zub da jini; zan yi ruwa mai yawa da ƙanƙara da kibiritu mai cin wuta a kansa da a kan sojojinsa da kuma a kan al’ummai masu yawa da suke tare da shi. ");
INSERT INTO hausa_vpl VALUES ("EK38_23","027_38_23","EZK","38","23","23","Ta haka zan nuna girmana da kuma tsarkina, zan sanar da kaina a gaban al’ummai masu yawa. Sa’an nan za su san cewa ni ne Ubangiji.’ ");
INSERT INTO hausa_vpl VALUES ("EK39_1","027_39_1","EZK","39","1","1","“Ɗan mutum, ka yi annabci a kan Gog ka ce, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa ina gāba da kai, ya Gog, babban sarkin Meshek da Tubal. ");
INSERT INTO hausa_vpl VALUES ("EK39_2","027_39_2","EZK","39","2","2","Zan juya ka in kuma ja ka. Zan kawo ka daga can arewa in aike ka don ka fāɗa wa duwatsun Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK39_3","027_39_3","EZK","39","3","3","Sa’an nan zan karya bakan da take a hannun hagunka, in sa kibiyoyin da suke a hannun damanka su fāɗi. ");
INSERT INTO hausa_vpl VALUES ("EK39_4","027_39_4","EZK","39","4","4","A kan duwatsun Isra’ila za ka fāɗi, kai da sojojinka da kuma al’ummai da suke tare da kai. Zan bayar da kai ka zama abinci ga tsuntsaye da namun jeji masu cin nama. ");
INSERT INTO hausa_vpl VALUES ("EK39_5","027_39_5","EZK","39","5","5","Za ka mutu a fili, gama haka ni na faɗa, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK39_6","027_39_6","EZK","39","6","6","Zan aika da wuta a kan Magog da kuma a kan waɗanda suke zama lafiya a bakin teku, za su kuwa san cewa ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK39_7","027_39_7","EZK","39","7","7","“ ‘Zan sanar da sunana mai tsarki a cikin mutanena Isra’ila. Ba zan ƙara bari a ɓata sunana mai tsarki ba, kuma al’ummai za su san cewa Ni Ubangiji Mai Tsarki ne a cikin Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK39_8","027_39_8","EZK","39","8","8","Yana zuwa! Tabbatacce zai faru, in ji Ubangiji Mai Iko Duka. Ranar da na yi magana ke nan. ");
INSERT INTO hausa_vpl VALUES ("EK39_9","027_39_9","EZK","39","9","9","“ ‘Sa’an nan waɗanda suke zama a garuruwan Isra’ila za su fita su tattara makamai su hura wuta da su su kuma ƙone su, manya da ƙanana garkuwoyi, bakkuna da kibiyoyi, kulake da māsu. Shekara bakwai za su yi amfani da su don hura wuta. ");
INSERT INTO hausa_vpl VALUES ("EK39_10","027_39_10","EZK","39","10","10","Ba za su yi wahalar zuwa jeji don neman itacen hura wuta ba, domin za su yi amfani da makamai don hura wuta. Za su kuma washe waɗanda suka washe su ganima, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK39_11","027_39_11","EZK","39","11","11","“ ‘A ranar zan yi wa Gog makabarta a cikin Isra’ila, a kwarin waɗanda suke tafiya wajen gabashin Teku. Za tă tare hanyar matafiya, domin za a binne Gog da dukan mutanensa a can. Ta haka za a kira wurin Kwarin Haman Gog. ");
INSERT INTO hausa_vpl VALUES ("EK39_12","027_39_12","EZK","39","12","12","“ ‘Watanni bakwai gidan Isra’ila zai yi ta binne su don a tsarkake ƙasar. ");
INSERT INTO hausa_vpl VALUES ("EK39_13","027_39_13","EZK","39","13","13","Dukan mutanen ƙasar za su binne su, kuma ranar da za a ɗaukaka ni za tă zama ranar tuni a gare su, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK39_14","027_39_14","EZK","39","14","14","“ ‘Za a ɗauki mutane kullum don tsabtacce ƙasar. Waɗansu za su ratsa ƙasar, ƙari da waɗannan, waɗansu za su binne gawawwakin da suka ragu a ƙasar. A ƙarshen watanni bakwai ɗin za su fara bincikensu. ");
INSERT INTO hausa_vpl VALUES ("EK39_15","027_39_15","EZK","39","15","15","Yayinda suke ratsa ƙasar, in waninsu ya ga ƙashin mutum, zai kafa shi kamar alama a gefe sai masu haƙa kabari sun binne shi a Kwarin Haman Gog. ");
INSERT INTO hausa_vpl VALUES ("EK39_16","027_39_16","EZK","39","16","16","Akwai wani garin da ake kira Hamona zai kasance a can. Ta haka za su tsabtacce ƙasar.’ ");
INSERT INTO hausa_vpl VALUES ("EK39_17","027_39_17","EZK","39","17","17","“Ɗan mutum, ga abin da Ubangiji Mai Iko Duka yana cewa, ka gayyato kowane irin tsuntsu da dukan namun jeji, ‘Ku taru ku kuma zo wuri ɗaya daga ko’ina don hadayar da nake shirya muku, babbar hadaya a kan duwatsun Isra’ila. A can za ku ci nama ku kuma sha jini. ");
INSERT INTO hausa_vpl VALUES ("EK39_18","027_39_18","EZK","39","18","18","Za ku ci naman manyan mutane ku kuma sha jinin sarakunan duniya sai ka ce an yanka raguna da ’yan tumaki, awaki da bijimai, dukansu turkakkun dabbobi daga Bashan. ");
INSERT INTO hausa_vpl VALUES ("EK39_19","027_39_19","EZK","39","19","19","A hadayar da nake shirya muku, za ku ci kitse sai kun ƙoshi ku kuma sha jini sai kun bugu. ");
INSERT INTO hausa_vpl VALUES ("EK39_20","027_39_20","EZK","39","20","20","A teburina za ku ci iya ƙoshiyarku da naman jama’a da kuma mahaya, manyan mutane da sojoji na kowane iri,’ in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK39_21","027_39_21","EZK","39","21","21","“Zan nuna ɗaukakata a cikin al’ummai, kuma dukan al’ummai za su ga hukuncin da zan yi da kuma hannu mai nauyin da zan ɗora a kansu. ");
INSERT INTO hausa_vpl VALUES ("EK39_22","027_39_22","EZK","39","22","22","Daga wannan rana zuwa gaba gidan Isra’ila zai san cewa ni ne Ubangiji Allahnsu. ");
INSERT INTO hausa_vpl VALUES ("EK39_23","027_39_23","EZK","39","23","23","Al’ummai kuma za su san cewa mutanen Isra’ila sun tafi zaman bauta saboda zunubinsu, domin sun yi rashin aminci gare ni. Saboda haka na kawar da fuskata daga gare su na miƙa su ga abokan gābansu, suka kuwa mutu ta takobi. ");
INSERT INTO hausa_vpl VALUES ("EK39_24","027_39_24","EZK","39","24","24","Na yi da su gwargwadon rashin tsabtarsu da laifofinsu, na kuma kawar da fuskata daga gare su. ");
INSERT INTO hausa_vpl VALUES ("EK39_25","027_39_25","EZK","39","25","25","“Saboda haka ga abin da Ubangiji Mai Iko Duka yana cewa zan komo da Yaƙub daga zaman bauta zan kuma yi wa dukan Isra’ila jinƙai, zan kuma yi kishi saboda sunana mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK39_26","027_39_26","EZK","39","26","26","Za su manta da kunyar da suka sha da dukan rashin amincin da suka nuna mini sa’ad da suke zama lafiya a ƙasarsu inda ba wanda zai tsorata su. ");
INSERT INTO hausa_vpl VALUES ("EK39_27","027_39_27","EZK","39","27","27","Sa’ad da na komo da su daga al’ummai na kuma tattara su daga ƙasashen abokan gābansu, zan nuna kaina mai tsarki ta wurinsu a gaban al’ummai masu yawa. ");
INSERT INTO hausa_vpl VALUES ("EK39_28","027_39_28","EZK","39","28","28","Sa’an nan za su san cewa ni ne Ubangiji Allahnsu, gama ko da yake na tura su zaman bauta a cikin al’ummai, zan tattara su zuwa ƙasarsu, ba tare da barin wani a baya ba. ");
INSERT INTO hausa_vpl VALUES ("EK39_29","027_39_29","EZK","39","29","29","Ba zan ƙara kawar da fuskata daga gare su, gama zan zuba Ruhuna a kan gidan Isra’ila, in ji Ubangiji Mai Iko Duka.” ");
INSERT INTO hausa_vpl VALUES ("EK40_1","027_40_1","EZK","40","1","1","A shekara ta ashirin da biyar ta zaman bauta, a farkon shekara, a rana ta goma ga wata, a shekara ta goma sha huɗu bayan fāɗuwar birnin Urushalima, a wannan rana ikon Ubangiji ya sauko a kaina ya kuma iza ni. ");
INSERT INTO hausa_vpl VALUES ("EK40_2","027_40_2","EZK","40","2","2","Cikin wahayin, Allah ya kai ni ƙasar Isra’ila ya sa ni a kan wani dutse mai tsayi ƙwarai, inda a gefen kudunsa akwai gine-ginen da suka yi kamar birni. ");
INSERT INTO hausa_vpl VALUES ("EK40_3","027_40_3","EZK","40","3","3","A cikin wahayin ya kai ni can, na kuma ga mutum wanda kamanninsa ya yi kamar tagulla; yana tsaye a hanyar shiga yana riƙe da igiyar lilin da kuma karan awo a hannunsa. ");
INSERT INTO hausa_vpl VALUES ("EK40_4","027_40_4","EZK","40","4","4","Mutumin ya ce mini, “Ɗan mutum, duba da idanunka, ka ji da kunnuwanka ka kuma lura da kowane abin da zan nuna maka, gama abin da ya sa na kawo ka nan ke nan. Ka faɗa wa gidan Isra’ila duk abin da ka gani.” ");
INSERT INTO hausa_vpl VALUES ("EK40_5","027_40_5","EZK","40","5","5","Na ga katanga da ya kewaye filin haikali gaba ɗaya. Tsawon karan awon da yake a hannun mutumin kamu shida ne, sai ya auna kaurin katangar ya sami kamu shida, tsayinta kuma kamu shida. ");
INSERT INTO hausa_vpl VALUES ("EK40_6","027_40_6","EZK","40","6","6","Sa’an nan ya tafi ƙofar da take fuskantar gabas. Ya hau matakanta ya auna madogarar ƙofa; zurfinta kamu shida ne. ");
INSERT INTO hausa_vpl VALUES ("EK40_7","027_40_7","EZK","40","7","7","Tsawon kowane ɗakin matsara kamu shida ne, fāɗinsa kuma kamu shida, kaurin bangayen da suka raba ɗaki da ɗaki kamu biyar ne. Zurfin madogarar ƙofar da yake dab da shirayin da yake fuskantar haikalin kamu shida ne. ");
INSERT INTO hausa_vpl VALUES ("EK40_8","027_40_8","EZK","40","8","8","Sa’an nan ya auna shirayin hanyar shiga; ");
INSERT INTO hausa_vpl VALUES ("EK40_9","027_40_9","EZK","40","9","9","zurfinsa kamu takwas ne, kaurin kowane madogarar ƙofarsa kuwa kamu biyu ne. Shirayi hanyar shiga yana fuskantar haikalin. ");
INSERT INTO hausa_vpl VALUES ("EK40_10","027_40_10","EZK","40","10","10","A cikin ƙofar gabas akwai ɗakuna uku a kowane gefe na hanyar shiga; dukan ukun girmansu ɗaya, bangayen da suke tsakani a kowane gefe girmansu ɗaya ne. ");
INSERT INTO hausa_vpl VALUES ("EK40_11","027_40_11","EZK","40","11","11","Sa’an nan ya auna bakin hanyar shiga ya sami fāɗinsa kamu goma, tsawonsa kuma kamu goma sha uku. ");
INSERT INTO hausa_vpl VALUES ("EK40_12","027_40_12","EZK","40","12","12","A gaban kowane ɗakin akwai bango mai tsayi kamu ɗaya, ɗakunan kuma kamu shida-shida ne a kowane gefe. ");
INSERT INTO hausa_vpl VALUES ("EK40_13","027_40_13","EZK","40","13","13","Sa’an nan ya auna hanyar shiga daga saman bangon ɗaki a baya zuwa saman ɗakin da yake ɗaura da shi; nisansu kamu ashirin da biyar ne daga bango zuwa bango. ");
INSERT INTO hausa_vpl VALUES ("EK40_14","027_40_14","EZK","40","14","14","Ya auna ɗakin bakin ƙofa na can ƙarshen hanyar shiga ya sami kamu sittin. Awon ya kai har zuwa shirayin da yake fuskantar filin. ");
INSERT INTO hausa_vpl VALUES ("EK40_15","027_40_15","EZK","40","15","15","Nisan da take daga mashigin hanyar shiga zuwa can ƙarshen shirayin, kamu hamsin ne. ");
INSERT INTO hausa_vpl VALUES ("EK40_16","027_40_16","EZK","40","16","16","Akwai ƙananan tagogi a ɗakunan da kuma a bangayen hanyar shiga, yadda suke a shirayin; tagogi a kewaye duka suna fuskantar ciki. An yi wa bangayen da suke waje ƙofar shiga ado da zāne-zāne siffofin itatuwan dabino. ");
INSERT INTO hausa_vpl VALUES ("EK40_17","027_40_17","EZK","40","17","17","Sai mutumin ya bi da ni ta hanyar shiga zuwa filin waje, inda na ga ɗakuna talatin da aka gina kewaye a filin waje na filin. An gina waɗannan ɗakunan gefe a jikin bangon waje, a gabansu kuwa akwai daɓe kewaye da filin. ");
INSERT INTO hausa_vpl VALUES ("EK40_18","027_40_18","EZK","40","18","18","Daɓen ya bi ta daidai gefen hanyoyin shiga, kuma faɗinsa ya yi daidai da tsawon ƙofofin shiga; wannan shi ne daɓen da yake ƙasa-ƙasa. ");
INSERT INTO hausa_vpl VALUES ("EK40_19","027_40_19","EZK","40","19","19","Sa’an nan ya auna nisan da take daga hanyar shiga da take ƙasa-ƙasa daga ciki zuwa waje na filin ciki; ya kai kamu ɗari a gefen gabas haka ma yake a gefen arewa. ");
INSERT INTO hausa_vpl VALUES ("EK40_20","027_40_20","EZK","40","20","20","Sa’an nan mutumin ya auna tsawo da fāɗin ƙofar da take fuskantar arewa, wadda take bi zuwa filin waje. ");
INSERT INTO hausa_vpl VALUES ("EK40_21","027_40_21","EZK","40","21","21","Ƙofar shigar ma tana da ɗakuna uku-uku a kowane gefe. Girman bangayen da suka miƙe, da kuma shirayinta daidai suke da na ƙofa ta fari. Tsawonta kamu hamsin, fāɗinta kuwa kamu ashirin da biyar. ");
INSERT INTO hausa_vpl VALUES ("EK40_22","027_40_22","EZK","40","22","22","Tagoginta, shirayinta da siffofin itatuwan dabinon da aka yi zāne-zānen adonta duk girmansu ɗaya ne da na ƙofar da take fuskantar gabas. Ɗakin shiga shi ma ya fuskanci filin yana kuma da matakai bakwai waɗanda suka bi zuwa ƙofar shiga, da shirayinta ɗaura da su. ");
INSERT INTO hausa_vpl VALUES ("EK40_23","027_40_23","EZK","40","23","23","Akwai ƙofa zuwa filin ciki wadda take fuskantar ƙofar arewa, kamar dai yadda take a gabas. Ya auna daga ƙofa zuwa ƙofar da take ɗaura ta ita; ya sami kamu ɗari. ");
INSERT INTO hausa_vpl VALUES ("EK40_24","027_40_24","EZK","40","24","24","Sa’an nan ya kai ni gefen kudu, na kuma ga ƙofa tana fuskantar kudu. Ya auna madogaranta da shirayinta, dukansu girmansu ɗaya ne kamar sauran ƙofofi biyun. ");
INSERT INTO hausa_vpl VALUES ("EK40_25","027_40_25","EZK","40","25","25","Hanyar shiga da shirayinta suna da tagogi duk a kewaye, kamar tagogin sauran. Tsawonta kamu hamsin ne fāɗinta kuma kamu ashirin da biyar ne. ");
INSERT INTO hausa_vpl VALUES ("EK40_26","027_40_26","EZK","40","26","26","Matakai bakwai sun haura zuwa ƙofar, da shirayi ɗaura da matakan; tana da zāne-zānen adon itatuwan dabino a bangayen a kowane gefe. ");
INSERT INTO hausa_vpl VALUES ("EK40_27","027_40_27","EZK","40","27","27","Filin cikin ma yana da ƙofar da ta fuskanci kudu, sai ya auna daga wannan ƙofa zuwa ƙofar waje a gefen kudu; ya sami kamu ɗari. ");
INSERT INTO hausa_vpl VALUES ("EK40_28","027_40_28","EZK","40","28","28","Sai ya kawo ni cikin filin ciki ta ƙofar kudu, ya kuma auna ƙofar kudu; ita ma tana da girma ɗaya da sauran ƙofofin shiga. ");
INSERT INTO hausa_vpl VALUES ("EK40_29","027_40_29","EZK","40","29","29","Ɗakunanta na matsara, bangayenta duk suna da girma ɗaya da sauran. Hanyar shiga da shirayinta suna da tagogi duk a kewaye. Tsawonta kamu hamsin ne, fāɗinta kuma kamu ashirin da biyar ne. ");
INSERT INTO hausa_vpl VALUES ("EK40_30","027_40_30","EZK","40","30","30","(Fāɗin shirayun hanyoyin shiga kewaye da filin ciki kamu ashirin da biyar ne, fāɗinsu kuma kamu biyar.) ");
INSERT INTO hausa_vpl VALUES ("EK40_31","027_40_31","EZK","40","31","31","Shirayin ƙofar yana fuskantar filin waje; an yi zāne-zānen adon itatuwan dabino a madogarar bangayen hanyar shiga. Yana kuma da matakai takwas. ");
INSERT INTO hausa_vpl VALUES ("EK40_32","027_40_32","EZK","40","32","32","Sai ya kai ni filin da yake ciki a gefen gabas, ya kuma auna hanyar shiga; girmanta iri ɗaya ne kamar sauran. ");
INSERT INTO hausa_vpl VALUES ("EK40_33","027_40_33","EZK","40","33","33","Ɗakunanta, bangayenta da shirayinta duk girmansu iri ɗaya ne kamar sauran. Hanyar shiga da shirayinta suna da tagogi duk a kewaye. Tsawon hanyar shiga kamu hamsin ne, fāɗinta kuma kamu ashirin da biyar. ");
INSERT INTO hausa_vpl VALUES ("EK40_34","027_40_34","EZK","40","34","34","Shirayinta yana fuskantar filin da yake waje; tana da zāne-zānen adon itatuwan dabino a madogararta. Tana kuma da matakai takwas. ");
INSERT INTO hausa_vpl VALUES ("EK40_35","027_40_35","EZK","40","35","35","Sa’an nan ya kawo ni ƙofar arewa ya kuma auna ta. Girmanta ɗaya ne da sauran, ");
INSERT INTO hausa_vpl VALUES ("EK40_36","027_40_36","EZK","40","36","36","Haka ma ɗakunanta, bangayenta da shirayinta, ƙofar tana da tagogi duk a kewaye. Tsawonta kamu hamsin, fāɗinta kuma kamu ashirin da biyar. ");
INSERT INTO hausa_vpl VALUES ("EK40_37","027_40_37","EZK","40","37","37","Shirayin ƙofar ta fuskanci filin waje; tana da zāne-zānen adon itatuwan dabino a madogaranta, matakai takwas kuwa sun haura zuwa wajenta. ");
INSERT INTO hausa_vpl VALUES ("EK40_38","027_40_38","EZK","40","38","38","Ɗakin da hanya ta ratsa ciki yana kusa da shirayin a kowane hanyoyin shiga na ciki, inda a kan wanke hadayun ƙonawa. ");
INSERT INTO hausa_vpl VALUES ("EK40_39","027_40_39","EZK","40","39","39","A shirayin hanyar shiga akwai tebur biyu a kowane gefe, inda ake yankan hadayun ƙonawa, hadayun zunubi da kuma hadayun laifi. ");
INSERT INTO hausa_vpl VALUES ("EK40_40","027_40_40","EZK","40","40","40","Ta bangon waje na shirayin hanyar shiga, kusa da matakai a mashigin zuwa hanyar shiga da take arewa akwai tebur biyu, akwai kuma tebur biyu a gefe ɗaya na matakan. ");
INSERT INTO hausa_vpl VALUES ("EK40_41","027_40_41","EZK","40","41","41","Duka dai akwai tebur huɗu a gefe ɗaya na hanyar shiga, huɗu kuma a ɗaya gefen, tebur takwas ke nan gaba ɗaya, inda a kan yanka hadayu a kai. ");
INSERT INTO hausa_vpl VALUES ("EK40_42","027_40_42","EZK","40","42","42","Akwai kuma tebur huɗu da aka yi da sassaƙaƙƙun duwatsu don hadayun ƙonawa, tsawon kowanne kuwa kamu ɗaya da rabi ne, fāɗinsa kamu ɗaya da rabi, tsayinsa kuma kamu ɗaya. A kansu ne a kan ajiye kayan yanka hadayun ƙonawa da kuma sauran hadayu. ");
INSERT INTO hausa_vpl VALUES ("EK40_43","027_40_43","EZK","40","43","43","Aka kakkafa ƙugiyoyi kewaye a bangon, tsawon kowanne ya yi fāɗin tafin hannu. An yi amfani da teburin don a riƙa ajiye naman hadayu. ");
INSERT INTO hausa_vpl VALUES ("EK40_44","027_40_44","EZK","40","44","44","Waje da ƙofar ciki, a cikin filin ciki, akwai ɗakuna biyu, ɗaya a gefen ƙofar arewa yana kuma fuskantar kudu, wani kuma a gefen ƙofar kudu yana fuskantar arewa. ");
INSERT INTO hausa_vpl VALUES ("EK40_45","027_40_45","EZK","40","45","45","Sai mutumin ya ce mini, “Ɗakin da yake fuskantar kudu ne na firistocin da suke lura da haikali, ");
INSERT INTO hausa_vpl VALUES ("EK40_46","027_40_46","EZK","40","46","46","ɗaya ɗakin kuma da yake fuskantar arewa ne na firistocin da suke lura da bagade. Waɗannan su ne ’ya’yan Zadok maza, waɗanda su ne kaɗai Lawiyawan da za su iya yin kusa da Ubangiji don su yi hidima a gabansa.” ");
INSERT INTO hausa_vpl VALUES ("EK40_47","027_40_47","EZK","40","47","47","Sa’an nan ya auna filin, murabba’i ne, tsawonsa kamu ɗari, fāɗinsa kuma kamu ɗari. Bagaden kuwa yana a gaba a cikin haikalin. ");
INSERT INTO hausa_vpl VALUES ("EK40_48","027_40_48","EZK","40","48","48","Sai ya kawo ni shirayin haikalin ya kuma auna madogaran shirayin; fāɗinsu a kowane gefe kamu biyar-biyar ne. Fāɗin mashigin kamu goma sha huɗu ne, bangayenta kuma kamu uku-uku ne a kowane gefe. ");
INSERT INTO hausa_vpl VALUES ("EK40_49","027_40_49","EZK","40","49","49","Fāɗin shirayin kamu ashirin ne, kamu goma sha biyu kuma daga gaba zuwa baya. A kan kai samansa ta wurin hawan matakai, akwai kuma ginshiƙai a kowane gefe na madogaran. ");
INSERT INTO hausa_vpl VALUES ("EK41_1","027_41_1","EZK","41","1","1","Sai mutumin ya kawo ni wuri mai tsarki da yake waje ya kuma auna madogaransa; fāɗin gefe-gefen kamu shida ne a kowane gefe. ");
INSERT INTO hausa_vpl VALUES ("EK41_2","027_41_2","EZK","41","2","2","Faɗin ƙofar shiga kamu goma ne, fāɗin bangaye a kowane madogararta kamu biyar-biyar ne. Ya kuma auna wuri mai tsarkin da yake waje; tsawonsa kamu arba’in fāɗinsa kuma kamu ashirin. ");
INSERT INTO hausa_vpl VALUES ("EK41_3","027_41_3","EZK","41","3","3","Sa’an nan ya shiga wuri mai tsarki da yake can ciki ya auna madogarar ƙofar shigar; fāɗin kowanne kamu biyu ne. Faɗin ƙofar shigan kamu shida ne, fāɗin bangayen a kowane gefenta kamu bakwai-bakwai ne. ");
INSERT INTO hausa_vpl VALUES ("EK41_4","027_41_4","EZK","41","4","4","Ya kuma auna tsawon wuri mai tsarki da yake can ciki; tsawon kamu ashirin ne, fāɗinsa kuma kamu ashirin daga ƙurewa wuri mai tsarki da yake waje. Ya ce mini, “Wannan shi ne Wuri Mafi Tsarki.” ");
INSERT INTO hausa_vpl VALUES ("EK41_5","027_41_5","EZK","41","5","5","Sa’an nan ya auna bangon haikalin; kaurinsa kamu shida ne, kuma kowane ɗakin da yake a gefe kewaye da haikalin fāɗinsa kamu huɗu ne. ");
INSERT INTO hausa_vpl VALUES ("EK41_6","027_41_6","EZK","41","6","6","Ɗakunan da suke gefe masu hawa uku ne, wani bisa wani, guda talatin a kowane hawa. Akwai katanga kewaye da bangayen haikalin don ta tokare ɗakunan, domin ba a so ɗakunan su jingina da bangon haikalin. ");
INSERT INTO hausa_vpl VALUES ("EK41_7","027_41_7","EZK","41","7","7","Faɗin ɗakunan da suke gefe kewaye da haikalin ya yi ta ƙaruwa daga hawa zuwa hawa. Ginin da aka yi kewaye da haikalin ya yi ta ƙaruwa daga hawa zuwa hawa, don haka ɗakunan suka yi ta ƙara fāɗi yayinda suka ƙara bisa. Akwai mataki daga ɗaki na ƙasa zuwa ɗaki na bisa ta hanya hawa ɗaki na tsakiya. ");
INSERT INTO hausa_vpl VALUES ("EK41_8","027_41_8","EZK","41","8","8","Na ga cewa haikalin yana da ɗagaggen tushe kewaye da shi, wanda ya zama harsashin ɗakunan da suke gefe. Tsawonsa kara guda ne mai tsawon kamu shida. ");
INSERT INTO hausa_vpl VALUES ("EK41_9","027_41_9","EZK","41","9","9","Kaurin bangon waje na ɗakunan da suke gefe kamu biyar ne. Faɗin filin da yake tsakanin ɗakunan da suke gefen haikalin ");
INSERT INTO hausa_vpl VALUES ("EK41_10","027_41_10","EZK","41","10","10","da ɗakunan firistoci kamu ashirin ne kewaye da haikalin. ");
INSERT INTO hausa_vpl VALUES ("EK41_11","027_41_11","EZK","41","11","11","Akwai ƙofofin shiga daga fili, ɗaya a arewa ɗaya kuma a kudu; fāɗin tushen da ya yi kusa da filin kamu biyar ne kewaye. ");
INSERT INTO hausa_vpl VALUES ("EK41_12","027_41_12","EZK","41","12","12","Faɗin ginin da yake fuskantar filin haikali a wajen yamma kamu saba’in ne. Kaurin bangon ginin kamu biyar ne kewaye, tsawonsa kuma kamu tasa’in ne. ");
INSERT INTO hausa_vpl VALUES ("EK41_13","027_41_13","EZK","41","13","13","Sa’an nan ya auna haikalin; tsawonsa kamu ɗari ne, tsawon filin haikalin da ginin tare da bangayensa su ma kamu ɗari ne. ");
INSERT INTO hausa_vpl VALUES ("EK41_14","027_41_14","EZK","41","14","14","Faɗin filin haikalin a wajen gabas, haɗe da gaban haikalin, kamu ɗari ne. ");
INSERT INTO hausa_vpl VALUES ("EK41_15","027_41_15","EZK","41","15","15","Sa’an nan ya auna tsawon ginin da yake fuskantar filin a bayan haikalin, haɗe da rumfunansa a kowane gefe, kamu ɗari. Wuri mai tsarki da yake waje, wuri mai tsarki da yake can ciki da shirayin da yake fuskantar filin, ");
INSERT INTO hausa_vpl VALUES ("EK41_16","027_41_16","EZK","41","16","16","da madogaran ƙofa da matsattsun tagogi da rumfuna kewaye da su ukun, har da kome da yake gaba haɗe da madogarar ƙofa, an rufe su da katako. An rufe bangon haikalin daga ƙasa har zuwa tagogi, tagogin kuwa an rufe su. ");
INSERT INTO hausa_vpl VALUES ("EK41_17","027_41_17","EZK","41","17","17","A filin da yake bisan ƙofar shiga na waje zuwa wuri mai tsarki na can ciki da kuma a bangayen da aka daidaita tsakani kewaye da wuri mai tsarki na can ciki da kuma na can waje ");
INSERT INTO hausa_vpl VALUES ("EK41_18","027_41_18","EZK","41","18","18","an zāna siffofin kerubobi da na itatuwan dabino. Zānen siffar itacen dabino yana a tsakanin kerub da kerub. Kowane kerub yana da fuska biyu, ");
INSERT INTO hausa_vpl VALUES ("EK41_19","027_41_19","EZK","41","19","19","fuskar ɗaya kamar ta mutum tana fuskantar zānen siffar itacen dabino a wannan gefe, ɗaya fuskar kamar ta zaki tana fuskantar zānen siffar itacen dabino na wancan gefe. Haka aka zāna su dukan a jikin bangon haikalin kewaye. ");
INSERT INTO hausa_vpl VALUES ("EK41_20","027_41_20","EZK","41","20","20","Daga ƙasa zuwa daurin ƙofa, an zāna siffofin kerubobi da na itatuwan dabino a waje na wuri mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK41_21","027_41_21","EZK","41","21","21","Wuri mai tsarki da yake waje yana da madogarar ƙofa murabba’i, haka ma wadda take a gaban Wuri Mafi Tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK41_22","027_41_22","EZK","41","22","22","Akwai bagaden katako mai tsayi kamu uku, fāɗinsa kamu biyu da kuma tsawonsa kamu biyu; kusurwansa, tushensa da kuma gefe-gefensa duk katako ne. Sai mutumin ya ce mini, “Wannan shi ne tebur da yake a gaban Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("EK41_23","027_41_23","EZK","41","23","23","A wuri mai tsarki da yake waje da kuma Wuri Mafi Tsarki suna da ƙofa biyu a haɗe. ");
INSERT INTO hausa_vpl VALUES ("EK41_24","027_41_24","EZK","41","24","24","Kowace ƙofa tana da murfi biyu masu buɗewa ciki da waje. ");
INSERT INTO hausa_vpl VALUES ("EK41_25","027_41_25","EZK","41","25","25","A ƙofofin wuri mai tsarki da yake waje an zāna siffofin kerubobi da na itatuwan dabino kamar yadda aka zāna a bangayen, akwai kuma rumfar da aka yi da itace a gaban shirayin. ");
INSERT INTO hausa_vpl VALUES ("EK41_26","027_41_26","EZK","41","26","26","A bangayen da suke gefen shirayin akwai matsattsun tagogi da aka zāna siffar itatuwan dabino a kowane gefe. Gefe-gefen ɗakunan haikalin ma suna da rumfuna. ");
INSERT INTO hausa_vpl VALUES ("EK42_1","027_42_1","EZK","42","1","1","Sai mutumin ya kai ni wajen arewa zuwa cikin filin da yake waje ya kuma kawo ni ɗakunan da suke ɗaura da filin haikalin da yake a gefen arewa. ");
INSERT INTO hausa_vpl VALUES ("EK42_2","027_42_2","EZK","42","2","2","Tsawon ginin da yake fuskantar arewa kamu ɗari ne fāɗinsa kuma kamu hamsin. ");
INSERT INTO hausa_vpl VALUES ("EK42_3","027_42_3","EZK","42","3","3","A gaban kamu ashirin na filin da yake can ciki da kuma a gaban daɓen filin da yake waje, akwai rumfuna a jere waɗanda suke fuskantar juna hawa uku-uku. ");
INSERT INTO hausa_vpl VALUES ("EK42_4","027_42_4","EZK","42","4","4","A gaban ɗakunan akwai hanya a can ciki mai fāɗin kamu goma, tsawonta kuma kamu ɗari. Ƙofofinsu suna wajen arewa. ");
INSERT INTO hausa_vpl VALUES ("EK42_5","027_42_5","EZK","42","5","5","Ɗakunan da suke bisa ba su da fāɗi, gama mataki hawan benen ya cinye wuri fiye da a ɗakunan da suke a hawa na ƙasa da na tsakiya. ");
INSERT INTO hausa_vpl VALUES ("EK42_6","027_42_6","EZK","42","6","6","Ɗakunan da suke a hawa na uku ba su da ginshiƙai, yadda filayen suka kasance da su, saboda haka suka matsu fiye da waɗanda suke a hawa na ƙasa da na tsakiya. ");
INSERT INTO hausa_vpl VALUES ("EK42_7","027_42_7","EZK","42","7","7","Akwai katanga wadda take waje, wadda ta yi hannun riga da ɗakunan filin waje; ta miƙe a gaban ɗakunan, tsawonta kamu hamsin ne. ");
INSERT INTO hausa_vpl VALUES ("EK42_8","027_42_8","EZK","42","8","8","Yayinda tsawon jerin ɗakunan da suke a gefe kusa da filin da yake waje kamu hamsin ne, tsawon jerin ɗakunan da suke a gefen da yake kurkusa da wuri mai tsarki kamu ɗari ne. ");
INSERT INTO hausa_vpl VALUES ("EK42_9","027_42_9","EZK","42","9","9","Ɗakunan da suke can ƙasa suna da ƙofar shiga a wajen gabas in za a shiga cikinsu daga filin da yake waje. ");
INSERT INTO hausa_vpl VALUES ("EK42_10","027_42_10","EZK","42","10","10","A wajen kudu a ta katangar filin da yake waje, kusa da filin haikali da yake ɗaura da katangar waje, akwai ɗakuna ");
INSERT INTO hausa_vpl VALUES ("EK42_11","027_42_11","EZK","42","11","11","da hanya a gabansu. Waɗannan sun yi kama da ɗakunan da suke wajen arewa; tsawonsu da fāɗinsu duk iri ɗaya ne, da irin mafita ɗaya da kuma yadda aka shirya su. Sun yi kama da ƙofofin da suke wajen arewa ");
INSERT INTO hausa_vpl VALUES ("EK42_12","027_42_12","EZK","42","12","12","haka ma ƙofofin ɗakunan a wajen kudu. Akwai ƙofa a farkon hanyar da ta yi hannun riga da ɗayan katangar da ta miƙe wajen gabas, inda za a iya shiga ɗakunan. ");
INSERT INTO hausa_vpl VALUES ("EK42_13","027_42_13","EZK","42","13","13","Sai ya ce mini, “Ɗakunan arewa da na kudu waɗanda suke fuskantar filin haikali ɗakunan firistoci ne, inda firistocin da suke kusaci Ubangiji za su ci hadayu mafi tsarki. A can za su ajiye hadayu mafi tsarki, hadayu na gari, hadayu na zunubi da hadayu na laifi, gama wuri mai tsarki ne. ");
INSERT INTO hausa_vpl VALUES ("EK42_14","027_42_14","EZK","42","14","14","Da zarar firistoci suka shiga wuri mai tsarki, ba za su fita zuwa filin da yake waje ba sai sun tuɓe rigunan da suka yi hidima da su, gama waɗannan masu tsarki ne. Za su sa waɗansu riguna kafin su kusaci wuraren da mutane suke.” ");
INSERT INTO hausa_vpl VALUES ("EK42_15","027_42_15","EZK","42","15","15","Da ya gama auna filin da yake cikin haikali, sai ya fitar da ni ta ƙofar gabas ya auna dukan filin kewaye. ");
INSERT INTO hausa_vpl VALUES ("EK42_16","027_42_16","EZK","42","16","16","Ya auna gefen gabas da karan awo; ya samu kamu ɗari biyar. ");
INSERT INTO hausa_vpl VALUES ("EK42_17","027_42_17","EZK","42","17","17","Ya auna gefen arewa da karan awon; ya samu kamu ɗari biyar. ");
INSERT INTO hausa_vpl VALUES ("EK42_18","027_42_18","EZK","42","18","18","Ya auna gefen kudu da karan awon; ya samu kamu ɗari biyar. ");
INSERT INTO hausa_vpl VALUES ("EK42_19","027_42_19","EZK","42","19","19","Sa’an nan ya juya zuwa gefen yamma ya auna shi da karan awon, ya samu kamu ɗari biya. ");
INSERT INTO hausa_vpl VALUES ("EK42_20","027_42_20","EZK","42","20","20","Ta haka ya auna dukan kusurwoyi huɗu. Filin yana da katanga kewaye da shi, tsawon kamu ɗari biyar, fāɗin kuma kamu ɗari biyar don yă raba wuri mai tsarki daga wuri marar tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK43_1","027_43_1","EZK","43","1","1","Sai mutumin ya kawo ni ƙofar da take fuskantar gabas, ");
INSERT INTO hausa_vpl VALUES ("EK43_2","027_43_2","EZK","43","2","2","sai na ga ɗaukakar Allah na Isra’ila tana tahowa daga gabas. Muryarsa ta yi kamar rurin ruwaye masu gudu, ƙasa kuma ta haskaka da ɗaukakarsa. ");
INSERT INTO hausa_vpl VALUES ("EK43_3","027_43_3","EZK","43","3","3","Wahayin da na gani ya yi kamar wahayin da na gani sa’ad da ya zo don yă hallaka birnin, kamar kuma wahayin da na gani kusa da Kogin Kebar, na kuwa fāɗi rubda ciki. ");
INSERT INTO hausa_vpl VALUES ("EK43_4","027_43_4","EZK","43","4","4","Ɗaukakar Ubangiji ta shiga haikali ta ƙofar da take fuskantar gabas. ");
INSERT INTO hausa_vpl VALUES ("EK43_5","027_43_5","EZK","43","5","5","Sa’an nan Ruhu ya ɗaga ni sama ya kawo ni cikin fili na can ciki, ɗaukakar Ubangiji kuwa ta cika haikalin. ");
INSERT INTO hausa_vpl VALUES ("EK43_6","027_43_6","EZK","43","6","6","Yayinda mutumin yana tsaye kusa da ni, na ji wani yana magana da ni daga cikin haikalin. ");
INSERT INTO hausa_vpl VALUES ("EK43_7","027_43_7","EZK","43","7","7","Ya ce, “Ɗan mutum, wannan shi ne kursiyina da wurin tafin ƙafafuna. A nan ne zan zauna a cikin Isra’ilawa har abada. Gidan Isra’ila ba zai ƙara ɓata sunana mai tsarki ba, ko su ko sarakunansu, ta wurin karuwanci da gumakan da ba su da rai, sarakunansu a masujadan kan tudu. ");
INSERT INTO hausa_vpl VALUES ("EK43_8","027_43_8","EZK","43","8","8","Sa’ad da suka sa madogarar ƙofarsu kusa da madogarar ƙofata, da katanga kawai a tsakanina da su, sun ɓata sunana mai tsarki ta wurin ayyukansu masu banƙyama. Saboda haka na hallaka su cikin fushina. ");
INSERT INTO hausa_vpl VALUES ("EK43_9","027_43_9","EZK","43","9","9","Yanzu bari su kawar da karuwancinsu da gumakansu waɗanda ba su da rai na sarakunansu daga gabana, zan kuwa zauna a cikinsu har abada. ");
INSERT INTO hausa_vpl VALUES ("EK43_10","027_43_10","EZK","43","10","10","“Ɗan mutum, ka bayyana haikalin ga mutanen Isra’ila, don su ji kunya saboda zunubansu. Bari su yi la’akari da fasalin, ");
INSERT INTO hausa_vpl VALUES ("EK43_11","027_43_11","EZK","43","11","11","kuma in suka ji kunyar abubuwan da suka aikata, sai ka sanar musu fasalin haikalin da shirye-shiryensa, ƙofofinsa na shiga da fita, dukan fasalinsa da dukan ƙa’idodinsa da dokokinsa. Ka rubuta waɗannan a gabansu saboda su yi aminci da fasalinsa su kuma kiyaye dukan ƙa’idodinsa. ");
INSERT INTO hausa_vpl VALUES ("EK43_12","027_43_12","EZK","43","12","12","“Wannan ita ce dokar haikalin. Dukan filin da yake kewaye a kan dutsen, zai zama wuri mafi tsarki. Dokar haikalin ke nan. ");
INSERT INTO hausa_vpl VALUES ("EK43_13","027_43_13","EZK","43","13","13","“Waɗannan su ne aune-aunen bagade a tsawon kamu, wannan kamu shi ne kamun tafin hannu. Zurfin magudanar ruwansa kamu ɗaya ne fāɗinsa kuma kamu ɗaya, tare da da’ira kamun tafi ɗaya kewaye da gefensa. Wannan kuma shi ne tsayin bagaden. ");
INSERT INTO hausa_vpl VALUES ("EK43_14","027_43_14","EZK","43","14","14","Daga lambatun da yake a ƙasa har zuwa ƙaramin mahaɗin da yake ƙasa wanda ya kewaye bagade, tsayinsa kamu biyu ne, fāɗinsa kuma kamu guda. Daga ƙaramin mahaɗi zuwa babban mahaɗin wanda ya kewaye bagade, zai zama kamu huɗu, fāɗinsa kuwa kamu ɗaya. ");
INSERT INTO hausa_vpl VALUES ("EK43_15","027_43_15","EZK","43","15","15","Murhun bagaden kamu huɗu ne, akwai ƙahoni guda huɗu sun miƙe sama daga murhun. ");
INSERT INTO hausa_vpl VALUES ("EK43_16","027_43_16","EZK","43","16","16","Murhun bagaden murabba’i ne, tsawonsa kamu goma sha biyu, fāɗinsa kuma kamu goma sha biyu. ");
INSERT INTO hausa_vpl VALUES ("EK43_17","027_43_17","EZK","43","17","17","Gefen bisa ma murabba’i ne, tsawonsa kamu goma sha huɗu fāɗinsa kuma kamu goma huɗu, da da’ira da yake da fāɗin rabin kamu da magudanan ruwa kamu guda kewaye. Matakan bagaden suna fuskantar gabas.” ");
INSERT INTO hausa_vpl VALUES ("EK43_18","027_43_18","EZK","43","18","18","Sai ya ce mini, “Ɗan mutum, ga abin da Ubangiji Mai Iko Duka yana cewa waɗannan su ne za su zama ƙa’idodi don yin hadaya ta ƙonawa da yayyafawar jini a kan bagaden sa’ad da aka gina shi. ");
INSERT INTO hausa_vpl VALUES ("EK43_19","027_43_19","EZK","43","19","19","Za ka ba da ɗan bijimi a matsayin hadaya ta ƙonawa ga firistoci, waɗanda suke Lawiyawa, na iyalin Zadok, waɗanda suke zuwa kusa don hidima a gabana, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK43_20","027_43_20","EZK","43","20","20","Za ka ɗibi jininsa ka zuba shi a ƙahoni huɗu na bagaden a gefen bisa da kuma kewaye da da’irar, ta haka za ka tsarkake bagaden ka kuma yi kafara dominsa. ");
INSERT INTO hausa_vpl VALUES ("EK43_21","027_43_21","EZK","43","21","21","Za ka ɗauki bijimi na hadaya don zunubi ka ƙone shi a sashen da aka shirya na haikalin a wani wuri waje da wuri mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK43_22","027_43_22","EZK","43","22","22","“A rana ta biyu za ka miƙa bunsuru marar lahani domin hadaya don zunubi, za a kuma tsarkake bagaden yadda aka yi da bijimin. ");
INSERT INTO hausa_vpl VALUES ("EK43_23","027_43_23","EZK","43","23","23","Sa’ad da ka gama tsarkake shi, sai ka miƙa ɗan bijimi da kuma rago daga cikin garke, dukansu marasa lahani. ");
INSERT INTO hausa_vpl VALUES ("EK43_24","027_43_24","EZK","43","24","24","Za ka miƙa su a gaban Ubangiji, firistoci kuma za su barbaɗe gishiri a kansu su kuma miƙa su kamar hadaya ta ƙonawa ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK43_25","027_43_25","EZK","43","25","25","“Kwana bakwai za ka tanada bunsuru kullum domin hadaya don zunubi; za ka kuma tanada ɗan bijimi da rago daga garke, dukansu marasa lahani. ");
INSERT INTO hausa_vpl VALUES ("EK43_26","027_43_26","EZK","43","26","26","Kwana bakwai za su yi kafara saboda bagaden su kuma tsarkake shi; ta haka za su keɓe shi. ");
INSERT INTO hausa_vpl VALUES ("EK43_27","027_43_27","EZK","43","27","27","A ƙarshen waɗannan kwanaki, daga rana ta takwas zuwa gaba, firistoci za su miƙa hadayu na ƙonawa da hadayu na salama a kan bagade. Sa’an nan zan karɓe ku, in ji Ubangiji Mai Iko Duka.” ");
INSERT INTO hausa_vpl VALUES ("EK44_1","027_44_1","EZK","44","1","1","Sai mutumin ya komo da ni zuwa ƙofar waje na wuri mai tsarki, wadda take fuskantar gabas, tana kuwa a rufe. ");
INSERT INTO hausa_vpl VALUES ("EK44_2","027_44_2","EZK","44","2","2","Ubangiji ya ce mini, “Wannan ƙofar za tă kasance a rufe. Ba za a buɗe ta ba; ba wanda zai shiga ta wurinta. Za tă kasance a rufe domin Ubangiji, Allah na Isra’ila, ya shiga ta wurinta. ");
INSERT INTO hausa_vpl VALUES ("EK44_3","027_44_3","EZK","44","3","3","Sarki kansa ne kaɗai zai zauna a hanyar shiga don yă ci a gaban Ubangiji. Zai shiga ta hanyar shirayin hanyar shiga yă kuma fita a wannan hanya.” ");
INSERT INTO hausa_vpl VALUES ("EK44_4","027_44_4","EZK","44","4","4","Sa’an nan mutumin ya kawo ni ta hanyar ƙofar arewa zuwa gaban haikali. Na duba na kuma ga ɗaukakar Ubangiji tana cika haikalin Ubangiji, sai na fāɗi rubda ciki. ");
INSERT INTO hausa_vpl VALUES ("EK44_5","027_44_5","EZK","44","5","5","Ubangiji ya ce mini, “Ɗan mutum, ka lura sosai, ka saurara sosai ka kuma mai da hankali ga kome da na faɗa maka game da dukan ƙa’idodi game da haikalin Ubangiji. Ka lura sosai da ƙofar shigar haikali da kuma dukan ƙofofin wuri mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK44_6","027_44_6","EZK","44","6","6","Faɗa wa ’yan tawayen gidan Isra’ila, ‘Ga abin da Ubangiji Mai Iko Duka yana cewa ayyukan banƙyamarku sun isa haka, ya gidan Isra’ila! ");
INSERT INTO hausa_vpl VALUES ("EK44_7","027_44_7","EZK","44","7","7","Ban da dukan sauran ayyukanku na banƙyama, kun kawo baƙi marasa kaciya a zuciya da jiki a wurina mai tsarki, kun kuma ƙazantar da haikalina yayinda kuke miƙa mini abinci, kitse da kuma jini, kun kuma karya alkawarina. ");
INSERT INTO hausa_vpl VALUES ("EK44_8","027_44_8","EZK","44","8","8","A maimakon yin ayyukanku bisa ga abubuwana masu tsarki, kun sa waɗansu su lura da wurina mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK44_9","027_44_9","EZK","44","9","9","Ga abin da Ubangiji Mai Iko Duka yana cewa ba baƙo marar kaciya a zuciya da jiki da zai shiga wurina mai tsarki, kai, har ma da baƙin da suke zama a cikin Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK44_10","027_44_10","EZK","44","10","10","“ ‘Lawiyawan da suka yi nesa da ni sa’ad da Isra’ila suka kauce da kuma waɗanda suka karkata daga gare ni suka bi gumakansu, dole su ɗauki alhakin zunubinsu. ");
INSERT INTO hausa_vpl VALUES ("EK44_11","027_44_11","EZK","44","11","11","Za su iya yin hidima a wurina mai tsarki, suna lura da ƙofofin haikali suna kuma hidima a cikinsu; za su iya yankan hadayun ƙonawa da sadaka don mutane su kuma tsaya a gaban mutane su yi musu hidima. ");
INSERT INTO hausa_vpl VALUES ("EK44_12","027_44_12","EZK","44","12","12","Amma domin sun yi musu hidima a gaban gumakansu suka sa gidan Isra’ila ya yi zunubi, saboda haka na ɗaga hannu na rantse cewa dole su ɗauki alhakin zunubinsu, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK44_13","027_44_13","EZK","44","13","13","Ba za su yi kusa don su yi hidima kamar firistoci ko su zo kusa da abubuwana masu tsarki ko hadayuna mafi tsarki ba; dole su sha kunya saboda ayyukansu na banƙyama. ");
INSERT INTO hausa_vpl VALUES ("EK44_14","027_44_14","EZK","44","14","14","Duk da haka zan sa su su lura da ayyukan haikali da kuma dukan ayyukan da za a yi a cikinsa. ");
INSERT INTO hausa_vpl VALUES ("EK44_15","027_44_15","EZK","44","15","15","“ ‘Amma firistoci, waɗanda suke Lawiyawa kuma zuriyar Zadok waɗanda suka yi aminci ta wurin yin ayyukansu a wurina mai tsarki sa’ad da Isra’ilawa suka kauce daga gare ni, su ne za su zo kusa don hidima a gabana; za su tsaya a gabana don miƙa hadayun kitse da jini, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK44_16","027_44_16","EZK","44","16","16","Su ne kaɗai za su shiga wurina mai tsarki; su ne kaɗai za su zo kusa da teburina don yin hidima a gabana su kuma yi hidimata. ");
INSERT INTO hausa_vpl VALUES ("EK44_17","027_44_17","EZK","44","17","17","“ ‘Sa’ad da suka shiga ƙofofin fili na can ciki, dole su sa tufafin lilin; kada su sa wani rigar da aka yi da ulu yayinda suke hidima a ƙofofin fili na can ciki da cikin haikali. ");
INSERT INTO hausa_vpl VALUES ("EK44_18","027_44_18","EZK","44","18","18","Za su naɗa rawunan lilin a kawunansu, su kuma sa wandunan lilin. Kada su sa wani abin da zai sa su yi zuffa. ");
INSERT INTO hausa_vpl VALUES ("EK44_19","027_44_19","EZK","44","19","19","Sa’ad da suka fita daga haikali zuwa fili na waje inda mutane suke, sai su tuɓe rigunan da suka yi hidima da su su bar su a tsarkakan ɗakuna, su sa waɗansu riguna, don kada su tsarkake mutane ta wurin rigunansu. ");
INSERT INTO hausa_vpl VALUES ("EK44_20","027_44_20","EZK","44","20","20","“ ‘Ba za su aske kawunansu ko su bar gashin kansu ya yi tsayi ba, amma sai su sausaye gashin kansu. ");
INSERT INTO hausa_vpl VALUES ("EK44_21","027_44_21","EZK","44","21","21","Kada firist ya sha ruwan inabi sa’ad da zai shiga fili na can ciki. ");
INSERT INTO hausa_vpl VALUES ("EK44_22","027_44_22","EZK","44","22","22","Kada su auri gwauruwa ko macen da aka sāke; za su auri budurwai ne kaɗai na Isra’ilawa ko gwaurayen firistoci. ");
INSERT INTO hausa_vpl VALUES ("EK44_23","027_44_23","EZK","44","23","23","Za su koyar da mutanena bambanci tsakanin tsarki da rashin tsarki su kuma nuna musu yadda za su bambanta marar tsarki da mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK44_24","027_44_24","EZK","44","24","24","“ ‘A duk wani rashin jituwa, firistoci za su zama alƙalai su kuma yanke magana bisa ga farillaina. Za su kiyaye dokokina da ƙa’idodina a dukan ƙayyadaddun bukukkuwana, su kuma kiyaye Asabbataina da tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK44_25","027_44_25","EZK","44","25","25","“ ‘Firist ba zai ƙazantar da kansa ta wurin zuwa kusa da gawa ba; amma, in gawar mahaifinsa ko mahaifiyarsa, ko ɗansa ko ’yarsa, ko ɗan’uwansa ko ’yar’uwarsa ce, to, ba zai ƙazantar da kansa ba. ");
INSERT INTO hausa_vpl VALUES ("EK44_26","027_44_26","EZK","44","26","26","Bayan ya tsarkaka, dole yă jira har kwana bakwai. ");
INSERT INTO hausa_vpl VALUES ("EK44_27","027_44_27","EZK","44","27","27","A ranar da ya shiga fili na can ciki na wuri mai tsarki don hidima a wuri mai tsarki, zai miƙa hadaya don zunubi saboda kansa, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK44_28","027_44_28","EZK","44","28","28","“ ‘Ni ne kaɗai zan zama abin gādon da firistoci za su kasance da shi. Kada ka ba su wani mallaka a Isra’ila; zan zama mallakarsu. ");
INSERT INTO hausa_vpl VALUES ("EK44_29","027_44_29","EZK","44","29","29","Za su ci hadaya ta gari, hadaya don zunubi da hadaya don laifi; da kuma kowane keɓaɓɓen abu a Isra’ila da za a ba wa Ubangiji zai zama nasu. ");
INSERT INTO hausa_vpl VALUES ("EK44_30","027_44_30","EZK","44","30","30","Mafi kyau na nunan farinku da kuma dukan kyautanku na musamman za su zama na firistoci. Za ku ba su rabo na fari na ɓarzajjen hatsinku saboda albarka ta kasance a gidanku. ");
INSERT INTO hausa_vpl VALUES ("EK44_31","027_44_31","EZK","44","31","31","Firistoci ba za su ci mushen tsuntsu ko na dabba ba, ba kuwa za su ci waɗanda namun jeji suka kashe ba. ");
INSERT INTO hausa_vpl VALUES ("EK45_1","027_45_1","EZK","45","1","1","“ ‘Sa’ad da kuka rarraba ƙasar gādo, ku miƙa wa Ubangiji rabon ƙasar ya zama yanki mai tsarki, tsawonsa ya zama kamu 25,000 fāɗinsa kuma ya zama 20,000, dukan ƙasar za tă zama mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK45_2","027_45_2","EZK","45","2","2","Daga cikin wannan, sashe guda da yake murabba’i mai tsawo kamu 500 zai zama don wuri mai tsarki, kamu 50 kewaye da shi zai zama fili. ");
INSERT INTO hausa_vpl VALUES ("EK45_3","027_45_3","EZK","45","3","3","A cikin yanki mai tsarki, ka auna tsawo kamu 25,000 da kuma fāɗi kamu 10,000. A cikinsa wuri mai tsarki zai kasance, Wuri Mafi Tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK45_4","027_45_4","EZK","45","4","4","Zai zama tsattsarkan rabo na ƙasa domin firistoci, waɗanda za su yi hidima a cikin wuri mai tsarki da kuma waɗanda za su zo kusa don su yi hidima a gaban Ubangiji. Zai zama wuri don gidajensu ya kuma zama tsattsarkan wuri saboda wuri mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK45_5","027_45_5","EZK","45","5","5","Wani sashi kuma mai tsawo kamu 25,000 da fāɗi 10,000 zai zama na Lawiyawa, waɗanda suke hidima a cikin haikali, zai zama mallakarsu don su zauna a ciki. ");
INSERT INTO hausa_vpl VALUES ("EK45_6","027_45_6","EZK","45","6","6","“ ‘Za ka ba wa birnin fāɗin mallakarsa kamu 5,000, tsawonsa kuma 25,000, haɗe da tsattsarkan rabo; zai kasance na gidan Isra’ila duka. ");
INSERT INTO hausa_vpl VALUES ("EK45_7","027_45_7","EZK","45","7","7","“ ‘Sarki zai kasance da fili da ya yi iyaka da kowane gefe na yankin wuri mai tsarki da kuma mallakar birnin. Zai miƙe ya yi wajen yamma daga gefen yamma ya kuma yi wajen gabas daga gefen gabas, yana miƙewa a tsawo daga wajen yamma zuwa wajen gabashin iyaka don yă yi hannun riga da rabon kabilan. ");
INSERT INTO hausa_vpl VALUES ("EK45_8","027_45_8","EZK","45","8","8","Wannan fili zai zama mallakarsa a Isra’ila. Kuma sarakunana ba za su ƙara zaluntar mutanena ba amma za su bar gidan Isra’ila ya mallaki ƙasar bisa ga kabilansu. ");
INSERT INTO hausa_vpl VALUES ("EK45_9","027_45_9","EZK","45","9","9","“ ‘Ga abin da Ubangiji Mai Iko na ce ku sarakunan Isra’ila, danniya da zaluncin da kuke yi sun isa! Ku yi shari’a bisa ga gaskiya da adalci, ku bar korar mutanena, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK45_10","027_45_10","EZK","45","10","10","Ku yi amfani da garwan da yake daidai, efa da yake daidai da kuma garwa da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("EK45_11","027_45_11","EZK","45","11","11","Efa da garwan su kasance girmansu ɗaya, garwan ya zama kashi ɗaya bisa goma na ganga efa kuma ya zama kashi ɗaya bisa goma na ganga; ganga fitaccen ma’auni na duka biyu. ");
INSERT INTO hausa_vpl VALUES ("EK45_12","027_45_12","EZK","45","12","12","Shekel zai kasance da gera ashirin. Shekel ashirin a haɗa da shekel ashirin da biyar a haɗa da shekel goma sha biyar zai zama mina guda. ");
INSERT INTO hausa_vpl VALUES ("EK45_13","027_45_13","EZK","45","13","13","“ ‘Wannan ita ce bayarwa ta musamman da za ku miƙa, kashi ɗaya bisa shida na efa daga kowace gangan alkama da kashi ɗaya bisa shida na efa daga kowace gangan sha’ir. ");
INSERT INTO hausa_vpl VALUES ("EK45_14","027_45_14","EZK","45","14","14","Sashe na man da aka ƙayyade, da aka auna da garwa, kashi ɗaya bisa goma ne na garwa daga ganga (wanda yakan ci garwa goma, gama garwa goma suna daidai da ganga guda). ");
INSERT INTO hausa_vpl VALUES ("EK45_15","027_45_15","EZK","45","15","15","A kuma ba da tunkiya daga kowane garke mai tumaki ɗari biyu daga makiyaya da aka yi masa banruwa sosai na Isra’ila. Za a yi amfani da waɗannan don hadayun gari, hadayun ƙonawa da hadayun salama don yin kafara saboda mutane, in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK45_16","027_45_16","EZK","45","16","16","Dukan mutanen ƙasar za su yi wannan bayarwa ta musamman saboda amfanin sarki a Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK45_17","027_45_17","EZK","45","17","17","Zai zama hakkin sarki ne ya tanada hadayu na ƙonawa, hadayu na gari da hadayu na sha a bukukkuwa, Sabuwar Wata da Asabbatai, a duk ƙayyadaddun bukukkuwa na gidan Isra’ila. Zai tanada hadayu don zunubi, hadayu na gari, hadayu na ƙonawa da hadayu na salama don yin kafara saboda gidan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK45_18","027_45_18","EZK","45","18","18","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa a farkon wata a rana ta fari za ku ba da ɗan bijimi marar lahani a kuma tsarkake wuri mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("EK45_19","027_45_19","EZK","45","19","19","Firist zai ɗibi jinin hadaya don zunubi ya shafa a madogaran ƙofar haikali, a kusurwoyi huɗu na gefen bisa na bagade da kuma a kan madogaran ƙofar shiga na fili na can ciki. ");
INSERT INTO hausa_vpl VALUES ("EK45_20","027_45_20","EZK","45","20","20","Za ku yi haka kuma a rana ta bakwai ga watan domin duk wanda ya yi zunubai ba da gangan ba ko ta wurin rashin sani; saboda haka sai ku yi kafara domin haikalin. ");
INSERT INTO hausa_vpl VALUES ("EK45_21","027_45_21","EZK","45","21","21","“ ‘A wata na fari a rana ta goma sha huɗu za ku kiyaye Bikin Ƙetarewa, bikin da yakan ɗauki kwana bakwai, a lokacin ne za ku riƙa cin burodi marar yisti. ");
INSERT INTO hausa_vpl VALUES ("EK45_22","027_45_22","EZK","45","22","22","A wannan rana sarki zai tanada bijimi a matsayin hadaya don zunubi domin kansa da kuma domin dukan mutanen ƙasar. ");
INSERT INTO hausa_vpl VALUES ("EK45_23","027_45_23","EZK","45","23","23","Kowace rana a kwanaki bakwai na Bikin zai tanada bijimai guda bakwai da raguna bakwai marar lahani a matsayi hadaya ta ƙonawa ga Ubangiji, da kuma bunsuru saboda hadaya don zunubi. ");
INSERT INTO hausa_vpl VALUES ("EK45_24","027_45_24","EZK","45","24","24","Zai tanada efa na gari don kowane bijimi da kuma efa don kowane rago, tare da kwalabar mai don kowane efa guda. ");
INSERT INTO hausa_vpl VALUES ("EK45_25","027_45_25","EZK","45","25","25","“ ‘A lokacin kwana bakwai na Bikin, waɗanda za su fara a wata na bakwai a rana ta goma sha biyar, zai ba da abubuwan nan saboda hadayu don zunubi, hadayu na ƙonawa, hadayu na gari da kuma mai. ");
INSERT INTO hausa_vpl VALUES ("EK46_1","027_46_1","EZK","46","1","1","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa a rufe ƙofa ta fili na can cikin da take fuskantar gabas ranaku shida na aiki, amma a ranar Asabbaci da kuma a ranar ganin Sabuwar Wata a buɗe ta. ");
INSERT INTO hausa_vpl VALUES ("EK46_2","027_46_2","EZK","46","2","2","Sarki zai shiga daga waje ta shirayin hanyar shiga yă tsaya a madogarar ƙofa. Firistoci za su miƙa hadayarsa ta ƙonawa da hadayunsa na salama. Zai yi sujada a madogarar ƙofar hanyar shiga sa’an nan ya fita, amma ba za a rufe ƙofar ba sai da yamma. ");
INSERT INTO hausa_vpl VALUES ("EK46_3","027_46_3","EZK","46","3","3","A Asabbatai da kuma a Sabuwar Wata mutanen ƙasar za su yi sujada a gaban Ubangiji a mashigin wannan hanyar shiga. ");
INSERT INTO hausa_vpl VALUES ("EK46_4","027_46_4","EZK","46","4","4","Hadaya ta ƙonawar da sarki ya kawo wa Ubangiji a ranar Asabbaci ’yan raguna shida ne da rago guda, dukansu marasa lahani. ");
INSERT INTO hausa_vpl VALUES ("EK46_5","027_46_5","EZK","46","5","5","Hadayar garin da aka bayar tare da ragon efa guda ne, hadayar garin da ’yan ragunan yadda ya ga dama, tare da kwalabar mai don kowace efa. ");
INSERT INTO hausa_vpl VALUES ("EK46_6","027_46_6","EZK","46","6","6","A ranar Sabuwar Wata zai miƙa ɗan bijimi, ’yan raguna guda shida da kuma rago guda, dukansu marasa lahani. ");
INSERT INTO hausa_vpl VALUES ("EK46_7","027_46_7","EZK","46","7","7","Zai tanada a matsayin hadaya ta gari, efa guda tare da bijimi, efa guda tare da ’yan raguna, da kuma ’yan raguna yadda ya ga dama, tare da kwalabar mai don kowace efa. ");
INSERT INTO hausa_vpl VALUES ("EK46_8","027_46_8","EZK","46","8","8","Sa’ad da sarki zai shiga, zai shiga ta shirayin hanyar shiga, zai kuma fita ta nan. ");
INSERT INTO hausa_vpl VALUES ("EK46_9","027_46_9","EZK","46","9","9","“ ‘Sa’ad da mutanen ƙasar suka zo gaban Ubangiji a ƙayyadaddun bukukkuwa, duk wanda ya shiga ta ƙofar arewa don yă yi sujada sai ya fita ta ƙofar kudu; kuma duk wanda ya shiga ta ƙofar kudu sai ya fita ta ƙofar arewa. Ba wanda zai koma ta ƙofar da ya shiga, amma kowa zai fita a ƙofar ɗaura da wadda ya shiga. ");
INSERT INTO hausa_vpl VALUES ("EK46_10","027_46_10","EZK","46","10","10","Sarki zai kasance a cikinsu, zai shiga sa’ad da suke shiga ya kuma fita sa’ad da suka fita. ");
INSERT INTO hausa_vpl VALUES ("EK46_11","027_46_11","EZK","46","11","11","“ ‘A bukukkuwa da ƙayyadaddun bukukkuwa, hadaya ta gari zai zama efa tare da bijimi, efa da rago, da kuma ’yan raguna da ya ga dama, haɗe da kwalabar mai. ");
INSERT INTO hausa_vpl VALUES ("EK46_12","027_46_12","EZK","46","12","12","Sa’ad da sarki ya ba da hadaya ta yardar rai ga Ubangiji, ko hadaya ta ƙonawa ce ko hadayun salama ne, sai a buɗe masa ƙofar da take fuskantar gabas. Zai miƙa hadayarsa ta ƙonawa ko hadayarsa ta salama yadda yakan yi a ranar Asabbaci. Sa’an nan ya fita, bayan kuma ya fita, sai a rufe ƙofar. ");
INSERT INTO hausa_vpl VALUES ("EK46_13","027_46_13","EZK","46","13","13","“ ‘Kullum za ku tanada ɗan rago bana ɗaya marar lahani don hadaya ta ƙonawa ga Ubangiji; kowace safiya za ku tanada shi. ");
INSERT INTO hausa_vpl VALUES ("EK46_14","027_46_14","EZK","46","14","14","Tare da shi za ku tanada hadaya ta gari kowace safiya, da ya haɗa da kashi ɗaya bisa shida na efa tare da kashi ɗaya bisa uku na mai ga garin da aka cuɗa. Miƙawar wannan hadaya ta gari ga Ubangiji dawwammamiyar farilla ce. ");
INSERT INTO hausa_vpl VALUES ("EK46_15","027_46_15","EZK","46","15","15","Saboda haka za a tanada ɗan rago da hadaya ta gari da kuma mai kowace safiya don hadaya ta ƙonawa ta kullum. ");
INSERT INTO hausa_vpl VALUES ("EK46_16","027_46_16","EZK","46","16","16","“ ‘Ga abin da Ubangiji Mai Iko Duka yana cewa in sarkin ya ba wa ɗaya daga cikin ’ya’yansa kyauta daga gādonsa, zai kuwa zama na zuriyar; zai kuwa zama mallakarsu ta wurin gādo. ");
INSERT INTO hausa_vpl VALUES ("EK46_17","027_46_17","EZK","46","17","17","In kuma ya ba wa ɗaya daga cikin bayinsa kyauta daga gadonsa, bawan zai iya riƙe shi sai shekarar ’yantarwa; sa’an nan ya mayar wa sarkin. Gādon sarki na ’ya’yansa maza ne kaɗai; na su ne. ");
INSERT INTO hausa_vpl VALUES ("EK46_18","027_46_18","EZK","46","18","18","Kada sarki ya ƙwace gādon mutane, yana korinsu daga mallakarsu. Zai ba wa ’ya’yansa maza gādonsu daga cikin mallakarsa, don kada a raba wani daga mutanena da mallakarsa.’ ” ");
INSERT INTO hausa_vpl VALUES ("EK46_19","027_46_19","EZK","46","19","19","Sa’an nan mutumin ya fitar da ni ta ƙofar shiga a gefen ƙofar zuwa tsarkakakkun ɗakuna waɗanda suke fuskantar arewa, waɗanda suke na firistoci, ya kuma nuna mini wani wuri daga can ƙurewar yamma. ");
INSERT INTO hausa_vpl VALUES ("EK46_20","027_46_20","EZK","46","20","20","Ya ce mini, “Wannan shi ne wurin da firistoci za su dafa hadaya don laifi, da hadaya don zunubi, a nan ne kuma za su toya hadaya ta gari, domin kada su kai su a filin da yake waje, su tsarkake mutane.” ");
INSERT INTO hausa_vpl VALUES ("EK46_21","027_46_21","EZK","46","21","21","Sa’an nan ya kawo ni filin da yake waje ya kuma bi da ni kewaye da kusurwoyi huɗunsa, na kuma ga kowace kusurwa na wani fili. ");
INSERT INTO hausa_vpl VALUES ("EK46_22","027_46_22","EZK","46","22","22","A kusurwoyi huɗu na filin da yake waje akwai waɗansu filaye a haɗe, tsawonsu kamu arba’in fāɗinsu kuwa kamu talatin; kowane fili a kusurwoyi huɗun nan girmansu ɗaya ne. ");
INSERT INTO hausa_vpl VALUES ("EK46_23","027_46_23","EZK","46","23","23","Kewaye da cikin kowane filin huɗun nan akwai ginin dutse, da murhu da aka gina a kewaye a ƙarƙashin ginin. ");
INSERT INTO hausa_vpl VALUES ("EK46_24","027_46_24","EZK","46","24","24","Sai ya ce mini, “Waɗannan su ne ɗakunan dahuwa inda masu hidima a haikali za su dafa hadayun da jama’a.” ");
INSERT INTO hausa_vpl VALUES ("EK47_1","027_47_1","EZK","47","1","1","Mutumin ya komo da ni zuwa mashigin haikalin, sai na kuwa ga ruwa yana malalowa daga ƙarƙashin madogarar ƙofar haikalin wajen gabas (gama haikalin yana fuskantar gabas). Ruwan yana malalowa daga ƙarƙashin gefen kudun haikalin, kudu da bagaden. ");
INSERT INTO hausa_vpl VALUES ("EK47_2","027_47_2","EZK","47","2","2","Sai ya fitar da ni ta ƙofar arewa ya kewaye da ni ta waje zuwa ƙofar da take waje mai fuskantar gabas, ruwan kuwa yana malalowa daga wajen kudu. ");
INSERT INTO hausa_vpl VALUES ("EK47_3","027_47_3","EZK","47","3","3","Yayinda mutumin ya yi wajen gabas da karan awo a hannunsa, sai ya auna kamu dubu ya kuma bi da ni ta ruwan da zurfinsa ya kama ni a idon ƙafa. ");
INSERT INTO hausa_vpl VALUES ("EK47_4","027_47_4","EZK","47","4","4","Ya auna wani kamu dubu ya kuma bi da ni a ruwan da zurfinsa ya kai ni gwiwa. Ya sāke auna kamu dubu ya kuma bi da ni a ruwan da zurfinsa kama ni a gindi. ");
INSERT INTO hausa_vpl VALUES ("EK47_5","027_47_5","EZK","47","5","5","Ya auna wani kamu dubu, amma a yanzu ruwan ya zama kogin da ban iya hayewa ba, domin ruwan ya taso ya kuma yi zurfin da ya isa a yi iyo a ciki, kogin da ba za a iya hayewa ba. ");
INSERT INTO hausa_vpl VALUES ("EK47_6","027_47_6","EZK","47","6","6","Sai ya ce mini, “Ɗan mutum, ka ga wannan?” Sa’an nan ya komo da ni zuwa bakin kogin. ");
INSERT INTO hausa_vpl VALUES ("EK47_7","027_47_7","EZK","47","7","7","Sa’ad da na iso can, sai na ga itatuwa masu yawa a kowane gefen kogin. ");
INSERT INTO hausa_vpl VALUES ("EK47_8","027_47_8","EZK","47","8","8","Sai ya ce mini, “Wannan ruwa yana malalowa zuwa yankin gabas ya kuma gangaro zuwa cikin Araba, inda zai shiga Teku. Sa’ad da ya shiga cikin Tekun sai ruwan a can ya zama mai daɗi. ");
INSERT INTO hausa_vpl VALUES ("EK47_9","027_47_9","EZK","47","9","9","Tarin halittu masu rai za su rayu a duk inda ruwan ya malalo. Za a kasance da kifi masu yawa, domin wannan ruwa yana malalowa a can yana kuma mai da ruwan gishiri yă zama ruwa mai daɗi; saboda haka duk inda ruwan ya malalo, kome zai rayu. ");
INSERT INTO hausa_vpl VALUES ("EK47_10","027_47_10","EZK","47","10","10","Masunta za su tsaya a gaɓar; daga En Gedi zuwa En Eglayim, za a kasance da wuraren jefa abin kamun kifi. Za a sami kifayen iri-iri, kamar kifaye Bahar Rum. ");
INSERT INTO hausa_vpl VALUES ("EK47_11","027_47_11","EZK","47","11","11","Amma fadamun da tafkunan ba za su zama masu daɗi ba; za a bar su a gishirinsu. ");
INSERT INTO hausa_vpl VALUES ("EK47_12","027_47_12","EZK","47","12","12","’Ya’yan itatuwa na kowane iri za su yi girma a kowane gefen kogin. Ganyayensu ba su bushe ba, ba kuwa za su fasa yin ’ya’ya ba. Kowane wata za su ba da ’ya’ya domin ruwa daga wuri mai tsarki yana malalo musu. ’Ya’yansu za su zama abinci, ganyayensu kuma za su zama magani.” ");
INSERT INTO hausa_vpl VALUES ("EK47_13","027_47_13","EZK","47","13","13","Ga abin da Ubangiji Mai Iko Duka yana cewa, “Waɗannan su ne iyakokin da za ku raba ƙasar gādo cikin kabilan Isra’ila goma sha biyu, da rabo biyu don Yusuf. ");
INSERT INTO hausa_vpl VALUES ("EK47_14","027_47_14","EZK","47","14","14","Za ku raba ta daidai a cikinsu. Gama na ɗaga hannu na rantse zan ba da ita ga kakanninku, wannan ƙasa za tă zama gādonku. ");
INSERT INTO hausa_vpl VALUES ("EK47_15","027_47_15","EZK","47","15","15","“Wannan ce za tă zama iyakar ƙasa. “A wajen arewa za tă fara daga Bahar Rum ta hanyar Hetlon ta wuce Lebo Hamat zuwa Zedad, ");
INSERT INTO hausa_vpl VALUES ("EK47_16","027_47_16","EZK","47","16","16","Berota da Sibrayim (wadda take a iyaka tsakanin Damaskus da Hamat), har zuwa Hazer-Hattikon, wadda take a iyakar Hauran. ");
INSERT INTO hausa_vpl VALUES ("EK47_17","027_47_17","EZK","47","17","17","Iyakar za tă miƙe daga teku zuwa Hazar-Enon, ta iyakar Damaskus, da iyakar Hamat a arewa. Wannan ita ce iyakar a wajen arewa. ");
INSERT INTO hausa_vpl VALUES ("EK47_18","027_47_18","EZK","47","18","18","A wajen gabas iyakar za tă kama tsakanin Hauran da Damaskus, ta bi ta Urdun tsakanin Gileyad da ƙasar Isra’ila, zuwa tekun gabas har zuwa Tamar. Wannan ita ce iyakar a wajen gabas. ");
INSERT INTO hausa_vpl VALUES ("EK47_19","027_47_19","EZK","47","19","19","A wajen kudu za tă fara daga Tamar har zuwa ruwan Meriba Kadesh, sa’an nan ta bi Rafin Masar zuwa Bahar Rum. Wannan ita ce iyakar a wajen kudu. ");
INSERT INTO hausa_vpl VALUES ("EK47_20","027_47_20","EZK","47","20","20","A wajen yamma, Bahar Rum ne zai zama iyakar zuwa wani wuri ɗaura da Lebo Hamat. Wannan ita ce iyakar a wajen yamma. ");
INSERT INTO hausa_vpl VALUES ("EK47_21","027_47_21","EZK","47","21","21","“Za ku rarraba wannan ƙasa a tsakaninku bisa ga kabilan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK47_22","027_47_22","EZK","47","22","22","Za ku raba ta kamar gādo wa kanku da kuma wa baƙin da suka zauna a cikinku waɗanda suke da ’ya’ya. Za ku ɗauka su kamar ’yan ƙasa haifaffun Isra’ilawa; za su yi gādo tare da ku a cikin kabilan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK47_23","027_47_23","EZK","47","23","23","A duk kabilar da baƙon yake zama, a can za ku ba shi gādonsa,” in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK48_1","027_48_1","EZK","48","1","1","“Ga kabilan, a jere bisa ga sunayensu. “A iyaka ta arewa, Dan zai sami rabo; zai bi hanyar Hetlon zuwa Lebo Hamat. Hazar-Enan da iyakar arewancin Damaskus kusa da Hamat za tă zama sashen iyakarsa a wajen gabas zuwa wajen yamma. ");
INSERT INTO hausa_vpl VALUES ("EK48_2","027_48_2","EZK","48","2","2","Asher zai sami rabo; zai yi iyaka da yankin Dan daga gabas zuwa yamma. ");
INSERT INTO hausa_vpl VALUES ("EK48_3","027_48_3","EZK","48","3","3","Naftali zai sami rabo; zai yi iyaka da yankin Asher daga gabas zuwa yamma. ");
INSERT INTO hausa_vpl VALUES ("EK48_4","027_48_4","EZK","48","4","4","Manasse zai sami rabo; zai yi iyaka da yankin Naftali daga gabas zuwa yamma. ");
INSERT INTO hausa_vpl VALUES ("EK48_5","027_48_5","EZK","48","5","5","Efraim zai sami rabo; zai yi iyaka da yankin Manasse daga gabas zuwa yamma. ");
INSERT INTO hausa_vpl VALUES ("EK48_6","027_48_6","EZK","48","6","6","Ruben zai sami rabo; zai yi iyaka da Efraim daga gabas zuwa yamma. ");
INSERT INTO hausa_vpl VALUES ("EK48_7","027_48_7","EZK","48","7","7","Yahuda zai sami rabo; zai yi iyaka da yankin Ruben daga gabas zuwa yamma. ");
INSERT INTO hausa_vpl VALUES ("EK48_8","027_48_8","EZK","48","8","8","“Kusa da yankin Yahuda daga gabas zuwa yamma zai zama rabon da za ku bayar a matsayin kyauta ta musamman. Faɗinsa zai zama kamu 25,000, tsawonsa kuma zai zama daidai da tsawon yankunan kabilu daga gabas zuwa yamma; wuri mai tsarki zai kasance a tsakiyar wannan yanki. ");
INSERT INTO hausa_vpl VALUES ("EK48_9","027_48_9","EZK","48","9","9","“Tsawon rabo na musamman da za ku bayar ga Ubangiji zai zama kamu 25,000, fāɗinsa kuma kamu 10,000. ");
INSERT INTO hausa_vpl VALUES ("EK48_10","027_48_10","EZK","48","10","10","Wannan ne zai zama tsattsarkan rabo domin firistoci. Tsawon zai zama kamu 25,000 a wajen arewa, fāɗin kuma kamu 10,000 wajen yamma, kamu 10,000 zai zama fāɗinsa a wajen gabas, tsawonsa a wajen kudu zai zama kamu 25,000. A tsakiyarsa ne wuri mai tsarki na Ubangiji zai kasance. ");
INSERT INTO hausa_vpl VALUES ("EK48_11","027_48_11","EZK","48","11","11","Wannan zai zama na keɓaɓɓun firistoci, zuriyar Zadok, waɗanda suka yi aminci cikin hidimata ba su kuwa karkata kamar yadda Lawiyawa suka yi sa’ad da Isra’ilawa suka karkace ba. ");
INSERT INTO hausa_vpl VALUES ("EK48_12","027_48_12","EZK","48","12","12","Zai zama kyauta ta musamman a gare su daga tsattsarkan rabon ƙasar, kusa da yankin Lawiyawa. ");
INSERT INTO hausa_vpl VALUES ("EK48_13","027_48_13","EZK","48","13","13","“Dab da yankin firistoci, Lawiyawa za su sami rabo mai tsawon kamu 25,000, fāɗin kuma kamu 10,000. Tsawonsa gaba ɗaya zai zama kamu 25,000, fāɗinsa kuma kamu 10,000. ");
INSERT INTO hausa_vpl VALUES ("EK48_14","027_48_14","EZK","48","14","14","Ba za su sayar da shi ko su musayar da wani sashensa ba. Wannan shi ne mafi kyau na ƙasar ba kuma za a jinginar da ita ga wani ba, gama mai tsarki ce ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EK48_15","027_48_15","EZK","48","15","15","“Sauran wurin da ya rage mai fāɗin kamu 5,000 da tsawon kamu 25,000 zai zama don amfanin kowa a birnin, don gidaje da wurin kiwo. Birnin zai kasance a tsakiyar wurin da ya ragen nan ");
INSERT INTO hausa_vpl VALUES ("EK48_16","027_48_16","EZK","48","16","16","zai kuwa kasance da wannan awon, a wajen arewa kamu 45,000, wajen kudu kamu 45,000, wajen gabas kamu 45,000, wajen kudu kuma kamu 45,000. ");
INSERT INTO hausa_vpl VALUES ("EK48_17","027_48_17","EZK","48","17","17","Wurin kiwo don birnin zai zama kamu 250 a wajen arewa, kamu 250 a wajen kudu, kamu 250 a wajen gabas da kuma kamu 250 a wajen yamma. ");
INSERT INTO hausa_vpl VALUES ("EK48_18","027_48_18","EZK","48","18","18","Tsawon abin da ya rage a wurin, dab da tsattsarkan rabo, zai zama kamu 10,000 wajen gabas, kamu 10,000 kuma wajen yamma. Amfanin da zai bayar zai tanada abinci don ma’aikatan birnin. ");
INSERT INTO hausa_vpl VALUES ("EK48_19","027_48_19","EZK","48","19","19","Masu aiki daga birnin waɗanda suka nome ta za su fito daga dukan kabilan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("EK48_20","027_48_20","EZK","48","20","20","Dukan rabon zai zama murabba’i, kamu 25,000 kowane gefe. A matsayin kyauta ta musamman za ku keɓe tsattsarkan rabo, haka ma za ku yi da mallakar birnin. ");
INSERT INTO hausa_vpl VALUES ("EK48_21","027_48_21","EZK","48","21","21","“Abin da ya rage a kowane gefe na wurin zai zama tsattsarkan rabo kuma mallakar birnin za tă zama ta sarki. Zai miƙe wajen gabas daga kamu 25,000 na tsattsarkan rabo zuwa iyakar da take wajen gabashin iyaka, da kuma a wajen yamma kamu 25,000 zuwa iyakar da take a wajen yamma. Dukan wuraren nan da suke hannun riga da rabon kabilan zai zama na sarki, tsattsarkan rabon tare da wuri mai tsarkin za su kasance a tsakiyarsu. ");
INSERT INTO hausa_vpl VALUES ("EK48_22","027_48_22","EZK","48","22","22","Ta haka mallakar Lawiyawa da mallakar birnin za su kasance a tsakiyar wurin da yake na sarki. Wurin da yake na sarki zai kasance tsakanin iyakar Yahuda da iyakar Benyamin. ");
INSERT INTO hausa_vpl VALUES ("EK48_23","027_48_23","EZK","48","23","23","“Game da sauran kabilun kuwa, “Benyamin zai sami rabo; zai miƙe daga wajen gabas zuwa wajen yamma. ");
INSERT INTO hausa_vpl VALUES ("EK48_24","027_48_24","EZK","48","24","24","Simeyon zai sami rabo; zai yi iyaka da yankin Benyamin daga gabas zuwa yamma. ");
INSERT INTO hausa_vpl VALUES ("EK48_25","027_48_25","EZK","48","25","25","Issakar zai sami rabo; zai yi iyaka da yankin Simeyon daga gabas zuwa yamma. ");
INSERT INTO hausa_vpl VALUES ("EK48_26","027_48_26","EZK","48","26","26","Zebulun zai sami rabo; zai yi iyaka da yankin Issakar daga gabas zuwa yamma. ");
INSERT INTO hausa_vpl VALUES ("EK48_27","027_48_27","EZK","48","27","27","Gad zai sami rabo; zai yi iyaka da yankin Zebulun daga gabas zuwa yamma. ");
INSERT INTO hausa_vpl VALUES ("EK48_28","027_48_28","EZK","48","28","28","Iyakar kudu ta Gad za tă miƙe kudu daga Tamar zuwa ruwan Meriba Kadesh, sa’an nan ta bi Rafin Masar zuwa Bahar Rum. ");
INSERT INTO hausa_vpl VALUES ("EK48_29","027_48_29","EZK","48","29","29","“Wannan ce ƙasar da za ku raba gādo ga kabilan Isra’ila, kuma wannan ne zai zama rabonsu,” in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("EK48_30","027_48_30","EZK","48","30","30","“Waɗannan za su zama ƙofofin birnin. “Farawa da gefen arewa, wanda yake da tsawon kamu 4,500 ");
INSERT INTO hausa_vpl VALUES ("EK48_31","027_48_31","EZK","48","31","31","za a ba wa ƙofofin birnin sunaye kabilan Isra’ila. Ƙofofi uku a gefen arewa za su zama ƙofar Ruben, ƙofar Yahuda da ƙofar Lawi. ");
INSERT INTO hausa_vpl VALUES ("EK48_32","027_48_32","EZK","48","32","32","A gefen gabas, wanda yake da tsawon kamu 4,500 zai kasance da ƙofofi uku, ƙofar Yusuf, ƙofar Benyamin da ƙofar Dan. ");
INSERT INTO hausa_vpl VALUES ("EK48_33","027_48_33","EZK","48","33","33","A gefen kudu, wanda yake da tsawon kamu 4,500, zai kasance da ƙofofi uku, ƙofar Simeyon, ƙofar Issakar da ƙofar Zebulun. ");
INSERT INTO hausa_vpl VALUES ("EK48_34","027_48_34","EZK","48","34","34","A gefen yamma, wanda yake da tsawon kamun 4,500, zai kasance da ƙofofi uku, ƙofar Gad, ƙofar Asher da kuma ƙofar Naftali. ");
INSERT INTO hausa_vpl VALUES ("EK48_35","027_48_35","EZK","48","35","35","“Duk nisan wurare kewaye da birnin zai zama kamu 18,000 ne. “Sunan birnin kuwa daga wannan lokaci zai zama, ‘Ubangiji yana a nan.’ ”");
INSERT INTO hausa_vpl VALUES ("DN1_1","028_1_1","DAN","1","1","1","A Shekara ta uku ta mulki Yehohiyakim sarkin Yahuda, Nebukadnezzar sarkin Babilon ya zo Urushalima ya kuma yi mata ƙawanya. ");
INSERT INTO hausa_vpl VALUES ("DN1_2","028_1_2","DAN","1","2","2","Sai Ubangiji ya bashe Yehohiyakim sarkin Yahuda a hannunsa, tare da waɗansu kayayyakin haikalin Allah. Ya ɗauki waɗannan kayan zuwa cikin haikalin allahnsa a Babilon cikin ma’ajin gidan allahnsa. ");
INSERT INTO hausa_vpl VALUES ("DN1_3","028_1_3","DAN","1","3","3","Sa’an nan sarkin ya umarci Ashfenaz, shugaban fadarsa yă kawo waɗansu daga cikin Isra’ilawan da suka fito daga gidan sarauta da kuma na fitattun mutane. ");
INSERT INTO hausa_vpl VALUES ("DN1_4","028_1_4","DAN","1","4","4","Matasa maza waɗanda ba su da wata naƙasa kuma kyawawa, hazikai ta kowace hanyar koyo, sanannu, masu saurin fahimtar abu, da kuma waɗanda suka cancanci su yi aiki a fadar sarki. Zai koya musu harshen Babiloniyawa da kuma littattafansu. ");
INSERT INTO hausa_vpl VALUES ("DN1_5","028_1_5","DAN","1","5","5","Sarki kuma ya sa a ba su abinci da ruwan inabi kowace rana daga cikin abincin sarki. Za a koyar da su har shekaru uku, bayan haka kuma su shiga yin wa sarki hidima. ");
INSERT INTO hausa_vpl VALUES ("DN1_6","028_1_6","DAN","1","6","6","Daga cikin waɗannan da aka zaɓa akwai waɗansu daga Yahuda, Daniyel, Hananiya, Mishayel da kuma Azariya. ");
INSERT INTO hausa_vpl VALUES ("DN1_7","028_1_7","DAN","1","7","7","Sai sarkin fada ya raɗa musu sababbin sunaye, ga Daniyel ya raɗa masa Belteshazar; ga Hananiya ya raɗa masa Shadrak; ga Mishayel ya raɗa masa Meshak; ga Azariya kuma ya raɗa masa Abednego. ");
INSERT INTO hausa_vpl VALUES ("DN1_8","028_1_8","DAN","1","8","8","Amma Daniyel ya ƙudura a zuciyarsa ba zai ƙazantar da kansa da abinci da ruwan inabin sarki ba, sai ya tambayi sarkin fada don a ba shi izinin kada yă ƙazantar da kansa ta wannan hanya. ");
INSERT INTO hausa_vpl VALUES ("DN1_9","028_1_9","DAN","1","9","9","Sai Allah ya sa sarkin fada ya nuna masa tagomashi ya kuma ƙaunaci Daniyel, ");
INSERT INTO hausa_vpl VALUES ("DN1_10","028_1_10","DAN","1","10","10","amma sai sarkin fada ya ce wa Daniyel, “Ina jin tsoron ranka yă daɗe, sarkina wanda ya sa a ba ku abinci da ruwan inabi. Me zai sa yă ga kuna ramewa fiye da sauran samari, tsaranku? Sarki zai sa a fille mini kai saboda ku.” ");
INSERT INTO hausa_vpl VALUES ("DN1_11","028_1_11","DAN","1","11","11","Sai Daniyel ya ce wa mai gadi wanda sarkin fada ya sa yă kula da Daniyel, Hananiya, Mishayel da Azariya, ");
INSERT INTO hausa_vpl VALUES ("DN1_12","028_1_12","DAN","1","12","12","“Ina roƙonka ka gwada bayinka kwana goma. Kada ka ba mu kome sai kayan lambu mu ci da kuma baƙin ruwa mu sha. ");
INSERT INTO hausa_vpl VALUES ("DN1_13","028_1_13","DAN","1","13","13","Sa’an nan sai ka dubi fuskokinmu da na sauran samarin da suke ci daga abincin sarki; sa’an nan ka yi da bayinka bisa ga abin da ka gani.” ");
INSERT INTO hausa_vpl VALUES ("DN1_14","028_1_14","DAN","1","14","14","Sai ya amince da haka ya kuma gwada su har kwana goma. ");
INSERT INTO hausa_vpl VALUES ("DN1_15","028_1_15","DAN","1","15","15","A ƙarshen kwana goma sai aka ga fuskokinsu suna sheƙi, sun kuma yi ƙiba fiye da samarin da suke cin abinci irin na sarki. ");
INSERT INTO hausa_vpl VALUES ("DN1_16","028_1_16","DAN","1","16","16","Sai mai gadinsu ya janye abinci da ruwan inabi irin na sarki, ya ci gaba da ba su kayan lambu. ");
INSERT INTO hausa_vpl VALUES ("DN1_17","028_1_17","DAN","1","17","17","Ga samarin nan guda huɗu Allah ya ba su sani da ganewar dukan irin littattafai da kuma koyarwa. Daniyel kuma ya iya gane wahayi da kowane irin mafarki. ");
INSERT INTO hausa_vpl VALUES ("DN1_18","028_1_18","DAN","1","18","18","A ƙarshen lokacin da sarki ya sa da za a kawo su ciki, sai sarkin fada ya gabatar da su ga Nebukadnezzar. ");
INSERT INTO hausa_vpl VALUES ("DN1_19","028_1_19","DAN","1","19","19","Sarki kuwa ya yi magana da su, sai ya gano cewa babu wani kamar Daniyel, Hananiya, Mishayel da kuma Azariya; don haka sai suka shiga yi wa sarki hidima. ");
INSERT INTO hausa_vpl VALUES ("DN1_20","028_1_20","DAN","1","20","20","A dukan al’amuran hikima da na fahimta wanda sarki ya tambaye su, ya tarar sun fi dukan masu sihiri da bokaye waɗanda suke cikin mulkinsa sau goma. ");
INSERT INTO hausa_vpl VALUES ("DN1_21","028_1_21","DAN","1","21","21","Daniyel kuwa ya kasance a nan har shekara ta farko ta mulkin sarki Sairus. ");
INSERT INTO hausa_vpl VALUES ("DN2_1","028_2_1","DAN","2","1","1","A shekara ta biyu ta mulkinsa, Nebukadnezzar ya yi mafarkai; hankalinsa ya tashi har ya kāsa barci. ");
INSERT INTO hausa_vpl VALUES ("DN2_2","028_2_2","DAN","2","2","2","Sai sarki ya sa aka tattara masa masu sihiri da masu dabo da bokaye da masanan taurari domin su faɗi abin da ya yi mafarki a kai. Da suka shigo suka tsaya a gaban sarki, ");
INSERT INTO hausa_vpl VALUES ("DN2_3","028_2_3","DAN","2","3","3","sai ya ce musu, “Na yi mafarkin da ya dame ni kuma ina so in san me yake nufi.” ");
INSERT INTO hausa_vpl VALUES ("DN2_4","028_2_4","DAN","2","4","4","Sai masanan taurarin suka amsa wa sarki da Arameyanci “Ran sarki yă daɗe! Ka faɗa wa bayinka mafarkin, mu kuma sai mu fassara.” ");
INSERT INTO hausa_vpl VALUES ("DN2_5","028_2_5","DAN","2","5","5","Sai sarki ya amsa wa masanan taurarin ya ce, “Na mance da abin, idan ba ku tuno mini mafarkin, duk da fassararsa ba, to, za a daddatse ku gunduwa-gunduwa, a mai da gidajenku juji. ");
INSERT INTO hausa_vpl VALUES ("DN2_6","028_2_6","DAN","2","6","6","Amma in har kuka faɗa mini mafarkina kuka kuma bayyana fassararsa, za ku sami lada mai girma. Saboda haka ku faɗa mini mafarkin da kuma fassararsa.” ");
INSERT INTO hausa_vpl VALUES ("DN2_7","028_2_7","DAN","2","7","7","Sai suka sāke amsa masa suka ce, “Ran sarki yă daɗe, faɗa wa bayinka mafarkin, mu kuma za mu fassara shi.” ");
INSERT INTO hausa_vpl VALUES ("DN2_8","028_2_8","DAN","2","8","8","Sai sarki ya amsa ya ce, “Na gane cewa kuna ƙoƙari ku ɓata lokaci ne kawai domin ku ga na manta da abin. ");
INSERT INTO hausa_vpl VALUES ("DN2_9","028_2_9","DAN","2","9","9","In ba ku faɗa mini mafarkin ba, akwai hukunci guda ɗaya kurum dominku. Kun haɗa baki domin ku faɗa mini munanan al’amura domin ku ruɗe ni har lokaci yă wuce. Sai ku faɗa mini mafarkin, ta haka kuwa zan sani za ku iya yi mini fassararsa.” ");
INSERT INTO hausa_vpl VALUES ("DN2_10","028_2_10","DAN","2","10","10","Sai masanan taurarin suka amsa wa sarki suka ce, “Babu wani mutum a duniyan nan da zai iya yin abin da sarki yake nema! Babu wani sarki mai daraja da girma wanda ya taɓa yin irin wannan tambaya ga masu sihiri ko masu dabo ko masanan taurari. ");
INSERT INTO hausa_vpl VALUES ("DN2_11","028_2_11","DAN","2","11","11","Abin da sarki yake nema yana da wuya matuƙa. Babu wani da zai iya bayyana wannan ga sarki sai dai alloli; kuma ba su zama tare da ’yan adam.” ");
INSERT INTO hausa_vpl VALUES ("DN2_12","028_2_12","DAN","2","12","12","Wannan ya sa sarki ya fusata ƙwarai, ya ba da umarni a tafi da dukan masu hikima na Babilon a kashe su. ");
INSERT INTO hausa_vpl VALUES ("DN2_13","028_2_13","DAN","2","13","13","Sai aka ba da dokar da za a kashe masu hikima, sa’an nan aka aika mutane su je su nemo Daniyel da abokansa domin a kashe su. ");
INSERT INTO hausa_vpl VALUES ("DN2_14","028_2_14","DAN","2","14","14","Sa’ad da Ariyok, shugaban ƙungiyar matsaran sarki, ya fita domin yă kashe masu hikima na Babilon, sai Daniyel ya yi masa magana cikin hikima da dabara. ");
INSERT INTO hausa_vpl VALUES ("DN2_15","028_2_15","DAN","2","15","15","Ya tambayi mai tsaro na sarki, “Me ya sa sarki ya fitar da wannan doka haka da fushi?” Sai Ariyok ya yi wa Daniyel bayanin batun. ");
INSERT INTO hausa_vpl VALUES ("DN2_16","028_2_16","DAN","2","16","16","Da jin haka sai Daniyel ya tafi wurin sarki ya nemi ƙarin lokaci, domin yă bayyana wa sarki mafarkin da kuma fassararsa. ");
INSERT INTO hausa_vpl VALUES ("DN2_17","028_2_17","DAN","2","17","17","Sa’an nan Daniyel ya komo gida ya kuma sanar wa abokansa Hananiya, Mishayel da Azariya, batun nan duka. ");
INSERT INTO hausa_vpl VALUES ("DN2_18","028_2_18","DAN","2","18","18","Ya roƙe su su roƙi jinƙan Allah na sama domin wannan mafarki, saboda kada a kashe shi da abokansa tare da sauran masu hikima na Babilon. ");
INSERT INTO hausa_vpl VALUES ("DN2_19","028_2_19","DAN","2","19","19","A wannan dare sai aka bayyana wa Daniyel mafarkin cikin wahayi. Daniyel kuwa ya ɗaukaka Allah na sama. ");
INSERT INTO hausa_vpl VALUES ("DN2_20","028_2_20","DAN","2","20","20","Ya ce, “Yabo ya tabbata ga sunan Allah har abada abadin; hikima da iko nasa ne. ");
INSERT INTO hausa_vpl VALUES ("DN2_21","028_2_21","DAN","2","21","21","Yana sāke lokuta, yana tuɓe sarakuna yana kuma naɗa waɗansu. Yana ba da hikima ga masu hikima kuma ilimi ga masu basira. ");
INSERT INTO hausa_vpl VALUES ("DN2_22","028_2_22","DAN","2","22","22","Yakan bayyana zurfafa da ɓoyayyun abubuwa; ya san abin da yake cikin dare, haske kuwa yana zaune tare da shi. ");
INSERT INTO hausa_vpl VALUES ("DN2_23","028_2_23","DAN","2","23","23","Na gode maka ina yabonka, Allah na kakannina. Kai ka san hikima da iko, ka sanar da ni abin da muka tambaye ka, ka kuma sanar da mu mafarkin sarki.” ");
INSERT INTO hausa_vpl VALUES ("DN2_24","028_2_24","DAN","2","24","24","Sai Daniyel ya tafi wurin Ariyok, wanda sarki ya sa yă kashe masu hikiman Babilon, ya kuma ce masa, “Kada ka kashe masu hikiman Babilon ka kai ni wurin sarki, ni kuma zan fassara masa mafarkinsa.” ");
INSERT INTO hausa_vpl VALUES ("DN2_25","028_2_25","DAN","2","25","25","Sai Ariyok ya kai Daniyel wurin sarki nan take ya ce masa, “Na gano wani mutum daga cikin kamammun kabilar Yahuda wanda zai faɗa wa sarki abin da mafarkin yake nufi.” ");
INSERT INTO hausa_vpl VALUES ("DN2_26","028_2_26","DAN","2","26","26","Sarki ya tambayi Daniyel (wanda ake kira Belteshazar), za ka iya faɗa mini mafarkin da na yi ka kuma fassara shi? ");
INSERT INTO hausa_vpl VALUES ("DN2_27","028_2_27","DAN","2","27","27","Daniyel ya amsa, “Babu wani mai hikima, ko mai sihiri, ko mai dabo ko mai duban da zai iya warware wa sarki wannan matsala da ta dame shi, ");
INSERT INTO hausa_vpl VALUES ("DN2_28","028_2_28","DAN","2","28","28","amma akwai Allahn da yake a sama wanda yake bayyana asirai, ya nuna wa sarki Nebukadnezzar abin da zai faru a kwanaki masu zuwa. Mafarkinka da wahayin da ya wuce cikin tunaninka a sa’ad da kake kwance a gadonka su ne, ");
INSERT INTO hausa_vpl VALUES ("DN2_29","028_2_29","DAN","2","29","29","“A sa’ad da kake kwance, ya sarki, tunaninka ya ga al’amuran da suke zuwa, kuma shi mai bayyana al’amuran ya bayyana maka asiran abubuwan da za su faru. ");
INSERT INTO hausa_vpl VALUES ("DN2_30","028_2_30","DAN","2","30","30","Amma ba a bayyana mini wannan asiri saboda ina da wata hikima fiye da sauran mutane ba, sai dai domin a sanar wa sarki da fassarar, ka kuma san tunanin da ya shiga zuciyarka. ");
INSERT INTO hausa_vpl VALUES ("DN2_31","028_2_31","DAN","2","31","31","“Ya sarki, ka ga wata babbar siffa, mai girma, siffa ce mai haske, abar bantsoro tana tsaye a gabanka. ");
INSERT INTO hausa_vpl VALUES ("DN2_32","028_2_32","DAN","2","32","32","An yi kan wannan siffa da zinariya zalla, ƙirjinta da kuma hannuwanta an yi su da azurfa, cikinta da kuma cinyarta da tagulla ne. ");
INSERT INTO hausa_vpl VALUES ("DN2_33","028_2_33","DAN","2","33","33","An yi ƙafafun da ƙarfe, tafin ƙafafunta kuma an yi rabi da ƙarfe rabi kuma da yumɓu. ");
INSERT INTO hausa_vpl VALUES ("DN2_34","028_2_34","DAN","2","34","34","A lokacin da kake dubawa, sai aka yanko wani dutse, amma ba da hannun mutum ba. Ya fāɗa a kan ƙafafun siffar na ƙarfen da aka haɗa da yumɓu aka kuma ragargaje su. ");
INSERT INTO hausa_vpl VALUES ("DN2_35","028_2_35","DAN","2","35","35","Sai ƙarfen da yambun da tagulla da azurfan da kuma zinariyan suka ragargaje a lokaci ɗaya ya zama kamar ƙaiƙayi a masussuka a lokacin kaka. Sai iska ta kwashe su ta tafi, har ba a iya ganin ko alamarsu. Amma dutsen da ya fāɗo a siffar ya girke ya zama tsauni ya kuma cika dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("DN2_36","028_2_36","DAN","2","36","36","“Wannan shi ne mafarkin, yanzu kuma za mu fassara ta wa sarki. ");
INSERT INTO hausa_vpl VALUES ("DN2_37","028_2_37","DAN","2","37","37","Ya, sarki, kai ne sarkin sarakuna. Allah na sama ya ba ka iko da girma da suna; ");
INSERT INTO hausa_vpl VALUES ("DN2_38","028_2_38","DAN","2","38","38","a cikin hannunka ya sanya ɗan adam, da namun jeji da tsuntsayen sama. A duk inda suke zaune, ya maishe ka ka yi mulki a bisansu kai ne kan zinariyan nan na siffar. ");
INSERT INTO hausa_vpl VALUES ("DN2_39","028_2_39","DAN","2","39","39","“A bayanka, za a yi wani mulki, wanda bai kai naka ba. A gaba kuma, za a yi mulki na uku wanda yake na tagulla, zai yi mulkin dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("DN2_40","028_2_40","DAN","2","40","40","A ƙarshe, za a yi mulki na huɗu, mai ƙarfi kamar ƙarfe, Da yake baƙin ƙarfe yakan kakkarya, ya ragargaje abubuwa, haka nan wannan mulki zai ragargaje sauran mulkoki ");
INSERT INTO hausa_vpl VALUES ("DN2_41","028_2_41","DAN","2","41","41","Ka kuma ga an yi ƙafafun da yatsotsin da baƙin ƙarfe gauraye da yumɓu, wato, mulkin zai rabu, amma zai kasance da ƙarfi kamar na baƙin ƙarfe da yake gauraye da yumɓu. ");
INSERT INTO hausa_vpl VALUES ("DN2_42","028_2_42","DAN","2","42","42","Kamar yadda yatsotsin rabi na ƙarfe rabi kuma na yumɓu ne, haka wannan mulki zai zama rabi mai ƙarfi rabi kuma marar ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("DN2_43","028_2_43","DAN","2","43","43","Kamar dai yadda ka ga ƙarfen ya gauraye da yumɓu, haka mutanen za su zama a gauraye amma ba za su haɗu da juna ba, kamar yadda baƙin ƙarfe da yumɓu ba su haɗuwa. ");
INSERT INTO hausa_vpl VALUES ("DN2_44","028_2_44","DAN","2","44","44","“A lokacin mulkin waɗannan sarakunan, Allah na sama zai kafa mulki da ba zai taɓa rushewa ba, ba kuma za a ba ma waɗansu mutane ba. Zai ragargaje waɗannan mulkokin da kuma kawo su ga ƙarshe, amma shi wannan mulki zai dawwama har abada. ");
INSERT INTO hausa_vpl VALUES ("DN2_45","028_2_45","DAN","2","45","45","Wannan shi ne ma’anar wannan wahayin da ka gani na dutsen da aka yanko daga jikin tsaunin, amma ba da hannun ɗan adam ba, dutsen da ya ragargaza ƙarfen, da tagullar, da yumɓun da azurfar da kuma zinariyar. “Allah mai girma ya nuna wa sarki abin da zai faru nan gaba. Mafarkin gaskiya ne, fassararsa kuma abin dogara ne.” ");
INSERT INTO hausa_vpl VALUES ("DN2_46","028_2_46","DAN","2","46","46","Sai sarki Nebukadnezzar ya fāɗi da fuskarsa har ƙasa a gaban Daniyel domin ya girmama shi ya kuma umarta a miƙa hadaya da kuma hadayar ƙonawa ta turare ga Daniyel. ");
INSERT INTO hausa_vpl VALUES ("DN2_47","028_2_47","DAN","2","47","47","Sarki ya kuma ce wa Daniyel, “Tabbatacce Allahnka shi ne Allahn alloli da kuma Sarkin sarakuna da mai bayyana asirai, gama ka iya bayyana wannan asiri.” ");
INSERT INTO hausa_vpl VALUES ("DN2_48","028_2_48","DAN","2","48","48","Sai sarki ya ɗora Daniyel a babban matsayi ya kuma sanya shi mai mulki a kan dukan yankin ƙasar Babilon; ya kuma ɗora shi yă zama mai kula da duk masu hikima. ");
INSERT INTO hausa_vpl VALUES ("DN2_49","028_2_49","DAN","2","49","49","Bugu da ƙari, bisa ga bukatar Daniyel sai sarki yă naɗa Shadrak da Meshak da Abednego su zama masu kula da harkokin lardin Babilon, amma Daniyel kuma ya tsaya a fadar sarki. ");
INSERT INTO hausa_vpl VALUES ("DN3_1","028_3_1","DAN","3","1","1","Sarki Nebukadnezzar ya yi gunkin zinariya, tsawonsa kamu tasa’in, fāɗinsa kuma kamu tara ne, ya kafa shi a filin Dura a yankin Babilon. ");
INSERT INTO hausa_vpl VALUES ("DN3_2","028_3_2","DAN","3","2","2","Sa’an nan ya aika a kira hakimai da wakilai da gwamnoni da mashawarta, da ma’aji, da alƙalai, da marubutan kotu, da dukan sauran ma’aikatan yankunan, suka hallara domin a rusuna wa wannan siffar da ya kafa. ");
INSERT INTO hausa_vpl VALUES ("DN3_3","028_3_3","DAN","3","3","3","Saboda haka sai hakimai, da wakilai da gwamnoni, mashawarta da ma’aji da alƙalai, da marubutan alƙalai, da kuma dukan ma’aikatan yankunan suka tattaru domin kaddamar da siffar da Nebukadnezzar ya kafa, suka kuma tsaya a gabansa. ");
INSERT INTO hausa_vpl VALUES ("DN3_4","028_3_4","DAN","3","4","4","Sai mai shela ya daga murya da ƙarfi ya ce, “Wannan shi ne abin da aka umarce ku ku yi, ya ku mutane da al’umma da kowane yare. ");
INSERT INTO hausa_vpl VALUES ("DN3_5","028_3_5","DAN","3","5","5","Da zarar kuka ji karar ƙaho, da sarewa, da garaya da goge da molo da algaita da kowane irin kaɗe-kaɗe da bushe-bushe ku rusuna ku yi sujada ga wannan gunkin da sarki Nebukadnezzar ya kafa. ");
INSERT INTO hausa_vpl VALUES ("DN3_6","028_3_6","DAN","3","6","6","Duk wanda bai rusuna ya yi sujada ba, nan take za a jefa shi a cikin tendarun wuta.” ");
INSERT INTO hausa_vpl VALUES ("DN3_7","028_3_7","DAN","3","7","7","Saboda haka, da zarar suka ji karar ƙaho, da sarewa, garaya da goge da kowane irin kaɗe-kaɗe da bushe-bushe da kowane irin kaɗe-kaɗe kowane mutum da ko wace al’umma da kowane irin yare suka sunkuya suka yi sujada ga wannan siffa ta zinariya da sarki Nebukadnezzar ya kafa. ");
INSERT INTO hausa_vpl VALUES ("DN3_8","028_3_8","DAN","3","8","8","A wannan lokaci sai waɗansu masanan taurari suka zo gaba suka yi karar Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("DN3_9","028_3_9","DAN","3","9","9","Suka ce wa sarki Nebukadnezzar, “Ran sarki yă daɗe, ");
INSERT INTO hausa_vpl VALUES ("DN3_10","028_3_10","DAN","3","10","10","Ya sarki, ka fitar da doka, cewa duk wanda ya ji karar ƙaho, da sarewa, da garayu da goge, da molo da algaita da kowane irin kayan kaɗe-kaɗe da bushe-bushe sai yă rusuna yă yi sujada ga siffar zinariya, ");
INSERT INTO hausa_vpl VALUES ("DN3_11","028_3_11","DAN","3","11","11","kuma cewa duk wanda bai rusuna ya yi sujadar ba za a jefa shi cikin tanderun wuta. ");
INSERT INTO hausa_vpl VALUES ("DN3_12","028_3_12","DAN","3","12","12","Amma sai ga waɗansu Yahudawa waɗanda ka ɗora su a kan harkokin yankin Babilon, wato, Shadrak, Meshak da Abednego waɗanda ba su kula da umarninka ba, ya sarki. Ba su bauta wa allolin ba balle su yi sujada ga gunkin zinariya da ka kafa.” ");
INSERT INTO hausa_vpl VALUES ("DN3_13","028_3_13","DAN","3","13","13","Cikin fushi da hasala, Nebukadnezzar ya aika a kira Shadrak, Meshak da Abednego. Aka kawo waɗannan mutane a gaban sarki, ");
INSERT INTO hausa_vpl VALUES ("DN3_14","028_3_14","DAN","3","14","14","sai Nebukadnezzar ya ce musu, “Gaskiya ne Shadrak, Meshak da Abednego, cewa kun ƙi ku bauta wa alloli kuka kuma ƙi yi sujada ga gunkin da na kafa? ");
INSERT INTO hausa_vpl VALUES ("DN3_15","028_3_15","DAN","3","15","15","Yanzu sa’ad da kuka ji karar ƙaho, da sarewa, da garaya, da goge, da molo da algaita da kowane irin kaɗe-kaɗe da bushe-bushe, in kuna a shirye ku rusuna ƙasa ku yi wa wannan gunkin da na yi sujada, to, da kyau. Amma in ba ku yi sujada ba, za a je fa ku yanzu a cikin tanderun wutar nan. In ga kowane ne allahn nan da zai kuɓutar da ku daga hannuna?” ");
INSERT INTO hausa_vpl VALUES ("DN3_16","028_3_16","DAN","3","16","16","Sai Shadrak, Meshak da Abednego suka amsa wa sarki suka ce, “Ya Nebukadnezzar, ba mu bukata mu kāre kanmu a gabanka a kan wannan batu. ");
INSERT INTO hausa_vpl VALUES ("DN3_17","028_3_17","DAN","3","17","17","In an jefa mu cikin tanderun wutar nan, Allahn da muke bauta wa zai iya cetonmu daga ita, kuma ya sarki, zai cece mu daga hannunka. ");
INSERT INTO hausa_vpl VALUES ("DN3_18","028_3_18","DAN","3","18","18","Amma ko da bai cece mu ba, muna so ka sani, ya sarki; cewa ba za mu bauta wa allolinka ba ko kuma mu yi sujada ga gunkin zinariyar da ka kafa ba.” ");
INSERT INTO hausa_vpl VALUES ("DN3_19","028_3_19","DAN","3","19","19","Sai Nebukadnezzar ya husata da Shadrak, Meshak da Abednego, sai al’amuransa a kansu ya canja. Sai ya umarta a ƙara zuga wutar har sau bakwai domin tă yi zafi fiye da yadda take a dā. ");
INSERT INTO hausa_vpl VALUES ("DN3_20","028_3_20","DAN","3","20","20","Kuma ya umarci waɗansu ƙarfafan sojoji a cikin rundunarsa su daure Shadrak, Meshak da Abednego su jefa su cikin tanderun wutar. ");
INSERT INTO hausa_vpl VALUES ("DN3_21","028_3_21","DAN","3","21","21","Waɗannan mutanen suna sanye da riguna, da wanduna, da rawani da waɗansu kayan sawa, aka daure su, aka jefa su cikin tanderun wuta. ");
INSERT INTO hausa_vpl VALUES ("DN3_22","028_3_22","DAN","3","22","22","Sarki ya ba da umarnin da gaggawa kuma wutar ta yi zafi ƙwarai har harshen wutar ya kashe sojojin nan da suka ɗauki Shadrak, Meshak da Abednego, ");
INSERT INTO hausa_vpl VALUES ("DN3_23","028_3_23","DAN","3","23","23","waɗannan mutane uku kuma a daure, suka fāɗa cikin tanderun wutar. ");
INSERT INTO hausa_vpl VALUES ("DN3_24","028_3_24","DAN","3","24","24","Sai Sarki Nebukadnezzar ya miƙe tsaye, cike da mamaki ya tambayi mashawartansa, “Shin ba mutum uku ba ne muka daure muka jefa cikin wutar?” Suka amsa, “Tabbatacce haka yake ya sarki.” ");
INSERT INTO hausa_vpl VALUES ("DN3_25","028_3_25","DAN","3","25","25","Sai ya ce, “Ku duba ina ganin mutum huɗu suna tafiya suna yawo a cikin wutar, a sake kuma babu abin da ya same su, na huɗun sai ka ce ɗan alloli.” ");
INSERT INTO hausa_vpl VALUES ("DN3_26","028_3_26","DAN","3","26","26","Sai Nebukadnezzar ya matsa kusa da ƙofar tanderun wutar ya yi kira da ƙarfi, “Shedrak, Meshak da Abednego, bayin Allah Mafi Ɗaukaka ku fito! Ku zo nan!” Sai Shadrak, Meshak da Abednego suka fita daga cikin wutar, ");
INSERT INTO hausa_vpl VALUES ("DN3_27","028_3_27","DAN","3","27","27","Sa’an nan hakimai, da wakilai, da gwamnoni da masu ba wa sarki shawara suka kewaya su. Suka ga wutar ba tă yi musu wani lahani a jikinsu ba, babu ko gashin kansu da ya ƙuna; ko warin wuta ma ba su yi ba. ");
INSERT INTO hausa_vpl VALUES ("DN3_28","028_3_28","DAN","3","28","28","Sa’an nan Nebukadnezzar ya ce, “Yabo ya tabbata ga Allahn Shadrak, Meshak da Abednego wanda ya aiko da mala’ikansa ya ceci bayinsa da suka dogara matuƙa a gare shi, suka ki bin umarnin sarki kuma su na a shirye domin su ba da ransu da suka ƙi bauta ko su yi sujada ga wani allah sai dai Allahnsu. ");
INSERT INTO hausa_vpl VALUES ("DN3_29","028_3_29","DAN","3","29","29","Domin haka ina ba da doka cewa duk mutane da kowace al’umma ko kowane yaren da ya ce wani abu mummuna a kan Allahn Shadrak, Meshak da Abednego za a yanka shi gunduwa-gunduwa kuma gidansu zai zama wurin zuba shara, domin babu wani allahn da zai iya ceto ta irin wannan hanya.” ");
INSERT INTO hausa_vpl VALUES ("DN3_30","028_3_30","DAN","3","30","30","Sa’an nan sarki ya ƙara wa su Shadrak, Meshak da Abednego girma a yankin Babilon. ");
INSERT INTO hausa_vpl VALUES ("DN4_1","028_4_1","DAN","4","1","1","Daga sarki Nebukadnezzar. Zuwa ga mutane da al’ummai da kuma kowane yare, da suke zama a duniya. Salama mai yawa ta tabbata a gare ku! ");
INSERT INTO hausa_vpl VALUES ("DN4_2","028_4_2","DAN","4","2","2","Ina murna in shaida muku game da alamu da al’ajabai waɗanda Allah Mafi Ɗaukaka ya yi ta wurina. ");
INSERT INTO hausa_vpl VALUES ("DN4_3","028_4_3","DAN","4","3","3","Alamunsa da girma suke, ");
INSERT INTO hausa_vpl VALUES ("DN4_4","028_4_4","DAN","4","4","4","Ni, Nebukadnezzar, ina zaune a gidana cikin fadata, ina jin daɗi ina bunkasa. ");
INSERT INTO hausa_vpl VALUES ("DN4_5","028_4_5","DAN","4","5","5","Na yi mafarkin da ya ba ni tsoro. A sa’ad da nake kwance a gadona, siffofi da wahayoyi da suka bi ta cikin tunanina sun firgita ni. ");
INSERT INTO hausa_vpl VALUES ("DN4_6","028_4_6","DAN","4","6","6","Don haka na ba da umarni a tattaro dukan masu hikima na Babilon su bayyana a gabana domin su fassara mini mafarkin. ");
INSERT INTO hausa_vpl VALUES ("DN4_7","028_4_7","DAN","4","7","7","Sa’ad da masu sihiri, da masu dabo, da masanan taurari da masu duba suka zo, na faɗa musu mafarkin, amma ba su iya fassarta mini mafarkin ba. ");
INSERT INTO hausa_vpl VALUES ("DN4_8","028_4_8","DAN","4","8","8","A ƙarshe, sai Daniyel ya zo gabana na kuma faɗa masa mafarkin. (Ana ce da shi Belteshazar, wanda aka ba shi sunan allahna kuma ruhun alloli masu tsarki suna a bisansa.) ");
INSERT INTO hausa_vpl VALUES ("DN4_9","028_4_9","DAN","4","9","9","Na ce, “Belteshazar, shugaban masu sihiri, na san ruhun alloli suna a kanka, babu wani asirin da zai fi ƙarfin ganewarka. Ga dai mafarkin da na yi, sai ka fassara mini. ");
INSERT INTO hausa_vpl VALUES ("DN4_10","028_4_10","DAN","4","10","10","Waɗannan su ne wahayin da na gani a lokacin da nake kwance a gadona, na duba, a gabana kuwa ga wani itace a kafe a tsakiyar duniya, yana da tsawo ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("DN4_11","028_4_11","DAN","4","11","11","Itacen ya yi girma ya kuma yi ƙarfi, har tsayinsa ya taɓa sarari sama; ana iya ganinsa a ko’ina a duniya. ");
INSERT INTO hausa_vpl VALUES ("DN4_12","028_4_12","DAN","4","12","12","Ganyayensa suna da kyau, yana da ’ya’ya jingim, abinci kuma domin kowa da kowa. A ƙarƙashinsa namun jeji suke samun wurin hutawa, kuma tsuntsayen sama suna zaune a bisa rassansa; daga cikinsa kowace halitta take cin abinci. ");
INSERT INTO hausa_vpl VALUES ("DN4_13","028_4_13","DAN","4","13","13","“A cikin wahayin da gani sa’ad da nake kwance a kan gadona, Na duba, a gabana kuwa ga wani ɗan saƙo, mai tsarki, yana saukowa daga sama. ");
INSERT INTO hausa_vpl VALUES ("DN4_14","028_4_14","DAN","4","14","14","Sai ya yi kira da babbar murya ya ce, ‘A sare itacen a kuma yayyanka rassansa; a karkaɗe ganyensa a kuma warwatsar da ’ya’yansa. Bari dabbobi su tashi daga ƙarƙashinsa da kuma tsuntsayen da suke a rassansa. ");
INSERT INTO hausa_vpl VALUES ("DN4_15","028_4_15","DAN","4","15","15","Amma a bar kututturen da kuma saiwoyinsa, a daure shi da ƙarfe da kuma tagulla, a bar shi a cikin ƙasa, a cikin ciyayin filaye. “ ‘Bari yă jiƙu da raɓar, bari yă zauna cikin dabbobi tare da tsire-tsiren duniya. ");
INSERT INTO hausa_vpl VALUES ("DN4_16","028_4_16","DAN","4","16","16","Bari a canja tunaninsa irin na mutane a ba shi tunani irin na dabbobi, har sau bakwai su wuce a kansa. ");
INSERT INTO hausa_vpl VALUES ("DN4_17","028_4_17","DAN","4","17","17","“ ‘An sanar da wannan matsayi ne ta bakin ’yan saƙo, masu tsarki ne kuwa suka sanar da hukuncin, domin masu rai su sani Mafi Ɗaukaka ne mai iko duka a bisa kowane mulkin mutane, yakan kuma ba wa duk wanda ya ga dama, yakan sanya talaka yă zama sarki.’ ");
INSERT INTO hausa_vpl VALUES ("DN4_18","028_4_18","DAN","4","18","18","“Wannan shi ne mafarkin da ni, Nebukadnezzar, na yi. Yanzu Belteshazar, sai ka faɗa mini abin da yake nufi, domin babu wani a cikin masu hikima a mulkina da ya iya fassara mini shi. Amma za ka iya, domin ruhun alloli masu tsarki yana a bisanka.” ");
INSERT INTO hausa_vpl VALUES ("DN4_19","028_4_19","DAN","4","19","19","Sai Daniyel (wanda ake kira Belteshazar) ya tsaya zugum na ɗan lokaci, tunaninsa ya ba shi tsoro. Saboda haka sarki ya ce, “Belteshazar, kada ka bar mafarkin ko ma’anarsa ta tayar maka da hankali.” Belteshazar ya amsa ya ce, “Ranka yă daɗe, in dai har mafarkin zai tsaya a kan abokan gābanka da ma’anarsa kuma ta faɗa kan maƙiyan! ");
INSERT INTO hausa_vpl VALUES ("DN4_20","028_4_20","DAN","4","20","20","Itacen da ka gani; wanda ya yi girma da ƙarfe, da tsayinsa ya taɓa sararin sama, wanda ana ganinsa ko’ina a duniya, ");
INSERT INTO hausa_vpl VALUES ("DN4_21","028_4_21","DAN","4","21","21","wanda ganyayensa masu kyau ne yana da ’ya’yan itace da yawa, wanda yake ba da abinci ga duka, yana ba da wurin hutu ga namun jeji, kuma rassansa suna ɗauke da sheƙar tsuntsayen sama. ");
INSERT INTO hausa_vpl VALUES ("DN4_22","028_4_22","DAN","4","22","22","Ya sarki kai ne itacen nan! Ka yi girma da ƙarfi; girmanka kuma ta kai har sama, mulkinka kuma ya kai ko’ina a duniya. ");
INSERT INTO hausa_vpl VALUES ("DN4_23","028_4_23","DAN","4","23","23","“Ya sarki ka ga ɗan saƙon mai tsarkin nan, yana saukowa daga sama yana cewa, ‘A sare itacen a hallaka shi, amma a bar kututturensa daure da ƙarfe da tagulla, a bar shi can a ɗanyar ciyawar filaye, ya jiƙe da raɓa, ya zauna tare da namun jeji har shekara bakwai.’ ");
INSERT INTO hausa_vpl VALUES ("DN4_24","028_4_24","DAN","4","24","24","“Ga fassarar, ya sarki, wannan ita ce doka wadda Mafi Ɗaukaka ya bayar a kan ranka yă daɗe, sarkina. ");
INSERT INTO hausa_vpl VALUES ("DN4_25","028_4_25","DAN","4","25","25","Za a kore ka daga cikin mutane, za ka kuma zauna cikin namun jeji; za ka ci ciyawa kamar shanu, za ka jiƙe da raɓa har shekara bakwai cif sa’an nan za ka sani cewa Mafi Ɗaukaka ne mai iko duka a kan dukan mulkoki a duniya, yake kuma ba da mulki ga duk wanda ya ga dama. ");
INSERT INTO hausa_vpl VALUES ("DN4_26","028_4_26","DAN","4","26","26","Umarni na barin kututturen itacen da saiwoyinsa yana nufin cewa za a maido maka da mulkinka a lokacin da ka gane cewa Mai sama ne yake mulki. ");
INSERT INTO hausa_vpl VALUES ("DN4_27","028_4_27","DAN","4","27","27","Saboda haka, ya sarki, ina roƙonka ka karɓi shawarar da zan ba ka; ka furta zunubanka ta wurin yin abin da yake daidai. Ka bar muguntarka, ka aikata alheri ga waɗanda ake wulaƙantawa, wataƙila za a ƙara tsawon kwanakinka da salama.” ");
INSERT INTO hausa_vpl VALUES ("DN4_28","028_4_28","DAN","4","28","28","Duk wannan kuwa ya faru da sarki Nebukadnezzar. ");
INSERT INTO hausa_vpl VALUES ("DN4_29","028_4_29","DAN","4","29","29","Bayan wata goma sha biyu, a sa’ad da sarki yake takawa a bisan saman ɗakin fadar Babilon, ");
INSERT INTO hausa_vpl VALUES ("DN4_30","028_4_30","DAN","4","30","30","sai ya ce, “Ba wannan ita ce Babilon babba da na gina domin wurin zaman sarautar Babilon, da ikona kuma domin ɗaukakar darajata ba?” ");
INSERT INTO hausa_vpl VALUES ("DN4_31","028_4_31","DAN","4","31","31","Tun kalmomin suna cikin bakinsa sai ya ji murya daga sama tana cewa, “Wannan shi ne abin da aka zartar a kanka, Sarki Nebukadnezzar. An karɓe ikon mulkinka. ");
INSERT INTO hausa_vpl VALUES ("DN4_32","028_4_32","DAN","4","32","32","Za a kore ka daga cikin mutane za ka kuma yi rayuwa tare da namun jeji. Za ka ci ciyawa kamar sa har shekara bakwai cif, sa’an nan za ka gane Mafi Ɗaukaka ne mai iko duka a kan dukan mulkoki a duniya, yake kuma ba da mulki ga duk wanda ya ga dama.” ");
INSERT INTO hausa_vpl VALUES ("DN4_33","028_4_33","DAN","4","33","33","Nan da nan abin da aka faɗa a kan Nebukadnezzar tabbatarsa ya cika. Aka kore shi daga cikin mutane ya kuma shiga cin ciyawa kamar shanu. Jikinsa ya jiƙe da raɓa, har gashinsa ya yi tsawo kamar fikafikan gaggafa, kumbarsa kuma suka yi tsawo kamar na tsuntsu. ");
INSERT INTO hausa_vpl VALUES ("DN4_34","028_4_34","DAN","4","34","34","A ƙarshen waɗannan kwanaki, ni, Nebukadnezzar, na ɗaga idanuna sama, sai hankalina ya komo mini. Na kuwa yabi Maɗaukaki, na girmama shi, na ɗaukaka shi wanda yake rayayye har abada. ");
INSERT INTO hausa_vpl VALUES ("DN4_35","028_4_35","DAN","4","35","35","Dukan mutanen duniya ");
INSERT INTO hausa_vpl VALUES ("DN4_36","028_4_36","DAN","4","36","36","A lokacin nan hankalina ya komo mini, sai aka mayar mini da masarautata mai daraja, da martabata, da girmana. ’Yan majalisata da fadawana suka nemo ni. Aka maido ni kan gadon sarautata da daraja fiye da ta dā. ");
INSERT INTO hausa_vpl VALUES ("DN4_37","028_4_37","DAN","4","37","37","Yanzu ni, Nebukadnezzar, ina yabon Sarkin sama, ina waƙa ina kuma darjanta shi, saboda dukan abin da ya yi mini, mai kyau ne kuma dukan hanyoyinsa gaskiya ne. Kuma duk masu tafiya da girman kai zai ƙasƙantar da su. ");
INSERT INTO hausa_vpl VALUES ("DN5_1","028_5_1","DAN","5","1","1","Sarki Belshazar ya yi babban biki domin dubban hakimansa ya kuma sha ruwan inabi tare da su. ");
INSERT INTO hausa_vpl VALUES ("DN5_2","028_5_2","DAN","5","2","2","Yayinda Belshazar yake shan ruwan inabi, sai ya umarta a kawo zinariya da azurfan da Nebukadnezzar mahaifinsa ya kwaso daga haikali a Urushalima, saboda sarki da hakimansa, da matansa da ƙwarƙwaransa su sha da su. ");
INSERT INTO hausa_vpl VALUES ("DN5_3","028_5_3","DAN","5","3","3","Sai suka kawo kayan zinariyan nan da aka kwaso daga haikalin Allah a Urushalima, sarki kuwa da hakimansa, da matansa, da ƙwarƙwaransa suka yi ta sha da su. ");
INSERT INTO hausa_vpl VALUES ("DN5_4","028_5_4","DAN","5","4","4","Yayinda suke shan ruwan inabin, sai suka yabi allolin zinariya da azurfa, da na tagulla, da na ƙarfe, da na itace da kuma na dutse. ");
INSERT INTO hausa_vpl VALUES ("DN5_5","028_5_5","DAN","5","5","5","Nan da nan sai ga yatsotsin hannun mutum sun bayyana, suna yin rubutu a kan shafen bangon, kusa da wurin da ake ajiye fitilar fadar sarki. Sarki kuwa yana ganin hannun yayinda yake rubutu. ");
INSERT INTO hausa_vpl VALUES ("DN5_6","028_5_6","DAN","5","6","6","Sai fuskarsa ta ruɗe, ya kuma ji tsoro ƙwarai har gwiwoyinsa suka yi ta bugun juna, ƙafafunsa kuma suka rasa ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("DN5_7","028_5_7","DAN","5","7","7","Sai sarki ya kira masu dabo, masanan taurari da masu duba, a kawo su, ya kuma ce wa masu hikima na Babilon, “Duk wanda ya karanta wannan rubutu ya kuma faɗa mini abin da yake nufi, za a sa masa rigar shunayya, a kuma sa masa sarƙar zinariya a wuyansa, zai zama na uku a cikin masu mulkin ƙasar.” ");
INSERT INTO hausa_vpl VALUES ("DN5_8","028_5_8","DAN","5","8","8","Sa’an nan sai dukan masu hikima suka zo ciki, amma ba su iya karanta rubutun ba ko su faɗa wa sarki abin da yake nufi. ");
INSERT INTO hausa_vpl VALUES ("DN5_9","028_5_9","DAN","5","9","9","Saboda haka Sarki Belshazar ya firgita ƙwarai kuma fuskarsa ta ƙara ruɗewa. Hakimansa kuma suka rikice. ");
INSERT INTO hausa_vpl VALUES ("DN5_10","028_5_10","DAN","5","10","10","Sai sarauniya, da jin muryoyi na sarki da na hakimansa, ta shiga babban ɗakin liyafar. Ta ce, “Ya sarki, ranka yă daɗe! Kada ka firgita! Kada fuskarka ta ruɗe! ");
INSERT INTO hausa_vpl VALUES ("DN5_11","028_5_11","DAN","5","11","11","Akwai wani mutum a masarautarka wanda yake da ruhun alloli masu tsarki a cikinsa. A zamanin mahaifinka an gane cewa yana da basira da hazaka da hikima kamar na alloli. Sarki Nebukadnezzar mahaifinka, mahaifinka sarki, na ce, ya naɗa shugaban masu dabo, da masu sihiri, masanan taurari da kuma masu duba. ");
INSERT INTO hausa_vpl VALUES ("DN5_12","028_5_12","DAN","5","12","12","Wannan mutum Daniyel, wanda sarki ya kira Belteshazar, an gane yana da ruhu nagari, da ilimi, da ganewa don yin fassarar mafarkai, da bayyana ma’anar kacici-kacici, da warware al’amura masu wuya. Ka kira Daniyel shi kuwa zai faɗa maka abin da rubutun nan yake nufi.” ");
INSERT INTO hausa_vpl VALUES ("DN5_13","028_5_13","DAN","5","13","13","Saboda haka aka kawo Daniyel a gaban sarki, sai sarki ya ce masa, “Kai ne Daniyel ɗin nan, ɗaya daga cikin kamammu waɗanda mahaifina sarki ya kawo daga Yahuda? ");
INSERT INTO hausa_vpl VALUES ("DN5_14","028_5_14","DAN","5","14","14","Na sami labari cewa kana da ruhun alloli a cikinka da kuma basira, da hazaka da kuma fitacciyar hikima. ");
INSERT INTO hausa_vpl VALUES ("DN5_15","028_5_15","DAN","5","15","15","An kawo masu hikima da masu dabo a gabana domin su karanta wannan rubutu su kuma faɗa mini abin da yake nufi, amma ba su iya ba. ");
INSERT INTO hausa_vpl VALUES ("DN5_16","028_5_16","DAN","5","16","16","Na sami labari cewa kana iya ba da fassara da kuma warware matsaloli masu wuya. In har ka iya karanta wannan rubutun ka kuma faɗa mini abin da yake nufi, za a sa maka riga shunayya, a kuma sa sarƙar zinariya a wuyanka. Za ka zama na uku a cikin masu mulkin ƙasar.” ");
INSERT INTO hausa_vpl VALUES ("DN5_17","028_5_17","DAN","5","17","17","Sai Daniyel ya amsa wa sarki ya ce, “Za ka iya ajiye kyautar wa kanka ko kuma ka ba wa wani. Duk da haka, zan karanta wa sarki rubutun, in kuma faɗa abin da yake nufi. ");
INSERT INTO hausa_vpl VALUES ("DN5_18","028_5_18","DAN","5","18","18","“Ya sarki, Allah Mafi Ɗaukaka ya ba mahaifinka Nebukadnezzar sarauta, da girma, da ɗaukaka, da martaba. ");
INSERT INTO hausa_vpl VALUES ("DN5_19","028_5_19","DAN","5","19","19","Saboda irin matsayin da ya ba shi, dukan mutane da al’ummai da kuma dukan harsuna suka ji tsoronsa suka yi rawar jiki a gabansa. Bisa ga ganin damarsa yakan kashe wani, ya bar wani da rai, haka kuma yakan ɗaukaka wani, ya ƙasƙantar da wani. ");
INSERT INTO hausa_vpl VALUES ("DN5_20","028_5_20","DAN","5","20","20","Amma da lokacin da zuciyarsa ta cika da girman kai ta kuma taurare, sai aka kore shi daga gadon sarautarsa, aka raba shi kuma da darajarsa. ");
INSERT INTO hausa_vpl VALUES ("DN5_21","028_5_21","DAN","5","21","21","Aka kore shi daga cikin mutane aka kuma ba shi tunani irin na dabba; ya yi zama tare da jakunan jeji, ya kuma ci ciyawa kamar shanu; jikinsa kuma ya jiƙe da raɓa, har zuwa lokacin da ya gane, ashe, Allah Maɗaukaki ne mai iko duka a kan dukan mulkoki a duniya, yake kuma ba da mulki ga duk wanda ya ga dama. ");
INSERT INTO hausa_vpl VALUES ("DN5_22","028_5_22","DAN","5","22","22","“Amma kai ɗansa, Ya Belshazar, ba ka ƙasƙantar da kanka ba, ko da yake ka san wannan duka. ");
INSERT INTO hausa_vpl VALUES ("DN5_23","028_5_23","DAN","5","23","23","A maimakon, sai ka nuna wa Ubangiji na sama girman kai. Ka sa aka kawo maka su kwaf na zinariya daga haikalinsa, da kai da hakimanka, da matanka da ƙwarƙwaranka kuka sha ruwan inabi da su. Kuka yabi allolin zinariya da na azurfa, da na tagulla, da na baƙin ƙarfe, da na itace, da na dutse waɗanda ba sa ji, ba sa gani, ba sa da gane kome. Amma ba ka girmama Allah ba, wanda ranka da dukan harkokinka suna a hannunsa. ");
INSERT INTO hausa_vpl VALUES ("DN5_24","028_5_24","DAN","5","24","24","Saboda haka ya aiko da hannun da ya yi rubutun nan. ");
INSERT INTO hausa_vpl VALUES ("DN5_25","028_5_25","DAN","5","25","25","“Wannan shi ne rubutun da aka yi, Mene, mene, tekel, farsin ");
INSERT INTO hausa_vpl VALUES ("DN5_26","028_5_26","DAN","5","26","26","“Abin da kalmomin nan suke nufi shi ne, “Mene, Allah ya ƙayyade yawan kwanakin mulkinka ya kuma kawo su ga ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("DN5_27","028_5_27","DAN","5","27","27","“Tekel, An kuma auna ka a ma’auni aka tarar ka kāsa. ");
INSERT INTO hausa_vpl VALUES ("DN5_28","028_5_28","DAN","5","28","28","“Feres, An raba mulkinka aka ba wa Medes da Farisa.” ");
INSERT INTO hausa_vpl VALUES ("DN5_29","028_5_29","DAN","5","29","29","Sai Belshazar ya umarta, aka sa wa Daniyel riga mai shunayya, aka sa sarƙar zinariya a wuyansa, aka kuma yi shela, cewa yanzu shi ne na uku a cikin masu mulkin ƙasar. ");
INSERT INTO hausa_vpl VALUES ("DN5_30","028_5_30","DAN","5","30","30","A wannan dare aka kashe Belshazar, sarkin Babiloniyawa, ");
INSERT INTO hausa_vpl VALUES ("DN5_31","028_5_31","DAN","5","31","31","Dariyus mutumin Medes kuwa ya karɓi mulkin, yana da shekara sittin da biyu. ");
INSERT INTO hausa_vpl VALUES ("DN6_1","028_6_1","DAN","6","1","1","Ya gamshi Dariyus ya naɗa muƙaddasai 120 su yi shugabanci a duk fāɗin masarautar, ");
INSERT INTO hausa_vpl VALUES ("DN6_2","028_6_2","DAN","6","2","2","ya naɗa mutum uku a bisa waɗannan muƙaddasan, Daniyel yana ɗaya daga cikin mutum ukun nan. Sai aka sa muƙaddasan nan a ƙarƙashin waɗannan uku ɗin domin kada sarki ya yi hasarar kome. ");
INSERT INTO hausa_vpl VALUES ("DN6_3","028_6_3","DAN","6","3","3","To, Daniyel dai ya yi ficce a cikin shugabannin nan uku har da muƙaddasan ma, saboda waɗansu halaye nagari da yake da su, wanda ya sa sarki ya yi shiri ya ɗora shi a kan dukan mulkinsa. ");
INSERT INTO hausa_vpl VALUES ("DN6_4","028_6_4","DAN","6","4","4","A kan haka, shugabannin nan uku da muƙaddasan nan suka yi ƙoƙari su sami wani laifi a kan Daniyel a yadda yake tafiyar da aikin shugabancinsa, amma ba su samu ba. Ba su same shi da wani laifin cin hanci ba, domin shi amintacce ne kuma babu wani aibi a kansa ko rashin kula. ");
INSERT INTO hausa_vpl VALUES ("DN6_5","028_6_5","DAN","6","5","5","A ƙarshe waɗannan mutane suka ce; “Ba za mu taɓa samun wani laifin da za mu kama Daniyel da shi ba, sai dai ko abin ya shafi dokar Allahnsa.” ");
INSERT INTO hausa_vpl VALUES ("DN6_6","028_6_6","DAN","6","6","6","Saboda haka shugabannin nan suka haɗu da muƙaddasan nan suka tafi wurin sarki a ƙungiyance suka ce, “Ya Sarki Dariyus, ranka yă daɗe! ");
INSERT INTO hausa_vpl VALUES ("DN6_7","028_6_7","DAN","6","7","7","Shugabannin masarauta, da masu mulki, da muƙaddasai, da mashawarta da gwamnoni duk sun amince cewa sarki yă kafa doka yă kuma yi umarni cewa a cikin kwana talatin nan gaba duk wanda ya yi addu’a ga wani allah ko mutum, in ba a gare ka ba, ya sarki, jefa shi cikin kogon zakoki. ");
INSERT INTO hausa_vpl VALUES ("DN6_8","028_6_8","DAN","6","8","8","Yanzu, ya sarki, sai ka yi umarni ka kuma yi shi a rubuce saboda kada a canja shi, bisa ga dokar Medes da Farisa, waɗanda ba a iya sokewa.” ");
INSERT INTO hausa_vpl VALUES ("DN6_9","028_6_9","DAN","6","9","9","Sai Sarki Dariyus ya ba da umarnin a rubuce. ");
INSERT INTO hausa_vpl VALUES ("DN6_10","028_6_10","DAN","6","10","10","To, da Daniyel ya ji labarin cewa an fitar da doka, sai ya tafi gidansa a ɗakinsa na sama inda tagogin ɗakin suke duban wajen Urushalima. Sau uku yakan durƙusa yă yi addu’a yana yin godiya ga Allahnsa, kamar yadda ya saba yi. ");
INSERT INTO hausa_vpl VALUES ("DN6_11","028_6_11","DAN","6","11","11","Sai waɗannan mutane suka tafi a ƙungiyance suka kuma iske Daniyel yana addu’a yana roƙon Allah yă taimake shi. ");
INSERT INTO hausa_vpl VALUES ("DN6_12","028_6_12","DAN","6","12","12","Sai suka tafi wurin sarki suka yi masa magana game da dokar mulkinsa, suka ce, “Ashe, ba ka yi doka cewa a cikin kwana talatin nan gaba duk wanda aka tarar yana addu’a ga wani allah ko mutum in ba kai ba, ya sarki, za ka jefa shi a cikin ramin zakoki ba?” Sarki ya amsa ya ce, “Dokar tana nan daram bisa ga dokar Medes da Farisa, waɗanda ba a iya sokewa.” ");
INSERT INTO hausa_vpl VALUES ("DN6_13","028_6_13","DAN","6","13","13","Sai suka ce wa sarki, “Daniyel ɗin nan, wanda yake ɗaya daga cikin waɗanda aka kwaso daga Yahuda, bai kula da kai ba, ya sarki, balle fa dokar da ka yi. Har yanzu yana addu’a sau uku a rana.” ");
INSERT INTO hausa_vpl VALUES ("DN6_14","028_6_14","DAN","6","14","14","Da sarki ya ji haka, sai ya damu sosai, ya ƙudura yă ceci Daniyel, ya yi ta fama har fāɗuwar rana yadda zai yi yă kuɓutar da shi. ");
INSERT INTO hausa_vpl VALUES ("DN6_15","028_6_15","DAN","6","15","15","Sai mutanen nan suka je wurin sarki a ƙungiyance suka ce masa, “Ka tuna, ya sarki; cewa bisa ga dokar Medes da Farisa, babu umarni ko dokar da sarki ya yi da za a iya sokewa.” ");
INSERT INTO hausa_vpl VALUES ("DN6_16","028_6_16","DAN","6","16","16","Saboda haka sai sarki ya ba da umarni suka kuma kawo Daniyel suka jefa shi cikin ramin zakoki. Sarki ya ce wa Daniyel, “Bari Allahn nan wanda kake bauta masa kullum, yă cece ka!” ");
INSERT INTO hausa_vpl VALUES ("DN6_17","028_6_17","DAN","6","17","17","Aka kawo dutsen aka rufe bakin ramin, sa’an nan sarki ya hatimce shi da zobensa da kuma zoban manyan mutanensa, don kada wani yă canja yanayin Daniyel. ");
INSERT INTO hausa_vpl VALUES ("DN6_18","028_6_18","DAN","6","18","18","Sa’an nan sarki ya koma fadarsa ya kwana bai ci ba, kuma babu wata liyafar da aka kawo masa. Ya kuma kāsa barci. ");
INSERT INTO hausa_vpl VALUES ("DN6_19","028_6_19","DAN","6","19","19","Gari yana wayewa, sai sarki ya tashi ya hanzarta zuwa ramin zakoki. ");
INSERT INTO hausa_vpl VALUES ("DN6_20","028_6_20","DAN","6","20","20","Da ya yi kusa da ramin zakokin, sai ya kira Daniyel da muryar mai cike da damuwa ya ce, “Daniyel bawan Allah mai rai, ko Allahn nan naka wanda kake bauta wa kullum, ya iya cetonka daga zakoki?” ");
INSERT INTO hausa_vpl VALUES ("DN6_21","028_6_21","DAN","6","21","21","Sai Daniyel ya amsa ya ce, “Ran sarki, yă daɗe! ");
INSERT INTO hausa_vpl VALUES ("DN6_22","028_6_22","DAN","6","22","22","Allahna ya aiko da mala’ikansa, ya kuwa rufe bakunan zakoki. Ba su yi mini rauni ba, gama an same ni marar laifi ne a gabansa. Ban kuwa taɓa yin wani abu marar kyau a gabanka ba, ya sarki.” ");
INSERT INTO hausa_vpl VALUES ("DN6_23","028_6_23","DAN","6","23","23","Sai sarki ya cika da murna ƙwarai, ya kuma yi umarni a ciro Daniyel daga ramin zakoki. Kuma da aka fito da Daniyel daga ramin, ba a sami wani rauni a jikinsa ba, domin ya dogara ga Allahnsa. ");
INSERT INTO hausa_vpl VALUES ("DN6_24","028_6_24","DAN","6","24","24","Sai sarki ya umarta, a kawo mutanen nan da suka yi wa Daniyel maƙarƙashiya, a tura su, da ’ya’yansu, da matansu cikin ramin zakoki. Kafin ma su kai ƙurewar ramin, sai zakoki suka hallaka su suka yayyage su, suka yi kaca-kaca da su. ");
INSERT INTO hausa_vpl VALUES ("DN6_25","028_6_25","DAN","6","25","25","Sa’an nan Sarki Dariyus ya rubuta wa dukan mutane, da al’ummai da kuma mutanen dukan harsunan a duk fāɗin ƙasar. “Bari yă yi nasara sosai! ");
INSERT INTO hausa_vpl VALUES ("DN6_26","028_6_26","DAN","6","26","26","“Na fitar da doka cewa a cikin dukan iyakar ƙasar mulkina, dole mutane su ji tsoro su kuma girmama Allah na Daniyel. ");
INSERT INTO hausa_vpl VALUES ("DN6_27","028_6_27","DAN","6","27","27","Yakan kuɓutar ya kuma ceci; ");
INSERT INTO hausa_vpl VALUES ("DN6_28","028_6_28","DAN","6","28","28","Daniyel kuwa ya bunkasa a lokacin mulkin Dariyus da kuma mulkin Sairus na Farisa. ");
INSERT INTO hausa_vpl VALUES ("DN7_1","028_7_1","DAN","7","1","1","A shekara ta fari ta mulkin Belshazar sarkin Babilon, Daniyel ya yi mafarki, wahayoyi kuma suka ratsa tunaninsa a sa’ad da yake a kwance a gadonsa. Sai ya rubuta abin da mafarkin ya ƙunsa. ");
INSERT INTO hausa_vpl VALUES ("DN7_2","028_7_2","DAN","7","2","2","Daniyel ya ce, “A cikin wahayina da dare na duba, a gabana kuwa ga kusurwoyi huɗu na sama suna gurɓata babban teku. ");
INSERT INTO hausa_vpl VALUES ("DN7_3","028_7_3","DAN","7","3","3","Sai ga dabbobi huɗu, kowannensu ya yi dabam da sauran, suna fitowa daga teku. ");
INSERT INTO hausa_vpl VALUES ("DN7_4","028_7_4","DAN","7","4","4","“Na farkon ya yi kamar zaki kuma yana da fikafikai kamar gaggafa. Ina kallo, sai aka fizge fikafikanta, aka ɗaga ta sama, aka sa ta tsaya a kan ƙafafu biyu kamar mutum, aka ba ta tunani irin na mutum. ");
INSERT INTO hausa_vpl VALUES ("DN7_5","028_7_5","DAN","7","5","5","“A gabana kuma ga dabba ta biyu, wadda ta yi kamar beyar. Aka ɗaga ta a gefenta guda, tana kuwa da haƙarƙarai uku a bakinta a tsakanin haƙoranta. Aka faɗa mata, ‘Tashi ki cika cikinki da ɗanyen nama!’ ");
INSERT INTO hausa_vpl VALUES ("DN7_6","028_7_6","DAN","7","6","6","“Bayan haka, na duba, a gabana kuwa ga wata dabba wadda ta yi kamar Damisa, a bayanta kuma tana da fikafikai huɗu irin na tsuntsu. Wannan dabbar tana da kawuna huɗu, aka kuma ba ta iko tă yi mulki. ");
INSERT INTO hausa_vpl VALUES ("DN7_7","028_7_7","DAN","7","7","7","“Bayan haka, a cikin wahayina da dare na duba, a gabana kuwa ga dabba ta huɗu, wadda take da bantsoro da banrazana da kuma iko ƙwarai. Tana da manyan haƙoran ƙarfe; ta ragargaje ta cinye abin da ta kama, ta kuma tattaka duk abin da ya rage a ƙarƙashin ƙafafunta. Ta bambanta da dukan sauran dabbobin da suka riga ta, tana kuma da ƙahoni goma. ");
INSERT INTO hausa_vpl VALUES ("DN7_8","028_7_8","DAN","7","8","8","“Yayinda nake cikin tunani game da ƙahonin nan, a gabana kuwa ga wani ƙaho, ɗan ƙanƙani, wanda ya fito daga cikinsu; kuma an tumɓuke uku daga cikin ƙahonin farko kafin wannan. Wannan ƙaho yana da idanu kamar na mutum da kuma bakin da yake maganganun fariya. ");
INSERT INTO hausa_vpl VALUES ("DN7_9","028_7_9","DAN","7","9","9","“Ina cikin dubawa, “sai aka ajiye kursiyoyi, sai ga wani wanda yake tun fil azal ya zauna a mazauninsa. Rigarsa ta yi fari fat kamar ƙanƙara; gashin kansa sun yi fari kamar ulu. Kursiyinsa kuma harshen wuta, dukan ƙafafun kursiyin masu kama da keken yaƙin, wuta ne. ");
INSERT INTO hausa_vpl VALUES ("DN7_10","028_7_10","DAN","7","10","10","Kogin wuta yana gudu, yana fitowa daga gabansa. Dubun dubbai sun yi masa hidima; dubu goma sau dubu goma sun tsaya a gabansa. Aka zauna don shari’a, aka kuma buɗe littattafai. ");
INSERT INTO hausa_vpl VALUES ("DN7_11","028_7_11","DAN","7","11","11","“Sa’an nan na ci gaba da kallo saboda kalmomin fariyar da wannan ƙaho yake furtawa. Na yi ta kallo har sai da aka yanke dabbar, aka kuma hallaka jikinta a cikin wuta. ");
INSERT INTO hausa_vpl VALUES ("DN7_12","028_7_12","DAN","7","12","12","(An tuɓe sauran dabbobin daga mulkinsu, amma aka bar su su rayu na wani lokaci.) ");
INSERT INTO hausa_vpl VALUES ("DN7_13","028_7_13","DAN","7","13","13","“A wahayina na dare, na ga a gabana wani kamar ɗan mutum yana saukowa tare da gizagizan sama. Ya kusaci Wannan wanda yake Tun fil azal aka kuma kai shi gabansa. ");
INSERT INTO hausa_vpl VALUES ("DN7_14","028_7_14","DAN","7","14","14","Aka ba shi mulki, daraja da kuma mafificin iko; dukan mutane, da al’ummai, da mutane daga kowane harshe suka yi masa sujada. Mulkinsa kuwa dawwammamen mulki ne da ba zai ƙare ba, sarautarsa kuma ba ta taɓa lalacewa. ");
INSERT INTO hausa_vpl VALUES ("DN7_15","028_7_15","DAN","7","15","15","“Ni, Daniyel, ruhuna ya damu ƙwarai, kuma wahayin da ya ratsa tunanina ya dame ni. ");
INSERT INTO hausa_vpl VALUES ("DN7_16","028_7_16","DAN","7","16","16","Sai na matsa kusa da ɗaya daga cikin waɗanda suke tsaye a can, na tambaye shi gaskiya ma’anar waɗannan al’amura. “Don haka sai ya faɗa mini, ya kuma ba ni fassarar waɗannan al’amura. ");
INSERT INTO hausa_vpl VALUES ("DN7_17","028_7_17","DAN","7","17","17","‘Waɗannan manyan dabbobi huɗu, Masarautai ne huɗu waɗanda za su taso a duniya. ");
INSERT INTO hausa_vpl VALUES ("DN7_18","028_7_18","DAN","7","18","18","Amma tsarkaka na Mafi Ɗaukaka za su karɓi wannan sarauta, za su kuwa mallake ta har abada, I, har abada abadin.’ ");
INSERT INTO hausa_vpl VALUES ("DN7_19","028_7_19","DAN","7","19","19","“Sa’an nan kuma sai na so in san ma’anar wannan dabba ta huɗu, wadda ta yi dabam da sauran dabbobin da suke da matuƙar bantsoro, da take da haƙoran ƙarfe da kuma farcen tagulla, dabbar ta ragargaje ta cinye abin da ta kama, ta kuma tattaka duk abin da ya rage a ƙarƙashin ƙafafunta. ");
INSERT INTO hausa_vpl VALUES ("DN7_20","028_7_20","DAN","7","20","20","Na kuma so in gane game da ƙahonin nan guda goma da suke a kanta da kuma game da ƙahon nan da ya fito, wanda aka tumɓuke ƙahoni uku a gabansa, ƙahon nan da yake da idanu da bakin da yake furta manyan maganganun fariya, wanda ya yi kamar ya fi sauran girma. ");
INSERT INTO hausa_vpl VALUES ("DN7_21","028_7_21","DAN","7","21","21","Ina cikin dubawa, sai ga wannan ƙaho yana yaƙi da tsarkaka yana kuma cin nasara a kansu, ");
INSERT INTO hausa_vpl VALUES ("DN7_22","028_7_22","DAN","7","22","22","sai da Wannan wanda yake tun fil azal ya zo ya furta hukunci, aka kuma ba tsarkaka na Mafi Ɗaukaka gaskiya, lokaci kuwa ya cika sai suka karɓi mulki. ");
INSERT INTO hausa_vpl VALUES ("DN7_23","028_7_23","DAN","7","23","23","“Sai ya ba ni wannan bayani, ‘Dabbar nan ta huɗu, ita ce mulki na huɗu da zai bayyana a duniya. Zai bambanta da dukan sauran mulkoki, zai kuma cinye dukan duniya, yă tattake ta, yă kuma ragargaje ta. ");
INSERT INTO hausa_vpl VALUES ("DN7_24","028_7_24","DAN","7","24","24","Ƙahonin nan goma, sarakuna ne goma waɗanda za su taso daga wannan mulki. Bayansu kuma, wani sarki zai taso, wanda ya sha dabam da waɗanda suka riga shi. Zai rinjayi sarakunan nan uku. ");
INSERT INTO hausa_vpl VALUES ("DN7_25","028_7_25","DAN","7","25","25","Zai yi maganar saɓo a kan Mafi Ɗaukaka, zai kuma tsananta wa tsarkaka yă kuma yi ƙoƙarin sāke lokuta da shari’u. Za a miƙa tsarkaka a hannunsa na wani lokaci, lokuta da kuma rabin lokaci. ");
INSERT INTO hausa_vpl VALUES ("DN7_26","028_7_26","DAN","7","26","26","“ ‘Amma majalisa za tă yi zama, za a karɓe ikonsa, a kuma hallaka shi gaba ɗaya har abada. ");
INSERT INTO hausa_vpl VALUES ("DN7_27","028_7_27","DAN","7","27","27","Sa’an nan za a ba da mulki, iko da girma na mulkokin da suke a ƙarƙashin dukan sammai ga tsarkaka, mutane na Mafi Ɗaukaka. Mulkinsa kuwa mulki ne marar matuƙa, kuma dukan masu mulki za su yabe shi, su kuma yi masa biyayya.’ ");
INSERT INTO hausa_vpl VALUES ("DN7_28","028_7_28","DAN","7","28","28","“Wannan shi ne ƙarshen batun. Ni, Daniyel na damu ƙwarai da irin tunanina, kuma fuskata ta rikice, amma na riƙe batun a zuciyata.” ");
INSERT INTO hausa_vpl VALUES ("DN8_1","028_8_1","DAN","8","1","1","A shekara ta uku ta mulkin sarki Belshazar, ni, Daniyel, na ga wahayi, bayan wancan da na riga gani. ");
INSERT INTO hausa_vpl VALUES ("DN8_2","028_8_2","DAN","8","2","2","A cikin wahayin, na ga kaina a mafakar Shusha a yankin Elam; a wahayin na ga ina a bakin Kogin Ulai. ");
INSERT INTO hausa_vpl VALUES ("DN8_3","028_8_3","DAN","8","3","3","Na ɗaga ido, a gabana kuwa sai ga rago mai ƙahoni biyu, yana tsaye a gefen mashigin kogin, ƙahonin kuma suna da tsawo. Ɗaya daga cikin ƙahonin ya fi ɗayan tsawo. Wanda ya fi tsawon shi ne ya tsiro daga baya. ");
INSERT INTO hausa_vpl VALUES ("DN8_4","028_8_4","DAN","8","4","4","Na lura da ragon sa’ad da ya kai karo wajen yamma da arewa da kudu. Babu wata dabbar da ta iya ƙarawa da shi, babu kuma wanda ya iya kuɓuta daga ikonsa. Ya yi yadda ya ga dama, ya kuma zama mai girma. ");
INSERT INTO hausa_vpl VALUES ("DN8_5","028_8_5","DAN","8","5","5","Yayinda nake tunani game da wannan, farat ɗaya sai ga bunsurun da yake da sanannen ƙaho tsakanin idanunsa ya ɓullo daga wajen yamma, yana ratsa dukan duniya ba ya ko taɓa ƙasa. ");
INSERT INTO hausa_vpl VALUES ("DN8_6","028_8_6","DAN","8","6","6","Ya zo wajen rago mai ƙahoni biyu ɗin nan da na riga na gani tsaye a gefen mashigin kogin nan ya tasar masa da fushi mai zafi. ");
INSERT INTO hausa_vpl VALUES ("DN8_7","028_8_7","DAN","8","7","7","Na ga ya zo kusa da ragon, ya husata da shi ƙwarai, ya kai wa ragon hari. Ya kakkarya ƙahoninsa nan biyu. Ƙarfin ragon ya kāsa, bai iya kāre kansa daga bunsurun ba. Bunsurun ya buge shi ƙasa ya tattake shi. Ba wanda ya iya ceton ragon daga bunsurun. ");
INSERT INTO hausa_vpl VALUES ("DN8_8","028_8_8","DAN","8","8","8","Bunsurun kuwa ya ƙasaita, amma a ƙwanƙolin ikonsa sai aka karye babban ƙahonsa, kuma a wurin da ƙahon nan ya kasance waɗansu sanannun ƙahoni huɗu suka tsiro suna fuskantar kusurwoyin nan huɗu. ");
INSERT INTO hausa_vpl VALUES ("DN8_9","028_8_9","DAN","8","9","9","Daga cikin ɗayansu kuma wani ƙaramin ƙaho ya fito, ya yi girma ya ƙasaita ƙwarai zuwa kudu da kuma gabas da wajen Kyakkyawar Ƙasa. ");
INSERT INTO hausa_vpl VALUES ("DN8_10","028_8_10","DAN","8","10","10","Ya yi girma sai da ya kai rundunar sammai, ya kuma fid da waɗansu rundunar taurari zuwa ƙasa ya kuma tattake su. ");
INSERT INTO hausa_vpl VALUES ("DN8_11","028_8_11","DAN","8","11","11","Sai ya ɗora kansa ya zama mai girma kamar Sarkin runduna; sai aka ɗauke hadaya ta kullayaumi daga gare shi, aka kuma saukar da wurin masujadarsa ƙasa. ");
INSERT INTO hausa_vpl VALUES ("DN8_12","028_8_12","DAN","8","12","12","Saboda tawaye, sai aka ba da rundunar tsarkaka da kuma hadayar ƙonawa ta kowace rana ga ƙahon. Sai ya yi watsi da gaskiya, ya yi abin da ya ga dama, ya kuwa yi nasara. ");
INSERT INTO hausa_vpl VALUES ("DN8_13","028_8_13","DAN","8","13","13","Sa’an nan na ji mai tsarkin nan yana magana, wani mai tsarki kuma ya ce da wancan, “Har yaushe wannan wahayi zai tabbata, wahayi game da hadaya ta kullayaumi, da tawayen da yake kawo lalacewa, da kuma miƙa wuri mai tsarki da kuma na rundunar da za a tattake a ƙarƙashin sawu?” ");
INSERT INTO hausa_vpl VALUES ("DN8_14","028_8_14","DAN","8","14","14","Sai ya ce mini, “Zai ɗauki safiya da yamma 2,300; sa’an nan za a sāke tsarkake wuri mai tsarki.” ");
INSERT INTO hausa_vpl VALUES ("DN8_15","028_8_15","DAN","8","15","15","Yayinda ni, Daniyel, nake duban wahayi ina ƙoƙari in fahimce shi, sai ga wani a gabana wanda ya yi kama da mutum. ");
INSERT INTO hausa_vpl VALUES ("DN8_16","028_8_16","DAN","8","16","16","Sai na ji muryar wani mutum daga Ulai tana cewa, “Jibra’ilu, faɗa wa wannan mutum ma’anar wahayin.” ");
INSERT INTO hausa_vpl VALUES ("DN8_17","028_8_17","DAN","8","17","17","Da ya zo kusa da inda nake tsaye, na firgita na kuma fāɗi rubda ciki. Ya ce da ni “Ɗan mutum, ka gane da cewa wannan wahayi yana magana ne a kan kwanakin ƙarshe.” ");
INSERT INTO hausa_vpl VALUES ("DN8_18","028_8_18","DAN","8","18","18","Yayinda yake magana da ni, barci mai nauyi ya kwashe ni, da nake kwance rubda ciki. Sai ya taɓa ni ya kuma tashe ni tsaye. ");
INSERT INTO hausa_vpl VALUES ("DN8_19","028_8_19","DAN","8","19","19","Sai ya ce, “Zan faɗa maka abin da zai faru a lokacin fushi, saboda wahayin yana magana ne a kan lokacin da aka ƙayyade na ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("DN8_20","028_8_20","DAN","8","20","20","Rago mai ƙahoni biyu da ka gani, yana a madadin sarakunan Medes da Farisa ne. ");
INSERT INTO hausa_vpl VALUES ("DN8_21","028_8_21","DAN","8","21","21","Bunsurun kuwa sarkin Girka ne, kuma babban ƙahon da yake tsakanin idanunsa, sarki na farko ne. ");
INSERT INTO hausa_vpl VALUES ("DN8_22","028_8_22","DAN","8","22","22","Ƙahoni huɗu da suka maya wannan da ya karye yana a madadin masarautu huɗu da za su tashi daga cikin al’ummarsa amma ba za su sami irin ikonsa ba. ");
INSERT INTO hausa_vpl VALUES ("DN8_23","028_8_23","DAN","8","23","23","“Can wajen ƙarshe mulkinsu, sa’ad da muguntarsu ta kai intaha, wani mugun sarki mai rashin hankali, uban makirci, zai fito. ");
INSERT INTO hausa_vpl VALUES ("DN8_24","028_8_24","DAN","8","24","24","Zai yi ƙarfi ƙwarai da gaske, amma ba da ikonsa ba. Zai jawo mummunar hallakarwa kuma zai yi nasara a duk abin da ya sa gaba. Zai hallakar da majiya ƙarfi da kuma tsarkaka. ");
INSERT INTO hausa_vpl VALUES ("DN8_25","028_8_25","DAN","8","25","25","Zai sa yaudara ta ƙara yin yawa, zai ɗaukaka kansa. Sa’ad da suke ji sun sami mafaka, zai hallaka mutane da yawa sa’an nan kuma yă fara gāba da Sarkin sarakuna. Duk da haka za a hallaka shi, amma ba da ikon mutum ba. ");
INSERT INTO hausa_vpl VALUES ("DN8_26","028_8_26","DAN","8","26","26","“Wahayin nan na safiya da yamma da aka nuna maka gaskiya ne, amma ka ɓoye wahayin, gama ya shafi nan gaba mai tsawo ne.” ");
INSERT INTO hausa_vpl VALUES ("DN8_27","028_8_27","DAN","8","27","27","Ni, Daniyel, na gaji matuƙa na kuma yi rashin lafiya na kwanaki masu yawa. Sa’an nan sai na tashi na ci gaba da hidimar sarki. Wahayin ya shige mini duhu, ya fi ƙarfin fahimtata. ");
INSERT INTO hausa_vpl VALUES ("DN9_1","028_9_1","DAN","9","1","1","A shekara ta fari da mulkin Dariyus ɗan Zerzes (wanda yake Bamediye), wanda aka mai da shi sarki a masarautar Babiloniyawa ");
INSERT INTO hausa_vpl VALUES ("DN9_2","028_9_2","DAN","9","2","2","a shekara ta farko ta mulkinsa, ni, Daniyel na gane daga cikin littattafai, bisa ga maganar Ubangiji da aka faɗa wa annabi Irmiya, cewa zaman Urushalima kango zai kai shekara saba’in. ");
INSERT INTO hausa_vpl VALUES ("DN9_3","028_9_3","DAN","9","3","3","Sai na juya wurin Ubangiji Allah na roƙe shi ta wurin addu’a da koke-koke, cikin azumi, ina saye da tsummoki, na kuma zauna a cikin toka. ");
INSERT INTO hausa_vpl VALUES ("DN9_4","028_9_4","DAN","9","4","4","Na yi addu’a ga Ubangiji Allahna na furta laifina. “Ya Ubangiji, mai alfarma da kuma Allah mai banrazana, wanda yake cika alkawarinsa na ƙauna ga duk wanda ya ƙaunace shi ya kuma kiyaye dokokinsa, ");
INSERT INTO hausa_vpl VALUES ("DN9_5","028_9_5","DAN","9","5","5","mun yi zunubi muka kuma yi ba daidai ba. Mu mugaye ne da kuma ’yan tawaye; mun juya wa umarninka da shari’unka baya. ");
INSERT INTO hausa_vpl VALUES ("DN9_6","028_9_6","DAN","9","6","6","Ba mu saurari bayinka annabawa ba, waɗanda suka yi magana a sunanka ga sarakunanmu da masu mulkinmu da iyayenmu, da kuma dukan mutanen ƙasa. ");
INSERT INTO hausa_vpl VALUES ("DN9_7","028_9_7","DAN","9","7","7","“Ubangiji, kai mai adalci ne, amma a yau kunya ta rufe mu, mutanen Yahuda da mutanen Urushalima da na dukan Isra’ila, waɗanda suke kusa da kuma nesa, a dukan ƙasashen da ka warwatsa mu saboda rashin amincinmu a gare ka. ");
INSERT INTO hausa_vpl VALUES ("DN9_8","028_9_8","DAN","9","8","8","Ya Ubangiji, mu da sarakunanmu, da masu mulkinmu da iyayenmu kunya ta rufe mu saboda mun yi maka zunubi. ");
INSERT INTO hausa_vpl VALUES ("DN9_9","028_9_9","DAN","9","9","9","Ubangiji Allahnmu mai jinƙai ne, mai gafartawa ne kuma, ko da yake mun yi masa tawaye; ");
INSERT INTO hausa_vpl VALUES ("DN9_10","028_9_10","DAN","9","10","10","ba mu yi biyayya ga Ubangiji Allahnmu ba, ba mu kuma kiyaye shari’unsa da ya ba mu ta wuri bayinsa annabawa ba. ");
INSERT INTO hausa_vpl VALUES ("DN9_11","028_9_11","DAN","9","11","11","Dukan Isra’ila sun karya dokokinka suka kuma juya maka baya, sun ƙi yi maka biyayya. “Saboda haka la’anoni da rantsuwar hukunce-hukuncen da suke a rubuce a cikin Dokar Musa, bawan Allah, sun kama mu domin mun yi maka zunubi. ");
INSERT INTO hausa_vpl VALUES ("DN9_12","028_9_12","DAN","9","12","12","Ka cika kalmomin da ka yi a kanmu da kuma a kan masu mulkinmu ta wurin kawo mana babban bala’i. A duniya duka ba a taɓa yin wani abu kamar yadda aka yi wa Urushalima ba. ");
INSERT INTO hausa_vpl VALUES ("DN9_13","028_9_13","DAN","9","13","13","Kamar yadda yake a rubuce cikin Dokar Musa, dukan wannan bala’i ya sauko a kanmu, duk da haka ba mu nemi tagomashin Ubangiji Allahnmu ta wurin barin aikatawa zunubanmu, mu kuma mai da hankali a kan gaskiyarka ba. ");
INSERT INTO hausa_vpl VALUES ("DN9_14","028_9_14","DAN","9","14","14","Ubangiji bai yi wata-wata wajen kawo mana bala’i ba, domin Ubangiji Allahnmu mai adalci ne a cikin dukan abin da yake yi; duk da haka ba mu yi masa biyayya ba. ");
INSERT INTO hausa_vpl VALUES ("DN9_15","028_9_15","DAN","9","15","15","“Yanzu, ya Ubangiji Allahnmu, wanda ya fito da mutanensa daga Masar ta hannu mai ƙarfi wanda kuma ya yi wa kansa sunan da ya dawwama har yă zuwa yau, mun yi zunubi, mun yi abin da ba daidai ba. ");
INSERT INTO hausa_vpl VALUES ("DN9_16","028_9_16","DAN","9","16","16","Ya Ubangiji, ta wurin kiyaye dukan ayyukanka na adalci, ka huce daga fushinka da hukuncinka da ka yi a kan Urushalima, birninka, tudunka mai tsarki. Zunubinmu da laifofin iyayenmu sun mai da Urushalima da kuma mutanenka abin ba’a ga dukan waɗanda suke kewaye da mu. ");
INSERT INTO hausa_vpl VALUES ("DN9_17","028_9_17","DAN","9","17","17","“Yanzu, ya Allahnmu, ka ji addu’o’i da koke-koken bayinka. Saboda sunanka, ya Ubangiji, ka duba da rahama wurinka mai tsarki da ya zama kango. ");
INSERT INTO hausa_vpl VALUES ("DN9_18","028_9_18","DAN","9","18","18","Ka kasa kunne, ya Allah, ka kuma ji; ka buɗe idanunka ka kuma ga yadda birninka ya zama kango, birnin da yake ɗauke da Sunanka. Ba cewa muna roƙonka saboda mu masu adalci ba ne, amma saboda girman jinƙanka. ");
INSERT INTO hausa_vpl VALUES ("DN9_19","028_9_19","DAN","9","19","19","Ya Ubangiji, ka saurara! Ya Ubangiji ka gafarta! Ya Ubangiji, ka ji ka kuma yi wani abu! Saboda sunanka, ya Allahna, kada ka yi jinkiri, domin da sunanka ake kiran birninka da jama’arka.” ");
INSERT INTO hausa_vpl VALUES ("DN9_20","028_9_20","DAN","9","20","20","Yayinda da nake magana da addu’a, ina furta zunubina da zunubin mutanena Isra’ila ina miƙa koke-kokena ga Ubangiji Allahna saboda tudunsa mai tsarki, ");
INSERT INTO hausa_vpl VALUES ("DN9_21","028_9_21","DAN","9","21","21","yayinda nake cikin addu’a, sai Jibra’ilu, mutumin nan da na gani a wahayin da ya wuce, ya zo wurina gaggauce wajen lokacin yin hadaya ta yamma. ");
INSERT INTO hausa_vpl VALUES ("DN9_22","028_9_22","DAN","9","22","22","Ya umarce ni ya kuma ce mini, “Daniyel, yanzu na zo domin in ba ka hikima da ganewa. ");
INSERT INTO hausa_vpl VALUES ("DN9_23","028_9_23","DAN","9","23","23","Da zarar ka fara addu’a, an amsa, wadda na zo in faɗa maka, gama ana ƙaunar ka sosai. Saboda haka, ka yi lura da saƙon ka kuma fahimci wahayin. ");
INSERT INTO hausa_vpl VALUES ("DN9_24","028_9_24","DAN","9","24","24","“An ƙayyade wa jama’arka da tsattsarkan birninka shekara ɗari huɗu da tasa’in domin a kawo ƙarshen laifi da zunubi, domin a yi kafarar laifi, sa’an nan a shigo da adalci madawwami, a rufe wahayi da annabci, a tsarkake haikali. ");
INSERT INTO hausa_vpl VALUES ("DN9_25","028_9_25","DAN","9","25","25","“Sai ka sani ka kuma fahimci wannan; Tun daga sa’ad da aka kafa doka don a maido a kuma sāke gina Urushalima har sai Shafaffen nan, mai mulki, ya zo, za a yi shekara arba’in da tara, da shekara ɗari huɗu da talatin da huɗu. Za a sāke gina ta a yi mata tituna da mafaka. ");
INSERT INTO hausa_vpl VALUES ("DN9_26","028_9_26","DAN","9","26","26","Bayan shekara ɗari huɗu da talatin da huɗu, za a datse Shafaffen nan zai kuma kasance ba shi da kome. Mutanen mai mulkin za su zo su hallaka birnin da kuma wuri mai tsarki. Ƙarshen zai zo kamar rigyawa. Yaƙi zai ci gaba har ƙarshe, a kuma hallakar kamar yadda aka ƙaddara. ");
INSERT INTO hausa_vpl VALUES ("DN9_27","028_9_27","DAN","9","27","27","Zai tabbatar da alkawari da mutane masu yawa har na shekara bakwai. A tsakiyar bakwai ɗin nan ɗaya zai kawo ƙarshen duk wata hadaya da baiko. Kuma a kusurwar haikali zai sa abin ƙyama mai kawo hallaka, har sai ƙarshen da aka ƙaddara ya auko wa wanda ya sa abin ƙyama.” ");
INSERT INTO hausa_vpl VALUES ("DN10_1","028_10_1","DAN","10","1","1","A shekara ta uku ta Sairus sarkin Farisa, sai aka ba wa Daniyel (wanda ake kira Belteshazar) wahayi. Saƙon kuwa gaskiya ce wadda take tattare da babban yaƙi. Fahimtar saƙon ya zo masa a cikin wahayi. ");
INSERT INTO hausa_vpl VALUES ("DN10_2","028_10_2","DAN","10","2","2","A wannan lokaci ni Daniyel na yi makoki har na sati uku. ");
INSERT INTO hausa_vpl VALUES ("DN10_3","028_10_3","DAN","10","3","3","Ban ci abinci mai kyau ba; ba nama ko ruwa inabin da ya shiga bakina; kuma ba na amfani da man shafawa gaba ɗaya har sai da sati nan uku suka wuce. ");
INSERT INTO hausa_vpl VALUES ("DN10_4","028_10_4","DAN","10","4","4","A rana ta ashirin da huɗu ga watan farko, a sa’ad da nake tsaye a bakin babban kogi, Tigris, ");
INSERT INTO hausa_vpl VALUES ("DN10_5","028_10_5","DAN","10","5","5","na ɗaga kaina na duba sai ga wani mutum tsaye sanye da rigar lilin, ya yi ɗamara da zinariya zalla daga Ufaz kewaye da ƙugunsa. ");
INSERT INTO hausa_vpl VALUES ("DN10_6","028_10_6","DAN","10","6","6","Jikinsa kamar lu’ulu’u yake, fuskarsa kuma kamar walƙiya, idanunsa kamar harshen wuta, hannuwansa da ƙafafunsa kamar gogaggiyar tagulla, muryarsa kuma kamar amon babban taron jama’a. ");
INSERT INTO hausa_vpl VALUES ("DN10_7","028_10_7","DAN","10","7","7","Ni, Daniyel, kaɗai ne na ga wahayin; mutanen da suke tare da ni ba su gani ba, amma wata irin babbar razana ta auko musu har suka gudu suka ɓuya. ");
INSERT INTO hausa_vpl VALUES ("DN10_8","028_10_8","DAN","10","8","8","Sai aka bar ni ni kaɗai, ina juyayi wannan babban wahayi, ba ni da sauran ƙarfi, fuskata ta yamutse kuma ba ni da sauran ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("DN10_9","028_10_9","DAN","10","9","9","Sai na ji yana magana, da ina sauraronsa, sai na shiga barci mai nauyi, na kuwa fāɗi rubda ciki. ");
INSERT INTO hausa_vpl VALUES ("DN10_10","028_10_10","DAN","10","10","10","Sai hannu ya taɓa ni ya sa makyarkyata a hannuna da ƙafafuna. ");
INSERT INTO hausa_vpl VALUES ("DN10_11","028_10_11","DAN","10","11","11","Sai ya ce, “Daniyel, kai ne wanda ake ƙauna sosai, ka yi lura da kyau game da kalmomin da zan yi maka magana a kansu, ka tashi yanzu, gama an aiko ni a gare ka.” Sa’ad da ya faɗa mini haka, sai na tashi a tsaye ina rawan jiki. ");
INSERT INTO hausa_vpl VALUES ("DN10_12","028_10_12","DAN","10","12","12","Sai ya ci gaba da cewa, “Kada ka ji tsoro, Daniyel. Gama tun daga ran da ka fara sa zuciya ga neman ganewa, ka kuma ƙasƙantar da kanka a gaban Allahnka, an ji addu’arka, amsar addu’arka ce ta kawo ni. ");
INSERT INTO hausa_vpl VALUES ("DN10_13","028_10_13","DAN","10","13","13","Amma mai mulkin masarautar Farisa ya tsare ni har kwana ashirin da ɗaya. Sai da Mika’ilu, ɗaya daga cikin manya shugabanni, ya zo ya taimake ni, saboda an tsare ni a can tare da sarkin Farisa. ");
INSERT INTO hausa_vpl VALUES ("DN10_14","028_10_14","DAN","10","14","14","Yanzu na zo domin in bayyana maka abin da zai faru da mutanenka nan gaba, gama wahayin ya shafi lokacin da bai riga ya zo ba ne.” ");
INSERT INTO hausa_vpl VALUES ("DN10_15","028_10_15","DAN","10","15","15","Yayinda yake faɗin mini haka, sai na sunkuyar da kaina ƙasa shiru, ba magana. ");
INSERT INTO hausa_vpl VALUES ("DN10_16","028_10_16","DAN","10","16","16","Sai wani wanda ya yi kama da mutum ya taɓa leɓunana, na kuma buɗe bakina sai na fara magana. Na ce wa wannan da yake tsaye a gabana, “Na cika da azaba saboda wannan wahayi, ranka yă daɗe, ina kuma neman taimako. ");
INSERT INTO hausa_vpl VALUES ("DN10_17","028_10_17","DAN","10","17","17","Yaya ni bawanka zan iya magana da kai, ranka yă daɗe? Ƙarfina ya ƙare kuma ina numfashi da ƙyar.” ");
INSERT INTO hausa_vpl VALUES ("DN10_18","028_10_18","DAN","10","18","18","Har yanzu wannan wanda yana kama da mutum ya taɓa ni ya kuma ba ni ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("DN10_19","028_10_19","DAN","10","19","19","Ya kuma ce, “Kada ka ji tsoro, ya kai mutumin da ake fahariya, salama a gare ka! Ka ƙarfafa yanzu; ka yi ƙarfin hali.” Sa’ad da ya yi magana da ni, sai na samu ƙarfi na ce, “Ka yi magana ranka yă daɗe, tun da yake ka sa na sami ƙarfi.” ");
INSERT INTO hausa_vpl VALUES ("DN10_20","028_10_20","DAN","10","20","20","Sai ya ce mini, “Ka san abin da ya kawo ni gare ka? Ba da jimawa ba zan koma in yi yaƙi da mai mulkin Farisa, kuma idan na tafi, mai mulkin Hellenawa zai taso; ");
INSERT INTO hausa_vpl VALUES ("DN10_21","028_10_21","DAN","10","21","21","amma da farko zan faɗa maka abin da aka rubuta a cikin Littafin Gaskiya (Babu wanda ya taimake ni yaƙi da waɗannan sai dai Mika’ilu, sarkinku. ");
INSERT INTO hausa_vpl VALUES ("DN11_1","028_11_1","DAN","11","1","1","A shekara ta fari ta Dariyus mutumin Mede, na ɗauki matsayina domin in goyi baya in kuma kāre shi.) ");
INSERT INTO hausa_vpl VALUES ("DN11_2","028_11_2","DAN","11","2","2","“Yanzu dai, zan faɗa maka gaskiya. Sarakuna uku za su taso a Farisa, sa’an nan kuma na huɗu, wanda zai fi dukansu dukiya. Sa’ad da zai sami iko saboda dukiyarsa, zai zuga dukan kowane mutum yă yi gāba da masarautar Girka. ");
INSERT INTO hausa_vpl VALUES ("DN11_3","028_11_3","DAN","11","3","3","Sa’an nan wani babban sarki zai bayyana, wanda zai yi mulki da babban iko yă kuma yi abin da ya ga dama. ");
INSERT INTO hausa_vpl VALUES ("DN11_4","028_11_4","DAN","11","4","4","Bayan da ya bayyana, daularsa za tă wargaje za a rarraba ta zuwa kusurwoyi huɗu na duniya, a ba waɗansu waɗanda ba zuriyarsa ba, ba kuwa za su yi mulki da iko kamar yadda ya yi ba, gama za a tumɓuki daularsa a kuma ba wa waɗansu. ");
INSERT INTO hausa_vpl VALUES ("DN11_5","028_11_5","DAN","11","5","5","“Sai sarki Kudu zai yi ƙarfi ƙwarai, amma ɗaya daga cikin komandodinsa zai yi ƙarfi fiye da shi, zai kuma yi mulki masarautarsa da iko mai girma. ");
INSERT INTO hausa_vpl VALUES ("DN11_6","028_11_6","DAN","11","6","6","Bayan ’yan shekaru, za su haɗa kai. Diyar sarkin Kudu za tă je wurin sarkin Arewa ta sada zumunci, amma ba za tă riƙe iko ba, shi kuwa da ikonsa ba za su daɗe ba. A waɗannan kwanaki za a bashe ta, da ita da masu rakiyarta da kuma mahaifinta da kuma wanda ya goyi bayanta. ");
INSERT INTO hausa_vpl VALUES ("DN11_7","028_11_7","DAN","11","7","7","“Wani daga cikin zuriyarta zai taso yă ɗauki matsayinta. Zai kai wa sojojin sarkin Arewa hari yă kuma shiga kagararsa; zai yi yaƙi da su yă kuma yi nasara. ");
INSERT INTO hausa_vpl VALUES ("DN11_8","028_11_8","DAN","11","8","8","Zai ƙwace allolinsu, siffofinsu na ƙarfe da kuma kaya masu daraja na azurfa da na zinariya a kuma kai su Masar. Zai yi ’yan shekaru bai kai wa sarkin Arewa yaƙi ba. ");
INSERT INTO hausa_vpl VALUES ("DN11_9","028_11_9","DAN","11","9","9","Sa’an nan sarkin Arewa zai kai wa sarkin Kudu hari, amma zai janye, yă koma ƙasarsa. ");
INSERT INTO hausa_vpl VALUES ("DN11_10","028_11_10","DAN","11","10","10","’Ya’yansa maza za su yi shirin yaƙi za su kuma tattara babbar rundunar sojoji, waɗanda za su yi ta mamayewa kamar rigyawar da ba iya tarewa, kuma za su kai yaƙin har kagararsa. ");
INSERT INTO hausa_vpl VALUES ("DN11_11","028_11_11","DAN","11","11","11","“Sa’an nan sai sarkin Kudu zai kama hanya da fushi zuwa yaƙi da sarkin Arewa, wanda zai tattara babbar rundunar yaƙi, amma za a ci shi da yaƙi. ");
INSERT INTO hausa_vpl VALUES ("DN11_12","028_11_12","DAN","11","12","12","Sa’ad da zai kawar da rundunar, sarkin Kudu zai cika da girman kai zai kuma kashe mutane dubbai, duk da haka ba zai kasance mai nasara ba. ");
INSERT INTO hausa_vpl VALUES ("DN11_13","028_11_13","DAN","11","13","13","Sarki Arewa kuma zai ƙara tara babbar rundunar soja, wadda ta fi ta dā girma; bayan waɗansu shekaru kuma, zai tafi yaƙi da babbar rundunar mayaƙa cike da kayan yaƙi. ");
INSERT INTO hausa_vpl VALUES ("DN11_14","028_11_14","DAN","11","14","14","“A waɗannan lokutan mutane da yawa za su tashi gāba da sarkin Kudu. Amma waɗansu ’yan kama-karya za su taso daga jama’arka da niyya su cika abin da wahayin ya ce, amma za a fatattake su. ");
INSERT INTO hausa_vpl VALUES ("DN11_15","028_11_15","DAN","11","15","15","Sa’an nan sarkin arewa zai zo ya gina mahaurai a jikin katagar birni don yă ci birnin da yaƙi. Sojojin nan na Kudu kuwa ba za su iya tsayawa ba, ko zaɓaɓɓun jarumawansu ma, gama za su rasa ƙarfin tsayawa. ");
INSERT INTO hausa_vpl VALUES ("DN11_16","028_11_16","DAN","11","16","16","Wanda ya kai harin zai yi yadda ya ga dama, ba wanda zai iya ja da shi. Zai kafa kansa a Kyakkyawar Ƙasa zai kuma sami ikon da zai hallaka ta. ");
INSERT INTO hausa_vpl VALUES ("DN11_17","028_11_17","DAN","11","17","17","Zai yunƙura yă zo da ƙarfin dukan masarautarsa zai kuma nemi haɗinkan sarkin Kudu. Zai kuma ba shi diyarsa yă aura don yă lalatar da mulkin, amma shirinsa ba zai yi nasara ba ko yă taimake shi ba. ");
INSERT INTO hausa_vpl VALUES ("DN11_18","028_11_18","DAN","11","18","18","Sa’an nan zai mai da hankalinsa zuwa ƙasashe a bakin kogi, zai kuma kama da yawansu, amma wani komanda zai kawo ƙarshen faɗin ransa, zai kuma sa faɗin ransa yă koma masa. ");
INSERT INTO hausa_vpl VALUES ("DN11_19","028_11_19","DAN","11","19","19","Bayan wannan, zai juya ga kagarar ƙasarsa, amma zai yi tuntuɓe yă fāɗi, ba kuwa za a ƙara ganinsa ba. ");
INSERT INTO hausa_vpl VALUES ("DN11_20","028_11_20","DAN","11","20","20","“Magājinsa zai aiki mai karɓar haraji don darajar masarautarsa. Amma ba da daɗewa ba za a hallaka shi, duk da haka ba da fushi ko cikin yaƙi ba. ");
INSERT INTO hausa_vpl VALUES ("DN11_21","028_11_21","DAN","11","21","21","“Magājin wannan sarki zai zama wani mutumin banza wanda ma bai fito daga gidan sarauta ba. Zai taso ba zato ba tsammani, yă ƙwace sarautar ta hanyar zamba. ");
INSERT INTO hausa_vpl VALUES ("DN11_22","028_11_22","DAN","11","22","22","Sa’an nan zai shafe mayaƙa masu yawa a gabansa; zai hallaka har da waɗanda suke mulki na alkawari. ");
INSERT INTO hausa_vpl VALUES ("DN11_23","028_11_23","DAN","11","23","23","Bayan ƙulla yarjejjeniya da shi, zai yi zamba cikin aminci, kuma zai sami damar hawan mulki da goyon baya mutane kaɗan. ");
INSERT INTO hausa_vpl VALUES ("DN11_24","028_11_24","DAN","11","24","24","Sa’ad da yankuna mafi arziki suke ji kome lafiya yake, zai kai musu hari kuma Zai aikata abin da kakanninsa ba su taɓa yi ba. Zai rarraba abin da aka kwaso daga yaƙi, da ganima, da dukiya ga dukan mabiyansa. Zai kuma yi shiri yă kai wa mafaka hari, amma na ɗan lokaci ne kawai. ");
INSERT INTO hausa_vpl VALUES ("DN11_25","028_11_25","DAN","11","25","25","“Tare da babbar rundunar mayaƙa zai yi ƙarfin hali yă far wa sarkin Kudu da yaƙi. Sarkin kudu zai haɗa babbar rundunar soja mai ƙarfi don yaƙin, amma ba zai iya karo da shi ba, domin za a shirya masa maƙarƙashiya. ");
INSERT INTO hausa_vpl VALUES ("DN11_26","028_11_26","DAN","11","26","26","Waɗanda suke ci daga tanadin sarki za su yi ƙoƙari su hallaka shi; za a share mayaƙansa, kuma za a kashe mutane masu yawa a yaƙin. ");
INSERT INTO hausa_vpl VALUES ("DN11_27","028_11_27","DAN","11","27","27","Sarakunan nan biyu sun sa mugunta a ransu. Za su zauna a tebur guda su yi ta shara wa juna ƙarya, amma a banza, gama lokacin da aka ƙayyade bai yi ba tukuna. ");
INSERT INTO hausa_vpl VALUES ("DN11_28","028_11_28","DAN","11","28","28","“Sarkin Arewa zai koma ƙasarsa da dukiya mai girma, amma zuciyarsa za tă yi gāba da tsattsarkan alkawari. Zai ɗauki mataki a kan wannan abu sa’an nan yă koma ƙasarsa. ");
INSERT INTO hausa_vpl VALUES ("DN11_29","028_11_29","DAN","11","29","29","“A ƙayyadadden lokaci zai sāke kai wa Kudu hari, amma a wannan karo abin da zai faru zai sha bamban daga abin da ya faru can baya. ");
INSERT INTO hausa_vpl VALUES ("DN11_30","028_11_30","DAN","11","30","30","Jiragen ruwa yammancin bakin teku za su yi gāba da shi, zuciyarsa kuwa za tă yi sanyi. Sa’an nan zai juya ya huce haushinsa a kan tsattsarkan alkawari. Zai komo yă nuna jinƙai ga waɗanda suka juya wa tsattsarkan alkawari baya. ");
INSERT INTO hausa_vpl VALUES ("DN11_31","028_11_31","DAN","11","31","31","“Mayaƙansa za su taso su ƙazantar da kagarar haikali za su kuma kawar da hadaya ta kullum. Sa’an nan za su kafa abin banƙyama da yake lalatarwa. ");
INSERT INTO hausa_vpl VALUES ("DN11_32","028_11_32","DAN","11","32","32","Ta wurin daɗin baki zai gurɓata waɗannan da suka karya alkawari, amma mutanen da suka san Allahnsu za su yi tsayin daka su yi jayayya da shi. ");
INSERT INTO hausa_vpl VALUES ("DN11_33","028_11_33","DAN","11","33","33","“Waɗanda suke da hikima za su wayar da kan mutane da yawa, duk da haka za a kashe su da takobi, waɗansu da wuta, a washe waɗansu a kai su bauta. ");
INSERT INTO hausa_vpl VALUES ("DN11_34","028_11_34","DAN","11","34","34","Sa’ad da suka fāɗi, za su sami ɗan taimako, mutane da yawa za su haɗa kai da su, amma da munafunci. ");
INSERT INTO hausa_vpl VALUES ("DN11_35","028_11_35","DAN","11","35","35","Waɗansu masu hikima za su yi tuntuɓe, don a tsabtacce su, a tsarkake su, su yi tsab, har matuƙar da aka ƙayyade ta yi. ");
INSERT INTO hausa_vpl VALUES ("DN11_36","028_11_36","DAN","11","36","36","“Sarkin zai yi abin da ya ga dama. Zai ɗaukaka yă kuma girmama kansa gaba da kowane allah zai kuma faɗa munanan abubuwa a kan Allahn alloli. Zai yi nasara har sai lokacin hukunci ya cika, gama abin da aka ƙaddara zai cika. ");
INSERT INTO hausa_vpl VALUES ("DN11_37","028_11_37","DAN","11","37","37","Ba zai kula da alloli iyayensa ba ko wanda mata suke sha’awa, balle ma yă ga darajar wani allah, amma zai ɗaukaka kansa gaba da su duka. ");
INSERT INTO hausa_vpl VALUES ("DN11_38","028_11_38","DAN","11","38","38","A maimakonsu, zai ɗaukaka allahn kagarai; allahn da kakanninsa ba su ko sani ba, shi ne zai miƙa masa zinariya, da azurfa, da duwatsu masu daraja, da abubuwa masu tsada. ");
INSERT INTO hausa_vpl VALUES ("DN11_39","028_11_39","DAN","11","39","39","Zai kai wa kagarai mafi ƙarfi hari da taimakon baƙon allah zai kuma girmama waɗanda suka yarda da shi zai ba su girma, ya kuma shugabantar da su a kan mutane da yawa, zai raba musu ƙasa ta zama ladansu. ");
INSERT INTO hausa_vpl VALUES ("DN11_40","028_11_40","DAN","11","40","40","“A lokaci ƙarshe sarkin Kudu zai tasar masa da yaƙi, sarkin Arewa kuwa zai tunzura, yă tasar masa da kekunan yaƙi da mahayan dawakai, da jiragen ruwa da yawa. Zai ratsa ƙasashe, yă ci su da yaƙi, yă wuce. ");
INSERT INTO hausa_vpl VALUES ("DN11_41","028_11_41","DAN","11","41","41","Zai kuma mamaye Kyakkyawa Ƙasa. Ƙasashe masu yawa za su fāɗi, amma Edom, Mowab da kuma shugabannin Ammon za su kuɓuta daga hannunsa. ");
INSERT INTO hausa_vpl VALUES ("DN11_42","028_11_42","DAN","11","42","42","Zai fadada mulkinsa har zuwa ƙasashe masu yawa; Masar ma ba za tă tsira ba. ");
INSERT INTO hausa_vpl VALUES ("DN11_43","028_11_43","DAN","11","43","43","Zai mallaki dukiyoyi na zinariya, da na azurfa, da dukan abubuwa masu tsada na Masar. Zai kuma ci Libiyawa da Kush da yaƙi. ");
INSERT INTO hausa_vpl VALUES ("DN11_44","028_11_44","DAN","11","44","44","Amma labari daga gabas da arewa za su firgita shi, shi kuwa zai ci gaba da yin yaƙi da zafi, yă karkashe mutane da yawa, yă shafe su. ");
INSERT INTO hausa_vpl VALUES ("DN11_45","028_11_45","DAN","11","45","45","Zai kafa tentin mulkinsa tsakanin tekunan da suke a kyakkyawan tsauni mai tsarki. Duk da haka zai zo ga ƙarshensa, kuma babu wanda zai taimake shi. ");
INSERT INTO hausa_vpl VALUES ("DN12_1","028_12_1","DAN","12","1","1","“A wannan lokaci Mika’ilu, babban mai mulki wanda yake kāre mutanenka, zai tashi. Za a yi lokacin matsananciyar wahala wanda ba a taɓa yi tun farkon ƙasashe har zuwa yanzu. Amma a lokacin da mutanenka, kowane mutum wanda aka sami sunansa a rubuce a cikin littafin, za a cece shi. ");
INSERT INTO hausa_vpl VALUES ("DN12_2","028_12_2","DAN","12","2","2","Ɗumbun mutanen da suka yi barci cikin turɓayar duniya za su farka, waɗansu zuwa ga rai madawwami, waɗansu zuwa ga madawwamiyar kunya da kuma madawwamin ƙasƙanci. ");
INSERT INTO hausa_vpl VALUES ("DN12_3","028_12_3","DAN","12","3","3","Waɗanda suke da hikima za su haskaka kamar hasken samaniya, waɗanda kuma suka jagoranci waɗansu da yawa zuwa adalci, za su zama kamar taurari har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("DN12_4","028_12_4","DAN","12","4","4","Amma kai, Daniyel, ka rufe zancen nan ka kuma liƙe kalmomin littafin nan har sai ƙarshe. Mutane da yawa za su yi ta kai komo don neman sani.” ");
INSERT INTO hausa_vpl VALUES ("DN12_5","028_12_5","DAN","12","5","5","Sa’an nan ni, Daniyel, na duba, a gabana kuwa ga waɗansu mutum biyu tsaye, ɗaya a wannan hayen kogi ɗaya kuma a ƙetaren kogin. ");
INSERT INTO hausa_vpl VALUES ("DN12_6","028_12_6","DAN","12","6","6","Ɗayansu ya ce wa mutumin da yake sanye da tufafin lilin, wanda yake a saman ruwan kogin, “Har yaushe waɗannan abubuwan banmamakin za su cika?” ");
INSERT INTO hausa_vpl VALUES ("DN12_7","028_12_7","DAN","12","7","7","Mutumin da yake sanye da tufafin lilin, wanda yake a saman ruwan kogin, ya ɗaga hannun damansa da kuma na hagunsa sama, sai na ji yana rantsuwa da wannan da yake raye har abada, yana cewa, “Zai kasance na ɗan lokaci, lokuta da rabin lokaci. Za a kammala waɗannan abubuwa, sa’ad da aka gama ragargaje ikon tsarkakan mutane.” ");
INSERT INTO hausa_vpl VALUES ("DN12_8","028_12_8","DAN","12","8","8","Na kuma ji, amma ban fahimta ba. Don haka sai na yi tambaya, “Ranka yă daɗe, mene ne ƙarshen waɗannan abubuwa?” ");
INSERT INTO hausa_vpl VALUES ("DN12_9","028_12_9","DAN","12","9","9","Sai ya amsa ya ce, “Ka kama hanyarka, Daniyel, domin a rufe kalmomin aka kuma liƙe su har sai ƙarshen lokaci. ");
INSERT INTO hausa_vpl VALUES ("DN12_10","028_12_10","DAN","12","10","10","Za a tsarkake mutane da yawa, za a maishe su marasa aibi a kuma tace su; amma mugaye za su ci gaba da mugunta. Babu wani mugun da zai fahimta, amma waɗanda za su zama masu hikima za su fahimta. ");
INSERT INTO hausa_vpl VALUES ("DN12_11","028_12_11","DAN","12","11","11","“Daga lokacin da za a hana miƙa hadayar ƙonawa ta yau da kullum, a kuma kafa abin banƙyama, wanda yake lalatarwa, za a yi kwana 1,290. ");
INSERT INTO hausa_vpl VALUES ("DN12_12","028_12_12","DAN","12","12","12","Mai albarka ne wanda ya jira har yă zuwa ƙarshen kwanakin nan 1,335. ");
INSERT INTO hausa_vpl VALUES ("DN12_13","028_12_13","DAN","12","13","13","“Gare ka dai, ka yi tafiyarka har zuwa ƙarshe. Za ka huta, sa’an nan a ƙarshen kwanaki za ka tashi don karɓi sashen gadon da aka ba ka.”");
INSERT INTO hausa_vpl VALUES ("HS1_1","029_1_1","HOS","1","1","1","Maganar Ubangiji da ta zo wa Hosiya ɗan Beyeri a zamanin mulkin Uzziya, Yotam, Ahaz da Hezekiya, sarakunan Yahuda, da zamanin mulkin Yerobowam ɗan Yowash sarkin Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("HS1_2","029_1_2","HOS","1","2","2","Sa’ad da Ubangiji ya fara magana ta wurin Hosiya, Ubangiji ya ce masa, “Ka tafi, ka auro wa kanka mazinaciya da ’ya’yan da aka haifa ta hanyar rashin aminci, domin ƙasar tana da laifin mummunan zina ta wurin rabuwa da Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("HS1_3","029_1_3","HOS","1","3","3","Saboda haka sai ya auri Gomer ’yar Dibilayim, ta kuwa yi ciki ta haifi ɗa namiji. ");
INSERT INTO hausa_vpl VALUES ("HS1_4","029_1_4","HOS","1","4","4","Sai Ubangiji ya ce wa Hosiya, “Ka ba shi suna Yezireyel, domin ba da daɗewa ba zan hukunta gidan Yehu saboda kisan da aka yi a Yezireyel, zan kuma kawo ƙarshen mulkin Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("HS1_5","029_1_5","HOS","1","5","5","A wannan rana zan karye ƙarfin Isra’ila a Kwarin Yezireyel.” ");
INSERT INTO hausa_vpl VALUES ("HS1_6","029_1_6","HOS","1","6","6","Gomer ta sāke ɗauki ciki ta kuma haifi ’ya mace. Sai Ubangiji ya ce wa Hosiya, “Ka ba ta suna, Lo-Ruhama, gama ba zan ƙara nuna wa gidan Isra’ila ƙauna ba, har da zan gafarta musu. ");
INSERT INTO hausa_vpl VALUES ("HS1_7","029_1_7","HOS","1","7","7","Duk da haka zan nuna ƙauna ga gidan Yahuda; zan kuma cece su, ba da baka, takobi ko yaƙi ba, ko ta wurin dawakai, ko masu hawan dawakai ba, sai ko ta wurin Ubangiji Allahnsu.” ");
INSERT INTO hausa_vpl VALUES ("HS1_8","029_1_8","HOS","1","8","8","Bayan ta yaye Lo-Ruhama, sai Gomer ta sāke haifi wani ɗa namiji. ");
INSERT INTO hausa_vpl VALUES ("HS1_9","029_1_9","HOS","1","9","9","Sai Ubangiji ya ce, “Ka ba shi suna Lo-Ammi, gama ku ba mutanena ba ne, ni kuma ba Allahnku ba ne. ");
INSERT INTO hausa_vpl VALUES ("HS1_10","029_1_10","HOS","1","10","10","“Duk da haka Isra’ilawa za su zama kamar yashi a bakin teku, da ba za a iya aunawa ko a ƙirga ba. A inda aka ce musu, ‘Ku ba mutanena ba ne,’ za a kira su ‘’ya’yan Allah mai rai.’ ");
INSERT INTO hausa_vpl VALUES ("HS1_11","029_1_11","HOS","1","11","11","Mutanen Yahuda da mutanen Isra’ila za su sāke haɗu su zama ɗaya, za su kuma naɗa shugaba guda su kuma fita daga ƙasar, gama ranar za tă zama mai girma wa Yezireyel. ");
INSERT INTO hausa_vpl VALUES ("HS2_1","029_2_1","HOS","2","1","1","“Ka ce da ’yan’uwanka maza, ‘Mutanena,’ ka kuma ce da ’yan’uwanka mata, ‘Ƙaunatacciyata.’ ");
INSERT INTO hausa_vpl VALUES ("HS2_2","029_2_2","HOS","2","2","2","“Ka tsawata wa mahaifiyarka, ka tsawata mata, gama ita ba matata ba ce, ni kuma ba mijinta ba ne. Ku roƙe ta tă daina karuwancinta da kuma rashin aminci a tsakanin nononta. ");
INSERT INTO hausa_vpl VALUES ("HS2_3","029_2_3","HOS","2","3","3","In ba haka ba zai tuɓe ta tsirara in bar ta kamar yadda take a ranar da aka haife ta; zan sa ta zama kamar hamada, in mayar da ita busasshiyar ƙasar, in kashe ta da ƙishirwa. ");
INSERT INTO hausa_vpl VALUES ("HS2_4","029_2_4","HOS","2","4","4","Ba zan nuna wa ’ya’yanta ƙaunata ba, domin su ’ya’yan zina ne. ");
INSERT INTO hausa_vpl VALUES ("HS2_5","029_2_5","HOS","2","5","5","Mahaifiyarsu ta yi rashin aminci ta kuma ɗauki cikinsu ta wurin yi abin kunya. Ta ce, ‘Zan bi kwartayena, waɗanda suke ba ni abinci da ruwa, ulu nawa da lilina, mai nawa da kuma abin sha na.’ ");
INSERT INTO hausa_vpl VALUES ("HS2_6","029_2_6","HOS","2","6","6","Saboda haka zai tare hanyarta da ƙaya; zan yi mata katanga don kada tă sami hanya. ");
INSERT INTO hausa_vpl VALUES ("HS2_7","029_2_7","HOS","2","7","7","Za tă bi kwartayenta amma ba za tă kama su ba; za tă neme su amma ba za tă same su ba. Sa’an nan za tă ce, ‘Zan koma ga mijina na fari, gama dā ya fi mini yadda nake a yanzu.’ ");
INSERT INTO hausa_vpl VALUES ("HS2_8","029_2_8","HOS","2","8","8","Ba ta yarda cewa ni ne wanda ya ba ta hatsi, sabon ruwan inabi da mai ba, wanda ya jibge mata azurfa da zinariya, waɗanda suka yi amfani wa Ba’al ba. ");
INSERT INTO hausa_vpl VALUES ("HS2_9","029_2_9","HOS","2","9","9","“Saboda haka zan ƙwace hatsina sa’ad da ya nuna, da sabon ruwan inabina sa’ad da ya ƙosa. Zan karɓe ulu nawa da lilina, da take niyya ta rufe tsiraicinta. ");
INSERT INTO hausa_vpl VALUES ("HS2_10","029_2_10","HOS","2","10","10","Saboda haka yanzu zan buɗe tsiraicinta a idanun kwartayenta; ba wani da zai ƙwace ta daga hannuwana. ");
INSERT INTO hausa_vpl VALUES ("HS2_11","029_2_11","HOS","2","11","11","Zan tsayar da dukan bukukkuwarta, bukukkuwarta na shekara-shekara, da kuma kiyaye bikin Sababbin Wata nata, kwanakin Asabbacinta, dukan ƙayyadaddun bukukkuwarta. ");
INSERT INTO hausa_vpl VALUES ("HS2_12","029_2_12","HOS","2","12","12","Zan lalatar da inabinta da kuma itatuwan ɓaurenta, waɗanda take cewa su ne abin da kwartayenta suka biya; zan mayar da su kurmi, namun jeji kuwa za su ci su. ");
INSERT INTO hausa_vpl VALUES ("HS2_13","029_2_13","HOS","2","13","13","Zan hukunta ta saboda kwanakin da ta ƙone turare wa Ba’al; ta yi wa kanta ado da zobai da duwatsu masu daraja, ta bi kwartayenta, amma ta manta da ni,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("HS2_14","029_2_14","HOS","2","14","14","“Saboda haka yanzu zan rarrashe ta; zan bishe ta zuwa hamada in kuma yi mata magana a hankali. ");
INSERT INTO hausa_vpl VALUES ("HS2_15","029_2_15","HOS","2","15","15","A can zan mayar mata da gonakin inabinta, zan kuma sa Kwarin Akor yă zama ƙofar bege. A can za tă rera kamar a kwanakin ƙuruciyarta, kamar a lokacin da ta fita daga Masar. ");
INSERT INTO hausa_vpl VALUES ("HS2_16","029_2_16","HOS","2","16","16","“A waccan rana,” in ji Ubangiji, “za ki ce da ni ‘mijina’; ba za ki ƙara ce ni ‘maigidana’ ba. ");
INSERT INTO hausa_vpl VALUES ("HS2_17","029_2_17","HOS","2","17","17","Zan cire sunayen Ba’al daga leɓunanta; ba za a ƙara kira sunayensu ba. ");
INSERT INTO hausa_vpl VALUES ("HS2_18","029_2_18","HOS","2","18","18","A waccan rana zan yi alkawari dominsu da namun jeji da kuma tsuntsayen sararin sama da dukan halittu masu rarrafe a ƙasa. Baka da takobi da yaƙi zan sa su ƙare a ƙasar, domin duk su zauna lafiya. ");
INSERT INTO hausa_vpl VALUES ("HS2_19","029_2_19","HOS","2","19","19","Zan ɗaura aure da ke har abada; zan ɗaura aure da yake cikin adalci da gaskiya, cikin ƙauna da jinƙai. ");
INSERT INTO hausa_vpl VALUES ("HS2_20","029_2_20","HOS","2","20","20","Zan ɗaura aure da yake cikin aminci za ki kuwa yarda cewa ni ne Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("HS2_21","029_2_21","HOS","2","21","21","“A waccan rana zan amsa,” in ji Ubangiji, “zan amsa wa sararin sama, za su kuwa amsa wa ƙasa; ");
INSERT INTO hausa_vpl VALUES ("HS2_22","029_2_22","HOS","2","22","22","ƙasa kuma za tă amsa wa hatsi, sabon ruwan inabi da kuma mai, su kuma za su amsa wa Yezireyel. ");
INSERT INTO hausa_vpl VALUES ("HS2_23","029_2_23","HOS","2","23","23","Zan dasa ta wa kaina a ƙasar; zan shuka ƙaunata ga wanda na ce ‘Ba ƙaunatacciyata ba.’ Zan faɗa wa waɗanda a ce ‘Ba mutanena ba,’ ‘Ku mutanena ne’; za su kuwa ce, ‘Kai ne Allahna.’ ” ");
INSERT INTO hausa_vpl VALUES ("HS3_1","029_3_1","HOS","3","1","1","Ubangiji ya ce mini, “Ka tafi, ka sāke nuna wa matarka ƙauna, ko da yake wani yana son ta, ita kuma mazinaciya ce. Ka ƙaunace ta yadda Ubangiji yake ƙaunar Isra’ilawa, ko da yake sun juya ga waɗansu alloli suna kuma ƙauna wainar zabibi mai tsarki.” ");
INSERT INTO hausa_vpl VALUES ("HS3_2","029_3_2","HOS","3","2","2","Ta haka na saye ta da shekel goma sha biyar na azurfa da kuma wajen buhu na sha’ir. ");
INSERT INTO hausa_vpl VALUES ("HS3_3","029_3_3","HOS","3","3","3","Sai na faɗa mata, “Za ki zauna tare da ni kwanaki masu yawa; kada ki yi karuwanci ko ki yi abuta da wani namiji, ni kuwa zan zauna tare da ke.” ");
INSERT INTO hausa_vpl VALUES ("HS3_4","029_3_4","HOS","3","4","4","Gama Isra’ilawa za su yi kwanaki masu yawa ba tare da sarki ko shugaba ba, babu hadaya ko keɓaɓɓun duwatsu, babu efod ko gunki. ");
INSERT INTO hausa_vpl VALUES ("HS3_5","029_3_5","HOS","3","5","5","Daga baya Isra’ilawa za su dawo su nemi Ubangiji Allahnsu da kuma Dawuda sarkinsu. Za su je da rawan jiki wajen Ubangiji da kuma ga albarkunsa a kwanakin ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("HS4_1","029_4_1","HOS","4","1","1","Ku ji maganar Ubangiji, ku Isra’ilawa, gama Ubangiji yana da tuhumar da zai kawo a kan ku waɗanda suke zama a ƙasar. “Babu aminci, babu ƙauna, babu yarda da Allah a cikin ƙasar. ");
INSERT INTO hausa_vpl VALUES ("HS4_2","029_4_2","HOS","4","2","2","Akwai la’ana ce kawai, yin ƙarya da kisa, yin sata da zina; sun wuce gona da iri, kisankai a kan kisankai. ");
INSERT INTO hausa_vpl VALUES ("HS4_3","029_4_3","HOS","4","3","3","Saboda wannan ƙasar tana makoki, kuma dukan waɗanda suke zama a cikinta sun lalace; namun jeji da tsuntsayen sararin sama da kuma kifin teku suna mutuwa. ");
INSERT INTO hausa_vpl VALUES ("HS4_4","029_4_4","HOS","4","4","4","“Amma kada wani mutum yă kawo tuhuma, kada wani mutum yă zargi wani, gama mutanenka suna kama da waɗanda suke kawo tuhume-tuhume a kan firist ne. ");
INSERT INTO hausa_vpl VALUES ("HS4_5","029_4_5","HOS","4","5","5","Kuna tuntuɓe dare da rana, annabawa ma suna tuntuɓe tare da ku. Saboda haka zan hallaka mahaifiyarku, ");
INSERT INTO hausa_vpl VALUES ("HS4_6","029_4_6","HOS","4","6","6","mutanena suna hallaka saboda jahilci. “Domin kun ƙi neman sani, ni ma na ƙi ku a matsayin firistocina; domin kun ƙyale dokar Allahnku, ni ma zan ƙyale ’ya’yanku. ");
INSERT INTO hausa_vpl VALUES ("HS4_7","029_4_7","HOS","4","7","7","Yawan ƙaruwar firistoci, haka suke yawan zunubi a kaina; sun yi musaya Ɗaukakarsu da wani abin kunya. ");
INSERT INTO hausa_vpl VALUES ("HS4_8","029_4_8","HOS","4","8","8","Suna ciyar da kansu a kan zunuban mutanena suna kuma haɗamar muguntarsu. ");
INSERT INTO hausa_vpl VALUES ("HS4_9","029_4_9","HOS","4","9","9","Zai kuwa zama, kamar yadda mutane suke, haka firistoci suke. Zan hukunta dukansu saboda al’amuransu in kuma sāka musu saboda ayyukansu. ");
INSERT INTO hausa_vpl VALUES ("HS4_10","029_4_10","HOS","4","10","10","“Za su ci amma ba za su ƙoshi ba; za su shiga karuwanci amma ba za su ƙaru ba, gama sun rabu da Ubangiji don su ba da kansu ");
INSERT INTO hausa_vpl VALUES ("HS4_11","029_4_11","HOS","4","11","11","ga karuwanci, ga tsoho da kuma sabon ruwan inabi, waɗanda suka ɗauke ganewar mutanena. ");
INSERT INTO hausa_vpl VALUES ("HS4_12","029_4_12","HOS","4","12","12","Sun nemi shawarar gunkin da aka yi da itace suka kuwa sami amsa daga sanda. Halin karuwanci yakan ɓad da su; sun yi rashin aminci ga Allahnsu. ");
INSERT INTO hausa_vpl VALUES ("HS4_13","029_4_13","HOS","4","13","13","Suna miƙa hadaya a kan ƙwanƙolin duwatsu suna kuma ƙone hadayu a kan tuddai, a ƙarƙashin itatuwa oak, aduruku da katambiri, inda inuwa take da daɗi. Saboda haka ’ya’yanku mata suka juya wa karuwanci surukanku mata kuma suka shiga yin zina. ");
INSERT INTO hausa_vpl VALUES ("HS4_14","029_4_14","HOS","4","14","14","“Ba zan hukunta ’ya’yanku mata sa’ad da suka juya ga yin karuwanci ba, balle surukanku mata, sa’ad da suka yi zina, gama mazan da kansu suna ma’amala da karuwai suna kuma miƙa hadaya tare da karuwai na masujada, mutane marasa ganewa za su lalace! ");
INSERT INTO hausa_vpl VALUES ("HS4_15","029_4_15","HOS","4","15","15","“Ko da yake kun yi zina, ya Isra’ila, kada Yahuda ya yi laifi. “Kada ku tafi Gilgal; kada ku haura zuwa Bet-Awen. Kuma kada ku rantse cewa, ‘Muddin Ubangiji yana a raye!’ ");
INSERT INTO hausa_vpl VALUES ("HS4_16","029_4_16","HOS","4","16","16","Isra’ilawa masu taurinkai ne, kamar karsana mai taurinkai. Yaya Ubangiji zai iya kiwonsu kamar tumaki a makiyaya mai ɗanyar ciyawa? ");
INSERT INTO hausa_vpl VALUES ("HS4_17","029_4_17","HOS","4","17","17","Efraim ya haɗa kai da gumaka; ku ƙyale shi kurum! ");
INSERT INTO hausa_vpl VALUES ("HS4_18","029_4_18","HOS","4","18","18","Ko ma sa’ad da abin shansu ya ƙare, sai suka ci gaba da karuwancinsu; masu mulkinsu suna ƙaunar abin kunya. ");
INSERT INTO hausa_vpl VALUES ("HS4_19","029_4_19","HOS","4","19","19","Guguwa za tă share su, hadayunsu kuma za su jawo musu abin kunya. ");
INSERT INTO hausa_vpl VALUES ("HS5_1","029_5_1","HOS","5","1","1","“Ku ji wannan, ku firistoci! Ku kasa kunne, ku Isra’ilawa! Ku saurara, ya ku gidan sarauta! Wannan hukunci yana a kanku, kun zama tarko a Mizfa, ragar da aka shimfiɗa a kan Tabor. ");
INSERT INTO hausa_vpl VALUES ("HS5_2","029_5_2","HOS","5","2","2","’Yan tawaye sun yi zurfi cikin kisan gilla. Zan hore su duka. ");
INSERT INTO hausa_vpl VALUES ("HS5_3","029_5_3","HOS","5","3","3","Na san Efraim ƙaf; Isra’ila ba a ɓoye take a gare ni ba. Efraim, yanzu ka juya ka shiga karuwanci; Isra’ila ta lalace. ");
INSERT INTO hausa_vpl VALUES ("HS5_4","029_5_4","HOS","5","4","4","“Ayyukansu ba su ba su dama su koma ga Allahnsu ba. Halin karuwanci yana cikin zuciyarsu; ba su yarda da Ubangiji ba. ");
INSERT INTO hausa_vpl VALUES ("HS5_5","029_5_5","HOS","5","5","5","Girmankan Isra’ila yana ba da shaida a kansu; Isra’ilawa, har ma Efraim, sun yi tuntuɓe a cikin zunubinsu; Yahuda ma ya yi tuntuɓe tare da su. ");
INSERT INTO hausa_vpl VALUES ("HS5_6","029_5_6","HOS","5","6","6","Sa’ad da suka tafi tare da garkunan shanu, tumaki da awakinsu don su nemi Ubangiji, ba za su same shi ba; ya janye kansa daga gare su. ");
INSERT INTO hausa_vpl VALUES ("HS5_7","029_5_7","HOS","5","7","7","Su marasa aminci ne ga Ubangiji; suna haihuwar shegu. Yanzu bukukkuwar Sabon Watansu za su cinye su da gonakinsu. ");
INSERT INTO hausa_vpl VALUES ("HS5_8","029_5_8","HOS","5","8","8","“Amon kakaki a Gibeya, ƙaho a Rama. Ku yi kirarin yaƙi a Bet-Awen; ku ja gaba, ya Benyamin. ");
INSERT INTO hausa_vpl VALUES ("HS5_9","029_5_9","HOS","5","9","9","Efraim za tă zama kango a ranar hukunci. A cikin kabilan Isra’ila na yi shelar abin da yake tabbatacce. ");
INSERT INTO hausa_vpl VALUES ("HS5_10","029_5_10","HOS","5","10","10","Shugabannin Yahuda suna kamar waɗanda suke matsar da duwatsun shaidar da aka sa a kan iyaka ne. Zan zubo musu da fushina a kansu kamar rigyawar ruwa. ");
INSERT INTO hausa_vpl VALUES ("HS5_11","029_5_11","HOS","5","11","11","An danne Efraim, an murƙushe ta a shari’a ta ƙudura ga bin gumaka. ");
INSERT INTO hausa_vpl VALUES ("HS5_12","029_5_12","HOS","5","12","12","Na zama kamar asu ga Efraim, kamar ruɓa ga mutanen Yahuda. ");
INSERT INTO hausa_vpl VALUES ("HS5_13","029_5_13","HOS","5","13","13","“Sa’ad da Efraim ya ga ciwonsa, Yahuda kuwa miyakunta, sai Efraim ya juya ga Assuriya, ya aika wurin babban sarki don neman taimako. Amma bai iya warkar da kai ba, bai iya warkar da miyakunka ba. ");
INSERT INTO hausa_vpl VALUES ("HS5_14","029_5_14","HOS","5","14","14","Gama zan zama kamar zaki ga Efraim, kamar babban zaki ga Yahuda. Zan yage su kucu-kucu in tafi; zan kwashe su, ba wanda zai kuɓutar da su. ");
INSERT INTO hausa_vpl VALUES ("HS5_15","029_5_15","HOS","5","15","15","Sa’an nan zan koma wurina sai sun yarda da laifinsu. Za su kuma nemi fuskata; cikin azabansu za su nace da nemana.” ");
INSERT INTO hausa_vpl VALUES ("HS6_1","029_6_1","HOS","6","1","1","“Ku zo, mu koma ga Ubangiji. Ya yayyage mu kucu-kucu amma zai warkar da mu; ya ji mana ciwo amma zai daure mana miyakunmu. ");
INSERT INTO hausa_vpl VALUES ("HS6_2","029_6_2","HOS","6","2","2","Bayan kwana biyu zai rayar da mu, a rana ta uku zai tashe mu, don mu rayu a gabansa. ");
INSERT INTO hausa_vpl VALUES ("HS6_3","029_6_3","HOS","6","3","3","Bari mu yarda da Ubangiji; bari mu nace gaba don mu yarda da shi. Muddin rana tana fitowa, zai bayyana; zai zo mana kamar ruwan bazara, kamar ruwan saman farko da yake jiƙe ƙasa.” ");
INSERT INTO hausa_vpl VALUES ("HS6_4","029_6_4","HOS","6","4","4","“Me zan yi da kai Efraim? Me zan yi da kai Yahuda? Ƙaunarku tana kamar hazon safiya, kamar raɓar safiya da takan ɓace. ");
INSERT INTO hausa_vpl VALUES ("HS6_5","029_6_5","HOS","6","5","5","Saboda haka na yayyaga ku kucu-kucu tare da annabawana, na kashe ku da kalmomin bakina; hukuntaina sun haskaka kamar walƙiya a kanku. ");
INSERT INTO hausa_vpl VALUES ("HS6_6","029_6_6","HOS","6","6","6","Gama jinƙai nake bukata, ba hadaya ba, ku kuma san Allah a maimakon hadayun ƙonawa. ");
INSERT INTO hausa_vpl VALUES ("HS6_7","029_6_7","HOS","6","7","7","Kamar Adamu, sun tā da alkawari, sun yi mini rashin aminci a can. ");
INSERT INTO hausa_vpl VALUES ("HS6_8","029_6_8","HOS","6","8","8","Gileyad birni ce ta mugayen mutane, da tabon alamun jini. ");
INSERT INTO hausa_vpl VALUES ("HS6_9","029_6_9","HOS","6","9","9","Kamar yadda mafasa sukan yi fakon mutum, haka ƙungiyoyin firistoci suke; suna kisa a hanya zuwa Shekem, suna aikata laifofi bankunya. ");
INSERT INTO hausa_vpl VALUES ("HS6_10","029_6_10","HOS","6","10","10","Na ga wani abu mai bantsoro a gidan Isra’ila. A can Efraim ya miƙa wuya ga karuwanci Isra’ila kuma ta ƙazantu. ");
INSERT INTO hausa_vpl VALUES ("HS6_11","029_6_11","HOS","6","11","11","“Ku kuma, ya mutanen Yahuda, na shirya muku ranar girbi. “A duk sa’ad da zan mayar da dukiya wa mutanena, ");
INSERT INTO hausa_vpl VALUES ("HS7_1","029_7_1","HOS","7","1","1","a duka sa’ad da zan warkar da Isra’ila, zunuban Efraim za su tonu za a kuma bayyana laifofin Samariya. Suna ruɗu, ɓarayi sukan fasa su shiga gidaje, ’yan fashi sukan yi fashi a tituna; ");
INSERT INTO hausa_vpl VALUES ("HS7_2","029_7_2","HOS","7","2","2","amma ba su gane cewa na tuna da dukan ayyukan muguntarsu ba. Zunubansu sun kewaye su; kullum suna a gabana. ");
INSERT INTO hausa_vpl VALUES ("HS7_3","029_7_3","HOS","7","3","3","“Suna faranta wa sarki zuciya da muguntarsu, shugabanni kuma da ƙarairayinsu. ");
INSERT INTO hausa_vpl VALUES ("HS7_4","029_7_4","HOS","7","4","4","Dukansu mazinata ne suna ƙuna kamar matoya wadda mai gashin burodi ba ya bukata yă tura mata wuta daga cuɗe kullu har kumburinsa. ");
INSERT INTO hausa_vpl VALUES ("HS7_5","029_7_5","HOS","7","5","5","A ranar bikin sarkinmu shugabanni sukan bugu da ruwan inabi, yă yi cuɗanya da masu ba’a. ");
INSERT INTO hausa_vpl VALUES ("HS7_6","029_7_6","HOS","7","6","6","Zukatansu suna kamar matoya; sukan kusace shi da wayo. Muguwar aniyarsu takan yi ta ci dukan dare; da safe sai ta ƙuna kamar harshen wuta. ");
INSERT INTO hausa_vpl VALUES ("HS7_7","029_7_7","HOS","7","7","7","Dukansu suna da zafi kamar matoya; suna kashe masu mulkinsu. Dukan sarakunansu sukan fāɗi, kuma babu waninsu da yake kira gare ni. ");
INSERT INTO hausa_vpl VALUES ("HS7_8","029_7_8","HOS","7","8","8","“Efraim yana cuɗanya da al’ummai; Efraim waina ne mai fāɗi da ba a juye ba. ");
INSERT INTO hausa_vpl VALUES ("HS7_9","029_7_9","HOS","7","9","9","Baƙi sun tsotse ƙarfinsa, amma bai gane ba. Gashi kansa ya cika da furfura, amma bai lura ba. ");
INSERT INTO hausa_vpl VALUES ("HS7_10","029_7_10","HOS","7","10","10","Girmankan Isra’ila ya ba da shaida a kansa, amma duk da haka bai dawo ga Ubangiji Allahnsa ko yă neme shi ba. ");
INSERT INTO hausa_vpl VALUES ("HS7_11","029_7_11","HOS","7","11","11","“Efraim yana kama da kurciya, marar wayo, marar hankali, yanzu yana kira ga Masar, yanzu yana juyewa ga Assuriya. ");
INSERT INTO hausa_vpl VALUES ("HS7_12","029_7_12","HOS","7","12","12","Sa’ad da suka tafi, zan jefa ragata a kansu; zai janye su ƙasa kamar tsuntsayen sararin sama. Sa’ad da na ji suna tafiya tare, zan kama su. ");
INSERT INTO hausa_vpl VALUES ("HS7_13","029_7_13","HOS","7","13","13","Kaitonsu, domin sun kauce daga gare ni! Hallaka za tă aukar musu, domin sun tayar mini! Na ƙudura in cece su amma suna faɗar ƙarya a kaina. ");
INSERT INTO hausa_vpl VALUES ("HS7_14","029_7_14","HOS","7","14","14","Ba sa yin mini kuka da zuciyarsu amma suna ihu a kan gadajensu. Sukan taru wurin ɗaya don hatsi da ruwan inabi amma su juya mini baya. ");
INSERT INTO hausa_vpl VALUES ("HS7_15","029_7_15","HOS","7","15","15","Na horar da su na kuma ƙarfafa su, amma sun ƙulla mini maƙarƙashiya. ");
INSERT INTO hausa_vpl VALUES ("HS7_16","029_7_16","HOS","7","16","16","Ba sa juya ga Mafi Ɗaukaka; suna kama da tanƙwararren baka. Za a kashe shugabanninsu da takobi saboda banzan maganganunsu. Saboda wannan za a wulaƙanta su a ƙasar Masar. ");
INSERT INTO hausa_vpl VALUES ("HS8_1","029_8_1","HOS","8","1","1","“Ka sa kakaki a leɓunanka! Gaggafa tana a bisan gidan Ubangiji domin mutane sun tā da alkawarina suka kuma tayar wa dokata. ");
INSERT INTO hausa_vpl VALUES ("HS8_2","029_8_2","HOS","8","2","2","Isra’ila ta yi mini kuka, ‘Ya Allahnmu, mun yarda da kai!’ ");
INSERT INTO hausa_vpl VALUES ("HS8_3","029_8_3","HOS","8","3","3","Amma Isra’ila sun ƙi abin da yake mai kyau; abokin gāba zai fafare su. ");
INSERT INTO hausa_vpl VALUES ("HS8_4","029_8_4","HOS","8","4","4","Suna naɗa sarakuna, ba da izinina ba; sun zaɓa shugabanni ba da yardanta ba. Da azurfa da zinariya sun ƙera gumaka wa kansu wanda zai kai zuwa ga hallakarsu. ");
INSERT INTO hausa_vpl VALUES ("HS8_5","029_8_5","HOS","8","5","5","Ku zubar da gunkin maraƙinku, ya Samariya! Fushina yana ƙuna a kansu. Sai yaushe za su rabu da gumaka? ");
INSERT INTO hausa_vpl VALUES ("HS8_6","029_8_6","HOS","8","6","6","Su daga Isra’ila ne! Wannan maraƙi, mai aikin hannu ne ya yi shi; gunki ne ba Allah ba. Za a farfashe shi kucu-kucu, waccan maraƙin Samariya. ");
INSERT INTO hausa_vpl VALUES ("HS8_7","029_8_7","HOS","8","7","7","“Gama sun shuka iska don haka za su girbe guguwa. Hatsin da yake tsaye ba shi da kai, ba zai yi tsaba ba. Ko da ya yi tsaba ma, baƙi ne za su ci. ");
INSERT INTO hausa_vpl VALUES ("HS8_8","029_8_8","HOS","8","8","8","An haɗiye Isra’ila; yanzu tana cikin al’ummai kamar abin da ba shi da amfani. ");
INSERT INTO hausa_vpl VALUES ("HS8_9","029_8_9","HOS","8","9","9","Gama sun haura zuwa Assuriya kamar jakin jejin da yake yawo shi kaɗai. Efraim ya sayar da kansa ga maza. ");
INSERT INTO hausa_vpl VALUES ("HS8_10","029_8_10","HOS","8","10","10","Ko da yake sun sayar da kansu a cikin al’ummai, yanzu zan tattara su wuri ɗaya. Za su fara lalacewa a ƙarƙashi danniyar babban sarki. ");
INSERT INTO hausa_vpl VALUES ("HS8_11","029_8_11","HOS","8","11","11","“Ko da yake Efraim ya gina bagadai masu yawa don hadayun zunubi, waɗannan sun zama bagade don yin zunubi. ");
INSERT INTO hausa_vpl VALUES ("HS8_12","029_8_12","HOS","8","12","12","Na rubuta musu abubuwa masu yawa na dokata, amma suka ɗauke su tamƙar wani baƙon abu ne. ");
INSERT INTO hausa_vpl VALUES ("HS8_13","029_8_13","HOS","8","13","13","Suna miƙa hadayun da aka ba ni su kuma ci nama, amma Ubangiji ba ya jin daɗinsu. Yanzu zai tuna da muguntarsu yă kuma hukunta zunubansu. Za su koma Masar. ");
INSERT INTO hausa_vpl VALUES ("HS8_14","029_8_14","HOS","8","14","14","Isra’ila ya manta da Mahaliccinsa ya kuma gina fadodi; Yahuda ya gina katanga a yawancin garuruwansa. Amma zan aiko da wuta a bisa biranensu da zai cinye kagaransu.” ");
INSERT INTO hausa_vpl VALUES ("HS9_1","029_9_1","HOS","9","1","1","Kada ku yi farin ciki, ya Isra’ila; kada ku yi murna kamar waɗansu al’ummai. Gama kun yi rashin aminci ga Allahnku; kuna son hakkokin karuwa a kowace masussuka. ");
INSERT INTO hausa_vpl VALUES ("HS9_2","029_9_2","HOS","9","2","2","Masussukai da wuraren matsin inabi ba za su ciyar da mutane ba; sabon ruwan inabi zai kāsa musu. ");
INSERT INTO hausa_vpl VALUES ("HS9_3","029_9_3","HOS","9","3","3","Ba za su ci gaba da zama a ƙasar Ubangiji ba; Efraim zai koma Masar yă kuma ci abinci marar tsarki a Assuriya. ");
INSERT INTO hausa_vpl VALUES ("HS9_4","029_9_4","HOS","9","4","4","Ba za su zuba hadayun ruwan inabi ga Ubangiji ba, ba kuwa hadayunsu za su gamshe shi ba. Irin hadayun nan za su zama musu kamar burodin masu makoki; duk wanda ya ci su zai ƙazantu. Wannan abincin zai zama na kansu ne; ba zai zo cikin haikalin Ubangiji ba. ");
INSERT INTO hausa_vpl VALUES ("HS9_5","029_9_5","HOS","9","5","5","Me za ku yi a ƙayyadaddiyar ranar bukukkuwarku, a ranakun bikin Ubangiji? ");
INSERT INTO hausa_vpl VALUES ("HS9_6","029_9_6","HOS","9","6","6","Ko da sun kuɓuta daga hallaka, Masar za tă tattara su, Memfis kuma za tă binne su. Sarƙaƙƙiya za tă mamaye kayan azurfansu, ƙayayyuwa su tsiro a cikin tentunansu. ");
INSERT INTO hausa_vpl VALUES ("HS9_7","029_9_7","HOS","9","7","7","Kwanakin hukunci suna zuwa, kwanakin ba da lissafi suna a kusa. Bari Isra’ila su san da wannan. Saboda zunubanku sun yi yawa ƙiyayyarku kuma ta yi yawa, har ake ɗauka annabi wawa ne, mutumin da aka iza kuwa mahaukaci. ");
INSERT INTO hausa_vpl VALUES ("HS9_8","029_9_8","HOS","9","8","8","Annabi, tare da Allahna, su ne masu tsaro a bisa Efraim, duk da haka tarko na jiransa a dukan hanyoyi, da kuma ƙiyayya a cikin gidan Allahnsa. ");
INSERT INTO hausa_vpl VALUES ("HS9_9","029_9_9","HOS","9","9","9","Sun nutse da zurfi cikin lalaci, kamar a kwanakin Gibeya. Allah zai tuna da muguntarsu yă kuma hukunta su saboda zunubansu. ");
INSERT INTO hausa_vpl VALUES ("HS9_10","029_9_10","HOS","9","10","10","“Sa’ad da na sami Isra’ila, ya zama kamar samun inabi a hamada; sa’ad da na ga kakanninku, ya zama kamar ganin ’ya’yan itace na farko a itacen ɓaure. Amma sa’ad da suka zo Ba’al-Feyor, suka keɓe kansu wa gumaka bankunya sai suka zama abubuwan banƙyama kamar abubuwan da suke ƙauna. ");
INSERT INTO hausa_vpl VALUES ("HS9_11","029_9_11","HOS","9","11","11","Darajar Efraim za tă yi firiya tă tafi kamar tsuntsu, ba haihuwa, ba juna biyu, ba ɗaukar ciki. ");
INSERT INTO hausa_vpl VALUES ("HS9_12","029_9_12","HOS","9","12","12","Ko da sun yi renon ’ya’ya, zan sa su yi baƙin cikin kowannensu. Kaitonsu sa’ad da na juya musu baya! ");
INSERT INTO hausa_vpl VALUES ("HS9_13","029_9_13","HOS","9","13","13","Na ga Efraim, kamar birnin Taya, da aka kafa a wuri mai daɗi. Amma Efraim zai fitar da ’ya’yansu ga masu yanka.” ");
INSERT INTO hausa_vpl VALUES ("HS9_14","029_9_14","HOS","9","14","14","Ka ba su, ya Ubangiji Me za ka ba su? Ka ba su mahaifar da za su yi ɓarin ciki da busassun nono. ");
INSERT INTO hausa_vpl VALUES ("HS9_15","029_9_15","HOS","9","15","15","“Saboda dukan muguntarsu a Gilgal, na ƙi su a can. Saboda ayyukansu na zunubi, zan kore su daga gidana. Ba zan ƙara ƙaunace su ba; dukan shugabanninsu ’yan tawaye ne. ");
INSERT INTO hausa_vpl VALUES ("HS9_16","029_9_16","HOS","9","16","16","An ka da Efraim, saiwarsu ta bushe, ba sa ba da amfani. Ko da sun haifi ’ya’ya zan kashe waɗanda suka fi ƙauna.” ");
INSERT INTO hausa_vpl VALUES ("HS9_17","029_9_17","HOS","9","17","17","Allahna zai ƙi su saboda ba su yi masa biyayya ba; za su zama masu yawo a cikin al’ummai. ");
INSERT INTO hausa_vpl VALUES ("HS10_1","029_10_1","HOS","10","1","1","Isra’ila kuringa ce mai yaɗuwa; ya fitar da ’ya’ya wa kansa. Yayinda ’ya’yan suka ƙaru, ya gina ƙarin bagadai; da ƙasarsa ta wadata, ya yi wa keɓaɓɓun duwatsu ado. ");
INSERT INTO hausa_vpl VALUES ("HS10_2","029_10_2","HOS","10","2","2","Zuciyarsu masu ruɗu ne, yanzu kuwa dole su ɗauki laifinsu. Ubangiji zai rushe bagadansu yă kuma hallaka keɓaɓɓun duwatsunsu. ");
INSERT INTO hausa_vpl VALUES ("HS10_3","029_10_3","HOS","10","3","3","Sa’an nan za su ce, “Ba mu da sarki domin ba mu girmama Ubangiji ba. Amma ko da ma muna da sarki, me zai yi mana?” ");
INSERT INTO hausa_vpl VALUES ("HS10_4","029_10_4","HOS","10","4","4","Sun yi alkawura masu yawa, suka yi rantsuwar ƙarya da kuma yarjejjeniyoyi; saboda haka ƙararraki suka taso kamar ciyayi masu dafi da aka nome a gona. ");
INSERT INTO hausa_vpl VALUES ("HS10_5","029_10_5","HOS","10","5","5","Mutanen da suke zama a Samariya suna tsoro saboda gunki maraƙin Bet-Awen. Mutanensa za su yi makokinsa, haka ma firistocinsa matsafa, waɗanda suka yi farin ciki a kan darajarsa, don an ɗauke ta daga gare su aka kai ta zaman bauta. ");
INSERT INTO hausa_vpl VALUES ("HS10_6","029_10_6","HOS","10","6","6","Za a ɗauke shi a kai Assuriya kamar gandu wa babban sarki. Efraim zai sha kunya; Isra’ila zai sha kunya saboda gumakan itacensa. ");
INSERT INTO hausa_vpl VALUES ("HS10_7","029_10_7","HOS","10","7","7","Samariya da sarkinta za su ɓace kamar kumfa a bisa ruwaye. ");
INSERT INTO hausa_vpl VALUES ("HS10_8","029_10_8","HOS","10","8","8","Za a hallaka masujadai kan tudu na mugunta zunubin Isra’ila ne. Ƙayayuwa da sarƙaƙƙiya za su yi girma su rufe bagadansu. Sa’an nan za su ce wa duwatsu, “Ku rufe mu!” Ga tuddai kuma, “Ku fāɗo a kanmu!” ");
INSERT INTO hausa_vpl VALUES ("HS10_9","029_10_9","HOS","10","9","9","“Tun daga kwanakin Gibeya, kun yi zunubi, ya Isra’ila, a can kuwa kuka ci gaba. Yaƙi bai cimma masu aikata mugunta a Gibeya ba? ");
INSERT INTO hausa_vpl VALUES ("HS10_10","029_10_10","HOS","10","10","10","Sa’ad da na ga dama, zan hukunta su; al’ummai za su taru su yi gāba da su don su daure su saboda zunubansu da suka riɓanya. ");
INSERT INTO hausa_vpl VALUES ("HS10_11","029_10_11","HOS","10","11","11","Efraim horarriyar karsana ce mai son sussuka; saboda haka zan sa karkiya a kyakkyawan wuyanta. Zan bi da Efraim, Dole Yahuda yă yi noma, dole kuma Yaƙub yă ja garman noma. ");
INSERT INTO hausa_vpl VALUES ("HS10_12","029_10_12","HOS","10","12","12","Ku shuka wa kanku adalci, ku girbe ’ya’yan jinƙai marar ƙarewa, ku kuma nome ƙasar da ba a nome ba; gama lokaci ne na neman Ubangiji, sai ya zo ya zubo adalci a kanku. ");
INSERT INTO hausa_vpl VALUES ("HS10_13","029_10_13","HOS","10","13","13","Amma kun shuka mugunta, kuka girbe mugu kuka ci ’ya’yan ruɗu. Domin kun dogara da ƙarfinku da kuma a jarumawanku masu yawa, ");
INSERT INTO hausa_vpl VALUES ("HS10_14","029_10_14","HOS","10","14","14","hayaniyar yaƙi za tă tashi gāba da mutanenku, saboda a ragargaza kagaranku, kamar yadda Shalman ya ragargaza Bet-Arbel a ranar yaƙi, sa’ad da aka fyaɗa uwaye tare da ’ya’yansu da ƙasa. ");
INSERT INTO hausa_vpl VALUES ("HS10_15","029_10_15","HOS","10","15","15","Haka zai faru da kai, ya Betel, domin muguntarka ta yi yawa. Sa’ad da wannan rana ta zo, za a hallaka sarkin Isra’ila ƙaƙaf. ");
INSERT INTO hausa_vpl VALUES ("HS11_1","029_11_1","HOS","11","1","1","“Sa’ad da Isra’ila yake yaro, na ƙaunace shi, daga Masar kuma na kira ɗana. ");
INSERT INTO hausa_vpl VALUES ("HS11_2","029_11_2","HOS","11","2","2","Amma yawan kiran da na yi wa Isra’ila haka nesa da ni da suke ta yi. Suka miƙa hadaya ga Ba’al suka kuma ƙona turare ga siffofi. ");
INSERT INTO hausa_vpl VALUES ("HS11_3","029_11_3","HOS","11","3","3","Ni ne na koya wa Efraim tafiya ina kama su da hannu; amma ba su gane cewa ni ne na warkar da su ba. ");
INSERT INTO hausa_vpl VALUES ("HS11_4","029_11_4","HOS","11","4","4","Na bishe su da linzamin alheri da tausayi, da ragamar ƙauna; Na cire karkiya daga wuyansu na kuma rusuna na ciyar da su. ");
INSERT INTO hausa_vpl VALUES ("HS11_5","029_11_5","HOS","11","5","5","“Ba za su koma Masar ba Assuriya kuma ba za tă yi mulki a bisansu ba saboda sun ƙi su tuba ba? ");
INSERT INTO hausa_vpl VALUES ("HS11_6","029_11_6","HOS","11","6","6","Takuba za su yi ta wulgawa a biranensu, za su hallaka sandunan ƙarafan ƙofofinsu su kuma kawo ƙarshen ƙulle-ƙullensu. ");
INSERT INTO hausa_vpl VALUES ("HS11_7","029_11_7","HOS","11","7","7","Mutanena sun ƙudura su juye daga gare ni. Ko da ma suka yi kira ga Mafi Ɗaukaka, ta ko ƙaƙa ba zai girmama su ba. ");
INSERT INTO hausa_vpl VALUES ("HS11_8","029_11_8","HOS","11","8","8","“Yaya zan ba da kai, Efraim? Yaya zan miƙa ka, Isra’ila? Yaya zan yi da kai kamar Adma? Yaya zan yi da kai kamar Zeboyim? Zuciyata ta canja a cikina; dukan tausayina ya huru. ");
INSERT INTO hausa_vpl VALUES ("HS11_9","029_11_9","HOS","11","9","9","Ba zan zartar da fushina mai zafi ba, ba kuwa zan juya in ragargaza Efraim ba. Gama ni Allah ne, ba mutum ba, Mai Tsarki a cikinku. Ba zan zo cikin fushi ba. ");
INSERT INTO hausa_vpl VALUES ("HS11_10","029_11_10","HOS","11","10","10","Za su bi Ubangiji; zai yi ruri kamar zaki. Sa’ad da ya yi ruri, ’ya’yansa za su zo da rawan jiki daga yamma. ");
INSERT INTO hausa_vpl VALUES ("HS11_11","029_11_11","HOS","11","11","11","Za su zo da rawan jiki kamar tsuntsaye daga Masar, kamar kurciyoyi daga Assuriya. Zan zaunar da su a cikin gidajensu,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("HS11_12","029_11_12","HOS","11","12","12","Mutanen Efraim sun kewaye ni da ƙarairayi, gidan Isra’ila da ruɗu. Mutanen Yahuda kuma suna yi wa Allah ƙin ji, har ma a kan Mai Tsarkin nan mai aminci. ");
INSERT INTO hausa_vpl VALUES ("HS12_1","029_12_1","HOS","12","1","1","Efraim yana kiwo a kan iska; yana fafarar iskar gabas dukan yini yana riɓaɓɓanya ƙarairayi da rikici. Ya yi yarjejjeniya da Assuriya ya kuma aika wa Masar man zaitun. ");
INSERT INTO hausa_vpl VALUES ("HS12_2","029_12_2","HOS","12","2","2","Ubangiji yana da ƙarar da zai kawo a kan Yahuda; zai hukunta Yaƙub bisa ga hanyoyinsa zai sāka masa bisa ga ayyukansa. ");
INSERT INTO hausa_vpl VALUES ("HS12_3","029_12_3","HOS","12","3","3","A cikin mahaifa ya cafke ɗiɗɗigen ɗan’uwansa; a matsayin mutum ya yi kokawa da Allah. ");
INSERT INTO hausa_vpl VALUES ("HS12_4","029_12_4","HOS","12","4","4","Ya yi kokawa da mala’ika ya kuma rinjaye shi; ya yi kuka ya kuma yi roƙo don tagomashi. Ya same shi a Betel ya kuma yi magana da shi a can, ");
INSERT INTO hausa_vpl VALUES ("HS12_5","029_12_5","HOS","12","5","5","Ubangiji Allah Maɗaukaki, Ubangiji ne sunansa sananne! ");
INSERT INTO hausa_vpl VALUES ("HS12_6","029_12_6","HOS","12","6","6","Amma dole ku koma ga Allahnku; ku ci gaba da ƙauna da yin gaskiya, ku kuma saurari Allahnku kullum. ");
INSERT INTO hausa_vpl VALUES ("HS12_7","029_12_7","HOS","12","7","7","Ɗan kasuwa yana amfani da mudu marar gaskiya; yana jin daɗin cuta. ");
INSERT INTO hausa_vpl VALUES ("HS12_8","029_12_8","HOS","12","8","8","Efraim yana fariya yana cewa, “Ni mai arziki ne ƙwarai; na azurta. Da dukan wadatata ba za a sami wani laifi ko zunubi a gare ni ba.” ");
INSERT INTO hausa_vpl VALUES ("HS12_9","029_12_9","HOS","12","9","9","“Ni ne Ubangiji Allahnku, wanda ya fitar da ku daga Masar; zan sa ku sāke zauna a tentuna, kamar a kwanakin ƙayyadaddun bukukkuwanku. ");
INSERT INTO hausa_vpl VALUES ("HS12_10","029_12_10","HOS","12","10","10","Na yi magana da annabawa, na ba su wahayi da yawa na kuma ba da misalai ta wurinsu.” ");
INSERT INTO hausa_vpl VALUES ("HS12_11","029_12_11","HOS","12","11","11","Gileyad mugu ne? Mutanensa mutanen banza ne! Suna miƙa bijimai a Gilgal? Bagadansu za su zama tsibin duwatsu. A gonar da aka nome. ");
INSERT INTO hausa_vpl VALUES ("HS12_12","029_12_12","HOS","12","12","12","Yaƙub ya gudu zuwa ƙasar Aram; Isra’ila ya yi bauta don yă sami mata, domin kuma yă biya, sai da ya yi kiwon tumaki. ");
INSERT INTO hausa_vpl VALUES ("HS12_13","029_12_13","HOS","12","13","13","Ubangiji ya yi amfani da annabi don yă fitar da Isra’ila daga Masar ta wurin annabi ya lura da shi. ");
INSERT INTO hausa_vpl VALUES ("HS12_14","029_12_14","HOS","12","14","14","Amma Efraim ya yi muguwar tsokana da ta sa ya yi fushi; shugabansa zai ɗora musu hakkin jini a kansa kuma zai sāka masa saboda wulaƙancinsa. ");
INSERT INTO hausa_vpl VALUES ("HS13_1","029_13_1","HOS","13","1","1","Sa’ad da Efraim ya yi magana, mutane sun yi rawan jiki; an girmama shi a cikin Isra’ila. Amma sai ya zama mai laifi na yin wa Ba’al sujada, ya kuwa mutu. ");
INSERT INTO hausa_vpl VALUES ("HS13_2","029_13_2","HOS","13","2","2","Yanzu sai yin zunubi a kai a kai suke; suna yin gumaka wa kansu daga azurfansu, da wayo suna sarrafa siffofi, dukansu aikin masu aikin hannu ne. Ana magana waɗannan mutane cewa, “Suna miƙa hadayar mutum su kuma sumbaci gumakan maruƙa.” ");
INSERT INTO hausa_vpl VALUES ("HS13_3","029_13_3","HOS","13","3","3","Saboda haka za su zama kamar hazon safiya, kamar raɓar safen da yakan kakkaɓe, kamar ƙaiƙayin da ake tankaɗe daga masussuka, kamar hayaƙin da yake fita daga taga. ");
INSERT INTO hausa_vpl VALUES ("HS13_4","029_13_4","HOS","13","4","4","“Amma ni ne Ubangiji Allahnku, wanda ya fitar da ku daga Masar. Ba za ku yarda da wani Allah ba sai ni, ba wani Mai Ceto in ban da ni. ");
INSERT INTO hausa_vpl VALUES ("HS13_5","029_13_5","HOS","13","5","5","Na lura da ku a hamada, cikin ƙasar mai ƙunar zafi. ");
INSERT INTO hausa_vpl VALUES ("HS13_6","029_13_6","HOS","13","6","6","Sa’ad da na ciyar da su sun ƙoshi; sa’ad da suka ƙoshi, sai suka fara taƙama; sai suka manta da ni. ");
INSERT INTO hausa_vpl VALUES ("HS13_7","029_13_7","HOS","13","7","7","Saboda haka zan hau kansu kamar zaki, zan ɓuya a bakin hanya kamar damisa. ");
INSERT INTO hausa_vpl VALUES ("HS13_8","029_13_8","HOS","13","8","8","Kamar beyar da aka ƙwace mata ’ya’yanta, zan fāɗa musu in ɓarke su. Kamar zaki zan cinye su; kamar naman jeji zan yayyage su. ");
INSERT INTO hausa_vpl VALUES ("HS13_9","029_13_9","HOS","13","9","9","“An hallaka ku, ya Isra’ila, domin kun tayar mini, kun tayar wa mai taimakonku. ");
INSERT INTO hausa_vpl VALUES ("HS13_10","029_13_10","HOS","13","10","10","Ina sarkinku, da zai cece ku? Ina masu mulkinku cikin dukan garuruwanku, waɗanda kuka ce, ‘Ba mu sarki da shugabanni’? ");
INSERT INTO hausa_vpl VALUES ("HS13_11","029_13_11","HOS","13","11","11","Saboda haka cikin fushina na ba ku sarki, kuma cikin hasalata na ɗauke shi. ");
INSERT INTO hausa_vpl VALUES ("HS13_12","029_13_12","HOS","13","12","12","An yi ajiyar laifin Efraim, aka lissafta zunubansa. ");
INSERT INTO hausa_vpl VALUES ("HS13_13","029_13_13","HOS","13","13","13","Naƙuda ta zo masa kamar a mace mai haihuwa, amma shi yaro ne marar hikima; sa’ad da lokaci ya kai, ba ya zuwa inda mahaifa ta buɗe. ");
INSERT INTO hausa_vpl VALUES ("HS13_14","029_13_14","HOS","13","14","14","“Zan fanshe su daga ikon kabari; zan cece su daga mutuwa. Ina annobanki, ya mutuwa? Ina hallakarka, ya kabari? “Ba zan ji tausayi ba, ");
INSERT INTO hausa_vpl VALUES ("HS13_15","029_13_15","HOS","13","15","15","ko da ma ya ci gaba cikin ’yan’uwansa. Iskar gabas daga Ubangiji za tă zo, tana hurawa daga hamada; maɓulɓularsa za tă kafe rijiyarsa kuma ta bushe. Za a kwashi kaya masu daraja na ɗakin ajiyarsa ganima. ");
INSERT INTO hausa_vpl VALUES ("HS13_16","029_13_16","HOS","13","16","16","Dole mutanen Samariya su ɗauki laifinsu, domin sun tayar wa Allahnsu. Za a kashe su da takobi; za a fyaɗa ƙananansu da ƙasa, za a ɓarke matansu masu ciki.” ");
INSERT INTO hausa_vpl VALUES ("HS14_1","029_14_1","HOS","14","1","1","Ku dawo, ya Isra’ila, ga Ubangiji Allahnku. Zunubanku ne sun zama sanadin fāɗuwarku! ");
INSERT INTO hausa_vpl VALUES ("HS14_2","029_14_2","HOS","14","2","2","Ku ɗauki magana tare da ku ku komo wurin Ubangiji. Ku ce masa, “Ka gafarta mana dukan zunubanmu ka kuma karɓe mu da alheri, don mu iya yabe ka da leɓunanmu. ");
INSERT INTO hausa_vpl VALUES ("HS14_3","029_14_3","HOS","14","3","3","Assuriya ba za su iya cece mu ba; ba za mu hau dawakan yaƙi ba. Ba za mu ƙara ce, ‘Allolinmu’ wa abin da hannuwanmu suka yi ba, gama a gare ka ne maraya yakan sami jinƙai.” ");
INSERT INTO hausa_vpl VALUES ("HS14_4","029_14_4","HOS","14","4","4","“Zan gyara ɓatancinsu in kuma ƙaunace su a sake, gama fushina ya juya daga gare su. ");
INSERT INTO hausa_vpl VALUES ("HS14_5","029_14_5","HOS","14","5","5","Zan zama kamar raɓa ga Isra’ila zai yi fure kamar lili. Kamar al’ul na Lebanon zai sa saiwarsa zuwa ƙasa; ");
INSERT INTO hausa_vpl VALUES ("HS14_6","029_14_6","HOS","14","6","6","tohonsa za su yi girma. Darajarsa za tă zama kamar itacen zaitun, ƙanshinsa kamar al’ul na Lebanon. ");
INSERT INTO hausa_vpl VALUES ("HS14_7","029_14_7","HOS","14","7","7","Mutane za su sāke zauna a inuwarsa. Zai haɓaka kamar ƙwayar hatsi. Zai yi fure kamar kuringa, zai zama sananne kamar ruwan inabi daga Lebanon. ");
INSERT INTO hausa_vpl VALUES ("HS14_8","029_14_8","HOS","14","8","8","Efraim zai ce, me kuma zai haɗa ni da gumaka? Zan amsa masa in kuma lura da shi. Ni kamar koren itacen fir ne; amincinka yana fitowa daga gare ni ne.” ");
INSERT INTO hausa_vpl VALUES ("HS14_9","029_14_9","HOS","14","9","9","Wane ne yake da hikima? Zai gane waɗannan abubuwa. Hanyoyin Ubangiji daidai ne; masu adalci sukan yi tafiya a kansu, amma ’yan tawaye sukan yi tuntuɓe a kansu.");
INSERT INTO hausa_vpl VALUES ("JL1_1","030_1_1","JOL","1","1","1","Maganar Ubangiji wadda ta zo wurin Yowel ɗan Fetuwel. ");
INSERT INTO hausa_vpl VALUES ("JL1_2","030_1_2","JOL","1","2","2","Ku ji wannan, ku dattawa, ku kasa kunne, dukan waɗanda suke zaune a ƙasar. Ko wani abu makamancin haka ya taɓa faruwa a kwanakinku ko a kwanakin kakanninku? ");
INSERT INTO hausa_vpl VALUES ("JL1_3","030_1_3","JOL","1","3","3","Ku faɗa wa ’ya’yanku, bari kuma ’ya’yanku su faɗa wa ’ya’yansu, ’ya’yansu kuma su faɗa wa tsara ta gaba. ");
INSERT INTO hausa_vpl VALUES ("JL1_4","030_1_4","JOL","1","4","4","Abin da ɗango ya bari fāri masu girma sun cinye; abin da fāri masu girma suka bari, burduduwa ta cinye; abin da burduduwa ta bari sauran kwari sun cinye. ");
INSERT INTO hausa_vpl VALUES ("JL1_5","030_1_5","JOL","1","5","5","Ku farka, ku bugaggu, ku yi kuka! Ku yi kuka da ƙarfi, ku dukan mashayan ruwan inabi; ku yi kuka mai ƙarfi saboda sabon ruwan inabi, gama an riga an ƙwace ta daga leɓunanku. ");
INSERT INTO hausa_vpl VALUES ("JL1_6","030_1_6","JOL","1","6","6","Wata al’umma ta mamaye ƙasata, tana da ƙarfi ba ta kuma ƙidayuwa; tana da haƙoran zaki, da zagar zakanya. ");
INSERT INTO hausa_vpl VALUES ("JL1_7","030_1_7","JOL","1","7","7","Ta mayar da kuringar inabina kango ta kuma lalatar da itatuwan ɓaurena. Ta ɓamɓare bayansu duka ta kuma jefar da su ta bar rassansu fari fat. ");
INSERT INTO hausa_vpl VALUES ("JL1_8","030_1_8","JOL","1","8","8","Ku yi makoki kamar budurwa a cikin tsummoki tana baƙin ciki domin mijinta na ƙuruciyarta. ");
INSERT INTO hausa_vpl VALUES ("JL1_9","030_1_9","JOL","1","9","9","Hadayun hatsi da hadayun sha an yanke su daga gidan Ubangiji. Firistoci suna makoki, su waɗanda suke yi wa Ubangiji hidima. ");
INSERT INTO hausa_vpl VALUES ("JL1_10","030_1_10","JOL","1","10","10","Filaye sun zama marasa amfani, ƙasa ta bushe; an lalatar da hatsi, sabon ruwan inabin ya bushe, mai kuma ba amfani. ");
INSERT INTO hausa_vpl VALUES ("JL1_11","030_1_11","JOL","1","11","11","Ku fid da zuciya, ku manoma, ku yi ihu, ku masu noma inabi; ku yi baƙin ciki saboda alkama da sha’ir, saboda an lalata girbin filaye. ");
INSERT INTO hausa_vpl VALUES ("JL1_12","030_1_12","JOL","1","12","12","Kuringar inabin ta bushe itacen ɓaure kuma ya yi yaushi, ’ya’yan rumman, itacen dabino da itacen gawasa, dukan itatuwan filaye, sun bushe. Tabbatacce farin cikin ’yan adam ya bushe. ");
INSERT INTO hausa_vpl VALUES ("JL1_13","030_1_13","JOL","1","13","13","Ku sa tsummoki, ya firistoci, ku yi makoki; ku yi ihu, ku da kuke yin hidima a gaban bagade. Zo, ku kwana saye da tsummoki, ku waɗanda kuke yi wa Allahna hidima, gama an yanke hadayun hatsi da hadayun sha daga gidan Allahnku. ");
INSERT INTO hausa_vpl VALUES ("JL1_14","030_1_14","JOL","1","14","14","Ku yi shelar azumi mai tsarki; ku kira tsarkakan taro. Ku kira dattawa da kuma dukan mazaunan ƙasar zuwa gidan Ubangiji Allahnku, ku kuma yi kuka ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JL1_15","030_1_15","JOL","1","15","15","Kaito saboda wannan rana! Gama ranar Ubangiji ta kusa, za tă zo kamar hallaka daga wurin Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("JL1_16","030_1_16","JOL","1","16","16","Ba a yanke abinci a idanunmu, farin ciki da kuma murna daga gidan Allahnmu ba? ");
INSERT INTO hausa_vpl VALUES ("JL1_17","030_1_17","JOL","1","17","17","Iri suna ta yanƙwanewa a busasshiyar ƙasa Ɗakunan ajiya sun lalace, an rurrushe rumbunan hatsin, gama hatsi ya ƙare. ");
INSERT INTO hausa_vpl VALUES ("JL1_18","030_1_18","JOL","1","18","18","Ji yadda dabbobi suke nishi! Garkunan shanu sun ruɗe saboda ba su da ciyawa, har garkunan tumaki ma suna shan wahala. ");
INSERT INTO hausa_vpl VALUES ("JL1_19","030_1_19","JOL","1","19","19","A gare ka, ya Ubangiji, nake kira, gama wuta ta cinye wurin kiwo harshen wuta kuma ya ƙone dukan itatuwan jeji. ");
INSERT INTO hausa_vpl VALUES ("JL1_20","030_1_20","JOL","1","20","20","Har ma namun jeji suna haki gare ka; rafuffuka sun bushe wuta kuma ta cinye wurin kiwo a jeji. ");
INSERT INTO hausa_vpl VALUES ("JL2_1","030_2_1","JOL","2","1","1","Ku busa ƙaho a cikin Sihiyona; ku yi karar amo a tsaunina mai tsarki. Bari dukan mazaunan ƙasar su yi rawan jiki, gama ranar Ubangiji tana zuwa. Tana gab da faruwa ");
INSERT INTO hausa_vpl VALUES ("JL2_2","030_2_2","JOL","2","2","2","rana ce ta baƙin duhu ƙirin, ranar gizagizai ce baƙi ƙirin. Babbar rundunar mayaƙa mai ƙarfi tana zuwa kamar ketowar alfijir a kan duwatsu yadda ba a taɓa ganin irinta ba, ba kuwa za a ƙara ganin irinta ba har tsararraki masu zuwa. ");
INSERT INTO hausa_vpl VALUES ("JL2_3","030_2_3","JOL","2","3","3","A gabansu wuta tana ci, a bayansu ga harshen wuta yana ci, A gabansu ƙasa ta yi kamar gonar Eden, a bayansu kuma jeji ne wofi, babu abin da ya kuɓuce musu. ");
INSERT INTO hausa_vpl VALUES ("JL2_4","030_2_4","JOL","2","4","4","Suna da kamannin dawakai; suna gudu kamar dokin yaƙi. ");
INSERT INTO hausa_vpl VALUES ("JL2_5","030_2_5","JOL","2","5","5","Da motsi kamar na kekunan yaƙi sun tsallake ƙwanƙolin duwatsu, kamar ƙarar harshen wuta mai cin tattaka, kamar runduna mai ƙarfi wadda ta ja dāgār yaƙi. ");
INSERT INTO hausa_vpl VALUES ("JL2_6","030_2_6","JOL","2","6","6","Da ganinsu, al’ummai sun kamu da azaba; kowace fuska ta yanƙwane. ");
INSERT INTO hausa_vpl VALUES ("JL2_7","030_2_7","JOL","2","7","7","Sukan auka kamar jarumawa; sukan hau katanga kamar sojoji. Kowa yana takawa bisa ga tsari, ba mai kaucewa. ");
INSERT INTO hausa_vpl VALUES ("JL2_8","030_2_8","JOL","2","8","8","Ba sa turin juna, kowane yakan miƙe gaba. Sukan kutsa cikin abokan gāba ba mai tsai da su. ");
INSERT INTO hausa_vpl VALUES ("JL2_9","030_2_9","JOL","2","9","9","Sukan ruga cikin birni, suna gudu a kan katanga. Sukan hau gidaje, sukan shiga ta tagogi kamar ɓarayi. ");
INSERT INTO hausa_vpl VALUES ("JL2_10","030_2_10","JOL","2","10","10","A gabansu duniya takan girgiza, sararin sama kuma yakan jijjigu, rana da wata su yi duhu, taurari kuma ba sa ba da haske. ");
INSERT INTO hausa_vpl VALUES ("JL2_11","030_2_11","JOL","2","11","11","Ubangiji ya yi tsawa wa shugaban mayaƙansa; sojojinsa sun fi a ƙirge masu ƙarfi ne kuma su waɗanda suke biyayya da umarninsa. Ranar Ubangiji da girma take; mai banrazana. Wa zai iya jure mata? ");
INSERT INTO hausa_vpl VALUES ("JL2_12","030_2_12","JOL","2","12","12","“Ko yanzu”, in ji Ubangiji, “Ku juyo gare ni da dukan zuciyarku, da azumi da kuka da makoki.” ");
INSERT INTO hausa_vpl VALUES ("JL2_13","030_2_13","JOL","2","13","13","Ku kyakkece zuciyarku ba rigunanku ba. Ku juyo ga Ubangiji Allahnku, gama shi mai alheri ne mai tausayi kuma mai jinkirin fushi da yawan ƙauna, yakan kuma janye daga aika da bala’i. ");
INSERT INTO hausa_vpl VALUES ("JL2_14","030_2_14","JOL","2","14","14","Wa ya sani? Ko zai juya yă kuma ji tausayi yă sa mana albarka ta wurin hadaya ta gari da hadaya ta sha wa Ubangiji Allahnku. ");
INSERT INTO hausa_vpl VALUES ("JL2_15","030_2_15","JOL","2","15","15","A busa ƙaho a Sihiyona, a yi shelar azumi mai tsarki, a kira tsarkakan taro. ");
INSERT INTO hausa_vpl VALUES ("JL2_16","030_2_16","JOL","2","16","16","A tattara mutane; ku tsarkake taron; ku kawo dattawa wuri ɗaya; ku kuma tara yara, da waɗanda suke shan mama. Bari ango yă bar ɗakinsa amarya kuma lolokinta. ");
INSERT INTO hausa_vpl VALUES ("JL2_17","030_2_17","JOL","2","17","17","Bari firistocin da suke yin hidima a gaban Ubangiji, su yi kuka tsakanin filin haikali da bagade. Bari su ce, “Ka cece mutanenka, ya Ubangiji. Kada ka bar gādonka yă zama abin dariya, da abin ba’a a cikin al’ummai. Me zai sa a ce a cikin mutane, ‘Ina Allahnsu yake?’ ” ");
INSERT INTO hausa_vpl VALUES ("JL2_18","030_2_18","JOL","2","18","18","Ta haka Ubangiji zai yi kishin ƙasarsa yă kuma ji tausayin mutanensa. ");
INSERT INTO hausa_vpl VALUES ("JL2_19","030_2_19","JOL","2","19","19","Ubangiji zai amsa musu ya ce, “Ina aika da hatsi, sabon ruwan inabi, da mai, isashe da zai ƙosar da ku sosai; ba kuma zan ƙara maishe ku abin dariya ga al’ummai ba. ");
INSERT INTO hausa_vpl VALUES ("JL2_20","030_2_20","JOL","2","20","20","“Zan kori sojojin arewa nesa da ku, in tura su cikin busasshiyar ƙasa marar amfani kuma, kuma da sawunsu na gaba zan tura su zuwa gabashin teku da kuma sawunsu na baya tura su zuwa yammanci a Bahar Rum. Warinsu kuma zai bazu; ɗoyinsu zai tashi.” Tabbatacce ya yi al’amura masu girma. ");
INSERT INTO hausa_vpl VALUES ("JL2_21","030_2_21","JOL","2","21","21","Kada ki ji tsoro, ya ƙasa; ki yi murna ki kuma yi farin ciki. Tabbatacce Ubangiji ya yi abubuwa masu girma. ");
INSERT INTO hausa_vpl VALUES ("JL2_22","030_2_22","JOL","2","22","22","Kada ku ji tsoro, ya ku namun jeji, gama wuraren kiwo sun yi kore shar. Itatuwa suna ba da ’ya’yansu; itacen ɓaure da na inabi suna ba da amfaninsu. ");
INSERT INTO hausa_vpl VALUES ("JL2_23","030_2_23","JOL","2","23","23","Ku yi murna, ya ku mutanen Sihiyona, ku yi farin ciki cikin Ubangiji Allahnku, gama ya ba ku ruwan bazara cikin adalci. Yakan aika muku yayyafi a yalwace, na bazara da na kaka, kamar dā. ");
INSERT INTO hausa_vpl VALUES ("JL2_24","030_2_24","JOL","2","24","24","Masussukai za su cika da hatsi; randuna za su cika da sabon ruwan inabi da mai suna zuba. ");
INSERT INTO hausa_vpl VALUES ("JL2_25","030_2_25","JOL","2","25","25","“Zan mayar muku da abin da fāra suka ci a waɗannan shekaru waɗanda ɗango da fāra masu gaigayewa, da kuma sauran fāra da tarin fāra babban mayaƙan da na aika don su fāɗa muku. ");
INSERT INTO hausa_vpl VALUES ("JL2_26","030_2_26","JOL","2","26","26","Za ku sami a wadace ku ci, har sai kun ƙoshi, za ku kuma yabi sunan Ubangiji Allahnku, wanda ya yi muku ayyukan banmamaki; mutanena ba za su ƙara shan kunya ba. ");
INSERT INTO hausa_vpl VALUES ("JL2_27","030_2_27","JOL","2","27","27","Sa’an nan za ku sani ina cikin Isra’ila, cewa ni ne Ubangiji Allahnku, babu wani kuma; mutanena ba za su ƙara shan kunya ba. ");
INSERT INTO hausa_vpl VALUES ("JL2_28","030_2_28","JOL","2","28","28","“Daga baya kuma, zan zuba Ruhuna a bisan dukan mutane. ’Ya’yanku maza da mata za su yi annabci, tsofaffinku za su yi mafarkai, matasanku za su ga wahayoyi. ");
INSERT INTO hausa_vpl VALUES ("JL2_29","030_2_29","JOL","2","29","29","Har ma a bisan bayina, maza da mata, zan zuba Ruhuna a kwanakin nan. ");
INSERT INTO hausa_vpl VALUES ("JL2_30","030_2_30","JOL","2","30","30","Zan nuna abubuwan banmamaki a cikin sammai da kuma a kan duniya, za a ga jini da wuta da murtukewar hayaƙi. ");
INSERT INTO hausa_vpl VALUES ("JL2_31","030_2_31","JOL","2","31","31","Rana za tă duhunta wata kuma yă zama jini kafin isowar babbar ranan nan mai banrazana ta Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JL2_32","030_2_32","JOL","2","32","32","Amma dukan waɗanda suka nemi Ubangiji za su tsira. Kamar yadda Ubangiji ya ce, gama a Dutsen Sihiyona da Urushalima akwai ceto, a cikin waɗannan da Ubangiji ya kira. ");
INSERT INTO hausa_vpl VALUES ("JL3_1","030_3_1","JOL","3","1","1","“A waɗancan kwanaki da kuma a wancan lokaci, sa’ad da zan maido da arzikin Yahuda da Urushalima, ");
INSERT INTO hausa_vpl VALUES ("JL3_2","030_3_2","JOL","3","2","2","zan tattara dukan al’ummai in kuma kawo su Kwarin Yehoshafat Can zan yi musu shari’a game da gādona, mutanena Isra’ila, gama sun warwatsar da mutanena a cikin al’ummai sun kuma raba ƙasata. ");
INSERT INTO hausa_vpl VALUES ("JL3_3","030_3_3","JOL","3","3","3","Sun jefa ƙuri’a a kan mutanena suna kuma sayar da yara maza don karuwanci, sun sayar da ’yan matan domin ruwan inabi wanda za su sha. ");
INSERT INTO hausa_vpl VALUES ("JL3_4","030_3_4","JOL","3","4","4","“Yanzu mene ne damuwarku da ni, ya Taya da Sidon da kuma dukan mazaunan yankunan Filistiya? Kuna ƙoƙari ku sāka mini don abin da na yi ne? In kuna sāka mini ne, to, da gaggawa zan mayar muku da sakayya a kanku. ");
INSERT INTO hausa_vpl VALUES ("JL3_5","030_3_5","JOL","3","5","5","Gama kun kwashe azurfata da zinariyata kun kuma washe dukiyata mafi kyau kun kai cikin haikalinku. ");
INSERT INTO hausa_vpl VALUES ("JL3_6","030_3_6","JOL","3","6","6","Kun sayar da mutanen Yahuda da na Urushalima ga mutanen Hellenawa, don ku aika da su nesa da ƙasarsu. ");
INSERT INTO hausa_vpl VALUES ("JL3_7","030_3_7","JOL","3","7","7","“Duba, zan dawo da su daga wuraren da kuka sayar da su, in kuma yi muku abin da kuka yi musu. ");
INSERT INTO hausa_vpl VALUES ("JL3_8","030_3_8","JOL","3","8","8","Zan sayar da ’ya’yanku maza da mata ga mutanen Yahuda, su kuma za su sayar da su ga mutanen Sabenawa, al’umma da take nesa da ku.” Ubangiji ya faɗa. ");
INSERT INTO hausa_vpl VALUES ("JL3_9","030_3_9","JOL","3","9","9","Ku yi shelar wannan ga al’ummai. Ku yi shirin yaƙi! Ku tā da jarumawa! Bari mayaƙa su ja kusa su kai hari. ");
INSERT INTO hausa_vpl VALUES ("JL3_10","030_3_10","JOL","3","10","10","Ku bubbuge garemaninku su zama takuba da kuma laujenku su zama māsu. Bari raunana su ce, “Ni mai ƙarfi ne!” ");
INSERT INTO hausa_vpl VALUES ("JL3_11","030_3_11","JOL","3","11","11","Ku gaggauta, dukanku al’ummai daga kowane ɓangare, ku tattaru a can. Ka sauko da mayaƙanka, ya Ubangiji! ");
INSERT INTO hausa_vpl VALUES ("JL3_12","030_3_12","JOL","3","12","12","“Bari a tā da dukan al’ummai; bari su kutsa zuwa Kwarin Yehoshafat gama a can zan zauna in shari’anta dukan al’ummai daga kowane ɓangare. ");
INSERT INTO hausa_vpl VALUES ("JL3_13","030_3_13","JOL","3","13","13","Ku fito da lauje, gama girbi ya nuna. Ku zo, ku tattaka inabin, gama wurin matsewar ruwan inabi ya cika randunan tarawa kuma sun cika har suna zuba, muguntarsu da girma take!” ");
INSERT INTO hausa_vpl VALUES ("JL3_14","030_3_14","JOL","3","14","14","Dubun dubbai suna a cikin kwarin yanke shawara! Gama ranar Ubangiji ta yi kusa a cikin kwarin yanke shawara. ");
INSERT INTO hausa_vpl VALUES ("JL3_15","030_3_15","JOL","3","15","15","Za a duhunta rana da wata, taurari kuma ba za su ba da haske ba. ");
INSERT INTO hausa_vpl VALUES ("JL3_16","030_3_16","JOL","3","16","16","Ubangiji zai yi ruri daga Sihiyona tsawa kuma daga Urushalima; duniya da sararin sama za su yi rawan jiki. Amma Ubangiji zai zama mafakar mutanensa, mafaka ga mutanensa Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("JL3_17","030_3_17","JOL","3","17","17","“Sa’an nan za ku san cewa ni, Ubangiji Allahnku, ina zaune a Sihiyona, dutsena mai tsarki. Urushalima za tă zama mai tsarki; baƙi ba za su ƙara mamaye ta ba. ");
INSERT INTO hausa_vpl VALUES ("JL3_18","030_3_18","JOL","3","18","18","“A wannan rana duwatsu za su ɗiga da sabon ruwan inabi, tuddai kuma za su malmalo madara; dukan rafuffukan Yahuda za su yi ta gudano da ruwa. Maɓulɓula kuma za tă fito daga gidan Ubangiji haka ma ruwa a kwarin itatuwan ƙirya. ");
INSERT INTO hausa_vpl VALUES ("JL3_19","030_3_19","JOL","3","19","19","Amma Masar za tă zama kango, Edom kuma hamada marar amfani, saboda kama-karyar da aka yi wa mutanen Yahuda, a ƙasar da aka zub da jinin marasa laifi. ");
INSERT INTO hausa_vpl VALUES ("JL3_20","030_3_20","JOL","3","20","20","Za a zauna a Yahuda har abada Urushalima kuma daga tsara zuwa tsara. ");
INSERT INTO hausa_vpl VALUES ("JL3_21","030_3_21","JOL","3","21","21","Alhakin jininsu, wanda ban gafarta ba, zan gafarta.” ");
INSERT INTO hausa_vpl VALUES ("AM1_1","031_1_1","AMO","1","1","1","Kalmomin Amos, ɗaya daga cikin makiyayan Tekowa, abubuwan da ya gani game da Isra’ila shekaru biyu kafin a yi girgizar ƙasa, a lokacin da Uzziya yake sarkin Yahuda, Yerobowam ɗan Yowash kuma yake sarkin Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("AM1_2","031_1_2","AMO","1","2","2","Ya ce, “Ubangiji ya yi ruri daga Sihiyona ya kuma yi tsawa daga Urushalima; wuraren kiwo duk sun bushe, dutsen Karmel kuma ya yi yaushi.” ");
INSERT INTO hausa_vpl VALUES ("AM1_3","031_1_3","AMO","1","3","3","Ga abin da Ubangiji ya ce, “Saboda zunubai uku na Damaskus, har guda huɗu ma, ba zan fasa hukunta su ba. Domin sun ci zalunci Gileyad zalunci mai tsanani, ");
INSERT INTO hausa_vpl VALUES ("AM1_4","031_1_4","AMO","1","4","4","zan sa wuta a gidan Hazayel, da za tă ƙona kagarun Ben-Hadad. ");
INSERT INTO hausa_vpl VALUES ("AM1_5","031_1_5","AMO","1","5","5","Zan kakkarye ƙofofin Bet-Damaskus; zan hallaka sarkin da yake cikin Kwarin Awen da kuma mai riƙe da sandar mulkin Bet-Eden. Mutanen Aram za su je bauta a ƙasar Kir,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM1_6","031_1_6","AMO","1","6","6","Ga abin da Ubangiji ya ce, “Saboda zunubai uku na Gaza, har guda huɗu ma, ba zan fasa hukunta su ba. Don sun kwashe al’umma gaba ɗaya sun sayar wa Edom, ");
INSERT INTO hausa_vpl VALUES ("AM1_7","031_1_7","AMO","1","7","7","Zan aika da wuta a katangar Gaza ta ƙone duk kagarunta. ");
INSERT INTO hausa_vpl VALUES ("AM1_8","031_1_8","AMO","1","8","8","Zan hallaka sarkin Ashdod da kuma mai riƙe da sandar mulki na Ashkelon. Zan hukunta Ekron, har sai dukan Filistiyawa sun mutu,” in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("AM1_9","031_1_9","AMO","1","9","9","Ga abin da Ubangiji ya ce, “Saboda zunubai uku na Taya, har guda huɗu ma, ba zan fasa hukunta su ba. Don sun kwashe al’umma gaba ɗaya sun kai su bauta a Edom, ba su kula da yarjejjeniyar da aka yi ta zama kamar ’yan’uwa ba, ");
INSERT INTO hausa_vpl VALUES ("AM1_10","031_1_10","AMO","1","10","10","zan aika da wuta a Taya, da za tă ƙone kagarunta.” ");
INSERT INTO hausa_vpl VALUES ("AM1_11","031_1_11","AMO","1","11","11","Ga abin da Ubangiji ya ce, “Saboda zunubai uku na Edom, har guda huɗu ma, ba zan fasa hukunta shi ba. Don ya fafari ɗan’uwansa da takobi, babu tausayi, domin ya ci gaba da fusata bai yarda yă huce daga fushinsa ba. ");
INSERT INTO hausa_vpl VALUES ("AM1_12","031_1_12","AMO","1","12","12","Zan aika wuta a Teman da za tă ƙone kagarun Bozra.” ");
INSERT INTO hausa_vpl VALUES ("AM1_13","031_1_13","AMO","1","13","13","Ga abin da Ubangiji ya ce, “Saboda zunubai uku na Ammon, har guda huɗu ma, ba zan fasa hukunta shi ba. Don ya tsaga cikin matan Gileyad masu juna biyu don kawai yă ƙwace ƙasar. ");
INSERT INTO hausa_vpl VALUES ("AM1_14","031_1_14","AMO","1","14","14","Zan sa wuta a katangar Rabba da za tă ƙone kagarunta za a yi kururuwa a ranar yaƙi, faɗan kuwa zai yi rugugi kamar hadiri. ");
INSERT INTO hausa_vpl VALUES ("AM1_15","031_1_15","AMO","1","15","15","Sarkinta zai je bauta, shi da ma’aikatansa,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM2_1","031_2_1","AMO","2","1","1","Ga abin da Ubangiji ya ce, “Saboda zunubai uku na Mowab, har guda huɗu ma, ba zan fasa hukunta su ba. Gama ya ƙone ƙasusuwan sarkin Edom suka zama sai ka ce toka. ");
INSERT INTO hausa_vpl VALUES ("AM2_2","031_2_2","AMO","2","2","2","Zan sa wuta a Mowab da za tă ƙone kagarun Keriyot Mowab za tă gangara cikin hayaniya mai girma cikin kururuwar yaƙi da kuma ƙarar ƙaho. ");
INSERT INTO hausa_vpl VALUES ("AM2_3","031_2_3","AMO","2","3","3","Zan hallaka mai mulkinta zan kuma kashe shugabanninta.” ");
INSERT INTO hausa_vpl VALUES ("AM2_4","031_2_4","AMO","2","4","4","Ga abin da Ubangiji ya ce, “Saboda zunubai uku na Yahuda, har guda huɗu ma, ba zan fasa hukunta su ba. Gama sun ƙi bin dokar Ubangiji ba su kuma yi biyayya da ƙa’idodinsa ba, domin allolin ƙarya sun ruɗe su, allolin da kakanninsu suka bauta. ");
INSERT INTO hausa_vpl VALUES ("AM2_5","031_2_5","AMO","2","5","5","Zan sa wuta a Yahuda da za tă ƙone kagarun Urushalima.” ");
INSERT INTO hausa_vpl VALUES ("AM2_6","031_2_6","AMO","2","6","6","Ga abin da Ubangiji ya ce, “Saboda zunubai uku na Isra’ila, har guda huɗu ma, ba zan fasa hukunta su ba. Don sun sayar da adalai waɗanda suka kāsa biyan bashinsu. Sun kuma sayar da matalauta waɗanda bashinsu bai ma kai ko kuɗin bi-labi ba. ");
INSERT INTO hausa_vpl VALUES ("AM2_7","031_2_7","AMO","2","7","7","Sun tattake kawunan matalauta kamar yadda suke taka laka suka kuma danne wa marasa galihu gaskiya. Uba da ɗa su na kwana da yarinya guda, suna kuma ɓata sunana mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("AM2_8","031_2_8","AMO","2","8","8","Suna kwanciya kurkusa da kowane bagade a kan tufafin da suka karɓe jingina. A gidajen allolinsu sukan sha ruwan inabin da suka karɓo daga wurin waɗanda suka ci wa tara. ");
INSERT INTO hausa_vpl VALUES ("AM2_9","031_2_9","AMO","2","9","9","“Na hallaka mutumin Amoriyawa a gabansu, ko da yake ya yi dogo kamar itacen al’ul kuma mai ƙarfi kamar itacen oak. Na hallaka ’ya’yan itatuwansa daga sama, da kuma jijiyoyinsa daga ƙasa. ");
INSERT INTO hausa_vpl VALUES ("AM2_10","031_2_10","AMO","2","10","10","Na fitar da ku daga ƙasar Masar, na kuma bishe ku tsawon shekaru arba’in a cikin hamada don in ba ku ƙasar Amoriyawa. ");
INSERT INTO hausa_vpl VALUES ("AM2_11","031_2_11","AMO","2","11","11","“Na kuma tā da annabawa daga cikin ’ya’yanku maza waɗansu kuma su zama keɓaɓɓu daga cikin samarinku. Ba haka ba ne, mutanen Isra’ila?” In ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM2_12","031_2_12","AMO","2","12","12","“Amma kuka sa keɓaɓɓun suka sha ruwan inabi kuka kuma umarci annabawa kada su yi annabci. ");
INSERT INTO hausa_vpl VALUES ("AM2_13","031_2_13","AMO","2","13","13","“Saboda haka, yanzu zan murƙushe ku kamar yadda amalanke yakan murƙushe sa’ad da aka yi masa labtun hatsi. ");
INSERT INTO hausa_vpl VALUES ("AM2_14","031_2_14","AMO","2","14","14","Masu gudu da sauri ba za su tsira ba, masu ƙarfi ba za su iya yin amfani da ƙarfinsu ba, jarumi kuma ba zai iya ceton ransa ba. ");
INSERT INTO hausa_vpl VALUES ("AM2_15","031_2_15","AMO","2","15","15","’Yan baka ba za su iya dāgewa ba, masu saurin gudu ba za su tsira ba mahayin dawakai kuma ba zai tsere da ransa ba. ");
INSERT INTO hausa_vpl VALUES ("AM2_16","031_2_16","AMO","2","16","16","Ko jarumawa mafi jaruntaka za su gudu tsirara a ranan nan,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM3_1","031_3_1","AMO","3","1","1","Ku ji wannan maganar da Ubangiji ya yi game da ku, ya ku jama’ar Isra’ila, a kan dukan iyalin da na fitar daga Masar. ");
INSERT INTO hausa_vpl VALUES ("AM3_2","031_3_2","AMO","3","2","2","“Ku ne kaɗai na zaɓa cikin dukan al’umman duniya; saboda haka zan hukunta ku saboda dukan zunubanku.” ");
INSERT INTO hausa_vpl VALUES ("AM3_3","031_3_3","AMO","3","3","3","Mutum biyu za su iya yin tafiya tare in ba su yarda su yi haka ba? ");
INSERT INTO hausa_vpl VALUES ("AM3_4","031_3_4","AMO","3","4","4","Zaki yakan yi ruri a jeji in bai sami kama nama ba? Zai yi gurnani a cikin kogonsa in bai kama kome ba? ");
INSERT INTO hausa_vpl VALUES ("AM3_5","031_3_5","AMO","3","5","5","Tsuntsu yakan fāɗa a tarko a ƙasa inda ba a sa tarko ba, ko tarko yakan zargu daga ƙasa in ba abin da ya taɓa shi? ");
INSERT INTO hausa_vpl VALUES ("AM3_6","031_3_6","AMO","3","6","6","Idan aka busa ƙaho a ciki birni mutane ba sa yin rawar jiki? Sa’ad da bala’i ya auko wa birni, ba Ubangiji ne ya sa a kawo shi ba? ");
INSERT INTO hausa_vpl VALUES ("AM3_7","031_3_7","AMO","3","7","7","Ba shakka, Ubangiji Mai Iko Duka ba ya yin wani abu ba tare da ya sanar wa bayinsa annabawa ba. ");
INSERT INTO hausa_vpl VALUES ("AM3_8","031_3_8","AMO","3","8","8","Zaki ya yi ruri, wa ba zai tsorata ba? Ubangiji Mai Iko Duka ya yi magana, wa ba zai yi annabci ba? ");
INSERT INTO hausa_vpl VALUES ("AM3_9","031_3_9","AMO","3","9","9","Ku yi shela ga kagarun Ashdod da kuma ga kagarun Masar. “Ku tara kanku a tuddan Samariya; ku ga rashin jituwar da take a cikinta, da kuma zaluncin da ake yi a cikin mutanenta.” ");
INSERT INTO hausa_vpl VALUES ("AM3_10","031_3_10","AMO","3","10","10","“Ba su ma san yadda za su yi abin da yake daidai ba,” in ji Ubangiji, “sun ɓoye ganima da abubuwan da suka washe a cikin kagarunsu.” ");
INSERT INTO hausa_vpl VALUES ("AM3_11","031_3_11","AMO","3","11","11","Saboda haka ga abin da Ubangiji Mai Iko Duka ya ce, “Abokin gāba zai ƙwace ƙasar, zai saukar da mafakarku, zai washe kagarunku.” ");
INSERT INTO hausa_vpl VALUES ("AM3_12","031_3_12","AMO","3","12","12","Ga abin da Ubangiji ya ce, “Kamar yadda makiyayi yakan ceci daga bakin zaki ƙasusuwa ƙafafu biyu kawai ko kunne ɗaya, haka za a ceci Isra’ilawa, masu zama a Samariya da kan gado kawai da kuma a ɗan ƙyalle a kan dogayen kujerunsu.” ");
INSERT INTO hausa_vpl VALUES ("AM3_13","031_3_13","AMO","3","13","13","“Ku ji wannan ku kuma yi wa gidan Yaƙub gargaɗi,” in ji Ubangiji, Ubangiji Allah Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("AM3_14","031_3_14","AMO","3","14","14","“A ranar da zan hukunta Isra’ila saboda zunubanta, zan hallaka bagadan Betel; za a yayyanka ƙahonin bagadan za su fāɗa ƙasa ");
INSERT INTO hausa_vpl VALUES ("AM3_15","031_3_15","AMO","3","15","15","Zan rushe gidan rani da na damina; gidajen da aka yi musu ado da hauren giwa za a rushe su haka ma duk za a rurrushe manyan gidaje,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM4_1","031_4_1","AMO","4","1","1","Ku kasa kunne ga wannan, ya ku shanun Bashan a kan Dutsen Samariya, ku matan da kuke cin zalin matalauta, kuke kuma danne matalauta, kuna kuma ce wa mazanku, “Ku kawo mana abin sha!” ");
INSERT INTO hausa_vpl VALUES ("AM4_2","031_4_2","AMO","4","2","2","Ubangiji Mai Iko Duka ya rantse da tsarkinsa. “Tabbatacce lokaci yana zuwa da za a jawo ku da ƙugiyoyi, na ƙarshenku za a kama da ƙugiyar kifi. ");
INSERT INTO hausa_vpl VALUES ("AM4_3","031_4_3","AMO","4","3","3","Dukanku za ku wuce ta kai tsaye ta inda katangar ta tsage, za a jefar da ku a Harmon,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM4_4","031_4_4","AMO","4","4","4","“Ku tafi Betel ku yi ta aikata zunubi; ku je Gilgal ku ƙara yin zunubi. Ku kawo hadayunku kowace safiya, zakkarku kowace shekara uku. ");
INSERT INTO hausa_vpl VALUES ("AM4_5","031_4_5","AMO","4","5","5","Ku ƙona burodinku mai yisti kamar hadaya ta godiya, ku yi fariya game da hadayunku na yarda rai, ku yi taƙama game da su, ya ku Isra’ilawa, gama abin da kuke jin daɗin aikata ke nan,” in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("AM4_6","031_4_6","AMO","4","6","6","“Na bar ku da yunwa a kowace birni, da kuma rashin abinci a kowane gari, duk da haka ba ku juyo gare ni ba,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM4_7","031_4_7","AMO","4","7","7","“Na kuma hana muku ruwan sama tun shuke-shuken suna wata uku kafin lokacin girbi. Na sa aka yi ruwan sama a wani gari, sai na hana a yi a wani gari. Wata gona ta sami ruwan sama; wata gona kuma ta bushe. ");
INSERT INTO hausa_vpl VALUES ("AM4_8","031_4_8","AMO","4","8","8","Mutane suna tangaɗi daga gari zuwa gari suna neman ruwa amma ba su sami isashen ruwan sha ba, duk da haka ba ku juyo gare ni ba,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM4_9","031_4_9","AMO","4","9","9","“Sau da yawa na ɓata gonakinku da fumfuna da kuma cuta. Fāri suka cinye itatuwanku na inabi da na ɓaure, da na zaitun duk da haka ba ku juyo gare ni ba,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM4_10","031_4_10","AMO","4","10","10","“Na aiko muku annoba yadda na yi a Masar. Na karkashe samarinku da takobi, tare da kamammun dawakanku. Na cika hancinku da warin sansaninku, duk da haka ba ku juyo gare ni ba” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM4_11","031_4_11","AMO","4","11","11","“Na hallaka waɗansunku kamar yadda na hallaka Sodom da Gomorra. Kuna kama da itace mai cin wutar da na cire daga cikin wuta, duk da haka ba ku juyo gare ni ba,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM4_12","031_4_12","AMO","4","12","12","“Saboda haka ga abin da zan yi da ku, ya Isra’ila, don kuwa zan yi muku haka, sai ku yi shirin gamuwa da Allahnku, ya Isra’ila.” ");
INSERT INTO hausa_vpl VALUES ("AM4_13","031_4_13","AMO","4","13","13","Shi wanda ya yi duwatsu, ya halicci iska, ya kuma bayyana wa mutum tunaninsa, shi wanda ya juya safiya ta zama duhu yana takawa a wurare masu tsawo na duniya, Ubangiji Allah Maɗaukaki ne sunansa. ");
INSERT INTO hausa_vpl VALUES ("AM5_1","031_5_1","AMO","5","1","1","Ku ji wannan magana, ya gidan Isra’ila, ina makokin nan dominku. ");
INSERT INTO hausa_vpl VALUES ("AM5_2","031_5_2","AMO","5","2","2","“Budurwa Isra’ila ta fāɗi, ba za tă ƙara tashi ba, an yashe ta a ƙasarta, ba wanda zai ɗaga ta.” ");
INSERT INTO hausa_vpl VALUES ("AM5_3","031_5_3","AMO","5","3","3","Ga abin da Ubangiji Mai Iko Duka ya ce, “Birnin da ta fitar da masu ƙarfi dubbai don Isra’ila guda ɗari kaɗai za su dawo; garin da ya fitar da masu ƙarfi ɗari kuwa goma kaɗai za su dawo.” ");
INSERT INTO hausa_vpl VALUES ("AM5_4","031_5_4","AMO","5","4","4","Ga abin da Ubangiji ya ce wa gidan Isra’ila. “Ku neme ni ku rayu; ");
INSERT INTO hausa_vpl VALUES ("AM5_5","031_5_5","AMO","5","5","5","kada ku nemi Betel, kada ku je Gilgal, kada ku yi tafiya zuwa Beyersheba. Gama ba shakka Gilgal za tă tafi bauta, za a kuwa mai da Betel ba kome ba.” ");
INSERT INTO hausa_vpl VALUES ("AM5_6","031_5_6","AMO","5","6","6","Ku nemi Ubangiji ku kuma rayu, ko kuwa zai ratsa yă share gidan Yusuf kamar wuta; zai cinye Betel kuwa ba zai sami wanda zai kashe ta ba. ");
INSERT INTO hausa_vpl VALUES ("AM5_7","031_5_7","AMO","5","7","7","Ku ne masu mai da gaskiya ta koma ɗaci ku kuma zubar da adalci. ");
INSERT INTO hausa_vpl VALUES ("AM5_8","031_5_8","AMO","5","8","8","(Shi wanda ya yi Taurarin nan da ake ce Kaza da ’Ya’yanta da kuma Mai Farauta da Kare, wanda ya mai da duhu ya zama haske ya kuma baƙanta rana ta zama dare, yakan kwashe ruwan teku ya zubar a ƙasa, Ubangiji ne sunansa, ");
INSERT INTO hausa_vpl VALUES ("AM5_9","031_5_9","AMO","5","9","9","yakan kawo hallaka a mafaka mai ƙarfi yakan kuma mai da birnin mai katanga ya zama kufai). ");
INSERT INTO hausa_vpl VALUES ("AM5_10","031_5_10","AMO","5","10","10","Ba ku son mai yin gaskiya a ɗakin shari’a kuna ƙin mai faɗar gaskiya. ");
INSERT INTO hausa_vpl VALUES ("AM5_11","031_5_11","AMO","5","11","11","Kuna matsa wa matalauta kuna sa su dole su ba ku hatsi. Saboda haka, ko da yake kun gina gidajen duwatsu, ba za ku zauna a cikinsu ba; ko da yake kun nome gonaki masu kyau, ba za ku sha ruwan inabinsu ba. ");
INSERT INTO hausa_vpl VALUES ("AM5_12","031_5_12","AMO","5","12","12","Gama na san yawan laifofinku da kuma girman zunubanku. Kuna danne masu adalci kuna kuma cin hanci kuna kuma hana a yi wa matalauta shari’ar adalci a majalisa. ");
INSERT INTO hausa_vpl VALUES ("AM5_13","031_5_13","AMO","5","13","13","Saboda haka mai hankali yakan yi shiru a lokuta kamar haka, gama lokutan mugaye ne. ");
INSERT INTO hausa_vpl VALUES ("AM5_14","031_5_14","AMO","5","14","14","Ku yi nagarta, ba mugunta ba; don ku rayu sa’an nan Ubangiji Allah Maɗaukaki zai kasance da ku, kamar yadda kuka ce zai yi. ");
INSERT INTO hausa_vpl VALUES ("AM5_15","031_5_15","AMO","5","15","15","Ku ƙi mugunta, ku ƙaunaci nagarta; ku dinga yin shari’ar gaskiya a ɗakunan shari’a. Mai yiwuwa Ubangiji Allah Maɗaukaki zai ji tausayin raguwar Yusuf. ");
INSERT INTO hausa_vpl VALUES ("AM5_16","031_5_16","AMO","5","16","16","Saboda haka ga abin da Ubangiji, Ubangiji Allah Maɗaukaki yana cewa, “Za a yi kururuwa a dukan tituna a kuma yi kuka don azaba a dukan wuraren da jama’a sukan taru. Za a yi kira ga manoma su yi kuka masu makoki kuma su yi kuka. ");
INSERT INTO hausa_vpl VALUES ("AM5_17","031_5_17","AMO","5","17","17","Za a yi kuka a dukan gonakin inabi, gama zan ratsa a cikinku,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM5_18","031_5_18","AMO","5","18","18","Kaitonku masu son ganin ranar Ubangiji! Don me kuke son ganin ranar Ubangiji? Za a duhunta ranan nan, ba haske ba. ");
INSERT INTO hausa_vpl VALUES ("AM5_19","031_5_19","AMO","5","19","19","Za ku zama kamar mutanen da suka guje wa zaki sai suka fāɗa a hannun beyar, ko kuma kamar wanda ya shiga gida ya dāfa hannu a bango sai maciji ya sare shi. ");
INSERT INTO hausa_vpl VALUES ("AM5_20","031_5_20","AMO","5","20","20","Ashe, ranar Ubangiji ba duhu ba ce, a maimakon haske, duhu wuluk, ba tare da ko ɗan haske ba. ");
INSERT INTO hausa_vpl VALUES ("AM5_21","031_5_21","AMO","5","21","21","“Na ƙi, ina kuma ƙyamar bukukkuwanku na addini; ba na son ganin tarurrukanku. ");
INSERT INTO hausa_vpl VALUES ("AM5_22","031_5_22","AMO","5","22","22","Ko da kun kawo mini hadayu na ƙonawa da kuma hadayu na hatsi, ba zan karɓa ba. Ko da kun kawo zaɓaɓɓun hadayu na zumunta, ba zan ɗauke su a bakin kome ba. ");
INSERT INTO hausa_vpl VALUES ("AM5_23","031_5_23","AMO","5","23","23","Ku tashi daga nan da surutan waƙoƙinku! Ba zan saurari kaɗe-kaɗe da bushe bushenku ba. ");
INSERT INTO hausa_vpl VALUES ("AM5_24","031_5_24","AMO","5","24","24","Amma bari gaskiya ta kwararo kamar kogi, adalci kuma kamar rafin da ba ya taɓa bushewa! ");
INSERT INTO hausa_vpl VALUES ("AM5_25","031_5_25","AMO","5","25","25","“Kun kawo mini hadayu da sadakoki shekaru arba’in a cikin jeji, ya ku gidan Isra’ila? ");
INSERT INTO hausa_vpl VALUES ("AM5_26","031_5_26","AMO","5","26","26","Kun ɗaga masujadar sarkinku, siffofin gumakanku, tauraron allahnku, wanda kuka yi wa kanku. ");
INSERT INTO hausa_vpl VALUES ("AM5_27","031_5_27","AMO","5","27","27","Saboda haka zan tura ku zaman bauta gaba da Damaskus,” in ji Ubangiji, wanda sunansa ne Allah Mai Iko. ");
INSERT INTO hausa_vpl VALUES ("AM6_1","031_6_1","AMO","6","1","1","Taku ta ƙare, ku da kuke zaman sakewa a Sihiyona, da ku waɗanda kuke ji zama a Dutsen Samariya lafiya ne, ku manyan mutanen ƙasar da take sananniya, waɗanda mutanen Isra’ila suke zuwa! ");
INSERT INTO hausa_vpl VALUES ("AM6_2","031_6_2","AMO","6","2","2","Ku je Kalne ku dube ta; ku wuce daga can zuwa Hamat-rabba, sa’an nan ku gangara zuwa Gat a Filistiya. Sun fi masarautunku biyu ne? Ƙasarsu ta fi taku girma? ");
INSERT INTO hausa_vpl VALUES ("AM6_3","031_6_3","AMO","6","3","3","Kuna ƙoƙari ku kauce wa wannan muguwar rana kuna kuma jawo mulkin tashin hankali kusa. ");
INSERT INTO hausa_vpl VALUES ("AM6_4","031_6_4","AMO","6","4","4","Kuna kwanciya a kan gadajen da aka yi musu shimfiɗar hauren giwa kuna mimmiƙe a kan kujerunku. Kuna cin naman ƙibabbun raguna da na ƙosassun ’yan maruƙa. ");
INSERT INTO hausa_vpl VALUES ("AM6_5","031_6_5","AMO","6","5","5","Kuna kaɗa molayenku yadda Dawuda ya yi kuna ƙirƙiro waƙoƙi a kan kayan kaɗe-kaɗe. ");
INSERT INTO hausa_vpl VALUES ("AM6_6","031_6_6","AMO","6","6","6","Da manyan kwanoni kuke shan ruwan inabi kuna kuma shafa mai mafi kyau, amma ba kwa baƙin ciki game da kangon da Yusuf ya zama. ");
INSERT INTO hausa_vpl VALUES ("AM6_7","031_6_7","AMO","6","7","7","Saboda haka za ku zama na farkon da za su tafi zaman bauta; bukukkuwanku da shagulgulanku za su ƙare. ");
INSERT INTO hausa_vpl VALUES ("AM6_8","031_6_8","AMO","6","8","8","Ubangiji Mai Iko Duka da kansa ya rantse, Ubangiji Allah Maɗaukaki ya furta, “Ina ƙyamar girman kan Yaƙub, ba na kuma son kagarunsa; zan ba da birnin da duk abin da yake cikinta.” ");
INSERT INTO hausa_vpl VALUES ("AM6_9","031_6_9","AMO","6","9","9","Ko da mutum goma ne suka ragu a gida guda, su ma za su mutu. ");
INSERT INTO hausa_vpl VALUES ("AM6_10","031_6_10","AMO","6","10","10","In kuma wani dangi ya shiga don yă fitar da gawawwakin yă ƙone ya kuwa tambayi wani wanda yake ɓoye a can, yana cewa, “Akwai wani tare da kai?” Ya kuwa ce, “Babu,” sai yă ce, “Kul! Kada mu ambaci sunan Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("AM6_11","031_6_11","AMO","6","11","11","Gama Ubangiji ya ba da umarni, zai kuma ragargaza babban gidan nan kucu-kucu ƙaramin gidan kuwa zai yi rugu-rugu da shi. ");
INSERT INTO hausa_vpl VALUES ("AM6_12","031_6_12","AMO","6","12","12","Dawakai sukan yi gudu a kan duwatsu? Wani yana iya yin noma a teku da shanun noma? Amma ga shi kun mai da gaskiya ta zama dafi amfanin adalci kuma ya zama ɗaci, ");
INSERT INTO hausa_vpl VALUES ("AM6_13","031_6_13","AMO","6","13","13","ku da kuke murna saboda an ci Lo Debar da yaƙi kuka kuma ce, “Ba da ƙarfinmu ne muka ƙwace Karnayim ba?” ");
INSERT INTO hausa_vpl VALUES ("AM6_14","031_6_14","AMO","6","14","14","Gama Ubangiji Allah Maɗaukaki ya ce, “Zan sa wata ƙasa ta tayar muku, ya ku gidan Isra’ila, wadda za tă matsa muku tun daga Lebo Hamat zuwa kwarin Araba.” ");
INSERT INTO hausa_vpl VALUES ("AM7_1","031_7_1","AMO","7","1","1","Ga abin da Ubangiji Mai Iko Duka ya nuna mini. Ubangiji yana shirya cincirindon fāri bayan da aka ƙarasa yankan rabon hatsin da yake na sarki, hatsi na biyu kuma yake tohuwa. ");
INSERT INTO hausa_vpl VALUES ("AM7_2","031_7_2","AMO","7","2","2","Sa’ad da suka cinye kome, sai na yi kira, na ce, “Ubangiji Mai Iko Duka, ka gafarta! Ta yaya Yaƙub zai tsira? Ga shi ɗan ƙarami ne!” ");
INSERT INTO hausa_vpl VALUES ("AM7_3","031_7_3","AMO","7","3","3","Saboda haka sai Ubangiji ya dakatar da nufinsa. “Wannan ba zai faru ba,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM7_4","031_7_4","AMO","7","4","4","Ga abin da Ubangiji Mai Iko Duka ya nuna mini. Ubangiji Mai Iko Duka yana shirin hukunta da wuta; wutar ta ƙone teku ta kuma ƙone ƙasa. ");
INSERT INTO hausa_vpl VALUES ("AM7_5","031_7_5","AMO","7","5","5","Sai na yi kira, na ce, “Ubangiji Mai Iko Duka, ina roƙonka ka dakata! Ta yaya Yaƙub zai tsira? Ga shi ɗan ƙarami ne!” ");
INSERT INTO hausa_vpl VALUES ("AM7_6","031_7_6","AMO","7","6","6","Saboda haka sai Ubangiji ya dakatar da nufinsa. “Wannan ma ba zai faru ba,” in ji Ubangiji Mai Iko Duka. ");
INSERT INTO hausa_vpl VALUES ("AM7_7","031_7_7","AMO","7","7","7","Ga abin da ya nuna mini. Ubangiji yana tsaye kusa da bangon da aka gina, bisa ga awon igiyar gwada gini, da kuma magwaji a hannunsa. ");
INSERT INTO hausa_vpl VALUES ("AM7_8","031_7_8","AMO","7","8","8","Sai Ubangiji ya tambaye ni, “Me kake gani, Amos?” Sai na amsa, “Igiyar gwada gini.” Sa’an nan Ubangiji ya ce, “Duba, zan sa igiyan nan a cikin mutanena Isra’ila; ba zan ƙara barinsu ba. ");
INSERT INTO hausa_vpl VALUES ("AM7_9","031_7_9","AMO","7","9","9","“Za a hallakar da wuraren sujada na Ishaku kuma tsarkakan wurare na Isra’ila za su zama kango; da takobina zan tayar wa gidan Yerobowam.” ");
INSERT INTO hausa_vpl VALUES ("AM7_10","031_7_10","AMO","7","10","10","Sai Amaziya firist na Betel ya aika da saƙo zuwa wurin Yerobowam sarkin Isra’ila. “Amos yana shirya maka maƙarƙashiya a tsakiyar Isra’ila. Ƙasar ba za tă iya ɗauka abubuwan da yake faɗi ba. ");
INSERT INTO hausa_vpl VALUES ("AM7_11","031_7_11","AMO","7","11","11","Gama ga abin da Amos yake cewa, “ ‘Yerobowam zai mutu ta wurin takobi, kuma tabbatacce Isra’ila za su tafi zaman bauta, nesa da ainihin ƙasarsu.’ ” ");
INSERT INTO hausa_vpl VALUES ("AM7_12","031_7_12","AMO","7","12","12","Sai Amaziya ya ce wa Amos, “Tafi daga nan, mai duba kawai! Koma ƙasar Yahuda. Ka nemi abin zaman garinka a can ka kuma yi annabcinka a can. ");
INSERT INTO hausa_vpl VALUES ("AM7_13","031_7_13","AMO","7","13","13","Kada ka ƙara yin annabci a Betel, gama nan wuri mai tsarki ne na sarki da kuma haikalin ƙasar.” ");
INSERT INTO hausa_vpl VALUES ("AM7_14","031_7_14","AMO","7","14","14","Amos ya amsa wa Amaziya, “Ni ba annabi ba ne ko ɗan annabi, amma ni makiyayi ne, kuma ina lura da itatuwan al’ul. ");
INSERT INTO hausa_vpl VALUES ("AM7_15","031_7_15","AMO","7","15","15","Amma Ubangiji ya ɗauke ni daga kiwon dabbobi ya ce mini, ‘Je ka, ka yi wa mutanena Isra’ila annabci.’ ");
INSERT INTO hausa_vpl VALUES ("AM7_16","031_7_16","AMO","7","16","16","Yanzu fa, sai ka ji maganar Ubangiji. Ka ce, “ ‘Kada in yi annabci a kan Isra’ila, kuma in daina yin wa’azi a kan gidan Ishaku.’ ");
INSERT INTO hausa_vpl VALUES ("AM7_17","031_7_17","AMO","7","17","17","“Saboda haka ga abin da Ubangiji ya ce, “ ‘Matarka za tă zama karuwa a cikin birni, kuma da takobi za a kashe ’ya’yanka maza da mata. Za a auna ƙasarka a kuma raba ta, kai kuma za ka mutu a ƙasar arna. Ba shakka Isra’ila za su tafi zaman bauta, nesa da ainihin ƙasarsu.’ ” ");
INSERT INTO hausa_vpl VALUES ("AM8_1","031_8_1","AMO","8","1","1","Ga abin da Ubangiji Mai Iko Duka ya nuna mini. Ubangiji ya nuna mini kwandon nunannun ’ya’yan itace. ");
INSERT INTO hausa_vpl VALUES ("AM8_2","031_8_2","AMO","8","2","2","Ya yi tambaya ya ce, “Me ka gani Amos?” Sai na amsa na ce, “Kwandon nunannun ’ya’yan itace.” Sai Ubangiji ya ce mini, “Lokaci ya yi wa mutanena Isra’ila da ba zan ƙara barinsu ba. ");
INSERT INTO hausa_vpl VALUES ("AM8_3","031_8_3","AMO","8","3","3","“A ranan nan,” in ji Ubangiji Mai Iko Duka, “Waƙoƙin a haikali za su koma makoki. Za a ga gawawwaki a ko’ina! Shiru!” ");
INSERT INTO hausa_vpl VALUES ("AM8_4","031_8_4","AMO","8","4","4","Ku ji wannan, ku da kuke tattake masu bukata kuka kori matalautan ƙasar. ");
INSERT INTO hausa_vpl VALUES ("AM8_5","031_8_5","AMO","8","5","5","Kuna cewa, “Yaushe Sabon Wata zai wuce don mu sayar da hatsi, Asabbaci ta wuce, don mu sayar da alkama?” Mu yi awo da ma’aunin zalunci mu ƙara kuɗin kaya mu kuma cutar da mai saya, ");
INSERT INTO hausa_vpl VALUES ("AM8_6","031_8_6","AMO","8","6","6","mu sayi matalauta da azurfa masu bukata kuma da takalmi, mu sayar da alkamar haɗe da yayi. ");
INSERT INTO hausa_vpl VALUES ("AM8_7","031_8_7","AMO","8","7","7","Ubangiji ya rantse da Girman Yaƙub, “Ba zan taɓa mantawa da duk wani abin da suka yi ba. ");
INSERT INTO hausa_vpl VALUES ("AM8_8","031_8_8","AMO","8","8","8","“Shin, ƙasar ba za tă yi rawan jiki saboda wannan ba, kuma duk masu zama a cikinta ba za su yi makoki ba? Ƙasar duka za tă hau ta sauka kamar Nilu; za a dama ta sa’an nan ta nutse kamar kogin Masar. ");
INSERT INTO hausa_vpl VALUES ("AM8_9","031_8_9","AMO","8","9","9","“A wannan rana,” in ji Ubangiji Mai Iko Duka, “Zan sa rana ta fāɗi da tsakar rana in kuma duhunta duniya da rana tsaka. ");
INSERT INTO hausa_vpl VALUES ("AM8_10","031_8_10","AMO","8","10","10","Zan mai da bukukkuwanku na addini su zama makoki kuma dukan waƙoƙinku su zama kuka. Zan sa dukanku ku sa rigunan makoki za ku kuma aske kawunanku. Zan sa wannan lokaci yă zama kamar lokacin da ake makokin ɗan tilon da ake da shi kuma ƙarshenta kamar rana mai ɗaci. ");
INSERT INTO hausa_vpl VALUES ("AM8_11","031_8_11","AMO","8","11","11","“Ranakun suna zuwa,” in ji Ubangiji Mai Iko Duka, “sa’ad da zan aika da yunwa cikin ƙasar, ba yunwar abinci ko ta ƙishirwa ba, sai dai yunwa ta jin maganar Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM8_12","031_8_12","AMO","8","12","12","Mutane za su yi ta tangaɗi daga teku zuwa teku suna yawo daga arewa zuwa kudu, suna neman maganar Ubangiji, amma ba za su samu ba. ");
INSERT INTO hausa_vpl VALUES ("AM8_13","031_8_13","AMO","8","13","13","“A wannan rana “kyawawan ’yan mata da kuma samari masu ji da ƙarfi za su suma don ƙishirwa. ");
INSERT INTO hausa_vpl VALUES ("AM8_14","031_8_14","AMO","8","14","14","Waɗanda suka yi rantsuwa da abin kunya na Samariya, ko kuma su ce, ‘Muddin allahnku yana a raye, ya Dan,’ ko kuwa, ‘Muddin allahn Beyersheba yana a raye,’ za su fāɗi, ba kuwa za su ƙara tashi ba.” ");
INSERT INTO hausa_vpl VALUES ("AM9_1","031_9_1","AMO","9","1","1","Na ga Ubangiji yana tsaye a gaban bagade, ya kuma ce, “Bugi kan ginshiƙan don madogaran ƙofa su girgiza. Saukar da su a kan dukan mutane; waɗanda ba su mutu ba zan kashe su da takobi. Ba mutum guda da zai tsere, babu wani da zai tsira. ");
INSERT INTO hausa_vpl VALUES ("AM9_2","031_9_2","AMO","9","2","2","Ko da sun tona rami kamar zurfin kabari, daga can hannuna zai fitar da su. Ko da sun hau can sama daga can zan sauko da su. ");
INSERT INTO hausa_vpl VALUES ("AM9_3","031_9_3","AMO","9","3","3","Ko da sun ɓuya a bisa Karmel, a can zan farauce su in cafko. Ko da sun ɓuya can ƙarƙashin teku, a can zan umarci maciji yă sare su. ");
INSERT INTO hausa_vpl VALUES ("AM9_4","031_9_4","AMO","9","4","4","Ko da abokan gābansu sun kore su zuwa zaman bauta, a can zan umarci takobi yă kashe su. “Zan sa musu ido don mugunta ba don alheri ba.” ");
INSERT INTO hausa_vpl VALUES ("AM9_5","031_9_5","AMO","9","5","5","Ubangiji, Ubangiji Maɗaukaki, shi da yakan taɓa ƙasa sai ta narke, kuma dukan mazauna cikinta suna makoki, ƙasar gaba ɗaya takan hau ta kuma sauka kamar Nilu, sa’an nan ta nutse kamar kogin Masar, ");
INSERT INTO hausa_vpl VALUES ("AM9_6","031_9_6","AMO","9","6","6","shi da ya gina kyakkyawar fadarsa a cikin sammai ya kuma kafa harsashenta a duniya, shi da yakan kira ruwan teku yă kuma kwarara su a bisa duniya, Ubangiji ne sunansa. ");
INSERT INTO hausa_vpl VALUES ("AM9_7","031_9_7","AMO","9","7","7","“Ku ba Isra’ilawa ba ne, daidai gare ni kamar yadda Kushawa suke?” In ji Ubangiji. “Ban fito da Isra’ila daga Masar ba, Filistiyawa kuma daga Kaftor Arameyawa kuma daga Kir ba? ");
INSERT INTO hausa_vpl VALUES ("AM9_8","031_9_8","AMO","9","8","8","“Tabbatacce idanun Ubangiji Mai Iko Duka suna a kan mulkin nan mai zunubi. Zan hallaka shi daga fuskar duniya, duk da haka ba zan hallaka gidan Yaƙub ƙaƙaf ba,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AM9_9","031_9_9","AMO","9","9","9","“Gama zan ba da umarni, zan kuma tankaɗe gidan Isra’ila a cikin dukan ƙasashe kamar yadda ake tankaɗe hatsi a cikin matankaɗi kuma ko ƙwaya ɗaya ba za tă fāɗi a ƙasa ba. ");
INSERT INTO hausa_vpl VALUES ("AM9_10","031_9_10","AMO","9","10","10","Dukan masu zunubi a cikin mutanena za su mutu ta wurin takobi, wato, su masu cewa, ‘Masifa ba za tă fāɗo ko ta same mu ba.’ ");
INSERT INTO hausa_vpl VALUES ("AM9_11","031_9_11","AMO","9","11","11","“A wannan rana zan maido da tentin Dawuda da ya fāɗi. Zan gyaggyara wuraren da suka yayyage, in kuma maido da kufansa in gina shi kamar yadda yake a dā, ");
INSERT INTO hausa_vpl VALUES ("AM9_12","031_9_12","AMO","9","12","12","domin su mallaki raguwar Edom da duk al’ummai da suke amsa sunana,” in ji Ubangiji shi wanda zai yi waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("AM9_13","031_9_13","AMO","9","13","13","“Ranaku suna zuwa, in ji Ubangiji, “sa’ad da mai huɗa zai sha gaban mai girbi mai shuki kuma yă bi bayan mai matsin inabi. Sabon ruwan inabi zai ɗiga daga duwatsu yă kuma kwararo daga tuddai. ");
INSERT INTO hausa_vpl VALUES ("AM9_14","031_9_14","AMO","9","14","14","Zan dawo da waɗanda aka kai zaman bauta mutanena Isra’ila. “Za su sāke gina biranen da suke kango su kuma zauna a cikinsu. Za su shuka gonakin inabi su kuma sha ruwan inabinsu; za su yi lambuna su kuma ci amfaninsu. ");
INSERT INTO hausa_vpl VALUES ("AM9_15","031_9_15","AMO","9","15","15","Zan dasa Isra’ila a ƙasarsu, ba kuwa za a ƙara tumɓuke su daga ƙasar da na ba su ba,” in ji Ubangiji Allahnku.");
INSERT INTO hausa_vpl VALUES ("OB1_1","032_1_1","OBA","1","1","1","Wahayin Obadiya. Ga abin da Ubangiji Mai Iko Duka ya ce a kan Edom. Mun ji saƙo daga wurin Ubangiji cewa, An aiki jakada zuwa ga al’ummai yă faɗa musu cewa, “Ku tashi, mu tafi mu yi yaƙi da ita.” ");
INSERT INTO hausa_vpl VALUES ("OB1_2","032_1_2","OBA","1","2","2","“Duba, zan maishe ki ƙarama a cikin al’ummai; za a rena ki ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("OB1_3","032_1_3","OBA","1","3","3","Fariyar zuciyarki ta yaudare ki, ke da kike zama can bisa duwatsu kika kuma yi gidanki a kan ƙwanƙoli, ke da kike ce wa kanki, ‘Wa zai iya saukar da ni ƙasa?’ ");
INSERT INTO hausa_vpl VALUES ("OB1_4","032_1_4","OBA","1","4","4","Ko da yake kina firiya kamar gaggafa kin kuma yi sheƙarki a can cikin taurari, daga can zan saukar da ke,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("OB1_5","032_1_5","OBA","1","5","5","“In ɓarayi suka zo miki, in kuma ’yan fashi suka shigo gidan da dare, kash, bala’i zai jira ki ba abin da suke so ne kawai za su sata ba? In kuma masu tsinka ’ya’yan inabi suka zo miki, ba sukan bar ’ya’yan inabi kaɗan ba? ");
INSERT INTO hausa_vpl VALUES ("OB1_6","032_1_6","OBA","1","6","6","Amma za a washe Isuwa ƙaƙaf, a kuma yaye ɓoyayyiyar dukiyarsa! ");
INSERT INTO hausa_vpl VALUES ("OB1_7","032_1_7","OBA","1","7","7","Dukan waɗanda kike tarayya da su, za su kore ki zuwa iyaka; abokanki kuma za su yaudare ki, su kuma sha ƙarfinki; waɗanda suke cin abincinki, za su sa miki tarko, amma ba za ki gane ba. ");
INSERT INTO hausa_vpl VALUES ("OB1_8","032_1_8","OBA","1","8","8","“A wannan rana,” in jin Ubangiji, “zan hallaka masu hikimar Edom, zan shafe mutane masu fahima a duwatsun Isuwa. ");
INSERT INTO hausa_vpl VALUES ("OB1_9","032_1_9","OBA","1","9","9","Jarumawanki, ya Teman, za su razana, za a kashe kowane mutum a duwatsun Isuwa. ");
INSERT INTO hausa_vpl VALUES ("OB1_10","032_1_10","OBA","1","10","10","Saboda halin kama-karyar da kika yi wa ɗan’uwanka Yaƙub, za ki sha kunya; za a hallaka ki har abada. ");
INSERT INTO hausa_vpl VALUES ("OB1_11","032_1_11","OBA","1","11","11","A ranan nan kin tsaya kawai kina zuba ido yayinda baƙi suke washe dukiyar ɗan’uwanki, baƙi kuma suka shiga ta ƙofofinsa suka jefa ƙuri’a don a rarraba Urushalima, kin tsaya kina kallo kamar ɗaya daga cikin abokan gābansa. ");
INSERT INTO hausa_vpl VALUES ("OB1_12","032_1_12","OBA","1","12","12","Bai kamata ki rena ɗan’uwanki a ranar masifarsa ba, ko ki yi farin ciki a kan mutanen Yahuda a ranar hallakarsu, ko ki yi fariya sosai a ranar wahalarsu. ");
INSERT INTO hausa_vpl VALUES ("OB1_13","032_1_13","OBA","1","13","13","Bai kamata ki bi ta ƙofofin mutanena a ranar bala’insu ba, ko ki rena su a cikin masifarsu a ranar bala’insu, ko ki ƙwace dukiyarsu a ranar bala’insu ba. ");
INSERT INTO hausa_vpl VALUES ("OB1_14","032_1_14","OBA","1","14","14","Bai kamata ki tsaya a mararraba don ki kashe waɗanda suke ƙoƙarin tserewa ba, ko ki ba da waɗanda suka tsere ga hannun maƙiyansu a ranar wahalarsu ba. ");
INSERT INTO hausa_vpl VALUES ("OB1_15","032_1_15","OBA","1","15","15","“Ranar Ubangiji ta yi kusa don dukan al’ummai. Kamar yadda kuka yi, haka za a yi muku; ayyukanku za su koma a kanku. ");
INSERT INTO hausa_vpl VALUES ("OB1_16","032_1_16","OBA","1","16","16","Kamar yadda kuka sha a kan tuduna mai tsarki, haka dukan al’ummai za su yi ta sha, za su sha, su kuma sha su zama sai ka ce ba su taɓa kasancewa ba. ");
INSERT INTO hausa_vpl VALUES ("OB1_17","032_1_17","OBA","1","17","17","Amma a kan Dutsen Sihiyona za a sami ceto; Dutsen zai zama mai tsarki, gidan Yaƙub kuma zai mallaki gādonsa. ");
INSERT INTO hausa_vpl VALUES ("OB1_18","032_1_18","OBA","1","18","18","Gidan Yaƙub zai zama kamar wuta, gidan Yusuf kuma kamar harshen wuta; gidan Isuwa zai zama kamar tattaka, za a kuma sa masa wuta yă ƙone. Babu wanda zai tsira daga gidan Isuwa.” Ni Ubangiji na faɗa. ");
INSERT INTO hausa_vpl VALUES ("OB1_19","032_1_19","OBA","1","19","19","Mutane daga Negeb za su mamaye duwatsun Isuwa, mutane kuma daga gindin tuddai za su mallaki ƙasar Filistiyawa. Za su mamaye filayen Efraim da Samariya, Benyamin kuwa zai mallaki Gileyad. ");
INSERT INTO hausa_vpl VALUES ("OB1_20","032_1_20","OBA","1","20","20","Wannan ƙungiyar Isra’ilawan da aka kwashe zuwa bauta da suke a Kan’ana za su mallaki ƙasar har zuwa Zarefat; waɗannan da aka kwashe zuwa bauta daga Urushalima da suke a Sefarad za su mallaki garuruwan Negeb. ");
INSERT INTO hausa_vpl VALUES ("OB1_21","032_1_21","OBA","1","21","21","Masu kawo ceto za su haura zuwa Dutsen Sihiyona don su yi mulkin duwatsun Isuwa. Ubangiji ne zai yi mulki.");
INSERT INTO hausa_vpl VALUES ("JH1_1","033_1_1","JON","1","1","1","Maganar Ubangiji ta zo wa Yunana ɗan Amittai cewa, ");
INSERT INTO hausa_vpl VALUES ("JH1_2","033_1_2","JON","1","2","2","“Tafi babban birnin nan Ninebe ka yi mata wa’azi, saboda muguntarta ta haura zuwa gabana.” ");
INSERT INTO hausa_vpl VALUES ("JH1_3","033_1_3","JON","1","3","3","Amma Yunana ya gudu daga Ubangiji ya nufi Tarshish. Ya gangara zuwa Yaffa, inda ya sami jirgin ruwa mai shirin tashi daga tashar. Bayan ya biya kuɗin tafiya, sai ya shiga jirgi ya kama hanya zuwa Tarshish don yă tsere wa Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JH1_4","033_1_4","JON","1","4","4","Sai Ubangiji ya aika da babban iska a bisan teku, hadiri ya tsananta ƙwarai har jirgin ya yi barazanar farfashewa. ");
INSERT INTO hausa_vpl VALUES ("JH1_5","033_1_5","JON","1","5","5","Dukan matuƙan jirgin suka tsorata, kowannensu kuma ya yi kuka ga allahnsa, suka kuma jefar da kayan jirgi a cikin teku domin su rage nauyin jirgin. Ana cikin haka, ashe, Yunana ya sauka can ƙarƙashin jirgi ya je ya kwanta, yana ta sharar barcinsa. ");
INSERT INTO hausa_vpl VALUES ("JH1_6","033_1_6","JON","1","6","6","Sai kyaftin ɗin ya je wajensa ya ce masa, “Don me kake barci? Tashi ka kira bisa ga allahnka! Mai yiwuwa yă ji mu, yă cece mu don kada mu hallaka.” ");
INSERT INTO hausa_vpl VALUES ("JH1_7","033_1_7","JON","1","7","7","Matuƙan jirgin suka ce wa juna, “Ku zo, mu jefa ƙuri’a mu ga wa ke da alhakin wannan masifa.” Sai suka jefa ƙuri’a, ƙuri’ar kuwa ta fāɗa a kan Yunana. ");
INSERT INTO hausa_vpl VALUES ("JH1_8","033_1_8","JON","1","8","8","Saboda haka suka tambaye shi suka ce, “Yanzu, gaya mana, dalilin da ya sa wannan masifa ta zo mana? Mene ne aikinka? Daga ina ka fito? Ina ne ƙasarka? Daga wacce kabila ce ka fito?” ");
INSERT INTO hausa_vpl VALUES ("JH1_9","033_1_9","JON","1","9","9","Sai ya amsa, “Ni mutumin Ibraniyawa ne, ina kuma bauta wa Ubangiji Allah na sama, wanda ya yi teku da tuddai.” ");
INSERT INTO hausa_vpl VALUES ("JH1_10","033_1_10","JON","1","10","10","Sai matuƙan jirgin suka tsorata ƙwarai, suka ce masa, “Wane irin mugun abu ne ka aikata haka?” (Sun gane cewa yana gudu ne daga wurin Ubangiji, domin ya riga ya faɗa musu.) ");
INSERT INTO hausa_vpl VALUES ("JH1_11","033_1_11","JON","1","11","11","Sai tekun ya daɗa rikicewa. Sai suka tambaye shi, “Me za mu yi da kai domin tekun yă daina hauka?” ");
INSERT INTO hausa_vpl VALUES ("JH1_12","033_1_12","JON","1","12","12","Ya amsa musu ya ce, “Ku ɗauke ni ku jefa a cikin teku, tekun zai kwanta. Na san cewa laifina ne ya jawo wannan babban hadirin da ya auka muku.” ");
INSERT INTO hausa_vpl VALUES ("JH1_13","033_1_13","JON","1","13","13","Maimakon mutanen su yi haka, sai suka yi ƙoƙari su tura jirgin ruwan zuwa bakin teku. Amma ba su iya ba, saboda iskar ta sa tekun ya yi ta ƙara hauka. ");
INSERT INTO hausa_vpl VALUES ("JH1_14","033_1_14","JON","1","14","14","Sai suka yi kuka ga Ubangiji suka ce, “Ya Ubangiji, in ka yarda kada ka bar mu mu mutu saboda ran mutumin nan. Kada ka yi mana hukuncin masu kisankai, gama kai ne, ya Ubangiji, ka ga ya gamshe ka.” ");
INSERT INTO hausa_vpl VALUES ("JH1_15","033_1_15","JON","1","15","15","Sa’an nan suka ɗauki Yunana suka jefar da shi daga jirgin, sai tekun ya kwanta. ");
INSERT INTO hausa_vpl VALUES ("JH1_16","033_1_16","JON","1","16","16","Ganin haka sai mutanen suka cika da tsoron Ubangiji, suka kuma miƙa wa Ubangiji hadaya, suka yi wa’adi da shi. ");
INSERT INTO hausa_vpl VALUES ("JH1_17","033_1_17","JON","1","17","17","Amma Ubangiji ya tanada wani babban kifi da zai haɗiye Yunana, Yunana kuwa ya yi yini uku da dare uku a ciki cikin kifin. ");
INSERT INTO hausa_vpl VALUES ("JH2_1","033_2_1","JON","2","1","1","Daga ciki cikin kifi, Yunana ya yi addu’a ga Ubangiji Allahnsa. ");
INSERT INTO hausa_vpl VALUES ("JH2_2","033_2_2","JON","2","2","2","Ya ce, “A cikin damuwata na yi kira ga Ubangiji, ya kuwa amsa mini. Daga cikin zurfi kabari na yi kiran neman taimako, ka kuwa saurari kukata. ");
INSERT INTO hausa_vpl VALUES ("JH2_3","033_2_3","JON","2","3","3","Cikin tashin hankali, ka jefa ni cikin zurfafa, a tsakiyar teku, ka kuma jujjuya ni a cikin ruwa; dukan raƙuman ruwanka da ambaliyarka sun bi ta kaina. ");
INSERT INTO hausa_vpl VALUES ("JH2_4","033_2_4","JON","2","4","4","Sai na ce, ‘An kore ni daga fuskarka; duk da haka zan sāke duba wajen haikalinka mai tsarki.’ ");
INSERT INTO hausa_vpl VALUES ("JH2_5","033_2_5","JON","2","5","5","Ruwayen da suke kewaye da ni sun yi mini barazana, zurfi kuma ya kewaye ni, ciyayin ruwa suna nannaɗe kewaye da ni. ");
INSERT INTO hausa_vpl VALUES ("JH2_6","033_2_6","JON","2","6","6","Na nutsa har ƙarƙashin tuddai; a ƙarƙashin duniya, ka rufe ni har abada. Amma ka dawo da raina daga rami, Ya Ubangiji Allahna. ");
INSERT INTO hausa_vpl VALUES ("JH2_7","033_2_7","JON","2","7","7","“Sa’ad da na ji raina yana rabuwa da ni, na tuna da kai ya Ubangiji, addu’ata kuma ta kai gare ka, a haikalinka mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("JH2_8","033_2_8","JON","2","8","8","“Waɗanda suka maƙale wa gumaka marasa amfani, sukan ƙyale alherin da zai kasance nasu. ");
INSERT INTO hausa_vpl VALUES ("JH2_9","033_2_9","JON","2","9","9","Amma ni, da waƙar godiya, zan miƙa tawa hadaya gare ka. Abin da na yi alkawari, shi ne zan yi. Ceto yakan zo ne kawai daga wurin Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("JH2_10","033_2_10","JON","2","10","10","Sai Ubangiji ya umarci kifin, kifin kuwa ya amayar da Yunana a gaɓan teku. ");
INSERT INTO hausa_vpl VALUES ("JH3_1","033_3_1","JON","3","1","1","Sa’an nan sai maganar Ubangiji ta zo wa Yunana sau na biyu. ");
INSERT INTO hausa_vpl VALUES ("JH3_2","033_3_2","JON","3","2","2","“Tafi babban birnin nan Ninebe, ka yi masa shelar saƙon da na ba ka.” ");
INSERT INTO hausa_vpl VALUES ("JH3_3","033_3_3","JON","3","3","3","Sai Yunana ya yi biyayya da maganar Ubangiji, ya tafi Ninebe. Ninebe birni ne da yake da muhimmanci, wanda sai an ɗauki kwana uku kafin a iya zaga shi. ");
INSERT INTO hausa_vpl VALUES ("JH3_4","033_3_4","JON","3","4","4","A rana ta fari, Yunana ya kama tafiya yana ratsa birnin. Sai ya yi shela cewa, “Nan da kwana arba’in za a hallaka Ninebe?” ");
INSERT INTO hausa_vpl VALUES ("JH3_5","033_3_5","JON","3","5","5","Mutanen Ninebe kuwa suka gaskata Allah. Aka yi shela a yi azumi, sai dukansu daga babba har zuwa ƙaraminsu, suka sa tufafin makoki. ");
INSERT INTO hausa_vpl VALUES ("JH3_6","033_3_6","JON","3","6","6","Da saƙon Yunana ya kai kunnen sarkin Ninebe, sai ya tashi daga kujerar mulkinsa, ya tuɓe alkyabbarsa, ya sa rigar makoki, ya zauna cikin toka. ");
INSERT INTO hausa_vpl VALUES ("JH3_7","033_3_7","JON","3","7","7","Sai ya yi umarni a Ninebe cewa, “Bisa ga umarnin sarki da fadawansa. “Kada a bar wani mutum ko dabba, garke ko shannu, su ɗanɗana wani abu; kada a bari su ci ko su sha. ");
INSERT INTO hausa_vpl VALUES ("JH3_8","033_3_8","JON","3","8","8","Bari kowane mutum da dabba yă yafa rigunan makoki. Kowa yă roƙi Allah da gaske, kowa kuma yă bar mugayen ayyukan da yake yi. ");
INSERT INTO hausa_vpl VALUES ("JH3_9","033_3_9","JON","3","9","9","Wa ya sani? Ko Allah zai ji tausayinmu da kuma juyayinmu yă janye zafin fushinsa don kada mu hallaka.” ");
INSERT INTO hausa_vpl VALUES ("JH3_10","033_3_10","JON","3","10","10","Da Allah ya ga abin da suka yi, da kuma yadda suka juya daga mugayen hanyoyinsu sai ya ji tausayinsu, bai kawo hallaka a kansu yadda ya yi shirin yi ba. ");
INSERT INTO hausa_vpl VALUES ("JH4_1","033_4_1","JON","4","1","1","Sai abin ya ɓata wa Yunana rai ƙwarai har ya yi fushi. ");
INSERT INTO hausa_vpl VALUES ("JH4_2","033_4_2","JON","4","2","2","Sai ya yi addu’a ga Ubangiji ya ce, “Ya Ubangiji, ba irin abin da na faɗa ke nan ba tun ina gida? Wannan ne ya sa na yi ƙoƙarin tserewa zuwa Tarshish. Ai, na sani kai Allah ne mai alheri da tausayi, mai jinkirin fushi da cikakkiyar ƙauna, kai Allah ne mai dakatar da nufinka na yin hukunci. ");
INSERT INTO hausa_vpl VALUES ("JH4_3","033_4_3","JON","4","3","3","Yanzu, ya Ubangiji, ka ɗauki raina, domin ya fi sauƙi a gare ni in mutu da in rayu.” ");
INSERT INTO hausa_vpl VALUES ("JH4_4","033_4_4","JON","4","4","4","Amma Ubangiji ya amsa, ya ce; “Daidai ne ka yi fushi?” ");
INSERT INTO hausa_vpl VALUES ("JH4_5","033_4_5","JON","4","5","5","Sai Yunana ya fita daga birnin ya yi wajen gabas, ya zauna. A nan ya yi wa kansa rumfa, ya zauna cikin inuwarta yana jira yă ga abin da zai sami birnin. ");
INSERT INTO hausa_vpl VALUES ("JH4_6","033_4_6","JON","4","6","6","Sai Ubangiji Allah ya sa wata ’yar kuringa ta tsiro, ta yi girma a inda Yunana yake, don ta inuwantar da shi, yă ji daɗi. Yunana kuwa ya yi murna matuƙa da wannan kuringa. ");
INSERT INTO hausa_vpl VALUES ("JH4_7","033_4_7","JON","4","7","7","Amma kashegari da safe sai Allah ya sa tsutsa ta cinye ’yar kuringar har ta mutu. ");
INSERT INTO hausa_vpl VALUES ("JH4_8","033_4_8","JON","4","8","8","Sa’ad da rana ta yi sama, sai Allah ya sa iskar gabas mai zafi ta huro, zafin ranar kuma ya buga kan Yunana, har ya ji sai ka ce zai suma. Ya so a ce ya mutu ma, sai ya ce, “Gara in mutu da a ce ina zaune da rai.” ");
INSERT INTO hausa_vpl VALUES ("JH4_9","033_4_9","JON","4","9","9","Amma Allah ya ce wa Yunana, “Daidai ne ka yi fushi saboda wannan kuringa?” Sai Yunana ya ce, “I, daidai ne, ina fushi matuƙa, har ina so da na mutu ma.” ");
INSERT INTO hausa_vpl VALUES ("JH4_10","033_4_10","JON","4","10","10","Sai Ubangiji ya ce, “Ai, wannan kuringa ta tsira dare ɗaya ta kuma ɓace kafin dare na biyu, ba ka yi wata wahala dominta ba, ba kai ne ka sa ta yi girma ba, duk da haka ranka ya ɓace saboda ita. ");
INSERT INTO hausa_vpl VALUES ("JH4_11","033_4_11","JON","4","11","11","Ashe, ba dole ne in ji tausayin babban birnin nan Ninebe mai mutum sama da dubu ɗari da ashirin (120,000) marasa alhaki, da kuma dabbobi masu yawa ba?”");
INSERT INTO hausa_vpl VALUES ("MC1_1","034_1_1","MIC","1","1","1","Maganar Ubangiji ta zo wa Mika mutumin Moreshet a zamanin Yotam, da na Ahaz, da kuma na Hezekiya, sarakunan Yahuda, Mika ya ga wahayi a kan Samariya da kuma a kan Urushalima. Ga abin da ya ce. ");
INSERT INTO hausa_vpl VALUES ("MC1_2","034_1_2","MIC","1","2","2","Ku ji, ya ku mutane duka, ki saurara, ya ke duniya da dukan mazauna cikinki, bari Ubangiji Mai Iko Duka yă zama shaida a kanku, daga haikalinsa mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("MC1_3","034_1_3","MIC","1","3","3","Duba! Ubangiji yana zuwa daga wurin zamansa; zai sauko yă taka maɗaukakan wuraren duniya. ");
INSERT INTO hausa_vpl VALUES ("MC1_4","034_1_4","MIC","1","4","4","Duwatsu za su narke a ƙarƙashin ƙafafunsa, kamar kaki a gaban wuta, kwaruruka kuma za su ɓace, kamar ruwan da yake gangarowa daga tsauni. ");
INSERT INTO hausa_vpl VALUES ("MC1_5","034_1_5","MIC","1","5","5","Duk wannan zai faru saboda laifin Yaƙub, da kuma zunuban gidan Isra’ila ne. Mene ne laifin Yaƙub? Shin, ba Samariya ba ce? Ina ne maɗaukakan wuraren Yahuda? Shin, ba Urushalima ba ce? ");
INSERT INTO hausa_vpl VALUES ("MC1_6","034_1_6","MIC","1","6","6","“Saboda haka zan mai da Samariya tarin juji, wurin noman inabi. Zan zubar da duwatsunta a cikin kwari in kuma bar harsashin gininta a bayyane. ");
INSERT INTO hausa_vpl VALUES ("MC1_7","034_1_7","MIC","1","7","7","Za a ragargaje dukan allolinta; za a ƙone dukan baye-bayenta na haikali da wuta; zan lalatar da dukan gumakanta. Tun da ta wurin karuwanci ne ta tattara su, ga karuwanci kuma za su koma.” ");
INSERT INTO hausa_vpl VALUES ("MC1_8","034_1_8","MIC","1","8","8","Saboda wannan zan yi baƙin ciki, in yi kuka; zan yi tafiya ba takalmi, zan tuɓe, in kuma yi tafiya tsirara. Zan yi kuka kamar dila, in yi baƙin ciki kamar mujiya. ");
INSERT INTO hausa_vpl VALUES ("MC1_9","034_1_9","MIC","1","9","9","Gama raunin Samariya ba mai warkewa ba ne; ya bazu har Yahuda. Ya ma kai bakin ƙofar mutanena, har ma Urushalima da kanta. ");
INSERT INTO hausa_vpl VALUES ("MC1_10","034_1_10","MIC","1","10","10","Kada a faɗe shi a Gat; kada ma a yi kuka. A maimako haka, a yi birgima a cikin ƙura a Bet-Leyafra. ");
INSERT INTO hausa_vpl VALUES ("MC1_11","034_1_11","MIC","1","11","11","Ku wuce tsirara da kuma kunya, ku mazaunan Shafir. Bet-Ezel tana makoki domin babu wani daga Za’anan da ya fito don yă taimaka. ");
INSERT INTO hausa_vpl VALUES ("MC1_12","034_1_12","MIC","1","12","12","Mazaunan Marot sun ƙosa su ga alheri, amma Ubangiji ya sauko da azaba, har zuwa ƙofar Urushalima. ");
INSERT INTO hausa_vpl VALUES ("MC1_13","034_1_13","MIC","1","13","13","Ku da kuke zama a Lakish, ku ɗaura wa dawakai kekunan yaƙi. Gama ku kuka fara yin zunubi a Sihiyona, gama an sami laifofin Isra’ila a cikinku. ");
INSERT INTO hausa_vpl VALUES ("MC1_14","034_1_14","MIC","1","14","14","Saboda haka za ku ba da kyautan bankwana ga Moreshet Gat. Garin Akzib zai zama abin yaudara ga sarakunan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("MC1_15","034_1_15","MIC","1","15","15","Ku mazaunan Maresha Ubangiji zai kawo wanda zai ci ku da yaƙi. Sarakunan Isra’ila za su gudu zuwa Adullam. ");
INSERT INTO hausa_vpl VALUES ("MC1_16","034_1_16","MIC","1","16","16","Ku aske kanku ƙwal don makoki, ku yi wa kanku ƙwalƙwal kamar ungulu. Gama za a ja ’ya’yan da kuke farin ciki a kai su bauta. ");
INSERT INTO hausa_vpl VALUES ("MC2_1","034_2_1","MIC","2","1","1","Taku ta ƙare, ku da kuke shirya makirci, ku da kuke ƙulle-ƙullen mugunta a kan gadonku! Da gari ya waye sai ku fita ku aikata mugunta domin ikon aikatawa yana hannunku. ");
INSERT INTO hausa_vpl VALUES ("MC2_2","034_2_2","MIC","2","2","2","Kukan yi ƙyashin gonaki ku kuma ƙwace su, ku yi ƙyashin gidaje ku kuma ƙwace. Kukan zalunci mutum, ku ƙwace masa gidansa, har ku ƙwace masa gādonsa. ");
INSERT INTO hausa_vpl VALUES ("MC2_3","034_2_3","MIC","2","3","3","Saboda haka, Ubangiji ya ce, “Ina shirya wa waɗannan mutane bala’i, yadda ba za ku iya ceton kanku ba. Ba za ku ƙara tafiya kuna taƙama ba, gama zai zama lokacin bala’i ne. ");
INSERT INTO hausa_vpl VALUES ("MC2_4","034_2_4","MIC","2","4","4","A wannan rana mutane za su yi muku ba’a za su yi muku gwalo da wannan waƙar makoki, ‘An lalatar da mu sarai; an rarraba mallakar mutanena. Ya ɗauke shi daga gare ni! Ya miƙa filayenmu ga maciyan amanarmu.’ ” ");
INSERT INTO hausa_vpl VALUES ("MC2_5","034_2_5","MIC","2","5","5","Saboda haka ba za ku kasance da wani a taron jama’ar Ubangiji da zai raba ƙasar ta wurin jefa ƙuri’a ba. ");
INSERT INTO hausa_vpl VALUES ("MC2_6","034_2_6","MIC","2","6","6","“Kada ku yi annabci” in ji annabawansu. “Kada ku yi annabci game da waɗannan abubuwa; abin kunya ba zai same mu ba.” ");
INSERT INTO hausa_vpl VALUES ("MC2_7","034_2_7","MIC","2","7","7","Daidai ne a ce, ya gidan Yaƙub, “Ruhun Ubangiji yana fushi ne? Yana yin irin waɗannan abubuwa?” “Ashe, maganata ba tă amfane wanda ayyukansa suke daidai ba? ");
INSERT INTO hausa_vpl VALUES ("MC2_8","034_2_8","MIC","2","8","8","Ba da daɗewa ba mutanena sun tashi kamar magabci. Kun tuɓe riga mai tsada daga waɗanda suke wucewa ba tare da kun damu ba, sai ka ce mutanen da suke komowa daga yaƙi. ");
INSERT INTO hausa_vpl VALUES ("MC2_9","034_2_9","MIC","2","9","9","Kun kori matan mutanena daga gidajensu masu daɗi. Kuka kawar da albarkata har abada daga wurin ’ya’yansu. ");
INSERT INTO hausa_vpl VALUES ("MC2_10","034_2_10","MIC","2","10","10","Ku tafi, ku ba ni wuri! Gama wannan ba wurin hutunku ba ne, gama ya ƙazantu, ya zama kangon da ya wuce gyara. ");
INSERT INTO hausa_vpl VALUES ("MC2_11","034_2_11","MIC","2","11","11","In maƙaryaci da mazambaci ya zo ya ce, ‘Zan yi muku annabci ku sami wadataccen ruwan inabi da barasa,’ zai dai zama annabin da ya dace da wannan mutane ne! ");
INSERT INTO hausa_vpl VALUES ("MC2_12","034_2_12","MIC","2","12","12","“Tabbatacce zan tattara ku duka, ya gidan Yaƙub; zan tattara ku raguwar Isra’ila. Zan kawo su wuri ɗaya kamar tumaki a cikin garke, kamar garke a wajen kiwonsa; wurin zai cika da mutane. ");
INSERT INTO hausa_vpl VALUES ("MC2_13","034_2_13","MIC","2","13","13","Wanda ya fasa ƙofa ya buɗe, shi zai haura yă yi musu jagora, za su fashe bangon su fita. Sarkinsu zai wuce gabansu, Ubangiji kuma zai kasance a gaba.” ");
INSERT INTO hausa_vpl VALUES ("MC3_1","034_3_1","MIC","3","1","1","Sa’an nan na ce, “Ku kasa kunne, ku shugabannin Yaƙub, ku masu mulkin gidan Isra’ila. Ya kamata ku san shari’a, ");
INSERT INTO hausa_vpl VALUES ("MC3_2","034_3_2","MIC","3","2","2","ku da kuke ƙin abu mai kyau kuke ƙaunar mugunta, ku da kuke feɗe mutanena kuke tuge nama daga ƙasusuwansu; ");
INSERT INTO hausa_vpl VALUES ("MC3_3","034_3_3","MIC","3","3","3","ku da kuke cin naman mutanena, ku feɗe fatar jikinsu kuke kakkarya ƙasusuwansu, kuke yayyanka su gunduwa-gunduwa kamar naman da za a toya, kamar naman da za a sa a dafa.” ");
INSERT INTO hausa_vpl VALUES ("MC3_4","034_3_4","MIC","3","4","4","Sa’an nan za su kira ga Ubangiji, amma ba zai amsa musu ba. A wannan lokaci zai ɓoye fuskarsa daga gare su saboda irin muguntar da suka yi. ");
INSERT INTO hausa_vpl VALUES ("MC3_5","034_3_5","MIC","3","5","5","Ga abin da Ubangiji ya faɗa, “Game da annabawa masu ɓad da mutanena, in wani ya ciyar da su, sai su ce akwai ‘salama’ amma in bai ciyar da su ba, a shirye suke su kai masa hari. ");
INSERT INTO hausa_vpl VALUES ("MC3_6","034_3_6","MIC","3","6","6","Saboda haka dare yana zuwa a bisanku, ba tare da wahayi ba, kuma duhu, ba tare da duba ba. Rana za tă fāɗi wa annabawa, yini kuma zai zama musu duhu. ");
INSERT INTO hausa_vpl VALUES ("MC3_7","034_3_7","MIC","3","7","7","Masu gani za su ji kunya, masu duba kuma za su ji taƙaici. Dukansu za su rufe fuskokinsu gama ba amsa daga Allah.” ");
INSERT INTO hausa_vpl VALUES ("MC3_8","034_3_8","MIC","3","8","8","Amma game da ni, ina cike da iko ta wurin Ruhun Ubangiji da kuma adalci da ƙarfi, don a sanar da Yaƙub laifofinsa, ga Isra’ila kuma zunubinsa. ");
INSERT INTO hausa_vpl VALUES ("MC3_9","034_3_9","MIC","3","9","9","Ku ji wannan, ku shugabannin gidan Yaƙub, ku masu mulkin gidan Isra’ila, ku da kuke ƙyamar gaskiya, kuka karkatar duk abin da yake na gaskiya; ");
INSERT INTO hausa_vpl VALUES ("MC3_10","034_3_10","MIC","3","10","10","kuka gina Sihiyona ta wurin zub da jini, Urushalima kuma ta wurin mugunta. ");
INSERT INTO hausa_vpl VALUES ("MC3_11","034_3_11","MIC","3","11","11","Hukunce-hukuncen shugabannin ƙasar na cin hanci ne, firistocinta kuma suna koyarwa don a biya su, annabawanta kuwa suna yin annabci don neman kuɗi. Duk da haka suna jingina a kan Ubangiji suna cewa, “Ba Ubangiji yana tare da mu ba? Ba bala’in da zai zo mana.” ");
INSERT INTO hausa_vpl VALUES ("MC3_12","034_3_12","MIC","3","12","12","Don haka, saboda ku, za a nome Sihiyona kamar gona, Urushalima kuma ta zama tarin juji, tudun haikali kuwa zai zama kurmin ƙayayyuwa. ");
INSERT INTO hausa_vpl VALUES ("MC4_1","034_4_1","MIC","4","1","1","A kwanakin ƙarshe za a kafa dutsen haikalin Ubangiji yă zama babba a cikin duwatsu. Za a ɗaga shi sama da tuddai, mutane kuma za su riƙa ɗunguma zuwa gare shi. ");
INSERT INTO hausa_vpl VALUES ("MC4_2","034_4_2","MIC","4","2","2","Al’ummai da yawa za su zo su ce, “Ku zo, bari mu haura zuwa dutsen Ubangiji, zuwa gidan Allah na Yaƙub. Zai koya mana hanyoyinsa, don mu yi tafiya cikin hanyoyinsa.” Doka za tă fita daga Sihiyona, maganar Ubangiji kuma daga Urushalima. ");
INSERT INTO hausa_vpl VALUES ("MC4_3","034_4_3","MIC","4","3","3","Zai shari’anta tsakanin mutane yă kuma sulhunta tsakanin manyan al’ummai nesa da kuma kusa. Har su mai da takubansu su zama garemani, māsunsu kuma su zama wuƙaƙen askin itace. Al’umma ba za tă ɗauki takobi gāba da wata al’umma ba, ko a yi horarwa don yaƙi. ");
INSERT INTO hausa_vpl VALUES ("MC4_4","034_4_4","MIC","4","4","4","Kowa zai zauna a tushen kuringar inabinsa da tushen ɓaurensa, kuma ba wanda zai tsoratar da su, gama Ubangiji Maɗaukaki ne ya faɗa. ");
INSERT INTO hausa_vpl VALUES ("MC4_5","034_4_5","MIC","4","5","5","Dukan al’ummai za su iya tafiya a cikin sunan allolinsu; mu dai za mu yi tafiya a cikin sunan Ubangiji Allahnmu har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("MC4_6","034_4_6","MIC","4","6","6","“A wannan rana,” in ji Ubangiji, “zan tattara guragu; zan kuma tara masu zaman bauta, da waɗanda na sa suka damu. ");
INSERT INTO hausa_vpl VALUES ("MC4_7","034_4_7","MIC","4","7","7","Zan mai da guragu su zama raguwa, waɗanda aka kora, su zama al’umma mai ƙarfi. Ubangiji zai yi mulkinsu a Dutsen Sihiyona daga wannan rana da kuma har abada. ");
INSERT INTO hausa_vpl VALUES ("MC4_8","034_4_8","MIC","4","8","8","Game da ke, ya hasumiyar tsaron garke, Ya mafaka Diyar Sihiyona, za a maido miki da mulkinki na dā, sarauta kuma za tă zo wa Diyar Urushalima.” ");
INSERT INTO hausa_vpl VALUES ("MC4_9","034_4_9","MIC","4","9","9","Don me yanzu kike kuka da ƙarfi, ba ki da sarki ne? Masu shawararki sun hallaka ne, da zafi ya cika ki kamar mace mai naƙuda? ");
INSERT INTO hausa_vpl VALUES ("MC4_10","034_4_10","MIC","4","10","10","Ki yi birgima cikin zafin azaba, ya Diyar Sihiyona, kamar macen da take naƙuda, don yanzu dole ki bar birni ki kafa sansani a filin Allah. Za ki tafi Babilon; a can za a kuɓutar da ki. A can ne Ubangiji zai fanshe ki daga hannun maƙiyanki. ");
INSERT INTO hausa_vpl VALUES ("MC4_11","034_4_11","MIC","4","11","11","Amma yanzu al’ummai da yawa suna gāba da ke. Suna cewa, “Bari a ƙazantar da ita, bari mu zuba wa Sihiyona ido.” ");
INSERT INTO hausa_vpl VALUES ("MC4_12","034_4_12","MIC","4","12","12","Amma ba su san tunanin Ubangiji ba; ba su fahimci shirinsa ba, shi da ya tattara su kamar dammuna a masussuka. ");
INSERT INTO hausa_vpl VALUES ("MC4_13","034_4_13","MIC","4","13","13","“Ki tashi ki yi sussuka, ya Diyar Sihiyona, gama zan ba ki ƙahonin ƙarfe; zan ba ki kofatan tagulla domin ki ragargaje al’ummai masu yawa.” Za ki ba Ubangiji dukan dukiyarsu da suka tara ta hanyar zamba, wadatarsu kuma ga Ubangiji dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("MC5_1","034_5_1","MIC","5","1","1","Ki tattara sojojinki, ya ke birnin mayaƙa, gama an kewaye mu da yaƙi. Za su bugi kumatun mai mulkin Isra’ila da sandar ƙarfe. ");
INSERT INTO hausa_vpl VALUES ("MC5_2","034_5_2","MIC","5","2","2","“Amma ke, Betlehem ta Efrata, ko da yake ke ƙarama ce daga cikin zuriyarki a Yahuda, daga cikinki wani zai zo domina wanda zai yi mulkin Isra’ila, wanda asalinsa tun fil azal ne.” ");
INSERT INTO hausa_vpl VALUES ("MC5_3","034_5_3","MIC","5","3","3","Saboda haka za a yashe Isra’ila har sai wadda take naƙuda ta haihu sauran ’yan’uwansa kuma sun dawo su haɗu da Isra’ilawa. ");
INSERT INTO hausa_vpl VALUES ("MC5_4","034_5_4","MIC","5","4","4","Zai tsaya yă yi kiwon garkensa da ƙarfin Ubangiji, cikin girman sunan Ubangiji Allahnsa. Za su kuma zauna lafiya, gama girmansa za tă kai har ƙarshen duniya. ");
INSERT INTO hausa_vpl VALUES ("MC5_5","034_5_5","MIC","5","5","5","Zai kuma zama salamarsu. Sa’ad da Assuriyawa suka kawo wa ƙasarmu hari suka tattake kagarunmu, za mu tā da makiyaya bakwai, har ma shugabannin mutane takwas su yi gāba da su. ");
INSERT INTO hausa_vpl VALUES ("MC5_6","034_5_6","MIC","5","6","6","Za su yi mulkin ƙasar Assuriya da takobi, ƙasar Nimrod kuma da zaran takobi. Zai cece mu daga hannun Assuriyawa sa’ad da suka kawo wa ƙasarmu hari suka kuma tattake zuwa cikin iyakokinmu. ");
INSERT INTO hausa_vpl VALUES ("MC5_7","034_5_7","MIC","5","7","7","Raguwar Yaƙub za tă kasance a tsakiyar mutane masu yawa kamar raɓa daga Ubangiji, kamar yayyafi a kan ciyawa, wanda ba ya jiran mutum ko kuma yă dakata wa ɗan adam. ");
INSERT INTO hausa_vpl VALUES ("MC5_8","034_5_8","MIC","5","8","8","Raguwar Yaƙub za tă kasance tare da al’ummai, a cikin mutane masu yawa, kamar zaki a cikin sauran namun jeji, kamar ɗan zaki cikin garken tumaki, wanda yake tattaka yă kuma yi kaca-kaca da su sa’ad da yake ratsa a cikinsu, ba kuwa wanda zai cece su. ");
INSERT INTO hausa_vpl VALUES ("MC5_9","034_5_9","MIC","5","9","9","Za a ɗaga hannunka cikin nasara a kan abokan gābanka, za a hallaka maƙiyanka duka. ");
INSERT INTO hausa_vpl VALUES ("MC5_10","034_5_10","MIC","5","10","10","“A wannan rana,” in ji Ubangiji “Zan hallaka dawakanku daga cikinku, in kuma rurrushe kekunan yaƙinku. ");
INSERT INTO hausa_vpl VALUES ("MC5_11","034_5_11","MIC","5","11","11","Zan hallaka biranen ƙasarku in yi rugu-rugu da dukan katangunku. ");
INSERT INTO hausa_vpl VALUES ("MC5_12","034_5_12","MIC","5","12","12","Zan kawar da maitarku, ba za a ƙara yin sihiri ba. ");
INSERT INTO hausa_vpl VALUES ("MC5_13","034_5_13","MIC","5","13","13","Zan sassare dukan gumakan da kuka sassaƙa da keɓaɓɓun duwatsunku a cikinku, nan gaba ba za ku ƙara rusuna wa aikin hannuwanku ba. ");
INSERT INTO hausa_vpl VALUES ("MC5_14","034_5_14","MIC","5","14","14","Zan tumɓuke daga gare ku ginshiƙan Asheranku in kuma rurrushe biranenku. ");
INSERT INTO hausa_vpl VALUES ("MC5_15","034_5_15","MIC","5","15","15","Zan yi ramuwa cikin fushi da hasala a kan al’umman da ba su yi mini biyayya ba.” ");
INSERT INTO hausa_vpl VALUES ("MC6_1","034_6_1","MIC","6","1","1","Ku saurari abin da Ubangiji ya ce, “Tashi ku gabatar da ƙararku a gaban duwatsu; bari tuddai su ji abin da kuke so ku faɗa. ");
INSERT INTO hausa_vpl VALUES ("MC6_2","034_6_2","MIC","6","2","2","“Ku saurara, ya ku duwatsu game da tuhumar da Ubangiji yake muku, ku ji, ku daɗaɗɗun tushin duniya. Gama Ubangiji yana da ƙara a kan mutanensa; yana tuhumar Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("MC6_3","034_6_3","MIC","6","3","3","“Ya ku mutanena, me na yi muku? Ta yaya na nawaita muku? Ku amsa mini. ");
INSERT INTO hausa_vpl VALUES ("MC6_4","034_6_4","MIC","6","4","4","Na fito da ku daga ƙasar Masar na kuma ’yantar da ku daga ƙasar bauta. Na aika da Musa yă jagorance ku, haka ma Haruna da Miriyam. ");
INSERT INTO hausa_vpl VALUES ("MC6_5","034_6_5","MIC","6","5","5","Ya ku mutanena, ku tuna abin da Balak sarkin Mowab ya ƙulla da kuma amsar da Bala’am ɗan Beyor ya bayar. Ku tuna da tafiyarku daga Shittim zuwa Gilgal, don ku san ayyukan adalcin Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("MC6_6","034_6_6","MIC","6","6","6","Da me zan zo a gaban Ubangiji in rusuna a gaban Maɗaukaki Allah? Shin, zan zo ne a gabansa da hadaya ta ƙonawa, da ɗan maraƙi bana ɗaya? ");
INSERT INTO hausa_vpl VALUES ("MC6_7","034_6_7","MIC","6","7","7","Ubangiji zai ji daɗin hadayar raguna dubbai da kuma rafuffukan mai dubbai goma? Zan ba da ɗan farina ne don laifina, ko ’ya’yan jikina domin zunubin raina? ");
INSERT INTO hausa_vpl VALUES ("MC6_8","034_6_8","MIC","6","8","8","Ya nuna maka, ya mutum, abin da yake mai kyau. Me Ubangiji yake bukata daga gare ka kuwa shi ne ka yi gaskiya ka so aikata jinƙai ka kuma yi tafiya da tawali’u a gaban Allah. ");
INSERT INTO hausa_vpl VALUES ("MC6_9","034_6_9","MIC","6","9","9","Ku saurara! Ubangiji yana kira ga birni, a ji tsoron sunana kuwa hikima ce, “Ku kasa kunne ga sandan nan da kuma wannan wanda ya naɗa. ");
INSERT INTO hausa_vpl VALUES ("MC6_10","034_6_10","MIC","6","10","10","Har yanzu zan manta, ya muguwar gida da dukiyarki da kika samu a muguwar hanya zan kuma manta da bugaggen mudun awo wanda ake zargi? ");
INSERT INTO hausa_vpl VALUES ("MC6_11","034_6_11","MIC","6","11","11","Zan kuɓutar da mutumin da yake da ma’auni na rashin gaskiya, da kuma buhun ma’aunan ƙarya? ");
INSERT INTO hausa_vpl VALUES ("MC6_12","034_6_12","MIC","6","12","12","Attajiranta masu fitina ne; mutanenta kuma maƙaryata ne harsunansu kuwa suna yaudara. ");
INSERT INTO hausa_vpl VALUES ("MC6_13","034_6_13","MIC","6","13","13","Saboda haka, zan hallaka ku in lalace ku saboda zunubanku. ");
INSERT INTO hausa_vpl VALUES ("MC6_14","034_6_14","MIC","6","14","14","Za ku ci amma ba za ku ƙoshi ba, cikinku zai zama babu kome Za ku tattara amma ba za ku yi ajiyar kome ba, gama abin da kuka yi ajiya zan ba wa takobi. ");
INSERT INTO hausa_vpl VALUES ("MC6_15","034_6_15","MIC","6","15","15","Za ku yi shuki amma ba za ku girba ba; za ku matse zaitun amma ba za ku yi amfani da mai wa kanku ba, za ku tattaka ’ya’yan inabi amma ba za ku sha ruwan inabin ba. ");
INSERT INTO hausa_vpl VALUES ("MC6_16","034_6_16","MIC","6","16","16","Kuna kiyaye ƙa’idodin Omri da dukan ayyukan gidan Ahab kun kuma bi al’adunsu. Saboda haka, zan maishe ku kufai in mai da ku abin dariya a cikin mutane, za ku sha reni a wurin al’ummai.” ");
INSERT INTO hausa_vpl VALUES ("MC7_1","034_7_1","MIC","7","1","1","Tawa ta ƙare! Ina kama da wanda yake tattara ’ya’yan itatuwa a lokacin kalar ’ya’yan inabi; babu sauran nonon inabin da za a tsinka a ci, babu kuma ’ya’yan ɓaure na farko-farkon da raina yake marmari. ");
INSERT INTO hausa_vpl VALUES ("MC7_2","034_7_2","MIC","7","2","2","An kawar da masu tsoron Allah daga ƙasar; babu sauran mai adalcin da ya rage. Dukan mutane suna kwanto don su zub da jini; kowa yana farautar ɗan’uwansa da tarko. ");
INSERT INTO hausa_vpl VALUES ("MC7_3","034_7_3","MIC","7","3","3","Dukan hannuwansu sun gwaninta wajen yin mugunta; shugabanni suna nema a ba su kyautai, alƙalai suna nema a ba su cin hanci, masu iko suna faɗar son zuciyarsu, duk suna ƙulla makirci tare. ");
INSERT INTO hausa_vpl VALUES ("MC7_4","034_7_4","MIC","7","4","4","Mafi kyau a cikinsu yana kama da ƙaya, mafi gaskiyarsu ya fi shingen ƙaya muni. Ranar da Allah zai ziyarce ku ta zo, ranar da masu gadinku za su hura ƙaho. Yanzu ne lokacin ruɗewarku. ");
INSERT INTO hausa_vpl VALUES ("MC7_5","034_7_5","MIC","7","5","5","Kada ka yarda da maƙwabci; kada ka sa begenka ga abokai. Ko ma wadda take kwance a ƙirjinka, ka yi hankali da kalmominka. ");
INSERT INTO hausa_vpl VALUES ("MC7_6","034_7_6","MIC","7","6","6","Gama ɗa yakan ce wannan ba mahaifinsa ba ne, diya kuma takan tayar wa mahaifiyarta, matar ɗa takan yi gāba da uwar mijinta, abokan gāban mutum su ne iyalin cikin gidansa. ");
INSERT INTO hausa_vpl VALUES ("MC7_7","034_7_7","MIC","7","7","7","Amma game da ni, zan sa bege ga Ubangiji, ina sauraron Allah Mai Cetona; Allahna kuwa zai ji ni. ");
INSERT INTO hausa_vpl VALUES ("MC7_8","034_7_8","MIC","7","8","8","Kada ku yi farin ciki, ku maƙiyana! Ko da yake na fāɗi, zan tashi. Ko da yake na zauna a cikin duhu, Ubangiji zai zama haskena. ");
INSERT INTO hausa_vpl VALUES ("MC7_9","034_7_9","MIC","7","9","9","Domin na yi masa zunubi, zan fuskanci fushin Ubangiji, har sai ya dubi batuna ya kuma tabbatar da ’yancina. Zai kawo ni zuwa wurin haske; zan ga adalcinsa. ");
INSERT INTO hausa_vpl VALUES ("MC7_10","034_7_10","MIC","7","10","10","Sa’an nan maƙiyina zai gani yă kuma sha kunya, shi da yake ce da ni “Ina Ubangiji Allahnka?” Zai gani, yă kuma ji kunya. Ko yanzu ma za a tattake shi kamar taɓo a tituna. ");
INSERT INTO hausa_vpl VALUES ("MC7_11","034_7_11","MIC","7","11","11","Ranar gina katangarka tana zuwa, a ranar za a fadada iyakokinka. ");
INSERT INTO hausa_vpl VALUES ("MC7_12","034_7_12","MIC","7","12","12","A wannan rana mutane za su zo gare ka daga Assuriya da kuma biranen Masar, daga Masar ma har zuwa Yuferites daga teku zuwa teku, kuma daga dutse zuwa dutse. ");
INSERT INTO hausa_vpl VALUES ("MC7_13","034_7_13","MIC","7","13","13","Duniya za tă zama kufai saboda mazaunanta, saboda ayyukansu. ");
INSERT INTO hausa_vpl VALUES ("MC7_14","034_7_14","MIC","7","14","14","Ka yi kiwon mutanenka da sandarka, garken gādonka, wanda yake zaune shi kaɗai a kurmi, a ƙasa mai kyau ta kiwo, bari su yi kiwo a Bashan da Gileyad kamar a kwanakin dā. ");
INSERT INTO hausa_vpl VALUES ("MC7_15","034_7_15","MIC","7","15","15","“Kamar a kwanakin da kuka fito daga Masar, zan nuna musu al’ajabaina.” ");
INSERT INTO hausa_vpl VALUES ("MC7_16","034_7_16","MIC","7","16","16","Al’ummai za su gani su kuma ji kunya, za a kuma ƙwace musu dukan ikonsu. Za su kama bakinsu kunnuwansu kuma za su zama kurame. ");
INSERT INTO hausa_vpl VALUES ("MC7_17","034_7_17","MIC","7","17","17","Za su lashi ƙura kamar maciji, kamar dabbobi masu rarrafe a ƙasa. Za su fito daga maɓuyarsu da rawan jiki, za su juya cikin tsoro ga Ubangiji Allahnmu su kuma ji tsoronku. ");
INSERT INTO hausa_vpl VALUES ("MC7_18","034_7_18","MIC","7","18","18","Wane ne Allah kamar ka, wanda yake yafe zunubi yă kuma gafarta laifofin mutanensa da suka ragu? Ba ka zama mai fushi har abada amma kana marmari ka nuna jinƙai. ");
INSERT INTO hausa_vpl VALUES ("MC7_19","034_7_19","MIC","7","19","19","Za ka sāke jin tausayinmu; za ka tattake zunubanmu a ƙarƙashin sawunka ka kuma tura dukan kurakuranmu zuwa cikin zurfafan teku. ");
INSERT INTO hausa_vpl VALUES ("MC7_20","034_7_20","MIC","7","20","20","Za ka yi wa Yaƙub aminci, ka kuma nuna jinƙai ga Ibrahim, kamar yadda ka yi alkawari da rantsuwa ga kakanninmu tun a kwanankin dā.");
INSERT INTO hausa_vpl VALUES ("NM1_1","035_1_1","NAM","1","1","1","Jawabi game da Ninebe a littafin wahayin Nahum, mutumin Elkosh. ");
INSERT INTO hausa_vpl VALUES ("NM1_2","035_1_2","NAM","1","2","2","Ubangiji Allah mai kishi ne, mai sakayya kuma. Ubangiji Allah mai kishi ne, mai ɗaukar fansa kuma. Ubangiji yakan ɗauki fansa a kan maƙiyansa, yakan ci gaba da fushi a kan abokan gābansa. ");
INSERT INTO hausa_vpl VALUES ("NM1_3","035_1_3","NAM","1","3","3","Ubangiji mai jinkirin fushi ne, mai iko duka kuma. Ubangiji ba zai bar masu zunubi babu horo ba. Hanyarsa tana cikin guguwa da kuma hadari, gizagizai kuwa su ne ƙurar ƙafafunsa. ");
INSERT INTO hausa_vpl VALUES ("NM1_4","035_1_4","NAM","1","4","4","Yakan tsawata wa teku yă kuma busar da shi; yakan sa dukan koguna su kafe. Bashan da Karmel sun yi yaushi tohon Lebanon kuma ya koɗe. ");
INSERT INTO hausa_vpl VALUES ("NM1_5","035_1_5","NAM","1","5","5","Duwatsu suna rawan jiki a gabansa tuddai kuma sun narke. Duniya da dukan abin da yake cikinta suna rawan jiki a gabansa. ");
INSERT INTO hausa_vpl VALUES ("NM1_6","035_1_6","NAM","1","6","6","Wa zai iya tsaya wa fushinsa? Wa yake da ikon jimre wa zafin hasalarsa? Ana zuba fushinsa kamar wuta; aka kuma ragargaza duwatsu a gabansa. ");
INSERT INTO hausa_vpl VALUES ("NM1_7","035_1_7","NAM","1","7","7","Ubangiji nagari ne, mafaka kuma a lokacin wahala. Yana kula da waɗanda suka dogara gare shi, ");
INSERT INTO hausa_vpl VALUES ("NM1_8","035_1_8","NAM","1","8","8","amma da ambaliyar ruwa zai kawo Ninebe ga ƙarshe; zai fafari maƙiyansa zuwa cikin duhu. ");
INSERT INTO hausa_vpl VALUES ("NM1_9","035_1_9","NAM","1","9","9","Dukan abin da suke ƙullawa game da Ubangiji zai kawo ga ƙarshe; wahala ba za tă sāke komowa ƙaro na biyu ba. ");
INSERT INTO hausa_vpl VALUES ("NM1_10","035_1_10","NAM","1","10","10","Za su sarƙafe a ƙaya, za su kuma bugu da ruwan inabinsu; za a laƙume su kamar busasshiyar ciyawa. ");
INSERT INTO hausa_vpl VALUES ("NM1_11","035_1_11","NAM","1","11","11","Daga cikinki, ya Ninebe wani ya fito wanda ya ƙulla wa Ubangiji makirci yana ba da mugayen shawarwari. ");
INSERT INTO hausa_vpl VALUES ("NM1_12","035_1_12","NAM","1","12","12","Ga abin da Ubangiji ya ce, “Ko da yake sun yi tarayya, suna kuma da yawa, za a yanke su, a kawar a su. Ko da yake na ba ki azaba, ya Yahuda, ba zan ƙara ba ki azaba ba. ");
INSERT INTO hausa_vpl VALUES ("NM1_13","035_1_13","NAM","1","13","13","Yanzu zan karya karkiyarsu daga wuyanki in kuma tsittsinke sarƙar da suka ɗaura ki.” ");
INSERT INTO hausa_vpl VALUES ("NM1_14","035_1_14","NAM","1","14","14","Ubangiji ya ba da umarni game da ke Ninebe, “Ba za ki sami zuriyar da za tă ci gaba da sunanki ba. Zan rurrushe siffofin da kuka sassaƙa da kuma gumakan da kuka ƙera gumakan da suke a cikin haikalin allolinku. Zan shirya kabarinki, domin ke muguwa ce.” ");
INSERT INTO hausa_vpl VALUES ("NM1_15","035_1_15","NAM","1","15","15","Duba, can a bisa duwatsu, ga ƙafafu mai kawo labari mai daɗi, wanda yake shelar salama! Ki yi bukukkuwanki, ya Yahuda, ki kuma cika wa’adodinki. Mugaye ba za su ƙara mamaye ki ba; domin za a hallaka su ƙaƙaf. ");
INSERT INTO hausa_vpl VALUES ("NM2_1","035_2_1","NAM","2","1","1","Mai hari yana matsowa a kanki, Ninebe. Ki tsare mafaka, ki yi gadin hanya ki sha ɗamara ki tattaro dukan ƙarfinki! ");
INSERT INTO hausa_vpl VALUES ("NM2_2","035_2_2","NAM","2","2","2","Ubangiji zai maido da darajar Yaƙub, kamar ta Isra’ila, ko da yake masu washewa sun washe su suka kuma lalatar da inabinsu. ");
INSERT INTO hausa_vpl VALUES ("NM2_3","035_2_3","NAM","2","3","3","Garkuwoyin sojojinsa ja wur ne; jarumawansa suna sanye da kaya masu ruwan jan garura. Ƙarafan kekunan yaƙi suna walƙiya a ranar da aka shirya su; ana kaɗa māsu da bantsoro. ");
INSERT INTO hausa_vpl VALUES ("NM2_4","035_2_4","NAM","2","4","4","Kekunan yaƙi sun zabura a tituna, suna kai da kawowa a dandali. Suna walƙiya kamar tocila suna sheƙawa a guje kamar walƙiya. ");
INSERT INTO hausa_vpl VALUES ("NM2_5","035_2_5","NAM","2","5","5","Ninebe ta tattara rundunarta, duk da haka sun yi ta tuntuɓe a kan hanyarsu. Sun ruga zuwa katangan birnin, sun sanya garkuwar kāriya a inda ya kamata. ");
INSERT INTO hausa_vpl VALUES ("NM2_6","035_2_6","NAM","2","6","6","An buɗe ƙofofin rafuffukan sai wurin ya rurrushe. ");
INSERT INTO hausa_vpl VALUES ("NM2_7","035_2_7","NAM","2","7","7","An umarta cewa birnin za tă tafi bauta, za a kuma yi gaba da su. Bayi ’yan mata suna kuka kamar tattabaru suna buga ƙirjinsu. ");
INSERT INTO hausa_vpl VALUES ("NM2_8","035_2_8","NAM","2","8","8","Ninebe tana kama da tafki, wanda ruwanta yana yoyo. Suna kuka suna cewa, “Ku tsaya! Ku tsaya,” amma ba wanda ya waiga. ");
INSERT INTO hausa_vpl VALUES ("NM2_9","035_2_9","NAM","2","9","9","A washe azurfa; a washe zinariya; dukiyarsu ba ta da iyaka, arzikinsu kuma ba ya ƙarewa. ");
INSERT INTO hausa_vpl VALUES ("NM2_10","035_2_10","NAM","2","10","10","Ta zama wofi, an washe ta, an tuɓe ta! Zukata sun narke, gwiwoyi suna kaɗuwa, jikuna suna rawa, fuskoki duk sun kwantsare! ");
INSERT INTO hausa_vpl VALUES ("NM2_11","035_2_11","NAM","2","11","11","Ina kogon zakokin nan yake yanzu, inda suka ciyar da ’ya’yansu, inda zaki da zakanya sukan shiga, da ’ya’yansu, ba mai damunsu ");
INSERT INTO hausa_vpl VALUES ("NM2_12","035_2_12","NAM","2","12","12","Zaki ya kashe abin da ya ishe ’ya’yansa ya kuma murɗe wuyan dabbobi ya cika wurin zamansa da abin da ya kama ya cika kogwanninsa da abin da ya kashe. ");
INSERT INTO hausa_vpl VALUES ("NM2_13","035_2_13","NAM","2","13","13","“Ina gāba da ke,” in ji Ubangiji Maɗaukaki. “Zan ƙone kekunan yaƙinki, takobi kuma zai fafare ’ya’yan zakokinki. Ba kuma zan bar miki namun jejin da za ki kashe a duniya ba. Ba kuwa za a ƙara jin muryar ’yan saƙonki ba.” ");
INSERT INTO hausa_vpl VALUES ("NM3_1","035_3_1","NAM","3","1","1","Kaiton birni mai zub da jini, wadda take cike da ƙarairayi, cike da ganima, wadda ba a rasa masu fāɗawa cikin wahala! ");
INSERT INTO hausa_vpl VALUES ("NM3_2","035_3_2","NAM","3","2","2","Ku ji karar bulala da kwaramniyar ƙafafu, da sukuwar dawakai da girgizar kekunan yaƙi! ");
INSERT INTO hausa_vpl VALUES ("NM3_3","035_3_3","NAM","3","3","3","Mahaya dawakai sun kunno kai, takuba suna walƙiya, māsu kuma suna ƙyali; ga ɗumbun da aka kashe ga tsibin matattu, gawawwaki ba iyaka, mutane suna tuntuɓe da gawawwaki, ");
INSERT INTO hausa_vpl VALUES ("NM3_4","035_3_4","NAM","3","4","4","duk saboda yawan sha’awace-sha’awacen karuwa, mai daɗin baki, uwargidan maita, wadda ta ɓad da al’ummai ta wurin karuwancinta ta kuma ɓad da mutane ta wurin maitancinta. ");
INSERT INTO hausa_vpl VALUES ("NM3_5","035_3_5","NAM","3","5","5","“Ina gāba da ke,” in ji Ubangiji Maɗaukaki. “Zan kware fatarinki a idonki. Zan nuna wa al’ummai tsiraicinki, masarautai kuma kunyarki. ");
INSERT INTO hausa_vpl VALUES ("NM3_6","035_3_6","NAM","3","6","6","Zan watsa miki ƙazanta, in yi miki wulaƙanci in kuma mai da ke abin reni. ");
INSERT INTO hausa_vpl VALUES ("NM3_7","035_3_7","NAM","3","7","7","Duk wanda ya gan ki zai gudu daga gare ki yana cewa, ‘Ninebe ta lalace, wa zai yi makoki domin ta?’ Ina zan sami wani wanda zai yi miki ta’aziyya?” ");
INSERT INTO hausa_vpl VALUES ("NM3_8","035_3_8","NAM","3","8","8","Kin fi Tebes ne da take a bakin Nilu, da ruwa yake kewaye da ita? Rafi shi ne kāriyarta, ruwanta kuma katanga. ");
INSERT INTO hausa_vpl VALUES ("NM3_9","035_3_9","NAM","3","9","9","Kush da kuma Masar su ne ƙarfinta marar iyaka; Fut da Libiya suna cikin mataimakanta. ");
INSERT INTO hausa_vpl VALUES ("NM3_10","035_3_10","NAM","3","10","10","Duk da haka an tafi da ita ta kuma tafi bauta. Aka fyaɗa ƙanananta da ƙasa aka yayyanka su gunduwa-gunduwa a kan kowane titi. Aka jefa ƙuri’a a kan manyan mutanenta, aka daure manyan mutanenta da sarƙoƙi. ");
INSERT INTO hausa_vpl VALUES ("NM3_11","035_3_11","NAM","3","11","11","Ke ma za ki bugu, za ki ɓuya. Ki kuma nemi mafaka daga wurin abokin gāba. ");
INSERT INTO hausa_vpl VALUES ("NM3_12","035_3_12","NAM","3","12","12","Dukan kagarunki suna kama da itatuwan ɓaure da ’ya’yansu da suka nuna. Da an girgiza, sai ɓaure su zuba a bakin mai sha. ");
INSERT INTO hausa_vpl VALUES ("NM3_13","035_3_13","NAM","3","13","13","Dubi mayaƙanki, duk mata ne! Ƙofofin ƙasarki a buɗe suke ga abokan gābanki, wuta ta cinye madogaransu. ");
INSERT INTO hausa_vpl VALUES ("NM3_14","035_3_14","NAM","3","14","14","Ki ja ruwa gama za a kewaye ki da yaƙi. Ki ƙara ƙarfin kagaranki! Ki kwaɓa laka, ki sassaƙa turmi ki gyara abin yin tubali! ");
INSERT INTO hausa_vpl VALUES ("NM3_15","035_3_15","NAM","3","15","15","A can wuta za tă cinye ki; takobi zai sare ki, kuma kamar fāra, za a cinye ki. Ki riɓaɓɓanya kamar fāra, ki riɓaɓɓanya kamar fārin ɗango! ");
INSERT INTO hausa_vpl VALUES ("NM3_16","035_3_16","NAM","3","16","16","Kin ƙara yawan masu kasuwancinki har sai da suka fi taurarin sama. Amma kamar fāra sun cinye ƙasar sa’an nan suka tashi, suka tafi. ");
INSERT INTO hausa_vpl VALUES ("NM3_17","035_3_17","NAM","3","17","17","Masu tsaronki suna kama da fāri ɗango, shugabanninki sun yi cincirindo kamar fārin ɗango da suka sauka a kan bango a rana mai sanyi, amma da rana ta fito, duk za su tashi su tafi, ba kuma wanda ya san inda suka nufa. ");
INSERT INTO hausa_vpl VALUES ("NM3_18","035_3_18","NAM","3","18","18","Ya sarkin Assuriya, makiyayanka sun yi barci; manyan mutanenka sun kwanta su huta. An watsar da mutanenka a cikin duwatsu, ba wanda zai tattaro su. ");
INSERT INTO hausa_vpl VALUES ("NM3_19","035_3_19","NAM","3","19","19","Ba abin da zai warkar da rauninka; rauninka ya yi muni. Duk wanda ya ji labarinka zai tafa hannuwansa saboda farin cikin fāɗuwarka, gama wane ne bai ji jiki a hannunka ba?");
INSERT INTO hausa_vpl VALUES ("HK1_1","036_1_1","HAB","1","1","1","Saƙon da annabi Habakkuk ya karɓa. ");
INSERT INTO hausa_vpl VALUES ("HK1_2","036_1_2","HAB","1","2","2","Har yaushe, ya Ubangiji, zan yi kukan neman taimako, amma ka ƙi ji? Ina kuka a gare ka saboda zalunci amma ba ka ce ufam ba. ");
INSERT INTO hausa_vpl VALUES ("HK1_3","036_1_3","HAB","1","3","3","Me ya sa ka bari ina ta kallon rashin gaskiya? Me ya sa kake barin abin da ba daidai ba? Hallaka da tashin hankali suna a gabana; ga rashin jituwa da faɗa ko’ina. ");
INSERT INTO hausa_vpl VALUES ("HK1_4","036_1_4","HAB","1","4","4","Saboda haka ba a bin doka, shari’a kuma ba ta aiki. Mugaye sun kewaye masu adalci don a hana gaskiya tă yi aiki. ");
INSERT INTO hausa_vpl VALUES ("HK1_5","036_1_5","HAB","1","5","5","“Ka dubi al’ummai, ka gani, ka sha mamaki. Ga shi zan yi wani abu a kwanakinka, wanda ko ma an faɗa maka ba za ka gaskata ba. ");
INSERT INTO hausa_vpl VALUES ("HK1_6","036_1_6","HAB","1","6","6","Zan tā da Babiloniyawa, waɗannan marasa hankali da kuma marasa tausayi; masu gajeren haƙuri, waɗanda suke ratsa ko’ina a duniya don su ƙwace wuraren zaman da ba nasu ba. ");
INSERT INTO hausa_vpl VALUES ("HK1_7","036_1_7","HAB","1","7","7","Suna da bantsoro da firgitarwa; dokoki da ƙa’idodinsu ne kawai suka sani. ");
INSERT INTO hausa_vpl VALUES ("HK1_8","036_1_8","HAB","1","8","8","Dawakansu sun fi damisoshi sauri, sun fi kyarketan yamma zafin rai. Mahayansu suna zuwa a guje; mahayansu daga nesa suka fito. Suna firiya kamar ungulu mai sauka da gaggawa don yă ci mushe; ");
INSERT INTO hausa_vpl VALUES ("HK1_9","036_1_9","HAB","1","9","9","duk sukan zo da nufin tā-da-na-zaune-tsaye. Ana jin tsoronsu tun ma kafin su iso suna tattara bayi kamar yashi. ");
INSERT INTO hausa_vpl VALUES ("HK1_10","036_1_10","HAB","1","10","10","Sukan yi wa sarakuna ba’a su kuma rena masu mulki. Sukan yi wa dukan birane masu mafaka dariya; sukan tara ƙasa su hau, su cinye abokan gābansu da yaƙi. ");
INSERT INTO hausa_vpl VALUES ("HK1_11","036_1_11","HAB","1","11","11","Sa’an nan su wuce da sauri kamar iska, mutane ne masu laifi, waɗanda ƙarfinsu shi ne allahnsu.” ");
INSERT INTO hausa_vpl VALUES ("HK1_12","036_1_12","HAB","1","12","12","Ya Ubangiji, ba tun fil azal kake ba? Ya Allahna, Mai Tsarkina, ba za mu mutu ba. Ya Ubangiji ka sanya su su tabbatar da hukunci; Ya Dutse, ka naɗa su don su yi hukunci. ");
INSERT INTO hausa_vpl VALUES ("HK1_13","036_1_13","HAB","1","13","13","Idanunka masu tsarki ne da suka fi gaban duban mugunta; ba ka amince da abin da ke ba daidai ba. To, don me ka ƙyale munafukai suna cin karensu ba babbaka? Me ya sa kake shiru sa’ad da mugaye suke haɗiye adalai da suka fi su adalci? ");
INSERT INTO hausa_vpl VALUES ("HK1_14","036_1_14","HAB","1","14","14","Ka mai da maza kamar kifin teku, kamar halittun tekun da ba su da shugaba. ");
INSERT INTO hausa_vpl VALUES ("HK1_15","036_1_15","HAB","1","15","15","Mugu abokin gāba yakan kama su duka da ƙugiya, yă jawo su waje da abin kamun kifinsa, yă tattara su cikin ragarsa, ta haka yakan yi murna da farin ciki. ");
INSERT INTO hausa_vpl VALUES ("HK1_16","036_1_16","HAB","1","16","16","Saboda haka yakan yi hadaya wa abin kamun kifinsa yă kuma ƙona turare wa ragarsa, domin ta wurin abin kamun kifinsa ne yake yin rayuwar jin daɗi yă kuma zaɓi irin abincin da yake so. ");
INSERT INTO hausa_vpl VALUES ("HK1_17","036_1_17","HAB","1","17","17","Zai ci gaba da juye abin kamun kifinsu ke nan, suna hallaka al’ummai ba tausayi? ");
INSERT INTO hausa_vpl VALUES ("HK2_1","036_2_1","HAB","2","1","1","Zan tsaya wurin tsarona in kuma zauna a kan katanga; zan jira in ga abin da zai ce mini, da kuma wace amsa zan bayar ga wannan kuka. ");
INSERT INTO hausa_vpl VALUES ("HK2_2","036_2_2","HAB","2","2","2","Sa’an nan Ubangiji ya amsa ya ce, “Ka rubuta wannan ru’uya ka bayyana ta a fili a kan alluna don mai shela yă ruga da ita, yă kai. ");
INSERT INTO hausa_vpl VALUES ("HK2_3","036_2_3","HAB","2","3","3","Gama ru’uyar tana jiran ƙayyadadden lokaci; tana zancen ƙarshe kuma ba za tă zama ƙarya ba. Ko da ka ga kamar tana jinkiri, ka jira ta; lalle za tă zo, ba za tă makara ba. ");
INSERT INTO hausa_vpl VALUES ("HK2_4","036_2_4","HAB","2","4","4","“Duba, abokin gāba ya cika da ɗaga kai; sha’awarsa ba daidai ba ce, amma mai adalci zai rayu ta wurin bangaskiyarsa, ");
INSERT INTO hausa_vpl VALUES ("HK2_5","036_2_5","HAB","2","5","5","ba shakka, ruwan inabi ya yaudare shi; yana fariya kuma ba ya hutu. Domin shi mai haɗama ne kamar kabari kuma kamar mutuwa, ba ya ƙoshi; yakan tattara dukan al’ummai wa kansa yana kuma kama dukan mutane su zama kamammu. ");
INSERT INTO hausa_vpl VALUES ("HK2_6","036_2_6","HAB","2","6","6","“Dukansu ba za su yi masa tsiya, suna yin masa ba’a da dariya ba, suna cewa, “ ‘Kaito ga wannan wanda ya tara wa kansa kayan sata ya kuma wadatar da kansa da kayan ƙwace! Har yaushe wannan abu zai ci gaba?’ ");
INSERT INTO hausa_vpl VALUES ("HK2_7","036_2_7","HAB","2","7","7","Masu binka bashi ba za su taso maka nan da nan ba? Ba za su farka su sa ka fargaba ba? Ta haka ka zama ganima a gare su. ");
INSERT INTO hausa_vpl VALUES ("HK2_8","036_2_8","HAB","2","8","8","Domin ka washe al’ummai masu yawa, mutanen da suka rage za su washe ka. Domin ka zub da jinin mutane; ka hallaka ƙasashe, da birane, da kuma kowa da yake cikinsu. ");
INSERT INTO hausa_vpl VALUES ("HK2_9","036_2_9","HAB","2","9","9","“Kaito ga wanda ya gina masarautarsa da ƙazamar riba don yă kafa sheƙarsa can bisa, don yă tsere wa zama kango! ");
INSERT INTO hausa_vpl VALUES ("HK2_10","036_2_10","HAB","2","10","10","Ka ƙulla lalacin mutane masu yawa, ta haka ka kunyatar da gidanka ka kuma hallaka ranka. ");
INSERT INTO hausa_vpl VALUES ("HK2_11","036_2_11","HAB","2","11","11","Duwatsun katanga za su yi kuka, ginshiƙan katako kuma za su amsa. ");
INSERT INTO hausa_vpl VALUES ("HK2_12","036_2_12","HAB","2","12","12","“Kaiton mutumin da ya gina birni da jinin da ya zubar ya kuma kafa gari ta wurin mugun aiki! ");
INSERT INTO hausa_vpl VALUES ("HK2_13","036_2_13","HAB","2","13","13","Ba Ubangiji Maɗaukaki ne ya ƙudura cewa wahalar mutane ta zama mai kawai don wuta ba, cewa al’ummai su gajiyar da kansu a banza ba? ");
INSERT INTO hausa_vpl VALUES ("HK2_14","036_2_14","HAB","2","14","14","Gama duniya za tă cika da sanin ɗaukakar Ubangiji, yadda ruwaye suka rufe teku. ");
INSERT INTO hausa_vpl VALUES ("HK2_15","036_2_15","HAB","2","15","15","“Kaito wanda ya ba wa maƙwabtansa abin sha, yana ta zubawa daga salkan ruwan inabi har sai sun bugu, don dai yă ga tsiraicinsu. ");
INSERT INTO hausa_vpl VALUES ("HK2_16","036_2_16","HAB","2","16","16","Za ka cika da kunya a maimakon ɗaukaka. Yanzu lokacinka ne! Kai ma ka sha, a kuma tone asirinka! Gama kwaf na hannun daman Ubangiji yana zuwa kewaye da kai, abin kunya kuma zai rufe darajarka. ");
INSERT INTO hausa_vpl VALUES ("HK2_17","036_2_17","HAB","2","17","17","Ɓarnar da ka yi wa Lebanon zai komo kanka, kuma hallakar dabbobin da ka yi zai sa dabbobi su tsorata ka. Gama ka zub da jinin mutum; ka hallaka ƙasashe, da birane, da kuma kowa da yake cikinsu. ");
INSERT INTO hausa_vpl VALUES ("HK2_18","036_2_18","HAB","2","18","18","“Ina amfanin gunki da mutum ne ya sassaƙa? Ko siffar da take koyar da ƙarya? Gama wanda ya yi shi yana dogara ne ga halittarsa; ya yi gumakan da ba sa magana. ");
INSERT INTO hausa_vpl VALUES ("HK2_19","036_2_19","HAB","2","19","19","Kaito wanda ya ce da katako, ‘Rayu!’ Ko kuwa dutse marar rai, ‘Farka!’ Zai iya bishewa ne? An dalaye shi da zinariya da azurfa; ba numfashi a cikinsa.” ");
INSERT INTO hausa_vpl VALUES ("HK2_20","036_2_20","HAB","2","20","20","Amma Ubangiji yana a cikin haikalinsa mai tsarki; bari dukan duniya tă yi shiru a gabansa. ");
INSERT INTO hausa_vpl VALUES ("HK3_1","036_3_1","HAB","3","1","1","Addu’ar annabi Habakkuk. A kan shigiyont. ");
INSERT INTO hausa_vpl VALUES ("HK3_2","036_3_2","HAB","3","2","2","Ya Ubangiji, na ji irin shaharar da ka yi; na yi al’ajabi game da ayyukanka, ya Ubangiji. Ka maimaita su a kwanakinmu, ka sanar da su a lokacinmu; ka yi jinƙai ko a lokacin da kake fushi. ");
INSERT INTO hausa_vpl VALUES ("HK3_3","036_3_3","HAB","3","3","3","Allah ya zo daga Teman, Mai Tsarkin nan daga Dutsen Faran. Sela Ɗaukakarsa ta rufe sammai yabonsa kuma ya cika duniya. ");
INSERT INTO hausa_vpl VALUES ("HK3_4","036_3_4","HAB","3","4","4","Darajarsa ta yi kamar fitowar rana; ƙyalƙyali ya wulga daga hannunsa, inda ikonsa yake a ɓoye. ");
INSERT INTO hausa_vpl VALUES ("HK3_5","036_3_5","HAB","3","5","5","Annoba ta sha gabansa; cuta kuma tana bin bayansa. ");
INSERT INTO hausa_vpl VALUES ("HK3_6","036_3_6","HAB","3","6","6","Ya tsaya, ya kuwa girgiza duniya; ya duba, sai ya sa al’ummai suka yi rawan jiki. Tsofaffin duwatsu sun wargaje daɗaɗɗun tuddai kuma suka rurrushe. Hanyoyinsa dawwammamu ne. ");
INSERT INTO hausa_vpl VALUES ("HK3_7","036_3_7","HAB","3","7","7","Na ga tentin Kushan cikin azaba; wuraren zaman Midiyan cikin damuwa. ");
INSERT INTO hausa_vpl VALUES ("HK3_8","036_3_8","HAB","3","8","8","Ka ji haushin koguna ne, ya Ubangiji? Ko kuwa ka hasala da rafuffuka ne? Ko ka yi fushi da teku ne sa’ad da ka hau dawakanka da kuma kekunan yaƙinka masu nasara? ");
INSERT INTO hausa_vpl VALUES ("HK3_9","036_3_9","HAB","3","9","9","Ka ja bakanka, ka nemi a ba ka kibiyoyi masu yawa. Sela Ka raba duniya da koguna; ");
INSERT INTO hausa_vpl VALUES ("HK3_10","036_3_10","HAB","3","10","10","duwatsu sun gan ka sai suka ƙame. Ruwaye masu hauka sun yi ta fantsamawa; zurfafa suka yi ruri suka tā da raƙuman ruwansu sama. ");
INSERT INTO hausa_vpl VALUES ("HK3_11","036_3_11","HAB","3","11","11","Rana da wata suka tsaya cik a sammai da ganin kibiyoyinka masu wucewa fyu, da ganin hasken māshinka mai walƙiya. ");
INSERT INTO hausa_vpl VALUES ("HK3_12","036_3_12","HAB","3","12","12","Cikin hasala ka ratsa duniya cikin fushi kuma ka tattake ƙasashe. ");
INSERT INTO hausa_vpl VALUES ("HK3_13","036_3_13","HAB","3","13","13","Ka fito don ka fanshi mutanenka, don ceci shafaffenka. Ka ragargaza shugaban ƙasar mugaye, ka tuɓe shi daga kai har ƙafa. Sela ");
INSERT INTO hausa_vpl VALUES ("HK3_14","036_3_14","HAB","3","14","14","Da māshinsa ka soki kansa sa’ad da jarumawansa suka fito don su tarwatse mu, suna farin ciki sai ka ce masu shirin cinye matalautan da suke a ɓoye. ");
INSERT INTO hausa_vpl VALUES ("HK3_15","036_3_15","HAB","3","15","15","Ka tattake teku da dawakanka, kana kaɗa manyan ruwaye. ");
INSERT INTO hausa_vpl VALUES ("HK3_16","036_3_16","HAB","3","16","16","Na ji sai zuciyata ta buga, leɓunana sun yi rawa da jin murya; ƙasusuwana suka ruɓe, ƙafafuna kuma sun yi rawa. Duk da haka zan jira da haƙuri ga ranar bala’i ta zo a kan al’umman nan mai kawo mana hari. ");
INSERT INTO hausa_vpl VALUES ("HK3_17","036_3_17","HAB","3","17","17","Ko da yake itace ɓaure bai tohu ba, ba kuma ’ya’ya a kuringar inabi, ko da yake zaitun bai ba da amfani ba, gonaki kuma ba su ba da abinci ba, ko da yake babu tumaki a garke, ba kuma shanu a turaku, ");
INSERT INTO hausa_vpl VALUES ("HK3_18","036_3_18","HAB","3","18","18","duk da haka zan yi farin ciki da Ubangiji, zan yi murna da Allah Mai Cetona. ");
INSERT INTO hausa_vpl VALUES ("HK3_19","036_3_19","HAB","3","19","19","Ubangiji Mai Iko Duka shi ne ƙarfina; yakan mai da ƙafafuna kamar na barewa, yakan sa in yi tafiya a wurare masu tsayi. Domin mai bi da kaɗe-kaɗe. A kan kayan kiɗi masu tsirkiyata.");
INSERT INTO hausa_vpl VALUES ("ZP1_1","037_1_1","ZEP","1","1","1"," Maganar Ubangiji da ta zo wa Zefaniya ɗan Kushi, ɗan Gedaliya, ɗan Amariya, ɗan Hezekiya, a zamanin Yosiya ɗan Amon sarkin Yahuda. ");
INSERT INTO hausa_vpl VALUES ("ZP1_2","037_1_2","ZEP","1","2","2","“Zan hallaka kome a fuskar duniya,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ZP1_3","037_1_3","ZEP","1","3","3","“Zan hallaka mutane da dabbobi; zan kuma hallaka tsuntsayen sama da kifayen teku, da gumakan da suke sa mugaye su yi tuntuɓe.” “Sa’ad da zan kawar da mutum daga fuskar duniya,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ZP1_4","037_1_4","ZEP","1","4","4","“Zan miƙa hannuna gāba da Yahuda da kuma dukan mazaunan Urushalima. Zan datse raguwar Ba’al daga wannan wuri, da sunayen firistocin gumaka da na marasa sanin Allah, ");
INSERT INTO hausa_vpl VALUES ("ZP1_5","037_1_5","ZEP","1","5","5","waɗanda suka rusuna a kan rufin ɗaki don su yi sujada ga rundunar taurari. Waɗanda suka rusuna suka kuma yi rantsuwa da sunan Ubangiji suke kuma rantsuwa da sunan Molek. ");
INSERT INTO hausa_vpl VALUES ("ZP1_6","037_1_6","ZEP","1","6","6","Waɗanda suka juya daga bin Ubangiji, ba sa kuma neman Ubangiji ko su nemi nufinsa.” ");
INSERT INTO hausa_vpl VALUES ("ZP1_7","037_1_7","ZEP","1","7","7","Ku yi shiru a gaban Ubangiji Mai Iko Duka, gama ranar Ubangiji ta yi kusa. Ubangiji ya shirya hadaya; ya kuma tsarkake waɗanda ya gayyato. ");
INSERT INTO hausa_vpl VALUES ("ZP1_8","037_1_8","ZEP","1","8","8","“A ranar hadayar Ubangiji zan hukunta sarakuna da kuma ’ya’yan sarakuna da duk waɗanda suke sanye da rigunan ƙasashen waje. ");
INSERT INTO hausa_vpl VALUES ("ZP1_9","037_1_9","ZEP","1","9","9","A wannan rana zan hukunta dukan waɗanda suke kauce taka madogarar ƙofa, waɗanda suke cika haikalin allolinsu da rikici da ruɗu. ");
INSERT INTO hausa_vpl VALUES ("ZP1_10","037_1_10","ZEP","1","10","10","“A wannan rana,” in ji Ubangiji, “Za a ji kuka daga Ƙofar Kifi, kururuwa daga Sabon Mazauni, da kuma amo mai ƙarfi daga tuddai. ");
INSERT INTO hausa_vpl VALUES ("ZP1_11","037_1_11","ZEP","1","11","11","Ku yi kururuwa, ku da kuke zaune a yankin kasuwa; za a hallaka dukan ’yan kasuwanku, dukan waɗanda suke kasuwanci da azurfa za su lalace. ");
INSERT INTO hausa_vpl VALUES ("ZP1_12","037_1_12","ZEP","1","12","12","A wannan lokaci zan bincike Urushalima da fitilu in kuma hukunta waɗanda ba su kula ba, waɗanda suke kamar ruwan inabin da aka bar a ƙasan tukunya, waɗanda suke tsammani, ‘Ubangiji ba zai yi kome ba nagari ko mummuna.’ ");
INSERT INTO hausa_vpl VALUES ("ZP1_13","037_1_13","ZEP","1","13","13","Za a washe dukiyarsu, a rurrushe gidajensu. Za su gina gidaje amma ba za su zauna a ciki ba; za su shuka inabi amma ba za su sha ruwansa ba.” ");
INSERT INTO hausa_vpl VALUES ("ZP1_14","037_1_14","ZEP","1","14","14","Babbar ranar Ubangiji ta yi kusa, ta yi kusa kuma tana zuwa da sauri. Ku saurara! Kukan ranar Ubangiji za tă yi zafi, za a ji kururuwan jarumi a can. ");
INSERT INTO hausa_vpl VALUES ("ZP1_15","037_1_15","ZEP","1","15","15","Ranan nan za tă zama ranar fushi, rana ce ta baƙin ciki da azaba, rana ce ta tashin hankali da lalacewa, ranar duhu baƙi ƙirin, ranar gizagizai da baƙin duhu, ");
INSERT INTO hausa_vpl VALUES ("ZP1_16","037_1_16","ZEP","1","16","16","rana ce ta busa ƙaho da kururuwar yaƙi gāba da birane masu mafaka, da kuma kusurwar hasumiyoyi. ");
INSERT INTO hausa_vpl VALUES ("ZP1_17","037_1_17","ZEP","1","17","17","“Zan kawo baƙin ciki a kan mutane za su kuma yi tafiya kamar makafi, domin sun yi wa Ubangiji zunubi. Za a zubar da jininsu kamar ƙura kayan cikinsu kuma kamar najasa. ");
INSERT INTO hausa_vpl VALUES ("ZP1_18","037_1_18","ZEP","1","18","18","Azurfarsu ko zinariyarsu ba za su iya cetonsu ba a ranar fushin Ubangiji.” A cikin zafin kishinsa za a hallaka dukan duniya gama zai kawo ƙarshen dukan mazaunan duniya nan da nan. ");
INSERT INTO hausa_vpl VALUES ("ZP2_1","037_2_1","ZEP","2","1","1","Ku tattaru, ku tattaru, Ya ku al’umma marar kunya, ");
INSERT INTO hausa_vpl VALUES ("ZP2_2","037_2_2","ZEP","2","2","2","kafin ƙayyadadden lokacin nan yă zo ranan nan kuma ta share ku kamar ƙaiƙayi kuma kafin fushi mai tsanani na Ubangiji yă auko muku, kafin ranar fushin Ubangiji ta auko muku. ");
INSERT INTO hausa_vpl VALUES ("ZP2_3","037_2_3","ZEP","2","3","3","Ku nemi Ubangiji, dukanku ƙasashe masu tawali’u, ku da kuke yin abin da ya umarta. Ku nemi adalci da tawali’u; mai yiwuwa ku sami mafaka a ranar fushin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ZP2_4","037_2_4","ZEP","2","4","4","Za a yashe Gaza a kuma bar Ashkelon kango. Da tsakar rana Ashdod za tă zama babu kowa a kuma tumɓuke Ekron. ");
INSERT INTO hausa_vpl VALUES ("ZP2_5","037_2_5","ZEP","2","5","5","Taku ta ƙare ku da kuke zama a bakin teku, Ya ku mutanen Keretawa; maganar Ubangiji tana gāba da ke, Ya ke Kan’ana, ƙasar Filistiyawa. “Zan hallaka ki kuma babu abin da zai rage.” ");
INSERT INTO hausa_vpl VALUES ("ZP2_6","037_2_6","ZEP","2","6","6","Ƙasar da take a bakin teku, inda Keretawa suke zaune, za tă zama wurin da makiyaya da ta garken tumaki. ");
INSERT INTO hausa_vpl VALUES ("ZP2_7","037_2_7","ZEP","2","7","7","Za tă zama mallakar raguwar gidan Yahuda; a can za su sami wurin kiwo. Da yamma za su kwanta a gidajen Ashkelon. Ubangiji Allahnsu zai lura da su; zai maido musu da martabarsu. ");
INSERT INTO hausa_vpl VALUES ("ZP2_8","037_2_8","ZEP","2","8","8","“Na ji irin zagin da Mowab take yi, da kuma ba’ar Ammonawa, waɗanda suka zagi mutanena suna kuma yi barazana a kan ƙasarsu. ");
INSERT INTO hausa_vpl VALUES ("ZP2_9","037_2_9","ZEP","2","9","9","Saboda haka, muddin ina raye,” in ji Ubangiji Maɗaukaki, Allah na Isra’ila, “tabbatacce Mowab za tă zama kamar Sodom, Ammonawa kuma kamar Gomorra, ƙasa mai ciyayi da rammukan gishiri, ƙasa marar amfani har abada. Raguwar mutanena za su washe su; waɗanda suka rage na al’ummata za su gāda ƙasarsu.” ");
INSERT INTO hausa_vpl VALUES ("ZP2_10","037_2_10","ZEP","2","10","10","Wannan ne zai zama sakamakon girmankansu, saboda zagi da kuma ba’ar da suka yi wa mutanen Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ZP2_11","037_2_11","ZEP","2","11","11","Ubangiji zai zama abin tsoro a gare su sa’ad da ya hallaka allolin ƙasar. Al’ummai a kowane bakin teku za su yi masa sujada, kowa a ƙasarsa. ");
INSERT INTO hausa_vpl VALUES ("ZP2_12","037_2_12","ZEP","2","12","12","“Ku ma, ya Kushawa, za a kashe ku da takobina.” ");
INSERT INTO hausa_vpl VALUES ("ZP2_13","037_2_13","ZEP","2","13","13","Zai kuma miƙa hannunsa gāba da arewa yă kuma hallaka Assuriya, zai mai da Ninebe kango gaba ɗaya ta kuma zama busasshiya kamar hamada. ");
INSERT INTO hausa_vpl VALUES ("ZP2_14","037_2_14","ZEP","2","14","14","Garkuna za su kwanta a can, da kowace irin halitta, Mujiyar hamada da bushiya za su zauna a kan ginshiƙanta. Kukansu za tă ratsa tagogi, ɓuraguzai za su tare ƙofofin shiga, za a kware ginshiƙan al’ul. ");
INSERT INTO hausa_vpl VALUES ("ZP2_15","037_2_15","ZEP","2","15","15","Birnin da yake harka ke nan da take zaune lafiya. Ta ce wa kanta, “Ni ce, kuma babu kamata.” Dubi irin kangon da ta zama mana, mazaunin namun jeji! Duk wanda ya wuce ta sai ya yi mata tsaki yana kaɗa kai. ");
INSERT INTO hausa_vpl VALUES ("ZP3_1","037_3_1","ZEP","3","1","1","Taki ta ƙare, ke birnin mai danniya, mai ’yan tawaye da kuma masu ƙazanta! ");
INSERT INTO hausa_vpl VALUES ("ZP3_2","037_3_2","ZEP","3","2","2","Ba kya yi wa kowa biyayya, ba kya kuma yarda da kuskurenki. Ba kya dogara ga Ubangiji, ba kya kuma kusatowa kusa da Allahnki. ");
INSERT INTO hausa_vpl VALUES ("ZP3_3","037_3_3","ZEP","3","3","3","Sarakunanki ruri ne na zakoki, shugabanninki kyarketan dare ne, waɗanda ba sa rage kome don safe. ");
INSERT INTO hausa_vpl VALUES ("ZP3_4","037_3_4","ZEP","3","4","4","Annabawanki mahaukata ne mutanenki masu cin amana ne. Firistocinki suna ƙazantar da Wurin Mai Tsarki suna kuma keta dokoki. ");
INSERT INTO hausa_vpl VALUES ("ZP3_5","037_3_5","ZEP","3","5","5","Ubangiji da yake cikinki mai adalci ne; ba ya yin abin da ba daidai ba. Kowace safiya yakan bayyana dokokinsa a fili, kowace sabuwar rana kuma ba ya kāsawa, duk da haka marasa adalci ba sa jin kunya. ");
INSERT INTO hausa_vpl VALUES ("ZP3_6","037_3_6","ZEP","3","6","6","“Na daddatse al’ummai; an kuma rurrushe kagararsu. Na bar titunansu ba kowa, ba mai ratsawa a ciki. An ragargaza biranensu; ba wanda za a bari, babu ko ɗaya. ");
INSERT INTO hausa_vpl VALUES ("ZP3_7","037_3_7","ZEP","3","7","7","Na ce wa birnin, ‘Tabbatacce za ki ji tsorona ki kuma yarda da gyara!’ Ta haka ba za a datse wurin zamanki ba, ba kuwa dukan hukuncena za su hau bisa kansu ba. Amma har yanzu suna marmari su yi rashin gaskiya a duk abin da suke yi. ");
INSERT INTO hausa_vpl VALUES ("ZP3_8","037_3_8","ZEP","3","8","8","Saboda haka ku jira ni,” in ji Ubangiji; “a ranar da zan tsaya in ba da shaida, Na yanke shawara in tattara dukan al’ummai, in tattara mulkoki in kuma zuba fushina a kansu, da dukan zafin haushina. Za a mamaye dukan duniya da zafin fushina. ");
INSERT INTO hausa_vpl VALUES ("ZP3_9","037_3_9","ZEP","3","9","9","“Sa’an nan zan tsarkake leɓunan mutanen, don dukansu su kira bisa ga sunan Ubangiji su kuma yi masa hidima kafaɗa da kafaɗa. ");
INSERT INTO hausa_vpl VALUES ("ZP3_10","037_3_10","ZEP","3","10","10","Tun daga ƙetaren rafuffukan Kush masu yi mini sujada, mutanena da suke a warwatse, za su kawo mini hadayu. ");
INSERT INTO hausa_vpl VALUES ("ZP3_11","037_3_11","ZEP","3","11","11","A wannan rana ba za ku sha kunya saboda laifofin da kuka yi mini, gama zan ɗauke wa wannan birni waɗanda suke farin ciki cikin girmankansu. Ba kuma za ka ƙara yin kallon reni a tuduna mai tsarki ba. ");
INSERT INTO hausa_vpl VALUES ("ZP3_12","037_3_12","ZEP","3","12","12","Amma zan zauna a cikinki masu tawali’u da masu ƙasƙantar da kai, waɗanda suke dogara ga sunan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ZP3_13","037_3_13","ZEP","3","13","13","Raguwar Isra’ila ba za su ƙara aikata abin da ba daidai ba, ba za su faɗa ƙarya ba, ba kuwa za a sami ruɗu a bakunansu ba. Za su ci su kuma kwanta kuma babu wanda zai ba su tsoro.” ");
INSERT INTO hausa_vpl VALUES ("ZP3_14","037_3_14","ZEP","3","14","14","Ki rera, ya Diyar Sihiyona; ki tā da murya, ya Isra’ila! Ki yi murna ki kuma yi farin ciki da dukan zuciyarki, Ya Diyar Urushalima! ");
INSERT INTO hausa_vpl VALUES ("ZP3_15","037_3_15","ZEP","3","15","15","Ubangiji ya ɗauke hukuncinki, ya mai da abokan gābanki baya. Ubangiji, Sarkin Isra’ila, yana tare da ke; ba kuma za ki ƙara jin tsoron wani lahani ba. ");
INSERT INTO hausa_vpl VALUES ("ZP3_16","037_3_16","ZEP","3","16","16","A wannan rana za su cewa Urushalima, “Kada ki ji tsoro, ya Sihiyona; kada ki bar hannuwanki su raunana. ");
INSERT INTO hausa_vpl VALUES ("ZP3_17","037_3_17","ZEP","3","17","17","Ubangiji Allahnki yana tare da ke, mai iko ne don ceto. Zai yi matuƙar farin ciki da ke, zai rufe ki da ƙaunarsa, zai yi farin ciki da ke ta wurin rerawa.” ");
INSERT INTO hausa_vpl VALUES ("ZP3_18","037_3_18","ZEP","3","18","18","“Zan cire taƙaici daga gare ki a ƙayyadaddun bukukkuwa; su kaya ne da kuma zargi a gare ki. ");
INSERT INTO hausa_vpl VALUES ("ZP3_19","037_3_19","ZEP","3","19","19","A wannan lokaci zan jijji wa waɗanda suka danne ku; zan kuɓutar da guragu in kuma tattara waɗanda suke a warwatse. Zan sa a yabe su a kuma girmama su a kowace ƙasar da aka kunyatar da su. ");
INSERT INTO hausa_vpl VALUES ("ZP3_20","037_3_20","ZEP","3","20","20","A wannan lokaci zan tattara ku; a wannan lokaci zan kawo ku gida, zan sa a yabe ku a kuma girmama ku a cikin dukan mutanen duniya a sa’ad da na maido da arzikinku a idanunku,” in ji Ubangiji.");
INSERT INTO hausa_vpl VALUES ("HG1_1","038_1_1","HAG","1","1","1","A shekara ta biyu ta mulkin Sarki Dariyus, a rana ta fari ga watan shida, maganar Ubangiji ta zo ta wurin annabi Haggai zuwa ga Zerubbabel ɗan Sheyaltiyel, gwamnan Yahuda, da kuma Yoshuwa ɗan Yehozadak, babban firist. ");
INSERT INTO hausa_vpl VALUES ("HG1_2","038_1_2","HAG","1","2","2","Ga abin da Ubangiji Maɗaukaki ya ce, “Waɗannan mutane sun ce, ‘Lokaci bai yi ba tukuna da za a gina gidan Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("HG1_3","038_1_3","HAG","1","3","3","Sa’an nan maganar Ubangiji ta zo ta wurin annabi Haggai cewa, ");
INSERT INTO hausa_vpl VALUES ("HG1_4","038_1_4","HAG","1","4","4","“Ashe, lokaci ya yi da za ku zauna a ɗakunan da kuka yi da rufin katako, amma haikalin nan yana zaman kufai?” ");
INSERT INTO hausa_vpl VALUES ("HG1_5","038_1_5","HAG","1","5","5","To, ga abin da Ubangiji Maɗaukaki ya ce, “Ku lura da al’amuranku. ");
INSERT INTO hausa_vpl VALUES ("HG1_6","038_1_6","HAG","1","6","6","Kun shuka da yawa, amma kun girbe kaɗan. Kun ci, amma ba ku ƙoshi ba. Kun sha, amma ba ku kashe ƙishirwa ba. Kun sa tufafi, amma ba ku ji ɗumi ba. Kuna karɓar albashi, ya zama sai ka ce kuna zuba a hudajjen aljihu.” ");
INSERT INTO hausa_vpl VALUES ("HG1_7","038_1_7","HAG","1","7","7","Ga abin da Ubangiji Maɗaukaki ya ce, “Ku lura da al’amuranku. ");
INSERT INTO hausa_vpl VALUES ("HG1_8","038_1_8","HAG","1","8","8","Ku haura zuwa kan duwatsu ku sauko da katakai don ku gina gidan, don ni ma in ji daɗinsa, in kuma sami ɗaukaka,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("HG1_9","038_1_9","HAG","1","9","9","“Ga shi, kukan sa rai za ku sami da yawa, amma sai ku ga kun sami kaɗan. Ɗan kaɗan ɗin ma da kukan kawo gida, nakan hura shi yă tafi. Me ya sa yake faruwa haka?” In ji Ubangiji Maɗaukaki. “Saboda gidana da yake zaman kango, yayinda kowannenku yana faman gina gidansa. ");
INSERT INTO hausa_vpl VALUES ("HG1_10","038_1_10","HAG","1","10","10","Shi ya sa, saboda ku sammai sun ƙi saukar da raɓa, ƙasa kuma ta ƙi ba da amfani. ");
INSERT INTO hausa_vpl VALUES ("HG1_11","038_1_11","HAG","1","11","11","Na kawo fări a ƙasar, da a kan duwatsu, da a kan hatsi, da a kan dukan abin da yake tsirowa daga ƙasa, da a kan mutane, da a kan dabbobi da kuma a kan wahalar hannuwanku.” ");
INSERT INTO hausa_vpl VALUES ("HG1_12","038_1_12","HAG","1","12","12","Sa’an nan sai Zerubbabel ɗan Sheyaltiyel, da Yoshuwa ɗan Yehozadak, wanda yake babban firist, da kuma dukan raguwar jama’ar suka yi biyayya da muryar Ubangiji Allahnsu da kuma saƙon annabi Haggai, domin Ubangiji Allahnsu ne ya aiko shi. Mutane kuwa suka ji tsoron Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("HG1_13","038_1_13","HAG","1","13","13","Sai Haggai, ɗan saƙon Ubangiji, ya ba da wannan saƙo na Ubangiji ga mutane cewa, “Ina tare da ku” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("HG1_14","038_1_14","HAG","1","14","14","Saboda haka Ubangiji ya motsa zuciyar Zerubbabel ɗan Sheyaltiyel, wanda yake gwamna a Yahuda, da kuma zuciyar Yoshuwa ɗan Yehozadak, babban firist, da kuma zukatan dukan raguwar jama’ar. Suka zo suka fara aiki a gidan Ubangiji Maɗaukaki, Allahnsu, ");
INSERT INTO hausa_vpl VALUES ("HG1_15","038_1_15","HAG","1","15","15","a ranar ashirin da huɗu ga watan shida. A shekara ta biyu ta mulkin Sarki Dariyus, ");
INSERT INTO hausa_vpl VALUES ("HG2_1","038_2_1","HAG","2","1","1","a ranar ashirin da ɗaya ga watan bakwai, maganar Ubangiji ta zo ta wurin annabi Haggai cewa, ");
INSERT INTO hausa_vpl VALUES ("HG2_2","038_2_2","HAG","2","2","2","“Ka yi magana da Zerubbabel ɗan Sheyaltiyel wanda yake gwamna a Yahuda, da Yoshuwa ɗan Yehozadak, babban firist, da kuma dukan raguwar mutane. Ka tambaye su ka ce, ");
INSERT INTO hausa_vpl VALUES ("HG2_3","038_2_3","HAG","2","3","3","‘Wane ne a cikinku ya ragu da ya ga wannan gida a darajarsa ta dā? Yaya yake a gare ku a yanzu? Bai yi kamar a bakin kome ba, ko ba haka ba? ");
INSERT INTO hausa_vpl VALUES ("HG2_4","038_2_4","HAG","2","4","4","Amma yanzu ka ƙarfafa, ya Zerubbabel,’ in ji Ubangiji. ‘Ka ƙarfafa, ya Yoshuwa ɗan Yehozadak, babban firist. Ku ƙarfafa, dukanku mutanen ƙasar,’ in ji Ubangiji, ‘ku yi aiki. Gama ina tare da ku,’ in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("HG2_5","038_2_5","HAG","2","5","5","‘Wannan shi ne alkawarin da na yi da ku a lokacin da kuka fito daga Masar. Ruhuna kuwa yana tare da ku. Kada ku ji tsoro.’ ");
INSERT INTO hausa_vpl VALUES ("HG2_6","038_2_6","HAG","2","6","6","“Ga abin da Ubangiji Maɗaukaki ya ce, ‘Ba da jimawa ba zan sāke girgiza sammai da kuma ƙasa, teku da busasshiyar ƙasa. ");
INSERT INTO hausa_vpl VALUES ("HG2_7","038_2_7","HAG","2","7","7","Zan girgiza dukan al’ummai, marmarin kowace al’umma kuma zai taso, sa’an nan zan cika gidan nan da ɗaukaka,’ in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("HG2_8","038_2_8","HAG","2","8","8","‘Da zinariya da azurfa duka nawa ne,’ in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("HG2_9","038_2_9","HAG","2","9","9","‘Ɗaukakar gidan nan na yanzu za tă fi ɗaukakar gidan nan na dā,’ in ji Ubangiji Maɗaukaki. ‘A wannan wuri kuma zan ba da salama,’ in ji Ubangiji Maɗaukaki.” ");
INSERT INTO hausa_vpl VALUES ("HG2_10","038_2_10","HAG","2","10","10","A ranar ashirin da huɗu ga watan tara, a shekara ta biyu ta mulkin Dariyus, maganar Ubangiji ta zo wa annabi Haggai cewa, ");
INSERT INTO hausa_vpl VALUES ("HG2_11","038_2_11","HAG","2","11","11","“Ga abin da Ubangiji Maɗaukaki ya ce, ‘Ku tambayi firist abin da doka ta ce. ");
INSERT INTO hausa_vpl VALUES ("HG2_12","038_2_12","HAG","2","12","12","Idan mutum yana riƙe da naman da aka keɓe a rigarsa, sa’an nan kuma wannan rigar ta taɓa burodi, ko dafaffen abinci, ko ruwan inabi, ko mai, ko kowane irin abinci, wannan zai sa abin yă zama tsarkake?’ ” Firistoci suka amsa, suka ce, “A’a.” ");
INSERT INTO hausa_vpl VALUES ("HG2_13","038_2_13","HAG","2","13","13","Sa’an nan Haggai ya ce, “In mutumin da ya ƙazantar da kansa ta wurin taɓa gawa, ya taɓa wani daga cikin waɗannan abubuwa, za su ƙazantu?” Firistoci suka amsa, suka ce, “I, zai ƙazantu.” ");
INSERT INTO hausa_vpl VALUES ("HG2_14","038_2_14","HAG","2","14","14","Sai annabi Haggai ya ce, “ ‘Haka yake da wannan mutane da kuma wannan al’umma a gabana,’ in ji Ubangiji. ‘Duk abin da suke yi da kuma dukan abin da suke miƙawa ƙazantattu ne. ");
INSERT INTO hausa_vpl VALUES ("HG2_15","038_2_15","HAG","2","15","15","“ ‘Yanzu kuwa sai ku yi la’akari da wannan daga wannan rana zuwa gaba, ku tuna yadda al’amura suke kafin a ɗora wani dutse bisa wani a haikalin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("HG2_16","038_2_16","HAG","2","16","16","A lokacin, idan wani ya tafi wurin tsibin da zai auna mudu ashirin, sai yă iske mudu goma kawai. Idan kuma wani ya tafi wurin matse ruwan inabi don yă ɗebo lita hamsin, sai yă tarar da lita ashirin kawai. ");
INSERT INTO hausa_vpl VALUES ("HG2_17","038_2_17","HAG","2","17","17","Na mai da aikin da kuka sha wahala kuka yi ya zama banza ta wurin saukar da burtuntuna, da fumfuna, da ƙanƙara, duk da haka ba ku juyo gare ni ba,’ in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("HG2_18","038_2_18","HAG","2","18","18","‘Daga wannan rana zuwa gaba, wato, rana ta ashirin da huɗu ga watan tara, ku lura da ranar da aka kafa harsashin haikalin Ubangiji. Ku lura da kyau. ");
INSERT INTO hausa_vpl VALUES ("HG2_19","038_2_19","HAG","2","19","19","Akwai sauran irin da ya rage a rumbu? Har yanzu, kuringar inabi da itacen ɓaure, rumman da itacen zaitun ba su ba da ’ya’ya ba tukuna. “ ‘Amma daga wannan rana zuwa gaba zan sa muku albarka.’ ” ");
INSERT INTO hausa_vpl VALUES ("HG2_20","038_2_20","HAG","2","20","20","Maganar Ubangiji ta zo wa annabi Haggai sau na biyu a rana ta ashirin da huɗu ga wata cewa, ");
INSERT INTO hausa_vpl VALUES ("HG2_21","038_2_21","HAG","2","21","21","“Ka faɗa wa Zerubbabel gwamnan Yahuda cewa zan girgiza sammai da ƙasa. ");
INSERT INTO hausa_vpl VALUES ("HG2_22","038_2_22","HAG","2","22","22","Zan hamɓarar da gadajen mulki in kuma ragargaza ƙarfin ƙasashen al’ummai. Zan tumɓuke kekunan yaƙi da mahayansu; dawakai da mahayansu za su mutu, kowane ta wurin takobin ɗan’uwansu. ");
INSERT INTO hausa_vpl VALUES ("HG2_23","038_2_23","HAG","2","23","23","“ ‘A wannan rana,’ in ji Ubangiji Maɗaukaki, ‘Zan ɗauke ka, bawana Zerubbabel ɗan Sheyaltiyel,’ in ji Ubangiji, ‘in kuma maishe ka kamar zoben hatimi, gama na zaɓe ka,’ in ji Ubangiji Maɗaukaki.”");
INSERT INTO hausa_vpl VALUES ("ZC1_1","039_1_1","ZEC","1","1","1","A wata na bakwai na shekara ta biyu ta mulkin Dariyus, maganar Ubangiji ta zo wa annabi Zakariya ɗan Berekiya ɗan Iddo. ");
INSERT INTO hausa_vpl VALUES ("ZC1_2","039_1_2","ZEC","1","2","2","“Ubangiji ya yi fushi sosai da kakanninku. ");
INSERT INTO hausa_vpl VALUES ("ZC1_3","039_1_3","ZEC","1","3","3","Saboda haka ka gaya wa mutanen, ga abin da Ubangiji Maɗaukaki ya ce, ‘Ku komo gare ni,’ in ji Ubangiji Maɗaukaki, ‘ni kuma zan komo gare ku,’ in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ZC1_4","039_1_4","ZEC","1","4","4","Kada ku zama kamar kakanninku, waɗanda annabawa na dā suka ce musu, ga abin da Ubangiji Maɗaukaki ya ce, ‘Ku juya daga mugayen hanyoyinku da mugayen abubuwan da kuke yi.’ Amma ba su saurara ba, ko ma su kula da ni, in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ZC1_5","039_1_5","ZEC","1","5","5","Yanzu ina kakanninku suke? Annabawan kuma fa, sun rayu har abada ne? ");
INSERT INTO hausa_vpl VALUES ("ZC1_6","039_1_6","ZEC","1","6","6","Amma maganata da dokokina da na umarta ta wurin bayina annabawa fa, ashe, ba su tabbata ba a kan kakanninku? “Sa’an nan suka tuba suka ce, ‘Ubangiji Maɗaukaki ya yi mana daidai abin da hanyoyinmu suka cancanci mu samu, kamar dai yadda ya yi niyya yi.’ ” ");
INSERT INTO hausa_vpl VALUES ("ZC1_7","039_1_7","ZEC","1","7","7","7-8 A rana ta ashirin da huɗu ga watan goma sha ɗaya, wato, watan Shebat, a shekara ta biyu ta Dariyus, maganar Ubangiji ta zo wa annabi Zakariya ɗan Berekiya ɗan Iddo. ");
INSERT INTO hausa_vpl VALUES ("ZC1_8","039_1_8","ZEC","1","8","8","Da dare, na ga wahayi, a gabana kuwa ga mutum a kan jan doki! Yana tsaye a cikin itatuwa masu furanni, a bayansa a cikin itatuwan ci-zaƙi, a bayansa kuwa akwai dawakai masu ruwan ja, ruwan ƙasa-ƙasa da kuma ruwan fari. ");
INSERT INTO hausa_vpl VALUES ("ZC1_9","039_1_9","ZEC","1","9","9","Sai na yi tambaya na ce, “Mene ne waɗannan ranka yă daɗe?” Mala’ikan da yake magana da ni ya amsa ya ce, “Zan nuna maka mene ne su.” ");
INSERT INTO hausa_vpl VALUES ("ZC1_10","039_1_10","ZEC","1","10","10","Sai mutumin da yake tsaye cikin itatuwan ci-zaƙin ya yi bayani cewa, “Su ne waɗanda Ubangiji ya aika ko’ina a duniya.” ");
INSERT INTO hausa_vpl VALUES ("ZC1_11","039_1_11","ZEC","1","11","11","Sai suka ce wa mala’ikan da yake tsaye cikin itatuwan ci-zaƙin, “Mun ratsa ko’ina a duniya, sai muka ga duniya duka tana zaman lafiya.” ");
INSERT INTO hausa_vpl VALUES ("ZC1_12","039_1_12","ZEC","1","12","12","Sa’an nan mala’ikan Ubangiji ya ce, “Ya Ubangiji Maɗaukaki, har yaushe za ka ci gaba da ƙi nuna wa Urushalima da kuma garuruwan Yahuda jinƙai, waɗanda kake fushi da su shekarun nan saba’in?” ");
INSERT INTO hausa_vpl VALUES ("ZC1_13","039_1_13","ZEC","1","13","13","Sai Ubangiji ya yi wa mala’ikan da ya yi magana da ni magana da kalmomi masu daɗi da kuma masu ta’azantarwa. ");
INSERT INTO hausa_vpl VALUES ("ZC1_14","039_1_14","ZEC","1","14","14","Sai mala’ikan da yake magana da ni ya ce, “Ka yi shelar maganan nan, ga abin da Ubangiji Maɗaukaki ya ce, ‘Ina kishi domin Urushalima da Sihiyona, ");
INSERT INTO hausa_vpl VALUES ("ZC1_15","039_1_15","ZEC","1","15","15","amma ina fushi da ƙasashen da suke ji suna zaman lafiya, na ɗan yi fushina kawai, amma sai suka ƙara musu masifar.’ ");
INSERT INTO hausa_vpl VALUES ("ZC1_16","039_1_16","ZEC","1","16","16","“Saboda haka, ga abin da Ubangiji ya ce, ‘Zan komo Urushalima da jinƙai, a can ne za a sāke gina gidana. Za a kuma miƙe ma’auni a bisa Urushalima,’ in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ZC1_17","039_1_17","ZEC","1","17","17","“Ci gaba da yin shela, ga abin da Ubangiji Maɗaukaki ya ce, ‘Garuruwana za su sāke kwarara da wadata, Ubangiji kuma zai sāke yi wa Sihiyona ta’aziyya, yă kuma zaɓi Urushalima.’ ” ");
INSERT INTO hausa_vpl VALUES ("ZC1_18","039_1_18","ZEC","1","18","18","Sa’an nan na dubi sama a gabana kuwa sai ga ƙahoni huɗu! ");
INSERT INTO hausa_vpl VALUES ("ZC1_19","039_1_19","ZEC","1","19","19","Na tambayi mala’ikan da yake mini magana, na ce, “Mene ne waɗannan?” Ya amsa mini ya ce, “Waɗannan su ne ƙahonin da suka watsar da Yahuda, Isra’ila da kuma Urushalima.” ");
INSERT INTO hausa_vpl VALUES ("ZC1_20","039_1_20","ZEC","1","20","20","Sa’an nan Ubangiji ya nuna mini maƙera guda huɗu. ");
INSERT INTO hausa_vpl VALUES ("ZC1_21","039_1_21","ZEC","1","21","21","Na yi tambaya na ce, “Mene ne waɗannan suke zuwa yi?” Ya amsa ya ce, “Waɗannan ne ƙahonin da suka watsar da Yahuda har ba wanda yake iya ɗaga kansa, amma maƙeran sun zo don su tsorata su su kuma saukar da ƙahonin ƙasashen nan waɗanda suka ɗaga ƙahoninsu gāba da ƙasar Yahuda don su warwatsa ta.” ");
INSERT INTO hausa_vpl VALUES ("ZC2_1","039_2_1","ZEC","2","1","1","Sa’an nan na ɗaga kai sai na ga mutum a tsaye riƙe da ma’auni a hannunsa! ");
INSERT INTO hausa_vpl VALUES ("ZC2_2","039_2_2","ZEC","2","2","2","Sai na yi tambaya, na ce, “Ina za ka?” Ya amsa mini ya ce, “Zan je in auna Urushalima, in ga yadda fāɗinta da tsawonta suke.” ");
INSERT INTO hausa_vpl VALUES ("ZC2_3","039_2_3","ZEC","2","3","3","Sai mala’ikan da yake yi mini magana ya tafi, sai wani mala’ika ya zo ya same shi ");
INSERT INTO hausa_vpl VALUES ("ZC2_4","039_2_4","ZEC","2","4","4","ya ce masa, “Yi gudu, gaya wa saurayin can cewa, ‘Urushalima za tă zama birni marar katanga domin mutane da dabbobi masu yawa ƙwarai za su kasance a cikinta. ");
INSERT INTO hausa_vpl VALUES ("ZC2_5","039_2_5","ZEC","2","5","5","Ni da kaina ne zan zama katangar wuta kewaye da birnin, in kuma zama darajarta,’ in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ZC2_6","039_2_6","ZEC","2","6","6","“Zo! Zo! Ku gudu daga ƙasar arewa,” in ji Ubangiji, “gama na warwatsa ku a kusurwoyi huɗu na sama,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ZC2_7","039_2_7","ZEC","2","7","7","“Zo, ya ke Sihiyona! Ku tsere, ku masu zama a cikin Diyar Babilon!” ");
INSERT INTO hausa_vpl VALUES ("ZC2_8","039_2_8","ZEC","2","8","8","Gama ga abin da Ubangiji Maɗaukaki ya ce, “Bayan ya ɗaukaka ni, ya kuma aiko ni ga ƙasashen da suka washe ku gama duk wanda ya taɓa ku ya taɓa ƙwayar idonsa ne. ");
INSERT INTO hausa_vpl VALUES ("ZC2_9","039_2_9","ZEC","2","9","9","Ba shakka zan tā da hannuna a kansu domin bayinsu su washe su. Sa’an nan za ku san cewa Ubangiji Maɗaukaki ne ya aiko ni. ");
INSERT INTO hausa_vpl VALUES ("ZC2_10","039_2_10","ZEC","2","10","10","“Ki yi sowa ki yi murna, ya ke Diyar Sihiyona. Gama ina zuwa, zan zauna a cikinki,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ZC2_11","039_2_11","ZEC","2","11","11","“Ƙasashe da yawa za su haɗa kai da Ubangiji a ranan nan, za su kuma zama mutanena. Zan zauna a cikinku, za ku kuma san cewa Ubangiji Maɗaukaki ne ya aiko ni gare ku. ");
INSERT INTO hausa_vpl VALUES ("ZC2_12","039_2_12","ZEC","2","12","12","Ubangiji zai gāji Yahuda a matsayin rabonsa a cikin ƙasa mai tsarki zai kuma sāke zaɓi Urushalima. ");
INSERT INTO hausa_vpl VALUES ("ZC2_13","039_2_13","ZEC","2","13","13","Ku yi tsit a gaban Ubangiji, dukanku ’yan adam, gama ya taso daga wurin zamansa mai tsarki.” ");
INSERT INTO hausa_vpl VALUES ("ZC3_1","039_3_1","ZEC","3","1","1","Sa’an nan ya nuna mini Yoshuwa babban firist a tsaye a gaban mala’ikan Ubangiji, Shaiɗan kuma yana tsaye a damansa don yă tuhume shi. ");
INSERT INTO hausa_vpl VALUES ("ZC3_2","039_3_2","ZEC","3","2","2","Ubangiji ya ce wa Shaiɗan, “Ubangiji ya tsawata maka, Shaiɗan! Ubangiji wanda ya zaɓi Urushalima, ya tsawata maka! Ashe, mutumin nan ba shi ne sandar da take ƙonewa da aka ciro daga cikin wuta ba?” ");
INSERT INTO hausa_vpl VALUES ("ZC3_3","039_3_3","ZEC","3","3","3","Yanzu an sa wa Yoshuwa tufafi masu dauda sa’ad da yake tsaye a gaban mala’ikan. ");
INSERT INTO hausa_vpl VALUES ("ZC3_4","039_3_4","ZEC","3","4","4","Mala’ikan ya ce wa waɗanda suke tsaye a gabansa, “Ku cire masa tufafinsa masu dauda.” Sai ya ce wa Yoshuwa, “Duba, na ɗauke zunubanka, zan sa maka tufafi masu tsada.” ");
INSERT INTO hausa_vpl VALUES ("ZC3_5","039_3_5","ZEC","3","5","5","Sai na ce, “Sa masa rawani mai tsabta a kansa.” Aka sa masa rawani mai tsabta a kansa aka kuma sa masa tufafi yayinda mala’ikan Ubangiji yake tsaye a wurin. ");
INSERT INTO hausa_vpl VALUES ("ZC3_6","039_3_6","ZEC","3","6","6","Mala’ikan Ubangiji ya yi wa Yoshuwa wannan gargaɗi. ");
INSERT INTO hausa_vpl VALUES ("ZC3_7","039_3_7","ZEC","3","7","7","“Ga abin da Ubangiji Maɗaukaki ya ce, ‘In za ka yi tafiya a hanyoyina ka kuma kiyaye abubuwan da nake so, za ka zama shugaban haikalina, ka kuma lura da ɗakunan shari’ata, zan kuma ba ka wuri cikin waɗannan da suke tsaye a nan. ");
INSERT INTO hausa_vpl VALUES ("ZC3_8","039_3_8","ZEC","3","8","8","“ ‘Ka saurara, ya babban firist Yoshuwa, kai da abokanka da suke zaune a gabanka, ku da kuke alamun abubuwan da za su zo. Zan kawo bawana, wanda yake Reshe. ");
INSERT INTO hausa_vpl VALUES ("ZC3_9","039_3_9","ZEC","3","9","9","Dubi dutsen da na ajiye a gaban Yoshuwa! Akwai idanu bakwai a kan wannan dutse guda, zan kuma yi rubutu a kansa,’ in ji Ubangiji Maɗaukaki, ‘zan kuma kawar da zunubin ƙasan nan a rana ɗaya. ");
INSERT INTO hausa_vpl VALUES ("ZC3_10","039_3_10","ZEC","3","10","10","“ ‘A wannan rana kowannenku zai gayyaci maƙwabcinsa yă zauna a ƙarƙashin itacen inabi da kuma na ɓaure,’ in ji Ubangiji Maɗaukaki.” ");
INSERT INTO hausa_vpl VALUES ("ZC4_1","039_4_1","ZEC","4","1","1","Sai mala’ikan da ya yi magana da ni ya komo ya farkar da ni, kamar yadda ake farkar da mutum daga barcinsa. ");
INSERT INTO hausa_vpl VALUES ("ZC4_2","039_4_2","ZEC","4","2","2","Ya tambaye ni ya ce, “Me ka gani?” Na amsa, na ce, “Na ga wurin ajiye fitilan zinariya da kwano a kai, da kuma fitilu bakwai a kansa, da butocin kai wa fitilu mai guda bakwai. ");
INSERT INTO hausa_vpl VALUES ("ZC4_3","039_4_3","ZEC","4","3","3","Akwai kuma itatuwan zaitun guda biyu a gefensa, ɗaya a gefen dama na kwanon ɗaya kuma a gefen hagunsa.” ");
INSERT INTO hausa_vpl VALUES ("ZC4_4","039_4_4","ZEC","4","4","4","Na tambayi mala’ikan da ya yi magana da ni na ce, “Mene ne waɗannan, ranka yă daɗe?” ");
INSERT INTO hausa_vpl VALUES ("ZC4_5","039_4_5","ZEC","4","5","5","Sai ya amsa ya ce, “Ba ka san mene ne waɗannan ba?” Na amsa, na ce, “A’a, ranka yă daɗe.” ");
INSERT INTO hausa_vpl VALUES ("ZC4_6","039_4_6","ZEC","4","6","6","Sai ya ce mini, “Wannan ce maganar Ubangiji ga Zerubbabel. ‘Ba ta wurin ƙarfi ba, ko ta wurin iko, sai dai ta wurin Ruhuna,’ in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ZC4_7","039_4_7","ZEC","4","7","7","“Kai mene ne, ya babban dutse? A gaban Zerubbabel za a rushe ka ka zama fili. Sa’an nan Zerubbabel yă kawo dutsen da ya fi kyau, a kuma yi ta sowa ana cewa, ‘Allah yă yi masa albarka! Allah yă yi masa albarka!’ ” ");
INSERT INTO hausa_vpl VALUES ("ZC4_8","039_4_8","ZEC","4","8","8","Sai maganar Ubangiji ta zo mini, ");
INSERT INTO hausa_vpl VALUES ("ZC4_9","039_4_9","ZEC","4","9","9","“Hannuwan Zerubbabel sun kafa harsashin haikalin nan; hannuwansa ne kuma za su gama ginin. Sa’an nan ne za ka san cewa Ubangiji Maɗaukaki ne ya aiko ni zuwa wurinka. ");
INSERT INTO hausa_vpl VALUES ("ZC4_10","039_4_10","ZEC","4","10","10","“Wa ya rena ranar ƙananan abubuwa? Mutane za su yi murna sa’ad da suka ga igiyar gwaji a hannun Zerubbabel. “Waɗannan guda bakwai ɗin su ne idanun Ubangiji, masu jujjuyawa cikin dukan duniya.” ");
INSERT INTO hausa_vpl VALUES ("ZC4_11","039_4_11","ZEC","4","11","11","Sai na tambaye shi na ce, “Mene ne waɗannan itatuwan zaitun guda biyu tsaye a hagu da kuma daman wurin ajiye fitilan fitilu?” ");
INSERT INTO hausa_vpl VALUES ("ZC4_12","039_4_12","ZEC","4","12","12","Na sāke tambaye shi na ce, “Mene ne waɗannan rassa biyun nan na zaitun a gefen bututu biyu na zinariya da suke zuba man zinariya?” ");
INSERT INTO hausa_vpl VALUES ("ZC4_13","039_4_13","ZEC","4","13","13","Ya amsa ya ce, “Ba ka san mene ne waɗannan ba?” Na ce, “A’a, ranka yă daɗe.” ");
INSERT INTO hausa_vpl VALUES ("ZC4_14","039_4_14","ZEC","4","14","14","Sai ya ce, “Waɗannan su ne biyun da aka shafe don su yi wa Ubangiji dukan duniya hidima.” ");
INSERT INTO hausa_vpl VALUES ("ZC5_1","039_5_1","ZEC","5","1","1","Na sāke dubawa sai ga naɗaɗɗen littafi mai firiya a gabana! ");
INSERT INTO hausa_vpl VALUES ("ZC5_2","039_5_2","ZEC","5","2","2","Sai ya tambaye ni ya ce, “Me ka gani?” Sai na amsa na ce, “Na ga naɗaɗɗen littafi mai firiya, tsawonsa ƙafa talatin da fāɗinsa kuma ƙafa goma sha biyar.” ");
INSERT INTO hausa_vpl VALUES ("ZC5_3","039_5_3","ZEC","5","3","3","Sai ya ce mini, “Wannan ce la’anar da za tă ratsa dukan ƙasar; gama bisa ga abin da ya ce a gefe ɗaya, za a kawar da kowane ɓarawo, kuma bisa ga abin da ya ce a ɗaya gefen za a kawar da duk mai rantsuwar ƙarya. ");
INSERT INTO hausa_vpl VALUES ("ZC5_4","039_5_4","ZEC","5","4","4","Ubangiji Maɗaukaki ya ce, ‘Zan aika shi, zai shiga gidan ɓarawo, da gidan mai rantsuwar ƙarya da sunana. Zai kasance a gidansa yă hallaka gidan da katakon da duwatsun.’ ” ");
INSERT INTO hausa_vpl VALUES ("ZC5_5","039_5_5","ZEC","5","5","5","Sai mala’ikan da yake mini magana ya zo gaba ya ce mini, “Duba ka gani ko mene ne wannan da yake fitowa.” ");
INSERT INTO hausa_vpl VALUES ("ZC5_6","039_5_6","ZEC","5","6","6","Na tambaya na ce, “Mene ne?” Ya amsa ya ce, “Kwando ne na awo.” Ya ƙara da cewa, “Wannan shi ne laifin mutanen a duk fāɗin ƙasar.” ");
INSERT INTO hausa_vpl VALUES ("ZC5_7","039_5_7","ZEC","5","7","7","Sa’an nan aka ɗaga murfin dalman, a ciki kuwa ga mace zaune! ");
INSERT INTO hausa_vpl VALUES ("ZC5_8","039_5_8","ZEC","5","8","8","Ya ce, “Wannan mugunta ce,” ya kuma tura ta cikin kwandon ya rufe da murfin dalman, ya kuma danna da dutse. ");
INSERT INTO hausa_vpl VALUES ("ZC5_9","039_5_9","ZEC","5","9","9","Na ɗaga idona sama, sai ga mata biyu a gabana, iska tana hura fikafikansu! Suna da fikafikai kamar na shamuwa, suka kuma ɗaga kwandon sama. ");
INSERT INTO hausa_vpl VALUES ("ZC5_10","039_5_10","ZEC","5","10","10","Na tambayi mala’ikan da yake magana da ni na ce, “Ina za ku kai kwandon?” ");
INSERT INTO hausa_vpl VALUES ("ZC5_11","039_5_11","ZEC","5","11","11","Ya amsa ya ce, “Zuwa ƙasar Babiloniya don a gina masa haikali. Sa’ad da aka gama ginin, za a ajiye shi a ciki.” ");
INSERT INTO hausa_vpl VALUES ("ZC6_1","039_6_1","ZEC","6","1","1","Na sāke ɗaga kai sama, sai ga kekunan yaƙi guda huɗu a gabana suna fitowa tsakanin duwatsu guda biyu, duwatsun tagulla! ");
INSERT INTO hausa_vpl VALUES ("ZC6_2","039_6_2","ZEC","6","2","2","Karusa ta farko tana da jajjayen dawakai, ta biyu kuma baƙaƙen dawakai, ");
INSERT INTO hausa_vpl VALUES ("ZC6_3","039_6_3","ZEC","6","3","3","ta ukun farare dawakai, ta huɗu kuma dawakai masu ɗigo-ɗigo a dukan jikinsu, dukansu kuwa ƙarfafa. ");
INSERT INTO hausa_vpl VALUES ("ZC6_4","039_6_4","ZEC","6","4","4","Sai na tambayi mala’ikan da yake magana da ni na ce, “Mene ne waɗannan, ranka yă daɗe?” ");
INSERT INTO hausa_vpl VALUES ("ZC6_5","039_6_5","ZEC","6","5","5","Mala’ikan ya amsa mini ya ce, “Waɗannan su ne ruhohi huɗu na sama, waɗanda suka fito daga wurin Ubangiji na dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("ZC6_6","039_6_6","ZEC","6","6","6","Wannan mai baƙaƙen dawakai zai nufi wajen ƙasar arewa, mai fararen dawakai zai nufi wajen yamma, sai kuma mai dawakai masu ɗigo-ɗigo a jiki zai nufi wajen kudu.” ");
INSERT INTO hausa_vpl VALUES ("ZC6_7","039_6_7","ZEC","6","7","7","Da ƙarfafa dawakan suka fito, sai suka yi marmari su ratsa dukan duniya. Sai ya ce, “Ku ratsa dukan duniya!” Saboda haka suka ratsa dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("ZC6_8","039_6_8","ZEC","6","8","8","Sai ya kira ni ya ce, “Duba, waɗanda suka nufi wajen ƙasar arewa sun ba wa Ruhuna hutu a ƙasar arewa.” ");
INSERT INTO hausa_vpl VALUES ("ZC6_9","039_6_9","ZEC","6","9","9","Maganar Ubangiji ta zo mini, ta ce, ");
INSERT INTO hausa_vpl VALUES ("ZC6_10","039_6_10","ZEC","6","10","10","“Ka karɓi azurfa da zinariya daga masu zaman bauta Heldai, Tobiya, Yedahiya, waɗanda suka iso daga Babilon. A ranar kuma ka je gidan Yosiya ɗan Zefaniya. ");
INSERT INTO hausa_vpl VALUES ("ZC6_11","039_6_11","ZEC","6","11","11","Ka ɗauki azurfar da zinariyar ka yi rawani, ka ɗora shi a kan babban firist, Yoshuwa ɗan Yehozadak. ");
INSERT INTO hausa_vpl VALUES ("ZC6_12","039_6_12","ZEC","6","12","12","Ka ce masa ga abin da Ubangiji Maɗaukaki ya ce, ‘Ga mutumin da sunansa ne Reshe, zai kuma ratse daga inda yake yă gina haikalin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ZC6_13","039_6_13","ZEC","6","13","13","Shi ne zai gina haikalin Ubangiji, za a kuma martaba shi da daraja, zai kuma zauna yă yi mulki a kan kursiyinsa. Zai zama firist a kan kursiyinsa. Kuma a tsakanin biyun za a sami zaman lafiya.’ ");
INSERT INTO hausa_vpl VALUES ("ZC6_14","039_6_14","ZEC","6","14","14","Za a ba Heldai, Tobiya, Yedahiya da kuma Hen ɗan Zefaniya kamar abin tunawa a cikin haikalin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ZC6_15","039_6_15","ZEC","6","15","15","Waɗanda suke nesa za su zo su taimaka gina haikalin Ubangiji, za ku kuma san cewa Ubangiji Maɗaukaki ne ya aiko ni gare ku. Wannan zai faru in kuka yi biyayya sosai ga Ubangiji Allahnku.” ");
INSERT INTO hausa_vpl VALUES ("ZC7_1","039_7_1","ZEC","7","1","1","A shekara ta huɗu ta Sarki Dariyus, maganar Ubangiji ta zo wa Zakariya a rana ta huɗu ta watan tara, wato, watan Kisleb. ");
INSERT INTO hausa_vpl VALUES ("ZC7_2","039_7_2","ZEC","7","2","2","Mutanen Betel sun aika Sharezer da Regem-Melek, tare da mutanensu su nemi tagomashin Ubangiji ");
INSERT INTO hausa_vpl VALUES ("ZC7_3","039_7_3","ZEC","7","3","3","ta wurin tambayar firistocin da kuma annabawan gidan Ubangiji Maɗaukaki, “Ko ya kamata in yi makoki da azumi a wata na biyar, yadda na yi a shekaru masu yawa?” ");
INSERT INTO hausa_vpl VALUES ("ZC7_4","039_7_4","ZEC","7","4","4","Sai maganar Ubangiji Maɗaukaki ta zo mini ta ce, ");
INSERT INTO hausa_vpl VALUES ("ZC7_5","039_7_5","ZEC","7","5","5","“Ka tambayi dukan mutanen ƙasar da firistoci cewa, ‘Sa’ad da kuka yi makoki da azumi a wata na biyar da na bakwai dukan shekaru saba’in nan, a ainihi saboda ni kuka yi azumi? ");
INSERT INTO hausa_vpl VALUES ("ZC7_6","039_7_6","ZEC","7","6","6","Kuma sa’ad da kuke ci kuke sha, ba kanku kuke yi wa shagali ba? ");
INSERT INTO hausa_vpl VALUES ("ZC7_7","039_7_7","ZEC","7","7","7","Ashe, ba kalmomin da Ubangiji ya faɗi ke nan ta bakin annabawan farko ba sa’ad da Urushalima da garuruwan da suke kewaye da ita suke hutawa, suke cikin wadata, akwai kuma mutane a Negeb da yammancin gindin tuddai?’ ” ");
INSERT INTO hausa_vpl VALUES ("ZC7_8","039_7_8","ZEC","7","8","8","Sai maganar Ubangiji ta sāke zuwa wa Zakariya cewa, ");
INSERT INTO hausa_vpl VALUES ("ZC7_9","039_7_9","ZEC","7","9","9","“Ga abin da Ubangiji Maɗaukaki ya ce, ‘Ku yi shari’ar gaskiya; ku nuna jinƙai da tausayi ga juna. ");
INSERT INTO hausa_vpl VALUES ("ZC7_10","039_7_10","ZEC","7","10","10","Kada ku danne gwauruwa ko maraya, baƙo ko talaka. A cikin zuciyarku kada ku yi mugun tunani game da juna.’ ");
INSERT INTO hausa_vpl VALUES ("ZC7_11","039_7_11","ZEC","7","11","11","“Amma suka ƙi su saurara; da taurinkai suka juya bayansu suka kuma toshe kunnuwansu. ");
INSERT INTO hausa_vpl VALUES ("ZC7_12","039_7_12","ZEC","7","12","12","Suka taurare zukatansu kamar dutse, suka ƙi jin abin da doka ko kuma maganar Ubangiji Maɗaukaki take faɗi wadda ya aika ta wurin Ruhunsa ta wurin annabawan farko. Saboda haka Ubangiji Maɗaukaki ya ji fushi ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("ZC7_13","039_7_13","ZEC","7","13","13","“ ‘Sa’ad da na yi kira, ba su saurara ba; saboda haka sa’ad da suka kira, ba zan saurara ba,’ in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ZC7_14","039_7_14","ZEC","7","14","14","‘Na warwatsar da su da guguwa a cikin dukan ƙasashe, inda suka zama baƙi. Aka bar ƙasar ta zama kango bayansu, da har ba mai shiga ko fita. Haka suka sa ƙasan nan mai daɗi ta zama kango.’ ” ");
INSERT INTO hausa_vpl VALUES ("ZC8_1","039_8_1","ZEC","8","1","1","Maganar Ubangiji Maɗaukaki ta sāke zuwa gare ni. ");
INSERT INTO hausa_vpl VALUES ("ZC8_2","039_8_2","ZEC","8","2","2","Ga abin da Ubangiji Maɗaukaki ya ce, “Ina kishin Sihiyona ƙwarai; ina kuma cike da kishi dominta.” ");
INSERT INTO hausa_vpl VALUES ("ZC8_3","039_8_3","ZEC","8","3","3","Ga abin da Ubangiji ya ce, “Zan koma Sihiyona in zauna a Urushalima. Sa’an nan za a kira Urushalima Birnin Gaskiya, a kuma kira dutsen Ubangiji Maɗaukaki Dutse Mai Tsarki.” ");
INSERT INTO hausa_vpl VALUES ("ZC8_4","039_8_4","ZEC","8","4","4","Ga abin da Ubangiji Maɗaukaki ya ce, “Tsofaffi maza da mata za su sāke zauna a titunan Urushalima, kowanne da sanda a hannu saboda tsufa. ");
INSERT INTO hausa_vpl VALUES ("ZC8_5","039_8_5","ZEC","8","5","5","Titunan birnin za su cika da samari da ’yan mata suna wasa.” ");
INSERT INTO hausa_vpl VALUES ("ZC8_6","039_8_6","ZEC","8","6","6","Ga abin da Ubangiji Maɗaukaki ya ce, “Mai yiwuwa ya zama da mamaki ga raguwar wannan mutanen da suke nan a lokacin, amma zai zama abin mamaki gare ni ne?” In ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ZC8_7","039_8_7","ZEC","8","7","7","Ga abin da Ubangiji Maɗaukaki ya ce, “Zan ceci mutanena daga ƙasashen gabas da yamma. ");
INSERT INTO hausa_vpl VALUES ("ZC8_8","039_8_8","ZEC","8","8","8","Zan komo da su su zauna a Urushalima; za su zama mutanena, ni kuwa zan zama amintaccen Allahnsu mai adalci.” ");
INSERT INTO hausa_vpl VALUES ("ZC8_9","039_8_9","ZEC","8","9","9","Ga abin da Ubangiji Maɗaukaki ya ce, “Ku da yanzu kuke jin maganan nan da annabawa suka faɗi, waɗanda suke a nan lokacin da aka kafa harsashin haikalin Ubangiji Maɗaukaki, bari hannuwanku su zama da ƙarfi don a gama gina haikalin. ");
INSERT INTO hausa_vpl VALUES ("ZC8_10","039_8_10","ZEC","8","10","10","Kafin wannan lokaci babu albashi domin mutum ko dabba. Ba wanda yake iya sakewa yă yi hidimominsa saboda maƙiya, domin na sa kowa yă zama maƙiyi maƙwabcinsa. ");
INSERT INTO hausa_vpl VALUES ("ZC8_11","039_8_11","ZEC","8","11","11","Amma yanzu ba zan yi da waɗanda raguwar mutane yadda na yi da na dā ba,” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ZC8_12","039_8_12","ZEC","8","12","12","“Iri zai yi girma da kyau, kuringa za tă ba da ’ya’yanta, ƙasa za tă ba da hatsi, sama kuma za tă ba da raɓa. Zan ba da duk waɗannan abubuwa su zama gādo ga raguwar mutanen nan. ");
INSERT INTO hausa_vpl VALUES ("ZC8_13","039_8_13","ZEC","8","13","13","Kamar yadda kuka zama abin la’ana a ƙasashe, ya Yahuda da Isra’ila, haka zan cece ku, za ku kuma zama albarka. Kada ku ji tsoro, sai dai ku bar hannuwanku su zama da ƙarfi.” ");
INSERT INTO hausa_vpl VALUES ("ZC8_14","039_8_14","ZEC","8","14","14","Ga abin da Ubangiji Maɗaukaki ya ce, “Kamar dai yadda na yi niyyar kawo muku bala’i, in kuma ƙi jin tausayi sa’ad da kakanninku suka ba ni haushi,” in ji Ubangiji Maɗaukaki, ");
INSERT INTO hausa_vpl VALUES ("ZC8_15","039_8_15","ZEC","8","15","15","kada ku ji tsoro “saboda a yanzu na yi niyya in sāke yi wa Urushalima da Yahuda abu mai kyau. ");
INSERT INTO hausa_vpl VALUES ("ZC8_16","039_8_16","ZEC","8","16","16","Abubuwan da za ku yi ke nan. Ku gaya wa juna gaskiya, ku kuma dinga yin shari’ar gaskiya a ɗakunanku na shari’arku; ");
INSERT INTO hausa_vpl VALUES ("ZC8_17","039_8_17","ZEC","8","17","17","kada ku ƙulla wa maƙwabtanku mugunta, kuma kada ku so yin rantsuwa ta ƙarya. Ina ƙyamar waɗannan duka,” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ZC8_18","039_8_18","ZEC","8","18","18","Maganar Ubangiji Maɗaukaki ta sāke zuwa wurina. ");
INSERT INTO hausa_vpl VALUES ("ZC8_19","039_8_19","ZEC","8","19","19","Ga abin da Ubangiji Maɗaukaki ya ce, “Azumin wata na huɗu, da na watan biyar, da na watan bakwai da na watan goma za su zama lokutan farin ciki da murna da kuma bukukkuwa na murna ga Yahuda. Saboda haka sai ku ƙaunaci gaskiya da salama.” ");
INSERT INTO hausa_vpl VALUES ("ZC8_20","039_8_20","ZEC","8","20","20","Ga abin da Ubangiji Maɗaukaki ya ce, “Mutane da yawa da kuma mazaunan birane da yawa har yanzu za su zo, ");
INSERT INTO hausa_vpl VALUES ("ZC8_21","039_8_21","ZEC","8","21","21","mazaunan wani birni za su je wurin mazaunan wani birni su ce, ‘Bari mu je nan da nan mu roƙi Ubangiji mu kuma nemi Ubangiji Maɗaukaki. Ni kaina zan je.’ ");
INSERT INTO hausa_vpl VALUES ("ZC8_22","039_8_22","ZEC","8","22","22","Mutane da yawa kuma da al’ummai masu ƙarfi za su zo Urushalima su nemi Ubangiji Maɗaukaki su kuma roƙe shi.” ");
INSERT INTO hausa_vpl VALUES ("ZC8_23","039_8_23","ZEC","8","23","23","Ga abin da Ubangiji Maɗaukaki ya ce, “A kwanakin nan, mutane goma daga kabilu da al’ummai za su riƙe rigar mutumin Yahuda guda su ce, ‘Bari mu tafi tare da kai, domin mun ji cewa Allah yana tare da ku.’ ” ");
INSERT INTO hausa_vpl VALUES ("ZC9_1","039_9_1","ZEC","9","1","1","Annabci. Maganar Ubangiji tana gāba da ƙasar Hadrak za tă kuma sauko a kan Damaskus, gama idanun dukan mutane da na kabilan Isra’ila suna a kan Ubangiji, ");
INSERT INTO hausa_vpl VALUES ("ZC9_2","039_9_2","ZEC","9","2","2","da kuma a kan Hamat ita ma, wadda ta yi iyaka da ita, da kuma a kan Taya da Sidon, ko da yake suna da hikima ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("ZC9_3","039_9_3","ZEC","9","3","3","Taya ta gina wa kanta mafaka mai ƙarfi; ta tara azurfa kamar ƙasa, zinariya kuma kamar tarin shara a tituna. ");
INSERT INTO hausa_vpl VALUES ("ZC9_4","039_9_4","ZEC","9","4","4","Amma Ubangiji zai karɓe mallakarta, zai hallaka ikonta da take da shi a kan teku, wuta kuma za tă cinye ta. ");
INSERT INTO hausa_vpl VALUES ("ZC9_5","039_9_5","ZEC","9","5","5","Ashkelon za tă ga haka ta ji tsoro; Gaza za tă yi birgima cikin azaba, haka Ekron ma, gama za tă fid da zuciya. Gaza za tă rasa sarkinta za a kuma gudu a bar Ashkelon. ");
INSERT INTO hausa_vpl VALUES ("ZC9_6","039_9_6","ZEC","9","6","6","Baƙi za su mallaki Ashdod, kuma zan kawar da girman kan Filistiyawa. ");
INSERT INTO hausa_vpl VALUES ("ZC9_7","039_9_7","ZEC","9","7","7","Zan kawar da jini daga bakinsu, zan kuma cire abincin da aka haramta daga tsakanin haƙoransu. Waɗanda za a bari za su zama na Allahnmu, su kuma zama shugabanni a Yahuda, Ekron kuma za tă zama kamar Yebusiyawa. ");
INSERT INTO hausa_vpl VALUES ("ZC9_8","039_9_8","ZEC","9","8","8","Amma zan kāre gidana daga sojoji masu kai da kawowa. Azzalumi ba zai ƙara cin mutanena da yaƙi ba, gama yanzu ina tsaro. ");
INSERT INTO hausa_vpl VALUES ("ZC9_9","039_9_9","ZEC","9","9","9","Ki yi murna ƙwarai, ya Diyar Urushalima! Ki yi sowa, Diyar Urushalima! Duba, ga sarkinki yana zuwa wurinki, mai adalci yana kuma da ceto, mai tawali’u yana kuma hawan jaki, yana a kan ɗan aholaki, a kan ’yar jaka. ");
INSERT INTO hausa_vpl VALUES ("ZC9_10","039_9_10","ZEC","9","10","10","Zan ƙwace kekunan yaƙi daga Efraim, da kuma dawakan yaƙi daga Urushalima, za a kuma karya bakan yaƙi. Zai yi shelar salama ga al’ummai. Mulkinsa zai yaɗu daga teku zuwa teku, daga Kogi kuma zuwa ƙarshen duniya. ");
INSERT INTO hausa_vpl VALUES ("ZC9_11","039_9_11","ZEC","9","11","11","Ke kuma, saboda jinin alkawarina da ke, zan ’yantar da ’yan kurkukunki daga rami marar ruwa. ");
INSERT INTO hausa_vpl VALUES ("ZC9_12","039_9_12","ZEC","9","12","12","Ku koma maɓuya, ya ku ’yan kurkuku masu sa zuciya; ko yanzu ma na sanar cewa zan mayar muku ninki biyu. ");
INSERT INTO hausa_vpl VALUES ("ZC9_13","039_9_13","ZEC","9","13","13","Zan lanƙwasa Yahuda yadda nake lanƙwasa bakana, in kuma cika ta da Efraim kamar kibiya. Zan tā da ’ya’yanki maza, ya Sihiyona, gāba da ’ya’yanki, ya Girka, in kuma mai da ke kamar takobin jarumin yaƙi. ");
INSERT INTO hausa_vpl VALUES ("ZC9_14","039_9_14","ZEC","9","14","14","Sa’an nan Ubangiji zai bayyana a bisansu; kibiyarsa za tă wulga kamar walƙiya. Ubangiji Mai Iko Duka zai busa ƙaho; zai taho ta cikin guguwa daga kudu, ");
INSERT INTO hausa_vpl VALUES ("ZC9_15","039_9_15","ZEC","9","15","15","Ubangiji Maɗaukaki kuma zai tsare su. Za su hallakar su kuma yi nasara da duwatsun majajjawa. Za su sha su yi kururuwa kamar sun sha ruwan inabi; za su cika kamar kwanon da ake amfani don a yayyafa jini a kusurwoyin bagade. ");
INSERT INTO hausa_vpl VALUES ("ZC9_16","039_9_16","ZEC","9","16","16","Ubangiji Allahnsu zai cece su a wannan rana gama su mutanensa ne da kuma garkensa. Za su haska a cikin ƙasarsa kamar lu’ulu’u a rawani. ");
INSERT INTO hausa_vpl VALUES ("ZC9_17","039_9_17","ZEC","9","17","17","Za su yi kyan gani da kuma bansha’awa! Hatsi zai sa samari su yi murna, sabon ruwan inabi kuma zai sa ’yan mata su yi farin ciki. ");
INSERT INTO hausa_vpl VALUES ("ZC10_1","039_10_1","ZEC","10","1","1","Ku roƙi Ubangiji yă ba ku ruwa a lokacin bazara; Ubangiji ne yake yin gizagizan hadari. Shi ne yake ba wa mutane yayyafin ruwan sama yana kuma ba da tsire-tsire na fili ga kowa. ");
INSERT INTO hausa_vpl VALUES ("ZC10_2","039_10_2","ZEC","10","2","2","Gumaka suna maganganun ruɗu, masu duba suna ganin wahayoyin ƙarya, suna faɗa mafarkan ƙarya suna ba da ta’aziyyar banza. Saboda haka mutane suna yawo kamar tumaki waɗanda suke shan wahala saboda rashin makiyayi. ");
INSERT INTO hausa_vpl VALUES ("ZC10_3","039_10_3","ZEC","10","3","3","“Ina fushi da makiyayan, zan kuma hukunta shugabannin; gama Ubangiji Maɗaukaki zai lura da garkensa, wato, gidan Yahuda, zai kuma sa su zama kamar doki mai fariya cikin yaƙi. ");
INSERT INTO hausa_vpl VALUES ("ZC10_4","039_10_4","ZEC","10","4","4","Daga Yahuda dutsen kusurwa zai fito, daga gare shi za a samu abin kafa tenti, daga gare shi za a sami bakan yaƙi, daga gare shi za a sami kowane mai mulki. ");
INSERT INTO hausa_vpl VALUES ("ZC10_5","039_10_5","ZEC","10","5","5","Tare za su zama kamar mutane masu ƙarfi suna tattake lakar tituna a cikin yaƙi. Domin Ubangiji yana tare da su, za su yi faɗa su kuma yi nasara a kan masu yaƙi a kan dawakai. ");
INSERT INTO hausa_vpl VALUES ("ZC10_6","039_10_6","ZEC","10","6","6","“Zan ƙarfafa gidan Yahuda in kuma ceci gidan Yusuf. Zan maido da su domin ina jin tausayinsu. Za su zama kamar ban taɓa ƙinsu ba, gama ni ne Ubangiji Allahnsu zan kuma amsa musu. ");
INSERT INTO hausa_vpl VALUES ("ZC10_7","039_10_7","ZEC","10","7","7","Mutanen Efraim za su zama kamar mutane masu ƙarfi, zukatansu kuwa za su yi murna kamar sun sha ruwan inabi. ’Ya’yansu za su gani su yi murna; zuciyarsu za tă yi farin ciki a cikin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ZC10_8","039_10_8","ZEC","10","8","8","Zan ba da alama in kuma tattara su. Ba shakka zan fanshe su; za su yi yawa kamar yadda suke a dā. ");
INSERT INTO hausa_vpl VALUES ("ZC10_9","039_10_9","ZEC","10","9","9","Ko da yake na warwatsa su cikin mutane, duk da haka a can ƙasashe masu nisa za su tuna da ni. Su da ’ya’yansu za su rayu, za su kuwa komo. ");
INSERT INTO hausa_vpl VALUES ("ZC10_10","039_10_10","ZEC","10","10","10","Zan komo da su daga Masar in kuma tattara su daga Assuriya. Zan kawo su Gileyad da Lebanon, har wuri yă kāsa musu. ");
INSERT INTO hausa_vpl VALUES ("ZC10_11","039_10_11","ZEC","10","11","11","Za su ratsa cikin tekun wahala; zan kwantar da raƙuman teku dukan zurfafan Nilu kuma za su bushe. Za a ƙasƙantar da Assuriya, sandar sarautar Masar kuma za tă rabu da ita. ");
INSERT INTO hausa_vpl VALUES ("ZC10_12","039_10_12","ZEC","10","12","12","Zan ƙarfafa su a cikin Ubangiji kuma a cikin sunansa za su yi tafiya,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ZC11_1","039_11_1","ZEC","11","1","1","Buɗe ƙofofinki, ya Lebanon, don wuta ta cinye itatuwan al’ul naki. ");
INSERT INTO hausa_vpl VALUES ("ZC11_2","039_11_2","ZEC","11","2","2","Yi kuka, ya itacen fir, gama itacen al’ul ya fāɗi; itatuwa masu daraja sun lalace! Ku yi kuka, ku itatuwan oak na Bashan; an sassare itatuwan babban kurmi! ");
INSERT INTO hausa_vpl VALUES ("ZC11_3","039_11_3","ZEC","11","3","3","Ku ji kukan makiyaya; an ɓata musu wuraren kiwonsu masu ciyayi! Ku ji rurin zakoki; an lalatar da jejin Urdun! ");
INSERT INTO hausa_vpl VALUES ("ZC11_4","039_11_4","ZEC","11","4","4","Ga abin da Ubangiji Allahna ya ce, “Yi kiwon garken tumakin da za a yanka. ");
INSERT INTO hausa_vpl VALUES ("ZC11_5","039_11_5","ZEC","11","5","5","Masu sayensu sun yanyanka su, suka kuwa tafi ba hukunci. Masu sayar da su sun ce, ‘Yabi Ubangiji, na yi arziki!’ Makiyayansu ma ba su ji tausayinsu ba. ");
INSERT INTO hausa_vpl VALUES ("ZC11_6","039_11_6","ZEC","11","6","6","Gama ba zan ƙara jin tausayin mutanen ƙasar ba,” in ji Ubangiji. “Zan ba da kowa ga maƙwabcinsa da kuma sarkinsa. Za su zalunci ƙasar, ba zan kuma cece su daga hannuwansu ba.” ");
INSERT INTO hausa_vpl VALUES ("ZC11_7","039_11_7","ZEC","11","7","7","Saboda haka na yi kiwon garken da za a yanka, musamman garken da ake zalunta. Sai na ɗauki sanduna biyu na kira ɗaya Tagomashi, ɗaya kuma Haɗinkai, sai na yi kiwon garken. ");
INSERT INTO hausa_vpl VALUES ("ZC11_8","039_11_8","ZEC","11","8","8","Cikin wata guda na kawar da makiyayan nan uku. Garken suka ƙi ni, na kuwa gaji da su ");
INSERT INTO hausa_vpl VALUES ("ZC11_9","039_11_9","ZEC","11","9","9","na ce, “Ba zan zama makiyayinku ba. Bari masu mutuwa su mutu, masu hallaka kuma su hallaka. Bari waɗanda suka ragu su ci naman juna.” ");
INSERT INTO hausa_vpl VALUES ("ZC11_10","039_11_10","ZEC","11","10","10","Sai na ɗauki sandana mai suna Tagomashi na karya shi, na janye alkawarin da na yi da dukan al’ummai. ");
INSERT INTO hausa_vpl VALUES ("ZC11_11","039_11_11","ZEC","11","11","11","An janye shi a ranan nan, saboda haka garken da yake cikin wahala masu kallona sun san cewa maganar Ubangiji ce. ");
INSERT INTO hausa_vpl VALUES ("ZC11_12","039_11_12","ZEC","11","12","12","Na faɗa musu cewa, “In kun ga ya fi kyau, ku biya ni; in kuwa ba haka ba, ku riƙe.” Saboda haka suka biya ni azurfa talatin. ");
INSERT INTO hausa_vpl VALUES ("ZC11_13","039_11_13","ZEC","11","13","13","Sai Ubangiji ya ce mini, “Jefar da shi cikin ma’aji,” Lada mai kyau da aka yi cinikina ne! Saboda haka sai na ɗauki azurfa talatin ɗin na jefa su cikin gidan Ubangiji don a sa cikin ma’aji. ");
INSERT INTO hausa_vpl VALUES ("ZC11_14","039_11_14","ZEC","11","14","14","Sai na karya sandana na biyu mai suna Haɗinkai, ta haka na karya ’yan’uwantakar da take tsakanin Yahuda da Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("ZC11_15","039_11_15","ZEC","11","15","15","Sai Ubangiji ya ce mini, “Ka sāke ɗaukar kayan aiki na wawan makiyayi. ");
INSERT INTO hausa_vpl VALUES ("ZC11_16","039_11_16","ZEC","11","16","16","Gama zan tā da makiyayi a ƙasar wanda ba zai kula da ɓatattu, ko yă nemi ƙanana, ko yă warkar da waɗanda suka ji ciwo, ko kuma ciyar da masu lafiya ba, sai dai zai ci naman keɓaɓɓun tumaki, yă farfasa kofatonsu. ");
INSERT INTO hausa_vpl VALUES ("ZC11_17","039_11_17","ZEC","11","17","17","“Kaito ga banzan makiyayin nan, wanda ya bar garken! Bari takobi yă sare hannunsa da idonsa na dama! Bari hannunsa yă shanye gaba ƙaf, idonsa na dama kuma yă makance sarai!” ");
INSERT INTO hausa_vpl VALUES ("ZC12_1","039_12_1","ZEC","12","1","1","Annabci, maganar Ubangiji game da Isra’ila. Ubangiji, wanda ya shimfiɗa sammai, wanda ya kafa harsashin duniya, wanda kuma ya yi ruhun mutum a cikinsa ya ce, ");
INSERT INTO hausa_vpl VALUES ("ZC12_2","039_12_2","ZEC","12","2","2","“Zan sa Urushalima ta zama kwaf mai sa mutanen da suke a dukan kewayenta, jiri. Yaƙi zai kewaye Urushalima har yă shafi Yahuda ma. ");
INSERT INTO hausa_vpl VALUES ("ZC12_3","039_12_3","ZEC","12","3","3","A ranan nan, sa’ad da duk al’umman duniya za su tayar mata, zan sa Urushalima ta zama dutsen da ba a iya matsarwa ga dukan al’ummai. Duk waɗanda suka yi ƙoƙari su matsar da shi za su ji ciwo. ");
INSERT INTO hausa_vpl VALUES ("ZC12_4","039_12_4","ZEC","12","4","4","A ranan nan zan sa kowane doki yă tsorata, mai hawan dokin kuma yă haukace,” in ji Ubangiji. “Zan sa idanuna in tsare gidan Yahuda, amma zan makantar da dukan dawakan al’ummai. ");
INSERT INTO hausa_vpl VALUES ("ZC12_5","039_12_5","ZEC","12","5","5","Sa’an nan shugabannin Yahuda za su ce a cikin zukatansu, ‘Mutanen Urushalima suna da ƙarfi domin Ubangiji Maɗaukaki shi ne Allahnsu.’ ");
INSERT INTO hausa_vpl VALUES ("ZC12_6","039_12_6","ZEC","12","6","6","“A ranan nan zan sa shugabannin Yahuda su zama kamar tukunyar wuta a tarin itacen wuta; kamar harshen wuta a dammunan hatsi. Za su ƙone dukan mutanen da suke kewaye da su hagu da dama, amma babu abin da zai taɓa mutanen Urushalima. ");
INSERT INTO hausa_vpl VALUES ("ZC12_7","039_12_7","ZEC","12","7","7","“Ubangiji zai ceci wuraren zaman Yahuda da farko, don kada darajar gidan Dawuda da mazaunan Urushalima su fi na Yahuda daraja. ");
INSERT INTO hausa_vpl VALUES ("ZC12_8","039_12_8","ZEC","12","8","8","A ranan nan Ubangiji zai kiyaye waɗanda suke zama a Urushalima, domin marasa ƙarfi a cikinsu su zama kamar Dawuda, gidan Dawuda kuma zai zama kamar Allah, kamar mala’ikan Ubangiji da yake tafiya a gabansu. ");
INSERT INTO hausa_vpl VALUES ("ZC12_9","039_12_9","ZEC","12","9","9","A ranan nan zan fito don in hallaka dukan al’umman da suka yaƙi Urushalima. ");
INSERT INTO hausa_vpl VALUES ("ZC12_10","039_12_10","ZEC","12","10","10","“Zan kuma zubo wa gidan Dawuda da mazaunan Urushalima ruhun alheri da na addu’a. Za su dube ni, wannan da suka soke shi, za su kuma yi makoki dominsa kamar yadda mutum yakan yi makokin mutuwar ɗansa tilo, su kuma yi baƙin ciki ƙwarai kamar yadda mutum yakan yi baƙin ciki don ɗan fari. ");
INSERT INTO hausa_vpl VALUES ("ZC12_11","039_12_11","ZEC","12","11","11","A ranan nan kuka a Urushalima zai yi yawa kamar kukan Hadad Rimmon a filin Megiddo. ");
INSERT INTO hausa_vpl VALUES ("ZC12_12","039_12_12","ZEC","12","12","12","Ƙasar za tă yi makoki, kowane iyali zai yi makoki a ware, tare da matansu su ma a ware, iyalin gidan Dawuda da matansu, iyalin gidan Natan da matansu, ");
INSERT INTO hausa_vpl VALUES ("ZC12_13","039_12_13","ZEC","12","13","13","iyalin gidan Lawi da matansu, iyalin gidan Shimeyi da matansu, ");
INSERT INTO hausa_vpl VALUES ("ZC12_14","039_12_14","ZEC","12","14","14","dukan sauran iyalan kuma da matansu. ");
INSERT INTO hausa_vpl VALUES ("ZC13_1","039_13_1","ZEC","13","1","1","“A ranan nan za a buɗe maɓulɓulan ruwa zuwa gidan Dawuda da mazaunan Urushalima, don a tsarkake su daga zunubi da rashin tsabta. ");
INSERT INTO hausa_vpl VALUES ("ZC13_2","039_13_2","ZEC","13","2","2","“A ranan nan, zan kawar da sunayen gumaka daga ƙasar, ba kuwa za a ƙara tunawa da su ba,” in ji Ubangiji Maɗaukaki. “Zan kawar da annabawa da kuma ruhu marar tsabta daga ƙasar. ");
INSERT INTO hausa_vpl VALUES ("ZC13_3","039_13_3","ZEC","13","3","3","In kuma wani ya yi annabci, sai mahaifinsa da mahaifiyarsa su ce masa, ‘Ba za ka rayu ba, gama kana faɗar ƙarya da sunan Ubangiji.’ Sa’ad da yake yin annabci, iyayensa za su soke shi da takobi. ");
INSERT INTO hausa_vpl VALUES ("ZC13_4","039_13_4","ZEC","13","4","4","“A ranan nan kowane annabi zai ji kunyar annabcin wahayinsa. Ba zai sa rigar annabci mai gashi ba don yă yi ruɗu. ");
INSERT INTO hausa_vpl VALUES ("ZC13_5","039_13_5","ZEC","13","5","5","Zai ce, ‘Ni ba annabi ba ne. Ni manomi ne; ƙasa ce nake samun abin zaman gari tun ina matashi.’ ");
INSERT INTO hausa_vpl VALUES ("ZC13_6","039_13_6","ZEC","13","6","6","In wani ya tambaye shi, ‘Waɗanne miyaku ne haka a jikinka?’ Zai amsa yă ce, ‘Miyakun da aka yi mini a gidan abokaina ne.’ ");
INSERT INTO hausa_vpl VALUES ("ZC13_7","039_13_7","ZEC","13","7","7","“Tashi, ya takobi, gāba da makiyayina, mutumin da yake kusa da ni sosai!” In ji Ubangiji Maɗaukaki. “Kashe makiyayin, sai tumakin su watse, in kuma tayar wa ƙananan. ");
INSERT INTO hausa_vpl VALUES ("ZC13_8","039_13_8","ZEC","13","8","8","A cikin ƙasar duka,” in ji Ubangiji, “kashi biyu bisa uku za a buge su su hallaka; duk da haka za a bar kashi ɗaya bisa uku a cikinta. ");
INSERT INTO hausa_vpl VALUES ("ZC13_9","039_13_9","ZEC","13","9","9","Wannan kashi ɗaya bisa ukun zan kawo in sa a cikin wuta; zan tace su kamar azurfa in gwada su kamar zinariya. Za su kira bisa sunana zan kuwa amsa musu; zan ce, ‘Su mutanena ne,’ za su kuma ce, ‘Ubangiji ne Allahnmu.’ ” ");
INSERT INTO hausa_vpl VALUES ("ZC14_1","039_14_1","ZEC","14","1","1","Ranar Ubangiji tana zuwa sa’ad da za a raba muku ganimar da aka washe daga gare ku. ");
INSERT INTO hausa_vpl VALUES ("ZC14_2","039_14_2","ZEC","14","2","2","Zan tara dukan al’ummai su yaƙi Urushalima; za a ci birnin da yaƙi, za a washe gidaje, a kuma yi wa mata fyaɗe. Rabin birnin zai je bauta, amma ba za a kwashe sauran mutanen daga birnin ba. ");
INSERT INTO hausa_vpl VALUES ("ZC14_3","039_14_3","ZEC","14","3","3","Sa’an nan Ubangiji zai fita yă yi yaƙi da waɗannan al’ummai, kamar yadda yake yaƙi a ranar yaƙi. ");
INSERT INTO hausa_vpl VALUES ("ZC14_4","039_14_4","ZEC","14","4","4","A ranan nan ƙafafunsa za su tsaya a kan Dutsen Zaitun, gabas da Urushalima, za a kuma tsage Dutsen Zaitun kashi biyu daga gabas zuwa yamma, yă zama babban kwari, rabin dutsen zai matsa zuwa wajen arewa, rabi kuma zai matsa zuwa wajen kudu. ");
INSERT INTO hausa_vpl VALUES ("ZC14_5","039_14_5","ZEC","14","5","5","Za ku gudu ta wajen kwarin dutsena, gama zai miƙe har zuwa Azel. Za ku gudu kamar yadda kuka guje wa girgizar ƙasa a kwanakin Uzziya sarkin Yahuda. Sa’an nan Ubangiji Allahna zai zo, tare da duk masu tsarki. ");
INSERT INTO hausa_vpl VALUES ("ZC14_6","039_14_6","ZEC","14","6","6","A ranan nan ba za a kasance da haske ko sanyi ba, ko hazo mai duhu ba. ");
INSERT INTO hausa_vpl VALUES ("ZC14_7","039_14_7","ZEC","14","7","7","Za tă zama rana ce ta musamman, ba yini ko dare, rana da take sananne ga Ubangiji. Sa’ad da yamma ta yi, za a yi haske. ");
INSERT INTO hausa_vpl VALUES ("ZC14_8","039_14_8","ZEC","14","8","8","A ranan nan ruwan rai zai kwararo daga Urushalima, rabi zai gangara gabas zuwa teku rabi kuma zai gangara yamma zuwa Bahar Rum, a damina da rani. ");
INSERT INTO hausa_vpl VALUES ("ZC14_9","039_14_9","ZEC","14","9","9","Ubangiji zai sama sarki bisa dukan duniya. A ranan nan za a kasance da Ubangiji ɗaya, ba wani suna kuma sai nasa. ");
INSERT INTO hausa_vpl VALUES ("ZC14_10","039_14_10","ZEC","14","10","10","Ƙasar gaba ɗaya daga Geba zuwa Rimmon, kudu da Urushalima, za tă zama kamar Araba. Amma Urushalima za tă kasance a wurinta, daga Ƙofar Benyamin zuwa sashen Ƙofa ta Farko, zuwa Ƙofar Kusurwa, daga kuma Hasumiyar Hananel zuwa wurin matsin ruwan inabin sarki. ");
INSERT INTO hausa_vpl VALUES ("ZC14_11","039_14_11","ZEC","14","11","11","Za a zauna a cikinka; ba za a ƙara hallaka ta ba. Urushalima za tă zauna lafiya. ");
INSERT INTO hausa_vpl VALUES ("ZC14_12","039_14_12","ZEC","14","12","12","Ga bala’in da Ubangiji zai bugi dukan al’umman da suka yi yaƙi da Urushalima. Fatar jikinsu za tă ruɓe tun suna tsaye a ƙafafunsu, idanunsu za su ruɓe a cikin kwarminsu, harsunansu kuma zai ruɓe a cikin bakunansu. ");
INSERT INTO hausa_vpl VALUES ("ZC14_13","039_14_13","ZEC","14","13","13","A ranan nan Ubangiji zai sa maza su cika da tsoro ƙwarai. Kowane mutum zai kama hannun ɗan’uwansa, za su kai wa juna hari. ");
INSERT INTO hausa_vpl VALUES ("ZC14_14","039_14_14","ZEC","14","14","14","Yahuda ma za tă yi yaƙi a Urushalima. Za a tattara dukiyar al’umman da suke kewaye, za a tara zinariya da azurfa masu yawan gaske tare da tufafi. ");
INSERT INTO hausa_vpl VALUES ("ZC14_15","039_14_15","ZEC","14","15","15","Irin wannan bala’i zai auko wa dawakai da alfadarai, raƙuma da jakuna, da kuma dukan dabbobi a wannan sansani. ");
INSERT INTO hausa_vpl VALUES ("ZC14_16","039_14_16","ZEC","14","16","16","Sa’an nan waɗanda suka tsira daga cikin al’umman da suka yaƙe Urushalima za su haura shekara-shekara su yi wa Sarki, Ubangiji Maɗaukaki sujada, su kuma yi Bikin Tabanakul. ");
INSERT INTO hausa_vpl VALUES ("ZC14_17","039_14_17","ZEC","14","17","17","In waɗansu mutanen da suke duniya ba su haura Urushalima suka yi wa Sarki, Ubangiji Maɗaukaki sujada ba, ba za su sami ruwan sama ba. ");
INSERT INTO hausa_vpl VALUES ("ZC14_18","039_14_18","ZEC","14","18","18","In mutanen Masar ba su haura sun yi sujada ba, ba za su sami ruwan sama ba. Ubangiji zai kawo masu bala’in da ya aika wa al’umman da ba su haura sun yi Bikin Tabanakul ba. ");
INSERT INTO hausa_vpl VALUES ("ZC14_19","039_14_19","ZEC","14","19","19","Wannan ne zai zama hukuncin Masar da kuma na dukan al’umman da ba su haura sun yi Bikin Tabanakul ba. ");
INSERT INTO hausa_vpl VALUES ("ZC14_20","039_14_20","ZEC","14","20","20","A ranan nan za a rubuta TSARKI GA Ubangiji a jikin ƙararrawar dawakai, kuma tukwanen dahuwa a gidan Ubangiji za su zama kamar kwanoni masu tsarki a gaban bagade. ");
INSERT INTO hausa_vpl VALUES ("ZC14_21","039_14_21","ZEC","14","21","21","Kowace tukunya a Urushalima da Yahuda za tă zama mai tsarki ga Ubangiji Maɗaukaki, kuma duk wanda ya zo don miƙa hadaya zai ɗauki waɗansu tukwane yă yi dahuwa da su. A ranan nan kuwa, ba Bakan’ane da zai ƙara kasance a gidan Ubangiji Maɗaukaki.");
INSERT INTO hausa_vpl VALUES ("ML1_1","040_1_1","MAL","1","1","1","Annabci, wannan ita ce maganar Ubangiji ga Isra’ila ta wurin Malaki. ");
INSERT INTO hausa_vpl VALUES ("ML1_2","040_1_2","MAL","1","2","2","“Na ƙaunace ku, in ji Ubangiji. “Amma sai kuka ce, ‘Yaya ka ƙaunace mu?’ “Isuwa ba ɗan’uwan Yaƙub ba ne?” In ji Ubangiji. “Duk da haka na ƙaunaci Yaƙub, ");
INSERT INTO hausa_vpl VALUES ("ML1_3","040_1_3","MAL","1","3","3","amma na ƙi Isuwa, na kuma mai da ƙasarsa da take kan duwatsu kango, na ba da gādonsa ga dilolin hamada.” ");
INSERT INTO hausa_vpl VALUES ("ML1_4","040_1_4","MAL","1","4","4","Edom zai iya cewa, “Ko da yake an ragargaza mu, ai, za mu sāke gina kufanmu.” Amma ga abin da Ubangiji Maɗaukaki ya ce, “Za su iya gini, amma zan rushe. Za a ce da su Muguwar Ƙasa, mutane da kullum suke a ƙarƙashi fushin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ML1_5","040_1_5","MAL","1","5","5","Za ku ga wannan da idanunku ku kuma ce, ‘Ubangiji da girma yake, har gaba da iyakokin Isra’ila ma!’ ");
INSERT INTO hausa_vpl VALUES ("ML1_6","040_1_6","MAL","1","6","6","“Ɗa yakan girmama mahaifinsa, bawa kuma yakan girmama maigidansa. In ni mahaifi ne, ina girman da ya dace da ni? In ni maigida ne, ina girman da ya dace da ni?” In ji Ubangiji Maɗaukaki. “Ku firistoci, ku ne kuka rena sunana. “Amma sai kuka ce, ‘Yaya muka rena sunanka?’ ");
INSERT INTO hausa_vpl VALUES ("ML1_7","040_1_7","MAL","1","7","7","“Kun ajiye abinci mai ƙazanta a kan bagadena. “Sai kuka ce, ‘Yaya muka ƙazantar da kai?’ “Ta wurin cewa teburin Ubangiji abin reni ne. ");
INSERT INTO hausa_vpl VALUES ("ML1_8","040_1_8","MAL","1","8","8","Sa’ad da kuka kawo makauniyar dabba don ku miƙa mini hadaya, wannan daidai ne? Sa’ad da kuka miƙa gurguwar dabba ko marar lafiya, wannan daidai ne? Ku gwada ba wa gwamnanku irin wannan ku gani! Kuna gani zai ji daɗinku? Zai karɓe ku ne?” In ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML1_9","040_1_9","MAL","1","9","9","“To, firistoci yanzu ku gwada ku roƙi Allah yă yi mana alheri. Da irin hadayun nan a hannuwanku ne zai ji ku?” In ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML1_10","040_1_10","MAL","1","10","10","“Kash, da ma wani daga cikinku ya rufe ƙofofin haikali don kada ku shiga, ku hura wuta marar amfani a bisa bagadena! Ba na jin daɗinku, ba zan kuwa karɓi hadaya daga hannuwanku ba” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML1_11","040_1_11","MAL","1","11","11","Sunana zai zama mai girma a cikin al’ummai, daga fitowar rana har zuwa fāɗuwarta. A kowane wuri za a miƙa wa sunana turare da tsabtacciyar hadaya domin sunana zai zama mai girma a cikin al’ummai, in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML1_12","040_1_12","MAL","1","12","12","“Amma kun ƙazantar da sunana ta wurin cewa ‘Teburin Ubangiji ya ƙazantu,’ kuka kuma yi magana a kan abincinsa kuna cewa, ‘Abin reni ne.’ ");
INSERT INTO hausa_vpl VALUES ("ML1_13","040_1_13","MAL","1","13","13","Kun kuma ce, ‘Mun gaji da irin wannan wahala!’ Kuna hura mini hancin reni,” in ji Ubangiji Maɗaukaki. “Sa’ad da kuka kawo raunannu, gurguntattun dabbobi, ko kuma dabbobi masu fama da cuta, kuka kuma miƙa su hadaya, kuna gani zan karɓi wannan daga gare ku?” In ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("ML1_14","040_1_14","MAL","1","14","14","“La’ananne ne macucin da yake da lafiyayyiyar dabba namiji a garkensa wadda ya yi alkawari zai bayar, amma sai ya miƙa hadayar dabba mai aibi ga Ubangiji. Gama ni babban sarki ne, za a kuma ji tsoron sunana a cikin al’ummai,” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML2_1","040_2_1","MAL","2","1","1","“Yanzu fa wannan gargaɗi dominku ne, ku firistoci. ");
INSERT INTO hausa_vpl VALUES ("ML2_2","040_2_2","MAL","2","2","2","In ba ku saurara ba, in kuma ba ku sa zuciyarku ga girmama sunana ba, zan aukar muku da la’ana, zan kuma la’antar da albarkunku. I, na riga na la’anta su, domin ba ku sa zuciyarku ga girmama ni ba, in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML2_3","040_2_3","MAL","2","3","3","“Saboda ku zan tsawata wa zuriyarku; zan watsa kashin dabbobin hadayunku a fuskokinku, a kuma kwashe ku tare da shi. ");
INSERT INTO hausa_vpl VALUES ("ML2_4","040_2_4","MAL","2","4","4","Za ku kuwa san cewa ni ne na aika muku da wannan gargaɗi domin alkawarina da Lawi yă ci gaba,” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML2_5","040_2_5","MAL","2","5","5","“Alkawarina da shi, alkawari ne na rai da salama, wanda na ba shi; domin yă girmama ni, ya kuwa girmama ni, ya kuma ji tsoron sunana ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("ML2_6","040_2_6","MAL","2","6","6","Umarnin gaskiya yana a bakinsa, ba a kuma sami wani ƙarya a leɓunansa ba. Ya yi tafiya tare da ni cikin salama da adalci, ya kuwa juyo da mutane masu yawa daga zunubi. ");
INSERT INTO hausa_vpl VALUES ("ML2_7","040_2_7","MAL","2","7","7","“Gama ya kamata leɓunan firist su kiyaye ilimi, ya kamata kuma mutane su nemi umarni daga bakinsa, domin shi ne manzon Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML2_8","040_2_8","MAL","2","8","8","Amma sai kuka kauce hanya, ta wurin koyarwarku kuma kuka sa mutane da yawa suka yi tuntuɓe; kun keta alkawarin da na yi da Lawi,” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML2_9","040_2_9","MAL","2","9","9","“Saboda haka na sa a rena ku, a kuma wulaƙanta ku a gaban dukan mutane, domin ba ku bi hanyoyina ba amma kuka nuna sonkai a al’amuran shari’a.” ");
INSERT INTO hausa_vpl VALUES ("ML2_10","040_2_10","MAL","2","10","10","Ashe, ba Mahaifi guda dukanmu muke da shi ba? Ba Allah ɗaya ne ya halicce mu ba? Don me muka keta alkawarin kakanninmu ta wurin cin amanar juna? ");
INSERT INTO hausa_vpl VALUES ("ML2_11","040_2_11","MAL","2","11","11","Yahuda ya ci amana. An yi abin kunya a Isra’ila da kuma a Urushalima. Yahuda ya ƙazantar da wuri mai tsarkin da Ubangiji yake ƙauna, ta wurin auren ’yar wani baƙon allah. ");
INSERT INTO hausa_vpl VALUES ("ML2_12","040_2_12","MAL","2","12","12","Game da mutumin da ya aikata wannan, ko wane ne shi, bari Ubangiji yă yanke shi daga tentunan Yaƙub, ko da ma ya kawo hadayu ga Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML2_13","040_2_13","MAL","2","13","13","Ga kuma wani abin da kuke yi. Kukan cika bagaden Ubangiji da hawaye. Kukan yi kuka kuna ihu gama Ubangiji ba ya mai da hankali ga hadayunku ko yă karɓe su da farin ciki. ");
INSERT INTO hausa_vpl VALUES ("ML2_14","040_2_14","MAL","2","14","14","Kukan ce, “Don me ba ya karɓan hadayunmu?” Ai, domin Ubangiji ya zama shaida tsakaninka da matar ƙuruciyarka, gama ka keta amanar da ka yi mata, ko da yake ita abokiyar zamanka ce, matar aurenka ta alkawari. ");
INSERT INTO hausa_vpl VALUES ("ML2_15","040_2_15","MAL","2","15","15","Ashe, Ubangiji bai maishe su ɗaya ba? Cikin jiki da ruhu, su nasa ne. Me ya sa suke ɗaya? Domin yana neman ’ya’ya masu tsoron Allah. Saboda haka sai ka lura da kanka, kada kuma ka ci amanar matar ƙuruciyarka. ");
INSERT INTO hausa_vpl VALUES ("ML2_16","040_2_16","MAL","2","16","16","“Na ƙi kisan aure,” in ji Ubangiji, Allah na Isra’ila. “Na kuma ƙi mutumin da ya rufe kansa da tashin hankali kamar riga,” in ji Ubangiji Maɗaukaki. Saboda haka sai ka lura da kanka, kada kuma ka ci amana. ");
INSERT INTO hausa_vpl VALUES ("ML2_17","040_2_17","MAL","2","17","17","Kun sa Ubangiji Maɗaukaki ya gaji da maganganunku. Sai kuka ce, “Yaya muka sa ya gaji?” Kun yi haka ta wurin cewa, “Duk waɗanda suke aikata mugunta, mutanen kirki ne a gaban Ubangiji, yana kuwa jin daɗinsu,” kuna kuma cewa, “Ina Allah mai adalci yake?” ");
INSERT INTO hausa_vpl VALUES ("ML3_1","040_3_1","MAL","3","1","1","“Duba, zan aika manzona, wanda zai shirya hanya a gabana. Sa’an nan a farat ɗaya Ubangiji wanda kuke nema zai zo haikalinsa. Manzon alkawari, wanda kuke sa zuciya kuwa zai zo,” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML3_2","040_3_2","MAL","3","2","2","Amma wa zai jure wa ranar zuwansa? Wa zai iya tsaya sa’ad da ya bayyana? Gama zai zama kamar wuta mai tace ƙarfe, ko sabulu mai wanki. ");
INSERT INTO hausa_vpl VALUES ("ML3_3","040_3_3","MAL","3","3","3","Zai zama kamar mai tace azurfa da mai tsarkaketa; zai tsabtacce Lawiyawa, yă kuma tace su kamar zinariya da azurfa. Sa’an nan Ubangiji zai sami mutanen da za su kawo hadayu a cikin adalci. ");
INSERT INTO hausa_vpl VALUES ("ML3_4","040_3_4","MAL","3","4","4","Hadayun Yahuda da na Urushalima za su zama yardajje ga Ubangiji, za su zama kamar a kwanakin da suka wuce, kamar a shekarun baya. ");
INSERT INTO hausa_vpl VALUES ("ML3_5","040_3_5","MAL","3","5","5","“Ta haka zan zo kusa da ku don in yi hukunci. Zan hanzarta ba da shaida a kan masu yin sihiri, da mazinata da masu shaidar zur. Zan ba da shaida a kan waɗanda suke zaluntar ma’aikata a kan albashinsu, da waɗanda suke ƙwarar gwauraye da marayu, suna kuma hana baƙi samun adalci, ba sa ma tsorona,” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML3_6","040_3_6","MAL","3","6","6","“Ni Ubangiji ba na canjawa. Shi ya sa ku zuriyar Yaƙub, ba a hallaka ku ƙaƙaf ba. ");
INSERT INTO hausa_vpl VALUES ("ML3_7","040_3_7","MAL","3","7","7","Tun zamanin kakanninku, kun juye wa ƙa’idodina baya, ba ku kuma kiyaye su ba. Ku komo gare ni, ni kuma zan koma gare ku,” in ji Ubangiji Maɗaukaki. “Amma sai kuka ce, ‘Yaya za mu koma gare ka?’ ");
INSERT INTO hausa_vpl VALUES ("ML3_8","040_3_8","MAL","3","8","8","“Mutum zai iya yi wa Allah fashi ne? Duk da haka kun yi mini fashi. “Amma sai kuka ce, ‘Yaya muka yi maka fashi?’ “A wajen zakka da hadayu. ");
INSERT INTO hausa_vpl VALUES ("ML3_9","040_3_9","MAL","3","9","9","Kuna ƙarƙashin la’ana, dukan al’ummarku, domin kuna yin mini fashi. ");
INSERT INTO hausa_vpl VALUES ("ML3_10","040_3_10","MAL","3","10","10","Ku kawo dukan zakka cikin gidan ajiya, don a kasance da abinci a gidana. Ku gwada ni a wannan ku ga, ko ba zan buɗe taskokin sama in zubo muku albarka mai yawa, wadda har ba za ku rasa wurin sa ta ba, in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML3_11","040_3_11","MAL","3","11","11","Zan hana ƙwari su cinye hatsinku. Kuringar inabi a gonakinku kuma ba za su zubar da ’ya’yansu kafin su nuna ba,” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML3_12","040_3_12","MAL","3","12","12","“Sa’an nan dukan al’ummai za su ce da ku masu albarka, gama ƙasarku za tă yi daɗin zama,” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML3_13","040_3_13","MAL","3","13","13","“Kun faɗi mugayen abubuwa a kaina,” in ji Ubangiji. “Duk da haka kuka ce, ‘Me muka faɗa a kanka?’ ");
INSERT INTO hausa_vpl VALUES ("ML3_14","040_3_14","MAL","3","14","14","“Kun ce, ‘Ba amfani a bauta wa Allah. Wanda amfani muka samu ta wurin kiyaye umarnansa muna yawo kamar masu makoki a gaban Ubangiji Maɗaukaki? ");
INSERT INTO hausa_vpl VALUES ("ML3_15","040_3_15","MAL","3","15","15","A ganinmu, masu girman kai suna jin daɗi. Masu aikata mugunta kuwa ba arziki kaɗai suka yi ba, amma sukan gwada Allah da mugayen ayyukansu, su kuwa zauna lafiya.’ ” ");
INSERT INTO hausa_vpl VALUES ("ML3_16","040_3_16","MAL","3","16","16","Sa’an nan waɗanda suke tsoron Ubangiji suka yi magana da juna, Ubangiji kuwa ya kasa kunne ya kuma ji. A gabansa aka rubuta a littafin tarihi waɗanda suke tsoron Ubangiji, suna kuma girmama sunansa. ");
INSERT INTO hausa_vpl VALUES ("ML3_17","040_3_17","MAL","3","17","17","“A ranar da na shirya ajiyayyen mallakata, za su zama nawa,” in ji Ubangiji Maɗaukaki. “Zan ji kansu kamar yadda mahaifi cikin tausayi yakan ji kan ɗansa wanda yake masa hidima. ");
INSERT INTO hausa_vpl VALUES ("ML3_18","040_3_18","MAL","3","18","18","Za ku kuma ga bambanci tsakanin masu adalci da mugaye, tsakanin waɗanda suke wa Allah hidima da kuma waɗanda ba sa yi. ");
INSERT INTO hausa_vpl VALUES ("ML4_1","040_4_1","MAL","4","1","1","“Tabbatacce rana tana zuwa; za tă yi ƙuna kamar wutar maƙera. Dukan masu girman kai da kowane mai aikata mugunta zai zama ciyawa, wannan rana mai zuwa za tă ƙone su. Babu saiwa ko reshen da za a bar musu,” in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML4_2","040_4_2","MAL","4","2","2","Amma ku da kuke girmama sunana, ranar adalci za tă fito tare da warkarwa a fikafikanta. Za ku kuwa fita kuna tsalle kamar ’yan maruƙan da aka sake daga garke. ");
INSERT INTO hausa_vpl VALUES ("ML4_3","040_4_3","MAL","4","3","3","Sa’an nan za ku tattake mugaye; za su zama toka a ƙarƙashin tafin ƙafafunku a ranar da zan aikata waɗannan abubuwa, in ji Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("ML4_4","040_4_4","MAL","4","4","4","“Ku tuna da dokar bawana Musa, ƙa’idodi da dokokin da na ba shi a Horeb domin dukan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("ML4_5","040_4_5","MAL","4","5","5","“Ga shi, zan aika muku da annabi Iliya kafin babbar ranan nan mai banrazana ta Ubangiji tă zo. ");
INSERT INTO hausa_vpl VALUES ("ML4_6","040_4_6","MAL","4","6","6","Zai juye zukatan iyaye ga ’ya’yansu, zukatan ’ya’ya kuma ga iyayensu; in ba haka ba zan bugi ƙasar da hallaka gaba ɗaya.”");
INSERT INTO hausa_vpl VALUES ("MT1_1","070_1_1","MAT","1","1","1","Tarihin da aka rubuta game da asalin Yesu Kiristi ɗan Dawuda, ɗan Ibrahim. ");
INSERT INTO hausa_vpl VALUES ("MT1_2","070_1_2","MAT","1","2","2","Ibrahim ya haifi Ishaku, Ishaku ya haifi Yaƙub, Yaƙub ya haifi Yahuda da ’yan’uwansa, ");
INSERT INTO hausa_vpl VALUES ("MT1_3","070_1_3","MAT","1","3","3","Yahuda ya haifi Ferez da Zera, waɗanda Tamar ce mahaifiyarsu; Ferez ya haifi Hezron, Hezron ya haifi Ram, ");
INSERT INTO hausa_vpl VALUES ("MT1_4","070_1_4","MAT","1","4","4","Ram ya haifi Amminadab, Amminadab ya haifi Nashon, Nashon ya haifi Salmon, ");
INSERT INTO hausa_vpl VALUES ("MT1_5","070_1_5","MAT","1","5","5","Salmon ya haifi Bowaz, wanda Rahab ce mahaifiyarsa, Bowaz ya haifi Obed, wanda Rut ce mahaifiyarsa, Obed ya haifi Yesse, ");
INSERT INTO hausa_vpl VALUES ("MT1_6","070_1_6","MAT","1","6","6","Yesse kuwa ya haifi Sarki Dawuda. Dawuda ya haifi Solomon, wanda matar Uriya ce mahaifiyarsa. ");
INSERT INTO hausa_vpl VALUES ("MT1_7","070_1_7","MAT","1","7","7","Solomon ya haifi Rehobowam, Rehobowam ya haifi Abiya, Abiya ya haifi Asa, ");
INSERT INTO hausa_vpl VALUES ("MT1_8","070_1_8","MAT","1","8","8","Asa ya haifi Yehoshafat, Yehoshafat ya haifi Yehoram, Yehoram ya haifi Azariya, ");
INSERT INTO hausa_vpl VALUES ("MT1_9","070_1_9","MAT","1","9","9","Azariya ya haifi Yotam, Yotam ya haifi Ahaz, Ahaz ya haifi Hezekiya, ");
INSERT INTO hausa_vpl VALUES ("MT1_10","070_1_10","MAT","1","10","10","Hezekiya ya haifi Manasse, Manasse ya haifi Amon, Amon ya haifi Yosiya, ");
INSERT INTO hausa_vpl VALUES ("MT1_11","070_1_11","MAT","1","11","11","Yosiya kuma ya haifi Yekoniya da ’yan’uwansa a lokacin da aka kwashe su zuwa bauta a Babilon. ");
INSERT INTO hausa_vpl VALUES ("MT1_12","070_1_12","MAT","1","12","12","Bayan an kwashe su zuwa bauta a Babilon. Yekoniya ya haifi Sheyaltiyel, Sheyaltiyel ya haifi Zerubbabel, ");
INSERT INTO hausa_vpl VALUES ("MT1_13","070_1_13","MAT","1","13","13","Zerubbabel ya haifi Abiyud, Abiyud ya haifi Eliyakim, Eliyakim ya haifi Azor, ");
INSERT INTO hausa_vpl VALUES ("MT1_14","070_1_14","MAT","1","14","14","Azor ya haifi Zadok, Zadok ya haifi Akim, Akim kuma ya haifi Eliyud, ");
INSERT INTO hausa_vpl VALUES ("MT1_15","070_1_15","MAT","1","15","15","Eliyud ya haifi Eleyazar, Eleyazar ya haifi Mattan, Mattan ya haifi Yaƙub, ");
INSERT INTO hausa_vpl VALUES ("MT1_16","070_1_16","MAT","1","16","16","Yaƙub ya haifi Yusuf, mijin Maryamu, wadda ta haifi Yesu, wanda ake kira Kiristi. ");
INSERT INTO hausa_vpl VALUES ("MT1_17","070_1_17","MAT","1","17","17","Ta haka akwai zuriya goma sha huɗu ke nan duka-duka daga lokacin Ibrahim zuwa lokacin Dawuda, goma sha huɗu kuma daga Dawuda zuwa bauta a Babilon, goma sha huɗu kuma daga bauta a Babilon zuwa Kiristi. ");
INSERT INTO hausa_vpl VALUES ("MT1_18","070_1_18","MAT","1","18","18","Ga yadda haihuwar Yesu Kiristi ta kasance. An yi alkawarin auren mahaifiyarsa Maryamu, ga Yusuf. Amma tun kafin su zama miji da mata, sai aka tarar Maryamu tana da ciki, ta wurin Ruhu Mai Tsarki. ");
INSERT INTO hausa_vpl VALUES ("MT1_19","070_1_19","MAT","1","19","19","Yusuf mijinta, da yake shi mai adalci ne, bai so yă ba ta kunya, yă tone mata asiri a fili ba, sai ya yi tunani yă sake ta a ɓoye. ");
INSERT INTO hausa_vpl VALUES ("MT1_20","070_1_20","MAT","1","20","20","Amma yana cikin wannan tunani, sai wani mala’ikan Ubangiji ya bayyana masa cikin mafarki ya ce, “Yusuf ɗan Dawuda, kada ka ji tsoron ɗaukan Maryamu zuwa gidanka a matsayin matarka, gama cikin nan nata, daga wurin Ruhu Mai Tsarki ne. ");
INSERT INTO hausa_vpl VALUES ("MT1_21","070_1_21","MAT","1","21","21","Za tă haifi ɗa, za ka kuma sa masa suna Yesu, gama shi ne zai ceci mutanensa daga zunubansu.” ");
INSERT INTO hausa_vpl VALUES ("MT1_22","070_1_22","MAT","1","22","22","Duk wannan ya faru ne, don a cika abin da Ubangiji ya faɗi ta bakin annabin cewa, ");
INSERT INTO hausa_vpl VALUES ("MT1_23","070_1_23","MAT","1","23","23","“Ga shi budurwa za tă yi ciki, za tă haifi ɗa, kuma za a kira shi Immanuwel” (wanda yake nufin “Allah tare da mu”). ");
INSERT INTO hausa_vpl VALUES ("MT1_24","070_1_24","MAT","1","24","24","Da Yusuf ya farka daga barci, sai ya bi umarnin mala’ikan Ubangiji, ya ɗauki Maryamu zuwa gida a matsayin matarsa. ");
INSERT INTO hausa_vpl VALUES ("MT1_25","070_1_25","MAT","1","25","25","Amma bai kwana da ita ba, sai bayan da ta haifi ɗan. Ya kuwa sa masa suna Yesu. ");
INSERT INTO hausa_vpl VALUES ("MT2_1","070_2_1","MAT","2","1","1","Bayan an haifi Yesu a Betlehem, a Yahudiya, a zamanin Sarki Hiridus, sai waɗansu Masana, daga gabas suka zo Urushalima ");
INSERT INTO hausa_vpl VALUES ("MT2_2","070_2_2","MAT","2","2","2","suka yi tambaya suka ce, “Ina shi wanda aka haifa sarkin Yahudawa? Gama mun ga tauraronsa a gabas mun kuwa zo ne domin mu yi masa sujada.” ");
INSERT INTO hausa_vpl VALUES ("MT2_3","070_2_3","MAT","2","3","3","Da Sarki Hiridus ya ji wannan, sai hankalinsa ya tashi haka ma na dukan Urushalima. ");
INSERT INTO hausa_vpl VALUES ("MT2_4","070_2_4","MAT","2","4","4","Bayan ya kira dukan manyan firistoci da malaman dokoki na mutane wuri ɗaya, sai ya tambaye su inda za a haifi Kiristi. ");
INSERT INTO hausa_vpl VALUES ("MT2_5","070_2_5","MAT","2","5","5","Suka amsa suka ce, “A Betlehem ne, cikin Yahudiya, gama haka annabin ya rubuta. ");
INSERT INTO hausa_vpl VALUES ("MT2_6","070_2_6","MAT","2","6","6","“ ‘Amma ke Betlehem, a cikin ƙasar Yahuda, ba ke ce mafi ƙanƙanta a cikin masu mulki a Yahuda ba, gama daga cikinki mai mulki zai zo, wanda zai zama makiyayin mutanena Isra’ila.’” ");
INSERT INTO hausa_vpl VALUES ("MT2_7","070_2_7","MAT","2","7","7","Sai Hiridus ya kira Masanan nan a ɓoye, yă gano daga wurinsu daidai lokacin da tauraron ya bayyana. ");
INSERT INTO hausa_vpl VALUES ("MT2_8","070_2_8","MAT","2","8","8","Sai ya aike su Betlehem ya ce, “Ku je ku binciko a hankali game da yaron nan. Da kun same shi, sai ku kawo mini labari nan da nan, domin ni ma in je in yi masa sujada.” ");
INSERT INTO hausa_vpl VALUES ("MT2_9","070_2_9","MAT","2","9","9","Bayan sun saurari sarki, sai suka kama hanyarsu, tauraron da suka gani a gabas kuwa yana tafe a gabansu, sai da ya kai inda yaron yake. ");
INSERT INTO hausa_vpl VALUES ("MT2_10","070_2_10","MAT","2","10","10","Da suka ga tauraron, sai suka yi farin ciki ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("MT2_11","070_2_11","MAT","2","11","11","Suka shiga gidan, suka kuwa ga yaron tare da mahaifiyarsa Maryamu. Suka durƙusa har ƙasa, suka yi masa sujada. Sa’an nan suka kunce dukiyarsu, suka miƙa masa kyautai na zinariya da na turare da na mur. ");
INSERT INTO hausa_vpl VALUES ("MT2_12","070_2_12","MAT","2","12","12","Bayan an gargaɗe su cikin mafarki kada su koma wurin Hiridus, sai suka koma ƙasarsu ta wata hanya dabam. ");
INSERT INTO hausa_vpl VALUES ("MT2_13","070_2_13","MAT","2","13","13","Bayan sun tafi, sai mala’ikan Ubangiji ya bayyana ga Yusuf a mafarki ya ce, “Tashi, ka ɗauki yaron da mahaifiyarsa, ku gudu zuwa Masar. Ku zauna a can sai na gaya muku, gama Hiridus zai nemi yaron don yă kashe.” ");
INSERT INTO hausa_vpl VALUES ("MT2_14","070_2_14","MAT","2","14","14","Sai Yusuf ya tashi, ya ɗauki yaron da mahaifiyarsa da dad dare suka tafi Masar, ");
INSERT INTO hausa_vpl VALUES ("MT2_15","070_2_15","MAT","2","15","15","inda ya zauna har sai da Hiridus ya mutu. Ta haka kuwa aka cika abin da Ubangiji ya faɗa ta bakin annabin cewa, “Daga Masar na kira ɗana.” ");
INSERT INTO hausa_vpl VALUES ("MT2_16","070_2_16","MAT","2","16","16","Da Hiridus ya gane cewa Masanan nan sun yi masa wayo, sai ya husata ƙwarai, ya yi umarni cewa a karkashe dukan ’yan yara maza da suke a Betlehem da kewayenta, daga masu shekara biyu zuwa ƙasa, bisa ga lokacin da ya sami labarin daga Masanan nan. ");
INSERT INTO hausa_vpl VALUES ("MT2_17","070_2_17","MAT","2","17","17","Sai abin da aka faɗa ta bakin annabi Irmiya ya cika, cewa, ");
INSERT INTO hausa_vpl VALUES ("MT2_18","070_2_18","MAT","2","18","18","“An ji murya a Rama, tana kuka da makoki mai tsanani, Rahila ce take kuka domin ’ya’yanta, an kāsa ta’azantar da ita, don ba su.” ");
INSERT INTO hausa_vpl VALUES ("MT2_19","070_2_19","MAT","2","19","19","Bayan Hiridus ya mutu, sai mala’ikan Ubangiji ya bayyana ga Yusuf a mafarki a Masar, ");
INSERT INTO hausa_vpl VALUES ("MT2_20","070_2_20","MAT","2","20","20","ya ce, “Tashi, ka ɗauki yaron da mahaifiyarsa ku tafi ƙasar Isra’ila, domin waɗanda suke neman ran yaron sun mutu.” ");
INSERT INTO hausa_vpl VALUES ("MT2_21","070_2_21","MAT","2","21","21","Sai ya tashi, ya ɗauki yaron da mahaifiyarsa suka tafi ƙasar Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("MT2_22","070_2_22","MAT","2","22","22","Amma da ya ji Arkelawus ne yake mulki a Yahudiya a matsayin wanda ya gāji mahaifinsa Hiridus, sai ya ji tsoron zuwa can. Bayan an gargaɗe shi a mafarki, sai ya ratse zuwa gundumar Galili, ");
INSERT INTO hausa_vpl VALUES ("MT2_23","070_2_23","MAT","2","23","23","ya je ya zauna a wani garin da ake kira Nazaret. Ta haka aka cika abin da aka faɗa ta bakin annabawa cewa, “Za a ce da shi Banazare.” ");
INSERT INTO hausa_vpl VALUES ("MT3_1","070_3_1","MAT","3","1","1","A waɗancan kwanaki, Yohanna Mai Baftisma ya zo, yana wa’azi a Hamadan Yahudiya ");
INSERT INTO hausa_vpl VALUES ("MT3_2","070_3_2","MAT","3","2","2","yana cewa, “Ku tuba, gama mulkin sama ya yi kusa.” ");
INSERT INTO hausa_vpl VALUES ("MT3_3","070_3_3","MAT","3","3","3","Wannan shi ne wanda aka yi maganarsa ta wurin annabi Ishaya cewa, “Ga murya mai kira a hamada tana cewa, ‘Ku shirya wa Ubangiji hanya, ku miƙe hanyoyi dominsa.’ ” ");
INSERT INTO hausa_vpl VALUES ("MT3_4","070_3_4","MAT","3","4","4","Tufafin Yohanna kuwa an yi su da gashin raƙumi ne, yana kuma daure da ɗamara ta fata. Abincinsa kuwa fāri ne da zumar jeji. ");
INSERT INTO hausa_vpl VALUES ("MT3_5","070_3_5","MAT","3","5","5","Mutane suka zo wurinsa daga Urushalima da dukan Yahudiya da kuma dukan yankin Urdun. ");
INSERT INTO hausa_vpl VALUES ("MT3_6","070_3_6","MAT","3","6","6","Suna furta zunubansu, ya kuma yi musu baftisma a Kogin Urdun. ");
INSERT INTO hausa_vpl VALUES ("MT3_7","070_3_7","MAT","3","7","7","Amma da Yohanna ya ga Farisiyawa da Sadukiyawa da yawa suna zuwa inda yake yin baftisma, sai ya ce musu, “Ku macizai! Wa ya gargaɗe ku ku guje wa fushin nan mai zuwa? ");
INSERT INTO hausa_vpl VALUES ("MT3_8","070_3_8","MAT","3","8","8","Ku yi ayyukan da suka dace da tuba. ");
INSERT INTO hausa_vpl VALUES ("MT3_9","070_3_9","MAT","3","9","9","Kada ma ku yi tunani a ranku cewa, ‘Ai, Ibrahim ne mahaifinmu.’ Ina gaya muku cewa Allah zai iya tā da ’ya’ya wa Ibrahim daga cikin duwatsun nan. ");
INSERT INTO hausa_vpl VALUES ("MT3_10","070_3_10","MAT","3","10","10","An riga an sa bakin gatari a gindin itatuwa, kuma duk itacen da bai ba da ’ya’ya masu kyau ba, za a sare shi a jefa cikin wuta. ");
INSERT INTO hausa_vpl VALUES ("MT3_11","070_3_11","MAT","3","11","11","“Ina muku baftisma da ruwa domin tuba. Amma wani yana zuwa a bayana wanda ya fi ni iko, wanda ko takalmansa ma ban isa in ɗauka ba. Zai yi muku baftisma da Ruhu Mai Tsarki da kuma wuta. ");
INSERT INTO hausa_vpl VALUES ("MT3_12","070_3_12","MAT","3","12","12","Yana riƙe da matankaɗinsa, zai tankaɗe hatsinsa, yă kuma tattara alkamarsa a cikin rumbu, amma zai ƙone yayin da wutar da ba a iya kashewa.” ");
INSERT INTO hausa_vpl VALUES ("MT3_13","070_3_13","MAT","3","13","13","Sai Yesu ya zo daga Galili, ya je Urdun don Yohanna yă yi masa baftisma. ");
INSERT INTO hausa_vpl VALUES ("MT3_14","070_3_14","MAT","3","14","14","Amma Yohanna ya so yă hana shi, yana cewa, “Ina bukata ka yi mini baftisma, yaya kake zuwa wurina?” ");
INSERT INTO hausa_vpl VALUES ("MT3_15","070_3_15","MAT","3","15","15","Yesu ya amsa ya ce, “Bari yă zama haka yanzu; ya dace mu yi haka don mu cika dukan adalci.” Sa’an nan Yohanna ya yarda. ");
INSERT INTO hausa_vpl VALUES ("MT3_16","070_3_16","MAT","3","16","16","Nan da nan da aka yi wa Yesu baftisma, sai ya fito daga ruwa. A wannan lokaci sama ya buɗe, sai ya ga Ruhun Allah yana saukowa kamar kurciya ya kuwa sauka a kansa. ");
INSERT INTO hausa_vpl VALUES ("MT3_17","070_3_17","MAT","3","17","17","Sai murya daga sama ta ce, “Wannan shi ne Ɗana wanda nake ƙauna; wanda kuma nake jin daɗinsa ƙwarai.” ");
INSERT INTO hausa_vpl VALUES ("MT4_1","070_4_1","MAT","4","1","1","Sa’an nan Ruhu ya kai Yesu cikin hamada don Iblis yă gwada shi. ");
INSERT INTO hausa_vpl VALUES ("MT4_2","070_4_2","MAT","4","2","2","Bayan ya yi azumi yini arba’in da kuma dare arba’in, sai ya ji yunwa. ");
INSERT INTO hausa_vpl VALUES ("MT4_3","070_4_3","MAT","4","3","3","Sai mai gwajin ya zo wurinsa ya ce, “In kai Ɗan Allah ne, ka ce wa duwatsun nan su zama burodi.” ");
INSERT INTO hausa_vpl VALUES ("MT4_4","070_4_4","MAT","4","4","4","Yesu ya amsa ya ce, “A rubuce yake cewa, ‘Ba da abinci kaɗai mutum yake rayuwa ba, sai dai da kowace kalmar da take fitowa daga bakin Allah.’” ");
INSERT INTO hausa_vpl VALUES ("MT4_5","070_4_5","MAT","4","5","5","Sai Iblis ya kai shi birni mai tsarki, ya kai shi can wuri mafi tsayi duka na haikali. ");
INSERT INTO hausa_vpl VALUES ("MT4_6","070_4_6","MAT","4","6","6","Ya ce, “In kai Ɗan Allah ne, yi tsalle ka sauka ƙasa. Gama a rubuce yake, “ ‘Zai umarci mala’ikunsa game da kai, za su tallafe ka da hannuwansu, don kada ka buga ƙafarka a kan dutse.’” ");
INSERT INTO hausa_vpl VALUES ("MT4_7","070_4_7","MAT","4","7","7","Yesu ya amsa masa ya ce, “A rubuce yake kuma cewa, ‘Kada ka gwada Ubangiji Allahnka.’” ");
INSERT INTO hausa_vpl VALUES ("MT4_8","070_4_8","MAT","4","8","8","Har wa yau, Iblis ya kai shi bisa wani dutse mai tsawo sosai, ya nunnuna masa dukan mulkokin duniya da darajarsu. ");
INSERT INTO hausa_vpl VALUES ("MT4_9","070_4_9","MAT","4","9","9","Ya ce, “Zan ba ka dukan wannan, in za ka durƙusa ka yi mini sujada.” ");
INSERT INTO hausa_vpl VALUES ("MT4_10","070_4_10","MAT","4","10","10","Sai Yesu ya ce masa, “Rabu da ni, Shaiɗan! Gama a rubuce yake, ‘Yi wa Ubangiji Allahnka sujada, shi kaɗai kuma za ka bauta wa.’” ");
INSERT INTO hausa_vpl VALUES ("MT4_11","070_4_11","MAT","4","11","11","Sa’an nan Iblis ya bar shi, mala’iku kuwa suka zo suka yi masa hidima. ");
INSERT INTO hausa_vpl VALUES ("MT4_12","070_4_12","MAT","4","12","12","Da Yesu ya ji labari cewa an kulle Yohanna a kurkuku, sai ya koma zuwa Galili. ");
INSERT INTO hausa_vpl VALUES ("MT4_13","070_4_13","MAT","4","13","13","Ya bar Nazaret, ya je ya zauna a Kafarnahum, wadda take a bakin tafki wajen Zebulun da Naftali ");
INSERT INTO hausa_vpl VALUES ("MT4_14","070_4_14","MAT","4","14","14","don a cika abin da aka faɗa ta bakin annabi Ishaya cewa, ");
INSERT INTO hausa_vpl VALUES ("MT4_15","070_4_15","MAT","4","15","15","“Ƙasar Zebulun da ƙasar Naftali, da kuke a hanyar zuwa tekun Galili, a ƙetaren Urdun, wannan yankin Galili ta Al’ummai, ");
INSERT INTO hausa_vpl VALUES ("MT4_16","070_4_16","MAT","4","16","16","mutanen da suke zama cikin duhu sun ga babban haske; haske kuma ya haskaka a kan waɗanda suke zama a inuwar mutuwa.” ");
INSERT INTO hausa_vpl VALUES ("MT4_17","070_4_17","MAT","4","17","17","Tun daga wannan lokaci, Yesu ya fara wa’azi yana cewa, “Ku tuba, gama mulkin sama ya yi kusa.” ");
INSERT INTO hausa_vpl VALUES ("MT4_18","070_4_18","MAT","4","18","18","Da Yesu yana kan tafiya a bakin Tekun Galili, sai ya ga waɗansu ’yan’uwa guda biyu, Siman wanda ake kira Bitrus da ɗan’uwansa Andarawus. Suna jefa abin kamun kifi a tafki, gama su masunta ne. ");
INSERT INTO hausa_vpl VALUES ("MT4_19","070_4_19","MAT","4","19","19","Sai Yesu ya ce, “Zo, ku bi ni, ni kuwa zan mai da ku masu jan mutane zuwa wurina.” ");
INSERT INTO hausa_vpl VALUES ("MT4_20","070_4_20","MAT","4","20","20","Nan da nan suka bar abin kamun kifinsu suka bi shi. ");
INSERT INTO hausa_vpl VALUES ("MT4_21","070_4_21","MAT","4","21","21","Da ya ci gaba daga nan, sai ya ga waɗansu ’yan’uwa guda biyu, Yaƙub ɗan Zebedi da ɗan’uwansa Yohanna. Suna cikin jirgin ruwa tare da mahaifinsu Zebedi, suna shirya abin kamun kifinsu. Yesu ya kira su, ");
INSERT INTO hausa_vpl VALUES ("MT4_22","070_4_22","MAT","4","22","22","nan take suka bar jirgin ruwan da mahaifinsu suka kuwa bi Yesu. ");
INSERT INTO hausa_vpl VALUES ("MT4_23","070_4_23","MAT","4","23","23","Yesu ya zazzaga dukan Galili, yana koyarwa a cikin majami’unsu, yana wa’azin labari mai daɗi na mulkin sama, yana kuma warkar da kowace cuta da rashin lafiyar mutane. ");
INSERT INTO hausa_vpl VALUES ("MT4_24","070_4_24","MAT","4","24","24","Labarinsa ya bazu ko’ina a Suriya, mutane kuwa suka kawo masa dukan waɗanda suke fama da cututtuka iri-iri, da waɗanda suke da zafin ciwo, da masu aljanu, da waɗanda suke masu farfaɗiya, da shanyayyu, ya kuwa warkar da su. ");
INSERT INTO hausa_vpl VALUES ("MT4_25","070_4_25","MAT","4","25","25","Taron mutane mai yawa daga Galili, Dekafolis, Urushalima, Yahudiya da kuma yankin hayin Urdun suka bi shi. ");
INSERT INTO hausa_vpl VALUES ("MT5_1","070_5_1","MAT","5","1","1","Ganin taron mutane, sai ya hau kan gefen dutse ya zauna. Almajiransa kuwa suka zo wurinsa, ");
INSERT INTO hausa_vpl VALUES ("MT5_2","070_5_2","MAT","5","2","2","sai ya fara koya musu. Yana cewa, ");
INSERT INTO hausa_vpl VALUES ("MT5_3","070_5_3","MAT","5","3","3","“Masu albarka ne waɗanda suke matalauta a ruhu, gama mulkin sama nasu ne. ");
INSERT INTO hausa_vpl VALUES ("MT5_4","070_5_4","MAT","5","4","4","Masu albarka ne waɗanda suke makoki, gama za a yi musu ta’aziyya. ");
INSERT INTO hausa_vpl VALUES ("MT5_5","070_5_5","MAT","5","5","5","Masu albarka ne waɗanda suke masu tawali’u, gama za su gāji duniya. ");
INSERT INTO hausa_vpl VALUES ("MT5_6","070_5_6","MAT","5","6","6","Masu albarka ne waɗanda suke jin yunwa da ƙishirwa don gani an yi adalci, gama za a ƙosar da su. ");
INSERT INTO hausa_vpl VALUES ("MT5_7","070_5_7","MAT","5","7","7","Masu albarka ne waɗanda suke masu jinƙai, gama za a nuna musu jinƙai. ");
INSERT INTO hausa_vpl VALUES ("MT5_8","070_5_8","MAT","5","8","8","Masu albarka ne waɗanda suke masu tsabtar zuciya, gama za su ga Allah. ");
INSERT INTO hausa_vpl VALUES ("MT5_9","070_5_9","MAT","5","9","9","Masu albarka ne waɗanda suke masu ƙulla zumunci, gama za a kira su ’ya’yan Allah. ");
INSERT INTO hausa_vpl VALUES ("MT5_10","070_5_10","MAT","5","10","10","Masu albarka ne waɗanda ake tsananta musu don gani an yi adalci, gama mulkin sama nasu ne. ");
INSERT INTO hausa_vpl VALUES ("MT5_11","070_5_11","MAT","5","11","11","“Masu albarka ne ku, sa’ad da mutane suke zaginku, suna tsananta muku, suna kuma faɗin kowace irin muguwar magana a kanku saboda ni. ");
INSERT INTO hausa_vpl VALUES ("MT5_12","070_5_12","MAT","5","12","12","Ku yi murna ku kuma yi farin ciki, domin ladarku mai yawa ne a sama, gama haka suka tsananta wa annabawan da suka riga ku. ");
INSERT INTO hausa_vpl VALUES ("MT5_13","070_5_13","MAT","5","13","13","“Ku ne gishirin duniya, amma in gishiri ya rabu da daɗin ɗanɗanonsa, yaya za a sāke mai da daɗin ɗanɗanonsa? Ba shi da sauran amfani, sai dai a zubar da shi mutane kuma su tattaka. ");
INSERT INTO hausa_vpl VALUES ("MT5_14","070_5_14","MAT","5","14","14","“Ku ne hasken duniya. Birnin da yake a bisan tudu ba ya ɓoyuwa. ");
INSERT INTO hausa_vpl VALUES ("MT5_15","070_5_15","MAT","5","15","15","Mutane ba sa ƙuna fitila su rufe ta da murfi. A maimako, sukan ajiye ta a kan wurin ajiye fitila, takan kuma ba da haske ga kowa a cikin gida. ");
INSERT INTO hausa_vpl VALUES ("MT5_16","070_5_16","MAT","5","16","16","Haka ma, bari haskenku yă haskaka a gaban mutane, domin su ga ayyukanku masu kyau, su kuwa yabi Ubanku da yake cikin sama. ");
INSERT INTO hausa_vpl VALUES ("MT5_17","070_5_17","MAT","5","17","17","“Kada ku yi tsammani na zo ne domin in kawar da Doka ko kuma Annabawa; ban zo domin in kawar da su ba ne, sai dai domin in ciccika su. ");
INSERT INTO hausa_vpl VALUES ("MT5_18","070_5_18","MAT","5","18","18","Gaskiya nake gaya muku, kafin sama da ƙasa sun shuɗe, babu ko ɗan wasali, babu wani ɗigo ta kowace hanya da zai ɓace daga Dokar, sai an cika kome. ");
INSERT INTO hausa_vpl VALUES ("MT5_19","070_5_19","MAT","5","19","19","Duk wanda ya karya ɗaya daga cikin mafi ƙanƙanta na umarnan nan, ya kuma koya wa waɗansu su yi haka, za a ce da shi mafi ƙanƙanta a mulkin sama. Amma duk wanda ya aikata, ya kuma koyar da waɗannan umarnai, za a kira shi mai girma a cikin mulkin sama. ");
INSERT INTO hausa_vpl VALUES ("MT5_20","070_5_20","MAT","5","20","20","Gama ina faɗa muku cewa in dai adalcinku bai fi na Farisiyawa da na malaman dokoki ba, faufau, ba za ku shiga mulkin sama ba. ");
INSERT INTO hausa_vpl VALUES ("MT5_21","070_5_21","MAT","5","21","21","“Kun dai ji an faɗa wa mutanen dā cewa, ‘Kada ka yi kisankai;kuma duk wanda ya yi kisankai za a hukunta shi.’ ");
INSERT INTO hausa_vpl VALUES ("MT5_22","070_5_22","MAT","5","22","22","Amma ina gaya muku, duk wanda ya yi fushi da ɗan’uwansa, za a hukunta shi. Kuma duk wanda ya ce wa ɗan’uwansa ‘Raka,’za a kai shi gaban Majalisa. Amma duk wanda ya ce, ‘Kai wawa!’ Zai kasance a hatsarin shiga jahannama ta wuta. ");
INSERT INTO hausa_vpl VALUES ("MT5_23","070_5_23","MAT","5","23","23","“Saboda haka, in kana cikin ba da baikonka a kan bagade, a can kuwa ka tuna cewa ɗan’uwanka yana riƙe da kai a zuci, ");
INSERT INTO hausa_vpl VALUES ("MT5_24","070_5_24","MAT","5","24","24","sai ka bar baikonka a can gaban bagade. Ka je ka shirya tukuna da ɗan’uwanka; sa’an nan ka zo ka ba da baikonka. ");
INSERT INTO hausa_vpl VALUES ("MT5_25","070_5_25","MAT","5","25","25","“Ka yi hanzari ka shirya al’amura da maƙiyinka wanda yake ƙararka a kotu. Ka yi haka, tun kana tare da shi a kan hanya, in ba haka ba, zai miƙa ka ga alƙali, alƙali kuma yă miƙa ka ga ɗan sanda, mai yiwuwa kuwa a jefa ka a kurkuku. ");
INSERT INTO hausa_vpl VALUES ("MT5_26","070_5_26","MAT","5","26","26","Gaskiya nake gaya maka, ba za ka fita ba, sai ka biya kobo na ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("MT5_27","070_5_27","MAT","5","27","27","“Kun dai ji an faɗa, ‘Kada ka yi zina.’ ");
INSERT INTO hausa_vpl VALUES ("MT5_28","070_5_28","MAT","5","28","28","Amma ina gaya muku, duk wanda ya dubi mace, sa’an nan ya yi sha’awarta a zuci, ya riga ya yi zina ke nan da ita a zuciyarsa. ");
INSERT INTO hausa_vpl VALUES ("MT5_29","070_5_29","MAT","5","29","29","In idonka na dama yana sa ka yin zunubi, ƙwaƙule shi ka yar. Zai fiye maka ka rasa ɗaya daga cikin gaɓoɓin jikinka, da a jefa jikinka ɗungum a cikin jahannama ta wuta. ");
INSERT INTO hausa_vpl VALUES ("MT5_30","070_5_30","MAT","5","30","30","In kuma hannunka na dama yana sa ka yin zunubi, yanke shi ka yar. Zai fiye maka ka rasa ɗaya daga cikin gaɓoɓin jikinka, da a jefa jikinka ɗungum a cikin jahannama ta wuta. ");
INSERT INTO hausa_vpl VALUES ("MT5_31","070_5_31","MAT","5","31","31","“An kuma faɗa, ‘Duk wanda ya saki matarsa, dole yă ba ta takardar saki.’ ");
INSERT INTO hausa_vpl VALUES ("MT5_32","070_5_32","MAT","5","32","32","Amma ina gaya muku, duk wanda ya saki matarsa in ba a kan laifin zina ba, ya sa ta zama mazinaciya ke nan, kuma duk wanda ya auri macen da mijinta ya sake, shi ma yana zina ne. ");
INSERT INTO hausa_vpl VALUES ("MT5_33","070_5_33","MAT","5","33","33","“Har wa yau dai kun ji an faɗa wa mutane a dā, ‘Kada ka karya alkawarinka, sai dai ka cika alkawaran da ka yi wa Ubangiji.’ ");
INSERT INTO hausa_vpl VALUES ("MT5_34","070_5_34","MAT","5","34","34","Amma ina gaya muku, Kada ku yi rantsuwa sam, ko da sama, domin kursiyin Allah ne; ");
INSERT INTO hausa_vpl VALUES ("MT5_35","070_5_35","MAT","5","35","35","ko da ƙasa, domin matashin ƙafafunsa ne; ko kuma da Urushalima, domin birnin Babban Sarki ne. ");
INSERT INTO hausa_vpl VALUES ("MT5_36","070_5_36","MAT","5","36","36","Kada kuma ka rantse da kanka, domin ba za ka iya mai da ko gashi ɗaya yă zama fari ko baƙi ba. ");
INSERT INTO hausa_vpl VALUES ("MT5_37","070_5_37","MAT","5","37","37","Abin da ya kamata ku ce kawai, shi ne, I, ko A’a. Abin da ya wuce haka kuwa daga wurin Mugun nan yake. ");
INSERT INTO hausa_vpl VALUES ("MT5_38","070_5_38","MAT","5","38","38","“Kun dai ji an faɗa, ‘Ido domin ido, haƙori kuma domin haƙori.’ ");
INSERT INTO hausa_vpl VALUES ("MT5_39","070_5_39","MAT","5","39","39","Amma ina gaya muku, Kada ku yi tsayayya da mugun mutum. In wani ya mare ka a kumatun dama, juya masa ɗayan ma. ");
INSERT INTO hausa_vpl VALUES ("MT5_40","070_5_40","MAT","5","40","40","In kuma wani yana so yă yi ƙararka yă ƙwace rigarka, to, ba shi mayafinka ma. ");
INSERT INTO hausa_vpl VALUES ("MT5_41","070_5_41","MAT","5","41","41","In wani ya tilasta ka yin tafiya mil ɗaya, to, tafi tare da shi mil biyu. ");
INSERT INTO hausa_vpl VALUES ("MT5_42","070_5_42","MAT","5","42","42","Ka ba wa duk wanda ya roƙe ka abu, kada kuma ka hana wa wanda yake neman bashi daga gare ka. ");
INSERT INTO hausa_vpl VALUES ("MT5_43","070_5_43","MAT","5","43","43","“Kun dai ji an faɗa, ‘Ka ƙaunaci maƙwabcinka,ka kuma ƙi abokin gābanka.’ ");
INSERT INTO hausa_vpl VALUES ("MT5_44","070_5_44","MAT","5","44","44","Amma ina gaya muku, ku ƙaunaci abokan gābankukuma ku yi wa waɗanda suke tsananta muku addu’a, ");
INSERT INTO hausa_vpl VALUES ("MT5_45","070_5_45","MAT","5","45","45","don ku zama ’ya’yan Ubanku na sama. Shi yakan sa ranarsa ta haskaka a kan mugaye da masu kirki; yakan kuma sako ruwan sama a bisa masu adalci da marasa adalci. ");
INSERT INTO hausa_vpl VALUES ("MT5_46","070_5_46","MAT","5","46","46","In masoyarku kawai kuke ƙauna, wace lada ce gare ku? Ko masu karɓar haraji ma ba haka suke yi ba? ");
INSERT INTO hausa_vpl VALUES ("MT5_47","070_5_47","MAT","5","47","47","In kuwa kuna gai da ’yan’uwanku ne kaɗai, me kuke yi fiye da waɗansu? Marasa bin Allah ma ba haka suke yi ba? ");
INSERT INTO hausa_vpl VALUES ("MT5_48","070_5_48","MAT","5","48","48","Saboda haka sai ku zama cikakku, yadda Ubanku na sama yake cikakke. ");
INSERT INTO hausa_vpl VALUES ("MT6_1","070_6_1","MAT","6","1","1","“Ku yi hankali kada ku nuna ‘ayyukanku na adalci’ a gaban mutane, don su gani. In kuka yi haka, ba za ku sami lada daga wurin Ubanku da yake cikin sama ba. ");
INSERT INTO hausa_vpl VALUES ("MT6_2","070_6_2","MAT","6","2","2","“Saboda haka sa’ad da kake ba wa masu bukata taimako, kada ka yi shelarsa, yadda munafukai suke yi a majami’u da kuma kan tituna, don mutane su yabe su. Gaskiya nake gaya muku, sun riga sun sami ladarsu cikakke. ");
INSERT INTO hausa_vpl VALUES ("MT6_3","070_6_3","MAT","6","3","3","Amma sa’ad da kake ba wa masu bukata taimako, kada ka yarda hannun hagunka yă ma san abin da hannun damarka yake yi, ");
INSERT INTO hausa_vpl VALUES ("MT6_4","070_6_4","MAT","6","4","4","don bayarwarka ta zama a ɓoye. Ubanka kuwa mai ganin abin da ake yi a ɓoye, zai sāka maka. ");
INSERT INTO hausa_vpl VALUES ("MT6_5","070_6_5","MAT","6","5","5","“Sa’ad da kuma kuke addu’a, kada ku zama kamar munafukai, gama sun cika son yin addu’a a tsaye a cikin majami’u da kuma a bakin titi, don mutane su gan su. Gaskiya nake gaya muku, sun riga sun sami ladarsu cikakke. ");
INSERT INTO hausa_vpl VALUES ("MT6_6","070_6_6","MAT","6","6","6","Amma sa’ad da kake addu’a, sai ka shiga ɗakinka, ka rufe ƙofa, ka yi addu’a ga Ubanka wanda ba a gani. Ubanka kuwa mai ganin abin da ake yi a ɓoye, zai sāka maka. ");
INSERT INTO hausa_vpl VALUES ("MT6_7","070_6_7","MAT","6","7","7","Sa’ad da kuma kuke addu’a, kada ku yi ta maimaita magana, kamar marasa sanin Allah, domin suna tsammani za a ji su saboda yawan maganarsu. ");
INSERT INTO hausa_vpl VALUES ("MT6_8","070_6_8","MAT","6","8","8","Kada ku zama kamar su, gama Ubanku ya san abin da kuke bukata kafin ma ku roƙe shi. ");
INSERT INTO hausa_vpl VALUES ("MT6_9","070_6_9","MAT","6","9","9","“To, ga yadda ya kamata ku yi addu’a. “ ‘Ubanmu wanda yake cikin sama, a tsarkake sunanka, ");
INSERT INTO hausa_vpl VALUES ("MT6_10","070_6_10","MAT","6","10","10","mulkinka yă zo a aikata nufinka a duniya kamar yadda ake yi a sama. ");
INSERT INTO hausa_vpl VALUES ("MT6_11","070_6_11","MAT","6","11","11","Ka ba mu yau abincin yininmu. ");
INSERT INTO hausa_vpl VALUES ("MT6_12","070_6_12","MAT","6","12","12","Ka gafarta mana laifofinmu, kamar yadda mu ma muke gafarta wa masu yin mana laifi. ");
INSERT INTO hausa_vpl VALUES ("MT6_13","070_6_13","MAT","6","13","13","Kada ka bari a kai mu cikin jarraba, amma ka cece mu daga mugun nan.’ ");
INSERT INTO hausa_vpl VALUES ("MT6_14","070_6_14","MAT","6","14","14","Gama in kuna yafe wa mutane sa’ad da suka yi muku laifi, Ubanku da yake cikin sama ma zai gafarta muku. ");
INSERT INTO hausa_vpl VALUES ("MT6_15","070_6_15","MAT","6","15","15","Amma in ba kwa yafe wa mutane laifofinsu, Ubanku ma ba zai gafarta muku zunubanku ba. ");
INSERT INTO hausa_vpl VALUES ("MT6_16","070_6_16","MAT","6","16","16","“Sa’ad da kuma kuna azumi, kada ku ɓata fuska, yadda munafukai suke yi. Sukan ɓata fuskokinsu domin su nuna wa mutane cewa suna azumi. Gaskiya nake gaya muku, sun riga sun sami ladarsu cikakke. ");
INSERT INTO hausa_vpl VALUES ("MT6_17","070_6_17","MAT","6","17","17","Amma sa’ad da kana azumi, ka shafa wa kanka mai, ka wanke fuskarka, ");
INSERT INTO hausa_vpl VALUES ("MT6_18","070_6_18","MAT","6","18","18","domin kada mutane su ga alama cewa kana azumi, sai dai Ubanka kaɗai wanda ba a gani; Ubanka kuwa mai ganin abin da ake yi a ɓoye, zai sāka maka. ");
INSERT INTO hausa_vpl VALUES ("MT6_19","070_6_19","MAT","6","19","19","“Kada ku yi wa kanku ajiyar dukiya a duniya, inda asu da tsatsa suke ɓatawa, inda kuma ɓarayi sukan fasa, su yi sata. ");
INSERT INTO hausa_vpl VALUES ("MT6_20","070_6_20","MAT","6","20","20","Amma ku yi wa kanku ajiyar dukiya a sama, inda ba tsatsa da asu da za su ɓata su, inda kuma ba ɓarayin da za su fasa, su yi sata. ");
INSERT INTO hausa_vpl VALUES ("MT6_21","070_6_21","MAT","6","21","21","Gama inda dukiyarka take, a nan ne fa zuciyarka za tă kasance. ");
INSERT INTO hausa_vpl VALUES ("MT6_22","070_6_22","MAT","6","22","22","“Ido shi ne fitilar jiki. In idanunka suna da kyau, dukan jikinka zai cika da haske. ");
INSERT INTO hausa_vpl VALUES ("MT6_23","070_6_23","MAT","6","23","23","Amma in idanunka suna da lahani, dukan jikinka ma zai cika da duhu. To, in hasken da yake a cikinka duhu ne, duhun ya wuce misali ke nan! ");
INSERT INTO hausa_vpl VALUES ("MT6_24","070_6_24","MAT","6","24","24","“Ba mai iya bauta wa iyayengiji biyu. Ko dai yă ƙi ɗaya, yă ƙaunaci ɗaya, ko kuwa yă yi aminci ga ɗaya, sa’an nan yă rena ɗayan. Ba dama ku bauta wa Allah, ku kuma bauta wa kuɗi gaba ɗaya.” ");
INSERT INTO hausa_vpl VALUES ("MT6_25","070_6_25","MAT","6","25","25","“Saboda haka, ina gaya muku, kada ku damu game da rayuwarku, game da abin da za ku ci, ko abin da za ku sha; ko kuma game da jikinku, game da abin da za ku sa. Ashe, rai bai fi abinci ba, jiki kuma bai fi tufafi ba? ");
INSERT INTO hausa_vpl VALUES ("MT6_26","070_6_26","MAT","6","26","26","Ku dubi tsuntsayen sararin sama mana; ba sa shuki ko girbi ko ajiya a rumbuna, duk da haka, Ubanku na sama yana ciyar da su. Ashe, ba ku fi su daraja nesa ba? ");
INSERT INTO hausa_vpl VALUES ("MT6_27","070_6_27","MAT","6","27","27","Wane ne a cikinku ta wurin damuwa zai iya ƙara wa rayuwarsa ko sa’a ɗaya? ");
INSERT INTO hausa_vpl VALUES ("MT6_28","070_6_28","MAT","6","28","28","“Me ya sa kuke damuwa a kan riguna? Ku dubi yadda furannin jeji suke girma mana. Ba sa aiki ko saƙa. ");
INSERT INTO hausa_vpl VALUES ("MT6_29","070_6_29","MAT","6","29","29","Duk da haka ina gaya muku ko Solomon cikin dukan darajarsa bai sa kayan adon da ya kai na ko ɗaya a cikinsu ba. ");
INSERT INTO hausa_vpl VALUES ("MT6_30","070_6_30","MAT","6","30","30","In haka Allah yake yi wa ciyawar jeji sutura, wadda yau tana nan, gobe kuwa a jefa a cikin wuta, ba zai ma fi yi muku sutura ba, ya ku masu ƙarancin bangaskiya? ");
INSERT INTO hausa_vpl VALUES ("MT6_31","070_6_31","MAT","6","31","31","Don haka, kada ku damu, kuna cewa, ‘Me za mu ci?’ Ko, ‘Me za mu sha?’ Ko kuma, ‘Me za mu sa?’ ");
INSERT INTO hausa_vpl VALUES ("MT6_32","070_6_32","MAT","6","32","32","Gama marasa sanin Allah suna fama neman dukan waɗannan abubuwa, Ubanku na sama kuwa ya san kuna bukatarsu. ");
INSERT INTO hausa_vpl VALUES ("MT6_33","070_6_33","MAT","6","33","33","Da farko dai, ku nemi mulkin Allah da kuma adalcinsa, za a kuwa ba ku dukan waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("MT6_34","070_6_34","MAT","6","34","34","Saboda haka kada ku damu game da gobe, gama gobe zai damu da kansa. Damuwar yau ma ta isa wahala. ");
INSERT INTO hausa_vpl VALUES ("MT7_1","070_7_1","MAT","7","1","1","“Kada ku ba wa kowa laifi, don kada a ba ku laifi ku ma. ");
INSERT INTO hausa_vpl VALUES ("MT7_2","070_7_2","MAT","7","2","2","Gama da irin shari’ar da kuka yi wa waɗansu, da ita za a shari’anta ku. Mudun da kuka yi awo da shi, da shi za a yi muku. ");
INSERT INTO hausa_vpl VALUES ("MT7_3","070_7_3","MAT","7","3","3","“Don me kake duban ɗan tsinken da yake idon ɗan’uwanka, alhali kuwa ga gungume a naka ido? ");
INSERT INTO hausa_vpl VALUES ("MT7_4","070_7_4","MAT","7","4","4","Yaya za ka ce wa ɗan’uwanka, ‘Bari in cire maka ɗan tsinken nan daga idonka,’ alhali kuwa a kowane lokaci akwai gungume a naka ido? ");
INSERT INTO hausa_vpl VALUES ("MT7_5","070_7_5","MAT","7","5","5","Kai munafuki, fara cire gungumen da yake idonka, a sa’an nan ne za ka iya gani sosai yadda za ka cire ɗan tsinken da yake a idon ɗan’uwanka. ");
INSERT INTO hausa_vpl VALUES ("MT7_6","070_7_6","MAT","7","6","6","“Kada ku ba karnuka abin da yake mai tsarki; kada kuma ku jefa wa aladu lu’ulu’anku. In kuka yi haka za su tattake su, sa’an nan su juyo su jijji muku ciwo. ");
INSERT INTO hausa_vpl VALUES ("MT7_7","070_7_7","MAT","7","7","7","“Ku roƙa za a ba ku; ku nema za ku samu; ku ƙwanƙwasa za a kuwa buɗe muku ƙofa. ");
INSERT INTO hausa_vpl VALUES ("MT7_8","070_7_8","MAT","7","8","8","Gama duk wanda ya roƙa, akan ba shi; wanda ya nema kuwa, yakan samu, wanda kuma ya ƙwanƙwasa, za a buɗe masa ƙofa. ");
INSERT INTO hausa_vpl VALUES ("MT7_9","070_7_9","MAT","7","9","9","“Wane ne a cikinku in ɗansa ya roƙe shi burodi, sai yă ba shi dutse? ");
INSERT INTO hausa_vpl VALUES ("MT7_10","070_7_10","MAT","7","10","10","Ko kuwa in ya roƙe shi kifi, sai yă ba shi maciji? ");
INSERT INTO hausa_vpl VALUES ("MT7_11","070_7_11","MAT","7","11","11","In ku da kuke mugaye kun san yadda za ku ba da kyautai masu kyau ga ’ya’yanku, balle Ubanku na sama, ba zai fi ku iya ba da abubuwa masu kyau, ga su waɗanda suka roƙe shi ba! ");
INSERT INTO hausa_vpl VALUES ("MT7_12","070_7_12","MAT","7","12","12","Saboda haka, duk abin da kuke so mutane su yi muku, ku ma sai ku yi musu, domin wannan shi ne Doka da koyarwar Annabawa sun ƙunsa. ");
INSERT INTO hausa_vpl VALUES ("MT7_13","070_7_13","MAT","7","13","13","“Ku shiga ta matsattsiyar ƙofa. Gama ƙofar zuwa hallaka faɗaɗɗiya ce mai sauƙin bi kuma, masu shiga ta cikinta kuwa suna da yawa. ");
INSERT INTO hausa_vpl VALUES ("MT7_14","070_7_14","MAT","7","14","14","Amma ƙofar zuwa rai, ƙarama ce matsattsiya kuma, masu samunta kuwa kaɗan ne. ");
INSERT INTO hausa_vpl VALUES ("MT7_15","070_7_15","MAT","7","15","15","“Ku yi hankali da annabawan ƙarya. Sukan zo muku da kamannin tumaki, amma daga ciki mugayen kyarketai ne. ");
INSERT INTO hausa_vpl VALUES ("MT7_16","070_7_16","MAT","7","16","16","Ta wurin aikinsu za ku gane su. Mutane suna iya tsinkan inabi a jikin ƙaya, ko kuwa ɓaure a jikin sarƙaƙƙiya? ");
INSERT INTO hausa_vpl VALUES ("MT7_17","070_7_17","MAT","7","17","17","Haka ma kowane itace mai kyau yakan ba da ’ya’ya masu kyau, kuma mummunan itace ba ya ba da ’ya’ya masu kyau. ");
INSERT INTO hausa_vpl VALUES ("MT7_18","070_7_18","MAT","7","18","18","Itace mai kyau ba ya ba da munanan ’ya’ya, haka kuma mummunan itace ba ya ba da ’ya’ya masu kyau. ");
INSERT INTO hausa_vpl VALUES ("MT7_19","070_7_19","MAT","7","19","19","Duk itacen da ba ya ba da ’ya’ya masu kyau sai a sare shi a jefa cikin wuta. ");
INSERT INTO hausa_vpl VALUES ("MT7_20","070_7_20","MAT","7","20","20","Ta haka, ta wurin aikinsu za ku gane su.” ");
INSERT INTO hausa_vpl VALUES ("MT7_21","070_7_21","MAT","7","21","21","“Ba duk mai ce mini, ‘Ubangiji, Ubangiji,’ ne zai shiga mulkin sama ba, sai dai wanda yake aikata nufin Ubana da yake sama. ");
INSERT INTO hausa_vpl VALUES ("MT7_22","070_7_22","MAT","7","22","22","Da yawa za su ce mini a wannan rana, ‘Ubangiji, Ubangiji, ashe, ba mu yi annabci a cikin sunanka ba, ba kuma a cikin sunanka ne muka fitar da aljanu, muka yi abubuwan banmamaki da yawa ba?’ ");
INSERT INTO hausa_vpl VALUES ("MT7_23","070_7_23","MAT","7","23","23","Sa’an nan zan ce musu a fili, ‘Ban taɓa saninku ba. Ku rabu da ni, ku masu aikata mugunta!’ ");
INSERT INTO hausa_vpl VALUES ("MT7_24","070_7_24","MAT","7","24","24","“Saboda haka duk wanda yake jin kalmomin nan nawa yake kuma aikata su, yana kama da mutum mai hikima wanda ya gina gidansa a kan dutse. ");
INSERT INTO hausa_vpl VALUES ("MT7_25","070_7_25","MAT","7","25","25","Ruwan sama ya sauko, rafuffuka suka cika, iska kuma ta hura ta bugi gidan; duk da haka bai fāɗi ba, gama yana da harsashinsa a kan dutse. ");
INSERT INTO hausa_vpl VALUES ("MT7_26","070_7_26","MAT","7","26","26","Amma duk wanda yake jin kalmomin nan nawa bai kuwa aikata su ba, yana kama da wani wawa wanda ya gina gidansa a kan yashi. ");
INSERT INTO hausa_vpl VALUES ("MT7_27","070_7_27","MAT","7","27","27","Ruwan sama ya sauko, rafuffuka suka cika, iska kuwa ta hura ta bugi gidan, sai ya fāɗi da mummunar ragargajewa kuwa.” ");
INSERT INTO hausa_vpl VALUES ("MT7_28","070_7_28","MAT","7","28","28","Sa’ad da Yesu ya gama faɗin waɗannan abubuwa, sai taron mutanen suka yi mamakin koyarwarsa, ");
INSERT INTO hausa_vpl VALUES ("MT7_29","070_7_29","MAT","7","29","29","domin ya koyar kamar wani wanda yake da iko, ba kamar malamansu na dokoki ba. ");
INSERT INTO hausa_vpl VALUES ("MT8_1","070_8_1","MAT","8","1","1","Da ya sauko daga dutsen, sai taron mutane mai yawan gaske suka bi shi. ");
INSERT INTO hausa_vpl VALUES ("MT8_2","070_8_2","MAT","8","2","2","Wani mutum mai kuturta ya zo ya durƙusa a gabansa ya ce, “Ubangiji, in kana so, kana iya tsabtacce ni.” ");
INSERT INTO hausa_vpl VALUES ("MT8_3","070_8_3","MAT","8","3","3","Yesu ya miƙa hannunsa ya taɓa mutumin. Ya ce, “Ina so, ka tsabtacce!” Nan da nan aka warkar da shi daga kuturtarsa. ");
INSERT INTO hausa_vpl VALUES ("MT8_4","070_8_4","MAT","8","4","4","Sai Yesu ya ce masa, “Ka lura kada ka gaya wa kowa. Sai dai ka tafi, ka nuna kanka ga firist ka kuma yi bayarwar da Musa ya umarta, a matsayin shaida gare su.” ");
INSERT INTO hausa_vpl VALUES ("MT8_5","070_8_5","MAT","8","5","5","Da Yesu ya shiga Kafarnahum, sai wani jarumi ya zo wurinsa, yana neman taimako. ");
INSERT INTO hausa_vpl VALUES ("MT8_6","070_8_6","MAT","8","6","6","Ya ce, “Ubangiji, bawana yana kwance a gida shanyayye, yana kuma shan azaba ƙwarai.” ");
INSERT INTO hausa_vpl VALUES ("MT8_7","070_8_7","MAT","8","7","7","Yesu ya ce masa, “Zan je in warkar da shi.” ");
INSERT INTO hausa_vpl VALUES ("MT8_8","070_8_8","MAT","8","8","8","Jarumin ya amsa, “Ubangiji, ban cancanci in sa ka zo gidana ba, ka dai yi magana kawai, bawana zai warke. ");
INSERT INTO hausa_vpl VALUES ("MT8_9","070_8_9","MAT","8","9","9","Gama ni kaina mutum ne a ƙarƙashin iko, da kuma sojoji a ƙarƙashina. Nakan ce wa wannan, ‘Je ka,’ sai yă tafi; wancan kuma, ‘Zo nan,’ sai yă zo. Nakan ce wa bawana, ‘Yi wannan,’ sai kuwa yă yi.” ");
INSERT INTO hausa_vpl VALUES ("MT8_10","070_8_10","MAT","8","10","10","Da Yesu ya ji wannan, sai ya yi mamaki ya kuma ce wa waɗanda suke binsa, “Gaskiya nake gaya muku, ban taɓa samun wani a Isra’ila da bangaskiya mai girma haka ba. ");
INSERT INTO hausa_vpl VALUES ("MT8_11","070_8_11","MAT","8","11","11","Ina kuma gaya muku da yawa za su zo daga gabas da kuma yamma, su ɗauki wuraren zamansu a biki tare da Ibrahim, Ishaku, da Yaƙub a cikin mulkin sama. ");
INSERT INTO hausa_vpl VALUES ("MT8_12","070_8_12","MAT","8","12","12","Amma za a jefar da ’ya’yan mulki waje, zuwa cikin baƙin duhu, inda za a yi kuka da cizon haƙora.” ");
INSERT INTO hausa_vpl VALUES ("MT8_13","070_8_13","MAT","8","13","13","Sa’an nan Yesu ya ce wa jarumin, “Je ka! Za a yi bisa ga bangaskiyarka.” A daidai wannan lokaci bawansa kuwa ya warke. ");
INSERT INTO hausa_vpl VALUES ("MT8_14","070_8_14","MAT","8","14","14","Da Yesu ya zo cikin gidan Bitrus, sai ya ga surukar Bitrus tana kwance a gado tana da zazzaɓi. ");
INSERT INTO hausa_vpl VALUES ("MT8_15","070_8_15","MAT","8","15","15","Ya taɓa hannunta sai zazzaɓin ya sake ta, ta kuwa tashi ta fara yin masa hidima. ");
INSERT INTO hausa_vpl VALUES ("MT8_16","070_8_16","MAT","8","16","16","Da yamma ta yi, aka kawo masa masu aljanu da yawa, ya kuwa fitar da ruhohin ta wurin magana, ya kuma warkar da dukan marasa lafiya. ");
INSERT INTO hausa_vpl VALUES ("MT8_17","070_8_17","MAT","8","17","17","Wannan ya faru ne domin a cika abin da aka faɗa ta bakin annabi Ishaya cewa, “Ya ɗebi rashin lafiyarmu, ya kuma ɗauki cututtukanmu.” ");
INSERT INTO hausa_vpl VALUES ("MT8_18","070_8_18","MAT","8","18","18","Da Yesu ya ga taron mutane kewaye da shi, sai ya ba da umarni a ƙetare zuwa ɗayan hayin tafkin. ");
INSERT INTO hausa_vpl VALUES ("MT8_19","070_8_19","MAT","8","19","19","Sai wani malamin dokoki ya zo wurinsa ya ce, “Malam, zan bi ka duk inda za ka.” ");
INSERT INTO hausa_vpl VALUES ("MT8_20","070_8_20","MAT","8","20","20","Sai Yesu ya amsa ya ce, “Yanyawa suna da ramummuka, tsuntsayen sararin sama suna da sheƙuna, amma Ɗan Mutum ba shi da wurin da zai sa kansa.” ");
INSERT INTO hausa_vpl VALUES ("MT8_21","070_8_21","MAT","8","21","21","Sai wani almajiri ya ce masa, “Ubangiji, da farko bari in je in binne mahaifina.” ");
INSERT INTO hausa_vpl VALUES ("MT8_22","070_8_22","MAT","8","22","22","Amma Yesu ya ce masa, “Ka bi ni, ka bar matattu su binne matattunsu.” ");
INSERT INTO hausa_vpl VALUES ("MT8_23","070_8_23","MAT","8","23","23","Sai ya shiga jirgin ruwa, almajiransa kuwa suka bi shi. ");
INSERT INTO hausa_vpl VALUES ("MT8_24","070_8_24","MAT","8","24","24","Ba zato ba tsammani, sai wani babban hadari ya taso a tafkin, har raƙuman ruwan suka sha kan jirgin. Amma Yesu yana barci. ");
INSERT INTO hausa_vpl VALUES ("MT8_25","070_8_25","MAT","8","25","25","Almajiran suka je suka tashe shi, suna cewa, “Ubangiji, ka cece mu! Za mu nutse!” ");
INSERT INTO hausa_vpl VALUES ("MT8_26","070_8_26","MAT","8","26","26","Ya amsa ya ce, “Ku masu ƙarancin bangaskiya, me ya sa kuke tsoro haka?” Sa’an nan ya tashi ya tsawata wa iskar da kuma raƙuman ruwan, sai wuri ya yi tsit gaba ɗaya. ");
INSERT INTO hausa_vpl VALUES ("MT8_27","070_8_27","MAT","8","27","27","Mutanen suka yi mamaki suka ce, “Wane irin mutum ne wannan? Har iska da raƙuman ruwa suna masa biyayya!” ");
INSERT INTO hausa_vpl VALUES ("MT8_28","070_8_28","MAT","8","28","28","Da ya isa ɗayan gefen a yankin Gadarenawa (ko kuwa Gerasenawa), sai ga mutum biyu masu aljanu suna fitowa daga kaburbura suka tarye shi. Su abin tsoro ne ƙwarai, har ba mai iya bin wannan hanya. ");
INSERT INTO hausa_vpl VALUES ("MT8_29","070_8_29","MAT","8","29","29","Suka yi ihu suka ce, “Me ya haɗa ka da mu, Ɗan Allah?” Ka zo ne nan don ka ji mana kafin lokaci yă yi? ");
INSERT INTO hausa_vpl VALUES ("MT8_30","070_8_30","MAT","8","30","30","Nesa kaɗan da su kuwa akwai babban garken aladu da yake kiwo. ");
INSERT INTO hausa_vpl VALUES ("MT8_31","070_8_31","MAT","8","31","31","Aljanun suka roƙi Yesu suka ce, “In ka fitar da mu, tura mu cikin garken aladun nan.” ");
INSERT INTO hausa_vpl VALUES ("MT8_32","070_8_32","MAT","8","32","32","Ya ce musu, “Ku tafi!” Sai suka fita suka shiga cikin aladun, dukan garken kuwa ya gangara a guje daga kan tudun zuwa cikin tafkin aladun kuma suka mutu a cikin ruwa. ");
INSERT INTO hausa_vpl VALUES ("MT8_33","070_8_33","MAT","8","33","33","Masu kiwon aladun suka ruga, suka je cikin gari suka ba da labarin dukan wannan, haɗe da abin da ya faru da mutanen nan masu aljanu. ");
INSERT INTO hausa_vpl VALUES ("MT8_34","070_8_34","MAT","8","34","34","Sai dukan garin suka fito don su taryi Yesu. Da suka kuwa gan shi, sai suka roƙe shi yă bar musu yanki. ");
INSERT INTO hausa_vpl VALUES ("MT9_1","070_9_1","MAT","9","1","1","Yesu ya shiga jirgin ruwa, ya ƙetare ya zo garinsa. ");
INSERT INTO hausa_vpl VALUES ("MT9_2","070_9_2","MAT","9","2","2","Waɗansu mutane suka kawo masa wani shanyayye, kwance a tabarma. Da Yesu ya ga bangaskiyarsu, sai ya ce wa shanyayyen, “Kada ka damu saurayi, an gafarta maka zunubanka.” ");
INSERT INTO hausa_vpl VALUES ("MT9_3","070_9_3","MAT","9","3","3","Da jin wannan, waɗansu malaman dokoki suka ce wa juna, “Wannan mutum yana yin saɓo!” ");
INSERT INTO hausa_vpl VALUES ("MT9_4","070_9_4","MAT","9","4","4","Sane da tunaninsu, Yesu ya ce, “Me ya sa kuke da mugun tunani a zuciyarku? ");
INSERT INTO hausa_vpl VALUES ("MT9_5","070_9_5","MAT","9","5","5","Wanne ya fi sauƙi, a ce, ‘An gafarta maka zunubanka,’ ko kuwa a ce, ‘Tashi ka yi tafiya?’ ");
INSERT INTO hausa_vpl VALUES ("MT9_6","070_9_6","MAT","9","6","6","Amma don ku san cewa Ɗan Mutum yana da iko a duniya yă gafarta zunubai.” Sai ya ce wa shanyayyen, “Tashi, ɗauki tabarmarka ka tafi gida.” ");
INSERT INTO hausa_vpl VALUES ("MT9_7","070_9_7","MAT","9","7","7","Mutumin kuwa ya tashi ya tafi gida. ");
INSERT INTO hausa_vpl VALUES ("MT9_8","070_9_8","MAT","9","8","8","Da taron suka ga haka, sai suka cika da tsoro, suka yabi Allah wanda ya ba wa mutane irin ikon nan. ");
INSERT INTO hausa_vpl VALUES ("MT9_9","070_9_9","MAT","9","9","9","Da Yesu ya yi gaba daga wurin, sai ya ga wani mutum mai suna Mattiyu zaune a inda ake karɓar haraji. Ya ce masa, “Bi ni.” Mattiyu kuwa ya tashi ya bi shi. ");
INSERT INTO hausa_vpl VALUES ("MT9_10","070_9_10","MAT","9","10","10","Yayinda Yesu yake cin abinci a gidan Mattiyu, masu karɓar haraji da yawa da kuma masu zunubi suka zo suka kuwa ci tare da shi da kuma almajiransa. ");
INSERT INTO hausa_vpl VALUES ("MT9_11","070_9_11","MAT","9","11","11","Sa’ad da Farisiyawa suka ga haka, sai suka tambayi almajiransa suka ce, “Don me malaminku yake ci tare da masu karɓar haraji, da masu zunubi?” ");
INSERT INTO hausa_vpl VALUES ("MT9_12","070_9_12","MAT","9","12","12","Da jin wannan, Yesu ya ce, “Ai, ba masu lafiya ba ne su bukatar likita, sai dai marasa lafiya. ");
INSERT INTO hausa_vpl VALUES ("MT9_13","070_9_13","MAT","9","13","13","Amma ku je ku koyi abin da wannan yake nufi, ‘Jinƙai nake bukata, ba hadaya ba.’Gama ban zo domin in kira masu adalci ba, sai dai masu zunubi.” ");
INSERT INTO hausa_vpl VALUES ("MT9_14","070_9_14","MAT","9","14","14","Sai almajiran Yohanna suka zo suka tambaye shi suka ce, “Me ya sa mu da Farisiyawa muke azumi, amma almajiranka ba sa yi?” ");
INSERT INTO hausa_vpl VALUES ("MT9_15","070_9_15","MAT","9","15","15","Yesu ya amsa ya ce, “Yaya baƙin ango za su yi makoki yayinda yake tare da su? Lokaci yana zuwa da za a ɗauke ango daga gare su, sa’an nan za su yi azumi. ");
INSERT INTO hausa_vpl VALUES ("MT9_16","070_9_16","MAT","9","16","16","“Ba mai yin faci da sabon ƙyalle a kan tsohuwar riga, gama facin zai kece rigar yă sa kecewar ma ta fi ta dā muni. ");
INSERT INTO hausa_vpl VALUES ("MT9_17","070_9_17","MAT","9","17","17","Mutane kuma ba sa zuba sabon ruwan inabi a cikin tsofaffin salkuna. In suka yi haka, salkunan za su farfashe, ruwan inabin kuwa yă zube salkunan kuma su lalace. A’a, ai, sukan zuba sabon ruwan inabi ne a cikin sababbin salkuna, don a kiyaye dukan biyun.” ");
INSERT INTO hausa_vpl VALUES ("MT9_18","070_9_18","MAT","9","18","18","Yayinda yake faɗin wannan, sai wani mai mulki ya zo ya durƙusa a gabansa ya ce, “Yanzu-yanzu diyata ta rasu. Amma ka zo ka ɗibiya hannunka a kanta, za tă kuwa rayu.” ");
INSERT INTO hausa_vpl VALUES ("MT9_19","070_9_19","MAT","9","19","19","Yesu ya tashi ya tafi tare da shi, haka ma almajiransa. ");
INSERT INTO hausa_vpl VALUES ("MT9_20","070_9_20","MAT","9","20","20","A daidai wannan lokaci sai ga wata mace wadda ta yi shekaru goma sha biyu tana zub da jini ta raɓo ta bayansa ta taɓa gefen rigarsa. ");
INSERT INTO hausa_vpl VALUES ("MT9_21","070_9_21","MAT","9","21","21","Ta ce a ranta, “Ko da rigarsa ce kawai na taɓo, zan warke.” ");
INSERT INTO hausa_vpl VALUES ("MT9_22","070_9_22","MAT","9","22","22","Yesu ya juya ya gan ta. Sai ya ce, “Kada ki damu diyata, bangaskiyarki ta warkar da ke.” Nan take macen ta warke. ");
INSERT INTO hausa_vpl VALUES ("MT9_23","070_9_23","MAT","9","23","23","Da Yesu ya shiga gidan mai mulkin ya ga masu busan sarewa da taro mai hayaniya, ");
INSERT INTO hausa_vpl VALUES ("MT9_24","070_9_24","MAT","9","24","24","sai ya ce, “Ku ba da wuri. Ai, yarinyar ba tă mutu ba, tana barci ne.” Amma suka yi masa dariya. ");
INSERT INTO hausa_vpl VALUES ("MT9_25","070_9_25","MAT","9","25","25","Bayan an fitar da taron waje, sai ya shiga ciki ya kama yarinyar a hannu, ta kuwa tashi. ");
INSERT INTO hausa_vpl VALUES ("MT9_26","070_9_26","MAT","9","26","26","Labarin wannan kuwa ya bazu ko’ina a yankin. ");
INSERT INTO hausa_vpl VALUES ("MT9_27","070_9_27","MAT","9","27","27","Da Yesu ya fita daga can, sai waɗansu makafi biyu suka bi shi, suna kira, suna cewa, “Ka yi mana jinƙai, Ɗan Dawuda!” ");
INSERT INTO hausa_vpl VALUES ("MT9_28","070_9_28","MAT","9","28","28","Da ya shiga cikin gida, sai makafin nan suka zo wurinsa, ya kuma tambaye su, “Kun gaskata cewa ina iya yin wannan?” Suka amsa suka ce, “I, Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("MT9_29","070_9_29","MAT","9","29","29","Sa’an nan ya taɓa idanunsu ya ce, “Bisa ga bangaskiyarku a yi muku haka”; ");
INSERT INTO hausa_vpl VALUES ("MT9_30","070_9_30","MAT","9","30","30","sai idanunsu suka buɗe. Yesu ya gargaɗe su sosai ya ce, “Ku lura kada wani yă san wani abu game da wannan.” ");
INSERT INTO hausa_vpl VALUES ("MT9_31","070_9_31","MAT","9","31","31","Amma suka fita suka yi ta baza labari game da shi ko’ina a wannan yankin. ");
INSERT INTO hausa_vpl VALUES ("MT9_32","070_9_32","MAT","9","32","32","Yayinda suke fitowa, sai aka kawo wa Yesu wani mutum mai aljani, da ba ya iya magana. ");
INSERT INTO hausa_vpl VALUES ("MT9_33","070_9_33","MAT","9","33","33","Sa’ad da aka fitar da aljanin kuwa, sai beben ya yi magana. Taron suka yi mamaki suka ce, “Ba a taɓa ganin irin wannan abu a Isra’ila ba.” ");
INSERT INTO hausa_vpl VALUES ("MT9_34","070_9_34","MAT","9","34","34","Amma Farisiyawa suka ce, “Ai, da ikon sarkin aljanu yake fitar da aljanu.” ");
INSERT INTO hausa_vpl VALUES ("MT9_35","070_9_35","MAT","9","35","35","Yesu ya zazzaga dukan garuruwa da ƙauyuka, yana koyarwa a majami’unsu, yana wa’azin labari mai daɗi na mulkin yana kuma warkar da kowace irin cuta da rashin lafiya. ");
INSERT INTO hausa_vpl VALUES ("MT9_36","070_9_36","MAT","9","36","36","Da ya ga taron mutane, sai ya ji tausayinsu, domin an wulaƙanta su ba su kuma da mai taimako, kamar tumaki marasa makiyayi. ");
INSERT INTO hausa_vpl VALUES ("MT9_37","070_9_37","MAT","9","37","37","Sai ya ce wa almajiransa, “Girbi yana da yawa, amma ma’aikata kaɗan ne. ");
INSERT INTO hausa_vpl VALUES ("MT9_38","070_9_38","MAT","9","38","38","Saboda haka ku roƙi Ubangijin girbi, yă aiko da ma’aikata cikin gonarsa na girbi.” ");
INSERT INTO hausa_vpl VALUES ("MT10_1","070_10_1","MAT","10","1","1","Sai ya kira almajiransa goma sha biyu wurinsa ya kuma ba su iko su fitar aljanu, su kuma warkar da kowace irin cuta da rashin lafiya. ");
INSERT INTO hausa_vpl VALUES ("MT10_2","070_10_2","MAT","10","2","2","Ga sunayen manzannin nan goma sha biyu, da fari, Siman (wanda ake kira Bitrus) da ɗan’uwansa Andarawus; Yaƙub ɗan Zebedi da ɗan’uwansa Yohanna; ");
INSERT INTO hausa_vpl VALUES ("MT10_3","070_10_3","MAT","10","3","3","Filibus da Bartolomeyu; Toma da Mattiyu mai karɓar haraji; Yaƙub ɗan Alfayus da Taddayus; ");
INSERT INTO hausa_vpl VALUES ("MT10_4","070_10_4","MAT","10","4","4","Siman Zilot da kuma Yahuda Iskariyot wanda ya bashe Yesu. ");
INSERT INTO hausa_vpl VALUES ("MT10_5","070_10_5","MAT","10","5","5","Waɗannan sha biyun ne Yesu ya aika da umarni cewa, “Kada ku je cikin Al’ummai, ko kuwa ku shiga wani garin Samariyawa. ");
INSERT INTO hausa_vpl VALUES ("MT10_6","070_10_6","MAT","10","6","6","A maimakon haka ku je wajen ɓatattun tumakin Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("MT10_7","070_10_7","MAT","10","7","7","Sa’ad da kuke tafiya, ku yi wa’azi, kuna cewa, ‘Mulkin sama ya kusato.’ ");
INSERT INTO hausa_vpl VALUES ("MT10_8","070_10_8","MAT","10","8","8","Ku warkar da marasa lafiya, ku tā da matattu, ku tsabtacce kutare, ku kuma fitar da aljanu. A kyauta kuka samu, ku kuma bayar a kyauta. ");
INSERT INTO hausa_vpl VALUES ("MT10_9","070_10_9","MAT","10","9","9","“Kada ku riƙe wata zinariya ko azurfa ko jan ƙarfe a aljihunanku, ");
INSERT INTO hausa_vpl VALUES ("MT10_10","070_10_10","MAT","10","10","10","kada ku ɗauki jaka don tafiya, ko ƙarin riga, ko takalma ko sanda; domin ma’aikaci ya cancanci hakkinsa. ");
INSERT INTO hausa_vpl VALUES ("MT10_11","070_10_11","MAT","10","11","11","Kowane gari ko ƙauyen da kuka shiga, ku nemi mai mutunci a wurin, ku kuma zauna a gidansa har sai kun tashi. ");
INSERT INTO hausa_vpl VALUES ("MT10_12","070_10_12","MAT","10","12","12","Da shigarku gidan, ku yi gaisuwa. ");
INSERT INTO hausa_vpl VALUES ("MT10_13","070_10_13","MAT","10","13","13","In gidan na kirki ne, bari salamarku ta zauna a kansa; in kuwa ba mai kirki ba, salamarku ta komo muku. ");
INSERT INTO hausa_vpl VALUES ("MT10_14","070_10_14","MAT","10","14","14","Duk wanda ya ƙi marabtarku ko ya ƙi sauraron kalmominku, sai ku karkaɗe ƙurar ƙafafunku sa’ad da kuka fita gidan ko garin. ");
INSERT INTO hausa_vpl VALUES ("MT10_15","070_10_15","MAT","10","15","15","Gaskiya nake gaya muku, za a fi jin tausayin Sodom da Gomorra a ranar shari’a fiye da wannan gari. ");
INSERT INTO hausa_vpl VALUES ("MT10_16","070_10_16","MAT","10","16","16","“Ina aikan ku kamar tumaki a cikin kyarketai. Saboda haka ku zama masu wayo kamar macizai, kuma marasa ɓarna kamar kurciyoyi. ");
INSERT INTO hausa_vpl VALUES ("MT10_17","070_10_17","MAT","10","17","17","Ku yi hankali da mutane; za su miƙa ku ga majalisa su kuma yi muku bulala a majami’unsu. ");
INSERT INTO hausa_vpl VALUES ("MT10_18","070_10_18","MAT","10","18","18","Saboda ni, za a ja ku zuwa gaban gwamnoni da gaban sarakuna domin ku ba da shaida a gabansu, da kuma ga Al’ummai. ");
INSERT INTO hausa_vpl VALUES ("MT10_19","070_10_19","MAT","10","19","19","Amma sa’ad da suka kama ku, kada ku damu game da abin da za ku faɗa ko kuwa yadda za ku faɗe shi. A lokacin za a ba ku abin da za ku faɗa, ");
INSERT INTO hausa_vpl VALUES ("MT10_20","070_10_20","MAT","10","20","20","gama ba ku ba ne kuke magana, amma Ruhun Ubanku ne yake magana ta wurinku. ");
INSERT INTO hausa_vpl VALUES ("MT10_21","070_10_21","MAT","10","21","21","“Ɗan’uwa zai ci amanar ɗan’uwansa, a kuma kashe shi, Uba ma zai yi haka da ɗansa; ’ya’ya za su tayar wa iyayensu, su kuma sa a kashe su. ");
INSERT INTO hausa_vpl VALUES ("MT10_22","070_10_22","MAT","10","22","22","Dukan mutane za su ƙi ku saboda ni, amma wanda ya jure har ƙarshe zai sami ceto. ");
INSERT INTO hausa_vpl VALUES ("MT10_23","070_10_23","MAT","10","23","23","Sa’ad da aka tsananta muku a wannan wuri, ku gudu zuwa wancan. Gaskiya nake gaya muku, kafin ku gama zazzaga dukan biranen Isra’ila, Ɗan Mutum zai zo. ");
INSERT INTO hausa_vpl VALUES ("MT10_24","070_10_24","MAT","10","24","24","“Ɗalibi ba ya fin malaminsa, haka ma, bawa ba ya fin maigidansa. ");
INSERT INTO hausa_vpl VALUES ("MT10_25","070_10_25","MAT","10","25","25","Ya isa wa ɗalibi yă zama kamar malaminsa, haka ma bawa kamar maigidansa. In har an kira wanda yake kan gida Be’elzebub,me za su ce game da mutanen gidansa? ");
INSERT INTO hausa_vpl VALUES ("MT10_26","070_10_26","MAT","10","26","26","“Saboda haka kada ku ji tsoronsu. Ba abin da yake a rufe da ba za a tone ba, ko kuwa a ɓoye da ba za a bayyana ba. ");
INSERT INTO hausa_vpl VALUES ("MT10_27","070_10_27","MAT","10","27","27","Abin da na faɗa muku a asirce, ku faɗe shi a sarari; abin da aka faɗa muku a kunne, ku yi shelarsa daga kan rufin ɗaki. ");
INSERT INTO hausa_vpl VALUES ("MT10_28","070_10_28","MAT","10","28","28","Kada ku ji tsoron masu kashe jiki amma ba sa iya kashe rai. A maimakon haka, ku ji tsoron Wannan wanda yake da iko yă hallaka rai duk da jiki a jahannama ta wuta. ");
INSERT INTO hausa_vpl VALUES ("MT10_29","070_10_29","MAT","10","29","29","Ba akan sayar da kanari biyu kobo ɗaya ba? Duk da haka ba ɗayansu da zai fāɗi ƙasa ba da yardar Ubanku. ");
INSERT INTO hausa_vpl VALUES ("MT10_30","070_10_30","MAT","10","30","30","Kai, ko gashin kanku ma duk an ƙidaya su. ");
INSERT INTO hausa_vpl VALUES ("MT10_31","070_10_31","MAT","10","31","31","Saboda haka kada ku ji tsoro; kun fi kanari masu yawa, daraja nesa. ");
INSERT INTO hausa_vpl VALUES ("MT10_32","070_10_32","MAT","10","32","32","“Duk wanda ya bayyana yarda a gare ni a gaban mutane, ni ma zan bayyana yarda a gare shi a gaban Ubana da yake cikin sama. ");
INSERT INTO hausa_vpl VALUES ("MT10_33","070_10_33","MAT","10","33","33","Amma duk wanda ya yi mūsun sani na a gaban mutane, ni ma zan yi mūsun saninsa a gaban Ubana da yake cikin sama. ");
INSERT INTO hausa_vpl VALUES ("MT10_34","070_10_34","MAT","10","34","34","“Kada fa ku ɗauka na zo ne don in kawo salama a duniya. A’a, ban zo don in kawo salama ba, sai dai takobi. ");
INSERT INTO hausa_vpl VALUES ("MT10_35","070_10_35","MAT","10","35","35","Gama na zo ne in sa, “ ‘gāba tsakanin mutum da mahaifinsa, ’ya da mahaifiyarta, matar ɗa da surukarta, ");
INSERT INTO hausa_vpl VALUES ("MT10_36","070_10_36","MAT","10","36","36","abokan gāban mutum, za su zama mutanen gidansa ne.’ ");
INSERT INTO hausa_vpl VALUES ("MT10_37","070_10_37","MAT","10","37","37","“Duk wanda ya fi ƙaunar mahaifinsa ko mahaifiyarsa fiye da ni, bai dace yă zama nawa ba; duk kuwa wanda yake ƙaunar ɗansa ko diyarsa fiye da ni, bai dace yă zama nawa ba; ");
INSERT INTO hausa_vpl VALUES ("MT10_38","070_10_38","MAT","10","38","38","duk wanda kuma bai ɗauki gicciyensa ya bi ni ba, bai dace yă zama nawa ba. ");
INSERT INTO hausa_vpl VALUES ("MT10_39","070_10_39","MAT","10","39","39","Duk mai son adana ransa zai rasa shi, duk wanda kuwa ya rasa ransa saboda ni zai same shi. ");
INSERT INTO hausa_vpl VALUES ("MT10_40","070_10_40","MAT","10","40","40","“Wanda ya karɓe ku, ya karɓe ni ne, wanda kuma ya karɓe ni, ya karɓi wanda ya aiko ni ne. ");
INSERT INTO hausa_vpl VALUES ("MT10_41","070_10_41","MAT","10","41","41","Duk wanda ya karɓi annabi don shi annabi ne, zai sami ladar annabi, duk kuwa wanda ya karɓi mutum mai adalci don shi mai adalci ne, zai sami ladar mai adalci. ");
INSERT INTO hausa_vpl VALUES ("MT10_42","070_10_42","MAT","10","42","42","In kuma wani ya ba wa ɗaya daga cikin ƙananan nan ko da kwaf ruwan sanyi ne kan shi almajirina ne, gaskiya nake gaya muku, ba shakka ba zai rasa ladarsa ba.” ");
INSERT INTO hausa_vpl VALUES ("MT11_1","070_11_1","MAT","11","1","1","Bayan Yesu ya gama yi wa almajiransa sha biyun nan umarni, sai ya yi gaba daga can don yă koyar yă kuma yi wa’azi a garuruwan Galili. ");
INSERT INTO hausa_vpl VALUES ("MT11_2","070_11_2","MAT","11","2","2","Sa’ad da Yohanna Mai Baftisma ya ji a kurkuku abin da Kiristi yake yi, sai ya aiki almajiransa ");
INSERT INTO hausa_vpl VALUES ("MT11_3","070_11_3","MAT","11","3","3","su tambaye shi, “Kai ne wanda zai zo, ko kuwa mu sa ido ga wani?” ");
INSERT INTO hausa_vpl VALUES ("MT11_4","070_11_4","MAT","11","4","4","Yesu ya amsa ya ce, “Ku koma ku gaya wa Yohanna abin da kuka ji, kuka kuma gani. ");
INSERT INTO hausa_vpl VALUES ("MT11_5","070_11_5","MAT","11","5","5","Makafi suna gani, guragu suna tafiya, ana warkar da waɗanda suke da kuturta, kurame suna ji, ana tā da matattu, ana kuma yi wa matalauta wa’azin labari mai daɗi. ");
INSERT INTO hausa_vpl VALUES ("MT11_6","070_11_6","MAT","11","6","6","Mai albarka ne mutumin da bai yi tuntuɓe ba saboda ni.” ");
INSERT INTO hausa_vpl VALUES ("MT11_7","070_11_7","MAT","11","7","7","Sa’ad da almajiran Yohanna suke barin wurin, sai Yesu ya fara yi wa taron magana game da Yohanna. “Me kuka je kallo a hamada? Ciyawar da iska take kaɗawa ne? ");
INSERT INTO hausa_vpl VALUES ("MT11_8","070_11_8","MAT","11","8","8","In ba haka ba, to, me kuka je kallo? Mutum mai sanye da riguna masu kyau ne? A’a, masu sa riguna masu kyau, ai, a fadan sarakuna suke. ");
INSERT INTO hausa_vpl VALUES ("MT11_9","070_11_9","MAT","11","9","9","To, me kuka je kallo ne? Annabi? I, ina gaya muku, ya ma fi annabi. ");
INSERT INTO hausa_vpl VALUES ("MT11_10","070_11_10","MAT","11","10","10","Wannan shi ne wanda aka rubuta game da shi cewa, “ ‘Zan aiki ɗan saƙona yă sha gabanka, wanda zai shirya hanyarka a gabanka.’ ");
INSERT INTO hausa_vpl VALUES ("MT11_11","070_11_11","MAT","11","11","11","Gaskiya nake gaya muku. A cikin dukan waɗanda mata suka haifa, ba wani da ya taso da ya fi Yohanna Mai Baftisma girma; duk da haka mafi ƙanƙanta a mulkin sama ya fi shi girma. ");
INSERT INTO hausa_vpl VALUES ("MT11_12","070_11_12","MAT","11","12","12","Tun daga kwanakin Yohanna Mai Baftisma har yă zuwa yanzu, mulkin sama yana sha da ƙyar, fitanannu kuma sun kama mulkin sama sun riƙe gam. ");
INSERT INTO hausa_vpl VALUES ("MT11_13","070_11_13","MAT","11","13","13","Gama dukan Annabawa da kuma Doka sun yi ta annabci har yă zuwa kan Yohanna. ");
INSERT INTO hausa_vpl VALUES ("MT11_14","070_11_14","MAT","11","14","14","In kuna niyya ku yarda da wannan, to, shi ne Iliya da dā ma zai zo. ");
INSERT INTO hausa_vpl VALUES ("MT11_15","070_11_15","MAT","11","15","15","Duk mai kunnen ji, yă ji. ");
INSERT INTO hausa_vpl VALUES ("MT11_16","070_11_16","MAT","11","16","16","“Da me zan kwatanta wannan zamani? Suna kama da yara da suke zaune a kasuwa, suna kiran juna, suna cewa, ");
INSERT INTO hausa_vpl VALUES ("MT11_17","070_11_17","MAT","11","17","17","“ ‘Mun yi muku busa, ba ku kuwa yi rawa ba, mun rera waƙar makoki, ba ku kuwa yi makoki ba.’ ");
INSERT INTO hausa_vpl VALUES ("MT11_18","070_11_18","MAT","11","18","18","Gama Yohanna Mai Baftisma ya zo ba ya ciye-ciye, ba ya shaye-shaye, sai suka ce, ‘Ai, yana da aljani.’ ");
INSERT INTO hausa_vpl VALUES ("MT11_19","070_11_19","MAT","11","19","19","Ɗan Mutum ya zo yana ciye-ciye, yana shaye-shaye, sai suka ce, ‘Ga mai haɗama da kuma mashayi, abokin masu karɓar haraji da masu zunubi.’ Amma akan tabbatar da hikima ta wurin ayyukanta.” ");
INSERT INTO hausa_vpl VALUES ("MT11_20","070_11_20","MAT","11","20","20","Sai Yesu ya fara yin tir da biranen da aka yi yawancin ayyukansa na banmamaki, don ba su tuba ba. ");
INSERT INTO hausa_vpl VALUES ("MT11_21","070_11_21","MAT","11","21","21","“Kaitonki, Korazin! Kaitonki, Betsaida! Da a ce ayyukan banmamakin da aka yi a cikinki ne aka yi a Taya da Sidon, da tuni sun tuba sanye da rigar makoki da toka. ");
INSERT INTO hausa_vpl VALUES ("MT11_22","070_11_22","MAT","11","22","22","Amma ina gaya muku, za a fi jin tausayin Taya da Sidon a ranar shari’a, fiye da ku. ");
INSERT INTO hausa_vpl VALUES ("MT11_23","070_11_23","MAT","11","23","23","Ke kuma Kafarnahum, za a ɗaga ki sama ne? A’a, za ki gangara zuwa zurfafa ne. Da a ce ayyukan banmamakin da aka yi a cikinki ne a aka yi a Sodom, da tana nan har yă zuwa yau. ");
INSERT INTO hausa_vpl VALUES ("MT11_24","070_11_24","MAT","11","24","24","Amma ina gaya miki, za a fi jin tausayin Sodom fiye da ke a ranar shari’a.” ");
INSERT INTO hausa_vpl VALUES ("MT11_25","070_11_25","MAT","11","25","25","A wannan lokaci sai Yesu ya ce, “Ina yabonka, Uba, Ubangijin sama da ƙasa, gama ka ɓoye waɗannan abubuwa ga masu hikima da masu ilimi, ka kuma bayyana su ga ƙananan yara. ");
INSERT INTO hausa_vpl VALUES ("MT11_26","070_11_26","MAT","11","26","26","I, Uba, gama wannan shi ne abin da ka ji daɗin yi. ");
INSERT INTO hausa_vpl VALUES ("MT11_27","070_11_27","MAT","11","27","27","“Dukan kome Ubana ya danƙa mini. Ba wanda ya san Ɗan sai dai Uban, ba kuma wanda ya san Uban, sai dai Ɗan da kuma waɗanda Ɗan ya so yă bayyana musu shi. ");
INSERT INTO hausa_vpl VALUES ("MT11_28","070_11_28","MAT","11","28","28","“Ku zo gare ni, dukanku da kuka gaji kuke kuma fama da kaya, zan kuwa ba ku hutu. ");
INSERT INTO hausa_vpl VALUES ("MT11_29","070_11_29","MAT","11","29","29","Ku ɗauki karkiyata a kanku, ku kuma yi koyi da ni, gama ni mai tawali’u ne marar girman kai, za ku kuwa sami hutu don rayukanku. ");
INSERT INTO hausa_vpl VALUES ("MT11_30","070_11_30","MAT","11","30","30","Gama karkiyata mai sauƙi ce, kayana kuma marasa nauyi ne.” ");
INSERT INTO hausa_vpl VALUES ("MT12_1","070_12_1","MAT","12","1","1","A lokacin nan Yesu ya bi ta gonakin hatsi a ranar Asabbaci. Almajiransa kuwa suna jin yunwa, sai suka fara kakkarya kan hatsi suna ci. ");
INSERT INTO hausa_vpl VALUES ("MT12_2","070_12_2","MAT","12","2","2","Sa’ad da Farisiyawa suka ga wannan, sai suka ce masa, “Duba! Almajiranka suna yin abin da doka ta hana a yi a ranar Asabbaci.” ");
INSERT INTO hausa_vpl VALUES ("MT12_3","070_12_3","MAT","12","3","3","Sai ya amsa ya ce, “Ba ku karanta abin da Dawuda ya yi ba ne sa’ad da shi da abokan tafiyarsa suka ji yunwa? ");
INSERT INTO hausa_vpl VALUES ("MT12_4","070_12_4","MAT","12","4","4","Ya shiga gidan Allah, da shi da abokan tafiyarsa suka ci keɓaɓɓen burodin, wanda doka ta hana su yi, sai firistoci kaɗai. ");
INSERT INTO hausa_vpl VALUES ("MT12_5","070_12_5","MAT","12","5","5","Ko kuwa ba ku karanta a Doka cewa a ranar Asabbaci firistoci sukan karya dokar Asabbaci duk da haka ba da yin wani laifi ba? ");
INSERT INTO hausa_vpl VALUES ("MT12_6","070_12_6","MAT","12","6","6","Ina faɗa muku cewa waniwanda ya fi haikali yana a nan. ");
INSERT INTO hausa_vpl VALUES ("MT12_7","070_12_7","MAT","12","7","7","Da a ce kun san abin da waɗannan kalmomi suke nufi, ‘Jinƙai nake bukata, ba hadaya ba,’da ba ku zargi marar laifi ba. ");
INSERT INTO hausa_vpl VALUES ("MT12_8","070_12_8","MAT","12","8","8","Gama Ɗan Mutum shi ne Ubangijin Asabbaci.” ");
INSERT INTO hausa_vpl VALUES ("MT12_9","070_12_9","MAT","12","9","9","Da ya ci gaba daga wurin, sai ya shiga majami’arsu, ");
INSERT INTO hausa_vpl VALUES ("MT12_10","070_12_10","MAT","12","10","10","a nan kuwa akwai wani mutum mai shanyayyen hannu. Don neman dalili su zargi Yesu, sai suka tambaye shi suka ce, “Ya dace a warkar a ranar Asabbaci?” ");
INSERT INTO hausa_vpl VALUES ("MT12_11","070_12_11","MAT","12","11","11","Ya ce musu, “In waninku yana da tunkiya, ta kuma fāɗa a rami ran Asabbaci, ba zai cire ta daga ramin ba? ");
INSERT INTO hausa_vpl VALUES ("MT12_12","070_12_12","MAT","12","12","12","Sau nawa mutum ya fi tunkiya daraja! Saboda haka ya dace a aikata alheri ran Asabbaci.” ");
INSERT INTO hausa_vpl VALUES ("MT12_13","070_12_13","MAT","12","13","13","Sa’an nan ya ce wa mutumin, “Miƙa hannunka.” Sai ya miƙa, hannunsa kuwa ya koma lafiyayye, kamar dai ɗayan. ");
INSERT INTO hausa_vpl VALUES ("MT12_14","070_12_14","MAT","12","14","14","Amma Farisiyawa suka fita suka ƙulla shawara yadda za su kashe Yesu. ");
INSERT INTO hausa_vpl VALUES ("MT12_15","070_12_15","MAT","12","15","15","Da ya gane wannan, sai Yesu ya janye daga wurin. Da yawa suka bi shi, ya kuwa warkar da dukan masu ciwonsu, ");
INSERT INTO hausa_vpl VALUES ("MT12_16","070_12_16","MAT","12","16","16","yana jan musu kunne kada su faɗa wa kowa akan ko shi wane ne. ");
INSERT INTO hausa_vpl VALUES ("MT12_17","070_12_17","MAT","12","17","17","Wannan kuwa domin a cika abin da aka faɗa ta bakin annabi Ishaya ne cewa, ");
INSERT INTO hausa_vpl VALUES ("MT12_18","070_12_18","MAT","12","18","18","“Ga bawana da na zaɓa, ƙaunataccena, wanda nake farin ciki da shi; zan sa Ruhuna a kansa, zai kuma yi shelar adalci ga al’ummai. ");
INSERT INTO hausa_vpl VALUES ("MT12_19","070_12_19","MAT","12","19","19","Ba zai yi faɗa ko yă ɗaga murya ba, ba kuwa wanda zai ji muryarsa a kan tituna. ");
INSERT INTO hausa_vpl VALUES ("MT12_20","070_12_20","MAT","12","20","20","Kyauron da ya tanƙwasa ba zai karye shi ba. Fitilar da ta yi kusan mutuwa ba zai kashe ta ba, sai ya jagoranci adalci zuwa ga nasara. ");
INSERT INTO hausa_vpl VALUES ("MT12_21","070_12_21","MAT","12","21","21","Cikin sunansa al’ummai za su dogara.” ");
INSERT INTO hausa_vpl VALUES ("MT12_22","070_12_22","MAT","12","22","22","Sai aka kawo masa wani bebe kuma makaho mai aljani, Yesu kuwa ya warkar da shi, har ya iya magana ya kuma sami ganin gari. ");
INSERT INTO hausa_vpl VALUES ("MT12_23","070_12_23","MAT","12","23","23","Dukan mutane suka yi mamaki, suka ce, “Wannan Ɗan Dawuda ne kuwa?” ");
INSERT INTO hausa_vpl VALUES ("MT12_24","070_12_24","MAT","12","24","24","Amma da Farisiyawa suka ji haka, sai suka ce, “Ahab, da Be’elzebub sarkin aljanu ne kaɗai, wannan mutum yake fitar da aljanu.” ");
INSERT INTO hausa_vpl VALUES ("MT12_25","070_12_25","MAT","12","25","25","Yesu kuwa ya san tunaninsu sai ya ce musu, “Duk mulkin da yake gāba da kansa zai lalace, kuma duk birni ko gidan da yake rabe gāba da kansa ba zai ɗore ba. ");
INSERT INTO hausa_vpl VALUES ("MT12_26","070_12_26","MAT","12","26","26","In Shaiɗan yana fitar da Shaiɗan, ai, ya rabu yana gāba da kansa ke nan. Yaya kuwa mulkinsa zai ɗore? ");
INSERT INTO hausa_vpl VALUES ("MT12_27","070_12_27","MAT","12","27","27","In kuwa ta wurin Be’elzebub nake fitar da aljanu, to, ta wa mutanenku suke fitar da su? Saboda haka, su ne za su zama alƙalanku. ");
INSERT INTO hausa_vpl VALUES ("MT12_28","070_12_28","MAT","12","28","28","Amma in ina fitar da aljanu ta wurin Ruhun Allah ne, to, fa, mulkin Allah ya zo muku ke nan. ");
INSERT INTO hausa_vpl VALUES ("MT12_29","070_12_29","MAT","12","29","29","“Ko kuwa, yaya wani zai iya shiga gidan mai ƙarfi yă ƙwace masa kaya ba tare da ya fara daure mai ƙarfin nan tukuna ba? Sa’an nan zai iya washe gidansa. ");
INSERT INTO hausa_vpl VALUES ("MT12_30","070_12_30","MAT","12","30","30","“Wanda ba ya tare da ni, yana gāba da ni ne, kuma wanda ba ya taya ni tarawa, watsarwa yake yi. ");
INSERT INTO hausa_vpl VALUES ("MT12_31","070_12_31","MAT","12","31","31","Saboda haka ina gaya muku, za a gafarta wa mutane kowane zunubi da kuma saɓo, amma saɓo game da Ruhu, ba za a gafarta ba. ");
INSERT INTO hausa_vpl VALUES ("MT12_32","070_12_32","MAT","12","32","32","Duk wanda ya zargi Ɗan Mutum, za a gafarta masa, amma duk wanda ya zargi Ruhu Mai Tsarki, ba za a gafarta masa ba, ko a wannan zamani ko a zamani mai zuwa. ");
INSERT INTO hausa_vpl VALUES ("MT12_33","070_12_33","MAT","12","33","33","“Itace mai kyau, yakan ba da ’ya’ya masu kyau. Itace marar kyau kuma, yakan ba da ’ya’ya marasa kyau. Itace dai, da irin ’ya’yansa ne ake gane shi. ");
INSERT INTO hausa_vpl VALUES ("MT12_34","070_12_34","MAT","12","34","34","Ku macizai, ta yaya ku da kuke mugaye za ku iya magana kirki? Gama daga baki, mutum yakan faɗi abin da yake cikin zuciya. ");
INSERT INTO hausa_vpl VALUES ("MT12_35","070_12_35","MAT","12","35","35","Mutumin kirki yakan fito da abubuwa masu kyau daga ajiyar da aka a yi cikinsa, mugun mutum kuwa yakan fito da mugayen abubuwa daga cikin muguntar da aka yi ajiya a cikinsa. ");
INSERT INTO hausa_vpl VALUES ("MT12_36","070_12_36","MAT","12","36","36","Amma ina gaya muku cewa mutane za su ba da lissafi a ranar shari’a a kan kowace kalmar banza da suka faɗa. ");
INSERT INTO hausa_vpl VALUES ("MT12_37","070_12_37","MAT","12","37","37","Gama ta wurin kalmominka za a kuɓutar da kai, kuma ta wurin kalmominka za a hukunta ka.” ");
INSERT INTO hausa_vpl VALUES ("MT12_38","070_12_38","MAT","12","38","38","Sa’an nan waɗansu Farisiyawa da malaman dokoki suka ce masa, “Malam, muna so mu ga wata alama mai banmamaki daga gare ka.” ");
INSERT INTO hausa_vpl VALUES ("MT12_39","070_12_39","MAT","12","39","39","Sai ya amsa ya ce, “Mugaye da masu zinan zamanin nan suna neman wata alama mai banmamaki! Amma babu wadda za a nuna musu, sai dai alama ta annabi Yunana. ");
INSERT INTO hausa_vpl VALUES ("MT12_40","070_12_40","MAT","12","40","40","Gama kamar yadda Yunana ya yi yini uku da kuma dare uku a cikin wani babban kifi, haka Ɗan Mutum zai yi yini uku da kuma dare uku a cikin ƙasa. ");
INSERT INTO hausa_vpl VALUES ("MT12_41","070_12_41","MAT","12","41","41","Mutanen Ninebe za su tashi a ranar shari’a tare da wannan zamani, su kuwa hukunta shi; don sun tuba saboda wa’azin Yunana, yanzu kuwa ga wanda ya fi Yunana girma a nan. ");
INSERT INTO hausa_vpl VALUES ("MT12_42","070_12_42","MAT","12","42","42","Sarauniyar Sheba za tă tashi a ranar shari’a tare da wannan zamani, tă kuwa hukunta shi; don ta zo daga ƙarshen duniya, ta saurari hikimar Solomon, yanzu kuwa ga wanda ya fi Solomon girma a nan. ");
INSERT INTO hausa_vpl VALUES ("MT12_43","070_12_43","MAT","12","43","43","“Sa’ad da mugun ruhu ya fita daga mutum, yakan bi wuraren da ba ruwa yana neman hutu, ba ya kuwa samu. ");
INSERT INTO hausa_vpl VALUES ("MT12_44","070_12_44","MAT","12","44","44","Sa’an nan yakan ce, ‘Zan koma gidan da na bari.’ Sa’ad da ya iso, ya tarar da gidan ba kowa a ciki, shararre, kuma a kintse. ");
INSERT INTO hausa_vpl VALUES ("MT12_45","070_12_45","MAT","12","45","45","Sai yă je yă ɗebo waɗansu ruhohi bakwai da suka fi shi mugunta, su kuwa zo su shiga su zauna a can. Ƙarshen mutumin nan fa zai fi farkonsa muni. Haka zai zama ga wannan mugun zamani.” ");
INSERT INTO hausa_vpl VALUES ("MT12_46","070_12_46","MAT","12","46","46","Yayinda Yesu yake cikin magana da taron, sai ga mahaifiyarsa da ’yan’uwansa tsaye a waje, suna so su yi magana da shi. ");
INSERT INTO hausa_vpl VALUES ("MT12_47","070_12_47","MAT","12","47","47","Wani ya ce masa, “Mahaifiyarka da ’yan’uwanka suna tsaye a waje, suna so su yi magana da kai.” ");
INSERT INTO hausa_vpl VALUES ("MT12_48","070_12_48","MAT","12","48","48","Ya amsa masa ya ce, “Wace ce mahaifiyata, su wane ne kuma ’yan’uwana?” ");
INSERT INTO hausa_vpl VALUES ("MT12_49","070_12_49","MAT","12","49","49","Sai ya miƙa hannu wajen almajiransa ya ce, “Ga mahaifiyata da kuma ’yan’uwana. ");
INSERT INTO hausa_vpl VALUES ("MT12_50","070_12_50","MAT","12","50","50","Ai, duk wanda yake aikata nufin Ubana wanda yake cikin sama, shi ne ɗan’uwana da ’yar’uwata da kuma mahaifiyata.” ");
INSERT INTO hausa_vpl VALUES ("MT13_1","070_13_1","MAT","13","1","1","A ranan nan sai Yesu ya fita daga gida ya je ya zauna a bakin tafkin. ");
INSERT INTO hausa_vpl VALUES ("MT13_2","070_13_2","MAT","13","2","2","Taron mutane mai yawan gaske suka taru kewaye da shi har ya kai sai da ya shiga jirgin ruwa ya zauna, yayinda dukan mutane suka tsaya a gaci. ");
INSERT INTO hausa_vpl VALUES ("MT13_3","070_13_3","MAT","13","3","3","Sa’an nan ya faɗa musu abubuwa da yawa cikin misalai, yana cewa, “Wani manomi ya fita don yă shuka irinsa. ");
INSERT INTO hausa_vpl VALUES ("MT13_4","070_13_4","MAT","13","4","4","Da yana yafa irin, waɗansu suka fāffāɗi a kan hanya, tsuntsaye kuwa suka zo suka cinye su. ");
INSERT INTO hausa_vpl VALUES ("MT13_5","070_13_5","MAT","13","5","5","Waɗansu suka fāɗi a wurare mai duwatsu, inda babu ƙasa sosai, nan da nan kuwa suka tsira, da yake ƙasar ba zurfi. ");
INSERT INTO hausa_vpl VALUES ("MT13_6","070_13_6","MAT","13","6","6","Sai dai da rana ta ɗaga, sai tsire-tsiren suka ƙone, suka kuma yanƙwane domin ba su da saiwa sosai. ");
INSERT INTO hausa_vpl VALUES ("MT13_7","070_13_7","MAT","13","7","7","Waɗansu irin suka fāɗi a cikin ƙaya, ƙayan kuwa ta yi girma ta shaƙe su. ");
INSERT INTO hausa_vpl VALUES ("MT13_8","070_13_8","MAT","13","8","8","Har yanzu, waɗansu irin suka fāffāɗi a ƙasa mai kyau, inda suka ba da amfani riɓi ɗari, sittin ko kuma talatin na abin da aka shuka. ");
INSERT INTO hausa_vpl VALUES ("MT13_9","070_13_9","MAT","13","9","9","Duk mai kunnen ji, yă ji.” ");
INSERT INTO hausa_vpl VALUES ("MT13_10","070_13_10","MAT","13","10","10","Almajiran suka zo wurinsa suka tambaye shi, “Me ya sa kake wa mutane magana da misalai?” ");
INSERT INTO hausa_vpl VALUES ("MT13_11","070_13_11","MAT","13","11","11","Ya amsa ya ce, “Sanin asirin mulkin sama kam, ku aka ba wa, amma su ba a ba su ba. ");
INSERT INTO hausa_vpl VALUES ("MT13_12","070_13_12","MAT","13","12","12","Duk wanda yake da shi, za a ƙara masa, zai kuwa samu a yalwace. Duk wanda kuma ba shi da shi, ko ɗan abin da yake da shi ma, za a karɓe. ");
INSERT INTO hausa_vpl VALUES ("MT13_13","070_13_13","MAT","13","13","13","Abin da ya sa nake musu magana da misalai ke nan. “Ko da yake suna kallo, ba sa gani; ko da yake suna saurara, ba sa ji ko su gane. ");
INSERT INTO hausa_vpl VALUES ("MT13_14","070_13_14","MAT","13","14","14","A kansu ne aka cika annabcin Ishaya cewa, “ ‘Za ku yi ta ji amma ba za ku taɓa ganewa ba; za ku yi ta kallo amma ba za ku taɓa gani ba. ");
INSERT INTO hausa_vpl VALUES ("MT13_15","070_13_15","MAT","13","15","15","Gama zuciyar mutanen nan ta taurare; da ƙyar suke ji da kunnuwansu, sun kuma rufe idanunsu. Da ba haka ba, mai yiwuwa su gani da idanunsu, su kuma ji da kunnuwansu, su gane a zuciyarsu, su kuwa juya, in kuma warkar da su.’ ");
INSERT INTO hausa_vpl VALUES ("MT13_16","070_13_16","MAT","13","16","16","Amma idanunku masu albarka ne domin suna gani, haka ma kunnuwanku domin suna ji. ");
INSERT INTO hausa_vpl VALUES ("MT13_17","070_13_17","MAT","13","17","17","Gama gaskiya nake gaya muku, annabawa da mutane masu adalci da yawa sun yi marmarin ganin abin da kuke gani amma ba su gani ba, su kuma ji abin da kuke ji amma ba su ji ba. ");
INSERT INTO hausa_vpl VALUES ("MT13_18","070_13_18","MAT","13","18","18","“To, ku saurari ma’anar misali na mai shukan nan. ");
INSERT INTO hausa_vpl VALUES ("MT13_19","070_13_19","MAT","13","19","19","Duk sa’ad da wani ya ji saƙo game da mulkin bai kuwa fahimce shi ba, mugun nan yakan zo yă ƙwace abin da aka shuka a zuciyarsa. Wannan shi ne irin da ya fāɗi a kan hanya. ");
INSERT INTO hausa_vpl VALUES ("MT13_20","070_13_20","MAT","13","20","20","Wanda ya karɓi irin da ya fāɗi a wuraren duwatsu kuwa, shi ne mutumin da yakan ji maganar, nan da nan kuwa yă karɓe ta da murna. ");
INSERT INTO hausa_vpl VALUES ("MT13_21","070_13_21","MAT","13","21","21","Sai dai da yake ba shi da saiwa, yakan ɗan jima kaɗan kawai. Da wata wahala ko tsanani ya auko masa saboda maganar, nan da nan sai yă ja da baya. ");
INSERT INTO hausa_vpl VALUES ("MT13_22","070_13_22","MAT","13","22","22","Wanda ya karɓi irin da ya fāɗi cikin ƙaya kuwa, shi ne mutumin da yakan ji maganar, sai dai damuwoyin rayuwan nan da jarrabar arzikin duniya sukan shaƙe shi, yă sa maganar ta kāsa amfani. ");
INSERT INTO hausa_vpl VALUES ("MT13_23","070_13_23","MAT","13","23","23","Amma wanda ya karɓi irin da ya fāɗi a ƙasa mai kyau, shi ne mutumin da yakan ji maganar yă kuwa fahimce ta. Yakan ba da amfani wani riɓi ɗari, sittin, ko talatin na abin da aka shuka.” ");
INSERT INTO hausa_vpl VALUES ("MT13_24","070_13_24","MAT","13","24","24","Yesu ya ba su wani misali. “Mulkin sama yana kama da wani da ya shuka iri mai kyau a cikin gonarsa. ");
INSERT INTO hausa_vpl VALUES ("MT13_25","070_13_25","MAT","13","25","25","Amma yayinda kowa yake barci, abokin gābansa ya zo ya yafa ciyayi a cikin alkamar, ya tafi abinsa. ");
INSERT INTO hausa_vpl VALUES ("MT13_26","070_13_26","MAT","13","26","26","Sa’ad da alkamar ta tashi ta yi kawuna, sai ciyayin ma suka bayyana. ");
INSERT INTO hausa_vpl VALUES ("MT13_27","070_13_27","MAT","13","27","27","“Bayin mai gonar suka zo wurinsa suka ce, ‘Ranka yă daɗe, ashe, ba iri mai kyau ka shuka a gonarka ba? To, ina ciyayin nan suka fito?’ ");
INSERT INTO hausa_vpl VALUES ("MT13_28","070_13_28","MAT","13","28","28","“Sai ya ce, ‘Abokin gāba ne ya yi wannan.’ “Bayin suka tambaye shi suka ce, ‘Kana so mu je mu tuttumɓuke su?’ ");
INSERT INTO hausa_vpl VALUES ("MT13_29","070_13_29","MAT","13","29","29","“Ya amsa ya ce, ‘A’a, don kada garin tuttumɓuke ciyayi, ku cire har da alkamar. ");
INSERT INTO hausa_vpl VALUES ("MT13_30","070_13_30","MAT","13","30","30","Ku ƙyale su su yi girma tare sai lokacin girbi. A lokacin zan gaya wa masu girbi, da fari ku tara ciyayin ku kuma daure su dami-dami don a ƙone; sa’an nan ku tara alkamar ku kuma kawo su cikin rumbuna.’ ” ");
INSERT INTO hausa_vpl VALUES ("MT13_31","070_13_31","MAT","13","31","31","Ya ba su wani misali ya ce, “Mulkin sama yana kama da ƙwayar mustad, wadda mutum ya ɗauka ya shuka a gonarsa. ");
INSERT INTO hausa_vpl VALUES ("MT13_32","070_13_32","MAT","13","32","32","Ko da yake ita ce mafi ƙanƙanta cikin ƙwayoyinku, duk da haka sa’ad da ta yi girma, takan zama mafi girma cikin tsire-tsiren lambu ta kuma zama itace, har tsuntsayen sararin sama su zo su yi sheƙa a rassansa.” ");
INSERT INTO hausa_vpl VALUES ("MT13_33","070_13_33","MAT","13","33","33","Har yanzu ya ba su wani misali ya ce, “Mulkin sama yana kama da yisti wanda mace ta ɗauka ta kwaɓa garin alkama mai yawa, har sai da yistin ya gauraye yistin duka.” ");
INSERT INTO hausa_vpl VALUES ("MT13_34","070_13_34","MAT","13","34","34","Yesu ya faɗa wa taron dukan waɗannan abubuwa cikin misalai; bai faɗa musu kome ba, sai tare da yin amfani da misalai. ");
INSERT INTO hausa_vpl VALUES ("MT13_35","070_13_35","MAT","13","35","35","Ta haka aka cika abin da aka faɗa ta wurin annabi cewa, “Zan buɗe bakina da misalai, zan faɗi abubuwan da suke ɓoye tun halittar duniya.” ");
INSERT INTO hausa_vpl VALUES ("MT13_36","070_13_36","MAT","13","36","36","Sa’an nan ya bar taron ya shiga gida. Almajiransa kuwa suka zo wurinsa suka ce, “Bayyana mana misalin ciyayin nan a gona.” ");
INSERT INTO hausa_vpl VALUES ("MT13_37","070_13_37","MAT","13","37","37","Ya amsa ya ce, “Mai yafa irin mai kyan nan, shi ne Ɗan Mutum. ");
INSERT INTO hausa_vpl VALUES ("MT13_38","070_13_38","MAT","13","38","38","Gonar kuwa ita ce duniya, irin nan mai kyau kuwa suna a matsayin ’ya’yan mulkin. Ciyayin nan kuma su ne ’ya’yan mugun nan, ");
INSERT INTO hausa_vpl VALUES ("MT13_39","070_13_39","MAT","13","39","39","abokin gāban da yake shuka su kuwa, Iblis ne. Lokacin girbi kuma shi ne ƙarshen zamani, masu girbin kuwa su ne mala’iku. ");
INSERT INTO hausa_vpl VALUES ("MT13_40","070_13_40","MAT","13","40","40","“Kamar yadda aka tattara ciyayin aka kuma ƙone a wuta, haka zai zama a ƙarshen zamani. ");
INSERT INTO hausa_vpl VALUES ("MT13_41","070_13_41","MAT","13","41","41","Ɗan Mutum zai aiki mala’ikunsa, su kuwa cire daga mulkinsa kome da yake jawo zunubi da kuma duk masu aikata mugunta. ");
INSERT INTO hausa_vpl VALUES ("MT13_42","070_13_42","MAT","13","42","42","Za su jefa su cikin wuta mai zafi, inda za a yi kuka da cizon haƙora. ");
INSERT INTO hausa_vpl VALUES ("MT13_43","070_13_43","MAT","13","43","43","Sa’an nan masu adalci za su haskaka kamar rana a mulkin Ubansu. Duk mai kunnen ji, yă ji.” ");
INSERT INTO hausa_vpl VALUES ("MT13_44","070_13_44","MAT","13","44","44","“Mulkin sama yana kama da dukiyar da aka ɓoye a gona. Da wani ya same ta, sai yă sāke ɓoye ta, sa’an nan cikin farin cikinsa yă je yă sayar da duk abin da yake da shi yă sayi gonar. ");
INSERT INTO hausa_vpl VALUES ("MT13_45","070_13_45","MAT","13","45","45","“Har wa yau dai, mulkin sama yana kama da ɗan kasuwa mai neman lu’ulu’ai masu kyau. ");
INSERT INTO hausa_vpl VALUES ("MT13_46","070_13_46","MAT","13","46","46","Da ya sami dutse guda mai daraja sosai, sai ya tafi ya sayar da dukan abin da yake da shi ya saye shi. ");
INSERT INTO hausa_vpl VALUES ("MT13_47","070_13_47","MAT","13","47","47","“Har yanzu, mulkin sama yana kama da abin kamun kifin da aka jefa cikin tafki yă kamo kifi iri-iri. ");
INSERT INTO hausa_vpl VALUES ("MT13_48","070_13_48","MAT","13","48","48","Da abin kamun kifi ya cika, masuntan suka jawo shi gaci. Sai suka zauna suka tattara kifi masu kyau a kwanduna, amma suka zubar da marasa kyau. ");
INSERT INTO hausa_vpl VALUES ("MT13_49","070_13_49","MAT","13","49","49","Haka zai kasance a ƙarshen zamani. Mala’iku za su zo su ware masu mugunta daga masu adalci ");
INSERT INTO hausa_vpl VALUES ("MT13_50","070_13_50","MAT","13","50","50","su kuma jefa su cikin wuta mai zafi, inda za a yi kuka da cizon haƙora.” ");
INSERT INTO hausa_vpl VALUES ("MT13_51","070_13_51","MAT","13","51","51","Yesu ya tambaye su ya ce, “Kun gane dukan waɗannan abubuwa?” Suka amsa, “I.” ");
INSERT INTO hausa_vpl VALUES ("MT13_52","070_13_52","MAT","13","52","52","Sa’an nan ya ce musu, “Saboda haka duk malamin dokokin da ya horu game da koyarwar mulkin sama, yana kama da maigida wanda yakan fitar daga ɗakin ajiyarsa sababbin dukiya da kuma tsofaffi.” ");
INSERT INTO hausa_vpl VALUES ("MT13_53","070_13_53","MAT","13","53","53","Sa’ad da Yesu ya gama ba da waɗannan misalai, sai ya ci gaba daga can. ");
INSERT INTO hausa_vpl VALUES ("MT13_54","070_13_54","MAT","13","54","54","Yana isowa garinsa, sai ya fara koya wa mutane a cikin majami’arsu, suka kuwa yi mamaki. Suka yi ta tambaya suna cewa, “Ina wannan mutum ya sami irin wannan hikima da kuma ayyukan banmamaki haka? ");
INSERT INTO hausa_vpl VALUES ("MT13_55","070_13_55","MAT","13","55","55","Wannan ba shi ne ɗan kafinta nan ba? Ba mahaifiyarsa ba ce Maryamu, ’yan’uwansa kuma Yaƙub, Yusuf, Siman da Yahuda ba? ");
INSERT INTO hausa_vpl VALUES ("MT13_56","070_13_56","MAT","13","56","56","Duk ’yan’uwansa mata kuma ba tare da mu suke ba? To, a ina wannan mutum ya sami dukan waɗannan abubuwa?” ");
INSERT INTO hausa_vpl VALUES ("MT13_57","070_13_57","MAT","13","57","57","Sai suka ji haushinsa. Amma Yesu ya ce musu, “Sai a garinsa da kuma a gidansa na kaɗai annabi ba ya samun girma.” ");
INSERT INTO hausa_vpl VALUES ("MT13_58","070_13_58","MAT","13","58","58","Bai kuwa yi abubuwan banmamaki da yawa a can ba saboda rashin bangaskiyarsu. ");
INSERT INTO hausa_vpl VALUES ("MT14_1","070_14_1","MAT","14","1","1","A lokacin nan sarki Hiridus ya ji labarin Yesu, ");
INSERT INTO hausa_vpl VALUES ("MT14_2","070_14_2","MAT","14","2","2","sai ya ce wa fadawansa, “Wannan Yohanna Mai Baftisma ne; ya tashi daga matattu! Shi ya sa abubuwan banmamakin nan suke faruwa ta wurinsa.” ");
INSERT INTO hausa_vpl VALUES ("MT14_3","070_14_3","MAT","14","3","3","To, dā Hiridus ya kama Yohanna ya daure, ya kuma sa shi cikin kurkuku saboda Hiridiyas, matar ɗan’uwansa Filibus, ");
INSERT INTO hausa_vpl VALUES ("MT14_4","070_14_4","MAT","14","4","4","gama Yohanna ya dinga ce masa, “Ba daidai ba ne ka aure ta.” ");
INSERT INTO hausa_vpl VALUES ("MT14_5","070_14_5","MAT","14","5","5","Hiridus ya so yă kashe Yohanna, amma yana jin tsoron mutane, don sun ɗauka shi annabi ne. ");
INSERT INTO hausa_vpl VALUES ("MT14_6","070_14_6","MAT","14","6","6","A bikin tuna da ranar haihuwar Hiridus, diyar Hiridiyas ta yi musu rawa ta kuma gamsar da Hiridus ƙwarai, ");
INSERT INTO hausa_vpl VALUES ("MT14_7","070_14_7","MAT","14","7","7","har ya yi alkawari da rantsuwa cewa zai ba ta duk abin da ta roƙa. ");
INSERT INTO hausa_vpl VALUES ("MT14_8","070_14_8","MAT","14","8","8","Da mahaifiyarta ta zuga ta, sai ta ce, “Ba ni a cikin kwanon nan, kan Yohanna Mai Baftisma.” ");
INSERT INTO hausa_vpl VALUES ("MT14_9","070_14_9","MAT","14","9","9","Sarki ya yi baƙin ciki, amma saboda rantsuwarsa da kuma baƙinsa, sai ya ba da umarni a ba ta abin da ta roƙa ");
INSERT INTO hausa_vpl VALUES ("MT14_10","070_14_10","MAT","14","10","10","ya kuma sa aka yanke kan Yohanna a kurkuku. ");
INSERT INTO hausa_vpl VALUES ("MT14_11","070_14_11","MAT","14","11","11","Aka kawo kansa cikin kwano aka ba yarinyar, ita kuma ta kai wa mahaifiyarta. ");
INSERT INTO hausa_vpl VALUES ("MT14_12","070_14_12","MAT","14","12","12","Almajiran Yohanna suka zo suka ɗauki gawarsa suka binne. Sa’an nan suka je suka gaya wa Yesu. ");
INSERT INTO hausa_vpl VALUES ("MT14_13","070_14_13","MAT","14","13","13","Sa’ad da Yesu ya ji abin da ya faru, sai ya shiga jirgin ruwa ya janye shi kaɗai zuwa wani wuri inda ba kowa. Da jin haka, taron mutane suka bi shi da ƙafa daga garuruwa. ");
INSERT INTO hausa_vpl VALUES ("MT14_14","070_14_14","MAT","14","14","14","Da Yesu ya sauka ya kuma ga taro mai yawa, sai ya ji tausayinsu ya kuma warkar da marasa lafiyarsu. ");
INSERT INTO hausa_vpl VALUES ("MT14_15","070_14_15","MAT","14","15","15","Da yamma ta yi, sai almajiransa suka zo wurinsa suka ce, “Wurin nan fa ba kowa, ga shi kuma rana ta kusa fāɗuwa. Ka sallami taron don su shiga ƙauyuka su nemi wa kansu abinci.” ");
INSERT INTO hausa_vpl VALUES ("MT14_16","070_14_16","MAT","14","16","16","Yesu ya amsa, “Ba su bukata su tafi. Ku ku ba su wani abu su ci.” ");
INSERT INTO hausa_vpl VALUES ("MT14_17","070_14_17","MAT","14","17","17","Suka ce, “Burodi biyar da kifi biyu ne kawai muke da su a nan.” ");
INSERT INTO hausa_vpl VALUES ("MT14_18","070_14_18","MAT","14","18","18","Ya ce, “Ku kawo mini su a nan.” ");
INSERT INTO hausa_vpl VALUES ("MT14_19","070_14_19","MAT","14","19","19","Sai ya umarci mutanen su zazzauna a kan ciyawa. Da ya ɗauki burodi biyar da kifin biyun nan ya dubi sama, ya yi godiya ya kuma kakkarya burodin. Sa’an nan ya ba wa almajiransa, almajiran kuwa suka ba wa mutane. ");
INSERT INTO hausa_vpl VALUES ("MT14_20","070_14_20","MAT","14","20","20","Duk suka ci suka ƙoshi, almajiran kuwa suka kwashe ragowar gutsattsarin cike da kwanduna goma sha biyu. ");
INSERT INTO hausa_vpl VALUES ("MT14_21","070_14_21","MAT","14","21","21","Yawan waɗanda suka ci, sun yi wajen maza dubu biyar, ban da mata da yara. ");
INSERT INTO hausa_vpl VALUES ("MT14_22","070_14_22","MAT","14","22","22","Nan da nan Yesu ya sa almajiran su shiga jirgin ruwa su sha gabansa, su haye zuwa ɗayan hayin, yayinda shi kuma yă sallami taron. ");
INSERT INTO hausa_vpl VALUES ("MT14_23","070_14_23","MAT","14","23","23","Bayan ya sallame su, sai ya haura bisan gefen dutse shi kaɗai don yă yi addu’a. Da yamma ta yi, yana can shi kaɗai, ");
INSERT INTO hausa_vpl VALUES ("MT14_24","070_14_24","MAT","14","24","24","jirgin ruwan kuwa ya riga ya yi nesa da gaci, yana fama da raƙuman ruwa domin iska tana gāba da shi. ");
INSERT INTO hausa_vpl VALUES ("MT14_25","070_14_25","MAT","14","25","25","Wajen tsaro na huɗu na dare, sai Yesu ya nufe su, yana takawa a kan tafkin. ");
INSERT INTO hausa_vpl VALUES ("MT14_26","070_14_26","MAT","14","26","26","Sa’ad da almajiran suka gan shi yana takawa a kan tafkin, sai tsoro ya kama su. Suka yi ihu don tsoro suka ce, “Fatalwa ce.” ");
INSERT INTO hausa_vpl VALUES ("MT14_27","070_14_27","MAT","14","27","27","Amma nan da nan Yesu ya ce musu, “Ku yi ƙarfin hali! Ni ne. Kada ku ji tsoro.” ");
INSERT INTO hausa_vpl VALUES ("MT14_28","070_14_28","MAT","14","28","28","Sai Bitrus ya amsa ya ce, “Ubangiji in kai ne ka ce mini in zo wurinka a kan ruwan.” ");
INSERT INTO hausa_vpl VALUES ("MT14_29","070_14_29","MAT","14","29","29","Ya ce, “Zo.” Sai Bitrus ya fita daga jirgin ruwan, ya taka a kan ruwan ya nufe wajen Yesu. ");
INSERT INTO hausa_vpl VALUES ("MT14_30","070_14_30","MAT","14","30","30","Amma da ya ga haukar iskar, sai ya ji tsoro, ya kuma fara nutsewa, sai ya yi ihu ya ce, “Ubangiji, ka cece ni!” ");
INSERT INTO hausa_vpl VALUES ("MT14_31","070_14_31","MAT","14","31","31","Nan da nan Yesu ya miƙa hannu ya kamo shi ya ce, “Kai mai ƙarancin bangaskiya, don me ka yi shakka?” ");
INSERT INTO hausa_vpl VALUES ("MT14_32","070_14_32","MAT","14","32","32","Da suka hau jirgin ruwan, sai iskar ta kwanta. ");
INSERT INTO hausa_vpl VALUES ("MT14_33","070_14_33","MAT","14","33","33","Waɗanda suke cikin jirgin ruwan kuwa suka yi masa sujada, suna cewa, “Gaskiya kai Ɗan Allah ne.” ");
INSERT INTO hausa_vpl VALUES ("MT14_34","070_14_34","MAT","14","34","34","Sa’ad da suka haye, sai suka sauka a Gennesaret. ");
INSERT INTO hausa_vpl VALUES ("MT14_35","070_14_35","MAT","14","35","35","Da mutanen wurin suka gane da Yesu, sai suka kai labari a ko’ina a ƙauyukan da suke kewaye. Mutane suka kawo masa dukan marasa lafiyarsu ");
INSERT INTO hausa_vpl VALUES ("MT14_36","070_14_36","MAT","14","36","36","suka kuwa roƙe shi yă bar marasa lafiya su taɓa ko da gefen rigarsa kawai, duk waɗanda suka taɓa shi kuwa suka warke. ");
INSERT INTO hausa_vpl VALUES ("MT15_1","070_15_1","MAT","15","1","1","Sa’an nan waɗansu Farisiyawa da malaman dokoki suka zo wurin Yesu daga Urushalima suka yi tambaya suka ce, ");
INSERT INTO hausa_vpl VALUES ("MT15_2","070_15_2","MAT","15","2","2","“Me ya sa almajiranka suke karya al’adun dattawa? Ba sa wanke hannuwansu kafin su ci abinci!” ");
INSERT INTO hausa_vpl VALUES ("MT15_3","070_15_3","MAT","15","3","3","Yesu ya amsa ya ce, “Ku ma me ya sa kuke karya dokar Allah saboda al’adarku? ");
INSERT INTO hausa_vpl VALUES ("MT15_4","070_15_4","MAT","15","4","4","Gama Allah ya ce, ‘Ka girmama mahaifinka da mahaifiyarka,kuma duk wanda ya zagi mahaifinsa ko mahaifiyarsa dole a kashe shi.’ ");
INSERT INTO hausa_vpl VALUES ("MT15_5","070_15_5","MAT","15","5","5","Amma ku kukan ce, in wani ya ce wa mahaifinsa ko mahaifiyarsa, ‘Duk taimakon da dā ya kamata za ku samu daga gare ni an ba wa Allah,’ ");
INSERT INTO hausa_vpl VALUES ("MT15_6","070_15_6","MAT","15","6","6","ba zai ‘girmama mahaifinsa’ da shi ba. Ta haka kun yi banza da maganar Allah saboda al’adarku. ");
INSERT INTO hausa_vpl VALUES ("MT15_7","070_15_7","MAT","15","7","7","Ku munafukai! Daidai ne Ishaya ya yi annabci a kanku da ya ce, ");
INSERT INTO hausa_vpl VALUES ("MT15_8","070_15_8","MAT","15","8","8","“ ‘Waɗannan mutane da baki kawai suke girmama ni, amma zukatansu suna nesa da ni. ");
INSERT INTO hausa_vpl VALUES ("MT15_9","070_15_9","MAT","15","9","9","A banza suke mini sujada, koyarwarsu, dokoki ne kawai da mutane suke koyarwa.’ ” ");
INSERT INTO hausa_vpl VALUES ("MT15_10","070_15_10","MAT","15","10","10","Sai Yesu ya kira taron wurinsa ya ce, “Ku saurara ku kuma gane. ");
INSERT INTO hausa_vpl VALUES ("MT15_11","070_15_11","MAT","15","11","11","Abin da yake shiga bakin mutum ba ya ƙazantar da shi, sai dai abin da yake fitowa daga bakinsa, shi ne yake ƙazantar da shi.” ");
INSERT INTO hausa_vpl VALUES ("MT15_12","070_15_12","MAT","15","12","12","Sai almajiran suka zo wurinsa suka ce, “Ka san cewa Farisiyawa ba su ji daɗi sa’ad da suka ji wannan ba?” ");
INSERT INTO hausa_vpl VALUES ("MT15_13","070_15_13","MAT","15","13","13","Ya amsa ya ce, “Duk tsiron da Ubana na sama bai shuka ba, za a tumɓuke shi daga saiwoyi. ");
INSERT INTO hausa_vpl VALUES ("MT15_14","070_15_14","MAT","15","14","14","Ku ƙyale su, ai, makafin jagorai ne.In makaho ya yi wa makaho jagora, dukansu za su fāɗa a rami.” ");
INSERT INTO hausa_vpl VALUES ("MT15_15","070_15_15","MAT","15","15","15","Bitrus ya ce, “Ka bayyana mana wannan misali.” ");
INSERT INTO hausa_vpl VALUES ("MT15_16","070_15_16","MAT","15","16","16","Yesu ya tambaye su ya ce, “Har yanzu ba ku gane ba ne? ");
INSERT INTO hausa_vpl VALUES ("MT15_17","070_15_17","MAT","15","17","17","Ba ku gane cewa duk abin da ya shiga baki yakan wuce ciki ne daga nan kuma yă fita daga jiki ba? ");
INSERT INTO hausa_vpl VALUES ("MT15_18","070_15_18","MAT","15","18","18","Amma abubuwan da suke fitowa ta baki suna fitowa ne daga zuciya, su ne kuma suke ƙazantar da mutum. ");
INSERT INTO hausa_vpl VALUES ("MT15_19","070_15_19","MAT","15","19","19","Gama daga zuciya ne mugayen tunani, kisankai, zina, fasikanci, sata, shaidar ƙarya, ɓatan suna, suka fitowa. ");
INSERT INTO hausa_vpl VALUES ("MT15_20","070_15_20","MAT","15","20","20","Waɗannan su ne suke ƙazantar da mutum; amma cin abinci ba tare da wanke hannuwa ba, ba ya ƙazantar da mutum.” ");
INSERT INTO hausa_vpl VALUES ("MT15_21","070_15_21","MAT","15","21","21","Barin wurin ke nan, sai Yesu ya janye zuwa yankin Taya da Sidon. ");
INSERT INTO hausa_vpl VALUES ("MT15_22","070_15_22","MAT","15","22","22","Wata mutuniyar Kan’ana daga wajajen ta zo wurinsa, tana ihu tana cewa, “Ubangiji, Ɗan Dawuda, ka yi mini jinƙai! ’Yata tana shan wahala ƙwarai daga aljanin da yake cikinta.” ");
INSERT INTO hausa_vpl VALUES ("MT15_23","070_15_23","MAT","15","23","23","Yesu bai ce mata uffam ba. Saboda haka almajiransa suka zo wurinsa suka roƙe shi suka ce, “Ka kore ta tă tafi, tana ta binmu tana damunmu da ihu.” ");
INSERT INTO hausa_vpl VALUES ("MT15_24","070_15_24","MAT","15","24","24","Ya amsa ya ce, “An aiko ni wurin ɓatattun tumakin Isra’ila ne kaɗai.” ");
INSERT INTO hausa_vpl VALUES ("MT15_25","070_15_25","MAT","15","25","25","Sai macen ta zo ta durƙusa a gabansa ta ce, “Ubangiji, ka taimake ni!” ");
INSERT INTO hausa_vpl VALUES ("MT15_26","070_15_26","MAT","15","26","26","Ya amsa ya ce, “Ba daidai ba ne a ɗauki abincin yara a jefa wa karnukansu.” ");
INSERT INTO hausa_vpl VALUES ("MT15_27","070_15_27","MAT","15","27","27","Ta amsa, ta ce, “I, Ubangiji, amma karnuka ma sukan ci gutsattsarin da sukan fāɗi daga teburin maigidansu.” ");
INSERT INTO hausa_vpl VALUES ("MT15_28","070_15_28","MAT","15","28","28","Sa’an nan Yesu ya amsa ya ce, “Mace, kina da bangaskiya mai yawa! An biya miki bukatarki.” ’Yarta kuwa ta warke nan take. ");
INSERT INTO hausa_vpl VALUES ("MT15_29","070_15_29","MAT","15","29","29","Yesu ya tashi daga nan ya bi ta gefen Tekun Galili. Sa’an nan ya haura gefen wani dutse ya zauna. ");
INSERT INTO hausa_vpl VALUES ("MT15_30","070_15_30","MAT","15","30","30","Taron mutane mai girma kuwa suka zo wurinsa, suna kawo masa guragu, makafi, shanyayyu, kurame da dai waɗansu da yawa, suka kuwa kwantar da su a gabansa; ya kuma warkar da su. ");
INSERT INTO hausa_vpl VALUES ("MT15_31","070_15_31","MAT","15","31","31","Mutanen kuwa suka yi mamaki sa’ad da suka ga kurame suna magana, shanyayyu suna samun lafiya, guragu suna takawa, makafi kuma suna ganin gari. Sai suka yabi Allah na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("MT15_32","070_15_32","MAT","15","32","32","Yesu ya kira almajiransa wurinsa ya ce, “Ina jin tausayin mutanen nan; gama kwana uku ke nan suke tare da ni ba abin da za su ci. Ba na so in sallame su da yunwa, don kada su kāsa a hanya.” ");
INSERT INTO hausa_vpl VALUES ("MT15_33","070_15_33","MAT","15","33","33","Sai almajiransa suka amsa suka ce, “Ina za mu sami isashen burodi a wannan wurin da babu kowa mu ciyar da irin taron nan?” ");
INSERT INTO hausa_vpl VALUES ("MT15_34","070_15_34","MAT","15","34","34","Yesu ya tambaye su, “Burodi guda nawa kuke da shi?” Suka amsa suka ce, “Guda bakwai da ’yan ƙananan kifaye.” ");
INSERT INTO hausa_vpl VALUES ("MT15_35","070_15_35","MAT","15","35","35","Ya sa taron su zazzauna a ƙasa. ");
INSERT INTO hausa_vpl VALUES ("MT15_36","070_15_36","MAT","15","36","36","Sa’an nan ya ɗauki burodi guda bakwai da kuma kifayen nan, da ya yi godiya, sai ya kakkarya su ya ba wa almajiran, su kuma suka ba wa mutane. ");
INSERT INTO hausa_vpl VALUES ("MT15_37","070_15_37","MAT","15","37","37","Duk kuwa suka ci, suka ƙoshi. Daga baya almajiran suka kwashe ragowar gutsattsarin cike da kwanduna bakwai. ");
INSERT INTO hausa_vpl VALUES ("MT15_38","070_15_38","MAT","15","38","38","Yawan waɗanda suka ci kuwa, maza dubu huɗu ne, ban da mata da yara. ");
INSERT INTO hausa_vpl VALUES ("MT15_39","070_15_39","MAT","15","39","39","Bayan Yesu ya sallami taron, sai ya shiga jirgin ruwa ya tafi wajajen Magadan. ");
INSERT INTO hausa_vpl VALUES ("MT16_1","070_16_1","MAT","16","1","1","Farisiyawa da Sadukiyawa suka zo don su gwada Yesu ta wurin neman yă nuna musu wata alama daga sama. ");
INSERT INTO hausa_vpl VALUES ("MT16_2","070_16_2","MAT","16","2","2","Ya amsa ya ce,“Sa’ad da yamma ta yi, kukan ce, ‘Yanayi zai yi kyau, gama sararin sama ya yi ja,’ ");
INSERT INTO hausa_vpl VALUES ("MT16_3","070_16_3","MAT","16","3","3","da safe kuma, ku ce, ‘Yau kam za a yi hadari, gama sararin sama ya yi ja, ya kuma ɓata fuska.’ Kun san yadda za ku fassara yanayin sararin sama, amma ba kwa iya fassarar alamun lokuta. ");
INSERT INTO hausa_vpl VALUES ("MT16_4","070_16_4","MAT","16","4","4","Wannan mugu da mazinacin zamani yana neman wani abin banmamaki, amma ba wata alamar da za a nuna wa wannan zamani sai dai ta Yunana.” Sai Yesu ya bar su ya tafi abinsa. ");
INSERT INTO hausa_vpl VALUES ("MT16_5","070_16_5","MAT","16","5","5","Da suka ƙetare tafkin, almajiran sun manta su riƙe burodi. ");
INSERT INTO hausa_vpl VALUES ("MT16_6","070_16_6","MAT","16","6","6","Yesu ya ce musu, “Ku yi hankali, ku yi taka zallan da yistin Farisiyawa da Sadukiyawa.” ");
INSERT INTO hausa_vpl VALUES ("MT16_7","070_16_7","MAT","16","7","7","Sai suka fara tattaunawa da junansu suna cewa, “Ko don ba mu kawo burodi ba ne.” ");
INSERT INTO hausa_vpl VALUES ("MT16_8","070_16_8","MAT","16","8","8","Sane da abin da suke zance, sai Yesu ya ce, “Ku masu ƙarancin bangaskiya, don me kuke magana da junanku a kan ba ku zo da burodi ba? ");
INSERT INTO hausa_vpl VALUES ("MT16_9","070_16_9","MAT","16","9","9","Har yanzu ba ku gane ba ne? Ba ku tuna da gurasa biyar ɗin nan na mutum dubu biyar ba? Kwando nawa kuka tattara cike? ");
INSERT INTO hausa_vpl VALUES ("MT16_10","070_16_10","MAT","16","10","10","Ko kuma burodi bakwai nan na mutum dubu huɗu, cikakku manyan kwanduna nawa kuka ɗauka? ");
INSERT INTO hausa_vpl VALUES ("MT16_11","070_16_11","MAT","16","11","11","Yaya kuka kāsa gane cewa ba zancen burodi nake yi ba? Sai dai ku yi hankali da yistin Farisiyawa da Sadukiyawa.” ");
INSERT INTO hausa_vpl VALUES ("MT16_12","070_16_12","MAT","16","12","12","Sa’an nan suka gane ba cewa yake musu su yi hankali da yistin da ake amfani da shi a burodi ba ne, sai dai su yi hankali da koyarwar Farisiyawa da Sadukiyawa ne. ");
INSERT INTO hausa_vpl VALUES ("MT16_13","070_16_13","MAT","16","13","13","Sa’ad da Yesu ya zo yankin Kaisariya Filibbi, sai ya tambayi almajiransa ya ce, “Wa mutane suke ce da Ɗan Mutum?” ");
INSERT INTO hausa_vpl VALUES ("MT16_14","070_16_14","MAT","16","14","14","Suka amsa, “Waɗansu suna ce Yohanna Mai Baftisma; waɗansu kuma suna ce annabi Iliya; har wa yau waɗansu suna ce Irmiya ne ko kuma ɗaya daga cikin annabawa.” ");
INSERT INTO hausa_vpl VALUES ("MT16_15","070_16_15","MAT","16","15","15","Ya tambaye su, “Amma ku fa, wane ne ni a ganinku?” ");
INSERT INTO hausa_vpl VALUES ("MT16_16","070_16_16","MAT","16","16","16","Siman Bitrus ya amsa ya ce, “Kai ne Kiristi, Ɗan Allah mai rai.” ");
INSERT INTO hausa_vpl VALUES ("MT16_17","070_16_17","MAT","16","17","17","Yesu ya amsa ya ce, “Mai albarka ne kai Siman ɗan Yunana, gama ba mutum ne ya bayyana maka wannan ba, sai dai Ubana da yake cikin sama. ");
INSERT INTO hausa_vpl VALUES ("MT16_18","070_16_18","MAT","16","18","18","Ina kuwa gaya maka, kai ne Bitrus,a kan wannan dutse zan gina ikkilisiyata, kuma ƙofofin Hadesba za su rinjaye ta ba. ");
INSERT INTO hausa_vpl VALUES ("MT16_19","070_16_19","MAT","16","19","19","Zan ba ka mabuɗan mulkin sama; kome ka daure a duniya zai zama a daure a sama, kome kuma ka kunce a duniya zai zama a kunce a sama.” ");
INSERT INTO hausa_vpl VALUES ("MT16_20","070_16_20","MAT","16","20","20","Sa’an nan ya gargaɗe almajiransa cewa kada su faɗa wa kowa shi ne Kiristi. ");
INSERT INTO hausa_vpl VALUES ("MT16_21","070_16_21","MAT","16","21","21","Tun daga wannan lokaci Yesu ya fara bayyana wa almajiransa cewa dole yă tafi Urushalima yă sha wahaloli da yawa a hannun dattawa, manyan firistoci da kuma malaman dokoki, dole a kashe shi, a rana ta uku kuma a tashe shi. ");
INSERT INTO hausa_vpl VALUES ("MT16_22","070_16_22","MAT","16","22","22","Bitrus ya ja shi gefe ya fara tsawata masa yana cewa, “Sam, Ubangiji! Wannan ba zai taɓa faruwa da kai ba!” ");
INSERT INTO hausa_vpl VALUES ("MT16_23","070_16_23","MAT","16","23","23","Yesu ya juya ya ce wa Bitrus, “Rabu da ni, Shaiɗan! Kai abin sa tuntuɓe ne a gare ni; ba ka tunanin al’amuran Allah, sai dai al’amuran mutane.” ");
INSERT INTO hausa_vpl VALUES ("MT16_24","070_16_24","MAT","16","24","24","Sa’an nan Yesu ya ce wa almajiransa, “Duk mai son bina, dole yă ƙi kansa, yă ɗauki gicciyensa, yă bi ni. ");
INSERT INTO hausa_vpl VALUES ("MT16_25","070_16_25","MAT","16","25","25","Gama duk mai son ceton ransa zai rasa shi, amma duk wanda ya rasa ransa saboda ni, zai same shi. ");
INSERT INTO hausa_vpl VALUES ("MT16_26","070_16_26","MAT","16","26","26","Me mutum zai amfana in ya sami duniya duka, amma ya rasa ransa? Ko kuwa me mutum zai bayar a bakin ransa? ");
INSERT INTO hausa_vpl VALUES ("MT16_27","070_16_27","MAT","16","27","27","Gama Ɗan Mutum zai zo cikin ɗaukakar Ubansa, tare da mala’ikunsa, sa’an nan zai ba wa kowane mutum lada gwargwadon abin da ya yi. ");
INSERT INTO hausa_vpl VALUES ("MT16_28","070_16_28","MAT","16","28","28","“Gaskiya nake gaya muku, akwai waɗansu da suke tsaitsaye a nan da ba za su mutu ba sai sun ga Ɗan Mutum yana zuwa cikin mulkinsa.” ");
INSERT INTO hausa_vpl VALUES ("MT17_1","070_17_1","MAT","17","1","1","Bayan kwana shida, sai Yesu ya ɗauki Bitrus, Yaƙub da Yohanna ɗan’uwan Yaƙub, ya kai su kan wani dutse mai tsawo, su kaɗai. ");
INSERT INTO hausa_vpl VALUES ("MT17_2","070_17_2","MAT","17","2","2","A can aka sāke kamanninsa a gabansu. Fuskarsa ta haskaka kamar rana, tufafinsa kuwa suka zama fari fat suna walƙiya. ");
INSERT INTO hausa_vpl VALUES ("MT17_3","070_17_3","MAT","17","3","3","Nan take sai ga Musa da Iliya suka bayyana a gabansu, suna magana da Yesu. ");
INSERT INTO hausa_vpl VALUES ("MT17_4","070_17_4","MAT","17","4","4","Sai Bitrus ya ce wa Yesu, “Ubangiji, ya yi kyau da muke nan. In kana so, sai in kafa bukkoki uku, ɗaya dominka, ɗaya domin Musa, ɗaya kuma domin Iliya.” ");
INSERT INTO hausa_vpl VALUES ("MT17_5","070_17_5","MAT","17","5","5","Yayinda yake cikin magana, sai wani girgije mai haske ya rufe su, sai wata murya daga cikin girgijen ta ce, “Wannan Ɗana ne, wanda nake ƙauna; wanda kuma nake jin daɗinsa ƙwarai. Ku saurare shi!” ");
INSERT INTO hausa_vpl VALUES ("MT17_6","070_17_6","MAT","17","6","6","Sa’ad da almajiran suka ji haka, sai suka fāɗi ƙasa rubda ciki, a firgice. ");
INSERT INTO hausa_vpl VALUES ("MT17_7","070_17_7","MAT","17","7","7","Amma Yesu ya zo ya taɓa su ya ce, “Ku tashi, kada ku ji tsoro.” ");
INSERT INTO hausa_vpl VALUES ("MT17_8","070_17_8","MAT","17","8","8","Da suka ɗaga kai, ba su ga kowa ba sai Yesu kaɗai. ");
INSERT INTO hausa_vpl VALUES ("MT17_9","070_17_9","MAT","17","9","9","Suna cikin gangarowa daga dutsen ke nan, sai Yesu ya umarce su cewa, “Kada ku faɗa wa kowa abin da kuka gani, sai bayan an tā da Ɗan Mutum daga matattu.” ");
INSERT INTO hausa_vpl VALUES ("MT17_10","070_17_10","MAT","17","10","10","Almajiran suka tambaye shi suka ce, “To, me ya sa malaman dokoki suke cewa, dole sai Iliya ya fara zuwa?” ");
INSERT INTO hausa_vpl VALUES ("MT17_11","070_17_11","MAT","17","11","11","Yesu ya amsa ya ce, “Tabbatacce, Iliya zai zo, zai kuma gyara dukan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("MT17_12","070_17_12","MAT","17","12","12","Amma ina faɗa muku, Iliya ya riga ya zo, ba su kuwa gane shi ba, amma suka yi masa duk abin da suka ga dama. Haka ma Ɗan Mutum zai sha wahala a hannunsu.” ");
INSERT INTO hausa_vpl VALUES ("MT17_13","070_17_13","MAT","17","13","13","Sa’an nan almajiran suka gane cewa yana musu zancen Yohanna Mai Baftisma ne. ");
INSERT INTO hausa_vpl VALUES ("MT17_14","070_17_14","MAT","17","14","14","Da suka isa wajen taron, sai wani mutum ya zo ya durƙusa a gabansa. ");
INSERT INTO hausa_vpl VALUES ("MT17_15","070_17_15","MAT","17","15","15","Ya ce, “Ubangiji, ka yi wa ɗana jinƙai. Yana da farfaɗiya yana kuma shan wahala ƙwarai. Ya sha fāɗuwa cikin wuta ko ruwa. ");
INSERT INTO hausa_vpl VALUES ("MT17_16","070_17_16","MAT","17","16","16","Na kuma kawo shi wurin almajiranka, amma ba su iya warkar da shi ba.” ");
INSERT INTO hausa_vpl VALUES ("MT17_17","070_17_17","MAT","17","17","17","Yesu ya amsa ya ce, “Ya ku zamani marasa bangaskiya da kuma masu taurinkai, har yaushe zan kasance tare da ku? Har yaushe kuma zan yi haƙuri da ku? Kawo mini yaron a nan.” ");
INSERT INTO hausa_vpl VALUES ("MT17_18","070_17_18","MAT","17","18","18","Yesu ya tsawata wa aljanin, ya kuwa rabu da yaron, nan take yaron ya warke. ");
INSERT INTO hausa_vpl VALUES ("MT17_19","070_17_19","MAT","17","19","19","Sa’an nan almajiran suka zo wurin Yesu a ɓoye suka tambaye shi suka ce, “Me ya sa ba mu iya fitar da aljanin ba?” ");
INSERT INTO hausa_vpl VALUES ("MT17_20","070_17_20","MAT","17","20","20","Ya amsa ya ce, “Saboda kuna da ƙarancin bangaskiya sosai. Gaskiya nake gaya muku, in kuna da bangaskiyar da take ƙanƙanuwa kamar ƙwayar mustad, za ku iya ce wa wannan dutse, ‘Matsa daga nan zuwa can,’ zai kuwa matsa. Babu abin da zai gagare ku.” ");
INSERT INTO hausa_vpl VALUES ("MT17_22","070_17_22","MAT","17","22","22","Da suka taru a Galili, sai ya ce musu, “Za a bashe Ɗan Mutum, a hannun mutane. ");
INSERT INTO hausa_vpl VALUES ("MT17_23","070_17_23","MAT","17","23","23","Za su kashe shi, a rana ta uku kuma za a tashe shi.” Almajiran kuwa suka cika da baƙin ciki. ");
INSERT INTO hausa_vpl VALUES ("MT17_24","070_17_24","MAT","17","24","24","Bayan Yesu da almajiransa suka isa Kafarnahum, sai masu karɓan harajin rabin shekel suka zo wurin Bitrus suka ce, “Malaminku ba ya biyan harajin haikali ne?” ");
INSERT INTO hausa_vpl VALUES ("MT17_25","070_17_25","MAT","17","25","25","Ya amsa ya ce “I, yana biya.” Da Bitrus ya shiga gida, Yesu ne ya fara magana. Ya ce masa, “Me ka gani, Siman? Daga wurin wane ne sarakunan duniya suke karɓar kuɗin shiga da kuma haraji, daga wurin ’ya’yansu ne ko kuwa daga wurin waɗansu?” ");
INSERT INTO hausa_vpl VALUES ("MT17_26","070_17_26","MAT","17","26","26","Bitrus ya amsa ya ce, “Daga wurin waɗansu.” Yesu ya ce masa, “Wato, an ɗauke wa ’ya’yan ke nan. ");
INSERT INTO hausa_vpl VALUES ("MT17_27","070_17_27","MAT","17","27","27","Amma don kada mu ɓata musu rai, ka je tafki ka jefa ƙugiyarka. Ka ɗauki kifin da ka fara kama; ka buɗe bakinsa, za ka sami shekel guda. Ka kawo ka ba su, harajina da naka ke nan.” ");
INSERT INTO hausa_vpl VALUES ("MT18_1","070_18_1","MAT","18","1","1","A lokacin nan sai almajirai suka zo wurin Yesu suka yi tambaya suka ce, “Wane ne mafi girma a mulkin sama?” ");
INSERT INTO hausa_vpl VALUES ("MT18_2","070_18_2","MAT","18","2","2","Sai ya kira ƙaramin yaro ya sa shi yă tsaya a tsakiyarsu. ");
INSERT INTO hausa_vpl VALUES ("MT18_3","070_18_3","MAT","18","3","3","Sai ya ce, “Gaskiya nake gaya muku, in ba kun canja kuka zama kamar ƙananan yara ba, labudda, ba za ku shiga mulkin sama ba. ");
INSERT INTO hausa_vpl VALUES ("MT18_4","070_18_4","MAT","18","4","4","Saboda haka, duk wanda ya ƙasƙantar da kansa kamar wannan yaro, shi ne mafi girma a mulkin sama. ");
INSERT INTO hausa_vpl VALUES ("MT18_5","070_18_5","MAT","18","5","5","Duk kuma wanda ya karɓi ƙaramin yaro kamar wannan a cikin sunana ya karɓe ni ne. ");
INSERT INTO hausa_vpl VALUES ("MT18_6","070_18_6","MAT","18","6","6","“Amma duk wanda ya sa ɗaya daga cikin ƙananan nan da suka gaskata da ni ya yi zunubi, zai fiye masa a rataya babban dutsen niƙa a wuyarsa, a kuma nutsar da shi a zurfin teku. ");
INSERT INTO hausa_vpl VALUES ("MT18_7","070_18_7","MAT","18","7","7","Kaiton duniya saboda abubuwan da suke sa mutane su yi zunubi! Dole irin waɗannan abubuwa su zo, sai dai kaiton mutumin da ya zama sanadin kawo su! ");
INSERT INTO hausa_vpl VALUES ("MT18_8","070_18_8","MAT","18","8","8","In hannunka ko ƙafarka yana sa ka zunubi, yanke shi ka yar. Zai fiye maka ka shiga rai da hannu ko ƙafa ɗaya da hannuwa biyu ko ƙafafu biyu da a jefar da kai cikin madawwamiyar wuta da hannuwa biyu ko ƙafafu biyu. ");
INSERT INTO hausa_vpl VALUES ("MT18_9","070_18_9","MAT","18","9","9","In kuma idonka yana sa ka zunubi, ƙwaƙule shi ka yar. Zai fiye maka ka shiga rai da ido ɗaya, da ka shiga jahannama ta wuta da idanunka biyu. ");
INSERT INTO hausa_vpl VALUES ("MT18_10","070_18_10","MAT","18","10","10","“Ku lura, kada ku rena ɗaya daga cikin waɗannan ƙanana. Gama ina faɗa muku mala’ikunsu a sama kullum suna duban fuskar Ubana da yake cikin sama. ");
INSERT INTO hausa_vpl VALUES ("MT18_12","070_18_12","MAT","18","12","12","“Me kuka gani? In wani yana da tumaki ɗari, sai ɗaya daga cikinsu ta ɓace, ba sai yă bar tasa’in da taran a kan tuddai yă je neman guda ɗayan da ta ɓace ba? ");
INSERT INTO hausa_vpl VALUES ("MT18_13","070_18_13","MAT","18","13","13","In kuwa ya same ta, ina gaya muku gaskiya, zai yi murna saboda ɗayan fiye da tasa’in da taran da ba su ɓace ba. ");
INSERT INTO hausa_vpl VALUES ("MT18_14","070_18_14","MAT","18","14","14","Haka ma Ubanku da yake cikin sama ba ya so ko ɗaya daga cikin ƙananan nan yă ɓace. ");
INSERT INTO hausa_vpl VALUES ("MT18_15","070_18_15","MAT","18","15","15","“In ɗan’uwanka ya yi maka laifi, ka je ka nuna masa laifinsa, tsakaninku biyu kaɗai. In ya saurare ka, ka maido da ɗan’uwanka ke nan. ");
INSERT INTO hausa_vpl VALUES ("MT18_16","070_18_16","MAT","18","16","16","Amma in bai saurare ka ba, ka je tare da mutum ɗaya ko biyu, domin ‘a tabbatar da kowace magana a bakin shaidu biyu ko uku.’ ");
INSERT INTO hausa_vpl VALUES ("MT18_17","070_18_17","MAT","18","17","17","In kuwa ya ƙi yă saurare su, sai ka gaya wa ikkilisiya; in kuma ya ƙi yă saurari ikkilisiya ma, ka yi da shi kamar marar sanin Allah ko mai karɓar haraji. ");
INSERT INTO hausa_vpl VALUES ("MT18_18","070_18_18","MAT","18","18","18","“Gaskiya nake gaya muku, duk abin da kuka daure a duniya, za a daure a sama, duk kuma abin da kuka kunce a duniya, za a kunce shi a sama. ");
INSERT INTO hausa_vpl VALUES ("MT18_19","070_18_19","MAT","18","19","19","“Har wa yau, ina gaya muku cewa in mutum biyu a cikinku a duniya suka yarda su roƙi wani abu, Ubana da yake cikin sama zai yi muku. ");
INSERT INTO hausa_vpl VALUES ("MT18_20","070_18_20","MAT","18","20","20","Gama inda mutum biyu ko uku suka taru cikin sunana, a can ma ina tare da su.” ");
INSERT INTO hausa_vpl VALUES ("MT18_21","070_18_21","MAT","18","21","21","Sai Bitrus ya zo wurin Yesu ya yi masa tambaya ya ce, “Ubangiji, sau nawa zan yafe wa ɗan’uwana sa’ad da ya yi mini zunubi? Har sau bakwai?” ");
INSERT INTO hausa_vpl VALUES ("MT18_22","070_18_22","MAT","18","22","22","Yesu amsa ya ce, “Ina gaya maka, ba sau bakwai ba, amma sau saba’in da bakwai. ");
INSERT INTO hausa_vpl VALUES ("MT18_23","070_18_23","MAT","18","23","23","“Saboda haka, mulkin sama yana kama da wani sarki wanda ya so yă yi ƙididdigar dukiyarsa da take a hannun bayinsa. ");
INSERT INTO hausa_vpl VALUES ("MT18_24","070_18_24","MAT","18","24","24","Da ya fara ƙididdigar, sai aka kawo masa wani wanda yake bin bashin talenti dubu goma. ");
INSERT INTO hausa_vpl VALUES ("MT18_25","070_18_25","MAT","18","25","25","Da yake bai iya biya ba, sai maigida ya umarta a sayar da shi da matarsa da yaransa da kuma duk abin da yake da shi, a biya bashin. ");
INSERT INTO hausa_vpl VALUES ("MT18_26","070_18_26","MAT","18","26","26","“Bawan ya durƙusa a gabansa. Ya yi roƙo ya ce, ‘Ka yi mini haƙuri, zan biya ka ƙaf.’ ");
INSERT INTO hausa_vpl VALUES ("MT18_27","070_18_27","MAT","18","27","27","Maigidan bawan ya ji tausayinsa, ya yafe masa bashin, ya kuma sake shi. ");
INSERT INTO hausa_vpl VALUES ("MT18_28","070_18_28","MAT","18","28","28","“Amma da wannan bawa ya fita, sai ya gamu da wani abokin bautarsa wanda yake binsa bashin dinari ɗari. Sai ya cafke shi, ya shaƙe shi a wuya yana cewa, ‘Biya ni abin da nake binka!’ ");
INSERT INTO hausa_vpl VALUES ("MT18_29","070_18_29","MAT","18","29","29","“Wannan abokin bautarsa ya durƙusa ya roƙe shi, ‘Ka yi mini haƙuri, zan biya ka.’ ");
INSERT INTO hausa_vpl VALUES ("MT18_30","070_18_30","MAT","18","30","30","“Amma ya ƙi. A maimako, sai ya je ya sa aka jefa shi a kurkuku, har yă biya bashin. ");
INSERT INTO hausa_vpl VALUES ("MT18_31","070_18_31","MAT","18","31","31","Sa’ad da sauran bayin suka ga abin da ya faru, abin ya ɓata musu rai ƙwarai, sai suka tafi suka faɗa wa maigidansu dukan abin da ya faru. ");
INSERT INTO hausa_vpl VALUES ("MT18_32","070_18_32","MAT","18","32","32","“Sai maigidan ya kira wannan bawa. Ya ce, ‘Kai mugun bawa, na yafe duk bashin da nake binka domin ka roƙe ni. ");
INSERT INTO hausa_vpl VALUES ("MT18_33","070_18_33","MAT","18","33","33","Ashe, bai kamata kai ma ka ji tausayin abokin bautarka yadda na yi maka ba?’ ");
INSERT INTO hausa_vpl VALUES ("MT18_34","070_18_34","MAT","18","34","34","Cikin fushi, maigidan ya miƙa shi ga ma’aikatan kurkuku su gwada masa azaba, har yă biya dukan bashin da ake binsa. ");
INSERT INTO hausa_vpl VALUES ("MT18_35","070_18_35","MAT","18","35","35","“Haka Ubana da yake cikin sama zai yi da kowannenku, in ba ku yafe wa ’yan’uwanku daga zuciyarku ba.” ");
INSERT INTO hausa_vpl VALUES ("MT19_1","070_19_1","MAT","19","1","1","Sa’ad da Yesu ya gama faɗin waɗannan abubuwa, sai ya bar Galili, ya tafi yankin Yahudiya a ɗaya gefen Urdun. ");
INSERT INTO hausa_vpl VALUES ("MT19_2","070_19_2","MAT","19","2","2","Taron mutane mai yawa suka bi shi, ya kuwa warkar da su a can. ");
INSERT INTO hausa_vpl VALUES ("MT19_3","070_19_3","MAT","19","3","3","Waɗansu Farisiyawa suka zo wurinsa don su gwada shi. Suka yi tambaya suka ce, “Daidai ne mutum yă saki matarsa saboda wani dalili da kuma a kan kowane dalili?” ");
INSERT INTO hausa_vpl VALUES ("MT19_4","070_19_4","MAT","19","4","4","Ya amsa ya ce, “Ba ku taɓa karantawa ba ne cewa, a farkon halitta, Mahalicci ‘ya yi su namiji da ta mace,’ ");
INSERT INTO hausa_vpl VALUES ("MT19_5","070_19_5","MAT","19","5","5","ya kuma ce, ‘Saboda wannan dalili, namiji zai bar mahaifinsa da mahaifiyarsa yă manne wa matarsa, biyun kuwa su zama jiki guda’? ");
INSERT INTO hausa_vpl VALUES ("MT19_6","070_19_6","MAT","19","6","6","Ta haka, ba sa ƙara zama biyu, sai dai ɗaya. Saboda haka abin da Allah ya haɗa fa, kada mutum yă raba.” ");
INSERT INTO hausa_vpl VALUES ("MT19_7","070_19_7","MAT","19","7","7","Suka yi tambaya, suka ce, “To, me ya sa Musa ya umarta cewa mutum yă ba wa matarsa takardar saki, yă kuma kore ta?” ");
INSERT INTO hausa_vpl VALUES ("MT19_8","070_19_8","MAT","19","8","8","Yesu ya amsa ya ce, “Musa ya ba ku izini ku saki matanku saboda taurin zuciyarku ne. Amma ba haka yake ba daga farko. ");
INSERT INTO hausa_vpl VALUES ("MT19_9","070_19_9","MAT","19","9","9","Ina faɗa muku cewa duk wanda ya saki matarsa, sai dai a kan rashin aminci a cikin aure, ya kuwa auri wata, ya yi zina ke nan.” ");
INSERT INTO hausa_vpl VALUES ("MT19_10","070_19_10","MAT","19","10","10","Almajiran suka ce masa, “In haka yake tsakanin miji da mata, ashe, ya ma fi kyau kada a yi aure.” ");
INSERT INTO hausa_vpl VALUES ("MT19_11","070_19_11","MAT","19","11","11","Yesu ya ce, “Ba kowa ba ne zai yarda da wannan magana, sai dai waɗanda aka yarda musu. ");
INSERT INTO hausa_vpl VALUES ("MT19_12","070_19_12","MAT","19","12","12","Gama waɗansu bābānni ne domin haka aka haife su; waɗansu kuwa mutane ne suka mai da su haka; waɗansu kuma sun ƙi aure ne saboda mulkin sama. Duk mai iya ɗaukar wannan yă ɗauka.” ");
INSERT INTO hausa_vpl VALUES ("MT19_13","070_19_13","MAT","19","13","13","Sa’an nan aka kawo yara ƙanana wurin Yesu don yă ɗibiya musu hannuwansa, yă kuma yi musu addu’a. Amma almajirai suka tsawata wa waɗanda suka kawo su. ");
INSERT INTO hausa_vpl VALUES ("MT19_14","070_19_14","MAT","19","14","14","Yesu ya ce, “Ku bar yara ƙanana su zo wurina, kada ku hana su, gama mulkin sama na irin waɗannan ne.” ");
INSERT INTO hausa_vpl VALUES ("MT19_15","070_19_15","MAT","19","15","15","Sa’ad da ya ɗibiya musu hannuwansa, sai ya tafi abinsa. ");
INSERT INTO hausa_vpl VALUES ("MT19_16","070_19_16","MAT","19","16","16","To, fa, sai ga wani ya zo wurin Yesu ya tambaye shi ya ce, “Malam, wane abu mai kyau ne ya zama mini dole in yi don in sami rai madawwami?” ");
INSERT INTO hausa_vpl VALUES ("MT19_17","070_19_17","MAT","19","17","17","Yesu ya amsa ya ce, “Don me kake tambayata game da abin da yake mai kyau? Akwai Mai kyau Ɗaya kaɗai. In kana so ka sami rai madawwami, ka kiyaye dokokin nan.” ");
INSERT INTO hausa_vpl VALUES ("MT19_18","070_19_18","MAT","19","18","18","Mutumin ya yi tambaya ya ce, “Waɗanne?” Yesu ya amsa ya ce, “ ‘Kada ka yi kisankai, kada ka yi zina, kada ka yi sata, kada ka yi shaidar ƙarya, ");
INSERT INTO hausa_vpl VALUES ("MT19_19","070_19_19","MAT","19","19","19","ka girmama mahaifinka da mahaifiyarka,’ka kuma ‘ƙaunaci maƙwabcinka kamar kanka.’” ");
INSERT INTO hausa_vpl VALUES ("MT19_20","070_19_20","MAT","19","20","20","Saurayin ya ce, “Duk waɗannan na kiyaye. Me kuma ya rage mini?” ");
INSERT INTO hausa_vpl VALUES ("MT19_21","070_19_21","MAT","19","21","21","Yesu ya amsa ya ce, “In kana so ka zama cikakke, ka je, ka sayar da dukan dukiyarka ka kuma ba matalauta, za ka kuwa sami dukiya a sama. Sa’an nan ka zo, ka bi ni.” ");
INSERT INTO hausa_vpl VALUES ("MT19_22","070_19_22","MAT","19","22","22","Da saurayin ya ji haka, sai ya tafi rai a ɓace, don yana da arziki sosai. ");
INSERT INTO hausa_vpl VALUES ("MT19_23","070_19_23","MAT","19","23","23","Sa’an nan Yesu ya ce wa almajiransa, “Gaskiya nake gaya muku, yana da wuya mai arziki yă shiga mulkin sama. ");
INSERT INTO hausa_vpl VALUES ("MT19_24","070_19_24","MAT","19","24","24","Har wa yau ina gaya muku, zai fi sauƙi raƙumi yă shiga ta kafar allura, da mai arziki yă shiga mulkin Allah.” ");
INSERT INTO hausa_vpl VALUES ("MT19_25","070_19_25","MAT","19","25","25","Sa’ad da almajiran suka ji wannan, sai suka yi mamaki ƙwarai. Suka yi tambaya suka ce, “To, wa zai sami ceto ke nan?” ");
INSERT INTO hausa_vpl VALUES ("MT19_26","070_19_26","MAT","19","26","26","Yesu ya kalle su ya ce, “Ga mutum kam, wannan ba ya yiwuwa, amma ga Allah kuwa, dukan abubuwa masu yiwuwa ne.” ");
INSERT INTO hausa_vpl VALUES ("MT19_27","070_19_27","MAT","19","27","27","Sai Bitrus ya amsa masa, “Ga shi mun bar kome don mu bi ka! Me za mu samu ke nan?” ");
INSERT INTO hausa_vpl VALUES ("MT19_28","070_19_28","MAT","19","28","28","Yesu ya ce musu, “Gaskiya nake gaya muku, a lokacin sabunta dukan kome, sa’ad da Ɗan Mutum ya zauna a kan kursiyinsa mai daraja, ku da kuka bi ni, ku ma za ku zauna a kan kursiyoyi goma sha biyu, kuna yi wa kabilu goma sha biyu na Isra’ila shari’a. ");
INSERT INTO hausa_vpl VALUES ("MT19_29","070_19_29","MAT","19","29","29","Duk kuma wanda ya bar gidaje ko ’yan’uwa maza ko ’yan’uwa mata ko mahaifi ko mahaifiya ko yara ko gonaki, saboda ni, zai sami abin da ya fi haka riɓi ɗari, yă kuma gāji rai madawwami. ");
INSERT INTO hausa_vpl VALUES ("MT19_30","070_19_30","MAT","19","30","30","Amma da yawa da suke na farko, za su zama na ƙarshe, da yawa kuma da suke na ƙarshe, za su zama na farko. ");
INSERT INTO hausa_vpl VALUES ("MT20_1","070_20_1","MAT","20","1","1","“Mulkin sama yana kama da wani mai gona, wanda ya fita da sassafe don yă yi hayar mutane su yi aiki a gonar inabinsa. ");
INSERT INTO hausa_vpl VALUES ("MT20_2","070_20_2","MAT","20","2","2","Ya yarda yă biya su dinari guda a yini, sai ya tura su gonar inabinsa. ");
INSERT INTO hausa_vpl VALUES ("MT20_3","070_20_3","MAT","20","3","3","“Wajen sa’a ta uku, ya fita sai ya ga waɗansu suna tsattsaye a bakin kasuwa ba sa kome. ");
INSERT INTO hausa_vpl VALUES ("MT20_4","070_20_4","MAT","20","4","4","Ya ce musu, ‘Ku ma ku tafi gonar inabina ku yi aiki, zan kuwa biya ku abin da ya dace.’ ");
INSERT INTO hausa_vpl VALUES ("MT20_5","070_20_5","MAT","20","5","5","Saboda haka suka tafi. “Ya sāke fita a sa’a ta shida da kuma sa’a ta tara, ya sāke yin haka. ");
INSERT INTO hausa_vpl VALUES ("MT20_6","070_20_6","MAT","20","6","6","Wajen sa’a ta goma sha ɗaya, ya sāke fita, ya tarar da waɗansu har yanzu suna tsattsaye. Ya tambaye su, ‘Don me kuke yini tsattsaye a nan ba kwa kome?’ ");
INSERT INTO hausa_vpl VALUES ("MT20_7","070_20_7","MAT","20","7","7","“Suka amsa, ‘Don ba wanda ya ɗauke mu aiki.’ “Ya ce musu, ‘Ku ma ku je ku yi aiki a gonar inabina.’ ");
INSERT INTO hausa_vpl VALUES ("MT20_8","070_20_8","MAT","20","8","8","“Sa’ad da yamma ta yi, sai mai gonar inabin ya ce wa wakilinsa, ‘Kira ma’aikatan, ka biya su hakkin aikinsu, fara daga waɗanda aka ɗauke su a ƙarshe har zuwa na farko.’ ");
INSERT INTO hausa_vpl VALUES ("MT20_9","070_20_9","MAT","20","9","9","“Ma’aikatan da ka ɗauka wajen sa’a ta goma sha ɗaya suka zo, kowannensu kuwa ya karɓi dinari guda. ");
INSERT INTO hausa_vpl VALUES ("MT20_10","070_20_10","MAT","20","10","10","Saboda haka da waɗanda aka ɗauka da fari suka zo, sun zaci za su sami fiye da haka. Amma kowannensu ma ya karɓi dinari guda. ");
INSERT INTO hausa_vpl VALUES ("MT20_11","070_20_11","MAT","20","11","11","Sa’ad da suka karɓa, sai suka fara yin gunaguni a kan mai gonar. ");
INSERT INTO hausa_vpl VALUES ("MT20_12","070_20_12","MAT","20","12","12","Suna cewa, ‘Waɗannan mutanen da aka ɗauka a ƙarshe sun yi aikin sa’a ɗaya ne kawai, ka kuma mai da su daidai da mu da muka yini muna faman aiki, muka kuma sha zafin rana.’ ");
INSERT INTO hausa_vpl VALUES ("MT20_13","070_20_13","MAT","20","13","13","“Amma ya amsa wa ɗayansu ya ce, ‘Aboki, ban cuce ka ba. Ba ka yarda ka yi aiki a kan dinari guda ba? ");
INSERT INTO hausa_vpl VALUES ("MT20_14","070_20_14","MAT","20","14","14","Ka karɓi hakkinka ka tafi. Ni na ga damar ba waɗannan na ƙarshe daidai da yadda na ba ka. ");
INSERT INTO hausa_vpl VALUES ("MT20_15","070_20_15","MAT","20","15","15","Ba ni da ikon yin abin da na ga dama da kuɗina ne? Ko kana kishi saboda ni mai kyauta ne?’ ");
INSERT INTO hausa_vpl VALUES ("MT20_16","070_20_16","MAT","20","16","16","“Saboda haka fa, na ƙarshe za su zama na farko, na farko kuma su zama na ƙarshe.” ");
INSERT INTO hausa_vpl VALUES ("MT20_17","070_20_17","MAT","20","17","17","To, da Yesu yana haurawa zuwa Urushalima, sai ya ja almajiran nan goma sha biyu gefe, ya ce musu, ");
INSERT INTO hausa_vpl VALUES ("MT20_18","070_20_18","MAT","20","18","18","“Za mu haura zuwa Urushalima, za a kuma bashe Ɗan Mutum ga manyan firistoci da malaman dokoki. Za su yi masa hukuncin kisa ");
INSERT INTO hausa_vpl VALUES ("MT20_19","070_20_19","MAT","20","19","19","za su kuma bashe shi ga Al’ummai su yi masa ba’a, su yi masa bulala, su kuma gicciye shi. A rana ta uku kuma a tashe shi!” ");
INSERT INTO hausa_vpl VALUES ("MT20_20","070_20_20","MAT","20","20","20","Sai mahaifiyar ’ya’yan Zebedin nan ta zo wurin Yesu tare da ’ya’yanta, da ta durƙusa a ƙasa, sai ta roƙe shi yă yi mata wani abu. ");
INSERT INTO hausa_vpl VALUES ("MT20_21","070_20_21","MAT","20","21","21","Ya yi tambaya ya ce, “Mene ne kike so?” Ta ce, “Ka sa daga cikin ’ya’yan nan nawa biyu, ɗaya yă zauna a damarka, ɗaya kuma a hagunka, a mulkinka.” ");
INSERT INTO hausa_vpl VALUES ("MT20_22","070_20_22","MAT","20","22","22","Yesu ya ce musu, “Ba ku san abin da kuke roƙo ba. Za ku iya sha daga kwaf da zan sha?” Suka amsa, “Za mu iya.” ");
INSERT INTO hausa_vpl VALUES ("MT20_23","070_20_23","MAT","20","23","23","Yesu ya ce musu, “Tabbatacce za ku sha daga kwaf na, sai dai zama a damana, ko haguna, ba ni nake da izinin bayarwa ba. Waɗannan wurare na waɗanda Ubana ya shirya wa ne.” ");
INSERT INTO hausa_vpl VALUES ("MT20_24","070_20_24","MAT","20","24","24","Da goman suka ji haka, sai suka yi fushi da ’yan’uwan nan biyu. ");
INSERT INTO hausa_vpl VALUES ("MT20_25","070_20_25","MAT","20","25","25","Yesu ya kira su wuri ɗaya ya ce, “Kun san cewa masu mulkin Al’ummai sukan nuna musu iko, hakimansu kuma sukan gasa musu iko. ");
INSERT INTO hausa_vpl VALUES ("MT20_26","070_20_26","MAT","20","26","26","Ba haka zai kasance da ku ba. Maimakon haka, duk mai son zama babba a cikinku, dole yă zama bawanku, ");
INSERT INTO hausa_vpl VALUES ("MT20_27","070_20_27","MAT","20","27","27","kuma duk mai son zama shugaba, dole yă zama bawanku, ");
INSERT INTO hausa_vpl VALUES ("MT20_28","070_20_28","MAT","20","28","28","kamar yadda Ɗan Mutum bai zo don a bauta masa ba, sai dai don yă yi bauta, yă kuma ba da ransa fansa saboda mutane da yawa.” ");
INSERT INTO hausa_vpl VALUES ("MT20_29","070_20_29","MAT","20","29","29","Sa’ad da Yesu da almajiransa suke barin Yeriko, sai wani babban taro ya bi shi. ");
INSERT INTO hausa_vpl VALUES ("MT20_30","070_20_30","MAT","20","30","30","Makafi biyu kuwa suna zaune a bakin hanya, da suka ji cewa Yesu yana wucewa, sai suka ɗaga murya suka ce, “Ubangiji, Ɗan Dawuda, ka ji tausayinmu!” ");
INSERT INTO hausa_vpl VALUES ("MT20_31","070_20_31","MAT","20","31","31","Mutane suka tsawata musu, suka ce musu su yi shiru. Sai suka ƙara ɗaga murya suna cewa, “Ubangiji, Ɗan Dawuda, ka ji tausayinmu!” ");
INSERT INTO hausa_vpl VALUES ("MT20_32","070_20_32","MAT","20","32","32","Yesu ya tsaya ya kira su. Ya tambaye su, “Me kuke so in yi muku?” ");
INSERT INTO hausa_vpl VALUES ("MT20_33","070_20_33","MAT","20","33","33","Suka amsa suka ce, “Ubangiji, muna so mu sami ganin gari.” ");
INSERT INTO hausa_vpl VALUES ("MT20_34","070_20_34","MAT","20","34","34","Sai Yesu ya ji tausayinsu, ya taɓa idanunsu. Nan da nan kuwa suka sami ganin gari, suka kuma bi shi. ");
INSERT INTO hausa_vpl VALUES ("MT21_1","070_21_1","MAT","21","1","1","Da suka yi kusa da Urushalima suka kuma kai Betfaji da yake kan Dutsen Zaitun, sai Yesu ya aiki almajirai biyu, ");
INSERT INTO hausa_vpl VALUES ("MT21_2","070_21_2","MAT","21","2","2","yana ce musu, “Ku je ƙauyen da yake gabanku, nan take za ku ga wata jaka a daure tare da ɗanta kusa da ita, a can. Ku kunce su ku kawo mini. ");
INSERT INTO hausa_vpl VALUES ("MT21_3","070_21_3","MAT","21","3","3","In wani ya yi muku wata magana, ku ce masa Ubangiji yana bukatarsu, zai kuwa mai da su nan da nan.” ");
INSERT INTO hausa_vpl VALUES ("MT21_4","070_21_4","MAT","21","4","4","Wannan ya faru ne don a cika abin da aka faɗa ta bakin annabin cewa, ");
INSERT INTO hausa_vpl VALUES ("MT21_5","070_21_5","MAT","21","5","5","“Ku ce wa Diyar Sihiyona, ‘Duba, sarkinki yana zuwa gare ki, mai tawali’u yana a kan jaki, a kan aholaki, ɗan jaki.’ ” ");
INSERT INTO hausa_vpl VALUES ("MT21_6","070_21_6","MAT","21","6","6","Almajiran suka tafi suka yi kamar yadda Yesu ya umarce su. ");
INSERT INTO hausa_vpl VALUES ("MT21_7","070_21_7","MAT","21","7","7","Suka kawo jakar da ɗanta, suka shimfiɗa mayafansu a kansu, Yesu kuma ya zauna a kansu. ");
INSERT INTO hausa_vpl VALUES ("MT21_8","070_21_8","MAT","21","8","8","Wani babban taron mutane suka shimfiɗa mayafansu a kan hanya, yayinda waɗansu suka sassari rassan itatuwa suka shisshimfiɗa a kan hanya. ");
INSERT INTO hausa_vpl VALUES ("MT21_9","070_21_9","MAT","21","9","9","Taron mutanen da suke gabansa da kuma waɗanda suke binsa a baya suka yi ihu suna cewa, “Hosanna ga Ɗan Dawuda!” “Mai albarka ne wanda yake zuwa cikin sunan Ubangiji!” “Hosanna a cikin sama!” ");
INSERT INTO hausa_vpl VALUES ("MT21_10","070_21_10","MAT","21","10","10","Sa’ad da Yesu ya shiga Urushalima, dukan birnin ya ruɗe, ana ta tambaya, “Wane ne wannan?” ");
INSERT INTO hausa_vpl VALUES ("MT21_11","070_21_11","MAT","21","11","11","Taron mutane suka amsa, “Wannan shi ne Yesu, annabin nan daga Nazaret a Galili.” ");
INSERT INTO hausa_vpl VALUES ("MT21_12","070_21_12","MAT","21","12","12","Yesu ya shiga filin haikali, ya kuma kori duk masu saya da sayarwa a can. Ya tutture tebur masu canjin kuɗi da kuma kujerun masu sayar da tattabarai. ");
INSERT INTO hausa_vpl VALUES ("MT21_13","070_21_13","MAT","21","13","13","Ya ce musu, “A rubuce yake, ‘Za a ce da gidana, gidan addu’a,’amma kuna mai da shi ‘kogon ’yan fashi.’ ” ");
INSERT INTO hausa_vpl VALUES ("MT21_14","070_21_14","MAT","21","14","14","Makafi da guragu suka zo wurinsa a haikali, ya kuwa warkar da su. ");
INSERT INTO hausa_vpl VALUES ("MT21_15","070_21_15","MAT","21","15","15","Amma da manyan firistoci da malaman dokoki suka ga abubuwan banmamakin da ya yi, yara kuma suna ihu a filin haikali suna cewa, “Hosanna ga Ɗan Dawuda,” sai fushi ya kama su. ");
INSERT INTO hausa_vpl VALUES ("MT21_16","070_21_16","MAT","21","16","16","Suka tambaye shi suka ce, “Kana jin abin da waɗannan suke faɗa?” Yesu ya amsa ya ce, “I, ba ku taɓa karanta ba cewa, “ ‘Daga leɓunan yara da jarirai kai, Ubangiji, ka shirya wa kanka yabo’?” ");
INSERT INTO hausa_vpl VALUES ("MT21_17","070_21_17","MAT","21","17","17","Sai ya bar su, ya fita daga birnin ya tafi Betani, inda ya kwana. ");
INSERT INTO hausa_vpl VALUES ("MT21_18","070_21_18","MAT","21","18","18","Kashegari da sassafe, yayinda yake kan hanyarsa ta komawa cikin birni, sai ya ji yunwa. ");
INSERT INTO hausa_vpl VALUES ("MT21_19","070_21_19","MAT","21","19","19","Ganin itacen ɓaure kusa da hanya, sai ya je wajensa amma bai sami kome a kansa ba sai ganye. Sai ya ce masa, “Kada ka ƙara yin ’ya’ya!” Nan da nan itacen ya yanƙwane. ");
INSERT INTO hausa_vpl VALUES ("MT21_20","070_21_20","MAT","21","20","20","Sa’ad da almajiran suka ga haka, sai suka yi mamaki suna tambaya, “Yaya itacen ɓauren ya yanƙwane nan da nan haka?” ");
INSERT INTO hausa_vpl VALUES ("MT21_21","070_21_21","MAT","21","21","21","Yesu ya amsa ya ce, “Gaskiya nake gaya muku, in kuna da bangaskiya, ba kuwa da wata shakka ba, ba kawai za ku iya yin abin da aka yi wa itacen ɓauren nan ba, amma za ku ma iya ce wa dutsen nan, ‘Je ka, ka jefa kanka cikin teku,’ sai yă faru. ");
INSERT INTO hausa_vpl VALUES ("MT21_22","070_21_22","MAT","21","22","22","In kun gaskata, za ku karɓi duk abin da kuka roƙa a cikin addu’a.” ");
INSERT INTO hausa_vpl VALUES ("MT21_23","070_21_23","MAT","21","23","23","Sai Yesu ya shiga filin haikali, yayinda yake koyarwa, sai manyan firistoci da dattawan mutane suka zo wurinsa suka yi tambaya, “Da wane iko kake yin waɗannan abubuwa? Kuma wa ya ba ka wannan iko?” ");
INSERT INTO hausa_vpl VALUES ("MT21_24","070_21_24","MAT","21","24","24","Yesu ya amsa ya ce, “Ni ma zan yi muku tambaya guda. In kuka ba ni amsa, ni ma zan gaya muku ko da wane iko nake yin waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("MT21_25","070_21_25","MAT","21","25","25","Baftismar Yohanna, daga ina ta fito? Daga sama ce, ko daga mutane?” Sai suka tattauna a junansu suka ce, “In muka ce, ‘Daga sama,’ zai ce, ‘To, me ya sa ba mu gaskata shi ba?’ ");
INSERT INTO hausa_vpl VALUES ("MT21_26","070_21_26","MAT","21","26","26","In kuma muka ce, ‘Daga mutane,’ muna tsoron mutane, gama duk sun ɗauka Yohanna annabi ne.” ");
INSERT INTO hausa_vpl VALUES ("MT21_27","070_21_27","MAT","21","27","27","Saboda haka suka amsa wa Yesu suka ce, “Ba mu sani ba.” Sai ya ce, “Ni ma ba zan gaya muku ko da wane iko nake yin waɗannan abubuwa ba.” ");
INSERT INTO hausa_vpl VALUES ("MT21_28","070_21_28","MAT","21","28","28","“Me kuka gani? An yi wani mutum wanda yake da ’ya’ya biyu maza. Sai ya je wajen ɗan farin ya ce, ‘Ɗana, yau tafi gonar inabi ka yi aiki.’ ");
INSERT INTO hausa_vpl VALUES ("MT21_29","070_21_29","MAT","21","29","29","“Ya amsa ya ce, ‘Ba zan tafi ba,’ amma daga baya ya sāke tunani, ya tafi. ");
INSERT INTO hausa_vpl VALUES ("MT21_30","070_21_30","MAT","21","30","30","“Sai mahaifin ya tafi waje na biyun ya faɗa masa iri magana guda. Sai ya amsa ya ce, ‘Zan tafi, ranka yă daɗe,’ amma bai tafi ba. ");
INSERT INTO hausa_vpl VALUES ("MT21_31","070_21_31","MAT","21","31","31","“Wanne cikin yaran nan biyu ya yi abin da mahaifinsa yake so?” Suka amsa, “Na farin.” Yesu ya ce musu, “Gaskiya nake gaya muku, masu karɓar haraji da karuwai suna riga ku shiga mulkin Allah. ");
INSERT INTO hausa_vpl VALUES ("MT21_32","070_21_32","MAT","21","32","32","Gama Yohanna Mai Baftisma ya zo wurinku don yă nuna muku hanyar adalci, ba ku gaskata shi ba, amma masu karɓar haraji da karuwai sun gaskata. Har ma bayan kun ga wannan, ba ku tuba kun gaskata shi ba.” ");
INSERT INTO hausa_vpl VALUES ("MT21_33","070_21_33","MAT","21","33","33","“Ku saurari wani misali. An yi wani mai gona wanda ya yi gonar inabi. Ya kewaye ta da katanga, ya haƙa wurin matsin inabi a ciki, ya kuma gina hasumiyar gadi. Sa’an nan ya ba wa waɗansu manoma hayar gonar inabin, ya kuma yi tafiya. ");
INSERT INTO hausa_vpl VALUES ("MT21_34","070_21_34","MAT","21","34","34","Da lokacin girbi ya yi kusa, sai ya aiki bayinsa wajen ’yan hayan, su karɓo masa ’ya’yan inabi. ");
INSERT INTO hausa_vpl VALUES ("MT21_35","070_21_35","MAT","21","35","35","“Amma ’yan hayan suka kama bayinsa; suka dūke ɗaya, suka kashe ɗaya, suka kuma jajjefi na ukun. ");
INSERT INTO hausa_vpl VALUES ("MT21_36","070_21_36","MAT","21","36","36","Sai ya sāke aiken waɗansu bayi wurinsu, fiye da na dā yawa, amma ’yan hayan suka yi musu kamar yadda suka yi wa na farin. ");
INSERT INTO hausa_vpl VALUES ("MT21_37","070_21_37","MAT","21","37","37","A ƙarshe, sai ya aiki ɗansa a wurinsu. Ya ce, ‘Za su girmama ɗana.’ ");
INSERT INTO hausa_vpl VALUES ("MT21_38","070_21_38","MAT","21","38","38","“Amma da ’yan hayan suka hangi ɗan, sai suka ce wa juna, ‘Wannan shi ne magājin. Ku zo, mu kashe shi, mu ci gādonsa.’ ");
INSERT INTO hausa_vpl VALUES ("MT21_39","070_21_39","MAT","21","39","39","Saboda haka suka kama shi, suka jefar da shi bayan katangar gonar inabin, suka kashe shi. ");
INSERT INTO hausa_vpl VALUES ("MT21_40","070_21_40","MAT","21","40","40","“To, idan mai gonar inabin ya zo, me zai yi da ’yan hayan nan?” ");
INSERT INTO hausa_vpl VALUES ("MT21_41","070_21_41","MAT","21","41","41","Suka amsa suka ce, “Zai yi wa banzan mutanen nan mugun kisa, yă ba da hayar gonar inabin ga waɗansu ’yan haya, waɗanda za su ba shi rabonsa na amfanin gona a lokacin girbi.” ");
INSERT INTO hausa_vpl VALUES ("MT21_42","070_21_42","MAT","21","42","42","Yesu ya ce musu, “Ashe, ba ku taɓa karanta a cikin Nassi cewa, “ ‘Dutsen da magina suka ƙi shi ne ya zama dutsen kusurwar gini. Ubangiji ne ya aikata wannan, kuma abin mamaki ne a idanunmu’? ");
INSERT INTO hausa_vpl VALUES ("MT21_43","070_21_43","MAT","21","43","43","“Saboda haka, ina gaya muku cewa za a karɓe mulkin Allah daga gare ku, a ba wa mutanen da za su ba da amfani. ");
INSERT INTO hausa_vpl VALUES ("MT21_44","070_21_44","MAT","21","44","44","Duk wanda ya fāɗi a kan dutsen nan, zai kakkarye. Amma duk wanda dutsen nan ya fāɗi a kansa, za a murƙushe shi.” ");
INSERT INTO hausa_vpl VALUES ("MT21_45","070_21_45","MAT","21","45","45","Da manyan firistoci da Farisiyawa suka ji misalan Yesu, sai suka gane cewa da su yake. ");
INSERT INTO hausa_vpl VALUES ("MT21_46","070_21_46","MAT","21","46","46","Suka nemi hanyar kama shi, amma suka ji tsoron taron, don mutane sun ɗauka shi annabi ne. ");
INSERT INTO hausa_vpl VALUES ("MT22_1","070_22_1","MAT","22","1","1","Yesu ya sāke yin musu magana da misalai, yana cewa, ");
INSERT INTO hausa_vpl VALUES ("MT22_2","070_22_2","MAT","22","2","2","“Mulkin sama yana kama da wani sarki wanda ya shirya bikin auren ɗansa. ");
INSERT INTO hausa_vpl VALUES ("MT22_3","070_22_3","MAT","22","3","3","Sai ya aiki bayinsa su kira waɗanda aka gayyata zuwa bikin, amma waɗanda aka ce su zo bikin, suka ƙi zuwa. ");
INSERT INTO hausa_vpl VALUES ("MT22_4","070_22_4","MAT","22","4","4","“Sai ya sāke aiken waɗansu bayi ya ce, ‘Ku ce wa waɗanda aka gayyata cewa na shirya abinci. An yanka bijimai da shanun da aka yi kiwo, kome a shirye yake. Ku zo bikin auren mana.’ ");
INSERT INTO hausa_vpl VALUES ("MT22_5","070_22_5","MAT","22","5","5","“Amma ba su kula ba, suka kama gabansu, ɗaya ya tafi gonarsa, ɗaya kuma ya tafi kasuwancinsa. ");
INSERT INTO hausa_vpl VALUES ("MT22_6","070_22_6","MAT","22","6","6","Sauran suka kama bayinsa suka wulaƙanta su, suka kuma kashe su. ");
INSERT INTO hausa_vpl VALUES ("MT22_7","070_22_7","MAT","22","7","7","Sai sarkin ya yi fushi. Ya aiki mayaƙansa suka karkashe masu kisankan nan, aka kuma ƙone birninsu. ");
INSERT INTO hausa_vpl VALUES ("MT22_8","070_22_8","MAT","22","8","8","“Sa’an nan ya ce wa bayinsa, ‘Bikin aure fa ya shiryu, sai dai mutanen da na gayyata ba su dace ba. ");
INSERT INTO hausa_vpl VALUES ("MT22_9","070_22_9","MAT","22","9","9","Ku bi titi-titi ku gayyato duk waɗanda kuka gani, su zo bikin.’ ");
INSERT INTO hausa_vpl VALUES ("MT22_10","070_22_10","MAT","22","10","10","Saboda haka bayin suka bi titi-titi, suka tattaro duk mutanen da suka samu, masu kirki da marasa kirki, zauren bikin ya cika makil da baƙi. ");
INSERT INTO hausa_vpl VALUES ("MT22_11","070_22_11","MAT","22","11","11","“Amma da sarkin ya shigo don yă ga baƙin, sai ya ga wani can da ba ya sanye da kayan auren. ");
INSERT INTO hausa_vpl VALUES ("MT22_12","070_22_12","MAT","22","12","12","Ya yi tambaya ya ce, ‘Aboki, yaya ka shigo nan ba tare da rigar aure ba?’ Mutumin ya rasa ta cewa. ");
INSERT INTO hausa_vpl VALUES ("MT22_13","070_22_13","MAT","22","13","13","“Sai sarkin ya ce wa fadawa, ‘Ku daure shi hannu da ƙafa, ku jefar da shi waje, cikin duhu, inda za a yi kuka da cizon haƙora.’ ");
INSERT INTO hausa_vpl VALUES ("MT22_14","070_22_14","MAT","22","14","14","“Gama kirayayu da yawa, amma zaɓaɓɓu kaɗan ne zaɓaɓɓu.” ");
INSERT INTO hausa_vpl VALUES ("MT22_15","070_22_15","MAT","22","15","15","Sai Farisiyawa suka yi waje, suka ƙulla yadda za su yi masa tarko cikin maganarsa. ");
INSERT INTO hausa_vpl VALUES ("MT22_16","070_22_16","MAT","22","16","16","Suka aiki almajiransu tare da mutanen Hiridus wurinsa. Suka ce, “Malam, mun san kai mutum ne mai mutunci, kuma kana koyar da maganar Allah bisa gaskiya. Mutane ba sa ɗaukan hankalinka, domin ba ka kula ko su wane ne ba. ");
INSERT INTO hausa_vpl VALUES ("MT22_17","070_22_17","MAT","22","17","17","To, ka gaya mana, a ra’ayinka? Ya dace a biya Kaisar haraji ko a’a?” ");
INSERT INTO hausa_vpl VALUES ("MT22_18","070_22_18","MAT","22","18","18","Amma Yesu da yake ya san mugun nufinsu, sai ya ce, “Ku munafukai, don me kuke ƙoƙarin sa mini tarko? ");
INSERT INTO hausa_vpl VALUES ("MT22_19","070_22_19","MAT","22","19","19","Ku nuna mini kuɗin da ake biyan haraji da shi.” Sai suka kawo masa dinari, ");
INSERT INTO hausa_vpl VALUES ("MT22_20","070_22_20","MAT","22","20","20","sai ya tambaye su ya ce, “Hoton wane ne wannan? Kuma rubutun wane ne?” ");
INSERT INTO hausa_vpl VALUES ("MT22_21","070_22_21","MAT","22","21","21","Suka amsa, “Na Kaisar ne.” Sai ya ce musu, “Ku ba wa Kaisar abin da yake na Kaisar, ku kuma ba wa Allah abin da yake na Allah.” ");
INSERT INTO hausa_vpl VALUES ("MT22_22","070_22_22","MAT","22","22","22","Da suka ji haka, sai suka yi mamaki. Saboda haka suka ƙyale shi, suka yi tafiyarsu. ");
INSERT INTO hausa_vpl VALUES ("MT22_23","070_22_23","MAT","22","23","23","A ranan nan Sadukiyawa, waɗanda suke cewa babu tashin matattu, suka zo wurinsa da tambaya. ");
INSERT INTO hausa_vpl VALUES ("MT22_24","070_22_24","MAT","22","24","24","Suka ce “Malam, Musa ya faɗa mana cewa in mutum ya mutu ba shi da ’ya’ya, dole ɗan’uwansa yă auri gwauruwar yă kuma haifar wa ɗan’uwan ’ya’ya. ");
INSERT INTO hausa_vpl VALUES ("MT22_25","070_22_25","MAT","22","25","25","A cikinmu an yi ’yan’uwa guda bakwai. Na fari ya yi aure, ya mutu, da yake bai sami ’ya’ya ba, sai ya bar matarsa wa ɗan’uwansa. ");
INSERT INTO hausa_vpl VALUES ("MT22_26","070_22_26","MAT","22","26","26","Haka ya faru da ɗan’uwa na biyu da na uku, har zuwa na bakwai. ");
INSERT INTO hausa_vpl VALUES ("MT22_27","070_22_27","MAT","22","27","27","A ƙarshe, macen ta mutu. ");
INSERT INTO hausa_vpl VALUES ("MT22_28","070_22_28","MAT","22","28","28","To, a tashin matattu, matar wa a cikinsu bakwai ɗin nan za tă zama, da yake dukansu sun aure ta?” ");
INSERT INTO hausa_vpl VALUES ("MT22_29","070_22_29","MAT","22","29","29","Yesu ya amsa ya ce, “Kun ɓata, domin ba ku san Nassi ko ikon Allah ba. ");
INSERT INTO hausa_vpl VALUES ("MT22_30","070_22_30","MAT","22","30","30","Ai, a tashin matattu, mutane ba za su yi aure ko su ba da aure ba; za su zama kamar mala’iku a sama. ");
INSERT INTO hausa_vpl VALUES ("MT22_31","070_22_31","MAT","22","31","31","Amma game da tashi daga matattu na waɗanda suka mutu ba ku karanta abin da Allah ya ce muku ba ne, ");
INSERT INTO hausa_vpl VALUES ("MT22_32","070_22_32","MAT","22","32","32","‘Ni ne Allah na Ibrahim, Allah na Ishaku da kuma Allah na Yaƙub’? Ai, shi ba Allah na matattu ba ne, shi Allah na masu rai ne.” ");
INSERT INTO hausa_vpl VALUES ("MT22_33","070_22_33","MAT","22","33","33","Da taro suka ji haka, sai suka yi mamakin koyarwarsa. ");
INSERT INTO hausa_vpl VALUES ("MT22_34","070_22_34","MAT","22","34","34","Da jin Yesu ya ƙure Sadukiyawa, sai Farisiyawa suka tattaru. ");
INSERT INTO hausa_vpl VALUES ("MT22_35","070_22_35","MAT","22","35","35","Ɗaya daga cikinsu, wani masanin Doka, ya gwada shi da wannan tambaya. ");
INSERT INTO hausa_vpl VALUES ("MT22_36","070_22_36","MAT","22","36","36","“Malam, wace doka ce mafi girma a cikin dokoki?” ");
INSERT INTO hausa_vpl VALUES ("MT22_37","070_22_37","MAT","22","37","37","Yesu ya amsa ya ce, “ ‘Ka ƙaunaci Ubangiji Allahnka da dukan zuciyarka da dukan ranka da kuma dukan hankalinka.’ ");
INSERT INTO hausa_vpl VALUES ("MT22_38","070_22_38","MAT","22","38","38","Wannan, ita ce doka ta fari da kuma mafi girma. ");
INSERT INTO hausa_vpl VALUES ("MT22_39","070_22_39","MAT","22","39","39","Ta biye kuma kamar ta farkon take. ‘Ka ƙaunaci maƙwabcinka kamar kanka.’ ");
INSERT INTO hausa_vpl VALUES ("MT22_40","070_22_40","MAT","22","40","40","Dukan Doka da Annabawa suna rataya ne a kan waɗannan dokoki biyu.” ");
INSERT INTO hausa_vpl VALUES ("MT22_41","070_22_41","MAT","22","41","41","Yayinda Farisiyawa suke a tattare wuri ɗaya, sai Yesu ya tambaye su, ");
INSERT INTO hausa_vpl VALUES ("MT22_42","070_22_42","MAT","22","42","42","“Me kuke tsammani game da Kiristi? Ɗan wane ne shi?” Suka amsa suka ce, “Ɗan Dawuda.” ");
INSERT INTO hausa_vpl VALUES ("MT22_43","070_22_43","MAT","22","43","43","Ya ce musu, “To, ta yaya Dawuda ya yi magana ta wurin Ruhu Mai Tsarki, ya kira shi ‘Ubangiji’? Gama ya ce, ");
INSERT INTO hausa_vpl VALUES ("MT22_44","070_22_44","MAT","22","44","44","“ ‘Ubangiji ya ce wa Ubangijina, “Zauna a hannun damana, sai na sa abokan gābanka su zama matashin sawunka.” ’ ");
INSERT INTO hausa_vpl VALUES ("MT22_45","070_22_45","MAT","22","45","45","To, in Dawuda ya kira shi ‘Ubangiji,’ yaya zai zama ɗansa?” ");
INSERT INTO hausa_vpl VALUES ("MT22_46","070_22_46","MAT","22","46","46","Ba wanda ya iya tanka masa, daga wannan rana kuwa ba wanda ya sāke yin karambanin yin masa wata tambaya. ");
INSERT INTO hausa_vpl VALUES ("MT23_1","070_23_1","MAT","23","1","1","Sa’an nan Yesu ya ce wa taron mutane da kuma almajiransa, ");
INSERT INTO hausa_vpl VALUES ("MT23_2","070_23_2","MAT","23","2","2","“Malaman dokoki da Farisiyawa suke zama a kujerar Musa. ");
INSERT INTO hausa_vpl VALUES ("MT23_3","070_23_3","MAT","23","3","3","Saboda haka dole ku yi musu biyayya, ku kuma yi duk abin da suka faɗa muku. Sai dai kada ku yi abin da suke yi, gama ba sa yin abin da suke wa’azi. ");
INSERT INTO hausa_vpl VALUES ("MT23_4","070_23_4","MAT","23","4","4","Sukan ɗaura kaya masu nauyi, su sa wa mutane a kafaɗa. Amma su kansu, ba sa ko sa yatsa su taimaka. ");
INSERT INTO hausa_vpl VALUES ("MT23_5","070_23_5","MAT","23","5","5","“Kome suke yi, suna yi ne don mutane su gani. Sukan yi layunsufantam-fantam bakin rigunarsu kuma sukan kai har ƙasa; ");
INSERT INTO hausa_vpl VALUES ("MT23_6","070_23_6","MAT","23","6","6","suna son wurin zaman manya a wurin biki, da kuma wuraren zama gaba-gaba a majami’u; ");
INSERT INTO hausa_vpl VALUES ("MT23_7","070_23_7","MAT","23","7","7","suna so a yi ta gaisuwarsu a kasuwa, ana kuma riƙa ce musu, ‘Rabbi.’ ");
INSERT INTO hausa_vpl VALUES ("MT23_8","070_23_8","MAT","23","8","8","“Amma kada a kira ku ‘Rabbi,’ gama kuna da Maigida ɗaya ne, ku duka kuwa, ’yan’uwa ne. ");
INSERT INTO hausa_vpl VALUES ("MT23_9","070_23_9","MAT","23","9","9","Kada kuma ku kira wani a duniya ‘uba,’ gama kuna da Uba ɗaya ne, yana kuwa a sama. ");
INSERT INTO hausa_vpl VALUES ("MT23_10","070_23_10","MAT","23","10","10","Ba kuwa za a kira ku ‘malam’ ba, gama kuna da Malami ɗaya ne, Kiristi. ");
INSERT INTO hausa_vpl VALUES ("MT23_11","070_23_11","MAT","23","11","11","Mafi girma a cikinku, zai zama bawanku. ");
INSERT INTO hausa_vpl VALUES ("MT23_12","070_23_12","MAT","23","12","12","Gama duk wanda ya ɗaukaka kansa, za a ƙasƙantar da shi, duk kuma wanda ya ƙasƙantar da kansa, za a ɗaukaka shi. ");
INSERT INTO hausa_vpl VALUES ("MT23_13","070_23_13","MAT","23","13","13","“Kaitonku, malaman dokoki da Farisiyawa, ku munafukai! Kun rufe ƙofar mulkin sama a gaban mutane. Ku kanku ba ku shiga ba, ba kuwa bar waɗanda suke ƙoƙarin shiga su shiga ba. ");
INSERT INTO hausa_vpl VALUES ("MT23_15","070_23_15","MAT","23","15","15","“Kaitonku, malaman dokoki da Farisiyawa, munafukai! Kukan yi tafiye-tafiye zuwa ƙasashe, ku ƙetare teku don ku sami mai tuba ɗaya, sa’ad da ya tuba kuwa, sai ku mai da shi ɗan wuta fiye da ku, har sau biyu. ");
INSERT INTO hausa_vpl VALUES ("MT23_16","070_23_16","MAT","23","16","16","“Kaitonku, makafi jagora! Kukan ce, ‘In wani ya rantse da haikali, ba damuwa; amma in ya rantse da zinariyar haikali, sai rantsuwar ta kama shi.’ ");
INSERT INTO hausa_vpl VALUES ("MT23_17","070_23_17","MAT","23","17","17","Wawaye makafi! Wanne ya fi girma, zinariyar, ko haikalin da yake tsarkake zinariyar? ");
INSERT INTO hausa_vpl VALUES ("MT23_18","070_23_18","MAT","23","18","18","Kukan kuma ce, ‘In wani ya rantse da bagade, ba damuwa; amma in ya rantse da bayarwar da take bisansa, sai rantsuwar ta kama shi.’ ");
INSERT INTO hausa_vpl VALUES ("MT23_19","070_23_19","MAT","23","19","19","Makafi kawai! Wanne ya fi girma, bayarwar, ko kuwa bagaden da yake tsarkake bayarwar? ");
INSERT INTO hausa_vpl VALUES ("MT23_20","070_23_20","MAT","23","20","20","Saboda haka, duk wanda ya rantse da bagade, ya rantse ne da bagaden tare da abin da yake bisansa. ");
INSERT INTO hausa_vpl VALUES ("MT23_21","070_23_21","MAT","23","21","21","Kuma duk wanda ya rantse da haikali, ya rantse ne da shi da kuma wanda yake zaune a cikinsa. ");
INSERT INTO hausa_vpl VALUES ("MT23_22","070_23_22","MAT","23","22","22","Duk kuma wanda ya rantse da sama, ya rantse ne da kursiyin Allah da kuma wanda yake zaune a kansa. ");
INSERT INTO hausa_vpl VALUES ("MT23_23","070_23_23","MAT","23","23","23","“Kaitonku, malaman dokoki da Farisiyawa, munafukai! Kukan ba da kashi ɗaya bisa goma na kayan yajinku, na’ana’a, anise, da lafsur. Amma kun ƙyale abubuwan da suka fi girma na dokoki, adalci, jinƙai da aminci. Waɗannan ne ya kamata da kun kiyaye ba tare da kun ƙyale sauran ba. ");
INSERT INTO hausa_vpl VALUES ("MT23_24","070_23_24","MAT","23","24","24","Makafi jagora! Kukan tace ƙwaro ɗan mitsil amma sai ku haɗiye raƙumi. ");
INSERT INTO hausa_vpl VALUES ("MT23_25","070_23_25","MAT","23","25","25","“Kaitonku, malaman dokoki da Farisiyawa, munafukai! Kukan wanke bayan kwaf da kwano, amma a ciki, cike suke da zalunci da sonkai. ");
INSERT INTO hausa_vpl VALUES ("MT23_26","070_23_26","MAT","23","26","26","Kai makaho Bafarisiye! Ka fara wanke cikin kwaf da kwano, sa’an nan bayan ma zai zama da tsabta. ");
INSERT INTO hausa_vpl VALUES ("MT23_27","070_23_27","MAT","23","27","27","“Kaitonku, malaman dokoki da Farisiyawa, munafukai! Kuna kama da kaburburan da aka shafa musu farin fenti, waɗanda suna da kyan gani a waje, amma a ciki, cike suke da ƙasusuwan matattu da kuma kowane irin abu mai ƙazanta. ");
INSERT INTO hausa_vpl VALUES ("MT23_28","070_23_28","MAT","23","28","28","Haka ku ma, a waje, a idon mutane, ku masu adalci ne, amma a ciki, cike kuke da munafunci da mugunta. ");
INSERT INTO hausa_vpl VALUES ("MT23_29","070_23_29","MAT","23","29","29","“Kaitonku, malaman dokoki da Farisiyawa, munafukai! Kukan gina kaburbura don annabawa, ku kuma yi wa kaburburan mutane masu adalci ado. ");
INSERT INTO hausa_vpl VALUES ("MT23_30","070_23_30","MAT","23","30","30","Kuna cewa, ‘Da mun kasance a zamanin kakanninmu, ai, da ba mu haɗa hannu da su muka karkashe annabawa ba.’ ");
INSERT INTO hausa_vpl VALUES ("MT23_31","070_23_31","MAT","23","31","31","Ta haka kuna ba da shaida a kanku cewa ku zuriyar waɗanda suka karkashe annabawa ne. ");
INSERT INTO hausa_vpl VALUES ("MT23_32","070_23_32","MAT","23","32","32","To, sai ku ci gaba ku cikasa ayyukan da kakanninku suka fara! ");
INSERT INTO hausa_vpl VALUES ("MT23_33","070_23_33","MAT","23","33","33","“Ku macizai! ’Ya’yan macizai! Ta yaya za ku tsere wa hukuncin jahannama ta wuta? ");
INSERT INTO hausa_vpl VALUES ("MT23_34","070_23_34","MAT","23","34","34","Saboda haka ina aika muku da annabawa, da masu hikima da malamai. Waɗansunsu za ku kashe ku kuma gicciye; waɗansu kuma za ku yi musu bulala a majami’unku kuna kuma binsu gari-gari. ");
INSERT INTO hausa_vpl VALUES ("MT23_35","070_23_35","MAT","23","35","35","Ta haka alhakin jinin masu adalcin da aka zubar a duniya, tun daga jinin Habila mai adalci, zuwa jinin Zakariya ɗan Berekiya, wanda kuka kashe tsakanin haikali da bagade zai koma kanku. ");
INSERT INTO hausa_vpl VALUES ("MT23_36","070_23_36","MAT","23","36","36","Gaskiya nake gaya muku, duk wannan zai auko wa wannan zamani. ");
INSERT INTO hausa_vpl VALUES ("MT23_37","070_23_37","MAT","23","37","37","“Urushalima, ayya Urushalima, ke da kike kashe annabawa, kike kuma jifan waɗanda aka aiko gare ki, sau da sau na so in tattara ’ya’yanki wuri ɗaya, yadda kaza takan tattara ’ya’yanta cikin fikafikanta, amma kuka ƙi. ");
INSERT INTO hausa_vpl VALUES ("MT23_38","070_23_38","MAT","23","38","38","Ga shi, an bar muku gidanku a yashe. ");
INSERT INTO hausa_vpl VALUES ("MT23_39","070_23_39","MAT","23","39","39","Gama ina gaya muku, ba za ku sāke ganina ba sai kun ce, ‘Mai albarka ne wanda yake zuwa cikin sunan Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("MT24_1","070_24_1","MAT","24","1","1","Yesu ya bar haikali ke nan, yana cikin tafiya sai almajiransa suka zo wurinsa don su ja hankalinsa ga gine-ginen haikali. ");
INSERT INTO hausa_vpl VALUES ("MT24_2","070_24_2","MAT","24","2","2","Sai Yesu ya ce, “Kun ga duk waɗannan abubuwa? Gaskiya nake gaya muku, ba wani dutse a nan da za a bari a kan wani; duk za a rushe.” ");
INSERT INTO hausa_vpl VALUES ("MT24_3","070_24_3","MAT","24","3","3","Da Yesu yana zaune a Dutsen Zaitun, almajiran suka zo wurinsa a ɓoye. Suka ce, “Gaya mana, yaushe ne wannan zai faru, mece ce alamar zuwanka da kuma ta ƙarshen zamani?” ");
INSERT INTO hausa_vpl VALUES ("MT24_4","070_24_4","MAT","24","4","4","Yesu ya amsa, “Ku lura fa, kada wani yă ruɗe ku. ");
INSERT INTO hausa_vpl VALUES ("MT24_5","070_24_5","MAT","24","5","5","Gama mutane da yawa za su zo cikin sunana, suna cewa, ‘Ni ne Kiristi,’ za su kuwa ruɗi mutane da yawa. ");
INSERT INTO hausa_vpl VALUES ("MT24_6","070_24_6","MAT","24","6","6","Za ku ji labarin yaƙe-yaƙe da kuma jita-jitarsu, sai dai ku lura kada hankalinku yă tashi. Dole irin waɗannan abubuwa su faru, amma ƙarshen tukuna. ");
INSERT INTO hausa_vpl VALUES ("MT24_7","070_24_7","MAT","24","7","7","Al’umma za tă tasar wa al’umma, mulki yă tasar wa mulki. Za a yi yunwa da girgizar ƙasa a wurare dabam-dabam. ");
INSERT INTO hausa_vpl VALUES ("MT24_8","070_24_8","MAT","24","8","8","Dukan waɗannan fa, mafarin azabar naƙudar haihuwa ne. ");
INSERT INTO hausa_vpl VALUES ("MT24_9","070_24_9","MAT","24","9","9","“Sa’an nan za a bashe ku don a tsananta muku a kuma kashe ku, dukan al’ummai za su ƙi ku saboda ni. ");
INSERT INTO hausa_vpl VALUES ("MT24_10","070_24_10","MAT","24","10","10","A wannan lokaci, da yawa za su juya daga bangaskiya, su ci amana su kuma ƙi juna, ");
INSERT INTO hausa_vpl VALUES ("MT24_11","070_24_11","MAT","24","11","11","annabawan ƙarya da yawa za su firfito su kuma ruɗi mutane da yawa. ");
INSERT INTO hausa_vpl VALUES ("MT24_12","070_24_12","MAT","24","12","12","Saboda ƙaruwar mugunta, ƙaunar yawanci za tă yi sanyi, ");
INSERT INTO hausa_vpl VALUES ("MT24_13","070_24_13","MAT","24","13","13","amma duk wanda ya tsaya da ƙarfi har ƙarshe, zai sami ceto. ");
INSERT INTO hausa_vpl VALUES ("MT24_14","070_24_14","MAT","24","14","14","Za a kuma yi wa’azin wannan bisharar mulki a cikin dukan duniya, yă zama shaida ga dukan al’ummai, sa’an nan ƙarshen yă zo. ");
INSERT INTO hausa_vpl VALUES ("MT24_15","070_24_15","MAT","24","15","15","“Saboda haka sa’ad da kuka ga ‘abin ƙyama mai kawo hallaka,’wanda annabi Daniyel ya yi magana a kai, yana tsaye a tsattsarkan wuri (mai karatu yă gane), ");
INSERT INTO hausa_vpl VALUES ("MT24_16","070_24_16","MAT","24","16","16","to, sai waɗanda suke cikin Yahudiya, su gudu zuwa cikin duwatsu. ");
INSERT INTO hausa_vpl VALUES ("MT24_17","070_24_17","MAT","24","17","17","Kada wani da yake a kan rufin gidansa, yă sauko don ɗaukar wani abu a gida. ");
INSERT INTO hausa_vpl VALUES ("MT24_18","070_24_18","MAT","24","18","18","Kada wani da yake gona kuma yă komo don ɗaukar rigarsa. ");
INSERT INTO hausa_vpl VALUES ("MT24_19","070_24_19","MAT","24","19","19","Kaiton mata masu ciki da mata masu renon ’ya’ya a waɗancan kwanakin! ");
INSERT INTO hausa_vpl VALUES ("MT24_20","070_24_20","MAT","24","20","20","Ku yi addu’a, kada gudunku yă zama a lokacin sanyi ko a ranar Asabbaci. ");
INSERT INTO hausa_vpl VALUES ("MT24_21","070_24_21","MAT","24","21","21","Gama a lokacin za a yi wata matsananciyar wahala, wadda ba a taɓa yi ba tun farkon duniya har ya zuwa yanzu ba kuwa za a ƙara yi ba. ");
INSERT INTO hausa_vpl VALUES ("MT24_22","070_24_22","MAT","24","22","22","“Da ba don an taƙaita kwanakin nan ba, da babu wani da zai tsira, amma saboda zaɓaɓɓun nan, za a taƙaita kwanakin. ");
INSERT INTO hausa_vpl VALUES ("MT24_23","070_24_23","MAT","24","23","23","A lokacin in wani ya ce muku, ‘Duba, ga Kiristi nan!’ Ko, ‘Ga shi can!’ Kada ku gaskata. ");
INSERT INTO hausa_vpl VALUES ("MT24_24","070_24_24","MAT","24","24","24","Gama Kiristi masu yawa na ƙarya, da annabawan ƙarya za su firfito, su kuma aikata manyan alamu da ayyukan banmamaki don su ruɗi har da zaɓaɓɓu ma in zai yiwu. ");
INSERT INTO hausa_vpl VALUES ("MT24_25","070_24_25","MAT","24","25","25","Ga shi, na faɗa muku tun da wuri. ");
INSERT INTO hausa_vpl VALUES ("MT24_26","070_24_26","MAT","24","26","26","“Saboda haka in wani ya ce muku, ‘Ga shi can a hamada,’ kada ku fita; ko, ‘Ga shi nan a ɗakunan ciki,’ kada ku gaskata. ");
INSERT INTO hausa_vpl VALUES ("MT24_27","070_24_27","MAT","24","27","27","Gama kamar yadda walƙiya take wulgawa walai daga gabas zuwa yamma, haka dawowar Ɗan Mutum zai kasance. ");
INSERT INTO hausa_vpl VALUES ("MT24_28","070_24_28","MAT","24","28","28","Duk inda mushe yake, can ungulai za su taru. ");
INSERT INTO hausa_vpl VALUES ("MT24_29","070_24_29","MAT","24","29","29","“Nan da nan bayan tsabar wahalan nan “ ‘sai a duhunta rana, wata kuma ba zai ba da haskensa ba; taurari kuma za su fāffāɗi daga sararin sama, za a kuma girgiza abubuwan sararin sama.’ ");
INSERT INTO hausa_vpl VALUES ("MT24_30","070_24_30","MAT","24","30","30","“A sa’an nan ne alamar dawowar Ɗan Mutum zai bayyana a sararin sama, dukan al’umman duniya kuwa za su yi kuka. Za su ga Ɗan Mutum yana zuwa kan gizagizan sararin sama, da iko da kuma ɗaukaka mai girma. ");
INSERT INTO hausa_vpl VALUES ("MT24_31","070_24_31","MAT","24","31","31","Zai kuwa aiki mala’ikunsa su busa ƙaho mai ƙara sosai, za su kuwa tattaro zaɓaɓɓunsa daga kusurwoyi huɗun nan, daga wannan bangon duniya zuwa wancan. ");
INSERT INTO hausa_vpl VALUES ("MT24_32","070_24_32","MAT","24","32","32","“Yanzu fa, sai ku koyi wannan darasi daga itacen ɓaure. Da zarar rassansa suka yi taushi ganyayensa kuma suka toho, kun san damina ta kusa. ");
INSERT INTO hausa_vpl VALUES ("MT24_33","070_24_33","MAT","24","33","33","Haka kuma, sa’ad da kun ga dukan waɗannan abubuwa, ku sani ya yi kusan zuwa, yana ma dab da bakin ƙofa. ");
INSERT INTO hausa_vpl VALUES ("MT24_34","070_24_34","MAT","24","34","34","Gaskiya nake gaya muku, wannan zamani ba zai shuɗe ba sai dukan abubuwan nan sun faru. ");
INSERT INTO hausa_vpl VALUES ("MT24_35","070_24_35","MAT","24","35","35","Sama da ƙasa za su shuɗe, amma maganata ba za tă taɓa shuɗe ba. ");
INSERT INTO hausa_vpl VALUES ("MT24_36","070_24_36","MAT","24","36","36","“Babu wanda ya san wannan rana ko sa’a, ko mala’ikun da suke sama ma, ko Ɗan, sai dai Uban kaɗai. ");
INSERT INTO hausa_vpl VALUES ("MT24_37","070_24_37","MAT","24","37","37","Kamar yadda ya faru a zamanin Nuhu, haka zai zama a dawowar Ɗan Mutum. ");
INSERT INTO hausa_vpl VALUES ("MT24_38","070_24_38","MAT","24","38","38","Gama a kwanaki kafin ruwan tsufana, mutane sun yi ta ci, sun kuma yi ta sha, suna aure, suna kuma aurarwa, har zuwa ranar da Nuhu ya shiga jirgi; ");
INSERT INTO hausa_vpl VALUES ("MT24_39","070_24_39","MAT","24","39","39","ba su kuwa san abin da yake faruwa ba sai da ruwan tsufana ya zo ya share su tas. Haka zai zama a dawowar Ɗan Mutum. ");
INSERT INTO hausa_vpl VALUES ("MT24_40","070_24_40","MAT","24","40","40","Maza biyu za su kasance a gona; za a ɗau ɗaya a bar ɗaya. ");
INSERT INTO hausa_vpl VALUES ("MT24_41","070_24_41","MAT","24","41","41","Mata biyu za su kasance suna niƙa; za a ɗau ɗaya a bar ɗaya. ");
INSERT INTO hausa_vpl VALUES ("MT24_42","070_24_42","MAT","24","42","42","“Saboda haka sai ku zauna a faɗake, gama ba ku san a wace rana ce Ubangijinku zai zo ba. ");
INSERT INTO hausa_vpl VALUES ("MT24_43","070_24_43","MAT","24","43","43","Ku dai gane wannan, da maigida ya san ko a wane lokaci ne da dare, ɓarawo zai zo, da sai yă zauna a faɗake yă kuma hana a shiga masa gida. ");
INSERT INTO hausa_vpl VALUES ("MT24_44","070_24_44","MAT","24","44","44","Saboda haka ku ma, sai ku zauna a faɗake, domin Ɗan Mutum zai zo a sa’ar da ba ku za tă ba. ");
INSERT INTO hausa_vpl VALUES ("MT24_45","070_24_45","MAT","24","45","45","“Wane ne bawan nan mai aminci da kuma mai hikima, wanda maigida ya sa yă lura da bayi a cikin gidansa, yă riƙa ba su abinci a daidai lokaci? ");
INSERT INTO hausa_vpl VALUES ("MT24_46","070_24_46","MAT","24","46","46","Zai zama wa bawan nan da kyau in maigidan ya dawo ya same shi yana yin haka. ");
INSERT INTO hausa_vpl VALUES ("MT24_47","070_24_47","MAT","24","47","47","Gaskiya nake gaya muku, zai sa shi yă lura da dukan dukiyarsa. ");
INSERT INTO hausa_vpl VALUES ("MT24_48","070_24_48","MAT","24","48","48","Amma in wannan bawa mugu ne, ya kuma ce a ransa, ‘Maigidana ba zai dawo da wuri ba.’ ");
INSERT INTO hausa_vpl VALUES ("MT24_49","070_24_49","MAT","24","49","49","Sa’an nan yă fara dūkan ’yan’uwansa bayi, yana ci yana kuma sha tare da mashaya. ");
INSERT INTO hausa_vpl VALUES ("MT24_50","070_24_50","MAT","24","50","50","Maigidan wannan bawa zai dawo a ranar da bai yi tsammani ba, a sa’ar kuma da bai sani ba. ");
INSERT INTO hausa_vpl VALUES ("MT24_51","070_24_51","MAT","24","51","51","Maigidan zai farfasa masa jiki da bulala, yă kuma ba shi wuri tare da munafukai, inda za a yi kuka da cizon haƙora. ");
INSERT INTO hausa_vpl VALUES ("MT25_1","070_25_1","MAT","25","1","1","“A lokacin mulkin sama zai zama kamar budurwai goma waɗanda suka ɗauki fitilunsu suka fita don su taryi ango. ");
INSERT INTO hausa_vpl VALUES ("MT25_2","070_25_2","MAT","25","2","2","Biyar daga cikinsu wawaye ne, biyar kuma masu hikima. ");
INSERT INTO hausa_vpl VALUES ("MT25_3","070_25_3","MAT","25","3","3","Wawayen sun ɗauki fitilunsu, sai dai ba su riƙe mai ba. ");
INSERT INTO hausa_vpl VALUES ("MT25_4","070_25_4","MAT","25","4","4","Masu hikimar kuwa suka riƙo tulunan mai da fitilunsu. ");
INSERT INTO hausa_vpl VALUES ("MT25_5","070_25_5","MAT","25","5","5","Ango ya yi jinkirin zuwa, sai duk suka shiga gyangyaɗi har barci ya kwashe su. ");
INSERT INTO hausa_vpl VALUES ("MT25_6","070_25_6","MAT","25","6","6","“Can tsakar dare, sai aka ji kira, ana cewa, ‘Ga ango nan! Ku fito, ku tarye shi!’ ");
INSERT INTO hausa_vpl VALUES ("MT25_7","070_25_7","MAT","25","7","7","“Sai dukan budurwan nan suka farka suka kuna fitilunsu. ");
INSERT INTO hausa_vpl VALUES ("MT25_8","070_25_8","MAT","25","8","8","Sai wawayen suka ce wa masu hikimar, ‘Ku ɗan sassam mana manku; fitilunmu suna mutuwa.’ ");
INSERT INTO hausa_vpl VALUES ("MT25_9","070_25_9","MAT","25","9","9","“Su kuwa suka amsa, suka ce, ‘A’a, wataƙila ba zai ishe mu da ku ba. Gara ku je wurin masu sayarwa ku sayo.’ ");
INSERT INTO hausa_vpl VALUES ("MT25_10","070_25_10","MAT","25","10","10","“Amma yayinda suke kan tafiya garin sayen mai, sai ango ya iso. Budurwai da suke a shirye, suka shiga wajen bikin auren tare da shi. Aka kuma kulle ƙofa. ");
INSERT INTO hausa_vpl VALUES ("MT25_11","070_25_11","MAT","25","11","11","“An jima can, sai ga sauran sun iso. Suka ce, ‘Ranka yă daɗe! Ranka yă daɗe! Ka buɗe mana ƙofa!’ ");
INSERT INTO hausa_vpl VALUES ("MT25_12","070_25_12","MAT","25","12","12","“Amma ya amsa ya ce, ‘Gaskiya nake gaya muku, ban san ku ba.’ ");
INSERT INTO hausa_vpl VALUES ("MT25_13","070_25_13","MAT","25","13","13","“Saboda haka sai ku zauna a faɗake, don ba ku san ranar ko sa’ar ba. ");
INSERT INTO hausa_vpl VALUES ("MT25_14","070_25_14","MAT","25","14","14","“Har wa yau, za a kwatanta shi da mutumin da zai yi tafiya, wanda ya kira bayinsa ya kuma danƙa musu mallakarsa. ");
INSERT INTO hausa_vpl VALUES ("MT25_15","070_25_15","MAT","25","15","15","Ga guda, ya ba shi talenti biyar na kuɗi, ga wani talenti biyu, ga wani kuma talenti ɗaya, kowa bisa ga azancinsa. Sa’an nan ya yi tafiyarsa. ");
INSERT INTO hausa_vpl VALUES ("MT25_16","070_25_16","MAT","25","16","16","Mutumin da ya karɓi talenti biyar, nan da nan ya tafi ya yi kasuwanci da su har ya sami ribar talenti biyar. ");
INSERT INTO hausa_vpl VALUES ("MT25_17","070_25_17","MAT","25","17","17","Haka ma, wannan mai talenti biyu, shi ma ya yi riba biyu. ");
INSERT INTO hausa_vpl VALUES ("MT25_18","070_25_18","MAT","25","18","18","Amma mutumin da ya karɓi talenti ɗaya ɗin, ya tafi, ya tona rami, ya ɓoye kuɗin maigidansa. ");
INSERT INTO hausa_vpl VALUES ("MT25_19","070_25_19","MAT","25","19","19","“Bayan an daɗe, sai maigidan bayin nan ya dawo, ya kuma daidaita lissafi da su. ");
INSERT INTO hausa_vpl VALUES ("MT25_20","070_25_20","MAT","25","20","20","Mutumin da ya karɓi talenti biyar, ya kawo ƙarin talenti biyar. Ya ce, ‘Maigida, ka danƙa mini talenti biyar. Ga shi, na yi ribar biyar.’ ");
INSERT INTO hausa_vpl VALUES ("MT25_21","070_25_21","MAT","25","21","21","“Maigidansa ya amsa ya ce, ‘Madalla, bawan kirki mai aminci! Ka yi aminci a kan abubuwa kaɗan, zan sa ka lura da abubuwa masu yawa. Zo ka yi farin ciki tare da maigidanka!’ ");
INSERT INTO hausa_vpl VALUES ("MT25_22","070_25_22","MAT","25","22","22","“Mutumin da yake da talenti biyu, shi ma ya zo ya ce, ‘Maigida, ka danƙa mini talenti biyu; ga shi, na yi ribar biyu.’ ");
INSERT INTO hausa_vpl VALUES ("MT25_23","070_25_23","MAT","25","23","23","“Maigidansa ya amsa ya ce, ‘Madalla, bawan kirki mai aminci! Ka yi aminci a kan abubuwa kaɗan, zan sa ka lura da abubuwa masu yawa. Zo ka yi farin ciki tare da maigidanka!’ ");
INSERT INTO hausa_vpl VALUES ("MT25_24","070_25_24","MAT","25","24","24","“Sa’an nan mutumin da ya karɓi talenti ɗaya ya zo. Ya ce, ‘Maigida, na san cewa kai mutum ne mai wuyan sha’ani, kana girbi inda ba ka shuka ba, kana kuma tara inda ba ka yafa iri ba. ");
INSERT INTO hausa_vpl VALUES ("MT25_25","070_25_25","MAT","25","25","25","Saboda haka na ji tsoro, na je na ɓoye talentinka a ƙasa. Ga abinka.’ ");
INSERT INTO hausa_vpl VALUES ("MT25_26","070_25_26","MAT","25","26","26","“Maigidansa ya amsa ya ce, ‘Kai mugun bawa, mai ƙyuya! Ashe, ka san cewa ina girbi inda ban yi shuka ba, ina kuma tarawa inda ban yafa iri ba? ");
INSERT INTO hausa_vpl VALUES ("MT25_27","070_25_27","MAT","25","27","27","To, in haka ne, ai, da ka sa kuɗina a banki, don sa’ad da na dawo da na karɓi abina da riba. ");
INSERT INTO hausa_vpl VALUES ("MT25_28","070_25_28","MAT","25","28","28","“ ‘Karɓi talentin daga hannunsa ku ba wanda yake da talenti goma. ");
INSERT INTO hausa_vpl VALUES ("MT25_29","070_25_29","MAT","25","29","29","Gama duk mai abu za a ƙara masa, zai kuma same shi a yawalce. Duk wanda ba shi da shi kuwa, ko ɗan abin da yake da shi ma, sai an karɓe masa. ");
INSERT INTO hausa_vpl VALUES ("MT25_30","070_25_30","MAT","25","30","30","Ku jefar da banzan bawan nan waje, cikin duhu, inda za a yi kuka da cizon haƙora.’ ");
INSERT INTO hausa_vpl VALUES ("MT25_31","070_25_31","MAT","25","31","31","“Sa’ad da Ɗan Mutum ya zo cikin ɗaukakarsa, tare da dukan mala’iku, zai zauna a kursiyinsa cikin ɗaukakar sama. ");
INSERT INTO hausa_vpl VALUES ("MT25_32","070_25_32","MAT","25","32","32","Za a tara dukan al’ummai a gabansa, zai kuma raba mutane dabam-dabam yadda makiyayi yakan ware tumaki daga awaki. ");
INSERT INTO hausa_vpl VALUES ("MT25_33","070_25_33","MAT","25","33","33","Zai sa tumaki a damansa, awaki kuma a hagunsa. ");
INSERT INTO hausa_vpl VALUES ("MT25_34","070_25_34","MAT","25","34","34","“Sa’an nan Sarki zai ce wa waɗanda suke damansa, ‘Ku zo, ku da Ubana ya yi wa albarka; ku karɓi gādonku, mulkin da aka shirya muku tun halittar duniya. ");
INSERT INTO hausa_vpl VALUES ("MT25_35","070_25_35","MAT","25","35","35","Gama da nake jin yunwa, kun ciyar da ni, da nake jin ƙishirwa, kun ba ni abin sha, da nake baƙunci, kun karɓe ni, ");
INSERT INTO hausa_vpl VALUES ("MT25_36","070_25_36","MAT","25","36","36","da nake bukatar tufafi, kun yi mini sutura, da na yi rashin lafiya, kun lura da ni, da nake kurkuku, kun ziyarce ni.’ ");
INSERT INTO hausa_vpl VALUES ("MT25_37","070_25_37","MAT","25","37","37","“Sa’an nan masu adalci za su amsa masa, su ce, ‘Ubangiji, yaushe muka gan ka da yunwa muka ciyar da kai, ko da ƙishirwa muka ba ka abin sha? ");
INSERT INTO hausa_vpl VALUES ("MT25_38","070_25_38","MAT","25","38","38","Yaushe kuma muka gan ka baƙo muka karɓe ka, ko cikin bukatar tufafi muka yi maka sutura? ");
INSERT INTO hausa_vpl VALUES ("MT25_39","070_25_39","MAT","25","39","39","Yaushe kuma muka gan ka cikin rashin lafiya ko a kurkuku muka ziyarce ka?’ ");
INSERT INTO hausa_vpl VALUES ("MT25_40","070_25_40","MAT","25","40","40","“Sarkin zai amsa ya ce, ‘Gaskiya nake gaya muku, duk abin da kuka yi wa ɗaya daga cikin waɗannan ’yan’uwana mafi ƙanƙanta, ni kuka yi wa.’ ");
INSERT INTO hausa_vpl VALUES ("MT25_41","070_25_41","MAT","25","41","41","“Sa’an nan zai ce wa waɗanda suke a hagunsa, ‘Ku rabu da ni, la’anannu, zuwa cikin madawwamiyar wutar da aka shirya don Iblis da mala’ikunsa. ");
INSERT INTO hausa_vpl VALUES ("MT25_42","070_25_42","MAT","25","42","42","Gama da nake jin yunwa, ba ku ba ni abinci ba, da nake jin ƙishirwa, ba ku ba ni abin sha ba, ");
INSERT INTO hausa_vpl VALUES ("MT25_43","070_25_43","MAT","25","43","43","da na yi baƙunci, ba ku karɓe ni ba, da nake bukatar tufafi, ba ku yi mini sutura ba, da na yi rashin lafiya kuma ina a kurkuku, ba ku lura da ni ba.’ ");
INSERT INTO hausa_vpl VALUES ("MT25_44","070_25_44","MAT","25","44","44","“Su ma za su amsa, su ce, ‘Ubangiji, yaushe muka gan ka cikin yunwa ko ƙishirwa ko baƙo ko cikin bukatar tufafi ko cikin rashin lafiya ko cikin kurkuku, ba mu taimake ka ba?’ ");
INSERT INTO hausa_vpl VALUES ("MT25_45","070_25_45","MAT","25","45","45","“Zai amsa, yă ce, ‘Gaskiya nake gaya muku, duk abin da ba ku yi wa ɗaya daga cikin waɗannan mafi ƙanƙanta ba, ba ku yi mini ba ke nan.’ ");
INSERT INTO hausa_vpl VALUES ("MT25_46","070_25_46","MAT","25","46","46","“Sa’an nan za su tafi cikin madawwamiyar hukunci, amma masu adalci kuwa za su shiga rai madawwami.” ");
INSERT INTO hausa_vpl VALUES ("MT26_1","070_26_1","MAT","26","1","1","Sa’ad da Yesu ya gama faɗin dukan waɗannan abubuwa, sai ya ce wa almajiransa, ");
INSERT INTO hausa_vpl VALUES ("MT26_2","070_26_2","MAT","26","2","2","“Kamar yadda kuka sani, Bikin Ƙetarewa sauran kwana biyu, za a kuma ba da Ɗan Mutum don a gicciye shi.” ");
INSERT INTO hausa_vpl VALUES ("MT26_3","070_26_3","MAT","26","3","3","Sai manyan firistoci da dattawan mutane, suka taru a fadan babban firist, mai suna Kayifas, ");
INSERT INTO hausa_vpl VALUES ("MT26_4","070_26_4","MAT","26","4","4","suka ƙulla shawara su kama Yesu da makirci, su kuma kashe shi. ");
INSERT INTO hausa_vpl VALUES ("MT26_5","070_26_5","MAT","26","5","5","Suka ce, “Amma ba a lokacin Biki ba, don kada mutane su tā da rikici.” ");
INSERT INTO hausa_vpl VALUES ("MT26_6","070_26_6","MAT","26","6","6","Yayinda Yesu yake a Betani, a gidan wani mutumin da ake kira Siman Kuturu, ");
INSERT INTO hausa_vpl VALUES ("MT26_7","070_26_7","MAT","26","7","7","wata mace ta zo wurinsa da wani ɗan tulun alabasta na turaren mai tsada sosai, wanda ta zuba a kansa a lokacin da yake cin abinci. ");
INSERT INTO hausa_vpl VALUES ("MT26_8","070_26_8","MAT","26","8","8","Sa’ad da almajiransa suka ga wannan, sai suka yi fushi. Suka ce, “Wannan almubazzaranci fa! ");
INSERT INTO hausa_vpl VALUES ("MT26_9","070_26_9","MAT","26","9","9","Wannan turare ai, da an sayar da shi da kuɗi mai yawa a ba matalauta kuɗin.” ");
INSERT INTO hausa_vpl VALUES ("MT26_10","070_26_10","MAT","26","10","10","Sane da wannan, Yesu ya ce musu, “Me ya sa kuke damun macen nan? Ta yi mini abu mai kyau ne. ");
INSERT INTO hausa_vpl VALUES ("MT26_11","070_26_11","MAT","26","11","11","Matalauta za su kasance tare da ku kullum, amma ni ba zan kasance tare da ku kullum ba. ");
INSERT INTO hausa_vpl VALUES ("MT26_12","070_26_12","MAT","26","12","12","Sa’ad da ta zuba turaren nan a jikina, ta shirya ni ne don jana’izata. ");
INSERT INTO hausa_vpl VALUES ("MT26_13","070_26_13","MAT","26","13","13","Gaskiya nake gaya muku, duk inda aka yi wa’azin bisharan nan a duniya duka, abin da matan nan ta yi, za a riƙa faɗarsa don tunawa da ita.” ");
INSERT INTO hausa_vpl VALUES ("MT26_14","070_26_14","MAT","26","14","14","Sai ɗaya daga cikin Sha Biyun nan, wanda ake kira Yahuda Iskariyot, ya je wurin manyan firistoci ");
INSERT INTO hausa_vpl VALUES ("MT26_15","070_26_15","MAT","26","15","15","ya ce, “Me za ku ba ni, in na bashe shi gare ku?” Sai suka ƙirga masa kuɗi azurfa talatin. ");
INSERT INTO hausa_vpl VALUES ("MT26_16","070_26_16","MAT","26","16","16","Daga wannan lokaci, Yahuda ya yi ta neman zarafin da zai miƙa shi. ");
INSERT INTO hausa_vpl VALUES ("MT26_17","070_26_17","MAT","26","17","17","A rana ta fari ta Bikin Burodi Marar Yisti, sai almajiran suka zo wurin Yesu suka yi tambaya suka ce, “Ina kake so mu je mu shirya maka wurin da za ka ci Bikin Ƙetarewa?” ");
INSERT INTO hausa_vpl VALUES ("MT26_18","070_26_18","MAT","26","18","18","Ya amsa ya ce, “Ku shiga gari wurin wāne, ku ce masa, ‘Malam ya ce, lokacina ya yi kusa. Zan ci Bikin Ƙetarewa tare da almajiraina a gidanka.’ ” ");
INSERT INTO hausa_vpl VALUES ("MT26_19","070_26_19","MAT","26","19","19","Saboda haka almajiran suka yi yadda Yesu ya umarce su, suka kuwa shirya Bikin Ƙetarewa. ");
INSERT INTO hausa_vpl VALUES ("MT26_20","070_26_20","MAT","26","20","20","Da yamma ta yi, sai Yesu ya zauna don cin abinci tare da Sha Biyun. ");
INSERT INTO hausa_vpl VALUES ("MT26_21","070_26_21","MAT","26","21","21","Yayinda suke cin abinci, sai ya ce, “Gaskiya nake gaya muku, ɗayanku zai bashe ni.” ");
INSERT INTO hausa_vpl VALUES ("MT26_22","070_26_22","MAT","26","22","22","Suka yi baƙin ciki ƙwarai, suka fara ce masa da ɗaya-ɗaya, “Gaskiya nake gaya muku, ɗayanku zai bashe ni.” ");
INSERT INTO hausa_vpl VALUES ("MT26_23","070_26_23","MAT","26","23","23","Yesu ya amsa ya ce, “Wanda ya sa hannunsa a kwano tare da ni ne, zai bashe ni. ");
INSERT INTO hausa_vpl VALUES ("MT26_24","070_26_24","MAT","26","24","24","Ɗan Mutum zai tafi kamar yadda aka rubuta game da shi. Amma kaiton mutumin da zai bashe Ɗan Mutum! Da ma ba a haifi mutumin nan ba, da ya fi masa.” ");
INSERT INTO hausa_vpl VALUES ("MT26_25","070_26_25","MAT","26","25","25","Sa’an nan Yahuda, wanda zai bashe shi ya ce, “Tabbatacce ba ni ba ne, ko, Rabbi?” Yesu ya amsa ya ce, “I, kai ma ka fada.” ");
INSERT INTO hausa_vpl VALUES ("MT26_26","070_26_26","MAT","26","26","26","Yayinda suke cikin cin abinci, Yesu ya ɗauki burodi, ya yi godiya ya kuma kakkarya, ya ba wa almajiransa yana cewa, “Ku karɓa ku ci; wannan jikina ne.” ");
INSERT INTO hausa_vpl VALUES ("MT26_27","070_26_27","MAT","26","27","27","Sa’an nan ya ɗauki kwaf, ya yi godiya, ya kuma ba su, yana cewa, “Ku shassha daga cikinsa, dukanku. ");
INSERT INTO hausa_vpl VALUES ("MT26_28","070_26_28","MAT","26","28","28","Wannan jinina ne na sabon alkawari, wanda aka zubar saboda mutane da yawa, don gafarar zunubai. ");
INSERT INTO hausa_vpl VALUES ("MT26_29","070_26_29","MAT","26","29","29","Ina gaya muku, ba zan ƙara shan ruwan inabin nan ba har sai ranar da zan sha shi sabo tare da ku a mulkin Ubana.” ");
INSERT INTO hausa_vpl VALUES ("MT26_30","070_26_30","MAT","26","30","30","Da suka rera waƙa, sai suka fita, suka tafi Dutsen Zaitun. ");
INSERT INTO hausa_vpl VALUES ("MT26_31","070_26_31","MAT","26","31","31","Sai Yesu ya ce musu, “A wannan dare, dukanku za ku ja da baya saboda ni, gama a rubuce yake cewa, “ ‘Zan bugi makiyayin, tumakin garken kuwa za su fasu.’ ");
INSERT INTO hausa_vpl VALUES ("MT26_32","070_26_32","MAT","26","32","32","Amma bayan na tashi, zan sha gabanku zuwa Galili.” ");
INSERT INTO hausa_vpl VALUES ("MT26_33","070_26_33","MAT","26","33","33","Bitrus ya amsa ya ce, “Ko da duka sun ja da baya saboda kai, ba zan taɓa ja da baya ba.” ");
INSERT INTO hausa_vpl VALUES ("MT26_34","070_26_34","MAT","26","34","34","Yesu ya amsa ya ce, “Gaskiya nake gaya maka, a daren nan, kafin zakara yă yi cara, za ka yi mūsun sanina sau uku.” ");
INSERT INTO hausa_vpl VALUES ("MT26_35","070_26_35","MAT","26","35","35","Bitrus ya furta, “Ko da ma zan mutu ne tare da kai, ba zan taɓa yin mūsun saninka ba.” Dukan sauran almajiran ma suka faɗa haka. ");
INSERT INTO hausa_vpl VALUES ("MT26_36","070_26_36","MAT","26","36","36","Sa’an nan Yesu ya tafi da almajiransa zuwa wani wurin da ake kira Getsemane, ya ce musu, “Ku zauna nan, in je can in yi addu’a.” ");
INSERT INTO hausa_vpl VALUES ("MT26_37","070_26_37","MAT","26","37","37","Ya ɗauki Bitrus da ’ya’ya biyun nan na Zebedi tare da shi, sai ya fara baƙin ciki, ya kuma damu. ");
INSERT INTO hausa_vpl VALUES ("MT26_38","070_26_38","MAT","26","38","38","Sai ya ce musu, “Raina yana cike da baƙin ciki har kamar zan mutu. Ku dakata a nan, ku kuma yi tsaro tare da ni.” ");
INSERT INTO hausa_vpl VALUES ("MT26_39","070_26_39","MAT","26","39","39","Da ya yi gaba kaɗan, sai ya fāɗi a ƙasa, ya yi addu’a ya ce, “Ubana, in mai yiwuwa ne, a ɗauke mini wannan kwaf. Amma ba nufina ba, sai naka.” ");
INSERT INTO hausa_vpl VALUES ("MT26_40","070_26_40","MAT","26","40","40","Sa’an nan ya komo wurin almajiransa, ya tarar suna barci. Ya tambayi Bitrus ya ce, “Ashe, ba za ku iya yin tsaro tare da ni ko na sa’a guda ba? ");
INSERT INTO hausa_vpl VALUES ("MT26_41","070_26_41","MAT","26","41","41","Ku yi tsaro, ku kuma yi addu’a, don kada ku fāɗi cikin jarraba. Ruhu yana so, sai dai jiki raunana ne.” ");
INSERT INTO hausa_vpl VALUES ("MT26_42","070_26_42","MAT","26","42","42","Ya sāke tafiya sau na biyu, ya yi addu’a ya ce, “Ubana, in ba zai yiwu a ɗauke wannan kwaf ba sai na sha shi, to, bari a aikata nufinka.” ");
INSERT INTO hausa_vpl VALUES ("MT26_43","070_26_43","MAT","26","43","43","Da ya dawo, har yanzu ya tarar suna barci, domin idanunsu sun yi nauyi da barci. ");
INSERT INTO hausa_vpl VALUES ("MT26_44","070_26_44","MAT","26","44","44","Saboda haka ya sāke barinsu, ya yi addu’a sau na uku, yana maimaita iri abu guda. ");
INSERT INTO hausa_vpl VALUES ("MT26_45","070_26_45","MAT","26","45","45","Sa’an nan ya komo wurin almajiransa, ya ce musu, “Har yanzu kuna barci kuna hutawa ba? Ga shi, sa’a ta yi kusa, an kuma bashe Ɗan Mutum a hannuwan masu zunubi. ");
INSERT INTO hausa_vpl VALUES ("MT26_46","070_26_46","MAT","26","46","46","Ku tashi, mu tafi! Ga mai bashe ni nan yana zuwa!” ");
INSERT INTO hausa_vpl VALUES ("MT26_47","070_26_47","MAT","26","47","47","Yayinda yana cikin magana, sai Yahuda, ɗaya daga cikin Sha Biyun nan, ya iso. Tare da shi kuwa ga taro mai yawa riƙe da takuba da sanduna, manyan firistoci da dattawan mutane ne suka turo su. ");
INSERT INTO hausa_vpl VALUES ("MT26_48","070_26_48","MAT","26","48","48","To, mai bashe shi ɗin, ya riga ya shirya alama da su, “Wanda na yi masa sumba, shi ne mutumin; ku kama shi.” ");
INSERT INTO hausa_vpl VALUES ("MT26_49","070_26_49","MAT","26","49","49","Da zuwansa, sai ya miƙe zuwa wurin Yesu ya ce, “Gaisuwa, Rabbi!” Sa’an nan ya yi masa sumba. ");
INSERT INTO hausa_vpl VALUES ("MT26_50","070_26_50","MAT","26","50","50","Yesu ya amsa ya ce, “Aboki, yi abin da ya kawo ka.” Sa’an nan mutanen suka matso, suka kama Yesu suka riƙe shi. ");
INSERT INTO hausa_vpl VALUES ("MT26_51","070_26_51","MAT","26","51","51","Ganin haka, sai ɗaya daga cikin waɗanda suke tare da Yesu, ya zaro takobinsa ya kai wa bawan babban firist sara, ya fille masa kunne. ");
INSERT INTO hausa_vpl VALUES ("MT26_52","070_26_52","MAT","26","52","52","Sai Yesu ya ce, masa, “Mai da takobinka kube, gama duk masu zare takobi, a takobi za su mutu. ");
INSERT INTO hausa_vpl VALUES ("MT26_53","070_26_53","MAT","26","53","53","Kuna tsammani ba zan iya kira Ubana, nan take kuwa yă aiko mini fiye da rundunar mala’iku goma sha biyu ba? ");
INSERT INTO hausa_vpl VALUES ("MT26_54","070_26_54","MAT","26","54","54","Amma ta yaya za a cika Nassin da ya ce dole haka yă faru?” ");
INSERT INTO hausa_vpl VALUES ("MT26_55","070_26_55","MAT","26","55","55","A wannan lokaci sai Yesu ya ce wa taron, “Ina jagoran wani tawaye ne, da kuka fito da takuba da kuma sanduna domin ku kama ni? Kowace rana ina zama a filin haikali ina koyarwa, ba ku kuwa kama ni ba. ");
INSERT INTO hausa_vpl VALUES ("MT26_56","070_26_56","MAT","26","56","56","Amma wannan duka ya faru ne don a cika rubuce-rubucen annabawa.” Sa’an nan dukan almajiran suka yashe shi suka gudu. ");
INSERT INTO hausa_vpl VALUES ("MT26_57","070_26_57","MAT","26","57","57","Waɗanda suka kama Yesu kuwa suka kai shi wurin Kayifas, babban firist, inda malaman dokoki da dattawa suka taru. ");
INSERT INTO hausa_vpl VALUES ("MT26_58","070_26_58","MAT","26","58","58","Amma Bitrus ya bi daga nesa, har zuwa cikin filin gidan babban firist. Ya shiga, ya zauna tare da masu gadi, don yă ga ƙarshen abin. ");
INSERT INTO hausa_vpl VALUES ("MT26_59","070_26_59","MAT","26","59","59","Sai manyan firistoci da ’yan majalisa duka suka yi ta neman shaidar ƙarya a kan Yesu, don su sami dama su kashe shi. ");
INSERT INTO hausa_vpl VALUES ("MT26_60","070_26_60","MAT","26","60","60","Amma ba su sami ko ɗaya ba, ko da yake masu shaidar ƙarya da yawa sun firfito. A ƙarshe, biyu suka zo gaba, ");
INSERT INTO hausa_vpl VALUES ("MT26_61","070_26_61","MAT","26","61","61","suka furta cewa, “Wannan mutum ya ce, ‘Ina iya rushe haikalin Allah, in sāke gina shi cikin kwana uku.’ ” ");
INSERT INTO hausa_vpl VALUES ("MT26_62","070_26_62","MAT","26","62","62","Sa’an nan babban firist ya miƙe tsaye, ya ce wa Yesu, “Ba ka da wata amsa? Shaidar da mutanen nan suke yi a kanka fa?” ");
INSERT INTO hausa_vpl VALUES ("MT26_63","070_26_63","MAT","26","63","63","Amma Yesu ya yi shiru. Sai babban firist ya ce masa, “Na haɗa ka da Allah mai rai. Faɗa mana in kai ne Kiristi, Ɗan Allah.” ");
INSERT INTO hausa_vpl VALUES ("MT26_64","070_26_64","MAT","26","64","64","Sai Yesu ya amsa ya ce, “I, haka yake yadda ka faɗa. Sai dai ina gaya muku duka, nan gaba, za ku ga Ɗan Mutum zaune a hannun dama na Mai Iko, yana kuma zuwa a kan gizagizan sama.” ");
INSERT INTO hausa_vpl VALUES ("MT26_65","070_26_65","MAT","26","65","65","Sa’an nan babban firist ya yage tufafinsa ya ce, “Ya yi saɓo! Don me muke bukatar ƙarin shaidu? Ga shi, yanzu kun dai ji saɓon. ");
INSERT INTO hausa_vpl VALUES ("MT26_66","070_26_66","MAT","26","66","66","Me kuka gani?” Suka amsa, suka ce, “Ya cancanci mutuwa.” ");
INSERT INTO hausa_vpl VALUES ("MT26_67","070_26_67","MAT","26","67","67","Sai suka tottofa masa miyau a fuskarsa, suka kuma bubbuge shi da hannuwansu. Waɗansu kuma suka mammare shi ");
INSERT INTO hausa_vpl VALUES ("MT26_68","070_26_68","MAT","26","68","68","suka ce, “Yi mana annabci, Kiristi. Wa ya buge ka?” ");
INSERT INTO hausa_vpl VALUES ("MT26_69","070_26_69","MAT","26","69","69","To, Bitrus yana nan zaune a filin, sai wata yarinya baiwa, ta zo wurinsa. Ta ce, “Kai ma kana tare da Yesu mutumin Galili.” ");
INSERT INTO hausa_vpl VALUES ("MT26_70","070_26_70","MAT","26","70","70","Amma ya yi mūsu a gabansu duka. Ya ce, “Ban san abin da kike magana ba.” ");
INSERT INTO hausa_vpl VALUES ("MT26_71","070_26_71","MAT","26","71","71","Sa’an nan ya fito zuwa hanyar shiga, inda wata yarinya kuma ta gan shi, ta ce wa mutanen da suke can, “Wannan mutum ma yana tare da Yesu Banazare.” ");
INSERT INTO hausa_vpl VALUES ("MT26_72","070_26_72","MAT","26","72","72","Ya sāke mūsu har da rantsuwa, yana cewa, “Ban ma san mutumin nan ba!” ");
INSERT INTO hausa_vpl VALUES ("MT26_73","070_26_73","MAT","26","73","73","Bayan ɗan lokaci, sai na tsattsaye a wurin, suka hauro wurin Bitrus, suka ce, “Tabbatacce, kai ɗayansu ne, don harshen maganarka, ya tone ka.” ");
INSERT INTO hausa_vpl VALUES ("MT26_74","070_26_74","MAT","26","74","74","Sai ya fara la’antar kansa, yana ta rantsuwa yana ce musu, “Ban ma san mutumin nan ba!” Nan da take, sai zakara ya yi cara. ");
INSERT INTO hausa_vpl VALUES ("MT26_75","070_26_75","MAT","26","75","75","Sai Bitrus ya tuna da maganar da Yesu ya yi cewa, “Kafin zakara yă yi cara, za ka yi mūsun sani na sau uku.” Sai ya fita waje, ya yi ta kuka. ");
INSERT INTO hausa_vpl VALUES ("MT27_1","070_27_1","MAT","27","1","1","Da wayewar gari, sai dukan manyan firistoci da dattawan mutane suka yanke shawara su kashe Yesu. ");
INSERT INTO hausa_vpl VALUES ("MT27_2","070_27_2","MAT","27","2","2","Suka daure shi, suka tafi da shi, suka ba da shi ga gwamna Bilatus. ");
INSERT INTO hausa_vpl VALUES ("MT27_3","070_27_3","MAT","27","3","3","Sa’ad da Yahuda, wanda ya bashe Yesu, ya ga an yanke wa Yesu hukuncin kisa, sai ya yi “da na sani.” Ya je mayar wa manyan firistoci da dattawan kuɗin azurfa talatin ɗin. ");
INSERT INTO hausa_vpl VALUES ("MT27_4","070_27_4","MAT","27","4","4","Ya ce, “Na yi zunubi da na ci amanar marar laifi.” Suka ce masa, “Ina ruwanmu da wannan? Wannan dai ruwanka ne.” ");
INSERT INTO hausa_vpl VALUES ("MT27_5","070_27_5","MAT","27","5","5","Sai Yahuda ya zubar da kuɗin a cikin haikalin ya tafi. Sa’an nan ya je ya rataye kansa. ");
INSERT INTO hausa_vpl VALUES ("MT27_6","070_27_6","MAT","27","6","6","Manyan firistoci suka ɗauki kuɗin, suka ce, “Doka ta hana a sa kuɗin a cikin ma’aji, da yake kuɗin jini ne.” ");
INSERT INTO hausa_vpl VALUES ("MT27_7","070_27_7","MAT","27","7","7","Saboda haka, sai suka yanke shawara su yi amfani da kuɗin suka sayi filin mai yin tukwane, saboda binne baƙi. ");
INSERT INTO hausa_vpl VALUES ("MT27_8","070_27_8","MAT","27","8","8","Shi ya sa ake kiran filin, Filin Jini har yă zuwa yau. ");
INSERT INTO hausa_vpl VALUES ("MT27_9","070_27_9","MAT","27","9","9","Sai abin da aka faɗa ta bakin annabi Irmiya ya cika cewa, “Suka ɗauki azurfa talatin, kuɗin da mutanen Isra’ila suka sa a kansa, ");
INSERT INTO hausa_vpl VALUES ("MT27_10","070_27_10","MAT","27","10","10","suka kuma yi amfani da su, suka sayi filin mai yin tukwane, kamar yadda Ubangiji ya umarce ni.” ");
INSERT INTO hausa_vpl VALUES ("MT27_11","070_27_11","MAT","27","11","11","Ana cikin haka, Yesu kuwa yana tsaye a gaban gwamna, sai gwamnan ya tambaye shi, “Kai ne Sarkin Yahudawa?” Yesu ya ce, “I, haka ne, kamar yadda ka faɗa.” ");
INSERT INTO hausa_vpl VALUES ("MT27_12","070_27_12","MAT","27","12","12","Da manyan firistoci da dattawa suka zarge shi, bai ba da amsa ba. ");
INSERT INTO hausa_vpl VALUES ("MT27_13","070_27_13","MAT","27","13","13","Sai Bilatus ya tambaye shi ya ce, “Ba ka jin shaidar da suke kawowa a kanka?” ");
INSERT INTO hausa_vpl VALUES ("MT27_14","070_27_14","MAT","27","14","14","Amma Yesu bai ce uffam game da ko ɗaya daga cikin zargin da suka yi masa ba. Har gwamna ya yi mamaki ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("MT27_15","070_27_15","MAT","27","15","15","A wannan irin Biki, gwamna yana da wata al’ada, ta sakin ɗan kurkuku guda wanda taron suka zaɓa. ");
INSERT INTO hausa_vpl VALUES ("MT27_16","070_27_16","MAT","27","16","16","To, a wannan lokaci kuwa suna da wani shahararren ɗan kurkuku da ake kira Barabbas. ");
INSERT INTO hausa_vpl VALUES ("MT27_17","070_27_17","MAT","27","17","17","Saboda haka da taron suka taru, sai Bilatus ya tambaye su ya ce, “Wane ne a cikinsu kuke so in sakar muku. Barabbas ko Yesu wanda ake kira Kiristi?” ");
INSERT INTO hausa_vpl VALUES ("MT27_18","070_27_18","MAT","27","18","18","Don ya san saboda sonkai ne suka ba da Yesu a gare shi. ");
INSERT INTO hausa_vpl VALUES ("MT27_19","070_27_19","MAT","27","19","19","Yayinda Bilatus yake zaune a kan kujerar shari’a, sai matarsa ta aika masa da wannan saƙo cewa, “Kada ka sa hannunka a kan marar laifin nan, domin na sha wahala ƙwarai, a cikin mafarki yau game da shi.” ");
INSERT INTO hausa_vpl VALUES ("MT27_20","070_27_20","MAT","27","20","20","Amma manyan firistoci da dattawa suka shawo kan taron, su ce, a ba su Barabbas, amma a kashe Yesu. ");
INSERT INTO hausa_vpl VALUES ("MT27_21","070_27_21","MAT","27","21","21","Gwamna ya yi tambaya ya ce, “Wane ne cikin biyun nan, kuke so in sakar muku?” Suka ce, “Barabbas.” ");
INSERT INTO hausa_vpl VALUES ("MT27_22","070_27_22","MAT","27","22","22","Bilatus ya yi tambaya, “To, me zan yi da Yesu wanda ake kira Kiristi?” Duka suka ce, “A gicciye shi!” ");
INSERT INTO hausa_vpl VALUES ("MT27_23","070_27_23","MAT","27","23","23","Bilatus ya ce, “Don me? Wane laifi ya yi?” Amma suka ƙara tā da ihu, suna cewa, “A gicciye shi!” ");
INSERT INTO hausa_vpl VALUES ("MT27_24","070_27_24","MAT","27","24","24","Da Bilatus ya ga cewa ba ya kaiwa ko’ina, sai ma hargitsi ne yake so yă tashi, sai ya ɗibi ruwa, ya wanke hannuwansa a gaban taron ya ce, “Ni kam, ba ruwana da alhakin jinin mutumin nan. Wannan ruwanku ne!” ");
INSERT INTO hausa_vpl VALUES ("MT27_25","070_27_25","MAT","27","25","25","Sai dukan mutane suka amsa, suka ce, “Bari alhakin jininsa yă zauna a kanmu da ’ya’yanmu!” ");
INSERT INTO hausa_vpl VALUES ("MT27_26","070_27_26","MAT","27","26","26","Sai ya sakar musu Barabbas. Amma ya sa aka yi wa Yesu bulala, sa’an nan ya ba da shi a gicciye. ");
INSERT INTO hausa_vpl VALUES ("MT27_27","070_27_27","MAT","27","27","27","Sai sojojin gwamna suka ɗauki Yesu suka kai shi Fadar mai mulki, sa’an nan suka tara dukan kamfanin sojoji kewaye da shi. ");
INSERT INTO hausa_vpl VALUES ("MT27_28","070_27_28","MAT","27","28","28","Suka tuɓe shi, suka yafa masa wata jar riga. ");
INSERT INTO hausa_vpl VALUES ("MT27_29","070_27_29","MAT","27","29","29","Suka kuma tuƙa wani rawanin ƙaya, suka sa masa a kā. Suka sa sanda a hannun damansa. Suka durƙusa a gabansa, suka yi masa ba’a, suna cewa, “Ranka yă daɗe sarkin Yahudawa!” ");
INSERT INTO hausa_vpl VALUES ("MT27_30","070_27_30","MAT","27","30","30","Suka tattofa masa miyau, suka karɓe sandan, suka yi ta ƙwala masa shi a kai. ");
INSERT INTO hausa_vpl VALUES ("MT27_31","070_27_31","MAT","27","31","31","Bayan sun yi masa ba’a, sai suka tuɓe masa rigar, suka sa masa nasa tufafin. Sai suka tafi da shi, domin su gicciye shi. ");
INSERT INTO hausa_vpl VALUES ("MT27_32","070_27_32","MAT","27","32","32","Suna fitowa ke nan, sai suka sadu da wani mutumin Sairin, mai suna Siman. Sai suka tilasta shi ya ɗauki gicciyen. ");
INSERT INTO hausa_vpl VALUES ("MT27_33","070_27_33","MAT","27","33","33","Sai suka iso wani wurin da ake kira Golgota (wanda yake nufin Wurin Ƙoƙon Kai). ");
INSERT INTO hausa_vpl VALUES ("MT27_34","070_27_34","MAT","27","34","34","A can, suka ba shi ruwan inabi gauraye da wani abu mai ɗaci yă sha. Amma da ya ɗanɗana, sai ya ƙi sha. ");
INSERT INTO hausa_vpl VALUES ("MT27_35","070_27_35","MAT","27","35","35","Bayan da suka gicciye shi, sai suka raba tufafinsa a tsakaninsu ta wurin jefa ƙuri’a. ");
INSERT INTO hausa_vpl VALUES ("MT27_36","070_27_36","MAT","27","36","36","Sa’an nan suka zauna suna tsaronsa. ");
INSERT INTO hausa_vpl VALUES ("MT27_37","070_27_37","MAT","27","37","37","Bisa da kansa kuwa, an kafa rubutun zargin da aka yi masa, da ya ce, Wannan shi ne Yesu Sarkin Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("MT27_38","070_27_38","MAT","27","38","38","An gicciye ’yan fashi biyu tare da shi, ɗaya a damansa, ɗaya kuma a hagunsa. ");
INSERT INTO hausa_vpl VALUES ("MT27_39","070_27_39","MAT","27","39","39","Masu wucewa, suka zazzage shi, suna kaɗa kai, ");
INSERT INTO hausa_vpl VALUES ("MT27_40","070_27_40","MAT","27","40","40","suna cewa, “Kai da za ka rushe haikali, ka kuma gina shi cikin kwana uku, ceci kanka mana! In kai Ɗan Allah ne, ka sauka daga gicciyen!” ");
INSERT INTO hausa_vpl VALUES ("MT27_41","070_27_41","MAT","27","41","41","Haka ma, manyan firistoci da malaman dokoki da kuma dattawa, suka yi ta yin masa ba’a, suna cewa, ");
INSERT INTO hausa_vpl VALUES ("MT27_42","070_27_42","MAT","27","42","42","“Ya ceci waɗansu, amma ya kāsa ceton kansa! In shi ne Sarkin Isra’ila! To, yă sauko daga kan gicciyen nan, mu kuwa mu gaskata shi. ");
INSERT INTO hausa_vpl VALUES ("MT27_43","070_27_43","MAT","27","43","43","Ya dogara ga Allah. Bari Allah yă cece shi yanzu, in yana sonsa, domin ya ce, ‘Ni Ɗan Allah ne.’ ” ");
INSERT INTO hausa_vpl VALUES ("MT27_44","070_27_44","MAT","27","44","44","Haka ma, ’yan fashin da aka gicciye tare da shi, suka zazzage shi. ");
INSERT INTO hausa_vpl VALUES ("MT27_45","070_27_45","MAT","27","45","45","Daga sa’a ta shida, har zuwa sa’a ta tara, duhu ya rufe ƙasa duka. ");
INSERT INTO hausa_vpl VALUES ("MT27_46","070_27_46","MAT","27","46","46","Wajen sa’a ta tara, Yesu ya ɗaga murya da ƙarfi ya ce, “Eloi, Eloi,lama sabaktani?” (Wato, “Ya Allahna, ya Allahna, don me ka yashe ni?”). ");
INSERT INTO hausa_vpl VALUES ("MT27_47","070_27_47","MAT","27","47","47","Sa’ad da waɗanda suke tsattsaye a wurin suka ji haka, sai suka ce, “Yana kiran Iliya.” ");
INSERT INTO hausa_vpl VALUES ("MT27_48","070_27_48","MAT","27","48","48","Nan da nan, ɗaya daga cikinsu ya ruga, ya sami soso, ya jiƙa shi da ruwan tsami, ya sa a sanda, ya miƙa wa Yesu, yă sha. ");
INSERT INTO hausa_vpl VALUES ("MT27_49","070_27_49","MAT","27","49","49","Sauran kuwa suka ce, “Ƙyale shi mu ga, ko Iliya zai zo yă cece shi.” ");
INSERT INTO hausa_vpl VALUES ("MT27_50","070_27_50","MAT","27","50","50","Da Yesu ya sāke ɗaga murya da ƙarfi, sai ya saki ruhunsa. ");
INSERT INTO hausa_vpl VALUES ("MT27_51","070_27_51","MAT","27","51","51","A daidai wannan lokaci, sai labulen haikali ya tsage gida biyu, daga sama har ƙasa. Ƙasa ta jijjiga, duwatsu kuma suka farfashe. ");
INSERT INTO hausa_vpl VALUES ("MT27_52","070_27_52","MAT","27","52","52","Kaburbura suka bubbuɗe, jikunan tsarkaka da yawa kuwa cikin waɗanda da suka mutu, suka tashi. ");
INSERT INTO hausa_vpl VALUES ("MT27_53","070_27_53","MAT","27","53","53","Suka firfito daga kaburbura, sa’an nan bayan tashin Yesu daga matattu, suka shiga birni mai tsarki, suka bayyana ga mutane da yawa. ");
INSERT INTO hausa_vpl VALUES ("MT27_54","070_27_54","MAT","27","54","54","Da jarumin nan tare da waɗanda suke tsaron Yesu, suka ga girgizar ƙasa, da kuma abin da ya faru, sai tsoro ya kama su, suka kuma ce, “Gaskiya, wannan Ɗan Allah ne!” ");
INSERT INTO hausa_vpl VALUES ("MT27_55","070_27_55","MAT","27","55","55","Akwai mata da yawa a can, suna kallo daga nesa. Sun bi Yesu tun daga Galili, suna masa hidima. ");
INSERT INTO hausa_vpl VALUES ("MT27_56","070_27_56","MAT","27","56","56","A cikinsu, akwai Maryamu Magdalin, da Maryamu uwar Yaƙub da Yoses, da kuma uwar ’ya’yan Zebedi. ");
INSERT INTO hausa_vpl VALUES ("MT27_57","070_27_57","MAT","27","57","57","Da yamma ta yi, sai ga wani mutum mai arziki daga Arimateya, sunansa Yusuf, wanda shi da kansa almajirin Yesu ne. ");
INSERT INTO hausa_vpl VALUES ("MT27_58","070_27_58","MAT","27","58","58","Ya je wurin Bilatus, ya roƙe shi yă ba shi jikin Yesu. Sai Bilatus ya umarta a ba shi. ");
INSERT INTO hausa_vpl VALUES ("MT27_59","070_27_59","MAT","27","59","59","Yusuf ya ɗauki jikin ya nannaɗe shi da zanen lilin mai tsabta. ");
INSERT INTO hausa_vpl VALUES ("MT27_60","070_27_60","MAT","27","60","60","Sa’an nan ya sa shi a sabon kabarinsa, wanda ya haƙa a dutse. Bayan ya gungura wani babban dutse ya rufe bakin kabarin, sai ya tafi abinsa. ");
INSERT INTO hausa_vpl VALUES ("MT27_61","070_27_61","MAT","27","61","61","Maryamu Magdalin da ɗayan Maryamun, suna zaune a wurin, ɗaura da kabarin. ");
INSERT INTO hausa_vpl VALUES ("MT27_62","070_27_62","MAT","27","62","62","Kashegari, wato, bayan Ranar Shirye-shirye, sai manyan firistoci da Farisiyawa, suka je wurin Bilatus. ");
INSERT INTO hausa_vpl VALUES ("MT27_63","070_27_63","MAT","27","63","63","Suka ce, “Ranka yă daɗe, mun tuna, mai ruɗin nan tun yana da rai ya ce, ‘Bayan kwana uku, zan tashi daga matattu.’ ");
INSERT INTO hausa_vpl VALUES ("MT27_64","070_27_64","MAT","27","64","64","Saboda haka, ka ba da umarni, a tsare kabarin sai rana ta uku ɗin. In ba haka ba, almajiransa za su iya zuwa su sace jikin, sa’an nan su faɗa wa mutane cewa, an tashe shi daga matattu. Ruɗin ƙarshen nan fa, sai yă fi na farkon muni.” ");
INSERT INTO hausa_vpl VALUES ("MT27_65","070_27_65","MAT","27","65","65","Sai Bilatus ya ce, “Shi ke nan, ku ɗebi soja, ku je ku tsare kabarin iya ƙoƙarinku.” ");
INSERT INTO hausa_vpl VALUES ("MT27_66","070_27_66","MAT","27","66","66","Sai suka je suka tsare kabarin ta wurin buga masa hatimi, suka kuma sa masu gadi. ");
INSERT INTO hausa_vpl VALUES ("MT28_1","070_28_1","MAT","28","1","1","Bayan ranar Asabbaci, da sassafe, a ranar farko ta mako, Maryamu Magdalin tare da ɗaya Maryamun, suka je don su ga kabarin. ");
INSERT INTO hausa_vpl VALUES ("MT28_2","070_28_2","MAT","28","2","2","Sai aka yi wata babbar girgizar ƙasa. Don wani mala’ikan Ubangiji ya sauka daga sama, ya je kabarin, ya gungurar da dutsen, ya kuma zauna a kai. ");
INSERT INTO hausa_vpl VALUES ("MT28_3","070_28_3","MAT","28","3","3","Kamanninsa yana kama da walƙiya, tufafinsa kuma fari fat kamar dusan ƙanƙara. ");
INSERT INTO hausa_vpl VALUES ("MT28_4","070_28_4","MAT","28","4","4","Masu gadin kabarin kuma suka ji tsoro ƙwarai, suka yi rawan jiki, suka zama kamar matattu. ");
INSERT INTO hausa_vpl VALUES ("MT28_5","070_28_5","MAT","28","5","5","Mala’ikan ya ce wa matan, “Kada ku ji tsoro, domin na san cewa kuna neman Yesu wanda aka gicciye ne. ");
INSERT INTO hausa_vpl VALUES ("MT28_6","070_28_6","MAT","28","6","6","Ai, ba ya nan, ya tashi kamar yadda ya faɗa. Ku zo ku ga inda ya kwanta. ");
INSERT INTO hausa_vpl VALUES ("MT28_7","070_28_7","MAT","28","7","7","Sai ku tafi da sauri ku gaya wa almajiransa cewa, ‘Ya tashi daga matattu, ya kuma ya sha gabanku zuwa Galili. Can za ku gan shi.’ Ga shi na faɗa muku.” ");
INSERT INTO hausa_vpl VALUES ("MT28_8","070_28_8","MAT","28","8","8","Sai matan suka bar kabarin da hanzari, da tsoro, sai dai cike da farin ciki, suka tafi a guje don su gaya wa almajiransa. ");
INSERT INTO hausa_vpl VALUES ("MT28_9","070_28_9","MAT","28","9","9","Kwaram, sai ga Yesu ya gamu da su ya ce, “Gaisuwa.” Sai suka zo kusa da shi, suka rungumi ƙafafunsa, suka yi masa sujada. ");
INSERT INTO hausa_vpl VALUES ("MT28_10","070_28_10","MAT","28","10","10","Sai Yesu ya ce musu, “Kada ku ji tsoro, ku tafi ku gaya wa ’yan’uwana, su tafi Galili. A can za su gan ni.” ");
INSERT INTO hausa_vpl VALUES ("MT28_11","070_28_11","MAT","28","11","11","Yayinda matan nan suna cikin tafiya, sai waɗansu daga cikin masu gadin suka shiga gari, suka ba wa manyan firistoci labarin duk abin da ya faru. ");
INSERT INTO hausa_vpl VALUES ("MT28_12","070_28_12","MAT","28","12","12","Da manyan firistoci da dattawa suka taru, sai suka ƙulla wata dabara, suka ba wa sojojin kuɗi mai yawa. ");
INSERT INTO hausa_vpl VALUES ("MT28_13","070_28_13","MAT","28","13","13","Suka ce musu, “Ku, za ku ce, ‘Almajiransa ne sun zo da dare suka sace shi, lokacin da muke barci.’ ");
INSERT INTO hausa_vpl VALUES ("MT28_14","070_28_14","MAT","28","14","14","In wannan labari ya kai kunnen gwamna, za mu lallashe shi, mu kuma kāre ku daga duk wata wahala.” ");
INSERT INTO hausa_vpl VALUES ("MT28_15","070_28_15","MAT","28","15","15","Sai sojojin suka karɓi kuɗin, suka kuma yi kamar yadda aka umarce su. Wannan labarin kuwa shi ne ake bazawa ko’ina a cikin Yahudawa, har yă zuwa yau. ");
INSERT INTO hausa_vpl VALUES ("MT28_16","070_28_16","MAT","28","16","16","Sa’an nan almajiransa goma sha ɗaya, suka tafi Galili, suka je dutsen da Yesu ya gaya musu. ");
INSERT INTO hausa_vpl VALUES ("MT28_17","070_28_17","MAT","28","17","17","Da suka gan shi, sai suka yi masa sujada, amma waɗansu suka yi shakka. ");
INSERT INTO hausa_vpl VALUES ("MT28_18","070_28_18","MAT","28","18","18","Sai Yesu ya zo wurinsu ya ce, “An ba ni dukan iko a sama da kuma ƙasa. ");
INSERT INTO hausa_vpl VALUES ("MT28_19","070_28_19","MAT","28","19","19","Saboda haka ku tafi, ku mai da dukan al’umman duniya su zama almajiraina, kuna yi musu baftisma a cikinsunan Uba, da na Ɗa, da na Ruhu Mai Tsarki, ");
INSERT INTO hausa_vpl VALUES ("MT28_20","070_28_20","MAT","28","20","20","kuna kuma koya musu, su yi biyayya da duk abin da na umarce ku, kuma tabbatacce, ina tare da ku kullum, har ƙarshen zamani.”");
INSERT INTO hausa_vpl VALUES ("MK1_1","071_1_1","MRK","1","1","1","Farkon bishara game da Yesu Kiristi, Ɗan Allah. ");
INSERT INTO hausa_vpl VALUES ("MK1_2","071_1_2","MRK","1","2","2","An rubuta a cikin littafin annabi Ishaya cewa, “Zan aika da ɗan aikena yă sha gabanka, wanda zai shirya hanyarka,” ");
INSERT INTO hausa_vpl VALUES ("MK1_3","071_1_3","MRK","1","3","3","“muryar mai kira a hamada tana cewa, ‘Ku shirya wa Ubangiji hanya, ku miƙe hanyoyi dominsa.’ ” ");
INSERT INTO hausa_vpl VALUES ("MK1_4","071_1_4","MRK","1","4","4","Ta haka Yohanna ya zo, yana baftisma a yankin hamada, yana kuma wa’azin baftismar tuba don gafarar zunubai. ");
INSERT INTO hausa_vpl VALUES ("MK1_5","071_1_5","MRK","1","5","5","Dukan ƙauyukan Yahudiya da dukan mutanen Urushalima suka fiffito zuwa wurinsa. Suna furta zunubansu, ya kuwa yi musu baftisma a Kogin Urdun. ");
INSERT INTO hausa_vpl VALUES ("MK1_6","071_1_6","MRK","1","6","6","Yohanna ya sa tufafin gashin raƙumi, ya kuma yi ɗamara da fata. Abincinsa fāri ne da kuma zumar jeji. ");
INSERT INTO hausa_vpl VALUES ("MK1_7","071_1_7","MRK","1","7","7","Wannan kuwa shi ne saƙonsa, “A bayana, wanda ya fi ni iko yana zuwa, ban kuwa isa in sunkuya in kunce igiyar takalmansa ba. ");
INSERT INTO hausa_vpl VALUES ("MK1_8","071_1_8","MRK","1","8","8","Ina muku baftisma da ruwa, amma shi zai yi muku baftisma da Ruhu Mai Tsarki.” ");
INSERT INTO hausa_vpl VALUES ("MK1_9","071_1_9","MRK","1","9","9","A lokacin, Yesu ya zo daga Nazaret na Galili, Yohanna kuwa ya yi masa baftisma a Urdun. ");
INSERT INTO hausa_vpl VALUES ("MK1_10","071_1_10","MRK","1","10","10","Da Yesu yana fitowa daga ruwan, sai ya ga sama ya buɗe, Ruhu kuma yana saukowa a kansa kamar kurciya. ");
INSERT INTO hausa_vpl VALUES ("MK1_11","071_1_11","MRK","1","11","11","Sai murya ta fito daga sama ta ce, “Kai ne Ɗana, wanda nake ƙauna, da kai kuma nake fari ciki ƙwarai.” ");
INSERT INTO hausa_vpl VALUES ("MK1_12","071_1_12","MRK","1","12","12","Nan da nan, sai Ruhu ya kai shi cikin hamada, ");
INSERT INTO hausa_vpl VALUES ("MK1_13","071_1_13","MRK","1","13","13","ya kuma kasance a hamada kwana arba’in, Shaiɗan yana gwada shi. Yana tare da namomin jeji, mala’iku kuma suka yi masa hidima. ");
INSERT INTO hausa_vpl VALUES ("MK1_14","071_1_14","MRK","1","14","14","Bayan da aka sa Yohanna a kurkuku, sai Yesu ya shigo cikin Galili, yana shelar bisharar Allah. ");
INSERT INTO hausa_vpl VALUES ("MK1_15","071_1_15","MRK","1","15","15","Yana cewa, “Lokaci ya yi. Mulkin Allah ya yi kusa. Ku tuba, ku gaskata bishara!” ");
INSERT INTO hausa_vpl VALUES ("MK1_16","071_1_16","MRK","1","16","16","Yayinda Yesu yake tafiya a gaɓar Tekun Galili, sai ya ga Siman da ɗan’uwansa Andarawus, suna jefa abin kamun kifi a cikin tafkin, domin su masunta ne. ");
INSERT INTO hausa_vpl VALUES ("MK1_17","071_1_17","MRK","1","17","17","Yesu ya ce, “Ku zo, ku bi ni, ni kuwa zan mai da ku masuntan mutane.” ");
INSERT INTO hausa_vpl VALUES ("MK1_18","071_1_18","MRK","1","18","18","Nan da nan, suka bar abin kamun kifinsu, suka bi shi. ");
INSERT INTO hausa_vpl VALUES ("MK1_19","071_1_19","MRK","1","19","19","Da ya yi gaba kaɗan, sai ya ga Yaƙub ɗan Zebedi, da ɗan’uwansa Yohanna a cikin jirgin ruwa, suna gyaran abin kamun kifinsu. ");
INSERT INTO hausa_vpl VALUES ("MK1_20","071_1_20","MRK","1","20","20","Ba da ɓata lokaci ba, ya kira su, sai suka bar mahaifinsu Zebedi a cikin jirgin ruwan, tare da ’yan haya, suka kuwa bi shi. ");
INSERT INTO hausa_vpl VALUES ("MK1_21","071_1_21","MRK","1","21","21","Suka tafi Kafarnahum. Da ranar Asabbaci ta kewayo, sai Yesu ya shiga majami’a ya fara koyarwa. ");
INSERT INTO hausa_vpl VALUES ("MK1_22","071_1_22","MRK","1","22","22","Mutane suka yi mamakin koyarwarsa, domin ya koyar da su kamar wanda yake da iko, ba kamar malaman dokoki ba. ");
INSERT INTO hausa_vpl VALUES ("MK1_23","071_1_23","MRK","1","23","23","Nan take, sai wani mutum mai mugun ruhu a majami’arsu, ya ɗaga murya ya ce, ");
INSERT INTO hausa_vpl VALUES ("MK1_24","071_1_24","MRK","1","24","24","“Ina ruwanka da mu, Yesu Banazare? Ka zo ne don ka hallaka mu? Na san wane ne kai, Mai Tsarki nan na Allah!” ");
INSERT INTO hausa_vpl VALUES ("MK1_25","071_1_25","MRK","1","25","25","Yesu ya tsawata masa ya ce, “Yi shiru! Fita daga cikinsa!” ");
INSERT INTO hausa_vpl VALUES ("MK1_26","071_1_26","MRK","1","26","26","Sai mugun ruhun ya jijjiga mutumin da ƙarfi, ya fita daga jikinsa da ihu. ");
INSERT INTO hausa_vpl VALUES ("MK1_27","071_1_27","MRK","1","27","27","Dukan mutane suka yi mamaki, suna tambayar juna suna cewa, “Mene ne haka? Tabɗi! Yau ga sabuwar koyarwa kuma da iko! Yana ma ba wa mugayen ruhohi umarni, suna kuma yin masa biyayya.” ");
INSERT INTO hausa_vpl VALUES ("MK1_28","071_1_28","MRK","1","28","28","Labari game da shi ya bazu nan da nan ko’ina a dukan yankin Galili. ");
INSERT INTO hausa_vpl VALUES ("MK1_29","071_1_29","MRK","1","29","29","Da suka bar majami’ar, sai suka tafi gidan su Siman da Andarawus, tare da Yaƙub da Yohanna. ");
INSERT INTO hausa_vpl VALUES ("MK1_30","071_1_30","MRK","1","30","30","Surukar Siman tana kwance da zazzaɓi, sai suka gaya wa Yesu game da ita. ");
INSERT INTO hausa_vpl VALUES ("MK1_31","071_1_31","MRK","1","31","31","Sai ya je wajenta, ya kama hannunta, ya ɗaga ta. Zazzaɓin kuwa ya sāke ta, ta kuma yi musu hidima. ");
INSERT INTO hausa_vpl VALUES ("MK1_32","071_1_32","MRK","1","32","32","A wannan yamma, bayan fāɗuwar rana, mutane suka kawo wa Yesu dukan marasa lafiya, da masu aljanu. ");
INSERT INTO hausa_vpl VALUES ("MK1_33","071_1_33","MRK","1","33","33","Duk garin ya taru a ƙofar gidan. ");
INSERT INTO hausa_vpl VALUES ("MK1_34","071_1_34","MRK","1","34","34","Yesu kuwa ya warkar da marasa lafiya da yawa da suke da cututtuka iri-iri. Ya kuma fitar da aljanu da yawa, amma bai yarda aljanun suka yi magana ba, don sun san wane ne shi. ");
INSERT INTO hausa_vpl VALUES ("MK1_35","071_1_35","MRK","1","35","35","Da sassafe, tun da sauran duhu, Yesu ya tashi, ya bar gida, ya tafi wani wurin da ba kowa, a can ya yi addu’a. ");
INSERT INTO hausa_vpl VALUES ("MK1_36","071_1_36","MRK","1","36","36","Siman da abokansa suka fita nemansa. ");
INSERT INTO hausa_vpl VALUES ("MK1_37","071_1_37","MRK","1","37","37","Da suka same shi, sai suka ce, “Kowa yana nemanka!” ");
INSERT INTO hausa_vpl VALUES ("MK1_38","071_1_38","MRK","1","38","38","Yesu ya amsa ya ce, “Mu je wani wuri dabam, zuwa ƙauyukan da suke kusa, don in yi wa’azi a can ma. Wannan shi ne dalilin zuwana.” ");
INSERT INTO hausa_vpl VALUES ("MK1_39","071_1_39","MRK","1","39","39","Sai ya tafi ko’ina a Galili, yana wa’azi a majami’unsu, yana kuma fitar da aljanu. ");
INSERT INTO hausa_vpl VALUES ("MK1_40","071_1_40","MRK","1","40","40","Wani mutum mai kuturta ya zo wurinsa, ya durƙusa ya roƙe shi ya ce, “In kana so, za ka iya tsabtacce ni.” ");
INSERT INTO hausa_vpl VALUES ("MK1_41","071_1_41","MRK","1","41","41","Cike da tausayi, sai Yesu ya miƙa hannunsa ya taɓa mutumin ya ce, “Na yarda, ka tsabtacce!” ");
INSERT INTO hausa_vpl VALUES ("MK1_42","071_1_42","MRK","1","42","42","Nan da nan, sai kuturtar ta rabu da shi, ya kuma warke. ");
INSERT INTO hausa_vpl VALUES ("MK1_43","071_1_43","MRK","1","43","43","Yesu ya sallame shi nan take, da gargaɗi mai ƙarfi cewa, ");
INSERT INTO hausa_vpl VALUES ("MK1_44","071_1_44","MRK","1","44","44","“Ka lura kada ka gaya wa kowa wannan. Amma ka tafi ka nuna kanka ga firist, ka kuma miƙa hadayun da Musa ya umarta saboda tsarkakewarka, don yă zama shaida gare su.” ");
INSERT INTO hausa_vpl VALUES ("MK1_45","071_1_45","MRK","1","45","45","A maimakon haka, sai ya fita, ya fara magana a sake, yana baza labarin. Saboda haka, Yesu bai ƙara iya shiga cikin gari a fili ba, sai dai ya kasance a wuraren da ba kowa. Duk da haka, mutane suka yi ta zuwa wurinsa daga ko’ina. ");
INSERT INTO hausa_vpl VALUES ("MK2_1","071_2_1","MRK","2","1","1","Bayan ’yan kwanaki, da Yesu ya sāke shiga Kafarnahum, sai mutane suka ji labarin zuwansa gida. ");
INSERT INTO hausa_vpl VALUES ("MK2_2","071_2_2","MRK","2","2","2","Mutane suka taru da yawa har ma babu wuri, ko a bakin ƙofa ma, sai ya yi musu wa’azin bishara. ");
INSERT INTO hausa_vpl VALUES ("MK2_3","071_2_3","MRK","2","3","3","Waɗansu mutum huɗu suka zo wajensa ɗauke da wani shanyayye. ");
INSERT INTO hausa_vpl VALUES ("MK2_4","071_2_4","MRK","2","4","4","Da ba su iya kai shi wurin Yesu ba, saboda taron, sai suka buɗe rufin gidan saman, bisa daidai inda Yesu yake. Bayan da suka huda rami, sai suka saukar da shanyayyen, kwance a kan tabarmarsa. ");
INSERT INTO hausa_vpl VALUES ("MK2_5","071_2_5","MRK","2","5","5","Da Yesu ya ga bangaskiyarsu, sai ya ce wa shanyayyen, “Saurayi, an gafarta zunubanka.” ");
INSERT INTO hausa_vpl VALUES ("MK2_6","071_2_6","MRK","2","6","6","To, waɗansu malaman dokoki da suke zaune a wurin, suka yi tunani a zuciyarsu, suna cewa, ");
INSERT INTO hausa_vpl VALUES ("MK2_7","071_2_7","MRK","2","7","7","“Me ya sa mutumin nan yake magana haka? Yana saɓo! Wane ne zai iya gafarta zunubai, in ba Allah kaɗai ba?” ");
INSERT INTO hausa_vpl VALUES ("MK2_8","071_2_8","MRK","2","8","8","Nan da nan, Yesu ya gane a ruhunsa abin da suke tunani a zuciyarsu, sai ya ce musu, “Me ya sa kuke tunanin waɗannan abubuwa? ");
INSERT INTO hausa_vpl VALUES ("MK2_9","071_2_9","MRK","2","9","9","Wanne ya fi sauƙi, a ce wa shanyayyen, ‘An gafarta zunubanka,’ ko a ce, ‘Tashi, ɗauki tabarmarka ka yi tafiya’? ");
INSERT INTO hausa_vpl VALUES ("MK2_10","071_2_10","MRK","2","10","10","Amma don ku san cewa, Ɗan Mutum yana da iko a duniya yă gafarta zunubai.” Sai ya ce wa shanyayyen, ");
INSERT INTO hausa_vpl VALUES ("MK2_11","071_2_11","MRK","2","11","11","“Ina ce maka, tashi, ɗauki tabarmarka, ka tafi gida.” ");
INSERT INTO hausa_vpl VALUES ("MK2_12","071_2_12","MRK","2","12","12","Sai ya tashi, ya ɗauki tabarmarsa, ya yi tafiyarsa a gabansu duka. Wannan ya ba wa kowa mamaki, suka kuma ɗaukaka Allah suna cewa, “Ba mu taɓa ganin abu haka ba!” ");
INSERT INTO hausa_vpl VALUES ("MK2_13","071_2_13","MRK","2","13","13","Yesu ya sāke tafiya bakin tafkin. Taro mai yawa ya zo wurinsa, sai ya fara koya musu. ");
INSERT INTO hausa_vpl VALUES ("MK2_14","071_2_14","MRK","2","14","14","Yana cikin tafiya, sai ya ga Lawi, ɗan Alfayus zaune a inda ake karɓar haraji. Yesu ya ce masa, “Bi ni.” Sai Lawi ya tashi, ya bi shi. ");
INSERT INTO hausa_vpl VALUES ("MK2_15","071_2_15","MRK","2","15","15","Yayinda Yesu yake cin abinci a gidan Lawi, sai masu karɓar haraji da “masu zunubi” da yawa, suka zo suka ci tare da shi da almajiransa, gama akwai mutane da yawa da suka bi shi. ");
INSERT INTO hausa_vpl VALUES ("MK2_16","071_2_16","MRK","2","16","16","Da malaman dokoki, waɗanda su ma Farisiyawa ne, suka ga yana ci tare da masu “zunubi” da masu karɓar haraji, sai suka tambayi almajiransa, suka ce, “Me ya sa yake ci tare da masu karɓar haraji da masu zunubi?” ");
INSERT INTO hausa_vpl VALUES ("MK2_17","071_2_17","MRK","2","17","17","Da jin wannan, Yesu ya ce musu, “Ai, masu lafiya ba sa bukatar likita, sai dai marasa lafiya. Ban zo domin in kira masu adalci ba, sai dai masu zunubi.” ");
INSERT INTO hausa_vpl VALUES ("MK2_18","071_2_18","MRK","2","18","18","To, almajiran Yohanna da na Farisiyawa suna azumi, sai waɗansu mutane suka zo suka tambayi Yesu, suka ce, “Yaya almajiran Yohanna da na Farisiyawa suna azumi, amma almajiranka ba sa yi?” ");
INSERT INTO hausa_vpl VALUES ("MK2_19","071_2_19","MRK","2","19","19","Yesu ya amsa ya ce, “Yaya abokan ango za su yi azumi, sa’ad da yana tare da su? Ai, ba za su yi ba, muddin yana tare da su. ");
INSERT INTO hausa_vpl VALUES ("MK2_20","071_2_20","MRK","2","20","20","Ai, lokaci yana zuwa da za a ɗauke musu angon. A sa’an nan ne fa za su yi azumi. ");
INSERT INTO hausa_vpl VALUES ("MK2_21","071_2_21","MRK","2","21","21","“Ba mai facin sabon ƙyalle a tsohuwar riga. In ya yi haka, sabon ƙyallen zai yage daga tsohuwar, yagewar kuwa za tă zama da muni. ");
INSERT INTO hausa_vpl VALUES ("MK2_22","071_2_22","MRK","2","22","22","Ba wanda yakan zuba sabon ruwan inabi a tsofaffin salkuna. In ya yi haka, ruwan inabin zai farfashe salkunan, yă yi hasarar ruwan inabin, salkunan kuma su lalace. A’a, yakan zuba sabon ruwan inabin a sababbin salkuna.” ");
INSERT INTO hausa_vpl VALUES ("MK2_23","071_2_23","MRK","2","23","23","Wata ranar Asabbaci, Yesu yana ratsa gonakin hatsi, sai almajiransa da suke tafiya tare da shi, suka fara kakkarya waɗansu kan hatsi. ");
INSERT INTO hausa_vpl VALUES ("MK2_24","071_2_24","MRK","2","24","24","Farisiyawa suka ce masa, “Duba, me ya sa suke yin abin da doka ta hana a yi, a ranar Asabbaci?” ");
INSERT INTO hausa_vpl VALUES ("MK2_25","071_2_25","MRK","2","25","25","Ya amsa ya ce, “Ashe, ba ku taɓa karanta abin da Dawuda ya yi ba, sa’ad da shi da abokan tafiyarsa suka ji yunwa, suna kuma cikin bukata? ");
INSERT INTO hausa_vpl VALUES ("MK2_26","071_2_26","MRK","2","26","26","Ya shiga gidan Allah a zamanin Abiyatar babban firist, ya ci keɓaɓɓen burodin nan, ya kuma ba wa abokan tafiyarsa abin da firistoci kaɗai sukan ci bisa ga doka?” ");
INSERT INTO hausa_vpl VALUES ("MK2_27","071_2_27","MRK","2","27","27","Sai ya ce musu, “An yi Asabbaci saboda mutum ne, ba mutum saboda Asabbaci ba. ");
INSERT INTO hausa_vpl VALUES ("MK2_28","071_2_28","MRK","2","28","28","Don haka, Ɗan Mutum Ubangiji ne, har ma da na Asabbaci.” ");
INSERT INTO hausa_vpl VALUES ("MK3_1","071_3_1","MRK","3","1","1","Wani lokaci, da ya sāke shiga majami’a, sai ga wani mutum mai shanyayyen hannu. ");
INSERT INTO hausa_vpl VALUES ("MK3_2","071_3_2","MRK","3","2","2","Waɗansu daga cikin mutane suna neman dalilin zargin Yesu, sai suka zuba masa ido, su ga ko zai warkar da shi a ranar Asabbaci. ");
INSERT INTO hausa_vpl VALUES ("MK3_3","071_3_3","MRK","3","3","3","Yesu ya ce wa mutumin mai shanyayyen hannun, “Tashi ka tsaya a gaban kowa.” ");
INSERT INTO hausa_vpl VALUES ("MK3_4","071_3_4","MRK","3","4","4","Sai Yesu ya tambaye su ya ce, “Me ya kamata a yi bisa ga doka, a ranar Asabbaci, a aikata alheri, ko a aikata mugunta, a ceci rai, ko a yi kisa?” Amma suka yi shiru. ");
INSERT INTO hausa_vpl VALUES ("MK3_5","071_3_5","MRK","3","5","5","Sai ya kalle su da fushi, don taurin zuciyarsu ya ɓata masa rai sosai. Sai ya ce wa mutumin, “Miƙo hannunka.” Sai ya miƙa, hannunsa kuwa ya koma lafiyayye. ");
INSERT INTO hausa_vpl VALUES ("MK3_6","071_3_6","MRK","3","6","6","Sai Farisiyawa suka fita, suka fara ƙulla shawara da mutanen Hiridus yadda za su kashe Yesu. ");
INSERT INTO hausa_vpl VALUES ("MK3_7","071_3_7","MRK","3","7","7","Yesu da almajiransa suka janye zuwa tafkin, taro mai yawa kuwa daga Galili ya bi shi. ");
INSERT INTO hausa_vpl VALUES ("MK3_8","071_3_8","MRK","3","8","8","Mutane da yawa daga Yahudiya, da Urushalima, da Edom, da kuma yankunan da suke ƙetaren Urdun, da kewayen Taya, da Sidon suka zo wurinsa, don sun ji dukan abubuwan da yake yi. ");
INSERT INTO hausa_vpl VALUES ("MK3_9","071_3_9","MRK","3","9","9","Saboda taron, sai ya ce wa almajiransa su shirya masa ƙaramin jirgin ruwa, don kada mutane su matse shi. ");
INSERT INTO hausa_vpl VALUES ("MK3_10","071_3_10","MRK","3","10","10","Gama ya warkar da mutane da yawa, masu cututtuka suka yi ta ƙoƙarin zuwa gaba, don su taɓa shi. ");
INSERT INTO hausa_vpl VALUES ("MK3_11","071_3_11","MRK","3","11","11","Duk sa’ad da mugayen ruhohi suka gan shi, sai fāɗi a gabansa, su ɗaga murya, su ce, “Kai Ɗan Allah ne.” ");
INSERT INTO hausa_vpl VALUES ("MK3_12","071_3_12","MRK","3","12","12","Amma yakan tsawata musu, kada su shaida ko wane ne shi. ");
INSERT INTO hausa_vpl VALUES ("MK3_13","071_3_13","MRK","3","13","13","Yesu ya hau gefen wani dutse, ya kira waɗanda yake so, suka kuma zo wurinsa. ");
INSERT INTO hausa_vpl VALUES ("MK3_14","071_3_14","MRK","3","14","14","Ya naɗa sha biyu, ya kira su manzanni don su kasance tare da shi, domin kuma yă aike su yin wa’azi, ");
INSERT INTO hausa_vpl VALUES ("MK3_15","071_3_15","MRK","3","15","15","don kuma su sami ikon fitar da aljanu. ");
INSERT INTO hausa_vpl VALUES ("MK3_16","071_3_16","MRK","3","16","16","Ga sha biyun da ya naɗa. Siman (wanda ya ba shi suna Bitrus); ");
INSERT INTO hausa_vpl VALUES ("MK3_17","071_3_17","MRK","3","17","17","Yaƙub ɗan Zebedi da kuma ɗan’uwansa Yohanna (ga waɗannan kuwa ya sa musu suna Buwarnajis, wato, “’ya’yan tsawa”); ");
INSERT INTO hausa_vpl VALUES ("MK3_18","071_3_18","MRK","3","18","18","Andarawus, Filibus, Bartolomeyu, Mattiyu, Toma, Yaƙub ɗan Alfayus, Taddayus, Siman wanda ake kira Zilot, ");
INSERT INTO hausa_vpl VALUES ("MK3_19","071_3_19","MRK","3","19","19","da kuma Yahuda Iskariyot, wanda ya bashe Yesu. ");
INSERT INTO hausa_vpl VALUES ("MK3_20","071_3_20","MRK","3","20","20","Sai Yesu ya shiga wani gida, taro kuma ya sāke haɗuwa, har shi da almajiransa ma ba su sami damar cin abinci ba. ");
INSERT INTO hausa_vpl VALUES ("MK3_21","071_3_21","MRK","3","21","21","Da ’yan’uwansa suka sami wannan labari, sai suka tafi don su dawo da shi, suna cewa, “Ai, ya haukace.” ");
INSERT INTO hausa_vpl VALUES ("MK3_22","071_3_22","MRK","3","22","22","Malaman dokokin da suka zo daga Urushalima suka ce, “Ai, yana da Be’elzebub! Da ikon sarkin aljanu yake fitar da aljanu.” ");
INSERT INTO hausa_vpl VALUES ("MK3_23","071_3_23","MRK","3","23","23","Sai Yesu ya kira su, ya yi musu magana da misalai ya ce, “Yaya Shaiɗan zai fitar da Shaiɗan? ");
INSERT INTO hausa_vpl VALUES ("MK3_24","071_3_24","MRK","3","24","24","In mulki yana gāba da kansa, wannan mulki ba zai tsaya ba. ");
INSERT INTO hausa_vpl VALUES ("MK3_25","071_3_25","MRK","3","25","25","In gida yana gāba da kansa, wannan gida ba zai tsaya ba. ");
INSERT INTO hausa_vpl VALUES ("MK3_26","071_3_26","MRK","3","26","26","In kuwa Shaiɗan yana gāba da kansa, ya kuma rabu biyu, ba zai tsaya ba, ƙarshensa ya zo ke nan. ");
INSERT INTO hausa_vpl VALUES ("MK3_27","071_3_27","MRK","3","27","27","Tabbatacce, ba mai shiga gidan mai ƙarfi yă kwashe dukiyarsa, sai bayan ya daure mai ƙarfin, sa’an nan zai iya yin fashin gidansa. ");
INSERT INTO hausa_vpl VALUES ("MK3_28","071_3_28","MRK","3","28","28","Gaskiya nake gaya muku, za a gafarta duk zunubai da kuma saɓon mutane suka yi. ");
INSERT INTO hausa_vpl VALUES ("MK3_29","071_3_29","MRK","3","29","29","Amma duk wanda ya saɓi Ruhu Mai Tsarki, ba za a taɓa gafara masa ba. Ya aikata madawwamin zunubi ke nan.” ");
INSERT INTO hausa_vpl VALUES ("MK3_30","071_3_30","MRK","3","30","30","Ya faɗi haka domin suna cewa, “Yana da mugun ruhu.” ");
INSERT INTO hausa_vpl VALUES ("MK3_31","071_3_31","MRK","3","31","31","Sai mahaifiyar Yesu tare da ’yan’uwansa suka iso. Suna tsaye a waje, sai suka aiki wani ciki yă kira shi. ");
INSERT INTO hausa_vpl VALUES ("MK3_32","071_3_32","MRK","3","32","32","Taron yana zaune kewaye da shi, sai suka ce masa, “Mahaifiyarka da ’yan’uwanka suna waje, suna nemanka.” ");
INSERT INTO hausa_vpl VALUES ("MK3_33","071_3_33","MRK","3","33","33","Ya yi tambaya ya ce, “Su wane ne mahaifiyata, da ’yan’uwana?” ");
INSERT INTO hausa_vpl VALUES ("MK3_34","071_3_34","MRK","3","34","34","Sai ya dubi waɗanda suke zaune kewaye da shi ya ce, “Ga mahaifiyata da ’yan’uwana! ");
INSERT INTO hausa_vpl VALUES ("MK3_35","071_3_35","MRK","3","35","35","Duk wanda yake aikata nufin Allah, shi ne ɗan’uwana, da ’yar’uwata, da kuma mahaifiyata.” ");
INSERT INTO hausa_vpl VALUES ("MK4_1","071_4_1","MRK","4","1","1","Har wa yau, Yesu ya fara koyarwa a bakin tafki. Domin taron da yake kewaye da shi mai girma ne sosai, sai ya shiga cikin jirgin ruwa, ya zauna a ciki a tafkin, dukan mutanen kuwa suna a gaɓar ruwan. ");
INSERT INTO hausa_vpl VALUES ("MK4_2","071_4_2","MRK","4","2","2","Ya koya musu abubuwa da yawa da misalai. A koyarwarsa kuwa ya ce, ");
INSERT INTO hausa_vpl VALUES ("MK4_3","071_4_3","MRK","4","3","3","“Ku saurara! Wani manomi ya fita don yă shuka irinsa. ");
INSERT INTO hausa_vpl VALUES ("MK4_4","071_4_4","MRK","4","4","4","Da yana yafa irin, sai waɗansu suka fāɗi a kan hanya, tsuntsaye suka zo suka cinye su. ");
INSERT INTO hausa_vpl VALUES ("MK4_5","071_4_5","MRK","4","5","5","Waɗansu suka fāɗi a wuri mai duwatsu inda babu ƙasa sosai. Nan da nan, suka tsira domin ƙasar ba zurfi. ");
INSERT INTO hausa_vpl VALUES ("MK4_6","071_4_6","MRK","4","6","6","Amma da rana ta taso, sai tsire-tsiren suka ƙone, suka yanƙwane, domin ba su da saiwa. ");
INSERT INTO hausa_vpl VALUES ("MK4_7","071_4_7","MRK","4","7","7","Waɗansu irin suka fāɗi a cikin ƙaya. Da suka yi girma sai ƙaya suka shaƙe su, har ya sa ba su yi ƙwaya ba. ");
INSERT INTO hausa_vpl VALUES ("MK4_8","071_4_8","MRK","4","8","8","Har yanzu, waɗansu irin suka fāɗi a ƙasa mai kyau. Suka tsira, suka yi girma, suka ba da amfani, suka yi riɓi talatin-talatin, waɗansu sittin-sittin, waɗansu kuma ɗari-ɗari.” ");
INSERT INTO hausa_vpl VALUES ("MK4_9","071_4_9","MRK","4","9","9","Sai Yesu ya ce, “Duk mai kunnen ji, yă ji.” ");
INSERT INTO hausa_vpl VALUES ("MK4_10","071_4_10","MRK","4","10","10","Lokacin da yake shi kaɗai, Sha Biyun, da kuma waɗanda suke kewaye da shi, suka tambaye shi game da misalan. ");
INSERT INTO hausa_vpl VALUES ("MK4_11","071_4_11","MRK","4","11","11","Sai ya ce musu, “An ba ku sanin asirin mulkin Allah. Amma ga waɗanda suke waje kuwa, kome sai da misalai. ");
INSERT INTO hausa_vpl VALUES ("MK4_12","071_4_12","MRK","4","12","12","Saboda, “ ‘ko sun dinga duba, ba za su taɓa gane ba, kuma ko su dinga ji, ba za su taɓa fahimta ba, in ba haka ba, mai yiwuwa, su tuba, a gafarta musu!’ ” ");
INSERT INTO hausa_vpl VALUES ("MK4_13","071_4_13","MRK","4","13","13","Sai Yesu ya ce musu, “Ba ku fahimci wannan misali ba? Yaya za ku fahimci wani misali ke nan? ");
INSERT INTO hausa_vpl VALUES ("MK4_14","071_4_14","MRK","4","14","14","Manomi yakan shuka maganar Allah. ");
INSERT INTO hausa_vpl VALUES ("MK4_15","071_4_15","MRK","4","15","15","Waɗansu mutane suna kama da irin da ya fāɗi a kan hanya, inda akan shuka maganar Allah. Da jin maganar, nan da nan sai Shaiɗan yă zo yă ɗauke maganar da aka shuka a zuciyarsu. ");
INSERT INTO hausa_vpl VALUES ("MK4_16","071_4_16","MRK","4","16","16","Waɗansu suna kama da irin da aka shuka a wurare masu duwatsu, sukan ji maganar Allah, sukan kuma karɓe ta nan da nan da farin ciki. ");
INSERT INTO hausa_vpl VALUES ("MK4_17","071_4_17","MRK","4","17","17","Amma da yake ba su da saiwa, ba sa daɗewa. Da wahala ko tsanani ya tashi saboda maganar, nan da nan, sai su ja da baya. ");
INSERT INTO hausa_vpl VALUES ("MK4_18","071_4_18","MRK","4","18","18","Har yanzu, waɗansu kamar irin da aka shuka cikin ƙaya, sukan ji maganar, ");
INSERT INTO hausa_vpl VALUES ("MK4_19","071_4_19","MRK","4","19","19","amma damuwar wannan duniya, da son dukiya, da kuma kwaɗayin waɗansu abubuwa, sukan shiga, su shaƙe maganar, har su mai da ita marar amfani. ");
INSERT INTO hausa_vpl VALUES ("MK4_20","071_4_20","MRK","4","20","20","Waɗansu mutane kuwa suna kama da irin da aka shuka a ƙasa mai kyau, sukan ji maganar Allah, su kuma karɓa, sa’an nan kuma su fid da amfani riɓi talatin-talatin, ko sittin-sittin, ko ɗari-ɗari.” ");
INSERT INTO hausa_vpl VALUES ("MK4_21","071_4_21","MRK","4","21","21","Sai ya ce musu, “Ko kukan kawo fitila ku rufe ta da murfi ko kuma ku sa ta a ƙarƙashin gado ne? Ba kukan sa ta a kan wurin ajiye fitila ba? ");
INSERT INTO hausa_vpl VALUES ("MK4_22","071_4_22","MRK","4","22","22","Duk abin da yake a ɓoye, dole za a fallasa shi. Duk abin da kuma yake a rufe, dole za a fitar da shi a fili. ");
INSERT INTO hausa_vpl VALUES ("MK4_23","071_4_23","MRK","4","23","23","Duk mai kunnen ji, bari yă ji.” ");
INSERT INTO hausa_vpl VALUES ("MK4_24","071_4_24","MRK","4","24","24","Ya ci gaba da cewa, “Ku lura da abin da kuke ji da kyau. Mudun da ka auna da shi, da shi za a auna maka, har ma a ƙara. ");
INSERT INTO hausa_vpl VALUES ("MK4_25","071_4_25","MRK","4","25","25","Duk wanda yake da shi, za a ƙara masa, duk wanda kuma ba shi da shi, ko abin da yake da shi ma, za a karɓe daga gare shi.” ");
INSERT INTO hausa_vpl VALUES ("MK4_26","071_4_26","MRK","4","26","26","Ya sāke cewa, “Mulkin Allah yana kama da haka. Wani mutum ya yafa iri a gona. ");
INSERT INTO hausa_vpl VALUES ("MK4_27","071_4_27","MRK","4","27","27","A kwana a tashi har irin yă tsiro, yă yi girma, bai kuwa santa yadda aka yi ba. ");
INSERT INTO hausa_vpl VALUES ("MK4_28","071_4_28","MRK","4","28","28","Ƙasar da kanta takan ba da ƙwaya, da farko takan fid da ƙara, sa’an nan ta fid da kai, sa’an nan kan yă fid da ƙwaya. ");
INSERT INTO hausa_vpl VALUES ("MK4_29","071_4_29","MRK","4","29","29","Da ƙwayan ya nuna, sai yă sa lauje yă yanka, domin lokacin girbi ya yi.” ");
INSERT INTO hausa_vpl VALUES ("MK4_30","071_4_30","MRK","4","30","30","Ya kuma ce, “Da me za mu kwatanta mulkin Allah, ko kuwa da wane misali za mu bayyana shi? ");
INSERT INTO hausa_vpl VALUES ("MK4_31","071_4_31","MRK","4","31","31","Yana kama da ƙwayar mustad, wadda ita ce ƙwaya mafi ƙanƙanta da akan shuka a gona. ");
INSERT INTO hausa_vpl VALUES ("MK4_32","071_4_32","MRK","4","32","32","Duk da haka, in aka shuka ƙwayar, sai tă yi girma, tă zama mafi girma a itatuwan lambu. Har itacen yă kasance da manyan rassa, inda tsuntsayen sararin sama sukan iya huta a inuwarsa.” ");
INSERT INTO hausa_vpl VALUES ("MK4_33","071_4_33","MRK","4","33","33","Da misalai da yawa irin waɗannan, Yesu ya yi magana da su, daidai yadda za su iya fahimta. ");
INSERT INTO hausa_vpl VALUES ("MK4_34","071_4_34","MRK","4","34","34","Ba abin da ya faɗa musu, da ba da misali ba. Amma lokacin da yake shi kaɗai tare da almajiransa, sai yă bayyana kome. ");
INSERT INTO hausa_vpl VALUES ("MK4_35","071_4_35","MRK","4","35","35","A wannan rana, da yamma, sai ya ce wa almajiransa, “Mu ƙetare zuwa wancan hayi.” ");
INSERT INTO hausa_vpl VALUES ("MK4_36","071_4_36","MRK","4","36","36","Da suka bar taron, sai suka tafi tare da shi yadda yake, a cikin jirgin ruwa. Akwai waɗansu jiragen ruwa kuma tare da shi. ");
INSERT INTO hausa_vpl VALUES ("MK4_37","071_4_37","MRK","4","37","37","Sai babban hadari mai iska ya tashi, raƙuman ruwa suna ta bugun jirgin ruwan, har jirgin ruwan ya kusa yă cika da ruwa. ");
INSERT INTO hausa_vpl VALUES ("MK4_38","071_4_38","MRK","4","38","38","Yesu kuwa yana can baya, yana barci a kan katifa. Sai almajiran suka tashe shi suka ce masa, “Malam, ba ka kula ba ko mu nutse?” ");
INSERT INTO hausa_vpl VALUES ("MK4_39","071_4_39","MRK","4","39","39","Sai ya farka ya tsawata wa iskar, ya ce wa raƙuman ruwan, “Shiru! Ku natsu!” Sai iskar ta kwanta, kome kuma ya yi tsit. ");
INSERT INTO hausa_vpl VALUES ("MK4_40","071_4_40","MRK","4","40","40","Sai ya ce wa almajiransa, “Don me kuke tsoro haka? Har yanzu ba ku da bangaskiya ne?” ");
INSERT INTO hausa_vpl VALUES ("MK4_41","071_4_41","MRK","4","41","41","Suka tsorata, suka ce wa juna, “Wane ne wannan? Har iska da raƙuman ruwa ma suna masa biyayya!” ");
INSERT INTO hausa_vpl VALUES ("MK5_1","071_5_1","MRK","5","1","1","Suka ƙetare tafkin suka je yankin Gerasenawa. ");
INSERT INTO hausa_vpl VALUES ("MK5_2","071_5_2","MRK","5","2","2","Da Yesu ya sauka daga jirgin ruwa, sai wani mutum mai mugun ruhu ya fito daga kaburbura, ya tarye shi. ");
INSERT INTO hausa_vpl VALUES ("MK5_3","071_5_3","MRK","5","3","3","Wannan mutumin ya mai da kaburbura gidansa. Kuma ba wanda ya iya daure shi, ko da sarƙa ma. ");
INSERT INTO hausa_vpl VALUES ("MK5_4","071_5_4","MRK","5","4","4","Gama an sha daure shi hannu da ƙafa da sarƙa, amma yakan tsintsinke sarƙar, yă kuma karye ƙarafan da suke ƙafafunsa. Ba wanda yake da ƙarfin da zai iya yă riƙe shi. ");
INSERT INTO hausa_vpl VALUES ("MK5_5","071_5_5","MRK","5","5","5","Dare da rana, sai yă dinga kuka yana ƙuƙƙuje jikinsa da duwatsu a cikin kaburbura da kan tuddai. ");
INSERT INTO hausa_vpl VALUES ("MK5_6","071_5_6","MRK","5","6","6","Da ya hangi Yesu daga nesa, sai ya ruga da gudu, ya zo ya durƙusa a gabansa. ");
INSERT INTO hausa_vpl VALUES ("MK5_7","071_5_7","MRK","5","7","7","Ya yi ihu da babbar murya ya ce, “Ina ruwanka da ni Yesu, Ɗan Allah Mafi Ɗaukaka? Ka rantse da Allah cewa ba za ka ba ni azaba ba!” ");
INSERT INTO hausa_vpl VALUES ("MK5_8","071_5_8","MRK","5","8","8","Gama Yesu ya riga ya ce masa, “Ka fita daga jikin mutumin nan, kai mugun ruhu!” ");
INSERT INTO hausa_vpl VALUES ("MK5_9","071_5_9","MRK","5","9","9","Sai Yesu ya tambaye shi ya ce, “Mene ne sunanka?” Sai ya amsa ya ce, “Sunana Lejiyon, wato, ‘Tuli,’ domin muna da yawa.” ");
INSERT INTO hausa_vpl VALUES ("MK5_10","071_5_10","MRK","5","10","10","Sai ya yi ta roƙon Yesu, kada yă kore su daga wurin. ");
INSERT INTO hausa_vpl VALUES ("MK5_11","071_5_11","MRK","5","11","11","A kan tudun da yake nan kusa kuwa, akwai wani babban garken aladu, suna kiwo. ");
INSERT INTO hausa_vpl VALUES ("MK5_12","071_5_12","MRK","5","12","12","Sai aljanun suka roƙi Yesu, suka ce, “Tura mu cikin aladun nan, ka bari mu shiga cikinsu.” ");
INSERT INTO hausa_vpl VALUES ("MK5_13","071_5_13","MRK","5","13","13","Ya kuwa yarda musu, sai mugayen ruhohin suka fita suka shiga cikin aladun. Garken kuwa, yana da kusan aladu dubu biyu, suka gangara daga kan tudun zuwa cikin tafkin, suka nutse. ");
INSERT INTO hausa_vpl VALUES ("MK5_14","071_5_14","MRK","5","14","14","Masu kiwon aladun kuwa suka ruga da gudu zuwa cikin gari da ƙauyuka, suka ba da wannan labari. Sai mutanen suka fito, domin su ga abin da ya faru. ");
INSERT INTO hausa_vpl VALUES ("MK5_15","071_5_15","MRK","5","15","15","Da suka kai wajen Yesu, sai suka ga mutumin da dā yake da tulin aljanun yana zaune a wurin, sanye da tufafi kuma cikin hankalinsa, sai suka ji tsoro. ");
INSERT INTO hausa_vpl VALUES ("MK5_16","071_5_16","MRK","5","16","16","Waɗanda suka ga abin da ya faru, suka ba da labarin abin da ya faru da mai aljanun, da kuma aladun. ");
INSERT INTO hausa_vpl VALUES ("MK5_17","071_5_17","MRK","5","17","17","Sai mutane suka fara roƙon Yesu yă bar yankinsu. ");
INSERT INTO hausa_vpl VALUES ("MK5_18","071_5_18","MRK","5","18","18","Yesu yana kan shiga cikin jirgin ruwa ke nan, sai mutumin da dā yake da aljanun ya roƙa yă bi shi. ");
INSERT INTO hausa_vpl VALUES ("MK5_19","071_5_19","MRK","5","19","19","Yesu bai yardar masa ba, amma ya ce, “Ka tafi gida wurin iyalinka, ka gaya musu babban alherin da Ubangiji ya yi maka, da yadda ya yi maka jinƙai.” ");
INSERT INTO hausa_vpl VALUES ("MK5_20","071_5_20","MRK","5","20","20","Sai mutumin ya tafi, ya yi ta ba da labari a cikin Dekafolis a kan babban alherin da Yesu ya yi masa. Dukan mutane kuwa suka yi mamaki. ");
INSERT INTO hausa_vpl VALUES ("MK5_21","071_5_21","MRK","5","21","21","Da Yesu ya sāke ƙetarewa cikin jirgin ruwa zuwa ɗaya hayen tafkin, sai taro mai yawa ya taru kewaye da shi yayinda yake a bakin tafkin. ");
INSERT INTO hausa_vpl VALUES ("MK5_22","071_5_22","MRK","5","22","22","Sai ɗaya a cikin masu mulkin majami’a, wanda ake kira Yayirus ya zo wurin. Da ganin Yesu, sai ya durƙusa a gabansa, ");
INSERT INTO hausa_vpl VALUES ("MK5_23","071_5_23","MRK","5","23","23","ya roƙe shi da gaske ya ce, “Ƙaramar diyata tana bakin mutuwa. In ka yarda, ka zo ka ɗibiya hannunka a kanta, domin ta warke, ta kuma rayu.” ");
INSERT INTO hausa_vpl VALUES ("MK5_24","071_5_24","MRK","5","24","24","Sai Yesu ya tafi tare da shi. Babban taron kuma ya bi shi, suna ta matsinsa a kowane gefe. ");
INSERT INTO hausa_vpl VALUES ("MK5_25","071_5_25","MRK","5","25","25","A can kuwa akwai wata mace, wadda ta yi shekaru goma sha biyu tana zub da jini. ");
INSERT INTO hausa_vpl VALUES ("MK5_26","071_5_26","MRK","5","26","26","Ta kuma sha wahala ƙwarai a hannun likitoci da yawa, har ta kashe duk abin da take da shi, amma maimakon samun sauƙi, sai ciwon ya ƙara muni. ");
INSERT INTO hausa_vpl VALUES ("MK5_27","071_5_27","MRK","5","27","27","Da ta ji labarin Yesu, sai ta zo ta bayansa, a cikin taron, ta taɓa rigarsa, ");
INSERT INTO hausa_vpl VALUES ("MK5_28","071_5_28","MRK","5","28","28","domin ta yi tunani cewa, “Ko da rigunarsa ma na taɓa, zan warke.” ");
INSERT INTO hausa_vpl VALUES ("MK5_29","071_5_29","MRK","5","29","29","Nan da take, zub da jininta ya tsaya, sai ta ji a jikinta ta rabu da shan wahalarta. ");
INSERT INTO hausa_vpl VALUES ("MK5_30","071_5_30","MRK","5","30","30","Nan da nan Yesu ya gane cewa, iko ya fita daga gare shi. Sai ya juya a cikin taron ya yi tambaya, “Wa ya taɓa rigata?” ");
INSERT INTO hausa_vpl VALUES ("MK5_31","071_5_31","MRK","5","31","31","Sai almajiransa suka ce, “Kana ganin mutane suna matsinka, duk da haka kana tambaya, ‘Wa ya taɓa ni?’ ” ");
INSERT INTO hausa_vpl VALUES ("MK5_32","071_5_32","MRK","5","32","32","Amma Yesu ya ci gaba da dubawa don yă ga wa ya taɓa shi. ");
INSERT INTO hausa_vpl VALUES ("MK5_33","071_5_33","MRK","5","33","33","Matar, da yake ta san abin da ya faru da ita, sai ta zo ta durƙusa a gabansa, da tsoro da rawan jiki, ta kuma gaya masa dukan abin da ya faru. ");
INSERT INTO hausa_vpl VALUES ("MK5_34","071_5_34","MRK","5","34","34","Sai ya ce mata, “Diyata, bangaskiyarki ta warkar da ke. Ki sauka lafiya, kin kuma rabu da dukan wahalarki.” ");
INSERT INTO hausa_vpl VALUES ("MK5_35","071_5_35","MRK","5","35","35","Yayinda Yesu yana cikin magana, sai waɗansu mutane daga gidan Yayirus, mai mulkin majami’a, suka zo suka ce, “Diyarka ta rasu. Kada ma ka wahal da Malam.” ");
INSERT INTO hausa_vpl VALUES ("MK5_36","071_5_36","MRK","5","36","36","Yesu bai kula da abin da suka faɗa ba, sai ya ce wa mai mulkin majami’ar, “Kada ka ji tsoro, ka gaskata kawai.” ");
INSERT INTO hausa_vpl VALUES ("MK5_37","071_5_37","MRK","5","37","37","Bai bar kowa ya bi shi ba, sai Bitrus, Yaƙub da Yohanna ɗan’uwan Yaƙub. ");
INSERT INTO hausa_vpl VALUES ("MK5_38","071_5_38","MRK","5","38","38","Da suka iso gidan mai mulkin majami’ar, sai Yesu ya ga ana hayaniya, mutane suna kuka da kururuwa. ");
INSERT INTO hausa_vpl VALUES ("MK5_39","071_5_39","MRK","5","39","39","Sai ya shiga ciki, ya ce musu, “Mene ne dalilin wannan hayaniya da kuka? Yarinyar ba mutuwa ne ta yi ba, barci take yi.” ");
INSERT INTO hausa_vpl VALUES ("MK5_40","071_5_40","MRK","5","40","40","Sai suka yi masa dariya. Bayan ya fitar da su duk waje, sai ya ɗauki mahaifin da mahaifiyar yarinyar tare da almajiran da suke tare da shi, suka shiga inda yarinyar take. ");
INSERT INTO hausa_vpl VALUES ("MK5_41","071_5_41","MRK","5","41","41","Sai ya kama hannunta ya ce mata, “Talita kum!” (Wato, “Ƙaramar yarinya, na ce miki, tashi!”). ");
INSERT INTO hausa_vpl VALUES ("MK5_42","071_5_42","MRK","5","42","42","Nan da nan, sai yarinyar ta tashi ta yi tafiya (shekarunta goma sha biyu ne). Saboda wannan, suka yi mamaki ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("MK5_43","071_5_43","MRK","5","43","43","Sai ya ba da umarni mai tsanani, kada kowa yă san kome game da wannan. Sai ya ce musu, su ba ta wani abu tă ci. ");
INSERT INTO hausa_vpl VALUES ("MK6_1","071_6_1","MRK","6","1","1","Yesu ya tashi daga can ya tafi garinsa, tare da almajiransa. ");
INSERT INTO hausa_vpl VALUES ("MK6_2","071_6_2","MRK","6","2","2","Da Asabbaci ya kewayo, sai ya fara koyarwa a cikin majami’a, mutane da yawa da suka saurare shi, suka yi mamaki. Suna tambaya, “Ina mutumin nan ya sami waɗannan abubuwa? Wace hikima ce wannan da aka ba shi, har da yana yin ayyukan banmamaki haka! ");
INSERT INTO hausa_vpl VALUES ("MK6_3","071_6_3","MRK","6","3","3","Ashe, wannan ba shi ne kafinta nan ba? Shin, ba shi ne ɗan Maryamu ba, ba shi ne ɗan’uwan su Yaƙub, Yusuf, Yahuda da kuma Siman ba? Ashe, ’yan’uwansa mata kuma ba suna nan tare da mu ba?” Sai suka ji haushinsa. ");
INSERT INTO hausa_vpl VALUES ("MK6_4","071_6_4","MRK","6","4","4","Yesu ya ce musu, “Sai a garinsa kaɗai, da kuma cikin ’yan’uwansa, da cikin gidansa ne, annabi ba shi da daraja.” ");
INSERT INTO hausa_vpl VALUES ("MK6_5","071_6_5","MRK","6","5","5","Bai iya yin ayyukan banmamaki a wurin ba, sai dai ɗibiya hannuwansa da ya yi a kan mutane kima da suke da cututtuka, ya kuwa warkar da su. ");
INSERT INTO hausa_vpl VALUES ("MK6_6","071_6_6","MRK","6","6","6","Ya kuwa yi mamaki ƙwarai don rashin bangaskiyarsu. Sai ya Yesu zazzaga ƙauyuka yana koyarwa. ");
INSERT INTO hausa_vpl VALUES ("MK6_7","071_6_7","MRK","6","7","7","Ya kira Sha Biyun nan wurinsa, ya aike su biyu-biyu, ya kuma ba su iko bisa mugayen ruhohi. ");
INSERT INTO hausa_vpl VALUES ("MK6_8","071_6_8","MRK","6","8","8","Ga dai umarnansa, “Kada ku ɗauki kome don tafiyar, sai dai sanda ba burodi, ba jaka, ba kuɗi a ɗamararku. ");
INSERT INTO hausa_vpl VALUES ("MK6_9","071_6_9","MRK","6","9","9","Ku sa takalma, amma ban da riga fiye da waɗanda kuka sa. ");
INSERT INTO hausa_vpl VALUES ("MK6_10","071_6_10","MRK","6","10","10","Duk sa’ad da kuka shiga wani gida, ku zauna nan sai kun bar garin. ");
INSERT INTO hausa_vpl VALUES ("MK6_11","071_6_11","MRK","6","11","11","In kuwa a wani wuri ba a karɓe ku, ba a kuwa saurare ku ba, sai ku karkaɗe ƙurar ƙafafunku sa’ad da kuka fita, a matsayin shaida a kansu.” ");
INSERT INTO hausa_vpl VALUES ("MK6_12","071_6_12","MRK","6","12","12","Suka fita, suna yi wa’azi, suna ce wa mutane su tuba. ");
INSERT INTO hausa_vpl VALUES ("MK6_13","071_6_13","MRK","6","13","13","Suka fitar da aljanu da yawa, suka shafa wa marasa lafiya da yawa mai, suka kuwa warkar da su. ");
INSERT INTO hausa_vpl VALUES ("MK6_14","071_6_14","MRK","6","14","14","Sarki Hiridus ya ji wannan labari, gama sunan Yesu ya bazu a ko’ina. Waɗansu suna cewa, “An tashe Yohanna Mai Baftisma daga matattu ne, shi ya sa yana da ikon yin ayyukan banmamakin nan.” ");
INSERT INTO hausa_vpl VALUES ("MK6_15","071_6_15","MRK","6","15","15","Waɗansu suka ce, “Ai, Iliya ne.” Har wa yau waɗansu suka ce, “Ai, annabi ne, kamar ɗaya daga cikin annabawan dā.” ");
INSERT INTO hausa_vpl VALUES ("MK6_16","071_6_16","MRK","6","16","16","Amma da Hiridus ya ji haka, sai ya ce, “Ai, Yohanna ne, mutumin da na yanke masa kai, shi ne ya tashi daga matattu!” ");
INSERT INTO hausa_vpl VALUES ("MK6_17","071_6_17","MRK","6","17","17","Gama Hiridus da kansa ya ba da umarni a kama Yohanna, ya kuma sa aka daure shi, aka sa shi a kurkuku. Ya yi haka saboda Hiridiyas, matar ɗan’uwansa Filibus, wadda ya aura. ");
INSERT INTO hausa_vpl VALUES ("MK6_18","071_6_18","MRK","6","18","18","Gama Yohanna ya yi ta ce wa Hiridus, “Ba daidai ba ne bisa ga doka, ka ɗauki matar ɗan’uwanka.” ");
INSERT INTO hausa_vpl VALUES ("MK6_19","071_6_19","MRK","6","19","19","Saboda haka, Hiridiyas ta ƙulla munafunci game da Yohanna, ta kuma so ta kashe shi. Amma ba tă iya ba, ");
INSERT INTO hausa_vpl VALUES ("MK6_20","071_6_20","MRK","6","20","20","domin Hiridus yana jin tsoron Yohanna, ya kuma kāre shi sosai, da sanin cewa shi mutum ne mai adalci da kuma mai tsarki. Duk sa’ad da Hiridus ya saurari Yohanna, yakan damu ƙwarai, duk da haka, yakan so yă ji shi. ");
INSERT INTO hausa_vpl VALUES ("MK6_21","071_6_21","MRK","6","21","21","A ƙarshe, ta sami zarafi. A ranar murnar haihuwar Hiridus, ya yi biki domin hakimansa, da shugabannin sojojinsa, da kuma manyan mutanen Galili. ");
INSERT INTO hausa_vpl VALUES ("MK6_22","071_6_22","MRK","6","22","22","Sa’ad da diyar Hiridiyas ta shigo, ta kuma yi rawa, sai ta gamshi Hiridus tare da baƙinsa. Sai Sarkin ya ce wa yarinyar, “Ki tambaye ni kome da kike so, ni kuwa zan ba ki.” ");
INSERT INTO hausa_vpl VALUES ("MK6_23","071_6_23","MRK","6","23","23","Ya yi mata alkawari da rantsuwa cewa, “Duk abin da kika roƙa, zan ba ki, ko da rabin mulkina ne.” ");
INSERT INTO hausa_vpl VALUES ("MK6_24","071_6_24","MRK","6","24","24","Sai ta fita ta ce wa mahaifiyarta, “Me zan roƙa?” Ta ce, “Kan Yohanna Mai Baftisma.” ");
INSERT INTO hausa_vpl VALUES ("MK6_25","071_6_25","MRK","6","25","25","Nan da nan, sai yarinyar ta yi hanzari zuwa wajen sarki da roƙon, “Ina so ka ba ni kan Yohanna Mai Baftisma a cikin tasa, yanzu-yanzu nan.” ");
INSERT INTO hausa_vpl VALUES ("MK6_26","071_6_26","MRK","6","26","26","Sai sarki ya yi baƙin ciki ƙwarai, amma saboda rantsuwar da kuma baƙinsa, bai so yă hana ta ba. ");
INSERT INTO hausa_vpl VALUES ("MK6_27","071_6_27","MRK","6","27","27","Nan take, sai ya aiki mai aiwatar da kisa da umarni ya kawo kan Yohanna. Mutumin ya je ya yanke kan Yohanna a kurkuku. ");
INSERT INTO hausa_vpl VALUES ("MK6_28","071_6_28","MRK","6","28","28","Ya kuma kawo kan a tasa ya ba yarinyar. Ita kuma ta ba wa mahaifiyarta. ");
INSERT INTO hausa_vpl VALUES ("MK6_29","071_6_29","MRK","6","29","29","Da almajiran Yohanna suka sami labari, sai suka zo suka ɗauki jikinsa suka binne a kabari. ");
INSERT INTO hausa_vpl VALUES ("MK6_30","071_6_30","MRK","6","30","30","Manzannin suka taru kewaye da Yesu, suka ba shi rahoton duk abin da suka yi, da kuma suka koyar. ");
INSERT INTO hausa_vpl VALUES ("MK6_31","071_6_31","MRK","6","31","31","To, saboda mutane da yawa suna kai da kawowa, har ma ba su sami damar cin abinci ba, sai ya ce musu, “Ku zo mu kaɗaita inda ba kowa don ku ɗan huta.” ");
INSERT INTO hausa_vpl VALUES ("MK6_32","071_6_32","MRK","6","32","32","Sai suka tafi a jirgin ruwa su kaɗai, inda ba kowa. ");
INSERT INTO hausa_vpl VALUES ("MK6_33","071_6_33","MRK","6","33","33","Amma mutane da yawa waɗanda suka ga tashinsu, sun gane su, sai suka ruga da gudu a ƙafa daga dukan birane, suka riga su kaiwa can. ");
INSERT INTO hausa_vpl VALUES ("MK6_34","071_6_34","MRK","6","34","34","Da Yesu ya sauka, ya ga taro mai yawa, sai ya ji tausayinsu, gama kamar tumaki suke waɗanda ba su da makiyayi. Sai ya fara koya musu abubuwa da yawa. ");
INSERT INTO hausa_vpl VALUES ("MK6_35","071_6_35","MRK","6","35","35","A lokacin nan yamma ta yi, sai almajiransa suka zo wurinsa suka ce masa, “Wurin nan ƙauye ne, ga shi kuma lokaci ya ƙure. ");
INSERT INTO hausa_vpl VALUES ("MK6_36","071_6_36","MRK","6","36","36","Ka sallami mutanen su shiga ƙauyukan da suke kurkusa, su sayi wa kansu wani abu, su ci.” ");
INSERT INTO hausa_vpl VALUES ("MK6_37","071_6_37","MRK","6","37","37","Sai ya amsa ya ce, “Ku, ku ba su wani abu su ci.” Suka ce masa, “Ai, wannan zai ɗauki albashin wata takwas na mutum! Mu je mu kashe yawan kuɗin nan a burodi mu ba su su ci?” ");
INSERT INTO hausa_vpl VALUES ("MK6_38","071_6_38","MRK","6","38","38","Sai ya yi tambaya ya ce, “Burodi nawa kuke da su? Je ku duba.” Da suka duba, sai suka ce, “Biyar da kifi biyu.” ");
INSERT INTO hausa_vpl VALUES ("MK6_39","071_6_39","MRK","6","39","39","Sa’an nan Yesu ya umarce su su sa dukan mutanen su zazzauna ƙungiya-ƙungiya a kan ɗanyar ciyawa. ");
INSERT INTO hausa_vpl VALUES ("MK6_40","071_6_40","MRK","6","40","40","Haka suka zazzauna a ƙungiyar ɗari-ɗari, da kuma hamsin-hamsin. ");
INSERT INTO hausa_vpl VALUES ("MK6_41","071_6_41","MRK","6","41","41","Ya ɗauki burodi guda biyar da kifin nan biyu, ya ɗaga kai sama, ya yi godiya, ya kakkarya burodin. Sai ya ba wa almajiransa su rarraba wa mutane. Ya kuma rarraba kifi biyun a tsakaninsu duka. ");
INSERT INTO hausa_vpl VALUES ("MK6_42","071_6_42","MRK","6","42","42","Kowa ya ci, ya ƙoshi, ");
INSERT INTO hausa_vpl VALUES ("MK6_43","071_6_43","MRK","6","43","43","almajiran suka kwashe gutsattsarin burodin da na kifin cike da kwanduna goma sha biyu. ");
INSERT INTO hausa_vpl VALUES ("MK6_44","071_6_44","MRK","6","44","44","Yawan mutanen da suka ci kuwa maza dubu biyar ne. ");
INSERT INTO hausa_vpl VALUES ("MK6_45","071_6_45","MRK","6","45","45","Nan da nan Yesu ya sa almajiransa su shiga jirgin ruwa, su sha gabansa zuwa Betsaida, shi kuma yă sallami taron. ");
INSERT INTO hausa_vpl VALUES ("MK6_46","071_6_46","MRK","6","46","46","Bayan ya bar su, sai ya hau kan dutse don yă yi addu’a. ");
INSERT INTO hausa_vpl VALUES ("MK6_47","071_6_47","MRK","6","47","47","Da yamma ta yi, jirgin ruwan yana tsakiyar tafkin, Yesu kuma yana can a ƙasa shi kaɗai. ");
INSERT INTO hausa_vpl VALUES ("MK6_48","071_6_48","MRK","6","48","48","Ya ga almajiran suna fama da tuƙi saboda iska tana gāba da su. Wajen tsara ta huɗu na dare, sai ya tafi wurinsu, yana takawa a kan tafkin. Ya yi kamar zai wuce su, ");
INSERT INTO hausa_vpl VALUES ("MK6_49","071_6_49","MRK","6","49","49","amma da suka gan shi yana takawa a kan tafkin, sai suka yi tsammani fatalwa ce. Sai suka yi ihu, ");
INSERT INTO hausa_vpl VALUES ("MK6_50","071_6_50","MRK","6","50","50","domin dukansu sun gan shi, suka kuma tsorata. Nan da nan ya yi magana da su ya ce, “Ku yi ƙarfin hali! Ni ne. Kada ku ji tsoro.” ");
INSERT INTO hausa_vpl VALUES ("MK6_51","071_6_51","MRK","6","51","51","Sai ya shiga jirgin ruwan tare da su, iskar kuma ta kwanta. Dukansu suka yi mamaki, ");
INSERT INTO hausa_vpl VALUES ("MK6_52","071_6_52","MRK","6","52","52","gama ba su fahimci al’amarin burodin nan ba, don zuciyarsu ta taurare. ");
INSERT INTO hausa_vpl VALUES ("MK6_53","071_6_53","MRK","6","53","53","Da suka haye, sai suka sauka a Gennesaret, suka daure jirgin a ƙugiya. ");
INSERT INTO hausa_vpl VALUES ("MK6_54","071_6_54","MRK","6","54","54","Da fitowarsu daga jirgin, sai mutane suka gane Yesu. ");
INSERT INTO hausa_vpl VALUES ("MK6_55","071_6_55","MRK","6","55","55","Suka gama yankin da gudu, suna ɗaukan marasa lafiya a kan tabarmai zuwa duk inda suka ji yake. ");
INSERT INTO hausa_vpl VALUES ("MK6_56","071_6_56","MRK","6","56","56","Duk inda ya shiga, cikin ƙauyuka, birane ko karkara, sai su kwantar da marasa lafiya a bakin kasuwa. Suka roƙe shi yă bari su taɓa gefen rigarsa kawai, kuma duk waɗanda suka taɓa shi kuwa, suka warke. ");
INSERT INTO hausa_vpl VALUES ("MK7_1","071_7_1","MRK","7","1","1","Farisiyawa da waɗansu malaman dokoki waɗanda suka zo daga Urushalima, suka taru kewaye da Yesu. ");
INSERT INTO hausa_vpl VALUES ("MK7_2","071_7_2","MRK","7","2","2","Sai suka ga waɗansu daga cikin almajiransa suna cin abinci da hannuwa marasa tsabta, wato, da ba a wanke ba. ");
INSERT INTO hausa_vpl VALUES ("MK7_3","071_7_3","MRK","7","3","3","(Farisiyawa da dukan Yahudawa ba sa cin abinci, sai sun wanke hannuwa sarai tukuna, yadda al’adun dattawa suka ce. ");
INSERT INTO hausa_vpl VALUES ("MK7_4","071_7_4","MRK","7","4","4","Sa’ad da suka dawo daga wurin kasuwanci, dole su wanke hannu kafin su ci abinci. Sukan kuma kiyaye waɗansu al’adu da yawa, kamar wanken kwafuna, tuluna da butoci.) ");
INSERT INTO hausa_vpl VALUES ("MK7_5","071_7_5","MRK","7","5","5","Saboda haka, Farisiyawa da malaman dokoki suka tambayi Yesu, suka ce, “Don me almajiranka ba sa bin al’adun dattawa, a maimakon haka suna cin abinci da hannuwa marasa tsabta?” ");
INSERT INTO hausa_vpl VALUES ("MK7_6","071_7_6","MRK","7","6","6","Ya amsa ya ce, “Daidai ne Ishaya ya yi annabci game da ku munafukai; kamar yadda yake a rubuce cewa, “ ‘Waɗannan mutane da baki suke girmama ni, amma zukatansu sun yi nesa da ni. ");
INSERT INTO hausa_vpl VALUES ("MK7_7","071_7_7","MRK","7","7","7","A banza suke mini sujada, koyarwarsu, dokokin mutane ne kawai.’ ");
INSERT INTO hausa_vpl VALUES ("MK7_8","071_7_8","MRK","7","8","8","Kun yar da umarnan Allah, kuna bin al’adun mutane.” ");
INSERT INTO hausa_vpl VALUES ("MK7_9","071_7_9","MRK","7","9","9","Ya kuma ce musu, “Kuna da hanya mai sauƙi na ajiye umarnan Allah a gefe ɗaya, don ku kiyaye al’adunku! ");
INSERT INTO hausa_vpl VALUES ("MK7_10","071_7_10","MRK","7","10","10","Gama Musa ya ce, ‘Ka girmama mahaifinka da mahaifiyarka,’kuma, ‘Duk wanda ya zagi mahaifinsa ko mahaifiyarsa, dole a kashe shi.’ ");
INSERT INTO hausa_vpl VALUES ("MK7_11","071_7_11","MRK","7","11","11","Amma ku, kukan ce, in mutum ya ce wa mahaifinsa, ko mahaifiyarsa, ‘Duk taimakon da ya kamata ku samu daga wurina, Korban ne,’ (wato, abin da aka keɓe wa Allah), ");
INSERT INTO hausa_vpl VALUES ("MK7_12","071_7_12","MRK","7","12","12","sa’an nan haka ba kwa ƙara barinsa yă yi wa mahaifinsa ko mahaifiyarsa wani abu. ");
INSERT INTO hausa_vpl VALUES ("MK7_13","071_7_13","MRK","7","13","13","Ta haka kuke rushe maganar Allah ta wurin al’adun da kuke miƙa wa ’ya’yanku. Haka kuma kuke yin abubuwa da yawa.” ");
INSERT INTO hausa_vpl VALUES ("MK7_14","071_7_14","MRK","7","14","14","Sai Yesu ya sāke kiran taron wurinsa ya ce, “Ku saurare ni dukanku, ku kuma fahimci wannan. ");
INSERT INTO hausa_vpl VALUES ("MK7_15","071_7_15","MRK","7","15","15","Ba abin da yake shiga mutum daga waje ba ne yake ƙazantar da shi. Sai dai abin da ya fita daga cikin mutum ne, yake ƙazantar da shi.” ");
INSERT INTO hausa_vpl VALUES ("MK7_17","071_7_17","MRK","7","17","17","Bayan ya bar taron, ya shiga gida, sai almajiransa suka tambaye shi ma’anar wannan misali. ");
INSERT INTO hausa_vpl VALUES ("MK7_18","071_7_18","MRK","7","18","18","Ya ce, “Ashe, ba ku da saurin ganewa? Ba ku gane cewa ba abin da yake shiga mutum daga waje ba ne yake ƙazantar da shi. ");
INSERT INTO hausa_vpl VALUES ("MK7_19","071_7_19","MRK","7","19","19","Gama ba ya shiga cikin zuciyarsa, sai dai cikin tumbinsa, sa’an nan kuma yă fita daga jikinsa.” (Da faɗin haka, Yesu ya nuna tsabtar kowane irin abinci.) ");
INSERT INTO hausa_vpl VALUES ("MK7_20","071_7_20","MRK","7","20","20","Ya ci gaba, “Abin da yake fitowa daga mutum ne yake ƙazantar da shi. ");
INSERT INTO hausa_vpl VALUES ("MK7_21","071_7_21","MRK","7","21","21","Gama daga ciki, daga zuciyar mutane, mugayen tunani suke fitowa, fasikanci, sata, kisankai, zina, ");
INSERT INTO hausa_vpl VALUES ("MK7_22","071_7_22","MRK","7","22","22","kwaɗayi, ƙeta, ruɗu, ƙazantaccen sha’awa, kishi, ɓata suna, girman kai da kuma wauta. ");
INSERT INTO hausa_vpl VALUES ("MK7_23","071_7_23","MRK","7","23","23","Duk waɗannan mugayen abubuwa daga cikin suke fitowa, suna kuma ƙazantar da mutum.” ");
INSERT INTO hausa_vpl VALUES ("MK7_24","071_7_24","MRK","7","24","24","Sai Yesu ya bar wurin, ya kuma tafi wajajen Taya. Ya shiga wani gida, bai kuwa so kowa yă sani ba. Duk da haka, bai iya ɓoye kasancewarsa ba. ");
INSERT INTO hausa_vpl VALUES ("MK7_25","071_7_25","MRK","7","25","25","Da jin labarinsa, sai wata mace wadda ƙaramar diyarta tana da mugun ruhu, ta zo ta durƙusa a gabansa. ");
INSERT INTO hausa_vpl VALUES ("MK7_26","071_7_26","MRK","7","26","26","Macen kuwa mutuniyar Hellenawa ce, an haife ta a Funisiya a Suriya. Ta roƙi Yesu yă fitar da aljani da yake jikin diyarta. ");
INSERT INTO hausa_vpl VALUES ("MK7_27","071_7_27","MRK","7","27","27","Yesu ya ce mata, “Da farko, bari ’ya’ya su ci su ƙoshi tukuna, gama ba daidai ba ne, a ɗauki burodin yara a jefa wa karnukansu.” ");
INSERT INTO hausa_vpl VALUES ("MK7_28","071_7_28","MRK","7","28","28","Ta amsa, ta ce, “I, Ubangiji, ko karnuka ma da suke ƙarƙashin tebur, sukan ci burbuɗin da suke fāɗuwa daga abincin yara.” ");
INSERT INTO hausa_vpl VALUES ("MK7_29","071_7_29","MRK","7","29","29","Sai ya ce mata, “Saboda irin wannan amsa, ki tafi, aljanin ya rabu da diyarki.” ");
INSERT INTO hausa_vpl VALUES ("MK7_30","071_7_30","MRK","7","30","30","Ta tafi gida, ta tarar da diyarta kwance a gado, aljanin kuwa ya fita. ");
INSERT INTO hausa_vpl VALUES ("MK7_31","071_7_31","MRK","7","31","31","Sai Yesu ya bar wajajen Taya, ya bi ta Sidon har zuwa Tekun Galili da kuma cikin yankin Dekafolis. ");
INSERT INTO hausa_vpl VALUES ("MK7_32","071_7_32","MRK","7","32","32","A can ne waɗansu mutane suka kawo masa wani kurma, wanda da ƙyar yake magana. Sai suka roƙe shi yă ɗibiya hannunsa a kan mutumin. ");
INSERT INTO hausa_vpl VALUES ("MK7_33","071_7_33","MRK","7","33","33","Bayan da ya jawo shi gefe, sai Yesu ya sa yatsotsinsa a kunnuwan mutumin, ya tofa miyau ya kuma taɓa harshen mutumin. ");
INSERT INTO hausa_vpl VALUES ("MK7_34","071_7_34","MRK","7","34","34","Ya ɗaga kai sama, ya ja numfashi mai zurfi, sa’an nan ya ce masa, “Effata!” (Wato, “Buɗe!”). ");
INSERT INTO hausa_vpl VALUES ("MK7_35","071_7_35","MRK","7","35","35","Bayan ya faɗa haka, sai kunnuwan mutumin suka buɗe, harshensa kuma ya kunce, sai ya fara magana sarai. ");
INSERT INTO hausa_vpl VALUES ("MK7_36","071_7_36","MRK","7","36","36","Yesu ya umarce su, kada su gaya wa kowa. Amma ƙara yawan kwaɓarsu ƙara yawan yaɗa labarin suke ta yi. ");
INSERT INTO hausa_vpl VALUES ("MK7_37","071_7_37","MRK","7","37","37","Mutane suka cika da mamaki, suka ce, “Kai, ya yi kome daidai. Har ma yana sa kurame su ji, bebaye kuma su yi magana.” ");
INSERT INTO hausa_vpl VALUES ("MK8_1","071_8_1","MRK","8","1","1","A kwanakin nan wani taro mai girma ya taru. Tun da yake ba su da abin da za su ci, sai Yesu ya kira almajiransa ya ce, ");
INSERT INTO hausa_vpl VALUES ("MK8_2","071_8_2","MRK","8","2","2","“Ina jin tausayin mutanen nan, kwanansu uku ke nan tare da ni, kuma ba su da abin da za su ci. ");
INSERT INTO hausa_vpl VALUES ("MK8_3","071_8_3","MRK","8","3","3","In na sallame su gida da yunwa, za su kāsa a hanya, don waɗansu daga cikinsu sun zo daga nesa.” ");
INSERT INTO hausa_vpl VALUES ("MK8_4","071_8_4","MRK","8","4","4","Almajiransa suka amsa suka ce, “Amma a ina, a wannan wurin da ba kowa, wani zai iya samun isashen burodi, don a ciyar da su?” ");
INSERT INTO hausa_vpl VALUES ("MK8_5","071_8_5","MRK","8","5","5","Sai Yesu ya yi tambaya ya ce, “Burodi guda nawa kuke da su?” Suka ce, “Bakwai.” ");
INSERT INTO hausa_vpl VALUES ("MK8_6","071_8_6","MRK","8","6","6","Sai ya gaya wa taron su zazzauna a ƙasa. Bayan ya ɗauki burodin nan bakwai, ya yi godiya, sai ya kakkarya, ya ba wa almajiransa su rarraba wa mutanen, suka kuwa yi haka. ");
INSERT INTO hausa_vpl VALUES ("MK8_7","071_8_7","MRK","8","7","7","Suna kuma da ƙananan kifaye kaɗan, ya ba da godiya dominsu, ya kuma ce wa almajiran su rarraba musu. ");
INSERT INTO hausa_vpl VALUES ("MK8_8","071_8_8","MRK","8","8","8","Mutanen suka ci, suka ƙoshi. Daga baya, almajiran suka tattara gutsattsarin da suka rage cike da kwanduna bakwai. ");
INSERT INTO hausa_vpl VALUES ("MK8_9","071_8_9","MRK","8","9","9","Wajen maza dubu huɗu ne suka kasance. Da ya sallame su, ");
INSERT INTO hausa_vpl VALUES ("MK8_10","071_8_10","MRK","8","10","10","sai ya shiga jirgin ruwa tare da almajiransa, suka tafi yankin Dalmanuta. ");
INSERT INTO hausa_vpl VALUES ("MK8_11","071_8_11","MRK","8","11","11","Farisiyawa suka zo suka fara yin wa Yesu tambayoyi. Don su gwada shi, sai suka nemi yă nuna musu wata alama daga sama. ");
INSERT INTO hausa_vpl VALUES ("MK8_12","071_8_12","MRK","8","12","12","Sai ya ja numfashi mai zurfi ya ce, “Don me wannan zamani yake neman ganin abin banmamaki? Gaskiya nake gaya muku, ba wata alamar da za a ba su.” ");
INSERT INTO hausa_vpl VALUES ("MK8_13","071_8_13","MRK","8","13","13","Sai ya bar su, ya koma cikin jirgin ruwan, suka ƙetare zuwa ɗaya hayin. ");
INSERT INTO hausa_vpl VALUES ("MK8_14","071_8_14","MRK","8","14","14","Almajiran suka manta su riƙe burodi, sai dai guda ɗaya da suke da shi a cikin jirgin ruwan. ");
INSERT INTO hausa_vpl VALUES ("MK8_15","071_8_15","MRK","8","15","15","Yesu ya gargaɗe su ya ce, “Ku yi hankali, ku kuma lura da yistin Farisiyawa da na Hiridus.” ");
INSERT INTO hausa_vpl VALUES ("MK8_16","071_8_16","MRK","8","16","16","Suka tattauna wannan da juna, suna cewa, “Don ba mu da burodi ne.” ");
INSERT INTO hausa_vpl VALUES ("MK8_17","071_8_17","MRK","8","17","17","Da ya gane abin da suke tattaunawa, sai Yesu ya tambaye su ya ce, “Don me kuke zancen rashin burodi? Har yanzu ba ku gane ko fahimta ba? Zukatanku sun taurare ne? ");
INSERT INTO hausa_vpl VALUES ("MK8_18","071_8_18","MRK","8","18","18","Kuna da idanu, amma kun kāsa gani, kuna da kunnuwa, amma kun kāsa ji? Ba ku tuna ba? ");
INSERT INTO hausa_vpl VALUES ("MK8_19","071_8_19","MRK","8","19","19","Da na kakkarya burodi guda biyar wa mutane dubu biyar, kwanduna nawa kuka kwashe cike da gutsattsarin?” Suka amsa, “Sha biyu.” ");
INSERT INTO hausa_vpl VALUES ("MK8_20","071_8_20","MRK","8","20","20","“Da na kuma kakkarya burodin nan bakwai wa mutum dubu huɗu, kwanduna nawa kuka kwashe cike da gutsattsarin?” Suka ce, “Bakwai.” ");
INSERT INTO hausa_vpl VALUES ("MK8_21","071_8_21","MRK","8","21","21","Ya ce musu, “Har yanzu ba ku fahimta ba?” ");
INSERT INTO hausa_vpl VALUES ("MK8_22","071_8_22","MRK","8","22","22","Suka iso Betsaida, sai waɗansu mutane suka kawo wani makaho, suka roƙi Yesu yă taɓa shi. ");
INSERT INTO hausa_vpl VALUES ("MK8_23","071_8_23","MRK","8","23","23","Yesu ya kama hannun makahon ya kai shi bayan ƙauyen. Bayan ya tofa miyau a idanun mutumin, ya kuma ɗibiya masa hannuwansa, sai ya tambaye shi ya ce, “Kana iya ganin wani abu?” ");
INSERT INTO hausa_vpl VALUES ("MK8_24","071_8_24","MRK","8","24","24","Sai ya ɗaga kai ya ce, “Ina ganin mutane, suna kama da itatuwa da suke tafiya.” ");
INSERT INTO hausa_vpl VALUES ("MK8_25","071_8_25","MRK","8","25","25","Yesu ya sāke ɗibiya hannuwansa a idanun mutumin, sai idanunsa suka buɗe, ya sami gani, ya kuma ga kome sarai. ");
INSERT INTO hausa_vpl VALUES ("MK8_26","071_8_26","MRK","8","26","26","Yesu ya sallame shi gida ya ce, “Kada ka shiga cikin ƙauyen.” ");
INSERT INTO hausa_vpl VALUES ("MK8_27","071_8_27","MRK","8","27","27","Yesu da almajiransa suka tafi ƙauyukan da suke kewaye da Kaisariya Filibbi. A hanya ya tambaye su ya ce, “Wa, mutane suke ce da ni?” ");
INSERT INTO hausa_vpl VALUES ("MK8_28","071_8_28","MRK","8","28","28","Suka amsa, suka ce, “Waɗansu suna cewa, Yohanna Mai Baftisma, waɗansu Iliya, waɗansu kuma har wa yau sun ce, ɗaya daga cikin annabawa.” ");
INSERT INTO hausa_vpl VALUES ("MK8_29","071_8_29","MRK","8","29","29","Sai ya yi tambaya ya ce, “Amma ku fa, wa kuke ce da ni?” Bitrus ya amsa ya ce, “Kai ne Kiristi.” ");
INSERT INTO hausa_vpl VALUES ("MK8_30","071_8_30","MRK","8","30","30","Yesu ya gargaɗe su kada su gaya wa kowa kome a kansa. ");
INSERT INTO hausa_vpl VALUES ("MK8_31","071_8_31","MRK","8","31","31","Sai ya fara koya musu cewa, dole Ɗan Mutum yă sha wahaloli da yawa, dattawa, manyan firistoci da malaman dokoki kuma su ƙi shi. Dole kuma a kashe shi, bayan kwana uku kuma, yă tashi. ");
INSERT INTO hausa_vpl VALUES ("MK8_32","071_8_32","MRK","8","32","32","Ya yi wannan zance a sarari. Sai Bitrus ya jawo shi gefe, ya fara tsawata masa. ");
INSERT INTO hausa_vpl VALUES ("MK8_33","071_8_33","MRK","8","33","33","Amma da Yesu ya juya ya dubi almajiransa, sai ya tsawata wa Bitrus ya ce, “Tashi daga nan Shaiɗan! Ba ka da al’amuran Allah a zuciyarka, sai na mutane.” ");
INSERT INTO hausa_vpl VALUES ("MK8_34","071_8_34","MRK","8","34","34","Sai ya kira taron wurinsa tare da almajiransa ya ce, “Duk wanda zai bi ni, dole yă ƙi kansa, yă ɗauki gicciyensa yă bi ni. ");
INSERT INTO hausa_vpl VALUES ("MK8_35","071_8_35","MRK","8","35","35","Domin duk mai son ceton ransa zai rasa shi, amma duk wanda ya rasa ransa saboda ni, da kuma bishara, zai same shi. ");
INSERT INTO hausa_vpl VALUES ("MK8_36","071_8_36","MRK","8","36","36","Me mutum zai amfana, in ya ribato duniya duka a bakin ransa? ");
INSERT INTO hausa_vpl VALUES ("MK8_37","071_8_37","MRK","8","37","37","Ko kuma, me mutum zai bayar a musayar ransa? ");
INSERT INTO hausa_vpl VALUES ("MK8_38","071_8_38","MRK","8","38","38","Duk wanda ya ji kunyata, da na kalmomina a wannan zamani na fasikanci da zunubi, Ɗan Mutum ma zai ji kunyarsa lokacin da ya shiga cikin ɗaukakar Ubansa, tare da tsarkakan mala’iku.” ");
INSERT INTO hausa_vpl VALUES ("MK9_1","071_9_1","MRK","9","1","1","Ya kuma ce musu, “Gaskiya nake gaya muku, waɗansu da suke tsattsaye a nan ba za su mutu ba, sai sun ga mulkin Allah ya bayyana da iko.” ");
INSERT INTO hausa_vpl VALUES ("MK9_2","071_9_2","MRK","9","2","2","Bayan kwana shida, sai Yesu ya ɗauki Bitrus, Yaƙub da Yohanna tare da shi, ya kai su kan wani dutse mai tsawo, suka kasance su kaɗai a wurin. A can aka sāke kamanninsa a gabansu. ");
INSERT INTO hausa_vpl VALUES ("MK9_3","071_9_3","MRK","9","3","3","Tufafinsa suka zama fari suna ƙyalli, fiye da yadda wani a duniya zai iya yi su. ");
INSERT INTO hausa_vpl VALUES ("MK9_4","071_9_4","MRK","9","4","4","Iliya da Musa suka bayyana a gabansu, suna magana da Yesu. ");
INSERT INTO hausa_vpl VALUES ("MK9_5","071_9_5","MRK","9","5","5","Bitrus ya ce wa Yesu, “Rabbi, ya yi kyau da muke nan. Bari mu kafa bukkoki guda uku, ɗaya dominka, ɗaya domin Musa, ɗaya kuma domin Iliya.” ");
INSERT INTO hausa_vpl VALUES ("MK9_6","071_9_6","MRK","9","6","6","(Bai san abin da zai faɗa ba ne, gama sun tsorata ƙwarai.) ");
INSERT INTO hausa_vpl VALUES ("MK9_7","071_9_7","MRK","9","7","7","Sai wani girgije ya bayyana, ya rufe su, wata murya kuma ta fito daga girgijen, ta ce, “Wannan Ɗana ne, wanda nake ƙauna, ku saurare shi!” ");
INSERT INTO hausa_vpl VALUES ("MK9_8","071_9_8","MRK","9","8","8","Farat ɗaya, da suka waiwaya, ba su ƙara ganin kowa tare da su ba, sai dai Yesu. ");
INSERT INTO hausa_vpl VALUES ("MK9_9","071_9_9","MRK","9","9","9","Da suna saukowa daga dutsen, Yesu ya umarce su kada su gaya wa kowa abin da suka gani, sai bayan Ɗan Mutum ya tashi daga matattu. ");
INSERT INTO hausa_vpl VALUES ("MK9_10","071_9_10","MRK","9","10","10","Suka riƙe wannan zance a ɓoye tsakaninsu, suna tattaunawa ko mece ce ma’anar “tashi daga matattu.” ");
INSERT INTO hausa_vpl VALUES ("MK9_11","071_9_11","MRK","9","11","11","Suka tambaye shi, suka ce, “Don me malaman dokoki suke cewa, sai Iliya ya fara zuwa?” ");
INSERT INTO hausa_vpl VALUES ("MK9_12","071_9_12","MRK","9","12","12","Yesu ya amsa ya ce, “Gaskiya ne, Iliya zai zo da fari, yă kuma mayar da dukan abubuwa. Don me kuma aka rubuta cewa, dole Ɗan Mutum yă sha wahala sosai, kuma a ƙi shi? ");
INSERT INTO hausa_vpl VALUES ("MK9_13","071_9_13","MRK","9","13","13","Amma ina faɗa muku, Iliya ya riga ya zo, kuma suka yi duk abin da suka ga dama da shi, kamar yadda aka rubuta game da shi.” ");
INSERT INTO hausa_vpl VALUES ("MK9_14","071_9_14","MRK","9","14","14","Da suka dawo wurin sauran almajiran, sai suka ga babban taro kewaye da su, malaman dokoki suna gardama da su. ");
INSERT INTO hausa_vpl VALUES ("MK9_15","071_9_15","MRK","9","15","15","Nan take da dukan mutanen suka ga Yesu, sai suka cika da mamaki, suka ruga da gudu don su gai da shi. ");
INSERT INTO hausa_vpl VALUES ("MK9_16","071_9_16","MRK","9","16","16","Ya tambaye su ya ce, “Gardamar me kuke yi da su?” ");
INSERT INTO hausa_vpl VALUES ("MK9_17","071_9_17","MRK","9","17","17","Wani mutum a cikin taron ya amsa ya ce, “Malam, na kawo maka ɗana mai wani ruhun da yake hana shi magana. ");
INSERT INTO hausa_vpl VALUES ("MK9_18","071_9_18","MRK","9","18","18","Duk lokacin da mugun ruhun ya kama shi, yakan jefa shi a ƙasa. Bakinsa yakan yi kumfa, yă cije haƙorarsa, yakan sa jikinsa ya sandare, yă zama da ƙarfi. Na roƙi almajiranka su fitar da ruhun, amma ba su iya ba.” ");
INSERT INTO hausa_vpl VALUES ("MK9_19","071_9_19","MRK","9","19","19","Yesu ya ce, “Ya ku zamani marar bangaskiya, har yaushe zan kasance tare da ku? Har yaushe zan yi haƙuri da ku? Kawo mini yaron.” ");
INSERT INTO hausa_vpl VALUES ("MK9_20","071_9_20","MRK","9","20","20","Sai suka kawo shi. Da ruhun ya ga Yesu, nan da nan sai ya buge yaron da farfaɗiya. Ya fāɗi a ƙasa, yana birgima, bakinsa yana kumfa. ");
INSERT INTO hausa_vpl VALUES ("MK9_21","071_9_21","MRK","9","21","21","Yesu ya tambayi mahaifin yaron ya ce, “Tun yaushe yake haka?” Ya ce, “Tun yana ƙarami. ");
INSERT INTO hausa_vpl VALUES ("MK9_22","071_9_22","MRK","9","22","22","Ya sha jefa shi cikin wuta, ko ruwa don yă kashe shi. Amma in za ka iya yin wani abu, ka ji tausayinmu ka taimake mu.” ");
INSERT INTO hausa_vpl VALUES ("MK9_23","071_9_23","MRK","9","23","23","Yesu ya ce, “ ‘In za ka iya’? Ai, kome mai yiwuwa ne ga wanda ya gaskata.” ");
INSERT INTO hausa_vpl VALUES ("MK9_24","071_9_24","MRK","9","24","24","Nan da nan mahaifin yaron ya faɗa da ƙarfi ya ce, “Na gaskata, ka taimake ni in sha kan rashin bangaskiyata!” ");
INSERT INTO hausa_vpl VALUES ("MK9_25","071_9_25","MRK","9","25","25","Da Yesu ya ga taron suna zuwa can a guje, sai ya tsawata wa mugun ruhun ya ce, “Kai ruhun kurma, da na bebe, na umarce ka, ka fita daga cikinsa, kada kuma ka ƙara shigarsa.” ");
INSERT INTO hausa_vpl VALUES ("MK9_26","071_9_26","MRK","9","26","26","Sai ruhun ya yi ihu, ya buge shi da ƙarfi da farfaɗiya, ya fita. Yaron ya kwanta kamar matacce, har mutane da yawa suka ce, “Ai, ya mutu.” ");
INSERT INTO hausa_vpl VALUES ("MK9_27","071_9_27","MRK","9","27","27","Amma Yesu ya kama shi a hannu ya ɗaga, ya kuwa tashi tsaye. ");
INSERT INTO hausa_vpl VALUES ("MK9_28","071_9_28","MRK","9","28","28","Da Yesu ya shiga gida, almajiransa suka tambaye shi a ɓoye, suka ce, “Me ya sa ba mu iya fitar da shi ba?” ");
INSERT INTO hausa_vpl VALUES ("MK9_29","071_9_29","MRK","9","29","29","Ya amsa ya ce, “Sai da addu’akaɗai irin wannan yakan fita.” ");
INSERT INTO hausa_vpl VALUES ("MK9_30","071_9_30","MRK","9","30","30","Suka bar wurin suka bi ta Galili. Yesu bai so wani yă san inda suke ba, ");
INSERT INTO hausa_vpl VALUES ("MK9_31","071_9_31","MRK","9","31","31","gama yana koya wa almajiransa. Ya ce musu, “Za a ci amanar Ɗan Mutum, a ba da shi ga hannun mutane. Za su kashe shi, bayan kwana uku kuma zai tashi.” ");
INSERT INTO hausa_vpl VALUES ("MK9_32","071_9_32","MRK","9","32","32","Amma ba su fahimci abin da yake nufi ba, suka kuma ji tsoro su tambaye shi game da wannan. ");
INSERT INTO hausa_vpl VALUES ("MK9_33","071_9_33","MRK","9","33","33","Suka iso Kafarnahum. Da yana cikin gida, sai ya tambaye su ya ce, “Gardamar me kuke yi a hanya?” ");
INSERT INTO hausa_vpl VALUES ("MK9_34","071_9_34","MRK","9","34","34","Amma suka yi shiru, don a hanya suna gardama ne, a kan ko wane ne a cikinsu ya fi girma? ");
INSERT INTO hausa_vpl VALUES ("MK9_35","071_9_35","MRK","9","35","35","Da Yesu ya zauna, sai ya kira Sha Biyun ya ce, “In wani yana so yă zama na fari, dole yă zama na ƙarshe duka, da kuma bawan kowa.” ");
INSERT INTO hausa_vpl VALUES ("MK9_36","071_9_36","MRK","9","36","36","Ya ɗauki wani ƙaramin yaro ya sa yă tsaya a tsakiyarsu. Ya ɗauke shi a hannunsa, ya ce musu, ");
INSERT INTO hausa_vpl VALUES ("MK9_37","071_9_37","MRK","9","37","37","“Duk wanda ya karɓi ɗaya daga cikin waɗannan ƙananan yara a cikin sunana, ni ya karɓa. Duk wanda kuma ya karɓe ni, ba ni ya karɓa ba, amma wanda ya aiko ni ne ya karɓa.” ");
INSERT INTO hausa_vpl VALUES ("MK9_38","071_9_38","MRK","9","38","38","Yohanna ya ce, “Malam mun ga wani mutum yana fitar da aljanu a cikin sunanka, sai muka ce yă daina, domin shi ba ɗaya daga cikinmu ba ne.” ");
INSERT INTO hausa_vpl VALUES ("MK9_39","071_9_39","MRK","9","39","39","Yesu ya ce, “Kada ku hana shi. Ba wanda yake yin ayyukan banmamaki a cikin sunana, nan take yă faɗi wani abu mummuna game da ni. ");
INSERT INTO hausa_vpl VALUES ("MK9_40","071_9_40","MRK","9","40","40","Gama duk wanda ba ya gāba da mu, namu ne. ");
INSERT INTO hausa_vpl VALUES ("MK9_41","071_9_41","MRK","9","41","41","Gaskiya nake gaya muku, duk wanda ya ba ku ruwan sha a sunana, saboda ku na Kiristi ne, lalle, ba zai rasa ladarsa ba. ");
INSERT INTO hausa_vpl VALUES ("MK9_42","071_9_42","MRK","9","42","42","“Idan kuma wani yă sa ɗaya daga cikin waɗannan ’yan yara masu gaskatawa da ni yă yi laifi, zai fiye masa a rataya wani babban dutsen niƙa a wuyarsa, a jefa shi cikin teku. ");
INSERT INTO hausa_vpl VALUES ("MK9_43","071_9_43","MRK","9","43","43","In hannunka yana sa ka yin zunubi, yanke shi. Ai, gwamma ka shiga rai da hannu ɗaya, da ka shiga jahannama ta wuta, inda ba a iya kashe wutar ba, da hannuwanka biyu. ");
INSERT INTO hausa_vpl VALUES ("MK9_45","071_9_45","MRK","9","45","45","In kuma ƙafarka tana sa ka yin zunubi, yanke ta. Ai, gwamma ka shiga rai da ƙafa ɗaya, da a jefa ka cikin jahannama ta wuta, da ƙafafunka biyu. ");
INSERT INTO hausa_vpl VALUES ("MK9_47","071_9_47","MRK","9","47","47","In kuma idonka yana sa ka zunubi, ƙwaƙule shi. Ai, gwamma ka shiga mulkin Allah da ido ɗaya, da a jefa ka cikin jahannama ta wuta, da idanu biyu, ");
INSERT INTO hausa_vpl VALUES ("MK9_48","071_9_48","MRK","9","48","48","inda “ ‘tsutsotsinsu ba sa mutuwa, wutar kuma ba a iya kashewa.’ ");
INSERT INTO hausa_vpl VALUES ("MK9_49","071_9_49","MRK","9","49","49","Za a tsarkake kowa da wuta. ");
INSERT INTO hausa_vpl VALUES ("MK9_50","071_9_50","MRK","9","50","50","“Gishiri yana da daɗi, amma in ya rabu da ɗanɗanonsa, ta yaya za a sāke mai da ɗanɗanonsa? Ku kasance da gishiri a cikinku, ku kuma yi zauna lafiya da juna.” ");
INSERT INTO hausa_vpl VALUES ("MK10_1","071_10_1","MRK","10","1","1","Sai Yesu ya tashi daga nan ya tafi yankin Yahudiya, da kuma ƙetaren Urdun. Taron mutane suka sāke zuwa wurinsa, ya kuma koya musu kamar yadda ya saba. ");
INSERT INTO hausa_vpl VALUES ("MK10_2","071_10_2","MRK","10","2","2","Waɗansu Farisiyawa suka zo suka gwada shi, ta wurin yin masa tambaya cewa, “Daidai ne bisa ga doka, mutum yă saki matarsa?” ");
INSERT INTO hausa_vpl VALUES ("MK10_3","071_10_3","MRK","10","3","3","Ya amsa ya ce, “Me Musa ya umarce ku?” ");
INSERT INTO hausa_vpl VALUES ("MK10_4","071_10_4","MRK","10","4","4","Suka ce, “Musa ya ba da izini mutum yă rubuta takardar saki, yă kuma kore ta.” ");
INSERT INTO hausa_vpl VALUES ("MK10_5","071_10_5","MRK","10","5","5","Yesu ya ce, “Saboda taurin kanku ne, Musa ya rubuta muku wannan doka. ");
INSERT INTO hausa_vpl VALUES ("MK10_6","071_10_6","MRK","10","6","6","Amma a farkon halitta, Allah ya ‘halicce su miji da mace.’ ");
INSERT INTO hausa_vpl VALUES ("MK10_7","071_10_7","MRK","10","7","7","‘Saboda wannan dalili, mutum zai bar mahaifinsa da mahaifiyarsa, yă manne wa matarsa, ");
INSERT INTO hausa_vpl VALUES ("MK10_8","071_10_8","MRK","10","8","8","su biyun kuma za su zama jiki ɗaya.’Saboda haka, su ba mutum biyu ba ne, amma mutum ɗaya. ");
INSERT INTO hausa_vpl VALUES ("MK10_9","071_10_9","MRK","10","9","9","Domin haka, abin da Allah ya haɗa, kada mutum yă raba.” ");
INSERT INTO hausa_vpl VALUES ("MK10_10","071_10_10","MRK","10","10","10","Da suna cikin gida kuma, sai almajiran suka tambayi Yesu game da wannan. ");
INSERT INTO hausa_vpl VALUES ("MK10_11","071_10_11","MRK","10","11","11","Ya amsa ya ce, “Duk wanda ya saki matarsa, ya auri wata, yana da laifin aikata zina a kan matar da ya saki. ");
INSERT INTO hausa_vpl VALUES ("MK10_12","071_10_12","MRK","10","12","12","In kuma ta saki mijinta ta auri wani, ta yi zina ke nan.” ");
INSERT INTO hausa_vpl VALUES ("MK10_13","071_10_13","MRK","10","13","13","Mutane suka kawo ƙananan yara wurin Yesu don yă taɓa su, amma almajiran suka kwaɓe su. ");
INSERT INTO hausa_vpl VALUES ("MK10_14","071_10_14","MRK","10","14","14","Da Yesu ya ga haka, sai ya yi fushi, ya ce musu, “Ku bar yara ƙanana su zo wurina, kada ku hana su, gama mulkin Allah na irin waɗannan ne. ");
INSERT INTO hausa_vpl VALUES ("MK10_15","071_10_15","MRK","10","15","15","Gaskiya nake gaya muku, duk wanda bai karɓi mulkin Allah kamar ƙaramin yaro ba, ba zai taɓa shiga mulkin ba.” ");
INSERT INTO hausa_vpl VALUES ("MK10_16","071_10_16","MRK","10","16","16","Sai ya ɗauki yaran a hannuwansa, ya ɗibiya musu hannuwansa, ya kuma albarkace su. ");
INSERT INTO hausa_vpl VALUES ("MK10_17","071_10_17","MRK","10","17","17","Da Yesu ya kama hanya, sai wani mutum ya ruga da gudu ya zo wajensa, ya durƙusa a gabansa ya ce, “Malam nagari, me zan yi domin in gāji rai madawwami?” ");
INSERT INTO hausa_vpl VALUES ("MK10_18","071_10_18","MRK","10","18","18","Yesu ya amsa ya ce, “Don me kake ce da ni mai nagarta? Ai, ba wani nagari, sai Allah kaɗai. ");
INSERT INTO hausa_vpl VALUES ("MK10_19","071_10_19","MRK","10","19","19","Ka san dokokin da suka ce, ‘Kada ka yi kisankai, kada ka yi zina, kada ka yi sata, kada ka ba da shaida ta ƙarya, kada ka cuci wani, ka girmama mahaifinka da mahaifiyarka.’” ");
INSERT INTO hausa_vpl VALUES ("MK10_20","071_10_20","MRK","10","20","20","Mutumin ya ce, “Malam, ai, tun ina yaro na kiyaye duk waɗannan.” ");
INSERT INTO hausa_vpl VALUES ("MK10_21","071_10_21","MRK","10","21","21","Yesu ya kalle shi da ƙauna ya ce, “Abu ɗaya ka rasa, ka tafi ka sayar da duk abin da kake da shi, ka ba wa matalauta, za ka kuwa sami dukiya a sama. Sa’an nan ka zo ka bi ni.” ");
INSERT INTO hausa_vpl VALUES ("MK10_22","071_10_22","MRK","10","22","22","Da jin wannan, sai mutumin ya ɓata fuskarsa, ya tafi da baƙin ciki, gama yana da arziki sosai. ");
INSERT INTO hausa_vpl VALUES ("MK10_23","071_10_23","MRK","10","23","23","Yesu ya dudduba, sai ya ce wa almajiransa, “Yana da wuya fa masu arziki su shiga mulkin Allah!” ");
INSERT INTO hausa_vpl VALUES ("MK10_24","071_10_24","MRK","10","24","24","Almajiransa suka yi mamakin kalmominsa. Amma Yesu ya sāke ce musu, “’Ya’yana, yana da wuya fa a shiga mulkin Allah! ");
INSERT INTO hausa_vpl VALUES ("MK10_25","071_10_25","MRK","10","25","25","Ya fi sauƙi raƙumi yă shiga ta kafar allura, da mai arziki yă shiga mulkin Allah.” ");
INSERT INTO hausa_vpl VALUES ("MK10_26","071_10_26","MRK","10","26","26","Almajiran suka yi mamaki ƙwarai, suka ce wa juna, “To, wa zai sami ceto ke nan?” ");
INSERT INTO hausa_vpl VALUES ("MK10_27","071_10_27","MRK","10","27","27","Yesu ya kalle su ya ce, “Ga mutum kam, wannan ba mai yiwuwa ba ne, amma ga Allah, wannan mai yiwuwa ne; dukan abubuwa masu yiwuwa ne ga Allah.” ");
INSERT INTO hausa_vpl VALUES ("MK10_28","071_10_28","MRK","10","28","28","Bitrus ya ce, “Mun bar kome domin mu bi ka!” ");
INSERT INTO hausa_vpl VALUES ("MK10_29","071_10_29","MRK","10","29","29","Yesu ya amsa ya ce, “Gaskiya nake gaya muku, babu wanda zai bar gida, ko ’yan’uwa maza da mata, ko mahaifiya, ko mahaifi, ko ’ya’ya, ko gonaki saboda ni, da kuma bishara, ");
INSERT INTO hausa_vpl VALUES ("MK10_30","071_10_30","MRK","10","30","30","sa’an nan yă kāsa samun ninkinsu ɗari a zamanin yanzu (na gidaje, da ’yan’uwa mata, da ’yan’uwa maza, da uwaye, da ’ya’ya, da gonaki amma tare da tsanani) a lahira kuma yă sami rai madawwami. ");
INSERT INTO hausa_vpl VALUES ("MK10_31","071_10_31","MRK","10","31","31","Amma da yawa da suke na farko, za su zama na ƙarshe, na ƙarshe kuma, za su zama na farko.” ");
INSERT INTO hausa_vpl VALUES ("MK10_32","071_10_32","MRK","10","32","32","Suna haurawa a hanyarsu zuwa Urushalima ke nan, Yesu yana a gaba, almajiran suna bin sa suna mamaki, waɗanda suke bi kuma suna ji tsoro. Ya sāke kai Sha Biyun nan gefe, ya gaya musu abin da zai faru da shi. ");
INSERT INTO hausa_vpl VALUES ("MK10_33","071_10_33","MRK","10","33","33","Ya ce, “Za mu haura zuwa Urushalima, za a bashe Ɗan Mutum, ga manyan firistoci da malaman dokoki. Za su yi masa hukuncin kisa, a kuma ba da shi ga Al’ummai, ");
INSERT INTO hausa_vpl VALUES ("MK10_34","071_10_34","MRK","10","34","34","waɗanda za su yi masa ba’a, su tofa masa miyau, su yi masa bulala, su kuma kashe shi. Bayan kwana uku kuma yă tashi.” ");
INSERT INTO hausa_vpl VALUES ("MK10_35","071_10_35","MRK","10","35","35","Sai Yaƙub da Yohanna, ’ya’yan Zebedi maza suka zo wurinsa suka ce, “Malam, muna so ka yi mana duk abin da muka roƙa.” ");
INSERT INTO hausa_vpl VALUES ("MK10_36","071_10_36","MRK","10","36","36","Ya tambaye su ya ce, “Me kuke so in yi muku?” ");
INSERT INTO hausa_vpl VALUES ("MK10_37","071_10_37","MRK","10","37","37","Suka amsa suka ce, “Ka bar ɗayanmu yă zauna a damarka, ɗayan kuma a hagunka, a cikin ɗaukakarka.” ");
INSERT INTO hausa_vpl VALUES ("MK10_38","071_10_38","MRK","10","38","38","Yesu ya ce, “Ba ku san abin da kuke roƙo ba. Za ku iya shan kwaf da zan sha, ko a yi muku baftisma da baftismar da aka yi mini?” ");
INSERT INTO hausa_vpl VALUES ("MK10_39","071_10_39","MRK","10","39","39","Suka ce, “Za mu iya.” Yesu ya ce musu, “Za ku sha kwaf da zan sha, a kuma yi muku baftisma da aka yi mini, ");
INSERT INTO hausa_vpl VALUES ("MK10_40","071_10_40","MRK","10","40","40","amma zama a damana ko haguna, ba ni nake ba da izinin ba. Waɗannan wurare na waɗanda aka riga aka shirya musu ne.” ");
INSERT INTO hausa_vpl VALUES ("MK10_41","071_10_41","MRK","10","41","41","Da sauran goman suka ji wannan, sai suka yi fushi da Yaƙub da Yohanna. ");
INSERT INTO hausa_vpl VALUES ("MK10_42","071_10_42","MRK","10","42","42","Yesu ya kira su ya ce musu, “Kun sani waɗanda aka san su da mulkin al’ummai sukan nuna musu iko, hakimansu ma sukan gasa musu iko. ");
INSERT INTO hausa_vpl VALUES ("MK10_43","071_10_43","MRK","10","43","43","Ba haka ya kamata yă zama da ku ba. A maimakon, duk wanda yake so yă zama babba a cikinku, dole yă zama bawanku. ");
INSERT INTO hausa_vpl VALUES ("MK10_44","071_10_44","MRK","10","44","44","Duk wanda kuma yake so yă zama na farko, dole yă zama bawan kowa. ");
INSERT INTO hausa_vpl VALUES ("MK10_45","071_10_45","MRK","10","45","45","Gama ko Ɗan Mutum ma, bai zo domin a bauta masa ba, amma don yă yi bauta, yă kuma ba da ransa fansa saboda mutane da yawa.” ");
INSERT INTO hausa_vpl VALUES ("MK10_46","071_10_46","MRK","10","46","46","Sai suka iso Yeriko. Sa’ad da Yesu da almajiransa tare da taro mai yawa suke barin birnin, wani makaho da ake kira Bartimawus kuwa (wato, “ɗan Timawus”), yana zaune a gefen hanya yana bara. ");
INSERT INTO hausa_vpl VALUES ("MK10_47","071_10_47","MRK","10","47","47","Da ya ji cewa Yesu Banazare ne, sai ya ɗaga murya, yana cewa, “Yesu Ɗan Dawuda, ka yi mini jinƙai!” ");
INSERT INTO hausa_vpl VALUES ("MK10_48","071_10_48","MRK","10","48","48","Mutane da yawa suka kwaɓe shi, suka ce yă yi shiru, amma ya ƙara ɗaga murya yana cewa, “Ɗan Dawuda, ka yi mini jinƙai!” ");
INSERT INTO hausa_vpl VALUES ("MK10_49","071_10_49","MRK","10","49","49","Yesu ya tsaya ya ce, “Ku kira shi.” Sai suka kira makahon suka ce, “Ka yi farin ciki! Tashi tsaye! Yana kiranka.” ");
INSERT INTO hausa_vpl VALUES ("MK10_50","071_10_50","MRK","10","50","50","Ya jefar da mayafinsa waje ɗaya, ya yi wuf, ya zo wurin Yesu. ");
INSERT INTO hausa_vpl VALUES ("MK10_51","071_10_51","MRK","10","51","51","Yesu ya tambaye shi ya ce, “Me kake so in yi maka?” Makahon ya ce, “Rabbi, ina so in sami ganin gari.” ");
INSERT INTO hausa_vpl VALUES ("MK10_52","071_10_52","MRK","10","52","52","Yesu ya ce, “Je ka, bangaskiyarka ta warkar da kai.” Nan da nan, ya sami ganin gari, ya kuma bi Yesu suka tafi. ");
INSERT INTO hausa_vpl VALUES ("MK11_1","071_11_1","MRK","11","1","1","Sa’ad da suka yi kusa da Urushalima, suka zo Betfaji da Betani wajen Dutsen Zaitun, sai Yesu ya aiki biyu daga cikin almajiransa, ");
INSERT INTO hausa_vpl VALUES ("MK11_2","071_11_2","MRK","11","2","2","ya ce musu, “Ku je ƙauyen da yake gaba da ku, da shigarku, za ku tarar da wani ɗan jaki a daure a can, wanda ba wanda ya taɓa hawa. Ku kunce shi ku kawo nan. ");
INSERT INTO hausa_vpl VALUES ("MK11_3","071_11_3","MRK","11","3","3","In wani ya tambaye ku, ‘Don me kuke yin haka?’ Ku gaya masa cewa, ‘Ubangiji yana bukatarsa, zai kuma dawo da shi ba da jimawa ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("MK11_4","071_11_4","MRK","11","4","4","Suka tafi, suka kuwa tarar da wani ɗan jaki a waje, a titi, daure a ƙofar gida. Suna cikin kunce shi ke nan, ");
INSERT INTO hausa_vpl VALUES ("MK11_5","071_11_5","MRK","11","5","5","sai waɗansu mutane da suke tsattsaye a wurin suka ce musu, “Me kuke yi da kuke kunce ɗan jakin nan?” ");
INSERT INTO hausa_vpl VALUES ("MK11_6","071_11_6","MRK","11","6","6","Suka amsa kamar yadda Yesu ya ce su yi. Mutanen kuwa suka ƙyale su. ");
INSERT INTO hausa_vpl VALUES ("MK11_7","071_11_7","MRK","11","7","7","Da suka kawo shi wajen Yesu, sai suka shimfiɗa rigunarsu a bayansa. Yesu kuwa ya hau ya zauna bisansa. ");
INSERT INTO hausa_vpl VALUES ("MK11_8","071_11_8","MRK","11","8","8","Mutane da yawa suka shimfiɗa rigunarsu a kan hanya, waɗansu kuma suka baza rassan itatuwan da suka sara daga gonaki. ");
INSERT INTO hausa_vpl VALUES ("MK11_9","071_11_9","MRK","11","9","9","Waɗanda suka yi gaba, da kuma waɗanda suke biye, duk suka ɗaga murya, suna cewa, “Hosanna!” “Mai albarka ne wanda yake zuwa a cikin sunan Ubangiji!” ");
INSERT INTO hausa_vpl VALUES ("MK11_10","071_11_10","MRK","11","10","10","“Mai albarka ne mulkin nan mai zuwa na mahaifinmu Dawuda!” “Hosanna a can cikin samaniya!” ");
INSERT INTO hausa_vpl VALUES ("MK11_11","071_11_11","MRK","11","11","11","Yesu ya shiga Urushalima ya kuma tafi filin haikali. Ya dudduba kome duka, amma da yake yamma ta yi, sai ya tafi Betani tare da Sha Biyun. ");
INSERT INTO hausa_vpl VALUES ("MK11_12","071_11_12","MRK","11","12","12","Kashegari, da suke barin Betani, Yesu kuwa ya ji yunwa. ");
INSERT INTO hausa_vpl VALUES ("MK11_13","071_11_13","MRK","11","13","13","Da ya hangi wani itacen ɓaure mai ganye, sai ya je domin yă ga ko yana da ’ya’ya. Amma da ya kai can, bai tarar da kome ba sai ganye, domin ba lokacin ’ya’yan ɓaure ba ne. ");
INSERT INTO hausa_vpl VALUES ("MK11_14","071_11_14","MRK","11","14","14","Sai ya ce wa itacen, “Kada kowa yă ƙara cin ’ya’yanka.” Almajiransa kuwa suka ji ya faɗi haka. ");
INSERT INTO hausa_vpl VALUES ("MK11_15","071_11_15","MRK","11","15","15","Da suka kai Urushalima, sai Yesu ya shiga filin haikalin, ya fara korar waɗanda suke saya da sayarwa a can. Ya tutture tebur na masu musayar kuɗi, da kujerun masu sayar da tattabaru, ");
INSERT INTO hausa_vpl VALUES ("MK11_16","071_11_16","MRK","11","16","16","ya kuma hana kowa yă ratsa da a filin haikali ɗauke da kayan ciniki. ");
INSERT INTO hausa_vpl VALUES ("MK11_17","071_11_17","MRK","11","17","17","Da yake koya musu, sai ya ce, “Ashe, ba a rubuce yake ba cewa, ‘Za a kira gidana, gidan addu’a na dukan al’ummai ba’?Amma ga shi kun mai da shi ‘kogon ’yan fashi.’” ");
INSERT INTO hausa_vpl VALUES ("MK11_18","071_11_18","MRK","11","18","18","Manyan firistoci da malaman dokoki suka ji wannan, sai suka fara neman hanyar da za su kashe shi, gama suna jin tsoronsa, saboda dukan taron suna mamakin koyarwarsa. ");
INSERT INTO hausa_vpl VALUES ("MK11_19","071_11_19","MRK","11","19","19","Da yamma ta yi, sai Yesu da almajiransa suka bar garin. ");
INSERT INTO hausa_vpl VALUES ("MK11_20","071_11_20","MRK","11","20","20","Da safe, da suke wucewa, sai suka ga itacen ɓauren nan ya yanƙwane tun daga saiwarsa. ");
INSERT INTO hausa_vpl VALUES ("MK11_21","071_11_21","MRK","11","21","21","Bitrus ya tuna, sai ya ce wa Yesu, “Rabbi, duba! Itacen ɓauren nan da ka la’anta, ya yanƙwane!” ");
INSERT INTO hausa_vpl VALUES ("MK11_22","071_11_22","MRK","11","22","22","Yesu ya amsa ya ce, “Ku gaskata da Allah. ");
INSERT INTO hausa_vpl VALUES ("MK11_23","071_11_23","MRK","11","23","23","Gaskiya nake gaya muku, in wani ya ce wa dutsen nan, ‘Je ka, ka fāɗa cikin teku,’ bai kuwa yi shakka a zuciyarsa ba, amma ya gaskata cewa, abin da ya faɗa zai faru, haka kuwa za a yi masa. ");
INSERT INTO hausa_vpl VALUES ("MK11_24","071_11_24","MRK","11","24","24","Saboda haka, ina faɗa muku, duk abin da kuka roƙa cikin addu’a, ku gaskata kun riga kun karɓa, zai kuwa zama naku. ");
INSERT INTO hausa_vpl VALUES ("MK11_25","071_11_25","MRK","11","25","25","A duk lokacin da kuke tsaye cikin addu’a, in kuna riƙe da wani mutum a zuciyarku, ku gafarta masa, domin Ubanku da yake sama shi ma yă gafarta muku zunubanku.” ");
INSERT INTO hausa_vpl VALUES ("MK11_27","071_11_27","MRK","11","27","27","Suka sāke dawowa cikin Urushalima. Da Yesu yana tafiya a filin haikali, sai manyan firistoci, malaman dokoki da kuma dattawa suka zo wurinsa. ");
INSERT INTO hausa_vpl VALUES ("MK11_28","071_11_28","MRK","11","28","28","Suka tambaye, shi suka ce, “Da wane iko kake yin waɗannan abubuwa? Wa kuma ya ba ka ikon yin wannan?” ");
INSERT INTO hausa_vpl VALUES ("MK11_29","071_11_29","MRK","11","29","29","Yesu ya ce, “Zan yi muku tambaya guda. Ku ba ni amsa, ni kuma zan gaya muku, ko da wane iko nake yin waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("MK11_30","071_11_30","MRK","11","30","30","Baftismar Yohanna, daga sama ce, ko daga mutane? Ku faɗa mini!” ");
INSERT INTO hausa_vpl VALUES ("MK11_31","071_11_31","MRK","11","31","31","Sai suka tattauna a junansu, suka ce, “In muka ce, ‘Daga sama ne,’ zai ce, ‘To, don me ba ku gaskata shi ba?’ ");
INSERT INTO hausa_vpl VALUES ("MK11_32","071_11_32","MRK","11","32","32","In kuma muka ce, ‘Daga wurin mutane ne’; suna jin tsoron mutane, don kowa ya ɗauka cewa, Yohanna, annabi ne na gaskiya.” ");
INSERT INTO hausa_vpl VALUES ("MK11_33","071_11_33","MRK","11","33","33","Saboda haka, suka amsa wa Yesu suka ce, “Ba mu sani ba.” Yesu ya ce, “To, ni ma ba zan gaya muku ko da wane iko nake yin waɗannan abubuwa ba.” ");
INSERT INTO hausa_vpl VALUES ("MK12_1","071_12_1","MRK","12","1","1","Sa’an nan ya fara yi musu magana da misalai ya ce, “Wani mutum ya shuka gonar inabi. Ya kewaye ta da katanga, ya haƙa rami domin matsin inabin, ya kuma gina ɗakin gadi. Sai ya ba wa waɗansu manoma hayar gonar inabin, sa’an nan ya yi tafiya. ");
INSERT INTO hausa_vpl VALUES ("MK12_2","071_12_2","MRK","12","2","2","Da lokacin girbi ya yi, sai ya aiki wani bawa wajen ’yan hayan, don yă karɓo masa ’ya’yan inabin daga wurinsu. ");
INSERT INTO hausa_vpl VALUES ("MK12_3","071_12_3","MRK","12","3","3","Amma suka kama shi, suka yi masa dūka, suka kore shi hannun wofi. ");
INSERT INTO hausa_vpl VALUES ("MK12_4","071_12_4","MRK","12","4","4","Sai ya sāke aikan wani bawa wurinsu, amma suka bugi wannan mutum a kai, suka wulaƙanta shi. ");
INSERT INTO hausa_vpl VALUES ("MK12_5","071_12_5","MRK","12","5","5","Har yanzu ya sāke aikan wani. Wannan kuwa suka kashe. Ya aika waɗansu da yawa; suka bubbuge waɗansu, sauran kuwa suka kashe. ");
INSERT INTO hausa_vpl VALUES ("MK12_6","071_12_6","MRK","12","6","6","“Sauran mutum ɗaya da ya rage ya aika, ɗa, da yake ƙauna. Daga ƙarshe sai ya aike shi, yana cewa, ‘Za su girmama ɗana.’ ");
INSERT INTO hausa_vpl VALUES ("MK12_7","071_12_7","MRK","12","7","7","“Amma ’yan hayan suka ce wa juna, ‘Aha! Wannan shi ne magājin. Ku zo mu kashe shi, gādon kuma yă zama namu.’ ");
INSERT INTO hausa_vpl VALUES ("MK12_8","071_12_8","MRK","12","8","8","Sai suka kama shi suka kashe, suka jefa shi bayan gonar inabin. ");
INSERT INTO hausa_vpl VALUES ("MK12_9","071_12_9","MRK","12","9","9","“To, me, mai gonar inabin zai yi ke nan? Zai zo yă karkashe dukan ’yan hayan nan, ya kuma ba wa waɗansu gonar inabin. ");
INSERT INTO hausa_vpl VALUES ("MK12_10","071_12_10","MRK","12","10","10","Ba ku taɓa karanta wannan Nassi ba, “ ‘Dutsen da magina suka ƙi, shi ne kuwa ya zama dutsen kusurwan gini. ");
INSERT INTO hausa_vpl VALUES ("MK12_11","071_12_11","MRK","12","11","11","Ubangiji ya yi wannan, ya kuma yi kyau a idanunmu’?” ");
INSERT INTO hausa_vpl VALUES ("MK12_12","071_12_12","MRK","12","12","12","Sai manyan Firistoci da malaman dokoki da shugabanni suka nemi hanyar da za su kama shi, domin sun gane ya yi misalin a kansu ne. Amma suka ji tsoron taron, saboda haka suka bar shi suka yi tafiyarsu. ");
INSERT INTO hausa_vpl VALUES ("MK12_13","071_12_13","MRK","12","13","13","Daga baya, sai suka tura waɗansu Farisiyawa da mutanen Hiridus zuwa wurin Yesu, domin su sa masa tarko a cikin maganarsa. ");
INSERT INTO hausa_vpl VALUES ("MK12_14","071_12_14","MRK","12","14","14","Suka zo wurinsa suka ce, “Malam, mun san kai mutum ne mai mutunci. Ba ka bin ra’ayin mutane, don ba ka nuna bambanci. Amma kana koyar da hanyar Allah bisa ga gaskiya. Daidai ne a biya wa Kaisar haraji, ko babu? ");
INSERT INTO hausa_vpl VALUES ("MK12_15","071_12_15","MRK","12","15","15","Mu biya ko kada mu biya?” Amma Yesu ya san munafuncinsu, sai ya yi tambaya ya ce, “Don me kuke ƙoƙarin sa mini tarko? Ku kawo mini dinari in ga.” ");
INSERT INTO hausa_vpl VALUES ("MK12_16","071_12_16","MRK","12","16","16","Suka kawo masa kuɗin, sai ya tambaye, su ya ce, “Hoton wane ne wannan? Kuma rubutun wane ne wannan?” Suka ce, “Na Kaisar.” ");
INSERT INTO hausa_vpl VALUES ("MK12_17","071_12_17","MRK","12","17","17","Sai Yesu ya ce musu, “Ku ba wa Kaisar abin da yake na Kaisar, ku ba wa Allah kuma abin da yake na Allah.” Suka yi mamakinsa ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("MK12_18","071_12_18","MRK","12","18","18","Sa’an nan Sadukiyawa da suke cewa, babu tashin matattu, suka zo masa da tambaya. ");
INSERT INTO hausa_vpl VALUES ("MK12_19","071_12_19","MRK","12","19","19","Suka ce, “Malam, Musa ya rubuta mana cewa, in ɗan’uwan wani mutum ya mutu, ya bar mata babu ’ya’ya, dole mutumin ya auri gwauruwar, yă kuma samo wa ɗan’uwansa ’ya’ya. ");
INSERT INTO hausa_vpl VALUES ("MK12_20","071_12_20","MRK","12","20","20","To, an yi waɗansu ’yan’uwa guda bakwai. Na fari ya yi aure, ya mutu babu ’ya’ya. ");
INSERT INTO hausa_vpl VALUES ("MK12_21","071_12_21","MRK","12","21","21","Na biyun ya auri gwauruwar, sai shi ma ya mutu, babu ’ya’ya. Haka kuma na ukun. ");
INSERT INTO hausa_vpl VALUES ("MK12_22","071_12_22","MRK","12","22","22","A gaskiya, ba ko ɗaya daga cikin bakwai ɗin da ya bar ’ya’ya. Daga ƙarshe, macen ta mutu. ");
INSERT INTO hausa_vpl VALUES ("MK12_23","071_12_23","MRK","12","23","23","To, a tashin matattu, matar wa za tă zama, don duk su bakwai nan sun aure ta?” ");
INSERT INTO hausa_vpl VALUES ("MK12_24","071_12_24","MRK","12","24","24","Yesu ya ce, “Ashe, ba a cikin kuskure kuke ba saboda rashin sanin Nassi, ko ikon Allah? ");
INSERT INTO hausa_vpl VALUES ("MK12_25","071_12_25","MRK","12","25","25","Sa’ad da matattu suka tashi, ba za su yi aure ba, ba kuwa za a ba da su ga aure ba. Za su zama kamar yadda mala’iku suke a cikin sama. ");
INSERT INTO hausa_vpl VALUES ("MK12_26","071_12_26","MRK","12","26","26","Game da tashin matattu kuwa, ashe, ba ku karanta a cikin littafin Musa ba, game da labarin ɗan kurmin nan mai cin wuta da Musa ya gani a jeji, yadda Allah ya yi magana da shi ya ce, ‘Ni ne Allah na Ibrahim, Allah na Ishaku da kuma Allah na Yaƙub’? ");
INSERT INTO hausa_vpl VALUES ("MK12_27","071_12_27","MRK","12","27","27","Shi ba Allah na matattu ba ne, shi Allah na masu rai ne. Kun yi mummunan kuskure!” ");
INSERT INTO hausa_vpl VALUES ("MK12_28","071_12_28","MRK","12","28","28","Wani daga cikin malaman dokoki ya zo ya ji suna muhawwara. Da ya lura cewa Yesu ya amsa musu daidai, sai ya tambaye shi ya ce, “A cikin dukan dokoki, wacce ta fi girma duka?” ");
INSERT INTO hausa_vpl VALUES ("MK12_29","071_12_29","MRK","12","29","29","Yesu ya ce, “Wadda ta fi girma duka, ita ce wannan. ‘Ku saurara, ya Isra’ila, Ubangiji Allahnmu, Ubangiji ɗaya ne. ");
INSERT INTO hausa_vpl VALUES ("MK12_30","071_12_30","MRK","12","30","30","Ka ƙaunaci Ubangiji Allahnka da dukan zuciyarka, da dukan ranka, da dukan hankalinka, da kuma dukan ƙarfinka.’ ");
INSERT INTO hausa_vpl VALUES ("MK12_31","071_12_31","MRK","12","31","31","Na biyun ita ce, ‘Ka ƙaunaci maƙwabcinka kamar kanka.’Ba wata doka da ta fi waɗannan.” ");
INSERT INTO hausa_vpl VALUES ("MK12_32","071_12_32","MRK","12","32","32","Mutumin ya ce, “Malam, ka faɗi daidai. Daidai ne da ka ce, Allah ɗaya ne, babu kuma wani sai shi. ");
INSERT INTO hausa_vpl VALUES ("MK12_33","071_12_33","MRK","12","33","33","Nuna ƙauna ga Allah da dukan zuciyarka, da dukan ganewarka, da dukan ƙarfinka, da kuma nuna ƙauna ga maƙwabcinka kamar kanka, ya fi dukan hadayun ƙonawa da sadakoki.” ");
INSERT INTO hausa_vpl VALUES ("MK12_34","071_12_34","MRK","12","34","34","Da Yesu ya ga ya amsa da hikima, sai ya ce masa, “Ba ka da nisa da mulkin Allah.” Daga lokacin, ba wanda ya yi karambani yin masa wata tambaya. ");
INSERT INTO hausa_vpl VALUES ("MK12_35","071_12_35","MRK","12","35","35","Yayinda Yesu yake koyarwa a filin haikalin, sai ya yi tambaya ya ce, “Yaya malaman dokoki suke cewa Kiristi ɗan Dawuda ne? ");
INSERT INTO hausa_vpl VALUES ("MK12_36","071_12_36","MRK","12","36","36","Dawuda da kansa ya yi magana ta wurin Ruhu Mai Tsarki ya ce, “ ‘Ubangiji ya ce wa Ubangijina, “Zauna a hannun damana sai na sa abokan gābanka a ƙarƙashin sawunka.” ’ ");
INSERT INTO hausa_vpl VALUES ("MK12_37","071_12_37","MRK","12","37","37","Dawuda da kansa ya kira shi ‘Ubangiji.’ To, ta yaya zai zama ɗansa?” Taro mai yawa suka saurare shi da murna. ");
INSERT INTO hausa_vpl VALUES ("MK12_38","071_12_38","MRK","12","38","38","Sa’ad da Yesu yake koyarwa ya ce, “Ku lura da malaman dokoki. Sukan so yin tafiya a manyan riguna, a kuma dinga gaishe su a wuraren kasuwanci. ");
INSERT INTO hausa_vpl VALUES ("MK12_39","071_12_39","MRK","12","39","39","Sukan kuma nemi wuraren zama mafi daraja a majami’u, da kuma wuraren zaman manya a bukukkuwa. ");
INSERT INTO hausa_vpl VALUES ("MK12_40","071_12_40","MRK","12","40","40","Suna ƙwace gidajen gwauraye, kuma don nuna iyawa, sukan yi dogayen addu’o’i. Irin mutanen nan, za su sha hukunci mai tsanani sosai.” ");
INSERT INTO hausa_vpl VALUES ("MK12_41","071_12_41","MRK","12","41","41","Yesu ya zauna ɗaura da inda ake bayarwa, ya kuma dubi yadda taron suke sa kuɗinsu a cikin ɗakunan ajiya haikali. Masu arziki da yawa suka zuba kuɗaɗe masu yawa. ");
INSERT INTO hausa_vpl VALUES ("MK12_42","071_12_42","MRK","12","42","42","Amma wata matalauciya gwauruwa, ta zo ta saka anini biyu, da suka yi daidai da rabin kobo. ");
INSERT INTO hausa_vpl VALUES ("MK12_43","071_12_43","MRK","12","43","43","Yesu ya kira almajiransa wurinsa ya ce, “Gaskiya nake gaya muku, abin da matalauciya gwauruwan nan ta zuba cikin ɗakunan ajiya nan ya fi na sauran dukan. ");
INSERT INTO hausa_vpl VALUES ("MK12_44","071_12_44","MRK","12","44","44","Dukansu sun bayar ne daga cikin arzikinsu; ita kuwa, daga cikin talaucinta, ta ba da kome, duk abin da take da shi na rayuwa.” ");
INSERT INTO hausa_vpl VALUES ("MK13_1","071_13_1","MRK","13","1","1","Da yake barin haikalin, sai ɗaya daga cikin almajiransa ya ce masa, “Malam! Dubi irin manya-manyan duwatsun nan! Ka ga irin gine-ginen nan masu kyau mana!” ");
INSERT INTO hausa_vpl VALUES ("MK13_2","071_13_2","MRK","13","2","2","Yesu ya amsa ya ce, “Ka ga dukan manyan gine-ginen nan? Ba wani dutse a nan, da za a bari kan wani da ba za a rushe ba.” ");
INSERT INTO hausa_vpl VALUES ("MK13_3","071_13_3","MRK","13","3","3","Da Yesu yana zaune a kan Dutsen Zaitun da yake ɗaura da haikali, sai Bitrus, Yaƙub, Yohanna da kuma Andarawus, suka tambaye shi a ɓoye, suka ce, ");
INSERT INTO hausa_vpl VALUES ("MK13_4","071_13_4","MRK","13","4","4","“Ka gaya mana, yaushe waɗannan abubuwa za su faru? Wace alama ce kuma za tă nuna cewa, duk waɗannan suna dab da cikawa?” ");
INSERT INTO hausa_vpl VALUES ("MK13_5","071_13_5","MRK","13","5","5","Sai Yesu ya ce musu, “Ku lura fa kada wani yă ruɗe ku. ");
INSERT INTO hausa_vpl VALUES ("MK13_6","071_13_6","MRK","13","6","6","Da yawa za su zo a cikin sunana, suna cewa, ‘Ni ne shi.’ Za su kuwa ruɗi mutane da yawa. ");
INSERT INTO hausa_vpl VALUES ("MK13_7","071_13_7","MRK","13","7","7","Sa’ad da kuka ji labarun yaƙe-yaƙe da jita-jitar yaƙe-yaƙe, kada hankalinku yă tashi. Dole irin waɗannan abubuwa su faru. Amma ƙarshen tukuna. ");
INSERT INTO hausa_vpl VALUES ("MK13_8","071_13_8","MRK","13","8","8","Al’umma za tă tasar wa al’umma, mulki kuma yă tasar wa mulki. Za a yi girgizar ƙasa a wurare dabam-dabam, a kuma yi yunwa. Waɗannan dai mafarin azabar naƙuda. ");
INSERT INTO hausa_vpl VALUES ("MK13_9","071_13_9","MRK","13","9","9","“Dole ku yi zaman tsaro. Za a ba da ku ga hukuma, a kuma bulale ku a majami’u. Saboda ni kuma, za ku tsaya a gaban gwamnoni da sarakuna, domin ku ba da shaida a gabansu. ");
INSERT INTO hausa_vpl VALUES ("MK13_10","071_13_10","MRK","13","10","10","Dole sai an fara yin wa’azin bishara ga dukan al’ummai. ");
INSERT INTO hausa_vpl VALUES ("MK13_11","071_13_11","MRK","13","11","11","Sa’ad da aka kama ku, aka kuma kai ku don a yi muku shari’a, kada ku damu da abin da za ku faɗa. Sai dai ku faɗi abin da aka ba ku a lokacin. Gama ba ku kuke magana ba, Ruhu Mai Tsarki ne. ");
INSERT INTO hausa_vpl VALUES ("MK13_12","071_13_12","MRK","13","12","12","“Ɗan’uwa zai ba da ɗan’uwa a kashe. Mahaifi zai ba da ɗansa. ’Ya’ya za su tayar wa iyayensu, su kuma sa a kashe su. ");
INSERT INTO hausa_vpl VALUES ("MK13_13","071_13_13","MRK","13","13","13","Dukan mutane za su ƙi ku saboda ni, amma wanda ya tsaya da ƙarfi har ƙarshe, zai sami ceto. ");
INSERT INTO hausa_vpl VALUES ("MK13_14","071_13_14","MRK","13","14","14","“Sa’ad da kuka ga ‘abin ƙyama, mai kawo hallaka’tsaye indabai kamata ba (mai karatu ya gane), to, sai waɗanda suke a Yahudiya su gudu zuwa duwatsu. ");
INSERT INTO hausa_vpl VALUES ("MK13_15","071_13_15","MRK","13","15","15","Kada wani da yake kan rufin gidansa yă sauka, ko yă shiga gida don yă ɗauki wani abu. ");
INSERT INTO hausa_vpl VALUES ("MK13_16","071_13_16","MRK","13","16","16","Kada wani da yake gona kuma yă koma don ɗaukar rigarsa. ");
INSERT INTO hausa_vpl VALUES ("MK13_17","071_13_17","MRK","13","17","17","Kaiton mata masu ciki, da mata masu renon ’ya’ya a waɗancan kwanakin! ");
INSERT INTO hausa_vpl VALUES ("MK13_18","071_13_18","MRK","13","18","18","Ku yi addu’a, kada wannan yă faru a lokacin sanyi. ");
INSERT INTO hausa_vpl VALUES ("MK13_19","071_13_19","MRK","13","19","19","Domin waɗancan kwanakin za su zama kwanaki na baƙin ciki, waɗanda ba a taɓa yin irinsa ba tun farkon halitta, har yă zuwa yanzu, ba kuwa za a sāke yin irinsa ba. ");
INSERT INTO hausa_vpl VALUES ("MK13_20","071_13_20","MRK","13","20","20","“Da ba don Ubangiji ya rage kwanakin nan ba, da ba wani da zai tsira. Amma saboda zaɓaɓɓu waɗanda ya zaɓa, sai ya rage kwanakin. ");
INSERT INTO hausa_vpl VALUES ("MK13_21","071_13_21","MRK","13","21","21","A lokacin nan, in wani ya ce muku, ‘Duba, ga Kiristi nan!’ Ko kuwa, ‘Duba, ga shi can!’ Kada ku gaskata. ");
INSERT INTO hausa_vpl VALUES ("MK13_22","071_13_22","MRK","13","22","22","Gama Kiristi masu yawa na ƙarya, da annabawan ƙarya za su firfito, su kuma aikata manyan alamu da ayyukan banmamaki don su ruɗi har da zaɓaɓɓu ma in zai yiwu. ");
INSERT INTO hausa_vpl VALUES ("MK13_23","071_13_23","MRK","13","23","23","Amma ku kula! Na dai gaya muku kome tun da wuri. ");
INSERT INTO hausa_vpl VALUES ("MK13_24","071_13_24","MRK","13","24","24","“Amma waɗancan kwanaki, bayan baƙin azaban nan, “ ‘rana za tă yi duhu, wata kuma ba zai ba da haskensa ba; ");
INSERT INTO hausa_vpl VALUES ("MK13_25","071_13_25","MRK","13","25","25","taurari za su fāffāɗo daga sararin sama. Za a kuma girgiza manyan abubuwan da suke a sararin sama.’ ");
INSERT INTO hausa_vpl VALUES ("MK13_26","071_13_26","MRK","13","26","26","“Sa’an nan, mutane za su ga Ɗan Mutum yana zuwa cikin gizagizai da iko, da ɗaukaka mai girma. ");
INSERT INTO hausa_vpl VALUES ("MK13_27","071_13_27","MRK","13","27","27","Zai kuma aiko mala’ikunsa su tattaro zaɓaɓɓunsa daga kusurwoyi huɗun nan, daga iyakar duniya har yă zuwa iyakar sama. ");
INSERT INTO hausa_vpl VALUES ("MK13_28","071_13_28","MRK","13","28","28","“To, sai ku yi koyi da itacen ɓaure. Da zarar rassansa suka yi taushi, ganyayensa kuma suka toho, kun san cewa damina ta yi kusa ke nan. ");
INSERT INTO hausa_vpl VALUES ("MK13_29","071_13_29","MRK","13","29","29","Haka ma, in kuka ga waɗannan abubuwa suna faruwa, ku san cewa ya yi kusan zuwa, yana ma dab da bakin ƙofa. ");
INSERT INTO hausa_vpl VALUES ("MK13_30","071_13_30","MRK","13","30","30","Gaskiya nake gaya muku, zamanin nan ba zai shuɗe ba sai duk abubuwan nan sun faru. ");
INSERT INTO hausa_vpl VALUES ("MK13_31","071_13_31","MRK","13","31","31","Sama da ƙasa za su shuɗe, amma kalmomina ba za su taɓa shuɗewa ba. ");
INSERT INTO hausa_vpl VALUES ("MK13_32","071_13_32","MRK","13","32","32","“Game da wannan rana ko sa’a kuwa, ba wanda ya sani, ko mala’ikun da suke sama, ko Ɗan, sai Uban kaɗai. ");
INSERT INTO hausa_vpl VALUES ("MK13_33","071_13_33","MRK","13","33","33","Ku lura fa! Ku zauna a shirye! Don ba ku san lokacin da shi zai zo ba. ");
INSERT INTO hausa_vpl VALUES ("MK13_34","071_13_34","MRK","13","34","34","Yana kama da mutumin da zai yi tafiya. Yakan bar gidansa a hannun bayinsa, kowa da nasa aikin da aka sa shi, yă kuma ce wa wanda yake gadin ƙofa, yă yi tsaro. ");
INSERT INTO hausa_vpl VALUES ("MK13_35","071_13_35","MRK","13","35","35","“Saboda haka, sai ku zauna a shirye, domin ba ku san lokacin da maigidan zai dawo ba, ko da yamma ne, ko da tsakar dare ne, ko lokacin da zakara na cara ne, ko kuma da safe ne. ");
INSERT INTO hausa_vpl VALUES ("MK13_36","071_13_36","MRK","13","36","36","In ya zo kwaram, kada ka bari yă tarar da kai kana barci. ");
INSERT INTO hausa_vpl VALUES ("MK13_37","071_13_37","MRK","13","37","37","Abin da na faɗa muku, na faɗa wa kowa. ‘Ku yi tsaro!’ ” ");
INSERT INTO hausa_vpl VALUES ("MK14_1","071_14_1","MRK","14","1","1","To, saura kwana biyu ne kaɗai a yi Bikin Ƙetarewa da Bikin Burodi Marar Yisti, sai manyan firistoci da malaman dokoki, suka nemi wani dalili su kama Yesu a ɓoye, su kashe. ");
INSERT INTO hausa_vpl VALUES ("MK14_2","071_14_2","MRK","14","2","2","Suka ce, “Ba a lokacin Biki ba, don kada mutane su yi tawaye.” ");
INSERT INTO hausa_vpl VALUES ("MK14_3","071_14_3","MRK","14","3","3","Yayinda yake a Betani, a gidan wani mutumin da ake kira Siman Kuturu, yana cin abinci, sai wata mace ta zo da wani ɗan tulu na turaren alabasta da aka yi da nardi zalla, mai tsadan gaske. Ta fasa tulun, ta kuma zuba turaren a kansa. ");
INSERT INTO hausa_vpl VALUES ("MK14_4","071_14_4","MRK","14","4","4","Waɗansu daga cikin waɗanda suke wurin, suka ji haushi, suka ce wa juna, “Me ya sa za a ɓata turaren nan haka? ");
INSERT INTO hausa_vpl VALUES ("MK14_5","071_14_5","MRK","14","5","5","Da an sayar da shi, ai, da an sami kuɗi fiye da albashi ma’aikaci na shekara guda, a ba wa matalauta. Sai suka tsawata mata da zafi.” ");
INSERT INTO hausa_vpl VALUES ("MK14_6","071_14_6","MRK","14","6","6","Yesu ya ce, “Ku ƙyale ta mana. Don me kuke damunta? Ta yi abu mai kyau a gare ni. ");
INSERT INTO hausa_vpl VALUES ("MK14_7","071_14_7","MRK","14","7","7","Matalauta dai suna tare da ku kullum, za ku kuma iya taimakonsu a duk lokacin da kuke so. Amma ni ba zan kasance da ku kullum ba. ");
INSERT INTO hausa_vpl VALUES ("MK14_8","071_14_8","MRK","14","8","8","Ta yi abin da ta iya yi. Ta zuba turare a jikina kafin lokaci, don shirin jana’izata. ");
INSERT INTO hausa_vpl VALUES ("MK14_9","071_14_9","MRK","14","9","9","Gaskiya nake gaya muku, duk inda aka yi wa’azin bishara ko’ina a duniya, za a faɗi abin da ta yi, domin tunawa da ita.” ");
INSERT INTO hausa_vpl VALUES ("MK14_10","071_14_10","MRK","14","10","10","Sai Yahuda Iskariyot, ɗaya daga cikin Sha Biyun nan, ya je wajen manyan firistoci don yă bashe Yesu a gare su. ");
INSERT INTO hausa_vpl VALUES ("MK14_11","071_14_11","MRK","14","11","11","Suka yi murna da jin haka, suka yi alkawari za su ba shi kuɗi. Don haka, ya fara neman zarafi yă ba da shi. ");
INSERT INTO hausa_vpl VALUES ("MK14_12","071_14_12","MRK","14","12","12","A rana ta fari ta Bikin Burodi Marar Yisti, lokacin da akan yanka ɗan ragon hadayar kafara, bisa ga al’ada ta tunawa da Bikin Ƙetarewa, sai almajiran Yesu suka tambaye shi, suka ce, “Ina kake so mu je mu shirya maka wurin da za ka ci Bikin Ƙetarewa?” ");
INSERT INTO hausa_vpl VALUES ("MK14_13","071_14_13","MRK","14","13","13","Sai ya aiki biyu daga cikin almajiransa ya ce, “Ku shiga cikin birni, za ku sadu da wani ɗauke da tulun ruwa. Ku bi shi. ");
INSERT INTO hausa_vpl VALUES ("MK14_14","071_14_14","MRK","14","14","14","Gidan da ya shiga, ku gaya wa maigidan cewa, ‘Malam yana tambaya, ina ɗakin baƙina, inda zan ci Bikin Ƙetarewa tare da almajiraina?’ ");
INSERT INTO hausa_vpl VALUES ("MK14_15","071_14_15","MRK","14","15","15","Zai nuna muku wani babban ɗakin sama da aka shirya domin baƙi. Ku yi mana shirin a can.” ");
INSERT INTO hausa_vpl VALUES ("MK14_16","071_14_16","MRK","14","16","16","Almajiran suka tafi, suka shiga cikin birnin, suka kuwa tarar da kome kamar yadda Yesu ya faɗa musu. Sai suka shirya Bikin Ƙetarewa. ");
INSERT INTO hausa_vpl VALUES ("MK14_17","071_14_17","MRK","14","17","17","Da yamma ta yi, sai Yesu ya zo tare da Sha Biyun. ");
INSERT INTO hausa_vpl VALUES ("MK14_18","071_14_18","MRK","14","18","18","Yayinda suke cin abinci a tebur, sai ya ce, “Gaskiya nake gaya muku, ɗaya daga cikinku zai bashe ni, wani wanda yake ci tare da ni.” ");
INSERT INTO hausa_vpl VALUES ("MK14_19","071_14_19","MRK","14","19","19","Suka cika da baƙin ciki, da ɗaya-ɗaya suka ce masa, “Tabbatacce, ba ni ba ne, ko?” ");
INSERT INTO hausa_vpl VALUES ("MK14_20","071_14_20","MRK","14","20","20","Ya ce, “Ɗaya daga cikin Sha Biyun ne, wanda yake ci tare da ni a kwano. ");
INSERT INTO hausa_vpl VALUES ("MK14_21","071_14_21","MRK","14","21","21","Ɗan Mutum zai tafi kamar yadda yake a rubuce game da shi, amma kaiton mutumin da ya bashe Ɗan Mutum! Zai fi masa, da ba a haife shi ba.” ");
INSERT INTO hausa_vpl VALUES ("MK14_22","071_14_22","MRK","14","22","22","Yayinda suke cin abinci, sai Yesu ya ɗauki burodi, ya yi godiya, ya kakkarya, ya ba wa almajiransa, yana cewa, “Ku karɓa, wannan jikina ne.” ");
INSERT INTO hausa_vpl VALUES ("MK14_23","071_14_23","MRK","14","23","23","Sai kuma ya ɗauki kwaf ruwan inabi, ya yi godiya, ya kuma miƙa musu, dukansu suka sha daga ciki. ");
INSERT INTO hausa_vpl VALUES ("MK14_24","071_14_24","MRK","14","24","24","Sai ya ce musu, “Wannan jinina ne na alkawari, wanda aka zubar da shi saboda mutane da yawa. ");
INSERT INTO hausa_vpl VALUES ("MK14_25","071_14_25","MRK","14","25","25","Gaskiya nake gaya muku, ‘Ba zan ƙara sha daga ’ya’yan inabi ba, sai ranan nan, da zan sha shi sabo a mulkin Allah.’ ” ");
INSERT INTO hausa_vpl VALUES ("MK14_26","071_14_26","MRK","14","26","26","Da suka rera waƙa, sai suka fita, suka tafi Dutsen Zaitun. ");
INSERT INTO hausa_vpl VALUES ("MK14_27","071_14_27","MRK","14","27","27","Yesu ya ce musu, “Dukanku za ku ja da baya ku bar ni, gama yana a rubuce cewa, “ ‘Zan bugi makiyayin tumaki, tumakin kuwa za su warwatse.’ ");
INSERT INTO hausa_vpl VALUES ("MK14_28","071_14_28","MRK","14","28","28","Amma bayan na tashi, zan sha gabanku zuwa Galili.” ");
INSERT INTO hausa_vpl VALUES ("MK14_29","071_14_29","MRK","14","29","29","Bitrus ya ce, “Ko da duka sun ja da baya suka bar ka, ba zan bar ka ba.” ");
INSERT INTO hausa_vpl VALUES ("MK14_30","071_14_30","MRK","14","30","30","Yesu ya ce, “Gaskiya nake faɗa maka, yau, tabbatacce, a daren nan, kafin zakara yă yi cara sau biyukai da kanka za ka yi mūsun sanina sau uku.” ");
INSERT INTO hausa_vpl VALUES ("MK14_31","071_14_31","MRK","14","31","31","Amma Bitrus ya yi ta nanatawa da ƙarfi ya ce, “Ko da zan mutu tare da kai, ba zan taɓa yin mūsun saninka ba.” Duk sauran ma suka ce haka. ");
INSERT INTO hausa_vpl VALUES ("MK14_32","071_14_32","MRK","14","32","32","Suka tafi wani wurin da ake kira Getsemane, Yesu ya kuma ce wa almajiransa, “Ku zauna a nan, yayinda ni kuwa in yi addu’a.” ");
INSERT INTO hausa_vpl VALUES ("MK14_33","071_14_33","MRK","14","33","33","Ya tafi tare da Bitrus, Yaƙub da kuma Yohanna. Sai ya fara baƙin ciki da damuwa ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("MK14_34","071_14_34","MRK","14","34","34","Sai ya ce musu, “Raina yana cike da baƙin ciki har ma kamar zan mutu. Ku dakata a nan ku yi tsaro.” ");
INSERT INTO hausa_vpl VALUES ("MK14_35","071_14_35","MRK","14","35","35","Sai ya yi gaba kaɗan, ya fāɗi a ƙasa, ya yi addu’a, ya ce in mai yiwuwa ne, a ɗauke masa wannan sa’a. ");
INSERT INTO hausa_vpl VALUES ("MK14_36","071_14_36","MRK","14","36","36","Ya ce, “Ya Abba,Uba, kome mai yiwuwa ne a gare ka. Ka ɗauke mini wannan kwaf. Amma ba abin da nake so ba, sai dai abin da kake so.” ");
INSERT INTO hausa_vpl VALUES ("MK14_37","071_14_37","MRK","14","37","37","Sai ya koma wajen almajiransa, ya same su suna barci. Ya ce wa Bitrus, “Siman, kana barci ne? Ka kāsa yin tsaro na sa’a ɗaya? ");
INSERT INTO hausa_vpl VALUES ("MK14_38","071_14_38","MRK","14","38","38","Ku yi tsaro, ku kuma yi addu’a, domin kada ku fāɗi cikin jarraba. Ruhu yana so, sai dai jiki raunana ne.” ");
INSERT INTO hausa_vpl VALUES ("MK14_39","071_14_39","MRK","14","39","39","Ya sāke komawa, ya maimaita addu’ar da ya yi. ");
INSERT INTO hausa_vpl VALUES ("MK14_40","071_14_40","MRK","14","40","40","Da ya dawo, ya sāke tarar da su suna barci, domin barci ya cika musu ido. Suka rasa abin da za su ce masa. ");
INSERT INTO hausa_vpl VALUES ("MK14_41","071_14_41","MRK","14","41","41","Da ya koma sau na uku, sai ya ce musu, “Har yanzu kuna barci, kuna hutawa ba? Ya isa! Lokaci ya yi. Duba an ba da Ɗan Mutum a hannun masu zunubi. ");
INSERT INTO hausa_vpl VALUES ("MK14_42","071_14_42","MRK","14","42","42","Ku tashi! Mu tafi! Ga mai bashe ni ɗin yana zuwa!” ");
INSERT INTO hausa_vpl VALUES ("MK14_43","071_14_43","MRK","14","43","43","Yana cikin magana ke nan, sai Yahuda, ɗaya daga cikin Sha Biyun ya bayyana. Ya zo tare da taro da suke riƙe da takuba da sanduna. Manyan firistoci da malaman dokoki, da kuma dattawa ne suka turo taron. ");
INSERT INTO hausa_vpl VALUES ("MK14_44","071_14_44","MRK","14","44","44","Mai bashe shi ɗin ya riga ya shirya alama da su cewa, “Wanda na yi wa sumba, shi ne mutumin, ku kama shi, ku riƙe sosai.” ");
INSERT INTO hausa_vpl VALUES ("MK14_45","071_14_45","MRK","14","45","45","Nan da nan Yahuda ya je wurin Yesu ya ce, “Rabbi!” Ya kuma yi masa sumba. ");
INSERT INTO hausa_vpl VALUES ("MK14_46","071_14_46","MRK","14","46","46","Mutanen kuwa suka kama Yesu, suka riƙe shi. ");
INSERT INTO hausa_vpl VALUES ("MK14_47","071_14_47","MRK","14","47","47","Sai wani cikin waɗanda suke tsattsaye kusa ya zāre takobinsa, ya sare kunnen bawan babban firist. ");
INSERT INTO hausa_vpl VALUES ("MK14_48","071_14_48","MRK","14","48","48","Yesu ya ce, “Ina jagoran wani tawaye ne da kuka fito da takuba da kuma sanduna domin ku kama ni? ");
INSERT INTO hausa_vpl VALUES ("MK14_49","071_14_49","MRK","14","49","49","Kowace rana ina tare da ku, ina koyarwa a filin haikali, ba ku kama ni ba. Amma dole a cika Nassi.” ");
INSERT INTO hausa_vpl VALUES ("MK14_50","071_14_50","MRK","14","50","50","Sai kowa ya yashe shi ya gudu. ");
INSERT INTO hausa_vpl VALUES ("MK14_51","071_14_51","MRK","14","51","51","Wani saurayin da ba ya sanye da kome sai rigar lilin, yana bin Yesu. Da suka yi ƙoƙarin kama shi, ");
INSERT INTO hausa_vpl VALUES ("MK14_52","071_14_52","MRK","14","52","52","sai ya gudu ya bar rigarsa, ya gudu tsirara. ");
INSERT INTO hausa_vpl VALUES ("MK14_53","071_14_53","MRK","14","53","53","Suka kai Yesu wajen babban firist, sai dukan manyan firistoci, dattawa da kuma malaman dokoki suka taru. ");
INSERT INTO hausa_vpl VALUES ("MK14_54","071_14_54","MRK","14","54","54","Bitrus ya bi shi daga nesa, har cikin filin gidan babban firist. A can, ya zauna tare da masu gadi, yana jin ɗumin wuta. ");
INSERT INTO hausa_vpl VALUES ("MK14_55","071_14_55","MRK","14","55","55","Manyan firistoci da dukan ’yan Majalisa, suka shiga neman shaidar laifin da za a tabbatar a kan Yesu, domin su kashe shi. Amma ba su sami ko ɗaya ba. ");
INSERT INTO hausa_vpl VALUES ("MK14_56","071_14_56","MRK","14","56","56","Da yawa suka ba da shaidar ƙarya a kansa, amma shaidarsu ba tă zo ɗaya ba. ");
INSERT INTO hausa_vpl VALUES ("MK14_57","071_14_57","MRK","14","57","57","Sai waɗansu suka miƙe tsaye, suka ba da wannan shaida ƙarya a kansa, suka ce, ");
INSERT INTO hausa_vpl VALUES ("MK14_58","071_14_58","MRK","14","58","58","“Mun ji shi ya ce, ‘Zan rushe wannan haikali da mutum ya gina, cikin kwana uku, in sāke gina wani wanda ba ginin mutum ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("MK14_59","071_14_59","MRK","14","59","59","Duk da haka ma, shaidarsu ba tă zo ɗaya ba. ");
INSERT INTO hausa_vpl VALUES ("MK14_60","071_14_60","MRK","14","60","60","Sai babban firist ya tashi a gabansu, ya tambayi Yesu ya ce, “Ba za ka amsa ba? Wane shaida ke nan waɗannan mutane suke kawowa a kanka?” ");
INSERT INTO hausa_vpl VALUES ("MK14_61","071_14_61","MRK","14","61","61","Amma Yesu ya yi shiru, bai kuwa amsa ba. Babban firist ya sāke tambayarsa ya ce, “Kai ne Kiristi, Ɗan Mai Albarka?” ");
INSERT INTO hausa_vpl VALUES ("MK14_62","071_14_62","MRK","14","62","62","Yesu ya ce, “Ni ne. Za ku kuwa ga Ɗan Mutum yana zaune a hannun dama na Mai Iko, yana kuma zuwa a cikin gizagizan sama.” ");
INSERT INTO hausa_vpl VALUES ("MK14_63","071_14_63","MRK","14","63","63","Babban firist ya yage tufafinsa, ya yi ce, “Ina dalilin neman waɗansu shaidu kuma? ");
INSERT INTO hausa_vpl VALUES ("MK14_64","071_14_64","MRK","14","64","64","Kun dai ji saɓon. Me kuka gani?” Duka suka yanke masa hukuncin kisa. ");
INSERT INTO hausa_vpl VALUES ("MK14_65","071_14_65","MRK","14","65","65","Sai waɗansu suka fara tattofa masa miyau, suka rufe masa idanu, suka bubbuge shi da hannuwansu, suka ce, “Yi annabci!” Masu gadin kuma suka ɗauke shi, suka yi masa duka. ");
INSERT INTO hausa_vpl VALUES ("MK14_66","071_14_66","MRK","14","66","66","Yayinda Bitrus yake ƙasa a filin gidan, sai wata yarinya, baiwa, ɗaya daga cikin ma’aikatan babban firist, ta zo can. ");
INSERT INTO hausa_vpl VALUES ("MK14_67","071_14_67","MRK","14","67","67","Da ta ga Bitrus yana jin ɗumi, sai ta dube shi da kyau. Ta ce, “Kai ma kana tare da Yesu, Banazare.” ");
INSERT INTO hausa_vpl VALUES ("MK14_68","071_14_68","MRK","14","68","68","Amma ya yi mūsu ya ce, “Ban san abin da kike magana ba, balle ma in fahimce ki.” Sai ya fita zuwa zaure. ");
INSERT INTO hausa_vpl VALUES ("MK14_69","071_14_69","MRK","14","69","69","Da baiwar ta gan shi a can, sai ta sāke gaya wa waɗanda suke tsattsaye a wurin, ta ce, “Wannan mutum yana ɗaya daga cikinsu.” ");
INSERT INTO hausa_vpl VALUES ("MK14_70","071_14_70","MRK","14","70","70","Sai ya sāke yin musu. Bayan ɗan lokaci kaɗan, sai waɗanda suke tsattsaye kusa suka ce wa Bitrus, “Lalle, kana ɗaya daga cikinsu, gama kai mutumin Galili ne.” ");
INSERT INTO hausa_vpl VALUES ("MK14_71","071_14_71","MRK","14","71","71","Sai ya fara la’antar kansa, yana rantsuwa musu, yana cewa, “Ban san wannan mutumin da kuke magana a kai ba.” ");
INSERT INTO hausa_vpl VALUES ("MK14_72","071_14_72","MRK","14","72","72","Nan da nan zakara ya yi cara sau na biyu. Sai Bitrus ya tuna da maganar da Yesu ya yi masa cewa, “Kafin zakara yă yi cara sau biyu,za ka yi mūsun sanina sau uku.” Sai ya fashe da kuka. ");
INSERT INTO hausa_vpl VALUES ("MK15_1","071_15_1","MRK","15","1","1","Da sassafe, sai manyan firistoci da dattawa, da malaman dokoki, da dukan Majalisa, suka yanke shawara. Suka daure Yesu, suka kai shi, suka miƙa shi ga Bilatus. ");
INSERT INTO hausa_vpl VALUES ("MK15_2","071_15_2","MRK","15","2","2","Bilatus ya yi tambaya ya ce, “Kai ne Sarkin Yahudawa?” Yesu ya amsa ya ce, “I, haka yake, kamar yadda ka faɗa.” ");
INSERT INTO hausa_vpl VALUES ("MK15_3","071_15_3","MRK","15","3","3","Manyan firistoci suka zarge shi a kan abubuwa da yawa. ");
INSERT INTO hausa_vpl VALUES ("MK15_4","071_15_4","MRK","15","4","4","Don haka Bilatus ya sāke tambayarsa ya ce, “Ba za ka amsa ba? Dubi abubuwa da yawa da suke zarginka da su.” ");
INSERT INTO hausa_vpl VALUES ("MK15_5","071_15_5","MRK","15","5","5","Amma har yanzu, Yesu bai ba da amsa ba, Bilatus ya yi mamaki. ");
INSERT INTO hausa_vpl VALUES ("MK15_6","071_15_6","MRK","15","6","6","Yanzu fa, al’ada ce a lokacin Bikin, a saki ɗan kurkuku guda wanda mutane suka roƙa. ");
INSERT INTO hausa_vpl VALUES ("MK15_7","071_15_7","MRK","15","7","7","Wani mutumin da ake kira Barabbas, yana a kurkuku, tare da waɗansu ’yan tawaye da suka yi kisankai a lokacin wani hargitsi. ");
INSERT INTO hausa_vpl VALUES ("MK15_8","071_15_8","MRK","15","8","8","Taron suka matso, suka ce roƙi Bilatus yă yi musu abin da ya saba yi. ");
INSERT INTO hausa_vpl VALUES ("MK15_9","071_15_9","MRK","15","9","9","Bilatus ya yi tambaya ya ce, “Kuna so in sakar muku Sarkin Yahudawa?” ");
INSERT INTO hausa_vpl VALUES ("MK15_10","071_15_10","MRK","15","10","10","Don ya san saboda sonkai ne manyan firistoci suka ba da Yesu a gare shi. ");
INSERT INTO hausa_vpl VALUES ("MK15_11","071_15_11","MRK","15","11","11","Amma manyan firistoci suka zuga taron su sa a saki Barabbas, a maimakon Yesu. ");
INSERT INTO hausa_vpl VALUES ("MK15_12","071_15_12","MRK","15","12","12","Bilatus ya tambaye su ya ce, “To, me zan yi da wanda kuke ce da shi, sarkin Yahudawa?” ");
INSERT INTO hausa_vpl VALUES ("MK15_13","071_15_13","MRK","15","13","13","Suka yi ihu, suka ce, “A gicciye shi!” ");
INSERT INTO hausa_vpl VALUES ("MK15_14","071_15_14","MRK","15","14","14","Bilatus ya yi tambaya ya ce, “Don me? Wane laifi ya yi?” Amma suka ƙara yin ihu suna cewa, “A gicciye shi!” ");
INSERT INTO hausa_vpl VALUES ("MK15_15","071_15_15","MRK","15","15","15","Don son yă faranta wa taron rai, sai Bilatus ya sakar musu Barabbas. Ya sa aka yi wa Yesu bulala, sa’an nan ya ba da shi a gicciye. ");
INSERT INTO hausa_vpl VALUES ("MK15_16","071_15_16","MRK","15","16","16","Sojojin suka tafi da Yesu cikin fadar gwamna (wato, Firetoriyum), suka kira dukan kamfanin sojoji wuri ɗaya. ");
INSERT INTO hausa_vpl VALUES ("MK15_17","071_15_17","MRK","15","17","17","Suka sa masa wata riga mai ruwan shunayya, suka kuma tuƙa rawanin ƙaya suka sa masa. ");
INSERT INTO hausa_vpl VALUES ("MK15_18","071_15_18","MRK","15","18","18","Sai suka fara ce masa, “Ranka yă daɗe sarkin Yahudawa!” ");
INSERT INTO hausa_vpl VALUES ("MK15_19","071_15_19","MRK","15","19","19","Suka dinga bugunsa a kā da sanda, suka tattofa masa miyau. Suka durƙusa suka yi masa bangirma na ba’a. ");
INSERT INTO hausa_vpl VALUES ("MK15_20","071_15_20","MRK","15","20","20","Bayan da suka gama yin masa ba’a, suka tuɓe rigar mai ruwan shunayyar, suka sa masa nasa tufafi. Sai suka tafi da shi don a gicciye shi. ");
INSERT INTO hausa_vpl VALUES ("MK15_21","071_15_21","MRK","15","21","21","Sai ga wani mutum daga Sairin da ake kira Siman, mahaifin Alekzanda da Rufus, yana wucewa kan hanyarsa daga ƙauye. Sai suka tilasta shi yă ɗauki gicciyen. ");
INSERT INTO hausa_vpl VALUES ("MK15_22","071_15_22","MRK","15","22","22","Suka kawo Yesu a wurin da ake kira Golgota (wanda yake nufin Wurin Ƙoƙon Kai). ");
INSERT INTO hausa_vpl VALUES ("MK15_23","071_15_23","MRK","15","23","23","Sai suka miƙa masa ruwan inabi gauraye da mur, don yă rage zafi, amma bai sha ba. ");
INSERT INTO hausa_vpl VALUES ("MK15_24","071_15_24","MRK","15","24","24","Sai suka gicciye shi. Suka rarraba tufafinsa, suka jefa ƙuri’a a kansu don su ga abin da kowa zai samu. ");
INSERT INTO hausa_vpl VALUES ("MK15_25","071_15_25","MRK","15","25","25","Sa’a ta uku na safe ce kuwa aka gicciye shi. ");
INSERT INTO hausa_vpl VALUES ("MK15_26","071_15_26","MRK","15","26","26","Akwai rubutu na zarginsa, da ya ce, Sarkin Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("MK15_27","071_15_27","MRK","15","27","27","Suka gicciye ’yan fashi biyu tare da shi, ɗaya a damansa, ɗayan kuma a hagunsa. ");
INSERT INTO hausa_vpl VALUES ("MK15_29","071_15_29","MRK","15","29","29","Masu wucewa suka zazzage shi. Suka kaɗa kai suna cewa, “To, kai da za ka rushe haikali ka kuma gina shi a kwana uku, ");
INSERT INTO hausa_vpl VALUES ("MK15_30","071_15_30","MRK","15","30","30","sai ka sauko daga gicciyen, ka ceci kanka!” ");
INSERT INTO hausa_vpl VALUES ("MK15_31","071_15_31","MRK","15","31","31","Haka kuma, manyan firistoci da malaman dokoki suka yi masa ba’a a junansu, suna cewa, “Ya ceci waɗansu, amma ya kāsa ceton kansa! ");
INSERT INTO hausa_vpl VALUES ("MK15_32","071_15_32","MRK","15","32","32","Bari wannan Kiristi, wannan Sarkin Isra’ila, yă sauko yanzu daga gicciye, don mu ga mu kuma gaskata.” Waɗanda aka gicciye tare da shi ma suka zazzage shi. ");
INSERT INTO hausa_vpl VALUES ("MK15_33","071_15_33","MRK","15","33","33","Daga sa’a ta shida har zuwa sa’a ta tara na rana, duhu ya rufe dukan ƙasar. ");
INSERT INTO hausa_vpl VALUES ("MK15_34","071_15_34","MRK","15","34","34","A daidai sa’a ta tara na rana, sai Yesu ya ɗaga murya da ƙarfi ya ce, “Eloi, Eloi, lama sabaktani?” (Wato, “Ya Allahna, ya Allahna, don me ka yashe ni?”). ");
INSERT INTO hausa_vpl VALUES ("MK15_35","071_15_35","MRK","15","35","35","Da waɗansu cikin waɗanda suke tsattsaye kusa da wurin suka ji haka, suka ce, “Ku saurara, yana kiran Iliya.” ");
INSERT INTO hausa_vpl VALUES ("MK15_36","071_15_36","MRK","15","36","36","Wani mutum ya ruga ya je ya jiƙo soso da ruwan tsami, ya soka a sanda ya miƙa wa Yesu yă sha. Ya ce, “Ku ƙyale shi. Bari mu ga ko Iliya zai zo yă saukar da shi.” ");
INSERT INTO hausa_vpl VALUES ("MK15_37","071_15_37","MRK","15","37","37","Da murya mai ƙarfi, Yesu ya ja numfashinsa na ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("MK15_38","071_15_38","MRK","15","38","38","Labulen haikali kuwa ya yage kashi biyu, daga sama har ƙasa. ");
INSERT INTO hausa_vpl VALUES ("MK15_39","071_15_39","MRK","15","39","39","Da jarumin da yake tsaye a gaban Yesu ya ji muryarsa, ya kuma ga yadda ya mutu, sai ya ce, “Gaskiya, wannan mutum Ɗan Allah ne!” ");
INSERT INTO hausa_vpl VALUES ("MK15_40","071_15_40","MRK","15","40","40","Waɗansu mata suna kallo daga nesa. A cikinsu kuwa akwai Maryamu Magdalin, Maryamu mahaifiyar Yaƙub ƙarami da Yusuf, da kuma Salome. ");
INSERT INTO hausa_vpl VALUES ("MK15_41","071_15_41","MRK","15","41","41","A Galili waɗannan mata ne suka riƙa bin sa suna yin masa hidima. Waɗansu mata da yawa da suka zo tare da shi daga Urushalima, su ma suna nan a can. ");
INSERT INTO hausa_vpl VALUES ("MK15_42","071_15_42","MRK","15","42","42","Ranar kuwa ita ce ranar Shirye-shirye (wato, ana kashegari Asabbaci). Saboda haka, da yamma ta yi, sai ");
INSERT INTO hausa_vpl VALUES ("MK15_43","071_15_43","MRK","15","43","43","Yusuf daga Arimateya, wani sanannen ɗan Majalisa, wanda dā ma yake jiran zuwan mulkin Allah, ya je wajen Bilatus ba tsoro, ya roƙa a ba shi jikin Yesu. ");
INSERT INTO hausa_vpl VALUES ("MK15_44","071_15_44","MRK","15","44","44","Bilatus ya yi mamaki da ya ji cewa Yesu ya riga ya mutu. Sai ya kira jarumin ya tambaye shi ko Yesu ya riga ya mutu. ");
INSERT INTO hausa_vpl VALUES ("MK15_45","071_15_45","MRK","15","45","45","Da ya ji ta bakin jarumin cewa haka ne, sai ya ba wa Yusuf jikin. ");
INSERT INTO hausa_vpl VALUES ("MK15_46","071_15_46","MRK","15","46","46","Sai Yusuf ya kawo zanen lilin, ya saukar da jikin, ya nannaɗe shi da lilin ɗin, sa’an nan ya sa shi a kabarin da aka fafe a cikin dutse. Sai ya gungura wani dutse ya rufe bakin kabarin. ");
INSERT INTO hausa_vpl VALUES ("MK15_47","071_15_47","MRK","15","47","47","Maryamu Magdalin da Maryamu uwar Yusuf sun ga inda aka kwantar da shi. ");
INSERT INTO hausa_vpl VALUES ("MK16_1","071_16_1","MRK","16","1","1","Da Asabbaci ya wuce, sai Maryamu Magdalin, Maryamu mahaifiyar Yaƙub, da kuma Salome suka sayi kayan ƙanshi domin su je su shafa wa jikin Yesu. ");
INSERT INTO hausa_vpl VALUES ("MK16_2","071_16_2","MRK","16","2","2","A ranar farko ta mako, da sassafe, bayan fitowar rana, suna kan hanyarsu zuwa kabarin ke nan, ");
INSERT INTO hausa_vpl VALUES ("MK16_3","071_16_3","MRK","16","3","3","sai suka tambaye juna suka ce, “Wane ne zai gungura mana dutsen daga bakin kabarin?” ");
INSERT INTO hausa_vpl VALUES ("MK16_4","071_16_4","MRK","16","4","4","Amma da suka ɗaga kai, sai suka ga cewa, an riga an gungura dutsen. Dutsen kuwa babba ne. ");
INSERT INTO hausa_vpl VALUES ("MK16_5","071_16_5","MRK","16","5","5","Da suna shiga cikin kabarin, sai suka ga wani saurayi sanye da farar riga, yana zaune a hannun dama, sai suka firgita. ");
INSERT INTO hausa_vpl VALUES ("MK16_6","071_16_6","MRK","16","6","6","Ya ce, “Kada ku firgita. Kuna neman Yesu Banazare wanda aka gicciye ne. Ya tashi! Ba ya nan. Ku dubi inda aka kwantar da shi. ");
INSERT INTO hausa_vpl VALUES ("MK16_7","071_16_7","MRK","16","7","7","Amma ku tafi ku gaya wa almajiransa da kuma Bitrus cewa, ‘Ya sha gabanku zuwa Galili. Can za ku gan shi, kamar yadda ya faɗa muku.’ ” ");
INSERT INTO hausa_vpl VALUES ("MK16_8","071_16_8","MRK","16","8","8","Da rawan jiki da kuma ruɗewa, matan suka fita a guje daga kabarin. Ba su kuwa gaya wa kowa ba, don suna tsoro. ");
INSERT INTO hausa_vpl VALUES ("MK16_9","071_16_9","MRK","16","9","9","Da Yesu ya tashi daga matattu da safe, a ranar farko ta mako, ya fara bayyana ga Maryamu Magdalin, wadda ya fitar da aljanu bakwai daga cikinta. ");
INSERT INTO hausa_vpl VALUES ("MK16_10","071_16_10","MRK","16","10","10","Ta je ta gaya wa waɗanda dā suke tare da shi, waɗanda kuma suke makoki da kuka. ");
INSERT INTO hausa_vpl VALUES ("MK16_11","071_16_11","MRK","16","11","11","Da suka ji cewa Yesu yana da rai, har ma ta gan shi, ba su gaskata ba. ");
INSERT INTO hausa_vpl VALUES ("MK16_12","071_16_12","MRK","16","12","12","Daga baya Yesu ya bayyana a wani kamanni dabam ga biyunsu, yayinda suke tafiya ƙauye. ");
INSERT INTO hausa_vpl VALUES ("MK16_13","071_16_13","MRK","16","13","13","Waɗannan kuwa suka koma suka shaida wa sauran, amma su ma ba su gaskata ba. ");
INSERT INTO hausa_vpl VALUES ("MK16_14","071_16_14","MRK","16","14","14","Bayan haka, Yesu ya bayyana ga Sha Ɗayan, yayinda suke cin abinci. Ya tsawata musu a kan rashin bangaskiyarsu, da yadda suka ƙi gaskata waɗanda suka gan shi bayan ya tashi. ");
INSERT INTO hausa_vpl VALUES ("MK16_15","071_16_15","MRK","16","15","15","Ya ce, musu, “Ku tafi cikin dukan duniya, ku yi wa’azin bishara ga dukan halitta. ");
INSERT INTO hausa_vpl VALUES ("MK16_16","071_16_16","MRK","16","16","16","Duk wanda ya gaskata, aka kuma yi masa baftisma, zai sami ceto. Amma duk wanda bai gaskata ba kuwa, zai hallaka. ");
INSERT INTO hausa_vpl VALUES ("MK16_17","071_16_17","MRK","16","17","17","Waɗannan alamu za su kasance tare da waɗanda suka gaskata. A cikin sunana za su fitar da aljanu, za su yi magana da sababbin harsuna. ");
INSERT INTO hausa_vpl VALUES ("MK16_18","071_16_18","MRK","16","18","18","Za su ɗauki macizai da hannuwansu. In kuwa suka sha mugun dafi, ba zai cuce su ba ko kaɗan. Za su ɗibiya hannuwansu a kan marasa lafiya, su kuwa warke.” ");
INSERT INTO hausa_vpl VALUES ("MK16_19","071_16_19","MRK","16","19","19","Bayan Ubangiji Yesu ya yi musu magana, sai aka ɗauke shi zuwa sama, ya kuma zauna a hannun dama na Allah. ");
INSERT INTO hausa_vpl VALUES ("MK16_20","071_16_20","MRK","16","20","20","Sai almajiran suka fita, suka yi wa’azi ko’ina. Ubangiji kuwa ya yi aiki tare da su, ya tabbatar da maganarsa ta wurin alamu da suke biye da maganar.");
INSERT INTO hausa_vpl VALUES ("LK1_1","072_1_1","LUK","1","1","1","Mutane da yawa sun ɗau niyyar rubuta labarin abubuwan da aka cika a cikinmu, ");
INSERT INTO hausa_vpl VALUES ("LK1_2","072_1_2","LUK","1","2","2","kamar yadda muka karɓe su daga waɗanda tun farko shaidu ne da kuma masu hidimar bishara. ");
INSERT INTO hausa_vpl VALUES ("LK1_3","072_1_3","LUK","1","3","3","Saboda haka, da yake ni da kaina na binciko kome a hankali daga farko, na ga ya yi kyau in rubuta maka labarin dalla-dalla, ya mafifici Tiyofilus, ");
INSERT INTO hausa_vpl VALUES ("LK1_4","072_1_4","LUK","1","4","4","don ka san tabbacin abubuwan da aka koyar da kai. ");
INSERT INTO hausa_vpl VALUES ("LK1_5","072_1_5","LUK","1","5","5","A lokacin da Hiridus ne yake sarautar Yahudiya, an yi wani firist mai suna Zakariya, na sashin firistoci gidan Abiya. Matarsa Elizabet ma ’yar zuriyar Haruna ce. ");
INSERT INTO hausa_vpl VALUES ("LK1_6","072_1_6","LUK","1","6","6","Dukansu biyu kuwa masu adalci ne a gaban Allah, suna kuma bin umarnan Ubangiji da farillansa duka da halin rashin zargi. ");
INSERT INTO hausa_vpl VALUES ("LK1_7","072_1_7","LUK","1","7","7","Sai dai ba su da ’ya’ya, domin Elizabet bakararriya ce; kuma dukansu biyu sun tsufa. ");
INSERT INTO hausa_vpl VALUES ("LK1_8","072_1_8","LUK","1","8","8","Wata rana da lokacin aikin firistoci na sashen Zakariya na yin hidima ya kewayo, yana kuma cikin hidimarsa ta firist a gaban Allah, ");
INSERT INTO hausa_vpl VALUES ("LK1_9","072_1_9","LUK","1","9","9","sai aka zaɓe shi ta wurin ƙuri’a, bisa ga al’adar aikin firist, yă shiga haikalin Ubangiji yă ƙone turare. ");
INSERT INTO hausa_vpl VALUES ("LK1_10","072_1_10","LUK","1","10","10","Da lokacin ƙone turare ya yi, duk taron masu sujada suna a waje suna addu’a. ");
INSERT INTO hausa_vpl VALUES ("LK1_11","072_1_11","LUK","1","11","11","Sai mala’ikan Ubangiji ya bayyana gare shi, tsaye a dama da bagaden turare. ");
INSERT INTO hausa_vpl VALUES ("LK1_12","072_1_12","LUK","1","12","12","Da Zakariya ya gan shi sai ya firgita, tsoro kuma ya kama shi. ");
INSERT INTO hausa_vpl VALUES ("LK1_13","072_1_13","LUK","1","13","13","Amma mala’ikan ya ce masa, “Kada ka ji tsoro, Zakariya; an ji addu’arka. Matarka Elizabet za tă haifa maka ɗa, za ka kuma ba shi suna Yohanna. ");
INSERT INTO hausa_vpl VALUES ("LK1_14","072_1_14","LUK","1","14","14","Zai zama abin murna da farin ciki a gare ka, mutane da yawa kuwa za su yi murna don haihuwarsa, ");
INSERT INTO hausa_vpl VALUES ("LK1_15","072_1_15","LUK","1","15","15","gama zai zama mai girma a gaban Ubangiji. Ba kuwa zai taɓa shan ruwan inabi ko wani abu mai sa maye ba. Zai cika da Ruhu Mai Tsarki tun haihuwa. ");
INSERT INTO hausa_vpl VALUES ("LK1_16","072_1_16","LUK","1","16","16","Shi ne zai juye mutanen Isra’ila da yawa zuwa wurin Ubangiji Allahnsu. ");
INSERT INTO hausa_vpl VALUES ("LK1_17","072_1_17","LUK","1","17","17","Zai sha gaban Ubangiji, a ruhu da kuma iko irin na Iliya, domin yă juye zukatan iyaye ga ’ya’yansu, marasa biyayya kuma ga zama masu biyayya don yă kintsa mutane su zama shiryayyu domin Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("LK1_18","072_1_18","LUK","1","18","18","Sai Zakariya ya tambayi mala’ikan ya ce, “Yaya zan tabbatar da wannan? Ga ni tsoho, matana kuma ta kwana biyu.” ");
INSERT INTO hausa_vpl VALUES ("LK1_19","072_1_19","LUK","1","19","19","Mala’ikan ya ce, “Ni ne Jibra’ilu. Ina tsaya a gaban Allah, an kuma aiko ni in yi maka magana, in kuma faɗa maka wannan labari mai daɗi. ");
INSERT INTO hausa_vpl VALUES ("LK1_20","072_1_20","LUK","1","20","20","Yanzu za ka zama bebe, ba za ka ƙara iya magana ba sai ranar da wannan magana ta cika, saboda ba ka gaskata da kalmomina waɗanda za su zama gaskiya a daidai lokacinsu ba.” ");
INSERT INTO hausa_vpl VALUES ("LK1_21","072_1_21","LUK","1","21","21","Ana cikin haka, mutane suna jiran Zakariya, suna kuma mamaki me ya sa ya daɗe haka a cikin haikali. ");
INSERT INTO hausa_vpl VALUES ("LK1_22","072_1_22","LUK","1","22","22","Da ya fito, bai iya yin musu magana ba. Sai suka gane, ya ga wahayi ne a haikali, domin ya dinga yin musu alamu, amma ya kāsa yin magana. ");
INSERT INTO hausa_vpl VALUES ("LK1_23","072_1_23","LUK","1","23","23","Da lokacin hidimarsa ya cika, sai ya koma gida. ");
INSERT INTO hausa_vpl VALUES ("LK1_24","072_1_24","LUK","1","24","24","Bayan wannan, matarsa Elizabet ta yi ciki, ta kuma riƙa ɓuya har wata biyar. ");
INSERT INTO hausa_vpl VALUES ("LK1_25","072_1_25","LUK","1","25","25","Sai ta ce, “Ubangiji ne ya yi mini wannan. A waɗannan kwanaki ya nuna tagomashinsa ya kuma kawar mini da kunya a cikin mutane.” ");
INSERT INTO hausa_vpl VALUES ("LK1_26","072_1_26","LUK","1","26","26","A wata na shida, sai Allah ya aiki mala’ika Jibra’ilu zuwa Nazaret, wani gari a Galili, ");
INSERT INTO hausa_vpl VALUES ("LK1_27","072_1_27","LUK","1","27","27","gun wata budurwar da aka yi alkawarin aurenta ga wani mutum mai suna Yusuf daga zuriyar Dawuda. Sunan budurwar Maryamu. ");
INSERT INTO hausa_vpl VALUES ("LK1_28","072_1_28","LUK","1","28","28","Mala’ikan ya je wurinta ya ce, “A gaishe ki, ya ke da kika sami tagomashi ƙwarai! Ubangiji yana tare da ke.” ");
INSERT INTO hausa_vpl VALUES ("LK1_29","072_1_29","LUK","1","29","29","Maryamu ta damu ƙwarai da kalmominsa, tana tunani wace irin gaisuwa ce haka? ");
INSERT INTO hausa_vpl VALUES ("LK1_30","072_1_30","LUK","1","30","30","Amma mala’ikan ya ce mata, “Kada ki ji tsoro, Maryamu, kin sami tagomashi a wurin Allah. ");
INSERT INTO hausa_vpl VALUES ("LK1_31","072_1_31","LUK","1","31","31","Ga shi za ki yi ciki ki kuma haifi ɗa, za ki kuma ba shi suna Yesu. ");
INSERT INTO hausa_vpl VALUES ("LK1_32","072_1_32","LUK","1","32","32","Zai zama mai girma, za a kuma kira shi Ɗan Maɗaukaki. Ubangiji Allah zai ba shi gadon sarautar kakansa Dawuda, ");
INSERT INTO hausa_vpl VALUES ("LK1_33","072_1_33","LUK","1","33","33","zai yi mulkin gidan Yaƙub har abada, mulkinsa kuma ba zai taɓa ƙare ba.” ");
INSERT INTO hausa_vpl VALUES ("LK1_34","072_1_34","LUK","1","34","34","Maryamu ta tambayi mala’ikan ta ce, “Yaya wannan zai yiwu, da yake ni budurwa ce?” ");
INSERT INTO hausa_vpl VALUES ("LK1_35","072_1_35","LUK","1","35","35","Mala’ikan ya amsa ya ce, “Ruhu Mai Tsarki zai sauko miki, ikon Maɗaukaki kuma zai rufe ke. Saboda haka, Mai Tsarkin nan da za a haifa, za a kira shi Ɗan Allah. ");
INSERT INTO hausa_vpl VALUES ("LK1_36","072_1_36","LUK","1","36","36","’Yar’uwarki Elizabet ma za tă haifi ɗa a tsufanta, ita da aka ce bakararriya, ga shi tana a watanta na shida. ");
INSERT INTO hausa_vpl VALUES ("LK1_37","072_1_37","LUK","1","37","37","Gama ba abin da zai gagari Allah.” ");
INSERT INTO hausa_vpl VALUES ("LK1_38","072_1_38","LUK","1","38","38","Maryamu ta amsa ta ce, “To, ni baiwar Allah ce, bari yă zama mini kamar yadda ka faɗa.” Sai mala’ikan ya tafi abinsa. ");
INSERT INTO hausa_vpl VALUES ("LK1_39","072_1_39","LUK","1","39","39","A lokacin sai Maryamu ta shirya ta gaggauta zuwa wani gari a ƙasar tudu ta Yahudiya, ");
INSERT INTO hausa_vpl VALUES ("LK1_40","072_1_40","LUK","1","40","40","inda ta shiga gidan Zakariya ta kuma gai da Elizabet. ");
INSERT INTO hausa_vpl VALUES ("LK1_41","072_1_41","LUK","1","41","41","Da Elizabet ta ji gaisuwar Maryamu, sai jaririn da yake a cikinta ya yi motsi. Elizabet kuma ta cika da Ruhu Mai Tsarki. ");
INSERT INTO hausa_vpl VALUES ("LK1_42","072_1_42","LUK","1","42","42","Sai ta ɗaga murya da ƙarfi ta ce, “Ke mai albarka ce a cikin mata. Mai albarka ne kuma ɗan da za ki haifa! ");
INSERT INTO hausa_vpl VALUES ("LK1_43","072_1_43","LUK","1","43","43","Me ya sa na sami wannan tagomashi har da mahaifiyar Ubangijina za tă zo wurina? ");
INSERT INTO hausa_vpl VALUES ("LK1_44","072_1_44","LUK","1","44","44","Da jin gaisuwarki, sai jaririn da yake cikina ya yi motsi don murna. ");
INSERT INTO hausa_vpl VALUES ("LK1_45","072_1_45","LUK","1","45","45","Mai albarka ce wadda ta gaskata cewa abin da Ubangiji ya faɗa mata zai cika!” ");
INSERT INTO hausa_vpl VALUES ("LK1_46","072_1_46","LUK","1","46","46","Sai Maryamu ta ce, “Raina yana ɗaukaka Ubangiji ");
INSERT INTO hausa_vpl VALUES ("LK1_47","072_1_47","LUK","1","47","47","ruhuna kuma yana farin ciki da Allah Mai Cetona, ");
INSERT INTO hausa_vpl VALUES ("LK1_48","072_1_48","LUK","1","48","48","gama ya lura da ƙasƙancin baiwarsa. Daga yanzu nan gaba dukan zamanai za su ce da ni mai albarka, ");
INSERT INTO hausa_vpl VALUES ("LK1_49","072_1_49","LUK","1","49","49","gama Mai Iko Duka ya yi mini manyan abubuwa, sunansa labudda Mai Tsarki ne. ");
INSERT INTO hausa_vpl VALUES ("LK1_50","072_1_50","LUK","1","50","50","Jinƙansa ya kai ga masu tsoronsa, daga zamani zuwa zamani. ");
INSERT INTO hausa_vpl VALUES ("LK1_51","072_1_51","LUK","1","51","51","Ya aikata manyan ayyuka da hannunsa; ya watsar da waɗanda suke masu girman kai a zurfin tunaninsu. ");
INSERT INTO hausa_vpl VALUES ("LK1_52","072_1_52","LUK","1","52","52","Ya saukar da masu mulki daga gadajen sarautarsu amma ya ɗaukaka ƙasƙantattu. ");
INSERT INTO hausa_vpl VALUES ("LK1_53","072_1_53","LUK","1","53","53","Ya ƙosar da masu yunwa da kyawawan abubuwa amma ya sallami mawadata hannu wofi. ");
INSERT INTO hausa_vpl VALUES ("LK1_54","072_1_54","LUK","1","54","54","Ya taimaki bawansa Isra’ila, yana tunawa yă nuna jinƙai ");
INSERT INTO hausa_vpl VALUES ("LK1_55","072_1_55","LUK","1","55","55","ga Ibrahim da zuriyarsa har abada, kamar yadda ya faɗa wa kakanninmu.” ");
INSERT INTO hausa_vpl VALUES ("LK1_56","072_1_56","LUK","1","56","56","Maryamu ta zauna da Elizabet kusan wata uku sa’an nan ta koma gida. ");
INSERT INTO hausa_vpl VALUES ("LK1_57","072_1_57","LUK","1","57","57","Sa’ad da kwanaki suka yi don Elizabet ta haihu, sai ta haifi ɗa. ");
INSERT INTO hausa_vpl VALUES ("LK1_58","072_1_58","LUK","1","58","58","Maƙwabtanta da ’yan’uwanta suka ji cewa Ubangiji ya nuna mata jinƙai mai yawa, suka kuma taya ta farin ciki. ");
INSERT INTO hausa_vpl VALUES ("LK1_59","072_1_59","LUK","1","59","59","A rana ta takwas, sai suka zo don a yi wa yaron kaciya, dā za su sa masa sunan mahaifinsa Zakariya ne, ");
INSERT INTO hausa_vpl VALUES ("LK1_60","072_1_60","LUK","1","60","60","amma mahaifiyar yaron ta ce, “A’a! Za a ce da shi Yohanna.” ");
INSERT INTO hausa_vpl VALUES ("LK1_61","072_1_61","LUK","1","61","61","Sai suka ce mata, “Ba wani a cikin danginku mai wannan suna.” ");
INSERT INTO hausa_vpl VALUES ("LK1_62","072_1_62","LUK","1","62","62","Sai suka yi alamu wa mahaifinsa, don su san sunan da zai su a kira yaron. ");
INSERT INTO hausa_vpl VALUES ("LK1_63","072_1_63","LUK","1","63","63","Ya yi alama a kawo masa allo, a gaban kowa sai ya rubuta, “Sunansa Yohanna.” Dukan mutane kuwa suka yi mamaki. ");
INSERT INTO hausa_vpl VALUES ("LK1_64","072_1_64","LUK","1","64","64","Nan da nan bakinsa ya buɗe harshensa kuma ya saku, sai ya fara magana yana yabon Allah. ");
INSERT INTO hausa_vpl VALUES ("LK1_65","072_1_65","LUK","1","65","65","Maƙwabta duk suka cika da tsoro, mutane kuwa suka yi ta yin magana game da dukan waɗannan abubuwa a ko’ina a cikin ƙasar tudu ta Yahudiya. ");
INSERT INTO hausa_vpl VALUES ("LK1_66","072_1_66","LUK","1","66","66","Duk waɗanda suka ji wannan kuwa sun yi mamaki suna cewa, “To, me yaron nan zai zama?” Gama hannun Ubangiji yana tare da shi. ");
INSERT INTO hausa_vpl VALUES ("LK1_67","072_1_67","LUK","1","67","67","Mahaifinsa Zakariya ya cika da Ruhu Mai Tsarki sai ya yi annabci ya ce, ");
INSERT INTO hausa_vpl VALUES ("LK1_68","072_1_68","LUK","1","68","68","“Yabo ya tabbata ga Ubangiji, Allah na Isra’ila, domin ya zo ya kuma fanshe mutanensa. ");
INSERT INTO hausa_vpl VALUES ("LK1_69","072_1_69","LUK","1","69","69","Ya tā mana ƙahon ceto a gidan bawansa Dawuda ");
INSERT INTO hausa_vpl VALUES ("LK1_70","072_1_70","LUK","1","70","70","(yadda ya yi magana tun tuni ta wurin annabawansa masu tsarki), ");
INSERT INTO hausa_vpl VALUES ("LK1_71","072_1_71","LUK","1","71","71","cewa zai cece mu daga abokan gābanmu daga kuma hannun dukan waɗanda suke ƙinmu ");
INSERT INTO hausa_vpl VALUES ("LK1_72","072_1_72","LUK","1","72","72","don yă nuna jinƙai ga kakanninmu, yă kuma tuna da alkawarinsa mai tsarki, ");
INSERT INTO hausa_vpl VALUES ("LK1_73","072_1_73","LUK","1","73","73","rantsuwar da ya yi wa mahaifinmu Ibrahim, ");
INSERT INTO hausa_vpl VALUES ("LK1_74","072_1_74","LUK","1","74","74","don yă kuɓutar da mu daga hannun abokan gābanmu, yă kuma sa mu iya yin masa hidima babu tsoro, ");
INSERT INTO hausa_vpl VALUES ("LK1_75","072_1_75","LUK","1","75","75","cikin tsarki da adalci a gabansa dukan kwanakinmu. ");
INSERT INTO hausa_vpl VALUES ("LK1_76","072_1_76","LUK","1","76","76","“Kai kuma, ɗana, za a ce da kai annabin Maɗaukaki; gama za ka sha gaban Ubangiji don ka shirya masa hanya, ");
INSERT INTO hausa_vpl VALUES ("LK1_77","072_1_77","LUK","1","77","77","don ka sanar da mutanensa ceto, ta wurin gafarar zunubansu, ");
INSERT INTO hausa_vpl VALUES ("LK1_78","072_1_78","LUK","1","78","78","saboda jinƙai na Allahnmu mai ƙauna, hasken nan na ceto zai ɓullo mana daga sama, ");
INSERT INTO hausa_vpl VALUES ("LK1_79","072_1_79","LUK","1","79","79","don yă haskaka a kan waɗanda suke zama cikin duhu, da kuma cikin inuwar mutuwa, don yă bi da ƙafafunmu a hanyar salama.” ");
INSERT INTO hausa_vpl VALUES ("LK1_80","072_1_80","LUK","1","80","80","Yaron kuwa ya yi girma ya kuma ƙarfafa a ruhu; ya zauna a hamada sai lokacin da ya fito a fili ga mutanen Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("LK2_1","072_2_1","LUK","2","1","1","A waɗancan kwanaki, Kaisar Augustus ya ba da doka cewa ya kamata a yi ƙidaya a dukan masarautar Roma. ");
INSERT INTO hausa_vpl VALUES ("LK2_2","072_2_2","LUK","2","2","2","(Wannan ce ƙidaya ta fari da aka yi a lokacin da Kwiriniyus yake gwamnar Suriya.) ");
INSERT INTO hausa_vpl VALUES ("LK2_3","072_2_3","LUK","2","3","3","Sai kowa ya koma garinsa don a rubuta shi. ");
INSERT INTO hausa_vpl VALUES ("LK2_4","072_2_4","LUK","2","4","4","Saboda haka Yusuf ma ya haura daga Nazaret a Galili zuwa Yahudiya, ya tafi Betlehem garin Dawuda, don shi daga gida da kuma zuriyar Dawuda ne. ");
INSERT INTO hausa_vpl VALUES ("LK2_5","072_2_5","LUK","2","5","5","Ya tafi can don a rubuta shi tare da Maryamu, wadda aka yi masa alkawari zai aura, tana kuwa da ciki. ");
INSERT INTO hausa_vpl VALUES ("LK2_6","072_2_6","LUK","2","6","6","Yayinda suke can, sai lokacin haihuwar jaririn ya yi, ");
INSERT INTO hausa_vpl VALUES ("LK2_7","072_2_7","LUK","2","7","7","ta kuwa haifi ɗanta na fari. Ta nannaɗe shi a zane ta kuma kwantar da shi cikin wani kwami, don ba su sami ɗaki a masauƙi ba. ");
INSERT INTO hausa_vpl VALUES ("LK2_8","072_2_8","LUK","2","8","8","Akwai makiyaya masu zama a fili kusa da wurin, suna tsaron garkunan tumakinsu da dare. ");
INSERT INTO hausa_vpl VALUES ("LK2_9","072_2_9","LUK","2","9","9","Sai wani mala’ikan Ubangiji ya bayyana gare su, ɗaukakar Ubangiji kuma ta haskaka kewaye da su, suka kuwa tsorata ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("LK2_10","072_2_10","LUK","2","10","10","Amma mala’ikan ya ce musu, “Kada ku ji tsoro. Na kawo muku labari mai daɗi na farin ciki mai yawa ne wanda zai zama domin dukan mutane. ");
INSERT INTO hausa_vpl VALUES ("LK2_11","072_2_11","LUK","2","11","11","Yau a birnin Dawuda an haifa muku Mai Ceto; shi ne Kiristi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("LK2_12","072_2_12","LUK","2","12","12","Wannan zai zama alama a gare ku. Za ku tarar da jariri a nannaɗe a zane kwance a kwami.” ");
INSERT INTO hausa_vpl VALUES ("LK2_13","072_2_13","LUK","2","13","13","Ba labari sai ga taron rundunar sama suka bayyana tare da mala’ikan, suna yabon Allah suna cewa, ");
INSERT INTO hausa_vpl VALUES ("LK2_14","072_2_14","LUK","2","14","14","“Ɗaukaka ga Allah a can cikin sama, a duniya kuma salama ga mutane waɗanda tagomashinsa yake bisansu.” ");
INSERT INTO hausa_vpl VALUES ("LK2_15","072_2_15","LUK","2","15","15","Da mala’ikun suka bar su, su suka koma sama, sai makiyayan suka ce wa juna, “Mu je Betlehem mu ga wannan abin da ya faru, wanda Ubangiji ya sanar mana.” ");
INSERT INTO hausa_vpl VALUES ("LK2_16","072_2_16","LUK","2","16","16","Sai suka tafi da sauri, suka tarar da Maryamu da Yusuf, da kuma jaririn kwance a kwami. ");
INSERT INTO hausa_vpl VALUES ("LK2_17","072_2_17","LUK","2","17","17","Sa’ad da suka gan shi, sai suka baza maganar da aka gaya musu game da yaron, ");
INSERT INTO hausa_vpl VALUES ("LK2_18","072_2_18","LUK","2","18","18","duk kuwa waɗanda suka ji wannan, suka yi mamaki a kan abin da makiyayan suka faɗa. ");
INSERT INTO hausa_vpl VALUES ("LK2_19","072_2_19","LUK","2","19","19","Amma Maryamu ta riƙe dukan waɗannan abubuwa ta kuma yi ta tunaninsu a zuciyarta. ");
INSERT INTO hausa_vpl VALUES ("LK2_20","072_2_20","LUK","2","20","20","Makiyayan kuwa suka koma, suna ɗaukaka suna kuma yabon Allah saboda dukan abubuwan da suka ji, suka kuma gani, yadda aka gaya musu. ");
INSERT INTO hausa_vpl VALUES ("LK2_21","072_2_21","LUK","2","21","21","A rana ta takwas, da lokaci ya yi da za a yi masa kaciya, sai aka ba shi suna Yesu, sunan da mala’ika ya ba shi kafin a yi cikinsa. ");
INSERT INTO hausa_vpl VALUES ("LK2_22","072_2_22","LUK","2","22","22","Da lokacin tsarkakewarsu bisa ga Dokar Musa ya cika, sai Yusuf da Maryamu suka ɗauke shi suka haura zuwa Urushalima don su miƙa shi ga Ubangiji ");
INSERT INTO hausa_vpl VALUES ("LK2_23","072_2_23","LUK","2","23","23","(yadda yake a rubuce a Dokar Ubangiji cewa, “Kowane ɗan fari, za a keɓe shi ga Ubangiji”), ");
INSERT INTO hausa_vpl VALUES ("LK2_24","072_2_24","LUK","2","24","24","don kuma su miƙa hadaya bisa ga abin da aka faɗa a Dokar Ubangiji cewa, “kurciyoyi biyu ko ’yan tattabarai biyu.” ");
INSERT INTO hausa_vpl VALUES ("LK2_25","072_2_25","LUK","2","25","25","To, akwai wani mutum a Urushalima mai suna Siman, shi mai adalci da kuma mai ibada. Yana jiran fansar Isra’ila, Ruhu Mai Tsarki kuwa yana tare da shi. ");
INSERT INTO hausa_vpl VALUES ("LK2_26","072_2_26","LUK","2","26","26","An bayyana masa ta wurin Ruhu Mai Tsarki cewa ba zai mutu ba sai ya ga Kiristi na Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("LK2_27","072_2_27","LUK","2","27","27","Da Ruhu ya iza shi, sai ya shiga cikin filin haikali. Sa’ad da iyayen suka kawo jaririn nan Yesu don su yi masa abin da al’adar Doka ta bukaci, ");
INSERT INTO hausa_vpl VALUES ("LK2_28","072_2_28","LUK","2","28","28","sai Siman ya karɓi yaron a hannuwansa ya yabi Allah, yana cewa, ");
INSERT INTO hausa_vpl VALUES ("LK2_29","072_2_29","LUK","2","29","29","“Ya Ubangiji Mai Iko Duka, kamar yadda ka yi alkawari, yanzu ka sallami bawanka lafiya. ");
INSERT INTO hausa_vpl VALUES ("LK2_30","072_2_30","LUK","2","30","30","Gama idanuna sun ga cetonka, ");
INSERT INTO hausa_vpl VALUES ("LK2_31","072_2_31","LUK","2","31","31","wanda ka shirya a gaban dukan mutane, ");
INSERT INTO hausa_vpl VALUES ("LK2_32","072_2_32","LUK","2","32","32","haske don bayyanawa ga Al’ummai da kuma ɗaukaka ga mutanenka Isra’ila.” ");
INSERT INTO hausa_vpl VALUES ("LK2_33","072_2_33","LUK","2","33","33","Mahaifin yaron da kuma mahaifiyarsa suka yi mamaki abin da aka faɗa game da shi. ");
INSERT INTO hausa_vpl VALUES ("LK2_34","072_2_34","LUK","2","34","34","Sa’an nan Siman ya sa musu albarka ya ce wa Maryamu mahaifiyarsa, “An ƙaddara yaron nan yă zama sanadin fāɗuwa da tashin mutane da yawa a Isra’ila, zai kuma zama alamar da mutane ba za su so ba, ");
INSERT INTO hausa_vpl VALUES ("LK2_35","072_2_35","LUK","2","35","35","ta haka za a fallasa tunanin zukatan mutane da yawa. Ke ma, takobi zai soki zuciyarki.” ");
INSERT INTO hausa_vpl VALUES ("LK2_36","072_2_36","LUK","2","36","36","Akwai wata annabiya ma, mai suna Anna, diyar Fanuwel, na kabilar Asher. Ta tsufa kutuf; ta yi zama da mijinta shekaru bakwai bayan sun yi aure, ");
INSERT INTO hausa_vpl VALUES ("LK2_37","072_2_37","LUK","2","37","37","ta kuwa zama gwauruwa sai da ta kai shekaru tamanin da huɗu. Ba ta taɓa barin haikali ba, tana sujada dare da rana, tana kuma azumi da addu’a. ");
INSERT INTO hausa_vpl VALUES ("LK2_38","072_2_38","LUK","2","38","38","Tana haurawa wurinsu ke nan a wannan lokaci, sai ta yi wa Allah godiya ta kuma yi magana game da yaron nan ga dukan waɗanda suke sauraron fansar Urushalima. ");
INSERT INTO hausa_vpl VALUES ("LK2_39","072_2_39","LUK","2","39","39","Bayan da Yusuf da Maryamu suka gama yin dukan abubuwan da Dokar Ubangiji ta bukaci, sai suka koma Galili suka tafi Nazaret garinsu. ");
INSERT INTO hausa_vpl VALUES ("LK2_40","072_2_40","LUK","2","40","40","Yaron kuwa ya yi girma ya yi ƙarfi; ya cika da hikima, alherin Allah kuwa yana bisansa. ");
INSERT INTO hausa_vpl VALUES ("LK2_41","072_2_41","LUK","2","41","41","Kowace shekara, iyayen Yesu sukan je Urushalima don Bikin Ƙetarewa. ");
INSERT INTO hausa_vpl VALUES ("LK2_42","072_2_42","LUK","2","42","42","Da Yesu ya cika shekaru goma sha biyu, sai suka tafi Bikin bisa ga al’ada. ");
INSERT INTO hausa_vpl VALUES ("LK2_43","072_2_43","LUK","2","43","43","Bayan Bikin, da iyayen suka kama hanya don su koma gida, sai Yesu, yaron nan, ya tsaya a Urushalima, ba da saninsu ba. ");
INSERT INTO hausa_vpl VALUES ("LK2_44","072_2_44","LUK","2","44","44","Su kuwa sun ɗauka yana tare da su, saboda haka, suka yi ta tafiya har na yini guda. Sa’an nan suka fara nemansa cikin ’yan’uwansu da abokansu. ");
INSERT INTO hausa_vpl VALUES ("LK2_45","072_2_45","LUK","2","45","45","Da ba su gan shi ba, sai suka koma Urushalima nemansa. ");
INSERT INTO hausa_vpl VALUES ("LK2_46","072_2_46","LUK","2","46","46","Bayan kwana uku, sai suka same shi a filin haikali zaune a tsakiyar malamai, yana sauraronsu yana kuma yi musu tambayoyi. ");
INSERT INTO hausa_vpl VALUES ("LK2_47","072_2_47","LUK","2","47","47","Dukan waɗanda suka ji shi, suka yi mamakin fahimtarsa, da amsoshinsa. ");
INSERT INTO hausa_vpl VALUES ("LK2_48","072_2_48","LUK","2","48","48","Da iyayensa suka gan shi sai suka yi mamaki. Mahaifiyarsa ta ce masa, “Ɗana, don me ka yi mana haka? Ni da mahaifinka duk mun damu muna nemanka.” ");
INSERT INTO hausa_vpl VALUES ("LK2_49","072_2_49","LUK","2","49","49","Sai ya ce, “Don me kuke nemana? Ba ku san cewa, dole in kasance a gidan Ubana ba?” ");
INSERT INTO hausa_vpl VALUES ("LK2_50","072_2_50","LUK","2","50","50","Amma ba su fahimci abin da yake faɗin musu ba. ");
INSERT INTO hausa_vpl VALUES ("LK2_51","072_2_51","LUK","2","51","51","Sai ya koma Nazaret tare da su, yana yi musu biyayya. Mahaifiyarsa kuma ta riƙe dukan waɗannan abubuwa a zuciyarta. ");
INSERT INTO hausa_vpl VALUES ("LK2_52","072_2_52","LUK","2","52","52","Yesu kuwa ya yi girma, ya kuma ƙaru cikin hikima, ya kuma sami tagomashi a wurin Allah da mutane. ");
INSERT INTO hausa_vpl VALUES ("LK3_1","072_3_1","LUK","3","1","1","A shekara ta goma sha biyar ta mulkin Kaisar Tiberiyus, a lokacin Buntus Bilatus ne gwamnar Yahudiya, Hiridus kuma yana sarautar Galili, ɗan’uwansa Filibus yana sarautar Ituriya da Tarakunitis, Lisaniyas kuma yana sarautar Abiline. ");
INSERT INTO hausa_vpl VALUES ("LK3_2","072_3_2","LUK","3","2","2","A lokacin ne Annas da Kayifas suke manyan firistoci. Sai maganar Allah ta zo wa Yohanna, ɗan Zakariya a hamada. ");
INSERT INTO hausa_vpl VALUES ("LK3_3","072_3_3","LUK","3","3","3","Ya zaga dukan ƙasar da take kewaye da Urdun, yana wa’azin baftismar tuba don gafarar zunubai. ");
INSERT INTO hausa_vpl VALUES ("LK3_4","072_3_4","LUK","3","4","4","Kamar yadda yake a rubuce a littafin annabi Ishaya. “Muryar mai kira a hamada, ‘Ku shirya wa Ubangiji hanya, ku miƙe hanyoyi dominsa. ");
INSERT INTO hausa_vpl VALUES ("LK3_5","072_3_5","LUK","3","5","5","Za a cike kowane kwari, a farfashe kowane dutse da kowane tudu. Za a miƙe hanyoyin da suka karkace, a gyaggyara hanyoyi masu gargaɗa su zama sumul. ");
INSERT INTO hausa_vpl VALUES ("LK3_6","072_3_6","LUK","3","6","6","Dukan ’yan Adam kuwa za su ga ceton Allah!’ ” ");
INSERT INTO hausa_vpl VALUES ("LK3_7","072_3_7","LUK","3","7","7","Yohanna ya ce wa taron da suke zuwa domin yă yi musu baftisma, “Ku macizai! Wa ya gargaɗe ku, ku guje wa fushin nan mai zuwa? ");
INSERT INTO hausa_vpl VALUES ("LK3_8","072_3_8","LUK","3","8","8","Ku yi ayyukan da suka dace da tuba. Kada ma ku yi tunani za ku iya ce wa kanku, ‘Ai, muna da mahaifinmu Ibrahim.’ Ina gaya muku cewa daga cikin duwatsun nan Allah zai iya tā da ’ya’ya wa Ibrahim. ");
INSERT INTO hausa_vpl VALUES ("LK3_9","072_3_9","LUK","3","9","9","An riga an sa bakin gatari a gindin itatuwa, kuma duk itacen da bai ba da ’ya’ya masu kyau ba, za a sare shi a jefa cikin wuta.” ");
INSERT INTO hausa_vpl VALUES ("LK3_10","072_3_10","LUK","3","10","10","Sai taron suka tambaye shi, suka ce “Me za mu yi ke nan?” ");
INSERT INTO hausa_vpl VALUES ("LK3_11","072_3_11","LUK","3","11","11","Ya amsa ya ce, “Ya kamata, mutumin da yake da riguna biyu, yă raba da wanda ba shi da riga, mai abinci kuma yă yi haka.” ");
INSERT INTO hausa_vpl VALUES ("LK3_12","072_3_12","LUK","3","12","12","Masu karɓar haraji ma suka zo, domin a yi musu baftisma. Suka yi tambaya, suka ce “Malam, me ya kamata mu yi?” ");
INSERT INTO hausa_vpl VALUES ("LK3_13","072_3_13","LUK","3","13","13","Ya ce musu, “Kada ku karɓa fiye da abin da aka ce a karɓa.” ");
INSERT INTO hausa_vpl VALUES ("LK3_14","072_3_14","LUK","3","14","14","Sai waɗansu sojoji suka tambaye shi, “Mu fa? Me ya kamata mu yi?” Sai ya amsa ya ce, “Kada ku ƙwace kuɗin mutane, kada kuma ku yi shaidar ƙarya. Ku yi haƙuri da abin da ake biyanku.” ");
INSERT INTO hausa_vpl VALUES ("LK3_15","072_3_15","LUK","3","15","15","Mutane suka zuba ido, suna kuma tunani a zuciyarsu, ko Yohanna ne Kiristi wanda ake sauraron zuwansa. ");
INSERT INTO hausa_vpl VALUES ("LK3_16","072_3_16","LUK","3","16","16","Yohanna ya amsa musu duka ya ce, “Ina muku baftisma da ruwa. Amma wani wanda ya fi ni iko yana zuwa, ban ma isa in kunce igiyar takalmansa ba. Shi zai yi muku baftisma da Ruhu Mai Tsarki da wuta kuma. ");
INSERT INTO hausa_vpl VALUES ("LK3_17","072_3_17","LUK","3","17","17","Matankaɗinsa yana a hannunsa don yă tankaɗe sussukarsa ya kuma tattara alkama cikin rumbunsa, amma zai ƙone yayin da wutar da ba a iya kashewa.” ");
INSERT INTO hausa_vpl VALUES ("LK3_18","072_3_18","LUK","3","18","18","Da kalmomi masu yawa Yohanna ya yi wa mutane gargaɗi, ya kuma yi musu wa’azin bishara. ");
INSERT INTO hausa_vpl VALUES ("LK3_19","072_3_19","LUK","3","19","19","Amma da Yohanna ya tsawata wa Hiridus mai mulki saboda Hiridiyas, matar ɗan’uwansa, da kuma dukan sauran mugayen abubuwan da ya yi, ");
INSERT INTO hausa_vpl VALUES ("LK3_20","072_3_20","LUK","3","20","20","Hiridus dai ya ƙara ɓata al’amarin. Ya sa a kulle Yohanna a kurkuku. ");
INSERT INTO hausa_vpl VALUES ("LK3_21","072_3_21","LUK","3","21","21","Sa’ad da ake wa dukan mutane baftisma, sai aka yi wa Yesu shi ma. Da yana cikin addu’a, sai sama ya buɗe, ");
INSERT INTO hausa_vpl VALUES ("LK3_22","072_3_22","LUK","3","22","22","Ruhu Mai Tsarki kuma ya sauko masa a wata siffa, kamar kurciya. Sai murya ta fito daga sama, ta ce, “Kai ne Ɗana, wanda nake ƙauna, kai ne kuma kana faranta mini zuciya ƙwarai.” ");
INSERT INTO hausa_vpl VALUES ("LK3_23","072_3_23","LUK","3","23","23","To, Yesu kansa yana da shekaru kusan talatin da haihuwa sa’ad da ya fara aikinsa. An ɗauka shi ɗan Yusuf ne, ɗan Heli, ");
INSERT INTO hausa_vpl VALUES ("LK3_24","072_3_24","LUK","3","24","24","ɗan Mattat, ɗan Lawi, ɗan Melki, ɗan Yannai, ɗan Yusuf, ");
INSERT INTO hausa_vpl VALUES ("LK3_25","072_3_25","LUK","3","25","25","ɗan Mattatiyas, ɗan Amos, ɗan Nahum, ɗan Esli, ɗan Naggai, ");
INSERT INTO hausa_vpl VALUES ("LK3_26","072_3_26","LUK","3","26","26","ɗan Ma’at, ɗan Mattatiyas, ɗan Semeyin, ɗan Yosek, ɗan Yoda, ");
INSERT INTO hausa_vpl VALUES ("LK3_27","072_3_27","LUK","3","27","27","ɗan Yowanan, ɗan Resa, ɗan Zerubbabel, ɗan Sheyaltiyel, ɗan Neri, ");
INSERT INTO hausa_vpl VALUES ("LK3_28","072_3_28","LUK","3","28","28","ɗan Melki, ɗan Addi, ɗan Kosam, ɗan Elmadam, ɗan Er, ");
INSERT INTO hausa_vpl VALUES ("LK3_29","072_3_29","LUK","3","29","29","ɗan Yoshuwa, ɗan Eliyezer, ɗan Yorim, ɗan Mattat, ɗan Lawi, ");
INSERT INTO hausa_vpl VALUES ("LK3_30","072_3_30","LUK","3","30","30","ɗan Simeyon, ɗan Yahuda, ɗan Yusuf, ɗan Yonam, ɗan Eliyakim, ");
INSERT INTO hausa_vpl VALUES ("LK3_31","072_3_31","LUK","3","31","31","ɗan Meleya, ɗan Menna, ɗan Mattata, ɗan Natan, ɗan Dawuda, ");
INSERT INTO hausa_vpl VALUES ("LK3_32","072_3_32","LUK","3","32","32","ɗan Yesse, ɗan Obed, ɗan Bowaz, ɗan Salmon, ɗan Nashon, ");
INSERT INTO hausa_vpl VALUES ("LK3_33","072_3_33","LUK","3","33","33","ɗan Amminadab, ɗan Ram, ɗan Hezron, ɗan Ferez, ɗan Yahuda, ");
INSERT INTO hausa_vpl VALUES ("LK3_34","072_3_34","LUK","3","34","34","ɗan Yaƙub, ɗan Ishaku, ɗan Ibrahim, ɗan Tera, ɗan Nahor, ");
INSERT INTO hausa_vpl VALUES ("LK3_35","072_3_35","LUK","3","35","35","ɗan Serug, ɗan Reyu, ɗan Feleg, ɗan Eber, ɗan Sala, ");
INSERT INTO hausa_vpl VALUES ("LK3_36","072_3_36","LUK","3","36","36","ɗan Kainan, ɗan Arfakshad, ɗan Shem, ɗan Nuhu, ɗan Lamek, ");
INSERT INTO hausa_vpl VALUES ("LK3_37","072_3_37","LUK","3","37","37","ɗan Metusela, ɗan Enok, ɗan Yared, ɗan Mahalalel, ɗan Kainan, ");
INSERT INTO hausa_vpl VALUES ("LK3_38","072_3_38","LUK","3","38","38","ɗan Enosh, ɗan Shitu, ɗan Adamu, ɗan Allah. ");
INSERT INTO hausa_vpl VALUES ("LK4_1","072_4_1","LUK","4","1","1","Yesu kuwa cike da Ruhu Mai Tsarki, ya dawo daga Urdun, Ruhu kuma ya kai shi cikin hamada, ");
INSERT INTO hausa_vpl VALUES ("LK4_2","072_4_2","LUK","4","2","2","inda kwana arba’in, Iblis ya gwada shi. Bai ci kome ba a cikin kwanakin nan, a ƙarshensu kuwa ya ji yunwa. ");
INSERT INTO hausa_vpl VALUES ("LK4_3","072_4_3","LUK","4","3","3","Iblis ya ce masa, “In kai Ɗan Allah ne, ka faɗa wa wannan dutse yă zama burodi.” ");
INSERT INTO hausa_vpl VALUES ("LK4_4","072_4_4","LUK","4","4","4","Yesu ya amsa ya ce, “A rubuce yake, ‘Ba da abinci kaɗai mutum zai rayu ba.’” ");
INSERT INTO hausa_vpl VALUES ("LK4_5","072_4_5","LUK","4","5","5","Iblis ya kai shi can kan wani wuri mai tsawo, ya nunnuna masa a ƙyiftawar ido dukan mulkokin duniya. ");
INSERT INTO hausa_vpl VALUES ("LK4_6","072_4_6","LUK","4","6","6","Ya ce masa, “Zan ba ka dukan ikonsu da darajarsu, gama ni aka danƙa wa, kuma zan bai wa duk wanda na ga dama. ");
INSERT INTO hausa_vpl VALUES ("LK4_7","072_4_7","LUK","4","7","7","Saboda haka in ka yi mini sujada, dukan wannan zai zama naka.” ");
INSERT INTO hausa_vpl VALUES ("LK4_8","072_4_8","LUK","4","8","8","Yesu ya amsa ya ce, “A rubuce yake, ‘Ka yi wa Ubangiji Allahnka sujada, kuma shi kaɗai za ka bauta wa.’” ");
INSERT INTO hausa_vpl VALUES ("LK4_9","072_4_9","LUK","4","9","9","Sai Iblis, ya kai shi Urushalima ya sa ya tsaya a kan wuri mafi tsayi na haikali ya ce, “In kai Ɗan Allah ne, ka yi tsalle daga nan zuwa ƙasa. ");
INSERT INTO hausa_vpl VALUES ("LK4_10","072_4_10","LUK","4","10","10","Gama a rubuce yake, “ ‘Zai umarci mala’ikunsa game da kai, su kiyaye ka da kyau; ");
INSERT INTO hausa_vpl VALUES ("LK4_11","072_4_11","LUK","4","11","11","za su tallafe ka da hannuwansu, don kada ka buga ƙafarka a kan dutse.’” ");
INSERT INTO hausa_vpl VALUES ("LK4_12","072_4_12","LUK","4","12","12","Yesu ya amsa ya ce, “An ce, ‘Kada ka gwada Ubangiji Allahnka.’” ");
INSERT INTO hausa_vpl VALUES ("LK4_13","072_4_13","LUK","4","13","13","Da Iblis ya gama dukan wannan gwajin, ya bar shi sai lokacin da wata dama ta samu. ");
INSERT INTO hausa_vpl VALUES ("LK4_14","072_4_14","LUK","4","14","14","Yesu ya koma Galili cikin ikon Ruhu. Labarinsa kuwa ya bazu ko’ina a ƙauyuka. ");
INSERT INTO hausa_vpl VALUES ("LK4_15","072_4_15","LUK","4","15","15","Ya yi ta koyarwa a majami’unsu, kowa kuwa ya yabe shi. ");
INSERT INTO hausa_vpl VALUES ("LK4_16","072_4_16","LUK","4","16","16","Ya tafi Nazaret, inda aka yi renonsa. A ranar Asabbaci kuma, ya shiga majami’a kamar yadda ya saba. Sai ya miƙe don yă yi karatu. ");
INSERT INTO hausa_vpl VALUES ("LK4_17","072_4_17","LUK","4","17","17","Aka kuwa ba shi naɗaɗɗen littafin annabi Ishaya. Da ya buɗe, sai ya sami wurin da aka rubuta, ");
INSERT INTO hausa_vpl VALUES ("LK4_18","072_4_18","LUK","4","18","18","“Ruhun Ubangiji yana kaina, domin ya shafe ni, in yi wa matalauta wa’azin bishara. Ya aiko ni in yi shelar ’yanci ga ’yan kurkuku, in kuma buɗe idanun makafi, in ba da ’yanci ga waɗanda aka danne. ");
INSERT INTO hausa_vpl VALUES ("LK4_19","072_4_19","LUK","4","19","19","In yi shelar shekarar tagomashin Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("LK4_20","072_4_20","LUK","4","20","20","Sai ya naɗe naɗaɗɗen littafin ya mayar wa mai hidimar, ya kuma zauna. Dukan idanun waɗanda suke a majami’ar, suka koma a kansa. ");
INSERT INTO hausa_vpl VALUES ("LK4_21","072_4_21","LUK","4","21","21","Sai ya fara ce musu, “A yau, Nassin nan, ya cika a kunnenku.” ");
INSERT INTO hausa_vpl VALUES ("LK4_22","072_4_22","LUK","4","22","22","Duk suka yabe shi, suka yi mamakin kalmomin alheri da suke fitowa daga bakinsa. Suka yi tambaya, suna cewa, “Anya, wannan ba ɗan Yusuf ba ne?” ");
INSERT INTO hausa_vpl VALUES ("LK4_23","072_4_23","LUK","4","23","23","Yesu ya ce musu, “Tabbatacce, na san za ku faɗa mini karin maganan nan, ‘Likita, warkar da kanka! Ka kuma yi abin da muka ji ka yi a Kafarnahum, a nan garinka.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK4_24","072_4_24","LUK","4","24","24","Ya ci gaba, da ce musu, “Gaskiya nake gaya muku, babu annabin da ake yarda da shi a garinsa. ");
INSERT INTO hausa_vpl VALUES ("LK4_25","072_4_25","LUK","4","25","25","Ina tabbatar muku a zamanin Iliya, akwai gwauraye da yawa a Isra’ila, sa’ad da aka rufe sararin sama har shekara uku da rabi, aka kuma yi yunwa mai tsanani ko’ina a ƙasar. ");
INSERT INTO hausa_vpl VALUES ("LK4_26","072_4_26","LUK","4","26","26","Duk da haka, ba a aiki Iliya ga ko ɗaya a cikinsu ba. Sai dai zuwa ga wata gwauruwa da take a Zarefat, a yankin Sidon. ");
INSERT INTO hausa_vpl VALUES ("LK4_27","072_4_27","LUK","4","27","27","Akwai kuma mutane da yawa a Isra’ila masu kuturta a zamanin annabi Elisha, amma ba ko ɗayansu da aka tsarkake sai Na’aman mutumin Suriyan nan kaɗai.” ");
INSERT INTO hausa_vpl VALUES ("LK4_28","072_4_28","LUK","4","28","28","Dukan mutanen da suke cikin majami’a suka fusata ƙwarai da jin wannan. ");
INSERT INTO hausa_vpl VALUES ("LK4_29","072_4_29","LUK","4","29","29","Suka tashi, suka fitar da Yesu bayan gari, suka kai shi goshin tudun da aka gina garin, don su ture shi ƙasa, ");
INSERT INTO hausa_vpl VALUES ("LK4_30","072_4_30","LUK","4","30","30","amma sai ya bi ta tsakiyar taron ya yi tafiyarsa. ");
INSERT INTO hausa_vpl VALUES ("LK4_31","072_4_31","LUK","4","31","31","Sai ya tafi Kafarnahum, wani gari a Galili, a ranar Asabbaci kuma, ya fara koya wa mutane. ");
INSERT INTO hausa_vpl VALUES ("LK4_32","072_4_32","LUK","4","32","32","Suka yi ta mamakin koyarwarsa, domin saƙonsa yana da iko. ");
INSERT INTO hausa_vpl VALUES ("LK4_33","072_4_33","LUK","4","33","33","A cikin majami’ar, akwai wani mutum mai aljani, wani mugun ruhu. Mutumin ya ɗaga murya da ƙarfi ya ce, ");
INSERT INTO hausa_vpl VALUES ("LK4_34","072_4_34","LUK","4","34","34","“Wayyo! Ina ruwanka da mu, Yesu Banazare? Ka zo ne don ka hallaka mu? Na san wane ne kai, Mai Tsarki na Allah!” ");
INSERT INTO hausa_vpl VALUES ("LK4_35","072_4_35","LUK","4","35","35","Yesu ya tsawata masa da ƙarfin cewa, “Yi shiru! Ka fita daga cikinsa!” Sai aljanin ya fyaɗa mutumin da ƙasa a gabansu duka, sa’an nan ya fita, ya bar shi ba wani rauni. ");
INSERT INTO hausa_vpl VALUES ("LK4_36","072_4_36","LUK","4","36","36","Dukan mutanen suka yi mamaki, suka ce wa junansu, “Wace irin koyarwa ce haka? Da ƙarfi da iko, yana ba wa mugayen ruhohin umarni suna kuma fita!” ");
INSERT INTO hausa_vpl VALUES ("LK4_37","072_4_37","LUK","4","37","37","Labarinsa kuwa ya bazu ko’ina a cikin ƙasar. ");
INSERT INTO hausa_vpl VALUES ("LK4_38","072_4_38","LUK","4","38","38","Yesu ya fita daga majami’ar, ya tafi gidan Siman. Surukar Siman kuwa tana fama da zazzaɓi mai tsanani, sai suka roƙi Yesu yă taimake ta. ");
INSERT INTO hausa_vpl VALUES ("LK4_39","072_4_39","LUK","4","39","39","Sai ya sunkuya kusa da ita, ya kuma tsawata wa zazzaɓin, sai zazzaɓin ya sāke ta. Nan take ta tashi, ta yi musu hidima. ");
INSERT INTO hausa_vpl VALUES ("LK4_40","072_4_40","LUK","4","40","40","Rana tana fāɗuwa, sai mutane suka yi ta kawo wa Yesu dukan waɗanda suke da cuta iri-iri, sai ya ɗibiya wa kowannensu hannuwansa, ya warkar da su. ");
INSERT INTO hausa_vpl VALUES ("LK4_41","072_4_41","LUK","4","41","41","Bugu da ƙari, aljanu suka fiffita daga cikin mutane da yawa suna ihu suna cewa, “Kai Ɗan Allah ne!” Amma ya kwaɓe su, ya hana su magana, don sun san cewa shi ne Kiristi. ");
INSERT INTO hausa_vpl VALUES ("LK4_42","072_4_42","LUK","4","42","42","Da gari yana wayewa, sai Yesu ya je inda ba kowa. Mutane suka yi ta nemansa, da suka zo inda yake, sai suka yi ƙoƙari su hana shi barinsu. ");
INSERT INTO hausa_vpl VALUES ("LK4_43","072_4_43","LUK","4","43","43","Amma ya ce, “Dole in yi wa’azin bisharar mulkin Allah ga sauran garuruwa, saboda wannan ne aka aiko ni.” ");
INSERT INTO hausa_vpl VALUES ("LK4_44","072_4_44","LUK","4","44","44","Sai ya dinga yin wa’azi a majami’un Yahudiya. ");
INSERT INTO hausa_vpl VALUES ("LK5_1","072_5_1","LUK","5","1","1","Wata rana, Yesu yana tsaye a bakin Tafkin Gennesaret, mutane kuma suna ta matsawa kewaye da shi, domin su ji maganar Allah, ");
INSERT INTO hausa_vpl VALUES ("LK5_2","072_5_2","LUK","5","2","2","sai ya hangi jiragen ruwa biyu a bakin tafkin, waɗanda masu kamun kifi suka bari suna wankin abin kamun kifinsu. ");
INSERT INTO hausa_vpl VALUES ("LK5_3","072_5_3","LUK","5","3","3","Sai ya shiga ɗaya jirgin ruwan da yake na Siman, ya kuma roƙe shi yă tura shi kaɗan daga gaci. Sai ya zauna a jirgin ruwan, ya koyar da mutane daga ciki. ");
INSERT INTO hausa_vpl VALUES ("LK5_4","072_5_4","LUK","5","4","4","Da ya gama magana, sai ya ce wa Siman, “Ka tuƙa jirgin zuwa inda akwai zurfi, ka saukar da abin kamun kifinka ka kama kifi.” ");
INSERT INTO hausa_vpl VALUES ("LK5_5","072_5_5","LUK","5","5","5","Siman ya amsa ya ce, “Ranka yă daɗe, duk dare mun yi ta fama ba mu kama kome ba, amma tun da ka ce haka, zan saki abin kamun kifin.” ");
INSERT INTO hausa_vpl VALUES ("LK5_6","072_5_6","LUK","5","6","6","Da suka yi haka, sai suka kama kifi da yawa, har abin kamun kifinsu suka fara tsintsinkewa. ");
INSERT INTO hausa_vpl VALUES ("LK5_7","072_5_7","LUK","5","7","7","Sai suka kira abokansu a ɗaya jirgin, su zo su taimake su, suka kuwa zo. Suka cika jiragen biyu da kifi cif, har jiragen suka fara nutsewa. ");
INSERT INTO hausa_vpl VALUES ("LK5_8","072_5_8","LUK","5","8","8","Da Siman Bitrus ya ga wannan, sai ya fāɗi a gaban Yesu ya ce, “Rabu da ni, Ubangiji. Ni mai zunubi ne!” ");
INSERT INTO hausa_vpl VALUES ("LK5_9","072_5_9","LUK","5","9","9","Gama mamaki ya kama shi da abokansa duka, saboda yawan kifin da suka kama. ");
INSERT INTO hausa_vpl VALUES ("LK5_10","072_5_10","LUK","5","10","10","Yaƙub da Yohanna, ’ya’yan Zebedi, abokan aikin Siman su ma suka yi mamaki. Sai Yesu ya ce wa Siman, “Kada ka ji tsoro, daga yanzu za ka riƙa kama mutane ne.” ");
INSERT INTO hausa_vpl VALUES ("LK5_11","072_5_11","LUK","5","11","11","Sai suka jawo jiragen ruwansu zuwa gaci, suka bar kome da kome, suka bi shi. ");
INSERT INTO hausa_vpl VALUES ("LK5_12","072_5_12","LUK","5","12","12","Yayinda Yesu yake ɗaya daga cikin garuruwan nan, sai ga wani mutum wanda kuturta ta ci ƙarfinsa. Da ganin Yesu, sai ya fāɗi da fuskarsa a ƙasa, ya roƙe shi ya ce, “Ubangiji, in ka yarda, kana iya ka tsabtacce ni.” ");
INSERT INTO hausa_vpl VALUES ("LK5_13","072_5_13","LUK","5","13","13","Yesu ya miƙa hannunsa ya taɓa mutumin ya ce, “Na yarda, ka zama da tsabta!” Nan da nan, sai kuturtar ta rabu da shi. ");
INSERT INTO hausa_vpl VALUES ("LK5_14","072_5_14","LUK","5","14","14","Sai Yesu ya umarce shi ya ce, “Kada ka gaya wa kowa, amma ka tafi ka nuna kanka ga firist, ka kuma miƙa hadayu da Musa ya umarta, saboda tsarkakewarka ta zama shaida a gare su.” ");
INSERT INTO hausa_vpl VALUES ("LK5_15","072_5_15","LUK","5","15","15","Duk da haka, labarinsa ya ƙara bazuwa sosai, har taron mutane suka dinga zuwa don jinsa, da kuma neman warkarwa daga cututtukansu. ");
INSERT INTO hausa_vpl VALUES ("LK5_16","072_5_16","LUK","5","16","16","Amma Yesu sau da yawa, yakan keɓe kansa zuwa wuraren da ba kowa, yă yi addu’a. ");
INSERT INTO hausa_vpl VALUES ("LK5_17","072_5_17","LUK","5","17","17","Wata rana, da yake cikin koyarwa, waɗansu Farisiyawa da malaman dokoki waɗanda suka zo daga kowane ƙauye a Galili, Yahudiya da Urushalima kuwa suna zaune. Ikon Ubangiji yana nan don yă warkar da masu ciwo. ");
INSERT INTO hausa_vpl VALUES ("LK5_18","072_5_18","LUK","5","18","18","Sai ga waɗansu mutane suka kawo wani shanyayye a kan tabarma. Suka yi ƙoƙari su shigar da shi cikin gidan, domin su kwantar da shi a gaban Yesu. ");
INSERT INTO hausa_vpl VALUES ("LK5_19","072_5_19","LUK","5","19","19","Da suka ga babu hanyar da za su bi saboda taron, sai suka haura rufin, suka saukar da shi a kan tabarmarsa, ta bakin ramin da suka huda a rufin, suka ajiye shi a tsakiyar taron, a gaban Yesu. ");
INSERT INTO hausa_vpl VALUES ("LK5_20","072_5_20","LUK","5","20","20","Da Yesu ya ga bangaskiyarsu, sai ya ce, “Saurayi, an gafarta maka zunubanka.” ");
INSERT INTO hausa_vpl VALUES ("LK5_21","072_5_21","LUK","5","21","21","Farisiyawa da malaman dokoki suka fara yin tunani a zukatansu, “Wane ne wannan mutum da yake saɓo haka? Wa zai iya gafarta zunubai, in ba Allah kaɗai ba?” ");
INSERT INTO hausa_vpl VALUES ("LK5_22","072_5_22","LUK","5","22","22","Yesu ya san abin da suke tunani, sai ya yi tambaya ya ce, “Don me kuke tunanin waɗannan abubuwa a zukatanku? ");
INSERT INTO hausa_vpl VALUES ("LK5_23","072_5_23","LUK","5","23","23","Wanne ya fi sauƙi, a ce, ‘An gafarta maka zunubanka,’ ko kuma a ce, ‘Tashi, ka yi tafiya’? ");
INSERT INTO hausa_vpl VALUES ("LK5_24","072_5_24","LUK","5","24","24","Amma domin ku san cewa Ɗan Mutum yana da iko a duniya ya gafarta zunubai.” Sai ya ce wa shanyayyen, “Na ce maka, tashi, ɗauki tabarmarka ka tafi gida.” ");
INSERT INTO hausa_vpl VALUES ("LK5_25","072_5_25","LUK","5","25","25","Nan da nan, ya tashi tsaye a gabansu, ya ɗauki tabarmar da yake kwance a kai, ya tafi gida, yana yabon Allah. ");
INSERT INTO hausa_vpl VALUES ("LK5_26","072_5_26","LUK","5","26","26","Kowa ya yi mamaki, ya kuma yabi Allah. Suka cika da tsoro, suna cewa, “Mun ga abubuwan banmamaki yau.” ");
INSERT INTO hausa_vpl VALUES ("LK5_27","072_5_27","LUK","5","27","27","Bayan wannan, sai Yesu ya fita, ya ga wani mai karɓar haraji, mai suna Lawi, yana zaune a wurin da ake karɓar haraji. Yesu ya ce masa, “Bi ni.” ");
INSERT INTO hausa_vpl VALUES ("LK5_28","072_5_28","LUK","5","28","28","Sai Lawi ya tashi, ya bar kome da kome, ya bi shi. ");
INSERT INTO hausa_vpl VALUES ("LK5_29","072_5_29","LUK","5","29","29","Sai Lawi ya shirya wa Yesu wani babban liyafa a gidansa. Wani babban taron na masu karɓar haraji, tare da waɗansu suna cin abinci tare da su. ");
INSERT INTO hausa_vpl VALUES ("LK5_30","072_5_30","LUK","5","30","30","Amma Farisiyawa da malaman dokokin da suke a ƙungiyarsu, suka yi wa almajiransa gunaguni, suna cewa, “Don me kuke ci, kuke sha tare da masu karɓar haraji da masu zunubi?” ");
INSERT INTO hausa_vpl VALUES ("LK5_31","072_5_31","LUK","5","31","31","Yesu ya amsa musu ya ce, “Ai, masu lafiya ba sa bukatar likita, sai dai marasa lafiya. ");
INSERT INTO hausa_vpl VALUES ("LK5_32","072_5_32","LUK","5","32","32","Ban zo don in kira masu adalci ba, sai dai masu zunubi zuwa ga tuba.” ");
INSERT INTO hausa_vpl VALUES ("LK5_33","072_5_33","LUK","5","33","33","Suka ce masa, “Almajiran Yohanna sukan yi azumi da addu’a, haka ma almajiran Farisiyawa, amma naka sai ci da sha.” ");
INSERT INTO hausa_vpl VALUES ("LK5_34","072_5_34","LUK","5","34","34","Yesu ya amsa ya ce, “Za ku iya sa abokan ango yin azumi yayinda yake tare da su? ");
INSERT INTO hausa_vpl VALUES ("LK5_35","072_5_35","LUK","5","35","35","Amma lokaci yana zuwa, da za a ɗauke ango daga gare su. A waɗancan kwanakin ne za su yi azumi.” ");
INSERT INTO hausa_vpl VALUES ("LK5_36","072_5_36","LUK","5","36","36","Sai ya faɗa musu wannan misali ya ce, “Ba wanda yakan yage ƙyalle daga sabuwar riga ya yi wa tsohuwar riga faci. In ya yi haka, zai yage sabuwar rigar, kuma facin daga sabuwar ba zai dace da tsohuwar rigar ba. ");
INSERT INTO hausa_vpl VALUES ("LK5_37","072_5_37","LUK","5","37","37","Kuma ba wanda yakan zuba sabon ruwan inabi a cikin tsofaffin salkuna. In ya yi haka, sabon ruwan inabi zai farfashe salkunan, ruwan inabin yă zube, salkunan kuma su lalace. ");
INSERT INTO hausa_vpl VALUES ("LK5_38","072_5_38","LUK","5","38","38","A’a, sai dai a zuba sabon ruwan inabi a sababbin salkuna. ");
INSERT INTO hausa_vpl VALUES ("LK5_39","072_5_39","LUK","5","39","39","Kuma ba wanda yakan so shan sabon ruwan inabi bayan ya sha tsohon, don yakan ce, ‘Ai, tsohon ya fi kyau.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK6_1","072_6_1","LUK","6","1","1","A wata ranar Asabbaci, Yesu yana bi ta gonakin hatsi, sai almajiran suka fara kakkarya kan hatsi suna murjewa a hannuwansu suna ci. ");
INSERT INTO hausa_vpl VALUES ("LK6_2","072_6_2","LUK","6","2","2","Sai waɗansu Farisiyawa suka ce, “Me ya sa kuke yin abin da doka ta hana yi a ranar Asabbaci?” ");
INSERT INTO hausa_vpl VALUES ("LK6_3","072_6_3","LUK","6","3","3","Yesu ya amsa musu ya ce, “Ashe, ba ku taɓa karanta abin da Dawuda ya yi, sa’ad da shi da abokan tafiyarsa suka ji yunwa ba? ");
INSERT INTO hausa_vpl VALUES ("LK6_4","072_6_4","LUK","6","4","4","Ya shiga gidan Allah, ya ɗauki keɓaɓɓen burodi, sa’an nan ya ci abin da firistoci kaɗai sukan ci bisa ga doka. Ya kuma ba wa abokan tafiyarsa?” ");
INSERT INTO hausa_vpl VALUES ("LK6_5","072_6_5","LUK","6","5","5","Sai Yesu ya ce musu, “Ai, Ɗan Mutum ne Ubangijin Asabbaci.” ");
INSERT INTO hausa_vpl VALUES ("LK6_6","072_6_6","LUK","6","6","6","A wata ranar Asabbaci kuma, Yesu ya shiga majami’a yana koyarwa. To, a nan kuwa akwai wani mutumin da hannun damansa ya shanye. ");
INSERT INTO hausa_vpl VALUES ("LK6_7","072_6_7","LUK","6","7","7","Farisiyawa da malaman dokoki suka zuba wa Yesu ido, su ga ko zai warkar a ranar Asabbaci, don su sami dalilin zarginsa. ");
INSERT INTO hausa_vpl VALUES ("LK6_8","072_6_8","LUK","6","8","8","Amma Yesu ya san abin da suke tunani. Sai ya ce wa mutumin mai shanyayyen hannun, “Tashi ka tsaya a gaban kowa.” Sai ya tashi ya tsaya. ");
INSERT INTO hausa_vpl VALUES ("LK6_9","072_6_9","LUK","6","9","9","Yesu ya ce musu, “Ina tambayarku, me ya kamata a yi bisa ga doka, a ranar Asabbaci, a aikata alheri ko a aikata mugunta, a ceci rai, ko a hallaka shi?” ");
INSERT INTO hausa_vpl VALUES ("LK6_10","072_6_10","LUK","6","10","10","Sai ya kalle su duka, sa’an nan ya ce wa mutumin, “Miƙo hannunka.” Sai ya miƙe, hannunsa kuwa ya koma lafiyayye. ");
INSERT INTO hausa_vpl VALUES ("LK6_11","072_6_11","LUK","6","11","11","Amma Farisiyawa da malaman Doka suka fusata, suka fara tattauna da junansu a kan abin da za su yi wa Yesu. ");
INSERT INTO hausa_vpl VALUES ("LK6_12","072_6_12","LUK","6","12","12","Wata rana, a cikin kwanakin nan, Yesu ya je wani dutse domin yă yi addu’a, ya kuma kwana yana addu’a ga Allah. ");
INSERT INTO hausa_vpl VALUES ("LK6_13","072_6_13","LUK","6","13","13","Da gari ya waye, sai ya kira almajiransa zuwa wurinsa, ya zaɓi guda goma sha biyu daga cikinsu, waɗanda ya kira su, Manzanni. ");
INSERT INTO hausa_vpl VALUES ("LK6_14","072_6_14","LUK","6","14","14","Siman (wanda ya kira Bitrus), ɗan’uwansa Andarawus, Yaƙub, Yohanna, Filibus, Bartolomeyu, ");
INSERT INTO hausa_vpl VALUES ("LK6_15","072_6_15","LUK","6","15","15","Mattiyu, Toma, Yaƙub ɗan Alfayus, Siman wanda ake kira Zilot, ");
INSERT INTO hausa_vpl VALUES ("LK6_16","072_6_16","LUK","6","16","16","Yahuda ɗan Yaƙub, da kuma Yahuda Iskariyot, wanda ya bashe Yesu. ");
INSERT INTO hausa_vpl VALUES ("LK6_17","072_6_17","LUK","6","17","17","Sai ya sauko tare da su, ya tsaya a wani fili. A can, akwai taro mai yawa na almajiransa, da kuma mutane masu yawan gaske daga ko’ina a Yahudiya, Urushalima da kuma Taya da Sidon da suke bakin teku, ");
INSERT INTO hausa_vpl VALUES ("LK6_18","072_6_18","LUK","6","18","18","waɗanda suka zo domin su ji shi, a kuma warkar da cututtukansu. Waɗanda suke fama da mugayen ruhohi kuwa aka warkar da su. ");
INSERT INTO hausa_vpl VALUES ("LK6_19","072_6_19","LUK","6","19","19","Kuma dukan mutane suka yi ƙoƙari su taɓa shi, domin iko yana fitowa daga gare shi, ya kuwa warkar da su duka. ");
INSERT INTO hausa_vpl VALUES ("LK6_20","072_6_20","LUK","6","20","20","Da ya dubi almajiransa, sai ya ce, “Masu albarka ne ku da kuke matalauta, gama mulkin Allah naku ne. ");
INSERT INTO hausa_vpl VALUES ("LK6_21","072_6_21","LUK","6","21","21","Masu albarka ne ku da kuke jin yunwa yanzu, gama za ku ƙoshi. Masu albarka ne ku da kuke kuka yanzu, gama za ku yi dariya. ");
INSERT INTO hausa_vpl VALUES ("LK6_22","072_6_22","LUK","6","22","22","Masu albarka ne sa’ad da mutane suka ƙi ku, suka ware ku, suka zage ku, suna ce da ku mugaye, saboda Ɗan Mutum. ");
INSERT INTO hausa_vpl VALUES ("LK6_23","072_6_23","LUK","6","23","23","“Ku yi farin ciki a wannan rana, ku kuma yi tsalle don murna, saboda ladarku yana da yawa a sama. Gama haka kakanninsu suka yi wa annabawa. ");
INSERT INTO hausa_vpl VALUES ("LK6_24","072_6_24","LUK","6","24","24","“Amma kaitonku da kuke da arziki, gama kun riga kun sami ta’aziyyarku. ");
INSERT INTO hausa_vpl VALUES ("LK6_25","072_6_25","LUK","6","25","25","Kaitonku da kuke ƙosassu yanzu, gama za ku zauna da yunwa. Kaitonku da kuke dariya yanzu, gama za ku yi makoki da kuka. ");
INSERT INTO hausa_vpl VALUES ("LK6_26","072_6_26","LUK","6","26","26","Kaitonku sa’ad da dukan mutane suna magana mai kyau a kanku, gama haka kakanninsu suka yi da annabawan ƙarya. ");
INSERT INTO hausa_vpl VALUES ("LK6_27","072_6_27","LUK","6","27","27","“Amma ina faɗa muku, ku da kuke ji na, ku ƙaunaci abokan gābanku, ku yi wa masu ƙinku alheri. ");
INSERT INTO hausa_vpl VALUES ("LK6_28","072_6_28","LUK","6","28","28","Ku albarkaci waɗanda suke la’anta ku, ku kuma yi wa waɗanda suke wulaƙanta ku addu’a. ");
INSERT INTO hausa_vpl VALUES ("LK6_29","072_6_29","LUK","6","29","29","In wani ya mare ka a wannan kumatu, juya masa ɗayan ma, in wani ya ƙwace maka babban riga, kada ma ka hana masa ’yar cikin ma. ");
INSERT INTO hausa_vpl VALUES ("LK6_30","072_6_30","LUK","6","30","30","Duk wanda ya roƙe ka abu, ka ba shi. In kuma wani ya yi maka ƙwace, kada ka nema yă mayar maka. ");
INSERT INTO hausa_vpl VALUES ("LK6_31","072_6_31","LUK","6","31","31","Ka yi wa waɗansu abin da kai kake so su yi maka. ");
INSERT INTO hausa_vpl VALUES ("LK6_32","072_6_32","LUK","6","32","32","“In kana ƙaunar masu ƙaunarka ne kawai, ina ribar wannan? Ko masu zunubi ma suna ƙaunar waɗanda suke ƙaunarsu. ");
INSERT INTO hausa_vpl VALUES ("LK6_33","072_6_33","LUK","6","33","33","In kuma kana yin alheri ga masu yi maka ne kaɗai, ina ribar wannan? Ko masu zunubi ma suna yin haka. ");
INSERT INTO hausa_vpl VALUES ("LK6_34","072_6_34","LUK","6","34","34","In kana ba da bashi ga mutanen da za su iya biyan ka ne kawai, ina ribar wannan? Ko masu zunubi ma, suna ba da bashi ga masu zunubi, da fata za a biya su tsab. ");
INSERT INTO hausa_vpl VALUES ("LK6_35","072_6_35","LUK","6","35","35","Amma, ku ƙaunaci abokan gābanku, ku kuma yi musu alheri, ku ba su bashi, ba da sa zuciya sai an biya ku ba. Ta yin haka ne kawai, za ku sami lada mai yawa, ku kuma zama ’ya’yan Mafi Ɗaukaka, gama shi mai alheri ne ga marasa godiya da mugaye. ");
INSERT INTO hausa_vpl VALUES ("LK6_36","072_6_36","LUK","6","36","36","Ku zama masu jinƙai, kamar yadda Ubanku mai jinƙai ne. ");
INSERT INTO hausa_vpl VALUES ("LK6_37","072_6_37","LUK","6","37","37","“Kada ku ɗora wa wani, ku ma ba za a ɗora muku ba. Kada ku yanke wa wani hukunci, ku ma ba za a yanke muku ba. Ku gafarta, ku ma za a gafarta muku. ");
INSERT INTO hausa_vpl VALUES ("LK6_38","072_6_38","LUK","6","38","38","Ku bayar, ku ma sai a ba ku mudu a cike, a danƙare, har yă yi tozo, yana zuba, za a juye muku a hannun riga. Mudun da kuka auna da shi, da shi za a auna muku.” ");
INSERT INTO hausa_vpl VALUES ("LK6_39","072_6_39","LUK","6","39","39","Ya kuma faɗa musu wannan misali cewa, “Makaho yana iya jagoran makaho ne? Ba sai dukansu biyu su fāɗa a rami ba? ");
INSERT INTO hausa_vpl VALUES ("LK6_40","072_6_40","LUK","6","40","40","Ɗalibi bai fi malaminsa ba, sai dai kowane ɗalibi wanda ya sami cikakkiyar koyarwa, zai zama kamar malaminsa. ");
INSERT INTO hausa_vpl VALUES ("LK6_41","072_6_41","LUK","6","41","41","“Don me kake duban ɗan tsinke da yake idon ɗan’uwanka, amma ba ka kula da gungumen da yake a naka ido ba? ");
INSERT INTO hausa_vpl VALUES ("LK6_42","072_6_42","LUK","6","42","42","Yaya za ka ce wa ɗan’uwanka, ‘Ɗan’uwa, bari in cire maka ɗan tsinke da yake idonka,’ alhali kuwa, kai kanka ka kāsa ganin gungumen da yake a naka ido? Kai munafuki! Ka fara cire gungumen daga idonka, sa’an nan za ka iya gani sosai, ka kuma cire ɗan tsinken da yake a idon ɗan’uwanka.” ");
INSERT INTO hausa_vpl VALUES ("LK6_43","072_6_43","LUK","6","43","43","“Ba itace mai kyau da yake ba da munanan ’ya’ya. Mummunan itace kuma ba ya ba da ’ya’ya masu kyau. ");
INSERT INTO hausa_vpl VALUES ("LK6_44","072_6_44","LUK","6","44","44","Kowane itace da irin ’ya’yansa ne ake saninsa. Mutane ba sa tsinke ’ya’yan ɓaure daga ƙaya, ko kuwa ’ya’yan inabi daga sarƙaƙƙiya. ");
INSERT INTO hausa_vpl VALUES ("LK6_45","072_6_45","LUK","6","45","45","Mutumin nagari yakan nuna abubuwa nagari daga cikin nagarta da yake a ɓoye a zuciyarsa, mugun mutum kuwa yakan nuna mugayen abubuwa daga muguntar da take a ɓoye a zuciyarsa. Gama baki yakan faɗa abin da ya cika zuciya ne.” ");
INSERT INTO hausa_vpl VALUES ("LK6_46","072_6_46","LUK","6","46","46","“Don me kuke ce da ni, ‘Ubangiji, Ubangiji,’ amma ba kwa yin abin da na faɗa? ");
INSERT INTO hausa_vpl VALUES ("LK6_47","072_6_47","LUK","6","47","47","Zan nuna muku kwatancin mutumin da yakan zo wurina, yă ji kalmomina, yă kuma aikata. ");
INSERT INTO hausa_vpl VALUES ("LK6_48","072_6_48","LUK","6","48","48","Yana kama da mutumin da ya gina gida, wanda ya haƙa ƙasa da zurfi, sa’an nan ya kafa tushen ginin a kan dutse. Da ambaliyar ruwa ta taso, ƙarfin ruwa kuwa ya buga gidan, wannan bai jijjiga shi ba, domin an yi masa tushen gini na ainihi. ");
INSERT INTO hausa_vpl VALUES ("LK6_49","072_6_49","LUK","6","49","49","Amma wanda yakan ji kalmomina, ba ya kuma aikata su, yana kama da mutumin da ya gina gida a ƙasa, ba tare da ya kafa tushen gini ba. A sa’ad da ƙarfin ruwa ya buga gidan, sai gidan yă rushe, mummunar rushewa kuwa.” ");
INSERT INTO hausa_vpl VALUES ("LK7_1","072_7_1","LUK","7","1","1","Bayan Yesu ya gama gaya wa mutanen dukan waɗannan abubuwa, sai ya shiga Kafarnahum. ");
INSERT INTO hausa_vpl VALUES ("LK7_2","072_7_2","LUK","7","2","2","A can, akwai wani bawan wani jarumin yana ciwo, yana kuma a bakin mutuwa. Maigidansa kuwa yana sonsa sosai. ");
INSERT INTO hausa_vpl VALUES ("LK7_3","072_7_3","LUK","7","3","3","Jarumin sojan ya ji labarin Yesu, sai ya aiki waɗansu dattawan Yahudawa wajensa, yana roƙonsa yă zo yă warkar da bawansa. ");
INSERT INTO hausa_vpl VALUES ("LK7_4","072_7_4","LUK","7","4","4","Da suka isa wurin Yesu, sai suka roƙe shi sosai, suka ce, “Wannan mutum, ai, ya dace a yi masa haka, ");
INSERT INTO hausa_vpl VALUES ("LK7_5","072_7_5","LUK","7","5","5","gama yana ƙaunar al’ummarmu ta Yahudawa, har ya gina majami’armu.” ");
INSERT INTO hausa_vpl VALUES ("LK7_6","072_7_6","LUK","7","6","6","Sai Yesu ya tafi tare da su. Da ya yi kusa da gidan, sai jarumin nan, ya aiki abokai su ce masa, “Ubangiji, kada ka dami kanka, gama ban isa ka shiga gidana ba. ");
INSERT INTO hausa_vpl VALUES ("LK7_7","072_7_7","LUK","7","7","7","Shi ya sa ban ma ga na isa in zo wurinka ba. Amma ka yi magana kawai, bawana zai warke. ");
INSERT INTO hausa_vpl VALUES ("LK7_8","072_7_8","LUK","7","8","8","Gama ni kaina, mutum ne a ƙarƙashin iko, akwai kuma sojoji a ƙarƙashin ikona. Nakan ce wa wannan, ‘Je ka,’ sai yă tafi, ga wani kuma in ce, ‘Zo nan,’ sai yă zo. Nakan kuma ce wa bawana, ‘Yi abu kaza,’ sai yă yi.” ");
INSERT INTO hausa_vpl VALUES ("LK7_9","072_7_9","LUK","7","9","9","Da Yesu ya ji haka, sai ya yi mamaki sosai. Ya juya ya wa taron da yake bin sa, “Ina faɗa muku, ban taɓa samun irin bangaskiya mai girma haka ko cikin Isra’ila ba.” ");
INSERT INTO hausa_vpl VALUES ("LK7_10","072_7_10","LUK","7","10","10","Sai mutanen da aka aika, suka koma gida, suka tarar bawan ya warke. ");
INSERT INTO hausa_vpl VALUES ("LK7_11","072_7_11","LUK","7","11","11","Ba a daɗe ba, sai Yesu ya tafi wani garin da ake kira Nayin. Almajiransa da taro mai yawa suka tafi tare da shi. ");
INSERT INTO hausa_vpl VALUES ("LK7_12","072_7_12","LUK","7","12","12","Da ya yi kusa da ƙofar garin, sai ga wata gawa ana fitowa da ita. Shi ne ɗa kaɗai ga mahaifiyarsa, ita kuma gwauruwa ce. Taro mai yawa daga garin yana tare da ita. ");
INSERT INTO hausa_vpl VALUES ("LK7_13","072_7_13","LUK","7","13","13","Da Ubangiji ya gan ta, sai ya ji tausayinta ya ce, “Kada ki yi kuka.” ");
INSERT INTO hausa_vpl VALUES ("LK7_14","072_7_14","LUK","7","14","14","Yesu ya je ya taɓa akwatin gawar, sai masu ɗaukarsa suka tsaya cik. Sai ya ce, “Saurayi, na ce maka, tashi!” ");
INSERT INTO hausa_vpl VALUES ("LK7_15","072_7_15","LUK","7","15","15","Sai mamacin ya tashi zaune, ya fara magana. Yesu kuma ya ba da shi ga mahaifiyarsa. ");
INSERT INTO hausa_vpl VALUES ("LK7_16","072_7_16","LUK","7","16","16","Sai tsoro ya kama su duka, suka yabi Allah, suna cewa, “Babban annabi ya bayyana a cikinmu. Allah ya zo domin yă taimaki mutanensa.” ");
INSERT INTO hausa_vpl VALUES ("LK7_17","072_7_17","LUK","7","17","17","Wannan labarin game da Yesu, ya bazu ko’ina a Yahudiya da kewayenta. ");
INSERT INTO hausa_vpl VALUES ("LK7_18","072_7_18","LUK","7","18","18","Almajiran Yohanna suka gaya masa dukan waɗannan abubuwa. Sai ya kira biyu daga cikinsu, ");
INSERT INTO hausa_vpl VALUES ("LK7_19","072_7_19","LUK","7","19","19","ya aike su wurin Ubangiji, su tambaya su ce, “Kai ne wanda zai zo, ko kuma mu saurari wani dabam?” ");
INSERT INTO hausa_vpl VALUES ("LK7_20","072_7_20","LUK","7","20","20","Da mutanen suka iso wurin Yesu, sai suka ce, “Yohanna Mai Baftisma ne ya aike mu wurinka, mu yi tambaya, ‘Ko kai ne wanda zai zo, ko kuma mu saurari wani dabam?’ ” ");
INSERT INTO hausa_vpl VALUES ("LK7_21","072_7_21","LUK","7","21","21","A daidai lokacin nan, Yesu ya warkar da mutane da yawa masu ciwo, masu cututtuka, da kuma masu mugayen ruhohi. Ya kuma ba makafi da yawa ganin gari. ");
INSERT INTO hausa_vpl VALUES ("LK7_22","072_7_22","LUK","7","22","22","Sai ya amsa wa almajiran Yohanna ya ce, “Ku koma ku faɗa wa Yohanna abin da kuka ji, da abin da kuka gani. Makafi suna ganin gari, guragu suna tafiya, ana warkar da waɗanda suke da kuturta, kurame suna ji, ana tā da matattu, ana kuma yi wa matalauta wa’azin bishara. ");
INSERT INTO hausa_vpl VALUES ("LK7_23","072_7_23","LUK","7","23","23","Mai albarka ne mutumin da bai yi shakkar bangaskiyar da yake da ita a kaina ba.” ");
INSERT INTO hausa_vpl VALUES ("LK7_24","072_7_24","LUK","7","24","24","Bayan almajiran Yohanna suka tafi, sai Yesu ya fara yi wa taron magana game da Yohanna ya ce, “Me kuka je kallo a hamada? Ciyawar da iska take kaɗawa ne? ");
INSERT INTO hausa_vpl VALUES ("LK7_25","072_7_25","LUK","7","25","25","In ba haka ba, to, me kuka je kallo? Mutum mai sanye da tufafi masu kyau ne? A’a, masu sa kayan tsada da suke cikin annashuwa, ai, a fada suke. ");
INSERT INTO hausa_vpl VALUES ("LK7_26","072_7_26","LUK","7","26","26","Amma me kuka je kallo? Annabi? I, ina kuma faɗa muku, ya ma fi annabi. ");
INSERT INTO hausa_vpl VALUES ("LK7_27","072_7_27","LUK","7","27","27","Wannan shi ne wanda aka rubuta game da shi cewa, “ ‘Zan aiko da ɗan saƙona yă sha gabanka, wanda zai shirya hanya, a gabanka.’ ");
INSERT INTO hausa_vpl VALUES ("LK7_28","072_7_28","LUK","7","28","28","Ina faɗa muku, a cikin duk waɗanda mata suka haifa, ba wanda ya fi Yohanna girma. Duk da haka wanda ya fi ƙasƙanta a Mulkin Allah ya fi shi.” ");
INSERT INTO hausa_vpl VALUES ("LK7_29","072_7_29","LUK","7","29","29","(Dukan mutane, har da masu karɓar haraji, da suka ji kalmomin Yesu, sai suka yarda cewa hanyar Allah gaskiya ce, domin Yohanna ne ya yi musu baftisma. ");
INSERT INTO hausa_vpl VALUES ("LK7_30","072_7_30","LUK","7","30","30","Amma Farisiyawa da masanan dokoki, suka ƙi nufin Allah game da su, domin Yohanna bai yi musu baftisma ba.) ");
INSERT INTO hausa_vpl VALUES ("LK7_31","072_7_31","LUK","7","31","31","Yesu ya ci gaba da cewa, “To, da me zan kwatanta mutanen zamanin nan? Kamar me suke? ");
INSERT INTO hausa_vpl VALUES ("LK7_32","072_7_32","LUK","7","32","32","Suna kama da yaran da suke zama a bakin kasuwa, suna kiran juna, suna cewa, “ ‘Mun busa muku sarewa, amma ba ku yi rawa ba, Mun kuma yi muku waƙar makoki, ba ku kuma yi kuka ba.’ ");
INSERT INTO hausa_vpl VALUES ("LK7_33","072_7_33","LUK","7","33","33","Gama Yohanna Mai Baftisma ya zo, ba ya cin burodi, ba ya shan ruwan inabi, sai kuka ce, ‘Ai, yana da aljani.’ ");
INSERT INTO hausa_vpl VALUES ("LK7_34","072_7_34","LUK","7","34","34","Ɗan Mutum ya zo yana ci, yana sha, sai kuka ce, ‘Ga mai yawan ci, mashayi, da kuma abokin masu karɓar haraji da masu zunubi.’ ");
INSERT INTO hausa_vpl VALUES ("LK7_35","072_7_35","LUK","7","35","35","Amma akan tabbatar da hikima ta gaskiya bisa ga dukan ’ya’yanta.” ");
INSERT INTO hausa_vpl VALUES ("LK7_36","072_7_36","LUK","7","36","36","To, ana nan, sai ɗaya daga cikin Farisiyawa ya gayyaci Yesu cin abincin yamma a gidansa, ya kuwa tafi gidan Bafarisiyen, ya zauna a tebur. ");
INSERT INTO hausa_vpl VALUES ("LK7_37","072_7_37","LUK","7","37","37","Da wata mace wadda ta yi rayuwar zunubi a wannan gari ta ji Yesu yana cin abinci a gidan Bafarisiyen, sai ta kawo ɗan tulun turaren alabasta, ");
INSERT INTO hausa_vpl VALUES ("LK7_38","072_7_38","LUK","7","38","38","ta kuma tsaya daga bayansa, wajen ƙafafunsa tana kuka, sai hawayenta sun fara zuba a ƙafafunsa. Sai ta goge su da gashin kanta, ta sumbace su, sa’an nan ta shafa musu turare. ");
INSERT INTO hausa_vpl VALUES ("LK7_39","072_7_39","LUK","7","39","39","Da Bafarisiyen da ya gayyace shi, ya ga wannan, sai ya ce a ransa, “Da mutumin nan annabi ne, da ya san ko wace ce take taɓansa, da kuma irin macen da take, cewa mai zunubi ce.” ");
INSERT INTO hausa_vpl VALUES ("LK7_40","072_7_40","LUK","7","40","40","Sai Yesu ya ce masa, “Siman, ina da abin da zan faɗa maka.” Shi kuwa ya ce, “Malam sai ka faɗa.” ");
INSERT INTO hausa_vpl VALUES ("LK7_41","072_7_41","LUK","7","41","41","Yesu ya ce, “An yi waɗansu mutum biyu da suke riƙe bashin mai ba da rance. Ana bin guda dinari ɗari biyar, ɗayan kuma hamsin. ");
INSERT INTO hausa_vpl VALUES ("LK7_42","072_7_42","LUK","7","42","42","Dukan biyun suka gagara biyansa, sai ya yafe musu. To, a ganinka, wa zai fi ƙaunar mutumin nan?” ");
INSERT INTO hausa_vpl VALUES ("LK7_43","072_7_43","LUK","7","43","43","Siman ya amsa ya ce, “A ganina, wanda aka yafe wa mai yawa ne.” Sai Yesu ya ce, “Ka faɗa daidai.” ");
INSERT INTO hausa_vpl VALUES ("LK7_44","072_7_44","LUK","7","44","44","Sai ya juya wajen macen, ya ce wa Siman, “Ka ga macen nan? Na shigo gidanka, ba ka ba ni ruwa don ƙafafuna ba, amma ta wanke ƙafafuna da hawayenta, ta kuma goge su da gashin kanta. ");
INSERT INTO hausa_vpl VALUES ("LK7_45","072_7_45","LUK","7","45","45","Ba ka yi mini sumba ba, amma tun shigowata a nan, macen nan ba tă daina sumbar ƙafafuna ba. ");
INSERT INTO hausa_vpl VALUES ("LK7_46","072_7_46","LUK","7","46","46","Ba ka shafa mai a kaina ba, amma ta zubo turare a ƙafafuna. ");
INSERT INTO hausa_vpl VALUES ("LK7_47","072_7_47","LUK","7","47","47","“Saboda haka ina gaya maka, zunubanta masu yawa, an gafarta mata, gama ƙaunarta mai yawa ce. Amma wanda aka gafarta wa kaɗan kuwa, yakan nuna ƙauna kaɗan.” ");
INSERT INTO hausa_vpl VALUES ("LK7_48","072_7_48","LUK","7","48","48","Sai Yesu ya ce mata, “An gafarta miki zunubanki.” ");
INSERT INTO hausa_vpl VALUES ("LK7_49","072_7_49","LUK","7","49","49","Sauran baƙin suka fara ce wa juna, “Wane ne wannan, wanda har yake gafarta zunubai?” ");
INSERT INTO hausa_vpl VALUES ("LK7_50","072_7_50","LUK","7","50","50","Yesu ya ce wa macen, “Bangaskiyarki ta cece ki, ki sauka lafiya.” ");
INSERT INTO hausa_vpl VALUES ("LK8_1","072_8_1","LUK","8","1","1","Bayan wannan sai Yesu ya zazzaga gari da ƙauye, yana wa’azin bisharar mulkin Allah. Sha Biyun nan kuwa suna tare da shi, ");
INSERT INTO hausa_vpl VALUES ("LK8_2","072_8_2","LUK","8","2","2","da kuma waɗansu mata waɗanda aka warkar da su daga cututtukansu, da kuma mugayen ruhohi. Cikinsu akwai Maryamu (wadda ake kira Magdalin) wadda aljanu bakwai suka fito daga cikinta. ");
INSERT INTO hausa_vpl VALUES ("LK8_3","072_8_3","LUK","8","3","3","Da Yowanna matar Kuza, manajan iyalin Hiridus; da Suzana; da waɗansu mata da yawa. Waɗannan mata suna taimaka musu cikin hidima, daga cikin abin da suke da shi na zaman gari. ");
INSERT INTO hausa_vpl VALUES ("LK8_4","072_8_4","LUK","8","4","4","Yayinda taron mai girma na taruwa, mutane kuma daga garuruwa dabam-dabam suna zuwa wurin Yesu, sai ya ba da wannan misali ya ce, ");
INSERT INTO hausa_vpl VALUES ("LK8_5","072_8_5","LUK","8","5","5","“Wani manomi ya fita domin ya shuka irinsa. Da yana watsa irin, sai waɗansu suka fāɗi a kan hanya, aka tattaka su, tsuntsayen sararin sama kuma suka cinye su. ");
INSERT INTO hausa_vpl VALUES ("LK8_6","072_8_6","LUK","8","6","6","Waɗansu suka fāɗi a kan dutse, da suka tsira sai suka yanƙwane don babu ruwa a wurin. ");
INSERT INTO hausa_vpl VALUES ("LK8_7","072_8_7","LUK","8","7","7","Waɗansu kuma suka fāɗi a cikin ƙaya. Da suka yi girma tare, sai ƙayan suka shaƙe su. ");
INSERT INTO hausa_vpl VALUES ("LK8_8","072_8_8","LUK","8","8","8","Waɗansu kuma har yanzu, suka fāɗi a ƙasa mai kyau, suka yi girma, suka ba da amfani riɓi ɗari-ɗari, fiye da abin da aka shuka.” Da faɗin haka sai ya ce, “Duk mai kunnen ji, yă ji.” ");
INSERT INTO hausa_vpl VALUES ("LK8_9","072_8_9","LUK","8","9","9","Almajiransa suka tambaye shi ma’anar wannan misali. ");
INSERT INTO hausa_vpl VALUES ("LK8_10","072_8_10","LUK","8","10","10","Sai ya ce, “Ku ne aka ba sanin asirin mulkin Allah, amma ga sauran mutane kam, ina magana da misalai, saboda, “ ‘ko da yake suna kallo, ba za su gani ba, ko da yake suna ji, ba za su gane ba.’ ");
INSERT INTO hausa_vpl VALUES ("LK8_11","072_8_11","LUK","8","11","11","“Ga ma’anar misalin, irin, shi ne maganar Allah. ");
INSERT INTO hausa_vpl VALUES ("LK8_12","072_8_12","LUK","8","12","12","Waɗanda suka fāɗi a kan hanya su ne mutanen da suka ji, amma Iblis, yakan zo ya ɗauke maganar daga zuciyarsu, don kada su gaskata, su sami ceto. ");
INSERT INTO hausa_vpl VALUES ("LK8_13","072_8_13","LUK","8","13","13","Na kan dutse kuwa, su ne da jin maganar, sukan karɓa da murna, amma ba su da saiwa. Sukan gaskata na ɗan lokaci, amma lokacin gwaji, sai su ja da baya. ");
INSERT INTO hausa_vpl VALUES ("LK8_14","072_8_14","LUK","8","14","14","Irin da suka fāɗi a cikin ƙaya kuwa, su ne mutanen da suka ji, amma a kwana a tashi, tunanin kayan duniya, da neman arziki, da son jin daɗi, sukan hana su ba da ’ya’ya. ");
INSERT INTO hausa_vpl VALUES ("LK8_15","072_8_15","LUK","8","15","15","Amma irin da suka fāɗi a ƙasa mai kyau kuwa, su ne mutane masu kyakkyawar zuciya, mai kyau, da suka ji, suka riƙe, suka kuma jimre har suka ba da ’ya’ya.” ");
INSERT INTO hausa_vpl VALUES ("LK8_16","072_8_16","LUK","8","16","16","“Ba mai ƙuna fitila sa’an nan ya ɓoye ta a cikin tulu, ko kuma ya sa ta a ƙarƙashin gado ba. A maimakon haka, yakan sa ta a kan wurin ajiye fitila, saboda mutane masu shigowa su ga haske. ");
INSERT INTO hausa_vpl VALUES ("LK8_17","072_8_17","LUK","8","17","17","Ba abin da yake ɓoye da ba za a fallasa ba. Kuma ba abin da yake rufe, da ba za a sani ba, ko a fitar da shi a fili ba. ");
INSERT INTO hausa_vpl VALUES ("LK8_18","072_8_18","LUK","8","18","18","Saboda haka, ku yi tunani da kyau yadda kuke saurara. Duk wanda yake da shi, za a ƙara masa, duk wanda ba shi da shi kuma, abin da yake tsammani yana da shi ma, za a karɓe daga gare shi.” ");
INSERT INTO hausa_vpl VALUES ("LK8_19","072_8_19","LUK","8","19","19","Sai uwar Yesu da ’yan’uwansa suka zo, domin su gan shi, amma ba su iya zuwa kusa da shi ba, saboda taron. ");
INSERT INTO hausa_vpl VALUES ("LK8_20","072_8_20","LUK","8","20","20","Sai wani ya faɗa masa cewa, “Ga uwarka da ’yan’uwanka suna tsaye a waje suna so su gan ka.” ");
INSERT INTO hausa_vpl VALUES ("LK8_21","072_8_21","LUK","8","21","21","Ya amsa ya ce, “Mahaifiyata da ’yan’uwana, su ne waɗanda suke jin maganar Allah, suna kuma aikata ta.” ");
INSERT INTO hausa_vpl VALUES ("LK8_22","072_8_22","LUK","8","22","22","Wata rana Yesu ya ce wa almajiransa, “Mu haye zuwa wancan gefen tafkin.” Sai suka shiga jirgin ruwa suka fara tafiya. ");
INSERT INTO hausa_vpl VALUES ("LK8_23","072_8_23","LUK","8","23","23","Da suna cikin tafiya, sai barci ya kwashe shi. Sai wata babban iska ta taso kan tafkin, har ruwa ya fara shiga cikin jirgin. Suka shiga babban hatsari. ");
INSERT INTO hausa_vpl VALUES ("LK8_24","072_8_24","LUK","8","24","24","Almajiran suka je suka tashe shi daga barci, suka ce, “Ubangiji, Ubangiji, za mu nutse!” Ya tashi ya kwaɓe iskar da kuma haukar ruwan. Sai ruwan da iskar suka natsu. Kome ya yi tsit. ");
INSERT INTO hausa_vpl VALUES ("LK8_25","072_8_25","LUK","8","25","25","Sai ya tambayi almajiransa, “Ina bangaskiyarku?” A cikin tsoro da mamaki, suka ce wa junansu, “Wane ne wannan? Yana ba da umarni ga iska da ruwa ma, kuma suna biyayya da shi?” ");
INSERT INTO hausa_vpl VALUES ("LK8_26","072_8_26","LUK","8","26","26","Suka shiga jirgin ruwa zuwa yankin Gerasenawa da yake a hayin tafkin, daga wajen Galili. ");
INSERT INTO hausa_vpl VALUES ("LK8_27","072_8_27","LUK","8","27","27","Da Yesu ya sauka daga jirgin, sai ga wani mutum mai aljanu daga garin. Mutumin ya daɗe bai sa tufafi ba, kuma ba ya zama a gida. Yana zama a cikin kaburbura. ");
INSERT INTO hausa_vpl VALUES ("LK8_28","072_8_28","LUK","8","28","28","Da ya ga Yesu, sai mutumin ya ɗaga murya da ƙarfi, ya fāɗi a gabansa, yana ihu cewa, “Ina ruwanka da ni, Yesu, Ɗan Allah Mafi Ɗaukaka? Ina roƙonka, kada ka ba ni wahala!” ");
INSERT INTO hausa_vpl VALUES ("LK8_29","072_8_29","LUK","8","29","29","Gama Yesu ya riga ya umarci mugun ruhun ya fita daga mutumin. Sau da yawa mugun ruhun ya sha kamunsa. Ko da yake akan daure shi hannu da ƙafa, da sarƙa, a kuma yi gadinsa, amma yakan tsinke sarƙoƙinsa, aljanun kuma su kore shi zuwa wuraren kaɗaici, inda ba kowa. ");
INSERT INTO hausa_vpl VALUES ("LK8_30","072_8_30","LUK","8","30","30","Yesu ya tambaye shi, “Mene ne sunanka?” Sai ya amsa, “Tuli,” gama aljanu masu ɗumbun yawa ne suna cikinsa. ");
INSERT INTO hausa_vpl VALUES ("LK8_31","072_8_31","LUK","8","31","31","Suka yi ta roƙonsa kada yă umarce su su shiga ramin Abis. ");
INSERT INTO hausa_vpl VALUES ("LK8_32","072_8_32","LUK","8","32","32","A wurin kuwa, akwai babban garken aladu da suke kiwo a gefen tudu. Aljanun suka roƙi Yesu ya bar su, su shiga cikin aladun, ya kuwa yardar musu. ");
INSERT INTO hausa_vpl VALUES ("LK8_33","072_8_33","LUK","8","33","33","Da aljanun suka fita daga cikin mutumin, sai suka shiga cikin aladun. Garken kuma ya gangara daga kan tudun zuwa cikin tafkin, kuma suka nutse. ");
INSERT INTO hausa_vpl VALUES ("LK8_34","072_8_34","LUK","8","34","34","Da masu kiwon aladun suka ga abin da ya faru, sai suka ruga da gudu zuwa garin da kewaye suka kai labari. ");
INSERT INTO hausa_vpl VALUES ("LK8_35","072_8_35","LUK","8","35","35","Mutanen kuma suka fito don su ga abin da ya faru. Da suka iso wurin Yesu, sai suka tarar da mutumin da aljanun suka fita daga cikinsa, yana zaune kusa da Yesu sanye da tufafi, kuma cikin hankalinsa, sai tsoro ya kama su. ");
INSERT INTO hausa_vpl VALUES ("LK8_36","072_8_36","LUK","8","36","36","Waɗanda suka ga abin da faru, suka gaya wa mutanen yadda aka warkar da mai aljanun. ");
INSERT INTO hausa_vpl VALUES ("LK8_37","072_8_37","LUK","8","37","37","Sai dukan mutanen yankin Gerasenawa suka roƙi Yesu ya bar su, don sun tsorata sosai. Sai Yesu ya shiga jirgin ruwa ya tafi. ");
INSERT INTO hausa_vpl VALUES ("LK8_38","072_8_38","LUK","8","38","38","Mutumin da aka fitar da aljanun daga cikinsa, ya roƙi Yesu don yă tafi tare da shi, amma Yesu ya sallame shi ya ce, ");
INSERT INTO hausa_vpl VALUES ("LK8_39","072_8_39","LUK","8","39","39","“Koma gida, ka shaida babban alherin da Allah ya yi maka.” Sai mutumin ya tafi yana faɗin abin da Yesu ya yi masa a duk garin. ");
INSERT INTO hausa_vpl VALUES ("LK8_40","072_8_40","LUK","8","40","40","Da Yesu ya koma, taron suka marabce shi, don dā ma duk suna jiransa. ");
INSERT INTO hausa_vpl VALUES ("LK8_41","072_8_41","LUK","8","41","41","Sai wani mutum mai suna Yayirus, wani mai mulkin majami’a, ya zo ya fāɗi a gaban Yesu, yana roƙonsa ya zo gidansa, ");
INSERT INTO hausa_vpl VALUES ("LK8_42","072_8_42","LUK","8","42","42","domin diyarsa ɗaya tak, wadda ta kai shekara goma sha biyu, tana bakin mutuwa. Da Yesu yake kan hanyarsa, taron mutane masu yawa suka yi ta matsa shi a kowane gefe. ");
INSERT INTO hausa_vpl VALUES ("LK8_43","072_8_43","LUK","8","43","43","A wurin kuwa, akwai wata mace wadda tana da ciwon zubar da jini, har na shekara goma sha biyu, amma babu wanda ya iya warkar da ita. ");
INSERT INTO hausa_vpl VALUES ("LK8_44","072_8_44","LUK","8","44","44","Sai ta zo ta bayansa, ta taɓa bakin rigarsa. Nan da nan, zubar da jininta ya tsaya. ");
INSERT INTO hausa_vpl VALUES ("LK8_45","072_8_45","LUK","8","45","45","Yesu ya yi tambaya, “Wa ya taɓa ni?” Bayan kowa ya yi musu, sai Bitrus ya ce, “Ubangiji, ai, mutane da yawa suna matsinka ta kowane gefe.” ");
INSERT INTO hausa_vpl VALUES ("LK8_46","072_8_46","LUK","8","46","46","Amma Yesu ya ce, “Wani ya taɓa ni, na san cewa iko ya fita daga wurina.” ");
INSERT INTO hausa_vpl VALUES ("LK8_47","072_8_47","LUK","8","47","47","Sai macen, da ta ga ba halin ɓoyewa, sai ta fita, jikinta na rawa, ta fāɗi a gabansa. A gaban dukan mutanen, ta faɗi dalilin da ya sa ta taɓa shi, da yadda ta warke nan take. ");
INSERT INTO hausa_vpl VALUES ("LK8_48","072_8_48","LUK","8","48","48","Sai Yesu ya ce mata, “Diyata, bangaskiyarki ta warkar da ke. Ki sauka lafiya.” ");
INSERT INTO hausa_vpl VALUES ("LK8_49","072_8_49","LUK","8","49","49","Yayinda Yesu na cikin magana har yanzu, sai ga wani daga gidan Yayirus, mai mulkin majami’ar ya ce, “Kada ka ƙara damun malam, diyarka ta rasu.” ");
INSERT INTO hausa_vpl VALUES ("LK8_50","072_8_50","LUK","8","50","50","Da Yesu ya ji wannan, sai ya ce wa Yayirus, “Kada ka ji tsoro, ka gaskata, za a kuma warkar da ita.” ");
INSERT INTO hausa_vpl VALUES ("LK8_51","072_8_51","LUK","8","51","51","Da ya iso gidan Yayirus, sai ya hana kowa yă bi shi cikin ɗakin, sai dai Bitrus, da Yohanna, da Yaƙub, da kuma mahaifin da mahaifiyar. ");
INSERT INTO hausa_vpl VALUES ("LK8_52","072_8_52","LUK","8","52","52","Ana cikin haka, dukan mutanen kuma sai kuka da makoki suke ta yi, domin yarinyar. Sai Yesu ya ce, “Ka daina yin kuka, ba tă mutu ba, tana barci ne.” ");
INSERT INTO hausa_vpl VALUES ("LK8_53","072_8_53","LUK","8","53","53","Sai suka yi masa dariya, da yake sun san cewa, ta mutu. ");
INSERT INTO hausa_vpl VALUES ("LK8_54","072_8_54","LUK","8","54","54","Amma Yesu ya kama ta a hannu ya ce, “Diyata, tashi.” ");
INSERT INTO hausa_vpl VALUES ("LK8_55","072_8_55","LUK","8","55","55","Ruhunta ya dawo, kuma ta tashi, nan take. Yesu ya ce musu, su ba ta wani abu tă ci. ");
INSERT INTO hausa_vpl VALUES ("LK8_56","072_8_56","LUK","8","56","56","Iyayenta suka yi mamaki, amma ya ba su umarni kada su faɗa wa kowa abin da ya faru. ");
INSERT INTO hausa_vpl VALUES ("LK9_1","072_9_1","LUK","9","1","1","Bayan da Yesu ya tara Sha Biyun wuri ɗaya, sai ya ba su iko da izini na fitar da dukan aljanu, da na warkar da cututtuka. ");
INSERT INTO hausa_vpl VALUES ("LK9_2","072_9_2","LUK","9","2","2","Ya kuma aike su, su yi wa’azin mulkin Allah, su kuma warkar da marasa lafiya. ");
INSERT INTO hausa_vpl VALUES ("LK9_3","072_9_3","LUK","9","3","3","Ya ce musu, “Kada ku ɗauki kome don tafiyar, wato, ba sanda, ba jaka, ba burodi, ba kuɗi, ba riga na biyu. ");
INSERT INTO hausa_vpl VALUES ("LK9_4","072_9_4","LUK","9","4","4","Duk gidan da kuka sauka, ku zauna nan sai kun bar garin. ");
INSERT INTO hausa_vpl VALUES ("LK9_5","072_9_5","LUK","9","5","5","In mutane ba su karɓe ku ba, sa’ad da kun bar garinsu, ku karkaɗe ƙurar ƙafafunku don shaida a kansu.” ");
INSERT INTO hausa_vpl VALUES ("LK9_6","072_9_6","LUK","9","6","6","Sai suka tashi suka shiga ƙauye zuwa ƙauye suna wa’azin bishara, suna warkar da marasa lafiya a ko’ina. ");
INSERT INTO hausa_vpl VALUES ("LK9_7","072_9_7","LUK","9","7","7","Yanzu fa, Hiridus mai sarauta ya ji labarin dukan abubuwan da suke faruwa. Sai ya rikice, don waɗansu mutane suna cewa, Yohanna Mai Baftisma ne ya tashi daga matattu, ");
INSERT INTO hausa_vpl VALUES ("LK9_8","072_9_8","LUK","9","8","8","waɗansu kuma suna cewa, annabi Iliya ne ya sāke bayyana. Waɗansu kuma har wa yau, suna cewa, ɗaya daga cikin annabawa na dā ne, ya tashi. ");
INSERT INTO hausa_vpl VALUES ("LK9_9","072_9_9","LUK","9","9","9","Amma Hiridus ya ce, “Yohanna dai na yanke kansa, amma wanne mutum ne nake jin labarin abubuwan nan a kansa?” Sai ya yi ƙoƙari ya ga Yesu. ");
INSERT INTO hausa_vpl VALUES ("LK9_10","072_9_10","LUK","9","10","10","Da manzannin suka dawo, sai suka faɗa wa Yesu abin da suka yi. Sai ya ɗauke su, suka keɓe kansu su kaɗai, zuwa wani gari da ake kira Betsaida. ");
INSERT INTO hausa_vpl VALUES ("LK9_11","072_9_11","LUK","9","11","11","Amma taron mutane suka ji labari, sai suka bi shi. Ya marabce su, kuma ya yi musu magana a kan mulkin Allah, ya kuma warkar da masu bukatar warkarwa. ");
INSERT INTO hausa_vpl VALUES ("LK9_12","072_9_12","LUK","9","12","12","Da rana ta kusa fāɗuwa, sai Sha Biyun suka zo wurinsa, suka ce, “Ka sallami taron domin su shiga ƙauyuka na kewaye, su nemi abin da za su ci, da wurin kwana, don inda muke, ba kowa.” ");
INSERT INTO hausa_vpl VALUES ("LK9_13","072_9_13","LUK","9","13","13","Yesu ya ce, “Ku, ku ba su wani abu su ci.” Sai suka ce masa, “Muna da burodi biyar da kifi biyu kaɗai. Sai dai, in mun je mu sayi abinci domin dukan wannan taron.” ");
INSERT INTO hausa_vpl VALUES ("LK9_14","072_9_14","LUK","9","14","14","Maza kaɗai sun kai kusan dubu biyar. Amma ya ce wa almajiransa, “Ku sa su su zauna a ƙungiya hamsin-hamsin.” ");
INSERT INTO hausa_vpl VALUES ("LK9_15","072_9_15","LUK","9","15","15","Haka almajiran suka yi, kowa kuwa ya zauna. ");
INSERT INTO hausa_vpl VALUES ("LK9_16","072_9_16","LUK","9","16","16","Sai Yesu ya ɗauki burodin biyar da kifin biyun, ya ɗaga kansa sama, ya yi godiya, ya kuma kakkarya su. Ya ba wa almajiransa, domin su rarraba wa mutanen. ");
INSERT INTO hausa_vpl VALUES ("LK9_17","072_9_17","LUK","9","17","17","Duka kuwa suka ci suka ƙoshi. Almajiran suka kwashe ragowar gutsattsarin cike da kwanduna goma sha biyu. ");
INSERT INTO hausa_vpl VALUES ("LK9_18","072_9_18","LUK","9","18","18","Wata rana sa’ad da Yesu yana addu’a a ɓoye, almajiransa kuma suna tare da shi, sai ya tambaye, su ya ce, “Wa, taron mutane ke ce da ni?” ");
INSERT INTO hausa_vpl VALUES ("LK9_19","072_9_19","LUK","9","19","19","Suka amsa, suka ce, “Waɗansu suna cewa, Yohanna Mai Baftisma, waɗansu kuma annabi Iliya, har wa yau waɗansu suna cewa, kai ɗaya daga cikin annabawan da ne, da ya tashi da rai.” ");
INSERT INTO hausa_vpl VALUES ("LK9_20","072_9_20","LUK","9","20","20","“Amma ku fa, wa, kuke ce da ni?” Bitrus ya amsa ya ce, “Kiristi na Allah.” ");
INSERT INTO hausa_vpl VALUES ("LK9_21","072_9_21","LUK","9","21","21","Yesu ya gargaɗe su da ƙarfi, kada su gaya wa kowa wannan magana. ");
INSERT INTO hausa_vpl VALUES ("LK9_22","072_9_22","LUK","9","22","22","Ya sāke cewa, “Dole ne Ɗan mutum ya sha wahaloli da yawa, dattawa, da manyan firistoci, da malaman dokoki kuma su ƙi shi, kuma dole a kashe shi, a rana ta uku kuma a tā da shi da rai.” ");
INSERT INTO hausa_vpl VALUES ("LK9_23","072_9_23","LUK","9","23","23","Sai ya ce wa dukansu, “In wani zai bi ni, dole yă mūsanta kansa, ya ɗauki gicciyensa kowace rana, ya bi ni. ");
INSERT INTO hausa_vpl VALUES ("LK9_24","072_9_24","LUK","9","24","24","Gama duk mai son ceton ransa zai rasa shi, amma duk wanda ya rasa ransa saboda ni zai same shi. ");
INSERT INTO hausa_vpl VALUES ("LK9_25","072_9_25","LUK","9","25","25","Ina amfani, in mutum ya ribato duniya duka, amma ya rasa ransa, ko kuma ya yi hasarar ransa. ");
INSERT INTO hausa_vpl VALUES ("LK9_26","072_9_26","LUK","9","26","26","Duk wanda yake jin kunyana da na kalmomina, Ɗan Mutum ma zai ji kunyarsa sa’ad da zai zo a cikin ɗaukakarsa, da ɗaukakar Uban, da kuma ta tsarkaka mala’ikun. ");
INSERT INTO hausa_vpl VALUES ("LK9_27","072_9_27","LUK","9","27","27","“Gaskiya nake gaya muku, waɗansu da suke tsattsaye a nan ba za su ga mutuwa ba, sai sun ga mulkin Allah.” ");
INSERT INTO hausa_vpl VALUES ("LK9_28","072_9_28","LUK","9","28","28","Bayan kamar kwana takwas da yin wannan magana, sai Yesu ya ɗauki Bitrus, da Yohanna, da kuma Yaƙub, suka hau kan dutse tare don yin addu’a. ");
INSERT INTO hausa_vpl VALUES ("LK9_29","072_9_29","LUK","9","29","29","Yana cikin addu’a, sai kamannin fuskarsa ta sāke, tufafinsa kuma suka zama da haske kamar hasken walƙiya. ");
INSERT INTO hausa_vpl VALUES ("LK9_30","072_9_30","LUK","9","30","30","Sai ga mutum biyu, Musa da Iliya, suka bayyana cikin kyakkyawar daraja, suna magana da Yesu. ");
INSERT INTO hausa_vpl VALUES ("LK9_31","072_9_31","LUK","9","31","31","Suka yi zance a kan tashinsa, wanda shi ya kusan ya kawo ga cikarsa a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("LK9_32","072_9_32","LUK","9","32","32","Barci kuwa ya kama Bitrus da abokan tafiyarsa sosai. Da idanunsu suka warware, sai suka ga ɗaukakarsa da kuma mutum biyun tsaye tare da shi. ");
INSERT INTO hausa_vpl VALUES ("LK9_33","072_9_33","LUK","9","33","33","Da mutanen na barin Yesu, sai Bitrus ya ce masa, “Ubangiji, ya yi kyau da muke nan. Bari mu kafa bukkoki guda uku, wato, ɗaya dominka, ɗaya domin Musa, ɗaya kuma domin Iliya.” (Bai ma san abin da yake faɗi ba.) ");
INSERT INTO hausa_vpl VALUES ("LK9_34","072_9_34","LUK","9","34","34","Yayinda yake cikin magana, sai wani girgije ya bayyana ya rufe su, sai suka ji tsoro, yayinda suke shiga cikin girgijen. ");
INSERT INTO hausa_vpl VALUES ("LK9_35","072_9_35","LUK","9","35","35","Wata murya ta fito daga cikin girgijen, tana cewa, “Wannan Ɗana ne, zaɓaɓɓena, ku saurare shi.” ");
INSERT INTO hausa_vpl VALUES ("LK9_36","072_9_36","LUK","9","36","36","Da muryar ta gama magana, sai suka tarar Yesu shi kaɗai ne. Almajiran kuwa suka riƙe wannan al’amari a zukatansu. A lokacin nan, ba su gaya wa kowa abin da suka gani ba. ");
INSERT INTO hausa_vpl VALUES ("LK9_37","072_9_37","LUK","9","37","37","Kashegari, sa’ad da Yesu tare da almajiran nan uku suka sauka daga kan dutsen, sai taro mai yawa ya haɗu da shi. ");
INSERT INTO hausa_vpl VALUES ("LK9_38","072_9_38","LUK","9","38","38","Sai wani mutum daga cikin taron ya yi kira da ƙarfi ya ce, “Malam, ina roƙonka, ka dubi ɗan nan nawa, gama shi ne kaɗai nake da shi. ");
INSERT INTO hausa_vpl VALUES ("LK9_39","072_9_39","LUK","9","39","39","Wani ruhu yakan kama shi, sai ya yi ihu farar ɗaya. Yakan sa shi farfaɗiya, har bakinsa ya yi kumfa. Da ƙyar yake barinsa, yana kuwa kan hallakar da shi. ");
INSERT INTO hausa_vpl VALUES ("LK9_40","072_9_40","LUK","9","40","40","Na roƙi almajiranka su fitar da shi, amma ba su iya ba.” ");
INSERT INTO hausa_vpl VALUES ("LK9_41","072_9_41","LUK","9","41","41","Yesu ya amsa ya ce, “Ya karkataccen zamani marar bangaskiya, har yaushe ne zan kasance tare da ku, ina kuma haƙuri da ku? Kawo yaronka nan.” ");
INSERT INTO hausa_vpl VALUES ("LK9_42","072_9_42","LUK","9","42","42","Yaron yana kan zuwa ke nan, sai aljanin ya buga shi ƙasa, cikin farfaɗiya. Amma Yesu ya kwaɓe mugun ruhun, ya warkar da yaron, sai ya miƙa shi ga mahaifinsa. ");
INSERT INTO hausa_vpl VALUES ("LK9_43","072_9_43","LUK","9","43","43","Duk suka yi mamakin girman Allah. Yayinda kowa yana cikin mamakin dukan abubuwan da Yesu ya yi, sai ya ce wa almajiransa, ");
INSERT INTO hausa_vpl VALUES ("LK9_44","072_9_44","LUK","9","44","44","“Ku kasa kunne da kyau ga abin da zan faɗa muku. Za a bashe Ɗan Mutum ga hannun mutane.” ");
INSERT INTO hausa_vpl VALUES ("LK9_45","072_9_45","LUK","9","45","45","Amma ba su fahimci abin da yake nufi da wannan magana ba. Ba su gane ba, don an ɓoye musu shi. Su kuwa sun ji tsoro su tambaye shi. ");
INSERT INTO hausa_vpl VALUES ("LK9_46","072_9_46","LUK","9","46","46","Wata gardama ta tashi a tsakanin almajiran, a kan ko wane ne a cikinsu zai zama mafi girma ");
INSERT INTO hausa_vpl VALUES ("LK9_47","072_9_47","LUK","9","47","47","Da yake Yesu ya san tunaninsu, sai ya ɗauki wani ƙaramin yaro, ya sa ya tsaya kusa da shi. ");
INSERT INTO hausa_vpl VALUES ("LK9_48","072_9_48","LUK","9","48","48","Sai ya ce musu, “Duk wanda ya karɓi wannan ƙaramin yaron a cikin sunana, ni ya karɓa, kuma duk wanda ya karɓe ni, ya karɓi wanda ya aiko ni ne. Gama mafi ƙanƙanta duka a cikinku, shi ne kuma mafi girma.” ");
INSERT INTO hausa_vpl VALUES ("LK9_49","072_9_49","LUK","9","49","49","Sai Yohanna ya ce, “Ubangiji, mun ga wani mutum yana fitar da aljanu a cikin sunanka, muka yi ƙoƙarin hana shi, don shi ba ɗaya ba ne daga cikinmu.” ");
INSERT INTO hausa_vpl VALUES ("LK9_50","072_9_50","LUK","9","50","50","Yesu ya ce, “Kada ku hana shi, gama duk wanda ba ya gāba da ku, naku ne.” ");
INSERT INTO hausa_vpl VALUES ("LK9_51","072_9_51","LUK","9","51","51","Da lokaci ya yi kusa da za a ɗauki Yesu zuwa sama, sai ya ɗaura niyyar tafiya Urushalima. ");
INSERT INTO hausa_vpl VALUES ("LK9_52","072_9_52","LUK","9","52","52","Sai ya aiki ’yan saƙo, su yi gaba. Su kuwa, suka shiga cikin wani ƙauyen Samariyawa, don su shirya masa abubuwa. ");
INSERT INTO hausa_vpl VALUES ("LK9_53","072_9_53","LUK","9","53","53","Amma mutanen ƙauyen ba su karɓe shi ba, don yana kan hanyar zuwa Urushalima ne. ");
INSERT INTO hausa_vpl VALUES ("LK9_54","072_9_54","LUK","9","54","54","Da almajiransa, Yaƙub da Yohanna suka ga haka, sai suka yi tambaya suka ce, “Ubangiji, kana so mu kira wuta ta sauka daga sama ta hallaka su?” ");
INSERT INTO hausa_vpl VALUES ("LK9_55","072_9_55","LUK","9","55","55","Amma Yesu ya juya, ya kwaɓe su. ");
INSERT INTO hausa_vpl VALUES ("LK9_56","072_9_56","LUK","9","56","56","Sai shi da almajiransa suka tafi wani ƙauye. ");
INSERT INTO hausa_vpl VALUES ("LK9_57","072_9_57","LUK","9","57","57","Suna kan tafiya a hanya, sai wani mutum ya ce masa, “Zan bi ka, duk inda za ka.” ");
INSERT INTO hausa_vpl VALUES ("LK9_58","072_9_58","LUK","9","58","58","Yesu ya ce, “Yanyawa suna da ramummuka, tsuntsayen sararin sama suna da sheƙuna, amma Ɗan Mutum ba shi da wurin da zai sa kansa.” ");
INSERT INTO hausa_vpl VALUES ("LK9_59","072_9_59","LUK","9","59","59","Ya kuma ce wa wani mutum, “Ka bi ni.” Amma mutumin ya amsa ya ce, “Ubangiji, bari in je in binne mahaifina tukuna.” ");
INSERT INTO hausa_vpl VALUES ("LK9_60","072_9_60","LUK","9","60","60","Yesu ya ce masa, “Ka bar matattu su binne matattunsu, amma kai, ka je ka yi shelar mulkin Allah.” ");
INSERT INTO hausa_vpl VALUES ("LK9_61","072_9_61","LUK","9","61","61","Har wa yau, wani ya ce, “Zan bi ka, Ubangiji, amma ka bar ni in je in yi bankwana da iyalina tukuna.” ");
INSERT INTO hausa_vpl VALUES ("LK9_62","072_9_62","LUK","9","62","62","Yesu ya amsa ya ce, “Babu wani da yakan sa hannunsa a garman shanu, sa’an nan ya waiwaya baya, da ya isa ya shiga hidima a cikin mulkin Allah ba.” ");
INSERT INTO hausa_vpl VALUES ("LK10_1","072_10_1","LUK","10","1","1","Bayan haka, Ubangiji ya naɗa waɗansu mutum saba’in da biyu, ya aike su biyu-biyu, su riga shi yin gaba zuwa kowane gari da kowane wuri da zai shiga. ");
INSERT INTO hausa_vpl VALUES ("LK10_2","072_10_2","LUK","10","2","2","Ya ce musu, “Girbi na da yawa, amma ma’aikata kaɗan ne. Saboda haka, ku roƙi Ubangijin girbi ya aikar da ma’aikata zuwa gonarsa. ");
INSERT INTO hausa_vpl VALUES ("LK10_3","072_10_3","LUK","10","3","3","Ku tafi! Ina aikan ku kamar tumaki cikin kyarketai. ");
INSERT INTO hausa_vpl VALUES ("LK10_4","072_10_4","LUK","10","4","4","Kada ku ɗauki jakar kuɗi, ko jaka, ko takalma. Kada ma ku gai da kowa a kan hanya. ");
INSERT INTO hausa_vpl VALUES ("LK10_5","072_10_5","LUK","10","5","5","“Sa’ad da kuka shiga wani gida, ku fara da cewa, ‘Salama a gare ku mutanen gida.’ ");
INSERT INTO hausa_vpl VALUES ("LK10_6","072_10_6","LUK","10","6","6","In akwai mutum mai salama a gidan, salamarku za tă kasance tare da shi, in kuwa babu, salamarku za tă koma muku. ");
INSERT INTO hausa_vpl VALUES ("LK10_7","072_10_7","LUK","10","7","7","Ku zauna a wannan gidan, kuna ci kuna shan duk abin da suka ba ku, gama ma’aikaci ya cancanci albashinsa. Kada ku yi yawan sāke masauƙi, daga gida zuwa gida. ");
INSERT INTO hausa_vpl VALUES ("LK10_8","072_10_8","LUK","10","8","8","“Sa’ad da kuka shiga garin, kuma aka karɓe ku, ku ci ko mene ne da aka ajiye a gabanku. ");
INSERT INTO hausa_vpl VALUES ("LK10_9","072_10_9","LUK","10","9","9","Ku warkar da marasa lafiya da suke wurin. Ku kuma faɗa musu cewa, ‘Mulkin Allah yana kusa da ku.’ ");
INSERT INTO hausa_vpl VALUES ("LK10_10","072_10_10","LUK","10","10","10","Amma sa’ad da kuka shiga garin, kuma ba a karɓe ku ba, ku bi titi-titi ku ce, ");
INSERT INTO hausa_vpl VALUES ("LK10_11","072_10_11","LUK","10","11","11","‘Ko ƙurar garinku da kuke manne a ƙafafunmu, mun karkaɗe muku. Duk da haka, ku tabbatar da wannan, “Mulkin Allah yana kusa.” ’ ");
INSERT INTO hausa_vpl VALUES ("LK10_12","072_10_12","LUK","10","12","12","Ina dai faɗa muku, a ranan nan, za a fi jin tausayin Sodom fiye da wannan garin. ");
INSERT INTO hausa_vpl VALUES ("LK10_13","072_10_13","LUK","10","13","13","“ ‘Kaitonki, Korazin! Kaitonki, Betsaida!’ Ai, da a ce a Taya da Sidon ne aka yi ayyukan banmamaki da aka yi a cikinku, da tuni sun tuba, suna zama cikin rigar makoki da toka. ");
INSERT INTO hausa_vpl VALUES ("LK10_14","072_10_14","LUK","10","14","14","A ranar shari’a, za a fi jin tausayin Taya da Sidon fiye da ku. ");
INSERT INTO hausa_vpl VALUES ("LK10_15","072_10_15","LUK","10","15","15","Ke kuma Kafarnahum, kina tsammani za ki sami ɗaukaka ne? A’a, za a hallaka ki. ");
INSERT INTO hausa_vpl VALUES ("LK10_16","072_10_16","LUK","10","16","16","“Wanda ya saurare ku, ni yake saurara. Wanda ya ƙi ku, ni yake ƙi. Amma wanda ya ƙi ni kuwa, ya ƙi wanda ya aiko ni ne.” ");
INSERT INTO hausa_vpl VALUES ("LK10_17","072_10_17","LUK","10","17","17","Mutum saba’in da biyun nan suka dawo da murna, suka ce, “Ubangiji, har mun sha ƙarfin aljanu ma a cikin sunanka.” ");
INSERT INTO hausa_vpl VALUES ("LK10_18","072_10_18","LUK","10","18","18","Sai ya amsa ya ce, “Na ga Shaiɗan ya fāɗi daga sama kamar walƙiya. ");
INSERT INTO hausa_vpl VALUES ("LK10_19","072_10_19","LUK","10","19","19","Na ba ku iko da za ku tattaka macizai, da kunamai, ku kuma shawo kan dukan ikon abokin gāba, kuma ba wani lahani da zai same ku. ");
INSERT INTO hausa_vpl VALUES ("LK10_20","072_10_20","LUK","10","20","20","Duk da haka, kada ku yi farin ciki da cewa, kun sha ƙarfin ruhohi, amma ku yi farin ciki, domin an rubuta sunayenku a sama.” ");
INSERT INTO hausa_vpl VALUES ("LK10_21","072_10_21","LUK","10","21","21","A wannan lokaci, Yesu, cike da murna ta wurin Ruhu Mai Tsarki ya ce, “Na yabe ka, ya Uba, Ubangijin sama da ƙasa, domin ka ɓoye waɗannan abubuwa ga masu hikima, da masu ilimi, ka kuma bayyana su ga ƙananan yara. I, ya Uba, gama wannan shi ne nufinka mai kyau. ");
INSERT INTO hausa_vpl VALUES ("LK10_22","072_10_22","LUK","10","22","22","“Ubana ya danƙa mini dukan kome. Ba wanda ya san Ɗan sai Uban, kuma ba wanda ya san Uban, sai Ɗan, da kuma waɗanda Ɗan ya zaɓa ya bayyana musu shi.” ");
INSERT INTO hausa_vpl VALUES ("LK10_23","072_10_23","LUK","10","23","23","Sai ya juya wajen almajiransa, ya ce musu a ɓoye, “Albarka ga idanun da suka ga abin da kuke gani. ");
INSERT INTO hausa_vpl VALUES ("LK10_24","072_10_24","LUK","10","24","24","Ina faɗa muku, annabawa da sarakuna da yawa sun so su ga abin nan da kuke gani, amma ba su gani ba. Sun so su ji abin da kuke ji, amma ba su ji ba.” ");
INSERT INTO hausa_vpl VALUES ("LK10_25","072_10_25","LUK","10","25","25","Wata rana, sai wani masanin dokoki ya miƙe tsaye don yă gwada Yesu. Ya tambaya ya ce, “Malam, me zan yi don in gāji rai madawwami?” ");
INSERT INTO hausa_vpl VALUES ("LK10_26","072_10_26","LUK","10","26","26","Yesu ya amsa ya ce, “Me aka rubuta a cikin Doka? Yaya kake karanta ta?” ");
INSERT INTO hausa_vpl VALUES ("LK10_27","072_10_27","LUK","10","27","27","Sai ya amsa ya ce, “ ‘Ka ƙaunaci Ubangiji Allahnka da dukan zuciyarka, da dukan ranka, da dukan ƙarfinka, da kuma dukan hankalinka’; kuma, ‘Ka ƙaunaci maƙwabcinka kamar kanka.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK10_28","072_10_28","LUK","10","28","28","Yesu ya ce, “Ka amsa daidai. Ka yi haka, kuma za ka rayu.” ");
INSERT INTO hausa_vpl VALUES ("LK10_29","072_10_29","LUK","10","29","29","Amma domin ya kāre kansa, sai ya tambayi Yesu ya ce, “Shin, wane ne maƙwabcina?” ");
INSERT INTO hausa_vpl VALUES ("LK10_30","072_10_30","LUK","10","30","30","Yesu ya amsa ya ce, “Wani mutum ya tashi daga Urushalima za shi Yeriko, sai ya fāɗi a hannun mafasa, wato, ’yan fashi. Suka ƙwace tufafinsa, suka yi masa dūka, suka bar shi nan bakin rai da mutuwa. ");
INSERT INTO hausa_vpl VALUES ("LK10_31","072_10_31","LUK","10","31","31","Ya zamana wani firist ya bi kan wannan hanya. Da ya ga mutumin, sai ya bi gefe ya wuce abinsa. ");
INSERT INTO hausa_vpl VALUES ("LK10_32","072_10_32","LUK","10","32","32","Haka ma wani daga kabilar Lawi, mai hidima cikin haikali, da ya zo wurin, ya gan shi, sai shi ma ya bi gefe ɗaya, ya wuce abinsa. ");
INSERT INTO hausa_vpl VALUES ("LK10_33","072_10_33","LUK","10","33","33","Amma wani mutumin Samariya da yake kan tafiya, da ya kai inda mutumin yake, ya gan shi, sai ya ji tausayinsa. ");
INSERT INTO hausa_vpl VALUES ("LK10_34","072_10_34","LUK","10","34","34","Ya je wurinsa, ya daddaure masa raunukansa, sa’an nan ya zuba mai, da ruwan inabi. Ya ɗauki mutumin ya sa a kan jakinsa, ya kai shi wani masauƙi, ya yi jinyarsa. ");
INSERT INTO hausa_vpl VALUES ("LK10_35","072_10_35","LUK","10","35","35","Kashegari, sai ya ɗauki dinari biyu, ya ba wa mai masauƙin ya ce, ‘Ka lura da shi, bayan na dawo, zan biya ka duk abin da ka ƙara kashewa a kansa.’ ");
INSERT INTO hausa_vpl VALUES ("LK10_36","072_10_36","LUK","10","36","36","“A ganinka, a cikin waɗannan mutane uku, wane ne maƙwabcin mutumin da ya fāɗi a hannun mafasa?” ");
INSERT INTO hausa_vpl VALUES ("LK10_37","072_10_37","LUK","10","37","37","Masanin dokoki ya amsa ya ce, “Wanda ya nuna masa jinƙai.” Yesu ya ce masa, “Je ka, ka yi haka nan.” ");
INSERT INTO hausa_vpl VALUES ("LK10_38","072_10_38","LUK","10","38","38","Yayinda Yesu da almajiransa suna cikin tafiya, sai ya kai wani ƙauye inda wata mace mai suna Marta ta marabce shi a gidanta. ");
INSERT INTO hausa_vpl VALUES ("LK10_39","072_10_39","LUK","10","39","39","Tana da ’yar’uwa mai suna Maryamu, wadda ta zauna a gaban Ubangiji tana jin maganarsa. ");
INSERT INTO hausa_vpl VALUES ("LK10_40","072_10_40","LUK","10","40","40","Marta kuwa, aikin hidima da ya kamata a yi, ya ɗauke mata hankali, sai ta zo wurin Yesu, ta ce, “Ubangiji, ba ka damu da yadda ’yar’uwata ta bar mini aiki ni kaɗai ba? Gaya mata ta taimake ni!” ");
INSERT INTO hausa_vpl VALUES ("LK10_41","072_10_41","LUK","10","41","41","Amma Ubangiji ya amsa ya ce, “Marta, Marta, hankalinki ya tashi, kuma kina damuwa a kan abubuwa da yawa. ");
INSERT INTO hausa_vpl VALUES ("LK10_42","072_10_42","LUK","10","42","42","Amma abu ɗaya tak ake bukata, Maryamu ta zaɓi abin da ya fi kyau, kuma ba za a raba ta da shi ba.” ");
INSERT INTO hausa_vpl VALUES ("LK11_1","072_11_1","LUK","11","1","1","Wata rana Yesu yana addu’a a wani wuri. Da ya gama, sai ɗaya daga cikin almajiransa ya ce masa, “Ubangiji, ka koya mana yin addu’a, kamar yadda Yohanna ya koya wa almajiransa.” ");
INSERT INTO hausa_vpl VALUES ("LK11_2","072_11_2","LUK","11","2","2","Sai ya ce musu, “Sa’ad da kuke yin addu’a ku ce, “ ‘Ya Uba, sunanka mai tsarki ne mulkinka ya zo. ");
INSERT INTO hausa_vpl VALUES ("LK11_3","072_11_3","LUK","11","3","3","Ka ba mu kowace rana abincin yini. ");
INSERT INTO hausa_vpl VALUES ("LK11_4","072_11_4","LUK","11","4","4","Ka gafarta mana zunubanmu, kamar yadda mu ma ke gafarta wa duk wanda ya yi mana laifi. Kada ka bari a kai mu cikin jarraba.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK11_5","072_11_5","LUK","11","5","5","Sa’an nan ya ce musu, “Da a ce ɗayanku yana da aboki, sa’an nan ya je wurinsa da tsakar dare ya ce, ‘Aboki, ranta mini burodi guda uku, ");
INSERT INTO hausa_vpl VALUES ("LK11_6","072_11_6","LUK","11","6","6","domin wani abokina da yake tafiya ya sauka a wurina. Ga shi, ba ni da abinci da zan ba shi.’ ");
INSERT INTO hausa_vpl VALUES ("LK11_7","072_11_7","LUK","11","7","7","Sai wanda yake cikin ɗaki ya amsa ya ce, ‘Kada ka dame ni. An riga an kulle ƙofa, da ni da yarana kuwa mun kwanta, ba zan iya tashi in ba ka kome ba.’ ");
INSERT INTO hausa_vpl VALUES ("LK11_8","072_11_8","LUK","11","8","8","Ina gaya muku, ko da yake ba zai so ya tashi ya ba shi burodin don shi abokinsa ne ba, duk da haka, zai tashi ya ba shi yawan abin da yake bukata, saboda nacewarsa. ");
INSERT INTO hausa_vpl VALUES ("LK11_9","072_11_9","LUK","11","9","9","“Don haka ina faɗa muku, ku roƙa, za a ba ku, ku nema za ku samu, ku ƙwanƙwasa za a kuwa buɗe muku ƙofa. ");
INSERT INTO hausa_vpl VALUES ("LK11_10","072_11_10","LUK","11","10","10","Gama duk wanda ya roƙa, yana karɓa, mai nema yana samu, wanda ya ƙwanƙwasa kuma, za a buɗe masa ƙofa. ");
INSERT INTO hausa_vpl VALUES ("LK11_11","072_11_11","LUK","11","11","11","“Wane mahaifi ne a cikinku, in ɗansa ya roƙe shi kifi, zai ba shi maciji a maimakon, ");
INSERT INTO hausa_vpl VALUES ("LK11_12","072_11_12","LUK","11","12","12","ko kuma in ya roƙi ƙwai, ya ba shi kunama? ");
INSERT INTO hausa_vpl VALUES ("LK11_13","072_11_13","LUK","11","13","13","In fa haka ne, ko da yake ku mugaye ne, kun san ba ’ya’yanku kyautai masu kyau, balle fa Ubanku na sama, zai yi fiye da haka, ta wurin ba da Ruhu Mai Tsarki, ga masu roƙonsa!” ");
INSERT INTO hausa_vpl VALUES ("LK11_14","072_11_14","LUK","11","14","14","Sa’ad da Yesu yake fitar da wani beben aljani daga wani mutum, da aljanin ya fita, sai mutumin wanda da bebe ne, ya yi magana, taron kuwa suka yi mamaki. ");
INSERT INTO hausa_vpl VALUES ("LK11_15","072_11_15","LUK","11","15","15","Amma waɗansunsu suka ce, “Ai, da ikon Be’elzebub, sarkin aljanu ne, yake fitar da aljanu.” ");
INSERT INTO hausa_vpl VALUES ("LK11_16","072_11_16","LUK","11","16","16","Waɗansu kuma suka gwada shi, ta wurin neman yă nuna musu wata alama daga sama. ");
INSERT INTO hausa_vpl VALUES ("LK11_17","072_11_17","LUK","11","17","17","Yesu kuwa ya san tunaninsu, sai ya ce musu, “Duk mulkin da yake gāba da kansa, zai lalace, kuma gidan da yake gaba da kansa zai rushe. ");
INSERT INTO hausa_vpl VALUES ("LK11_18","072_11_18","LUK","11","18","18","In Shaiɗan yana gāba da kansa, yaya mulkinsa zai tsaya? Ina faɗin haka domin kun ce, da ikon Be’elzebub nake fitar da aljanu. ");
INSERT INTO hausa_vpl VALUES ("LK11_19","072_11_19","LUK","11","19","19","In da ikon Be’elzebub nake fitar da su, to, da ikon wa masu binku suke fitar da su? Saboda haka, za su zama alƙalanku ke nan. ");
INSERT INTO hausa_vpl VALUES ("LK11_20","072_11_20","LUK","11","20","20","Amma in da ikon Allah ne ni nake fitar da aljanu, ashe, mulkin Allah ya zo muku ke nan. ");
INSERT INTO hausa_vpl VALUES ("LK11_21","072_11_21","LUK","11","21","21","“Sa’ad da mutum mai ƙarfi, wanda yake da makamai yana gadin gidan kansa, an tsare lafiyar dukiyarsa ke nan. ");
INSERT INTO hausa_vpl VALUES ("LK11_22","072_11_22","LUK","11","22","22","Amma in wani wanda ya fi shi ƙarfi, ya faɗa masa ya kuma sha ƙarfinsa, yakan ƙwace makaman da mutumin ke dogara da su, ya kuma rarraba ganima. ");
INSERT INTO hausa_vpl VALUES ("LK11_23","072_11_23","LUK","11","23","23","“Wanda ba ya tare da ni, yana gāba da ni, wanda kuma ba ya tarawa da ni, watsarwa yake yi. ");
INSERT INTO hausa_vpl VALUES ("LK11_24","072_11_24","LUK","11","24","24","“Lokacin da mugun ruhu ya fita daga mutum, sai ya bi ta wuraren da ba mutane, yana neman hutu, amma ya kāsa samu, sai ya ce, ‘Zan koma gidan da na bari.’ ");
INSERT INTO hausa_vpl VALUES ("LK11_25","072_11_25","LUK","11","25","25","Sa’ad da ya koma, ya tarar da gidan a share da tsabta, kuma a shirye. ");
INSERT INTO hausa_vpl VALUES ("LK11_26","072_11_26","LUK","11","26","26","Sai ya je ya ɗebo waɗansu ruhohi bakwai da suka fi shi mugunta, sai su shiga su zauna a wurin. Ƙarshen wannan mutum kuwa zai fi farkonsa muni.” ");
INSERT INTO hausa_vpl VALUES ("LK11_27","072_11_27","LUK","11","27","27","Da Yesu yake cikin faɗin waɗannan abubuwa, sai wata mace daga cikin taron ta ɗaga murya ta ce masa, “Mai albarka ce uwar da ta haife ka, wadda ka sha mamanta.” ");
INSERT INTO hausa_vpl VALUES ("LK11_28","072_11_28","LUK","11","28","28","Yesu ya amsa ya ce, “A maimakon, masu albarka ne waɗanda suke jin maganar Allah, suna kuma biyayya da ita.” ");
INSERT INTO hausa_vpl VALUES ("LK11_29","072_11_29","LUK","11","29","29","Da taron mutane suka ƙaru, sai Yesu ya ce, “Wannan mugun zamani ne. Tana neman wani abin banmamaki, amma ba ko ɗaya da za a ba ta, sai dai ta Yunana. ");
INSERT INTO hausa_vpl VALUES ("LK11_30","072_11_30","LUK","11","30","30","Kamar yadda Yunana ya zama alama ga mutanen Ninebe, haka ma Ɗan Mutum zai zama ga zamanin nan. ");
INSERT INTO hausa_vpl VALUES ("LK11_31","072_11_31","LUK","11","31","31","A ranar shari’a, Sarauniyar Kudu za tă tashi tsaye tare da wannan zamani, ta yanke wa wannan zamani hukunci, domin ta zo daga ƙarshen duniya ta saurari hikimar Solomon, ga shi kuwa, shi wanda ya fi Solomon girma, na nan. ");
INSERT INTO hausa_vpl VALUES ("LK11_32","072_11_32","LUK","11","32","32","A ranar shari’a, mutanen Ninebe za su tashi tsaye tare da wannan zamani, su yanke wa wannan zamani hukunci. Gama sun tuba sa’ad da Yunana ya yi musu wa’azi. Ga shi yanzu, shi wanda ya fi Yunana girma, na nan. ");
INSERT INTO hausa_vpl VALUES ("LK11_33","072_11_33","LUK","11","33","33","“Babu wanda yakan ƙuna fitila sa’an nan ya ɓoye ta, ko ya rufe ta da murfi ba. A maimako, yakan ajiye ta a kan wurin ajiye fitila, don masu shiga su ga haske. ");
INSERT INTO hausa_vpl VALUES ("LK11_34","072_11_34","LUK","11","34","34","Idonka shi ne fitilar jikinka. Sa’ad da idanunka suna da lafiya, dukan jikinka ma na cike da haske, amma sa’ad da idanunka suna da lahani, dukan jikinka ma na cike da duhu. ");
INSERT INTO hausa_vpl VALUES ("LK11_35","072_11_35","LUK","11","35","35","Ka lura fa, kada hasken da yake cikinka ya zamana duhu ne. ");
INSERT INTO hausa_vpl VALUES ("LK11_36","072_11_36","LUK","11","36","36","Saboda haka, in dukan jikinka yana cike da haske, ba inda ke da duhu, jikinka kuwa zai kasance da haske gaba ɗaya, kamar yadda hasken fitila yake haskaka ka.” ");
INSERT INTO hausa_vpl VALUES ("LK11_37","072_11_37","LUK","11","37","37","Da Yesu ya gama magana, sai wani Bafarisiye ya gayyace shi cin abinci tare da shi. Sai kuwa ya shiga ya zauna a tebur. ");
INSERT INTO hausa_vpl VALUES ("LK11_38","072_11_38","LUK","11","38","38","Amma Bafarisiyen ya lura cewa, Yesu bai wanke hannu kafin ya ci abinci ba, sai mamaki ya kama shi. ");
INSERT INTO hausa_vpl VALUES ("LK11_39","072_11_39","LUK","11","39","39","Sai Ubangiji ya ce masa, “Ku Farisiyawa, kukan wanke bayan kwano da kwaf, amma a ciki kuna cike da kwaɗayi da mugunta. ");
INSERT INTO hausa_vpl VALUES ("LK11_40","072_11_40","LUK","11","40","40","Ku wawayen mutane! Ashe, wanda ya yi bayan, ba shi ne kuma ya yi cikin ba? ");
INSERT INTO hausa_vpl VALUES ("LK11_41","072_11_41","LUK","11","41","41","Ku ba matalauta abin da yake cikin kwano, kuma kome zai zama muku da tsabta. ");
INSERT INTO hausa_vpl VALUES ("LK11_42","072_11_42","LUK","11","42","42","“Kaitonku, Farisiyawa, domin kuna ba wa Allah zakka na na’ana’arku, da ƙarƙashinku, da kuma sauran ganyen lambunku iri-iri, amma kun ƙyale adalci da ƙaunar Allah. Ya kamata da kun kiyaye na ƙarshen, ban ba barin na farkon. ");
INSERT INTO hausa_vpl VALUES ("LK11_43","072_11_43","LUK","11","43","43","“Kaitonku, Farisiyawa, domin kun cika son wuraren zama masu daraja a majami’u, da kuma yawan gaisuwa a wuraren kasuwanci. ");
INSERT INTO hausa_vpl VALUES ("LK11_44","072_11_44","LUK","11","44","44","“Kaitonku, domin ku kamar kaburbura ne da ba a sa musu alama ba, waɗanda mutane suke takawa don rashin sani.” ");
INSERT INTO hausa_vpl VALUES ("LK11_45","072_11_45","LUK","11","45","45","Sai ɗaya daga cikin masanan dokoki ya ce wa Yesu, “Malam, in ka faɗi waɗannan abubuwa haka, kai kuma ka zage mu ke nan.” ");
INSERT INTO hausa_vpl VALUES ("LK11_46","072_11_46","LUK","11","46","46","Yesu ya amsa ya ce, “Ku masanan dokoki ma, kaitonku, domin kun ɗora wa mutane kaya masu nauyi waɗanda da ƙyar suke ɗaukawa, amma ku da kanku ba za ku sa ko yatsa ɗaya, don ku taimake su ba. ");
INSERT INTO hausa_vpl VALUES ("LK11_47","072_11_47","LUK","11","47","47","“Kaitonku, domin kun gina kaburbura saboda annabawa, nan kuwa kakannin-kakanninku ne suka kashe su. ");
INSERT INTO hausa_vpl VALUES ("LK11_48","072_11_48","LUK","11","48","48","Wannan ya shaida cewa kun amince da abin da kakannin-kakanninku suka yi. Sun karkashe annabawa, ku kuma kun gina kaburburansu. ");
INSERT INTO hausa_vpl VALUES ("LK11_49","072_11_49","LUK","11","49","49","Saboda haka, Allah a cikin hikimarsa ya ce, ‘Zan aika musu da annabawa da manzanni. Za su kashe waɗansu, su kuma tsananta wa waɗansu.’ ");
INSERT INTO hausa_vpl VALUES ("LK11_50","072_11_50","LUK","11","50","50","Saboda haka, alhakin jinin dukan annabawa da aka kashe, tun farkon duniya, yana kan wannan zamani, ");
INSERT INTO hausa_vpl VALUES ("LK11_51","072_11_51","LUK","11","51","51","wato, tun daga jinin Habila, har zuwa jinin Zakariya, wanda aka kashe tsakanin bagade da mazauni. I, ina gaya muku, alhakinsu duka yana kan wannan zamani. ");
INSERT INTO hausa_vpl VALUES ("LK11_52","072_11_52","LUK","11","52","52","“Kaitonku, masanan dokoki, domin kun ɗauke mabuɗin ilimi. Ku kanku ba ku shiga ba, kuma kun hana wa waɗanda suke shiga, su shiga.” ");
INSERT INTO hausa_vpl VALUES ("LK11_53","072_11_53","LUK","11","53","53","Da Yesu ya bar wurin, sai Farisiyawa da malaman dokoki suka fara gaba mai tsanani da shi, kuma suna tsokanansa da tambayoyi. ");
INSERT INTO hausa_vpl VALUES ("LK11_54","072_11_54","LUK","11","54","54","Suna fakonsa, don su kama shi a kan wata magana da zai faɗa. ");
INSERT INTO hausa_vpl VALUES ("LK12_1","072_12_1","LUK","12","1","1","Ana nan sa’ad da taron dubban mutane suka taru har suna tattaka juna, Yesu fara yin magana, da farko da almajiransa ya ce, “Ku yi hankali da yistin Farisiyawa, wato, munafunci. ");
INSERT INTO hausa_vpl VALUES ("LK12_2","072_12_2","LUK","12","2","2","Ba abin da yake rufe da ba za a fallasa ba, ko kuma abin da yake ɓoye da ba za a bayyana ba. ");
INSERT INTO hausa_vpl VALUES ("LK12_3","072_12_3","LUK","12","3","3","Abin da kuka faɗa a cikin duhu, za a ji shi a hasken rana. Kuma abin da kuka faɗa a kunne, a cikin ɗakunan ciki-ciki, za a yi shelarsa daga kan rufin ɗakuna. ");
INSERT INTO hausa_vpl VALUES ("LK12_4","072_12_4","LUK","12","4","4","“Ina dai gaya muku abokaina, kada ku ji tsoron masu kashe jiki, amma bayan haka, ba sauran abin da za su iya yi. ");
INSERT INTO hausa_vpl VALUES ("LK12_5","072_12_5","LUK","12","5","5","Amma zan nuna muku wanda za ku ji tsoronsa. Ku ji tsoron wanda, bayan da ya kashe jikin, yana da iko ya jefa ku cikin jahannama ta wuta. I, ina gaya muku, ku ji tsoronsa. ");
INSERT INTO hausa_vpl VALUES ("LK12_6","072_12_6","LUK","12","6","6","Ba ana sayar da kanari biyar a kan kobo biyu ba? Duk da haka, Allah bai manta da ko ɗayansu ba. ");
INSERT INTO hausa_vpl VALUES ("LK12_7","072_12_7","LUK","12","7","7","Tabbatacce, gashin kanku ɗin nan ma, an ƙidaya su duka. Kada ku ji tsoro. Darajarku ta fi na kanari masu yawa girma. ");
INSERT INTO hausa_vpl VALUES ("LK12_8","072_12_8","LUK","12","8","8","“Ina gaya muku, duk wanda ya shaida ni a gaban mutane, Ɗan Mutum ma zai shaida shi a gaban mala’ikun Allah. ");
INSERT INTO hausa_vpl VALUES ("LK12_9","072_12_9","LUK","12","9","9","Amma wanda ya yi mūsun sanina a gaban mutane, shi ma za a yi mūsunsa a gaban mala’ikun Allah. ");
INSERT INTO hausa_vpl VALUES ("LK12_10","072_12_10","LUK","12","10","10","Kuma duk wanda ya faɗi kalmar zagi a kan Ɗan Mutum, za a gafarta masa, amma duk wanda ya saɓa wa Ruhu Mai Tsarki, ba za a gafarta masa ba. ");
INSERT INTO hausa_vpl VALUES ("LK12_11","072_12_11","LUK","12","11","11","“Sa’ad da an kai ku a gaban majami’u, da gaban masu mulki, da kuma gaban masu iko, kada ku damu da yadda za ku kāre kanku, ko kuma abin da za ku faɗa, ");
INSERT INTO hausa_vpl VALUES ("LK12_12","072_12_12","LUK","12","12","12","gama Ruhu Mai Tsarki zai koya muku abin da ya dace ku faɗa a lokacin.” ");
INSERT INTO hausa_vpl VALUES ("LK12_13","072_12_13","LUK","12","13","13","Sai wani mutum daga cikin taron ya ce masa, “Malam, ka ce wa ɗan’uwana ya raba gādon da ni.” ");
INSERT INTO hausa_vpl VALUES ("LK12_14","072_12_14","LUK","12","14","14","Yesu ya amsa masa ya ce, “Kai, wa ya naɗa ni alƙali, ko mai sulhu a tsakaninku?” ");
INSERT INTO hausa_vpl VALUES ("LK12_15","072_12_15","LUK","12","15","15","Sai ya ce musu, “Ku lura fa! Ku tsare kanku daga dukan kowane irin kwaɗayi. Ran mutum ba ya danganta a kan yawan dukiyarsa ba.” ");
INSERT INTO hausa_vpl VALUES ("LK12_16","072_12_16","LUK","12","16","16","Sai ya gaya musu wannan misali ya ce, “Gonar wani mai arziki ta ba da amfani sosai. ");
INSERT INTO hausa_vpl VALUES ("LK12_17","072_12_17","LUK","12","17","17","Ya yi tunani a ransa ya ce, ‘Ba ni da inda zan ajiye amfanin gonana. Me zan yi ke nan?’ ");
INSERT INTO hausa_vpl VALUES ("LK12_18","072_12_18","LUK","12","18","18","“Sai ya ce, ‘Ga abin da zan yi. Zan rushe rumbunana, in gina manya, in zuba dukan hatsina da kayana a ciki. ");
INSERT INTO hausa_vpl VALUES ("LK12_19","072_12_19","LUK","12","19","19","Ni kuma zan ce wa raina, “Kana da kaya da yawa masu kyau, da aka yi ajiyarsu domin shekaru da dama masu zuwa. Yi hutunka, ka ci, ka sha, ka yi annashuwa.” ’ ");
INSERT INTO hausa_vpl VALUES ("LK12_20","072_12_20","LUK","12","20","20","“Amma Allah ya ce masa, ‘Kai wawa! A wannan dare za a nemi ranka. Bayan haka, wa zai gāji abin da ka tara wa kanka?’ ");
INSERT INTO hausa_vpl VALUES ("LK12_21","072_12_21","LUK","12","21","21","“Haka zai zama ga duk wanda ya tara wa kansa dukiya, amma ba shi da arziki a gaban Allah.” ");
INSERT INTO hausa_vpl VALUES ("LK12_22","072_12_22","LUK","12","22","22","Sai Yesu ya ce wa almajiransa, “Saboda haka, ina faɗa muku, kada ku damu game da rayuwarku, abin da za ku ci, ko kuma game da jikinku, abin da za ku yafa. ");
INSERT INTO hausa_vpl VALUES ("LK12_23","072_12_23","LUK","12","23","23","Rai ya fi abinci, jiki kuma ya fi tufafi. ");
INSERT INTO hausa_vpl VALUES ("LK12_24","072_12_24","LUK","12","24","24","Ku dubi hankaki. Ba sa shuki ko girbi, kuma ba su da ɗakin ajiya ko rumbu ba, duk da haka, duk da haka, Allah na ciyar da su. Darajarku ta fi na tsuntsaye sau da yawa! ");
INSERT INTO hausa_vpl VALUES ("LK12_25","072_12_25","LUK","12","25","25","Wane ne a cikinku ta wurin damuwarsa, zai iya ƙara ko sa’a ɗaya ga rayuwarsa? ");
INSERT INTO hausa_vpl VALUES ("LK12_26","072_12_26","LUK","12","26","26","Tun da ba za ku iya yin wannan ƙanƙanin abu ba, me ya sa kuke damuwa a kan sauran? ");
INSERT INTO hausa_vpl VALUES ("LK12_27","072_12_27","LUK","12","27","27","“Ku dubi yadda furanni suke girma. Ba sukan yi aiki, ko saƙa ba, duk da haka, ina faɗa muku cewa, ko Solomon cikin kyakkyawan darajarsa duka, bai yafa kayan ado da ya kai kamar na ko ɗaya a cikinsu ba. ");
INSERT INTO hausa_vpl VALUES ("LK12_28","072_12_28","LUK","12","28","28","In haka ne Allah yake yi wa ciyayin jeji sutura, wadda yau suna nan, sa’an nan gobe kuma a jefa cikin wuta, Allah ba zai yi muku sutura fiye da ciyayin jeji ba, ya ku masu ƙarancin bangaskiya! ");
INSERT INTO hausa_vpl VALUES ("LK12_29","072_12_29","LUK","12","29","29","Kada ku sa zuciyarku a kan abin da za ku ci, ko abin da za ku sha, kada ku damu a kan su. ");
INSERT INTO hausa_vpl VALUES ("LK12_30","072_12_30","LUK","12","30","30","Gama duniya da ba tă san Allah ba, tana faman neman dukan waɗannan abubuwa, Ubanku na sama kuwa, ya san kuna bukatarsu. ");
INSERT INTO hausa_vpl VALUES ("LK12_31","072_12_31","LUK","12","31","31","Amma ku nemi mulkinsa, za a kuwa ƙara muku waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("LK12_32","072_12_32","LUK","12","32","32","“Ya ƙaramin garke, kada ku ji tsoro, gama ya gamshi Ubanku ya ba ku mulkin. ");
INSERT INTO hausa_vpl VALUES ("LK12_33","072_12_33","LUK","12","33","33","Ku sayar da dukiyarku, ku ba wa matalauta. Ku yi wa kanku jakar kuɗin da ba za su lalace ba. Ku yi wa kanku ajiyar dukiyar da ba za tă kare ba a sama, inda ɓarawo ba zai yi kusa ba, asu kuma ba za su iya su lalatar ba. ");
INSERT INTO hausa_vpl VALUES ("LK12_34","072_12_34","LUK","12","34","34","Gama inda dukiyarku take, nan ne zuciyarku ma take. ");
INSERT INTO hausa_vpl VALUES ("LK12_35","072_12_35","LUK","12","35","35","“Ku shirya ɗamara don hidima. Ku bar fitilunku suna ci, ");
INSERT INTO hausa_vpl VALUES ("LK12_36","072_12_36","LUK","12","36","36","kamar maza da suke jiran maigidansu ya dawo daga bikin aure. Saboda duk lokacin da ya dawo ya ƙwanƙwasa ƙofa, a shirye suke su buɗe masa nan da nan. ");
INSERT INTO hausa_vpl VALUES ("LK12_37","072_12_37","LUK","12","37","37","Zai zama da albarka in maigida ya dawo, ya tarar da bayinsa suna zaman tsaro. Gaskiya ni faɗa muku, zai sa kayan hidima da kansa, ya sa bayinsa su zauna kan tebur, sa’an nan ya yi musu hidimar abinci. ");
INSERT INTO hausa_vpl VALUES ("LK12_38","072_12_38","LUK","12","38","38","Zai zama da albarka ga bayin da maigidansu ya iske su, suna zaman tsaro, a duk lokacin da ya dawo, ko da ya dawo a sa’a ta biyu, ko ta uku na tsakar dare ne. ");
INSERT INTO hausa_vpl VALUES ("LK12_39","072_12_39","LUK","12","39","39","Amma ku fahimci wannan. Da maigida ya san sa’ar da ɓarawo zai zo, ai, da ba zai bari a shiga, a fasa masa gida ba. ");
INSERT INTO hausa_vpl VALUES ("LK12_40","072_12_40","LUK","12","40","40","Ku ma, sai ku zauna da shiri, domin Ɗan Mutum zai zo a sa’ar da ba ku yi tsammani ba.” ");
INSERT INTO hausa_vpl VALUES ("LK12_41","072_12_41","LUK","12","41","41","Bitrus ya yi tambaya ya ce, “Ya Ubangiji, mu ne kake faɗa wa wannan misali, ko kuwa ga kowa da kowa ne?” ");
INSERT INTO hausa_vpl VALUES ("LK12_42","072_12_42","LUK","12","42","42","Ubangiji ya amsa ya ce, “To, wane ne manaja mai aminci da hikima, wanda maigida ya ba shi riƙon bayinsa, domin ya ba su abincinsu a daidai lokaci? ");
INSERT INTO hausa_vpl VALUES ("LK12_43","072_12_43","LUK","12","43","43","Zai zama da albarka ga bawan nan wanda maigidan ya dawo, ya same shi yana yin haka. ");
INSERT INTO hausa_vpl VALUES ("LK12_44","072_12_44","LUK","12","44","44","Gaskiya nake gaya muku, maigidan zai ba shi riƙon dukan dukiyarsa. ");
INSERT INTO hausa_vpl VALUES ("LK12_45","072_12_45","LUK","12","45","45","Amma da a ce bawan ya yi tunani a zuciyarsa ya ce, ‘Ai, maigidana ya yi jinkirin dawowa,’ sa’an nan ya fara dūkan bayin, maza da mata, ya kuma shiga ci, da sha, har da buguwa. ");
INSERT INTO hausa_vpl VALUES ("LK12_46","072_12_46","LUK","12","46","46","Maigidan bawan nan zai dawo a ranar da wannan bawan bai yi tsammaninsa ba, kuma a sa’ar da bai sani ba. Maigidan zai yayyanka shi, ya kuma ba shi rabonsa tare da marasa bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("LK12_47","072_12_47","LUK","12","47","47","“Bawan da ya san nufin maigidansa, kuma bai yi shiri ba, ko kuma bai yi abin da maigidansa yake so ba, zai sha mummunan duka. ");
INSERT INTO hausa_vpl VALUES ("LK12_48","072_12_48","LUK","12","48","48","Amma wanda bai sani ba, ya kuwa yi abin da ya isa horo, za a dūke shi kaɗan. Duk wanda aka ba shi mai yawa, mai yawan ne za a bida daga gare shi. Duk wanda kuma aka ba shi riƙon amana mai yawa, fiye da haka kuma za a bida daga gare shi. ");
INSERT INTO hausa_vpl VALUES ("LK12_49","072_12_49","LUK","12","49","49","“Na zo ne domin in kawo wuta a duniya. Ina so da ta riga ta ƙunu! ");
INSERT INTO hausa_vpl VALUES ("LK12_50","072_12_50","LUK","12","50","50","Amma ina da baftismar da za a yi mini, na kuwa damu sosai, sai na kammala ta! ");
INSERT INTO hausa_vpl VALUES ("LK12_51","072_12_51","LUK","12","51","51","Kuna tsammani na zo domin in kawo salama a duniya ne? A’a! Ina gaya muku, rabuwa ne. ");
INSERT INTO hausa_vpl VALUES ("LK12_52","072_12_52","LUK","12","52","52","Daga yanzu, za a iske mutum biyar a gida ɗaya sun rabu, suna gāba da juna, uku suna gāba da biyu, biyun suna gāba da ukun. ");
INSERT INTO hausa_vpl VALUES ("LK12_53","072_12_53","LUK","12","53","53","Za su rarrabu. Mahaifi yana gāba da ɗan, ɗan kuma yana gāba da mahaifin. Mahaifiya tana gāba da diyar, diyar kuma tana gāba da mahaifiyar. Suruka tana gāba da matar ɗa, matar ɗa kuma tana gāba da suruka.” ");
INSERT INTO hausa_vpl VALUES ("LK12_54","072_12_54","LUK","12","54","54","Ya ce wa taron, “Sa’ad da kuka ga hadari ya fito daga yamma, nan da nan kukan ce, ‘Za a yi ruwan sama,’ sai a kuwa yi. ");
INSERT INTO hausa_vpl VALUES ("LK12_55","072_12_55","LUK","12","55","55","Sa’ad da kuma iska ta taso daga kudu, kukan ce, ‘Za a yi zafi,’ sai kuwa a yi. ");
INSERT INTO hausa_vpl VALUES ("LK12_56","072_12_56","LUK","12","56","56","Munafukai! Kuna san yadda za ku fassara yanayin ƙasa da na sararin sama. Ta yaya ba ku san yadda za ku yi fassarar wannan zamani ba? ");
INSERT INTO hausa_vpl VALUES ("LK12_57","072_12_57","LUK","12","57","57","“Don me ba ku iya auna wa kanku, abin da yake daidai ba? ");
INSERT INTO hausa_vpl VALUES ("LK12_58","072_12_58","LUK","12","58","58","Yayinda kake kan hanyar zuwa kotu da maƙiyinka, ka yi matuƙar ƙoƙari ku shirya tun kuna kan hanya. In ba haka ba, zai kai ka gaban alƙali, alƙali kuma ya miƙa ka ga ɗan sanda, ɗan sanda kuma ya jefa ka a kurkuku. ");
INSERT INTO hausa_vpl VALUES ("LK12_59","072_12_59","LUK","12","59","59","Ina gaya maka, ba za ka fita ba, sai ka biya kobo na ƙarshe.” ");
INSERT INTO hausa_vpl VALUES ("LK13_1","072_13_1","LUK","13","1","1","A yanzun fa, akwai waɗansu da suka kasance a lokacin can, suka ba Yesu labarin Galiliyawa da Bilatus ya gauraye jininsu tare da jinin hadayunsu. ");
INSERT INTO hausa_vpl VALUES ("LK13_2","072_13_2","LUK","13","2","2","Yesu ya amsa ya ce, “Kuna tsammani waɗannan Galiliyawan sun fi dukan sauran Galiliyawa zunubi ne, shi ya sa suka sha irin wannan wahala? ");
INSERT INTO hausa_vpl VALUES ("LK13_3","072_13_3","LUK","13","3","3","Ina gaya muku, a’a! Amma in ba ku tuba ba, ku ma duka za ku hallaka. ");
INSERT INTO hausa_vpl VALUES ("LK13_4","072_13_4","LUK","13","4","4","Ko kuwa kuna tsammani, sha takwas ɗin nan da suka mutu lokacin da hasumiya a Silowam ya fāɗi a kansu, sun fi dukan sauran mutanen Urushalima laifi ne? ");
INSERT INTO hausa_vpl VALUES ("LK13_5","072_13_5","LUK","13","5","5","Ina gaya muku, a’a! Amma in ba ku tuba ba, ku ma duka za ku hallaka.” ");
INSERT INTO hausa_vpl VALUES ("LK13_6","072_13_6","LUK","13","6","6","Sai ya ba su wannan misali ya ce, “Wani mutum yana da itacen ɓaure, da aka shuka a gonar inabinsa. Da ya je cire ’ya’yan itacen, sai ya tarar ba tă yi ’ya’ya ba. ");
INSERT INTO hausa_vpl VALUES ("LK13_7","072_13_7","LUK","13","7","7","Sai ya ce wa mai lura da gonar inabin, ‘Yau shekara uku ke nan ina zuwa neman ’ya’yan ɓaure daga itacen nan, amma ba na samun kome. Sare shi! Don me za a bar shi ya tare wuri.’ ");
INSERT INTO hausa_vpl VALUES ("LK13_8","072_13_8","LUK","13","8","8","“Mutumin ya amsa ya ce, ‘Ranka yă daɗe, ka bar shi, in yi masa banƙasa, in kuma zuba masa taki har na shekara ɗaya. ");
INSERT INTO hausa_vpl VALUES ("LK13_9","072_13_9","LUK","13","9","9","In kuwa ya ba da ’ya’ya shekara mai zuwa, yana da kyau! In kuwa ba haka ba, sai ka sare shi.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK13_10","072_13_10","LUK","13","10","10","Wata ranar Asabbaci, Yesu yana koyarwa a wata majami’a, ");
INSERT INTO hausa_vpl VALUES ("LK13_11","072_13_11","LUK","13","11","11","a wurin kuwa, akwai wata mace wadda aljani ya gurgunta, har na shekaru goma sha takwas. Duk ta tanƙware, ba ta ma iya miƙewa ko kaɗan. ");
INSERT INTO hausa_vpl VALUES ("LK13_12","072_13_12","LUK","13","12","12","Da Yesu ya gan ta, sai ya kirata gaba, ya ce mata, “Mace, an ’yantar da ke daga rashin lafiyarki.” ");
INSERT INTO hausa_vpl VALUES ("LK13_13","072_13_13","LUK","13","13","13","Sai ya ɗibiya hannuwansa a kanta, nan da nan sai ta miƙe, ta yabi Allah. ");
INSERT INTO hausa_vpl VALUES ("LK13_14","072_13_14","LUK","13","14","14","Amma mai mulkin majami’ar ya ji haushi da Yesu ya yi warkarwa a ranar Asabbaci. Sai ya ce wa mutanen, “Akwai ranaku shida da ya kamata a yi aiki. Saboda haka, ku zo a ranakun nan a warkar da ku, ba ranar Asabbaci ba.” ");
INSERT INTO hausa_vpl VALUES ("LK13_15","072_13_15","LUK","13","15","15","Ubangiji ya amsa masa ya ce, “Ku munafukai! Ashe, kowannenku ba yakan kunce bijiminsa ko jakinsa, yă kai shi waje yă ba shi ruwa, a ranar Asabbaci ba? ");
INSERT INTO hausa_vpl VALUES ("LK13_16","072_13_16","LUK","13","16","16","Ashe, bai kamata a ’yantar da macen nan, diyar zuriyar Ibrahim, wadda Shaiɗan ya daure, har shekara goma sha takwas, a ranar Asabbaci, daga abin da ya daure ta ba?” ");
INSERT INTO hausa_vpl VALUES ("LK13_17","072_13_17","LUK","13","17","17","Sa’ad da ya faɗi wannan, sai duka masu gāba da shi suka kunyata. Amma mutane kuwa suka yi murna saboda dukan abubuwan banmamaki da yake yi. ");
INSERT INTO hausa_vpl VALUES ("LK13_18","072_13_18","LUK","13","18","18","Sai Yesu ya yi tambaya ya ce, “Yaya mulkin Allah yake? Da me zan kwatanta shi? ");
INSERT INTO hausa_vpl VALUES ("LK13_19","072_13_19","LUK","13","19","19","Yana kama da ƙwayar mustad, wadda wani mutum ya ɗauka, kuma ya shuka a gonarsa. Ta yi girma, ta zama itace, kuma tsuntsayen sararin sama suka huta a rassansa.” ");
INSERT INTO hausa_vpl VALUES ("LK13_20","072_13_20","LUK","13","20","20","Ya sāke tambaya, “Da me zan kwatanta mulkin Allah? ");
INSERT INTO hausa_vpl VALUES ("LK13_21","072_13_21","LUK","13","21","21","Yana kama da yisti wadda mace ta ɗauka, ta kwaɓa garin alkama mai yawa da shi, har sai da yistin ya gauraye kullun duka.” ");
INSERT INTO hausa_vpl VALUES ("LK13_22","072_13_22","LUK","13","22","22","Sa’ad da Yesu yana kan hanyarsa zuwa Urushalima, sai ya bi ta cikin garuruwan da ƙauyukan, yana koyarwa. ");
INSERT INTO hausa_vpl VALUES ("LK13_23","072_13_23","LUK","13","23","23","Sai wani ya tambaye shi ya ce, “Ya Ubangiji, shin, wai mutane kima ne kawai za su sami ceto?” Ya ce musu, ");
INSERT INTO hausa_vpl VALUES ("LK13_24","072_13_24","LUK","13","24","24","“Ku yi matuƙar ƙoƙari ku shiga ta matsattsiyar ƙofa, domin ina faɗa muku, mutane da yawa za su yi ƙoƙarin shiga, amma ba za su iya ba. ");
INSERT INTO hausa_vpl VALUES ("LK13_25","072_13_25","LUK","13","25","25","Da zaran maigidan ya tashi ya rufe ƙofar, za ku tsaya a waje kuna ƙwanƙwasawa, kuna roƙo cewa, ‘Ranka yă daɗe, buɗe mana ƙofa.’ “Amma shi zai amma ya ce, ‘Ni ban san ku, ko inda kuka fito ba.’ ");
INSERT INTO hausa_vpl VALUES ("LK13_26","072_13_26","LUK","13","26","26","“Sa’an nan za ku ce, ‘Haba, mu da muka ci, muka sha tare da kai, har ka yi koyarwa a cikin titi-titi namu.’ ");
INSERT INTO hausa_vpl VALUES ("LK13_27","072_13_27","LUK","13","27","27","“Amma shi zai amma ya ce, ‘Ban san ku, ko inda kuka fito ba. Ku rabu da ni, dukan ku masu aikata mugunta!’ ");
INSERT INTO hausa_vpl VALUES ("LK13_28","072_13_28","LUK","13","28","28","“Za a yi kuka a can, da cizon haƙora, sa’ad da kuka ga Ibrahim, da Ishaku, da Yaƙub, da dukan annabawa a mulkin Allah, amma ku kuwa, za a jefar da ku a waje. ");
INSERT INTO hausa_vpl VALUES ("LK13_29","072_13_29","LUK","13","29","29","Mutane za su zo daga gabas, da yamma, da kudu, da arewa, su ɗauki wuraren zamansu a bikin, a cikin mulkin Allah. ");
INSERT INTO hausa_vpl VALUES ("LK13_30","072_13_30","LUK","13","30","30","Tabbatacce, akwai waɗansu da suke na ƙarshe, da za su zama na farko, na farko kuma, da za su zama na ƙarshe.” ");
INSERT INTO hausa_vpl VALUES ("LK13_31","072_13_31","LUK","13","31","31","A wannan lokaci, waɗansu Farisiyawa suka zo suka ce wa Yesu, “Ka bar nan ka tafi wani wuri dabam. Hiridus yana so ya kashe ka.” ");
INSERT INTO hausa_vpl VALUES ("LK13_32","072_13_32","LUK","13","32","32","Ya amsa ya ce, “Ku je ku gaya wa dilan nan, wato, mai makirci cewa, ‘Da yau da kuma gobe, zan fitar da aljanu, in kuma warkar da mutane, sa’an nan a rana ta uku in cika burin aikina. ");
INSERT INTO hausa_vpl VALUES ("LK13_33","072_13_33","LUK","13","33","33","Duk da haka, dole in ci gaba da aikin a yau, da kuma gobe, sa’an nan in ci gaba da yin haka kashegari kuma, gama tabbatacce, ba annabi da yakan mutu a bayan birnin Urushalima!’ ");
INSERT INTO hausa_vpl VALUES ("LK13_34","072_13_34","LUK","13","34","34","“Urushalima, ayya Urushalima, ke da kika kashe annabawa, kuma kika jefa wa waɗanda aka aika gare ki da duwatsu. Sau da yawa na yi kewan in tattara ’ya’yanki wuri ɗaya, kamar yadda kaza takan tattara ’ya’yanta cikin fikafikanta, amma ba ki yarda ba! ");
INSERT INTO hausa_vpl VALUES ("LK13_35","072_13_35","LUK","13","35","35","Duba, an bar muku gidanku fanko. Ina kuwa faɗa muku, ba za ku sāke ganina ba, sai kun ce, ‘Mai albarka ne shi wanda yake zuwa cikin sunan Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK14_1","072_14_1","LUK","14","1","1","Wata ranar Asabbaci, da Yesu ya shiga gidan wani sanannen Bafarisiye don cin abinci, sai mutane suka zuba masa ido da kyau. ");
INSERT INTO hausa_vpl VALUES ("LK14_2","072_14_2","LUK","14","2","2","A nan a gabansa kuwa akwai wani mutum mai ciwon kumburin ƙafa da hannu. ");
INSERT INTO hausa_vpl VALUES ("LK14_3","072_14_3","LUK","14","3","3","Sai Yesu ya tambayi masanan dokoki da Farisiyawa ya ce, “Daidai ne bisa ga doka, a yi warkarwa a ranar Asabbaci, ko babu?” ");
INSERT INTO hausa_vpl VALUES ("LK14_4","072_14_4","LUK","14","4","4","Amma ba su ce kome ba. Sai ya riƙe mutumin, ya warkar da shi, sa’an nan ya sallame shi. ");
INSERT INTO hausa_vpl VALUES ("LK14_5","072_14_5","LUK","14","5","5","Sai ya tambaye, su ya ce, “In wani a cikinku yana da ɗa, ko bijimi da ya faɗa a rijiya a ranar Asabbaci, ba za ku cire shi nan da nan ba?” ");
INSERT INTO hausa_vpl VALUES ("LK14_6","072_14_6","LUK","14","6","6","Suka rasa abin faɗi. ");
INSERT INTO hausa_vpl VALUES ("LK14_7","072_14_7","LUK","14","7","7","Da ya lura da yadda baƙi suna zaɓan wuraren zama masu bangirma a tebur, sai ya faɗa musu wannan misali, ya ce; ");
INSERT INTO hausa_vpl VALUES ("LK14_8","072_14_8","LUK","14","8","8","“In wani ya gayyace ka bikin aure, kada ka zaɓi wurin zama mai bangirma, don wataƙila akwai wani da ya fi ka girma, da aka gayyata. ");
INSERT INTO hausa_vpl VALUES ("LK14_9","072_14_9","LUK","14","9","9","In kuwa haka ne, wanda ya gayyace duk biyunku, zai zo ya ce maka, ‘Ka ba wa mutumin nan wurin zamanka.’ Ka ga, an ƙasƙantar da kai, kuma dole ka ɗauki wuri mafi ƙasƙanci. ");
INSERT INTO hausa_vpl VALUES ("LK14_10","072_14_10","LUK","14","10","10","Amma in an gayyace ka, ɗauki wuri mafi ƙasƙanci, don in wanda ya gayyace ka ya zo, zai ce maka, ‘Ka hawo nan aboki a wuri mafi girma.’ Wannan zai ɗaukaka ka a gaban dukan ’yan’uwanka baƙi. ");
INSERT INTO hausa_vpl VALUES ("LK14_11","072_14_11","LUK","14","11","11","Gama duk wanda ya ɗaukaka kansa, za a ƙasƙantar da shi. Shi wanda kuma ya ƙasƙantar da kansa, za a ɗaukaka shi.” ");
INSERT INTO hausa_vpl VALUES ("LK14_12","072_14_12","LUK","14","12","12","Sai Yesu ya ce wa wanda ya gayyace shi, “Lokacin da ka shirya biki ko liyafa, kada ka gayyaci abokanka, ko ’yan’uwanka, ko danginka, ko kuma maƙwabtanka masu arziki, gama in ka yi haka, suna iya gayyatarka, su biya maka alherin da ka yi musu. ");
INSERT INTO hausa_vpl VALUES ("LK14_13","072_14_13","LUK","14","13","13","Amma lokacin da ka kira biki, ka gayyaci matalauta, da guragu, da shanyayyu, da makafi. ");
INSERT INTO hausa_vpl VALUES ("LK14_14","072_14_14","LUK","14","14","14","Ta haka, za ka sami albarka. Ko da yake ba za su iya biyan ka ba, za a biya ka a ranar tashin masu adalci daga matattu.” ");
INSERT INTO hausa_vpl VALUES ("LK14_15","072_14_15","LUK","14","15","15","Da jin haka, sai wani da yake tare da shi a tebur ɗin, ya ce wa Yesu, “Mai albarka ne wanda zai ci abinci a bikin nan a mulkin Allah.” ");
INSERT INTO hausa_vpl VALUES ("LK14_16","072_14_16","LUK","14","16","16","Yesu ya amsa ya ce, “Wani mutum yana shirya wani babban biki, ya kuma gayyaci baƙi da yawa. ");
INSERT INTO hausa_vpl VALUES ("LK14_17","072_14_17","LUK","14","17","17","Da lokacin bikin ya yi, sai ya aiki bawansa ya je ya ce wa waɗanda aka gayyata, ‘Ku zo, don an shirya kome.’ ");
INSERT INTO hausa_vpl VALUES ("LK14_18","072_14_18","LUK","14","18","18","“Amma sai dukansu suka fara ba da hujjoji. Na farkon ya ce, ‘Na sayi gona yanzun nan, dole in je in ga yadda take, ina roƙonka ka yi mini haƙuri.’ ");
INSERT INTO hausa_vpl VALUES ("LK14_19","072_14_19","LUK","14","19","19","“Wani ya ce, ‘Na sayi shanun noma guda goma yanzun nan, ina kan hanyata ke nan in gwada su, ina roƙonka, ka yi mini haƙuri.’ ");
INSERT INTO hausa_vpl VALUES ("LK14_20","072_14_20","LUK","14","20","20","“Har yanzu wani ya ce, ‘Na yi aure yanzun nan, don haka ni ba zan iya zuwa ba.’ ");
INSERT INTO hausa_vpl VALUES ("LK14_21","072_14_21","LUK","14","21","21","“Bawansa ya dawo ya gaya wa maigidansa wannan. Sai maigidan ya yi fushi, ya ba da umarni ga bawansa ya ce, ‘Ka fita da sauri, ka bi titi-titi da lungu-lungu na garin, ka kawo matalauta, da guragu, da makafi, da shanyayyu.’ ");
INSERT INTO hausa_vpl VALUES ("LK14_22","072_14_22","LUK","14","22","22","“Bawan ya dawo ya ce, ‘Ranka yă daɗe, an yi abin da ka umarta, amma har yanzu da sauran wuri.’ ");
INSERT INTO hausa_vpl VALUES ("LK14_23","072_14_23","LUK","14","23","23","“Maigidan ya ce wa bawansa, ‘Ka je kan hanyoyin da layi-layi na karkara, ka sa su shigo, don gidana ya cika.’ ");
INSERT INTO hausa_vpl VALUES ("LK14_24","072_14_24","LUK","14","24","24","Ina gaya muku, babu ko ɗaya daga cikin mutanen nan da aka gayyata da zai ɗanɗana bikina.” ");
INSERT INTO hausa_vpl VALUES ("LK14_25","072_14_25","LUK","14","25","25","Taron mutane mai yawa suna tafiya tare da Yesu, sai ya juya ya ce musu, ");
INSERT INTO hausa_vpl VALUES ("LK14_26","072_14_26","LUK","14","26","26","“Duk wanda yakan zo wurina, amma bai ƙi mahaifinsa da mahaifiyarsa, da matarsa da ’ya’yansa, da ’yan’uwansa mata da maza, kai, har ma ransa ba, ba zai iya zama almajirina ba. ");
INSERT INTO hausa_vpl VALUES ("LK14_27","072_14_27","LUK","14","27","27","Kuma duk wanda ba yakan ɗauki gicciyensa ya bi ni ba, ba zai iya zama almajirina ba. ");
INSERT INTO hausa_vpl VALUES ("LK14_28","072_14_28","LUK","14","28","28","“In wani daga cikinku yana so ya gina gidan sama, ai, yakan fara zama ne, ya yi lissafin abin da ginin zai ci tukuna, don yă ga ko yana da isashen kuɗi da zai gama ginin. ");
INSERT INTO hausa_vpl VALUES ("LK14_29","072_14_29","LUK","14","29","29","Gama in ya sa tushen gini, amma bai iya gamawa ba, duk wanda ya gani zai yi masa ba’a, ");
INSERT INTO hausa_vpl VALUES ("LK14_30","072_14_30","LUK","14","30","30","yana cewa, ‘Wannan mutum ya fara gini, amma bai iya gamawa ba.’ ");
INSERT INTO hausa_vpl VALUES ("LK14_31","072_14_31","LUK","14","31","31","“Ko kuma, wane sarki ne, in zai je yaƙi da wani sarki, ai, yakan fara zama ne, ya duba ya ga, ko da mutane dubu goma, shi zai iya ƙarawa da mai zuwa da dubu ashirin? ");
INSERT INTO hausa_vpl VALUES ("LK14_32","072_14_32","LUK","14","32","32","In ba zai iya ba, to, tun suna nesa, zai aika da wakilai, su je neman sharuɗan salama. ");
INSERT INTO hausa_vpl VALUES ("LK14_33","072_14_33","LUK","14","33","33","Haka nan fa, kowane ne a cikinku, da ba ya rabu da abin da yake da shi ba, ba zai iya zama almajirina ba. ");
INSERT INTO hausa_vpl VALUES ("LK14_34","072_14_34","LUK","14","34","34","“Gishiri fa yana da kyau, amma in gishiri ya rabu da daɗin ɗanɗanonsa, ta yaya za a sāke mai da daɗin ɗanɗanonsa? ");
INSERT INTO hausa_vpl VALUES ("LK14_35","072_14_35","LUK","14","35","35","Ba shi da wani amfani, ko ga ƙasa, ko ga juji, sai dai a zubar da shi. “Duk mai kunnen ji, yă ji.” ");
INSERT INTO hausa_vpl VALUES ("LK15_1","072_15_1","LUK","15","1","1","Yanzu fa, masu karɓar haraji da “masu zunubi” duka suna taruwa don jin koyarwar Yesu. ");
INSERT INTO hausa_vpl VALUES ("LK15_2","072_15_2","LUK","15","2","2","Amma Farisiyawa da malaman dokoki suka yi gunaguni, suna cewa, “Wannan mutum yana karɓan ‘masu zunubi,’ kuma yana ci tare da su.” ");
INSERT INTO hausa_vpl VALUES ("LK15_3","072_15_3","LUK","15","3","3","Sai Yesu ya faɗa musu wannan misali ya ce, ");
INSERT INTO hausa_vpl VALUES ("LK15_4","072_15_4","LUK","15","4","4","“In ɗayanku yana da tumaki ɗari, sa’an nan ɗayansu ta ɓace. Ashe, ba zai bar tasa’in da tara a fili ya je neman wadda ta ɓace, har sai ya same ta ba? ");
INSERT INTO hausa_vpl VALUES ("LK15_5","072_15_5","LUK","15","5","5","In ya same ta, zai sa ta a kafaɗa da murna, ");
INSERT INTO hausa_vpl VALUES ("LK15_6","072_15_6","LUK","15","6","6","ya dawo gida. Sa’an nan zai kira abokansa da maƙwabtansa wuri ɗaya ya ce, ‘Ku taya ni murna, na sami tunkiyana da ta ɓata.’ ");
INSERT INTO hausa_vpl VALUES ("LK15_7","072_15_7","LUK","15","7","7","Ina gaya muku, haka za a yi murna sosai a sama, a kan mai zunubi guda ɗaya da ya tuba, fiye da masu adalci tasa’in da tara, waɗanda ba su bukatan tuba. ");
INSERT INTO hausa_vpl VALUES ("LK15_8","072_15_8","LUK","15","8","8","“Ko kuwa in wata mace tana da kuɗi na azurfa guda goma, sa’an nan ɗaya ya ɓata, ashe, ba za tă ƙuna fitila, ta share gidan, ta nema a hankali, har sai ta samu ba? ");
INSERT INTO hausa_vpl VALUES ("LK15_9","072_15_9","LUK","15","9","9","In ta same shi, sai ta kira ƙawayenta da maƙwabtanta wuri ɗaya, ta ce musu, ‘Ku taya ni murna, na sami kuɗina da ya ɓata.’ ");
INSERT INTO hausa_vpl VALUES ("LK15_10","072_15_10","LUK","15","10","10","Haka, ina gaya muku, akwai murna a gaban mala’ikun Allah a kan mai zunubi guda ɗaya, da ya tuba.” ");
INSERT INTO hausa_vpl VALUES ("LK15_11","072_15_11","LUK","15","11","11","Yesu ya ci gaba da cewa, “Akwai wani mutum wanda yake da ’ya’ya biyu maza. ");
INSERT INTO hausa_vpl VALUES ("LK15_12","072_15_12","LUK","15","12","12","Ƙaramin ya ce wa mahaifinsu, ‘Baba, ba ni rabon gādona.’ Sai mahaifin ya raba musu dukiyarsa. ");
INSERT INTO hausa_vpl VALUES ("LK15_13","072_15_13","LUK","15","13","13","“Bayan ’yan kwanaki, sai ƙaramin ɗan ya tattara kayansa duk, ya tashi ya tafi wata ƙasa mai nisa. A can, ya ɓatar da dukiyarsa duka a rayuwar banza. ");
INSERT INTO hausa_vpl VALUES ("LK15_14","072_15_14","LUK","15","14","14","Bayan ya ɓatar da kome, sai ga muguwar yunwa a dukan ƙasar, har ya shiga rashi. ");
INSERT INTO hausa_vpl VALUES ("LK15_15","072_15_15","LUK","15","15","15","Sai ya je ya sami aiki a wurin wani mutumin ƙasar, wanda ya aike shi a gonakinsa, ya yi kiwon aladu. ");
INSERT INTO hausa_vpl VALUES ("LK15_16","072_15_16","LUK","15","16","16","Ya yi marmarin cin dusan da aladun suke ci, amma ba wanda ya ba shi wani abu. ");
INSERT INTO hausa_vpl VALUES ("LK15_17","072_15_17","LUK","15","17","17","“Da hankalinsa ya dawo, sai ya ce, ‘Kai, bayin mahaifina guda nawa ne, da suke da abinci fiye da isashe, ni kuma ina nan, zan mutu don yunwa! ");
INSERT INTO hausa_vpl VALUES ("LK15_18","072_15_18","LUK","15","18","18","Zan tashi in koma wurin mahaifina, in ce masa, “Baba, na yi wa sama, na kuma yi maka zunubi. ");
INSERT INTO hausa_vpl VALUES ("LK15_19","072_15_19","LUK","15","19","19","Ni ban isa a ƙara kira na ɗanka ba. Ka mai da ni kamar ɗaya daga cikin bayinka.” ’ ");
INSERT INTO hausa_vpl VALUES ("LK15_20","072_15_20","LUK","15","20","20","Sai ya tashi ya kama hanya ya koma wurin mahaifinsa. “Amma tun yana nesa, mahaifinsa ya hange shi. Tausayi kuma ya kama shi, sai ya tashi ya ruga da gudu wurinsa, ya rungume shi, ya yi masa sumba. ");
INSERT INTO hausa_vpl VALUES ("LK15_21","072_15_21","LUK","15","21","21","“Sai ɗan ya ce masa, ‘Baba, na yi wa sama, na kuma yi maka zunubi. Ni ban isa a ƙara kira na ɗanka ba.’ ");
INSERT INTO hausa_vpl VALUES ("LK15_22","072_15_22","LUK","15","22","22","“Amma mahaifin ya ce wa bayinsa, ‘Maza! Ku kawo riga mafi kyau ku sa masa. Ku sa zobe a yatsarsa, da takalma kuma a ƙafafunsa. ");
INSERT INTO hausa_vpl VALUES ("LK15_23","072_15_23","LUK","15","23","23","Ku kawo ɗan saniya mai ƙiba ku yanka. Bari mu yi biki mu yi shagali. ");
INSERT INTO hausa_vpl VALUES ("LK15_24","072_15_24","LUK","15","24","24","Gama ɗan nan nawa, da ya mutu, amma yanzu yana da rai kuma. Da ya ɓata, amma yanzu an same shi.’ Sai suka fara shagali. ");
INSERT INTO hausa_vpl VALUES ("LK15_25","072_15_25","LUK","15","25","25","“Yayinda ake haka, babban ɗan yana gona. Da ya zo kusa da gida, sai ya ji ana kiɗi ana rawa. ");
INSERT INTO hausa_vpl VALUES ("LK15_26","072_15_26","LUK","15","26","26","Sai ya kira ɗaya daga cikin bayin, ya tambaye shi abin da yake faruwa. ");
INSERT INTO hausa_vpl VALUES ("LK15_27","072_15_27","LUK","15","27","27","Bawan ya ce, ‘Ai, ɗan’uwanka ne ya dawo, shi ne mahaifinka ya yanka ɗan saniya mai ƙiba, gama ya yi murna ya karɓi ɗansa da ya dawo gida lafiyayye, ba abin da ya same shi.’ ");
INSERT INTO hausa_vpl VALUES ("LK15_28","072_15_28","LUK","15","28","28","“Sai yayan ya yi fushi, ya ƙi shiga gida. Sai mahaifinsa ya fita ya roƙe shi. ");
INSERT INTO hausa_vpl VALUES ("LK15_29","072_15_29","LUK","15","29","29","Amma ya amsa wa mahaifinsa ya ce, ‘Duba! Duk waɗannan shekaru, ina yin maka aiki kamar bawa, ban taɓa maka rashin biyayya ba. Duk da haka, ba ka taɓa ba ni ko ɗan akuya domin in yi shagali da abokaina ba. ");
INSERT INTO hausa_vpl VALUES ("LK15_30","072_15_30","LUK","15","30","30","Amma da wannan ɗan naka, wanda ya ɓatar da dukiyarka a kan karuwai ya dawo, ka yanka masa ɗan saniya mai ƙiba!’ ");
INSERT INTO hausa_vpl VALUES ("LK15_31","072_15_31","LUK","15","31","31","“Sai mahaifin ya ce masa, ‘Ɗana, kullum kana nan tare da ni, kuma duk abin da nake da shi, naka ne. ");
INSERT INTO hausa_vpl VALUES ("LK15_32","072_15_32","LUK","15","32","32","Amma ya zama mana dole, mu yi shagali, mu yi murna, domin ɗan’uwan nan naka, da ya mutu, yanzu kuwa yana da rai, da ya ɓata, amma yanzu an same shi.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK16_1","072_16_1","LUK","16","1","1","Yesu ya ce wa almajiransa, “An yi wani mai arziki wanda aka yi wa manajansa zargin yin banza da dukiyarsa. ");
INSERT INTO hausa_vpl VALUES ("LK16_2","072_16_2","LUK","16","2","2","Sai ya kira manajan, ya tambaye shi, ‘Me nake ji haka a kanka? Ka kawo lissafin aikinka, domin ba za ka iya cin gaba da aikinka ba.’ ");
INSERT INTO hausa_vpl VALUES ("LK16_3","072_16_3","LUK","16","3","3","“Sai manajan ya ce cikin tunaninsa, ‘Maigidana zai kore ni daga aiki, me zan yi? Ba ni da ƙarfin noma, kuma ina jin kunyan yin bara. ");
INSERT INTO hausa_vpl VALUES ("LK16_4","072_16_4","LUK","16","4","4","Na san abin da zan yi, don mutane su karɓe ni a gidajensu, bayan an kore ni daga aiki a nan.’ ");
INSERT INTO hausa_vpl VALUES ("LK16_5","072_16_5","LUK","16","5","5","“Sai ya kira kowane ɗaya da maigidansa yake bin bashi. Ya tambayi na farkon ya ce, ‘Nawa ne maigidana yake bin ka?’ ");
INSERT INTO hausa_vpl VALUES ("LK16_6","072_16_6","LUK","16","6","6","“Ya amsa ya ce, ‘Garwar mai na zaitun guda ɗari tara.’ “Manajan ya ce, ‘Ga takardarka, ka zauna maza ka mai da shi ɗari huɗu.’ ");
INSERT INTO hausa_vpl VALUES ("LK16_7","072_16_7","LUK","16","7","7","“Ya kuma tambayi na biyun, ‘Kai fa, nawa ne ake bin ka?’ “Sai ya amsa ya ce, ‘Buhunan alkama dubu.’ “Ya ce, ‘Ga takardarka, ka mai da shi ɗari takwas.’ ");
INSERT INTO hausa_vpl VALUES ("LK16_8","072_16_8","LUK","16","8","8","“Maigidan kuwa ya yabi manajan nan marar gaskiya saboda wayonsa. Gama ’yan duniyan nan suna da wayon yin hulɗa da junansu fiye da ’yan haske. ");
INSERT INTO hausa_vpl VALUES ("LK16_9","072_16_9","LUK","16","9","9","Ina gaya muku, ku yi amfani da dukiya na wannan duniya, domin ku sami wa kanku abokai. Saboda bayan dukiyar ta ƙare, za a karɓe ku a wuraren zama da sun dawwama. ");
INSERT INTO hausa_vpl VALUES ("LK16_10","072_16_10","LUK","16","10","10","“Duk wanda ana amincewa da shi cikin ƙaramin abu, ana kuma amincewa da shi cikin babba. Kuma duk marar gaskiya cikin ƙaramin abu, zai zama marar gaskiya cikin babba. ");
INSERT INTO hausa_vpl VALUES ("LK16_11","072_16_11","LUK","16","11","11","In fa ku ba amintattu ne cikin tafiyar da dukiya ta wannan duniya ba, wa zai amince muku da dukiya ta gaskiya? ");
INSERT INTO hausa_vpl VALUES ("LK16_12","072_16_12","LUK","16","12","12","In fa ku ba amintattu ne cikin tafiyar da dukiyar wani ba, wa zai ba ku dukiya naku, na kanku? ");
INSERT INTO hausa_vpl VALUES ("LK16_13","072_16_13","LUK","16","13","13","“Babu wani bawa mai iya bauta wa iyayengiji biyu ba. Ko dai ya ƙi ɗaya, ya so ɗayan, ko kuwa ya dāge ga yi wa ɗaya bauta, sa’an nan ya rena ɗayan. Ba za ku iya ku bauta wa Allah tare da bauta wa Mammon (wato, Kuɗi) a lokaci ɗaya ba.” ");
INSERT INTO hausa_vpl VALUES ("LK16_14","072_16_14","LUK","16","14","14","Da Farisiyawa masu son kuɗi suka ji wannan duka, sai suka yi wa Yesu tsaki. ");
INSERT INTO hausa_vpl VALUES ("LK16_15","072_16_15","LUK","16","15","15","Ya ce musu, “Ku ne masu mai da kanku marasa laifi a gaban mutane, amma Allah ya san zuciyarku. Abu mai daraja a gaban mutane, abin ƙyama ne a gaban Allah. ");
INSERT INTO hausa_vpl VALUES ("LK16_16","072_16_16","LUK","16","16","16","“An yi shelar Doka da Annabawa har zuwa lokacin Yohanna. Tun daga lokacin nan, bisharar mulkin Allah ne ake wa’azinta, kowa kuma yana ƙoƙarin kutsa kai ya shiga. ");
INSERT INTO hausa_vpl VALUES ("LK16_17","072_16_17","LUK","16","17","17","Gama ta fi sauƙi sama da ƙasa su shuɗe, da a ce ɗigo guda ɗaya na rubutun, ya fita ya fāɗi daga cikin Doka. ");
INSERT INTO hausa_vpl VALUES ("LK16_18","072_16_18","LUK","16","18","18","“Duk wanda ya saki matarsa ya auri wata mace, zina ne yake yi. Kuma mutumin da ya auri macen da aka sake, zina ne yake yi. ");
INSERT INTO hausa_vpl VALUES ("LK16_19","072_16_19","LUK","16","19","19","“An yi wani mutum mai arziki wanda yakan sa tufafi masu ruwan shunayya, da kuma na lallausan lilin, yana kuma cikin rayuwar jin daɗi kullum. ");
INSERT INTO hausa_vpl VALUES ("LK16_20","072_16_20","LUK","16","20","20","A ƙofar gidansa kuma akan ajiye wani mai bara, mai suna Lazarus, wanda jikinsa duk gyambuna ne. ");
INSERT INTO hausa_vpl VALUES ("LK16_21","072_16_21","LUK","16","21","21","Shi kuwa yakan yi marmarin cin abin da yakan fāɗi daga tebur na mai arzikin nan. Har karnuka ma sukan zo su lashe gyambunansa. ");
INSERT INTO hausa_vpl VALUES ("LK16_22","072_16_22","LUK","16","22","22","“Ana nan, sai mai baran ya mutu, kuma mala’iku suka ɗauke shi zuwa gefen Ibrahim. Mai arzikin ma ya mutu, aka kuma binne shi. ");
INSERT INTO hausa_vpl VALUES ("LK16_23","072_16_23","LUK","16","23","23","A cikin jahannama ta wuta, inda yana shan azaba, ya ɗaga kai ya hangi Ibrahim can nesa, da kuma Lazarus a gefensa. ");
INSERT INTO hausa_vpl VALUES ("LK16_24","072_16_24","LUK","16","24","24","Sai ya yi masa kira ya ce, ‘Baba, Ibrahim, ka ji tausayina, ka aiki Lazarus ya sa ɗan yatsarsa a ruwa, ya ɗiga mini a harshe saboda in ji sanyi, domin ina shan azaba cikin wannan wuta.’ ");
INSERT INTO hausa_vpl VALUES ("LK16_25","072_16_25","LUK","16","25","25","“Amma Ibrahim ya ce, ‘Ka tuna fa ɗana, a lokacin da kake duniya, ka sami abubuwa masu kyau naka, Lazarus kuwa ya sami munanan abubuwa. Amma yanzu ya sami ta’aziyya a nan, kai kuwa kana shan azaba. ");
INSERT INTO hausa_vpl VALUES ("LK16_26","072_16_26","LUK","16","26","26","Ban da wannan duka ma, tsakaninmu da kai, akwai wani babban rami da aka yi, yadda waɗanda suke son ƙetarewa daga nan zuwa wurinku, ba za su iya ba, kuma ba mai iya ƙetarewa daga wurinku zuwa wurinmu.’ ");
INSERT INTO hausa_vpl VALUES ("LK16_27","072_16_27","LUK","16","27","27","“Ya amsa ya ce, ‘To, ina roƙonka, ya uba, ka aiki Lazarus zuwa gidan mahaifina, ");
INSERT INTO hausa_vpl VALUES ("LK16_28","072_16_28","LUK","16","28","28","gama ina da ’yan’uwana biyar maza. Bari yă ba su gargaɗi, don kada su ma su zo wurin nan mai azaba.’ ");
INSERT INTO hausa_vpl VALUES ("LK16_29","072_16_29","LUK","16","29","29","“Ibrahim ya amsa ya ce, ‘Suna da Musa da Annabawa, ai, sai su saurare su.’ ");
INSERT INTO hausa_vpl VALUES ("LK16_30","072_16_30","LUK","16","30","30","“Sai ya ce, ‘A’a, ya uba, Ibrahim, in dai wani ya tashi daga matattu ya je wurinsu, za su tuba.’ ");
INSERT INTO hausa_vpl VALUES ("LK16_31","072_16_31","LUK","16","31","31","“Amma ya ce masa, ‘In ba su saurari Musa da Annabawa ba, kai, ko da wani ya tashi daga matattu ma, ba za su saurare shi ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK17_1","072_17_1","LUK","17","1","1","Yesu ya ce wa almajiransa, “Dole ne a sami abubuwan da suke sa mutane su yi zunubi, amma kaiton mutumin nan wanda suke zuwa ta wurinsa. ");
INSERT INTO hausa_vpl VALUES ("LK17_2","072_17_2","LUK","17","2","2","Gwamma a ɗaura dutsen niƙa a wuyansa, a jefa shi cikin teku, da ya sa ɗaya daga cikin ƙananan yaran nan ya yi zunubi. ");
INSERT INTO hausa_vpl VALUES ("LK17_3","072_17_3","LUK","17","3","3","Saboda haka, ku lura da kanku. “In ɗan’uwanka ya yi zunubi, ka kwaɓe shi. In ya tuba, ka gafarta masa. ");
INSERT INTO hausa_vpl VALUES ("LK17_4","072_17_4","LUK","17","4","4","In ya yi maka laifi sau bakwai a rana ɗaya, ya kuma dawo sau bakwai ɗin a wurinka, yana cewa, ‘Na tuba,’ sai ka gafarta masa.” ");
INSERT INTO hausa_vpl VALUES ("LK17_5","072_17_5","LUK","17","5","5","Sai manzannin suka ce wa Ubangiji, “Ka ƙara mana bangaskiya!” ");
INSERT INTO hausa_vpl VALUES ("LK17_6","072_17_6","LUK","17","6","6","Ya amsa musu ya ce, “In kuna da bangaskiya da take ƙanƙani kamar ƙwayar mustad, kuna iya ce wa wannan itacen durumi, ‘Ka tumɓuke daga nan, ka dasu a cikin teku.’ Zai kuwa yi muku biyayya. ");
INSERT INTO hausa_vpl VALUES ("LK17_7","072_17_7","LUK","17","7","7","“In ɗaya a cikinku yana da bawa, wanda yake masa noma, ko kiwon tumaki, da dawowar bawan daga gonar, ai, ba zai ce masa, ‘Ka zo nan, ka zauna, ka ci abinci ba’? ");
INSERT INTO hausa_vpl VALUES ("LK17_8","072_17_8","LUK","17","8","8","Ashe, ba zai ce masa, ‘Ka shirya mini abincin yamma, ka shirya ka yi mini hidima domin in ci in sha, bayan haka kana iya ci, ka kuma sha ba’? ");
INSERT INTO hausa_vpl VALUES ("LK17_9","072_17_9","LUK","17","9","9","Shin, zai gode wa bawan don yă yi aikin da aka ce ya yi ne? ");
INSERT INTO hausa_vpl VALUES ("LK17_10","072_17_10","LUK","17","10","10","Haka ku ma, bayan kun yi duk abin da aka ce muku ku yi, ya kamata ku ce, ‘Mu bayi ne marasa cancanta, mun dai yi aikinmu ne kaɗai.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK17_11","072_17_11","LUK","17","11","11","Yesu yana kan hanyarsa zuwa Urushalima, sai ya bi takan iyakar Samariya da Galili. ");
INSERT INTO hausa_vpl VALUES ("LK17_12","072_17_12","LUK","17","12","12","Da zai shiga wani ƙauye, sai maza goma da suke da kuturta suka sadu da shi. Suka tsaya da nesa, ");
INSERT INTO hausa_vpl VALUES ("LK17_13","072_17_13","LUK","17","13","13","suka yi kira da babbar murya, suka ce, “Yesu, Ubangiji, ka ji tausayinmu!” ");
INSERT INTO hausa_vpl VALUES ("LK17_14","072_17_14","LUK","17","14","14","Da ya gan su sai ya ce, “Ku je ku nuna kanku ga firistoci.” Suna kan hanyar tafiya sai suka tsabtacce. ");
INSERT INTO hausa_vpl VALUES ("LK17_15","072_17_15","LUK","17","15","15","Da ɗayansu ya ga ya warke, sai ya koma, yana yabon Allah da babbar murya. ");
INSERT INTO hausa_vpl VALUES ("LK17_16","072_17_16","LUK","17","16","16","Ya zo ya fāɗi a gaban Yesu, ya gode masa. Shi kuwa mutumin Samariya ne. ");
INSERT INTO hausa_vpl VALUES ("LK17_17","072_17_17","LUK","17","17","17","Yesu ya yi tambaya ya ce, “Ba duka goma ne aka tsabtacce ba? Ina sauran taran? ");
INSERT INTO hausa_vpl VALUES ("LK17_18","072_17_18","LUK","17","18","18","Ba wanda ya dawo don yă yabi Allah, sai dai wannan baƙon?” ");
INSERT INTO hausa_vpl VALUES ("LK17_19","072_17_19","LUK","17","19","19","Sai ya ce masa, “Tashi, ka yi tafiyarka, bangaskiyarka ta warkar da kai.” ");
INSERT INTO hausa_vpl VALUES ("LK17_20","072_17_20","LUK","17","20","20","Wata rana, Farisiyawa suka tambaye shi lokacin da mulkin Allah zai zo, Yesu ya amsa ya ce, “Ai, mulkin Allah ba takan zo ta wurin yin kallon ku ba. ");
INSERT INTO hausa_vpl VALUES ("LK17_21","072_17_21","LUK","17","21","21","Mutane kuma ba za su ce, ‘Ga shi nan,’ ko kuma, ‘Ga shi can’ ba, domin mulkin Allah yana cikinku ne.” ");
INSERT INTO hausa_vpl VALUES ("LK17_22","072_17_22","LUK","17","22","22","Sai ya ce wa almajiransa, “Lokaci yana zuwa da za ku yi marmarin ganin rana ɗaya cikin ranakun Ɗan Mutum, amma ba za ku gani ba. ");
INSERT INTO hausa_vpl VALUES ("LK17_23","072_17_23","LUK","17","23","23","Mutane za su ce muku, ‘Ga shi can!’ Ko kuma, ‘Ga shi nan!’ Kada ku yi hanzarin binsu. ");
INSERT INTO hausa_vpl VALUES ("LK17_24","072_17_24","LUK","17","24","24","Gama Ɗan Mutum, a cikin ranarsa, zai zama kamar walƙiya da take walƙawa, da take kuma haskaka sararin sama, daga wannan kusurwa zuwa wancan kusurwa. ");
INSERT INTO hausa_vpl VALUES ("LK17_25","072_17_25","LUK","17","25","25","Amma da fari, dole yă sha wahaloli masu yawa, kuma mutanen zamanin nan su ƙi shi. ");
INSERT INTO hausa_vpl VALUES ("LK17_26","072_17_26","LUK","17","26","26","“Daidai kamar yadda ya faru a zamanin Nuhu, haka zai zama a zamanin Ɗan Mutum. ");
INSERT INTO hausa_vpl VALUES ("LK17_27","072_17_27","LUK","17","27","27","Mutane suna ci, suna sha, suna aurayya, ana kuma ba da su ga aure, har ranar da Nuhu ya shiga jirgin. Sa’an nan ambaliyar ruwan ya sauka, ya hallaka su duka. ");
INSERT INTO hausa_vpl VALUES ("LK17_28","072_17_28","LUK","17","28","28","“Haka ma aka yi a zamanin Lot. Mutane suna ci, suna sha, suna saya, suna sayarwa, suna shuki, suna kuma gine-gine. ");
INSERT INTO hausa_vpl VALUES ("LK17_29","072_17_29","LUK","17","29","29","Amma a ranar da Lot ya bar Sodom, sai aka yi ruwan wuta da farar wuta daga sama, aka hallaka su duka. ");
INSERT INTO hausa_vpl VALUES ("LK17_30","072_17_30","LUK","17","30","30","“Daidai haka zai zama, a ranar da Ɗan Mutum zai bayyana. ");
INSERT INTO hausa_vpl VALUES ("LK17_31","072_17_31","LUK","17","31","31","A ranan nan, kada wanda yake kan rufin gidansa ya sauka don yă kwashe dukiyarsa da take cikin gidan. Haka ma duk wanda yake gona, kada yă koma don wani abu. ");
INSERT INTO hausa_vpl VALUES ("LK17_32","072_17_32","LUK","17","32","32","Ku tuna fa da matar Lot! ");
INSERT INTO hausa_vpl VALUES ("LK17_33","072_17_33","LUK","17","33","33","Duk wanda yake so ya ceci ransa, zai rasa shi, amma duk wanda ya rasa ransa, zai cece shi. ");
INSERT INTO hausa_vpl VALUES ("LK17_34","072_17_34","LUK","17","34","34","Ina gaya muku, a daren nan, mutane biyu za su kasance a gado ɗaya, za a ɗauki ɗaya, a bar ɗayan. ");
INSERT INTO hausa_vpl VALUES ("LK17_35","072_17_35","LUK","17","35","35","Mata biyu za su kasance suna niƙan hatsi tare, za a ɗauki ɗaya, a bar ɗayan.” ");
INSERT INTO hausa_vpl VALUES ("LK17_37","072_17_37","LUK","17","37","37","Suka tambaya, suka ce, “A ina ne, ya Ubangiji?” Ya ce musu, “Ai, inda gawa take, nan ne ungulai za su taru.” ");
INSERT INTO hausa_vpl VALUES ("LK18_1","072_18_1","LUK","18","1","1","Yesu ya ba wa almajiransa wani misali, don yă koya musu yadda ya kamata su dinga yin addu’a kullum, ban da fasawa. ");
INSERT INTO hausa_vpl VALUES ("LK18_2","072_18_2","LUK","18","2","2","Ya ce, “A wani gari, an yi wani alƙali wanda ba ya tsoron Allah, bai kuma kula da mutane ba. ");
INSERT INTO hausa_vpl VALUES ("LK18_3","072_18_3","LUK","18","3","3","A garin nan kuma, akwai wata gwauruwa, wadda ta dinga zuwa wurin alƙalin nan, da roƙo cewa, ‘Ka yi mini adalci tsakanina da maƙiyina.’ ");
INSERT INTO hausa_vpl VALUES ("LK18_4","072_18_4","LUK","18","4","4","“An daɗe yana ƙi, amma a ƙarshe ya ce cikin tunaninsa, ‘Ko da yake ba na tsoron Allah, ba na kuma kula da mutane ba, ");
INSERT INTO hausa_vpl VALUES ("LK18_5","072_18_5","LUK","18","5","5","amma don gwauruwan nan ta dame ni, zan tabbatar cewa ta sami adalci, domin kada tă gajiyar da ni, da yawan zuwanta.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK18_6","072_18_6","LUK","18","6","6","Sai Ubangiji ya ce, “Ku ji fa abin da alƙalin nan, marar gaskiya, ya ce. ");
INSERT INTO hausa_vpl VALUES ("LK18_7","072_18_7","LUK","18","7","7","Ashe, Allah ba zai biya wa zaɓaɓɓunsa da suke masa kuka, dare da rana adalci ba? Zai ci gaba da ƙin sauraronsu ne? ");
INSERT INTO hausa_vpl VALUES ("LK18_8","072_18_8","LUK","18","8","8","Ina gaya muku, zai tabbatar sun sami adalci, ban da ɓatan lokaci. Amma sa’ad da Ɗan Mutum ya dawo, zai sami bangaskiya a duniya ke nan?” ");
INSERT INTO hausa_vpl VALUES ("LK18_9","072_18_9","LUK","18","9","9","Yesu ya kuma faɗi wannan misali ga waɗansu masu taƙama da adalcinsu, kuma suna rena sauran mutane ya ce, ");
INSERT INTO hausa_vpl VALUES ("LK18_10","072_18_10","LUK","18","10","10","“Waɗansu mutane biyu sun tafi haikali don yin addu’a. Ɗaya Bafarisiye ne, ɗayan kuma mai karɓar haraji. ");
INSERT INTO hausa_vpl VALUES ("LK18_11","072_18_11","LUK","18","11","11","Sai Bafarisiyen ya tashi tsaye, ya yi addu’a game da kansa yana cewa, ‘Allah, na gode maka, saboda ni ba kamar sauran mutane ba ne, wato, mafasa, masu aikata mugunta, masu zina, ko kuma kamar mai karɓar harajin nan. ");
INSERT INTO hausa_vpl VALUES ("LK18_12","072_18_12","LUK","18","12","12","Ina azumi sau biyu a mako, ina ba da zakka daga kowane abin da na samu.’ ");
INSERT INTO hausa_vpl VALUES ("LK18_13","072_18_13","LUK","18","13","13","“Amma mai karɓar harajin ya tsaya daga nesa. Bai ma iya ɗaga kansa sama ba, sai ya buga ƙirjinsa, yana cewa, ‘Allah, ka yi mini jinƙai, ni mai zunubi ne.’ ");
INSERT INTO hausa_vpl VALUES ("LK18_14","072_18_14","LUK","18","14","14","“Ina gaya muku, wannan mutum ne, ba ɗayan ba, ya koma gida baratacce, babu laifi a gaban Allah. Gama duk wanda ya ɗaukaka kansa, za a ƙasƙantar da shi. Wanda kuma ya ƙasƙantar da kansa, za a ɗaukaka shi.” ");
INSERT INTO hausa_vpl VALUES ("LK18_15","072_18_15","LUK","18","15","15","Mutane suna kawo jarirai wurin Yesu don yă taɓa su. Da almajiransa suka ga haka, sai suka kwaɓe su. ");
INSERT INTO hausa_vpl VALUES ("LK18_16","072_18_16","LUK","18","16","16","Amma Yesu ya kira yaran a wurinsa ya ce, “Ku bar yara ƙanana su zo wurina. Kada ku hana su, gama mulkin Allah na irin waɗannan ne. ");
INSERT INTO hausa_vpl VALUES ("LK18_17","072_18_17","LUK","18","17","17","Gaskiya nake gaya muku, duk wanda ba zai karɓi mulkin Allah kamar ƙaramin yaro ba, ba zai taɓa shiga mulkin ba.” ");
INSERT INTO hausa_vpl VALUES ("LK18_18","072_18_18","LUK","18","18","18","Wani mai mulki ya tambayi Yesu ya ce, “Malam managarci, me zan yi don in gāji rai madawwami?” ");
INSERT INTO hausa_vpl VALUES ("LK18_19","072_18_19","LUK","18","19","19","Yesu ya amsa ya ce, “Don me kake kira na managarci? Ai, ba wani nagari, sai Allah kaɗai. ");
INSERT INTO hausa_vpl VALUES ("LK18_20","072_18_20","LUK","18","20","20","Ka san dokokin da suka ce, ‘Kada ka yi zina, kada ka yi kisankai, kada ka yi sata, kada ka ba da shaida ta ƙarya, ka girmama mahaifinka da mahaifiyarka.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK18_21","072_18_21","LUK","18","21","21","Mutumin ya ce, “Ai, tun ina ƙarami, na kiyaye duka waɗannan.” ");
INSERT INTO hausa_vpl VALUES ("LK18_22","072_18_22","LUK","18","22","22","Da Yesu ya ji haka, sai ya ce masa, “Akwai abu ɗaya har yanzu da ya rage maka. Ka sayar da duk abin da kake da shi, ka ba wa matalauta, sa’an nan za ka sami dukiya a sama. Bayan haka, ka zo ka bi ni.” ");
INSERT INTO hausa_vpl VALUES ("LK18_23","072_18_23","LUK","18","23","23","Da jin haka, sai ya ɓata rai, domin shi mai arziki ne sosai. ");
INSERT INTO hausa_vpl VALUES ("LK18_24","072_18_24","LUK","18","24","24","Yesu ya kalle shi ya ce, “Yana da wuya fa, masu arziki su shiga mulkin Allah! ");
INSERT INTO hausa_vpl VALUES ("LK18_25","072_18_25","LUK","18","25","25","Tabbatacce, zai fi sauƙi raƙumi ya shiga ta kafar allura, da mai arziki ya shiga mulkin Allah.” ");
INSERT INTO hausa_vpl VALUES ("LK18_26","072_18_26","LUK","18","26","26","Waɗanda suka ji wannan suka yi tambaya suka ce, “To, wa zai iya samun ceto?” ");
INSERT INTO hausa_vpl VALUES ("LK18_27","072_18_27","LUK","18","27","27","Yesu ya amsa ya ce, “Abin da ba ya yiwuwa ga mutane, mai yiwuwa ne ga Allah.” ");
INSERT INTO hausa_vpl VALUES ("LK18_28","072_18_28","LUK","18","28","28","Sai Bitrus ya ce, masa, “To, ga shi mun bar kome da muke da shi, don mu bi ka!” ");
INSERT INTO hausa_vpl VALUES ("LK18_29","072_18_29","LUK","18","29","29","Yesu ya ce musu, “Gaskiya nake gaya muku, ba wanda ya bar gida, ko mata, ko ’yan’uwa maza, ko iyaye, ko yara, saboda mulkin Allah, ");
INSERT INTO hausa_vpl VALUES ("LK18_30","072_18_30","LUK","18","30","30","da zai kāsa samun riɓi mai yawa, a wannan zamani, ya kuma sami rai madawwami a zamani mai zuwa.” ");
INSERT INTO hausa_vpl VALUES ("LK18_31","072_18_31","LUK","18","31","31","Sai ya kai Sha Biyun gefe ɗaya, ya ce musu, “Za mu Urushalima, kuma dukan abin da annabawa suka rubuta a kan Ɗan Mutum zai cika. ");
INSERT INTO hausa_vpl VALUES ("LK18_32","072_18_32","LUK","18","32","32","Za a ba da shi ga Al’ummai, za su yi masa ba’a, su zage shi, su tofa masa miyau, ");
INSERT INTO hausa_vpl VALUES ("LK18_33","072_18_33","LUK","18","33","33","za su yi masa bulala, su kuma kashe shi. A rana ta uku kuma zai tashi.” ");
INSERT INTO hausa_vpl VALUES ("LK18_34","072_18_34","LUK","18","34","34","Almajiran ba su gane da ko ɗaya daga cikin wannan ba. An ɓoye musu ma’anarsa, kuma ba su gane da abin da yake magana a kai ba. ");
INSERT INTO hausa_vpl VALUES ("LK18_35","072_18_35","LUK","18","35","35","Da Yesu ya yi kusa da Yeriko, akwai wani makaho da yake zaune a gefen hanya, yana bara. ");
INSERT INTO hausa_vpl VALUES ("LK18_36","072_18_36","LUK","18","36","36","Da ya ji taron suna wucewa, sai ya yi tambaya ko mene ne ke faruwa. ");
INSERT INTO hausa_vpl VALUES ("LK18_37","072_18_37","LUK","18","37","37","Suka ce masa, “Ai, Yesu Banazare ne ke wucewa.” ");
INSERT INTO hausa_vpl VALUES ("LK18_38","072_18_38","LUK","18","38","38","Sai ya yi kira ya ce, “Yesu, Ɗan Dawuda, ka yi mini jinƙai!” ");
INSERT INTO hausa_vpl VALUES ("LK18_39","072_18_39","LUK","18","39","39","Mutane da suke gaba suka kwaɓe shi, suka ce masa ya yi shiru. Amma sai ya ƙara ɗaga murya, yana cewa, “Ɗan Dawuda, ka yi mini jinƙai!” ");
INSERT INTO hausa_vpl VALUES ("LK18_40","072_18_40","LUK","18","40","40","Sai Yesu ya tsaya, ya ba da umarni a kawo mutumin wurinsa. Da ya zo kusa, Yesu ya tambaye shi ya ce, ");
INSERT INTO hausa_vpl VALUES ("LK18_41","072_18_41","LUK","18","41","41","“Me kake so in yi maka?” Sai ya amsa ya ce, “Ubangiji, ina so in sami ganin gari.” ");
INSERT INTO hausa_vpl VALUES ("LK18_42","072_18_42","LUK","18","42","42","Yesu ya ce masa, “Ka sami ganin garinka; bangaskiyarka ta warkar da kai.” ");
INSERT INTO hausa_vpl VALUES ("LK18_43","072_18_43","LUK","18","43","43","Nan da nan, ya sami ganin garinsa, kuma ya bi Yesu, yana yabon Allah. Da dukan mutane suka ga wannan, sai su ma suka yabi Allah. ");
INSERT INTO hausa_vpl VALUES ("LK19_1","072_19_1","LUK","19","1","1","Yesu ya shiga Yeriko, yana ratsa ta cikinta. ");
INSERT INTO hausa_vpl VALUES ("LK19_2","072_19_2","LUK","19","2","2","Akwai wani mutum a garin, mai suna Zakka. Shi shugaban masu karɓar haraji ne, mai arziki kuma. ");
INSERT INTO hausa_vpl VALUES ("LK19_3","072_19_3","LUK","19","3","3","Ya so yă ga ko wane ne Yesu, amma saboda taron, bai iya ba, domin shi gajere ne. ");
INSERT INTO hausa_vpl VALUES ("LK19_4","072_19_4","LUK","19","4","4","Saboda haka, ya yi gaba da gudu, kuma ya hau itacen sikamo, don yă gan shi, tun da Yesu zai bi wannan hanyar ne. ");
INSERT INTO hausa_vpl VALUES ("LK19_5","072_19_5","LUK","19","5","5","Da Yesu ya iso wurin, sai ya ɗaga ido sama, ya ce masa, “Zakka, ka yi maza ka sauka. Ni kam, dole in sauka a gidanka yau.” ");
INSERT INTO hausa_vpl VALUES ("LK19_6","072_19_6","LUK","19","6","6","Sai ya sauka nan da nan, ya karɓe shi da murna. ");
INSERT INTO hausa_vpl VALUES ("LK19_7","072_19_7","LUK","19","7","7","Dukan mutane suka ga haka, kuma suka fara gunaguni, suka ce, “Ya je don yă zama baƙon ‘mai zunubi.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK19_8","072_19_8","LUK","19","8","8","Amma Zakka ya tashi a tsaye, ya ce wa Ubangiji, “Duba, Ubangiji! Nan take, rabin dukiyar da nake da shi, na ba wa matalauta. In kuma na taɓa cutan wani, a kan wani abu, zan mayar da shi ninki huɗu.” ");
INSERT INTO hausa_vpl VALUES ("LK19_9","072_19_9","LUK","19","9","9","Sai Yesu ya ce masa, “Yau, ceto ya zo gidan nan, domin wannan mutum shi ma ɗan Ibrahim ne. ");
INSERT INTO hausa_vpl VALUES ("LK19_10","072_19_10","LUK","19","10","10","Saboda Ɗan Mutum ya zo ne, domin yă nemi abin da ya ɓata, yă cece shi kuma.” ");
INSERT INTO hausa_vpl VALUES ("LK19_11","072_19_11","LUK","19","11","11","Yayinda suna cikin sauraron wannan, sai ya ci gaba da gaya musu wani misali, domin ya yi kusa da Urushalima, kuma mutanen suna tsammani mulkin Allah zai bayyana, nan da nan. ");
INSERT INTO hausa_vpl VALUES ("LK19_12","072_19_12","LUK","19","12","12","Ya ce, “Wani mutum mai martaba ya tafi wata ƙasa mai nisa don a naɗa shi sarki sa’an nan ya dawo. ");
INSERT INTO hausa_vpl VALUES ("LK19_13","072_19_13","LUK","19","13","13","Saboda haka ya kira bayinsa goma ya ba su mina goma. Ya ce, ‘Ku yi kasuwanci da kuɗin nan, sai na dawo.’ ");
INSERT INTO hausa_vpl VALUES ("LK19_14","072_19_14","LUK","19","14","14","“Amma talakawansa suka ƙi shi, sai suka aikar da wakilai bayansa, domin su ce, ‘Ba mu son wannan mutum ya zama sarkinmu.’ ");
INSERT INTO hausa_vpl VALUES ("LK19_15","072_19_15","LUK","19","15","15","“Duk da haka, aka naɗa shi sarki, sa’an nan ya dawo gida. Sai ya aika aka kira bayin da ya ba su kuɗin, don yă san ribar da suka samu. ");
INSERT INTO hausa_vpl VALUES ("LK19_16","072_19_16","LUK","19","16","16","“Na fari ya zo ya ce, ‘Ranka yă daɗe, minarka ya sami ribar goma.’ ");
INSERT INTO hausa_vpl VALUES ("LK19_17","072_19_17","LUK","19","17","17","“Maigidan ya amsa ya ce, ‘Madalla, bawana mai kirki! Tun da ka yi aminci a kan abu ƙanƙani, ka yi riƙon birane goma.’ ");
INSERT INTO hausa_vpl VALUES ("LK19_18","072_19_18","LUK","19","18","18","“Na biyun ya zo ya ce, ‘Ranka yă daɗe, minarka ya sami ribar biyar.’ ");
INSERT INTO hausa_vpl VALUES ("LK19_19","072_19_19","LUK","19","19","19","“Maigidansa ya ce, ‘Kai ka yi riƙon birane biyar.’ ");
INSERT INTO hausa_vpl VALUES ("LK19_20","072_19_20","LUK","19","20","20","“Sai wani bawan ya zo ya ce, ‘Ranka yă daɗe, ga minarka. Na ɓoye shi a wani ɗan tsumma. ");
INSERT INTO hausa_vpl VALUES ("LK19_21","072_19_21","LUK","19","21","21","Na ji tsoronka, don kai mai wuyan sha’ani ne. Kakan ɗauki abin da ba ka ajiye ba, kakan kuma yi girbin abin da ba ka shuka ba.’ ");
INSERT INTO hausa_vpl VALUES ("LK19_22","072_19_22","LUK","19","22","22","“Sai maigidansa, ya amsa ya ce, ‘Zan hukunta ka a kan kalmominka, kai mugun bawa! Ashe, ka san cewa ni mai wuyan sha’ani ne, nakan ɗauka abin da ban ajiye ba, ina kuma girbin abin da ban shuka ba? ");
INSERT INTO hausa_vpl VALUES ("LK19_23","072_19_23","LUK","19","23","23","Don me ba ka sa kuɗina a wajen ajiya, don in na dawo, in sami riba a kai ba?’ ");
INSERT INTO hausa_vpl VALUES ("LK19_24","072_19_24","LUK","19","24","24","“Sai ya ce wa waɗanda suke tsaye a wajen, ‘Ku karɓi minarsa ku ba wa wanda yake da mina goma.’ ");
INSERT INTO hausa_vpl VALUES ("LK19_25","072_19_25","LUK","19","25","25","“Suka ce, ‘Ranka yă daɗe, ai, yana da guda goma ko!’ ");
INSERT INTO hausa_vpl VALUES ("LK19_26","072_19_26","LUK","19","26","26","“Ya amsa ya ce, ‘Ina gaya muku, duk wanda yake da abu, za a ƙara masa. Amma wanda ba shi da shi kuwa, ko abin da yake da shi ma, za a karɓe. ");
INSERT INTO hausa_vpl VALUES ("LK19_27","072_19_27","LUK","19","27","27","Amma waɗannan abokan gābana, waɗanda ba su so in zama sarkinsu ba, ku kawo su nan, ku karkashe su, a gabana.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK19_28","072_19_28","LUK","19","28","28","Bayan Yesu ya yi wannan magana, sai ya yi gaba zuwa Urushalima. ");
INSERT INTO hausa_vpl VALUES ("LK19_29","072_19_29","LUK","19","29","29","Da ya kai kusa da Betfaji da Betani, a tudun da ake kira Dutsen Zaitun, sai ya aiki almajiransa guda biyu, ya ce musu, ");
INSERT INTO hausa_vpl VALUES ("LK19_30","072_19_30","LUK","19","30","30","“Ku je ƙauyen da yake gaba da ku. Da kuna shiga, za ku tarar da wani ɗan jaki, wadda ba wanda ya taɓa hawa, a daure a wurin. Ku kunce shi ku kawo nan. ");
INSERT INTO hausa_vpl VALUES ("LK19_31","072_19_31","LUK","19","31","31","In wani ya tambaye ku, ‘Don me kuke kunce shi?’ Ku ce masa, ‘Ubangiji yana bukatarsa.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK19_32","072_19_32","LUK","19","32","32","Waɗanda aka aika su yi gaba suka tafi, suka kuwa tarar kamar yadda ya gaya musu. ");
INSERT INTO hausa_vpl VALUES ("LK19_33","072_19_33","LUK","19","33","33","Suna cikin kunce ɗan jakin, sai masu ɗan jakin suka ce musu, “Don me kuke kunce shi?” ");
INSERT INTO hausa_vpl VALUES ("LK19_34","072_19_34","LUK","19","34","34","Suka amsa suka ce, “Ubangiji ne na bukatarsa.” ");
INSERT INTO hausa_vpl VALUES ("LK19_35","072_19_35","LUK","19","35","35","Suka kawo shi wurin Yesu. Suka sa rigunarsu a kan ɗan jakin, sa’an nan suka sa Yesu a kai. ");
INSERT INTO hausa_vpl VALUES ("LK19_36","072_19_36","LUK","19","36","36","Yana cikin tafiya, sai mutane suka shimfiɗa rigunarsu a kan hanya. ");
INSERT INTO hausa_vpl VALUES ("LK19_37","072_19_37","LUK","19","37","37","Da ya yi kusa da wurin da hanyar ta gangara zuwa Dutsen Zaitun, sai dukan taron almajirai suka fara yabon Allah, da muryoyi masu ƙarfi, da murna, saboda dukan ayyukan banmamaki da suka gani. Suna cewa, ");
INSERT INTO hausa_vpl VALUES ("LK19_38","072_19_38","LUK","19","38","38","“Mai albarka ne sarki wanda yake zuwa cikin sunan Ubangiji!” “Salama ta kasance a sama, da ɗaukaka kuma a can cikin sama!” ");
INSERT INTO hausa_vpl VALUES ("LK19_39","072_19_39","LUK","19","39","39","Sai waɗansu Farisiyawa a cikin taron suka ce wa Yesu, “Malam, ka kwaɓi almajiranka!” ");
INSERT INTO hausa_vpl VALUES ("LK19_40","072_19_40","LUK","19","40","40","Ya amsa ya ce, “Ina gaya muku, ko da sun yi shiru, duwatsu za su fara kirari.” ");
INSERT INTO hausa_vpl VALUES ("LK19_41","072_19_41","LUK","19","41","41","Da ya yi kusa da Urushalima, ya kuma ga birnin, sai ya yi kuka a kanta, ");
INSERT INTO hausa_vpl VALUES ("LK19_42","072_19_42","LUK","19","42","42","kuma ya ce, “In ke, ko ke ɗin ma, dā ma kin san abin da zai kawo miki salama a wannan rana, amma yanzu an ɓoye shi daga idanunki. ");
INSERT INTO hausa_vpl VALUES ("LK19_43","072_19_43","LUK","19","43","43","Ranakun za su auko miki, a lokacin da abokan gābanki za su gina bango gāba da ke, su kuma kewaye inda kike, za su kuma tsare kowane gefenki, su sa ke a tsakiya. ");
INSERT INTO hausa_vpl VALUES ("LK19_44","072_19_44","LUK","19","44","44","Za su fyaɗa ke a ƙasa, ke da ’ya’yan da suke cikin katanganki. Ba za su bar wani dutse a kan wani ba, saboda ba ki gane da lokacin da Allah zai ziyarce ki ba.” ");
INSERT INTO hausa_vpl VALUES ("LK19_45","072_19_45","LUK","19","45","45","Sai ya shiga filin haikali, ya fara korar masu sayar da kaya. ");
INSERT INTO hausa_vpl VALUES ("LK19_46","072_19_46","LUK","19","46","46","Ya ce musu, “A rubuce, yake cewa, ‘Gidana, zai zama gidan addu’a,’amma ga shi kun mai da shi ‘kogon ’yan fashi.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK19_47","072_19_47","LUK","19","47","47","Kowace rana, ya yi ta koyarwa a haikalin. Amma manyan firistoci, da malaman dokoki, da shugabannin mutane, suna ƙoƙarin kashe shi. ");
INSERT INTO hausa_vpl VALUES ("LK19_48","072_19_48","LUK","19","48","48","Amma ba su sami hanyar yin haka ba, domin kalmominsa sun kama hankalin dukan mutanen. ");
INSERT INTO hausa_vpl VALUES ("LK20_1","072_20_1","LUK","20","1","1","Wata rana da Yesu yana koyar da mutane, yana musu wa’azin bishara a filin haikalin, sai manyan firistoci da malaman dokoki, tare da dattawan suka zo wurinsa. ");
INSERT INTO hausa_vpl VALUES ("LK20_2","072_20_2","LUK","20","2","2","Suka ce masa, “Gaya mana, da wane iko kake yin waɗannan abubuwa. Wa ya ba ka wannan ikon?” ");
INSERT INTO hausa_vpl VALUES ("LK20_3","072_20_3","LUK","20","3","3","Ya amsa ya ce, “Ni ma zan yi muku wata tambaya. Ku faɗa mini, ");
INSERT INTO hausa_vpl VALUES ("LK20_4","072_20_4","LUK","20","4","4","baftismar Yohanna, daga sama ne ta fito, ko kuwa daga wurin mutane ne?” ");
INSERT INTO hausa_vpl VALUES ("LK20_5","072_20_5","LUK","20","5","5","Sai suka yi shawara da junansu, suka ce, “In muka ce, ‘Daga sama ne,’ zai tambaya, ‘To, don me ba ku gaskata shi ba?’ ");
INSERT INTO hausa_vpl VALUES ("LK20_6","072_20_6","LUK","20","6","6","Amma in kuma muka ce, ‘Daga mutane ne,’ dukan mutanen za su jajjefe mu da duwatsu, domin sun tabbata cewa, Yohanna annabi ne.” ");
INSERT INTO hausa_vpl VALUES ("LK20_7","072_20_7","LUK","20","7","7","Don haka, sai suka amsa cewa, “Ba mu san inda ta fito ba.” ");
INSERT INTO hausa_vpl VALUES ("LK20_8","072_20_8","LUK","20","8","8","Yesu ya ce, “To, ni ma ba zan gaya muku, ko da wane iko ne, nake yin waɗannan abubuwa ba.” ");
INSERT INTO hausa_vpl VALUES ("LK20_9","072_20_9","LUK","20","9","9","Sai ya ci gaba da gaya wa mutanen wannan misali ya ce, “Wani mutum ya yi gonar inabi, sai ya ba da hayarta ga waɗansu manoma, sa’an nan ya yi wata doguwar tafiya. ");
INSERT INTO hausa_vpl VALUES ("LK20_10","072_20_10","LUK","20","10","10","A lokacin girbi, sai ya aiki bawa zuwa wurin masu hayan, don su ba shi daga cikin ’ya’yan inabin. Amma ’yan hayan suka yi wa bawan nan dūka, suka kore shi hannu wofi. ");
INSERT INTO hausa_vpl VALUES ("LK20_11","072_20_11","LUK","20","11","11","Ya sāke aikan wani bawa, shi ma suka yi masa dūka, suka kunyata shi, suka kuma kore shi hannu wofi. ");
INSERT INTO hausa_vpl VALUES ("LK20_12","072_20_12","LUK","20","12","12","Har yanzu, ya sāke aikan na uku, amma suka ji masa rauni, suka jefar da shi waje. ");
INSERT INTO hausa_vpl VALUES ("LK20_13","072_20_13","LUK","20","13","13","“Sai mai gonar inabin ya ce, ‘Me zan yi? Zan aiki ɗana da nake ƙauna, wataƙila za su girmama shi.’ ");
INSERT INTO hausa_vpl VALUES ("LK20_14","072_20_14","LUK","20","14","14","“Amma da ’yan hayan suka gan shi, sai suka tattauna zancen, suka ce, ‘Wannan shi ne magājin, mu kashe shi sa’an nan gādon zai zama namu!’ ");
INSERT INTO hausa_vpl VALUES ("LK20_15","072_20_15","LUK","20","15","15","Sai suka fitar da shi waje, suka kashe shi. “To, me mai gonar inabin zai yi da su? ");
INSERT INTO hausa_vpl VALUES ("LK20_16","072_20_16","LUK","20","16","16","Zai zo ya karkashe masu hayan nan, ya ba wa waɗansu gonar inabin.” Da mutanen suka ji wannan, sai suka ce, “Allah ya sawwaƙa!” ");
INSERT INTO hausa_vpl VALUES ("LK20_17","072_20_17","LUK","20","17","17","Yesu ya zura musu ido ya ce, “To, mene ne ma’anar abin da aka rubuta cewa, “ ‘Dutsen da magina suka ƙi, shi ne kuwa ya zama dutsen kan ginin’ ");
INSERT INTO hausa_vpl VALUES ("LK20_18","072_20_18","LUK","20","18","18","Duk wanda ya fāɗi a kan dutsen nan, zai kakkarye. Kuma in dutsen nan ya fāɗi a kan wani, zai murƙushe shi.” ");
INSERT INTO hausa_vpl VALUES ("LK20_19","072_20_19","LUK","20","19","19","Malaman dokoki da manyan firistoci, suka nemi hanyar kama shi nan da nan, domin sun san cewa, ya yi wannan misali a kansu ne, amma suna jin tsoron mutane. ");
INSERT INTO hausa_vpl VALUES ("LK20_20","072_20_20","LUK","20","20","20","Sai suka sa masa ido, suka aiki ’yan leƙen asiri, waɗanda suka nuna kamar su masu gaskiya ne, suna nufin su kama shi game da abin da zai faɗa, domin su ba da shi ga gwamna mai mulki, da mai iko. ");
INSERT INTO hausa_vpl VALUES ("LK20_21","072_20_21","LUK","20","21","21","Sai ’yan leƙen asirin suka tambaye shi, suka ce, “Malam, mun sani kana faɗin, kuma kana koyar da abin da yake daidai, ba ka kuma nuna bambanci, amma kana koyar da hanyar Allah bisa ga gaskiya. ");
INSERT INTO hausa_vpl VALUES ("LK20_22","072_20_22","LUK","20","22","22","Daidai ne mu biya haraji ga Kaisar, ko babu?” ");
INSERT INTO hausa_vpl VALUES ("LK20_23","072_20_23","LUK","20","23","23","Ya gane makircinsu, sai ya ce musu, ");
INSERT INTO hausa_vpl VALUES ("LK20_24","072_20_24","LUK","20","24","24","“Nuna mini dinari. Hoton wane ne, kuma rubutun wane ne a kai?” Suka amsa, “Na Kaisar.” ");
INSERT INTO hausa_vpl VALUES ("LK20_25","072_20_25","LUK","20","25","25","Sai ya ce musu, “Ku ba wa Kaisar abin da yake na Kaisar, ku kuma ba wa Allah abin da yake na Allah.” ");
INSERT INTO hausa_vpl VALUES ("LK20_26","072_20_26","LUK","20","26","26","Ba su iya kama shi a kan abin da ya faɗa a fili ba. Amsarsa ya ba su mamaki, shi ya sa suka yi shiru. ");
INSERT INTO hausa_vpl VALUES ("LK20_27","072_20_27","LUK","20","27","27","Waɗansu Sadukiyawa da suke cewa, ba tashin matattu, suka zo wurin Yesu da tambaya cewa, ");
INSERT INTO hausa_vpl VALUES ("LK20_28","072_20_28","LUK","20","28","28","“Malam, Musa ya rubuta mana cewa, ‘In ɗan’uwan wani mutum ya mutu, ya bar mata amma ba ’ya’ya, dole mutumin ya aure gwauruwar, ya samo wa ɗan’uwansa ’ya’ya.’ ");
INSERT INTO hausa_vpl VALUES ("LK20_29","072_20_29","LUK","20","29","29","To, an yi waɗansu ’yan’uwa bakwai. Na fari ya auri wata mace, ya mutu ba ’ya’ya. ");
INSERT INTO hausa_vpl VALUES ("LK20_30","072_20_30","LUK","20","30","30","Na biyun, ");
INSERT INTO hausa_vpl VALUES ("LK20_31","072_20_31","LUK","20","31","31","da na ukun suka aure ta. Haka nan dukansu bakwai suka mutu babu ’ya’ya. ");
INSERT INTO hausa_vpl VALUES ("LK20_32","072_20_32","LUK","20","32","32","A ƙarshe, ita macen ma ta mutu. ");
INSERT INTO hausa_vpl VALUES ("LK20_33","072_20_33","LUK","20","33","33","Shin, a tashin matattu, matar wa za tă zama? Tun da su bakwan nan, sun aure ta.” ");
INSERT INTO hausa_vpl VALUES ("LK20_34","072_20_34","LUK","20","34","34","Yesu ya amsa ya ce, “Mutanen zamanin nan suna aure, suna kuma ba da aure, ");
INSERT INTO hausa_vpl VALUES ("LK20_35","072_20_35","LUK","20","35","35","amma su waɗanda aka ga sun cancantar kasancewa a zamanin can, da kuma na tashin matattu, ba za su yi aure, ko su ba da aure ba. ");
INSERT INTO hausa_vpl VALUES ("LK20_36","072_20_36","LUK","20","36","36","Kuma ba za su sāke mutuwa ba, gama su kamar mala’iku ne. Su ’ya’yan Allah ne, tun da su ’ya’yan tashin matattu ne. ");
INSERT INTO hausa_vpl VALUES ("LK20_37","072_20_37","LUK","20","37","37","Amma bisa ga labari na bishiya nan, mai cin wuta da Musa ya gani a jeji, ko Musa ma, ya nuna cewa, matattu suna tashi. Gama ya kira Ubangiji, ‘Allah na Ibrahim, da Allah na Ishaku, da kuma Allah na Yaƙub.’ ");
INSERT INTO hausa_vpl VALUES ("LK20_38","072_20_38","LUK","20","38","38","Shi ba Allah na matattu ba ne, amma na masu rai ne, gama a gare shi, duka na da rai.” ");
INSERT INTO hausa_vpl VALUES ("LK20_39","072_20_39","LUK","20","39","39","Sai waɗansu malaman dokoki suka amsa suka ce, “Ka faɗi daidai, malam!” ");
INSERT INTO hausa_vpl VALUES ("LK20_40","072_20_40","LUK","20","40","40","Kuma ba wanda ya sami ƙarfin halin yin masa waɗansu tambayoyi. ");
INSERT INTO hausa_vpl VALUES ("LK20_41","072_20_41","LUK","20","41","41","Sai Yesu ya ce musu, “Yaya suke cewa, ‘Kiristi ɗan Dawuda ne?’ ");
INSERT INTO hausa_vpl VALUES ("LK20_42","072_20_42","LUK","20","42","42","Dawuda da kansa ya faɗa a cikin Zabura, “ ‘Ubangiji ya ce wa Ubangijina, “Zauna a hannun damana, ");
INSERT INTO hausa_vpl VALUES ("LK20_43","072_20_43","LUK","20","43","43","sai na sa abokan gābanka su zama matashin sawunka.” ’ ");
INSERT INTO hausa_vpl VALUES ("LK20_44","072_20_44","LUK","20","44","44","Dawuda ya kira shi ‘Ubangiji.’ Ta, yaya zai zama ɗansa?” ");
INSERT INTO hausa_vpl VALUES ("LK20_45","072_20_45","LUK","20","45","45","Yayinda dukan mutane suna cikin sauraronsa, sai Yesu ya ce wa almajiransa, ");
INSERT INTO hausa_vpl VALUES ("LK20_46","072_20_46","LUK","20","46","46","“Ku yi hankali da malaman dokoki. Sukan so sa manyan riguna suna zaga, suna sha’awan karɓan gaisuwa a wuraren kasuwanci, da kuma wuraren zama mafi daraja a majami’u, da wuraren bangirma a bukukkuwa. ");
INSERT INTO hausa_vpl VALUES ("LK20_47","072_20_47","LUK","20","47","47","Suna mamaye gidajen gwauraye, kuma don burga, suna dogayen addu’o’i. Ga irin waɗannan mutane, za a yi musu hukunci mai tsanani sosai.” ");
INSERT INTO hausa_vpl VALUES ("LK21_1","072_21_1","LUK","21","1","1","Da Yesu ya ɗaga ido, sai ya ga waɗansu masu arziki suna sa baikonsu a ma’ajin haikalin. ");
INSERT INTO hausa_vpl VALUES ("LK21_2","072_21_2","LUK","21","2","2","Ya kuma ga wata gwauruwa matalauciya, ta saka anini biyu. ");
INSERT INTO hausa_vpl VALUES ("LK21_3","072_21_3","LUK","21","3","3","Sai ya ce, “Gaskiya ina faɗa muku, wacce nan gwauruwa matalauciya ta sa fiye da dukan sauran. ");
INSERT INTO hausa_vpl VALUES ("LK21_4","072_21_4","LUK","21","4","4","Dukan mutanen nan sun ba da baikonsu daga cikin arzikinsu ne, amma ita daga cikin talaucinta, ta saka duk abin da take da shi na rayuwa.” ");
INSERT INTO hausa_vpl VALUES ("LK21_5","072_21_5","LUK","21","5","5","Waɗansu daga cikin almajiransa, suka fara magana a kan yadda aka yi wa haikalin ado da duwatsu masu kyau, da kuma kyautai da aka keɓe wa Allah. Amma Yesu ya ce, ");
INSERT INTO hausa_vpl VALUES ("LK21_6","072_21_6","LUK","21","6","6","“Wannan abin da kuke kallo a nan, lokaci yana zuwa da ba za a bar wani dutse a kan wani dutse ba. Kowannensu, za a rushe shi.” ");
INSERT INTO hausa_vpl VALUES ("LK21_7","072_21_7","LUK","21","7","7","Suka tambaye shi suka ce, “Malam, yaushe waɗannan za su faru? Kuma wace alama za tă nuna cewa suna dab da faruwa?” ");
INSERT INTO hausa_vpl VALUES ("LK21_8","072_21_8","LUK","21","8","8","Ya amsa ya ce, “Ku lura, kada ku kuma a ruɗe ku. Gama da yawa za su zo a cikin sunana, suna cewa, ‘Ai, ni ne shi,’ da kuma, ‘Lokaci ya yi kusa.’ Kada ku bi su. ");
INSERT INTO hausa_vpl VALUES ("LK21_9","072_21_9","LUK","21","9","9","Sa’ad da kuka ji labarin yaƙe-yaƙe, da juye juyen mulki, kada ku tsorota. Dole ne waɗannan abubuwa su fara faruwa, amma ƙarshen ba zai zo nan da nan ba.” ");
INSERT INTO hausa_vpl VALUES ("LK21_10","072_21_10","LUK","21","10","10","Sai ya ce musu, “Al’umma za tă tasar wa al’umma, mulki zai tasar wa mulki. ");
INSERT INTO hausa_vpl VALUES ("LK21_11","072_21_11","LUK","21","11","11","Za a yi manyan girgizar ƙasa, da yunwa, da annoba a wurare dabam-dabam, da kuma abubuwa masu bantsoro, da manyan alamu daga sama. ");
INSERT INTO hausa_vpl VALUES ("LK21_12","072_21_12","LUK","21","12","12","“Amma kafin duk abubuwa nan, za a kama ku a tsananta muku. Za a kai ku majami’u, da kurkuku. Za a kuma kai ku gaban sarakuna da gwamnoni, kuma dukan waɗannan saboda sunana. ");
INSERT INTO hausa_vpl VALUES ("LK21_13","072_21_13","LUK","21","13","13","Wannan zai sa ku zama shaidu a gare su. ");
INSERT INTO hausa_vpl VALUES ("LK21_14","072_21_14","LUK","21","14","14","Amma ku yi ƙuduri, wato, ku shirya zuciyarku, a kan ba za ku damu ba kafin lokacin, game da yadda za ku kāre kanku. ");
INSERT INTO hausa_vpl VALUES ("LK21_15","072_21_15","LUK","21","15","15","Gama zan ba ku kalmomi, da hikima waɗanda ba ko ɗaya daga cikin maƙiyanku, za su iya tsayayya da ku, ko su ƙaryata. ");
INSERT INTO hausa_vpl VALUES ("LK21_16","072_21_16","LUK","21","16","16","Har iyayenku, da ’yan’uwanku maza, da danginku, da abokanku ma, duk za su bashe ku, su kuma kashe waɗansunku. ");
INSERT INTO hausa_vpl VALUES ("LK21_17","072_21_17","LUK","21","17","17","Duk mutane za su ƙi ku saboda ni. ");
INSERT INTO hausa_vpl VALUES ("LK21_18","072_21_18","LUK","21","18","18","Amma ko gashi ɗaya na kanku, ba zai hallaka ba. ");
INSERT INTO hausa_vpl VALUES ("LK21_19","072_21_19","LUK","21","19","19","Ta wurin tsayawa da ƙarfi, za ku sami rai. ");
INSERT INTO hausa_vpl VALUES ("LK21_20","072_21_20","LUK","21","20","20","“In kuka ga mayaƙa sun kewaye Urushalima, za ku sani rushewarta ya yi kusa. ");
INSERT INTO hausa_vpl VALUES ("LK21_21","072_21_21","LUK","21","21","21","A lokacin nan, bari waɗanda suke Yahudiya, su gudu zuwa cikin duwatsu. Bari waɗanda suke cikin birnin kuma su fita, bari kuma waɗanda suke ƙauye kada su shiga birnin. ");
INSERT INTO hausa_vpl VALUES ("LK21_22","072_21_22","LUK","21","22","22","Gama wannan shi ne lokacin hukunci, saboda a cika duk abin da aka rubuta. ");
INSERT INTO hausa_vpl VALUES ("LK21_23","072_21_23","LUK","21","23","23","Zai zama abin kaito ga mata masu ciki, da mata masu renon ’ya’ya, a waɗancan kwanakin! Za a yi baƙin ciki mai tsanani a ƙasar, da kuma fushi mai tsanani a kan mutanen nan. ");
INSERT INTO hausa_vpl VALUES ("LK21_24","072_21_24","LUK","21","24","24","Za a kashe su da takobi, a kuma ɗauke su ’yan kurkuku, zuwa dukan al’ummai. Al’ummai za su tattaka Urushalima, har sai lokacin Al’ummai ya cika. ");
INSERT INTO hausa_vpl VALUES ("LK21_25","072_21_25","LUK","21","25","25","“Za a yi alamu a cikin rana, da cikin wata, da cikin taurari. A duniya, al’ummai za su yi baƙin ciki, su kuma rikice don tsoro, saboda ruri da kuma tafasar teku. ");
INSERT INTO hausa_vpl VALUES ("LK21_26","072_21_26","LUK","21","26","26","Mutane za su suma don tsoro, za su kuma yi fargaba, a kan abin da yake zuwa a bisan duniya, gama za a girgiza duniyar taurarin sararin sama. ");
INSERT INTO hausa_vpl VALUES ("LK21_27","072_21_27","LUK","21","27","27","A lokacin ne za su ga Ɗan Mutum yana zuwa cikin girgije, da iko, da ɗaukaka mai girma. ");
INSERT INTO hausa_vpl VALUES ("LK21_28","072_21_28","LUK","21","28","28","Sa’ad da waɗannan abubuwa sun fara faruwa, ku tashi tsaye, ku ɗaga kawunanku, domin fansarku yana matsowa kusa.” ");
INSERT INTO hausa_vpl VALUES ("LK21_29","072_21_29","LUK","21","29","29","Sai ya gaya musu wannan misali ya ce, “Ku dubi itacen ɓaure da dukan itatuwa. ");
INSERT INTO hausa_vpl VALUES ("LK21_30","072_21_30","LUK","21","30","30","A duk lokacin da sun fara fitar da ganye, za ku gani da kanku, ku san cewa, damina ta yi kusa. ");
INSERT INTO hausa_vpl VALUES ("LK21_31","072_21_31","LUK","21","31","31","Haka ma, in kuka ga waɗannan abubuwa suna faruwa, ku sani mulkin Allah ya yi kusa. ");
INSERT INTO hausa_vpl VALUES ("LK21_32","072_21_32","LUK","21","32","32","“Gaskiya nake gaya muku, ba shakka, wannan zamani ba zai shuɗe ba, sai dukan waɗannan abubuwa sun cika. ");
INSERT INTO hausa_vpl VALUES ("LK21_33","072_21_33","LUK","21","33","33","Sama da ƙasa za su shuɗe, amma kalmomina ba za su taɓa shuɗewa ba. ");
INSERT INTO hausa_vpl VALUES ("LK21_34","072_21_34","LUK","21","34","34","“Ku lura fa don kada son jin daɗi na banza, da shaye-shaye, da damuwa na rayuwa su rinjayi zuciyarku, har ranar ta auko muku ba tsammani kamar tarko. ");
INSERT INTO hausa_vpl VALUES ("LK21_35","072_21_35","LUK","21","35","35","Gama za tă zo a kan kowa da yake kan dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("LK21_36","072_21_36","LUK","21","36","36","Ku yi tsaro kullum, ku yi addu’a don ku iya kuɓuta daga dukan waɗannan abubuwa da suke kusan faruwa, don ku iya tsayawa a gaban Ɗan Mutum.” ");
INSERT INTO hausa_vpl VALUES ("LK21_37","072_21_37","LUK","21","37","37","Kowace rana, Yesu yakan je haikalin ya yi koyarwa, da kowace yamma kuma, ya je ya kwana a kan tudun da ake kira Dutsen Zaitun. ");
INSERT INTO hausa_vpl VALUES ("LK21_38","072_21_38","LUK","21","38","38","Da sassafe kuma, dukan mutanen suka zo haikalin, don su saurare shi. ");
INSERT INTO hausa_vpl VALUES ("LK22_1","072_22_1","LUK","22","1","1","Yanzu fa, Bikin Burodi Marar Yistin da ake kira Bikin Ƙetarewa ya yi kusa, ");
INSERT INTO hausa_vpl VALUES ("LK22_2","072_22_2","LUK","22","2","2","manyan firistoci da malaman dokoki kuma suna neman yadda za su kashe Yesu a ɓoye, don suna tsoron mutane. ");
INSERT INTO hausa_vpl VALUES ("LK22_3","072_22_3","LUK","22","3","3","Shaiɗan kuwa ya shiga Yahuda, wanda ake kira Iskariyot, ɗaya daga cikin Sha Biyun. ");
INSERT INTO hausa_vpl VALUES ("LK22_4","072_22_4","LUK","22","4","4","Sai Yahuda ya je ya tattauna da manyan firistoci, da ma’aikatan ’yan gadin haikali, a kan yadda zai ba da Yesu a gare su. ");
INSERT INTO hausa_vpl VALUES ("LK22_5","072_22_5","LUK","22","5","5","Suka kuwa yi murna, suka yarda su ba shi kuɗi. ");
INSERT INTO hausa_vpl VALUES ("LK22_6","072_22_6","LUK","22","6","6","Ya ko yarda, ya fara neman zarafin da zai ba da Yesu a gare su, sa’ad da taro ba sa nan tare da shi. ");
INSERT INTO hausa_vpl VALUES ("LK22_7","072_22_7","LUK","22","7","7","Sai ranar Bikin Burodi Marar Yisti ta kewayo, wato, ranar hadayar ɗan ragon kafara na Bikin Ƙetarewa. ");
INSERT INTO hausa_vpl VALUES ("LK22_8","072_22_8","LUK","22","8","8","Sai Yesu ya aiki Bitrus da Yohanna, ya ce musu, “Ku je ku yi shirye-shiryen Bikin Ƙetarewar da za mu ci.” ");
INSERT INTO hausa_vpl VALUES ("LK22_9","072_22_9","LUK","22","9","9","Suka tambaye shi suka ce, “Ina kake so mu je mu yi shirin?” ");
INSERT INTO hausa_vpl VALUES ("LK22_10","072_22_10","LUK","22","10","10","Ya amsa ya ce, “Sa’ad da kuka shiga cikin gari, za ku sadu da wani mutum yana ɗauke da tulun ruwa. Ku bi shi zuwa gidan da zai shiga. ");
INSERT INTO hausa_vpl VALUES ("LK22_11","072_22_11","LUK","22","11","11","Ku ce wa maigidan, Malam ya aike mu mu ce maka, ‘Ina ɗakin baƙi, inda ni da almajiraina za mu ci abincin Bikin Ƙetarewa?’ ");
INSERT INTO hausa_vpl VALUES ("LK22_12","072_22_12","LUK","22","12","12","Zai nuna muku wani babban ɗakin sama a shirye. Nan za ku yi shirin.” ");
INSERT INTO hausa_vpl VALUES ("LK22_13","072_22_13","LUK","22","13","13","Sai suka tafi, suka kuma iske kome kamar yadda Yesu ya faɗa musu. Sai suka shirya Bikin Ƙetarewa. ");
INSERT INTO hausa_vpl VALUES ("LK22_14","072_22_14","LUK","22","14","14","Da lokaci ya yi, sai Yesu ya zauna tare da manzanninsa don cin abinci. ");
INSERT INTO hausa_vpl VALUES ("LK22_15","072_22_15","LUK","22","15","15","Sai ya ce musu, “Na yi marmari ƙwarai don in ci wannan Bikin Ƙetarewa tare da ku, kafin in sha wahala. ");
INSERT INTO hausa_vpl VALUES ("LK22_16","072_22_16","LUK","22","16","16","Ina dai gaya muku, ba zan ƙara cinsa ba, sai ya sami cika a mulkin Allah.” ");
INSERT INTO hausa_vpl VALUES ("LK22_17","072_22_17","LUK","22","17","17","Bayan ya ɗauki kwaf ruwan inabi, ya yi godiya, sai ya ce, “Ku karɓa, ku rarraba wa junanku. ");
INSERT INTO hausa_vpl VALUES ("LK22_18","072_22_18","LUK","22","18","18","Ina dai gaya muku, ba zan ƙara sha daga ’ya’yan inabi ba, sai mulkin Allah ya zo.” ");
INSERT INTO hausa_vpl VALUES ("LK22_19","072_22_19","LUK","22","19","19","Sai ya ɗauki burodi ya yi godiya, ya kakkarya ya ba su, da cewa, “Wannan jikina ne, da aka bayar dominku. Ku riƙa yin haka don tunawa da ni.” ");
INSERT INTO hausa_vpl VALUES ("LK22_20","072_22_20","LUK","22","20","20","Haka kuma, bayan abincin, ya ɗauki kwaf ruwan inabi ya ce, “Wannan kwaf ruwan inabi shi ne, na sabon alkawari cikin jinina, da aka zubar dominku. ");
INSERT INTO hausa_vpl VALUES ("LK22_21","072_22_21","LUK","22","21","21","Amma hannun wanda zai ci amanata, yana cin abincin tare da ni. ");
INSERT INTO hausa_vpl VALUES ("LK22_22","072_22_22","LUK","22","22","22","Ɗan Mutum zai mutu kamar yadda aka ƙaddara, amma kaiton mutumin da zai bashe shi.” ");
INSERT INTO hausa_vpl VALUES ("LK22_23","072_22_23","LUK","22","23","23","Sai suka fara tambayar junansu, ko wane ne a cikinsu zai yi wannan. ");
INSERT INTO hausa_vpl VALUES ("LK22_24","072_22_24","LUK","22","24","24","Gardama ta tashi a tsakaninsu, a kan ko wane ne a cikinsu ya fi girma. ");
INSERT INTO hausa_vpl VALUES ("LK22_25","072_22_25","LUK","22","25","25","Yesu ya ce musu, “Sarakunan Al’ummai suna nuna iko a kan mutanensu, kuma waɗanda suke nuna iko a kansu, suna kiran kansu Masu Taimakon mutane. ");
INSERT INTO hausa_vpl VALUES ("LK22_26","072_22_26","LUK","22","26","26","Amma ku, kada ku zama haka. A maimakon haka, sai dai wanda ya fi girma a cikinku, ya zama kamar wanda ya fi ƙanƙanta, wanda kuma ke mulki, ya zama kamar mai hidima. ");
INSERT INTO hausa_vpl VALUES ("LK22_27","072_22_27","LUK","22","27","27","Wane ne ya fi girma? Wanda yake zaune a tebur ne, ko kuma shi da yake yin hidima? Ashe, ba wanda yake zaune a tebur ba ne? Amma ga ni, ni mai yin hidima ne a cikinku. ");
INSERT INTO hausa_vpl VALUES ("LK22_28","072_22_28","LUK","22","28","28","Ku ne kuka tsaya tare da ni a gwaje-gwajen da na sha. ");
INSERT INTO hausa_vpl VALUES ("LK22_29","072_22_29","LUK","22","29","29","Daidai kamar yadda Ubana ya ba ni mulki, haka ni ma nake ba ku. ");
INSERT INTO hausa_vpl VALUES ("LK22_30","072_22_30","LUK","22","30","30","Saboda ku ci, ku sha a teburina a cikin mulkina. Kuma ku zauna a kan gadon sarauta, ku yi wa kabilu goma sha biyu na Isra’ila shari’a. ");
INSERT INTO hausa_vpl VALUES ("LK22_31","072_22_31","LUK","22","31","31","“Siman, Siman, Shaiɗan ya nemi izini ya sheƙe kakamar alkama. ");
INSERT INTO hausa_vpl VALUES ("LK22_32","072_22_32","LUK","22","32","32","Amma na yi maka addu’a, Siman, domin kada bangaskiyarka ta kāsa. Bayan ka juyo, ka ƙarfafa ’yan’uwanka.” ");
INSERT INTO hausa_vpl VALUES ("LK22_33","072_22_33","LUK","22","33","33","Amma ya amsa ya ce, “Ubangiji, ina a shirye in tafi tare da kai har kurkuku, ko mutuwa ma.” ");
INSERT INTO hausa_vpl VALUES ("LK22_34","072_22_34","LUK","22","34","34","Yesu ya ce, “Ina gaya maka Bitrus, kafin zakara ya yi cara yau, za ka yi mūsun sanina sau uku.” ");
INSERT INTO hausa_vpl VALUES ("LK22_35","072_22_35","LUK","22","35","35","Sai Yesu ya tambaye, su ya ce, “Lokacin da na aike ku ba tare da jakar kuɗi, ko jaka, ko takalma ba, kun rasa wani abu?” Suka amsa, “Babu.” ");
INSERT INTO hausa_vpl VALUES ("LK22_36","072_22_36","LUK","22","36","36","Ya ce musu, “Amma yanzu, in kuna da jakar kuɗi, ko jaka, ku ɗauka. In kuma ba ku da takobi, ku sayar da rigarku, ku saya. ");
INSERT INTO hausa_vpl VALUES ("LK22_37","072_22_37","LUK","22","37","37","A rubuce yake cewa, ‘An lissafta shi tare da masu zunubi.’ Ina kuwa gaya muku, dole wannan ya cika a kaina. I, abin da aka rubuta a kaina yana kusan cikawa.” ");
INSERT INTO hausa_vpl VALUES ("LK22_38","072_22_38","LUK","22","38","38","Almajiran suka ce, “Duba Ubangiji, ga takuba biyu.” Yesu ya ce, “Ya isa.” ");
INSERT INTO hausa_vpl VALUES ("LK22_39","072_22_39","LUK","22","39","39","Yesu ya fita zuwa Dutsen Zaitun kamar yadda ya saba, almajiransa kuma suka bi shi. ");
INSERT INTO hausa_vpl VALUES ("LK22_40","072_22_40","LUK","22","40","40","Da ya kai wurin, sai ya ce musu, “Ku yi addu’a don kada ku fāɗi cikin jarraba.” ");
INSERT INTO hausa_vpl VALUES ("LK22_41","072_22_41","LUK","22","41","41","Sai ya janye daga wurinsu, misalin nisan jifa, ya durƙusa a ƙasa ya yi addu’a, ");
INSERT INTO hausa_vpl VALUES ("LK22_42","072_22_42","LUK","22","42","42","“Uba, in ka yarda, ka ɗauke mini wannan kwaf, amma ba nufina ba, sai dai naka.” ");
INSERT INTO hausa_vpl VALUES ("LK22_43","072_22_43","LUK","22","43","43","Wani mala’ika daga sama ya bayyana gare shi, ya ƙarfafa shi. ");
INSERT INTO hausa_vpl VALUES ("LK22_44","072_22_44","LUK","22","44","44","Domin tsananin azaba, sai ya ƙara himma cikin addu’a, zuffansa kuma na ɗigowa ƙasa kamar jini. ");
INSERT INTO hausa_vpl VALUES ("LK22_45","072_22_45","LUK","22","45","45","Da ya tashi daga addu’a, ya koma inda almajiransa suke, sai ya iske su suna barci, daga gajiyar baƙin ciki. ");
INSERT INTO hausa_vpl VALUES ("LK22_46","072_22_46","LUK","22","46","46","Ya tambaye su, “Don me kuke barci? Ku tashi ku yi addu’a, don kada ku fāɗi cikin jarraba.” ");
INSERT INTO hausa_vpl VALUES ("LK22_47","072_22_47","LUK","22","47","47","Yana cikin magana sai ga taro sun zo. Mutumin nan da ake kira Yahuda, ɗaya daga cikin Sha Biyun, shi ya bi da su. Sai ya matso kusa da Yesu don yă yi masa sumba. ");
INSERT INTO hausa_vpl VALUES ("LK22_48","072_22_48","LUK","22","48","48","Amma Yesu ya tambaye shi ya ce, “Yahuda, ashe, da sumba za ka bashe Ɗan Mutum?” ");
INSERT INTO hausa_vpl VALUES ("LK22_49","072_22_49","LUK","22","49","49","Da masu bin Yesu suka ga abin da zai faru, sai suka ce, “Ubangiji, mu yi sara da takubanmu ne?” ");
INSERT INTO hausa_vpl VALUES ("LK22_50","072_22_50","LUK","22","50","50","Sai ɗayansu ya kai sara ga bawan babban firist, ya sare kunnen damansa. ");
INSERT INTO hausa_vpl VALUES ("LK22_51","072_22_51","LUK","22","51","51","Amma Yesu ya amsa ya ce, “Kada a ƙara yin wannan!” Sai ya taɓa kunnen mutumin da aka sara, ya warkar da shi. ");
INSERT INTO hausa_vpl VALUES ("LK22_52","072_22_52","LUK","22","52","52","Sai Yesu ya ce wa manyan firistoci, da ma’aikatan ’yan gadin haikali, da dattawa, waɗanda suka zo don su kama shi, “Ina jagoran wani tawaye ne, da za ku zo da takuba da sanduna? ");
INSERT INTO hausa_vpl VALUES ("LK22_53","072_22_53","LUK","22","53","53","Kullum ina tare da ku a filin haikali, amma ba ku kama ni ba. Amma wannan ne sa’a naku, lokacin da duhu yake mulki.” ");
INSERT INTO hausa_vpl VALUES ("LK22_54","072_22_54","LUK","22","54","54","Sai suka kama shi suka kai shi gidan babban firist. Bitrus ya bi su daga nesa. ");
INSERT INTO hausa_vpl VALUES ("LK22_55","072_22_55","LUK","22","55","55","Amma da suka hura wuta a tsakiyar harabar gidan, kowa ya zauna, sai Bitrus ya zo ya zauna tare da su. ");
INSERT INTO hausa_vpl VALUES ("LK22_56","072_22_56","LUK","22","56","56","Wata baiwa ta gan shi zaune kusa da wutar. Ta dube shi sosai sa’an nan, ta ce, “Ai, wannan mutum ma yana tare da shi.” ");
INSERT INTO hausa_vpl VALUES ("LK22_57","072_22_57","LUK","22","57","57","Amma ya yi mūsu ya ce, “Mace, ban san shi ba!” ");
INSERT INTO hausa_vpl VALUES ("LK22_58","072_22_58","LUK","22","58","58","Bayan ɗan lokaci kaɗan, wani dabam ya gan shi ya ce, “Kai ma ɗayansu ne.” Bitrus ya amsa ya ce, “Kai, ba na cikinsu!” ");
INSERT INTO hausa_vpl VALUES ("LK22_59","072_22_59","LUK","22","59","59","Bayan kamar sa’a ɗaya, sai wani mutum ya ce, “Ba shakka, mutumin nan ma yana tare da shi, don shi mutumin Galili ne.” ");
INSERT INTO hausa_vpl VALUES ("LK22_60","072_22_60","LUK","22","60","60","Bitrus ya amsa ya ce, “Kai, ban ma san abin da kake magana a kai ba!” Yana cikin magana, sai zakara ya yi cara. ");
INSERT INTO hausa_vpl VALUES ("LK22_61","072_22_61","LUK","22","61","61","Ubangiji kuma ya juya ya kafa wa Bitrus ido. Sai Bitrus ya tuna da maganar da Ubangiji ya ce masa, “Kafin zakara ya yi cara yau, za ka yi mūsun sanina sau uku.” ");
INSERT INTO hausa_vpl VALUES ("LK22_62","072_22_62","LUK","22","62","62","Sai ya fita waje, ya yi kuka mai zafi. ");
INSERT INTO hausa_vpl VALUES ("LK22_63","072_22_63","LUK","22","63","63","Mutanen da suke gadin Yesu suka fara masa ba’a da dūka. ");
INSERT INTO hausa_vpl VALUES ("LK22_64","072_22_64","LUK","22","64","64","Suka rufe masa idanu suna tambaya cewa, “Ka yi annabci! Wa ya mare ka?” ");
INSERT INTO hausa_vpl VALUES ("LK22_65","072_22_65","LUK","22","65","65","Suka kuma yi masa waɗansu baƙaƙen maganganu masu yawa. ");
INSERT INTO hausa_vpl VALUES ("LK22_66","072_22_66","LUK","22","66","66","Da gari ya waye, sai majalisar dattawa na mutane, da manyan firistoci, da malaman dokoki, suka taru wuri ɗaya. Sai aka kawo Yesu a gabansu. ");
INSERT INTO hausa_vpl VALUES ("LK22_67","072_22_67","LUK","22","67","67","Suka ce, “Ka faɗa mana, ko kai ne Kiristi?” Yesu ya amsa ya ce, “Ko na gaya muku, ba za ku gaskata ni ba, ");
INSERT INTO hausa_vpl VALUES ("LK22_68","072_22_68","LUK","22","68","68","in kuma na yi muku tambaya ba za ku iya ba ni amsa ba. ");
INSERT INTO hausa_vpl VALUES ("LK22_69","072_22_69","LUK","22","69","69","Amma daga yanzu, Ɗan Mutum zai zauna a hannun dama na Allah Mai Iko.” ");
INSERT INTO hausa_vpl VALUES ("LK22_70","072_22_70","LUK","22","70","70","Sai dukansu suka yi tambaya suka ce, “Wato, kai Ɗan Allah ke nan?” Ya amsa ya ce, “Kun faɗa daidai, ni ne.” ");
INSERT INTO hausa_vpl VALUES ("LK22_71","072_22_71","LUK","22","71","71","Sai suka ce, “Wace shaida kuma muke nema? Ai, mun ji abin da ya ce da bakinsa.” ");
INSERT INTO hausa_vpl VALUES ("LK23_1","072_23_1","LUK","23","1","1","Sai dukan majalisa suka tashi, suka kai shi gaban Bilatus. ");
INSERT INTO hausa_vpl VALUES ("LK23_2","072_23_2","LUK","23","2","2","Suka fara zarginsa suna cewa, “Mun sami wannan mutum yana rikitar da al’ummarmu. Yana hana a biya haraji ga Kaisar. Yana kuma cewa, shi Kiristi ne, sarki kuma.” ");
INSERT INTO hausa_vpl VALUES ("LK23_3","072_23_3","LUK","23","3","3","Sai Bilatus ya tambayi Yesu ya ce, “Kai ne sarkin Yahudawa?” Yesu ya amsa ya ce, “I, haka yake, kamar yadda ka faɗa.” ");
INSERT INTO hausa_vpl VALUES ("LK23_4","072_23_4","LUK","23","4","4","Sai Bilatus ya sanar wa manyan firistoci da taron ya ce, “Ni fa, ban sami wani ainihin abin zargi game wannan mutum nan ba.” ");
INSERT INTO hausa_vpl VALUES ("LK23_5","072_23_5","LUK","23","5","5","Amma suka nace, suna cewa, “Yana tā da hankulan mutane, ko’ina a Yahudiya da koyarwarsa. Ya fara daga Galili, ga shi har ya kai nan.” ");
INSERT INTO hausa_vpl VALUES ("LK23_6","072_23_6","LUK","23","6","6","Da Bilatus ya ji haka, sai ya yi tambaya, “Ko shi mutumin Galili ne?” ");
INSERT INTO hausa_vpl VALUES ("LK23_7","072_23_7","LUK","23","7","7","Da ya ji cewa, Yesu yana ƙarƙashin mulkin Hiridus ne, sai ya aika da shi zuwa wurin Hiridus, don a lokacin Hiridus yana Urushalima. ");
INSERT INTO hausa_vpl VALUES ("LK23_8","072_23_8","LUK","23","8","8","Da Hiridus ya ga Yesu, sai ya yi murna ƙwarai, don tun dā ma yana marmari ya gan shi a kan abin da ya ji game da shi. Ya yi fata ya ga Yesu, yă kuma yi waɗansu ayyukan banmamaki. ");
INSERT INTO hausa_vpl VALUES ("LK23_9","072_23_9","LUK","23","9","9","Ya yi masa tambayoyi masu yawa, amma Yesu bai ba shi ko amsa ba. ");
INSERT INTO hausa_vpl VALUES ("LK23_10","072_23_10","LUK","23","10","10","Manyan firistoci da malaman dokoki suna tsaye a wurin, suna kawo zargi masu ƙarfi a kansa. ");
INSERT INTO hausa_vpl VALUES ("LK23_11","072_23_11","LUK","23","11","11","Sai Hiridus da sojojinsa suka wulaƙanta shi, suka yi masa ba’a. Sa’an nan, suka sa masa babban riga, suka mai da shi wurin Bilatus. ");
INSERT INTO hausa_vpl VALUES ("LK23_12","072_23_12","LUK","23","12","12","A ranar, Hiridus da Bilatus suka zama abokan juna, don tun dā ma, su abokan gāba ne. ");
INSERT INTO hausa_vpl VALUES ("LK23_13","072_23_13","LUK","23","13","13","Bilatus ya tara manyan firistoci, da masu mulki, da mutane, ");
INSERT INTO hausa_vpl VALUES ("LK23_14","072_23_14","LUK","23","14","14","ya ce musu, “Kun kawo mini wannan mutum, a matsayin wanda yana zuga mutane su yi tawaye. Na bincike shi a gabanku, ban ga a kan me kuka kawo kararsa ba. ");
INSERT INTO hausa_vpl VALUES ("LK23_15","072_23_15","LUK","23","15","15","Haka ma Hiridus, shi ya sa ya dawo da shi nan wurinmu. Kamar yadda ku ma kun gani, ba abin da mutumin nan ya yi, da ya isa mutuwa. ");
INSERT INTO hausa_vpl VALUES ("LK23_16","072_23_16","LUK","23","16","16","Saboda haka, zan yi masa bulala, in sāke shi.” ");
INSERT INTO hausa_vpl VALUES ("LK23_18","072_23_18","LUK","23","18","18","Suka yi ihu gaba ɗaya suka ce, “A yi gaba da wannan mutum! A sake mana Barabbas!” ");
INSERT INTO hausa_vpl VALUES ("LK23_19","072_23_19","LUK","23","19","19","(Barabbas yana kurkuku saboda laifin tā da hankali a birnin, da kuma don kisankai.) ");
INSERT INTO hausa_vpl VALUES ("LK23_20","072_23_20","LUK","23","20","20","Sai Bilatus ya sāke yin musu magana don yana so ya saki Yesu. ");
INSERT INTO hausa_vpl VALUES ("LK23_21","072_23_21","LUK","23","21","21","Amma sai suka ci gaba da ihu, suna cewa, “A gicciye shi! A gicciye shi!” ");
INSERT INTO hausa_vpl VALUES ("LK23_22","072_23_22","LUK","23","22","22","Ya sāke ce musu, sau na uku, “Don me? Wane laifi wannan mutum ya yi? Ni dai ban same shi da wani dalilin da ya isa a kashe shi ba. Saboda haka, zan sa a hore shi, sa’an nan in sāke shi.” ");
INSERT INTO hausa_vpl VALUES ("LK23_23","072_23_23","LUK","23","23","23","Amma suna ihu, suna nacewa, suna cewa, dole a gicciye shi, har ihunsu ya rinjaye shi. ");
INSERT INTO hausa_vpl VALUES ("LK23_24","072_23_24","LUK","23","24","24","Sai Bilatus ya biya bukatarsu da ya ji roƙonsu. ");
INSERT INTO hausa_vpl VALUES ("LK23_25","072_23_25","LUK","23","25","25","Ya saki mutumin da aka jefa a kurkuku saboda tā da hankali, da kisankai, shi wanda suka roƙa. Sa’an nan ya ba da Yesu ga nufinsu. ");
INSERT INTO hausa_vpl VALUES ("LK23_26","072_23_26","LUK","23","26","26","Sa’ad da suna tafiya da Yesu, sai wani da ake kira Siman, mutumin Sairin, yana zuwa daga ƙauye. Suka kama shi, suka aza masa gicciyen, suka tilasta shi ya ɗauki gicciyen, ya bi Yesu a baya. ");
INSERT INTO hausa_vpl VALUES ("LK23_27","072_23_27","LUK","23","27","27","Mutane da yawa sosai suka bi shi, a cikinsu ma da mata waɗanda suka yi makoki da kuka dominsa. ");
INSERT INTO hausa_vpl VALUES ("LK23_28","072_23_28","LUK","23","28","28","Yesu ya juya, ya ce musu, “’Yan matan Urushalima, kada ku yi kuka saboda ni, amma ku yi kuka saboda kanku, da kuma saboda ’ya’yanku. ");
INSERT INTO hausa_vpl VALUES ("LK23_29","072_23_29","LUK","23","29","29","Gama lokaci yana zuwa da za ku ce, ‘Masu albarka ne bakararru, wato, mata marasa haihuwa, da mahaihuwar da ba su taɓa haihuwa ba, da kuma mama da ba su taɓa shayar da nono ba!’ ");
INSERT INTO hausa_vpl VALUES ("LK23_30","072_23_30","LUK","23","30","30","Sa’an nan “ ‘za su ce wa duwatsu, “Ku fāɗi a kanmu!” Za su ce wa tuddai kuma, “Ku rufe mu!” ’ ");
INSERT INTO hausa_vpl VALUES ("LK23_31","072_23_31","LUK","23","31","31","Gama in mutane suna yin waɗannan abubuwa a lokacin da itace na ɗanye, me zai faru in ya bushe?” ");
INSERT INTO hausa_vpl VALUES ("LK23_32","072_23_32","LUK","23","32","32","Tare da shi akwai mutum biyu masu laifi, da aka tafi da su don a gicciye. ");
INSERT INTO hausa_vpl VALUES ("LK23_33","072_23_33","LUK","23","33","33","Da suka isa wurin da ake kira “Ƙoƙon Kai,” nan suka gicciye shi, tare da masu laifin nan, ɗaya a hannun damansa, ɗayan kuma a hagunsa. ");
INSERT INTO hausa_vpl VALUES ("LK23_34","072_23_34","LUK","23","34","34","Yesu ya ce, “Ya Uba ka yi musu gafara, don ba su san abin da suke yi ba.” Suka rarraba tufafinsa ta wurin jefa ƙuri’a. ");
INSERT INTO hausa_vpl VALUES ("LK23_35","072_23_35","LUK","23","35","35","Mutanen suka tsaya suna kallo. Har masu mulki ma suka yi masa ba’a, suna cewa, “Ya ceci waɗansu, to, ya ceci kansa in shi ne Kiristi na Allah, Zaɓaɓɓe.” ");
INSERT INTO hausa_vpl VALUES ("LK23_36","072_23_36","LUK","23","36","36","Sojoji su ma, suka zo suka yi masa ba’a. Suka miƙa masa ruwan tsami. ");
INSERT INTO hausa_vpl VALUES ("LK23_37","072_23_37","LUK","23","37","37","Suka ce, “In kai ne sarkin Yahudawa, ka ceci kanka mana.” ");
INSERT INTO hausa_vpl VALUES ("LK23_38","072_23_38","LUK","23","38","38","Bisa da shi kuma akwai rubutun da ya ce, Wannan shi ne Sarkin Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("LK23_39","072_23_39","LUK","23","39","39","Ɗaya daga cikin masu laifin da aka gicciye a wurin ya zazzage shi ya ce, “Shin, ba kai ne Kiristi ba? To, ka ceci kanka, ka kuma cece mu mana!” ");
INSERT INTO hausa_vpl VALUES ("LK23_40","072_23_40","LUK","23","40","40","Amma ɗayan mai laifi ya kwaɓe shi ya ce, “Ba ka da tsoron Allah ne, wai saboda kana ƙarƙashin hukunci ɗaya tare da shi? ");
INSERT INTO hausa_vpl VALUES ("LK23_41","072_23_41","LUK","23","41","41","Horonmu, daidai aka yi mana, sakamakon abin da muka yi ne. Amma wannan mutum, bai yi wani laifi ba.” ");
INSERT INTO hausa_vpl VALUES ("LK23_42","072_23_42","LUK","23","42","42","Sai ya ce, “Yesu, ka tuna da ni sa’ad da ka shiga mulkinka.” ");
INSERT INTO hausa_vpl VALUES ("LK23_43","072_23_43","LUK","23","43","43","Yesu ya amsa, ya ce masa, “Gaskiya nake faɗa maka, yau ɗin nan, za ka kasance tare da ni, a mulkina a sama.” ");
INSERT INTO hausa_vpl VALUES ("LK23_44","072_23_44","LUK","23","44","44","Yanzu kuwa wajen sa’a ta shida ne, kuma duhu ya rufe ko’ina a ƙasar, har zuwa sa’a ta tara, ");
INSERT INTO hausa_vpl VALUES ("LK23_45","072_23_45","LUK","23","45","45","domin rana ta daina haskakawa. Labulen da yake cikin haikali kuma ya yage kashi biyu. ");
INSERT INTO hausa_vpl VALUES ("LK23_46","072_23_46","LUK","23","46","46","Yesu ya yi kira da babbar murya ya ce, “Ya Uba, na danƙa ruhuna a hannunka.” Da ya faɗi haka, sai ya ja numfashi na ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("LK23_47","072_23_47","LUK","23","47","47","Da jarumin ya ga abin da ya faru, sai ya yabi Allah ya ce, “Gaskiya, wannan mutum mai adalci ne.” ");
INSERT INTO hausa_vpl VALUES ("LK23_48","072_23_48","LUK","23","48","48","Da dukan mutanen da suka taru, domin shaidar waɗannan abubuwa, suka ga abin da ya faru, sai suka buga ƙirjinsu suka tafi. ");
INSERT INTO hausa_vpl VALUES ("LK23_49","072_23_49","LUK","23","49","49","Amma dukan mutanen da suka san Yesu, tare da mata da suka bi shi daga Galili, suka tsaya daga nesa suna kallon abubuwan nan. ");
INSERT INTO hausa_vpl VALUES ("LK23_50","072_23_50","LUK","23","50","50","Akwai wani mutum mai suna Yusuf, ɗan Majalisa, wanda shi nagari ne, mai adalci, ");
INSERT INTO hausa_vpl VALUES ("LK23_51","072_23_51","LUK","23","51","51","shi dā ma bai yarda da shawararsu, da kuma abin da suka yi ba. Shi daga Arimateya ne wani garin Yahudiya. Yana kuma jiran zuwa mulkin Allah. ");
INSERT INTO hausa_vpl VALUES ("LK23_52","072_23_52","LUK","23","52","52","Sai ya je wurin Bilatus ya roƙa a ba shi jikin Yesu. ");
INSERT INTO hausa_vpl VALUES ("LK23_53","072_23_53","LUK","23","53","53","Sai ya saukar da jikin, ya nannaɗe shi a cikin zanen lilin, ya sa shi a wani kabari da aka fafe a cikin dutse, wadda ba a taɓa sa kowa ba. ");
INSERT INTO hausa_vpl VALUES ("LK23_54","072_23_54","LUK","23","54","54","An yi haka ne a Ranar Shirye-shirye, ranar Asabbaci kuma yana dab da farawa. ");
INSERT INTO hausa_vpl VALUES ("LK23_55","072_23_55","LUK","23","55","55","Matan da suka zo tare da Yesu, daga Galili suka bi Yusuf suka ga kabarin, da kuma yadda aka ajiye jikin. ");
INSERT INTO hausa_vpl VALUES ("LK23_56","072_23_56","LUK","23","56","56","Sa’an nan, suka koma gida, suka shirya kayan ƙanshi da turare. Amma suka huta a ranar Asabbaci don kiyaye doka. ");
INSERT INTO hausa_vpl VALUES ("LK24_1","072_24_1","LUK","24","1","1","Da sassafe a ranar farko ta mako, matan suka je kabarin, da kayan ƙanshin da suka shirya. ");
INSERT INTO hausa_vpl VALUES ("LK24_2","072_24_2","LUK","24","2","2","Suka iske an riga an gungurar da dutsen daga bakin kabarin. ");
INSERT INTO hausa_vpl VALUES ("LK24_3","072_24_3","LUK","24","3","3","Amma da suka shiga ciki, ba su iske jikin Ubangiji Yesu ba. ");
INSERT INTO hausa_vpl VALUES ("LK24_4","072_24_4","LUK","24","4","4","Yayinda suna cikin tunani a kan wannan, nan take, ga waɗansu mutum biyu tsaye kusa da su, sanye da kaya masu ƙyalli, kamar walƙiya. ");
INSERT INTO hausa_vpl VALUES ("LK24_5","072_24_5","LUK","24","5","5","A cikin tsoro, matan suka fāɗi da fuskokinsu a ƙasa, amma mutanen suka ce musu, “Me ya sa kuke neman mai rai a cikin matattu? ");
INSERT INTO hausa_vpl VALUES ("LK24_6","072_24_6","LUK","24","6","6","Ba ya nan, ya tashi! Ku tuna yadda ya gaya muku tun yana tare da ku a Galili cewa, ");
INSERT INTO hausa_vpl VALUES ("LK24_7","072_24_7","LUK","24","7","7","‘Dole a ba da Ɗan Mutum ga hannun masu zunubi, a kuma gicciye shi, a rana ta uku kuma a tashe shi.’ ” ");
INSERT INTO hausa_vpl VALUES ("LK24_8","072_24_8","LUK","24","8","8","Sai suka tuna da maganarsa. ");
INSERT INTO hausa_vpl VALUES ("LK24_9","072_24_9","LUK","24","9","9","Da suka dawo daga kabarin, sai suka faɗa wa Sha Ɗayan nan da sauransu, dukan waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("LK24_10","072_24_10","LUK","24","10","10","Matan da suka gaya wa manzannin waɗannan abubuwa su ne, Maryamu Magdalin, da Yowanna, da Maryamu uwar Yaƙub, da waɗansu da suke tare da su. ");
INSERT INTO hausa_vpl VALUES ("LK24_11","072_24_11","LUK","24","11","11","Amma ba su gaskata matan ba, domin sun ɗauki kalmominsu wani zancen banza ne. ");
INSERT INTO hausa_vpl VALUES ("LK24_12","072_24_12","LUK","24","12","12","Duk da haka, Bitrus ya tashi a guje zuwa kabarin. Da ya sunkuya, sai ya ga ƙyallayen lilin kaɗai a kwance. Sai ya koma yana tunani a ransa, a kan abin da ya faru. ");
INSERT INTO hausa_vpl VALUES ("LK24_13","072_24_13","LUK","24","13","13","A wannan rana kuma, biyu daga cikinsu suna tafiya zuwa wani ƙauye, da ake kira Emmawus, da suke kusan mil bakwai daga Urushalima. ");
INSERT INTO hausa_vpl VALUES ("LK24_14","072_24_14","LUK","24","14","14","Suna magana da juna a kan dukan abubuwan da suka faru. ");
INSERT INTO hausa_vpl VALUES ("LK24_15","072_24_15","LUK","24","15","15","Da suna magana, kuma suna tattauna waɗannan abubuwa da junansu, sai Yesu da kansa ya zo yana tafiya tare da su. ");
INSERT INTO hausa_vpl VALUES ("LK24_16","072_24_16","LUK","24","16","16","Amma ba a ba su ikon gane shi ba. ");
INSERT INTO hausa_vpl VALUES ("LK24_17","072_24_17","LUK","24","17","17","Sai ya tambaye, su ya ce, “Mene ne kuke tattaunawa da juna a cikin tafiyarku?” Suka tsaya shiru, da damuwa a fuskarsu. ");
INSERT INTO hausa_vpl VALUES ("LK24_18","072_24_18","LUK","24","18","18","Ɗaya daga cikinsu, mai suna Kiliyobas, ya tambaye shi ya ce, “Ashe, kai baƙo ne a Urushalima, da ba ka san abubuwan da suka faru a can, a cikin kwanakin nan ba?” ");
INSERT INTO hausa_vpl VALUES ("LK24_19","072_24_19","LUK","24","19","19","Sai ya yi tambaya, “Waɗanne abubuwa?” Suka amsa suka ce, “Game da Yesu Banazare. Shi annabi ne, mai iko ne kuma cikin ayyukansa da maganarsa, a gaban Allah da kuma dukan mutane. ");
INSERT INTO hausa_vpl VALUES ("LK24_20","072_24_20","LUK","24","20","20","Manyan firistoci da masu mulkinmu sun ba da shi a yi masa hukuncin mutuwa, suka kuwa gicciye shi. ");
INSERT INTO hausa_vpl VALUES ("LK24_21","072_24_21","LUK","24","21","21","Amma da, muna sa zuciya cewa, shi ne wanda zai fanshi Isra’ila. Bugu da ƙari kuma yau kwana uku ke nan tun da wannan abin ya faru. ");
INSERT INTO hausa_vpl VALUES ("LK24_22","072_24_22","LUK","24","22","22","Har wa yau, waɗansu daga cikin matanmu sun ba mu mamaki. Sun je kabarin da sassafen nan, ");
INSERT INTO hausa_vpl VALUES ("LK24_23","072_24_23","LUK","24","23","23","amma ba su sami jikinsa ba. Sun dawo sun faɗa mana cewa, sun ga wahayi na mala’iku, da suka ce yana da rai. ");
INSERT INTO hausa_vpl VALUES ("LK24_24","072_24_24","LUK","24","24","24","Sa’an nan, waɗansu abokanmu suka je kabarin, suka kuma tarar da kome kamar yadda matan suka faɗa, amma shi, ba su gan shi ba.” ");
INSERT INTO hausa_vpl VALUES ("LK24_25","072_24_25","LUK","24","25","25","Sai ya ce musu, “Ashe, ku marasa azanci ne, masu nauyin zuciyar gaskata, da dukan abin da annabawa suka faɗa! ");
INSERT INTO hausa_vpl VALUES ("LK24_26","072_24_26","LUK","24","26","26","Ai, dole Kiristi yă sha waɗannan wahalolin, kafin yă shiga ɗaukakarsa. ");
INSERT INTO hausa_vpl VALUES ("LK24_27","072_24_27","LUK","24","27","27","Sai ya fara bayyana musu daga Musa da dukan Annabawa, abin da dukan Nassi ya faɗa a kansa.” ");
INSERT INTO hausa_vpl VALUES ("LK24_28","072_24_28","LUK","24","28","28","Da suka yi kusa da ƙauyen da za su, sai Yesu ya yi kamar zai ci gaba. ");
INSERT INTO hausa_vpl VALUES ("LK24_29","072_24_29","LUK","24","29","29","Amma suka matsa masa suka ce, “Sauka wurinmu, don dare ya kusa, rana ta kusa fāɗuwa.” Sai ya sauka wurinsu. ");
INSERT INTO hausa_vpl VALUES ("LK24_30","072_24_30","LUK","24","30","30","Da ya zauna a tebur tare da su, sai ya ɗauki burodi, ya yi godiya, ya kakkarya ya fara ba su. ");
INSERT INTO hausa_vpl VALUES ("LK24_31","072_24_31","LUK","24","31","31","Sa’an nan idanunsu suka buɗe, suka gane shi. Sai ya ɓace musu. ");
INSERT INTO hausa_vpl VALUES ("LK24_32","072_24_32","LUK","24","32","32","Suka tambayi juna, “Ashe, shi ya sa zukatanmu suka kuna a cikinmu, sa’ad da yake magana da mu a hanya, yana bayyana mana Nassi.” ");
INSERT INTO hausa_vpl VALUES ("LK24_33","072_24_33","LUK","24","33","33","Suka tashi nan da nan suka koma Urushalima. A can suka sami Sha Ɗayan nan da waɗanda suke tare da su a wuri ɗaya, ");
INSERT INTO hausa_vpl VALUES ("LK24_34","072_24_34","LUK","24","34","34","suna cewa, “Gaskiya ne! Ubangiji ya tashi, ya kuma bayyana ga Siman” ");
INSERT INTO hausa_vpl VALUES ("LK24_35","072_24_35","LUK","24","35","35","Sai su biyun nan suka ba da labarin abin da ya faru a hanya, da kuma yadda suka gane Yesu yayinda ya kakkarya burodin. ");
INSERT INTO hausa_vpl VALUES ("LK24_36","072_24_36","LUK","24","36","36","Suna cikin wannan zance, sai ga Yesu da kansa tsaye a tsakiyarsu. Sai ya ce musu, “Salama a gare ku!” ");
INSERT INTO hausa_vpl VALUES ("LK24_37","072_24_37","LUK","24","37","37","Suka firgita, suka tsorota, suna tsammani fatalwa ce suka gani. ");
INSERT INTO hausa_vpl VALUES ("LK24_38","072_24_38","LUK","24","38","38","Sai ya ce musu, “Don me kuke damuwa, kuke kuma shakka a zuciyarku? ");
INSERT INTO hausa_vpl VALUES ("LK24_39","072_24_39","LUK","24","39","39","Ku duba hannuwana da ƙafafuna. Ai, ni ne da kaina! Ku taɓa ni ku ji, ai, fatalwa ba ta da nama da ƙashi, yadda kuke gani nake da su.” ");
INSERT INTO hausa_vpl VALUES ("LK24_40","072_24_40","LUK","24","40","40","Da ya faɗi haka, sai ya nuna musu hannuwansa da ƙafafunsa. ");
INSERT INTO hausa_vpl VALUES ("LK24_41","072_24_41","LUK","24","41","41","Kuma har yanzu, suna cikin rashin gaskatawa, saboda murna da mamaki, sai ya tambaye su, “Kuna da abinci a nan?” ");
INSERT INTO hausa_vpl VALUES ("LK24_42","072_24_42","LUK","24","42","42","Suka ba shi ɗan gasasshen kifi, ");
INSERT INTO hausa_vpl VALUES ("LK24_43","072_24_43","LUK","24","43","43","ya karɓa ya ci a gabansu. ");
INSERT INTO hausa_vpl VALUES ("LK24_44","072_24_44","LUK","24","44","44","Ya ce musu, “Wannan shi ne abin da na gaya muku tun ina tare da ku cewa, dole a cika kome da aka rubuta game da ni, a cikin Dokar Musa, da Annabawa, da kuma Zabura.” ");
INSERT INTO hausa_vpl VALUES ("LK24_45","072_24_45","LUK","24","45","45","Sai ya wayar da tunaninsu don su fahimci Nassi. ");
INSERT INTO hausa_vpl VALUES ("LK24_46","072_24_46","LUK","24","46","46","Ya ce musu, “Wannan shi ne abin da aka rubuta, cewa dole Kiristi yă sha wahala, a rana ta uku kuma yă tashi daga matattu. ");
INSERT INTO hausa_vpl VALUES ("LK24_47","072_24_47","LUK","24","47","47","Kuma a cikin sunansa za a yi wa’azin tuba da gafarar zunubai, ga dukan ƙasashe. Za a kuwa fara daga Urushalima. ");
INSERT INTO hausa_vpl VALUES ("LK24_48","072_24_48","LUK","24","48","48","Ku ne shaidun waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("LK24_49","072_24_49","LUK","24","49","49","Zan aika muku da abin da Ubana ya yi alkawari. Amma ku dakata a birnin tukuna, sai an rufe ku da iko daga sama.” ");
INSERT INTO hausa_vpl VALUES ("LK24_50","072_24_50","LUK","24","50","50","Bayan ya kai su waje kusa da Betani, sai ya ɗaga hannuwansa ya sa musu albarka. ");
INSERT INTO hausa_vpl VALUES ("LK24_51","072_24_51","LUK","24","51","51","Yana cikin sa musu albarka, sai ya rabu da su. Aka ɗauke shi zuwa cikin sama. ");
INSERT INTO hausa_vpl VALUES ("LK24_52","072_24_52","LUK","24","52","52","Sai suka yi masa sujada, suka koma Urushalima cike da murna sosai. ");
INSERT INTO hausa_vpl VALUES ("LK24_53","072_24_53","LUK","24","53","53","Sai suka ci gaba da zama a cikin haikalin, suna yabon Allah.");
INSERT INTO hausa_vpl VALUES ("JN1_1","073_1_1","JHN","1","1","1","Tun farar farawa akwai Kalma, Kalman kuwa yana nan tare da Allah, Kalman kuwa Allah ne. ");
INSERT INTO hausa_vpl VALUES ("JN1_2","073_1_2","JHN","1","2","2","Yana nan tare da Allah tun farar farawa. ");
INSERT INTO hausa_vpl VALUES ("JN1_3","073_1_3","JHN","1","3","3","Ta wurin Kalman ne aka halicci dukan abubuwa. In ba tare da shi ba, babu abin da aka yi wanda aka yi. ");
INSERT INTO hausa_vpl VALUES ("JN1_4","073_1_4","JHN","1","4","4","A cikinsa rai ya kasance, wannan rai kuwa shi ne hasken mutane. ");
INSERT INTO hausa_vpl VALUES ("JN1_5","073_1_5","JHN","1","5","5","Hasken yana haskakawa cikin duhu, amma duhun bai rinjaye shi ba. ");
INSERT INTO hausa_vpl VALUES ("JN1_6","073_1_6","JHN","1","6","6","Akwai wani mutumin da aka aiko daga Allah; mai suna Yohanna. ");
INSERT INTO hausa_vpl VALUES ("JN1_7","073_1_7","JHN","1","7","7","Ya zo a matsayin mai shaida domin yă ba da shaida game da wannan haske, don ta wurinsa dukan mutane su ba da gaskiya. ");
INSERT INTO hausa_vpl VALUES ("JN1_8","073_1_8","JHN","1","8","8","Shi kansa ba shi ne hasken ba; sai dai ya zo a matsayin shaida ne kaɗai ga hasken. ");
INSERT INTO hausa_vpl VALUES ("JN1_9","073_1_9","JHN","1","9","9","Haske na gaskiya da yake ba da haske ga kowane mutum mai shigowa duniya. ");
INSERT INTO hausa_vpl VALUES ("JN1_10","073_1_10","JHN","1","10","10","Yana a duniya, kuma ko da yake an yi duniya ta wurinsa ne, duniya ba tă gane shi ba. ");
INSERT INTO hausa_vpl VALUES ("JN1_11","073_1_11","JHN","1","11","11","Ya zo wurin abin da yake nasa, amma nasa ɗin ba su karɓe shi ba. ");
INSERT INTO hausa_vpl VALUES ("JN1_12","073_1_12","JHN","1","12","12","Duk da haka dukan waɗanda suka karɓe shi, ga waɗanda suka gaskata a sunansa, ya ba su iko su zama ’ya’yan Allah ");
INSERT INTO hausa_vpl VALUES ("JN1_13","073_1_13","JHN","1","13","13","’ya’yan da aka haifa ba bisa hanyar ’yan adam, ko shawarar mutum ko nufin namiji ba, sai dai haifaffu bisa ga nufin Allah. ");
INSERT INTO hausa_vpl VALUES ("JN1_14","073_1_14","JHN","1","14","14","Kalman ya zama mutum, ya kuwa zauna a cikinmu. Muka ga ɗaukakarsa, ɗaukaka ta wanda yake Ɗaya kuma Makaɗaici, wanda ya zo daga wurin Uba, cike da alheri da gaskiya. ");
INSERT INTO hausa_vpl VALUES ("JN1_15","073_1_15","JHN","1","15","15","(Yohanna ya ba da shaida game da shi. Ya ɗaga murya yana cewa, “Wannan shi ne wanda na ce, ‘Mai zuwa bayana ya fi ni girma domin yana nan kafin ni.’ ”) ");
INSERT INTO hausa_vpl VALUES ("JN1_16","073_1_16","JHN","1","16","16","Daga yalwar alherinsa dukanmu muka sami albarka bisa albarka. ");
INSERT INTO hausa_vpl VALUES ("JN1_17","073_1_17","JHN","1","17","17","Gama an ba da doka ta wurin Musa; alheri da gaskiya kuwa sun zo ne ta wurin Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("JN1_18","073_1_18","JHN","1","18","18","Ba wanda ya taɓa ganin Allah, sai dai Allah da yake Ɗaya da kuma Makaɗaici wanda yake a gefen Uba, shi ne ya bayyana shi. ");
INSERT INTO hausa_vpl VALUES ("JN1_19","073_1_19","JHN","1","19","19","To, ga shaidar Yohanna sa’ad da Yahudawan Urushalima suka aiki firistoci da Lawiyawa su tambaye shi ko shi wane ne. ");
INSERT INTO hausa_vpl VALUES ("JN1_20","073_1_20","JHN","1","20","20","Bai yi mūsu ba, amma ya shaida a fili cewa, “Ba ni ne Kiristi ba.” ");
INSERT INTO hausa_vpl VALUES ("JN1_21","073_1_21","JHN","1","21","21","Sai suka tambaye shi suka ce, “To, wane ne kai? Kai ne Iliya?” Ya ce, “A’a, ni ba shi ba ne.” “Kai ne Annabin nan?” Ya amsa ya ce, “A’a.” ");
INSERT INTO hausa_vpl VALUES ("JN1_22","073_1_22","JHN","1","22","22","A ƙarshe suka ce, “Wane ne kai? Ka ba mu amsa don mu mayar wa waɗanda suka aike mu. Me kake ce da kanka?” ");
INSERT INTO hausa_vpl VALUES ("JN1_23","073_1_23","JHN","1","23","23","Yohanna ya amsa da kalmomin annabi Ishaya, “Ni murya ne mai kira a hamada, ‘Ku miƙe hanya domin Ubangiji.’ ” ");
INSERT INTO hausa_vpl VALUES ("JN1_24","073_1_24","JHN","1","24","24","To, waɗansu Farisiyawan da aka aika ");
INSERT INTO hausa_vpl VALUES ("JN1_25","073_1_25","JHN","1","25","25","suka tambaye shi suka ce, “Don me kake yin baftisma in kai ba Kiristi ba ne, ba kuwa Iliya ba, ba kuma annabin nan ba?” ");
INSERT INTO hausa_vpl VALUES ("JN1_26","073_1_26","JHN","1","26","26","Yohanna ya amsa ya ce, “Ni dai ina baftisma da ruwa ne, amma a cikinku akwai wani tsaye da ba ku sani ba. ");
INSERT INTO hausa_vpl VALUES ("JN1_27","073_1_27","JHN","1","27","27","Shi ne mai zuwa bayana, wanda ko igiyar takalmansa ma ban isa in kunce ba.” ");
INSERT INTO hausa_vpl VALUES ("JN1_28","073_1_28","JHN","1","28","28","Wannan duk ya faru ne a Betani a ƙetaren Urdun, inda Yohanna yake yin baftisma. ");
INSERT INTO hausa_vpl VALUES ("JN1_29","073_1_29","JHN","1","29","29","Kashegari Yohanna ya ga Yesu yana zuwa wajensa sai ya ce, “Ku ga, ga Ɗan Rago na Allah mai ɗauke zunubin duniya! ");
INSERT INTO hausa_vpl VALUES ("JN1_30","073_1_30","JHN","1","30","30","Wannan shi ne wanda nake nufi sa’ad da na ce, ‘Mutum mai zuwa bayana ya fi ni girma, domin yana nan kafin ni.’ ");
INSERT INTO hausa_vpl VALUES ("JN1_31","073_1_31","JHN","1","31","31","Ko ni ma dā ban san shi ba, sai dai abin da ya sa na zo ina baftisma da ruwa shi ne domin a bayyana shi ga Isra’ila.” ");
INSERT INTO hausa_vpl VALUES ("JN1_32","073_1_32","JHN","1","32","32","Sai Yohanna ya ba da wannan shaida, “Na ga Ruhu ya sauko kamar kurciya daga sama ya zauna a kansa. ");
INSERT INTO hausa_vpl VALUES ("JN1_33","073_1_33","JHN","1","33","33","Dā ban san shi ba, sai dai wanda ya aiko ni in yi baftisma da ruwa ya gaya mini cewa, ‘Mutumin da ka ga Ruhu ya sauko ya kuma zauna a kansa shi ne wanda zai yi baftisma da Ruhu Mai Tsarki.’ ");
INSERT INTO hausa_vpl VALUES ("JN1_34","073_1_34","JHN","1","34","34","Na gani na kuma shaida cewa wannan Ɗan Allah ne.” ");
INSERT INTO hausa_vpl VALUES ("JN1_35","073_1_35","JHN","1","35","35","Kashegari kuma Yohanna yana can tare da biyu daga cikin almajiransa. ");
INSERT INTO hausa_vpl VALUES ("JN1_36","073_1_36","JHN","1","36","36","Da ya ga Yesu yana wucewa, sai ya ce, “Ku ga, ga Ɗan Rago na Allah!” ");
INSERT INTO hausa_vpl VALUES ("JN1_37","073_1_37","JHN","1","37","37","Da almajiran nan biyu suka ji ya faɗi haka, sai suka bi Yesu. ");
INSERT INTO hausa_vpl VALUES ("JN1_38","073_1_38","JHN","1","38","38","Da juyewa, sai Yesu ya ga suna bin sa, sai ya tambaye, su ya ce, “Me kuke nema?” Suka ce, “Rabbi” (wato, “Malam”), “ina kake da zama?” ");
INSERT INTO hausa_vpl VALUES ("JN1_39","073_1_39","JHN","1","39","39","Ya amsa musu ya ce, “Ku zo, za ku kuma gani.” Saboda haka suka je suka ga inda yake da zama, suka kuma zauna a can tare da shi. Wajen sa’a ta goma ce kuwa. ");
INSERT INTO hausa_vpl VALUES ("JN1_40","073_1_40","JHN","1","40","40","Andarawus ɗan’uwan Siman Bitrus, yana ɗaya daga cikin biyun nan da suka bi Yesu bayan da suka ji maganar Yohanna a kan Yesu. ");
INSERT INTO hausa_vpl VALUES ("JN1_41","073_1_41","JHN","1","41","41","Abu na fari da Andarawus ya yi shi ne ya sami ɗan’uwansa Siman ya gaya masa cewa, “Mun sami Almasihu” (wato, Kiristi). ");
INSERT INTO hausa_vpl VALUES ("JN1_42","073_1_42","JHN","1","42","42","Ya kuma kawo shi wurin Yesu. Yesu ya dube shi ya ce, “Kai ne Siman ɗan Yohanna. Za a ce da kai Kefas” (in an fassara, Bitrus ke nan). ");
INSERT INTO hausa_vpl VALUES ("JN1_43","073_1_43","JHN","1","43","43","Kashegari Yesu ya yanke shawara yă tafi Galili. Da ya sami Filibus sai ya ce masa, “Bi ni.” ");
INSERT INTO hausa_vpl VALUES ("JN1_44","073_1_44","JHN","1","44","44","Filibus, kamar Andarawus da Bitrus shi ma daga garin Betsaida ne. ");
INSERT INTO hausa_vpl VALUES ("JN1_45","073_1_45","JHN","1","45","45","Filibus ya sami Natanayel ya kuma gaya masa, “Mun sami wanda Musa ya rubuta game da shi a cikin Doka, kuma wanda annabawa suka rubuta a kansa, Yesu Banazare, ɗan Yusuf.” ");
INSERT INTO hausa_vpl VALUES ("JN1_46","073_1_46","JHN","1","46","46","Natanayel ya ce, “A Nazaret! Wani abin kirki zai iya fito daga can?” Filibus ya ce, “Zo ka gani.” ");
INSERT INTO hausa_vpl VALUES ("JN1_47","073_1_47","JHN","1","47","47","Da Yesu ya ga Natanayel yana zuwa, sai ya yi magana game da shi cewa, “Ga mutumin Isra’ila na gaske wanda ba shi da ha’inci.” ");
INSERT INTO hausa_vpl VALUES ("JN1_48","073_1_48","JHN","1","48","48","Natanayel ya yi tambaya ya ce, “A ina ka san ni?” Yesu ya amsa ya ce, “Na gan ka yayinda kake a gindin itacen ɓaure, kafin Filibus yă kira ka.” ");
INSERT INTO hausa_vpl VALUES ("JN1_49","073_1_49","JHN","1","49","49","Sai Natanayel ya ce, “Rabbi, kai Ɗan Allah ne. Kai ne Sarkin Isra’ila.” ");
INSERT INTO hausa_vpl VALUES ("JN1_50","073_1_50","JHN","1","50","50","Yesu ya ce, “Ka gaskata domin na ce maka na gan ka a gindin itacen ɓaure. Za ka ga abubuwan da suka fi haka.” ");
INSERT INTO hausa_vpl VALUES ("JN1_51","073_1_51","JHN","1","51","51","Sai ya ƙara da cewa, “Gaskiya nake gaya muku, za ku ga sama a buɗe, mala’ikun Allah kuma suna hawa suna kuma sauka a kan Ɗan Mutum.” ");
INSERT INTO hausa_vpl VALUES ("JN2_1","073_2_1","JHN","2","1","1","A rana ta uku sai aka yi bikin aure a Kana ta Galili. Mahaifiyar Yesu kuwa tana can, ");
INSERT INTO hausa_vpl VALUES ("JN2_2","073_2_2","JHN","2","2","2","aka gayyaci Yesu da almajiransa su ma a auren. ");
INSERT INTO hausa_vpl VALUES ("JN2_3","073_2_3","JHN","2","3","3","Da ruwan inabi ya ƙare, sai mahaifiyar Yesu ta ce masa, “Ba su da sauran ruwan inabi.” ");
INSERT INTO hausa_vpl VALUES ("JN2_4","073_2_4","JHN","2","4","4","Yesu ya ce, “Mace, me ya sa kike haɗa ni a wannan? Lokacina bai yi ba tukuna.” ");
INSERT INTO hausa_vpl VALUES ("JN2_5","073_2_5","JHN","2","5","5","Sai mahaifiyarsa ta ce wa bayin, “Ku yi duk abin da ya faɗa.” ");
INSERT INTO hausa_vpl VALUES ("JN2_6","073_2_6","JHN","2","6","6","Nan kusa kuwa akwai tulunan ruwa shida na dutse a ajiye, irin da Yahudawa suke amfani da su don tsarkakewa bisa ga al’ada, kowace kan ci gallon kusan ashirin zuwa talatin. ");
INSERT INTO hausa_vpl VALUES ("JN2_7","073_2_7","JHN","2","7","7","Sai Yesu ya ce wa bayin, “Ku ciccika tulunan da ruwa.” Suka kuwa ciccika su fal. ");
INSERT INTO hausa_vpl VALUES ("JN2_8","073_2_8","JHN","2","8","8","Sa’an nan ya ce musu, “Yanzu ku ɗiba ku kai wa uban bikin.” Suka yi haka. ");
INSERT INTO hausa_vpl VALUES ("JN2_9","073_2_9","JHN","2","9","9","Uban bikin kuwa ya ɗanɗana ruwan da aka juya ya zama ruwan inabi. Bai san daga ina ya fito ba, ko da yake bayin da suka ɗiba ruwan sun sani. Sai ya kira angon waje ɗaya ");
INSERT INTO hausa_vpl VALUES ("JN2_10","073_2_10","JHN","2","10","10","ya ce, “Kowa yakan kawo ruwan inabi mafi kyau da fari, sa’an nan marar kyan bayan baƙin sun sha da yawa; amma ka ajiye ruwan inabi mafi kyau sai yanzu.” ");
INSERT INTO hausa_vpl VALUES ("JN2_11","073_2_11","JHN","2","11","11","Wannan shi ne na fari cikin abubuwan banmamakin da Yesu ya yi a Kana ta Galili. Ta haka ya bayyana ɗaukakarsa, almajiransa kuwa suka ba da gaskiya gare shi. ");
INSERT INTO hausa_vpl VALUES ("JN2_12","073_2_12","JHN","2","12","12","Bayan wannan sai ya tafi Kafarnahum tare da mahaifiyarsa da ’yan’uwansa da kuma almajiransa. A can suka zauna ’yan kwanaki. ");
INSERT INTO hausa_vpl VALUES ("JN2_13","073_2_13","JHN","2","13","13","Da lokacin Bikin Ƙetarewa na Yahudawa ya yi kusa, sai Yesu ya haura zuwa Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JN2_14","073_2_14","JHN","2","14","14","A filin haikali ya sami mutane suna sayar da shanu, tumaki da tattabaru, waɗansu kuma zaune a tebur suna canjin kuɗi. ");
INSERT INTO hausa_vpl VALUES ("JN2_15","073_2_15","JHN","2","15","15","Saboda haka ya tuƙa bulala ta igiyoyi, ya kori duka daga filin haikali, har da tumaki da shanu; ya watsar da kuɗin masu canjin, ya birkice teburansu. ");
INSERT INTO hausa_vpl VALUES ("JN2_16","073_2_16","JHN","2","16","16","Ga masu sayar da tattabaru kuwa ya ce, “Ku kwashe waɗannan daga nan! Don me za ku mai da gidan Ubana kasuwa!” ");
INSERT INTO hausa_vpl VALUES ("JN2_17","073_2_17","JHN","2","17","17","Sai almajiransa suka tuna cewa a rubuce yake, “Himma saboda gidanka zai cinye ni.” ");
INSERT INTO hausa_vpl VALUES ("JN2_18","073_2_18","JHN","2","18","18","Sai Yahudawa suka tambaye shi, “Wace abar banmamaki za ka nuna mana ka tabbatar mana ikonka na yin duk waɗannan?” ");
INSERT INTO hausa_vpl VALUES ("JN2_19","073_2_19","JHN","2","19","19","Yesu ya amsa musu ya ce, “Ku rushe wannan haikali, zan kuwa sāke tā da shi cikin kwana uku.” ");
INSERT INTO hausa_vpl VALUES ("JN2_20","073_2_20","JHN","2","20","20","Yahudawa suka ce, “Sai fa da aka shekara arba’in da shida ana ginin haikalin nan, kai kuwa a cikin kwana uku za ka tā da shi?” ");
INSERT INTO hausa_vpl VALUES ("JN2_21","073_2_21","JHN","2","21","21","Amma haikalin da ya yi magana jikinsa ne. ");
INSERT INTO hausa_vpl VALUES ("JN2_22","073_2_22","JHN","2","22","22","Bayan da ya tashi daga matattu, sai almajiransa suka tuna da abin da ya faɗa. Sa’an nan suka gaskata Nassi da kuma kalmomin da Yesu ya yi. ");
INSERT INTO hausa_vpl VALUES ("JN2_23","073_2_23","JHN","2","23","23","To, yayinda yake a Urushalima a Bikin Ƙetarewa, mutane da yawa suka ga abubuwan banmamakin da yake aikata suka kuma gaskata da sunansa. ");
INSERT INTO hausa_vpl VALUES ("JN2_24","073_2_24","JHN","2","24","24","Sai dai Yesu bai amince da su ba, don ya san dukan mutane. ");
INSERT INTO hausa_vpl VALUES ("JN2_25","073_2_25","JHN","2","25","25","Ba ya bukatar shaidar mutum game da mutum, don yă san abin da yake cikin zuciyar mutum. ");
INSERT INTO hausa_vpl VALUES ("JN3_1","073_3_1","JHN","3","1","1","Akwai wani Bafarisiye mai suna Nikodimus, wani ɗan majalisar Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("JN3_2","073_3_2","JHN","3","2","2","Ya zo wurin Yesu da dad dare ya ce, “Rabbi, mun sani kai malami ne daga Allah. Gama ba wanda zai iya yin waɗannan abubuwan banmamaki da kake yi in Allah ba ya tare da shi.” ");
INSERT INTO hausa_vpl VALUES ("JN3_3","073_3_3","JHN","3","3","3","Yesu ya amsa ya ce, “Gaskiya nake faɗa maka, ba wanda zai iya ganin mulkin Allah sai an sāke haihuwarsa.” ");
INSERT INTO hausa_vpl VALUES ("JN3_4","073_3_4","JHN","3","4","4","Nikodimus ya yi tambaya ya ce, “Yaya za a haifi mutum sa’ad da ya tsufa? Tabbatacce ba zai sāke koma sau na biyu a cikin mahaifiyarsa don a haife shi kuma ba!” ");
INSERT INTO hausa_vpl VALUES ("JN3_5","073_3_5","JHN","3","5","5","Yesu ya amsa ya ce, “Gaskiya nake faɗa maka, ba wanda zai iya ganin mulkin Allah sai an haife shi ta wurin ruwa da kuma Ruhu. ");
INSERT INTO hausa_vpl VALUES ("JN3_6","073_3_6","JHN","3","6","6","Jiki yakan haifi jiki, amma Ruhu yana haifi ruhu. ");
INSERT INTO hausa_vpl VALUES ("JN3_7","073_3_7","JHN","3","7","7","Kada ka yi mamaki da na ce, ‘Dole ne a sāke haifarku.’ ");
INSERT INTO hausa_vpl VALUES ("JN3_8","073_3_8","JHN","3","8","8","Iska takan hura zuwa inda take so. Kai kakan ji motsinta, sai dai ba ka iya sanin inda take fitowa ko kuwa inda za ta. Haka yake ga duk wanda aka haifa ta wurin Ruhu.” ");
INSERT INTO hausa_vpl VALUES ("JN3_9","073_3_9","JHN","3","9","9","Nikodimus ya yi tambaya ya ce, “Yaya wannan zai yiwu?” ");
INSERT INTO hausa_vpl VALUES ("JN3_10","073_3_10","JHN","3","10","10","Yesu ya ce, “Kai ma da kake malami na Isra’ila, ba ka fahimci waɗannan abubuwa ba? ");
INSERT INTO hausa_vpl VALUES ("JN3_11","073_3_11","JHN","3","11","11","Gaskiya nake faɗa maka, muna magana a kan abin da muka sani, muka kuma shaida abin da muka gani ne, amma har yanzu kun ƙi ku karɓi shaidarmu. ");
INSERT INTO hausa_vpl VALUES ("JN3_12","073_3_12","JHN","3","12","12","Na yi muku magana a kan abubuwan duniya amma ba ku gaskata ba; to, yaya za ku gaskata in na yi magana a kan abubuwan sama? ");
INSERT INTO hausa_vpl VALUES ("JN3_13","073_3_13","JHN","3","13","13","Ba wanda ya taɓa hawa zuwa sama sai wanda ya sauka daga sama, wato, Ɗan Mutum. ");
INSERT INTO hausa_vpl VALUES ("JN3_14","073_3_14","JHN","3","14","14","Kamar dai yadda Musa ya ɗaga maciji a hamada, haka dole ne a ɗaga Ɗan Mutum, ");
INSERT INTO hausa_vpl VALUES ("JN3_15","073_3_15","JHN","3","15","15","don duk mai gaskata da shi ya sami rai madawwami.” ");
INSERT INTO hausa_vpl VALUES ("JN3_16","073_3_16","JHN","3","16","16","Gama Allah ya ƙaunaci duniya sosai har ya ba da wanda yake Ɗaya kuma Makaɗaicin Ɗansa domin duk wanda ya gaskata da shi kada yă hallaka sai dai yă sami rai madawwami. ");
INSERT INTO hausa_vpl VALUES ("JN3_17","073_3_17","JHN","3","17","17","Gama Allah bai aiki Ɗansa duniya don yă yi wa duniya hukunci ba, sai dai domin yă ceci duniya ta wurinsa. ");
INSERT INTO hausa_vpl VALUES ("JN3_18","073_3_18","JHN","3","18","18","Duk wanda ya gaskata da shi ba za a yi masa hukunci ba, amma duk wanda bai gaskata ba an riga an yi masa hukunci domin bai gaskata da sunan wanda yake Ɗaya kuma Makaɗaicin Ɗan Allah ba. ");
INSERT INTO hausa_vpl VALUES ("JN3_19","073_3_19","JHN","3","19","19","Hukuncin shi ne, Haske ya zo cikin duniya, amma mutane suka so duhu a maimakon haske domin ayyukansu mugaye ne. ");
INSERT INTO hausa_vpl VALUES ("JN3_20","073_3_20","JHN","3","20","20","Duk mai aikata mugunta yana ƙin haske, ba zai kuwa zo cikin haske ba don yana tsoro kada ayyukansa su tonu. ");
INSERT INTO hausa_vpl VALUES ("JN3_21","073_3_21","JHN","3","21","21","Amma duk mai rayuwa bisa ga gaskiya yakan zo cikin haske, domin a gani a sarari cewa ayyukan da ya yi an yi su ne ta wurin Allah. ");
INSERT INTO hausa_vpl VALUES ("JN3_22","073_3_22","JHN","3","22","22","Bayan wannan, Yesu da almajiransa suka tafi ƙauyukan Yahudiya, inda ya ɗan jima da su, ya kuma yi baftisma. ");
INSERT INTO hausa_vpl VALUES ("JN3_23","073_3_23","JHN","3","23","23","To, Yohanna ma yana yin baftisma a Ainon kusa da Salim, saboda akwai ruwa da yawa a can, mutane kuwa suka yi ta zuwa don a yi musu baftisma. ");
INSERT INTO hausa_vpl VALUES ("JN3_24","073_3_24","JHN","3","24","24","(Wannan kuwa kafin a sa Yohanna a kurkuku.) ");
INSERT INTO hausa_vpl VALUES ("JN3_25","073_3_25","JHN","3","25","25","Sai gardama ta tashi tsakanin waɗansu almajiran Yohanna da wani mutumin Yahuda a kan zancen al’adar tsarkakewa. ");
INSERT INTO hausa_vpl VALUES ("JN3_26","073_3_26","JHN","3","26","26","Sai suka zo wurin Yohanna suka ce masa, “Rabbi, wancan mutumin da yake tare da kai a ƙetaren Urdun, wannan da ka ba da shaida a kansa sosai nan, yana baftisma, kuma kowa yana zuwa wurinsa.” ");
INSERT INTO hausa_vpl VALUES ("JN3_27","073_3_27","JHN","3","27","27","Ga wannan zancen Yohanna ya amsa ya ce, “Mutum yakan karɓi kawai abin da aka ba shi ne daga sama. ");
INSERT INTO hausa_vpl VALUES ("JN3_28","073_3_28","JHN","3","28","28","Ku kanku za ku shaida cewa na ce, ‘Ba ni ne Kiristi ba, sai dai an aiko ni ne in sha gabansa.’ ");
INSERT INTO hausa_vpl VALUES ("JN3_29","073_3_29","JHN","3","29","29","Ango ne mai amarya. Abokin da yake masa hidima yakan jira ya kuma saurara masa, yakan kuma cika da farin ciki sa’ad da ya ji muryar ango. Wannan farin cikin kuwa nawa ne, ya kuma cika a yanzu. ");
INSERT INTO hausa_vpl VALUES ("JN3_30","073_3_30","JHN","3","30","30","Dole ne yă yi ta ƙaruwa, ni kuma in yi ta raguwa. ");
INSERT INTO hausa_vpl VALUES ("JN3_31","073_3_31","JHN","3","31","31","“Wannan da ya zo daga sama ya fi kowa; wannan da ya zo daga ƙasa na ƙasa ne, yana kuma magana kamar wanda ya zo daga ƙasa ne. Wannan da ya zo daga sama ya fi kowa. ");
INSERT INTO hausa_vpl VALUES ("JN3_32","073_3_32","JHN","3","32","32","Yana ba da shaidar abin da ya gani da kuma ya ji, duk da haka ba wanda ya yarda da shaidarsa. ");
INSERT INTO hausa_vpl VALUES ("JN3_33","073_3_33","JHN","3","33","33","Mutumin da ya yarda da ita ya tabbatar da cewa Allah mai gaskiya ne. ");
INSERT INTO hausa_vpl VALUES ("JN3_34","073_3_34","JHN","3","34","34","Gama wannan da Allah ya aiko yakan faɗi kalmomin Allah ne, gama Allah yana ba da Ruhu babu iyaka. ");
INSERT INTO hausa_vpl VALUES ("JN3_35","073_3_35","JHN","3","35","35","Uban yana ƙaunar Ɗan ya kuma danƙa kome a hannuwansa. ");
INSERT INTO hausa_vpl VALUES ("JN3_36","073_3_36","JHN","3","36","36","Duk wanda ya gaskata da Ɗan yana da rai madawwami, amma duk wanda ya ƙi Ɗan ba zai sami rai ba, gama fushin Allah yana nan a bisansa.” ");
INSERT INTO hausa_vpl VALUES ("JN4_1","073_4_1","JHN","4","1","1","Yesu ya ji labari cewa Yahudawa sun ji cewa ya wuce Yohanna samun masu bi, yana kuma yin musu baftisma, ");
INSERT INTO hausa_vpl VALUES ("JN4_2","073_4_2","JHN","4","2","2","ko da yake ba Yesu ne yake baftismar ba, almajiransa ne. ");
INSERT INTO hausa_vpl VALUES ("JN4_3","073_4_3","JHN","4","3","3","Da ya sami wannan labari, sai ya bar Yahudiya ya sāke koma Galili. ");
INSERT INTO hausa_vpl VALUES ("JN4_4","073_4_4","JHN","4","4","4","To, ya zama dole yă bi ta Samariya. ");
INSERT INTO hausa_vpl VALUES ("JN4_5","073_4_5","JHN","4","5","5","Sai ya zo wani gari a Samariya da ake ce da shi Saikar, kurkusa da filin da Yaƙub ya ba wa ɗansa Yusuf. ");
INSERT INTO hausa_vpl VALUES ("JN4_6","073_4_6","JHN","4","6","6","Rijiyar Yaƙub kuwa tana can, Yesu kuwa, saboda gajiyar tafiya, sai ya zauna a bakin rijiyar. Wajen sa’a ta shida ne. ");
INSERT INTO hausa_vpl VALUES ("JN4_7","073_4_7","JHN","4","7","7","Sa’ad da wata mutuniyar Samariya ta zo ɗiban ruwa, sai Yesu ya ce mata, “Ba ni ruwa in sha?” ");
INSERT INTO hausa_vpl VALUES ("JN4_8","073_4_8","JHN","4","8","8","(Almajiransa kuwa sun shiga gari don sayi abinci.) ");
INSERT INTO hausa_vpl VALUES ("JN4_9","073_4_9","JHN","4","9","9","Sai mutuniyar Samariyar ta ce masa, “Kai mutumin Yahuda ne, ni kuwa mutuniyar Samariya ce. Yaya za ka roƙe ni ruwan sha?” (Don Yahudawa ba sa hulɗa da Samariyawa.) ");
INSERT INTO hausa_vpl VALUES ("JN4_10","073_4_10","JHN","4","10","10","Yesu ya amsa mata ya ce, “Da kin san kyautar Allah, da kuma wanda yake roƙonki ruwan sha, da kin roƙe shi, shi kuwa da ya ba ki ruwan rai.” ");
INSERT INTO hausa_vpl VALUES ("JN4_11","073_4_11","JHN","4","11","11","Sai macen ta ce, “Ranka yă daɗe, ba ka da guga rijiyar kuwa tana da zurfi. Ina za ka sami wannan ruwan rai? ");
INSERT INTO hausa_vpl VALUES ("JN4_12","073_4_12","JHN","4","12","12","Ka fi mahaifinmu Yaƙub ne, wanda ya ba mu rijiyar ya kuma sha daga ciki da kansa, haka ma ’ya’yansa da kuma garkunan shanunsa da tumakinsa?” ");
INSERT INTO hausa_vpl VALUES ("JN4_13","073_4_13","JHN","4","13","13","Yesu ya amsa ya ce, “Kowa ya sha wannan ruwa, zai sāke jin ƙishirwa, ");
INSERT INTO hausa_vpl VALUES ("JN4_14","073_4_14","JHN","4","14","14","amma duk wanda ya sha ruwan da zan ba shi, ba zai ƙara jin ƙishirwa ba. Tabbatacce, ruwan da zan ba shi, zai zama masa maɓuɓɓugan ruwa da yake ɓuɓɓugowa har yă zuwa rai madawwami.” ");
INSERT INTO hausa_vpl VALUES ("JN4_15","073_4_15","JHN","4","15","15","Sai macen ta ce masa, “Ranka yă daɗe, ka ba ni ruwan nan, don kada in ƙara jin ƙishirwa, in yi ta zuwa nan ɗiban ruwa.” ");
INSERT INTO hausa_vpl VALUES ("JN4_16","073_4_16","JHN","4","16","16","Sai ya ce mata, “Je ki zo da mijinki.” ");
INSERT INTO hausa_vpl VALUES ("JN4_17","073_4_17","JHN","4","17","17","Sai ta amsa ta ce, “Ai, ba ni da miji.” Yesu ya ce mata, “Gaskiyarki da kika ce ba ki da miji. ");
INSERT INTO hausa_vpl VALUES ("JN4_18","073_4_18","JHN","4","18","18","Gaskiyar ita ce, kin auri maza biyar, wanda kuke tare yanzu kuwa ba mijinki ba ne. A nan kam kin yi gaskiya.” ");
INSERT INTO hausa_vpl VALUES ("JN4_19","073_4_19","JHN","4","19","19","Sai macen ta ce, “Ranka yă daɗe, ina gani kai annabi ne. ");
INSERT INTO hausa_vpl VALUES ("JN4_20","073_4_20","JHN","4","20","20","Kakanninmu sun yi sujada a dutsen nan, amma ku Yahudawa kun ce a Urushalima ne ya kamata a yi sujada.” ");
INSERT INTO hausa_vpl VALUES ("JN4_21","073_4_21","JHN","4","21","21","Sai Yesu ya ce, “Uwargida, ina tabbatar miki, lokaci yana zuwa da ba za ku yi wa Uba sujada ko a dutsen nan, ko kuwa a Urushalima ba. ");
INSERT INTO hausa_vpl VALUES ("JN4_22","073_4_22","JHN","4","22","22","Ku Samariyawa ba ku san abin da kuke yi wa sujada ba; mu kuwa mun san abin da muke yi wa sujada, gama ceto daga Yahudawa yake. ");
INSERT INTO hausa_vpl VALUES ("JN4_23","073_4_23","JHN","4","23","23","Duk da haka, lokaci yana zuwa har ma ya riga ya yi, da masu sujada na gaskiya za su yi wa Uba sujada a Ruhu da kuma gaskiya, gama irin waɗannan masu sujada ne Uba yake nema. ");
INSERT INTO hausa_vpl VALUES ("JN4_24","073_4_24","JHN","4","24","24","Allah ruhu ne, masu yi masa sujada kuwa dole su yi masa sujada a ruhu, da gaskiya kuma.” ");
INSERT INTO hausa_vpl VALUES ("JN4_25","073_4_25","JHN","4","25","25","Macen ta ce, “Na san cewa Almasihu” (da ake ce da shi Kiristi) “yana zuwa. Sa’ad da ya zo kuwa, zai bayyana mana kome.” ");
INSERT INTO hausa_vpl VALUES ("JN4_26","073_4_26","JHN","4","26","26","Sai Yesu ya ce, “Ni mai maganan nan da ke, Ni ne shi.” ");
INSERT INTO hausa_vpl VALUES ("JN4_27","073_4_27","JHN","4","27","27","Suna gama magana ke nan sai almajiransa suka iso, suka yi mamakin ganin yana magana da mace. Amma ba wanda ya ce, “Me kake so?” Ko “Me ya sa kake magana da ita?” ");
INSERT INTO hausa_vpl VALUES ("JN4_28","073_4_28","JHN","4","28","28","Sai macen ta bar tulunta na ruwa, ta koma cikin gari ta ce wa mutane, ");
INSERT INTO hausa_vpl VALUES ("JN4_29","073_4_29","JHN","4","29","29","“Ku zo, ku ga mutumin da ya gaya mini duk abin da na taɓa yi. Shin, ko shi ne Kiristi?” ");
INSERT INTO hausa_vpl VALUES ("JN4_30","073_4_30","JHN","4","30","30","Sai suka fita daga garin suka nufa inda yake. ");
INSERT INTO hausa_vpl VALUES ("JN4_31","073_4_31","JHN","4","31","31","Ana cikin haka, sai almajiransa suka roƙe shi suka ce, “Rabbi, ci abinci mana.” ");
INSERT INTO hausa_vpl VALUES ("JN4_32","073_4_32","JHN","4","32","32","Amma ya ce musu, “Ina da abincin da ba ku san kome a kai ba.” ");
INSERT INTO hausa_vpl VALUES ("JN4_33","073_4_33","JHN","4","33","33","Sai almajiran suka ce wa juna, “Shin, ko wani ya kawo masa abinci ne?” ");
INSERT INTO hausa_vpl VALUES ("JN4_34","073_4_34","JHN","4","34","34","Yesu ya ce, “Abincina shi ne, in aikata nufin wannan da ya aiko ni, in kuma gama aikinsa. ");
INSERT INTO hausa_vpl VALUES ("JN4_35","073_4_35","JHN","4","35","35","Ba kukan ce, ‘Sauran wata huɗu a yi girbi ba?’ Ina gaya muku, ku ɗaga idanu ku dubi gonaki! Sun isa girbi. ");
INSERT INTO hausa_vpl VALUES ("JN4_36","073_4_36","JHN","4","36","36","Mai girbi na samun lada, yana kuma tara amfani zuwa rai madawwami, domin mai shuka da mai girbi su yi farin ciki tare. ");
INSERT INTO hausa_vpl VALUES ("JN4_37","073_4_37","JHN","4","37","37","Karin maganan nan gaskiya ne cewa, ‘Wani da shuka, wani kuma da girbi.’ ");
INSERT INTO hausa_vpl VALUES ("JN4_38","073_4_38","JHN","4","38","38","Na aike ku girbin abin da ba ku yi aikinsa ba. Waɗansu sun yi aikin nan mai wahala, ku kuwa kun sami ladan aikinsu.” ");
INSERT INTO hausa_vpl VALUES ("JN4_39","073_4_39","JHN","4","39","39","Samariyawa da yawa daga wannan gari suka gaskata da shi saboda shaidar macen da ta ce, “Ya gaya mini duk abin da na taɓa yi.” ");
INSERT INTO hausa_vpl VALUES ("JN4_40","073_4_40","JHN","4","40","40","To, da Samariyawa suka zo wurinsa, sai suka roƙe shi yă zauna da su, ya kuwa zauna kwana biyu. ");
INSERT INTO hausa_vpl VALUES ("JN4_41","073_4_41","JHN","4","41","41","Saboda kalmominsa kuwa da yawa suka gaskata. ");
INSERT INTO hausa_vpl VALUES ("JN4_42","073_4_42","JHN","4","42","42","Sai suka ce wa macen, “Yanzu kam mun gaskata, ba don abin da kika faɗa kawai ba; yanzu mun ji da kanmu, mun kuwa san cewa wannan mutum tabbatacce shi ne Mai Ceton duniya.” ");
INSERT INTO hausa_vpl VALUES ("JN4_43","073_4_43","JHN","4","43","43","Bayan kwana biyun nan sai ya bar can zuwa Galili. ");
INSERT INTO hausa_vpl VALUES ("JN4_44","073_4_44","JHN","4","44","44","(To, Yesu kansa ya taɓa faɗa cewa annabi ba shi da daraja a ƙasarsa.) ");
INSERT INTO hausa_vpl VALUES ("JN4_45","073_4_45","JHN","4","45","45","Da ya isa Galili, sai mutanen Galili suka marabce shi. Sun ga duk abin da ya yi a Urushalima a lokacin Bikin Ƙetarewa, gama su ma sun kasance a can. ");
INSERT INTO hausa_vpl VALUES ("JN4_46","073_4_46","JHN","4","46","46","Sai ya sāke ziyarci Kana ta Galili inda ya juya ruwa ya zama ruwan inabi. Akwai wani ma’aikacin hukuma a can wanda ɗansa yake kwance da rashin lafiya a Kafarnahum. ");
INSERT INTO hausa_vpl VALUES ("JN4_47","073_4_47","JHN","4","47","47","Da mutumin nan ya ji cewa Yesu ya isa Galili daga Yahudiya, sai ya je wurinsa ya roƙe shi yă zo yă warkar da ɗansa da yake bakin mutuwa. ");
INSERT INTO hausa_vpl VALUES ("JN4_48","073_4_48","JHN","4","48","48","Yesu ya ce masa, “Ku mutane, in ba kun ga alamu da abubuwan banmamaki ba, ba yadda za a yi ku ba da gaskiya.” ");
INSERT INTO hausa_vpl VALUES ("JN4_49","073_4_49","JHN","4","49","49","Ma’aikacin hukuman ya ce, “Ranka yă daɗe, ka zo kafin ɗana yă mutu.” ");
INSERT INTO hausa_vpl VALUES ("JN4_50","073_4_50","JHN","4","50","50","Sai Yesu ya amsa ya ce, “Ka tafi. Ɗanka zai rayu.” Mutumin kuwa ya amince da maganar da Yesu ya yi ya kuwa tafi. ");
INSERT INTO hausa_vpl VALUES ("JN4_51","073_4_51","JHN","4","51","51","Tun yana kan hanya, bayinsa suka tarye shi da labari cewa yaron yana warkewa. ");
INSERT INTO hausa_vpl VALUES ("JN4_52","073_4_52","JHN","4","52","52","Da ya tambayi lokacin da ɗansa ya sami sauƙi, sai suka ce masa, “Zazzaɓin ya sake shi jiya a sa’a ta bakwai.” ");
INSERT INTO hausa_vpl VALUES ("JN4_53","073_4_53","JHN","4","53","53","Sai mahaifin ya gane a daidai wannan lokaci ne Yesu ya ce masa, “Ɗanka zai rayu.” Saboda haka shi da dukan iyalinsa suka gaskata. ");
INSERT INTO hausa_vpl VALUES ("JN4_54","073_4_54","JHN","4","54","54","Wannan ce abin banmamaki ta biyu da Yesu ya yi, bayan zuwansa daga Yahudiya zuwa Galili. ");
INSERT INTO hausa_vpl VALUES ("JN5_1","073_5_1","JHN","5","1","1","Bayan an ɗan jima, sai Yesu ya haura zuwa Urushalima don wani bikin Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("JN5_2","073_5_2","JHN","5","2","2","To, a Urushalima akwai wani tafki kusa da Ƙofar Tumaki, wanda a yaren Arameyik ake kira Betesda an kuma kewaye shi da shirayi biyar. ");
INSERT INTO hausa_vpl VALUES ("JN5_3","073_5_3","JHN","5","3","3","A nan naƙasassu da yawa sukan kwanta, makafi, guragu, shanyayyu. ");
INSERT INTO hausa_vpl VALUES ("JN5_5","073_5_5","JHN","5","5","5","Akwai wani da yake nan ba shi da amfani shekara talatin da takwas. ");
INSERT INTO hausa_vpl VALUES ("JN5_6","073_5_6","JHN","5","6","6","Da Yesu ya gan shi kwance a can ya kuma sami labari cewa ya daɗe a wannan hali, sai ya tambaye shi, “Kana so ka warke?” ");
INSERT INTO hausa_vpl VALUES ("JN5_7","073_5_7","JHN","5","7","7","Marar amfanin nan ya ce, “Ranka yă daɗe, ba ni da wanda zai taimaka yă sa ni a cikin tafkin sa’ad da aka motsa ruwan. Yayinda nake ƙoƙarin shiga, sai wani yă riga ni.” ");
INSERT INTO hausa_vpl VALUES ("JN5_8","073_5_8","JHN","5","8","8","Sai Yesu ya ce masa, “Tashi! Ɗauki tabarmarka ka yi tafiya.” ");
INSERT INTO hausa_vpl VALUES ("JN5_9","073_5_9","JHN","5","9","9","Nan take mutumin ya warke; ya ɗauki tabarmarsa ya yi tafiya. A ranar da wannan ya faru ranar Asabbaci ce, ");
INSERT INTO hausa_vpl VALUES ("JN5_10","073_5_10","JHN","5","10","10","saboda haka kuwa Yahudawa suka ce wa mutumin da aka warkar, “Yau Asabbaci ne; doka ta hana ka ɗauki tabarmarka.” ");
INSERT INTO hausa_vpl VALUES ("JN5_11","073_5_11","JHN","5","11","11","Amma ya amsa ya ce, “Mutumin da ya warkar da ni shi ya ce mini, ‘Ɗauki tabarmarka ka yi tafiya.’ ” ");
INSERT INTO hausa_vpl VALUES ("JN5_12","073_5_12","JHN","5","12","12","Sai suka tambaye shi suka ce, “Wane ne wannan da ya ce maka ka ɗauke ta ka yi tafiya?” ");
INSERT INTO hausa_vpl VALUES ("JN5_13","073_5_13","JHN","5","13","13","Mutumin da aka warkar kuwa bai ma san ko wane ne ba ne, gama Yesu ya ɓace cikin taron da yake can. ");
INSERT INTO hausa_vpl VALUES ("JN5_14","073_5_14","JHN","5","14","14","Daga baya Yesu ya same shi a haikali ya ce masa, “Ga shi, ka warke. Ka daina yin zunubi, in ba haka ba wani abin da ya fi wannan muni zai iya samunka.” ");
INSERT INTO hausa_vpl VALUES ("JN5_15","073_5_15","JHN","5","15","15","Sai mutumin ya je ya gaya wa Yahudawa cewa Yesu ne ya warkar da shi. ");
INSERT INTO hausa_vpl VALUES ("JN5_16","073_5_16","JHN","5","16","16","To, domin Yesu yana yin waɗannan abubuwa a ranar Asabbaci, sai Yahudawa suka tsananta masa. ");
INSERT INTO hausa_vpl VALUES ("JN5_17","073_5_17","JHN","5","17","17","Yesu ya ce musu, “Ubana yana cikin aikinsa kullum har yă zuwa wannan rana, haka ni ma, ina kan aiki.” ");
INSERT INTO hausa_vpl VALUES ("JN5_18","073_5_18","JHN","5","18","18","Don haka Yahudawa suka ƙara nema su kashe shi; ba don yă karya Asabbaci kawai ba, har ma yana ce Allah Ubansa ne, yana mai da kansa daidai da Allah. ");
INSERT INTO hausa_vpl VALUES ("JN5_19","073_5_19","JHN","5","19","19","Sai Yesu ya ba su wannan amsa cewa, “Gaskiya nake gaya muku, Ɗan ba ya iya yin kome da kansa; yana yin abin da ya ga Ubansa yake yi ne kawai, gama duk abin da Uban yake yi shi ne Ɗan ma yake yi. ");
INSERT INTO hausa_vpl VALUES ("JN5_20","073_5_20","JHN","5","20","20","Gama Uban yana ƙaunar Ɗan yana kuma nuna masa duk abin da yake yi. I, za ku kuwa yi mamaki, gama zai nuna masa abubuwan da suka fi waɗannan girma. ");
INSERT INTO hausa_vpl VALUES ("JN5_21","073_5_21","JHN","5","21","21","Gama kamar yadda Uban yake tā da matattu yake kuma ba su rai, haka ma Ɗan yake ba da rai ga wanda ya ga dama. ");
INSERT INTO hausa_vpl VALUES ("JN5_22","073_5_22","JHN","5","22","22","Bugu da ƙari, Uban ba ya hukunta kowa, sai dai ya danƙa dukan hukunci a hannun Ɗan, ");
INSERT INTO hausa_vpl VALUES ("JN5_23","073_5_23","JHN","5","23","23","don kowa yă girmama Ɗan kamar yadda yake girmama Uban. Wanda ba ya girmama Ɗan ba ya girmama Uban, da ya aiko shi ke nan. ");
INSERT INTO hausa_vpl VALUES ("JN5_24","073_5_24","JHN","5","24","24","“Gaskiya nake gaya muku, duk wanda ya ji maganata ya kuma gaskata da wanda ya aiko ni yana da rai madawwami ba za a kuma hukunta shi ba; ya riga ya ƙetare daga mutuwa zuwa rai. ");
INSERT INTO hausa_vpl VALUES ("JN5_25","073_5_25","JHN","5","25","25","Gaskiya nake gaya muku, lokaci yana zuwa har ma ya riga ya zo sa’ad da matattu za su ji muryar Ɗan Allah waɗanda kuwa suka ji za su rayu. ");
INSERT INTO hausa_vpl VALUES ("JN5_26","073_5_26","JHN","5","26","26","Gama kamar yadda Uban yana da rai a cikinsa, haka ya sa Ɗan yă kasance da rai a cikin kansa. ");
INSERT INTO hausa_vpl VALUES ("JN5_27","073_5_27","JHN","5","27","27","Ya kuma ba shi iko yă hukunta domin shi Ɗan Mutum ne. ");
INSERT INTO hausa_vpl VALUES ("JN5_28","073_5_28","JHN","5","28","28","“Kada ku yi mamakin wannan, gama lokaci yana zuwa da duk waɗanda suke cikin kaburbura za su ji muryarsa ");
INSERT INTO hausa_vpl VALUES ("JN5_29","073_5_29","JHN","5","29","29","su kuma fito, waɗanda suka aikata nagarta za su tashi zuwa ga rai, waɗanda kuma suka aikata mugunta za su tashi zuwa ga hukunci. ");
INSERT INTO hausa_vpl VALUES ("JN5_30","073_5_30","JHN","5","30","30","Ni kaɗai dai ba na iya yin kome, ina shari’a ne bisa ga abin da na ji. Shari’ata kuwa mai adalci ce. Gama ba na neman gamsar da kaina, sai dai in gamshi shi wanda ya aiko ni. ");
INSERT INTO hausa_vpl VALUES ("JN5_31","073_5_31","JHN","5","31","31","“In na ba da shaida a kaina, shaidata ba gaskiya ba ce. ");
INSERT INTO hausa_vpl VALUES ("JN5_32","073_5_32","JHN","5","32","32","Akwai wani mai ba da shaida mai kyau a kaina, na kuma san cewa shaidarsa game da ni gaskiya ce. ");
INSERT INTO hausa_vpl VALUES ("JN5_33","073_5_33","JHN","5","33","33","“Kun aika wajen Yohanna ya kuma yi shaida a kan gaskiya. ");
INSERT INTO hausa_vpl VALUES ("JN5_34","073_5_34","JHN","5","34","34","Ba cewa ina neman shaidar mutum ba ne; sai dai na faɗi haka ne domin ku sami ceto. ");
INSERT INTO hausa_vpl VALUES ("JN5_35","073_5_35","JHN","5","35","35","Yohanna fitila ne da ya ci ya kuma ba da haske, kun kuwa zaɓa ku ji daɗin haskensa na ɗan lokaci. ");
INSERT INTO hausa_vpl VALUES ("JN5_36","073_5_36","JHN","5","36","36","“Ina da shaidar da ta fi ta Yohanna ƙarfi. Gama aikin nan da Uba ya ba ni in kammala, wanda kuwa nake yi, yana ba da shaida cewa Uba ne ya aiko ni. ");
INSERT INTO hausa_vpl VALUES ("JN5_37","073_5_37","JHN","5","37","37","Uba da ya aiko ni kuwa kansa ya yi shaida game da ni. Ba ku taɓa jin muryarsa ko ganin siffarsa ba, ");
INSERT INTO hausa_vpl VALUES ("JN5_38","073_5_38","JHN","5","38","38","maganarsa kuwa ba ta zama a cikinku, gama ba ku gaskata da wanda ya aiko ni ba. ");
INSERT INTO hausa_vpl VALUES ("JN5_39","073_5_39","JHN","5","39","39","Kuna ta nazarin Nassosi da himma don kuna tsammani ta wurinsu ne kuna samun rai madawwami. Nassosin nan ne suke ba da shaida a kaina, ");
INSERT INTO hausa_vpl VALUES ("JN5_40","073_5_40","JHN","5","40","40","duk da haka kun ƙi zuwa wurina domin ku sami rai. ");
INSERT INTO hausa_vpl VALUES ("JN5_41","073_5_41","JHN","5","41","41","“Ni ba na neman yabon mutane, ");
INSERT INTO hausa_vpl VALUES ("JN5_42","073_5_42","JHN","5","42","42","na fa san ku. Na san cewa ba ku da ƙaunar Allah a cikin zukatanku. ");
INSERT INTO hausa_vpl VALUES ("JN5_43","073_5_43","JHN","5","43","43","Na zo a cikin sunan Ubana, ba ku kuwa karɓe ni ba; amma a ce wani dabam ya zo a cikin sunan kansa, za ku karɓe shi. ");
INSERT INTO hausa_vpl VALUES ("JN5_44","073_5_44","JHN","5","44","44","Ta yaya za ku gaskata in kuna neman yabon junanku, ba kwa kuwa yin ƙoƙarin neman yabon da yake zuwa daga Allah Makaɗaici? ");
INSERT INTO hausa_vpl VALUES ("JN5_45","073_5_45","JHN","5","45","45","“Kada fa ku yi tsammani zan yi ƙararku wurin Uba. Akwai mai yin ƙararku, shi ne Musa, wanda kuke dogara da shi. ");
INSERT INTO hausa_vpl VALUES ("JN5_46","073_5_46","JHN","5","46","46","Da a ce kun gaskata da Musa, da kun gaskata ni, domin ya rubuta game da ni. ");
INSERT INTO hausa_vpl VALUES ("JN5_47","073_5_47","JHN","5","47","47","Amma da yake ba ku gaskata abin da ya rubuta ba, yaya za ku gaskata maganata?” ");
INSERT INTO hausa_vpl VALUES ("JN6_1","073_6_1","JHN","6","1","1","Ɗan lokaci bayan wannan, sai Yesu ya ƙetare zuwa gaɓar mai nesa na Tekun Galili (wato, Tekun Tibariya), ");
INSERT INTO hausa_vpl VALUES ("JN6_2","073_6_2","JHN","6","2","2","sai taro mai yawa na mutane suka bi shi domin sun ga abubuwan banmamakin da ya yi ga marasa lafiya. ");
INSERT INTO hausa_vpl VALUES ("JN6_3","073_6_3","JHN","6","3","3","Sa’an nan Yesu ya hau gefen dutse ya zauna tare da almajiransa. ");
INSERT INTO hausa_vpl VALUES ("JN6_4","073_6_4","JHN","6","4","4","Bikin Ƙetarewan Yahudawa ya yi kusa. ");
INSERT INTO hausa_vpl VALUES ("JN6_5","073_6_5","JHN","6","5","5","Sa’ad da Yesu ya ɗaga kai ya ga taro mai yawa suna zuwa wajensa, sai ya ce wa Filibus, “Ina za mu sayi burodi saboda mutanen nan su ci?” ");
INSERT INTO hausa_vpl VALUES ("JN6_6","073_6_6","JHN","6","6","6","Ya yi wannan tambayar don yă gwada shi ne kawai, gama ya riga ya san abin da zai yi. ");
INSERT INTO hausa_vpl VALUES ("JN6_7","073_6_7","JHN","6","7","7","Sai Filibus ya amsa ya ce, “Kai, ko albashin wata takwas ba zai iya sayan isashen burodin da kowa zai ɗan samu kaɗan ba!” ");
INSERT INTO hausa_vpl VALUES ("JN6_8","073_6_8","JHN","6","8","8","Sai wani daga cikin almajiransa Andarawus, ɗan’uwan Bitrus, ya yi magana, ");
INSERT INTO hausa_vpl VALUES ("JN6_9","073_6_9","JHN","6","9","9","“Ga wani yaro da ƙananan burodin sha’ir guda biyar da ƙananan kifi biyu, amma me wannan zai yi wa yawan mutanen nan.” ");
INSERT INTO hausa_vpl VALUES ("JN6_10","073_6_10","JHN","6","10","10","Yesu ya ce, “Ku sa mutanen su zauna.” Wurin kuwa akwai ciyawa da sosai, sai maza suka zazzauna, sun kai wajen dubu biyar. ");
INSERT INTO hausa_vpl VALUES ("JN6_11","073_6_11","JHN","6","11","11","Sa’an nan Yesu ya ɗauki burodin, ya yi godiya, ya kuma rarraba wa waɗanda suke zaune gwargwadon abin da ya ishe su. Haka kuma ya yi da kifin. ");
INSERT INTO hausa_vpl VALUES ("JN6_12","073_6_12","JHN","6","12","12","Sa’ad da duk suka ci suka ƙoshi, sai ya ce wa almajiransa, “Ku tattara gutsattsarin da suka rage. Kada kome yă lalace.” ");
INSERT INTO hausa_vpl VALUES ("JN6_13","073_6_13","JHN","6","13","13","Saboda haka suka tattara su suka kuma cika kwanduna goma sha biyu na gutsattsarin burodin sha’ir biyar nan da suka ragu bayan kowa ya ci. ");
INSERT INTO hausa_vpl VALUES ("JN6_14","073_6_14","JHN","6","14","14","Bayan mutanen suka ga abin banmamakin da Yesu ya yi, sai suka fara cewa, “Lalle, wannan shi ne Annabin nan mai zuwa duniya.” ");
INSERT INTO hausa_vpl VALUES ("JN6_15","073_6_15","JHN","6","15","15","Da Yesu ya gane suna shirin su ɗauke shi ƙarfi da yaji su naɗa shi sarki, sai ya sāke komawa kan dutsen shi kaɗai. ");
INSERT INTO hausa_vpl VALUES ("JN6_16","073_6_16","JHN","6","16","16","Da yamma ta yi, sai almajiransa suka gangara zuwa tafki, ");
INSERT INTO hausa_vpl VALUES ("JN6_17","073_6_17","JHN","6","17","17","inda suka shiga jirgin ruwa suka tasar wa haye tafkin zuwa Kafarnahum. A lokacin kuwa duhu ya yi, Yesu kuma bai riga ya zo wurinsu ba tukuna. ");
INSERT INTO hausa_vpl VALUES ("JN6_18","073_6_18","JHN","6","18","18","Iska mai ƙarfi kuwa tana bugowa, ruwaye kuma suka fara hauka. ");
INSERT INTO hausa_vpl VALUES ("JN6_19","073_6_19","JHN","6","19","19","Bayan sun yi tuƙi wajen mil uku ko uku da rabi, sai suka ga Yesu ya kusato jirgin ruwan, yana takawa a kan ruwan; sai suka tsorata. ");
INSERT INTO hausa_vpl VALUES ("JN6_20","073_6_20","JHN","6","20","20","Amma ya ce musu, “Ni ne; kada ku ji tsoro.” ");
INSERT INTO hausa_vpl VALUES ("JN6_21","073_6_21","JHN","6","21","21","Sa’an nan suka yarda suka karɓe shi a cikin jirgin ruwan, nan da nan kuwa jirgin ya kai gaɓar da za su. ");
INSERT INTO hausa_vpl VALUES ("JN6_22","073_6_22","JHN","6","22","22","Kashegari taron da suka tsaya a wancan ƙetaren tafkin suka lura cewa jirgin ruwa ɗaya ne yake a can dā ma, kuma sun lura cewa Yesu bai shiga ciki tare da almajiransa ba, gama sun tashi su kaɗai. ");
INSERT INTO hausa_vpl VALUES ("JN6_23","073_6_23","JHN","6","23","23","Sai ga waɗansu jiragen ruwa daga Tibariya suka iso kusa da wurin da mutanen suka ci burodi bayan Ubangiji ya yi godiya. ");
INSERT INTO hausa_vpl VALUES ("JN6_24","073_6_24","JHN","6","24","24","Da taron suka lura cewa Yesu da almajiransa ba sa can, sai suka shiga jiragen ruwa suka tafi Kafarnahum neman Yesu. ");
INSERT INTO hausa_vpl VALUES ("JN6_25","073_6_25","JHN","6","25","25","Da suka same shi a wancan ƙetaren tafkin, sai suka tambaye shi suka ce, “Rabbi, yaushe ka kai nan?” ");
INSERT INTO hausa_vpl VALUES ("JN6_26","073_6_26","JHN","6","26","26","Yesu ya amsa ya ce, “Gaskiya nake gaya muku, kuna nemana ne ba don kun ga abubuwan banmamaki ba, sai dai domin kun ci burodi kun ƙoshi. ");
INSERT INTO hausa_vpl VALUES ("JN6_27","073_6_27","JHN","6","27","27","Kada ku yi aiki saboda abincin da yake lalacewa, sai dai saboda abinci mai dawwama har yă zuwa rai madawwami, wanda Ɗan Mutum zai ba ku. A kansa ne Allah Uba ya sa hatimin amincewarsa.” ");
INSERT INTO hausa_vpl VALUES ("JN6_28","073_6_28","JHN","6","28","28","Sai suka tambaye shi suka ce, “Me za mu yi don mu aikata ayyukan da Allah yake so?” ");
INSERT INTO hausa_vpl VALUES ("JN6_29","073_6_29","JHN","6","29","29","Yesu ya amsa, “Aikin Allah shi ne, a gaskata da wanda ya aiko.” ");
INSERT INTO hausa_vpl VALUES ("JN6_30","073_6_30","JHN","6","30","30","Sai suka tambaye shi, “Wace abin banmamaki ce za ka yi don mu gani mu kuwa gaskata ka? Me za ka yi? ");
INSERT INTO hausa_vpl VALUES ("JN6_31","073_6_31","JHN","6","31","31","Kakannin-kakanninmu sun ci Manna a hamada; kamar yadda yake a rubuce, ‘Ya ba su burodi daga sama su ci.’” ");
INSERT INTO hausa_vpl VALUES ("JN6_32","073_6_32","JHN","6","32","32","Yesu ya ce musu, “Gaskiya nake gaya muku, ba Musa ne ya ba ku burodi daga sama ba, sai dai Ubana ne yake ba ku burodi na gaskiya daga sama. ");
INSERT INTO hausa_vpl VALUES ("JN6_33","073_6_33","JHN","6","33","33","Gama burodin Allah shi ne wanda yake saukowa daga sama, yana kuma ba wa duniya rai.” ");
INSERT INTO hausa_vpl VALUES ("JN6_34","073_6_34","JHN","6","34","34","Sai suka ce, “Ranka yă daɗe, daga yanzu ka dinga ba mu wannan burodi.” ");
INSERT INTO hausa_vpl VALUES ("JN6_35","073_6_35","JHN","6","35","35","Sa’an nan Yesu ya furta cewa, “Ni ne burodin rai. Wanda ya zo wurina ba zai taɓa jin yunwa ba, wanda kuma ya gaskata da ni ba zai taɓa jin ƙishirwa ba. ");
INSERT INTO hausa_vpl VALUES ("JN6_36","073_6_36","JHN","6","36","36","Amma kamar yadda na faɗa muku, kun gan ni duk da haka ba ku gaskata ba. ");
INSERT INTO hausa_vpl VALUES ("JN6_37","073_6_37","JHN","6","37","37","Duk waɗanda Uba ya ba ni za su zo wurina, kuma duk wanda ya zo wurina ba zan kore shi ba ko kaɗan. ");
INSERT INTO hausa_vpl VALUES ("JN6_38","073_6_38","JHN","6","38","38","Gama na sauko daga sama ba don in cika nufin kaina ba sai dai don in cika nufin shi wanda ya aiko ni. ");
INSERT INTO hausa_vpl VALUES ("JN6_39","073_6_39","JHN","6","39","39","Nufin wanda ya aiko ni kuwa shi ne, kada in yar da ko ɗaya daga cikin duk waɗanda ya ba ni, sai dai in tashe su a rana ta ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("JN6_40","073_6_40","JHN","6","40","40","Gama nufin Ubana shi ne, duk wanda yake duban Ɗan, ya kuma gaskata shi zai sami rai madawwami, ni kuwa zan tashe shi a rana ta ƙarshe.” ");
INSERT INTO hausa_vpl VALUES ("JN6_41","073_6_41","JHN","6","41","41","Da jin haka, Yahudawa suka fara gunaguni a kansa, domin ya ce, “Ni ne burodin da ya sauka daga sama.” ");
INSERT INTO hausa_vpl VALUES ("JN6_42","073_6_42","JHN","6","42","42","Suka ce, “Kai, wannan ba Yesu ba ne, ɗan Yusuf, wanda mahaifinsa da mahaifiyarsa duk mun san su? Yaya yanzu zai ce, ‘Na sauko daga sama?’ ” ");
INSERT INTO hausa_vpl VALUES ("JN6_43","073_6_43","JHN","6","43","43","Sai Yesu ya amsa ya ce, “Ku daina gunaguni a junanku. ");
INSERT INTO hausa_vpl VALUES ("JN6_44","073_6_44","JHN","6","44","44","Ba mai iya zuwa wurina, sai dai in Uban da ya aiko ni ya jawo shi, ni kuwa zan tashe shi a rana ta ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("JN6_45","073_6_45","JHN","6","45","45","A rubuce yake a cikin Annabawa cewa, ‘Allah zai koyar da dukansu.’Duk wanda ya saurari Uba, ya kuma koyi daga wurinsa, zai zo wurina. ");
INSERT INTO hausa_vpl VALUES ("JN6_46","073_6_46","JHN","6","46","46","Ba wanda ya taɓa ganin Uban, sai shi wanda ya zo daga Allah; shi ne kaɗai ya taɓa ganin Uban. ");
INSERT INTO hausa_vpl VALUES ("JN6_47","073_6_47","JHN","6","47","47","Gaskiya nake gaya muku, wanda ya gaskata yana da rai madawwami. ");
INSERT INTO hausa_vpl VALUES ("JN6_48","073_6_48","JHN","6","48","48","Ni ne burodin rai. ");
INSERT INTO hausa_vpl VALUES ("JN6_49","073_6_49","JHN","6","49","49","Kakannin-kakanninku sun ci Manna a hamada, duk da haka suka mutu. ");
INSERT INTO hausa_vpl VALUES ("JN6_50","073_6_50","JHN","6","50","50","Amma ga burodin da ya sauko daga sama, wanda mutum zai iya ci, ba zai kuma mutu ba. ");
INSERT INTO hausa_vpl VALUES ("JN6_51","073_6_51","JHN","6","51","51","Ni ne burodin rai mai saukowa daga sama. Duk wanda ya ci wannan burodi, zai rayu har abada. Wannan burodin shi ne jikina, da zan bayar don duniya ta sami rai.” ");
INSERT INTO hausa_vpl VALUES ("JN6_52","073_6_52","JHN","6","52","52","Sai Yahudawa suka fara gardama mai tsanani a junansu suna cewa, “Yaya wannan mutum zai ba mu naman jikinsa mu ci?” ");
INSERT INTO hausa_vpl VALUES ("JN6_53","073_6_53","JHN","6","53","53","Sai Yesu ya ce musu, “Gaskiya nake gaya muku, sai kun ci naman jikin Ɗan Mutum kuka kuma sha jininsa, ba za ku kasance da rai a cikinku ba. ");
INSERT INTO hausa_vpl VALUES ("JN6_54","073_6_54","JHN","6","54","54","Duk wanda ya ci naman jikina ya kuma sha jinina, yana da rai madawwami. Ni kuwa zan tashe shi a rana ta ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("JN6_55","073_6_55","JHN","6","55","55","Gama naman jikina abinci ne na gaskiya jinina kuma abin sha ne na gaskiya. ");
INSERT INTO hausa_vpl VALUES ("JN6_56","073_6_56","JHN","6","56","56","Duk wanda ya ci naman jikina ya kuma sha jinina, yana cikina, ni kuma ina cikinsa. ");
INSERT INTO hausa_vpl VALUES ("JN6_57","073_6_57","JHN","6","57","57","Kamar dai yadda Uba mai rai ya aiko ni, ina kuma rayuwa ta saboda shi, haka ma wanda yake ni ne abincinsa zai rayu saboda ni. ");
INSERT INTO hausa_vpl VALUES ("JN6_58","073_6_58","JHN","6","58","58","Wannan shi ne burodin da ya sauko daga sama. Kakannin-kakanninku sun ci Manna suka kuma mutu, amma duk wanda yake cin wannan burodi zai rayu har abada.” ");
INSERT INTO hausa_vpl VALUES ("JN6_59","073_6_59","JHN","6","59","59","Ya faɗi wannan ne lokacin da yake koyarwa a cikin majami’a a Kafarnahum. ");
INSERT INTO hausa_vpl VALUES ("JN6_60","073_6_60","JHN","6","60","60","Da jin haka, da yawa daga cikin almajiransa suka ce, “Wannan koyarwa tana da wuya. Wa zai iya yarda da ita?” ");
INSERT INTO hausa_vpl VALUES ("JN6_61","073_6_61","JHN","6","61","61","Da yake ya san almajiransa suna gunaguni game da wannan, sai Yesu ya ce musu, “Wannan ya ɓata muku rai ne? ");
INSERT INTO hausa_vpl VALUES ("JN6_62","073_6_62","JHN","6","62","62","Me za ku ce ke nan, in kuka gan Ɗan Mutum yana hawa zuwa inda yake dā! ");
INSERT INTO hausa_vpl VALUES ("JN6_63","073_6_63","JHN","6","63","63","Ruhu ne yake ba da rai; jikin kam, ba ya amfana kome. Kalmomin da na faɗa muku, Ruhu ne, da kuma rai. ");
INSERT INTO hausa_vpl VALUES ("JN6_64","073_6_64","JHN","6","64","64","Duk da haka akwai waɗansunku da ba su gaskata ba.” Gama Yesu ya sani tun farko, waɗanda ba su gaskata ba, da kuma wanda zai bashe shi. ");
INSERT INTO hausa_vpl VALUES ("JN6_65","073_6_65","JHN","6","65","65","Ya ci gaba da cewa, “Shi ya sa na faɗa muku cewa ba mai iya zuwa wurina, sai dai Uba ya yardar masa.” ");
INSERT INTO hausa_vpl VALUES ("JN6_66","073_6_66","JHN","6","66","66","Daga wannan lokaci da yawa daga cikin almajiransa suka ja da baya, suka daina bin sa. ");
INSERT INTO hausa_vpl VALUES ("JN6_67","073_6_67","JHN","6","67","67","Sai Yesu ya tambayi Sha Biyun, “Ku ma za ku tafi ne?” ");
INSERT INTO hausa_vpl VALUES ("JN6_68","073_6_68","JHN","6","68","68","Sai Siman Bitrus ya amsa ya ce, “Ubangiji wajen wa za mu tafi? Kai ne da kalmomin rai madawwami. ");
INSERT INTO hausa_vpl VALUES ("JN6_69","073_6_69","JHN","6","69","69","Mun gaskata mun kuma san cewa kai ne Mai Tsarkin nan na Allah.” ");
INSERT INTO hausa_vpl VALUES ("JN6_70","073_6_70","JHN","6","70","70","Sai Yesu ya amsa ya ce, “Ba ni na zaɓe ku Sha Biyu ba? Amma ɗayanku Iblis ne!” ");
INSERT INTO hausa_vpl VALUES ("JN6_71","073_6_71","JHN","6","71","71","(Yana nufin Yahuda, ɗan Siman Iskariyot, wanda, ko da yake ɗaya ne cikin Sha Biyun, zai bashe shi daga baya.) ");
INSERT INTO hausa_vpl VALUES ("JN7_1","073_7_1","JHN","7","1","1","Bayan wannan, sai Yesu ya yi ta zagawa a cikin Galili, da ganga bai yarda yă je Yahudiya ba domin Yahudawa a can suna nema su kashe shi. ");
INSERT INTO hausa_vpl VALUES ("JN7_2","073_7_2","JHN","7","2","2","Amma sa’ad da Bikin Tabanakul na Yahudawa ya yi kusa, ");
INSERT INTO hausa_vpl VALUES ("JN7_3","073_7_3","JHN","7","3","3","sai ’yan’uwan Yesu suka ce masa, “Ya kamata ka bar nan ka tafi Yahudiya, don almajiranka su ga ayyukan banmamaki da kake yi. ");
INSERT INTO hausa_vpl VALUES ("JN7_4","073_7_4","JHN","7","4","4","Ba wanda yake so a san shi da zai yi abu a ɓoye. Da yake kana yin waɗannan abubuwa, sai ka nuna kanka ga duniya.” ");
INSERT INTO hausa_vpl VALUES ("JN7_5","073_7_5","JHN","7","5","5","Domin ko ’yan’uwansa ma ba su gaskata da shi ba. ");
INSERT INTO hausa_vpl VALUES ("JN7_6","073_7_6","JHN","7","6","6","Saboda haka Yesu ya ce musu, “Lokacina bai yi ba tukuna; amma a gare ku kowane lokaci daidai ne. ");
INSERT INTO hausa_vpl VALUES ("JN7_7","073_7_7","JHN","7","7","7","Duniya ba za tă iya ƙinku ba, amma ni take ƙi domin ina shaida cewa ayyukanta mugaye ne. ");
INSERT INTO hausa_vpl VALUES ("JN7_8","073_7_8","JHN","7","8","8","Ku ku tafi Bikin, ba zan haura zuwa wannan Bikin ba yanzu, domin lokacina bai yi ba tukuna.” ");
INSERT INTO hausa_vpl VALUES ("JN7_9","073_7_9","JHN","7","9","9","Da ya faɗa haka, sai ya dakata a Galili. ");
INSERT INTO hausa_vpl VALUES ("JN7_10","073_7_10","JHN","7","10","10","Amma fa, bayan ’yan’uwansa suka tafi Bikin, shi ma ya tafi, ba a fili ba, amma a ɓoye. ");
INSERT INTO hausa_vpl VALUES ("JN7_11","073_7_11","JHN","7","11","11","A Bikin kuwa, Yahudawa suka yi ta nemansa, suna cewa, “Ina mutumin yake?” ");
INSERT INTO hausa_vpl VALUES ("JN7_12","073_7_12","JHN","7","12","12","A cikin taron kuwa aka yi ta raɗe-raɗe game da shi. Waɗansu suka ce, “Shi mutumin kirki ne.” Waɗansu kuwa suka ce, “A’a, ai, ruɗin mutane yake.” ");
INSERT INTO hausa_vpl VALUES ("JN7_13","073_7_13","JHN","7","13","13","Amma ba wanda ya ce kome a fili game da shi don tsoron Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("JN7_14","073_7_14","JHN","7","14","14","Sai bayan da aka kai tsakiyar Bikin, sa’an nan Yesu ya haura zuwa filin haikali ya fara koyarwa. ");
INSERT INTO hausa_vpl VALUES ("JN7_15","073_7_15","JHN","7","15","15","Yahudawa suka yi mamaki suna tambaya, “Yaya wannan mutum ya sami wannan sani haka ba tare da ya yi wani karatu ba?” ");
INSERT INTO hausa_vpl VALUES ("JN7_16","073_7_16","JHN","7","16","16","Yesu ya amsa ya ce, “Koyarwata ba tawa ba ce, ta fito ne daga wurin wanda ya aiko ni. ");
INSERT INTO hausa_vpl VALUES ("JN7_17","073_7_17","JHN","7","17","17","Duk wanda ya zaɓi yin nufin Allah, zai gane ko koyarwata daga Allah ce, ko kuwa don kaina ne nake magana. ");
INSERT INTO hausa_vpl VALUES ("JN7_18","073_7_18","JHN","7","18","18","Mai magana don kansa, neman ɗaukakar kansa yake yi. Amma mai neman ɗaukakar wanda ya aiko shi, shi ne mai gaskiya, ba kuwa rashin gaskiya a gare shi. ");
INSERT INTO hausa_vpl VALUES ("JN7_19","073_7_19","JHN","7","19","19","Ashe, ba Musa ba ne ya ba ku Doka? Duk da haka ba ko ɗayanku da yake kiyaye Dokar. Me ya sa kuke nema ku kashe ni?” ");
INSERT INTO hausa_vpl VALUES ("JN7_20","073_7_20","JHN","7","20","20","Taron suka amsa suka ce, “Kana da aljani, wane ne yake so yă kashe ka?” ");
INSERT INTO hausa_vpl VALUES ("JN7_21","073_7_21","JHN","7","21","21","Yesu ya ce musu, “Na yi abin banmamaki ɗaya, dukanku kuwa kuka yi mamaki. ");
INSERT INTO hausa_vpl VALUES ("JN7_22","073_7_22","JHN","7","22","22","Duk da haka, domin Musa ya bar muku kaciya (ko da yake a gaskiya, ba daga wurin Musa ne ya fito ba, sai dai daga wurin kakannin kakanninku), ga shi kuna yin wa yaro kaciya a ranar Asabbaci. ");
INSERT INTO hausa_vpl VALUES ("JN7_23","073_7_23","JHN","7","23","23","To, in za a iya yin wa yaro kaciya a ranar Asabbaci don kada a karya dokar Musa, don me kuke fushi da ni saboda na warkar da mutum a ranar Asabbaci? ");
INSERT INTO hausa_vpl VALUES ("JN7_24","073_7_24","JHN","7","24","24","Ku daina yin shari’a bisa ga ganin ido, sai dai ku yi shari’a bisa ga adalci.” ");
INSERT INTO hausa_vpl VALUES ("JN7_25","073_7_25","JHN","7","25","25","A nan ne fa waɗansu mutane daga Urushalima suka fara tambaya suna cewa, “Ashe, ba wannan mutum ne suke nema su kashe ba? ");
INSERT INTO hausa_vpl VALUES ("JN7_26","073_7_26","JHN","7","26","26","Ga shi nan yana magana a fili, su kuma ba su ce masa uffam ba. Ko hukumomi sun yarda cewa shi ne Kiristi? ");
INSERT INTO hausa_vpl VALUES ("JN7_27","073_7_27","JHN","7","27","27","Mun dai san inda mutumin nan ya fito; amma sa’ad da Kiristi ya zo ba wanda zai san inda ya fito.” ");
INSERT INTO hausa_vpl VALUES ("JN7_28","073_7_28","JHN","7","28","28","Yesu yana cikin koyarwa a filin haikali ke nan, sai ya ɗaga murya ya ce, “I, kun san ni, kun kuma san inda na fito. Ban zo don kaina ba, sai dai shi da ya aiko ni mai gaskiya ne. Ba ku san shi ba, ");
INSERT INTO hausa_vpl VALUES ("JN7_29","073_7_29","JHN","7","29","29","amma na san shi, domin ni daga wurinsa ne, kuma shi ya aiko ni.” ");
INSERT INTO hausa_vpl VALUES ("JN7_30","073_7_30","JHN","7","30","30","Da jin haka, sai suka yi ƙoƙari su kama shi, sai dai ba wanda ya taɓa shi, don lokacinsa bai yi ba tukuna. ");
INSERT INTO hausa_vpl VALUES ("JN7_31","073_7_31","JHN","7","31","31","Duk da haka, da yawa a cikin taron suka ba da gaskiya gare shi. Suka ce, “Sa’ad da Kiristi ya zo, zai yi abubuwan banmamaki fiye da na wannan mutum ne?” ");
INSERT INTO hausa_vpl VALUES ("JN7_32","073_7_32","JHN","7","32","32","Farisiyawa suka ji taron suna raɗe-raɗen waɗannan abubuwa game da shi. Sai manyan firistoci da Farisiyawa suka aiki masu gadin haikalin su kama shi. ");
INSERT INTO hausa_vpl VALUES ("JN7_33","073_7_33","JHN","7","33","33","Sai Yesu ya ce, “Ina tare da ku na ɗan ƙanƙanin lokaci ne kawai, sa’an nan zan koma wurin wanda ya aiko ni. ");
INSERT INTO hausa_vpl VALUES ("JN7_34","073_7_34","JHN","7","34","34","Za ku neme ni, amma ba za ku same ni ba; inda nake kuwa, ba za ku iya zuwa ba.” ");
INSERT INTO hausa_vpl VALUES ("JN7_35","073_7_35","JHN","7","35","35","Sai Yahudawa suka ce wa juna, “Ina mutumin nan yake niyyar tafiya da ba za mu iya samunsa ba? Zai je wurin mutanenmu da suke zaune warwatse a cikin Hellenawa, yă kuma koya wa Hellenawa ne? ");
INSERT INTO hausa_vpl VALUES ("JN7_36","073_7_36","JHN","7","36","36","Me yake nufi da ya ce, ‘Za ku neme ni, amma ba za ku same ni ba,’ da kuma ‘Inda nake, ba za ku iya zuwa ba’?” ");
INSERT INTO hausa_vpl VALUES ("JN7_37","073_7_37","JHN","7","37","37","A rana ta ƙarshe kuma mafi girma ta Bikin, Yesu ya tsaya ya yi magana da babbar murya ya ce, “Duk mai jin ƙishirwa, yă zo wurina yă sha. ");
INSERT INTO hausa_vpl VALUES ("JN7_38","073_7_38","JHN","7","38","38","Duk wanda ya gaskata da ni, kamar yadda Nassi ya ce, kogunan ruwa masu rai za su gudana daga cikinsa.” ");
INSERT INTO hausa_vpl VALUES ("JN7_39","073_7_39","JHN","7","39","39","Da wannan yana nufin Ruhu ke nan, wanda waɗanda suka gaskata da shi za su karɓa daga baya. Har yă zuwa wannan lokaci ba a ba da Ruhu ba tukuna, da yake ba a riga an ɗaukaka Yesu ba. ");
INSERT INTO hausa_vpl VALUES ("JN7_40","073_7_40","JHN","7","40","40","Da jin kalmominsa, waɗansu mutane suka ce, “Ba shakka, mutumin nan shi ne Annabin.” ");
INSERT INTO hausa_vpl VALUES ("JN7_41","073_7_41","JHN","7","41","41","Waɗansu suka ce, “Shi ne Kiristi.” Waɗansu har wa yau suka ce, “Yaya Kiristi zai fito daga Galili? ");
INSERT INTO hausa_vpl VALUES ("JN7_42","073_7_42","JHN","7","42","42","Nassi bai ce Kiristi zai fito daga zuriyar Dawuda, daga kuma Betlehem garin da Dawuda ya zauna ba?” ");
INSERT INTO hausa_vpl VALUES ("JN7_43","073_7_43","JHN","7","43","43","Sai mutanen suka rabu saboda Yesu. ");
INSERT INTO hausa_vpl VALUES ("JN7_44","073_7_44","JHN","7","44","44","Waɗansu suka so su kama shi, sai dai ba wanda ya taɓa shi. ");
INSERT INTO hausa_vpl VALUES ("JN7_45","073_7_45","JHN","7","45","45","A ƙarshe masu gadin haikali suka koma wurin manyan firistocin da Farisiyawa, waɗanda suka tambaye su cewa, “Don me ba ku kawo shi nan ba?” ");
INSERT INTO hausa_vpl VALUES ("JN7_46","073_7_46","JHN","7","46","46","Sai masu gadin suka ce, “Kai, babu wanda ya taɓa magana kamar wannan mutum.” ");
INSERT INTO hausa_vpl VALUES ("JN7_47","073_7_47","JHN","7","47","47","Sai Farisiyawa suka amsa cikin fushi suka ce, “Af, kuna nufi har da ku ma ya ruɗe ku ke nan? ");
INSERT INTO hausa_vpl VALUES ("JN7_48","073_7_48","JHN","7","48","48","Akwai wani daga cikin masu mulki ko cikin Farisiyawan da ya gaskata da shi? ");
INSERT INTO hausa_vpl VALUES ("JN7_49","073_7_49","JHN","7","49","49","A’a! Sai dai wannan taron da ba su san kome game da Doka ba, la’anannu ne.” ");
INSERT INTO hausa_vpl VALUES ("JN7_50","073_7_50","JHN","7","50","50","Nikodimus, wanda ya je wurin Yesu dā, wanda kuma yake ɗayansu ya ce, ");
INSERT INTO hausa_vpl VALUES ("JN7_51","073_7_51","JHN","7","51","51","“Ashe, dokarmu takan hukunta mutum ba tare da an fara ji daga bakinsa game da abin da yake yi ba?” ");
INSERT INTO hausa_vpl VALUES ("JN7_52","073_7_52","JHN","7","52","52","Sai suka amsa suka ce, “Kai ma daga Galili ne? Bincika ka gani, za ka iske cewa ba annabin da zai fito daga Galili.” ");
INSERT INTO hausa_vpl VALUES ("JN7_53","073_7_53","JHN","7","53","53","Sai kowannensu ya koma gidansa. ");
INSERT INTO hausa_vpl VALUES ("JN8_1","073_8_1","JHN","8","1","1","Amma Yesu ya tafi Dutsen Zaitun. ");
INSERT INTO hausa_vpl VALUES ("JN8_2","073_8_2","JHN","8","2","2","Da sassafe ya sāke bayyana a filin haikali, inda dukan mutane suka taru kewaye da shi, sai ya zauna don yă koya musu. ");
INSERT INTO hausa_vpl VALUES ("JN8_3","073_8_3","JHN","8","3","3","Sai malaman dokoki da Farisiyawa suka kawo wata macen da aka kama a zina. Suka sa ta tsaya a gaban taron ");
INSERT INTO hausa_vpl VALUES ("JN8_4","073_8_4","JHN","8","4","4","suka kuma ce wa Yesu, “Malam, an kama wannan mace tana zina. ");
INSERT INTO hausa_vpl VALUES ("JN8_5","073_8_5","JHN","8","5","5","A cikin Doka Musa ya umarce mu, mu jajjefe irin waɗannan mata. To, me ka ce?” ");
INSERT INTO hausa_vpl VALUES ("JN8_6","073_8_6","JHN","8","6","6","Sun yi wannan tambaya ce don su sa masa tarko, don su sami hanyar zarge shi. Amma Yesu ya sunkuya ya fara rubutu a ƙasa da yatsarsa. ");
INSERT INTO hausa_vpl VALUES ("JN8_7","073_8_7","JHN","8","7","7","Da suka ci gaba da yin masa tambayoyi, sai ya miƙe tsaye ya ce musu, “In da wani a cikinku da ba shi da zunubi, sai yă fara jifanta da dutse.” ");
INSERT INTO hausa_vpl VALUES ("JN8_8","073_8_8","JHN","8","8","8","Sai ya sāke sunkuyawa ya kuma yi rubutu a ƙasa. ");
INSERT INTO hausa_vpl VALUES ("JN8_9","073_8_9","JHN","8","9","9","Da jin haka, waɗanda suka ji sai suka fara tashi daga wurin ɗaya-ɗaya, tun daga babbansu har ya zuwa ƙaraminsu, sai da aka bar Yesu kaɗai, tare da macen tsaye a wurin. ");
INSERT INTO hausa_vpl VALUES ("JN8_10","073_8_10","JHN","8","10","10","Sai Yesu ya miƙe tsaye ya tambaye ta ya ce, “Mace, ina suke? Ba wanda ya hukunta ki?” ");
INSERT INTO hausa_vpl VALUES ("JN8_11","073_8_11","JHN","8","11","11","Ta ce, “Ba kowa, ranka yă daɗe.” Sai Yesu ya ce, “Haka ni ma ban hukunta ki ba. Ki tafi, ki daina rayuwar zunubi.” ");
INSERT INTO hausa_vpl VALUES ("JN8_12","073_8_12","JHN","8","12","12","Sa’ad da Yesu ya sāke magana da mutanen, sai ya ce, “Ni ne hasken duniya. Duk wanda ya bi ni ba zai yi tafiya cikin duhu ba, sai dai yă sami hasken rayuwa.” ");
INSERT INTO hausa_vpl VALUES ("JN8_13","073_8_13","JHN","8","13","13","Sai Farisiyawa suka tambaye shi suka ce, “Ga kai dai, kana yi wa kanka shaida, shaidarka kuwa ba tabbatacciya ba ce.” ");
INSERT INTO hausa_vpl VALUES ("JN8_14","073_8_14","JHN","8","14","14","Sai Yesu ya amsa ya ce, “Ko na shaidi kaina, ai, shaidata tabbatacciya ce, gama na san inda na fito da kuma inda za ni. Amma ku ba ku san inda na fito ko inda za ni ba. ");
INSERT INTO hausa_vpl VALUES ("JN8_15","073_8_15","JHN","8","15","15","Kuna shari’a bisa ga ma’aunin mutane; ni kuwa ba na yin wa kowa shari’a. ");
INSERT INTO hausa_vpl VALUES ("JN8_16","073_8_16","JHN","8","16","16","Amma ko da zan yi shari’a, shari’ata daidai ce, don ba ni kaɗai ba ne. Ina tare da Uba da ya aiko ni. ");
INSERT INTO hausa_vpl VALUES ("JN8_17","073_8_17","JHN","8","17","17","A cikin Dokarku a rubuce yake cewa shaidar mutum biyu tabbatacciya ce. ");
INSERT INTO hausa_vpl VALUES ("JN8_18","073_8_18","JHN","8","18","18","Ni ne nake shaidar kaina, Uba da ya aiko ni kuma yana shaidata.” ");
INSERT INTO hausa_vpl VALUES ("JN8_19","073_8_19","JHN","8","19","19","Suka tambaye shi suka ce, “Ina Uban nan naka?” Sai Yesu ya ce, “Ba ku san ni ko Ubana ba. Da kun san ni, da za ku san Ubana ma.” ");
INSERT INTO hausa_vpl VALUES ("JN8_20","073_8_20","JHN","8","20","20","Ya faɗi waɗannan kalmomi ne yayinda yake koyarwa a filin haikali, kusa da inda ake ajiye baye-baye. Duk da haka ba wanda ya kama shi, domin lokacinsa bai yi ba tukuna. ");
INSERT INTO hausa_vpl VALUES ("JN8_21","073_8_21","JHN","8","21","21","Har wa yau Yesu ya sāke ce musu, “Zan tafi, za ku kuwa neme ni, za ku kuma mutu cikin zunubinku. Inda za ni, ba za ku iya zuwa ba.” ");
INSERT INTO hausa_vpl VALUES ("JN8_22","073_8_22","JHN","8","22","22","Wannan ya sa Yahudawa suka yi tambaya suka ce, “Zai kashe kansa ne? Shi ya sa yake cewa, ‘Inda za ni, ba za ku iya zuwa ba’?” ");
INSERT INTO hausa_vpl VALUES ("JN8_23","073_8_23","JHN","8","23","23","Amma ya ci gaba da cewa, “Ku daga ƙasa kuke; ni kuwa daga bisa ne. Ku na duniyan nan ne; ni kuwa ba na duniyan nan ba ne. ");
INSERT INTO hausa_vpl VALUES ("JN8_24","073_8_24","JHN","8","24","24","Na gaya muku cewa za ku mutu cikin zunubanku; in ba ku gaskata cewa ni ne wanda na ce nake ba, lalle za ku mutu cikin zunubanku.” ");
INSERT INTO hausa_vpl VALUES ("JN8_25","073_8_25","JHN","8","25","25","Suka ce, “Wane ne kai?” Sai Yesu ya amsa ya ce, “Ni ne wannan da na sha faɗi muku. ");
INSERT INTO hausa_vpl VALUES ("JN8_26","073_8_26","JHN","8","26","26","Ina da abubuwa masu yawa da zan faɗa game ku in kuma yi muku shari’a. Amma wanda ya aiko ni mai aminci ne, abin da kuma na ji daga gare shi, shi nake gaya wa duniya.” ");
INSERT INTO hausa_vpl VALUES ("JN8_27","073_8_27","JHN","8","27","27","Ba su gane cewa yana yin musu magana game da Ubansa ba ne. ");
INSERT INTO hausa_vpl VALUES ("JN8_28","073_8_28","JHN","8","28","28","Saboda haka Yesu ya ce, “Sa’ad da kuka ɗaga Ɗan Mutum, a sa’an nan ne za ku san cewa ni ne wannan da na ce nake. Ni kuwa ba na yin kome ni kaɗai, sai in dai faɗi abin da Uba ya koya mini. ");
INSERT INTO hausa_vpl VALUES ("JN8_29","073_8_29","JHN","8","29","29","Wanda kuwa ya aiko ni yana tare da ni; bai bar ni ni kaɗai ba, domin kullum ina aikata abin da ya gamshe shi.” ");
INSERT INTO hausa_vpl VALUES ("JN8_30","073_8_30","JHN","8","30","30","Sa’ad da yake cikin magana, da yawa suka ba da gaskiya gare shi. ");
INSERT INTO hausa_vpl VALUES ("JN8_31","073_8_31","JHN","8","31","31","Sai Yesu ya ce wa Yahudawan da suka gaskata da shi, “In dai kun riƙe koyarwata, ku almajiraina ne da gaske. ");
INSERT INTO hausa_vpl VALUES ("JN8_32","073_8_32","JHN","8","32","32","Sa’an nan za ku san gaskiya, gaskiyar kuwa za tă ’yantar da ku.” ");
INSERT INTO hausa_vpl VALUES ("JN8_33","073_8_33","JHN","8","33","33","Sai suka amsa masa suka ce, “Ai, mu zuriyar Ibrahim ne kuma ba mu taɓa bauta wa kowa ba. Yaya za ka ce za a ’yantar da mu?” ");
INSERT INTO hausa_vpl VALUES ("JN8_34","073_8_34","JHN","8","34","34","Yesu ya amsa ya ce, “Gaskiya nake gaya muku, duk mai yin zunubi bawan zunubi ne. ");
INSERT INTO hausa_vpl VALUES ("JN8_35","073_8_35","JHN","8","35","35","Bawa dai ba shi da wurin zama na ɗinɗinɗin a cikin iyali, amma ɗa na gida ne har abada. ");
INSERT INTO hausa_vpl VALUES ("JN8_36","073_8_36","JHN","8","36","36","Saboda haka in Ɗan ya ’yantar da ku, za ku ’yantu da gaske. ");
INSERT INTO hausa_vpl VALUES ("JN8_37","073_8_37","JHN","8","37","37","Na dai san ku zuriyar Ibrahim ne. Duk da haka kuna shiri ku kashe ni, don maganata ba ta da wurin zama a cikinku. ");
INSERT INTO hausa_vpl VALUES ("JN8_38","073_8_38","JHN","8","38","38","Ina faɗi muku abin da na gani a wurin Ubana, ku kuwa kuna yin abin da kuka ji daga wurin ubanku.” ");
INSERT INTO hausa_vpl VALUES ("JN8_39","073_8_39","JHN","8","39","39","Suka ce, “To, ai, Ibrahim ne mahaifinmu.” Yesu ya ce, “Da ku ’ya’yan Ibrahim ne, da za ku aikata abubuwan da Ibrahim ya yi. ");
INSERT INTO hausa_vpl VALUES ("JN8_40","073_8_40","JHN","8","40","40","Ga shi kun ƙudura, sai kun kashe ni, ni mutumin da ya faɗa muku gaskiyar da na ji daga Allah. Ibrahim bai yi irin waɗannan abubuwa ba. ");
INSERT INTO hausa_vpl VALUES ("JN8_41","073_8_41","JHN","8","41","41","Kuna yin abubuwan da ubanku yake yi ne.” Suka ce, “Mu fa ba shegu ba ne. Uba guda kaɗai da muke da shi, shi ne Allah kansa.” ");
INSERT INTO hausa_vpl VALUES ("JN8_42","073_8_42","JHN","8","42","42","Yesu ya ce musu, “Da Allah ne Ubanku, da kun ƙaunace ni, gama daga Allah na fito yanzu kuma ga ni nan. Ban zo saboda kaina ba, amma shi ne ya aiko ni. ");
INSERT INTO hausa_vpl VALUES ("JN8_43","073_8_43","JHN","8","43","43","Me ya sa ba kwa gane da maganata? Don ba kwa iya jin abin da nake faɗi. ");
INSERT INTO hausa_vpl VALUES ("JN8_44","073_8_44","JHN","8","44","44","Ku na ubanku ne, Iblis, kuna kuwa so ku aikata abin da ubanku yake so. Shi mai kisankai ne tun farko. Ba ruwansa da gaskiya, gama gaskiya ba ta cikinsa. Yayinda yake ƙarya, yana yin halinsa ne, gama shi maƙaryaci ne, uban ƙarairayi kuma. ");
INSERT INTO hausa_vpl VALUES ("JN8_45","073_8_45","JHN","8","45","45","Amma domin ina faɗin gaskiya, ba kwa gaskata! ");
INSERT INTO hausa_vpl VALUES ("JN8_46","073_8_46","JHN","8","46","46","Akwai waninku da zai iya haƙaƙƙewa na taɓa yin zunubi? In kuwa gaskiya na faɗa, me ya sa ba kwa gaskata ni? ");
INSERT INTO hausa_vpl VALUES ("JN8_47","073_8_47","JHN","8","47","47","Wanda yake na Allah, yakan ji abin da Allah yake faɗi. Abin da ya sa ba kwa jin sa kuwa shi ne don ku ba na Allah ba ne.” ");
INSERT INTO hausa_vpl VALUES ("JN8_48","073_8_48","JHN","8","48","48","Yahudawa suka amsa masa suka ce, “Aha, ai, gaskiyarmu da muka ce kai mutumin Samariya ne, kana kuma da aljani.” ");
INSERT INTO hausa_vpl VALUES ("JN8_49","073_8_49","JHN","8","49","49","Yesu ya ce, “Ni ba mai aljani ba ne, ni dai ina girmama Ubana, ku kuwa ba kwa girmama ni. ");
INSERT INTO hausa_vpl VALUES ("JN8_50","073_8_50","JHN","8","50","50","Ba na nema wa kaina ɗaukaka, amma akwai wani wanda yake neman mini, shi ne kuma alƙali. ");
INSERT INTO hausa_vpl VALUES ("JN8_51","073_8_51","JHN","8","51","51","Gaskiya nake gaya muku, duk wanda ya kiyaye maganata, ba zai ɗanɗana mutuwa ba sam.” ");
INSERT INTO hausa_vpl VALUES ("JN8_52","073_8_52","JHN","8","52","52","Da jin haka Yahudawa suka ce, “Tabɗi, yanzu kam mun san kana da aljani! Ibrahim ya mutu haka ma annabawa, ga shi kana cewa duk wanda ya kiyaye maganarka ba zai ɗanɗana mutuwa ba sam. ");
INSERT INTO hausa_vpl VALUES ("JN8_53","073_8_53","JHN","8","53","53","Ka fi Ibrahim mahaifinmu ne? Ya mutu, haka ma annabawa. Wa kake ɗauka kanka ne?” ");
INSERT INTO hausa_vpl VALUES ("JN8_54","073_8_54","JHN","8","54","54","Yesu ya amsa ya ce, “In ma na ɗaukaka kaina, ɗaukakata ba kome ba ce. Ubana, wanda kuke cewa shi ne Allahnku, shi ne wanda yake ɗaukaka ni. ");
INSERT INTO hausa_vpl VALUES ("JN8_55","073_8_55","JHN","8","55","55","Ko da yake ba ku san shi ba, ni dai na san shi. In kuwa na ce ban san shi ba, na zama maƙaryaci kamar ku ke nan, amma na san shi, kuma ina kiyaye maganarsa. ");
INSERT INTO hausa_vpl VALUES ("JN8_56","073_8_56","JHN","8","56","56","Mahaifinku Ibrahim ya yi farin ciki sosai yă sami ganin ranata; ya kuwa gan ta, ya yi murna.” ");
INSERT INTO hausa_vpl VALUES ("JN8_57","073_8_57","JHN","8","57","57","Sai Yahudawa suka ce masa, “Kai, shekarunka har yanzu ba su kai hamsin tukuna ba fa, har ka ga Ibrahim!” ");
INSERT INTO hausa_vpl VALUES ("JN8_58","073_8_58","JHN","8","58","58","Yesu ya amsa ya ce, “Gaskiya nake gaya muku, tun ba a haifi Ibrahim ba, ni ne!” ");
INSERT INTO hausa_vpl VALUES ("JN8_59","073_8_59","JHN","8","59","59","Da jin haka sai suka ɗebo duwatsu don su jajjefe shi, amma Yesu ya ɓuya, ya fita daga filin haikali. ");
INSERT INTO hausa_vpl VALUES ("JN9_1","073_9_1","JHN","9","1","1","Da Yesu yana tafiya, sai ya ga wani mutum wanda aka haifa makaho. ");
INSERT INTO hausa_vpl VALUES ("JN9_2","073_9_2","JHN","9","2","2","Sai almajiransa suka tambaye shi suka ce, “Rabbi, wane ne ya yi zunubi, mutumin ne, ko iyayensa, da ya sa aka haife shi makaho?” ");
INSERT INTO hausa_vpl VALUES ("JN9_3","073_9_3","JHN","9","3","3","Sai Yesu ya ce, “Ba don mutumin ko iyayensa sun yi zunubi ne ba, sai dai don a bayyana aikin Allah ne a rayuwarsa. ");
INSERT INTO hausa_vpl VALUES ("JN9_4","073_9_4","JHN","9","4","4","Muddin da sauran rana, dole mu yi aikin wanda ya aiko ni. Dare yana zuwa, sa’ad da ba wanda zai iya yin aiki. ");
INSERT INTO hausa_vpl VALUES ("JN9_5","073_9_5","JHN","9","5","5","Yayinda ina a cikin duniya, ni ne hasken duniya.” ");
INSERT INTO hausa_vpl VALUES ("JN9_6","073_9_6","JHN","9","6","6","Bayan ya faɗi haka, sai ya tofa miyau a ƙasa, ya kwaɓa laka da miyau ɗin, ya kuma shafa a idanun mutumin. ");
INSERT INTO hausa_vpl VALUES ("JN9_7","073_9_7","JHN","9","7","7","Ya ce masa, “Je ka, ka wanke a Tafkin Silowam” (kalman nan tana nufin “Aikakke”). Saboda haka mutumin ya tafi ya wanke, ya kuma dawo gida yana gani. ");
INSERT INTO hausa_vpl VALUES ("JN9_8","073_9_8","JHN","9","8","8","Maƙwabta da waɗanda suka saba ganinsa dā yana bara, suka ce, “Kai, ba wannan mutum ne ya saba zama yana bara ba?” ");
INSERT INTO hausa_vpl VALUES ("JN9_9","073_9_9","JHN","9","9","9","Waɗansu suka ce shi mana. Waɗansu kuwa suka ce, “A’a, ya dai yi kama da shi.” Amma shi ɗin ya ce, “Ƙwarai kuwa ni ne.” ");
INSERT INTO hausa_vpl VALUES ("JN9_10","073_9_10","JHN","9","10","10","Sai suka ce, “To, yaya aka yi idanunka suka buɗe?” ");
INSERT INTO hausa_vpl VALUES ("JN9_11","073_9_11","JHN","9","11","11","Ya amsa ya ce, “Mutumin da ake kira Yesu ne ya kwaɓa laka ya shafa mini a idanu. Ya ce mini in je Silowam in wanke. Na kuwa tafi, na wanke, sai na sami ganin gari.” ");
INSERT INTO hausa_vpl VALUES ("JN9_12","073_9_12","JHN","9","12","12","Suka tambaye shi suka ce, “Ina mutumin yake?” Ya ce, “Ban sani ba.” ");
INSERT INTO hausa_vpl VALUES ("JN9_13","073_9_13","JHN","9","13","13","Sai suka kawo mutumin da dā yake makaho wurin Farisiyawa. ");
INSERT INTO hausa_vpl VALUES ("JN9_14","073_9_14","JHN","9","14","14","To, a ranar da Yesu ya kwaɓa laka ya buɗe idanun mutumin ranar Asabbaci ce. ");
INSERT INTO hausa_vpl VALUES ("JN9_15","073_9_15","JHN","9","15","15","Saboda haka Farisiyawa suka tambaye shi yadda ya sami ganin gari. Mutumin ya amsa, “Ya shafa laka a idanuna, sai na wanke, ina kuwa gani.” ");
INSERT INTO hausa_vpl VALUES ("JN9_16","073_9_16","JHN","9","16","16","Sai waɗansu daga cikin Farisiyawa suka ce, “Mutumin nan ba daga Allah yake ba, don ba ya kiyaye ranar Asabbaci.” Amma waɗansu suka yi tambaya suka ce, “Yaya mutum mai zunubi zai yi irin abubuwan banmamaki haka?” Sai ra’ayinsu ya sha bamban. ");
INSERT INTO hausa_vpl VALUES ("JN9_17","073_9_17","JHN","9","17","17","A ƙarshe suka sāke koma ga makahon suka ce, “Kai fa, me ka gani game da shi? Idanunka ne fa ya buɗe.” Sai mutumin ya ce, “Tab, ai, shi annabi ne.” ");
INSERT INTO hausa_vpl VALUES ("JN9_18","073_9_18","JHN","9","18","18","Yahudawa dai ba su yarda cewa dā shi makaho ne ya kuma sami ganin gari ba, sai da suka kira iyayen mutumin. ");
INSERT INTO hausa_vpl VALUES ("JN9_19","073_9_19","JHN","9","19","19","Suka tambaye su, “Wannan ɗanku ne? Shi ne wanda kuka ce an haife shi makaho? To, ta yaya yake gani yanzu?” ");
INSERT INTO hausa_vpl VALUES ("JN9_20","073_9_20","JHN","9","20","20","Iyayen suka amsa suka ce, “Mun dai san shi ɗanmu ne, mun kuma san cewa an haife shi makaho. ");
INSERT INTO hausa_vpl VALUES ("JN9_21","073_9_21","JHN","9","21","21","Sai dai yadda yake gani yanzu, ko kuma wa ya buɗe idanunsa, ba mu sani ba. Ku tambaye shi. Ai, shi ba yaro ba ne, zai faɗa da bakinsa.” ");
INSERT INTO hausa_vpl VALUES ("JN9_22","073_9_22","JHN","9","22","22","Iyayensa sun faɗa haka ne saboda suna tsoron Yahudawa, gama Yahudawa sun riga sun yanke shawara cewa duk wanda ya yarda cewa Yesu shi ne Kiristi, za a kore shi daga majami’a. ");
INSERT INTO hausa_vpl VALUES ("JN9_23","073_9_23","JHN","9","23","23","Shi ya sa iyayensa suka ce, “Ai, shi ba yaro ba ne, ku tambaye shi.” ");
INSERT INTO hausa_vpl VALUES ("JN9_24","073_9_24","JHN","9","24","24","Sai suka sāke kiran mutumin nan da yake makaho a dā, suka ce masa, “Ka ɗaukaka Allah, mu kam, mun san mutumin nan mai zunubi ne.” ");
INSERT INTO hausa_vpl VALUES ("JN9_25","073_9_25","JHN","9","25","25","Sai ya amsa ya ce, “Ko shi mai zunubi ne ko babu, ni dai ban sani ba. Abu ɗaya fa na sani, dā ni makaho ne, amma yanzu ina gani!” ");
INSERT INTO hausa_vpl VALUES ("JN9_26","073_9_26","JHN","9","26","26","Sai suka tambaye suka ce, “Shin, me ya yi maka? Ta yaya ya buɗe idanunka?” ");
INSERT INTO hausa_vpl VALUES ("JN9_27","073_9_27","JHN","9","27","27","Ya amsa ya ce, “Na riga na gaya muku ba ku kuwa saurara ba. Don me kuke so ku sāke ji? Ko ku ma kuna so ku zama almajiransa ne?” ");
INSERT INTO hausa_vpl VALUES ("JN9_28","073_9_28","JHN","9","28","28","Sai suka hau shi da zagi suna cewa, “Kai ne dai almajirin mutumin! Mu almajiran Musa ne! ");
INSERT INTO hausa_vpl VALUES ("JN9_29","073_9_29","JHN","9","29","29","Mun dai san cewa Allah ya yi magana da Musa, amma wannan mutum ba mu san inda ya fito ba.” ");
INSERT INTO hausa_vpl VALUES ("JN9_30","073_9_30","JHN","9","30","30","Sai mutumin ya ce, “Cabɗi, yau ga abin mamaki! Ba ku san inda ya fito ba, ga shi kuwa ya buɗe idanuna. ");
INSERT INTO hausa_vpl VALUES ("JN9_31","073_9_31","JHN","9","31","31","Mun san cewa Allah ba ya sauraron masu zunubi. Yakan saurari mai tsoronsa mai aikata nufinsa. ");
INSERT INTO hausa_vpl VALUES ("JN9_32","073_9_32","JHN","9","32","32","Ba wanda ya taɓa ji cewa an buɗe idanun wanda aka haifa makaho. ");
INSERT INTO hausa_vpl VALUES ("JN9_33","073_9_33","JHN","9","33","33","Da mutumin nan ba daga Allah ba ne, da ba abin da zai iya yi.” ");
INSERT INTO hausa_vpl VALUES ("JN9_34","073_9_34","JHN","9","34","34","Sai suka amsa suka ce, “Kai da aka haifa cike da zunubi; za ka yi karambanin koyarwar da mu!” Sai suka kore shi. ");
INSERT INTO hausa_vpl VALUES ("JN9_35","073_9_35","JHN","9","35","35","Yesu ya ji labari cewa sun kore shi, da ya same shi kuwa, sai ya ce, “Ka gaskata da Ɗan Mutum?” ");
INSERT INTO hausa_vpl VALUES ("JN9_36","073_9_36","JHN","9","36","36","Sai mutumin ya amsa ya ce, “Ranka yă daɗe, wane ne shi? Gaya mini, don in gaskata da shi.” ");
INSERT INTO hausa_vpl VALUES ("JN9_37","073_9_37","JHN","9","37","37","Yesu ya ce, “Yanzu ka gan shi; tabbatacce ma, shi ne yake magana da kai.” ");
INSERT INTO hausa_vpl VALUES ("JN9_38","073_9_38","JHN","9","38","38","Sai mutumin ya ce, “Ubangiji, na gaskata,” ya kuma yi masa sujada. ");
INSERT INTO hausa_vpl VALUES ("JN9_39","073_9_39","JHN","9","39","39","Yesu ya ce, “Saboda shari’a ce na zo duniya nan, saboda makafi su sami ganin gari, waɗanda suke gani kuma su makance.” ");
INSERT INTO hausa_vpl VALUES ("JN9_40","073_9_40","JHN","9","40","40","Da Farisiyawan da suke tare da shi suka ji ya faɗi haka sai suka yi tambaya suka ce, “Mene? Mu ma makafi ne?” ");
INSERT INTO hausa_vpl VALUES ("JN9_41","073_9_41","JHN","9","41","41","Yesu ya ce, “Ai, da ku makafi ne ma, da ba ku da zunubi, amma da yake kun ce, kuna gani, zunubanku suna nan daram. ");
INSERT INTO hausa_vpl VALUES ("JN10_1","073_10_1","JHN","10","1","1","“Gaskiya nake gaya muku, mutumin da bai shiga inda ake ajiye garken tumaki ta ƙofa ba, amma ya hau ta katanga, ɓarawo ne, ɗan fashi kuma. ");
INSERT INTO hausa_vpl VALUES ("JN10_2","073_10_2","JHN","10","2","2","Mutumin da ya shiga ta ƙofa makiyayin tumakinsa ne. ");
INSERT INTO hausa_vpl VALUES ("JN10_3","073_10_3","JHN","10","3","3","Mai gadin yakan buɗe wa makiyayin ƙofa, tumakin kuma sukan saurari muryarsa. Yakan kira tumakinsa da suna, yă kuma fid da su waje. ");
INSERT INTO hausa_vpl VALUES ("JN10_4","073_10_4","JHN","10","4","4","Sa’ad da ya fitar da dukan nasa waje, sai ya ja gabansu, tumakinsa kuma sukan bi shi domin sun san muryarsa. ");
INSERT INTO hausa_vpl VALUES ("JN10_5","073_10_5","JHN","10","5","5","Amma ba za su taɓa bin baƙo ba; sai dai ma su guje masa don ba su san muryar baƙo ba.” ");
INSERT INTO hausa_vpl VALUES ("JN10_6","073_10_6","JHN","10","6","6","Yesu ya yi musu wannan misali, amma ba su fahimci abin da yake faɗa musu ba. ");
INSERT INTO hausa_vpl VALUES ("JN10_7","073_10_7","JHN","10","7","7","Saboda haka Yesu ya sāke cewa, “Gaskiya nake gaya muku, ni ne ƙofar tumakin. ");
INSERT INTO hausa_vpl VALUES ("JN10_8","073_10_8","JHN","10","8","8","Duk waɗanda suka riga ni zuwa ɓarayi ne, ’yan fashi kuma, amma tumakin ba su saurare su ba. ");
INSERT INTO hausa_vpl VALUES ("JN10_9","073_10_9","JHN","10","9","9","Ni ne ƙofar; duk wanda ya shiga ta wurina zai sami ceto. Zai riƙa shiga yă fita yă kuwa sami wurin kiwo. ");
INSERT INTO hausa_vpl VALUES ("JN10_10","073_10_10","JHN","10","10","10","Ɓarawo yakan zo don yă yi sata ne kawai da kisa da kuma ɓarna. Ni kuwa na zo ne don su sami rai, su kuma same shi a yalwace. ");
INSERT INTO hausa_vpl VALUES ("JN10_11","073_10_11","JHN","10","11","11","“Ni ne makiyayi mai kyau. Makiyayi mai kyau yakan ba da ransa domin tumakin. ");
INSERT INTO hausa_vpl VALUES ("JN10_12","073_10_12","JHN","10","12","12","Wanda aka ɗauko haya ba shi ne makiyayi mai tumakin ba. Saboda haka sa’ad da ya ga kyarkeci yana zuwa, sai yă sheƙa da gudu yă bar tumakin. Sai kyarkecin yă kai wa garken hari, yă kuma watsar da su. ");
INSERT INTO hausa_vpl VALUES ("JN10_13","073_10_13","JHN","10","13","13","Mutumin yakan gudu don shi ɗan haya ne kawai, bai kuwa damu da tumakin ba. ");
INSERT INTO hausa_vpl VALUES ("JN10_14","073_10_14","JHN","10","14","14","“Ni ne makiyayi mai kyau; na san tumakina, tumakina kuma sun san ni, ");
INSERT INTO hausa_vpl VALUES ("JN10_15","073_10_15","JHN","10","15","15","kamar yadda Uba ya san ni, ni kuma na san Uba, ina kuwa ba da raina domin tumakin. ");
INSERT INTO hausa_vpl VALUES ("JN10_16","073_10_16","JHN","10","16","16","Ina da waɗansu tumaki da ba na wannan garken ba ne. Dole ne in kawo su su ma. Za su saurari muryata, za su kasance garke guda ɗaya, makiyayi guda kuma. ");
INSERT INTO hausa_vpl VALUES ("JN10_17","073_10_17","JHN","10","17","17","Abin da ya sa Ubana yake ƙaunata ke nan, domin ina ba da raina, in ɗauko shi kuma. ");
INSERT INTO hausa_vpl VALUES ("JN10_18","073_10_18","JHN","10","18","18","Ba mai karɓe mini rai, ina dai ba da shi. Ina da iko in ba da shi, ina da iko in ɗauko shi kuma. Wannan umarni kuwa daga wurin Ubana na karɓo shi.” ");
INSERT INTO hausa_vpl VALUES ("JN10_19","073_10_19","JHN","10","19","19","Saboda waɗannan kalmomi fa, sai ɓaraka ta sāke shiga cikin Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("JN10_20","073_10_20","JHN","10","20","20","Da yawa daga cikinsu suka ce, “Yana da aljani, yana kuma hauka. Don me za ku saurare shi?” ");
INSERT INTO hausa_vpl VALUES ("JN10_21","073_10_21","JHN","10","21","21","Amma waɗansu suka ce, “Kai, waɗannan kalmomi ba na mai aljani ba ne. Anya, aljani yana iya buɗe idanun makaho?” ");
INSERT INTO hausa_vpl VALUES ("JN10_22","073_10_22","JHN","10","22","22","Bikin Miƙawa a Urushalima ya kewayo, lokacin sanyin hunturu ne kuwa. ");
INSERT INTO hausa_vpl VALUES ("JN10_23","073_10_23","JHN","10","23","23","Sai ga Yesu a filin haikali yana zagawa a Shirayin Solomon, ");
INSERT INTO hausa_vpl VALUES ("JN10_24","073_10_24","JHN","10","24","24","sai Yahudawa suka taru kewaye da shi, suka ce masa, “Har yaushe za ka bar mu da shakka? In kai ne Kiristin, ka faɗa mana a fili mana.” ");
INSERT INTO hausa_vpl VALUES ("JN10_25","073_10_25","JHN","10","25","25","Yesu ya amsa ya ce, “Na faɗa muku, amma ba ku gaskata ba. Ayyukan da nake yi cikin sunan Ubana su suke nuna ko wane ne ni. ");
INSERT INTO hausa_vpl VALUES ("JN10_26","073_10_26","JHN","10","26","26","Amma ba ku gaskata ba domin ku ba tumakina ba ne. ");
INSERT INTO hausa_vpl VALUES ("JN10_27","073_10_27","JHN","10","27","27","Tumakina sukan saurari muryata; na sansu, suna kuma bi na. ");
INSERT INTO hausa_vpl VALUES ("JN10_28","073_10_28","JHN","10","28","28","Ina ba su rai madawwami, ba za su taɓa hallaka ba; ba kuma mai ƙwace su daga hannuna. ");
INSERT INTO hausa_vpl VALUES ("JN10_29","073_10_29","JHN","10","29","29","Ubana, wanda ya ba ni su, ya fi duka girma, ba mai ƙwace su daga hannun Ubana. ");
INSERT INTO hausa_vpl VALUES ("JN10_30","073_10_30","JHN","10","30","30","Da ni da Uba ɗaya ne.” ");
INSERT INTO hausa_vpl VALUES ("JN10_31","073_10_31","JHN","10","31","31","Sai Yahudawa suka sāke ɗebo duwatsu don su jajjefe shi, ");
INSERT INTO hausa_vpl VALUES ("JN10_32","073_10_32","JHN","10","32","32","amma Yesu ya ce musu, “Na nuna muku ayyukan alheri masu yawa da Uba ya aiko ni in yi, a kan wanne kuke so ku jajjefe ni?” ");
INSERT INTO hausa_vpl VALUES ("JN10_33","073_10_33","JHN","10","33","33","Yahudawa suka amsa suka ce, “Ai, ba don wani daga cikin waɗannan ayyukan alheri ne muke so mu jajjefe ka ba, amma don saɓon da kake yi, kai da kake mutum kawai, kana mai da kanka Allah.” ");
INSERT INTO hausa_vpl VALUES ("JN10_34","073_10_34","JHN","10","34","34","Yesu ya amsa musu ya ce, “Ba a rubuce yake a cikin Dokarku ba cewa, ‘Na ce ku alloli ne’? ");
INSERT INTO hausa_vpl VALUES ("JN10_35","073_10_35","JHN","10","35","35","Mun dai san Nassi ba ya ƙarya, In har ya kira su waɗanda maganar Allah ta zo musu, ‘alloli,’ ");
INSERT INTO hausa_vpl VALUES ("JN10_36","073_10_36","JHN","10","36","36","to, game da wanda Uba ya keɓe a matsayin nasa ne ya kuma aiko shi duniya. Don me kuke ce saɓo nake, domin na ce, ‘Ni Ɗan Allah ne?’ ");
INSERT INTO hausa_vpl VALUES ("JN10_37","073_10_37","JHN","10","37","37","In ba ayyukan da Ubana yake yi ne nake yi ba, to, kada ku gaskata ni. ");
INSERT INTO hausa_vpl VALUES ("JN10_38","073_10_38","JHN","10","38","38","Amma in su nake yi, ko ba ku gaskata ni ba, to, ku gaskata ayyukan, don ku sani, ku kuma gane, Uban yana cikina, ni kuma ina cikin Uban.” ");
INSERT INTO hausa_vpl VALUES ("JN10_39","073_10_39","JHN","10","39","39","Sai suka sāke yin ƙoƙari su kama shi, amma ya kuɓuce musu. ");
INSERT INTO hausa_vpl VALUES ("JN10_40","073_10_40","JHN","10","40","40","Sa’an nan Yesu ya sāke koma ƙetaren Urdun inda dā Yohanna yake baftisma. A can ya zauna ");
INSERT INTO hausa_vpl VALUES ("JN10_41","073_10_41","JHN","10","41","41","mutane da yawa suka zo wurinsa. Suka ce, “Ko da yake Yohanna bai yi wani abin banmamaki ba, duk abubuwan da Yohanna ya faɗa game da mutumin nan gaskiya ne.” ");
INSERT INTO hausa_vpl VALUES ("JN10_42","073_10_42","JHN","10","42","42","A nan kuwa mutane da yawa suka gaskata da Yesu. ");
INSERT INTO hausa_vpl VALUES ("JN11_1","073_11_1","JHN","11","1","1","To, an yi wani mutum mai suna Lazarus wanda ya yi rashin lafiya. Shi daga Betani ne, ƙauyen su Maryamu da ’yar’uwarta Marta. ");
INSERT INTO hausa_vpl VALUES ("JN11_2","073_11_2","JHN","11","2","2","Maryamun nan kuwa, wadda ɗan’uwanta Lazarus yake rashin lafiya, ita ce ta zuba wa Ubangiji turare ta kuma goge ƙafafunsa da gashin kanta. ");
INSERT INTO hausa_vpl VALUES ("JN11_3","073_11_3","JHN","11","3","3","Saboda haka ’yan’uwansa mata suka aika da saƙo wa Yesu cewa, “Ubangiji, wannan da kake ƙauna yana rashin lafiya.” ");
INSERT INTO hausa_vpl VALUES ("JN11_4","073_11_4","JHN","11","4","4","Sa’ad da ya ji haka, sai Yesu ya ce, “Wannan rashin lafiya ba zai kai ga mutuwa ba. A’a, sai dai don a ɗaukaka Allah a kuma ɗaukaka Ɗan Allah ta wurin wannan.” ");
INSERT INTO hausa_vpl VALUES ("JN11_5","073_11_5","JHN","11","5","5","Yesu kuwa yana ƙaunar Marta da ’yar’uwarta da kuma Lazarus. ");
INSERT INTO hausa_vpl VALUES ("JN11_6","073_11_6","JHN","11","6","6","Duk da haka sa’ad da ya ji Lazarus ba shi da lafiya, sai ya ƙara kwana biyu a inda yake. ");
INSERT INTO hausa_vpl VALUES ("JN11_7","073_11_7","JHN","11","7","7","Sai ya ce wa almajiransa, “Mu koma Yahudiya.” ");
INSERT INTO hausa_vpl VALUES ("JN11_8","073_11_8","JHN","11","8","8","Sai suka ce, “Rabbi, ba da daɗewa ba ne Yahudawa suka nemi su jajjefe ka, duk da haka za ka koma can?” ");
INSERT INTO hausa_vpl VALUES ("JN11_9","073_11_9","JHN","11","9","9","Yesu ya amsa ya ce, “Ba sa’a goma sha biyu ce yini guda ba? Mutumin da yake tafiya da rana ba zai yi tuntuɓe ba gama yana ganin hasken duniyan nan. ");
INSERT INTO hausa_vpl VALUES ("JN11_10","073_11_10","JHN","11","10","10","Sai a sa’ad da yake tafiya da dare ne zai yi tuntuɓe, don ba shi da haske.” ");
INSERT INTO hausa_vpl VALUES ("JN11_11","073_11_11","JHN","11","11","11","Bayan ya faɗa haka, sai ya ƙara ce musu, “Abokinmu Lazarus ya yi barci, amma za ni in tashe shi.” ");
INSERT INTO hausa_vpl VALUES ("JN11_12","073_11_12","JHN","11","12","12","Almajiransa suka ce, “Ubangiji, in barci ne yake, to, ai, zai sami sauƙi.” ");
INSERT INTO hausa_vpl VALUES ("JN11_13","073_11_13","JHN","11","13","13","Yesu kuwa yana magana mutuwarsa ce, amma almajiransa suka ɗauka yana nufin barcin gaskiya ne. ");
INSERT INTO hausa_vpl VALUES ("JN11_14","073_11_14","JHN","11","14","14","Saboda haka sai ya gaya musu a fili cewa, “Lazarus ya mutu, ");
INSERT INTO hausa_vpl VALUES ("JN11_15","073_11_15","JHN","11","15","15","amma saboda ku na yi farin ciki da ba na can, domin ku gaskata. Amma mu dai je wurinsa.” ");
INSERT INTO hausa_vpl VALUES ("JN11_16","073_11_16","JHN","11","16","16","Sai Toma (wanda ake kira Didaimus) ya ce wa sauran almajiran, “Mu ma mu je, mu mutu tare da shi.” ");
INSERT INTO hausa_vpl VALUES ("JN11_17","073_11_17","JHN","11","17","17","Da isowarsa, Yesu ya tarar Lazarus ya riga ya yi kwana huɗu a kabari. ");
INSERT INTO hausa_vpl VALUES ("JN11_18","073_11_18","JHN","11","18","18","Betani bai kai mil biyu ba daga Urushalima, ");
INSERT INTO hausa_vpl VALUES ("JN11_19","073_11_19","JHN","11","19","19","Yahudawa da yawa kuwa suka zo wurin Marta da Maryamu don su yi musu ta’aziyya, saboda rasuwar ɗan’uwansu. ");
INSERT INTO hausa_vpl VALUES ("JN11_20","073_11_20","JHN","11","20","20","Sa’ad da Marta ta ji cewa Yesu yana zuwa, sai ta fita don ta tarye shi, amma Maryamu ta zauna a gida. ");
INSERT INTO hausa_vpl VALUES ("JN11_21","073_11_21","JHN","11","21","21","Sai Marta ta ce wa Yesu, “Ubangiji, da kana nan da ɗan’uwana bai mutu ba. ");
INSERT INTO hausa_vpl VALUES ("JN11_22","073_11_22","JHN","11","22","22","Amma na san cewa ko yanzu ma Allah zai ba ka duk abin da ka roƙa.” ");
INSERT INTO hausa_vpl VALUES ("JN11_23","073_11_23","JHN","11","23","23","Yesu ya ce mata, “Ɗan’uwanki zai sāke tashi.” ");
INSERT INTO hausa_vpl VALUES ("JN11_24","073_11_24","JHN","11","24","24","Marta ta amsa ta ce, “Na sani zai sāke tashi a tashin matattu a rana ta ƙarshe.” ");
INSERT INTO hausa_vpl VALUES ("JN11_25","073_11_25","JHN","11","25","25","Yesu ya ce mata, “Ni ne tashin matattu da kuma rai. Duk wanda ya gaskata da ni zai rayu, ko ya mutu; ");
INSERT INTO hausa_vpl VALUES ("JN11_26","073_11_26","JHN","11","26","26","kuma duk wanda yake raye ya kuma gaskata da ni ba zai taɓa mutuwa ba. Kin gaskata wannan?” ");
INSERT INTO hausa_vpl VALUES ("JN11_27","073_11_27","JHN","11","27","27","Sai ta ce masa, “I, Ubangiji, na gaskata kai ne Kiristi, Ɗan Allah, mai zuwa cikin duniya.” ");
INSERT INTO hausa_vpl VALUES ("JN11_28","073_11_28","JHN","11","28","28","Bayan ta faɗa haka kuwa, sai ta koma ta je ta kira ’yar’uwarta Maryamu a gefe. Ta ce, “Ga Malam ya zo, kuma yana kiranki.” ");
INSERT INTO hausa_vpl VALUES ("JN11_29","073_11_29","JHN","11","29","29","Sa’ad da Maryamu ta ji haka sai ta yi wuf ta tafi wurinsa. ");
INSERT INTO hausa_vpl VALUES ("JN11_30","073_11_30","JHN","11","30","30","Yesu dai bai riga ya shiga ƙauyen ba tukuna, har yanzu yana inda Marta ta tarye shi. ");
INSERT INTO hausa_vpl VALUES ("JN11_31","073_11_31","JHN","11","31","31","Da Yahudawan da suke tare da Maryamu a cikin gida, suke mata ta’aziyya, suka ga ta yi wuf ta fita, sai suka bi ta, suna tsammani za tă kabarin ne tă yi kuka a can. ");
INSERT INTO hausa_vpl VALUES ("JN11_32","073_11_32","JHN","11","32","32","Sa’ad da Maryamu ta kai inda Yesu yake, ta kuma gan shi, sai ta fāɗi a gabansa ta ce, “Ubangiji, da kana nan, da ɗan’uwana bai mutu ba.” ");
INSERT INTO hausa_vpl VALUES ("JN11_33","073_11_33","JHN","11","33","33","Da Yesu ya ga tana kuka, Yahudawan da suka zo tare da ita ma suna kuka, sai ya yi juyayi ƙwarai a ruhu ya kuma damu. ");
INSERT INTO hausa_vpl VALUES ("JN11_34","073_11_34","JHN","11","34","34","Sai ya yi tambaya ya ce, “Ina kuka sa shi?” Suka amsa suka ce, “Ubangiji zo ka gani.” ");
INSERT INTO hausa_vpl VALUES ("JN11_35","073_11_35","JHN","11","35","35","Yesu ya yi kuka. ");
INSERT INTO hausa_vpl VALUES ("JN11_36","073_11_36","JHN","11","36","36","Sai Yahudawa suka ce, “Dubi yadda yake ƙaunarsa!” ");
INSERT INTO hausa_vpl VALUES ("JN11_37","073_11_37","JHN","11","37","37","Amma waɗansunsu suka ce, “Anya, wanda ya buɗe wa makahon nan idanu, ba zai iya yin wani abu yă hana wannan mutum mutuwa ba?” ");
INSERT INTO hausa_vpl VALUES ("JN11_38","073_11_38","JHN","11","38","38","Yesu, har yanzu cike da juyayi, ya zo kabarin. Kogo ne da aka rufe bakin da dutse. ");
INSERT INTO hausa_vpl VALUES ("JN11_39","073_11_39","JHN","11","39","39","Sai Yesu ya ce, “Ku kawar da dutsen.” Marta, ’yar’uwan mamacin ta ce, “Ubangiji, yanzu, ai, zai yi wari, don yau kwanansa huɗu ke nan a can.” ");
INSERT INTO hausa_vpl VALUES ("JN11_40","073_11_40","JHN","11","40","40","Sai Yesu ya ce, “Ban gaya miki cewa in kin gaskata za ki ga ɗaukakar Allah ba?” ");
INSERT INTO hausa_vpl VALUES ("JN11_41","073_11_41","JHN","11","41","41","Saboda haka suka kawar da dutsen. Sa’an nan Yesu ya dubi sama ya ce, “Uba, na gode maka da ka saurare ni. ");
INSERT INTO hausa_vpl VALUES ("JN11_42","073_11_42","JHN","11","42","42","Na san kullum kakan saurare ni, na dai faɗa haka ne saboda amfanin mutanen nan da suke tsaitsaye, don su gaskata cewa kai ka aiko ni.” ");
INSERT INTO hausa_vpl VALUES ("JN11_43","073_11_43","JHN","11","43","43","Sa’ad da ya faɗa haka, sai Yesu ya yi kira da babbar murya ya ce, “Lazarus, ka fito!” ");
INSERT INTO hausa_vpl VALUES ("JN11_44","073_11_44","JHN","11","44","44","Sai mamacin ya fito, hannuwansa da ƙafafunsa a daure da ƙyallayen lilin, fuskarsa kuwa an naɗe da mayafi. Yesu ya ce musu, “Ku tuɓe kayan bizo, ku bar shi yă tafi.” ");
INSERT INTO hausa_vpl VALUES ("JN11_45","073_11_45","JHN","11","45","45","Saboda haka Yahudawa da yawa da suka zo don su ziyarci Maryamu, suka kuma ga abin da Yesu ya yi, suka ba da gaskiya gare shi. ");
INSERT INTO hausa_vpl VALUES ("JN11_46","073_11_46","JHN","11","46","46","Amma waɗansunsu suka je wurin Farisiyawa suka gaya musu abin da Yesu ya yi. ");
INSERT INTO hausa_vpl VALUES ("JN11_47","073_11_47","JHN","11","47","47","Sai manyan firistoci da Farisiyawa suka kira taron Majalisa. Suka yi tambaya suna cewa, “Me muke yi ne? Ga mutumin nan yana yin abubuwan banmamaki masu yawa. ");
INSERT INTO hausa_vpl VALUES ("JN11_48","073_11_48","JHN","11","48","48","In fa muka ƙyale shi ya ci gaba da haka, kowa zai gaskata da shi, Romawa kuma su zo su karɓe wurinmu su kuma ƙwace ƙasarmu.” ");
INSERT INTO hausa_vpl VALUES ("JN11_49","073_11_49","JHN","11","49","49","Sai waninsu, mai suna Kayifas, wanda ya kasance babban firist a shekarar ya ce, “Ku dai ba ku san kome ba! ");
INSERT INTO hausa_vpl VALUES ("JN11_50","073_11_50","JHN","11","50","50","Ba ku gane ba, ai, gwamma mutum ɗaya yă mutu saboda mutane da duk ƙasar ta hallaka.” ");
INSERT INTO hausa_vpl VALUES ("JN11_51","073_11_51","JHN","11","51","51","Bai faɗa haka bisa nufinsa ba, sai dai a matsayinsa na babban firist a shekarar, ya yi annabci ne cewa Yesu zai mutu saboda ƙasar Yahudawa, ");
INSERT INTO hausa_vpl VALUES ("JN11_52","073_11_52","JHN","11","52","52","ba don ƙasan nan kaɗai ba amma don yă tattaro ’ya’yan Allah da suke warwatse ma, su zama ɗaya. ");
INSERT INTO hausa_vpl VALUES ("JN11_53","073_11_53","JHN","11","53","53","Saboda haka, daga wannan rana suka ƙulla su ɗauke ransa. ");
INSERT INTO hausa_vpl VALUES ("JN11_54","073_11_54","JHN","11","54","54","Saboda haka Yesu bai ƙara tafiya a cikin Yahudawa a sarari ba. A maimako haka sai ya janye zuwa yankin kusa da hamada, a wani ƙauye da ake kira Efraim, inda ya zauna da almajiransa. ");
INSERT INTO hausa_vpl VALUES ("JN11_55","073_11_55","JHN","11","55","55","Sa’ad da lokaci ya yi kusa a yi Bikin Ƙetarewa na Yahudawa, da yawa suka haura daga ƙauyuka zuwa Urushalima, don su tsarkake kansu kafin Bikin Ƙetarewa. ");
INSERT INTO hausa_vpl VALUES ("JN11_56","073_11_56","JHN","11","56","56","Suka yi ta neman Yesu, da suke a tsaitsaye a filin haikali kuwa suka dinga tambayar juna, suna cewa, “Me kuka gani? Anya, zai zo Bikin kuwa?” ");
INSERT INTO hausa_vpl VALUES ("JN11_57","073_11_57","JHN","11","57","57","Manyan firistoci da Farisiyawa tuni sun riga sun yi umarni cewa duk wanda ya san inda Yesu yake, yă faɗa don su kama shi. ");
INSERT INTO hausa_vpl VALUES ("JN12_1","073_12_1","JHN","12","1","1","Kwana shida kafin Bikin Ƙetarewa, sai Yesu ya iso Betani, inda Lazarus yake, wanda Yesu ya tā da daga matattu. ");
INSERT INTO hausa_vpl VALUES ("JN12_2","073_12_2","JHN","12","2","2","A nan aka shirya abincin yamma don girmama Yesu. Marta ta ce yi hidima, Lazarus kuma yana ɗaya cikin waɗanda suke ci tare shi. ");
INSERT INTO hausa_vpl VALUES ("JN12_3","073_12_3","JHN","12","3","3","Sai Maryamu ta ɗauki wajen awo guda na nardi zalla, turare mai tsada; ta zuba a ƙafafun Yesu ta kuma goge ƙafafunsa da gashinta. Gidan duk ya cika da ƙanshin turaren. ");
INSERT INTO hausa_vpl VALUES ("JN12_4","073_12_4","JHN","12","4","4","Amma ɗaya daga cikin almajiransa, Yahuda Iskariyot, wanda daga baya zai bashe shi, bai amince ba ya ce, ");
INSERT INTO hausa_vpl VALUES ("JN12_5","073_12_5","JHN","12","5","5","“Don me ba a sayar da turaren nan aka kuma ba da kuɗin ga matalauta ba? Ai, kuɗin ya kai albashin shekara guda.” ");
INSERT INTO hausa_vpl VALUES ("JN12_6","073_12_6","JHN","12","6","6","Ya yi wannan magana ba don ya kula da matalauta ba ne, sai dai don shi ɓarawo ne. Da yake shi ne mai ajiya jakar kuɗin, yakan taimaki kansa da abin da aka sa a ciki. ");
INSERT INTO hausa_vpl VALUES ("JN12_7","073_12_7","JHN","12","7","7","Yesu ya ce, “Ku ƙyale ta, an nufa ta ajiye wannan turaren don ranar jana’izata. ");
INSERT INTO hausa_vpl VALUES ("JN12_8","073_12_8","JHN","12","8","8","Kullum za ku kasance da matalauta, amma ba kullum za ku kasance tare da ni ba.” ");
INSERT INTO hausa_vpl VALUES ("JN12_9","073_12_9","JHN","12","9","9","Ana cikin haka sai babban taron Yahudawa suka sami labari Yesu yana can suka kuwa zo, ba kawai don shi ba amma don su kuma ga Lazarus, wanda ya tā da daga matattu. ");
INSERT INTO hausa_vpl VALUES ("JN12_10","073_12_10","JHN","12","10","10","Saboda haka manyan firistoci suka ƙulla su kashe Lazarus shi ma, ");
INSERT INTO hausa_vpl VALUES ("JN12_11","073_12_11","JHN","12","11","11","gama dalilinsa Yahudawa da yawa suna komawa ga Yesu suna kuma ba da gaskiya gare shi. ");
INSERT INTO hausa_vpl VALUES ("JN12_12","073_12_12","JHN","12","12","12","Kashegari babban taron da suka zo Bikin suka sami labari cewa Yesu yana kan hanyarsa zuwa Urushalima. ");
INSERT INTO hausa_vpl VALUES ("JN12_13","073_12_13","JHN","12","13","13","Sai suka ɗaɗɗauko rassan dabino suka fiffita taryensa, suna ɗaga murya suna cewa, “Hosanna!” “Mai albarka ne wanda yake zuwa cikin sunan Ubangiji!” “Mai albarka ne Sarkin Isra’ila!” ");
INSERT INTO hausa_vpl VALUES ("JN12_14","073_12_14","JHN","12","14","14","Yesu ya sami ɗan jaki, ya hau, kamar yadda yake a rubuce cewa, ");
INSERT INTO hausa_vpl VALUES ("JN12_15","073_12_15","JHN","12","15","15","“Kada ki ji tsoro, ya Diyar Sihiyona; duba, ga sarkinki yana zuwa, zaune a kan aholaki jaki.” ");
INSERT INTO hausa_vpl VALUES ("JN12_16","073_12_16","JHN","12","16","16","Da fari almajiransa ba su gane dukan wannan ba. Sai bayan da aka ɗaukaka Yesu, sa’an nan suka gane cewa an rubuta waɗannan abubuwa game da shi ne, har ma suka yi masa waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("JN12_17","073_12_17","JHN","12","17","17","Taron da suke tare da shi a sa’ad da ya kira Lazarus daga kabari ya kuma tā da shi daga matattu suka yi ta baza labarin. ");
INSERT INTO hausa_vpl VALUES ("JN12_18","073_12_18","JHN","12","18","18","Mutane da yawa kuwa suka fita taryensa, saboda sun ji labarin abin banmamakin da ya yi. ");
INSERT INTO hausa_vpl VALUES ("JN12_19","073_12_19","JHN","12","19","19","Saboda haka Farisiyawa suka ce wa juna, “Duba, wannan ba ya kai mu ko’ina. Ga shi, duk duniya tana bin sa!” ");
INSERT INTO hausa_vpl VALUES ("JN12_20","073_12_20","JHN","12","20","20","To, akwai waɗansu Hellenawa a cikin waɗanda suka haura don su yi sujada a Bikin. ");
INSERT INTO hausa_vpl VALUES ("JN12_21","073_12_21","JHN","12","21","21","Suka zo wurin Filibus, wanda yake daga Betsaida ta Galili, da roƙo. Suka ce, “Ranka yă daɗe, muna so mu ga Yesu.” ");
INSERT INTO hausa_vpl VALUES ("JN12_22","073_12_22","JHN","12","22","22","Sai Filibus ya je ya gaya wa Andarawus, Andarawus da kuma Filibus suka gaya wa Yesu. ");
INSERT INTO hausa_vpl VALUES ("JN12_23","073_12_23","JHN","12","23","23","Yesu ya amsa ya ce, “Lokaci ya yi da za a ɗaukaka Ɗan Mutum. ");
INSERT INTO hausa_vpl VALUES ("JN12_24","073_12_24","JHN","12","24","24","Gaskiya nake gaya muku, sai ƙwayar alkama ta fāɗi ƙasa ta mutu, in ba haka ba za tă kasance ƙwaya ɗaya tak. Amma in ta mutu, za tă ba da ’ya’ya da yawa. ");
INSERT INTO hausa_vpl VALUES ("JN12_25","073_12_25","JHN","12","25","25","Duk mai ƙaunar ransa, zai rasa shi, duk mai ƙin ransa a wannan duniya, zai kiyaye shi har yă zuwa rai madawwami. ");
INSERT INTO hausa_vpl VALUES ("JN12_26","073_12_26","JHN","12","26","26","Duk wanda zai bauta mini dole yă bi ni, inda kuma nake, a can bawana zai kasance. Ubana zai girmama wanda yake bauta mini. ");
INSERT INTO hausa_vpl VALUES ("JN12_27","073_12_27","JHN","12","27","27","“Yanzu kuwa na damu, amma me zan ce? ‘Uba, ka cece ni daga wannan sa’a’? A’a, ai, saboda wannan dalili ne musamman na zo. ");
INSERT INTO hausa_vpl VALUES ("JN12_28","073_12_28","JHN","12","28","28","Uba, ka ɗaukaka sunanka!” Sai wata murya ta fito daga sama ta ce, “Na riga na ɗaukaka shi, zan kuma ƙara ɗaukaka shi.” ");
INSERT INTO hausa_vpl VALUES ("JN12_29","073_12_29","JHN","12","29","29","Taron da suke a wurin suka ji, suka ce an yi tsawa; waɗansu kuwa suka ce mala’ika ne ya yi masa magana. ");
INSERT INTO hausa_vpl VALUES ("JN12_30","073_12_30","JHN","12","30","30","Yesu ya ce, “An yi wannan muryar saboda amfaninku ne, ba don nawa ba. ");
INSERT INTO hausa_vpl VALUES ("JN12_31","073_12_31","JHN","12","31","31","Yanzu ne za a yi wa duniyan nan shari’a, yanzu ne za a tumɓuke mai mulkin duniyan nan. ");
INSERT INTO hausa_vpl VALUES ("JN12_32","073_12_32","JHN","12","32","32","Amma ni, sa’ad da aka ɗaga ni daga ƙasa, zan ja dukan mutane gare ni.” ");
INSERT INTO hausa_vpl VALUES ("JN12_33","073_12_33","JHN","12","33","33","Ya faɗa haka ne don yă nuna irin mutuwar da zai yi. ");
INSERT INTO hausa_vpl VALUES ("JN12_34","073_12_34","JHN","12","34","34","Sai taron suka ce, “Ahab, Dokarmu ta gaya mana cewa, Kiristi zai kasance har abada, to, yaya za ka ce, ‘Dole ne a ɗaga Ɗan Mutum?’ Wane ne wannan ‘Ɗan Mutum’?” ");
INSERT INTO hausa_vpl VALUES ("JN12_35","073_12_35","JHN","12","35","35","Sai Yesu ya ce musu, “Haske zai kasance da ku na ɗan lokaci. Ku yi tafiya yayinda hasken yana nan tare da ku, kada duhu yă cim muku. Mai tafiya a cikin duhu bai san inda za shi ba. ");
INSERT INTO hausa_vpl VALUES ("JN12_36","073_12_36","JHN","12","36","36","Ku dogara ga hasken yayinda kuke da shi, don ku zama ’ya’yan haske.” Da Yesu ya gama magana, sai ya tafi ya ɓuya daga gare su. ");
INSERT INTO hausa_vpl VALUES ("JN12_37","073_12_37","JHN","12","37","37","Ko bayan Yesu ya yi dukan waɗannan abubuwan banmamaki a gabansu, duk da haka ba su gaskata da shi ba. ");
INSERT INTO hausa_vpl VALUES ("JN12_38","073_12_38","JHN","12","38","38","Wannan ya faru ne, don a cika maganar annabi Ishaya cewa, “Ubangiji, wa ya gaskata saƙonmu, ga wa kuma aka bayyana hannun ikon Ubangiji?” ");
INSERT INTO hausa_vpl VALUES ("JN12_39","073_12_39","JHN","12","39","39","Saboda haka ba su iya gaskatawa ba, domin, kamar yadda Ishaya ya faɗa a wani wuri cewa, ");
INSERT INTO hausa_vpl VALUES ("JN12_40","073_12_40","JHN","12","40","40","“Ya makantar da idanunsu ya kuma taurare zukatansu, don kada su gani da idanunsu, ko su fahimta a zukatansu, ko kuwa su juyo, har in warkar da su.” ");
INSERT INTO hausa_vpl VALUES ("JN12_41","073_12_41","JHN","12","41","41","Ishaya ya faɗi haka ne, saboda ya hangi ɗaukakar Yesu, ya kuwa yi magana a kansa. ");
INSERT INTO hausa_vpl VALUES ("JN12_42","073_12_42","JHN","12","42","42","Duk da haka, da yawa har daga cikin shugabanni ma suka gaskata da shi. Amma saboda Farisiyawa ba su furta bangaskiyarsu ba, don tsoron kada a kore su daga majami’a; ");
INSERT INTO hausa_vpl VALUES ("JN12_43","073_12_43","JHN","12","43","43","gama sun fi son yabon mutane, fiye da yabon Allah. ");
INSERT INTO hausa_vpl VALUES ("JN12_44","073_12_44","JHN","12","44","44","Sa’an nan Yesu ya ɗaga murya ya ce, “Duk wanda ya gaskata da ni, ba ni yake gaskatawa ba, amma ga wanda ya aiko ni ne. ");
INSERT INTO hausa_vpl VALUES ("JN12_45","073_12_45","JHN","12","45","45","Duk mai dubana, yana duban wanda ya aiko ni ne. ");
INSERT INTO hausa_vpl VALUES ("JN12_46","073_12_46","JHN","12","46","46","Na zo cikin duniya a kan ni haske ne, don duk wanda ya gaskata da ni, kada yă zauna a cikin duhu. ");
INSERT INTO hausa_vpl VALUES ("JN12_47","073_12_47","JHN","12","47","47","“Duk mai jin kalmomina bai kuwa kiyaye su ba, ba ni ba ne nake shari’anta shi. Gama ban zo domin in yi wa duniya shari’a ba, sai dai domin in cece ta. ");
INSERT INTO hausa_vpl VALUES ("JN12_48","073_12_48","JHN","12","48","48","Akwai mai hukunci saboda wanda ya ƙi ni, bai kuma karɓi kalmomina ba; wannan maganar da na faɗa ita ce za tă hukunta shi a rana ta ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("JN12_49","073_12_49","JHN","12","49","49","Gama ba don kaina na yi magana ba, Uban da ya aiko ni shi kansa ne ya ba ni umarni a kan abin da zan faɗa da kuma yadda zan faɗe shi. ");
INSERT INTO hausa_vpl VALUES ("JN12_50","073_12_50","JHN","12","50","50","Na san cewa umarninsa yana kai ga rai madawwami. Saboda haka duk abin da na faɗa na faɗe shi ne kamar dai yadda Uba ya ce in faɗa.” ");
INSERT INTO hausa_vpl VALUES ("JN13_1","073_13_1","JHN","13","1","1","Ana gab da Bikin Ƙetarewa. Yesu kuwa ya san cewa lokaci ya yi da zai bar wannan duniya, yă koma wurin Uba. Da yake ya ƙaunaci waɗanda suke nasa a duniya, yanzu kuwa ya nuna musu cikakkiyar ƙaunarsa. ");
INSERT INTO hausa_vpl VALUES ("JN13_2","073_13_2","JHN","13","2","2","Ana cikin cin abincin yamma, Iblis kuwa ya riga ya zuga Yahuda Iskariyot, ɗan Siman yă bashe Yesu. ");
INSERT INTO hausa_vpl VALUES ("JN13_3","073_13_3","JHN","13","3","3","Yesu kuwa ya san cewa, Uba ya sa dukan abubuwa a ƙarƙashin ikonsa, ya kuma san cewa daga Allah ya zo, zai kuma koma wurin Allah; ");
INSERT INTO hausa_vpl VALUES ("JN13_4","073_13_4","JHN","13","4","4","saboda haka ya tashi daga cin abincin, ya tuɓe rigarsa ta waje, ya ɗaura tawul a ƙugunsa. ");
INSERT INTO hausa_vpl VALUES ("JN13_5","073_13_5","JHN","13","5","5","Bayan haka, sai ya zuba ruwa a cikin kwano, sa’an nan ya fara wanke ƙafafun almajiransa, yana sharewa da tawul wanda ya ɗaura. ");
INSERT INTO hausa_vpl VALUES ("JN13_6","073_13_6","JHN","13","6","6","Ya zo kan Siman Bitrus, wanda ya ce masa, “Ubangiji, kai za ka wanke ƙafafuna?” ");
INSERT INTO hausa_vpl VALUES ("JN13_7","073_13_7","JHN","13","7","7","Yesu ya amsa ya ce, “Yanzu ba ka fahimci abin da nake yi ba, amma nan gaba za ka gane.” ");
INSERT INTO hausa_vpl VALUES ("JN13_8","073_13_8","JHN","13","8","8","Sai Bitrus ya ce, “Faufau, ba za ka taɓa wanke ƙafafuna ba.” Yesu ya amsa ya ce, “Sai na wanke ka, in ba haka ba, ba ka da rabo a gare ni.” ");
INSERT INTO hausa_vpl VALUES ("JN13_9","073_13_9","JHN","13","9","9","Sai Siman Bitrus ya ce, “To, Ubangiji, ba ƙafafuna kaɗai ba har ma da hannuwana da kaina kuma!” ");
INSERT INTO hausa_vpl VALUES ("JN13_10","073_13_10","JHN","13","10","10","Yesu ya amsa ya ce, “Wanda ya riga ya yi wanka yana bukata yă wanke ƙafafunsa ne kawai; dukan jikinsa yana da tsabta. Ku kuwa kuna da tsabta, ko da yake ba kowannenku ba.” ");
INSERT INTO hausa_vpl VALUES ("JN13_11","073_13_11","JHN","13","11","11","Gama ya san wanda zai bashe shi, shi ya sa ya ce, “Ba kowa ba ne yake da tsabta.” ");
INSERT INTO hausa_vpl VALUES ("JN13_12","073_13_12","JHN","13","12","12","Da ya gama wanke ƙafafunsu, sai ya sa tufafinsa ya koma wurin zamansa. Ya tambaye su ya ce, “Kun fahimci abin da na yi muku? ");
INSERT INTO hausa_vpl VALUES ("JN13_13","073_13_13","JHN","13","13","13","Kuna ce da ni ‘Malam’ da kuma ‘Ubangiji,’ daidai ne kuwa, gama haka nake. ");
INSERT INTO hausa_vpl VALUES ("JN13_14","073_13_14","JHN","13","14","14","Da yake ni da nake Ubangijinku da kuma Malaminku, na wanke ƙafafunku, haka ku ma ya kamata ku wanke ƙafafun juna. ");
INSERT INTO hausa_vpl VALUES ("JN13_15","073_13_15","JHN","13","15","15","Na ba ku misali domin ku yi yadda na yi muku. ");
INSERT INTO hausa_vpl VALUES ("JN13_16","073_13_16","JHN","13","16","16","Gaskiya nake gaya muku, ba bawan da ya fi maigidansa, ko ɗan saƙon da ya fi wanda ya aike shi. ");
INSERT INTO hausa_vpl VALUES ("JN13_17","073_13_17","JHN","13","17","17","Yanzu da kuka san waɗannan abubuwa, ku masu albarka ne, in kuka yi su. ");
INSERT INTO hausa_vpl VALUES ("JN13_18","073_13_18","JHN","13","18","18","“Ba dukanku nake nufi ba; na san waɗanda na zaɓa. Wannan kuwa don a cika Nassi ne da ya ce, ‘Wanda ya ci burodina tare da ni ya tasar mini.’ ");
INSERT INTO hausa_vpl VALUES ("JN13_19","073_13_19","JHN","13","19","19","“Ina faɗa muku yanzu tun kafin yă faru, domin in ya faru, ku gaskata cewa ni ne Shi. ");
INSERT INTO hausa_vpl VALUES ("JN13_20","073_13_20","JHN","13","20","20","Gaskiya nake gaya muku, ‘Duk wanda ya karɓi wani da na aiko, ni ne ya karɓa ke nan. Kuma duk wanda ya karɓe ni, ya karɓi wanda ya aiko ni ne.’ ” ");
INSERT INTO hausa_vpl VALUES ("JN13_21","073_13_21","JHN","13","21","21","Bayan Yesu ya faɗi haka, sai ya yi juyayi a ruhu, ya kuma furta cewa, “Gaskiya nake gaya muku, ɗayanku zai bashe ni.” ");
INSERT INTO hausa_vpl VALUES ("JN13_22","073_13_22","JHN","13","22","22","Almajiransa suka dubi juna, suka rasa ko da wa yake. ");
INSERT INTO hausa_vpl VALUES ("JN13_23","073_13_23","JHN","13","23","23","Ɗaya daga cikin almajiran Yesu wanda yake ƙauna kuwa, yana zaune kusa da shi. ");
INSERT INTO hausa_vpl VALUES ("JN13_24","073_13_24","JHN","13","24","24","Sai Siman Bitrus ya taɓa wannan almajirin ya ce, “Tambaye shi, wa yake nufi?” ");
INSERT INTO hausa_vpl VALUES ("JN13_25","073_13_25","JHN","13","25","25","Shi kuwa da yake jingine kusa da Yesu, ya ce, “Ubangiji, wane ne?” ");
INSERT INTO hausa_vpl VALUES ("JN13_26","073_13_26","JHN","13","26","26","Yesu ya amsa ya ce, “Shi ne wanda zan ba shi gutsurin burodin nan sa’ad da na tsoma cikin kwanon.” Da ya tsoma gutsurin burodin, sai ya ba wa Yahuda Iskariyot, ɗan Siman. ");
INSERT INTO hausa_vpl VALUES ("JN13_27","073_13_27","JHN","13","27","27","Nan take bayan Yahuda ya karɓi burodin, sai Shaiɗan ya shige shi. Sai Yesu ya ce masa, “Abin nan da kake niyyar yi, ka yi shi maza.” ");
INSERT INTO hausa_vpl VALUES ("JN13_28","073_13_28","JHN","13","28","28","Amma ba wani a wurin cin abincin da ya fahimci dalilin da ya sa Yesu ya faɗa masa haka. ");
INSERT INTO hausa_vpl VALUES ("JN13_29","073_13_29","JHN","13","29","29","Da yake Yahuda ne ma’aji, waɗansunsu suka ɗauka Yesu yana ce masa yă sayi abin da ake bukata don Bikin ne, ko kuwa yă ba wa matalauta wani abu. ");
INSERT INTO hausa_vpl VALUES ("JN13_30","073_13_30","JHN","13","30","30","Nan da nan da Yahuda ya karɓi burodin, sai ya fita. A lokacin kuwa dare ya yi. ");
INSERT INTO hausa_vpl VALUES ("JN13_31","073_13_31","JHN","13","31","31","Da ya tafi, sai Yesu ya ce, “Yanzu ne aka ɗaukaka Ɗan Mutum aka kuma ɗaukaka Allah a cikinsa. ");
INSERT INTO hausa_vpl VALUES ("JN13_32","073_13_32","JHN","13","32","32","In kuwa Allah ya sami ɗaukaka a cikin Ɗan, Allah kuwa zai ɗaukaka Ɗan zuwa ga zatinsa, zai kuma ɗaukaka shi nan take. ");
INSERT INTO hausa_vpl VALUES ("JN13_33","073_13_33","JHN","13","33","33","“’Ya’yana, zan kasance da ku na ɗan ƙanƙani lokaci ne. Za ku neme ni. Kuma kamar yadda na gaya wa Yahudawa, haka nake gaya muku yanzu. Inda zan tafi, ba za ku iya zuwa ba. ");
INSERT INTO hausa_vpl VALUES ("JN13_34","073_13_34","JHN","13","34","34","“Sabon umarni nake ba ku. Ku ƙaunaci juna. Kamar yadda na ƙaunace ku, ku ma ku ƙaunaci juna. ");
INSERT INTO hausa_vpl VALUES ("JN13_35","073_13_35","JHN","13","35","35","Ta haka kowa zai san cewa ku almajiraina ne, in kuna ƙaunar juna.” ");
INSERT INTO hausa_vpl VALUES ("JN13_36","073_13_36","JHN","13","36","36","Siman Bitrus ya tambaye shi ya ce, “Ubangiji ina za ka?” Yesu ya amsa ya ce, “Wurin da za ni, ba za ka iya zuwa yanzu ba, amma za ka bi ni daga baya.” ");
INSERT INTO hausa_vpl VALUES ("JN13_37","073_13_37","JHN","13","37","37","Bitrus ya ce masa, “Ubangiji, don me ba zan binka yanzu ba? Zan ba da raina saboda kai.” ");
INSERT INTO hausa_vpl VALUES ("JN13_38","073_13_38","JHN","13","38","38","Sai Yesu ya amsa ya ce, “Anya, za ka iya ba da ranka saboda ni? Gaskiya nake faɗa maka, kafin zakara yă yi cara, za ka yi mūsun sanina sau uku! ");
INSERT INTO hausa_vpl VALUES ("JN14_1","073_14_1","JHN","14","1","1","“Kada zuciyarku ta ɓaci. Ku gaskata da Allah, ku kuma gaskata da ni. ");
INSERT INTO hausa_vpl VALUES ("JN14_2","073_14_2","JHN","14","2","2","A cikin gidan Ubana akwai wurin zama da yawa; da a ce ba haka ba ne, da na gaya muku. Za ni can don in shirya muku wuri. ");
INSERT INTO hausa_vpl VALUES ("JN14_3","073_14_3","JHN","14","3","3","In kuwa na tafi na shirya muku wuri, sai in dawo in ɗauke ku ku kasance tare da ni don ku kasance inda nake. ");
INSERT INTO hausa_vpl VALUES ("JN14_4","073_14_4","JHN","14","4","4","Ai, kun san hanyar zuwa inda za ni.” ");
INSERT INTO hausa_vpl VALUES ("JN14_5","073_14_5","JHN","14","5","5","Sai Toma ya ce masa, “Ubangiji, ba mu san inda za ka ba, to, ta yaya za mu san hanyar?” ");
INSERT INTO hausa_vpl VALUES ("JN14_6","073_14_6","JHN","14","6","6","Yesu ya amsa ya ce, “Ni ne hanya, ni ne gaskiya, ni ne kuma rai. Ba mai zuwa wurin Uba sai dai ta wurina. ");
INSERT INTO hausa_vpl VALUES ("JN14_7","073_14_7","JHN","14","7","7","Da kun san ni, da za ku san Ubana ma. Daga yanzu, kun san shi kun kuma gan shi.” ");
INSERT INTO hausa_vpl VALUES ("JN14_8","073_14_8","JHN","14","8","8","Filibus ya ce, “Ubangiji, ka nuna mana Uban, wannan kuwa zai biya bukatarmu.” ");
INSERT INTO hausa_vpl VALUES ("JN14_9","073_14_9","JHN","14","9","9","Yesu ya amsa ya ce, “Ba san ni ba, Filibus, duk da daɗewan nan da na yi tare da ku? Duk wanda ya gan ni, ai, ya ga Uban. Yaya za ka ce, ‘Ka nuna mana Uban’? ");
INSERT INTO hausa_vpl VALUES ("JN14_10","073_14_10","JHN","14","10","10","Ba ka gaskata cewa ina cikin Uba, Uba kuma yana cikina ba? Kalmomin da nake gaya muku ba na kaina ba ne. Ai, Uban da yake raye a cikina ne yake aikinsa. ");
INSERT INTO hausa_vpl VALUES ("JN14_11","073_14_11","JHN","14","11","11","Ku gaskata ni sa’ad da na ce ina cikin Uba, Uba kuma yana cikina. Ko kuwa ku gaskata ni saboda ayyukan banmamakin su kansu. ");
INSERT INTO hausa_vpl VALUES ("JN14_12","073_14_12","JHN","14","12","12","Gaskiya nake gaya muku, duk wanda yake da bangaskiya gare ni, zai yi abubuwan da ni nake yi. Zai ma yi abubuwa masu girma fiye da waɗannan, don zan tafi wurin Uba. ");
INSERT INTO hausa_vpl VALUES ("JN14_13","073_14_13","JHN","14","13","13","Kuma zan yi duk abin da kuka roƙa cikin sunana, don Ɗan ya kawo ɗaukaka ga Uban. ");
INSERT INTO hausa_vpl VALUES ("JN14_14","073_14_14","JHN","14","14","14","Za ku iya roƙe ni kome a cikin sunana, zan kuwa yi. ");
INSERT INTO hausa_vpl VALUES ("JN14_15","073_14_15","JHN","14","15","15","“In kuna ƙaunata za ku yi biyayya da umarnina. ");
INSERT INTO hausa_vpl VALUES ("JN14_16","073_14_16","JHN","14","16","16","Zan kuwa roƙi Uba, zai kuwa ba ku wani Mai Taimakon da zai kasance tare da ku har abada, ");
INSERT INTO hausa_vpl VALUES ("JN14_17","073_14_17","JHN","14","17","17","Ruhun gaskiya. Duniya ba ta iya karɓarsa, don ba ta ganinsa ba ta kuma san shi ba. Amma kun san shi, saboda yana zama tare da ku zai kuma kasance a cikinku. ");
INSERT INTO hausa_vpl VALUES ("JN14_18","073_14_18","JHN","14","18","18","Ba zan bar ku marayu ba; zan zo wurinku. ");
INSERT INTO hausa_vpl VALUES ("JN14_19","073_14_19","JHN","14","19","19","Ba da daɗewa ba, duniya ba za tă ƙara ganina ba, amma za ku gan ni. Don ina raye, ku ma za ku rayu. ");
INSERT INTO hausa_vpl VALUES ("JN14_20","073_14_20","JHN","14","20","20","A ranan nan za ku sani ina cikin Uba, ku kuma kuna cikina, ni kuma ina cikinku. ");
INSERT INTO hausa_vpl VALUES ("JN14_21","073_14_21","JHN","14","21","21","Duk wanda yake da umarnaina yana kuma yin biyayya da su, shi ne wanda yake ƙaunata. Wanda yake ƙaunata kuwa Ubana zai ƙaunace shi, ni ma zan ƙaunace shi, in kuma bayyana kaina gare shi.” ");
INSERT INTO hausa_vpl VALUES ("JN14_22","073_14_22","JHN","14","22","22","Sai Yahuda (ba Yahuda Iskariyot ba) ya ce, “Ubangiji, me ya sa za ka bayyana kanka gare mu amma ba ga duniya ba?” ");
INSERT INTO hausa_vpl VALUES ("JN14_23","073_14_23","JHN","14","23","23","Yesu ya amsa ya ce, “Duk mai ƙaunata, zai yi biyayya da koyarwata. Ubana zai ƙaunace shi, za mu kuwa zo wurinsa mu zauna tare da shi. ");
INSERT INTO hausa_vpl VALUES ("JN14_24","073_14_24","JHN","14","24","24","Wanda ba ya ƙaunata ba zai yi biyayya da koyarwata ba. Waɗannan kalmomin da kuke ji ba nawa ba ne; na Uba ne da ya aiko ni. ");
INSERT INTO hausa_vpl VALUES ("JN14_25","073_14_25","JHN","14","25","25","“Duk wannan na faɗa ne yayinda ina tare da ku. ");
INSERT INTO hausa_vpl VALUES ("JN14_26","073_14_26","JHN","14","26","26","Amma Mai Taimako, Ruhu Mai Tsarki, wanda Uba zai aiko cikin sunana, zai koya muku kome, zai kuma tuna muku duk abin da na faɗa muku. ");
INSERT INTO hausa_vpl VALUES ("JN14_27","073_14_27","JHN","14","27","27","Salama na bari tare da ku; salamata nake ba ku. Ba kamar yadda duniya take bayarwa nake ba ku ba. Kada zuciyarku ta ɓaci kada kuma ku ji tsoro. ");
INSERT INTO hausa_vpl VALUES ("JN14_28","073_14_28","JHN","14","28","28","“Kun dai ji na ce, ‘Zan tafi in kuma sāke dawo wurinku.’ In har kuna ƙaunata, za ku yi farin ciki cewa za ni wurin Uba, domin kuwa Uban ya fi ni. ");
INSERT INTO hausa_vpl VALUES ("JN14_29","073_14_29","JHN","14","29","29","Na faɗa muku tun kafin yă faru, domin in ya faru, ku gaskata. ");
INSERT INTO hausa_vpl VALUES ("JN14_30","073_14_30","JHN","14","30","30","Ba zan ƙara yi muku magana ba, gama mai mulkin duniyan nan yana zuwa. Ba shi da iko a kaina, ");
INSERT INTO hausa_vpl VALUES ("JN14_31","073_14_31","JHN","14","31","31","amma dole duniya ta koya cewa ina ƙaunar Uba, ina kuma yin yadda Ubana ya umarce ni. “Ku zo, mu bar nan. ");
INSERT INTO hausa_vpl VALUES ("JN15_1","073_15_1","JHN","15","1","1","“Ni ne kuringar inabi na gaskiya, Ubana kuwa shi ne manomin. ");
INSERT INTO hausa_vpl VALUES ("JN15_2","073_15_2","JHN","15","2","2","Yakan sare kowane reshe a cikina da ba ya ’ya’ya, amma yakan ƙundume kowane reshe da yake ba da ’ya’ya, domin yă ƙara ba da ’ya’ya. ");
INSERT INTO hausa_vpl VALUES ("JN15_3","073_15_3","JHN","15","3","3","Kun riga kun zama masu tsabta saboda maganar da na yi muku. ");
INSERT INTO hausa_vpl VALUES ("JN15_4","073_15_4","JHN","15","4","4","Ku kasance a cikina, ni kuma zan kasance a cikinku. Babu reshen da zai iya yin ’ya’ya da kansa, dole yă kasance a jikin kuringar inabin. Haka ku ma, ba za ku iya ba da ’ya’ya ba sai kun kasance a cikina. ");
INSERT INTO hausa_vpl VALUES ("JN15_5","073_15_5","JHN","15","5","5","“Ni ne kuringar inabin; ku ne kuma rassan. In mutum ya kasance a cikina ni kuma a cikinsa, zai ba da ’ya’ya da yawa; in ba tare da ni ba, ba za ku iya yin kome ba. ");
INSERT INTO hausa_vpl VALUES ("JN15_6","073_15_6","JHN","15","6","6","Duk wanda bai kasance a cikina ba, yana kamar reshen da aka jefar yă bushe; irin waɗannan rassan ne akan tattara, a jefa cikin wuta a ƙone. ");
INSERT INTO hausa_vpl VALUES ("JN15_7","073_15_7","JHN","15","7","7","In kun kasance a cikina kalmomina kuma suka kasance a cikinku, ku roƙi kome da kuke so, za a kuwa ba ku. ");
INSERT INTO hausa_vpl VALUES ("JN15_8","073_15_8","JHN","15","8","8","Wannan ne yakan kawo ɗaukaka ga Ubana, ku ba da ’ya’ya da yawa, kuna kuma nuna kanku ku almajiraina ne. ");
INSERT INTO hausa_vpl VALUES ("JN15_9","073_15_9","JHN","15","9","9","“Kamar yadda Uba ya ƙaunace ni, haka ni ma na ƙaunace ku. To, fa, ku kasance cikin ƙaunata. ");
INSERT INTO hausa_vpl VALUES ("JN15_10","073_15_10","JHN","15","10","10","In kuka yi biyayya da umarnaina, za ku kasance a cikin ƙaunata, kamar dai yadda na yi biyayya da umarnan Ubana na kuma kasance a cikin ƙaunarsa. ");
INSERT INTO hausa_vpl VALUES ("JN15_11","073_15_11","JHN","15","11","11","Na gaya muku wannan domin murnata ta kasance a cikinku, murnanku kuma ta zama cikakkiya. ");
INSERT INTO hausa_vpl VALUES ("JN15_12","073_15_12","JHN","15","12","12","Umarnina shi ne, Ku ƙaunaci juna kamar yadda na ƙaunace ku. ");
INSERT INTO hausa_vpl VALUES ("JN15_13","073_15_13","JHN","15","13","13","Babu ƙaunar da ta fi wannan, a ce mutum ya ba da ransa saboda abokansa. ");
INSERT INTO hausa_vpl VALUES ("JN15_14","073_15_14","JHN","15","14","14","Ku abokaina ne, in kun yi abin da na umarta. ");
INSERT INTO hausa_vpl VALUES ("JN15_15","073_15_15","JHN","15","15","15","Ba zan ƙara ce da ku bayi ba, don bawa bai san abin da maigidansa yake yi ba. A maimako in ce da ku abokai, domin na sanar da ku duk abin da na ji daga wurin Ubana. ");
INSERT INTO hausa_vpl VALUES ("JN15_16","073_15_16","JHN","15","16","16","Ba ku kuka zaɓe ni ba, a’a, ni ne na zaɓe ku na kuma naɗa ku ku je ku ba da ’ya’ya-’ya’yan da za su dawwama. Uba kuwa zai ba ku duk abin da kuka roƙa cikin sunana. ");
INSERT INTO hausa_vpl VALUES ("JN15_17","073_15_17","JHN","15","17","17","Umarnina ke nan. Ku ƙaunaci juna. ");
INSERT INTO hausa_vpl VALUES ("JN15_18","073_15_18","JHN","15","18","18","“In duniya ta ƙi ku, ku san cewa ta fara ƙin na ne. ");
INSERT INTO hausa_vpl VALUES ("JN15_19","073_15_19","JHN","15","19","19","Da ku na duniya ne, da ta ƙaunaci abinta. Kamar yadda yake, ku ba na duniya ba ne, na zaɓe ku daga duniya, shi ya sa duniya take ƙinku. ");
INSERT INTO hausa_vpl VALUES ("JN15_20","073_15_20","JHN","15","20","20","Ku tuna da kalmomin da na yi muku cewa, ‘Ba bawan da ya fi maigidansa,’In sun tsananta mini, ku ma za su tsananta muku. Da sun yi biyayya da koyarwata, da za su yi biyayya da taku ma. ");
INSERT INTO hausa_vpl VALUES ("JN15_21","073_15_21","JHN","15","21","21","Za su yi muku haka saboda sunana, gama ba su san Wannan da ya aiko ni ba. ");
INSERT INTO hausa_vpl VALUES ("JN15_22","073_15_22","JHN","15","22","22","Da a ce ban zo na yi musu magana ba, da ba su da zunubi. Yanzu kam, ba su da wata hujja a kan zunubinsu. ");
INSERT INTO hausa_vpl VALUES ("JN15_23","073_15_23","JHN","15","23","23","Wanda ya ƙi ni ya ƙi ya ƙi Ubana ma. ");
INSERT INTO hausa_vpl VALUES ("JN15_24","073_15_24","JHN","15","24","24","Da a ce ban yi ayyuka a cikinsu waɗanda babu wani da ya taɓa yi ba, da ba su da zunubi. Amma yanzu sun ga waɗannan ayyukan banmamaki, duk da haka sun ƙi ni sun kuma ƙi Ubana. ");
INSERT INTO hausa_vpl VALUES ("JN15_25","073_15_25","JHN","15","25","25","Amma wannan ya faru ne domin a cika abin da yake a rubuce cikin Dokarsu cewa, ‘Sun ƙi ni ba dalili.’ ");
INSERT INTO hausa_vpl VALUES ("JN15_26","073_15_26","JHN","15","26","26","“Sa’ad da Mai Taimako ya zo, wanda zan aiko muku daga wurin Uba, Ruhun gaskiya wanda yake fitowa daga wurin Uba, zai ba da shaida game da ni. ");
INSERT INTO hausa_vpl VALUES ("JN15_27","073_15_27","JHN","15","27","27","Ku ma dole ku ba da shaida, domin kun kasance tare da ni tun daga farko. ");
INSERT INTO hausa_vpl VALUES ("JN16_1","073_16_1","JHN","16","1","1","“Na faɗa muku wannan duka, domin kada ku bauɗe. ");
INSERT INTO hausa_vpl VALUES ("JN16_2","073_16_2","JHN","16","2","2","Za su kore ku daga majami’a; lalle, lokaci yana zuwa da duk wanda ya kashe ku, zai ɗauka yana yin wa Allah hidima ne. ");
INSERT INTO hausa_vpl VALUES ("JN16_3","073_16_3","JHN","16","3","3","Za su yi waɗannan abubuwa ne domin ba su san Uba ko ni ba. ");
INSERT INTO hausa_vpl VALUES ("JN16_4","073_16_4","JHN","16","4","4","Na faɗa muku wannan, domin in lokacin ya yi, ku tuna na gargaɗe ku. Ban faɗa muku wannan tun da fari ba domin ina tare da ku. ");
INSERT INTO hausa_vpl VALUES ("JN16_5","073_16_5","JHN","16","5","5","“Yanzu zan tafi wurin wanda ya aiko ni, duk da haka ba waninku da ya tambaye ni, ‘Ina za ka?’ ");
INSERT INTO hausa_vpl VALUES ("JN16_6","073_16_6","JHN","16","6","6","Saboda na faɗa waɗannan abubuwa ga shi kun cika da baƙin ciki. ");
INSERT INTO hausa_vpl VALUES ("JN16_7","073_16_7","JHN","16","7","7","Amma gaskiya nake gaya muku. Don amfaninku ne zan tafi. Sai ko na tafi, in ba haka ba Mai Taimakon nan ba zai zo muku ba. Amma in na tafi, zan aiko shi gare ku. ");
INSERT INTO hausa_vpl VALUES ("JN16_8","073_16_8","JHN","16","8","8","Sa’ad da ya zo kuwa, zai kā da duniya a kan zunubi da adalci da kuma hukunci, ");
INSERT INTO hausa_vpl VALUES ("JN16_9","073_16_9","JHN","16","9","9","a kan zunubi, domin mutane ba su gaskata da ni ba; ");
INSERT INTO hausa_vpl VALUES ("JN16_10","073_16_10","JHN","16","10","10","a kan adalci, domin zan tafi wurin Uba, inda ba za ku ƙara ganina ba; ");
INSERT INTO hausa_vpl VALUES ("JN16_11","073_16_11","JHN","16","11","11","a kan hukunci kuma, domin an yanke hukunci a kan mai mulkin duniyan nan. ");
INSERT INTO hausa_vpl VALUES ("JN16_12","073_16_12","JHN","16","12","12","“Ina da sauran abubuwa da yawa da zan faɗa muku, amma ba za ku iya ɗauka a yanzu ba. ");
INSERT INTO hausa_vpl VALUES ("JN16_13","073_16_13","JHN","16","13","13","Amma sa’ad da shi, Ruhun gaskiya ya zo, zai bi da ku zuwa ga dukan gaskiya. Ba zai yi magana don kansa ba; zai faɗi abin da ya ji ne kaɗai, zai kuma faɗa muku abin da bai faru ba tukuna. ");
INSERT INTO hausa_vpl VALUES ("JN16_14","073_16_14","JHN","16","14","14","Zai kawo ɗaukaka gare ni ta wurin ɗaukan abin da yake nawa, ya bayyana muku. ");
INSERT INTO hausa_vpl VALUES ("JN16_15","073_16_15","JHN","16","15","15","Duk abin da yake na Uba nawa ne. Shi ya sa na ce, ‘Ruhun zai ɗauko daga abin da yake nawa, yă bayyana muku.’ ” ");
INSERT INTO hausa_vpl VALUES ("JN16_16","073_16_16","JHN","16","16","16","Yesu ya ci gaba da cewa, “Jim kaɗan, ba za ku ƙara ganina ba, sa’an nan bayan an jima kaɗan kuma, za ku gan ni.” ");
INSERT INTO hausa_vpl VALUES ("JN16_17","073_16_17","JHN","16","17","17","A nan fa sai waɗansu almajiransa suka ce wa juna, “Me yake nufi da cewa, ‘Jim kaɗan ba za ku ƙara ganina ba, kuma bayan an jima kaɗan, za ku gan ni,’ da kuma, ‘Domin zan tafi wurin Uba’?” ");
INSERT INTO hausa_vpl VALUES ("JN16_18","073_16_18","JHN","16","18","18","Suka yi ta tambaya, “Me yake nufi da ‘jim kaɗan’? Ba mu fahimci abin da yake faɗi ba.” ");
INSERT INTO hausa_vpl VALUES ("JN16_19","073_16_19","JHN","16","19","19","Yesu ya gane suna so su tambaye shi game da wannan, sai ya ce musu, “Kuna tambayar juna game da abin da nake nufi da na ce, ‘Jim kaɗan ba za ku ƙara ganina ba, da kuma bayan an jima kaɗan, za ku gan ni’? ");
INSERT INTO hausa_vpl VALUES ("JN16_20","073_16_20","JHN","16","20","20","Gaskiya nake gaya muku, za ku yi kuka da kuma gunji, yayinda duniya take murna. Za ku yi baƙin ciki, amma baƙin cikinku zai koma farin ciki. ");
INSERT INTO hausa_vpl VALUES ("JN16_21","073_16_21","JHN","16","21","21","Macen da za tă haihu takan yi naƙuda domin lokacinta ya yi; amma sa’ad da ta haihu, sai ta manta da wahalar domin farin ciki an haifi jariri a duniya. ");
INSERT INTO hausa_vpl VALUES ("JN16_22","073_16_22","JHN","16","22","22","Haka ku ma, yanzu ne lokacin baƙin cikinku, amma zan sāke ganinku za ku kuma yi farin ciki, ba kuwa wanda zai ɗauke muku farin cikinku. ");
INSERT INTO hausa_vpl VALUES ("JN16_23","073_16_23","JHN","16","23","23","A ranan nan, ba za ku sāke tambaya ta kome ba. Gaskiya nake gaya muku, Ubana zai ba ku kome da kuka roƙa cikin sunana. ");
INSERT INTO hausa_vpl VALUES ("JN16_24","073_16_24","JHN","16","24","24","Har yanzu dai ba ku roƙi kome cikin sunana ba. Ku roƙa za ku kuwa samu, farin cikinku kuwa zai zama cikakke. ");
INSERT INTO hausa_vpl VALUES ("JN16_25","073_16_25","JHN","16","25","25","“Ko da yake ina magana da misalai, lokaci yana zuwa da ba zan ƙara yin magana da misalai ba, sai dai in faɗa muku a fili game da Ubana. ");
INSERT INTO hausa_vpl VALUES ("JN16_26","073_16_26","JHN","16","26","26","A ranan nan, za ku roƙa a cikin sunana. Ban ce zan roƙi Uba a madadinku ba. ");
INSERT INTO hausa_vpl VALUES ("JN16_27","073_16_27","JHN","16","27","27","Ai, shi Uban kansa yana ƙaunarku domin kun ƙaunace ni kun kuma gaskata cewa daga Allah na fito. ");
INSERT INTO hausa_vpl VALUES ("JN16_28","073_16_28","JHN","16","28","28","Na fito daga wurin Uba, na kuma shigo duniya, yanzu kuwa zan bar duniya in koma wurin Uba.” ");
INSERT INTO hausa_vpl VALUES ("JN16_29","073_16_29","JHN","16","29","29","Sai almajiran Yesu suka ce, “Haba, yanzu ne fa kake magana a sarari ba tare da misalai ba. ");
INSERT INTO hausa_vpl VALUES ("JN16_30","073_16_30","JHN","16","30","30","Yanzu mun gane cewa ka san kome ba sai wani ya tambaye ka ba. Wannan ya sa muka gaskata ka fito daga Allah.” ");
INSERT INTO hausa_vpl VALUES ("JN16_31","073_16_31","JHN","16","31","31","Yesu ya amsa ya ce, “A ƙarshe kun gaskata! ");
INSERT INTO hausa_vpl VALUES ("JN16_32","073_16_32","JHN","16","32","32","Amma lokaci na zuwa, har ma ya yi, da za a warwatsa ku, kowa yă koma gidansa. Za ku bar ni ni kaɗai. Duk da haka ba ni kaɗai ba ne, gama Ubana yana tare da ni. ");
INSERT INTO hausa_vpl VALUES ("JN16_33","073_16_33","JHN","16","33","33","“Na faɗa muku waɗannan abubuwa ne, domin a cikina ku sami salama. A duniyan nan za ku sha wahala. Amma ku yi ƙarfin hali! Na yi nasara a kan duniya.” ");
INSERT INTO hausa_vpl VALUES ("JN17_1","073_17_1","JHN","17","1","1","Bayan da Yesu ya faɗi wannan, sai ya dubi sama ya yi addu’a ya ce, “Uba, lokaci ya yi. Ka ɗaukaka Ɗanka, don Ɗanka yă ɗaukaka ka. ");
INSERT INTO hausa_vpl VALUES ("JN17_2","073_17_2","JHN","17","2","2","Gama ka ba shi iko bisa dukan mutane domin yă ba da rai madawwami ga duk waɗanda ka ba shi. ");
INSERT INTO hausa_vpl VALUES ("JN17_3","073_17_3","JHN","17","3","3","Rai madawwami kuwa shi ne, su san ka, Allah makaɗaici mai gaskiya, da kuma Yesu Kiristi, wanda ka aiko. ");
INSERT INTO hausa_vpl VALUES ("JN17_4","073_17_4","JHN","17","4","4","Na ɗaukaka ka a duniya ta wurin gama aikin da ka ba ni. ");
INSERT INTO hausa_vpl VALUES ("JN17_5","073_17_5","JHN","17","5","5","Yanzu ya Uba, ka ɗaukaka ni a gabanka da ɗaukakar da dā nake da ita tun kafin a kafa duniya. ");
INSERT INTO hausa_vpl VALUES ("JN17_6","073_17_6","JHN","17","6","6","“Na bayyana ka ga waɗanda ka ba ni a duniya. Su naka ne; kai ka ba ni su sun kuma yi biyayya da maganarka. ");
INSERT INTO hausa_vpl VALUES ("JN17_7","073_17_7","JHN","17","7","7","Yanzu sun san cewa duk abin da ka ba ni daga gare ka ya fito. ");
INSERT INTO hausa_vpl VALUES ("JN17_8","073_17_8","JHN","17","8","8","Na ba su kalmomin da ka ba ni sun kuwa karɓa. Sun san tabbatacce daga wurinka na fito. Sun kuma gaskata kai ka aiko ni. ");
INSERT INTO hausa_vpl VALUES ("JN17_9","073_17_9","JHN","17","9","9","Ina addu’a dominsu. Ba domin duniya nake addu’a ba, amma domin waɗanda ka ba ni, gama su naka ne. ");
INSERT INTO hausa_vpl VALUES ("JN17_10","073_17_10","JHN","17","10","10","Duk abin da nake da shi naka ne, kuma duk abin da kake da shi nawa ne. Na kuwa sami ɗaukaka ta wurinsu. ");
INSERT INTO hausa_vpl VALUES ("JN17_11","073_17_11","JHN","17","11","11","Ba sauran zamana a duniya, amma waɗannan a duniya suke, ni kuwa ina zuwa wurinka. Ya Uba Mai Tsarki, ka kiyaye su ta wurin ikon sunanka, sunan da ka ba ni, don su zama ɗaya kamar yadda muke ɗaya. ");
INSERT INTO hausa_vpl VALUES ("JN17_12","073_17_12","JHN","17","12","12","Yayinda nake tare da su, na kāre su na kuma kiyaye su ta wurin sunan nan da ka ba ni. Ba ko ɗayan da ya ɓace, sai dai wannan da aka ƙaddara zuwa ga hallaka don Nassi yă cika. ");
INSERT INTO hausa_vpl VALUES ("JN17_13","073_17_13","JHN","17","13","13","“Yanzu ina zuwa wurinka, sai dai na faɗi waɗannan abubuwa ne tun ina a duniya domin farin ciki yă zama cikakke a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("JN17_14","073_17_14","JHN","17","14","14","Na gaya musu maganarka duniya kuwa ta ƙi su, don su ba na duniya ba ne yadda ni ma ba na duniya ba ne. ");
INSERT INTO hausa_vpl VALUES ("JN17_15","073_17_15","JHN","17","15","15","Ba addu’ata ba ce ka ɗauke su daga duniya ba, sai dai ka kāre su daga mugun nan. ");
INSERT INTO hausa_vpl VALUES ("JN17_16","073_17_16","JHN","17","16","16","Su ba na duniya ba ne, kamar yadda ni ma ba na duniya ba ne. ");
INSERT INTO hausa_vpl VALUES ("JN17_17","073_17_17","JHN","17","17","17","Ka tsarkake su ta wurin gaskiya; maganarka ce gaskiya. ");
INSERT INTO hausa_vpl VALUES ("JN17_18","073_17_18","JHN","17","18","18","Kamar yadda ka aiko ni cikin duniya, haka ni ma na aike su cikin duniya. ");
INSERT INTO hausa_vpl VALUES ("JN17_19","073_17_19","JHN","17","19","19","Saboda su ne na tsarkake kaina, domin su ma a tsarkake su da gaske. ");
INSERT INTO hausa_vpl VALUES ("JN17_20","073_17_20","JHN","17","20","20","“Addu’ata ba saboda masu bina kaɗai ba ne. Ina addu’a kuma saboda waɗanda za su gaskata da ni ta wurin maganarsu. ");
INSERT INTO hausa_vpl VALUES ("JN17_21","073_17_21","JHN","17","21","21","Ina so dukansu su zama ɗaya, ya Uba, kamar yadda kake a cikina, ni kuwa a cikinka. Haka su ma bari su zauna cikinmu, domin duniya ta gaskata cewa kai ka aiko ni. ");
INSERT INTO hausa_vpl VALUES ("JN17_22","073_17_22","JHN","17","22","22","Na ba su ɗaukakar da ka ba ni, don su zama ɗaya kamar yadda muke ɗaya. ");
INSERT INTO hausa_vpl VALUES ("JN17_23","073_17_23","JHN","17","23","23","Ni a cikinsu kai kuma a cikina. Bari su kasance da cikakken haɗinkai, domin duniya ta san cewa kai ka aiko ni. Ka kuwa ƙaunace su yadda ka ƙaunace ni. ");
INSERT INTO hausa_vpl VALUES ("JN17_24","073_17_24","JHN","17","24","24","“Uba, ina so waɗanda ka ba ni su kasance tare da ni a inda nake, su kuma ga ɗaukakata, ɗaukakar da ka ba ni domin kana ƙaunata kafin halittar duniya. ");
INSERT INTO hausa_vpl VALUES ("JN17_25","073_17_25","JHN","17","25","25","“Ya Uba Mai Adalci, ko da yake duniya ba tă san ka ba, ni na san ka, sun kuma san kai ka aiko ni. ");
INSERT INTO hausa_vpl VALUES ("JN17_26","073_17_26","JHN","17","26","26","Na bayyana ka a gare su, zan kuma ci gaba da bayyana ka domin ƙaunar da ka yi mini ta kasance a cikinsu ni ma in kasance a cikinsu.” ");
INSERT INTO hausa_vpl VALUES ("JN18_1","073_18_1","JHN","18","1","1","Da ya gama addu’a, sai Yesu ya fita tare da almajiransa suka haye Kwarin Kidron. A wancan ƙetaren kuwa akwai lambun zaitun, da shi da almajiransa suka shiga ciki. ");
INSERT INTO hausa_vpl VALUES ("JN18_2","073_18_2","JHN","18","2","2","To, Yahuda, wanda ya bashe shi, ya san wurin, domin Yesu ya sha zuwa wurin da almajiransa. ");
INSERT INTO hausa_vpl VALUES ("JN18_3","073_18_3","JHN","18","3","3","Saboda haka Yahuda ya zo cikin lambun, yana jagoranta ƙungiyar sojoji da waɗansu ma’aikata daga wurin manyan firistoci da Farisiyawa. Suna riƙe da toci, fitilu da kuma makamai. ");
INSERT INTO hausa_vpl VALUES ("JN18_4","073_18_4","JHN","18","4","4","Yesu kuwa, sane da duk abin da zai same shi, ya fito ya tambaye, su ya ce, “Wa kuke nema?” ");
INSERT INTO hausa_vpl VALUES ("JN18_5","073_18_5","JHN","18","5","5","Suka amsa suka ce, “Yesu Banazare.” Yesu ya ce, “Ni ne shi.” (Yahuda kuwa wanda ya bashe shi yana nan tsaye tare da su.) ");
INSERT INTO hausa_vpl VALUES ("JN18_6","073_18_6","JHN","18","6","6","Da Yesu ya ce, “Ni ne shi,” sai suka ja da baya suka fāɗi a ƙasa. ");
INSERT INTO hausa_vpl VALUES ("JN18_7","073_18_7","JHN","18","7","7","Sai ya sāke tambayar su ya ce, “Wa kuke nema?” Suka ce, “Yesu Banazare.” ");
INSERT INTO hausa_vpl VALUES ("JN18_8","073_18_8","JHN","18","8","8","Yesu ya amsa ya ce, “Ai, na gaya muku ni ne shi. In kuma ni ne kuke nema, to, sai ku bar waɗannan su tafi.” ");
INSERT INTO hausa_vpl VALUES ("JN18_9","073_18_9","JHN","18","9","9","Wannan ya faru ne don a cika kalmomin da ya yi cewa, “Ban yar da ko ɗaya daga cikin waɗanda ka ba ni ba.” ");
INSERT INTO hausa_vpl VALUES ("JN18_10","073_18_10","JHN","18","10","10","Sai Siman Bitrus, wanda yake da takobi, ya zāre, ya kai wa bawan babban firist sara, ya ɗauke masa kunnensa na dama (Sunan bawan kuwa Malkus ne.) ");
INSERT INTO hausa_vpl VALUES ("JN18_11","073_18_11","JHN","18","11","11","Sai Yesu ya umarce Bitrus ya ce, “Mai da takobinka kube! Ba zan sha kwaf da Uba ya ba ni ba?” ");
INSERT INTO hausa_vpl VALUES ("JN18_12","073_18_12","JHN","18","12","12","Sai ƙungiyar soja tare da shugaban sojanta da kuma ma’aikatan Yahudawa suka kama Yesu. Suka daure shi ");
INSERT INTO hausa_vpl VALUES ("JN18_13","073_18_13","JHN","18","13","13","sa’an nan suka kawo shi da farko wurin Annas, wanda yake surukin Kayifas, babban firist a shekaran nan. ");
INSERT INTO hausa_vpl VALUES ("JN18_14","073_18_14","JHN","18","14","14","Kayifas ne wanda ya shawarci Yahudawa cewa zai fi kyau mutum ɗaya yă mutu saboda mutane. ");
INSERT INTO hausa_vpl VALUES ("JN18_15","073_18_15","JHN","18","15","15","Siman Bitrus da kuma wani almajiri suna bin Yesu. Domin almajirin nan sananne ne ga babban firist, sai ya shiga tare da Yesu a filin gidan babban firist ɗin, ");
INSERT INTO hausa_vpl VALUES ("JN18_16","073_18_16","JHN","18","16","16","Bitrus kuwa ya dakata a waje a bakin ƙofa. Almajirin nan da yake sananne ga babban firist, ya dawo ya yi magana da yarinyar mai aiki a can, ya kuma shigo da Bitrus. ");
INSERT INTO hausa_vpl VALUES ("JN18_17","073_18_17","JHN","18","17","17","Yarinyar da take bakin ƙofar ta ce wa Bitrus, “Kai ba ɗaya ne daga cikin almajiran mutumin nan ba ne?” Bitrus ya amsa ya ce, “A’a, ba na ciki.” ");
INSERT INTO hausa_vpl VALUES ("JN18_18","073_18_18","JHN","18","18","18","To, ana sanyi, bayi da ma’aikatan suna tsattsaye kewaye da wutar da suka hura don su ji ɗumi. Bitrus ma yana tsaye tare da su, yana jin ɗumi. ");
INSERT INTO hausa_vpl VALUES ("JN18_19","073_18_19","JHN","18","19","19","Ana cikin haka, sai babban firist ya tuhumi Yesu game da almajiransa da kuma koyarwarsa. ");
INSERT INTO hausa_vpl VALUES ("JN18_20","073_18_20","JHN","18","20","20","Yesu ya amsa ya ce, “Ai, na yi wa duniya magana a fili. Na kuma sha yin koyarwa a majami’u ko kuma a haikali inda Yahudawa duka sukan taru. Ban taɓa faɗin kome a ɓoye ba. ");
INSERT INTO hausa_vpl VALUES ("JN18_21","073_18_21","JHN","18","21","21","Don me kake tuhumata? Ka tambayi waɗanda suka ji ni. Ba shakka, sun san abin da na faɗa.” ");
INSERT INTO hausa_vpl VALUES ("JN18_22","073_18_22","JHN","18","22","22","Da Yesu ya faɗa haka, sai ɗaya daga cikin ma’aikatan da yake tsaye kusa ya mare shi a fuska ya ce, “Haka za ka amsa wa babban firist?” ");
INSERT INTO hausa_vpl VALUES ("JN18_23","073_18_23","JHN","18","23","23","Yesu ya amsa ya ce, “In na faɗi abin da ba daidai ba, ka nuna abin da ba daidai ba. Amma in gaskiya na faɗa, don me ka mare ni?” ");
INSERT INTO hausa_vpl VALUES ("JN18_24","073_18_24","JHN","18","24","24","Sai Annas ya aika da shi, a daure, wurin Kayifas babban firist. ");
INSERT INTO hausa_vpl VALUES ("JN18_25","073_18_25","JHN","18","25","25","Da Siman Bitrus yana nan tsaye yana jin ɗumin wuta, sai aka tambaye shi, “Kai, kai ma ba ɗaya daga cikin almajiransa ba ne?” Sai ya yi mūsu, yana cewa, “Sam, ba na ciki.” ");
INSERT INTO hausa_vpl VALUES ("JN18_26","073_18_26","JHN","18","26","26","Sai wani daga cikin bayin babban firist dangin wanda Bitrus ya sare wa kunne, ya tambaya shi ya ce, “Kana tsammani ban gan ka tare da shi a gonar zaitun ba?” ");
INSERT INTO hausa_vpl VALUES ("JN18_27","073_18_27","JHN","18","27","27","Bitrus ya sāke yin mūsu, nan take kuwa zakara ya yi cara. ");
INSERT INTO hausa_vpl VALUES ("JN18_28","073_18_28","JHN","18","28","28","Sa’an nan Yahudawa suka fitar da Yesu daga wurin Kayifas zuwa fadar gwamnar Roma. A yanzu dai, safiya ta yi, don gudu kada su ƙazantar da kansu Yahudawa ba su shiga cikin fadar ba; sun so su iya ci Bikin Ƙetarewa. ");
INSERT INTO hausa_vpl VALUES ("JN18_29","073_18_29","JHN","18","29","29","Saboda haka Bilatus ya fito wajensu ya ce, “Wace ƙara kuke kawowa game da mutumin nan?” ");
INSERT INTO hausa_vpl VALUES ("JN18_30","073_18_30","JHN","18","30","30","Suka amsa suka ce, “Da a ce shi ba mai laifi ba ne, ai, da ba mu bashe shi gare ka ba.” ");
INSERT INTO hausa_vpl VALUES ("JN18_31","073_18_31","JHN","18","31","31","Bilatus ya ce, “Ku tafi da shi da kanku mana, ku hukunta shi bisa ga dokarku.” Sai Yahudawa suka ƙi suka ce, “Ba mu da ikon yanke wa wani hukuncin kisa.” ");
INSERT INTO hausa_vpl VALUES ("JN18_32","073_18_32","JHN","18","32","32","Wannan kuwa ya faru ne don a cika kalmomin da Yesu ya yi da suka nuna irin mutuwar da zai yi. ");
INSERT INTO hausa_vpl VALUES ("JN18_33","073_18_33","JHN","18","33","33","Sai Bilatus ya koma cikin fada, ya kira Yesu ya tambaye shi, “Shin, kai ne sarkin Yahudawa?” ");
INSERT INTO hausa_vpl VALUES ("JN18_34","073_18_34","JHN","18","34","34","Yesu ya yi tambaya ya ce, “Wannan ra’ayin kanka ne, ko waɗansu ne suka yi maka magana game da ni?” ");
INSERT INTO hausa_vpl VALUES ("JN18_35","073_18_35","JHN","18","35","35","Bilatus ya amsa ya ce, “Ni mutumin Yahuda ne? Ai, mutanenka ne da kuma manyan firistoci suka bashe ka gare ni. Me ka yi?” ");
INSERT INTO hausa_vpl VALUES ("JN18_36","073_18_36","JHN","18","36","36","Yesu ya ce, “Mulkina ba na duniyan nan ba ne. Da na duniyan nan ne da bayina sun yi yaƙi su hana Yahudawa kama ni. Amma fa mulkina daga wani waje ne.” ");
INSERT INTO hausa_vpl VALUES ("JN18_37","073_18_37","JHN","18","37","37","Sai Bilatus ya ce, “To, wato, kai sarki ne!” Yesu ya amsa ya ce, “Haka yake, ni sarki ne yadda ka faɗa. Tabbatacce, saboda wannan dalili ne aka haife ni, kuma don wannan ne na zo duniya, domin in shaidi gaskiya. Duk wanda yake gefen gaskiya yakan saurare ni.” ");
INSERT INTO hausa_vpl VALUES ("JN18_38","073_18_38","JHN","18","38","38","Bilatus ya tambaye shi ya ce, “Mece ce gaskiya?” Da ya faɗi haka, sai ya sāke fitowa wurin Yahudawa ya ce, “Ni fa ban sami wani abin zargi game da shi ba. ");
INSERT INTO hausa_vpl VALUES ("JN18_39","073_18_39","JHN","18","39","39","Amma fa kuna da wata al’ada in lokacin Bikin Ƙetarewa ya yi, nakan sakar muku da ɗan kurkuku ɗaya. To, kuna so in sakar muku ‘sarkin Yahudawa’?” ");
INSERT INTO hausa_vpl VALUES ("JN18_40","073_18_40","JHN","18","40","40","Sai suka ɗau kururuwa suna cewa, “Kai, ba shi ba! A ba mu Barabbas!” To, Barabbas ɗin nan yana da hannu dumu-dumu a wani tawaye. ");
INSERT INTO hausa_vpl VALUES ("JN19_1","073_19_1","JHN","19","1","1","Sa’an nan Bilatus ya tafi da Yesu ya kuma sa aka yi masa bulala. ");
INSERT INTO hausa_vpl VALUES ("JN19_2","073_19_2","JHN","19","2","2","Sai sojojin suka tuƙa rawanin ƙaya suka sa masa a kā, suka kuma yafa masa wata riga mai ruwan shunayya. ");
INSERT INTO hausa_vpl VALUES ("JN19_3","073_19_3","JHN","19","3","3","Suka yi ta zuwa wurinsa suna cewa, “Ranka yă daɗe, sarkin Yahudawa!” Suna ta marinsa a fuska. ");
INSERT INTO hausa_vpl VALUES ("JN19_4","073_19_4","JHN","19","4","4","Bilatus kuwa ya sāke fitowa ya ce wa Yahudawa, “Ga shi, zan fito muku da shi don ku san cewa ban same shi da wani abin zargi ba.” ");
INSERT INTO hausa_vpl VALUES ("JN19_5","073_19_5","JHN","19","5","5","Sa’ad da Yesu ya fito sanye da rawanin ƙayar da kuma riga mai ruwan shunayya, sai Bilatus ya ce musu, “Ga mutumin!” ");
INSERT INTO hausa_vpl VALUES ("JN19_6","073_19_6","JHN","19","6","6","Nan da nan da manyan firistoci da ma’aikatansu suka gan shi, sai suka yi ihu suka ce, “A gicciye! A gicciye!” Amma Bilatus ya amsa ya ce, “Ku, ku ɗauke shi ku gicciye. Ni dai ban same shi da wani abin zargi ba.” ");
INSERT INTO hausa_vpl VALUES ("JN19_7","073_19_7","JHN","19","7","7","Yahudawa dai suka nace suna cewa, “Mu fa muna da doka, kuma bisa ga dokar dole yă mutu domin ya mai da kansa Ɗan Allah.” ");
INSERT INTO hausa_vpl VALUES ("JN19_8","073_19_8","JHN","19","8","8","Da Bilatus ya ji haka, sai tsoro ya ƙara kama shi, ");
INSERT INTO hausa_vpl VALUES ("JN19_9","073_19_9","JHN","19","9","9","sai ya sāke koma cikin fada. Ya tambayi Yesu, “Daga ina ka fito?” Amma Yesu bai amsa masa ba. ");
INSERT INTO hausa_vpl VALUES ("JN19_10","073_19_10","JHN","19","10","10","Bilatus ya ce, “Ba za ka yi mini magana ba? Ba ka san cewa ina da ikon sakinka, ko gicciye ka ba?” ");
INSERT INTO hausa_vpl VALUES ("JN19_11","073_19_11","JHN","19","11","11","Yesu ya amsa ya ce, “Ba ka da wani iko a kaina, in ba a ba ka daga sama ba. Saboda haka wanda ya bashe ni gare ka, ya fi na zunubi.” ");
INSERT INTO hausa_vpl VALUES ("JN19_12","073_19_12","JHN","19","12","12","Daga nan fa, Bilatus ya yi nemi yă saki Yesu, sai dai Yahudawa suka yi ta ihu suna cewa, “In ka saki wannan mutum, kai ba abokin Kaisar ba ne. Duk wanda ya ɗauka kansa a matsayin sarki, ai, yana gāba da Kaisar ne.” ");
INSERT INTO hausa_vpl VALUES ("JN19_13","073_19_13","JHN","19","13","13","Da Bilatus ya ji haka, sai ya fito da Yesu, ya kuma zauna a kujerar shari’ar da ake ce da shi Daɓen Dutse (wanda a harshen Arameyik ana ce da shi Gabbata). ");
INSERT INTO hausa_vpl VALUES ("JN19_14","073_19_14","JHN","19","14","14","Ranar Shirye-shiryen Makon Bikin Ƙetarewa ce kuwa, wajen sa’a ta shida. Sai Bilatus ya ce wa Yahudawa, “Ga sarkinku.” ");
INSERT INTO hausa_vpl VALUES ("JN19_15","073_19_15","JHN","19","15","15","Amma suka yi ihu suka ce, “A yi da shi! A yi da shi! A gicciye shi!” Bilatus ya ce, “A! In gicciye sarkinku?” Sai manyan firistoci suka amsa suka ce, “Mu dai, ba mu da wani sarki sai Kaisar.” ");
INSERT INTO hausa_vpl VALUES ("JN19_16","073_19_16","JHN","19","16","16","A ƙarshe Bilatus ya ba da shi gare su a gicciye shi. Saboda haka sojoji suka tafi da Yesu. ");
INSERT INTO hausa_vpl VALUES ("JN19_17","073_19_17","JHN","19","17","17","Ɗauke da gicciyensa, ya kuwa fita zuwa wurin Ƙoƙon Kai (wanda a harshen Arameya ana ce da shi Golgota). ");
INSERT INTO hausa_vpl VALUES ("JN19_18","073_19_18","JHN","19","18","18","Nan suka gicciye shi tare da waɗansu mutum biyu, ɗaya a kowane gefe da Yesu a tsakiya. ");
INSERT INTO hausa_vpl VALUES ("JN19_19","073_19_19","JHN","19","19","19","Bilatus ya sa aka rubuta wata sanarwa aka kafa a kan gicciyen. Abin da aka rubuta kuwa shi ne, Yesu Banazare, Sarkin Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("JN19_20","073_19_20","JHN","19","20","20","Yahudawa da yawa suka karanta wannan sanarwa, gama inda aka gicciye Yesu yana kusa da birni. An kuwa rubuta sanarwar da Arameyanci, Romanci da kuma Girik. ");
INSERT INTO hausa_vpl VALUES ("JN19_21","073_19_21","JHN","19","21","21","Sai manyan firistocin Yahudawa suka ce, “A’a! Kada ka rubuta, ‘Sarkin Yahudawa,’ ka dai rubuta, wannan mutum ya ce shi sarkin Yahudawa ne.” ");
INSERT INTO hausa_vpl VALUES ("JN19_22","073_19_22","JHN","19","22","22","Bilatus ya amsa ya ce, “Abin da na rubuta, na rubuta.” ");
INSERT INTO hausa_vpl VALUES ("JN19_23","073_19_23","JHN","19","23","23","Da sojojin suka gicciye Yesu, sai suka ɗibi tufafinsa suka kasa kashi huɗu, kowanne ya ɗauki kashi ɗaya. Suka kuma ɗauki taguwarsa, taguwar kuwa ba ɗinki, saƙa ɗaya ce gudanta daga sama har ƙasa. ");
INSERT INTO hausa_vpl VALUES ("JN19_24","073_19_24","JHN","19","24","24","Sai suka ce wa juna, “Kada mu yage ta, sai dai mu jefa ƙuri’a a kanta mu ga wanda zai ci.” Wannan ya faru ne don a cika nassin da ya ce, “Suka rarraba tufafina a junansu, suka kuma jefa ƙuri’a a kan rigata.” Abin da sojojin suka yi ke nan. ");
INSERT INTO hausa_vpl VALUES ("JN19_25","073_19_25","JHN","19","25","25","To, tsaye kusa da gicciyen Yesu kuwa akwai mahaifiyarsa, tare da ’yar’uwar mahaifiyarsa, Maryamu matar Kilofas, da kuma Maryamu Magdalin. ");
INSERT INTO hausa_vpl VALUES ("JN19_26","073_19_26","JHN","19","26","26","Sa’ad da Yesu ya ga mahaifiyarsa a can, da kuma almajirin nan da yake ƙauna tsaye kusa, sai ya ce wa mahaifiyarsa, “Mace, ga ɗanki,” ");
INSERT INTO hausa_vpl VALUES ("JN19_27","073_19_27","JHN","19","27","27","ga almajirin kuwa ya ce, “Ga mahaifiyarka.” Tun daga wannan lokaci fa almajirin nan ya kai ta gidansa. ");
INSERT INTO hausa_vpl VALUES ("JN19_28","073_19_28","JHN","19","28","28","Bayan haka, sanin cewa an cika kome, kuma domin a cika Nassi, sai Yesu ya ce, “Ina jin ƙishirwa.” ");
INSERT INTO hausa_vpl VALUES ("JN19_29","073_19_29","JHN","19","29","29","To, akwai wani tulun ruwan tsami ajiye a can, saboda haka suka jiƙa soso da shi, suka soka soson a sandan itacen hizzob, suka kai bakin Yesu. ");
INSERT INTO hausa_vpl VALUES ("JN19_30","073_19_30","JHN","19","30","30","Da ya tsotsi abin sha ɗin, sai Yesu ya ce, “An gama.” Da wannan fa, ya sunkuyar da kansa ya saki ruhunsa. ");
INSERT INTO hausa_vpl VALUES ("JN19_31","073_19_31","JHN","19","31","31","To, ranan nan fa, ranar Shirye-shirye ce, kashegari kuma muhimmin Asabbaci ne. Domin Yahudawa ba sa so a bar jikunan a kan gicciyoyi a Asabbaci, sai suka roƙi Bilatus a kakkarye ƙafafunsu kuma sauko da jikunan. ");
INSERT INTO hausa_vpl VALUES ("JN19_32","073_19_32","JHN","19","32","32","Sai sojoji suka zo suka karya ƙafafun mutum na farko da aka gicciye tare da Yesu, da kuma na ɗayan. ");
INSERT INTO hausa_vpl VALUES ("JN19_33","073_19_33","JHN","19","33","33","Amma sa’ad da suka zo kan Yesu suka tarar ya riga ya mutu, ba su karya ƙafafunsa ba. ");
INSERT INTO hausa_vpl VALUES ("JN19_34","073_19_34","JHN","19","34","34","A maimako, sai ɗaya daga cikin sojojin ya soki Yesu a gefe da māshi, nan take jini da ruwa suka fito. ");
INSERT INTO hausa_vpl VALUES ("JN19_35","073_19_35","JHN","19","35","35","Mutumin da ya gani ɗin shi ya ba da shaida, shaidarsa kuwa gaskiya ce. Ya san gaskiya yake faɗa, yana kuma ba da shaidar domin ku ma ku gaskata. ");
INSERT INTO hausa_vpl VALUES ("JN19_36","073_19_36","JHN","19","36","36","Waɗannan abubuwa sun faru don a cika Nassi ne cewa, “Ba ko ɗaya daga cikin ƙasusuwansa da za a karya,” ");
INSERT INTO hausa_vpl VALUES ("JN19_37","073_19_37","JHN","19","37","37","kuma kamar yadda wani Nassi ya ce, “Za su dubi wanda suka soka.” ");
INSERT INTO hausa_vpl VALUES ("JN19_38","073_19_38","JHN","19","38","38","Bayan haka, Yusuf mutumin Arimateya ya roƙi Bilatus a ba shi jikin Yesu. Yusuf dai almajirin Yesu ne, amma a ɓoye domin yana tsoron Yahudawa. Da izinin Bilatus, ya zo ya ɗauki jikin. ");
INSERT INTO hausa_vpl VALUES ("JN19_39","073_19_39","JHN","19","39","39","Yana tare da Nikodimus, wannan da ya taɓa zuwa wurin Yesu da dare. Nikodimus ya zo da mur da aloyes a gauraye, wajen awo ɗari. ");
INSERT INTO hausa_vpl VALUES ("JN19_40","073_19_40","JHN","19","40","40","Da ɗaukowar jikin Yesu, sai su biyun suka nannaɗe shi tare da kayan ƙanshi a cikin ƙyallayen lilin bisa ga al’adar Yahudawa ta jana’iza. ");
INSERT INTO hausa_vpl VALUES ("JN19_41","073_19_41","JHN","19","41","41","A inda aka gicciye Yesu, akwai wani lambu, a cikin lambun kuwa akwai sabon kabari, wanda ba a taɓa sa kowa ba. ");
INSERT INTO hausa_vpl VALUES ("JN19_42","073_19_42","JHN","19","42","42","Da yake ranan nan, ranar Shirye-shirye ce ta Yahudawa, kabarin kuma yana kusa, sai suka binne Yesu a can. ");
INSERT INTO hausa_vpl VALUES ("JN20_1","073_20_1","JHN","20","1","1","Da sassafe a ranar farko ta mako, tun da sauran duhu, Maryamu Magdalin ta tafi kabarin ta kuwa tarar an kawar da dutsen daga bakin kabarin. ");
INSERT INTO hausa_vpl VALUES ("JN20_2","073_20_2","JHN","20","2","2","Sai ta zo da gudu wajen Siman Bitrus da ɗayan almajirin, wanda Yesu yake ƙauna, ta ce, “Sun ɗauke Ubangiji daga kabarin, ba mu kuma san inda suka sa shi ba!” ");
INSERT INTO hausa_vpl VALUES ("JN20_3","073_20_3","JHN","20","3","3","Sai Bitrus da almajirin nan suka nufi kabarin. ");
INSERT INTO hausa_vpl VALUES ("JN20_4","073_20_4","JHN","20","4","4","Dukansu biyu suna gudu, amma ɗayan almajirin ya tsere wa Bitrus ya kuma fara kai kabarin. ");
INSERT INTO hausa_vpl VALUES ("JN20_5","073_20_5","JHN","20","5","5","Ya sunkuya ya duba ciki ya ga ƙyallayen lilin ne kwance a can amma bai shiga ba. ");
INSERT INTO hausa_vpl VALUES ("JN20_6","073_20_6","JHN","20","6","6","Sa’an nan Siman Bitrus, wanda yake bayansa, ya iso ya kuwa wuce cikin kabarin. Ya ga ƙyallayen lilin kwance a can, ");
INSERT INTO hausa_vpl VALUES ("JN20_7","073_20_7","JHN","20","7","7","haka ma zanen binnewar da aka naɗe kan Yesu da shi. Zanen a naɗe yake shi kaɗai, a keɓe da lilin ɗin. ");
INSERT INTO hausa_vpl VALUES ("JN20_8","073_20_8","JHN","20","8","8","A ƙarshe sai almajirin nan, wanda ya kai kabarin da farko, shi ma ya shiga. Ya gani ya kuma gaskata. ");
INSERT INTO hausa_vpl VALUES ("JN20_9","073_20_9","JHN","20","9","9","(Har yanzu ba su fahimci Nassin nan da ya ce lalle ne Yesu yă tashi daga matattu ba.) ");
INSERT INTO hausa_vpl VALUES ("JN20_10","073_20_10","JHN","20","10","10","Sai almajiran suka koma zuwa inda suke zama. ");
INSERT INTO hausa_vpl VALUES ("JN20_11","073_20_11","JHN","20","11","11","Maryamu kuwa ta tsaya a bakin kabarin daga waje tana kuka. Da tana cikin kuka, sai ta sunkuya ta leƙa cikin kabarin, ");
INSERT INTO hausa_vpl VALUES ("JN20_12","073_20_12","JHN","20","12","12","sai ta ga waɗansu mala’iku biyu saye da fararen tufafi, zaune a inda dā gawar Yesu take, ɗaya wajen kai ɗayan kuma wajen ƙafafu. ");
INSERT INTO hausa_vpl VALUES ("JN20_13","073_20_13","JHN","20","13","13","Suka tambaye ta cewa, “Mace, don me kike kuka?” Ta ce, “Sun ɗauke Ubangijina, ban kuma san inda suka ajiye shi ba.” ");
INSERT INTO hausa_vpl VALUES ("JN20_14","073_20_14","JHN","20","14","14","Da ta faɗin haka, sai ta juya ta ga Yesu tsaye, sai dai ba tă gane cewa Yesu ne ba. ");
INSERT INTO hausa_vpl VALUES ("JN20_15","073_20_15","JHN","20","15","15","Sai ya ce, “Mace, don me kike kuka? Wa kike nema?” Ta yi tsammani shi ne mai aikin lambun, sai ta ce, “Ranka yă daɗe, in kai ne ka ɗauke shi, gaya mini inda ka ajiye shi, in je in ɗauke shi.” ");
INSERT INTO hausa_vpl VALUES ("JN20_16","073_20_16","JHN","20","16","16","Yesu ya ce mata, “Maryamu.” Sai ta juya wajensa ta ɗaga murya ta ce da Arameyanci, “Rabboni!” (Wanda yake nufin “Malam”). ");
INSERT INTO hausa_vpl VALUES ("JN20_17","073_20_17","JHN","20","17","17","Yesu ya ce, “Kada ki riƙe ni, gama ban riga na koma wajen Uba tukuna ba. A maimako, ki tafi wajen ’yan’uwana ki gaya musu, ‘Ina komawa wajen Ubana da Ubanku, wajen Allahna da kuma Allahnku.’ ” ");
INSERT INTO hausa_vpl VALUES ("JN20_18","073_20_18","JHN","20","18","18","Sai Maryamu Magdalin ta wajen almajiran da labari cewa, “Na ga Ubangiji!” Ta kuma gaya musu cewa ya faɗa mata waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("JN20_19","073_20_19","JHN","20","19","19","Da Yamman ranar farko ta mako, sa’ad da almajiran suna tare, ƙofofi kuma suna a kulle saboda tsoron Yahudawa, sai ga Yesu ya zo ya tsaya a tsakiyarsu ya ce, “Salama tă kasance tare da ku!” ");
INSERT INTO hausa_vpl VALUES ("JN20_20","073_20_20","JHN","20","20","20","Bayan ya faɗa haka, sai ya nuna musu hannuwansa da gefensa. Sai almajiran suka yi farin ciki ƙwarai da suka ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JN20_21","073_20_21","JHN","20","21","21","Sai Yesu ya sāke ce musu, “Salama tă kasance tare da ku! Kamar yadda Uba ya aiko ni, haka ni ma ina aikan ku.” ");
INSERT INTO hausa_vpl VALUES ("JN20_22","073_20_22","JHN","20","22","22","Da wannan sai ya hura musu numfashinsa ya ce, “Ku karɓi Ruhu Mai Tsarki. ");
INSERT INTO hausa_vpl VALUES ("JN20_23","073_20_23","JHN","20","23","23","Duk wanda kuka gafarta wa zunubansa, an gafarta masa ke nan. Duk wanda ba ku gafarta wa ba kuwa, ba a gafarta masa ba ke nan.” ");
INSERT INTO hausa_vpl VALUES ("JN20_24","073_20_24","JHN","20","24","24","Toma kuwa (wanda ake kira Didaimus), ɗaya daga cikin Sha Biyun, ba ya tare da almajiran sa’ad da Yesu ya zo. ");
INSERT INTO hausa_vpl VALUES ("JN20_25","073_20_25","JHN","20","25","25","Saboda haka sauran almajiran suka ce masa, “Ai, mun ga Ubangiji!” Amma ya ce musu, “Ina, ai, sai na ga ramin ƙusa a hannuwansa na sa yatsata a inda ƙusoshi suka kasance, na kuma sa hannuna a gefensa, in ba haka ba, ba zan gaskata ba.” ");
INSERT INTO hausa_vpl VALUES ("JN20_26","073_20_26","JHN","20","26","26","Bayan mako guda, har wa yau almajiransa suna cikin gidan, Toma kuwa yana tare da su. Ko da yake ƙofofi suna kulle, sai ga Yesu ya zo ya tsaya a tsakiyarsu ya ce, “Salama tă kasance tare da ku!” ");
INSERT INTO hausa_vpl VALUES ("JN20_27","073_20_27","JHN","20","27","27","Sa’an nan ya ce wa Toma, “Sa yatsarka nan; dubi hannuwana. Miƙa hannunka ka sa a gefena. Ka daina shakka ka gaskata.” ");
INSERT INTO hausa_vpl VALUES ("JN20_28","073_20_28","JHN","20","28","28","Toma ya ce masa, “Ya Ubangijina da Allahna!” ");
INSERT INTO hausa_vpl VALUES ("JN20_29","073_20_29","JHN","20","29","29","Sai Yesu ya ce masa, “Wato ka gaskata saboda ka gan ni ne, masu albarka ne waɗanda ba su gan ni ba, amma suka gaskata.” ");
INSERT INTO hausa_vpl VALUES ("JN20_30","073_20_30","JHN","20","30","30","Yesu ya yi waɗansu abubuwan banmamaki da yawa a gaban almajiransa da ba a rubuta a wannan littafi ba. ");
INSERT INTO hausa_vpl VALUES ("JN20_31","073_20_31","JHN","20","31","31","An dai rubuta waɗannan ne don ku gaskata Yesu ne Kiristi, Ɗan Allah kuma ta wurin gaskatawa ku sami rai a cikin sunansa. ");
INSERT INTO hausa_vpl VALUES ("JN21_1","073_21_1","JHN","21","1","1","Daga baya Yesu ya sāke bayyana kansa ga almajiransa, a bakin Tekun Tibariya. Ga yadda ya faru. ");
INSERT INTO hausa_vpl VALUES ("JN21_2","073_21_2","JHN","21","2","2","Siman Bitrus, Toma (wanda ake kira Didaimus), Natanayel daga Kana ta Galili, ’ya’yan Zebedi maza, da kuma waɗansu almajirai guda biyu suna tare. ");
INSERT INTO hausa_vpl VALUES ("JN21_3","073_21_3","JHN","21","3","3","Sai Siman Bitrus ya ce musu, “Za ni kamun kifi,” suka ce, “Za mu tafi tare da kai.” Saboda haka suka fita suka shiga jirgin ruwa, amma a daren nan ba su kama kome ba. ");
INSERT INTO hausa_vpl VALUES ("JN21_4","073_21_4","JHN","21","4","4","Da sassafe, sai ga Yesu tsaye a gaci, amma almajiran ba su gane cewa Yesu ne ba. ");
INSERT INTO hausa_vpl VALUES ("JN21_5","073_21_5","JHN","21","5","5","Sai ya ce musu, “Abokai, kuna da kifi kuwa?” Suka amsa suka ce, “A’a.” ");
INSERT INTO hausa_vpl VALUES ("JN21_6","073_21_6","JHN","21","6","6","Ya ce musu, “Ku jefa abin kamun kifinku dama da jirgin ruwan, za ku samu.” Da suka yi haka, sai suka kāsa jawo abin kamun kifin saboda yawan kifi. ");
INSERT INTO hausa_vpl VALUES ("JN21_7","073_21_7","JHN","21","7","7","Sai almajirin da Yesu yake ƙauna ya ce wa Bitrus, “Ai, Ubangiji ne!” Nan da nan da Siman Bitrus ya ji ya ce, “Ai, Ubangiji ne,” sai ya yafa mayafinsa (don dā ma ya tuɓe shi), ya fāɗa cikin ruwan. ");
INSERT INTO hausa_vpl VALUES ("JN21_8","073_21_8","JHN","21","8","8","Sauran almajiran kuwa suka bi shi cikin jirgin ruwan, janye da abin kamun kifin cike da kifi, don ba su da nisa daga gaci, wajen yadi ɗari ne. ");
INSERT INTO hausa_vpl VALUES ("JN21_9","073_21_9","JHN","21","9","9","Da suka sauka, sai suka ga garwashin wuta a can da kifi a kai, da kuma ’yan burodi. ");
INSERT INTO hausa_vpl VALUES ("JN21_10","073_21_10","JHN","21","10","10","Yesu ya ce musu, “Ku kawo waɗansu kifin da kuka kama yanzu.” ");
INSERT INTO hausa_vpl VALUES ("JN21_11","073_21_11","JHN","21","11","11","Sai Siman Bitrus ya hau ya jawo abin kamun kifin gaci. Ya cika da manyan kifi, 153, amma duk da yawansun nan abin kamun kifin bai tsintsinke ba. ");
INSERT INTO hausa_vpl VALUES ("JN21_12","073_21_12","JHN","21","12","12","Yesu ya ce musu, “Ku zo ku karya kumallo.” Ba wani daga cikin almajiran da ya yi karambanin tambayarsa, “Wane ne kai?” Sun san cewa Ubangiji ne. ");
INSERT INTO hausa_vpl VALUES ("JN21_13","073_21_13","JHN","21","13","13","Yesu ya zo, ya ɗauki burodin ya ba su, haka kuma kifin. ");
INSERT INTO hausa_vpl VALUES ("JN21_14","073_21_14","JHN","21","14","14","Wannan fa shi ne sau na uku da Yesu ya bayyana kansa ga almajiransa bayan an tashe shi daga matattu. ");
INSERT INTO hausa_vpl VALUES ("JN21_15","073_21_15","JHN","21","15","15","Da suka gama ci, sai Yesu ya ce wa Siman Bitrus, “Siman ɗan Yohanna, kana ƙaunata da gaske fiye da waɗannan?” Ya ce, “I, Ubangiji, ka san cewa ina sonka.” Yesu ya ce, “Ciyar da ’ya’yan tumakina.” ");
INSERT INTO hausa_vpl VALUES ("JN21_16","073_21_16","JHN","21","16","16","Har wa yau Yesu ya ce, “Siman ɗan Yohanna, kana ƙaunata da gaske?” Ya amsa ya ce, “I, Ubangiji, ka san cewa ina sonka.” Yesu ya ce, “Lura da tumakina.” ");
INSERT INTO hausa_vpl VALUES ("JN21_17","073_21_17","JHN","21","17","17","Sau na uku ya ce masa, “Siman ɗan Yohanna, kana ƙaunata?” Sai Bitrus ya ɓata rai saboda Yesu ya tambaye shi sau na uku, “Kana ƙaunata?” Ya ce, “Ubangiji ka san kome duka; ka san cewa, ina ƙaunarka.” Yesu ya ce, “Ciyar da tumakina. ");
INSERT INTO hausa_vpl VALUES ("JN21_18","073_21_18","JHN","21","18","18","Gaskiya nake faɗa maka, sa’ad da kake saurayi kakan yi wa kanka sutura ka tafi inda ka so; amma sa’ad da ka tsufa za ka miƙa hannuwanka, wani dabam yă yi maka sutura yă kai ka inda ba ka so.” ");
INSERT INTO hausa_vpl VALUES ("JN21_19","073_21_19","JHN","21","19","19","Yesu ya faɗi wannan ne, don yă nuna irin mutuwar da Bitrus zai yi yă ɗaukaka Allah. Sa’an nan ya ce masa, “Bi ni!” ");
INSERT INTO hausa_vpl VALUES ("JN21_20","073_21_20","JHN","21","20","20","Bitrus ya juya ya ga cewa almajirin nan da Yesu yake ƙauna yana binsu. (Wannan ne ya jingina a jikin Yesu sa’ad da suke cin abincin yamman nan da ya ce, “Ubangiji wane ne zai bashe ka?”) ");
INSERT INTO hausa_vpl VALUES ("JN21_21","073_21_21","JHN","21","21","21","Da Bitrus ya gan shi sai ya ce, “Ubangiji, wannan fa?” ");
INSERT INTO hausa_vpl VALUES ("JN21_22","073_21_22","JHN","21","22","22","Yesu ya amsa ya ce, “Idan na so yă kasance da rai har in dawo, mene ne naka a ciki? Kai dai bi ni.” ");
INSERT INTO hausa_vpl VALUES ("JN21_23","073_21_23","JHN","21","23","23","Saboda wannan, jita-jita ta bazu a cikin ’yan’uwa cewa wannan almajirin ba zai mutu ba. Amma fa Yesu bai ce ba zai mutu ba; shi dai ya ce, “In na so yă kasance da rai har in dawo, mene ne naka a ciki?” ");
INSERT INTO hausa_vpl VALUES ("JN21_24","073_21_24","JHN","21","24","24","Wannan shi ne almajirin da ya ba da shaida a kan waɗannan abubuwa ya kuma rubuta su. Mun san cewa shaidarsa gaskiya ce. ");
INSERT INTO hausa_vpl VALUES ("JN21_25","073_21_25","JHN","21","25","25","Yesu ya yi waɗansu abubuwa da yawa kuma. Da a ce an rubuta kowannensu, na tabbata ko duniya duka ba za tă sami wuri saboda littattafan da za a rubuta ba.");
INSERT INTO hausa_vpl VALUES ("AC1_1","074_1_1","ACT","1","1","1","A littafina na farko, Tiyofilus, na rubuta game da dukan abin da Yesu ya fara yi, da abin da ya koyar ");
INSERT INTO hausa_vpl VALUES ("AC1_2","074_1_2","ACT","1","2","2","har zuwa ranar da aka ɗauke shi zuwa sama, bayan ya ba da umarnai ta wurin Ruhu Mai Tsarki ga manzannin da ya zaɓa. ");
INSERT INTO hausa_vpl VALUES ("AC1_3","074_1_3","ACT","1","3","3","Bayan wahalarsa, ya bayyana kansa ga waɗannan mutane ya kuma ba da tabbatattun alamu masu yawa cewa yana da rai. Ya bayyana a gare su har kwana arba’in ya kuma yi musu magana game da mulkin Allah. ");
INSERT INTO hausa_vpl VALUES ("AC1_4","074_1_4","ACT","1","4","4","A wani lokaci, yayinda yake ci tare da su, ya ba su wannan umarni, “Kada ku bar Urushalima, amma ku jira kyautar da Ubana ya yi alkawari, wadda kuka ji na yi magana a kai. ");
INSERT INTO hausa_vpl VALUES ("AC1_5","074_1_5","ACT","1","5","5","Gama Yohanna ya yi baftisma daruwa, amma a cikin ’yan kwanaki za a yi muku baftisma da Ruhu Mai Tsarki.” ");
INSERT INTO hausa_vpl VALUES ("AC1_6","074_1_6","ACT","1","6","6","Saboda haka, sa’ad da suka taru, sai suka tambaye shi, “Ubangiji, a wannan lokaci za ka mayar da mulki ga Isra’ila?” ");
INSERT INTO hausa_vpl VALUES ("AC1_7","074_1_7","ACT","1","7","7","Ya ce musu, “Ba naku ba ne ku san lokuta ko ranakun da Uban ya shirya cikin ikonsa. ");
INSERT INTO hausa_vpl VALUES ("AC1_8","074_1_8","ACT","1","8","8","Amma ku za ku karɓi iko sa’ad da Ruhu Mai Tsarki ya sauka a kanku; za ku kuma zama shaiduna cikin Urushalima, da kuma cikin dukan Yahudiya da Samariya, zuwa kuma iyakar duniya.” ");
INSERT INTO hausa_vpl VALUES ("AC1_9","074_1_9","ACT","1","9","9","Bayan ya faɗi wannan, sai aka ɗauke shi sama a idanunsu sai wani girgije ya rufe shi daga ganinsu. ");
INSERT INTO hausa_vpl VALUES ("AC1_10","074_1_10","ACT","1","10","10","Suna zuba ido a bisa, zuwa cikin sararin sama yayinda yake tafiya, nan da nan, sai ga mutane biyu saye da fararen riguna tsaye kusa da su. ");
INSERT INTO hausa_vpl VALUES ("AC1_11","074_1_11","ACT","1","11","11","Sai suka ce, “Mutanen Galili, don me kuke tsaye a nan kuna duban sararin sama? Wannan Yesu, wanda aka ɗauke daga gare ku zuwa sama, zai komo daidai yadda kuka ga ya tafi sama.” ");
INSERT INTO hausa_vpl VALUES ("AC1_12","074_1_12","ACT","1","12","12","Sai suka koma Urushalima daga tudun da ake kira Dutsen Zaitun, tafiyar ranar Asabbaci guda daga birnin. ");
INSERT INTO hausa_vpl VALUES ("AC1_13","074_1_13","ACT","1","13","13","Da suka iso, sai suka hau gidan sama, zuwa ɗakin da suke zama. Waɗanda suka kasance kuwa su ne, Bitrus, Yohanna, Yaƙub da Andarawus; Filibus da Toma; Bartolomeyu da Mattiyu; Yaƙub ɗan Alfayus da Siman Zilot, da kuma Yahuda ɗan Yaƙub. ");
INSERT INTO hausa_vpl VALUES ("AC1_14","074_1_14","ACT","1","14","14","Waɗannan duka suka duƙufa cikin addu’a, tare da waɗansu mata da Maryamu mahaifiyar Yesu, da kuma tare da ’yan’uwansa. ");
INSERT INTO hausa_vpl VALUES ("AC1_15","074_1_15","ACT","1","15","15","A waɗancan kwanakin Bitrus ya miƙe tsaye cikin ’yan’uwa masu bi (taron da ya yi kusan mutum ɗari da ashirin) ");
INSERT INTO hausa_vpl VALUES ("AC1_16","074_1_16","ACT","1","16","16","ya ce, “’Yan’uwana, dole a cika Nassin nan da Ruhu Mai Tsarki ya yi magana tun da daɗewa ta bakin Dawuda game da Yahuda, wanda ya zama jagora ga waɗanda suka kama Yesu ");
INSERT INTO hausa_vpl VALUES ("AC1_17","074_1_17","ACT","1","17","17","dā shi ɗaya ne cikinmu, ya kuma yi hidima a cikin aikin nan.” ");
INSERT INTO hausa_vpl VALUES ("AC1_18","074_1_18","ACT","1","18","18","(Da ladar da ya samu saboda muguntarsa Yahuda ya sayi wani fili; a can ya fāɗi da kā, jikinsa ya fashe, hanjinsa kuma duk suka zubo. ");
INSERT INTO hausa_vpl VALUES ("AC1_19","074_1_19","ACT","1","19","19","Kowa a Urushalima ya ji game da wannan, saboda haka suka kira wannan filin Akeldama, da yarensu, wato, Filin Jini.) ");
INSERT INTO hausa_vpl VALUES ("AC1_20","074_1_20","ACT","1","20","20","Bitrus ya ce, “Gama yana a rubuce a cikin Littafin Zabura cewa, “ ‘Bari wurinsa yă zama babu kowa; kada kowa ya zauna a cikinsa,’ kuma, “ ‘Bari wani ya ɗauki matsayinsa na shugabanci.’ ");
INSERT INTO hausa_vpl VALUES ("AC1_21","074_1_21","ACT","1","21","21","Saboda haka dole a zaɓi ɗaya daga cikin mutanen da suke tare da mu duk lokacin da Ubangiji Yesu yake shiga da fita a cikinmu, ");
INSERT INTO hausa_vpl VALUES ("AC1_22","074_1_22","ACT","1","22","22","farawa daga baftisma ta Yohanna har zuwa sa’ad da aka ɗauke Yesu daga gare mu. Gama dole ɗaya daga waɗannan ya zama shaidar tashinsa daga matattu tare da mu.” ");
INSERT INTO hausa_vpl VALUES ("AC1_23","074_1_23","ACT","1","23","23","Saboda haka suka gabatar da mutane biyu. Yusuf mai suna Barsabbas (da aka kuma sani da Yustus) da kuma Mattiyas. ");
INSERT INTO hausa_vpl VALUES ("AC1_24","074_1_24","ACT","1","24","24","Sai suka yi addu’a suka ce, “Ubangiji, ka san zuciyar kowa. Nuna mana wanne a cikin waɗannan biyu da ka zaɓa ");
INSERT INTO hausa_vpl VALUES ("AC1_25","074_1_25","ACT","1","25","25","ya karɓi wannan aikin manzanci, wanda Yahuda ya bari don yă tafi wurin da yake nasa.” ");
INSERT INTO hausa_vpl VALUES ("AC1_26","074_1_26","ACT","1","26","26","Sa’an nan suka jefa ƙuri’u, ƙuri’ar kuwa ta fāɗo a kan Mattiyas; sai aka sa shi cikin manzannin nan goma sha ɗaya. ");
INSERT INTO hausa_vpl VALUES ("AC2_1","074_2_1","ACT","2","1","1","Da ranar Fentekos ta yi, dukansu suna tare wuri ɗaya. ");
INSERT INTO hausa_vpl VALUES ("AC2_2","074_2_2","ACT","2","2","2","Ba zato ba tsammani sai aka ji motsi kamar ta babbar iska tana hurowa daga sama ta kuma cika dukan gidan da suke zaune. ");
INSERT INTO hausa_vpl VALUES ("AC2_3","074_2_3","ACT","2","3","3","Suka ga wani abin da ya yi kama da harsunan wuta, suka rarrabu suna kuma sassauka a kan kowannensu. ");
INSERT INTO hausa_vpl VALUES ("AC2_4","074_2_4","ACT","2","4","4","Dukansu kuwa suka cika da Ruhu Mai Tsarki suka kuma fara magana da waɗansu harsuna yadda Ruhu ya sa suka iya. ");
INSERT INTO hausa_vpl VALUES ("AC2_5","074_2_5","ACT","2","5","5","To, a Urushalima akwai Yahudawa masu tsoron Allah, daga kowace ƙasa a duniya. ");
INSERT INTO hausa_vpl VALUES ("AC2_6","074_2_6","ACT","2","6","6","Da suka ji wannan motsi, taro ya haɗu wuri ɗaya a ruɗe, domin kowannensu ya ji suna magana da yarensa. ");
INSERT INTO hausa_vpl VALUES ("AC2_7","074_2_7","ACT","2","7","7","Cike da mamaki, suka yi tambaya suna cewa, “Ashe, duk waɗannan mutane masu magana ba Galiliyawa ba ne? ");
INSERT INTO hausa_vpl VALUES ("AC2_8","074_2_8","ACT","2","8","8","To, yaya kowannenmu yana ji suna yarensa? ");
INSERT INTO hausa_vpl VALUES ("AC2_9","074_2_9","ACT","2","9","9","Fartiyawa, Medes da Elamawa; mazaunan Mesofotamiya, Yahudiya da Kaffadokiya, Fontus da Asiya, ");
INSERT INTO hausa_vpl VALUES ("AC2_10","074_2_10","ACT","2","10","10","Firjiya da Famfiliya, Masar da sassa Libiya kusa da Sairin; baƙi daga Roma ");
INSERT INTO hausa_vpl VALUES ("AC2_11","074_2_11","ACT","2","11","11","(Yahudawa da kuma waɗanda suka tuba suka shiga Yahudanci); Kiretawa da Larabawa, mun ji su suna shelar abubuwan banmamaki na Allah da yarenmu!” ");
INSERT INTO hausa_vpl VALUES ("AC2_12","074_2_12","ACT","2","12","12","A ruɗe kuma cike da mamaki, suka tambayi junansu cewa, “Mene ne wannan yake nufi?” ");
INSERT INTO hausa_vpl VALUES ("AC2_13","074_2_13","ACT","2","13","13","Duk da haka waɗansu suka yi musu ba’a suka ce, “Sun yi tatil da ruwan inabi ne.” ");
INSERT INTO hausa_vpl VALUES ("AC2_14","074_2_14","ACT","2","14","14","Sai Bitrus ya miƙe tsaye tare da Sha Ɗayan nan, ya ɗaga muryarsa ya yi wa taron jawabi ya ce, “’Yan’uwana Yahudawa da dukanku da kuke zama cikin Urushalima, bari in bayyana muku wannan, ku saurara da kyau ga abin da zan faɗa. ");
INSERT INTO hausa_vpl VALUES ("AC2_15","074_2_15","ACT","2","15","15","Waɗannan mutane ba su bugu ba, kamar yadda kuka ɗauka. Yanzu ƙarfe tara na safe ne kawai! ");
INSERT INTO hausa_vpl VALUES ("AC2_16","074_2_16","ACT","2","16","16","A’a, ai, abin da aka yi magana ta bakin annabi Yowel ke nan cewa, ");
INSERT INTO hausa_vpl VALUES ("AC2_17","074_2_17","ACT","2","17","17","“Allah ya ce, ‘A kwanakin ƙarshe, zan zubo Ruhuna bisa dukan mutane. ’Ya’yanku maza da mata za su yi annabci, samarinku za su ga wahayoyi, dattawanku kuma za su yi mafarkai. ");
INSERT INTO hausa_vpl VALUES ("AC2_18","074_2_18","ACT","2","18","18","Kai, har ma a kan bayina, maza da mata, zan zubo Ruhuna a waɗancan kwanaki, za su kuwa yi annabci. ");
INSERT INTO hausa_vpl VALUES ("AC2_19","074_2_19","ACT","2","19","19","Zan nuna abubuwan banmamaki a sararin sama da alamu a nan ƙasa, jini da wuta da kuma hauhawan hayaƙi. ");
INSERT INTO hausa_vpl VALUES ("AC2_20","074_2_20","ACT","2","20","20","Za a mai da rana duhu, wata kuma ya zama jini, kafin zuwa rana mai girma da kuma ta ɗaukaka ta Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AC2_21","074_2_21","ACT","2","21","21","Kuma duk wanda ya kira bisa sunan Ubangiji zai sami ceto.’ ");
INSERT INTO hausa_vpl VALUES ("AC2_22","074_2_22","ACT","2","22","22","“Mutanen Isra’ila, ku saurari wannan. Yesu Banazare shi ne mutumin da Allah ya tabbatar muku ta wurin mu’ujizai, ayyukan banmamaki, da kuma alamu, waɗanda Allah ya yi a cikinku ta wurinsa, kamar yadda ku kanku kuka sani. ");
INSERT INTO hausa_vpl VALUES ("AC2_23","074_2_23","ACT","2","23","23","An ba da wannan mutum gare ku bisa ga nufin Allah da kuma rigyasaninsa, ku kuma tare da taimakon mugayen mutane, kuka kashe shi ta wurin kafa shi a kan gicciye. ");
INSERT INTO hausa_vpl VALUES ("AC2_24","074_2_24","ACT","2","24","24","Amma Allah ya tashe shi daga matattu, ya ’yantar da shi daga azabar mutuwa, don ba ya yiwuwa mutuwa ta riƙe shi. ");
INSERT INTO hausa_vpl VALUES ("AC2_25","074_2_25","ACT","2","25","25","Dawuda ya yi faɗi game da shi cewa, “ ‘Kullum ina ganin Ubangiji a gabana. Gama yana a hannuna na dama, ba zan jijjigu ba. ");
INSERT INTO hausa_vpl VALUES ("AC2_26","074_2_26","ACT","2","26","26","Saboda haka, zuciyata na farin ciki, harshena kuma na murna, jikina kuma zai kasance da bege, ");
INSERT INTO hausa_vpl VALUES ("AC2_27","074_2_27","ACT","2","27","27","gama ba za ka bar ni cikin kabari ba, ba kuwa za ka yarda Mai Tsarkinka yă ruɓa ba. ");
INSERT INTO hausa_vpl VALUES ("AC2_28","074_2_28","ACT","2","28","28","Ka sanar da ni hanyoyin rai, za ka cika ni da farin ciki a gabanka.’ ");
INSERT INTO hausa_vpl VALUES ("AC2_29","074_2_29","ACT","2","29","29","“’Yan’uwa, zan iya tabbatar muku gabagadi cewa kakanmu Dawuda ya mutu aka kuma binne shi, kabarinsa kuwa yana a nan har yă zuwa yau. ");
INSERT INTO hausa_vpl VALUES ("AC2_30","074_2_30","ACT","2","30","30","Amma shi annabi ne ya kuma san abin da Allah ya yi masa alkawari da rantsuwa cewa zai ɗora ɗaya daga cikin zuriyarsa a kan gadon sarautarsa. ");
INSERT INTO hausa_vpl VALUES ("AC2_31","074_2_31","ACT","2","31","31","Ganin abin da yake gaba, ya yi magana a kan tashin Kiristi daga matattu cewa, ba a bar shi a kabari ba, jikinsa kuma bai ruɓa ba. ");
INSERT INTO hausa_vpl VALUES ("AC2_32","074_2_32","ACT","2","32","32","Allah ya tashe wannan Yesu zuwa rai, mu kuwa duk shaidu ne ga wannan. ");
INSERT INTO hausa_vpl VALUES ("AC2_33","074_2_33","ACT","2","33","33","An ɗaukaka shi zuwa ga hannun dama na Allah, ya karɓi alkawarin Ruhu Mai Tsarki daga Uba, ya kuma zubo abin da yanzu kuke gani kuke kuma ji. ");
INSERT INTO hausa_vpl VALUES ("AC2_34","074_2_34","ACT","2","34","34","Gama Dawuda bai hau zuwa sama ba, duk da haka ya ce, “ ‘Ubangiji ya ce wa Ubangijina, “Zauna a hannun damana, ");
INSERT INTO hausa_vpl VALUES ("AC2_35","074_2_35","ACT","2","35","35","sai na sa abokan gābanka su zama matashin sawunka.” ’ ");
INSERT INTO hausa_vpl VALUES ("AC2_36","074_2_36","ACT","2","36","36","“Saboda haka bari dukan Isra’ila su tabbatar da wannan. Allah ya mai da wannan Yesu, da kuka gicciye, Ubangiji da kuma Kiristi.” ");
INSERT INTO hausa_vpl VALUES ("AC2_37","074_2_37","ACT","2","37","37","Sa’ad da mutane suka ji wannan, sai suka soku a zuci sai suka ce wa Bitrus da sauran manzanni, “’Yan’uwa, me za mu yi?” ");
INSERT INTO hausa_vpl VALUES ("AC2_38","074_2_38","ACT","2","38","38","Bitrus ya amsa, “Ku tuba a kuma yi muku baftisma, kowannenku a cikin sunan Yesu Kiristi domin gafarar zunubanku. Za ku kuwa karɓi kyautar Ruhu Mai Tsarki. ");
INSERT INTO hausa_vpl VALUES ("AC2_39","074_2_39","ACT","2","39","39","Alkawarin dominku ne da ’ya’yanku da kuma dukan waɗanda suke da nesa, domin dukan waɗanda Ubangiji Allahnmu zai kira.” ");
INSERT INTO hausa_vpl VALUES ("AC2_40","074_2_40","ACT","2","40","40","Da waɗansu kalmomi masu yawa ya gargaɗe su; ya kuma roƙe su cewa, “Ku ceci kanku daga wannan lalataccen zamani.” ");
INSERT INTO hausa_vpl VALUES ("AC2_41","074_2_41","ACT","2","41","41","Waɗanda suka yarda da saƙonsa kuwa aka yi musu baftisma, a ranar kuwa yawansu ya ƙaru da mutum kusan dubu uku. ");
INSERT INTO hausa_vpl VALUES ("AC2_42","074_2_42","ACT","2","42","42","Suka ba da kansu ga koyarwar manzanni da kuma ga zumunci, ga gutsuttsura burodin da kuma ga addu’a. ");
INSERT INTO hausa_vpl VALUES ("AC2_43","074_2_43","ACT","2","43","43","Kowa ya cika da tsoro, manzannin kuwa suka aikata abubuwan banmamaki da alamu masu yawa. ");
INSERT INTO hausa_vpl VALUES ("AC2_44","074_2_44","ACT","2","44","44","Dukan masu bi suna tare, suna kuma mallakar kome tare. ");
INSERT INTO hausa_vpl VALUES ("AC2_45","074_2_45","ACT","2","45","45","Suka dinga sayar da ƙaddarorinsu da kayayyakinsu, suka ba wa kowa gwargwadon bukatarsa. ");
INSERT INTO hausa_vpl VALUES ("AC2_46","074_2_46","ACT","2","46","46","Kowace rana suka ci gaba da taruwa a filin haikali. Suka gutsuttsura burodi a gidajensu suna cin abinci tare da farin ciki da zuciya ɗaya, ");
INSERT INTO hausa_vpl VALUES ("AC2_47","074_2_47","ACT","2","47","47","suna yabon Allah suna kuma samun tagomashin dukan mutane. Ubangiji kuwa ya ƙara yawansu kowace rana na waɗanda suke samun ceto. ");
INSERT INTO hausa_vpl VALUES ("AC3_1","074_3_1","ACT","3","1","1","Wata rana, Bitrus da Yohanna suna haurawa zuwa haikali a lokacin addu’a da ƙarfe uku na rana. ");
INSERT INTO hausa_vpl VALUES ("AC3_2","074_3_2","ACT","3","2","2","To, sai ga wani da aka haifa gurgu ana ɗauke da shi zuwa ƙofar haikalin da ake kira Kyakkyawa, inda akan ajiye kowace rana, don yă yi bara daga masu shigowa cikin filayen haikali. ");
INSERT INTO hausa_vpl VALUES ("AC3_3","074_3_3","ACT","3","3","3","Da ya ga Bitrus da Yohanna suna gab da shiga, sai ya roƙe su kuɗi. ");
INSERT INTO hausa_vpl VALUES ("AC3_4","074_3_4","ACT","3","4","4","Bitrus kuwa ya kafa masa ido, haka ma Yohanna. Sai Bitrus ya ce, “Dube mu!” ");
INSERT INTO hausa_vpl VALUES ("AC3_5","074_3_5","ACT","3","5","5","Saboda haka mutumin ya mai da hankalinsa a kansu, yana fata samun wani abu daga gare su. ");
INSERT INTO hausa_vpl VALUES ("AC3_6","074_3_6","ACT","3","6","6","Sai Bitrus ya ce, “Azurfa ko zinariya ba ni da su, amma abin da nake da shi, shi zan ba ka. A cikin sunan Yesu Kiristi Banazare, ka yi tafiya.” ");
INSERT INTO hausa_vpl VALUES ("AC3_7","074_3_7","ACT","3","7","7","Ta wurin kama hannunsa na dama, ya taimake shi ya miƙe, nan take ƙafafu da idon sawun mutumin suka yi ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("AC3_8","074_3_8","ACT","3","8","8","Sai ya yi wuf da ƙafafunsa ya fara tafiya. Ya tafi tare da su ya shiga cikin filin haikali yana tafiya yana tsalle, yana kuma yabon Allah. ");
INSERT INTO hausa_vpl VALUES ("AC3_9","074_3_9","ACT","3","9","9","Sa’ad da dukan mutane suka gan shi yana tafiya yana yabon Allah, ");
INSERT INTO hausa_vpl VALUES ("AC3_10","074_3_10","ACT","3","10","10","sai suka gane cewa shi ne mutumin nan wanda dā yake zama yana bara a bakin ƙofar haikalin da ake kira Kyakkyawa, suka kuwa cika da mamaki da tsoro a kan abin da ya faru gare shi. ");
INSERT INTO hausa_vpl VALUES ("AC3_11","074_3_11","ACT","3","11","11","Tun mai bawan yana riƙe da Bitrus da Yohanna, dukan mutanen suka yi mamaki, suka zo wurinsu a guje a inda ake kira Shirayin Solomon. ");
INSERT INTO hausa_vpl VALUES ("AC3_12","074_3_12","ACT","3","12","12","Da Bitrus ya ga haka, sai ya ce musu, “Mutanen Isra’ila, don me wannan ya ba ku mamaki? Don me kuke kallonmu sai ka ce da ikon kanmu ne ko kuwa don ibadarmu ne muka sa wannan mutum ya yi tafiya? ");
INSERT INTO hausa_vpl VALUES ("AC3_13","074_3_13","ACT","3","13","13","Allah na Ibrahim, Ishaku, da Yaƙub, Allah na kakanninmu, ya ɗaukaka bawansa Yesu. Ku kuka ba da shi domin a kashe, kuka yi mūsun saninsa a gaban Bilatus, ko da yake ya yi niyya ya sake shi. ");
INSERT INTO hausa_vpl VALUES ("AC3_14","074_3_14","ACT","3","14","14","Kuka yi mūsun sanin Mai Tsarki da Mai Adalci kuka roƙa a sakar muku mai kisankai. ");
INSERT INTO hausa_vpl VALUES ("AC3_15","074_3_15","ACT","3","15","15","Kuka kashe tushen rai, amma Allah ya tashe shi daga matattu. Mu shaidu ne ga wannan. ");
INSERT INTO hausa_vpl VALUES ("AC3_16","074_3_16","ACT","3","16","16","Ta wurin bangaskiya cikin sunan Yesu ne wannan mutum da kuke gani kuka kuma sani ya sami ƙarfi. Da sunan Yesu, da kuma bangaskiyar da take samuwa ta wurinsa ne ya ba shi cikakkiyar warkarwa, yadda dukanku kuke gani. ");
INSERT INTO hausa_vpl VALUES ("AC3_17","074_3_17","ACT","3","17","17","“To, ’yan’uwa, na san cewa, kun aikata wannan cikin jahilci ne, yadda shugabanninku suka yi. ");
INSERT INTO hausa_vpl VALUES ("AC3_18","074_3_18","ACT","3","18","18","Amma ta haka ne Allah ya cika abin da ya rigyafaɗi ta bakin dukan annabawa cewa, Kiristinsa zai sha wahala. ");
INSERT INTO hausa_vpl VALUES ("AC3_19","074_3_19","ACT","3","19","19","Saboda haka ku tuba, ku juyo ga Allah, don a shafe zunubanku, don lokutan wartsakewa su zo daga wurin Ubangiji, ");
INSERT INTO hausa_vpl VALUES ("AC3_20","074_3_20","ACT","3","20","20","don kuma ya iya aika da Kiristi, wanda aka naɗa tun dā saboda ku, Yesu ke nan. ");
INSERT INTO hausa_vpl VALUES ("AC3_21","074_3_21","ACT","3","21","21","Dole yă kasance a sama, sai lokaci ya yi da Allah zai mai da kome sabo, yadda ya yi alkawari tun dā ta wurin annabawansa masu tsarki. ");
INSERT INTO hausa_vpl VALUES ("AC3_22","074_3_22","ACT","3","22","22","Gama Musa ya ce, ‘Ubangiji Allahnku zai tasar muku wani annabi kamar ni daga cikin mutanenku; dole ku saurari duk abin da ya faɗa muku. ");
INSERT INTO hausa_vpl VALUES ("AC3_23","074_3_23","ACT","3","23","23","Duk wanda bai saurare shi ba za a ware shi gaba ɗaya daga mutanensa.’ ");
INSERT INTO hausa_vpl VALUES ("AC3_24","074_3_24","ACT","3","24","24","“Tabbatacce, dukan annabawa daga Sama’ila zuwa gaba, dukansu da suka yi magana, sun rigya faɗin waɗannan kwanaki. ");
INSERT INTO hausa_vpl VALUES ("AC3_25","074_3_25","ACT","3","25","25","Ku kuwa magādan annabawan ne da kuma na alkawarin da Allah ya yi da kakanninku. Ya ce wa Ibrahim, ‘Ta wurin zuriyarka, dukan kabilan duniya za su sami albarka.’ ");
INSERT INTO hausa_vpl VALUES ("AC3_26","074_3_26","ACT","3","26","26","Da Allah ya tashe bawansa, ya aike shi da fari zuwa gare ku don yă albarkace ku ta wurin juye kowannenku daga mugayen hanyoyinku.” ");
INSERT INTO hausa_vpl VALUES ("AC4_1","074_4_1","ACT","4","1","1","Sai firistoci da shugaban masu gadin haikalin da kuma Sadukiyawa suka hauro wurin Bitrus da Yohanna yayinda suke cikin magana da mutane. ");
INSERT INTO hausa_vpl VALUES ("AC4_2","074_4_2","ACT","4","2","2","Sun damu ƙwarai da gaske domin manzannin suna koya wa mutane suna kuma shela a cikin Yesu cewa akwai tashin matattu. ");
INSERT INTO hausa_vpl VALUES ("AC4_3","074_4_3","ACT","4","3","3","Sai suka kama Bitrus da Yohanna, amma da yake yamma ta riga ta yi sai suka sa su cikin kurkuku sai kashegari. ");
INSERT INTO hausa_vpl VALUES ("AC4_4","074_4_4","ACT","4","4","4","Amma da yawa da suka ji saƙon suka gaskata, yawan mutanen kuwa ya ƙaru ya kai wajen dubu biyar. ");
INSERT INTO hausa_vpl VALUES ("AC4_5","074_4_5","ACT","4","5","5","Kashegari, sai masu mulki, dattawa da kuma malaman dokoki suka taru a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("AC4_6","074_4_6","ACT","4","6","6","Annas babban firist yana nan, haka ma Kayifas Yohanna, Alekzanda da kuma sauran mutanen da suke iyalin babban firist. ");
INSERT INTO hausa_vpl VALUES ("AC4_7","074_4_7","ACT","4","7","7","Suka sa aka kawo Bitrus da Yohanna a gabansu suka kuma fara yin musu tambayoyi cewa, “Da wane iko ko da wane suna kuka yi wannan?” ");
INSERT INTO hausa_vpl VALUES ("AC4_8","074_4_8","ACT","4","8","8","Sai Bitrus, cike da Ruhu Mai Tsarki ya ce musu, “Masu mulki da dattawan mutane! ");
INSERT INTO hausa_vpl VALUES ("AC4_9","074_4_9","ACT","4","9","9","In ana tuhumarmu ne yau saboda alherin da aka yi wa gurgun nan da kuma yadda aka warkar da shi, ");
INSERT INTO hausa_vpl VALUES ("AC4_10","074_4_10","ACT","4","10","10","to, sai ku san wannan, ku da dukan mutanen Isra’ila cewa da sunan Yesu Kiristi Banazare, wanda kuka gicciye amma wanda Allah ya tasar daga matattu ne, wannan mutum yake tsaye a gabanku lafiyayye. ");
INSERT INTO hausa_vpl VALUES ("AC4_11","074_4_11","ACT","4","11","11","Shi ne, “ ‘dutsen da ku magina kuka ƙi, wanda kuwa ya zama dutsen kusurwar gini.’ ");
INSERT INTO hausa_vpl VALUES ("AC4_12","074_4_12","ACT","4","12","12","Ba a samun ceto ta wurin wani dabam, gama babu wani suna a ƙarƙashin sama da aka ba wa mutane wanda ta wurinsa dole mu sami ceto.” ");
INSERT INTO hausa_vpl VALUES ("AC4_13","074_4_13","ACT","4","13","13","Da suka ga ƙarfin halin Bitrus da Yohanna suka kuma gane cewa su marasa ilimi ne, talakawa kuma, sai suka yi mamaki suka kuma lura cewa waɗannan mutane sun kasance tare da Yesu. ");
INSERT INTO hausa_vpl VALUES ("AC4_14","074_4_14","ACT","4","14","14","Amma da yake sun ga mutumin da aka warkar yana tsaye a wurin tare da su, sai suka rasa abin faɗi. ");
INSERT INTO hausa_vpl VALUES ("AC4_15","074_4_15","ACT","4","15","15","Saboda haka suka umarta a fitar da su daga Majalisar, sa’an nan suka yi shawara da juna. ");
INSERT INTO hausa_vpl VALUES ("AC4_16","074_4_16","ACT","4","16","16","Suka ce, “Me za mu yi da waɗannan mutane? Kowa da yake zama a Urushalima ya san sun yi abin banmamaki, kuma ba za mu iya yin mūsu wannan ba. ");
INSERT INTO hausa_vpl VALUES ("AC4_17","074_4_17","ACT","4","17","17","Amma don a hana wannan abu daga ƙara bazuwa cikin mutane, dole mu kwaɓe mutanen nan kada su ƙara yi wa kowa magana cikin wannan suna.” ");
INSERT INTO hausa_vpl VALUES ("AC4_18","074_4_18","ACT","4","18","18","Sai suka sāke kiransu ciki suka kuma umarce su kada su kuskura su yi magana ko su ƙara koyarwa a cikin sunan Yesu. ");
INSERT INTO hausa_vpl VALUES ("AC4_19","074_4_19","ACT","4","19","19","Amma Bitrus da Yohanna suka amsa, “Ku shari’anta da kanku ko daidai ne a gaban Allah mu yi muku biyayya maimakon Allah. ");
INSERT INTO hausa_vpl VALUES ("AC4_20","074_4_20","ACT","4","20","20","Gama ba za mu iya daina yin magana game da abin da muka gani muka kuma ji ba.” ");
INSERT INTO hausa_vpl VALUES ("AC4_21","074_4_21","ACT","4","21","21","Bayan ƙarin barazana sai suka bar su su tafi. Ba su iya yanke shawara yadda za a hore su ba, domin dukan mutane suna yabon Allah saboda abin da ya faru. ");
INSERT INTO hausa_vpl VALUES ("AC4_22","074_4_22","ACT","4","22","22","Gama mutumin da ya sami warkarwar banmamaki, shekarunsa sun fi arba’in. ");
INSERT INTO hausa_vpl VALUES ("AC4_23","074_4_23","ACT","4","23","23","Da aka sake su, Bitrus da Yohanna suka koma wajen mutanensu suka ba da labarin duk abin da manyan firistoci da dattawa suka faɗa musu. ");
INSERT INTO hausa_vpl VALUES ("AC4_24","074_4_24","ACT","4","24","24","Sa’ad da suka ji wannan, sai suka ɗaga muryoyinsu gaba ɗaya cikin addu’a ga Allah, suka ce, “Ya Ubangiji Mai Iko Duka, kai ka halicci sama da ƙasa da kuma teku, da kome da yake cikinsu. ");
INSERT INTO hausa_vpl VALUES ("AC4_25","074_4_25","ACT","4","25","25","Ka yi magana ta wurin Ruhu Mai Tsarki ta bakin bawanka, kakanmu Dawuda cewa, “ ‘Don me ƙasashe suke fushi, mutane kuma suke ƙulla shawara a banza? ");
INSERT INTO hausa_vpl VALUES ("AC4_26","074_4_26","ACT","4","26","26","Sarakunan duniya sun ja dāgā, masu mulki kuma sun taru gaba ɗaya, suna gāba da Ubangiji da kuma Shafaffensa.’ ");
INSERT INTO hausa_vpl VALUES ("AC4_27","074_4_27","ACT","4","27","27","Tabbatacce Hiridus da Buntus Bilatus suka haɗu tare da Al’ummai da kuma mutanen Isra’ila a wannan birni ce don su ƙulla gāba da bawanka mai tsarki Yesu, wanda ka shafe. ");
INSERT INTO hausa_vpl VALUES ("AC4_28","074_4_28","ACT","4","28","28","Sun aikata abin da ikonka da kuma nufinka ya riga ya shirya tuntuni zai faru. ");
INSERT INTO hausa_vpl VALUES ("AC4_29","074_4_29","ACT","4","29","29","Yanzu, Ubangiji, ka dubi barazanansu ka kuma sa bayinka su furta maganarka da iyakar ƙarfin hali. ");
INSERT INTO hausa_vpl VALUES ("AC4_30","074_4_30","ACT","4","30","30","Ka miƙa hannunka don ka warkar ka kuma yi ayyukan banmamaki da alamu masu banmamaki ta wurin sunan bawanka mai tsarki Yesu.” ");
INSERT INTO hausa_vpl VALUES ("AC4_31","074_4_31","ACT","4","31","31","Bayan suka yi addu’a, sai inda suka taru ya jijjigu. Dukansu kuwa suka cika da Ruhu Mai Tsarki, suka yi ta shaidar maganar Allah babu tsoro. ");
INSERT INTO hausa_vpl VALUES ("AC4_32","074_4_32","ACT","4","32","32","Dukan masu bi kuwa zuciyarsu ɗaya ne, nufinsu kuwa ɗaya. Babu wani da ya ce abin da ya mallaka nasa ne, amma sun raba kome da suke da shi. ");
INSERT INTO hausa_vpl VALUES ("AC4_33","074_4_33","ACT","4","33","33","Da iko mai ƙarfi manzanni suka ci gaba da shaidar tashin matattu na Ubangiji Yesu, alheri mai yawa kuwa yana bisansu duka. ");
INSERT INTO hausa_vpl VALUES ("AC4_34","074_4_34","ACT","4","34","34","Babu mabukata a cikinsu. Lokaci-lokaci waɗanda suke da gonaki ko gidaje sukan sayar da su, su kawo kuɗi daga abin da suka sayar, ");
INSERT INTO hausa_vpl VALUES ("AC4_35","074_4_35","ACT","4","35","35","su ajiye a sawun manzannin, a kuma raba wa kowa gwargwadon bukatarsa. ");
INSERT INTO hausa_vpl VALUES ("AC4_36","074_4_36","ACT","4","36","36","Yusuf, wani Balawe daga Saifurus, wanda manzanni suke kira Barnabas (wanda yake nufin Ɗan Ƙarfafawa) ");
INSERT INTO hausa_vpl VALUES ("AC4_37","074_4_37","ACT","4","37","37","ya sayar da wata gonar da ya mallaki ya kuma kawo kuɗin ya ajiye a sawun manzanni. ");
INSERT INTO hausa_vpl VALUES ("AC5_1","074_5_1","ACT","5","1","1","To wani mutum mai suna Ananiyas tare da matarsa Saffiratu, shi ma ya sayar da wata mallakarsa. ");
INSERT INTO hausa_vpl VALUES ("AC5_2","074_5_2","ACT","5","2","2","Da cikakken sanin matarsa ya ajiye sashi daga cikin kuɗin don kansa, ya kuma kawo sauran ya ajiye a sawun manzanni. ");
INSERT INTO hausa_vpl VALUES ("AC5_3","074_5_3","ACT","5","3","3","Sai Bitrus ya ce, “Ananiyas, ta yaya Shaiɗan ya cika zuciyarka haka da ka yi wa Ruhu Mai Tsarki ƙarya ka kuma ajiye wa kanka sauran kuɗin da ka karɓa na filin? ");
INSERT INTO hausa_vpl VALUES ("AC5_4","074_5_4","ACT","5","4","4","Ba naka ba ne kafin ka sayar da shi? Bayan da ka sayar da shi kuma, kuɗin ba naka ba ne? Me ya sa ka yi tunanin yin irin wannan abu? Ba mutum ne ka yi wa ƙarya ba, Allah ne ka yi masa.” ");
INSERT INTO hausa_vpl VALUES ("AC5_5","074_5_5","ACT","5","5","5","Da Ananiyas ya ji wannan, sai ya fāɗi ya mutu. Sai babban tsoro kuwa ya kama duk waɗanda suka ji abin da ya faru. ");
INSERT INTO hausa_vpl VALUES ("AC5_6","074_5_6","ACT","5","6","6","Sai samari suka zo gaba, suka naɗe gawarsa, suka fitar da shi suka je suka binne. ");
INSERT INTO hausa_vpl VALUES ("AC5_7","074_5_7","ACT","5","7","7","Bayan kusan awa uku, sai matarsa ta shigo, ba da sanin abin da ya faru ba. ");
INSERT INTO hausa_vpl VALUES ("AC5_8","074_5_8","ACT","5","8","8","Bitrus ya tambaye ta ya ce, “Gaya mini, kuɗin da yake da Ananiyas kuka sayar da filin ke nan?” Ta ce, “I, haka ne muka sayar.” ");
INSERT INTO hausa_vpl VALUES ("AC5_9","074_5_9","ACT","5","9","9","Bitrus ya ce mata, “Ta yaya kuka yarda ku gwada Ruhun Ubangiji? Duba! Sawun mutanen da suka binne mijinki suna bakin ƙofa, za su kuwa ɗauke ki zuwa waje ke ma.” ");
INSERT INTO hausa_vpl VALUES ("AC5_10","074_5_10","ACT","5","10","10","Nan take ta fāɗi a ƙafafunsa ta mutu. Sai samarin suka shigo ciki, suka kuwa same ta matacciya, suka ɗauke ta suka kai ta waje suka binne ta kusa da mijinta. ");
INSERT INTO hausa_vpl VALUES ("AC5_11","074_5_11","ACT","5","11","11","Babban tsoro ya kama dukan ikkilisiya da kuma duk wanda ya ji game da abubuwan nan. ");
INSERT INTO hausa_vpl VALUES ("AC5_12","074_5_12","ACT","5","12","12","Manzannin suka yi ayyukan da alamu masu banmamaki masu yawa a cikin mutanen. Dukan masu bi kuwa sukan taru a Shirayin Solomon. ");
INSERT INTO hausa_vpl VALUES ("AC5_13","074_5_13","ACT","5","13","13","Ba wanda ya yi karambanin shiga cikinsu, duk da haka mutane suna girmama su ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("AC5_14","074_5_14","ACT","5","14","14","Duk da haka, maza da matan da suke gaskata ga Ubangiji sai ƙaruwa suke, suka kuma ƙaru a yawa. ");
INSERT INTO hausa_vpl VALUES ("AC5_15","074_5_15","ACT","5","15","15","A sakamakon haka, mutane suka kawo marasa lafiya a tituna suka kwantar da su a kan gadaje da tabarmai domin aƙalla inuwar Bitrus za tă bi kan waɗansunsu yayinda yake wucewa. ");
INSERT INTO hausa_vpl VALUES ("AC5_16","074_5_16","ACT","5","16","16","Jama’a ma suka tattaru daga garuruwa kewaye da Urushalima suna kawo marasa lafiyarsu da kuma waɗanda mugayen ruhohi suke damun su, dukansu kuwa suka warke. ");
INSERT INTO hausa_vpl VALUES ("AC5_17","074_5_17","ACT","5","17","17","Sai babban firist da dukan abokan aikinsa, waɗanda suke na ƙungiyar Sadukiyawa suka cika da kishi. ");
INSERT INTO hausa_vpl VALUES ("AC5_18","074_5_18","ACT","5","18","18","Suka kama manzannin suka sa su a kurkukun da ake sa kowa da kowa. ");
INSERT INTO hausa_vpl VALUES ("AC5_19","074_5_19","ACT","5","19","19","Amma da dare wani mala’ikan Ubangiji ya buɗe ƙofofin kurkukun ya fitar da su. ");
INSERT INTO hausa_vpl VALUES ("AC5_20","074_5_20","ACT","5","20","20","Ya ce, “Ku je ku tsaya a filin haikali ku sanar wa mutane cikakken saƙon wannan sabon rai.” ");
INSERT INTO hausa_vpl VALUES ("AC5_21","074_5_21","ACT","5","21","21","Da gari ya waye, sai suka shiga filin haikali, yadda aka faɗa musu, suka kuwa fara koyar da mutane. Sa’ad da babban firist da abokan aikinsa suka iso, sai suka kira Majalisa gaba ɗaya dukan dattawan Isra’ila, suka kuma aika kurkuku a zo da manzannin. ");
INSERT INTO hausa_vpl VALUES ("AC5_22","074_5_22","ACT","5","22","22","Amma da dogarawan suka iso kurkukun, ba su same su a can ba. Saboda haka suka dawo suka ba da labari, suka ce, ");
INSERT INTO hausa_vpl VALUES ("AC5_23","074_5_23","ACT","5","23","23","“Mun iske kurkukun a kulle sosai, da masu gadi suna tsaye a bakin ƙofofin; amma da muka buɗe su, sai muka tarar ba kowa a ciki.” ");
INSERT INTO hausa_vpl VALUES ("AC5_24","074_5_24","ACT","5","24","24","Da jin wannan labari, sai shugaban masu gadin haikali da manyan firistocin suka ruɗe, suna tunanin abin da wannan al’amari zai zama. ");
INSERT INTO hausa_vpl VALUES ("AC5_25","074_5_25","ACT","5","25","25","Sai wani ya zo ya ce, “Ga shi! Mutanen da kuka sa a kurkuku suna tsaye a filin haikali suna koya wa mutane.” ");
INSERT INTO hausa_vpl VALUES ("AC5_26","074_5_26","ACT","5","26","26","Da wannan, shugaban ya tafi tare da dogarawansa suka kawo manzannin. Sun kawo su amma fa ba ƙarfi da yaji ba, don suna tsoro kada mutane su jajjefe su da duwatsu. ");
INSERT INTO hausa_vpl VALUES ("AC5_27","074_5_27","ACT","5","27","27","Da suka kawo manzannin, sai suka sa su suka bayyana a gaban Majalisar don babban firist ya tuhume su. ");
INSERT INTO hausa_vpl VALUES ("AC5_28","074_5_28","ACT","5","28","28","Ya ce, “Mun kwaɓe ku da gaske kada ku ƙara koyarwa cikin wannan suna, duk da haka kun cika Urushalima da koyarwarku, har ma kuna so ku ɗora mana laifin jinin mutumin nan.” ");
INSERT INTO hausa_vpl VALUES ("AC5_29","074_5_29","ACT","5","29","29","Bitrus da sauran manzannin suka amsa suka ce, “Dole ne mu yi wa Allah biyayya a maimakon mutane! ");
INSERT INTO hausa_vpl VALUES ("AC5_30","074_5_30","ACT","5","30","30","Allahn kakanninmu ya tā da Yesu daga matattu, wanda kuka kashe ta wurin ratayewa a bisan itace. ");
INSERT INTO hausa_vpl VALUES ("AC5_31","074_5_31","ACT","5","31","31","Allah ya ɗaukaka shi zuwa hannun damansa a matsayin Yerima da Mai Ceto don yă kawo tuba da gafarar zunubai ga Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("AC5_32","074_5_32","ACT","5","32","32","Mu shaidu ne ga waɗannan abubuwa, haka kuma Ruhu Mai Tsarki, wanda Allah ya ba wa waɗanda suke yin masa biyayya.” ");
INSERT INTO hausa_vpl VALUES ("AC5_33","074_5_33","ACT","5","33","33","Da suka ji haka, sai suka yi fushi suka so su kashe su. ");
INSERT INTO hausa_vpl VALUES ("AC5_34","074_5_34","ACT","5","34","34","Amma wani Bafarisiyen da ake kira Gamaliyel, wani malamin doka, wanda dukan mutane ke girmamawa, ya miƙe tsaye a Majalisar ya umarta a fitar da mutanen waje na ɗan lokaci. ");
INSERT INTO hausa_vpl VALUES ("AC5_35","074_5_35","ACT","5","35","35","Sa’an nan ya yi musu jawabi ya ce, “Mutanen Isra’ila, ku yi kula da kyau da abin da kuke niyyar yi wa mutanen nan. ");
INSERT INTO hausa_vpl VALUES ("AC5_36","074_5_36","ACT","5","36","36","Kwanan baya, Teyudas ya ɓullo, yana cewa wai shi wani mutum ne, kuma wajen mutane ɗari huɗu suka bi shi. Aka kuwa kashe shi, dukan masu binsa kuwa suka watse, kome ya wargaje. ");
INSERT INTO hausa_vpl VALUES ("AC5_37","074_5_37","ACT","5","37","37","Bayansa, Yahuda mutumin Galili ya ɓullo a kwanakin ƙidaya, ya jagoranci mutane cikin tawaye. Shi ma aka kashe shi, dukan mabiyansa kuma aka watsar da su. ");
INSERT INTO hausa_vpl VALUES ("AC5_38","074_5_38","ACT","5","38","38","Saboda haka, a wannan batu na yanzu, ina ba ku shawara. Ku ƙyale mutanen nan! Ku bar su su tafi! Gama in manufarsu ko ayyukansu na mutum ne, ai, zai rushe. ");
INSERT INTO hausa_vpl VALUES ("AC5_39","074_5_39","ACT","5","39","39","Amma in daga Allah ne, ba za ku iya hana waɗannan mutane ba, za ku dai sami kanku kuna gāba da Allah ne.” ");
INSERT INTO hausa_vpl VALUES ("AC5_40","074_5_40","ACT","5","40","40","Jawabinsa ya rinjaye su. Suka kira manzannin suka sa aka yi musu bulala. Sa’an nan suka kwaɓe su kada su ƙara magana a cikin sunan Yesu, suka kuma bar su suka tafi. ");
INSERT INTO hausa_vpl VALUES ("AC5_41","074_5_41","ACT","5","41","41","Manzannin suka bar Majalisar, suna farin ciki domin an ga sun cancanta a kunyata su saboda Sunan nan. ");
INSERT INTO hausa_vpl VALUES ("AC5_42","074_5_42","ACT","5","42","42","Kowace rana, a filin haikali da kuma gida-gida, ba su fasa koyarwa da kuma shelar labari mai daɗi cewa Yesu shi ne Kiristi ba. ");
INSERT INTO hausa_vpl VALUES ("AC6_1","074_6_1","ACT","6","1","1","A waɗannan kwanaki, sa’ad da yawan almajirai suke ƙaruwa, sai Yahudawan masu jin Hellenanci a cikinsu suka yi gunaguni a kan Yahudawan da suke Ibraniyawa domin ba a kula da gwaurayensu a wajen raba abinci na yau da kullum. ");
INSERT INTO hausa_vpl VALUES ("AC6_2","074_6_2","ACT","6","2","2","Saboda haka Sha Biyun nan suka tara dukan almajirai wuri ɗaya, suka ce, “Bai zai yi kyau mu bar hidimar maganar Allah don mu shiga hidimar abinci ba. ");
INSERT INTO hausa_vpl VALUES ("AC6_3","074_6_3","ACT","6","3","3","’Yan’uwa, ku zaɓi mutum bakwai daga cikinku waɗanda aka sani suna cike da Ruhu da kuma hikima. Mu kuwa za mu danƙa musu wannan aiki ");
INSERT INTO hausa_vpl VALUES ("AC6_4","074_6_4","ACT","6","4","4","mu kuwa mu mai da halinmu ga yin addu’a da kuma hidimar maganar Allah.” ");
INSERT INTO hausa_vpl VALUES ("AC6_5","074_6_5","ACT","6","5","5","Wannan shawarar kuwa ta gamshi dukan ƙungiyar. Sai suka zaɓi Istifanus, mutumin da yake cike da bangaskiya da kuma Ruhu Mai Tsarki; da Filibus, Burokorus, Nikano, Timon, Farmenas, da Nikolas daga Antiyok, wanda ya tuba zuwa Yahudanci. ");
INSERT INTO hausa_vpl VALUES ("AC6_6","074_6_6","ACT","6","6","6","Suka gabatar da waɗannan mutane wa manzanni, waɗanda kuwa suka yi addu’a, suka ɗibiya hannuwansu a kansu. ");
INSERT INTO hausa_vpl VALUES ("AC6_7","074_6_7","ACT","6","7","7","Saboda haka maganar Allah ta yaɗu. Yawan almajirai a Urushalima kuwa ya yi saurin ƙaruwa, firistoci masu yawa kuma suka zama masu biyayya ga wannan bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("AC6_8","074_6_8","ACT","6","8","8","To, Istifanus, mutum cike da alheri da ikon Allah, ya aikata manyan ayyukan da alamu masu banmamaki a cikin mutane. ");
INSERT INTO hausa_vpl VALUES ("AC6_9","074_6_9","ACT","6","9","9","Sai hamayya ta taso daga ’yan ƙungiyar Majami’a na ’Yantattu (kamar yadda ake kiransu), Yahudawan Sairin da Alekzandariya da kuma lardunan Silisiya da Asiya. Mutanen nan suka fara muhawwara da Istifanus, ");
INSERT INTO hausa_vpl VALUES ("AC6_10","074_6_10","ACT","6","10","10","amma ba su iya cin nasara kan hikimarsa ko kuma a kan Ruhu wanda ta wurinsa ne ya magana ba. ");
INSERT INTO hausa_vpl VALUES ("AC6_11","074_6_11","ACT","6","11","11","Sa’an nan a asirce suka zuga waɗansu mutane su ce, “Mun ji Istifanus ya faɗa kalmomin saɓo game da Musa da kuma Allah.” ");
INSERT INTO hausa_vpl VALUES ("AC6_12","074_6_12","ACT","6","12","12","Ta haka suka tā da hankalin mutane da dattawa da kuma malaman dokoki. Suka kama Istifanus suka kawo shi a gaban Majalisa. ");
INSERT INTO hausa_vpl VALUES ("AC6_13","074_6_13","ACT","6","13","13","Suka kawo masu ba da shaidar ƙarya, waɗanda suka ba da shaida cewa, “Wannan mutum ba ya rabuwa da maganar banza a kan wurin nan mai tsarki da kuma doka. ");
INSERT INTO hausa_vpl VALUES ("AC6_14","074_6_14","ACT","6","14","14","Gama mun ji shi yana cewa wannan Yesu Banazare zai rushe wurin nan ya kuma canja al’adun da Musa ya ba mu.” ");
INSERT INTO hausa_vpl VALUES ("AC6_15","074_6_15","ACT","6","15","15","Dukan waɗanda suke zaune a Majalisar suka kafa wa Istifanus ido, suka kuma ga fuskarsa ta yi kama da ta mala’ika. ");
INSERT INTO hausa_vpl VALUES ("AC7_1","074_7_1","ACT","7","1","1","Sai babban firist ya tambaye shi ya ce, “Waɗannan zargen gaskiya ne?” ");
INSERT INTO hausa_vpl VALUES ("AC7_2","074_7_2","ACT","7","2","2","Game da wannan ya amsa ya ce, “’Yan’uwa da ubanni, ku saurare ni! Allah mai ɗaukaka ya bayyana ga kakanmu Ibrahim yayinda yake a ƙasar Mesofotamiya tukuna, kafin ya yi zama a Haran. ");
INSERT INTO hausa_vpl VALUES ("AC7_3","074_7_3","ACT","7","3","3","Allah ya ce, ‘Ka bar ƙasarka da kuma mutanenka, ka tafi ƙasar da zan nuna maka.’ ");
INSERT INTO hausa_vpl VALUES ("AC7_4","074_7_4","ACT","7","4","4","“Saboda haka ya bar ƙasar Kaldiyawa ya kuma yi zama a Haran. Bayan mutuwar mahaifinsa, Allah ya aika da shi wannan ƙasar da yanzu kuke zama. ");
INSERT INTO hausa_vpl VALUES ("AC7_5","074_7_5","ACT","7","5","5","Bai ba shi gādo a nan ba, ko taki ɗaya na ƙasa. Amma Allah ya yi masa alkawari cewa shi da zuriyarsa masu zuwa bayansa za su mallaki ƙasar, ko da yake a lokacin Ibrahim ba shi da yaro. ");
INSERT INTO hausa_vpl VALUES ("AC7_6","074_7_6","ACT","7","6","6","Allah ya yi magana da shi ta haka, ‘Shekara ɗari huɗu, zuriyarka za tă yi baƙunci a wata ƙasar da ba tasu ba, za su yi bauta su kuma sha wulaƙanci. ");
INSERT INTO hausa_vpl VALUES ("AC7_7","074_7_7","ACT","7","7","7","Amma zan hore ƙasar da suka bauta wa.’ Allah ya ce, ‘Kuma daga baya za su fita daga wannan ƙasa su kuma yi mini sujada a wannan wuri.’ ");
INSERT INTO hausa_vpl VALUES ("AC7_8","074_7_8","ACT","7","8","8","Sa’an nan ya yi wa Ibrahim alkawari game da kaciya. Ibrahim kuwa ya zama mahaifin Ishaku ya kuma yi masa kaciya kwana takwas bayan haihuwarsa. Daga baya Ishaku ya zama mahaifin Yaƙub, Yaƙub kuma ya zama mahaifin kakanninmu sha biyun nan. ");
INSERT INTO hausa_vpl VALUES ("AC7_9","074_7_9","ACT","7","9","9","“Domin kakanninmu sun ji kishin Yusuf, sai suka sayar da shi bawa zuwa Masar. Amma Allah ya kasance tare da shi ");
INSERT INTO hausa_vpl VALUES ("AC7_10","074_7_10","ACT","7","10","10","ya kuma cece shi daga dukan wahalolinsa. Ya ba wa Yusuf hikima ya kuma sa ya sami farin jini a wurin Fir’auna, sarkin Masar; saboda haka ya mai da shi mai mulki a kan Masar da kuma dukan fadarsa. ");
INSERT INTO hausa_vpl VALUES ("AC7_11","074_7_11","ACT","7","11","11","“Sai yunwa ta auko wa dukan Masar da Kan’ana, ta kawo wahala mai tsanani, kakanninmu ba su iya samun abinci ba. ");
INSERT INTO hausa_vpl VALUES ("AC7_12","074_7_12","ACT","7","12","12","Sa’ad da Yaƙub ya ji cewa akwai hatsi a Masar, sai ya aiki kakanninmu ziyararsu ta farko. ");
INSERT INTO hausa_vpl VALUES ("AC7_13","074_7_13","ACT","7","13","13","A ziyararsu ta biyu, Yusuf ya faɗa wa ’yan’uwansa wane ne shi, Fir’auna kuwa ya sami sani game da iyalin Yusuf. ");
INSERT INTO hausa_vpl VALUES ("AC7_14","074_7_14","ACT","7","14","14","Bayan wannan, Yusuf ya aika a zo da mahaifinsa Yaƙub da dukan iyalinsa, gaba ɗaya dai mutum saba’in da biyar ne. ");
INSERT INTO hausa_vpl VALUES ("AC7_15","074_7_15","ACT","7","15","15","Sai Yaƙub ya gangara zuwa Masar, inda shi da kuma kakanninmu suka mutu. ");
INSERT INTO hausa_vpl VALUES ("AC7_16","074_7_16","ACT","7","16","16","Aka dawo da gawawwakinsu Shekem aka binne su a kabarin da Ibrahim ya saya daga wurin ’ya’yan Hamor da waɗansu kuɗi a Shekem. ");
INSERT INTO hausa_vpl VALUES ("AC7_17","074_7_17","ACT","7","17","17","“Da lokaci ya yi kusa da Allah zai cika alkawarin da ya yi wa Ibrahim, sai yawan mutanenmu da suke a Masar ya ƙaru ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("AC7_18","074_7_18","ACT","7","18","18","Sa’an nan wani sarki, wanda bai san kome game da Yusuf ba, ya zama mai mulkin Masar. ");
INSERT INTO hausa_vpl VALUES ("AC7_19","074_7_19","ACT","7","19","19","Ya kuwa wulaƙanta mutanenmu sosai, ya kuma gwada wa kakanni-kakanninmu azaba ta wurin tilasta su su zubar da sababbin jariransu, don su mutu. ");
INSERT INTO hausa_vpl VALUES ("AC7_20","074_7_20","ACT","7","20","20","“A lokacin nan aka haifi Musa, shi kuwa ba kamar sauran jarirai ba ne. Wata uku aka yi renonsa a gidan mahaifinsa. ");
INSERT INTO hausa_vpl VALUES ("AC7_21","074_7_21","ACT","7","21","21","Sa’ad da aka ajiye shi a waje, diyar Fir’auna ta ɗauke shi ta kuma rene shi kamar ɗanta. ");
INSERT INTO hausa_vpl VALUES ("AC7_22","074_7_22","ACT","7","22","22","Musa ya sami ilimi cikin dukan hikimar Masarawa ya kuma zama mai iko cikin magana da ayyuka. ");
INSERT INTO hausa_vpl VALUES ("AC7_23","074_7_23","ACT","7","23","23","“Da Musa ya cika shekara arba’in da haihuwa, sai ya yanke shawara yă ziyarci ’yan’uwansa Isra’ilawa. ");
INSERT INTO hausa_vpl VALUES ("AC7_24","074_7_24","ACT","7","24","24","Ya ga ɗayansu yana shan wulaƙanci a hannun wani mutumin Masar, sai ya je ya kāre shi, ya rama masa ta wurin kashe mutumin Masar ɗin. ");
INSERT INTO hausa_vpl VALUES ("AC7_25","074_7_25","ACT","7","25","25","Musa ya yi tsammani mutanensa za su gane cewa, Allah yana amfani da shi don yă cece su, amma ba su gane ba. ");
INSERT INTO hausa_vpl VALUES ("AC7_26","074_7_26","ACT","7","26","26","Kashegari, Musa ya sadu da Isra’ilawa biyu suna faɗa. Ya yi ƙoƙari ya sasanta su, yana cewa, ‘Ku mutane, ku ’yan’uwa ne, don me kuke so ku cutar da juna?’ ");
INSERT INTO hausa_vpl VALUES ("AC7_27","074_7_27","ACT","7","27","27","“Amma mutumin da yake wulaƙanta ɗayan, ya tura Musa a gefe ya ce, ‘Wa ya mai da kai mai mulki, da alƙali a kanmu? ");
INSERT INTO hausa_vpl VALUES ("AC7_28","074_7_28","ACT","7","28","28","Kana so ka kashe ni kamar yadda ka kashe mutumin Masar nan na jiya?’ ");
INSERT INTO hausa_vpl VALUES ("AC7_29","074_7_29","ACT","7","29","29","Sa’ad da Musa ya ji haka, sai ya gudu zuwa ƙasar Midiyan, inda ya yi baƙunci, ya kuma haifi ’ya’ya biyu maza. ");
INSERT INTO hausa_vpl VALUES ("AC7_30","074_7_30","ACT","7","30","30","“Bayan shekaru arba’in suka wuce, sai mala’ika ya bayyana ga Musa cikin harshen wuta a ɗan itace a hamada kusa da Dutsen Sinai. ");
INSERT INTO hausa_vpl VALUES ("AC7_31","074_7_31","ACT","7","31","31","Sa’ad da ya ga haka, ya yi mamakin abin da ya gani. Da ya yi kusa domin ya duba sosai, sai ya ji muryar Ubangiji ta ce, ");
INSERT INTO hausa_vpl VALUES ("AC7_32","074_7_32","ACT","7","32","32","‘Ni ne Allahn kakanninka, Allah na Ibrahim, Ishaku, da kuma Yaƙub.’ Sai Musa ya yi rawan jiki don tsoro, bai kuwa yi karambanin dubawa ba. ");
INSERT INTO hausa_vpl VALUES ("AC7_33","074_7_33","ACT","7","33","33","“Sa’an nan Ubangiji ya ce masa, ‘Ka cire takalmanka; wurin da kake tsayen nan mai tsarki ne. ");
INSERT INTO hausa_vpl VALUES ("AC7_34","074_7_34","ACT","7","34","34","Tabbatacce na ga wulaƙancin da ake yi wa mutanena a Masar. Na ji nishinsu na kuma sauka domin in ’yantar da su. Yanzu ka zo, zan aike ka ka koma Masar.’ ");
INSERT INTO hausa_vpl VALUES ("AC7_35","074_7_35","ACT","7","35","35","“Wannan Musa ɗin da suka ƙi suna cewa, ‘Wa ya mai da kai mai mulki da kuma alƙali?’ Allah da kansa ya aike shi, ta wurin mala’ikan da ya bayyana a gare shi a ɗan itace, yă zama mai mulkinsu, da kuma mai cetonsu. ");
INSERT INTO hausa_vpl VALUES ("AC7_36","074_7_36","ACT","7","36","36","Ya fitar da su daga Masar ya kuma yi ayyukan da abubuwan banmamaki a Masar, a Jan Teku, da kuma cikin hamada har shekara arba’in. ");
INSERT INTO hausa_vpl VALUES ("AC7_37","074_7_37","ACT","7","37","37","“Wannan Musa ne ya ce Isra’ilawa, ‘Allah zai aika muku wani annabi kamar ni daga cikin mutanenku.’ ");
INSERT INTO hausa_vpl VALUES ("AC7_38","074_7_38","ACT","7","38","38","Ya kasance a cikin taron nan a hamada, tare da mala’ikan da ya yi magana da shi a Dutsen Sinai, da kuma tare da kakanninmu; ya kuma karɓi kalmomi masu rai don yă miƙa mana. ");
INSERT INTO hausa_vpl VALUES ("AC7_39","074_7_39","ACT","7","39","39","“Amma kakanninmu suka ƙi yin masa biyayya. A maimakon haka, sai suka ƙi shi a cikin zuciyarsu kuwa suka koma Masar. ");
INSERT INTO hausa_vpl VALUES ("AC7_40","074_7_40","ACT","7","40","40","Suka ce wa Haruna, ‘Ka yi mana allolin da za su yi mana jagora. Game da wannan Musa ɗin wanda ya fitar da mu daga Masar, ba mu san abin da ya faru da shi ba!’ ");
INSERT INTO hausa_vpl VALUES ("AC7_41","074_7_41","ACT","7","41","41","A lokacin ne suka ƙera gunki mai siffar ɗan maraƙi. Suka kawo masa hadayu suka kuma yi bikin girmama abin da suka ƙera da hannuwansu. ");
INSERT INTO hausa_vpl VALUES ("AC7_42","074_7_42","ACT","7","42","42","Sai Amma Allah ya juya musu baya ya kuma ba da su ga bautar abubuwan da suke a sararin sama. Wannan ya yi daidai da abin da yake a rubuce a cikin littafin annabawa cewa, “ ‘Kun kawo mini hadayu da sadakoki shekaru arba’in cikin, hamada, ya gidan Isra’ila? ");
INSERT INTO hausa_vpl VALUES ("AC7_43","074_7_43","ACT","7","43","43","Kun ɗaukaka gidan tsafin Molek, da tauraron allahnku Refan, gumakan da kuka ƙera don ku yi musu sujada. Saboda haka zan aike ku zuwa bauta’ gaba da Babilon. ");
INSERT INTO hausa_vpl VALUES ("AC7_44","074_7_44","ACT","7","44","44","“Kakanni-kakanninmu suna da tabanakul na Shaida tare da su a hamada. An yi shi bisa ga yadda Allah ya umarci Musa, bisa ga zānen da ya gani. ");
INSERT INTO hausa_vpl VALUES ("AC7_45","074_7_45","ACT","7","45","45","Bayan sun gāji tabanakul nan, kakanninmu a ƙarƙashin jagorancin Yoshuwa suka kawo shi tare da su, lokacin da suka ƙwace ƙasar daga al’umman da Allah ya kora a idanunsu. Tabanakul ɗin ya kasance a ƙasar har zamanin Dawuda, ");
INSERT INTO hausa_vpl VALUES ("AC7_46","074_7_46","ACT","7","46","46","wanda ya sami tagomashi daga Allah, ya kuma nemi yă yi wa Allah na Yaƙub wurin zama. ");
INSERT INTO hausa_vpl VALUES ("AC7_47","074_7_47","ACT","7","47","47","Amma Solomon ne ya gina masa gida. ");
INSERT INTO hausa_vpl VALUES ("AC7_48","074_7_48","ACT","7","48","48","“Duk da haka, Mafi Ɗaukaka ba ya zama a gidajen da mutane suka gina. Kamar yadda annabi ya faɗi cewa, ");
INSERT INTO hausa_vpl VALUES ("AC7_49","074_7_49","ACT","7","49","49","“ ‘Sama ne kursiyina, duniya kuma wurin ajiye tafin ƙafata. Wane irin gida za ka gina mini? Ko kuwa ina wurin hutuna zai kasance? In ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AC7_50","074_7_50","ACT","7","50","50","Ba hannuna ne ya yi dukan waɗannan abubuwa ba?’ ");
INSERT INTO hausa_vpl VALUES ("AC7_51","074_7_51","ACT","7","51","51","“Ku mutane masu taurinkai, da zukata da kuma kunnuwa marasa kaciya! Kuna kama da kakanninku. Kullum kuna tsayayya da Ruhu Mai Tsarki! ");
INSERT INTO hausa_vpl VALUES ("AC7_52","074_7_52","ACT","7","52","52","An yi wani annabin da kakanninku ba su tsananta wa ba? Sun ma kashe waɗanda suka yi maganar zuwan Mai Adalcin nan. Yanzu kuwa kun bashe shi kuka kuma kashe shi ");
INSERT INTO hausa_vpl VALUES ("AC7_53","074_7_53","ACT","7","53","53","ku da kuka karɓi dokar da aka sa a aiki ta wurin mala’iku amma ba ku yi biyayya da ita ba.” ");
INSERT INTO hausa_vpl VALUES ("AC7_54","074_7_54","ACT","7","54","54","Da membobin Sanhedrin suka ji haka, sai suka yi fushi suka ciji haƙoransu. ");
INSERT INTO hausa_vpl VALUES ("AC7_55","074_7_55","ACT","7","55","55","Amma Istifanus, cike da Ruhu Mai Tsarki, ya dubi sama ya kuma ga ɗaukakar Allah, da Yesu kuma tsaye a hannun dama na Allah. ");
INSERT INTO hausa_vpl VALUES ("AC7_56","074_7_56","ACT","7","56","56","Ya ce, “Ga shi, na ga sama a buɗe da kuma Ɗan Mutum tsaye a hannun dama na Allah.” ");
INSERT INTO hausa_vpl VALUES ("AC7_57","074_7_57","ACT","7","57","57","Da jin haka sai suka tattoshe kunnuwansu, suka kuma yi ihu da ƙarfi sosai, suka aukar masa gaba ɗaya. ");
INSERT INTO hausa_vpl VALUES ("AC7_58","074_7_58","ACT","7","58","58","Suka ja shi zuwa bayan birnin suka kuma yi ta jifansa da duwatsu. Ana cikin haka, shaidun suka ajiye tufafinsu a wurin wani saurayi mai suna Shawulu. ");
INSERT INTO hausa_vpl VALUES ("AC7_59","074_7_59","ACT","7","59","59","Yayinda suke cikin jifansa, sai Istifanus ya yi addu’a ya ce, “Ubangiji Yesu, ka karɓi ruhuna.” ");
INSERT INTO hausa_vpl VALUES ("AC7_60","074_7_60","ACT","7","60","60","Sa’an nan ya durƙusa ya ɗaga murya ya ce, “Ubangiji, kada ka riƙe wannan zunubi a kansu.” Da ya faɗi haka, sai ya yi barci. ");
INSERT INTO hausa_vpl VALUES ("AC8_1","074_8_1","ACT","8","1","1","Shawulu kuwa yana can, yana tabbatar da mutuwarsa. A wannan rana wani babban tsanani ya auka wa ikkilisiyar da take a Urushalima, sai duka suka warwatsu ko’ina a Yahudiya da Samariya, manzanni kaɗai ne suka rage. ");
INSERT INTO hausa_vpl VALUES ("AC8_2","074_8_2","ACT","8","2","2","Mutane masu tsoron Allah suka binne Istifanus suka kuma yi makoki ƙwarai dominsa. ");
INSERT INTO hausa_vpl VALUES ("AC8_3","074_8_3","ACT","8","3","3","Amma Shawulu ya fara hallaka ikkilisiya. Yana shiga gida-gida, yana jan maza da mata yana jefa su cikin kurkuku. ");
INSERT INTO hausa_vpl VALUES ("AC8_4","074_8_4","ACT","8","4","4","Waɗanda aka wartsar suka yi ta wa’azin maganar a duk inda suka tafi. ");
INSERT INTO hausa_vpl VALUES ("AC8_5","074_8_5","ACT","8","5","5","Filibus ya gangara zuwa wani birni a Samariya ya kuma yi shelar Kiristi a can. ");
INSERT INTO hausa_vpl VALUES ("AC8_6","074_8_6","ACT","8","6","6","Sa’ad da taron mutane suka ji Filibus suka kuma ga abubuwan banmamakin da ya yi, sai duk suka mai da hankali sosai ga abin da ya faɗa. ");
INSERT INTO hausa_vpl VALUES ("AC8_7","074_8_7","ACT","8","7","7","Mugayen ruhohi suka fiffito suna kururuwa daga cikin mutane da yawa, shanyayyu da guragu masu yawa suka sami warkarwa. ");
INSERT INTO hausa_vpl VALUES ("AC8_8","074_8_8","ACT","8","8","8","Saboda haka aka yi farin ciki ƙwarai a birnin. ");
INSERT INTO hausa_vpl VALUES ("AC8_9","074_8_9","ACT","8","9","9","To, akwai wani mutum mai suna Siman wanda ya kwana biyu yana yin sihiri a birnin har ya ba wa duk mutanen Samariya mamaki. Ya kuma yi taƙama cewa shi wani mai girma ne, ");
INSERT INTO hausa_vpl VALUES ("AC8_10","074_8_10","ACT","8","10","10","dukan mutane kuwa, manyan da ƙanana, suka mai da hankali gare shi suka kuma ce, “Mutumin nan shi ne ikon Allah da aka sani a matsayin Iko Mai Girma” ");
INSERT INTO hausa_vpl VALUES ("AC8_11","074_8_11","ACT","8","11","11","Suka bi shi domin ya daɗe yana ba su mamaki da sihirinsa. ");
INSERT INTO hausa_vpl VALUES ("AC8_12","074_8_12","ACT","8","12","12","Amma da suka gaskata da Filibus sa’ad da yake wa’azin labari mai daɗi na mulkin Allah da kuma sunan Yesu Kiristi, sai aka yi musu baftisma, maza da mata. ");
INSERT INTO hausa_vpl VALUES ("AC8_13","074_8_13","ACT","8","13","13","Siman kansa ya gaskata aka kuma yi masa baftisma. Ya kuma bi Filibus ko’ina, yana mamakin manyan alamu da ayyukan banmamakin da ya gani. ");
INSERT INTO hausa_vpl VALUES ("AC8_14","074_8_14","ACT","8","14","14","Sa’ad da manzannin da suke a Urushalima suka ji cewa Samariya ta karɓi maganar Allah, sai suka aika musu da Bitrus da Yohanna. ");
INSERT INTO hausa_vpl VALUES ("AC8_15","074_8_15","ACT","8","15","15","Da suka iso, sai suka yi musu addu’a domin su karɓi Ruhu Mai Tsarki, ");
INSERT INTO hausa_vpl VALUES ("AC8_16","074_8_16","ACT","8","16","16","domin Ruhu Mai Tsarki bai riga ya sauka wa waninsu ba tukuna, an dai yi musu baftisma ne kawai a cikin sunan Ubangiji Yesu. ");
INSERT INTO hausa_vpl VALUES ("AC8_17","074_8_17","ACT","8","17","17","Sa’an nan Bitrus da Yohanna suka ɗibiya hannuwansu a kansu, suka kuwa karɓi Ruhu Mai Tsarki. ");
INSERT INTO hausa_vpl VALUES ("AC8_18","074_8_18","ACT","8","18","18","Sa’ad da Siman ya ga cewa ana ba da Ruhu ta wurin ɗibiya hannuwan manzannin, sai ya miƙa musu kuɗi, ");
INSERT INTO hausa_vpl VALUES ("AC8_19","074_8_19","ACT","8","19","19","ya ce, “Ni ma ku ba ni wannan iyawa don kowa na ɗibiya wa hannuwana yă karɓi Ruhu Mai Tsarki.” ");
INSERT INTO hausa_vpl VALUES ("AC8_20","074_8_20","ACT","8","20","20","Bitrus ya amsa ya ce, “Bari kuɗinka ya hallaka tare da kai, domin ka yi tsammani za ka iya saya kyautar Allah da kuɗi! ");
INSERT INTO hausa_vpl VALUES ("AC8_21","074_8_21","ACT","8","21","21","Ba ruwanka da wannan hidimar, domin zuciyarka ba daidai take a gaban Allah ba. ");
INSERT INTO hausa_vpl VALUES ("AC8_22","074_8_22","ACT","8","22","22","Ka tuba daga wannan mugunta ka kuma yi addu’a ga Ubangiji. Wataƙila zai gafarta maka don irin tunanin da yake a zuciyarka. ");
INSERT INTO hausa_vpl VALUES ("AC8_23","074_8_23","ACT","8","23","23","Gama na lura kana cike da ɗacin rai kana kuma daure cikin zunubi.” ");
INSERT INTO hausa_vpl VALUES ("AC8_24","074_8_24","ACT","8","24","24","Sai Siman ya amsa ya ce, “Ku yi addu’a ga Ubangiji saboda ni don kada ko ɗaya daga cikin abin da ka faɗa ya same ni.” ");
INSERT INTO hausa_vpl VALUES ("AC8_25","074_8_25","ACT","8","25","25","Sa’ad da suka yi shaidar suka kuma yi shelar maganar Ubangiji, sai Bitrus da Yohanna suka koma Urushalima, suna wa’azin bishara a ƙauyukan Samariya masu yawa. ");
INSERT INTO hausa_vpl VALUES ("AC8_26","074_8_26","ACT","8","26","26","To wani mala’ikan Ubangiji ya ce wa Filibus, “Ka yi kudu zuwa hanyar, hanyar hamada, da ta gangara daga Urushalima zuwa Gaza.” ");
INSERT INTO hausa_vpl VALUES ("AC8_27","074_8_27","ACT","8","27","27","Saboda haka ya kama hanya, a kan hanyarsa kuwa sai ya sadu da wani mutumin Itiyofiya, wanda yake bābā, hafsa mai muhimmanci wanda yake lura da dukan ma’ajin Kandas (wanda yake nufin “sarauniyar mutanen Itiyofiya”). Mutumin nan ya tafi Urushalima ne domin yin sujada, ");
INSERT INTO hausa_vpl VALUES ("AC8_28","074_8_28","ACT","8","28","28","a kan hanyarsa ta komawa gida kuwa yana zaune bisan keken yaƙinsa yana karatun littafin annabin Ishaya. ");
INSERT INTO hausa_vpl VALUES ("AC8_29","074_8_29","ACT","8","29","29","Sai Ruhu ya ce wa Filibus, “Matsa wurin kekunan yaƙin nan ka yi kusa da ita.” ");
INSERT INTO hausa_vpl VALUES ("AC8_30","074_8_30","ACT","8","30","30","Sai Filibus ya ruga zuwa wajen keken yaƙin ya kuma ji mutumin yana karatun littafin annabin Ishaya. Filibus ya yi tambaya ya ce, “Ka fahimci abin da kake karantawa?” ");
INSERT INTO hausa_vpl VALUES ("AC8_31","074_8_31","ACT","8","31","31","Sai ya ce, “Ina fa zan iya, in ba dai wani ya fassara mini ba?” Saboda haka sai ya gayyaci Filibus yă hau yă zauna tare da shi. ");
INSERT INTO hausa_vpl VALUES ("AC8_32","074_8_32","ACT","8","32","32","Bābān yana karanta wannan Nassin, “An ja shi kamar tunkiya zuwa mayanka, kuma kamar ɗan rago a hannun mai askin gashinsa yake shiru, haka kuwa bai buɗe bakinsa ba. ");
INSERT INTO hausa_vpl VALUES ("AC8_33","074_8_33","ACT","8","33","33","A cikin wulaƙacinsa aka hana masa gaskiya. Wa zai iya yin zancen zuriyarsa? Gama an ɗauke ransa daga duniya.” ");
INSERT INTO hausa_vpl VALUES ("AC8_34","074_8_34","ACT","8","34","34","Sai bābān ya tambayi Filibus ya ce, “Ka gaya mini, ina roƙonka, annabin yana magana a kan wane ne, kansa ne, ko kuwa wani dabam?” ");
INSERT INTO hausa_vpl VALUES ("AC8_35","074_8_35","ACT","8","35","35","Sa’an nan Filibus ya fara da wannan Nassi ɗin ya kuma faɗa masa labari mai daɗi game da Yesu. ");
INSERT INTO hausa_vpl VALUES ("AC8_36","074_8_36","ACT","8","36","36","Yayinda suke cikin tafiya a kan hanya, sai suka iso wani wurin ruwa bābān nan ya ce, “Duba, ga ruwa. Me zai hana a yi mini baftisma?” ");
INSERT INTO hausa_vpl VALUES ("AC8_38","074_8_38","ACT","8","38","38","Ya kuwa ba da umarni a tsai da keken yaƙin. Sa’an nan da Filibus da bābān suka gangara zuwa cikin ruwan Filibus kuwa ya yi masa baftisma. ");
INSERT INTO hausa_vpl VALUES ("AC8_39","074_8_39","ACT","8","39","39","Sa’ad da suka fita daga cikin ruwan, sai Ruhun Ubangiji ya fyauce Filibus, bābān kuwa bai ƙara ganinsa ba, amma ya ci gaba da tafiyarsa yana farin ciki. ");
INSERT INTO hausa_vpl VALUES ("AC8_40","074_8_40","ACT","8","40","40","Filibus kuwa ya fito a Azotus, ya yi ta zagawa, yana wa’azin bishara a dukan garuruwan sai da ya kai Kaisariya. ");
INSERT INTO hausa_vpl VALUES ("AC9_1","074_9_1","ACT","9","1","1","Ana cikin haka, Shawulu ya ɗage yana barazana yin kisa da tsananta wa almajiran Ubangiji. Sai ya je wurin babban firist ");
INSERT INTO hausa_vpl VALUES ("AC9_2","074_9_2","ACT","9","2","2","ya roƙe shi ya ba shi wasiƙu zuwa majami’un Damaskus, don in ya sami wani a wurin wanda yake bin wannan Hanya, ko maza ko mata, yă kama su a matsayin ’yan kurkuku yă kai Urushalima. ");
INSERT INTO hausa_vpl VALUES ("AC9_3","074_9_3","ACT","9","3","3","Da ya yi kusa da Damaskus a kan hanyarsa, ba zato ba tsammani sai wani haske daga sama ya haskaka kewaye da shi. ");
INSERT INTO hausa_vpl VALUES ("AC9_4","074_9_4","ACT","9","4","4","Sai ya fāɗi a ƙasa ya kuma ji wata murya ta ce masa, “Shawulu, Shawulu, don me kake tsananta mini?” ");
INSERT INTO hausa_vpl VALUES ("AC9_5","074_9_5","ACT","9","5","5","Shawulu ya yi tambaya ya ce, “Wane ne kai, ya Ubangiji?” Ya amsa ya ce, “Ni ne Yesu wanda kake tsananta wa. ");
INSERT INTO hausa_vpl VALUES ("AC9_6","074_9_6","ACT","9","6","6","Yanzu ka tashi ka shiga cikin birnin, za a kuma gaya maka abin da dole za ka yi.” ");
INSERT INTO hausa_vpl VALUES ("AC9_7","074_9_7","ACT","9","7","7","Mutanen da suke tafiya tare da Shawulu suka rasa bakin magana; sun ji muryar amma ba su ga kowa ba. ");
INSERT INTO hausa_vpl VALUES ("AC9_8","074_9_8","ACT","9","8","8","Shawulu ya tashi daga ƙasa, amma sa’ad da ya buɗe idanunsa bai iya ganin wani abu ba. Saboda haka aka kama hannunsa aka yi masa jagora zuwa cikin Damaskus. ");
INSERT INTO hausa_vpl VALUES ("AC9_9","074_9_9","ACT","9","9","9","Kwana uku yana a makance, bai ci ba bai kuma sha kome ba. ");
INSERT INTO hausa_vpl VALUES ("AC9_10","074_9_10","ACT","9","10","10","A Damaskus kuwa akwai wani almajiri mai suna Ananiyas. Ubangiji ya kira shi a cikin wahayi ya ce, “Ananiyas!” Ananiyas ya amsa, “Ga ni, ya Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("AC9_11","074_9_11","ACT","9","11","11","Ubangiji ya ce masa, “Je gidan Yahuda da yake a Miƙaƙƙen Titi ka yi tambaya ko akwai wani mutum daga Tarshish mai suna Shawulu, gama ga shi yana addu’a. ");
INSERT INTO hausa_vpl VALUES ("AC9_12","074_9_12","ACT","9","12","12","Cikin wahayi ya ga wani mutum mai suna Ananiyas ya zo ya sa hannuwansa a kansa don yă sāke samun ganin gari.” ");
INSERT INTO hausa_vpl VALUES ("AC9_13","074_9_13","ACT","9","13","13","Ananiyas ya amsa ya ce, “Ubangiji, na ji labarin mutumin nan sosai da kuma duk lahanin da ya yi wa tsarkakanka a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("AC9_14","074_9_14","ACT","9","14","14","Ga shi kuma ya zo nan da izinin manyan firistoci, don yă kama duk wanda yake kiran bisa sunanka.” ");
INSERT INTO hausa_vpl VALUES ("AC9_15","074_9_15","ACT","9","15","15","Amma Ubangiji ya ce wa Ananiyas, “Je ka! Wannan mutum zaɓaɓɓen kayan aikina ne don yă kai sunana a gaban Al’ummai da sarakunansu da kuma a gaban mutanen Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("AC9_16","074_9_16","ACT","9","16","16","Zan nuna masa wahalar da dole zai sha saboda sunana.” ");
INSERT INTO hausa_vpl VALUES ("AC9_17","074_9_17","ACT","9","17","17","Sa’an nan Ananiyas ya tafi gidan ya kuma shiga ciki. Da ya sa hannuwansa a kan Shawulu, sai ya ce, “Ɗan’uwana Shawulu, Ubangiji, Yesu, wanda ya bayyana gare ka a kan hanya yayinda kake zuwa nan, ya aiko ni domin ka sāke gani a kuma cika ka da Ruhu Mai Tsarki.” ");
INSERT INTO hausa_vpl VALUES ("AC9_18","074_9_18","ACT","9","18","18","Nan da nan, sai wani abu kamar ɓawo ya fāɗo daga idanun Shawulu, ya kuma sāke iya ganin gari. Sai ya tashi aka kuma yi masa baftisma, ");
INSERT INTO hausa_vpl VALUES ("AC9_19","074_9_19","ACT","9","19","19","bayan ya ci abinci, sai sāke samun ƙarfi. Shawulu ya yi kwanaki masu yawa tare da almajiran da suke a Damaskus. ");
INSERT INTO hausa_vpl VALUES ("AC9_20","074_9_20","ACT","9","20","20","Nan take ya fara wa’azi cikin majami’u cewa Yesu Ɗan Allah ne. ");
INSERT INTO hausa_vpl VALUES ("AC9_21","074_9_21","ACT","9","21","21","Dukan waɗanda suka ji shi suka yi mamaki suka ce, “Ba shi ne mutumin da ya tā-da-na-zaune-tsaye a kan masu kira bisa ga wannan sunan a Urushalima ba? Ba ya zo nan ne don yă kai su a matsayin ’yan kurkuku ga manyan firistoci ba?” ");
INSERT INTO hausa_vpl VALUES ("AC9_22","074_9_22","ACT","9","22","22","Duk da haka Shawulu ya yi ta ƙara ƙarfi, ya kuma rikitar da Yahudawan da suke zaune a Damaskus, ta wurin tabbatar musu cewa, Yesu shi ne Kiristi. ");
INSERT INTO hausa_vpl VALUES ("AC9_23","074_9_23","ACT","9","23","23","Bayan kwanaki masu yawa, sai Yahudawa suka haɗa baki su kashe shi, ");
INSERT INTO hausa_vpl VALUES ("AC9_24","074_9_24","ACT","9","24","24","amma Shawulu ya sami labarin shirinsu. Dare da rana suka yi fakonsa a ƙofofin birnin don su kashe shi. ");
INSERT INTO hausa_vpl VALUES ("AC9_25","074_9_25","ACT","9","25","25","Amma almajiransa suka ɗauke shi da dare suka saukar da shi a cikin kwando ta taga a katanga. ");
INSERT INTO hausa_vpl VALUES ("AC9_26","074_9_26","ACT","9","26","26","Da ya zo Urushalima, ya yi ƙoƙarin shiga cikin almajiran amma dukansu suka ji tsoronsa, ba su gaskata cewa tabbatacce shi almajiri ba ne. ");
INSERT INTO hausa_vpl VALUES ("AC9_27","074_9_27","ACT","9","27","27","Amma Barnabas ya ɗauke shi ya kawo shi wurin manzanni. Ya gaya musu yadda Shawulu a kan hanyarsa ya ga Ubangiji kuma cewa Ubangiji ya yi magana da shi, da yadda a Damaskus ya yi wa’azi ba tsoro a cikin sunan Yesu. ");
INSERT INTO hausa_vpl VALUES ("AC9_28","074_9_28","ACT","9","28","28","Saboda haka Shawulu ya zauna tare da su yana kai da kawowa a sake a cikin Urushalima, yana magana gabagadi a cikin sunan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AC9_29","074_9_29","ACT","9","29","29","Ya yi magana ya kuma yi muhawwara da Yahudawa masu jin Hellenanci, amma suka yi ƙoƙarin kashe shi. ");
INSERT INTO hausa_vpl VALUES ("AC9_30","074_9_30","ACT","9","30","30","Sa’ad da ’yan’uwa suka sami labarin wannan, sai suka ɗauke shi zuwa Kaisariya suka aika da shi Tarshish. ");
INSERT INTO hausa_vpl VALUES ("AC9_31","074_9_31","ACT","9","31","31","Sa’an nan ikkilisiya ko’ina a Yahudiya, Galili da kuma Samariya ta sami salama. Ta yi ƙarfi; ta kuma ƙarfafa ta wurin Ruhu Mai Tsarki, ta ƙaru sosai tana rayuwa cikin tsoron Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AC9_32","074_9_32","ACT","9","32","32","Da Bitrus yake zazzaga ƙasar, sai ya je ya ziyarci tsarkakan da suke a Lidda. ");
INSERT INTO hausa_vpl VALUES ("AC9_33","074_9_33","ACT","9","33","33","A can ya tarar da wani mutum mai suna Eniyas, shanyayye wanda yake kwance kan gado shekara takwas. ");
INSERT INTO hausa_vpl VALUES ("AC9_34","074_9_34","ACT","9","34","34","Sai Bitrus ya ce masa, “Eniyas, Yesu Kiristi ya warkar da kai. Tashi ka naɗe tabarmarka.” Nan da nan Eniyas ya tashi. ");
INSERT INTO hausa_vpl VALUES ("AC9_35","074_9_35","ACT","9","35","35","Duk waɗanda suke zama a Lidda da Sharon suka gan shi suka kuma juyo ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AC9_36","074_9_36","ACT","9","36","36","A Yoffa akwai wata almajira mai suna Tabita (a harshen Girik sunanta shi ne Dokas); ita mai aikin alheri ce kullum, tana kuma taimakon matalauta. ");
INSERT INTO hausa_vpl VALUES ("AC9_37","074_9_37","ACT","9","37","37","A lokacin nan ta yi rashin lafiya ta mutu, aka kuma yi wa gawarta wanka aka ajiye a wani ɗaki a gidan sama. ");
INSERT INTO hausa_vpl VALUES ("AC9_38","074_9_38","ACT","9","38","38","Lidda yana kusa da Yoffa; saboda haka sa’ad da almajirai suka ji cewa Bitrus yana a Lidda, sai suka aiki mutum biyu wurinsa su roƙe shi cewa, “In ka yarda ka zo nan da nan!” ");
INSERT INTO hausa_vpl VALUES ("AC9_39","074_9_39","ACT","9","39","39","Sai Bitrus ya tafi tare da su, sa’ad da ya iso sai aka kai shi ɗakin saman. Duka gwauraye suka tsaya kewaye da shi, suna kuka suna nunnuna masa riguna da kuma waɗansu tufafin da Dokas ta yi yayinda take tare da su. ");
INSERT INTO hausa_vpl VALUES ("AC9_40","074_9_40","ACT","9","40","40","Bitrus ya fitar da su duka daga ɗakin; sa’an nan ya durƙusa ya yi addu’a. Da ya juya wajen matacciyar, sai ya ce, “Tabita, tashi.” Ta buɗe idanunta, ta ga Bitrus sai ta tashi zaune. ");
INSERT INTO hausa_vpl VALUES ("AC9_41","074_9_41","ACT","9","41","41","Ya kama ta a hannu ya taimake ta ta tsaya a ƙafafunta. Sa’an nan ya kira masu bi da kuma gwaurayen ya miƙa musu ita da rai. ");
INSERT INTO hausa_vpl VALUES ("AC9_42","074_9_42","ACT","9","42","42","Wannan ya zama sananne ko’ina a Yoffa, mutane da yawa kuma suka gaskata da Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AC9_43","074_9_43","ACT","9","43","43","Bitrus ya zauna a Yoffa na ɗan lokaci tare da wani mai aikin fatu mai suna Siman. ");
INSERT INTO hausa_vpl VALUES ("AC10_1","074_10_1","ACT","10","1","1","A Kaisariya akwai wani mutum mai suna Korneliyus, wani jarumin Roma ne, a ƙungiyar soja da ake kira Bataliyar Italiya. ");
INSERT INTO hausa_vpl VALUES ("AC10_2","074_10_2","ACT","10","2","2","Shi da dukan iyalinsa masu ibada ne masu tsoron Allah kuma; yakan ba da kyauta hannu sake ga masu bukata yana kuma addu’a ga Allah ba fasawa. ");
INSERT INTO hausa_vpl VALUES ("AC10_3","074_10_3","ACT","10","3","3","Wata rana wajen ƙarfe uku na yamma ya ga wahayi. A sarari ya ga wani mala’ikan Allah, wanda ya zo wajensa ya ce, “Korneliyus!” ");
INSERT INTO hausa_vpl VALUES ("AC10_4","074_10_4","ACT","10","4","4","Korneliyus kuwa ya zura masa ido a tsorace ya ce, “Mene ne, ya Ubangiji?” Mala’ikan ya ce, “Addu’o’inka da kyautanka ga matalauta sun kai har sama, hadayar tunawa ce a gaban Allah. ");
INSERT INTO hausa_vpl VALUES ("AC10_5","074_10_5","ACT","10","5","5","Yanzu sai ka aiki mutane zuwa Yoffa su dawo da wani mutum mai suna Siman wanda ake kira Bitrus. ");
INSERT INTO hausa_vpl VALUES ("AC10_6","074_10_6","ACT","10","6","6","Yana zama tare da Siman, mai aikin fatu, wanda gidansa ke bakin teku.” ");
INSERT INTO hausa_vpl VALUES ("AC10_7","074_10_7","ACT","10","7","7","Sa’ad da mala’ikan da ya yi masa magana ya tafi, sai Korneliyus ya kira biyu daga cikin bayinsa da kuma wani soja mai ibada wanda yake ɗaya a cikin masu yin masa hidima. ");
INSERT INTO hausa_vpl VALUES ("AC10_8","074_10_8","ACT","10","8","8","Ya fada musu duk abin da ya faru sa’an nan ya aike su Yoffa. ");
INSERT INTO hausa_vpl VALUES ("AC10_9","074_10_9","ACT","10","9","9","Wajen tsakar rana kashegari yayinda suke cikin tafiyarsu suna kuma dab da birnin, sai Bitrus ya hau bisan rufin gida yă yi addu’a. ");
INSERT INTO hausa_vpl VALUES ("AC10_10","074_10_10","ACT","10","10","10","Yunwa ta kama shi ya kuwa so yă ci wani abu, yayinda ake shirya abinci, sai wahayi ya zo masa. ");
INSERT INTO hausa_vpl VALUES ("AC10_11","074_10_11","ACT","10","11","11","Ya ga sama ya buɗe ana kuwa saukowa wani abu ƙasa kamar babban mayafi zuwa duniya ta kusurwansa huɗu. ");
INSERT INTO hausa_vpl VALUES ("AC10_12","074_10_12","ACT","10","12","12","Cikinsa kuwa akwai kowace irin dabba mai ƙafa huɗu da masu ja da ciki na duniya da kuma tsuntsayen sararin sama. ");
INSERT INTO hausa_vpl VALUES ("AC10_13","074_10_13","ACT","10","13","13","Sa’an nan wata murya ta ce masa, “Bitrus, ka tashi. Ka yanka ka ci.” ");
INSERT INTO hausa_vpl VALUES ("AC10_14","074_10_14","ACT","10","14","14","Bitrus ya ce, “Sam, Ubangiji! Ban taɓa cin wani abu marar tsarki ko marar tsabta ba.” ");
INSERT INTO hausa_vpl VALUES ("AC10_15","074_10_15","ACT","10","15","15","Muryar ta yi magana da shi sau na biyu ta ce, “Kada ka ce da abin da Allah ya tsarkake marar tsarki.” ");
INSERT INTO hausa_vpl VALUES ("AC10_16","074_10_16","ACT","10","16","16","Wannan ya faru har sau uku, sai nan da nan aka ɗauke mayafin zuwa sama. ");
INSERT INTO hausa_vpl VALUES ("AC10_17","074_10_17","ACT","10","17","17","Tun Bitrus yana cikin tunani game da ma’anar wahayin nan, sai ga mutanen da Korneliyus ya aika sun sami gidan Siman suna kuma tsaye a ƙofar. ");
INSERT INTO hausa_vpl VALUES ("AC10_18","074_10_18","ACT","10","18","18","Suka yi sallama, suna tambaya ko Siman wanda aka sani da suna Bitrus yana zama a can. ");
INSERT INTO hausa_vpl VALUES ("AC10_19","074_10_19","ACT","10","19","19","Yayinda Bitrus yana cikin tunani game da wahayin, sai Ruhu ya ce masa, “Siman, ga mutum uku suna nemanka. ");
INSERT INTO hausa_vpl VALUES ("AC10_20","074_10_20","ACT","10","20","20","Saboda haka ka tashi ka sauka. Kada ka yi wata-wata, gama ni ne na aiko su.” ");
INSERT INTO hausa_vpl VALUES ("AC10_21","074_10_21","ACT","10","21","21","Sai Bitrus ya sauka ya ce wa mutanen, “Ni ne kuke nema. Me ya kawo ku?” ");
INSERT INTO hausa_vpl VALUES ("AC10_22","074_10_22","ACT","10","22","22","Mutanen suka amsa, “Mun zo ne daga wurin Korneliyus wani jarumin. Shi mutum ne mai adalci mai tsoron Allah kuma, wanda dukan Yahudawa ke girmamawa. Wani mala’ika mai tsarki ya faɗa masa, yă sa ka zo gidansa don yă ji abin da za ka faɗa.” ");
INSERT INTO hausa_vpl VALUES ("AC10_23","074_10_23","ACT","10","23","23","Sai Bitrus ya gayyaci mutanen cikin gida su zama baƙinsa. Kashegari Bitrus ya tafi tare da su, waɗansu ’yan’uwa daga Yoffa kuwa suka tafi tare da shi. ");
INSERT INTO hausa_vpl VALUES ("AC10_24","074_10_24","ACT","10","24","24","Kashegari sai ya iso Kaisariya. Korneliyus kuwa yana nan yana jiransu, ya kuma gayyaci ’yan’uwansa da abokansa na kusa. ");
INSERT INTO hausa_vpl VALUES ("AC10_25","074_10_25","ACT","10","25","25","Da Bitrus ya shiga gidan, Korneliyus ya sadu da shi ya kuma fāɗi a gabansa cikin bangirma. ");
INSERT INTO hausa_vpl VALUES ("AC10_26","074_10_26","ACT","10","26","26","Amma Bitrus ya sa shi ya tashi. Ya ce, “Tashi, ni mutum ne kawai.” ");
INSERT INTO hausa_vpl VALUES ("AC10_27","074_10_27","ACT","10","27","27","Yana magana da shi, sai Bitrus ya shiga ciki ya kuma tarar da taron mutane da yawa. ");
INSERT INTO hausa_vpl VALUES ("AC10_28","074_10_28","ACT","10","28","28","Sai ya ce musu, “Ku da kanku kun san cewa dokarmu ta hana mutumin Yahuda yin cuɗanya, ko ya ziyarci Ba’al’umme. Amma Allah ya nuna mini cewa kada in kira wani mutum marar tsarki ko marar tsabta. ");
INSERT INTO hausa_vpl VALUES ("AC10_29","074_10_29","ACT","10","29","29","Don haka sa’ad da aka aika in zo, na zo ba wata faɗa. To, ko zan san abin da ya sa ka aika in zo?” ");
INSERT INTO hausa_vpl VALUES ("AC10_30","074_10_30","ACT","10","30","30","Korneliyus ya amsa ya ce, “Kwana huɗu da suka wuce ina a gidana ina addu’a a wannan lokaci, wajen ƙarfe uku na yamma. Ba zato ba tsammani sai ga wani mutum cikin tufafi masu walƙiya ya tsaya a gabana ");
INSERT INTO hausa_vpl VALUES ("AC10_31","074_10_31","ACT","10","31","31","ya ce, ‘Korneliyus, Allah ya ji addu’arka, ya kuma tuna da kyautanka ga matalauta. ");
INSERT INTO hausa_vpl VALUES ("AC10_32","074_10_32","ACT","10","32","32","Ka aika zuwa Yoffa don a kira Siman wanda ake ce da shi Bitrus. Shi baƙo ne a gidan Siman mai aikin fatu, wanda yake zama a bakin teku.’ ");
INSERT INTO hausa_vpl VALUES ("AC10_33","074_10_33","ACT","10","33","33","Saboda haka na aika a zo da kai nan da nan, ya kuma yi kyau da ka zo. To ga mu duka a nan a gaban Allah don mu saurari dukan abin da Ubangiji ya umarce ka ka faɗa mana.” ");
INSERT INTO hausa_vpl VALUES ("AC10_34","074_10_34","ACT","10","34","34","Sa’an nan Bitrus ya fara magana ya ce, “Yanzu na gane yadda gaskiya ne cewa Allah ba ya sonkai ");
INSERT INTO hausa_vpl VALUES ("AC10_35","074_10_35","ACT","10","35","35","amma yana karɓan mutane daga kowace al’ummar da take tsoronsa suke kuma aikata abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("AC10_36","074_10_36","ACT","10","36","36","Kun san saƙon da Allah ya aika wa mutanen Isra’ila, yana shelar labari mai daɗi na salama ta wurin Yesu Kiristi, shi ne kuwa Ubangijin kowa. ");
INSERT INTO hausa_vpl VALUES ("AC10_37","074_10_37","ACT","10","37","37","Kun san abin da ya faru a dukan Yahudiya, farawa daga Galili bayan baftismar da Yohanna ya yi wa’azi, ");
INSERT INTO hausa_vpl VALUES ("AC10_38","074_10_38","ACT","10","38","38","yadda Allah ya shafe Yesu Banazare da Ruhu Mai Tsarki da kuma iko, da kuma yadda ya zaga ko’ina yana aikata alheri yana kuma warkar da dukan waɗanda suke ƙarƙashin ikon Iblis, domin Allah yana tare da shi. ");
INSERT INTO hausa_vpl VALUES ("AC10_39","074_10_39","ACT","10","39","39","“Mu kuwa shaidu ne na dukan abin da ya yi a ƙasar Yahudawa da kuma a Urushalima. Suka kashe shi ta wurin rataye shi a kan itace, ");
INSERT INTO hausa_vpl VALUES ("AC10_40","074_10_40","ACT","10","40","40","amma Allah ya tashe shi daga matattu a rana ta uku, ya sa kuma aka gan shi. ");
INSERT INTO hausa_vpl VALUES ("AC10_41","074_10_41","ACT","10","41","41","Ba dukan mutane ne suka gan shi ba, amma ta wurin shaidun da Allah ya riga ya zaɓa, ta wurinmu da muka ci muka kuma sha tare da shi bayan tashinsa daga matattu. ");
INSERT INTO hausa_vpl VALUES ("AC10_42","074_10_42","ACT","10","42","42","Ya umarce mu mu yi wa’azi ga mutane mu kuma shaida cewa shi ne wanda Allah ya naɗa yă zama mai shari’a na masu rai da na matattu. ");
INSERT INTO hausa_vpl VALUES ("AC10_43","074_10_43","ACT","10","43","43","Duk annabawa sun yi shaida game da shi cewa duk wanda ya ba da gaskiya gare shi zai sami gafarar zunubai ta wurin sunansa.” ");
INSERT INTO hausa_vpl VALUES ("AC10_44","074_10_44","ACT","10","44","44","Tun Bitrus yana cikin faɗin waɗannan kalmomi, sai Ruhu Mai Tsarki ya sauka wa duk waɗanda suka ji saƙon. ");
INSERT INTO hausa_vpl VALUES ("AC10_45","074_10_45","ACT","10","45","45","Masu bin da suke da kaciya waɗanda suka zo tare da Bitrus suka yi mamaki cewa an ba da kyautar Ruhu Mai Tsarki har ma a kan Al’ummai. ");
INSERT INTO hausa_vpl VALUES ("AC10_46","074_10_46","ACT","10","46","46","Gama sun ji su suna magana da waɗansu harsuna suna kuma yabon Allah. Sai Bitrus ya ce, ");
INSERT INTO hausa_vpl VALUES ("AC10_47","074_10_47","ACT","10","47","47","“Wani zai iya hana a yi wa waɗannan mutane baftisma da ruwa? Sun karɓi Ruhu Mai Tsarki kamar yadda muka karɓa.” ");
INSERT INTO hausa_vpl VALUES ("AC10_48","074_10_48","ACT","10","48","48","Saboda haka ya ba da umarni a yi musu baftisma cikin sunan Yesu Kiristi. Sa’an nan suka roƙi Bitrus yă zauna da su na ’yan kwanaki. ");
INSERT INTO hausa_vpl VALUES ("AC11_1","074_11_1","ACT","11","1","1","Manzanni da ’yan’uwa ko’ina a Yahudiya suka ji cewa Al’ummai ma sun karɓi maganar Allah. ");
INSERT INTO hausa_vpl VALUES ("AC11_2","074_11_2","ACT","11","2","2","Saboda haka sa’ad da Bitrus ya haura zuwa Urushalima, masu bin da suke da kaciya suka zarge shi ");
INSERT INTO hausa_vpl VALUES ("AC11_3","074_11_3","ACT","11","3","3","suka ce, “Ka je gidan mutanen da suke marasa kaciya ka kuwa ci tare da su.” ");
INSERT INTO hausa_vpl VALUES ("AC11_4","074_11_4","ACT","11","4","4","Bitrus ya fara yin musu bayani dalla-dalla yadda ya faru cewa, ");
INSERT INTO hausa_vpl VALUES ("AC11_5","074_11_5","ACT","11","5","5","“Ina a birnin Yoffa ina addu’a, sai ga wahayi ya zo mini. Na ga ana sauko da wani abu kamar babban mayafi daga sama ta kusurwansa huɗu, ya kuma sauko inda nake. ");
INSERT INTO hausa_vpl VALUES ("AC11_6","074_11_6","ACT","11","6","6","Na duba cikinsa na ga dabbobi masu ƙafa huɗu na duniya, da namun jeji, da masu ja da ciki, da kuma tsuntsayen sararin sama. ");
INSERT INTO hausa_vpl VALUES ("AC11_7","074_11_7","ACT","11","7","7","Sa’an nan na ji wata murya tana ce mini, ‘Bitrus, ka tashi. Ka yanka ka ci.’ ");
INSERT INTO hausa_vpl VALUES ("AC11_8","074_11_8","ACT","11","8","8","“Na amsa na ce, ‘Sam, Ubangiji! Ban taɓa cin wani abu marar tsarki ko marar tsabta ba.’ ");
INSERT INTO hausa_vpl VALUES ("AC11_9","074_11_9","ACT","11","9","9","“Sai muryar daga sama ta yi magana sau na biyu, ta ce, ‘Kada ka ce da abin da Allah ya tsarkake marar tsarki.’ ");
INSERT INTO hausa_vpl VALUES ("AC11_10","074_11_10","ACT","11","10","10","Wannan ya faru har sau uku, sa’an nan duk aka sāke ɗauke shi zuwa sama. ");
INSERT INTO hausa_vpl VALUES ("AC11_11","074_11_11","ACT","11","11","11","“Nan take sai ga mutum uku da aka aika wurina daga Kaisariya a tsaye a ƙofar gidan da nake. ");
INSERT INTO hausa_vpl VALUES ("AC11_12","074_11_12","ACT","11","12","12","Ruhu ya ce mini kada in yi wata-wata game da tafiya tare da su. Waɗannan ’yan’uwa guda shida su ma suka rako ni, muka kuwa shiga gidan mutumin. ");
INSERT INTO hausa_vpl VALUES ("AC11_13","074_11_13","ACT","11","13","13","Ya kuma gaya mana yadda wani mala’ika ya bayyana a gidansa ya ce masa, ‘Ka aika zuwa Yoffa a kira Siman wanda ake ce da shi Bitrus. ");
INSERT INTO hausa_vpl VALUES ("AC11_14","074_11_14","ACT","11","14","14","Zai kawo maka saƙo wanda ta wurinsa kai da dukan iyalinka za ku sami ceto.’ ");
INSERT INTO hausa_vpl VALUES ("AC11_15","074_11_15","ACT","11","15","15","“Na fara magana ke nan, sai Ruhu Mai Tsarki ya sauko musu yadda ya sauko mana a farko. ");
INSERT INTO hausa_vpl VALUES ("AC11_16","074_11_16","ACT","11","16","16","Sa’an nan na tuna da abin da Ubangiji ya ce, ‘Yohanna ya yi baftisma da ruwa, amma za a yi muku baftisma daRuhu Mai Tsarki.’ ");
INSERT INTO hausa_vpl VALUES ("AC11_17","074_11_17","ACT","11","17","17","To, in Allah ya ba su kyauta yadda ya ba mu, mu da muka gaskata da Ubangiji Yesu Kiristi, wane ni da zan yi hamayya da Allah?” ");
INSERT INTO hausa_vpl VALUES ("AC11_18","074_11_18","ACT","11","18","18","Sa’ad da suka ji haka, ba su ƙara yin faɗa ba, suka kuma ɗaukaka Allah, suna cewa, “To, fa, har Al’ummai ma Allah ya sa suka tuba zuwa rai.” ");
INSERT INTO hausa_vpl VALUES ("AC11_19","074_11_19","ACT","11","19","19","To, waɗanda suka warwatsu saboda tsananin da ya tashi a kan batun Istifanus suka tafi har Funisiya, Saifurus da kuma Antiyok, suna ba da saƙon ga Yahudawa kaɗai. ");
INSERT INTO hausa_vpl VALUES ("AC11_20","074_11_20","ACT","11","20","20","Amma waɗansunsu kuwa, mutane daga Saifurus da Sairin, suka je Antiyok suka fara yi wa Hellenawa magana su ma, suna ba da labari mai daɗi game da Ubangiji Yesu. ");
INSERT INTO hausa_vpl VALUES ("AC11_21","074_11_21","ACT","11","21","21","Hannun Ubangiji kuwa yana tare da su, mutane da yawan gaske kuwa suka gaskata suka juya ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AC11_22","074_11_22","ACT","11","22","22","Labari wannan abu ya kai kunnuwan ikkilisiya a Urushalima, sai suka aiki Barnabas zuwa Antiyok. ");
INSERT INTO hausa_vpl VALUES ("AC11_23","074_11_23","ACT","11","23","23","Da ya iso ya kuma ga tabbacin alherin Allah, sai ya yi farin ciki ya kuma ƙarfafa su duka su tsaya da gaskiya cikin Ubangiji da dukan zukatansu. ");
INSERT INTO hausa_vpl VALUES ("AC11_24","074_11_24","ACT","11","24","24","Mutum ne nagari, cike da Ruhu Mai Tsarki da bangaskiya, mutane masu yawan gaske kuwa suka juya ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AC11_25","074_11_25","ACT","11","25","25","Sa’an nan Barnabas ya tafi Tarshish don yă nemi Shawulu, ");
INSERT INTO hausa_vpl VALUES ("AC11_26","074_11_26","ACT","11","26","26","sa’ad da ya same shi kuwa, sai ya kawo shi Antiyok. Ta haka shekara guda cur Barnabas da Shawulu suka yi suna taruwa da ikkilisiya, suka kuma koya wa mutane masu yawan gaske. A Antiyok ne aka fara kiran almajirai da suna Kirista. ");
INSERT INTO hausa_vpl VALUES ("AC11_27","074_11_27","ACT","11","27","27","A wannan lokaci waɗansu annabawa sun zo Antiyok daga Urushalima. ");
INSERT INTO hausa_vpl VALUES ("AC11_28","074_11_28","ACT","11","28","28","Ɗaya daga cikinsu mai suna Agabus, ya miƙe tsaye ya yi annabci ta wurin Ruhu cewa za a yi yunwa mai tsanani wadda za tă bazu a dukan duniyar Romawa (Wannan ya faru a zamanin mulkin Kalaudiyus.) ");
INSERT INTO hausa_vpl VALUES ("AC11_29","074_11_29","ACT","11","29","29","Kowanne a cikin almajiran, gwargwadon azancinsa, ya yanke shawara ya ba da gudummawa ga ’yan’uwan da suke zama a Yahudiya. ");
INSERT INTO hausa_vpl VALUES ("AC11_30","074_11_30","ACT","11","30","30","Haka kuwa suka yi, suka aika da kyautarsa wa dattawan ikkilisiyar ta hannu Barnabas da Shawulu. ");
INSERT INTO hausa_vpl VALUES ("AC12_1","074_12_1","ACT","12","1","1","Kusan a wannan lokaci ne Sarki Hiridus ya kama waɗansu da suke na ikkilisiya, da niyya ya tsananta musu. ");
INSERT INTO hausa_vpl VALUES ("AC12_2","074_12_2","ACT","12","2","2","Ya sa aka kashe Yaƙub, ɗan’uwan Yohanna, da takobi. ");
INSERT INTO hausa_vpl VALUES ("AC12_3","074_12_3","ACT","12","3","3","Sa’ad da ya ga wannan ya faranta wa Yahudawa rai, sai ya kama Bitrus shi ma. Wannan ya faru kwanakin Bikin Burodi Marar Yisti. ");
INSERT INTO hausa_vpl VALUES ("AC12_4","074_12_4","ACT","12","4","4","Bayan ya kama shi, sai ya sa shi a kurkuku, ya danƙa shi a hannun soja hurhuɗu kashi huɗu, don su yi gadinsa. Hiridus ya yi niyyar ya yi masa shari’a a gaban mutane bayan Bikin Ƙetarewa. ");
INSERT INTO hausa_vpl VALUES ("AC12_5","074_12_5","ACT","12","5","5","Saboda haka aka tsare Bitrus a kurkuku, amma ikkilisiya ta nace da addu’a ga Allah dominsa. ");
INSERT INTO hausa_vpl VALUES ("AC12_6","074_12_6","ACT","12","6","6","A daren da in gari ya waye da Hiridus yake niyyar kawo shi domin a yi masa shari’a, Bitrus yana barci tsakanin sojoji biyu, daure da sarƙoƙi biyu, masu gadi kuma suna bakin ƙofa. ");
INSERT INTO hausa_vpl VALUES ("AC12_7","074_12_7","ACT","12","7","7","Ba zato ba tsammani sai mala’ikan Ubangiji ya bayyana haske kuma ya haskaka a ɗakin. Ya bugi Bitrus a gefe ya kuma tashe shi ya ce, “Maza, ka tashi!” Sarƙoƙin kuwa suka zube daga hannuwansa. ");
INSERT INTO hausa_vpl VALUES ("AC12_8","074_12_8","ACT","12","8","8","Sa’an nan mala’ikan ya ce masa, “Ka sa rigunarka da takalmanka.” Bitrus kuwa ya sa. Mala’ikan ya faɗa masa cewa, “Ka yafa mayafinka ka bi ni.” ");
INSERT INTO hausa_vpl VALUES ("AC12_9","074_12_9","ACT","12","9","9","Bitrus ya bi shi suka fita kurkukun, amma bai ma san cewa abin da mala’ikan yake yi tabbatacce ne ba; yana tsammani wahayi yake gani. ");
INSERT INTO hausa_vpl VALUES ("AC12_10","074_12_10","ACT","12","10","10","Suka wuce masu gadi na fari da na biyu, suka kuma isa ƙofar ƙarfe ta shiga birni. Ƙofar kuwa ta buɗe musu da kanta, suka kuma wuce. Sa’ad da suka yi tafiya tsawon wani titi, nan take mala’ikan ya bar shi. ");
INSERT INTO hausa_vpl VALUES ("AC12_11","074_12_11","ACT","12","11","11","Sai Bitrus ya dawo hankalinsa ya ce, “Yanzu na sani ba shakka Ubangiji ne ya aiki mala’ikansa yă cece ni daga hannun Hiridus da kuma dukan mugun fatan Yahudawa.” ");
INSERT INTO hausa_vpl VALUES ("AC12_12","074_12_12","ACT","12","12","12","Da ya gane haka, sai ya tafi gidan Maryamu uwar Yohanna, wanda ake kuma kira Markus, inda mutane da yawa suka taru suna addu’a. ");
INSERT INTO hausa_vpl VALUES ("AC12_13","074_12_13","ACT","12","13","13","Bitrus ya ƙwanƙwasa ƙofar waje, sai wata mai aiki a gidan da ake kira Roda ta zo tă ji ko wane ne. ");
INSERT INTO hausa_vpl VALUES ("AC12_14","074_12_14","ACT","12","14","14","Da ta gane muryar Bitrus, ta cika da murna ta gudu ta koma ba tare da ta buɗe ƙofar ba, sai ta koma a guje ta ce da ƙarfi, “Ga Bitrus a bakin ƙofa!” ");
INSERT INTO hausa_vpl VALUES ("AC12_15","074_12_15","ACT","12","15","15","Sai suka ce mata, “Kina hauka.” Da ta nace cewa shi ne, sai suka ce, “To, lalle, mala’ikansa ne.” ");
INSERT INTO hausa_vpl VALUES ("AC12_16","074_12_16","ACT","12","16","16","Amma Bitrus ya yi ta ƙwanƙwasawa. Da suka buɗe ƙofar suka kuma gan shi, sai suka yi mamaki. ");
INSERT INTO hausa_vpl VALUES ("AC12_17","074_12_17","ACT","12","17","17","Bitrus ya yi musu alama da hannunsa su yi shiru sai ya bayyana yadda Ubangiji ya fitar da shi daga kurkuku. Ya ce, “Ku gaya wa Yaƙub da kuma ’yan’uwa game da wannan,” sa’an nan ya tashi ya tafi wani wuri. ");
INSERT INTO hausa_vpl VALUES ("AC12_18","074_12_18","ACT","12","18","18","Da safe, hargitsin da ya tashi tsakanin sojojin ba ƙarami ba ne, a kan abin da ya sami Bitrus. ");
INSERT INTO hausa_vpl VALUES ("AC12_19","074_12_19","ACT","12","19","19","Bayan Hiridus ya neme shi bai same shi ba, sai ya tuhumi masu gadin, ya kuma ba da umarni a kashe su. Sa’an nan Hiridus ya tashi daga Yahudiya ya tafi Kaisariya ya kuma yi ’yan kwanaki a can. ");
INSERT INTO hausa_vpl VALUES ("AC12_20","074_12_20","ACT","12","20","20","Yana da rashin jituwa da mutanen Taya da na Sidon; sai suka haɗa kai suka nemi ganawa da shi. Bayan suka sami goyon bayan Bilastus, amintaccen bawan sarki, sai suka nemi salama, domin sun dogara ga ƙasar sarkin don samun abincinsu. ");
INSERT INTO hausa_vpl VALUES ("AC12_21","074_12_21","ACT","12","21","21","A ranar da aka shirya Hiridus, sanye da kayan sarautarsa, ya zauna a gadon sarautarsa ya kuma ya wa mutanen jawabi. ");
INSERT INTO hausa_vpl VALUES ("AC12_22","074_12_22","ACT","12","22","22","Suka tā da murya suka ce, “Wannan muryar wani allah ne, ba ta mutum ba.” ");
INSERT INTO hausa_vpl VALUES ("AC12_23","074_12_23","ACT","12","23","23","Nan take, domin Hiridus bai yi wa Allah yabo ba, wani mala’ikan Ubangiji ya buge shi, tsutsotsi kuwa suka cinye shi ya kuma mutu. ");
INSERT INTO hausa_vpl VALUES ("AC12_24","074_12_24","ACT","12","24","24","Amma maganar Allah ta ci gaba da ƙaruwa ta kuma bazu. ");
INSERT INTO hausa_vpl VALUES ("AC12_25","074_12_25","ACT","12","25","25","Sa’ad da Barnabas da Shawulu suka kammala aikinsu, sai suka komo daga Urushalima, tare da Yohanna, wanda ake kira Markus. ");
INSERT INTO hausa_vpl VALUES ("AC13_1","074_13_1","ACT","13","1","1","A ikkilisiyar da take a Antiyok akwai waɗansu annabawa da malamai. Barnabas, Siman wanda ake kira Baƙi, Lusiyus mutumin Sairin, Manayen (wanda aka goya tare da Hiridus mai mulki), da kuma Shawulu. ");
INSERT INTO hausa_vpl VALUES ("AC13_2","074_13_2","ACT","13","2","2","Yayinda suna cikin sujada da azumi ga Ubangiji, Ruhu Mai Tsarki ya ce, “Ku keɓe mini Barnabas da Shawulu domin aikin da na kira su.” ");
INSERT INTO hausa_vpl VALUES ("AC13_3","074_13_3","ACT","13","3","3","Saboda haka bayan suka yi azumi da addu’a, sai suka ɗibiya musu hannuwansu a kansu suka sallame su. ");
INSERT INTO hausa_vpl VALUES ("AC13_4","074_13_4","ACT","13","4","4","Sai su biyu da Ruhu Mai Tsarki ya aika suka gangara zuwa Selusiya suka shiga jirgin ruwa daga can zuwa Saifurus. ");
INSERT INTO hausa_vpl VALUES ("AC13_5","074_13_5","ACT","13","5","5","Da suka isa Salamis, sai suka yi shelar maganar Allah a majami’un Yahudawa. Yohanna yana tare da su a matsayin mai taimakonsu. ");
INSERT INTO hausa_vpl VALUES ("AC13_6","074_13_6","ACT","13","6","6","Suka zaga dukan tsibirin har sai da suka kai Bafos. A can suka sadu da wani mutumin Yahuda mai sihiri, annabin ƙarya, mai suna Bar-Yesu, ");
INSERT INTO hausa_vpl VALUES ("AC13_7","074_13_7","ACT","13","7","7","wanda yake ma’aikacin muƙaddas Sergiyus Bulus ne. Muƙaddas ɗin kuwa mai azanci ne ƙwarai, ya sa aka kira Barnabas da Shawulu don yana so ya ji maganar Allah. ");
INSERT INTO hausa_vpl VALUES ("AC13_8","074_13_8","ACT","13","8","8","Amma Elimas mai sihirin nan (domin ma’anar sunansa ke nan) ya yi hamayya da maganarsu ya kuma yi ƙoƙari ya juyar da muƙaddas ɗin daga bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("AC13_9","074_13_9","ACT","13","9","9","Sai Shawulu, wanda kuma ake kira Bulus, cike da Ruhu Mai Tsarki, ya kafa wa Elimas ido ya ce, ");
INSERT INTO hausa_vpl VALUES ("AC13_10","074_13_10","ACT","13","10","10","“Kai ɗan Iblis ne abokin gāban dukan abin da yake daidai! Kana cike da kowane irin ruɗi da munafunci. Ba za ka daina karkata hanyoyin da suke daidai na Ubangiji ba? ");
INSERT INTO hausa_vpl VALUES ("AC13_11","074_13_11","ACT","13","11","11","Ga shi hannun Ubangiji yana gāba da kai. Za ka makance, kuma ba za ka ga rana ba har na wani lokaci.” Nan take, hazo da duhu suka sauko a kansa, ya yi ta lallubawa, yana neman wanda zai yi masa jagora. ");
INSERT INTO hausa_vpl VALUES ("AC13_12","074_13_12","ACT","13","12","12","Sa’ad da muƙaddas ɗin ya ga abin da ya faru, sai ya ba da gaskiya, gama ya yi mamaki a kan da koyarwa game Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AC13_13","074_13_13","ACT","13","13","13","Bulus da abokan tafiyarsa suka tashi daga Bafos a jirgin ruwa zuwa Ferga a Famfiliya inda Yohanna ya bar su ya koma Urushalima. ");
INSERT INTO hausa_vpl VALUES ("AC13_14","074_13_14","ACT","13","14","14","Daga Ferga kuwa suka ci gaba zuwa Antiyok na Fisidiya. A ranar Asabbaci sai suka shiga majami’a suka zauna. ");
INSERT INTO hausa_vpl VALUES ("AC13_15","074_13_15","ACT","13","15","15","Bayan an yi karatu daga cikin Doka, da kuma Annabawa, sai shugabannin majami’ar suka aika musu suka ce, “’Yan’uwa, in kuna da wani saƙon ƙarfafawa domin jama’a, sai ku yi.” ");
INSERT INTO hausa_vpl VALUES ("AC13_16","074_13_16","ACT","13","16","16","Yana miƙewa tsaye, sai Bulus ya yi musu alama da hannu ya ce, “Mutanen Isra’ila da kuma ku Al’ummai da kuke wa Allah sujada, ku saurare ni! ");
INSERT INTO hausa_vpl VALUES ("AC13_17","074_13_17","ACT","13","17","17","Allahn mutanen Isra’ila ya zaɓi kakanninmu; ya kuma sa mutanen suka yi bunkasa yayinda suke zama a ƙasar Masar, da iko mai girma ya fitar da su daga ƙasar, ");
INSERT INTO hausa_vpl VALUES ("AC13_18","074_13_18","ACT","13","18","18","ya kuma jure da halinsu har shekara arba’in a cikin hamada, ");
INSERT INTO hausa_vpl VALUES ("AC13_19","074_13_19","ACT","13","19","19","ya tumɓuke ƙasashe bakwai a Kan’ana ya kuma ba da ƙasarsu gādo ga mutanensa. ");
INSERT INTO hausa_vpl VALUES ("AC13_20","074_13_20","ACT","13","20","20","Dukan wannan ya ɗauki kusan shekaru 450. “Bayan wannan, Allah ya ba su alƙalai har zuwa zamanin annabi Sama’ila. ");
INSERT INTO hausa_vpl VALUES ("AC13_21","074_13_21","ACT","13","21","21","Sa’an nan mutanen suka nemi a ba su sarki, Allah kuwa ya ba su Shawulu ɗan Kish, na kabilar Benyamin, wanda ya yi mulki shekaru arba’in. ");
INSERT INTO hausa_vpl VALUES ("AC13_22","074_13_22","ACT","13","22","22","Bayan an kau da Shawulu, sai ya naɗa Dawuda ya zama sarkinsu. Ya kuma yi shaida game da shi cewa, ‘Na sami Dawuda ɗan Yesse, mutum ne da nake so a zuciyata; shi zai aikata dukan abin da nake so.’ ");
INSERT INTO hausa_vpl VALUES ("AC13_23","074_13_23","ACT","13","23","23","“Daga zuriyar mutumin nan ne Allah ya kawo wa Isra’ila Mai Ceto Yesu, kamar yadda ya yi alkawari. ");
INSERT INTO hausa_vpl VALUES ("AC13_24","074_13_24","ACT","13","24","24","Kafin zuwan Yesu, Yohanna ya yi wa’azin tuba da baftisma ga dukan mutanen Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("AC13_25","074_13_25","ACT","13","25","25","Yayinda Yohanna yake kammala aikinsa ya ce, ‘Wa kuke tsammani ni nake? Ba ni ne shi ba. A’a, amma yana zuwa bayana, wanda ko takalmansa ma ban isa in kunce ba.’ ");
INSERT INTO hausa_vpl VALUES ("AC13_26","074_13_26","ACT","13","26","26","“Ya ku ’yan’uwa, ’ya’yan Ibrahim, da ku kuma Al’ummai masu tsoron Allah, a gare mu ne fa aka aiko wannan saƙon ceto. ");
INSERT INTO hausa_vpl VALUES ("AC13_27","074_13_27","ACT","13","27","27","Mutanen Urushalima da masu mulkinsu ba su gane da Yesu ba, duk da haka cikin hukunta shi suka cika kalmomin annabawan da ake karantawa kowane Asabbaci. ");
INSERT INTO hausa_vpl VALUES ("AC13_28","074_13_28","ACT","13","28","28","Ko da yake ba su same shi da wani dalilin da ya kai ga hukuncin kisa ba, suka roƙi Bilatus yă sa a kashe shi. ");
INSERT INTO hausa_vpl VALUES ("AC13_29","074_13_29","ACT","13","29","29","Sa’ad da suka aikata duk abin da aka rubuta game da shi, sai suka saukar da shi daga itacen suka kuma sa shi a kabari. ");
INSERT INTO hausa_vpl VALUES ("AC13_30","074_13_30","ACT","13","30","30","Amma Allah ya tashe shi daga matattu, ");
INSERT INTO hausa_vpl VALUES ("AC13_31","074_13_31","ACT","13","31","31","kuma kwanaki da yawa waɗanda suka yi tafiya tare da shi daga Galili zuwa Urushalima suka gan shi. Su ne yanzu shaidu ga mutanenmu. ");
INSERT INTO hausa_vpl VALUES ("AC13_32","074_13_32","ACT","13","32","32","“Muna gaya muku labari mai daɗi cewa abin da Allah ya yi wa kakanninmu alkawari, ");
INSERT INTO hausa_vpl VALUES ("AC13_33","074_13_33","ACT","13","33","33","ya cika mana, mu zuriyarsu, ta wurin tā da Yesu daga matattu. Kamar yadda yake a rubuce a cikin Zabura ta biyu cewa, “ ‘Kai Ɗana ne, yau na zama Uba a gare ka.’ ");
INSERT INTO hausa_vpl VALUES ("AC13_34","074_13_34","ACT","13","34","34","Gaskiyar cewa Allah ya tā da shi daga matattu, a kan ba zai taɓa ruɓewa ba, an faɗe shi a cikin waɗannan kalmomi. “ ‘Zan ba ku tsarki da kuma tabbatattun albarkun da na yi wa Dawuda alkawari.’ ");
INSERT INTO hausa_vpl VALUES ("AC13_35","074_13_35","ACT","13","35","35","Haka kuma aka faɗa a wani wuri. “ ‘Ba za ka yarda Mai Tsarkinka ya ruɓa ba.’ ");
INSERT INTO hausa_vpl VALUES ("AC13_36","074_13_36","ACT","13","36","36","“Gama sa’ad da Dawuda ya gama hidimar nufin Allah a zamaninsa, sai ya yi barci; aka binne shi tare da kakanninsa jikinsa kuwa ya ruɓe. ");
INSERT INTO hausa_vpl VALUES ("AC13_37","074_13_37","ACT","13","37","37","Amma wanda Allah ya tā da daga matattu bai ruɓa ba. ");
INSERT INTO hausa_vpl VALUES ("AC13_38","074_13_38","ACT","13","38","38","“Saboda haka, ’yan’uwana, ina so ku san cewa ta wurin Yesu ana sanar muku da gafarar zunubi. ");
INSERT INTO hausa_vpl VALUES ("AC13_39","074_13_39","ACT","13","39","39","Ta wurinsa kowa da ya gaskata an kuɓutar da shi daga dukan abin da Dokar Musa ba tă iya kuɓutar ba. ");
INSERT INTO hausa_vpl VALUES ("AC13_40","074_13_40","ACT","13","40","40","Ku lura kada abubuwan da annabawa suka faɗa su faru muku. ");
INSERT INTO hausa_vpl VALUES ("AC13_41","074_13_41","ACT","13","41","41","“ ‘Ku duba, ku masu ba’a, ku yi mamaki, ku hallaka, gama zan yi wani abu a zamaninku da ba za ku taɓa gaskatawa ba ko da wani ya gaya muku.’” ");
INSERT INTO hausa_vpl VALUES ("AC13_42","074_13_42","ACT","13","42","42","Bulus da Barnabas suna fita daga majami’ar ke nan, sai mutane suka gayyace su su ƙara yin maganan nan a kan waɗannan abubuwa a ranar Asabbaci mai zuwa. ");
INSERT INTO hausa_vpl VALUES ("AC13_43","074_13_43","ACT","13","43","43","Da aka sallami jama’a, Yahudawa da yawa da kuma waɗanda suka tuba suka shiga Yahudanci masu ibada suka bi Bulus da Barnabas, waɗanda suka yi magana musu suka kuma ƙarfafa su su ci gaba a cikin alherin Allah. ");
INSERT INTO hausa_vpl VALUES ("AC13_44","074_13_44","ACT","13","44","44","A ranar Asabbaci na biye kusan dukan birnin suka taru don su ji maganar Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AC13_45","074_13_45","ACT","13","45","45","Sa’ad da Yahudawa suka ga taron mutanen, sai suka cika da kishi suka yi ta munanan maganganu a kan abin da Bulus yake faɗi. ");
INSERT INTO hausa_vpl VALUES ("AC13_46","074_13_46","ACT","13","46","46","Sai Bulus da Barnabas suka amsa musu gabagadi, suka ce, “Ya zama mana dole mu yi muku maganar Allah da farko. Da yake kun ƙi ta ba ku kuma ga kun cancanci rai madawwami ba, to, za mu juya ga Al’ummai. ");
INSERT INTO hausa_vpl VALUES ("AC13_47","074_13_47","ACT","13","47","47","Gama abin da Allah ya umarce mu ke nan cewa, “ ‘Na sa ka zama haske ga Al’ummai, don ka kawo cetona zuwa iyakokin duniya.’” ");
INSERT INTO hausa_vpl VALUES ("AC13_48","074_13_48","ACT","13","48","48","Sa’ad da Al’ummai suka ji haka, sai suka yi farin ciki suka ɗaukaka maganar Ubangiji; kuma duk waɗanda aka zaɓa don samun rai madawwami, suka gaskata. ");
INSERT INTO hausa_vpl VALUES ("AC13_49","074_13_49","ACT","13","49","49","Maganar Ubangiji kuwa ta bazu a dukan yankin. ");
INSERT INTO hausa_vpl VALUES ("AC13_50","074_13_50","ACT","13","50","50","Amma Yahudawa suka zuga waɗansu mata masu tsoron Allah masu martaba da kuma waɗansu maza masu matsayi a gari. Suka tā da tsanani ga Bulus da Barnabas, suka kore su daga yankinsu. ");
INSERT INTO hausa_vpl VALUES ("AC13_51","074_13_51","ACT","13","51","51","Saboda haka suka karkaɗe ƙurar ƙafafunsu don shaidar a kansu suka kuwa tafi Ikoniyum. ");
INSERT INTO hausa_vpl VALUES ("AC13_52","074_13_52","ACT","13","52","52","Masu bi kuwa suka cika da farin ciki da kuma Ruhu Mai Tsarki. ");
INSERT INTO hausa_vpl VALUES ("AC14_1","074_14_1","ACT","14","1","1","A Ikoniyum Bulus da Barnabas suka shiga majami’ar Yahudawa yadda suka saba. A can suka yi magana gabagadi har Yahudawa da Al’ummai masu yawa suka gaskata. ");
INSERT INTO hausa_vpl VALUES ("AC14_2","074_14_2","ACT","14","2","2","Amma Yahudawan da suka ƙi ba da gaskata, suka zuga Al’ummai suka sa ɓata tsakaninsu da ’yan’uwa. ");
INSERT INTO hausa_vpl VALUES ("AC14_3","074_14_3","ACT","14","3","3","Bulus da Barnabas kuwa suka daɗe sosai a can, suna magana gabagadi saboda Ubangiji, wanda kuwa ya tabbatar da saƙon alherinsa ta wurinsa su su aikata ayyuka da alamu masu banmamaki. ");
INSERT INTO hausa_vpl VALUES ("AC14_4","074_14_4","ACT","14","4","4","Mutanen birnin suka rarrabu, waɗansu suka goyi bayan Yahudawa, waɗansu kuma suka goyi bayan manzannin. ");
INSERT INTO hausa_vpl VALUES ("AC14_5","074_14_5","ACT","14","5","5","Yahudawa da Al’ummai tare da shugabanninsu suka ƙulla shawara a tsakaninsu, domin su wulaƙanta su su kuma jajjefe su da duwatsu. ");
INSERT INTO hausa_vpl VALUES ("AC14_6","074_14_6","ACT","14","6","6","Amma suka sami labari suka kuma gudu zuwa biranen Ikoniyum na Listira da Derbe da kuma ƙauyukan kewaye, ");
INSERT INTO hausa_vpl VALUES ("AC14_7","074_14_7","ACT","14","7","7","inda suka ci gaba da wa’azin labari mai daɗi. ");
INSERT INTO hausa_vpl VALUES ("AC14_8","074_14_8","ACT","14","8","8","A Listira kuwa akwai wani gurgu zaune a ƙafafunsa, wanda gurgu ne tun haihuwa, kuma bai taɓa tafiya ba. ");
INSERT INTO hausa_vpl VALUES ("AC14_9","074_14_9","ACT","14","9","9","Ya kasa kunne yayinda Bulus yake magana. Bulus kuma ya kafa masa ido, ya lura cewa yana da bangaskiyar da za tă warkar da shi ");
INSERT INTO hausa_vpl VALUES ("AC14_10","074_14_10","ACT","14","10","10","sai ya ɗaga murya ya ce, “Tashi ka tsaya kan ƙafafunka!” Da jin haka, sai mutumin ya yi wuf ya kuma fara tafiya. ");
INSERT INTO hausa_vpl VALUES ("AC14_11","074_14_11","ACT","14","11","11","Sa’ad da taron suka ga abin da Bulus ya yi, sai suka ihu da harshen Likayoniyawa, suna cewa, “Alloli sun sauka mana da siffar mutane!” ");
INSERT INTO hausa_vpl VALUES ("AC14_12","074_14_12","ACT","14","12","12","Sai suka ba wa Barnabas, sunan Zeyus, Bulus kuma suka kira Hermes domin shi ne shugaban magana. ");
INSERT INTO hausa_vpl VALUES ("AC14_13","074_14_13","ACT","14","13","13","Firist na Zeyus, wanda haikalinsa ke bayan birni, ya kawo bijimai da furanni a ƙofofin birni domin shi da taron mutanen sun so su miƙa musu hadayu. ");
INSERT INTO hausa_vpl VALUES ("AC14_14","074_14_14","ACT","14","14","14","Amma da manzannin nan Barnabas da Bulus suka ji haka, sai suka yayyage tufafinsu suka ruga cikin taron, suna ihu suna cewa, ");
INSERT INTO hausa_vpl VALUES ("AC14_15","074_14_15","ACT","14","15","15","“Ya ku mutane, don me kuke yin haka? Ai, mu ma mutane ne kawai, ’yan adam ne kamar ku. Mun kawo muku labari mai daɗi ne, muna gaya muku ku juya daga waɗannan abubuwa banza, ku juyo ga Allah mai rai, wanda ya yi sama da ƙasa da teku da kuma dukan abin da yake cikinsu. ");
INSERT INTO hausa_vpl VALUES ("AC14_16","074_14_16","ACT","14","16","16","A zamanin dā, ya bar dukan ƙasashe su yi yadda suka ga dama. ");
INSERT INTO hausa_vpl VALUES ("AC14_17","074_14_17","ACT","14","17","17","Duk da haka bai bar kansa babu shaida ba. Ya nuna alheri ta wurin ba ku ruwan sama da kuma amfanin gona a lokutansu; ya ba ku abinci mai yawa ya kuma cika zukatanku da farin ciki.” ");
INSERT INTO hausa_vpl VALUES ("AC14_18","074_14_18","ACT","14","18","18","Ko da waɗannan kalmomi ma, da ƙyar suka hana jama’an nan yin musu hadaya. ");
INSERT INTO hausa_vpl VALUES ("AC14_19","074_14_19","ACT","14","19","19","Sai waɗansu Yahudawa suka zo daga Antiyok da Ikoniyum suka sha kan taron. Suka jajjefi Bulus da duwatsu suka kuma ja shi bayan birni, suna tsammani ya mutu. ");
INSERT INTO hausa_vpl VALUES ("AC14_20","074_14_20","ACT","14","20","20","Amma bayan da almajiran suka taru kewaye da shi, sai ya tashi ya koma cikin birni. Kashegari shi da Barnabas suka tashi zuwa Derbe. ");
INSERT INTO hausa_vpl VALUES ("AC14_21","074_14_21","ACT","14","21","21","Suka yi wa’azin Labari mai daɗi a wannan birni, suka kuma sami almajirai da yawa. Sai suka koma Listira, Ikoniyum da kuma Antiyok, ");
INSERT INTO hausa_vpl VALUES ("AC14_22","074_14_22","ACT","14","22","22","suna gina almajirai suna kuma ƙarfafa su su tsaya da gaske cikin bangaskiya. Suka ce, “Sai da shan wahaloli masu yawa za mu shiga mulkin Allah.” ");
INSERT INTO hausa_vpl VALUES ("AC14_23","074_14_23","ACT","14","23","23","Bulus da Barnabas suka naɗa musu dattawa a kowace ikkilisiya, tare da addu’a da azumi, suka miƙa su ga Ubangiji, wanda suka dogara da shi. ");
INSERT INTO hausa_vpl VALUES ("AC14_24","074_14_24","ACT","14","24","24","Bayan sun bi ta Fisidiya, sai suka zo cikin Famfiliya, ");
INSERT INTO hausa_vpl VALUES ("AC14_25","074_14_25","ACT","14","25","25","kuma sa’ad da suka yi wa’azi a Ferga, sai suka gangara zuwa Attaliya. ");
INSERT INTO hausa_vpl VALUES ("AC14_26","074_14_26","ACT","14","26","26","Daga Attaliya kuma suka shiga jirgin ruwa suka koma Antiyok, inda dā aka danƙa su ga alherin Allah saboda aikin da suka kammala yanzu. ");
INSERT INTO hausa_vpl VALUES ("AC14_27","074_14_27","ACT","14","27","27","Da isarsu a can, sai suka tara ikkilisiya wuri ɗaya suka ba da rahoton duk abin da Allah ya aikata ta wurinsu da kuma yadda ya buɗe ƙofar bangaskiya domin Al’ummai. ");
INSERT INTO hausa_vpl VALUES ("AC14_28","074_14_28","ACT","14","28","28","Suka kuma jima a can tare da almajirai. ");
INSERT INTO hausa_vpl VALUES ("AC15_1","074_15_1","ACT","15","1","1","Waɗansu mutane suka gangara daga Yahudiya zuwa Antiyok suna kuma koya wa ’yan’uwa cewa, “Sai ko an yi muku kaciya bisa ga al’ada da Musa ya koyar, in ba haka ba, ba za ku sami ceto ba.” ");
INSERT INTO hausa_vpl VALUES ("AC15_2","074_15_2","ACT","15","2","2","Wannan ya kai Bulus da Barnabas suka shiga babban gardama da muhawwara da su. Saboda haka aka naɗa Bulus da Barnabas tare da waɗansu masu bi, su haura zuwa Urushalima don su ga manzanni da dattawa a kan wannan magana. ");
INSERT INTO hausa_vpl VALUES ("AC15_3","074_15_3","ACT","15","3","3","Ikkilisiya ta raka su suka tafi, yayinda suke ratsawa ta Funisiya da Samariya, suka ba da labari yadda Al’ummai suka tuba. Wannan labarin ya sa dukan ’yan’uwa suka yi murna ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("AC15_4","074_15_4","ACT","15","4","4","Sa’ad da suka isa Urushalima, sai ikkilisiya da manzanni da kuma dattawa suka marabce su, sai suka ba su rahoton dukan abin da Allah ya aikata ta wurinsu. ");
INSERT INTO hausa_vpl VALUES ("AC15_5","074_15_5","ACT","15","5","5","Sai waɗansu daga cikin masu bin da suke na ƙungiyar Farisiyawa suka miƙe tsaye suka ce, “Dole ne a yi wa Al’ummai kaciya a kuma bukace su su yi biyayya da dokokin Musa.” ");
INSERT INTO hausa_vpl VALUES ("AC15_6","074_15_6","ACT","15","6","6","Sai manzanni da dattawa suka taru don su duba maganar. ");
INSERT INTO hausa_vpl VALUES ("AC15_7","074_15_7","ACT","15","7","7","Bayan aka yi muhawwara da sosai, sai Bitrus ya miƙe tsaye ya yi musu jawabi ya ce, “’Yan’uwa, kun san cewa a kwanakin baya Allah ya yi zaɓe a cikinku don Al’ummai su ji daga leɓunana saƙon bishara su kuma gaskata. ");
INSERT INTO hausa_vpl VALUES ("AC15_8","074_15_8","ACT","15","8","8","Allah, wanda ya san zuciya, ya nuna cewa ya karɓe su ta wurin ba su Ruhu Mai Tsarki, kamar yadda ya ba mu. ");
INSERT INTO hausa_vpl VALUES ("AC15_9","074_15_9","ACT","15","9","9","Bai nuna bambanci tsakaninmu da su ba, gama ya tsarkake zukatansu ta wurin bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("AC15_10","074_15_10","ACT","15","10","10","To, fa, don me kuke ƙoƙari ku gwada Allah ta wurin ɗora wa almajiran nan kayan da mu ko kakanninmu ba mu iya ɗauka ba? ");
INSERT INTO hausa_vpl VALUES ("AC15_11","074_15_11","ACT","15","11","11","A’a! Mun gaskata cewa ta wurin alherin Ubangiji Yesu ne muka sami ceto, kamar yadda su ma suka samu.” ");
INSERT INTO hausa_vpl VALUES ("AC15_12","074_15_12","ACT","15","12","12","Sai duk taron suka yi tsit yayinda suke sauraron Barnabas da Bulus suna ba da labari game da ayyuka da kuma abubuwan banmamakin da Allah ya yi a cikin Al’ummai ta wurinsu. ");
INSERT INTO hausa_vpl VALUES ("AC15_13","074_15_13","ACT","15","13","13","Da suka gama, sai Yaƙub ya yi magana ya ce, “’Yan’uwa, ku saurare ni. ");
INSERT INTO hausa_vpl VALUES ("AC15_14","074_15_14","ACT","15","14","14","Siman ya bayyana mana yadda Allah da farko ya nuna damuwarsa ta wurin ɗaukan mutane daga cikin Al’ummai su zama nasa. ");
INSERT INTO hausa_vpl VALUES ("AC15_15","074_15_15","ACT","15","15","15","Kalmomin annabawa sun yi daidai da wannan, kamar yadda yake a rubuce cewa, ");
INSERT INTO hausa_vpl VALUES ("AC15_16","074_15_16","ACT","15","16","16","“ ‘Bayan wannan zan koma in kuma sāke gina tentin Dawuda da ya rushe. Kufansa zan sāke gina, in kuma mai da shi, ");
INSERT INTO hausa_vpl VALUES ("AC15_17","074_15_17","ACT","15","17","17","don ragowar mutane su nemi Ubangiji, kuma duk Al’umman da suke kira bisa sunana, in ji Ubangiji, wanda yake yin waɗannan abubuwa’ ");
INSERT INTO hausa_vpl VALUES ("AC15_18","074_15_18","ACT","15","18","18","da aka sani tun zamanai. ");
INSERT INTO hausa_vpl VALUES ("AC15_19","074_15_19","ACT","15","19","19","“Saboda haka, a ganina, kada mu matsa wa Al’ummai waɗanda suke juyowa ga Allah. ");
INSERT INTO hausa_vpl VALUES ("AC15_20","074_15_20","ACT","15","20","20","A maimakon haka, ya kamata mu rubuta musu cewa, su guji abincin da alloli suka ƙazantar, da fasikanci, da naman dabbar da aka murɗe da kuma jini. ");
INSERT INTO hausa_vpl VALUES ("AC15_21","074_15_21","ACT","15","21","21","Gama Musa ya yi wa’azi a kowace birni tun zamanin dā, ana kuma karanta shi a majami’u kowane Asabbaci.” ");
INSERT INTO hausa_vpl VALUES ("AC15_22","074_15_22","ACT","15","22","22","Sai manzanni da dattawa, tare da dukan ikkilisiya, suka yanke shawara su zaɓi waɗansu daga cikin mutanensu su kuma aike su zuwa Antiyok tare da Bulus da Barnabas. Sai suka zaɓi Yahuda (wanda ake kira Barsabbas) da kuma Sila, mutum biyu da suke shugabanni cikin ’yan’uwa. ");
INSERT INTO hausa_vpl VALUES ("AC15_23","074_15_23","ACT","15","23","23","Tare da su suka aika da wannan wasiƙa. Daga manzanni da dattawa, ’yan’uwanku. Zuwa ga Al’ummai masu bi a Antiyok, Suriya da Silisiya. Gaisuwa. ");
INSERT INTO hausa_vpl VALUES ("AC15_24","074_15_24","ACT","15","24","24","Mun ji cewa, waɗansu da sun fita daga cikinmu ba tare da izininmu ba suka kuma dame ku, suna tā da hankalinku ta wurin abin da suka ce. ");
INSERT INTO hausa_vpl VALUES ("AC15_25","074_15_25","ACT","15","25","25","Saboda haka dukanmu mun yarda mu zaɓi waɗansu mutane mu kuma aike su wurinku tare da ƙaunatattun abokanmu Barnabas da Bulus ");
INSERT INTO hausa_vpl VALUES ("AC15_26","074_15_26","ACT","15","26","26","mutanen da suka sa rayukansu cikin hatsari saboda sunan Ubangijinmu Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("AC15_27","074_15_27","ACT","15","27","27","Saboda haka muna aika Yahuda da Sila don su tabbatar muku da baki abin da muka rubuta. ");
INSERT INTO hausa_vpl VALUES ("AC15_28","074_15_28","ACT","15","28","28","Ya gamshe Ruhu Mai Tsarki da mu ma kada a ɗora muku nauyi fiye da na waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("AC15_29","074_15_29","ACT","15","29","29","Ku guji abincin da aka yi wa alloli hadaya, da jini, da naman dabbar da aka murɗe da kuma fasikanci. Za ku kyauta in kun kiyaye waɗannan abubuwa. Ku huta lafiya. ");
INSERT INTO hausa_vpl VALUES ("AC15_30","074_15_30","ACT","15","30","30","Aka sallami mutanen sai suka gangara zuwa Antiyok, inda suka tara ikkilisiya wuri ɗaya suka ba da wasiƙar. ");
INSERT INTO hausa_vpl VALUES ("AC15_31","074_15_31","ACT","15","31","31","Mutanen suka karantata suka kuma yi farin ciki saboda saƙonta mai ƙarfafawa. ");
INSERT INTO hausa_vpl VALUES ("AC15_32","074_15_32","ACT","15","32","32","Yahuda da Sila, waɗanda su kansu annabawa ne, suka yi magana sosai don su gina su kuma ƙarfafa ’yan’uwa. ");
INSERT INTO hausa_vpl VALUES ("AC15_33","074_15_33","ACT","15","33","33","Bayan suka yi ’yan kwanaki a can, sai ’yan’uwa suka sallame su da albarkar salama su dawo wurin waɗanda suka aike su. ");
INSERT INTO hausa_vpl VALUES ("AC15_35","074_15_35","ACT","15","35","35","Amma Bulus da Barnabas kuwa suka dakata a Antiyok, inda su da waɗansu da yawa suka yi koyarwa suka kuma yi wa’azin maganar Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AC15_36","074_15_36","ACT","15","36","36","Bayan ’yan kwanaki sai Bulus ya ce wa Barnabas, “Mu koma mu ziyarci ’yan’uwa a duk garuruwan da muka yi wa’azin bisharar Ubangiji mu ga yadda suke.” ");
INSERT INTO hausa_vpl VALUES ("AC15_37","074_15_37","ACT","15","37","37","Barnabas ya so Yohanna, wanda ake kira Markus ya tafi tare da su, ");
INSERT INTO hausa_vpl VALUES ("AC15_38","074_15_38","ACT","15","38","38","amma Bulus bai ga ya kyautu ya tafi da shi ba, domin ya yashe su a Famfiliya bai kuwa ci gaba tare da su a aikin ba. ");
INSERT INTO hausa_vpl VALUES ("AC15_39","074_15_39","ACT","15","39","39","Suka sami saɓanin ra’ayi tsakaninsu har suka rabu. Barnabas ya ɗauki Markus suka shiga jirgin ruwa zuwa Saifurus, ");
INSERT INTO hausa_vpl VALUES ("AC15_40","074_15_40","ACT","15","40","40","amma Bulus ya zaɓi Sila suka kuwa tashi, bayan ’yan’uwa suka danƙa su ga alherin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AC15_41","074_15_41","ACT","15","41","41","Ya ratsa ta Suriya da Silisiya, yana ƙarfafa ikkilisiyoyi. ");
INSERT INTO hausa_vpl VALUES ("AC16_1","074_16_1","ACT","16","1","1","Bulus ya kai Derbe sa’an nan kuma zuwa Listira, inda wani almajiri mai suna Timoti yake da zama, wanda mahaifiyarsa mutuniyar Yahuda ce kuma mai bi ce, amma mahaifinsa mutumin Hellenawa ne. ");
INSERT INTO hausa_vpl VALUES ("AC16_2","074_16_2","ACT","16","2","2","’Yan’uwa a Listira da Ikoniyum sun yi magana mai kyau ƙwarai a kansa. ");
INSERT INTO hausa_vpl VALUES ("AC16_3","074_16_3","ACT","16","3","3","Bulus ya so ya ɗauke shi a tafiyar, saboda haka ya yi masa kaciya, domin Yahudawan da suke da zama a wurin, don duk sun san cewa mahaifinsa mutumin Hellenawa ne. ");
INSERT INTO hausa_vpl VALUES ("AC16_4","074_16_4","ACT","16","4","4","Yayinda suke tafiya daga gari zuwa gari, suka dinga ba da shawarwarin da manzanni da dattawa a Urushalima suka zartar domin mutane su kiyaye. ");
INSERT INTO hausa_vpl VALUES ("AC16_5","074_16_5","ACT","16","5","5","Saboda haka ikkilisiyoyi suka ginu cikin bangaskiya suka kuma yi girma suka yi ta ƙaruwa kowace rana. ");
INSERT INTO hausa_vpl VALUES ("AC16_6","074_16_6","ACT","16","6","6","Bulus da abokan tafiyarsa suka zazzaga dukan yankin Firjiya da Galatiya, don Ruhu Mai Tsarki ya hana su yin wa’azi a lardin Asiya. ");
INSERT INTO hausa_vpl VALUES ("AC16_7","074_16_7","ACT","16","7","7","Da suka isa kan iyakar Misiya, suka yi ƙoƙari su shiga Bitiniya, amma Ruhun Yesu bai yarda musu ba. ");
INSERT INTO hausa_vpl VALUES ("AC16_8","074_16_8","ACT","16","8","8","Saboda haka suka ratsa Misiya suka zo Toruwas. ");
INSERT INTO hausa_vpl VALUES ("AC16_9","074_16_9","ACT","16","9","9","Da dare Bulus ya ga wahayin wani mutumin Makidoniya yana tsaye yana roƙonsa cewa, “Ka zo Makidoniya ka taimake mu.” ");
INSERT INTO hausa_vpl VALUES ("AC16_10","074_16_10","ACT","16","10","10","Bayan Bulus ya ga wahayin, muka shirya nan take mu tashi zuwa Makidoniya, mun tabbata cewa, Allah ya kira mu mu yi musu wa’azin bishara. ");
INSERT INTO hausa_vpl VALUES ("AC16_11","074_16_11","ACT","16","11","11","Daga Toruwas muka tashi zuwa teku muka kuma shiga jirgin ruwa muka miƙe kai tsaye zuwa Samotiras, kashegari kuma muka nufi Neyafolis. ");
INSERT INTO hausa_vpl VALUES ("AC16_12","074_16_12","ACT","16","12","12","Daga can muka tafi Filibbi, wata babbar alkaryar Roma wadda kuma take babban birni a gundumar Makidoniya. Muka zauna a can kwanaki masu yawa. ");
INSERT INTO hausa_vpl VALUES ("AC16_13","074_16_13","ACT","16","13","13","A Asabbaci, muka fita ƙofar birnin zuwa bakin kogi, inda muke tsammani za mu sami wurin yin addu’a. Muka zauna muka fara yin wa matan da suka taru a can magana. ");
INSERT INTO hausa_vpl VALUES ("AC16_14","074_16_14","ACT","16","14","14","Ɗaya daga cikin waɗanda suka saurare mu mace ce mai suna Lidiya, mai sayar da yadunan jan garura masu tsada daga birnin Tiyatira, mai yi wa Allah sujada. Ubangiji ya buɗe zuciyarta har ta karɓi saƙon Bulus. ");
INSERT INTO hausa_vpl VALUES ("AC16_15","074_16_15","ACT","16","15","15","Da aka yi mata baftisma tare da iyalin gidanta, sai ta gayyace mu zuwa gidanta. Ta ce, “In kun amince ni mai bi ce cikin Ubangiji, sai ku zo ku sauka a gidana.” Sai ta kuwa rinjaye mu. ");
INSERT INTO hausa_vpl VALUES ("AC16_16","074_16_16","ACT","16","16","16","Wata rana muna tafiya zuwa wurin yin addu’a, sai muka sadu da wata baranya mai ruhun aljani mai duba. Takan samo wa mutanenta kuɗi da yawa, duban da take yi. ");
INSERT INTO hausa_vpl VALUES ("AC16_17","074_16_17","ACT","16","17","17","Wannan yarinya kuwa ta bi Bulus da kuma sauranmu, tana ihu tana cewa, “Waɗannan mutane bayin Allah Mafi Ɗaukaka ne, suna sanar da ku hanyar ceto.” ");
INSERT INTO hausa_vpl VALUES ("AC16_18","074_16_18","ACT","16","18","18","Ta yi ta faɗin haka har kwanaki masu yawa. A ƙarshe Bulus ya damu ƙwarai sai ya juya ya ce wa aljanin, “A cikin sunan Yesu Kiristi na umarce ka, ka rabu da ita!” Nan take aljanin ya rabu da ita. ");
INSERT INTO hausa_vpl VALUES ("AC16_19","074_16_19","ACT","16","19","19","Da iyayengijin baranyar suka ga hanyar samun kuɗinsu ta toshe, sai suka kama Bulus da Sila suka ja su zuwa cikin kasuwa don su fuskanci hukuma. ");
INSERT INTO hausa_vpl VALUES ("AC16_20","074_16_20","ACT","16","20","20","Sai suka kawo su a gaban alƙalai suka ce, “Waɗannan Yahudawa ne, suna kuma birkitar mana da gari, ");
INSERT INTO hausa_vpl VALUES ("AC16_21","074_16_21","ACT","16","21","21","ta wurin koyar da al’adun da ba daidai ba ne mu Romawa mu karɓa ko mu aikata.” ");
INSERT INTO hausa_vpl VALUES ("AC16_22","074_16_22","ACT","16","22","22","Sai taron suka fāɗa wa Bulus da Sila gaba ɗaya, alƙalan kuwa suka yi umarni a tuɓe su a kuma yi musu dūka. ");
INSERT INTO hausa_vpl VALUES ("AC16_23","074_16_23","ACT","16","23","23","Bayan an yi musu bulala sosai, sai aka jefa su cikin kurkuku, aka umarci mai gadin kurkukun yă tsare su da kyau. ");
INSERT INTO hausa_vpl VALUES ("AC16_24","074_16_24","ACT","16","24","24","Da karɓan irin umarnan nan, sai ya sa su can cikin ɗakin kurkuku na ciki-ciki, kuma ya ɗaura ƙafafunsu a turu. ");
INSERT INTO hausa_vpl VALUES ("AC16_25","074_16_25","ACT","16","25","25","Wajen tsakar dare Bulus da Sila suna addu’a suna rera waƙoƙi ga Allah, sauran ’yan kurkuku kuwa suna sauraronsu. ");
INSERT INTO hausa_vpl VALUES ("AC16_26","074_16_26","ACT","16","26","26","Ba zato ba tsammani sai aka yi wata babbar girgizar ƙasa har tushen ginin kurkukun ya jijjiga. Nan da nan sai duk ƙofofin kurkukun suka bubbuɗe, sarƙoƙin kowa kuma suka ɓaɓɓalle. ");
INSERT INTO hausa_vpl VALUES ("AC16_27","074_16_27","ACT","16","27","27","Mai gadin kurkukun ya farka daga barci, sa’ad da ya ga ƙofofin kurkukun a buɗe, sai ya zāre takobinsa yana shirin kashe kansa domin ya ɗauka ’yan kurkukun sun gudu. ");
INSERT INTO hausa_vpl VALUES ("AC16_28","074_16_28","ACT","16","28","28","Amma Bulus ya yi ihu ya ce, “Kada ka yi wa kanka lahani! Dukanmu muna nan!” ");
INSERT INTO hausa_vpl VALUES ("AC16_29","074_16_29","ACT","16","29","29","Mai gadin kurkukun ya kira a kawo fitilu, ya ruga ciki ya fāɗi yana rawan jiki a gaban Bulus da Sila. ");
INSERT INTO hausa_vpl VALUES ("AC16_30","074_16_30","ACT","16","30","30","Sai ya fito da su waje ya kuma tambaye su ya ce, “Ranku yă daɗe, me zan yi domin in sami ceto?” ");
INSERT INTO hausa_vpl VALUES ("AC16_31","074_16_31","ACT","16","31","31","Suka amsa suka ce, “Ka gaskata da Ubangiji Yesu, za ka sami ceto, kai da iyalinka.” ");
INSERT INTO hausa_vpl VALUES ("AC16_32","074_16_32","ACT","16","32","32","Sa’an nan suka yi masa maganar Ubangiji shi da kuma dukan sauran da suke a gidansa. ");
INSERT INTO hausa_vpl VALUES ("AC16_33","074_16_33","ACT","16","33","33","A wannan sa’a na daren, mai gadin kurkukun ya ɗauke su ya wanke musu raunukansu; nan take aka yi masa baftisma da dukan iyalinsa. ");
INSERT INTO hausa_vpl VALUES ("AC16_34","074_16_34","ACT","16","34","34","Sai mai gadin kurkukun ya kawo su cikin gidansa ya ba su abinci; ya kuwa cika da murna don yă gaskata da Allah, shi da dukan iyalinsa. ");
INSERT INTO hausa_vpl VALUES ("AC16_35","074_16_35","ACT","16","35","35","Da gari ya waye, sai alƙalan suka aika ma’aikatansu wajen mai gadin kurkukun da umarni cewa, “Ka saki mutanen nan.” ");
INSERT INTO hausa_vpl VALUES ("AC16_36","074_16_36","ACT","16","36","36","Sai mai gadin kurkukun ya gaya wa Bulus cewa, “Alƙalai sun ba da umarni a sake ku kai da Sila. Yanzu sai ku tafi. Ku sauka lafiya.” ");
INSERT INTO hausa_vpl VALUES ("AC16_37","074_16_37","ACT","16","37","37","Amma Bulus ya ce wa ma’aikatan, “Sun yi mana dūka a fili ba tare da shari’a ba, ko da yake mu ’yan ƙasar Roma ne, suka kuma jefa mu cikin kurkuku. Yanzu suna so su fitar da mu a ɓoye? A’a! Sai dai su zo da kansu su rako mu waje.” ");
INSERT INTO hausa_vpl VALUES ("AC16_38","074_16_38","ACT","16","38","38","Sai ma’aikatan suka faɗa wa alƙalan wannan, da suka ji cewa Bulus da Sila Romawa ne, sai suka ji tsoro. ");
INSERT INTO hausa_vpl VALUES ("AC16_39","074_16_39","ACT","16","39","39","Sai suka zo don su roƙe su, suka yi musu rakiya daga kurkukun, suna roƙonsu su bar birnin. ");
INSERT INTO hausa_vpl VALUES ("AC16_40","074_16_40","ACT","16","40","40","Bayan Bulus da Sila suka fita daga kurkukun, sai suka tafi gidan Lidiya, inda suka sadu da ’yan’uwa suka kuma ƙarfafa su. Sa’an nan suka tafi. ");
INSERT INTO hausa_vpl VALUES ("AC17_1","074_17_1","ACT","17","1","1","Da suka bi ta Amfifolis da Afolloniya, sai suka isa Tessalonika, inda akwai majami’ar Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("AC17_2","074_17_2","ACT","17","2","2","Kamar yadda ya saba, Bulus ya shiga majami’ar, ranakun Asabbaci uku ya yi ta yin muhawwara da su daga cikin Nassosi, ");
INSERT INTO hausa_vpl VALUES ("AC17_3","074_17_3","ACT","17","3","3","yana musu bayani da tabbatarwa cewa dole Kiristi ya sha wahala ya kuma tashi daga matattu. Ya kuma ce, “Wannan Yesu da nake sanar muku shi ne Kiristi.” ");
INSERT INTO hausa_vpl VALUES ("AC17_4","074_17_4","ACT","17","4","4","Waɗansu Yahudawa suka amince suka kuma bi Bulus da Sila, haka ma Hellenawa da yawa masu tsoron Allah da kuma manyan mata ba kaɗan ba. ");
INSERT INTO hausa_vpl VALUES ("AC17_5","074_17_5","ACT","17","5","5","Amma Yahudawa suka yi kishi; saboda haka suka tattara ’yan iska daga kasuwa, suka shirya wata ƙungiya, suka tā da tarzoma a birni. Suka ruga zuwa gidan Yason suna neman Bulus da Sila don su kawo su a gaban taron. ");
INSERT INTO hausa_vpl VALUES ("AC17_6","074_17_6","ACT","17","6","6","Amma da ba su same su ba, sai suka ja Yason da waɗansu ’yan’uwa zuwa gaban mahukuntan birnin, suna ihu suna cewa, “Waɗannan mutanen da suke tā da fitina ko’ina a duniya sun iso nan, ");
INSERT INTO hausa_vpl VALUES ("AC17_7","074_17_7","ACT","17","7","7","Yason kuwa ya karɓe su a gidansa. Dukansu suna karya dokokin Kaisar, suna cewa akwai wani sarki, wanda ake kira Yesu.” ");
INSERT INTO hausa_vpl VALUES ("AC17_8","074_17_8","ACT","17","8","8","Da suka ji haka, sai hankalin taron da na mahukuntan birnin ya tashi. ");
INSERT INTO hausa_vpl VALUES ("AC17_9","074_17_9","ACT","17","9","9","Sai suka sa Yason da sauran su biya kuɗin saki sa’an nan suka sallame su. ");
INSERT INTO hausa_vpl VALUES ("AC17_10","074_17_10","ACT","17","10","10","Da dare ya yi, sai ’yan’uwa suka sallami Bulus da Sila su tafi Bereya. Da suka isa can, sai suka shiga majami’ar Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("AC17_11","074_17_11","ACT","17","11","11","Bereyawa kuwa sun fi Tessalonikawa hankali, gama sun karɓi saƙon da marmari ƙwarai, suka kuma yi ta yin bincike Nassosi kowace rana su ga ko abin da Bulus ya faɗa gaskiya ne. ");
INSERT INTO hausa_vpl VALUES ("AC17_12","074_17_12","ACT","17","12","12","Yahudawa da yawa suka gaskata, haka ma waɗansu manyan matan Hellenawa da kuma mazan Hellenawa da yawa. ");
INSERT INTO hausa_vpl VALUES ("AC17_13","074_17_13","ACT","17","13","13","Da Yahudawan da suke a Tessalonika suka ji cewa Bulus yana wa’azin maganar Allah a Bereya, sai suka je can ma, suna zuga taro suna kuma tā da hankalinsu. ");
INSERT INTO hausa_vpl VALUES ("AC17_14","074_17_14","ACT","17","14","14","Nan da nan ’yan’uwa suka sa Bulus yă tafi bakin teku, amma Sila da Timoti suka dakata a Bereya. ");
INSERT INTO hausa_vpl VALUES ("AC17_15","074_17_15","ACT","17","15","15","Mutanen da suka raka Bulus kuwa suka kawo shi Atens sa’an nan suka dawo da umarnai wa Sila da Timoti cewa su zo wurinsa da gaggawa. ");
INSERT INTO hausa_vpl VALUES ("AC17_16","074_17_16","ACT","17","16","16","Yayinda Bulus yake jiransu a Atens, ya damu ƙwarai da ya ga birnin cike da gumaka. ");
INSERT INTO hausa_vpl VALUES ("AC17_17","074_17_17","ACT","17","17","17","Saboda haka ya yi ta muhawwara a majami’a da Yahudawa da kuma Hellenawa masu tsoron Allah, haka kuma da waɗanda yake tararwa a bakin kasuwa. ");
INSERT INTO hausa_vpl VALUES ("AC17_18","074_17_18","ACT","17","18","18","Wata ƙungiyar Afikuriya da kuma masu bin ussan ilimin Sitoyik suka fara gardama da shi. Waɗansunsu suka ce, “Mene ne mai surutun nan yake ƙoƙarin faɗi?” Waɗansu suka ce, “Kamar yana wa’azin baƙin alloli ne.” Sun faɗa haka ne domin Bulus yana wa’azin labari mai daɗi game da Yesu da kuma tashin matattu. ");
INSERT INTO hausa_vpl VALUES ("AC17_19","074_17_19","ACT","17","19","19","Sai suka ɗauke shi suka kawo shi wurin taron Areyofagus, inda suka ce masa, “Ko za mu san mene ne sabon koyarwan nan ya ƙunsa da kake yi? ");
INSERT INTO hausa_vpl VALUES ("AC17_20","074_17_20","ACT","17","20","20","Kana kawo mana ra’ayoyin da suke baƙo a gare mu, kuma muna so mu san mene ne suke nufi.” ");
INSERT INTO hausa_vpl VALUES ("AC17_21","074_17_21","ACT","17","21","21","(Duk Atenawa da baƙin da suke zama a can suna zaman kashe wando ne kawai kuma ba abin da suke yi sai dai taɗi da kuma jin sababbin ra’ayoyi.) ");
INSERT INTO hausa_vpl VALUES ("AC17_22","074_17_22","ACT","17","22","22","Sai Bulus ya miƙe tsaye a tsakiyar taron Areyofagus ya ce, “Ya ku mutanen Atens! Na dai lura cewa ta kowace hanya ku masu addini ne ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("AC17_23","074_17_23","ACT","17","23","23","Gama sa’ad da nake zagawa, na lura da kyau da abubuwan da kuke bauta wa, har ma na tarar da wani bagade da wannan rubutu, Ga Allahn da ba a sani ba. To, abin nan da kuke yi wa sujada a matsayin abin da ba ku sani nan ba shi ne zan sanar da ku. ");
INSERT INTO hausa_vpl VALUES ("AC17_24","074_17_24","ACT","17","24","24","“Allahn da ya halicci duniya da kome da yake cikinta shi ne Ubangijin sama da ƙasa, ba ya kuma zama a haikalin da aka gina da hannuwa. ");
INSERT INTO hausa_vpl VALUES ("AC17_25","074_17_25","ACT","17","25","25","Ba a kuma yin masa hidima da hannun mutum, sai ka ce mai bukatan wani abu, domin shi kansa ne ke ba wa dukan mutane rai da numfashi da kuma kome. ");
INSERT INTO hausa_vpl VALUES ("AC17_26","074_17_26","ACT","17","26","26","Daga mutum ɗaya, ya halicci kowace al’ummar mutane, don su zauna a duk duniya; shi ne kuma ya ƙaddara lokuta bisa ga tsarinsu da kuma inda za su kasance. ");
INSERT INTO hausa_vpl VALUES ("AC17_27","074_17_27","ACT","17","27","27","Allah ya yi wannan domin mutane su neme shi mai yiwuwa kuma su lalluba su same shi, ko da yake ba shi da nisa daga kowannenmu. ");
INSERT INTO hausa_vpl VALUES ("AC17_28","074_17_28","ACT","17","28","28","‘Gama a cikinsa ne muke rayuwa muke motsi muka kuma kasance.’ Yadda waɗansu mawaƙanku suka ce, ‘Mu zuriyarsa ce.’ ");
INSERT INTO hausa_vpl VALUES ("AC17_29","074_17_29","ACT","17","29","29","“Saboda haka da yake mu zuriyar Allah ce, kada mu yi tsammani cewa kamannin Allah yana kama da zinariya ko azurfa ko dutse, siffar da mutum ya ƙago ta wurin dabararsa. ");
INSERT INTO hausa_vpl VALUES ("AC17_30","074_17_30","ACT","17","30","30","A dā Allah ya kawar da Allah ya kawar da kai ga zamanin jahilci, amma yanzu ya umarci dukan mutane a ko’ina su tuba. ");
INSERT INTO hausa_vpl VALUES ("AC17_31","074_17_31","ACT","17","31","31","Gama ya sa ranar da zai yi wa duniya shari’a da adalci ta wurin mutumin da ya naɗa. Ya riga ya ba da tabbacin wannan ga dukan mutane ta wurin tā da shi daga matattu.” ");
INSERT INTO hausa_vpl VALUES ("AC17_32","074_17_32","ACT","17","32","32","Sa’ad da suka ji maganar tashin matattu, waɗansunsu suka yi tsaki, amma waɗansu suka ce, “Muna so mu ƙara jin ka a kan wannan batu.” ");
INSERT INTO hausa_vpl VALUES ("AC17_33","074_17_33","ACT","17","33","33","Da wannan, Bulus ya bar Majalisar. ");
INSERT INTO hausa_vpl VALUES ("AC17_34","074_17_34","ACT","17","34","34","Waɗansu mutane kima suka zama mabiyan Bulus suka kuwa gaskata. A cikinsu kuwa akwai Diyonasiyus ɗan Majalisar Areyofagus, haka kuma wata mace mai suna Damaris, da waɗansu dai haka. ");
INSERT INTO hausa_vpl VALUES ("AC18_1","074_18_1","ACT","18","1","1","Bayan haka, Bulus ya bar Atens ya tafi Korint. ");
INSERT INTO hausa_vpl VALUES ("AC18_2","074_18_2","ACT","18","2","2","A can ya sadu da wani mutumin Yahuda mai suna Akwila, ɗan garin Fontus, wanda ya je can ba da daɗewa ba daga Italiya tare da matarsa Firiskila, gama Kalaudiyus ya umarci dukan Yahudawa su bar Roma. Sai Bulus ya tafi yă gan su, ");
INSERT INTO hausa_vpl VALUES ("AC18_3","074_18_3","ACT","18","3","3","da yake shi ma mai ɗinkin tenti ne kamar su, sai ya zauna ya yi aiki tare da su. ");
INSERT INTO hausa_vpl VALUES ("AC18_4","074_18_4","ACT","18","4","4","Kowace Asabbaci kuwa yakan yi muhawwara a majami’a, yana ƙoƙari yă rinjayi Yahudawa da Hellenawa. ");
INSERT INTO hausa_vpl VALUES ("AC18_5","074_18_5","ACT","18","5","5","Sa’ad da Sila da Timoti suka iso daga Makidoniya, sai Bulus ya ba da kansa ga yin wa’azi kaɗai, yana tabbatar wa Yahudawa cewa Yesu shi ne Kiristi. ");
INSERT INTO hausa_vpl VALUES ("AC18_6","074_18_6","ACT","18","6","6","Amma sa’ad da Yahudawa suka yi hamayya da Bulus suka kuma shiga zaginsa, sai ya karkaɗe tufafinsa a cikin rashin yarda, ya ce musu, “Alhakinku yana a kanku! Ba ni da wani laifi. Daga yanzu zan tafi wajen Al’ummai.” ");
INSERT INTO hausa_vpl VALUES ("AC18_7","074_18_7","ACT","18","7","7","Sai Bulus ya bar majami’ar ya kuma tafi ƙofar da take kusa da gidan Titus Yustus, mai yi wa Allah sujada. ");
INSERT INTO hausa_vpl VALUES ("AC18_8","074_18_8","ACT","18","8","8","Kirisbus, shugaban majami’a, da dukan iyalinsa suka gaskata Ubangiji; Korintiyawa masu yawa kuwa da suka ji shi suka gaskata, aka kuwa yi musu baftisma. ");
INSERT INTO hausa_vpl VALUES ("AC18_9","074_18_9","ACT","18","9","9","Wata rana da dad dare, Ubangiji ya yi magana da Bulus a cikin wahayi ya ce, “Kada ka ji tsoro; ka ci gaba da yin magana, kada ka yi shiru. ");
INSERT INTO hausa_vpl VALUES ("AC18_10","074_18_10","ACT","18","10","10","Gama ina tare da kai, ba kuma wanda zai fāɗa maka ya cuce ka, domin ina da mutane da yawa a wannan birni.” ");
INSERT INTO hausa_vpl VALUES ("AC18_11","074_18_11","ACT","18","11","11","Saboda haka Bulus ya zauna a nan har shekara ɗaya da rabi, yana koya musu maganar Allah. ");
INSERT INTO hausa_vpl VALUES ("AC18_12","074_18_12","ACT","18","12","12","Yayinda Galliyo yake muƙaddas Akayya, Yahudawa suka haɗa kai suka tasar wa Bulus, suka kuwa kawo shi cikin kotu. ");
INSERT INTO hausa_vpl VALUES ("AC18_13","074_18_13","ACT","18","13","13","Suka yi zarge cewa, “Wannan mutum yana rarrashin mutane su yi wa Allah sujada a hanyoyin da suka saɓa wa doka.” ");
INSERT INTO hausa_vpl VALUES ("AC18_14","074_18_14","ACT","18","14","14","A daidai sa’ad da Bulus yana shirin yin magana, sai Galliyo ya ce wa Yahudawan, “Da a ce ku Yahudawa kuna gunaguni game da munafunci, ko kuma wani babban laifi, da sai in iya sauraronku. ");
INSERT INTO hausa_vpl VALUES ("AC18_15","074_18_15","ACT","18","15","15","Amma da yake ya shafi gardama ce game da kalmomi da sunaye da kuma dokarku, sai ku ji da ita da kanku. Ni ba zan zama mai shari’a kan irin waɗannan abubuwa ba.” ");
INSERT INTO hausa_vpl VALUES ("AC18_16","074_18_16","ACT","18","16","16","Saboda haka ya kore su. ");
INSERT INTO hausa_vpl VALUES ("AC18_17","074_18_17","ACT","18","17","17","Sai duk suka juya kan Sostenes shugaban majami’a suka yi masa dūka a gaban kotun. Amma Galliyo ko yă kula. ");
INSERT INTO hausa_vpl VALUES ("AC18_18","074_18_18","ACT","18","18","18","Bulus kuwa ya ci gaba da zama a Korint na ’yan kwanaki. Sa’an nan ya bar ’yan’uwa ya shiga jirgin ruwa zuwa Suriya tare da Firiskila da Akwila. Kafin ya tashi, ya aske kansa a Kenkireya saboda alkawarin da ya yi. ");
INSERT INTO hausa_vpl VALUES ("AC18_19","074_18_19","ACT","18","19","19","Suka isa Afisa, inda Bulus ya bar Firiskila da Akwila. Shi kansa ya shiga majami’a ya kuma yi muhawwara da Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("AC18_20","074_18_20","ACT","18","20","20","Sa’ad da suka roƙe shi ya ƙara ’yan kwanaki da su, bai yarda ba. ");
INSERT INTO hausa_vpl VALUES ("AC18_21","074_18_21","ACT","18","21","21","Amma da yake barin wurin, ya yi alkawari cewa, “Zan dawo in Allah ya yarda.” Sa’an nan ya tashi daga Afisa a jirgin ruwa. ");
INSERT INTO hausa_vpl VALUES ("AC18_22","074_18_22","ACT","18","22","22","Sa’ad da ya sauka a Kaisariya, sai ya haura ya gai da ikkilisiya sa’an nan ya gangara zuwa Antiyok. ");
INSERT INTO hausa_vpl VALUES ("AC18_23","074_18_23","ACT","18","23","23","Bayan ya yi ’yan kwanaki a Antiyok, Bulus ya tashi daga can ya zaga ko’ina a yankin Galatiya da Firjiya, yana ƙarfafa dukan almajirai. ");
INSERT INTO hausa_vpl VALUES ("AC18_24","074_18_24","ACT","18","24","24","Ana cikin haka sai wani mutumin Yahuda mai suna Afollos, ɗan ƙasar Alekzandariya, ya zo Afisa. Shi masani ne, yana da cikakken sani na Nassosi. ");
INSERT INTO hausa_vpl VALUES ("AC18_25","074_18_25","ACT","18","25","25","An horar da shi a hanyar Ubangiji, ya kuma himma ƙwarai a magana, ya kuma yi koyarwa game da Yesu, daidai, ko da yake baftismar Yohanna ce kaɗai ya sani. ");
INSERT INTO hausa_vpl VALUES ("AC18_26","074_18_26","ACT","18","26","26","Sai ya fara magana gabagadi a majami’a. Sa’ad da Firiskila da Akwila suka ji shi, sai suka gayyace shi gidansu suka ƙara bayyana masa hanyar Allah sosai. ");
INSERT INTO hausa_vpl VALUES ("AC18_27","074_18_27","ACT","18","27","27","Sa’ad da Afollos ya so ya tafi Akayya, sai ’yan’uwa suka ƙarfafa shi suka kuma rubuta wa almajiran da suke can da su marabce shi. Da isowarsa, ya zama da taimako ƙwarai ga waɗanda ta wurin alheri suka gaskata. ");
INSERT INTO hausa_vpl VALUES ("AC18_28","074_18_28","ACT","18","28","28","Gama da ƙwazo ya ƙaryata Yahudawa a muhawwara a fili, yana tabbatar daga Nassosi cewa Yesu shi ne Kiristi. ");
INSERT INTO hausa_vpl VALUES ("AC19_1","074_19_1","ACT","19","1","1","Lokacin da Afollos yake a Korint, Bulus ya bi hanyar da ta ratsa ta Asiya ya zo Afisa. A can ya sadu da waɗansu almajirai, ");
INSERT INTO hausa_vpl VALUES ("AC19_2","074_19_2","ACT","19","2","2","sai ya tambaye, su ya ce, “Kun karɓi Ruhu Mai Tsarki sa’ad da kuka gaskata?” Suka amsa suka ce, “A’a, ba mu ma san akwai Ruhu Mai Tsarki ba.” ");
INSERT INTO hausa_vpl VALUES ("AC19_3","074_19_3","ACT","19","3","3","Saboda haka Bulus ya yi tambaya ya ce, “To, wace baftisma aka yi muku?” Suka ce, “Baftismar Yohanna.” ");
INSERT INTO hausa_vpl VALUES ("AC19_4","074_19_4","ACT","19","4","4","Bulus ya ce, “Ai, baftismar Yohanna, baftisma ce ta tuba. Ya ce wa mutane su gaskata a wani wanda yake zuwa bayansa, wato, Yesu.” ");
INSERT INTO hausa_vpl VALUES ("AC19_5","074_19_5","ACT","19","5","5","Da ji wannan, sai aka yi musu baftisma a cikin sunan Ubangiji Yesu. ");
INSERT INTO hausa_vpl VALUES ("AC19_6","074_19_6","ACT","19","6","6","Da Bulus ya ɗibiya musu hannuwansa, sai Ruhu Mai Tsarki ya sauka musu, suka kuwa yi magana da harsuna, suka kuma yi annabci. ");
INSERT INTO hausa_vpl VALUES ("AC19_7","074_19_7","ACT","19","7","7","Mutane kuwa su wajen mutum goma sha biyu ne. ");
INSERT INTO hausa_vpl VALUES ("AC19_8","074_19_8","ACT","19","8","8","Bulus ya shiga majami’a ya yi magana gabagadi a can na watanni uku, yana muhawwara yana kuma rinjayarsu game da mulkin Allah. ");
INSERT INTO hausa_vpl VALUES ("AC19_9","074_19_9","ACT","19","9","9","Amma waɗansunsu suka taurara; suka ƙi su gaskata kuma a gaban jama’a suka yi baƙar magana game da Hanyar. Bulus kuwa ya bar su. Ya tafi tare da almajirai ya dinga tattaunawa da su kullum a babban ɗakin jawabi na Tirannus. ");
INSERT INTO hausa_vpl VALUES ("AC19_10","074_19_10","ACT","19","10","10","Wannan ya ci gaba har shekara biyu, sai da ya sa dukan Yahudawa da Hellenawa da suke zaune a lardin Asiya suka ji maganar Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("AC19_11","074_19_11","ACT","19","11","11","Allah ya yi ayyukan banmamakin da suka wuce misali ta hannu Bulus, ");
INSERT INTO hausa_vpl VALUES ("AC19_12","074_19_12","ACT","19","12","12","har ma ana kai hankicif da adikan da suka taɓa jikinsa wa marasa lafiya, suka kuwa warke daga cututtukansu mugayen ruhohi kuma suka rabu da su. ");
INSERT INTO hausa_vpl VALUES ("AC19_13","074_19_13","ACT","19","13","13","Waɗansu Yahudawa masu yawo gari-gari suna fitar da mugayen ruhohi suka yi ƙoƙari su yi amfani da sunan Ubangiji Yesu a kan waɗanda suke da aljanu. Suna cewa, “A cikin sunan Yesu wanda Bulus yake wa’azi, na umarce ku, ku fito.” ");
INSERT INTO hausa_vpl VALUES ("AC19_14","074_19_14","ACT","19","14","14","’Ya’ya bakwai maza na Sikeba, wani babban firist na Yahudawa, suna yin haka. ");
INSERT INTO hausa_vpl VALUES ("AC19_15","074_19_15","ACT","19","15","15","Wata rana mugun ruhu ya amsa musu ya ce, “Yesu kam na sani, Bulus kuma na sani, amma ku kuma su wane ne?” ");
INSERT INTO hausa_vpl VALUES ("AC19_16","074_19_16","ACT","19","16","16","Sai mutumin da yake da mugun ruhun ya fāɗa musu ya sha ƙarfinsu duka. Ya yi musu dūkan tsiya har suka fita a guje daga gidan tsirara jini yana zuba. ");
INSERT INTO hausa_vpl VALUES ("AC19_17","074_19_17","ACT","19","17","17","Da Yahudawa da Hellenawan da suke zama a Afisa suka ji wannan labari sai duk tsoro ya kama su, aka kuwa darjanta sunan Ubangiji Yesu ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("AC19_18","074_19_18","ACT","19","18","18","Da yawa cikin waɗanda suka gaskata yanzu suka zo a fili suka furta mugayen ayyukansu. ");
INSERT INTO hausa_vpl VALUES ("AC19_19","074_19_19","ACT","19","19","19","Waɗansu masu yin sihiri suka kawo naɗaɗɗun littattafansu wuri ɗaya suka kuwa ƙone su a gaban jama’a. Sa’ad da aka lissafta yawan kuɗin naɗaɗɗun littattafan nan, sai jimillar ta kai darik dubu hamsin. ");
INSERT INTO hausa_vpl VALUES ("AC19_20","074_19_20","ACT","19","20","20","Ta haka maganar Ubangiji ta bazu ko’ina ta kuma yi ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("AC19_21","074_19_21","ACT","19","21","21","Bayan dukan wannan ya faru, sai Bulus ya yanke shawara ya ratsa Makidoniya da Akayya in za shi Urushalima. Ya kuma ce, “Bayan na tafi can, dole in ziyarci Roma ita ma.” ");
INSERT INTO hausa_vpl VALUES ("AC19_22","074_19_22","ACT","19","22","22","Sai ya aiki biyu daga cikin masu taimakonsa, Timoti da Erastus, zuwa Makidoniya, yayinda shi kuwa ya ɗan dakata a lardin Asiya. ");
INSERT INTO hausa_vpl VALUES ("AC19_23","074_19_23","ACT","19","23","23","Kusan wannan lokaci sai aka yi wani babban hargitsi game da wannan Hanyar. ");
INSERT INTO hausa_vpl VALUES ("AC19_24","074_19_24","ACT","19","24","24","Wani maƙerin azurfa, mai suna Demetiriyus wanda yake ƙera siffar ɗakunan tsafin Artemis da azurfa, ba ƙaramin ciniki yake kawo wa mutane masu sana’an nan ba. ");
INSERT INTO hausa_vpl VALUES ("AC19_25","074_19_25","ACT","19","25","25","Sai ya tara su wuri ɗaya, tare da masu irin wannan sana’ar ya ce, “Ku jama’a, kun san muna samun kuɗin shiga sosai daga wannan sana’a. ");
INSERT INTO hausa_vpl VALUES ("AC19_26","074_19_26","ACT","19","26","26","Kuma kuna ji kuna gani yadda Bulus ɗin nan ya shawo kan mutane da yawa ya kuma sa suka bauɗe a nan a Afisa da dukan lardin Asiya. Yana cewa alloli da mutum ya ƙera ba alloli ba ne ko kaɗan. ");
INSERT INTO hausa_vpl VALUES ("AC19_27","074_19_27","ACT","19","27","27","Akwai hatsari, ba kawai cewa sana’armu za tă rasa sunanta mai daraja ba, amma za a yi banza da ɗakin tsafin Artemis alliyarmu mai girma, alliyar kanta wadda ake bauta a ko’ina a yankin Asiya da kuma duniya, za a raba ta da darajarta.” ");
INSERT INTO hausa_vpl VALUES ("AC19_28","074_19_28","ACT","19","28","28","Da suka ji haka, sai suka yi fushi ƙwarai suka fara ihu suna cewa, “Girma ta tabbata ga Artemis ta Afisawa!” ");
INSERT INTO hausa_vpl VALUES ("AC19_29","074_19_29","ACT","19","29","29","Jim kaɗan sai hayaniya ta tashi a dukan birnin. Sai mutane suka cafke Gayus da Aristarkus, abokan tafiyar Bulus daga Makidoniya, suka ruga da zuwa fili da nufi ɗaya. ");
INSERT INTO hausa_vpl VALUES ("AC19_30","074_19_30","ACT","19","30","30","Bulus ya so ya bayyana a gaban taron, amma almajirai ba su bar shi ba. ");
INSERT INTO hausa_vpl VALUES ("AC19_31","074_19_31","ACT","19","31","31","Har waɗansu shugabannin lardin ma, abokan Bulus, suka aika masa suna roƙonsa kada yă kuskura ya shiga filin nan. ");
INSERT INTO hausa_vpl VALUES ("AC19_32","074_19_32","ACT","19","32","32","Taron kuwa ya ruɗe. Waɗansu suna ihu suna ce abu kaza, waɗansu kuma wani abu dabam. Yawancin mutane kuma ba su ma san abin da ya sa suke a wurin ba. ");
INSERT INTO hausa_vpl VALUES ("AC19_33","074_19_33","ACT","19","33","33","Yahudawa suka tura Alekzanda gaba, sai waɗansu a taron suka riƙa yin masa ihu. Sai ya ɗaga hannu don a yi shiru don yă kāre kansa a gaban mutane. ");
INSERT INTO hausa_vpl VALUES ("AC19_34","074_19_34","ACT","19","34","34","Amma sa’ad da suka gane shi mutumin Yahuda ne, sai duk suka yi ihu gaba ɗaya na kusa sa’a biyu, suna cewa, “Girma ta tabbata ga Artemis ta Afisawa!” ");
INSERT INTO hausa_vpl VALUES ("AC19_35","074_19_35","ACT","19","35","35","Sai magatakardar birnin ya sa taron su yi shiru, sa’an nan ya ce, “Mutanen Afisa, ashe duk duniya ba tă san cewa birnin Afisa ce mai lura da haikalin Artemis mai girma da kuma siffarta da ya fāɗi daga sama ba? ");
INSERT INTO hausa_vpl VALUES ("AC19_36","074_19_36","ACT","19","36","36","Saboda haka, da yake ba dama a yi mūsun wannan gaskiya, ya kamata ku natsu kada ku yi kome da garaje. ");
INSERT INTO hausa_vpl VALUES ("AC19_37","074_19_37","ACT","19","37","37","Kun kawo mutanen nan a nan, gashi kuwa ba su yi fashin haikali ba, ba su kuwa saɓa wa alliyarmu ba. ");
INSERT INTO hausa_vpl VALUES ("AC19_38","074_19_38","ACT","19","38","38","To, in haka ne, in Demetiriyus da abokan sana’arsa suna da wata magana game da wani ai, kotuna suna nan a buɗe, akwai kuma muƙaddasai. Suna iya kai ƙara. ");
INSERT INTO hausa_vpl VALUES ("AC19_39","074_19_39","ACT","19","39","39","In kuma akwai wani abu har yanzu da kuke so ku kawo, dole a daidaita shi a majalisa. ");
INSERT INTO hausa_vpl VALUES ("AC19_40","074_19_40","ACT","19","40","40","Yadda yake a yanzu, muna a hatsarin amsa zargin ta da hargitsi saboda abin da ya faru yau. Da yake ba za mu iya ba da dalilin da ya sa aka yi wannan hargitsi ba.” ");
INSERT INTO hausa_vpl VALUES ("AC19_41","074_19_41","ACT","19","41","41","Bayan da ya faɗi haka, sai ya sallami taron. ");
INSERT INTO hausa_vpl VALUES ("AC20_1","074_20_1","ACT","20","1","1","Sa’ad da hayaniyar ta kwanta, sai Bulus ya aika a kira almajiran, kuma bayan ya ƙarfafa su, sai ya yi bankwana ya tafi Makidoniya. ");
INSERT INTO hausa_vpl VALUES ("AC20_2","074_20_2","ACT","20","2","2","Ya ratsa wurin yana ƙarfafa mutanen da kalmomi masu yawa, a ƙarshe kuma ya kai Giris, ");
INSERT INTO hausa_vpl VALUES ("AC20_3","074_20_3","ACT","20","3","3","inda ya zauna wata uku. Da yake Yahudawa sun ƙulla masa makirci, a lokacin da yake shirin tashi cikin jirgin ruwa zuwa Suriya, sai ya yanka shawara yă koma ta Makidoniya. ");
INSERT INTO hausa_vpl VALUES ("AC20_4","074_20_4","ACT","20","4","4","Sai Sofater ɗan Fairrus daga Bereya, Aristarkus da Sekundus daga Tessalonika, Gayus daga Derbe, Timoti ma, da Tikikus da Turofimus daga lardin Asiya suka tafi tare da shi. ");
INSERT INTO hausa_vpl VALUES ("AC20_5","074_20_5","ACT","20","5","5","Waɗannan mutane suka sha gaba suka kuma jira mu a Toruwas. ");
INSERT INTO hausa_vpl VALUES ("AC20_6","074_20_6","ACT","20","6","6","Amma muka tashi daga Filibbi a jirgin ruwa bayan Bikin Burodi Marar Yisti bayan kuma kwana biyar muka sadu da sauran a Toruwas, inda muka zauna kwana bakwai. ");
INSERT INTO hausa_vpl VALUES ("AC20_7","074_20_7","ACT","20","7","7","A ranar farko ta mako muka taru wuri ɗaya don gutsuttsura burodi. Bulus ya yi wa mutane magana, don yana niyyar tashi kashegari, sai ya yi ta yin magana har tsakar dare. ");
INSERT INTO hausa_vpl VALUES ("AC20_8","074_20_8","ACT","20","8","8","Akwai fitilu da yawa a ɗakin gidan saman da muka taru. ");
INSERT INTO hausa_vpl VALUES ("AC20_9","074_20_9","ACT","20","9","9","Akwai wani saurayi zaune a taga mai suna Yitikus, wanda barci mai nauyi ya ɗauke shi yayinda Bulus yake ta tsawaita magana. Sa’ad da yake barci, sai ya fāɗi daga gidan sama a hawa ta uku aka kuma ɗauke shi matacce. ");
INSERT INTO hausa_vpl VALUES ("AC20_10","074_20_10","ACT","20","10","10","Sai Bulus ya sauka, ya miƙe a kan saurayin ya rungume shi ya ce, “Kada ku damu, yana da rai!” ");
INSERT INTO hausa_vpl VALUES ("AC20_11","074_20_11","ACT","20","11","11","Sai ya koma ɗakin da yake a gidan sama, ya gutsuttsura burodi ya kuma ci. Bayan ya yi magana har gari ya waye, sai ya tafi. ");
INSERT INTO hausa_vpl VALUES ("AC20_12","074_20_12","ACT","20","12","12","Mutanen suka ɗauki saurayin da rai zuwa gida suka kuma ta’azantu ƙwarai da gaske. ");
INSERT INTO hausa_vpl VALUES ("AC20_13","074_20_13","ACT","20","13","13","Mu kuwa muka ci gaba zuwa jirgin ruwan muka tashi muka nufi Assos inda za mu ɗauki Bulus. Ya yi wannan shirin don zai tafi can da ƙafa. ");
INSERT INTO hausa_vpl VALUES ("AC20_14","074_20_14","ACT","20","14","14","Da ya same mu a Assos, sai muka ɗauke shi a jirgin ruwan muka zo Mitilen. ");
INSERT INTO hausa_vpl VALUES ("AC20_15","074_20_15","ACT","20","15","15","Kashegari muka tashi cikin jirgin ruwa daga can muka zo gefen Kiyos. Kwana ɗaya bayan wannan, sai muka ƙetare zuwa Samos, kashegari kuma muka iso Miletus. ");
INSERT INTO hausa_vpl VALUES ("AC20_16","074_20_16","ACT","20","16","16","Bulus ya yanke shawara yă wuce Afisa a jirgin ruwa don kada yă ɓata lokaci a lardin Asiya, gama yana sauri yă kai Urushalima, in ya yiwu ma, a ranar Fentekos. ");
INSERT INTO hausa_vpl VALUES ("AC20_17","074_20_17","ACT","20","17","17","Daga Miletus, Bulus ya aika zuwa Afisa a kira dattawan ikkilisiya. ");
INSERT INTO hausa_vpl VALUES ("AC20_18","074_20_18","ACT","20","18","18","Da suka iso, sai ya ce musu, “Kun san irin zaman da na yi tun lokacin da na zauna da ku, daga ranar farkon da na zo cikin lardin Asiya. ");
INSERT INTO hausa_vpl VALUES ("AC20_19","074_20_19","ACT","20","19","19","Na bauta wa Ubangiji da matuƙar tawali’u har da hawaye, da gwagwarmaya iri-irin da na sha game da makircin Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("AC20_20","074_20_20","ACT","20","20","20","Kun san cewa ban yi wata-wata yin muku wa’azi game da duk abin da zai amfane ku ba amma na koyar da ku a fili da kuma gida-gida. ");
INSERT INTO hausa_vpl VALUES ("AC20_21","074_20_21","ACT","20","21","21","Na yi shela ga Yahudawa da Hellenawa cewa dole su juye ga Allah cikin tuba su kuma amince da Ubangijinmu Yesu. ");
INSERT INTO hausa_vpl VALUES ("AC20_22","074_20_22","ACT","20","22","22","“Yanzu kuma Ruhu ya tilasta ni, za ni Urushalima, ba tare da sanin abin da zai faru da ni a can ba. ");
INSERT INTO hausa_vpl VALUES ("AC20_23","074_20_23","ACT","20","23","23","Na dai san cewa a kowace birni Ruhu Mai Tsarki yakan gargaɗe ni cewa kurkuku da shan wuya suna jirana. ");
INSERT INTO hausa_vpl VALUES ("AC20_24","074_20_24","ACT","20","24","24","Amma ni ban ɗauki raina a bakin kome ba, in dai zan iya gama tserena in kuma kammala aikin da Ubangiji Yesu ya ba ni aikin shaida bisharar alherin Allah. ");
INSERT INTO hausa_vpl VALUES ("AC20_25","074_20_25","ACT","20","25","25","“Yanzu na san cewa ba ko ɗaya daga cikinku wanda na zazzaga ina muku wa’azin mulkin Allah da zai sāke ganina. ");
INSERT INTO hausa_vpl VALUES ("AC20_26","074_20_26","ACT","20","26","26","Saboda haka, ina muku shela a yau cewa ba ni da alhakin kowa a kaina. ");
INSERT INTO hausa_vpl VALUES ("AC20_27","074_20_27","ACT","20","27","27","Gama ban yi wata-wata a sanar muku dukan nufin Allah ba. ");
INSERT INTO hausa_vpl VALUES ("AC20_28","074_20_28","ACT","20","28","28","Ku lura da kanku da dukan garken da Ruhu Mai Tsarki ya sa ku ku zama masu kula da shi. Ku zama masu kiwon ikkilisiyar Allah, wadda ya saya da jininsa. ");
INSERT INTO hausa_vpl VALUES ("AC20_29","074_20_29","ACT","20","29","29","Na san cewa bayan na tafi, mugayen kyarketai za su shigo cikinku ba za su kuwa ƙyale garken ba. ");
INSERT INTO hausa_vpl VALUES ("AC20_30","074_20_30","ACT","20","30","30","Ko cikinku ma mutane za su taso su karkatar da gaskiya don su jawo wa kansu almajirai. ");
INSERT INTO hausa_vpl VALUES ("AC20_31","074_20_31","ACT","20","31","31","Saboda haka ku zauna a faɗake! Ku tuna cewa shekara uku, dare da rana ban taɓa fasa yin wa kowannenku gargaɗi ba, har da hawaye. ");
INSERT INTO hausa_vpl VALUES ("AC20_32","074_20_32","ACT","20","32","32","“To, yanzu na danƙa ku ga Allah da kuma ga maganar alherinsa, wadda za tă iya gina ku ta kuma ba ku gādo a cikin dukan waɗanda aka tsarkake. ");
INSERT INTO hausa_vpl VALUES ("AC20_33","074_20_33","ACT","20","33","33","Ban yi ƙyashin azurfa ko zinariya ko tufafin kowa ba. ");
INSERT INTO hausa_vpl VALUES ("AC20_34","074_20_34","ACT","20","34","34","Ku kanku kun san cewa hannuwan nan nawa sun biya mini bukatuna da kuma na abokan aikina. ");
INSERT INTO hausa_vpl VALUES ("AC20_35","074_20_35","ACT","20","35","35","Cikin kowane abin da na yi, na nuna muku cewa da irin wannan aiki tuƙuru don mu taimaki marasa ƙarfi, muna tunawa da kalmomin da Ubangiji Yesu kansa ya ce, ‘Bayarwa ta fi karɓa albarka.’ ” ");
INSERT INTO hausa_vpl VALUES ("AC20_36","074_20_36","ACT","20","36","36","Da ya faɗi haka, ya durƙusa tare da dukansu ya yi addu’a. ");
INSERT INTO hausa_vpl VALUES ("AC20_37","074_20_37","ACT","20","37","37","Sai dukansu suka yi kuka suka rungume shi, suka kuma yi masa sumba. ");
INSERT INTO hausa_vpl VALUES ("AC20_38","074_20_38","ACT","20","38","38","Abin da ya fi sa su baƙin ciki shi ne maganarsa da ya ce, ba za su ƙara ganin fuskarsa ba. Sai suka raka shi zuwa wajen jirgin ruwa. ");
INSERT INTO hausa_vpl VALUES ("AC21_1","074_21_1","ACT","21","1","1","Bayan muka rabu da su da ƙyar, sai muka shiga jirgin ruwa, muka miƙe zuwa Kos. Kashegari muka tafi Rods daga can kuma muka je Fatara. ");
INSERT INTO hausa_vpl VALUES ("AC21_2","074_21_2","ACT","21","2","2","Sai muka sami wani jirgin ruwa da zai ƙetare zuwa Funisiya, sai muka shiga muka kama tafiya. ");
INSERT INTO hausa_vpl VALUES ("AC21_3","074_21_3","ACT","21","3","3","Bayan muka hangi Saifurus muka wuce shi ta kudu, sai muka ci gaba zuwa Suriya. Muka sauka a Taya, inda jirgin ruwanmu zai sauke kayansa. ");
INSERT INTO hausa_vpl VALUES ("AC21_4","074_21_4","ACT","21","4","4","Da muka sami almajirai a can, sai muka zauna da su kwana bakwai. Ta wurin Ruhu, suka yi ƙoƙari su hana Bulus wucewa zuwa Urushalima. ");
INSERT INTO hausa_vpl VALUES ("AC21_5","074_21_5","ACT","21","5","5","Amma da lokacin tashinmu ya yi, sai muka tashi muka ci gaba da tafiyarmu. Dukan almajirai da matansu da ’ya’yansu suka raka mu har bayan birni, a can kuwa a bakin teku muka durƙusa muka yi addu’a. ");
INSERT INTO hausa_vpl VALUES ("AC21_6","074_21_6","ACT","21","6","6","Bayan mun yi bankwana da juna, sai muka shiga jirgin ruwa, su kuwa suka koma gida. ");
INSERT INTO hausa_vpl VALUES ("AC21_7","074_21_7","ACT","21","7","7","Muka ci gaba da tafiyarmu daga Taya muka sauka a Tolemayis, inda muka gai da ’yan’uwa muka yi kwana ɗaya tare da su. ");
INSERT INTO hausa_vpl VALUES ("AC21_8","074_21_8","ACT","21","8","8","Da muka tashi kashegari, sai muka isa Kaisariya muka kuma sauka a gidan Filibus mai bishara, ɗaya daga cikin Bakwai ɗin nan. ");
INSERT INTO hausa_vpl VALUES ("AC21_9","074_21_9","ACT","21","9","9","Yana da ’ya’ya huɗu ’yan mata da ba su yi aure ba, waɗanda suka yi annabci. ");
INSERT INTO hausa_vpl VALUES ("AC21_10","074_21_10","ACT","21","10","10","Bayan muka yi ’yan kwanaki da dama a can, sai wani annabin da ake kira Agabus ya gangaro daga Yahudiya. ");
INSERT INTO hausa_vpl VALUES ("AC21_11","074_21_11","ACT","21","11","11","Da ya zo wurinmu, sai ya ɗauki ɗamarar Bulus, ya ɗaura hannuwansa da ƙafafunsa da ita sa’an nan ya ce, “Ruhu Mai Tsarki ya ce, ‘Haka Yahudawan Urushalima za su daure mai wannan ɗamara su kuma ba da shi ga Al’ummai.’ ” ");
INSERT INTO hausa_vpl VALUES ("AC21_12","074_21_12","ACT","21","12","12","Sa’ad da muka ji haka, sai mu da mutanen da suke can muka roƙi Bulus kada yă je Urushalima. ");
INSERT INTO hausa_vpl VALUES ("AC21_13","074_21_13","ACT","21","13","13","Sai Bulus ya amsa ya ce, “Don me kuke kuka kuna kuma ɓata mini zuciya? A shirye nake ba ma a daure ni kawai ba, amma har ma in mutu a Urushalima saboda sunan Ubangiji Yesu.” ");
INSERT INTO hausa_vpl VALUES ("AC21_14","074_21_14","ACT","21","14","14","Da dai ya ƙi rarrasuwa, muka yi shiru, muka ce, “Bari Ubangiji yă yi nufinsa.” ");
INSERT INTO hausa_vpl VALUES ("AC21_15","074_21_15","ACT","21","15","15","Bayan haka, sai muka shirya muka kuma haura zuwa Urushalima. ");
INSERT INTO hausa_vpl VALUES ("AC21_16","074_21_16","ACT","21","16","16","Waɗansu almajirai daga Kaisariya suka raka mu suka kawo mu gidan Minason, inda za mu sauka. Shi mutumin Saifurus ne kuma ɗaya daga cikin almajirai na farko. ");
INSERT INTO hausa_vpl VALUES ("AC21_17","074_21_17","ACT","21","17","17","Sa’ad da muka zo Urushalima, ’yan’uwa suka karɓe mu da murna. ");
INSERT INTO hausa_vpl VALUES ("AC21_18","074_21_18","ACT","21","18","18","Kashegari Bulus da sauranmu muka tafi domin mu ga Yaƙub, dukan dattawan kuwa suna nan. ");
INSERT INTO hausa_vpl VALUES ("AC21_19","074_21_19","ACT","21","19","19","Bulus ya gaishe su ya kuma ba su rahoto dalla-dalla a kan abin da Allah ya yi a cikin Al’ummai ta wurin aikinsa. ");
INSERT INTO hausa_vpl VALUES ("AC21_20","074_21_20","ACT","21","20","20","Da suka ji haka, sai suka yabi Allah. Sa’an nan suka ce wa Bulus, “Ka gani ɗan’uwa, yawan dubban Yahudawan da suka gaskata, kuma dukansu masu himma ne a wajen bin doka. ");
INSERT INTO hausa_vpl VALUES ("AC21_21","074_21_21","ACT","21","21","21","An sanar da su cewa kana koya wa dukan Yahudawan da suke zama a cikin Al’ummai cewa su juye daga Musa, kana kuma faɗa musu kada su yi wa ’ya’yansu kaciya ko su yi rayuwa bisa ga al’adunmu. ");
INSERT INTO hausa_vpl VALUES ("AC21_22","074_21_22","ACT","21","22","22","To, me za mu yi ke nan? Lalle za su ji cewa ka iso, ");
INSERT INTO hausa_vpl VALUES ("AC21_23","074_21_23","ACT","21","23","23","saboda haka, ka yi abin da muka faɗa maka. Akwai mutum huɗu tare da mu da suka yi alkawari. ");
INSERT INTO hausa_vpl VALUES ("AC21_24","074_21_24","ACT","21","24","24","Ka ɗauki waɗannan mutane, ka tafi da su ku tsarkaka gaba ɗaya, ka kuma biya musu kome don su samu su yi aski. Ta haka kowa zai sani babu gaskiya a waɗannan rahotanni game da kai, za a kuma ga cewa kai kanka kana kiyaye dokar. ");
INSERT INTO hausa_vpl VALUES ("AC21_25","074_21_25","ACT","21","25","25","Game da Al’ummai masu bi kuwa, mun yi musu wasiƙa a kan shawararmu cewa su guji abincin da aka miƙa wa gumaka, da jini, da naman dabbar da aka maƙure da kuma fasikanci.” ");
INSERT INTO hausa_vpl VALUES ("AC21_26","074_21_26","ACT","21","26","26","Kashegari, sai Bulus ya ɗauki mutanen ya kuma tsarkake kansa tare da su. Sa’an nan ya tafi haikali domin yă sanar da ranar cikar tsarkakewarsu da kuma ranar da za a ba da sadaka domin kowannensu. ");
INSERT INTO hausa_vpl VALUES ("AC21_27","074_21_27","ACT","21","27","27","Da kwana bakwai ɗin suka yi kusan cika, waɗansu Yahudawa daga lardin Asiya suka ga Bulus a haikali. Sai suka zuga taron duka, suka kama shi, ");
INSERT INTO hausa_vpl VALUES ("AC21_28","074_21_28","ACT","21","28","28","suna ihu suna cewa “Mutanen Isra’ila ku taimake mu! Ga mutumin da yake koya wa dukan mutane ko’ina cewa su ƙi mutanenmu da dokarmu da kuma wannan wuri. Ban da haka ma, ya kawo Hellenawa a cikin filin haikali ya ƙazantar da wurin nan mai tsarki.” ");
INSERT INTO hausa_vpl VALUES ("AC21_29","074_21_29","ACT","21","29","29","(Dā ma can sun ga Turofimus mutumin Afisa a birni tare da Bulus suka yi tsammani Bulus ya kawo shi filin haikali.) ");
INSERT INTO hausa_vpl VALUES ("AC21_30","074_21_30","ACT","21","30","30","Duk birnin ya ruɗe, mutane suka zaburo da gudu daga kowane gefe. Suka kama Bulus, suka ja shi daga haikali, nan da nan aka rurrufe ƙofofi. ");
INSERT INTO hausa_vpl VALUES ("AC21_31","074_21_31","ACT","21","31","31","Yayinda suke ƙoƙari su kashe shi, sai labari ya kai ga shugaban ƙungiyar sojan Roma cewa birnin Urushalima duk ta hargitse. ");
INSERT INTO hausa_vpl VALUES ("AC21_32","074_21_32","ACT","21","32","32","Nan da nan ya ɗibi waɗansu hafsoshi da sojoji suka gangara a guje wurin taron. Da masu hargitsin suka ga shugaban ƙungiyar sojan da sojojinsa, sai suka daina dūkan Bulus. ");
INSERT INTO hausa_vpl VALUES ("AC21_33","074_21_33","ACT","21","33","33","Shugaban ƙungiyar sojan ya zo ya kama shi ya ba da umarni a daure shi da sarƙoƙi biyu. Sa’an nan ya yi tambaya ko shi wane ne, da kuma abin da ya yi. ");
INSERT INTO hausa_vpl VALUES ("AC21_34","074_21_34","ACT","21","34","34","Waɗansu daga cikin taron suka ɗau kururuwa suna ce abu kaza, waɗansu kuma suna ce abu kaza, da yake shugaban ƙungiyar sojan ya kāsa samun ainihin tushen maganar saboda yawan hayaniyar, sai ya yi umarni a kai Bulus barikin soja. ");
INSERT INTO hausa_vpl VALUES ("AC21_35","074_21_35","ACT","21","35","35","Sa’ad da Bulus ya kai bakin matakala, sai da sojoji suka ɗaga shi sama saboda tsananin haukan taron. ");
INSERT INTO hausa_vpl VALUES ("AC21_36","074_21_36","ACT","21","36","36","Taron da suka bi suka dinga kururuwa, suna cewa, “A yi da shi!” ");
INSERT INTO hausa_vpl VALUES ("AC21_37","074_21_37","ACT","21","37","37","Da sojoji suka kai gab da shigar da Bulus cikin bariki, sai ya ce wa shugaban ƙungiyar sojan, “Ko ka yarda in yi magana da kai?” Sai ya amsa ya ce, “Ka iya Girik ne? ");
INSERT INTO hausa_vpl VALUES ("AC21_38","074_21_38","ACT","21","38","38","Ba kai ba ne mutumin Masar nan da ya haddasa tawaye har ya yi jagorar ’yan ta’ada dubu huɗu zuwa hamada a shekarun baya?” ");
INSERT INTO hausa_vpl VALUES ("AC21_39","074_21_39","ACT","21","39","39","Bulus ya amsa ya ce, “Ni mutumin Yahuda ne, daga Tarshish a Silisiya shahararren birnin nan. In ka yarda bari in yi wa mutane magana.” ");
INSERT INTO hausa_vpl VALUES ("AC21_40","074_21_40","ACT","21","40","40","Da ya sami izini daga shugaban ƙungiyar sojan, sai Bulus ya tsaya a matakala, ya ɗaga wa taron hannu. Da dukan suka yi shiru, sai ya ce musu da Arameyanci, ");
INSERT INTO hausa_vpl VALUES ("AC22_1","074_22_1","ACT","22","1","1","“’Yan’uwa da iyaye, ku saurari kāriyata yanzu.” ");
INSERT INTO hausa_vpl VALUES ("AC22_2","074_22_2","ACT","22","2","2","Da suka ji ya yi musu magana da Arameyik, sai suka yi tsit. Sai Bulus ya ce, ");
INSERT INTO hausa_vpl VALUES ("AC22_3","074_22_3","ACT","22","3","3","“Ni mutumin Yahuda ne haifaffen Tarshish na Silisiya, amma a nan birnin ne aka rene ni. Aka horar da ni sosai cikin dokokin kakanninmu a ƙarƙashin Gamaliyel ni ma dā mai himma ne cikin bauta wa Allah kamar yadda kowannenku yake a yau. ");
INSERT INTO hausa_vpl VALUES ("AC22_4","074_22_4","ACT","22","4","4","Na tsananta wa masu bin wannan Hanyar har ga mutuwarsu, ina kama maza da mata ina kuma jefa su cikin kurkuku, ");
INSERT INTO hausa_vpl VALUES ("AC22_5","074_22_5","ACT","22","5","5","kamar yadda babban firist da dukan Majalisa za su iya shaida. Na ma karɓi wasiƙu daga gare su zuwa ga ’yan’uwansu a Damaskus, na kuma tafi can don in kawo waɗannan mutane a daure zuwa Urushalima don a hukunta su. ");
INSERT INTO hausa_vpl VALUES ("AC22_6","074_22_6","ACT","22","6","6","“Wajen tsakar rana da na yi kusa da Damaskus, ba zato ba tsammani sai wani babban haske daga sama ya haskaka kewaye da ni. ");
INSERT INTO hausa_vpl VALUES ("AC22_7","074_22_7","ACT","22","7","7","Sai na fāɗi a ƙasa na kuma ji wata murya ta ce mini, ‘Shawulu! Shawulu! Don me kake tsananta mini?’ ");
INSERT INTO hausa_vpl VALUES ("AC22_8","074_22_8","ACT","22","8","8","“Sai na yi tambaya na ce, ‘Wane ne kai, ya Ubangiji?’ “Ya amsa ya ce, ‘Ni ne Yesu Banazare, wanda kake tsanantawa.’ ");
INSERT INTO hausa_vpl VALUES ("AC22_9","074_22_9","ACT","22","9","9","Abokan tafiyata suka ga hasken, amma ba su fahimci muryar mai magana da ni ba. ");
INSERT INTO hausa_vpl VALUES ("AC22_10","074_22_10","ACT","22","10","10","“Sai na yi tambaya, na ce, ‘Me zan yi, ya Ubangiji?’ “Ubangiji ya ce, ‘Tashi, ka tafi cikin Damaskus. A can za a faɗa maka duk abin da aka shirya za ka yi.’ ");
INSERT INTO hausa_vpl VALUES ("AC22_11","074_22_11","ACT","22","11","11","Abokan tafiyata suka ja ni a hannu zuwa cikin Damaskus, saboda ƙarfin hasken ya makanta ni. ");
INSERT INTO hausa_vpl VALUES ("AC22_12","074_22_12","ACT","22","12","12","“Wani mutumin da ake kira Ananiyas ya zo ya gan ni. Shi mai ibada ne wajen kiyaye dokoki wanda dukan Yahudawan da suke zama a can suna girmama shi ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("AC22_13","074_22_13","ACT","22","13","13","Ya tsaya kusa da ni ya ce, ‘Ɗan’uwa Shawulu, ka sami ganin garinka!’ A daidai lokacin kuwa na iya ganinsa. ");
INSERT INTO hausa_vpl VALUES ("AC22_14","074_22_14","ACT","22","14","14","“Sa’an nan ya ce, ‘Allah na kakanninmu ya zaɓe ka ka san nufinsa ka kuma ga Mai Adalcin nan ka kuma ji kalmomi daga bakinsa. ");
INSERT INTO hausa_vpl VALUES ("AC22_15","074_22_15","ACT","22","15","15","Za ka zama mai shaidarsa ga dukan mutane game da abin da ka gani ka kuma ji. ");
INSERT INTO hausa_vpl VALUES ("AC22_16","074_22_16","ACT","22","16","16","Yanzu me kake jira? Ka tashi, a yi maka baftisma, a wanke zunubanka, ta wurin kira bisa ga sunansa.’ ");
INSERT INTO hausa_vpl VALUES ("AC22_17","074_22_17","ACT","22","17","17","“Sa’ad da na dawo Urushalima ina cikin addu’a a haikali, sai na ga wahayi ");
INSERT INTO hausa_vpl VALUES ("AC22_18","074_22_18","ACT","22","18","18","na ga Ubangiji yana magana. Ya ce mini, ‘Maza! Ka bar Urushalima, gama ba za su yarda da shaidarka game da ni ba.’ ");
INSERT INTO hausa_vpl VALUES ("AC22_19","074_22_19","ACT","22","19","19","“Na amsa na ce, ‘Ubangiji, waɗannan mutane sun san cewa na bi majami’a-majami’a na jefa waɗanda suka gaskata da kai a cikin kurkuku, in kuma yin musu dūka. ");
INSERT INTO hausa_vpl VALUES ("AC22_20","074_22_20","ACT","22","20","20","Sa’ad da kuma aka zub da jinin Istifanus mashaidinka, na tsaya can ina ba da goyon bayana ina kuma tsaron tufafin masu kisansa.’ ");
INSERT INTO hausa_vpl VALUES ("AC22_21","074_22_21","ACT","22","21","21","“Sa’an nan Ubangiji ya ce mini, ‘Je ka; zan aike ka can nesa a wurin Al’ummai.’ ” ");
INSERT INTO hausa_vpl VALUES ("AC22_22","074_22_22","ACT","22","22","22","Taron suka saurari Bulus sai da ya yi wannan magana. Sa’an nan suka ɗaga muryoyinsu suka yi ihu suka ce, “A raba duniya da wannan mutum! Bai cancanci yă rayu ba!” ");
INSERT INTO hausa_vpl VALUES ("AC22_23","074_22_23","ACT","22","23","23","Da suna ihu suna kaɗa mayafansu suna da tā da ƙura sama, ");
INSERT INTO hausa_vpl VALUES ("AC22_24","074_22_24","ACT","22","24","24","sai shugaban ƙungiyar sojan ya umarta a kai Bulus a barikin soja. Ya ba da umarni a yi masa bulala a kuma tambaye shi abin da ya sa mutane suke masa ihu haka. ");
INSERT INTO hausa_vpl VALUES ("AC22_25","074_22_25","ACT","22","25","25","Suna kwantar da shi ke nan domin a yi masa bulala, sai Bulus ya ce wa jarumin da yake tsaye a nan, “Ashe, daidai ne bisa ga doka a yi wa ɗan ƙasar Roma bulala wanda ba a ma tabbatar da laifi a kansa ba?” ");
INSERT INTO hausa_vpl VALUES ("AC22_26","074_22_26","ACT","22","26","26","Da jarumin ya ji haka sai ya je wurin shugaban ƙungiyar sojan ya ce masa, “Me kake so yi ne? Wannan mutum ɗan ƙasar Roma ne.” ");
INSERT INTO hausa_vpl VALUES ("AC22_27","074_22_27","ACT","22","27","27","Sai shugaban ƙungiyar sojan ya je ya tambayi Bulus ya ce, “Faɗa mini, kai ɗan ƙasar Roma ne?” Bulus ya ce, “I.” ");
INSERT INTO hausa_vpl VALUES ("AC22_28","074_22_28","ACT","22","28","28","Sai shugaban ƙungiyar sojan ya ce, “Sai da na biya kuɗi mai yawa kafin in zama ɗan ƙasa.” Bulus ya ce, “Ni kuwa an haife ni ɗan ƙasa.” ");
INSERT INTO hausa_vpl VALUES ("AC22_29","074_22_29","ACT","22","29","29","Waɗanda dā suke shirin yin masa tambayoyi suka ja da baya nan da nan. Shugaban ƙungiyar sojan kansa ya tsorata da ya fahimci cewa ya sa wa Bulus, ɗan ƙasar Roma sarƙa. ");
INSERT INTO hausa_vpl VALUES ("AC22_30","074_22_30","ACT","22","30","30","Kashegari da yake shugaban ƙungiyar sojan ya so yă tabbatar da ainihin abin da ya sa Yahudawa suke zargin Bulus, sai ya sake shi ya kuwa umarci manyan firistoci da dukan Majalisar su taru. Sa’an nan ya kawo Bulus ya sa ya tsaya a gabansu. ");
INSERT INTO hausa_vpl VALUES ("AC23_1","074_23_1","ACT","23","1","1","Bulus ya zuba wa Majalisar ido ya ce, “’Yan’uwana, na cika aikina ga Allah cikin lamiri mai kyau har yă zuwa yau.” ");
INSERT INTO hausa_vpl VALUES ("AC23_2","074_23_2","ACT","23","2","2","Da jin wannan Ananiyas babban firist ya umarci waɗanda suke tsaye kusa da Bulus su buge bakinsa. ");
INSERT INTO hausa_vpl VALUES ("AC23_3","074_23_3","ACT","23","3","3","Sai Bulus ya ce masa, “Allah zai buge ka, kai farin bango! Ka zauna a can kana hukunta ni bisa ga doka, ga shi kai kanka kana ƙetare dokar ta wurin ba da umarni a buge ni!” ");
INSERT INTO hausa_vpl VALUES ("AC23_4","074_23_4","ACT","23","4","4","Waɗanda suke tsaye kusa da Bulus kuwa suka ce masa, “Babban firist na Allah za ka zaga?” ");
INSERT INTO hausa_vpl VALUES ("AC23_5","074_23_5","ACT","23","5","5","Bulus ya amsa ya ce, “’Yan’uwa, ai, ban san cewa shi ne babban firist ba; gama yana a rubuce cewa, ‘Kada ka yi mugun magana game da mai mulkin mutanenka.’” ");
INSERT INTO hausa_vpl VALUES ("AC23_6","074_23_6","ACT","23","6","6","Bulus, da ya gane cewa waɗansu daga cikinsu Sadukiyawa ne sauran kuma Farisiyawa ne, sai ya ɗaga murya a Majalisar ya ce, “’Yan’uwana, ni Bafarisiye ne, ɗan Farisiyawa. Ana mini shari’a saboda begen da nake da shi a kan tashin matattu.” ");
INSERT INTO hausa_vpl VALUES ("AC23_7","074_23_7","ACT","23","7","7","Da ya faɗi haka, sai gardama ta tashi tsakanin Farisiyawa da Sadukiyawa, taron kuwa ya rabu biyu. ");
INSERT INTO hausa_vpl VALUES ("AC23_8","074_23_8","ACT","23","8","8","(Sadukiyawa suna cewa babu tashin matattu, babu mala’iku ko ruhohi. Amma Farisiyawa kuwa sun tsaya a kan cewa duk akwai.) ");
INSERT INTO hausa_vpl VALUES ("AC23_9","074_23_9","ACT","23","9","9","Aka yi babbar hayaniya. Waɗansu daga cikin malaman dokokin da suke Farisiyawa suka miƙe tsaye suka yi gardama mai ƙarfi suna cewa, “Ba mu sami wani laifi a wurin mutumin nan ba. A ce wani ruhu ko mala’ika ne ya yi masa magana fa?” ");
INSERT INTO hausa_vpl VALUES ("AC23_10","074_23_10","ACT","23","10","10","Gardamar kuwa ta yi tsanani har shugaban ƙungiyar sojan ya ji tsoro za su yayyage Bulus. Ya umarci sojoji su tafi su ƙwace shi ƙarfi da yaji daga wurinsu su kawo shi cikin barikin soja. ");
INSERT INTO hausa_vpl VALUES ("AC23_11","074_23_11","ACT","23","11","11","Kashegari da dare Ubangiji ya tsaya kusa da Bulus ya ce, “Ka yi ƙarfin hali! Don kamar yadda ka yi shaida game da ni a Urushalima, haka kuma lalle, za ka yi shaidata a Roma.” ");
INSERT INTO hausa_vpl VALUES ("AC23_12","074_23_12","ACT","23","12","12","Kashegari, Yahudawa suka ƙulla makirci suka kuma yi rantsuwa cewa ba za su ci ko sha ba sai sun kashe Bulus. ");
INSERT INTO hausa_vpl VALUES ("AC23_13","074_23_13","ACT","23","13","13","Fiye da mutane arba’in ne suka ƙulla wannan makirci. ");
INSERT INTO hausa_vpl VALUES ("AC23_14","074_23_14","ACT","23","14","14","Suka je wajen manyan firistoci da dattawa suka ce, “Mun yi babbar rantsuwa cewa ba za mu ci kome ba sai mun kashe Bulus. ");
INSERT INTO hausa_vpl VALUES ("AC23_15","074_23_15","ACT","23","15","15","Saboda haka, sai ku da Majalisa sai ku roƙi shugaban ƙungiyar sojan yă kawo shi a gabanku kamar kuna so ku ƙara samun cikakken bayani game da zancensa. Mu kuwa muna a shirye mu kashe shi kafin yă iso nan.” ");
INSERT INTO hausa_vpl VALUES ("AC23_16","074_23_16","ACT","23","16","16","Amma da ɗan ’yar’uwar Bulus ya ji wannan makirci, sai ya tafi cikin barikin soja ya gaya wa Bulus. ");
INSERT INTO hausa_vpl VALUES ("AC23_17","074_23_17","ACT","23","17","17","Sai Bulus ya kira ɗaya daga cikin jarumawan ya ce, “Ka kai wannan saurayi wurin shugaban ƙungiyar soja; yana da wani abin da zai faɗa masa.” ");
INSERT INTO hausa_vpl VALUES ("AC23_18","074_23_18","ACT","23","18","18","Saboda haka ya ɗauke shi ya kai wajen shugaban ƙungiyar sojan. Jarumin ya ce, “Bulus, ɗan kurkukun nan ya kira ni, ya roƙe ni in kawo wannan saurayi a wurinka domin yana da wani abin da zai faɗa maka.” ");
INSERT INTO hausa_vpl VALUES ("AC23_19","074_23_19","ACT","23","19","19","Sai shugaban ƙungiyar sojan ya kama hannun saurayin ya ja shi gefe, ya tambaye shi cewa, “Mene ne kake so ka gaya mini?” ");
INSERT INTO hausa_vpl VALUES ("AC23_20","074_23_20","ACT","23","20","20","Saurayin ya ce, “Yahudawa sun ƙulla za su roƙe ka ka kawo Bulus a gaban Majalisa gobe kamar suna neman ƙarin cikakken bayani game da Bulus. ");
INSERT INTO hausa_vpl VALUES ("AC23_21","074_23_21","ACT","23","21","21","Kada ka yarda da su, domin fiye da mutum arba’in daga cikinsu suna fakonsa. Sun yi rantsuwa ba za su ci ko sha ba sai sun kashe shi. Suna nan a shirye yanzu, suna jira ka amince da roƙonsu.” ");
INSERT INTO hausa_vpl VALUES ("AC23_22","074_23_22","ACT","23","22","22","Sai shugaban ƙungiyar sojan ya sallami saurayin ya kwaɓe shi ya ce, “Kada ka gaya wa kowa cewa ka faɗa mini wannan.” ");
INSERT INTO hausa_vpl VALUES ("AC23_23","074_23_23","ACT","23","23","23","Sai ya kira biyu daga cikin jarumawansa, ya umarce su cewa, “Ku shirya sojoji ɗari biyu, da masu hawan dawakai saba’in da kuma masu māsu ɗari biyu su tafi Kaisariya da ƙarfe tara na daren nan. ");
INSERT INTO hausa_vpl VALUES ("AC23_24","074_23_24","ACT","23","24","24","Ku shirya wa Bulus dawakai da zai hau don a kai shi wurin Gwamna Felis lafiya.” ");
INSERT INTO hausa_vpl VALUES ("AC23_25","074_23_25","ACT","23","25","25","Ya kuma rubuta wasiƙa kamar haka, ");
INSERT INTO hausa_vpl VALUES ("AC23_26","074_23_26","ACT","23","26","26","Kalaudiyus Lisiyas. Zuwa ga Mai Girma, Gwamna Felis. Gaisuwa. ");
INSERT INTO hausa_vpl VALUES ("AC23_27","074_23_27","ACT","23","27","27","Yahudawa sun kama wannan mutum suna kuma dab da kashe shi, amma na zo da sojojina na ƙwato shi, saboda na ji shi ɗan ƙasar Roma ne. ");
INSERT INTO hausa_vpl VALUES ("AC23_28","074_23_28","ACT","23","28","28","Na so in san abin da ya sa suke zarginsa, saboda haka na kawo shi a gaban Majalisarsu. ");
INSERT INTO hausa_vpl VALUES ("AC23_29","074_23_29","ACT","23","29","29","Na tarar cewa zargin da ake masa ya shafi waɗansu abubuwan da suka shafi dokarsu ne, amma ba wani zargi a kansa da ya isa kisa ko a daure shi. ");
INSERT INTO hausa_vpl VALUES ("AC23_30","074_23_30","ACT","23","30","30","Sa’ad da na sami labari cewa akwai wani makircin da aka ƙulla masa, sai na aika shi wurinka nan da nan. Na kuma umarci masu zarginsa su kai ƙararsu gare ka. ");
INSERT INTO hausa_vpl VALUES ("AC23_31","074_23_31","ACT","23","31","31","Saboda haka sojojin, don cika umarni, suka ɗauki Bulus da dad dare suka kawo shi har Antifatiris. ");
INSERT INTO hausa_vpl VALUES ("AC23_32","074_23_32","ACT","23","32","32","Kashegari suka bar masu hawan dawakai suka ci gaba da shi, yayinda sojojin suka koma barikin soja. ");
INSERT INTO hausa_vpl VALUES ("AC23_33","074_23_33","ACT","23","33","33","Sa’ad da masu hawan dawakai suka isa Kaisariya, sai suka ba wa gwamna wasiƙar suka kuma miƙa masa Bulus. ");
INSERT INTO hausa_vpl VALUES ("AC23_34","074_23_34","ACT","23","34","34","Gwamna ya karanta wasiƙar ya kuma tambaya ko daga wanda lardi ne ya fito. Da ya ji cewa shi daga Silisiya ne, ");
INSERT INTO hausa_vpl VALUES ("AC23_35","074_23_35","ACT","23","35","35","sai ya ce, “Zan ji batunka lokacin da masu zarginka suka iso.” Sa’an nan ya ba da umarni a kai Bulus a tsare shi a fadar Hiridus. ");
INSERT INTO hausa_vpl VALUES ("AC24_1","074_24_1","ACT","24","1","1","Bayan kwana biyar sai Ananiyas babban firist ya tafi Kaisariya tare da waɗansu daga cikin dattawa da kuma wani lauya mai suna Tertullus, suka kawo ƙararsu game da Bulus a gaban gwamna. ");
INSERT INTO hausa_vpl VALUES ("AC24_2","074_24_2","ACT","24","2","2","Sa’ad da aka shigo da Bulus, sai Tertullus ya shiga kai ƙararsa a gaban Felis yana cewa, “Mun daɗe muna zaman lafiya a ƙarƙashinka, hangen nesanka kuma ya kawo gyare-gyare a wannan ƙasa. ");
INSERT INTO hausa_vpl VALUES ("AC24_3","074_24_3","ACT","24","3","3","Ko’ina da kuma a kowace hanya, ya mafifici Felis, mun amince da wannan da godiya marar iyaka. ");
INSERT INTO hausa_vpl VALUES ("AC24_4","074_24_4","ACT","24","4","4","Amma don kada in ƙara gajiyar da kai, ina roƙonka ka yi haƙuri ka saurari ɗan taƙaitaccen jawabinmu. ");
INSERT INTO hausa_vpl VALUES ("AC24_5","074_24_5","ACT","24","5","5","“Mun tarar da wannan mutum fitinanne ne, yana tā-da-na-zaune-tsaye a tsakanin Yahudawa ko’ina a duniya. Shi shugaban ɗarikar Nazarawa ");
INSERT INTO hausa_vpl VALUES ("AC24_6","074_24_6","ACT","24","6","6","har ma ya yi ƙoƙari ya ƙazantar da haikali; shi ya sa muka kama shi. ");
INSERT INTO hausa_vpl VALUES ("AC24_8","074_24_8","ACT","24","8","8","Ta wurin bincika shi da kanka za ka gane gaskiyar game da dukan waɗannan zargin da muke kawo a kansa.” ");
INSERT INTO hausa_vpl VALUES ("AC24_9","074_24_9","ACT","24","9","9","Yahudawa ma suka goyi bayan zargin, suna tabbatar cewa waɗannan abubuwa haka suke. ");
INSERT INTO hausa_vpl VALUES ("AC24_10","074_24_10","ACT","24","10","10","Da gwamna ya yi masa alama yă yi magana, sai Bulus ya amsa ya ce, “Na san cewa ka yi shekaru da yawa kana mulki a wannan ƙasa; saboda haka ina farin ciki in kāre kaina. ");
INSERT INTO hausa_vpl VALUES ("AC24_11","074_24_11","ACT","24","11","11","Da sauƙi za ka iya tabbatar cewa, bai fi kwana goma sha biyu da suka wuce ne na tafi Urushalima, domin yin sujada ba. ");
INSERT INTO hausa_vpl VALUES ("AC24_12","074_24_12","ACT","24","12","12","Masu zargina ba su same ni ina gardama da kowa a haikali, ko kuma ina tā da hankalin jama’a a majami’u ko kuwa wani wuri dabam a cikin birni ba. ");
INSERT INTO hausa_vpl VALUES ("AC24_13","074_24_13","ACT","24","13","13","Ba kuwa za su iya tabbatar maka ƙarar da suke yi yanzu a kaina ba. ");
INSERT INTO hausa_vpl VALUES ("AC24_14","074_24_14","ACT","24","14","14","Amma na yarda cewa ina bauta wa Allah na kakanninmu a matsayin mai bin Hanyar da suke kira ɗarika. Na gaskata dukan abin da ya amince da Doka da yake kuma a rubuce cikin Annabawa, ");
INSERT INTO hausa_vpl VALUES ("AC24_15","074_24_15","ACT","24","15","15","ina kuma da irin bege ɗaya ga Allah yadda mutanen nan suke da shi, cewa akwai tashin matattu masu adalci da masu mugunta duka. ");
INSERT INTO hausa_vpl VALUES ("AC24_16","074_24_16","ACT","24","16","16","Saboda haka, ina ƙoƙari kullum in kasance da lamiri mai tsabta a gaban Allah da mutane. ");
INSERT INTO hausa_vpl VALUES ("AC24_17","074_24_17","ACT","24","17","17","“Bayan ’yan shekaru da dama da ba na nan, sai na dawo Urushalima don in kawo wa mutanena kyautai saboda matalauta in kuma yi sadaka. ");
INSERT INTO hausa_vpl VALUES ("AC24_18","074_24_18","ACT","24","18","18","Ni tsarkake ne sa’ad da suka same ni cikin filin haikalin ina yin haka. Babu taro tare da ni, ba kuwa ina tā da hankali ba. ");
INSERT INTO hausa_vpl VALUES ("AC24_19","074_24_19","ACT","24","19","19","Amma akwai waɗansu Yahudawa daga lardin Asiya, waɗanda ya kamata suna a nan a gabanka su kawo ƙara in suna da wani a kaina. ");
INSERT INTO hausa_vpl VALUES ("AC24_20","074_24_20","ACT","24","20","20","Ko kuwa waɗannan da suke a nan su faɗi laifin da suka same ni da shi sa’ad da na tsaya a gaban Majalisa, ");
INSERT INTO hausa_vpl VALUES ("AC24_21","074_24_21","ACT","24","21","21","sai ko wannan abu ɗaya kaɗai da na ɗaga murya na faɗi yayinda nake tsaye a gabansu cewa, ‘A game da tashin matattu ake mini shari’a a gabanku yau.’ ” ");
INSERT INTO hausa_vpl VALUES ("AC24_22","074_24_22","ACT","24","22","22","Sai Felis, wanda yake da cikakken sani game da Hanyar, ya ɗaga sauraron ƙarar. Ya ce, “In Lisiyas shugaban ƙungiyar soja ya iso, zan yanke muku shari’a.” ");
INSERT INTO hausa_vpl VALUES ("AC24_23","074_24_23","ACT","24","23","23","Ya yi wa jarumin umarni yă tsare Bulus amma yă ba shi ’yanci yă kuma bar abokansa su lura da bukatunsa. ");
INSERT INTO hausa_vpl VALUES ("AC24_24","074_24_24","ACT","24","24","24","Bayan ’yan kwanaki da dama sai Felis ya zo da matarsa Durusilla, mutuniyar Yahuda. Sai ya aika a zo da Bulus ya kuma saurare shi da yake magana game da bangaskiya cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("AC24_25","074_24_25","ACT","24","25","25","Da Bulus ya ci gaba jawabi a kan adalci, kamunkai da kuma hukunci mai zuwa, sai Felis ya tsorata ya ce, “Yanzu kam, ya isa haka! Kana iya tafi. In na sami zarafi, zan kira ka.” ");
INSERT INTO hausa_vpl VALUES ("AC24_26","074_24_26","ACT","24","26","26","A wani fanni yana sa rai cewa Bulus zai ba shi toshiyar baki, saboda haka ya yi ta aika a kira masa Bulus yă yi magana da shi. ");
INSERT INTO hausa_vpl VALUES ("AC24_27","074_24_27","ACT","24","27","27","Da shekaru biyu suka wuce, sai Forsiyus Festus, ya gāji Felis, amma domin Felis ya so yă biya wa Yahudawa bukata, sai ya bar Bulus a kurkuku. ");
INSERT INTO hausa_vpl VALUES ("AC25_1","074_25_1","ACT","25","1","1","Kwana uku bayan isowa a lardin, sai Festus ya haura daga Kaisariya zuwa Urushalima, ");
INSERT INTO hausa_vpl VALUES ("AC25_2","074_25_2","ACT","25","2","2","inda manyan firistoci da shugabannin Yahudawa suka bayyana a gabansa suka kuma gabatar da ƙararsu a kan Bulus. ");
INSERT INTO hausa_vpl VALUES ("AC25_3","074_25_3","ACT","25","3","3","Suka roƙi Festus a gaggauce a matsayin alfarma gare su, da yă sa a mai da Bulus Urushalima, gama sun ’yan kwanto su kashe shi a hanya. ");
INSERT INTO hausa_vpl VALUES ("AC25_4","074_25_4","ACT","25","4","4","Festus ya amsa ya ce, “Bulus yana tsare a Kaisariya, ni da kaina kuma zan je can ba da daɗewa ba. ");
INSERT INTO hausa_vpl VALUES ("AC25_5","074_25_5","ACT","25","5","5","Ku sa waɗansu daga cikin shugabanninku su tafi tare da ni su kawo ƙararsu a kan mutumin a can, in ya aikata wani laifi.” ");
INSERT INTO hausa_vpl VALUES ("AC25_6","074_25_6","ACT","25","6","6","Bayan ya yi kwanaki takwas ko goma tare da su, sai ya gangara zuwa Kaisariya, kashegari kuma ya kira a yi zaman kotu ya kuma umarta a kawo Bulus a gabansa. ");
INSERT INTO hausa_vpl VALUES ("AC25_7","074_25_7","ACT","25","7","7","Da Bulus ya bayyana, sai Yahudawan da suka gangaro daga Urushalima suka tsaya kewaye shi, suna kawo ƙarar masu tsanani da yawa a kansa, waɗanda ba su iya tabbatarwa ba. ");
INSERT INTO hausa_vpl VALUES ("AC25_8","074_25_8","ACT","25","8","8","Sa’an nan Bulus ya kāre kansa ya ce, “Ban aikata wani laifi game da dokokin Yahudawa ko game da haikali ko kuma game da Kaisar ba.” ");
INSERT INTO hausa_vpl VALUES ("AC25_9","074_25_9","ACT","25","9","9","Festus, da yake yana so yă yi wa Yahudawa alfarma, sai ya ce wa Bulus, “Ka yarda ka je Urushalima a yi maka shari’a a can a gabana a kan waɗannan zarge?” ");
INSERT INTO hausa_vpl VALUES ("AC25_10","074_25_10","ACT","25","10","10","Bulus ya amsa ya ce, “Yanzu ina tsaye a gaban kotun Kaisar, inda ya kamata a yi mini shari’a. Ban yi wani laifi ga Yahudawa ba, kai da kanka ma ka san da haka sarai. ");
INSERT INTO hausa_vpl VALUES ("AC25_11","074_25_11","ACT","25","11","11","In kuwa ina da wani laifin da ya isa kisa, ban ƙi in mutu ba. Amma in ƙarar da waɗannan Yahudawa suka kawo a kaina ba gaskiya ba ne, ba wanda yake da iko ya ba da ni a gare su. Na ɗaukaka ƙara zuwa gaban Kaisar!” ");
INSERT INTO hausa_vpl VALUES ("AC25_12","074_25_12","ACT","25","12","12","Bayan Festus ya yi shawara da majalisarsa sai ya ce, “Ka ɗaukaka ƙara zuwa gaban Kaisar. To, ga Kaisar kuwa za ka tafi!” ");
INSERT INTO hausa_vpl VALUES ("AC25_13","074_25_13","ACT","25","13","13","Bayan ’yan kwanaki sai Sarki Agiriffa da Bernis suka iso Kaisariya don su yi wa Festus gaisuwar bangirma. ");
INSERT INTO hausa_vpl VALUES ("AC25_14","074_25_14","ACT","25","14","14","Da yake za su yi kwanaki da dama a can, sai Festus ya tattauna batun Bulus da sarki. Ya ce, “Akwai mutumin da Felis ya bari a daure. ");
INSERT INTO hausa_vpl VALUES ("AC25_15","074_25_15","ACT","25","15","15","Sa’ad da na je Urushalima, manyan firistoci da dattawan Yahudawa suka kawo ƙara game da shi suka kuma nema a hukunta shi. ");
INSERT INTO hausa_vpl VALUES ("AC25_16","074_25_16","ACT","25","16","16","“Na gaya musu cewa ba al’adar Romawa ba ce a hukunta mutum kafin ya fuskanci masu ƙararsa ya kuma sami damar kāre kansa game da ƙararsu. ");
INSERT INTO hausa_vpl VALUES ("AC25_17","074_25_17","ACT","25","17","17","Da suka zo nan tare da ni, ban yi wani jinkiri ba, na kira zaman kotu kashegari kuma na umarta a kawo mutumin. ");
INSERT INTO hausa_vpl VALUES ("AC25_18","074_25_18","ACT","25","18","18","Sa’ad da masu zarginsa suka tashi tsaye don su yi magana, ba su zarge shi da wani laifin da na yi tsammani ba. ");
INSERT INTO hausa_vpl VALUES ("AC25_19","074_25_19","ACT","25","19","19","A maimako haka, sai suka kawo waɗansu ’yan maganganu game da addininsu da ba su yarda da shi ba da kuma game da wani Yesu da ya mutu wanda Bulus ya ce yana da rai. ");
INSERT INTO hausa_vpl VALUES ("AC25_20","074_25_20","ACT","25","20","20","Na rasa yadda zan bincike irin abubuwan nan; saboda haka na yi tambaya ko zai yarda ya tafi Urushalima a yi masa shari’a a can game da waɗannan zargi. ");
INSERT INTO hausa_vpl VALUES ("AC25_21","074_25_21","ACT","25","21","21","Da Bulus ya ɗaukaka ƙara zuwa gaban Babban Sarki sai na umarta a tsare shi har kafin in aika shi zuwa ga Kaisar.” ");
INSERT INTO hausa_vpl VALUES ("AC25_22","074_25_22","ACT","25","22","22","Sai Agiriffa ya ce wa Festus, “Ni ma zan so in saurari mutumin da kaina.” Sai ya amsa ya ce, “Za ka kuwa ji shi gobe.” ");
INSERT INTO hausa_vpl VALUES ("AC25_23","074_25_23","ACT","25","23","23","Kashegari Agiriffa da Bernis suka yi shiga irin ta sarauta suka shiga ɗakin jama’a tare da manyan sojoji da manyan mutanen birni. Da umarnin Festus, sai aka shigo da Bulus. ");
INSERT INTO hausa_vpl VALUES ("AC25_24","074_25_24","ACT","25","24","24","Sai Festus ya ce, “Sarki Agiriffa, da kuma dukan waɗanda suke tare da mu, kun ga wannan mutum! Dukan jama’ar Yahudawa sun kawo mini kararsa a Urushalima da kuma a nan Kaisariya, suna kururuwa suna cewa bai kamata a bar shi da rai ba. ");
INSERT INTO hausa_vpl VALUES ("AC25_25","074_25_25","ACT","25","25","25","Ban same shi da wani laifin da ya isa kisa ba, amma saboda ya ɗaukaka ƙararsa zuwa gaban Babban Sarki sai na yanke shawara in aika da shi Roma. ");
INSERT INTO hausa_vpl VALUES ("AC25_26","074_25_26","ACT","25","26","26","Ba ni da wata tabbatacciyar maganar da zan rubuta wa Mai Girma game da shi. Saboda haka na kawo shi a gabanku duka, musamman a gabanka, Sarki Agiriffa, saboda a sakamakon wannan bincike zan iya samun abin da zan rubuta. ");
INSERT INTO hausa_vpl VALUES ("AC25_27","074_25_27","ACT","25","27","27","Don a ganina wauta ce a aika da ɗan kurkuku ba tare da an nuna zargin da ake yi a kansa ba.” ");
INSERT INTO hausa_vpl VALUES ("AC26_1","074_26_1","ACT","26","1","1","Sai Agiriffa ya ce wa Bulus, “An ba ka izini ka yi magana.” Saboda haka Bulus ya yi alama da hannunsa ya fara kāriyarsa. ");
INSERT INTO hausa_vpl VALUES ("AC26_2","074_26_2","ACT","26","2","2","Ya ce, “Sarki Agiriffa, na yi sa’a da na tsaya a gabanka yau yayinda nake kāriyata game da dukan zargin Yahudawa, ");
INSERT INTO hausa_vpl VALUES ("AC26_3","074_26_3","ACT","26","3","3","musamman ma domin ka saba sosai da dukan al’adun Yahudawa da kuma maganganunsu. Saboda haka ina roƙonka ka saurare ni da haƙuri. ");
INSERT INTO hausa_vpl VALUES ("AC26_4","074_26_4","ACT","26","4","4","“Yahudawa duk sun san yadda na yi rayuwa tun ina yaro, daga farkon rayuwata a ƙasarmu da kuma a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("AC26_5","074_26_5","ACT","26","5","5","Sun san ni tun da daɗewa za su kuwa shaida, in suna so, cewa bisa ga ɗarikar addininmu mafi tsanani, na yi rayuwar Bafarisiye ne. ");
INSERT INTO hausa_vpl VALUES ("AC26_6","074_26_6","ACT","26","6","6","Yanzu kuwa saboda begena cikin abin da Allah ya yi wa kakanninmu alkawari ne, ake mini shari’a yau. ");
INSERT INTO hausa_vpl VALUES ("AC26_7","074_26_7","ACT","26","7","7","Wannan shi ne alkawarin da kabilanmu goma sha biyu suke bege su ga cikawarsa, yayinda suke bauta wa Allah da himma dare da rana. Ya Sarki, saboda wannan bege ne fa Yahudawa suke zargena. ");
INSERT INTO hausa_vpl VALUES ("AC26_8","074_26_8","ACT","26","8","8","Don me wani a cikinku zai yi shakka cewa Allah yana tā da matattu? ");
INSERT INTO hausa_vpl VALUES ("AC26_9","074_26_9","ACT","26","9","9","“Ni ma a dā na tabbata cewa ya kamata in yi duk abin da zan iya yi domin in yi gāba da sunan Yesu Banazare. ");
INSERT INTO hausa_vpl VALUES ("AC26_10","074_26_10","ACT","26","10","10","Abin da na yi ke nan a Urushalima. Da izinin manyan firistoci na sa tsarkaka da yawa a kurkuku, sa’ad da kuma ake kashe su, nakan ka da ƙuri’ata gāba da su. ");
INSERT INTO hausa_vpl VALUES ("AC26_11","074_26_11","ACT","26","11","11","Sau da dama nakan bi majami’a-majami’a, in sa a yi musu hukunci. Na kuma yi ƙoƙarin tilasta su su yi saɓo. Don kuma tsananin fushi da su, sai da na fafare su har waɗansu garuruwa na ƙetaren iyaka, ina tsananta musu. ");
INSERT INTO hausa_vpl VALUES ("AC26_12","074_26_12","ACT","26","12","12","“A cikin irin tafiye-tafiyen nan ne ina kan hanya zuwa Damaskus tare da izini daga manyan firistoci. ");
INSERT INTO hausa_vpl VALUES ("AC26_13","074_26_13","ACT","26","13","13","Da tsakar rana, ya sarki, sa’ad da nake kan hanya, sai na ga wani haske daga sama, fiye da hasken rana, yana haskakawa kewaye da ni da abokan tafiyata. ");
INSERT INTO hausa_vpl VALUES ("AC26_14","074_26_14","ACT","26","14","14","Dukanmu muka fāɗi ƙasa, na kuwa ji wata murya tana ce mini da harshen Arameyik, ‘Shawulu, Shawulu, don me kake tsananta mini? Yana da wuya ka shuri tsinken tsokanar dabba.’ ");
INSERT INTO hausa_vpl VALUES ("AC26_15","074_26_15","ACT","26","15","15","“Sai na yi tambaya na ce, ‘Wane ne kai, ya Ubangiji?’ “Ubangiji ya ce, ‘Ni ne Yesu wanda kake tsananta wa. ");
INSERT INTO hausa_vpl VALUES ("AC26_16","074_26_16","ACT","26","16","16","Yanzu ka tashi, ka tsaya da ƙafafunka. Na bayyana a gare ka don in naɗa ka bawa da kuma mai shaidar abin da ka gani game da ni da kuma abin da zan nuna maka. ");
INSERT INTO hausa_vpl VALUES ("AC26_17","074_26_17","ACT","26","17","17","Zan tsirar da kai daga mutanenka da kuma daga Al’ummai. Ina aikan ka zuwa gare su domin ");
INSERT INTO hausa_vpl VALUES ("AC26_18","074_26_18","ACT","26","18","18","ka buɗe idanunsu su kuwa juyo daga duhu zuwa haske, daga mulkin Shaiɗan kuma zuwa wurin Allah, domin su sami gafarar zunubai da kuma matsayi a cikin waɗanda aka tsarkake ta wurin bangaskiya a cikina.’ ");
INSERT INTO hausa_vpl VALUES ("AC26_19","074_26_19","ACT","26","19","19","“Saboda haka fa, Sarki Agiriffa, ban yi rashin biyayya ga wahayin nan daga sama ba. ");
INSERT INTO hausa_vpl VALUES ("AC26_20","074_26_20","ACT","26","20","20","Da farko ga waɗanda suke a Damaskus, sa’an nan ga waɗanda suke a Urushalima da kuma cikin dukan Yahudiya, da kuma ga Al’ummai su ma, na yi wa’azi don su tuba su juyo ga Allah su kuma tabbatar da tubansu ta wurin ayyukansu. ");
INSERT INTO hausa_vpl VALUES ("AC26_21","074_26_21","ACT","26","21","21","Shi ya sa Yahudawa suka kama ni a filin haikali suka kuma yi ƙoƙarin kashe ni. ");
INSERT INTO hausa_vpl VALUES ("AC26_22","074_26_22","ACT","26","22","22","Amma na sami taimakon Allah har yă zuwa yau. Yanzu ga ni a tsaye a nan, ina shaida ga babba da yaro. Ba na faɗin kome fiye da abin da annabawa da Musa suka ce zai faru, ");
INSERT INTO hausa_vpl VALUES ("AC26_23","074_26_23","ACT","26","23","23","cewa Kiristi zai sha wahala, kuma a matsayin wanda yake na fari da zai tashi daga matattu, zai yi shelar haske ga mutanensa da kuma Al’ummai.” ");
INSERT INTO hausa_vpl VALUES ("AC26_24","074_26_24","ACT","26","24","24","A nan ne fa Festus ya tsai da kāriyar Bulus. Ya yi ihu ya ce, “Bulus! Kai dai ruɗaɗɗe ne, yawan karatunka yana juya maka kai.” ");
INSERT INTO hausa_vpl VALUES ("AC26_25","074_26_25","ACT","26","25","25","Bulus ya amsa ya ce, “Ba na hauka, ya mafifici Festus. Abin da nake faɗi gaskiya ne da kuma mai kyau. ");
INSERT INTO hausa_vpl VALUES ("AC26_26","074_26_26","ACT","26","26","26","Sarki ya san waɗannan abubuwa, ina kuma iya yin magana da shi a sake. Na tabbata cewa ba ɗaya daga cikin waɗannan da ya kuɓuce saninsa, domin ba a ɓoye aka yi shi ba. ");
INSERT INTO hausa_vpl VALUES ("AC26_27","074_26_27","ACT","26","27","27","Sarki Agiriffa ka gaskata da annabawa? Na san ka gaskata.” ");
INSERT INTO hausa_vpl VALUES ("AC26_28","074_26_28","ACT","26","28","28","Sai Agiriffa ya ce wa Bulus, “Kana tsammani cewa a cikin ɗan ƙanƙanin lokaci kana so ka mai da ni Kirista?” ");
INSERT INTO hausa_vpl VALUES ("AC26_29","074_26_29","ACT","26","29","29","Bulus ya amsa ya ce, “Ko a ɗan lokaci, ko a lokaci mai yawa, ina addu’a ga Allah cewa, ba kai kaɗai ba amma duk waɗanda suke saurare ni a yau su zama abin da nake, sai dai ban da sarƙoƙin nan.” ");
INSERT INTO hausa_vpl VALUES ("AC26_30","074_26_30","ACT","26","30","30","Sai sarki ya tashi, haka kuma gwamna da Bernis da kuma waɗanda suke zaune tare da su. ");
INSERT INTO hausa_vpl VALUES ("AC26_31","074_26_31","ACT","26","31","31","Suka bar ɗakin, kuma yayinda suke magana da juna, sai suka ce, “Wannan mutum ba ya yin kome da ya isa kisa ko dauri.” ");
INSERT INTO hausa_vpl VALUES ("AC26_32","074_26_32","ACT","26","32","32","Sai Agiriffa ya ce wa Festus, “Da ba don wannan mutum ya ɗaukaka ƙara zuwa gaban Kaisar ba da an sake shi.” ");
INSERT INTO hausa_vpl VALUES ("AC27_1","074_27_1","ACT","27","1","1","Sa’ad da aka yanke shawara cewa za mu tashi a jirgin ruwa zuwa Italiya, sai aka danƙa Bulus da waɗansu ’yan kurkuku a hannun wani jarumin mai suna Juliyos, wanda yake na Bataliyar Babban Sarki. ");
INSERT INTO hausa_vpl VALUES ("AC27_2","074_27_2","ACT","27","2","2","Muka shiga jirgin ruwa daga Andiramitiyum wanda yake shirin tashi zuwa tasoshin da suke bakin tekun lardin Asiya, sai muka kama tafiya. Aristarkus, mutumin Makidoniya daga Tessalonika, yana tare da mu. ");
INSERT INTO hausa_vpl VALUES ("AC27_3","074_27_3","ACT","27","3","3","Kashegari muka sauka a Sidon; Juliyos kuwa, cikin alheri ga Bulus, ya bar shi yă je wajen abokansa domin su biya masa bukatunsa. ");
INSERT INTO hausa_vpl VALUES ("AC27_4","074_27_4","ACT","27","4","4","Daga can kuma muka sāke kama tafiya muka zaga ta bayan tsibirin Saifurus saboda iska tana gāba da mu. ");
INSERT INTO hausa_vpl VALUES ("AC27_5","074_27_5","ACT","27","5","5","Sa’ad da muka ƙetare tekun da yake sassan gaɓar Silisiya da Famfiliya sai muka sauka a Mira ta Lisiya. ");
INSERT INTO hausa_vpl VALUES ("AC27_6","074_27_6","ACT","27","6","6","A can jarumin ya sami wani jirgin ruwan Alekzandariyan da za shi Italiya sai ya sa mu a ciki. ");
INSERT INTO hausa_vpl VALUES ("AC27_7","074_27_7","ACT","27","7","7","Tafiyar ta ɗauki kwanaki da yawa muna yi kaɗan-kaɗan da ƙyar muka iso kusa da gaɓar Kinidus. Da iskar ta hana mu ci gaba, sai muka bi ta bayan tsibirin Kirit ɗaura da Salmone. ");
INSERT INTO hausa_vpl VALUES ("AC27_8","074_27_8","ACT","27","8","8","Muka ci gaba a gefen gaɓar da ƙyar har muka iso wani wurin da ake kira Kyakkyawan Mafaka, kusa da garin Laseya. ");
INSERT INTO hausa_vpl VALUES ("AC27_9","074_27_9","ACT","27","9","9","An riga an ɓata lokaci da yawa, tafiya kuwa ta riga ta zama da hatsari domin a lokacin Azumi ya riga ta wuce. Saboda haka Bulus ya gargaɗe su, ");
INSERT INTO hausa_vpl VALUES ("AC27_10","074_27_10","ACT","27","10","10","ya ce, “Mutane, ina gani tafiyarmu za tă zama da masifa ta kuma kawo babbar hasara ga jirgin ruwan da kaya, da kuma ga rayukanmu ma.” ");
INSERT INTO hausa_vpl VALUES ("AC27_11","074_27_11","ACT","27","11","11","Amma jarumin, a maimakon ya saurari abin da Bulus ya ce, sai ya bi shawarar matuƙi da kuma mai jirgin ruwan. ");
INSERT INTO hausa_vpl VALUES ("AC27_12","074_27_12","ACT","27","12","12","Da yake tashar jirgin ruwan ba tă dace a ci damina a can ba, yawanci suka ba yanke shawara cewa mu ci gaba da tafiya, da bege za mu kai Funis mu ci damina a can. Wannan tashar jirgin ruwa ne a Kirit, tana fuskantar kudu maso yamma da kuma arewa maso yamma. ");
INSERT INTO hausa_vpl VALUES ("AC27_13","074_27_13","ACT","27","13","13","Da iska ta fara busowa daga kudu a hankali, sai suka yi tsammani sun sami abin da suke nema; saboda haka suka janye ƙugiyar jirgin ruwa suka bi ta gefen tsibirin Kirit. ");
INSERT INTO hausa_vpl VALUES ("AC27_14","074_27_14","ACT","27","14","14","Ba a jima ba, sai ga wata guguwar iska mai ƙarfin da ake kira “’Yar arewa maso gabas,” ta buga daga tsibirin. ");
INSERT INTO hausa_vpl VALUES ("AC27_15","074_27_15","ACT","27","15","15","Iskar ta ci ƙarfin jirgin ruwan har ya kāsa fuskantar iskar; saboda haka muka sallamar mata tă yi ta tura mu. ");
INSERT INTO hausa_vpl VALUES ("AC27_16","074_27_16","ACT","27","16","16","Da muka bi ta bayan wani ɗan tsibirin da ake kira Kauda, da ƙyar muka jawo ɗan ƙaramin jirgin kusa da jirgin. ");
INSERT INTO hausa_vpl VALUES ("AC27_17","074_27_17","ACT","27","17","17","Da mutanen suka jawo shi cikin babban jirgin ruwan, sai suka sa igiyoyi ta ƙarƙashin jirgin ruwan kanta don su ɗaɗɗaura shi. Don gudun kada a fyaɗa mu da yashin gaɓar Sirtis, sai suka saukar da ƙugiyar jirgin ruwan, suka bari aka yi ta tura jirgin haka. ");
INSERT INTO hausa_vpl VALUES ("AC27_18","074_27_18","ACT","27","18","18","Haka muka yi ta shan bugun guguwar hadarin nan kashegari suka fara jajjefar da kayan da jirgin yake ɗauke da su a cikin teku. ");
INSERT INTO hausa_vpl VALUES ("AC27_19","074_27_19","ACT","27","19","19","A rana ta uku, da hannuwansu suka jefar da kayan aikin jirgin ruwan a cikin teku. ");
INSERT INTO hausa_vpl VALUES ("AC27_20","074_27_20","ACT","27","20","20","Da dai aka yi kwana da kwanaki ba a ga rana ko taurari ba guguwar iska kuma ta ci gaba da bugowa, a ƙarshe muka fid da zuciya za mu tsira. ");
INSERT INTO hausa_vpl VALUES ("AC27_21","074_27_21","ACT","27","21","21","Bayan mutanen sun daɗe ba su ci abinci ba, Bulus ya miƙe tsaye a gabansu ya ce, “Mutane, da kun ji shawarata na kada ku tashi daga Kirit, da ba ku fāɗa wannan masifa da hasara ba. ");
INSERT INTO hausa_vpl VALUES ("AC27_22","074_27_22","ACT","27","22","22","Amma yanzu ina ƙarfafa ku ku yi ƙarfin hali, domin ba ɗayanku da zai rasa ransa; jirgin ruwan ne kaɗai zai hallaka. ");
INSERT INTO hausa_vpl VALUES ("AC27_23","074_27_23","ACT","27","23","23","Jiya da dare wani mala’ikan Allahn da nake nasa nake kuma bauta wa ya tsaya kusa da ni ");
INSERT INTO hausa_vpl VALUES ("AC27_24","074_27_24","ACT","27","24","24","ya ce, ‘Kada ka ji tsoro, Bulus. Lalle za ka tsaya a gaban Kaisar a yi maka shari’a; Allah kuma cikin alherinsa ya ba ka dukan rayukan mutanen da suke tafiya tare da kai.’ ");
INSERT INTO hausa_vpl VALUES ("AC27_25","074_27_25","ACT","27","25","25","Saboda haka ku yi ƙarfin hali, ku jama’a, gama gaskata Allah a kan cewa yadda aka faɗa mini ɗin nan, haka zai faru. ");
INSERT INTO hausa_vpl VALUES ("AC27_26","074_27_26","ACT","27","26","26","Duk da haka, dole a fyaɗa mu a wani tsibiri.” ");
INSERT INTO hausa_vpl VALUES ("AC27_27","074_27_27","ACT","27","27","27","A dare na goma sha huɗu iska dai tana ta korarmu a Tekun Adiriyatik, wajen tsakar dare sai masu tuƙin jirgin suka zaci sun yi kusa da ƙasa. ");
INSERT INTO hausa_vpl VALUES ("AC27_28","074_27_28","ACT","27","28","28","Sai suka gwada zurfin ruwan suka ga ya kai ƙafa ɗari da ashirin. Bayan ɗan lokaci kaɗan suka sāke gwadawa suka ga zurfin ya kai ƙafa tasa’in. ");
INSERT INTO hausa_vpl VALUES ("AC27_29","074_27_29","ACT","27","29","29","Don gudun kada a fyaɗa mu a kan duwatsu, sai suka saki ƙugiyoyin jirgin guda huɗu daga bayan jirgin suka yi fata gari ya waye. ");
INSERT INTO hausa_vpl VALUES ("AC27_30","074_27_30","ACT","27","30","30","Cikin ƙoƙarin tserewa daga jirgin, sai masu tuƙin jirgin suka saukar da ɗan ƙaramin jirgin ruwan cikin tekun, suka yi kamar za su saki waɗansu ƙugiyoyi daga sashen gaba na babban jirgin ne. ");
INSERT INTO hausa_vpl VALUES ("AC27_31","074_27_31","ACT","27","31","31","Sai Bulus ya ce wa jarumin da kuma sojojin, “In mutanen nan ba su tsaya a cikin jirgin nan ba, ba za ku tsira ba.” ");
INSERT INTO hausa_vpl VALUES ("AC27_32","074_27_32","ACT","27","32","32","Sai sojojin suka yayyanke igiyoyin da suke riƙe da ɗan ƙaramin jirgin, suka bar shi ya bi ruwa. ");
INSERT INTO hausa_vpl VALUES ("AC27_33","074_27_33","ACT","27","33","33","Kafin gari ya waye Bulus ya roƙe su duka su ci abinci. Ya ce, “Kwana goma sha huɗu ke nan, kuna zama cikin zulumi kun kuma kasance ba abinci, ba ku ci kome ba. ");
INSERT INTO hausa_vpl VALUES ("AC27_34","074_27_34","ACT","27","34","34","Ina roƙonku yanzu ku ci abinci. Kuna bukatarsa don ku rayu. Ba ɗayanku da zai rasa ko gashin kansa guda ɗaya.” ");
INSERT INTO hausa_vpl VALUES ("AC27_35","074_27_35","ACT","27","35","35","Bayan da ya faɗi haka, sai ya ɗauki burodi ya yi godiya ga Allah a gabansu duka. Sa’an nan ya gutsuttsura ya fara ci. ");
INSERT INTO hausa_vpl VALUES ("AC27_36","074_27_36","ACT","27","36","36","Dukansu kuwa suka sami ƙarfafawa, suka kuma ci abinci. ");
INSERT INTO hausa_vpl VALUES ("AC27_37","074_27_37","ACT","27","37","37","Dukanmu a jirgin kuwa mutane 276 ne. ");
INSERT INTO hausa_vpl VALUES ("AC27_38","074_27_38","ACT","27","38","38","Sa’ad da suka ci iyakar abin da suke so, sai suka rage nauyin jirgin ta wurin zubar da hatsin a cikin tekun. ");
INSERT INTO hausa_vpl VALUES ("AC27_39","074_27_39","ACT","27","39","39","Da gari ya waye, ba su gane ƙasar da suke ba, amma suka ga wani lungu da gaci mai yashi, sai suka yanke shawara su kai jirgin can in za su iya. ");
INSERT INTO hausa_vpl VALUES ("AC27_40","074_27_40","ACT","27","40","40","Da suka yanke ƙugiyoyin, sai suka bar su a cikin teku a lokaci guda kuma suka ɓalle maɗaurin abin juya jirgin. Sai suka tā da filafilan gaban jirgin daidai yadda iska za tă tura shi gaba, sa’an nan suka nufi gaci. ");
INSERT INTO hausa_vpl VALUES ("AC27_41","074_27_41","ACT","27","41","41","Amma jirgin ruwan ya shiga yashi ya kafe. Kan jirgin ya shiga cikin yashin ya kāsa motsi, sai jirgin ya fara farfashewa ta baya saboda haukan raƙuman ruwa. ");
INSERT INTO hausa_vpl VALUES ("AC27_42","074_27_42","ACT","27","42","42","Sojojin suka yi niyya su kakkashe ’yan kurkukun don hana waninsu yă yi iyo yă tsere. ");
INSERT INTO hausa_vpl VALUES ("AC27_43","074_27_43","ACT","27","43","43","Amma jarumin ya so yă ceci ran Bulus, sai ya hana su aiwatar da niyyarsu. Ya kuma yi umarni duk waɗanda suka iya ruwa su fara fāɗawa zuwa gaci. ");
INSERT INTO hausa_vpl VALUES ("AC27_44","074_27_44","ACT","27","44","44","Sauran kuma su bi katakai zuwa can ko kuma a kan tarkacen jirgin ruwan. Ta haka kowa ya kai bakin teku lafiya. ");
INSERT INTO hausa_vpl VALUES ("AC28_1","074_28_1","ACT","28","1","1","Bayan da muka kai bakin tekun lafiya, sai muka tarar cewa sunan tsibirin Malta ne. ");
INSERT INTO hausa_vpl VALUES ("AC28_2","074_28_2","ACT","28","2","2","Mutanen tsibirin kuwa suka nuna mana babban alheri. Suka hura wuta suka marabce mu duka saboda ana ruwan sama da kuma sanyi. ");
INSERT INTO hausa_vpl VALUES ("AC28_3","074_28_3","ACT","28","3","3","Bulus ya tattara tarin itace, yayinda kuma yake sa itacen a wuta, sai maciji ya ɓullo saboda zafi, ya dāfe a hannunsa. ");
INSERT INTO hausa_vpl VALUES ("AC28_4","074_28_4","ACT","28","4","4","Da mutanen tsibirin suka ga macijin yana lilo a hannunsa, sai suka ce wa juna “Lalle, wannan mutum mai kisankai ne; gama ko da yake ya tsira daga teku, Adalci bai bar shi ya rayu ba.” ");
INSERT INTO hausa_vpl VALUES ("AC28_5","074_28_5","ACT","28","5","5","Amma Bulus ya karkaɗe macijin a cikin wuta, bai kuwa ji wani ciwo ba. ");
INSERT INTO hausa_vpl VALUES ("AC28_6","074_28_6","ACT","28","6","6","Mutanen kuma suka yi zato zai kumbura ko kuma nan da nan zai fāɗi matacce, amma da aka daɗe ba su ga wani abu ya faru da shi ba, sai suka sāke ra’ayi suka ce shi wani allah ne. ");
INSERT INTO hausa_vpl VALUES ("AC28_7","074_28_7","ACT","28","7","7","Akwai wani filin nan kusa wanda yake na Fubiliyus, babban shugaban tsibirin. Shi ne ya karɓe mu a gidansa da alheri ya kuma ciyar da mu har kwana uku. ");
INSERT INTO hausa_vpl VALUES ("AC28_8","074_28_8","ACT","28","8","8","Mahaifinsa kuwa yana kwanciya a gado yana fama da zazzaɓi da atuni. Bulus ya shiga ciki don yă gan shi, bayan ya yi masa addu’a, sai ya ɗibiya masa hannuwa ya warkar da shi. ");
INSERT INTO hausa_vpl VALUES ("AC28_9","074_28_9","ACT","28","9","9","Sa’ad da wannan ya faru, sauran marasa lafiya a tsibirin suka zo aka kuma warkar da su. ");
INSERT INTO hausa_vpl VALUES ("AC28_10","074_28_10","ACT","28","10","10","Suka girmama mu ta kowane hali da muka shirya za mu tashi, sai suka ba mu abubuwan da muke bukata. ");
INSERT INTO hausa_vpl VALUES ("AC28_11","074_28_11","ACT","28","11","11","Bayan wata uku sai muka tashi a wani jirgin ruwan da ya ci damina a tsibirin. Jirgin ruwa kuwa na Alekzandariya ne yana da siffar tagwayen allolin Kasto da Follus. ");
INSERT INTO hausa_vpl VALUES ("AC28_12","074_28_12","ACT","28","12","12","Muka isa Sirakus a can muka yi kwana uku. ");
INSERT INTO hausa_vpl VALUES ("AC28_13","074_28_13","ACT","28","13","13","Daga can muka tashi muka isa Regiyum. Kashegari iskar kudu ta taso, kashegari kuma muka kai Futeyoli. ");
INSERT INTO hausa_vpl VALUES ("AC28_14","074_28_14","ACT","28","14","14","A can muka tarar da waɗansu ’yan’uwa waɗanda suka gayyaci mu mu yi mako ɗaya da su. Da haka dai muka kai Roma. ");
INSERT INTO hausa_vpl VALUES ("AC28_15","074_28_15","ACT","28","15","15","’Yan’uwan da suke can sun sami labari cewa muna zuwa, sai suka tashi tun daga Kasuwar Affiyus da Masauƙi Uku don su tarye mu. Da ganin mutanen nan sai Bulus ya gode wa Allah ya kuma sami ƙarfafawa. ");
INSERT INTO hausa_vpl VALUES ("AC28_16","074_28_16","ACT","28","16","16","Da muka isa Roma, sai aka yarda wa Bulus yă zauna shi kaɗai, tare da sojan da zai yi gadinsa. ");
INSERT INTO hausa_vpl VALUES ("AC28_17","074_28_17","ACT","28","17","17","Bayan kwana uku sai ya kira taron shugabannin Yahudawa. Da suka taru, Bulus ya ce musu, “’Yan’uwana, ko da yake ban yi wa mutanenmu wani laifi ba ko kuma wani abu game da al’adun kakanninmu, aka kama ni a Urushalima aka kuma ba da ni ga Romawa. ");
INSERT INTO hausa_vpl VALUES ("AC28_18","074_28_18","ACT","28","18","18","Suka tuhume ni suka kuma so su sake ni, domin ba a same ni da wani laifin da ya cancanci kisa ba. ");
INSERT INTO hausa_vpl VALUES ("AC28_19","074_28_19","ACT","28","19","19","Amma da Yahudawa suka ƙi, sai ya zama mini dole in ɗaukaka ƙara zuwa gaban Kaisar ba don ina da wani zargin da zan kawo game da mutanena ba. ");
INSERT INTO hausa_vpl VALUES ("AC28_20","074_28_20","ACT","28","20","20","Saboda wannan ne na nemi in gan ku in kuma yi magana da ku. Saboda begen Isra’ila ne, nake a daure da wannan sarƙa.” ");
INSERT INTO hausa_vpl VALUES ("AC28_21","074_28_21","ACT","28","21","21","Suka amsa cewa, “Ba mu sami wani wasiƙa daga Yahudiya game da kai ba, kuma ba kowa daga cikin ’yan’uwan da suka zo daga can ya kawo wani labari ko ya faɗi wani mummuna abu game da kai. ");
INSERT INTO hausa_vpl VALUES ("AC28_22","074_28_22","ACT","28","22","22","Amma muna so mu ji ra’ayinka, gama mun san cewa mutane ko’ina suna muguwar magana a kan wannan ɗarikar.” ");
INSERT INTO hausa_vpl VALUES ("AC28_23","074_28_23","ACT","28","23","23","Suka shirya su sadu da Bulus wata rana, suka ma zo da yawa fiye da dā a wurin da Bulus yake zama. Daga safe har zuwa yamma ya yi ta yin musu bayani, ya kuma shaida musu mulkin Allah yana ƙoƙarin rinjayarsu game da Yesu daga Dokar Musa da kuma daga Annabawa. ");
INSERT INTO hausa_vpl VALUES ("AC28_24","074_28_24","ACT","28","24","24","Waɗansu suka rinjayu da abin da ya faɗa, amma waɗansu suka ba su gaskata ba. ");
INSERT INTO hausa_vpl VALUES ("AC28_25","074_28_25","ACT","28","25","25","Suka kāsa yarda da juna suka fara watsewa bayan Bulus ya yi wannan magana guda cewa, “Ruhu Mai Tsarki ya faɗa wa kakannin-kakanninku gaskiya sa’ad da ya ce ta bakin annabi Ishaya cewa, ");
INSERT INTO hausa_vpl VALUES ("AC28_26","074_28_26","ACT","28","26","26","“ ‘Je ka wurin mutanen nan ka ce, “Za ku yi ta ji amma ba za ku fahimta ba; za ku yi ta dubawa, amma ba za ku gani ba.” ");
INSERT INTO hausa_vpl VALUES ("AC28_27","074_28_27","ACT","28","27","27","Gama zuciyar mutanen nan ta yi tauri; da ƙyar suke ji da kunnuwansu, sun kuma rufe idanunsu. In ba haka ba za su iya gani da idanunsu, su ji da kunnuwansu, su fahimta a zukatansu, su kuma juyo, in kuwa warkar da su.’ ");
INSERT INTO hausa_vpl VALUES ("AC28_28","074_28_28","ACT","28","28","28","“Saboda haka na so ku san cewa an aika da ceton Allah ga Al’ummai, za su kuwa saurara!” ");
INSERT INTO hausa_vpl VALUES ("AC28_30","074_28_30","ACT","28","30","30","Shekaru biyu cif Bulus ya zauna a can a gidansa na haya yana marabtar duk wanda ya je wurinsa. ");
INSERT INTO hausa_vpl VALUES ("AC28_31","074_28_31","ACT","28","31","31","Ya yi wa’azin mulkin Allah yana kuma koyarwa game da Ubangiji Yesu Kiristi, gabagadi ba tare da wani abu ya hana shi ba.");
INSERT INTO hausa_vpl VALUES ("RM1_1","075_1_1","ROM","1","1","1","Bulus, bawan Kiristi Yesu, kirayaye don yă zama manzo, keɓaɓɓe kuma domin bisharar Allah. ");
INSERT INTO hausa_vpl VALUES ("RM1_2","075_1_2","ROM","1","2","2","Bisharar da Allah ya yi alkawari tuntuni ta bakin annabawansa a cikin Nassosi Masu Tsarki ");
INSERT INTO hausa_vpl VALUES ("RM1_3","075_1_3","ROM","1","3","3","game da Ɗansa. Wanda bisa ga mutuntakarsa, zuriyar Dawuda ne. ");
INSERT INTO hausa_vpl VALUES ("RM1_4","075_1_4","ROM","1","4","4","Wanda bisa ga Ruhun tsarki, an shaida shi da iko cewa shi Ɗan Allah ne ta wurin tashinsa daga matattu. Wannan bishara kuwa game da Yesu Kiristi Ubangijinmu ne. ");
INSERT INTO hausa_vpl VALUES ("RM1_5","075_1_5","ROM","1","5","5","Ta wurinsa da kuma saboda sunansa, muka sami alheri muka kuma zama manzanni don mu kira mutane daga cikin dukan Al’ummai zuwa ga biyayyar da take zuwa daga bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("RM1_6","075_1_6","ROM","1","6","6","Ku ma kuna cikin waɗanda aka kira ku zama na Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("RM1_7","075_1_7","ROM","1","7","7","Wannan wasiƙa ce zuwa ga dukanku da kuke a Roma waɗanda Allah yake ƙauna, waɗanda kuma ya kira domin su zama tsarkaka. Alheri da salama daga Allah Ubanmu da kuma daga Ubangiji Yesu Kiristi, su kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("RM1_8","075_1_8","ROM","1","8","8","Da farko, ina gode wa Allahna ta wurin Yesu Kiristi saboda ku duka, gama ana ba da labarin bangaskiyarku a ko’ina a duniya. ");
INSERT INTO hausa_vpl VALUES ("RM1_9","075_1_9","ROM","1","9","9","Allah, wanda nake bauta wa da dukan zuciyata cikin wa’azin bisharar Ɗansa, shi ne shaidata a kan yadda kullum ina tunawa da ku ");
INSERT INTO hausa_vpl VALUES ("RM1_10","075_1_10","ROM","1","10","10","cikin addu’o’ina a kowane lokaci; ina kuma addu’a cewa a ƙarshe in Allah ya yarda hanya za tă buɗe mini in zo wurinku. ");
INSERT INTO hausa_vpl VALUES ("RM1_11","075_1_11","ROM","1","11","11","Ina marmarin ganinku don in ba ku wata baiwar ruhaniya, don ku yi ƙarfi ");
INSERT INTO hausa_vpl VALUES ("RM1_12","075_1_12","ROM","1","12","12","wato, don ni da ku mu ƙarfafa juna ta wurin bangaskiyarmu. ");
INSERT INTO hausa_vpl VALUES ("RM1_13","075_1_13","ROM","1","13","13","Ina so ku sani ’yan’uwa cewa na yi shirin zuwa wurinku sau da dama (amma aka hana ni yin haka sai yanzu). Na so in zo domin in sami mutane wa Kiristi a cikinku, kamar yadda na yi a cikin sauran Al’ummai. ");
INSERT INTO hausa_vpl VALUES ("RM1_14","075_1_14","ROM","1","14","14","Ina da hakki ga Hellenawa da waɗanda ba Hellenawa ba, ga masu hikima da kuma marasa azanci. ");
INSERT INTO hausa_vpl VALUES ("RM1_15","075_1_15","ROM","1","15","15","Shi ya sa na yi himma sosai in yi muku wa’azin bishara ku ma da kuke a Roma. ");
INSERT INTO hausa_vpl VALUES ("RM1_16","075_1_16","ROM","1","16","16","Ba na jin kunyar bishara, gama ita ikon Allah ne domin ceton kowa da ya gaskata, da farko ga Yahudawa, sa’an nan ga Al’ummai. ");
INSERT INTO hausa_vpl VALUES ("RM1_17","075_1_17","ROM","1","17","17","Gama a cikin bishara an bayyana adalci daga Allah wanda yake ta wurin bangaskiya daga farko zuwa ƙarshe, kamar yadda yake a rubuce cewa, “Mai adalci zai rayu ta wurin bangaskiya.” ");
INSERT INTO hausa_vpl VALUES ("RM1_18","075_1_18","ROM","1","18","18","Ana bayyana fushin Allah daga sama a kan dukan rashin sanin Allah da kuma muguntar mutanen da suke danne gaskiya ta wurin muguntarsu, ");
INSERT INTO hausa_vpl VALUES ("RM1_19","075_1_19","ROM","1","19","19","gama abin da ana iya sani game da Allah a bayyane yake a gare su, domin Allah ya bayyana musu shi. ");
INSERT INTO hausa_vpl VALUES ("RM1_20","075_1_20","ROM","1","20","20","Gama tun halittar duniya halayen Allah marar ganuwa, madawwamin ikonsa da kuma allahntakarsa, ana iya ganinsu sarai, ana fahimtarsu ta wurin abubuwan da Allah ya halitta, domin kada mutane su sami wata hujja. ");
INSERT INTO hausa_vpl VALUES ("RM1_21","075_1_21","ROM","1","21","21","Gama ko da yake sun san Allah, ba su ɗaukaka shi a matsayin Allah ko su gode masa ba, sai dai tunaninsu ya zama banza, zukatansu masu wauta kuma suka duhunta. ");
INSERT INTO hausa_vpl VALUES ("RM1_22","075_1_22","ROM","1","22","22","Ko da yake sun ɗauka su masu hikima ne, sai suka zama wawaye, ");
INSERT INTO hausa_vpl VALUES ("RM1_23","075_1_23","ROM","1","23","23","suka kuma yi musayar ɗaukakar Allah marar mutuwa da siffofin da aka ƙera su yi kama da mutum mai mutuwa da tsuntsaye da dabbobi da kuma halittu masu ja da ciki. ");
INSERT INTO hausa_vpl VALUES ("RM1_24","075_1_24","ROM","1","24","24","Saboda haka Allah ya yashe su ga mugayen sha’awace-sha’awacen zukatansu ga fasikanci don a ƙasƙantar da jikunansu ga yin abin kunya. ");
INSERT INTO hausa_vpl VALUES ("RM1_25","075_1_25","ROM","1","25","25","Sun sauya gaskiyar Allah da ƙarya, suka kuma yi wa abubuwan da aka halitta sujada suna bauta musu a maimakon Mahalicci, wanda ake yabo har abada. Amin. ");
INSERT INTO hausa_vpl VALUES ("RM1_26","075_1_26","ROM","1","26","26","Saboda wannan, Allah ya yashe su ga sha’awace-sha’awacensu masu banƙyama. Har matansu suka sauya daga haɗuwar mace da miji wadda ita ce daidai bisa ga halitta zuwa haɗuwa da ’yan’uwansu mata wadda ba daidai ba. ");
INSERT INTO hausa_vpl VALUES ("RM1_27","075_1_27","ROM","1","27","27","Haka ma maza suka bar al’adar kwana da mata suka tunzura cikin sha’awar kwana da juna, abin da ba daidai ba bisa ga halitta. Maza suka aikata rashin kunya da waɗansu maza, suka jawo wa kansu sakamako daidai da bauɗewarsu. ");
INSERT INTO hausa_vpl VALUES ("RM1_28","075_1_28","ROM","1","28","28","Da yake ba su yi tunani cewa ya dace su riƙe sanin Allah da suke da shi ba, sai ya yashe su ga tunanin banza da wofi, su aikata abin da bai kamata a yi ba. ");
INSERT INTO hausa_vpl VALUES ("RM1_29","075_1_29","ROM","1","29","29","Sun cika da kowace irin ƙeta, mugunta, kwaɗayi, da tunanin banza da wofi. Suka kuma cika da kishi, kisankai, faɗa, ruɗu, da kuma riƙo a zuci. Su masu gulma ne, ");
INSERT INTO hausa_vpl VALUES ("RM1_30","075_1_30","ROM","1","30","30","da masu ɓata suna, masu ƙin Allah, masu rashin kunya, masu girman kai, masu rigima; sukan ƙaga hanyoyin yin mugunta; suna rashin biyayya ga iyayensu; ");
INSERT INTO hausa_vpl VALUES ("RM1_31","075_1_31","ROM","1","31","31","su marasa hankali ne, marasa bangaskiya, marasa ƙauna, marasa tausayi. ");
INSERT INTO hausa_vpl VALUES ("RM1_32","075_1_32","ROM","1","32","32","Ko da yake sun san dokar adalcin Allah cewa masu aikata irin waɗannan abubuwa sun cancanci mutuwa, duk da haka ba cin gaba da aikata waɗannan abubuwa kaɗai suke yi ba, har ma suna goyon bayan masu yinsu. ");
INSERT INTO hausa_vpl VALUES ("RM2_1","075_2_1","ROM","2","1","1","Saboda haka, kai da kake ba wa wani laifi, ba ka da wata hujja, gama a duk lokacin da kake ba wa wani laifi, kana hukunta kanka ne, domin kai da kake ba wa wani laifi kai ma kana aikata waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("RM2_2","075_2_2","ROM","2","2","2","Yanzu mun san cewa hukuncin Allah a kan masu aikata waɗannan abubuwa daidai ne. ");
INSERT INTO hausa_vpl VALUES ("RM2_3","075_2_3","ROM","2","3","3","Saboda haka sa’ad da kai mutum kurum, kana ba su laifi, duk da haka kana aikata abubuwan nan, kana tsammani za ka tsere wa hukuncin Allah ne? ");
INSERT INTO hausa_vpl VALUES ("RM2_4","075_2_4","ROM","2","4","4","Ko kuma kana rena wadatar alherinsa, haƙurinsa, da kuma jimrewarsa ne ba tare da sanin cewa alherin Allah yana kai ka ga tuba ba ne? ");
INSERT INTO hausa_vpl VALUES ("RM2_5","075_2_5","ROM","2","5","5","Amma saboda taurinkanka da zuciyarka marar tuba, kana tara wa kanka fushi a ranar fushin Allah, sa’ad da za a bayyana hukuncinsa mai adalci. ");
INSERT INTO hausa_vpl VALUES ("RM2_6","075_2_6","ROM","2","6","6","Allah, “Zai sāka wa kowane mutum gwargwadon aikin da ya yi.” ");
INSERT INTO hausa_vpl VALUES ("RM2_7","075_2_7","ROM","2","7","7","Ga waɗanda ta wurin naciya suna yin nagarta suna neman ɗaukaka, girma da rashin mutuwa, su za a ba su rai madawwami. ");
INSERT INTO hausa_vpl VALUES ("RM2_8","075_2_8","ROM","2","8","8","Amma ga waɗanda suke sonkai waɗanda suke ƙin gaskiya suke kuma bin mugunta, akwai fushi da haushi dominsu. ");
INSERT INTO hausa_vpl VALUES ("RM2_9","075_2_9","ROM","2","9","9","Akwai wahala da baƙin ciki ga duk mutumin da yake aikata mugunta, da farko Yahudawa, sa’an nan Al’ummai, ");
INSERT INTO hausa_vpl VALUES ("RM2_10","075_2_10","ROM","2","10","10","amma akwai ɗaukaka, girma da salama ga duk mutumin da yake aikata alheri, da farko Yahudawa, sa’an nan Al’ummai. ");
INSERT INTO hausa_vpl VALUES ("RM2_11","075_2_11","ROM","2","11","11","Gama Allah ba ya nuna bambanci. ");
INSERT INTO hausa_vpl VALUES ("RM2_12","075_2_12","ROM","2","12","12","Duk waɗanda suka yi zunubi a rashi sanin doka, a rashin doka za su hallaka, waɗanda kuma suka yi zunubi ƙarƙashin doka, a ƙarƙashin doka za a hukunta su. ");
INSERT INTO hausa_vpl VALUES ("RM2_13","075_2_13","ROM","2","13","13","Gama ba masu jin dokar ne suke da adalci a gaban Allah ba, amma waɗanda suke yin biyayya da dokar, su za a ce da su masu adalci. ");
INSERT INTO hausa_vpl VALUES ("RM2_14","075_2_14","ROM","2","14","14","Tabbatacce, sa’ad da Al’ummai, waɗanda ba su da dokar, suka aikata abubuwan da dokar take bukata, abubuwan sun zama doka ke nan gare su, ko da yake ba su da dokar. ");
INSERT INTO hausa_vpl VALUES ("RM2_15","075_2_15","ROM","2","15","15","To, da yake sun nuna cewa abubuwan da dokar take bukata suna a rubuce a zukatansu, lamirinsu yana kuma ba da shaida, tunaninsu kuwa yanzu yana zarginsu ko kuma yana kāre su. ");
INSERT INTO hausa_vpl VALUES ("RM2_16","075_2_16","ROM","2","16","16","Wannan zai faru a ranar da Allah ta wurin Yesu Kiristi zai shari’anta ɓoyayyun abubuwan da mutane suka yi, yadda bisharata ta furta. ");
INSERT INTO hausa_vpl VALUES ("RM2_17","075_2_17","ROM","2","17","17","To, kai, da kake kiran kanka mutumin Yahuda; in kana dogara ga doka kana kuma taƙama da dangantakarka da Allah; ");
INSERT INTO hausa_vpl VALUES ("RM2_18","075_2_18","ROM","2","18","18","in ka san nufinsa ka kuma amince da abin da yake mafifici domin an koyar da kai bisa ga doka; ");
INSERT INTO hausa_vpl VALUES ("RM2_19","075_2_19","ROM","2","19","19","in ka tabbata cewa kai jagora ne ga makafi, haske ga waɗanda suke cikin duhu, ");
INSERT INTO hausa_vpl VALUES ("RM2_20","075_2_20","ROM","2","20","20","mai koyar da masu wauta, malamin jarirai, domin a cikin dokar ce akwai sani da gaskiya ");
INSERT INTO hausa_vpl VALUES ("RM2_21","075_2_21","ROM","2","21","21","to, kai mai koya wa waɗansu, ba kanka kake koya wa ba? Kai da kake wa’azi kada a yi sata, kana sata? ");
INSERT INTO hausa_vpl VALUES ("RM2_22","075_2_22","ROM","2","22","22","Kai da kake cewa wa mutane kada su yi zina, kana yin zina? Kai da kake ƙyamar gumaka, kana wa haikali fashi? ");
INSERT INTO hausa_vpl VALUES ("RM2_23","075_2_23","ROM","2","23","23","Kai da kake taƙama da doka, kana nuna rashin bangirma ga Allah ta wurin karya dokar? ");
INSERT INTO hausa_vpl VALUES ("RM2_24","075_2_24","ROM","2","24","24","Kamar yadda yake a rubuce, “Ana saɓon sunan Allah a cikin Al’ummai saboda ku.” ");
INSERT INTO hausa_vpl VALUES ("RM2_25","075_2_25","ROM","2","25","25","Kaciya tana da amfani in kana kiyaye dokar, amma in kana karya dokar, ka zama kamar ba a yi maka kaciya ba. ");
INSERT INTO hausa_vpl VALUES ("RM2_26","075_2_26","ROM","2","26","26","In marasa kaciya suna kiyaye dokar, ashe, ba za a ɗauke su kamar an yi musu kaciya ba? ");
INSERT INTO hausa_vpl VALUES ("RM2_27","075_2_27","ROM","2","27","27","Wanda ba shi da kaciya ta jiki duk da haka yana biyayya da dokar zai iya hukunta ka, kai da kake karya dokar, ko da yake kana da rubutaccen tsarin dokar an kuma yi maka kaciya. ");
INSERT INTO hausa_vpl VALUES ("RM2_28","075_2_28","ROM","2","28","28","Mutum ba mutumin Yahuda ba ne in shi mutumin Yahuda ne kawai a jiki, haka kuma kaciya ba a waje ko a jiki kawai ba. ");
INSERT INTO hausa_vpl VALUES ("RM2_29","075_2_29","ROM","2","29","29","A’a, mutum mutumin Yahuda ne in shi mutumin Yahuda ne a zuci; kuma kaciya ita ce kaciya ta zuci, ta wurin Ruhu, ba ta wurin rubutaccen doka ba. Irin wannan mutum yana samun yabo daga Allah ne, ba ɗan adam ba. ");
INSERT INTO hausa_vpl VALUES ("RM3_1","075_3_1","ROM","3","1","1","To, mece ce ribar zama mutumin Yahuda, ko kuwa mene ne amfanin kaciya? ");
INSERT INTO hausa_vpl VALUES ("RM3_2","075_3_2","ROM","3","2","2","Akwai riba ƙwarai ta kowace hanya! Da farko dai, su ne aka danƙa wa kalmomin nan na Allah. ");
INSERT INTO hausa_vpl VALUES ("RM3_3","075_3_3","ROM","3","3","3","Amma a ce waɗansu ba su da bangaskiya fa? Rashin bangaskiyarsu nan zai shafe amincin Allah? ");
INSERT INTO hausa_vpl VALUES ("RM3_4","075_3_4","ROM","3","4","4","Ko kaɗan! Bari Allah yă zama mai gaskiya, kowane mutum kuma yă zama maƙaryaci. Kamar yadda yake a rubuce cewa, “Gama a tabbatar kana da gaskiya, sa’ad da ka yi magana, ka kuma yi nasara sa’ad da ka yi shari’a.” ");
INSERT INTO hausa_vpl VALUES ("RM3_5","075_3_5","ROM","3","5","5","Amma in rashin adalcinmu ya bayyana adalcin Allah a fili, me za mu ce ke nan? Za mu ce Allah ya yi rashin adalci ke nan da ya saukar da fushinsa a kanmu? (Ina magana kamar yadda mutum zai yi ne.) ");
INSERT INTO hausa_vpl VALUES ("RM3_6","075_3_6","ROM","3","6","6","Sam, ko kusa! Da a ce haka ne, ta yaya Allah zai shari’anta duniya? ");
INSERT INTO hausa_vpl VALUES ("RM3_7","075_3_7","ROM","3","7","7","Wani zai iya ce, “In a dalilin ƙaryata, gaskiyar Allah ta ƙara bayyana, har aka ƙara ɗaukaka shi, to, ta yaya zan zama mai zunubi, in ƙaryata tana kawo ɗaukaka ga Allah?” ");
INSERT INTO hausa_vpl VALUES ("RM3_8","075_3_8","ROM","3","8","8","In haka ne, “Ba sai mu yi ta yin mugunta don yă zama hanyar samun nagarta ba”? Kamar yadda masu baƙar magana game da mu suna cewa wai haka muke faɗa. Tabbatacce za a hukunta irin waɗannan da hukuncin da ya dace da su. ");
INSERT INTO hausa_vpl VALUES ("RM3_9","075_3_9","ROM","3","9","9","To, me za mu ce ke nan? Mun fi su ke nan? Ina, ko kaɗan! Mun riga mun zartar cewa da Yahudawa da Al’ummai duk suna a ƙarƙarshin zunubi. ");
INSERT INTO hausa_vpl VALUES ("RM3_10","075_3_10","ROM","3","10","10","Kamar yadda yake a rubuce cewa, “Babu wani mai adalci, babu ko ɗaya; ");
INSERT INTO hausa_vpl VALUES ("RM3_11","075_3_11","ROM","3","11","11","babu wani mai fahimta, babu wani mai neman Allah. ");
INSERT INTO hausa_vpl VALUES ("RM3_12","075_3_12","ROM","3","12","12","Duk sun kauce gaba ɗaya, sun zama marasa amfani; babu wani mai aikata nagarta, babu ko ɗaya.” ");
INSERT INTO hausa_vpl VALUES ("RM3_13","075_3_13","ROM","3","13","13","“Maƙogwaronsu kamar buɗaɗɗun kaburbura ne, harsunansu suna yin ƙarya.” “Dafin mugun maciji yana a leɓunansu.” ");
INSERT INTO hausa_vpl VALUES ("RM3_14","075_3_14","ROM","3","14","14","“Bakunansu sun cike da la’ana da ɗacin rai.” ");
INSERT INTO hausa_vpl VALUES ("RM3_15","075_3_15","ROM","3","15","15","“Ƙafafunsu suna saurin kai su zuwa ga zub da jini; ");
INSERT INTO hausa_vpl VALUES ("RM3_16","075_3_16","ROM","3","16","16","hallaka da baƙin ciki suna ko’ina a hanyoyinsu, ");
INSERT INTO hausa_vpl VALUES ("RM3_17","075_3_17","ROM","3","17","17","ba su kuma san hanyar salama ba.” ");
INSERT INTO hausa_vpl VALUES ("RM3_18","075_3_18","ROM","3","18","18","“Babu tsoron Allah a idanunsu.” ");
INSERT INTO hausa_vpl VALUES ("RM3_19","075_3_19","ROM","3","19","19","Yanzu mun san cewa dukan abin da doka ta ce, tana magana ne ga waɗanda suke ƙarƙarshin doka, saboda a rufe kowane baki; dukan duniya kuma ta ba da lissafin kanta a gaban Allah. ");
INSERT INTO hausa_vpl VALUES ("RM3_20","075_3_20","ROM","3","20","20","Saboda haka babu wanda Allah zai ce da shi mai adalci ta wurin kiyaye doka kawai; a maimako, ta wurin doka ne muke sane da zunubi. ");
INSERT INTO hausa_vpl VALUES ("RM3_21","075_3_21","ROM","3","21","21","Amma yanzu an bayyana wani adalci daga Allah, wannan adalcin bai danganta ga doka ba, Doka da Annabawa suna ba da shaida game da wannan adalci. ");
INSERT INTO hausa_vpl VALUES ("RM3_22","075_3_22","ROM","3","22","22","Wannan adalcin Allah yana zuwa ta wurin bangaskiya a cikin Yesu Kiristi ga dukan waɗanda suka ba da gaskiya ne. Ba bambanci, ");
INSERT INTO hausa_vpl VALUES ("RM3_23","075_3_23","ROM","3","23","23","gama duka sun yi zunubi suka kuma kāsa ga ɗaukakar Allah, ");
INSERT INTO hausa_vpl VALUES ("RM3_24","075_3_24","ROM","3","24","24","an kuma kuɓutar da su kyauta ta wurin alherinsa bisa ga aikin fansar da ya zo ta wurin Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("RM3_25","075_3_25","ROM","3","25","25","Allah ya miƙa Yesu Kiristi a matsayin hadayar kafara, ta wurin bangaskiya cikin jininsa. Ya yi haka domin yă nuna adalcinsa, domin a cikin haƙurinsa bai hukunta zunuban da aka aikata a dā ba ");
INSERT INTO hausa_vpl VALUES ("RM3_26","075_3_26","ROM","3","26","26","ya yi haka domin yă nuna adalcinsa a wannan lokaci, saboda yă zama mai adalci da mai kuɓutar da waɗanda suke ba da gaskiya a cikin Yesu. ");
INSERT INTO hausa_vpl VALUES ("RM3_27","075_3_27","ROM","3","27","27","To, me za mu yi taƙama a kai? Babu wani abin da zamu yi taƙama a kai. A kan wace ƙa’ida ce za mu yi taƙama? Ta hanyar bin doka ne? A’a, sai dai ta wurin bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("RM3_28","075_3_28","ROM","3","28","28","Gama mun tsaya a kan cewa ta wurin bangaskiya ne ake kuɓutar da mutum, ba ta wurin kiyaye doka ba. ");
INSERT INTO hausa_vpl VALUES ("RM3_29","075_3_29","ROM","3","29","29","Allah ɗin, Allahn Yahudawa ne kaɗai? Shi ba Allahn Al’ummai ba ne? I, shi Allahn Al’ummai ne ma, ");
INSERT INTO hausa_vpl VALUES ("RM3_30","075_3_30","ROM","3","30","30","da yake Allah ɗaya ne kaɗai, shi kuma zai kuɓutar da masu kaciya bisa ga bangaskiya da kuma marasa kaciya ta wurin wannan bangaskiya ɗin. ");
INSERT INTO hausa_vpl VALUES ("RM3_31","075_3_31","ROM","3","31","31","To, za mu soke dokar saboda wannan bangaskiyar ne? Ko kaɗan! A maimako, sai ma tabbatar da ita muke yi. ");
INSERT INTO hausa_vpl VALUES ("RM4_1","075_4_1","ROM","4","1","1","To, me za mu ce Ibrahim kakan kakanninmu ya gani game da wannan batu? ");
INSERT INTO hausa_vpl VALUES ("RM4_2","075_4_2","ROM","4","2","2","In fa da gaske ne Ibrahim ya sami kuɓuta ta wurin ayyuka, yana da abin da zai yin taƙama da shi ke nan, amma ba a gaban Allah ba. ");
INSERT INTO hausa_vpl VALUES ("RM4_3","075_4_3","ROM","4","3","3","Me Nassin ya ce? “Ibrahim ya gaskata Allah, aka kuma lissafta wannan adalci ne a gare shi.” ");
INSERT INTO hausa_vpl VALUES ("RM4_4","075_4_4","ROM","4","4","4","To, sa’ad da mutum ya yi aiki, ba a lissafta ladan aikinsa a matsayin kyauta, sai dai a matsayin hakkinsa. ");
INSERT INTO hausa_vpl VALUES ("RM4_5","075_4_5","ROM","4","5","5","Amma fa, game da mutumin da ba ya aiki sai dai dogara ga Allah wanda yake kuɓutar da masu mugunta, akan lissafta bangaskiyarsa a matsayin adalci ne. ");
INSERT INTO hausa_vpl VALUES ("RM4_6","075_4_6","ROM","4","6","6","Dawuda ya faɗi haka sa’ad da ya yi magana game da albarkar da aka yi wa mutumin da Allah ya lissafta adalci a gare shi, ba don yă yi ayyuka ba. ");
INSERT INTO hausa_vpl VALUES ("RM4_7","075_4_7","ROM","4","7","7","“Masu albarka ne waɗanda aka gafarta laifofinsu, waɗanda aka kuma rufe zunubansu. ");
INSERT INTO hausa_vpl VALUES ("RM4_8","075_4_8","ROM","4","8","8","Mai albarka ne mutumin da Ubangiji ba zai taɓa lissafta zunubansa ba.” ");
INSERT INTO hausa_vpl VALUES ("RM4_9","075_4_9","ROM","4","9","9","Shin, wannan albarkar a kan masu kaciya ne kawai, ko kuwa har da marasa kaciya ma? Mun sha faɗi cewa an lissafta bangaskiyar Ibrahim adalci ne a gare shi. ");
INSERT INTO hausa_vpl VALUES ("RM4_10","075_4_10","ROM","4","10","10","A kan wane hali ne aka lissafta masa? Bayan da aka yi masa kaciya ne, ko kuwa kafin kaciyar? Ba bayan an yi masa kaciya ba ne, amma kafin a yi masa kaciya! ");
INSERT INTO hausa_vpl VALUES ("RM4_11","075_4_11","ROM","4","11","11","Ya kuma karɓi alamar kaciya, hatimin adalcin da yake da shi ta wurin bangaskiya tun yana marar kaciya. Saboda haka fa, ya zama mahaifin dukan waɗanda suka gaskata domin su ma a lasafta su masu adalci ne, ba tare da an yi musu kaciya ba. ");
INSERT INTO hausa_vpl VALUES ("RM4_12","075_4_12","ROM","4","12","12","Ya kuma zama mahaifin masu kaciya waɗanda ba kaciya kaɗai suke da ita ba amma har ma suna bin gurbin bangaskiyar da mahaifinmu Ibrahim yake da ita kafin aka yi masa kaciya. ");
INSERT INTO hausa_vpl VALUES ("RM4_13","075_4_13","ROM","4","13","13","Ba ta wurin doka ce Ibrahim da zuriyarsa suka sami alkawarin cewa zai zama magājin duniya ba, amma sai dai ta wurin adalcin da yake zuwa ta wurin bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("RM4_14","075_4_14","ROM","4","14","14","Gama da a ce masu kiyaye doka ne magāda, ai, da bangaskiya ba ta da amfani, alkawarin kuma ya zama banza, ");
INSERT INTO hausa_vpl VALUES ("RM4_15","075_4_15","ROM","4","15","15","domin doka tana jawo fushi ne. Kuma inda babu doka babu keta umarni ke nan. ");
INSERT INTO hausa_vpl VALUES ("RM4_16","075_4_16","ROM","4","16","16","Saboda haka, alkawari yakan zo ta wurin bangaskiya ne, domin yă zama ta wurin alheri, don a tabbatar wa dukan zuriyar Ibrahim ba kawai ga waɗanda suke na doka ba amma har ma ga waɗanda suke na bangaskiyar Ibrahim. Shi ne kuwa mahaifinmu duka. ");
INSERT INTO hausa_vpl VALUES ("RM4_17","075_4_17","ROM","4","17","17","Kamar yadda yake a rubuce cewa, “Na mai da kai uban al’ummai masu yawa.” Shi ubanmu ne a gaban Allah, wanda a cikinsa ya gaskata, Allahn da yake ba da rai ga matattu, yake kuma kiran abubuwan da ba su kasance ba su zama kamar sun kasance. ");
INSERT INTO hausa_vpl VALUES ("RM4_18","075_4_18","ROM","4","18","18","Saɓanin dukan bege, Ibrahim cikin bege ya gaskata, haka kuwa ya zama uban al’ummai masu yawa, kamar yadda aka riga aka faɗa masa cewa, “Haka zuriyarka za tă zama.” ");
INSERT INTO hausa_vpl VALUES ("RM4_19","075_4_19","ROM","4","19","19","Ba tare da ya bar bangaskiyarsa ta yi rauni ba, ya fuskanci gaskiyan nan mai cewa jikinsa mai tsufa matacce ne, da yake yana da shekara wajen ɗari, mahaifar Saratu kuma matacciya ce. ");
INSERT INTO hausa_vpl VALUES ("RM4_20","075_4_20","ROM","4","20","20","Duk da haka bai yi shakka ta wurin rashin bangaskiya game da alkawarin Allah ba, sai ma ya ƙara ƙarfafa ga bangaskiyarsa, ya kuma ɗaukaka Allah, ");
INSERT INTO hausa_vpl VALUES ("RM4_21","075_4_21","ROM","4","21","21","yana kuma da cikakken tabbaci cewa Allah yana da iko yă cika abin da ya yi alkawari. ");
INSERT INTO hausa_vpl VALUES ("RM4_22","075_4_22","ROM","4","22","22","Shi ya sa, “aka lissafta adalci a gare shi.” ");
INSERT INTO hausa_vpl VALUES ("RM4_23","075_4_23","ROM","4","23","23","Kalmomin nan, “aka lissafta a gare shi” ba a rubuta su saboda shi kaɗai ba ne, ");
INSERT INTO hausa_vpl VALUES ("RM4_24","075_4_24","ROM","4","24","24","amma saboda mu ma, mu da Allah zai lissafta adalci, mu da muka ba da gaskiya gare shi da ya tashe Yesu Ubangijinmu daga matattu. ");
INSERT INTO hausa_vpl VALUES ("RM4_25","075_4_25","ROM","4","25","25","An miƙa shi ga mutuwa saboda zunubanmu, aka kuma tashe shi zuwa rai saboda Allah zai same mu marasa laifi. ");
INSERT INTO hausa_vpl VALUES ("RM5_1","075_5_1","ROM","5","1","1","Saboda haka, da yake an same mu marasa laifi ta wurin bangaskiya, muna da salama tare da Allah ta wurin Ubangijinmu Yesu Kiristi, ");
INSERT INTO hausa_vpl VALUES ("RM5_2","075_5_2","ROM","5","2","2","ta wurinsa ne muka sami shiga wannan alherin da muke tsaye yanzu, ta wurin bangaskiya. Muna kuma farin ciki a begen ɗaukakar Allah. ");
INSERT INTO hausa_vpl VALUES ("RM5_3","075_5_3","ROM","5","3","3","Ba haka kawai ba, amma muna kuma da farin ciki cikin shan wuyanmu, gama mun san cewa shan wuyan nan takan haifi jimiri; ");
INSERT INTO hausa_vpl VALUES ("RM5_4","075_5_4","ROM","5","4","4","jimiri kuma yakan kawo hali mai kyau; hali mai kyau kuma yakan sa bege. ");
INSERT INTO hausa_vpl VALUES ("RM5_5","075_5_5","ROM","5","5","5","Bege kuwa ba ya ba mu kunya, domin Allah ya zuba ƙaunarsa a zukatanmu ta wurin Ruhu Mai Tsarkin da ya ba mu. ");
INSERT INTO hausa_vpl VALUES ("RM5_6","075_5_6","ROM","5","6","6","Kun ga, a daidai lokaci, yayinda muke marasa ƙarfi, Kiristi ya mutu saboda waɗanda ba su san Allah ba. ");
INSERT INTO hausa_vpl VALUES ("RM5_7","075_5_7","ROM","5","7","7","Da ƙyar wani yă mutu saboda mai adalci, ko da yake saboda mutumin kirki wani zai iya ƙarfin hali yă mutu. ");
INSERT INTO hausa_vpl VALUES ("RM5_8","075_5_8","ROM","5","8","8","Amma Allah ya nuna mana ƙaunarsa a wannan. Tun muna masu zunubi tukuna, Kiristi ya mutu dominmu. ");
INSERT INTO hausa_vpl VALUES ("RM5_9","075_5_9","ROM","5","9","9","Da yake yanzu mun sami zama marasa laifi ta wurin jininsa, ashe kuwa za a cece mu daga fushin Allah ta wurinsa! ");
INSERT INTO hausa_vpl VALUES ("RM5_10","075_5_10","ROM","5","10","10","Gama in kuwa, sa’ad da muke abokan gāban Allah, aka sulhunta mu da shi ta wurin mutuwar Ɗansa, ashe, da yake an sulhunta mu, za mu sami ceto ta wurin ransa! ");
INSERT INTO hausa_vpl VALUES ("RM5_11","075_5_11","ROM","5","11","11","Ba ma haka yake kawai ba, har muna farin ciki da Allah ta wurin Ubangijinmu Yesu Kiristi, wanda ta wurinsa yanzu muka sami sulhu. ");
INSERT INTO hausa_vpl VALUES ("RM5_12","075_5_12","ROM","5","12","12","Saboda haka, kamar yadda zunubi ya shigo duniya ta wurin mutum ɗaya, mutuwa kuma ta wurin zunubi, ta haka kuwa mutuwa ta shafi dukan mutane, domin dukan mutane sun yi zunubi. ");
INSERT INTO hausa_vpl VALUES ("RM5_13","075_5_13","ROM","5","13","13","Gama kafin a ba da doka, zunubi yana nan a duniya. Amma ba a lissafin zunubi inda babu doka. ");
INSERT INTO hausa_vpl VALUES ("RM5_14","075_5_14","ROM","5","14","14","Duk da haka, mutuwa ta yi mulki tun Adamu har yă zuwa Musa, ta yi mulki har ma a kan waɗanda ba su yi zunubi ta wurin taka umarni kamar yadda Adamu ya yi ba. A wata hanya dai Adamu shi ne kwatancin wani mutumin nan mai zuwa. ");
INSERT INTO hausa_vpl VALUES ("RM5_15","075_5_15","ROM","5","15","15","Amma kyautan nan dabam take da laifin nan. Gama in mutane da yawa sun mutu saboda laifin mutum ɗayan nan, to, ai, alherin Allah da kuma kyautan nan mai zuwa ta wurin alherin mutum ɗayan nan, Yesu Kiristi, ya shafi mutane da yawa! ");
INSERT INTO hausa_vpl VALUES ("RM5_16","075_5_16","ROM","5","16","16","Kyautar Allah kuwa ba kamar sakamakon da ya bi zunubin mutum gudan nan ba ne, Hukuncin ya bi zunubin mutum gudan nan, ya kuma kawo hallaka, amma kyautar ta bi laifofin masu yawa ta kuma sa Allah ya gan mu a matsayin marasa laifi. ");
INSERT INTO hausa_vpl VALUES ("RM5_17","075_5_17","ROM","5","17","17","Gama in, ta wurin laifin mutum ɗaya, mutuwa ta yi mulki ta wurin mutum ɗayan nan, ashe, waɗanda suka sami kyautar alherin Allah a yalwace da kuma kyautar adalci za su yi mulki a wannan rayuwa ta wurin mutum ɗayan nan, Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("RM5_18","075_5_18","ROM","5","18","18","Saboda haka, kamar yadda sakamakon laifin mutum guda ya jawo hallaka ga dukan mutane, haka ma sakamakon aikin adalci guda ya sa Allah ya same mu marasa laifi, wannan kuwa kawo rai ga dukan mutane. ");
INSERT INTO hausa_vpl VALUES ("RM5_19","075_5_19","ROM","5","19","19","Gama kamar yadda ta wurin rashin biyayyar mutum guda, mutane masu yawa suka zama masu zunubi, haka kuma ta wurin biyayyar mutum guda, mutane da yawa za su zama masu adalci. ");
INSERT INTO hausa_vpl VALUES ("RM5_20","075_5_20","ROM","5","20","20","An ba da dokar don mu ga yadda laifi yake da girma. Amma da zunubi ya ƙaru, sai alheri ya ƙaru sosai, ");
INSERT INTO hausa_vpl VALUES ("RM5_21","075_5_21","ROM","5","21","21","domin, kamar yadda zunubi ya yi mulki cikin mutuwa, haka ma alheri yă yi mulki ta wurin adalci yă kuwa kawo rai madawwami ta wurin Yesu Kiristi Ubangijinmu. ");
INSERT INTO hausa_vpl VALUES ("RM6_1","075_6_1","ROM","6","1","1","Me za mu ce ke nan? Za mu ci gaba da yin zunubi domin alheri yă haɓaka? ");
INSERT INTO hausa_vpl VALUES ("RM6_2","075_6_2","ROM","6","2","2","Sam, ko kaɗan! Mun mutu ga zunubi; ta yaya za mu ci gaba da rayuwa a cikinsa kuma? ");
INSERT INTO hausa_vpl VALUES ("RM6_3","075_6_3","ROM","6","3","3","Ko ba ku sani ba cewa dukanmu da aka yi wa baftisma a cikin Kiristi Yesu an yi mana baftismar ne zuwa cikin mutuwarsa? ");
INSERT INTO hausa_vpl VALUES ("RM6_4","075_6_4","ROM","6","4","4","Saboda haka, an binne mu da shi ke nan, ta wurin baftisma cikin mutuwarsa, domin kamar yadda aka tā da Kiristi daga matattu ta wurin ɗaukakar Uba, haka mu ma mu yi zaman sabuwar rayuwa. ");
INSERT INTO hausa_vpl VALUES ("RM6_5","075_6_5","ROM","6","5","5","In kuwa mun zama ɗaya tare da shi haka a cikin mutuwarsa, tabbatacce mu ma za mu zama ɗaya tare da shi cikin tashinsa daga matattu. ");
INSERT INTO hausa_vpl VALUES ("RM6_6","075_6_6","ROM","6","6","6","Gama mun san cewa an gicciye halayenmu na dā tare da shi domin a kawar da jikin nan mai zunubi don kada mu ƙara zama bayi ga zunubi ");
INSERT INTO hausa_vpl VALUES ("RM6_7","075_6_7","ROM","6","7","7","domin duk wanda ya mutu an ’yantar da shi daga zunubi ke nan. ");
INSERT INTO hausa_vpl VALUES ("RM6_8","075_6_8","ROM","6","8","8","To, in mun mutu tare da Kiristi, mun gaskata cewa za mu rayu tare da shi kuma. ");
INSERT INTO hausa_vpl VALUES ("RM6_9","075_6_9","ROM","6","9","9","Gama mun san cewa da yake an tā da Kiristi daga matattu, ba zai sāke mutuwa ba; mutuwa ba ta da sauran iko a kansa. ");
INSERT INTO hausa_vpl VALUES ("RM6_10","075_6_10","ROM","6","10","10","Mutuwar da ya yi, ya mutu ne sau ɗaya tak, saboda yă shafe zunubi, amma rayuwar da yake yi, yana yi ne cikin tarayya da Allah. ");
INSERT INTO hausa_vpl VALUES ("RM6_11","075_6_11","ROM","6","11","11","Haka ku ma, ku ɗauke kanku matattu ne ga ikon zunubi amma rayayyu cikin tarayya da Allah cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("RM6_12","075_6_12","ROM","6","12","12","Saboda haka kada ku bar zunubi yă mallaki jikin nan naku mai mutuwa yă sa ku zama masu biyayya ga mugayen sha’awace-sha’awacensa. ");
INSERT INTO hausa_vpl VALUES ("RM6_13","075_6_13","ROM","6","13","13","Kada ku miƙa gaɓoɓin jikinku ga zunubi a matsayin kayan aikin mugunta, sai dai ku miƙa kanku ga Allah, a matsayin waɗanda aka fitar da su daga mutuwa zuwa rai; ku kuma miƙa gaɓoɓin jikinku gare shi a matsayin kayan aikin adalci. ");
INSERT INTO hausa_vpl VALUES ("RM6_14","075_6_14","ROM","6","14","14","Gama zunubi ba zai zama maigidanku ba, domin ba kwa ƙarƙashin doka, sai dai ƙarƙashin alheri. ");
INSERT INTO hausa_vpl VALUES ("RM6_15","075_6_15","ROM","6","15","15","Me za mu ce ke nan? Za mu ci gaba yin zunubi domin ba ma ƙarƙashin doka sai dai ƙarƙashin alheri? Sam, ko kaɗan! ");
INSERT INTO hausa_vpl VALUES ("RM6_16","075_6_16","ROM","6","16","16","Ba ku sani ba cewa sa’ad da kuka miƙa kanku ga wani don ku yi masa biyayya a matsayin bayi, ko ku bayi ne ga zunubi, wanda yake kai ga mutuwa, ko kuwa ga biyayya, wadda take kai ga adalci, ashe, ba kun zama bayi ga wannan da kuke yi wa biyayya ba ke nan? ");
INSERT INTO hausa_vpl VALUES ("RM6_17","075_6_17","ROM","6","17","17","Amma godiya ga Allah don ko da yake a dā ku bayi ne ga ikon zunubi, da dukan zuciyarku kun yi biyayya ga irin koyarwar da aka danƙa muku. ");
INSERT INTO hausa_vpl VALUES ("RM6_18","075_6_18","ROM","6","18","18","An ’yanta ku daga zunubi, kun kuma zama bayi ga aikin adalci. ");
INSERT INTO hausa_vpl VALUES ("RM6_19","075_6_19","ROM","6","19","19","Ina magana ne kamar mutane saboda kun raunana a jikinku. Kamar yadda kuka saba miƙa gaɓoɓin jikinku a bautar abubuwan ƙazanta da mugun aiki a kan mugun aiki, saboda haka yanzu sai ku miƙa su bayi ga aikin adalci mai kai ga zaman tsarki. ");
INSERT INTO hausa_vpl VALUES ("RM6_20","075_6_20","ROM","6","20","20","Sa’ad da kuke bayin zunubi, ba ruwanku da aikin adalci. ");
INSERT INTO hausa_vpl VALUES ("RM6_21","075_6_21","ROM","6","21","21","Wace riba ce kuka samu a lokacin, daga abubuwan nan da yanzu suka zama muku abin kunya? Ƙarshen irin abubuwan nan dai, mutuwa ne! ");
INSERT INTO hausa_vpl VALUES ("RM6_22","075_6_22","ROM","6","22","22","Amma a yanzu da aka ’yantar da ku daga zunubi kuka kuma zama bayi ga Allah, ribar da kuka samu tana kai ga zaman tsarki, ƙarshenta kuwa rai madawwami ne. ");
INSERT INTO hausa_vpl VALUES ("RM6_23","075_6_23","ROM","6","23","23","Gama sakamakon zunubi mutuwa ne, amma kyautar Allah rai madawwami ne a cikin Kiristi Yesu Ubangijinmu. ");
INSERT INTO hausa_vpl VALUES ("RM7_1","075_7_1","ROM","7","1","1","Ba ku sani ba, ’yan’uwa, ina magana ne fa da mutanen da suka san doka, cewa dokar tana da iko a kan mutum muddin yana a raye ne kawai. ");
INSERT INTO hausa_vpl VALUES ("RM7_2","075_7_2","ROM","7","2","2","Misali, bisa ga doka mace mai aure tana daure ga mijinta muddin mijin yana da rai, amma in mijinta ya mutu, an sake ta ke nan daga dokar aure. ");
INSERT INTO hausa_vpl VALUES ("RM7_3","075_7_3","ROM","7","3","3","Saboda haka fa, in ta auri wani yayinda mijinta yana raye, za a ce da ita mazinaciya. Amma in mijinta ya mutu, an sake ta ke nan daga wannan doka, ita kuwa ba mazinaciya ba ce, ko da yake ta auri wani. ");
INSERT INTO hausa_vpl VALUES ("RM7_4","075_7_4","ROM","7","4","4","Saboda haka ’yan’uwana, ku ma kun mutu ga dokar ta wurin jikin Kiristi, domin ku zama na wani, gare shi wanda aka tashe shi daga matattu, don mu ba da amfani ga Allah. ");
INSERT INTO hausa_vpl VALUES ("RM7_5","075_7_5","ROM","7","5","5","Gama sa’ad da halin mutuntaka yake mulkinmu, sha’awace-sha’awacen zunubi waɗanda dokar ta zuga sun yi ta aiki a jikunanmu, don mu ba da amfani wa mutuwa. ");
INSERT INTO hausa_vpl VALUES ("RM7_6","075_7_6","ROM","7","6","6","Amma yanzu, ta wurin mutuwa ga abin da dā ya daure mu, an sake mu daga dokar saboda mu yi hidima a sabuwar hanyar Ruhu, ba a tsohuwar hanyar rubutaccen ƙa’ida ba. ");
INSERT INTO hausa_vpl VALUES ("RM7_7","075_7_7","ROM","7","7","7","Me za mu ce ke nan? Dokar zunubi ce? Sam, ko kaɗan! Tabbatacce ai, da ban san mene ne zunubi ba in ba ta wurin doka ba. Gama da ban san mene ne ƙyashi yake ba tabbatacce in ba don doka ta ce, “Kada ka yi ƙyashi ba.” ");
INSERT INTO hausa_vpl VALUES ("RM7_8","075_7_8","ROM","7","8","8","Amma zunubi, da ya sami dama ta wurin umarnin nan, ya haifar a cikina kowane halin ƙyashi iri-iri. Gama in babu doka, zunubi matacce ne. ");
INSERT INTO hausa_vpl VALUES ("RM7_9","075_7_9","ROM","7","9","9","Dā kam ina da rai sa’ad da ban san doka ba; amma da umarni ya zo, sai zunubi ya zaburo da rai na kuma mutu. ");
INSERT INTO hausa_vpl VALUES ("RM7_10","075_7_10","ROM","7","10","10","Na gane cewa wannan umarnin da aka nufa ya kawo rai, a gaskiya ya jawo mutuwa ce. ");
INSERT INTO hausa_vpl VALUES ("RM7_11","075_7_11","ROM","7","11","11","Gama zunubi, da ya sami dama ta wurin umarni, sai ya ruɗe ni, kuma ta wurin umarnin kuwa ya kashe ni. ");
INSERT INTO hausa_vpl VALUES ("RM7_12","075_7_12","ROM","7","12","12","Saboda haka fa, dokar tana da tsarki, umarnin kuma yana da tsarki, su duka suna da adalci da kuma kyau. ");
INSERT INTO hausa_vpl VALUES ("RM7_13","075_7_13","ROM","7","13","13","Abin nan da yana mai kyau, zai kawo mini mutuwa? Ko kaɗan! Amma domin zunubi ya bayyana kansa a matsayin zunubi, sai ya haifar da mutuwa a cikina ta wurin abin da yake mai kyau, domin ta wurin umarnin nan zunubi ya fito da matuƙar muninsa. ");
INSERT INTO hausa_vpl VALUES ("RM7_14","075_7_14","ROM","7","14","14","Mun san cewa doka aba ce ta ruhu; amma ni ba na ruhu ba ne, an sayar da ni a matsayin bawa ga zunubi. ");
INSERT INTO hausa_vpl VALUES ("RM7_15","075_7_15","ROM","7","15","15","Ban gane abin da nake yi ba. Don abin da nakan so yi, ba shi nakan yi ba, sai dai abin da nake ƙi, shi nake yi. ");
INSERT INTO hausa_vpl VALUES ("RM7_16","075_7_16","ROM","7","16","16","In kuma na yi abin da ba na son yi, na yarda da cewa dokar aba ce mai kyau. ");
INSERT INTO hausa_vpl VALUES ("RM7_17","075_7_17","ROM","7","17","17","Kamar dai yadda yake, ba ni kaina nake yinsa ba, sai dai zunubin da yake zaune a cikina ne. ");
INSERT INTO hausa_vpl VALUES ("RM7_18","075_7_18","ROM","7","18","18","Gama na san cewa babu wani abin kirkin da yake zaune a cikina, wato, a mutuntakata. Gama sha’awar yin abu mai kyau kam ina da ita, sai dai ikon yin ne fa babu. ");
INSERT INTO hausa_vpl VALUES ("RM7_19","075_7_19","ROM","7","19","19","Gama abin da nake yi ba shi ne abu mai kyau da nake so in yi ba; a’a, mugun da ba na so in yi, shi ne nake ci gaba da yi. ");
INSERT INTO hausa_vpl VALUES ("RM7_20","075_7_20","ROM","7","20","20","To, in na yi abin da ba na so in yi, ba ni ba ne nake yinsa, sai dai zunubin nan da yake zaune a cikina. ");
INSERT INTO hausa_vpl VALUES ("RM7_21","075_7_21","ROM","7","21","21","Saboda haka na gane wannan ƙa’ida ce take aiki a cikina. Sa’ad da nake so in yi abu mai kyau, sai in ga cewa mugun nan ne nake yi. ");
INSERT INTO hausa_vpl VALUES ("RM7_22","075_7_22","ROM","7","22","22","Gama a ciki-cikina ina farin cikin da dokar Allah; ");
INSERT INTO hausa_vpl VALUES ("RM7_23","075_7_23","ROM","7","23","23","amma ina ganin wata doka tana aiki a gaɓoɓin jikina, tana yaƙi da dokar hankalina, tana kuma sa in zama ɗaurarren dokar zunubin da take aiki a gaɓoɓin jikina. ");
INSERT INTO hausa_vpl VALUES ("RM7_24","075_7_24","ROM","7","24","24","Kaitona! Wane ne zai cece ni daga wannan jiki mai mutuwa? ");
INSERT INTO hausa_vpl VALUES ("RM7_25","075_7_25","ROM","7","25","25","Godiya ga Allah ta wurin Yesu Kiristi Ubangijinmu! Saboda haka fa, ni kaina a cikin hankalina, ni bawa ne ga dokar Allah, amma a mutuntaka, ni bawa ne ga dokar zunubi. ");
INSERT INTO hausa_vpl VALUES ("RM8_1","075_8_1","ROM","8","1","1","Saboda haka, yanzu babu hukunci don waɗanda suke cikin Kiristi Yesu, ");
INSERT INTO hausa_vpl VALUES ("RM8_2","075_8_2","ROM","8","2","2","gama ta wurin Kiristi Yesu dokar Ruhu mai ba da rai ta ’yantar da ni daga Dokar Musa. ");
INSERT INTO hausa_vpl VALUES ("RM8_3","075_8_3","ROM","8","3","3","Gama abin da dokar ba tă iya yi saboda kāsawar mutuntaka ba, Allah ya yi shi sa’ad da ya aiko da Ɗansa a kamannin mutum mai zunubi, don yă zama hadaya ta zunubi. Ta haka, ya hukunta zunubi a cikin mutum mai zunubi. ");
INSERT INTO hausa_vpl VALUES ("RM8_4","075_8_4","ROM","8","4","4","Ya yi haka domin yă cika bukatun adalcin doka a cikinmu, mu da ba ma rayuwa bisa ga mutuntaka, sai dai bisa ga Ruhu. ");
INSERT INTO hausa_vpl VALUES ("RM8_5","075_8_5","ROM","8","5","5","Waɗanda suke rayuwa bisa ga mutuntaka sun kafa hankulansu a kan sha’awace-shawa’acen jiki; amma waɗanda suke rayuwa bisa ga Ruhu sun kafa hankulansu a kan abubuwan da Ruhu yake so. ");
INSERT INTO hausa_vpl VALUES ("RM8_6","075_8_6","ROM","8","6","6","Ƙwallafa rai ga al’amuran halin mutuntaka ƙarshensa mutuwa ne, ƙwallafa rai ga al’amuran Ruhu kuwa rai ne da salama; ");
INSERT INTO hausa_vpl VALUES ("RM8_7","075_8_7","ROM","8","7","7","hankalin mai zunubi na gāba da Allah. Ba ya biyayya da dokar Allah, ba kuwa zai iya yin haka ba. ");
INSERT INTO hausa_vpl VALUES ("RM8_8","075_8_8","ROM","8","8","8","Waɗanda mutuntaka yake mulkinsu ba za su iya su gamshi Allah ba. ");
INSERT INTO hausa_vpl VALUES ("RM8_9","075_8_9","ROM","8","9","9","Ku kam, ana mulkinku ba ta wurin mutuntaka ba, sai dai ta wurin Ruhu, in Ruhun Allah yana zaune a cikinku. In kuma wani ba shi da Ruhun Kiristi, shi ba na Kiristi ba ne. ");
INSERT INTO hausa_vpl VALUES ("RM8_10","075_8_10","ROM","8","10","10","Amma in Kiristi yana a cikinku, jikinku matacce ne saboda zunubi, duk da haka ruhunku yana a raye saboda adalci. ");
INSERT INTO hausa_vpl VALUES ("RM8_11","075_8_11","ROM","8","11","11","In kuwa Ruhu wannan da ya tā da Yesu daga matattu yana zama a cikinku, shi wanda ya tā da Kiristi daga matattu zai ba da rai ga jikunanku masu mutuwa ta wurin Ruhunsa, wanda yake zama a cikinku. ");
INSERT INTO hausa_vpl VALUES ("RM8_12","075_8_12","ROM","8","12","12","Saboda haka ’yan’uwa, muna da hakki, amma ba na wanda za mu yi rayuwar mutuntaka da yake so ba. ");
INSERT INTO hausa_vpl VALUES ("RM8_13","075_8_13","ROM","8","13","13","Gama in kuna rayuwa bisa ga mutuntaka, za ku mutu; amma in ta wurin Ruhu kuka kashe ayyukan jikin nan, za ku rayu. ");
INSERT INTO hausa_vpl VALUES ("RM8_14","075_8_14","ROM","8","14","14","Domin waɗanda Ruhun Allah yake bi da su ne ’ya’yan Allah. ");
INSERT INTO hausa_vpl VALUES ("RM8_15","075_8_15","ROM","8","15","15","Gama ba ku karɓi ruhun da ya mai da ku bayi da za ku sāke jin tsoro ba ne, sai dai kun karɓi Ruhun zaman ɗa. Ta wurinsa kuwa muke kira, “Abba, Uba.” ");
INSERT INTO hausa_vpl VALUES ("RM8_16","075_8_16","ROM","8","16","16","Ruhu kansa yana ba da shaida tare da ruhunmu cewa mu ’ya’yan Allah ne. ");
INSERT INTO hausa_vpl VALUES ("RM8_17","075_8_17","ROM","8","17","17","In kuwa mu ’ya’ya ne, to, mu magāda ne, magādan Allah da kuma abokan gādo tare da Kiristi, in kuwa muna tarayya a cikin shan wuyarsa to, za mu yi tarayya a cikin ɗaukakarsa. ");
INSERT INTO hausa_vpl VALUES ("RM8_18","075_8_18","ROM","8","18","18","A ganina, wuyar da muke sha a wannan lokaci ba su isa a kwatanta da ɗaukakar da za a bayyana a cikinmu ba. ");
INSERT INTO hausa_vpl VALUES ("RM8_19","075_8_19","ROM","8","19","19","Halitta tana jira da marmari ta ƙosa ta ga bayyanuwar ’ya’yan Allah. ");
INSERT INTO hausa_vpl VALUES ("RM8_20","075_8_20","ROM","8","20","20","Gama an sa halitta a cikin wulaƙanci, ba da son ta ba, sai dai ta wurin nufin wannan da ya mai da ita haka, da bege ");
INSERT INTO hausa_vpl VALUES ("RM8_21","075_8_21","ROM","8","21","21","cewa za a ’yantar da halitta kanta daga bautarta ga ruɓewa a kuma kawo ta cikin ’yancin ɗaukakar ’ya’yan Allah. ");
INSERT INTO hausa_vpl VALUES ("RM8_22","075_8_22","ROM","8","22","22","Mun san cewa dukan halitta tana nishi sai ka ce mace mai naƙuda har yă zuwa wannan lokaci. ");
INSERT INTO hausa_vpl VALUES ("RM8_23","075_8_23","ROM","8","23","23","Ba haka kaɗai ba ma, mu kanmu da muke da nunan fari na Ruhu, muna nishi a ciki-cikinmu yayinda muke jira da marmari a maishe mu ’ya’yan riƙo na Allah, fansar jikunanmu. ");
INSERT INTO hausa_vpl VALUES ("RM8_24","075_8_24","ROM","8","24","24","Gama a wannan begen ne muka sami ceto. Amma begen da ake gani ba bege ba ne sam. Wa yake begen abin da ya riga ya samu? ");
INSERT INTO hausa_vpl VALUES ("RM8_25","075_8_25","ROM","8","25","25","Amma in muna begen abin da ba mu riga mun samu tukuna ba, mukan jira da haƙuri. ");
INSERT INTO hausa_vpl VALUES ("RM8_26","075_8_26","ROM","8","26","26","Haka nan ma, Ruhu yana taimakonmu cikin rashin ƙarfinmu. Ba mu san abin da ya kamata mu roƙa cikin addu’a ba, amma Ruhu kansa yana roƙo a madadinmu da nishe-nishen da kalmomi ba sa iya bayyanawa. ");
INSERT INTO hausa_vpl VALUES ("RM8_27","075_8_27","ROM","8","27","27","Shi kuma wanda yake binciken zukatanmu ya san halin Ruhu, domin Ruhu yana roƙo a madadin tsarkaka bisa ga nufin Allah. ");
INSERT INTO hausa_vpl VALUES ("RM8_28","075_8_28","ROM","8","28","28","Mun kuma san cewa a cikin dukan abubuwa Allah yana aikata alheri ga waɗanda suke ƙaunarsa, yana waɗanda aka kira bisa ga nufinsa. ");
INSERT INTO hausa_vpl VALUES ("RM8_29","075_8_29","ROM","8","29","29","Gama waɗanda Allah ya rigyasani ya kuma ƙaddara su dace da kamannin Ɗansa, don yă zama ɗan fari cikin ’yan’uwa masu yawa. ");
INSERT INTO hausa_vpl VALUES ("RM8_30","075_8_30","ROM","8","30","30","Waɗanda kuwa ya ƙaddara, su ne ya kira; waɗanda ya kira kuwa, su ne ya kuɓutar; waɗanda ya kuɓutar kuwa, su ne ya ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("RM8_31","075_8_31","ROM","8","31","31","Me za mu ce ke nan game da wannan abu? In Allah yana goyon bayanmu, wa kuwa zai iya gāba da mu? ");
INSERT INTO hausa_vpl VALUES ("RM8_32","075_8_32","ROM","8","32","32","Shi da bai hana Ɗansa ba, sai ma ya ba da shi saboda mu duka, ashe, ba zai kuma ba mu, tare da shi, dukan abubuwa cikin alherinsa ba? ");
INSERT INTO hausa_vpl VALUES ("RM8_33","075_8_33","ROM","8","33","33","Wa zai kawo wani zargi a kan waɗanda Allah ya zaɓa? Allah ne mai kuɓutarwa. ");
INSERT INTO hausa_vpl VALUES ("RM8_34","075_8_34","ROM","8","34","34","Wa zai yi hukunci? Yesu Kiristi ne, wanda ya mutu, fiye da haka ma, shi da aka tā da zuwa rai, yana zaune a hannun dama na Allah yana kuma yin roƙo a madadinmu. ");
INSERT INTO hausa_vpl VALUES ("RM8_35","075_8_35","ROM","8","35","35","Wane ne zai raba mu da ƙaunar Kiristi? Masifa ce ko wahala ko tsanani ko yunwa ko tsiraici ko hatsari ko takobi? ");
INSERT INTO hausa_vpl VALUES ("RM8_36","075_8_36","ROM","8","36","36","Kamar yadda yake a rubuce cewa, “Saboda kai ne muke fuskantar mutuwa dukan yini; an ɗauke mu kamar tumakin da za a yanka.” ");
INSERT INTO hausa_vpl VALUES ("RM8_37","075_8_37","ROM","8","37","37","A’a, cikin dukan waɗannan abubuwa mun ma fi masu nasara ta wurin shi wanda ya ƙaunace mu. ");
INSERT INTO hausa_vpl VALUES ("RM8_38","075_8_38","ROM","8","38","38","Gama na tabbata cewa ko mutuwa ko rai, ko mala’iku ko aljanu, ko abubuwa na yanzu ko abubuwa masu zuwa nan gaba, ko ikoki, ");
INSERT INTO hausa_vpl VALUES ("RM8_39","075_8_39","ROM","8","39","39","ko tsayi ko zurfi, ko wani abu dabam cikin dukan halitta da zai iya raba mu da ƙaunar Allah wadda take cikin Kiristi Yesu Ubangijinmu. ");
INSERT INTO hausa_vpl VALUES ("RM9_1","075_9_1","ROM","9","1","1","Ina faɗin gaskiya a cikin Kiristi ba ƙarya nake yi ba, lamirina ya tabbatar da wannan a cikin Ruhu Mai Tsarki. ");
INSERT INTO hausa_vpl VALUES ("RM9_2","075_9_2","ROM","9","2","2","Ina da baƙin ciki mai yawa da kuma rashin kwanciyar rai marar ƙarewa a zuciyata. ");
INSERT INTO hausa_vpl VALUES ("RM9_3","075_9_3","ROM","9","3","3","Gama da so na ne, sai a la’anta ni a kuma raba ni da Kiristi saboda ’yan’uwana, waɗannan na kabilata, ");
INSERT INTO hausa_vpl VALUES ("RM9_4","075_9_4","ROM","9","4","4","mutanen Isra’ila. Su ne Allah ya mai da su ’ya’yansa, ya bayyana musu ɗaukakarsa, ya ba su alkawarinsa da Dokarsa, ya nuna musu hanyar sujada ta gaske, ya kuma ba su sauran alkawura. ");
INSERT INTO hausa_vpl VALUES ("RM9_5","075_9_5","ROM","9","5","5","Kakannin-kakannin nan kuma nasu ne, Kiristi kuma, ta wurin zamansa mutum, na kabilarsu ne. Yabo ya tabbata ga Allah har abada, shi da yake bisa kome! Amin. ");
INSERT INTO hausa_vpl VALUES ("RM9_6","075_9_6","ROM","9","6","6","Ba cewa maganar Allah ta kāsa ba ne. Gama ba duk waɗanda suke zuriyar Isra’ila ne suke Isra’ila na gaske ba. ");
INSERT INTO hausa_vpl VALUES ("RM9_7","075_9_7","ROM","9","7","7","Ba kuwa don su zuriyarsa ne dukansu suka zama ’ya’yan Ibrahim ba. A maimako, “Ta wurin Ishaku ne za a lissafta zuriyarka.” ");
INSERT INTO hausa_vpl VALUES ("RM9_8","075_9_8","ROM","9","8","8","Ana iya cewa zaman zuriyar Ibrahim, ba shi ne zama ’ya’yan Allah ba, a’a, zuriya ta alkawarin nan su ne ake lasaftawa zuriyar Ibrahim. ");
INSERT INTO hausa_vpl VALUES ("RM9_9","075_9_9","ROM","9","9","9","Ga yadda aka yi alkawarin nan, “A ƙayyadadden lokaci zan dawo, Saratu kuma za tă haifi ɗa.” ");
INSERT INTO hausa_vpl VALUES ("RM9_10","075_9_10","ROM","9","10","10","Ba ma haka kaɗai ba, ’ya’yan Rifkatu suna da mahaifi guda ne, wato, mahaifinmu Ishaku. ");
INSERT INTO hausa_vpl VALUES ("RM9_11","075_9_11","ROM","9","11","11","Duk da haka, tun ba a haifi tagwayen nan ba, balle su yi wani abu mai kyau ko marar kyau don nufin Allah bisa ga zaɓensa ya tabbata, ba ga aikin lada ba, sai dai ga kiransa, ");
INSERT INTO hausa_vpl VALUES ("RM9_12","075_9_12","ROM","9","12","12","ba ta wurin ayyuka ba sai dai ta wurin shi wanda ya kira, aka faɗa mata cewa, “Babban zai bauta wa ƙaramin.” ");
INSERT INTO hausa_vpl VALUES ("RM9_13","075_9_13","ROM","9","13","13","Kamar yadda yake a rubuce cewa, “Yaƙub ne na so, amma Isuwa ne na ƙi.” ");
INSERT INTO hausa_vpl VALUES ("RM9_14","075_9_14","ROM","9","14","14","Me za mu ce ke nan? Allah marar adalci ne? Sam, ko kaɗan! ");
INSERT INTO hausa_vpl VALUES ("RM9_15","075_9_15","ROM","9","15","15","Gama ya ce wa Musa, “Zan nuna jinƙai ga wanda zan nuna jinƙai, zan kuma ji tausayin wanda zan ji tausayi.” ");
INSERT INTO hausa_vpl VALUES ("RM9_16","075_9_16","ROM","9","16","16","Saboda haka, bai danganta ga sha’awar mutum ko ƙoƙarinsa ba, sai dai ga jinƙan Allah. ");
INSERT INTO hausa_vpl VALUES ("RM9_17","075_9_17","ROM","9","17","17","Gama Nassi ya ce wa Fir’auna, “Na ɗaga ka saboda wannan manufa, saboda in nuna ikona a cikinka domin kuma a shaida sunana a duniya duka.” ");
INSERT INTO hausa_vpl VALUES ("RM9_18","075_9_18","ROM","9","18","18","Saboda haka Allah yana nuna jinƙai ga wanda yake so, yana kuma taurara zuciyar wanda yake so. ");
INSERT INTO hausa_vpl VALUES ("RM9_19","075_9_19","ROM","9","19","19","Waninku zai iya ce mini, “To, don me har yanzu Allah yake ganin laifinmu? Gama wa zai iya tsayayya da nufinsa?” ");
INSERT INTO hausa_vpl VALUES ("RM9_20","075_9_20","ROM","9","20","20","Amma wane ne kai, ya mutum, da za ka mayar wa Allah magana? “Ashe, abin da aka gina zai iya ce wa wanda ya gina shi, ‘Don me ka gina ni haka?’ ” ");
INSERT INTO hausa_vpl VALUES ("RM9_21","075_9_21","ROM","9","21","21","Ashe, mai ginin tukwane ba shi da iko yin amfani da yumɓu guda yă gina tukunya domin ayyuka masu daraja da kuma waɗansu don ayyuka marasa daraja? ");
INSERT INTO hausa_vpl VALUES ("RM9_22","075_9_22","ROM","9","22","22","Haka ma aikin Allah yake. Ya so yă nuna fushinsa yă kuma sanar da ikonsa, ya yi haka cikin haƙuri ƙwarai ga waɗanda suka cancanci fushinsa, waɗanda aka shirya domin hallaka? ");
INSERT INTO hausa_vpl VALUES ("RM9_23","075_9_23","ROM","9","23","23","Haka kuma ya so yă sanar da wadatar ɗaukakarsa ga waɗanda suka cancanci jinƙansa, waɗanda ya shirya tun kafin lokaci don ɗaukaka ");
INSERT INTO hausa_vpl VALUES ("RM9_24","075_9_24","ROM","9","24","24","har da mu ma, mu da ya kira, ba daga cikin Yahudawa kaɗai ba amma har ma daga cikin Al’ummai? ");
INSERT INTO hausa_vpl VALUES ("RM9_25","075_9_25","ROM","9","25","25","Kamar yadda ya faɗa a Hosiya. “Zan kira su ‘mutanena,’ su da ba mutanena ba; zan kuma kira ta ‘ƙaunatacciyata,’ ita da ba ƙaunatacciyata ba,” ");
INSERT INTO hausa_vpl VALUES ("RM9_26","075_9_26","ROM","9","26","26","kuma, “Zai zama cewa a daidai inda aka ce musu, ‘Ku ba mutanena ba,’ za a ce da su, ‘’ya’yan Allah mai rai.’ ” ");
INSERT INTO hausa_vpl VALUES ("RM9_27","075_9_27","ROM","9","27","27","Ishaya ya ɗaga murya game da Isra’ila ya ce, “Ko da yake yawan Isra’ilawa yana kama da yashi a bakin teku, ragowa ce kaɗai za su sami ceto. ");
INSERT INTO hausa_vpl VALUES ("RM9_28","075_9_28","ROM","9","28","28","Gama Ubangiji zai zartar da hukuncinsa a bisan duniya da sauri kuma ba da ɓata lokaci ba.” ");
INSERT INTO hausa_vpl VALUES ("RM9_29","075_9_29","ROM","9","29","29","Yana nan kamar yadda Ishaya ya riga ya faɗa. “Da ba don Ubangiji Maɗaukaki ya bar mana zuriya ba, da mun zama kamar Sodom, da mun kuma zama kamar Gomorra.” ");
INSERT INTO hausa_vpl VALUES ("RM9_30","075_9_30","ROM","9","30","30","Me za mu ce ke nan? Ai, Al’ummai da ba su nemi adalci ba, sun same shi, adalcin da yake ta wurin bangaskiya; ");
INSERT INTO hausa_vpl VALUES ("RM9_31","075_9_31","ROM","9","31","31","amma Isra’ila da suka yi ƙwazo wajen bin Dokar adalci, ba su same shi ba. ");
INSERT INTO hausa_vpl VALUES ("RM9_32","075_9_32","ROM","9","32","32","Don me? Domin sun yi ƙwazo wajen binta ba ta wurin bangaskiya ba sai dai ta wurin ayyuka. Sun yi tuntuɓe a kan “dutsen sa tuntuɓe.” ");
INSERT INTO hausa_vpl VALUES ("RM9_33","075_9_33","ROM","9","33","33","Kamar yadda yake a rubuce, “Ga shi, na sa dutse a Sihiyona da yake sa mutane yin tuntuɓe da kuma dutsen da yake sa su fāɗi wanda kuwa ya dogara gare shi ba zai taɓa shan kunya ba.” ");
INSERT INTO hausa_vpl VALUES ("RM10_1","075_10_1","ROM","10","1","1","’Yan’uwa, abin da zuciyata take so da kuma addu’ata ga Allah saboda Isra’ilawa shi ne su sami ceto. ");
INSERT INTO hausa_vpl VALUES ("RM10_2","075_10_2","ROM","10","2","2","Gama na shaida su a kan suna da kishi bin Allah, sai dai kishinsu ba a bisa sani ba. ");
INSERT INTO hausa_vpl VALUES ("RM10_3","075_10_3","ROM","10","3","3","Da yake ba su san adalcin da yake fitowa daga Allah ba suka kuma nemi su kafa nasu, sai suka ƙi miƙa kai ga adalcin Allah. ");
INSERT INTO hausa_vpl VALUES ("RM10_4","075_10_4","ROM","10","4","4","Kiristi shi ne ƙarshen doka domin a sami adalci wa kowane mai bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("RM10_5","075_10_5","ROM","10","5","5","Musa ya bayyana adalcin da yake ga Doka cewa, “Mutumin da ya aikata waɗannan abubuwa zai rayu ta wurinsu.” ");
INSERT INTO hausa_vpl VALUES ("RM10_6","075_10_6","ROM","10","6","6","Amma adalcin da yake ga bangaskiya yana cewa, “Kada ka faɗa a zuciyarka, ‘Wa zai hau sama?’ ” (wato, don yă sauko da Kiristi), ");
INSERT INTO hausa_vpl VALUES ("RM10_7","075_10_7","ROM","10","7","7","“ko kuwa ‘Wa zai gangara can zurfin ƙasa?’ ” (wato, don yă hauro da Kiristi daga matattu). ");
INSERT INTO hausa_vpl VALUES ("RM10_8","075_10_8","ROM","10","8","8","Amma mene ne aka ce? “Maganar tana kusa da kai; tana cikin bakinka da kuma cikin zuciyarka,” wato, maganar bangaskiyan nan da muke shela. ");
INSERT INTO hausa_vpl VALUES ("RM10_9","075_10_9","ROM","10","9","9","Cewa in ka furta da bakinka, “Yesu Ubangiji ne,” ka kuma gaskata a zuciyarka cewa Allah ya tā da shi daga matattu, za ka sami ceto. ");
INSERT INTO hausa_vpl VALUES ("RM10_10","075_10_10","ROM","10","10","10","Gama da zuciyarka ce kakan gaskata a kuma kuɓutar da kai, da bakinka ne kuma kake furta a kuma cece ka. ");
INSERT INTO hausa_vpl VALUES ("RM10_11","075_10_11","ROM","10","11","11","Kamar yadda Nassi ya ce, “Duk wanda ya gaskata da shi ba zai taɓa shan kunya ba.” ");
INSERT INTO hausa_vpl VALUES ("RM10_12","075_10_12","ROM","10","12","12","Gama ba bambanci tsakanin mutumin Yahuda da mutumin Al’ummai, Ubangijin nan ɗaya shi ne Ubangijin kowa yana kuma ba da albarka a yalwace ga duk masu kira gare shi, ");
INSERT INTO hausa_vpl VALUES ("RM10_13","075_10_13","ROM","10","13","13","gama, “Duk wanda ya kira bisa sunan Ubangiji zai sami ceto.” ");
INSERT INTO hausa_vpl VALUES ("RM10_14","075_10_14","ROM","10","14","14","To, ta yaya za su kira ga wanda ba su gaskata ba? Ta yaya kuma za su gaskata wanda ba su taɓa ji ba? Ta yaya kuma za su ji ba tare da wani ya yi musu wa’azi ba? ");
INSERT INTO hausa_vpl VALUES ("RM10_15","075_10_15","ROM","10","15","15","Kuma ta yaya za su yi wa’azi in ba an aike su ba? Kamar yadda yake a rubuce cewa, “Isowar masu kawo labari mai daɗi abu mai kyau ne ƙwarai!” ");
INSERT INTO hausa_vpl VALUES ("RM10_16","075_10_16","ROM","10","16","16","Amma ba dukan Isra’ilawa ne suka karɓi labari mai daɗin nan ba. Gama Ishaya ya ce, “Ubangiji, wa ya gaskata saƙonmu?” ");
INSERT INTO hausa_vpl VALUES ("RM10_17","075_10_17","ROM","10","17","17","Saboda haka, bangaskiya takan zo ne ta wurin jin saƙo, akan ji saƙon kuma ta wurin maganar Kiristi. ");
INSERT INTO hausa_vpl VALUES ("RM10_18","075_10_18","ROM","10","18","18","Amma ina tambaya, “Ba su ji ba ne? Tabbatacce sun ji. “Muryarsu ta tafi ko’ina a cikin duniya, kalmominsu kuma har iyakar duniya.” ");
INSERT INTO hausa_vpl VALUES ("RM10_19","075_10_19","ROM","10","19","19","Har wa yau, ina da tambaya. Shin, Isra’ila ba su fahimta ba ne? Da farko, Musa ya ce, “Zan sa ku yi kishin waɗanda ba al’umma ba; zan sa ku yi fushin al’ummar da ba ta da fahimta.” ");
INSERT INTO hausa_vpl VALUES ("RM10_20","075_10_20","ROM","10","20","20","Ishaya kuma ya fito gabagadi ya ce, “Waɗanda ba su neme ni ba, su suka same ni; Na bayyana kaina ga waɗanda ba su ma taɓa neman sanina ba.” ");
INSERT INTO hausa_vpl VALUES ("RM10_21","075_10_21","ROM","10","21","21","Amma game da Isra’ila ya ce, “Dukan yini na miƙa hannuwana ga mutane marasa biyayya da masu taurinkai.” ");
INSERT INTO hausa_vpl VALUES ("RM11_1","075_11_1","ROM","11","1","1","To, ina da tambaya. Allah ya ƙi mutanensa ne? Sam, ko kaɗan! Ni mutumin Isra’ila ne kaina, zuriyar Ibrahim kuwa, daga kabilar Benyamin. ");
INSERT INTO hausa_vpl VALUES ("RM11_2","075_11_2","ROM","11","2","2","Allah bai ƙi mutanensa da ya rigya sani ba. Ba ku san abin da Nassi ya faɗa game da Iliya ba, yadda ya kawo kuka ga Allah a kan Isra’ila ya ce, ");
INSERT INTO hausa_vpl VALUES ("RM11_3","075_11_3","ROM","11","3","3","“Ya Ubangiji, sun karkashe annabawanka suka kuma rurrushe bagadanka; ni kaɗai na ragu, suna kuma neman raina”? ");
INSERT INTO hausa_vpl VALUES ("RM11_4","075_11_4","ROM","11","4","4","Wace amsa ce Allah ya ba shi? “Na keɓe wa kaina dubu bakwai waɗanda ba su yi wa Ba’al sujada ba.” ");
INSERT INTO hausa_vpl VALUES ("RM11_5","075_11_5","ROM","11","5","5","Haka ma, a wannan zamani akwai ragowar da aka zaɓa ta wurin alheri. ");
INSERT INTO hausa_vpl VALUES ("RM11_6","075_11_6","ROM","11","6","6","In kuwa na alheri ne, ba sauran cewa ya dogara ga ayyuka ke nan. In ba haka ba, ashe, alheri ba alheri ba ne kuma. ");
INSERT INTO hausa_vpl VALUES ("RM11_7","075_11_7","ROM","11","7","7","To, sai me? Abin da Isra’ila suka nema da himma ba su samu ba, amma zaɓaɓɓun suka samu. Sauran suka taurare, ");
INSERT INTO hausa_vpl VALUES ("RM11_8","075_11_8","ROM","11","8","8","kamar yadda yake a rubuce cewa, “Allah ya ba su ruhun ruɗewa, idanu don su kāsa gani, da kuma kunnuwa don su kāsa ji, har yă zuwa yau.” ");
INSERT INTO hausa_vpl VALUES ("RM11_9","075_11_9","ROM","11","9","9","Dawuda kuma ya ce, “Bari teburin cin abincinsu yă zama musu tarko, sanadin fāɗuwa da dutsen sa tuntuɓe da kuma ramuwa a kansu. ");
INSERT INTO hausa_vpl VALUES ("RM11_10","075_11_10","ROM","11","10","10","Bari idanunsu su duhunta don kada su iya gani, bayansu kuma yă tanƙware har abada.” ");
INSERT INTO hausa_vpl VALUES ("RM11_11","075_11_11","ROM","11","11","11","Har yanzu ina da tambaya. Sun yi tuntuɓe har ya kai ga fāɗuwar da ba za su iya tashi ba ne? Sam, ko kaɗan! A maimako, saboda laifinsu ne ceto ya zo ga Al’ummai don a sa mutanen Isra’ila su ji kishi. ");
INSERT INTO hausa_vpl VALUES ("RM11_12","075_11_12","ROM","11","12","12","Amma in laifinsu yana nufin albarka ga duniya, hasararsu kuma albarka ga Al’ummai, ina misalin yalwar da albarkunsu za su kawo! ");
INSERT INTO hausa_vpl VALUES ("RM11_13","075_11_13","ROM","11","13","13","Ina magana da ku ne fa Al’ummai. Tun da yake ni manzo ne ga Al’ummai, ina taƙama da aikin nan nawa, ");
INSERT INTO hausa_vpl VALUES ("RM11_14","075_11_14","ROM","11","14","14","da fata zan rura kabilata a ta kowace hanya su ji kishi har ma yă sa in ceci waɗansunsu. ");
INSERT INTO hausa_vpl VALUES ("RM11_15","075_11_15","ROM","11","15","15","Gama in ƙinsu da aka yi ya zama sulhu ga duniya, me karɓarsu za tă zama in ba rai daga matattu ba? ");
INSERT INTO hausa_vpl VALUES ("RM11_16","075_11_16","ROM","11","16","16","In sashen da aka miƙa a matsayin nunan fari tsattsarka ne, to, sauran ma tsattsarka ne; in saiwar tsattsarka ce, to, sauran rassan ma tsattsarka ne. ");
INSERT INTO hausa_vpl VALUES ("RM11_17","075_11_17","ROM","11","17","17","In an sassare waɗansu rassa, kai kuwa da kake kai zaitun jeji, aka ɗauke ka aka kuma yi muku aure, a yanzu kuwa kana shan ni’imar saiwar zaitun ɗin nan tare da sauran rassan, ");
INSERT INTO hausa_vpl VALUES ("RM11_18","075_11_18","ROM","11","18","18","kada ka yi taƙama cewa ka fi waɗancan rassan da aka sassare. In kuwa ka yi haka, to, ka yi la’akari da wannan. Ba kai ne kake taimakon saiwar ba, saiwar ce take taimakonka. ");
INSERT INTO hausa_vpl VALUES ("RM11_19","075_11_19","ROM","11","19","19","To, kana iya cewa, “An sassare rassan ne don a ɗaura aure da ni.” ");
INSERT INTO hausa_vpl VALUES ("RM11_20","075_11_20","ROM","11","20","20","Haka yake. Amma an sassare su ne saboda rashin bangaskiya, kai kuma kana tsaye ta wurin bangaskiya. Kada ka yi taƙama, sai dai ka ji tsoro. ");
INSERT INTO hausa_vpl VALUES ("RM11_21","075_11_21","ROM","11","21","21","Gama in har Allah bai bar rassan nan na asali ba, kai ma ba zai bar ka ba. ");
INSERT INTO hausa_vpl VALUES ("RM11_22","075_11_22","ROM","11","22","22","Ka lura fa da alheri da kuma tsananin Allah, tsanani ga waɗanda suka fāɗi, amma alheri a gare ka, da fata za ka ci gaba cikin alherinsa. In ba haka ba, kai ma za a sare ka. ");
INSERT INTO hausa_vpl VALUES ("RM11_23","075_11_23","ROM","11","23","23","In kuwa ba su nace cikin rashin bangaskiya ba, za a sāke ɗaura aure da su, domin Allah yana iya sāke haɗa su. ");
INSERT INTO hausa_vpl VALUES ("RM11_24","075_11_24","ROM","11","24","24","Kai ma da aka saro daga zaitun ɗin da asalinsa yake na jeji, aka ɗaura aure da kai a jikin zaitun ɗin na gida, saɓanin yadda aka saba, balle waɗannan rassa na asali, da za a ɗaura aure da su a jikin zaitun ɗin nan nasu na asali? ");
INSERT INTO hausa_vpl VALUES ("RM11_25","075_11_25","ROM","11","25","25","Ba na so ku kasance cikin rashin sani game da wannan asirin ’yan’uwa, domin kada ku ɗaga kai. Isra’ila sun ɗanɗana sashe na taurarewa har sai da shigowar Al’ummai masu yawa ya cika. ");
INSERT INTO hausa_vpl VALUES ("RM11_26","075_11_26","ROM","11","26","26","Ta haka kuwa za a ceci dukan Isra’ila, kamar yadda yake a rubuce cewa, “Mai ceto zai zo daga Sihiyona; zai kawar da rashin bin Allah daga Yaƙub. ");
INSERT INTO hausa_vpl VALUES ("RM11_27","075_11_27","ROM","11","27","27","Wannan kuwa shi ne alkawarina da su sa’ad da na ɗauke musu zunubansu.” ");
INSERT INTO hausa_vpl VALUES ("RM11_28","075_11_28","ROM","11","28","28","Game da zancen nan na bishara kuwa, su abokan gāba ne saboda ku; amma game da zaɓen kuwa, su ƙaunatattunsa ne, albarkacin kakannin kakanninsu, ");
INSERT INTO hausa_vpl VALUES ("RM11_29","075_11_29","ROM","11","29","29","gama kyautar Allah da kiransa ba a sokewa. ");
INSERT INTO hausa_vpl VALUES ("RM11_30","075_11_30","ROM","11","30","30","Kamar yadda a dā can ku da kuke marasa biyayya ga Allah kuka sami jinƙai yanzu ta dalilin rashin biyayyarsu, ");
INSERT INTO hausa_vpl VALUES ("RM11_31","075_11_31","ROM","11","31","31","haka su ma suka zama marasa biyayya a yanzu domin su ma su sami jinƙai ta dalilin jinƙan da Allah ya yi muku. ");
INSERT INTO hausa_vpl VALUES ("RM11_32","075_11_32","ROM","11","32","32","Gama Allah ya daure dukan mutane ga rashin biyayya don yă nuna jinƙai ga kowa. ");
INSERT INTO hausa_vpl VALUES ("RM11_33","075_11_33","ROM","11","33","33","Kai, zurfin yalwar hikima da kuma sanin Allah yana nan a yalwace! Hukunce-hukuncensa kuma su fi gaban bincike, hanyoyinsa kuwa sun wuce gaban ganewa! ");
INSERT INTO hausa_vpl VALUES ("RM11_34","075_11_34","ROM","11","34","34","“Wa ya taɓa sanin zuciyar Ubangiji? Ko kuwa yă ba shi shawara?” ");
INSERT INTO hausa_vpl VALUES ("RM11_35","075_11_35","ROM","11","35","35","“Wa ya taɓa ba wa Allah wani abu, da Allah zai sāka masa?” ");
INSERT INTO hausa_vpl VALUES ("RM11_36","075_11_36","ROM","11","36","36","Gama daga gare shi, ta wurinsa, da kuma saboda shi ne dukan abubuwa suka kasance. Ɗaukaka ta tabbata a gare shi har abada! Amin. ");
INSERT INTO hausa_vpl VALUES ("RM12_1","075_12_1","ROM","12","1","1","Saboda haka, ina roƙonku, ’yan’uwa, saboda yawan jinƙan Allah, ku miƙa jikunanku hadaya wadda take mai rai, mai tsarki abin karɓa kuma ga Allah, wannan ita ce hanyar hidimarku ta ruhaniya. ");
INSERT INTO hausa_vpl VALUES ("RM12_2","075_12_2","ROM","12","2","2","Kada ku ci gaba da yin abin da duniya take yi, sai dai ku bar halinku ya sāke, ta wurin sabunta hankalinku ɗungum, don ku tabbatar da abin da Allah yake so yake, abu mai kyau, mai daɗi da kuma cikakke. ");
INSERT INTO hausa_vpl VALUES ("RM12_3","075_12_3","ROM","12","3","3","Gama ta wurin alherin nan da aka yi mini ne ina ce wa kowannenku. Kada yă ɗauki kansa fiye da yadda ya kamata, a maimakon haka bari yă auna kansa cikin natsuwa, gwargwadon baiwar bangaskiyar da Allah yi masa. ");
INSERT INTO hausa_vpl VALUES ("RM12_4","075_12_4","ROM","12","4","4","Kamar dai yadda kowannenmu yake da jiki ɗaya da gaɓoɓi da yawa, gaɓoɓin nan kuwa ba aiki iri ɗaya suke yi ba, ");
INSERT INTO hausa_vpl VALUES ("RM12_5","075_12_5","ROM","12","5","5","haka ma a cikin Kiristi mu da muke da yawa mun zama jiki ɗaya, kuma kowace gaɓar ɗan’uwan sauran ne. ");
INSERT INTO hausa_vpl VALUES ("RM12_6","075_12_6","ROM","12","6","6","Muna da baye-baye dabam-dabam, gwargwadon alherin da aka yi mana. In baiwar mutum ta yin annabci ce, sai yă yi amfani da ita gwargwadon bangaskiyarsa. ");
INSERT INTO hausa_vpl VALUES ("RM12_7","075_12_7","ROM","12","7","7","In ta hidima ce; sai yă yi hidima. In kuma ta koyarwa ce, sai yă koyar; ");
INSERT INTO hausa_vpl VALUES ("RM12_8","075_12_8","ROM","12","8","8","in ta ƙarfafawa ce, sai yă ƙarfafa; in kuma ta ba da taimako ce don biyan bukatun waɗansu, sai yă yi haka hannu sake; in ta shugabanci ce, sai yă yi shugabanci da himma; in ta nuna jinƙai ce, sai yă yi haka da fara’a. ");
INSERT INTO hausa_vpl VALUES ("RM12_9","075_12_9","ROM","12","9","9","Dole ƙauna tă zama ta gaskiya. Ku ƙi duk abin da yake mugu; ku manne wa abin da yake nagari. ");
INSERT INTO hausa_vpl VALUES ("RM12_10","075_12_10","ROM","12","10","10","Ku ba da kanku ga juna cikin ƙauna irin ta ’yan’uwa. Kowa yă yi ƙoƙari wajen girmama wani fiye da kansa. ");
INSERT INTO hausa_vpl VALUES ("RM12_11","075_12_11","ROM","12","11","11","Kada ku zama marasa himma, sai dai masu himma a ruhaniyarku, kuna bauta wa Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("RM12_12","075_12_12","ROM","12","12","12","Ku yi farin ciki cikin bege, haƙuri cikin shan wuya, aminci cikin addu’a. ");
INSERT INTO hausa_vpl VALUES ("RM12_13","075_12_13","ROM","12","13","13","Ku taimaki mutanen Allah masu bukata. Ku zama masu karɓan baƙi. ");
INSERT INTO hausa_vpl VALUES ("RM12_14","075_12_14","ROM","12","14","14","Ku sa wa masu tsananta muku albarka; ku sa albarka kada fa ku la’anta. ");
INSERT INTO hausa_vpl VALUES ("RM12_15","075_12_15","ROM","12","15","15","Ku yi murna da masu murna, ku yi kuka da masu kuka. ");
INSERT INTO hausa_vpl VALUES ("RM12_16","075_12_16","ROM","12","16","16","Ku yi zaman lafiya da juna. Kada ku nuna girman kai, sai ma ku riƙa cuɗanya da talakawa. Kada ku zama masu ɗaga kai. ");
INSERT INTO hausa_vpl VALUES ("RM12_17","075_12_17","ROM","12","17","17","Idan kowa ya yi muku mugunta, kada ku sāka masa da mugunta. Ku lura don ku aikata abin da kowa zai iya gani cewa daidai ne. ");
INSERT INTO hausa_vpl VALUES ("RM12_18","075_12_18","ROM","12","18","18","Ku yi iya ƙoƙarinku, in zai yiwu, ku yi zaman lafiya da kowa. ");
INSERT INTO hausa_vpl VALUES ("RM12_19","075_12_19","ROM","12","19","19","Kada ku yi ramuwa, abokaina, sai dai ku bar wa Allah. Gama a rubuce yake cewa, “Ramuwa tawa ce; zan kuwa sāka,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("RM12_20","075_12_20","ROM","12","20","20","A maimakon haka, “In abokin gābanka yana jin yunwa, ka ciyar da shi; in yana jin ƙishirwa, ka ba shi ruwan sha. Ta yin haka, za ka tara garwashin wuta a kansa.” ");
INSERT INTO hausa_vpl VALUES ("RM12_21","075_12_21","ROM","12","21","21","Kada ku bar mugunta ta sha kanku, sai dai ku sha kan mugunta ta wurin aikata nagarta. ");
INSERT INTO hausa_vpl VALUES ("RM13_1","075_13_1","ROM","13","1","1","Dole kowa yă yi biyayya ga masu mulki, gama babu wani iko sai ko in Allah ya yarda. Duk hukumomin da muke su, naɗin Allah ne. ");
INSERT INTO hausa_vpl VALUES ("RM13_2","075_13_2","ROM","13","2","2","Saboda haka, duk wanda ya yi tawaye ga hukuma yana yin tawaye da abin da Allah ya naɗa ne, waɗanda kuwa suke aikata haka, za su jawo wa kansu hukunci. ");
INSERT INTO hausa_vpl VALUES ("RM13_3","075_13_3","ROM","13","3","3","Gama masu mulki ba abin tsoro ba ne ga waɗanda suke yin abin da yake daidai, sai dai ga waɗanda suke aikata laifi. Kana so ka rabu da jin tsoron wanda yake mulki? To, sai ka aikata abin da yake daidai, zai kuwa yabe ka. ");
INSERT INTO hausa_vpl VALUES ("RM13_4","075_13_4","ROM","13","4","4","Gama shi bawan Allah ne don kyautata rayuwarka. Amma in ka aikata mugunta, to, sai ka ji tsoro, don ba a banza ne shugaba yake ɗaukan takobinsa ba. Shi fa bawan Allah ne, ta wurinsa ne fushin Allah yakan hukunta masu laifi. ");
INSERT INTO hausa_vpl VALUES ("RM13_5","075_13_5","ROM","13","5","5","Saboda haka, dole a yi biyayya ga hukumomi, ba don gudun horo kawai ba amma don lamirinku. ");
INSERT INTO hausa_vpl VALUES ("RM13_6","075_13_6","ROM","13","6","6","Shi ne ma ya sa kuke biyan haraji, gama hukumomin nan bayin Allah ne, waɗanda suke ba da dukan lokacinsu don aikin shugabanci. ");
INSERT INTO hausa_vpl VALUES ("RM13_7","075_13_7","ROM","13","7","7","Ku ba wa kowa hakkinsa. In kuna da bashin haraji, sai ku biya; in kuɗin shiga ne, ku biya kuɗin shiga; in ladabi ne, ku yi ladabi; in kuma girmamawa ne, ku ba da girma. ");
INSERT INTO hausa_vpl VALUES ("RM13_8","075_13_8","ROM","13","8","8","Kada hakkin kowa yă zauna a kanku, sai dai na ƙaunar juna, don mai ƙaunar maƙwabcinsa ya cika Doka ke nan. ");
INSERT INTO hausa_vpl VALUES ("RM13_9","075_13_9","ROM","13","9","9","Umarnan nan, “Kada ka yi zina.” “Kada ka yi kisankai.” “Kada ka yi sata.” “Kada kuma ka yi ƙyashi.” Da dai duk sauran umarnai an ƙunshe su ne a wannan kalma “Ka ƙaunaci maƙwabcinka kamar kanka.” ");
INSERT INTO hausa_vpl VALUES ("RM13_10","075_13_10","ROM","13","10","10","Ƙauna ba ta cutar da maƙwabci. Saboda haka ƙauna cika Doka ce. ");
INSERT INTO hausa_vpl VALUES ("RM13_11","075_13_11","ROM","13","11","11","Ku yi wannan domin kun san irin zamanin da kuke ciki. Lokaci ya yi da za ku farka daga barcinku, don cetonmu ya yi kusa yanzu fiye da lokacin da muka fara ba da gaskiya. ");
INSERT INTO hausa_vpl VALUES ("RM13_12","075_13_12","ROM","13","12","12","Dare fa ya kusan ƙarewa; gari kuma yana gab da wayewa. Saboda haka bari mu kawar da ayyukan duhu mu kuma yafa kayan yaƙi na haske. ");
INSERT INTO hausa_vpl VALUES ("RM13_13","075_13_13","ROM","13","13","13","Bari mu tafiyar da al’amuranmu yadda ya dace a yi da rana, ba a cikin shashanci da buguwa ba, ba cikin fasikanci da rashin kunya ba, ba kuma cikin faɗa da kishi ba. ");
INSERT INTO hausa_vpl VALUES ("RM13_14","075_13_14","ROM","13","14","14","A maimakon haka, ku ɗauki halin Ubangiji Yesu Kiristi, kada kuma ku yi tunani game da yadda za ku gamsar da sha’awace-sha’awacen mutuntaka. ");
INSERT INTO hausa_vpl VALUES ("RM14_1","075_14_1","ROM","14","1","1","Ku karɓi wanda bangaskiyarsa ba tă yi ƙarfi ba, amma fa kada ku hukunta shi a kan abubuwan da ake da shakka a kai ba. ");
INSERT INTO hausa_vpl VALUES ("RM14_2","075_14_2","ROM","14","2","2","Bangaskiyar mutum ta yarda masa yă ci kome, amma wanda bangaskiyarsa ba tă yi ƙarfi ba, yakan ci kayan lambu ne kawai. ");
INSERT INTO hausa_vpl VALUES ("RM14_3","075_14_3","ROM","14","3","3","Mutumin da yake cin kowane irin abinci, kada yă rena wanda ba ya cin, wanda kuma ba ya cin kowane irin abinci, kada yă ga laifin mutumin da yake ci, domin Allah ya riga ya karɓe shi. ");
INSERT INTO hausa_vpl VALUES ("RM14_4","075_14_4","ROM","14","4","4","Kai wane ne har da za ka ga laifin bawan wani? Ko bawan yă yi aiki mai kyau, ko yă kāsa, ai, wannan ruwan maigidansa ne. Za a ma tsai da shi, domin Ubangiji yana da ikon tsai da shi. ");
INSERT INTO hausa_vpl VALUES ("RM14_5","075_14_5","ROM","14","5","5","Wani yakan ɗauki wata rana da daraja fiye da sauran ranaku; wani kuma yana ganin dukan ranakun ɗaya ne. Ya kamata kowa yă kasance da tabbaci a cikin zuciyarsa. ");
INSERT INTO hausa_vpl VALUES ("RM14_6","075_14_6","ROM","14","6","6","Wannan mai ɗaukan rana ɗaya da muhimmanci fiye da sauran, yana yin haka ne ga Ubangiji. Wannan mai cin nama, yana yin haka ne ga Ubangiji, gama yakan yi godiya ga Allah; wannan da ba ya ci kuwa, yana yin haka ne ga Ubangiji yana kuwa yin godiya ga Allah. ");
INSERT INTO hausa_vpl VALUES ("RM14_7","075_14_7","ROM","14","7","7","Gama ba waninmu da yake rayuwa wa kansa kaɗai, kuma ba waninmu da kan mutu don kansa kaɗai. ");
INSERT INTO hausa_vpl VALUES ("RM14_8","075_14_8","ROM","14","8","8","In muna rayuwa, muna rayuwa ne ga Ubangiji; in kuma muna mutuwa, muna mutuwa ne ga Ubangiji. Saboda haka, ko muna a raye ko muna a mace, mu na Ubangiji ne. ");
INSERT INTO hausa_vpl VALUES ("RM14_9","075_14_9","ROM","14","9","9","Saboda wannan ne Kiristi ya mutu, ya kuma sāke rayuwa domin yă zama Ubangiji na matattu da na masu rai. ");
INSERT INTO hausa_vpl VALUES ("RM14_10","075_14_10","ROM","14","10","10","Kai kuwa, don me kake ganin laifin ɗan’uwanka? Ko kuma don me kake rena ɗan’uwanka? Gama duk za mu tsaya a gaban kujerar shari’ar Allah. ");
INSERT INTO hausa_vpl VALUES ("RM14_11","075_14_11","ROM","14","11","11","A rubuce yake cewa, “ ‘Muddin ina raye,’ in ji Ubangiji, ‘kowace gwiwa za tă durƙusa a gabana; kowane harshe kuma zai furta wa Allah.’ ” ");
INSERT INTO hausa_vpl VALUES ("RM14_12","075_14_12","ROM","14","12","12","Don haka kowannenmu zai ba da lissafin kansa ga Allah. ");
INSERT INTO hausa_vpl VALUES ("RM14_13","075_14_13","ROM","14","13","13","Saboda haka bari mu daina ba wa juna laifi. A maimakon, sai kowa yă yi niyya ba zai sa dutsen tuntuɓe ko abin sa fāɗuwa a hanyar ɗan’uwansa ba. ");
INSERT INTO hausa_vpl VALUES ("RM14_14","075_14_14","ROM","14","14","14","A matsayina na mai bin Ubangiji Yesu na tabbata ƙwarai cewa babu abincin da yake marar tsabta don kansa. Amma in wani ya ɗauka wani abu marar tsabta ne, to, a gare shi marar tsabta ne. ");
INSERT INTO hausa_vpl VALUES ("RM14_15","075_14_15","ROM","14","15","15","In kana ɓata wa ɗan’uwanka zuciya saboda abincin da kake ci, ba halin ƙauna kake nunawa ba ke nan. Kada abincin da kake ci yă zama hanyar lalatar da ɗan’uwanka wanda Kiristi ya mutu dominsa. ");
INSERT INTO hausa_vpl VALUES ("RM14_16","075_14_16","ROM","14","16","16","Kada ka bar abin da ka ɗauka a matsayi kyakkyawa yă zama abin zargi ga waɗansu. ");
INSERT INTO hausa_vpl VALUES ("RM14_17","075_14_17","ROM","14","17","17","Gama mulkin Allah ba batun ci da sha ba ne, sai dai na adalci, salama, da kuma farin ciki cikin Ruhu Mai Tsarki, ");
INSERT INTO hausa_vpl VALUES ("RM14_18","075_14_18","ROM","14","18","18","duk kuwa wanda yake bauta wa Kiristi a haka yana faranta wa Allah rai ne, yardajje kuma ga mutane. ");
INSERT INTO hausa_vpl VALUES ("RM14_19","075_14_19","ROM","14","19","19","Saboda haka sai mu yi iya ƙoƙari mu aikata abin da zai kawo salama da kuma ingantawa ga juna. ");
INSERT INTO hausa_vpl VALUES ("RM14_20","075_14_20","ROM","14","20","20","Kada ku lalatar da aikin Allah saboda abinci. Dukan abinci mai tsabta ne, sai dai ba daidai ba ne mutum yă ci abin da zai sa wani yă yi tuntuɓe. ");
INSERT INTO hausa_vpl VALUES ("RM14_21","075_14_21","ROM","14","21","21","Ya fi kyau kada ka ci nama ko ka sha ruwan inabi ko kuma ka yi wani abin da zai sa ɗan’uwanka yă fāɗi. ");
INSERT INTO hausa_vpl VALUES ("RM14_22","075_14_22","ROM","14","22","22","Bari duk ra’ayin da kake da shi game da wannan sha’ani yă kasance tsakaninka da Allah. Mai albarka ne wanda zuciyarsa ba tă ba shi laifi game da abin da shi da kansa ya ɗauka cewa daidai ne ba. ");
INSERT INTO hausa_vpl VALUES ("RM14_23","075_14_23","ROM","14","23","23","Amma wanda yake da shakka yakan jawo wa kansa hukunci ne in ya ci, domin yana ci ne ba bisa ga bangaskiya ba; kuma duk abin da bai zo daga bangaskiya ba zunubi ne. ");
INSERT INTO hausa_vpl VALUES ("RM15_1","075_15_1","ROM","15","1","1","Mu da muke da ƙarfi ya kamata mu yi haƙuri da kāsawar marasa ƙarfi ba kawai mu gamshi kanmu ba. ");
INSERT INTO hausa_vpl VALUES ("RM15_2","075_15_2","ROM","15","2","2","Ya kamata kowannenmu yă faranta wa maƙwabcinsa rai don kyautata zamansa domin kuma yă gina shi. ");
INSERT INTO hausa_vpl VALUES ("RM15_3","075_15_3","ROM","15","3","3","Gama ko Kiristi ma bai gamshi kansa ba, amma kamar yadda yake a rubuce cewa, “Zage-zagen da waɗansu suka yi maka, duk sun fāɗo a kaina.” ");
INSERT INTO hausa_vpl VALUES ("RM15_4","075_15_4","ROM","15","4","4","Gama duk abin da aka rubuta a dā an rubuta ne domin yă koya mana, don ta wurin jimrewa da kuma ƙarfafawar Nassosi mu kasance da bege. ");
INSERT INTO hausa_vpl VALUES ("RM15_5","075_15_5","ROM","15","5","5","Bari Allah mai ba da haƙuri da kuma ƙarfafawa yă ba ku ruhun haɗinkai da juna yayinda kuke bin Kiristi Yesu, ");
INSERT INTO hausa_vpl VALUES ("RM15_6","075_15_6","ROM","15","6","6","don da zuciya ɗaya da kuma baki ɗaya kuke ɗaukaka Allah da kuma Uban Ubangijinmu Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("RM15_7","075_15_7","ROM","15","7","7","Ta haka sai ku karɓi juna kamar yadda Kiristi ya karɓe ku, don a yabi Allah. ");
INSERT INTO hausa_vpl VALUES ("RM15_8","075_15_8","ROM","15","8","8","Ina dai gaya muku cewa Kiristi ya zama bawan Yahudawa a madadin gaskiyar Allah, don yă tabbatar da alkawaran da aka yi wa kakannin kakanninmu ");
INSERT INTO hausa_vpl VALUES ("RM15_9","075_15_9","ROM","15","9","9","domin Al’ummai su ɗaukaka Allah saboda jinƙansa, kamar yadda yake a rubuce, “Saboda haka zan yabe ka a cikin Al’ummai; zan rera waƙoƙi ga sunanka.” ");
INSERT INTO hausa_vpl VALUES ("RM15_10","075_15_10","ROM","15","10","10","Ya kuma ce, “Ku yi farin ciki, ya Al’ummai, tare da mutanensa.” ");
INSERT INTO hausa_vpl VALUES ("RM15_11","075_15_11","ROM","15","11","11","Da kuma, “Ku yabi Ubangiji, dukanku Al’ummai, ku kuma rera masa yabo, dukanku mutanen duniya.” ");
INSERT INTO hausa_vpl VALUES ("RM15_12","075_15_12","ROM","15","12","12","Kuma Ishaya ya ce, “Tushen Yesse zai tsiro, wanda zai taso yă yi mulkin al’ummai; al’ummai za su sa bege a gare shi.” ");
INSERT INTO hausa_vpl VALUES ("RM15_13","075_15_13","ROM","15","13","13","Bari Allah na bege yă cika ku da matuƙar farin ciki da salama yayinda kuke dogara gare shi, domin ku yalwata cikin bege ta wurin ikon Ruhu Mai Tsarki. ");
INSERT INTO hausa_vpl VALUES ("RM15_14","075_15_14","ROM","15","14","14","Ni kaina na tabbata, ’yan’uwana, cewa ku kanku kuna cike da kirki, cikakku cikin sani da kuma ƙwararru don yin wa juna gargaɗi. ");
INSERT INTO hausa_vpl VALUES ("RM15_15","075_15_15","ROM","15","15","15","Na rubuta muku gabagadi a kan waɗansu batuttuwa, don in sāke tuna muku su, saboda alherin da Allah ya ba ni ");
INSERT INTO hausa_vpl VALUES ("RM15_16","075_15_16","ROM","15","16","16","in zama mai hidimar Kiristi Yesu ga Al’ummai da aikin firist na yin shelar bisharar Allah, don Al’ummai su zama hadaya mai karɓuwa ga Allah, tsattsarka ta wurin Ruhu Mai Tsarki. ");
INSERT INTO hausa_vpl VALUES ("RM15_17","075_15_17","ROM","15","17","17","Saboda haka ina taƙama cikin Kiristi Yesu a cikin hidimata ga Allah. ");
INSERT INTO hausa_vpl VALUES ("RM15_18","075_15_18","ROM","15","18","18","Ba zan yi karambani in faɗi kome ba sai dai abin da Kiristi ya aikata ta wurina a jagorantar da Al’ummai su yi biyayya ga Allah ta wurin abin da na faɗa da kuma aikata ");
INSERT INTO hausa_vpl VALUES ("RM15_19","075_15_19","ROM","15","19","19","ta wurin ikon alamu da ayyukan banmamaki, da kuma ikon Ruhun Allah. Ta haka daga Urushalima har yă zuwa kewayen Illirikum, na yi wa’azin bisharar Kiristi. ");
INSERT INTO hausa_vpl VALUES ("RM15_20","075_15_20","ROM","15","20","20","Labudda, burina shi ne in yi wa’azin bishara inda ba a san Kiristi ba, don kada yă zama ina gini ne a kan tushen da wani ya kafa. ");
INSERT INTO hausa_vpl VALUES ("RM15_21","075_15_21","ROM","15","21","21","Sai dai kamar yadda yake a rubuce, “Waɗanda ba a faɗa musu labarinsa ba za su gani, waɗanda kuma ba su ji ba za su fahimta.” ");
INSERT INTO hausa_vpl VALUES ("RM15_22","075_15_22","ROM","15","22","22","Wannan ne ya sa sau da yawa aka hana ni zuwa wurinku. ");
INSERT INTO hausa_vpl VALUES ("RM15_23","075_15_23","ROM","15","23","23","Amma yanzu da babu sauran wurin da ya rage mini in yi aiki a waɗannan yankuna, da yake kuma shekaru masu yawa ina da marmari in gan ku, ");
INSERT INTO hausa_vpl VALUES ("RM15_24","075_15_24","ROM","15","24","24","ina shirin yin haka in na tafi Sifen. Ina fata in ziyarce ku yayinda nake wucewa don ku raka ni can, bayan na ji daɗin zama tare da ku na ɗan lokaci. ");
INSERT INTO hausa_vpl VALUES ("RM15_25","075_15_25","ROM","15","25","25","Yanzu kam, ina hanyata zuwa Urushalima don in kai gudummawa ga tsarkaka a can. ");
INSERT INTO hausa_vpl VALUES ("RM15_26","075_15_26","ROM","15","26","26","Gama Makidoniya da Akayya sun ji daɗin yin gudummawa domin matalautan da suke cikin tsarkakan da suke a Urushalima. ");
INSERT INTO hausa_vpl VALUES ("RM15_27","075_15_27","ROM","15","27","27","Sun kuwa ji daɗin yin haka, gama ya zama kamar bashi ne a gare su. Da yake Al’ummai sun sami rabo cikin albarkun ruhaniyar Yahudawa, ya zama musu kamar bashi su ma su taimaki Yahudawa da albarkunsu na kayan duniya. ");
INSERT INTO hausa_vpl VALUES ("RM15_28","075_15_28","ROM","15","28","28","Saboda haka in na kammala wannan aiki na kuma tabbata cewa sun karɓi wannan amfani, zan tafi Sifen in kuma ziyarce ku a hanyata. ");
INSERT INTO hausa_vpl VALUES ("RM15_29","075_15_29","ROM","15","29","29","Na san cewa sa’ad da na zo wurinku, zan zo ne cikin yalwar albarkar Kiristi. ");
INSERT INTO hausa_vpl VALUES ("RM15_30","075_15_30","ROM","15","30","30","Ina roƙonku ’yan’uwa, saboda Ubangijinmu Yesu Kiristi da kuma saboda ƙaunar Ruhu, ku haɗa kai tare da ni cikin famata ta wurin yin addu’a ga Allah saboda ni. ");
INSERT INTO hausa_vpl VALUES ("RM15_31","075_15_31","ROM","15","31","31","Ku yi addu’a don in kuɓuta daga hannun marasa bi a Yahudiya don kuma gudummawar da nake kaiwa Urushalima ta zama abar karɓa ga tsarkaka a can, ");
INSERT INTO hausa_vpl VALUES ("RM15_32","075_15_32","ROM","15","32","32","don da yardar Allah, in iso wurinku da farin ciki in kuma wartsake tare da ku. ");
INSERT INTO hausa_vpl VALUES ("RM15_33","075_15_33","ROM","15","33","33","Allah na salama yă kasance tare da ku duka. Amin. ");
INSERT INTO hausa_vpl VALUES ("RM16_1","075_16_1","ROM","16","1","1","Ina gabatar muku da ’yar’uwarmu Fibi, baranyar ikkilisiya a Kenkireya. ");
INSERT INTO hausa_vpl VALUES ("RM16_2","075_16_2","ROM","16","2","2","Ina roƙonku ku karɓe ta a cikin Ubangiji yadda ya dace a karɓi tsarkaka a kuma ba ta kowane irin taimakon da take bukata daga wurinku, gama ta zama mai taimako ƙwarai ga mutane masu yawa, haɗe da ni ma. ");
INSERT INTO hausa_vpl VALUES ("RM16_3","075_16_3","ROM","16","3","3","Ku gai da Firiskila da Akwila, abokan aikina cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("RM16_4","075_16_4","ROM","16","4","4","Sun yi kasai da ransu saboda ni. Ba ni kaɗai nake musu godiya ba amma har ma da dukan ikkilisiyoyin Al’ummai. ");
INSERT INTO hausa_vpl VALUES ("RM16_5","075_16_5","ROM","16","5","5","Ku kuma gai da ikkilisiyar da take haɗuwa a gidansu. Ku gai da ƙaunataccen abokina Efenetus, wanda ya zama na farko a karɓar Kiristi a lardin Asiya. ");
INSERT INTO hausa_vpl VALUES ("RM16_6","075_16_6","ROM","16","6","6","Ku gai da Maryamu wadda ta yi muku aiki tuƙuru. ");
INSERT INTO hausa_vpl VALUES ("RM16_7","075_16_7","ROM","16","7","7","Ku gai da Anduronikus da Yuniyas, dangina waɗanda aka daure a kurkuku tare da ni. Su fitattu ne sosai a cikin manzanni, sun riga ni zama masu bin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("RM16_8","075_16_8","ROM","16","8","8","Ku gai da Amfiliyatus, ƙaunataccena a cikin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("RM16_9","075_16_9","ROM","16","9","9","Ku gai da Urbanus, abokin aikinmu cikin Kiristi, da kuma ƙaunataccen abokina Sitakis. ");
INSERT INTO hausa_vpl VALUES ("RM16_10","075_16_10","ROM","16","10","10","Ku gai da Afelles wanda amincinsa cikin Kiristi tabbatacce ne. Ku gai da iyalin gidan Aristobulus. ");
INSERT INTO hausa_vpl VALUES ("RM16_11","075_16_11","ROM","16","11","11","Ku gai da ɗan’uwana, Hirodiyon. Ku gai da iyalin gidan Narkissus da suke cikin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("RM16_12","075_16_12","ROM","16","12","12","Ku gai da Tiryifena da Tiryifosa, matan nan da suke aiki tuƙuru cikin Ubangiji. Ku gai da ƙaunatacciyata Fersis, wata matan da ta yi aiki tuƙuru cikin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("RM16_13","075_16_13","ROM","16","13","13","Ku gai da Rufus zaɓaɓɓe cikin Ubangiji, da kuma mahaifiyarsa, wadda ta zama kamar mahaifiya a gare ni. ");
INSERT INTO hausa_vpl VALUES ("RM16_14","075_16_14","ROM","16","14","14","Ku gai da Asinkiritus, Filegon, Hermes, Faturobas, Hermas da kuma ’yan’uwan da suke tare da su. ");
INSERT INTO hausa_vpl VALUES ("RM16_15","075_16_15","ROM","16","15","15","Ku gai da Filologus, Yuliya, Nereyus da ’yar’uwarsa, da kuma Olimfas da dukan tsarkakan da suke tare da su. ");
INSERT INTO hausa_vpl VALUES ("RM16_16","075_16_16","ROM","16","16","16","Ku gaggai da juna da sumba mai tsarki. Dukan ikkilisiyoyin Kiristi suna gaishe ku. ");
INSERT INTO hausa_vpl VALUES ("RM16_17","075_16_17","ROM","16","17","17","Ina roƙonku, ’yan’uwa, ku yi hankali fa da masu raba tsakani, saɓanin koyarwar da kuka koya, suna sa tuntuɓe. Ku yi nesa da su. ");
INSERT INTO hausa_vpl VALUES ("RM16_18","075_16_18","ROM","16","18","18","Gama irin waɗannan mutane ba sa bautar Ubangijinmu Kiristi, sai dai cikinsu. Ta wurin yaudara da kuma daɗin baki, suna ruɗin marasa wayo. ");
INSERT INTO hausa_vpl VALUES ("RM16_19","075_16_19","ROM","16","19","19","Kowa ya riga ya ji game da biyayyarku, don haka ina cike da farin ciki game da ku; amma ina so ku zama masu hikima game da abin da yake nagari, ku kuma zama marasa laifi ga abin da yake mugu. ");
INSERT INTO hausa_vpl VALUES ("RM16_20","075_16_20","ROM","16","20","20","Allah na salama zai tattake Shaiɗan ba da daɗewa ba yă kuma sa shi a ƙarƙashin sawunku. Alherin Ubangijinmu Yesu kuma yă kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("RM16_21","075_16_21","ROM","16","21","21","Timoti, abokin aikina, yana gai da ku, haka ma Lusiyus, Yason, da Sosifater, dangina. ");
INSERT INTO hausa_vpl VALUES ("RM16_22","075_16_22","ROM","16","22","22","Ni, Tertiyus, wanda ya rubuta wannan wasiƙa, ina gai da ku cikin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("RM16_23","075_16_23","ROM","16","23","23","Gayus, mai masauƙina, mai kuma saukar da dukan ’yan Ikkilisiya, yana gaishe ku. Erastus, mai bi da ayyukan jama’ar gari, da kuma ɗan’uwanmu Kwartus, suna gaishe ku. ");
INSERT INTO hausa_vpl VALUES ("RM16_25","075_16_25","ROM","16","25","25","Ɗaukaka ta tabbata ga mai ikon ƙarfafa ku bisa ga bisharata, bisa ga wa’azin Yesu Kiristi, wadda ta gare ta ne aka bayyana asirin nan da yake ɓoye tun fil azal, ");
INSERT INTO hausa_vpl VALUES ("RM16_26","075_16_26","ROM","16","26","26","amma yanzu kuwa aka bayyana, aka kuma sanar ta wurin rubuce-rubucen annabawa bisa ga umarnin Allah madawwami, domin dukan al’ummai su gaskata su kuma yi masa biyayya ");
INSERT INTO hausa_vpl VALUES ("RM16_27","075_16_27","ROM","16","27","27","ɗaukaka ta tabbata har abada ga Allah, wanda shi ne kaɗai mai hikima ta wurin Yesu Kiristi! Amin.");
INSERT INTO hausa_vpl VALUES ("C11_1","076_1_1","1CO","1","1","1","Bulus, wanda aka kira domin yă zama manzon Kiristi Yesu, bisa ga nufin Allah, da kuma ɗan’uwanmu Sostenes, ");
INSERT INTO hausa_vpl VALUES ("C11_2","076_1_2","1CO","1","2","2","Zuwa ga ikkilisiyar Allah da take a Korint, da waɗanda aka tsarkake cikin Kiristi Yesu, aka kuma kira domin su zama masu tsarki, tare da dukan waɗanda suke ko’ina da suke kiran sunan Ubangijinmu Yesu Kiristi, Ubangijinsu da kuma namu. ");
INSERT INTO hausa_vpl VALUES ("C11_3","076_1_3","1CO","1","3","3","Alheri da salama daga Allah Ubanmu, da Ubangiji Yesu Kiristi, su kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("C11_4","076_1_4","1CO","1","4","4","Ina gode wa Allah kullum dominku, saboda alherinsa da aka ba ku a cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("C11_5","076_1_5","1CO","1","5","5","Gama a cikinsa kuka sami wadata ta kowace hanya, a cikin dukan maganarku, da kuma cikin dukan saninku ");
INSERT INTO hausa_vpl VALUES ("C11_6","076_1_6","1CO","1","6","6","gama shaidarmu game da Kiristi ta tabbata a cikinku. ");
INSERT INTO hausa_vpl VALUES ("C11_7","076_1_7","1CO","1","7","7","Saboda haka, ba ku rasa kowace baiwa ta ruhaniya ba, yayinda kuke jira da marmari, saboda bayyanuwar Ubangijinmu Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("C11_8","076_1_8","1CO","1","8","8","Zai ƙarfafa ku har zuwa ƙarshe, domin ku zama marasa aibi a ranar Ubangijinmu Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("C11_9","076_1_9","1CO","1","9","9","Allah, wanda ya kira ku zuwa ga zumunci tare da Ɗansa Yesu Kiristi Ubangijinmu, shi mai aminci ne. ");
INSERT INTO hausa_vpl VALUES ("C11_10","076_1_10","1CO","1","10","10","Ina roƙonku ’yan’uwa, a cikin sunan Ubangijinmu Yesu Kiristi, dukanku ku yarda da juna, domin kada a sami tsattsaguwa a cikinku, domin kuma ku zama ɗaya, cikakku a cikin halinku da tunaninku. ");
INSERT INTO hausa_vpl VALUES ("C11_11","076_1_11","1CO","1","11","11","’Yan’uwana, waɗansu daga iyalin gidan Kulos sun gaya mini cewa, akwai faɗa a cikinku. ");
INSERT INTO hausa_vpl VALUES ("C11_12","076_1_12","1CO","1","12","12","Abin da nake nufi shi ne, ɗaya daga cikinku na cewa, “Ni ina bin Bulus,” wani na cewa, “Ni ina bin Afollos,” wani kuma, “Ni ina bin Kefas,” har wa yau wani kuma, “Ni ina bin Kiristi.” ");
INSERT INTO hausa_vpl VALUES ("C11_13","076_1_13","1CO","1","13","13","Kiristi a rabe ne? Bulus ne aka gicciye dominku? An yi muku baftisma a cikin sunan Bulus ne? ");
INSERT INTO hausa_vpl VALUES ("C11_14","076_1_14","1CO","1","14","14","Ina godiya domin ban yi wa wani baftisma a cikinku ba, sai dai Kirisbus da Gayus kaɗai. ");
INSERT INTO hausa_vpl VALUES ("C11_15","076_1_15","1CO","1","15","15","Don haka, ba wanda na iya cewa an yi muku baftisma a cikin sunana. ");
INSERT INTO hausa_vpl VALUES ("C11_16","076_1_16","1CO","1","16","16","(I, na kuma yi wa iyalin gidan Istifanas baftisma, ban da wannan, ban tuna da wani da na yi masa baftisma ba.) ");
INSERT INTO hausa_vpl VALUES ("C11_17","076_1_17","1CO","1","17","17","Gama Kiristi bai aike ni yin baftisma ba, sai dai wa’azin bishara ba da kalmomin hikimar mutum ba, domin kada gicciyen Kiristi ya rasa ikonsa. ");
INSERT INTO hausa_vpl VALUES ("C11_18","076_1_18","1CO","1","18","18","Gama saƙon gicciye wauta ne ga waɗanda suke hallaka, amma a gare mu, mu da ake ceto, ikon Allah ne. ");
INSERT INTO hausa_vpl VALUES ("C11_19","076_1_19","1CO","1","19","19","Gama a rubuce yake cewa, “Zan rushe hikimar mai hikima, basirar mai azanci kuma zan rikita shi.” ");
INSERT INTO hausa_vpl VALUES ("C11_20","076_1_20","1CO","1","20","20","Ina mai hikima? Ina mai zurfin bincike? Ina masana na wannan zamani? Ashe, Allah bai wofinta hikimar duniya ba? ");
INSERT INTO hausa_vpl VALUES ("C11_21","076_1_21","1CO","1","21","21","Gama tun da a cikin hikimar Allah, duniya a cikin hikimarta ba tă san shi ba, Allah ya ji daɗin ceton waɗanda suka ba da gaskiya ta wurin wautar wa’azin bishara. ");
INSERT INTO hausa_vpl VALUES ("C11_22","076_1_22","1CO","1","22","22","Yahudawa suna so su ga alama, Hellenawa kuma suna neman hikima, ");
INSERT INTO hausa_vpl VALUES ("C11_23","076_1_23","1CO","1","23","23","amma mu, muna wa’azin Kiristi wanda aka gicciye ne, wanda ya zama dutsen tuntuɓe ga Yahudawa, wauta kuma ga Al’ummai, ");
INSERT INTO hausa_vpl VALUES ("C11_24","076_1_24","1CO","1","24","24","amma ga su waɗanda Allah ya kira, Yahudawa da Hellenawa, Kiristi ikon Allah ne, da kuma hikimar Allah. ");
INSERT INTO hausa_vpl VALUES ("C11_25","076_1_25","1CO","1","25","25","Gama wautar Allah ta fi hikimar mutum, kuma rashin ƙarfin Allah ya fi ƙarfin mutum. ");
INSERT INTO hausa_vpl VALUES ("C11_26","076_1_26","1CO","1","26","26","’Yan’uwa, ku tuna yadda kuke sa’ad da aka kira ku. Babu masu hikima da yawa a cikinku, bisa ga ganin mutum; babu masu iko da yawa, babu masu martaba da yawa bisa ga haihuwa. ");
INSERT INTO hausa_vpl VALUES ("C11_27","076_1_27","1CO","1","27","27","Amma Allah ya zaɓi abubuwa masu wautata duniya, don yă kunyata masu hikima. Allah ya zaɓi abubuwa marasa ƙarfi na duniya, domin ya ba wa masu ƙarfi kunya. ");
INSERT INTO hausa_vpl VALUES ("C11_28","076_1_28","1CO","1","28","28","Ya zaɓi abubuwa marasa martaba na wannan duniya da kuma abubuwan da aka rena da abubuwan da ba a ɗauka a bakin kome ba, domin a wofinta abubuwan da ake ganinsu da daraja, ");
INSERT INTO hausa_vpl VALUES ("C11_29","076_1_29","1CO","1","29","29","domin kada wani ya yi taƙama a gabansa. ");
INSERT INTO hausa_vpl VALUES ("C11_30","076_1_30","1CO","1","30","30","Saboda Allah ne kuke cikin Kiristi Yesu, shi wanda ya zama hikima a gare mu daga Allah. Kiristi shi ne adalcinmu, da tsarkinmu, da kuma fansarmu. ");
INSERT INTO hausa_vpl VALUES ("C11_31","076_1_31","1CO","1","31","31","Saboda haka, kamar yadda yake a rubuce cewa, “Duk wanda yake taƙama, ya yi taƙama a cikin Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("C12_1","076_2_1","1CO","2","1","1","Da na zo wurinku ’yan’uwa, ban zo da iya magana ko wani mafificin hikima yayinda na yi muku shelar shaida game da Allah ba. ");
INSERT INTO hausa_vpl VALUES ("C12_2","076_2_2","1CO","2","2","2","Don na ƙudura a raina sa’ad da nake tare da ku cewa ba zan mai da hankali ga kome ba sai dai Yesu Kiristi wanda aka gicciye. ");
INSERT INTO hausa_vpl VALUES ("C12_3","076_2_3","1CO","2","3","3","Na zo wurinku cikin rashin ƙarfi da tsoro, da rawan jiki ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("C12_4","076_2_4","1CO","2","4","4","Saƙona da wa’azina ba su zo cikin hikima da kalmomin lallashi ba, sai dai da nuna ikon Ruhu, ");
INSERT INTO hausa_vpl VALUES ("C12_5","076_2_5","1CO","2","5","5","domin kada bangaskiyarku ta dogara a kan hikimar mutane, sai dai a kan ikon Allah. ");
INSERT INTO hausa_vpl VALUES ("C12_6","076_2_6","1CO","2","6","6","Duk da haka, muna sanar da saƙon hikima cikin waɗanda suka balaga, amma ba hikima irin ta wannan zamani ba ne, ko kuwa irin ta masu mulkin zamanin nan, waɗanda za su shuɗe ba. ");
INSERT INTO hausa_vpl VALUES ("C12_7","076_2_7","1CO","2","7","7","A’a, muna magana ne a kan asirin hikimar Allah, hikimar da tun dā, take a ɓoye, wadda Allah ya ƙaddara domin ɗaukakarmu, tun kafin farkon zamanai. ");
INSERT INTO hausa_vpl VALUES ("C12_8","076_2_8","1CO","2","8","8","Ba ko ɗaya daga cikin masu mulkin wannan zamani da ya fahimce ta, gama da a ce sun fahimce ta, da ba su gicciye Ubangiji mai ɗaukaka ba. ");
INSERT INTO hausa_vpl VALUES ("C12_9","076_2_9","1CO","2","9","9","Duk da haka, kamar yadda yake a rubuce cewa, “Ba idon da ya taɓa gani, ba kunnen da ya taɓa ji, ba kuma zuciyar da ta taɓa tunanin abin da Allah ya shirya wa masu ƙaunarsa.” ");
INSERT INTO hausa_vpl VALUES ("C12_10","076_2_10","1CO","2","10","10","Amma Allah ya bayyana mana shi ta wurin Ruhunsa. Ruhu yana bincika dukan abubuwa, har ma da abubuwa masu zurfi na Allah. ");
INSERT INTO hausa_vpl VALUES ("C12_11","076_2_11","1CO","2","11","11","Wane ne a cikin mutane ya san tunanin mutum, in ba ruhun mutumin da yake cikinsa ba? Haka kuma ba wanda ya san tunanin Allah, sai dai Ruhun Allah. ");
INSERT INTO hausa_vpl VALUES ("C12_12","076_2_12","1CO","2","12","12","Ba mu karɓi ruhun duniya ba, sai dai Ruhun da yake daga Allah, domin mu fahimci abin da Allah ya ba mu hannu sake. ");
INSERT INTO hausa_vpl VALUES ("C12_13","076_2_13","1CO","2","13","13","Wannan shi ne abin da muke sanarwa, ba da kalmomin da muka koya ta wurin hikimar mutum ba, amma da kalmomin da Ruhu yake koyarwa, muna faɗin gaskiya ta ruhaniya da kalmomin ruhaniya. ");
INSERT INTO hausa_vpl VALUES ("C12_14","076_2_14","1CO","2","14","14","Mutumin da ba shi da Ruhu, ba ya yarda da abubuwan da suka fita daga Ruhun Allah, domin wauta ce a gare shi. Ba kuwa zai fahimce su ba, domin ta Ruhu ne ake fahimtarsu. ");
INSERT INTO hausa_vpl VALUES ("C12_15","076_2_15","1CO","2","15","15","Mutumin ruhaniya yakan gwada dukan abubuwa, amma shi kansa ba ya ƙarƙashin shari’ar mutum. ");
INSERT INTO hausa_vpl VALUES ("C12_16","076_2_16","1CO","2","16","16","“Wa ya taɓa sanin hankalin Ubangiji, har da zai koya masa?” Amma muna da tunani iri na Kiristi ne. ");
INSERT INTO hausa_vpl VALUES ("C13_1","076_3_1","1CO","3","1","1","’Yan’uwa, ban iya yi muku magana kamar masu ruhaniya ba, sai dai kamar masu halin mutuntaka, jarirai cikin bin Kiristi kawai. ");
INSERT INTO hausa_vpl VALUES ("C13_2","076_3_2","1CO","3","2","2","Na ba ku madara ba abinci mai tauri ba, domin ba ku balaga ba a lokacin. Kai, har yanzu ma, ba ku balaga ba. ");
INSERT INTO hausa_vpl VALUES ("C13_3","076_3_3","1CO","3","3","3","Har yanzu kuna rayuwa bisa ga halin mutuntaka. Da yake akwai kishi da faɗace-faɗace a cikinku, ba rayuwa irin ta halin mutuntaka ke nan kuke yi ba? Kuma ba rayuwa irin ta mutane ce kawai kuke yi ba? ");
INSERT INTO hausa_vpl VALUES ("C13_4","076_3_4","1CO","3","4","4","Gama sa’ad da wani ya ce, “Ni na Bulus ne,” wani kuma ya ce, “Ni na Afollos ne,” ba rayuwa irin ta mutane ke nan kuke yi ba? ");
INSERT INTO hausa_vpl VALUES ("C13_5","076_3_5","1CO","3","5","5","Shin, wane ne Afollos? Wane ne kuma Bulus? Ai, bayi ne kawai waɗanda ta wurinsu kuka gaskata, kamar yadda Ubangiji ya ba kowannensu aikinsa. ");
INSERT INTO hausa_vpl VALUES ("C13_6","076_3_6","1CO","3","6","6","Ni na shuka iri, Afollos kuma ya yi banruwa, amma Allah ne ya sa irin ya yi girma. ");
INSERT INTO hausa_vpl VALUES ("C13_7","076_3_7","1CO","3","7","7","Don haka, da wanda ya yi shuki, da wanda ya yi banruwa, ba a bakin kome suke ba, sai dai Allah kaɗai, mai sa abubuwa su yi girma. ");
INSERT INTO hausa_vpl VALUES ("C13_8","076_3_8","1CO","3","8","8","Mutumin da ya yi shuki, da mutumin da ya yi banruwa nufinsu ɗaya ne, kuma kowannensu zai sami lada gwargwadon aikinsa. ");
INSERT INTO hausa_vpl VALUES ("C13_9","076_3_9","1CO","3","9","9","Gama mu abokan aiki ne na Allah; ku kuwa gonar ce ta Allah, ginin Allah kuma. ");
INSERT INTO hausa_vpl VALUES ("C13_10","076_3_10","1CO","3","10","10","Ta wurin alherin da Allah ya ba ni, na kafa tushen gini kamar ƙwararren magini, wani kuma dabam yana gini a kai. Amma kowa yă lura da yadda yake gini. ");
INSERT INTO hausa_vpl VALUES ("C13_11","076_3_11","1CO","3","11","11","Gama babu wanda zai iya kafa wani tushen gini dabam da wanda aka riga aka kafa, wanda yake Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("C13_12","076_3_12","1CO","3","12","12","In wani ya yi gini a kan tushen ginin nan da zinariya, azurfa, duwatsu masu daraja, itace, ciyawa ko kara, ");
INSERT INTO hausa_vpl VALUES ("C13_13","076_3_13","1CO","3","13","13","aikin zai bayyana kansa, domin za a nuna shi a sarari a Ranar. Wuta ce za tă bayyana aikin, wutar kuwa za tă gwada ingancin aikin kowa. ");
INSERT INTO hausa_vpl VALUES ("C13_14","076_3_14","1CO","3","14","14","In abin da kowane mutum ya gina ya tsaya, zai sami lada. ");
INSERT INTO hausa_vpl VALUES ("C13_15","076_3_15","1CO","3","15","15","In ya ƙone, zai yi hasara, amma zai sami ceto, sai dai kamar wanda ya bi ta tsakiyar wuta ne. ");
INSERT INTO hausa_vpl VALUES ("C13_16","076_3_16","1CO","3","16","16","Ashe, ba ku sani ba cewa ku kanku haikalin Allah ne, Ruhun Allah kuma yana zaune a cikinku? ");
INSERT INTO hausa_vpl VALUES ("C13_17","076_3_17","1CO","3","17","17","Duk wanda ya ɓata haikalin Allah, Allah zai ɓata shi, don haikalin Allah mai tsarki ne, ku ne kuwa haikalin nan. ");
INSERT INTO hausa_vpl VALUES ("C13_18","076_3_18","1CO","3","18","18","Kada ku ruɗi kanku. In waninku yana tsammani cewa yana da hikima, yadda duniya ta ɗauki hikima, to, sai ya mai da kansa “wawa” don yă zama mai hikima. ");
INSERT INTO hausa_vpl VALUES ("C13_19","076_3_19","1CO","3","19","19","Gama hikimar duniyan nan, wauta ce a gaban Allah, kamar yadda yake a rubuce cewa, “Yakan kama masu hikima a cikin makircinsu”; ");
INSERT INTO hausa_vpl VALUES ("C13_20","076_3_20","1CO","3","20","20","kuma a rubuce yake cewa, “Ubangiji ya san dukan tunanin masu hikima banza ne.” ");
INSERT INTO hausa_vpl VALUES ("C13_21","076_3_21","1CO","3","21","21","Saboda haka, kada wani yă yi taƙama da mutum! Gama kome naku ne, ");
INSERT INTO hausa_vpl VALUES ("C13_22","076_3_22","1CO","3","22","22","ko Bulus ko Afollos ko Kefas ko duniya ko rai ko mutuwa ko abubuwa na yanzu ko na nan gaba, ai, duka naku ne, ");
INSERT INTO hausa_vpl VALUES ("C13_23","076_3_23","1CO","3","23","23","ku kuwa na Kiristi ne, Kiristi kuma na Allah ne. ");
INSERT INTO hausa_vpl VALUES ("C14_1","076_4_1","1CO","4","1","1","Saboda haka, ya kamata mutane su ɗauke mu a matsayin bayin Kiristi, da kuma a matsayin waɗanda aka ba su amanar asirin abubuwan Allah. ");
INSERT INTO hausa_vpl VALUES ("C14_2","076_4_2","1CO","4","2","2","Yanzu fa, ana bukatar waɗanda aka ba su riƙon amana, dole su zama masu aminci. ");
INSERT INTO hausa_vpl VALUES ("C14_3","076_4_3","1CO","4","3","3","Ƙaramin abu ne a gare ni a ce ku ne za ku gwada ni, ko kuwa a gwada ni a wata kotun mutane, ai, ko ni kaina ba na yanka wa kaina hukunci. ");
INSERT INTO hausa_vpl VALUES ("C14_4","076_4_4","1CO","4","4","4","Lamirina bai ba ni laifi ba, sai dai wannan bai mai da ni marar laifi ba. Ubangiji ne mai hukunta ni. ");
INSERT INTO hausa_vpl VALUES ("C14_5","076_4_5","1CO","4","5","5","Saboda haka, kada ku shari’anta kome tun lokaci bai yi ba. Ku jira sai Ubangiji ya zo. Zai bayyana abin da yake a ɓoye a cikin duhu a sarari, zai kuma tone nufin zukatan mutane. A lokacin ne fa kowa zai karɓi yabo daga wurin Allah daidai gwargwado. ");
INSERT INTO hausa_vpl VALUES ("C14_6","076_4_6","1CO","4","6","6","To, fa ’yan’uwa, ga zancen waɗannan abubuwa, na misalta su ne ga kaina, da kuma Afollos saboda ku, don ku yi koyi da mu a kan abin da ake nufi da cewa, “Kada ku zarce abin da yake a rubuce.” Ta haka, ba za ku yi taƙama da wani mutum fiye da wani ba. ");
INSERT INTO hausa_vpl VALUES ("C14_7","076_4_7","1CO","4","7","7","Wa ya ce ka fi sauran mutane? Me kuma kake da shi, wanda ba karɓa ka yi ba? In kuma karɓa ka yi, me ya sa kake taƙama kamar ba karɓa ba ne ka yi? ");
INSERT INTO hausa_vpl VALUES ("C14_8","076_4_8","1CO","4","8","8","Kun riga kun sami duk abin da kuke nema! Kun riga kun yi arziki! Kun zama sarakuna, kun kuma zama haka ɗin ba tare da mu ba! Da a ce kun riga kun zama sarakuna mana da sai mu zama sarakuna tare da ku! ");
INSERT INTO hausa_vpl VALUES ("C14_9","076_4_9","1CO","4","9","9","Gama a ganina fa, Allah ya baje mu manzanni a ƙarshen jerin gwanon, a matsayin mutanen da aka hukunta ga mutuwa a filin wasanni. Mun zama abin kallo ga dukan duniya, ga mala’iku da kuma mutane. ");
INSERT INTO hausa_vpl VALUES ("C14_10","076_4_10","1CO","4","10","10","Mun zama masu wauta saboda Kiristi, ku kuwa kuna da hikima sosai a cikin Kiristi! Ba mu da ƙarfi, amma ku kuna da ƙarfi! Ana girmama ku, mu kuwa ana ƙasƙantar da mu! ");
INSERT INTO hausa_vpl VALUES ("C14_11","076_4_11","1CO","4","11","11","Har yă zuwa wannan sa’a, yunwa da ƙishirwa muke ciki, muna sanye da tsummoki, ana wulaƙanta mu, ba mu kuma da gida. ");
INSERT INTO hausa_vpl VALUES ("C14_12","076_4_12","1CO","4","12","12","Muna aiki da gaske da hannuwanmu. In aka la’anta mu, mukan sa albarka. In aka tsananta mana, mukan jimre; ");
INSERT INTO hausa_vpl VALUES ("C14_13","076_4_13","1CO","4","13","13","in aka ɓata mana suna, mukan mayar da alheri. Har yă zuwa wannan lokaci, mu ne kamar jujin duniya, abin ƙyamar kowa. ");
INSERT INTO hausa_vpl VALUES ("C14_14","076_4_14","1CO","4","14","14","Ba don in kunyata ku ba ne na rubuta wannan, sai dai don in gargaɗe ku a kan cewa ku ’ya’yana ne, ƙaunatattu. ");
INSERT INTO hausa_vpl VALUES ("C14_15","076_4_15","1CO","4","15","15","Ko da kuna da iyayen riƙo dubu goma cikin Kiristi, ba ku da ubanni da yawa, gama a cikin Kiristi Yesu, na zama mahaifi a gare ku, ta wurin bishara. ");
INSERT INTO hausa_vpl VALUES ("C14_16","076_4_16","1CO","4","16","16","Saboda haka, ina roƙonku ku yi koyi da ni. ");
INSERT INTO hausa_vpl VALUES ("C14_17","076_4_17","1CO","4","17","17","Saboda wannan dalili ina aika muku Timoti, ɗana, wanda nake ƙauna, mai aminci kuma a cikin Ubangiji. Zai tunashe ku game da yadda za ku bi Kiristi Yesu da kuma yadda ya yi daidai da yadda nake koyarwa a ko’ina, a kowace ikkilisiya. ");
INSERT INTO hausa_vpl VALUES ("C14_18","076_4_18","1CO","4","18","18","Waɗansunku suna tsammani ba zan zo wurinku ba har suna ɗagankai. ");
INSERT INTO hausa_vpl VALUES ("C14_19","076_4_19","1CO","4","19","19","Amma in Ubangiji ya yarda zan zo wurinku ba da daɗewa ba. Sa’an nan zan bincike ko masu wannan yawan ɗagan kan nan suna da wani iko. ");
INSERT INTO hausa_vpl VALUES ("C14_20","076_4_20","1CO","4","20","20","Gama mulkin Allah ba cika baki ba ne, sai dai ga iko. ");
INSERT INTO hausa_vpl VALUES ("C14_21","076_4_21","1CO","4","21","21","Wanne kuka fi so in na zo? Kuna so in tsananta muku ko in zama mai hankali da kuma sauƙinkai? ");
INSERT INTO hausa_vpl VALUES ("C15_1","076_5_1","1CO","5","1","1","Ana ba da labari cewa ana lalata a cikinku, irin da ba a ma samu a cikin masu bautar gumaka. Har mutum yana kwana da matar mahaifinsa. ");
INSERT INTO hausa_vpl VALUES ("C15_2","076_5_2","1CO","5","2","2","Har ya zama muku abin taƙama! Ashe, bai kamata ku cika da baƙin ciki ku kuma daina zumunci da mutumin da yake aikata wannan ba? ");
INSERT INTO hausa_vpl VALUES ("C15_3","076_5_3","1CO","5","3","3","Ko da yake ba na nan tare da ku cikin jiki, ina tare da ku a cikin ruhu. Na riga na yanke wa wanda ya aikata wannan hukunci, kamar dai ina tare da ku. ");
INSERT INTO hausa_vpl VALUES ("C15_4","076_5_4","1CO","5","4","4","Saboda haka sa’ad da kun taru ikon Ubangijinmu Yesu kuma yana nan, ni ma ina tare da ku. ");
INSERT INTO hausa_vpl VALUES ("C15_5","076_5_5","1CO","5","5","5","Ku miƙa irin wannan mutum ga Shaiɗan, don a hallaka halin nan na mutuntaka, ruhunsa kuma yă sami ceto a ranar da Ubangiji zai dawo. ");
INSERT INTO hausa_vpl VALUES ("C15_6","076_5_6","1CO","5","6","6","Ku daina taƙama. Ba ku san cewa ɗan ƙanƙanin yisti ne yakan sa dukan curin burodi yă kumbura ba? ");
INSERT INTO hausa_vpl VALUES ("C15_7","076_5_7","1CO","5","7","7","Ku kawar da tsohon yisti don ku zama kamar sabon curi da aka yi babu yisti yadda dai kuke. Gama an miƙa Kiristi Ɗan Ragon Bikin Ƙetarewarmu. ");
INSERT INTO hausa_vpl VALUES ("C15_8","076_5_8","1CO","5","8","8","Saboda haka, sai mu kiyaye Bikin ba da burodi mai tsohon yisti ba, ba kuma da yisti na ƙeta da mugunta ba, sai dai da burodi marar yisti na sahihanci da na gaskiya. ");
INSERT INTO hausa_vpl VALUES ("C15_9","076_5_9","1CO","5","9","9","Na rubuta muku cikin wasiƙata, kada ku yi haɗa kai da masu aikin lalata. ");
INSERT INTO hausa_vpl VALUES ("C15_10","076_5_10","1CO","5","10","10","Ko kusa, ba na nufin fasikai marasa bi, ko makwaɗaita da mazambata, ko matsafa, don in haka ne, sai yă zama dole ku fita daga duniya. ");
INSERT INTO hausa_vpl VALUES ("C15_11","076_5_11","1CO","5","11","11","Yanzu dai ina rubuta muku cewa kada ku haɗa kai da duk mai kiran kansa ɗan’uwa, amma yana fasikanci, ko kwaɗayi, ko bautar gumaka, ko ɓata suna, ko mashayi, ko mazambaci. Kada ku ko ci abinci da irin wannan mutum. ");
INSERT INTO hausa_vpl VALUES ("C15_12","076_5_12","1CO","5","12","12","Me zai kai yin hukunci ga waɗanda ba ’yan ikkilisiya ba. Ai, waɗanda suke ’yan ikkilisiya ne za ku hukunta. ");
INSERT INTO hausa_vpl VALUES ("C15_13","076_5_13","1CO","5","13","13","Allah zai hukunta waɗanda ba namu ba. “Ku yi waje da irin mugun mutumin nan daga cikinku.” ");
INSERT INTO hausa_vpl VALUES ("C16_1","076_6_1","1CO","6","1","1","In wani a cikinku yana da damuwa da wani, don me zai kai ƙara a gaban marasa bi, maimakon yă kai ƙara a gaban tsarkaka? ");
INSERT INTO hausa_vpl VALUES ("C16_2","076_6_2","1CO","6","2","2","Ba ku san cewa tsarkaka ne za su yi wa duniya shari’a ba? In kuwa za ku yi wa duniya shari’a, ai, kun isa ku yi shari’a a kan ƙananan damuwoyi ke nan. ");
INSERT INTO hausa_vpl VALUES ("C16_3","076_6_3","1CO","6","3","3","Ba ku san cewa za mu yi wa mala’iku shari’a ba? Balle al’amuran da suka shafi duniyan nan! ");
INSERT INTO hausa_vpl VALUES ("C16_4","076_6_4","1CO","6","4","4","Saboda haka, in kuna da damuwa game da irin waɗannan al’amura, sai ku naɗa alƙalai ko cikin waɗanda ba kome ba ne a ikkilisiya! ");
INSERT INTO hausa_vpl VALUES ("C16_5","076_6_5","1CO","6","5","5","Na faɗi haka ne don ku ji kunya. Ashe, ba za a iya samun wani a cikinku mai hikima wanda zai iya sasanta tsakanin masu bi ba? ");
INSERT INTO hausa_vpl VALUES ("C16_6","076_6_6","1CO","6","6","6","Me zai sa ɗan’uwa yă kai ƙarar ɗan’uwa, a gaban marasa bi? ");
INSERT INTO hausa_vpl VALUES ("C16_7","076_6_7","1CO","6","7","7","Ƙarar junanku ma da kuke yi, ai, kāsawa ce a gare ku. Ba gara ku haƙura a cuce ku ba? Ku kuma haƙura ko an zambace ku? ");
INSERT INTO hausa_vpl VALUES ("C16_8","076_6_8","1CO","6","8","8","Amma ga shi ku da kanku kuna cuta, kuna kuma zamba, har ma ga ’yan’uwanku ne kuke yi wannan. ");
INSERT INTO hausa_vpl VALUES ("C16_9","076_6_9","1CO","6","9","9","Ba ku sani ba cewa mugaye ba za su gāji mulkin Allah ba? Kada fa a ruɗe ku. Ba masu fasikanci ko masu bautar gumaka ko masu zina ko karuwan maza, ko ’yan daudu, ");
INSERT INTO hausa_vpl VALUES ("C16_10","076_6_10","1CO","6","10","10","ko ɓarayi ko masu kwaɗayi ko mashaya ko masu ɓata suna ko masu zamba da za su gāji mulkin Allah. ");
INSERT INTO hausa_vpl VALUES ("C16_11","076_6_11","1CO","6","11","11","Haka waɗansu a cikinku ma suke a dā. Amma an wanke ku, an tsarkake ku, aka kuma sa kuka zama marasa laifi cikin sunan Ubangijinmu Yesu Kiristi da kuma ta wurin Ruhun Allahnmu. ");
INSERT INTO hausa_vpl VALUES ("C16_12","076_6_12","1CO","6","12","12","“Ina da dama in yi kome,” sai dai ba kome ba ne yake da amfani. “Ina da dama in yi kome” sai dai ba abin da zai mallake ni. ");
INSERT INTO hausa_vpl VALUES ("C16_13","076_6_13","1CO","6","13","13","“An yi abinci domin ciki ne, ciki kuma domin abinci.” Amma Allah zai hallaka su duka. Ba a yi jiki saboda fasikanci ba, sai dai domin Ubangiji, Ubangiji kuma domin jiki. ");
INSERT INTO hausa_vpl VALUES ("C16_14","076_6_14","1CO","6","14","14","Ta wurin ikonsa, Allah ya tashe Ubangiji daga matattu, haka zai tashe mu mu ma. ");
INSERT INTO hausa_vpl VALUES ("C16_15","076_6_15","1CO","6","15","15","Ba ku sani ba cewa jikunanku gaɓoɓin Kiristi ne kansa? Zai kyautu in ɗauki gaɓoɓin Kiristi in haɗa da jikin karuwa? Sam! ");
INSERT INTO hausa_vpl VALUES ("C16_16","076_6_16","1CO","6","16","16","Ba ku san cewa shi wanda ya haɗa jikinsa da karuwa sun zama ɗaya a cikin jiki ke nan ba? Gama an ce, “Biyun za su zama jiki ɗaya.” ");
INSERT INTO hausa_vpl VALUES ("C16_17","076_6_17","1CO","6","17","17","Wanda kuwa ya haɗa jikinsa da Ubangiji ya zama ɗaya da shi ke nan a ruhu. ");
INSERT INTO hausa_vpl VALUES ("C16_18","076_6_18","1CO","6","18","18","Ku guji fasikanci. Duk sauran zunubai da mutum yakan aikata suna waje da jikinsa, amma mai yin fasikanci, yana ɗaukar alhalin jikinsa ne. ");
INSERT INTO hausa_vpl VALUES ("C16_19","076_6_19","1CO","6","19","19","Ba ku san cewa jikin nan naku haikalin Ruhu Mai Tsarki ba ne wanda yake cikinku yake kuma daga Allah? Ku ba na kanku ba ne; ");
INSERT INTO hausa_vpl VALUES ("C16_20","076_6_20","1CO","6","20","20","saye ku fa aka yi da tsada, saboda haka, sai ku girmama Allah da jikinku. ");
INSERT INTO hausa_vpl VALUES ("C17_1","076_7_1","1CO","7","1","1","To, game da zancen da kuka rubuto. Yana da kyau mutum yă zauna ba aure. ");
INSERT INTO hausa_vpl VALUES ("C17_2","076_7_2","1CO","7","2","2","Amma da yake fasikanci ya yi yawa, ya kamata kowane mutum yă kasance da matarsa, kowace mace kuma da mijinta. ");
INSERT INTO hausa_vpl VALUES ("C17_3","076_7_3","1CO","7","3","3","Ya kamata miji yă cika hakkinsa na aure ga matarsa. Haka kuma matar ta yi ga mijinta. ");
INSERT INTO hausa_vpl VALUES ("C17_4","076_7_4","1CO","7","4","4","Jikin matar ba nata ne kaɗai ba, amma na mijinta ne ma. Haka ma jikin mijin, ba na shi ne kaɗai ba, amma na matarsa ne ma. ");
INSERT INTO hausa_vpl VALUES ("C17_5","076_7_5","1CO","7","5","5","Kada ku ƙi kwana da juna sai ko kun yarda a junanku kuma na ɗan lokaci, don ku himmantu ga addu’a. Sa’an nan ku sāke haɗuwa don kada Shaiɗan yă jarrabce ku saboda rashin ƙamewarku. ");
INSERT INTO hausa_vpl VALUES ("C17_6","076_7_6","1CO","7","6","6","Wannan fa shawara ce nake ba ku, ba umarni ba. ");
INSERT INTO hausa_vpl VALUES ("C17_7","076_7_7","1CO","7","7","7","Da ma a ce dukan maza kamar ni suke mana. Sai dai kowa da irin baiwar da Allah ya yi masa; wani yana da wannan baiwa, wani kuwa wancan. ");
INSERT INTO hausa_vpl VALUES ("C17_8","076_7_8","1CO","7","8","8","To, ga marasa aure da gwauraye kuwa ina cewa yana da kyau su zauna haka ba aure, yadda nake. ");
INSERT INTO hausa_vpl VALUES ("C17_9","076_7_9","1CO","7","9","9","Sai dai in ba za su iya ƙame kansu ba, to, su yi aure, don yă fi kyau a yi aure, da sha’awa ta sha kan mutum. ");
INSERT INTO hausa_vpl VALUES ("C17_10","076_7_10","1CO","7","10","10","Ga waɗanda suke da aure kuwa ina ba da wannan umarni (ba ni ba, amma Ubangiji) cewa kada mace ta rabu da mijinta. ");
INSERT INTO hausa_vpl VALUES ("C17_11","076_7_11","1CO","7","11","11","In kuwa ta rabu da shi, sai ta kasance ba aure, ko kuma ta sāke shiryawa da mijinta. Kada miji kuma yă saki matarsa. ");
INSERT INTO hausa_vpl VALUES ("C17_12","076_7_12","1CO","7","12","12","Ga sauran kuwa (ni ne fa na ce ba Ubangiji ba), in wani ɗan’uwa yana da mata wadda ba mai bi ba ce, kuma tana so ta zauna tare da shi, kada yă sake ta. ");
INSERT INTO hausa_vpl VALUES ("C17_13","076_7_13","1CO","7","13","13","In kuma mace tana da miji wanda ba mai bi ba ne, kuma yana so yă zauna tare da ita, kada tă kashe auren. ");
INSERT INTO hausa_vpl VALUES ("C17_14","076_7_14","1CO","7","14","14","Don miji marar ba da gaskiya an tsarkake shi ta wurin matarsa. Mace marar ba da gaskiya kuma an tsarkake ta ta wurin mijinta. In ba haka ba ’ya’yanku ba za su zama da tsarki ba, amma kamar yadda yake, su masu tsarki ne. ");
INSERT INTO hausa_vpl VALUES ("C17_15","076_7_15","1CO","7","15","15","Amma in marar bi ɗin ya raba auren, a ƙyale shi. A irin wannan hali, babu tilas a kan wani, ko wata mai bi. Allah ya kira mu ga zaman lafiya ne. ");
INSERT INTO hausa_vpl VALUES ("C17_16","076_7_16","1CO","7","16","16","Ke mace, kin sani ne, ko ke ce za ki ceci mijinki? Kai miji, ka sani ne, ko kai ne za ka ceci matarka? ");
INSERT INTO hausa_vpl VALUES ("C17_17","076_7_17","1CO","7","17","17","Duk da haka, sai kowa yă kasance a rayuwar da Ubangiji ya sa shi da kuma wanda Allah ya kira shi. Umarnin da na kafa a dukan ikkilisiyoyi ke nan. ");
INSERT INTO hausa_vpl VALUES ("C17_18","076_7_18","1CO","7","18","18","In an riga an yi wa mutum kaciya sa’ad da aka kira shi, to, kada yă zama marar kaciya. In an kira mutum sa’ad da yake marar kaciya, to, kada a yi masa kaciya. ");
INSERT INTO hausa_vpl VALUES ("C17_19","076_7_19","1CO","7","19","19","Kaciya ba wani abu ba ne, rashin kaciya kuma ba wani abu ba ne. Kiyaye umarnin Allah shi ne muhimmin abu. ");
INSERT INTO hausa_vpl VALUES ("C17_20","076_7_20","1CO","7","20","20","Ya kamata kowa yă kasance a matsayin da yake ciki sa’ad da Allah ya kira shi. ");
INSERT INTO hausa_vpl VALUES ("C17_21","076_7_21","1CO","7","21","21","Kai bawa ne sa’ad da aka kira ka? Kada wannan yă dame ka, sai dai in kana iya samun ’yanci, sai ka yi amfani da wannan dama. ");
INSERT INTO hausa_vpl VALUES ("C17_22","076_7_22","1CO","7","22","22","Gama wanda yake bawa sa’ad da Ubangiji ya kira shi, ’yantacce ne na Ubangiji; haka ma, wanda yake ’yantacce sa’ad da aka kira shi, bawa ne na Kiristi. ");
INSERT INTO hausa_vpl VALUES ("C17_23","076_7_23","1CO","7","23","23","Da tsada fa aka saye ku, kada ku zama bayin mutane. ");
INSERT INTO hausa_vpl VALUES ("C17_24","076_7_24","1CO","7","24","24","’Yan’uwa, a duk matsayin da mutum yake sa’ad da aka kira shi, sai yă kasance haka a sabuwar dangantakarsa da Allah. ");
INSERT INTO hausa_vpl VALUES ("C17_25","076_7_25","1CO","7","25","25","To, game da budurwai. Ba ni da wani umarni daga Ubangiji, sai dai na yanke hukunci a matsayi wanda yake amintacce ta wurin jinƙan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("C17_26","076_7_26","1CO","7","26","26","Saboda ƙuncin rayuwar da ake ciki, ina gani ya fi kyau ku kasance yadda kuke. ");
INSERT INTO hausa_vpl VALUES ("C17_27","076_7_27","1CO","7","27","27","In kuna da aure, kada ku nemi kashe auren. In ba ku da aure, kada ku nemi yin aure. ");
INSERT INTO hausa_vpl VALUES ("C17_28","076_7_28","1CO","7","28","28","Amma idan ka riga ka yi aure, to, ba laifi, ba zunubi ba ne, kuma idan yarinya ta yi aure, ba tă yi laifi ba. Sai dai waɗanda suka yi aure za su fuskanci damuwoyi masu yawa a cikin rayuwa, ni kuwa ina so in fisshe su daga wannan. ");
INSERT INTO hausa_vpl VALUES ("C17_29","076_7_29","1CO","7","29","29","’Yan’uwa, abin da nake nufi shi ne, lokaci ya rage kaɗan. Daga yanzu, waɗanda suke da mata ya kamata su yi rayuwa kamar ba su da su; ");
INSERT INTO hausa_vpl VALUES ("C17_30","076_7_30","1CO","7","30","30","waɗanda suke kuka kuma kamar ba kuka suke yi ba, waɗanda suke farin ciki kuwa kamar ba farin ciki suke yi ba. Waɗanda suka sayi abu su yi kamar ba nasu ba ne; ");
INSERT INTO hausa_vpl VALUES ("C17_31","076_7_31","1CO","7","31","31","masu amfani da kayan duniya kuwa, kada su duƙufa a cikinsu. Gama duniyan nan a yadda take mai shuɗewa ce. ");
INSERT INTO hausa_vpl VALUES ("C17_32","076_7_32","1CO","7","32","32","Zan so ku ’yantu daga damuwa. Mutum marar aure ya damu ne da al’amuran Ubangiji, yadda zai gamshi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("C17_33","076_7_33","1CO","7","33","33","Amma mutumin da yake da aure yakan damu ne da al’amuran wannan duniya, yadda zai gamshi matarsa ");
INSERT INTO hausa_vpl VALUES ("C17_34","076_7_34","1CO","7","34","34","hankalinsa a rabe yake. Mace marar aure ko kuwa budurwa ta damu ne da al’amuran Ubangiji. Nufinta shi ne ta ba da kanta ga Ubangiji cikin jiki da ruhu. Amma mace da take da aure ta damu ne da al’amuran wannan duniya, yadda za tă gamshi mijinta. ");
INSERT INTO hausa_vpl VALUES ("C17_35","076_7_35","1CO","7","35","35","Na faɗa haka don amfaninku ne, ba don in ƙuntata muku ba. Sai dai don ku yi rayuwa a hanyar da ta dace da nufin ku himmantu ga bautar Ubangiji ba da raba hankali ba. ");
INSERT INTO hausa_vpl VALUES ("C17_36","076_7_36","1CO","7","36","36","In mutum ya ga cewa ba ya nuna halin da ya kamata ga budurwar da ya yi alkawarin aure da ita, in kuma shekarunta suna wucewa, shi kuma ya ga ya kamata yă yi aure, to, sai yă yi. Ba zunubi ba ne. Ya kamata su yi aure. ");
INSERT INTO hausa_vpl VALUES ("C17_37","076_7_37","1CO","7","37","37","Amma mutumin da ya riga ya yanke shawara a ransa, wanda kuma ba lalle ba ne amma yana iya shan kan nufinsa, kuma ya riga ya zartar a zuciyarsa ba zai auri budurwar ba, wannan mutum ma ya yi abin da ya dace. ");
INSERT INTO hausa_vpl VALUES ("C17_38","076_7_38","1CO","7","38","38","Don haka, wanda ya auri budurwar ya yi daidai, amma wanda bai aure ta ba ya ma fi. ");
INSERT INTO hausa_vpl VALUES ("C17_39","076_7_39","1CO","7","39","39","Mace tana haɗe da mijinta muddin yana da rai. Amma in mijinta ya mutu, tana da ’yanci ta auri wanda take so. Amma fa, sai mai bin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("C17_40","076_7_40","1CO","7","40","40","A nawa ra’ayi, za tă fi jin daɗi in ta zauna haka, a ganina kuwa ina ba ku shawara ce daga Ruhun Allah da na ce haka. ");
INSERT INTO hausa_vpl VALUES ("C18_1","076_8_1","1CO","8","1","1","To, game da abincin da aka miƙa hadaya ga gumaka kuwa. Mun san cewa dukanmu muna da ilimi. Ilimi yakan kawo girman kai, amma ƙauna takan gina. ");
INSERT INTO hausa_vpl VALUES ("C18_2","076_8_2","1CO","8","2","2","Mutumin da yake tsammani ya san abu, sanin da yake da shi bai isa ba. ");
INSERT INTO hausa_vpl VALUES ("C18_3","076_8_3","1CO","8","3","3","Amma mutumin da yake ƙaunar Allah, Allah yana sane da shi. ");
INSERT INTO hausa_vpl VALUES ("C18_4","076_8_4","1CO","8","4","4","To, game da cin abincin da aka miƙa hadaya ga gumaka kuwa, mun san cewa “Gunki ba kome ba ne a duniya”, kuma “Babu wani Allah sai dai ɗaya.” ");
INSERT INTO hausa_vpl VALUES ("C18_5","076_8_5","1CO","8","5","5","Gama ko da akwai abubuwan da ake ce da su alloli, a sama ko a ƙasa (don kuwa akwai “alloli” da “iyayengiji” da yawa), ");
INSERT INTO hausa_vpl VALUES ("C18_6","076_8_6","1CO","8","6","6","duk da haka a gare mu dai akwai Allah ɗaya kaɗai, Uba, wanda dukan abubuwa suke daga gare shi, wanda kuma saboda shi ne muke rayuwa, kuma akwai Ubangiji ɗaya, Yesu Kiristi, wanda ta wurinsa ne aka yi dukan abu, ta wurinsa ne kuma muke rayuwa. ");
INSERT INTO hausa_vpl VALUES ("C18_7","076_8_7","1CO","8","7","7","Amma ba kowa ne ya san wannan ba. Har yanzu, waɗansu mutane sun saba da tunani cewa gumaka ainihi ne, saboda haka sa’ad da suka ci irin abincin nan, sukan ɗauka cewa kamar an miƙa wa ga gunki ne, kuma da yake lamirinsu ba ƙarfi, yakan ƙazantu. ");
INSERT INTO hausa_vpl VALUES ("C18_8","076_8_8","1CO","8","8","8","Gaskiya ne cewa ba ma samun yardar Allah ta wurin abin da muke ci. Ba ma rasa wani abu idan ba mu ci ba, kuma ba ma ƙaru da wani abu in muka ci. ");
INSERT INTO hausa_vpl VALUES ("C18_9","076_8_9","1CO","8","9","9","Sai dai ku yi hankali, kada yin amfani da ’yancinku yă zama abin sa tuntuɓe ga marasa ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("C18_10","076_8_10","1CO","8","10","10","Gama in wani wanda lamirinsa ba shi da ƙarfi ya gan ka, kai da kake da wannan sani, kana ci a haikalin gumaka, ashe, ba zai sami ƙarfin halin cin abin da aka miƙa wa gumaka ba? ");
INSERT INTO hausa_vpl VALUES ("C18_11","076_8_11","1CO","8","11","11","Saboda haka ta wurin sanin nan naka sai ka sa wannan ɗan’uwa marar ƙarfi wanda Kiristi ya mutu dominsa yă hallaka. ");
INSERT INTO hausa_vpl VALUES ("C18_12","076_8_12","1CO","8","12","12","Sa’ad da ka rushe lamiri mai bi marar ƙarfi, ka yi wa Kiristi zunubi ke nan. ");
INSERT INTO hausa_vpl VALUES ("C18_13","076_8_13","1CO","8","13","13","Saboda haka, in abin da nake ci zai sa ɗan’uwana yă yi zunubi, ba zan ƙara cin nama ba, don kada in sa shi yă yi tuntuɓe. ");
INSERT INTO hausa_vpl VALUES ("C19_1","076_9_1","1CO","9","1","1","Ba ni da ’yanci ne? Ni ba manzo ba ne? Ni ban gan Yesu Ubangijinmu ba ne? Ba ku ne sakamakon aikina cikin Ubangiji ba? ");
INSERT INTO hausa_vpl VALUES ("C19_2","076_9_2","1CO","9","2","2","Ko da waɗansu ba su ɗauke ni a matsayin manzo ba, tabbatacce, ni manzo ne a gare ku! Gama ku ne hatimin manzancina a gaban Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("C19_3","076_9_3","1CO","9","3","3","Wannan ita ce kāriyata ga waɗanda suke tuhumata game da manzancina. ");
INSERT INTO hausa_vpl VALUES ("C19_4","076_9_4","1CO","9","4","4","Ba mu da ’yancin ci da sha ne? ");
INSERT INTO hausa_vpl VALUES ("C19_5","076_9_5","1CO","9","5","5","Ba mu da ’yancin tafiya tare da matar da muka aura mai bi kamar sauran manzanni da ’yan’uwan Ubangiji da kuma Kefas suke yi? ");
INSERT INTO hausa_vpl VALUES ("C19_6","076_9_6","1CO","9","6","6","Ko ni da Barnabas ne kawai ba mu da ’yanci a ɗauke mana aikin ci da kai? ");
INSERT INTO hausa_vpl VALUES ("C19_7","076_9_7","1CO","9","7","7","Wa yake ciyar da kansa yayinda yake aikin soja? Wa yake shukar gonar inabi, da ba ya cin amfaninta? Wa yake kiwon garke, da ba ya sha madararsa? ");
INSERT INTO hausa_vpl VALUES ("C19_8","076_9_8","1CO","9","8","8","Ina faɗin wannan bisa ga ra’ayin mutum kawai ne? Ashe, Doka ma ba tă faɗa haka ba? ");
INSERT INTO hausa_vpl VALUES ("C19_9","076_9_9","1CO","9","9","9","Gama yana a rubuce a cikin Dokar Musa cewa, “Kada ka sa wa saniya takunkumi sa’ad da yake sussukar hatsi.” Kuna tsammani a kan shanu ne Allah ya damu sa’ad da ya ce haka? ");
INSERT INTO hausa_vpl VALUES ("C19_10","076_9_10","1CO","9","10","10","Babu shakka, ya yi maganan nan saboda mu ne. Ko ba haka ba? I, an rubuta wannan saboda mu ne, domin sa’ad da mai noma yake noma, mai sussuka kuma yana sussuka, suna wannan ne da bege za su sami rabonsu daga girbin. ");
INSERT INTO hausa_vpl VALUES ("C19_11","076_9_11","1CO","9","11","11","In muka shuka iri na ruhaniya a cikinku, ashe, bai kamata mu yi girbin abin biyan bukatarmu daga gare ku ba? ");
INSERT INTO hausa_vpl VALUES ("C19_12","076_9_12","1CO","9","12","12","In waɗansu suna samun wannan taimako daga gare ku, ashe, mu ba mu fi cancanta mu samu ba? Amma ba mu yi amfani da wannan ’yancin ba. A maimakon haka, mun jure da kome, domin kada mu hana bisharar Kiristi yaɗuwa. ");
INSERT INTO hausa_vpl VALUES ("C19_13","076_9_13","1CO","9","13","13","Ashe, ba ku san cewa waɗanda suke hidima a haikali suna samun abincinsu daga haikali ba ne, waɗanda kuma suke hidima a bagade suna samun rabo a hadayar da suka miƙa ba ne? ");
INSERT INTO hausa_vpl VALUES ("C19_14","076_9_14","1CO","9","14","14","Haka ma Ubangiji ya umarta cewa ya kamata waɗanda suke wa’azin bishara, su sami abin biyan bukatarsu daga bisharar. ");
INSERT INTO hausa_vpl VALUES ("C19_15","076_9_15","1CO","9","15","15","Amma ban yi amfani da ko ɗaya daga cikin waɗannan ’yancin ba. Ba kuma ina rubuta muku wannan da fata za ku yi mini waɗannan abubuwa ba ne. Gwamma in mutu, da wani yă hana ni wannan abin taƙama. ");
INSERT INTO hausa_vpl VALUES ("C19_16","076_9_16","1CO","9","16","16","Duk da haka, sa’ad da ina wa’azin bishara, ba na taƙama, domin tilas ne a gare ni in yi wa’azi. Kaitona, in ban yi wa’azin bishara ba! ");
INSERT INTO hausa_vpl VALUES ("C19_17","076_9_17","1CO","9","17","17","In na yi wa’azi da yardar rai, ina da lada; in ba da yardar rai ba, ina dai cika amana da aka danƙa mini ne. ");
INSERT INTO hausa_vpl VALUES ("C19_18","076_9_18","1CO","9","18","18","To, mene ne ladana? Ladana kaɗai shi ne, in yi wa’azin bishara, in kuma yi shi a kyauta, yadda ba zan yi amfani da ’yancina cikin wa’azin ba. ");
INSERT INTO hausa_vpl VALUES ("C19_19","076_9_19","1CO","9","19","19","Ko da yake ina da ’yanci ba na kuma ƙarƙashin kowa, na mai da kaina bawa ga kowa, domin in rinjayi mutane da yawa. ");
INSERT INTO hausa_vpl VALUES ("C19_20","076_9_20","1CO","9","20","20","Ga Yahudawa na zama kamar mutumin Yahuda, domin in rinjayi Yahudawa. Ga waɗanda suke ƙarƙashin doka kuma, na zama kamar wanda yake ƙarƙashin Dokar (ko da yake ni kaina ba na ƙarƙashin Doka), domin in rinjayi waɗanda suke ƙarƙashin Doka. ");
INSERT INTO hausa_vpl VALUES ("C19_21","076_9_21","1CO","9","21","21","Ga waɗanda ba su da Dokar kuwa, na zama kamar wanda ba shi da Dokar (ko da yake ba ni da ’yanci daga dokar Allah, amma ina ƙarƙashin dokar Kiristi), domin in rinjayi waɗanda ba su da dokar. ");
INSERT INTO hausa_vpl VALUES ("C19_22","076_9_22","1CO","9","22","22","Ga waɗanda ba su da ƙarfi, na zama marar ƙarfi, domin in rinjayi waɗanda ba su da ƙarfi. Na zama dukan abu ga dukan mutane, domin ko ta yaya in zai yiwu, in ceci waɗansu. ");
INSERT INTO hausa_vpl VALUES ("C19_23","076_9_23","1CO","9","23","23","Ina yin dukan waɗannan ne saboda bishara, domin in sami rabo a cikin albarkarta. ");
INSERT INTO hausa_vpl VALUES ("C19_24","076_9_24","1CO","9","24","24","Ba ku sani ba cewa a gasar gudu, dukan masu gudu sukan yi gudu, amma guda ne kaɗai yakan sami lada? To, sai ku yi gudu yadda za ku sami lada. ");
INSERT INTO hausa_vpl VALUES ("C19_25","076_9_25","1CO","9","25","25","Duk ’yan wasan gasa sukan hori kansu sosai. Sukan yi haka domin su sami rawanin da ba zai daɗe ba. Amma mu muna yi ne domin mu sami rawanin da zai dawwama. ");
INSERT INTO hausa_vpl VALUES ("C19_26","076_9_26","1CO","9","26","26","To, ni fa ba gudu nake yi kamar mai gudu ba wurin zuwa ba. Dambena kuma ba naushin iska nake yi ba. ");
INSERT INTO hausa_vpl VALUES ("C19_27","076_9_27","1CO","9","27","27","A’a, ina horon jikina in mai da shi bawana, saboda bayan na yi wa waɗansu wa’azi, ni kaina kada in kāsa cancantar samun lada. ");
INSERT INTO hausa_vpl VALUES ("C110_1","076_10_1","1CO","10","1","1","Ba na so ku kasance da rashin sani, ’yan’uwa, cewa dukan kakannin-kakanninmu sun yi tafiya a ƙarƙashin girgije, dukansu kuma suka bi ta tsakiyar teku. ");
INSERT INTO hausa_vpl VALUES ("C110_2","076_10_2","1CO","10","2","2","An yi wa dukansu baftisma ga bin Musa a cikin girgije da kuma cikin teku. ");
INSERT INTO hausa_vpl VALUES ("C110_3","076_10_3","1CO","10","3","3","Dukansu sun ci abincin ruhaniya guda ");
INSERT INTO hausa_vpl VALUES ("C110_4","076_10_4","1CO","10","4","4","suka kuma sha ruwan ruhaniyan nan guda; gama sun sha daga dutsen ruhaniya nan, wanda ya yi tafiya tare da su, wannan dutsen kuwa Kiristi ne. ");
INSERT INTO hausa_vpl VALUES ("C110_5","076_10_5","1CO","10","5","5","Duk da haka, Allah bai ji daɗin yawancinsu ba; gawawwakinsu kuwa suka bazu ko’ina a cikin hamada. ");
INSERT INTO hausa_vpl VALUES ("C110_6","076_10_6","1CO","10","6","6","To, waɗannan abubuwa misalai ne a gare mu, kada mu yi marmarin mugayen abubuwa, kamar yadda suka yi. ");
INSERT INTO hausa_vpl VALUES ("C110_7","076_10_7","1CO","10","7","7","Kada ku zama masu bautar gumaka, yadda waɗansunsu suka zama; kamar yadda yake a rubuce cewa, “Mutanen suka zauna don su ci su kuma sha, suka kuma tashi suka shiga rawa ta rashin kunya.” ");
INSERT INTO hausa_vpl VALUES ("C110_8","076_10_8","1CO","10","8","8","Kada fa mu yi fasikanci yadda waɗansunsu suka yi, har a rana guda mutane dubu ashirin da uku a cikinsu suka mutu. ");
INSERT INTO hausa_vpl VALUES ("C110_9","076_10_9","1CO","10","9","9","Kada mu gwada Kiristi yadda waɗansunsu suka yi, har macizai suka kakkashe su. ");
INSERT INTO hausa_vpl VALUES ("C110_10","076_10_10","1CO","10","10","10","Kada kuma ku yi gunaguni yadda waɗansunsu suka yi, har mala’ika mai hallakarwa ya hallaka su. ");
INSERT INTO hausa_vpl VALUES ("C110_11","076_10_11","1CO","10","11","11","Waɗannnan abubuwa sun same su ne, domin su zama abubuwan koyi, aka kuma rubuta su domin a gargaɗe mu, mu da ƙarshen zamani ya zo mana. ");
INSERT INTO hausa_vpl VALUES ("C110_12","076_10_12","1CO","10","12","12","Saboda haka in kana tsammani kana tsaye ne, to, ka yi hankali kada ka fāɗi! ");
INSERT INTO hausa_vpl VALUES ("C110_13","076_10_13","1CO","10","13","13","Ba jarrabar da ta taɓa samunku, wadda ba a saba yi wa mutum ba. Allah mai aminci ne; ba zai bari a jarrabce ku fiye da ƙarfinku ba. Amma in aka jarrabce ku, zai nuna muku mafita, domin ku iya cin nasara. ");
INSERT INTO hausa_vpl VALUES ("C110_14","076_10_14","1CO","10","14","14","Saboda haka abokaina ƙaunatattu, ku guje wa bautar gumaka. ");
INSERT INTO hausa_vpl VALUES ("C110_15","076_10_15","1CO","10","15","15","Ina magana da ku a kan ku mutane ne fa masu azanci; ku duba da kanku ku ga abin da nake faɗa. ");
INSERT INTO hausa_vpl VALUES ("C110_16","076_10_16","1CO","10","16","16","Kwaf nan na godiya da muke yin godiya da shi, ashe ba tarayya ce a cikin jinin Kiristi ba? Wannan burodi kuma da muke karya mu ci, ashe, ba tarayya ne a cikin jikin Kiristi ba? ");
INSERT INTO hausa_vpl VALUES ("C110_17","076_10_17","1CO","10","17","17","Da yake burodin nan ɗaya ne, ashe kuwa, mu da muke da yawa jiki ɗaya ne, gama dukanmu muna ci daga burodi nan guda. ");
INSERT INTO hausa_vpl VALUES ("C110_18","076_10_18","1CO","10","18","18","Ku dubi mutanen Isra’ila mana. Ashe, waɗanda suke cin hadayu, ba ɗaya suke da juna cikin cin hadayun da aka miƙa a bagade ba? ");
INSERT INTO hausa_vpl VALUES ("C110_19","076_10_19","1CO","10","19","19","To, me kuke tsammani nake nufi a nan? Hadayar da aka miƙa wa gunki ce wani abu, ko kuma gunkin ne wani abu? ");
INSERT INTO hausa_vpl VALUES ("C110_20","076_10_20","1CO","10","20","20","A’a, ina nufin akan miƙa hadayun da masu bautar gumaka suka wa aljanu ne, ba Allah ba. Ba na so ku zama ɗaya da aljanu. ");
INSERT INTO hausa_vpl VALUES ("C110_21","076_10_21","1CO","10","21","21","Ba zai yiwu ku sha daga kwaf na Ubangiji ku kuma sha daga kwaf na aljanu ba, ba ya yiwuwa ku ci a teburin Ubangiji, ku kuma ci a teburin aljanu. ");
INSERT INTO hausa_vpl VALUES ("C110_22","076_10_22","1CO","10","22","22","Ashe, so muke mu tsokani Ubangiji ya yi kishi? Mun fi shi ƙarfi ne? ");
INSERT INTO hausa_vpl VALUES ("C110_23","076_10_23","1CO","10","23","23","“Ana da dama a yi kome” sai dai ba kome ba ne yake da amfani. “Ana da dama a yi kome” sai dai ba kome ba ne mai ginawa. ");
INSERT INTO hausa_vpl VALUES ("C110_24","076_10_24","1CO","10","24","24","Kada wani yă kula da kansa kawai, sai dai yă kula da waɗansu kuma. ");
INSERT INTO hausa_vpl VALUES ("C110_25","076_10_25","1CO","10","25","25","Ku ci kowane abin da ake sayarwa a kasuwar nama ba sai kun tambaya ba don kada lamiri yă damu da inda abin ya fito, ");
INSERT INTO hausa_vpl VALUES ("C110_26","076_10_26","1CO","10","26","26","gama “Duniya da duk abin da yake cikinta na Ubangiji ne.” ");
INSERT INTO hausa_vpl VALUES ("C110_27","076_10_27","1CO","10","27","27","In wani marar bi ya gayyace ku cin abinci kuka kuwa yarda ku je, sai ku ci ko mene ne da aka sa a gabanku, ba tare da tambaya don kada lamiri yă damu da inda abin ya fito. ");
INSERT INTO hausa_vpl VALUES ("C110_28","076_10_28","1CO","10","28","28","Sai dai in wani ya ce muku, “Ai, wannan an miƙa ne wa gunki,” to, kada ku ci, saboda duban mutuncin wannan da ya gaya muku, don kuma lamiri yă kasance babu laifi ");
INSERT INTO hausa_vpl VALUES ("C110_29","076_10_29","1CO","10","29","29","ina nufin lamirin wancan mutum ne fa, ba naku ba. Don me lamirin wani zai shari’anta ’yancina? ");
INSERT INTO hausa_vpl VALUES ("C110_30","076_10_30","1CO","10","30","30","In na ci abinci da godiya, don me za a zarge ni a kan abin da na ci da godiya ga Allah? ");
INSERT INTO hausa_vpl VALUES ("C110_31","076_10_31","1CO","10","31","31","Saboda haka, duk abin da kuke yi, ko ci ko sha, ku yi shi duka saboda ɗaukakar Allah. ");
INSERT INTO hausa_vpl VALUES ("C110_32","076_10_32","1CO","10","32","32","Kada ku sa wani yă yi tuntuɓe, ko mutumin Yahuda ne, ko mutumin Al’ummai ko kuma ikkilisiyar Allah ");
INSERT INTO hausa_vpl VALUES ("C110_33","076_10_33","1CO","10","33","33","kamar dai yadda nake ƙoƙarin faranta wa kowa rai, ta kowace hanya. Gama ba don kaina kaɗai nake yi ba, sai dai don amfanin mutane da yawa, don su sami ceto. ");
INSERT INTO hausa_vpl VALUES ("C111_1","076_11_1","1CO","11","1","1","Ku bi gurbina, kamar yadda ni nake bin gurbin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("C111_2","076_11_2","1CO","11","2","2","Ina yabonku saboda kuna tunawa da ni a cikin kowane abu, kuna kuma riƙe da koyarwar, yadda na ba ku. ");
INSERT INTO hausa_vpl VALUES ("C111_3","076_11_3","1CO","11","3","3","To, ina so ku gane cewa shugaban kowane namiji Kiristi ne, shugaban mace namiji ne, shugaban Kiristi kuma Allah ne. ");
INSERT INTO hausa_vpl VALUES ("C111_4","076_11_4","1CO","11","4","4","Kowane namijin da ya yi addu’a ko annabci da kansa a rufe ya jawo kunya wa kansa. ");
INSERT INTO hausa_vpl VALUES ("C111_5","076_11_5","1CO","11","5","5","Duk macen da ta yi addu’a ko annabci da kanta a buɗe kuwa ta rena kanta, ya zama kamar an aske kanta ke nan. ");
INSERT INTO hausa_vpl VALUES ("C111_6","076_11_6","1CO","11","6","6","In mace ba ta so tă rufe kanta, to, sai tă aske gashinta; in kuwa abin kunya ne mace tă yanke ko tă aske gashinta, to, sai tă rufe kanta. ");
INSERT INTO hausa_vpl VALUES ("C111_7","076_11_7","1CO","11","7","7","Namiji kuwa bai kamata ya rufe kansa ba, da yake shi kamannin Allah ne, da kuma darajar Allah, amma mace dai, darajar namiji ne. ");
INSERT INTO hausa_vpl VALUES ("C111_8","076_11_8","1CO","11","8","8","Gama namiji bai fito daga mace ba, sai dai mace ce ta fito daga namiji. ");
INSERT INTO hausa_vpl VALUES ("C111_9","076_11_9","1CO","11","9","9","Ba a kuma halicci namiji don mace ba, sai dai mace don namiji. ");
INSERT INTO hausa_vpl VALUES ("C111_10","076_11_10","1CO","11","10","10","Don haka, saboda wannan, da kuma saboda mala’iku, dole mace ta ɗaura wani abu a kanta. ");
INSERT INTO hausa_vpl VALUES ("C111_11","076_11_11","1CO","11","11","11","Duk da haka a cikin Ubangiji, mace ba a rabe take da namiji ba, namiji kuma ba a rabe yake da mace ba. ");
INSERT INTO hausa_vpl VALUES ("C111_12","076_11_12","1CO","11","12","12","Kamar yadda mace ta fito daga namiji, haka kuma aka haifi namiji ta wurin mace. Sai dai kowane abu daga Allah yake. ");
INSERT INTO hausa_vpl VALUES ("C111_13","076_11_13","1CO","11","13","13","Ku kanku duba mana. Ya yi kyau mace tă yi addu’a ga Allah da kanta a buɗe? ");
INSERT INTO hausa_vpl VALUES ("C111_14","076_11_14","1CO","11","14","14","Kai, yadda halitta take ma, ai, ta koya muku cewa in namiji yana da dogon gashi, abin kunya ne a gare shi, ");
INSERT INTO hausa_vpl VALUES ("C111_15","076_11_15","1CO","11","15","15","amma in mace tana da dogon gashi, ai, daraja ce a gare ta. Gama an ba ta dogon gashi saboda rufe kanta ne. ");
INSERT INTO hausa_vpl VALUES ("C111_16","076_11_16","1CO","11","16","16","In akwai mai gardama da wannan, to, mu dai ba mu da wata al’ada, haka ma ikkilisiyoyin Allah. ");
INSERT INTO hausa_vpl VALUES ("C111_17","076_11_17","1CO","11","17","17","Game da umarnan nan dai, ban yaba muku ba, domin taruwarku ba ta kirki ba ce, ɓarna ce. ");
INSERT INTO hausa_vpl VALUES ("C111_18","076_11_18","1CO","11","18","18","Da farko dai, na ji cewa sa’ad da kuka taru a matsayin ikkilisiya, akwai tsattsaguwa a tsakaninku, har na fara yarda da zancen. ");
INSERT INTO hausa_vpl VALUES ("C111_19","076_11_19","1CO","11","19","19","Ba shakka dole a sami bambanci a tsakaninku don a nuna wa Allah ya amince da shi a cikinku. ");
INSERT INTO hausa_vpl VALUES ("C111_20","076_11_20","1CO","11","20","20","Sa’ad da kuka taru, ba Cimar Ubangiji kuke ci ba, ");
INSERT INTO hausa_vpl VALUES ("C111_21","076_11_21","1CO","11","21","21","gama yayinda kuke ci, kowa yakan ci gaba ba tare da jiran wani ba. Wani yă zauna da yunwa, wani kuma yă bugu. ");
INSERT INTO hausa_vpl VALUES ("C111_22","076_11_22","1CO","11","22","22","Kai, ba ku da gidajen da za ku ci ku sha ne? Ko dai kun rena ikkilisiyar Allah ne, kuna kuma wulaƙanta waɗanda ba su da kome? Me zan ce muku? In yabe ku ne game da wannan? A’a, ko kaɗan! ");
INSERT INTO hausa_vpl VALUES ("C111_23","076_11_23","1CO","11","23","23","Gama abin da na karɓa daga wurin Ubangiji shi ne nake ba ku. Ubangiji Yesu, a daren da aka bashe shi, ya ɗauki burodi, ");
INSERT INTO hausa_vpl VALUES ("C111_24","076_11_24","1CO","11","24","24","bayan ya yi godiya, sai ya kakkarya ya ce, “Wannan jikina ne, wanda yake dominku, ku yi wannan don tunawa da ni.” ");
INSERT INTO hausa_vpl VALUES ("C111_25","076_11_25","1CO","11","25","25","Haka kuma bayan cimar, ya ɗauki kwaf, yana cewa, “Wannan kwaf ne sabon alkawari a jinina; ku yi wannan, a duk sa’ad da kuke sha, don tunawa da ni.” ");
INSERT INTO hausa_vpl VALUES ("C111_26","076_11_26","1CO","11","26","26","Gama a duk sa’ad da kuke cin wannan burodi, kuke kuma sha daga wannan kwaf, kuna shelar mutuwar Ubangiji ne har yă dawo. ");
INSERT INTO hausa_vpl VALUES ("C111_27","076_11_27","1CO","11","27","27","Saboda haka, duk wanda ya ci burodin ko ya sha daga kwaf na Ubangiji da rashin cancanta, ya yi laifin wulaƙanta jiki da jinin Ubangiji ke nan. ");
INSERT INTO hausa_vpl VALUES ("C111_28","076_11_28","1CO","11","28","28","Dole kowa yă bincike kansa kafin yă ci burodin yă kuma sha daga kwaf ɗin. ");
INSERT INTO hausa_vpl VALUES ("C111_29","076_11_29","1CO","11","29","29","Gama duk wanda ya ci ya kuma sha ba tare da fahimtar jikin Ubangiji ba, ya ci ya kuma sha wa kansa hukunci ne. ");
INSERT INTO hausa_vpl VALUES ("C111_30","076_11_30","1CO","11","30","30","Shi ya sa da yawa a cikinku ba su da ƙarfi, suna kuma da rashin lafiya, waɗansunku kuma sun riga sun yi barci. ");
INSERT INTO hausa_vpl VALUES ("C111_31","076_11_31","1CO","11","31","31","Amma in da za mu auna kanmu sosai, da ba za mu shiga irin hukuncin nan ba. ");
INSERT INTO hausa_vpl VALUES ("C111_32","076_11_32","1CO","11","32","32","Duk da haka sa’ad da Ubangiji ya hukunta mu, ana yin mana horo ne don kada a ƙarshe a hallaka mu tare da duniya. ");
INSERT INTO hausa_vpl VALUES ("C111_33","076_11_33","1CO","11","33","33","Saboda haka ’yan’uwana, sa’ad da kuka taru don ci, ku jira juna. ");
INSERT INTO hausa_vpl VALUES ("C111_34","076_11_34","1CO","11","34","34","In wani yana jin yunwa, sai yă ci abinci a gida, saboda in kuka taru kada yă jawo hukunci. Sa’ad da na zo kuma zan ba da ƙarin umarnai. ");
INSERT INTO hausa_vpl VALUES ("C112_1","076_12_1","1CO","12","1","1","To, game da baye-baye na ruhaniya, ’yan’uwa, ba na so ku kasance da rashin sani. ");
INSERT INTO hausa_vpl VALUES ("C112_2","076_12_2","1CO","12","2","2","Kun san cewa sa’ad da kuke masu bautar gumaka, ya zama, an shawo kanku, aka kuma ɓad da ku ga bin gumaka marasa magana. ");
INSERT INTO hausa_vpl VALUES ("C112_3","076_12_3","1CO","12","3","3","Saboda haka, ina gaya muku cewa ba wani mai magana da ikon Ruhun Allah da zai ce, “Yesu la’ananne ne,” haka kuma ba wanda zai ce, “Yesu Ubangiji ne,” sai wanda Ruhu Mai Tsarki yake bi da shi. ");
INSERT INTO hausa_vpl VALUES ("C112_4","076_12_4","1CO","12","4","4","Akwai baye-baye iri dabam-dabam, amma Ruhu ɗaya ne. ");
INSERT INTO hausa_vpl VALUES ("C112_5","076_12_5","1CO","12","5","5","Akwai hidimomi iri-iri, amma Ubangiji ɗaya ne. ");
INSERT INTO hausa_vpl VALUES ("C112_6","076_12_6","1CO","12","6","6","Akwai aiki iri-iri, amma duk Allah ɗaya ne yake aikata su a cikin dukan mutane. ");
INSERT INTO hausa_vpl VALUES ("C112_7","076_12_7","1CO","12","7","7","An ba wa kowane mutum bayyanuwar Ruhu don amfanin kowa. ");
INSERT INTO hausa_vpl VALUES ("C112_8","076_12_8","1CO","12","8","8","Ga wani, an ba shi saƙon hikima ta wurin Ruhu, ga wani baiwar saƙon sani ta wurin wannan Ruhu guda. ");
INSERT INTO hausa_vpl VALUES ("C112_9","076_12_9","1CO","12","9","9","Ga wani bangaskiya ta wurin wannan Ruhu, ga wani kuma baiwar warkarwa ta wurin wannan Ruhu guda. ");
INSERT INTO hausa_vpl VALUES ("C112_10","076_12_10","1CO","12","10","10","Ga wani yin ayyukan banmamaki, ga wani annabci, ga wani baiwar rarrabe ruhohi, ga wani baiwar magana da harsuna dabam-dabam, ga wani har wa yau iya fassarar harsuna. ");
INSERT INTO hausa_vpl VALUES ("C112_11","076_12_11","1CO","12","11","11","Duk waɗannan aiki ne na wannan Ruhu guda, yana kuma ba da su ga kowane mutum, yadda yake so. ");
INSERT INTO hausa_vpl VALUES ("C112_12","076_12_12","1CO","12","12","12","Jiki guda ne, ko da yake an yi shi da gaɓoɓi da yawa; gaɓoɓin kuma ko da yake da yawa suke, jiki ɗaya ne. Haka yake da Kiristi. ");
INSERT INTO hausa_vpl VALUES ("C112_13","076_12_13","1CO","12","13","13","Dukanmu an yi mana baftisma ta wurin Ruhu guda zuwa ga jiki guda, ko Yahudawa ko Hellenawa, bawa ko ’yantacce, an kuma ba wa dukanmu wannan Ruhu guda mu sha. ");
INSERT INTO hausa_vpl VALUES ("C112_14","076_12_14","1CO","12","14","14","To, ba a yi jiki da gaɓa ɗaya kawai ba, amma da gaɓoɓi da yawa. ");
INSERT INTO hausa_vpl VALUES ("C112_15","076_12_15","1CO","12","15","15","Da ƙafa za tă ce, “Saboda ni ba hannu ba ce, ni ba gaɓar jiki ba ce.” Wannan ba zai hana ta zama gaɓar jikin ba. ");
INSERT INTO hausa_vpl VALUES ("C112_16","076_12_16","1CO","12","16","16","Da kunne zai ce, “Saboda ni ba ido ba ne, ni ba gaɓar jiki ba ne.” Wannan ba zai hana shi zama gaɓar jikin ba. ");
INSERT INTO hausa_vpl VALUES ("C112_17","076_12_17","1CO","12","17","17","Da a ce dukan jiki ido ne, da me za a ji? Da kuma a ce dukan jiki kunne ne, da me za a sansana? ");
INSERT INTO hausa_vpl VALUES ("C112_18","076_12_18","1CO","12","18","18","Tabbatacce, Allah ya shirya gaɓoɓin jiki, kowannensu, kamar yadda yake so su zama. ");
INSERT INTO hausa_vpl VALUES ("C112_19","076_12_19","1CO","12","19","19","Da a ce dukan jiki gaɓa ɗaya ne, da ina sauran jikin? ");
INSERT INTO hausa_vpl VALUES ("C112_20","076_12_20","1CO","12","20","20","Yadda yake dai, akwai gaɓoɓi da yawa, amma jiki ɗaya. ");
INSERT INTO hausa_vpl VALUES ("C112_21","076_12_21","1CO","12","21","21","Ba dama ido ya ce wa hannu, “Ba na bukatarka ba!” Kai kuma ba zai ce wa ƙafafu, “Ba na bukatarku ba!” ");
INSERT INTO hausa_vpl VALUES ("C112_22","076_12_22","1CO","12","22","22","A maimakon haka, gaɓoɓin jiki da ake gani kamar ba su da ƙarfi, su ne masu muhimmanci. ");
INSERT INTO hausa_vpl VALUES ("C112_23","076_12_23","1CO","12","23","23","Kuma gaɓoɓin da muke tsammani ba su da martaba sosai, su ne mukan fi ba su girma. Sa’an nan gaɓoɓi marasa kyan gani, mun fi mai da hankali a kansu, ");
INSERT INTO hausa_vpl VALUES ("C112_24","076_12_24","1CO","12","24","24","gaɓoɓi masu kyan gani kuwa, ba su bukatar yawan girmamawa. Allah ya harhaɗa jikunanmu yadda gaɓoɓin da ake gani kamar ba su da muhimmanci suna da amfani, ");
INSERT INTO hausa_vpl VALUES ("C112_25","076_12_25","1CO","12","25","25","don kada rarrabuwa ta kasance a jiki, sai dai gaɓoɓin jiki su kula da juna. ");
INSERT INTO hausa_vpl VALUES ("C112_26","076_12_26","1CO","12","26","26","In wata gaɓa tana a damuwa, duk sai su damu tare. In kuma an ɗaukaka wata gaɓa, sai duk su yi farin ciki tare. ");
INSERT INTO hausa_vpl VALUES ("C112_27","076_12_27","1CO","12","27","27","To, ku jikin Kiristi ne, kowannenku kuwa gaɓarsa ne. ");
INSERT INTO hausa_vpl VALUES ("C112_28","076_12_28","1CO","12","28","28","A cikin ikkilisiya, da farko dai Allah ya zaɓa waɗansu ya naɗa su su zama manzanni, na biyu annabawa, na uku malamai, sa’an nan masu yin ayyukan banmamaki, sai masu baiwar warkarwa, da masu taimakon waɗansu, da masu baiwar gudanarwa, sa’an nan kuma masu magana da harsuna iri-iri. ");
INSERT INTO hausa_vpl VALUES ("C112_29","076_12_29","1CO","12","29","29","Shin, duka ne manzanni? Duka ne annabawa? Duka ne malamai? Duka ne suke da baiwar yin ayyukan banmamaki? ");
INSERT INTO hausa_vpl VALUES ("C112_30","076_12_30","1CO","12","30","30","Duka ne suke da baiwar warkarwa? Duka ne suke magana da harsuna? Duka ne suke iya fassara? ");
INSERT INTO hausa_vpl VALUES ("C112_31","076_12_31","1CO","12","31","31","Sai dai ku yi marmarin neman baye-baye mafi girma. Yanzu kuwa zan nuna muku mafificiyar hanya. ");
INSERT INTO hausa_vpl VALUES ("C113_1","076_13_1","1CO","13","1","1","In ina iya yin magana da harsunan mutane, da na mala’iku, amma ba ni da ƙauna, na zama kamar kuge mai yawan ƙara, ko kuma ƙararrawa mai amo kawai. ");
INSERT INTO hausa_vpl VALUES ("C113_2","076_13_2","1CO","13","2","2","In ina da baiwar annabci, ina kuma iya fahimtar dukan asirai da dukan ilimi, in kuma ina da bangaskiyar da zan iya kawar da manyan duwatsu, amma ba ni da ƙauna, ni ba kome ba ne. ");
INSERT INTO hausa_vpl VALUES ("C113_3","076_13_3","1CO","13","3","3","In na ba wa matalauta dukan abin da nake da shi, na kuma miƙa jikina a ƙone, amma ba ni da ƙauna, ban yi riban kome ba. ");
INSERT INTO hausa_vpl VALUES ("C113_4","076_13_4","1CO","13","4","4","Ƙauna tana da haƙuri, ƙauna tana da kirki. Ba ta kishi, ba ta burga, ba ta da girman kai. ");
INSERT INTO hausa_vpl VALUES ("C113_5","076_13_5","1CO","13","5","5","Ba ta rashin ladabi, ba ta sonkai, ba ta da saurin fushi, ba ta riƙe mutum a zuciya. ");
INSERT INTO hausa_vpl VALUES ("C113_6","076_13_6","1CO","13","6","6","Ƙauna ba ta jin daɗin mugunta, sai dai ta ji daɗin gaskiya. ");
INSERT INTO hausa_vpl VALUES ("C113_7","076_13_7","1CO","13","7","7","Tana kāriya kullum, tana amincewa kullum, tana bege kullum, tana jimrewa kullum. ");
INSERT INTO hausa_vpl VALUES ("C113_8","076_13_8","1CO","13","8","8","Ƙauna ba ta ƙarewa. Amma in akwai annabci zai shuɗe, harsuna su ɓace, ilimi kuma zai ƙare. ");
INSERT INTO hausa_vpl VALUES ("C113_9","076_13_9","1CO","13","9","9","Gama saninmu ba cikakke ba ne, annabcinmu kuma ba cikakke ba ne. ");
INSERT INTO hausa_vpl VALUES ("C113_10","076_13_10","1CO","13","10","10","Sai dai sa’ad da cikakken ya zo, sai wanda ba cikakke yă shuɗe. ");
INSERT INTO hausa_vpl VALUES ("C113_11","076_13_11","1CO","13","11","11","Sa’ad da nake yaro, na yi magana kamar yaro, na yi tunani kamar yaro, na yanke shawara kamar yaro. Da na isa mutum kuwa, sai na bar halin yarantakata. ");
INSERT INTO hausa_vpl VALUES ("C113_12","076_13_12","1CO","13","12","12","Yanzu kam muna ganin abubuwa kamar a madubi sai dai ba sosai ba, amma a ranan nan za mu gani fuska da fuska. Yanzu kam sanina ba cikakke ba ne, amma a ranan nan zan kasance da cikakken sani, kamar dai yadda Allah ya san ni a yanzu. ");
INSERT INTO hausa_vpl VALUES ("C113_13","076_13_13","1CO","13","13","13","Yanzu kam abubuwan nan uku sun tabbata, bangaskiya, bege, da kuma ƙauna. Sai dai mafi girma a cikinsu ita ce ƙauna. ");
INSERT INTO hausa_vpl VALUES ("C114_1","076_14_1","1CO","14","1","1","Ku bi halin ƙauna kuna kuma marmarin neman baye-bayen ruhaniya, musamman baiwar annabci. ");
INSERT INTO hausa_vpl VALUES ("C114_2","076_14_2","1CO","14","2","2","Gama duk wanda yake magana da wani harshe ba da mutane yake magana ba, sai dai da Allah. Tabbatacce, ba wanda yake fahimtarsa; yana faɗin asirai ta wurin ruhu ne. ");
INSERT INTO hausa_vpl VALUES ("C114_3","076_14_3","1CO","14","3","3","Amma duk wanda yake annabci, yana magana ne da mutane domin yă gina su, yă ƙarfafa su, yă kuma yi musu ta’aziyya. ");
INSERT INTO hausa_vpl VALUES ("C114_4","076_14_4","1CO","14","4","4","Wanda yake magana da wani harshe kuwa, kansa yake gina, amma mai annabci, ikkilisiya ce yake gina. ");
INSERT INTO hausa_vpl VALUES ("C114_5","076_14_5","1CO","14","5","5","Zan so kowannenku yă yi magana da harsuna, sai dai zan fi so ku yi annabci. Wanda yake annabci ya fi wanda yake magana da harsuna, sai dai in ya fassara don ikkilisiya ta ginu. ");
INSERT INTO hausa_vpl VALUES ("C114_6","076_14_6","1CO","14","6","6","To, ’yan’uwa, a ce na zo wurinku ina kuma yin magana da waɗansu harsuna, amfanin me zan yi muku in ban zo muku da wani bayani ko sani ko annabci, ko kuma kalmar koyarwa ba? ");
INSERT INTO hausa_vpl VALUES ("C114_7","076_14_7","1CO","14","7","7","Abubuwan nan marasa rai ma da sukan yi ƙara, kamar su algaita ko molo, in muryarsu ba tă fita sosai ba, yaya wani zai san abin da ake busawa ko kaɗawa? ");
INSERT INTO hausa_vpl VALUES ("C114_8","076_14_8","1CO","14","8","8","Haka ma in ba a busa ƙaho sosai ba, wa zai yi shirin yaƙi? ");
INSERT INTO hausa_vpl VALUES ("C114_9","076_14_9","1CO","14","9","9","Haka yake sa’ad da kuka yi magana da waɗansu harsunan da ba a fahimta. In babu wanda zai san abin da kuke faɗi, za ka dai yi wa iska magana ne kawai. ");
INSERT INTO hausa_vpl VALUES ("C114_10","076_14_10","1CO","14","10","10","Ba shakka akwai harsuna iri-iri a duniya, duk da haka kowane a cikinsu yana da ma’ana. ");
INSERT INTO hausa_vpl VALUES ("C114_11","076_14_11","1CO","14","11","11","To, in ban gane ma’anar abin da wani yake faɗi ba, ni baƙo ne ga mai maganar, shi kuma baƙo ne a gare ni. ");
INSERT INTO hausa_vpl VALUES ("C114_12","076_14_12","1CO","14","12","12","Haka yake a gare ku. Da yake kuna marmarin samun baye-bayen ruhaniya, sai ku ba da ƙarfinku ga yin amfani da waɗanda za su gina ikkilisiya. ");
INSERT INTO hausa_vpl VALUES ("C114_13","076_14_13","1CO","14","13","13","Saboda haka, duk wanda yake magana da harshe, sai yă yi addu’a a yi masa baiwar fassara. ");
INSERT INTO hausa_vpl VALUES ("C114_14","076_14_14","1CO","14","14","14","Gama in na yi addu’a da wani harshe, ruhuna ne yake addu’a, amma tunanina bai amfana kome ba. ");
INSERT INTO hausa_vpl VALUES ("C114_15","076_14_15","1CO","14","15","15","To, me zan yi? Akwai lokutan da zan yi addu’a da ruhuna; akwai kuma lokutan da zan yi addu’a da hankalina. Wani lokaci ya kamata in yi waƙa da ruhuna, a wani lokacin kuma in yi waƙa da hankalina. ");
INSERT INTO hausa_vpl VALUES ("C114_16","076_14_16","1CO","14","16","16","A cewa waɗansu baƙi suna cikin sujadarku, sa’ad da kuke yabon Allah da ruhunku, yaya waɗanda suke tare ku za su fahimta, har su ce, “Amin,” da yake ba su san abin da kuke faɗi ba? ");
INSERT INTO hausa_vpl VALUES ("C114_17","076_14_17","1CO","14","17","17","Ko da yake kuna ba da godiya da kyau, amma wancan mutumin da yake tare da ku bai ginu ba. ");
INSERT INTO hausa_vpl VALUES ("C114_18","076_14_18","1CO","14","18","18","Na gode wa Allah, domin ina magana da harsuna fiye da ku duka. ");
INSERT INTO hausa_vpl VALUES ("C114_19","076_14_19","1CO","14","19","19","Amma a cikin ikkilisiya zan gwammace in yi magana da kalmomi biyar da za a fahimta don in koyar da waɗansu da a ce in yi magana da kalmomi guda dubu goma a wani harshe. ");
INSERT INTO hausa_vpl VALUES ("C114_20","076_14_20","1CO","14","20","20","’Yan’uwa, ku daina tunani kamar yara. Wajen mugunta ku zama jarirai, sai dai wajen tunaninku, ku zama manya. ");
INSERT INTO hausa_vpl VALUES ("C114_21","076_14_21","1CO","14","21","21","A cikin Doka yana a rubuce cewa, “Ta wurin mutane masu baƙin harsuna da kuma ta leɓunan baƙi zan yi magana da waɗannan mutane, amma duk da haka, ba za su saurare ni ba,” in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("C114_22","076_14_22","1CO","14","22","22","Harsuna fa alama ce ba ga masu bi ba, sai dai ga marasa bi. Annabci kuwa ga masu bi ne ba ga marasa bi ba. ");
INSERT INTO hausa_vpl VALUES ("C114_23","076_14_23","1CO","14","23","23","Saboda haka, in dukan ikkilisiya ta taru, kowa kuma yana magana da waɗansu harsuna, sai waɗansu jahilai ko waɗansu marasa bi suka shigo, ashe, ba za su ce kuna hauka ba? ");
INSERT INTO hausa_vpl VALUES ("C114_24","076_14_24","1CO","14","24","24","Amma in wani marar bi, ko jahili ya shigo sa’ad da kowa yana annabci, sai maganar kowa ta ratsa shi, za su shawo kansa yă gane cewa shi mai zunubi ne saboda abin da kowa yake faɗi, ");
INSERT INTO hausa_vpl VALUES ("C114_25","076_14_25","1CO","14","25","25","asirin zuciyarsa kuma su bayyana a fili. Don haka, zai fāɗi a ƙasa yă yi wa Allah sujada yana cewa, “Lalle, Allah yana cikinku!” ");
INSERT INTO hausa_vpl VALUES ("C114_26","076_14_26","1CO","14","26","26","Me za mu ce ke nan ’yan’uwa? Sa’ad da kuka taru, wani yakan yi waƙa, wani koyarwa, wani wahayi, wani yin magana da wani harshe, wani kuma fassara. Dole ne a yi duka don gina ikkilisiya. ");
INSERT INTO hausa_vpl VALUES ("C114_27","076_14_27","1CO","14","27","27","In kuwa waɗansu za su yi magana a wani harshe, to, kada su fi mutum biyu ko uku, kuma a yi bi da bi, wani kuma yă fassara. ");
INSERT INTO hausa_vpl VALUES ("C114_28","076_14_28","1CO","14","28","28","In babu mai fassara, sai mai magana yă yi shiru a cikin ikkilisiya, yă yi wa kansa magana da kuma Allah. ");
INSERT INTO hausa_vpl VALUES ("C114_29","076_14_29","1CO","14","29","29","Annabawa biyu ko uku za su iya yin magana, sauran kuma sai su auna a hankali abin da aka faɗa. ");
INSERT INTO hausa_vpl VALUES ("C114_30","076_14_30","1CO","14","30","30","In kuma wahayi ya zo wa wani da yake zaune, sai mai magana na farko yă yi shiru. ");
INSERT INTO hausa_vpl VALUES ("C114_31","076_14_31","1CO","14","31","31","Dukanku kuna iya yin annabci bi da bi, domin kowa yă sami koyarwa da ƙarfafawa. ");
INSERT INTO hausa_vpl VALUES ("C114_32","076_14_32","1CO","14","32","32","Ruhohin annabawa kuwa suna ƙarƙashin sarrafawar annabawa. ");
INSERT INTO hausa_vpl VALUES ("C114_33","076_14_33","1CO","14","33","33","Gama Allah, ba Allah mai sa rikicewa ba ne, sai dai mai salama. Kamar yadda yake a dukan ikkilisiyoyi na tsarkaka. ");
INSERT INTO hausa_vpl VALUES ("C114_34","076_14_34","1CO","14","34","34","Ya kamata mata su zauna shiru a cikin ikkilisiyoyi. Ba su da izinin yin magana, sai dai su yi biyayya yadda Doka ta faɗi. ");
INSERT INTO hausa_vpl VALUES ("C114_35","076_14_35","1CO","14","35","35","In suna so su yi tambaya game da wani abu, ya kamata su tambayi mazansu a gida, domin abin kunya ne mace tă yi magana a cikin ikkilisiya. ");
INSERT INTO hausa_vpl VALUES ("C114_36","076_14_36","1CO","14","36","36","Shin, a kanku ne maganar Allah ta fara? Ko kuma a gare ku ne kaɗai ta iso? ");
INSERT INTO hausa_vpl VALUES ("C114_37","076_14_37","1CO","14","37","37","In wani yana tsammani shi annabi ne, ko yana da baiwar ruhaniya, bari yă gane cewa abin da nake rubuta muku umarnin Ubangiji ne. ");
INSERT INTO hausa_vpl VALUES ("C114_38","076_14_38","1CO","14","38","38","In ya ƙi kula da wannan, shi ma sai a ƙi kula da shi. ");
INSERT INTO hausa_vpl VALUES ("C114_39","076_14_39","1CO","14","39","39","Saboda haka ’yan’uwana, ku yi marmarin yin annabci, kada kuma ku hana magana da harsuna. ");
INSERT INTO hausa_vpl VALUES ("C114_40","076_14_40","1CO","14","40","40","Sai dai a yi kome daidai da kuma cikin tsari. ");
INSERT INTO hausa_vpl VALUES ("C115_1","076_15_1","1CO","15","1","1","To, ’yan’uwa, ina so in tuna muku da bisharar da na yi muku wa’azinta, wadda kuka karɓa, wadda kuma kuka yanke shawara ku tsaya a kai. ");
INSERT INTO hausa_vpl VALUES ("C115_2","076_15_2","1CO","15","2","2","Ta wurin wannan bisharar ce kuka sami ceto, muddin kuna riƙe da wa’azin da na yi muku kam-kam. In ba haka ba, kun gaskata a banza ke nan. ");
INSERT INTO hausa_vpl VALUES ("C115_3","076_15_3","1CO","15","3","3","Gama abu farko mafi muhimmancin da na karɓo shi ne na ba ku cewa Kiristi ya mutu domin zunubanmu bisa ga Nassi, ");
INSERT INTO hausa_vpl VALUES ("C115_4","076_15_4","1CO","15","4","4","cewa an binne shi an kuma tashe shi a rana ta uku bisa ga Nassi, ");
INSERT INTO hausa_vpl VALUES ("C115_5","076_15_5","1CO","15","5","5","cewa ya bayyana ga Bitrus, sa’an nan ga Sha Biyun. ");
INSERT INTO hausa_vpl VALUES ("C115_6","076_15_6","1CO","15","6","6","Bayan haka, ya bayyana ga fiye da ɗari biyar daga cikin ’yan’uwa a lokaci guda. Yawancinsu kuwa suna nan da rai, ko da yake waɗansu sun riga sun yi barci. ");
INSERT INTO hausa_vpl VALUES ("C115_7","076_15_7","1CO","15","7","7","Sa’an nan ya bayyana ga Yaƙub, sa’an nan ga dukan manzannin, ");
INSERT INTO hausa_vpl VALUES ("C115_8","076_15_8","1CO","15","8","8","a ƙarshe duka, ya bayyana a gare ni, kamar wanda an haifa a lokacin da bai kamata ba. ");
INSERT INTO hausa_vpl VALUES ("C115_9","076_15_9","1CO","15","9","9","Gama ni ne mafi ƙanƙanta a cikin manzanni, ban kuma isa a kira ni manzo ba, domin na tsananta wa ikkilisiyar Allah. ");
INSERT INTO hausa_vpl VALUES ("C115_10","076_15_10","1CO","15","10","10","Amma bisa ga alherin Allah, na zama abin da nake, alherinsa zuwa gare ni kuwa bai zama a banza ba. A’a, na yi aiki fiye da dukansu, duk da haka, ba ni ba ne, sai dai alherin Allah da yake tare da ni ne. ");
INSERT INTO hausa_vpl VALUES ("C115_11","076_15_11","1CO","15","11","11","To, ko ni ne, ko su ne, wannan shi ne abin da muke wa’azi, shi ne kuma abin da kuka gaskata. ");
INSERT INTO hausa_vpl VALUES ("C115_12","076_15_12","1CO","15","12","12","Amma in ana wa’azi cewa Kiristi ya tashi daga matattu, yaya waɗansu a cikinku suke cewa babu tashin matattu? ");
INSERT INTO hausa_vpl VALUES ("C115_13","076_15_13","1CO","15","13","13","In babu tashin matattu, to, ba a tā da Kiristi ma ba ke nan. ");
INSERT INTO hausa_vpl VALUES ("C115_14","076_15_14","1CO","15","14","14","In ba a tashe Kiristi ba kuwa, ai, wa’azinmu, da bangaskiyarku banza ne. ");
INSERT INTO hausa_vpl VALUES ("C115_15","076_15_15","1CO","15","15","15","Sai ma ya zama mun zama masu ba da shaidar ƙarya game da Allah ke nan, domin mun shaida game da Allah cewa ya tashe Kiristi daga matattu. Bai tashe Kiristi ba ke nan, in lalle ba a tā da matattu. ");
INSERT INTO hausa_vpl VALUES ("C115_16","076_15_16","1CO","15","16","16","Gama in ba a tā da matattu ba, to, Kiristi ma ba a tashe shi ba ke nan. ");
INSERT INTO hausa_vpl VALUES ("C115_17","076_15_17","1CO","15","17","17","In kuwa ba a tashe Kiristi ba, bangaskiyarku a banza take, ya zama har yanzu kuna cikin zunubanku ke nan. ");
INSERT INTO hausa_vpl VALUES ("C115_18","076_15_18","1CO","15","18","18","Ashe, waɗanda suka yi barci a cikin Kiristi ma sun hallaka ke nan. ");
INSERT INTO hausa_vpl VALUES ("C115_19","076_15_19","1CO","15","19","19","In a wannan rayuwar ce kaɗai muke da bege cikin Kiristi, mun zama abin tausayi fiye da dukan mutane. ");
INSERT INTO hausa_vpl VALUES ("C115_20","076_15_20","1CO","15","20","20","Amma tabbatacce, an tā da Kiristi daga matattu, nunan fari kuwa cikin waɗanda suka yi barci. ");
INSERT INTO hausa_vpl VALUES ("C115_21","076_15_21","1CO","15","21","21","Da yake mutuwa ta zo ta wurin mutum, haka tashin matattu ma ya zo ta wurin mutum. ");
INSERT INTO hausa_vpl VALUES ("C115_22","076_15_22","1CO","15","22","22","Kamar yadda duka suka mutu cikin Adamu, haka duka za su rayu cikin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("C115_23","076_15_23","1CO","15","23","23","Sai dai kowa da lokacinsa. Kiristi ne nunan fari; sa’an nan sa’ad da ya dawo; za a tā da waɗanda suke nasa. ");
INSERT INTO hausa_vpl VALUES ("C115_24","076_15_24","1CO","15","24","24","Sa’an nan sai ƙarshen ta zo, sa’ad da zai miƙa wa Allah Uba mulki, bayan ya hallaka dukan sarauta, mulki da iko. ");
INSERT INTO hausa_vpl VALUES ("C115_25","076_15_25","1CO","15","25","25","Gama dole yă yi mulki har sai ya sa dukan abokan gābansa a ƙarƙashin ƙafafunsa. ");
INSERT INTO hausa_vpl VALUES ("C115_26","076_15_26","1CO","15","26","26","Abokin gāba na ƙarshen da za a hallaka kuwa, shi ne mutuwa. ");
INSERT INTO hausa_vpl VALUES ("C115_27","076_15_27","1CO","15","27","27","Gama ya “sa kome a ƙarƙashin ƙafafunsa.” To, da aka ce an sa “kome” a ƙarƙashinsa, a fili yake cewa ba a haɗa da Allah a ciki ba, shi wannan da ya sa kome a ƙarƙashin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("C115_28","076_15_28","1CO","15","28","28","Sa’ad da ya yi haka, sa’an nan Ɗan kansa yă koma a ƙarƙashin shi wanda ya sa kome a ƙarƙashinsa, domin Allah yă zama kome da kome. ");
INSERT INTO hausa_vpl VALUES ("C115_29","076_15_29","1CO","15","29","29","To, in babu tashin matattu, mene ne waɗanda ake musu baftisma saboda matattu za su yi? In ba a tā da matattu sam, me ya sa ake yin wa mutane baftisma saboda su? ");
INSERT INTO hausa_vpl VALUES ("C115_30","076_15_30","1CO","15","30","30","Mu ma don me muke sa kanmu cikin hatsari a kowace sa’a? ");
INSERT INTO hausa_vpl VALUES ("C115_31","076_15_31","1CO","15","31","31","Ina fuskantar mutuwa kowace rana. I, kamar yadda yake tabbatacce cewa ina taƙama da ku cikin Kiristi Yesu Ubangijinmu. ");
INSERT INTO hausa_vpl VALUES ("C115_32","076_15_32","1CO","15","32","32","In na yi kokawa da mugayen namomin jeji a Afisa bisa ga ra’ayin mutane ne kawai, mece ce ribata, in har ba a tā da matattu? Ai, “Sai mu ci mu sha, da yake gobe za mu mutu.” ");
INSERT INTO hausa_vpl VALUES ("C115_33","076_15_33","1CO","15","33","33","Kada fa a ruɗe ku, “Ajiyar mugayen abokai yana ɓata hali mai kyau.” ");
INSERT INTO hausa_vpl VALUES ("C115_34","076_15_34","1CO","15","34","34","Ku koma cikin hankalinku yadda ya kamata, ku kuma daina yin zunubi, gama akwai waɗansu da ba su san Allah ba, na faɗi wannan ne don ku kunyata. ");
INSERT INTO hausa_vpl VALUES ("C115_35","076_15_35","1CO","15","35","35","Amma wani yana iya tambaya yă ce, “Ta yaya ake tā da matattun? Da wane irin jiki za su tashi?” ");
INSERT INTO hausa_vpl VALUES ("C115_36","076_15_36","1CO","15","36","36","Kai, marar azanci! Abin da kuka shuka ba zai tsira ba sai ya mutu. ");
INSERT INTO hausa_vpl VALUES ("C115_37","076_15_37","1CO","15","37","37","Sa’ad da kuke shuki, ba tsiron da zai yi girma ba ne kuka shuka, ƙwayar ce kawai, ko ta alkama ko kuma na wani irin dabam. ");
INSERT INTO hausa_vpl VALUES ("C115_38","076_15_38","1CO","15","38","38","Amma Allah yakan ba ƙwayar jiki yadda ya yi niyya, kuma ga kowane irin ƙwaya yakan ba ta irin jikinta. ");
INSERT INTO hausa_vpl VALUES ("C115_39","076_15_39","1CO","15","39","39","Ba dukan nama ne iri ɗaya ba. Mutane da irin nasu, dabbobi da irin nasu, tsuntsaye da irin nasu, kifaye kuma da irin nasu. ");
INSERT INTO hausa_vpl VALUES ("C115_40","076_15_40","1CO","15","40","40","Akwai jikuna iri na samaniya, akwai kuma jikuna iri na duniya; sai dai darajar jikunan samaniya dabam take, darajar jikunan duniya kuma dabam take. ");
INSERT INTO hausa_vpl VALUES ("C115_41","076_15_41","1CO","15","41","41","Rana tana da wata irin daraja, wata yana da wata darajar dabam, taurari kuma suna da tasu dabam. Wani tauraro kuwa yakan bambanta da wani a wajen daraja. ");
INSERT INTO hausa_vpl VALUES ("C115_42","076_15_42","1CO","15","42","42","Haka ne tashin matattu zai kasance. Abin da aka shuka yakan ruɓe, abin da aka tā da shi kuma ba ya ruɓewa; ");
INSERT INTO hausa_vpl VALUES ("C115_43","076_15_43","1CO","15","43","43","akan shuka shi cikin ƙasƙanci, a kuma tā da shi cikin ɗaukaka, akan shuka shi da rashin ƙarfi, a kuma tā da shi da ƙarfi; ");
INSERT INTO hausa_vpl VALUES ("C115_44","076_15_44","1CO","15","44","44","akan shuka shi da jiki na mutuntaka, a kuma tā da shi da jikin ruhaniya. In akwai jiki na mutuntaka, to, lalle akwai jikin ruhaniya ma. ");
INSERT INTO hausa_vpl VALUES ("C115_45","076_15_45","1CO","15","45","45","Haka yake a rubuce cewa, “Adamu, mutumin farko ya zama mai rai”; Adamu na ƙarshe kuwa ruhu ne mai ba da rai. ");
INSERT INTO hausa_vpl VALUES ("C115_46","076_15_46","1CO","15","46","46","Ba jikin ruhaniya ne ya zo da farko ba, na mutuntakan ne, daga baya kuma sai na ruhaniya. ");
INSERT INTO hausa_vpl VALUES ("C115_47","076_15_47","1CO","15","47","47","Mutumin farko daga turɓaya ce ya fito, mutum na biyu kuwa daga sama ne ya fito. ");
INSERT INTO hausa_vpl VALUES ("C115_48","076_15_48","1CO","15","48","48","Kamar yadda mutumin turɓaya yake, haka ma waɗanda suke na turɓaya. Kuma kamar yadda mutumin sama yake, haka ma waɗanda suke na sama. ");
INSERT INTO hausa_vpl VALUES ("C115_49","076_15_49","1CO","15","49","49","Kamar dai yadda muka ɗauki siffar mutumin turɓaya, haka kuma za mu ɗauki siffar mutumin sama. ");
INSERT INTO hausa_vpl VALUES ("C115_50","076_15_50","1CO","15","50","50","Ina sanar da ku, ’yan’uwa, cewa nama da jini ba za su gāji mulkin Allah ba, haka ma ruɓa ba zai gāji rashin ruɓa ba. ");
INSERT INTO hausa_vpl VALUES ("C115_51","076_15_51","1CO","15","51","51","Ku saurara, in gaya muku wani asiri. Ba dukanmu ne za mu yi barci ba, sai dai duk za a sauya kamanninmu ");
INSERT INTO hausa_vpl VALUES ("C115_52","076_15_52","1CO","15","52","52","farat ɗaya, cikin ƙyaftawar ido, da busan ƙaho na ƙarshe. Gama za a busa ƙaho, za a tā da matattu da jiki irin da ba ya ruɓewa, za a kuma sauya kamanninmu. ");
INSERT INTO hausa_vpl VALUES ("C115_53","076_15_53","1CO","15","53","53","Gama dole mai ruɓa yă maye wa mai ruɓan nan, marar mutuwa kuma yă maye wa mai mutuwan nan. ");
INSERT INTO hausa_vpl VALUES ("C115_54","076_15_54","1CO","15","54","54","Sa’ad da mai ruɓan nan ya maye marar ruɓan nan, mai mutuwa kuma ya maye marar mutuwan nan, sa’an nan ne karin maganar da yake a rubuce zai zama gaskiya cewa, “An haɗiye mutuwa cikin nasara.” ");
INSERT INTO hausa_vpl VALUES ("C115_55","076_15_55","1CO","15","55","55","“Ya ke mutuwa, ina nasararki? Ya ke mutuwa, ina dafinki?” ");
INSERT INTO hausa_vpl VALUES ("C115_56","076_15_56","1CO","15","56","56","Zunubi ne yake ba wa mutuwa dafi, Doka kuma take ba wa zunubi iko. ");
INSERT INTO hausa_vpl VALUES ("C115_57","076_15_57","1CO","15","57","57","Amma godiya ga Allah! Shi ne ya ba mu nasara ta wurin Ubangijinmu Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("C115_58","076_15_58","1CO","15","58","58","Saboda haka, ƙaunatattu ’yan’uwana, ku tsaya da daram. Kada wani abu yă jijjiga ku. Ku ba da kanku kullum ga aikin Ubangiji, domin kun san cewa famar da kuke yi saboda Ubangiji ba a banza take ba. ");
INSERT INTO hausa_vpl VALUES ("C116_1","076_16_1","1CO","16","1","1","To, game da tara kuɗi domin taimakon mutanen Allah, ku yi abin da na gaya wa ikkilisiyoyin Galatiyawa. ");
INSERT INTO hausa_vpl VALUES ("C116_2","076_16_2","1CO","16","2","2","A ranar farko ta kowace mako, ya kamata kowannenku yă keɓe ’yan kuɗi bisa ga abin da yake samu, yă ajiye, ba sai na zo kafin a tara taimakon ba. ");
INSERT INTO hausa_vpl VALUES ("C116_3","076_16_3","1CO","16","3","3","In kuwa na iso sai in ba da wasiƙun gabatarwa ga mutanen da kuka amince da su, in kuma aike su da taimakonku zuwa Urushalima. ");
INSERT INTO hausa_vpl VALUES ("C116_4","076_16_4","1CO","16","4","4","In kuma ya dace in tafi, to, sai su tafi tare da ni. ");
INSERT INTO hausa_vpl VALUES ("C116_5","076_16_5","1CO","16","5","5","Bayan na zazzaga Makidoniya, zan zo wurinku, domin zan ratsa ta Makidoniya. ");
INSERT INTO hausa_vpl VALUES ("C116_6","076_16_6","1CO","16","6","6","Wataƙila zan ɗan jima a wajenku, ko ma in ci damina a can, domin ku yi mini rakiya a tafiyata, duk inda za ni. ");
INSERT INTO hausa_vpl VALUES ("C116_7","076_16_7","1CO","16","7","7","Ba na so in gan ku yanzu in wuce kawai, ina fata zan yi ’yan kwanaki tare da ku, in Ubangiji ya yarda. ");
INSERT INTO hausa_vpl VALUES ("C116_8","076_16_8","1CO","16","8","8","Sai dai zan kasance a Afisa har lokacin Fentekos, ");
INSERT INTO hausa_vpl VALUES ("C116_9","076_16_9","1CO","16","9","9","domin an buɗe mini wata hanya mai fāɗi don aiki mai amfani, ko da yake akwai mutane da yawa masu gāba da ni. ");
INSERT INTO hausa_vpl VALUES ("C116_10","076_16_10","1CO","16","10","10","In Timoti ya zo, ku tabbata ya sami sakewa a cikinku, domin aikin Ubangiji yake yi kamar yadda nake yi. ");
INSERT INTO hausa_vpl VALUES ("C116_11","076_16_11","1CO","16","11","11","Kada fa wani yă ƙi karɓansa. Ku sallame shi lafiya, domin yă koma wurina. Ina duban hanyarsa tare da ’yan’uwa. ");
INSERT INTO hausa_vpl VALUES ("C116_12","076_16_12","1CO","16","12","12","Batun ɗan’uwanmu Afollos kuwa, na roƙe shi sosai yă zo wurinku tare da ’yan’uwa. Bai so zuwa yanzu ba, amma zai zo in ya sami zarafi. ");
INSERT INTO hausa_vpl VALUES ("C116_13","076_16_13","1CO","16","13","13","Ku zauna a faɗake; ku dāge cikin bangaskiya; ku zauna da ƙarfafawa; ku yi ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("C116_14","076_16_14","1CO","16","14","14","Ku yi kome da ƙauna. ");
INSERT INTO hausa_vpl VALUES ("C116_15","076_16_15","1CO","16","15","15","Kun san cewa iyalin gidan Istifanas ne suka fara tuba a Akayya. Sun kuma ba da kansu ga yi wa tsarkaka hidima. Ina roƙonku ’yan’uwa, ");
INSERT INTO hausa_vpl VALUES ("C116_16","076_16_16","1CO","16","16","16","ku ba da kanku ga irin waɗannan, ga kuma kowa da ya haɗa hannu a aikin, yana kuma faman a cikinsa. ");
INSERT INTO hausa_vpl VALUES ("C116_17","076_16_17","1CO","16","17","17","Na yi farin ciki da isowar Istifanas, Fortunatus da Akaikus, domin sun biya bukatar da ba ku iya biya ba. ");
INSERT INTO hausa_vpl VALUES ("C116_18","076_16_18","1CO","16","18","18","Gama sun wartsake ruhuna da kuma naku. Ya kamata ku girmama irin waɗannan mutane. ");
INSERT INTO hausa_vpl VALUES ("C116_19","076_16_19","1CO","16","19","19","Ikkilisiyoyin da suke a lardin Asiya suna gaisuwa. Akwila da Firiskila suna gaishe ku sosai cikin Ubangiji, haka ma ikkilisiyar da takan taru a gidansu. ");
INSERT INTO hausa_vpl VALUES ("C116_20","076_16_20","1CO","16","20","20","Dukan ’yan’uwa a nan suna gaisuwa. Ku gai da juna da sumba mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("C116_21","076_16_21","1CO","16","21","21","Ni, Bulus nake rubuta wannan gaisuwa da hannuna. ");
INSERT INTO hausa_vpl VALUES ("C116_22","076_16_22","1CO","16","22","22","Duk wanda ba ya ƙaunar Ubangiji, la’ana ta zauna a kansa. Zo, ya Ubangiji! ");
INSERT INTO hausa_vpl VALUES ("C116_23","076_16_23","1CO","16","23","23","Alherin Ubangiji Yesu yă kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("C116_24","076_16_24","1CO","16","24","24","Ina gaishe ku duka, gaisuwar ƙaunata cikin Kiristi Yesu. Amin.");
INSERT INTO hausa_vpl VALUES ("C21_1","077_1_1","2CO","1","1","1","Bulus, manzon Kiristi Yesu ta wurin nufin Allah, da kuma daga Timoti ɗan’uwanmu, Zuwa ga ikkilisiyar Allah da take a Korint, tare da dukan tsarkaka a ko’ina a Akayya. ");
INSERT INTO hausa_vpl VALUES ("C21_2","077_1_2","2CO","1","2","2","Alheri da salama daga Allah Ubanmu da kuma Ubangiji Yesu Kiristi, su kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("C21_3","077_1_3","2CO","1","3","3","Yabo ya tabbata ga Allah, da Uban Ubangijinmu Yesu Kiristi, Uba mai tausayi, da kuma Allah na dukan ta’aziyya, ");
INSERT INTO hausa_vpl VALUES ("C21_4","077_1_4","2CO","1","4","4","wanda yakan yi mana ta’aziyya a cikin dukan wahalolinmu, domin mu kuma mu iya ta’azantar da waɗanda suke cikin kowace irin wahala, da ta’aziyyar da mu kanmu muka samu daga Allah. ");
INSERT INTO hausa_vpl VALUES ("C21_5","077_1_5","2CO","1","5","5","Gama kamar yadda wahalar Kiristi ta cika har tana zuba a cikin rayuwarmu, haka nan kuma ta wurin Kiristi ta’aziyyarmu ta cika har tana zuba. ");
INSERT INTO hausa_vpl VALUES ("C21_6","077_1_6","2CO","1","6","6","In muna shan wahala, ai, muna shanta domin ta’aziyyarku, da cetonku ne, in mun sami ta’aziyya, ai, mun same ta domin ta’aziyyarku ce, wadda take sa ku jure wa irin wahalan nan, da muke sha. ");
INSERT INTO hausa_vpl VALUES ("C21_7","077_1_7","2CO","1","7","7","Begen da muke da shi dominku kuwa, tabbatacce ne, domin mun san cewa kamar yadda kuke tarayya da mu a cikin wahalolinmu, haka kuma kuke tarayya da mu a cikin ta’aziyyarmu. ");
INSERT INTO hausa_vpl VALUES ("C21_8","077_1_8","2CO","1","8","8","’Yan’uwa, ba ma so ku zama da rashin sani, a kan wahalolin da muka sha a lardin Asiya. Mun sha wahaloli sosai, har abin ya fi ƙarfinmu, ya sa muka fid da tsammanin rayuwa. ");
INSERT INTO hausa_vpl VALUES ("C21_9","077_1_9","2CO","1","9","9","Ba shakka, a zuciyarmu mun ji kamar hukuncin kisa ne aka yi mana. Wannan kuwa ya faru ne domin kada mu dogara da kanmu, sai dai ga Allah, wanda yake tā da matattu. ");
INSERT INTO hausa_vpl VALUES ("C21_10","077_1_10","2CO","1","10","10","Shi ya cece mu daga irin wannan hatsari na mutuwa, zai kuwa cece mu. A kansa muka kafa bege cewa zai ci gaba da cetonmu, ");
INSERT INTO hausa_vpl VALUES ("C21_11","077_1_11","2CO","1","11","11","yayinda kuke taimakonmu ta wurin addu’o’inku. Mutane da yawa kuwa za su yi godiya ta dalilinmu, saboda albarkar da aka yi mana, ta amsa addu’o’i masu yawa. ");
INSERT INTO hausa_vpl VALUES ("C21_12","077_1_12","2CO","1","12","12","Wannan shi ne taƙamarmu. Lamirinmu yana ba da shaida cewa mun yi zamanmu a duniya, musamman a dangantakarmu da ku cikin tsarki, tsakani da Allah. Mun yi haka ta wurin bishewar alherin Allah, ba bisa ga hikimar duniya ba. ");
INSERT INTO hausa_vpl VALUES ("C21_13","077_1_13","2CO","1","13","13","Gama ba mu rubuta muku abin da ba za ku iya karatu ko ku kāsa fahimta ba. Ina kuma fata cewa, ");
INSERT INTO hausa_vpl VALUES ("C21_14","077_1_14","2CO","1","14","14","kamar yadda kuka ɗan fahimce mu, za ku kai ga cikakkiyar fahimta cewa za ku iya yin taƙama da mu, kamar yadda mu ma za mu yi taƙama da ku a ranar da Ubangiji Yesu zai dawo. ");
INSERT INTO hausa_vpl VALUES ("C21_15","077_1_15","2CO","1","15","15","Saboda na amince da haka, shi ya sa na so zuwa wurinku da fari, domin ku sami albarka riɓi biyu. ");
INSERT INTO hausa_vpl VALUES ("C21_16","077_1_16","2CO","1","16","16","Na yi shiri in ziyarce ku a kan hanyata zuwa Makidoniya, in kuma sāke dawo wurinku a kan hanyata daga Makidoniya, sa’an nan ku yi mini rakiya a hanyata zuwa Yahudiya. ");
INSERT INTO hausa_vpl VALUES ("C21_17","077_1_17","2CO","1","17","17","Kuna gani na yi wannan shirin ba da sanin abin da nake yi ba ne? Ko kuwa, kuna gani na yi shirin nan da halin mutuntaka ne, don in ce, “I” in koma in ce, “A’a”? ");
INSERT INTO hausa_vpl VALUES ("C21_18","077_1_18","2CO","1","18","18","Kamar dai yadda ba shakka Allah yake mai aminci, haka ma maganar da muka yi muku, ba “I” da kuma “A’a” ba ce. ");
INSERT INTO hausa_vpl VALUES ("C21_19","077_1_19","2CO","1","19","19","Gama Ɗan Allah, Yesu Kiristi, wanda ni da Sila da Timoti muka yi muku wa’azinsa, ai, ba “I” da “A’a” ba ne, amma a cikin Kiristi, “I” ne kullum. ");
INSERT INTO hausa_vpl VALUES ("C21_20","077_1_20","2CO","1","20","20","Domin dukan alkawaran Allah cikarsu a gare shi suke, ta wurinsa ne kuma muke faɗar “Amin”, domin a ɗaukaka Allah. ");
INSERT INTO hausa_vpl VALUES ("C21_21","077_1_21","2CO","1","21","21","Allah ne fa yake sa mu da ku mu tsaya daram cikin Kiristi. Shi ne ya shafe mu, ");
INSERT INTO hausa_vpl VALUES ("C21_22","077_1_22","2CO","1","22","22","ya buga mana hatiminsa a kan mu nasa ne, ya kuma sa mana Ruhunsa a cikin zukatanmu, domin yă tabbatar da abin da yake zuwa nan gaba. ");
INSERT INTO hausa_vpl VALUES ("C21_23","077_1_23","2CO","1","23","23","Labudda, Allah shi ne shaidata cewa don kada in ƙara muku wahala ne ya sa ban koma Korint ba. ");
INSERT INTO hausa_vpl VALUES ("C21_24","077_1_24","2CO","1","24","24","Ba nuna muku iko a kan bangaskiyarku muke yi ba, sai dai muna aiki tare da ku ne saboda farin cikinku, domin bisa ga bangaskiya ce kuke tsaye da ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("C22_1","077_2_1","2CO","2","1","1","Saboda haka na yanke shawara ba zan sāke kawo muku ziyara ta ɓacin rai ba. ");
INSERT INTO hausa_vpl VALUES ("C22_2","077_2_2","2CO","2","2","2","Gama in na sa ku baƙin ciki, wa ya rage yă faranta mini zuciya, in ba ku waɗanda na sa baƙin cikin ba? ");
INSERT INTO hausa_vpl VALUES ("C22_3","077_2_3","2CO","2","3","3","Na rubuta yadda na yi ne saboda sa’ad da na iso kada waɗanda ya kamata su faranta mini rai, su sa ni baƙin ciki. Na amince da ku duka a kan farin cikina naku ne ku duka. ");
INSERT INTO hausa_vpl VALUES ("C22_4","077_2_4","2CO","2","4","4","Gama na rubuta muku ne cikin baƙin ciki mai yawa da ɓacin zuciya har ma da hawaye mai yawa, ba don in sa ku baƙin ciki ba ne, a’a, sai dai domin in nuna muku zurfin ƙaunar da nake yi muku. ");
INSERT INTO hausa_vpl VALUES ("C22_5","077_2_5","2CO","2","5","5","In wani ya jawo baƙin ciki, ba ni kaɗai ya jawo wa ba, amma a wani fanni, sai in ce dukanku ne ya jawo wa, ba na faɗa haka don in matsa muku lamba ba ne. ");
INSERT INTO hausa_vpl VALUES ("C22_6","077_2_6","2CO","2","6","6","Irin wannan mutum, horon da yawancin mutane suka yi masa ya isa haka. ");
INSERT INTO hausa_vpl VALUES ("C22_7","077_2_7","2CO","2","7","7","Yanzu fa, a maimako, gara ku yafe masa, ku kuma ta’azantar da shi, don kada baƙin ciki mai yawa yă sha kansa. ");
INSERT INTO hausa_vpl VALUES ("C22_8","077_2_8","2CO","2","8","8","Saboda haka, ina roƙonku, ku sāke nuna masa ƙaunarku. ");
INSERT INTO hausa_vpl VALUES ("C22_9","077_2_9","2CO","2","9","9","Abin da ya sa na rubuta muku shi ne don in ga ko za ku jimre da gwajin nan, kuna kuma yin biyayya ta kowace hanya. ");
INSERT INTO hausa_vpl VALUES ("C22_10","077_2_10","2CO","2","10","10","In kuka gafarta wa wani, ni ma na gafarta masa. Abin da na gafarta kuwa, in har ma da abin gafartawa, saboda ku ne na gafarta masa, albarkacin Kiristi, ");
INSERT INTO hausa_vpl VALUES ("C22_11","077_2_11","2CO","2","11","11","don kada Shaiɗan yă rinjaye mu. Da yake muna sane da dabarunsa. ");
INSERT INTO hausa_vpl VALUES ("C22_12","077_2_12","2CO","2","12","12","To, sa’ad da na tafi Toruwas don in yi wa’azin bisharar Kiristi, ko da yake na tarar cewa Ubangiji ya buɗe mini ƙofa, ");
INSERT INTO hausa_vpl VALUES ("C22_13","077_2_13","2CO","2","13","13","duk da haka, ban sami salama a zuciyata ba domin ban sami ɗan’uwana Titus a can ba. Sai na yi bankwana da su na wuce zuwa Makidoniya. ");
INSERT INTO hausa_vpl VALUES ("C22_14","077_2_14","2CO","2","14","14","Amma godiya ga Allah, wanda kullum yake bi da mu da nasara cikin Kiristi, kuma ta wurinmu, yana baza ƙanshin nan na sanin Kiristi a ko’ina. ");
INSERT INTO hausa_vpl VALUES ("C22_15","077_2_15","2CO","2","15","15","Don kuwa, a wurin Allah mu ƙanshin Kiristi ne cikin waɗanda ake ceto, da kuma waɗanda suke hanyar hallaka. ");
INSERT INTO hausa_vpl VALUES ("C22_16","077_2_16","2CO","2","16","16","Ga wani, mu warin mutuwa ne, amma ga wani kuwa, mu ƙanshin rai ne. Wa ya isa yă yi irin wannan aikin? ");
INSERT INTO hausa_vpl VALUES ("C22_17","077_2_17","2CO","2","17","17","Ba ma tallar maganar Allah don riba yadda waɗansu mutane da yawa suke yi. A maimakon haka, muna magana cikin Kiristi a gaban Allah da gaskiya, kamar mutanen da aka aika daga Allah. ");
INSERT INTO hausa_vpl VALUES ("C23_1","077_3_1","2CO","3","1","1","Yabon kanmu ne kuma muka fara yi? Ko kuwa muna bukatar wasiƙun yabo ne zuwa gare ku, ko daga gare ku, kamar yadda waɗansu suke yi? ");
INSERT INTO hausa_vpl VALUES ("C23_2","077_3_2","2CO","3","2","2","Ai, ku kanku ku ne wasiƙarmu, wadda aka rubuta a zukatanku, domin kowa yă santa, yă kuma karanta ta. ");
INSERT INTO hausa_vpl VALUES ("C23_3","077_3_3","2CO","3","3","3","Kun nuna cewa ku wasiƙa ce daga Kiristi, sakamakon hidimarmu, ba wadda aka rubuta da inki ba, sai dai da Ruhun Allah mai rai. Ba kuma a kan allunan dutse ba, sai dai a kan allunan zukatan mutane. ");
INSERT INTO hausa_vpl VALUES ("C23_4","077_3_4","2CO","3","4","4","Amincewa kamar wannan shi ne namu ta wurin Kiristi a gaban Allah. ");
INSERT INTO hausa_vpl VALUES ("C23_5","077_3_5","2CO","3","5","5","Ba mu da wani abin da za mu nuna cewa da iyawarmu ne muke aikin nan. Iyawarmu daga wurin Allah ne. ");
INSERT INTO hausa_vpl VALUES ("C23_6","077_3_6","2CO","3","6","6","Shi ya sa muka gwaninta a matsayinmu na masu hidimar sabon alkawari ba ta rubutacciyar Dokar ba, amma ta Ruhu; don Dokar, kisa take yi, Ruhu kuwa yana ba da rai. ");
INSERT INTO hausa_vpl VALUES ("C23_7","077_3_7","2CO","3","7","7","To, in hidimar da ta kawo mutuwa, wadda an rubuta a kan allon dutse, ta zo da ɗaukaka har Isra’ilawa suka kāsa duban fuskar Musa saboda tsananin haskenta, ko da yake mai shuɗewa ce, ");
INSERT INTO hausa_vpl VALUES ("C23_8","077_3_8","2CO","3","8","8","ashe, hidimar Ruhu ba za tă fi wannan ɗaukaka ba? ");
INSERT INTO hausa_vpl VALUES ("C23_9","077_3_9","2CO","3","9","9","In hidimar da take jawo wa mutane hukunci tana da ɗaukaka haka, to, lalle, hidimar da take kawo adalci za tă fi ta ɗaukaka nesa! ");
INSERT INTO hausa_vpl VALUES ("C23_10","077_3_10","2CO","3","10","10","Gama abin da dā take da ɗaukaka, ba ta da ɗaukaka a yanzu, in aka kwatantata da mafificiyar ɗaukaka ta yanzu. ");
INSERT INTO hausa_vpl VALUES ("C23_11","077_3_11","2CO","3","11","11","In kuma aba mai shuɗewa ta zo da ɗaukaka, ashe, abin da yake dawwammame, lalle ne yă kasance da ɗaukakar da ta fi haka nesa! ");
INSERT INTO hausa_vpl VALUES ("C23_12","077_3_12","2CO","3","12","12","Da yake muna da bege irin wannan, to, muna da ƙarfin zuciya sosai ke nan. ");
INSERT INTO hausa_vpl VALUES ("C23_13","077_3_13","2CO","3","13","13","Mu ba kamar Musa ba ne, wanda ya rufe fuskarsa da lulluɓi, don kada Isra’ilawa su ga ƙarewar ɗaukakan nan mai shuɗewa. ");
INSERT INTO hausa_vpl VALUES ("C23_14","077_3_14","2CO","3","14","14","Amma aka sa hankulansu suka dushe, gama har yă zuwa yau akwai lulluɓin nan a duk sa’ad da ake karatun tsohon alkawari. Ba a kawar da shi ba, sai a cikin Kiristi ne kaɗai ake kawar da shi. ");
INSERT INTO hausa_vpl VALUES ("C23_15","077_3_15","2CO","3","15","15","Har yă zuwa yau, duk sa’ad da ake karatun littattafan Musa, lulluɓin nan yakan rufe zukatansu. ");
INSERT INTO hausa_vpl VALUES ("C23_16","077_3_16","2CO","3","16","16","Amma duk sa’ad da wani ya juyo ga Ubangiji, akan kawar da lulluɓin. ");
INSERT INTO hausa_vpl VALUES ("C23_17","077_3_17","2CO","3","17","17","Ubangiji fa, shi ne Ruhu, kuma duk inda Ruhun Ubangiji yake, a nan ’yanci yake. ");
INSERT INTO hausa_vpl VALUES ("C23_18","077_3_18","2CO","3","18","18","Mu da ba mu da lulluɓi a fuskokinmu duk muna nuna ɗaukakar Ubangiji, ana sauya mu mu ɗauki kamanninsa cikin ɗaukaka mai hauhawa. Ubangiji wanda yake ruhu kuwa shi ne mai zartar da haka. ");
INSERT INTO hausa_vpl VALUES ("C24_1","077_4_1","2CO","4","1","1","Saboda haka, da yake ta wurin jinƙan Allah ne muke da wannan hidima, ba za mu fid da zuciya ba. ");
INSERT INTO hausa_vpl VALUES ("C24_2","077_4_2","2CO","4","2","2","Ba ruwanmu da ɓoye-ɓoye na munafuncin da suke abubuwan kunya. Ba ruwanmu da ruɗu, ko yin ƙarya da kalmar Allah. Sai dai muna faɗin gaskiya a fili. Ta haka ne kowa zai yi shaidar gaskiyarmu a gaban Allah cikin zuciyarsa. ");
INSERT INTO hausa_vpl VALUES ("C24_3","077_4_3","2CO","4","3","3","Ko da bishararmu a rufe take, tana a rufe ne ga waɗanda suke hallaka. ");
INSERT INTO hausa_vpl VALUES ("C24_4","077_4_4","2CO","4","4","4","Allahn zamanin nan ya makanta hankulan marasa ba da gaskiya, yadda har ba za su iya ganin hasken bishara ta ɗaukakar Kiristi ba, wanda yake kamannin Allah. ");
INSERT INTO hausa_vpl VALUES ("C24_5","077_4_5","2CO","4","5","5","Gama ba wa’azin kanmu muke yi ba, sai dai na Yesu Kiristi, a kan shi ne Ubangiji, mu kuma bayinku saboda Yesu. ");
INSERT INTO hausa_vpl VALUES ("C24_6","077_4_6","2CO","4","6","6","Domin shi Allah wanda ya ce, “Bari haske yă haskaka daga duhu,” ya sa haskensa ya haskaka a cikin zukatanmu, don yă ba mu hasken sanin ɗaukakar Allah a fuskar Kiristi. ");
INSERT INTO hausa_vpl VALUES ("C24_7","077_4_7","2CO","4","7","7","Amma muna da wannan dukiya a cikin tulunan yumɓu, don a nuna wannan mafificin ikon nan daga Allah ne, ba daga gare mu ba. ");
INSERT INTO hausa_vpl VALUES ("C24_8","077_4_8","2CO","4","8","8","A matse muke a kowane gefe, sai dai ba a gurgunta mu ba. An rikitar da mu, amma ba mu fid da zuciya ba. ");
INSERT INTO hausa_vpl VALUES ("C24_9","077_4_9","2CO","4","9","9","An tsananta mana, amma ba a yashe mu ba, an fyaɗe mu da ƙasa, amma ba a hallaka mu ba. ");
INSERT INTO hausa_vpl VALUES ("C24_10","077_4_10","2CO","4","10","10","Kullum muna ɗauke da mutuwar Yesu a jikinmu, domin ran Yesu yă bayyana a jikinmu. ");
INSERT INTO hausa_vpl VALUES ("C24_11","077_4_11","2CO","4","11","11","Muddin muna a raye, kullum zaman mutuwa muke yi saboda Yesu, don a bayyana ran Yesu ta wurin jikin nan namu mai mutuwa. ");
INSERT INTO hausa_vpl VALUES ("C24_12","077_4_12","2CO","4","12","12","Ta haka, mutuwa tana aiki a cikinmu, ku kuwa rai a cikinku. ");
INSERT INTO hausa_vpl VALUES ("C24_13","077_4_13","2CO","4","13","13","A rubuce yake cewa, “Na gaskata; saboda haka na yi magana.” Da wannan ruhun bangaskiya ne mu ma muka gaskata, saboda haka muke magana. ");
INSERT INTO hausa_vpl VALUES ("C24_14","077_4_14","2CO","4","14","14","Domin mun san cewa shi da ya tā da Ubangiji Yesu daga matattu, zai tashe mu mu ma tare da Kiristi, yă kuma miƙa mu a gabansa tare da ku. ");
INSERT INTO hausa_vpl VALUES ("C24_15","077_4_15","2CO","4","15","15","Duk wannan fa don amfaninku ne, domin alherin nan da yake bazuwa zuwa ga mutane masu yawa, yă zama dalilin godiya mai yawa ga ɗaukakar Allah. ");
INSERT INTO hausa_vpl VALUES ("C24_16","077_4_16","2CO","4","16","16","Saboda haka, ba mu fid da zuciya ba. Ko da yake a waje, jikinmu mai mutuwa yana lalacewa, amma can ciki, ana sabunta mu kowace rana. ");
INSERT INTO hausa_vpl VALUES ("C24_17","077_4_17","2CO","4","17","17","Don wannan ’yar wahalar tamu mai saurin wucewa, ita take tanadar mana madawwamiyar ɗaukaka mai yawa, fiye da kwatanci. ");
INSERT INTO hausa_vpl VALUES ("C24_18","077_4_18","2CO","4","18","18","Domin ba abubuwan da ido yake gani ne muke dubawa ba, sai dai marasa ganuwa. Gama abubuwan da ake gani masu saurin wucewa ne, marasa ganuwa kuwa, madawwama ne. ");
INSERT INTO hausa_vpl VALUES ("C25_1","077_5_1","2CO","5","1","1","Yanzu mun san cewa in an hallaka tentin duniyan nan da muke ciki, muna da wani gini daga Allah, madawwamin gida a sama, wanda ba da hannuwan mutum ne suka gina shi ba. ");
INSERT INTO hausa_vpl VALUES ("C25_2","077_5_2","2CO","5","2","2","Kafin nan muna nishi, da marmari a yi mana sutura da gidanmu na sama, ");
INSERT INTO hausa_vpl VALUES ("C25_3","077_5_3","2CO","5","3","3","don sa’ad da aka yi mana sutura, ba za a same mu tsirara ba. ");
INSERT INTO hausa_vpl VALUES ("C25_4","077_5_4","2CO","5","4","4","Sa’ad da muke zaune a cikin jikin nan na duniya, nishi muke domin matsuwar da muke sha, ba domin muna so mu rabu da jikinmu na wannan duniya ba ne, sai dai don so muke yi a suturta mu da na Sama, domin mai rai ya shafe mai mutuwa. ");
INSERT INTO hausa_vpl VALUES ("C25_5","077_5_5","2CO","5","5","5","Allah ne ya yi mu domin wannan, ya kuma ba mu Ruhu a matsayin abin ajiya, yana kuma tabbatar da abin da zai zo nan gaba. ");
INSERT INTO hausa_vpl VALUES ("C25_6","077_5_6","2CO","5","6","6","Saboda haka, kullum muna da tabbaci mun kuma san cewa, muddin muna a duniya cikin jikin nan, ana raba mu da Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("C25_7","077_5_7","2CO","5","7","7","Rayuwa bangaskiya muke, ba ta ganin ido ba. ");
INSERT INTO hausa_vpl VALUES ("C25_8","077_5_8","2CO","5","8","8","Ina cewa muna da tabbaci, za mu fi so mu rabu da jikin nan, mu kuma kasance a sama tare da Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("C25_9","077_5_9","2CO","5","9","9","Saboda haka, niyyarmu ita ce, mu gamshe shi, ko muna a duniya cikin jikin nan, ko ba mu nan. ");
INSERT INTO hausa_vpl VALUES ("C25_10","077_5_10","2CO","5","10","10","Gama dole dukanmu mu bayyana a gaban kujerar shari’ar Kiristi, domin kowannenmu yă karɓi ladan aikin da ya yi a wannan jiki, ko mai kyau ne ko marar kyau. ");
INSERT INTO hausa_vpl VALUES ("C25_11","077_5_11","2CO","5","11","11","To, da yake mun san ko mene tsoron Ubangiji yake, muna ƙoƙari mu rinjaye mutane. Yadda muke kuwa, yana sane a sarari ga Allah, ina kuma fata yana nan a sarari a lamirinku. ");
INSERT INTO hausa_vpl VALUES ("C25_12","077_5_12","2CO","5","12","12","Ba ƙoƙari muke mu yabe kanmu a gare ku ba ne, sai dai muna ba ku damar yin taƙama da mu ne, don ku sami amsar da za ku ba wa waɗanda suke taƙama da abin da ake gani ne, a maimakon abin da yake cikin zuciya. ");
INSERT INTO hausa_vpl VALUES ("C25_13","077_5_13","2CO","5","13","13","In hankalinmu a taɓe yake, ai, saboda Allah ne, in kuwa cikin hankalinmu muke, ai, saboda ku ne. ");
INSERT INTO hausa_vpl VALUES ("C25_14","077_5_14","2CO","5","14","14","Ƙaunar Kiristi a gare mu, ita take mallakarmu, saboda haka mun tabbata, da yake wani ya mutu saboda dukan mutane, ashe kuwa, mutuwarsu ce dukansu. ");
INSERT INTO hausa_vpl VALUES ("C25_15","077_5_15","2CO","5","15","15","Ya kuwa mutu ne saboda dukan mutane, domin kada waɗanda suke rayuwa kada su yi zaman ganin dama a nan gaba, sai dai su yi zaman wannan da ya mutu saboda su, aka kuma tashe shi saboda su. ");
INSERT INTO hausa_vpl VALUES ("C25_16","077_5_16","2CO","5","16","16","Saboda haka, daga yanzu zuwa nan gaba, ba mu ƙara ɗaukan wani mutum bisa ga ganin duniya ba. Ko da yake a dā, mun ɗauki Kiristi haka, amma yanzu mun daina yin haka. ");
INSERT INTO hausa_vpl VALUES ("C25_17","077_5_17","2CO","5","17","17","Saboda haka, duk wanda yake cikin Kiristi, sabuwar halitta ce, tsohon al’amari ya shuɗe, sabon ya zo! ");
INSERT INTO hausa_vpl VALUES ("C25_18","077_5_18","2CO","5","18","18","Duk wannan kuwa daga Allah ne, wanda ya sulhunta mu da kansa ta wurin Kiristi, ya kuma ba mu hidimar sulhu, ");
INSERT INTO hausa_vpl VALUES ("C25_19","077_5_19","2CO","5","19","19","wato, Allah ya sulhunta duniya zuwa kansa ta wurin Kiristi, ba ya lissafta zunuban mutane a kansu. Ya kuma danƙa mana saƙon sulhu. ");
INSERT INTO hausa_vpl VALUES ("C25_20","077_5_20","2CO","5","20","20","Saboda haka, mu jakadu ne na Kiristi, sai ka ce Allah kansa yake magana ta wurinmu. Muna roƙonku a madadin Kiristi. Ku sulhuntu da Allah. ");
INSERT INTO hausa_vpl VALUES ("C25_21","077_5_21","2CO","5","21","21","Shi da bai san zunubi ba, Allah ya mai da shi kamar hadayar zunubi saboda mu, domin mu sami adalcin Allah ta wurinsa. ");
INSERT INTO hausa_vpl VALUES ("C26_1","077_6_1","2CO","6","1","1","A matsayinmu na abokan aikin Allah, muna roƙonku kada ku karɓi alherin Allah a banza. ");
INSERT INTO hausa_vpl VALUES ("C26_2","077_6_2","2CO","6","2","2","Gama ya ce, “A lokacin samun alherina, na ji ka, a ranar samun ceto kuma, na taimake ka.” Ina gaya muku, yanzu ne lokacin samun alherin Allah, yanzu ne ranar samun ceto. ");
INSERT INTO hausa_vpl VALUES ("C26_3","077_6_3","2CO","6","3","3","Ba ma sa abin tuntuɓe wa kowa, domin kada hidimarmu ta zama abin zargi. ");
INSERT INTO hausa_vpl VALUES ("C26_4","077_6_4","2CO","6","4","4","A maimakon haka, duk abin da muke yi, muna yin shi ne don mu nuna cewa mu masu hidimar Allah ne. Muna yin haka cikin jimrewa, da shan wahala, da shan wuya, har da shan masifu. ");
INSERT INTO hausa_vpl VALUES ("C26_5","077_6_5","2CO","6","5","5","Da shan dūka, da shan dauri, da yawan hargitsi, da yawan fama, da rashin barci, da kuma yunwa. ");
INSERT INTO hausa_vpl VALUES ("C26_6","077_6_6","2CO","6","6","6","Da cikin tsarki, da fahimta, da haƙuri, da kirki, da cikin Ruhu Mai Tsarki, da cikin ƙauna mai gaskiya, ");
INSERT INTO hausa_vpl VALUES ("C26_7","077_6_7","2CO","6","7","7","da cikin magana mai gaskiya, da kuma cikin ikon Allah. Muna riƙe da makaman adalci dama da hagu, ");
INSERT INTO hausa_vpl VALUES ("C26_8","077_6_8","2CO","6","8","8","ta wurin ɗaukaka da ƙasƙanci, da cikin ɓata suna, da kuma cikin yabo. Cikin faɗin gaskiya, an ɗauke mu masu ƙarya, ");
INSERT INTO hausa_vpl VALUES ("C26_9","077_6_9","2CO","6","9","9","mu sanannu ne, duk da haka an ɗauke mu kamar ba a san mu ba, muna mutuwa, duk da haka a raye muke, an ba mu horo, duk da haka ba a kashe mu ba, ");
INSERT INTO hausa_vpl VALUES ("C26_10","077_6_10","2CO","6","10","10","cikin baƙin ciki, duk da haka kullum cikin murna muke. Cikin matalauta, duk da haka muna azurtar da mutane da yawa. Ba mu da kome, alhali kuwa kome namu ne. ");
INSERT INTO hausa_vpl VALUES ("C26_11","077_6_11","2CO","6","11","11","Ya ku Korintiyawa, mun yi muku magana a sake, muka kuma saki zuciya da ku ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("C26_12","077_6_12","2CO","6","12","12","Ba mu ƙi nuna muku ƙaunarmu ba, sai dai ku kuka ƙi nuna mana. ");
INSERT INTO hausa_vpl VALUES ("C26_13","077_6_13","2CO","6","13","13","A wannan zance kam, ina magana da ku kamar ’ya’yana, ku ma ku saki zuciya da mu. ");
INSERT INTO hausa_vpl VALUES ("C26_14","077_6_14","2CO","6","14","14","Kada ku haɗa kai da marasa bi. Gama me ya haɗa adalci da mugunta? Ko kuwa me ya haɗa haske da duhu? ");
INSERT INTO hausa_vpl VALUES ("C26_15","077_6_15","2CO","6","15","15","Wace daidaituwa ce tsakanin Kiristi da Iblis? Me ya haɗa mai bi da marar bi? ");
INSERT INTO hausa_vpl VALUES ("C26_16","077_6_16","2CO","6","16","16","Wane alkawari ne tsakanin haikalin Allah da na gumaka? Gama mu haikalin Allah mai rai ne. Kamar yadda Allah ya ce, “Zan zauna tare da su, in yi tafiya a cikinsu, zan zama Allahnsu, su kuma za su zama mutanena.” ");
INSERT INTO hausa_vpl VALUES ("C26_17","077_6_17","2CO","6","17","17","Saboda haka, “Sai ku fito daga cikinsu, ku keɓe kanku, in ji Ubangiji. Kada ku taɓa wani abu marar tsabta, zan kuma karɓe ku.” ");
INSERT INTO hausa_vpl VALUES ("C26_18","077_6_18","2CO","6","18","18","Kuma, “Zan zama Uba a gare ku, ku kuma za ku zama ’ya’yana, maza da mata, in ji Ubangiji Maɗaukaki.” ");
INSERT INTO hausa_vpl VALUES ("C27_1","077_7_1","2CO","7","1","1","Da yake muna da waɗannan alkawura, ya ku ƙaunatattu, sai mu tsarkake kanmu daga kowane abu da yake ƙazantar da jiki, da ruhu, mu zama da cikakken tsarki, saboda bangirma ga Allah. ");
INSERT INTO hausa_vpl VALUES ("C27_2","077_7_2","2CO","7","2","2","Ku saki zuciya da mu. Ba mu yi wa kowa laifi ba, ba mu ɓata kowa ba, ba mu cuci kowa ba. ");
INSERT INTO hausa_vpl VALUES ("C27_3","077_7_3","2CO","7","3","3","Ba na faɗin wannan don in sa muku laifi. Na riga na gaya muku yadda muke ƙaunarku ƙwarai cikin zukatanmu, har babu abin da zai iya raba ku da ƙaunarmu, ko a mutuwa ko a rayuwa. ");
INSERT INTO hausa_vpl VALUES ("C27_4","077_7_4","2CO","7","4","4","Na amince da ku gaya, ina kuma taƙama da ku ƙwarai. Na ƙarfafa sosai. Duk da wahalce wahalcenmu dai ina farin ciki ƙwarai da gaske. ");
INSERT INTO hausa_vpl VALUES ("C27_5","077_7_5","2CO","7","5","5","Gama sa’ad da muka zo Makidoniya, jikin nan namu bai sami hutu ba, sai ma aka matsa mana a ta kowane gefe, a waje ga rikici, a zukatanmu kuma ga tsoro. ");
INSERT INTO hausa_vpl VALUES ("C27_6","077_7_6","2CO","7","6","6","Amma Allah, wanda yakan yi wa masu ɓacin rai ta’aziyya ya yi mana ta’aziyya da zuwan Titus, ");
INSERT INTO hausa_vpl VALUES ("C27_7","077_7_7","2CO","7","7","7","ba ma don zuwansa kaɗai ba, har ma a game da ƙarfafa zuciyan nan da ya samu a wurinku. Ya gaya mana yadda kuke so ku gan ni sosai, da kuma yadda kuka yi baƙin ciki game da abin da ya faru, da niyyar da kuka yi na goyon bayana. Wannan ne ya sa na ji daɗi ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("C27_8","077_7_8","2CO","7","8","8","Ko da na ɓata muku rai ta wurin wasiƙata, ba na baƙin ciki da haka. Ko da yake dā kam na yi baƙin ciki, don na lura wasiƙata ta ɓata muku rai, amma na ɗan lokaci ne kawai. ");
INSERT INTO hausa_vpl VALUES ("C27_9","077_7_9","2CO","7","9","9","Duk da haka, yanzu ina farin ciki, ba don na sa ku baƙin ciki ba, sai dai domin baƙin cikinku ya kai ku ga tuba. Gama kun yi baƙin ciki kamar yadda Allah ya so, saboda haka, ba ku yi hasarar kome a sanadinmu ba. ");
INSERT INTO hausa_vpl VALUES ("C27_10","077_7_10","2CO","7","10","10","Baƙin ciki irin na tsoron Allah yana kai ga tuban da yake kawo ceto, ba ya kuma kawo baƙin ciki, amma baƙin ciki irin na duniya yakan kawo mutuwa. ");
INSERT INTO hausa_vpl VALUES ("C27_11","077_7_11","2CO","7","11","11","Ku dubi abin da wannan baƙin ciki irin na tsoron Allah ya kawo muku mana, ya sa ku marmarin aikatawa, da nuna cewa kun yi kuskure, ya sa kuka yi fushi, kuka kuma ji tsoro, ya sa kuka sa zuciya, kuka kuma sa aniya, ya sa kuna a shirye ku ga an yi horon da ya dace. Game da wannan sha’ani kam, lalle ta kowace hanya kun nuna cewa ba ku da laifi. ");
INSERT INTO hausa_vpl VALUES ("C27_12","077_7_12","2CO","7","12","12","To, ko da yake na rubuta muku, ba musamman a kan wanda ya yi laifin ba ne, ba kuwa a kan wanda aka cutar ba, sai dai domin a bayyana muku a gaban Allah tsananin kula da kuke yi mana. ");
INSERT INTO hausa_vpl VALUES ("C27_13","077_7_13","2CO","7","13","13","Ta wurin wannan duka, muka sami ƙarfafawa. Ban da ƙarfafawar da muka samu, mun ji daɗi ƙwarai saboda yadda muka ga farin cikin Titus, domin ruhunsa ya sami wartsakewa daga gare ku duka. ");
INSERT INTO hausa_vpl VALUES ("C27_14","077_7_14","2CO","7","14","14","Na yi taƙama da ku a wurinsa, ba ku kuwa ba ni kunya ba. Kamar dai yadda dukan abin da muka gaya muku gaskiya ne, haka ma taƙamarmu a kanku a gaban Titus ya zama gaskiya. ");
INSERT INTO hausa_vpl VALUES ("C27_15","077_7_15","2CO","7","15","15","Ƙaunar da yake yi muku ya ƙaru ƙwarai, duk sa’ad da yake tunawa da biyayyarku duka, da kuma irin yawan bangirman da kuka nuna masa lokacin da kuka karɓe shi. ");
INSERT INTO hausa_vpl VALUES ("C27_16","077_7_16","2CO","7","16","16","Ina farin ciki ne don na amince da ku ƙwarai da gaske. ");
INSERT INTO hausa_vpl VALUES ("C28_1","077_8_1","2CO","8","1","1","To, ’yan’uwa, muna so ku san abin da alherin Allah ya ba wa ikkilisiyoyin Makidoniya. ");
INSERT INTO hausa_vpl VALUES ("C28_2","077_8_2","2CO","8","2","2","Gama sun sha wuya sosai saboda tsananin wahalar da suka shiga, har yawan farin cikinsu ya kai su ga yin alheri ta bayarwa ga waɗansu, ko da yake suna cikin tsananin talauci. ");
INSERT INTO hausa_vpl VALUES ("C28_3","077_8_3","2CO","8","3","3","Gama ina shaida cewa sun bayar daidai gwargwadon iyawarsu, har ma fiye da ƙarfinsu. Su kansu, ");
INSERT INTO hausa_vpl VALUES ("C28_4","077_8_4","2CO","8","4","4","sun roƙe mu sosai don su sami damar yin bayarwa a wannan hidima ga tsarkaka. ");
INSERT INTO hausa_vpl VALUES ("C28_5","077_8_5","2CO","8","5","5","Ba su yi yadda muka za tă ba, sai ma suka fara ba da kansu ga Ubangiji, sa’an nan sai suka ba da kansu gare mu bisa ga nufin Allah. ");
INSERT INTO hausa_vpl VALUES ("C28_6","077_8_6","2CO","8","6","6","Ganin haka sai muka roƙi Titus, da yake shi ne ya riga ya tsiro da wannan aikin alheri a cikinku, sai yă ƙarasa shi. ");
INSERT INTO hausa_vpl VALUES ("C28_7","077_8_7","2CO","8","7","7","To, da yake kun fiffita a kowane abu cikin bangaskiya, cikin magana, cikin sani, cikin dukan ƙwazo, da kuma cikin ƙaunarku dominmu, sai ku fiffita a wannan aikin alheri ma. ");
INSERT INTO hausa_vpl VALUES ("C28_8","077_8_8","2CO","8","8","8","Ba umarni nake ba ku ba, sai dai ina so in gwada gaskiyar ƙaunarku ne, ta wurin kwatanta ta da aniyar waɗansu. ");
INSERT INTO hausa_vpl VALUES ("C28_9","077_8_9","2CO","8","9","9","Gama kun san alherin Ubangijinmu Yesu Kiristi cewa ko da yake shi mawadaci ne, duk da haka, ya zama matalauci saboda ku, domin ta wurin talaucinsa, ku zama mawadata. ");
INSERT INTO hausa_vpl VALUES ("C28_10","077_8_10","2CO","8","10","10","Ga shawarata a kan abin da ya fi muku kyau a wannan al’amari. Bara ku kuka fara bayarwa, kuka kuma zama na farko wajen niyyar yin haka. ");
INSERT INTO hausa_vpl VALUES ("C28_11","077_8_11","2CO","8","11","11","Yanzu sai ku ƙarasa aikin da irin niyyar da kuka fara, ku yi haka gwargwadon ƙarfinku. ");
INSERT INTO hausa_vpl VALUES ("C28_12","077_8_12","2CO","8","12","12","Gama in da niyyar bayarwa, za a karɓi bayarwa bisa ga abin da mutum yake da shi, ba bisa ga abin da ba shi da shi ba. ");
INSERT INTO hausa_vpl VALUES ("C28_13","077_8_13","2CO","8","13","13","Ba nufi nake yi a sawwaƙe wa waɗansu, ku kuwa a jibga muku nauyin ba. Amma ya yi kyau dai ");
INSERT INTO hausa_vpl VALUES ("C28_14","077_8_14","2CO","8","14","14","a raba daidai wa daida, sai ku taimake su a yanzu da yalwarku saboda rashinsu. Wata rana su ma su taimake ku da yalwarsu saboda rashinku, don a daidaita al’amari, ");
INSERT INTO hausa_vpl VALUES ("C28_15","077_8_15","2CO","8","15","15","kamar yadda yake a rubuce cewa, “Wanda ya tara da yawa, bai tara fiye da bukatarsa ba, wanda kuma ya tara kaɗan, bai kāsa masa ba.” ");
INSERT INTO hausa_vpl VALUES ("C28_16","077_8_16","2CO","8","16","16","Ina gode wa Allah, wanda ya sa a zuciyar Titus, irin kula da nake da shi dominku. ");
INSERT INTO hausa_vpl VALUES ("C28_17","077_8_17","2CO","8","17","17","Ba kawai ya yarda yă je wurinku kamar yadda muka roƙe shi yă yi ba, amma ya so yă zo kamar yadda ya riga ya yi niyya. ");
INSERT INTO hausa_vpl VALUES ("C28_18","077_8_18","2CO","8","18","18","Ga shi mun aiko ɗan’uwanmu nan tare da shi, wanda ikkilisiyoyi duka suna yabo saboda hidimarsa ga bishara. ");
INSERT INTO hausa_vpl VALUES ("C28_19","077_8_19","2CO","8","19","19","Ba kuwa haka kaɗai ba, har ma ikkilisiyoyi sun zaɓe shi yă riƙa tafiya tare da mu kan wannan aikin alheri da muke yi saboda ɗaukakar Ubangiji, da kuma nuna kyakkyawar niyyarmu. ");
INSERT INTO hausa_vpl VALUES ("C28_20","077_8_20","2CO","8","20","20","Muna gudu kada wani yă zarge mu, a kan yadda muke gudanar da wannan kyautar da aka bayar hannu sake. ");
INSERT INTO hausa_vpl VALUES ("C28_21","077_8_21","2CO","8","21","21","Gama muna iya ƙoƙari mu yi abin da yake daidai, ba a gaban Ubangiji kaɗai ba, amma a gaban mutane ma. ");
INSERT INTO hausa_vpl VALUES ("C28_22","077_8_22","2CO","8","22","22","Ban da wannan kuma, mun aiko da ɗan’uwanmu tare da su, wanda ya sha tabbatar mana da ƙwazonsa ta hanyoyi iri-iri, musamman yanzu, domin ya amince da ku da gaske. ");
INSERT INTO hausa_vpl VALUES ("C28_23","077_8_23","2CO","8","23","23","Game da Titus kuma, shi abokin tarayyata ne, da kuma abokin aikina a cikinku; game da ’yan’uwanmu kuwa, su wakilai ne na ikkilisiyoyi, kuma su masu ɗaukaka Kiristi ne. ");
INSERT INTO hausa_vpl VALUES ("C28_24","077_8_24","2CO","8","24","24","Saboda haka, ku nuna wa waɗannan mutane shaidar ƙaunarku, da kuma dalilin taƙamarmu da ku, domin ikkilisiyoyi su gani. ");
INSERT INTO hausa_vpl VALUES ("C29_1","077_9_1","2CO","9","1","1","Babu wata bukata in rubuta muku game da hidiman nan ga tsarkaka. ");
INSERT INTO hausa_vpl VALUES ("C29_2","077_9_2","2CO","9","2","2","Gama na san aniyarku na yin taimako, ina kuma taƙama a kan wannan ga Makidoniyawa, ina faɗin musu cewa tun bara, ku da kuke a Akayya a shirye kuke ku bayar. Ƙoƙarinku kuwa ya zuga yawancinsu ga aiki. ");
INSERT INTO hausa_vpl VALUES ("C29_3","077_9_3","2CO","9","3","3","Amma ina aika ’yan’uwan nan don kada taƙamar da muke yi da ku, a kan wannan al’amari ta zama a banza, sai dai domin yă zama kuna nan a shirye, kamar yadda na faɗa za ku kasance. ");
INSERT INTO hausa_vpl VALUES ("C29_4","077_9_4","2CO","9","4","4","Gama in waɗansu mutanen Makidoniya sun zo tare da ni, suka tarar ba a shirye kuke ba, kunya ta ishe mu, balle fa ku, saboda amincewa da muke yi da ku. ");
INSERT INTO hausa_vpl VALUES ("C29_5","077_9_5","2CO","9","5","5","Saboda haka, na ga ya dace in roƙi ’yan’uwan nan su ziyarce ku kafin lokacin, su kuma gama shirye-shirye saboda bayarwa ta yardar ran da kuka yi alkawari. Ta haka bayarwar za tă zama a shirye, ta yardar rai ba ta dole ba. ");
INSERT INTO hausa_vpl VALUES ("C29_6","077_9_6","2CO","9","6","6","Ku tuna fa, duk wanda ya yi shuki kaɗan zai girbe kaɗan, kuma duk wanda ya yi shuki da yawa, zai girbe a yalwace. ");
INSERT INTO hausa_vpl VALUES ("C29_7","077_9_7","2CO","9","7","7","Ya kamata kowa yă bayar bisa ga abin da ya yi shawara a zuciyarsa, ba tare da jin nauyi ko don dole ba, gama Allah yana son mai bayarwa da daɗin rai. ");
INSERT INTO hausa_vpl VALUES ("C29_8","077_9_8","2CO","9","8","8","Allah kuwa yana da iko yă ba ku fiye da bukatarku, domin kullum ku wadata da kome ta kowace hanya, kuna ta bayarwa hannu sake, kowane irin kyakkyawan aiki. ");
INSERT INTO hausa_vpl VALUES ("C29_9","077_9_9","2CO","9","9","9","Kamar yadda yake a rubuce cewa, “Ya ba gajiyayyu hannu sake, ayyukansa na alheri madawwama ne.” ");
INSERT INTO hausa_vpl VALUES ("C29_10","077_9_10","2CO","9","10","10","To, shi da yake ba mai shuka iri, yake kuma ba da abinci a ci, shi ne zai ba ku irin shukawa, yă riɓanya shi, yă kuma albarkaci ayyukanku na alheri da yawa. ");
INSERT INTO hausa_vpl VALUES ("C29_11","077_9_11","2CO","9","11","11","Za a wadatar da ku ta kowace hanya, domin ku riƙa bayarwa hannu sake a kowane lokaci. Ta wurinmu kuma bayarwarku hannu sake za tă zama sanadin godiya ga Allah. ");
INSERT INTO hausa_vpl VALUES ("C29_12","077_9_12","2CO","9","12","12","Wannan hidimar da kuke yi, ba bukatun mutanen Allah kaɗai take biya ba, amma tana cike da hanyoyin nuna godiya masu yawa ga Allah. ");
INSERT INTO hausa_vpl VALUES ("C29_13","077_9_13","2CO","9","13","13","Aikin nan naku na alheri tabbatar bangaskiyarku ne, za a kuwa ɗaukaka Allah saboda kun bayyana yarda, cewa kun yi na’am da bisharar Kiristi, saboda kuma gudummawa da kuka yi musu da saura duka, hannu sake. ");
INSERT INTO hausa_vpl VALUES ("C29_14","077_9_14","2CO","9","14","14","A cikin addu’arsu dominku kuwa, zukatansu za su koma gare ku, saboda mafificin alherin da Allah ya ba ku. ");
INSERT INTO hausa_vpl VALUES ("C29_15","077_9_15","2CO","9","15","15","Godiya ga Allah, saboda kyautarsa da ta wuce misali! ");
INSERT INTO hausa_vpl VALUES ("C210_1","077_10_1","2CO","10","1","1","Ni Bulus da kaina, ina roƙonku albarkacin tawali’u da sanyin hali na Kiristi, ni da ake yi wa kirari “marar tsanani” a cikinku, amma “mai matsawa” sa’ad da nake rabe da ku! ");
INSERT INTO hausa_vpl VALUES ("C210_2","077_10_2","2CO","10","2","2","Ina roƙonku cewa sa’ad da na zo kada ku tilasta ni in matsa muku, gama na tabbata zan iya tsaya wa waɗanda suka ce abin da muke yi sha’anin duniya ne. ");
INSERT INTO hausa_vpl VALUES ("C210_3","077_10_3","2CO","10","3","3","Ko da yake muna cikin duniya, ba ma yaƙi kamar yadda duniya take yi. ");
INSERT INTO hausa_vpl VALUES ("C210_4","077_10_4","2CO","10","4","4","Makaman da muke yaƙi da su, ba makamai na duniya ba ne. Sai dai na ikon Allah ne, masu rushe wuraren mafaka masu ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("C210_5","077_10_5","2CO","10","5","5","Muna ka da masu gardama da kowane tunanin ɗaga kai da yake kafa kansa gāba da sanin Allah, muna kuma jan hankalin kowa ga bautar Kiristi. ");
INSERT INTO hausa_vpl VALUES ("C210_6","077_10_6","2CO","10","6","6","A shirye muke mu hori kowane rashin biyayya, sa’ad da biyayyarku ta cika. ");
INSERT INTO hausa_vpl VALUES ("C210_7","077_10_7","2CO","10","7","7","Kuna duban abubuwa bisa-bisa ne kawai. In wani ya ganin cewa shi na Kiristi ne, ya kamata yă sāke lura cewa kamar yadda yake na Kiristi, haka mu ma muke. ");
INSERT INTO hausa_vpl VALUES ("C210_8","077_10_8","2CO","10","8","8","Ko da zan yi gadara fiye da kima a game da izinin nan namu, wanda Ubangiji ya bayar saboda inganta ku, ba don rushe ku ba, ba ni da abin jin kunya a ciki. ");
INSERT INTO hausa_vpl VALUES ("C210_9","077_10_9","2CO","10","9","9","Ba na so yă zama kamar ina ƙoƙari in tsorata ku ne da wasiƙuna. ");
INSERT INTO hausa_vpl VALUES ("C210_10","077_10_10","2CO","10","10","10","Gama waɗansu suna cewa, “Wasiƙunsa suna da nauyi da kuma ƙarfi, amma kuwa in ka gan shi, ba shi da wani kwarjini, maganarsa kuma ba kome ba ce.” ");
INSERT INTO hausa_vpl VALUES ("C210_11","077_10_11","2CO","10","11","11","Ya kamata irin waɗannan mutane su gane cewa abin da muke faɗa a cikin wasiƙunmu sa’ad da ba ma nan tare da ku, shi muke aikatawa sa’ad da muke nan. ");
INSERT INTO hausa_vpl VALUES ("C210_12","077_10_12","2CO","10","12","12","Ba za mu yi ƙarfin halin lissafta kanmu, ko mu kwatanta kanmu da waɗansu masu yabon kansu ba. Sa’ad da suke gwada kansu da kansu, da kuma kwatanta kansu da kansu, ba su da hikima. ");
INSERT INTO hausa_vpl VALUES ("C210_13","077_10_13","2CO","10","13","13","Amma mu kam, ba za mu yi taƙama mu zarce iyakarmu ba, sai dai za mu yi taƙama cikin filin da Allah ya ƙayyade mana, filin kuwa ya kai har zuwa wurinku. ");
INSERT INTO hausa_vpl VALUES ("C210_14","077_10_14","2CO","10","14","14","Ba mu wuce gona da iri a taƙamarmu ba, kamar yadda zai zama, da a ce ba mu zo wurinku ba, gama mun kai har wurinku da bisharar Kiristi. ");
INSERT INTO hausa_vpl VALUES ("C210_15","077_10_15","2CO","10","15","15","Fahariyarmu ba fiye da yadda ya kamata take ba, ba tă kuma shafi aikin waɗansu ba. Sai dai muna sa zuciya bangaskiyarku ta riƙa ƙaruwa, ta haka kuma fagen aikinmu a cikinku yă riƙa ƙaruwa ƙwarai da gaske. ");
INSERT INTO hausa_vpl VALUES ("C210_16","077_10_16","2CO","10","16","16","Saboda mu iya yin wa’azin bishara a yankunan da suke gaba da ku. Gama ba ma so mu yi taƙama game da aikin da aka riga aka yi a sashen wani. ");
INSERT INTO hausa_vpl VALUES ("C210_17","077_10_17","2CO","10","17","17","Amma, “Duk mai yin taƙama, sai ya yi taƙama da Ubangiji.” ");
INSERT INTO hausa_vpl VALUES ("C210_18","077_10_18","2CO","10","18","18","Ai, ba mai yabon kansa ake amincewa da shi ba, sai dai wanda Ubangiji ya yaba wa. ");
INSERT INTO hausa_vpl VALUES ("C211_1","077_11_1","2CO","11","1","1","Ina fata za ku yi haƙuri da ’yar wautata. Amma, ai, kun riga kun yi haƙuri. ");
INSERT INTO hausa_vpl VALUES ("C211_2","077_11_2","2CO","11","2","2","Ina kishinku da kishi irin na Allah. Na yi muku alkawarin aure ga miji ɗaya, Kiristi, domin in miƙa ku a gare shi kamar budurwa zalla. ");
INSERT INTO hausa_vpl VALUES ("C211_3","077_11_3","2CO","11","3","3","Sai dai ina tsoro kada yă zama, kamar yadda maciji ya yaudari Hawwa’u da makircinsa, ku ma a bauɗar da hankalinku daga sahihiyar biyayya amintacciya ga Kiristi. ");
INSERT INTO hausa_vpl VALUES ("C211_4","077_11_4","2CO","11","4","4","Gama in wani ya zo wurinku yana wa’azin wani Yesu dabam da wanda muka yi wa’azinsa, ko kuma in kun karɓi wani ruhu dabam da wanda kuka karɓa, ko wata bishara dabam da wadda kuka karɓa, ya nuna kun yarda da su ke nan cikin sauƙinkai. ");
INSERT INTO hausa_vpl VALUES ("C211_5","077_11_5","2CO","11","5","5","Amma a ganina waɗancan da kuke ce da su “manyan manzanni” ba su fi ni da wani abu ba. ");
INSERT INTO hausa_vpl VALUES ("C211_6","077_11_6","2CO","11","6","6","Mai yiwuwa ni ba horarre ba ne a magana, amma ina da sani. Mun kuwa bayyana muku wannan a sarari, ta kowace hanya. ");
INSERT INTO hausa_vpl VALUES ("C211_7","077_11_7","2CO","11","7","7","Laifi ke nan ne na yi da na ƙasƙantar da kaina, don a ɗaga ku zuwa babban matsayi ta wurin yin muku wa’azin bisharar Allah kyauta? ");
INSERT INTO hausa_vpl VALUES ("C211_8","077_11_8","2CO","11","8","8","Na yi wa waɗansu ikkilisiyoyi ƙwace ta wurin karɓar taimako daga wurinsu, domin in yi muku hidima. ");
INSERT INTO hausa_vpl VALUES ("C211_9","077_11_9","2CO","11","9","9","Sa’ad da nake tare da ku kuma nake zaman rashi, ban nawaita wa kowa ba, gama ’yan’uwan da suka zo daga Makidoniya sun biya bukata. Na kiyaye kaina daga nawaita muku ta kowace hanya, zan kuma ci gaba da yin haka. ");
INSERT INTO hausa_vpl VALUES ("C211_10","077_11_10","2CO","11","10","10","Ba shakka, kamar yadda gaskiyar Kiristi take a cikina, babu wani a yankunan Akayya da zai iya hana yin taƙaman nan tawa. ");
INSERT INTO hausa_vpl VALUES ("C211_11","077_11_11","2CO","11","11","11","Don me? Don ba na ƙaunar ku ne? Allah dai ya sani ina ƙaunarku! ");
INSERT INTO hausa_vpl VALUES ("C211_12","077_11_12","2CO","11","12","12","Zan kuma ci gaba da yin abin da nake yi, domin in toshe kafar mutanen nan da suke fariya, suna nema mu daidaita da su. ");
INSERT INTO hausa_vpl VALUES ("C211_13","077_11_13","2CO","11","13","13","Gama irin waɗannan mutane manzannin ƙarya ne, ma’aikata ne masu ruɗi, sun ɓad da kamanni kamar su manzannin Kiristi ne. ");
INSERT INTO hausa_vpl VALUES ("C211_14","077_11_14","2CO","11","14","14","Ba abin mamaki ba ne, gama Shaiɗan kansa ma yana ɓad da kamanni kamar shi mala’ikan haske ne. ");
INSERT INTO hausa_vpl VALUES ("C211_15","077_11_15","2CO","11","15","15","Don haka, ba abin mamaki ba ne, in bayin Shaiɗan sun ɓad da kamanni kamar su bayin adalci ne. A ƙarshe, za a sāka musu gwargwadon ayyukansu. ");
INSERT INTO hausa_vpl VALUES ("C211_16","077_11_16","2CO","11","16","16","Ina sāke faɗa, kada wani yă ɗauka ni wawa ne. Amma in kun ɗauke ni haka, to, sai ku karɓe ni kamar yadda kuke karɓan wawa, domin in ɗan in yi taƙama. ");
INSERT INTO hausa_vpl VALUES ("C211_17","077_11_17","2CO","11","17","17","A wannan taƙamata ba na magana yadda Ubangiji zai yi ba ne, sai dai magana ce irin ta wawa. ");
INSERT INTO hausa_vpl VALUES ("C211_18","077_11_18","2CO","11","18","18","Da yake mutane da yawa suna taƙama irin ta duniya, ni ma haka zan yi. ");
INSERT INTO hausa_vpl VALUES ("C211_19","077_11_19","2CO","11","19","19","Ku kam kuna da wayo sosai, har kuna jimre wa wawaye da murna! ");
INSERT INTO hausa_vpl VALUES ("C211_20","077_11_20","2CO","11","20","20","Gaskiyar ita ce, kuna haƙuri da duk wanda ya sa ku bauta ko ya cuce ku ko ya more ku ko ya nuna muku isa ko kuma ya mare ku a fuska. ");
INSERT INTO hausa_vpl VALUES ("C211_21","077_11_21","2CO","11","21","21","Ina jin kunya in ce mun nuna kāsawa da ba mu yi waɗannan abubuwan ba! Abin da wani yake da ƙarfin hali yin taƙama a kai, shi ne ni ma nake ƙarfin hali yin taƙama a kai. Ina magana kamar wawa ne. ");
INSERT INTO hausa_vpl VALUES ("C211_22","077_11_22","2CO","11","22","22","In su Ibraniyawa ne, ni ma haka. In su Isra’ilawa ne, ni ma haka. In su zuriyar Ibrahim ne, ni ma haka. ");
INSERT INTO hausa_vpl VALUES ("C211_23","077_11_23","2CO","11","23","23","In su bayin Kiristi ne, ni na fi su ma, ina magana kamar ruɗaɗɗe ne fa! Ai, na fi su shan fama ƙwarai da gaske, da shan dauri, na sha dūka marar iyaka, na sha hatsarin mutuwa iri-iri. ");
INSERT INTO hausa_vpl VALUES ("C211_24","077_11_24","2CO","11","24","24","Sau biyar Yahudawa suka yi mini bulala arba’in ɗaya babu. ");
INSERT INTO hausa_vpl VALUES ("C211_25","077_11_25","2CO","11","25","25","Sau uku aka bulale ni da bulalar ƙarfe, sau ɗaya aka jajjefe ni da duwatsu, sau uku jirgin ruwa ya ragargaje ina ciki, na kwana na kuma yini ruwan teku yana tafiya da ni. ");
INSERT INTO hausa_vpl VALUES ("C211_26","077_11_26","2CO","11","26","26","Na yi tafiye-tafiye da yawa, na sha hatsari a koguna, na sha hatsarin ’yan fashi, na sha hatsari a hannun kabilarmu, na sha hatsari a hannun al’ummai, na sha hatsari a birane, na sha hatsari a jeji, na sha hatsari a teku, na kuma sha hatsarin ’yan’uwa na ƙarya. ");
INSERT INTO hausa_vpl VALUES ("C211_27","077_11_27","2CO","11","27","27","Na yi fama, na shan wuya, ga kuma rashin barci sau da yawa. Na san abin da ake nufin da jin yunwa da ƙishirwa, sau da yawa kuwa na kasance da rashin abinci, na sha sanyi da zaman tsirara. ");
INSERT INTO hausa_vpl VALUES ("C211_28","077_11_28","2CO","11","28","28","Ban da waɗannan abubuwa, kowace rana ina ɗauke da nauyin kula da dukan ikkilisiyoyi. ");
INSERT INTO hausa_vpl VALUES ("C211_29","077_11_29","2CO","11","29","29","Wane ne ya rasa ƙarfi, da ban ji shi a jikina ba? Wane ne ya fāɗi cikin zunubi, da ban ji zafin wannan ba? ");
INSERT INTO hausa_vpl VALUES ("C211_30","077_11_30","2CO","11","30","30","In ma lalle ne in yi taƙama, to, sai in yi taƙama da abubuwan da suka nuna rashin ƙarfina. ");
INSERT INTO hausa_vpl VALUES ("C211_31","077_11_31","2CO","11","31","31","Allah Uban Ubangiji Yesu Kiristi, wanda yabo ta tabbata a gare shi har abada, ya san cewa ba ƙarya nake yi ba. ");
INSERT INTO hausa_vpl VALUES ("C211_32","077_11_32","2CO","11","32","32","A Damaskus, gwamnan da yake ƙarƙashin Sarki Aretas, ya sa tsare ƙofofin birnin Damaskus, don yă kama ni. ");
INSERT INTO hausa_vpl VALUES ("C211_33","077_11_33","2CO","11","33","33","Amma aka saukar da ni cikin kwando ta tagar katanga, na kuɓuce masa. ");
INSERT INTO hausa_vpl VALUES ("C212_1","077_12_1","2CO","12","1","1","Dole in ci gaba da yin taƙama. Ko da yake ba za tă amfane ni ba, zan yi magana a kan ru’uyoyi da wahayoyi waɗanda na karɓa daga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("C212_2","077_12_2","2CO","12","2","2","Na san wani a cikin Kiristi wanda shekaru goma sha huɗu da suka wuce an ɗauke zuwa sama ta uku. Ko a cikin jiki ne, ko kuwa ba a cikin jiki ba, ni dai ban sani ba, Allah ne ya sani. ");
INSERT INTO hausa_vpl VALUES ("C212_3","077_12_3","2CO","12","3","3","Na kuma san cewa wannan mutum, ko a cikin jiki ne, ko kuma ba a cikin jiki ba, ni dai ban sani ba, amma Allah ne ya sani, ");
INSERT INTO hausa_vpl VALUES ("C212_4","077_12_4","2CO","12","4","4","an ɗauke shi ne zuwa aljanna. Ya ji waɗansu abubuwa waɗanda ba zai iya faɗarsu da kalmomi ba, abubuwan da ba a ba wa mutum damar faɗi. ");
INSERT INTO hausa_vpl VALUES ("C212_5","077_12_5","2CO","12","5","5","Zan yi taƙama game da mutum irin wannan, sai dai ni ba zan yi taƙama da kaina ba, sai dai a kan rashin ƙarfina. ");
INSERT INTO hausa_vpl VALUES ("C212_6","077_12_6","2CO","12","6","6","Ko da zan so yin gadara ma, ba zan zama wawa ba, gama gaskiya zan faɗa. Amma na bar zancen haka, don kada wani ya ɗauke ni fiye da yadda yake ganina, ko yadda yake jin maganata. ");
INSERT INTO hausa_vpl VALUES ("C212_7","077_12_7","2CO","12","7","7","Don kada in cika da girman kai saboda waɗannan mafifitan manyan wahayoyi, sai aka sa mini wata ƙaya a jikina wadda ta zama ɗan saƙon Shaiɗan, don ta wahalshe ni. ");
INSERT INTO hausa_vpl VALUES ("C212_8","077_12_8","2CO","12","8","8","Sau uku na roƙi Ubangiji yă raba ni da wannan abu. ");
INSERT INTO hausa_vpl VALUES ("C212_9","077_12_9","2CO","12","9","9","Amma ya ce mini, “Alherina ya ishe ka, domin a cikin rashin ƙarfi ne ake ganin cikar ikona.” Saboda haka, zan ƙara yin taƙama da farin ciki game da rashin ƙarfina, domin ikon Yesu Kiristi yă zauna tare da ni. ");
INSERT INTO hausa_vpl VALUES ("C212_10","077_12_10","2CO","12","10","10","Shi ya sa nake murna cikin rashin ƙarfi, da zagi, da shan wahaloli, da tsanantawa, da matsaloli, saboda Kiristi. Don a sa’ad da nake marar ƙarfi a nan ne nake da ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("C212_11","077_12_11","2CO","12","11","11","Na yi wauta kam, amma ku ne kuke tilasta mini, ku ne kuwa ya kamata ku yaba mini, domin ba inda na kāsa waɗannan mafiffitan manzanni, ko da yake ni ba kome ba ne. ");
INSERT INTO hausa_vpl VALUES ("C212_12","077_12_12","2CO","12","12","12","Abubuwan da suke tabbatar da manzo, alamu, abubuwa da kuma ayyukan banmamaki, an aikata su a cikinku da matuƙar nacewa. ");
INSERT INTO hausa_vpl VALUES ("C212_13","077_12_13","2CO","12","13","13","Ta yaya ne darajarku ba tă kai ta sauran ikkilisiyoyi ba, ko kuwa don dai ban nawaita muku ba ne? Ku gafarta mini wannan laifi! ");
INSERT INTO hausa_vpl VALUES ("C212_14","077_12_14","2CO","12","14","14","Yanzu a shirye nake in ziyarce ku sau na uku, ba zan kuma nawaita muku ba, don ba kayanku nake so ba, ku nake so. Gama ba yara ne da ɗaukar nauyin iyayensu ba, sai dai iyaye ne da ɗaukar nauyin yaran. ");
INSERT INTO hausa_vpl VALUES ("C212_15","077_12_15","2CO","12","15","15","Don haka ina farin ciki in kashe dukan abin da nake da shi a kanku, har in ba da kaina ma dominku. In na ƙaunace ku fiye da haka, za ku rage ƙaunarku gare ni ne? ");
INSERT INTO hausa_vpl VALUES ("C212_16","077_12_16","2CO","12","16","16","To, shi ke nan, ban nawaita muku ba. Ashe, sai ku ce dabara na yi muku, na shawo kanku ta hanyar yaudara! ");
INSERT INTO hausa_vpl VALUES ("C212_17","077_12_17","2CO","12","17","17","Na cuce ku ne ta wurin wani daga cikin waɗanda na aiko a gare ku? ");
INSERT INTO hausa_vpl VALUES ("C212_18","077_12_18","2CO","12","18","18","Na roƙi Titus ya zo wurinku. Na kuma aiki ɗan’uwanmu tare da shi. Ko Titus ya cuce ku ne? Ba ruhu ɗaya yake bi da mu ba? Ba kuma hanya guda muka bi ba? ");
INSERT INTO hausa_vpl VALUES ("C212_19","077_12_19","2CO","12","19","19","Ko tun dā can, kuna tsammani muna kāre kanmu a gare ku ne? A gaban Allah muke magana, kamar waɗanda suke cikin Kiristi. Ƙaunatattuna, kome da muke yi, muna yi ne don inganta ku ne. ");
INSERT INTO hausa_vpl VALUES ("C212_20","077_12_20","2CO","12","20","20","Gama ina tsoro, in na zo, in tarar da ku dabam da yadda nake so, ku ma ku tarar da ni dabam da yadda kuke so. Ina tsoro kada yă zama akwai faɗa, da kishi, da fushi mai zafi, da tsattsaguwa, da ɓata suna, da gulma, da girman kai, da hargitsi. ");
INSERT INTO hausa_vpl VALUES ("C212_21","077_12_21","2CO","12","21","21","Ina tsoro kada sa’ad da na sāke zuwa, Allahna zai ƙasƙantar da ni a gabanku, kuma in yi baƙin ciki saboda waɗanda suka yi zunubi a dā, ba su kuma tuba daga aikin ƙazanta, da na fasikanci, da kuma lalata da suka sa kansu a ciki ba. ");
INSERT INTO hausa_vpl VALUES ("C213_1","077_13_1","2CO","13","1","1","Wannan za tă zama ziyarata ta uku a wurinku ke nan. “Dole a tabbatar da kowace magana ta bakin shaidu biyu ko uku.” ");
INSERT INTO hausa_vpl VALUES ("C213_2","077_13_2","2CO","13","2","2","Na riga na yi muku gargaɗi sa’ad da nake tare da ku a zuwana na biyu. Yanzu da ba na nan tare da ku, ina maimaita irin gargaɗin nan domin in na zo ba wanda zai kuɓuce wa horon nan, ");
INSERT INTO hausa_vpl VALUES ("C213_3","077_13_3","2CO","13","3","3","da yake kuna neman tabbaci cewa Kiristi yana magana ta wurina ne. To, ai, shi ba rarrauna ba ne a gare ku, amma ƙaƙƙarfa ne a cikinku. ");
INSERT INTO hausa_vpl VALUES ("C213_4","077_13_4","2CO","13","4","4","Ko da yake tabbatacce an gicciye shi cikin rashin ƙarfi, duk da haka, yana rayuwa bisa ga ikon Allah. Haka mu ma marasa ƙarfi ne a cikinsa, amma ta wurin ikon Allah za mu rayu tare da shi don mu yi muku hidima. ");
INSERT INTO hausa_vpl VALUES ("C213_5","077_13_5","2CO","13","5","5","Ku gwada kanku ku gani ko kuna cikin bangaskiya; ku auna kanku. Ashe, ba ku san cewa Kiristi Yesu yana cikinku ba? Sai ko in kun fāɗi gwajin. ");
INSERT INTO hausa_vpl VALUES ("C213_6","077_13_6","2CO","13","6","6","Ina fata za ku gane cewa ba mu fāɗi gwajin ba. ");
INSERT INTO hausa_vpl VALUES ("C213_7","077_13_7","2CO","13","7","7","Muna addu’a ga Allah kada ku aikata wani laifi. Ba don mutane su gani cewa mun ci gwajin ba ne, a’a, sai dai don ku yi abin da yake daidai, ko da yake zai zama kamar mun fāɗi gwajin ne. ");
INSERT INTO hausa_vpl VALUES ("C213_8","077_13_8","2CO","13","8","8","Kai, ba dama mu saɓa wa gaskiya, sai dai mu bi bayan gaskiyar. ");
INSERT INTO hausa_vpl VALUES ("C213_9","077_13_9","2CO","13","9","9","Murna muke sa’ad da ba mu da ƙarfi, ku kuwa kuna da ƙarfi. Addu’armu ita ce, ku zama cikakku. ");
INSERT INTO hausa_vpl VALUES ("C213_10","077_13_10","2CO","13","10","10","Shi ya sa nake rubuta waɗannan abubuwa, sa’ad da ba na nan tare da ku, domin sa’ad da na zo, kada yă zama mini tilas in yi muku tsanani a game da nuna ikon nan da Ubangiji ya ba ni saboda ingantawa, ba saboda rushewa ba. ");
INSERT INTO hausa_vpl VALUES ("C213_11","077_13_11","2CO","13","11","11","A ƙarshe ’yan’uwa, sai wata rana. Ku yi ƙoƙari ku zama cikakku. Ku saurari roƙona, ku zama da tunani ɗaya, ku yi zaman salama. Allah na ƙauna da salama kuwa zai kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("C213_12","077_13_12","2CO","13","12","12","Ku gaggai da juna da sumba mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("C213_13","077_13_13","2CO","13","13","13","Dukan tsarkaka suna gaishe ku. ");
INSERT INTO hausa_vpl VALUES ("C213_14","077_13_14","2CO","13","14","14","Alherin Ubangiji Yesu Kiristi, da ƙaunar Allah, da zumuntar Ruhu Mai Tsarki su kasance tare da ku duka.");
INSERT INTO hausa_vpl VALUES ("GL1_1","078_1_1","GAL","1","1","1","Bulus manzo, aikakke ba daga wurin mutum ba, ba kuma ta wurin mutane ba, amma ta wurin Yesu Kiristi da kuma Allah Uba, wanda ya tā da Yesu daga matattu. ");
INSERT INTO hausa_vpl VALUES ("GL1_2","078_1_2","GAL","1","2","2","Dukan ’yan’uwan kuma da suke tare da ni a nan, Suna gai da ikkilisiyoyi a Galatiya. ");
INSERT INTO hausa_vpl VALUES ("GL1_3","078_1_3","GAL","1","3","3","Alheri da salama daga Allah Ubanmu da Ubangiji Yesu Kiristi, su kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("GL1_4","078_1_4","GAL","1","4","4","Shi wanda ya ba da kansa saboda zunubanmu don yă cece mu daga wannan mugun zamani na yanzu, bisa ga nufin Allah wanda yake kuma Ubanmu, ");
INSERT INTO hausa_vpl VALUES ("GL1_5","078_1_5","GAL","1","5","5","a gare shi ɗaukaka ta tabbata har abada abadin. Amin. ");
INSERT INTO hausa_vpl VALUES ("GL1_6","078_1_6","GAL","1","6","6","Ina mamaki yadda kuka yi saurin yashe wanda ya kira ku ta wurin alherin Kiristi, kuna juyewa ga wata bishara dabam ");
INSERT INTO hausa_vpl VALUES ("GL1_7","078_1_7","GAL","1","7","7","wadda a gaskiya ba bishara ba ce ko kaɗan. Tabbatacce waɗansu mutane suna birkitar da ku, suna kuma ƙoƙari su karkatar da bisharar Kiristi. ");
INSERT INTO hausa_vpl VALUES ("GL1_8","078_1_8","GAL","1","8","8","Amma ko mu, ko mala’ika daga sama ya yi wa’azin wata bishara dabam da wadda muka yi muku, bari yă zama la’ananne har abada! ");
INSERT INTO hausa_vpl VALUES ("GL1_9","078_1_9","GAL","1","9","9","Kamar yadda muka riga muka faɗa, haka yanzu ma ina ƙara cewa in wani yana muku wa’azin wata bishara dabam da wadda kuka karɓa, bari yă zama la’ananne har abada! ");
INSERT INTO hausa_vpl VALUES ("GL1_10","078_1_10","GAL","1","10","10","Za a ce, ina ƙoƙarin neman amincewar mutane ne, ko amincewa ta Allah? Ko kuwa ina ƙoƙarin faranta wa mutane zuciya ne? Da a ce har yanzu ina ƙoƙarin faranta wa mutane zuciya ne, ai, da ban zama bawan Kiristi ba. ");
INSERT INTO hausa_vpl VALUES ("GL1_11","078_1_11","GAL","1","11","11","Ina so ku sani ’yan’uwa, cewa bisharar da nake wa’azi, ba mutum ne ya ƙago ta ba. ");
INSERT INTO hausa_vpl VALUES ("GL1_12","078_1_12","GAL","1","12","12","Ban karɓe ta daga wurin wani mutum ba, ba a kuma koya mini ita ba, a maimako, na karɓe ta, ta wurin wahayi daga Yesu Kiristi ne. ");
INSERT INTO hausa_vpl VALUES ("GL1_13","078_1_13","GAL","1","13","13","Kun dai ji labarin rayuwata ta dā a cikin Yahudanci, yadda na tsananta wa ikkilisiyar Allah ƙwarai, na kuma yi ƙoƙarin hallaka ta. ");
INSERT INTO hausa_vpl VALUES ("GL1_14","078_1_14","GAL","1","14","14","Na ci gaba a cikin Yahudanci fiye da yawancin Yahudawan da suke tsarana, na kuma yi ƙwazo ƙwarai ga bin al’adun kakannina. ");
INSERT INTO hausa_vpl VALUES ("GL1_15","078_1_15","GAL","1","15","15","Amma sa’ad da Allah, wanda ya keɓe ni daga mahaifa ya kira ni ta wurin alherinsa, ya kuma gamshe shi ");
INSERT INTO hausa_vpl VALUES ("GL1_16","078_1_16","GAL","1","16","16","yă bayyana Ɗansa a cikina, domin in yi wa’azinsa cikin Al’ummai. Ban nemi shawarar wani mutum ba. ");
INSERT INTO hausa_vpl VALUES ("GL1_17","078_1_17","GAL","1","17","17","Ban kuma tafi Urushalima domin in ga waɗanda suka riga ni zaman manzanni ba, sai dai na hanzarta na tafi ƙasar Arabiya, daga baya sai na koma Damaskus. ");
INSERT INTO hausa_vpl VALUES ("GL1_18","078_1_18","GAL","1","18","18","Bayan shekara uku, sai na haura zuwa Urushalima domin in sadu da Bitrus, na kuwa zauna tare da shi kwana goma sha biyar. ");
INSERT INTO hausa_vpl VALUES ("GL1_19","078_1_19","GAL","1","19","19","Ban ga wani a ciki sauran manzanni ba, sai dai Yaƙub ɗan’uwan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("GL1_20","078_1_20","GAL","1","20","20","Ina tabbatar muku a gaban Allah cewa abin da nake rubuta muku ba ƙarya ba ne. ");
INSERT INTO hausa_vpl VALUES ("GL1_21","078_1_21","GAL","1","21","21","Daga baya sai na tafi Suriya da Silisiya. ");
INSERT INTO hausa_vpl VALUES ("GL1_22","078_1_22","GAL","1","22","22","Ikkilisiyoyin da suke cikin Kiristi da suke a Yahudiya ba su san ni ba tukuna. ");
INSERT INTO hausa_vpl VALUES ("GL1_23","078_1_23","GAL","1","23","23","Sun dai sami labari ne kawai cewa, “Mutumin da dā yake tsananta mana yanzu yana wa’azin bangaskiyar da dā ya yi ƙoƙari yă hallaka.” ");
INSERT INTO hausa_vpl VALUES ("GL1_24","078_1_24","GAL","1","24","24","Sai suka yabi Allah saboda ni. ");
INSERT INTO hausa_vpl VALUES ("GL2_1","078_2_1","GAL","2","1","1","Bayan shekara goma sha huɗu sai na sāke haurawa zuwa Urushalima, a wannan lokaci na tafi tare da Barnabas. Na kuma ɗauki Titus muka tafi tare. ");
INSERT INTO hausa_vpl VALUES ("GL2_2","078_2_2","GAL","2","2","2","Na tafi ne bisa ga wani wahayi. Da na kai can, sai na bayyana musu bisharar da nake wa’azi a cikin Al’ummai. Na yi haka a keɓance a gaban waɗanda suke shugabanni, don tsoro kada gudun da nake yi, ko kuwa na riga na yi, yă zama a banza. ");
INSERT INTO hausa_vpl VALUES ("GL2_3","078_2_3","GAL","2","3","3","Amma ko Titus ma da yake tare da ni, ba a ce dole sai ya yi kaciya ba, ko da yake shi mutumin Al’ummai ne. ");
INSERT INTO hausa_vpl VALUES ("GL2_4","078_2_4","GAL","2","4","4","Wannan zancen kaciya ya taso domin waɗansu ’yan’uwan ƙarya sun shiga cikinmu domin su yi leƙe a kan ’yancin da muke da shi a cikin Kiristi Yesu, su kuma mai da mu bayi. ");
INSERT INTO hausa_vpl VALUES ("GL2_5","078_2_5","GAL","2","5","5","Ba mu kuwa ba su zarafi ba ko kaɗan, don gaskiyar bishara ta ci gaba da kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("GL2_6","078_2_6","GAL","2","6","6","Game da waɗanda aka ɗauka a dā a kan su wani abu ne, ko wane ne su, duk ɗaya ne a wurina; gama Allah ba ya nuna bambanci, ina dai gaya muku waɗannan da suke wani abu ne a dā, ba su ƙara mini kome ba. ");
INSERT INTO hausa_vpl VALUES ("GL2_7","078_2_7","GAL","2","7","7","A maimakon haka, sun ga cewa an danƙa mini hakkin wa’azin bishara ga Al’ummai, kamar yadda aka danƙa wa Bitrus ga Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("GL2_8","078_2_8","GAL","2","8","8","Gama Allah wanda ya yi aiki a cikin hidimar Bitrus a matsayin manzo ga Yahudawa, haka ma ya yi aiki a cikin hidimata a matsayin manzo ga Al’ummai. ");
INSERT INTO hausa_vpl VALUES ("GL2_9","078_2_9","GAL","2","9","9","Yaƙub, Bitrus da Yohanna waɗanda suke fitattun ginshiƙai, sun karɓe ni da Barnabas da hannu biyu biyu sa’ad da suka gane alherin da aka ba ni. Suka kuma yarda cewa ya kamata mu tafi wajen Al’ummai, su kuwa su tafi wajen Yahudawa. ");
INSERT INTO hausa_vpl VALUES ("GL2_10","078_2_10","GAL","2","10","10","Abin da dai suka roƙa shi ne ya kamata mu riƙa tuna da matalauta, abin nan da nake marmarin yi. ");
INSERT INTO hausa_vpl VALUES ("GL2_11","078_2_11","GAL","2","11","11","Sa’ad da Bitrus ya zo Antiyok, na tsawata masa ido da ido don laifinsa a fili yake. ");
INSERT INTO hausa_vpl VALUES ("GL2_12","078_2_12","GAL","2","12","12","Kafin waɗansu mutane su zo daga wurin Yaƙub, yakan ci abinci tare da Al’ummai. Amma da suka iso, sai ya fara janyewa, ya kuma ware kansa daga wajen Al’ummai domin yana tsoron waɗanda suke ƙungiyar masu kaciya. ");
INSERT INTO hausa_vpl VALUES ("GL2_13","078_2_13","GAL","2","13","13","Sauran Yahudawa suka haɗa kai da shi a munafuncinsa har Barnabas ma ya bauɗe. ");
INSERT INTO hausa_vpl VALUES ("GL2_14","078_2_14","GAL","2","14","14","Da na ga cewa ba sa yin daidai da gaskiyar bishara, sai na ce wa Bitrus a gabansu duka, “Kai mutumin Yahuda ne, duk da haka kana rayuwa kamar Ba’al’umme ba kamar mutumin Yahuda ba. To, yaya aka yi, kana tilasta Al’ummai su bi al’adun Yahudawa? ");
INSERT INTO hausa_vpl VALUES ("GL2_15","078_2_15","GAL","2","15","15","“Mu da muke Yahudawa ta wurin haihuwa ba Al’ummai masu zunubi ba, ");
INSERT INTO hausa_vpl VALUES ("GL2_16","078_2_16","GAL","2","16","16","mun san cewa mutum ba ya samun kuɓuta ta wurin kiyaye Doka, sai dai ta wurin bangaskiya cikin Kiristi Yesu. Saboda haka, mu ma, muka sa bangaskiyarmu cikin Kiristi Yesu don mu sami kuɓuta ta wurin bangaskiya cikin Kiristi ba ta wurin kiyaye Doka ba, domin ba wanda zai kuɓuta ta wurin bin Doka. ");
INSERT INTO hausa_vpl VALUES ("GL2_17","078_2_17","GAL","2","17","17","“In kuwa ya zama muna so mu sami zaman marasa laifi a gaban Allah ta wurin dogara ga Kiristi, sa’an nan an same mu mu kanmu ma masu zunubi ne, ashe, ko wannan zai nuna Kiristi yana ƙarfafa zunubi ke nan? A’a, ko kusa! ");
INSERT INTO hausa_vpl VALUES ("GL2_18","078_2_18","GAL","2","18","18","In na sāke gina abin da na rushe, na zama mai karyar Doka ke nan. ");
INSERT INTO hausa_vpl VALUES ("GL2_19","078_2_19","GAL","2","19","19","“Gama ta wurin Doka na mutu ga Doka saboda in rayu ga Allah. ");
INSERT INTO hausa_vpl VALUES ("GL2_20","078_2_20","GAL","2","20","20","An gicciye ni tare da Kiristi. Yanzu ba ni ne nake raye ba, Kiristi ne yake raye a cikina. Rayuwar da nake yi a jiki, ina rayuwa ce ta wurin bangaskiya cikin Ɗan Allah, wanda ya ƙaunace ni ya kuma ba da kansa domina. ");
INSERT INTO hausa_vpl VALUES ("GL2_21","078_2_21","GAL","2","21","21","Ba na ajiyar alherin Allah a gefe, gama da a ce ana samun adalci ta wurin Doka, ai, da Kiristi ya mutu a banza ke nan!” ");
INSERT INTO hausa_vpl VALUES ("GL3_1","078_3_1","GAL","3","1","1","Ya ku Galatiyawa marasa azanci! Wa ya ruɗe ku? A idanunku aka bayyana Yesu Kiristi gicciyeyye a sarari. ");
INSERT INTO hausa_vpl VALUES ("GL3_2","078_3_2","GAL","3","2","2","Zan so in san abu guda tak daga gare ku. Kun karɓi Ruhu ta wurin kiyaye Doka ne, ko kuwa ta wurin gaskata abin da kuka ji? ");
INSERT INTO hausa_vpl VALUES ("GL3_3","078_3_3","GAL","3","3","3","Ashe, rashin azancinku har ya kai ga haka? Bayan kun fara da Ruhu, a yanzu kuma da halin mutuntaka za ku ƙarasa? ");
INSERT INTO hausa_vpl VALUES ("GL3_4","078_3_4","GAL","3","4","4","Ashe, wahaloli dabam-dabam da kuka sha sun zama a banza ke nan? Haka zai yiwu kuwa? ");
INSERT INTO hausa_vpl VALUES ("GL3_5","078_3_5","GAL","3","5","5","Allah ya ba ku Ruhunsa yana kuma aikata ayyukan banmamaki a cikinku saboda kuna kiyaye Doka ne, ko kuwa domin kuna gaskatawa abin da kuka ji ne? ");
INSERT INTO hausa_vpl VALUES ("GL3_6","078_3_6","GAL","3","6","6","Ku dubi Ibrahim mana, “Ya gaskata Allah, aka kuwa lissafta wannan adalci ne a gare shi.” ");
INSERT INTO hausa_vpl VALUES ("GL3_7","078_3_7","GAL","3","7","7","Ku sani fa, waɗannan waɗanda suka gaskata, ’ya’yan Ibrahim ne. ");
INSERT INTO hausa_vpl VALUES ("GL3_8","078_3_8","GAL","3","8","8","Nassi ya hanga cewa Allah zai kuɓutar da Al’ummai ta wurin bangaskiya, ya kuwa sanar wa Ibrahim wannan bisharar tun kafin lokaci yă yi cewa, “Dukan al’ummai za su sami albarka ta wurinka.” ");
INSERT INTO hausa_vpl VALUES ("GL3_9","078_3_9","GAL","3","9","9","Saboda haka waɗanda suke da bangaskiya sun sami albarka tare da Ibrahim, mutumin bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("GL3_10","078_3_10","GAL","3","10","10","Dukan waɗanda suka dogara ga kiyaye Doka la’anannu ne, gama a rubuce yake cewa, “La’ananne ne duk wanda bai ci gaba da yi dukan abubuwan da aka rubuta a Littafin Doka ba.” ");
INSERT INTO hausa_vpl VALUES ("GL3_11","078_3_11","GAL","3","11","11","A fili yake ba wanda zai kuɓuta a gaban Allah ta wurin Doka, domin “Mai adalci zai rayu ta wurin bangaskiya.” ");
INSERT INTO hausa_vpl VALUES ("GL3_12","078_3_12","GAL","3","12","12","Doka ba tă dangana ga bangaskiya ba; a maimakon haka, “Mutumin da ya aikata waɗannan abubuwa zai rayu ta wurinsu.” ");
INSERT INTO hausa_vpl VALUES ("GL3_13","078_3_13","GAL","3","13","13","Kiristi ya fanshe mu daga la’anar Doka ta wurin zama la’ana saboda mu, gama a rubuce yake cewa, “La’ananne ne duk wanda aka rataye a kan itace.” ");
INSERT INTO hausa_vpl VALUES ("GL3_14","078_3_14","GAL","3","14","14","Ya fanshe mu domin albarkar da aka yi wa Ibrahim yă zo ga Al’ummai, ta wurin Kiristi Yesu, domin ta wurin bangaskiya mu karɓi alkawarin Ruhu. ");
INSERT INTO hausa_vpl VALUES ("GL3_15","078_3_15","GAL","3","15","15","’Yan’uwa, bari in yi muku misali da rayuwarmu ta yau da kullum. Kamar dai yadda ba mai kawarwa ko yă ƙara wani abu cikin alkawarin da mutane suka kafa, haka yake a wannan batu. ");
INSERT INTO hausa_vpl VALUES ("GL3_16","078_3_16","GAL","3","16","16","Alkawaran nan fa ga Ibrahim ne aka faɗa da kuma wani zuriyarsa. Nassi bai ce, “da zuriyoyi ba” wanda ya nuna kamar mutane da yawa, amma “ga zuriyarka,” wanda yake nufin mutum ɗaya, wanda shi ne Kiristi. ");
INSERT INTO hausa_vpl VALUES ("GL3_17","078_3_17","GAL","3","17","17","Abin da nake nufi shi ne, Dokar da aka shigar ita bayan shekaru 430, ba tă kawar da alkawarin da Allah ya yi tun dā ba. ");
INSERT INTO hausa_vpl VALUES ("GL3_18","078_3_18","GAL","3","18","18","Gama da a ce gādon yă dangana a kan doka ne, ai, da ba zai dangana a kan alkawari ba; amma Allah cikin alherinsa ya ba wa Ibrahim gādon ta wurin alkawari. ");
INSERT INTO hausa_vpl VALUES ("GL3_19","078_3_19","GAL","3","19","19","To, don me aka kawo Doka? An yi ƙari da Doka ne don fitowa da laifi fili har kafin na zuriyan nan ya zo, wanda aka yi wa alkawarin, an ba da doka ta wurin mala’iku ne, aka kuma danƙa ta a hannun matsakanci. ");
INSERT INTO hausa_vpl VALUES ("GL3_20","078_3_20","GAL","3","20","20","Kuma akan bukaci wani a tsakani ne idan da mutum biyu ake zance, Allah kuwa ɗaya ne. ");
INSERT INTO hausa_vpl VALUES ("GL3_21","078_3_21","GAL","3","21","21","To, Dokar ce tana gāba da alkawaran Allah ke nan? Sam, ko kaɗan! Gama da a ce an ba da Dokar da tana iya ba da rai, tabbatacce, da sai a sami adalci ta wurin Doka. ");
INSERT INTO hausa_vpl VALUES ("GL3_22","078_3_22","GAL","3","22","22","Amma Nassi ya kulle kome a ƙarƙashin ikon zunubi, domin abin da aka yi alkawarin nan, da ake bayar ta wurin bangaskiya a cikin Yesu Kiristi, a ba da shi ga waɗanda suka gaskata. ");
INSERT INTO hausa_vpl VALUES ("GL3_23","078_3_23","GAL","3","23","23","Kafin bangaskiyan nan tă zo, mun kasance a daure a kurkuku a ƙarƙashin Doka, a kulle sai da bangaskiyar da za tă zo ta bayyana. ");
INSERT INTO hausa_vpl VALUES ("GL3_24","078_3_24","GAL","3","24","24","Ta haka aka sa Dokar ta zama jagorarmu zuwa ga Kiristi don mu sami kuɓuta ta wurin bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("GL3_25","078_3_25","GAL","3","25","25","Yanzu da bangaskiya ta zo, ba sauran zamanmu a ƙarƙashin Doka. ");
INSERT INTO hausa_vpl VALUES ("GL3_26","078_3_26","GAL","3","26","26","Dukanku ’ya’yan Allah ne ta wurin bangaskiya cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("GL3_27","078_3_27","GAL","3","27","27","Gama dukanku da aka yi muku baftisma cikin Kiristi, kuna sanye da Kiristi ke nan. ");
INSERT INTO hausa_vpl VALUES ("GL3_28","078_3_28","GAL","3","28","28","Babu bambanci tsakanin mutumin Yahuda da mutumin Al’ummai, bawa da ’yantacce, namiji da ta mace, gama dukanku ɗaya ne cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("GL3_29","078_3_29","GAL","3","29","29","In kuwa ku na Kiristi ne, to, ku zuriyar Ibrahim ne, magāda kuma bisa ga alkawarin nan. ");
INSERT INTO hausa_vpl VALUES ("GL4_1","078_4_1","GAL","4","1","1","Abin da nake nufi shi ne, muddin magāji yana ɗan yaro ne tukuna, babu bambanci tsakaninsa da bawa, ko da yake shi ne da mallakar kome. ");
INSERT INTO hausa_vpl VALUES ("GL4_2","078_4_2","GAL","4","2","2","Yana ƙarƙashin iyayen goyonsa da masu riƙon amana har yă zuwa cikar lokacin da mahaifinsa ya sa. ");
INSERT INTO hausa_vpl VALUES ("GL4_3","078_4_3","GAL","4","3","3","Haka yake, sa’ad da muke ’yan yara, mun kasance cikin bauta a ƙarƙashin ƙa’idodin duniya. ");
INSERT INTO hausa_vpl VALUES ("GL4_4","078_4_4","GAL","4","4","4","Amma da lokacin da aka tsara ya yi sosai, sai Allah ya aiki Ɗansa, haifaffe daga mace, haifaffe a ƙarƙashin Doka, ");
INSERT INTO hausa_vpl VALUES ("GL4_5","078_4_5","GAL","4","5","5","domin yă fanshi waɗanda suke a ƙarƙashin doka, saboda mu sami cikakken matsayin zaman ’ya’ya. ");
INSERT INTO hausa_vpl VALUES ("GL4_6","078_4_6","GAL","4","6","6","Da yake ku ’ya’ya ne, sai Allah ya aiko da Ruhun Ɗansa a cikin zukatanmu, Ruhun da yake kira, “Abba, Uba.” ");
INSERT INTO hausa_vpl VALUES ("GL4_7","078_4_7","GAL","4","7","7","Saboda haka kai ba bawa ba ne kuma, kai ɗa ne; da yake kuwa kai ɗa ne, Allah ya mai da kai magāji. ");
INSERT INTO hausa_vpl VALUES ("GL4_8","078_4_8","GAL","4","8","8","Dā da ba ku san Allah ba, ku bayi ne ga waɗanda a ainihi ba alloli ba ne. ");
INSERT INTO hausa_vpl VALUES ("GL4_9","078_4_9","GAL","4","9","9","Amma yanzu da kuka san Allah, ko kuma a ce Allah ya san ku, yaya kuke sāke komawa ga ƙa’idodin duniya marasa ƙarfi, abin tausayi kuma? Kuna so ku sāke komawa ga bautarsu ne? ");
INSERT INTO hausa_vpl VALUES ("GL4_10","078_4_10","GAL","4","10","10","Kuna kiyaye ranaku da watanni da lokuta da shekaru na musamman! ");
INSERT INTO hausa_vpl VALUES ("GL4_11","078_4_11","GAL","4","11","11","Kai, kun ba ni tsoro, don ya zama kamar duk wahalar da na yi a kanku banza ne! ");
INSERT INTO hausa_vpl VALUES ("GL4_12","078_4_12","GAL","4","12","12","Ina roƙonku ’yan’uwa, ku zama kamar ni, gama na zama kamar ku. Ba ku yi mini wani laifi ba. ");
INSERT INTO hausa_vpl VALUES ("GL4_13","078_4_13","GAL","4","13","13","Kun san rashin lafiyar da na yi, shi ne ya yi mini hanyar da na kawo muku bishara da farko. ");
INSERT INTO hausa_vpl VALUES ("GL4_14","078_4_14","GAL","4","14","14","Ko da yake ciwona gwaji ne gare ku, ba ku yi mini reni ko ƙyama ba. A maimakon haka, kuka karɓe ni sai ka ce mala’ikan Allah, kuma sai ka ce Kiristi Yesu kansa. ");
INSERT INTO hausa_vpl VALUES ("GL4_15","078_4_15","GAL","4","15","15","Me ya faru da dukan farin cikinku? Na tabbata, a lokacin, da mai yiwuwa ne da kun ciccire idanunku kun ba ni. ");
INSERT INTO hausa_vpl VALUES ("GL4_16","078_4_16","GAL","4","16","16","Yanzu na zama abokin gābanku don na faɗa muku gaskiya ke nan? ");
INSERT INTO hausa_vpl VALUES ("GL4_17","078_4_17","GAL","4","17","17","Waɗancan mutane suna neman su rinjaye ku da ƙwazo, amma ba da kyakkyawar aniya ba. Abin da suke so shi ne su raba ku da mu, saboda ƙwazonku yă koma gare su. ");
INSERT INTO hausa_vpl VALUES ("GL4_18","078_4_18","GAL","4","18","18","Yana da kyau ku kasance da irin wannan niyya idan da nufi mai kyau ne, ku kuma kasance a haka koyaushe ba sai ina tare da ku ba. ");
INSERT INTO hausa_vpl VALUES ("GL4_19","078_4_19","GAL","4","19","19","Ya ku ’ya’yana ƙaunatattu, ina sāke shan wahalar naƙudarku, har sai Kiristi ya kahu a cikinku. ");
INSERT INTO hausa_vpl VALUES ("GL4_20","078_4_20","GAL","4","20","20","Da ma a ce ina tare da ku yanzu in canja muryata mana! Gama na damu ƙwarai saboda ku! ");
INSERT INTO hausa_vpl VALUES ("GL4_21","078_4_21","GAL","4","21","21","Ku gaya mini, ku da kuke so ku zauna a ƙarƙashin Doka, ba ku san abin da Doka ta ce ba ne? ");
INSERT INTO hausa_vpl VALUES ("GL4_22","078_4_22","GAL","4","22","22","Gama a rubuce yake cewa Ibrahim yana da ’ya’ya biyu maza, ɗaya ta wurin mace ’yar aikin gidansa, ɗaya kuma ta wurin ainihin matarsa. ");
INSERT INTO hausa_vpl VALUES ("GL4_23","078_4_23","GAL","4","23","23","Ɗansa na wajen mace ’yar aikin gidansa ya zo bisa ga ƙa’idar jiki ne; amma ɗansa na wajen ainihin matarsa ya zo a sakamakon alkawarin ne. ");
INSERT INTO hausa_vpl VALUES ("GL4_24","078_4_24","GAL","4","24","24","Za a iya ɗaukan waɗannan al’amura a matsayin misali, domin matan nan suna misalta alkawura biyu ne. Alkawari ɗaya daga Dutsen Sinai ne yana kuma haihuwar ’ya’yan da za su zama bayi. Hagar ke nan. ");
INSERT INTO hausa_vpl VALUES ("GL4_25","078_4_25","GAL","4","25","25","Hagar tana a matsayin Dutsen Sinai a Arabiya tana kuma kwatancin birnin Urushalima na yanzu, gama ita baiwa ce tare da ’ya’yanta. ");
INSERT INTO hausa_vpl VALUES ("GL4_26","078_4_26","GAL","4","26","26","Amma Urushalimar da take sama ’yantacciya ce, ita ce kuma mahaifiyarmu. ");
INSERT INTO hausa_vpl VALUES ("GL4_27","078_4_27","GAL","4","27","27","Gama a rubuce yake cewa, “Ki yi farin ciki, ya ke bakararriya, wadda ba ta haihuwa ki ɓarke da murna, ki kuma tā da murya, ke da ba kya naƙuda; domin da yawa ne ’ya’yan macen da aka yashe, fiye da na mai miji.” ");
INSERT INTO hausa_vpl VALUES ("GL4_28","078_4_28","GAL","4","28","28","To, ku ’yan’uwa, ku ’ya’yan alkawari ne kamar Ishaku. ");
INSERT INTO hausa_vpl VALUES ("GL4_29","078_4_29","GAL","4","29","29","A wancan lokaci, wannan ɗa wanda aka haifa ta wurin ƙa’idar jiki ya tsananta wa wanda aka haifa ta ikon Ruhu. Haka ma yake har yanzu. ");
INSERT INTO hausa_vpl VALUES ("GL4_30","078_4_30","GAL","4","30","30","Amma me Nassi ya ce? Nassi ya ce, “Kori macen nan ’yar aikin gida da ɗanta don ɗan mace ’yar aikin gida ba zai taɓa raba gādo tare da ɗa na ainihin matarka ba.” ");
INSERT INTO hausa_vpl VALUES ("GL4_31","078_4_31","GAL","4","31","31","Saboda haka, ’yan’uwa, mu ba ’ya’yan mace ’yar aikin gida ba ne, amma na ainihin matan gidan ne. ");
INSERT INTO hausa_vpl VALUES ("GL5_1","078_5_1","GAL","5","1","1","Saboda ’yanci ne Kiristi ya ’yantar da mu. Sai ku tsaya daram, kada ku yarda ku sāke komawa ƙarƙashin nauyin bauta. ");
INSERT INTO hausa_vpl VALUES ("GL5_2","078_5_2","GAL","5","2","2","Ku lura da kalmomina! Ni Bulus ina gaya muku cewa in kuka yarda aka yi muku kaciya, wannan ya nuna Kiristi ba shi da amfani a gare ku ba ko kaɗan. ");
INSERT INTO hausa_vpl VALUES ("GL5_3","078_5_3","GAL","5","3","3","Haka kuma ina ƙara sanar wa kowane mutumin da ya yarda aka yi masa kaciya cewa dole yă kiyaye dukan Doka. ");
INSERT INTO hausa_vpl VALUES ("GL5_4","078_5_4","GAL","5","4","4","Ku da kuke ƙoƙarin kuɓuta ta wurin Doka an raba ku da Kiristi ke nan; kuka kuma fāɗi daga alheri. ");
INSERT INTO hausa_vpl VALUES ("GL5_5","078_5_5","GAL","5","5","5","Amma ta wurin bangaskiya muna marmarin jira adalcin da muke bege ta wurin Ruhu. ");
INSERT INTO hausa_vpl VALUES ("GL5_6","078_5_6","GAL","5","6","6","Gama a cikin Kiristi Yesu, kaciya ko rashin kaciya ba su da wani amfani. Abin da kawai yake da amfani shi ne, bangaskiyar da take bayyana kanta ta wurin ƙauna. ");
INSERT INTO hausa_vpl VALUES ("GL5_7","078_5_7","GAL","5","7","7","Kun yi tsere mai kyau a dā. Wa ya shige gabanku ya hana ku bin gaskiya? ");
INSERT INTO hausa_vpl VALUES ("GL5_8","078_5_8","GAL","5","8","8","Wannan rarrashin da ake muku ba daga wanda ya kira ku ba ne. ");
INSERT INTO hausa_vpl VALUES ("GL5_9","078_5_9","GAL","5","9","9","“Ɗan yisti kaɗan ne yake gama dukan curin burodi.” ");
INSERT INTO hausa_vpl VALUES ("GL5_10","078_5_10","GAL","5","10","10","Ina da tabbaci cikin Ubangiji cewa ba za ku bi wani ra’ayi dabam ba. Wannan da yake rikita ku za a hukunta shi, ko shi wane ne. ");
INSERT INTO hausa_vpl VALUES ("GL5_11","078_5_11","GAL","5","11","11","’Yan’uwa, da a ce har yanzu ina wa’azin kaciya ne, to, me ya sa ake tsananta mini har yanzu? In haka ne, ashe, an kawar da abin da yake sa tuntuɓe game da gicciye ke nan. ");
INSERT INTO hausa_vpl VALUES ("GL5_12","078_5_12","GAL","5","12","12","Da ma a ce masu tā da hankalinku ɗin nan su yanke gabansu gaba ɗaya mana! ");
INSERT INTO hausa_vpl VALUES ("GL5_13","078_5_13","GAL","5","13","13","Ku ’yan’uwana, an kira ku ga zama ’yantattu. Amma kada ku yi amfani da ’yancinku don aikata ayyukan mutuntaka a maimakon haka, ku yi hidimar juna da ƙauna. ");
INSERT INTO hausa_vpl VALUES ("GL5_14","078_5_14","GAL","5","14","14","Dukan doka an taƙaita a cikin umarni ɗaya ne cewa, “Ka ƙaunaci maƙwabcinka kamar kanka.” ");
INSERT INTO hausa_vpl VALUES ("GL5_15","078_5_15","GAL","5","15","15","In kun ci gaba da cizo, kuna kuma cin naman juna, ku yi hankali in ba haka ba za ku hallaka juna. ");
INSERT INTO hausa_vpl VALUES ("GL5_16","078_5_16","GAL","5","16","16","Saboda haka ina ce muku, ku yi rayuwa ta wurin Ruhu, ba za ku kuwa gamsar da sha’awace-sha’awacen mutuntaka ba. ");
INSERT INTO hausa_vpl VALUES ("GL5_17","078_5_17","GAL","5","17","17","Gama mutuntaka yana son abin da Ruhu yake ƙi, Ruhu kuma yana son abin da mutuntaka yake ƙi. Waɗannan biyu kuwa gāba suke da juna, har ku kāsa yin abin da kuke so. ");
INSERT INTO hausa_vpl VALUES ("GL5_18","078_5_18","GAL","5","18","18","Amma in Ruhu ne yake bishe ku, ba ku a ƙarƙashin Doka ke nan. ");
INSERT INTO hausa_vpl VALUES ("GL5_19","078_5_19","GAL","5","19","19","Ayyukan mutuntaka kuwa a fili suke. Wato, fasikanci, ƙazanta da kuma lalata; ");
INSERT INTO hausa_vpl VALUES ("GL5_20","078_5_20","GAL","5","20","20","bautar gumaka da sihiri; ƙiyayya, faɗa, kishi, fushi mai zafi, sonkai, tsattsaguwa, hamayya, ");
INSERT INTO hausa_vpl VALUES ("GL5_21","078_5_21","GAL","5","21","21","da ƙyashi; buguwa, shashanci, da ire-irensu. Na gargaɗe ku, yadda na yi a dā, cewa masu irin wannan rayuwa ba za su gāji mulkin Allah ba. ");
INSERT INTO hausa_vpl VALUES ("GL5_22","078_5_22","GAL","5","22","22","Amma amfanin da Ruhu yake bayar shi ne ƙauna, farin ciki, salama, haƙuri, kirki, nagarta, aminci, ");
INSERT INTO hausa_vpl VALUES ("GL5_23","078_5_23","GAL","5","23","23","sauƙinkai, da kuma kamunkai. Ai, ba ruwan Doka da waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("GL5_24","078_5_24","GAL","5","24","24","Waɗanda suke na Kiristi Yesu, sun gicciye mutuntaka tare da abubuwan da mutum yake marmari da kuma sha’awace-sha’awacensa. ");
INSERT INTO hausa_vpl VALUES ("GL5_25","078_5_25","GAL","5","25","25","Da yake muna rayuwa ta Ruhu ne, bari mu ci gaba da al’amuranmu ta wurin Ruhu. ");
INSERT INTO hausa_vpl VALUES ("GL5_26","078_5_26","GAL","5","26","26","Kada mu zama masu girman kai, muna tsokana muna kuma jin kishin juna. ");
INSERT INTO hausa_vpl VALUES ("GL6_1","078_6_1","GAL","6","1","1","’Yan’uwa, in an kama wani yana cikin yin zunubi, ku da kuke masu ruhaniya ya kamata ku komo da shi a kan hanya a hankali. Amma ku lura da kanku, domin kada maimakon dawowa da ɗan’uwanku, ku ma ku fāɗi cikin jarraba. ");
INSERT INTO hausa_vpl VALUES ("GL6_2","078_6_2","GAL","6","2","2","Ku ɗauki nawayar juna, a haka kuwa za ku cika dokar Kiristi. ");
INSERT INTO hausa_vpl VALUES ("GL6_3","078_6_3","GAL","6","3","3","In wani yana tsammani shi wani abu ne alhali kuwa shi ba kome ba, ruɗin kansa yake yi. ");
INSERT INTO hausa_vpl VALUES ("GL6_4","078_6_4","GAL","6","4","4","Kowa yă auna ayyukansa. A sa’an nan ne zai iya yin taƙama da kansa, ba tare da kwatanta kansa da wani ba, ");
INSERT INTO hausa_vpl VALUES ("GL6_5","078_6_5","GAL","6","5","5","gama kowa zai ɗauki kayansa. ");
INSERT INTO hausa_vpl VALUES ("GL6_6","078_6_6","GAL","6","6","6","Duk haka, wanda aka koya wa maganar Kiristi, bari yă raba abubuwan nan na alheri tare da wanda ya koyar da shi. ");
INSERT INTO hausa_vpl VALUES ("GL6_7","078_6_7","GAL","6","7","7","Kada a ruɗe ku. Ba a yi wa Allah ba’a. Mutum yakan girbe abin da ya shuka ne. ");
INSERT INTO hausa_vpl VALUES ("GL6_8","078_6_8","GAL","6","8","8","Wanda ya yi shuki don yă gamshi mutuntakarsa, daga wannan mutuntaka zai girbi hallaka. Wanda ya yi shuki domin yă gamshi Ruhu, daga Ruhu zai girbi rai madawwami. ");
INSERT INTO hausa_vpl VALUES ("GL6_9","078_6_9","GAL","6","9","9","Kada mu gaji da yin nagarta, gama a daidai lokaci za mu girbe amfani, in ba mu fid da zuciya ba. ");
INSERT INTO hausa_vpl VALUES ("GL6_10","078_6_10","GAL","6","10","10","Saboda haka, in da hali, bari mu aikata nagarta ga dukan mutane, musamman ga waɗanda suke na iyalin masu bi. ");
INSERT INTO hausa_vpl VALUES ("GL6_11","078_6_11","GAL","6","11","11","Ku dubi irin manya-manyan harufan da na yi amfani da su yayinda nake rubuta muku da hannuna! ");
INSERT INTO hausa_vpl VALUES ("GL6_12","078_6_12","GAL","6","12","12","Waɗanda suke son nuna bajinta a fili suna ƙoƙari su tilasta muku ku yi kaciya ne. Dalilin kaɗai da suke yin haka shi ne don gudu kada a tsananta musu saboda gicciyen Kiristi ne. ");
INSERT INTO hausa_vpl VALUES ("GL6_13","078_6_13","GAL","6","13","13","Kai, su masu kaciya ma ba su kiyaye Doka ba, duk da haka suna so a yi muku kaciya don su yi taƙama kan an yi muku kaciya. ");
INSERT INTO hausa_vpl VALUES ("GL6_14","078_6_14","GAL","6","14","14","Kada in taɓa yin taƙama ga kome sai dai a cikin gicciyen Ubangijinmu Yesu Kiristi, wanda ta wurinsa aka gicciye duniya a gare ni, aka kuma gicciye ni ga duniya. ");
INSERT INTO hausa_vpl VALUES ("GL6_15","078_6_15","GAL","6","15","15","Kaciya ko rashin kaciya ba wani abu ba ne; abin da yake da amfani shi ne sabuwar halitta. ");
INSERT INTO hausa_vpl VALUES ("GL6_16","078_6_16","GAL","6","16","16","Salama da jinƙai su tabbata ga dukan waɗanda suke bin wannan ƙa’ida, har ma ga Isra’ila na Allah. ");
INSERT INTO hausa_vpl VALUES ("GL6_17","078_6_17","GAL","6","17","17","A ƙarshe, kada kowa yă ƙara damuna, gama ina ɗauke da raunuka masu nuna ni bawan Ubangiji Yesu ne. ");
INSERT INTO hausa_vpl VALUES ("GL6_18","078_6_18","GAL","6","18","18","’Yan’uwa! Alherin Ubangijinmu Yesu Kiristi yă kasance tare da ruhunku. Amin.");
INSERT INTO hausa_vpl VALUES ("EP1_1","079_1_1","EPH","1","1","1","Bulus, wanda Allah ya zaɓa don yă zama manzon Kiristi Yesu, Zuwa ga tsarkaka da suke a Afisa, da kuma suke amintattu cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("EP1_2","079_1_2","EPH","1","2","2","Alheri da salama daga Allah Ubanmu da Ubangiji Yesu Kiristi, su kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("EP1_3","079_1_3","EPH","1","3","3","Yabo ya tabbata ga Allah Uban Ubangijinmu Yesu Kiristi, wanda ya kawo mana kowace albarka ta ruhaniya daga sama. ");
INSERT INTO hausa_vpl VALUES ("EP1_4","079_1_4","EPH","1","4","4","Gama ya zaɓe mu a cikin Kiristi tun dā can, kafin ma a halicci duniya don mu zama masu tsarki da kuma marasa aibi a gabansa. ");
INSERT INTO hausa_vpl VALUES ("EP1_5","079_1_5","EPH","1","5","5","A cikin ƙauna, ya ƙaddara mu zama ’ya’yansa na riƙo ta wurin Kiristi Yesu, bisa ga nufinsa na alheri. ");
INSERT INTO hausa_vpl VALUES ("EP1_6","079_1_6","EPH","1","6","6","Ya yi haka don mu yabi Allah saboda alherin da ya yi mana saboda mu na ƙaunataccen Ɗansa ne. ");
INSERT INTO hausa_vpl VALUES ("EP1_7","079_1_7","EPH","1","7","7","A cikinsa muka sami fansa ta wurin jininsa, wato, yafewar zunubanmu. Kiristi ya yi wannan saboda yawan alherin Allah ");
INSERT INTO hausa_vpl VALUES ("EP1_8","079_1_8","EPH","1","8","8","wanda ya ba mu babu iyaka tare da dukan hikima da fahimta. ");
INSERT INTO hausa_vpl VALUES ("EP1_9","079_1_9","EPH","1","9","9","Allah ya yi abin da ya nufa, ya kuma sanar mana shirin asirin da ya riga ya shirya yă cika ta wurin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("EP1_10","079_1_10","EPH","1","10","10","Nufinsa ke nan, idan lokaci ya cika, yă harhaɗa dukan abubuwa a ƙarƙashin ikon Kiristi, wato, dukan abubuwan da suke sama da abubuwan da suke ƙasa. ");
INSERT INTO hausa_vpl VALUES ("EP1_11","079_1_11","EPH","1","11","11","A cikinsa ne kuma aka zaɓe mu mu sami gādo daga Allah, an kuwa ƙaddara mu ga haka bisa ga nufin wannan da yake zartar da dukan abubuwa yadda ya yi nufi yă yi. ");
INSERT INTO hausa_vpl VALUES ("EP1_12","079_1_12","EPH","1","12","12","Manufar Allah ita ce cewa mu da muka fara sa bege a cikin Kiristi, mu yi zaman yabon ɗaukakar Allah. ");
INSERT INTO hausa_vpl VALUES ("EP1_13","079_1_13","EPH","1","13","13","An kuma haɗa ku a cikin Kiristi lokacin da kuka ji saƙon nan na gaskiya, wanda yake labari mai daɗi na cetonku. Da kuka ba da gaskiya, sai aka yi muku alamar shaida a cikinsa da Ruhu Mai Tsarki. ");
INSERT INTO hausa_vpl VALUES ("EP1_14","079_1_14","EPH","1","14","14","Ruhu Mai Tsarkin nan shi ne tabbacin da Allah ya yi na cewa zai ba mu kome da ya yi alkawari, har ya sa muka sani nan gaba Allah zai ceci waɗanda suke nasa. Wannan kuwa domin yabon ɗaukakarsa ne. ");
INSERT INTO hausa_vpl VALUES ("EP1_15","079_1_15","EPH","1","15","15","Saboda haka, tun lokacin da na ji labarin bangaskiyarku cikin Ubangiji Yesu da kuma ƙaunar da kuke yi wa dukan mutanen Allah, ");
INSERT INTO hausa_vpl VALUES ("EP1_16","079_1_16","EPH","1","16","16","ban fasa yin godiya saboda ku ba, ina tuna da ku cikin addu’o’ina. ");
INSERT INTO hausa_vpl VALUES ("EP1_17","079_1_17","EPH","1","17","17","Ina ta roƙo cewa Allah na Ubangijinmu Yesu Kiristi, Uba Maɗaukaki, yă ba ku Ruhun hikima da na ganewa, domin ku san shi da kyau. ");
INSERT INTO hausa_vpl VALUES ("EP1_18","079_1_18","EPH","1","18","18","Ina kuma addu’a cewa zuciyarku tă waye don ku gane ko mene ne sa zuciyan nan da ya kira ku a kansa, ku kuma san darajar dukiyan nan wadda take ta mutanen Allah, wato, albarkunsa. ");
INSERT INTO hausa_vpl VALUES ("EP1_19","079_1_19","EPH","1","19","19","Ina addu’a ku san girman ikon Allah wanda ya wuce misali, wanda yake namu. Ikon da yake aiki a cikinmu, ɗaya ne da ikon nan ");
INSERT INTO hausa_vpl VALUES ("EP1_20","079_1_20","EPH","1","20","20","da ya tā da Kiristi daga matattu, ya kuma sa ya zauna a hannun damansa a cikin mulkin samaniya. ");
INSERT INTO hausa_vpl VALUES ("EP1_21","079_1_21","EPH","1","21","21","Yanzu yana mulki a kan dukan masu sarauta, da masu iko, da masu ƙarfi, da kuma masu mulki. Yana mulkin kome a wannan duniya, zai kuma yi mulkin duniya mai zuwa. ");
INSERT INTO hausa_vpl VALUES ("EP1_22","079_1_22","EPH","1","22","22","Allah ya sa kome a ƙarƙashin ikonsa, ya kuma ba shi iko a kan kome don amfanin ikkilisiya. ");
INSERT INTO hausa_vpl VALUES ("EP1_23","079_1_23","EPH","1","23","23","Kuma ikkilisiya ce jikinsa; ta kuma cika da Kiristi, wanda ya cika kome ta kowace hanya. ");
INSERT INTO hausa_vpl VALUES ("EP2_1","079_2_1","EPH","2","1","1","Ku kam, a dā ku matattu ne saboda laifofinku da kuma zunubanku. ");
INSERT INTO hausa_vpl VALUES ("EP2_2","079_2_2","EPH","2","2","2","Kun yi rayuwa kamar yadda sauran mutanen duniya suke yi, cike da zunubi, kuna biyayya ga sarki masu ikon sarari sama, wato, ruhun nan da yanzu yake aiki a cikin masu ƙin biyayya ga Allah. ");
INSERT INTO hausa_vpl VALUES ("EP2_3","079_2_3","EPH","2","3","3","Dukanmu a dā mun yi irin rayuwan nan a cikinsu, muna bin kwaɗayi da sha’awace-sha’awacen jikunanmu da tunaninmu. Kamar sauran mutane, mun cancanci fushin Allah. ");
INSERT INTO hausa_vpl VALUES ("EP2_4","079_2_4","EPH","2","4","4","Amma saboda yawan ƙaunar da yake mana, Allah, wanda yake mai yawan jinƙai, ");
INSERT INTO hausa_vpl VALUES ("EP2_5","079_2_5","EPH","2","5","5","ya ba mu rai sa’ad da ya tashe Kiristi daga matattu. Ta wurin alherin Allah ne aka cece ku. ");
INSERT INTO hausa_vpl VALUES ("EP2_6","079_2_6","EPH","2","6","6","Allah ya tashe mu tare da Kiristi, ya kuma ba mu wurin zama tare da shi a cikin mulkin samaniya. ");
INSERT INTO hausa_vpl VALUES ("EP2_7","079_2_7","EPH","2","7","7","Allah ya yi haka domin a tsararraki masu zuwa yă nuna yalwar alherinsa da ya wuce misali, an bayyana alheransa da ya yi mana ta wurin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("EP2_8","079_2_8","EPH","2","8","8","Allah ya cece ku ta wurin alheri sa’ad da kuka ba da gaskiya. Wannan kuwa ba yinku ba ne, kyauta ce daga Allah. ");
INSERT INTO hausa_vpl VALUES ("EP2_9","079_2_9","EPH","2","9","9","Ba kuwa saboda aikin lada ba, don kada wani yă ɗaga kai. ");
INSERT INTO hausa_vpl VALUES ("EP2_10","079_2_10","EPH","2","10","10","Ai, mu aikinsa ne, an sāke halittarmu a cikin Kiristi Yesu musamman domin mu yi kyawawan ayyuka, waɗanda Allah ya tanadar mana tun da fari, mu yi. ");
INSERT INTO hausa_vpl VALUES ("EP2_11","079_2_11","EPH","2","11","11","Saboda haka, ku tuna dā ku Al’ummai ne bisa ga haihuwa, waɗanda kuma ake kira masu “kaciya” sukan kira ku “marasa kaciya” (ga shi kuwa, kaciyar nan ta jiki ce, wadda ake yi da hannu). ");
INSERT INTO hausa_vpl VALUES ("EP2_12","079_2_12","EPH","2","12","12","Ku kuma tuna a lokacin ba ku san Kiristi ba. A ware kuke daga mutanen Isra’ila, ba ku kuma da dangantaka da alkawaran da Allah ya yi da su. Kun yi zama a duniyan nan babu bege kuma babu Allah. ");
INSERT INTO hausa_vpl VALUES ("EP2_13","079_2_13","EPH","2","13","13","Amma yanzu a cikin Kiristi Yesu, ku da dā kuke can da nesa an kawo ku kusa ta wurin jinin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("EP2_14","079_2_14","EPH","2","14","14","Gama shi kansa shi ne salamarmu, shi ne ya kawo ƙungiyoyi biyu suka zama ɗaya, ya kuma rushe katangan nan ta ƙiyayya wadda ta raba mu. ");
INSERT INTO hausa_vpl VALUES ("EP2_15","079_2_15","EPH","2","15","15","Kiristi ya ba da jikinsa don yă kawar da doka da dukan umarnanta da kuma ƙa’idodinta. Ya yi haka domin yă halicci sabuwar zuriya daga zuriyoyin nan biyu. Ta haka kuma ya kawo salama tsakaninsu. ");
INSERT INTO hausa_vpl VALUES ("EP2_16","079_2_16","EPH","2","16","16","A kan gicciye, Kiristi ya kawar da ƙiyayyar da take tsakaninmu da juna. Ya kuma kawo sulhu tsakaninmu da Allah. ");
INSERT INTO hausa_vpl VALUES ("EP2_17","079_2_17","EPH","2","17","17","Ya zo ya yi muku wa’azin salama; ku da kuke nesa da shi, ya kuma yi wa waɗanda suke kusa. ");
INSERT INTO hausa_vpl VALUES ("EP2_18","079_2_18","EPH","2","18","18","Gama ta wurinsa dukanmu za mu iya zuwa gun Uba ta wurin Ruhu guda. ");
INSERT INTO hausa_vpl VALUES ("EP2_19","079_2_19","EPH","2","19","19","Don haka, yanzu ku ba baƙi ba ne, ku kuma ba bare ba ne. Ku ’yan ƙasa ne tare da mutanen Allah, iyalin gidan Allah kuma. ");
INSERT INTO hausa_vpl VALUES ("EP2_20","079_2_20","EPH","2","20","20","Ku gini ne wanda manzanni da annabawa suke tushensa, Kiristi kuma shi ne dutse mafi muhimmanci na ginin. ");
INSERT INTO hausa_vpl VALUES ("EP2_21","079_2_21","EPH","2","21","21","Ta wurinsa ne dukan ginin yake a haɗe, shi ne kuma yake sa ginin yă yi girma, yă zama haikali mai tsarki domin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EP2_22","079_2_22","EPH","2","22","22","Ku ma sashe ne na wannan ginin da Kiristi ya yi inda Allah yake zaune ta wurin Ruhunsa. ");
INSERT INTO hausa_vpl VALUES ("EP3_1","079_3_1","EPH","3","1","1","Saboda haka, ni Bulus, na zama ɗan kurkuku na Kiristi Yesu saboda ku Al’ummai. ");
INSERT INTO hausa_vpl VALUES ("EP3_2","079_3_2","EPH","3","2","2","Na tabbata kun ji labarin hidimar alheri na musamman da Allah ya ba ni dominku. ");
INSERT INTO hausa_vpl VALUES ("EP3_3","079_3_3","EPH","3","3","3","Wannan wasiƙa za tă faɗa muku kaɗan game da yadda Allah ya bayyana mini shirinsa na asiri. ");
INSERT INTO hausa_vpl VALUES ("EP3_4","079_3_4","EPH","3","4","4","A yayinda kuke karanta wannan, za ku gane abin da na sani game da wannan shirin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("EP3_5","079_3_5","EPH","3","5","5","Ba a sanar da wannan asiri wa wani a sauran zamanai ba, amma a yanzu an bayyana shi ta wurin Ruhu Mai Tsarki ga manzanninsa da annabawansa. ");
INSERT INTO hausa_vpl VALUES ("EP3_6","079_3_6","EPH","3","6","6","Asirin nan kuwa shi ne cewa ta wurin bishara, Al’ummai sun zama waɗanda za su yi gādo tare da Isra’ila, sun zama gaɓoɓin jiki ɗaya, abokan tarayya kuma ga alkawaran nan a cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("EP3_7","079_3_7","EPH","3","7","7","Na zama bawan wannan bishara ta wurin baiwar alherin Allah da aka yi mini ta wurin ikonsa da yake aiki a cikina. ");
INSERT INTO hausa_vpl VALUES ("EP3_8","079_3_8","EPH","3","8","8","Ko da yake ni ba kome ba ne a cikin dukan mutanen Ubangiji, aka ba ni wannan baiwa mai daraja don in faɗa wa Al’ummai cewa saboda Kiristi akwai albarkun da suka wuce gaban misali. ");
INSERT INTO hausa_vpl VALUES ("EP3_9","079_3_9","EPH","3","9","9","An zaɓe ni in bayyana wa dukan mutane shirin asirin nan wanda Allah, mahaliccin kome, ya ɓoye shekara da shekaru. ");
INSERT INTO hausa_vpl VALUES ("EP3_10","079_3_10","EPH","3","10","10","Nufinsa shi ne, yanzu, ta wurin ikkilisiya, a sanar da hikima iri dabam-dabam na Allah ga masu mulki, da masu iko a samaniya. ");
INSERT INTO hausa_vpl VALUES ("EP3_11","079_3_11","EPH","3","11","11","Wannan shi ne madawwamin shirinsa, kuma an aikata shi ta wurin Kiristi Yesu Ubangijinmu. ");
INSERT INTO hausa_vpl VALUES ("EP3_12","079_3_12","EPH","3","12","12","A cikinsa, kuma ta wurin bangaskiya a cikinsa ne muke da ƙarfin halin zuwa kusa da Allah gabagadi. ");
INSERT INTO hausa_vpl VALUES ("EP3_13","079_3_13","EPH","3","13","13","Don haka, ina roƙonku kada ku fid da zuciya saboda abin da ake yi mini a nan. Ai, saboda ku ne nake shan wahalolin nan, wannan kuwa ɗaukakarku ce. ");
INSERT INTO hausa_vpl VALUES ("EP3_14","079_3_14","EPH","3","14","14","Saboda wannan ne nake a durƙushe a gaban Uba, ");
INSERT INTO hausa_vpl VALUES ("EP3_15","079_3_15","EPH","3","15","15","wanda ya ba wa kowane iyali a sama da ƙasa suna. ");
INSERT INTO hausa_vpl VALUES ("EP3_16","079_3_16","EPH","3","16","16","Ina addu’a cewa daga yalwar ɗaukakarsa zai ƙarfafa ku da iko daga ciki ta wurin Ruhunsa. ");
INSERT INTO hausa_vpl VALUES ("EP3_17","079_3_17","EPH","3","17","17","Ina addu’a domin Kiristi yă zauna a cikin zukatanku ta wurin bangaskiya. Ina kuma addu’a saboda ku da kuka kahu sosai cikin ƙauna, ");
INSERT INTO hausa_vpl VALUES ("EP3_18","079_3_18","EPH","3","18","18","don ku sami iko, tare da dukan tsarkaka, ku fahimci fāɗi, tsawo, da kuma zurfin ƙaunar Kiristi take. ");
INSERT INTO hausa_vpl VALUES ("EP3_19","079_3_19","EPH","3","19","19","Ku kuma san wannan ƙauna wadda ta fi gaban sani, domin a cika ku da dukan cikar Allah. ");
INSERT INTO hausa_vpl VALUES ("EP3_20","079_3_20","EPH","3","20","20","Bari ɗaukaka ta tabbata a gare shi shi wanda yake da ikon yin aiki a cikinmu, yana kuma aikata abubuwa fiye da dukan abin da muke roƙo, ko muke tunani. ");
INSERT INTO hausa_vpl VALUES ("EP3_21","079_3_21","EPH","3","21","21","Bari ɗaukaka ta tabbata a gare shi a cikin ikkilisiya da kuma a cikin Kiristi Yesu, har yă zuwa dukan zamanai, har abada abadin! Amin. ");
INSERT INTO hausa_vpl VALUES ("EP4_1","079_4_1","EPH","4","1","1","A matsayina na ɗan kurkuku saboda Ubangiji, ina roƙonku ku yi rayuwar da ta dace da kiran da aka yi muku. ");
INSERT INTO hausa_vpl VALUES ("EP4_2","079_4_2","EPH","4","2","2","Kullum ku kasance masu sauƙinkai da kuma hankali; ku zama masu haƙuri, kuna jimrewa da juna cikin ƙauna. ");
INSERT INTO hausa_vpl VALUES ("EP4_3","079_4_3","EPH","4","3","3","Ku yi ƙoƙari sosai ku kiyaye zaman ɗayan nan da Ruhu ya ba ku, ku yi haka ta wurin zaman lafiya da juna. ");
INSERT INTO hausa_vpl VALUES ("EP4_4","079_4_4","EPH","4","4","4","Dukanku jiki ɗaya ne, kuna kuma da Ruhu guda. An ba ku bege guda sa’ad da aka kira ku. ");
INSERT INTO hausa_vpl VALUES ("EP4_5","079_4_5","EPH","4","5","5","Ubangiji ɗaya, bangaskiya ɗaya, baftisma kuma ɗaya, ");
INSERT INTO hausa_vpl VALUES ("EP4_6","079_4_6","EPH","4","6","6","Allah ɗaya Uban duka, wanda yake a bisa duka, ta wurin duka, a cikin duka kuma. ");
INSERT INTO hausa_vpl VALUES ("EP4_7","079_4_7","EPH","4","7","7","Amma ga kowannenmu an ba da alheri bisa ga yadda Kiristi ya rarraba. ");
INSERT INTO hausa_vpl VALUES ("EP4_8","079_4_8","EPH","4","8","8","Shi ya sa aka ce, “Sa’ad da ya hau sama, ya bi da kamammu kamar tawagarsa ya kuma ba da baye-baye ga mutane.” ");
INSERT INTO hausa_vpl VALUES ("EP4_9","079_4_9","EPH","4","9","9","(Me ake nufin da “ya hau,” in ba cewa dā ya sauka can ƙarƙashin ƙasa ba? ");
INSERT INTO hausa_vpl VALUES ("EP4_10","079_4_10","EPH","4","10","10","Shi wannan da ya sauka ɗin, shi ne kuma ya hau zuwa can sama, kai, gaba da sammai, don mulkinsa yă cika duniya gaba ɗaya.) ");
INSERT INTO hausa_vpl VALUES ("EP4_11","079_4_11","EPH","4","11","11","Saboda haka Kiristi kansa ya ba wa waɗansu baiwa su zama manzanni, waɗansu su zama annabawa, waɗansu su zama masu wa’azi, waɗansu kuma su zama fastoci, da kuma malamai. ");
INSERT INTO hausa_vpl VALUES ("EP4_12","079_4_12","EPH","4","12","12","Ya yi haka don yă shirya mutanensa saboda ayyukan hidima, don a gina jikin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("EP4_13","079_4_13","EPH","4","13","13","Wannan zai ci gaba har sai mun zama ɗaya a cikin bangaskiya da kuma ta wurin fahimtarmu na Ɗan Allah. Sa’an nan za mu zama balagaggu, kamar yadda Kiristi yake, mu kuma zama gaba ɗaya cikakku kamar sa. ");
INSERT INTO hausa_vpl VALUES ("EP4_14","079_4_14","EPH","4","14","14","An yi wannan kuwa don kada mu koma zama kamar yara, muna ta canja zukatanmu game da abin da muka gaskata don kawai wani ya faɗa mana wani abu dabam, ko domin wani ya yi wayo ya ruɗe mu, ya sa ƙarya ta zama kamar gaskiya. ");
INSERT INTO hausa_vpl VALUES ("EP4_15","079_4_15","EPH","4","15","15","Ya kamata kullum ƙauna tă sa mu faɗa gaskiya. Ta haka za mu yi girma a kowace hanya, mu kuma zama kamar Kiristi, wanda yake kan ");
INSERT INTO hausa_vpl VALUES ("EP4_16","079_4_16","EPH","4","16","16","dukan jiki. Shi ne ya haɗe jiki duka, ya kuma sa dukan gaɓoɓin jiki suna aiki daidai, yayinda kowace gaɓa take aikinta cikin ƙauna. ");
INSERT INTO hausa_vpl VALUES ("EP4_17","079_4_17","EPH","4","17","17","To, ina dai faɗa muku, ina kuma nace faɗa muku a cikin Ubangiji, cewa kada ku ci gaba da yin rayuwa kamar yadda Al’ummai suke yi, masu banzan tunani. ");
INSERT INTO hausa_vpl VALUES ("EP4_18","079_4_18","EPH","4","18","18","Suna a cikin duhu a fahimtarsu, kuma a rabe suke daga ran Allah saboda jahilcin da yake cikinsu ta dalilin taurarewar zukatansu. ");
INSERT INTO hausa_vpl VALUES ("EP4_19","079_4_19","EPH","4","19","19","Ba sa damu da wani abu ko mai kyau ko marar kyau. Rayukansu sun cika da kowace irin ƙazanta da haɗama. ");
INSERT INTO hausa_vpl VALUES ("EP4_20","079_4_20","EPH","4","20","20","Amma ba abin da aka koya muku ke nan ba sa’ad da kuka zo ga sanin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("EP4_21","079_4_21","EPH","4","21","21","Da yake kun ji duka game da shi, kuka kuma koyi gaskiyar da take cikin Yesu, ");
INSERT INTO hausa_vpl VALUES ("EP4_22","079_4_22","EPH","4","22","22","sai ku tuɓe tsohon mutumin nan naku da kuma rayuwarku ta dā, wadda take lalacewa saboda sha’awace-sha’awacen da suke ruɗe ku. ");
INSERT INTO hausa_vpl VALUES ("EP4_23","079_4_23","EPH","4","23","23","A maimakon haka, bari Ruhu yă sabunta tunaninku da kuma halayenku. ");
INSERT INTO hausa_vpl VALUES ("EP4_24","079_4_24","EPH","4","24","24","Ku sanya sabon halin nan da aka halitta bisa ga kamannin Allah, halin nan kuwa, yă bayyana cikin adalci, da zaman tsarki. ");
INSERT INTO hausa_vpl VALUES ("EP4_25","079_4_25","EPH","4","25","25","Saboda haka dole kowannenku yă bar yin ƙarya, yă kuma riƙa faɗa wa maƙwabcinsa gaskiya, gama dukanmu gaɓoɓi jiki ɗaya ne. ");
INSERT INTO hausa_vpl VALUES ("EP4_26","079_4_26","EPH","4","26","26","“Cikin fushinku kada ku yi zunubi.” Kada ku bar rana ta fāɗi kuna fushi, ");
INSERT INTO hausa_vpl VALUES ("EP4_27","079_4_27","EPH","4","27","27","kada kuma ku ba wa Iblis dama. ");
INSERT INTO hausa_vpl VALUES ("EP4_28","079_4_28","EPH","4","28","28","Duk wanda yake sata, sai yă daina sata, dole kuma yă yi aiki, yă yi wani abu mai amfani da hannuwansa, don yă sami abin da zai iya raba da masu bukata. ");
INSERT INTO hausa_vpl VALUES ("EP4_29","079_4_29","EPH","4","29","29","Kada wata ƙazamar magana ta fita daga bakunanku, sai dai abin da yake da amfani don gina waɗansu bisa ga bukatunsu. Ta haka maganarku za tă zama da amfani ga masu jinta. ");
INSERT INTO hausa_vpl VALUES ("EP4_30","079_4_30","EPH","4","30","30","Kada kuma ku ɓata wa Ruhu Mai Tsarki na Allah rai, wanda da shi aka hatimce ku da shi don ranar fansa. ");
INSERT INTO hausa_vpl VALUES ("EP4_31","079_4_31","EPH","4","31","31","Ku rabu da kowane irin ɗacin rai, haushi da hasala, faɗa da ɓata suna, ku rabu da kowace irin ƙeta. ");
INSERT INTO hausa_vpl VALUES ("EP4_32","079_4_32","EPH","4","32","32","Ku yi alheri, ku kuma ji tausayin juna, kuna gafarta wa juna, kamar yadda a cikin Kiristi, Allah ya gafarta muku. ");
INSERT INTO hausa_vpl VALUES ("EP5_1","079_5_1","EPH","5","1","1","Ku zama masu koyi da Allah, kamar ƙaunatattun ’ya’ya, ");
INSERT INTO hausa_vpl VALUES ("EP5_2","079_5_2","EPH","5","2","2","ku kuma yi rayuwar ƙauna, kamar yadda Kiristi ya ƙaunace mu, har ya ba da kansa dominmu a matsayin sadaka mai ƙanshi da kuma hadaya ga Allah. ");
INSERT INTO hausa_vpl VALUES ("EP5_3","079_5_3","EPH","5","3","3","Kada a ma ambaci fasikanci, da kowane irin aikin lalata, ko kwaɗayi a tsakaninku, domin bai dace da mutane masu tsarki na Allah ba. ");
INSERT INTO hausa_vpl VALUES ("EP5_4","079_5_4","EPH","5","4","4","Haka ma bai kamata a sami datti, ƙazamar magana, ko zancen banza a cikinku ba, domin ba su dace ba, a maimakon haka sai ku yi ta yin godiya. ");
INSERT INTO hausa_vpl VALUES ("EP5_5","079_5_5","EPH","5","5","5","Ku dai tabbata, ba wani mai fasikanci, ko mai aikin lalata, ko mai kwaɗayin (wanda shi da mai bautar gumaka ɗaya ne), da yake da gādo a mulkin Kiristi da na Allah. ");
INSERT INTO hausa_vpl VALUES ("EP5_6","079_5_6","EPH","5","6","6","Kada wani yă ruɗe ku da kalmomin wofi, gama saboda waɗannan abubuwa ne fushin Allah yake zuwa a kan marasa biyayya. ");
INSERT INTO hausa_vpl VALUES ("EP5_7","079_5_7","EPH","5","7","7","Saboda haka kada ku haɗa kai da su. ");
INSERT INTO hausa_vpl VALUES ("EP5_8","079_5_8","EPH","5","8","8","Gama a dā zukatanku sun cika da duhu, amma yanzu ku haske ne a cikin Ubangiji. Ku yi rayuwa kamar ’ya’yan haske ");
INSERT INTO hausa_vpl VALUES ("EP5_9","079_5_9","EPH","5","9","9","(domin amfanin haske ya ƙunshi nagarta, adalci, da kuma gaskiya) ");
INSERT INTO hausa_vpl VALUES ("EP5_10","079_5_10","EPH","5","10","10","ku nemi abin da zai gamshi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EP5_11","079_5_11","EPH","5","11","11","Ku yi nesa da ayyukan duhun da mutane suke yi, a maimakon haka, ku tona su. ");
INSERT INTO hausa_vpl VALUES ("EP5_12","079_5_12","EPH","5","12","12","Gama abin kunya ne a ma faɗi abubuwan da marasa biyayya suke yi a ɓoye. ");
INSERT INTO hausa_vpl VALUES ("EP5_13","079_5_13","EPH","5","13","13","Duk abin da aka kawo a gaban haske ana iya ganinsa, kuma duk abin da aka haskaka yakan zama haske. ");
INSERT INTO hausa_vpl VALUES ("EP5_14","079_5_14","EPH","5","14","14","Shi ya sa aka ce, “Ka farka, ya kai mai barci, ka tashi daga matattu, Kiristi kuwa zai haskaka ka.” ");
INSERT INTO hausa_vpl VALUES ("EP5_15","079_5_15","EPH","5","15","15","Sai ku yi hankali sosai da yadda kuke rayuwa, kada ku zama kamar marasa hikima, sai dai kamar masu hikima. ");
INSERT INTO hausa_vpl VALUES ("EP5_16","079_5_16","EPH","5","16","16","Ku kuma yi matuƙar amfani da kowane zarafi, don kwanakin nan mugaye ne. ");
INSERT INTO hausa_vpl VALUES ("EP5_17","079_5_17","EPH","5","17","17","Saboda haka kada ku zama wawaye, sai dai ku fahimci ko mene ne nufin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EP5_18","079_5_18","EPH","5","18","18","Kada ku bugu da ruwan inabi, wanda yake kai ga lalaci. A maimako haka, ku cika da Ruhu. ");
INSERT INTO hausa_vpl VALUES ("EP5_19","079_5_19","EPH","5","19","19","Ku yi zance da juna cikin zabura, da waƙoƙi, da kuma waƙoƙin ruhaniya. Ku rera, ku kuma yi kiɗe-kiɗe a zuciyarku ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EP5_20","079_5_20","EPH","5","20","20","Kullum ku dinga yin amfani da sunan Ubangijinmu Yesu Kiristi, kuna gode wa Allah Uba a kome. ");
INSERT INTO hausa_vpl VALUES ("EP5_21","079_5_21","EPH","5","21","21","Ku yi biyayya da juna saboda bangirmar da kuke nuna wa Kiristi. ");
INSERT INTO hausa_vpl VALUES ("EP5_22","079_5_22","EPH","5","22","22","Matan aure, ku yi biyayya ga mazanku, kamar ga Ubangiji ne kuke yi. ");
INSERT INTO hausa_vpl VALUES ("EP5_23","079_5_23","EPH","5","23","23","Gama miji shi ne kan mace, yadda Kiristi yake kai da kuma Mai Ceton ikkilisiya, wadda take jikinsa. ");
INSERT INTO hausa_vpl VALUES ("EP5_24","079_5_24","EPH","5","24","24","To, kamar yadda ikkilisiya take biyayya ga Kiristi, haka ma ya kamata mata su yi biyayya ga mazansu cikin kome. ");
INSERT INTO hausa_vpl VALUES ("EP5_25","079_5_25","EPH","5","25","25","Maza, ku ƙaunaci matanku, kamar yadda Kiristi ya ƙaunaci ikkilisiya, ya kuma ba da kansa dominta. ");
INSERT INTO hausa_vpl VALUES ("EP5_26","079_5_26","EPH","5","26","26","Ya mai da ikkilisiya ta zama mai tsarki ta wurin ikon maganarsa, ya kuma tsabtacce ta ta wurin wanke ta da ruwa. ");
INSERT INTO hausa_vpl VALUES ("EP5_27","079_5_27","EPH","5","27","27","Kiristi ya yi haka don yă miƙa wa kansa ikkilisiya mai ɗaukaka da kuma mai tsarki, marar aibi, marar tabo, da kuma marar lahani. ");
INSERT INTO hausa_vpl VALUES ("EP5_28","079_5_28","EPH","5","28","28","Don haka, dole maza su ƙaunaci matansu kamar yadda suke ƙaunar jikunansu. Wanda yake ƙaunar matarsa, yana ƙaunar kansa ne. ");
INSERT INTO hausa_vpl VALUES ("EP5_29","079_5_29","EPH","5","29","29","Gama ba wanda ya taɓa ƙin jikinsa, sai dai yă ciyar da shi, yă kuma kula da shi, kamar yadda Kiristi yake yi wa ikkilisiya, ");
INSERT INTO hausa_vpl VALUES ("EP5_30","079_5_30","EPH","5","30","30","gama mu gaɓoɓin jikinsa ne. ");
INSERT INTO hausa_vpl VALUES ("EP5_31","079_5_31","EPH","5","31","31","“Saboda haka mutum yakan bar mahaifinsa da mahaifiyarsa, yă manne wa matarsa, su biyun su zama jiki ɗaya.” ");
INSERT INTO hausa_vpl VALUES ("EP5_32","079_5_32","EPH","5","32","32","Wannan babban asiri ne, amma na ɗauke shi a matsayin kwatanci ne na Kiristi da ikkilisiya. ");
INSERT INTO hausa_vpl VALUES ("EP5_33","079_5_33","EPH","5","33","33","Duk da haka, dole kowannenku yă ƙaunaci matarsa kamar yadda yake ƙaunar kansa, kuma dole matar tă yi biyayya ga mijinta. ");
INSERT INTO hausa_vpl VALUES ("EP6_1","079_6_1","EPH","6","1","1","Ku ’ya’ya, ku yi biyayya ga iyayenku, gama ku na Ubangiji, abin da ya dace ku yi ke nan. ");
INSERT INTO hausa_vpl VALUES ("EP6_2","079_6_2","EPH","6","2","2","Doka ta farko wadda aka haɗa da alkawari ita ce, “Ka girmama mahaifinka da mahaifiyarka, ");
INSERT INTO hausa_vpl VALUES ("EP6_3","079_6_3","EPH","6","3","3","don ka zauna lafiya, ka kuma yi tsawon rai a duniya.” ");
INSERT INTO hausa_vpl VALUES ("EP6_4","079_6_4","EPH","6","4","4","Ku kuma iyaye, kada ku tsokane ’ya’yanku. Ku yi musu reno mai kyau. Ku koyar da su, ku kuma gargaɗe su game da Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("EP6_5","079_6_5","EPH","6","5","5","Ku bayi, ku yi biyayya ga iyayengijinku na duniya. Ku nuna musu halin bangirma, kuna kuma yin musu biyayya cikin dukan abu, da zuciya ɗaya kamar ga Kiristi kuke yi. ");
INSERT INTO hausa_vpl VALUES ("EP6_6","079_6_6","EPH","6","6","6","Ku yi aiki sosai, ba don kawai ku gamshe su sa’ad da suke kallonku ba. Da yake ku bayin Kiristi ne, ku aikata nufin Allah da dukan zuciyarku. ");
INSERT INTO hausa_vpl VALUES ("EP6_7","079_6_7","EPH","6","7","7","Ku yi aikinku da kyakkyawar niyya, sai ka ce ga Ubangiji kuke yi, ba mutane ba. ");
INSERT INTO hausa_vpl VALUES ("EP6_8","079_6_8","EPH","6","8","8","Gama kun san cewa Ubangiji zai ba da lada ga kowa gwargwadon kowane aiki nagarin da ya yi, ko shi bawa ne, ko ’yantacce. ");
INSERT INTO hausa_vpl VALUES ("EP6_9","079_6_9","EPH","6","9","9","Ku kuma masu bayi, dole ku bi da bayinku da kyau. Ku daina ba su tsoro. Ku tuna, ku da su, Maigida ɗaya kuke da shi a sama, kuma ba ya nuna bambanci. ");
INSERT INTO hausa_vpl VALUES ("EP6_10","079_6_10","EPH","6","10","10","A ƙarshe, bari ƙarfin ikon Ubangiji yă ba ku ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("EP6_11","079_6_11","EPH","6","11","11","Ku yafa dukan kayan yaƙin da Allah yake bayarwa, don ku iya kāre kanku daga dabarun Shaiɗan. ");
INSERT INTO hausa_vpl VALUES ("EP6_12","079_6_12","EPH","6","12","12","Gama ba da mutane da suke nama da jini ne muke yaƙi ba. Muna yaƙi ne da ikoki, da hukumomi, da masu mulkin duhu, da kuma a ikokin da suke cikin a sararin sama. ");
INSERT INTO hausa_vpl VALUES ("EP6_13","079_6_13","EPH","6","13","13","Saboda haka sai ku yafa dukan kayan yaƙi na Allah, domin sa’ad da ranar mugun nan ta zo, ku iya yin tsayin daka, bayan kuma kuka gama kome, ku dāge. ");
INSERT INTO hausa_vpl VALUES ("EP6_14","079_6_14","EPH","6","14","14","Saboda haka fa ku dāge, ku sa gaskiya tă zama ɗamararku, adalci yă zama sulkenku, ");
INSERT INTO hausa_vpl VALUES ("EP6_15","079_6_15","EPH","6","15","15","shirin kai bisharar salama yă zama kamar takalmi a ƙafafunku. ");
INSERT INTO hausa_vpl VALUES ("EP6_16","079_6_16","EPH","6","16","16","Ban da waɗannan kuma, ku ɗauki garkuwar bangaskiya, wadda za ku iya kashe dukan kibiyoyin wutar Mugun nan da ita. ");
INSERT INTO hausa_vpl VALUES ("EP6_17","079_6_17","EPH","6","17","17","Ku kuma ɗauki hular kwano na ceto, da takobin Ruhu, wato, Maganar Allah. ");
INSERT INTO hausa_vpl VALUES ("EP6_18","079_6_18","EPH","6","18","18","A koyaushe ku kasance kuna addu’a da roƙo ta wurin ikon Ruhu ba fasawa. A kan wannan manufa ku zauna a faɗake da matuƙar naci, kuna yin wa dukan mutanen Ubangiji addu’a. ");
INSERT INTO hausa_vpl VALUES ("EP6_19","079_6_19","EPH","6","19","19","Ku kuma yi addu’a domina, don duk sa’ad da na buɗe bakina, in sami kalmomi babu tsoro, don in sanar da asirin bishara, ");
INSERT INTO hausa_vpl VALUES ("EP6_20","079_6_20","EPH","6","20","20","wadda nake jakadanta cikin sarƙoƙi. Ku yi addu’a don in iya yin shelarta babu tsoro, yadda ya kamata in yi. ");
INSERT INTO hausa_vpl VALUES ("EP6_21","079_6_21","EPH","6","21","21","Tikikus, ƙaunataccen ɗan’uwa da kuma amintaccen bawa cikin Ubangiji, zai faɗa muku kome, domin ku ma ku san yadda nake, da kuma abin da nake yi. ");
INSERT INTO hausa_vpl VALUES ("EP6_22","079_6_22","EPH","6","22","22","Na aike shi gare ku musamman don wannan, domin ku san yadda muke, yă kuma ƙarfafa ku. ");
INSERT INTO hausa_vpl VALUES ("EP6_23","079_6_23","EPH","6","23","23","’Yan’uwa, salama tare da ƙauna da kuma bangaskiya daga Allah Uba da Ubangiji Yesu Kiristi su kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("EP6_24","079_6_24","EPH","6","24","24","Alheri yă tabbata ga dukan masu ƙaunar Ubangiji Yesu Kiristi da ƙauna marar ƙarewa.");
INSERT INTO hausa_vpl VALUES ("PP1_1","080_1_1","PHP","1","1","1","Bulus da Timoti, bayin Kiristi Yesu, Zuwa ga dukan tsarkaka cikin Kiristi Yesu a Filibbi, tare da masu kula da Ikkilisiya da kuma masu hidima. ");
INSERT INTO hausa_vpl VALUES ("PP1_2","080_1_2","PHP","1","2","2","Alheri da salama daga Allah Ubanmu da kuma Ubangiji Yesu Kiristi, su kasance tare ku. ");
INSERT INTO hausa_vpl VALUES ("PP1_3","080_1_3","PHP","1","3","3","Ina gode wa Allahna a kowane lokacin da na tuna da ku. ");
INSERT INTO hausa_vpl VALUES ("PP1_4","080_1_4","PHP","1","4","4","A cikin dukan addu’o’ina dominku duka, nakan yi addu’a da farin ciki kullum ");
INSERT INTO hausa_vpl VALUES ("PP1_5","080_1_5","PHP","1","5","5","saboda tarayyarku a cikin bishara daga ranar farko har yă zuwa yanzu, ");
INSERT INTO hausa_vpl VALUES ("PP1_6","080_1_6","PHP","1","6","6","da tabbacin cewa wanda ya fara kyakkyawan aikin nan a cikinku, zai kai shi ga kammalawa har yă zuwa ranar Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("PP1_7","080_1_7","PHP","1","7","7","Daidai ne in yi wannan tunani game da dukanku, da yake kuna a zuciyata; domin ko ina daure cikin sarƙoƙi ko ina kāre bishara ina kuma tabbatar da ita, dukanku kuna tarayya cikin alherin Allah tare da ni. ");
INSERT INTO hausa_vpl VALUES ("PP1_8","080_1_8","PHP","1","8","8","Allah shi ne shaidata, ya san yadda nake ƙaunarku duka da ƙaunar Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("PP1_9","080_1_9","PHP","1","9","9","Addu’ata ita ce ƙaunarku tă yi ta cin gaba da ƙaruwa cikin sani da kuma zurfin ganewa, ");
INSERT INTO hausa_vpl VALUES ("PP1_10","080_1_10","PHP","1","10","10","don ku iya rarrabe abin da yake mafi kyau, ku kuma zama da tsarki, marasa aibi har yă zuwa ranar Kiristi, ");
INSERT INTO hausa_vpl VALUES ("PP1_11","080_1_11","PHP","1","11","11","cikakku da sakamakon aikin adalci da yake zuwa ta wurin Yesu Kiristi, zuwa ga ɗaukakar Allah da kuma yabonsa. ");
INSERT INTO hausa_vpl VALUES ("PP1_12","080_1_12","PHP","1","12","12","To, ina so ku sani ’yan’uwa, cewa abin da ya faru da ni ya sa cin gaban bishara. ");
INSERT INTO hausa_vpl VALUES ("PP1_13","080_1_13","PHP","1","13","13","Ta haka, ya zama sananne ga dukan masu gadin fada da kuma ga kowa cewa an daure ni da sarƙoƙi saboda Kiristi. ");
INSERT INTO hausa_vpl VALUES ("PP1_14","080_1_14","PHP","1","14","14","Saboda sarƙoƙina, yawancin ’yan’uwa cikin Ubangiji sun sami ƙarfafawa su yi maganar Allah gabagadi da kuma babu tsoro. ");
INSERT INTO hausa_vpl VALUES ("PP1_15","080_1_15","PHP","1","15","15","Gaskiya ce cewa waɗansu suna yin wa’azin Kiristi saboda kishi da neman faɗa, amma waɗansu da nufi mai kyau suke yi. ");
INSERT INTO hausa_vpl VALUES ("PP1_16","080_1_16","PHP","1","16","16","Na biye suna yin haka cikin ƙauna, da sanin cewa an sa ni a nan ne domin kāriyar bishara. ");
INSERT INTO hausa_vpl VALUES ("PP1_17","080_1_17","PHP","1","17","17","Na farin dai suna wa’azin Kiristi da sonkai ne, ba da zuciya ɗaya ba, a sonsu, su wahalar da ni a cikin sarƙoƙi. ");
INSERT INTO hausa_vpl VALUES ("PP1_18","080_1_18","PHP","1","18","18","Me kuma? Ta ko yaya dai, ko da gangan, ko da gaske, ana shelar Kiristi. Domin wannan kuwa ina farin ciki. I, zan kuwa ci gaba da farin ciki, ");
INSERT INTO hausa_vpl VALUES ("PP1_19","080_1_19","PHP","1","19","19","gama na san cewa ta wurin addu’o’inku da kuma taimako daga Ruhun Yesu Kiristi, abin da ya same ni zai zama sanadin kuɓutata. ");
INSERT INTO hausa_vpl VALUES ("PP1_20","080_1_20","PHP","1","20","20","Ina saurara da marmari da kuma bege cewa ba zan taɓa shan kunya ba, sai dai zan sami issashen ƙarfin hali yanzu kamar kullum, za a ɗaukaka Kiristi a jikina, ko ta wurin rayuwa ko kuma ta wurin mutuwa. ");
INSERT INTO hausa_vpl VALUES ("PP1_21","080_1_21","PHP","1","21","21","Gama a gare ni, rai Kiristi ne, mutuwa kuma riba ce. ");
INSERT INTO hausa_vpl VALUES ("PP1_22","080_1_22","PHP","1","22","22","In zan ci gaba da rayuwa a cikin jiki, wannan zai zama aiki mai amfani a gare ni. Duk da haka me zan zaɓa? Ban sani ba! ");
INSERT INTO hausa_vpl VALUES ("PP1_23","080_1_23","PHP","1","23","23","Na rasa wanda zan zaɓa cikin biyun nan. Ina sha’awa in yi ƙaura in zauna tare da Kiristi, wannan kuwa ya fi kyau nesa ba kusa ba; ");
INSERT INTO hausa_vpl VALUES ("PP1_24","080_1_24","PHP","1","24","24","amma ya fi muku muhimmanci in rayu cikin jiki. ");
INSERT INTO hausa_vpl VALUES ("PP1_25","080_1_25","PHP","1","25","25","Na tabbata haka ne, na kuwa san zan wanzu in zauna tare da ku duka, domin ku ci gaba, bangaskiyarku tana sa ku farin ciki, ");
INSERT INTO hausa_vpl VALUES ("PP1_26","080_1_26","PHP","1","26","26","domin ta wurin kasancewata tare da ku, farin cikinku cikin Kiristi Yesu zai cika sosai ta dalilina. ");
INSERT INTO hausa_vpl VALUES ("PP1_27","080_1_27","PHP","1","27","27","Kome ya faru, ku yi zaman da ya cancanci bisharar Kiristi. Ta haka, ko na zo na gan ku, ko ban zo ba, in ji labari cewa kun tsaya da ƙarfi a cikin ruhu ɗaya, kuna fama kamar mutum ɗaya saboda bangaskiyar bishara ");
INSERT INTO hausa_vpl VALUES ("PP1_28","080_1_28","PHP","1","28","28","ba tare da kun ji tsoron waɗanda suke gāba da ku ta kowace hanya ba. Wannan alama ce a gare su cewa za a hallaka su, amma a gare ku za a cece ku, wannan tabbacin kuwa daga wurin Allah ne. ");
INSERT INTO hausa_vpl VALUES ("PP1_29","080_1_29","PHP","1","29","29","Gama an ba ku zarafi a madadin Kiristi cewa ba gaskatawa da shi kaɗai ba kuka yi ba, har ma ku sha wahala dominsa, ");
INSERT INTO hausa_vpl VALUES ("PP1_30","080_1_30","PHP","1","30","30","da yake kuna shan faman da kuka gan na sha, kuna kuma jin cewa har yanzu ina sha. ");
INSERT INTO hausa_vpl VALUES ("PP2_1","080_2_1","PHP","2","1","1","In kuna da wata ƙarfafawa daga tarayya da Kiristi, in da wata ta’aziyya daga ƙaunarsa, in da wani zumunci da Ruhu, in da juyayi da tausayi, ");
INSERT INTO hausa_vpl VALUES ("PP2_2","080_2_2","PHP","2","2","2","to, sai ku sa farin cikina yă zama cikakke ta wurin kasance da hali ɗaya, kuna ƙauna ɗaya, kuna zama ɗaya cikin ruhu da kuma manufa. ");
INSERT INTO hausa_vpl VALUES ("PP2_3","080_2_3","PHP","2","3","3","Kada ku yi kome da sonkai ko girman kai, sai dai cikin tawali’u, ku ɗauki waɗansu sun fi ku. ");
INSERT INTO hausa_vpl VALUES ("PP2_4","080_2_4","PHP","2","4","4","Bai kamata kowannenku yă kula da sha’anin kansa kawai ba, sai dai yă kula da sha’anin waɗansu ma. ");
INSERT INTO hausa_vpl VALUES ("PP2_5","080_2_5","PHP","2","5","5","A cikin dangantakarku da juna, ya kamata halayenku su zama kamar na Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("PP2_6","080_2_6","PHP","2","6","6","Wanda, ko da yake cikin ainihin surar Allah yake, bai mai da daidaitakansa nan da Allah wani abin riƙewa kam-kam ba, ");
INSERT INTO hausa_vpl VALUES ("PP2_7","080_2_7","PHP","2","7","7","amma ya mai da kansa ba kome ba, yana ɗaukan ainihin surar bawa, aka yi shi cikin siffar mutum. ");
INSERT INTO hausa_vpl VALUES ("PP2_8","080_2_8","PHP","2","8","8","Aka kuma same shi a kamannin mutum, ya ƙasƙantar da kansa ya kuma zama mai biyayya wadda ta kai shi har mutuwa, mutuwar ma ta gicciye! ");
INSERT INTO hausa_vpl VALUES ("PP2_9","080_2_9","PHP","2","9","9","Saboda haka Allah ya ɗaukaka shi zuwa mafificin wuri ya kuma ba shi sunan da ya fi dukan sunaye, ");
INSERT INTO hausa_vpl VALUES ("PP2_10","080_2_10","PHP","2","10","10","don a sunan Yesu kowace gwiwa za tă durƙusa, a sama da a ƙasa da kuma a ƙarƙashin ƙasa, ");
INSERT INTO hausa_vpl VALUES ("PP2_11","080_2_11","PHP","2","11","11","kowane harshe kuma yă furta cewa Yesu Kiristi Ubangiji ne, don ɗaukakar Allah Uba. ");
INSERT INTO hausa_vpl VALUES ("PP2_12","080_2_12","PHP","2","12","12","Saboda haka, ya abokaina ƙaunatattu, kamar yadda kullum kuke biyayya ba kawai sa’ad da ina nan ba, amma yanzu da ba na nan tare da ku, ku ci gaba da yin ayyukan cetonku da tsoro da kuma rawan jiki, ");
INSERT INTO hausa_vpl VALUES ("PP2_13","080_2_13","PHP","2","13","13","gama Allah ne yake aiki a cikinku, don ku nufa ku kuma aikata bisa ga nufinsa mai kyau. ");
INSERT INTO hausa_vpl VALUES ("PP2_14","080_2_14","PHP","2","14","14","Ku yi kome ba tare da gunaguni ko gardama ba, ");
INSERT INTO hausa_vpl VALUES ("PP2_15","080_2_15","PHP","2","15","15","don ku zama marasa abin zargi, sahihai ’ya’yan Allah, waɗanda ba su da laifi, a zamanin mutane karkatattu, kangararru, waɗanda kuke haskakawa a cikinsu kamar fitilu a duniya ");
INSERT INTO hausa_vpl VALUES ("PP2_16","080_2_16","PHP","2","16","16","kuna kuwa cin gaba da riƙe maganar rai domin in yi taƙama a ranar Kiristi cewa ban yi gudu ko fama a banza ba. ");
INSERT INTO hausa_vpl VALUES ("PP2_17","080_2_17","PHP","2","17","17","Amma ko da ana tsiyaye jinina kamar hadaya ta sha a kan hadaya da kuma hidimar da take fitowa daga bangaskiyarku, ina murna ina kuma farin ciki da ku duka. ");
INSERT INTO hausa_vpl VALUES ("PP2_18","080_2_18","PHP","2","18","18","Haka ma ya kamata ku yi murna ku kuma yi farin ciki tare da ni. ");
INSERT INTO hausa_vpl VALUES ("PP2_19","080_2_19","PHP","2","19","19","Ina sa rai a cikin Ubangiji Yesu cewa zan aika da Timoti zuwa gare ku ba da daɗewa ba, don ni ma in ji daɗi sa’ad da na ji labarinku. ");
INSERT INTO hausa_vpl VALUES ("PP2_20","080_2_20","PHP","2","20","20","Ba ni da wani kamar sa, wanda yake da ainihin sha’awa a zaman lafiyarku. ");
INSERT INTO hausa_vpl VALUES ("PP2_21","080_2_21","PHP","2","21","21","Gama kowa yana lura da al’amuran kansa ne kawai, ba na Kiristi Yesu ba. ");
INSERT INTO hausa_vpl VALUES ("PP2_22","080_2_22","PHP","2","22","22","Amma, ai, kun san darajar Timoti yadda muka yi bautar bishara tare, kamar ɗa da mahaifinsa. ");
INSERT INTO hausa_vpl VALUES ("PP2_23","080_2_23","PHP","2","23","23","Saboda haka, ina sa rai, in aike shi da zarar na ga yadda abubuwa suke a nan. ");
INSERT INTO hausa_vpl VALUES ("PP2_24","080_2_24","PHP","2","24","24","Ni kuma ina da tabbaci a cikin Ubangiji cewa zan zo ba da daɗewa ba. ");
INSERT INTO hausa_vpl VALUES ("PP2_25","080_2_25","PHP","2","25","25","Amma ina gani ya dace in aika da Afaforiditus, ɗan’uwana, abokin aikina da kuma abokin famana, wanda kuma yake ɗan saƙonku, wanda kuka aika domin yă biya mini bukatuna. ");
INSERT INTO hausa_vpl VALUES ("PP2_26","080_2_26","PHP","2","26","26","Gama yana marmarin ganinku duka ya kuma damu domin kun ji cewa ya yi rashin lafiya. ");
INSERT INTO hausa_vpl VALUES ("PP2_27","080_2_27","PHP","2","27","27","Ba shakka ya yi rashin lafiya, har ya kusa mutuwa. Amma Allah ya nuna masa jinƙai, ba shi kaɗai ba amma har da ni ma, don yă rage mini baƙin ciki kan baƙin ciki. ");
INSERT INTO hausa_vpl VALUES ("PP2_28","080_2_28","PHP","2","28","28","Saboda haka na yi niyya ƙwarai in aike shi wurinku, don sa’ad da kuka sāke ganinsa za ku yi murna, ni kuma in rage damuwa. ");
INSERT INTO hausa_vpl VALUES ("PP2_29","080_2_29","PHP","2","29","29","Ku marabce shi cikin Ubangiji da farin ciki mai yawa, ku kuma girmama mutane irinsa, ");
INSERT INTO hausa_vpl VALUES ("PP2_30","080_2_30","PHP","2","30","30","domin ya kusa yă mutu saboda aikin Kiristi, ya yi kasai da ransa don yă cikasa taimakon da ba ku iya yi mini ba. ");
INSERT INTO hausa_vpl VALUES ("PP3_1","080_3_1","PHP","3","1","1","A ƙarshe, ’yan’uwana, ku yi farin ciki a cikin Ubangiji! Ba abin damuwa ba ne a gare ni in sāke rubuta muku irin waɗannan abubuwa, domin lafiyarku ne. ");
INSERT INTO hausa_vpl VALUES ("PP3_2","080_3_2","PHP","3","2","2","Ku yi hankali da waɗancan karnuka, waɗancan mutane masu aikata mugunta, waɗancan masu yankan jiki. ");
INSERT INTO hausa_vpl VALUES ("PP3_3","080_3_3","PHP","3","3","3","Gama mu ne masu kaciya, mu da muke yi sujada ta wurin Ruhun Allah, mu da muke taƙama a cikin Kiristi Yesu, mu da ba mu dogara da ayyukan da ake gani ba, ");
INSERT INTO hausa_vpl VALUES ("PP3_4","080_3_4","PHP","3","4","4","ko da yake ni kaina ina da dalilan dogara da haka. In kuwa akwai wani wanda yake tsammani yana da dalilan dogara ga jiki, ni fa na fi shi, ");
INSERT INTO hausa_vpl VALUES ("PP3_5","080_3_5","PHP","3","5","5","an yi mini kaciya a rana ta takwas, asalina Isra’ila ne, na kabilar Benyamin, mutumin Ibraniyawa ɗan Ibraniyawa; bisa ga doka kuwa ni Bafarisiye ne; ");
INSERT INTO hausa_vpl VALUES ("PP3_6","080_3_6","PHP","3","6","6","wajen himma kuwa, ni mai tsananta wa ikkilisiya ne, wajen aikin adalci bisa ga hanyar doka, ni marar laifi ne. ");
INSERT INTO hausa_vpl VALUES ("PP3_7","080_3_7","PHP","3","7","7","Amma abin da dā ya zama mini riba yanzu, na ɗauka hasara ce saboda Kiristi. ");
INSERT INTO hausa_vpl VALUES ("PP3_8","080_3_8","PHP","3","8","8","Me kuma ya fi, na ɗauki dukan abubuwa hasara ne in aka kwatanta da mafificiyar girman sanin Kiristi Yesu Ubangijina, wanda saboda shi ne na yi hasarar kome. Na mai da su kayan wofi, domin in sami Kiristi ");
INSERT INTO hausa_vpl VALUES ("PP3_9","080_3_9","PHP","3","9","9","a kuma same ni a cikinsa, ba da wani adalcin kaina wanda yake zuwa daga bin doka ba, sai dai adalcin da yake samuwa ta wurin bangaskiya a cikin Kiristi, adalcin da yake fitowa daga Allah da kuma yake zuwa ta wurin bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("PP3_10","080_3_10","PHP","3","10","10","Ina so in san Kiristi da ikon tashinsa daga matattu da kuma zumuncin tarayya cikin shan wahalarsa, in kuma zama kamar sa a cikin mutuwarsa, ");
INSERT INTO hausa_vpl VALUES ("PP3_11","080_3_11","PHP","3","11","11","yadda kuma ko ta yaya, in kai ga tashin nan daga matattu. ");
INSERT INTO hausa_vpl VALUES ("PP3_12","080_3_12","PHP","3","12","12","Ba cewa na riga na sami dukan wannan ba ne, ko kuma an riga an mai da ni cikakke ba, sai dai ina nacewa don in kai ga samun abin da Kiristi Yesu ya riƙe ni saboda shi. ");
INSERT INTO hausa_vpl VALUES ("PP3_13","080_3_13","PHP","3","13","13","’Yan’uwa, ban ɗauki kaina a kan cewa na riga na sami abin ba. Sai dai abu guda nake yi. Ina mantawa da abin da yake baya, ina kuma nacewa zuwa ga samun abin da yake gaba, ");
INSERT INTO hausa_vpl VALUES ("PP3_14","080_3_14","PHP","3","14","14","ina nacewa gaba zuwa ga manufar, don in sami ladar da Allah ya yi mini na kiran nan zuwa sama a cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("PP3_15","080_3_15","PHP","3","15","15","Dukanmu da muka balaga ya kamata mu yi wannan irin ganin abubuwa. In kuwa saboda wani dalili tunaninku ya yi dabam, Allah zai bayyana muku wannan ma. ");
INSERT INTO hausa_vpl VALUES ("PP3_16","080_3_16","PHP","3","16","16","Sai dai a duk inda muka kai, mu ci gaba da haka. ");
INSERT INTO hausa_vpl VALUES ("PP3_17","080_3_17","PHP","3","17","17","Ku haɗa kai da waɗansu cikin bin gurbina, ku kuma lura da waɗanda suke rayuwa bisa ga ƙa’idar da muka ba ku. ");
INSERT INTO hausa_vpl VALUES ("PP3_18","080_3_18","PHP","3","18","18","Gama kamar yadda na sha gaya muku yanzu kuma ina sāke gaya muku har ma da hawaye, waɗansu da yawa suna rayuwa kamar abokan gāban gicciyen Kiristi. ");
INSERT INTO hausa_vpl VALUES ("PP3_19","080_3_19","PHP","3","19","19","Ƙaddararsu hallaka ce, allahnsu cikinsu ne, rashin kunyarsu shi ne abin fahariyarsu. Hankalinsu yana kan kayan duniya. ");
INSERT INTO hausa_vpl VALUES ("PP3_20","080_3_20","PHP","3","20","20","Amma mu ’yan mulkin sama ne. Muna kuma jira zuwan Mai Ceto daga can, Ubangiji Yesu Kiristi, ");
INSERT INTO hausa_vpl VALUES ("PP3_21","080_3_21","PHP","3","21","21","shi ne mai ikon kawo dukan abubuwa ƙarƙashin mulkinsa. Ta wurin ikon nan nasa zai sāke jikin nan namu na ƙasƙanci, yă mai da shi kamar jikin nan nasa na ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("PP4_1","080_4_1","PHP","4","1","1","Saboda haka ’yan’uwana, ku da nake ƙauna, nake kuma marmarin ganinku, ku da kuke farin cikina da kuma rawanina, ku dāge ga Ubangiji, ya ku ƙaunatattuna! ");
INSERT INTO hausa_vpl VALUES ("PP4_2","080_4_2","PHP","4","2","2","Ina roƙon Yuwodiya ina kuma roƙon Sintike, su yi zaman lafiya da juna saboda su na Ubangiji ne. ");
INSERT INTO hausa_vpl VALUES ("PP4_3","080_4_3","PHP","4","3","3","I, ina kuma roƙonka, abokin famata, ka taimaki matan nan waɗanda suka yi fama aikin bishara tare da ni, haka ma Kilemen da kuma sauran abokan aikina, waɗanda sunayensu suna cikin littafin rai. ");
INSERT INTO hausa_vpl VALUES ("PP4_4","080_4_4","PHP","4","4","4","Ku yi farin ciki a cikin Ubangiji kullum. Ina sāke gaya muku ku yi farin ciki! ");
INSERT INTO hausa_vpl VALUES ("PP4_5","080_4_5","PHP","4","5","5","Bari kowa yă kasance da sauƙinkai. Ubangiji ya yi kusan zuwa. ");
INSERT INTO hausa_vpl VALUES ("PP4_6","080_4_6","PHP","4","6","6","Kada ku damu game da kome sai dai a cikin abu duka, ku gabatar da roƙe-roƙenku ga Allah ta wurin addu’a da roƙo, tare da godiya. ");
INSERT INTO hausa_vpl VALUES ("PP4_7","080_4_7","PHP","4","7","7","Salamar Allah, wadda ta wuce dukan fahimta, za tă tsai da zukatanku da tunaninku cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("PP4_8","080_4_8","PHP","4","8","8","A ƙarshe, ’yan’uwa, duk abin da yake na gaskiya, duk abin da yake na girmamawa, duk abin da yake daidai, duk abin da yake da tsarki, duk abin da yake kyakkyawa, duk abin da yake na sha’awa, in ma wani abu mafifici ne, ko ya cancanci yabo, ku yi tunani a kan irin abubuwan nan. ");
INSERT INTO hausa_vpl VALUES ("PP4_9","080_4_9","PHP","4","9","9","Duk abin da kuka koya ko kuka karɓa ko kuka ji daga wurina, ko kuka gani a cikina, ku yi aiki da shi. Allah na salama kuma zai kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("PP4_10","080_4_10","PHP","4","10","10","Na yi farin ciki sosai ga Ubangiji don yanzu kun sāke nuna kun kula da ni. Ko da yake dā ma kun kula da ni sai dai ba ku sami dama ku nuna mini ba. ");
INSERT INTO hausa_vpl VALUES ("PP4_11","080_4_11","PHP","4","11","11","Ba na faɗin haka domin ina cikin bukata, gama na koya yadda zan gamsu a cikin kowane hali. ");
INSERT INTO hausa_vpl VALUES ("PP4_12","080_4_12","PHP","4","12","12","Na san mene ne zaman rashi, na kuma san mene ne zaman samu. Zan iya zama cikin kowane hali, ko cikin ƙoshi ko cikin yunwa, ko cikin yalwa ko kuma cikin fatara. ");
INSERT INTO hausa_vpl VALUES ("PP4_13","080_4_13","PHP","4","13","13","Ina iya yin kome ta wurin wannan wanda yake ba ni ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("PP4_14","080_4_14","PHP","4","14","14","Duk da haka kun kyauta da kuka yi tarayya da ni cikin wahalolina. ");
INSERT INTO hausa_vpl VALUES ("PP4_15","080_4_15","PHP","4","15","15","Ban da haka, kamar yadda ku Filibbiyawa kuka sani, a farkon kwanakin da kuka ji bishara, sa’ad da na tashi daga Makidoniya, babu wata ikkilisiyar da tă yi tarayya da ni a fannin bayarwa da karɓa, sai ku kaɗai; ");
INSERT INTO hausa_vpl VALUES ("PP4_16","080_4_16","PHP","4","16","16","gama ko sa’ad da nake a Tessalonika ma, kun aiko mini da taimako sau da sau sa’ad da nake cikin bukata. ");
INSERT INTO hausa_vpl VALUES ("PP4_17","080_4_17","PHP","4","17","17","Ba cewa ina neman kyauta ba ne, sai dai ina neman abin da za a ƙara a kan ribarku. ");
INSERT INTO hausa_vpl VALUES ("PP4_18","080_4_18","PHP","4","18","18","An biya ni duka, biyan da ya wuce misali. Bukatata ta biya, da yake na karɓi kyautarku da kuka aiko ta hannun Afaforiditus. Baiwa mai ƙanshi, hadaya abar karɓa, mai faranta wa Allah rai. ");
INSERT INTO hausa_vpl VALUES ("PP4_19","080_4_19","PHP","4","19","19","Allahna kuma zai biya dukan bukatunku bisa ga ɗaukakar wadatarsa cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("PP4_20","080_4_20","PHP","4","20","20","Ɗaukaka ta tabbata ga Allahnmu da Ubanmu har abada abadin. Amin. ");
INSERT INTO hausa_vpl VALUES ("PP4_21","080_4_21","PHP","4","21","21","Ku gai da dukan tsarkaka cikin Kiristi Yesu. ’Yan’uwan da suke tare da ni suna gaishe ku. ");
INSERT INTO hausa_vpl VALUES ("PP4_22","080_4_22","PHP","4","22","22","Dukan tsarkaka suna gaishe ku, musamman waɗanda suke na gidan Kaisar. ");
INSERT INTO hausa_vpl VALUES ("PP4_23","080_4_23","PHP","4","23","23","Alherin Ubangiji Yesu Kiristi yă kasance da ruhunku. Amin.");
INSERT INTO hausa_vpl VALUES ("CL1_1","081_1_1","COL","1","1","1","Bulus, wanda Allah ya zaɓa don yă zama manzon Kiristi Yesu, da kuma daga Timoti ɗan’uwanmu, ");
INSERT INTO hausa_vpl VALUES ("CL1_2","081_1_2","COL","1","2","2","Zuwa ga tsarkaka da kuma amintattun ’yan’uwa cikin Kiristi da suke a Kolossi. Alheri da salama daga Allah Ubanmu, su kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("CL1_3","081_1_3","COL","1","3","3","Kullum muna gode wa Allah, Uban Ubangijinmu Yesu Kiristi, sa’ad da muke addu’a dominku. ");
INSERT INTO hausa_vpl VALUES ("CL1_4","081_1_4","COL","1","4","4","Gama mun ji labarin bangaskiyarku a cikin Yesu Kiristi da kuma ƙaunar da kuke yi saboda dukan tsarkaka. ");
INSERT INTO hausa_vpl VALUES ("CL1_5","081_1_5","COL","1","5","5","Kuna yin haka ne kuwa domin abin da kuke bege yana a ajiye a sama. Kun riga kun ji game da wannan bege sa’ad da kuka gaskata saƙon nan na gaskiya wanda shi ne bisharar ");
INSERT INTO hausa_vpl VALUES ("CL1_6","081_1_6","COL","1","6","6","da ta zo muku. Ko’ina a duniya wannan bishara tana yi ta haihuwa tana kuma girma, kamar yadda take yi a cikinku tun daga ranar da kuka ji ta kuka kuma fahimci alherin Allah cikin dukan gaskiyarta. ");
INSERT INTO hausa_vpl VALUES ("CL1_7","081_1_7","COL","1","7","7","Kun koyi wannan gaskiya daga wurin Efafaras, ƙaunataccen abokin hidimarmu, wanda yake amintacce mai hidimar Kiristi a madadinmu, ");
INSERT INTO hausa_vpl VALUES ("CL1_8","081_1_8","COL","1","8","8","wanda kuma ya faɗa mana ƙaunar da kuke yi cikin Ruhu. ");
INSERT INTO hausa_vpl VALUES ("CL1_9","081_1_9","COL","1","9","9","Shi ya sa tun daga ranar da muka sami labarin, ba mu fasa yin addu’a dominku ba. Kullum muna roƙon Allah yă sa ku san kome da yake so ku yi, domin ku sami hikima ta Ruhu, ku kuma sami ganewar kome duka. ");
INSERT INTO hausa_vpl VALUES ("CL1_10","081_1_10","COL","1","10","10","Ta haka za ku yi rayuwa wadda ta dace da Ubangiji, ku kuma gamshe shi a ta kowace hanya, kuna yin aiki mai kyau ta kowace hanya, kuna kuma yin girma cikin sanin Allah. ");
INSERT INTO hausa_vpl VALUES ("CL1_11","081_1_11","COL","1","11","11","Allah yă ƙarfafa ku da dukan iko bisa ga ɗaukakar ƙarfinsa domin ku kasance da jimrewa sosai da kuma haƙuri, cikin farin ciki ");
INSERT INTO hausa_vpl VALUES ("CL1_12","081_1_12","COL","1","12","12","kuna gode wa Uba, wanda ya sa kuka cancanci ku sami rabo a gādon tsarkaka a cikin mulkin haske. ");
INSERT INTO hausa_vpl VALUES ("CL1_13","081_1_13","COL","1","13","13","Gama ya riga ya cece mu daga mulkin duhu ya kuma kawo mu cikin mulkin Ɗan da yake ƙauna, ");
INSERT INTO hausa_vpl VALUES ("CL1_14","081_1_14","COL","1","14","14","wanda ta wurinsa muka sami fansa da kuma gafarar zunubai. ");
INSERT INTO hausa_vpl VALUES ("CL1_15","081_1_15","COL","1","15","15","Kiristi shi ne surar da ake gani na Allah wanda ba a iya gani, ɗan fari a kan dukan halitta. ");
INSERT INTO hausa_vpl VALUES ("CL1_16","081_1_16","COL","1","16","16","Ta wurinsa aka halicci dukan abu, abubuwan da suke cikin sama da abubuwan da suke a duniya, waɗanda ake gani, da waɗanda ba a gani, ko kursiyoyi ko ikoki ko masu mulki ko hukumomi; an halicci dukan abu ta wurinsa da kuma dominsa ne. ");
INSERT INTO hausa_vpl VALUES ("CL1_17","081_1_17","COL","1","17","17","Ya kasance kafin dukan abu, kuma a cikinsa ne dukan abubuwa suke a harhaɗe. ");
INSERT INTO hausa_vpl VALUES ("CL1_18","081_1_18","COL","1","18","18","Shi ne kuma kan ikkilisiya, wadda take jikinsa. Shi ne mafari da kuma na farko da ya tashi daga matattu, domin a cikin kowane abu yă zama mafifici. ");
INSERT INTO hausa_vpl VALUES ("CL1_19","081_1_19","COL","1","19","19","Gama Allah ya ji daɗi yă sa dukan cikarsa ta kasance a cikin Kiristi, ");
INSERT INTO hausa_vpl VALUES ("CL1_20","081_1_20","COL","1","20","20","ta wurin Kiristi ne ya komar da kome zuwa ga kansa. Ya kawo salama ga abubuwan da suke ƙasa da abubuwan da suke sama, ta wurin jinin Kiristi da ya zubar a kan gicciye. ");
INSERT INTO hausa_vpl VALUES ("CL1_21","081_1_21","COL","1","21","21","A dā kuna a ware da Allah, kuka kuma zama abokan gāba a cikin tunaninku saboda mugun halinku. ");
INSERT INTO hausa_vpl VALUES ("CL1_22","081_1_22","COL","1","22","22","Amma Ɗansa ya zama mutum ya kuma mutu. Saboda haka Allah ya yi sulhu da ku, yanzu kuwa ya bar ku ku tsaya a gabansa da tsarki, marasa aibi, da kuma marasa abin zargi. ");
INSERT INTO hausa_vpl VALUES ("CL1_23","081_1_23","COL","1","23","23","Sai ku ci gaba cikin bangaskiyarku, kuna tsaye a kafe kuma tsayayyu, ba tare da gusawa daga begen da kuka ji daga bishara ba. Wannan ita ce bisharar da kuka ji wadda aka yi shelarta ga kowace halittar da take ƙarƙashin sama, wadda kuma ni Bulus, na zama mai hidimarta. ");
INSERT INTO hausa_vpl VALUES ("CL1_24","081_1_24","COL","1","24","24","Yanzu, ina farin ciki saboda wuyar da nake sha dominku, don ta wurin wuyan nan zan cika abin da ya rage na wuyar da Kiristi ya sha saboda jikinsa, wato, ikkilisiya. ");
INSERT INTO hausa_vpl VALUES ("CL1_25","081_1_25","COL","1","25","25","Na zama mai hidimar ikkilisiya bisa ga aikin nan da Allah ya ba ni amana saboda ku, domin in sanar da maganar Allah sosai. ");
INSERT INTO hausa_vpl VALUES ("CL1_26","081_1_26","COL","1","26","26","Wannan magana da nake gaya muku asiri ne da yake a ɓoye tun zamanai masu yawa, wanda yanzu aka bayyana ga tsarkaka. ");
INSERT INTO hausa_vpl VALUES ("CL1_27","081_1_27","COL","1","27","27","Su ne Allah ya so yă sanar da yadda irin yalwar ɗaukakar asirin nan take a cikin al’ummai, asirin nan kuwa shi ne Kiristi a cikinku, begen ɗaukakar da za a bayyana. ");
INSERT INTO hausa_vpl VALUES ("CL1_28","081_1_28","COL","1","28","28","Saboda haka ko’ina muka tafi, muna shela, muna gargaɗi, muna kuma koyar da kowa da dukan hikima, don mu miƙa kowa cikakke a cikin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("CL1_29","081_1_29","COL","1","29","29","Don haka ne ina fama, ina kuma ƙoƙari da duk ƙarfin nan da Kiristi ya ba ni. ");
INSERT INTO hausa_vpl VALUES ("CL2_1","081_2_1","COL","2","1","1","Ina so ku san irin famar da nake yi saboda ku da kuma waɗanda suke a Lawodiseya, da kuma saboda dukan waɗanda ba su taɓa ganina ido da ido ba. ");
INSERT INTO hausa_vpl VALUES ("CL2_2","081_2_2","COL","2","2","2","Manufata ita ce a ƙarfafa su su kuma zama ɗaya a cikin ƙauna. Ina so su kasance da cikakken ƙarfin hali domin suna da cikakken fahimtar asirin Allah, wato, Kiristi kansa, ");
INSERT INTO hausa_vpl VALUES ("CL2_3","081_2_3","COL","2","3","3","a cikinsa ne aka ɓoye dukkan dukiya ta hikima da ta sani. ");
INSERT INTO hausa_vpl VALUES ("CL2_4","081_2_4","COL","2","4","4","Ina faɗa muku wannan ne don kada wani yă ruɗe ku da daɗin baki. ");
INSERT INTO hausa_vpl VALUES ("CL2_5","081_2_5","COL","2","5","5","Gama ko da yake ba na nan tare da ku a cikin jiki, ina tunaninku kullum, ina kuma farin ciki da gani kuna rayuwa yadda ya kamata, kuna kuma dāgewarku a kan bangaskiyarku a cikin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("CL2_6","081_2_6","COL","2","6","6","To, da yake kun karɓi Kiristi Yesu a matsayin Ubangiji, sai ku ci gaba da rayuwa a cikinsa, ");
INSERT INTO hausa_vpl VALUES ("CL2_7","081_2_7","COL","2","7","7","ku tsaya daram ku kuma ginu a cikinsa, ku sami ƙarfafawa a cikin bangaskiya kamar yadda aka koya muku, kuna kuma cike da godiya. ");
INSERT INTO hausa_vpl VALUES ("CL2_8","081_2_8","COL","2","8","8","Ku lura kada wani yă ruɗe ku da ilimin banza da wofi. Wannan koyarwa ta mutane ce kawai. Ta fito daga ikokin wannan duniya ne ba daga Kiristi ba. ");
INSERT INTO hausa_vpl VALUES ("CL2_9","081_2_9","COL","2","9","9","Gama a cikin Kiristi cikin jiki dukkan cikar Allahntaka take tabbata, ");
INSERT INTO hausa_vpl VALUES ("CL2_10","081_2_10","COL","2","10","10","an kuma mai da ku cikakku a cikin Kiristi, wanda yake shi ne kai a kan kowane iko da kuma hukuma. ");
INSERT INTO hausa_vpl VALUES ("CL2_11","081_2_11","COL","2","11","11","A cikinsa ne kuma aka yi muku kaciya, ba kuwa yin mutum ba, amma wadda Kiristi ya yi muku, ta wurin tuɓe halinku na mutuntaka. ");
INSERT INTO hausa_vpl VALUES ("CL2_12","081_2_12","COL","2","12","12","Da yake an binne ku tare da shi cikin baftisma haka kuma aka tashe ku tare da shi ta wurin bangaskiyarku a cikin ikon Allah, wanda ya tashe shi daga matattu. ");
INSERT INTO hausa_vpl VALUES ("CL2_13","081_2_13","COL","2","13","13","Kun zama matattu saboda ku masu zunubi ne kuma saboda halin zunubanku aka ware. Sa’an nan Allah ya sa kuka rayu tare da Kiristi. Ya gafarta mana dukan zunubanmu. ");
INSERT INTO hausa_vpl VALUES ("CL2_14","081_2_14","COL","2","14","14","Ya soke rubutacciyar doka tare da ƙa’idodinta, wadda take gāba da mu, take kuma hamayya da mu; ya kuma kawar da ta, ya kafe ta a kan gicciye. ");
INSERT INTO hausa_vpl VALUES ("CL2_15","081_2_15","COL","2","15","15","Bayan ya ƙwace makaman ikoki da hukumomi, ya kunyata su a sarari, ya ci nasara a bisansu ta wurin gicciye. ");
INSERT INTO hausa_vpl VALUES ("CL2_16","081_2_16","COL","2","16","16","Saboda haka kada ku bar wani yă shari’anta ku a kan abin da kuke ci ko sha, ko bisa ga abin da ya shafi wani bikin addini, ko Bikin Sabon Wata ko na ranar Asabbaci. ");
INSERT INTO hausa_vpl VALUES ("CL2_17","081_2_17","COL","2","17","17","Waɗannan su ne hoton abubuwan da za su zo; amma Kiristi ne ainihinsu. ");
INSERT INTO hausa_vpl VALUES ("CL2_18","081_2_18","COL","2","18","18","Kada ku yarda wani yă ɓata ku, cewa shi wani abu ne don yă ga wahayi. Irin mutumin nan yakan nuna ƙasƙancin kai na ƙarya, yă kuma ce yana yi wa mala’iku sujada. Irin mutumin nan yana kumbura kansa ba dalili, sai son zuciya irin na halin mutuntaka. ");
INSERT INTO hausa_vpl VALUES ("CL2_19","081_2_19","COL","2","19","19","Ya yanke dangantaka da Kiristi wanda yake kai, wanda ta gare shi ne dukan jiki yake a haɗe, yake tsaye ta wurin taimakon gaɓoɓi da jijiyoyi, yana kuma girma kamar yadda Allah yake sa yă yi girma. ");
INSERT INTO hausa_vpl VALUES ("CL2_20","081_2_20","COL","2","20","20","Kun mutu tare da Kiristi. Yanzu ƙa’idodin wannan duniya ba su da iko a kanku. Don me kuke zama har yanzu kamar ku nasu ne? Kuna biyayya da umarnansu cewa, ");
INSERT INTO hausa_vpl VALUES ("CL2_21","081_2_21","COL","2","21","21","“Kada ka kama! Kada ka ɗanɗana! Kada ka taɓa”? ");
INSERT INTO hausa_vpl VALUES ("CL2_22","081_2_22","COL","2","22","22","Irin waɗannan dokoki suna magana a kan abubuwan da ba sa daɗewa. Su ayyukan mutane ne, sun kuma fito daga koyarwar mutane. ");
INSERT INTO hausa_vpl VALUES ("CL2_23","081_2_23","COL","2","23","23","Yin biyayya da irin waɗannan ƙa’idodi za su yi kamar su ne abu mafi kyau da za a yi. Sukan yi kamar suna sa a ƙaunaci Allah sosai a kuma kasance da sauƙinkai a kuma kasance da kamunkai. Amma ba su da wani iko a kan sha’awace-sha’awacenmu. ");
INSERT INTO hausa_vpl VALUES ("CL3_1","081_3_1","COL","3","1","1","Da yake an tashe ku tare da Kiristi, sai ku sa zukatanku a kan abubuwan da suke sama, inda Kiristi yake zaune a hannun dama na Allah. ");
INSERT INTO hausa_vpl VALUES ("CL3_2","081_3_2","COL","3","2","2","Ku sa hankulanku a kan abubuwan sama, ba kan abubuwan duniya ba. ");
INSERT INTO hausa_vpl VALUES ("CL3_3","081_3_3","COL","3","3","3","Gama kun mutu, ranku yanzu kuwa yana ɓoye tare da Kiristi a cikin Allah. ");
INSERT INTO hausa_vpl VALUES ("CL3_4","081_3_4","COL","3","4","4","Sa’ad da Kiristi, wanda shi ne ranku, ya bayyana, ku ma za ku bayyana tare da shi cikin ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("CL3_5","081_3_5","COL","3","5","5","Saboda haka, sai ku fid da duk wani abin da yake kawo sha’awa a zukatanku, fasikanci, ƙazanta, sha’awa, muguwar sha’awa, da kuma kwaɗayi wanda shi ma bautar gumaka ne. ");
INSERT INTO hausa_vpl VALUES ("CL3_6","081_3_6","COL","3","6","6","Gama fushin Allah zai sauko a kan masu aikata waɗannan. ");
INSERT INTO hausa_vpl VALUES ("CL3_7","081_3_7","COL","3","7","7","Dā kun yi waɗannan abubuwa, sa’ad da rayuwar tana cikin duniya mai wannan hali. ");
INSERT INTO hausa_vpl VALUES ("CL3_8","081_3_8","COL","3","8","8","Amma yanzu dole ku raba kanku da dukan ire-iren abubuwan nan. Ku daina fushi, ku daina ƙiyayya da ƙeta. Ku bar ɓatan suna da kuma ƙazamar magana daga leɓunanku. ");
INSERT INTO hausa_vpl VALUES ("CL3_9","081_3_9","COL","3","9","9","Kada ku yi wa juna ƙarya, da yake kun tuɓe tsohon halinku tare da ayyukansa ");
INSERT INTO hausa_vpl VALUES ("CL3_10","081_3_10","COL","3","10","10","kun ɗauki sabon halin nan da ake sabuntawa ga sani, bisa ga kamannin Mahaliccinsa. ");
INSERT INTO hausa_vpl VALUES ("CL3_11","081_3_11","COL","3","11","11","A wannan sabuwar rayuwa babu bambanci ko kai mutumin Al’ummai ne ko mutumin Yahuda, mai kaciya ne ko marar kaciya, baƙo, baƙauye, bawa ne ko ’yantacce, gama Kiristi shi ne kome, kuma yana cikin kome. ");
INSERT INTO hausa_vpl VALUES ("CL3_12","081_3_12","COL","3","12","12","Da yake Allah ya mai da ku zaɓaɓɓu, tsarkaka, ƙaunatattu, sai ku dinga jin tausayin juna, kuna yin alheri, kuna nuna tawali’u da sauƙinkai da jimrewa. ");
INSERT INTO hausa_vpl VALUES ("CL3_13","081_3_13","COL","3","13","13","Ku riƙa yin haƙuri da juna kuna kuma gafarta wa juna duk wani laifin da wani ya yi muku. Ku gafarta kamar yadda Ubangiji ya gafarce ku. ");
INSERT INTO hausa_vpl VALUES ("CL3_14","081_3_14","COL","3","14","14","Fiye da waɗannan duka, ku yi ƙaunar juna, gama ƙauna ce take haɗa kome gaba ɗaya. ");
INSERT INTO hausa_vpl VALUES ("CL3_15","081_3_15","COL","3","15","15","Ku bar salamar Kiristi tă yi mulki a zukatanku, da yake a matsayin gaɓoɓin jiki ɗaya an kira ku ga salama. Ku zama masu godiya. ");
INSERT INTO hausa_vpl VALUES ("CL3_16","081_3_16","COL","3","16","16","Ku bar maganar Kiristi ta zauna a cikinku a yalwace yayinda kuke koya, kuna kuma yi wa juna gargaɗi da dukan hikima, da kuma yayinda kuke waƙoƙin zabura, waƙoƙi da waƙoƙin ruhaniya tare da godiya a zukatanku ga Allah. ");
INSERT INTO hausa_vpl VALUES ("CL3_17","081_3_17","COL","3","17","17","Kuma ko mene ne kuke yi, ko cikin magana ko cikin ayyuka, ku yi shi duka a cikin sunan Ubangiji Yesu, kuna yin godiya ga Allah Uba ta wurinsa. ");
INSERT INTO hausa_vpl VALUES ("CL3_18","081_3_18","COL","3","18","18","Mata, ku yi biyayya ga mazanku, yadda ya dace cikin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("CL3_19","081_3_19","COL","3","19","19","Maza, ku ƙaunaci matanku kada ku nuna musu hali marar tausayi. ");
INSERT INTO hausa_vpl VALUES ("CL3_20","081_3_20","COL","3","20","20","’Ya’ya, ku yi biyayya ga iyayenku cikin kome, gama wannan yakan gamshi Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("CL3_21","081_3_21","COL","3","21","21","Ubanni, kada ku matsa wa yaranku lamba, don kada su fid da zuciya. ");
INSERT INTO hausa_vpl VALUES ("CL3_22","081_3_22","COL","3","22","22","Bayi, ku yi biyayya ga iyayengijinku na duniya cikin kome; kada ku yi aikin ganin ido kamar masu neman yabon mutane, sai dai ku yi aiki tsakaninku da Allah, kamar masu tsoron Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("CL3_23","081_3_23","COL","3","23","23","Kome kuke yi, ku yi shi da dukan zuciyarku, sai ka ce ga Ubangiji kuke yi, ba ga mutum ba. ");
INSERT INTO hausa_vpl VALUES ("CL3_24","081_3_24","COL","3","24","24","Kun san cewa zai ba ku gādo a matsayin ladanku. Ubangiji Kiristi ne fa kuke bauta wa. ");
INSERT INTO hausa_vpl VALUES ("CL3_25","081_3_25","COL","3","25","25","Duk wanda ya yi laifi, za a sāka masa don laifinsa, babu sonkai. ");
INSERT INTO hausa_vpl VALUES ("CL4_1","081_4_1","COL","4","1","1","Masu bayi, ku riƙe bayinku da kyau da kuma daidai, domin kun san cewa ku ma kuna da Ubangiji a sama. ");
INSERT INTO hausa_vpl VALUES ("CL4_2","081_4_2","COL","4","2","2","Ku nace da yin addu’a, kuna zaman tsaro da kuma godiya. ");
INSERT INTO hausa_vpl VALUES ("CL4_3","081_4_3","COL","4","3","3","Ku kuma yi mana addu’a, mu ma, don Allah yă buɗe ƙofa saboda saƙonmu, don mu iya yin shelar asirin Kiristi, wanda saboda shi nake cikin sarƙoƙi. ");
INSERT INTO hausa_vpl VALUES ("CL4_4","081_4_4","COL","4","4","4","Ku yi addu’a yadda zan yi shelarsa, yadda ya kamata. ");
INSERT INTO hausa_vpl VALUES ("CL4_5","081_4_5","COL","4","5","5","Ku zama masu hikima a yadda kuke ma’amala da waɗanda suke ba masu bi ba; ku kuma yi amfani da kowane zarafi. ");
INSERT INTO hausa_vpl VALUES ("CL4_6","081_4_6","COL","4","6","6","Bari maganarku kullum ta zama da ladabi da kuma daɗin ji, domin ku san amsar da ta dace ku ba wa kowa. ");
INSERT INTO hausa_vpl VALUES ("CL4_7","081_4_7","COL","4","7","7","Tikikus shi ne ƙaunataccen ɗan’uwan nan, wanda ya yi aiki da aminci a hidimar Ubangiji tare da mu, zai kuwa faɗa muku dukan labari game da ni. ");
INSERT INTO hausa_vpl VALUES ("CL4_8","081_4_8","COL","4","8","8","Ina aikansa shi a gare ku musamman domin ku san yadda muke, yă kuma ƙarfafa muku zuciya. ");
INSERT INTO hausa_vpl VALUES ("CL4_9","081_4_9","COL","4","9","9","Yana zuwa tare da Onesimus, ƙaunatacce da kuma amintaccen mai bin nan, wanda yake ɗaya daga cikinku. Za su gaya muku dukan abin da yake faruwa a nan. ");
INSERT INTO hausa_vpl VALUES ("CL4_10","081_4_10","COL","4","10","10","Aristarkus yana a kurkuku tare da ni. Yana gaishe ku, haka ma Markus, wanda kakansa ɗaya ne da Barnabas. (Shi ne na riga na yi magana a kansa, na ce muku in ya zo, ku karɓe shi hannu biyu-biyu.) ");
INSERT INTO hausa_vpl VALUES ("CL4_11","081_4_11","COL","4","11","11","Yesu, wannan da muke kira Yustus, shi ma yana gaisuwa. Waɗannan ne kaɗai Yahudawa masu bi a cikin abokan aikina saboda mulkin Allah. Sun kuma zama da taimako a gare ni. ");
INSERT INTO hausa_vpl VALUES ("CL4_12","081_4_12","COL","4","12","12","Efafaras naku, mai hidimar Kiristi Yesu, yana gaisuwa. Kullum yana addu’a dominku sosai, don ku san cikakken abin da Allah yake so ku yi don kuma ku yi shi cikakke. ");
INSERT INTO hausa_vpl VALUES ("CL4_13","081_4_13","COL","4","13","13","Na tabbatar muku, cewa yana aiki ƙwarai dominku da kuma domin waɗanda suke a Lawodiseya da Hiyerafolis. ");
INSERT INTO hausa_vpl VALUES ("CL4_14","081_4_14","COL","4","14","14","Luka ƙaunataccen likitan nan, da kuma Demas suna gaishe ku. ");
INSERT INTO hausa_vpl VALUES ("CL4_15","081_4_15","COL","4","15","15","Ku miƙa gaisuwata ga ’yan’uwan da suke a Lawodiseya, musamman ga Nimfa da kuma ikkilisiyar da take taru a gidanta. ");
INSERT INTO hausa_vpl VALUES ("CL4_16","081_4_16","COL","4","16","16","Bayan an karanta muku wannan wasiƙa, ku tabbata an karanta ta kuma a ikkilisiyar Lawodiseyawa; ku ma ku karanta wasiƙar da ta zo daga Lawodiseya. ");
INSERT INTO hausa_vpl VALUES ("CL4_17","081_4_17","COL","4","17","17","Ku faɗa wa Arkiffus yă tabbata ya ƙarasa aikin da ya karɓa cikin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("CL4_18","081_4_18","COL","4","18","18","Ni Bulus ne nake rubuta muku wannan gaisuwa da hannuna. Ku tuna da sarƙoƙina. Alherin Allah yă kasance tare da ku.");
INSERT INTO hausa_vpl VALUES ("H11_1","082_1_1","1TH","1","1","1","Bulus, Sila da Timoti, Zuwa ga ikkilisiyar Tessalonikawa ta Allah Uba da Ubangiji Yesu Kiristi. Alheri da salama su kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("H11_2","082_1_2","1TH","1","2","2","Kullum muna gode wa Allah dominku duka, muna ambatonku cikin addu’o’inmu. ");
INSERT INTO hausa_vpl VALUES ("H11_3","082_1_3","1TH","1","3","3","Muna tunawa da aikinku ba fasawa a gaban Allah da Ubanmu ta wurin bangaskiya, da famar da kuke yi domin ƙauna, da kuma begenku marar gushewa ga Ubangijinmu Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("H11_4","082_1_4","1TH","1","4","4","Gama mun sani, ’yan’uwa, ƙaunatattu na Allah, cewa ya zaɓe ku, ");
INSERT INTO hausa_vpl VALUES ("H11_5","082_1_5","1TH","1","5","5","domin bishararmu ba tă zo gare ku da kalmomi kawai ba, amma da iko, da Ruhu Mai Tsarki, da kuma cikakken tabbaci. Kun san irin rayuwar da muka yi a cikinku don amfaninku. ");
INSERT INTO hausa_vpl VALUES ("H11_6","082_1_6","1TH","1","6","6","Har kuka zama masu koyi da mu da kuma Ubangiji; duk da tsananin wahala, kuka karɓi saƙon nan da farin ciki wanda Ruhu Mai Tsarki ya bayar. ");
INSERT INTO hausa_vpl VALUES ("H11_7","082_1_7","1TH","1","7","7","Ta haka kuwa kuka zama gurbi ga dukan masu bi a Makidoniya da Akayya. ");
INSERT INTO hausa_vpl VALUES ("H11_8","082_1_8","1TH","1","8","8","Saƙon Ubangiji ya fito daga gare ku ne ba a Makidoniya da Akayya kaɗai ba bangaskiyarku ga Allah ta zama sananne ko’ina. Saboda haka ba ma bukata mu faɗa wani abu a kai, ");
INSERT INTO hausa_vpl VALUES ("H11_9","082_1_9","1TH","1","9","9","gama su kansu su suke ba da labari irin karɓar da kuka yi mana. Suna faɗin yadda kuka juyo ga Allah daga gumaka don ku bauta wa Allah rayayye da kuma na gaskiya, ");
INSERT INTO hausa_vpl VALUES ("H11_10","082_1_10","1TH","1","10","10","ku kuma jira dawowar Ɗansa daga sama, wanda ya tasa daga matattu, Yesu, wanda ya cece mu daga fushi mai zuwa. ");
INSERT INTO hausa_vpl VALUES ("H12_1","082_2_1","1TH","2","1","1","Kun sani, ’yan’uwa, cewa ziyararmu a gare ku ba tă zama a banza ba. ");
INSERT INTO hausa_vpl VALUES ("H12_2","082_2_2","1TH","2","2","2","Mun riga mun sha wahala, aka kuma zage mu a Filibbi, kamar yadda kuka sani, amma da taimakon Allahnmu muka yi ƙarfin hali muka sanar muku bishararsa duk da matsananciyar gāba. ");
INSERT INTO hausa_vpl VALUES ("H12_3","082_2_3","1TH","2","3","3","Gama roƙon da muke yi bai fito daga kuskure ko munafunci ba, ba kuwa ƙoƙari muke yi mu yaudare ku ba. ");
INSERT INTO hausa_vpl VALUES ("H12_4","082_2_4","1TH","2","4","4","A maimako haka, muna magana ne kamar mutanen da Allah ya amince yă danƙa musu amanar wannan bishara. Ba ma ƙoƙari mu gamshi mutane sai dai Allah, mai auna zukatanmu. ");
INSERT INTO hausa_vpl VALUES ("H12_5","082_2_5","1TH","2","5","5","Kun san ba ma taɓa yin daɗin baki ko mu yi ƙoƙarin kasance da halin kwaɗayin da muke ɓoyewa, Allah shi ne shaidarmu. ");
INSERT INTO hausa_vpl VALUES ("H12_6","082_2_6","1TH","2","6","6","Ba ma neman yabo daga wurin mutane, ko a gare ku, ko ga waɗansu. A matsayinmu na manzannin Kiristi da mun so, da mun nawaita muku, ");
INSERT INTO hausa_vpl VALUES ("H12_7","082_2_7","1TH","2","7","7","amma muka kasance masu sauƙinkai a cikinku, kamar yadda mahaifiya take lura da ƙananan ’ya’yanta. ");
INSERT INTO hausa_vpl VALUES ("H12_8","082_2_8","1TH","2","8","8","Muka ƙaunace ku ƙwarai har muka ji daɗin bayyana muku, ba bisharar Allah kaɗai ba amma har rayukanmu ma, domin kun zama ƙaunatattu a gare mu. ");
INSERT INTO hausa_vpl VALUES ("H12_9","082_2_9","1TH","2","9","9","Ba shakka kuna iya tunawa, ’yan’uwa, famarmu da kuma wahalarmu; mun yi aiki dare da rana don kada mu zama nauyi wa wani yayinda muke muku wa’azin bisharar Allah. ");
INSERT INTO hausa_vpl VALUES ("H12_10","082_2_10","1TH","2","10","10","Ku shaidu ne, haka ma Allah, na yadda muka yi zaman tsarki, adalci da kuma marar aibi a cikinku, ku da kuka ba da gaskiya. ");
INSERT INTO hausa_vpl VALUES ("H12_11","082_2_11","1TH","2","11","11","Gama kun san cewa mun bi da kowannenku yadda mahaifi yakan yi da ’ya’yansa, ");
INSERT INTO hausa_vpl VALUES ("H12_12","082_2_12","1TH","2","12","12","muna ƙarfafa ku, muna ta’azantar da ku, muna kuma gargaɗe ku ku yi rayuwar da za tă cancanci Allah, wanda ya kira ku zuwa mulkinsa da kuma ɗaukakarsa. ");
INSERT INTO hausa_vpl VALUES ("H12_13","082_2_13","1TH","2","13","13","Muna kuma gode wa Allah ba fasawa domin, sa’ad da kuka karɓi maganar Allah, wadda kuka ji daga gare mu, kun karɓe ta ba kamar maganar mutane ba, sai dai kamar yadda take, maganar Allah wadda take aiki a cikinku ku da kuka ba da gaskiya. ");
INSERT INTO hausa_vpl VALUES ("H12_14","082_2_14","1TH","2","14","14","Gama ku, ’yan’uwa, kun zama masu koyi da ikkilisiyoyin Allah a Yahudiya waɗanda suke cikin Kiristi Yesu. Kun sha wahala a hannun mutanen ƙasarku kamar yadda ikkilisiyoyin nan ma suka sha a hannun Yahudawa, ");
INSERT INTO hausa_vpl VALUES ("H12_15","082_2_15","1TH","2","15","15","waɗanda suka kashe Ubangiji Yesu da annabawa suka kuma kore mu. Ba sa yin aikin da Allah yake so, masu gāba ne kuwa da dukan mutane ");
INSERT INTO hausa_vpl VALUES ("H12_16","082_2_16","1TH","2","16","16","suna ƙoƙarin hana mu yin magana ga Al’ummai don kada su sami ceto. Ta haka kullum suke ƙara tara tsibin zunubansu. Fushin Allah ya aukar musu a ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("H12_17","082_2_17","1TH","2","17","17","Amma, ’yan’uwa, sa’ad da aka raba mu da ku na ɗan lokaci (a jiki, ba a tunani ba), daga cikin marmarinmu mai tsanani mun yi duk abin da muke iya yi mu gan ku. ");
INSERT INTO hausa_vpl VALUES ("H12_18","082_2_18","1TH","2","18","18","Gama mun so mu zo wurinku, tabbatacce ni, Bulus, na yi ƙoƙari sau da sau, amma Shaiɗan ya hana mu. ");
INSERT INTO hausa_vpl VALUES ("H12_19","082_2_19","1TH","2","19","19","Gama mene ne begenmu, farin cikinmu, ko kuma rawanin da zai zama mana abin ɗaukaka a gaban Ubangijinmu Yesu sa’ad da ya dawo? Ba ku ba ne? ");
INSERT INTO hausa_vpl VALUES ("H12_20","082_2_20","1TH","2","20","20","Tabbatacce, ku ne ɗaukakarmu da kuma farin cikinmu. ");
INSERT INTO hausa_vpl VALUES ("H13_1","082_3_1","1TH","3","1","1","Saboda haka da muka kāsa daurewa, sai muka ga ya fi kyau a bar mu a Atens mu kaɗai. ");
INSERT INTO hausa_vpl VALUES ("H13_2","082_3_2","1TH","3","2","2","Muka aiki Timoti, wanda yake ɗan’uwanmu da kuma abokin aikin Allah a cikin yaɗa bisharar Kiristi, don yă gina ku yă kuma ƙarfafa ku cikin bangaskiyarku, ");
INSERT INTO hausa_vpl VALUES ("H13_3","082_3_3","1TH","3","3","3","don kada kowa yă raunana ta wurin waɗannan gwaje-gwajen. Kun sani sarai cewa an ƙaddara mu don waɗannan. ");
INSERT INTO hausa_vpl VALUES ("H13_4","082_3_4","1TH","3","4","4","Gaskiyar ita ce, sa’ad da muke tare da ku, mun sha gaya muku cewa za a tsananta mana. Haka kuwa ya faru, kamar dai yadda kuka sani. ");
INSERT INTO hausa_vpl VALUES ("H13_5","082_3_5","1TH","3","5","5","Saboda wannan, sa’ad da ban iya jimrewa ba, sai na aika domin in sami labarin bangaskiyarku, da fata kada yă zama mai jarraban nan ya riga ya jarrabce ku, ƙoƙarinmu kuma yă zama banza. ");
INSERT INTO hausa_vpl VALUES ("H13_6","082_3_6","1TH","3","6","6","Amma ga shi yanzu Timoti ya dawo mana daga wurinku ya kuma kawo labari mai daɗi game da bangaskiyarku da kuma ƙaunarku. Ya faɗa mana yadda kullum kuke da tunani mai kyau a kanmu, yadda kuke marmari ku gan mu, kamar dai yadda mu ma muke marmari mu gan ku. ");
INSERT INTO hausa_vpl VALUES ("H13_7","082_3_7","1TH","3","7","7","Saboda haka ’yan’uwa, cikin dukan damuwarmu da tsananinmu an ƙarfafa mu game da ku saboda bangaskiyarku. ");
INSERT INTO hausa_vpl VALUES ("H13_8","082_3_8","1TH","3","8","8","Gama yanzu tabbatacce muna da rai, da yake kuna nan tsaye daram a cikin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("H13_9","082_3_9","1TH","3","9","9","Wace irin godiya ce za mu yi wa Allah saboda ku a kan dukan farin cikin da muke da shi a gaban Allahnmu ta dalilinku? ");
INSERT INTO hausa_vpl VALUES ("H13_10","082_3_10","1TH","3","10","10","Dare da rana muna addu’a da himma domin mu sāke ganinku, mu kuma ba ku abin da kuka rasa a bangaskiyarku. ");
INSERT INTO hausa_vpl VALUES ("H13_11","082_3_11","1TH","3","11","11","Yanzu bari Allahnmu da Ubanmu kansa da kuma Ubangijinmu Yesu yă shirya mana hanya mu zo wurinku. ");
INSERT INTO hausa_vpl VALUES ("H13_12","082_3_12","1TH","3","12","12","Ubangiji yă sa ƙaunarku ta ƙaru ta kuma yalwata ga juna da kuma ga kowa, kamar yadda tamu take muku. ");
INSERT INTO hausa_vpl VALUES ("H13_13","082_3_13","1TH","3","13","13","Bari yă ƙarfafa zukatanku har ku zama marasa aibi da kuma tsarkaka a gaban Allahnmu da Ubanmu sa’ad da Ubangijimmu Yesu ya dawo tare da dukan tsarkakansa. ");
INSERT INTO hausa_vpl VALUES ("H14_1","082_4_1","1TH","4","1","1","A ƙarshe, ’yan’uwa, mun umarce ku yadda za ku yi rayuwa domin ku gamshi Allah, kamar yadda kuke yi. Yanzu muna roƙonku muna kuma gargaɗe ku a cikin Ubangiji Yesu ku yi haka sau da sau. ");
INSERT INTO hausa_vpl VALUES ("H14_2","082_4_2","1TH","4","2","2","Gama kun san umarnan da muka ba ku ta wurin ikon Ubangiji Yesu. ");
INSERT INTO hausa_vpl VALUES ("H14_3","082_4_3","1TH","4","3","3","Nufin Allah ne a tsarkake ku, cewa ku guje wa fasikanci; ");
INSERT INTO hausa_vpl VALUES ("H14_4","082_4_4","1TH","4","4","4","don kowannenku yă koya yadda zai ƙame kansa a hanyar da take mai tsarki, mai mutunci kuma, ");
INSERT INTO hausa_vpl VALUES ("H14_5","082_4_5","1TH","4","5","5","ba cikin muguwar sha’awa kamar ta marasa bangaskiya, waɗanda ba su san Allah ba; ");
INSERT INTO hausa_vpl VALUES ("H14_6","082_4_6","1TH","4","6","6","cikin wannan al’amari kuwa kada wani yă yi wa ɗan’uwansa laifi ko yă cuce shi. Ubangiji zai hukunta mutane saboda dukan irin waɗannan zunubai, kamar yadda muka riga muka gaya muku, muka kuma yi muku gargaɗi. ");
INSERT INTO hausa_vpl VALUES ("H14_7","082_4_7","1TH","4","7","7","Gama Allah bai kira mu ga zaman marasa tsarki ba, sai dai ga zaman tsarki. ");
INSERT INTO hausa_vpl VALUES ("H14_8","082_4_8","1TH","4","8","8","Saboda haka, duk wanda ya ƙi wannan umarni ba mutum ne ya ƙi ba sai ko Allah, wanda ya ba ku Ruhunsa Mai Tsarki. ");
INSERT INTO hausa_vpl VALUES ("H14_9","082_4_9","1TH","4","9","9","Yanzu kuwa game da ƙaunar ’yan’uwa, ba ma bukata mu rubuta muku, gama ku kanku Allah ya riga ya koya muku ku ƙaunaci juna. ");
INSERT INTO hausa_vpl VALUES ("H14_10","082_4_10","1TH","4","10","10","Gaskiyar kuwa ita ce, kuna ƙaunar dukan ’yan’uwa ko’ina a Makidoniya. Duk da haka muna ƙara gargaɗe ku, ’yan’uwa, ku yi haka sau da sau. ");
INSERT INTO hausa_vpl VALUES ("H14_11","082_4_11","1TH","4","11","11","Ku mai da wannan burinku na yi natsattsiyar rayuwa, kuna mai da hankali ga sha’anin da yake gabanku, kuna kuma yin aiki da hannuwanku, kamar dai yadda muka gaya muku, ");
INSERT INTO hausa_vpl VALUES ("H14_12","082_4_12","1TH","4","12","12","don rayuwanku ta kullum ta zama da mutunci ga waɗanda suke na waje don kuma kada ku dogara a kan kowa. ");
INSERT INTO hausa_vpl VALUES ("H14_13","082_4_13","1TH","4","13","13","’Yan’uwa, ba ma so ku kasance cikin jahilci game da waɗanda suka yi barci, ko kuwa ku yi baƙin ciki kamar sauran mutanen da ba su da bege. ");
INSERT INTO hausa_vpl VALUES ("H14_14","082_4_14","1TH","4","14","14","Mun gaskata cewa Yesu ya mutu ya tashi kuma daga matattu, ta haka muka gaskata cewa Allah zai kawo waɗanda suka yi barci a cikinsa tare da Yesu. ");
INSERT INTO hausa_vpl VALUES ("H14_15","082_4_15","1TH","4","15","15","Bisa ga maganar Ubangiji kansa, muna gaya muku cewa mu da muke raye har yanzu, waɗanda aka bari har dawowar Ubangiji, tabbatacce ba za mu riga waɗanda suka yi barci tashi ba. ");
INSERT INTO hausa_vpl VALUES ("H14_16","082_4_16","1TH","4","16","16","Gama Ubangiji kansa zai sauko daga sama, da umarni mai ƙarfi, da muryar babban mala’ika da kuma busar ƙahon Allah, waɗanda suka mutu kuwa cikin Kiristi za su tashi da farko. ");
INSERT INTO hausa_vpl VALUES ("H14_17","082_4_17","1TH","4","17","17","Bayan haka, mu da muke da rai da aka bari, za a ɗauke mu tare da su a cikin gizagizai don mu sadu da Ubangiji a sararin sama. Ta haka za mu kasance tare da Ubangiji har abada. ");
INSERT INTO hausa_vpl VALUES ("H14_18","082_4_18","1TH","4","18","18","Saboda haka ku ƙarfafa juna da waɗannan kalmomi. ");
INSERT INTO hausa_vpl VALUES ("H15_1","082_5_1","1TH","5","1","1","To, ’yan’uwa, game da lokuta da ranaku, ba ma bukata mu rubuta muku, ");
INSERT INTO hausa_vpl VALUES ("H15_2","082_5_2","1TH","5","2","2","gama kun sani sarai cewa ranar Ubangiji za tă zo kamar ɓarawo da dare. ");
INSERT INTO hausa_vpl VALUES ("H15_3","082_5_3","1TH","5","3","3","Yayinda mutane suke cewa, “Akwai salama da zaman lafiya,” hallaka za tă auko musu farat ɗaya, kamar yadda naƙuda take kama mace mai ciki, ba za su kuwa tsira ba. ");
INSERT INTO hausa_vpl VALUES ("H15_4","082_5_4","1TH","5","4","4","Amma ku, ’yan’uwa, ba kwa cikin duhu da wannan rana za tă zo muku ba zato kamar ɓarawo. ");
INSERT INTO hausa_vpl VALUES ("H15_5","082_5_5","1TH","5","5","5","Dukanku ’ya’yan haske ne da kuma ’ya’yan rana. Mu ba mutanen dare ko na duhu ba ne. ");
INSERT INTO hausa_vpl VALUES ("H15_6","082_5_6","1TH","5","6","6","Saboda haka fa, kada mu zama kamar saura, waɗanda suke barci, sai dai mu zama masu tsaro da masu kamunkai. ");
INSERT INTO hausa_vpl VALUES ("H15_7","082_5_7","1TH","5","7","7","Gama masu barci, da dad dare suke barci, masu sha su bugu kuwa, da dad dare suke buguwa. ");
INSERT INTO hausa_vpl VALUES ("H15_8","082_5_8","1TH","5","8","8","Amma da yake mu na rana ne, bari mu zama masu kamunkai, sanye da bangaskiya da ƙauna kamar sulke, begen cetonmu kuma kamar hular kwano. ");
INSERT INTO hausa_vpl VALUES ("H15_9","082_5_9","1TH","5","9","9","Gama Allah bai naɗa mu don mu sha fushi ba, sai dai mu sami ceto ta wurin Ubangijinmu Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("H15_10","082_5_10","1TH","5","10","10","Ya mutu saboda mu domin, ko muna a faɗake ko muna barci, mu kasance tare da shi. ");
INSERT INTO hausa_vpl VALUES ("H15_11","082_5_11","1TH","5","11","11","Saboda haka ku ƙarfafa juna ku kuma gina juna, kamar dai yadda kuke yi. ");
INSERT INTO hausa_vpl VALUES ("H15_12","082_5_12","1TH","5","12","12","To, muna roƙonku, ’yan’uwa, ku girmama waɗanda suke aiki sosai a cikinku, waɗanda suke bisanku cikin Ubangiji da kuma waɗanda suke yin muku gargaɗi. ");
INSERT INTO hausa_vpl VALUES ("H15_13","082_5_13","1TH","5","13","13","Ku riƙe su da mutunci sosai cikin ƙauna saboda aikinsu. Ku yi zaman lafiya da juna. ");
INSERT INTO hausa_vpl VALUES ("H15_14","082_5_14","1TH","5","14","14","Muna kuma gargaɗe ku, ’yan’uwa, ku gargaɗe waɗanda suke zaman banza, ku ƙarfafa masu raunanar zuciya, ku taimaki marasa ƙarfi, ku yi haƙuri da kowa. ");
INSERT INTO hausa_vpl VALUES ("H15_15","082_5_15","1TH","5","15","15","Ku tabbata cewa kada kowa yă rama mugunta da mugunta, sai dai kullum ku yi ƙoƙarin yin wa juna alheri da kuma dukan mutane. ");
INSERT INTO hausa_vpl VALUES ("H15_16","082_5_16","1TH","5","16","16","Ku riƙa farin ciki kullum; ");
INSERT INTO hausa_vpl VALUES ("H15_17","082_5_17","1TH","5","17","17","ku ci gaba da yin addu’a; ");
INSERT INTO hausa_vpl VALUES ("H15_18","082_5_18","1TH","5","18","18","ku yi godiya cikin kowane hali, gama wannan shi ne nufin Allah dominku cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("H15_19","082_5_19","1TH","5","19","19","Kada ku danne aikin Ruhu. ");
INSERT INTO hausa_vpl VALUES ("H15_20","082_5_20","1TH","5","20","20","Kada ku rena annabci, ");
INSERT INTO hausa_vpl VALUES ("H15_21","082_5_21","1TH","5","21","21","amma ku gwada kome, ku riƙe abin da yake mai kyau, ");
INSERT INTO hausa_vpl VALUES ("H15_22","082_5_22","1TH","5","22","22","ku ƙi kowace mugunta. ");
INSERT INTO hausa_vpl VALUES ("H15_23","082_5_23","1TH","5","23","23","Bari Allah da kansa, Allah na salama, yă tsarkake ku sarai. Bari dukan ruhunku, ranku, da kuma jikinku su zama marar aibi a dawowar Ubangijinmu Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("H15_24","082_5_24","1TH","5","24","24","Wannan wanda ya kira ku mai aminci ne zai kuwa aikata. ");
INSERT INTO hausa_vpl VALUES ("H15_25","082_5_25","1TH","5","25","25","’Yan’uwa, ku yi mana addu’a. ");
INSERT INTO hausa_vpl VALUES ("H15_26","082_5_26","1TH","5","26","26","Ku gaggai da dukan ’yan’uwa da sumba mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("H15_27","082_5_27","1TH","5","27","27","Na gama ku da Ubangiji ku sa a karanta wannan wasiƙa ga dukan ’yan’uwa. ");
INSERT INTO hausa_vpl VALUES ("H15_28","082_5_28","1TH","5","28","28","Alherin Ubangijinmu Yesu Kiristi yă kasance tare da ku.");
INSERT INTO hausa_vpl VALUES ("H21_1","083_1_1","2TH","1","1","1","Bulus, da Sila, da Timoti, Zuwa ga ikkilisiya ta Tessalonikawa ta Allah Ubanmu da Ubangiji Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("H21_2","083_1_2","2TH","1","2","2","Alheri da salama daga Allah Uba da kuma Ubangiji Yesu Kiristi, su kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("H21_3","083_1_3","2TH","1","3","3","Dole kullum mu gode wa Allah saboda ku, ’yan’uwa, haka kuwa ya dace, domin bangaskiyarku tana girma gaba-gaba, ƙaunar da kowannenku yake yi wa juna kuwa tana ƙaruwa. ");
INSERT INTO hausa_vpl VALUES ("H21_4","083_1_4","2TH","1","4","4","Saboda haka, a cikin ikkilisiyoyin Allah muna taƙama game da daurewarku da kuma bangaskiyarku cikin dukan tsanani da gwaje-gwajen da kuke sha. ");
INSERT INTO hausa_vpl VALUES ("H21_5","083_1_5","2TH","1","5","5","Dukan wannan yana tabbatar cewa hukuncin Allah daidai ne, saboda haka kuma za a lissafta ku a kan kun cancanci mulkin Allah, wanda dominsa ne kuke shan wahala. ");
INSERT INTO hausa_vpl VALUES ("H21_6","083_1_6","2TH","1","6","6","Allah mai adalci ne, Zai sāka wa masu ba ku wahala da wahala ");
INSERT INTO hausa_vpl VALUES ("H21_7","083_1_7","2TH","1","7","7","yă kuma sauƙaƙa muku ku da kuke wahala, har ma da mu. Wannan zai faru sa’ad da aka bayyana Ubangiji Yesu daga sama cikin wuta mai ci tare da mala’ikunsa masu iko. ");
INSERT INTO hausa_vpl VALUES ("H21_8","083_1_8","2TH","1","8","8","Zai hukunta waɗanda ba su san Allah ba da kuma waɗanda ba su yi biyayya da bisharar Ubangijinmu Yesu ba. ");
INSERT INTO hausa_vpl VALUES ("H21_9","083_1_9","2TH","1","9","9","Za a hukunta su da madawwamiyar hallaka a kuma kau da su daga gaban Ubangiji da kuma daga ɗaukakar ikonsa ");
INSERT INTO hausa_vpl VALUES ("H21_10","083_1_10","2TH","1","10","10","a ranar da zai dawo don a ɗaukaka shi a cikin mutanensa masu tsarki, yă kuma zama abin banmamaki ga dukan waɗanda suka gaskata. Wannan ya haɗa har da ku, domin kun gaskata shaidar da muka yi muku. ");
INSERT INTO hausa_vpl VALUES ("H21_11","083_1_11","2TH","1","11","11","Sane da wannan, kullum muna addu’a saboda ku, don Allahnmu yă sa ku cancanci kiransa, ta wurin ikonsa kuma yă cika kowace manufarku mai kyau da kuma kowane aikin da bangaskiyarku ta iza. ");
INSERT INTO hausa_vpl VALUES ("H21_12","083_1_12","2TH","1","12","12","Muna wannan addu’a don sunan Ubangijinmu Yesu yă sami ɗaukaka a cikinku, ku kuma a cikinsa, bisa ga alherin Allahnmu da na Ubangiji Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("H22_1","083_2_1","2TH","2","1","1","Game da dawowar Ubangijinmu Yesu Kiristi da game da tattara mu gare shi, muna roƙonku, ’yan’uwa, ");
INSERT INTO hausa_vpl VALUES ("H22_2","083_2_2","2TH","2","2","2","kada ku yi saurin jijjiguwa ko kuwa hankalinku yă tashi ta wurin wani annabci, rahoto ko wasiƙar da an ce daga wurinmu ne, cewa ranar Ubangiji ta riga ta zo. ");
INSERT INTO hausa_vpl VALUES ("H22_3","083_2_3","2TH","2","3","3","Kada ku bar wani yă ruɗe ku ko ta yaya, gama wannan rana ba za tă zo ba sai an yi tawayen nan an kuma bayyana mutumin tawayen nan, mutumin da aka ƙaddara ga hallaka. ");
INSERT INTO hausa_vpl VALUES ("H22_4","083_2_4","2TH","2","4","4","Zai yi gāba yă kuma ɗaukaka kansa a bisa kome da ya shafe sunan Allah, ko kuma ake yi wa sujada, domin yă kafa kansa a haikalin Allah, yana shelar kansa a kan shi Allah ne. ");
INSERT INTO hausa_vpl VALUES ("H22_5","083_2_5","2TH","2","5","5","Ba ku tuna ba cewa sa’ad da nake tare da ku nakan gaya muku waɗannan abubuwa? ");
INSERT INTO hausa_vpl VALUES ("H22_6","083_2_6","2TH","2","6","6","Yanzu kuwa kun san abin da yake hana shi, wannan yana faruwa ne don a bayyana shi a daidai lokaci. ");
INSERT INTO hausa_vpl VALUES ("H22_7","083_2_7","2TH","2","7","7","Gama ikon asirin tawaye ya riga ya fara aiki; sai dai wannan da yake hana shi zai ci gaba da yin haka sai an kau da shi. ");
INSERT INTO hausa_vpl VALUES ("H22_8","083_2_8","2TH","2","8","8","Sa’an nan za a bayyana mai tawayen, Ubangiji Yesu kuwa zai hamɓare shi da numfashin bakinsa yă kuma hallaka shi da darajar dawowarsa. ");
INSERT INTO hausa_vpl VALUES ("H22_9","083_2_9","2TH","2","9","9","Zuwan mai tawayen nan zai zama ta wurin aikin Shaiɗan da aka bayyana cikin kowane irin ayyukan banmamaki, alamu da abubuwan banmamaki na ƙarya, ");
INSERT INTO hausa_vpl VALUES ("H22_10","083_2_10","2TH","2","10","10","da kuma cikin kowace irin muguntar da take ruɗin waɗanda suke hallaka. Sun hallaka ne domin sun ƙi su ƙaunaci gaskiya don su sami ceto. ");
INSERT INTO hausa_vpl VALUES ("H22_11","083_2_11","2TH","2","11","11","Saboda haka Allah zai aiko musu da babban ruɗu don su gaskata ƙarya ");
INSERT INTO hausa_vpl VALUES ("H22_12","083_2_12","2TH","2","12","12","don kuma a hukunta dukan waɗanda ba su gaskata gaskiyar ba sai dai suke jin daɗin mugunta. ");
INSERT INTO hausa_vpl VALUES ("H22_13","083_2_13","2TH","2","13","13","Amma dole kullum mu gode wa Allah dominku, ’yan’uwa waɗanda Ubangiji ya ƙaunace, domin daga farko Allah ya zaɓe ku don a cece ku ta wurin aikin tsarkakewar Ruhu da kuma ta wurin gaskatawa da gaskiya. ");
INSERT INTO hausa_vpl VALUES ("H22_14","083_2_14","2TH","2","14","14","Ya kira ku ga wannan ta wurin bishararmu, don ku sami rabo a cikin ɗaukakar Ubangijinmu Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("H22_15","083_2_15","2TH","2","15","15","Saboda haka fa, ’yan’uwa, sai ku tsaya daram ku riƙe koyarwar da muka miƙa muku, ko ta wurin maganar baki ko kuma ta wurin wasiƙa. ");
INSERT INTO hausa_vpl VALUES ("H22_16","083_2_16","2TH","2","16","16","Ubangijinmu Yesu Kiristi kansa da kuma Allah Ubanmu, wanda ya ƙaunace mu kuma ta wurin alherinsa yă ba mu madawwamiyar ƙarfafawa da kyakkyawar bege, ");
INSERT INTO hausa_vpl VALUES ("H22_17","083_2_17","2TH","2","17","17","yă ƙarfafa zukatanku yă kuma gina ku cikin kowane aikin nagari da kuma magana. ");
INSERT INTO hausa_vpl VALUES ("H23_1","083_3_1","2TH","3","1","1","A ƙarshe, ’yan’uwa, ku yi mana addu’a domin saƙon Ubangiji yă yi saurin bazuwa a kuma girmama shi, kamar yadda yake a wurinku. ");
INSERT INTO hausa_vpl VALUES ("H23_2","083_3_2","2TH","3","2","2","Ku kuma yi addu’a yadda za a cece mu daga mugayen mutane masu mugunta, gama ba kowa ba ne yake da bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("H23_3","083_3_3","2TH","3","3","3","Ubangiji mai aminci ne, zai ƙarfafa ku, yă kuma tsare ku daga mugun nan. ");
INSERT INTO hausa_vpl VALUES ("H23_4","083_3_4","2TH","3","4","4","Muna da tabbaci cikin Ubangiji cewa kuna bin umarnai da muka yi muku, za ku kuma ci gaba da yin abubuwan da muka umarta. ");
INSERT INTO hausa_vpl VALUES ("H23_5","083_3_5","2TH","3","5","5","Bari Ubangiji yă bi da zukatanku ga ƙaunan nan ta Allah da kuma jimirin nan na Kiristi. ");
INSERT INTO hausa_vpl VALUES ("H23_6","083_3_6","2TH","3","6","6","A cikin sunan Ubangiji Yesu Kiristi, muna muku umarni, ’yan’uwa, da ku kiyaye kanku daga kowane ɗan’uwa mai zaman banza da ba ya rayuwa bisa ga koyarwar da kuka karɓa daga wurinmu. ");
INSERT INTO hausa_vpl VALUES ("H23_7","083_3_7","2TH","3","7","7","Gama ku kanku kun san yadda ya kamata ku bi gurbinmu. Ba mu yi zaman banza sa’ad da muke tare da ku ba, ");
INSERT INTO hausa_vpl VALUES ("H23_8","083_3_8","2TH","3","8","8","ba mu kuwa ci abincin kowa ba tare da ba mu biya ba. A maimakon haka, mun yi aiki dare da rana, muna fama muna wahala kuma don kada mu nawaita wa waninku. ");
INSERT INTO hausa_vpl VALUES ("H23_9","083_3_9","2TH","3","9","9","Mun yi wannan, ba don ba mu da ’yancin karɓar irin taimakon nan ba ne, sai dai domin mu zama gurbin da za ku bi. ");
INSERT INTO hausa_vpl VALUES ("H23_10","083_3_10","2TH","3","10","10","Ko ma a sa’ad da muke tare da ku, mun ba ku wannan umarni cewa, “In mutum ya ƙi yin aiki, kada a ba shi abinci.” ");
INSERT INTO hausa_vpl VALUES ("H23_11","083_3_11","2TH","3","11","11","Mun ji cewa waɗansunku suna zaman banza. Ba sa aikin kome; sai shisshigi kurum. ");
INSERT INTO hausa_vpl VALUES ("H23_12","083_3_12","2TH","3","12","12","Irin waɗannan mutane muna ba da umarni muna kuma gargaɗe su cikin Ubangiji Yesu Kiristi su natsu su kuma nemi abincin da suke ci. ");
INSERT INTO hausa_vpl VALUES ("H23_13","083_3_13","2TH","3","13","13","Game da ku kuma ’yan’uwa, kada ku gaji da yin abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("H23_14","083_3_14","2TH","3","14","14","In wani bai yi biyayya da umarninmu a wannan wasiƙa ba, sai fa ku lura da shi. Kada ku haɗa kai da shi, don yă ji kunya. ");
INSERT INTO hausa_vpl VALUES ("H23_15","083_3_15","2TH","3","15","15","Duk da haka kada ku mai da shi abokin gāba, sai dai ku gargaɗe shi a matsayin ɗan’uwa. ");
INSERT INTO hausa_vpl VALUES ("H23_16","083_3_16","2TH","3","16","16","Yanzu, bari Ubangiji mai salama kansa yă ba ku salama a kowane lokaci da kuma a ta kowace hanya. Ubangiji yă kasance tare da ku duka. ");
INSERT INTO hausa_vpl VALUES ("H23_17","083_3_17","2TH","3","17","17","Ni, Bulus, nake rubuta wannan gaisuwa da hannuna, wannan ce shaida a kowace wasiƙata, haka nake rubutu. ");
INSERT INTO hausa_vpl VALUES ("H23_18","083_3_18","2TH","3","18","18","Alherin Ubangijinmu Yesu Kiristi yă kasance tare da ku duka.");
INSERT INTO hausa_vpl VALUES ("T11_1","084_1_1","1TI","1","1","1","Bulus, manzon Kiristi Yesu ta wurin umarnin Allah Mai Cetonmu da kuma na Yesu Kiristi begenmu, ");
INSERT INTO hausa_vpl VALUES ("T11_2","084_1_2","1TI","1","2","2","Zuwa ga Timoti ɗana na gaske cikin bangaskiya. Alheri, jinƙai da kuma salama daga Allah Uba da Kiristi Yesu Ubangijinmu, su kasance tare da kai. ");
INSERT INTO hausa_vpl VALUES ("T11_3","084_1_3","1TI","1","3","3","Kamar yadda na gargaɗe ka sa’ad da zan je Makidoniya, ka zauna can Afisa domin ka umarci waɗansu mutane kada su koyar da ƙa’idodin ƙarya nan gaba ");
INSERT INTO hausa_vpl VALUES ("T11_4","084_1_4","1TI","1","4","4","ko su ba da kansu ga tatsuniyoyi da ƙididdigar asali marar iyaka. Waɗannan suna kawo faɗa a maimakon aikin Allah wanda yake ta wurin bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("T11_5","084_1_5","1TI","1","5","5","Maƙasudin wannan umarnin dai ƙauna ce, wadda take zuwa daga zuciya mai tsabta da lamiri mai kyau da kuma sahihiyar bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("T11_6","084_1_6","1TI","1","6","6","Waɗansu sun bauɗe daga waɗannan al’amura, suka koma ga maganganu marasa ma’ana. ");
INSERT INTO hausa_vpl VALUES ("T11_7","084_1_7","1TI","1","7","7","So suke su zama malaman doka, ba tare da fahimtar abin da suke faɗa ba, balle abubuwan da suke ta nacewa a kai. ");
INSERT INTO hausa_vpl VALUES ("T11_8","084_1_8","1TI","1","8","8","Mun san cewa doka tana da kyau in an yi amfani da ita yadda ya kamata. ");
INSERT INTO hausa_vpl VALUES ("T11_9","084_1_9","1TI","1","9","9","Mun kuma san cewa an yi doka ba domin masu adalci ba sai dai masu tawaye, da marasa biyayya, da marasa bin Allah, da masu zunubi, da marasa tsarkaka, da masu saɓon Allah, da masu kashe iyaye maza da mata, da masu kisankai, ");
INSERT INTO hausa_vpl VALUES ("T11_10","084_1_10","1TI","1","10","10","da masu zina da kuma da maza masu kwana da maza, ko mata masu kwana da mata, da masu cinikin bayi da masu ƙarya da kuma masu shaidar ƙarya, da kuma duk wani abin da ya saɓa wa sahihiyar koyarwa, ");
INSERT INTO hausa_vpl VALUES ("T11_11","084_1_11","1TI","1","11","11","da take bisa ga bishara mai ɗaukaka ta Allah mai albarka, wadda ya danƙa mini. ");
INSERT INTO hausa_vpl VALUES ("T11_12","084_1_12","1TI","1","12","12","Na gode wa Kiristi Yesu Ubangijinmu, wanda ya ba ni ƙarfi, saboda ya amince da ni, har ya sa ni aikinsa. ");
INSERT INTO hausa_vpl VALUES ("T11_13","084_1_13","1TI","1","13","13","Ko da yake a dā ni mai saɓo da mai tsanantawa da kuma mai rikici ne, aka nuna mini jinƙai saboda na yi haka cikin jahilci ne da kuma rashin bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("T11_14","084_1_14","1TI","1","14","14","An zubo mini alherin Ubangijinmu a yalwace, tare da bangaskiya da ƙaunar da take cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("T11_15","084_1_15","1TI","1","15","15","Ga wata magana tabbatacciya wadda ta cancanci cikakkiyar karɓa. Kiristi Yesu ya zo duniya domin ceton masu zunubi, wanda nake mafi muni a cikinsu. ");
INSERT INTO hausa_vpl VALUES ("T11_16","084_1_16","1TI","1","16","16","Amma saboda wannan dalilin ne aka nuna mini jinƙai domin ta wurina, mafi zunubi duka, Kiristi Yesu yă iya bayyana matuƙar haƙurinsa a matsayin misali ga waɗanda za su gaskata shi su kuma sami rai madawwami. ");
INSERT INTO hausa_vpl VALUES ("T11_17","084_1_17","1TI","1","17","17","Bari girma da ɗaukaka su tabbata har abada abadin ga Sarki madawwami, wanda ba ya mutuwa, wanda ba a ganinsa, wanda kuma shi ne kaɗai Allah! Amin. ");
INSERT INTO hausa_vpl VALUES ("T11_18","084_1_18","1TI","1","18","18","Timoti, ɗana, na ba ka wannan umarni bisa ga annabce-annabcen da aka yi a dā game da kai, domin ta wurin binsu ka iya yin yaƙi mai kyau, ");
INSERT INTO hausa_vpl VALUES ("T11_19","084_1_19","1TI","1","19","19","kana riƙe da bangaskiya da kuma lamiri mai kyau. Gama waɗansu mutane, saboda ƙin kasa kunne ga lamirinsu, suka lalatar da bangaskiyarsu. ");
INSERT INTO hausa_vpl VALUES ("T11_20","084_1_20","1TI","1","20","20","Cikinsu kuwa akwai Himenayus da Alekzanda, waɗanda na miƙa ga Shaiɗan don su horo su bar yin saɓo. ");
INSERT INTO hausa_vpl VALUES ("T12_1","084_2_1","1TI","2","1","1","Da farko dai, ina gargaɗe ku cewa a yi roƙe-roƙe, ana addu’o’i, ana yin addu’a a madadin waɗansu da kuma a yi godiya saboda kowane mutum ");
INSERT INTO hausa_vpl VALUES ("T12_2","084_2_2","1TI","2","2","2","da sarakuna da dukan masu mulki, domin mu zauna lafiya, rai kuma kwance, muna bin Allah sosai a cikin natsuwa. ");
INSERT INTO hausa_vpl VALUES ("T12_3","084_2_3","1TI","2","3","3","Wannan yana da kyau, yakan kuma gamshi Allah Mai Cetonmu, ");
INSERT INTO hausa_vpl VALUES ("T12_4","084_2_4","1TI","2","4","4","wanda yake so dukan mutane su sami ceto su kuma zo ga sanin gaskiya. ");
INSERT INTO hausa_vpl VALUES ("T12_5","084_2_5","1TI","2","5","5","Gama Allah ɗaya ne, matsakanci kuma ɗaya tsakanin Allah da mutane, shi ne kuwa Kiristi Yesu, ");
INSERT INTO hausa_vpl VALUES ("T12_6","084_2_6","1TI","2","6","6","wanda ya ba da kansa fansa domin dukan mutane, shaidar da aka bayar a daidai lokaci. ");
INSERT INTO hausa_vpl VALUES ("T12_7","084_2_7","1TI","2","7","7","Don haka ne aka sa ni mai wa’azi, da manzo kuma, gaskiya nake faɗa, ba ƙarya ba, na kuma zama malami mai koya wa al’ummai al’amarin bangaskiya da kuma na gaskiya. ");
INSERT INTO hausa_vpl VALUES ("T12_8","084_2_8","1TI","2","8","8","Ina so maza a ko’ina su ɗaga hannuwansu masu tsarki cikin addu’a, ba tare da fushi ko faɗa ba. ");
INSERT INTO hausa_vpl VALUES ("T12_9","084_2_9","1TI","2","9","9","Ina kuma so mata su lura su yi wa kansu adon da ya cancanta, da rigunan da suka dace, ba da adon kitso ko sa kayan zinariya ko lu’ulu’u ko kuma tufafi masu tsada ba, ");
INSERT INTO hausa_vpl VALUES ("T12_10","084_2_10","1TI","2","10","10","sai dai su yi ayyuka masu kyan da suka dace da matan da suke masu bauta wa Allah. ");
INSERT INTO hausa_vpl VALUES ("T12_11","084_2_11","1TI","2","11","11","Ya kamata mace ta riƙa koyo cikin natsuwa da cikakkiyar biyayya. ");
INSERT INTO hausa_vpl VALUES ("T12_12","084_2_12","1TI","2","12","12","Ban ba mace izini ta koyar ko tă yi mulki a kan namiji ba; sai dai ta zauna shiru. ");
INSERT INTO hausa_vpl VALUES ("T12_13","084_2_13","1TI","2","13","13","Gama Adamu ne aka fara halitta, sa’an nan Hawwa’u. ");
INSERT INTO hausa_vpl VALUES ("T12_14","084_2_14","1TI","2","14","14","Ba kuma Adamu ne aka yaudara ba; macen ce aka yaudara ta kuma zama mai zunubi. ");
INSERT INTO hausa_vpl VALUES ("T12_15","084_2_15","1TI","2","15","15","Amma mata Za tă sami ceto za su sami ceto ta wurin haihuwa, in suka ci gaba cikin bangaskiya, ƙauna da kuma tsarki tare da halin sanin ya kamata. ");
INSERT INTO hausa_vpl VALUES ("T13_1","084_3_1","1TI","3","1","1","Ga wata tabbatacciyar magana. In wani ya sa zuciyarsa a kan zama mai kula da ikkilisiya, yana marmarin yin aiki mai daraja ne. ");
INSERT INTO hausa_vpl VALUES ("T13_2","084_3_2","1TI","3","2","2","To, dole mai kula da Ikkilisiya yă kasance marar abin zargi, mijin mace guda, mai sauƙinkai, mai kamunkai, wanda ake girmama, mai karɓan baƙi, mai iya koyarwa, ");
INSERT INTO hausa_vpl VALUES ("T13_3","084_3_3","1TI","3","3","3","ba mai buguwa ba, ba mai rikici ba sai dai mai hankali, ba mai yawan faɗa ba, ba kuma mai yawan son kuɗi ba. ");
INSERT INTO hausa_vpl VALUES ("T13_4","084_3_4","1TI","3","4","4","Dole yă iya tafiyar da iyalinsa da kyau, yă kuma tabbata cewa ’ya’yansa suna yin masa biyayya da ladabin da ya dace. ");
INSERT INTO hausa_vpl VALUES ("T13_5","084_3_5","1TI","3","5","5","(In mutum bai san yadda zai tafiyar da iyalinsa ba, yaya zai iya kula da ikkilisiyar Allah?) ");
INSERT INTO hausa_vpl VALUES ("T13_6","084_3_6","1TI","3","6","6","Kada yă zama sabon tuba, in ba haka zai zama mai girman kai yă kuma fāɗa cikin irin hukuncin da ya fāɗo wa Iblis. ");
INSERT INTO hausa_vpl VALUES ("T13_7","084_3_7","1TI","3","7","7","Dole kuma yă kasance da shaida mai kyau ga waɗanda suke na waje, don kada yă zama abin kunya yă kuma fāɗa cikin tarkon Iblis. ");
INSERT INTO hausa_vpl VALUES ("T13_8","084_3_8","1TI","3","8","8","Haka masu hidima a cikin ikkilisiya; su ma, su zama maza da sun cancanci girmamawa, masu gaskiya, ba masu yawan shan ruwan inabi ba, ba masu kwaɗayin ƙazamar riba ba. ");
INSERT INTO hausa_vpl VALUES ("T13_9","084_3_9","1TI","3","9","9","Dole su riƙe asirin bangaskiya su kuma kasance da lamiri mai tsabta. ");
INSERT INTO hausa_vpl VALUES ("T13_10","084_3_10","1TI","3","10","10","Dole a fara gwada su tukuna; sa’an nan in ba a sami wani abin zargi game da su ba, sai su shiga aikin masu hidima. ");
INSERT INTO hausa_vpl VALUES ("T13_11","084_3_11","1TI","3","11","11","A haka kuma, dole matansu su zama matan da suka cancanci girmamawa, ba masu gulma ba, sai dai masu sauƙinkai da kuma masu aminci a cikin kome. ");
INSERT INTO hausa_vpl VALUES ("T13_12","084_3_12","1TI","3","12","12","Dole mai hidimar ikkilisiya yă zama mijin mace guda dole kuma yă iya tafiyar da ’ya’yansa da kuma iyalinsa da kyau. ");
INSERT INTO hausa_vpl VALUES ("T13_13","084_3_13","1TI","3","13","13","Waɗanda suke hidima da kyau suna samar wa kansu kyakkyawan suna da kuma cikakken tabbatarwa a cikin bangaskiyarsu cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("T13_14","084_3_14","1TI","3","14","14","Ko da yake ina sa zuciya zo wurinka nan ba da daɗewa ba, ina rubuta muka waɗannan umarnai domin, ");
INSERT INTO hausa_vpl VALUES ("T13_15","084_3_15","1TI","3","15","15","in na yi jinkiri, za ka san yadda ya kamata mutane su tafiyar da halayensu a cikin jama’ar Allah, wadda take ikkilisiyar Allah rayayye, ginshiƙi da kuma tushen gaskiya. ");
INSERT INTO hausa_vpl VALUES ("T13_16","084_3_16","1TI","3","16","16","Ba shakka, asirin addini da girma yake. Ya bayyana cikin jiki, Ruhu ya nuna shi adali ne, mala’iku suka gan shi, aka yi wa’azinsa cikin al’ummai, aka gaskata shi a duniya, aka ɗauke shi sama cikin ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("T14_1","084_4_1","1TI","4","1","1","Ruhu a sarari ya faɗa cewa a kwanakin ƙarshe waɗansu za su watsar da bangaskiya su bi ruhohi masu ruɗu da kuma abubuwan da aljanu suke koyarwa. ");
INSERT INTO hausa_vpl VALUES ("T14_2","084_4_2","1TI","4","2","2","Irin koyarwan nan tana zuwa ne daga waɗansu munafukai maƙaryata, waɗanda aka yi wa lamirinsu kaca-kaca. ");
INSERT INTO hausa_vpl VALUES ("T14_3","084_4_3","1TI","4","3","3","Suna hana mutane yin aure suna kuma umarce su kada su ci waɗansu irin abinci, waɗanda Allah ya halitta don waɗanda suka gaskata suka kuma san gaskiya, su karɓa da godiya. ");
INSERT INTO hausa_vpl VALUES ("T14_4","084_4_4","1TI","4","4","4","Gama duk abin da Allah ya halitta yana da kyau, kada kuma a ƙi kome in dai an karɓe shi da godiya, ");
INSERT INTO hausa_vpl VALUES ("T14_5","084_4_5","1TI","4","5","5","domin an tsarkake shi ta wurin maganar Allah da kuma addu’a. ");
INSERT INTO hausa_vpl VALUES ("T14_6","084_4_6","1TI","4","6","6","In ka nuna wa ’yan’uwa waɗannan abubuwa, za ka zama mai hidima mai kyau na Kiristi Yesu, wanda aka goya cikin gaskiyar bangaskiya da kuma koyarwa mai kyau wadda ka bi. ");
INSERT INTO hausa_vpl VALUES ("T14_7","084_4_7","1TI","4","7","7","Ka kiyaye kanka daga tatsuniyoyi na rashin tsoron Allah da labaru banza na tsofaffin mata; a maimako, ka hori kanka ga zama mai tsoron Allah. ");
INSERT INTO hausa_vpl VALUES ("T14_8","084_4_8","1TI","4","8","8","Gama horon jiki yana da amfani, amma tsoron Allah yana da amfani ga kowane abu, yana da albarka ga rai na yanzu da kuma rai mai zuwa. ");
INSERT INTO hausa_vpl VALUES ("T14_9","084_4_9","1TI","4","9","9","Wannan magana tabbatacciya ce wadda ta cancanci cikakkiyar karɓa. ");
INSERT INTO hausa_vpl VALUES ("T14_10","084_4_10","1TI","4","10","10","Saboda wannan kuwa muke wahala da kuma fama, domin mun sa begenmu ga Allah mai rai, wanda yake Mai Ceton dukan mutane, musamman na waɗanda suka ba da gaskiya. ");
INSERT INTO hausa_vpl VALUES ("T14_11","084_4_11","1TI","4","11","11","Ka umarta ka kuma koyar da waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("T14_12","084_4_12","1TI","4","12","12","Kada ka bar wani yă rena ka domin kai matashi ne, sai dai ka zama gurbi ga masu bi cikin magana, cikin rayuwa, cikin ƙauna, cikin bangaskiya da kuma cikin zaman tsarki. ");
INSERT INTO hausa_vpl VALUES ("T14_13","084_4_13","1TI","4","13","13","Kafin in zo, ka ci gaba da karanta wa mutane Nassi, da yin wa’azi, da kuma koyarwa. ");
INSERT INTO hausa_vpl VALUES ("T14_14","084_4_14","1TI","4","14","14","Kada ka yi sakaci da baiwarka, wadda aka ba ka ta wurin saƙon annabci sa’ad da ƙungiyar dattawa suka ɗibiya hannuwa a kanka. ");
INSERT INTO hausa_vpl VALUES ("T14_15","084_4_15","1TI","4","15","15","Ka yi ƙwazo cikin waɗannan batuttuwa; ka ba da kanka gaba ɗaya gare su, don kowa yă ga ci gabanka. ");
INSERT INTO hausa_vpl VALUES ("T14_16","084_4_16","1TI","4","16","16","Ka kula da rayuwarka da kuma koyarwarka da kyau. Ka daure a cikinsu, domin in ka yi, za ka ceci kanka da kuma masu sauraronka. ");
INSERT INTO hausa_vpl VALUES ("T15_1","084_5_1","1TI","5","1","1","Kada ka tsawata wa dattijo, sai dai ka gargaɗe shi a matsayinka. Ka ɗauki samari a matsayin ’yan’uwanka, ");
INSERT INTO hausa_vpl VALUES ("T15_2","084_5_2","1TI","5","2","2","tsofaffin mata kuwa sai ka ce uwaye, ’yan mata kuma a matsayin ’yan’uwa da matuƙar tsarki. ");
INSERT INTO hausa_vpl VALUES ("T15_3","084_5_3","1TI","5","3","3","Ka girmama gwauraye waɗanda suke cikin bukata ta ainihi. ");
INSERT INTO hausa_vpl VALUES ("T15_4","084_5_4","1TI","5","4","4","Amma in gwauruwa tana da ’ya’ya ko jikoki, to, sai su fara koyon yin ayyukan addininsu ga danginsu, ta haka za su sāka wa iyayensu da kakanninsu, gama wannan yakan gamshi Allah. ");
INSERT INTO hausa_vpl VALUES ("T15_5","084_5_5","1TI","5","5","5","Gwauruwa wadda ba ta da kowa da zai taimake ta, za tă sa zuciyarta ga Allah, tana roƙo da addu’o’i dare da rana gare shi don taimako. ");
INSERT INTO hausa_vpl VALUES ("T15_6","084_5_6","1TI","5","6","6","Amma gwauruwar da take zaman jin daɗi, matacciya ce tun tana da rai. ");
INSERT INTO hausa_vpl VALUES ("T15_7","084_5_7","1TI","5","7","7","Ka umarce su game da waɗannan abubuwa, don su kasance marasa abin zargi. ");
INSERT INTO hausa_vpl VALUES ("T15_8","084_5_8","1TI","5","8","8","In wani bai kula da danginsa ba, musamman iyalinsa na kurkusa, ya mūsunta bangaskiya ke nan, ya kuma fi marar ba da gaskiya muni. ");
INSERT INTO hausa_vpl VALUES ("T15_9","084_5_9","1TI","5","9","9","Kada a lasafta gwauruwa cikin jerin gwauraye sai ta wuce shekara sittin, ta kuma yi zaman aminci ga mijinta, ");
INSERT INTO hausa_vpl VALUES ("T15_10","084_5_10","1TI","5","10","10","aka kuma santa sosai saboda ayyuka masu kyau, kamar renon ’ya’ya, da karɓan baƙi, tana yi wa tsarkaka hidima, tana taimakon waɗanda suke cikin wahala tana kuma ba da kanta ga yin kowane aikin mai kyau. ");
INSERT INTO hausa_vpl VALUES ("T15_11","084_5_11","1TI","5","11","11","Game da gwauraye masu ƙuruciya kuwa, kada ka sa su cikin wannan lissafi. Gama sa’ad da sha’awar jikinsu ta kāsa daurewa game da wa’adin da suka yi da Kiristi, sai su so yin aure. ");
INSERT INTO hausa_vpl VALUES ("T15_12","084_5_12","1TI","5","12","12","Ta haka suna jawo wa kansu hukunci, saboda sun karya alkawarinsu na farko. ");
INSERT INTO hausa_vpl VALUES ("T15_13","084_5_13","1TI","5","13","13","Ban da haka, sukan koyi zaman banza, suna zirga-zirga gida-gida. Ba kawai sun zama masu zaman banza ba, har ma sun zama masu gulma da masu shisshigi, suna faɗin abubuwan da bai kamata su faɗa ba. ");
INSERT INTO hausa_vpl VALUES ("T15_14","084_5_14","1TI","5","14","14","Saboda haka ina ba wa gwauraye masu ƙuruciya shawara su yi aure, su sami ’ya’ya, su lura da gidajensu kada kuwa su ba abokin gāba zarafin ɓata suna. ");
INSERT INTO hausa_vpl VALUES ("T15_15","084_5_15","1TI","5","15","15","Waɗansu dai sun riga sun bauɗe sun bi Shaiɗan. ");
INSERT INTO hausa_vpl VALUES ("T15_16","084_5_16","1TI","5","16","16","In mace mai bi tana da gwauraye a iyalinta, ya kamata tă taimake su, kada tă bar wa ikkilisiya wannan nauyi, domin ikkilisiya ta sami zarafin taimakon gwaurayen da suke da bukata ta ainihi. ");
INSERT INTO hausa_vpl VALUES ("T15_17","084_5_17","1TI","5","17","17","Dattawan da suka bi da al’amuran ikkilisiya da kyau sun cancanci girmamawa ninki biyu, musamman waɗanda aikinsu wa’azi ne da kuma koyarwa. ");
INSERT INTO hausa_vpl VALUES ("T15_18","084_5_18","1TI","5","18","18","Gama Nassi ya ce, “Kada ka sa wa bijimi takunkumi yayinda yake sussukar hatsi,” da kuma, “Ma’aikaci ya cancanci hakkinsa.” ");
INSERT INTO hausa_vpl VALUES ("T15_19","084_5_19","1TI","5","19","19","Kada ka saurari ƙara game da dattijo sai da shaidu biyu ko uku. ");
INSERT INTO hausa_vpl VALUES ("T15_20","084_5_20","1TI","5","20","20","Amman waɗannan dattawa waɗanda suke yin zunubi kuwa sai ka kwaɓe su a gaban jama’a, don saura su ji tsoro. ");
INSERT INTO hausa_vpl VALUES ("T15_21","084_5_21","1TI","5","21","21","Na gama ka da Allah, da Kiristi Yesu, da kuma zaɓaɓɓun mala’iku, ka kiyaye waɗannan abubuwa ƙwarai da gaske, kada ka nuna bambanci. ");
INSERT INTO hausa_vpl VALUES ("T15_22","084_5_22","1TI","5","22","22","Kada ka yi garajen ɗibiya hannuwa, kada kuma ka yi tarayya a cikin zunuban waɗansu. Ka kiyaye kanka da tsarki. ");
INSERT INTO hausa_vpl VALUES ("T15_23","084_5_23","1TI","5","23","23","Ka daina shan ruwa kaɗai, yi amfani da ruwan inabi kaɗan saboda cikinka da kuma yawan rashin lafiyarka. ");
INSERT INTO hausa_vpl VALUES ("T15_24","084_5_24","1TI","5","24","24","Zunuban waɗansu mutane a fili suke, suna shan gabansu zuwa hukunci; zunuban waɗansu kuwa sukan bi su a baya. ");
INSERT INTO hausa_vpl VALUES ("T15_25","084_5_25","1TI","5","25","25","Haka ma ayyuka nagari a fili suke, ko ba ma a fili suke ba, ba a iya ɓoye su. ");
INSERT INTO hausa_vpl VALUES ("T16_1","084_6_1","1TI","6","1","1","Duk waɗanda suke ƙarƙashin bauta, ya kamata su ɗauki iyayengijinsu a kan sun cancanci girmamawa matuƙa, don kada a ɓata sunan Allah da kuma koyarwarmu. ");
INSERT INTO hausa_vpl VALUES ("T16_2","084_6_2","1TI","6","2","2","Waɗanda suke da iyayengiji masu bi, to, kada su yi musu reni domin su ’yan’uwa ne. A maimako, sai ma su fi bauta musu, saboda waɗanda suke cin moriyar hidimarsu masu bi ne, ƙaunatattu ne kuma a gare su. Waɗannan su ne abubuwan da za ka koya musu ka kuma gargaɗe su. ");
INSERT INTO hausa_vpl VALUES ("T16_3","084_6_3","1TI","6","3","3","In wani yana koyarwar ƙarya bai kuma yarda da sahihiyar koyarwar Ubangijinmu Yesu Kiristi da kuma koyarwa ta tsoron Allah ba, ");
INSERT INTO hausa_vpl VALUES ("T16_4","084_6_4","1TI","6","4","4","yana cike da girman kai bai kuma san kome ba. Yana da mugun halin son gardama da muhawwara game da kalmomin da suke kawo kishi, rikici, maganar ƙeta, da mugayen zace-zace ");
INSERT INTO hausa_vpl VALUES ("T16_5","084_6_5","1TI","6","5","5","da yawan tankiya tsakanin mutane masu mugun hali, waɗanda aka raba su da gaskiya, suke kuma tsammani cewa bin Allah wata hanya ce ta samun kuɗi. ");
INSERT INTO hausa_vpl VALUES ("T16_6","084_6_6","1TI","6","6","6","Amma bin Allah da gamsuwa riba ce mai yawa. ");
INSERT INTO hausa_vpl VALUES ("T16_7","084_6_7","1TI","6","7","7","Gama ba mu zo duniya da kome ba, ba kuwa za mu fita daga cikinta da kome ba. ");
INSERT INTO hausa_vpl VALUES ("T16_8","084_6_8","1TI","6","8","8","In dai muna da abinci da sutura, ai, sai mu gamsu da su. ");
INSERT INTO hausa_vpl VALUES ("T16_9","084_6_9","1TI","6","9","9","Mutanen da suke son yin arziki sukan fāɗi cikin jarraba, su fāɗa a tarko, suna mugayen sha’awace-sha’awace iri-iri na wauta da cutarwa, irin waɗanda suke dulmuyar da mutane, su kai ga lalacewa da hallaka. ");
INSERT INTO hausa_vpl VALUES ("T16_10","084_6_10","1TI","6","10","10","Gama son kuɗi shi ne tushen kowane irin mugun abu. Waɗansu mutane, don tsananin son kuɗi, sun bauɗe daga bangaskiya suka kuma jawo wa kansu da baƙin ciki iri-iri. ");
INSERT INTO hausa_vpl VALUES ("T16_11","084_6_11","1TI","6","11","11","Amma kai, mutumin Allah, ka guji duk wannan, ka kuma nemi adalci, tsoron Allah, bangaskiya, ƙauna, jimrewa da kuma hankali. ");
INSERT INTO hausa_vpl VALUES ("T16_12","084_6_12","1TI","6","12","12","Ka yi fama, kyakkyawar fama ta bangaskiya. Ka riƙi rai madawwamin nan, wanda aka kira saboda shi, sa’ad da ka yi kyakkyawar shaida a gaban shaidu masu yawa. ");
INSERT INTO hausa_vpl VALUES ("T16_13","084_6_13","1TI","6","13","13","Na umarce ka, a gaban Allah mai ba da rai ga kome, da kuma Kiristi Yesu wanda yayinda yake ba da shaida a gaban Buntus Bilatus ya yi kyakkyawar shaida, ");
INSERT INTO hausa_vpl VALUES ("T16_14","084_6_14","1TI","6","14","14","ka kiyaye wannan umarni ba tare da wani aibi ko abin zargi ba har yă bayyanuwar Ubangijinmu Yesu Kiristi, ");
INSERT INTO hausa_vpl VALUES ("T16_15","084_6_15","1TI","6","15","15","wanda Allah zai kawo a daidai lokaci, Allah, mai albarka wanda yake kaɗai Mai Mulki, Sarkin sarakuna da Ubangijin iyayengiji, ");
INSERT INTO hausa_vpl VALUES ("T16_16","084_6_16","1TI","6","16","16","wanda shi kaɗai ne marar mutuwa wanda kuma yake zaune cikin hasken da ba ya kusatuwa, wanda babu wanda ya taɓa gani ko zai iya gani. A gare shi girma da iko su tabbata har abada. Amin. ");
INSERT INTO hausa_vpl VALUES ("T16_17","084_6_17","1TI","6","17","17","Ka umarci waɗanda suke da arziki a wannan duniya kada su ɗaga kai ko su sa begensu a kan dukiyar da ba ta da tabbaci, sai dai su sa begensu ga Allah, wanda yake ba mu kome a yalwace don jin daɗinmu. ");
INSERT INTO hausa_vpl VALUES ("T16_18","084_6_18","1TI","6","18","18","Ka umarce su su yi nagarta, su wadatu cikin ayyuka nagari, su kuma zama masu bayarwa hannu sake da kuma masu niyyar yin taimako. ");
INSERT INTO hausa_vpl VALUES ("T16_19","084_6_19","1TI","6","19","19","Ta haka za su ajiye wa kansu dukiya a matsayin tushen mai ƙarfi don tsara mai zuwa, don su riƙi rai wanda yake na tabbatacce. ");
INSERT INTO hausa_vpl VALUES ("T16_20","084_6_20","1TI","6","20","20","Timoti, ka lura da abin da aka danƙa maka amana. Ka yi nesa da masu maganganun rashin tsoron Allah da kuma yawan mūsu da ake ƙarya, ake ce da shi ilimi, ");
INSERT INTO hausa_vpl VALUES ("T16_21","084_6_21","1TI","6","21","21","wanda waɗansu suka furta kuma ta yin haka suka bauɗe daga bangaskiya. Alheri yă kasance tare da ku.");
INSERT INTO hausa_vpl VALUES ("T21_1","085_1_1","2TI","1","1","1","Bulus, manzon Kiristi Yesu ta wurin nufin Allah, bisa ga alkawarin rai wanda yake cikin Kiristi Yesu, ");
INSERT INTO hausa_vpl VALUES ("T21_2","085_1_2","2TI","1","2","2","Zuwa ga Timoti, ƙaunataccen ɗana. Alheri, jinƙai da salama daga Allah Uba da kuma Kiristi Yesu Ubangijinmu, su kasance tare da kai. ");
INSERT INTO hausa_vpl VALUES ("T21_3","085_1_3","2TI","1","3","3","Na gode wa Allah wanda nake bauta wa, kamar yadda kakanni-kakannina suka yi da lamiri mai tsabta, yadda kullum dare da rana ina tuna da ku a cikin addu’o’ina. ");
INSERT INTO hausa_vpl VALUES ("T21_4","085_1_4","2TI","1","4","4","Sa’ad da na tuna da hawayenka, nakan yi marmarin ganinka, don in cika da farin ciki. ");
INSERT INTO hausa_vpl VALUES ("T21_5","085_1_5","2TI","1","5","5","An tunashe ni da sahihiyar bangaskiyarka, wadda a farko ta kasance a cikin kakarka Loyis da kuma mahaifiyarka Yunis yanzu kuwa na tabbata tana cikinka. ");
INSERT INTO hausa_vpl VALUES ("T21_6","085_1_6","2TI","1","6","6","Saboda haka, ina so in faɗakar da kai, ka lura baiwan nan ta Allah, wadda take tare da kai ta wurin ɗibiya maka hannuwana. ");
INSERT INTO hausa_vpl VALUES ("T21_7","085_1_7","2TI","1","7","7","Gama Allah bai ba mu ruhun tsoro ba, sai dai ruhun iko, na ƙauna da kuma na kamunkai. ");
INSERT INTO hausa_vpl VALUES ("T21_8","085_1_8","2TI","1","8","8","Saboda haka kada ka ji kunyar ba da shaida game da Ubangijinmu, ko kuwa ka ji kunyata, ni da nake ɗan sarƙa saboda shi. Sai dai ka haɗa kai tare da ni cikin shan wahala saboda bishara ta wurin ikon Allah, ");
INSERT INTO hausa_vpl VALUES ("T21_9","085_1_9","2TI","1","9","9","wanda ya cece mu ya kuma kira mu ga rayuwar tsarki ba saboda wani abin da muka yi ba sai dai saboda nufinsa da kuma alherinsa. An ba mu wannan alheri cikin Kiristi Yesu tun fil azal, ");
INSERT INTO hausa_vpl VALUES ("T21_10","085_1_10","2TI","1","10","10","amma yanzu an bayyana ta ta wurin bayyanuwar Mai Cetonmu, Kiristi Yesu, wanda ya hallaka mutuwa ya kuma kawo rai da rashin mutuwa a sarari ta wurin bishara. ");
INSERT INTO hausa_vpl VALUES ("T21_11","085_1_11","2TI","1","11","11","A wannan bishara ce, aka naɗa ni mai shela da manzo da kuma malami. ");
INSERT INTO hausa_vpl VALUES ("T21_12","085_1_12","2TI","1","12","12","Shi ya sa nake shan wahalar da nake sha. Duk da haka ba na jin kunya, domin na san wanda na gaskata da shi, na kuma tabbata cewa yana iya kiyaye abin da na danƙa masa amana don wancan rana. ");
INSERT INTO hausa_vpl VALUES ("T21_13","085_1_13","2TI","1","13","13","Abin da ka ji daga gare ni, ka kiyaye shi kamar tsarin sahihiyar koyarwa, cikin bangaskiya da ƙauna cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("T21_14","085_1_14","2TI","1","14","14","Ka kiyaye kyakkyawar ajiyan nan da aka danƙa maka amana, ka lura da ita da taimakon Ruhu Mai Tsarki wanda yake raye a cikinmu. ");
INSERT INTO hausa_vpl VALUES ("T21_15","085_1_15","2TI","1","15","15","Ka san cewa kowa a lardin Asiya ya juya mini baya, har da Figelus da Hermogenes. ");
INSERT INTO hausa_vpl VALUES ("T21_16","085_1_16","2TI","1","16","16","Bari Ubangiji yă yi wa iyalin Onesiforus jinƙai, domin sau da dama yakan wartsakar da ni, bai kuma ji kunyar sarƙoƙina ba. ");
INSERT INTO hausa_vpl VALUES ("T21_17","085_1_17","2TI","1","17","17","A maimakon haka ma, sa’ad da yake a Roma, ya neme ni ido a rufe sai da ya same ni. ");
INSERT INTO hausa_vpl VALUES ("T21_18","085_1_18","2TI","1","18","18","Bari Ubangiji yă sa yă sami jinƙai daga Ubangiji a wancan ranar! Ka sani sarai yadda ya taimake ni a hanyoyi dabam-dabam a Afisa. ");
INSERT INTO hausa_vpl VALUES ("T22_1","085_2_1","2TI","2","1","1","Kai kuma, ɗana, ka yi ƙarfi cikin alherin da yake cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("T22_2","085_2_2","2TI","2","2","2","Abubuwan da ka ji na faɗa a gaban shaidu masu yawa kuwa ka danƙa wa amintattun mutane waɗanda su ma za su iya koya wa waɗansu. ");
INSERT INTO hausa_vpl VALUES ("T22_3","085_2_3","2TI","2","3","3","Ka jure wa shan wahala tare da mu kamar soja mai kyau na Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("T22_4","085_2_4","2TI","2","4","4","Ba wanda yake aikin soja da zai sa kansa a sha’anin mutumin da ba ya aikin soja, domin yakan so yă gamshi wanda ya ɗauke shi soja. ");
INSERT INTO hausa_vpl VALUES ("T22_5","085_2_5","2TI","2","5","5","Haka ma, in wani ya yi gasa a matsayi shi ɗan wasa ne, ba ya sami rawanin nasara, sai in ya yi gasar bisa ga dokoki. ");
INSERT INTO hausa_vpl VALUES ("T22_6","085_2_6","2TI","2","6","6","Manomi mai aiki sosai ya kamata yă zama na fari wajen samun rabon amfanin gona. ");
INSERT INTO hausa_vpl VALUES ("T22_7","085_2_7","2TI","2","7","7","Ka yi tunani a kan abin da nake faɗi, gama Ubangiji zai ba ka ganewa cikin dukan wannan. ");
INSERT INTO hausa_vpl VALUES ("T22_8","085_2_8","2TI","2","8","8","Ka tuna da Yesu Kiristi, wanda aka tā da shi daga matattu, zuriyar Dawuda, wanda shi ne bisharata, ");
INSERT INTO hausa_vpl VALUES ("T22_9","085_2_9","2TI","2","9","9","wadda nake shan wahala har ga daurin sarƙa kamar mai laifi. Amma Maganar Allah ba a daure take ba. ");
INSERT INTO hausa_vpl VALUES ("T22_10","085_2_10","2TI","2","10","10","Saboda haka nake jure kome saboda zaɓaɓɓu, domin su ma su sami ceton da yake cikin Kiristi Yesu, tare da madawwamiyar ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("T22_11","085_2_11","2TI","2","11","11","Ga wata magana tabbatacciya, “In muka mutu tare da shi, za mu rayu tare da shi; ");
INSERT INTO hausa_vpl VALUES ("T22_12","085_2_12","2TI","2","12","12","in muka jimre, za mu yi mulki tare da shi. In muka yi mūsunsa, shi ma zai yi mūsunmu; ");
INSERT INTO hausa_vpl VALUES ("T22_13","085_2_13","2TI","2","13","13","in ba mu da aminci, shi dai mai aminci ne, domin shi ba zai iya mūsun kansa ba.” ");
INSERT INTO hausa_vpl VALUES ("T22_14","085_2_14","2TI","2","14","14","Ka riƙa tuna masu da haka, ka kuma gama su da Allah, kada su yi jayayya a kan maganganu, don ba ta da wani amfani, sai ɓad da masu ji kawai take yi. ");
INSERT INTO hausa_vpl VALUES ("T22_15","085_2_15","2TI","2","15","15","Ka yi iyakacin ƙoƙarinka ka gabatar da kanka a gaban Allah a matsayin wanda aka amince da shi, ma’aikaci wanda ba shi da dalilin jin kunya wanda kuma yake fassara kalmar gaskiya daidai. ");
INSERT INTO hausa_vpl VALUES ("T22_16","085_2_16","2TI","2","16","16","Ka yi nesa da maganganun banza na rashin tsoron Allah, gama waɗanda suka mai da hankali ga yin waɗannan za su ƙara zama marasa tsoron Allah. ");
INSERT INTO hausa_vpl VALUES ("T22_17","085_2_17","2TI","2","17","17","Koyarwarsu za tă bazu kamar ruɓaɓɓen gyambo. A cikinsu akwai Himenayus da Filetus, ");
INSERT INTO hausa_vpl VALUES ("T22_18","085_2_18","2TI","2","18","18","waɗanda suka bauɗe daga gaskiya. Suna cewa tashin matattu ya riga ya faru, suna kuma ɓata bangaskiyar waɗansu. ");
INSERT INTO hausa_vpl VALUES ("T22_19","085_2_19","2TI","2","19","19","Duk da haka, ƙaƙƙarfan tushen nan na Allah yana nan daram, an hatimce shi da wannan rubutu, “Ubangiji ya san waɗanda suke nasa,” da kuma, “Duk wanda ya bayyana yarda ga sunan Ubangiji, to, dole yă yi nesa da aikata mugunta.” ");
INSERT INTO hausa_vpl VALUES ("T22_20","085_2_20","2TI","2","20","20","A babban gida akwai kayayyakin da ba na zinariya da na azurfa kaɗai ba, amma har da na katako da na yumɓu ma; waɗansu domin hidima mai daraja waɗansu kuwa domin hidima marar daraja. ");
INSERT INTO hausa_vpl VALUES ("T22_21","085_2_21","2TI","2","21","21","In mutum ya tsabtacce kansa daga na farkon zai zama kayan aikin hidima mai daraja, mai amfani ga Maigida, kuma shiryayye domin yin kowane aiki mai kyau. ");
INSERT INTO hausa_vpl VALUES ("T22_22","085_2_22","2TI","2","22","22","Ka yi nesa da mugayen sha’awace-sha’awace na ƙuruciya, ka kuma bi adalci, bangaskiya, ƙauna da kuma salama, tare da waɗanda suke kira ga Ubangiji daga zuciya mai tsabta. ");
INSERT INTO hausa_vpl VALUES ("T22_23","085_2_23","2TI","2","23","23","Kada wani abu yă haɗa ka da gardandamin banza da wofi, domin ka san yadda suke jawo faɗa. ");
INSERT INTO hausa_vpl VALUES ("T22_24","085_2_24","2TI","2","24","24","Bai kamata bawan Ubangiji yă zama mai neman faɗa ba; a maimako, dole yă nuna alheri ga kowa, mai iya koyarwa, mai haƙuri kuma. ");
INSERT INTO hausa_vpl VALUES ("T22_25","085_2_25","2TI","2","25","25","Waɗanda suke gāba da shi kuwa dole yă yi musu gargaɗi cikin hankali, da fata Allah zai sa su tuba su kai ga sanin gaskiya, ");
INSERT INTO hausa_vpl VALUES ("T22_26","085_2_26","2TI","2","26","26","su kuma dawo cikin hankulansu su kuɓuta daga tarkon Iblis, wanda ya sa suka zama kamammu don su aikata nufinsa. ");
INSERT INTO hausa_vpl VALUES ("T23_1","085_3_1","2TI","3","1","1","Amma fa ka san wannan, za a yi lokutan shan wahala a kwanakin ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("T23_2","085_3_2","2TI","3","2","2","Mutane za su zama masu son kansu, masu son kuɗi, masu taƙama, masu girman kai, masu zage-zage, marasa biyayya ga iyayensu, marasa godiya, marasa tsarki, ");
INSERT INTO hausa_vpl VALUES ("T23_3","085_3_3","2TI","3","3","3","marasa ƙauna, marasa gafartawa, masu ɓata sunayen waɗansu, marasa kamunkai, masu ƙeta, marasa ƙaunar nagarta, ");
INSERT INTO hausa_vpl VALUES ("T23_4","085_3_4","2TI","3","4","4","masu cin amana, marasa hankali, waɗanda sun cika da ɗaga kai, masu son jin daɗi a maimakon ƙaunar Allah ");
INSERT INTO hausa_vpl VALUES ("T23_5","085_3_5","2TI","3","5","5","suna riƙe da siffofin ibada, amma suna mūsun ikonta. Kada wani abu yă haɗa ka da su. ");
INSERT INTO hausa_vpl VALUES ("T23_6","085_3_6","2TI","3","6","6","Irin su ne suke saɗaɗawa su shiga gidaje suna rinjayar mata marasa ƙarfin hali, waɗanda zunubai suka sha kansu, mugayen sha’awace-sha’awace kuma sun ɗauke hankulansu, ");
INSERT INTO hausa_vpl VALUES ("T23_7","085_3_7","2TI","3","7","7","kullum suna koyo amma ba sa taɓa iya yarda da gaskiya. ");
INSERT INTO hausa_vpl VALUES ("T23_8","085_3_8","2TI","3","8","8","Kamar dai yadda Yannes da Yamberes suka tayar wa Musa, haka waɗannan mutane ma suke tayar wa gaskiya, mutane masu ɓataccen hankali, waɗanda, in ana zancen bangaskiya ne, to, fa ba sa ciki. ");
INSERT INTO hausa_vpl VALUES ("T23_9","085_3_9","2TI","3","9","9","Sai dai ba za su yi nisa ba, don rashin hankalinsu zai bayyana ga kowa, kamar na mutanen nan biyu. ");
INSERT INTO hausa_vpl VALUES ("T23_10","085_3_10","2TI","3","10","10","Kai kam, ka san kome game da koyarwata, da halina, da niyyata, bangaskiya, haƙuri, ƙauna, jimiri, ");
INSERT INTO hausa_vpl VALUES ("T23_11","085_3_11","2TI","3","11","11","tsanani, shan wahala, irin abubuwan da suka faru da ni a Antiyok, Ikoniyum da kuma Listira, tsananin da na jure. Duk da haka Ubangiji ya cece ni daga dukansu. ");
INSERT INTO hausa_vpl VALUES ("T23_12","085_3_12","2TI","3","12","12","Labudda, duk masu niyyar zaman tsarkaka, suna na Kiristi Yesu, za su sha tsanani. ");
INSERT INTO hausa_vpl VALUES ("T23_13","085_3_13","2TI","3","13","13","Mugayen mutane da masu ruɗi kuwa, ƙara muni za su riƙa yi, suna yaudara, ana kuma yaudararsu. ");
INSERT INTO hausa_vpl VALUES ("T23_14","085_3_14","2TI","3","14","14","Amma kai kam, ka ci gaba da abin da ka koya ka kuma tabbatar, gama ka san waɗanda ka koye su daga gare su, ");
INSERT INTO hausa_vpl VALUES ("T23_15","085_3_15","2TI","3","15","15","da kuma yadda tun kana ɗan jinjiri ka san Nassosi masu tsarki, waɗanda suke iya sa ka zama mai hikima zuwa ceto ta wurin bangaskiya cikin Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("T23_16","085_3_16","2TI","3","16","16","Dukan Nassi numfashin Allah ne yana kuma da amfani don koyarwa, tsawatarwa, gyara da kuma horarwa cikin adalci, ");
INSERT INTO hausa_vpl VALUES ("T23_17","085_3_17","2TI","3","17","17","domin mutumin Allah yă zama shiryayye sosai saboda kowane kyakkyawan aiki. ");
INSERT INTO hausa_vpl VALUES ("T24_1","085_4_1","2TI","4","1","1","A gaban Allah da kuma Kiristi Yesu, wanda zai yi wa masu rai da matattu shari’a, saboda kuma bayyanuwarsa da mulkinsa, ina ba ka umarni. ");
INSERT INTO hausa_vpl VALUES ("T24_2","085_4_2","2TI","4","2","2","Ka yi wa’azin Maganar Allah, ka zama a shirye a kullum, ko da zarafi, ko babu zarafi, ka yi gyara, ka kwaɓe, ka kuma ƙarfafa, da matuƙar haƙuri da koyarwa cikin natsuwa. ");
INSERT INTO hausa_vpl VALUES ("T24_3","085_4_3","2TI","4","3","3","Gama lokaci yana zuwa da mutane ba za su jure da sahihiyar koyarwa ba. A maimako, don cimma burinsu, za su taro wa kansu malamai masu yawa, domin su faɗi abin da kunnuwansu masu ƙaiƙayi suke so su ji. ");
INSERT INTO hausa_vpl VALUES ("T24_4","085_4_4","2TI","4","4","4","Za su juye kunnuwansu daga gaskiya zuwa ga jin tatsuniyoyi. ");
INSERT INTO hausa_vpl VALUES ("T24_5","085_4_5","2TI","4","5","5","Amma kai, ka natsu cikin kowane hali, ka jure shan wahala, ka yi aikin mai bishara, ka cika dukan ayyukan hidimarka. ");
INSERT INTO hausa_vpl VALUES ("T24_6","085_4_6","2TI","4","6","6","Gama an riga an tsiyaye ni kamar hadaya ta sha, kuma lokacin tashina ya yi. ");
INSERT INTO hausa_vpl VALUES ("T24_7","085_4_7","2TI","4","7","7","Na yi fama mai kyau, na gama tseren, na riƙe bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("T24_8","085_4_8","2TI","4","8","8","Yanzu kuwa an ajiye mini rawanin adalci, wanda Ubangiji, Alƙali mai adalci zai ba ni a ranan nan ba kuwa ni kaɗai ba, amma ga duk waɗanda suka yi marmarin bayyanuwarsa. ");
INSERT INTO hausa_vpl VALUES ("T24_9","085_4_9","2TI","4","9","9","Ka yi iyakacin ƙoƙarinka ka zo wurina da sauri, ");
INSERT INTO hausa_vpl VALUES ("T24_10","085_4_10","2TI","4","10","10","gama Demas, saboda ƙaunar wannan duniya, ya yashe ni ya tafi Tessalonika. Kirssens ya tafi Galatiya, Titus kuwa ya tafi Dalmatiya. ");
INSERT INTO hausa_vpl VALUES ("T24_11","085_4_11","2TI","4","11","11","Luka ne kaɗai yake tare da ni. Ka nemi Markus ku zo tare, domin yana da amfani a gare ni cikin hidimata. ");
INSERT INTO hausa_vpl VALUES ("T24_12","085_4_12","2TI","4","12","12","Na aiki Tikikus zuwa Afisa. ");
INSERT INTO hausa_vpl VALUES ("T24_13","085_4_13","2TI","4","13","13","Sa’ad da za ka dawo, ka zo mini da alkyabbar da na bari a wurin Karbus a Toruwas, da kuma naɗaɗɗun littattafaina, tun ba ma fatun nan masu rubutu ba. ");
INSERT INTO hausa_vpl VALUES ("T24_14","085_4_14","2TI","4","14","14","Alekzanda maƙerin ƙarafan nan ya yi mini mugunta ƙwarai. Ubangiji zai sāka masa saboda abin da ya yi. ");
INSERT INTO hausa_vpl VALUES ("T24_15","085_4_15","2TI","4","15","15","Kai ma sai ka lura da shi, domin ya yi gāba sosai da saƙonmu. ");
INSERT INTO hausa_vpl VALUES ("T24_16","085_4_16","2TI","4","16","16","A lokacin da na kāre kaina da farko, ba wanda ya goyi bayana, sai ma kowa ya yashe ni. Ina fata ba za a lasafta wannan laifi a kansu ba. ");
INSERT INTO hausa_vpl VALUES ("T24_17","085_4_17","2TI","4","17","17","Amma Ubangiji ya tsaya tare da ni, ya kuma ba ni ƙarfi, don ta wurina a yi cikakkiyar shelar saƙon har Al’ummai duka su ji. Aka kuma cece ni daga bakin zaki. ");
INSERT INTO hausa_vpl VALUES ("T24_18","085_4_18","2TI","4","18","18","Ubangiji zai cece ni daga kowane mugun hari yă kuma kai ni mulkinsa na sama lafiya. A gare shi ɗaukaka ta tabbata har abada abadin. Amin. ");
INSERT INTO hausa_vpl VALUES ("T24_19","085_4_19","2TI","4","19","19","Ka gai da Firiskila da Akwila da iyalin Onesiforus. ");
INSERT INTO hausa_vpl VALUES ("T24_20","085_4_20","2TI","4","20","20","Erastus ya dakata a Korint, na kuma bar Turofimus cikin rashin lafiya a Miletus. ");
INSERT INTO hausa_vpl VALUES ("T24_21","085_4_21","2TI","4","21","21","Ka yi iyakacin ƙoƙarinka ka iso nan kafin damina. Yubulus yana gaishe ka, haka ma Fuden, Lainus, Kalaudiya da kuma dukan ’yan’uwa. ");
INSERT INTO hausa_vpl VALUES ("T24_22","085_4_22","2TI","4","22","22","Ubangiji yă zama tare da ruhunka. Alheri yă zama tare da ku.");
INSERT INTO hausa_vpl VALUES ("TT1_1","086_1_1","TIT","1","1","1","Bulus, bawan Allah da kuma manzon Yesu Kiristi saboda bangaskiyar zaɓaɓɓu na Allah da kuma sanin gaskiya wadda take kaiwa ga rayuwa ta tsoron Allah ");
INSERT INTO hausa_vpl VALUES ("TT1_2","086_1_2","TIT","1","2","2","duk wannan kuwa saboda begen nan ne ga rai madawwami da Allah ya yi alkawari tun fil azal, shi wanda ƙarya ba ta a gare shi, ");
INSERT INTO hausa_vpl VALUES ("TT1_3","086_1_3","TIT","1","3","3","da lokacin da Allah ya zaɓa ya cika sai ya bayyana maganarsa a sarari ta wurin wa’azin da aka danƙa mini amana ta wurin umarnin Allah Mai Cetonmu, ");
INSERT INTO hausa_vpl VALUES ("TT1_4","086_1_4","TIT","1","4","4","Zuwa ga Titus, ɗana na gaske a tarayyarmu cikin bangaskiya. Alheri da salama daga Allah Uba da kuma Kiristi Yesu Mai Cetonmu, su kasance tare da kai. ");
INSERT INTO hausa_vpl VALUES ("TT1_5","086_1_5","TIT","1","5","5","Dalilin da ya sa na bar ka a Kirit shi ne don ka daidaita abubuwan da suka rage da ba a kammala ba, ka kuma naɗa dattawa a kowane gari, yadda na umarce ka. ");
INSERT INTO hausa_vpl VALUES ("TT1_6","086_1_6","TIT","1","6","6","Dole dattijo yă kasance marar aibi, mijin mace guda, mutumin da ’ya’yansa masu bi ne, waɗanda kuma ba a san su da lalata ko rashin biyayya ba. ");
INSERT INTO hausa_vpl VALUES ("TT1_7","086_1_7","TIT","1","7","7","Da yake an danƙa wa mai kula da ikkilisiya riƙon amana saboda Allah, dole yă zama marar aibi ba mai girman kai ba, ba mai saurin fushi ba, ba mai buguwa ba, ba mai rikici ba, ba kuma mai son ƙazamar riba ba. ");
INSERT INTO hausa_vpl VALUES ("TT1_8","086_1_8","TIT","1","8","8","A maimakon haka dole yă zama mai karɓan baƙi, mai son abu nagari, mai kamunkai, mai adalci, mai tsarki da kuma natsattse. ");
INSERT INTO hausa_vpl VALUES ("TT1_9","086_1_9","TIT","1","9","9","Dole yă riƙe tabbataccen saƙon nan kam-kam yadda aka koyar, don yă iya ƙarfafa waɗansu da sahihiyar koyarwa yă kuma ƙaryata waɗanda suke gāba da shi. ");
INSERT INTO hausa_vpl VALUES ("TT1_10","086_1_10","TIT","1","10","10","Gama akwai ’yan tawaye da yawa, masu surutun banza da masu ruɗi, musamman ƙungiyar masu kaciya. ");
INSERT INTO hausa_vpl VALUES ("TT1_11","086_1_11","TIT","1","11","11","Dole a hana su yin magana, domin suna kawo rushewar iyalai ta wurin koyar da abubuwan da bai kamata su koyar ba don neman ƙazamar riba. ");
INSERT INTO hausa_vpl VALUES ("TT1_12","086_1_12","TIT","1","12","12","Wani daga cikin annabawansu ma ya ce, “Kiretawa a kullum maƙaryata ne, mugayen dabbobi, ragwaye haɗamammu.” ");
INSERT INTO hausa_vpl VALUES ("TT1_13","086_1_13","TIT","1","13","13","Wannan shaida gaskiya ce. Saboda haka, sai ka tsawata musu sosai, don su zama sahihai a wajen bangaskiya, ");
INSERT INTO hausa_vpl VALUES ("TT1_14","086_1_14","TIT","1","14","14","ba za su kuma mai da hankalinsu ga tatsuniyoyin Yahudawa ko ga umarnan waɗanda suke ƙin gaskiya ba. ");
INSERT INTO hausa_vpl VALUES ("TT1_15","086_1_15","TIT","1","15","15","Ga tsarkaka kuwa, kome mai tsarki ne, amma ga waɗanda suke marasa tsarki da kuma marasa ba da gaskiya, ba abin da yake da tsarki. Gaskiya dai, hankulansu da lamirinsu duk marasa tsarki ne. ");
INSERT INTO hausa_vpl VALUES ("TT1_16","086_1_16","TIT","1","16","16","Sun ɗauka cewa sun san Allah, amma ta wurin ayyukansu suna mūsunsa. Sun zama abin ƙyama, marasa biyayya, ba su ma isa su yi aiki nagari ba. ");
INSERT INTO hausa_vpl VALUES ("TT2_1","086_2_1","TIT","2","1","1","Dole ka koyar da abin da yake bisa sahihiyar koyarwa. ");
INSERT INTO hausa_vpl VALUES ("TT2_2","086_2_2","TIT","2","2","2","Ka koya wa tsofaffin maza su kasance masu sauƙinkai, waɗanda suka cancanci girmamawa, masu kamunkai, sahihai wajen bangaskiya, da ƙauna da kuma jimiri. ");
INSERT INTO hausa_vpl VALUES ("TT2_3","086_2_3","TIT","2","3","3","Haka ma, ka koya wa tsofaffin mata su zama masu bangirma cikin rayuwarsu, ba masu ɓata suna ko masu jarrabar shan giya ba, sai dai su zama masu koyar da abin da yake nagari. ");
INSERT INTO hausa_vpl VALUES ("TT2_4","086_2_4","TIT","2","4","4","Sa’an nan za su iya su koya wa mata masu ƙuruciya su ƙaunaci mazansu da ’ya’yansu, ");
INSERT INTO hausa_vpl VALUES ("TT2_5","086_2_5","TIT","2","5","5","su kasance da kamunkai da kuma tsarki, masu aiki a gida, masu kirki da kuma masu biyayya ga mazansu, don kada wani yă rena maganar Allah. ");
INSERT INTO hausa_vpl VALUES ("TT2_6","086_2_6","TIT","2","6","6","Haka kuma, ka ƙarfafa samari su zama masu kamunkai. ");
INSERT INTO hausa_vpl VALUES ("TT2_7","086_2_7","TIT","2","7","7","Cikin kowane abu ka zama musu misali mai kyau ta wurin aikata abin da yake nagari. A cikin koyarwarka ka nuna mutunci da ƙwazo ");
INSERT INTO hausa_vpl VALUES ("TT2_8","086_2_8","TIT","2","8","8","da kuma sahihanci cikin maganar da ba za a iya kushewa ba, domin masu gāba da kai su ji kunya, su kuma rasa wani mugun abin da za su faɗa game da mu. ");
INSERT INTO hausa_vpl VALUES ("TT2_9","086_2_9","TIT","2","9","9","Ka koya wa bayi su yi wa iyayengijinsu biyayya cikin kowane abu, su yi ƙoƙari su gamshe su, kada su mayar musu da magana, ");
INSERT INTO hausa_vpl VALUES ("TT2_10","086_2_10","TIT","2","10","10","kada kuma su yi musu sata, sai dai su nuna za a iya amince da su sosai, don ta kowace hanya su sa koyarwa game da Allah Mai Cetonmu ta zama abin ɗaukan hankali. ");
INSERT INTO hausa_vpl VALUES ("TT2_11","086_2_11","TIT","2","11","11","Gama alherin Allah mai kawo ceto ya bayyana ga dukan mutane. ");
INSERT INTO hausa_vpl VALUES ("TT2_12","086_2_12","TIT","2","12","12","Yana koya mana mu ce, “A’a” ga rashin tsoron Allah da kuma sha’awace-sha’awacen duniya, mu kuma yi rayuwa ta kamunkai, ta adalci da kuma ta tsoron Allah a cikin wannan zamani, ");
INSERT INTO hausa_vpl VALUES ("TT2_13","086_2_13","TIT","2","13","13","yayinda muke sauraron begenmu mai albarka bayyanuwar ɗaukakar Allahnmu mai girma da kuma Mai Cetonmu, Yesu Kiristi, ");
INSERT INTO hausa_vpl VALUES ("TT2_14","086_2_14","TIT","2","14","14","wanda ya ba da kansa dominmu don yă fanshe mu daga dukan mugunta yă kuma tsarkake wa kansa mutanen da suke nasa, waɗanda suke marmarin yin abin da yake nagari. ");
INSERT INTO hausa_vpl VALUES ("TT2_15","086_2_15","TIT","2","15","15","Waɗannan kam, su ne abubuwan da ya kamata ka koyar, ka ƙarfafa ka kuma tsawata da dukan iko. Kada ka yarda wani yă rena ka. ");
INSERT INTO hausa_vpl VALUES ("TT3_1","086_3_1","TIT","3","1","1","Ka tuna wa mutane su zama masu biyayya ga masu mulki da kuma hukumomi, su zama masu biyayya suna kuma a shirye su yi kowane abin da yake mai kyau, ");
INSERT INTO hausa_vpl VALUES ("TT3_2","086_3_2","TIT","3","2","2","kada su zama masu ɓata sunan kowa, su zama masu salama da kulawa, su kuma zama masu matuƙar tawali’u ga dukan mutane. ");
INSERT INTO hausa_vpl VALUES ("TT3_3","086_3_3","TIT","3","3","3","A wani lokaci can baya mu ma wawaye ne, marasa biyayya, aka ruɗe mu, sha’awace-sha’awace da kwaɗayi iri-iri suka daure mu, muka yi zaman ƙiyayya da kishi, aka ƙi mu, mu kuma muka ƙi juna. ");
INSERT INTO hausa_vpl VALUES ("TT3_4","086_3_4","TIT","3","4","4","Amma da alheri da kuma ƙaunar Allah Mai Cetonmu suka bayyana, ");
INSERT INTO hausa_vpl VALUES ("TT3_5","086_3_5","TIT","3","5","5","sai ya cece mu, ba saboda abubuwan adalcin da muka aikata ba, sai dai saboda jinƙansa. Ya cece mu ta wurin wankan nan na sāke haihuwa da kuma sabuntawan nan ta Ruhu Mai Tsarki, ");
INSERT INTO hausa_vpl VALUES ("TT3_6","086_3_6","TIT","3","6","6","wanda ya zubo mana a yalwace ta wurin Yesu Kiristi Mai Cetonmu, ");
INSERT INTO hausa_vpl VALUES ("TT3_7","086_3_7","TIT","3","7","7","wannan fa domin an kuɓutar da mu ne ta wurin alherinsa, don mu zama magāda masu begen ga rai madawwami. ");
INSERT INTO hausa_vpl VALUES ("TT3_8","086_3_8","TIT","3","8","8","Wannan magana tabbatacciya ce, ina kuma so ka nanata waɗannan abubuwa ƙwarai, domin waɗanda suka dogara ga Allah su himmantu ga aiki mai kyau. Waɗannan abubuwa suna da kyau sosai suna kuma da amfani ga kowane mutum. ");
INSERT INTO hausa_vpl VALUES ("TT3_9","086_3_9","TIT","3","9","9","Amma ka guji jayayyar banza da ƙididdigar asali da gardandami da faɗace-faɗace game da Doka, gama ba su da riba kuma aikin banza ne. ");
INSERT INTO hausa_vpl VALUES ("TT3_10","086_3_10","TIT","3","10","10","Ka gargaɗe mutumin da yake kawo tsattsaguwa sau ɗaya, ka kuma gargaɗe shi sau na biyu. Bayan haka, kada wani abu yă haɗa ka da shi. ");
INSERT INTO hausa_vpl VALUES ("TT3_11","086_3_11","TIT","3","11","11","Ka dai san cewa irin mutumin nan ya taurare kuma mai zunubi ne; ya yanke wa kansa hukunci. ");
INSERT INTO hausa_vpl VALUES ("TT3_12","086_3_12","TIT","3","12","12","Da zarar na aika Artemas ko Tikikus zuwa wurinka, sai ka yi iyakacin ƙoƙarinka ka zo wurina a Nikofolis, domin na yanke shawara in ci damina a can. ");
INSERT INTO hausa_vpl VALUES ("TT3_13","086_3_13","TIT","3","13","13","Ka yi iyakacin ƙoƙarinka ka taimaki Zenas lauyan nan da Afollos a hanyarsu ka kuma tabbata ba su rasa kome ba. ");
INSERT INTO hausa_vpl VALUES ("TT3_14","086_3_14","TIT","3","14","14","Dole mutanenmu su koyi ba da kansu ga aikata abin da yake nagari, domin su iya biyan bukatunsu na yau da kullum kada kuma su yi rayuwar marar amfani. ");
INSERT INTO hausa_vpl VALUES ("TT3_15","086_3_15","TIT","3","15","15","Dukan waɗanda suke tare da ni suna gaishe ka. Ka gaggai mini da masoyanmu, masu bangaskiya. Alheri yă kasance tare da ku duka.");
INSERT INTO hausa_vpl VALUES ("PM1_1","087_1_1","PHM","1","1","1","Bulus, ɗan kurkuku saboda Kiristi Yesu, da kuma Timoti ɗan’uwanmu, Zuwa ga Filemon ƙaunataccen abokinmu da kuma abokin aikinmu, ");
INSERT INTO hausa_vpl VALUES ("PM1_2","087_1_2","PHM","1","2","2","zuwa kuma ga Affiya ’yar’uwarmu, zuwa kuma ga Arkiffus abokin famarmu, da zuwa kuma ga ikkilisiyar da take taruwa a gidanka. ");
INSERT INTO hausa_vpl VALUES ("PM1_3","087_1_3","PHM","1","3","3","Alheri da salama daga Allah Ubanmu da kuma Ubangiji Yesu Kiristi, su kasance tare da ku. ");
INSERT INTO hausa_vpl VALUES ("PM1_4","087_1_4","PHM","1","4","4","Kullum nakan gode wa Allahna sa’ad da nake tuna da kai cikin addu’o’ina, ");
INSERT INTO hausa_vpl VALUES ("PM1_5","087_1_5","PHM","1","5","5","domin ina jin labari bangaskiyarka cikin Ubangiji Yesu da kuma ƙaunarka da kake yi saboda dukan tsarkaka. ");
INSERT INTO hausa_vpl VALUES ("PM1_6","087_1_6","PHM","1","6","6","Ina addu’a ka zama mai ƙwazo cikin shaida bangaskiyarka, domin ka sami cikakken fahimta ta kowane abin da yake nagarin da muke da shi cikin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("PM1_7","087_1_7","PHM","1","7","7","Ƙaunarka ta sa ni farin ciki ƙwarai ta kuma ƙarfafa ni, domin kai, ɗan’uwa, ka wartsake zukatan tsarkaka. ");
INSERT INTO hausa_vpl VALUES ("PM1_8","087_1_8","PHM","1","8","8","Saboda haka, ko da yake cikin Kiristi ina iya yin ƙarfin hali in umarce ka ka yi abin da ya kamata, ");
INSERT INTO hausa_vpl VALUES ("PM1_9","087_1_9","PHM","1","9","9","duk da haka ina roƙonka saboda ƙauna, na fi so in roƙe ka, ni Bulus tsoho, a yanzu kuma ga ni ɗan sarƙa saboda Kiristi Yesu. ");
INSERT INTO hausa_vpl VALUES ("PM1_10","087_1_10","PHM","1","10","10","Ina roƙonka saboda ɗana Onesimus, wanda ya zama ɗana yayinda nake cikin sarƙoƙi. ");
INSERT INTO hausa_vpl VALUES ("PM1_11","087_1_11","PHM","1","11","11","Dā kam, ba shi da amfani a gare ka, amma yanzu ya zama da amfani a gare ka da kuma gare ni. ");
INSERT INTO hausa_vpl VALUES ("PM1_12","087_1_12","PHM","1","12","12","Ina aike shi yă koma gare ka, shi da yake zuciyata. ");
INSERT INTO hausa_vpl VALUES ("PM1_13","087_1_13","PHM","1","13","13","Na so in riƙe shi a wurina a madadinka domin yă taimake ni yayinda nake cikin sarƙoƙi saboda bishara. ");
INSERT INTO hausa_vpl VALUES ("PM1_14","087_1_14","PHM","1","14","14","Sai dai ban so in yi kome ban da yardarka ba, domin kowane alherin da za ka yi, yă fito daga zuciyarka, ba na tilas ba. ");
INSERT INTO hausa_vpl VALUES ("PM1_15","087_1_15","PHM","1","15","15","Wataƙila abin da ya sa aka raba ka da shi na ɗan lokaci ƙanƙani shi ne don ka same shi da amfani ");
INSERT INTO hausa_vpl VALUES ("PM1_16","087_1_16","PHM","1","16","16","ba kamar bawa kuma ba, sai dai fiye da bawa, a matsayin ƙaunataccen ɗan’uwa. Shi ƙaunatacce ne sosai a gare ni amma a gare ka ya ma fi zama ƙaunatacce, kamar mutum da kuma kamar ɗan’uwa a cikin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("PM1_17","087_1_17","PHM","1","17","17","Saboda haka in ka ɗauke ni a kan ni abokin tarayya ne, sai ka marabce shi kamar yadda za ka marabce ni. ");
INSERT INTO hausa_vpl VALUES ("PM1_18","087_1_18","PHM","1","18","18","In ya yi maka wani laifi ko kuma yana riƙe maka wani bashi, sai ka mai da shi a kaina. ");
INSERT INTO hausa_vpl VALUES ("PM1_19","087_1_19","PHM","1","19","19","Ni, Bulus, nake rubuta wannan da hannuna. Zan biya ka, kada ma a yi zancen ranka da kake riƙe mini bashi. ");
INSERT INTO hausa_vpl VALUES ("PM1_20","087_1_20","PHM","1","20","20","Ina fata, ɗan’uwa, zan sami amfani daga gare ka cikin Ubangiji; ka wartsake zuciyata cikin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("PM1_21","087_1_21","PHM","1","21","21","Da tabbacin biyayyarka, ina rubuta maka, da sanin za ka yi fiye da abin da na ce. ");
INSERT INTO hausa_vpl VALUES ("PM1_22","087_1_22","PHM","1","22","22","Abu guda ya rage, ka shirya mini masauƙi, domin ina bege za a mayar da ni gare ku albarkacin addu’o’inku. ");
INSERT INTO hausa_vpl VALUES ("PM1_23","087_1_23","PHM","1","23","23","Efafaras, abokin tarayyata a kurkuku cikin Kiristi Yesu, yana gaishe ka. ");
INSERT INTO hausa_vpl VALUES ("PM1_24","087_1_24","PHM","1","24","24","Haka kuma Markus, Aristarkus, Demas da kuma Luka, abokan aikina. ");
INSERT INTO hausa_vpl VALUES ("PM1_25","087_1_25","PHM","1","25","25","Alherin Ubangiji Yesu Kiristi yă kasance da ruhunku.");
INSERT INTO hausa_vpl VALUES ("HB1_1","088_1_1","HEB","1","1","1","A dā Allah ya yi wa kakanni-kakanninmu magana ta bakin annabawa a lokuta dabam-dabam da kuma a hanyoyi iri-iri, ");
INSERT INTO hausa_vpl VALUES ("HB1_2","088_1_2","HEB","1","2","2","amma a waɗannan kwanaki a ƙarshe ya yi magana da mu ta wurin Ɗansa, wanda ya naɗa magājin dukan abubuwa, wanda kuma ta wurinsa ya halicci duniya. ");
INSERT INTO hausa_vpl VALUES ("HB1_3","088_1_3","HEB","1","3","3","Ɗan shi ne hasken ɗaukakar Allah, shi ne kuma ainihin kamanninsa, yana riƙe da dukan abubuwa ta wurin kalmarsa mai iko. Bayan ya yi tsarkakewa don zunubai, sai ya zauna a hannun daman Maɗaukaki a sama. ");
INSERT INTO hausa_vpl VALUES ("HB1_4","088_1_4","HEB","1","4","4","Ta haka yake da fifiko a kan mala’iku kamar yadda sunan da ya gāda ya fi nasu fifiko. ");
INSERT INTO hausa_vpl VALUES ("HB1_5","088_1_5","HEB","1","5","5","Gama ga wane daga cikin mala’ikun Allah ya taɓa cewa, “Kai Ɗana ne; yau na zama Uba a gare ka”? Ko kuwa, “Zan zama Ubansa, shi kuma zai zama Ɗana”? ");
INSERT INTO hausa_vpl VALUES ("HB1_6","088_1_6","HEB","1","6","6","Haka kuma, sa’ad da Allah ya kawo ɗan farinsa a duniya ya ce, “Bari dukan mala’ikun Allah su yi masa sujada.” ");
INSERT INTO hausa_vpl VALUES ("HB1_7","088_1_7","HEB","1","7","7","Da yake magana game da mala’iku kuwa ya ce, “Ya mai da mala’ikunsa iska, bayinsa kuma harsunan wuta.” ");
INSERT INTO hausa_vpl VALUES ("HB1_8","088_1_8","HEB","1","8","8","Amma game da Ɗan ya ce, “Kursiyinka, ya Allah, zai kasance har abada abadin, adalci kuma zai zama sandan mulkinka. ");
INSERT INTO hausa_vpl VALUES ("HB1_9","088_1_9","HEB","1","9","9","Ka ƙaunaci abin da yake daidai, ka kuma ƙi mugunta; saboda haka Allah, Allahnka, ya ɗora ka a bisan abokan zamanka, ta wurin shafan da ya yi maka da man farin ciki.” ");
INSERT INTO hausa_vpl VALUES ("HB1_10","088_1_10","HEB","1","10","10","Ya kuma ce, “Tun da farko, ya Ubangiji, ka kafa tushen duniya, sammai kuma aikin hannuwanka ne. ");
INSERT INTO hausa_vpl VALUES ("HB1_11","088_1_11","HEB","1","11","11","Su za su hallaka, amma kai kana nan; dukansu za su tsufa kamar riga. ");
INSERT INTO hausa_vpl VALUES ("HB1_12","088_1_12","HEB","1","12","12","Za ka naɗe su kamar mayafi, kamar riga za su sauya. Amma kai ba za ka canja ba, shekarunka kuma ba za su taɓa ƙarewa ba.” ");
INSERT INTO hausa_vpl VALUES ("HB1_13","088_1_13","HEB","1","13","13","Ga wane daga cikin mala’iku Allah ya taɓa cewa, “Zauna a hannun damana, sai na sa abokan gābanka su zama matashin sawunka”? ");
INSERT INTO hausa_vpl VALUES ("HB1_14","088_1_14","HEB","1","14","14","Ashe, dukan mala’iku ba ruhohi masu hidima ba ne da aka aika don su yi wa waɗanda za su gāji ceto hidima? ");
INSERT INTO hausa_vpl VALUES ("HB2_1","088_2_1","HEB","2","1","1","Dole mu ƙara mai da hankali sosai ga abubuwan da muka ji, don kada mu kauce. ");
INSERT INTO hausa_vpl VALUES ("HB2_2","088_2_2","HEB","2","2","2","Gama in saƙon da aka faɗi ta bakin mala’iku ya zama tabbatacce, kuma kowane ƙeta umarni da rashin biyayya suka karɓi sakamakonsu da ya dace, ");
INSERT INTO hausa_vpl VALUES ("HB2_3","088_2_3","HEB","2","3","3","yaya za mu tsira in muka ƙyale irin wannan babban ceto? Wannan ceto, wanda Ubangiji ne ya fara sanar, aka kuma tabbatar mana ta bakin waɗanda suka ji shi. ");
INSERT INTO hausa_vpl VALUES ("HB2_4","088_2_4","HEB","2","4","4","Allah shi ma ya shaida ta wurin alamu, abubuwan banmamaki da mu’ujizai iri-iri, da kuma baye-bayen Ruhu Mai Tsarki da aka rarraba bisa ga nufinsa. ");
INSERT INTO hausa_vpl VALUES ("HB2_5","088_2_5","HEB","2","5","5","Ba ga mala’iku ba ne ya sa su yi mulkin duniya mai zuwa, wanda muke magana a kai ba. ");
INSERT INTO hausa_vpl VALUES ("HB2_6","088_2_6","HEB","2","6","6","Amma akwai wani wurin da wani ya shaida cewa, “Mene ne mutum, da kake tuna da shi, ɗan mutum da kake kula da shi? ");
INSERT INTO hausa_vpl VALUES ("HB2_7","088_2_7","HEB","2","7","7","Ka sa shi ƙasa kaɗan da darajar mala’iku; ka naɗa shi da ɗaukaka da girma, ");
INSERT INTO hausa_vpl VALUES ("HB2_8","088_2_8","HEB","2","8","8","ka kuma sa kome a ƙarƙashin ƙafafunsa.” Ta wurin sa kome a ƙarƙashinsa, Allah bai bar wani abu da bai sa a ƙarƙashinsa ba. Duk da haka a yanzu ba mu ga kowane abu a ƙarƙashinsa ba. ");
INSERT INTO hausa_vpl VALUES ("HB2_9","088_2_9","HEB","2","9","9","Sai dai muna ganin Yesu, wanda aka mai da shi ƙasa kaɗan da darajar mala’iku, yanzu kuwa an naɗa shi da ɗaukaka da girma domin yă sha wahalar mutuwa, domin ta wurin alherin Allah yă ɗanɗana mutuwa saboda kowa. ");
INSERT INTO hausa_vpl VALUES ("HB2_10","088_2_10","HEB","2","10","10","Ta wurin kawo ’ya’ya masu yawa zuwa ga ɗaukaka, ya dace cewa Allah, wanda dominsa da kuma ta wurinsa ne kome yake kasancewa, ya sa tushen cetonsu yă zama cikakke ta wurin shan wahala. ");
INSERT INTO hausa_vpl VALUES ("HB2_11","088_2_11","HEB","2","11","11","Da shi wanda yake tsarkake mutane da kuma su waɗanda ake tsarkakewa duk ’yan iyali ɗaya ne. Saboda haka Yesu ba ya kunyan kiransu ’yan’uwansa. ");
INSERT INTO hausa_vpl VALUES ("HB2_12","088_2_12","HEB","2","12","12","Ya ce, “Zan sanar da sunanka ga ’yan’uwana; a gaban jama’a zan rera yabonka.” ");
INSERT INTO hausa_vpl VALUES ("HB2_13","088_2_13","HEB","2","13","13","Har wa yau ya ce, “Zan dogara gare shi.” Ya kuma ce, “Ga ni, da ’ya’yan da Allah ya ba ni.” ");
INSERT INTO hausa_vpl VALUES ("HB2_14","088_2_14","HEB","2","14","14","Da yake ’ya’yan suna da nama da jini, shi ma sai ya ɗauki kamanninsu na mutum domin ta wurin mutuwarsa yă hallaka wanda yake riƙe da ikon mutuwa, wato, Iblis ");
INSERT INTO hausa_vpl VALUES ("HB2_15","088_2_15","HEB","2","15","15","ya kuma ’yantar da waɗanda dukan rayuwarsu tsoron mutuwa ya riƙe su cikin bauta. ");
INSERT INTO hausa_vpl VALUES ("HB2_16","088_2_16","HEB","2","16","16","Gama tabbatacce ba mala’iku ne ya taimaka ba, sai dai zuriyar Ibrahim. ");
INSERT INTO hausa_vpl VALUES ("HB2_17","088_2_17","HEB","2","17","17","Saboda wannan dole a mai da shi kamar ’yan’uwansa ta kowace hanya, domin yă zama babban firist mai aminci da mai jinƙai cikin hidima ga Allah, yă kuma miƙa hadayar sulhu saboda zunuban mutane. ");
INSERT INTO hausa_vpl VALUES ("HB2_18","088_2_18","HEB","2","18","18","Domin shi kansa ya sha wahala sa’ad da aka gwada shi, yana iya taimakon waɗanda ake yi wa gwaji. ");
INSERT INTO hausa_vpl VALUES ("HB3_1","088_3_1","HEB","3","1","1","Saboda haka, ’yan’uwa tsarkaka, waɗanda suke da rabo a kiran nan na sama, ku kafa tunaninku a kan Yesu, manzo da kuma babban firist wanda muke shaidawa. ");
INSERT INTO hausa_vpl VALUES ("HB3_2","088_3_2","HEB","3","2","2","Ya yi aminci ga wanda ya naɗa shi, kamar yadda Musa ya yi aminci ga dukan gidan Allah. ");
INSERT INTO hausa_vpl VALUES ("HB3_3","088_3_3","HEB","3","3","3","An ga Yesu ya cancanci girma fiye da Musa, kamar yadda mai ginin gida ya fi gidan daraja. ");
INSERT INTO hausa_vpl VALUES ("HB3_4","088_3_4","HEB","3","4","4","Gama kowane gida yana da wanda ya gina shi, amma maginin dukan abu Allah ne. ");
INSERT INTO hausa_vpl VALUES ("HB3_5","088_3_5","HEB","3","5","5","Musa ya yi aminci a matsayin bawa cikin dukan gidan Allah, yana ba da shaida a kan abubuwan da za a faɗa nan gaba. ");
INSERT INTO hausa_vpl VALUES ("HB3_6","088_3_6","HEB","3","6","6","Amma Kiristi mai aminci ne kamar ɗa a gidan Allah. Mu kuwa gidansa ne, in muka tsaya gabanmu gadi da kuma begen da muke taƙama a kai. ");
INSERT INTO hausa_vpl VALUES ("HB3_7","088_3_7","HEB","3","7","7","Kamar dai yadda Ruhu Mai Tsarki ya ce, “Yau, in kuka ji muryarsa, ");
INSERT INTO hausa_vpl VALUES ("HB3_8","088_3_8","HEB","3","8","8","kada ku taurare zukatanku, yadda kuka yi a tawayen nan, a lokacin gwaji a hamada, ");
INSERT INTO hausa_vpl VALUES ("HB3_9","088_3_9","HEB","3","9","9","inda kakanninku suka gwada ni, suka kuma gwada ni, ko da yake a cikin shekaru arba’in sun ga abin da na yi. ");
INSERT INTO hausa_vpl VALUES ("HB3_10","088_3_10","HEB","3","10","10","Shi ya sa na yi fushi da wancan zamani, na kuma ce, ‘Kullum zukatansu a karkace suke, ba su kuma san hanyoyina ba.’ ");
INSERT INTO hausa_vpl VALUES ("HB3_11","088_3_11","HEB","3","11","11","Saboda haka na yi rantsuwa a cikin fushina, ‘Ba za su taɓa shiga hutuna ba.’ ” ");
INSERT INTO hausa_vpl VALUES ("HB3_12","088_3_12","HEB","3","12","12","Ku lura fa, ’yan’uwa, cewa kada waninku yă kasance da zuciya mai zunubi marar bangaskiya da takan juye daga bin Allah mai rai. ");
INSERT INTO hausa_vpl VALUES ("HB3_13","088_3_13","HEB","3","13","13","Sai dai ku ƙarfafa juna kullum, muddin akwai lokacin da ana ce da shi Yau, don kada waninku yă zama mai taurin zuciya ta wurin ruɗun zunubi. ");
INSERT INTO hausa_vpl VALUES ("HB3_14","088_3_14","HEB","3","14","14","Mu masu tarayya ne da Kiristi idan mun riƙe bangaskiyarmu da ƙarfi daga farko har zuwa ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("HB3_15","088_3_15","HEB","3","15","15","Kamar yadda aka faɗa cewa, “Yau, in kuka ji muryarsa, kada ku taurare zukatanku kamar yadda kuka yi a tawayen nan.” ");
INSERT INTO hausa_vpl VALUES ("HB3_16","088_3_16","HEB","3","16","16","Su wane ne suka ji suka kuma yi tawaye? Ba su ne duk waɗanda Musa ya bi da su daga Masar ba? ");
INSERT INTO hausa_vpl VALUES ("HB3_17","088_3_17","HEB","3","17","17","Da su wane ne kuwa ya yi fushi har shekaru arba’in? Ba da waɗanda suka yi zunubi, waɗanda suka mutu a hamada ba? ");
INSERT INTO hausa_vpl VALUES ("HB3_18","088_3_18","HEB","3","18","18","Kuma ga su wane ne Allah ya rantse cewa ba za su taɓa shiga hutunsa ba, in ba ga marasa biyayyan nan ba? ");
INSERT INTO hausa_vpl VALUES ("HB3_19","088_3_19","HEB","3","19","19","Saboda haka mun ga cewa ba su iya shiga ba, saboda rashin bangaskiyarsu ne. ");
INSERT INTO hausa_vpl VALUES ("HB4_1","088_4_1","HEB","4","1","1","Saboda haka, da yake alkawarin shiga hutunsa yana nan har yanzu, sai mu yi hankali kada waninku yă kāsa shiga. ");
INSERT INTO hausa_vpl VALUES ("HB4_2","088_4_2","HEB","4","2","2","Gama mu ma mun ji an yi mana wa’azin bishara, kamar yadda su ma suka ji; sai dai saƙon da suka ji ba tă amfane su ba, domin waɗanda suka ji ba su karɓe shi da bangaskiya ba. ");
INSERT INTO hausa_vpl VALUES ("HB4_3","088_4_3","HEB","4","3","3","Mu kam da muka gaskata mu ne muka shiga wannan hutu, kamar yadda Allah ya ce, “Saboda haka na yi rantsuwa cikin fushina, ‘Ba za su taɓa shiga hutuna ba.’ ” Allah ya faɗa haka ko da yake ya riga ya kammala aikinsa tun halittar duniya. ");
INSERT INTO hausa_vpl VALUES ("HB4_4","088_4_4","HEB","4","4","4","Gama a wani wuri ya yi magana a kan rana ta bakwai cikin waɗannan kalmomi, “A rana ta bakwai kuwa Allah ya huta daga dukan aikinsa.” ");
INSERT INTO hausa_vpl VALUES ("HB4_5","088_4_5","HEB","4","5","5","Haka kuma a nassin nan ya ce, “Ba za su taɓa shiga hutuna ba.” ");
INSERT INTO hausa_vpl VALUES ("HB4_6","088_4_6","HEB","4","6","6","Har yanzu dai da sauran dama domin waɗansu su shiga, su kuwa waɗanda aka fara yi wa albishirin nan sun kāsa shiga saboda rashin biyayya. ");
INSERT INTO hausa_vpl VALUES ("HB4_7","088_4_7","HEB","4","7","7","Saboda haka Allah ya sāke sa wata rana, yana kiranta Yau, bayan wani dogon lokaci Allah ya yi magana ta bakin Dawuda, yadda aka riga aka faɗa, “Yau, in kuka ji muryarsa, kada ku taurare zukatanku.” ");
INSERT INTO hausa_vpl VALUES ("HB4_8","088_4_8","HEB","4","8","8","Gama da a ce Yoshuwa ya ba su hutu, da Allah bai yi magana daga baya a kan wata rana dabam ba. ");
INSERT INTO hausa_vpl VALUES ("HB4_9","088_4_9","HEB","4","9","9","Har yanzu, akwai wani hutun Asabbacin da ya rage domin mutanen Allah; ");
INSERT INTO hausa_vpl VALUES ("HB4_10","088_4_10","HEB","4","10","10","gama duk wanda ya shiga hutun Allah, shi ma yakan huta daga nasa aiki, kamar yadda Allah ya huta daga nasa. ");
INSERT INTO hausa_vpl VALUES ("HB4_11","088_4_11","HEB","4","11","11","Saboda haka, bari mu yi iyakacin ƙoƙarinmu mu shiga wannan hutu, don kada wani yă kāsa ta wurin bin gurbinsu na rashin biyayya. ");
INSERT INTO hausa_vpl VALUES ("HB4_12","088_4_12","HEB","4","12","12","Maganar Allah tana da rai, tana kuma da ƙarfin aiki. Ta fi kowane takobi mai baki biyu kaifi. Maganarsa takan ratsa har ciki-ciki, tana raba rai da ruhu, gaɓoɓi da kuma ɓargon ƙashi; har sai ta tone ainihi wane ne muke. ");
INSERT INTO hausa_vpl VALUES ("HB4_13","088_4_13","HEB","4","13","13","Babu wani abu cikin dukan halittar da yake ɓoye daga fuskar Allah. Kowane abu a buɗe yake yana kuma a shimfiɗe a idanun wanda dole mu ba da lissafi a gare shi. ");
INSERT INTO hausa_vpl VALUES ("HB4_14","088_4_14","HEB","4","14","14","Saboda haka, da yake muna da babban firist mai girma wanda ya ratsa sama, Yesu Ɗan Allah, bari mu riƙe bangaskiyan nan wadda muke shaidawa da ƙarfi. ");
INSERT INTO hausa_vpl VALUES ("HB4_15","088_4_15","HEB","4","15","15","Gama babban firist da muke da shi ba marar juyayin kāsawarmu ba ne, amma muna da wanda aka gwada ta kowace hanya, kamar dai yadda akan yi mana, duk da haka bai yi zunubi ba. ");
INSERT INTO hausa_vpl VALUES ("HB4_16","088_4_16","HEB","4","16","16","Saboda haka sai mu matso kusa da kursiyin alheri da ƙarfi zuciya, don mu sami jinƙai mu kuma sami alherin da zai taimake mu a lokacin bukata. ");
INSERT INTO hausa_vpl VALUES ("HB5_1","088_5_1","HEB","5","1","1","Akan zaɓi kowane babban firist daga cikin mutane ne, akan kuma naɗa shi domin yă wakilce su a kan al’amuran Allah, domin yă miƙa kyautai da hadayu saboda zunubai. ");
INSERT INTO hausa_vpl VALUES ("HB5_2","088_5_2","HEB","5","2","2","Da yake babban firist ɗin mai kāsawa ne, yana iya bin da jahilai da kuma waɗanda suka kauce hanya, a hankali. ");
INSERT INTO hausa_vpl VALUES ("HB5_3","088_5_3","HEB","5","3","3","Shi ya sa dole yă miƙa hadayu domin zunubansa, da kuma domin zunuban mutane. ");
INSERT INTO hausa_vpl VALUES ("HB5_4","088_5_4","HEB","5","4","4","Ba wanda yakan kai kansa a wannan matsayi mai girma; sai ko Allah ya kira shi, kamar yadda aka yi wa Haruna. ");
INSERT INTO hausa_vpl VALUES ("HB5_5","088_5_5","HEB","5","5","5","Haka ma Kiristi bai kai kansa neman ɗaukaka na zama babban firist ba. Allah ne dai ya ce masa, “Kai Ɗana ne; yau na zama Uba a gare ka.” ");
INSERT INTO hausa_vpl VALUES ("HB5_6","088_5_6","HEB","5","6","6","Ya kuma ya ce a wani wuri, “Kai firist ne na har abada, bisa ga tsarin Melkizedek.” ");
INSERT INTO hausa_vpl VALUES ("HB5_7","088_5_7","HEB","5","7","7","A lokacin da Yesu ya yi rayuwa a duniya, ya yi addu’o’i da roƙe-roƙe tare da kuka mai zafi da kuma hawaye ga wannan wanda yake da ikon cetonsa daga mutuwa, aka kuwa ji shi saboda tsananin bangirman da ya yi. ");
INSERT INTO hausa_vpl VALUES ("HB5_8","088_5_8","HEB","5","8","8","Ko da yake shi ɗa ne, ya yi biyayya ta wurin shan wahala ");
INSERT INTO hausa_vpl VALUES ("HB5_9","088_5_9","HEB","5","9","9","kuma da aka mai da shi cikakke, sai ya zama hanyar samun madawwamin ceto ga dukan waɗanda suke masa biyayya. ");
INSERT INTO hausa_vpl VALUES ("HB5_10","088_5_10","HEB","5","10","10","Allah kuwa ya naɗa shi yă zama babban firist, bisa ga tsarin Melkizedek. ");
INSERT INTO hausa_vpl VALUES ("HB5_11","088_5_11","HEB","5","11","11","Muna da abubuwa masu yawa da za mu faɗa game da wannan batu, sai dai yana da wuya a bayyana, da yake ba ku da saurin ganewa. ");
INSERT INTO hausa_vpl VALUES ("HB5_12","088_5_12","HEB","5","12","12","Gaskiya, a yanzu ya kamata a ce kun zama malamai, sai ga shi kuna bukatar wani yă sāke koya muku abubuwa masu sauƙi game da abin da Allah ya faɗa. Kuna bukatar madara, ba abinci mai kauri ba! ");
INSERT INTO hausa_vpl VALUES ("HB5_13","088_5_13","HEB","5","13","13","Duk wanda yake rayuwa a kan madara, shi kamar jariri ne har yanzu, kuma bai san ainihi mene ne ya dace ba. ");
INSERT INTO hausa_vpl VALUES ("HB5_14","088_5_14","HEB","5","14","14","Amma abinci mai kauri na balagaggu ne, waɗanda suka hori kansu don su bambanta tsakanin nagarta da mugunta. ");
INSERT INTO hausa_vpl VALUES ("HB6_1","088_6_1","HEB","6","1","1","Dole mu yi ƙoƙarin zama balagaggu mu kuma fara tunani game da abubuwan da suka fi koyarwan nan mai sauƙi game da Kiristi. Bai kamata mu ci gaba da magana game da me ya sa dole mu juye daga ayyukan da suke kawo mutuwa da kuma me ya sa za mu kasance da bangaskiya a cikin Allah ba. ");
INSERT INTO hausa_vpl VALUES ("HB6_2","088_6_2","HEB","6","2","2","Kuma bai kamata mu ci gaba da koyar da umarnai game da baftisma, ɗibiya hannuwa, tashin matattu, da kuma madawwamin hukunci ba. ");
INSERT INTO hausa_vpl VALUES ("HB6_3","088_6_3","HEB","6","3","3","Da yardar Allah, za mu ci gaba ga ƙarin ganewa. ");
INSERT INTO hausa_vpl VALUES ("HB6_4","088_6_4","HEB","6","4","4","Waɗanda suka taɓa samun haske, waɗanda suka ɗanɗana kyauta ta sama, waɗanda suka sami rabo cikin Ruhu Mai Tsarki, ");
INSERT INTO hausa_vpl VALUES ("HB6_5","088_6_5","HEB","6","5","5","waɗanda suka ɗanɗana daɗin maganar Allah da kuma ikokin zamani mai zuwa, ");
INSERT INTO hausa_vpl VALUES ("HB6_6","088_6_6","HEB","6","6","6","ba ya yiwuwa a sāke kawo su ga tuba in suka kauce, domin suna sāke gicciye Ɗan Allah ke nan suna kuma kunyata shi a gaban jama’a. ");
INSERT INTO hausa_vpl VALUES ("HB6_7","088_6_7","HEB","6","7","7","Ƙasar da take shan ruwan sama da yake fāɗi a kanta kullum da kuma take ba da hatsin da yake da amfani ga waɗanda ake noma dominsu, takan sami albarkar Allah. ");
INSERT INTO hausa_vpl VALUES ("HB6_8","088_6_8","HEB","6","8","8","Amma ƙasar da take ba da ƙaya da sarƙaƙƙiya ba ta da amfani tana kuma cikin hatsarin la’ana. A ƙarshe za a ƙone ta. ");
INSERT INTO hausa_vpl VALUES ("HB6_9","088_6_9","HEB","6","9","9","Abokaina, ko da yake muna irin maganan nan, mun tabbata kuna yi abubuwan nan masu kyau da waɗanda suka sami ceto suke yi. ");
INSERT INTO hausa_vpl VALUES ("HB6_10","088_6_10","HEB","6","10","10","Allah ba marar adalci ba ne. Ba zai manta da aikinku da kuma ƙaunar da kuka nuna masa wajen taimakon mutanensa da kuma ci gaba da taimakonsu da kuke yi ba. ");
INSERT INTO hausa_vpl VALUES ("HB6_11","088_6_11","HEB","6","11","11","Muna so kowannenku yă nuna ƙwazon nan har zuwa ƙarshe, domin ku tabbatar da begenku. ");
INSERT INTO hausa_vpl VALUES ("HB6_12","088_6_12","HEB","6","12","12","Ba ma so ku zama masu ƙyuya, sai dai ku yi koyi da waɗanda ta wurin bangaskiya da haƙuri suka gāji abin da aka yi alkawari. ");
INSERT INTO hausa_vpl VALUES ("HB6_13","088_6_13","HEB","6","13","13","Babu wanda ya fi Allah, saboda haka sa’ad da ya yi alkawari ga Ibrahim, sai ya rantse da sunansa, ");
INSERT INTO hausa_vpl VALUES ("HB6_14","088_6_14","HEB","6","14","14","cewa, “Tabbatacce zan albarkace ka in kuma ba ka zuriya mai yawa.” ");
INSERT INTO hausa_vpl VALUES ("HB6_15","088_6_15","HEB","6","15","15","Haka kuwa bayan Ibrahim ya jira da haƙuri, sai ya karɓi abin da aka yi alkawari. ");
INSERT INTO hausa_vpl VALUES ("HB6_16","088_6_16","HEB","6","16","16","In mutane za su yi rantsuwa sukan yi haka da wanda ya fi su ne, rantsuwar kuwa takan tabbatar da abin da aka faɗa ta kuma kawo ƙarshen dukan gardama. ");
INSERT INTO hausa_vpl VALUES ("HB6_17","088_6_17","HEB","6","17","17","Saboda haka da Allah ya so yă bayyana nufinsa marar canjawa a sarari ga magādan abin da aka yi alkawari, sai ya tabbatar da shi da rantsuwa. ");
INSERT INTO hausa_vpl VALUES ("HB6_18","088_6_18","HEB","6","18","18","Allah ba ya karya! Haka ma alkawuransa da rantsuwarsa abubuwa biyu ne da ba a iya canjawa. Mun gudu zuwa wurin Allah domin kāriya. Ya kamata alkawuransa su ƙarfafawa sosai mu riƙe begen nan da yake gabanmu. ");
INSERT INTO hausa_vpl VALUES ("HB6_19","088_6_19","HEB","6","19","19","Muna da wannan bege kamar anka na rai, kafaffe da kuma tabbatacce. Yana shiga tsattsarkan wuri na can ciki a bayan labule, ");
INSERT INTO hausa_vpl VALUES ("HB6_20","088_6_20","HEB","6","20","20","inda Yesu, wanda ya sha gabanmu, ya shiga a madadinmu. Ya zama babban firist na har abada, bisa ga tsarin Melkizedek. ");
INSERT INTO hausa_vpl VALUES ("HB7_1","088_7_1","HEB","7","1","1","Wannan Melkizedek sarkin Salem ne da kuma firist na Allah Mafi Ɗaukaka. Shi ne ya sadu da Ibrahim ya albarkace shi sa’ad da Ibrahim ya dawowa daga cin nasara a bisa sarakuna, ");
INSERT INTO hausa_vpl VALUES ("HB7_2","088_7_2","HEB","7","2","2","Ibrahim kuwa ya ba shi kashi ɗaya bisa goma na kome. Ma’anar sunan Melkizedek ita ce, “sarkin adalci.” Amma da yake Salem yana nufin “salama,” shi kuma “Sarkin salama” ne. ");
INSERT INTO hausa_vpl VALUES ("HB7_3","088_7_3","HEB","7","3","3","Ba shi da mahaifi ko mahaifiya, ba shi da asali, ba shi da farko ko ƙarshe, shi dai kamar Ɗan Allah ne kuma firist ne har abada. ");
INSERT INTO hausa_vpl VALUES ("HB7_4","088_7_4","HEB","7","4","4","Ku dubi irin girman da Melkizedek mana. Ko kakanmu Ibrahim ma ya ba shi kashi ɗaya bisa goma na ganima! ");
INSERT INTO hausa_vpl VALUES ("HB7_5","088_7_5","HEB","7","5","5","Yanzu doka ta umarci zuriyar Lawi waɗanda suka zama firistoci su karɓi kashi ɗaya bisa goma daga wurin mutane, wato, ’yan’uwansu, ko da yake ’yan’uwansu zuriyar Ibrahim ne. ");
INSERT INTO hausa_vpl VALUES ("HB7_6","088_7_6","HEB","7","6","6","Ko da yake Melkizedek ba daga zuriyar Lawi ba ne, duk da haka Ibrahim ya ba shi kashi ɗaya bisa goma na abin da yake da shi, Melkizedek kuwa ya sa masa albarka, shi da aka yi wa alkawura. ");
INSERT INTO hausa_vpl VALUES ("HB7_7","088_7_7","HEB","7","7","7","Kowa ya sani cewa na gaba shi yake sa wa na baya albarka. ");
INSERT INTO hausa_vpl VALUES ("HB7_8","088_7_8","HEB","7","8","8","Firistoci ake ba wa kashi ɗaya bisa goma na abin da mutane suke samu. Amma dukan firistoci sukan mutu, sai dai Melkizedek, kuma nassi ya ce yana da rai. ");
INSERT INTO hausa_vpl VALUES ("HB7_9","088_7_9","HEB","7","9","9","Ana ma iya cewa zuriyar Lawi, mai karɓar kashi ɗaya bisa goma daga mutane, ya ba da kashi ɗaya bisa goma ta wurin Ibrahim, ");
INSERT INTO hausa_vpl VALUES ("HB7_10","088_7_10","HEB","7","10","10","wannan ya kasance haka domin an haifi Lawi daga baya a iyalin Ibrahim wanda ya ba wa Melkizedek kashi ɗaya bisa goma. ");
INSERT INTO hausa_vpl VALUES ("HB7_11","088_7_11","HEB","7","11","11","Ko da yake Dokar Musa ta ce dole firistoci su kasance zuriyar Lawi, waɗannan firistoci ba su iya sa wani yă zama cikakke ba. Saboda akwai bukata wani firist kamar Melkizedek ya zo, a maimakon wani daga iyalin Haruna. ");
INSERT INTO hausa_vpl VALUES ("HB7_12","088_7_12","HEB","7","12","12","Gama in aka canja yadda ake zaɓan firist, dole a canja Dokar ita ma. ");
INSERT INTO hausa_vpl VALUES ("HB7_13","088_7_13","HEB","7","13","13","Mutumin da muke wannan zance a kai, ai, shi na wata kabila ce dabam, wadda ba wani daga kabilar da ya taɓa yin hidima a bagade. ");
INSERT INTO hausa_vpl VALUES ("HB7_14","088_7_14","HEB","7","14","14","Kowa ya san cewa Ubangijinmu ya fito ne daga zuriyar Yahuda ne, kuma Musa bai taɓa ce firistoci za su fito daga wannan kabila ba. ");
INSERT INTO hausa_vpl VALUES ("HB7_15","088_7_15","HEB","7","15","15","Canjin nan a Dokar Allah ya ƙara fitowa fili da wani firist dabam wanda yake kamar Melkizedek ya bayyana. ");
INSERT INTO hausa_vpl VALUES ("HB7_16","088_7_16","HEB","7","16","16","Ya zama firist ne ba saboda ya cika wata ƙa’ida ta zama zuriyar Lawi ba, sai dai bisa ga ikon ran da ba a iya hallakawa. ");
INSERT INTO hausa_vpl VALUES ("HB7_17","088_7_17","HEB","7","17","17","Gama nassi ya ce, “Kai firist ne na har abada, bisa ga tsarin Melkizedek.” ");
INSERT INTO hausa_vpl VALUES ("HB7_18","088_7_18","HEB","7","18","18","Ta haka aka kawar da ƙa’ida marar ƙarfi da kuma marar amfani ");
INSERT INTO hausa_vpl VALUES ("HB7_19","088_7_19","HEB","7","19","19","(gama doka ba tă mai da wani abu cikakke ba), yanzu kuwa bege mafi kyau ya ɗauki matsayinta. Ta haka kuma muka matso kusa da Allah. ");
INSERT INTO hausa_vpl VALUES ("HB7_20","088_7_20","HEB","7","20","20","Ba kuwa da rashin rantsuwa aka yi haka ba. Waɗansu sun zama firistocin ba tare da wata rantsuwa ba, ");
INSERT INTO hausa_vpl VALUES ("HB7_21","088_7_21","HEB","7","21","21","shi wannan ya zama firist ta wurin rantsuwar da Allah ya yi da ya ce masa, “Ubangiji ya rantse, ba kuwa zai canja zuciyarsa ba, ‘Kai firist ne na har abada.’ ” ");
INSERT INTO hausa_vpl VALUES ("HB7_22","088_7_22","HEB","7","22","22","Saboda wannan rantsuwa, Yesu ya zama tabbacin alkawari mafi kyau. ");
INSERT INTO hausa_vpl VALUES ("HB7_23","088_7_23","HEB","7","23","23","To, akwai waɗannan firistoci da yawa, da yake mutuwa ta hana su cin gaba da aikin zaman firist; ");
INSERT INTO hausa_vpl VALUES ("HB7_24","088_7_24","HEB","7","24","24","amma Yesu ba zai mutu ba, don haka zai zama firist har abada. ");
INSERT INTO hausa_vpl VALUES ("HB7_25","088_7_25","HEB","7","25","25","Saboda haka ya iya ba da ceto gaba ɗaya ga masu zuwa wurin Allah ta wurinsa, gama kullum a raye yake saboda yă yi roƙo dominsu. ");
INSERT INTO hausa_vpl VALUES ("HB7_26","088_7_26","HEB","7","26","26","Irin wannan babban firist ne muke bukata, shi mai tsarki ne, marar aibi, mai tsabta, ba kamar mu masu zunubi ba sam. An ɗaukaka shi fiye da kome a sama. ");
INSERT INTO hausa_vpl VALUES ("HB7_27","088_7_27","HEB","7","27","27","Ba ya bukata yă yi ta miƙa hadayu kowace rana saboda zunubansa, sa’an nan saboda zunuban mutane kamar sauran firistoci. Ya miƙa hadaya sau ɗaya tak, sa’ad da ya miƙa kansa. ");
INSERT INTO hausa_vpl VALUES ("HB7_28","088_7_28","HEB","7","28","28","Gama doka takan naɗa babban firist a cikin mutane masu kāsawa; amma rantsuwar da ta zo bayan dokar, ta naɗa Ɗan, wanda aka mai da shi cikakke har abada. ");
INSERT INTO hausa_vpl VALUES ("HB8_1","088_8_1","HEB","8","1","1","Abin da muke magana a nan shi ne, muna da irin wannan babban firist, wanda ya zauna a hannun dama na kursiyin Maɗaukaki a sama, ");
INSERT INTO hausa_vpl VALUES ("HB8_2","088_8_2","HEB","8","2","2","wanda yake hidima a cikin wuri mai tsarki, tabanakul na gaskiya wanda Ubangiji ne ya kafa, ba mutum ba. ");
INSERT INTO hausa_vpl VALUES ("HB8_3","088_8_3","HEB","8","3","3","Da yake dole kowane babban firist da aka naɗa yă miƙa baye-baye da hadayu, haka ma wannan ya bukaci yă kasance da abin da zai miƙa. ");
INSERT INTO hausa_vpl VALUES ("HB8_4","088_8_4","HEB","8","4","4","Da a ce yana a duniya ne, da bai zama firist ba, domin a nan akwai mutanen da doka ta naɗa don su miƙa baye-baye. ");
INSERT INTO hausa_vpl VALUES ("HB8_5","088_8_5","HEB","8","5","5","Suna hidima a cikin tsattsarkan wuri wanda yake hoto da kuma siffar abin da yake cikin sama. Shi ya sa aka gargaɗi Musa sa’ad da yana dab da gina tabanakul cewa, “Ka lura fa, ka yi kome daidai bisa ga zānen da aka nuna maka a kan dutsen.” ");
INSERT INTO hausa_vpl VALUES ("HB8_6","088_8_6","HEB","8","6","6","Amma hidimar da Yesu ya karɓa tana da fifiko a kan tasu, kamar yadda alkawarin da shi ne yake matsakanci ya fi na dā fifiko nesa, an kuma kafa shi a kan alkawura mafi kyau. ");
INSERT INTO hausa_vpl VALUES ("HB8_7","088_8_7","HEB","8","7","7","Gama da a ce alkawari na fari ba shi da wani laifi, da ba sai an sāke neman wani ba. ");
INSERT INTO hausa_vpl VALUES ("HB8_8","088_8_8","HEB","8","8","8","Amma Allah ya sami mutane da laifi ya ce, “Ina gaya muku lokaci yana zuwa, sa’ad da zan yi sabon alkawari da gidan Isra’ila da kuma gidan Yahuda. ");
INSERT INTO hausa_vpl VALUES ("HB8_9","088_8_9","HEB","8","9","9","Ba zai zama kamar irin alkawarin da na yi da kakanni-kakanninsu sa’ad da na kama hannunsu don in fitar da su daga Masar ba, domin ba su yi aminci da alkawarina ba, sai na juya musu baya, in ji Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("HB8_10","088_8_10","HEB","8","10","10","Wannan shi ne alkawarin da zan yi da gidan Isra’ila, bayan lokacin nan, in ji Ubangiji. Zan sa dokokina a cikin zukatansu, in kuma rubuta su a kan zukatansu. Zan zama Allahnsu, su kuwa za su zama mutanena. ");
INSERT INTO hausa_vpl VALUES ("HB8_11","088_8_11","HEB","8","11","11","Mutum ba zai ƙara koya wa maƙwabcinsa ba, balle mutum yă ce wa ɗan’uwansa, ‘Ka san Ubangiji,’ domin dukansu za su san ni, daga ƙaraminsu zuwa babba. ");
INSERT INTO hausa_vpl VALUES ("HB8_12","088_8_12","HEB","8","12","12","Gama zan gafarta muguntarsu ba zan kuma ƙara tuna da zunubansu ba.” ");
INSERT INTO hausa_vpl VALUES ("HB8_13","088_8_13","HEB","8","13","13","Ta wurin kira wannan alkawari “sabo,” ya mai da na farin tsoho ke nan; abin da yake tsoho yana kuma daɗa tsufa, zai shuɗe nan ba da daɗewa ba. ");
INSERT INTO hausa_vpl VALUES ("HB9_1","088_9_1","HEB","9","1","1","Alkawarin farko ya ƙunshi ƙa’idodi don sujada da kuma tsattsarkan wuri a duniya. ");
INSERT INTO hausa_vpl VALUES ("HB9_2","088_9_2","HEB","9","2","2","An kafa tabanakul. A cikin ɗakinsa na farko akwai wurin ajiye fitila, tebur da kuma keɓaɓɓen burodi; an kira wannan Wuri Mai Tsarki. ");
INSERT INTO hausa_vpl VALUES ("HB9_3","088_9_3","HEB","9","3","3","Sa’an nan akwai labule, kuma a bayan labulen akwai ɗaki na biyu da ake kira Wuri Mafi Tsarki, ");
INSERT INTO hausa_vpl VALUES ("HB9_4","088_9_4","HEB","9","4","4","wanda yake da bagaden zinariya na turare da kuma akwatin alkawarin da aka dalaye da zinariya. A cikin akwatin alkawarin akwai tulun zinariya mai Manna a ciki, sandan Haruna wanda ya yi toho, da kuma allunan dutsen alkawari. ");
INSERT INTO hausa_vpl VALUES ("HB9_5","088_9_5","HEB","9","5","5","A bisa akwatin alkawarin kuwa akwai kerubobi na Ɗaukaka, waɗanda suka inuwantar da murfin kafara da fikafikansu. Sai dai ba za mu tattauna waɗannan abubuwa dalla-dalla a yanzu ba. ");
INSERT INTO hausa_vpl VALUES ("HB9_6","088_9_6","HEB","9","6","6","Sa’ad da aka shirya kome haka, sai firistoci suka shiga kullum cikin ɗaki na waje don su yi hidimarsu. ");
INSERT INTO hausa_vpl VALUES ("HB9_7","088_9_7","HEB","9","7","7","Amma babban firist ne kaɗai yakan shiga ɗaki na ciki-ciki, sau ɗaya tak a shekara, kuma sai da jini, wanda yakan miƙa domin zunubansa da kuma domin zunuban da mutane suka yi a cikin rashin sani. ");
INSERT INTO hausa_vpl VALUES ("HB9_8","088_9_8","HEB","9","8","8","Ta haka Ruhu Mai Tsarki ya nuna cewa ba a riga an bayyana hanyar shiga Wuri Mafi Tsarki ba tukuna, muddin tabanakul na fari yana nan tsaye. ");
INSERT INTO hausa_vpl VALUES ("HB9_9","088_9_9","HEB","9","9","9","Wannan ma yana da ma’ana wa mutane a yau. Ya nuna cewa ba za mu iya wanke lamirinmu ta wurin miƙa baye-baye da hadayu ba. ");
INSERT INTO hausa_vpl VALUES ("HB9_10","088_9_10","HEB","9","10","10","Waɗannan ƙa’idodi sun shafi sha’anin abinci da abin sha ne kawai da kuma ƙa’idodi tsarkake kanmu. Dokoki game da abubuwa na waje da ake amfani da su za su kasance ne sai lokacin ya yi da za a kawo abu mafi kyau. ");
INSERT INTO hausa_vpl VALUES ("HB9_11","088_9_11","HEB","9","11","11","Sa’ad da Kiristi ya zo a matsayin babban firist na kyawawan abubuwan da suka riga suka kasance a nan, ya bi ta cikin tabanakul mafi girma da kuma mafi cikakke wanda ba mutum ne ya yi ba, wato, ba na wannan halitta ba. ");
INSERT INTO hausa_vpl VALUES ("HB9_12","088_9_12","HEB","9","12","12","Bai shiga ta wurin jinin awaki da na maruƙa ba; amma ya shiga Wuri Mafi Tsarki sau ɗaya tak ta wurin jininsa, bayan ya samo madawwamiyar fansa. ");
INSERT INTO hausa_vpl VALUES ("HB9_13","088_9_13","HEB","9","13","13","In har akan yayyafa jinin awaki da na bijimai da kuma tokar karsanar a kan waɗanda suke marasa tsabta bisa ga al’ada, a tsarkake su yadda za su zama masu tsabta a waje, ");
INSERT INTO hausa_vpl VALUES ("HB9_14","088_9_14","HEB","9","14","14","balle jinin Kiristi, wanda ta wurin Ruhu madawwami ya miƙa kansa marar aibi ga Allah, ai, zai tsabtacce lamirinmu daga ayyukan da suke kai ga mutuwa, don mu bauta wa Allah mai rai! ");
INSERT INTO hausa_vpl VALUES ("HB9_15","088_9_15","HEB","9","15","15","Saboda haka Kiristi shi ne matsakancin sabon alkawari, don waɗanda aka kira su sami madawwamin gādon da aka yi alkawari, yanzu da ya mutu a matsayin mai fansa don yă ’yantar da su daga zunuban da aka aikata a ƙarƙashin alkawari na farko. ");
INSERT INTO hausa_vpl VALUES ("HB9_16","088_9_16","HEB","9","16","16","Sa’ad da wani ya yi alkawari game da gādonsa, dole a tabbatar da mutuwar wanda ya yi ta, ");
INSERT INTO hausa_vpl VALUES ("HB9_17","088_9_17","HEB","9","17","17","domin alkawarin gādo yana aiki ne kawai bayan mai yinsa ya mutu, ba ya taɓa aiki yayinda mai yinsa yana da rai. ");
INSERT INTO hausa_vpl VALUES ("HB9_18","088_9_18","HEB","9","18","18","Shi ya sa alkawari na farko bai fara aiki ba sai da aka zub da jini. ");
INSERT INTO hausa_vpl VALUES ("HB9_19","088_9_19","HEB","9","19","19","Sa’ad da Musa ya sanar wa dukan mutane kowane umarni na doka, sai ya ɗauki jinin maruƙa tare da ruwa, jan ulu da kuma rassan hizzob, ya yayyafa a kan naɗaɗɗen littafin da kuma a kan dukan mutanen. ");
INSERT INTO hausa_vpl VALUES ("HB9_20","088_9_20","HEB","9","20","20","Ya ce, “Wannan shi ne jinin alkawarin da Allah ya umarce ku ku kiyaye.” ");
INSERT INTO hausa_vpl VALUES ("HB9_21","088_9_21","HEB","9","21","21","Ta haka ya yayyafa jinin a kan tabanakul da kuma a kan dukan kayayyakin da ake amfani da su don yin hidima. ");
INSERT INTO hausa_vpl VALUES ("HB9_22","088_9_22","HEB","9","22","22","Tabbatacce, doka ta bukaci a tsabtacce kusa kowane abu da jini, kuma in ba tare da zub da jini ba babu gafara. ");
INSERT INTO hausa_vpl VALUES ("HB9_23","088_9_23","HEB","9","23","23","Waɗannan abubuwa hotuna ne kawai na abin da yake a sama, dole kuma a tsarkake su ta wurin waɗannan ƙa’idodi. Amma dole a tsarkake ainihin abubuwa na sama da wani abu mafi kyau. ");
INSERT INTO hausa_vpl VALUES ("HB9_24","088_9_24","HEB","9","24","24","Gama Kiristi bai shiga wani wuri tsattsarka da mutum ya yi ba, wanda yake hoto ne kawai na gaskataccen, a’a sama kanta ya shiga, domin yă bayyana a gaban zatin Allah a yanzu saboda mu. ");
INSERT INTO hausa_vpl VALUES ("HB9_25","088_9_25","HEB","9","25","25","Bai kuwa shiga sama domin yă yi ta miƙa kansa a kai a kai, yadda babban firist yake shiga Wuri Mafi Tsarki kowace shekara da jinin da ba nasa ba. ");
INSERT INTO hausa_vpl VALUES ("HB9_26","088_9_26","HEB","9","26","26","Da a ce haka ne, ai, da Kiristi ya sha wahala sau da yawa tun halittar duniya. Amma yanzu ya bayyana sau ɗaya tak a ƙarshen zamanai domin yă kawar da zunubi ta wurin miƙa kansa hadaya. ");
INSERT INTO hausa_vpl VALUES ("HB9_27","088_9_27","HEB","9","27","27","Kamar dai yadda aka ƙaddara wa mutum yă mutu sau ɗaya, bayan haka kuma sai shari’a, ");
INSERT INTO hausa_vpl VALUES ("HB9_28","088_9_28","HEB","9","28","28","haka aka miƙa Kiristi hadaya sau ɗaya domin yă ɗauke zunuban mutane masu yawa; zai kuma bayyana sau na biyu, ba don yă ɗauki zunubi ba, sai dai don yă kawo ceto ga waɗanda suke jiransa. ");
INSERT INTO hausa_vpl VALUES ("HB10_1","088_10_1","HEB","10","1","1","Dokar, inuwa ce kawai ta kyawawan abubuwa masu zuwa, wannan inuwar ba ita ce ainihin abubuwan ba ne. Saboda haka ba za tă taɓa mai da masu matsowa kusa don yin sujada cikakku ta wurin irin hadayun da ake maimaitawa ba fasawa shekara-shekara ba. ");
INSERT INTO hausa_vpl VALUES ("HB10_2","088_10_2","HEB","10","2","2","Da a ce za tă iya, da ba su daina miƙa hadayu ba? Ai, da an riga an tsabtacce masu yin sujada sau ɗaya tak, da kuma ba za su ƙara damuwa da zunubansu ba. ");
INSERT INTO hausa_vpl VALUES ("HB10_3","088_10_3","HEB","10","3","3","Amma waɗancan hadayu abin tunawa da zunubai ne na kowace shekara, ");
INSERT INTO hausa_vpl VALUES ("HB10_4","088_10_4","HEB","10","4","4","domin ba zai taɓa yiwuwa jinin bijimai da na awaki yă kawar da zunubai ba. ");
INSERT INTO hausa_vpl VALUES ("HB10_5","088_10_5","HEB","10","5","5","Saboda haka, sa’ad da Kiristi ya shigo duniya ya ce, “Hadaya da sadaka kam ba ka so, sai dai ka tanadar mini jiki; ");
INSERT INTO hausa_vpl VALUES ("HB10_6","088_10_6","HEB","10","6","6","hadayun ƙonawa da kuma hadayun zunubi ba ka ji daɗin. ");
INSERT INTO hausa_vpl VALUES ("HB10_7","088_10_7","HEB","10","7","7","Sai na ce, ‘Ga ni nan, a rubuce yake cikin naɗaɗɗen littafi na zo in aikata nufinka, ya Allah.’ ” ");
INSERT INTO hausa_vpl VALUES ("HB10_8","088_10_8","HEB","10","8","8","Da farko ya ce, “Hadayu da sadakoki, hadayun ƙonawa da hadayun zunubi ba ka so, ba ka kuwa jin daɗinsu” (ko da yake doka ta bukaci a yi su). ");
INSERT INTO hausa_vpl VALUES ("HB10_9","088_10_9","HEB","10","9","9","Sa’an nan ya ce, “Ga ni nan, na zo in aikata nufinka.” Ya kawar da na farkon domin yă kafa na biyun. ");
INSERT INTO hausa_vpl VALUES ("HB10_10","088_10_10","HEB","10","10","10","Kuma bisa ga wannan nufi, aka mai da mu masu tsarki ta wurin miƙa hadayar jikin Yesu Kiristi sau ɗaya tak. ");
INSERT INTO hausa_vpl VALUES ("HB10_11","088_10_11","HEB","10","11","11","Kowace rana kowane firist yakan tsaya yin hidimar ibadarsa; sau da sau yakan miƙa hadayu iri ɗaya, waɗanda ba za su taɓa kawar da zunubai ba. ");
INSERT INTO hausa_vpl VALUES ("HB10_12","088_10_12","HEB","10","12","12","Amma da Kiristi ya miƙa hadaya ɗaya ta dukan lokaci saboda zunubai, sai ya zauna a hannun dama na Allah. ");
INSERT INTO hausa_vpl VALUES ("HB10_13","088_10_13","HEB","10","13","13","Tun daga lokacin nan yana jira a mai da abokan gābansa matashin ƙafafunsa, ");
INSERT INTO hausa_vpl VALUES ("HB10_14","088_10_14","HEB","10","14","14","gama ta wurin hadayan nan guda ɗaya ya kammala har abada waɗanda ake tsarkake. ");
INSERT INTO hausa_vpl VALUES ("HB10_15","088_10_15","HEB","10","15","15","Ruhu Mai Tsarki ma ya yi mana shaida game da wannan. Da farko ya ce, ");
INSERT INTO hausa_vpl VALUES ("HB10_16","088_10_16","HEB","10","16","16","“Wannan shi ne alkawarin da zan yi da su bayan wannan lokaci, in ji Ubangiji. Zan sa dokokina a cikin zukatansu, in kuma rubuta su a kan zukatansu.” ");
INSERT INTO hausa_vpl VALUES ("HB10_17","088_10_17","HEB","10","17","17","Sai ya ƙara da cewa, “Zunubansu da kurakuransu ba zan ƙara tunawa da su ba.” ");
INSERT INTO hausa_vpl VALUES ("HB10_18","088_10_18","HEB","10","18","18","In an gafarta zunubai, babu sauran bukatar miƙa hadaya. ");
INSERT INTO hausa_vpl VALUES ("HB10_19","088_10_19","HEB","10","19","19","Saboda haka, ’yan’uwa, da yake muna da wannan tabbaci na shiga Wuri Mafi Tsarki ta wurin jinin Yesu, ");
INSERT INTO hausa_vpl VALUES ("HB10_20","088_10_20","HEB","10","20","20","ta wurin sabuwa, rayayyiyar hanya kuma wadda aka buɗe mana ta labulen nan, wato, jikinsa, ");
INSERT INTO hausa_vpl VALUES ("HB10_21","088_10_21","HEB","10","21","21","da yake kuma muna da babban firist mai mulkin gidan Allah, ");
INSERT INTO hausa_vpl VALUES ("HB10_22","088_10_22","HEB","10","22","22","bari mu matso kusa da Allah da zuciya mai gaskiya da kuma cikakken tabbaci mai zuwa ta wurin bangaskiya. Bari mu bar zukatan da tsabta, lamirinmu babu mugunta, da kuma jikunanmu a wanke da ruwa. ");
INSERT INTO hausa_vpl VALUES ("HB10_23","088_10_23","HEB","10","23","23","Bari mu tsaya da ƙarfi a kan ga begen da muka ce namu ne, gama shi da ya yi alkawarin, mai aminci ne. ");
INSERT INTO hausa_vpl VALUES ("HB10_24","088_10_24","HEB","10","24","24","Bari kuma mu yi tunani a kan yadda za mu gargaɗe juna ga ƙauna da kuma ayyuka nagari. ");
INSERT INTO hausa_vpl VALUES ("HB10_25","088_10_25","HEB","10","25","25","Kada mu daina taruwa kamar yadda waɗansu suka saba, sai dai mu ƙarfafa juna, tun ba ma da kuka ga Ranan nan tana kusatowa ba. ");
INSERT INTO hausa_vpl VALUES ("HB10_26","088_10_26","HEB","10","26","26","Ba wata hadayar da za a yi don mutanen da suka yanke shawara su yi ci gaba da yin zunubi da gangan bayan sun sami sanin gaskiya. ");
INSERT INTO hausa_vpl VALUES ("HB10_27","088_10_27","HEB","10","27","27","A maimakon haka za su kasance da babban fargabar hukunci da kuma ta ƙunar wuta wadda za tă cinye abokan gāban Allah. ");
INSERT INTO hausa_vpl VALUES ("HB10_28","088_10_28","HEB","10","28","28","Duk wanda ya ƙi ya kiyaye dokar Musa akan kashe shi ba tausayi, a kan shaidar mutum biyu ko uku. ");
INSERT INTO hausa_vpl VALUES ("HB10_29","088_10_29","HEB","10","29","29","Wane irin hukunci mai tsanani ne kuke tsammani zai dace da mutumin da ya nuna rashin bangirma ga Ɗan Allah, wanda ya yi banza da jinin nan na alkawarin da ya tsarkake shi, wanda kuma ya zargi Ruhun alheri? ");
INSERT INTO hausa_vpl VALUES ("HB10_30","088_10_30","HEB","10","30","30","Gama mun san shi, wannan wanda ya ce, “Ramuwa tawa ce; zan rama,” da kuma, “Ubangiji zai yi wa mutanensa hukunci.” ");
INSERT INTO hausa_vpl VALUES ("HB10_31","088_10_31","HEB","10","31","31","Abu mai matuƙar bantsoro ne a fāɗa cikin hannuwan Allah mai rai. ");
INSERT INTO hausa_vpl VALUES ("HB10_32","088_10_32","HEB","10","32","32","Ku tuna da kwanakin nan da suka wuce bayan kun sami haske, sa’ad da kuka tsaya daram a tsananin shan wahala. ");
INSERT INTO hausa_vpl VALUES ("HB10_33","088_10_33","HEB","10","33","33","Wani lokaci a fili an tsananta muku aka kuma zage ku aka kuma tsananta muku; a wani lokaci kuma kuka tsaya tare da waɗanda aka yi musu haka. ");
INSERT INTO hausa_vpl VALUES ("HB10_34","088_10_34","HEB","10","34","34","Kuka ji tausayin waɗanda suke cikin kurkuku, da farin ciki kuma kuka yarda ku rabu da dukiyar da aka ƙwace muku, domin ku kanku kun san cewa kuna da madawwamiyar dukiya mafi kyau. ");
INSERT INTO hausa_vpl VALUES ("HB10_35","088_10_35","HEB","10","35","35","Saboda haka kada ku yar da tabbacinku; za a sāka muku a yalwace. ");
INSERT INTO hausa_vpl VALUES ("HB10_36","088_10_36","HEB","10","36","36","Kuna bukata ku jimre don sa’ad da kuka aikata nufin Allah, za ku karɓi abin da ya yi alkawari. ");
INSERT INTO hausa_vpl VALUES ("HB10_37","088_10_37","HEB","10","37","37","Gama, “A cikin ɗan lokaci kaɗan, mai zuwan nan zai zo ba kuwa zai yi jinkiri ba. ");
INSERT INTO hausa_vpl VALUES ("HB10_38","088_10_38","HEB","10","38","38","Amma, “Mai adalcina zai rayu ta wurin bangaskiya. In kuwa ya ja da baya, ba zan ji daɗinsa ba.” ");
INSERT INTO hausa_vpl VALUES ("HB10_39","088_10_39","HEB","10","39","39","Amma mu ba na waɗanda suke ja da baya, su kuma hallaka ba ne, amma na waɗanda suka gaskata, suka kuma sami ceto ne. ");
INSERT INTO hausa_vpl VALUES ("HB11_1","088_11_1","HEB","11","1","1","Bangaskiya ita ce kasance tabbacin abin da muke bege a kai da kuma tabbatar da abin da ba mu gani ba. ");
INSERT INTO hausa_vpl VALUES ("HB11_2","088_11_2","HEB","11","2","2","Abin da aka yabi kakanni na dā a kai ke nan. ");
INSERT INTO hausa_vpl VALUES ("HB11_3","088_11_3","HEB","11","3","3","Ta wurin bangaskiya ne muka fahimci cewa an halicci duniya bisa ga umarnin Allah, saboda an halicce abin da ake gani daga abin da ba a gani. ");
INSERT INTO hausa_vpl VALUES ("HB11_4","088_11_4","HEB","11","4","4","Ta wurin bangaskiya Habila ya miƙa wa Allah hadayar da ta fi wadda Kayinu ya miƙa. Ta wurin bangaskiya aka yabe shi cewa shi mai adalci ne, sa’ad da Allah ya yi magana mai kyau game da bayarwarsa. Ta wurin bangaskiya kuma har yanzu yana magana, ko da yake ya riga ya mutu. ");
INSERT INTO hausa_vpl VALUES ("HB11_5","088_11_5","HEB","11","5","5","Ta wurin bangaskiya ne aka ɗauki Enok daga wannan rayuwa, ta haka bai ɗanɗana mutuwa ba; ba a kuwa same shi ba, domin Allah ya ɗauke shi. Gama kafin a ɗauke shi, an yabe shi a kan ya gamshi Allah. ");
INSERT INTO hausa_vpl VALUES ("HB11_6","088_11_6","HEB","11","6","6","In ba tare da bangaskiya ba kuwa, ba ya yiwuwa a gamshi Allah, domin duk mai zuwa wurin Allah dole yă gaskata cewa yana nan, kuma shi ne yakan sāka wa waɗanda suke nemansa da gaske. ");
INSERT INTO hausa_vpl VALUES ("HB11_7","088_11_7","HEB","11","7","7","Ta wurin bangaskiya Nuhu, sa’ad da aka yi masa gargaɗi a kan abubuwan da ba a gani ba tukuna, a cikin tsoro mai tsarki ya sassaƙa jirgi don ceton iyalinsa. Ta wurin bangaskiyarsa ya hukunta duniya ya kuma zama magājin adalcin da ake samu ta wurin bangaskiya. ");
INSERT INTO hausa_vpl VALUES ("HB11_8","088_11_8","HEB","11","8","8","Ta wurin bangaskiya ne Ibrahim, sa’ad da aka kira shi ya fita zuwa wata ƙasar da zai karɓi gādo daga baya, ya kuwa yi biyayya ya tafi, ko da yake bai san inda za shi ba. ");
INSERT INTO hausa_vpl VALUES ("HB11_9","088_11_9","HEB","11","9","9","Ta wurin bangaskiya ya yi zama a ƙasar da aka yi masa alkawari kamar baƙo a baƙuwar ƙasa; ya zauna a tentuna, haka ma Ishaku da Yaƙub, waɗanda su ma magādan alkawarin nan ne tare da shi. ");
INSERT INTO hausa_vpl VALUES ("HB11_10","088_11_10","HEB","11","10","10","Gama yana zuba ido ga birnin nan mai tushe, wanda mai zānen gininsa da kuma mai gininsa Allah ne. ");
INSERT INTO hausa_vpl VALUES ("HB11_11","088_11_11","HEB","11","11","11","Ta wurin bangaskiya Ibrahim, ko da yake shekarunsa sun wuce, Saratu kanta kuma bakararriya ce ya iya zama mahaifi domin ya amince cewa shi wanda ya yi alkawarin mai aminci ne. ");
INSERT INTO hausa_vpl VALUES ("HB11_12","088_11_12","HEB","11","12","12","Saboda haka, daga mutum ɗaya, wanda dā shi ma da matacce kusan ɗaya ne, zuriya masu yawa suka fito kamar taurari a sararin sama da kuma kamar yashin da ba a iya ƙirgawa a bakin teku. ");
INSERT INTO hausa_vpl VALUES ("HB11_13","088_11_13","HEB","11","13","13","Duk mutanen nan suna cikin bangaskiya sa’ad da suka mutu. Ba su kuwa karɓi abubuwan da aka yi alkawari ba; sun dai hango su suka kuma marabce su daga nesa. Suka kuma amince cewa su baƙi ne, bare kuma a duniya. ");
INSERT INTO hausa_vpl VALUES ("HB11_14","088_11_14","HEB","11","14","14","Mutane masu faɗin irin abubuwan nan sun nuna cewa suna neman ƙasar da take tasu. ");
INSERT INTO hausa_vpl VALUES ("HB11_15","088_11_15","HEB","11","15","15","Da a ce suna tunanin ƙasar da suka bari a baya, da sun riga sun sami damar komawa. ");
INSERT INTO hausa_vpl VALUES ("HB11_16","088_11_16","HEB","11","16","16","A maimako, suna marmarin wata ƙasa mafi kyau, ta sama. Saboda haka Allah ba ya kunya a kira shi Allahnsu, domin ya riga ya shirya musu birni. ");
INSERT INTO hausa_vpl VALUES ("HB11_17","088_11_17","HEB","11","17","17","Ta wurin bangaskiya Ibrahim, sa’ad da Allah ya gwada shi, sai ya miƙa Ishaku hadaya. Shi da ya karɓi alkawaran ya yi shirin miƙa makaɗaicin ɗansa, ");
INSERT INTO hausa_vpl VALUES ("HB11_18","088_11_18","HEB","11","18","18","ko da yake Allah ya ce masa, “Ta wurin Ishaku ne za a lissafta zuriyarka.” ");
INSERT INTO hausa_vpl VALUES ("HB11_19","088_11_19","HEB","11","19","19","Ibrahim ya yi tunani cewa Allah yana iya tā da matattu, a misalce kuwa, ya sāke karɓan Ishaku daga matattu. ");
INSERT INTO hausa_vpl VALUES ("HB11_20","088_11_20","HEB","11","20","20","Ta wurin bangaskiya ne Ishaku ya albarkaci Yaƙub da Isuwa game da nan gabansu. ");
INSERT INTO hausa_vpl VALUES ("HB11_21","088_11_21","HEB","11","21","21","Ta wurin bangaskiya ne Yaƙub, sa’ad da yake bakin mutuwa, ya albarkaci kowane ɗan Yusuf, ya kuma yi sujada yayinda yake jingine a kan sandansa. ");
INSERT INTO hausa_vpl VALUES ("HB11_22","088_11_22","HEB","11","22","22","Ta wurin bangaskiya ne Yusuf, sa’ad da kwanakinsa suka yi kusan ƙarewa, ya yi magana game da fitowar Isra’ilawa daga Masar ya kuma ba da umarni game da ƙasusuwansa. ");
INSERT INTO hausa_vpl VALUES ("HB11_23","088_11_23","HEB","11","23","23","Ta wurin bangaskiya ne iyayen Musa suka ɓoye shi har wata uku bayan haihuwarsa, domin sun ga cewa shi ba kamar sauran yara ba ne, ba su kuwa ji tsoron umarnin sarki ba. ");
INSERT INTO hausa_vpl VALUES ("HB11_24","088_11_24","HEB","11","24","24","Ta wurin bangaskiya ne Musa, sa’ad da ya yi girma, ya ƙi a kira shi ɗan diyar Fir’auna. ");
INSERT INTO hausa_vpl VALUES ("HB11_25","088_11_25","HEB","11","25","25","Ya zaɓa yă sha wahala tare da mutanen Allah, maimakon yă ji daɗin sha’awace-sha’awacen zunubi na ɗan lokaci. ");
INSERT INTO hausa_vpl VALUES ("HB11_26","088_11_26","HEB","11","26","26","Ya ɗauki wulaƙancin da yake sha saboda Kiristi ya fi dukiyar Masar daraja, domin ya sa ido ga ladansa. ");
INSERT INTO hausa_vpl VALUES ("HB11_27","088_11_27","HEB","11","27","27","Ta wurin bangaskiya ya bar Masar, ba tare da jin tsoron fushin sarki ba; ya kuwa jure domin ya ga wannan wanda ba a iya gani. ");
INSERT INTO hausa_vpl VALUES ("HB11_28","088_11_28","HEB","11","28","28","Ta wurin bangaskiya ya kiyaye Bikin Ƙetarewa ya kuma yayyafa jini, domin kada mai hallakar ’ya’yan fari yă taɓa ’ya’yan fari na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("HB11_29","088_11_29","HEB","11","29","29","Ta wurin bangaskiya ne mutane suka bi ta cikin Jan Teku, sai ka ce a kan busasshiyar ƙasa; amma da Masarawa suka yi ƙoƙari su yi haka, sai aka nutsar da su. ");
INSERT INTO hausa_vpl VALUES ("HB11_30","088_11_30","HEB","11","30","30","Ta wurin bangaskiya ne katangar Yeriko ta rushe, bayan mutane suka yi ta kewaye ta har kwana bakwai. ");
INSERT INTO hausa_vpl VALUES ("HB11_31","088_11_31","HEB","11","31","31","Ta wurin bangaskiya ne ba a kashe Rahab karuwan nan, ta tare da marasa biyayya ba don ta marabci ’yan leƙan asiri. ");
INSERT INTO hausa_vpl VALUES ("HB11_32","088_11_32","HEB","11","32","32","Me kuma zan faɗa? Ba ni da lokacin da zan ba da labari a kan Gideyon, Barak, Samson, Yefta, Dawuda, Sama’ila, da kuma annabawa, ");
INSERT INTO hausa_vpl VALUES ("HB11_33","088_11_33","HEB","11","33","33","waɗanda ta wurin bangaskiya ne suka ci nasara a kan mulkoki, suka aikata adalci, suka kuma sami abin da aka yi alkawari; waɗanda suka rurrufe bakunan zakoki, ");
INSERT INTO hausa_vpl VALUES ("HB11_34","088_11_34","HEB","11","34","34","suka kashe harshen wuta, suka kuma tsere wa kaifin takobi; waɗanda aka mai da rashin ƙarfinsu ya zama ƙarfi; waɗanda suka yi jaruntaka wajen yaƙi suka kuma fatattaki mayaƙan waɗansu ƙasashe. ");
INSERT INTO hausa_vpl VALUES ("HB11_35","088_11_35","HEB","11","35","35","Mata suka karɓi ƙaunatattunsu da aka sāke tasar daga matattu. Aka azabtar da yawancin mutanen nan, amma suka ƙi a sake su, domin sun tabbata za su sami lada mafi kyau sa’ad da aka tā da matattu. ");
INSERT INTO hausa_vpl VALUES ("HB11_36","088_11_36","HEB","11","36","36","Waɗansu suka sha ba’a da bulala, har da dauri da sarƙa, da kuma jefa su cikin kurkuku. ");
INSERT INTO hausa_vpl VALUES ("HB11_37","088_11_37","HEB","11","37","37","Aka jajjefe su da duwatsu; aka raba su biyu da zarto; aka kashe su da takobi. Suka yi ta yawo saye da fatun tumaki da na awaki, suka yi zaman rashi, suka sha tsanani da kuma wulaƙanci ");
INSERT INTO hausa_vpl VALUES ("HB11_38","088_11_38","HEB","11","38","38","duniya ba tă ma cancanci su zauna a cikinta ba. Suka yi ta yawo a cikin hamada da a kan duwatsu, da cikin kogwanni da kuma cikin ramummuka. ");
INSERT INTO hausa_vpl VALUES ("HB11_39","088_11_39","HEB","11","39","39","Waɗannan duka an yabe su saboda bangaskiyarsu, duk da haka babu waninsu da ya sami abin da aka yi alkawari. ");
INSERT INTO hausa_vpl VALUES ("HB11_40","088_11_40","HEB","11","40","40","Allah ya shirya mana wani abu mafi kyau. Kuma bai so su kai ga maƙasudin bangaskiyarsu ba sai tare da mu. ");
INSERT INTO hausa_vpl VALUES ("HB12_1","088_12_1","HEB","12","1","1","Saboda haka, da yake muna kewaye da irin wannan taron shaidu mai girma, sai mu yar da duk abin da yake hana mu da kuma zunubin da yake saurin daure mu, mu kuma yi tseren da aka sa a gabanmu da nacewa. ");
INSERT INTO hausa_vpl VALUES ("HB12_2","088_12_2","HEB","12","2","2","Bari mu kafa idanunmu a kan Yesu, tushe da kuma kammalar bangaskiyarmu, wanda ya jure kunyar gicciye da aka yi masa, domin ya san cewa daga baya zai yi farin ciki ya yi haka. Yanzu kuma yana zaune a hannun dama na kursiyin Allah. ");
INSERT INTO hausa_vpl VALUES ("HB12_3","088_12_3","HEB","12","3","3","Ku lura da wannan wanda ya jure da irin hamayyan nan daga masu zunubi, don kada ku gaji, har ku fid da zuciya. ");
INSERT INTO hausa_vpl VALUES ("HB12_4","088_12_4","HEB","12","4","4","Cikin famanku da zunubi, ba ku yi tsayayya har ga zub da jininku ba tukuna. ");
INSERT INTO hausa_vpl VALUES ("HB12_5","088_12_5","HEB","12","5","5","Kun kuma manta da kalmar ƙarfafawan nan da tana ce da ku ’ya’ya, “Ɗana kada ka rena horon Ubangiji, kada kuma ka fid da zuciya sa’ad da ya kwaɓe ka, ");
INSERT INTO hausa_vpl VALUES ("HB12_6","088_12_6","HEB","12","6","6","domin Ubangiji yakan hori waɗanda yake ƙauna, yakan kuma hori duk wanda yakan karɓa a matsayin ɗa.” ");
INSERT INTO hausa_vpl VALUES ("HB12_7","088_12_7","HEB","12","7","7","Ku jimre shan wahala a matsayin horo; Allah yana yi da ku kamar ’ya’ya. Gama wane ɗa ne mahaifinsa ba ya horonsa? ");
INSERT INTO hausa_vpl VALUES ("HB12_8","088_12_8","HEB","12","8","8","In ba a hore ku ba (kowa kuwa yakan sami horo), to, ku shegu ne ba ’ya’yan gida ba. ");
INSERT INTO hausa_vpl VALUES ("HB12_9","088_12_9","HEB","12","9","9","Ban da haka ma, dukanmu mun kasance da ubannin jiki waɗanda suka hore mu muka kuma yi musu ladabi. Ashe, bai kamata mu yi wa Uban ruhohinmu biyayya mu kuwa rayu ba! ");
INSERT INTO hausa_vpl VALUES ("HB12_10","088_12_10","HEB","12","10","10","Ubanninmu sun hore mu na ɗan lokaci yadda suka ga ya fi kyau; amma Allah yakan hore mu don amfaninmu, domin mu sami rabo cikin tsarkinsa. ");
INSERT INTO hausa_vpl VALUES ("HB12_11","088_12_11","HEB","12","11","11","Babu horon da yake da daɗi a lokacin da ake yinsa, sai dai zafi. Amma daga baya waɗanda suka horu ta haka sukan sami kwanciyar rai wadda aikin adalci yake bayarwa. ");
INSERT INTO hausa_vpl VALUES ("HB12_12","088_12_12","HEB","12","12","12","Saboda haka, sai ku ƙarfafa raunanan hannuwanku da gwiwoyinku marasa ƙarfi! ");
INSERT INTO hausa_vpl VALUES ("HB12_13","088_12_13","HEB","12","13","13","“Ku shirya hanyoyi marasa gargaɗa saboda ƙafafunku,” don kada guragu su daɗa gurguntawa, sai dai su warke. ");
INSERT INTO hausa_vpl VALUES ("HB12_14","088_12_14","HEB","12","14","14","Ku yi iyakacin ƙoƙari ku yi zaman lafiya da kowa, ku kuma zama masu tsarki; gama in ban da tsarki ba babu wanda zai ga Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("HB12_15","088_12_15","HEB","12","15","15","Ku lura fa kada wani yă kāsa samun alherin Allah, kada kuma wani tushen ɗacin rai yă tsira har yă kawo rikici, yă kuma ƙazantar da mutane da yawa. ");
INSERT INTO hausa_vpl VALUES ("HB12_16","088_12_16","HEB","12","16","16","Ku lura kada wani yă zama mai fasikanci, ko marar tsoron Allah kamar Isuwa, wanda saboda ƙwaryar abinci ɗaya tak ya sayar da gādonsa na ɗan fari. ");
INSERT INTO hausa_vpl VALUES ("HB12_17","088_12_17","HEB","12","17","17","Daga baya, kamar yadda kuka sani, sa’ad da ya nemi yă gāji wannan albarka, aka ƙi shi. Bai sami zarafin tuba ba, ko da yake ya nemi albarkan nan da hawaye. ");
INSERT INTO hausa_vpl VALUES ("HB12_18","088_12_18","HEB","12","18","18","Ba ku zo ga Dutsen Sinai wanda ana iya taɓawa ba, ko ga wuta mai ci sosai, ko ga duhu baƙi ƙirin, ko ");
INSERT INTO hausa_vpl VALUES ("HB12_19","088_12_19","HEB","12","19","19","ko busar ƙaho, ko ga irin wata murya mai magana da kalmomin da masu jinta suka yi roƙo kada su ƙara ji, ");
INSERT INTO hausa_vpl VALUES ("HB12_20","088_12_20","HEB","12","20","20","domin ba su iya jimrewa da abin da aka umarta cewa, “Ko da ma dabba ce ta taɓa dutsen, dole a jajjefe ta da duwatsu.” ");
INSERT INTO hausa_vpl VALUES ("HB12_21","088_12_21","HEB","12","21","21","Ganin wannan abu da matuƙar bantsoro yake, har Musa ya ce, “Ina rawar jiki don tsoro.” ");
INSERT INTO hausa_vpl VALUES ("HB12_22","088_12_22","HEB","12","22","22","Sai dai kun zo ne ga Dutsen Sihiyona, ga Urushalima ta sama, birnin Allah mai rai. Kun zo ga dubu dubban mala’ikun da suke cikin taron farin ciki, ");
INSERT INTO hausa_vpl VALUES ("HB12_23","088_12_23","HEB","12","23","23","kun zo ga ikkilisiyar ɗan fari, waɗanda sunayensu suna a rubuce a sama. Kun zo ga Allah, alƙalin dukan mutane, kun kuma zo ga ruhohin mutane masu adalci da aka mai da su cikakku. ");
INSERT INTO hausa_vpl VALUES ("HB12_24","088_12_24","HEB","12","24","24","Kun zo ga Yesu, mai yin sulhu na sabon alkawari, da kuma ga jinin da aka yayyafa wanda yake magana mafi kyau fiye da jinin Habila. ");
INSERT INTO hausa_vpl VALUES ("HB12_25","088_12_25","HEB","12","25","25","Ku lura fa kada ku ƙi wanda yake magana. Gama in su ba su tsira sa’ad da suka ƙi wanda ya gargaɗe su a wannan duniya ba, to, ƙaƙa mu za mu tsira, in mun ƙi jin wannan da yake yi mana gargaɗi daga Sama? ");
INSERT INTO hausa_vpl VALUES ("HB12_26","088_12_26","HEB","12","26","26","A lokacin nan muryarsa ta jijjiga duniya, amma yanzu ya yi alkawari cewa, “Har wa yau sau ɗaya tak zan ƙara jijjiga ba duniya kaɗai ba, amma har ma da sammai.” ");
INSERT INTO hausa_vpl VALUES ("HB12_27","088_12_27","HEB","12","27","27","Wannan magana “sau ɗayan nan” sun nuna, kawar da abin da za a iya jijjigawa, wato, ƙirƙiro abubuwa, saboda abubuwan da ba a iya jijjigawa, su kasance. ");
INSERT INTO hausa_vpl VALUES ("HB12_28","088_12_28","HEB","12","28","28","Saboda haka, da yake muna karɓar mulkin da ba ya jijjiguwa, sai mu yi godiya, ta haka kuwa mu yi wa Allah sujada yadda ya kamata, tare da bangirma da kuma tsoro, ");
INSERT INTO hausa_vpl VALUES ("HB12_29","088_12_29","HEB","12","29","29","gama “Allahnmu wuta ne mai cinyewa.” ");
INSERT INTO hausa_vpl VALUES ("HB13_1","088_13_1","HEB","13","1","1","Ku ci gaba da ƙaunar juna kamar ’yan’uwa. ");
INSERT INTO hausa_vpl VALUES ("HB13_2","088_13_2","HEB","13","2","2","Kada ku manta da yin alheri ga baƙi, gama ta yin haka ne waɗansu suka yi wa mala’iku hidima, ba da saninsu ba. ");
INSERT INTO hausa_vpl VALUES ("HB13_3","088_13_3","HEB","13","3","3","Ku riƙa tunawa da waɗanda suke a kurkuku kamar tare kuke a kurkuku, da kuma waɗanda ake gwada musu azaba, kamar ku ake yi wa. ");
INSERT INTO hausa_vpl VALUES ("HB13_4","088_13_4","HEB","13","4","4","Aure yă zama abin girmamawa ga kowa, a kuma kiyaye gadon aure da tsabta, gama Allah zai hukunta masu zina da kuma dukan masu fasikanci. ");
INSERT INTO hausa_vpl VALUES ("HB13_5","088_13_5","HEB","13","5","5","Ku kiyaye kanku daga yawan son kuɗi, ku kuma gamsu da abin da kuke da shi, gama Allah ya ce, “Ba zan taɓa bar ka ba; ba zan taɓa yashe ka ba.” ");
INSERT INTO hausa_vpl VALUES ("HB13_6","088_13_6","HEB","13","6","6","Saboda haka muna iya fitowa gabagadi, mu ce, “Ubangiji ne mai taimakona; ba zan ji tsoro ba. Me mutum zai iya yi mini?” ");
INSERT INTO hausa_vpl VALUES ("HB13_7","088_13_7","HEB","13","7","7","Ku tuna da shugabanninku, waɗanda suka faɗa muku maganar Allah. Ku dubi irin rayuwar da suka yi ku kuma yi koyi da bangaskiyarsu. ");
INSERT INTO hausa_vpl VALUES ("HB13_8","088_13_8","HEB","13","8","8","Yesu Kiristi ba ya sākewa, shi ne a jiya, shi ne a yau, shi ne kuma har abada. ");
INSERT INTO hausa_vpl VALUES ("HB13_9","088_13_9","HEB","13","9","9","Kada a ɗauke muku hankali da sababbin koyarwa dabam-dabam. Yana da kyau zukatanmu su ƙarfafa ta wurin alheri, ba ta wurin abinci waɗanda ba su da amfani ga waɗanda suke cinsu. ");
INSERT INTO hausa_vpl VALUES ("HB13_10","088_13_10","HEB","13","10","10","Muna da bagade inda firistocin da suka yi hidima a tabanakul ba su da izini su ci. ");
INSERT INTO hausa_vpl VALUES ("HB13_11","088_13_11","HEB","13","11","11","Babban firist yakan ɗauki jinin dabbobi yă shiga cikin Wuri Mafi Tsarki a matsayin hadaya ta zunubi, amma jikunan dabbobin akan ƙone su a bayan sansani. ");
INSERT INTO hausa_vpl VALUES ("HB13_12","088_13_12","HEB","13","12","12","Haka ma Yesu ya sha wahala a bayan gari don yă tsarkake mutane ta wurin jininsa. ");
INSERT INTO hausa_vpl VALUES ("HB13_13","088_13_13","HEB","13","13","13","Saboda haka, sai mu fita mu je wajensa a bayan sansani, muna ɗaukar kunyar da ya sha. ");
INSERT INTO hausa_vpl VALUES ("HB13_14","088_13_14","HEB","13","14","14","Gama a nan ba mu da dawwammamen birni, sai dai muna zuba ido a kan birnin nan mai zuwa. ");
INSERT INTO hausa_vpl VALUES ("HB13_15","088_13_15","HEB","13","15","15","Saboda haka, ta wurin Yesu, bari mu ci gaba da miƙa hadaya ta yabo ga Allah, yabon leɓuna da yake shaidar sunansa. ");
INSERT INTO hausa_vpl VALUES ("HB13_16","088_13_16","HEB","13","16","16","Kada kuma ku manta yin aikin nagari da kuma taimakon waɗansu, gama da irin waɗannan hadayu ne Allah yake jin daɗi. ");
INSERT INTO hausa_vpl VALUES ("HB13_17","088_13_17","HEB","13","17","17","Ku yi wa shugabanninku biyayya ku kuma miƙa kanku ga ikonsu. Suna lura da ku kuma za su ba da lissafi a gaban Allah. Saboda haka kada ku sa su yi fushi saboda aikinsu, ku sa su yi farin ciki. In ba haka ba za su iya taimakonku ba ko kaɗan. ");
INSERT INTO hausa_vpl VALUES ("HB13_18","088_13_18","HEB","13","18","18","Ku yi mana addu’a. Mun tabbata cewa muna da lamiri mai kyau, kuma muna da marmari mu yi rayuwa ta bangirma a ta kowace hanya. ");
INSERT INTO hausa_vpl VALUES ("HB13_19","088_13_19","HEB","13","19","19","Ni musamman, ina roƙonku ku yi addu’a, don a komo da ni a gare ku ba da daɗewa ba. ");
INSERT INTO hausa_vpl VALUES ("HB13_20","088_13_20","HEB","13","20","20","Bari Allah na salama, wanda ta wurin jinin madawwamin alkawari ya tā da Ubangijinmu Yesu daga matattu, wannan Makiyayin tumaki mai girma, ");
INSERT INTO hausa_vpl VALUES ("HB13_21","088_13_21","HEB","13","21","21","yă kintsa ku da kowane abu mai kyau domin aikata nufinsa, bari kuma yă aikata abin da zai gamshe shi cikinmu, ta wurin Yesu Kiristi, a gare shi ɗaukaka ta tabbata har abada. Amin. ");
INSERT INTO hausa_vpl VALUES ("HB13_22","088_13_22","HEB","13","22","22","’Yan’uwa, ina roƙonku ku yi haƙuri da wannan gargaɗi, don ba wata doguwar wasiƙa ce na rubuta muku ba. ");
INSERT INTO hausa_vpl VALUES ("HB13_23","088_13_23","HEB","13","23","23","Ina so ku san cewa an saki ɗan’uwanmu Timoti. In ya iso da wuri, zan zo tare da shi in gan ku. ");
INSERT INTO hausa_vpl VALUES ("HB13_24","088_13_24","HEB","13","24","24","Ku gai da dukan shugabanninku da kuma dukan mutanen Allah. Waɗanda suke Italiya suna gaishe ku. ");
INSERT INTO hausa_vpl VALUES ("HB13_25","088_13_25","HEB","13","25","25","Alheri yă kasance da ku duka.");
INSERT INTO hausa_vpl VALUES ("JM1_1","089_1_1","JAS","1","1","1","Yaƙub, bawan Allah da kuma na Ubangiji Yesu Kiristi, Zuwa ga kabilan nan goma sha biyu, da suke warwartse a cikin al’ummai. Gaisuwa mai yawa. ");
INSERT INTO hausa_vpl VALUES ("JM1_2","089_1_2","JAS","1","2","2","Ku ɗauki wannan da farin ciki mai tsabta, ’yan’uwana, duk sa’ad da gwaje-gwaje na kowane iri suka zo muku, ");
INSERT INTO hausa_vpl VALUES ("JM1_3","089_1_3","JAS","1","3","3","domin kun san cewa gwajin bangaskiyarku yakan haifi daurewa. ");
INSERT INTO hausa_vpl VALUES ("JM1_4","089_1_4","JAS","1","4","4","Dole daurewa ta kammala aikinta don ku zama balagaggu da kuma cikakku, ba ku kuma rasa kome ba. ");
INSERT INTO hausa_vpl VALUES ("JM1_5","089_1_5","JAS","1","5","5","In waninku ya rasa hikima, ya kamata yă roƙi Allah, mai bayarwa hannu sake ga kowa ba tare da gori ba, za a kuwa ba shi. ");
INSERT INTO hausa_vpl VALUES ("JM1_6","089_1_6","JAS","1","6","6","Amma sa’ad da ya roƙa, dole yă gaskata, ba tare da shakka ba, domin shi mai shakka, yana kama da raƙumar ruwan tekun da iska take kori tana kuma ɓuɓɓugowa. ");
INSERT INTO hausa_vpl VALUES ("JM1_7","089_1_7","JAS","1","7","7","Kada irin wannan mutum yă yi tsammani zai sami wani abu daga Ubangiji; ");
INSERT INTO hausa_vpl VALUES ("JM1_8","089_1_8","JAS","1","8","8","shi mai zuciya biyu ne, marar tsai da zuciyarsa wuri ɗaya a cikin duk abin da yake yi. ");
INSERT INTO hausa_vpl VALUES ("JM1_9","089_1_9","JAS","1","9","9","Bari ɗan’uwan da yake cikin halin ƙasƙanci yă yi taƙama a matsayinsa na ɗaukaka. ");
INSERT INTO hausa_vpl VALUES ("JM1_10","089_1_10","JAS","1","10","10","Amma wanda yake mai arziki, ya kamata yă yi taƙama a matsayinsa na ƙasƙanci, gama ba zai daɗe ba kamar furen jeji. ");
INSERT INTO hausa_vpl VALUES ("JM1_11","089_1_11","JAS","1","11","11","Gama in rana ta fito ta yi zafi mai tsanani sai ta sa tsiro yă yanƙwane tsiro; furensa yă kakkaɓe, kyansa kuma yă lalace. Haka ma mai arziki zai shuɗe yayinda yake cikin harkarsa. ");
INSERT INTO hausa_vpl VALUES ("JM1_12","089_1_12","JAS","1","12","12","Mai albarka ne mutumin da yake daurewa cikin gwaji, gama bayan ya yi nasara da gwajin, zai sami rawanin rai wanda Allah ya yi alkawari ga waɗanda suke ƙaunarsa. ");
INSERT INTO hausa_vpl VALUES ("JM1_13","089_1_13","JAS","1","13","13","Sa’ad da aka jarrabci mutum, kada yă ce, “Allah ne yake jarrabtarsa.” Gama ba ya yiwuwa a jarrabci Allah da mugunta, shi kuma ba ya jarrabtar kowa; ");
INSERT INTO hausa_vpl VALUES ("JM1_14","089_1_14","JAS","1","14","14","amma akan jarrabce kowane mutum sa’ad da muguwar sha’awarsa ta janye shi ta kuma rinjaye shi. ");
INSERT INTO hausa_vpl VALUES ("JM1_15","089_1_15","JAS","1","15","15","Sa’an nan, bayan da sha’awar ta yi ciki, takan haifi zunubi; zunubi kuwa, sa’ad da ya balaga yakan haifi mutuwa. ");
INSERT INTO hausa_vpl VALUES ("JM1_16","089_1_16","JAS","1","16","16","Kada a ruɗe ku, ’yan’uwana ƙaunatattu. ");
INSERT INTO hausa_vpl VALUES ("JM1_17","089_1_17","JAS","1","17","17","Kowane abu mai kyau da kuma kowace cikakkiyar kyauta daga sama suke, sun sauko ne daga wurin Uban haskoki, wanda ba sauyawa ko wata alamar sākewa a gare shi faufau. ");
INSERT INTO hausa_vpl VALUES ("JM1_18","089_1_18","JAS","1","18","18","Ya zaɓa yă haife mu ta wurin kalmar gaskiya, domin mu zama ’ya’yan fari na dukan abin da ya halitta. ");
INSERT INTO hausa_vpl VALUES ("JM1_19","089_1_19","JAS","1","19","19","’Yan’uwana ƙaunatattu, ku lura da wannan. Ya kamata kowa yă kasance mai saurin saurara, ba mai saurin magana ba, ba kuma mai saurin fushi ba, ");
INSERT INTO hausa_vpl VALUES ("JM1_20","089_1_20","JAS","1","20","20","gama fushin mutum ba ya kawo rayuwar adalcin da Allah yake so. ");
INSERT INTO hausa_vpl VALUES ("JM1_21","089_1_21","JAS","1","21","21","Saboda haka, ku rabu da ƙazamin hali da kuma kowace irin mugunta ku kuma yi na’am da maganar da aka shuka a cikinku da tawali’u, wadda za tă iya cetonku. ");
INSERT INTO hausa_vpl VALUES ("JM1_22","089_1_22","JAS","1","22","22","Kada ku zama masu ji kawai, ku ruɗi kanku. A maimakon haka ku zama masu yin abin da ta ce. ");
INSERT INTO hausa_vpl VALUES ("JM1_23","089_1_23","JAS","1","23","23","Duk wanda yake ji magana ne kawai, bai kuwa aikata abin da ta ce ba, yana kama da mutumin da ya kalli fuskarsa a madubi ");
INSERT INTO hausa_vpl VALUES ("JM1_24","089_1_24","JAS","1","24","24","bayan ya kalli kansa, sa’ad da ya tashi daga wurin, nan da nan sai yă manta da kamanninsa. ");
INSERT INTO hausa_vpl VALUES ("JM1_25","089_1_25","JAS","1","25","25","Amma duk mai duba cikakkiyar ƙa’idan nan ta ’yanci, ya kuma nace a kanta, ya zama ba mai ji ne kawai yă mance ba, sai dai mai yi ne yă zartar, to wannan shi za a yi wa albarka a cikin abin da yake yi. ");
INSERT INTO hausa_vpl VALUES ("JM1_26","089_1_26","JAS","1","26","26","In wani ya ɗauki kansa mai addini ne duk da haka bai ƙame harshensa ba, ruɗin kansa yake yi addininsa kuwa banza ne. ");
INSERT INTO hausa_vpl VALUES ("JM1_27","089_1_27","JAS","1","27","27","Addinin da Allah Ubanmu ya yarda da shi a matsayin mai tsabta da kuma marar aibi shi ne, a kula da marayu da gwauraye cikin damuwoyinsu, a kuma kiyaye kai daga lalacin da duniya take sa wa. ");
INSERT INTO hausa_vpl VALUES ("JM2_1","089_2_1","JAS","2","1","1","’Yan’uwana, a matsayinmu cikin Ubangiji Yesu Kiristi maɗaukaki, kada ku nuna bambanci. ");
INSERT INTO hausa_vpl VALUES ("JM2_2","089_2_2","JAS","2","2","2","A ce wani ya shigo cikin taronku saye da zoben zinariya da riguna masu tsada, wani matalauci kuma saye da tsummoki shi ma ya shigo, ");
INSERT INTO hausa_vpl VALUES ("JM2_3","089_2_3","JAS","2","3","3","in kuka mai da hankali na musamman ga mutumin da yake da riguna masu tsadan nan kuka kuma ce, “Ga wurin zama mai kyau dominka,” amma kuka ce wa matalaucin nan, “Kai tsaya daga can,” ko kuwa, “Ka zauna a ƙasa kusa da ƙafafuna,” ");
INSERT INTO hausa_vpl VALUES ("JM2_4","089_2_4","JAS","2","4","4","ashe, ba ku nuna bambanci a tsakaninku ke nan ba, kuka kuma zama alƙalai masu mugayen tunani? ");
INSERT INTO hausa_vpl VALUES ("JM2_5","089_2_5","JAS","2","5","5","Ku saurara, ’yan’uwana ƙaunatattu. Ashe, Allah bai zaɓi waɗanda suke matalauta a idon duniya don su zama masu wadata cikin bangaskiya, su kuma gāji mulkin da ya yi wa masu ƙaunarsa alkawari ba? ");
INSERT INTO hausa_vpl VALUES ("JM2_6","089_2_6","JAS","2","6","6","Ga shi kun wulaƙanta matalauta. Ashe, ba masu arziki ne suke cutarku ba? Ba su ba ne suke jan ku zuwa kotu? ");
INSERT INTO hausa_vpl VALUES ("JM2_7","089_2_7","JAS","2","7","7","Ba su ba ne suke ɓata sunan nan mai martaba wanda aka san ku da shi ba? ");
INSERT INTO hausa_vpl VALUES ("JM2_8","089_2_8","JAS","2","8","8","In fa kun kiyaye dokan nan ta mulki wadda take cikin Nassi mai cewa, “Ƙaunaci maƙwabcinka kamar kanka,” kun yi daidai. ");
INSERT INTO hausa_vpl VALUES ("JM2_9","089_2_9","JAS","2","9","9","Amma in kuka nuna bambanci, kun yi zunubi ke nan shari’a kuma ta same ku da laifi a matsayin masu karya doka. ");
INSERT INTO hausa_vpl VALUES ("JM2_10","089_2_10","JAS","2","10","10","Gama duk wanda ya kiyaye dukan doka amma ya yi tuntuɓe a kan abu ɗaya kaɗai, ya zama mai laifin karya dukansu ke nan. ");
INSERT INTO hausa_vpl VALUES ("JM2_11","089_2_11","JAS","2","11","11","Gama shi da ya ce, “Kada ka yi zina,” shi ne kuma ya ce, “Kada ka yi kisankai.” In kuwa ba ka zina amma kana kisankai, ka zama mai karya doka ke nan. ");
INSERT INTO hausa_vpl VALUES ("JM2_12","089_2_12","JAS","2","12","12","Ku yi magana ku kuma yi aiki kamar waɗanda za a yi musu shari’a bisa ga doka mai ba da ’yanci, ");
INSERT INTO hausa_vpl VALUES ("JM2_13","089_2_13","JAS","2","13","13","gama za a yi wa duk wanda bai nuna jinƙai ba hukunci babu jinƙai. Jinƙai yakan yi nasara a kan hukunci! ");
INSERT INTO hausa_vpl VALUES ("JM2_14","089_2_14","JAS","2","14","14","Wanda amfani ne, ’yan’uwana, a ce wani yă ce yana da bangaskiya, amma ba shi da ayyuka? Anya, wannan bangaskiya za tă iya cetonsa kuwa? ");
INSERT INTO hausa_vpl VALUES ("JM2_15","089_2_15","JAS","2","15","15","A ce wani ɗan’uwa ko ’yar’uwa ba shi da riguna ko abincin yini, ");
INSERT INTO hausa_vpl VALUES ("JM2_16","089_2_16","JAS","2","16","16","sai waninku yă ce masa, “Sauka lafiya, Allah ya ba da ci da sha da kuma sutura,” amma bai yi wani abu game da bukatunsa na jiki ba, ina amfani? ");
INSERT INTO hausa_vpl VALUES ("JM2_17","089_2_17","JAS","2","17","17","Haka ma bangaskiya ita kaɗai, in ba tare da ayyuka ba, matacciya ce. ");
INSERT INTO hausa_vpl VALUES ("JM2_18","089_2_18","JAS","2","18","18","Amma wani zai ce, “Kai kana da bangaskiya; ni kuma ina da ayyuka.” Ka nuna mini bangaskiyarka ba tare da ayyuka ba, ni kuma zan nuna maka bangaskiyata ta wurin abin da nake yi. ");
INSERT INTO hausa_vpl VALUES ("JM2_19","089_2_19","JAS","2","19","19","Ka gaskata cewa Allah ɗaya ne. To, da kyau! Ai, ko aljanu ma sun gaskata wannan, har da rawan jiki. ");
INSERT INTO hausa_vpl VALUES ("JM2_20","089_2_20","JAS","2","20","20","Kai wawa, kana son tabbaci cewa bangaskiya marar ayyuka banza ce? ");
INSERT INTO hausa_vpl VALUES ("JM2_21","089_2_21","JAS","2","21","21","Ashe, ba a mai da kakanmu Ibrahim mai adalci saboda abin da ya yi ba ne sa’ad da ya miƙa ɗansa Ishaku a bisa bagade? ");
INSERT INTO hausa_vpl VALUES ("JM2_22","089_2_22","JAS","2","22","22","Ai, ka gani cewa bangaskiyarsa da ayyukansa sun yi aiki tare, bangaskiyarsa kuma ta zama cikakkiya ta wurin abin da ya yi. ");
INSERT INTO hausa_vpl VALUES ("JM2_23","089_2_23","JAS","2","23","23","Aka kuma cika nassin nan da ya ce, “Ibrahim ya gaskata Allah, aka kuma lissafta wannan adalci ne gare shi,” aka kuma ce da shi abokin Allah. ");
INSERT INTO hausa_vpl VALUES ("JM2_24","089_2_24","JAS","2","24","24","Kun ga cewa ashe mutum zai sami kuɓuta ta wurin abin da ya yi ne ba ta wurin bangaskiya kaɗai ba. ");
INSERT INTO hausa_vpl VALUES ("JM2_25","089_2_25","JAS","2","25","25","Ta haka kuma ashe, Rahab karuwan nan ba a ɗauke ta mai adalci ce saboda abin da ta yi ba ne sa’ad da ta ba wa ’yan leƙen asirin nan masauƙi ta kuma sallame su suka tafi ta wata hanya dabam? ");
INSERT INTO hausa_vpl VALUES ("JM2_26","089_2_26","JAS","2","26","26","Kamar yadda jikin da babu ruhu matacce ne, haka ma bangaskiyar da babu ayyuka matacciya ce. ");
INSERT INTO hausa_vpl VALUES ("JM3_1","089_3_1","JAS","3","1","1","Kada yawancinku su so ɗaukan kansu a matsayin malamai, ’yan’uwana, domin kun san cewa mu da muke koyarwa za a yi mana shari’a mafi tsanani. ");
INSERT INTO hausa_vpl VALUES ("JM3_2","089_3_2","JAS","3","2","2","Dukanmu mukan yi tuntuɓe a hanyoyi dabam-dabam. In wani bai taɓa yin kuskure a cikin maganarsa ba, shi cikakke ne, yana kuma iya ƙame dukan jikinsa. ");
INSERT INTO hausa_vpl VALUES ("JM3_3","089_3_3","JAS","3","3","3","Sa’ad da muka sa linzamai a bakunan dawakai don mu sa su yi mana biyayya, mukan iya bin da dabbar gaba ɗaya. ");
INSERT INTO hausa_vpl VALUES ("JM3_4","089_3_4","JAS","3","4","4","Ko kuwa misali, mu dubi jiragen ruwa, mana. Ko da yake suna da girma ƙwarai kuma iska mai ƙarfi ce take tura su, ana tuƙa su da ɗan ƙaramin sandan ƙarfe ne zuwa duk inda mai tuƙin jirgin yake so. ");
INSERT INTO hausa_vpl VALUES ("JM3_5","089_3_5","JAS","3","5","5","Haka ma harshe yake, ga shi ɗan ƙanƙanin gaɓar jiki ne, amma sai manyan fariya. Ku dubi yadda ɗan ƙaramin ƙyastu yake ƙuna wa babban jeji wuta mana. ");
INSERT INTO hausa_vpl VALUES ("JM3_6","089_3_6","JAS","3","6","6","Harshe ma wuta ne! A cikin duk gaɓoɓinmu, harshe shi ne tushen kowace irin mugunta, mai ɓata mutum gaba ɗaya, mai zuga zuciyar mutum ta tafasa, shi kuwa jahannama ce take zuga shi. ");
INSERT INTO hausa_vpl VALUES ("JM3_7","089_3_7","JAS","3","7","7","Kowace irin dabba, tsuntsu, masu ja da ciki da kuma halittun da suke cikin teku an sarrafa su kuma mutum ne ya sarrafa, ");
INSERT INTO hausa_vpl VALUES ("JM3_8","089_3_8","JAS","3","8","8","amma ba mutumin da zai iya ya sarrafa harshe. Mugu ne marar hutu, cike da dafi mai kisa. ");
INSERT INTO hausa_vpl VALUES ("JM3_9","089_3_9","JAS","3","9","9","Da harshe mukan yabi Ubangijinmu da kuma Ubanmu, da shi kuma muke la’antar mutane, waɗanda aka halitta a kamannin Allah. ");
INSERT INTO hausa_vpl VALUES ("JM3_10","089_3_10","JAS","3","10","10","Daga wannan baki guda yabo da la’ana suke fitowa. ’Yan’uwana, wannan bai kamata yă zama haka ba. ");
INSERT INTO hausa_vpl VALUES ("JM3_11","089_3_11","JAS","3","11","11","Ruwa mai kyau da kuma ruwan gishiri zai iya fito daga maɓulɓula ɗaya? ");
INSERT INTO hausa_vpl VALUES ("JM3_12","089_3_12","JAS","3","12","12","’Yan’uwana, itacen ɓaure yana iya haifar ’ya’yan zaitun, ko kuma itacen inabi yă haifi ’ya’yan ɓaure? Haka ma, maɓulɓular ruwan gishiri ba zai iya ba da ruwa mai kyau ba. ");
INSERT INTO hausa_vpl VALUES ("JM3_13","089_3_13","JAS","3","13","13","Wane ne mai hikima da fahimta a cikinku? Bari yă nuna ta ta wurin rayuwarsa mai kyau, ta wurin ayyukan da aka yi cikin tawali’un da suke fitowa daga hikima. ");
INSERT INTO hausa_vpl VALUES ("JM3_14","089_3_14","JAS","3","14","14","Amma in kuna cike da mugun kishi da kuma sonkai a cikin zukatanku, kada ku yi taƙama game da wannan, ko ku danne gaskiya. ");
INSERT INTO hausa_vpl VALUES ("JM3_15","089_3_15","JAS","3","15","15","Irin wannan “hikima” ba daga sama ta sauko ba, ta duniya ce, ta rashin ruhaniya, ta Iblis kuma. ");
INSERT INTO hausa_vpl VALUES ("JM3_16","089_3_16","JAS","3","16","16","Gama inda akwai kishi da sonkai, a can za a tarar da hargitsi da kowane irin mugun aiki. ");
INSERT INTO hausa_vpl VALUES ("JM3_17","089_3_17","JAS","3","17","17","Amma hikimar da ta zo daga sama da fari tana da tsabta gaba ɗaya; sa’an nan mai ƙaunar salama ce, mai sanin ya kamata, mai biyayya, cike da jinƙai da aiki mai kyau, marar nuna bambanci, sahihiya kuma. ");
INSERT INTO hausa_vpl VALUES ("JM3_18","089_3_18","JAS","3","18","18","Masu salama da suke shuki cikin salama sukan girbe adalci. ");
INSERT INTO hausa_vpl VALUES ("JM4_1","089_4_1","JAS","4","1","1","Me yake jawo faɗace-faɗace da gardandami a tsakaninku? Ashe, ba sha’awace-sha’awacenku da suke yaƙi a zukatanku ba ne? ");
INSERT INTO hausa_vpl VALUES ("JM4_2","089_4_2","JAS","4","2","2","Kukan nemi abu ku rasa, sai ku yi kisa da ƙyashi. In kuka rasa abin da kuke nema sai ku shiga yin gardama da faɗa. Kukan rasa ne, domin ba ku roƙi Allah ba. ");
INSERT INTO hausa_vpl VALUES ("JM4_3","089_4_3","JAS","4","3","3","Sa’ad da kuka roƙa, ba kwa samu, don kun roƙa da mugun nufi, don ku kashe abin da kuka samu a kan sha’awace-sha’awacenku. ");
INSERT INTO hausa_vpl VALUES ("JM4_4","089_4_4","JAS","4","4","4","Ku mazinata, ba ku san cewa abokantaka da duniya gāba ce da Allah ba? Duk wanda ya zaɓa yă zama abokin duniya ya zama abokin gāban Allah ke nan. ");
INSERT INTO hausa_vpl VALUES ("JM4_5","089_4_5","JAS","4","5","5","Ko kuna tsammani a banza ne Nassi ya ce ruhun da ya sa yă zauna a cikinmu yana kishi sosai? ");
INSERT INTO hausa_vpl VALUES ("JM4_6","089_4_6","JAS","4","6","6","Amma yakan ba mu alheri a yalwace. Shi ya sa Nassi ya ce, “Allah yana gāba da masu girman kai amma yakan ba da alheri ga masu tawali’u.” ");
INSERT INTO hausa_vpl VALUES ("JM4_7","089_4_7","JAS","4","7","7","Saboda haka, ku miƙa kanku ga Allah. Ku yi tsayayya da Iblis, zai kuwa guje ku. ");
INSERT INTO hausa_vpl VALUES ("JM4_8","089_4_8","JAS","4","8","8","Ku matso kusa da Allah shi kuwa zai matso kusa da ku. Ku wanke hannuwanku, ku masu zunubi, ku kuma tsarkake zukatanku, ku masu zuciya biyu. ");
INSERT INTO hausa_vpl VALUES ("JM4_9","089_4_9","JAS","4","9","9","Ku yi baƙin ciki, ku yi makoki ku kuma yi kuka. Ku mai da dariyarku ta zama makoki, farin cikinku kuma yă zama ɓacin zuciya. ");
INSERT INTO hausa_vpl VALUES ("JM4_10","089_4_10","JAS","4","10","10","Ku ƙasƙantar da kanku a gaban Ubangiji, zai kuwa ɗaukaka ku. ");
INSERT INTO hausa_vpl VALUES ("JM4_11","089_4_11","JAS","4","11","11","’Yan’uwa, kada ku ɓata wa juna suna. Duk wanda ya zargi ɗan’uwansa ko ya ɗora masa laifi, yana gāba da doka ne yana kuma yin mata shari’a ke nan. In kuwa ka ɗora wa shari’a laifi, kai ba mai binta ba ne, mai ɗora mata laifi ne. ");
INSERT INTO hausa_vpl VALUES ("JM4_12","089_4_12","JAS","4","12","12","Akwai Mai ba da doka da kuma Alƙali guda ɗaya tak, shi ne yake da ikon ceto da kuma hallakarwa. Amma kai, wane ne da za ka hukunta maƙwabcinka? ");
INSERT INTO hausa_vpl VALUES ("JM4_13","089_4_13","JAS","4","13","13","Yanzu fa sai ku saurara, ku da kuke cewa, “Yau ko gobe za mu je wannan ko wancan birni, mu yi shekara a can, mu yi kasuwanci, mu ci riba.” ");
INSERT INTO hausa_vpl VALUES ("JM4_14","089_4_14","JAS","4","14","14","Alhali kuwa ba ku ma san abin da zai faru gobe ba. Wane iri ne ranku? Ku kamar hazo ne da yake bayyana na ɗan lokaci sa’an nan yă ɓace. ");
INSERT INTO hausa_vpl VALUES ("JM4_15","089_4_15","JAS","4","15","15","A maimakon haka, ya kamata ku ce, “In Ubangiji ya yarda, muna kuma a raye, za mu yi wannan ko wancan.” ");
INSERT INTO hausa_vpl VALUES ("JM4_16","089_4_16","JAS","4","16","16","Ga shi, kuna fariya da taƙama. Duk irin wannan taƙama mugun abu ne. ");
INSERT INTO hausa_vpl VALUES ("JM4_17","089_4_17","JAS","4","17","17","Saboda haka, duk wanda ya san abu mai kyan da ya kamata yă yi, bai kuwa yi ba, ya yi zunubi ke nan. ");
INSERT INTO hausa_vpl VALUES ("JM5_1","089_5_1","JAS","5","1","1","Yanzu fa sai ku saurara, ku masu arziki, ku yi kuka da ihu, saboda azabar da take zuwa a kanku. ");
INSERT INTO hausa_vpl VALUES ("JM5_2","089_5_2","JAS","5","2","2","Arzikinku ya ruɓa, asu kuma sun cinye tufafinku. ");
INSERT INTO hausa_vpl VALUES ("JM5_3","089_5_3","JAS","5","3","3","Zinariyarku da azurfarku sun yi tsatsa. Tsatsarsu kuwa za tă zama shaida a kanku, ta kuma ci namar jikinku kamar wuta. Kun ɓoye dukiya a kwanakin ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("JM5_4","089_5_4","JAS","5","4","4","Ga shi! Zaluncin da kuka yi na hakkin ma’aikatan gonakinku yana ta ƙara. Kukan masu girbi ya kai kunnuwan Ubangiji Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("JM5_5","089_5_5","JAS","5","5","5","Kun yi rayuwar jin daɗi a duniya kuna ci kuna sha na ganin dama. Kun ciyar da kanku kun yi ƙiba don ranar yanka. ");
INSERT INTO hausa_vpl VALUES ("JM5_6","089_5_6","JAS","5","6","6","Kun hukunta kun kuma kashe mutane marasa laifi, waɗanda ba su yi gāba da ku ba. ");
INSERT INTO hausa_vpl VALUES ("JM5_7","089_5_7","JAS","5","7","7","Saboda haka ’yan’uwa, sai ku yi haƙuri har dawowar Ubangiji. Ku dubi yadda manomi yakan jira gona ta ba da amfaninta mai kyau, da kuma yadda yake haƙurin jiran ruwan sama na damina da na kaka. ");
INSERT INTO hausa_vpl VALUES ("JM5_8","089_5_8","JAS","5","8","8","Haka ku ma, ku yi haƙuri, ku tsaya da ƙarfi, gama dawowar Ubangiji ya yi kusa. ");
INSERT INTO hausa_vpl VALUES ("JM5_9","089_5_9","JAS","5","9","9","’Yan’uwa, kada ku yi gunaguni da juna, don kada a hukunta ku. Alƙalin yana tsaye a bakin ƙofa! ");
INSERT INTO hausa_vpl VALUES ("JM5_10","089_5_10","JAS","5","10","10","’Yan’uwa, ku ɗauki annabawa da suka yi magana a cikin sunan Ubangiji, a matsayin gurbi na haƙuri a cikin shan wahala. ");
INSERT INTO hausa_vpl VALUES ("JM5_11","089_5_11","JAS","5","11","11","Kamar yadda kuka sani, mukan ce da waɗanda suka jure, masu albarka ne. Kun ji daurewar Ayuba, kuka kuma ga abin da Ubangiji ya yi a ƙarshe. Ubangiji yana cike da tausayi da jinƙai. ");
INSERT INTO hausa_vpl VALUES ("JM5_12","089_5_12","JAS","5","12","12","’Yan’uwana, fiye da kome, kada ku yi rantsuwa ko da sama, ko da ƙasa ko da wani abu dabam. Bari “I” naku yă zama “I”. “A’a” naku kuma yă zama “A’a”, don kada a hukunta ku. ");
INSERT INTO hausa_vpl VALUES ("JM5_13","089_5_13","JAS","5","13","13","Akwai waninku da yake shan wahala? Ya kamata yă yi addu’a. Akwai wani mai murna? Sai yă rera waƙoƙin yabo. ");
INSERT INTO hausa_vpl VALUES ("JM5_14","089_5_14","JAS","5","14","14","Akwai waninku da yake ciwo? Ya kamata yă kira dattawan ikkilisiya su yi masa addu’a, su kuma shafa masa mai cikin sunan Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("JM5_15","089_5_15","JAS","5","15","15","Addu’ar da aka yi cikin bangaskiya, za tă warkar da marar lafiya, Ubangiji zai tashe shi. In ya yi zunubi kuwa za a gafarta masa. ");
INSERT INTO hausa_vpl VALUES ("JM5_16","089_5_16","JAS","5","16","16","Saboda haka, ku furta wa juna zunubanku, ku yi addu’a saboda juna, domin ku sami warkarwa. Addu’ar mai adalci tana da iko da kuma amfani. ");
INSERT INTO hausa_vpl VALUES ("JM5_17","089_5_17","JAS","5","17","17","Iliya mutum ne kamar mu. Ya yi addu’a da gaske don kada a yi ruwan sama, ba a kuma yi ruwan sama a ƙasar ba har shekaru uku da rabi. ");
INSERT INTO hausa_vpl VALUES ("JM5_18","089_5_18","JAS","5","18","18","Ya sāke yin addu’a, sai sammai suka ba da ruwan sama, ƙasa kuma ta ba da amfaninta. ");
INSERT INTO hausa_vpl VALUES ("JM5_19","089_5_19","JAS","5","19","19","’Yan’uwana, in waninku ya kauce daga gaskiya, wani kuma ya komo da shi, ");
INSERT INTO hausa_vpl VALUES ("JM5_20","089_5_20","JAS","5","20","20","sai yă tuna da wannan. Duk wanda ya komo da mai zunubi daga kaucewarsa, zai cece shi daga mutuwa, yă kuma rufe zunubai masu ɗumbun yawa.");
INSERT INTO hausa_vpl VALUES ("P11_1","090_1_1","1PE","1","1","1","Bitrus, manzon Yesu Kiristi, Zuwa ga zaɓaɓɓu na Allah, baƙi a duniya, da suke a warwatse ko’ina a Fontus, Galatiya, Kaffadokiya, Asiya da kuma Bitiniya, ");
INSERT INTO hausa_vpl VALUES ("P11_2","090_1_2","1PE","1","2","2","waɗanda aka zaɓa bisa ga rigyasanin Allah Uba, ta wurin aikin tsarkakewar Ruhu, don biyayya ga Yesu Kiristi, su kuma sami yayyafan jininsa. Alheri da salama su zama naku a yalwace. ");
INSERT INTO hausa_vpl VALUES ("P11_3","090_1_3","1PE","1","3","3","Yabo ya tabbata ga Allah Uban Ubangijinmu Yesu Kiristi! Cikin jinƙansa mai girma ya ba mu sabuwar haihuwa cikin bege mai rai ta wurin tashin Yesu Kiristi daga matattu, ");
INSERT INTO hausa_vpl VALUES ("P11_4","090_1_4","1PE","1","4","4","da kuma cikin gādon da ba zai taɓa lalacewa, ɓacewa ko koɗewa ba, ajiyayye a sama dominku, ");
INSERT INTO hausa_vpl VALUES ("P11_5","090_1_5","1PE","1","5","5","ku waɗanda ta wurin bangaskiya ake kiyayewa ta wurin ikon Allah har yă zuwa ceton da yake a shirye da za a bayyana a ƙarshen lokaci. ");
INSERT INTO hausa_vpl VALUES ("P11_6","090_1_6","1PE","1","6","6","A kan wannan kuke cike da farin ciki ƙwarai, ko da yake yanzu na ɗan lokaci kuna fuskantar baƙin ciki daga gwaje-gwaje iri-iri. ");
INSERT INTO hausa_vpl VALUES ("P11_7","090_1_7","1PE","1","7","7","Wannan kuwa domin a tabbatar da sahihancin bangaskiyarku ne, wadda ta fi zinariya daraja nesa, ita zinariya kuwa, ko da yake mai ƙarewa ce, akan gwada ta da wuta, domin bangaskiyan nan taku ta jawo muku yabo da girma da ɗaukaka a bayyanar Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("P11_8","090_1_8","1PE","1","8","8","Ko da yake ba ku taɓa ganinsa ba, kuna ƙaunarsa; kuma ko da yake ba kwa ganinsa yanzu, kun gaskata shi, kun kuma cika da farin ciki ƙwarai, wanda ya fi gaban faɗi, ");
INSERT INTO hausa_vpl VALUES ("P11_9","090_1_9","1PE","1","9","9","gama kuna samun sakamakon bangaskiyarku, ceton rayukanku ke nan. ");
INSERT INTO hausa_vpl VALUES ("P11_10","090_1_10","1PE","1","10","10","Game da ceton nan, annabawa, waɗanda suka yi maganar alherin da za tă zo gare ku, sun yi bincike mai zurfi, a natse, ");
INSERT INTO hausa_vpl VALUES ("P11_11","090_1_11","1PE","1","11","11","suna ƙoƙari su san lokaci da kuma yanayin da Ruhun Kiristi da yake cikinsu yana nunawa sa’ad da ya yi faɗi a kan wahalolin Kiristi da kuma ɗaukaka da za tă bi. ");
INSERT INTO hausa_vpl VALUES ("P11_12","090_1_12","1PE","1","12","12","Aka bayyana musu cewa ba kansu ne suke bauta wa ba sai ku, sa’ad da suka yi maganar abubuwan da aka faɗa muku ta wurin waɗanda suka yi muku wa’azin bishara, ta wurin Ruhu Mai Tsarki wanda aka aika daga sama. Ko mala’iku ma suna marmari su ga waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("P11_13","090_1_13","1PE","1","13","13","Saboda haka, ku shirya kanku don aiki; ku zama masu kamunkai; ku kafa begenku duka a kan alherin da za a ba ku sa’ad da aka bayyana Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("P11_14","090_1_14","1PE","1","14","14","Kamar ’ya’ya masu biyayya, kada ku bi mugayen sha’awace-sha’awacen da dā kuke da su sa’ad da kuke rayuwa a cikin jahilci. ");
INSERT INTO hausa_vpl VALUES ("P11_15","090_1_15","1PE","1","15","15","Amma kamar yadda wanda ya kira ku yake mai tsarki, haka ku ma sai ku kasance masu tsarki cikin dukan abubuwan da kuke yi; ");
INSERT INTO hausa_vpl VALUES ("P11_16","090_1_16","1PE","1","16","16","gama a rubuce yake cewa, “Ku zama masu tsarki, domin ni mai tsarki ne.” ");
INSERT INTO hausa_vpl VALUES ("P11_17","090_1_17","1PE","1","17","17","Tun da yake kuna kira ga Uba wanda yake yin wa kowane mutum shari’a bisa ga ayyukansa ba bambanci, sai ku yi rayuwarku a nan kamar baƙi cikin tsoro mai bangirma. ");
INSERT INTO hausa_vpl VALUES ("P11_18","090_1_18","1PE","1","18","18","Gama kun san cewa ba da abubuwa masu lalacewa kamar azurfa ko zinariya ce aka fanshe ku daga rayuwar banza da kuka karɓa daga kakanni-kakanninku ba, ");
INSERT INTO hausa_vpl VALUES ("P11_19","090_1_19","1PE","1","19","19","sai dai an fanshe ku da jini mai daraja na Kiristi, ɗan rago marar aibi ko lahani. ");
INSERT INTO hausa_vpl VALUES ("P11_20","090_1_20","1PE","1","20","20","An zaɓe shi kafin halittar duniya, amma an bayyana shi a zamanin ƙarshe saboda ku. ");
INSERT INTO hausa_vpl VALUES ("P11_21","090_1_21","1PE","1","21","21","Ta gare shi ne kuka gaskata da Allah, wanda ya tā da shi daga matattu, aka kuma ɗaukaka shi, ta haka bari bangaskiyarku da begenku su kasance ga Allah. ");
INSERT INTO hausa_vpl VALUES ("P11_22","090_1_22","1PE","1","22","22","Yanzu da kuka tsarkake kanku ta wurin yin biyayya ga gaskiyan nan, don ku kasance da ƙauna mai gaskiya wa ’yan’uwanku, sai ku ƙaunaci juna ƙwarai, daga zuciya. ");
INSERT INTO hausa_vpl VALUES ("P11_23","090_1_23","1PE","1","23","23","Gama an sāke haihuwarku, ba da iri da yake lalacewa ba, sai dai marar lalacewa, ta wurin rayayyiya da kuma madawwamiyar maganar Allah. ");
INSERT INTO hausa_vpl VALUES ("P11_24","090_1_24","1PE","1","24","24","Gama, “Dukan mutane kamar ciyawa suke, darajarsu kuma kamar furannin jeji ne; ciyawa takan yanƙwane furannin kuma su kakkaɓe, ");
INSERT INTO hausa_vpl VALUES ("P11_25","090_1_25","1PE","1","25","25","amma maganar Ubangiji tana nan har abada.” Wannan kuwa ita ce kalmar da aka yi muku wa’azi. ");
INSERT INTO hausa_vpl VALUES ("P12_1","090_2_1","1PE","2","1","1","Saboda haka, ku rabu da kowace ƙeta da dukan ruɗu, munafunci, kishi, da kuma kowace irin ɓata suna. ");
INSERT INTO hausa_vpl VALUES ("P12_2","090_2_2","1PE","2","2","2","Kamar sababbin jarirai, ku yi marmarin madara zalla ta ruhaniya, domin ta wurinta za ku yi girma cikin cetonku, ");
INSERT INTO hausa_vpl VALUES ("P12_3","090_2_3","1PE","2","3","3","yanzu da kuka ɗanɗana alherin Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("P12_4","090_2_4","1PE","2","4","4","Da kuka zo gare shi, rayayyen Dutse, da mutane suka ƙi amma Allah ya zaɓa, kuma mai daraja a gare shi ");
INSERT INTO hausa_vpl VALUES ("P12_5","090_2_5","1PE","2","5","5","ku ma, a matsayinku na duwatsu masu rai, ana gina ku ga zama gidan ruhaniya don ku zama tsattsarkar ƙungiyar firistoci, kuna miƙa hadayun ruhaniya, abin karɓa ga Allah ta wurin Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("P12_6","090_2_6","1PE","2","6","6","Gama a cikin Nassi an ce, “Ga shi, na kafa dutse a Sihiyona, zaɓaɓɓen dutse na kusurwar gini mai daraja, wanda kuma ya dogara gare shi ba zai taɓa kunyata ba.” ");
INSERT INTO hausa_vpl VALUES ("P12_7","090_2_7","1PE","2","7","7","A gare ku da kuka gaskata, wannan dutse mai daraja ne. Amma ga waɗanda ba su gaskata ba, “Dutsen da magina suka ƙi ya zama dutsen kusurwar gini, ");
INSERT INTO hausa_vpl VALUES ("P12_8","090_2_8","1PE","2","8","8","kuma, “Dutse ne da yake sa mutane tuntuɓe kuma fā ne da yake sa su fāɗi.” Sun yi tuntuɓe domin sun ƙi su yi biyayya da saƙon, wanda kuma yake abin da aka ƙaddara musu. ");
INSERT INTO hausa_vpl VALUES ("P12_9","090_2_9","1PE","2","9","9","Amma ku zaɓaɓɓu ne, ƙungiyar firistocin babban Sarki, al’umma mai tsarki, jama’a mallakar Allah, domin ku shaida yabon shi wanda ya kira ku daga cikin duhu zuwa haskensa mai banmamaki. ");
INSERT INTO hausa_vpl VALUES ("P12_10","090_2_10","1PE","2","10","10","Dā ku ba mutane ba ne, amma yanzu ku mutanen Allah ne; Dā ba ku karɓi jinƙai ba, amma yanzu kun karɓi jinƙai. ");
INSERT INTO hausa_vpl VALUES ("P12_11","090_2_11","1PE","2","11","11","Abokaina ƙaunatattu, ina roƙonku, a matsayin bare da kuma baƙi a duniya, ku rabu da sha’awace-sha’awacen zunubin da suke yaƙi da ranku. ");
INSERT INTO hausa_vpl VALUES ("P12_12","090_2_12","1PE","2","12","12","Ku yi irin rayuwa mai kyau a cikin masu bautar gumaka, yadda ko da sun zarge ku da yin laifi, za su iya ganin ayyukanku nagari, su ɗaukaka Allah a ranar da zai ziyarce mu. ");
INSERT INTO hausa_vpl VALUES ("P12_13","090_2_13","1PE","2","13","13","Saboda Ubangiji, ku yi biyayya ga kowace hukumar da aka kafa cikin mutane, ko ga sarki, a matsayi wanda ya fi iko, ");
INSERT INTO hausa_vpl VALUES ("P12_14","090_2_14","1PE","2","14","14","ko ga gwamnoni, waɗanda ya aika domin su hukunta masu laifi su kuma yabi masu aikata abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("P12_15","090_2_15","1PE","2","15","15","Gama nufin Allah ne cewa ta wurin yin nagarta za ku toshe jahilcin marasa azanci. ");
INSERT INTO hausa_vpl VALUES ("P12_16","090_2_16","1PE","2","16","16","Ku yi rayuwa kamar mutanen da aka ’yantar, sai dai kada ku yi amfani da ’yancinku a matsayin hujjar aikata mugunta; ku yi rayuwa kamar bayin Allah. ");
INSERT INTO hausa_vpl VALUES ("P12_17","090_2_17","1PE","2","17","17","Ku nuna ladabin da ya dace ga kowa. Ku ƙaunaci ’yan’uwantakar masu bi, ku ji tsoron Allah, ku girmama sarki. ");
INSERT INTO hausa_vpl VALUES ("P12_18","090_2_18","1PE","2","18","18","Bayi, ku yi biyayya ga iyayengijinku da matuƙar ladabi, ba kawai ga waɗanda suke da kirki da masu sauƙinkai ba, amma har ga masu zafin rai ma. ");
INSERT INTO hausa_vpl VALUES ("P12_19","090_2_19","1PE","2","19","19","Gama abin yabo ne in mutum ya yi haƙuri cikin zafin wahalar rashin adalci saboda yana sane da Allah. ");
INSERT INTO hausa_vpl VALUES ("P12_20","090_2_20","1PE","2","20","20","Amma ina abin taƙama in kuka sha duka saboda kun yi laifi kuka kuma jimre? Sai dai in kuka sha wahala saboda yin nagari kuka kuma jimre, abin yabo ne a gaban Allah. ");
INSERT INTO hausa_vpl VALUES ("P12_21","090_2_21","1PE","2","21","21","Ga wannan ne aka kira ku, domin Kiristi ya sha wahala dominku, ya bar muku gurbin da ya kamata ku bi. ");
INSERT INTO hausa_vpl VALUES ("P12_22","090_2_22","1PE","2","22","22","“Bai taɓa yin laifi ba sam, ba a kuma sami ƙarya a bakinsa ba.” ");
INSERT INTO hausa_vpl VALUES ("P12_23","090_2_23","1PE","2","23","23","Sa’ad da suka zazzage shi, bai rama ba; sa’ad da ya sha wahala, bai yi barazana ba. A maimakon haka, ya miƙa kansa ga wanda yake shari’ar adalci. ");
INSERT INTO hausa_vpl VALUES ("P12_24","090_2_24","1PE","2","24","24","Shi kansa ya ɗauki zunubanmu a jikinsa a kan itace, domin mu mutu ga zunubai mu kuma rayu ga adalci; ta wurin raunukansa ne kuka sami warkarwa. ");
INSERT INTO hausa_vpl VALUES ("P12_25","090_2_25","1PE","2","25","25","Gama dā kuna kama da tumakin da suka ɓace, amma yanzu kun dawo ga Makiyayi da kuma Mai lura da rayukanku. ");
INSERT INTO hausa_vpl VALUES ("P13_1","090_3_1","1PE","3","1","1","Haka ma, ku matan aure, ku yi biyayya ga mazanku, domin in waɗansunsu ba su gaskata maganar ba, wataƙila a shawo kansu ba tare da magana ba ");
INSERT INTO hausa_vpl VALUES ("P13_2","090_3_2","1PE","3","2","2","sa’ad da suka ga rayuwarku mai tsabta da kuma na ladabi. ");
INSERT INTO hausa_vpl VALUES ("P13_3","090_3_3","1PE","3","3","3","Kyanku bai kamata yă zama na adon jiki ba, kamar kitso da sa kayan ado na zinariya da kuma sa kaya masu tsada. ");
INSERT INTO hausa_vpl VALUES ("P13_4","090_3_4","1PE","3","4","4","Maimakon haka, kyanku ya kamata yă zama ainihi na halinku na ciki, kyan da ba ya koɗewa na tawali’u da kuma na natsattsen ruhu, wanda yake mai daraja a gaban Allah. ");
INSERT INTO hausa_vpl VALUES ("P13_5","090_3_5","1PE","3","5","5","Gama haka matan masu tsarki na dā waɗanda suka sa begensu ga Allah suka yi wa kansu ado. Sun yi wa mazansu biyayya, ");
INSERT INTO hausa_vpl VALUES ("P13_6","090_3_6","1PE","3","6","6","kamar Saratu, wadda ta yi biyayya ga Ibrahim, har ta kira shi maigidanta. Ku ’ya’yanta ne mata in kun aikata abin da yake daidai, ba ku kuma ba tsoro dama ba. ");
INSERT INTO hausa_vpl VALUES ("P13_7","090_3_7","1PE","3","7","7","Mazan aure, ku ma, ku yi zaman sanin ya kamata yayinda kuke zama da matanku, ku girmama su a matsayin abokan zama marasa ƙarfi da kuma a matsayin magādan kyautar rai na alheri tare da ku, don kada wani abu yă hana addu’o’inku. ");
INSERT INTO hausa_vpl VALUES ("P13_8","090_3_8","1PE","3","8","8","A ƙarshe, dukanku ku zauna lafiya da juna; ku zama masu juyayi, kuna ƙaunar juna kamar ’yan’uwa, ku zama masu tausayi da kuma tawali’u. ");
INSERT INTO hausa_vpl VALUES ("P13_9","090_3_9","1PE","3","9","9","Kada ku rama mugunta da mugunta ko zagi da zagi, sai dai ku sa albarka, gama ga wannan ne aka kira ku, ku kuma gāji albarka. ");
INSERT INTO hausa_vpl VALUES ("P13_10","090_3_10","1PE","3","10","10","Gama, “Duk wanda yake so yă ji daɗin rayuwa, yă kuma ga kwanaki masu kyau dole yă ƙame harshensa daga mugunta leɓunansa kuma daga maganar yaudara. ");
INSERT INTO hausa_vpl VALUES ("P13_11","090_3_11","1PE","3","11","11","Dole yă juye daga mugunta, ya aikata nagarta; dole yă nemi salama yă kuma bi ta. ");
INSERT INTO hausa_vpl VALUES ("P13_12","090_3_12","1PE","3","12","12","Gama idanun Ubangiji suna a kan masu adalci kunnuwansa kuma suna jin addu’arsu, amma fuskar Ubangiji tana gāba da masu mugunta.” ");
INSERT INTO hausa_vpl VALUES ("P13_13","090_3_13","1PE","3","13","13","Wa zai yi muku lahani in kun himmantu ga yin nagarta? ");
INSERT INTO hausa_vpl VALUES ("P13_14","090_3_14","1PE","3","14","14","Amma ko da za ku sha wahala saboda abin da yake daidai, ku masu albarka ne. “Kada ku ji tsoron abin da suke tsoro; kada kuma ku firgita.” ");
INSERT INTO hausa_vpl VALUES ("P13_15","090_3_15","1PE","3","15","15","Sai dai a cikin zukatanku ku keɓe Kiristi a matsayin Ubangiji. A kullum, ku kasance a shirye ku ba da amsa ga duk wanda yake neman ku ba da dalilin wannan begen da kuke da shi. Amma ku yi wannan cikin tawali’u da ladabi, ");
INSERT INTO hausa_vpl VALUES ("P13_16","090_3_16","1PE","3","16","16","tare da lamiri mai kyau, saboda waɗanda suke maganganun banza a kan kyawawan ayyukanku cikin Kiristi su ji kunya da irin ɓata suna da suke yi. ");
INSERT INTO hausa_vpl VALUES ("P13_17","090_3_17","1PE","3","17","17","Ya fi kyau, in nufin Allah ne, a sha wahala don yin nagarta fiye da yin mugunta. ");
INSERT INTO hausa_vpl VALUES ("P13_18","090_3_18","1PE","3","18","18","Gama Kiristi ya mutu domin zunubi sau ɗaya tak, mai adalci saboda marasa adalci, don yă kawo ku ga Allah. An kashe shi a cikin jiki, amma an rayar da shi a Ruhu, ");
INSERT INTO hausa_vpl VALUES ("P13_19","090_3_19","1PE","3","19","19","ta wurin wanda kuma ya tafi ya yi wa ruhohin da suke a kurkuku wa’azi ");
INSERT INTO hausa_vpl VALUES ("P13_20","090_3_20","1PE","3","20","20","waɗanda dā ba su yi biyayya ba sa’ad da Allah ya jira da haƙuri a kwanaki Nuhu yayinda ake sassaƙa jirgi. A cikinsa mutane kima ne kawai, su takwas, aka kuɓutar ta ruwa, ");
INSERT INTO hausa_vpl VALUES ("P13_21","090_3_21","1PE","3","21","21","ruwan nan kuwa kwatancin baftisma ne da yanzu ya cece ku ku ma, ba kawar da dauda daga jiki ba, sai dai yin alkawari na lamiri mai kyau ga Allah. Ya cece ku ta wurin tashin Yesu Kiristi daga matattu, ");
INSERT INTO hausa_vpl VALUES ("P13_22","090_3_22","1PE","3","22","22","wanda ya tafi sama, yana kuma a hannun dama na Allah, mala’iku, mulkoki da kuma masu iko suna masa biyayya. ");
INSERT INTO hausa_vpl VALUES ("P14_1","090_4_1","1PE","4","1","1","Saboda haka, da yake Kiristi ya sha wahala a jikinsa, sai ku ma ku yi wa kanku ɗamara da irin wannan hali, gama wanda ya sha wahala a jikinsa ya gama da zunubi ke nan. ");
INSERT INTO hausa_vpl VALUES ("P14_2","090_4_2","1PE","4","2","2","Ta haka, ba ya sauran rayuwarsa a kan mugayen sha’awace-sha’awacen jiki, sai dai nufin Allah. ");
INSERT INTO hausa_vpl VALUES ("P14_3","090_4_3","1PE","4","3","3","Gama kun ɓata lokaci sosai a dā kuna yin abubuwan da masu bauta gumaka suka zaɓa su yi, kuna rayuwa cikin lalata, sha’awace-sha’awace, buguwa, shashanci, shaye-shaye da kuma bautar gumaka masu banƙyama. ");
INSERT INTO hausa_vpl VALUES ("P14_4","090_4_4","1PE","4","4","4","Sun yi mamaki da ba kwa haɗa kai da su a yanzu, da ba kwa kutsa kai tare da su cikin irin rayuwar banzan nan, har suna zaginku. ");
INSERT INTO hausa_vpl VALUES ("P14_5","090_4_5","1PE","4","5","5","Amma dole su ba da lissafi gare shi wanda yake a shirye yă shari’anta masu rai da matattu. ");
INSERT INTO hausa_vpl VALUES ("P14_6","090_4_6","1PE","4","6","6","Dalilin ke nan da ya sa aka yi wa’azin bishara har ga waɗanda yanzu suke mutattu, don ko da yake an hukunta su a matsayin mutane a batun jiki, amma su rayu ga Allah a batun ruhu. ");
INSERT INTO hausa_vpl VALUES ("P14_7","090_4_7","1PE","4","7","7","Ƙarshen abubuwa duka ya yi kusa. Saboda haka ku kasance masu tunani mai kyau da masu kamunkai don ku iya yin addu’a. ");
INSERT INTO hausa_vpl VALUES ("P14_8","090_4_8","1PE","4","8","8","Fiye da kome, ku ƙaunaci juna sosai, domin ƙauna tana rufe zunubai masu ɗumbun yawa. ");
INSERT INTO hausa_vpl VALUES ("P14_9","090_4_9","1PE","4","9","9","Ku riƙa karɓar juna ba da gunaguni ba. ");
INSERT INTO hausa_vpl VALUES ("P14_10","090_4_10","1PE","4","10","10","Kowa yă yi amfani da kowace baiwar da ya samu don kyautata wa waɗansu, cikin aminci yana aikata alherin Allah a hanyoyi dabam-dabam. ");
INSERT INTO hausa_vpl VALUES ("P14_11","090_4_11","1PE","4","11","11","In wani ya yi magana, ya kamata yă yi ta a matsayin wanda yake magana ainihin kalmomin Allah. In wani yana yin hidima, ya kamata yă yi ta da ƙarfin da Allah ya tanadar, domin a cikin kome a yabi Allah ta wurin Yesu Kiristi. A gare shi ɗaukaka da iko sun tabbata har abada abadin. Amin. ");
INSERT INTO hausa_vpl VALUES ("P14_12","090_4_12","1PE","4","12","12","Abokaina ƙaunatattu, kada ku yi mamakin gwaji mai tsananin da kuke sha, sai ka ce wani baƙon abu ne yake faruwa da ku. ");
INSERT INTO hausa_vpl VALUES ("P14_13","090_4_13","1PE","4","13","13","Sai dai ku yi murna cewa kuna tarayya cikin shan wahalolin Kiristi, domin ku kai ga farin ciki mai yawa sa’ad da aka bayyana ɗaukakarsa. ");
INSERT INTO hausa_vpl VALUES ("P14_14","090_4_14","1PE","4","14","14","In an zage ku saboda sunan Kiristi, ku masu albarka ne, gama Ruhun ɗaukaka da kuma na Allah yana bisanku. ");
INSERT INTO hausa_vpl VALUES ("P14_15","090_4_15","1PE","4","15","15","In kuna shan wahala, kada yă zama don ku masu kisankai ne ko ɓarayi ko masu wani irin laifi ko kuma masu shisshigi. ");
INSERT INTO hausa_vpl VALUES ("P14_16","090_4_16","1PE","4","16","16","Amma fa, in kuka sha wahala a matsayin ku Kirista ne, kada ku ji kunya, sai dai ku yabi Allah cewa kuna amsa wannan suna. ");
INSERT INTO hausa_vpl VALUES ("P14_17","090_4_17","1PE","4","17","17","Gama lokaci ya yi da za a fara yi wa iyalin Allah shari’a; in kuwa ya fara da mu, to, me zai faru da waɗanda ba sa biyayya da bisharar Allah? ");
INSERT INTO hausa_vpl VALUES ("P14_18","090_4_18","1PE","4","18","18","Kuma, “In da ƙyar masu adalci su kuɓuta, me zai faru da marasa tsoron Allah da kuma masu zunubi?” ");
INSERT INTO hausa_vpl VALUES ("P14_19","090_4_19","1PE","4","19","19","Saboda haka, waɗanda suke shan wahala bisa ga nufin Allah ya kamata su danƙa kansu ga Mahaliccinsu mai aminci, su kuma ci gaba da aikata abin da yake daidai. ");
INSERT INTO hausa_vpl VALUES ("P15_1","090_5_1","1PE","5","1","1","Zuwa ga dattawan da suke cikinku, ina roƙo a matsayin ɗan’uwanku dattijo, mashaidin shan wahalar Kiristi wanda kuma shi ma zai sami rabo cikin ɗaukakar da za a bayyana. ");
INSERT INTO hausa_vpl VALUES ("P15_2","090_5_2","1PE","5","2","2","Ku zama makiyayan garken Allah da yake a ƙarƙashin kulawarku, kuna hidima kamar masu kula, ba kan dole ba, sai dai da yardar rai, yadda Allah yake so ku zama; ban da kwaɗayin kuɗi, sai dai marmarin yin hidima; ");
INSERT INTO hausa_vpl VALUES ("P15_3","090_5_3","1PE","5","3","3","ban da nuna iko a kan waɗanda aka danƙa muku amana, sai dai ku zama gurbi ga garken. ");
INSERT INTO hausa_vpl VALUES ("P15_4","090_5_4","1PE","5","4","4","Sa’ad da kuwa Babban Makiyayin ya bayyana, za ku karɓi rawanin ɗaukaka marar koɗewa. ");
INSERT INTO hausa_vpl VALUES ("P15_5","090_5_5","1PE","5","5","5","Samari, ku ma, ku yi biyayya ga waɗanda suka girme ku. Dukanku, ku yafa sauƙinkai ga juna, domin, “Allah yana gāba da mai girman kai, amma yakan yi alheri ga mai sauƙinkai.” ");
INSERT INTO hausa_vpl VALUES ("P15_6","090_5_6","1PE","5","6","6","Saboda haka, ku ƙasƙantar da kanku a ƙarƙashin hannun Allah mai ƙarfi, don yă ɗaukaka ku a lokacin da ya ga dama. ");
INSERT INTO hausa_vpl VALUES ("P15_7","090_5_7","1PE","5","7","7","Ku danƙa masa dukan damuwarku, domin shi ne yake lura da ku. ");
INSERT INTO hausa_vpl VALUES ("P15_8","090_5_8","1PE","5","8","8","Ku zama masu kamunkai, ku kuma zauna a faɗake. Abokin gābanku, Iblis yana kewayewa kamar zaki mai ruri, yana neman wanda zai cinye. ");
INSERT INTO hausa_vpl VALUES ("P15_9","090_5_9","1PE","5","9","9","Ku yi tsayayya da shi, kuna tsayawa daram cikin bangaskiya, domin kun san cewa ’yan’uwanku ko’ina a duniya suna shan irin wahalolin nan. ");
INSERT INTO hausa_vpl VALUES ("P15_10","090_5_10","1PE","5","10","10","Allah mai dukan alheri, wanda ya kira ku ga madawwamiyar ɗaukaka cikin Kiristi, bayan kun sha wahala na ɗan lokaci, shi da kansa zai raya ku, yă kuma sa ku yi ƙarfi, ku kahu, ku kuma tsaya daram. ");
INSERT INTO hausa_vpl VALUES ("P15_11","090_5_11","1PE","5","11","11","Gare shi bari iko yă tabbata har abada abadin. Amin. ");
INSERT INTO hausa_vpl VALUES ("P15_12","090_5_12","1PE","5","12","12","Da taimakon Sila, wanda na ɗauka a matsayin ɗan’uwa mai aminci, na rubuta muku a taƙaice, ina ƙarfafa ku ina kuma shaida muku cewa wannan shi ne alherin Allah na gaske. Ku tsaya daram a cikinsa. ");
INSERT INTO hausa_vpl VALUES ("P15_13","090_5_13","1PE","5","13","13","Ita wadda take a Babilon, zaɓaɓɓiya tare da ku, tana gaishe ku, haka ma ɗana Markus. ");
INSERT INTO hausa_vpl VALUES ("P15_14","090_5_14","1PE","5","14","14","Ku gai da juna da sumbar ƙauna. Salama gare ku duka da kuke cikin Kiristi.");
INSERT INTO hausa_vpl VALUES ("P21_1","091_1_1","2PE","1","1","1","Siman Bitrus, bawa da kuma manzon Yesu Kiristi, Zuwa ga waɗanda ta wurin adalcin Allahnmu da Mai Cetonmu Yesu Kiristi sun sami bangaskiya mai daraja irin tamu. ");
INSERT INTO hausa_vpl VALUES ("P21_2","091_1_2","2PE","1","2","2","Alheri da salama su zama naku a yalwace ta wurin sanin Allah da Yesu Ubangijinmu. ");
INSERT INTO hausa_vpl VALUES ("P21_3","091_1_3","2PE","1","3","3","Ikonsa na Allahntaka ya ba mu kome da muke bukata don rayuwa da kuma tsoron Allah ta wurin sanin wanda ya kira mu ta wurin ɗaukakarsa da nagartarsa. ");
INSERT INTO hausa_vpl VALUES ("P21_4","091_1_4","2PE","1","4","4","Ta wurin waɗannan ya ba mu alkawaransa masu girma da kuma masu daraja, domin ta wurinsu ku iya yin tarayya cikin Allahntakarsa, ku kuma kuɓuta daga lalatar da take cikin duniya wadda mugayen sha’awace-sha’awace suke jawowa. ");
INSERT INTO hausa_vpl VALUES ("P21_5","091_1_5","2PE","1","5","5","Saboda haka, ku yi iyakar ƙoƙari ku ƙara wa bangaskiyarku nagarta; ga nagarta kuwa, ku ƙara mata sani; ");
INSERT INTO hausa_vpl VALUES ("P21_6","091_1_6","2PE","1","6","6","ga sani kuma ku ƙara masa kamunkai; ga kamunkai kuma ku ƙara da daurewa; ga daurewa kuwa ku ƙara da tsoron Allah; ");
INSERT INTO hausa_vpl VALUES ("P21_7","091_1_7","2PE","1","7","7","ga tsoron Allah kuma ku ƙara da nuna alheri ga ’yan’uwa; ga nuna alheri ga ’yan’uwa kuma ku ƙara da ƙauna. ");
INSERT INTO hausa_vpl VALUES ("P21_8","091_1_8","2PE","1","8","8","Domin in kuna ƙaruwa a waɗannan halaye, za su kāre ku daga rashin tasiri da rayuwa na rashin amfani cikin saninku na Ubangijinmu Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("P21_9","091_1_9","2PE","1","9","9","Amma in wani ba shi da su, ba shi da hangen nesa ke nan kuma makaho ne, ya kuma manta cewa an tsarkake shi daga zunubansa na dā. ");
INSERT INTO hausa_vpl VALUES ("P21_10","091_1_10","2PE","1","10","10","Saboda haka ’yan’uwana, ku ƙara aniya wajen tabbatar da kiranku da zaɓenku da aka yi. Gama in kuka yi waɗannan abubuwa, ba za ku taɓa fāɗuwa ba, ");
INSERT INTO hausa_vpl VALUES ("P21_11","091_1_11","2PE","1","11","11","za ku sami kyakkyawar marabta cikin madawwamin mulkin Ubangijinmu da Mai Cetonmu Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("P21_12","091_1_12","2PE","1","12","12","Saboda haka kullum zan tuna muku da waɗannan, ko da yake kun sansu kun kuma kahu ƙwarai cikin gaskiyar da kuke da ita yanzu. ");
INSERT INTO hausa_vpl VALUES ("P21_13","091_1_13","2PE","1","13","13","A ganina ya dace in tunashe ku muddin ina raye cikin tentin wannan jiki, ");
INSERT INTO hausa_vpl VALUES ("P21_14","091_1_14","2PE","1","14","14","domin na sani na kusa in ajiye shi a gefe, yadda Ubangijinmu Yesu Kiristi ya nuna mini a sarari. ");
INSERT INTO hausa_vpl VALUES ("P21_15","091_1_15","2PE","1","15","15","Zan kuwa yi iyakacin ƙoƙari in ga cewa bayan rabuwata kullum za ku iya tuna da waɗannan abubuwa. ");
INSERT INTO hausa_vpl VALUES ("P21_16","091_1_16","2PE","1","16","16","Ba mu bi tatsuniyoyin da aka ƙaga da wayo sa’ad da muka gaya muku game da ikon Ubangijinmu Yesu Kiristi da zuwansa ba, sai dai mu shaidu ne na ɗaukakarsa mai girma da muka gani da ido. ");
INSERT INTO hausa_vpl VALUES ("P21_17","091_1_17","2PE","1","17","17","Gama ya sami girma da ɗaukaka daga Allah Uba sa’ad da murya ta zo masa daga Mafificiyar Ɗaukaka cewa, “Wannan Ɗana ne, wanda nake ƙauna; da shi nake jin daɗi ƙwarai.” ");
INSERT INTO hausa_vpl VALUES ("P21_18","091_1_18","2PE","1","18","18","Mu kanmu mun ji wannan muryar da ta zo daga sama sa’ad da muke tare da shi a kan dutse mai tsarki. ");
INSERT INTO hausa_vpl VALUES ("P21_19","091_1_19","2PE","1","19","19","Muna kuwa da maganar annabawa da aka ƙara tabbatar mana, zai fi kyau in kuka lura da ita, kamar hasken da yake haskakawa a wuri mai duhu, har yă zuwa wayewar gari da kuma haskakawar tauraron asubahi a zukatanku. ");
INSERT INTO hausa_vpl VALUES ("P21_20","091_1_20","2PE","1","20","20","Gaba da kome dai, dole ku gane cewa babu annabcin Nassin da ya fito daga fassarar annabi da kansa. ");
INSERT INTO hausa_vpl VALUES ("P21_21","091_1_21","2PE","1","21","21","Gama annabci bai taɓa samo tushensa daga nufin mutum ba, sai dai mutane sun yi magana daga Allah yayinda Ruhu Mai Tsarki ya bishe su. ");
INSERT INTO hausa_vpl VALUES ("P22_1","091_2_1","2PE","2","1","1","Amma a dā akwai annabawan ƙarya a cikin mutane, kamar yadda za a sami malaman ƙarya a cikinku. A ɓoye za su shigar da karkataccen koyarwa mai hallaka, har ma su yi mūsun Ubangiji mai iko duka wanda ya saye su suna kawo wa kansu hallaka farat ɗaya. ");
INSERT INTO hausa_vpl VALUES ("P22_2","091_2_2","2PE","2","2","2","Da yawa za su bi hanyoyinsu na rashin kunya su kuma sa a rena hanyar gaskiya. ");
INSERT INTO hausa_vpl VALUES ("P22_3","091_2_3","2PE","2","3","3","Cikin kwaɗayinsu waɗannan malaman ƙarya za su cuce ku da tatsuniyoyin da suka ƙaga. Hukuncinsu yana a rataye a kansu tun da daɗewa, hallakarsu kuma ba ta barci. ");
INSERT INTO hausa_vpl VALUES ("P22_4","091_2_4","2PE","2","4","4","Gama in har Allah bai ƙyale mala’iku sa’ad da suka yi zunubi ba, amma ya tura su cikin lahira, domin a tsare su don hukunci; ");
INSERT INTO hausa_vpl VALUES ("P22_5","091_2_5","2PE","2","5","5","in har bai ƙyale duniya ta dā ba sa’ad da ya kawo ambaliya a kan mutanenta marasa tsoron Allah, amma ya kiyaye Nuhu, mai wa’azin adalci, da kuma waɗansu bakwai; ");
INSERT INTO hausa_vpl VALUES ("P22_6","091_2_6","2PE","2","6","6","in har ya hukunta biranen Sodom da Gomorra ta wurin ƙone su suka zama toka, ya kuma maishe su misali na abin da zai faru da marasa tsoron Allah; ");
INSERT INTO hausa_vpl VALUES ("P22_7","091_2_7","2PE","2","7","7","in kuwa har ya ceci Lot, mai adalci, wanda ya damu ainun da ƙazamar rayuwar mutane marasa bin doka; ");
INSERT INTO hausa_vpl VALUES ("P22_8","091_2_8","2PE","2","8","8","(adon kuwa abin da adalin nan ya yi, ya kuma gani, sa’ad da yake a cikinsu, sai kowace rana yakan ji ciwon aikinsu na kangara a zuciyarsa mai adalci) ");
INSERT INTO hausa_vpl VALUES ("P22_9","091_2_9","2PE","2","9","9","in haka ne, to, Ubangiji ya san yadda zai ceci mutane masu tsoron Allah daga gwaje-gwaje, yă kuma tsare marasa adalci don ranar hukunci, har yă zuwa ranar shari’a. ");
INSERT INTO hausa_vpl VALUES ("P22_10","091_2_10","2PE","2","10","10","Wannan gaskiya ce musamman ga waɗanda suke bin sha’awace-sha’awacen lalaci na mutuntaka, suna kuma rena masu mulki. Da ƙarfin hali da kuma girman kai, waɗannan mutane ba sa tsoro kawo zargin ɓata sunan talikan sama; ");
INSERT INTO hausa_vpl VALUES ("P22_11","091_2_11","2PE","2","11","11","duk da haka ko mala’iku ma da suka fi su ƙarfi suka kuma fi su iko, ba sa kawo irin wannan zargi na ɓata suna game da waɗannan talikai a gaban Ubangiji. ");
INSERT INTO hausa_vpl VALUES ("P22_12","091_2_12","2PE","2","12","12","Amma waɗannan mutane suna yin saɓo a kan abubuwan da ba su fahimta ba. Suna kama da dabbobi marasa hankali, halittun da suke bin abin da jikinsu ya faɗa musu kawai, waɗanda aka haifa don a kama a hallaka, kuma kamar dabbobi su ma za su hallaka. ");
INSERT INTO hausa_vpl VALUES ("P22_13","091_2_13","2PE","2","13","13","Za a yi musu sakamako da muguntar da suka yi. A ra’ayinsu jin daɗi shi ne a yi annashuwa da rana tsaka. Su ƙazamai ne marasa kunya, suna cike da jin daɗin sha’awace-sha’awacensu yayinda suke cin biki tare da ku. ");
INSERT INTO hausa_vpl VALUES ("P22_14","091_2_14","2PE","2","14","14","Idanunsu sun cike da zina, ba sa ƙoshi da yin zunubi; suna jarrabtar waɗanda ba tsayayyu ba; gwanaye ne a kan kwaɗayi, la’anannun iri! ");
INSERT INTO hausa_vpl VALUES ("P22_15","091_2_15","2PE","2","15","15","Sun bar miƙaƙƙiyar hanya suka bauɗe suna bin hanyar Bala’am ɗan Beyor, wanda ya yi ƙaunar hakkin mugunta. ");
INSERT INTO hausa_vpl VALUES ("P22_16","091_2_16","2PE","2","16","16","Amma an tsawata masa saboda laifinsa ta wurin jaki, dabbar da ba ta magana, wadda ta yi magana da muryar mutum ta kuma kwaɓi haukan annabin. ");
INSERT INTO hausa_vpl VALUES ("P22_17","091_2_17","2PE","2","17","17","Waɗannan mutane maɓulɓulai ne babu ruwa da kuma hazon da guguwar iska take kora. An shirya matsanancin duhu dominsu. ");
INSERT INTO hausa_vpl VALUES ("P22_18","091_2_18","2PE","2","18","18","Gama suna surutai banza na girman kai, ta wurin son bin fasikanci na mutuntaka, sukan jan hankulan mutanen da suke kuɓucewa daga waɗancan masu zama cikin kuskure. ");
INSERT INTO hausa_vpl VALUES ("P22_19","091_2_19","2PE","2","19","19","Suna yin musu alkawarin ’yanci, yayinda su kansu bayi ne ga aikin lalata gama mutum bawa ne ga duk abin da ya mallake shi. ");
INSERT INTO hausa_vpl VALUES ("P22_20","091_2_20","2PE","2","20","20","In har sun kuɓuta daga lalacin duniya ta wurin sanin Ubangijinmu da kuma Mai Cetonmu Yesu Kiristi sai suka sāke koma a cikin lalacin, har ya rinjaye su, za su fi muni a ƙarshe fiye da farko. ");
INSERT INTO hausa_vpl VALUES ("P22_21","091_2_21","2PE","2","21","21","Zai fi musu kyau da ba su taɓa sanin hanyar adalci ba, fiye da a ce sun sani sa’an nan su juya bayansu ga umarni mai tsarkin nan da aka ba su. ");
INSERT INTO hausa_vpl VALUES ("P22_22","091_2_22","2PE","2","22","22","A kansu karin maganan nan gaskiya ce, “Kare ya koma kan amansa,” da kuma, “Alade da aka yi wa wanka, ya koma birgimarsa cikin laka.” ");
INSERT INTO hausa_vpl VALUES ("P23_1","091_3_1","2PE","3","1","1","Abokaina ƙaunatattu, wannan ita ce wasiƙata ta biyu gare ku. Na rubuta su biyun su zama abin tuni don su faɗakar da ku ga tunani mai kyau. ");
INSERT INTO hausa_vpl VALUES ("P23_2","091_3_2","2PE","3","2","2","Ina so ku tuna da kalmomin da annabawa masu tsarki na dā suka faɗa da kuma umarnin da Ubangijinmu da Mai Cetonmu ya bayar ta wurin manzanninku. ");
INSERT INTO hausa_vpl VALUES ("P23_3","091_3_3","2PE","3","3","3","Da farko dai, dole ku fahimci wannan cewa a kwanakin ƙarshe masu ba’a za su zo suna ba’a, suna bin mugayen sha’awace-sha’awacensu. ");
INSERT INTO hausa_vpl VALUES ("P23_4","091_3_4","2PE","3","4","4","Za su ce, “Ina wannan ‘dawowar’ da ya yi alkawari ne? Tun mutuwar kakanninmu, kome yana tafiya kamar yadda yake tun farkon halitta.” ");
INSERT INTO hausa_vpl VALUES ("P23_5","091_3_5","2PE","3","5","5","Amma da gangan suke manta cewa tun dā can ta wurin maganar Allah sammai suka kasance aka kuma yi ƙasa daga ruwa ta wurin ruwa kuma. ");
INSERT INTO hausa_vpl VALUES ("P23_6","091_3_6","2PE","3","6","6","Ta wurin waɗannan ruwan ne aka nutsar, aka kuma hallakar da duniya ta wancan lokaci. ");
INSERT INTO hausa_vpl VALUES ("P23_7","091_3_7","2PE","3","7","7","Ta wurin wannan magana ce aka ajiye sammai da ƙasa na yanzu domin wuta, an ajiye su kuma don ranar hukunci da hallaka ta mutane marasa tsoron Allah. ");
INSERT INTO hausa_vpl VALUES ("P23_8","091_3_8","2PE","3","8","8","Amma kada ku manta da wannan abu guda ɗaya, abokaina ƙaunatattu. Ga Ubangiji kwana ɗaya kamar shekaru dubu ne, shekaru dubu kuma kamar kwana ɗaya ne. ");
INSERT INTO hausa_vpl VALUES ("P23_9","091_3_9","2PE","3","9","9","Ubangiji ba mai jinkiri ba ne wajen cika alkawarinsa, yadda waɗansunku suka fahimci jinkiri. Yana haƙuri da ku, ba ya so wani yă hallaka, sai dai kowa yă kai ga tuba. ");
INSERT INTO hausa_vpl VALUES ("P23_10","091_3_10","2PE","3","10","10","Amma ranar Ubangiji za tă zo kamar ɓarawo. Sammai za su ɓace da ruri, abubuwan da suke cikinsu za su ƙone, ƙasa kuma da dukan abin da yake cikinta za su tonu. ");
INSERT INTO hausa_vpl VALUES ("P23_11","091_3_11","2PE","3","11","11","Da yake za a hallaka dukan abubuwa ta haka, waɗanne irin mutane ne ya kamata ku zama? Ya kamata ku yi rayuwar tsarki da ta tsoron Allah, ");
INSERT INTO hausa_vpl VALUES ("P23_12","091_3_12","2PE","3","12","12","yayinda kuke zuba ido ga zuwan ranar Allah kuna gaggauta zuwanta. Wannan rana za tă kawo wa sammai hallaka ta ƙunan wuta, abubuwa kuma za su narke don zafi. ");
INSERT INTO hausa_vpl VALUES ("P23_13","091_3_13","2PE","3","13","13","Amma bisa ga alkawarinsa muna zuba ido ga sabuwar sama da kuma sabuwar ƙasa, inda adalci zai yi zama. ");
INSERT INTO hausa_vpl VALUES ("P23_14","091_3_14","2PE","3","14","14","Saboda haka, abokaina ƙaunatattu, da yake kuna zuba ido ga wannan, sai ku yi matuƙar ƙoƙari don a same ku ba tabo, sai dai zaman salama da shi. ");
INSERT INTO hausa_vpl VALUES ("P23_15","091_3_15","2PE","3","15","15","Ku yi zaman sanin cewa haƙurin Ubangijinmu yana nufin ceto ne, kamar yadda ƙaunataccen ɗan’uwanmu Bulus ma ya rubuta muku da hikimar da Allah ya ba shi. ");
INSERT INTO hausa_vpl VALUES ("P23_16","091_3_16","2PE","3","16","16","Haka yake rubutu cikin dukan wasiƙunsa, yana magana a cikinsu a kan waɗannan al’amura. Wasiƙunsa sun ƙunshi waɗansu abubuwa masu wuyar fahimta, waɗanda jahilai da kuma waɗanda ba tsayayyu ba ne suke murɗe ma’anarsu, kamar yadda suke yi da sauran Nassosi, ta haka suke jawo wa kansu hallaka. ");
INSERT INTO hausa_vpl VALUES ("P23_17","091_3_17","2PE","3","17","17","Saboda haka, abokaina ƙaunatattu, da yake kun riga kun san wannan, sai ku zauna a faɗake don kada a ɗauke hankalinku ta wurin kuskuren marasa bin dokan nan har ku fāɗi daga matsayinku. ");
INSERT INTO hausa_vpl VALUES ("P23_18","091_3_18","2PE","3","18","18","Sai dai ku yi girma cikin alheri da sanin Ubangijinmu da Mai Cetonmu Yesu Kiristi. A gare shi ɗaukaka ta tabbata yanzu da har abada! Amin.");
INSERT INTO hausa_vpl VALUES ("J11_1","092_1_1","1JN","1","1","1","Wannan da ya kasance tun farko, wanda muka ji, wanda muka gani da idanunmu, wanda muka duba, hannuwanmu kuma suka taɓa, wannan ne muke shela game da Kalman rai. ");
INSERT INTO hausa_vpl VALUES ("J11_2","092_1_2","1JN","1","2","2","Wannan Rai ya bayyana, muka kuwa gan shi, muka kuma shaida shi, muna kuwa yin muku shelar wannan rai madawwami, wanda dā yake tare da Uba, ya kuma bayyana a gare mu. ");
INSERT INTO hausa_vpl VALUES ("J11_3","092_1_3","1JN","1","3","3","Muna yin muku shelar abin da muka gani, muka kuma ji ne, domin ku ma ku yi zumunci tare da mu. Zumuncinmu kuwa yana tare da Uba da kuma Ɗansa, Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("J11_4","092_1_4","1JN","1","4","4","Muna rubuta wannan domin farin cikinmu yă zama cikakke. ");
INSERT INTO hausa_vpl VALUES ("J11_5","092_1_5","1JN","1","5","5","Wannan shi ne saƙon da muka ji daga wurinsa, muna kuma sanar da ku cewa Allah haske ne; a cikinsa kuwa babu duhu ko kaɗan. ");
INSERT INTO hausa_vpl VALUES ("J11_6","092_1_6","1JN","1","6","6","In muka ce muna zumunci da shi amma muna tafiya cikin duhu, ƙarya muke yi, kuma ba ma rayuwa bisa ga gaskiya. ");
INSERT INTO hausa_vpl VALUES ("J11_7","092_1_7","1JN","1","7","7","Amma in muna tafiya cikin haske, yadda yake cikin haske, muna da zumunci da juna ke nan, kuma jinin Yesu, Ɗansa, yana tsarkake mu daga dukan zunubi. ");
INSERT INTO hausa_vpl VALUES ("J11_8","092_1_8","1JN","1","8","8","In muka ce ba mu da zunubi, muna ruɗin kanmu ne, gaskiya kuwa ba ta cikinmu. ");
INSERT INTO hausa_vpl VALUES ("J11_9","092_1_9","1JN","1","9","9","In muka furta zunubanmu, shi mai aminci ne, mai adalci kuma, zai gafarta mana zunubanmu, yă kuma tsarkake mu daga dukan rashin adalci. ");
INSERT INTO hausa_vpl VALUES ("J11_10","092_1_10","1JN","1","10","10","In muka ce ba mu yi zunubi ba, mun mai da shi maƙaryaci ke nan, maganarsa kuwa ba ta da wuri a cikinmu. ");
INSERT INTO hausa_vpl VALUES ("J12_1","092_2_1","1JN","2","1","1","’Ya’yana ƙaunatattu, ina rubuta muku wannan ne don kada ku yi zunubi. Amma in wani ya yi zunubi, muna da wani wanda yake magana da Uba don taimakonmu, wato, Yesu Kiristi, Mai Adalci. ");
INSERT INTO hausa_vpl VALUES ("J12_2","092_2_2","1JN","2","2","2","Shi ne hadayar kafara saboda zunubanmu, kuma ba don namu kaɗai ba amma har ma da zunuban duniya duka. ");
INSERT INTO hausa_vpl VALUES ("J12_3","092_2_3","1JN","2","3","3","Ta haka za mu tabbata cewa mun san shi in muna yin biyayya da umarnansa. ");
INSERT INTO hausa_vpl VALUES ("J12_4","092_2_4","1JN","2","4","4","Mutumin da ya ce, “Na san shi,” amma ba ya yin abin da ya umarta, maƙaryaci ne, gaskiya kuwa ba ta cikinsa. ");
INSERT INTO hausa_vpl VALUES ("J12_5","092_2_5","1JN","2","5","5","Amma in wani ya yi biyayya da maganarsa, ƙaunar Allah ta zama cikakkiya ke nan a cikinsa. Ta haka muka san cewa muna cikinsa. ");
INSERT INTO hausa_vpl VALUES ("J12_6","092_2_6","1JN","2","6","6","Duk wanda ya ce yana rayuwa a cikinsa dole yă yi tafiya kamar yadda Yesu ya yi. ");
INSERT INTO hausa_vpl VALUES ("J12_7","092_2_7","1JN","2","7","7","Abokaina ƙaunatattu, ba sabon umarni nake rubuta muku ba, a’a, daɗaɗɗen umarnin nan ne, wanda kuke da shi tun farko. Wannan tsohon umarni shi ne saƙon da kuka riga kuka ji. ");
INSERT INTO hausa_vpl VALUES ("J12_8","092_2_8","1JN","2","8","8","Duk da haka ina rubuta muku sabon umarni; ana ganin gaskiyar umarnin a cikinsa da kuma cikinku, gama duhu yana shuɗewa, haske na gaskiya kuwa yana haskakawa. ");
INSERT INTO hausa_vpl VALUES ("J12_9","092_2_9","1JN","2","9","9","Duk wanda ya ce yana cikin haske yana kuma ƙin ɗan’uwansa, ashe a duhu yake har yanzu. ");
INSERT INTO hausa_vpl VALUES ("J12_10","092_2_10","1JN","2","10","10","Duk wanda yake ƙaunar ɗan’uwansa, a cikin hasken yake rayuwa ke nan, kuma babu wani abin da yake cikinsa da zai sa yă yi tuntuɓe. ");
INSERT INTO hausa_vpl VALUES ("J12_11","092_2_11","1JN","2","11","11","Amma duk wanda yake ƙin ɗan’uwansa, cikin duhu yake, yana kuma tafiya cikin duhu ke nan; bai ma san inda za shi ba, domin duhun ya makanta shi. ");
INSERT INTO hausa_vpl VALUES ("J12_12","092_2_12","1JN","2","12","12","Ina rubuta muku, ’ya’yana ƙaunatattu, domin an gafarta muku zunubanku saboda sunansa. ");
INSERT INTO hausa_vpl VALUES ("J12_13","092_2_13","1JN","2","13","13","Ina rubuta muku, ubanni, domin kun san shi wanda yake tun farko. Ina rubuta muku, samari, domin kun ci nasara a kan mugun nan. ");
INSERT INTO hausa_vpl VALUES ("J12_14","092_2_14","1JN","2","14","14","Ina rubuta muku, ’ya’yana ƙaunatattu, domin kun san Uba. Ina rubuta muku, ubanni, domin kun san shi wanda yake tun farko. Ina rubuta muku, samari, domin kuna da ƙarfi, maganar Allah kuwa tana zaune a cikinku, kun kuma ci nasara a kan mugun nan. ");
INSERT INTO hausa_vpl VALUES ("J12_15","092_2_15","1JN","2","15","15","Kada ku ƙaunaci duniya, ko wani abin da yake cikinta. In wani yana ƙaunar duniya, ƙaunar Uba ba ta cikinsa. ");
INSERT INTO hausa_vpl VALUES ("J12_16","092_2_16","1JN","2","16","16","Gama duk abin da yake na duniya, kamar sha’awace-sha’awacen mutuntaka, sha’awar idanunsa, da kuma taƙama da abin da yake da shi, yake kuma yi, ba daga wurin Uba suke fitowa ba sai dai daga duniya. ");
INSERT INTO hausa_vpl VALUES ("J12_17","092_2_17","1JN","2","17","17","Duniya da sha’awace-sha’awacenta suna shuɗewa, amma mutumin da yake aikata nufin Allah, zai rayu har abada. ");
INSERT INTO hausa_vpl VALUES ("J12_18","092_2_18","1JN","2","18","18","’Ya’yana ƙaunatattu, waɗannan su ne kwanakin ƙarshe; kuma kamar yadda kuka ji cewa magabcin Kiristi yana zuwa, ko yanzu ma abokan gāban Kiristi da yawa sun zo. Ta haka muka san cewa kwanakin ƙarshe sun iso. ");
INSERT INTO hausa_vpl VALUES ("J12_19","092_2_19","1JN","2","19","19","Waɗannan masu gāba da Kiristi suna cikinmu a dā, amma sun bar mu, don tun dā ma su ba namu ba ne. Ai, da su namu ne, da har yanzu suna tare da mu. Amma sun bar mu, wannan ya nuna a fili cewa su ba namu ba ne. ");
INSERT INTO hausa_vpl VALUES ("J12_20","092_2_20","1JN","2","20","20","Amma ku kam, kuna da shafewa daga wurin Mai Tsarkin nan, kuma dukanku kun san gaskiya. ");
INSERT INTO hausa_vpl VALUES ("J12_21","092_2_21","1JN","2","21","21","Ina rubuta muku ba domin ba ku san gaskiya ba ne, a’a, sai dai domin kun santa, kun kuma san cewa babu yadda ƙarya za tă fito daga gaskiya. ");
INSERT INTO hausa_vpl VALUES ("J12_22","092_2_22","1JN","2","22","22","Wane ne maƙaryaci? Ai, shi ne mutumin da yake mūsun cewa Yesu shi ne Kiristi. Irin wannan mutum shi ne magabcin Kiristi, ya yi mūsun Uban da kuma Ɗan. ");
INSERT INTO hausa_vpl VALUES ("J12_23","092_2_23","1JN","2","23","23","Ba wanda yake mūsun Ɗan, sa’an nan yă ce yana da Uban; duk wanda ya yarda da Ɗan, yana da Uban a cikinsa ke nan. ");
INSERT INTO hausa_vpl VALUES ("J12_24","092_2_24","1JN","2","24","24","Ku lura fa cewa abin da kuka ji daga farko, bari yă ci gaba da kasance a cikinku. In kuwa ya ci gaba da zama a cikinku, za ku kasance a cikin Ɗan, da kuma a cikin Uban. ");
INSERT INTO hausa_vpl VALUES ("J12_25","092_2_25","1JN","2","25","25","Wannan shi ne abin da ya yi mana alkawari, wato, rai madawwami. ");
INSERT INTO hausa_vpl VALUES ("J12_26","092_2_26","1JN","2","26","26","Ina rubuta muku waɗannan abubuwa ne game da waɗanda suke ƙoƙari su sa ku kauce. ");
INSERT INTO hausa_vpl VALUES ("J12_27","092_2_27","1JN","2","27","27","Game da ku kuwa, shafan nan da kuka karɓa daga gare shi tana nan a cikinku, ba kwa kuma bukata wani yă koyar da ku. Amma kamar yadda shafan nan tasa tana koya muku kome, ita kuwa gaskiya ce ba ƙarya ba, yadda dai ta koya muku, to, sai ku zauna a cikinsa. ");
INSERT INTO hausa_vpl VALUES ("J12_28","092_2_28","1JN","2","28","28","Yanzu fa, ya ku ’ya’yana ƙaunatattu, sai ku ci gaba a cikinsa, domin sa’ad da ya bayyana, mu iya tsaya gabagadi babu kunya a dawowarsa. ");
INSERT INTO hausa_vpl VALUES ("J12_29","092_2_29","1JN","2","29","29","In kun san cewa shi mai adalci ne, to, kun dai san cewa duk mai aikata abin da yake daidai haifaffensa ne. ");
INSERT INTO hausa_vpl VALUES ("J13_1","092_3_1","1JN","3","1","1","Dubi irin ƙaunar da Uba ya ƙaunace mu da ita mana, har ana ce da mu ’ya’yan Allah! Haka kuwa muke! Dalilin da ya sa duniya ba tă san mu ba shi ne, don ba tă san shi ba. ");
INSERT INTO hausa_vpl VALUES ("J13_2","092_3_2","1JN","3","2","2","Abokaina ƙaunatattu, yanzu, mu ’ya’yan Allah ne, kuma abin da za mu zama nan gaba ba a riga an bayyana ba. Sai dai mun san cewa sa’ad da Kiristi ya bayyana, za mu zama kamar sa, domin za mu gan shi kamar yadda yake. ");
INSERT INTO hausa_vpl VALUES ("J13_3","092_3_3","1JN","3","3","3","Duk mai wannan bege a cikinsa yakan tsarkake kansa, kamar yadda shi Kiristi yake da tsabta. ");
INSERT INTO hausa_vpl VALUES ("J13_4","092_3_4","1JN","3","4","4","Duk mai yin zunubi yana karya doka ne; tabbatacce, zunubi, karya doka ne. ");
INSERT INTO hausa_vpl VALUES ("J13_5","092_3_5","1JN","3","5","5","Sai dai kun san cewa Kiristi ya bayyana ne domin yă ɗauke zunubanmu. A cikinsa kuwa babu zunubi. ");
INSERT INTO hausa_vpl VALUES ("J13_6","092_3_6","1JN","3","6","6","Ba mai rayuwa a cikinsa da yake cin gaba da yin zunubi. Kowa da yake aikata zunubi, bai taɓa ganinsa ba, bai ma san shi ba. ");
INSERT INTO hausa_vpl VALUES ("J13_7","092_3_7","1JN","3","7","7","’Ya’yana ƙaunatattu, kada ku yarda wani yă ruɗe ku. Duk mai yin abin da yake daidai mai adalci ne, yadda Kiristi yake mai adalci. ");
INSERT INTO hausa_vpl VALUES ("J13_8","092_3_8","1JN","3","8","8","Duk mai aikata abin da yake zunubi shi na Iblis ne, domin Iblis mai aikata zunubi ne tun farko. Dalilin da ya sa Ɗan Allah ya bayyana kuwa shi ne don yă rushe aikin Iblis. ");
INSERT INTO hausa_vpl VALUES ("J13_9","092_3_9","1JN","3","9","9","Babu haifaffe na Allah da zai ci gaba da yin zunubi, domin iri na Allah yana a cikinsa; ba zai iya ci gaba da yin zunubi ba, domin haifaffe ne na Allah. ");
INSERT INTO hausa_vpl VALUES ("J13_10","092_3_10","1JN","3","10","10","Ta haka muka san waɗanda suke ’ya’yan Allah da kuma waɗanda suke ’ya’yan Iblis. Duk wanda ba ya yin abin da yake daidai, ba ɗan Allah ba ne; haka ma wanda ba ya ƙaunar ɗan’uwansa. ");
INSERT INTO hausa_vpl VALUES ("J13_11","092_3_11","1JN","3","11","11","Wannan shi ne saƙon da kuka ji tun farko. Ya kamata mu ƙaunaci juna. ");
INSERT INTO hausa_vpl VALUES ("J13_12","092_3_12","1JN","3","12","12","Kada ku zama kamar Kayinu, wanda ya zama na mugun nan, ya kuma kashe ɗan’uwansa. Me ya sa ya kashe shi? Domin ayyukansa mugaye ne, na ɗan’uwansa kuma na adalci ne. ");
INSERT INTO hausa_vpl VALUES ("J13_13","092_3_13","1JN","3","13","13","Kada ku yi mamaki ’yan’uwana, in duniya ta ƙi ku. ");
INSERT INTO hausa_vpl VALUES ("J13_14","092_3_14","1JN","3","14","14","Mun san cewa mun riga mun ratsa daga mutuwa zuwa rai, domin muna ƙaunar ’yan’uwanmu. Duk wanda ba ya ƙauna matacce ne har yanzu. ");
INSERT INTO hausa_vpl VALUES ("J13_15","092_3_15","1JN","3","15","15","Duk mai ƙin ɗan’uwansa mai kisankai ne, kun kuma san cewa ba mai kisankan da yake da rai madawwami a cikinsa. ");
INSERT INTO hausa_vpl VALUES ("J13_16","092_3_16","1JN","3","16","16","Yadda muka san ƙauna ke nan, wato, Yesu Kiristi ya ba da ransa dominmu. Ya kamata mu ma mu ba da rayukanmu domin ’yan’uwanmu. ");
INSERT INTO hausa_vpl VALUES ("J13_17","092_3_17","1JN","3","17","17","In wani yana da arziki, ya kuma ga ɗan’uwansa cikin rashi, bai kuwa taimake shi ba, anya, ƙaunar Allah tana a cikinsa kuwa? ");
INSERT INTO hausa_vpl VALUES ("J13_18","092_3_18","1JN","3","18","18","’Ya’yana ƙaunatattu, kada mu yi ƙauna da fatar baki kawai, sai dai mu nuna ta ta wurin aikatawa da kuma gaskiya. ");
INSERT INTO hausa_vpl VALUES ("J13_19","092_3_19","1JN","3","19","19","Ta haka muka san cewa mu na gaskiya ne, kuma za mu iya tsaya a gaban Allah ba tare da rawar jiki ba. ");
INSERT INTO hausa_vpl VALUES ("J13_20","092_3_20","1JN","3","20","20","Idan zuciyarmu ta nuna mana muna da laifi, mun san cewa Allah ya fi zuciyarmu, ya kuma san dukan kome. ");
INSERT INTO hausa_vpl VALUES ("J13_21","092_3_21","1JN","3","21","21","Abokaina ƙaunatattu, in zukatanmu ba su ba mu laifi ba, muna da ƙarfin halin tsayawa a gaban Allah ke nan. ");
INSERT INTO hausa_vpl VALUES ("J13_22","092_3_22","1JN","3","22","22","Muna kuma samun dukan abin da muka roƙa daga gare shi, domin muna biyayya da umarnansa, muna kuma yin abin da ya gamshe shi. ");
INSERT INTO hausa_vpl VALUES ("J13_23","092_3_23","1JN","3","23","23","Umarninsa kuwa shi ne, mu gaskata da sunan Ɗansa, Yesu Kiristi, mu kuma ƙaunaci juna kamar yadda ya umarce mu. ");
INSERT INTO hausa_vpl VALUES ("J13_24","092_3_24","1JN","3","24","24","Waɗanda suke biyayya da umarnansa kuwa suna rayuwa a cikinsa, shi kuma a cikinsu. Ta haka muka san cewa yana raye a cikinmu. Mun san haka ta wurin Ruhun da ya ba mu. ");
INSERT INTO hausa_vpl VALUES ("J14_1","092_4_1","1JN","4","1","1","Abokaina ƙaunatattu, ba kowane ruhu za ku gaskata ba, sai dai ku gwada ruhohi don ku ga ko daga Allah ne, domin annabawan ƙarya da yawa sun fito duniya. ");
INSERT INTO hausa_vpl VALUES ("J14_2","092_4_2","1JN","4","2","2","Ga yadda za ku gane Ruhun Allah, duk ruhun da ya yarda cewa Yesu Kiristi ya zo cikin jiki, to, daga Allah yake. ");
INSERT INTO hausa_vpl VALUES ("J14_3","092_4_3","1JN","4","3","3","Amma duk ruhun da bai yarda da Yesu ba, ba daga Allah ba ne, ruhun magabcin Kiristi ne, wanda kuka ji yana zuwa, har ma ya riga ya shigo duniya. ");
INSERT INTO hausa_vpl VALUES ("J14_4","092_4_4","1JN","4","4","4","Ku, ’ya’yana ƙaunatattu, ku daga Allah ne, kun kuma yi nasara a kan magabtan Kiristi, domin wanda yake a cikinku ya fi wanda yake a duniya girma. ");
INSERT INTO hausa_vpl VALUES ("J14_5","092_4_5","1JN","4","5","5","Su daga duniya ne saboda haka suke magana yadda duniya take ganin abubuwa, duniya kuwa tana sauraronsu. ");
INSERT INTO hausa_vpl VALUES ("J14_6","092_4_6","1JN","4","6","6","Mu daga Allah ne, kuma duk wanda ya san Allah yakan saurare mu. Amma duk wanda ba daga Allah ba, ba ya sauraronmu. Ta haka ne muke gane Ruhun gaskiya, da kuma ruhun ƙarya. ");
INSERT INTO hausa_vpl VALUES ("J14_7","092_4_7","1JN","4","7","7","Abokaina ƙaunatattu, mu ƙaunaci juna, domin ƙauna tana zuwa daga Allah ne. Duk mai ƙauna, haifaffe ne na Allah, ya kuma san Allah. ");
INSERT INTO hausa_vpl VALUES ("J14_8","092_4_8","1JN","4","8","8","Duk wanda ba ya ƙauna, bai san Allah ba, domin Allah ƙauna ne. ");
INSERT INTO hausa_vpl VALUES ("J14_9","092_4_9","1JN","4","9","9","Ga yadda Allah ya nuna ƙaunarsa a cikinmu, Allah ya aiki makaɗaici Ɗansa zuwa duniya domin mu rayu ta wurinsa. ");
INSERT INTO hausa_vpl VALUES ("J14_10","092_4_10","1JN","4","10","10","Wannan ita ce ƙauna, wato, ba mu ne muka ƙaunaci Allah ba, sai dai shi ne ya ƙaunace mu, ya kuma aiko Ɗansa yă zama hadaya ta kafara saboda zunubanmu. ");
INSERT INTO hausa_vpl VALUES ("J14_11","092_4_11","1JN","4","11","11","Abokaina ƙaunatattu, da yake Allah ya ƙaunace mu haka, ya kamata mu ma mu ƙaunaci juna. ");
INSERT INTO hausa_vpl VALUES ("J14_12","092_4_12","1JN","4","12","12","Ba wanda ya taɓa ganin Allah; amma in muna ƙaunar juna, Allah yana raye a cikinmu, ƙaunarsa kuwa ta zama cikakkiya a cikinmu ke nan. ");
INSERT INTO hausa_vpl VALUES ("J14_13","092_4_13","1JN","4","13","13","Mun san cewa muna rayuwa a cikinsa shi kuma a cikinmu, domin ya ba mu Ruhunsa. ");
INSERT INTO hausa_vpl VALUES ("J14_14","092_4_14","1JN","4","14","14","Mun gani, mun kuma shaida cewa Uba ya aiko Ɗansa domin yă zama Mai Ceton duniya. ");
INSERT INTO hausa_vpl VALUES ("J14_15","092_4_15","1JN","4","15","15","Duk wanda ya yarda cewa Yesu Ɗan Allah ne, Allah yana raye a cikinsa, shi kuma a cikin Allah. ");
INSERT INTO hausa_vpl VALUES ("J14_16","092_4_16","1JN","4","16","16","Ta haka muka sani, muke kuma dogara ga ƙaunar da Allah yake mana. Allah ƙauna ne. Duk wanda yake rayuwa cikin ƙauna, yana rayuwa a cikin Allah ne, Allah kuma a cikinsa. ");
INSERT INTO hausa_vpl VALUES ("J14_17","092_4_17","1JN","4","17","17","Ta haka, ƙauna ta zama cikakkiya a cikinmu domin mu kasance masu ƙarfin hali a ranar shari’a, domin a wannan duniya muna kama da shi. ");
INSERT INTO hausa_vpl VALUES ("J14_18","092_4_18","1JN","4","18","18","Babu tsoro cikin ƙauna. Cikakkiyar ƙauna dai takan kawar da tsoro, domin hukunci ne yake kawo tsoro. Mai jin tsoro ba cikakke ba ne a cikin ƙauna. ");
INSERT INTO hausa_vpl VALUES ("J14_19","092_4_19","1JN","4","19","19","Muna ƙauna, domin ya ƙaunace mu da farko. ");
INSERT INTO hausa_vpl VALUES ("J14_20","092_4_20","1JN","4","20","20","Duk wanda ya ce, “Ina ƙaunar Allah,” amma yana ƙin ɗan’uwansa, maƙaryaci ne. Gama duk wanda ba ya ƙaunar ɗan’uwansa da yake gani, ba zai iya ƙaunar Allah wanda ba ya gani ba. ");
INSERT INTO hausa_vpl VALUES ("J14_21","092_4_21","1JN","4","21","21","Ya kuma ba mu wannan umarni cewa duk wanda yake ƙaunar Allah, dole yă ƙaunaci ɗan’uwansa. ");
INSERT INTO hausa_vpl VALUES ("J15_1","092_5_1","1JN","5","1","1","Kowa ya gaskata cewa Yesu shi ne Kiristi, shi haifaffe na Allah ne, kuma duk mai ƙaunar mahaifi kuwa, yakan ƙaunaci ɗansa ma. ");
INSERT INTO hausa_vpl VALUES ("J15_2","092_5_2","1JN","5","2","2","Ga yadda muka san cewa muna ƙaunar ’ya’yan Allah. Muna yin haka ta wurin ƙaunar Allah da kuma aikata umarnansa. ");
INSERT INTO hausa_vpl VALUES ("J15_3","092_5_3","1JN","5","3","3","Ƙaunar Allah ita ce, a yi biyayya da umarnansa. Umarnansa kuwa ba masu nauyi ba ne; ");
INSERT INTO hausa_vpl VALUES ("J15_4","092_5_4","1JN","5","4","4","domin duk haifaffe na Allah yana cin nasara a kan duniya. Bangaskiyarmu kuwa ita ce ta ba mu wannan nasara a kan duniya. ");
INSERT INTO hausa_vpl VALUES ("J15_5","092_5_5","1JN","5","5","5","Wa ya cin nasara a kan duniya? Sai wanda ya gaskata cewa Yesu Ɗan Allah ne. ");
INSERT INTO hausa_vpl VALUES ("J15_6","092_5_6","1JN","5","6","6","Ga wanda ya zo ta wurin ruwa da jini, wato, Yesu Kiristi. Bai zo ta wurin ruwa kaɗai ba, sai dai ta wurin ruwa da kuma jini. Ruhu ne kuwa yake ba da shaida, gama Ruhu shi ne gaskiya. ");
INSERT INTO hausa_vpl VALUES ("J15_7","092_5_7","1JN","5","7","7","Akwai shaidu uku, wato, ");
INSERT INTO hausa_vpl VALUES ("J15_8","092_5_8","1JN","5","8","8","Ruhu, da ruwa, da kuma jini; waɗannan uku kuwa manufarsu ɗaya ce. ");
INSERT INTO hausa_vpl VALUES ("J15_9","092_5_9","1JN","5","9","9","Tun da yake mukan yarda da shaida mutane, ai, shaidar Allah ta fi ƙarfi. Wannan ita ce shaidar Allah, wato, ya shaidi Ɗansa. ");
INSERT INTO hausa_vpl VALUES ("J15_10","092_5_10","1JN","5","10","10","Duk wanda ya gaskata da Ɗan Allah, yana da shaidan nan a zuciyarsa. Duk wanda bai gaskata da Allah ba kuwa ya mai da shi maƙaryaci, domin bai gaskata shaidar da Allah ya bayar game da Ɗansa ba. ");
INSERT INTO hausa_vpl VALUES ("J15_11","092_5_11","1JN","5","11","11","Wannan kuwa ita ce shaidar; cewa Allah ya ba mu rai madawwami, wannan rai kuwa yana cikin Ɗansa. ");
INSERT INTO hausa_vpl VALUES ("J15_12","092_5_12","1JN","5","12","12","Duk wanda yake da Ɗan, yana da rai; wanda kuwa ba shi da Ɗan Allah, ba shi da rai. ");
INSERT INTO hausa_vpl VALUES ("J15_13","092_5_13","1JN","5","13","13","Ina rubuta waɗannan abubuwa gare ku, ku da kuka gaskata sunan Ɗan Allah domin ku san kuna da rai madawwami. ");
INSERT INTO hausa_vpl VALUES ("J15_14","092_5_14","1JN","5","14","14","Wannan shi ne ƙarfin halin da muke da shi sa’ad da muke zuwa a gaban Allah, gama mun san cewa kome muka roƙa bisa ga nufinsa, yakan saurare mu. ");
INSERT INTO hausa_vpl VALUES ("J15_15","092_5_15","1JN","5","15","15","In kuwa muka san cewa yana sauraranmu, ko mene ne muka roƙa, mun sani, mun riga mun sami abin da muka roƙa daga gare shi ke nan. ");
INSERT INTO hausa_vpl VALUES ("J15_16","092_5_16","1JN","5","16","16","Kowa ya ga ɗan’uwansa yana yin zunubin da bai kai ga mutuwa ba, sai yă yi masa addu’a. Ta dalilin mai addu’an nan kuwa, Allah zai ba da rai ga mai yin zunubin da bai kai ga mutuwa ba. Akwai zunubin da yakan kai ga mutuwa. Ban ce a yi addu’a domin wannan ba. ");
INSERT INTO hausa_vpl VALUES ("J15_17","092_5_17","1JN","5","17","17","Duk rashin adalci, zunubi ne, amma akwai waɗansu zunuban da ba sa kai ga mutuwa. ");
INSERT INTO hausa_vpl VALUES ("J15_18","092_5_18","1JN","5","18","18","Mun san cewa kowane haifaffe na Allah ba ya cin gaba da yin zunubi; kasancewarsa haifaffe na Allah ita takan kāre shi, mugun kuwa ba zai iya cuce shi ba. ");
INSERT INTO hausa_vpl VALUES ("J15_19","092_5_19","1JN","5","19","19","Mun san cewa mu ’ya’yan Allah ne, duniya duka kuwa tana hannun Mugun. ");
INSERT INTO hausa_vpl VALUES ("J15_20","092_5_20","1JN","5","20","20","Mun san cewa Ɗan Allah ya zo duniya, ya kuma ba mu ganewa domin mu san shi wanda yake na gaskiya. Mu kuwa muna cikinsa, shi da yake Allah na gaskiya wato, cikin Ɗansa Yesu Kiristi. Shi ne Allah na gaskiya da kuma rai na har abada. ");
INSERT INTO hausa_vpl VALUES ("J15_21","092_5_21","1JN","5","21","21","’Ya’yana ƙaunatattu, ku yi nesa da gumaka.");
INSERT INTO hausa_vpl VALUES ("J21_1","093_1_1","2JN","1","1","1","Dattijon nan, Zuwa ga uwargida zaɓaɓɓiya da kuma ’ya’yanta, waɗanda nake ƙauna ƙwarai da gaske kuma ba ni kaɗai ba, amma har da dukan waɗanda suka san gaskiya. ");
INSERT INTO hausa_vpl VALUES ("J21_2","093_1_2","2JN","1","2","2","Muna ƙaunarku saboda gaskiyan nan, wadda take cikinmu za tă kuma kasance tare da mu har abada. ");
INSERT INTO hausa_vpl VALUES ("J21_3","093_1_3","2JN","1","3","3","Alheri, jinƙai da kuma salama daga Allah Uba da kuma Yesu Kiristi, Ɗan Uba, su kasance tare da mu cikin gaskiya da ƙauna. ");
INSERT INTO hausa_vpl VALUES ("J21_4","093_1_4","2JN","1","4","4","Na yi farin ciki ƙwarai, da na sami waɗansu ’ya’yanki suna tafiya cikin gaskiya, kamar yadda Uba ya umarce mu. ");
INSERT INTO hausa_vpl VALUES ("J21_5","093_1_5","2JN","1","5","5","Yanzu kuma, uwargida ƙaunatacciya, ba sabon umarni nake rubuta miki ba sai dai wanda muke da shi tun farko. Ina roƙo cewa mu ƙaunaci juna. ");
INSERT INTO hausa_vpl VALUES ("J21_6","093_1_6","2JN","1","6","6","Ƙauna, ita ce mu yi biyayya ga umarnansa. Kamar yadda kuka ji tun da fari, umarninsa shi ne ku yi zaman ƙauna. ");
INSERT INTO hausa_vpl VALUES ("J21_7","093_1_7","2JN","1","7","7","Masu ruɗi da yawa, waɗanda ba su yarda da zuwan Yesu Kiristi cikin jiki ba, sun riga sun fito a duniya. Duk irin mutumin nan mai ruɗi ne kuma magabcin Kiristi. ");
INSERT INTO hausa_vpl VALUES ("J21_8","093_1_8","2JN","1","8","8","Ku lura don kada ku yi hasarar aikin da kuka yi, sai dai ku sami cikakken lada. ");
INSERT INTO hausa_vpl VALUES ("J21_9","093_1_9","2JN","1","9","9","Duk mutumin da bai tsaya a kan koyarwar Kiristi ba, amma ya yi ƙari a kanta, mutumin nan ba shi da Allah. Amma wanda ya tsaya a kan koyarwar Kiristi, yana da Uban da kuma Ɗan. ");
INSERT INTO hausa_vpl VALUES ("J21_10","093_1_10","2JN","1","10","10","Duk wanda ya zo wurinku bai kuma kawo koyarwan nan ba, kada ku karɓe shi a gidanku ko ku marabce shi. ");
INSERT INTO hausa_vpl VALUES ("J21_11","093_1_11","2JN","1","11","11","Duk wanda ya karɓe shi yana tarayya da mugun aikinsa ke nan. ");
INSERT INTO hausa_vpl VALUES ("J21_12","093_1_12","2JN","1","12","12","Ina da abubuwa da dama da zan rubuta muku, sai dai ba na so in yi amfani da takarda da inki in rubuta. A maimako, ina fata in ziyarce ku in kuma yi magana da ku fuska da fuska, domin farin cikinmu yă zama cikakke. ");
INSERT INTO hausa_vpl VALUES ("J21_13","093_1_13","2JN","1","13","13","’Ya’yan ’yar’uwarki wadda Allah ya keɓe, suna gaishe ku.");
INSERT INTO hausa_vpl VALUES ("J31_1","094_1_1","3JN","1","1","1","Dattijon nan, Zuwa ga ƙaunataccen abokina Gayus, wanda nake ƙauna ƙwarai da gaske. ");
INSERT INTO hausa_vpl VALUES ("J31_2","094_1_2","3JN","1","2","2","Abokina ƙaunatacce, ina addu’a ka sami zaman lafiya don kome yă yi maka daidai, kamar yadda ruhunka yake zaune lafiya. ");
INSERT INTO hausa_vpl VALUES ("J31_3","094_1_3","3JN","1","3","3","Na yi farin ciki ƙwarai sa’ad da waɗansu ’yan’uwa suka zo suka yi zance game da yadda kake da aminci ga gaskiyan nan da kuma yadda kake cin gaba cikin gaskiyan nan. ");
INSERT INTO hausa_vpl VALUES ("J31_4","094_1_4","3JN","1","4","4","Ba abin da ya fi sa ni farin ciki fiye da in ji cewa ’ya’yana suna cikin gaskiyan nan. ");
INSERT INTO hausa_vpl VALUES ("J31_5","094_1_5","3JN","1","5","5","Abokina ƙaunatacce, kana da aminci cikin abin da kake yi wa ’yan’uwa, ko da yake su baƙi ne a gare ka. ");
INSERT INTO hausa_vpl VALUES ("J31_6","094_1_6","3JN","1","6","6","Sun faɗa wa ikkilisiya game da ƙaunarka. Za ka kyauta in ka sallame su a hanyar da ta cancanci Allah. ");
INSERT INTO hausa_vpl VALUES ("J31_7","094_1_7","3JN","1","7","7","Saboda Sunan nan ne suka fito, ba sa karɓan wani taimako daga waɗanda ba masu bi ba. ");
INSERT INTO hausa_vpl VALUES ("J31_8","094_1_8","3JN","1","8","8","Saboda haka ya kamata mu nuna halin karɓan baƙi ga irin mutanen nan domin mu yi aiki tare saboda gaskiyan nan. ");
INSERT INTO hausa_vpl VALUES ("J31_9","094_1_9","3JN","1","9","9","Na rubuta wa ikkilisiya, amma Diyotirefes, wanda yake son zama na farko, ya ƙi yă yi hulɗa da mu. ");
INSERT INTO hausa_vpl VALUES ("J31_10","094_1_10","3JN","1","10","10","Saboda haka in na zo, zan tone abin da yake yi, yana surutu game da mu, yana ɓaɓɓata mu. Wannan ma bai ishe shi ba, har yana ƙin marabtar ’yan’uwa. Yana hana waɗanda suke so yin haka, yana ma korinsu daga ikkilisiya. ");
INSERT INTO hausa_vpl VALUES ("J31_11","094_1_11","3JN","1","11","11","Abokina ƙaunatacce, kada ka yi koyi da abin da yake mugu sai dai abin da yake nagari. Duk mai yin abin da yake nagari daga Allah yake. Duk mai yin abin da yake mugu bai taɓa sanin Allah ba. ");
INSERT INTO hausa_vpl VALUES ("J31_12","094_1_12","3JN","1","12","12","Demetiriyus yana da shaida mai kyau daga wurin kowa, har gaskiya kanta ma ta shaide shi. Mu ma muna ba da shaida mai kyau a kansa, ka kuma san cewa shaidarmu gaskiya ce. ");
INSERT INTO hausa_vpl VALUES ("J31_13","094_1_13","3JN","1","13","13","Ina da abubuwa da dama da zan rubuta maka, sai dai ba na so in yi amfani da alƙalami da inki in rubuta su. ");
INSERT INTO hausa_vpl VALUES ("J31_14","094_1_14","3JN","1","14","14","Ina fata in gan ka nan ba da daɗewa ba, za mu kuwa yi magana fuska da fuska. ");
INSERT INTO hausa_vpl VALUES ("J31_15","094_1_15","3JN","1","15","15","Salama gare ka. Abokai a nan suna gaishe ka. Ka gai da abokai a can da sunansu.");
INSERT INTO hausa_vpl VALUES ("JD1_1","095_1_1","JUD","1","1","1","Yahuda, bawan Yesu Kiristi, ɗan’uwan Yaƙub, Zuwa ga waɗanda aka kira, waɗanda Allah Uba yake ƙauna, waɗanda kuma Yesu Kiristi ya kiyaye. ");
INSERT INTO hausa_vpl VALUES ("JD1_2","095_1_2","JUD","1","2","2","Jinƙai, salama da kuma ƙauna, su kasance tare da ku a yalwace. ");
INSERT INTO hausa_vpl VALUES ("JD1_3","095_1_3","JUD","1","3","3","Abokaina ƙaunatattu, ko da yake na yi marmari ƙwarai in rubuta muku game da ceton nan namu, sai na ga ya dace in rubuta, in gargaɗe ku ku tsaya da ƙarfi cikin bangaskiya wadda aka danƙa wa mutane masu tsarki na Allah sau ɗaya tak. ");
INSERT INTO hausa_vpl VALUES ("JD1_4","095_1_4","JUD","1","4","4","Na faɗa haka ne domin waɗansu mutanen da aka rubuta hukuncinsu tun dā sun shiga cikinku a ɓoye. Su fa marasa tsoron Allah ne. Su ne waɗanda suka mai da alherin Allahnmu ya zama dalilin yin fasikanci, suna kuma mūsun Yesu Kiristi wanda shi ne Makaɗaici Mai Iko Duka da kuma Ubangijinmu. ");
INSERT INTO hausa_vpl VALUES ("JD1_5","095_1_5","JUD","1","5","5","Ko da yake kun riga kun san duk wannan, ina so in tuna muku cewa Ubangiji ya ceci mutanensa daga Masar, duk da haka daga baya ya hallaka waɗanda ba su ba da gaskiya ba. ");
INSERT INTO hausa_vpl VALUES ("JD1_6","095_1_6","JUD","1","6","6","Haka ma mala’ikun da ba su riƙe matsayinsu na iko ba, waɗanda suka bar ainihin mazauninsu, su ne ya tsare a duhu daure da dawwammamun sarƙoƙi don hukunci ta babbar Ranan nan. ");
INSERT INTO hausa_vpl VALUES ("JD1_7","095_1_7","JUD","1","7","7","Haka ma Sodom da Gomorra da garuruwan da suke kewaye da su, waɗanda su ma suka ba da kansu ga fasikanci da muguwar sha’awar jiki, sun zama misalin waɗanda suke shan hukuncin madawwamiyar wuta. ");
INSERT INTO hausa_vpl VALUES ("JD1_8","095_1_8","JUD","1","8","8","Haka yake da masu mafarke-mafarken nan, gama sun ƙazantar da jikunansu, suka ƙi bin masu mulki, suna ɓata sunan talikan sararin sama. ");
INSERT INTO hausa_vpl VALUES ("JD1_9","095_1_9","JUD","1","9","9","Kai, ko Mika’ilu babban shugaban mala’iku ma, sa’ad da yake mūsu da Iblis game da gawar Musa, bai yi garajen ɗora masa laifi da baƙar magana ba, sai dai ya ce, “Ubangiji yă tsawata maka!” ");
INSERT INTO hausa_vpl VALUES ("JD1_10","095_1_10","JUD","1","10","10","Duk da haka mutanen nan suna maganar banza a kan kome da ba su gane ba; kuma abubuwan da suka fahimta bisa ga jiki, kamar dabbobi marasa hankali, waɗannan abubuwa ne suke hallaka su. ");
INSERT INTO hausa_vpl VALUES ("JD1_11","095_1_11","JUD","1","11","11","Kaitonsu! Gama sun kama hanyar Kayinu; sun ruga a guje garin neman riba cikin kuskure kamar Bala’am; aka kuma hallaka su cikin tawayen Kora. ");
INSERT INTO hausa_vpl VALUES ("JD1_12","095_1_12","JUD","1","12","12","Waɗannan mutane sun zama kamar ƙazanta a taronku na soyayya, suna ta ciye-ciye a cikinku, ba kunya ba tsoro. Su masu kiwo ne da suke ciyar da kansu kawai. Su kamar hadari ne da babu ruwa da iska take kori. Su kamar itatuwa ne, marasa ’ya’ya da rani, waɗanda aka tumɓuke, ko kamar itatuwan da aka tumɓuke suka kuma mutu ƙurmus. ");
INSERT INTO hausa_vpl VALUES ("JD1_13","095_1_13","JUD","1","13","13","Su kamar raƙuman ruwan teku ne masu hauka, suna taƙama da tumbatsan kumfar kunyarsu. Su kamar taurari ne masu yawo barkatai, waɗanda aka ajiye mugun duhu saboda su har abada. ");
INSERT INTO hausa_vpl VALUES ("JD1_14","095_1_14","JUD","1","14","14","Enok ma, wanda yake na bakwai daga Adamu, ya yi annabci game da waɗannan mutane cewa, “Duba, Ubangiji yana zuwa da dubu dubban tsarkakansa ");
INSERT INTO hausa_vpl VALUES ("JD1_15","095_1_15","JUD","1","15","15","don yă yi wa kowa shari’a, yă kuma hukunta duk marasa tsoron Allah game da dukan ayyukansu na rashin tsoron Allah da suka aikata ta hanyar rashin tsoron Allah, da kuma dukan baƙaƙen kalmomin da masu zunubi marasa tsoron Allah suka faɗa game da shi.” ");
INSERT INTO hausa_vpl VALUES ("JD1_16","095_1_16","JUD","1","16","16","Waɗannan mutane dai, gunaguni gare su, kullum ganin laifin waɗansu suke yi. Muguwar sha’awa ce kaɗai tunaninsu. Sun cika da banzar magana ta yabon kansu. Suna ruɗin mutane da zaƙin baki don samun ribar kansu. ");
INSERT INTO hausa_vpl VALUES ("JD1_17","095_1_17","JUD","1","17","17","Amma ku abokaina ƙaunatattu, ku tuna da abin da manzannin Ubangijinmu Yesu Kiristi suka faɗa a dā. ");
INSERT INTO hausa_vpl VALUES ("JD1_18","095_1_18","JUD","1","18","18","Sun ce muku, “A kwanakin ƙarshe za a kasance da masu ba’a waɗanda za su bi sha’awace-sha’awacensu na rashin tsoron Allah.” ");
INSERT INTO hausa_vpl VALUES ("JD1_19","095_1_19","JUD","1","19","19","Waɗannan mutanen ne, suke kawo rabe-rabe, masu bin abin da jiki yake so, marasa Ruhu. ");
INSERT INTO hausa_vpl VALUES ("JD1_20","095_1_20","JUD","1","20","20","Amma ku, abokaina ƙaunatattu, ku gina kanku cikin bangaskiyarku mafi tsarki, ku kuma yi addu’a cikin Ruhu Mai Tsarki. ");
INSERT INTO hausa_vpl VALUES ("JD1_21","095_1_21","JUD","1","21","21","Ku zauna cikin ƙaunar Allah yayinda kuke jira jinƙan Ubangijinmu Yesu Kiristi don yă kawo ku ga rai madawwami. ");
INSERT INTO hausa_vpl VALUES ("JD1_22","095_1_22","JUD","1","22","22","Ku ji tausayin waɗanda suke shakka; ");
INSERT INTO hausa_vpl VALUES ("JD1_23","095_1_23","JUD","1","23","23","ku cece waɗansu ta wurin fizge su daga wuta. Ga waɗansu kuma ku ji tausayinsu, amma tare da tsoro, har ma ku yi ƙyamar tufafin da suka ɓata da ayyukansu na jiki. ");
INSERT INTO hausa_vpl VALUES ("JD1_24","095_1_24","JUD","1","24","24","To, yabo yă tabbata a gare shi, shi wanda yake da iko yă tsare ku daga fāɗuwa, yă kuma miƙa ku marasa laifi a gaban ɗaukakarsa da matuƙar farin ciki. ");
INSERT INTO hausa_vpl VALUES ("JD1_25","095_1_25","JUD","1","25","25","Gare shi kuma, shi da yake kaɗai Allah Mai Cetonmu, ta wurin Yesu Kiristi Ubangijinmu, bari ɗaukaka, daraja, iko da mulki, su tabbata a gare shi, tun farkon zamanai, yanzu, da har abada abadin! Amin.");
INSERT INTO hausa_vpl VALUES ("RV1_1","096_1_1","REV","1","1","1","Wahayin Yesu Kiristi, wanda Allah ya ba shi yă nuna wa bayinsa abin da lalle zai faru nan ba da daɗewa ba. Ya bayyana shi ta wurin aiko da mala’ikansa zuwa ga bawansa Yohanna, ");
INSERT INTO hausa_vpl VALUES ("RV1_2","096_1_2","REV","1","2","2","wanda ya shaida dukan abin da ya gani, wato, maganar Allah da kuma shaidar Yesu Kiristi. ");
INSERT INTO hausa_vpl VALUES ("RV1_3","096_1_3","REV","1","3","3","Mai albarka ne wanda yake karanta waɗannan kalmomin annabci, masu albarka ne kuma waɗanda suke jinsu, suke kuma sa abin da aka rubuta a ciki a zuciya, domin lokaci ya yi kusa. ");
INSERT INTO hausa_vpl VALUES ("RV1_4","096_1_4","REV","1","4","4","Daga Yohanna, Zuwa ga ikkilisiyoyi bakwai da suke a lardin Asiya. Alheri da salama gare ku daga shi wanda yake a yanzu, wanda yake a dā, da kuma wanda zai zo, da kuma daga ruhohi bakwai da suke a gaban kursiyinsa, ");
INSERT INTO hausa_vpl VALUES ("RV1_5","096_1_5","REV","1","5","5","da kuma daga Yesu Kiristi, wanda yake amintaccen shaida, ɗan farin daga tashin matattu, da kuma mai mulkin sarakunan duniya. Gare shi wanda yake ƙaunarmu wanda kuma ya ’yantar da mu daga zunubanmu ta wurin jininsa, ");
INSERT INTO hausa_vpl VALUES ("RV1_6","096_1_6","REV","1","6","6","ya kuma mai da mu masarauta da firistoci don mu yi wa Allahnsa da Ubansa hidima, a gare shi ɗaukaka da iko sun tabbata har abada abadin! Amin. ");
INSERT INTO hausa_vpl VALUES ("RV1_7","096_1_7","REV","1","7","7","“Duba, yana zuwa cikin gizagizai, kowane ido kuwa zai gan shi, har da waɗanda suka soke shi”; dukan mutanen duniya kuwa “za su yi makoki dominsa.” ");
INSERT INTO hausa_vpl VALUES ("RV1_8","096_1_8","REV","1","8","8","“Ni ne Alfa da kuma Omega,” in ji Ubangiji Allah, “wanda yake a yanzu, wanda yake a dā, da kuma wanda zai zo, Maɗaukaki.” ");
INSERT INTO hausa_vpl VALUES ("RV1_9","096_1_9","REV","1","9","9","Ni, Yohanna, ɗan’uwanku da kuma abokin tarayyarku cikin wahala da mulki, da kuma haƙurin jimrewa da suke namu cikin Yesu, ina can tsibirin Fatmos saboda maganar Allah da kuma saboda shaidar Yesu. ");
INSERT INTO hausa_vpl VALUES ("RV1_10","096_1_10","REV","1","10","10","A Ranar Ubangiji ina cikin Ruhu, sai na ji a bayana wata babbar murya kamar ƙaho, ");
INSERT INTO hausa_vpl VALUES ("RV1_11","096_1_11","REV","1","11","11","wadda ta ce, “Rubuta a cikin naɗaɗɗen littafi abin da ka gani ka kuma aika ta zuwa ga ikkilisiyoyi bakwai, zuwa Afisa, Simirna, Fergamum, Tiyatira, Sardis, Filadelfiya, da kuma Lawodiseya.” ");
INSERT INTO hausa_vpl VALUES ("RV1_12","096_1_12","REV","1","12","12","Sai na juya don in ga muryar da take magana da ni. Da na juya kuwa sai na ga alkukan fitilu bakwai na zinariya. ");
INSERT INTO hausa_vpl VALUES ("RV1_13","096_1_13","REV","1","13","13","A tsakiyar alkukan kuwa akwai wani “kama da ɗan mutum,” saye da rigar da ya kai har ƙafafunsa da kuma ɗamarar zinariya daure a ƙirjinsa. ");
INSERT INTO hausa_vpl VALUES ("RV1_14","096_1_14","REV","1","14","14","Kansa da kuma gashin fari ne fat kamar ulu, fari kamar dusar ƙanƙara, idanunsa kuwa kamar harshen wuta. ");
INSERT INTO hausa_vpl VALUES ("RV1_15","096_1_15","REV","1","15","15","Sawunsa sun yi kamar tagullar da take haske cikin matoya, muryarsa kuma ta yi kamar muryar ruwaye masu gudu. ");
INSERT INTO hausa_vpl VALUES ("RV1_16","096_1_16","REV","1","16","16","A hannunsa na dama ya riƙe taurari bakwai, daga bakinsa kuwa takobi mai kaifi biyu ya fito. Fuskarsa ta yi kamar rana mai haskakawa da dukan haskenta. ");
INSERT INTO hausa_vpl VALUES ("RV1_17","096_1_17","REV","1","17","17","Sa’ad da na gan shi, sai na fāɗi a gabansa sai ka ce matacce. Sai ya ɗibiya hannunsa na dama a kaina ya ce, “Kada ka ji tsoro. Ni ne Farko da kuma Ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("RV1_18","096_1_18","REV","1","18","18","Ni ne Rayayye, dā na mutu, ga shi kuwa ina a raye har abada abadin! Ina kuma riƙe da mabuɗan mutuwa da na Hades. ");
INSERT INTO hausa_vpl VALUES ("RV1_19","096_1_19","REV","1","19","19","“Saboda haka, ka rubuta abin da ka gani, abin da yake yanzu, da abin da zai faru nan gaba. ");
INSERT INTO hausa_vpl VALUES ("RV1_20","096_1_20","REV","1","20","20","Asirin taurari bakwai da ka gani a hannuna na dama da kuma na alkukan fitilu bakwai na zinariya shi ne, Taurarin bakwai ɗin nan, mala’ikun ikkilisiyoyi bakwai ne; alkukan fitilu bakwai ɗin nan kuma ikkilisiyoyi bakwai ne. ");
INSERT INTO hausa_vpl VALUES ("RV2_1","096_2_1","REV","2","1","1","“Zuwa ga mala’ikan ikkilisiya a Afisa, ka rubuta, Waɗannan su ne kalmomi na wannan wanda yake riƙe da taurari bakwai a hannunsa na dama yana kuma tafiya a tsakanin alkukan fitilu bakwai na zinariya. ");
INSERT INTO hausa_vpl VALUES ("RV2_2","096_2_2","REV","2","2","2","Na san ayyukanka, faman aikinka da daurewarka. Na san cewa ba ka iya haƙuri da mugayen mutane, ka gwada waɗanda suke cewa su manzanni ne, alhali kuwa ba haka ba ne, ka kuwa tarar cewa su na ƙarya ne. ");
INSERT INTO hausa_vpl VALUES ("RV2_3","096_2_3","REV","2","3","3","Kai kam ka daure ka kuma jimre da wahala saboda sunana, ba ka kuwa gaji ba. ");
INSERT INTO hausa_vpl VALUES ("RV2_4","096_2_4","REV","2","4","4","Duk da haka ina riƙe da wannan game da kai. Ka watsar da ƙaunarka ta farko. ");
INSERT INTO hausa_vpl VALUES ("RV2_5","096_2_5","REV","2","5","5","Ka tuna da matsayinka a dā kafin ka fāɗi! Ka tuba ka kuma yi ayyukan da ka yi da fari. In ba ka tuba ba, zan zo wajenka in ɗauke wurin ajiye fitilanka daga inda yake. ");
INSERT INTO hausa_vpl VALUES ("RV2_6","096_2_6","REV","2","6","6","Sai dai kana da wannan abu mai kyau. Ka ƙi ayyukan Nikolaitawa da ni ma nake ƙi. ");
INSERT INTO hausa_vpl VALUES ("RV2_7","096_2_7","REV","2","7","7","Duk mai kunnen ji, yă ji abin da Ruhu yake faɗa wa ikkilisiyoyi. Duk wanda ya ci nasara, zan ba shi ikon ci daga itacen rai, da yake cikin aljannar Allah. ");
INSERT INTO hausa_vpl VALUES ("RV2_8","096_2_8","REV","2","8","8","“Zuwa ga mala’ikan ikkilisiya a Simirna, ka rubuta, Waɗannan su ne kalmomin wannan da yake na Farko da na Ƙarshe, wanda ya mutu ya kuma sāke tashi da rai. ");
INSERT INTO hausa_vpl VALUES ("RV2_9","096_2_9","REV","2","9","9","Na san wahalarka da kuma talaucinka, duk da haka kai mai arziki ne! Na san ɓata suna da waɗannan suke yi maka waɗannan da suke cewa su Yahudawa ne alhali kuwa ba haka ba ne, su dai majami’ar Shaiɗan ne. ");
INSERT INTO hausa_vpl VALUES ("RV2_10","096_2_10","REV","2","10","10","Kada ka ji tsoron wahalar da kake gab da sha. Ina gaya maka, Iblis zai sa waɗansunku a kurkuku don yă gwada ku. Za ku sha tsanani na kwana goma. Ka yi aminci ko da za a kashe ka, ni kuwa zan ba ka rawanin rai. ");
INSERT INTO hausa_vpl VALUES ("RV2_11","096_2_11","REV","2","11","11","Duk mai kunnen ji, yă ji abin da Ruhu yake faɗa wa ikkilisiyoyi. Duk wanda ya ci nasara mutuwa ta biyu ba za tă cuce shi ba ko kaɗan. ");
INSERT INTO hausa_vpl VALUES ("RV2_12","096_2_12","REV","2","12","12","“Zuwa ga mala’ikan ikkilisiya a Fergamum, ka rubuta, Waɗannan su ne kalmomin wannan wanda yake da takobi mai kaifi biyu. ");
INSERT INTO hausa_vpl VALUES ("RV2_13","096_2_13","REV","2","13","13","Na san inda kake da zama, inda Shaiɗan yana da gadon sarautarsa. Duk da haka ka riƙe sunana da gaske. Ba ka yi mūsun bangaskiyarka gare ni ba, har ma a kwanakin Antifas, amintaccen mashaidina, wanda aka kashe a birninku, inda Shaiɗan yake zama. ");
INSERT INTO hausa_vpl VALUES ("RV2_14","096_2_14","REV","2","14","14","Duk da haka, ina da abubuwa kima game da kai. Kana da mutane a can waɗanda suke riƙe da koyarwar Bala’am, wanda ya koya wa Balak yă ja hankalin Isra’ilawa su yi zunubi ta wurin cin abincin da aka miƙa wa gumaka hadaya, su kuma yi fasikanci. ");
INSERT INTO hausa_vpl VALUES ("RV2_15","096_2_15","REV","2","15","15","Haka ma kana da waɗanda suke riƙe da koyarwar Nikolaitawa. ");
INSERT INTO hausa_vpl VALUES ("RV2_16","096_2_16","REV","2","16","16","Saboda haka ka tuba! In ba haka ba, zan zo wajenka ba da daɗewa ba in yaƙe su da takobin bakina. ");
INSERT INTO hausa_vpl VALUES ("RV2_17","096_2_17","REV","2","17","17","Duk mai kunnen ji, yă ji abin da Ruhu yake faɗa wa ikkilisiyoyi. Duk wanda ya ci nasara zan ba shi kaɗan daga cikin ɓoyayyiyar Manna. Zan kuma ba shi farin dutse tare da sabon suna a rubuce a bisansa, sananne kawai ga mai karɓan dutsen. ");
INSERT INTO hausa_vpl VALUES ("RV2_18","096_2_18","REV","2","18","18","“Zuwa ga mala’ikan ikkilisiya a Tiyatira, ka rubuta, Waɗannan su ne kalmomin Ɗan Allah, wanda idanunsa suna kama da harshen wuta wanda kuma ƙafafunsa suna kama da tagullar da aka goge. ");
INSERT INTO hausa_vpl VALUES ("RV2_19","096_2_19","REV","2","19","19","Na san ayyukanka, ƙaunarka da bangaskiyarka, hidimarka da daurewarka, kuma cewa kana yin abubuwa a yanzu fiye da abin da ka yi da farko. ");
INSERT INTO hausa_vpl VALUES ("RV2_20","096_2_20","REV","2","20","20","Duk da haka, ina da wannan game da kai. Kana haƙuri da matan nan Yezebel, wadda take kira kanta annabiya. Ta wurin koyarwarta tana ɓad da bayina ga yin fasikanci suka kuma ci abincin da aka miƙa wa gumaka. ");
INSERT INTO hausa_vpl VALUES ("RV2_21","096_2_21","REV","2","21","21","Na ba ta lokaci tă tuba daga fasikancinta, amma ba ta da niyya. ");
INSERT INTO hausa_vpl VALUES ("RV2_22","096_2_22","REV","2","22","22","Don haka zan jefa ta a kan gadon wahala, zan kuma sa waɗanda suke zina da ita, su sha azaba ƙwarai, sai dai in sun tuba daga hanyoyinta. ");
INSERT INTO hausa_vpl VALUES ("RV2_23","096_2_23","REV","2","23","23","Zan kashe ’ya’yanta. Sa’an nan dukan ikkilisiyoyi za su san cewa ni ne mai bincika zukata da tunani, zan kuwa sāka wa kowannenku gwargwadon ayyukansa. ");
INSERT INTO hausa_vpl VALUES ("RV2_24","096_2_24","REV","2","24","24","Yanzu, ina ce wa sauranku da kuke a Tiyatira, ku da ba ku riƙe da koyarwarta ba kuma ba ku koyi abin da suke kira zurfafan asiran Shaiɗan, ‘Ba zan ƙara muku wani nauyi ba. ");
INSERT INTO hausa_vpl VALUES ("RV2_25","096_2_25","REV","2","25","25","Sai dai ku riƙe abin da kuke da shi har sai na zo.’ ");
INSERT INTO hausa_vpl VALUES ("RV2_26","096_2_26","REV","2","26","26","Gare shi wanda ya ci nasara ya kuma aikata nufina har ƙarshe, zan ba shi iko a kan al’ummai. ");
INSERT INTO hausa_vpl VALUES ("RV2_27","096_2_27","REV","2","27","27","‘Zai yi mulki a kansu da sandar sarauta ta ƙarfe, zai farfashe su, kamar tukwanen yumɓu’kamar yadda na karɓi iko daga Ubana. ");
INSERT INTO hausa_vpl VALUES ("RV2_28","096_2_28","REV","2","28","28","Zan kuma ba shi tauraron asubahi. ");
INSERT INTO hausa_vpl VALUES ("RV2_29","096_2_29","REV","2","29","29","Duk mai kunnen ji, yă ji abin da Ruhu yake faɗa wa ikkilisiyoyi. ");
INSERT INTO hausa_vpl VALUES ("RV3_1","096_3_1","REV","3","1","1","“Zuwa ga mala’ikan ikkilisiya a Sardis, ka rubuta, Waɗannan su ne kalmomi, na wanda yake riƙe da ruhohi bakwai na Allah da kuma taurari bakwai. Na san ayyukanka; ana ganinka kamar rayayye, amma kai matacce ne. ");
INSERT INTO hausa_vpl VALUES ("RV3_2","096_3_2","REV","3","2","2","Ka farka! Ka ƙarfafa abin da ya rage wanda kuma yake bakin mutuwa, don ban ga ayyukanka cikakke ne ba a gaban Allahna. ");
INSERT INTO hausa_vpl VALUES ("RV3_3","096_3_3","REV","3","3","3","Saboda haka, ka tuna fa, abin da ka karɓa ka kuma ji; ka yi biyayya da shi, ka kuma tuba. Amma in ba ka farka ba, zan zo kamar ɓarawo, ba kuwa za ka san lokacin da zan zo maka ba. ");
INSERT INTO hausa_vpl VALUES ("RV3_4","096_3_4","REV","3","4","4","Duk da haka kana da mutane kima cikin Sardis waɗanda ba su ɓata tufafinsu ba. Za su yi tafiya tare da ni, saye da fararen tufafi, don sun cancanta. ");
INSERT INTO hausa_vpl VALUES ("RV3_5","096_3_5","REV","3","5","5","Wanda ya ci nasara, kamar su, za a sanya masa fararen tufafi. Ba zan taɓa share sunansa daga cikin littafin rai ba, sai dai zan shaida sunansa a gaban Ubana da mala’ikunsa. ");
INSERT INTO hausa_vpl VALUES ("RV3_6","096_3_6","REV","3","6","6","Duk mai kunnen ji, yă ji abin da Ruhu yake faɗa wa ikkilisiyoyi. ");
INSERT INTO hausa_vpl VALUES ("RV3_7","096_3_7","REV","3","7","7","“Zuwa ga mala’ikan ikkilisiya a Filadelfiya, ka rubuta, Waɗannan su ne kalmomi, na wanda yake mai tsarki da kuma gaskiya, wanda yake riƙe da mabuɗin Dawuda. Abin da ya buɗe ba mai rufewa, abin da kuma ya rufe ba mai buɗewa. ");
INSERT INTO hausa_vpl VALUES ("RV3_8","096_3_8","REV","3","8","8","Na san ayyukanka. Duba, na sa a gabanka buɗaɗɗen ƙofa wadda ba mai iya rufewa. Na san cewa kana da ɗan ƙarfi, duk da haka ka kiyaye maganata ba ka kuwa yi mūsun sunana ba. ");
INSERT INTO hausa_vpl VALUES ("RV3_9","096_3_9","REV","3","9","9","Zan sa waɗanda suke na majami’ar Shaiɗan, waɗanda suke cewa su Yahudawa ne alhali kuwa ba haka ba ne, sai dai maƙaryata, zan sa su zo su fāɗi a ƙasa a gabanka su kuma shaida cewa na ƙaunace ka. ");
INSERT INTO hausa_vpl VALUES ("RV3_10","096_3_10","REV","3","10","10","Da yake ka kiyaye umarnina ta wurin jimrewa, ni ma zan tsare ka daga lokacin nan na gwaji wanda zai zo bisan dukan duniya don a gwada waɗanda suke zama a duniya. ");
INSERT INTO hausa_vpl VALUES ("RV3_11","096_3_11","REV","3","11","11","Ina zuwa ba da daɗewa ba. Ka riƙe abin da kake da shi, don kada wani ya karɓe rawaninka. ");
INSERT INTO hausa_vpl VALUES ("RV3_12","096_3_12","REV","3","12","12","Duk wanda ya ci nasara zan mai da shi ginshiƙi a haikalin Allahna. Ba kuwa zai sāke barin wurin ba. Zan rubuta a kansa sunan Allahna da kuma sunan birnin Allahna, sabuwar Urushalima, wadda take saukowa daga sama daga Allahna; ni kuma zan rubuta a kansa sabon sunana. ");
INSERT INTO hausa_vpl VALUES ("RV3_13","096_3_13","REV","3","13","13","Duk mai kunnen ji, yă ji abin da Ruhu yake faɗa wa ikkilisiyoyi. ");
INSERT INTO hausa_vpl VALUES ("RV3_14","096_3_14","REV","3","14","14","“Zuwa ga mala’ikan ikkilisiya a Lawodiseya, ka rubuta, Waɗannan su ne kalmomina Amin, amintaccen mashaidi mai gaskiya, da kuma mai mulkin halittar Allah. ");
INSERT INTO hausa_vpl VALUES ("RV3_15","096_3_15","REV","3","15","15","Na san ayyukanka, ba ka da sanyi ba ka kuma da zafi. Na so da kai ɗaya ne daga ciki, ko sanyi, ko zafi! ");
INSERT INTO hausa_vpl VALUES ("RV3_16","096_3_16","REV","3","16","16","Amma domin kana tsaka-tsaka ba zafi ba, ba kuma sanyi ba, ina dab da tofar da kai daga bakina. ");
INSERT INTO hausa_vpl VALUES ("RV3_17","096_3_17","REV","3","17","17","Ka ce, ‘Ina da arziki; na sami dukiya ba na kuma bukatar kome.’ Amma ba ka gane ba cewa kai matsiyaci ne, abin tausayi, matalauci, makaho kana kuma tsirara. ");
INSERT INTO hausa_vpl VALUES ("RV3_18","096_3_18","REV","3","18","18","Na shawarce ka ka sayi zinariyar da aka tace cikin wuta daga gare ni, don ka yi arziki; da fararen tufafi ka sa, don ka rufe kunyar tsirancinka; da kuma maganin ido ka sa a idanunka, don ka gani. ");
INSERT INTO hausa_vpl VALUES ("RV3_19","096_3_19","REV","3","19","19","Waɗanda nake ƙauna su nake tsawata wa, nake kuma horo. Saboda haka ka yi himma ka tuba. ");
INSERT INTO hausa_vpl VALUES ("RV3_20","096_3_20","REV","3","20","20","Ga ni! Ina tsaye a bakin ƙofa, ina ƙwanƙwasawa. Duk wanda ya ji muryata ya kuma buɗe ƙofar, zan shiga in kuma ci tare da shi, shi kuma tare da ni. ");
INSERT INTO hausa_vpl VALUES ("RV3_21","096_3_21","REV","3","21","21","Duk wanda ya ci nasara, zan ba shi ikon zama tare da ni a kursiyina, kamar yadda na ci nasara, kuma ina zaune tare da Ubana a kursiyinsa. ");
INSERT INTO hausa_vpl VALUES ("RV3_22","096_3_22","REV","3","22","22","Duk mai kunnen ji, yă ji abin da Ruhu yake faɗa wa ikkilisiyoyi.” ");
INSERT INTO hausa_vpl VALUES ("RV4_1","096_4_1","REV","4","1","1","Bayan wannan sai na duba, a can kuma a gabana ga ƙofa a buɗe a sama. Sai muryar da na ji da fari da take magana da ni mai kama da busar ƙaho ta ce, “Hauro nan, zan kuma nuna maka abin da lalle zai faru bayan wannan.” ");
INSERT INTO hausa_vpl VALUES ("RV4_2","096_4_2","REV","4","2","2","Nan da nan sai ga ni cikin Ruhu, a can a gabana kuwa ga kursiyi a cikin sama da wani zaune a kansa. ");
INSERT INTO hausa_vpl VALUES ("RV4_3","096_4_3","REV","4","3","3","Wannan mai zama a can kuwa yana da kamannin dutsen yasfa da karneliya. Bakan gizo, mai kama da zumurrudu, ya kewaye kursiyin. ");
INSERT INTO hausa_vpl VALUES ("RV4_4","096_4_4","REV","4","4","4","Kewaye da kursiyin kuwa akwai waɗansu kursiyoyi ashirin da huɗu, zaune a kansu kuwa dattawa ashirin da huɗu ne. Suna saye da fararen tufafi suna kuma da rawanin zinariya a kawunansu. ");
INSERT INTO hausa_vpl VALUES ("RV4_5","096_4_5","REV","4","5","5","Daga kursiyin hasken walƙiya yana ta fitowa, da ƙararraki da kuma tsawa. A gaban kursiyin, fitilu bakwai suna ci. Waɗannan ne ruhohi bakwai na Allah. ");
INSERT INTO hausa_vpl VALUES ("RV4_6","096_4_6","REV","4","6","6","Haka kuma a gaban kursiyin akwai wani abu mai kama da tekun gilashi, yana ƙyalli kamar madubi. A tsakiya kuwa, kewaye da kursiyin, akwai halittu huɗu masu rai, cike kuma suna da idanu gaba da baya. ");
INSERT INTO hausa_vpl VALUES ("RV4_7","096_4_7","REV","4","7","7","Halitta ta fari tana kama da zaki, ta biyun kuwa tana kama da bijimi, ta ukun kuma tana da fuska kamar ta mutum, ta huɗun kuma tana kama da gaggafa mai tashi sama. ");
INSERT INTO hausa_vpl VALUES ("RV4_8","096_4_8","REV","4","8","8","Kowace a cikin halittu huɗu masu rai ɗin nan tana da fikafikai guda shida, tana kuma cike da idanu a ko’ina, har ma ƙarƙashin fikafikanta. Dare da rana ba sa fasa cewa, ");
INSERT INTO hausa_vpl VALUES ("RV4_9","096_4_9","REV","4","9","9","Duk lokacin da halittu masu ran nan suka rera ɗaukaka, girma da kuma godiya ga wannan wanda yake zaune a kan kursiyin da kuma wanda yake mai rai har abada abadin, ");
INSERT INTO hausa_vpl VALUES ("RV4_10","096_4_10","REV","4","10","10","sai dattawa ashirin da huɗun nan su fāɗi a ƙasa a gaban wannan wanda yake zaune a kursiyin, su yi sujada wa wannan wanda yake da rai har abada abadin. Sukan ajiye rawaninsu a gaban kursiyin suna cewa, ");
INSERT INTO hausa_vpl VALUES ("RV4_11","096_4_11","REV","4","11","11","“Ya Ubangijinmu da Allahnmu, ka cancanci ɗaukaka da girma da iko, domin ka halicci dukan abubuwa, kuma ta wurin nufinka aka halicce su suka kuma kasance.” ");
INSERT INTO hausa_vpl VALUES ("RV5_1","096_5_1","REV","5","1","1","Sa’an nan na ga a hannun damar wannan wanda yake zaune a kursiyin naɗaɗɗen littafi da rubutu a ciki da wajensa an kuma hatimce shi da hatimai bakwai. ");
INSERT INTO hausa_vpl VALUES ("RV5_2","096_5_2","REV","5","2","2","Na kuma ga wani babban mala’ika yana shela da babbar murya cewa, “Wa ya cancanta yă ɓalle hatiman nan yă kuma buɗe naɗaɗɗen littafin?” ");
INSERT INTO hausa_vpl VALUES ("RV5_3","096_5_3","REV","5","3","3","Amma ba wani a sama ko a ƙasa ko a ƙarƙashin ƙasan da ya iya buɗe naɗaɗɗen littafin ko ma yă duba cikinsa. ");
INSERT INTO hausa_vpl VALUES ("RV5_4","096_5_4","REV","5","4","4","Na yi ta kuka domin ba a iya samun wanda ya cancanta yă buɗe naɗaɗɗen littafin ko yă duba cikinsa ba. ");
INSERT INTO hausa_vpl VALUES ("RV5_5","096_5_5","REV","5","5","5","Sai ɗaya daga cikin dattawan ya ce mini, “Kada ka yi kuka! Duba, Zakin kabilar Yahuda, da kuma Tushen Dawuda ya ci nasara. Ya iya buɗe naɗaɗɗen littafin da hatimansa bakwai.” ");
INSERT INTO hausa_vpl VALUES ("RV5_6","096_5_6","REV","5","6","6","Sa’an nan na ga Ɗan Rago, yana kamar an yanka, tsaye a tsakiyar kursiyin, halittu huɗun nan masu rai da kuma dattawan an sun kewaye shi. Yana da ƙahoni bakwai da idanu bakwai, waɗanda suke ruhohi bakwai na Allah da aka aika cikin dukan duniya. ");
INSERT INTO hausa_vpl VALUES ("RV5_7","096_5_7","REV","5","7","7","Ya zo ya karɓi naɗaɗɗen littafin daga hannun dama na wannan wanda yake zaune a kursiyin. ");
INSERT INTO hausa_vpl VALUES ("RV5_8","096_5_8","REV","5","8","8","Bayan ya karɓa, sai halittu huɗun nan masu rai da kuma dattawan nan ashirin da huɗu suka fāɗi ƙasa a gaban Ɗan Ragon. Kowannensu yana da garaya kuma suna riƙe da kaskon zinariya cike da turare, waɗanda suke addu’o’in tsarkaka. ");
INSERT INTO hausa_vpl VALUES ("RV5_9","096_5_9","REV","5","9","9","Suka rera sabuwar waƙa, “Ka cancanci ka karɓi naɗaɗɗen littafin ka kuma buɗe hatimansa, domin an kashe ka, da jininka kuma ka sayi mutane wa Allah, daga kowace kabila da harshe da mutane da kuma al’umma. ");
INSERT INTO hausa_vpl VALUES ("RV5_10","096_5_10","REV","5","10","10","Ka mai da su masarauta da kuma firistoci, don su yi wa Allahnmu hidima, kuma za su yi mulki a duniya.” ");
INSERT INTO hausa_vpl VALUES ("RV5_11","096_5_11","REV","5","11","11","Sai na duba na kuma ji muryar mala’iku masu yawa, yawansu kuwa ya kai dubu dubbai, da kuma dubu goma sau dubu goma. Suka kewaye kursiyin da halittu huɗun nan masu rai da kuma dattawan nan. ");
INSERT INTO hausa_vpl VALUES ("RV5_12","096_5_12","REV","5","12","12","Da babbar murya suka rera, “Macancanci ne Ɗan Ragon nan da aka kashe, don yă sami iko da wadata da hikima da ƙarfi da girma da ɗaukaka da kuma yabo!” ");
INSERT INTO hausa_vpl VALUES ("RV5_13","096_5_13","REV","5","13","13","Sa’an nan na ji kowace halitta a sama da ƙasa da ƙarƙashin ƙasa da kuma bisan teku, da kome da yake cikinsu yana rerawa, “Gare shi mai zama a kan kursiyin da kuma ga Ɗan Ragon yabo da girma da ɗaukaka da iko, ");
INSERT INTO hausa_vpl VALUES ("RV5_14","096_5_14","REV","5","14","14","Sai halittu huɗun nan masu rai suka ce, “Amin”, dattawan kuma suka fāɗi suka yi sujada. ");
INSERT INTO hausa_vpl VALUES ("RV6_1","096_6_1","REV","6","1","1","Na kalli yayinda Ɗan Ragon ya buɗe hatimin farko na hatimai bakwai ɗin nan. Sai na ji ɗaya daga cikin halittu huɗun nan masu rai ya yi magana da murya mai kama da tsawa ya ce, “Zo!” ");
INSERT INTO hausa_vpl VALUES ("RV6_2","096_6_2","REV","6","2","2","Na duba, can kuwa a gabana ga wani farin doki! Mai hawansa yana riƙe da baka, aka kuma ba shi rawani, ya yi sukuwa ya fito kamar mai nasara da ya kutsa don nasara. ");
INSERT INTO hausa_vpl VALUES ("RV6_3","096_6_3","REV","6","3","3","Sa’ad da Ɗan Ragon ya buɗe hatimi na biyun, sai na ji halitta mai rai na biyu ya ce, “Zo!” ");
INSERT INTO hausa_vpl VALUES ("RV6_4","096_6_4","REV","6","4","4","Sai wani doki ya fito, ja wur. Aka ba wa mai hawansa iko yă ɗauke salama daga duniya yă kuma sa mutane su kashe juna. Aka ba shi babban takobi. ");
INSERT INTO hausa_vpl VALUES ("RV6_5","096_6_5","REV","6","5","5","Sa’ad da Ɗan Ragon ya buɗe hatimi na uku, sai na ji halitta mai rai na uku ya ce, “Zo!” Na duba, can a gabana kuwa ga wani baƙin doki! Mai hawansa yana riƙe da abubuwan awo guda biyu a hannunsa. ");
INSERT INTO hausa_vpl VALUES ("RV6_6","096_6_6","REV","6","6","6","Sai na ji wani abu mai ƙara kamar wata murya a tsakiyar halittu huɗun nan masu rai tana cewa, “Kwatan alkama don albashin aikin yini, da kuma kwata uku na sha’ir don albashin yini guda, kada kuwa ka ɓata man da ruwan inabi!” ");
INSERT INTO hausa_vpl VALUES ("RV6_7","096_6_7","REV","6","7","7","Sa’ad da Ɗan Ragon ya buɗe hatimi na huɗu, sai na ji muryar halitta mai rai na huɗu ya ce, “Zo!” ");
INSERT INTO hausa_vpl VALUES ("RV6_8","096_6_8","REV","6","8","8","Na duba, can a gabana kuwa ga ƙodaɗɗen doki! An ba wa mai hawansa suna Mutuwa, Hades kuwa yana biye da shi. Aka ba su iko a kan kashi ɗaya bisa huɗu na duniya don su yi kisa da takobi, yunwa da annoba, har ma da namomin jeji na duniya. ");
INSERT INTO hausa_vpl VALUES ("RV6_9","096_6_9","REV","6","9","9","Sa’ad da ya buɗe hatimi na biyar, sai na ga a ƙarƙashin bagaden rayukan waɗanda aka kashe saboda maganar Allah da kuma shaidar da suka yi. ");
INSERT INTO hausa_vpl VALUES ("RV6_10","096_6_10","REV","6","10","10","Suka yi kira da babbar murya suka ce, “Ya Ubangiji Mai Iko Duka, Mai Tsarki da kuma Mai Gaskiya, sai yaushe za ka shari’anta mazaunan duniya ka kuma ɗauki mana fansar jininmu?” ");
INSERT INTO hausa_vpl VALUES ("RV6_11","096_6_11","REV","6","11","11","Sai aka ba wa kowannensu farin riga, aka kuma faɗa musu su ɗan jira kaɗan sai an cika adadin abokansu masu hidima da kuma ’yan’uwansu waɗanda za a kashe kamar yadda su ma aka kashe su. ");
INSERT INTO hausa_vpl VALUES ("RV6_12","096_6_12","REV","6","12","12","Ina kallo yayinda ya buɗe hatimi na shida. Sai aka yi babban girgizar ƙasa. Rana ta zama baƙa kamar gwado na gashin akuya, wata kuma gaba ɗaya ya zama ja wur kamar jini, ");
INSERT INTO hausa_vpl VALUES ("RV6_13","096_6_13","REV","6","13","13","taurarin sararin sama suka fāffāɗi a ƙasa, kamar yadda ɗanyun ’ya’yan ɓaure suke fāɗuwa daga itacen ɓaure sa’ad da iska mai ƙarfi ta jijjiga shi. ");
INSERT INTO hausa_vpl VALUES ("RV6_14","096_6_14","REV","6","14","14","Sararin sama kuwa ya janye kamar naɗaɗɗen littafi, ya yi ta naɗewa, aka kuma kawar da kowane dutse da kowane tsibiri daga wurinsa. ");
INSERT INTO hausa_vpl VALUES ("RV6_15","096_6_15","REV","6","15","15","Sa’an nan sarakunan duniya, hakimai, jarumawa, masu arziki, masu ƙarfi, da kowane bawa da kuma kowane ’yantacce ya ɓoye a cikin koguna da kuma cikin duwatsun tsaunuka. ");
INSERT INTO hausa_vpl VALUES ("RV6_16","096_6_16","REV","6","16","16","Suka kira duwatsu da tsaunuka suna cewa, “Ku fāɗi a kanmu ku kuma ɓoye mu daga fuskar wannan mai zama a kan kursiyi da kuma daga fushin Ɗan Ragon nan! ");
INSERT INTO hausa_vpl VALUES ("RV6_17","096_6_17","REV","6","17","17","Gama babbar ranar fushinsu ta zo, wa kuwa zai iya tsayawa?” ");
INSERT INTO hausa_vpl VALUES ("RV7_1","096_7_1","REV","7","1","1","Bayan wannan, na ga mala’iku huɗu, a tsaye a kusurwoyi huɗu na duniya, suna tsare iskoki huɗu na duniya, domin su hana wani iska hurawa a bisan ƙasa ko a bisan teku ko a bisa wani itace. ");
INSERT INTO hausa_vpl VALUES ("RV7_2","096_7_2","REV","7","2","2","Sai na ga wani mala’ika yana zuwa daga gabas, yana da hatimin Allah mai rai. Ya yi kira da babbar murya wa mala’ikun nan huɗu da aka ba su iko su cuci ƙasa da teku ya ce, ");
INSERT INTO hausa_vpl VALUES ("RV7_3","096_7_3","REV","7","3","3","“Kada ku cuci ƙasa ko teku ko kuma itatuwa sai bayan mun sa hatimi a goshin dukan bayin Allahnmu.” ");
INSERT INTO hausa_vpl VALUES ("RV7_4","096_7_4","REV","7","4","4","Sai na ji yawan waɗanda aka sa musu hatimi. Su 144,000 daga dukan kabilan Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("RV7_5","096_7_5","REV","7","5","5","Daga kabilar Yahuda mutum 12,000 ne aka sa musu hatimin, daga kabilar Ruben mutum 12,000, daga kabilar Gad mutum 12,000, ");
INSERT INTO hausa_vpl VALUES ("RV7_6","096_7_6","REV","7","6","6","daga kabilar Asher mutum 12,000, daga kabilar Naftali mutum 12,000, daga kabilar Manasse mutum 12,000, ");
INSERT INTO hausa_vpl VALUES ("RV7_7","096_7_7","REV","7","7","7","daga kabilar Simeyon mutum 12,000, daga kabilar Lawi mutum 12,000, daga kabilar Issakar mutum 12,000, ");
INSERT INTO hausa_vpl VALUES ("RV7_8","096_7_8","REV","7","8","8","daga kabilar Zebulun mutum 12,000, daga kabilar Yusuf mutum 12,000, daga kabilar Benyamin mutum 12,000. ");
INSERT INTO hausa_vpl VALUES ("RV7_9","096_7_9","REV","7","9","9","Bayan wannan sai na duba, can a gabana kuwa ga wani taro mai girma, wanda ba mai iya ƙirgawa, daga kowace al’umma, kabila, mutane da kuma harshe, suna tsaye a gaban kursiyin da kuma gaban Ɗan Ragon nan. Suna saye da fararen tufafi suna kuma riƙe da rassan dabino a hannuwansu. ");
INSERT INTO hausa_vpl VALUES ("RV7_10","096_7_10","REV","7","10","10","Suka tā da murya da ƙarfi suna cewa, “Ceto na Allahnmu ne, wanda yake zaune a bisan kursiyi, da kuma na Ɗan Ragon.” ");
INSERT INTO hausa_vpl VALUES ("RV7_11","096_7_11","REV","7","11","11","Dukan mala’iku suna tsaye kewaye da kursiyin da kuma kewaye da dattawan tare da halittu huɗun nan masu rai. Suka fāɗi da fuskokinsu ƙasa a gaban kursiyin suka kuma yi wa Allah sujada, ");
INSERT INTO hausa_vpl VALUES ("RV7_12","096_7_12","REV","7","12","12","suna cewa, “Amin! Yabo da ɗaukaka, da hikima da godiya da girma da iko da ƙarfi sun tabbata ga Allahnmu har abada abadin. Amin!” ");
INSERT INTO hausa_vpl VALUES ("RV7_13","096_7_13","REV","7","13","13","Sai ɗaya daga cikin dattawan ya tambaye ni ya ce, “Waɗannan da suke saye da fararen tufafi su wane ne, daga ina kuma suka fito?” ");
INSERT INTO hausa_vpl VALUES ("RV7_14","096_7_14","REV","7","14","14","Na amsa na ce, “Ranka yă daɗe, kai ka sani.” Sai ya ce, “Waɗannan su ne waɗanda suka fito daga matsananciyar wahala; sun wanke tufafinsu suka kuma mai da su farare da jinin Ɗan Ragon nan. ");
INSERT INTO hausa_vpl VALUES ("RV7_15","096_7_15","REV","7","15","15","Saboda haka, “suna a gaban kursiyin Allah suna masa hidima dare da rana a cikin haikalinsa; kuma wannan mai zaune a kursiyin zai shimfiɗa tentinsa a bisansu. ");
INSERT INTO hausa_vpl VALUES ("RV7_16","096_7_16","REV","7","16","16","‘Ba za su sāke jin yunwa ba; ba za su kuma sāke jin ƙishirwa ba. Rana ba za tă buga su ba,’ ko kuma kowane irin zafin ƙuna. ");
INSERT INTO hausa_vpl VALUES ("RV7_17","096_7_17","REV","7","17","17","Gama Ɗan Ragon da yake a tsakiyar kursiyin zai zama makiyayinsu; ‘zai bi da su zuwa ga maɓulɓular ruwan rai.’ ‘Allah kuwa zai share dukan hawaye daga idanunsu.’ ” ");
INSERT INTO hausa_vpl VALUES ("RV8_1","096_8_1","REV","8","1","1","Sa’ad da ya buɗe hatimi na bakwai, sai aka yi shiru a sama na kusan rabin sa’a. ");
INSERT INTO hausa_vpl VALUES ("RV8_2","096_8_2","REV","8","2","2","Sai na ga mala’iku bakwai da suke tsayawa a gaban Allah, a gare su kuwa aka ba da ƙahoni bakwai. ");
INSERT INTO hausa_vpl VALUES ("RV8_3","096_8_3","REV","8","3","3","Wani mala’ika, da yake da kaskon zinariyar da ake zuba turare, ya zo ya tsaya kusa da bagaden. Aka ba shi turare da yawa don yă miƙa tare da addu’o’in dukan tsarkaka a bisa bagaden zinariya a gaban kursiyin. ");
INSERT INTO hausa_vpl VALUES ("RV8_4","096_8_4","REV","8","4","4","Hayaƙin turaren tare da addu’o’in tsarkaka, suka hau zuwa gaban Allah daga hannun mala’ikan. ");
INSERT INTO hausa_vpl VALUES ("RV8_5","096_8_5","REV","8","5","5","Sai mala’ikan ya ɗauki kaskon, ya cika shi da wuta daga bagaden, ya kuma wurga shi bisan duniya; sai aka yi ta yin tsawa, ƙararraki, walƙiya, da kuma girgizar ƙasa. ");
INSERT INTO hausa_vpl VALUES ("RV8_6","096_8_6","REV","8","6","6","Sai mala’iku bakwai ɗin nan da suke da ƙahoni bakwai suka shirya don su busa su. ");
INSERT INTO hausa_vpl VALUES ("RV8_7","096_8_7","REV","8","7","7","Mala’ika na fari ya busa ƙahonsa, sai ga ƙanƙara da wuta haɗe da jini, aka kuma wurga su bisan duniya. Kashi ɗaya bisa uku na duniya ya ƙone, kashi ɗaya bisa uku na itatuwa suka ƙone, dukan ɗanyar ciyawa kuma ta ƙone. ");
INSERT INTO hausa_vpl VALUES ("RV8_8","096_8_8","REV","8","8","8","Mala’ika na biyu ya busa ƙahonsa, sai ga wani abu kamar babban dutse mai cin wuta, aka jefa cikin teku. Kashi ɗaya bisa uku na teku ya zama jini, ");
INSERT INTO hausa_vpl VALUES ("RV8_9","096_8_9","REV","8","9","9","kashi ɗaya bisa uku na halittu masu rai da suke cikin tekun suka mutu, kashi ɗaya bisa uku kuma na jiragen ruwa kuma suka hallaka. ");
INSERT INTO hausa_vpl VALUES ("RV8_10","096_8_10","REV","8","10","10","Mala’ika na uku ya busa ƙahonsa, sai wani babban tauraro mai cin wuta kamar toci, ya fāɗi daga sararin sama, a kan kashi ɗaya bisa uku na koguna da kuma a bisa maɓulɓulan ruwa ");
INSERT INTO hausa_vpl VALUES ("RV8_11","096_8_11","REV","8","11","11","sunan tauraron kuwa Maɗaci. Kashi ɗaya bisa uku na ruwaye ya zama mai ɗaci, mutane da yawa kuma suka mutu saboda shan ruwan, don ɗacinsa. ");
INSERT INTO hausa_vpl VALUES ("RV8_12","096_8_12","REV","8","12","12","Mala’ika na huɗu ya busa ƙahonsa, sai aka bugi kashi ɗaya bisa uku na rana, kashi ɗaya bisa uku na wata, da kashi ɗaya bisa uku na taurari, har kashi ɗaya bisa uku nasu ya duhunta. Kashi ɗaya bisa uku na yini ya kasance babu haske, haka ma kashi ɗaya bisan uku na dare. ");
INSERT INTO hausa_vpl VALUES ("RV8_13","096_8_13","REV","8","13","13","Yayinda nake kallo, sai na ji gaggafar da take tashi sama a tsakiyar sararin sama ta yi kira da babbar murya ta ce, “Kaito! Kaito! Kaiton mazaunan duniya, in an yi busan sauran ƙahonin da mala’ikun nan uku suke shirin busawa!” ");
INSERT INTO hausa_vpl VALUES ("RV9_1","096_9_1","REV","9","1","1","Mala’ika na biyar ya busa ƙahonsa, sai na ga tauraron da ya fāɗo duniya daga sararin sama. Aka ba wa tauraron mabuɗin ramin Abis. ");
INSERT INTO hausa_vpl VALUES ("RV9_2","096_9_2","REV","9","2","2","Da ya buɗe Abis ɗin, sai hayaƙi ya taso daga cikin kamar hayaƙin matoya mai girma. Hayaƙin nan daga Abis ya duhunta rana da sararin sama. ");
INSERT INTO hausa_vpl VALUES ("RV9_3","096_9_3","REV","9","3","3","Daga cikin hayaƙin kuwa fāri suka fito zuwa cikin duniya aka kuma ba su iko irin na kunaman duniya. ");
INSERT INTO hausa_vpl VALUES ("RV9_4","096_9_4","REV","9","4","4","Aka faɗa musu kada su yi wa ciyawa na duniya lahani ko wani tsiro ko itace, sai dai su yi wa mutanen da ba su da hatimin Allah a goshinsu kaɗai lahani. ");
INSERT INTO hausa_vpl VALUES ("RV9_5","096_9_5","REV","9","5","5","Ba a ba su iko su kashe su ba, sai dai su ba su azaba na watanni biyar. Azabar da suka sha kuwa ya yi kamar ta harbin kunama sa’ad da ta harbi mutum. ");
INSERT INTO hausa_vpl VALUES ("RV9_6","096_9_6","REV","9","6","6","Cikin waɗannan kwanakin mutane za su nemi mutuwa, amma ba za su samu ba; za su yi marmarin mutuwa, amma mutuwa za tă ɓace musu. ");
INSERT INTO hausa_vpl VALUES ("RV9_7","096_9_7","REV","9","7","7","Kamannin fārin nan kuwa yana kama da dawakan da aka shirya don yaƙi. A kawunansu kuwa da wani abu da ya yi kamar rawanin zinariya, fuskokinsu kuma sun yi kamar fuskokin mutane. ");
INSERT INTO hausa_vpl VALUES ("RV9_8","096_9_8","REV","9","8","8","Gashin kansu ya yi kamar gashin kan mata, haƙoransu kuma sun yi kamar haƙoran zakoki. ");
INSERT INTO hausa_vpl VALUES ("RV9_9","096_9_9","REV","9","9","9","Suna da sulkuna kamar sulkunan ƙarfe, ƙarar fikafikansu kuma ta yi kamar motsin dawakai da kekunan yaƙi masu yawa da suke rugawa zuwa yaƙi. ");
INSERT INTO hausa_vpl VALUES ("RV9_10","096_9_10","REV","9","10","10","Suna da wutsiyoyi da ƙari kamar kunamai, kuma a wutsiyoyinsu suna da iko su ba wa mutane azaba na wata biyar. ");
INSERT INTO hausa_vpl VALUES ("RV9_11","096_9_11","REV","9","11","11","Suna da sarkin da yake mulki a bisansu wanda yake mala’ikan Abis, wanda sunansa a harshen Yahudawa shi ne Abaddon, da harshen Hellenawa kuwa shi ne, Afolliyon. ");
INSERT INTO hausa_vpl VALUES ("RV9_12","096_9_12","REV","9","12","12","Bala’i na fari ya wuce, sauran bala’i biyu suna nan zuwa. ");
INSERT INTO hausa_vpl VALUES ("RV9_13","096_9_13","REV","9","13","13","Mala’ika na shida ya busa ƙahonsa, sai na ji murya tana fitowa daga ƙahonin bagaden zinariya da suke a gaban Allah. ");
INSERT INTO hausa_vpl VALUES ("RV9_14","096_9_14","REV","9","14","14","Ta ce wa mala’ika na shida da yake da ƙahon, “Ka saki mala’iku huɗun nan da suke a daure a babban kogin Yuferites.” ");
INSERT INTO hausa_vpl VALUES ("RV9_15","096_9_15","REV","9","15","15","Mala’iku huɗun nan kuwa da aka shirya musamman don wannan sa’a da kuma don wannan rana da wata da kuma shekara aka sake su domin su kashe kashi ɗaya bisa uku na ’yan Adam. ");
INSERT INTO hausa_vpl VALUES ("RV9_16","096_9_16","REV","9","16","16","Yawan rundunan masu hawan dawakan nan mutum miliyon ɗari biyu ne. Na ji adadinsu. ");
INSERT INTO hausa_vpl VALUES ("RV9_17","096_9_17","REV","9","17","17","Dawakai da masu hawansu da na gani cikin wahayina sun yi kamar. Sulkunansu ja wur ne, baƙin shuɗi, da kuma rawaya kamar farar wuta. Kawunan dawakan sun yi kamar kawunan zakoki, daga bakunansu kuwa wuta, hayaƙi, da farar wuta suna fitowa. ");
INSERT INTO hausa_vpl VALUES ("RV9_18","096_9_18","REV","9","18","18","Aka kashe kashi ɗaya bisa uku na ’yan Adam da annobai uku na wuta, hayaƙi da farar wuta da suka fito daga bakunansu. ");
INSERT INTO hausa_vpl VALUES ("RV9_19","096_9_19","REV","9","19","19","Ƙarfin dawakan nan kuwa yana a bakunansu da wutsiyoyinsu; gama wutsiyoyinsu suna kama da macizai masu kawuna, da wutsiyoyin ne kuma suke yi wa mutane rauni. ");
INSERT INTO hausa_vpl VALUES ("RV9_20","096_9_20","REV","9","20","20","Sauran ’yan Adam da ba a kashe ta wajen waɗannan annobai ba kuwa har wa yau ba su tuba daga aikin hannuwansu ba; ba su daina bauta wa aljanu, da gumakan zinariya, azurfa, tagulla, dutse da na itace, gumakan da ba sa iya gani ko ji ko tafiya ba. ");
INSERT INTO hausa_vpl VALUES ("RV9_21","096_9_21","REV","9","21","21","Ba su kuma tuba daga kisankansu, sihirinsu, fasikancinsu ko kuma daga sace-sacensu ba. ");
INSERT INTO hausa_vpl VALUES ("RV10_1","096_10_1","REV","10","1","1","Sai na ga wani babban mala’ika yana saukowa daga sama. An lulluɓe shi da girgije, bakan gizo kuma yana kansa; fuskarsa tana kama da rana, ƙafafunsa kuma suna kama da ginshiƙan wuta. ");
INSERT INTO hausa_vpl VALUES ("RV10_2","096_10_2","REV","10","2","2","Yana riƙe da ɗan ƙaramin naɗaɗɗen littafi, wanda yake a buɗe a hannunsa. Ya kafa ƙafarsa ta dama a kan teku ƙafarsa ta hagu kuma a kan ƙasa, ");
INSERT INTO hausa_vpl VALUES ("RV10_3","096_10_3","REV","10","3","3","ya kuma yi ihu da ƙarfi kamar rurin zaki. Da ya yi ihun, sai muryoyin tsawan nan bakwai suka yi magana. ");
INSERT INTO hausa_vpl VALUES ("RV10_4","096_10_4","REV","10","4","4","Sa’ad da tsawan nan bakwai kuwa suka yi magana, ina dab da rubutawa; amma na ji wata murya daga sama ta ce, “Rufe abin da tsawan nan bakwai suka faɗa kada ka rubuta.” ");
INSERT INTO hausa_vpl VALUES ("RV10_5","096_10_5","REV","10","5","5","Sai mala’ikan da na gani na tsaye a teku da ƙasa ya ɗaga hannunsa na dama sama. ");
INSERT INTO hausa_vpl VALUES ("RV10_6","096_10_6","REV","10","6","6","Ya kuma yi rantsuwa da wannan wanda yake raye har abada abadin, wanda ya halicci sammai da dukan abin da yake cikinsu, duniya da dukan abin da yake cikinta, da kuma teku da dukan abin da yake cikinsa, ya kuma ce, “Babu sauran jinkiri! ");
INSERT INTO hausa_vpl VALUES ("RV10_7","096_10_7","REV","10","7","7","Amma a ranakun da mala’ika na bakwai na dab da busa ƙahonsa, za a cika asirin Allah, kamar yadda ya sanar wa bayinsa annabawa.” ");
INSERT INTO hausa_vpl VALUES ("RV10_8","096_10_8","REV","10","8","8","Sai muryar da na ji daga sama ta sāke magana da ni ta ce, “Tafi, ka karɓi naɗaɗɗen littafin da yake a buɗe a hannun mala’ikan da yake tsaye bisa teku da ƙasa.” ");
INSERT INTO hausa_vpl VALUES ("RV10_9","096_10_9","REV","10","9","9","Sai na je wajen mala’ikan na ce masa yă ba ni ƙaramin naɗaɗɗen littafin. Ya ce mini, “Karɓa ka ci. Zai sa cikinka yă yi tsami, amma ‘a bakinka zai zama da zaƙi kamar zuma.’ ” ");
INSERT INTO hausa_vpl VALUES ("RV10_10","096_10_10","REV","10","10","10","Na karɓi ƙaramin naɗaɗɗen littafin daga hannun mala’ikan na kuma ci. Ya yi zaƙi kamar zuma a bakina, amma sa’ad da na cinye, cikina ya yi tsami. ");
INSERT INTO hausa_vpl VALUES ("RV10_11","096_10_11","REV","10","11","11","Sa’an nan aka ce mini, “Dole ne ka sāke yin annabci game da mutane masu yawa, al’ummai, harsuna da kuma sarakuna.” ");
INSERT INTO hausa_vpl VALUES ("RV11_1","096_11_1","REV","11","1","1","Aka ba ni ƙara kamar sandan awo aka kuma ce mini, “Tafi ka auna haikalin Allah da bagaden, ka kuma ƙirga waɗanda suke sujada a can. ");
INSERT INTO hausa_vpl VALUES ("RV11_2","096_11_2","REV","11","2","2","Sai dai kada ka haɗa da harabar waje; kada ka auna ta, domin an ba da ita ga Al’ummai. Za su tattaka birni mai tsarki har watanni 42. ");
INSERT INTO hausa_vpl VALUES ("RV11_3","096_11_3","REV","11","3","3","Zan kuma ba wa shaiduna nan biyu iko, za su kuwa yi annabci na kwanaki 1,260, saye da gwadon makoki.” ");
INSERT INTO hausa_vpl VALUES ("RV11_4","096_11_4","REV","11","4","4","Waɗannan su ne itatuwan zaitun biyu da kuma alkukai biyu da suke tsaye a gaban Ubangijin duniya. ");
INSERT INTO hausa_vpl VALUES ("RV11_5","096_11_5","REV","11","5","5","Duk wanda ya yi ƙoƙari yin musu lahani, wuta za tă fito daga bakunansu ta cinye abokan gābansu. Haka ne duk mai niyyar yin musu lahani zai mutu. ");
INSERT INTO hausa_vpl VALUES ("RV11_6","096_11_6","REV","11","6","6","Waɗannan mutane suna da iko su kulle sararin sama don kada a yi ruwan sama a lokacin da suke annabci; suna kuma da iko su juye ruwaye su zama jini su kuma bugi duniya da kowace irin annoba a duk lokacin da suke so. ");
INSERT INTO hausa_vpl VALUES ("RV11_7","096_11_7","REV","11","7","7","To, da suka gama shaidarsu, dabbar da takan fito daga Abis za tă kai musu hari, tă kuwa sha ƙarfinsu tă kuma kashe su. ");
INSERT INTO hausa_vpl VALUES ("RV11_8","096_11_8","REV","11","8","8","Gawawwakinsu za su kasance a kwance a titin babban birni, wanda a misalce ake kira Sodom da Masar, inda kuma aka gicciye Ubangijinsu. ");
INSERT INTO hausa_vpl VALUES ("RV11_9","096_11_9","REV","11","9","9","Kwana uku da rabi mutane daga kowace jama’a, kabila, harshe da kuma al’umma za su yi ta kallon gawawwakinsu su kuma ƙi binne su. ");
INSERT INTO hausa_vpl VALUES ("RV11_10","096_11_10","REV","11","10","10","Mazaunan duniya za su ƙyaface su kuma yi biki ta wurin aika kyautai wa juna, domin waɗannan annabawan nan biyu ne suka azabtar da mazaunan duniya. ");
INSERT INTO hausa_vpl VALUES ("RV11_11","096_11_11","REV","11","11","11","Amma bayan kwana uku da rabi ɗin numfashin rai daga Allah ya shige su, suka kuwa tashi tsaye, tsoro kuma ya kama waɗanda suka gan su. ");
INSERT INTO hausa_vpl VALUES ("RV11_12","096_11_12","REV","11","12","12","Sai suka ji wata babbar murya daga sama tana ce musu, “Ku hauro nan.” Suka kuwa haura zuwa sama cikin girgije, yayinda abokan gābansu suna kallo. ");
INSERT INTO hausa_vpl VALUES ("RV11_13","096_11_13","REV","11","13","13","A wannan sa’a aka yi wata babbar girgizar ƙasa kashi ɗaya bisa goma kuma na birnin ya rushe. Aka kashe mutane dubu bakwai a girgizar ƙasar, waɗanda suka tsira kuwa suka ji tsoro suka ɗaukaka Allah na sama. ");
INSERT INTO hausa_vpl VALUES ("RV11_14","096_11_14","REV","11","14","14","Kaito na biyu ya wuce; kaito na uku yana zuwa ba da daɗewa ba. ");
INSERT INTO hausa_vpl VALUES ("RV11_15","096_11_15","REV","11","15","15","Mala’ika na bakwai ya busa ƙahonsa, sai aka ji muryoyi masu ƙarfi a sama da suka ce, “Mulkin duniya ya zama mulkin Ubangijinmu da na Kiristinsa, zai kuwa yi mulki har abada abadin.” ");
INSERT INTO hausa_vpl VALUES ("RV11_16","096_11_16","REV","11","16","16","Sai dattawan nan ashirin da huɗu da suke zaune a kursiyoyinsu a gaban Allah, suka fāɗi da fuskokinsu a ƙasa suka kuma yi wa Allah sujada, ");
INSERT INTO hausa_vpl VALUES ("RV11_17","096_11_17","REV","11","17","17","suna cewa, “Muna maka godiya ya Ubangiji Allah, Maɗaukaki, wanda yake a yanzu, shi ne kuma a dā, domin ka karɓi ikonka mai girma ka kuma fara mulki. ");
INSERT INTO hausa_vpl VALUES ("RV11_18","096_11_18","REV","11","18","18","Al’ummai suka yi fushi; fushinka kuwa ya zo. Lokaci ya yi don a shari’anta matattu, da kuma don sākawa wa bayinka annabawa da tsarkakanka da kuma su waɗanda suke girmama sunanka, ƙarami da babba, don kuma hallakar da waɗanda suka hallaka duniya.” ");
INSERT INTO hausa_vpl VALUES ("RV11_19","096_11_19","REV","11","19","19","Sa’an nan aka buɗe haikalin Allah da yake a sama, kuma a cikin haikalinsa aka ga akwatin alkawarinsa. Sai kuwa ga walƙiya, ƙararraki, tsawa, girgizar ƙasa, da kuma ƙanƙara masu girma. ");
INSERT INTO hausa_vpl VALUES ("RV12_1","096_12_1","REV","12","1","1","Babbar alama mai banmamaki ta bayyana a sama, mace tana lulluɓe da rana, da kuma wata a ƙarƙashin sawunta, akwai kuma rawani mai taurari goma sha biyu a kanta. ");
INSERT INTO hausa_vpl VALUES ("RV12_2","096_12_2","REV","12","2","2","Tana da ciki ta kuma yi kuka mai zafi yayinda take gab da haihuwa. ");
INSERT INTO hausa_vpl VALUES ("RV12_3","096_12_3","REV","12","3","3","Sai wata alama ta bayyana a sama, wani babban jan maciji mai kawuna bakwai da ƙahoni goma da rawani bakwai a kan kawunansa. ");
INSERT INTO hausa_vpl VALUES ("RV12_4","096_12_4","REV","12","4","4","Wutsiyarsa ta share kashi ɗaya bisa uku na taurari daga sararin sama ta kuma zubar da su ƙasa. Ƙaton jan macijin ya tsaya a gaban macen wadda take gab da haihuwa, don yă cinye ɗanta nan take bayan an haife shi. ");
INSERT INTO hausa_vpl VALUES ("RV12_5","096_12_5","REV","12","5","5","Ta haifi ɗa, namiji, wanda zai yi mulkin dukan al’ummai da sandar ƙarfe. Aka fyauce ɗanta zuwa wurin Allah da kuma kursiyinsa. ");
INSERT INTO hausa_vpl VALUES ("RV12_6","096_12_6","REV","12","6","6","Sai macen ta gudu zuwa hamada zuwa inda Allah ya shirya dominta, inda za a lura da ita har kwana 1,260. ");
INSERT INTO hausa_vpl VALUES ("RV12_7","096_12_7","REV","12","7","7","Aka kuwa yi yaƙi a sama. Mika’ilu da mala’ikunsa yaƙi macijin, maciji da mala’ikunsa su ma suka mai da martani. ");
INSERT INTO hausa_vpl VALUES ("RV12_8","096_12_8","REV","12","8","8","Amma macijin nan ba shi da isashen ƙarfi, har suka rasa matsayinsu a sama. ");
INSERT INTO hausa_vpl VALUES ("RV12_9","096_12_9","REV","12","9","9","Aka jefar da ƙaton jan macijin ƙasa, tsohon maciji nan da ake kira Iblis, ko Shaiɗan, wanda ya ɓad da dukan duniya. Aka jefar da shi ƙasa, tare da mala’ikunsa a duniya. ");
INSERT INTO hausa_vpl VALUES ("RV12_10","096_12_10","REV","12","10","10","Sa’an nan na ji babbar murya daga sama tana cewa, “Yanzu ceto da iko da mulkin Allahnmu, da kuma ikon Kiristinsa. Gama mai zargin ’yan’uwanmu, wanda yake zarginsu a gaban Allahnmu dare da rana, an jefar da shi ƙasa. ");
INSERT INTO hausa_vpl VALUES ("RV12_11","096_12_11","REV","12","11","11","Sun ci nasara a kansa ta wurin jinin Ɗan Ragon da ta wurin kalmar shaidarsu; ba su ƙaunaci rayukansu sosai har da za su ja da baya daga mutuwa. ");
INSERT INTO hausa_vpl VALUES ("RV12_12","096_12_12","REV","12","12","12","Saboda haka ku yi farin ciki, ku sammai, da ku da kuke zaune a cikinsu! Amma kaiton duniya da kuma teku, gama Iblis ya sauko gare ku! Ya cika da fushi, domin ya san cewa lokacinsa ya rage kaɗan.” ");
INSERT INTO hausa_vpl VALUES ("RV12_13","096_12_13","REV","12","13","13","Sa’ad da macijin ya ga an jefar da shi a duniya, sai ya fafari macen nan da ta haifi ɗa namiji. ");
INSERT INTO hausa_vpl VALUES ("RV12_14","096_12_14","REV","12","14","14","Sai aka ba wa macen fikafikai biyu na babban gaggafa, don ta tashi sama zuwa inda aka shirya mata a hamada, inda za a lura da ita na ɗan lokaci, lokuta da rabin lokaci, inda macijin ba zai iya kaiwa ba. ");
INSERT INTO hausa_vpl VALUES ("RV12_15","096_12_15","REV","12","15","15","Sa’an nan daga bakinsa macijin ya kwarara ruwa kamar kogi, don ruwan ya cimma matan yă kuma kwashe ta tare da ambaliya. ");
INSERT INTO hausa_vpl VALUES ("RV12_16","096_12_16","REV","12","16","16","Amma ƙasa ta taimaki macen ta wurin buɗe bakinta ta kuma shanye ruwan kogin da macijin ya kwarara daga bakinsa. ");
INSERT INTO hausa_vpl VALUES ("RV12_17","096_12_17","REV","12","17","17","Sai macijin ya yi fushi da macen ya kuma koma wajen sauran zuriyarta don yă yaƙe su waɗannan waɗanda suke biyayya da umarnan Allah suke kuma riƙe da shaidar Yesu. ");
INSERT INTO hausa_vpl VALUES ("RV13_1","096_13_1","REV","13","1","1","Macijin kuwa ya tsaya a bakin teku. Sai na ga wata dabba tana fitowa daga teku. Tana da ƙahoni goma da kawuna bakwai, da kuma rawani goma a ƙahoninta, a kowane kai kuwa akwai sunan saɓo. ");
INSERT INTO hausa_vpl VALUES ("RV13_2","096_13_2","REV","13","2","2","Dabbar da na gani ta yi kamar damisa, amma tana da ƙafafu kamar na beyar, bakinta kuma ya yi kamar na zaki. Macijin nan ya ba wa dabbar ƙarfinsa da gadon sarautarsa da kuma ikonsa mai girma. ");
INSERT INTO hausa_vpl VALUES ("RV13_3","096_13_3","REV","13","3","3","Ɗaya daga cikin kawunan dabbar ya yi kamar yana da raunin da zai iya kashe shi, amma raunin nan da zai iya kashe shi ya riga ya warke. Dukan duniya ta yi mamaki ta kuma bi dabbar. ");
INSERT INTO hausa_vpl VALUES ("RV13_4","096_13_4","REV","13","4","4","Mutane suka yi wa macijin sujada domin ya ba wa dabbar ikonsa, suka yi wa dabbar sujada, suka kuma yi tambaya cewa, “Wane ne yake kama da dabban nan? Wa zai iya yaƙe ta?” ");
INSERT INTO hausa_vpl VALUES ("RV13_5","096_13_5","REV","13","5","5","Aka ba wa dabbar baki don ta faɗi kalmomin girman kai da na saɓo ta kuma yi amfani da ikonta har watanni arba’in da biyu. ");
INSERT INTO hausa_vpl VALUES ("RV13_6","096_13_6","REV","13","6","6","Ta buɗe bakinta don tă yi wa Allah saɓo, ta kuma ɓata sunansa da kuma mazauninsa da na waɗanda suke zama a sama. ");
INSERT INTO hausa_vpl VALUES ("RV13_7","096_13_7","REV","13","7","7","Aka ba ta iko tă yaƙi tsarkaka tă kuma ci nasara a kansu. Aka kuma ba ta iko bisa kowace kabila, jama’a, harshe da kuma al’umma. ");
INSERT INTO hausa_vpl VALUES ("RV13_8","096_13_8","REV","13","8","8","Dukan mazaunan duniya za su yi wa dabbar sujada, dukan waɗanda ba a rubuta sunayensu a cikin littafin ran da yake na Ɗan Ragon da aka yanka tun kafin halittar duniya ba. ");
INSERT INTO hausa_vpl VALUES ("RV13_9","096_13_9","REV","13","9","9","Duk mai kunne ji, bari yă ji. ");
INSERT INTO hausa_vpl VALUES ("RV13_10","096_13_10","REV","13","10","10","Duk wanda aka ƙaddara ga bauta, ga bauta zai tafi. Duk wanda aka ƙaddara za a kashe da takobi, da takobin za a kashe shi. Wannan yana bukata haƙuri da aminci a gefen tsarkaka. ");
INSERT INTO hausa_vpl VALUES ("RV13_11","096_13_11","REV","13","11","11","Sai na ga wata dabba tana fitowa daga ƙasa. Tana da ƙahoni biyu kamar ɗan rago, amma ta yi magana kamar maciji. ");
INSERT INTO hausa_vpl VALUES ("RV13_12","096_13_12","REV","13","12","12","Ta mori dukan ikon dabban nan ta fari a madadinta, ta sa duniya da mazaunanta su yi wa dabba ta farin nan sujada, wadda aka warkar mata da raunin nan da zai iya kashe ta. ");
INSERT INTO hausa_vpl VALUES ("RV13_13","096_13_13","REV","13","13","13","Ta kuma yi manyan ayyuka da kuma alamu masu banmamaki, har ta sa wuta ta sauko daga sama zuwa ƙasa a gaban idon mutane. ");
INSERT INTO hausa_vpl VALUES ("RV13_14","096_13_14","REV","13","14","14","Saboda alamun nan da aka ba ta iko tă yi a madadin dabban nan ta fari, sai ta ruɗi mazaunan duniya. Ta umarce su su kafa siffa don girmama dabbar da aka ji mata rauni da takobi duk da haka ta rayu. ");
INSERT INTO hausa_vpl VALUES ("RV13_15","096_13_15","REV","13","15","15","Aka ba ta iko tă ba da numfashi ga siffar dabban nan ta fari, don tă yi magana tă kuma sa a kashe duk waɗanda suka ƙi yi wa siffar sujada. ");
INSERT INTO hausa_vpl VALUES ("RV13_16","096_13_16","REV","13","16","16","Ta kuma tilasta wa kowa, manya da yara, mawadata da matalauta, ’yantattu da bayi, don a yi musu alama a hannun dama ko a goshi, ");
INSERT INTO hausa_vpl VALUES ("RV13_17","096_13_17","REV","13","17","17","don kada kowa yă saya ko yă sayar, sai dai yana da alamar, wadda take sunan dabbar ko kuma lambar sunanta. ");
INSERT INTO hausa_vpl VALUES ("RV13_18","096_13_18","REV","13","18","18","Wannan yana bukata hikima. Duk mai hankali, sai yă lissafta lambar dabbar, gama lamban nan ta mutum ne. Lambarta kuwa ita ce 666. ");
INSERT INTO hausa_vpl VALUES ("RV14_1","096_14_1","REV","14","1","1","Sai na duba, can a gabana kuwa ga Ɗan Rago, tsaye a kan Dutsen Sihiyona, tare da shi akwai kuma mutane 144,000 waɗanda suke da sunansa da sunan Ubansa a rubuce a goshinsu. ");
INSERT INTO hausa_vpl VALUES ("RV14_2","096_14_2","REV","14","2","2","Sai na ji ƙara daga sama kamar motsin ruwaye masu gudu, kamar kuma tsawa. Ƙarar da na ji ta yi kamar ta masu garaya da suke kiɗin garayarsu. ");
INSERT INTO hausa_vpl VALUES ("RV14_3","096_14_3","REV","14","3","3","Suka kuwa rera sabuwar waƙa a gaban kursiyin da kuma a gaban halittu huɗun nan masu rai, da kuma a gaban dattawa. Ba wanda ya iya koyon waƙar sai mutanen nan 144,000 da aka fansa daga duniya. ");
INSERT INTO hausa_vpl VALUES ("RV14_4","096_14_4","REV","14","4","4","Waɗannan su ne waɗanda ba su ƙazantar da kansu da mata ba, gama sun kiyaye kansu da tsarki. Suna bin Ɗan Ragon duk inda ya tafi. Su ne aka saya daga cikin mutane aka kuwa miƙa su kamar ’ya’yan fari ga Allah da kuma Ɗan Ragon. ");
INSERT INTO hausa_vpl VALUES ("RV14_5","096_14_5","REV","14","5","5","Ba a sami ƙarya a bakunansu ba; su kuma marasa aibi ne. ");
INSERT INTO hausa_vpl VALUES ("RV14_6","096_14_6","REV","14","6","6","Sai na ga wani mala’ika yana tashi sama a tsakiyar sararin sama, yana kuma da madawwamiyar bishara wadda zai yi shela ga waɗanda suke zama a duniya, ga kowace al’umma, kabila, harshe, da kuma jama’a. ");
INSERT INTO hausa_vpl VALUES ("RV14_7","096_14_7","REV","14","7","7","Ya ce da babbar murya, “Ku ji tsoron Allah ku kuma ɗaukaka shi, domin sa’ar hukuncinsa ya yi. Ku yi wa wannan da ya halicci sammai, ƙasa, teku, da maɓulɓulan ruwa sujada.” ");
INSERT INTO hausa_vpl VALUES ("RV14_8","096_14_8","REV","14","8","8","Mala’ika na biyu ya biyo yana cewa, “Ta fāɗi! Babilon Mai Girma ta fāɗi, wadda ta sa dukan al’ummai suka sha ruwan inabin hauka na zinanta.” ");
INSERT INTO hausa_vpl VALUES ("RV14_9","096_14_9","REV","14","9","9","Mala’ika na uku ya biyo su ya ce da babbar murya, “Duk wanda ya yi wa dabban nan da siffarta sujada ya kuma sami alamarta a goshi ko a hannu, ");
INSERT INTO hausa_vpl VALUES ("RV14_10","096_14_10","REV","14","10","10","shi ma zai sha ruwan inabin fushin Allah, wanda aka zuba da duk ƙarfinsa a kwaf fushinsa. Za a ba shi azaba da farar wuta mai ci a gaban tsarkakan mala’iku da na Ɗan Ragon. ");
INSERT INTO hausa_vpl VALUES ("RV14_11","096_14_11","REV","14","11","11","Hayaƙin azabarsu kuwa zai dinga tashi har abada abadin. Kuma babu hutu dare ko rana wa waɗanda suke wa dabbar da siffarta sujada, ko kuwa ga duk wanda ya sami alamar sunanta.” ");
INSERT INTO hausa_vpl VALUES ("RV14_12","096_14_12","REV","14","12","12","Wannan yana bukata haƙuri, a gefen tsarkakan da suke biyayya da umarnan Allah suka kuma kasance da aminci ga Yesu. ");
INSERT INTO hausa_vpl VALUES ("RV14_13","096_14_13","REV","14","13","13","Sai na ji murya daga sama ta ce, “Rubuta, Masu albarka ne matattun da suka mutu cikin Ubangiji daga yanzu zuwa gaba.” “I, za su huta daga faman aikinsu, gama ayyukansu za su bi su,” in ji Ruhu. ");
INSERT INTO hausa_vpl VALUES ("RV14_14","096_14_14","REV","14","14","14","Na duba, can gabana kuwa ga farin girgije, zaune kuma a kan girgijen kuwa ga wani da ya yi kamar “ɗan mutum” tare da rawanin zinariya a kansa da kuma lauje mai kaifi a hannunsa. ");
INSERT INTO hausa_vpl VALUES ("RV14_15","096_14_15","REV","14","15","15","Sai wani mala’ika ya fito daga haikali ya kuma yi kira da babbar murya ga wannan mai zaune a kan girgijen ya ce, “Ɗauki laujenka ka yi girbi, domin lokacin girbi ya yi, gama amfanin da yake duniya ya nuna.” ");
INSERT INTO hausa_vpl VALUES ("RV14_16","096_14_16","REV","14","16","16","Sai wannan mai zaune a girgijen ya wurga laujensa a duniya, sai aka kuwa girbe duniya. ");
INSERT INTO hausa_vpl VALUES ("RV14_17","096_14_17","REV","14","17","17","Wani mala’ika kuma ya fito daga haikali a sama, shi ma yana da lauje mai kaifi. ");
INSERT INTO hausa_vpl VALUES ("RV14_18","096_14_18","REV","14","18","18","Har yanzu, wani mala’ika mai lura da wuta, ya fito daga bagaden ya yi kira da babbar murya ga wannan wanda yake da lauje mai kaifi ya ce, “Ɗauki laujenka mai kaifi ka tattara kawunan ’ya’yan inabi daga kuringar inabin duniya, domin ’ya’yan inabin sun nuna.” ");
INSERT INTO hausa_vpl VALUES ("RV14_19","096_14_19","REV","14","19","19","Mala’ikan ya wurga laujensa a duniya, ya tattara ’ya’yan inabin, ya kuma zuba su cikin babbar wurin matsewar inabin fushin Allah. ");
INSERT INTO hausa_vpl VALUES ("RV14_20","096_14_20","REV","14","20","20","Aka tattake su a wurin matsin inabi a bayan gari, jini kuwa ya yi ta gudana daga wurin matsin inabi tsayinsa ya kai kamar tsawon linzami a bakin doki, nisansa kuma ya kai wajen kilomita 300. ");
INSERT INTO hausa_vpl VALUES ("RV15_1","096_15_1","REV","15","1","1","Na ga wata babbar alama mai banmamaki a sama, mala’iku bakwai da annobai bakwai na ƙarshe, na ƙarshe, domin da su ne fushin Allah ya cika. ");
INSERT INTO hausa_vpl VALUES ("RV15_2","096_15_2","REV","15","2","2","Sai na ga abin da ya yi kamar tekun gilashi gauraye da wuta kuma tsaye kusa da teku, waɗanda suka ci nasara bisan dabbar da siffarta da bisan lambar sunanta. Suna riƙe da garayu waɗanda Allah ya ba su ");
INSERT INTO hausa_vpl VALUES ("RV15_3","096_15_3","REV","15","3","3","suka rera waƙar Musa bawan Allah da kuma waƙar Ɗan Ragon suna cewa, “Ayyukanka suna da girma da kuma banmamaki, ya Ubangiji Maɗaukaki. Al’amuranka suna da aminci da kuma gaskiya, ya Sarkin zamanai. ");
INSERT INTO hausa_vpl VALUES ("RV15_4","096_15_4","REV","15","4","4","Wane ne ba zai ji tsoronka, yă kuma kawo ɗaukaka ga sunanka ba, ya Ubangiji? Gama kai kaɗai ne mai tsarki. Dukan al’ummai za su zo su yi sujada a gabanka, gama an bayyana ayyukan adalcinka.” ");
INSERT INTO hausa_vpl VALUES ("RV15_5","096_15_5","REV","15","5","5","Bayan wannan sai na duba, a cikin sama kuwa sai ga haikali, wato, tabanakul na Shaida, a buɗe. ");
INSERT INTO hausa_vpl VALUES ("RV15_6","096_15_6","REV","15","6","6","Daga cikin haikalin mala’iku bakwai tare da annobai bakwai suka fito. Suna saye da tufafin lilin masu tsabta masu walƙiya, suna kuma saye da ɗamarar zinariya a ƙirjinsu. ");
INSERT INTO hausa_vpl VALUES ("RV15_7","096_15_7","REV","15","7","7","Sai ɗaya daga cikin halittu huɗun nan masu rai, ya ba wa mala’iku bakwai nan kwanonin zinariya bakwai cike da fushin Allah, wanda yake raye har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("RV15_8","096_15_8","REV","15","8","8","Aka kuma cika haikalin da hayaƙi daga ɗaukakar Allah da kuma daga ikonsa, kuma ba wanda ya iya shiga haikalin sai da aka cika annobai bakwai nan na mala’iku bakwai. ");
INSERT INTO hausa_vpl VALUES ("RV16_1","096_16_1","REV","16","1","1","Sai na ji wata babbar murya daga haikalin tana ce wa mala’iku bakwai nan, “Ku tafi ku zuba kwanoni bakwai nan na fushin Allah a kan duniya.” ");
INSERT INTO hausa_vpl VALUES ("RV16_2","096_16_2","REV","16","2","2","Mala’ika na fari ya je ya juye kwanonsa a bisan ƙasa, sai munanan gyambuna masu zafi suka fito a jikin mutanen da suke da alamar dabbar suka kuma yi wa siffarta sujada. ");
INSERT INTO hausa_vpl VALUES ("RV16_3","096_16_3","REV","16","3","3","Mala’ika na biyu ya juye kwanonsa a bisan teku, sai tekun ya zama jini kamar na mataccen mutum, kuma kowane abu mai rai da yake cikin tekun ya mutu. ");
INSERT INTO hausa_vpl VALUES ("RV16_4","096_16_4","REV","16","4","4","Mala’ika na uku ya juye kwanonsa a bisan koguna da maɓulɓulan ruwa, sai suka zama jini. ");
INSERT INTO hausa_vpl VALUES ("RV16_5","096_16_5","REV","16","5","5","Sa’an nan na ji mala’ikan da yake lura da ruwaye ya ce, “Kai mai adalci ne cikin waɗannan hukuntai, kai da kake yanzu, kake kuma a dā, Mai Tsarki, saboda yadda ka yi hukuncin nan; ");
INSERT INTO hausa_vpl VALUES ("RV16_6","096_16_6","REV","16","6","6","gama sun zub da jinin tsarkakanka da kuma annabawanka, ka kuwa ba su jini su sha, yadda ya dace da su.” ");
INSERT INTO hausa_vpl VALUES ("RV16_7","096_16_7","REV","16","7","7","Na kuma ji bagaden ya amsa, “I, Ubangiji Allah, Maɗaukaki, hukuntanka daidai yake na adalci ne kuma.” ");
INSERT INTO hausa_vpl VALUES ("RV16_8","096_16_8","REV","16","8","8","Mala’ika na huɗu ya juye kwanonsa a bisan rana, sai aka ba wa rana iko ta ƙona mutane da wuta. ");
INSERT INTO hausa_vpl VALUES ("RV16_9","096_16_9","REV","16","9","9","Aka ƙone su da zafin wuta mai tsanani suka kuwa la’anci sunan Allah wanda yake da iko a kan waɗannan annoban, amma suka ƙi su tuba su kuma ɗaukaka shi. ");
INSERT INTO hausa_vpl VALUES ("RV16_10","096_16_10","REV","16","10","10","Mala’ika na biyar ya juye kwanonsa a bisan gadon sarautar dabbar, mulkinta kuwa ya zama duhu. Mutane suka yi ta cizon bakinsu saboda azaba ");
INSERT INTO hausa_vpl VALUES ("RV16_11","096_16_11","REV","16","11","11","suka kuma la’anci Allah na sama saboda zafinsu, da kuma saboda gyambunansu, amma suka ƙi su tuba daga abin da suka riga suka yi. ");
INSERT INTO hausa_vpl VALUES ("RV16_12","096_16_12","REV","16","12","12","Mala’ika na shida ya juye kwanonsa a bisan babban kogin Yuferites, sai ruwansa ya shanye don a shirya hanya saboda sarakuna daga Gabas. ");
INSERT INTO hausa_vpl VALUES ("RV16_13","096_16_13","REV","16","13","13","Sa’an nan na ga mugayen ruhohi guda uku da suka yi kamar kwaɗi; suka fito daga bakin macijin nan, da kuma daga bakin dabbar, da kuma daga bakin annabin ƙaryan nan. ");
INSERT INTO hausa_vpl VALUES ("RV16_14","096_16_14","REV","16","14","14","Su ruhohin aljanu ne da suke aikata abubuwan banmamaki, sukan je wurin sarakunan dukan duniya, don su tattara su don yaƙi a babbar ranar Allah Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("RV16_15","096_16_15","REV","16","15","15","“Ga shi, ina zuwa kamar ɓarawo! Mai albarka ne wanda yake zama a faɗake yana kuma saye da tufafinsa, don kada yă yi tafiya tsirara a kuma kunyata shi.” ");
INSERT INTO hausa_vpl VALUES ("RV16_16","096_16_16","REV","16","16","16","Sa’an nan aka tattara sarakuna zuwa wurin da a Ibraniyanci ake kira Armageddon. ");
INSERT INTO hausa_vpl VALUES ("RV16_17","096_16_17","REV","16","17","17","Mala’ika na bakwai ya juye kwanonsa cikin iska, daga haikalin kuwa sai aka ji wata babbar murya daga kursiyin, tana cewa, “An gama!” ");
INSERT INTO hausa_vpl VALUES ("RV16_18","096_16_18","REV","16","18","18","Sai ga walƙiya, ƙararraki, tsawa da kuma matsananciyar girgizar ƙasa. Ba a taɓa yin irin wannan girgizar ƙasar ba, tun kasancewar mutum a duniya, girgizar ƙasar kuwa gawurtacciya ce. ");
INSERT INTO hausa_vpl VALUES ("RV16_19","096_16_19","REV","16","19","19","Babban birnin ya rabu kashi uku, biranen al’ummai kuma suka rurrushe. Allah ya tuna da Babilon Mai Girma ya kuma ba ta kwaf cike da ruwan inabin fushinsa. ");
INSERT INTO hausa_vpl VALUES ("RV16_20","096_16_20","REV","16","20","20","Kowane tsibiri ya gudu ba a kuwa ƙara ganin duwatsu ba. ");
INSERT INTO hausa_vpl VALUES ("RV16_21","096_16_21","REV","16","21","21","Daga sararin sama manyan ƙanƙara masu nauyin gaske suka fāɗo a kan mutane. Suka kuma la’anci Allah saboda annobar ƙanƙarar, domin annobar ta yi muni ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("RV17_1","096_17_1","REV","17","1","1","Ɗaya daga cikin mala’iku bakwai masu ɗauke da kwanoni bakwai nan, ya zo ya ce mini, “Zo, zan nuna maka hukuncin babbar karuwan nan da take zaune a bisan ruwaye masu yawa. ");
INSERT INTO hausa_vpl VALUES ("RV17_2","096_17_2","REV","17","2","2","Da ita ce sarakunan duniya suka yi zina mazaunan duniya kuma suka bugu da ruwan inabin zinace zinacenta.” ");
INSERT INTO hausa_vpl VALUES ("RV17_3","096_17_3","REV","17","3","3","Sa’an nan mala’ikan ya ɗauke ni cikin Ruhu zuwa hamada. A can na ga mace zaune a kan wata jan dabbar da aka rufe da sunayen saɓo tana kuma da kawuna bakwai da ƙahoni goma. ");
INSERT INTO hausa_vpl VALUES ("RV17_4","096_17_4","REV","17","4","4","Macen tana saye da tufafi masu ruwan ja da shunayya, tana ƙyalli da zinariya, duwatsu masu daraja da kuma lu’ulu’ai. Tana riƙe da kwaf na zinariya a hannunta, cike da abubuwa masu banƙyama da kuma ƙazantar zinace zinacenta. ");
INSERT INTO hausa_vpl VALUES ("RV17_5","096_17_5","REV","17","5","5","Sunan da aka rubuta a goshinta asiri ne, Babilon mai girma mahaifiyar karuwai da kuma na abubuwa masu banƙyama na duniya. ");
INSERT INTO hausa_vpl VALUES ("RV17_6","096_17_6","REV","17","6","6","Na ga cewa macen ta bugu da jinin tsarkaka, jinin waɗanda suka shaida Yesu. Da na gan ta, sai na yi mamaki ƙwarai. ");
INSERT INTO hausa_vpl VALUES ("RV17_7","096_17_7","REV","17","7","7","Sa’an nan mala’ikan ya ce mini, “Don me kake mamaki? Zan bayyana maka asirin macen nan da dabbar da take hawa, wadda take da kawuna bakwai da ƙahoni goma. ");
INSERT INTO hausa_vpl VALUES ("RV17_8","096_17_8","REV","17","8","8","Dabbar da ka gani, a dā ta taɓa kasancewa, a yanzu, ba ta, za tă kuma fito daga Abis zuwa ga hallakarta. Mazaunan duniya waɗanda ba a rubuta sunayensu a littafin rai tun kafin halittar duniya ba za su yi mamaki sa’ad da suka ga dabbar, domin a dā ta taɓa kasancewa, yanzu kuwa ba ta, duk da haka za tă dawo. ");
INSERT INTO hausa_vpl VALUES ("RV17_9","096_17_9","REV","17","9","9","“Wannan yana bukata hankali da kuma hikima. Kawuna bakwai nan tuddai bakwai ne da macen take zama a kai. ");
INSERT INTO hausa_vpl VALUES ("RV17_10","096_17_10","REV","17","10","10","Sarakuna bakwai ne kuma. Biyar sun fāɗi, ɗaya yana nan, ɗayan kuma bai zo ba tukuna; amma sa’ad da ya zo, zai kasance na ɗan lokaci. ");
INSERT INTO hausa_vpl VALUES ("RV17_11","096_17_11","REV","17","11","11","Dabbar da a dā ta taɓa kasancewa, amma yanzu ba ta, ita ce sarki na takwas. Ita ɗaya ce cikin bakwai ɗin, kuma tana tafiya zuwa ga hallakarta. ");
INSERT INTO hausa_vpl VALUES ("RV17_12","096_17_12","REV","17","12","12","“Ƙahonin nan goma da ka gani sarakuna goma ne da ba su riga sun karɓi mulki ba, amma waɗanda na sa’a guda za su karɓi iko a matsayin sarakuna tare da dabbar. ");
INSERT INTO hausa_vpl VALUES ("RV17_13","096_17_13","REV","17","13","13","Suna da manufa guda za su kuma ba wa dabbar ikonsu da kuma sarautarsu. ");
INSERT INTO hausa_vpl VALUES ("RV17_14","096_17_14","REV","17","14","14","Za su yi yaƙi da Ɗan Ragon, sai dai Ɗan Ragon zai ci nasara a bisansu domin shi ne Ubangijin iyayengiji, Sarkin sarakuna, tare da shi kuwa kirayayunsa, zaɓaɓɓunsa da kuma amintattu masu binsa za su kasance.” ");
INSERT INTO hausa_vpl VALUES ("RV17_15","096_17_15","REV","17","15","15","Sa’an nan mala’ikan ya ce mini, “Ruwayen da ka gani, inda karuwan take zama, jama’a ce, taro masu yawa, al’ummai da kuma harsuna. ");
INSERT INTO hausa_vpl VALUES ("RV17_16","096_17_16","REV","17","16","16","Dabbar da kuma ƙahoni goma da ka gani za su ƙi jinin karuwar. Za su kai ta ga hallaka su kuma bar ta tsirara; za su ci namanta su kuma ƙone ta da wuta. ");
INSERT INTO hausa_vpl VALUES ("RV17_17","096_17_17","REV","17","17","17","Gama Allah ya sa a zukatansu su cika nufinsa ta wurin yarda su ba wa dabbar ikonsu tă yi mulki, sai lokacin da kalmomin Allah sun cika. ");
INSERT INTO hausa_vpl VALUES ("RV17_18","096_17_18","REV","17","18","18","Macen da ka gani ita ce babban birnin da yake mulki a bisan sarakunan duniya.” ");
INSERT INTO hausa_vpl VALUES ("RV18_1","096_18_1","REV","18","1","1","Bayan wannan sai na ga wani mala’ika yana saukowa daga sama. Yana da iko mai girma, aka haskaka duniya da darajarsa. ");
INSERT INTO hausa_vpl VALUES ("RV18_2","096_18_2","REV","18","2","2","Ya yi kira da babbar murya ya ce, “Ta fāɗi! Babilon Mai Girma ta fāɗi. Ta zama gidan aljanu da kuma wurin zaman kowace irin mugun ruhu, wurin zaman kowane irin tsuntsu marar tsabta da mai banƙyama. ");
INSERT INTO hausa_vpl VALUES ("RV18_3","096_18_3","REV","18","3","3","Gama dukan al’ummai sun sha ruwan inabin haukan zinace zinacenta. Sarakunan duniya sun yi zina tare da ita, attajiran duniya kuma sun arzuta da almubazzarancinta.” ");
INSERT INTO hausa_vpl VALUES ("RV18_4","096_18_4","REV","18","4","4","Sai na ji wata murya daga sama ta ce, “Ku fita daga cikinta, mutanena, don kada zunubanta su shafe ku, don kada wata annobarta ta same ku; ");
INSERT INTO hausa_vpl VALUES ("RV18_5","096_18_5","REV","18","5","5","gama zunubanta sun yi tsororuwa sun kai sama. Allah kuma ya tuna da laifofinta. ");
INSERT INTO hausa_vpl VALUES ("RV18_6","096_18_6","REV","18","6","6","Ku sāka mata kamar yadda ta sāka muku; ku sāka mata sau biyu na abin da ta yi. Ku dama mata sau biyu na abin da yake cikin kwaf nata. ");
INSERT INTO hausa_vpl VALUES ("RV18_7","096_18_7","REV","18","7","7","Ku ba ta isashen azaba da baƙin ciki kamar daraja da kuma jin daɗin da ta ba wa kanta. A zuciyarta takan yi taƙama, ta ce, ‘Ina zama kamar sarauniya; ni ba gwauruwa ba ce, kuma ba zan taɓa yin makoki ba.’ ");
INSERT INTO hausa_vpl VALUES ("RV18_8","096_18_8","REV","18","8","8","Saboda haka a rana ɗaya annobarta za su cim mata, mutuwa, makoki da kuma yunwa. Wuta zai cinye ta, gama Ubangiji Allah mai girma ne, wanda yake shari’anta ta. ");
INSERT INTO hausa_vpl VALUES ("RV18_9","096_18_9","REV","18","9","9","“Sa’ad da sarakunan duniya da suka yi zina da ita suka kuma yi tarayya cikin jin daɗinta suka ga hayaƙin ƙunarta, za su yi kuka da makoki saboda ita. ");
INSERT INTO hausa_vpl VALUES ("RV18_10","096_18_10","REV","18","10","10","Don tsoron ganin azabarta za su tsaya daga nesa, su yi kuka suna cewa, “ ‘Kaito! Kaito, ya birni mai girma. Ya ke Babilon, birni mai iko! Cikin sa’a guda hallakarki ta zo!’ ");
INSERT INTO hausa_vpl VALUES ("RV18_11","096_18_11","REV","18","11","11","“Attajiran duniya za su yi kuka su kuma yi makoki a kanta, domin ba wanda yake ƙara sayen kayayyakinsu ");
INSERT INTO hausa_vpl VALUES ("RV18_12","096_18_12","REV","18","12","12","kayayyakin zinariya, azurfa, duwatsu masu daraja da lu’ulu’ai; lallausan lilin, tufa masu ruwan shunayya, siliki da jan tufa; da kowane irin katakai masu ƙanshi da kayayyaki na kowane iri da aka yi da hauren giwa, katakai masu tsada, tagulla, baƙin ƙarfe da dutse mai sheƙi; ");
INSERT INTO hausa_vpl VALUES ("RV18_13","096_18_13","REV","18","13","13","kayayyakin sinnamon da kayan yaji, na turaren wuta, mur da turare, na ruwan inabi da man zaitun, na gari mai laushi da alkama; shanu da tumaki; dawakai da kekunan doki, da jikuna da kuma rayukan mutane. ");
INSERT INTO hausa_vpl VALUES ("RV18_14","096_18_14","REV","18","14","14","“Za su ce, ‘Amfanin da kike marmari ya kuɓuce. Dukan arzikinki da darajarki sun ɓace, ba kuwa za a ƙara samunsu ba.’ ");
INSERT INTO hausa_vpl VALUES ("RV18_15","096_18_15","REV","18","15","15","Attajiran da suka sayar da waɗannan kayayyaki suka kuma sami arzikinsu daga gare ta za su tsaya daga nesa, cike da tsoron ganin azabarta. Za su yi kuka da makoki ");
INSERT INTO hausa_vpl VALUES ("RV18_16","096_18_16","REV","18","16","16","su ce, “ ‘Kaito! Kaito, ya birni mai girma, saye da lallausan lilin, shunayya da kuma ja, mai walƙiya da zinariya, duwatsu masu daraja da kuma lu’ulu’ai! ");
INSERT INTO hausa_vpl VALUES ("RV18_17","096_18_17","REV","18","17","17","Cikin sa’a guda irin wannan dukiya mai yawa ta hallaka!’ “Duk matuƙan jirgin ruwa, da dukan waɗanda suke tafiya a jirgin ruwa, ma’aikatanta, da duk masu samun abin zama gari daga teku za su tsaya daga nesa. ");
INSERT INTO hausa_vpl VALUES ("RV18_18","096_18_18","REV","18","18","18","Sa’ad da suka ga hayaƙin ƙunarta, za su yi ihu su ce, ‘An taɓa samun birni kamar wannan babban birnin kuwa?’ ");
INSERT INTO hausa_vpl VALUES ("RV18_19","096_18_19","REV","18","19","19","Za su zuba ƙura a kawunansu, da kuka da makoki za su yi ta kururuwa, “ ‘Kaito! Kaito, ya birni mai girma, inda dukan waɗanda suke da jiragen ruwa a teku suka arzuta da ɗumbun dukiyarsa! Cikin sa’a ɗaya ta hallaka!’ ");
INSERT INTO hausa_vpl VALUES ("RV18_20","096_18_20","REV","18","20","20","“Ki yi murna a kanta, ya sama! Ku yi murna, ku tsarkaka! Ku yi murna, ku manzanni da annabawa! Allah ya hukunta shi saboda abin da ya yi muku.” ");
INSERT INTO hausa_vpl VALUES ("RV18_21","096_18_21","REV","18","21","21","Sa’an nan wani mala’ika mai ƙarfi ya ɗauki dutse kamar girman babban dutsen niƙa ya jefa cikin teku ya ce, “Da wannan irin giggitawa za a jefar da birnin Babilon mai girma ƙasa, ba za a ƙara ganin ta ba. ");
INSERT INTO hausa_vpl VALUES ("RV18_22","096_18_22","REV","18","22","22","Ba za a ƙara jin ƙarar kiɗin masu garaya da muryar mawaƙa, da na masu bushe-bushe, da na masu busan ƙaho a cikinki ba. Ba za a ƙara samun ma’aikaci na kowace irin sana’a a cikinki kuma ba. Ba za a ƙara jin ƙarar dutsen niƙa a cikinki kuma ba. ");
INSERT INTO hausa_vpl VALUES ("RV18_23","096_18_23","REV","18","23","23","Hasken fitila ba zai ƙara haskakawa a cikinki ba. Ba za a ƙara jin muryar ango da amarya a cikinki ba. Attajiranki, dā su ne manyan mutanen duniya. Ta wurin sihirinki, dukan ƙasashe sun kauce. ");
INSERT INTO hausa_vpl VALUES ("RV18_24","096_18_24","REV","18","24","24","A cikinta aka sami jinin annabawa, da na tsarkaka, da kuma na dukan waɗanda aka kashe a duniya.” ");
INSERT INTO hausa_vpl VALUES ("RV19_1","096_19_1","REV","19","1","1","Bayan wannan sai na ji abin da ya yi kamar ƙasaitaccen taron mutane a sama, suna cewa, “Halleluya! Ceto da ɗaukaka da iko sun tabbata ga Allahnmu, ");
INSERT INTO hausa_vpl VALUES ("RV19_2","096_19_2","REV","19","2","2","gama hukuncinsa daidai ne, mai adalci kuma. Ya hukunta babbar karuwan nan wadda ta ɓata duniya da zinace zinacenta. Ya rama jinin bayinsa a kanta.” ");
INSERT INTO hausa_vpl VALUES ("RV19_3","096_19_3","REV","19","3","3","Suka sāke tā da murya suka ce, “Halleluya! Hayaƙin yake fitowa daga wurinta ya yi ta tashi sama har abada abadin.” ");
INSERT INTO hausa_vpl VALUES ("RV19_4","096_19_4","REV","19","4","4","Dattawan nan ashirin da huɗu da halittu huɗun nan masu rai suka fāɗi suka yi wa Allah sujada, wannan da yake zaune a kursiyi. Suka tā da murya suka ce, “Amin, Halleluya!” ");
INSERT INTO hausa_vpl VALUES ("RV19_5","096_19_5","REV","19","5","5","Sa’an nan wata murya ta fito daga kursiyin, tana cewa, “Ku yabi Allahnmu, dukanku da kuke bayinsa, ku da kuke tsoronsa, babba da yaro!” ");
INSERT INTO hausa_vpl VALUES ("RV19_6","096_19_6","REV","19","6","6","Sai na ji wani abu mai ƙara kamar ƙasaitaccen taron mutane, kamar rurin ruwaye masu gudu da kuma kamar bugun tsawa mai ƙarfi, suna tā da murya suna cewa, “Halleluya! Gama Ubangiji Allahnmu Maɗaukaki ne yake mulki. ");
INSERT INTO hausa_vpl VALUES ("RV19_7","096_19_7","REV","19","7","7","Bari mu yi farin ciki mu kuma yi murna mu kuma ɗaukaka shi! Domin lokacin auren Ɗan Ragon ya yi, amaryarsa kuwa ta shirya kanta. ");
INSERT INTO hausa_vpl VALUES ("RV19_8","096_19_8","REV","19","8","8","Aka ba ta lallausan lilin, mai haske da tsabta ta sanya.” (Lallausan lilin yana misalta ayyukan adalci na tsarkaka.) ");
INSERT INTO hausa_vpl VALUES ("RV19_9","096_19_9","REV","19","9","9","Sai mala’ikan ya ce mini, “Rubuta, ‘Masu albarka ne waɗanda aka gayyace su zuwa bikin auren Ɗan Ragon!’ ” Sai ya ƙara da cewa, “Waɗannan su ne kalmomin Allah da gaske.” ");
INSERT INTO hausa_vpl VALUES ("RV19_10","096_19_10","REV","19","10","10","Da wannan sai na fāɗi a gabansa, don in yi masa sujada. Amma ya ce mini, “Kada ka yi haka! Ni ma abokin bauta ne da kai da kuma ’yan’uwanka waɗanda suke riƙe da shaidar Yesu. Ka yi wa Allah sujada! Domin shaidar Yesu ita ce ruhun annabci.” ");
INSERT INTO hausa_vpl VALUES ("RV19_11","096_19_11","REV","19","11","11","Sai na ga sama a buɗe can kuwa a gabana ga farin doki, sunan mahayinsa Mai Aminci da Mai Gaskiya ne. Da adalci yake shari’a yake kuma yaƙi. ");
INSERT INTO hausa_vpl VALUES ("RV19_12","096_19_12","REV","19","12","12","Idanunsa sun yi kamar harshen wuta, a kansa kuwa akwai rawani masu yawa. Yana da suna rubuce a kansa da babu wanda ya sani sai dai shi. ");
INSERT INTO hausa_vpl VALUES ("RV19_13","096_19_13","REV","19","13","13","Yana saye da rigar da aka tsoma a jini, sunansa kuwa Kalman Allah ne. ");
INSERT INTO hausa_vpl VALUES ("RV19_14","096_19_14","REV","19","14","14","Mayaƙan sama suna biye da shi, suna hawan fararen dawakai, saye da fararen tufafi masu tsabta na lallausan lilin. ");
INSERT INTO hausa_vpl VALUES ("RV19_15","096_19_15","REV","19","15","15","Daga bakinsa takobi mai kaifi ya fito. Da shi zai karkashe al’ummai. “Zai yi mulkinsu da sandan sarautar ƙarfe.” Yana tattake wurin matsin ruwan inabi na fushin Allah Maɗaukaki. ");
INSERT INTO hausa_vpl VALUES ("RV19_16","096_19_16","REV","19","16","16","A rigarsa da kuma a cinyarsa akwai wannan suna a rubuce, Sarkin sarakuna da Ubangijin iyayengiji. ");
INSERT INTO hausa_vpl VALUES ("RV19_17","096_19_17","REV","19","17","17","Na kuma ga wani mala’ika tsaye a cikin rana, wanda ya yi kira da babbar murya ga dukan tsuntsaye da suke tashi sama a tsakiyar sararin sama cewa, “Ku zo, ku taru don babban bikin nan na Allah, ");
INSERT INTO hausa_vpl VALUES ("RV19_18","096_19_18","REV","19","18","18","don ku ci naman sarakuna, jarumawa, da kuma manyan mutane, na dawakai da mahayansu, da kuma naman dukan mutane, ’yantacce da bawa, babba da yaro.” ");
INSERT INTO hausa_vpl VALUES ("RV19_19","096_19_19","REV","19","19","19","Sa’an nan na ga dabbar da sarakunan duniya da mayaƙansu sun taru don su yi yaƙi da wannan wanda yake kan farin dokin da kuma mayaƙansa. ");
INSERT INTO hausa_vpl VALUES ("RV19_20","096_19_20","REV","19","20","20","Amma aka kama dabbar tare da annabin ƙaryan nan wanda ya aikata alamu masu banmamaki a madadinta. Da waɗannan alamun ne ya ruɗe waɗanda suka sami alamar dabbar suka kuma bauta wa siffarta. Aka jefa dukansu biyu da rai cikin tafkin wuta ta da farar wuta mai ci. ");
INSERT INTO hausa_vpl VALUES ("RV19_21","096_19_21","REV","19","21","21","Sauran kuma aka kashe su da takobin da ya fito daga bakin wannan wanda yake kan dokin. Dukan tsuntsaye kuwa suka ci namansu iyakar iyawarsu. ");
INSERT INTO hausa_vpl VALUES ("RV20_1","096_20_1","REV","20","1","1","Na kuma ga wani mala’ika yana saukowa daga sama, yana da mabuɗin Abis yana kuma riƙe da ƙaton sarƙa a hannunsa. ");
INSERT INTO hausa_vpl VALUES ("RV20_2","096_20_2","REV","20","2","2","Ya kama macijin, wannan tsohon maciji, wanda yake shi ne Iblis, ko kuwa Shaiɗan, aka kuma ɗaura shi har shekara dubu. ");
INSERT INTO hausa_vpl VALUES ("RV20_3","096_20_3","REV","20","3","3","Ya jefa shi cikin Abis, ya kuma kulle ya sa hatimi a kansa, don a hana kada yă ƙara ruɗin al’ummai, sai shekarun nan dubu sun cika. Bayan wannan, dole a sake shi na ɗan lokaci. ");
INSERT INTO hausa_vpl VALUES ("RV20_4","096_20_4","REV","20","4","4","Na ga kursiyoyi inda waɗanda aka ba su ikon shari’a suke zama a kai. Sai na ga rayukan waɗanda aka yanke kawunansu saboda shaidarsu don Yesu saboda kuma maganar Allah. Ba su yi wa dabban nan ko siffarta sujada ba, ba su kuma sami alamarta a goshinsu ko a hannuwansu ba. Suka sāke rayuwa daga matattu, suka yi mulki tare da Kiristi shekaru dubu. ");
INSERT INTO hausa_vpl VALUES ("RV20_5","096_20_5","REV","20","5","5","(Sauran matattu ba su sāke rayuwa ba, sai da shekaru dubun nan suka cika.) Wannan fa shi ne tashin matattu na farko. ");
INSERT INTO hausa_vpl VALUES ("RV20_6","096_20_6","REV","20","6","6","Masu albarka da kuma tsarki ne waɗanda suke da rabo a tashin matattu na farko. Mutuwa ta biyu ba ta da iko a kansu, sai dai za su zama firistocin Allah da kuma na Kiristi za su kuma yi mulki tare da shi na shekaru dubu. ");
INSERT INTO hausa_vpl VALUES ("RV20_7","096_20_7","REV","20","7","7","Sa’ad da shekaru dubun nan suka cika, za a saki Shaiɗan daga kurkukun da yake, ");
INSERT INTO hausa_vpl VALUES ("RV20_8","096_20_8","REV","20","8","8","zai kuma fito don yă ruɗi al’ummai da suke a kursuyoyi huɗu na duniya, Gog da Magog, yă tattara su don yaƙi. Yawansu kuwa ya yi kamar yashi a bakin teku. ");
INSERT INTO hausa_vpl VALUES ("RV20_9","096_20_9","REV","20","9","9","Suka mamaye duk fāɗin duniya suka kuma kewaye sansanin mutanen Allah, birnin da yake ƙauna. Amma wuta ta fito daga sama ta cinye su. ");
INSERT INTO hausa_vpl VALUES ("RV20_10","096_20_10","REV","20","10","10","Aka jefa Iblis da ya ruɗe su cikin tafkin farar wuta, inda aka jefa dabban nan da annabin ƙaryan nan. Za a ba su azaba dare da rana har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("RV20_11","096_20_11","REV","20","11","11","Sa’an nan na ga babban farin kursiyi da kuma wannan da yake zama a kansa. Duniya da sararin sama kuwa suka ɓace daga gabansa, babu wuri kuwa dominsu. ");
INSERT INTO hausa_vpl VALUES ("RV20_12","096_20_12","REV","20","12","12","Sai na ga matattu, babba da yaro tsaye a gaban kursiyin, aka kuma buɗe littattafai. Aka buɗe wani littafi, wanda yake shi ne littafin rai. Aka yi wa matattu shari’a bisa ga abin da suka aikata yadda yake a rubuce a cikin littattafai. ");
INSERT INTO hausa_vpl VALUES ("RV20_13","096_20_13","REV","20","13","13","Teku ya ba da matattu da suke cikinsa, mutuwa da Hades kuma suka ba da matattu da suke cikinsu, aka kuma yi wa kowane mutum shari’a bisa ga abin da ya aikata. ");
INSERT INTO hausa_vpl VALUES ("RV20_14","096_20_14","REV","20","14","14","Sa’an nan aka jefar da mutuwa da kuma Hades cikin tafkin wuta. Tafkin wutar nan kuwa shi ne mutuwa ta biyu. ");
INSERT INTO hausa_vpl VALUES ("RV20_15","096_20_15","REV","20","15","15","Duk wanda ba a sami sunansa a rubuce a cikin littafin rai ba, an jefar da shi cikin tafkin wutar nan. ");
INSERT INTO hausa_vpl VALUES ("RV21_1","096_21_1","REV","21","1","1","Sa’an nan na ga sabon sama da sabuwar duniya, gama sama na farko da duniya ta farko sun shuɗe, babu kuma wani teku. ");
INSERT INTO hausa_vpl VALUES ("RV21_2","096_21_2","REV","21","2","2","Na ga Birni Mai Tsarki, sabuwar Urushalima tana saukowa daga sama, daga Allah, a shirye kamar amaryar da aka yi mata ado mai kyau saboda mijinta. ");
INSERT INTO hausa_vpl VALUES ("RV21_3","096_21_3","REV","21","3","3","Na kuma ji wata babbar murya daga kursiyin tana cewa, “Yanzu mazaunin Allah yana tare da mutane, zai kuma zauna tare da su. Za su zama mutanensa, Allah kansa kuwa zai kasance tare da su yă kuma zama Allahnsu. ");
INSERT INTO hausa_vpl VALUES ("RV21_4","096_21_4","REV","21","4","4","Zai share dukan hawaye daga idanunsu. Ba sauran mutuwa ko makoki ko kuka ko azaba, gama tsofaffin al’amura sun shuɗe.” ");
INSERT INTO hausa_vpl VALUES ("RV21_5","096_21_5","REV","21","5","5","Wannan da yake zaune a kursiyin ya ce. “Ina yin kome sabo!” Sai ya ce, “Rubuta wannan, domin waɗannan kalmomi amintattu ne gaskiya ne kuma.” ");
INSERT INTO hausa_vpl VALUES ("RV21_6","096_21_6","REV","21","6","6","Ya ce mini, “An gama. Ni ne Alfa da kuma Omega, na Farko da kuma na Ƙarshe. Duk mai jin ƙishirwa zan ba shi abin sha kyauta daga maɓulɓular ruwan rai. ");
INSERT INTO hausa_vpl VALUES ("RV21_7","096_21_7","REV","21","7","7","Duk wanda ya ci nasara zai gāji dukan wannan, zan kuma zama Allahnsa, shi kuma zai zama ɗana. ");
INSERT INTO hausa_vpl VALUES ("RV21_8","096_21_8","REV","21","8","8","Amma matsorata, da marasa bangaskiya, masu ƙazanta, masu kisankai, masu fasikanci, masu sihiri, masu bautar gumaka da dukan maƙaryata, wurinsu zai kasance a cikin tafkin wutar da yake farar wuta mai ci. Wannan fa ita ce mutuwa ta biyu.” ");
INSERT INTO hausa_vpl VALUES ("RV21_9","096_21_9","REV","21","9","9","Ɗaya daga cikin mala’ikun nan bakwai masu kwanonin nan bakwai cike da annoban nan bakwai na ƙarshe, ya zo ya ce mini “Zo, zan nuna maka amaryar, matar Ɗan Ragon.” ");
INSERT INTO hausa_vpl VALUES ("RV21_10","096_21_10","REV","21","10","10","Ya kuwa ɗauke ni cikin Ruhu zuwa wani babban dutse mai tsayi, ya kuma nuna mini Birni Mai Tsarki, Urushalima, tana saukowa daga sama, daga Allah. ");
INSERT INTO hausa_vpl VALUES ("RV21_11","096_21_11","REV","21","11","11","Ya haskaka da ɗaukakar Allah, haskensa kuwa ya yi kamar lu’ulu’u mai daraja sosai, kamar yasfa, yana ƙyalƙyali kamar madubi. ");
INSERT INTO hausa_vpl VALUES ("RV21_12","096_21_12","REV","21","12","12","Yana da babbar katanga mai tsayi, mai ƙofofi goma sha biyu, da kuma mala’iku goma sha biyu a ƙofofin. A bisa ƙofofin an rubuta sunayen kabilu goma sha biyu na Isra’ila. ");
INSERT INTO hausa_vpl VALUES ("RV21_13","096_21_13","REV","21","13","13","Akwai ƙofofi uku a gabas, uku a arewa, uku a kudu, uku kuma a yamma. ");
INSERT INTO hausa_vpl VALUES ("RV21_14","096_21_14","REV","21","14","14","An gina katangar birnin a kan tushen gini goma sha biyu, a kansu kuwa akwai sunayen manzannin sha biyu na Ɗan Ragon. ");
INSERT INTO hausa_vpl VALUES ("RV21_15","096_21_15","REV","21","15","15","Mala’ikan da ya yi magana da ni yana da sandan awo na zinariya don awon birnin, ƙofofinsa, da kuma katangarsa. ");
INSERT INTO hausa_vpl VALUES ("RV21_16","096_21_16","REV","21","16","16","Birnin murabba’i ne, tsayinsa daidai ne da fāɗinsa. Ya auna birnin da sandarsa ya kuwa sami mil 1,400 (wajen kilomita 2,200) tsawonsa, fāɗinsa da kuma tsayinsa daidai suke. ");
INSERT INTO hausa_vpl VALUES ("RV21_17","096_21_17","REV","21","17","17","Ya auna katangarsa ya kuma sami ƙaurinta kamun 144, bisa ga ma’aunin mutum, wanda mala’ikan ya yi amfani da shi. ");
INSERT INTO hausa_vpl VALUES ("RV21_18","096_21_18","REV","21","18","18","An yi katangar da yasfa, birnin kuma da zinariya zalla, yana kuma ƙyalli kamar madubi. ");
INSERT INTO hausa_vpl VALUES ("RV21_19","096_21_19","REV","21","19","19","Tushen ginin katangar birnin kuwa an yi masa adon da kowane irin dutse mai daraja. Tushe na farko an yi shi yasfa, na biyu saffaya, na uku agat, na huɗu zumurrudu, ");
INSERT INTO hausa_vpl VALUES ("RV21_20","096_21_20","REV","21","20","20","na biyar onis, na shida yakutu, na bakwai kirisolit, na takwas beril, na tara tofaz, na goma kirisofuras, na goma sha ɗaya yasin, na goma sha biyu kuma ametis. ");
INSERT INTO hausa_vpl VALUES ("RV21_21","096_21_21","REV","21","21","21","Ƙofofi goma sha biyun nan lu’ulu’ai goma sha biyu ne, kowace ƙofa an yi ta da lu’ulu’u guda. Babban titin birnin kuwa an yi shi da zinariya zalla, yana kuma ƙyalli kamar madubi. ");
INSERT INTO hausa_vpl VALUES ("RV21_22","096_21_22","REV","21","22","22","Ban ga haikali a cikin birnin ba, domin Ubangiji Allah Maɗaukaki da kuma Ɗan Ragon ne haikalin birnin. ");
INSERT INTO hausa_vpl VALUES ("RV21_23","096_21_23","REV","21","23","23","Birnin ba ya bukatar rana ko wata su haskaka shi, gama ɗaukakar Allah tana ba shi haske, Ɗan Ragon kuwa shi ne fitilar birnin. ");
INSERT INTO hausa_vpl VALUES ("RV21_24","096_21_24","REV","21","24","24","Al’ummai za su yi tafiya cikin hasken birnin, sarakunan duniya kuma za su kawo darajarsu cikin birnin. ");
INSERT INTO hausa_vpl VALUES ("RV21_25","096_21_25","REV","21","25","25","Ba za a taɓa rufe ƙofofin birnin da rana ba, gama ba za a yi dare a can ba. ");
INSERT INTO hausa_vpl VALUES ("RV21_26","096_21_26","REV","21","26","26","Za a kawo ɗaukaka da girmar al’ummai a cikin birnin. ");
INSERT INTO hausa_vpl VALUES ("RV21_27","096_21_27","REV","21","27","27","Babu wani abu marar tsarkin da zai taɓa shiga cikin birnin, babu kuma wani mai aikata abin kunya ko ruɗi da zai shiga, sai dai waɗanda aka rubuta sunayensu a cikin littafin rai na Ɗan Ragon. ");
INSERT INTO hausa_vpl VALUES ("RV22_1","096_22_1","REV","22","1","1","Sai mala’ikan ya nuna mini kogin ruwan rai, mai ƙyalli kamar madubi, yana gangarawa daga kursiyin Allah da na Ɗan Ragon, ");
INSERT INTO hausa_vpl VALUES ("RV22_2","096_22_2","REV","22","2","2","yana bin tsakiyar babban titi na birnin. A kowane gefen kogin akwai itacen rai mai ba da ’ya’ya goma sha biyu, yana ba da ’ya’yansa kowane wata. Ganyayen itacen kuwa saboda warkar da al’ummai ne. ");
INSERT INTO hausa_vpl VALUES ("RV22_3","096_22_3","REV","22","3","3","Ba za a ƙara samun la’ana ba. Kursiyin Allah da na Ɗan Ragon zai kasance a cikin birnin, bayinsa kuma za su yi masa hidima. ");
INSERT INTO hausa_vpl VALUES ("RV22_4","096_22_4","REV","22","4","4","Za su ga fuskarsa, sunansa kuma zai kasance a goshinsu. ");
INSERT INTO hausa_vpl VALUES ("RV22_5","096_22_5","REV","22","5","5","Ba za a ƙara yin dare ba. Ba za su bukaci hasken fitila ko hasken rana ba, domin Ubangiji Allah zai haskaka su. Za su kuwa yi mulki har abada abadin. ");
INSERT INTO hausa_vpl VALUES ("RV22_6","096_22_6","REV","22","6","6","Mala’ikan ya ce mini, “Waɗannan kalmomi amintattu ne gaskiya ne kuma. Ubangiji, Allahn ruhohin annabawa, ya aiki mala’ikansa, don yă nuna wa bayinsa abubuwan da za su faru nan ba da daɗewa ba.” ");
INSERT INTO hausa_vpl VALUES ("RV22_7","096_22_7","REV","22","7","7","“Ga shi! Ina zuwa da wuri! Mai albarka ne wanda yake kiyaye kalmomin annabcin da suke cikin wannan littafi.” ");
INSERT INTO hausa_vpl VALUES ("RV22_8","096_22_8","REV","22","8","8","Ni, Yohanna, na ji, na kuma ga abubuwan nan. Kuma sa’ad da na ji, na kuma gan su, sai na fāɗi a ƙasa a gaban mala’ikan da yake nuna mini su, don in yi sujada. ");
INSERT INTO hausa_vpl VALUES ("RV22_9","096_22_9","REV","22","9","9","Amma ya ce mini, “Kada ka yi haka! Ni abokin bautarku ne, kai da ’yan’uwanka annabawa, da kuma waɗanda suke kiyaye kalmomin wannan littafi. Allah za ka yi wa sujada!” ");
INSERT INTO hausa_vpl VALUES ("RV22_10","096_22_10","REV","22","10","10","Sa’an nan ya gaya mini cewa, “Kada ka rufe kalmomin annabcin littafin nan, domin lokaci ya yi kusa. ");
INSERT INTO hausa_vpl VALUES ("RV22_11","096_22_11","REV","22","11","11","Duk mai yin laifi yă ci gaba da yin laifi; duk mai aikata ƙazanta yă ci gaba da aikata ƙazanta. Duk mai aikata abin da yake daidai, yă ci gaba da aikata abin da yake daidai. Kuma duk wanda yake mai tsarki, yă ci gaba da yin abin da yake da tsarki.” ");
INSERT INTO hausa_vpl VALUES ("RV22_12","096_22_12","REV","22","12","12","“Ga shi, ina zuwa da wuri! Ladan da zan bayar yana tare da ni, kuma zan ba wa kowa gwargwadon abin da ya yi. ");
INSERT INTO hausa_vpl VALUES ("RV22_13","096_22_13","REV","22","13","13","Ni ne Alfa da kuma Omega, na Fari da kuma na Baya, Farko da kuma Ƙarshe. ");
INSERT INTO hausa_vpl VALUES ("RV22_14","096_22_14","REV","22","14","14","“Masu albarka ne waɗanda suka wanke tufafinsu, don su sami izinin ci daga itacen rai su kuma shiga birnin ta ƙofofi. ");
INSERT INTO hausa_vpl VALUES ("RV22_15","096_22_15","REV","22","15","15","Waɗanda suke waje kuwa karnuka ne, masu sihiri, masu fasikanci, masu kisankai, masu bautar gumaka, da duk wanda yake ƙaunar ƙarya yake kuma aikata ta. ");
INSERT INTO hausa_vpl VALUES ("RV22_16","096_22_16","REV","22","16","16","“Ni, Yesu, na aiko mala’ikana ya ba ka wannan shaida saboda ikkilisiyoyi. Ni ne Tushe da kuma Zuriyar Dawuda, da kuma Tauraron Asubahi mai haske.” ");
INSERT INTO hausa_vpl VALUES ("RV22_17","096_22_17","REV","22","17","17","Ruhu da kuma amarya suna cewa, “Zo!” Duk wanda ya ji kuwa, yă ce, “Zo!” Duk mai jin ƙishirwa, yă zo; duk mai bukata kuma, yă ɗibi ruwan rai kyauta. ");
INSERT INTO hausa_vpl VALUES ("RV22_18","096_22_18","REV","22","18","18","Ina yin wa duk wanda ya ji kalmomin annabcin wannan littafi gargaɗi. Duk wanda ya ƙara wani abu a kansu, Allah zai ƙara masa annoban da aka bayyana a littafin nan. ");
INSERT INTO hausa_vpl VALUES ("RV22_19","096_22_19","REV","22","19","19","Duk wanda kuma ya yi ragi a kalmomi daga littafin annabcin nan, Allah zai ɗauke rabonsa na itacen rai da kuma na birnin nan mai tsarki, waɗanda aka bayyana a littafin nan. ");
INSERT INTO hausa_vpl VALUES ("RV22_20","096_22_20","REV","22","20","20","Shi da ya shaida waɗannan abubuwa ya ce, “I, ina zuwa da wuri.” Amin. Zo, Ubangiji Yesu! ");
INSERT INTO hausa_vpl VALUES ("RV22_21","096_22_21","REV","22","21","21","Alherin Ubangiji Yesu yă kasance tare da mutanen Allah. Amin.");
